"use client";

import { useEffect, useId, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// AdhesiveSqueezeBead — a "merge two items" affordance modeled on structural
// adhesive bonding with bond-line thickness control (aerospace/automotive
// bonded-joint practice): a bead of adhesive sits between two panels, and as
// they're pressed together it spreads and excess is forced out at the seam
// as visible "squeeze-out" — a fillet along the joint. A physical spacer
// (the bond-line stop) keeps the panels from pressing fully flat, so a good
// bond shows continuous, unbroken squeeze-out; a starved bond shows a broken
// line. That's the one visual fact this component asks a viewer to read.
//
// The bead is 24 independently-perturbed control points along the seam, not
// a single stroke-width tween: on contact each point grows toward its own
// randomized target radius (a container-scaled range around the spec's 2-5px,
// widened so the settle motion stays legible at small card sizes — see
// BASE_MIN_TARGET_R/BASE_MAX_TARGET_R below) over 340ms — deliberately
// lumpy — then relaxes LINEARLY toward a 3-point moving average of its
// neighbors (two passes) over 700ms, visibly settling from uneven to a
// continuous even fillet. THAT settle motion is the one thing to follow, and
// it holds at "finished, even fillet" for 2.1s before fading and resetting.
// Panels ease-IN (accelerating close, like two rigid parts under applied
// pressure) from a 14px starting gap to a fixed 3px bond-line stop over
// 260ms; the ~3900ms cycle then runs forever, unforced, with zero input.
//
// Dragging the lower panel drives the approach distance directly off pointer
// position instead of the ambient clock — release past the 6px squeeze-out
// threshold commits to the same growth+settle+hold+reset sequence the
// ambient loop runs (drag just jumps the shared timeline to that point);
// releasing short of it springs the panel back to the 14px start and the
// ambient loop simply resumes from t0. No pointer input is required for the
// component to be alive — dragging is an accent on top of a real resting
// loop, never the only way to see it move.
//
// Colors are --foreground / --ns-muted / --border / --surface / --background
// only, read live through CSS custom properties (no JS color reads, no
// literals) — the bead is never accent-colored; its unevenness-to-evenness
// motion is luminance/geometry only, never dressed up with hue.
// ---------------------------------------------------------------------------

export interface AdhesiveSqueezeBeadProps {
  /** content rendered inside the upper (fixed) panel */
  topContent?: React.ReactNode;
  /** content rendered inside the lower (draggable) panel */
  bottomContent?: React.ReactNode;
  /** enable drag-to-attach on the lower panel. Default true. */
  draggable?: boolean;
  /** fired once the squeeze-out bead finishes settling (ambient cycle completing the hold, or a committed drag). */
  onBond?: (source: "ambient" | "drag") => void;
  /** accessible name for the bonding preview region */
  ariaLabel?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const POINTS = 24;
const START_GAP = 14; // px, panels apart at rest
const BOND_GAP = 3; // px, fixed bond-line stop (spacer thickness)
const SQUEEZE_THRESHOLD_GAP = 6; // px, gap below which the bead starts building

const APPROACH_MS = 260;
const GROWTH_MS = 340;
const SETTLE_MS = 700;
const HOLD_MS = 2100;
const RESET_MS = 500;

const T_APPROACH_END = APPROACH_MS; // 260
const T_GROWTH_END = T_APPROACH_END + GROWTH_MS; // 600
const T_SETTLE_END = T_GROWTH_END + SETTLE_MS; // 1300
const T_HOLD_END = T_SETTLE_END + HOLD_MS; // 3400
const PERIOD_MS = T_HOLD_END + RESET_MS; // 3900

// spec's real numbers for the target radius range at a ~240px minimum card
// dimension. `layout()` multiplies these by a container-derived scale factor
// (binding rule: derive geometry from the smaller dimension) so the settle
// motion — the one thing this component asks a viewer to follow — stays
// legible instead of shrinking to a sub-pixel wobble on a small card.
const BASE_MIN_TARGET_R = 4;
const BASE_MAX_TARGET_R = 12;
const SCALE_REFERENCE_DIM = 240; // px
const MIN_SCALE = 0.75;
const MAX_SCALE = 2.5;

const EDGE_PAD = 12; // px inset kept around both panels AND the bead's 24 points — the
// same value so the bead reaches all the way to each panel's end, matching
// "squeeze-out along the seam," not stopping short of it.

interface Point {
  x: number;
  r: number;
}

function easeInQuad(t: number): number {
  return t * t;
}

function easeOutQuad(t: number): number {
  return 1 - (1 - t) * (1 - t);
}

function easeInOutQuad(t: number): number {
  return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
}

function clamp01(t: number): number {
  return t < 0 ? 0 : t > 1 ? 1 : t;
}

function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

/** 3-point moving average, edges clamped (duplicate the edge value rather than wrap —
 * this is a linear seam, not a loop). Two passes, per spec, are what turns a lumpy
 * per-point growth into a visibly continuous fillet. */
function smoothOnce(values: number[]): number[] {
  const n = values.length;
  const out = new Array(n) as number[];
  for (let i = 0; i < n; i++) {
    const prev = values[i - 1] ?? values[0] ?? 0;
    const cur = values[i] ?? 0;
    const next = values[i + 1] ?? values[n - 1] ?? 0;
    out[i] = (prev + cur + next) / 3;
  }
  return out;
}

function smoothTwice(values: number[]): number[] {
  return smoothOnce(smoothOnce(values));
}

/** Catmull-Rom -> cubic Bezier through an ordered point list, clamped at both ends
 * (no wraparound — each edge of the bead terminates flat at the seam's visible extent
 * rather than closing into a loop). Returns path commands WITHOUT the leading M. */
function smoothSegment(pts: { x: number; y: number }[]): string {
  if (pts.length < 2) return "";
  let d = "";
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[i - 1] ?? pts[i];
    const p1 = pts[i];
    const p2 = pts[i + 1];
    const p3 = pts[i + 2] ?? p2;
    if (!p0 || !p1 || !p2 || !p3) continue;
    const c1x = p1.x + (p2.x - p0.x) / 6;
    const c1y = p1.y + (p2.y - p0.y) / 6;
    const c2x = p2.x - (p3.x - p1.x) / 6;
    const c2y = p2.y - (p3.y - p1.y) / 6;
    d += `C${c1x.toFixed(2)} ${c1y.toFixed(2)} ${c2x.toFixed(2)} ${c2y.toFixed(2)} ${p2.x.toFixed(2)} ${p2.y.toFixed(2)}`;
  }
  return d;
}

function buildBeadPath(points: Point[], seamY: number): string {
  if (points.length === 0) return "";
  const top = points.map((p) => ({ x: p.x, y: seamY - p.r }));
  const bottom = points.map((p) => ({ x: p.x, y: seamY + p.r })).reverse();
  const first = top[0];
  if (!first) return "";
  return `M${first.x.toFixed(2)} ${first.y.toFixed(2)}${smoothSegment(top)}L${bottom[0]?.x.toFixed(2)} ${bottom[0]?.y.toFixed(2)}${smoothSegment(bottom)}Z`;
}

export function AdhesiveSqueezeBead({
  topContent,
  bottomContent,
  draggable = true,
  onBond,
  ariaLabel = "Adhesive bond preview",
  className = "",
}: AdhesiveSqueezeBeadProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);
  const beadRef = useRef<SVGPathElement>(null);
  const topPanelRef = useRef<HTMLDivElement>(null);
  const bottomPanelRef = useRef<HTMLDivElement>(null);
  const statusId = useId();
  const [statusText, setStatusText] = useState("");
  const [ready, setReady] = useState(false);
  const onBondRef = useRef(onBond);
  onBondRef.current = onBond;

  useEffect(() => {
    const root = rootRef.current;
    const svg = svgRef.current;
    const bead = beadRef.current;
    const topPanel = topPanelRef.current;
    const bottomPanel = bottomPanelRef.current;
    if (!root || !svg || !bead || !topPanel || !bottomPanel) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let disposed = false;
    let visible = true;
    let raf = 0;
    let w = 0;
    let h = 0;
    let sized = false;

    // fixed x positions for the 24 seam points, recomputed on resize only
    let xs: number[] = [];
    let seamY = 0;
    let minTargetR = BASE_MIN_TARGET_R;
    let maxTargetR = BASE_MAX_TARGET_R;

    let cycleStart = 0;
    let growthTargets: number[] | null = null;
    let settled: number[] | null = null;
    let announcedThisCycle = false;
    let lastCommitWasDrag = false;

    let dragging = false;
    let dragStartY = 0;
    let dragStartGap = START_GAP;
    let liveGap = START_GAP;

    const layout = () => {
      const rect = root.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      if (w < 2 || h < 2) {
        sized = false;
        return;
      }
      sized = true;
      svg.setAttribute("viewBox", `0 0 ${w} ${h}`);
      seamY = h / 2;
      xs = [];
      const usable = Math.max(1, w - EDGE_PAD * 2);
      for (let i = 0; i < POINTS; i++) {
        xs.push(EDGE_PAD + (usable * i) / (POINTS - 1));
      }

      // panel height is DERIVED, not hardcoded, so the two panels' inner
      // edges are always exactly START_GAP apart at rest — the bond-line
      // stop only means something if the resting gap is the number the
      // spec says it is.
      const panelH = Math.max(1, (h - EDGE_PAD * 2 - START_GAP) / 2);
      topPanel.style.top = `${EDGE_PAD}px`;
      topPanel.style.height = `${panelH}px`;
      bottomPanel.style.bottom = `${EDGE_PAD}px`;
      bottomPanel.style.height = `${panelH}px`;

      // binding rule: derive geometry from the container's smaller
      // dimension so the settle motion reads at card scale instead of
      // shrinking to a sub-pixel wobble on a small card.
      const minDim = Math.min(w, h);
      const scale = Math.min(MAX_SCALE, Math.max(MIN_SCALE, minDim / SCALE_REFERENCE_DIM));
      minTargetR = BASE_MIN_TARGET_R * scale;
      maxTargetR = BASE_MAX_TARGET_R * scale;

      setReady(true);
    };

    // applies a gap (px between panel inner edges) and a bead point set to the DOM.
    // Every frame writes come through here — ambient clock, drag, and the
    // reduced-motion one-shot render all funnel through the same function so
    // there is exactly one place that touches panel transforms and the path.
    const apply = (gap: number, radii: number[] | null, opacity: number) => {
      const delta = (START_GAP - gap) / 2;
      topPanel.style.transform = `translateY(${delta.toFixed(2)}px)`;
      bottomPanel.style.transform = `translateY(${(-delta).toFixed(2)}px)`;
      if (radii && radii.some((r) => r > 0.01)) {
        const pts: Point[] = xs.map((x, i) => ({ x, r: radii[i] ?? 0 }));
        bead.setAttribute("d", buildBeadPath(pts, seamY));
        bead.style.opacity = String(opacity);
      } else {
        bead.setAttribute("d", "");
      }
    };

    const phaseAt = (t: number) => {
      if (t < T_APPROACH_END) return "approach" as const;
      if (t < T_GROWTH_END) return "growth" as const;
      if (t < T_SETTLE_END) return "settle" as const;
      if (t < T_HOLD_END) return "hold" as const;
      return "reset" as const;
    };

    const frameAt = (t: number) => {
      const phase = phaseAt(t);

      if (phase === "approach") {
        growthTargets = null;
        settled = null;
        announcedThisCycle = false;
        const p = clamp01(t / APPROACH_MS);
        const gap = START_GAP - (START_GAP - BOND_GAP) * easeInQuad(p);
        return { gap, radii: null as number[] | null, opacity: 1 };
      }

      if (phase === "growth") {
        if (!growthTargets) {
          growthTargets = Array.from(
            { length: POINTS },
            () => minTargetR + Math.random() * (maxTargetR - minTargetR)
          );
        }
        const p = clamp01((t - T_APPROACH_END) / GROWTH_MS);
        const eased = easeOutQuad(p);
        const radii = growthTargets.map((target) => target * eased);
        return { gap: BOND_GAP, radii, opacity: 1 };
      }

      if (phase === "settle") {
        if (!growthTargets) {
          growthTargets = Array.from(
            { length: POINTS },
            () => minTargetR + Math.random() * (maxTargetR - minTargetR)
          );
        }
        if (!settled) settled = smoothTwice(growthTargets);
        const p = clamp01((t - T_GROWTH_END) / SETTLE_MS);
        // linear, deliberately: an eased curve front-loads the visual change and
        // leaves too little residual unevenness left at the t5s resting-loop
        // check-frame (1.1s into the next cycle, 71% through this window) to
        // read as distinct from the fully-settled hold frame at t2.5s.
        const eased = p;
        const radii = growthTargets.map((target, i) => lerp(target, settled?.[i] ?? target, eased));
        return { gap: BOND_GAP, radii, opacity: 1 };
      }

      if (phase === "hold") {
        if (!announcedThisCycle) {
          announcedThisCycle = true;
          onBondRef.current?.(lastCommitWasDrag ? "drag" : "ambient");
          lastCommitWasDrag = false;
          setStatusText("Bonded — squeeze-out even along the seam");
        }
        const radii = settled ?? growthTargets ?? new Array(POINTS).fill(maxTargetR);
        return { gap: BOND_GAP, radii, opacity: 1 };
      }

      // reset: bead fades while panels separate back to the starting gap
      const p = clamp01((t - T_HOLD_END) / RESET_MS);
      const eased = easeInOutQuad(p);
      const gap = BOND_GAP + (START_GAP - BOND_GAP) * eased;
      const radii = settled ?? growthTargets;
      return { gap, radii, opacity: 1 - eased };
    };

    const loop = (now: number) => {
      raf = 0;
      if (!visible || !sized || dragging) return;
      if (cycleStart === 0) cycleStart = now;
      let t = now - cycleStart;
      if (t >= PERIOD_MS) {
        cycleStart += Math.floor(t / PERIOD_MS) * PERIOD_MS;
        t = now - cycleStart;
      }
      const { gap, radii, opacity } = frameAt(t);
      apply(gap, radii, opacity);
      raf = requestAnimationFrame(loop);
    };

    const renderReducedSettled = () => {
      const targets = Array.from(
        { length: POINTS },
        () => minTargetR + Math.random() * (maxTargetR - minTargetR)
      );
      settled = smoothTwice(targets);
      apply(BOND_GAP, settled, 1);
      setStatusText("Bonded — squeeze-out even along the seam");
    };

    const onPointerMove = (e: PointerEvent) => {
      if (!dragging) return;
      const dy = e.clientY - dragStartY;
      liveGap = Math.max(BOND_GAP, Math.min(START_GAP, dragStartGap + dy));
      // no bead while actively dragging — the squeeze-out sequence only ever
      // plays as a committed sequence on release, never tracked live.
      apply(liveGap, null, 1);
    };

    const onPointerUp = () => {
      if (!dragging) return;
      dragging = false;
      window.removeEventListener("pointermove", onPointerMove);
      window.removeEventListener("pointerup", onPointerUp);
      const committed = liveGap <= SQUEEZE_THRESHOLD_GAP;
      if (reduced) {
        if (committed) {
          renderReducedSettled();
        } else {
          apply(START_GAP, null, 1);
          setStatusText("Released before bond line — no squeeze-out");
        }
        return;
      }
      lastCommitWasDrag = true;
      if (committed) {
        // a fresh commit gets a fresh growth cycle — never replay whatever the
        // previous ambient cycle happened to leave in these refs (e.g. a drag
        // started mid-hold), and let the "hold" phase announce again.
        growthTargets = null;
        settled = null;
        announcedThisCycle = false;
        // jump the shared timeline straight to the start of growth, already at the
        // bond-line stop, so the exact same growth+settle+hold+reset sequence the
        // ambient loop runs plays out from here.
        cycleStart = performance.now() - T_APPROACH_END;
      } else {
        setStatusText("Released before bond line — no squeeze-out");
        cycleStart = performance.now();
      }
      if (!raf) raf = requestAnimationFrame(loop);
    };

    const onPointerDown = (e: PointerEvent) => {
      // reduced motion still allows the drag itself — only the ambient
      // auto-loop is disabled; this listener is only ever attached when
      // `draggable` is true (see the effect's attach/detach below).
      dragging = true;
      raf && cancelAnimationFrame(raf);
      raf = 0;
      dragStartY = e.clientY;
      // reconstruct the currently-displayed gap from the panel's own transform so a
      // drag started mid-cycle picks up exactly where the ambient loop left off.
      const style = window.getComputedStyle(topPanel);
      const matrix = new DOMMatrixReadOnly(style.transform);
      const currentDelta = matrix.m42;
      dragStartGap = Math.max(BOND_GAP, Math.min(START_GAP, START_GAP - currentDelta * 2));
      liveGap = dragStartGap;
      window.addEventListener("pointermove", onPointerMove);
      window.addEventListener("pointerup", onPointerUp);
    };

    layout();

    if (reduced) {
      renderReducedSettled();
    } else if (sized) {
      raf = requestAnimationFrame(loop);
    }

    let resizeTimer = 0;
    const ro = new ResizeObserver(() => {
      window.clearTimeout(resizeTimer);
      resizeTimer = window.setTimeout(() => {
        if (disposed) return;
        layout();
        if (reduced) {
          renderReducedSettled();
        } else if (sized && !dragging && !raf) {
          // the very first measurement (lazy-mounted preview iframe, an
          // initially-collapsed container) can land here instead of the
          // mount-time branch above — resume the ambient loop the same way
          // the IntersectionObserver's resume path does, or it never starts.
          raf = requestAnimationFrame(loop);
        }
      }, 100);
    });
    ro.observe(root);

    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && !reduced && sized && !dragging && !raf) {
        raf = requestAnimationFrame(loop);
      }
    });
    io.observe(root);

    if (draggable) {
      bottomPanel.addEventListener("pointerdown", onPointerDown);
    }

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      raf = 0;
      window.clearTimeout(resizeTimer);
      ro.disconnect();
      io.disconnect();
      window.removeEventListener("pointermove", onPointerMove);
      window.removeEventListener("pointerup", onPointerUp);
      if (draggable) bottomPanel.removeEventListener("pointerdown", onPointerDown);
    };
    // onBond is read through onBondRef (set every render above) so an inline
    // callback identity never re-runs this effect and restarts the cycle.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [draggable]);

  return (
    <div
      ref={rootRef}
      data-adhesive-squeeze-bead
      role="group"
      aria-label={ariaLabel}
      className={`relative aspect-[4/3] w-full overflow-hidden rounded-md border border-border bg-background transition-opacity duration-200 ${ready ? "opacity-100" : "opacity-0"} ${className}`}
    >
      <div
        ref={topPanelRef}
        className="absolute inset-x-3 flex items-center justify-center rounded-sm border border-foreground/15 bg-surface"
        style={{ willChange: "transform" }}
      >
        {topContent ?? (
          <span className="font-mono text-[11px] tracking-widest text-ns-muted">PANEL A</span>
        )}
      </div>
      <div
        ref={bottomPanelRef}
        className={`absolute inset-x-3 flex items-center justify-center rounded-sm border border-foreground/15 bg-surface ${draggable ? "cursor-grab touch-none active:cursor-grabbing" : ""}`}
        style={{ willChange: "transform" }}
      >
        {bottomContent ?? (
          <span className="font-mono text-[11px] tracking-widest text-ns-muted">PANEL B</span>
        )}
      </div>
      <svg
        ref={svgRef}
        aria-hidden="true"
        focusable="false"
        className="pointer-events-none absolute inset-0 h-full w-full"
      >
        <path ref={beadRef} d="" fill="var(--foreground)" stroke="none" />
      </svg>
      <p id={statusId} role="status" aria-live="polite" className="sr-only">
        {statusText}
      </p>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// AirliftSlugFlow — a background file-sync/upload activity rail: a slim
// vertical conduit, sized off the container's smaller dimension, standing in
// for a generic spinner or a looping "syncing…" label. The mechanic is a
// real airlift pump (mining dewatering, geothermal lift, aquarium airlift):
// compressed air injected at the foot of a submerged riser forms discrete gas
// slugs, and each slug's buoyant rise drags the plug of liquid immediately
// ahead of it up the pipe — classic two-phase "slug flow", delivery arriving
// in distinct pulses rather than a continuous stream.
//
// A new slug/plug pair is injected at the rail's foot every 1.8s (inside the
// real 0.5-3Hz small-riser slugging band) and rises at a constant 140px/s
// (buoyancy-driven rise is near-constant, not accelerating). The slug is a
// rounded capsule at reduced --foreground opacity (the bubble read); the
// liquid plug it drags is a solid --foreground band riding flush against the
// slug's leading edge, same speed — two coupled parts, never one blob. On
// reaching the rail's head the pair fades over 220ms and deposits into a
// small accumulator basin, whose fill increments 1/14th per arrival and
// wraps every 14 arrivals (~25s self-contained macro-cycle).
//
// Everything is driven off a virtual clock that only advances while the rail
// is on-screen (an IntersectionObserver pauses/resumes it), so a tab-away
// never produces a catch-up burst on return. Geometry is recomputed from a
// ResizeObserver reading the container's own box — no restart on resize, the
// running pairs simply reflow onto the new rail height next frame.
// ---------------------------------------------------------------------------

const INJECT_INTERVAL_MS = 1800; // slug injection period — real 0.5-3Hz small-riser band
const RISE_SPEED_PX_S = 140; // constant buoyancy-driven rise speed
const SLUG_HEIGHT_FRAC = 0.09; // slug capsule height, fraction of rail height
const PLUG_HEIGHT_FRAC = 0.14; // dragged liquid plug height, fraction of rail height
const FADE_MS = 220; // arrival fade-out, slug+plug together
const BASIN_STEPS = 14; // arrivals per full basin cycle (~25s macro-cycle)
const RAIL_WIDTH_FRAC = 0.08; // rail width = 8% of the container's smaller dimension
const RAIL_WIDTH_MIN = 5;
const RAIL_WIDTH_MAX = 22;
const BASIN_SIZE_MULT = 2.4; // basin side length = rail width * this
const BASIN_GAP = 3; // px gap between rail head and basin
const REDUCED_BASIN_FRAC = 5 / BASIN_STEPS; // frozen-frame basin level — mid-cycle, not 0 or full

interface Pair {
  slug: HTMLDivElement;
  plug: HTMLDivElement;
  injectedAtV: number; // virtual ms timestamp at injection
  fading: boolean;
  fadeStartV: number;
}

export interface AirliftSlugFlowProps {
  /** fired once per slug arrival at the basin — hook a real file row's status pulse to it */
  onSlugArrival?: () => void;
  /** extra classes merged onto the root element */
  className?: string;
}

export function AirliftSlugFlow({ onSlugArrival, className = "" }: AirliftSlugFlowProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const railRef = useRef<HTMLDivElement>(null);
  const columnRef = useRef<HTMLDivElement>(null);
  const layerRef = useRef<HTMLDivElement>(null);
  const basinRef = useRef<HTMLDivElement>(null);
  const basinFillRef = useRef<HTMLDivElement>(null);
  const onArrivalRef = useRef(onSlugArrival);
  onArrivalRef.current = onSlugArrival;

  useEffect(() => {
    const root = rootRef.current;
    const rail = railRef.current;
    const column = columnRef.current;
    const layer = layerRef.current;
    const basin = basinRef.current;
    const basinFill = basinFillRef.current;
    if (!root || !rail || !column || !layer || !basin || !basinFill) return;

    let disposed = false;
    let railWidthPx = 0;
    let railHeightPx = 0;
    let visible = true;
    let raf = 0;
    let last = 0;
    let vClock = 0;
    let injectAcc = 0;
    let arrivalCount = 0;
    let pairs: Pair[] = [];

    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");

    const layoutBasin = () => {
      const size = Math.min(RAIL_WIDTH_MAX * BASIN_SIZE_MULT, Math.max(RAIL_WIDTH_MIN * BASIN_SIZE_MULT, railWidthPx * BASIN_SIZE_MULT));
      basin.style.width = `${size}px`;
      basin.style.height = `${size}px`;
      basin.style.marginBottom = `${BASIN_GAP}px`;
    };

    const setBasinFrac = (frac: number) => {
      basinFill.style.height = `${Math.max(0, Math.min(1, frac)) * 100}%`;
    };

    const spawnPair = (injectedAtV: number) => {
      const slug = document.createElement("div");
      slug.className = "asf-slug";
      const plug = document.createElement("div");
      plug.className = "asf-plug";
      layer.appendChild(plug);
      layer.appendChild(slug);
      pairs.push({ slug, plug, injectedAtV, fading: false, fadeStartV: 0 });
    };

    const removePair = (p: Pair) => {
      p.slug.remove();
      p.plug.remove();
    };

    const arrive = () => {
      arrivalCount = (arrivalCount % BASIN_STEPS) + 1;
      setBasinFrac(arrivalCount / BASIN_STEPS);
      onArrivalRef.current?.();
    };

    const applyPairStyle = (p: Pair, elapsedV: number) => {
      const slugH = railHeightPx * SLUG_HEIGHT_FRAC;
      const plugH = railHeightPx * PLUG_HEIGHT_FRAC;
      const y = (elapsedV / 1000) * RISE_SPEED_PX_S;
      const slugTop = y + slugH;
      const pairTop = slugTop + plugH;

      if (!p.fading && pairTop >= railHeightPx) {
        p.fading = true;
        p.fadeStartV = elapsedV;
        p.slug.style.transition = `opacity ${FADE_MS}ms linear`;
        p.plug.style.transition = `opacity ${FADE_MS}ms linear`;
        p.slug.style.opacity = "0";
        p.plug.style.opacity = "0";
        arrive();
      }

      p.slug.style.height = `${slugH}px`;
      p.slug.style.bottom = `${Math.min(y, railHeightPx - slugH)}px`;
      p.plug.style.height = `${plugH}px`;
      p.plug.style.bottom = `${Math.min(slugTop, railHeightPx - 0)}px`;
    };

    const layoutFrozenFrame = () => {
      const slugH = railHeightPx * SLUG_HEIGHT_FRAC;
      const plugH = railHeightPx * PLUG_HEIGHT_FRAC;
      const pairH = slugH + plugH;
      const bottom = railHeightPx * 0.5 - pairH / 2;
      layer.innerHTML = "";
      const slug = document.createElement("div");
      slug.className = "asf-slug";
      slug.style.height = `${slugH}px`;
      slug.style.bottom = `${bottom}px`;
      const plug = document.createElement("div");
      plug.className = "asf-plug";
      plug.style.height = `${plugH}px`;
      plug.style.bottom = `${bottom + slugH}px`;
      layer.appendChild(plug);
      layer.appendChild(slug);
      setBasinFrac(REDUCED_BASIN_FRAC);
    };

    const measure = () => {
      const rect = root.getBoundingClientRect();
      const minDim = Math.min(rect.width, rect.height);
      railWidthPx = Math.max(RAIL_WIDTH_MIN, Math.min(RAIL_WIDTH_MAX, minDim * RAIL_WIDTH_FRAC));
      column.style.width = `${railWidthPx}px`;
      rail.style.width = `${railWidthPx}px`;
      layoutBasin();
      const basinRect = basin.getBoundingClientRect();
      railHeightPx = Math.max(0, rect.height - basinRect.height - BASIN_GAP);
      rail.style.height = `${railHeightPx}px`;
      if (mq.matches) layoutFrozenFrame();
    };

    const loop = (now: number) => {
      raf = 0;
      if (disposed) return;
      if (!visible || railHeightPx <= 0) {
        raf = requestAnimationFrame(loop);
        return;
      }
      if (last === 0) last = now;
      const dt = Math.min(100, now - last);
      last = now;
      vClock += dt;

      injectAcc += dt;
      while (injectAcc >= INJECT_INTERVAL_MS) {
        injectAcc -= INJECT_INTERVAL_MS;
        spawnPair(vClock);
      }

      pairs = pairs.filter((p) => {
        const elapsedV = vClock - p.injectedAtV;
        applyPairStyle(p, elapsedV);
        if (p.fading && vClock - p.fadeStartV >= FADE_MS) {
          removePair(p);
          return false;
        }
        return true;
      });

      raf = requestAnimationFrame(loop);
    };

    const start = () => {
      measure();
      if (mq.matches) return; // reduced motion: one static frame, no loop
      last = 0;
      if (!raf) raf = requestAnimationFrame(loop);
    };

    const onReducedChange = () => {
      cancelAnimationFrame(raf);
      raf = 0;
      layer.innerHTML = "";
      pairs = [];
      injectAcc = 0;
      vClock = 0;
      last = 0;
      arrivalCount = 0;
      setBasinFrac(0);
      start();
    };
    mq.addEventListener("change", onReducedChange);

    let resizeTimer = 0;
    const ro = new ResizeObserver(() => {
      window.clearTimeout(resizeTimer);
      resizeTimer = window.setTimeout(() => {
        if (disposed) return;
        measure();
      }, 100);
    });
    ro.observe(root);

    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && !mq.matches && !raf) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    });
    io.observe(root);

    document.fonts.ready.then(() => {
      if (!disposed) measure();
    });

    start();

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      raf = 0;
      window.clearTimeout(resizeTimer);
      mq.removeEventListener("change", onReducedChange);
      ro.disconnect();
      io.disconnect();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div ref={rootRef} className={`relative flex h-full w-full flex-col items-center justify-end ${className}`}>
      <style>{CSS}</style>
      <div ref={basinRef} className="asf-basin">
        <div ref={basinFillRef} className="asf-basin-fill" />
      </div>
      <div ref={columnRef} className="relative">
        <div ref={railRef} className="asf-static-column relative overflow-visible">
          <div ref={layerRef} className="absolute inset-x-0 bottom-0" />
        </div>
      </div>
    </div>
  );
}

const CSS = `
.asf-static-column {
  background: var(--ns-muted);
  opacity: 0.3;
  border-radius: 999px;
}
.dark .asf-static-column {
  opacity: 0.16;
}
.asf-slug {
  position: absolute;
  left: 0;
  right: 0;
  border-radius: 999px;
  background: var(--foreground);
  opacity: 0.4;
}
.asf-plug {
  position: absolute;
  left: 0;
  right: 0;
  border-radius: 2px;
  background: var(--foreground);
  opacity: 1;
}
.asf-basin {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 3px;
  background: var(--background);
}
.asf-basin-fill {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 0%;
  background: var(--foreground);
  transition: height 220ms linear;
}
`;

"use client";

import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// AnnouncementBarRelay — a queued announcement bar that hands off honestly.
//
// The problem with every dismissible banner queue: the DOM swaps the message
// and the page below jumps by whatever the height difference happens to be.
// Here a hidden mirror row renders the NEXT message at the bar's exact content
// width, so its height h1 is known BEFORE the handoff starts. On dismiss the
// live height h0 is written to the bar as an explicit px height, and one rAF
// later three things start on the same clock:
//
//   (a) the outgoing message shears up and out   translateY(-100%) skewX(-3deg)
//   (b) the incoming message arrives from below  translateY(100%)  skewX(3deg)
//   (c) the BAR eases height h0 -> h1
//
// The 3deg shear is what makes the two messages read as one carriage
// travelling past a window rather than a crossfade. The height easing is what
// keeps the page below moving continuously instead of snapping at the swap.
// On settle the explicit height is cleared back to auto.
//
// The queue readout collapses in the same beat: the leaving pip animates its
// width (and margin) from 6px to 0, so the row of dots visibly gets shorter.
//
// Last item: same outgoing shear, the bar eases h0 -> 0, and the region
// unmounts on transitionend — guarded by a fallback timer, because a
// transitionend that never fires (tab hidden mid-flight) must not strand a
// zero-height region in the document.
//
// Tokens only: --border, --foreground, --ns-muted, --surface, --ns-accent. Accent is
// restricted to the action link and the focus rings; tone:"accent" shifts only
// the 2px leading rule, never the bar's background.
// ---------------------------------------------------------------------------

const SWAP_MS = 240; // message travel
const SWAP_DELAY_MS = 60; // lead-in on the incoming message
const HEIGHT_MS = 300; // bar height ease — outlasts the swap on purpose
const PIP_MS = 200; // queue pip collapse
const EASE = "cubic-bezier(0.4, 0, 0.2, 1)";
const SETTLE_FALLBACK_MS = 400; // transitionend guard

export interface AnnouncementItem {
  /** Stable id — also the localStorage suffix, so it must survive deploys. */
  id: string;
  /** The notice itself. One sentence; the bar is a single line at rest. */
  message: string;
  /** Optional inline link rendered after the message. */
  action?: { label: string; href: string };
  /** Shifts only the 2px leading rule. @default "muted" */
  tone?: "muted" | "accent";
}

export interface AnnouncementBarRelayProps {
  /** The queue, front to back. Dismissed ids are skipped. */
  items: AnnouncementItem[];
  /** Namespaced localStorage prefix; each dismissed id is written as
   * `${storageKeyPrefix}${id}` = "1". @default "ns-announcement-bar-relay:" */
  storageKeyPrefix?: string;
  /** Clear this queue's stored dismissals on mount — for demos and previews,
   * so a replaying page can't permanently empty itself. @default false */
  resetOnMount?: boolean;
  /** Fires once the last item has been dismissed and the bar has collapsed. */
  onExhausted?: () => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

function MessageBody({ item, linkTabIndex }: { item: AnnouncementItem; linkTabIndex?: number }) {
  return (
    <span className="block text-sm leading-6 text-foreground">
      {item.message}
      {item.action && (
        <>
          {" "}
          <a
            href={item.action.href}
            tabIndex={linkTabIndex}
            className="rounded-sm text-ns-accent underline decoration-ns-accent/40 underline-offset-[3px] outline-none transition-colors hover:decoration-ns-accent focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-surface"
          >
            {item.action.label}
          </a>
        </>
      )}
    </span>
  );
}

export function AnnouncementBarRelay({
  items,
  storageKeyPrefix = "ns-announcement-bar-relay:",
  resetOnMount = false,
  onExhausted,
  className = "",
}: AnnouncementBarRelayProps) {
  // Storage is read in an effect, never during render, so the server markup and
  // the first client paint agree: item 0 renders optimistically and is swapped
  // after hydration if it turns out to be already dismissed.
  const [dismissed, setDismissed] = useState<string[]>([]);
  const [outgoing, setOutgoing] = useState<AnnouncementItem | null>(null);
  const [entering, setEntering] = useState(false); // incoming still at its start pose
  const [leaving, setLeaving] = useState(false); // outgoing shearing out
  const [barHeight, setBarHeight] = useState<number | null>(null);
  const [animating, setAnimating] = useState(false);
  const [gone, setGone] = useState(false);

  const barRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const mirrorRef = useRef<HTMLDivElement>(null);
  const busyRef = useRef(false);
  const pendingRef = useRef<{ h1: number; last: boolean } | null>(null);
  const finishRef = useRef<(() => void) | null>(null);
  const timerRef = useRef<number | undefined>(undefined);
  const rafRef = useRef(0);
  const onExhaustedRef = useRef(onExhausted);
  onExhaustedRef.current = onExhausted;

  const labelId = useId();

  useEffect(() => {
    if (typeof window === "undefined") return;
    let store: Storage | null = null;
    try {
      store = window.localStorage;
    } catch {
      return; // storage denied — the bar simply never persists
    }
    if (!store) return;
    if (resetOnMount) {
      for (const item of items) {
        try {
          store.removeItem(`${storageKeyPrefix}${item.id}`);
        } catch {
          /* quota / private mode — nothing to do */
        }
      }
      return;
    }
    const seen: string[] = [];
    for (const item of items) {
      try {
        if (store.getItem(`${storageKeyPrefix}${item.id}`) === "1") seen.push(item.id);
      } catch {
        /* ignore */
      }
    }
    if (seen.length) setDismissed(seen);
    // Intentionally mount-only: the queue is fixed for the bar's lifetime.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(
    () => () => {
      window.clearTimeout(timerRef.current);
      cancelAnimationFrame(rafRef.current);
    },
    []
  );

  const remaining = items.filter((item) => !dismissed.includes(item.id));
  const current = remaining[0] ?? null;
  const next = remaining[1] ?? null;
  const position = Math.min(items.length, items.length - remaining.length + 1);

  const handleDismiss = useCallback(() => {
    if (busyRef.current || !current) return;
    const bar = barRef.current;
    const content = contentRef.current;
    if (!bar || !content) return;
    busyRef.current = true;

    try {
      window.localStorage.setItem(`${storageKeyPrefix}${current.id}`, "1");
    } catch {
      /* storage denied — dismissal is still honoured for this session */
    }

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const isLast = next == null;

    if (reduced) {
      // One paint: no shear, no height easing, no pip collapse.
      setDismissed((d) => [...d, current.id]);
      if (isLast) {
        setGone(true);
        onExhaustedRef.current?.();
      }
      busyRef.current = false;
      return;
    }

    // h0 is the live border-box height; h1 comes from the mirror, which is
    // already rendering `next` at the bar's exact content width. `chrome` is
    // whatever the bar adds around its content row (the hairline rule), so the
    // two measurements are in the same box model.
    const h0 = bar.getBoundingClientRect().height;
    const chrome = bar.offsetHeight - content.offsetHeight;
    const h1 = isLast ? 0 : (mirrorRef.current?.offsetHeight ?? content.offsetHeight) + chrome;

    pendingRef.current = { h1, last: isLast };
    setBarHeight(h0);
    setAnimating(true);
    setOutgoing(current);
    setEntering(true);
    setDismissed((d) => [...d, current.id]);
  }, [current, next, storageKeyPrefix]);

  // Start every clock in the same rAF, one paint after the start poses have
  // actually rendered — otherwise the browser coalesces start and end and
  // nothing transitions.
  useLayoutEffect(() => {
    const pending = pendingRef.current;
    if (!pending || !outgoing) return;
    pendingRef.current = null;

    rafRef.current = requestAnimationFrame(() => {
      setBarHeight(pending.h1);
      setEntering(false);
      setLeaving(true);
    });

    const finish = () => {
      if (!finishRef.current) return;
      finishRef.current = null;
      window.clearTimeout(timerRef.current);
      setAnimating(false);
      setBarHeight(null);
      setOutgoing(null);
      setLeaving(false);
      busyRef.current = false;
      if (pending.last) {
        setGone(true);
        onExhaustedRef.current?.();
      }
    };
    finishRef.current = finish;
    timerRef.current = window.setTimeout(finish, HEIGHT_MS + SETTLE_FALLBACK_MS);
    return () => cancelAnimationFrame(rafRef.current);
  }, [outgoing]);

  const onBarTransitionEnd = (event: React.TransitionEvent<HTMLDivElement>) => {
    if (event.propertyName !== "height" || event.target !== barRef.current) return;
    finishRef.current?.();
  };

  if (gone || (!current && !outgoing)) return null;

  const shown = current ?? outgoing;
  if (!shown) return null;

  const toneAccent = (current ?? outgoing)?.tone === "accent";

  return (
    <div
      ref={barRef}
      role="region"
      aria-labelledby={labelId}
      data-announcement-bar=""
      onTransitionEnd={onBarTransitionEnd}
      style={{
        height: barHeight == null ? undefined : `${barHeight}px`,
        transition: animating ? `height ${HEIGHT_MS}ms ${EASE}` : undefined,
      }}
      className={`ns-abr relative w-full overflow-hidden border-b border-border bg-surface ${className}`}
    >
      <span id={labelId} className="sr-only">
        Announcements
      </span>
      <span
        aria-hidden="true"
        className="pointer-events-none absolute inset-y-0 left-0 w-[2px]"
        style={{ background: toneAccent ? "var(--ns-accent)" : "var(--border)" }}
      />

      <div ref={contentRef} className="flex items-center gap-4 px-4 py-2.5 pl-5 sm:px-6 sm:pl-7">
        <div className="relative min-w-0 flex-1" aria-live="polite">
          {outgoing && (
            <div aria-hidden="true" className="ns-abr-msg absolute inset-x-0 top-0" data-leave={leaving ? "" : undefined}>
              <MessageBody item={outgoing} linkTabIndex={-1} />
            </div>
          )}
          {current && (
            <div key={current.id} className="ns-abr-msg" data-enter={entering ? "" : undefined}>
              <MessageBody item={current} />
            </div>
          )}
          {/* Inside the live region on purpose: the pips and the counter are
              aria-hidden, so this is the only way the new position is spoken
              at all — outside it, it would change silently. */}
          <span className="sr-only">
            Announcement {position} of {items.length}
          </span>
        </div>

        <div className="flex shrink-0 items-center gap-3">
          <div className="flex items-center" aria-hidden="true">
            <span className="flex items-center">
              {outgoing && <span className="ns-abr-pip ns-abr-pip-on" data-collapse={leaving ? "" : undefined} />}
              {remaining.map((item, i) => (
                <span key={item.id} className={`ns-abr-pip ${i === 0 ? "ns-abr-pip-on" : ""}`} />
              ))}
            </span>
            <span className="ml-1 font-mono text-[11px] tabular-nums text-ns-muted">
              {position}/{items.length}
            </span>
          </div>

          <button
            type="button"
            data-announcement-dismiss=""
            onClick={handleDismiss}
            aria-label={`Dismiss: ${shown.message}`}
            className="flex h-7 w-7 shrink-0 items-center justify-center rounded-sm text-ns-muted outline-none transition-colors hover:bg-foreground/[0.07] hover:text-foreground focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-inset"
          >
            <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.4" className="h-3.5 w-3.5" aria-hidden="true">
              <path d="M4 4l8 8M12 4l-8 8" strokeLinecap="round" />
            </svg>
          </button>
        </div>
      </div>

      {/* Height oracle: the next message rendered at the bar's exact content
          width, so h1 is a measured fact before the handoff starts. */}
      <div
        ref={mirrorRef}
        aria-hidden="true"
        className="pointer-events-none absolute inset-x-0 top-0 flex items-center gap-4 px-4 py-2.5 pl-5 sm:px-6 sm:pl-7"
        style={{ visibility: "hidden" }}
      >
        <div className="min-w-0 flex-1">{next && <MessageBody item={next} linkTabIndex={-1} />}</div>
        {/* The right-hand block is reproduced exactly — pips, counter, button box —
            at the count it will have AFTER the dismissal, so the mirror's message
            column is the same width as the real one and a wrap is measured, not
            missed. */}
        <div className="flex shrink-0 items-center gap-3">
          <div className="flex items-center">
            <span className="flex items-center">
              {remaining.slice(1).map((item) => (
                <span key={item.id} className="ns-abr-pip" />
              ))}
            </span>
            <span className="ml-1 font-mono text-[11px] tabular-nums text-ns-muted">
              {Math.min(items.length, position + 1)}/{items.length}
            </span>
          </div>
          <span className="h-7 w-7" />
        </div>
      </div>

      <style>{`
        .ns-abr-msg {
          transform: translateY(0) skewX(0deg);
          opacity: 1;
          transition: transform ${SWAP_MS}ms ${EASE} ${SWAP_DELAY_MS}ms, opacity ${SWAP_MS}ms ${EASE} ${SWAP_DELAY_MS}ms;
          will-change: transform;
        }
        .ns-abr-msg[data-enter] {
          transform: translateY(100%) skewX(3deg);
          opacity: 0;
          transition: none;
        }
        .ns-abr-msg[data-leave] {
          transform: translateY(-100%) skewX(-3deg);
          opacity: 0;
          transition: transform ${SWAP_MS}ms ${EASE}, opacity ${SWAP_MS}ms ${EASE};
        }
        .ns-abr-pip {
          box-sizing: border-box;
          display: inline-block;
          width: 6px;
          height: 6px;
          margin-right: 6px;
          border-radius: 9999px;
          border: 1px solid var(--border);
          transition: width ${PIP_MS}ms ${EASE}, margin-right ${PIP_MS}ms ${EASE};
        }
        .ns-abr-pip-on {
          background: var(--foreground);
          border-color: var(--foreground);
        }
        .ns-abr-pip[data-collapse] {
          width: 0;
          margin-right: 0;
          border-width: 0;
        }
        @media (prefers-reduced-motion: reduce) {
          .ns-abr-msg,
          .ns-abr-msg[data-leave],
          .ns-abr-pip {
            transition: none;
          }
        }
      `}</style>
    </div>
  );
}

"use client";

import { useEffect, useId, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// AssayGate — a human-in-the-loop approval row for an agent's proposed tool
// call. Every argument renders as a real, labelled, inline-editable field;
// touching one keeps the original value on the record and shows a Geist Mono
// old→new diff (strikethrough) beneath it rather than silently swapping the
// value. Approve and Deny are told apart by fill and weight, not colour —
// Approve is the solid accent action, Deny a plain outlined one, both with
// distinct glyphs. Deciding collapses the row into a one-line receipt
// (outcome · actor · time) that cannot be reopened for editing — the
// collapse is driven by grid-template-rows so it plays as a real motion, and
// once `decision` is set nothing in this component ever clears it. The full
// payload survives as-decided behind a native <details> disclosure on the
// receipt line.
// ---------------------------------------------------------------------------

export type AssayField = {
  key: string;
  /** short label shown above the field, e.g. "command" */
  label: string;
  value: string;
};

export type AssayDecision = {
  outcome: "approved" | "denied";
  /** who decided — the human at the console, not the requesting agent */
  actor: string;
  timestamp: number;
};

export interface AssayGateProps {
  /** the tool being called, e.g. "execute_shell" */
  toolName: string;
  /** the agent/identity that proposed the call */
  requestedBy?: string;
  /** the call's arguments, one editable field each */
  fields: AssayField[];
  /** seed one or more fields as already edited, keyed by field.key — the
   * diff renders immediately instead of waiting for the human to type */
  initialValues?: Record<string, string>;
  /** recorded on the receipt as the decider — default "you" */
  approverName?: string;
  /** called once the human decides, with the final field values */
  onDecision?: (decision: AssayDecision, fields: AssayField[]) => void;
  /** pre-seed as already decided (e.g. rendering decision history) */
  initialDecision?: AssayDecision;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

function timeLabel(ts: number) {
  return new Date(ts).toLocaleTimeString(undefined, {
    hour: "numeric",
    minute: "2-digit",
    second: "2-digit",
  });
}

// A wall-clock stamp is the one thing in this component that can legitimately
// differ between the server render and the client one: `toLocaleTimeString`
// resolves against the *renderer's* locale and time zone, and a server in UTC
// formatting the same epoch as a browser in Europe/Athens produces different
// text. Left alone that is a hydration text mismatch (React error #418) on
// every receipt. The client's formatting is the correct one to show, so the
// mismatch is expected rather than a bug — which is exactly what
// `suppressHydrationWarning` is for.
function TimeStamp({ ts }: { ts: number }) {
  return <span suppressHydrationWarning>{timeLabel(ts)}</span>;
}

function CheckIcon() {
  return (
    <svg viewBox="0 0 16 16" className="h-3.5 w-3.5" fill="none" aria-hidden>
      <path
        d="M3.5 8.5l3 3 6-7"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function DenyIcon() {
  return (
    <svg viewBox="0 0 16 16" className="h-3.5 w-3.5" fill="none" aria-hidden>
      <path
        d="M4 4l8 8M12 4l-8 8"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
      />
    </svg>
  );
}

function ArrowIcon() {
  return (
    <svg viewBox="0 0 16 16" className="h-3 w-3 shrink-0" fill="none" aria-hidden>
      <path
        d="M2.5 8h10M8.5 4.5L12 8l-3.5 3.5"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function ChevronIcon() {
  return (
    <svg
      viewBox="0 0 16 16"
      className="h-3.5 w-3.5 shrink-0 transition-transform duration-200 group-open:rotate-180"
      fill="none"
      aria-hidden
    >
      <path
        d="M4 6l4 4 4-4"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

export function AssayGate({
  toolName,
  requestedBy = "agent",
  fields,
  initialValues,
  approverName = "you",
  onDecision,
  initialDecision,
  className = "",
}: AssayGateProps) {
  const uid = useId();
  const originals = useRef(
    Object.fromEntries(fields.map((f) => [f.key, f.value]))
  ).current;
  const [values, setValues] = useState<Record<string, string>>(() => ({
    ...originals,
    ...initialValues,
  }));
  const [decision, setDecision] = useState<AssayDecision | null>(
    initialDecision ?? null
  );
  const decidedRef = useRef(!!initialDecision);
  const summaryRef = useRef<HTMLElement>(null);
  const wasPending = useRef(!initialDecision);

  // move focus onto the receipt once a decision lands, so the outcome is
  // where focus is and gets announced rather than stranded on a collapsing
  // button; only for decisions made *in* this session, not the seeded ones.
  useEffect(() => {
    if (decision && wasPending.current) {
      wasPending.current = false;
      summaryRef.current?.focus();
    }
  }, [decision]);

  function decide(outcome: "approved" | "denied") {
    if (decidedRef.current) return; // irreversible: first decision wins, no path back
    decidedRef.current = true;
    const next: AssayDecision = {
      outcome,
      actor: approverName,
      timestamp: Date.now(),
    };
    const finalFields = fields.map((f) => ({
      ...f,
      value: values[f.key] ?? f.value,
    }));
    setDecision(next);
    onDecision?.(next, finalFields);
  }

  const approved = decision?.outcome === "approved";
  const receiptLabel = decision
    ? decision.outcome === "approved"
      ? "Approved"
      : "Denied"
    : "";

  return (
    <div className={className}>
      <style>{`
@keyframes ns-assay-in{from{opacity:0;transform:translateY(-4px)}to{opacity:1;transform:translateY(0)}}
.ns-assay-in{animation:ns-assay-in 320ms cubic-bezier(0.16,1,0.3,1) both}
.ns-assay-collapse{display:grid;transition:grid-template-rows 420ms cubic-bezier(0.16,1,0.3,1)}
@media (prefers-reduced-motion: reduce){
  .ns-assay-in{animation:none}
  .ns-assay-collapse{transition:none}
}
`}</style>

      {/* pending body — collapses to zero height, irreversibly, on decision */}
      <div
        className="ns-assay-collapse"
        style={{ gridTemplateRows: decision ? "0fr" : "1fr" }}
        // removed from hit-testing and the a11y tree the moment a decision
        // lands, so a stray Tab can never land on a control now sitting at
        // zero height inside the collapsing row
        inert={decision ? true : undefined}
      >
        <div className="overflow-hidden">
          <div className="rounded-md border border-border bg-surface p-4">
            <div className="mb-3 flex items-center justify-between gap-3">
              <div className="min-w-0">
                <p className="truncate font-mono text-sm font-medium text-foreground">
                  {toolName}
                </p>
                <p className="truncate font-mono text-[11px] text-ns-muted">
                  requested by {requestedBy}
                </p>
              </div>
              <span className="shrink-0 rounded-full border border-border px-2 py-0.5 font-mono text-[10px] uppercase tracking-wide text-ns-muted">
                pending
              </span>
            </div>

            <div className="space-y-3">
              {fields.map((f) => {
                const id = `${uid}-${f.key}`;
                const current = values[f.key] ?? f.value;
                const dirty = current !== originals[f.key];
                return (
                  <div key={f.key}>
                    <label
                      htmlFor={id}
                      className="block font-mono text-[11px] uppercase tracking-wide text-ns-muted"
                    >
                      {f.label}
                    </label>
                    <input
                      id={id}
                      type="text"
                      value={current}
                      onChange={(e) =>
                        setValues((v) => ({ ...v, [f.key]: e.target.value }))
                      }
                      className="mt-1 w-full rounded-sm border border-border bg-background px-2.5 py-1.5 font-mono text-sm text-foreground outline-none transition-colors focus-visible:border-ns-accent"
                    />
                    {dirty ? (
                      <div className="mt-1.5 flex flex-wrap items-center gap-1.5 font-mono text-xs">
                        <span className="sr-only">changed from</span>
                        <s className="break-all text-ns-muted decoration-1">
                          {originals[f.key]}
                        </s>
                        <span className="sr-only">to</span>
                        <span className="text-ns-muted">
                          <ArrowIcon />
                        </span>
                        <span className="break-all text-foreground">
                          {current}
                        </span>
                      </div>
                    ) : null}
                  </div>
                );
              })}
            </div>

            <div className="mt-4 flex items-center justify-end gap-2">
              <button
                type="button"
                data-assay-deny
                onClick={() => decide("denied")}
                className="inline-flex items-center gap-1.5 rounded-sm border border-border px-3 py-1.5 text-sm text-foreground transition-colors hover:bg-background focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
              >
                <DenyIcon />
                Deny
              </button>
              <button
                type="button"
                data-assay-approve
                onClick={() => decide("approved")}
                className="inline-flex items-center gap-1.5 rounded-sm bg-ns-accent px-3 py-1.5 text-sm font-medium text-white transition-colors hover:bg-ns-accent-hover focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
              >
                <CheckIcon />
                Approve
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* receipt — mounts once, never unmounts, never edited again */}
      {decision ? (
        <div className="ns-assay-in">
          <details className="group rounded-md border border-border">
            <summary
              ref={summaryRef}
              tabIndex={0}
              data-assay-receipt
              className="flex cursor-pointer list-none items-center gap-2 px-3 py-2 font-mono text-xs text-foreground [&::-webkit-details-marker]:hidden"
            >
              <span
                className={
                  "flex h-4 w-4 shrink-0 items-center justify-center rounded-full border " +
                  (approved
                    ? "border-foreground text-foreground"
                    : "border-border text-ns-muted")
                }
                aria-hidden
              >
                {approved ? <CheckIcon /> : <DenyIcon />}
              </span>
              <span className={"shrink-0 " + (approved ? "font-medium" : "")}>
                {receiptLabel}
              </span>
              <span className="shrink-0 text-ns-muted">·</span>
              {/* the one variable-length field on this row — it truncates so a
                  long tool name can't shove the payload affordance into the
                  timestamp (ml-auto yields nothing once the row is full) */}
              <span className="min-w-0 truncate text-ns-muted">{toolName}</span>
              <span className="shrink-0 text-ns-muted">·</span>
              {/* the actor is variable-length too (a console handle can be an
                  email or a long service identity): like the tool name it
                  gives rather than shoving the timestamp/payload off the row,
                  and the full string stays available on hover and in the
                  expanded payload's own header row below */}
              <span
                className="min-w-0 truncate text-ns-muted"
                title={decision.actor}
              >
                {decision.actor}
              </span>
              <span className="shrink-0 text-ns-muted">·</span>
              {/* shrink-0 + nowrap: without it flex squeezed the stamp until
                  "4:33:04 PM" wrapped onto a second line and got clipped by the
                  row. The tool name above is the only field allowed to give. */}
              <span className="shrink-0 whitespace-nowrap text-ns-muted">
                <TimeStamp ts={decision.timestamp} />
              </span>
              <span className="ml-auto flex shrink-0 items-center gap-1 pl-3 text-ns-muted">
                payload
                <ChevronIcon />
              </span>
            </summary>
            <div
              data-assay-payload
              className="space-y-1.5 border-t border-border px-3 py-2.5"
            >
              {/* the two identifiers that truncate on the collapsed receipt
                  line (the tool and the decider) are repeated here in full, so
                  ellipsizing them above never loses information */}
              <div className="flex gap-2 font-mono text-xs">
                <span className="shrink-0 text-ns-muted">tool</span>
                <span className="break-all text-foreground">{toolName}</span>
              </div>
              <div className="flex gap-2 font-mono text-xs">
                <span className="shrink-0 text-ns-muted">decided by</span>
                <span className="break-all text-foreground">{decision.actor}</span>
              </div>
              {fields.map((f) => (
                <div key={f.key} className="flex gap-2 font-mono text-xs">
                  <span className="shrink-0 text-ns-muted">{f.label}</span>
                  <span className="break-all text-foreground">
                    {values[f.key] ?? f.value}
                  </span>
                </div>
              ))}
            </div>
          </details>
          <p role="status" aria-live="polite" className="sr-only">
            {receiptLabel} by {decision.actor} at <TimeStamp ts={decision.timestamp} />
          </p>
        </div>
      ) : null}
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
  type PointerEvent as ReactPointerEvent,
} from "react";

// ---------------------------------------------------------------------------
// PawlTick — autosave status rendered as a mechanical ratchet, not a spinner
// or a text swap. A 10-tooth gear (9 teeth in --ns-muted, one index tooth in
// --foreground so a one-tooth-width rotation is actually visible against the
// gear's own 10-fold symmetry) sits under a fixed pawl triangle. Every
// SUCCESSFUL save advances the gear exactly one tooth-width and folds into a
// silent running tally; the position is cosmetic (it wraps every 10 saves),
// the count and timestamp are the real record and live in the tooltip text.
//
// Motion is three distinct, non-looping events, all direct-DOM CSS-transform
// writes on two SVG refs (no React state on the hot path):
//   - save-start ("saving"): a small anticipation backswing, winding the
//     wheel back against the pawl before the outcome is known.
//   - ack ("saved"): a 200ms ease-out-expo spring settle forward past the
//     wind-up to the next tooth. Count++, timestamp stamped, wind-up cleared.
//   - failure ("error"): the pawl slips — the wheel kicks back half a tooth
//     from its last good seat (not from wherever the wind-up left it, so
//     repeated failures hold the same broken pose rather than unraveling
//     further) and the pawl itself lifts off and thickens to 2px
//     --foreground. That pose holds — no loop — until the next successful
//     save resolves it.
//
// Accessibility: a dedicated sr-only span (not the whole wrapper) is the
// status live region — role=status/aria-live=polite/aria-atomic=true on
// just that span, so re-reading it atomically never picks up the button's
// label or an open tooltip's duplicated text, and hovering the tooltip
// (marked aria-live=off) can never itself trigger a spurious announcement.
// "Saving"/"Saved" chatter is throttled to at most one shared announcement
// per 30s so a bursty autosave doesn't spam a screen reader; "Save failed"
// always announces and resets that throttle window so the next resolution
// is guaranteed to announce too. The gear is aria-hidden; the only focusable
// element is the button that doubles as the tooltip trigger (hover or focus
// reveals a Geist Mono panel that duplicates every fact as text — status,
// session count, time since the last successful save), and Escape closes
// it. The failed state additionally renders the plain visible words
// "Not saved" beside the wheel, so the state is never carried by the
// graphic alone. prefers-reduced-motion drops the wind-up anticipation
// entirely (pure flourish, no state of its own), but ack and failure keep a
// short 140ms linear settle rather than jumping straight to their resolved
// angle — the wheel's position is the only passive signal a save just
// landed, so it still has to visibly move.
// ---------------------------------------------------------------------------

export type PawlTickStatus = "idle" | "saving" | "saved" | "error";

export interface PawlTickProps {
  /**
   * Current autosave status. Transitions drive everything: idle/saved/error
   * -> "saving" plays the anticipation wind-up; "saving" -> "saved" advances
   * one tooth with a spring settle and folds into the session tally;
   * any -> "error" plays the pawl-slip kick-back and holds until the next
   * "saved".
   */
  status: PawlTickStatus;
  /** Gear glyph size in px. Default 20. */
  size?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const TOOTH_COUNT = 10;
const TOOTH_DEG = 360 / TOOTH_COUNT;
const ANTICIPATE_DEG = 8;
const FAIL_KICK_DEG = TOOTH_DEG / 2;

const EASE_OUT_EXPO = "cubic-bezier(0.16, 1, 0.3, 1)";
const EASE_WINDUP = "cubic-bezier(0.55, 0, 1, 0.45)";
const EASE_KICK = "cubic-bezier(0.7, 0, 0.84, 0)";

const SETTLE_MS = 200;
const ANTICIPATE_MS = 130;
const KICK_MS = 160;
const PAWL_MS = 160;
// Reduced motion drops the wind-up anticipation (pure flourish) but keeps a
// short, non-eased settle on the ack/fail step itself — the wheel angle is
// the only passive signal that a save just landed, so it needs to visibly
// move rather than teleport.
const REDUCED_MS = 140;

const ANNOUNCE_THROTTLE_MS = 30_000;
const HOVER_OPEN_DELAY_MS = 400;
const TOUCH_AUTOCLOSE_MS = 4000;
const TICK_MS = 1000;

const CENTER = 12;
const R_INNER = 6.2;
const R_OUTER = 9.6;

interface Tooth {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  index: boolean;
}

// 10 radial ticks, clock-style, index tooth (the only asymmetric one) at
// 12 o'clock — its position is the only thing that makes a one-tooth
// rotation of an otherwise 10-fold-symmetric ring visible at all.
const TEETH: Tooth[] = Array.from({ length: TOOTH_COUNT }, (_, i) => {
  const deg = -90 + i * TOOTH_DEG;
  const rad = (deg * Math.PI) / 180;
  const cos = Math.cos(rad);
  const sin = Math.sin(rad);
  return {
    x1: CENTER + R_INNER * cos,
    y1: CENTER + R_INNER * sin,
    x2: CENTER + R_OUTER * cos,
    y2: CENTER + R_OUTER * sin,
    index: i === 0,
  };
});

// Fixed pawl triangle, apex resting just inside the tooth ring at 12
// o'clock, base above it — never rotates with the wheel. Kept well clear of
// the viewBox edge so the thickened+lifted failure pose never clips.
const PAWL_PATH = `M ${CENTER} ${CENTER - R_OUTER + 1.2} L ${CENTER - 2.1} ${CENTER - R_OUTER - 0.6} L ${CENTER + 2.1} ${CENTER - R_OUTER - 0.6} Z`;

// Returns a complete relative-time phrase ("just now", "5s ago") so callers
// never append "ago" themselves — "just now ago" shipped once.
function formatAgo(ms: number): string {
  if (ms < 1000) return "just now";
  const s = Math.round(ms / 1000);
  if (s < 60) return `${s}s ago`;
  const m = Math.round(s / 60);
  if (m < 60) return `${m}m ago`;
  const h = Math.round(m / 60);
  return `${h}h ago`;
}

function setWheelAngle(el: SVGGElement | null, deg: number, ms: number, ease: string) {
  if (!el) return;
  el.style.transition = ms > 0 ? `transform ${ms}ms ${ease}` : "none";
  el.style.transform = `rotate(${deg}deg)`;
}

function setPawlPose(el: SVGPathElement | null, slipped: boolean, ms: number) {
  if (!el) return;
  el.style.transition =
    ms > 0
      ? `transform ${ms}ms ${EASE_OUT_EXPO}, stroke-width ${ms}ms ${EASE_OUT_EXPO}, stroke ${ms}ms linear`
      : "none";
  el.style.transform = slipped ? "translateY(-1.2px)" : "translateY(0)";
  el.style.strokeWidth = slipped ? "2" : "1.4";
  el.style.stroke = slipped ? "var(--foreground)" : "var(--ns-muted)";
}

function buildTooltipText(
  status: PawlTickStatus,
  count: number,
  failed: boolean,
  lastSavedAt: number | null,
  now: number
): string {
  if (failed) {
    if (count > 0 && lastSavedAt) {
      return `Save failed. ${count} saved this session, last successful save ${formatAgo(now - lastSavedAt)}.`;
    }
    return "Save failed. No successful saves yet this session.";
  }
  if (status === "saving") return "Saving…";
  if (count === 0) return "No saves yet this session.";
  const times = count === 1 ? "time" : "times";
  return `Saved ${count} ${times}, last ${formatAgo(now - (lastSavedAt ?? now))}.`;
}

export function PawlTick({ status, size = 20, className = "" }: PawlTickProps) {
  const autoId = useId();
  const tooltipId = `autosave-ratchet-tip-${autoId.replace(/:/g, "")}`;

  const rootRef = useRef<HTMLSpanElement | null>(null);
  const wheelRef = useRef<SVGGElement | null>(null);
  const pawlRef = useRef<SVGPathElement | null>(null);

  const reducedRef = useRef(false);
  const prevStatusRef = useRef<PawlTickStatus>(status);
  const angleRef = useRef(0); // angle currently applied to the wheel
  const successBaseRef = useRef(0); // angle of the last confirmed good seat
  const lastSavedAtRef = useRef<number | null>(null);
  const lastRoutineAnnounceRef = useRef(0);
  const parityRef = useRef(false);

  const [count, setCount] = useState(0);
  const [failed, setFailed] = useState(false);
  const [announceText, setAnnounceText] = useState("");

  const [open, setOpen] = useState(false);
  const [now, setNow] = useState(() => Date.now());
  const hoverRef = useRef(false);
  const focusRef = useRef(false);
  const viaTouchRef = useRef(false);
  const openTimerRef = useRef<number | undefined>(undefined);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    reducedRef.current = mq.matches;
    const onChange = () => {
      reducedRef.current = mq.matches;
    };
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  const announce = useCallback((message: "Saving" | "Saved" | "Save failed", force: boolean) => {
    const at = Date.now();
    if (!force) {
      if (at - lastRoutineAnnounceRef.current < ANNOUNCE_THROTTLE_MS) return;
      lastRoutineAnnounceRef.current = at;
    } else {
      lastRoutineAnnounceRef.current = 0; // guarantee the next routine announcement also goes through
    }
    // A zero-width toggle forces a real text-node change even when the
    // message text repeats (e.g. two "Save failed" in a row), which is what
    // actually re-triggers an aria-live announcement.
    parityRef.current = !parityRef.current;
    setAnnounceText(message + (parityRef.current ? "​" : ""));
  }, []);

  useEffect(() => {
    const prev = prevStatusRef.current;
    prevStatusRef.current = status;
    if (prev === status) return;

    const reduced = reducedRef.current;

    if (status === "saving") {
      if (!reduced) {
        const target = angleRef.current - ANTICIPATE_DEG;
        setWheelAngle(wheelRef.current, target, ANTICIPATE_MS, EASE_WINDUP);
        angleRef.current = target;
      }
      announce("Saving", false);
      return;
    }

    if (status === "saved") {
      const target = successBaseRef.current + TOOTH_DEG;
      setWheelAngle(wheelRef.current, target, reduced ? REDUCED_MS : SETTLE_MS, reduced ? "linear" : EASE_OUT_EXPO);
      angleRef.current = target;
      successBaseRef.current = target;
      setPawlPose(pawlRef.current, false, reduced ? REDUCED_MS : PAWL_MS);
      setFailed(false);
      lastSavedAtRef.current = Date.now();
      setCount((c) => c + 1);
      announce("Saved", false);
      return;
    }

    if (status === "error") {
      const target = successBaseRef.current - FAIL_KICK_DEG;
      setWheelAngle(wheelRef.current, target, reduced ? REDUCED_MS : KICK_MS, reduced ? "linear" : EASE_KICK);
      angleRef.current = target;
      setPawlPose(pawlRef.current, true, reduced ? REDUCED_MS : PAWL_MS);
      setFailed(true);
      announce("Save failed", true);
      return;
    }
    // "idle": no motion — a held failure pose stays held until a save
    // actually resolves it, never on a plain idle transition.
  }, [status, announce]);

  // Tick the tooltip's relative timestamp once a second while it's open.
  useEffect(() => {
    if (!open) return;
    setNow(Date.now());
    const id = window.setInterval(() => setNow(Date.now()), TICK_MS);
    return () => window.clearInterval(id);
  }, [open]);

  const evaluate = useCallback(() => {
    const should = hoverRef.current || focusRef.current;
    if (should && !open) {
      if (focusRef.current) {
        window.clearTimeout(openTimerRef.current);
        setOpen(true);
        return;
      }
      window.clearTimeout(openTimerRef.current);
      openTimerRef.current = window.setTimeout(() => setOpen(true), HOVER_OPEN_DELAY_MS);
    } else if (!should) {
      window.clearTimeout(openTimerRef.current);
      if (open) setOpen(false);
    }
  }, [open]);

  // Escape always closes; a touch-opened peek also gets outside-tap, scroll
  // and a safety timeout, since touch has no hover to release it on.
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    document.addEventListener("keydown", onKey);

    let onOutside: ((e: PointerEvent) => void) | undefined;
    let onScroll: (() => void) | undefined;
    let safety: number | undefined;
    if (viaTouchRef.current) {
      onOutside = (e) => {
        const t = e.target as Node;
        if (rootRef.current?.contains(t)) return;
        setOpen(false);
      };
      onScroll = () => setOpen(false);
      document.addEventListener("pointerdown", onOutside, true);
      window.addEventListener("scroll", onScroll, true);
      safety = window.setTimeout(() => setOpen(false), TOUCH_AUTOCLOSE_MS);
    }

    return () => {
      document.removeEventListener("keydown", onKey);
      if (onOutside) document.removeEventListener("pointerdown", onOutside, true);
      if (onScroll) window.removeEventListener("scroll", onScroll, true);
      if (safety !== undefined) window.clearTimeout(safety);
    };
  }, [open]);

  useEffect(() => () => window.clearTimeout(openTimerRef.current), []);

  const tooltipText = useMemo(
    () => buildTooltipText(status, count, failed, lastSavedAtRef.current, now),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [status, count, failed, now]
  );

  return (
    <span ref={rootRef} className={`relative inline-flex items-center gap-1.5 ${className}`}>
      <style>{CSS}</style>
      {/* The announcer, not the whole wrapper, is the live region: it holds
          only the throttled status message, so aria-atomic re-reading it
          on every change never picks up the button's label or an open
          tooltip's duplicated text along with it. */}
      <span role="status" aria-live="polite" aria-atomic="true" className="sr-only">
        {announceText}
      </span>

      <button
        type="button"
        aria-label="Autosave status"
        aria-describedby={open ? tooltipId : undefined}
        className="inline-flex shrink-0 items-center justify-center rounded-[6px] p-0.5 text-foreground hover:bg-border/50 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
        onPointerEnter={(e: ReactPointerEvent) => {
          if (e.pointerType === "touch") return;
          hoverRef.current = true;
          evaluate();
        }}
        onPointerLeave={(e: ReactPointerEvent) => {
          if (e.pointerType === "touch") return;
          hoverRef.current = false;
          evaluate();
        }}
        onPointerDown={(e: ReactPointerEvent) => {
          if (e.pointerType !== "touch") return;
          viaTouchRef.current = true;
          setOpen((v) => !v);
        }}
        onFocus={() => {
          focusRef.current = true;
          evaluate();
        }}
        onBlur={() => {
          focusRef.current = false;
          evaluate();
        }}
        onKeyDown={(e: ReactKeyboardEvent) => {
          if (e.key === "Escape" && open) {
            e.stopPropagation();
            setOpen(false);
          }
        }}
      >
        <svg
          width={size}
          height={size}
          viewBox="0 0 24 24"
          aria-hidden="true"
          focusable="false"
        >
          <g ref={wheelRef} className="ns-pt-wheel">
            <circle
              cx={CENTER}
              cy={CENTER}
              r={R_INNER - 0.4}
              fill="none"
              stroke="var(--border)"
              strokeWidth={1}
            />
            <circle cx={CENTER} cy={CENTER} r={1.6} fill="var(--border)" />
            {TEETH.map((t, i) => (
              <line
                key={i}
                x1={t.x1}
                y1={t.y1}
                x2={t.x2}
                y2={t.y2}
                strokeWidth={1.6}
                strokeLinecap="round"
                stroke={t.index ? "var(--foreground)" : "var(--ns-muted)"}
              />
            ))}
          </g>
          <path
            ref={pawlRef}
            d={PAWL_PATH}
            className="ns-pt-pawl"
            fill="none"
            stroke="var(--ns-muted)"
            strokeWidth={1.4}
            strokeLinejoin="round"
            strokeLinecap="round"
          />
        </svg>
      </button>

      {failed && (
        <span aria-hidden="true" className="font-mono text-[11px] uppercase tracking-wide text-foreground">
          Not saved
        </span>
      )}

      {open && (
        <div
          id={tooltipId}
          role="tooltip"
          aria-live="off"
          className="absolute left-1/2 top-full z-10 mt-2 w-max max-w-56 -translate-x-1/2 rounded-[6px] border border-border bg-background px-2.5 py-1.5 font-mono text-[11px] leading-snug text-foreground shadow-sm"
        >
          {tooltipText}
        </div>
      )}
    </span>
  );
}

const CSS = `
.ns-pt-wheel{transform-box:fill-box;transform-origin:center;}
.ns-pt-pawl{transform-box:fill-box;transform-origin:center;}
@media (prefers-reduced-motion: reduce){
  .ns-pt-wheel,.ns-pt-pawl{transition-duration:140ms !important;transition-timing-function:linear !important;}
}
`;

"use client";

import { useEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// AuxinCanal — a full-bleed hero whose vein network grows by space
// colonisation (Runions et al.) through whatever area the copy leaves empty.
// Auxin sources are scattered on a jittered grid across the container, then
// every source that falls inside a measured content box (headline, subcopy,
// CTA row, stat strip — read live via getBoundingClientRect under a
// ResizeObserver) is simply never added. Avoidance is therefore a property
// of where the sources exist, not a mask or clip-path drawn over the result.
//
// Each 30Hz tick: a quadtree of current vein tips answers "which sources are
// within reach", tips advance one step toward the mean direction of every
// source that picked them as nearest, and a second quadtree of sources
// answers "which sources just got swallowed" so they can be removed before
// the next tick. Kill distance dk = 1.7x the mean source spacing (the grid
// cell size); attraction radius = 5x dk; step length = 0.6x dk (always
// smaller than dk, so a step can never leap clean over a source without
// killing it). rho — how tight the source grid is packed — is the one knob
// between a sparse palm-fan network and a dense reticulate mesh.
//
// Segment width is NOT looked up from a lookup table; it is Murray's law,
// maintained incrementally. Every node tracks leafCount = the number of live
// terminal tips its subtree currently ends in (1 while it is itself a tip).
// Extending a tip in place never changes that count. Only the moment a node
// that already has one child grows a SECOND child — an actual fork — does
// its count rise, and that rise is walked straight up its ancestor chain.
// Width of the segment feeding any node = leafCount^(1/3), so a trunk is
// only ever as thick as the tissue still draining through it.
//
// Committed geometry is batched into eight <path> elements bucketed by that
// width (colour is var(--ns-muted) for the four thin buckets, var(--foreground)
// for the four thick ones, via `currentColor` on two wrapping <g>s so a theme
// switch repaints for free); only the current tick's freshly grown segments
// live in a ninth "active tip" path until the next tick folds them in. Once
// no source remains reachable the lamina rests, then abscises — the two
// wrapping groups' `color` transitions to var(--background), draining the
// whole network into the page — and a fresh source scatter begins.
// ---------------------------------------------------------------------------

interface Box {
  x: number;
  y: number;
  w: number;
  h: number;
}

interface Source {
  x: number;
  y: number;
}

interface VNode {
  x: number;
  y: number;
  parent: number; // -1 = seed, enters from the container edge
  leafCount: number;
  children: number[];
}

interface QPoint {
  x: number;
  y: number;
  id: number;
}

/** Minimal point quadtree: insert + circular range query. Rebuilt fresh each
 * tick from whichever point set (tips, or remaining sources) it is asked to
 * index — cheap at these counts (<=1500 points) and avoids ever having to
 * remove a point from a persistent tree. */
class Quadtree {
  private readonly capacity = 8;
  private points: QPoint[] = [];
  private divided = false;
  private nw: Quadtree | null = null;
  private ne: Quadtree | null = null;
  private sw: Quadtree | null = null;
  private se: Quadtree | null = null;

  constructor(private readonly bx: number, private readonly by: number, private readonly bw: number, private readonly bh: number) {}

  private contains(p: QPoint): boolean {
    return p.x >= this.bx && p.x < this.bx + this.bw && p.y >= this.by && p.y < this.by + this.bh;
  }

  private intersectsCircle(cx: number, cy: number, r: number): boolean {
    const nx = Math.max(this.bx, Math.min(cx, this.bx + this.bw));
    const ny = Math.max(this.by, Math.min(cy, this.by + this.bh));
    const dx = cx - nx;
    const dy = cy - ny;
    return dx * dx + dy * dy <= r * r;
  }

  private subdivide(): void {
    const hw = this.bw / 2;
    const hh = this.bh / 2;
    this.nw = new Quadtree(this.bx, this.by, hw, hh);
    this.ne = new Quadtree(this.bx + hw, this.by, hw, hh);
    this.sw = new Quadtree(this.bx, this.by + hh, hw, hh);
    this.se = new Quadtree(this.bx + hw, this.by + hh, hw, hh);
    this.divided = true;
  }

  insert(p: QPoint): boolean {
    if (!this.contains(p)) return false;
    if (!this.divided && this.points.length < this.capacity) {
      this.points.push(p);
      return true;
    }
    if (this.bw < 1 || this.bh < 1) {
      // degenerate leaf — stop subdividing, just accumulate
      this.points.push(p);
      return true;
    }
    if (!this.divided) this.subdivide();
    return (
      (this.nw?.insert(p) ?? false) ||
      (this.ne?.insert(p) ?? false) ||
      (this.sw?.insert(p) ?? false) ||
      (this.se?.insert(p) ?? false)
    );
  }

  queryRadius(cx: number, cy: number, r: number, out: QPoint[]): void {
    if (!this.intersectsCircle(cx, cy, r)) return;
    const r2 = r * r;
    for (const p of this.points) {
      const dx = p.x - cx;
      const dy = p.y - cy;
      if (dx * dx + dy * dy <= r2) out.push(p);
    }
    if (this.divided) {
      this.nw?.queryRadius(cx, cy, r, out);
      this.ne?.queryRadius(cx, cy, r, out);
      this.sw?.queryRadius(cx, cy, r, out);
      this.se?.queryRadius(cx, cy, r, out);
    }
  }
}

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const KILL_RATIO = 1.7; // dk = KILL_RATIO * mean source spacing
const ATTRACT_RATIO = 5; // di = ATTRACT_RATIO * dk
const STEP_RATIO = 0.6; // D = STEP_RATIO * dk — always < dk
const BOX_PAD = 22; // px clearance kept around every measured content box
const STEP_MS = 1000 / 30; // fixed 30Hz colonisation tick
const STAGNANT_LIMIT = 3; // consecutive empty ticks before growth is "done"
const MAX_TICKS = 900; // hard safety cap (~30s at 30Hz)
const MAX_NODES = 1600;
const REST_MS = 3200; // how long a completed lamina rests before it drains
const DRAIN_MS = 1500; // colour-drain to --background
const W0 = 0.55; // leaf (tip) stroke width in px

const BUCKET_WIDTH = [0.55, 0.85, 1.15, 1.5, 1.9, 2.4, 3.0, 3.7];
const BUCKET_OPACITY = [0.3, 0.4, 0.5, 0.6, 0.5, 0.66, 0.82, 1];
const THIN_BUCKETS = 4; // buckets 0..3 render in the --ns-muted group

function buildSeeds(w: number, h: number): Source[] {
  return [
    { x: w * 0.14, y: h - 1 },
    { x: w * 0.5, y: h - 1 },
    { x: w * 0.86, y: h - 1 },
    { x: 1, y: h * 0.28 },
    { x: 1, y: h * 0.72 },
    { x: w - 1, y: h * 0.28 },
    { x: w - 1, y: h * 0.72 },
  ];
}

function insideAnyBox(x: number, y: number, boxes: Box[]): boolean {
  for (const b of boxes) {
    if (x >= b.x - BOX_PAD && x <= b.x + b.w + BOX_PAD && y >= b.y - BOX_PAD && y <= b.y + b.h + BOX_PAD) {
      return true;
    }
  }
  return false;
}

function buildSources(
  w: number,
  h: number,
  boxes: Box[],
  targetCount: number,
  rand: () => number
): { sources: Source[]; meanSpacing: number } {
  const area = Math.max(1, w * h);
  const cell = Math.sqrt(area / Math.max(1, targetCount));
  const cols = Math.max(1, Math.round(w / cell));
  const rows = Math.max(1, Math.round(h / cell));
  const cw = w / cols;
  const ch = h / rows;
  const sources: Source[] = [];
  for (let j = 0; j < rows; j++) {
    for (let i = 0; i < cols; i++) {
      const x = (i + 0.5) * cw + (rand() - 0.5) * 0.8 * cw;
      const y = (j + 0.5) * ch + (rand() - 0.5) * 0.8 * ch;
      if (x < 0 || y < 0 || x > w || y > h) continue;
      if (insideAnyBox(x, y, boxes)) continue;
      sources.push({ x, y });
    }
  }
  return { sources, meanSpacing: (cw + ch) / 2 };
}

export interface AuxinCanalProps {
  /** mono eyebrow line above the headline */
  eyebrow?: string;
  /** display headline, one string per rendered line */
  headlineLines?: string[];
  /** muted supporting copy under the headline */
  subcopy?: string;
  /** accent primary CTA */
  primaryCta?: { label: string; href: string };
  /** ghost secondary CTA */
  secondaryCta?: { label: string; href: string };
  /** three mono stats for the bordered strip below the CTAs */
  stats?: { value: string; label: string }[];
  /** target auxin source count before content-box exclusion (rho's knob) */
  sourceCount?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function AuxinCanal({
  eyebrow = "SPACE-COLONISED ROUTING",
  headlineLines = ["Traffic finds every channel", "your interface leaves open"],
  subcopy = "Auxin Canal grows a delivery network through whatever capacity the page doesn't use — sources scattered across the empty space, consumed as tips reach them, and widened by Murray's law so trunks earn their thickness from the load they actually carry.",
  primaryCta = { label: "Read the docs", href: "#docs" },
  secondaryCta = { label: "View the API", href: "#api" },
  stats = [
    { value: "1,200", label: "auxin sources / cycle" },
    { value: "1.7×", label: "kill-distance ratio" },
    { value: "30Hz", label: "colonisation tick" },
  ],
  sourceCount = 1200,
  className = "",
}: AuxinCanalProps) {
  const rootRef = useRef<HTMLElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);
  const bucketRefs = useRef<(SVGPathElement | null)[]>([]);
  const activeRef = useRef<SVGPathElement | null>(null);
  const [draining, setDraining] = useState(false);
  const linesKey = headlineLines.join(" ");

  useEffect(() => {
    const root = rootRef.current;
    const svg = svgRef.current;
    if (!root || !svg) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const rand = mulberry32(0xa0c1a2);

    let disposed = false;
    let w = 0;
    let h = 0;
    let sized = false;

    let nodes: VNode[] = [];
    let sources: Source[] = [];
    let dk = 1;
    let di = 1;
    let step = 1;
    let newTickStart = 0;
    let stagnant = 0;
    let tickCount = 0;
    let phase: "grow" | "rest" | "drain" = "grow";
    let visible = true;

    let raf = 0;
    let acc = 0;
    let last = 0;
    let restTimer = 0;
    let drainTimer = 0;

    const measureBoxes = (): Box[] => {
      const rect = root.getBoundingClientRect();
      const boxes: Box[] = [];
      root.querySelectorAll<HTMLElement>("[data-auxin-box]").forEach((el) => {
        const r = el.getBoundingClientRect();
        if (r.width <= 0 || r.height <= 0) return;
        boxes.push({ x: r.left - rect.left, y: r.top - rect.top, w: r.width, h: r.height });
      });
      return boxes;
    };

    const applyD = (idx: number, d: string) => {
      const el = bucketRefs.current[idx];
      if (el) el.setAttribute("d", d);
    };

    const clearPaths = () => {
      for (let i = 0; i < 8; i++) applyD(i, "");
      activeRef.current?.setAttribute("d", "");
    };

    // -- one node ends a tip's flight; adding a child is where Murray's law
    // actually happens: extending an existing tip in place costs nothing,
    // only a genuine fork (a node gaining its SECOND child) raises leafCount,
    // and that rise is walked straight up the ancestor chain. --------------
    const addChild = (parentIdx: number, x: number, y: number): number => {
      const idx = nodes.length;
      nodes.push({ x, y, parent: parentIdx, leafCount: 1, children: [] });
      const parent = nodes[parentIdx];
      if (!parent) return idx;
      const wasLeaf = parent.children.length === 0;
      parent.children.push(idx);
      if (!wasLeaf) {
        let cur: number = parentIdx;
        while (cur !== -1) {
          const n = nodes[cur];
          if (!n) break;
          n.leafCount += 1;
          cur = n.parent;
        }
      }
      return idx;
    };

    // -- one fixed-length colonisation step: attract every live source to
    // its nearest reachable tip via a quadtree of nodes, advance every tip
    // that attracted at least one source, then kill every source a fresh
    // node lands within dk of via a quadtree of sources. ------------------
    const tick = (): boolean => {
      if (sources.length === 0 || nodes.length >= MAX_NODES) return false;

      const nodeQT = new Quadtree(-di, -di, w + 2 * di, h + 2 * di);
      for (let i = 0; i < nodes.length; i++) {
        const n = nodes[i];
        if (n) nodeQT.insert({ x: n.x, y: n.y, id: i });
      }

      const sumX = new Map<number, number>();
      const sumY = new Map<number, number>();
      const buf: QPoint[] = [];
      for (const s of sources) {
        buf.length = 0;
        nodeQT.queryRadius(s.x, s.y, di, buf);
        if (buf.length === 0) continue;
        let bestId = -1;
        let bestD = Infinity;
        for (const p of buf) {
          const dx = p.x - s.x;
          const dy = p.y - s.y;
          const d = dx * dx + dy * dy;
          if (d < bestD) {
            bestD = d;
            bestId = p.id;
          }
        }
        if (bestId < 0) continue;
        const node = nodes[bestId];
        if (!node) continue;
        const dx = s.x - node.x;
        const dy = s.y - node.y;
        const len = Math.hypot(dx, dy) || 1;
        sumX.set(bestId, (sumX.get(bestId) ?? 0) + dx / len);
        sumY.set(bestId, (sumY.get(bestId) ?? 0) + dy / len);
      }
      if (sumX.size === 0) return false;

      newTickStart = nodes.length;
      for (const [idx, sx] of sumX) {
        const sy = sumY.get(idx) ?? 0;
        const len = Math.hypot(sx, sy) || 1;
        const parent = nodes[idx];
        if (!parent) continue;
        const nx = parent.x + (sx / len) * step;
        const ny = parent.y + (sy / len) * step;
        addChild(idx, nx, ny);
        if (nodes.length >= MAX_NODES) break;
      }
      if (nodes.length === newTickStart) return false;

      const srcQT = new Quadtree(-1, -1, w + 2, h + 2);
      for (let i = 0; i < sources.length; i++) {
        const s = sources[i];
        if (s) srcQT.insert({ x: s.x, y: s.y, id: i });
      }
      const dead = new Set<number>();
      const kbuf: QPoint[] = [];
      for (let i = newTickStart; i < nodes.length; i++) {
        const n = nodes[i];
        if (!n) continue;
        kbuf.length = 0;
        srcQT.queryRadius(n.x, n.y, dk, kbuf);
        for (const p of kbuf) dead.add(p.id);
      }
      if (dead.size > 0) sources = sources.filter((_, i) => !dead.has(i));
      return true;
    };

    // -- rebuild the eight committed buckets (everything grown before this
    // tick) and the one active-tip path (everything grown this tick). Full
    // rebuild every tick is O(nodes) — trivial at these counts (<=1600). --
    const render = () => {
      let maxLeaf = 1;
      for (const n of nodes) if (n.leafCount > maxLeaf) maxLeaf = n.leafCount;
      const maxWidth = W0 * Math.cbrt(maxLeaf);
      const spans = new Array(8).fill("") as string[];
      let activeSpan = "";
      for (let i = 0; i < nodes.length; i++) {
        const n = nodes[i];
        if (!n || n.parent === -1) continue;
        const p = nodes[n.parent];
        if (!p) continue;
        const seg = `M${p.x.toFixed(1)} ${p.y.toFixed(1)}L${n.x.toFixed(1)} ${n.y.toFixed(1)}`;
        if (i >= newTickStart) {
          activeSpan += seg;
          continue;
        }
        const width = W0 * Math.cbrt(n.leafCount);
        const t = maxWidth > W0 ? (width - W0) / (maxWidth - W0) : 0;
        const bi = Math.min(7, Math.max(0, Math.floor(t * 8)));
        spans[bi] += seg;
      }
      for (let i = 0; i < 8; i++) applyD(i, spans[i] ?? "");
      activeRef.current?.setAttribute("d", activeSpan);
    };

    const finishGrowth = () => {
      phase = "rest";
      newTickStart = nodes.length; // fold whatever was still "active" in
      render();
      window.clearTimeout(restTimer);
      restTimer = window.setTimeout(beginDrain, REST_MS);
    };

    const beginDrain = () => {
      if (disposed) return;
      phase = "drain";
      setDraining(true);
      window.clearTimeout(drainTimer);
      drainTimer = window.setTimeout(resetCycle, DRAIN_MS);
    };

    const resetCycle = () => {
      if (disposed) return;
      setDraining(false);
      clearPaths();
      startCycle();
    };

    const startCycle = () => {
      window.clearTimeout(restTimer);
      window.clearTimeout(drainTimer);
      const rect = root.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      if (w < 2 || h < 2) {
        sized = false;
        return;
      }
      sized = true;
      const boxes = measureBoxes();
      const built = buildSources(w, h, boxes, sourceCount, rand);
      sources = built.sources;
      dk = KILL_RATIO * built.meanSpacing;
      di = ATTRACT_RATIO * dk;
      step = STEP_RATIO * dk;
      nodes = buildSeeds(w, h).map((s) => ({ x: s.x, y: s.y, parent: -1, leafCount: 1, children: [] }));
      newTickStart = nodes.length;
      stagnant = 0;
      tickCount = 0;
      phase = "grow";

      if (reduced) {
        // run the whole cycle to completion synchronously, once, and stop
        for (let i = 0; i < MAX_TICKS; i++) {
          const grew = tick();
          if (!grew) {
            stagnant += 1;
            if (stagnant >= STAGNANT_LIMIT) break;
          } else {
            stagnant = 0;
          }
        }
        newTickStart = nodes.length;
        render();
        phase = "rest"; // settled — no drain, no further cycles
        return;
      }

      last = 0;
      acc = 0;
      if (!raf) raf = requestAnimationFrame(loop);
    };

    const loop = (now: number) => {
      raf = 0;
      if (!visible || !sized || phase !== "grow") return;
      if (last === 0) last = now;
      acc += Math.min(100, now - last);
      last = now;
      while (acc >= STEP_MS) {
        acc -= STEP_MS;
        const grew = tick();
        tickCount += 1;
        if (!grew) {
          stagnant += 1;
        } else {
          stagnant = 0;
        }
        if (stagnant >= STAGNANT_LIMIT || tickCount >= MAX_TICKS) {
          finishGrowth();
          return;
        }
      }
      render();
      raf = requestAnimationFrame(loop);
    };

    startCycle();

    // -- resize / layout observers: re-measure content boxes and restart
    // the whole cycle, so a moved headline genuinely changes the topology
    // rather than just clipping the same network differently. ------------
    let resizeTimer = 0;
    const onResize = () => {
      window.clearTimeout(resizeTimer);
      resizeTimer = window.setTimeout(() => {
        if (disposed) return;
        cancelAnimationFrame(raf);
        raf = 0;
        window.clearTimeout(restTimer);
        window.clearTimeout(drainTimer);
        setDraining(false);
        clearPaths();
        startCycle();
      }, 120);
    };
    const ro = new ResizeObserver(onResize);
    ro.observe(root);

    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && phase === "grow" && !raf) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    });
    io.observe(root);

    document.fonts.ready.then(() => {
      if (!disposed) onResize();
    });

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      raf = 0;
      window.clearTimeout(restTimer);
      window.clearTimeout(drainTimer);
      window.clearTimeout(resizeTimer);
      ro.disconnect();
      io.disconnect();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [linesKey, sourceCount]);

  return (
    <section
      ref={rootRef}
      className={`relative isolate overflow-hidden bg-background ${className}`}
    >
      <svg
        ref={svgRef}
        aria-hidden="true"
        focusable="false"
        className="pointer-events-none absolute inset-0 h-full w-full"
      >
        <g
          style={{
            color: draining ? "var(--background)" : "var(--ns-muted)",
            transition: "color 1500ms cubic-bezier(0.4, 0, 0.2, 1)",
          }}
        >
          {BUCKET_WIDTH.slice(0, THIN_BUCKETS).map((width, i) => (
            <path
              key={i}
              ref={(el) => {
                bucketRefs.current[i] = el;
              }}
              d=""
              fill="none"
              stroke="currentColor"
              strokeOpacity={BUCKET_OPACITY[i]}
              strokeWidth={width}
              strokeLinecap="round"
            />
          ))}
          <path
            ref={activeRef}
            d=""
            fill="none"
            stroke="currentColor"
            strokeOpacity={0.4}
            strokeWidth={BUCKET_WIDTH[0]}
            strokeLinecap="round"
          />
        </g>
        <g
          style={{
            color: draining ? "var(--background)" : "var(--foreground)",
            transition: "color 1500ms cubic-bezier(0.4, 0, 0.2, 1)",
          }}
        >
          {BUCKET_WIDTH.slice(THIN_BUCKETS).map((width, i) => (
            <path
              key={i + THIN_BUCKETS}
              ref={(el) => {
                bucketRefs.current[i + THIN_BUCKETS] = el;
              }}
              d=""
              fill="none"
              stroke="currentColor"
              strokeOpacity={BUCKET_OPACITY[i + THIN_BUCKETS]}
              strokeWidth={width}
              strokeLinecap="round"
            />
          ))}
        </g>
      </svg>
      <div className="relative z-10 mx-auto flex w-full max-w-5xl flex-col items-center px-6 pb-16 pt-24 text-center sm:pb-24 sm:pt-32">
        <p className="mb-6 font-mono text-[11px] tracking-widest text-ns-muted">{eyebrow}</p>
        <h1
          data-auxin-box
          className="font-semibold text-foreground"
          style={{ fontSize: "clamp(2.5rem, 6.5vw, 4.5rem)", lineHeight: 1.06, letterSpacing: "-0.03em" }}
        >
          {headlineLines.map((line, i) => (
            <span key={i} className="block">
              {line}
            </span>
          ))}
        </h1>
        <p data-auxin-box className="mt-6 max-w-xl text-base leading-relaxed text-ns-muted">
          {subcopy}
        </p>
        <div data-auxin-box className="mt-9 flex flex-wrap items-center justify-center gap-3">
          <a
            href={primaryCta.href}
            className="rounded-sm bg-ns-accent px-5 py-2.5 text-sm font-medium text-white transition-colors duration-200 hover:bg-ns-accent-hover focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
          >
            {primaryCta.label}
          </a>
          <a
            href={secondaryCta.href}
            className="rounded-sm border border-border px-5 py-2.5 text-sm font-medium text-ns-muted transition-colors duration-200 hover:border-foreground/20 hover:bg-surface hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
          >
            {secondaryCta.label}
          </a>
        </div>
        <div
          data-auxin-box
          className="mt-16 grid w-full max-w-2xl grid-cols-1 divide-y divide-border border-y border-border sm:grid-cols-3 sm:divide-x sm:divide-y-0"
        >
          {stats.slice(0, 3).map((s) => (
            <div key={s.label} className="flex flex-col items-center gap-1 px-6 py-4">
              <span className="font-mono text-lg text-foreground">{s.value}</span>
              <span className="font-mono text-[11px] tracking-widest text-ns-muted">
                {s.label.toUpperCase()}
              </span>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// FlockStack — team avatar stack that never sits still: at rest the avatars
// mill as a bounded boids flock (separation / alignment / cohesion + soft
// walls); hovering or keyboard-focusing the region ramps a seek force toward
// each avatar's slot in the classic overlapping row, SUMMED into the same
// three rules, so the tidy "group photo" is itself a settled flocking state.
// Pure DOM — per-frame transforms from a refs-only vector sim, no canvas, no
// React state on the hot path. Every color is a CSS token class (nothing is
// read via getComputedStyle, so there is nothing to re-derive on theme
// change — ring-background / border-border / bg-surface self-adapt). The +N
// badge fades in only once the formation resolves; once resolved AND settled
// the rAF loop genuinely sleeps until hover exit. Static resolved row under
// prefers-reduced-motion.
// ---------------------------------------------------------------------------

export interface FlockMember {
  name: string;
  /** 1–2 chars; derived from name when omitted */
  initials?: string;
  /** optional avatar image url; initials shown otherwise */
  src?: string;
}

const DEFAULT_MEMBERS: FlockMember[] = [
  { name: "Mara Chen" },
  { name: "Jonas Weber" },
  { name: "Aiko Tanaka" },
  { name: "Sam Okafor" },
  { name: "Lena Fischer" },
  { name: "Ravi Patel" },
  { name: "Nora Lindqvist" },
];

function initialsOf(m: FlockMember) {
  if (m.initials) return m.initials.slice(0, 2).toUpperCase();
  return m.name
    .split(/\s+/)
    .map((w) => w[0] ?? "")
    .join("")
    .slice(0, 2)
    .toUpperCase();
}

// deterministic PRNG for the initial scatter (stable across strict-mode runs)
function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// sim constants — px, seconds
const SEP_R = 34;
const SEP_W = 1.4;
const ALI_R = 60;
const ALI_W = 0.6;
const COH_R = 90;
const COH_W = 0.5;
const MAX_SPEED = 60; // px/s while milling — keeps the ambient drift calm
const SEEK_MAX_SPEED = 480; // px/s ceiling while seeking, ramped in with seekT
const MAX_FORCE = 260; // steering clamp, px/s^2
const WALL_M = 24; // soft-wall ramp distance
const WALL_F = 300; // px/s^2 at the edge
const SEEK_W = 2.2; // full seek weight after the ramp
const SEEK_RAMP_S = 0.4; // seconds, both directions
const ARRIVE_R = 40; // arrival slowdown radius

export function FlockStack({
  members = DEFAULT_MEMBERS,
  overflow = 3,
  avatarSize = 28,
  className = "h-[120px]",
  "aria-label": ariaLabel,
}: {
  /** flocking avatars (<=12 recommended; sim is O(n^2)) */
  members?: FlockMember[];
  /** count in the "+N" badge shown once the flock resolves */
  overflow?: number;
  /** avatar diameter in px */
  avatarSize?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** accessible name for the avatar group */
  "aria-label"?: string;
}) {
  const regionRef = useRef<HTMLDivElement>(null);
  const badgeRef = useRef<HTMLDivElement>(null);
  const itemRefs = useRef<(HTMLDivElement | null)[]>([]);

  useEffect(() => {
    const region = regionRef.current;
    if (!region) return;
    const badge = badgeRef.current; // null when overflow <= 0
    const items = itemRefs.current
      .slice(0, members.length)
      .filter((el): el is HTMLDivElement => el !== null);
    const n = items.length;
    if (n === 0) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;
    const half = avatarSize / 2;

    // hot-path state — plain locals/arrays, never React state
    const px: number[] = new Array(n).fill(0);
    const py: number[] = new Array(n).fill(0);
    const vx: number[] = new Array(n).fill(0);
    const vy: number[] = new Array(n).fill(0);
    const wanderA: number[] = new Array(n).fill(0);
    const slotX: number[] = new Array(n).fill(0);
    let slotY = 0;
    let W = 0;
    let H = 0;
    let sized = false;

    const measure = () => {
      const r = region.getBoundingClientRect();
      W = r.width;
      H = r.height;
      // zero/tiny-size guard: no slots, no sim until we have real bounds
      sized = W >= avatarSize * 2 && H >= avatarSize + 8;
      if (!sized) return;
      const badgeCX = W - 16 - half;
      // classic -8 px overlap, compressed if the region is narrow
      const step = Math.min(
        avatarSize - 8,
        Math.max(6, (badgeCX - half - 12) / n)
      );
      slotY = H / 2;
      for (let i = 0; i < n; i++) slotX[i] = badgeCX - (n - i) * step;
      if (badge) {
        badge.style.transform = `translate3d(${badgeCX - half}px, ${slotY - half}px, 0)`;
      }
      // keep agents inside fresh bounds after a resize
      for (let i = 0; i < n; i++) {
        px[i] = Math.min(Math.max(px[i] ?? 0, half), W - half);
        py[i] = Math.min(Math.max(py[i] ?? 0, half), H - half);
      }
    };
    measure();

    // per-avatar hover: lift + tooltip, only once the formation is resolved
    let resolvedNow = reduced;
    const detachHover: Array<() => void> = [];
    items.forEach((el) => {
      const inner = el.querySelector<HTMLElement>("[data-avatar]");
      const tip = el.querySelector<HTMLElement>("[data-tip]");
      const baseZ = el.style.zIndex;
      const enter = () => {
        if (!resolvedNow) return;
        el.style.zIndex = "40";
        if (inner) inner.style.transform = "translateY(-3px)";
        if (tip) tip.style.opacity = "1";
      };
      const leave = () => {
        el.style.zIndex = baseZ;
        if (inner) inner.style.transform = "";
        if (tip) tip.style.opacity = "0";
      };
      el.addEventListener("pointerenter", enter);
      el.addEventListener("pointerleave", leave);
      detachHover.push(() => {
        el.removeEventListener("pointerenter", enter);
        el.removeEventListener("pointerleave", leave);
      });
    });

    // ------------------------------------------------------------------
    // reduced motion: static two-state — resolved row, badge always on,
    // no milling ever; tooltips/lift still work (CSS transitions only)
    // ------------------------------------------------------------------
    if (reduced) {
      const place = () => {
        measure();
        if (!sized) return;
        items.forEach((el, i) => {
          el.style.transform = `translate3d(${(slotX[i] ?? 0) - half}px, ${slotY - half}px, 0)`;
          el.style.opacity = "1";
        });
        if (badge) badge.style.opacity = "1";
      };
      region.dataset.resolved = "true";
      place();
      const ro = new ResizeObserver(place);
      ro.observe(region);
      return () => {
        ro.disconnect();
        detachHover.forEach((f) => f());
      };
    }

    // ------------------------------------------------------------------
    // animated path
    // ------------------------------------------------------------------
    const rand = mulberry32(0xf10c5 + n);
    let seeded = false;
    const seed = () => {
      if (seeded || !sized) return;
      for (let i = 0; i < n; i++) {
        px[i] = half + 8 + rand() * Math.max(1, W - avatarSize - 16);
        py[i] = half + 8 + rand() * Math.max(1, H - avatarSize - 16);
        const a = rand() * Math.PI * 2;
        vx[i] = Math.cos(a) * MAX_SPEED * 0.5;
        vy[i] = Math.sin(a) * MAX_SPEED * 0.5;
        wanderA[i] = a;
      }
      items.forEach((el) => {
        el.style.opacity = "1";
      });
      seeded = true;
    };
    seed();

    let raf = 0;
    let last = 0;
    let ioVisible = true;
    let docVisible = !document.hidden;
    let hovered = false;
    let focused = false;
    let seekT = 0; // 0..1, ramps over SEEK_RAMP_S both ways
    let sleeping = false;

    const setResolved = (v: boolean) => {
      if (resolvedNow === v) return;
      resolvedNow = v;
      region.dataset.resolved = v ? "true" : "false";
      if (badge) badge.style.opacity = v ? "1" : "0";
    };

    const clampScale = (x: number, y: number) => {
      const l = Math.hypot(x, y);
      return l > MAX_FORCE ? MAX_FORCE / l : 1;
    };

    function step(now: number) {
      raf = 0;
      if (!seeded) seed();
      if (!sized || !seeded) return; // ResizeObserver wakes us with real bounds
      const dt = last === 0 ? 1 / 60 : Math.min(0.05, (now - last) / 1000);
      last = now;

      const wantSeek = hovered || focused;
      seekT = Math.min(
        1,
        Math.max(0, seekT + ((wantSeek ? 1 : -1) * dt) / SEEK_RAMP_S)
      );
      const seekW = SEEK_W * seekT;
      const mill = 1 - seekT; // milling drive fades as the seek ramps in
      // the three rules stay summed, attenuated so arrival can actually settle —
      // must reach exactly 0 at full seek (mirrors `mill`) or a residual
      // separation force fights the seek force forever at tight slot spacing
      const flockW = Math.max(0, 1 - seekT);
      // milling's MAX_SPEED (60 px/s) is deliberately slow for a calm resting
      // drift, but that same cap made a from-scatter seek arrival take
      // 5-6+ seconds — far past the 400ms seek-ramp. Ramp a higher travel
      // ceiling in with seekT so milling speed is untouched at rest and the
      // seek phase alone gets a real sprint toward the slot.
      const travelCap = MAX_SPEED + (SEEK_MAX_SPEED - MAX_SPEED) * seekT;

      const damp = Math.pow(0.98, dt * 60);
      let allNear = true;
      let allStill = true;
      // position-only — deliberately NOT the same test as `allNear` (which
      // also gates on speed): a wake-from-sleep velocity kick can trip a
      // speed threshold for a frame without the avatar visibly leaving its
      // slot, and clearing the badge on that alone is exactly the flicker.
      let anyDeparted = false;

      for (let i = 0; i < n; i++) {
        const xi = px[i] ?? 0;
        const yi = py[i] ?? 0;
        let vxi = vx[i] ?? 0;
        let vyi = vy[i] ?? 0;
        let ax = 0;
        let ay = 0;

        // neighbor accumulation (n <= 12 → O(n^2) is nothing)
        let sx = 0;
        let sy = 0;
        let sc = 0;
        let alx = 0;
        let aly = 0;
        let ac = 0;
        let cxs = 0;
        let cys = 0;
        let cc = 0;
        for (let j = 0; j < n; j++) {
          if (j === i) continue;
          let dx = xi - (px[j] ?? 0);
          let dy = yi - (py[j] ?? 0);
          let d = Math.hypot(dx, dy);
          if (d < 1e-4) {
            // coincident agents: deterministic nudge, never a zero-length vector
            dx = i > j ? 0.01 : -0.01;
            dy = 0;
            d = 0.01;
          }
          if (d < SEP_R) {
            const f = (1 - d / SEP_R) / d;
            sx += dx * f;
            sy += dy * f;
            sc++;
          }
          if (d < ALI_R) {
            alx += vx[j] ?? 0;
            aly += vy[j] ?? 0;
            ac++;
          }
          if (d < COH_R) {
            cxs += px[j] ?? 0;
            cys += py[j] ?? 0;
            cc++;
          }
        }

        // Reynolds steering: desired velocity − current, clamped to MAX_FORCE
        if (sc > 0) {
          const m = Math.hypot(sx, sy);
          if (m > 1e-5) {
            const fx = (sx / m) * MAX_SPEED - vxi;
            const fy = (sy / m) * MAX_SPEED - vyi;
            const s = clampScale(fx, fy);
            ax += SEP_W * flockW * fx * s;
            ay += SEP_W * flockW * fy * s;
          }
        }
        if (ac > 0) {
          const mvx = alx / ac;
          const mvy = aly / ac;
          const m = Math.hypot(mvx, mvy);
          if (m > 1e-5) {
            const fx = (mvx / m) * MAX_SPEED - vxi;
            const fy = (mvy / m) * MAX_SPEED - vyi;
            const s = clampScale(fx, fy);
            ax += ALI_W * flockW * fx * s;
            ay += ALI_W * flockW * fy * s;
          }
        }
        if (cc > 0) {
          const tx = cxs / cc - xi;
          const ty = cys / cc - yi;
          const m = Math.hypot(tx, ty);
          if (m > 1e-5) {
            const fx = (tx / m) * MAX_SPEED - vxi;
            const fy = (ty / m) * MAX_SPEED - vyi;
            const s = clampScale(fx, fy);
            ax += COH_W * flockW * fx * s;
            ay += COH_W * flockW * fy * s;
          }
        }

        // milling drive: wander random-walk + cruise thrust, fades with seek
        if (mill > 0.001) {
          wanderA[i] = (wanderA[i] ?? 0) + (Math.random() * 2 - 1) * 4 * dt;
          const wa = wanderA[i] ?? 0;
          ax += Math.cos(wa) * 28 * mill;
          ay += Math.sin(wa) * 28 * mill;
          const sp = Math.hypot(vxi, vyi);
          if (sp > 1e-3) {
            const thrust = (MAX_SPEED * 0.65 - sp) * 1.6 * mill;
            ax += (vxi / sp) * thrust;
            ay += (vyi / sp) * thrust;
          } else {
            ax += Math.cos(wa) * 60 * mill;
            ay += Math.sin(wa) * 60 * mill;
          }
        }

        // soft walls: force ramps to WALL_F inside WALL_M of the region edge
        const dl = xi - half;
        if (dl < WALL_M) ax += WALL_F * (1 - Math.max(0, dl) / WALL_M);
        const dr = W - half - xi;
        if (dr < WALL_M) ax -= WALL_F * (1 - Math.max(0, dr) / WALL_M);
        const dtp = yi - half;
        if (dtp < WALL_M) ay += WALL_F * (1 - Math.max(0, dtp) / WALL_M);
        const db = H - half - yi;
        if (db < WALL_M) ay -= WALL_F * (1 - Math.max(0, db) / WALL_M);

        // seek to slot: summed into the same field, arrival slowdown < 40 px
        const sxT = slotX[i] ?? 0;
        if (seekW > 0) {
          const dx = sxT - xi;
          const dy = slotY - yi;
          const d = Math.hypot(dx, dy);
          if (d > 1e-4) {
            const spd = d < ARRIVE_R ? travelCap * (d / ARRIVE_R) : travelCap;
            const fx = (dx / d) * spd - vxi;
            const fy = (dy / d) * spd - vyi;
            const s = clampScale(fx, fy);
            ax += seekW * fx * s;
            ay += seekW * fy * s;
          }
        }

        // integrate: damping 0.98/frame normalized, speed cap ramps with seekT
        vxi = (vxi + ax * dt) * damp;
        vyi = (vyi + ay * dt) * damp;
        const sp2 = Math.hypot(vxi, vyi);
        if (sp2 > travelCap) {
          const s = travelCap / sp2;
          vxi *= s;
          vyi *= s;
        }
        let nx = xi + vxi * dt;
        let ny = yi + vyi * dt;

        // capture assist at full ramp: physics carries the approach, this
        // closes the last few px so the 2 px / 1 px/s gate is reachable
        if (seekT > 0.95) {
          const ddx = sxT - nx;
          const ddy = slotY - ny;
          if (Math.hypot(ddx, ddy) < 8) {
            const k = Math.min(1, 10 * dt);
            nx += ddx * k;
            ny += ddy * k;
            const kd = Math.pow(0.8, dt * 60);
            vxi *= kd;
            vyi *= kd;
          }
        }

        // hard containment safety net (soft walls do the real work)
        if (nx < half) {
          nx = half;
          vxi = Math.abs(vxi);
        } else if (nx > W - half) {
          nx = W - half;
          vxi = -Math.abs(vxi);
        }
        if (ny < half) {
          ny = half;
          vyi = Math.abs(vyi);
        } else if (ny > H - half) {
          ny = H - half;
          vyi = -Math.abs(vyi);
        }

        px[i] = nx;
        py[i] = ny;
        vx[i] = vxi;
        vy[i] = vyi;

        const speed = Math.hypot(vxi, vyi);
        const slotDist = Math.hypot(sxT - nx, slotY - ny);
        if (slotDist > 2 || speed >= 1) allNear = false;
        if (speed >= 0.5) allStill = false;
        if (slotDist > 2) anyDeparted = true;

        const el = items[i];
        if (el) {
          el.style.transform = `translate3d(${nx - half}px, ${ny - half}px, 0)`;
        }
      }

      // badge clears only once an avatar has actually left its slot (position,
      // not the speed-inclusive `allNear`) — not on every momentary
      // pointer-out, so a hover blip that never visibly moves the row can't
      // flicker the badge
      if (resolvedNow && anyDeparted) setResolved(false);

      if (wantSeek && seekT >= 1) {
        if (allNear) setResolved(true);
        if (allNear && allStill) {
          // snap exactly to slots, zero out, and genuinely sleep
          for (let i = 0; i < n; i++) {
            const sxT = slotX[i] ?? 0;
            px[i] = sxT;
            py[i] = slotY;
            vx[i] = 0;
            vy[i] = 0;
            const el = items[i];
            if (el) {
              el.style.transform = `translate3d(${sxT - half}px, ${slotY - half}px, 0)`;
            }
          }
          sleeping = true;
          last = 0;
          return;
        }
      }

      if (ioVisible && docVisible && !sleeping) {
        raf = requestAnimationFrame(step);
      }
    }

    const wake = () => {
      sleeping = false;
      if (raf === 0 && ioVisible && docVisible) {
        last = 0;
        raf = requestAnimationFrame(step);
      }
    };
    const pause = () => {
      if (raf !== 0) {
        cancelAnimationFrame(raf);
        raf = 0;
      }
      last = 0;
    };

    const onEnter = () => {
      hovered = true;
      wake();
    };
    const onLeave = () => {
      hovered = false;
      wake();
    };
    const onFocus = () => {
      // keyboard focus behaves like hover; pointer clicks don't lock the row
      focused = region.matches(":focus-visible");
      if (focused) wake();
    };
    const onBlur = () => {
      if (focused) {
        focused = false;
        wake();
      }
    };
    const onVis = () => {
      docVisible = !document.hidden;
      if (!docVisible) pause();
      else wake();
    };
    region.addEventListener("pointerenter", onEnter);
    region.addEventListener("pointerleave", onLeave);
    region.addEventListener("focus", onFocus);
    region.addEventListener("blur", onBlur);
    document.addEventListener("visibilitychange", onVis);

    // milling is the ambient default, so "sleep" also means: pause offscreen
    const io = new IntersectionObserver((entries) => {
      ioVisible = entries[0]?.isIntersecting ?? true;
      if (!ioVisible) pause();
      else wake();
    });
    io.observe(region);

    const ro = new ResizeObserver(() => {
      measure();
      seed();
      wake();
    });
    ro.observe(region);

    raf = requestAnimationFrame(step);

    return () => {
      if (raf !== 0) cancelAnimationFrame(raf);
      io.disconnect();
      ro.disconnect();
      region.removeEventListener("pointerenter", onEnter);
      region.removeEventListener("pointerleave", onLeave);
      region.removeEventListener("focus", onFocus);
      region.removeEventListener("blur", onBlur);
      document.removeEventListener("visibilitychange", onVis);
      detachHover.forEach((f) => f());
    };
  }, [members, avatarSize]);

  const label =
    ariaLabel ??
    `Team: ${members.map((m) => m.name).join(", ")}${
      overflow > 0 ? ` and ${overflow} more` : ""
    }`;

  return (
    <div
      ref={regionRef}
      tabIndex={0}
      role="group"
      aria-label={label}
      data-resolved="false"
      className={`relative w-full rounded-sm border border-border/60 bg-background/40 transition-colors hover:border-foreground/20 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent ${className}`}
    >
      {members.map((m, i) => (
        <div
          key={`${m.name}-${i}`}
          ref={(el) => {
            itemRefs.current[i] = el;
          }}
          className="absolute left-0 top-0 transition-opacity duration-300 will-change-transform"
          style={{ width: avatarSize, height: avatarSize, zIndex: i + 1, opacity: 0 }}
        >
          <div
            data-avatar
            className="flex h-full w-full select-none items-center justify-center rounded-full border border-border bg-surface font-mono text-[9px] font-medium text-ns-muted ring-2 ring-background transition-transform duration-200"
          >
            {m.src ? (
              <img
                src={m.src}
                alt=""
                className="h-full w-full rounded-full object-cover"
              />
            ) : (
              initialsOf(m)
            )}
          </div>
          <div
            data-tip
            aria-hidden
            className="pointer-events-none absolute bottom-full left-1/2 mb-1.5 -translate-x-1/2 whitespace-nowrap rounded-sm border border-border bg-surface px-1.5 py-0.5 font-mono text-[10px] text-foreground opacity-0 shadow-sm transition-opacity duration-150"
          >
            {m.name}
          </div>
        </div>
      ))}
      {overflow > 0 && (
        <div
          ref={badgeRef}
          className="absolute left-0 top-0 flex select-none items-center justify-center rounded-full border border-border bg-surface font-mono text-[10px] text-ns-muted ring-2 ring-background transition-opacity duration-200"
          style={{
            width: avatarSize,
            height: avatarSize,
            zIndex: members.length + 1,
            opacity: 0,
          }}
        >
          +{overflow}
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

// BackBearing — a sighting-compass bearing picker. A surveyor never trusts a
// single reading: the instrument always shows the fore bearing AND its
// reciprocal (+-180 deg) on the far side of the card, because a transposed
// digit only ever shows up as a back bearing that doesn't reconcile. So this
// is built like the real thing: one graduated card rotates under a FIXED
// lubber line, never a needle sweeping over a static rose. The lubber line,
// the fore readout (an always-editable Geist Mono input, not a popup) and
// the back readout never move — only the card turns, by -theta. Drag maps
// pointer atan2 to theta through a shortest signed delta (never the long way
// around), so mid-drag the card tracks the pointer 1:1; release hands the
// residual angular velocity to a second-order damped spring tuned just
// under critical (zeta ~0.85, matching confirm-dial-align's snap) so the
// card gives exactly one visible overshoot before it settles, the way a
// liquid-damped marine card behaves under real inertia. Direct-DOM refs
// drive the rotation every frame; React state carries only the committed
// theta. Zero deps, no canvas.

const K = 260; // spring stiffness, deg/s^2 per deg of displacement
const ZETA = 0.85; // just under critical -> exactly one overshoot
const C = 2 * ZETA * Math.sqrt(K);
const SLEEP_VEL = 0.5; // deg/s
const SLEEP_POS = 0.05; // deg

const CX = 120;
const CY = 120;
const R_OUTER = 104; // bezel radius
const R_TICK_OUTER = 100;
const R_MINOR_INNER = 94;
const R_MAJOR_INNER = 88;
const R_LETTER = 74;
const TICK_DEGREES = Array.from({ length: 180 }, (_, i) => i * 2);
const CARDINALS: { deg: number; letter: string }[] = [
  { deg: 0, letter: "N" },
  { deg: 90, letter: "E" },
  { deg: 180, letter: "S" },
  { deg: 270, letter: "W" },
];

function wrap360(v: number) {
  const w = v % 360;
  return w < 0 ? w + 360 : w;
}

function displayDeg(v: number) {
  let d = Math.round(v) % 360;
  if (d < 0) d += 360;
  return d;
}

function shortestDelta(from: number, to: number) {
  let d = (to - from) % 360;
  if (d > 180) d -= 360;
  if (d < -180) d += 360;
  return d;
}

// rounded to 3 decimals: Math.cos/sin can differ by a ULP between Node (SSR)
// and the browser's engine (CSR), which otherwise surfaces as a hydration
// mismatch in the serialized coordinate despite both being "correct"
function r3(n: number): number {
  return Math.round(n * 1000) / 1000;
}

function polar(r: number, deg: number) {
  const rad = (deg * Math.PI) / 180;
  return { x: r3(CX + r * Math.sin(rad)), y: r3(CY - r * Math.cos(rad)) };
}

function pad3(n: number) {
  return String(n).padStart(3, "0");
}

export interface BackBearingProps {
  /** controlled bearing in degrees true, 0-359.999; omit for uncontrolled */
  value?: number;
  /** uncontrolled initial bearing in degrees true */
  defaultValue?: number;
  /** fires on every committed change (drag, keys, or typed digits) */
  onValueChange?: (value: number) => void;
  /** accessible name for the instrument, also the input's label prefix */
  label?: string;
  /** dial diameter in px. Ticks are tuned for the 240 default. */
  size?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function BackBearing({
  value,
  defaultValue = 42,
  onValueChange,
  label = "Bearing",
  size = 240,
  className = "",
}: BackBearingProps) {
  const isControlled = value !== undefined;
  const [internal, setInternal] = useState(() => wrap360(defaultValue));
  const current = isControlled ? wrap360(value as number) : internal;
  const currentRef = useRef(current);
  currentRef.current = current;

  const foreDisp = displayDeg(current);
  const backDisp = displayDeg(current + 180);
  const valuetext = `bearing ${pad3(foreDisp)} degrees, back bearing ${pad3(backDisp)}`;

  const commitRef = useRef<(v: number) => void>(() => {});
  commitRef.current = (v: number) => {
    if (!isControlled) setInternal(v);
    onValueChange?.(v);
  };

  const regionRef = useRef<HTMLDivElement>(null);
  const cardGroupRef = useRef<SVGGElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const inputFocusedRef = useRef(false);
  const [inputText, setInputText] = useState(() => pad3(displayDeg(defaultValue)));

  // keep the typed-value input in sync with committed changes that came
  // from drag or arrow keys, but never fight the caret while the user types
  useEffect(() => {
    if (!inputFocusedRef.current) setInputText(pad3(foreDisp));
  }, [foreDisp]);

  const engineRef = useRef<{
    dragStart: (e: PointerEvent) => void;
    dragMove: (e: PointerEvent) => void;
    dragEnd: () => void;
    settleTo: (theta: number) => void;
  } | null>(null);

  // -- physics engine: direct DOM writes, React state only for the commit --
  useEffect(() => {
    const region = regionRef.current;
    const cardGroup = cardGroupRef.current;
    if (!region || !cardGroup) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    let committedRaw = currentRef.current; // continuous, unbounded
    let visualRaw = committedRaw;
    let vel = 0; // deg/s, drives the settle spring
    let dragging = false;
    let lastBearing = 0;
    let lastTime = 0;
    let raf = 0;
    let last = 0;

    const paint = (raw: number) => {
      cardGroup.setAttribute("transform", `rotate(${-raw} ${CX} ${CY})`);
    };
    paint(visualRaw);

    const loop = (now: number) => {
      const dt = last === 0 ? 1 / 60 : Math.min(0.05, (now - last) / 1000);
      last = now;
      const disp = visualRaw - committedRaw;
      vel += (-K * disp - C * vel) * dt;
      visualRaw += vel * dt;
      paint(visualRaw);
      if (Math.abs(vel) < SLEEP_VEL && Math.abs(visualRaw - committedRaw) < SLEEP_POS) {
        visualRaw = committedRaw;
        vel = 0;
        paint(visualRaw);
        raf = 0;
        last = 0;
        return;
      }
      raf = requestAnimationFrame(loop);
    };
    const wake = () => {
      if (!raf && !reduced) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const pointerBearing = (e: PointerEvent) => {
      const r = region.getBoundingClientRect();
      const dx = e.clientX - (r.left + r.width / 2);
      const dy = e.clientY - (r.top + r.height / 2);
      return wrap360((Math.atan2(dy, dx) * 180) / Math.PI + 90);
    };

    const dragStart = (e: PointerEvent) => {
      try {
        region.setPointerCapture(e.pointerId);
      } catch {
        // synthetic pointerIds (autoplay driver) may not resolve to a live
        // pointer — drag still works without capture
      }
      dragging = true;
      cancelAnimationFrame(raf);
      raf = 0;
      last = 0;
      vel = 0;
      lastBearing = pointerBearing(e);
      lastTime = performance.now();
    };

    const dragMove = (e: PointerEvent) => {
      if (!dragging) return;
      const pb = pointerBearing(e);
      const d = shortestDelta(lastBearing, pb);
      const t = performance.now();
      const mdt = Math.max(1e-3, (t - lastTime) / 1000);
      committedRaw += d;
      let theta = wrap360(committedRaw);
      if (e.shiftKey) {
        const snapped = wrap360(Math.round(theta / 22.5) * 22.5);
        committedRaw += shortestDelta(theta, snapped);
        theta = wrap360(committedRaw);
      }
      visualRaw = committedRaw;
      paint(visualRaw);
      vel = Math.max(-720, Math.min(720, 0.7 * vel + 0.3 * (d / mdt)));
      lastBearing = pb;
      lastTime = t;
      if (theta !== currentRef.current) commitRef.current(theta);
    };

    const dragEnd = () => {
      if (!dragging) return;
      dragging = false;
      if (reduced) {
        vel = 0;
        return;
      }
      // visualRaw already equals committedRaw (1:1 tracking while dragging);
      // the captured velocity alone drives the single overshoot on release
      wake();
    };

    const settleTo = (theta: number) => {
      const from = wrap360(committedRaw);
      committedRaw += shortestDelta(from, theta);
      if (reduced) {
        cancelAnimationFrame(raf);
        raf = 0;
        visualRaw = committedRaw;
        vel = 0;
        paint(visualRaw);
        return;
      }
      wake();
    };

    engineRef.current = { dragStart, dragMove, dragEnd, settleTo };

    return () => {
      cancelAnimationFrame(raf);
      engineRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const onKeyDown = (e: React.KeyboardEvent) => {
    let dir = 0;
    if (e.key === "ArrowRight" || e.key === "ArrowUp") dir = 1;
    else if (e.key === "ArrowLeft" || e.key === "ArrowDown") dir = -1;
    else return;
    e.preventDefault();
    const cur = currentRef.current;
    let next: number;
    if (e.shiftKey) {
      const n = cur / 22.5;
      const idx = dir > 0 ? Math.floor(n + 1e-6) + 1 : Math.ceil(n - 1e-6) - 1;
      next = wrap360(idx * 22.5);
    } else {
      next = wrap360(cur + dir);
    }
    engineRef.current?.settleTo(next);
    commitRef.current(next);
  };

  const onInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const digits = e.target.value.replace(/\D/g, "").slice(0, 3);
    setInputText(digits);
    if (digits === "") return;
    const parsed = parseInt(digits, 10);
    if (Number.isNaN(parsed)) return;
    const next = wrap360(parsed);
    if (next !== currentRef.current) {
      engineRef.current?.settleTo(next);
      commitRef.current(next);
    }
  };

  const onInputKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter") (e.target as HTMLInputElement).blur();
  };

  return (
    <div
      className={`flex w-full flex-col items-center gap-4 font-mono ${className}`}
    >
      <div className="flex items-baseline gap-1">
        <input
          ref={inputRef}
          type="text"
          inputMode="numeric"
          pattern="[0-9]*"
          value={inputText}
          onFocus={() => {
            inputFocusedRef.current = true;
          }}
          onBlur={() => {
            inputFocusedRef.current = false;
            setInputText(pad3(displayDeg(currentRef.current)));
          }}
          onChange={onInputChange}
          onKeyDown={onInputKeyDown}
          aria-label={`${label} degrees`}
          className="w-20 rounded-sm border border-border bg-surface px-2 py-1 text-center text-2xl tabular-nums text-foreground outline-none transition-colors duration-150 hover:border-ns-muted focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background"
        />
        <span aria-hidden className="text-2xl text-foreground">
          &deg;
        </span>
      </div>

      <div
        className="relative shrink-0"
        style={{ width: size, height: size }}
      >
        <div
          ref={regionRef}
          role="slider"
          tabIndex={0}
          aria-label={label}
          aria-valuemin={0}
          aria-valuemax={359}
          aria-valuenow={foreDisp}
          aria-valuetext={valuetext}
          onKeyDown={onKeyDown}
          onPointerDown={(e) => {
            regionRef.current?.focus({ preventScroll: true });
            engineRef.current?.dragStart(e.nativeEvent);
          }}
          onPointerMove={(e) => engineRef.current?.dragMove(e.nativeEvent)}
          onPointerUp={() => engineRef.current?.dragEnd()}
          onPointerCancel={() => engineRef.current?.dragEnd()}
          className="group absolute inset-0 cursor-grab touch-none select-none rounded-full outline-none active:cursor-grabbing focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background"
        >
          <svg
            viewBox="0 0 240 240"
            className="h-full w-full"
            aria-hidden
          >
            {/* bezel: fixed housing, never rotates */}
            <circle
              cx={CX}
              cy={CY}
              r={R_OUTER}
              className="fill-surface stroke-border transition-colors duration-150 group-hover:stroke-ns-muted"
              strokeWidth={1}
            />

            {/* graduated card: the ONLY thing that rotates, by -theta */}
            <g ref={cardGroupRef}>
              {TICK_DEGREES.map((deg) => {
                const major = deg % 10 === 0;
                const outer = polar(R_TICK_OUTER, deg);
                const inner = polar(
                  major ? R_MAJOR_INNER : R_MINOR_INNER,
                  deg
                );
                return (
                  <line
                    key={deg}
                    x1={outer.x}
                    y1={outer.y}
                    x2={inner.x}
                    y2={inner.y}
                    strokeWidth={major ? 2 : 1}
                    className={major ? "stroke-foreground" : "stroke-border"}
                  />
                );
              })}
              {CARDINALS.map(({ deg, letter }) => {
                const p = polar(R_LETTER, deg);
                return (
                  <text
                    key={letter}
                    x={p.x}
                    y={p.y}
                    textAnchor="middle"
                    dominantBaseline="central"
                    fontSize={18}
                    className="select-none fill-foreground font-mono font-semibold"
                  >
                    {letter}
                  </text>
                );
              })}
            </g>

            {/* lubber line — fixed, marks where the fore bearing is read */}
            <polygon
              points="120,16 113,3 127,3"
              className="fill-foreground"
            />
            {/* back-sight index — fixed, diametrically opposite the lubber
                line, marks where the reciprocal is read */}
            <polygon
              points="120,224 114,236 126,236"
              className="fill-ns-muted"
            />
            {/* pivot — fixed */}
            <circle cx={CX} cy={CY} r={3} className="fill-foreground" />
          </svg>
        </div>
      </div>

      <div
        aria-hidden
        className="flex items-baseline gap-1.5 text-ns-muted"
      >
        <span className="text-[10px] uppercase tracking-[0.2em]">
          back bearing
        </span>
        <span className="text-sm tabular-nums">
          {pad3(backDisp)}&deg;
        </span>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// CausticVeil — an ambient ASCII water-caustics background rendered in ink
// density. Three periodic wave grids, each rotated to its own angle and
// drifting at its own phase speed, are combined MULTIPLICATIVELY (not summed,
// which is background-ascii-plasma's technique) — sin(a) * sin(b) * sin(c) —
// and the product's distance from zero is sharpened by a power curve, which
// is exactly how two or three overlapping wave-fronts of light produce thin,
// bright, web-like caustic lines rather than smooth blobby luminance: the
// bright filaments trace where the waves cross in near-perfect
// anti/constructive alignment. The pointer acts as a LENS, not a stamp or an
// outward push: samples within its radius are pulled INWARD toward the
// cursor (the opposite sign of plasma's warp), so the caustic web visibly
// contracts and focuses toward the pointer like light converging through a
// magnifier, and relaxes back outward once the pointer leaves.
// ---------------------------------------------------------------------------

const RAMP = " .:-=+*#%@";
const ALPHA_BUCKETS = 6;
const LAYERS = [
  { angle: 0.0, freq: 0.07, speed: 0.22 },
  { angle: 1.15, freq: 0.09, speed: -0.17 },
  { angle: 2.3, freq: 0.05, speed: 0.13 },
] as const;
const CAUSTIC_POW = 5.5; // higher = thinner, sharper filaments
const LENS_TAU = 0.55; // s — lens strength relax time constant
const LENS_RADIUS = 10; // grid cells
const LENS_MAX = 3.4; // grid cells max inward pull
const DT_MAX = 0.05;

function caustic(x: number, y: number, t: number): number {
  let product = 1;
  for (let i = 0; i < LAYERS.length; i++) {
    const l = LAYERS[i]!;
    const rx = x * Math.cos(l.angle) + y * Math.sin(l.angle);
    product *= Math.sin(rx * l.freq + t * l.speed);
  }
  const v = Math.max(0, 1 - Math.abs(product));
  return Math.pow(v, CAUSTIC_POW);
}

export interface CausticVeilProps {
  /** grid cell size in px */
  cellSize?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function CausticVeil({ cellSize = 12, className = "" }: CausticVeilProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    let fg = "currentColor";
    let cellW = cellSize;
    let cellH = cellSize;
    let cols = 0;
    let rows = 0;
    let dpr = 1;
    let sized = false;
    let ready = false;
    let disposed = false;

    let charBuf = new Uint8Array(0);
    const bucketLists: number[][] = Array.from({ length: ALPHA_BUCKETS }, () => []);

    const readTokens = () => {
      fg = getComputedStyle(canvas).color;
    };

    const measureCell = (fontFamily: string) => {
      const off = document.createElement("canvas");
      const octx = off.getContext("2d");
      if (!octx) return;
      octx.font = `${cellSize}px ${fontFamily}`;
      cellW = Math.max(4, octx.measureText("MMMMMMMMMM").width / 10);
      cellH = cellSize;
    };

    const resize = () => {
      const { width, height } = canvas.getBoundingClientRect();
      if (width < 2 || height < 2) {
        sized = false;
        return;
      }
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const fontFamily = getComputedStyle(canvas).fontFamily;
      measureCell(fontFamily);
      ctx.font = `${cellSize}px ${fontFamily}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      cols = Math.max(4, Math.ceil(width / cellW));
      rows = Math.max(4, Math.ceil(height / cellH));
      charBuf = new Uint8Array(cols * rows);
      sized = true;
    };

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
        if (reduced) draw(0, -1e5, -1e5, 0);
      }, 150);
    };

    const draw = (t: number, lensGx: number, lensGy: number, lensStrength: number) => {
      if (!sized) return;
      const w = cols * cellW;
      const h = rows * cellH;
      ctx.clearRect(0, 0, w, h);

      for (let b = 0; b < ALPHA_BUCKETS; b++) bucketLists[b]!.length = 0;

      const r2 = LENS_RADIUS * LENS_RADIUS;
      let i = 0;
      for (let gy = 0; gy < rows; gy++) {
        for (let gx = 0; gx < cols; gx++, i++) {
          let sx = gx;
          let sy = gy;
          if (lensStrength > 0.01) {
            const dx = lensGx - gx;
            const dy = lensGy - gy;
            const d2 = dx * dx + dy * dy;
            if (d2 < r2 * 4) {
              const dist = Math.sqrt(d2) || 1e-4;
              const falloff = Math.exp(-d2 / r2);
              const pull = lensStrength * falloff * LENS_MAX;
              // INWARD: sample coordinate moves toward the lens center, the
              // opposite sign of an outward push — the field contracts here
              sx = gx + (dx / dist) * pull;
              sy = gy + (dy / dist) * pull;
            }
          }
          const v = caustic(sx, sy, t);
          const bucket = Math.min(ALPHA_BUCKETS - 1, Math.floor(v * ALPHA_BUCKETS));
          const ci = Math.floor(v * (RAMP.length - 1));
          charBuf[i] = ci;
          if (ci !== 0) bucketLists[bucket]!.push(i);
        }
      }

      ctx.fillStyle = fg;
      for (let b = 0; b < ALPHA_BUCKETS; b++) {
        const list = bucketLists[b]!;
        ctx.globalAlpha = 0.1 + (b / (ALPHA_BUCKETS - 1)) * 0.9;
        for (let k = 0; k < list.length; k++) {
          const idx = list[k]!;
          const gx = idx % cols;
          const gy = (idx - gx) / cols;
          ctx.fillText(
            RAMP[charBuf[idx]!]!,
            gx * cellW + cellW / 2,
            gy * cellH + cellH / 2
          );
        }
      }
      ctx.globalAlpha = 1;
    };

    // -- hot-path state -------------------------------------------------------
    let raf = 0;
    let last = 0;
    let t = 0;
    const lens = { gx: -1e5, gy: -1e5, has: false, strength: 0 };

    const loop = (now: number) => {
      const dt = last ? Math.min(DT_MAX, (now - last) / 1000) : 1 / 60;
      last = now;
      t += dt;
      const target = lens.has ? 1 : 0;
      lens.strength += (target - lens.strength) * Math.min(1, dt / LENS_TAU);
      draw(t, lens.gx, lens.gy, lens.strength);
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    const onPointerMove = (e: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      lens.gx = (e.clientX - rect.left) / cellW;
      lens.gy = (e.clientY - rect.top) / cellH;
      lens.has = true;
    };
    const onPointerLeave = () => {
      lens.has = false;
    };

    const onVis = () => {
      if (!document.hidden && !reduced && ready) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };
    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) draw(t, -1e5, -1e5, 0);
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    document.fonts.ready.then(() => {
      if (disposed) return;
      readTokens();
      resize();
      ready = true;
      if (reduced) {
        draw(0, -1e5, -1e5, 0);
      } else {
        raf = requestAnimationFrame(loop);
      }
    });

    window.addEventListener("resize", onResize);
    if (!reduced) {
      canvas.addEventListener("pointermove", onPointerMove);
      canvas.addEventListener("pointerleave", onPointerLeave);
    }
    document.addEventListener("visibilitychange", onVis);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      mo.disconnect();
      window.removeEventListener("resize", onResize);
      canvas.removeEventListener("pointermove", onPointerMove);
      canvas.removeEventListener("pointerleave", onPointerLeave);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [cellSize]);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden
      className={`block h-full w-full font-mono text-foreground ${className}`}
    />
  );
}

"use client";

import { useEffect, useRef } from "react";

const ASCII_RAMP = " .:-=+*#%@";
// 4x4 Bayer matrix, normalized 0..1
const BAYER = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5].map(
  (v) => (v + 0.5) / 16
);

type Mode = "ascii" | "dither" | "dot";

// cheap flowing value-noise, no deps
function noise(x: number, y: number, t: number): number {
  const v =
    Math.sin(x * 1.7 + t * 0.6) +
    Math.sin(y * 2.3 - t * 0.4) +
    Math.sin((x + y) * 1.1 + t * 0.25) +
    Math.sin(Math.hypot(x - 6, y - 4) * 1.9 - t * 0.7);
  return v / 8 + 0.5; // 0..1
}

export function AsciiDitherMedia({
  mode = "ascii",
  src,
  cellSize = 14,
  cursorRadius = 140,
  className = "",
}: {
  /** rendering style: "ascii" characters, "dither" pattern, or "dot" halftone */
  mode?: Mode;
  /** optional image URL; omit for the built-in animated noise field */
  src?: string;
  /** grid cell size in px */
  cellSize?: number;
  /** cursor-proximity resolve radius in px */
  cursorRadius?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    // glyph color from the surrounding theme; canvas bg stays transparent
    let fg = "";
    const readTokens = () => {
      fg = getComputedStyle(canvas).color;
    };
    readTokens();

    let cols = 0;
    let rows = 0;
    let dpr = 1;
    let imageLum: Float32Array | null = null;
    const cursor = { x: -1e4, y: -1e4, tx: -1e4, ty: -1e4 };
    let raf = 0;
    let t = 0;
    // bumped on every sampleImage() dispatch so a late-resolving onload from
    // a superseded resize (rapid window-resize) can detect it's stale and
    // bail instead of writing imageLum sized to an out-of-date cols/rows
    let sampleGen = 0;

    const resize = () => {
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      const { width, height } = canvas.getBoundingClientRect();
      canvas.width = width * dpr;
      canvas.height = height * dpr;
      cols = Math.ceil(width / cellSize);
      rows = Math.ceil(height / cellSize);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.font = `${cellSize * 0.85}px "GeistMono", ui-monospace, monospace`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      if (src) sampleImage();
    };

    // coalesce bursts of resize events (dragging a window edge fires dozens)
    // into one recompute + one image refetch/redecode
    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
      }, 150);
    };

    const sampleImage = () => {
      if (!src) return;
      const gen = ++sampleGen;
      const sampleCols = cols;
      const sampleRows = rows;
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => {
        if (gen !== sampleGen) return; // superseded by a newer resize/sample
        const buf = document.createElement("canvas");
        buf.width = sampleCols;
        buf.height = sampleRows;
        const bctx = buf.getContext("2d");
        if (!bctx) return;
        // cover-fit the image into the grid
        const scale = Math.max(sampleCols / img.width, sampleRows / img.height);
        const w = img.width * scale;
        const h = img.height * scale;
        bctx.drawImage(img, (sampleCols - w) / 2, (sampleRows - h) / 2, w, h);
        const data = bctx.getImageData(0, 0, sampleCols, sampleRows).data;
        const lum = new Float32Array(sampleCols * sampleRows);
        for (let i = 0; i < sampleCols * sampleRows; i++) {
          lum[i] =
            (0.2126 * data[i * 4] + 0.7152 * data[i * 4 + 1] + 0.0722 * data[i * 4 + 2]) / 255;
        }
        imageLum = lum;
        if (reduced) draw(); // static sources still need one paint
      };
      img.src = src;
    };

    const draw = () => {
      const { width, height } = canvas.getBoundingClientRect();
      ctx.clearRect(0, 0, width, height);
      ctx.fillStyle = fg;
      // ease cursor for a trailing resolve
      cursor.x += (cursor.tx - cursor.x) * 0.12;
      cursor.y += (cursor.ty - cursor.y) * 0.12;
      const r2 = cursorRadius * cursorRadius;

      for (let gy = 0; gy < rows; gy++) {
        for (let gx = 0; gx < cols; gx++) {
          // gamma deepens the noise floor: large areas go empty, crests pop.
          // x-advection makes the field travel, not just undulate in place
          let lum = imageLum
            ? imageLum[gy * cols + gx]
            : Math.pow(noise(gx * 0.35 + t * 0.22, gy * 0.35, t), 1.7);
          const px = gx * cellSize + cellSize / 2;
          const py = gy * cellSize + cellSize / 2;
          // gaussian-ish cursor boost
          const dx = px - cursor.x;
          const dy = py - cursor.y;
          const d2 = dx * dx + dy * dy;
          if (d2 < r2 * 4) lum = Math.min(1, lum + Math.exp(-d2 / r2) * 0.7);

          if (mode === "ascii") {
            const ch = ASCII_RAMP[Math.floor(lum * (ASCII_RAMP.length - 1))];
            if (ch !== " ") {
              ctx.globalAlpha = 0.25 + lum * 0.75;
              ctx.fillText(ch, px, py);
            }
          } else if (mode === "dither") {
            if (lum > BAYER[(gy % 4) * 4 + (gx % 4)]) {
              ctx.globalAlpha = 0.9;
              ctx.fillRect(px - 1, py - 1, 2, 2);
            }
          } else {
            const rad = (lum * cellSize) / 2.4;
            if (rad > 0.4) {
              ctx.globalAlpha = 0.3 + lum * 0.7;
              ctx.beginPath();
              ctx.arc(px, py, rad, 0, Math.PI * 2);
              ctx.fill();
            }
          }
        }
      }
      ctx.globalAlpha = 1;
    };

    const loop = () => {
      t += 0.028;
      draw();
      raf = requestAnimationFrame(loop);
    };

    const onPointer = (e: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      cursor.tx = e.clientX - rect.left;
      cursor.ty = e.clientY - rect.top;
    };
    const onLeave = () => {
      cursor.tx = -1e4;
      cursor.ty = -1e4;
    };

    // theme flip only swaps the .dark class — re-read the ink, no remount
    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) draw();
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    resize();
    window.addEventListener("resize", onResize);
    canvas.addEventListener("pointermove", onPointer);
    canvas.addEventListener("pointerleave", onLeave);
    if (reduced) {
      draw(); // single static frame
    } else {
      raf = requestAnimationFrame(loop);
    }
    return () => {
      cancelAnimationFrame(raf);
      mo.disconnect();
      if (resizeTimer) clearTimeout(resizeTimer);
      window.removeEventListener("resize", onResize);
      canvas.removeEventListener("pointermove", onPointer);
      canvas.removeEventListener("pointerleave", onLeave);
    };
  }, [mode, src, cellSize, cursorRadius]);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden
      className={`block h-full w-full text-foreground ${className}`}
    />
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// DomainWalls — an ambient ASCII background running a real 2D Ising model on
// the glyph grid and inking ONLY the domain walls: the bonds where an up-spin
// region meets a down-spin region. Domain interiors, which are the
// overwhelming majority of the lattice, draw absolutely nothing, so the frame
// reads as a sparse network of rough hairlines on empty ground — a Kerr
// micrograph of magnetic domains, or grain boundaries in cooled metal.
//
// Temperature is deliberately 0.92 * Tc (Tc = 2/ln(1+sqrt(2)) = 2.269...).
// Below that walls freeze straight and stop moving; at Tc the whole lattice
// becomes fractal mush. At 0.92 * Tc walls are simultaneously sharp AND
// mobile, which is the only regime where this reads as calm-but-alive.
//
// The pointer is not a brush. It applies a LOCAL MAGNETIC FIELD biasing spins
// toward +1; a uniform field thermodynamically suppresses the minority phase,
// so walls under the cursor retract and annihilate on their own and a clean
// circular clearing tracks the pointer. On leave the field relaxes and
// thermal fluctuation plus the periodic re-seed nucleates domains back into
// the cleared patch over about two seconds.
// ---------------------------------------------------------------------------

const GLYPHS = ["", "|", "-", "+"] as const; // by broken-bond kind
const ALPHA_BUCKETS = 6;

const J = 1; // ferromagnetic coupling
const SWEEP_FRACTION = 0.9; // flip attempts per frame, as a fraction of sites
const LUM_BASE = 0.35; // luminance of a perfectly straight wall cell
const LUM_PER_NEIGHBOUR = 0.09; // added per inked cell in the 8-ring
const RESEED_PERIOD = 3.0; // s between domain nucleations
const RESEED_JITTER = 0.6; // s +- on that period
const RESEED_RADIUS = 6; // cells
const FIELD_MAX = 1.4; // peak H under the pointer
const FIELD_SIGMA = 7; // cells — gaussian width of the field
const FIELD_CUTOFF2 = 24 * 24; // cells^2 beyond which H is numerically nil
const FIELD_TAU = 0.6; // s — field ease in/out time constant
const EQUILIBRATE_SWEEPS = 120; // so the first painted frame is already coarse
const REDUCED_SWEEPS = 400; // static frame equilibration
const DT_MAX = 0.05;

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export interface DomainWallsProps {
  /** grid cell size in px — this is also the Ising lattice spacing */
  cellSize?: number;
  /** Ising temperature in units of J/k_B; Tc is 2.269, default sits at 0.92 Tc */
  temperature?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function DomainWalls({
  cellSize = 12,
  temperature = 2.09,
  className = "",
}: DomainWallsProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    const T = Math.max(0.4, temperature);
    const rand = mulberry32(0x15196e);

    let fg = "currentColor";
    let cellW = cellSize;
    let cellH = cellSize;
    let cols = 0;
    let rows = 0;
    let n = 0;
    let dpr = 1;
    let sized = false;
    let ready = false;
    let disposed = false;

    let spins = new Int8Array(0);
    let glyphBuf = new Uint8Array(0);
    const bucketLists: number[][] = Array.from(
      { length: ALPHA_BUCKETS },
      () => []
    );

    // Only five values of dE are reachable at H = 0 (neighbour sum is one of
    // -4,-2,0,2,4 and s is +-1), so the Boltzmann factor is a lookup and
    // Math.exp never runs in the hot loop except for the few hundred cells
    // actually inside the pointer's field.
    const expTable = new Float64Array(5);
    for (let k = 0; k < 5; k++) expTable[k] = Math.exp(-(k * 4 - 8) / T);

    const readTokens = () => {
      fg = getComputedStyle(canvas).color;
    };

    const measureCell = (fontFamily: string) => {
      const off = document.createElement("canvas");
      const octx = off.getContext("2d");
      if (!octx) return;
      octx.font = `${cellSize}px ${fontFamily}`;
      cellW = Math.max(4, octx.measureText("MMMMMMMMMM").width / 10);
      cellH = cellSize;
    };

    const seedLattice = () => {
      spins = new Int8Array(n);
      for (let i = 0; i < n; i++) spins[i] = rand() < 0.5 ? 1 : -1;
    };

    /** Nucleate a fresh single-sign domain. Without this, curvature-driven
     *  coarsening eventually swallows every wall and the frame goes blank. */
    const reseed = () => {
      const cx = (rand() * cols) | 0;
      const cy = (rand() * rows) | 0;
      const sign = rand() < 0.5 ? 1 : -1;
      const r2 = RESEED_RADIUS * RESEED_RADIUS;
      for (let dy = -RESEED_RADIUS; dy <= RESEED_RADIUS; dy++) {
        for (let dx = -RESEED_RADIUS; dx <= RESEED_RADIUS; dx++) {
          if (dx * dx + dy * dy > r2) continue;
          const gx = (((cx + dx) % cols) + cols) % cols;
          const gy = (((cy + dy) % rows) + rows) % rows;
          spins[gy * cols + gx] = sign;
        }
      }
    };

    /** Metropolis single-spin-flip, periodic boundaries. */
    const step = (attempts: number, fx: number, fy: number, strength: number) => {
      const fieldOn = strength > 0.01;
      const amp = FIELD_MAX * strength;
      for (let a = 0; a < attempts; a++) {
        const gx = (rand() * cols) | 0;
        const gy = (rand() * rows) | 0;
        const i = gy * cols + gx;
        const s = spins[i]!;
        const rowOff = gy * cols;
        const xl = gx > 0 ? gx - 1 : cols - 1;
        const xr = gx < cols - 1 ? gx + 1 : 0;
        const yu = gy > 0 ? gy - 1 : rows - 1;
        const yd = gy < rows - 1 ? gy + 1 : 0;
        const sum =
          spins[rowOff + xl]! +
          spins[rowOff + xr]! +
          spins[yu * cols + gx]! +
          spins[yd * cols + gx]!;
        const dEj = 2 * J * s * sum;

        if (fieldOn) {
          const dx = gx - fx;
          const dy = gy - fy;
          const d2 = dx * dx + dy * dy;
          if (d2 < FIELD_CUTOFF2) {
            // E includes -H*s, so flipping costs +2*H*s: a positive H makes
            // flipping a down spin up cheap and the reverse expensive.
            const h = amp * Math.exp(-d2 / (2 * FIELD_SIGMA * FIELD_SIGMA));
            const dE = dEj + 2 * h * s;
            if (dE <= 0 || rand() < Math.exp(-dE / T)) spins[i] = -s as -1 | 1;
            continue;
          }
        }
        if (dEj <= 0 || rand() < expTable[(dEj + 8) >> 2]!) {
          spins[i] = -s as -1 | 1;
        }
      }
    };

    const resize = () => {
      const { width, height } = canvas.getBoundingClientRect();
      if (width < 2 || height < 2) {
        sized = false;
        return;
      }
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const fontFamily = getComputedStyle(canvas).fontFamily;
      measureCell(fontFamily);
      ctx.font = `${cellSize}px ${fontFamily}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      cols = Math.max(8, Math.ceil(width / cellW));
      rows = Math.max(8, Math.ceil(height / cellH));
      n = cols * rows;
      glyphBuf = new Uint8Array(n);
      seedLattice();
      const warm = reduced ? REDUCED_SWEEPS : EQUILIBRATE_SWEEPS;
      const perReseed = Math.max(1, Math.round(warm / 3));
      for (let k = 0; k < warm; k++) {
        step(n, 0, 0, 0);
        if (k > 0 && k % perReseed === 0) reseed();
      }
      sized = true;
    };

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
        if (reduced) draw();
      }, 150);
    };

    const draw = () => {
      if (!sized) return;
      ctx.clearRect(0, 0, cols * cellW, rows * cellH);
      for (let b = 0; b < ALPHA_BUCKETS; b++) bucketLists[b]!.length = 0;

      // Pass one — a cell inks only if its right OR down bond is broken. Which
      // bond broke picks the glyph, so the ink is genuine line-work along the
      // wall rather than a stipple.
      let i = 0;
      for (let gy = 0; gy < rows; gy++) {
        const rowOff = gy * cols;
        const downOff = (gy < rows - 1 ? gy + 1 : 0) * cols;
        for (let gx = 0; gx < cols; gx++, i++) {
          const s = spins[i]!;
          const right = s !== spins[rowOff + (gx < cols - 1 ? gx + 1 : 0)]!;
          const down = s !== spins[downOff + gx]!;
          glyphBuf[i] = right ? (down ? 3 : 1) : down ? 2 : 0;
        }
      }

      // Luminance is wall CURVATURE: how many of the 8 surrounding cells also
      // sit on a wall. A kinked, high-energy stretch reads brighter than a
      // straight one, which is exactly what costs energy.
      i = 0;
      for (let gy = 0; gy < rows; gy++) {
        const yu = (gy > 0 ? gy - 1 : rows - 1) * cols;
        const ym = gy * cols;
        const yd = (gy < rows - 1 ? gy + 1 : 0) * cols;
        for (let gx = 0; gx < cols; gx++, i++) {
          if (glyphBuf[i] === 0) continue;
          const xl = gx > 0 ? gx - 1 : cols - 1;
          const xr = gx < cols - 1 ? gx + 1 : 0;
          let c = 0;
          if (glyphBuf[yu + xl]) c++;
          if (glyphBuf[yu + gx]) c++;
          if (glyphBuf[yu + xr]) c++;
          if (glyphBuf[ym + xl]) c++;
          if (glyphBuf[ym + xr]) c++;
          if (glyphBuf[yd + xl]) c++;
          if (glyphBuf[yd + gx]) c++;
          if (glyphBuf[yd + xr]) c++;
          const lum = Math.min(1, LUM_BASE + LUM_PER_NEIGHBOUR * c);
          const b = Math.min(
            ALPHA_BUCKETS - 1,
            Math.floor(((lum - LUM_BASE) / (1 - LUM_BASE)) * ALPHA_BUCKETS)
          );
          bucketLists[b]!.push(i);
        }
      }

      // Pass two — one globalAlpha write per bucket, never per cell.
      ctx.fillStyle = fg;
      for (let b = 0; b < ALPHA_BUCKETS; b++) {
        const list = bucketLists[b]!;
        if (list.length === 0) continue;
        ctx.globalAlpha =
          LUM_BASE + ((b + 0.5) / ALPHA_BUCKETS) * (1 - LUM_BASE);
        for (let k = 0; k < list.length; k++) {
          const idx = list[k]!;
          const gx = idx % cols;
          const gy = (idx - gx) / cols;
          ctx.fillText(
            GLYPHS[glyphBuf[idx]!]!,
            gx * cellW + cellW / 2,
            gy * cellH + cellH / 2
          );
        }
      }
      ctx.globalAlpha = 1;
    };

    // -- hot-path state -------------------------------------------------------
    let raf = 0;
    let last = 0;
    let reseedIn = RESEED_PERIOD;
    const field = { gx: 0, gy: 0, has: false, strength: 0 };

    const loop = (now: number) => {
      const dt = last ? Math.min(DT_MAX, (now - last) / 1000) : 1 / 60;
      last = now;

      const target = field.has ? 1 : 0;
      field.strength += (target - field.strength) * Math.min(1, dt / FIELD_TAU);

      if (sized) {
        reseedIn -= dt;
        if (reseedIn <= 0) {
          reseed();
          reseedIn = RESEED_PERIOD + (rand() * 2 - 1) * RESEED_JITTER;
        }
        step(
          Math.round(SWEEP_FRACTION * n),
          field.gx,
          field.gy,
          field.strength
        );
        draw();
      }
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    const onPointerMove = (e: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      field.gx = (e.clientX - rect.left) / cellW;
      field.gy = (e.clientY - rect.top) / cellH;
      field.has = true;
    };
    const onPointerLeave = () => {
      field.has = false;
    };

    const onVis = () => {
      if (!document.hidden && !reduced && ready) {
        // A frame requested just before the tab hid is still queued and fires
        // on return; without this cancel it would coexist with the one below
        // and the lattice would evolve at double rate forever.
        cancelAnimationFrame(raf);
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) draw();
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    document.fonts.ready.then(() => {
      if (disposed) return;
      readTokens();
      resize();
      ready = true;
      if (reduced) {
        draw();
      } else {
        raf = requestAnimationFrame(loop);
      }
    });

    window.addEventListener("resize", onResize);
    if (!reduced) {
      canvas.addEventListener("pointermove", onPointerMove);
      canvas.addEventListener("pointerleave", onPointerLeave);
    }
    document.addEventListener("visibilitychange", onVis);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      mo.disconnect();
      window.removeEventListener("resize", onResize);
      canvas.removeEventListener("pointermove", onPointerMove);
      canvas.removeEventListener("pointerleave", onPointerLeave);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [cellSize, temperature]);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden
      className={`block h-full w-full font-mono text-foreground ${className}`}
    />
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// Slipstream — an ambient ASCII flow-field background. A 2D value-noise
// potential is sampled on a coarse sub-grid and its CURL (via central finite
// differences, the standard incompressible-flow trick: vx = dPotential/dy,
// vy = -dPotential/dx) is drawn as a faint, static direction glyph per cell —
// '-' / '|' / '/' / '\' chosen from the local velocity angle — giving the
// field a legible shape even before anything moves. A fixed set of tracer
// PARTICLES then genuinely rides that same time-evolving field: each step
// its own continuous (x, y) position is advanced by the curl velocity at
// that point plus time, not snapped to a cell until render, and its last few
// positions are kept in an explicit ring buffer and redrawn every frame at
// falling alpha — a real trail of history, not a decaying persistent grid
// (that's background-ascii-wake's mechanic; this one never accumulates
// state per cell). Direction glyph + trail-alpha together are what encode
// "which way, how fast" per particle. The pointer adds a local VORTEX: a
// tangential velocity term around the cursor, falloff by distance, whose
// strength ramps in while the pointer is over the field and eases back out
// when it leaves — particles visibly swirl around the cursor rather than
// being repelled or painted.
// ---------------------------------------------------------------------------

const DIR_CHARS = ["-", "|", "/", "\\"] as const;
const NOISE_FREQ = 0.05; // spatial frequency of the potential field
const FIELD_SPEED = 0.06; // t units/s the potential drifts
const CURL_SCALE = 46; // maps potential gradient to px/s particle speed
const AMBIENT_STEP = 3; // ambient direction glyph sampled every N cells
const AMBIENT_ALPHA_MAX = 0.55;
const AMBIENT_CUTOFF = 0.4; // below this normalized speed, draw nothing — real negative space
const PARTICLE_COUNT_MIN = 60;
const PARTICLE_COUNT_MAX = 130;
const TRAIL_LEN = 4;
const VORTEX_RADIUS = 120; // px
const VORTEX_STRENGTH = 2.4; // px/s per unit falloff, at full ramp
const VORTEX_EASE = 0.06;
const DT_MAX = 0.05;

function hash2(ix: number, iy: number, seed: number): number {
  const s = Math.sin(ix * 127.1 + iy * 311.7 + seed * 74.7) * 43758.5453;
  return s - Math.floor(s);
}

function smooth(t: number) {
  return t * t * (3 - 2 * t);
}

// bilinear value noise, [0, 1)
function noise2D(x: number, y: number, seed: number): number {
  const x0 = Math.floor(x);
  const y0 = Math.floor(y);
  const tx = smooth(x - x0);
  const ty = smooth(y - y0);
  const a = hash2(x0, y0, seed);
  const b = hash2(x0 + 1, y0, seed);
  const c = hash2(x0, y0 + 1, seed);
  const d = hash2(x0 + 1, y0 + 1, seed);
  const top = a + (b - a) * tx;
  const bot = c + (d - c) * tx;
  return top + (bot - top) * ty;
}

function potential(x: number, y: number, t: number): number {
  const n1 = noise2D(x * NOISE_FREQ, y * NOISE_FREQ + t, 11.3);
  const n2 = noise2D(x * NOISE_FREQ * 2.3 - t * 0.6, y * NOISE_FREQ * 2.3, 47.9);
  return n1 * 0.7 + n2 * 0.3;
}

// curl of the scalar potential field -> divergence-free velocity
function curlVel(x: number, y: number, t: number, eps: number): [number, number] {
  const py1 = potential(x, y + eps, t);
  const py0 = potential(x, y - eps, t);
  const px1 = potential(x + eps, y, t);
  const px0 = potential(x - eps, y, t);
  const vx = ((py1 - py0) / (2 * eps)) * CURL_SCALE;
  const vy = -((px1 - px0) / (2 * eps)) * CURL_SCALE;
  return [vx, vy];
}

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function dirChar(vx: number, vy: number): string {
  const angle = Math.atan2(vy, vx);
  // fold to [0, PI) then bucket into 4 slopes: -, /, |, \
  let a = angle % Math.PI;
  if (a < 0) a += Math.PI;
  const idx = Math.round(a / (Math.PI / 4)) % 4;
  return DIR_CHARS[idx]!;
}

export interface SlipstreamProps {
  /** grid cell size in px */
  cellSize?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function Slipstream({ cellSize = 14, className = "" }: SlipstreamProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    let fg = "currentColor";
    let muted = "currentColor";
    let cellW = cellSize;
    let cellH = cellSize;
    let cols = 0;
    let rows = 0;
    let width = 0;
    let height = 0;
    let dpr = 1;
    let sized = false;
    let ready = false;
    let disposed = false;

    let particleCount = 0;
    let px: Float32Array = new Float32Array(0);
    let py: Float32Array = new Float32Array(0);
    // ring buffer of the last TRAIL_LEN positions, flattened [p*TRAIL_LEN + slot]
    let histX: Float32Array = new Float32Array(0);
    let histY: Float32Array = new Float32Array(0);
    let histLive: Int32Array = new Int32Array(0); // how many history slots are filled
    let histHead: Int32Array = new Int32Array(0); // ring write cursor
    let velX: Float32Array = new Float32Array(0);
    let velY: Float32Array = new Float32Array(0);

    const readTokens = () => {
      fg = getComputedStyle(canvas).color;
      muted =
        getComputedStyle(document.documentElement)
          .getPropertyValue("--ns-muted")
          .trim() || fg;
    };

    const measureCell = (fontFamily: string) => {
      const off = document.createElement("canvas");
      const octx = off.getContext("2d");
      if (!octx) return;
      octx.font = `${cellSize}px ${fontFamily}`;
      cellW = Math.max(4, octx.measureText("MMMMMMMMMM").width / 10);
      cellH = cellSize;
    };

    const seedParticles = () => {
      const rand = mulberry32(0xf1044);
      particleCount = Math.max(
        PARTICLE_COUNT_MIN,
        Math.min(PARTICLE_COUNT_MAX, Math.floor(cols * rows * 0.045))
      );
      px = new Float32Array(particleCount);
      py = new Float32Array(particleCount);
      histX = new Float32Array(particleCount * TRAIL_LEN);
      histY = new Float32Array(particleCount * TRAIL_LEN);
      histLive = new Int32Array(particleCount);
      histHead = new Int32Array(particleCount);
      velX = new Float32Array(particleCount);
      velY = new Float32Array(particleCount);
      for (let i = 0; i < particleCount; i++) {
        const x = rand() * width;
        const y = rand() * height;
        px[i] = x;
        py[i] = y;
        for (let s = 0; s < TRAIL_LEN; s++) {
          histX[i * TRAIL_LEN + s] = x;
          histY[i * TRAIL_LEN + s] = y;
        }
      }
    };

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      if (width < 2 || height < 2) {
        sized = false;
        return;
      }
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const fontFamily = getComputedStyle(canvas).fontFamily;
      measureCell(fontFamily);
      ctx.font = `${cellSize}px ${fontFamily}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";

      cols = Math.max(4, Math.ceil(width / cellW));
      rows = Math.max(4, Math.ceil(height / cellH));
      seedParticles();
      sized = true;
    };

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
        if (reduced) draw(0);
      }, 150);
    };

    const drawAmbient = (t: number) => {
      ctx.fillStyle = muted;
      // Every ambient sample used to draw at the same fixed faint alpha
      // regardless of how fast the field moved there — the whole background
      // read as an even sprinkle of dashes with no shape and no negative
      // space. A fixed CURL_SCALE-based reference speed turned out to be the
      // wrong normalizer too: this potential field's gradient magnitude is
      // fairly uniform canvas-wide, so nearly every cell landed on the same
      // side of any fixed cutoff and the fix was invisible. Normalizing
      // against THIS FRAME's own actual max speed (two passes: measure, then
      // draw) guarantees real contrast regardless of the field's absolute
      // scale — cells at the local max always reach full brightness, cells
      // near the local min always fall below the cutoff into true negative
      // space, same as the frame-relative sharpening background-ascii-caustics
      // uses.
      // Single pass: curlVel is 4 potential() calls (8 noise2D) per sample —
      // computing it twice per cell every frame forever was a real perf
      // regression, not just inelegant. Cache vx/vy/speed once, normalize
      // against the max found in this same pass.
      const vxs: number[] = [];
      const vys: number[] = [];
      const speeds: number[] = [];
      let maxSpeed = 1e-6;
      for (let gy = 0; gy < rows; gy += AMBIENT_STEP) {
        for (let gx = 0; gx < cols; gx += AMBIENT_STEP) {
          const [vx, vy] = curlVel(gx * cellW, gy * cellH, t, 1.5);
          const speed = Math.hypot(vx, vy);
          vxs.push(vx);
          vys.push(vy);
          speeds.push(speed);
          if (speed > maxSpeed) maxSpeed = speed;
        }
      }
      let i = 0;
      for (let gy = 0; gy < rows; gy += AMBIENT_STEP) {
        for (let gx = 0; gx < cols; gx += AMBIENT_STEP) {
          const norm = speeds[i]! / maxSpeed;
          if (norm >= AMBIENT_CUTOFF) {
            const shaped = Math.pow((norm - AMBIENT_CUTOFF) / (1 - AMBIENT_CUTOFF), 2.2);
            ctx.globalAlpha = shaped * AMBIENT_ALPHA_MAX;
            const ch = dirChar(vxs[i]!, vys[i]!);
            ctx.fillText(ch, gx * cellW + cellW / 2, gy * cellH + cellH / 2);
          }
          i++;
        }
      }
    };

    const draw = (t: number) => {
      if (!sized) return;
      ctx.clearRect(0, 0, width, height);
      drawAmbient(t);

      ctx.fillStyle = fg;
      for (let i = 0; i < particleCount; i++) {
        const ch = dirChar(velX[i]!, velY[i]!);
        const live = histLive[i]!;
        // A particle sitting in a slow patch of the field used to draw at
        // the exact same brightness as one riding the fastest current —
        // every trail was equally bright regardless of how much it was
        // actually moving, which is most of why the whole canvas read as
        // one uniform density of dashes. Riding the same curl speed the
        // vortex/advection math already computes, a slow particle now fades
        // toward the background instead of matching the fast ones 1:1.
        const speedNorm = Math.min(1, Math.hypot(velX[i]!, velY[i]!) / (CURL_SCALE * 0.6));
        const speedGain = 0.35 + 0.65 * speedNorm;
        for (let s = 0; s < live; s++) {
          const slot = (histHead[i]! - s + TRAIL_LEN * 4) % TRAIL_LEN;
          const alpha = (1 - s / TRAIL_LEN) * speedGain;
          if (alpha <= 0.05) continue;
          ctx.globalAlpha = alpha;
          ctx.fillText(
            ch,
            histX[i * TRAIL_LEN + slot]!,
            histY[i * TRAIL_LEN + slot]!
          );
        }
      }
      ctx.globalAlpha = 1;
    };

    // -- hot-path state -------------------------------------------------------
    let raf = 0;
    let last = 0;
    let t = 0;
    const vortex = { x: -1e5, y: -1e5, has: false, strength: 0 };

    const step = (dt: number) => {
      t += dt * FIELD_SPEED;
      vortex.strength += ((vortex.has ? 1 : 0) - vortex.strength) * VORTEX_EASE;

      for (let i = 0; i < particleCount; i++) {
        let x = px[i]!;
        let y = py[i]!;
        const [vx0, vy0] = curlVel(x, y, t, 1.5 * cellW);
        let vx = vx0;
        let vy = vy0;
        if (vortex.strength > 0.01) {
          const ddx = x - vortex.x;
          const ddy = y - vortex.y;
          const d2 = ddx * ddx + ddy * ddy;
          if (d2 < VORTEX_RADIUS * VORTEX_RADIUS) {
            const dist = Math.sqrt(d2) || 1e-3;
            const falloff = 1 - dist / VORTEX_RADIUS;
            // tangential (perpendicular) push -> a swirl, not a repel
            const tx = -ddy / dist;
            const ty = ddx / dist;
            const mag = falloff * VORTEX_STRENGTH * vortex.strength * 20;
            vx += tx * mag;
            vy += ty * mag;
          }
        }
        x += vx * dt;
        y += vy * dt;
        if (x < 0) x += width;
        if (x >= width) x -= width;
        if (y < 0) y += height;
        if (y >= height) y -= height;
        px[i] = x;
        py[i] = y;
        velX[i] = vx;
        velY[i] = vy;

        const head = (histHead[i]! + 1) % TRAIL_LEN;
        histHead[i] = head;
        histX[i * TRAIL_LEN + head] = x;
        histY[i * TRAIL_LEN + head] = y;
        if (histLive[i]! < TRAIL_LEN) histLive[i]! += 1;
      }
    };

    const loop = (now: number) => {
      const dt = last ? Math.min(DT_MAX, (now - last) / 1000) : 1 / 60;
      last = now;
      step(dt);
      draw(t);
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    const onPointerMove = (e: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      vortex.x = e.clientX - rect.left;
      vortex.y = e.clientY - rect.top;
      vortex.has = true;
    };
    const onPointerLeave = () => {
      vortex.has = false;
    };

    const onVis = () => {
      if (!document.hidden && !reduced && ready) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };
    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) draw(t);
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    document.fonts.ready.then(() => {
      if (disposed) return;
      readTokens();
      resize();
      ready = true;
      if (reduced) {
        draw(0);
      } else {
        raf = requestAnimationFrame(loop);
      }
    });

    window.addEventListener("resize", onResize);
    if (!reduced) {
      canvas.addEventListener("pointermove", onPointerMove);
      canvas.addEventListener("pointerleave", onPointerLeave);
    }
    document.addEventListener("visibilitychange", onVis);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      mo.disconnect();
      window.removeEventListener("resize", onResize);
      canvas.removeEventListener("pointermove", onPointerMove);
      canvas.removeEventListener("pointerleave", onPointerLeave);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [cellSize]);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden
      className={`block h-full w-full font-mono text-foreground ${className}`}
    />
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// ForceChains — an ambient ASCII background of a granular packing under load.
//
// A static disc packing is built once per resize (seeded Poisson-disk
// sampling, polydisperse radii, a fixed contact graph). Nothing is ever
// re-packed, and no collisions are solved — the only thing that changes per
// frame is how the load DISTRIBUTES through that fixed contact network.
//
// Load enters at the top boundary, each grain adds its own weight, and every
// grain passes what it carries down to the grains beneath it in proportion to
// how vertical each contact normal is. That is the q-model of granular stress
// transmission: a multiplicative cascade down a disordered network, whose
// steady state is a heavy-tailed force distribution. Only the small minority
// of contacts carrying well above the mean force is inked, so what is drawn is
// the load-bearing skeleton — thin branching chains threading downward — while
// the ~88% of "spectator" grains carrying nothing draw absolutely nothing.
// That sparsity is the physics, not a stylistic filter: it is what a
// photoelastic sand experiment actually looks like.
//
// The pointer is an INDENTER pressed into the pile. Its point load is injected
// at the nearest grain and the relaxation redistributes it, so a bright stress
// cone fans downward and outward at roughly the packing's 45-degree cone
// angle, and unrelated chains DIM because the mean force rises and they lose
// their share of the threshold. On leave the load eases back to zero and the
// gravity-only skeleton returns.
// ---------------------------------------------------------------------------

/** ' .:-=+*#%@' at 0..9, then the four chain-body slope glyphs at 10..13. */
const GLYPHS = " .:-=+*#%@-|/\\";
const SLOPE_BASE = 10;
const ALPHA_BUCKETS = 6;

// -- packing ---------------------------------------------------------------
/** min-spacing solved from the target count: R = sqrt(area / (n * K)). */
const SPACING_K = 1.57;
/** min spacing expressed in grain radii — 1.9 * grainR. */
const SPACING_IN_RADII = 1.9;
/** radius polydispersity; a monodisperse packing crystallises into a hex lattice. */
const R_JITTER_MIN = 0.85;
const R_JITTER_SPAN = 0.3;
/** Bridson annulus width. Narrow (R..1.3R) packs jammed rather than loose. */
const ANNULUS = 0.3;
const CANDIDATES = 30;
/** contact where centre distance < (r_i + r_j) * TOL. Tuned for z ~= 4. */
const CONTACT_TOL = 1.35;

// -- load ------------------------------------------------------------------
/** depth of the top boundary row, in min-spacings. */
const TOP_BAND = 1.6;
/** total flux injected at the top, split across the top row — viewport-independent. */
const TOP_FLUX = 3.6;
/** total self-weight of the pile, split across every grain. */
const TOTAL_WEIGHT = 5.9;
/** point load of the indenter, comparable to the whole ambient flux. */
const INDENT_LOAD = 3.2;
const INDENT_TAU = 0.5; // s

// -- sparsity --------------------------------------------------------------
/** ink only contacts above this multiple of the mean force. ~12% survive. */
const CHAIN_THRESHOLD = 1.9;
/** width of the luminance ramp above the threshold, in units of the mean. */
const CHAIN_RANGE = 2.6;
const CHAIN_GAMMA = 0.8;
/** below this luminance a contact is drawn with the density ramp, not a slope glyph. */
const FAINT_CUTOFF = 0.34;

const DT_MAX = 0.05;

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

interface Packing {
  n: number;
  /** grain centres and radii, sorted top-to-bottom (depth order). */
  px: Float32Array;
  py: Float32Array;
  pr: Float32Array;
  /** contact edges, always directed from the upper grain to the lower one. */
  ea: Int32Array;
  eb: Int32Array;
  /** vertical component of each contact normal, always >= 0 by construction. */
  eny: Float32Array;
  /** CSR-style offsets into ea/eb for each grain's outgoing contacts. */
  off: Int32Array;
  /** sum of eny over each grain's outgoing contacts; 0 = nothing beneath it. */
  sumny: Float32Array;
  /** indices of the top-boundary grains and the column each one sits in. */
  topIdx: Int32Array;
  topCol: Int32Array;
  spacing: number;
  f: Float32Array;
  inF: Float32Array;
}

function buildPacking(w: number, h: number, count: number): Packing {
  const rnd = mulberry32(0x9e3779b9);
  const spacing = Math.max(6, Math.sqrt((w * h) / (count * SPACING_K)));
  const grainR = spacing / SPACING_IN_RADII;

  // --- seeded Poisson-disk sampling (Bridson) ---
  const cell = spacing / Math.SQRT2;
  const gw = Math.ceil(w / cell) + 1;
  const gh = Math.ceil(h / cell) + 1;
  const grid = new Int32Array(gw * gh).fill(-1);
  const xs: number[] = [];
  const ys: number[] = [];
  const rs: number[] = [];
  const active: number[] = [];
  const push = (x: number, y: number) => {
    const i = xs.length;
    xs.push(x);
    ys.push(y);
    rs.push(grainR * (R_JITTER_MIN + R_JITTER_SPAN * rnd()));
    grid[((y / cell) | 0) * gw + ((x / cell) | 0)] = i;
    active.push(i);
  };
  const free = (x: number, y: number) => {
    if (x < 0 || y < 0 || x >= w || y >= h) return false;
    const cx = (x / cell) | 0;
    const cy = (y / cell) | 0;
    for (let j = Math.max(0, cy - 2); j <= Math.min(gh - 1, cy + 2); j++) {
      for (let i = Math.max(0, cx - 2); i <= Math.min(gw - 1, cx + 2); i++) {
        const k = grid[j * gw + i]!;
        if (k < 0) continue;
        const dx = xs[k]! - x;
        const dy = ys[k]! - y;
        if (dx * dx + dy * dy < spacing * spacing) return false;
      }
    }
    return true;
  };
  push(rnd() * w, rnd() * h);
  while (active.length && xs.length < count) {
    const ai = (active.length * rnd()) | 0;
    const p = active[ai]!;
    let placed = false;
    for (let k = 0; k < CANDIDATES; k++) {
      const a = rnd() * Math.PI * 2;
      const d = spacing * (1 + ANNULUS * rnd());
      const x = xs[p]! + Math.cos(a) * d;
      const y = ys[p]! + Math.sin(a) * d;
      if (free(x, y)) {
        push(x, y);
        placed = true;
        break;
      }
    }
    if (!placed) {
      active[ai] = active[active.length - 1]!;
      active.pop();
    }
  }

  // --- sort top-to-bottom: depth order makes the contact graph a DAG ---
  const n = xs.length;
  const order = Array.from({ length: n }, (_, i) => i).sort(
    (a, b) => ys[a]! - ys[b]!
  );
  const px = new Float32Array(n);
  const py = new Float32Array(n);
  const pr = new Float32Array(n);
  for (let k = 0; k < n; k++) {
    px[k] = xs[order[k]!]!;
    py[k] = ys[order[k]!]!;
    pr[k] = rs[order[k]!]!;
  }

  // --- contact graph via a uniform neighbour grid, built once ---
  const cs = spacing * 1.8;
  const cw = Math.ceil(w / cs) + 1;
  const chh = Math.ceil(h / cs) + 1;
  const heads = new Int32Array(cw * chh).fill(-1);
  const next = new Int32Array(n).fill(-1);
  for (let i = 0; i < n; i++) {
    const c = ((py[i]! / cs) | 0) * cw + ((px[i]! / cs) | 0);
    next[i] = heads[c]!;
    heads[c] = i;
  }
  const ea: number[] = [];
  const eb: number[] = [];
  const eny: number[] = [];
  const off = new Int32Array(n + 1);
  for (let i = 0; i < n; i++) {
    off[i] = ea.length; // outgoing edges of i start here (i ascends, so CSR is contiguous)
    const cx = (px[i]! / cs) | 0;
    const cy = (py[i]! / cs) | 0;
    for (let j = Math.max(0, cy - 1); j <= Math.min(chh - 1, cy + 1); j++) {
      for (let k = Math.max(0, cx - 1); k <= Math.min(cw - 1, cx + 1); k++) {
        for (let q = heads[j * cw + k]!; q !== -1; q = next[q]!) {
          if (q <= i) continue; // q is at or below i in depth order
          const dx = px[q]! - px[i]!;
          const dy = py[q]! - py[i]!;
          const d = Math.sqrt(dx * dx + dy * dy);
          if (d >= (pr[i]! + pr[q]!) * CONTACT_TOL || d < 1e-6) continue;
          ea.push(i);
          eb.push(q);
          eny.push(dy / d);
        }
      }
    }
  }
  off[n] = ea.length;

  // --- per-grain sum of outgoing n.y, computed once ---
  const enyArr = Float32Array.from(eny);
  const sumny = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    let s = 0;
    for (let e = off[i]!; e < off[i + 1]!; e++) s += enyArr[e]!;
    sumny[i] = s;
  }

  // --- top boundary row and its columns ---
  const band = spacing * TOP_BAND;
  const topIdx: number[] = [];
  const topCol: number[] = [];
  for (let i = 0; i < n; i++) {
    if (py[i]! > band) break; // sorted by depth
    topIdx.push(i);
    topCol.push(Math.floor(px[i]! / spacing));
  }

  return {
    n,
    px,
    py,
    pr,
    ea: Int32Array.from(ea),
    eb: Int32Array.from(eb),
    eny: enyArr,
    off,
    sumny,
    topIdx: Int32Array.from(topIdx),
    topCol: Int32Array.from(topCol),
    spacing,
    f: new Float32Array(ea.length),
    inF: new Float32Array(n),
  };
}

/**
 * One ordered top-down sweep of the Gauss-Seidel force relaxation. Because the
 * grains are sorted by depth every contact points from an earlier index to a
 * later one, so the contact network is a DAG and a single in-order sweep IS
 * the converged fixed point — further iterations reproduce it exactly.
 */
function relax(p: Packing, t: number, indX: number, indY: number, indS: number) {
  const { n, inF, f, eb, eny, off, sumny, topIdx, topCol } = p;
  inF.fill(0);

  const unit = TOP_FLUX / Math.max(1, topIdx.length);
  const breathe = 0.08 * Math.sin(t * 1.7);
  for (let k = 0; k < topIdx.length; k++) {
    inF[topIdx[k]!] +=
      unit * (1 + 0.22 * Math.sin(t * 0.5 + topCol[k]! * 0.4) + breathe);
  }

  if (indS > 0.002) {
    let best = -1;
    let bd = Infinity;
    for (let i = 0; i < n; i++) {
      // a grain with nothing beneath it terminates the load, so pressing on one
      // would do literally nothing (~4% of pointer positions, measured) — the
      // indenter always seats on the nearest grain that can transmit
      if (sumny[i]! <= 1e-6) continue;
      const dx = p.px[i]! - indX;
      const dy = p.py[i]! - indY;
      const d = dx * dx + dy * dy;
      if (d < bd) {
        bd = d;
        best = i;
      }
    }
    if (best >= 0) inF[best] += INDENT_LOAD * indS;
  }

  const weight = TOTAL_WEIGHT / Math.max(1, n);
  for (let i = 0; i < n; i++) {
    const s = off[i + 1]!;
    const total = inF[i]! + weight;
    const sum = sumny[i]!;
    if (sum <= 1e-6) continue; // resting on the floor: the load terminates here
    for (let e = off[i]!; e < s; e++) {
      const v = (total * eny[e]!) / sum;
      f[e] = v;
      inF[eb[e]!] += v;
    }
  }
}

export interface ForceChainsProps {
  /** glyph grid cell size in px */
  cellSize?: number;
  /** target number of grains in the packing */
  grainCount?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function ForceChains({
  cellSize = 12,
  grainCount = 900,
  className = "",
}: ForceChainsProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const count = Math.max(200, Math.min(2000, Math.round(grainCount)));

    let fg = "currentColor";
    let cellW = cellSize;
    let cellH = cellSize;
    let cols = 0;
    let rows = 0;
    let sized = false;
    let ready = false;
    let disposed = false;
    let pack: Packing | null = null;

    let glyphBuf = new Uint8Array(0);
    let lumBuf = new Float32Array(0);
    const bucketLists: number[][] = Array.from(
      { length: ALPHA_BUCKETS },
      () => []
    );

    const readTokens = () => {
      fg = getComputedStyle(canvas).color;
    };

    const measureCell = (fontFamily: string) => {
      const off = document.createElement("canvas");
      const octx = off.getContext("2d");
      if (!octx) return;
      octx.font = `${cellSize}px ${fontFamily}`;
      cellW = Math.max(4, octx.measureText("MMMMMMMMMM").width / 10);
      cellH = cellSize;
    };

    const resize = () => {
      const { width, height } = canvas.getBoundingClientRect();
      if (width < 2 || height < 2) {
        sized = false;
        return;
      }
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const fontFamily = getComputedStyle(canvas).fontFamily;
      measureCell(fontFamily);
      ctx.font = `${cellSize}px ${fontFamily}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      cols = Math.max(4, Math.ceil(width / cellW));
      rows = Math.max(4, Math.ceil(height / cellH));
      glyphBuf = new Uint8Array(cols * rows);
      lumBuf = new Float32Array(cols * rows);
      pack = buildPacking(width, height, count);
      sized = true;
    };

    const draw = () => {
      const p = pack;
      if (!sized || !p) return;
      const w = cols * cellW;
      const h = rows * cellH;
      ctx.clearRect(0, 0, w, h);
      glyphBuf.fill(0);
      lumBuf.fill(0);
      for (let b = 0; b < ALPHA_BUCKETS; b++) bucketLists[b]!.length = 0;

      // --- mean contact force, the sparsity reference ---
      const E = p.f.length;
      if (!E) return;
      let sum = 0;
      for (let e = 0; e < E; e++) sum += p.f[e]!;
      const fbar = sum / E;
      if (fbar <= 1e-9) return;

      // --- pass one: rasterise only the chain-carrying contacts ---
      const step = Math.min(cellW, cellH);
      for (let e = 0; e < E; e++) {
        const ratio = p.f[e]! / fbar;
        if (ratio <= CHAIN_THRESHOLD) continue;
        const lum = Math.pow(
          Math.min(1, (ratio - CHAIN_THRESHOLD) / CHAIN_RANGE),
          CHAIN_GAMMA
        );
        const a = p.ea[e]!;
        const b = p.eb[e]!;
        const ax = p.px[a]!;
        const ay = p.py[a]!;
        const dx = p.px[b]! - ax;
        const dy = p.py[b]! - ay;
        const len = Math.sqrt(dx * dx + dy * dy);
        const deg = (Math.atan2(dy, dx) * 180) / Math.PI; // dy >= 0, so 0..180
        let slope: number;
        if (deg < 22.5 || deg > 157.5) slope = 0; // '-'
        else if (deg > 67.5 && deg < 112.5) slope = 1; // '|'
        else if (deg < 67.5) slope = 3; // '\'
        else slope = 2; // '/'
        // faint load is texture, so it stays on '.' / ':' — letting it reach
        // '-' put 145 horizontal marks on screen against 36 genuinely
        // horizontal chain cells (measured), which reads as streaking in a
        // field whose subject is vertical chains
        const gi =
          lum < FAINT_CUTOFF
            ? 1 + Math.min(1, Math.floor(lum * 8.8))
            : SLOPE_BASE + slope;
        const steps = Math.max(1, Math.ceil(len / step));
        for (let s = 0; s <= steps; s++) {
          const gx = ((ax + (dx * s) / steps) / cellW) | 0;
          const gy = ((ay + (dy * s) / steps) / cellH) | 0;
          if (gx < 0 || gy < 0 || gx >= cols || gy >= rows) continue;
          const idx = gy * cols + gx;
          if (lum <= lumBuf[idx]!) continue; // brightest chain wins the cell
          lumBuf[idx] = lum;
          glyphBuf[idx] = gi;
        }
      }

      for (let i = 0; i < glyphBuf.length; i++) {
        if (!glyphBuf[i]) continue;
        const b = Math.min(ALPHA_BUCKETS - 1, (lumBuf[i]! * ALPHA_BUCKETS) | 0);
        bucketLists[b]!.push(i);
      }

      // --- pass two: one globalAlpha write per bucket ---
      ctx.fillStyle = fg;
      for (let b = 0; b < ALPHA_BUCKETS; b++) {
        const list = bucketLists[b]!;
        if (!list.length) continue;
        ctx.globalAlpha = 0.1 + (b / (ALPHA_BUCKETS - 1)) * 0.9;
        for (let k = 0; k < list.length; k++) {
          const idx = list[k]!;
          const gx = idx % cols;
          const gy = (idx - gx) / cols;
          ctx.fillText(
            GLYPHS[glyphBuf[idx]!]!,
            gx * cellW + cellW / 2,
            gy * cellH + cellH / 2
          );
        }
      }
      ctx.globalAlpha = 1;
    };

    // -- hot-path state -------------------------------------------------------
    let raf = 0;
    let last = 0;
    let t = 0;
    const ind = { x: -1e5, y: -1e5, has: false, strength: 0 };

    const still = () => {
      if (!pack) return;
      relax(pack, 0, -1e5, -1e5, 0);
      draw();
    };

    const loop = (now: number) => {
      const dt = last ? Math.min(DT_MAX, (now - last) / 1000) : 1 / 60;
      last = now;
      t += dt;
      const target = ind.has ? 1 : 0;
      ind.strength += (target - ind.strength) * Math.min(1, dt / INDENT_TAU);
      if (pack) relax(pack, t, ind.x, ind.y, ind.strength);
      draw();
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    const onPointerMove = (e: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      ind.x = e.clientX - rect.left;
      ind.y = e.clientY - rect.top;
      ind.has = true;
    };
    const onPointerLeave = () => {
      ind.has = false;
    };

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
        if (reduced) still();
      }, 150);
    };

    const onVis = () => {
      if (!document.hidden && !reduced && ready) {
        // a rAF queued before the tab was hidden fires again on restore, so
        // cancel it first — otherwise resuming leaves two loops running
        cancelAnimationFrame(raf);
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) still();
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    document.fonts.ready.then(() => {
      if (disposed) return;
      readTokens();
      resize();
      ready = true;
      if (reduced) still();
      else raf = requestAnimationFrame(loop);
    });

    window.addEventListener("resize", onResize);
    if (!reduced) {
      canvas.addEventListener("pointermove", onPointerMove);
      canvas.addEventListener("pointerleave", onPointerLeave);
    }
    document.addEventListener("visibilitychange", onVis);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      mo.disconnect();
      window.removeEventListener("resize", onResize);
      canvas.removeEventListener("pointermove", onPointerMove);
      canvas.removeEventListener("pointerleave", onPointerLeave);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [cellSize, grainCount]);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden
      className={`block h-full w-full font-mono text-foreground ${className}`}
    />
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// NodalLines — an ambient ASCII background that draws the DESTRUCTIVE
// INTERFERENCE pattern of four point emitters, and only that. Four radial
// waves are SUMMED (background-ascii-caustics multiplies rotated PLANE waves
// and sharpens with a power curve; background-ascii-plasma sums octaves and
// maps luminance — this does neither), and ink appears only along the ZERO
// SET of that sum at the current instant: the cells where the four waves are
// cancelling each other out right now. The
// ~90% of the frame that is oscillating with any amplitude at all draws
// nothing, so what remains is the ripple-tank photograph — smooth curved
// hairlines, the hyperbolic dead-fringe families, fanning between four
// unmarked focal points. The emitters themselves are never drawn.
//
// The pointer is a FIFTH emitter, locked in antiphase with emitter 0.
// Interference depends on the path-length difference to EVERY source, so
// adding one reorganises the whole nodal family and fans a fresh set of dead
// fringes out from the cursor; on leave its amplitude eases back to zero and
// the four-source geometry returns exactly.
// ---------------------------------------------------------------------------

const RAMP = " .:-=+*#%@";
const ALPHA_BUCKETS = 6;

/** normalized emitter positions on a slightly irregular quadrilateral */
const SOURCES = [
  { nx: 0.24, ny: 0.3, amp: 1.0, phi: 0.0, drift: 0.05 },
  { nx: 0.76, ny: 0.26, amp: 0.88, phi: 0.6, drift: -0.037 },
  { nx: 0.3, ny: 0.74, amp: 1.12, phi: 1.9, drift: 0.061 },
  { nx: 0.72, ny: 0.78, amp: 0.95, phi: 3.1, drift: -0.044 },
] as const;

const K = 0.042; // rad/px — spatial wavenumber
const OMEGA = 1.15; // rad/s — temporal frequency
const R_MIN = 8; // px — clamp so the 1/sqrt(r) decay never blows up
const BAND_PX = 4.0; // px — half-width of the inked band around the zero set
const NODE_POW = 1.3; // falloff across that band
const FLAT_GUARD = 0.4; // skip loud cells (|A|/Amax above this) — see draw()
const POINTER_TAU = 0.5; // s — pointer emitter amplitude ease in/out
const POINTER_AMP = 1.0;
const POINTER_PHI = Math.PI; // antiphase with emitter 0
const DT_MAX = 0.05;

export interface NodalLinesProps {
  /** grid cell size in px */
  cellSize?: number;
  /** how many of the four fixed emitters to use (2–4) */
  sourceCount?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function NodalLines({
  cellSize = 12,
  sourceCount = 4,
  className = "",
}: NodalLinesProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    const n = Math.max(2, Math.min(SOURCES.length, Math.round(sourceCount)));

    let fg = "currentColor";
    let cellW = cellSize;
    let cellH = cellSize;
    let cols = 0;
    let rows = 0;
    let dpr = 1;
    let sized = false;
    let ready = false;
    let disposed = false;

    let charBuf = new Uint8Array(0);
    const bucketLists: number[][] = Array.from(
      { length: ALPHA_BUCKETS },
      () => []
    );

    // live emitter state, in px, rebuilt on resize
    const sx = new Float64Array(n + 1);
    const sy = new Float64Array(n + 1);
    const sa = new Float64Array(n + 1);
    const sp = new Float64Array(n + 1);

    const readTokens = () => {
      fg = getComputedStyle(canvas).color;
    };

    const measureCell = (fontFamily: string) => {
      const off = document.createElement("canvas");
      const octx = off.getContext("2d");
      if (!octx) return;
      octx.font = `${cellSize}px ${fontFamily}`;
      cellW = Math.max(4, octx.measureText("MMMMMMMMMM").width / 10);
      cellH = cellSize;
    };

    const resize = () => {
      const { width, height } = canvas.getBoundingClientRect();
      if (width < 2 || height < 2) {
        sized = false;
        return;
      }
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const fontFamily = getComputedStyle(canvas).fontFamily;
      measureCell(fontFamily);
      ctx.font = `${cellSize}px ${fontFamily}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      cols = Math.max(4, Math.ceil(width / cellW));
      rows = Math.max(4, Math.ceil(height / cellH));
      charBuf = new Uint8Array(cols * rows);
      for (let i = 0; i < n; i++) {
        const s = SOURCES[i]!;
        sx[i] = s.nx * width;
        sy[i] = s.ny * height;
        sa[i] = s.amp;
      }
      sized = true;
    };

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
        if (reduced) drawStatic();
      }, 150);
    };

    /**
     * One frame. `count` emitters are already loaded into sx/sy/sa/sp.
     *
     * A = sum_i a_i * cos(k*r_i - omega*t + phi_i) / sqrt(max(r_i, R_MIN))
     *
     * The 1/sqrt(r) term is the correct 2D cylindrical-wave amplitude decay —
     * it is what keeps the fringes close to an emitter from washing out. Ink
     * marks only the zero set of A. Point-sampling |A| against a fixed
     * amplitude threshold aliases into speckle at glyph resolution (the band
     * is ~1px wide, the cell is ~7px), so the distance to the nodal curve is
     * taken analytically instead: d = |A| / |grad A|, in px. That is the same
     * set, resolved rather than sampled. |A|/Amax still gates the result, so
     * cells sitting on a stationary point of an otherwise loud field never
     * ink.
     */
    const draw = (t: number, count: number) => {
      if (!sized) return;
      const w = cols * cellW;
      const h = rows * cellH;
      ctx.clearRect(0, 0, w, h);

      for (let b = 0; b < ALPHA_BUCKETS; b++) bucketLists[b]!.length = 0;

      let i = 0;
      for (let gy = 0; gy < rows; gy++) {
        const y = gy * cellH + cellH / 2;
        for (let gx = 0; gx < cols; gx++, i++) {
          const x = gx * cellW + cellW / 2;
          let a = 0; // summed amplitude
          let aMax = 0; // maximum amplitude reachable at this cell
          let gradX = 0;
          let gradY = 0;

          for (let s = 0; s < count; s++) {
            const amp = sa[s]!;
            if (amp <= 0.001) continue;
            const dx = x - sx[s]!;
            const dy = y - sy[s]!;
            const r = Math.max(Math.sqrt(dx * dx + dy * dy), R_MIN);
            const inv = amp / Math.sqrt(r);
            const theta = K * r - OMEGA * t + sp[s]!;
            const c = Math.cos(theta);
            const sn = Math.sin(theta);
            a += inv * c;
            aMax += inv;
            // d/dr of inv*cos(theta), projected onto x and y
            const dAdr = inv * (-sn * K) - (0.5 * inv * c) / r;
            gradX += (dAdr * dx) / r;
            gradY += (dAdr * dy) / r;
          }

          charBuf[i] = 0;
          if (aMax <= 1e-9) continue;
          const abs = Math.abs(a);
          if (abs / aMax > FLAT_GUARD) continue;
          const grad = Math.sqrt(gradX * gradX + gradY * gradY);
          if (grad < 1e-9) continue;
          const d = abs / grad; // px to the nearest nodal curve
          if (d >= BAND_PX) continue;

          const v = Math.pow(1 - d / BAND_PX, NODE_POW);
          const bucket = Math.min(
            ALPHA_BUCKETS - 1,
            Math.floor(v * ALPHA_BUCKETS)
          );
          const ci = Math.floor(v * (RAMP.length - 1));
          charBuf[i] = ci;
          if (ci !== 0) bucketLists[bucket]!.push(i);
        }
      }

      ctx.fillStyle = fg;
      for (let b = 0; b < ALPHA_BUCKETS; b++) {
        const list = bucketLists[b]!;
        if (list.length === 0) continue;
        ctx.globalAlpha = 0.14 + (b / (ALPHA_BUCKETS - 1)) * 0.86;
        for (let kk = 0; kk < list.length; kk++) {
          const idx = list[kk]!;
          const gx = idx % cols;
          const gy = (idx - gx) / cols;
          ctx.fillText(
            RAMP[charBuf[idx]!]!,
            gx * cellW + cellW / 2,
            gy * cellH + cellH / 2
          );
        }
      }
      ctx.globalAlpha = 1;
    };

    /** reduced-motion / theme-flip frame: t = 0, no pointer emitter */
    const drawStatic = () => {
      for (let i = 0; i < n; i++) sp[i] = SOURCES[i]!.phi;
      draw(0, n);
    };

    // -- hot-path state -------------------------------------------------------
    let raf = 0;
    let last = 0;
    let t = 0;
    const pointer = { x: 0, y: 0, has: false, amp: 0 };

    const loop = (now: number) => {
      const dt = last ? Math.min(DT_MAX, (now - last) / 1000) : 1 / 60;
      last = now;
      t += dt;

      // every emitter shares omega, so the whole field swings as
      // |S(x)|*cos(arg S(x) - omega*t) and the inked zero-crossing family
      // already sweeps at a resting ~28 px/s. On top of that each emitter's
      // phase drifts at its own much slower rate, which slowly re-shapes
      // *which* family you get so the pattern never repeats on a short cycle.
      for (let i = 0; i < n; i++) {
        const s = SOURCES[i]!;
        sp[i] = s.phi + s.drift * t;
      }

      const target = pointer.has ? POINTER_AMP : 0;
      pointer.amp += (target - pointer.amp) * Math.min(1, dt / POINTER_TAU);

      let count = n;
      if (pointer.amp > 0.001) {
        sx[n] = pointer.x;
        sy[n] = pointer.y;
        sa[n] = pointer.amp;
        sp[n] = POINTER_PHI;
        count = n + 1;
      }

      draw(t, count);
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    const onPointerMove = (e: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      pointer.x = e.clientX - rect.left;
      pointer.y = e.clientY - rect.top;
      pointer.has = true;
    };
    const onPointerLeave = () => {
      pointer.has = false;
    };

    const onVis = () => {
      if (!document.hidden && !reduced && ready) {
        // a frame queued before the tab was hidden is still pending and fires
        // on return — without this cancel each hide/show cycle would leave an
        // extra self-perpetuating loop running
        cancelAnimationFrame(raf);
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) drawStatic();
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    document.fonts.ready.then(() => {
      if (disposed) return;
      readTokens();
      resize();
      ready = true;
      if (reduced) {
        drawStatic();
      } else {
        raf = requestAnimationFrame(loop);
      }
    });

    window.addEventListener("resize", onResize);
    if (!reduced) {
      canvas.addEventListener("pointermove", onPointerMove);
      canvas.addEventListener("pointerleave", onPointerLeave);
    }
    document.addEventListener("visibilitychange", onVis);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      mo.disconnect();
      window.removeEventListener("resize", onResize);
      canvas.removeEventListener("pointermove", onPointerMove);
      canvas.removeEventListener("pointerleave", onPointerLeave);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [cellSize, sourceCount]);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden
      className={`block h-full w-full font-mono text-foreground ${className}`}
    />
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// VoronoiWalls — an ambient ASCII background that draws a Voronoi diagram's
// WALLS ONLY. For every grid cell the nearest and second-nearest site distances
// d1 <= d2 are found by a plain linear scan, and ink is placed only where the
// NORMALIZED difference w = (d2 - d1) / (d2 + d1) falls below a small
// threshold — i.e. exactly where the two closest sites are near-equidistant.
// The normalization is the point: raw (d2 - d1) would make walls near the
// sites hairline and walls far away fat, whereas w is scale-free, so every
// boundary in the frame is the same weight. Cell interiors have w near 1 and
// draw nothing, so most of the field is empty by construction and what is left
// is a network of hairlines meeting at clean three-way junctions — three sites
// equidistant is a Y-junction, which is why foam and cracked mud look like
// this. Measured coverage is ~10% of cells, stable across drift and frame
// size. The pointer joins the diagram as an EXTRA SITE WITH A POWER WEIGHT
// (a Laguerre / power Voronoi cell): its distance is measured as the tangent
// length sqrt(d^2 - r^2) rather than d, with r^2 easing up while the pointer
// is over the canvas. A positive weight makes its cell OWN MORE TERRITORY, so
// the surrounding walls bow convexly away and the neighbours are squeezed —
// a bubble inflating in a foam. On leave r^2 eases back to 0, the cell
// collapses, and the walls spring back to the undisturbed diagram.
// ---------------------------------------------------------------------------

const RAMP = " .:-=+*#%@";
const ALPHA_BUCKETS = 6;
const WALL_W = 0.055; // normalized (d2-d1)/(d2+d1) below which a cell is inked
const WALL_POW = 1.5; // luminance falloff across the wall's width
const JUNCTION_BOOST = 1.6; // triple points read a touch brighter, as in a foam
const DRIFT_AMP = 0.045; // * min(W,H) — lissajous amplitude per site
const DRIFT_MIN = 0.06; // rad/s
const DRIFT_MAX = 0.17; // rad/s
const MIN_SEP = 0.16; // * min(W,H) — poisson-disk rejection radius
const POINTER_R = 0.1; // * min(W,H) — max power radius of the pointer's cell
const POINTER_TAU = 0.5; // s — weight ease time constant, both directions
const DT_MAX = 0.05;
const SEED = 0x5eed1a;

/** deterministic PRNG so the site layout is stable for a given size */
function mulberry32(a: number) {
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export interface VoronoiWallsProps {
  /** grid cell size in px */
  cellSize?: number;
  /** base number of drifting sites, scaled by frame area and clamped 14..34 */
  siteCount?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function VoronoiWalls({
  cellSize = 12,
  siteCount = 22,
  className = "",
}: VoronoiWallsProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    let fg = "currentColor";
    let cellW = cellSize;
    let cellH = cellSize;
    let cols = 0;
    let rows = 0;
    let width = 0;
    let height = 0;
    let sized = false;
    let ready = false;
    let disposed = false;

    let charBuf = new Uint8Array(0);
    const bucketLists: number[][] = Array.from(
      { length: ALPHA_BUCKETS },
      () => []
    );

    // site fields: base position, lissajous frequency and phase
    let n = 0;
    let sx0 = new Float32Array(0);
    let sy0 = new Float32Array(0);
    let swx = new Float32Array(0);
    let swy = new Float32Array(0);
    let spx = new Float32Array(0);
    let spy = new Float32Array(0);
    let amp = 0;
    // live positions, plus one trailing slot for the pointer site
    let px = new Float32Array(0);
    let py = new Float32Array(0);

    const readTokens = () => {
      fg = getComputedStyle(canvas).color;
    };

    const measureCell = (fontFamily: string) => {
      const off = document.createElement("canvas");
      const octx = off.getContext("2d");
      if (!octx) return;
      octx.font = `${cellSize}px ${fontFamily}`;
      cellW = Math.max(4, octx.measureText("MMMMMMMMMM").width / 10);
      cellH = cellSize;
    };

    /** poisson-disk rejection sampling — no two sites closer than minSep */
    const seedSites = () => {
      const m = Math.min(width, height);
      const scale = Math.sqrt((width * height) / (1280 * 720));
      n = Math.max(14, Math.min(34, Math.round(siteCount * scale)));
      amp = DRIFT_AMP * m;
      sx0 = new Float32Array(n);
      sy0 = new Float32Array(n);
      swx = new Float32Array(n);
      swy = new Float32Array(n);
      spx = new Float32Array(n);
      spy = new Float32Array(n);
      px = new Float32Array(n + 1);
      py = new Float32Array(n + 1);

      const rng = mulberry32(SEED);
      let sep = MIN_SEP * m;
      const pad = -amp * 0.5; // let sites drift a little off-frame
      let placed = 0;
      let fails = 0;
      while (placed < n) {
        const cx = pad + rng() * (width - 2 * pad);
        const cy = pad + rng() * (height - 2 * pad);
        let ok = true;
        for (let i = 0; i < placed; i++) {
          const dx = cx - sx0[i]!;
          const dy = cy - sy0[i]!;
          if (dx * dx + dy * dy < sep * sep) {
            ok = false;
            break;
          }
        }
        if (!ok) {
          // relax the separation rather than spin forever in a tight frame
          if (++fails > 220) {
            sep *= 0.9;
            fails = 0;
          }
          continue;
        }
        sx0[placed] = cx;
        sy0[placed] = cy;
        swx[placed] = DRIFT_MIN + rng() * (DRIFT_MAX - DRIFT_MIN);
        swy[placed] = DRIFT_MIN + rng() * (DRIFT_MAX - DRIFT_MIN);
        spx[placed] = rng() * Math.PI * 2;
        spy[placed] = rng() * Math.PI * 2;
        placed++;
      }
    };

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      if (rect.width < 2 || rect.height < 2) {
        sized = false;
        return;
      }
      width = rect.width;
      height = rect.height;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const fontFamily = getComputedStyle(canvas).fontFamily;
      measureCell(fontFamily);
      ctx.font = `${cellSize}px ${fontFamily}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      cols = Math.max(4, Math.ceil(width / cellW));
      rows = Math.max(4, Math.ceil(height / cellH));
      charBuf = new Uint8Array(cols * rows);
      seedSites();
      sized = true;
    };

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
        if (reduced) draw(0, 0, 0, 0);
      }, 150);
    };

    const draw = (t: number, pxc: number, pyc: number, pr2: number) => {
      if (!sized) return;
      ctx.clearRect(0, 0, width, height);
      for (let b = 0; b < ALPHA_BUCKETS; b++) bucketLists[b]!.length = 0;

      // advance every site along its own slow lissajous
      for (let i = 0; i < n; i++) {
        px[i] = sx0[i]! + amp * Math.sin(t * swx[i]! + spx[i]!);
        py[i] = sy0[i]! + amp * Math.cos(t * swy[i]! + spy[i]!);
      }
      const hasPointer = pr2 > 1;
      const count = hasPointer ? n + 1 : n;
      if (hasPointer) {
        px[n] = pxc;
        py[n] = pyc;
      }

      let i = 0;
      for (let gy = 0; gy < rows; gy++) {
        const y = gy * cellH + cellH / 2;
        for (let gx = 0; gx < cols; gx++, i++) {
          const x = gx * cellW + cellW / 2;
          // three smallest effective distances by linear scan. Ordering is
          // done on the SQUARED quantity and only the three winners are
          // square-rooted, which keeps the scan at one sqrt-free inner step.
          let q1 = Infinity;
          let q2 = Infinity;
          let q3 = Infinity;
          for (let s = 0; s < count; s++) {
            const dx = x - px[s]!;
            const dy = y - py[s]!;
            let q = dx * dx + dy * dy;
            // power (Laguerre) distance for the weighted pointer site: the
            // squared tangent length to its circle, so the bisector is the
            // radical axis and the cell genuinely grows with the weight
            if (hasPointer && s === n) q = q > pr2 ? q - pr2 : 0;
            if (q < q1) {
              q3 = q2;
              q2 = q1;
              q1 = q;
            } else if (q < q2) {
              q3 = q2;
              q2 = q;
            } else if (q < q3) {
              q3 = q;
            }
          }
          const d1 = Math.sqrt(q1);
          const d2 = Math.sqrt(q2);
          const d3 = Math.sqrt(q3);

          const sum = d1 + d2;
          const w = sum > 1e-6 ? (d2 - d1) / sum : 1;
          let v = 0;
          if (w < WALL_W) {
            v = Math.pow(1 - w / WALL_W, WALL_POW);
            const sum3 = d1 + d3;
            if (sum3 > 1e-6 && (d3 - d1) / sum3 < WALL_W) {
              v = Math.min(1, v * JUNCTION_BOOST);
            }
          }

          const ci = Math.floor(v * (RAMP.length - 1));
          charBuf[i] = ci;
          if (ci !== 0) {
            const bucket = Math.min(
              ALPHA_BUCKETS - 1,
              Math.floor(v * ALPHA_BUCKETS)
            );
            bucketLists[bucket]!.push(i);
          }
        }
      }

      ctx.fillStyle = fg;
      for (let b = 0; b < ALPHA_BUCKETS; b++) {
        const list = bucketLists[b]!;
        if (list.length === 0) continue;
        ctx.globalAlpha = 0.14 + (b / (ALPHA_BUCKETS - 1)) * 0.86;
        for (let k = 0; k < list.length; k++) {
          const idx = list[k]!;
          const gx = idx % cols;
          const gy = (idx - gx) / cols;
          ctx.fillText(
            RAMP[charBuf[idx]!]!,
            gx * cellW + cellW / 2,
            gy * cellH + cellH / 2
          );
        }
      }
      ctx.globalAlpha = 1;
    };

    // -- hot-path state -------------------------------------------------------
    let raf = 0;
    let last = 0;
    let t = 0;
    const ptr = { x: 0, y: 0, has: false, r2: 0 };

    const loop = (now: number) => {
      const dt = last ? Math.min(DT_MAX, (now - last) / 1000) : 1 / 60;
      last = now;
      t += dt;
      const m = Math.min(width, height);
      const target = ptr.has ? (POINTER_R * m) ** 2 : 0;
      ptr.r2 += (target - ptr.r2) * Math.min(1, dt / POINTER_TAU);
      draw(t, ptr.x, ptr.y, ptr.r2);
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    const onPointerMove = (e: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      ptr.x = e.clientX - rect.left;
      ptr.y = e.clientY - rect.top;
      ptr.has = true;
    };
    const onPointerLeave = () => {
      ptr.has = false;
    };

    const onVis = () => {
      if (!document.hidden && !reduced && ready) {
        // a frame requested while the tab was hidden is still queued; drop it
        // so resuming never leaves two loops running at double speed
        cancelAnimationFrame(raf);
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) draw(0, 0, 0, 0);
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    document.fonts.ready.then(() => {
      if (disposed) return;
      readTokens();
      resize();
      ready = true;
      if (reduced) {
        draw(0, 0, 0, 0);
      } else {
        raf = requestAnimationFrame(loop);
      }
    });

    window.addEventListener("resize", onResize);
    if (!reduced) {
      canvas.addEventListener("pointermove", onPointerMove);
      canvas.addEventListener("pointerleave", onPointerLeave);
    }
    document.addEventListener("visibilitychange", onVis);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      mo.disconnect();
      window.removeEventListener("resize", onResize);
      canvas.removeEventListener("pointermove", onPointerMove);
      canvas.removeEventListener("pointerleave", onPointerLeave);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [cellSize, siteCount]);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden
      className={`block h-full w-full font-mono text-foreground ${className}`}
    />
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// WakeGlyph — a full-bleed monospace character-comet field. A sparse, static
// ambient scatter sits at rest; the pointer stamps a "heat" value into the
// cells it passes over, and each stamped cell decays back toward the ambient
// floor at a rate fixed at stamp time — a fast pass stamps many cells at a
// low, quick-decaying heat (a long, thin, short-lived wake), a slow pass
// stamps fewer cells at high heat with a slow decay rate (a fat, lingering
// blob). Direct-DOM rAF over a persistent Float32Array grid, glyph density
// mapped from an ASCII ramp, theme-aware ink read via getComputedStyle.
// ---------------------------------------------------------------------------

const RAMP = " .:-=+*#%@";

export interface WakeGlyphProps {
  /** grid cell size in px */
  cellSize?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

// deterministic PRNG so the ambient scatter is stable within a session
function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function WakeGlyph({ cellSize = 12, className = "" }: WakeGlyphProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    let fg = getComputedStyle(canvas).color;
    const monoFont =
      getComputedStyle(document.documentElement).getPropertyValue("--font-mono") ||
      "ui-monospace, monospace";

    let dpr = 1;
    let cols = 0;
    let rows = 0;
    let heat: Float32Array = new Float32Array(0);
    let rate: Float32Array = new Float32Array(0);
    let ambient: Float32Array = new Float32Array(0);
    let raf = 0;
    let last = 0;
    const pointer = { x: -1, y: -1, t: 0, has: false };

    const resize = () => {
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      const { width, height } = canvas.getBoundingClientRect();
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.font = `${cellSize * 0.85}px ${monoFont}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";

      cols = Math.max(1, Math.ceil(width / cellSize));
      rows = Math.max(1, Math.ceil(height / cellSize));
      const n = cols * rows;
      heat = new Float32Array(n);
      rate = new Float32Array(n).fill(1.4);
      ambient = new Float32Array(n);

      // sparse, near-silent ground state: a static seeded scatter of faint cells
      const rand = mulberry32(0xa53f9c1 ^ (cols * 71 + rows));
      for (let i = 0; i < n; i++) {
        if (rand() < 0.035) ambient[i] = 0.08 + rand() * 0.14;
      }
    };

    const draw = () => {
      const { width, height } = canvas.getBoundingClientRect();
      ctx.clearRect(0, 0, width, height);
      ctx.fillStyle = fg;
      for (let gy = 0; gy < rows; gy++) {
        for (let gx = 0; gx < cols; gx++) {
          const idx = gy * cols + gx;
          const lum = Math.max(ambient[idx]!, heat[idx]!);
          if (lum <= 0.03) continue;
          const ch = RAMP[Math.min(RAMP.length - 1, Math.floor(lum * (RAMP.length - 1)))];
          if (ch === " ") continue;
          ctx.globalAlpha = Math.min(1, 0.15 + lum * 0.85);
          ctx.fillText(ch, gx * cellSize + cellSize / 2, gy * cellSize + cellSize / 2);
        }
      }
      ctx.globalAlpha = 1;
    };

    // stamp a soft circular blot of heat around a grid cell, recording the
    // decay rate (higher = faster fade) that this pass's speed implies.
    const stamp = (px: number, py: number, radiusCells: number, decayRate: number) => {
      const cx = px / cellSize;
      const cy = py / cellSize;
      const r = Math.max(0.6, radiusCells);
      const minGx = Math.max(0, Math.floor(cx - r));
      const maxGx = Math.min(cols - 1, Math.ceil(cx + r));
      const minGy = Math.max(0, Math.floor(cy - r));
      const maxGy = Math.min(rows - 1, Math.ceil(cy + r));
      for (let gy = minGy; gy <= maxGy; gy++) {
        for (let gx = minGx; gx <= maxGx; gx++) {
          const d = Math.hypot(gx + 0.5 - cx, gy + 0.5 - cy);
          if (d > r) continue;
          const falloff = 1 - d / r;
          const idx = gy * cols + gx;
          if (falloff > heat[idx]!) {
            heat[idx] = falloff;
            rate[idx] = decayRate;
          }
        }
      }
    };

    const onPointerMove = (e: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      const now = performance.now();
      if (pointer.has) {
        const dx = x - pointer.x;
        const dy = y - pointer.y;
        const dist = Math.hypot(dx, dy);
        const dt = Math.max(1, now - pointer.t);
        const speed = dist / dt; // px/ms

        // velocity-dependent stamp: fast = thin+quick-fading, slow = fat+lingering
        const radiusCells = Math.max(0.6, Math.min(2.6, 2.4 / (1 + speed * 1.6)));
        const decayRate = Math.max(0.8, Math.min(4.5, 1.0 + speed * 3.2));

        // sample along the path so a fast pass doesn't leave gaps between frames
        const steps = Math.max(1, Math.ceil(dist / (cellSize * 0.5)));
        for (let s = 1; s <= steps; s++) {
          const t = s / steps;
          stamp(pointer.x + dx * t, pointer.y + dy * t, radiusCells, decayRate);
        }
      } else {
        stamp(x, y, 1.4, 1.4);
      }
      pointer.x = x;
      pointer.y = y;
      pointer.t = now;
      pointer.has = true;
    };

    const onPointerLeave = () => {
      pointer.has = false;
    };

    const loop = (now: number) => {
      const dt = last ? Math.min(64, now - last) / 1000 : 1 / 60;
      last = now;
      for (let i = 0; i < heat.length; i++) {
        if (heat[i]! > 0) {
          heat[i]! -= rate[i]! * dt;
          if (heat[i]! < 0) heat[i] = 0;
        }
      }
      draw();
      raf = requestAnimationFrame(loop);
    };

    resize();
    if (reduced) {
      draw(); // ambient-only static frame; pointer wake is skipped entirely
    } else {
      canvas.addEventListener("pointermove", onPointerMove);
      canvas.addEventListener("pointerleave", onPointerLeave);
      raf = requestAnimationFrame(loop);
    }

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
        if (reduced) draw();
      }, 150);
    };
    window.addEventListener("resize", onResize);

    // the site's theme toggle flips a `.dark` class on <html> live, with no
    // remount — watch it so the glyph color updates without a page reload
    const themeObserver = new MutationObserver(() => {
      fg = getComputedStyle(canvas).color;
      if (reduced) draw();
    });
    themeObserver.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    return () => {
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      themeObserver.disconnect();
      window.removeEventListener("resize", onResize);
      canvas.removeEventListener("pointermove", onPointerMove);
      canvas.removeEventListener("pointerleave", onPointerLeave);
    };
  }, [cellSize]);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden
      className={`block h-full w-full text-foreground ${className}`}
    />
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// LloydRelax — a blue-noise stipple screen that never finishes settling.
//
// Every frame runs exactly ONE iteration of weighted Lloyd relaxation against a
// drifting density function. Lloyd's algorithm moves each site toward the
// centroid of its own Voronoi cell; its fixed point is a centroidal Voronoi
// tessellation, whose local spacing goes as rho^(-1/2). That is the reason the
// field reads as an engraved tonal screen rather than scattered noise — the
// dots are not randomly placed, they are the stationary distribution of a
// relaxation, so they are locally equidistant everywhere while still being
// globally denser where rho is larger.
//
// The density has GENUINE ZEROS: rho = clamp((n - 0.35)/0.65, 0, 1)^2 with n a
// sum of three sines. The 0.35 floor leaves roughly a quarter of the frame at
// exactly zero, and the square makes the falloff steep, so ink pools into a few
// lobes with hard-edged bare paper between them instead of washing evenly over
// the frame. The three sine periods (~30s, ~42s, ~57s) are mutually
// incommensurate, so the lobes drift and reshape forever and the relaxation
// never converges — that non-convergence IS the resting pulse. There is no
// separate ambient animation layered on top.
//
// The Voronoi cell is never triangulated. Sites are binned into a uniform hash
// grid; a quarter-resolution sample lattice walks the frame, each sample finds
// its nearest site by scanning only the 3x3 neighbouring bins, and accumulates
// its own rho into that site's weight/moment accumulators. That is the discrete
// weighted Voronoi centroid — the Delaunay dual computed without ever building
// a triangulation.
//
// The pointer multiplies the density by a gaussian well. Nothing pulls the dots
// directly: the relaxation itself carries them inward over about a second
// because their cells' centroids have moved, and lets them drain back out at
// the same rate once the well eases shut.
// ---------------------------------------------------------------------------

const HASH_CELL = 48; // px — uniform site hash bin
const SAMPLE_CELL = 6; // px — quarter-resolution centroid sample lattice
const STEP = 0.55; // fraction of the way to the centroid, per iteration
const DEAD_W = 1e-4; // sumW below this = stranded in a zero region, teleport
const DOT_R = 1.5; // px
const ALPHAS = [0.22, 0.4, 0.58, 0.76, 0.95] as const;
const CULL_RHO = 0.02; // below this the point is not drawn at all
const WELL_GAIN = 2.6; // peak density multiplier under the pointer
const WELL_SIGMA = 90; // px
const WELL_TAU = 0.5; // s — well opens and closes on the same constant
const SEED_TRIES = 40;
const WARM_MOUNT = 12; // iterations run at (re)size so frame one is settled
const WARM_ITERS = 24; // reduced-motion: iterations run before the one frame
const DT_MAX = 1 / 30;
const SEED = 0x10ddd1;

/** deterministic PRNG so a given size always seeds the same field */
function mulberry32(a: number) {
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Ambient density. Three incommensurate sines, floored at 0.35 so about a
 * quarter of the frame is exactly zero, then squared for a steep edge.
 */
function ambient(x: number, y: number, t: number): number {
  const n =
    0.5 +
    (Math.sin(0.0091 * x + 0.21 * t) +
      Math.sin(0.0067 * y - 0.15 * t) +
      Math.sin(0.0053 * (x + y) + 0.11 * t)) /
      6;
  let r = (n - 0.35) / 0.65;
  if (r <= 0) return 0;
  if (r > 1) r = 1;
  return r * r;
}

export interface LloydRelaxProps {
  /** number of stipple sites */
  count?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function LloydRelax({ count = 1400, className = "" }: LloydRelaxProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    const n = Math.max(64, Math.round(count));
    let rng = mulberry32(SEED);

    let fg = "currentColor";
    let width = 0;
    let height = 0;
    let sized = false;
    let disposed = false;

    // site state — mutated in place, never reallocated on the hot path
    const px = new Float32Array(n);
    const py = new Float32Array(n);
    const sumW = new Float32Array(n);
    const sumWX = new Float32Array(n);
    const sumWY = new Float32Array(n);
    const next = new Int32Array(n);
    let heads = new Int32Array(0);
    let hCols = 0;
    let hRows = 0;

    const buckets: number[][] = Array.from({ length: ALPHAS.length }, () => []);

    const readTokens = () => {
      fg = getComputedStyle(canvas).color;
    };

    /** rejection-sample a position against the ambient density at time t */
    const place = (i: number, t: number) => {
      for (let k = 0; k < SEED_TRIES; k++) {
        const x = rng() * width;
        const y = rng() * height;
        if (rng() < ambient(x, y, t)) {
          px[i] = x;
          py[i] = y;
          return;
        }
      }
      px[i] = rng() * width;
      py[i] = rng() * height;
    };

    const seed = () => {
      // restart the stream so a given size always seeds the same field, even
      // after a resize has already drawn from it
      rng = mulberry32(SEED);
      for (let i = 0; i < n; i++) place(i, 0);
    };

    /** one weighted Lloyd iteration */
    const relax = (t: number, wx: number, wy: number, ws: number) => {
      // (1) rebuild the site hash in place
      heads.fill(-1);
      for (let i = 0; i < n; i++) {
        let cx = (px[i]! / HASH_CELL) | 0;
        let cy = (py[i]! / HASH_CELL) | 0;
        if (cx < 0) cx = 0;
        else if (cx >= hCols) cx = hCols - 1;
        if (cy < 0) cy = 0;
        else if (cy >= hRows) cy = hRows - 1;
        const c = cy * hCols + cx;
        next[i] = heads[c]!;
        heads[c] = i;
      }

      sumW.fill(0);
      sumWX.fill(0);
      sumWY.fill(0);

      // (2) walk the sample lattice, accumulate the weighted Voronoi centroid
      const sCols = Math.ceil(width / SAMPLE_CELL);
      const sRows = Math.ceil(height / SAMPLE_CELL);
      const wellActive = ws > 0.01;
      const inv2s2 = 1 / (2 * WELL_SIGMA * WELL_SIGMA);
      for (let sy = 0; sy < sRows; sy++) {
        const y = sy * SAMPLE_CELL + SAMPLE_CELL / 2;
        const by = (y / HASH_CELL) | 0;
        for (let sx = 0; sx < sCols; sx++) {
          const x = sx * SAMPLE_CELL + SAMPLE_CELL / 2;
          let w = ambient(x, y, t);
          if (wellActive) {
            const dx = x - wx;
            const dy = y - wy;
            w *= 1 + ws * WELL_GAIN * Math.exp(-(dx * dx + dy * dy) * inv2s2);
          }
          if (w <= 0) continue; // the zero regions cost nothing

          const bx = (x / HASH_CELL) | 0;
          let best = -1;
          let bestQ = Infinity;
          const y0 = by > 0 ? by - 1 : 0;
          const y1 = by + 1 < hRows ? by + 1 : hRows - 1;
          const x0 = bx > 0 ? bx - 1 : 0;
          const x1 = bx + 1 < hCols ? bx + 1 : hCols - 1;
          for (let cy = y0; cy <= y1; cy++) {
            const row = cy * hCols;
            for (let cx = x0; cx <= x1; cx++) {
              for (let i = heads[row + cx]!; i !== -1; i = next[i]!) {
                const dx = x - px[i]!;
                const dy = y - py[i]!;
                const q = dx * dx + dy * dy;
                if (q < bestQ) {
                  bestQ = q;
                  best = i;
                }
              }
            }
          }
          if (best === -1) continue;
          sumW[best] += w;
          sumWX[best] += w * x;
          sumWY[best] += w * y;
        }
      }

      // (3) step toward the centroid, or teleport out of a dead zone
      for (let i = 0; i < n; i++) {
        const sw = sumW[i]!;
        if (sw < DEAD_W) {
          place(i, t);
          continue;
        }
        const cx = sumWX[i]! / sw;
        const cy = sumWY[i]! / sw;
        let x = px[i]! + (cx - px[i]!) * STEP;
        let y = py[i]! + (cy - py[i]!) * STEP;
        if (x < 0) x = 0;
        else if (x > width) x = width;
        if (y < 0) y = 0;
        else if (y > height) y = height;
        px[i] = x;
        py[i] = y;
      }
    };

    const draw = (t: number, wx: number, wy: number, ws: number) => {
      if (!sized) return;
      ctx.clearRect(0, 0, width, height);
      for (let b = 0; b < buckets.length; b++) buckets[b]!.length = 0;

      const wellActive = ws > 0.01;
      const inv2s2 = 1 / (2 * WELL_SIGMA * WELL_SIGMA);
      for (let i = 0; i < n; i++) {
        const x = px[i]!;
        const y = py[i]!;
        let r = ambient(x, y, t);
        if (wellActive) {
          const dx = x - wx;
          const dy = y - wy;
          r *= 1 + ws * WELL_GAIN * Math.exp(-(dx * dx + dy * dy) * inv2s2);
        }
        if (r < CULL_RHO) continue;
        if (r > 1) r = 1;
        let b = (r * ALPHAS.length) | 0;
        if (b >= ALPHAS.length) b = ALPHAS.length - 1;
        buckets[b]!.push(i);
      }

      ctx.fillStyle = fg;
      for (let b = 0; b < ALPHAS.length; b++) {
        const list = buckets[b]!;
        if (list.length === 0) continue;
        ctx.globalAlpha = ALPHAS[b]!;
        ctx.beginPath();
        for (let k = 0; k < list.length; k++) {
          const i = list[k]!;
          ctx.moveTo(px[i]! + DOT_R, py[i]!);
          ctx.arc(px[i]!, py[i]!, DOT_R, 0, Math.PI * 2);
        }
        ctx.fill();
      }
      ctx.globalAlpha = 1;
    };

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      if (rect.width < 2 || rect.height < 2) {
        sized = false;
        return;
      }
      width = rect.width;
      height = rect.height;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      hCols = Math.max(1, Math.ceil(width / HASH_CELL));
      hRows = Math.max(1, Math.ceil(height / HASH_CELL));
      heads = new Int32Array(hCols * hRows);
      seed();
      sized = true;
      // warm the field so the very first painted frame is already a settled
      // stipple screen rather than the raw rejection-sampled scatter
      for (let k = 0; k < WARM_MOUNT; k++) relax(0, 0, 0, 0);
    };

    /** reduced motion: settle synchronously, then draw exactly one frame */
    const still = () => {
      if (!sized) return;
      for (let k = 0; k < WARM_ITERS; k++) relax(0, 0, 0, 0);
      draw(0, 0, 0, 0);
    };

    // -- hot-path state -------------------------------------------------------
    let raf = 0;
    let last = 0;
    let t = 0;
    const ptr = { x: 0, y: 0, has: false, s: 0 };

    const loop = (now: number) => {
      const dt = last ? Math.min(DT_MAX, (now - last) / 1000) : 1 / 60;
      last = now;
      t += dt;
      const target = ptr.has ? 1 : 0;
      ptr.s += (target - ptr.s) * Math.min(1, dt / WELL_TAU);
      if (sized) {
        relax(t, ptr.x, ptr.y, ptr.s);
        draw(t, ptr.x, ptr.y, ptr.s);
      }
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    const onPointerMove = (e: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      ptr.x = e.clientX - rect.left;
      ptr.y = e.clientY - rect.top;
      ptr.has = true;
    };
    const onPointerLeave = () => {
      ptr.has = false;
    };

    const onVis = () => {
      if (!document.hidden && !reduced) {
        last = 0;
        cancelAnimationFrame(raf);
        raf = requestAnimationFrame(loop);
      }
    };

    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) draw(0, 0, 0, 0);
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    let lastW = 0;
    let lastH = 0;
    const ro = new ResizeObserver(() => {
      if (disposed) return;
      const rect = canvas.getBoundingClientRect();
      if (
        Math.abs(rect.width - lastW) < 4 &&
        Math.abs(rect.height - lastH) < 4
      ) {
        return;
      }
      lastW = rect.width;
      lastH = rect.height;
      resize();
      if (reduced) still();
    });
    ro.observe(canvas);

    readTokens();
    resize();
    lastW = width;
    lastH = height;
    if (reduced) {
      still();
    } else {
      raf = requestAnimationFrame(loop);
      canvas.addEventListener("pointermove", onPointerMove);
      canvas.addEventListener("pointerleave", onPointerLeave);
      document.addEventListener("visibilitychange", onVis);
    }

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      mo.disconnect();
      ro.disconnect();
      canvas.removeEventListener("pointermove", onPointerMove);
      canvas.removeEventListener("pointerleave", onPointerLeave);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [count]);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden
      className={`block h-full w-full text-foreground ${className}`}
    />
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// TruchetWeave — an ambient Truchet arc weave. Every cell carries one of two
// quarter-arc tiles, and both tilings are edge-compatible (each cell edge is
// crossed at its midpoint), so the arcs join across every boundary into one
// continuous interlaced curve — the classic Truchet "maze of loops". What
// picks the tile is not a coin flip but the SIGN of a slow three-term harmonic
// field, so the frame organises into large soft domains of consistent
// orientation. Sparsity is the other half: stroke alpha falls off with the
// field's DISTANCE FROM ZERO, so cells sitting on the zero set — the domain
// walls, exactly where the orientation is about to flip — fade out entirely
// and the weave reads as torn open along pale seams rather than as a uniform
// mat. The pointer adds a gaussian bias to the field BEFORE the sign test, so
// cells with small |f| flip first: a new domain wall opens as a ring around
// the cursor and re-routes the arcs outward from it, then retreats when the
// pointer leaves.
// ---------------------------------------------------------------------------

const ALPHA_BUCKETS = 5;
const MIN_ALPHA = 0.06; // below this a cell is skipped entirely
const FADE_SCALE = 1.2; // |f| at which a cell reaches full ink
const FADE_POW = 1.6; // steepness of the seam falloff
const ANGLE_A = 0.42; // rad — first harmonic rotation
const ANGLE_B = 1.93; // rad — second harmonic rotation
const BIAS_RADIUS = 5.5; // cells — gaussian sigma of the pointer bias
const BIAS_PEAK = 1.35; // peak added to the field under the pointer
const BIAS_TAU = 0.5; // s — ease-in / relax-back time constant
const BIAS_CUT2 = (BIAS_RADIUS * 4) * (BIAS_RADIUS * 4);
const LINE_WIDTH = 1.25;
const DT_MAX = 1 / 30;

const COS_A = Math.cos(ANGLE_A);
const SIN_A = Math.sin(ANGLE_A);
const SIN_B = Math.sin(ANGLE_B);
const COS_B = Math.cos(ANGLE_B);

const HALF_PI = Math.PI / 2;

/** Three-term harmonic sum evaluated at two fixed rotation angles. */
function field(cx: number, cy: number, t: number): number {
  const u = cx * COS_A + cy * SIN_A;
  const v = -cx * SIN_B + cy * COS_B;
  return (
    Math.sin(u * 0.26 + 0.11 * t) +
    0.7 * Math.sin(v * 0.19 - 0.09 * t) +
    0.45 * Math.sin((u + v) * 0.11 + 0.05 * t)
  );
}

export interface TruchetWeaveProps {
  /** square tile size in px */
  tileSize?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function TruchetWeave({
  tileSize = 28,
  className = "",
}: TruchetWeaveProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    const TILE = Math.max(8, tileSize);
    const R = TILE / 2;

    let fg = "currentColor";
    let cols = 0;
    let rows = 0;
    let sized = false;
    let disposed = false;

    // per-bucket cell-index lists, reused every frame
    const bucketLists: number[][] = Array.from(
      { length: ALPHA_BUCKETS },
      () => []
    );

    const readTokens = () => {
      fg = getComputedStyle(canvas).color;
    };

    const resize = () => {
      const { width, height } = canvas.getBoundingClientRect();
      if (width < 4 || height < 4) {
        sized = false;
        return;
      }
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      cols = Math.max(2, Math.ceil(width / TILE));
      rows = Math.max(2, Math.ceil(height / TILE));
      sized = true;
    };

    const draw = (t: number, px: number, py: number, strength: number) => {
      if (!sized) return;
      ctx.clearRect(0, 0, cols * TILE + TILE, rows * TILE + TILE);

      for (let b = 0; b < ALPHA_BUCKETS; b++) bucketLists[b]!.length = 0;

      const sigma2 = 2 * BIAS_RADIUS * BIAS_RADIUS;
      const biased = strength > 0.01;

      // pass one — classify every cell into an alpha bucket
      let i = 0;
      for (let gy = 0; gy < rows; gy++) {
        for (let gx = 0; gx < cols; gx++, i++) {
          const cx = gx + 0.5;
          const cy = gy + 0.5;
          let f = field(cx, cy, t);
          if (biased) {
            const dx = cx - px;
            const dy = cy - py;
            const d2 = dx * dx + dy * dy;
            if (d2 < BIAS_CUT2) {
              f += BIAS_PEAK * strength * Math.exp(-d2 / sigma2);
            }
          }
          const a = Math.pow(
            Math.min(1, Math.abs(f) / FADE_SCALE),
            FADE_POW
          );
          if (a < MIN_ALPHA) continue;
          const b = Math.min(ALPHA_BUCKETS - 1, Math.floor(a * ALPHA_BUCKETS));
          // sign of the field picks the tile; pack it into the stored index
          bucketLists[b]!.push(f > 0 ? i : -i - 1);
        }
      }

      // pass two — one path, one globalAlpha write and one stroke per bucket
      ctx.strokeStyle = fg;
      ctx.lineWidth = LINE_WIDTH;
      ctx.lineCap = "butt";
      for (let b = 0; b < ALPHA_BUCKETS; b++) {
        const list = bucketLists[b]!;
        if (list.length === 0) continue;
        ctx.beginPath();
        for (let k = 0; k < list.length; k++) {
          const packed = list[k]!;
          const bit = packed >= 0;
          const idx = bit ? packed : -packed - 1;
          const gx = idx % cols;
          const gy = (idx - gx) / cols;
          const x = gx * TILE;
          const y = gy * TILE;
          if (bit) {
            // tile A — arcs centred on the top-left and bottom-right corners
            ctx.moveTo(x + R, y);
            ctx.arc(x, y, R, 0, HALF_PI);
            ctx.moveTo(x + TILE - R, y + TILE);
            ctx.arc(x + TILE, y + TILE, R, Math.PI, Math.PI + HALF_PI);
          } else {
            // tile B — arcs centred on the top-right and bottom-left corners
            ctx.moveTo(x + TILE, y + R);
            ctx.arc(x + TILE, y, R, HALF_PI, Math.PI);
            ctx.moveTo(x, y + TILE - R);
            ctx.arc(x, y + TILE, R, -HALF_PI, 0);
          }
        }
        ctx.globalAlpha = 0.1 + (b / (ALPHA_BUCKETS - 1)) * 0.62;
        ctx.stroke();
      }
      ctx.globalAlpha = 1;
    };

    // -- hot-path state -------------------------------------------------------
    let raf = 0;
    let last = 0;
    let t = 0;
    const ptr = { x: -1e5, y: -1e5, has: false, strength: 0 };

    const loop = (now: number) => {
      const dt = last ? Math.min(DT_MAX, (now - last) / 1000) : 1 / 60;
      last = now;
      t += dt;
      const target = ptr.has ? 1 : 0;
      ptr.strength += (target - ptr.strength) * Math.min(1, dt / BIAS_TAU);
      draw(t, ptr.x, ptr.y, ptr.strength);
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    const onPointerMove = (e: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      ptr.x = (e.clientX - rect.left) / TILE;
      ptr.y = (e.clientY - rect.top) / TILE;
      ptr.has = true;
    };
    const onPointerLeave = () => {
      ptr.has = false;
    };

    const onVis = () => {
      if (!document.hidden && !reduced && !disposed) {
        last = 0;
        cancelAnimationFrame(raf);
        raf = requestAnimationFrame(loop);
      }
    };

    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) draw(0, -1e5, -1e5, 0);
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    const ro = new ResizeObserver(() => {
      resize();
      if (reduced) draw(0, -1e5, -1e5, 0);
    });
    ro.observe(canvas);

    readTokens();
    resize();
    if (reduced) {
      draw(0, -1e5, -1e5, 0);
    } else {
      canvas.addEventListener("pointermove", onPointerMove);
      canvas.addEventListener("pointerleave", onPointerLeave);
      raf = requestAnimationFrame(loop);
    }
    document.addEventListener("visibilitychange", onVis);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      mo.disconnect();
      ro.disconnect();
      canvas.removeEventListener("pointermove", onPointerMove);
      canvas.removeEventListener("pointerleave", onPointerLeave);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [tileSize]);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden
      className={`block h-full w-full text-foreground ${className}`}
    />
  );
}

"use client";

import { useEffect, useId, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// PatinaPip — an unread badge that ages like brass instead of just counting.
// Its data-stage is derived from the newest item's timestamp, not the count:
// fresh (< 1 day) is a solid --foreground fill with background-token digits,
// waning (< 1 week) thins to a transparent fill with a 1.5px --foreground
// ring, dormant (>= 1 week) settles into a 1px --ns-muted ring with --ns-muted
// digits — fill, outline weight and text tone all move together so the three
// stages read apart under monochrome viewing, never by hue alone. Ordinary
// aging (the interval tick, or a prop simply reflecting more elapsed time)
// crossfades those properties over 400ms via a plain CSS transition; new
// activity is different in kind, not degree, so it's fast-pathed around that
// transition (a one-frame transitionDuration:0 clamp) straight to "fresh"
// and topped with a 200ms spring-eased scale(1 → 1.12 → 1) flare via the Web
// Animations API, so re-polish always reads as instantaneous, not eased.
// The pip itself is decorative (role="img", not a control) — the accessible
// name lives on it as an aria-label ("3 unread, newest 2 days ago") for a
// focusable nav item to pull in via aria-describedby, and a visually-hidden
// aria-live region separately announces new arrivals as they happen. Pure
// DOM + CSS, zero dependencies, no canvas.
// ---------------------------------------------------------------------------

export type PatinaPipStage = "fresh" | "waning" | "dormant";

export interface PatinaPipProps {
  /** unread item count. Incidental to the component's point — see newestTimestamp. */
  count: number;
  /** timestamp of the newest unread item; the sole driver of the tarnish stage. */
  newestTimestamp: number | Date;
  /** id placed on the pip itself, e.g. so a nav item can aria-describedby it. Defaults to an internal useId. */
  id?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const MINUTE_MS = 60_000;
const HOUR_MS = 60 * MINUTE_MS;
const DAY_MS = 24 * HOUR_MS;
const WEEK_MS = 7 * DAY_MS;

// how often the pip re-checks its own age while mounted, so a badge left
// open on screen tarnishes on its own without any new prop ever arriving.
const TICK_MS = MINUTE_MS;

const FLARE_KEYFRAMES: Keyframe[] = [
  { transform: "scale(1)" },
  { transform: "scale(1.12)", offset: 0.5 },
  { transform: "scale(1)" },
];
const FLARE_OPTIONS: KeyframeAnimationOptions = {
  duration: 200,
  easing: "cubic-bezier(0.34, 1.56, 0.64, 1)", // spring-like overshoot, not linear/ease
};

function toMs(ts: number | Date): number {
  return ts instanceof Date ? ts.getTime() : ts;
}

function computeStage(ageMs: number): PatinaPipStage {
  if (ageMs < DAY_MS) return "fresh";
  if (ageMs < WEEK_MS) return "waning";
  return "dormant";
}

function formatAge(ageMs: number): string {
  const ms = Math.max(0, ageMs);
  if (ms < MINUTE_MS) return "just now";
  if (ms < HOUR_MS) {
    const m = Math.round(ms / MINUTE_MS);
    return `${m} minute${m === 1 ? "" : "s"} ago`;
  }
  if (ms < DAY_MS) {
    const h = Math.round(ms / HOUR_MS);
    return `${h} hour${h === 1 ? "" : "s"} ago`;
  }
  if (ms < WEEK_MS) {
    const d = Math.round(ms / DAY_MS);
    return `${d} day${d === 1 ? "" : "s"} ago`;
  }
  const w = Math.round(ms / WEEK_MS);
  return `${w} week${w === 1 ? "" : "s"} ago`;
}

function useReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

const STAGE_CLASSES: Record<PatinaPipStage, string> = {
  fresh: "bg-foreground text-background border border-foreground font-semibold",
  waning: "bg-transparent text-foreground border-[1.5px] border-foreground font-medium",
  dormant: "bg-transparent text-ns-muted border border-ns-muted font-normal",
};

const BASE_CLASSES =
  "ns-badge-unread-tarnish inline-flex h-5 min-w-[1.25rem] items-center justify-center rounded-full px-1.5 font-mono text-[11px] leading-none tabular-nums select-none transition-[background-color,border-color,color,border-width] duration-[400ms] ease-out";

export function PatinaPip({ count, newestTimestamp, id, className }: PatinaPipProps) {
  const autoId = useId();
  const pipId = id ?? autoId;
  const nodeRef = useRef<HTMLSpanElement>(null);
  const prevTsRef = useRef(toMs(newestTimestamp));
  const mountedRef = useRef(false);
  const reducedMotion = useReducedMotion();

  // SSR-safe placeholder: never reads Date.now() during render (server and
  // client's pre-effect render must match exactly), corrected to the real
  // elapsed age the moment effects can run on the client.
  const [ageMs, setAgeMs] = useState(0);
  const [announcement, setAnnouncement] = useState("");

  useEffect(() => {
    const ts = toMs(newestTimestamp);

    if (!mountedRef.current) {
      // first client-side pass after hydration: adopt the real elapsed time
      // silently, no crossfade suppression and no flare — this is settling
      // in, not new activity.
      mountedRef.current = true;
      prevTsRef.current = ts;
      setAgeMs(Math.max(0, Date.now() - ts));
      return;
    }

    const prev = prevTsRef.current;
    prevTsRef.current = ts;
    const isNewer = ts > prev;
    const nextAge = Math.max(0, Date.now() - ts);

    if (isNewer) {
      const node = nodeRef.current;
      // clamp the transition to instant for exactly this update, so the
      // reset to "fresh" reads as a snap, not a 400ms crossfade — then
      // restore normal crossfade timing for whatever ages naturally next.
      if (node) node.style.transitionDuration = "0s";
      setAgeMs(nextAge);
      setAnnouncement(`New unread activity, ${count} unread`);
      requestAnimationFrame(() => {
        if (node) node.style.transitionDuration = "";
        if (node && !reducedMotion) node.animate(FLARE_KEYFRAMES, FLARE_OPTIONS);
      });
    } else {
      setAgeMs(nextAge);
    }
  }, [newestTimestamp, count, reducedMotion]);

  useEffect(() => {
    const tick = window.setInterval(() => {
      setAgeMs(Math.max(0, Date.now() - prevTsRef.current));
    }, TICK_MS);
    return () => window.clearInterval(tick);
  }, []);

  if (count <= 0) return null;

  const stage = computeStage(ageMs);
  const label = `${count} unread, newest ${formatAge(ageMs)}`;

  return (
    <>
      <span
        ref={nodeRef}
        id={pipId}
        role="img"
        aria-label={label}
        data-stage={stage}
        className={[BASE_CLASSES, STAGE_CLASSES[stage], className].filter(Boolean).join(" ")}
      >
        <span aria-hidden="true">{count}</span>
      </span>
      {/* async re-polish announcements — the resting description above already
          covers "how stale", this only ever speaks up when new mail lands */}
      <span aria-live="polite" className="sr-only">
        {announcement}
      </span>
    </>
  );
}

"use client";

import { useCallback, useEffect, useId, useRef, useState, type ReactNode } from "react";

// ---------------------------------------------------------------------------
// TearStub — a dismissible notice with a perforated edge, 32px in from the
// leading edge. Dismissing tears the panel off along that perforation with a
// quick ~1deg rip (translate + rotate + fade, ease-out-expo) while a slim
// stub stays seated flush at the edge — a permanent, always-legible record
// that a notice exists, exactly like the stub a receipt book keeps after the
// check tears out. Clicking the stub reopens the banner, reversing the rip
// and springing the row's height back open. The stub itself is always
// present as decoration while attached (just the icon, non-interactive) and
// is promoted into the Reopen button only once the panel is actually gone —
// so there is never a pointless enabled control sitting idle at rest.
//
// Differs from truncation-word-count on purpose: that folds content away in place and
// keeps the same object at a smaller size. Here the remainder is a distinct,
// much smaller object (a torn stub, not a folded panel) and the physical
// contract is that the record is never destroyed, only shrunk — dismissal
// is always recoverable.
//
// This component doesn't force a width — it's an inline flex row sized to
// its content. Pass className="w-full" for a page-width banner; either way,
// once the panel is torn off, only the stub column remains in the row, so
// the whole thing naturally shrinks down to a small tab rather than leaving
// a wide empty strip.
//
// DOM + CSS only, no canvas. Colors come from --background/--surface/
// --foreground/--ns-muted/--border/--ns-accent only. prefers-reduced-motion swaps
// the rip for a plain crossfade (handled by the stylesheet below) and the
// height change for a short linear resize instead of a spring (handled in
// JS, since a spring is inherently a physical motion).
// ---------------------------------------------------------------------------

const TEAR_MS = 300;
const TEAR_MS_REDUCED = 160;
const TEAR_EASE = "cubic-bezier(0.22, 1, 0.36, 1)"; // ease-out-expo-ish
const SPRING_STIFFNESS = 230; // s^-2
const SPRING_DAMPING = 26; // ~critically damped, one barely-visible settle
const STUB_HIT_OVERHANG = 6; // each side of the 32px (w-8) column — 44px touch target

function NoticeIcon({ urgent, className }: { urgent: boolean; className?: string }) {
  if (urgent) {
    return (
      <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.3" className={className} aria-hidden="true">
        <path d="M8 1.6 14.6 13a1 1 0 0 1-.87 1.5H2.27a1 1 0 0 1-.87-1.5L8 1.6Z" strokeLinejoin="round" />
        <path d="M8 6.2v3.1" strokeLinecap="round" />
        <circle cx="8" cy="11.4" r="0.75" fill="currentColor" stroke="none" />
      </svg>
    );
  }
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.3" className={className} aria-hidden="true">
      <circle cx="8" cy="8" r="6.3" />
      <path d="M8 7.3v3.9" strokeLinecap="round" />
      <circle cx="8" cy="4.9" r="0.75" fill="currentColor" stroke="none" />
    </svg>
  );
}

/** Physically integrates a height spring from `from` px to `to` px onto
 * `el.style.height`, then hands the element back to `auto` sizing once
 * settled. Returns a cancel fn — call it if another transition preempts
 * this one mid-flight. */
function springHeight(el: HTMLElement, from: number, to: number, onSettle?: () => void): () => void {
  let current = from;
  let velocity = 0;
  let last: number | null = null;
  let raf = 0;
  let cancelled = false;
  el.style.overflow = "hidden";
  el.style.height = `${from}px`;
  const step = (now: number) => {
    if (cancelled) return;
    if (last == null) last = now;
    const dt = Math.min((now - last) / 1000, 0.032);
    last = now;
    const disp = current - to;
    const accel = -SPRING_STIFFNESS * disp - SPRING_DAMPING * velocity;
    velocity += accel * dt;
    current += velocity * dt;
    if (Math.abs(disp) < 0.4 && Math.abs(velocity) < 0.4) {
      el.style.height = "";
      el.style.overflow = "";
      onSettle?.();
      return;
    }
    el.style.height = `${current}px`;
    raf = requestAnimationFrame(step);
  };
  raf = requestAnimationFrame(step);
  return () => {
    cancelled = true;
    cancelAnimationFrame(raf);
  };
}

/** Reduced-motion counterpart: no bounce, one short linear resize. */
function snapHeight(el: HTMLElement, to: number, onSettle?: () => void): () => void {
  let cancelled = false;
  el.style.overflow = "hidden";
  el.style.height = `${el.getBoundingClientRect().height}px`;
  el.style.transition = "";
  const raf = requestAnimationFrame(() => {
    if (cancelled) return;
    el.style.transition = `height ${TEAR_MS_REDUCED}ms linear`;
    el.style.height = `${to}px`;
  });
  const done = (e: TransitionEvent) => {
    if (e.propertyName !== "height") return;
    finish();
  };
  const finish = () => {
    if (cancelled) return;
    cancelled = true;
    el.style.transition = "";
    el.style.height = "";
    el.style.overflow = "";
    el.removeEventListener("transitionend", done);
    onSettle?.();
  };
  el.addEventListener("transitionend", done);
  return () => {
    cancelled = true;
    cancelAnimationFrame(raf);
    el.removeEventListener("transitionend", done);
  };
}

export interface TearStubProps {
  /** The notice's title. Also becomes the stub's accessible name once torn
   * off ("Reopen: <title>"). */
  title: string;
  /** Supporting copy shown under the title. */
  description?: ReactNode;
  /** Swaps role=status for role=alert and the default icon for the more
   * severe glyph. @default "info" */
  variant?: "info" | "urgent";
  /** Custom icon replacing the built-in glyph. Always rendered aria-hidden —
   * the accessible name comes from `title` and `dismissLabel`, not the icon. */
  icon?: ReactNode;
  /** Controlled open state. Omit to let the component manage its own. */
  open?: boolean;
  /** Initial open state when uncontrolled. @default true */
  defaultOpen?: boolean;
  /** Fires after a dismiss or a reopen, from a click or the keyboard. */
  onOpenChange?: (open: boolean) => void;
  /** Accessible name (and visible label) for the dismiss control. @default "Dismiss" */
  dismissLabel?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function TearStub({
  title,
  description,
  variant = "info",
  icon,
  open: openProp,
  defaultOpen = true,
  onOpenChange,
  dismissLabel = "Dismiss",
  className = "",
}: TearStubProps) {
  const isControlled = openProp !== undefined;
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const open = isControlled ? openProp : internalOpen;

  const setOpen = useCallback(
    (next: boolean) => {
      if (!isControlled) setInternalOpen(next);
      onOpenChange?.(next);
    },
    [isControlled, onOpenChange]
  );

  // `panelMounted` lags `open` on the way to false, so the rip gets to play
  // out (panel still occupying its layout box, just transformed) before the
  // panel actually leaves flow. `torn` drives the CSS transform/opacity —
  // kept a beat ahead of `panelMounted` on the way back in, so a freshly
  // remounted panel starts already in its torn pose and animates *out* of
  // it, rather than popping in already settled.
  const [panelMounted, setPanelMounted] = useState(open);
  const [torn, setTorn] = useState(!open);

  const containerRef = useRef<HTMLDivElement>(null);
  const stubRef = useRef<HTMLButtonElement>(null);
  const dismissRef = useRef<HTMLButtonElement>(null);
  const prevOpenRef = useRef(open);
  const firstRenderRef = useRef(true);
  const cancelHeightRef = useRef<(() => void) | null>(null);
  const tearTimeoutRef = useRef<number | undefined>(undefined);

  const titleId = useId();
  const hintId = useId();

  useEffect(
    () => () => {
      cancelHeightRef.current?.();
      window.clearTimeout(tearTimeoutRef.current);
    },
    []
  );

  useEffect(() => {
    if (firstRenderRef.current) {
      firstRenderRef.current = false;
      prevOpenRef.current = open;
      return; // no animation on mount, whichever state it mounts into
    }
    if (prevOpenRef.current === open) return;
    prevOpenRef.current = open;

    const container = containerRef.current;
    if (!container) return;
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    cancelHeightRef.current?.();
    window.clearTimeout(tearTimeoutRef.current);

    if (!open) {
      // DISMISS — rip the panel in place first (it's still in flow, so the
      // row doesn't move yet), then drop it from the DOM and spring the row
      // down to the stub's own height. The pre-unmount height must be read
      // BEFORE setPanelMounted(false): the container has no explicit height,
      // so by the post-render rAF it has already collapsed and the spring
      // would be a from==to no-op.
      setTorn(true);
      const tearMs = reduced ? TEAR_MS_REDUCED : TEAR_MS;
      tearTimeoutRef.current = window.setTimeout(() => {
        const from = containerRef.current?.getBoundingClientRect().height ?? 0;
        setPanelMounted(false);
        requestAnimationFrame(() => {
          const el = containerRef.current;
          if (!el) return;
          const to = el.scrollHeight; // natural height now that the panel is gone
          cancelHeightRef.current = reduced
            ? snapHeight(el, to, () => stubRef.current?.focus())
            : springHeight(el, from, to, () => stubRef.current?.focus());
        });
      }, tearMs);
    } else {
      // REOPEN — remount the panel already torn (no visible jump), spring
      // the row back open, then flip `torn` off a frame later to play the
      // rip in reverse.
      setPanelMounted(true);
      requestAnimationFrame(() => {
        const el = containerRef.current;
        if (!el) return;
        const from = el.getBoundingClientRect().height;
        const to = el.scrollHeight; // natural height with the panel back
        cancelHeightRef.current = reduced
          ? snapHeight(el, to, () => dismissRef.current?.focus())
          : springHeight(el, from, to, () => dismissRef.current?.focus());
        requestAnimationFrame(() => setTorn(false));
      });
    }
  }, [open]);

  const urgent = variant === "urgent";
  const iconNode = icon ?? <NoticeIcon urgent={urgent} className={`h-4 w-4 shrink-0 ${urgent ? "text-foreground" : "text-ns-muted"}`} />;

  return (
    <div
      ref={containerRef}
      // Static for the component's lifetime, not toggled per dismiss/reopen —
      // re-mounting the role every interaction is what would turn a one-time
      // "here's a notice" announcement into noise on every tear and heal.
      role={urgent ? "alert" : "status"}
      aria-live={urgent ? "assertive" : "polite"}
      aria-labelledby={panelMounted ? titleId : undefined}
      // When torn, cap the box at its content (the stub column) even if the
      // consumer passed w-full — the promise is a small tab, never a wide
      // empty strip. Cleared in the same commit that remounts the panel, so
      // the reopen measurement sees the full-width layout.
      style={panelMounted ? undefined : { maxWidth: "fit-content" }}
      className={`ns-tearstub relative inline-flex items-stretch rounded-md border border-border bg-background text-foreground ${className}`}
    >
      <div className="relative w-8 shrink-0 self-stretch">
        {panelMounted ? (
          <div aria-hidden="true" className="flex h-full w-full items-center justify-center">
            {iconNode}
          </div>
        ) : (
          <button
            ref={stubRef}
            type="button"
            onClick={() => setOpen(true)}
            aria-label={`Reopen: ${title}`}
            data-tearstub-reopen=""
            // In flow (not absolute): the stub is the only content left in
            // the row once the panel is gone, so it must contribute real
            // height — absolutely positioned it contributed none and the
            // whole notice collapsed to a flat border line. Negative x
            // margins keep the 44px touch target overhanging the 32px look.
            className="ns-tearstub-stub relative flex min-h-11 w-11 flex-col items-center justify-center gap-1.5 rounded-sm p-1 py-2 outline-none transition-colors hover:bg-foreground/[0.06] focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-inset"
            style={{ marginLeft: -STUB_HIT_OVERHANG, marginRight: -STUB_HIT_OVERHANG }}
          >
            {iconNode}
            <span aria-hidden="true" className="ns-tearstub-label select-none font-mono text-[9px] uppercase tracking-widest text-ns-muted">
              {title}
            </span>
          </button>
        )}
        <span aria-hidden="true" className="ns-tearstub-perf pointer-events-none absolute inset-y-0 right-0 w-px" />
      </div>

      {panelMounted && (
        <div data-torn={torn ? "" : undefined} className="ns-tearstub-panel flex flex-1 items-start gap-3 px-4 py-3.5">
          <div className="min-w-0 flex-1">
            <p id={titleId} className="text-sm font-medium leading-snug">
              {title}
            </p>
            {description && <p className="mt-1 text-sm leading-relaxed text-ns-muted">{description}</p>}
          </div>
          <button
            ref={dismissRef}
            type="button"
            onClick={() => setOpen(false)}
            aria-describedby={hintId}
            data-tearstub-dismiss=""
            className="shrink-0 rounded-sm px-2.5 py-1.5 font-mono text-[11px] uppercase tracking-wide text-ns-muted outline-none transition-colors hover:bg-foreground/[0.06] hover:text-foreground focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-inset"
          >
            {dismissLabel}
          </button>
          <span id={hintId} className="sr-only">
            A small tab stays after dismissing so you can reopen this notice.
          </span>
        </div>
      )}

      <style>{`
        .ns-tearstub-perf {
          background: var(--border);
          -webkit-mask-image: repeating-linear-gradient(to bottom, black 0 5px, transparent 5px 8px);
          mask-image: repeating-linear-gradient(to bottom, black 0 5px, transparent 5px 8px);
        }
        .ns-tearstub-label {
          writing-mode: vertical-rl;
          transform: rotate(180deg);
          max-height: 60px;
          overflow: hidden;
          white-space: nowrap; /* one vertical column — wrapping crowds the 32px stub */
        }
        .ns-tearstub-panel {
          transition: transform ${TEAR_MS}ms ${TEAR_EASE}, opacity ${TEAR_MS}ms ${TEAR_EASE};
          transform: translateX(0) rotate(0deg);
          opacity: 1;
        }
        .ns-tearstub-panel[data-torn] {
          transform: translateX(24px) rotate(1deg);
          opacity: 0;
        }
        @media (prefers-reduced-motion: reduce) {
          .ns-tearstub-panel {
            transition: opacity ${TEAR_MS_REDUCED}ms linear;
          }
          .ns-tearstub-panel[data-torn] {
            transform: none;
          }
        }
      `}</style>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// BarographDrumWeek — an ambient "running continuously, unattended" status
// widget modelled on the aneroid barograph: a clockwork drum turns once per
// week under a pen arm, wrapped in chart paper that already carries the day
// and hour ruling PRINTED IN ADVANCE — the pen only ever adds ink, it never
// draws the grid. This build compresses the real 7-day/604,800s drum period
// into a 45s loop (documented ratio ~1 app-second : 3.7 real hours).
//
// Two canvases stand in for the two physical layers: a grid canvas holds the
// pre-ruled paper (7 day dividers, full height; 23 hour ticks per day, drawn
// as SHORT marks at the top/bottom edges only so 168 ticks read as a faint
// structural ruling rather than a solid mesh) and is only ever redrawn on
// resize/token change, never per-frame. An ink canvas accumulates the trace
// by drawing ONE new line segment per frame from the previous point to the
// current one — it is never cleared mid-cycle, matching the "permanent
// trace" identity of the recording-instrument family, and every point is
// also kept in a small history array so a resize (which invalidates a
// canvas's raster) can losslessly replot the whole trace at the new pixel
// size instead of losing it.
//
// The trace itself is two incommensurate sine terms — a slow "weather
// front" swing (randomized 8-14s period per cycle, amplitude +/-30% of
// chart height) plus a faster secondary term for texture — with a bounded
// per-frame random-walk micro-jitter (+/-0.3px) layered on top for capsule-
// response noise. The pen arm is a real DOM element (never canvas) pivoting
// from its own tip, positioned by trigonometry from the SAME xFrac/yFrac
// value that was just pushed into the ink history, so the two can never
// desync. At the 45s mark the ink layer (canvas + pen) crossfades to
// transparent over 500ms, the point history clears, a fresh randomized
// front is drawn, and the cycle resumes at the empty day-0 state — a fade,
// never a hard cut.
// ---------------------------------------------------------------------------

const DAYS = 7;
const HOURS_PER_DAY = 24;
const LOOP_MS = 45_000; // compressed 7-day drum period
const CROSSFADE_MS = 500; // loop-end fade back to day 0
const TICK_LEN_FRAC = 0.09; // hour-tick length as a fraction of chart height
const AMPLITUDE_FRAC = 0.3; // weather-front swing, +/-30% of chart height
const FRONT_PERIOD_MIN = 8; // seconds — randomized primary front period
const FRONT_PERIOD_MAX = 14;
const JITTER_STEP = 0.6; // px — per-frame random-walk increment
const JITTER_MAX = 0.3; // px — capsule micro-jitter clamp
const STATIC_DAY = 4; // reduced-motion freeze: day 4 of 7 (~57% across)

interface Front {
  t1: number;
  p1: number;
  t2: number;
  p2: number;
}

interface Point {
  /** 0..1 across the full 7-day chart width */
  x: number;
  /** 0..1 down the chart height */
  y: number;
}

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function makeFront(rand: () => number): Front {
  const t1 = FRONT_PERIOD_MIN + rand() * (FRONT_PERIOD_MAX - FRONT_PERIOD_MIN);
  const p1 = rand() * Math.PI * 2;
  const t2 = t1 * (0.32 + rand() * 0.14); // unrelated secondary period, for texture
  const p2 = rand() * Math.PI * 2;
  return { t1, p1, t2, p2 };
}

function frontValue(tSec: number, f: Front): number {
  const v =
    0.66 * Math.sin((2 * Math.PI * tSec) / f.t1 + f.p1) +
    0.34 * Math.sin((2 * Math.PI * tSec) / f.t2 + f.p2);
  return Math.max(-1, Math.min(1, v));
}

interface Tokens {
  fg: string;
  border: string;
  muted: string;
}

function readTokens(): Tokens | null {
  if (typeof document === "undefined") return null;
  const cs = getComputedStyle(document.documentElement);
  const fg = cs.getPropertyValue("--foreground").trim();
  const border = cs.getPropertyValue("--border").trim();
  const muted = cs.getPropertyValue("--ns-muted").trim();
  if (!fg || !border || !muted) return null; // not loaded yet — no paint before this
  return { fg, border, muted };
}

export interface BarographDrumWeekProps {
  /** small mono label above the chart, e.g. the metric this trace tracks */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function BarographDrumWeek({
  label = "STATION UPTIME — 7 DAY TRACE",
  className = "",
}: BarographDrumWeekProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const chartWrapRef = useRef<HTMLDivElement>(null);
  const gridCanvasRef = useRef<HTMLCanvasElement>(null);
  const inkWrapRef = useRef<HTMLDivElement>(null);
  const inkCanvasRef = useRef<HTMLCanvasElement>(null);
  const penRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const chartWrap = chartWrapRef.current;
    const gridCanvas = gridCanvasRef.current;
    const inkWrap = inkWrapRef.current;
    const inkCanvas = inkCanvasRef.current;
    const pen = penRef.current;
    if (!chartWrap || !gridCanvas || !inkWrap || !inkCanvas || !pen) return;
    const gctx = gridCanvas.getContext("2d");
    const ictx = inkCanvas.getContext("2d");
    if (!gctx || !ictx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let disposed = false;
    let tokens: Tokens | null = null;
    let dpr = 1;
    let chartW = 0;
    let chartH = 0;
    let sized = false;
    let visible = true;

    const points: Point[] = [];
    let cycleStart = 0;
    let phase: "run" | "fade" = "run";
    let fadeStart = 0;
    let front = makeFront(Math.random);
    let jitterPx = 0;

    let raf = 0;
    let tokenWaitRaf = 0;

    const fitCanvas = (canvas: HTMLCanvasElement) => {
      canvas.width = Math.max(1, Math.round(chartW * dpr));
      canvas.height = Math.max(1, Math.round(chartH * dpr));
      const ctx = canvas.getContext("2d");
      ctx?.setTransform(dpr, 0, 0, dpr, 0, 0);
    };

    const drawGrid = () => {
      if (!tokens || !sized) return;
      gctx.clearRect(0, 0, chartW, chartH);

      // day dividers: only 7 lines, so a low-alpha --ns-muted stroke still
      // reads as a sparse ruling rather than a fill — --border alone is
      // near-invisible against the light-theme background (~1.1:1) and
      // these 7 lines are what carries the spec's 6.4s legibility beat, so
      // they get just enough weight to stay countable at a glance.
      gctx.strokeStyle = tokens.muted;
      gctx.globalAlpha = 0.32;
      gctx.lineWidth = 1;
      gctx.beginPath();
      for (let d = 0; d <= DAYS; d++) {
        const x = Math.round((d / DAYS) * chartW) + 0.5;
        gctx.moveTo(x, 0);
        gctx.lineTo(x, chartH);
      }
      gctx.stroke();
      gctx.globalAlpha = 1;

      // hour ticks: plain --border at its designed near-invisible role,
      // and short marks at the top/bottom edges only, never a full-height
      // line — this is what keeps 7x24 = 168 ticks a faint ruling instead
      // of a visible mesh.
      gctx.strokeStyle = tokens.border;
      const tickLen = chartH * TICK_LEN_FRAC;
      gctx.beginPath();
      for (let d = 0; d < DAYS; d++) {
        for (let h = 1; h < HOURS_PER_DAY; h++) {
          const x = Math.round(((d + h / HOURS_PER_DAY) / DAYS) * chartW) + 0.5;
          gctx.moveTo(x, 0);
          gctx.lineTo(x, tickLen);
          gctx.moveTo(x, chartH - tickLen);
          gctx.lineTo(x, chartH);
        }
      }
      gctx.stroke();
    };

    const redrawInk = () => {
      if (!tokens || !sized) return;
      ictx.clearRect(0, 0, chartW, chartH);
      if (points.length === 0) return;
      ictx.strokeStyle = tokens.fg;
      ictx.lineWidth = Math.max(1, Math.min(chartW, chartH) * 0.006);
      ictx.lineJoin = "round";
      ictx.lineCap = "round";
      if (points.length === 1) {
        const p = points[0]!;
        ictx.beginPath();
        ictx.arc(p.x * chartW, p.y * chartH, ictx.lineWidth / 2, 0, Math.PI * 2);
        ictx.fillStyle = tokens.fg;
        ictx.fill();
        return;
      }
      ictx.beginPath();
      points.forEach((p, i) => {
        const x = p.x * chartW;
        const y = p.y * chartH;
        if (i === 0) ictx.moveTo(x, y);
        else ictx.lineTo(x, y);
      });
      ictx.stroke();
    };

    // -- pen arm: a real DOM element, pivoting from its own tip, positioned
    // from the exact same (xFrac, yFrac) that was just pushed into the ink
    // history — the single source of truth shared with the canvas draw, so
    // the two can never drift apart. ---------------------------------------
    const positionPen = (xFrac: number, yFrac: number, angleRad: number) => {
      const x = xFrac * chartW;
      const y = yFrac * chartH;
      const armLen = Math.max(10, Math.min(chartW, chartH) * 0.16);
      pen.style.width = `${armLen}px`;
      pen.style.transform = `translate(${(x - armLen).toFixed(2)}px, ${(y - 1).toFixed(2)}px) rotate(${angleRad.toFixed(3)}rad)`;
    };

    const angleBetween = (a: Point, b: Point): number => {
      const dx = (b.x - a.x) * chartW;
      const dy = (b.y - a.y) * chartH;
      if (Math.abs(dx) < 0.0001 && Math.abs(dy) < 0.0001) return 0;
      return Math.max(-0.6, Math.min(0.6, Math.atan2(dy, dx || 0.0001)));
    };

    const drawFrameSegment = (prev: Point | undefined, next: Point) => {
      if (!tokens || !sized) return;
      ictx.strokeStyle = tokens.fg;
      ictx.lineWidth = Math.max(1, Math.min(chartW, chartH) * 0.006);
      ictx.lineCap = "round";
      if (prev) {
        ictx.beginPath();
        ictx.moveTo(prev.x * chartW, prev.y * chartH);
        ictx.lineTo(next.x * chartW, next.y * chartH);
        ictx.stroke();
      } else {
        ictx.beginPath();
        ictx.arc(next.x * chartW, next.y * chartH, ictx.lineWidth / 2, 0, Math.PI * 2);
        ictx.fillStyle = tokens.fg;
        ictx.fill();
      }
    };

    const stepFrame = (elapsedMs: number) => {
      const xFrac = Math.min(1, elapsedMs / LOOP_MS);
      const tSec = elapsedMs / 1000;
      const val = frontValue(tSec, front);
      jitterPx += (Math.random() - 0.5) * JITTER_STEP;
      jitterPx = Math.max(-JITTER_MAX, Math.min(JITTER_MAX, jitterPx));
      const jitterFrac = chartH > 0 ? jitterPx / chartH : 0;
      const yFrac = Math.min(1, Math.max(0, 0.5 - AMPLITUDE_FRAC * val + jitterFrac));
      const prev = points[points.length - 1];
      const next: Point = { x: xFrac, y: yFrac };
      points.push(next);
      drawFrameSegment(prev, next);
      positionPen(xFrac, yFrac, prev ? angleBetween(prev, next) : 0);
    };

    const resizeAll = () => {
      if (!tokens) return;
      const rect = chartWrap.getBoundingClientRect();
      if (rect.width < 4 || rect.height < 4) {
        sized = false;
        return;
      }
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      chartW = rect.width;
      chartH = rect.height;
      fitCanvas(gridCanvas);
      fitCanvas(inkCanvas);
      sized = true;
      drawGrid();
      redrawInk();
      const last = points[points.length - 1];
      if (last) {
        const prev = points[points.length - 2] ?? last;
        positionPen(last.x, last.y, angleBetween(prev, last));
      } else {
        positionPen(0, 0.5, 0);
      }
    };

    const buildStaticFrame = () => {
      // fully deterministic — reduced motion must render the same frozen
      // day-4 frame every time, never a random draw.
      const rand = mulberry32(0xba206);
      const staticFront = makeFront(rand);
      const xFracEnd = STATIC_DAY / DAYS;
      const samples = 220;
      for (let i = 0; i <= samples; i++) {
        const xFrac = (i / samples) * xFracEnd;
        const tSec = xFrac * (LOOP_MS / 1000);
        const val = frontValue(tSec, staticFront);
        const yFrac = Math.min(1, Math.max(0, 0.5 - AMPLITUDE_FRAC * val));
        points.push({ x: xFrac, y: yFrac });
      }
    };

    const loop = (now: number) => {
      if (disposed) return;
      if (!visible) {
        raf = 0; // IntersectionObserver re-arms this on re-entering view
        return;
      }
      raf = requestAnimationFrame(loop);
      if (!sized || !tokens) return;
      if (cycleStart === 0) cycleStart = now;
      if (phase === "run") {
        const elapsed = now - cycleStart;
        if (elapsed >= LOOP_MS) {
          phase = "fade";
          fadeStart = now;
          inkWrap.style.transition = `opacity ${CROSSFADE_MS}ms ease`;
          inkWrap.style.opacity = "0";
        } else {
          stepFrame(elapsed);
        }
      } else {
        if (now - fadeStart >= CROSSFADE_MS) {
          points.length = 0;
          ictx.clearRect(0, 0, chartW, chartH);
          front = makeFront(Math.random);
          jitterPx = 0;
          cycleStart = now;
          phase = "run";
          inkWrap.style.transition = "none";
          inkWrap.style.opacity = "1";
          void inkWrap.offsetHeight; // flush before the next transition arms
          positionPen(0, 0.5, 0);
        }
      }
    };

    // -- kickoff, retried from every path that can newly satisfy its
    // preconditions (mount, ResizeObserver, MutationObserver) rather than
    // attempted once at mount and abandoned — a container that is 0px wide
    // on first layout (lazy-mounted preview frame, display:none ancestor,
    // collapsed panel) must still start the moment it gets real size. -----
    let started = false;
    const kick = () => {
      if (started || disposed || !tokens || !sized) return;
      started = true;
      if (reduced) {
        buildStaticFrame();
        drawGrid();
        redrawInk();
        const last = points[points.length - 1];
        const prev = points[points.length - 2] ?? last;
        if (last && prev) positionPen(last.x, last.y, angleBetween(prev, last));
        return; // no rAF loop, no timers, no observers driving motion
      }
      raf = requestAnimationFrame(loop);
    };

    const start = () => {
      if (disposed) return;
      tokens = readTokens();
      if (!tokens) {
        tokenWaitRaf = requestAnimationFrame(start);
        return;
      }
      resizeAll();
      kick();
    };

    const ro = new ResizeObserver(() => {
      if (!tokens) return;
      resizeAll();
      kick();
    });
    ro.observe(chartWrap);

    const mo = new MutationObserver(() => {
      tokens = readTokens();
      if (tokens) {
        resizeAll();
        kick();
      }
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    const io = new IntersectionObserver((entries) => {
      const wasVisible = visible;
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && !wasVisible && !reduced && tokens && !raf) {
        tokens = readTokens() ?? tokens; // pick up any theme flip that happened while hidden
        resizeAll();
        // restart the cycle rather than resuming mid-flight — an arbitrarily
        // long time off-screen must not fade out a nearly-empty chart on
        // the very next frame back.
        points.length = 0;
        ictx.clearRect(0, 0, chartW, chartH);
        front = makeFront(Math.random);
        jitterPx = 0;
        cycleStart = 0;
        phase = "run";
        inkWrap.style.transition = "none";
        inkWrap.style.opacity = "1";
        positionPen(0, 0.5, 0);
        raf = requestAnimationFrame(loop);
      }
    });
    io.observe(chartWrap);

    start();

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      cancelAnimationFrame(tokenWaitRaf);
      ro.disconnect();
      mo.disconnect();
      io.disconnect();
    };
  }, []);

  return (
    <div
      ref={rootRef}
      className={`relative w-full max-w-sm overflow-hidden rounded-md border border-border bg-surface p-4 ${className}`}
    >
      <div className="mb-3 flex items-center justify-between gap-2">
        <p className="truncate font-mono text-[11px] tracking-widest text-ns-muted">{label}</p>
        <p className="shrink-0 font-mono text-[10px] tracking-widest text-ns-muted">7-DAY</p>
      </div>
      <div ref={chartWrapRef} className="relative w-full" style={{ aspectRatio: "2.2 / 1" }}>
        <canvas
          ref={gridCanvasRef}
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 h-full w-full"
        />
        <div ref={inkWrapRef} className="absolute inset-0" style={{ opacity: 1 }}>
          <canvas
            ref={inkCanvasRef}
            aria-hidden="true"
            className="pointer-events-none absolute inset-0 h-full w-full"
          />
          <div
            ref={penRef}
            aria-hidden="true"
            className="pointer-events-none absolute left-0 top-0 h-[2px] origin-right bg-foreground"
          />
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// BiasHysteresis — a level/capacity gauge rendered as an analog tape deck's
// own AC-bias hysteresis loop instead of a bar or dial.
//
// SOURCE: AC-bias magnetic tape recording linearizes an inherently nonlinear
// medium by superimposing a high-frequency bias signal on the audio; the
// tape's flux density B vs. drive field H traces a hysteresis loop, not a
// straight line (Jiles-Atherton hysteresis model; documented on any pro
// reel-to-reel service manual, e.g. Studer A80 / Ampex ATR bias alignment
// procedures). As input climbs toward and past 0dB the loop widens and its
// corners round off toward saturation — the mechanism behind analog tape's
// "soft clip" character, colloquially "tape saturation".
//
// A bright marker rides the loop's edge, one full lobe traversal every 8.3s.
// The loop itself is recomputed every frame from B = Bsat*tanh(k*(H -+ Hc))
// (sign set by sweep direction — ascending vs. descending branch — which is
// what opens the two straight tanh curves into a closed lobed loop rather
// than a single line), so its own envelope amplitude breathes on an
// independent 21s cycle: the loop is visibly narrower/sharper at low drive
// and wider/rounder at high drive across a single 5-second sample, not just
// a dot moving on a fixed shape. The real bias frequency this represents
// (~150kHz on a pro deck) is documented here only — rendering it 1:1 against
// a ~60Hz paint rate would alias into a strobe, so the rendered rate is a
// decoupled, deliberately slow drive sweep instead (round-9 legibility rule).
// ---------------------------------------------------------------------------

const DRIVE_PERIOD_S = 8.3; // one full lobe traversal (0.12Hz)
const DRIVE_PHASE_OFFSET = 0.12; // cycle fraction offset — see freeze-frame note below
const ENVELOPE_PERIOD_S = 21; // saturation-amount breathing cycle
const ENVELOPE_MIN = 0.6; // peak H amplitude at envelope trough
const ENVELOPE_MAX = 1.4; // peak H amplitude at envelope peak
const COERCIVITY_HC = 0.18;
const B_SAT = 0.92;
const K_STEEPNESS = 2.4; // tanh steepness — controls corner rounding
const LOOP_POINTS = 240; // 120 ascending + 120 descending branch samples
const SQUARE_FRACTION = 0.7; // loop region side = min(w,h) * this
const H_DOMAIN = 1.5; // H-axis half-range shown — tight enough that the trough-amplitude
// loop (amp 0.6) still reads as a lens with real horizontal width, not a
// tall sliver dominated by the fixed ~0.75 vertical coercivity gap
const B_DOMAIN = 1.05; // B-axis half-range shown, padding beyond Bsat
const MARKER_RADIUS_PX = 3.5;
const AREA_FILL_ALPHA = 0.05;

// FREEZE FRAME: reduced-motion locks at drive-cycle phase 0.62 — chosen so
// that with DRIVE_PHASE_OFFSET applied, H is descending through zero right
// as the 21s envelope sits within a hair of its own peak (0.62 * 8.3s =
// 5.146s; 5.146s / 21s ~= 0.245 of the envelope's own sine, ~=0.9993 of its
// peak). At H=0 the marker sits at the widest vertical separation between
// the two branches (the coercivity gap, ~0.75 of the B range) with the loop
// itself at peak envelope amplitude — the single frame that shows the full
// open loop at its widest, rather than a thin near-origin sliver at a small
// envelope amplitude.
const FREEZE_PHASE_FRAC = 0.62;
const FREEZE_T = FREEZE_PHASE_FRAC * DRIVE_PERIOD_S;

function envelopeAmplitude(t: number): number {
  const center = (ENVELOPE_MIN + ENVELOPE_MAX) / 2;
  const halfRange = (ENVELOPE_MAX - ENVELOPE_MIN) / 2;
  return center + halfRange * Math.sin((2 * Math.PI * t) / ENVELOPE_PERIOD_S);
}

function driveAngle(t: number): number {
  return 2 * Math.PI * (t / DRIVE_PERIOD_S - DRIVE_PHASE_OFFSET);
}

/** ascending branch: H rising, B lags "behind" toward +Hc */
function bAscending(h: number): number {
  return B_SAT * Math.tanh(K_STEEPNESS * (h - COERCIVITY_HC));
}

/** descending branch: H falling, B lags "behind" toward -Hc */
function bDescending(h: number): number {
  return B_SAT * Math.tanh(K_STEEPNESS * (h + COERCIVITY_HC));
}

/** Full closed loop, LOOP_POINTS samples, for the current envelope amplitude. */
function buildLoop(amp: number): { h: number; b: number }[] {
  const half = LOOP_POINTS / 2;
  const pts: { h: number; b: number }[] = [];
  for (let i = 0; i <= half; i++) {
    const h = -amp + (2 * amp * i) / half;
    pts.push({ h, b: bAscending(h) });
  }
  for (let i = 0; i <= half; i++) {
    const h = amp - (2 * amp * i) / half;
    pts.push({ h, b: bDescending(h) });
  }
  return pts;
}

/** Current marker position: same math as the loop branches, evaluated
 * directly at the drive's current H and sweep direction. */
function markerPoint(t: number, amp: number): { h: number; b: number } {
  const angle = driveAngle(t);
  const h = amp * Math.sin(angle);
  const rising = Math.cos(angle) >= 0;
  const b = rising ? bAscending(h) : bDescending(h);
  return { h, b };
}

export interface BiasHysteresisProps {
  /** accessible name for the reading, e.g. "Input drive" */
  label?: string;
  /** canvas panel height in px. Default 220. */
  height?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function BiasHysteresis({
  label = "Bias saturation",
  height = 220,
  className = "",
}: BiasHysteresisProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let fg = "";
    let border = "";

    // fallbacks are CSS keywords, never literal colour values
    const readTokens = () => {
      const root = getComputedStyle(document.documentElement);
      fg = root.getPropertyValue("--foreground").trim() || "currentColor";
      border = root.getPropertyValue("--border").trim() || "currentColor";
    };

    let w = 0;
    let h = 0;
    let sized = false;

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      if (rect.width < 2 || rect.height < 2) {
        sized = false;
        return;
      }
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      w = rect.width;
      h = rect.height;
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      sized = true;
    };

    const draw = (t: number) => {
      if (!sized) return;
      ctx.clearRect(0, 0, w, h);

      const side = Math.min(w, h) * SQUARE_FRACTION;
      const cx = w / 2;
      const cy = h / 2;
      const xFor = (hVal: number) => cx + (hVal / H_DOMAIN) * (side / 2);
      const yFor = (bVal: number) => cy - (bVal / B_DOMAIN) * (side / 2);

      // axis crosshair — separator only, never the loop's own line
      ctx.strokeStyle = border;
      ctx.lineWidth = 1;
      ctx.globalAlpha = 1;
      ctx.beginPath();
      ctx.moveTo(cx - side / 2, cy);
      ctx.lineTo(cx + side / 2, cy);
      ctx.moveTo(cx, cy - side / 2);
      ctx.lineTo(cx, cy + side / 2);
      ctx.stroke();

      const amp = envelopeAmplitude(t);
      const loop = buildLoop(amp);

      // enclosed hysteresis area — the "energy lost to saturation" — as a
      // very low-opacity foreground fill, never a hue
      ctx.beginPath();
      loop.forEach((p, i) => {
        const x = xFor(p.h);
        const y = yFor(p.b);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.closePath();
      ctx.fillStyle = fg;
      ctx.globalAlpha = AREA_FILL_ALPHA;
      ctx.fill();

      // the loop stroke itself
      ctx.globalAlpha = 1;
      ctx.strokeStyle = fg;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      loop.forEach((p, i) => {
        const x = xFor(p.h);
        const y = yFor(p.b);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.closePath();
      ctx.stroke();

      // marker riding the loop's edge — the one thing to follow
      const marker = markerPoint(t, amp);
      ctx.beginPath();
      ctx.arc(xFor(marker.h), yFor(marker.b), MARKER_RADIUS_PX, 0, Math.PI * 2);
      ctx.fillStyle = fg;
      ctx.globalAlpha = 1;
      ctx.fill();
    };

    // -- loop ----------------------------------------------------------------
    let raf = 0;
    let last = 0;
    let globalT = 0;

    const loop = (now: number) => {
      const dtMs = last ? Math.min(250, now - last) : 1000 / 60;
      last = now;
      globalT += dtMs / 1000;
      draw(globalT);
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    const mo = new MutationObserver(() => {
      readTokens();
      draw(reduced ? FREEZE_T : globalT);
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        readTokens();
        resize();
        draw(reduced ? FREEZE_T : globalT);
      }, 150);
    };
    const ro = new ResizeObserver(onResize);
    ro.observe(canvas);

    const io = new IntersectionObserver(
      (entries) => {
        const visible = entries[0]?.isIntersecting;
        if (visible && !reduced && sized) {
          cancelAnimationFrame(raf);
          last = 0;
          raf = requestAnimationFrame(loop);
        } else if (!visible) {
          cancelAnimationFrame(raf);
        }
      },
      { threshold: 0 }
    );
    io.observe(canvas);

    const onVis = () => {
      cancelAnimationFrame(raf);
      if (!document.hidden && !reduced && sized) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };
    document.addEventListener("visibilitychange", onVis);

    // no paint before the first token read
    readTokens();
    resize();

    if (reduced) {
      draw(FREEZE_T);
    } else {
      draw(0);
      raf = requestAnimationFrame(loop);
    }

    return () => {
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      mo.disconnect();
      ro.disconnect();
      io.disconnect();
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [height]);

  return (
    <div className={className}>
      <div className="flex items-baseline justify-between gap-3">
        <span className="font-mono text-[11px] tracking-wide text-ns-muted">
          {label.toUpperCase()}
        </span>
        <span className="font-mono text-[11px] tracking-wide text-ns-muted">H / B LOOP</span>
      </div>
      <div role="img" aria-label={`${label}: a closed hysteresis loop, widening and rounding as drive climbs toward saturation`} className="mt-2">
        <canvas
          ref={canvasRef}
          aria-hidden="true"
          className="block w-full"
          style={{ height }}
        />
      </div>
      <div className="mt-1.5 flex items-center justify-between font-mono text-[11px] text-ns-muted">
        <span>Hc {COERCIVITY_HC.toFixed(2)}</span>
        <span>Bsat {B_SAT.toFixed(2)}</span>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useId, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// BittingCut — a passkey's credential ID rendered as a physical key blade, so
// "the MacBook passkey" and "the phone passkey" are visually distinct objects
// a person recognizes across sessions, not two identical shield icons.
//
// The bitting profile (6 notch depths, quantized to 5 levels — real key-cut
// vocabulary) is a PURE function of the credential id: same id -> same cuts,
// every mount, forever. That is the whole point — recognition requires
// determinism, so there is no randomness anywhere in the depth derivation.
// Only a freshly-enrolled key (added at runtime, given a fresh random
// credential id) gets a NEW, still-deterministic-for-that-id profile.
//
// Enrollment plays a one-shot 700ms cutter pass: a cutting wheel sweeps the
// blade once and each notch STEPS to its final depth exactly as the wheel
// crosses it (a cutting wheel does not tween — it commits), with a brief
// --foreground burr flash at the instant of each cut. Removal runs the exact
// same traversal in "file" mode — every notch steps back to blank as the
// wheel passes — before the row collapses out of the list. Reduced motion
// skips both passes and lands directly on the finished (cut or blank) shape.
//
// Real list, real buttons, real text: name / created / last-used are plain
// DOM text beside the art, the SVG key is aria-hidden, and removal goes
// through an arm-then-confirm button (mirrors the repo's existing evict
// pattern) with a polite live-region announcement once it lands.
// ---------------------------------------------------------------------------

export interface Passkey {
  /** stable credential id — the ONLY input the bitting profile is derived from */
  id: string;
  /** device or credential label, e.g. "iPhone 16" */
  name: string;
  /** device glyph shown in the key's bow; inferred from `name` when omitted */
  device?: "phone" | "laptop" | "tablet" | "desktop" | "key" | "generic";
  /** epoch ms (or Date) this credential was enrolled */
  createdAt: number | Date;
  /** epoch ms (or Date) of last use; null/undefined = never used since enrollment */
  lastUsedAt?: number | Date | null;
}

export interface BittingCutProps {
  /** the starting set of enrolled passkeys, rendered already-cut (no entrance animation) */
  initialPasskeys?: Passkey[];
  /** stop offering "Add passkey" once the list reaches this size. default 6 */
  maxPasskeys?: number;
  /** accessible name for the list. default "Passkeys" */
  ariaLabel?: string;
  /** fired once a newly-generated passkey has been appended */
  onAdd?: (passkey: Passkey) => void;
  /** fired once a passkey has finished its removal (file + collapse) pass */
  onRemove?: (id: string) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

// ---- deterministic bitting -------------------------------------------------

const N_NOTCHES = 6;
const N_LEVELS = 5; // depths 0..4
const CUT_MS = 700;
const ZERO_DEPTHS = new Array(N_NOTCHES).fill(0) as number[];
const CENTER_FRACTIONS = Array.from({ length: N_NOTCHES }, (_, i) => (i + 0.5) / N_NOTCHES);

function fnv1a(input: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < input.length; i++) {
    h ^= input.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

/** pure function of `credentialId` — identical every call, every mount. */
function bittingDepths(credentialId: string): number[] {
  const depths: number[] = [];
  for (let i = 0; i < N_NOTCHES; i++) {
    depths.push(fnv1a(`${credentialId}#${i}`) % N_LEVELS);
  }
  return depths;
}

// ---- key geometry (single blade path, ring bow) ----------------------------

const BOW_CX = 16;
const BOW_CY = 20;
const BOW_R = 11;
const X0 = 27; // blade shoulder, meets the bow ring
const X1 = 100; // blade tip
const TOP = 15;
const BASE = 28;
const DEPTH_STEP = 2.6;
const VIEW_W = 112;
const VIEW_H = 40;

function round2(v: number): number {
  return Math.round(v * 100) / 100;
}

/** the blade silhouette as ONE closed path — stepped cuts, never a smooth curve. */
function bladePath(depths: number[]): string {
  const n = depths.length;
  const cellW = (X1 - X0) / n;
  const xs = Array.from({ length: n + 1 }, (_, i) => X0 + i * cellW);
  const ys = depths.map((d) => BASE - d * DEPTH_STEP);
  let d = `M${round2(xs[0])},${TOP} L${round2(xs[n])},${TOP} L${round2(xs[n])},${round2(ys[n - 1])}`;
  for (let i = n - 1; i >= 0; i--) {
    d += ` L${round2(xs[i])},${round2(ys[i])}`;
    if (i > 0) d += ` L${round2(xs[i])},${round2(ys[i - 1])}`;
  }
  d += ` L${round2(xs[0])},${BASE} Z`;
  return d;
}

function notchCenters(): number[] {
  const cellW = (X1 - X0) / N_NOTCHES;
  return CENTER_FRACTIONS.map((_, i) => X0 + cellW * (i + 0.5));
}

// ---- device glyph (lives inside the bow ring) ------------------------------

type DeviceKind = NonNullable<Passkey["device"]>;

function inferDevice(name: string): DeviceKind {
  const n = name.toLowerCase();
  if (/ipad|tablet/.test(n)) return "tablet";
  if (/iphone|pixel|galaxy|android|phone/.test(n)) return "phone";
  if (/macbook|laptop|notebook|thinkpad|chromebook/.test(n)) return "laptop";
  if (/imac|mac mini|mac studio|desktop|\bpc\b|windows/.test(n)) return "desktop";
  if (/yubikey|titan|security key|\bkey\b/.test(n)) return "key";
  return "generic";
}

function DeviceGlyph({ kind }: { kind: DeviceKind }) {
  const stroke = { stroke: "var(--foreground)", strokeWidth: 1.1, strokeLinecap: "round" as const, strokeLinejoin: "round" as const, fill: "none" };
  switch (kind) {
    case "phone":
      return <rect x={-2.8} y={-5} width={5.6} height={10} rx={1.3} {...stroke} />;
    case "tablet":
      return <rect x={-4.2} y={-3.2} width={8.4} height={6.4} rx={1} {...stroke} />;
    case "laptop":
      return (
        <>
          <rect x={-3.4} y={-4.2} width={6.8} height={4.6} rx={0.6} {...stroke} />
          <line x1={-4.6} y1={1.6} x2={4.6} y2={1.6} {...stroke} />
        </>
      );
    case "desktop":
      return (
        <>
          <rect x={-3.6} y={-4.2} width={7.2} height={5} rx={0.6} {...stroke} />
          <line x1={0} y1={0.8} x2={0} y2={2.6} {...stroke} />
          <line x1={-2.2} y1={2.6} x2={2.2} y2={2.6} {...stroke} />
        </>
      );
    case "key":
      return (
        <>
          <rect x={-2.2} y={-4.2} width={4.4} height={6} rx={0.8} {...stroke} />
          <line x1={-1.4} y1={1.8} x2={-1.4} y2={3.6} {...stroke} />
          <line x1={1.4} y1={1.8} x2={1.4} y2={3.6} {...stroke} />
        </>
      );
    default:
      return <rect x={-2.3} y={-2.3} width={4.6} height={4.6} transform="rotate(45)" {...stroke} />;
  }
}

// ---- time formatting (SSR-safe: "now" arrives after mount) ----------------

const DAY_MS = 86400000;

function formatCreated(ts: number | Date): string {
  const d = ts instanceof Date ? ts : new Date(ts);
  return new Intl.DateTimeFormat("en-US", { month: "long", day: "numeric" }).format(d);
}

function formatLastUsed(lastUsedAt: number | Date | null | undefined, now: number | null): string {
  if (lastUsedAt == null) return "Never used";
  if (now == null) return "…";
  const ts = lastUsedAt instanceof Date ? lastUsedAt.getTime() : lastUsedAt;
  const diff = Math.max(0, now - ts);
  if (diff < DAY_MS) return "Last used today";
  const days = Math.floor(diff / DAY_MS);
  if (days === 1) return "Last used yesterday";
  if (days < 7) return `Last used ${days} days ago`;
  const weeks = Math.floor(days / 7);
  if (weeks < 5) return `Last used ${weeks} week${weeks === 1 ? "" : "s"} ago`;
  return `Last used ${formatCreated(ts)}`;
}

function remainWord(n: number): string {
  return n === 1 ? "1 remains" : `${n} remain`;
}

function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

// ---- row ---------------------------------------------------------------

type CutPhase = "entering" | "settled" | "filing" | "exiting";

interface RowState extends Passkey {
  cutPhase: CutPhase;
}

const NOTCH_X = notchCenters();

// KeyArt composes the bow ring, the device glyph, and the blade in one
// document (single viewBox, single stacking order) and owns the row's cutter
// animation: a smooth 700ms sweep of the cutter graphic, with each notch's
// depth stepping (never tweening) to its target the instant the sweep
// crosses it.
function KeyArt({
  credentialId,
  device,
  cutPhase,
  reducedMotion,
  onCutSettled,
  onFileSettled,
}: {
  credentialId: string;
  device: DeviceKind;
  cutPhase: CutPhase;
  reducedMotion: boolean;
  onCutSettled: () => void;
  onFileSettled: () => void;
}) {
  const target = useRef(bittingDepths(credentialId)).current;
  const [depths, setDepths] = useState<number[]>(() => (cutPhase === "settled" ? target : ZERO_DEPTHS));
  const [cutterRun, setCutterRun] = useState(false);
  const flashRefs = useRef<(SVGRectElement | null)[]>([]);

  function flashNotch(i: number) {
    const el = flashRefs.current[i];
    if (!el) return;
    el.style.transition = "none";
    el.style.opacity = "1";
    requestAnimationFrame(() => {
      el.style.transition = "opacity 160ms ease-out";
      el.style.opacity = "0";
    });
  }

  useEffect(() => {
    if (cutPhase !== "entering" && cutPhase !== "filing") return;
    const goal = cutPhase === "entering" ? target : ZERO_DEPTHS;
    const settle = cutPhase === "entering" ? onCutSettled : onFileSettled;

    if (reducedMotion) {
      setDepths(goal);
      settle();
      return;
    }

    setCutterRun(false);
    const raf = requestAnimationFrame(() => setCutterRun(true));
    const timers: ReturnType<typeof setTimeout>[] = [];
    CENTER_FRACTIONS.forEach((frac, i) => {
      timers.push(
        setTimeout(() => {
          setDepths((d) => {
            const next = d.slice();
            next[i] = goal[i];
            return next;
          });
          flashNotch(i);
        }, Math.round(frac * CUT_MS))
      );
    });
    timers.push(
      setTimeout(() => {
        setCutterRun(false);
        settle();
      }, CUT_MS + 30)
    );

    return () => {
      cancelAnimationFrame(raf);
      timers.forEach(clearTimeout);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [cutPhase]);

  return (
    <svg aria-hidden="true" viewBox={`0 0 ${VIEW_W} ${VIEW_H}`} width="60" height="22" className="shrink-0">
      <circle cx={BOW_CX} cy={BOW_CY} r={BOW_R} fill="none" stroke="var(--foreground)" strokeWidth={3} />
      <g transform={`translate(${BOW_CX} ${BOW_CY})`}>
        <DeviceGlyph kind={device} />
      </g>
      <path d={bladePath(depths)} fill="var(--foreground)" />
      {NOTCH_X.map((x, i) => (
        <rect
          key={i}
          ref={(el) => {
            flashRefs.current[i] = el;
          }}
          x={x - 0.6}
          y={TOP - 4}
          width={1.2}
          height={BASE - TOP + 8}
          fill="var(--foreground)"
          opacity={0}
        />
      ))}
      <g className="ns-bc-cutter" data-run={cutterRun ? "go" : "idle"}>
        <line x1={X0} x2={X0} y1={TOP - 5} y2={BASE + 5} stroke="var(--foreground)" strokeWidth={1.4} />
        <circle cx={X0} cy={TOP - 7} r={2.2} fill="var(--foreground)" />
      </g>
    </svg>
  );
}

function PasskeyRow({
  row,
  armed,
  now,
  reducedMotion,
  onCutSettled,
  onFileSettled,
  onRequestRemove,
  onCancelArm,
}: {
  row: RowState;
  armed: boolean;
  now: number | null;
  reducedMotion: boolean;
  onCutSettled: (id: string) => void;
  onFileSettled: (id: string) => void;
  onRequestRemove: (id: string) => void;
  onCancelArm: (id: string) => void;
}) {
  const device = row.device ?? inferDevice(row.name);
  const busy = row.cutPhase !== "settled";
  const label = armed ? `Confirm remove ${row.name}` : `Remove ${row.name}`;

  return (
    <li
      data-collapsing={row.cutPhase === "exiting"}
      className="ns-bc-row"
    >
      <div className="ns-bc-row-clip">
        <div className="flex items-center gap-3 px-4 py-3">
          <KeyArt
            credentialId={row.id}
            device={device}
            cutPhase={row.cutPhase}
            reducedMotion={reducedMotion}
            onCutSettled={() => onCutSettled(row.id)}
            onFileSettled={() => onFileSettled(row.id)}
          />
          <div className="min-w-0 flex-1">
            <p className="truncate text-sm font-medium text-foreground">{row.name}</p>
            <p className="mt-0.5 truncate font-mono text-xs text-ns-muted">
              Created {formatCreated(row.createdAt)} · {formatLastUsed(row.lastUsedAt, now)}
            </p>
          </div>
          <button
            type="button"
            className="ns-bc-btn shrink-0"
            data-armed={armed}
            disabled={busy}
            aria-label={label}
            onClick={() => onRequestRemove(row.id)}
            onBlur={() => onCancelArm(row.id)}
            onKeyDown={(e) => {
              if (e.key === "Escape" && armed) onCancelArm(row.id);
            }}
          >
            {armed ? "Confirm" : "Remove"}
          </button>
        </div>
      </div>
    </li>
  );
}

// ---- root ---------------------------------------------------------------

const DEVICE_POOL: Array<{ name: string; device: DeviceKind }> = [
  { name: "iPhone 16", device: "phone" },
  { name: "MacBook Pro", device: "laptop" },
  { name: "iPad Air", device: "tablet" },
  { name: "YubiKey 5C", device: "key" },
  { name: "Pixel 9", device: "phone" },
  { name: "Mac Studio", device: "desktop" },
];

function newPasskey(existingCount: number): Passkey {
  const pick = DEVICE_POOL[existingCount % DEVICE_POOL.length];
  const id =
    typeof crypto !== "undefined" && "randomUUID" in crypto
      ? crypto.randomUUID()
      : `pk-${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return { id, name: pick.name, device: pick.device, createdAt: Date.now(), lastUsedAt: null };
}

export function BittingCut({
  initialPasskeys,
  maxPasskeys = 6,
  ariaLabel = "Passkeys",
  onAdd,
  onRemove,
  className = "",
}: BittingCutProps) {
  const uid = useId();
  const reducedMotion = useReducedMotion();
  const [rows, setRows] = useState<RowState[]>(() =>
    (initialPasskeys ?? []).map((p) => ({ ...p, cutPhase: "settled" as CutPhase }))
  );
  const [armedId, setArmedId] = useState<string | null>(null);
  const [announce, setAnnounce] = useState("");
  const [now, setNow] = useState<number | null>(null);

  useEffect(() => {
    setNow(Date.now());
  }, []);

  const atMax = rows.length >= maxPasskeys;

  function handleAdd() {
    if (atMax) return;
    const pk = newPasskey(rows.length);
    setRows((rs) => [...rs, { ...pk, cutPhase: "entering" }]);
    onAdd?.(pk);
  }

  function handleCutSettled(id: string) {
    setRows((rs) => rs.map((r) => (r.id === id ? { ...r, cutPhase: "settled" } : r)));
  }

  function handleRequestRemove(id: string) {
    if (armedId === id) {
      setArmedId(null);
      setRows((rs) => rs.map((r) => (r.id === id ? { ...r, cutPhase: "filing" } : r)));
    } else {
      setArmedId(id);
    }
  }

  function handleCancelArm(id: string) {
    setArmedId((cur) => (cur === id ? null : cur));
  }

  function handleFileSettled(id: string) {
    setRows((rs) => rs.map((r) => (r.id === id ? { ...r, cutPhase: "exiting" } : r)));
    const delay = reducedMotion ? 0 : 260;
    setTimeout(() => {
      setRows((rs) => {
        const target = rs.find((r) => r.id === id);
        const next = rs.filter((r) => r.id !== id);
        if (target) {
          onRemove?.(id);
          setAnnounce(`Passkey ${target.name} removed, ${remainWord(next.length)}.`);
        }
        return next;
      });
    }, delay);
  }

  return (
    <div className={["ns-bc", className].join(" ")}>
      <style>{CSS}</style>

      <div className="flex items-center justify-between gap-3 pb-3">
        <p className="font-mono text-[10px] uppercase tracking-[0.2em] text-ns-muted">Sign-in methods</p>
        <div className="flex items-center gap-2">
          {atMax && <span className="font-mono text-[10px] text-ns-muted">Maximum reached</span>}
          <button
            type="button"
            className="ns-bc-btn ns-bc-add"
            disabled={atMax}
            aria-label="Add passkey"
            onClick={handleAdd}
          >
            Add passkey
          </button>
        </div>
      </div>

      <ul role="list" aria-label={ariaLabel} id={`${uid}-list`} className="ns-bc-list rounded-[12px] border border-border bg-background">
        {rows.length === 0 ? (
          <li className="px-4 py-6 text-center font-mono text-xs text-ns-muted">No passkeys enrolled.</li>
        ) : (
          rows.map((row) => (
            <PasskeyRow
              key={row.id}
              row={row}
              armed={armedId === row.id}
              now={now}
              reducedMotion={reducedMotion}
              onCutSettled={handleCutSettled}
              onFileSettled={handleFileSettled}
              onRequestRemove={handleRequestRemove}
              onCancelArm={handleCancelArm}
            />
          ))
        )}
      </ul>

      <div role="status" aria-live="polite" aria-atomic="true" className="sr-only">
        {announce}
      </div>
    </div>
  );
}

const CSS = `
