"use client";

import { useEffect, useId, useMemo, useState } from "react";

// ---------------------------------------------------------------------------
// ChartDonutHalftone — the dithered-chart family's part-to-whole chart. The
// backlog flags pie/donut as a form to build "only with a real reason": the
// dataviz heuristic says bar beats pie for almost every job, and a donut
// whose slice DENSITY re-encoded its own share would be the textbook
// anti-pattern (a value-ramp on a channel that already shows the value via
// angle). The reason here is that the segments are ORDINAL — a small, fixed
// size-tier scale — not nominal categories. Angle still carries the only
// magnitude channel (share of the whole); density carries the tier's
// POSITION in the size scale (S sparsest -> XL densest), the same "one hue,
// monotone lightness steps" idea the dataviz skill prescribes for an ordinal
// ramp, translated into ink density instead of lightness. The two channels
// encode two different facts, so nothing is double-encoded.
//
// Same shared constant as chart-bar-halftone: the 4x4 Bayer matrix already
// used by background-ascii-dither and ascii-engraving-contour, stamped into
// 17 discrete ink-level patterns (0 empty, 16 solid) and duplicated verbatim
// here so both chart-family members produce byte-identical density at the
// same level. Pure var(--foreground) ink on var(--background) paper, no
// --ns-accent in the data channel, --ns-accent reserved for keyboard focus only —
// the family's colour decision, matching heatmap-year-stipple's precedent.
// ---------------------------------------------------------------------------

export interface ChartDonutHalftoneDatum {
  label: string;
  value: number;
}

export interface ChartDonutHalftoneProps {
  /** ordinal, low -> high tier order (e.g. size tiers, funnel stages) */
  data?: ChartDonutHalftoneDatum[];
  /** chart title, used as the figure's accessible name */
  title?: string;
  /** unit suffix appended to the center readout, e.g. "orders" */
  unit?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const BAYER = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5];
const LEVELS = 16;
const CELL = 4;

const SIZE = 240;
const CX = SIZE / 2;
const CY = SIZE / 2;
const R_OUTER = 96;
const R_INNER = 56;
const GAP_RAD = 0.035;
const EXPLODE_PX = 6;

function ordinalLevel(rank: number, total: number): number {
  if (total <= 1) return LEVELS;
  return Math.round((rank / (total - 1)) * LEVELS);
}

// rounded to 3 decimals: Math.cos/sin can differ by a ULP between Node (SSR)
// and the browser's engine (CSR), which otherwise surfaces as a hydration
// mismatch in the serialized `d` string despite both being "correct"
function r3(n: number): number {
  return Math.round(n * 1000) / 1000;
}

function polar(r: number, angle: number) {
  return { x: r3(CX + r * Math.cos(angle)), y: r3(CY + r * Math.sin(angle)) };
}

function wedgePath(rOuter: number, rInner: number, a0: number, a1: number): string {
  const large = a1 - a0 > Math.PI ? 1 : 0;
  const p0o = polar(rOuter, a0);
  const p1o = polar(rOuter, a1);
  const p1i = polar(rInner, a1);
  const p0i = polar(rInner, a0);
  return [
    `M${p0o.x},${p0o.y}`,
    `A${rOuter},${rOuter} 0 ${large} 1 ${p1o.x},${p1o.y}`,
    `L${p1i.x},${p1i.y}`,
    `A${rInner},${rInner} 0 ${large} 0 ${p0i.x},${p0i.y}`,
    `Z`,
  ].join(" ");
}

function formatValue(v: number): string {
  const abs = Math.abs(v);
  if (abs >= 1_000_000) return `${(v / 1_000_000).toFixed(1).replace(/\.0$/, "")}M`;
  if (abs >= 1_000) return `${(v / 1_000).toFixed(1).replace(/\.0$/, "")}K`;
  return Math.round(v).toLocaleString();
}

export function ChartDonutHalftone({
  data = [],
  title = "Chart",
  unit = "",
  className = "",
}: ChartDonutHalftoneProps) {
  const uid = useId().replace(/[:]/g, "");
  const [activeIndex, setActiveIndex] = useState(0);
  const [hoverIndex, setHoverIndex] = useState<number | null>(null);
  const [showTable, setShowTable] = useState(false);
  const [entered, setEntered] = useState(false);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    if (mq.matches) {
      setEntered(true);
      return;
    }
    const id = requestAnimationFrame(() => setEntered(true));
    return () => cancelAnimationFrame(id);
  }, []);

  const total = useMemo(() => data.reduce((s, d) => s + d.value, 0), [data]);

  const wedges = useMemo(() => {
    let angle = -Math.PI / 2;
    return data.map((d, i) => {
      const frac = total > 0 ? d.value / total : 0;
      const sweep = frac * Math.PI * 2;
      const a0 = angle;
      const a1 = angle + sweep;
      angle = a1;
      const insetA0 = sweep > GAP_RAD * 2.2 ? a0 + GAP_RAD / 2 : a0;
      const insetA1 = sweep > GAP_RAD * 2.2 ? a1 - GAP_RAD / 2 : a1;
      const mid = (insetA0 + insetA1) / 2;
      return {
        ...d,
        index: i,
        a0: insetA0,
        a1: insetA1,
        mid,
        frac,
        level: ordinalLevel(i, data.length),
      };
    });
  }, [data, total]);

  const focusWedge = (i: number) => {
    if (i < 0 || i >= data.length) return;
    setActiveIndex(i);
    document.getElementById(`${uid}-w-${i}`)?.focus();
  };

  const shown = hoverIndex ?? null;
  const shownWedge = shown !== null ? wedges[shown] : null;
  // resting caption stays short (fits the ring's hole at any title length);
  // the fuller title already sits in the header directly above the chart
  const centerLabel = shownWedge ? shownWedge.label : unit || "total";
  const centerValue = shownWedge ? shownWedge.value : total;

  return (
    <figure className={`ns-cdh inline-flex items-center gap-6 ${className}`} aria-label={`${title}, donut chart`}>
      <style>{CSS}</style>
      <div className="flex flex-col gap-2">
        <div className="flex items-center justify-between gap-3">
          <span className="font-mono text-xs tracking-widest text-ns-muted">{title.toUpperCase()}</span>
          <button
            type="button"
            onClick={() => setShowTable((s) => !s)}
            className="ns-cdh-toggle rounded-sm border border-border px-2 py-1 font-mono text-[10px] tracking-widest text-ns-muted transition-colors duration-150 hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
            aria-pressed={showTable}
          >
            {showTable ? "VIEW CHART" : "VIEW TABLE"}
          </button>
        </div>

        {showTable ? (
          <table className="ns-cdh-table border-collapse font-mono text-xs">
            <caption className="sr-only">{title}</caption>
            <thead>
              <tr>
                <th scope="col" className="border-b border-border px-2 py-1.5 text-left text-ns-muted">
                  Tier
                </th>
                <th scope="col" className="border-b border-border px-2 py-1.5 text-right text-ns-muted tabular-nums">
                  Value
                </th>
                <th scope="col" className="border-b border-border px-2 py-1.5 text-right text-ns-muted tabular-nums">
                  Share
                </th>
              </tr>
            </thead>
            <tbody>
              {wedges.map((w) => (
                <tr key={w.label}>
                  <td className="border-b border-border px-2 py-1.5 text-foreground">{w.label}</td>
                  <td className="border-b border-border px-2 py-1.5 text-right text-foreground tabular-nums">
                    {w.value.toLocaleString()}
                  </td>
                  <td className="border-b border-border px-2 py-1.5 text-right text-foreground tabular-nums">
                    {Math.round(w.frac * 100)}%
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <div className="relative" style={{ width: SIZE, height: SIZE }}>
            <svg
              className="ns-cdh-svg"
              viewBox={`0 0 ${SIZE} ${SIZE}`}
              width={SIZE}
              height={SIZE}
              focusable="false"
              role="presentation"
            >
              <defs>
                {Array.from({ length: LEVELS + 1 }, (_, level) => (
                  <pattern
                    key={level}
                    id={`${uid}-p${level}`}
                    x={0}
                    y={0}
                    width={CELL * 4}
                    height={CELL * 4}
                    patternUnits="userSpaceOnUse"
                  >
                    {BAYER.map((b, i) =>
                      b < level ? (
                        <rect
                          key={i}
                          x={(i % 4) * CELL}
                          y={Math.floor(i / 4) * CELL}
                          width={CELL}
                          height={CELL}
                          fill="var(--foreground)"
                        />
                      ) : null
                    )}
                  </pattern>
                ))}
              </defs>

              {wedges.map((w) => {
                const isActive = hoverIndex === w.index;
                const dx = isActive ? r3(Math.cos(w.mid) * EXPLODE_PX) : 0;
                const dy = isActive ? r3(Math.sin(w.mid) * EXPLODE_PX) : 0;
                return (
                  <path
                    key={w.label}
                    id={`${uid}-w-${w.index}`}
                    role="button"
                    tabIndex={activeIndex === w.index ? 0 : -1}
                    aria-label={`${w.label}: ${w.value.toLocaleString()}${unit ? ` ${unit}` : ""}, ${Math.round(w.frac * 100)}%`}
                    d={wedgePath(R_OUTER, R_INNER, w.a0, w.a1)}
                    fill={`url(#${uid}-p${w.level})`}
                    className="ns-cdh-wedge"
                    style={{
                      transform: `translate(${dx}px, ${dy}px) scale(${entered ? 1 : 0.6})`,
                      opacity: entered ? 1 : 0,
                      transformOrigin: `${CX}px ${CY}px`,
                      transitionDelay: `${w.index * 55}ms`,
                    }}
                    onPointerEnter={() => setHoverIndex(w.index)}
                    onPointerLeave={() => setHoverIndex((c) => (c === w.index ? null : c))}
                    onFocus={() => {
                      setActiveIndex(w.index);
                      setHoverIndex(w.index);
                    }}
                    onBlur={() => setHoverIndex((c) => (c === w.index ? null : c))}
                    onKeyDown={(e) => {
                      if (e.key === "ArrowLeft" || e.key === "ArrowUp") {
                        e.preventDefault();
                        focusWedge((w.index - 1 + data.length) % data.length);
                      } else if (e.key === "ArrowRight" || e.key === "ArrowDown") {
                        e.preventDefault();
                        focusWedge((w.index + 1) % data.length);
                      }
                    }}
                  />
                );
              })}
            </svg>

            <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center" aria-hidden="true">
              <span className="font-sans text-2xl font-semibold text-foreground">{formatValue(centerValue)}</span>
              <span className="mt-0.5 max-w-[6.5rem] truncate px-1 font-mono text-[10px] tracking-widest text-ns-muted">
                {centerLabel.toUpperCase()}
              </span>
            </div>
          </div>
        )}
      </div>

      {!showTable && (
        <ul className="ns-cdh-legend flex flex-col gap-2 font-mono text-xs" aria-hidden="true">
          {wedges.map((w) => (
            <li key={w.label} className="flex items-center gap-2">
              <svg width={14} height={14} aria-hidden="true">
                <rect width={14} height={14} rx={2} fill={`url(#${uid}-p${w.level})`} stroke="var(--border)" />
              </svg>
              <span className="text-foreground">{w.label}</span>
              <span className="text-ns-muted">{Math.round(w.frac * 100)}%</span>
            </li>
          ))}
        </ul>
      )}
    </figure>
  );
}

const CSS = `
.ns-cdh-wedge { transition: transform 220ms cubic-bezier(0.16, 1, 0.3, 1), opacity 420ms ease-out; cursor: pointer; outline: none; }
.ns-cdh-wedge:focus-visible { outline: 2px solid var(--ns-accent); outline-offset: 2px; }
@media (prefers-reduced-motion: reduce) {
  .ns-cdh-wedge { transition: none; }
}
`;

"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// ChartFunnelStageDrop — the dithered-chart family's funnel / stage-drop
// chart (backlog queue #13). Each stage is a tapering trapezoid, its interior
// filled with the family's shared ordered-dither ramp (4x4 Bayer matrix, 17
// ink levels) at a density tracking the stage's share of the top of the
// funnel — the usual redundant density channel. The mechanic that is new to
// this family member: hovering or focusing a stage animates its OWN drop-off
// — the count lost before the next stage — as ink particles trickling out of
// its bottom edge into the gap toward the next stage, gravity-plus-jitter,
// particle count proportional to the actual drop, seeded per stage so a
// replay of the same stage always looks identical. Nothing else in the
// registry visualizes a delta as falling ink. Pure var(--foreground) ink on
// var(--background) paper; var(--ns-accent) is reserved for keyboard focus
// only, matching the rest of the family's colour rule.
// ---------------------------------------------------------------------------

export interface ChartFunnelStageDropDatum {
  label: string;
  value: number;
}

export interface ChartFunnelStageDropProps {
  /** the funnel stages, in order */
  data?: ChartFunnelStageDropDatum[];
  /** heading above the chart */
  title?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const BAYER = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5];
const LEVELS = 16;
const CELL = 5;

const FUNNEL_W = 380;
const MIN_W_FRAC = 0.22;
const LABEL_ROW_H = 32;
const BAR_H = 44;
const GAP_H = 26;
const TOP_PAD = 6;
const BOTTOM_PAD = 6;
const SIDE_PAD = 24;
const MAX_PARTICLES = 34;
const PARTICLE_PERIOD_MS = 1000;
const ENTRANCE_MS = 420;
const ENTRANCE_STAGGER = 60;

function levelFor(norm: number): number {
  return Math.round(Math.min(1, Math.max(0, norm)) * LEVELS);
}

function formatValue(v: number): string {
  const abs = Math.abs(v);
  if (abs >= 1_000_000) return `${(v / 1_000_000).toFixed(1).replace(/\.0$/, "")}M`;
  if (abs >= 1_000) return `${(v / 1_000).toFixed(1).replace(/\.0$/, "")}K`;
  return Math.round(v).toLocaleString();
}

function easeOutExpo(t: number): number {
  return t >= 1 ? 1 : 1 - Math.pow(2, -10 * t);
}

function hashStr(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}
function mulberry32(seed: number) {
  let a = seed;
  return function () {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

interface Tokens {
  fg: string;
  bg: string;
  muted: string;
  border: string;
  accent: string;
}

function readTokens(): Tokens {
  const cs = getComputedStyle(document.documentElement);
  const get = (name: string, fallback: string) => cs.getPropertyValue(name).trim() || fallback;
  return {
    fg: get("--foreground", "#171717"),
    bg: get("--background", "#ffffff"),
    muted: get("--ns-muted", "#4d4d4d"),
    border: get("--border", "#ebebeb"),
    accent: get("--ns-accent", "#006bff"),
  };
}

function useTokens(): Tokens {
  const [tokens, setTokens] = useState<Tokens>(() =>
    typeof document === "undefined"
      ? { fg: "#171717", bg: "#ffffff", muted: "#4d4d4d", border: "#ebebeb", accent: "#006bff" }
      : readTokens()
  );
  useEffect(() => {
    const sync = () => setTokens(readTokens());
    sync();
    const mo = new MutationObserver(sync);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style"] });
    return () => mo.disconnect();
  }, []);
  return tokens;
}

/** A seeded rain of ink particles falling through a gap between two stage
 *  edges — deterministic per stage label so hovering the same stage twice
 *  looks identical. `phase` is 0..1 loop position. */
function particlesFor(seed: string, count: number, topW: number, botW: number) {
  const rng = mulberry32(hashStr(seed));
  return Array.from({ length: count }, () => ({
    x0: (rng() - 0.5) * topW,
    x1: (rng() - 0.5) * botW,
    offset: rng(),
    jitter: rng() * Math.PI * 2,
  }));
}

export function ChartFunnelStageDrop({ data = [], title = "Chart", className = "" }: ChartFunnelStageDropProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const tokens = useTokens();
  const [activeIndex, setActiveIndex] = useState(0);
  const [hoverIndex, setHoverIndex] = useState<number | null>(null);
  const [showTable, setShowTable] = useState(false);
  // useId, not Math.random(): the id is serialized into element ids on the
  // server and must match what the client renders, or React discards the
  // subtree as a hydration mismatch
  const uid = `cfs-${useId().replace(/:/g, "")}`;

  const reducedRef = useRef(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => {
      reducedRef.current = mq.matches;
    };
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);

  const n = data.length;
  const top = data[0]?.value ?? 1;

  const stages = useMemo(
    () =>
      data.map((d, i) => {
        const frac = top > 0 ? d.value / top : 0;
        const w = FUNNEL_W * (MIN_W_FRAC + (1 - MIN_W_FRAC) * frac);
        const next = data[i + 1];
        const nextFrac = next && top > 0 ? next.value / top : frac * 0.9;
        const wBottom = FUNNEL_W * (MIN_W_FRAC + (1 - MIN_W_FRAC) * nextFrac);
        const drop = next ? Math.max(0, d.value - next.value) : 0;
        const dropFrac = top > 0 ? drop / top : 0;
        return { ...d, index: i, wTop: w, wBottom, frac, drop, dropFrac, level: levelFor(frac) };
      }),
    [data, top]
  );

  const rowH = LABEL_ROW_H + BAR_H;
  const viewW = FUNNEL_W + SIDE_PAD * 2;
  const viewH = TOP_PAD + n * rowH + Math.max(0, n - 1) * GAP_H + BOTTOM_PAD;

  const rowTop = (i: number) => TOP_PAD + i * (rowH + GAP_H);

  const focusStage = (i: number) => {
    if (i < 0 || i >= n) return;
    setActiveIndex(i);
    document.getElementById(`${uid}-stage-${i}`)?.focus();
  };

  const mountAtRef = useRef(0);
  const activeAtRef = useRef<number | null>(null);
  const rafRef = useRef(0);

  useEffect(() => {
    mountAtRef.current = performance.now();
  }, []);

  useEffect(() => {
    if (hoverIndex !== null) activeAtRef.current = performance.now();
    else activeAtRef.current = null;
  }, [hoverIndex]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = viewW * dpr;
    canvas.height = viewH * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const cx = viewW / 2;

    const draw = () => {
      ctx.clearRect(0, 0, viewW, viewH);
      const now = performance.now();
      let stillAnimating = false;

      stages.forEach((s, i) => {
        const delay = i * ENTRANCE_STAGGER;
        const t = reducedRef.current ? 1 : Math.min(1, Math.max(0, (now - mountAtRef.current - delay) / ENTRANCE_MS));
        if (t < 1) stillAnimating = true;
        const grow = easeOutExpo(t);

        const yTop = rowTop(i) + LABEL_ROW_H;
        const yBottom = yTop + BAR_H;
        const wTop = s.wTop * grow;
        const wBottom = s.wBottom * grow;

        // trapezoid path
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(cx - wTop / 2, yTop);
        ctx.lineTo(cx + wTop / 2, yTop);
        ctx.lineTo(cx + wBottom / 2, yBottom);
        ctx.lineTo(cx - wBottom / 2, yBottom);
        ctx.closePath();
        const isActive = hoverIndex === i;
        ctx.strokeStyle = isActive ? tokens.accent : tokens.border;
        ctx.lineWidth = isActive ? 1.5 : 1;
        ctx.stroke();
        ctx.clip();

        ctx.fillStyle = tokens.fg;
        const startCol = Math.floor((cx - FUNNEL_W / 2) / CELL);
        const endCol = Math.ceil((cx + FUNNEL_W / 2) / CELL);
        const startRow = Math.floor(yTop / CELL);
        const endRow = Math.ceil(yBottom / CELL);
        for (let gy = startRow; gy < endRow; gy++) {
          for (let gx = startCol; gx < endCol; gx++) {
            const idx = (((gy % 4) + 4) % 4) * 4 + (((gx % 4) + 4) % 4);
            if (BAYER[idx] < s.level) ctx.fillRect(gx * CELL, gy * CELL, CELL, CELL);
          }
        }
        ctx.restore();

        // label + value row above the bar
        ctx.textAlign = "center";
        ctx.font = `10px "GeistMono", ui-monospace, monospace`;
        ctx.fillStyle = tokens.muted;
        ctx.globalAlpha = grow;
        ctx.fillText(s.label.toUpperCase(), cx, rowTop(i) + 12);
        ctx.font = `11px "GeistMono", ui-monospace, monospace`;
        ctx.fillStyle = tokens.fg;
        ctx.fillText(
          `${formatValue(s.value)}  (${Math.round(s.frac * 100)}%)`,
          cx,
          rowTop(i) + 26
        );
        ctx.globalAlpha = 1;

        // the drop-off rain, only in the gap after this stage
        if (i < n - 1 && s.drop > 0) {
          const isHot = hoverIndex === i;
          const count = Math.max(3, Math.round(s.dropFrac * MAX_PARTICLES));
          const parts = particlesFor(`${uid}:${s.label}`, count, s.wBottom, stages[i + 1].wTop);
          const activeAt = activeAtRef.current;

          if (isHot && !reducedRef.current && activeAt !== null) {
            stillAnimating = true;
            ctx.fillStyle = tokens.fg;
            parts.forEach((p) => {
              const elapsed = (now - activeAt + p.offset * PARTICLE_PERIOD_MS) % PARTICLE_PERIOD_MS;
              const phase = elapsed / PARTICLE_PERIOD_MS;
              const y = yBottom + phase * GAP_H;
              const wig = Math.sin(phase * Math.PI * 3 + p.jitter) * 3;
              const x = cx + p.x0 + (p.x1 - p.x0) * phase + wig;
              const alpha = phase < 0.12 ? phase / 0.12 : phase > 0.75 ? Math.max(0, (1 - phase) / 0.25) : 1;
              ctx.globalAlpha = alpha;
              ctx.beginPath();
              ctx.arc(x, y, 1.4, 0, Math.PI * 2);
              ctx.fill();
            });
            ctx.globalAlpha = 1;
          } else if (isHot && reducedRef.current) {
            // reduced motion: one static frame of evenly-spaced particles,
            // no animation loop, still communicates the drop-off count
            ctx.fillStyle = tokens.fg;
            parts.forEach((p, k) => {
              const phase = (k + 0.5) / parts.length;
              const y = yBottom + phase * GAP_H;
              const x = cx + p.x0 + (p.x1 - p.x0) * phase;
              ctx.beginPath();
              ctx.arc(x, y, 1.4, 0, Math.PI * 2);
              ctx.fill();
            });
          }
        }
      });

      if (stillAnimating) {
        rafRef.current = requestAnimationFrame(draw);
      }
    };

    draw();
    return () => cancelAnimationFrame(rafRef.current);
  }, [stages, tokens, viewW, viewH, n, hoverIndex, uid]);

  const hovered = hoverIndex;

  return (
    <figure className={`ns-cfs inline-block ${className}`} aria-label={`${title}, funnel chart`}>
      <style>{CSS}</style>
      <div className="flex items-center justify-between gap-3 pb-2">
        <span className="font-mono text-xs tracking-widest text-ns-muted">{title.toUpperCase()}</span>
        <button
          type="button"
          onClick={() => setShowTable((s) => !s)}
          className="ns-cfs-toggle rounded-sm border border-border px-2 py-1 font-mono text-[10px] tracking-widest text-ns-muted transition-colors duration-150 hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
          aria-pressed={showTable}
        >
          {showTable ? "VIEW CHART" : "VIEW TABLE"}
        </button>
      </div>

      {showTable ? (
        <table className="ns-cfs-table w-full border-collapse font-mono text-xs">
          <caption className="sr-only">{title}</caption>
          <thead>
            <tr>
              <th scope="col" className="border-b border-border px-2 py-1.5 text-left text-ns-muted">
                Stage
              </th>
              <th scope="col" className="border-b border-border px-2 py-1.5 text-right text-ns-muted tabular-nums">
                Value
              </th>
              <th scope="col" className="border-b border-border px-2 py-1.5 text-right text-ns-muted tabular-nums">
                Dropped
              </th>
            </tr>
          </thead>
          <tbody>
            {stages.map((s) => (
              <tr key={s.label}>
                <td className="border-b border-border px-2 py-1.5 text-foreground">{s.label}</td>
                <td className="border-b border-border px-2 py-1.5 text-right text-foreground tabular-nums">
                  {s.value.toLocaleString()}
                </td>
                <td className="border-b border-border px-2 py-1.5 text-right text-foreground tabular-nums">
                  {s.index < n - 1 ? s.drop.toLocaleString() : "—"}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <div className="relative" style={{ width: viewW, maxWidth: "100%" }}>
          <canvas
            ref={canvasRef}
            aria-hidden="true"
            className="ns-cfsd-canvas"
            style={{ width: viewW, height: viewH, maxWidth: "100%", display: "block" }}
          />

          {stages.map((s) => (
            <button
              key={s.label}
              type="button"
              id={`${uid}-stage-${s.index}`}
              tabIndex={activeIndex === s.index ? 0 : -1}
              aria-label={
                s.index < n - 1
                  ? `${s.label}: ${s.value.toLocaleString()}, ${Math.round(s.frac * 100)}% of top, ${s.drop.toLocaleString()} dropped before next stage`
                  : `${s.label}: ${s.value.toLocaleString()}, ${Math.round(s.frac * 100)}% of top`
              }
              className="ns-cfs-hit absolute cursor-pointer border-0 bg-transparent p-0 outline-none"
              style={{
                left: 0,
                top: rowTop(s.index),
                width: viewW,
                height: rowH + (s.index < n - 1 ? GAP_H : 0),
              }}
              onPointerEnter={() => setHoverIndex(s.index)}
              onPointerLeave={() => setHoverIndex((c) => (c === s.index ? null : c))}
              onFocus={() => {
                setActiveIndex(s.index);
                setHoverIndex(s.index);
              }}
              onBlur={() => setHoverIndex((c) => (c === s.index ? null : c))}
              onKeyDown={(e) => {
                if (e.key === "ArrowUp") {
                  e.preventDefault();
                  focusStage(s.index - 1);
                } else if (e.key === "ArrowDown") {
                  e.preventDefault();
                  focusStage(s.index + 1);
                }
              }}
            />
          ))}

          {hovered !== null && stages[hovered] && stages[hovered].index < n - 1 && (
            <div
              aria-hidden="true"
              className="ns-cfs-tip pointer-events-none absolute z-10 rounded-sm border border-border bg-background px-2 py-1 font-mono text-[11px] shadow-sm"
              style={{
                left: "50%",
                top: `${((rowTop(hovered) + rowH + GAP_H / 2) / viewH) * 100}%`,
                transform: "translate(-50%, -50%)",
              }}
            >
              <strong className="text-foreground">{stages[hovered].drop.toLocaleString()}</strong>{" "}
              <span className="text-ns-muted">dropped</span>
            </div>
          )}
        </div>
      )}
    </figure>
  );
}

const CSS = `
.ns-cfs-hit { touch-action: manipulation; }
.ns-cfs-hit:focus-visible { outline: 2px solid var(--ns-accent); outline-offset: -2px; }
`;

"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// ChartLineDither — the dithered-chart family's line/area chart, the second
// CANVAS member alongside chart-bar-dither. The mechanic here is a
// "developing" reticle: the area under the line rests at a uniform coarse
// 7px ordered-dither cell (same shared 4x4 Bayer matrix as the rest of the
// family), and a scrub cursor — pointer or keyboard — drags a local
// resolution field with it: columns near the scrub position ease down to a
// fine 2px cell in a soft falloff band, columns far from it ease back up to
// coarse, so an ink "loupe" of higher print resolution visibly trails the
// reticle across the chart. Density per column still tracks that column's
// own value (redundant with curve height, exactly like chart-bar-dither and
// chart-bar-halftone before it) — the reticle changes RESOLUTION, never
// hue, so the family's density-not-colour rule holds. Pure var(--foreground)
// ink on var(--background) paper; var(--ns-accent) is reserved for keyboard
// focus only.
// ---------------------------------------------------------------------------

export interface ChartLineDitherDatum {
  label: string;
  value: number;
}

export interface ChartLineDitherProps {
  /** the plotted line's points, in order */
  data?: ChartLineDitherDatum[];
  /** heading above the chart */
  title?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const BAYER = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5];
const LEVELS = 16;

const COARSE_CELL = 7;
const FINE_CELL = 2;
const RETICLE_RADIUS = 70;
const EASE_RATE = 0.18;
const EPS = 0.4;

const PLOT_W = 480;
const PLOT_H = 200;
const TOP_PAD = 30;
const BOTTOM_PAD = 26;
const LEFT_PAD = 14;
const RIGHT_PAD = 14;
const ENTRANCE_MS = 620;

function levelFor(norm: number): number {
  return Math.round(Math.min(1, Math.max(0, norm)) * LEVELS);
}

function formatValue(v: number): string {
  const abs = Math.abs(v);
  if (abs >= 1_000_000) return `${(v / 1_000_000).toFixed(1).replace(/\.0$/, "")}M`;
  if (abs >= 1_000) return `${(v / 1_000).toFixed(1).replace(/\.0$/, "")}K`;
  return Math.round(v).toLocaleString();
}

function easeOutExpo(t: number): number {
  return t >= 1 ? 1 : 1 - Math.pow(2, -10 * t);
}

interface Tokens {
  fg: string;
  bg: string;
  muted: string;
  border: string;
  accent: string;
}

function readTokens(): Tokens {
  const cs = getComputedStyle(document.documentElement);
  const get = (name: string, fallback: string) => cs.getPropertyValue(name).trim() || fallback;
  return {
    fg: get("--foreground", "#171717"),
    bg: get("--background", "#ffffff"),
    muted: get("--ns-muted", "#4d4d4d"),
    border: get("--border", "#ebebeb"),
    accent: get("--ns-accent", "#006bff"),
  };
}

function useTokens(): Tokens {
  const [tokens, setTokens] = useState<Tokens>(() =>
    typeof document === "undefined"
      ? { fg: "#171717", bg: "#ffffff", muted: "#4d4d4d", border: "#ebebeb", accent: "#006bff" }
      : readTokens()
  );
  useEffect(() => {
    const sync = () => setTokens(readTokens());
    sync();
    const mo = new MutationObserver(sync);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style"] });
    return () => mo.disconnect();
  }, []);
  return tokens;
}

export function ChartLineDither({ data = [], title = "Chart", className = "" }: ChartLineDitherProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const tokens = useTokens();
  const [activeIndex, setActiveIndex] = useState(0);
  const [scrubIndex, setScrubIndex] = useState<number | null>(null);
  const [showTable, setShowTable] = useState(false);
  // useId, not Math.random(): the id is serialized into element ids on the
  // server and must match what the client renders, or React discards the
  // subtree as a hydration mismatch
  const uid = `cld-${useId().replace(/:/g, "")}`;

  const reducedRef = useRef(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => {
      reducedRef.current = mq.matches;
    };
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);

  const n = data.length;
  const viewW = LEFT_PAD + PLOT_W + RIGHT_PAD;
  const viewH = TOP_PAD + PLOT_H + BOTTOM_PAD;
  const baseY = TOP_PAD + PLOT_H;

  const points = useMemo(() => {
    const max = Math.max(...data.map((d) => d.value), 0);
    const min = Math.min(...data.map((d) => d.value), 0);
    const range = max - min || 1;
    return data.map((d, i) => {
      const x = LEFT_PAD + (n <= 1 ? PLOT_W / 2 : (i / (n - 1)) * PLOT_W);
      const norm = (d.value - min) / range;
      const y = baseY - PLOT_H * norm;
      return { ...d, index: i, x, y, level: levelFor(norm) };
    });
  }, [data, n, baseY]);

  const focusPoint = (i: number) => {
    if (i < 0 || i >= n) return;
    setActiveIndex(i);
    document.getElementById(`${uid}-pt-${i}`)?.focus();
  };

  // continuous scrub-x target (canvas coords), eased for a trailing resolve
  const scrubTargetRef = useRef<number | null>(null);
  const scrubXRef = useRef<number | null>(null);
  const mountAtRef = useRef(0);
  const rafRef = useRef(0);

  useEffect(() => {
    mountAtRef.current = performance.now();
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = viewW * dpr;
    canvas.height = viewH * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const draw = () => {
      ctx.clearRect(0, 0, viewW, viewH);

      ctx.strokeStyle = tokens.border;
      ctx.lineWidth = 1;
      [0, 0.25, 0.5, 0.75, 1].forEach((f) => {
        const y = Math.round(baseY - PLOT_H * f) + 0.5;
        ctx.beginPath();
        ctx.moveTo(LEFT_PAD, y);
        ctx.lineTo(viewW - RIGHT_PAD, y);
        ctx.stroke();
      });

      if (points.length >= 2) {
        const now = performance.now();
        const t = reducedRef.current ? 1 : Math.min(1, Math.max(0, (now - mountAtRef.current) / ENTRANCE_MS));
        const grow = easeOutExpo(t);
        const revealX = LEFT_PAD + PLOT_W * grow;

        // ease the scrub cursor toward its target
        const target = scrubTargetRef.current;
        let stillAnimating = t < 1;
        if (target === null) {
          if (scrubXRef.current !== null) {
            scrubXRef.current = null;
          }
        } else if (reducedRef.current) {
          scrubXRef.current = target;
        } else {
          const cur = scrubXRef.current ?? target;
          const next = cur + (target - cur) * EASE_RATE;
          scrubXRef.current = Math.abs(next - target) < EPS ? target : next;
          if (Math.abs(scrubXRef.current - target) >= EPS) stillAnimating = true;
        }

        ctx.save();
        ctx.beginPath();
        ctx.rect(LEFT_PAD, TOP_PAD, Math.max(0, revealX - LEFT_PAD), PLOT_H);
        ctx.clip();

        // dithered area, clipped to the area-under-curve path
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(points[0].x, points[0].y);
        points.forEach((p) => ctx.lineTo(p.x, p.y));
        ctx.lineTo(points[points.length - 1].x, baseY);
        ctx.lineTo(points[0].x, baseY);
        ctx.closePath();
        ctx.clip();

        const scrub = scrubXRef.current;
        ctx.fillStyle = tokens.fg;
        const startCol = Math.floor(LEFT_PAD / COARSE_CELL);
        const endCol = Math.ceil((LEFT_PAD + PLOT_W) / COARSE_CELL);
        for (let gx = startCol; gx < endCol; gx++) {
          const colCenterX = gx * COARSE_CELL + COARSE_CELL / 2;
          // local column value: linear-interpolate level between the two
          // nearest data points so the dither ramp isn't stair-stepped
          const norm = colCenterX <= points[0].x
            ? points[0].level / LEVELS
            : colCenterX >= points[points.length - 1].x
              ? points[points.length - 1].level / LEVELS
              : (() => {
                  let lo = 0;
                  while (lo < points.length - 2 && points[lo + 1].x < colCenterX) lo++;
                  const a = points[lo];
                  const b = points[lo + 1];
                  const f = (colCenterX - a.x) / Math.max(1, b.x - a.x);
                  return (a.level + (b.level - a.level) * f) / LEVELS;
                })();
          const level = Math.round(norm * LEVELS);

          const dist = scrub === null ? Infinity : Math.abs(colCenterX - scrub);
          const resolveFrac = Math.max(0, 1 - dist / RETICLE_RADIUS);
          const cell = reducedRef.current
            ? COARSE_CELL
            : COARSE_CELL - (COARSE_CELL - FINE_CELL) * resolveFrac;

          const colGrid = Math.round(colCenterX / cell);
          for (let gy = Math.floor(TOP_PAD / cell); gy * cell < baseY; gy++) {
            const idx = (((gy % 4) + 4) % 4) * 4 + (((colGrid % 4) + 4) % 4);
            if (BAYER[idx] < level) {
              ctx.fillRect(gx * COARSE_CELL, gy * cell, COARSE_CELL, cell);
            }
          }
        }
        ctx.restore(); // area clip

        // the line itself, solid ink stroke on top of its own area
        ctx.strokeStyle = tokens.fg;
        ctx.lineWidth = 2;
        ctx.lineJoin = "round";
        ctx.lineCap = "round";
        ctx.beginPath();
        points.forEach((p, i) => {
          if (i === 0) ctx.moveTo(p.x, p.y);
          else ctx.lineTo(p.x, p.y);
        });
        ctx.stroke();

        ctx.restore(); // reveal clip

        // point markers + labels (outside the reveal clip is fine, always visible once entered)
        ctx.font = `9.5px "GeistMono", ui-monospace, monospace`;
        ctx.textAlign = "center";
        points.forEach((p, i) => {
          if (p.x > revealX + 1) return;
          const isActive = i === (scrubIndex ?? -1);
          ctx.beginPath();
          ctx.fillStyle = isActive ? tokens.accent : tokens.fg;
          ctx.arc(p.x, p.y, isActive ? 3 : 2, 0, Math.PI * 2);
          ctx.fill();
          ctx.fillStyle = tokens.muted;
          ctx.fillText(p.label, p.x, baseY + BOTTOM_PAD - 8);
        });

        if (stillAnimating && !reducedRef.current) {
          rafRef.current = requestAnimationFrame(draw);
        }
      }

      ctx.strokeStyle = tokens.border;
      ctx.beginPath();
      ctx.moveTo(LEFT_PAD, baseY + 0.5);
      ctx.lineTo(viewW - RIGHT_PAD, baseY + 0.5);
      ctx.stroke();
    };

    draw();
    return () => cancelAnimationFrame(rafRef.current);
  }, [points, tokens, viewW, viewH, baseY, scrubIndex]);

  // Lives on the wrapping container, not the canvas: the roving-tabindex
  // point buttons sit on top of the canvas and would otherwise swallow every
  // pointer event before it ever reached a canvas-level handler. Button
  // pointer events still bubble here, so this stays the single authority for
  // continuous scrub while the buttons keep only focus/blur for keyboard.
  const onCanvasPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    const canvas = canvasRef.current;
    if (!canvas || points.length === 0) return;
    const rect = canvas.getBoundingClientRect();
    const scale = viewW / rect.width;
    const x = (e.clientX - rect.left) * scale;
    scrubTargetRef.current = x;
    let nearest = 0;
    let bestDist = Infinity;
    points.forEach((p, i) => {
      const d = Math.abs(p.x - x);
      if (d < bestDist) {
        bestDist = d;
        nearest = i;
      }
    });
    setScrubIndex(nearest);
    // scrubIndex is a draw-effect dependency, so this state update alone
    // triggers a fresh single-frame paint even when reduced motion has no
    // persistent rAF loop running.
  };

  const onCanvasPointerLeave = () => {
    scrubTargetRef.current = null;
    setScrubIndex(null);
  };

  const shownIndex = scrubIndex ?? (points.length ? points.length - 1 : null);
  const shownPoint = shownIndex !== null ? points[shownIndex] : null;

  return (
    <figure className={`ns-cld inline-block ${className}`} aria-label={`${title}, line chart`}>
      <style>{CSS}</style>
      <div className="flex items-center justify-between gap-3 pb-2">
        <span className="font-mono text-xs tracking-widest text-ns-muted">{title.toUpperCase()}</span>
        <div className="flex items-center gap-3">
          <span className="font-mono text-[11px] text-foreground" aria-live="polite">
            {shownPoint ? (
              <>
                <strong>{formatValue(shownPoint.value)}</strong>{" "}
                <span className="text-ns-muted">{shownPoint.label}</span>
              </>
            ) : (
              " "
            )}
          </span>
          <button
            type="button"
            onClick={() => setShowTable((s) => !s)}
            className="ns-cld-toggle rounded-sm border border-border px-2 py-1 font-mono text-[10px] tracking-widest text-ns-muted transition-colors duration-150 hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
            aria-pressed={showTable}
          >
            {showTable ? "VIEW CHART" : "VIEW TABLE"}
          </button>
        </div>
      </div>

      {showTable ? (
        <table className="ns-cld-table w-full border-collapse font-mono text-xs">
          <caption className="sr-only">{title}</caption>
          <thead>
            <tr>
              <th scope="col" className="border-b border-border px-2 py-1.5 text-left text-ns-muted">
                Point
              </th>
              <th scope="col" className="border-b border-border px-2 py-1.5 text-right text-ns-muted tabular-nums">
                Value
              </th>
            </tr>
          </thead>
          <tbody>
            {data.map((d) => (
              <tr key={d.label}>
                <td className="border-b border-border px-2 py-1.5 text-foreground">{d.label}</td>
                <td className="border-b border-border px-2 py-1.5 text-right text-foreground tabular-nums">
                  {d.value.toLocaleString()}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <div
          className="relative"
          style={{ width: viewW, maxWidth: "100%" }}
          onPointerMove={onCanvasPointerMove}
          onPointerLeave={onCanvasPointerLeave}
        >
          <canvas
            ref={canvasRef}
            aria-hidden="true"
            className="ns-cld-canvas"
            style={{ width: viewW, height: viewH, maxWidth: "100%", display: "block", cursor: "crosshair" }}
          />

          <div role="listbox" aria-label={`${title} data points`} className="contents">
            {points.map((p, i) => {
              const slotW = n <= 1 ? PLOT_W : PLOT_W / n;
              return (
                <button
                  key={p.label}
                  type="button"
                  role="option"
                  id={`${uid}-pt-${i}`}
                  aria-selected={scrubIndex === i}
                  tabIndex={activeIndex === i ? 0 : -1}
                  aria-label={`${p.label}: ${p.value.toLocaleString()}`}
                  className="ns-cld-hit absolute border-0 bg-transparent p-0 outline-none"
                  style={{
                    left: p.x - slotW / 2,
                    top: TOP_PAD - 10,
                    width: slotW,
                    height: PLOT_H + 20,
                    // the wrapping container is the single pointer authority
                    // (continuous scrub) — these buttons exist for keyboard
                    // reach only, so they must not shadow it from pointer hit-testing
                    pointerEvents: "none",
                  }}
                  onFocus={() => {
                    setActiveIndex(i);
                    scrubTargetRef.current = p.x;
                    setScrubIndex(i);
                  }}
                  onBlur={() => setScrubIndex((c) => (c === i ? null : c))}
                  onKeyDown={(e) => {
                    if (e.key === "ArrowLeft" || e.key === "ArrowUp") {
                      e.preventDefault();
                      focusPoint(i - 1);
                    } else if (e.key === "ArrowRight" || e.key === "ArrowDown") {
                      e.preventDefault();
                      focusPoint(i + 1);
                    } else if (e.key === "Home") {
                      e.preventDefault();
                      focusPoint(0);
                    } else if (e.key === "End") {
                      e.preventDefault();
                      focusPoint(n - 1);
                    }
                  }}
                />
              );
            })}
          </div>
        </div>
      )}
    </figure>
  );
}

const CSS = `
.ns-cld-hit { touch-action: manipulation; }
.ns-cld-hit:focus-visible { outline: 2px solid var(--ns-accent); outline-offset: 2px; }
`;

"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// ChartRadarDither — the dithered-chart family's radar/spider chart, the
// fourth CANVAS member. The polygon's interior is tiled into one triangular
// wedge per axis (center to each pair of adjacent vertices), each wedge
// filled with the family's shared ordered-dither ramp (4x4 Bayer matrix, 17
// ink levels) at a density tracking that axis pair's own value — the usual
// redundant channel alongside the polygon's own radius. The mechanic unique
// to this family member: a literal radar sweep line rotates continuously
// around the center, and as it crosses a wedge, that wedge's ink eases down
// to a fine resolution and then decays back to coarse over a trailing
// half-second echo — a scanning "resolve" that visits every axis in turn.
// Hovering or focusing an axis (a real button at its vertex) independently
// pins its two adjacent wedges to fine resolution regardless of where the
// sweep currently is. Resolution is the only thing either mechanic changes;
// colour never encodes data — pure var(--foreground) ink on
// var(--background) paper, var(--ns-accent) reserved for the sweep line and
// keyboard focus only, matching the rest of the family.
// ---------------------------------------------------------------------------

export interface ChartRadarDitherDatum {
  label: string;
  value: number;
  /** axis max; defaults to 100 */
  max?: number;
}

export interface ChartRadarDitherProps {
  /** the plotted axes/values */
  data?: ChartRadarDitherDatum[];
  /** heading above the chart */
  title?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const BAYER = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5];
const LEVELS = 16;
const CELL_COARSE = 6;
const CELL_FINE = 2;

const SIZE = 280;
const R_MAX = 98;
const SWEEP_SPEED = (Math.PI * 2) / 6000; // one revolution / 6s
const DECAY_MS = 650;
const ENTRANCE_MS = 460;

function levelFor(norm: number): number {
  return Math.round(Math.min(1, Math.max(0, norm)) * LEVELS);
}

function easeOutExpo(t: number): number {
  return t >= 1 ? 1 : 1 - Math.pow(2, -10 * t);
}

function normalizeAngle(a: number): number {
  const twoPi = Math.PI * 2;
  return ((a % twoPi) + twoPi) % twoPi;
}

function inArc(angle: number, from: number, to: number): boolean {
  const a = normalizeAngle(angle);
  const f = normalizeAngle(from);
  const t = normalizeAngle(to);
  if (f <= t) return a >= f && a <= t;
  return a >= f || a <= t;
}

interface Tokens {
  fg: string;
  bg: string;
  muted: string;
  border: string;
  accent: string;
}

function readTokens(): Tokens {
  const cs = getComputedStyle(document.documentElement);
  const get = (name: string, fallback: string) => cs.getPropertyValue(name).trim() || fallback;
  return {
    fg: get("--foreground", "#171717"),
    bg: get("--background", "#ffffff"),
    muted: get("--ns-muted", "#4d4d4d"),
    border: get("--border", "#ebebeb"),
    accent: get("--ns-accent", "#006bff"),
  };
}

function useTokens(): Tokens {
  const [tokens, setTokens] = useState<Tokens>(() =>
    typeof document === "undefined"
      ? { fg: "#171717", bg: "#ffffff", muted: "#4d4d4d", border: "#ebebeb", accent: "#006bff" }
      : readTokens()
  );
  useEffect(() => {
    const sync = () => setTokens(readTokens());
    sync();
    const mo = new MutationObserver(sync);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style"] });
    return () => mo.disconnect();
  }, []);
  return tokens;
}

function polar(cx: number, cy: number, r: number, angle: number) {
  return { x: cx + r * Math.cos(angle), y: cy + r * Math.sin(angle) };
}

export function ChartRadarDither({ data = [], title = "Chart", className = "" }: ChartRadarDitherProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const tokens = useTokens();
  const [activeIndex, setActiveIndex] = useState(0);
  const [hoverIndex, setHoverIndex] = useState<number | null>(null);
  const [showTable, setShowTable] = useState(false);
  // useId, not Math.random(): the id is serialized into element ids on the
  // server and must match what the client renders, or React discards the
  // subtree as a hydration mismatch
  const uid = `crd-${useId().replace(/:/g, "")}`;

  const reducedRef = useRef(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => {
      reducedRef.current = mq.matches;
    };
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);

  const n = data.length;
  const cx = SIZE / 2;
  const cy = SIZE / 2;

  const axes = useMemo(
    () =>
      data.map((d, i) => {
        const max = d.max ?? 100;
        const frac = max > 0 ? Math.min(1, Math.max(0, d.value / max)) : 0;
        const angle = -Math.PI / 2 + (i / Math.max(1, n)) * Math.PI * 2;
        const r = R_MAX * frac;
        const vertex = polar(cx, cy, r, angle);
        const labelPos = polar(cx, cy, R_MAX + 22, angle);
        return { ...d, index: i, max, frac, angle, r, vertex, labelPos, level: levelFor(frac) };
      }),
    [data, n, cx, cy]
  );

  const focusAxis = (i: number) => {
    if (i < 0 || i >= n) return;
    setActiveIndex(i);
    document.getElementById(`${uid}-axis-${i}`)?.focus();
  };

  const mountAtRef = useRef(0);
  const rafRef = useRef(0);
  // per-wedge "last time the sweep crossed it" for the decaying echo
  const lastFreshRef = useRef<number[]>([]);

  useEffect(() => {
    mountAtRef.current = performance.now();
    lastFreshRef.current = axes.map(() => -Infinity);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [n]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = SIZE * dpr;
    canvas.height = SIZE * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const draw = () => {
      ctx.clearRect(0, 0, SIZE, SIZE);
      if (n < 3) return;
      const now = performance.now();
      const t = reducedRef.current ? 1 : Math.min(1, Math.max(0, (now - mountAtRef.current) / ENTRANCE_MS));
      let stillAnimating = t < 1;
      const grow = easeOutExpo(t);

      // background rings + spokes
      ctx.strokeStyle = tokens.border;
      ctx.lineWidth = 1;
      [0.25, 0.5, 0.75, 1].forEach((f) => {
        ctx.beginPath();
        axes.forEach((a, i) => {
          const p = polar(cx, cy, R_MAX * f, a.angle);
          if (i === 0) ctx.moveTo(p.x, p.y);
          else ctx.lineTo(p.x, p.y);
        });
        ctx.closePath();
        ctx.stroke();
      });
      axes.forEach((a) => {
        const p = polar(cx, cy, R_MAX, a.angle);
        ctx.beginPath();
        ctx.moveTo(cx, cy);
        ctx.lineTo(p.x, p.y);
        ctx.stroke();
      });

      // the sweep angle, and per-wedge freshness (fine <- sweep OR hover)
      const sweepAngle = reducedRef.current ? -Math.PI / 2 : normalizeAngle((now * SWEEP_SPEED) % (Math.PI * 2));

      axes.forEach((a, i) => {
        const b = axes[(i + 1) % n];
        const a0 = a.angle;
        const a1 = b.angle > a0 ? b.angle : b.angle + Math.PI * 2;

        const sweptNow = !reducedRef.current && inArc(sweepAngle, a0, a1);
        if (sweptNow) lastFreshRef.current[i] = now;
        const sinceFresh = now - (lastFreshRef.current[i] ?? -Infinity);
        const sweepFresh = reducedRef.current ? 0 : Math.max(0, 1 - sinceFresh / DECAY_MS);
        const hoverFresh = hoverIndex === i || hoverIndex === (i + 1) % n ? 1 : 0;
        const freshness = Math.max(sweepFresh, hoverFresh);
        if (freshness > 0.01 && freshness < 1) stillAnimating = true;
        if (sweptNow) stillAnimating = true;

        const cell = CELL_COARSE - (CELL_COARSE - CELL_FINE) * freshness;
        const vA = { x: cx + (a.vertex.x - cx) * grow, y: cy + (a.vertex.y - cy) * grow };
        const vB = { x: cx + (b.vertex.x - cx) * grow, y: cy + (b.vertex.y - cy) * grow };

        ctx.save();
        ctx.beginPath();
        ctx.moveTo(cx, cy);
        ctx.lineTo(vA.x, vA.y);
        ctx.lineTo(vB.x, vB.y);
        ctx.closePath();
        ctx.clip();

        ctx.fillStyle = tokens.fg;
        const level = Math.round(((a.level + b.level) / 2));
        const minX = Math.min(cx, vA.x, vB.x);
        const maxX = Math.max(cx, vA.x, vB.x);
        const minY = Math.min(cy, vA.y, vB.y);
        const maxY = Math.max(cy, vA.y, vB.y);
        const startCol = Math.floor(minX / cell);
        const endCol = Math.ceil(maxX / cell);
        const startRow = Math.floor(minY / cell);
        const endRow = Math.ceil(maxY / cell);
        for (let gy = startRow; gy < endRow; gy++) {
          for (let gx = startCol; gx < endCol; gx++) {
            const idx = (((gy % 4) + 4) % 4) * 4 + (((gx % 4) + 4) % 4);
            if (BAYER[idx] < level) ctx.fillRect(gx * cell, gy * cell, cell, cell);
          }
        }
        ctx.restore();
      });

      // polygon outline
      ctx.strokeStyle = tokens.fg;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      axes.forEach((a, i) => {
        const v = { x: cx + (a.vertex.x - cx) * grow, y: cy + (a.vertex.y - cy) * grow };
        if (i === 0) ctx.moveTo(v.x, v.y);
        else ctx.lineTo(v.x, v.y);
      });
      ctx.closePath();
      ctx.stroke();

      // vertex dots + labels
      ctx.font = `9.5px "GeistMono", ui-monospace, monospace`;
      ctx.textAlign = "center";
      axes.forEach((a, i) => {
        const isActive = hoverIndex === i;
        const v = { x: cx + (a.vertex.x - cx) * grow, y: cy + (a.vertex.y - cy) * grow };
        ctx.beginPath();
        ctx.fillStyle = isActive ? tokens.accent : tokens.fg;
        ctx.arc(v.x, v.y, isActive ? 3 : 2, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = tokens.muted;
        ctx.fillText(a.label.toUpperCase(), a.labelPos.x, a.labelPos.y);
      });

      // the sweep line itself
      if (!reducedRef.current) {
        const tip = polar(cx, cy, R_MAX, sweepAngle);
        ctx.strokeStyle = tokens.accent;
        ctx.globalAlpha = 0.55;
        ctx.lineWidth = 1.25;
        ctx.beginPath();
        ctx.moveTo(cx, cy);
        ctx.lineTo(tip.x, tip.y);
        ctx.stroke();
        ctx.globalAlpha = 1;
      }

      if (stillAnimating) {
        rafRef.current = requestAnimationFrame(draw);
      }
    };

    draw();
    return () => cancelAnimationFrame(rafRef.current);
  }, [axes, tokens, n, hoverIndex, cx, cy]);

  const shown = hoverIndex ?? null;
  const shownAxis = shown !== null ? axes[shown] : null;

  return (
    <figure className={`ns-crd inline-block ${className}`} aria-label={`${title}, radar chart`}>
      <style>{CSS}</style>
      <div className="flex items-center justify-between gap-3 pb-2">
        <span className="font-mono text-xs tracking-widest text-ns-muted">{title.toUpperCase()}</span>
        <div className="flex items-center gap-3">
          <span className="font-mono text-[11px] text-foreground" aria-live="polite">
            {shownAxis ? (
              <>
                <strong>{shownAxis.value.toLocaleString()}</strong>{" "}
                <span className="text-ns-muted">/ {shownAxis.max}</span>
              </>
            ) : (
              " "
            )}
          </span>
          <button
            type="button"
            onClick={() => setShowTable((s) => !s)}
            className="ns-crd-toggle rounded-sm border border-border px-2 py-1 font-mono text-[10px] tracking-widest text-ns-muted transition-colors duration-150 hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
            aria-pressed={showTable}
          >
            {showTable ? "VIEW CHART" : "VIEW TABLE"}
          </button>
        </div>
      </div>

      {showTable ? (
        <table className="ns-crd-table w-full border-collapse font-mono text-xs">
          <caption className="sr-only">{title}</caption>
          <thead>
            <tr>
              <th scope="col" className="border-b border-border px-2 py-1.5 text-left text-ns-muted">
                Axis
              </th>
              <th scope="col" className="border-b border-border px-2 py-1.5 text-right text-ns-muted tabular-nums">
                Value
              </th>
            </tr>
          </thead>
          <tbody>
            {data.map((d) => (
              <tr key={d.label}>
                <td className="border-b border-border px-2 py-1.5 text-foreground">{d.label}</td>
                <td className="border-b border-border px-2 py-1.5 text-right text-foreground tabular-nums">
                  {d.value.toLocaleString()} / {d.max ?? 100}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <div className="relative" style={{ width: SIZE, height: SIZE, maxWidth: "100%" }}>
          <canvas
            ref={canvasRef}
            aria-hidden="true"
            className="ns-crd-canvas"
            style={{ width: SIZE, height: SIZE, maxWidth: "100%", display: "block" }}
          />

          <div role="listbox" aria-label={`${title} axes`} className="contents">
            {axes.map((a) => (
              <button
                key={a.label}
                type="button"
                role="option"
                id={`${uid}-axis-${a.index}`}
                aria-selected={hoverIndex === a.index}
                tabIndex={activeIndex === a.index ? 0 : -1}
                aria-label={`${a.label}: ${a.value.toLocaleString()} of ${a.max}`}
                className="ns-crd-hit absolute cursor-pointer rounded-full border-0 bg-transparent p-0 outline-none"
                style={{ left: a.vertex.x - 14, top: a.vertex.y - 14, width: 28, height: 28 }}
                onPointerEnter={() => setHoverIndex(a.index)}
                onPointerLeave={() => setHoverIndex((c) => (c === a.index ? null : c))}
                onFocus={() => {
                  setActiveIndex(a.index);
                  setHoverIndex(a.index);
                }}
                onBlur={() => setHoverIndex((c) => (c === a.index ? null : c))}
                onKeyDown={(e) => {
                  if (e.key === "ArrowLeft" || e.key === "ArrowUp") {
                    e.preventDefault();
                    focusAxis((a.index - 1 + n) % n);
                  } else if (e.key === "ArrowRight" || e.key === "ArrowDown") {
                    e.preventDefault();
                    focusAxis((a.index + 1) % n);
                  }
                }}
              />
            ))}
          </div>
        </div>
      )}
    </figure>
  );
}

const CSS = `
.ns-crd-hit { touch-action: manipulation; }
.ns-crd-hit:focus-visible { outline: 2px solid var(--ns-accent); outline-offset: 2px; }
`;

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// deterministic 2-octave value noise — no deps, stable across frames
// ---------------------------------------------------------------------------
function hash2(x: number, y: number) {
  const n = Math.sin(x * 127.1 + y * 311.7) * 43758.5453123;
  return n - Math.floor(n);
}
function vnoise(x: number, y: number) {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const xf = x - xi;
  const yf = y - yi;
  const u = xf * xf * (3 - 2 * xf);
  const v = yf * yf * (3 - 2 * yf);
  const a = hash2(xi, yi);
  const b = hash2(xi + 1, yi);
  const c = hash2(xi, yi + 1);
  const d = hash2(xi + 1, yi + 1);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}
function noise2(x: number, y: number) {
  return 0.65 * vnoise(x, y) + 0.35 * vnoise(x * 2.1 + 19.7, y * 2.1 + 7.3);
}

// cubic-bezier(0.22, 1, 0.36, 1) solved via Newton–Raphson
function makeBezier(p1x: number, p1y: number, p2x: number, p2y: number) {
  const cx = 3 * p1x;
  const bx = 3 * (p2x - p1x) - cx;
  const ax = 1 - cx - bx;
  const cy = 3 * p1y;
  const by = 3 * (p2y - p1y) - cy;
  const ay = 1 - cy - by;
  const sampleX = (t: number) => ((ax * t + bx) * t + cx) * t;
  const sampleY = (t: number) => ((ay * t + by) * t + cy) * t;
  const slopeX = (t: number) => (3 * ax * t + 2 * bx) * t + cx;
  return (x: number) => {
    if (x <= 0) return 0;
    if (x >= 1) return 1;
    let t = x;
    for (let i = 0; i < 6; i++) {
      const s = slopeX(t);
      if (Math.abs(s) < 1e-6) break;
      t -= (sampleX(t) - x) / s;
    }
    return sampleY(Math.min(1, Math.max(0, t)));
  };
}
const glideEase = makeBezier(0.22, 1, 0.36, 1);

const EMPTY: number[] = [];

function parseColor(raw: string): { r: number; g: number; b: number } | null {
  const v = raw.trim();
  if (v.startsWith("#")) {
    const hex = v.slice(1);
    if (hex.length === 3) {
      const r = parseInt(hex[0] + hex[0], 16);
      const g = parseInt(hex[1] + hex[1], 16);
      const b = parseInt(hex[2] + hex[2], 16);
      if (Number.isNaN(r) || Number.isNaN(g) || Number.isNaN(b)) return null;
      return { r, g, b };
    }
    if (hex.length >= 6) {
      const r = parseInt(hex.slice(0, 2), 16);
      const g = parseInt(hex.slice(2, 4), 16);
      const b = parseInt(hex.slice(4, 6), 16);
      if (Number.isNaN(r) || Number.isNaN(g) || Number.isNaN(b)) return null;
      return { r, g, b };
    }
    return null;
  }
  const m = v.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/i);
  if (!m) return null;
  return { r: Number(m[1]), g: Number(m[2]), b: Number(m[3]) };
}

// ---------------------------------------------------------------------------
// SignalTerrain — Unknown-Pleasures ridgeline landscape where incoming data
// samples scroll forward as ridgelines (history recedes into ambient Perlin
// terrain) and the cursor dents the mesh gravitationally. Canvas 2D,
// painter's-algorithm occlusion, refs only — the rAF loop is the sole writer.
// ---------------------------------------------------------------------------
export function SignalTerrain({
  series = EMPTY,
  cols = 96,
  rows = 40,
  ambientAmplitude = 18,
  dataAmplitude = 68,
  glideMs = 600,
  dentSigma = 90,
  dentDepth = 26,
  className = "h-96",
  "aria-label": ariaLabel = "Live signal terrain",
}: {
  /** data samples, oldest → newest; newest enters at the front row */
  series?: number[];
  /** vertices per ridgeline */
  cols?: number;
  /** ridgeline count (back to front) */
  rows?: number;
  /** ambient noise height in px at the front row */
  ambientAmplitude?: number;
  /** data peak height in px at the front row */
  dataAmplitude?: number;
  /** ms for the history to glide one row back after a push */
  glideMs?: number;
  /** gaussian radius of the cursor dent in screen px */
  dentSigma?: number;
  /** max cursor dent depth in px */
  dentDepth?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** accessible name for the terrain. Default "Live signal terrain". */
  "aria-label"?: string;
}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const seriesRef = useRef<number[]>(series);
  const transRef = useRef(-1); // performance.now() of last push, -1 = settled
  const reducedRef = useRef(false);
  const drawRef = useRef<(() => void) | null>(null);

  // series is data, not render state: push detection + redraw happen in refs
  useEffect(() => {
    const prev = seriesRef.current;
    if (series === prev) return;
    const pushed =
      series.length !== prev.length ||
      (series.length > 0 &&
        series[series.length - 1] !== prev[prev.length - 1]);
    seriesRef.current = series;
    if (pushed) {
      if (reducedRef.current) drawRef.current?.();
      else transRef.current = performance.now();
    }
  }, [series]);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;
    reducedRef.current = reduced;

    let w = 0;
    let h = 0;
    let dpr = 1;
    const resize = () => {
      const rect = root.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
    };
    resize();

    // hot-path state — refs/locals only, never React state
    let raf = 0;
    let last = 0;
    let visible = true;
    let hovered = false;
    let px = 0;
    let py = 0;
    let dentAmt = 0;
    let dentVel = 0;
    let smoothMax = 0;
    const xs = new Float32Array(cols);
    const ys = new Float32Array(cols);
    const invCols = 1 / Math.max(1, cols - 1);
    const invRows = 1 / Math.max(1, rows - 1);
    const twoSigma2 = 2 * dentSigma * dentSigma;

    // theme tokens — resolved from CSS custom properties, never hardcoded,
    // so occlusion fill and ridgeline stroke read correctly in light or dark
    let fillRGB = { r: 10, g: 10, b: 10 };
    let strokeLowRGB = { r: 143, g: 143, b: 143 };
    let strokeHighRGB = { r: 237, g: 237, b: 237 };
    const deriveTokens = () => {
      const cs = getComputedStyle(document.documentElement);
      fillRGB =
        parseColor(cs.getPropertyValue("--surface")) ??
        parseColor(cs.getPropertyValue("--background")) ??
        fillRGB;
      strokeHighRGB = parseColor(cs.getPropertyValue("--foreground")) ?? strokeHighRGB;
      strokeLowRGB = parseColor(cs.getPropertyValue("--ns-muted")) ?? strokeLowRGB;
    };
    deriveTokens();
    // theme can flip after mount (class toggle on <html>, no remount) — without
    // this, fillRGB/strokeRGB stay frozen at whatever theme was active at mount
    const themeObserver = new MutationObserver(() => {
      deriveTokens();
      if (reduced) drawRef.current?.();
    });
    themeObserver.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    const draw = (now: number) => {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      const s = seriesRef.current;
      const len = s.length;

      // glide progress: 1 = settled, eases 0 → 1 over glideMs after a push
      let et = 1;
      if (!reduced && transRef.current >= 0) {
        const p = (now - transRef.current) / glideMs;
        if (p >= 1) {
          transRef.current = -1;
        } else {
          et = glideEase(p);
        }
      }

      // smoothed normalization peak over the visible window
      let mx = 1e-6;
      for (let i = Math.max(0, len - rows - 1); i < len; i++) {
        const sv = s[i] ?? 0;
        if (sv > mx) mx = sv;
      }
      smoothMax = smoothMax === 0 ? mx : smoothMax + (mx - smoothMax) * 0.05;

      const scroll = reduced ? 0 : (now / 1000) * 0.06; // 0.06 noise u/s
      const horizonY = h * 0.16;
      const baseY = h * 0.94;
      const pad = w * 0.03;
      const usable = Math.max(1, w - pad * 2);
      const hasDent = dentAmt > 0.001 || dentAmt < -0.001;

      ctx.lineJoin = "round";
      // back → front: stroke then fill below with the background so nearer
      // ridges occlude farther ones (painter's-algorithm ridgeline trick)
      for (let r = 0; r < rows; r++) {
        const t = r * invRows; // 0 = horizon, 1 = front
        const rowY = horizonY + (baseY - horizonY) * t * t; // quadratic ease
        const rowW = usable * (0.65 + 0.35 * t); // narrows 35% at the back
        const x0 = pad + (usable - rowW) / 2;

        // fractional sample index: history glides one row back per push
        const idx = len - rows + r - 1 + et;
        const i0 = Math.floor(idx);
        const f = idx - i0;
        const v0 = i0 >= 0 && i0 < len ? (s[i0] ?? 0) : 0;
        const v1 = i0 + 1 >= 0 && i0 + 1 < len ? (s[i0 + 1] ?? 0) : 0;
        const val = Math.min(1.4, Math.max(0, (v0 + (v1 - v0) * f) / smoothMax));
        const texIdx = Math.round(idx); // texture travels with the sample
        const frontScale = 0.25 + 0.75 * t;
        const ambScale = ambientAmplitude * (0.3 + 0.7 * t);
        const depthCoord = (rows - 1 - r) * 0.35 + scroll;

        for (let c = 0; c < cols; c++) {
          const cn = c * invCols;
          const x = x0 + rowW * cn;
          const amb = ambScale * noise2(cn * 4 + 7.3, depthCoord);
          const env = Math.exp(-((cn - 0.5) * (cn - 0.5)) / (2 * 0.18 * 0.18));
          const tex = 0.55 + 0.45 * noise2(cn * 9 + 3.1, texIdx * 0.7);
          let y = rowY - amb - dataAmplitude * frontScale * val * env * tex;
          if (hasDent) {
            const dx = x - px;
            const dy = y - py;
            y += dentDepth * dentAmt * Math.exp(-(dx * dx + dy * dy) / twoSigma2);
          }
          xs[c] = x;
          ys[c] = y;
        }

        // occlusion fill down to the bottom edge
        ctx.beginPath();
        ctx.moveTo(xs[0] ?? 0, ys[0] ?? 0);
        for (let c = 1; c < cols; c++) ctx.lineTo(xs[c] ?? 0, ys[c] ?? 0);
        ctx.lineTo(x0 + rowW, h + 2);
        ctx.lineTo(x0, h + 2);
        ctx.closePath();
        ctx.fillStyle = `rgb(${fillRGB.r},${fillRGB.g},${fillRGB.b})`;
        ctx.fill();

        // ridgeline stroke: muted-token color 1px at the horizon fading to
        // foreground-token color 1.5px at the front — theme-derived, not hardcoded
        const mix = Math.pow(t, 1.3);
        const rr = Math.round(strokeLowRGB.r + (strokeHighRGB.r - strokeLowRGB.r) * mix);
        const rg = Math.round(strokeLowRGB.g + (strokeHighRGB.g - strokeLowRGB.g) * mix);
        const rb = Math.round(strokeLowRGB.b + (strokeHighRGB.b - strokeLowRGB.b) * mix);
        const a = 0.25 + 0.75 * mix;
        ctx.beginPath();
        ctx.moveTo(xs[0] ?? 0, ys[0] ?? 0);
        for (let c = 1; c < cols; c++) ctx.lineTo(xs[c] ?? 0, ys[c] ?? 0);
        ctx.strokeStyle = `rgba(${rr},${rg},${rb},${a})`;
        ctx.lineWidth = 1 + 0.5 * mix;
        ctx.stroke();
      }
    };

    if (reduced) {
      // static fallback: current series at rest, no scroll, no dent;
      // redrawn instantly on data change (via drawRef) and on resize
      drawRef.current = () => draw(0);
      draw(0);
      const ro = new ResizeObserver(() => {
        resize();
        draw(0);
      });
      ro.observe(root);
      return () => {
        ro.disconnect();
        themeObserver.disconnect();
        drawRef.current = null;
      };
    }

    const loop = (now: number) => {
      const dt = last === 0 ? 1 / 60 : Math.min(0.05, (now - last) / 1000);
      last = now;
      if (hovered) {
        // lerp toward full dent at 0.12/frame (framerate-normalized)
        const prev = dentAmt;
        dentAmt += (1 - dentAmt) * (1 - Math.pow(0.88, dt * 60));
        dentVel = (dentAmt - prev) / dt; // carry velocity into the release
      } else if (dentAmt !== 0 || dentVel !== 0) {
        // underdamped spring release: k = 70 s^-2, zeta = 0.6 → one rebound
        const k = 70;
        const c = 2 * 0.6 * Math.sqrt(k);
        dentVel += (-k * dentAmt - c * dentVel) * dt;
        dentAmt += dentVel * dt;
        if (Math.abs(dentAmt) < 0.0005 && Math.abs(dentVel) < 0.005) {
          dentAmt = 0;
          dentVel = 0;
        }
      }
      draw(now);
      raf = visible ? requestAnimationFrame(loop) : 0;
    };
    raf = requestAnimationFrame(loop);

    // ambient scroll never settles, so "sleep" = pause offscreen
    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && raf === 0) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    });
    io.observe(root);

    const onMove = (e: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      px = e.clientX - rect.left;
      py = e.clientY - rect.top;
      hovered = true;
    };
    const onLeave = () => {
      hovered = false;
    };
    const ro = new ResizeObserver(resize);
    ro.observe(root);
    root.addEventListener("pointermove", onMove);
    root.addEventListener("pointerdown", onMove);
    root.addEventListener("pointerleave", onLeave);

    return () => {
      cancelAnimationFrame(raf);
      io.disconnect();
      ro.disconnect();
      themeObserver.disconnect();
      root.removeEventListener("pointermove", onMove);
      root.removeEventListener("pointerdown", onMove);
      root.removeEventListener("pointerleave", onLeave);
    };
  }, [cols, rows, ambientAmplitude, dataAmplitude, glideMs, dentSigma, dentDepth]);

  return (
    <div
      ref={rootRef}
      role="img"
      aria-label={ariaLabel}
      className={`relative w-full overflow-hidden ${className}`}
    >
      <canvas
        ref={canvasRef}
        aria-hidden
        className="absolute inset-0 h-full w-full"
      />
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// ChartScatterAsciiBin — a scatter plot rendered as a glyph-density grid
// (no scatter or hexbin exists anywhere in this registry — histogram-live-
// grain bins one dimension into falling grains, stem-and-leaf-live keeps
// every raw digit, chart-bar-dither is one categorical series; none of the
// three bins two continuous dimensions at once). Every point is binned into
// a coarse cell grid and each cell's glyph comes from the family's shared
// 10-step ASCII ramp (" .:-=+*#%@") scaled to that cell's point count — a
// static print of the joint distribution.
//
// The mechanic: a circular brush follows the pointer (or a focused, arrow-
// key-steerable hit target for keyboard users) and LIVE re-bins — not the
// grid cells, the raw points themselves, by exact distance to the brush
// centre — so the readout ("N pts selected, mean x/y") is exact, not a cell
// count. Every cell whose glyph is currently touched by the brush relinks
// to var(--ns-accent) ink in place, which is the only colour anywhere in the
// piece and reserved for the live interaction the same way chart-bar-dither
// reserves it for keyboard focus. Nothing else in the registry re-bins
// against a live pointer radius.
// ---------------------------------------------------------------------------

const RAMP = " .:-=+*#%@";

export interface ScatterPoint {
  x: number;
  y: number;
}

export interface ChartScatterAsciiBinProps {
  /** synthetic sample; x/y in arbitrary plot units, any range */
  data?: ScatterPoint[];
  /** heading above the plot */
  title?: string;
  /** brush radius in plot px */
  brushRadius?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const COLS = 42;
const ROWS = 20;
const CELL = 13;
const LEFT_PAD = 34;
const TOP_PAD = 20;
const BOTTOM_PAD = 30;
const RIGHT_PAD = 12;
const PLOT_W = COLS * CELL;
const PLOT_H = ROWS * CELL;
const ENTRANCE_MS = 320;

interface Tokens {
  fg: string;
  bg: string;
  muted: string;
  border: string;
  accent: string;
}

function readTokens(): Tokens {
  const cs = getComputedStyle(document.documentElement);
  const get = (name: string, fallback: string) => cs.getPropertyValue(name).trim() || fallback;
  return {
    fg: get("--foreground", "#171717"),
    bg: get("--background", "#ffffff"),
    muted: get("--ns-muted", "#4d4d4d"),
    border: get("--border", "#ebebeb"),
    accent: get("--ns-accent", "#006bff"),
  };
}

function useTokens(): Tokens {
  const [tokens, setTokens] = useState<Tokens>(() =>
    typeof document === "undefined"
      ? { fg: "#171717", bg: "#ffffff", muted: "#4d4d4d", border: "#ebebeb", accent: "#006bff" }
      : readTokens()
  );
  useEffect(() => {
    const sync = () => setTokens(readTokens());
    sync();
    const mo = new MutationObserver(sync);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style"] });
    return () => mo.disconnect();
  }, []);
  return tokens;
}

function useReducedMotion(): boolean {
  const ref = useRef(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => {
      ref.current = mq.matches;
    };
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);
  return ref.current;
}

// deterministic two-cluster synthetic sample — clearly fabricated demo data
function defaultSample(): ScatterPoint[] {
  const pts: ScatterPoint[] = [];
  let seed = 7;
  const rand = () => {
    seed = (seed * 16807) % 2147483647;
    return (seed - 1) / 2147483646;
  };
  const gauss = () => {
    let u = 0;
    let v = 0;
    while (u === 0) u = rand();
    while (v === 0) v = rand();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  };
  for (let i = 0; i < 140; i++) {
    pts.push({ x: 30 + gauss() * 14, y: 65 + gauss() * 10 });
  }
  for (let i = 0; i < 90; i++) {
    pts.push({ x: 74 + gauss() * 10, y: 30 + gauss() * 12 });
  }
  return pts;
}

export function ChartScatterAsciiBin({
  data,
  title = "Sample distribution",
  brushRadius = 46,
  className = "",
}: ChartScatterAsciiBinProps) {
  const points = useMemo(() => data ?? defaultSample(), [data]);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const hitRef = useRef<HTMLDivElement>(null);
  const tokens = useTokens();
  const reduced = useReducedMotion();
  const rafRef = useRef(0);
  const mountAtRef = useRef(0);

  const [brush, setBrush] = useState<{ x: number; y: number } | null>(null);
  const brushRef = useRef(brush);
  brushRef.current = brush;

  const xMin = useMemo(() => Math.min(...points.map((p) => p.x)), [points]);
  const xMax = useMemo(() => Math.max(...points.map((p) => p.x)), [points]);
  const yMin = useMemo(() => Math.min(...points.map((p) => p.y)), [points]);
  const yMax = useMemo(() => Math.max(...points.map((p) => p.y)), [points]);
  const xSpan = Math.max(1e-6, xMax - xMin);
  const ySpan = Math.max(1e-6, yMax - yMin);

  const toPx = (p: ScatterPoint) => ({
    px: ((p.x - xMin) / xSpan) * PLOT_W,
    // screen y grows downward; plot y should grow upward
    py: PLOT_H - ((p.y - yMin) / ySpan) * PLOT_H,
  });

  const plotPoints = useMemo(() => points.map(toPx), [points, xMin, xSpan, yMin, ySpan]);

  const cellCounts = useMemo(() => {
    const counts = new Uint16Array(COLS * ROWS);
    for (const { px, py } of plotPoints) {
      const cx = Math.min(COLS - 1, Math.max(0, Math.floor(px / CELL)));
      const cy = Math.min(ROWS - 1, Math.max(0, Math.floor(py / CELL)));
      counts[cy * COLS + cx]++;
    }
    return counts;
  }, [plotPoints]);
  const maxCount = useMemo(() => Math.max(1, ...cellCounts), [cellCounts]);

  const selection = useMemo(() => {
    if (!brush) return null;
    let n = 0;
    let sx = 0;
    let sy = 0;
    for (const { px, py } of plotPoints) {
      const dx = px - brush.x;
      const dy = py - brush.y;
      if (dx * dx + dy * dy <= brushRadius * brushRadius) {
        n++;
        sx += px;
        sy += py;
      }
    }
    if (n === 0) return { n: 0, meanX: 0, meanY: 0 };
    // back to data units for the readout
    const mpx = sx / n;
    const mpy = sy / n;
    const meanX = xMin + (mpx / PLOT_W) * xSpan;
    const meanY = yMin + (1 - mpy / PLOT_H) * ySpan;
    return { n, meanX, meanY };
  }, [brush, brushRadius, plotPoints, xMin, xSpan, yMin, ySpan]);

  useEffect(() => {
    mountAtRef.current = performance.now();
  }, [points]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const viewW = LEFT_PAD + PLOT_W + RIGHT_PAD;
    const viewH = TOP_PAD + PLOT_H + BOTTOM_PAD;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = viewW * dpr;
    canvas.height = viewH * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const draw = () => {
      const now = performance.now();
      const t = reduced ? 1 : Math.min(1, (now - mountAtRef.current) / ENTRANCE_MS);
      ctx.clearRect(0, 0, viewW, viewH);

      ctx.strokeStyle = tokens.border;
      ctx.lineWidth = 1;
      ctx.strokeRect(LEFT_PAD + 0.5, TOP_PAD + 0.5, PLOT_W, PLOT_H);

      ctx.font = `${CELL - 3}px "GeistMono", ui-monospace, monospace`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";

      const bx = brushRef.current;
      const r2 = brushRadius * brushRadius;

      for (let row = 0; row < ROWS; row++) {
        for (let col = 0; col < COLS; col++) {
          const count = cellCounts[row * COLS + col];
          if (count === 0) continue;
          const level = Math.min(RAMP.length - 1, Math.round((count / maxCount) * (RAMP.length - 1)));
          const ch = RAMP[level];
          if (ch === " ") continue;
          const cx = LEFT_PAD + col * CELL + CELL / 2;
          const cy = TOP_PAD + row * CELL + CELL / 2;
          const dx = cx - LEFT_PAD - (bx?.x ?? -9999);
          const dy = cy - TOP_PAD - (bx?.y ?? -9999);
          const inBrush = bx !== null && dx * dx + dy * dy <= r2;
          ctx.fillStyle = inBrush ? tokens.accent : tokens.fg;
          ctx.globalAlpha = t;
          ctx.fillText(ch, cx, cy);
          ctx.globalAlpha = 1;
        }
      }

      if (bx) {
        ctx.strokeStyle = tokens.accent;
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(LEFT_PAD + bx.x, TOP_PAD + bx.y, brushRadius, 0, Math.PI * 2);
        ctx.stroke();
      }

      // axis ticks
      ctx.fillStyle = tokens.muted;
      ctx.font = `9px "GeistMono", ui-monospace, monospace`;
      ctx.textAlign = "center";
      ctx.fillText(xMin.toFixed(0), LEFT_PAD, TOP_PAD + PLOT_H + 14);
      ctx.fillText(xMax.toFixed(0), LEFT_PAD + PLOT_W, TOP_PAD + PLOT_H + 14);
      ctx.save();
      ctx.textAlign = "right";
      ctx.fillText(yMax.toFixed(0), LEFT_PAD - 6, TOP_PAD + 4);
      ctx.fillText(yMin.toFixed(0), LEFT_PAD - 6, TOP_PAD + PLOT_H);
      ctx.restore();

      if (t < 1 && !reduced) rafRef.current = requestAnimationFrame(draw);
    };

    draw();
    return () => cancelAnimationFrame(rafRef.current);
  }, [cellCounts, maxCount, tokens, reduced, brush, brushRadius, xMin, xMax, yMin, yMax]);

  const setBrushFromEvent = (e: { clientX: number; clientY: number }) => {
    const el = hitRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setBrush({ x: Math.min(PLOT_W, Math.max(0, x)), y: Math.min(PLOT_H, Math.max(0, y)) });
  };

  const step = CELL;
  const keyMove = (dx: number, dy: number) => {
    setBrush((cur) => {
      const base = cur ?? { x: PLOT_W / 2, y: PLOT_H / 2 };
      return {
        x: Math.min(PLOT_W, Math.max(0, base.x + dx)),
        y: Math.min(PLOT_H, Math.max(0, base.y + dy)),
      };
    });
  };

  return (
    <figure className={`ns-csab inline-block ${className}`} aria-label={`${title}, scatter plot`}>
      <style>{CSS}</style>
      <div className="flex items-center justify-between gap-3 pb-2">
        <span className="font-mono text-xs tracking-widest text-ns-muted">{title.toUpperCase()}</span>
        <span className="font-mono text-[11px] text-ns-muted tabular-nums" aria-live="off">
          {selection ? `${selection.n} pts · mean (${selection.meanX.toFixed(1)}, ${selection.meanY.toFixed(1)})` : `${points.length} pts total`}
        </span>
      </div>
      <div className="relative" style={{ width: LEFT_PAD + PLOT_W + RIGHT_PAD, maxWidth: "100%" }}>
        <canvas
          ref={canvasRef}
          aria-hidden="true"
          className="ns-csab-canvas"
          style={{
            width: LEFT_PAD + PLOT_W + RIGHT_PAD,
            height: TOP_PAD + PLOT_H + BOTTOM_PAD,
            maxWidth: "100%",
            display: "block",
          }}
        />
        <div
          ref={hitRef}
          role="button"
          tabIndex={0}
          aria-label="Brush the scatter plot: drag or use arrow keys to select nearby points"
          className="ns-csab-hit absolute cursor-crosshair rounded-sm outline-none"
          style={{ left: LEFT_PAD, top: TOP_PAD, width: PLOT_W, height: PLOT_H }}
          onPointerMove={(e) => setBrushFromEvent(e)}
          onPointerDown={(e) => setBrushFromEvent(e)}
          onPointerLeave={() => setBrush(null)}
          onFocus={() => setBrush((c) => c ?? { x: PLOT_W / 2, y: PLOT_H / 2 })}
          onBlur={() => setBrush(null)}
          onKeyDown={(e) => {
            const d = e.shiftKey ? step * 3 : step;
            if (e.key === "ArrowLeft") {
              e.preventDefault();
              keyMove(-d, 0);
            } else if (e.key === "ArrowRight") {
              e.preventDefault();
              keyMove(d, 0);
            } else if (e.key === "ArrowUp") {
              e.preventDefault();
              keyMove(0, -d);
            } else if (e.key === "ArrowDown") {
              e.preventDefault();
              keyMove(0, d);
            } else if (e.key === "Escape") {
              setBrush(null);
            }
          }}
        />
      </div>
    </figure>
  );
}

const CSS = `
.ns-csab-hit:focus-visible { outline: 2px solid var(--ns-accent); outline-offset: 2px; }
`;

"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// ChartWaterfallAsciiStep — the registry's first waterfall chart. Nearest
// neighbours: chart-funnel-stage-drop tapers a single monotonic total and
// animates its OWN drop-off as falling ink; chart-bar-dither/-halftone are
// one static series per bar with no relationship between bars. Neither
// recomputes a chain — a waterfall's whole point is that every bar's
// position depends on every bar before it.
//
// The mechanic: every intermediate step has a real toggle (click or
// Enter/Space on its hit button, aria-pressed). Toggling excludes or
// restores that step's delta, and every bar from that step onward — plus
// the trailing running total — animates its floating top/bottom AND its
// displayed cumulative number to the new value over ~420ms. This is a
// genuine recompute rendered as motion, not a tooltip: excluding "Refunds"
// visibly redraws the shape of every later step and the total. Hovering or
// focusing (without toggling) shows a tooltip with that step's exact
// contribution and its before/after cumulative, so the read-out is
// available before committing to a change.
//
// Bars keep the family's shared 4x4-Bayer-equivalent ASCII ramp
// (' .:-=+*#%@') as a redundant density channel tracking |delta| — pure
// var(--foreground) ink, var(--ns-accent) reserved for the active/focused step.
// ---------------------------------------------------------------------------

const RAMP = " .:-=+*#%@";

export interface WaterfallStepDatum {
  label: string;
  /** first entry is the starting balance; every following entry is a signed delta */
  delta: number;
}

export interface ChartWaterfallAsciiStepProps {
  /** the steps, in order; the final bar is the running total */
  data?: WaterfallStepDatum[];
  /** heading above the chart */
  title?: string;
  /** label for the final running-total bar */
  totalLabel?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const DEFAULT_DATA: WaterfallStepDatum[] = [
  { label: "Start", delta: 1000 },
  { label: "New signups", delta: 420 },
  { label: "Upgrades", delta: 180 },
  { label: "Churn", delta: -260 },
  { label: "Refunds", delta: -90 },
  { label: "Expansion", delta: 140 },
];

const BAR_W = 30;
const SLOT_W = 62;
const PLOT_H = 190;
const TOP_PAD = 30;
const AXIS_H = 8;
const LABEL_H = 32;
const LEFT_PAD = 12;
const RIGHT_PAD = 12;
const CELL = 4;
const RECOMPUTE_MS = 420;

interface Tokens {
  fg: string;
  bg: string;
  muted: string;
  border: string;
  accent: string;
}

function readTokens(): Tokens {
  const cs = getComputedStyle(document.documentElement);
  const get = (name: string, fallback: string) => cs.getPropertyValue(name).trim() || fallback;
  return {
    fg: get("--foreground", "#171717"),
    bg: get("--background", "#ffffff"),
    muted: get("--ns-muted", "#4d4d4d"),
    border: get("--border", "#ebebeb"),
    accent: get("--ns-accent", "#006bff"),
  };
}

function useTokens(): Tokens {
  const [tokens, setTokens] = useState<Tokens>(() =>
    typeof document === "undefined"
      ? { fg: "#171717", bg: "#ffffff", muted: "#4d4d4d", border: "#ebebeb", accent: "#006bff" }
      : readTokens()
  );
  useEffect(() => {
    const sync = () => setTokens(readTokens());
    sync();
    const mo = new MutationObserver(sync);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style"] });
    return () => mo.disconnect();
  }, []);
  return tokens;
}

function easeOutCubic(t: number): number {
  return 1 - Math.pow(1 - t, 3);
}

function formatValue(v: number): string {
  const sign = v < 0 ? "-" : "";
  const abs = Math.abs(v);
  if (abs >= 1_000_000) return `${sign}${(abs / 1_000_000).toFixed(1).replace(/\.0$/, "")}M`;
  if (abs >= 1_000) return `${sign}${(abs / 1_000).toFixed(1).replace(/\.0$/, "")}K`;
  return `${sign}${Math.round(abs).toLocaleString()}`;
}

interface Bar {
  label: string;
  index: number;
  isStart: boolean;
  isTotal: boolean;
  toggleable: boolean;
  excluded: boolean;
  delta: number;
  from: number;
  to: number;
}

function paintDitherRect(
  ctx: CanvasRenderingContext2D,
  x: number,
  yTop: number,
  yBase: number,
  w: number,
  ch: string,
  ink: string
) {
  if (ch === " ") return;
  ctx.save();
  ctx.beginPath();
  ctx.rect(x, Math.min(yTop, yBase), w, Math.abs(yBase - yTop));
  ctx.clip();
  ctx.fillStyle = ink;
  ctx.font = `${CELL * 2.4}px "GeistMono", ui-monospace, monospace`;
  ctx.textAlign = "left";
  ctx.textBaseline = "top";
  const rowH = CELL * 2.6;
  const top = Math.min(yTop, yBase);
  const bottom = Math.max(yTop, yBase);
  for (let y = top; y < bottom; y += rowH) {
    for (let cx = x; cx < x + w; cx += CELL * 2) {
      ctx.fillText(ch, cx, y);
    }
  }
  ctx.restore();
}

export function ChartWaterfallAsciiStep({
  data = DEFAULT_DATA,
  title = "Chart",
  totalLabel = "Total",
  className = "",
}: ChartWaterfallAsciiStepProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const tokens = useTokens();
  const [excluded, setExcluded] = useState<Set<number>>(new Set());
  const [hoverIndex, setHoverIndex] = useState<number | null>(null);
  // index 0 is always the start bar (display-only, never focusable), so the
  // first real control is index 1
  const [activeIndex, setActiveIndex] = useState(1);
  // useId, not Math.random(): the id is serialized into element ids on the
  // server and must match what the client renders, or React discards the
  // subtree as a hydration mismatch
  const uid = `cwas-${useId().replace(/:/g, "")}`;

  const reducedRef = useRef(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => {
      reducedRef.current = mq.matches;
    };
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);

  const bars: Bar[] = useMemo(() => {
    let cumulative = 0;
    const out: Bar[] = [];
    data.forEach((d, i) => {
      const isStart = i === 0;
      const excludedNow = !isStart && excluded.has(i);
      const from = cumulative;
      const delta = excludedNow ? 0 : d.delta;
      cumulative += delta;
      out.push({
        label: d.label,
        index: i,
        isStart,
        isTotal: false,
        toggleable: !isStart,
        excluded: excludedNow,
        delta: d.delta,
        from,
        to: cumulative,
      });
    });
    out.push({
      label: totalLabel,
      index: data.length,
      isStart: false,
      isTotal: true,
      toggleable: false,
      excluded: false,
      delta: cumulative,
      from: 0,
      to: cumulative,
    });
    return out;
  }, [data, excluded, totalLabel]);

  const maxAbs = useMemo(() => Math.max(1, ...bars.map((b) => Math.max(Math.abs(b.from), Math.abs(b.to)))), [bars]);
  const n = bars.length;
  const viewW = LEFT_PAD + n * SLOT_W + RIGHT_PAD;
  const viewH = TOP_PAD + PLOT_H + AXIS_H + LABEL_H;
  const zeroY = TOP_PAD + PLOT_H;
  const valueToY = (v: number) => zeroY - (v / maxAbs) * PLOT_H;

  // only the intermediate delta steps are real, focusable controls — the
  // start and running-total bars are display-only, so roving tabindex must
  // stay confined to this list or Tab can land on nothing (a disabled
  // button ignores tabIndex entirely)
  const toggleableIndices = useMemo(() => bars.filter((b) => b.toggleable).map((b) => b.index), [bars]);

  useEffect(() => {
    if (!toggleableIndices.includes(activeIndex) && toggleableIndices.length > 0) {
      setActiveIndex(toggleableIndices[0]);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [toggleableIndices]);

  const focusByOffset = (offset: number) => {
    const from = toggleableIndices.indexOf(activeIndex);
    const nextPos = Math.min(toggleableIndices.length - 1, Math.max(0, (from < 0 ? 0 : from) + offset));
    const target = toggleableIndices[nextPos];
    if (target === undefined) return;
    setActiveIndex(target);
    document.getElementById(`${uid}-hit-${target}`)?.focus();
  };

  const toggle = (b: Bar) => {
    if (!b.toggleable) return;
    setExcluded((cur) => {
      const next = new Set(cur);
      if (next.has(b.index)) next.delete(b.index);
      else next.add(b.index);
      return next;
    });
  };

  // animated per-bar "to" value + displayed cumulative, lerped every frame
  // toward the freshly computed target so a toggle reads as a live recompute
  const displayToRef = useRef<number[]>([]);
  const rafRef = useRef(0);

  useEffect(() => {
    if (displayToRef.current.length !== n) {
      displayToRef.current = bars.map((b) => b.to);
    }
  }, [n, bars]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = viewW * dpr;
    canvas.height = viewH * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const draw = () => {
      ctx.clearRect(0, 0, viewW, viewH);

      ctx.strokeStyle = tokens.border;
      ctx.lineWidth = 1;
      const zy = Math.round(valueToY(0)) + 0.5;
      ctx.beginPath();
      ctx.moveTo(LEFT_PAD, zy);
      ctx.lineTo(viewW - RIGHT_PAD, zy);
      ctx.stroke();

      let stillAnimating = false;

      bars.forEach((b, i) => {
        const x = LEFT_PAD + i * SLOT_W + (SLOT_W - BAR_W) / 2;
        const curTo = displayToRef.current[i] ?? b.to;
        const nextTo = reducedRef.current ? b.to : curTo + (b.to - curTo) * 0.24;
        displayToRef.current[i] = Math.abs(nextTo - b.to) < 0.5 ? b.to : nextTo;
        if (Math.abs(displayToRef.current[i] - b.to) >= 0.5) stillAnimating = true;

        const yFrom = valueToY(b.isTotal ? 0 : b.from);
        const yTo = valueToY(b.isTotal ? displayToRef.current[i] : displayToRef.current[i]);

        // hoverIndex alone carries real interaction (pointer hover AND
        // keyboard focus both set it) — activeIndex is only roving-tabindex
        // bookkeeping and must never tint a resting, unfocused bar
        const isActive = hoverIndex === i;
        const level = Math.min(
          RAMP.length - 1,
          Math.round((Math.abs(b.isTotal ? b.to : b.to - b.from) / maxAbs) * (RAMP.length - 1))
        );
        const ch = b.excluded ? RAMP[1] : RAMP[Math.max(level, 2)];
        const ink = isActive ? tokens.accent : b.excluded ? tokens.muted : tokens.fg;

        paintDitherRect(ctx, x, yFrom, yTo, BAR_W, ch, ink);
        ctx.strokeStyle = ink;
        ctx.lineWidth = 1;
        ctx.strokeRect(x + 0.5, Math.min(yFrom, yTo) + 0.5, BAR_W, Math.abs(yTo - yFrom));

        // connector to next bar
        if (i < bars.length - 1) {
          ctx.strokeStyle = tokens.border;
          ctx.setLineDash([2, 2]);
          const connY = valueToY(displayToRef.current[i]);
          ctx.beginPath();
          ctx.moveTo(x + BAR_W, connY);
          ctx.lineTo(x + SLOT_W + (SLOT_W - BAR_W) / 2, connY);
          ctx.stroke();
          ctx.setLineDash([]);
        }

        ctx.font = `9.5px "GeistMono", ui-monospace, monospace`;
        ctx.textAlign = "center";
        ctx.fillStyle = ink;
        const labelValue = b.isTotal ? displayToRef.current[i] : b.excluded ? 0 : b.delta;
        const prefix = !b.isStart && !b.isTotal && labelValue >= 0 ? "+" : "";
        ctx.fillText(`${prefix}${formatValue(labelValue)}`, x + BAR_W / 2, Math.min(yFrom, yTo) - 8);
        ctx.fillStyle = tokens.muted;
        ctx.fillText(b.label, x + BAR_W / 2, zeroY + AXIS_H + 12);
        if (b.toggleable) {
          ctx.fillText(b.excluded ? "(excluded)" : "", x + BAR_W / 2, zeroY + AXIS_H + 24);
        }
      });

      if (stillAnimating && !reducedRef.current) {
        rafRef.current = requestAnimationFrame(draw);
      }
    };

    draw();
    return () => cancelAnimationFrame(rafRef.current);
  }, [bars, tokens, viewW, viewH, maxAbs, hoverIndex, activeIndex, zeroY]);

  const hovered = hoverIndex !== null ? bars[hoverIndex] : null;

  return (
    <figure className={`ns-cwas inline-block ${className}`} aria-label={`${title}, waterfall chart`}>
      <style>{CSS}</style>
      <div className="flex items-center justify-between gap-3 pb-2">
        <span className="font-mono text-xs tracking-widest text-ns-muted">{title.toUpperCase()}</span>
        <span className="font-mono text-[10px] tracking-widest text-ns-muted">
          {excluded.size > 0 ? `${excluded.size} STEP${excluded.size > 1 ? "S" : ""} EXCLUDED` : "ALL STEPS ACTIVE"}
        </span>
      </div>

      <div className="relative" style={{ width: viewW, maxWidth: "100%" }}>
        <canvas
          ref={canvasRef}
          aria-hidden="true"
          className="ns-cwas-canvas"
          style={{ width: viewW, height: viewH, maxWidth: "100%", display: "block" }}
        />

        {bars.map((b) =>
          b.toggleable ? (
            <button
              key={b.index}
              type="button"
              id={`${uid}-hit-${b.index}`}
              tabIndex={activeIndex === b.index ? 0 : -1}
              aria-label={`${b.label}: ${formatValue(b.delta)}${b.excluded ? ", excluded" : ""}`}
              aria-pressed={!b.excluded}
              className="ns-cwas-hit absolute cursor-pointer border-0 bg-transparent p-0 outline-none"
              style={{
                left: LEFT_PAD + b.index * SLOT_W,
                top: TOP_PAD - 16,
                width: SLOT_W,
                height: PLOT_H + 16,
              }}
              onPointerEnter={() => setHoverIndex(b.index)}
              onPointerLeave={() => setHoverIndex((c) => (c === b.index ? null : c))}
              onFocus={() => {
                setActiveIndex(b.index);
                setHoverIndex(b.index);
              }}
              onBlur={() => setHoverIndex((c) => (c === b.index ? null : c))}
              onClick={() => toggle(b)}
              onKeyDown={(e) => {
                if (e.key === "ArrowLeft") {
                  e.preventDefault();
                  focusByOffset(-1);
                } else if (e.key === "ArrowRight") {
                  e.preventDefault();
                  focusByOffset(1);
                }
              }}
            />
          ) : (
            // start / running-total bars are display-only, not real controls
            <div
              key={b.index}
              aria-hidden="true"
              className="ns-cwas-hover absolute"
              style={{
                left: LEFT_PAD + b.index * SLOT_W,
                top: TOP_PAD - 16,
                width: SLOT_W,
                height: PLOT_H + 16,
              }}
              onPointerEnter={() => setHoverIndex(b.index)}
              onPointerLeave={() => setHoverIndex((c) => (c === b.index ? null : c))}
            />
          )
        )}

        {hovered && (
          <div
            aria-hidden="true"
            className="ns-cwas-tip pointer-events-none absolute z-10 rounded-sm border border-border bg-background px-2 py-1 font-mono text-[11px] shadow-sm"
            style={{
              left: `${((LEFT_PAD + hovered.index * SLOT_W + SLOT_W / 2) / viewW) * 100}%`,
              top: `${(Math.max(0, valueToY(Math.max(hovered.from, hovered.to)) - 46) / viewH) * 100}%`,
              transform: "translateX(-50%)",
            }}
          >
            <strong className="text-foreground">
              {hovered.toggleable ? formatValue(hovered.delta) : formatValue(hovered.to)}
            </strong>{" "}
            <span className="text-ns-muted">
              {hovered.toggleable ? `${formatValue(hovered.from)} → ${formatValue(hovered.to)}` : "running total"}
            </span>
          </div>
        )}
      </div>
    </figure>
  );
}

const CSS = `
.ns-cwas-hit { touch-action: manipulation; }
.ns-cwas-hit:focus-visible { outline: 2px solid var(--ns-accent); outline-offset: 2px; }
`;

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type ChangeEvent,
} from "react";

// ---------------------------------------------------------------------------
// ToppleRun — a select-all whose propagation is the interaction model, not a
// cosmetic stagger. Flipping the master checkbox releases a wavefront that
// travels down the list at a fixed rate (14 rows/sec): as the front reaches
// row i, that row's own checkbox commits its new state under a 120ms
// spring-eased transition and the row takes a transient translateY(2px)
// lean toward row i+1 — read as the wave shoving the next domino — handed
// off with a short overlap so consecutive leans read as continuous contact.
// A thin tick travels the list's left edge marking the front's live
// position. Every row commits its state the instant the front passes it, so
// there is nothing to roll back: stopping the run just stops future rows
// from being touched.
//
// INTERRUPTION: the run is spatially interruptible, not just cancelable —
// activating ANY row (pointer or keyboard, since every row stays a fully
// operable checkbox for the run's entire duration) halts the wave
// immediately. Rows the front already passed keep their committed state;
// rows beyond the front are simply untouched, standing exactly as they
// were. Escape halts it too. This is the "all except a few" recovery path:
// watch the run, stop it where you want, no undo needed because nothing
// past that point was ever touched.
//
// A11Y: the master is a real input[type=checkbox] with aria-controls
// pointing at the row list's id; a polite live region announces once at
// the start ("Enabling all…") and once at the end or halt ("Enabled 34 of
// 40, stopped at row 35."). Every row is a real checkbox with its own
// native label association — nothing here is conveyed only by animation.
//
// REDUCED MOTION: there is no wave to catch, so interruption is replaced by
// a straightforward safety net — the master flips every row in a single
// frame and a 5s Undo affordance appears, reverting the whole batch if
// pressed in time.
//
// TOKENS: --foreground for ink (checkbox fill, the traveling tick),
// --border for hairlines, --ns-muted for secondary text, --ns-accent for the
// focus ring only. Pure DOM/CSS, no canvas.
// ---------------------------------------------------------------------------

const ROWS_PER_SEC = 14;
const ROW_H = 56; // px — must match the row wrapper's fixed height
const LEAN_MS = Math.round(1000 / ROWS_PER_SEC) + 40; // ~111ms, overlaps the next row's start
const UNDO_MS = 5000;

export interface ToppleRunItem {
  /** Stable identifier for this row. */
  id: string;
  /** Primary row label — also becomes its checkbox's accessible name. */
  label: string;
  /** Optional secondary line (sender, timestamp, byline...). */
  description?: string;
}

export interface ToppleRunProps {
  /** Rows the master toggle governs, top to bottom = wave direction. */
  items: ToppleRunItem[];
  /** Label for the master control. @default "Select all" */
  label?: string;
  /** Ids checked on mount. @default [] */
  defaultChecked?: string[];
  /** Fires whenever the checked set changes, including mid-run commits. */
  onChange?: (checkedIds: string[]) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

function useReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const onChange = () => setReduced(mq.matches);
    onChange();
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

interface Row extends ToppleRunItem {
  checked: boolean;
}

export function ToppleRun({
  items,
  label = "Select all",
  defaultChecked = [],
  onChange,
  className = "",
}: ToppleRunProps) {
  const uid = useId();
  const reducedMotion = useReducedMotion();

  const [rows, setRows] = useState<Row[]>(() =>
    items.map((item) => ({
      ...item,
      checked: defaultChecked.includes(item.id),
    }))
  );
  const [running, setRunning] = useState(false);
  const [liveMsg, setLiveMsg] = useState("");
  const [undoAvailable, setUndoAvailable] = useState(false);

  const masterRef = useRef<HTMLInputElement | null>(null);
  const rowElRefs = useRef<(HTMLLIElement | null)[]>([]);
  const tickRef = useRef<HTMLDivElement | null>(null);

  const rafRef = useRef<number | undefined>(undefined);
  const runTokenRef = useRef(0);
  const committedRef = useRef(-1);
  const startTimeRef = useRef(0);
  const targetRef = useRef(true);
  const leanTimersRef = useRef<Map<number, ReturnType<typeof setTimeout>>>(
    new Map()
  );
  const undoSnapshotRef = useRef<Row[] | null>(null);
  const undoTimerRef = useRef<ReturnType<typeof setTimeout> | undefined>(
    undefined
  );

  const total = rows.length;
  const checkedCount = rows.reduce((n, r) => (r.checked ? n + 1 : n), 0);
  const allChecked = total > 0 && checkedCount === total;
  const noneChecked = checkedCount === 0;
  const indeterminate = !allChecked && !noneChecked;

  useEffect(() => {
    if (masterRef.current) masterRef.current.indeterminate = indeterminate;
  }, [indeterminate]);

  const firstRender = useRef(true);
  useEffect(() => {
    if (firstRender.current) {
      firstRender.current = false;
      return;
    }
    onChange?.(rows.filter((r) => r.checked).map((r) => r.id));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [rows]);

  const clearLeanTimers = useCallback(() => {
    leanTimersRef.current.forEach((t) => clearTimeout(t));
    leanTimersRef.current.clear();
  }, []);

  const commitRow = useCallback((index: number, checked: boolean) => {
    setRows((prev) => {
      if (prev[index]?.checked === checked) return prev;
      const next = prev.slice();
      next[index] = { ...next[index]!, checked };
      return next;
    });
    const el = rowElRefs.current[index];
    if (el) {
      el.style.transform = "translateY(2px)";
      const prevTimer = leanTimersRef.current.get(index);
      if (prevTimer) clearTimeout(prevTimer);
      leanTimersRef.current.set(
        index,
        setTimeout(() => {
          el.style.transform = "";
          leanTimersRef.current.delete(index);
        }, LEAN_MS)
      );
    }
  }, []);

  const endRun = useCallback(
    (committedCount: number, rowTotal: number) => {
      if (rafRef.current !== undefined) {
        cancelAnimationFrame(rafRef.current);
        rafRef.current = undefined;
      }
      setRunning(false);
      if (tickRef.current) tickRef.current.style.opacity = "0";
      const verb = targetRef.current ? "Enabled" : "Disabled";
      if (rowTotal === 0) {
        setLiveMsg("");
      } else if (committedCount >= rowTotal) {
        setLiveMsg(`${verb} all ${rowTotal}.`);
      } else {
        setLiveMsg(
          `${verb} ${committedCount} of ${rowTotal}, stopped at row ${
            committedCount + 1
          }.`
        );
      }
    },
    []
  );

  const haltRun = useCallback(() => {
    if (!running) return;
    runTokenRef.current += 1;
    endRun(committedRef.current + 1, total);
  }, [running, endRun, total]);

  const startRun = useCallback(
    (target: boolean) => {
      if (total === 0) return;
      if (rafRef.current !== undefined) cancelAnimationFrame(rafRef.current);
      clearLeanTimers();

      runTokenRef.current += 1;
      const token = runTokenRef.current;
      targetRef.current = target;
      committedRef.current = -1;
      startTimeRef.current = performance.now();
      setRunning(true);
      setLiveMsg(target ? "Enabling all…" : "Disabling all…");
      if (tickRef.current) {
        tickRef.current.style.opacity = "1";
        tickRef.current.style.transform = "translateY(0px)";
      }

      const step = (now: number) => {
        if (runTokenRef.current !== token) return;
        const elapsedS = (now - startTimeRef.current) / 1000;
        const front = elapsedS * ROWS_PER_SEC;
        if (tickRef.current) {
          tickRef.current.style.transform = `translateY(${
            Math.min(front, total) * ROW_H
          }px)`;
        }
        while (committedRef.current + 1 < total && committedRef.current + 1 <= front) {
          const i = committedRef.current + 1;
          commitRow(i, target);
          committedRef.current = i;
        }
        if (committedRef.current >= total - 1) {
          endRun(total, total);
          return;
        }
        rafRef.current = requestAnimationFrame(step);
      };
      rafRef.current = requestAnimationFrame(step);
    },
    [total, clearLeanTimers, commitRow, endRun]
  );

  // Escape halts a live run from anywhere.
  useEffect(() => {
    if (!running) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") haltRun();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [running, haltRun]);

  useEffect(() => {
    return () => {
      if (rafRef.current !== undefined) cancelAnimationFrame(rafRef.current);
      clearLeanTimers();
      if (undoTimerRef.current) clearTimeout(undoTimerRef.current);
    };
  }, [clearLeanTimers]);

  const handleMasterChange = useCallback(
    (e: ChangeEvent<HTMLInputElement>) => {
      const target = e.target.checked;
      if (total === 0) return;

      if (reducedMotion) {
        if (undoTimerRef.current) clearTimeout(undoTimerRef.current);
        undoSnapshotRef.current = rows.map((r) => ({ ...r }));
        setRows((prev) => prev.map((r) => ({ ...r, checked: target })));
        setLiveMsg(
          target ? `Enabled all ${total}.` : `Disabled all ${total}.`
        );
        setUndoAvailable(true);
        undoTimerRef.current = setTimeout(() => {
          setUndoAvailable(false);
          undoSnapshotRef.current = null;
        }, UNDO_MS);
        return;
      }

      startRun(target);
    },
    [total, reducedMotion, rows, startRun]
  );

  const handleRowChange = useCallback(
    (index: number, checked: boolean) => {
      if (running) haltRun();
      setRows((prev) => {
        const next = prev.slice();
        next[index] = { ...next[index]!, checked };
        return next;
      });
    },
    [running, haltRun]
  );

  const handleUndo = useCallback(() => {
    if (undoTimerRef.current) clearTimeout(undoTimerRef.current);
    if (undoSnapshotRef.current) {
      const snapshot = undoSnapshotRef.current;
      setRows(snapshot);
      setLiveMsg("Undone.");
    }
    setUndoAvailable(false);
    undoSnapshotRef.current = null;
  }, []);

  const groupId = `checkbox-domino-run-${uid}-group`;
  const liveId = `checkbox-domino-run-${uid}-live`;

  return (
    <div className={`w-full rounded-md border border-border bg-surface ${className}`}>
      <div id={liveId} aria-live="polite" className="sr-only">
        {liveMsg}
      </div>

      <label className="relative flex h-14 cursor-pointer select-none items-center gap-3 border-b border-border px-4">
        <input
          ref={masterRef}
          type="checkbox"
          className="peer absolute inset-0 z-10 h-full w-full cursor-pointer opacity-0 focus:outline-none"
          checked={allChecked}
          onChange={handleMasterChange}
          aria-controls={groupId}
        />
        <CheckboxVisual
          checked={allChecked}
          indeterminate={indeterminate}
          reducedMotion={reducedMotion}
        />
        <span className="flex-1 text-[13px] font-medium text-foreground">
          {label}
        </span>
        <span aria-hidden="true" className="font-mono text-[11px] text-ns-muted">
          {checkedCount}/{total}
        </span>
      </label>

      <div className="relative">
        <div
          ref={tickRef}
          aria-hidden="true"
          className="pointer-events-none absolute left-0 top-0 z-10 w-[2px] bg-foreground opacity-0"
          style={{ height: ROW_H, willChange: "transform" }}
        />
        <ul id={groupId}>
          {rows.map((row, i) => (
            <li
              key={row.id}
              ref={(el) => {
                rowElRefs.current[i] = el;
              }}
              style={{
                height: ROW_H,
                transition: reducedMotion
                  ? undefined
                  : `transform ${LEAN_MS}ms cubic-bezier(0.34, 1.56, 0.64, 1)`,
              }}
              className={i < rows.length - 1 ? "border-b border-border" : ""}
            >
              <label className="relative flex h-full cursor-pointer select-none items-center gap-3 px-4">
                <input
                  type="checkbox"
                  className="peer absolute inset-0 z-10 h-full w-full cursor-pointer opacity-0 focus:outline-none"
                  checked={row.checked}
                  onChange={(e) => handleRowChange(i, e.target.checked)}
                />
                <CheckboxVisual
                  checked={row.checked}
                  reducedMotion={reducedMotion}
                />
                <span className="min-w-0 flex-1">
                  <span className="block truncate text-[13px] text-foreground">
                    {row.label}
                  </span>
                  {row.description && (
                    <span className="block truncate text-[12px] text-ns-muted">
                      {row.description}
                    </span>
                  )}
                </span>
              </label>
            </li>
          ))}
        </ul>
      </div>

      {undoAvailable && (
        <div className="flex items-center justify-between gap-3 border-t border-border px-4 py-3">
          <span className="text-[12px] text-ns-muted">
            Batch applied — undo within {UNDO_MS / 1000}s.
          </span>
          <button
            type="button"
            onClick={handleUndo}
            className="rounded-sm border border-border px-2.5 py-1 text-[12px] font-medium text-foreground transition-colors duration-150 hover:border-foreground/40 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
          >
            Undo
          </button>
        </div>
      )}
    </div>
  );
}

function CheckboxVisual({
  checked,
  indeterminate = false,
  reducedMotion = false,
}: {
  checked: boolean;
  indeterminate?: boolean;
  reducedMotion?: boolean;
}) {
  const springDuration = reducedMotion ? "0ms" : "120ms";
  const springEase = "cubic-bezier(0.34, 1.56, 0.64, 1)";
  return (
    <span
      aria-hidden="true"
      className="relative inline-flex h-5 w-5 shrink-0 items-center justify-center rounded-[6px] border border-border bg-background peer-checked:border-foreground peer-checked:bg-foreground peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-ns-accent"
      style={{
        transition: `background-color ${springDuration} ${springEase}, border-color ${springDuration} ${springEase}`,
      }}
    >
      <svg
        viewBox="0 0 16 16"
        className="h-3 w-3 text-background"
        style={{
          opacity: checked && !indeterminate ? 1 : 0,
          transform: checked && !indeterminate ? "scale(1)" : "scale(0.5)",
          transition: `opacity ${springDuration} ${springEase}, transform ${springDuration} ${springEase}`,
        }}
      >
        <path
          d="M3 8.2L6.2 11.4L13 4.4"
          fill="none"
          stroke="currentColor"
          strokeWidth={2}
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
      <span
        className="absolute h-[2px] w-2.5 rounded-full bg-background"
        style={{
          opacity: indeterminate ? 1 : 0,
          transition: `opacity ${springDuration} ${springEase}`,
        }}
      />
    </span>
  );
}

"use client";

import {
  useEffect,
  useId,
  useRef,
  useState,
  type ChangeEvent,
  type ReactNode,
} from "react";

// ---------------------------------------------------------------------------
// NibCheck — a checkbox (and tri-state parent) whose mark is inked on by a
// variable-width calligraphic stroke: thin entry, a thick corner flick, and a
// hair of overshoot past the natural tip. The three states — unchecked,
// checked, indeterminate — read as three distinct pen gestures rather than a
// check, a smaller check, and a minus.
//
// GEOMETRY: the check is one filled ribbon path built once at module scope by
// offsetting a hand-placed spine polyline with a per-point half-width (thin
// at the entry, widest right at the corner, tapering through the flick to a
// hairline overshoot tip) — see buildRibbon. Interior normals average their
// two adjacent segment normals, so the sharp direction change at the corner
// naturally bulges on the convex side and pinches on the concave one, like
// ink pooling as a pen changes direction. Indeterminate draws a separate,
// simpler fat rounded dash — not a shrunk-down check.
//
// REVEAL: both ink shapes sit under a left-anchored CSS clip-path (inset,
// fill-box) that transitions from fully clipped to fully revealed over
// ~220ms ease-out-expo, reading as ink drawn left-to-right: entry, corner,
// tip. Unchecking reverses the same clip back toward the entry edge — ink
// retracts — and a small dot at the entry point pops in and fades once
// retraction finishes. The box's own corner radius relaxes 2px on check, with
// a small imperative class-toggle "pop" (restarted without remounting, so
// focus never moves) standing in for the flick's ~4% overshoot.
//
// A11Y: a real input[type=checkbox] carries checked/indeterminate/disabled
// and all native keyboard + AT semantics; it is visually hidden (opacity: 0,
// sized to cover the box) but stays in the tab order and keeps focus — never
// aria-hidden. The SVG ink is aria-hidden. Colors: ink is --foreground, the
// box border is --border; --ns-accent appears only in the focus ring.
// prefers-reduced-motion disables every transition/animation here, so the
// final ink for the current state is simply present or absent, instantly.
// ---------------------------------------------------------------------------

type Pt = readonly [number, number];

function normalize(v: Pt): Pt {
  const len = Math.hypot(v[0], v[1]) || 1;
  return [v[0] / len, v[1] / len];
}

// rotate a direction vector 90 degrees (SVG's y-down space)
function perp(v: Pt): Pt {
  return [-v[1], v[0]];
}

/**
 * Offsets a spine polyline by a per-point half-width to build a closed,
 * filled ribbon outline — the calligraphic nib's variable-width stroke.
 */
function buildRibbon(spine: Pt[], halfWidth: number[]): string {
  const n = spine.length;
  const segNormals: Pt[] = [];
  for (let i = 0; i < n - 1; i++) {
    const dx = spine[i + 1]![0] - spine[i]![0];
    const dy = spine[i + 1]![1] - spine[i]![1];
    segNormals.push(normalize(perp([dx, dy])));
  }
  const ptNormals: Pt[] = spine.map((_, i) => {
    if (i === 0) return segNormals[0]!;
    if (i === n - 1) return segNormals[n - 2]!;
    const a = segNormals[i - 1]!;
    const b = segNormals[i]!;
    return normalize([a[0] + b[0], a[1] + b[1]]);
  });

  const left = spine.map((p, i) => [
    p[0] + ptNormals[i]![0] * halfWidth[i]!,
    p[1] + ptNormals[i]![1] * halfWidth[i]!,
  ]);
  const right = spine.map((p, i) => [
    p[0] - ptNormals[i]![0] * halfWidth[i]!,
    p[1] - ptNormals[i]![1] * halfWidth[i]!,
  ]);

  const fmt = (p: number[]) => `${p[0]!.toFixed(2)},${p[1]!.toFixed(2)}`;
  let d = `M${fmt(left[0]!)}`;
  for (let i = 1; i < n; i++) d += ` L${fmt(left[i]!)}`;
  for (let i = n - 1; i >= 0; i--) d += ` L${fmt(right[i]!)}`;
  return `${d} Z`;
}

// spine: entry (bottom-left, thin) -> corner (thick flick) -> tip, with a
// small overshoot past the corner's natural stopping point at the very end
const SPINE: Pt[] = [
  [4, 12.4],
  [7.6, 15.6],
  [9.7, 18],
  [12.3, 15.1],
  [15.2, 11.5],
  [18.1, 8],
  [19.7, 6.1],
];
const HALF_WIDTH = [0.55, 1.05, 1.7, 1.55, 1.15, 0.7, 0.35];
const CHECK_PATH = buildRibbon(SPINE, HALF_WIDTH);
const ENTRY: Pt = SPINE[0]!;

// indeterminate: a single fat rounded dash, not a shrunk checkmark
const DASH = { x: 6, y: 10.6, width: 12, height: 2.8, rx: 1.4 };

export type NibCheckValue = boolean | "indeterminate";

export interface NibCheckProps {
  /** controlled value; omit for uncontrolled. "indeterminate" is visual/AT only — the underlying value is boolean */
  checked?: NibCheckValue;
  /** initial value when uncontrolled. Default false. */
  defaultChecked?: NibCheckValue;
  /** called with the resolved boolean after a toggle; never fires "indeterminate" */
  onCheckedChange?: (checked: boolean) => void;
  /** blocks the input and mutes the box; the label cursor becomes not-allowed */
  disabled?: boolean;
  /** visible label; also becomes the accessible name via native label association */
  label?: ReactNode;
  /** id for the underlying `<input type="checkbox">`. Auto-generated when omitted. */
  id?: string;
  /** name for the underlying `<input>`, for native form submission */
  name?: string;
  /** value for the underlying `<input>`, for native form submission */
  value?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** accessible name for the input, used only when `label` is omitted */
  "aria-label"?: string;
}

export function NibCheck({
  checked,
  defaultChecked = false,
  onCheckedChange,
  disabled = false,
  label,
  id,
  name,
  value,
  className = "",
  "aria-label": ariaLabel,
}: NibCheckProps) {
  const autoId = useId();
  const inputId = id ?? `checkbox-ink-stroke-${autoId}`;
  const inputRef = useRef<HTMLInputElement>(null);
  const boxRef = useRef<HTMLSpanElement>(null);
  const reducedRef = useRef(false);

  const isControlled = checked !== undefined;
  const [internal, setInternal] = useState<NibCheckValue>(defaultChecked);
  const current = isControlled ? checked! : internal;
  const state: "checked" | "unchecked" | "indeterminate" =
    current === "indeterminate" ? "indeterminate" : current ? "checked" : "unchecked";

  const [dotTick, setDotTick] = useState(0);
  const [showDot, setShowDot] = useState(false);
  const prevStateRef = useRef(state);

  useEffect(() => {
    reducedRef.current = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;
  }, []);

  // native indeterminate is a DOM property, not an attribute
  useEffect(() => {
    if (inputRef.current) inputRef.current.indeterminate = state === "indeterminate";
  }, [state]);

  // fading entry dot only when ink actually retracts (checked/indeterminate -> unchecked)
  useEffect(() => {
    const prev = prevStateRef.current;
    if (prev !== "unchecked" && state === "unchecked" && !reducedRef.current) {
      setDotTick((t) => t + 1);
      setShowDot(true);
    }
    prevStateRef.current = state;
  }, [state]);

  // restart the box's small settle-pop each time the check lands — an
  // imperative class-toggle restart, not a remount, so the input never loses focus
  useEffect(() => {
    const el = boxRef.current;
    if (!el || reducedRef.current || state !== "checked") return;
    el.classList.remove("ns-nib-pop");
    void el.offsetWidth;
    el.classList.add("ns-nib-pop");
  }, [state]);

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    const next = e.target.checked;
    if (!isControlled) setInternal(next);
    onCheckedChange?.(next);
  };

  return (
    <label
      htmlFor={label ? inputId : undefined}
      className={`inline-flex items-center gap-2.5 ${
        disabled ? "cursor-not-allowed" : "cursor-pointer"
      } ${className}`}
    >
      <style>{`
        .ns-nib-box {
          transition: border-radius 200ms cubic-bezier(.16,1,.3,1), border-color 150ms cubic-bezier(.16,1,.3,1);
        }
        .ns-nib-ink {
          clip-path: inset(0 100% 0 0) fill-box;
          transition: clip-path 220ms cubic-bezier(.16,1,.3,1);
        }
        [data-state="checked"] .ns-nib-ink-check,
        [data-state="indeterminate"] .ns-nib-ink-dash {
          clip-path: inset(0 0 0 0) fill-box;
        }
        [data-state="checked"] .ns-nib-box {
          border-radius: 6px;
        }
        .ns-nib-dot {
          animation: ns-nib-dot-fade 320ms cubic-bezier(.16,1,.3,1) forwards;
        }
        @keyframes ns-nib-dot-fade {
          0% { opacity: 1; }
          100% { opacity: 0; }
        }
        .ns-nib-pop {
          animation: ns-nib-pop-settle 220ms cubic-bezier(.34,1.4,.64,1);
        }
        @keyframes ns-nib-pop-settle {
          0% { transform: scale(1); }
          55% { transform: scale(1.04); }
          100% { transform: scale(1); }
        }
        @media (prefers-reduced-motion: reduce) {
          .ns-nib-box, .ns-nib-ink { transition: none !important; }
          .ns-nib-dot, .ns-nib-pop { animation: none !important; }
        }
      `}</style>
      <span className="relative inline-flex h-[18px] w-[18px] shrink-0">
        <input
          ref={inputRef}
          type="checkbox"
          id={inputId}
          name={name}
          value={value}
          checked={current === true}
          disabled={disabled}
          onChange={handleChange}
          aria-label={label ? undefined : ariaLabel ?? "Checkbox"}
          className="peer absolute inset-0 h-full w-full cursor-pointer appearance-none opacity-0 disabled:cursor-not-allowed"
        />
        <span
          ref={boxRef}
          data-state={state}
          aria-hidden
          className={`ns-nib-box pointer-events-none absolute inset-0 rounded-[4px] border border-border peer-hover:border-foreground/30 peer-focus-visible:outline peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-ns-accent ${
            disabled ? "opacity-40" : ""
          }`}
        >
          <svg
            aria-hidden
            viewBox="0 0 24 24"
            className="pointer-events-none absolute inset-0 h-full w-full text-foreground"
          >
            <path
              d={CHECK_PATH}
              data-nib-ink="check"
              className="ns-nib-ink ns-nib-ink-check fill-current"
            />
            <rect
              x={DASH.x}
              y={DASH.y}
              width={DASH.width}
              height={DASH.height}
              rx={DASH.rx}
              data-nib-ink="dash"
              className="ns-nib-ink ns-nib-ink-dash fill-current"
            />
            {showDot && (
              <circle
                key={dotTick}
                cx={ENTRY[0]}
                cy={ENTRY[1]}
                r={1.15}
                className="ns-nib-dot fill-current"
                onAnimationEnd={() => setShowDot(false)}
              />
            )}
          </svg>
        </span>
      </span>
      {label && (
        <span className={`text-sm text-foreground ${disabled ? "opacity-40" : ""}`}>
          {label}
        </span>
      )}
    </label>
  );
}

"use client";

import { useMemo, useRef, useState } from "react";

// Checkbox group rendered as a carpenter's tally: each check carves a notch
// stroke into the row and adds a stroke to an aggregate tally cluster, where
// every fifth stroke slashes diagonally across its group of four. Strokes
// draw on with a dashoffset sweep and retract on uncheck; per-stroke jitter
// is seeded by index so the carving looks hand-cut but renders identically
// every mount. Pure DOM+SVG, tokens only, reduced-motion snaps instantly.

export interface TallyNotchItem {
  id: string;
  label: string;
  hint?: string;
}

export interface TallyNotchProps {
  /** the checkbox rows, in order */
  items: TallyNotchItem[];
  /** ids checked at mount */
  defaultChecked?: string[];
  /** called with the full list of checked ids after any toggle */
  onChange?: (checkedIds: string[]) => void;
  /** heading shown above the group; also the group's accessible name */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

// deterministic per-index jitter — mulberry32, so screenshots are stable
function jitter(i: number) {
  let t = (i + 1) * 0x6d2b79f5;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  const r = ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  return r * 2 - 1; // -1..1
}

// delay folded into the shorthand itself, not a separate transitionDelay
// longhand — mixing transition (shorthand) and transitionDelay (longhand)
// for the same property gives React two owners for one CSS value and it
// warns (and can genuinely race) on rerender.
const STROKE_STYLE = (drawn: boolean, reduced: boolean, delayMs = 0) =>
  ({
    strokeDasharray: 1,
    strokeDashoffset: drawn ? 0 : 1,
    transition: reduced
      ? "none"
      : `stroke-dashoffset 260ms ${drawn ? "cubic-bezier(0.22, 1, 0.36, 1)" : "cubic-bezier(0.55, 0, 0.55, 0.2)"} ${delayMs}ms`,
  }) as const;

function TallyCluster({
  count,
  max,
  reduced,
}: {
  count: number;
  max: number;
  reduced: boolean;
}) {
  const groups = Math.ceil(max / 5);
  const GW = 30; // group width
  const H = 26;
  const paths = useMemo(() => {
    const out: { d: string; idx: number }[] = [];
    for (let i = 0; i < max; i++) {
      const g = Math.floor(i / 5);
      const k = i % 5;
      const gx = g * (GW + 10);
      if (k < 4) {
        // vertical stroke with seeded lean and length variance
        const x = gx + 4 + k * 6 + jitter(i) * 1.2;
        const lean = jitter(i * 7 + 3) * 1.8;
        const top = 3 + jitter(i * 13 + 5) * 1.4;
        out.push({ d: `M ${x + lean} ${top} L ${x - lean} ${H - 3}`, idx: i });
      } else {
        // the fifth: a diagonal slash across the group of four
        const y1 = 6 + jitter(i) * 1.5;
        const y2 = H - 6 + jitter(i * 3) * 1.5;
        out.push({ d: `M ${gx - 1} ${y1} L ${gx + 23} ${y2}`, idx: i });
      }
    }
    return out;
  }, [max]);

  return (
    <svg
      aria-hidden
      width={groups * (GW + 10) - 10}
      height={H}
      viewBox={`0 0 ${groups * (GW + 10) - 10} ${H}`}
      className="overflow-visible"
    >
      {paths.map((p) => (
        <path
          key={p.idx}
          d={p.d}
          pathLength={1}
          fill="none"
          stroke="var(--foreground)"
          strokeWidth={p.idx % 5 === 4 ? 2 : 1.75}
          strokeLinecap="round"
          // later strokes draw a beat after earlier ones when several
          // arrive at once (e.g. defaultChecked mount)
          style={STROKE_STYLE(p.idx < count, reduced, reduced ? 0 : (p.idx % 5) * 30)}
        />
      ))}
    </svg>
  );
}

function NotchMark({ checked, reduced }: { checked: boolean; reduced: boolean }) {
  return (
    <svg aria-hidden width={20} height={20} viewBox="0 0 20 20" className="shrink-0">
      <rect
        x={1.5}
        y={1.5}
        width={17}
        height={17}
        rx={4}
        fill="none"
        stroke={checked ? "var(--foreground)" : "var(--border)"}
        strokeWidth={1.5}
        style={{ transition: reduced ? "none" : "stroke 200ms ease" }}
      />
      {/* two-cut carved notch: down-stroke lands, then the long up-stroke */}
      <path
        d="M 5.5 10.5 L 8.5 13.8"
        pathLength={1}
        fill="none"
        stroke="var(--foreground)"
        strokeWidth={2}
        strokeLinecap="round"
        style={STROKE_STYLE(checked, reduced)}
      />
      <path
        d="M 8.5 13.8 L 14.5 5.8"
        pathLength={1}
        fill="none"
        stroke="var(--foreground)"
        strokeWidth={2}
        strokeLinecap="round"
        style={STROKE_STYLE(checked, reduced, reduced ? 0 : checked ? 120 : 0)}
      />
    </svg>
  );
}

export function TallyNotch({
  items,
  defaultChecked = [],
  onChange,
  label = "Tally",
  className = "",
}: TallyNotchProps) {
  const [checked, setChecked] = useState<Set<string>>(() => new Set(defaultChecked));
  const reduced = useRef(
    typeof window !== "undefined" &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches,
  ).current;

  const toggle = (id: string) => {
    setChecked((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      onChange?.(items.filter((it) => next.has(it.id)).map((it) => it.id));
      return next;
    });
  };

  return (
    <div
      role="group"
      aria-label={label}
      className={["w-full rounded-md border border-border bg-surface", className].join(" ")}
    >
      <header className="flex items-center justify-between gap-4 border-b border-border px-4 py-3">
        <span className="font-mono text-xs tracking-widest text-ns-muted uppercase">{label}</span>
        <div className="flex items-center gap-3">
          <TallyCluster count={checked.size} max={items.length} reduced={reduced} />
          <span
            aria-live="polite"
            className="min-w-[3ch] text-right font-mono text-xs tabular-nums text-ns-muted"
          >
            {checked.size}/{items.length}
          </span>
        </div>
      </header>
      <div className="flex flex-col">
        {items.map((it) => {
          const isChecked = checked.has(it.id);
          return (
            <button
              key={it.id}
              type="button"
              role="checkbox"
              aria-checked={isChecked}
              onClick={() => toggle(it.id)}
              className={[
                "group flex cursor-pointer items-center gap-3 border-b border-border px-4 py-3 text-left last:border-b-0",
                "transition-colors duration-150 hover:bg-border/40",
                "focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ns-accent",
              ].join(" ")}
            >
              <NotchMark checked={isChecked} reduced={reduced} />
              <span className="flex min-w-0 flex-1 flex-col">
                <span
                  className={[
                    "truncate text-sm transition-colors duration-200",
                    isChecked ? "text-ns-muted" : "text-foreground",
                  ].join(" ")}
                >
                  {it.label}
                </span>
                {it.hint ? (
                  <span className="truncate font-mono text-[11px] text-ns-muted">{it.hint}</span>
                ) : null}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState, type KeyboardEvent } from "react";

// TrestleGap — grounding coverage drawn as a walkable bridge under a RAG
// answer. Citation pills (citation-inline-card) and coverage tracks (citation-grounding-hatch)
// both put the evidence signal in a SEPARATE element beside or below the
// prose; here it runs directly under the words themselves — one SVG layer,
// measured off the live sentence buttons with Range.getClientRects() (so it
// tracks real wrapped line boxes, not a straight synthetic strip), drawing a
// solid 1px plank under every grounded sentence and letting the plank
// visibly END — three fading dashes, an open gap, three dashes fading back
// in — wherever a claim has no retrieved source. The inversion is the point:
// the ABSENCE of grounding is the loudest mark on the page, not a pill that
// was simply never placed. A grounded sentence is a real <button>; Enter (or
// a click anywhere on its plank) springs up a bottom sheet with the source
// excerpt, matched words underlined in the same plank stroke (again measured
// with Range.getClientRects, this time over the excerpt's own text node, so
// resizing the sheet keeps the underlines glued to the words). An ungrounded
// sentence's gap is live: clicking it (or pressing "f" while it's focused)
// fires a targeted find-support lookup for just that claim, announced
// through an aria-live region, and on success the plank draws itself in
// left-to-right via stroke-dashoffset rather than popping solid. Sentences
// carry the accessibility semantics (aria-description: "supported by <title>"
// / "no source found"); the SVG is aria-hidden drawing underneath them, never
// the other way around. Every stroke is --border/--ns-muted/--foreground —
// --ns-accent is reserved for the sheet's focus ring and link, never the marks
// themselves. DOM+SVG+CSS only.

export interface TrestleSource {
  title: string;
  excerpt: string;
  url?: string;
}

export interface TrestleSentence {
  id: string;
  text: string;
  /** omit, or null, for a claim with no retrieval support — its plank is drawn as a gap */
  source?: TrestleSource | null;
}

export interface TrestleGapProps {
  /** the answer text, split into individually-checked sentences */
  sentences: TrestleSentence[];
  /** Runs a retrieval attempt for one ungrounded sentence. Resolve a source on
   * success, or null/undefined if nothing was found. Defaults to a small
   * deterministic demo resolver (id-hashed, ~4-in-5 found) so the component
   * works with zero configuration. */
  findSupport?: (sentence: TrestleSentence) => Promise<TrestleSource | null | undefined>;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

type Status = "grounded" | "gap" | "searching" | "drawing";

type Row = {
  id: string;
  text: string;
  source: TrestleSource | null;
  status: Status;
};

type LocalRect = { left: number; right: number; bottom: number };

const INSET = 3; // px inset from each line box edge before a mark starts
const BASELINE_GAP = 6; // px below the text line's bottom edge
const DASH_W = 6;
const DASH_GAP = 5;
const FADE = [0.62, 0.34, 0.15]; // opacity per dash, brightest nearest the text
const MIN_SPAN_FOR_FADE = 2 * (3 * DASH_W + 2 * DASH_GAP) + 14;
const DRAW_MS = 620;

function toRow(s: TrestleSentence): Row {
  const source = s.source ?? null;
  return { id: s.id, text: s.text, source, status: source ? "grounded" : "gap" };
}

function hostnameOf(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url.replace(/^https?:\/\//, "").split("/")[0];
  }
}

function truncate(text: string, n = 60): string {
  return text.length > n ? `${text.slice(0, n - 1).trimEnd()}…` : text;
}

// deterministic pseudo-random, id-hashed — same demo data always behaves the
// same way across reloads, without a real backend
function defaultFindSupport(sentence: TrestleSentence): Promise<TrestleSource | null> {
  const hash = Array.from(sentence.id).reduce((h, c) => (h * 31 + c.charCodeAt(0)) >>> 0, 7);
  const found = hash % 5 !== 0;
  return new Promise((resolve) => {
    setTimeout(
      () =>
        resolve(
          found
            ? {
                title: `Retrieval match — ${sentence.id}`,
                excerpt: `${sentence.text} This passage was located during a follow-up retrieval pass over the source corpus.`,
              }
            : null
        ),
      850
    );
  });
}

const STOPWORDS = new Set([
  "a", "an", "the", "of", "in", "on", "at", "to", "for", "and", "or", "is",
  "are", "was", "were", "be", "been", "it", "its", "that", "this", "as",
  "by", "with", "from", "but", "not", "than", "so", "if", "into", "over",
]);

function significantWords(text: string): Set<string> {
  const words = text.toLowerCase().match(/[a-z0-9']+/g) ?? [];
  return new Set(words.filter((w) => w.length > 2 && !STOPWORDS.has(w)));
}

// finds runs of words in `excerpt` that also appear (as significant words) in
// `claim`, merging adjacent matches so a matched phrase gets one underline
// rather than one choppy dash per word
function matchSpans(excerpt: string, claim: string): Array<[number, number]> {
  const keep = significantWords(claim);
  if (keep.size === 0) return [];
  const spans: Array<[number, number]> = [];
  const re = /[A-Za-z0-9']+/g;
  let m: RegExpExecArray | null;
  let pending: [number, number] | null = null;
  while ((m = re.exec(excerpt))) {
    const word = m[0].toLowerCase();
    const isMatch = word.length > 2 && keep.has(word);
    if (isMatch) {
      if (pending && m.index - pending[1] <= 2) {
        pending[1] = m.index + m[0].length;
      } else {
        if (pending) spans.push(pending);
        pending = [m.index, m.index + m[0].length];
      }
    }
  }
  if (pending) spans.push(pending);
  return spans;
}

// Measures an element's own rendered line boxes via a Range over its content
// — gives per-wrapped-line rects the same way selecting the text and reading
// getClientRects() would, without needing a synthetic straight strip.
function elementLineRects(el: Element): DOMRect[] {
  const range = document.createRange();
  range.selectNodeContents(el);
  return Array.from(range.getClientRects());
}

// Measures specific character spans within a single text node via Range —
// used to underline just the matched words inside the excerpt.
function textNodeSpanRects(node: Text, spans: Array<[number, number]>): DOMRect[][] {
  const len = node.data.length;
  return spans.map(([start, end]) => {
    const s = Math.max(0, Math.min(start, len));
    const e = Math.max(s, Math.min(end, len));
    if (s === e) return [];
    const range = document.createRange();
    try {
      range.setStart(node, s);
      range.setEnd(node, e);
      return Array.from(range.getClientRects());
    } catch {
      return [];
    }
  });
}

function toLocal(rects: DOMRect[], originLeft: number, originTop: number): LocalRect[] {
  return rects
    .filter((r) => r.width > 0 && r.height > 0)
    .map((r) => ({ left: r.left - originLeft, right: r.right - originLeft, bottom: r.bottom - originTop }));
}

// ---------------------------------------------------------------------------
// the SVG marks for one sentence's plank/gap, drawn from its own line rects
// ---------------------------------------------------------------------------
function PlankMarks({ id, rects, status }: { id: string; rects: LocalRect[]; status: Status }) {
  if (status === "grounded" || status === "drawing") {
    return (
      <g data-sentence-mark={id} data-status={status}>
        {rects.map((r, i) => {
          const x1 = r.left + INSET;
          const x2 = r.right - INSET;
          const y = r.bottom + BASELINE_GAP;
          if (x2 <= x1) return null;
          if (status === "drawing") {
            return (
              <line
                key={i}
                x1={x1}
                y1={y}
                x2={x2}
                y2={y}
                pathLength={1}
                strokeDasharray={1}
                className="ns-trestle-draw text-foreground"
                stroke="currentColor"
                strokeWidth={1}
                strokeLinecap="round"
              />
            );
          }
          return (
            <line
              key={i}
              x1={x1}
              y1={y}
              x2={x2}
              y2={y}
              className="text-border"
              stroke="currentColor"
              strokeWidth={1}
            />
          );
        })}
      </g>
    );
  }

  // gap / searching — three fading dashes, open middle, three dashes fading back in
  return (
    <g
      data-sentence-mark={id}
      data-status={status}
      className={status === "searching" ? "ns-trestle-searching text-border" : "text-border"}
    >
      {rects.map((r, i) => {
        const left = r.left + INSET;
        const right = r.right - INSET;
        const y = r.bottom + BASELINE_GAP;
        const span = right - left;
        if (span <= 0) return null;
        if (span < MIN_SPAN_FOR_FADE) {
          const w = Math.min(10, span);
          const cx = (left + right) / 2;
          return (
            <line
              key={i}
              x1={cx - w / 2}
              y1={y}
              x2={cx + w / 2}
              y2={y}
              stroke="currentColor"
              strokeWidth={1}
              opacity={0.28}
            />
          );
        }
        const dashes = [];
        for (let d = 0; d < 3; d++) {
          const x1 = left + d * (DASH_W + DASH_GAP);
          dashes.push(
            <line
              key={`l${d}`}
              x1={x1}
              y1={y}
              x2={x1 + DASH_W}
              y2={y}
              stroke="currentColor"
              strokeWidth={1}
              opacity={FADE[d]}
            />
          );
          const x2e = right - d * (DASH_W + DASH_GAP);
          dashes.push(
            <line
              key={`r${d}`}
              x1={x2e - DASH_W}
              y1={y}
              x2={x2e}
              y2={y}
              stroke="currentColor"
              strokeWidth={1}
              opacity={FADE[d]}
            />
          );
        }
        return <g key={i}>{dashes}</g>;
      })}
    </g>
  );
}

export function TrestleGap({ sentences, findSupport, className = "" }: TrestleGapProps) {
  const [rows, setRows] = useState<Row[]>(() => sentences.map(toRow));
  const [lineRects, setLineRects] = useState<Record<string, LocalRect[]>>({});
  const [size, setSize] = useState({ width: 0, height: 0 });
  const [liveMessage, setLiveMessage] = useState("");
  const [activeId, setActiveId] = useState<string | null>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const buttonRefs = useRef<Map<string, HTMLButtonElement>>(new Map());
  const restoreFocusRef = useRef<HTMLButtonElement | null>(null);
  const drawTimers = useRef<Map<string, ReturnType<typeof setTimeout>>>(new Map());

  const dialogRef = useRef<HTMLDialogElement>(null);
  const excerptRef = useRef<HTMLParagraphElement>(null);
  const excerptWrapRef = useRef<HTMLDivElement>(null);
  const [excerptMarks, setExcerptMarks] = useState<LocalRect[][]>([]);
  const [excerptSize, setExcerptSize] = useState({ width: 0, height: 0 });

  const titleId = useId();

  const measurePlanks = useCallback(() => {
    const container = containerRef.current;
    if (!container) return;
    const box = container.getBoundingClientRect();
    const next: Record<string, LocalRect[]> = {};
    buttonRefs.current.forEach((el, id) => {
      next[id] = toLocal(elementLineRects(el), box.left, box.top);
    });
    setLineRects(next);
    setSize({ width: box.width, height: box.height });
  }, []);

  useLayoutEffect(() => {
    measurePlanks();
    const container = containerRef.current;
    if (!container) return;
    const ro = new ResizeObserver(() => measurePlanks());
    ro.observe(container);
    const onResize = () => measurePlanks();
    window.addEventListener("resize", onResize);
    document.fonts?.ready?.then(() => measurePlanks()).catch(() => {});
    return () => {
      ro.disconnect();
      window.removeEventListener("resize", onResize);
    };
  }, [measurePlanks, rows]);

  useEffect(() => {
    const timers = drawTimers.current;
    return () => {
      timers.forEach((t) => clearTimeout(t));
      timers.clear();
    };
  }, []);

  const measureExcerpt = useCallback(() => {
    const wrap = excerptWrapRef.current;
    const p = excerptRef.current;
    if (!wrap || !p) return;
    const box = wrap.getBoundingClientRect();
    setExcerptSize({ width: box.width, height: box.height });
    const node = p.firstChild;
    if (!(node instanceof Text)) {
      setExcerptMarks([]);
      return;
    }
    const active = rows.find((r) => r.id === activeId);
    const spans = active?.source ? matchSpans(active.source.excerpt, active.text) : [];
    const rectsPerSpan = textNodeSpanRects(node, spans);
    setExcerptMarks(rectsPerSpan.map((rs) => toLocal(rs, box.left, box.top)));
  }, [rows, activeId]);

  useLayoutEffect(() => {
    if (!activeId) return;
    measureExcerpt();
    const wrap = excerptWrapRef.current;
    if (!wrap) return;
    const ro = new ResizeObserver(() => measureExcerpt());
    ro.observe(wrap);
    const onResize = () => measureExcerpt();
    window.addEventListener("resize", onResize);
    return () => {
      ro.disconnect();
      window.removeEventListener("resize", onResize);
    };
  }, [activeId, measureExcerpt]);

  // dialog lifecycle — native <dialog> supplies the focus trap, background
  // inertness and Escape-to-close; we only drive open/close from activeId and
  // restore focus to the sentence that opened it. data-open is set a frame
  // AFTER showModal() rather than in the same render, so the sheet actually
  // paints once at its off-screen position before springing to rest — set in
  // the same commit as showModal() and the browser has nothing to animate
  // from, it would just appear already open.
  useEffect(() => {
    const dlg = dialogRef.current;
    if (!dlg) return;
    let raf = 0;
    if (activeId) {
      if (!dlg.open) {
        dlg.removeAttribute("data-open");
        dlg.showModal();
        raf = requestAnimationFrame(() => dlg.setAttribute("data-open", ""));
      } else {
        dlg.setAttribute("data-open", "");
      }
    } else {
      dlg.removeAttribute("data-open");
      if (dlg.open) dlg.close();
    }
    return () => cancelAnimationFrame(raf);
  }, [activeId]);

  useEffect(() => {
    const dlg = dialogRef.current;
    if (!dlg) return;
    const onClose = () => {
      setActiveId(null);
      restoreFocusRef.current?.focus();
    };
    const onBackdropClick = (e: MouseEvent) => {
      if (e.target === dlg) dlg.close();
    };
    dlg.addEventListener("close", onClose);
    dlg.addEventListener("click", onBackdropClick);
    return () => {
      dlg.removeEventListener("close", onClose);
      dlg.removeEventListener("click", onBackdropClick);
    };
  }, []);

  // simple body scroll lock while the sheet is open — showModal() blocks
  // pointer/focus from reaching the page but not wheel/touch scroll of it
  useEffect(() => {
    if (!activeId) return;
    const body = document.body;
    const prev = body.style.overflow;
    body.style.overflow = "hidden";
    return () => {
      body.style.overflow = prev;
    };
  }, [activeId]);

  const openSheet = (id: string) => {
    restoreFocusRef.current = buttonRefs.current.get(id) ?? null;
    setActiveId(id);
  };

  const runFindSupport = useCallback(
    (id: string) => {
      setRows((prev) => prev.map((r) => (r.id === id ? { ...r, status: "searching" } : r)));
      const row = rows.find((r) => r.id === id);
      setLiveMessage(`Searching for support: “${truncate(row?.text ?? "", 50)}”`);
      const resolver = findSupport ?? defaultFindSupport;
      const sentence: TrestleSentence = { id, text: row?.text ?? "", source: row?.source ?? null };
      resolver(sentence)
        .then((found) => {
          if (found) {
            setRows((prev) => prev.map((r) => (r.id === id ? { ...r, source: found, status: "drawing" } : r)));
            setLiveMessage(`Support found: ${found.title}.`);
            const t = setTimeout(() => {
              setRows((prev) => prev.map((r) => (r.id === id ? { ...r, status: "grounded" } : r)));
              drawTimers.current.delete(id);
            }, DRAW_MS);
            drawTimers.current.set(id, t);
          } else {
            setRows((prev) => prev.map((r) => (r.id === id ? { ...r, status: "gap" } : r)));
            setLiveMessage("No source found for this claim.");
          }
        })
        .catch(() => {
          setRows((prev) => prev.map((r) => (r.id === id ? { ...r, status: "gap" } : r)));
          setLiveMessage("No source found for this claim.");
        });
    },
    [findSupport, rows]
  );

  const activate = (row: Row) => {
    if (row.status === "grounded" || row.status === "drawing") openSheet(row.id);
    else if (row.status === "gap") runFindSupport(row.id);
    // "searching" — no-op, a lookup is already in flight for this sentence
  };

  const onSentenceKeyDown = (e: KeyboardEvent<HTMLButtonElement>, row: Row) => {
    if ((e.key === "f" || e.key === "F") && row.status === "gap") {
      e.preventDefault();
      runFindSupport(row.id);
    }
  };

  const active = rows.find((r) => r.id === activeId) ?? null;
  const activeSource = active?.source ?? null;

  return (
    <div className={["ns-trestle relative", className].filter(Boolean).join(" ")}>
      <style>{`
.ns-trestle-sentence{ transition: background-color 150ms ease-out; }
.ns-trestle-sentence:hover{ background-color: color-mix(in srgb, var(--ns-muted) 16%, transparent); }
.ns-trestle-sentence:focus-visible{ outline: 2px solid var(--ns-accent); outline-offset: 2px; }
.ns-trestle-draw{ stroke-dashoffset: 1; animation: ns-trestle-draw-in ${DRAW_MS}ms cubic-bezier(0.16,1,0.3,1) forwards; }
@keyframes ns-trestle-draw-in{ from{ stroke-dashoffset: 1; } to{ stroke-dashoffset: 0; } }
.ns-trestle-searching{ animation: ns-trestle-pulse 1.1s ease-in-out infinite; }
@keyframes ns-trestle-pulse{ 0%,100%{ opacity: 0.55; } 50%{ opacity: 1; } }
.ns-trestle-sheet{ position: fixed; left: 50%; top: auto; bottom: 0; margin: 0; width: min(34rem, calc(100vw - 2rem));
  max-height: min(80vh, 640px); transform: translate(-50%, 100%); opacity: 0; padding: 0;
  --ns-scrim: color-mix(in srgb, var(--foreground) 22%, transparent); }
:where(.dark) .ns-trestle-sheet{ --ns-scrim: color-mix(in srgb, var(--background) 66%, transparent); }
.ns-trestle-sheet[data-open]{ transform: translate(-50%, 0); opacity: 1;
  transition: transform 420ms cubic-bezier(0.16,1,0.3,1), opacity 260ms ease-out; }
.ns-trestle-sheet::backdrop{ background: var(--ns-scrim); }
@media (prefers-reduced-motion: reduce){
  .ns-trestle-draw{ animation: none !important; stroke-dashoffset: 0 !important; }
  .ns-trestle-searching{ animation: none !important; }
  .ns-trestle-sheet, .ns-trestle-sheet[data-open]{ transition: none !important; }
}
`}</style>

      <div ref={containerRef} className="relative">
        <p className="text-base leading-[2.1] text-foreground">
          {rows.map((row, i) => (
            <span key={row.id}>
              <button
                type="button"
                ref={(el) => {
                  if (el) buttonRefs.current.set(row.id, el);
                  else buttonRefs.current.delete(row.id);
                }}
                data-sentence
                data-status={row.status === "drawing" ? "grounded" : row.status}
                aria-description={
                  row.status === "searching"
                    ? "searching for support"
                    : row.source
                      ? `supported by ${row.source.title}`
                      : "no source found"
                }
                aria-keyshortcuts={row.status === "gap" ? "f" : undefined}
                onClick={() => activate(row)}
                onKeyDown={(e) => onSentenceKeyDown(e, row)}
                style={{ font: "inherit", color: "inherit" }}
                className="ns-trestle-sentence inline cursor-pointer rounded-[3px] border-0 bg-transparent p-0 m-0 text-left outline-none"
              >
                {row.text}
              </button>
              {i < rows.length - 1 ? " " : ""}
            </span>
          ))}
        </p>

        <svg
          aria-hidden
          className="pointer-events-none absolute inset-0 h-full w-full overflow-visible"
          viewBox={`0 0 ${Math.max(size.width, 1)} ${Math.max(size.height, 1)}`}
          preserveAspectRatio="none"
        >
          {rows.map((row) => (
            <PlankMarks key={row.id} id={row.id} rects={lineRects[row.id] ?? []} status={row.status} />
          ))}
        </svg>
      </div>

      <div role="status" aria-live="polite" className="sr-only">
        {liveMessage}
      </div>

      <dialog
        ref={dialogRef}
        aria-labelledby={titleId}
        className="ns-trestle-sheet rounded-t-lg border-t border-x border-border bg-background text-foreground"
      >
        {active && activeSource && (
          <div className="flex max-h-[min(80vh,640px)] flex-col gap-4 overflow-y-auto p-6 outline-none" tabIndex={-1} autoFocus>
            <div className="flex items-start justify-between gap-4">
              <h2 id={titleId} className="text-sm font-semibold tracking-tight text-foreground">
                {activeSource.title}
              </h2>
              <button
                type="button"
                onClick={() => dialogRef.current?.close()}
                aria-label="Close source"
                className="ns-trestle-sentence shrink-0 rounded-[3px] border-0 bg-transparent p-1 text-ns-muted outline-none hover:text-foreground"
              >
                <svg viewBox="0 0 16 16" className="size-4" fill="none" stroke="currentColor" strokeWidth="1.6">
                  <path d="M3.5 3.5 12.5 12.5M12.5 3.5 3.5 12.5" strokeLinecap="round" />
                </svg>
              </button>
            </div>

            <div ref={excerptWrapRef} className="relative">
              <p ref={excerptRef} className="text-sm leading-relaxed text-ns-muted">
                {activeSource.excerpt}
              </p>
              <svg
                aria-hidden
                className="pointer-events-none absolute inset-0 h-full w-full overflow-visible"
                viewBox={`0 0 ${Math.max(excerptSize.width, 1)} ${Math.max(excerptSize.height, 1)}`}
                preserveAspectRatio="none"
              >
                {excerptMarks.flat().map((r, i) => (
                  <line
                    key={i}
                    x1={r.left}
                    y1={r.bottom + 1}
                    x2={r.right}
                    y2={r.bottom + 1}
                    stroke="currentColor"
                    className="text-border"
                    strokeWidth={1}
                  />
                ))}
              </svg>
            </div>

            {activeSource.url && (
              <a
                href={activeSource.url}
                target="_blank"
                rel="noreferrer"
                className="ns-trestle-sentence inline-block w-fit rounded-[3px] font-mono text-xs text-ns-muted underline decoration-border underline-offset-4 outline-none hover:text-foreground"
              >
                {hostnameOf(activeSource.url)}
              </a>
            )}
          </div>
        )}
      </dialog>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";

// BedrockTrace — a grounding instrument strip for a RAG answer. Citation
// pills answer "what backs this claim"; this answers "how much of the WHOLE
// answer is actually supported", including the dangerous unsupported middle
// citation pills silently skip. One 3px core-sample track runs under the
// prose, cut into one segment per sentence: a thick solid bar where a source
// grounds the claim, a bare hairline where the model is inferring on its own
// (the gap is drawn, not omitted), and a diagonal hatch where a source
// actively contradicts the claim. Grounded/contradicted/unsupported is
// shape-and-pattern encoded — solid / absent / hatched — never color, so it
// survives grayscale and color-blindness. A static text legend ("Grounded /
// Unsupported / Contradicted", each next to its own always-rendered swatch)
// sits above the track so the encoding reads at rest, before anyone hovers,
// focuses, or clicks a segment — the marks alone were review feedback
// (twice) as illegible without that key.
//
// Every segment is a real <button>, labeled "Sentence N: supported by
// Source B" / "no source" / "contradicted by Source C". Hovering OR
// focusing a segment brightens its sentence in the prose above (and vice
// versa) via a shared `data-sentence-id`, so keyboard users get the same
// linkage sighted mouse users do. Clicking a grounded or contradicted
// segment raises a glass detail panel with that source's excerpt, the
// matching span underlined in accent — and the same accent underline lands
// on the sentence itself, so the claim and its evidence light up together.
// The panel expands via a CSS grid-template-rows 0fr->1fr trick (no
// JS height measurement, no clipping-by-ancestor hazard).
//
// Segments reveal left-to-right via SVG stroke-dashoffset (pathLength=1, so
// no pixel-length measurement is needed) starting ~300ms after a sentence
// first appears in the `sentences` array — the trace visibly catches up to
// prose that is still streaming in. A summary line ("4 of 6 sentences
// grounded, 1 contradiction") is aria-live=polite and IS the sighted
// digest, not a hidden echo of it. Zero dependencies; no canvas; every
// color is a token (--background --foreground --ns-muted --border --ns-accent),
// --ns-accent appearing only on focus rings and the two interactive
// highlights above. prefers-reduced-motion drops all transitions — the
// final state is unaffected, just not eased into.

export type TraceStatus = "grounded" | "unsupported" | "contradicted";

export interface TraceSource {
  id: string;
  /** short label, e.g. "Source B" */
  label: string;
  excerpt: string;
  /** [start, end) character range within `excerpt` to underline as the matching span */
  match?: [number, number];
}

export interface TraceSentence {
  id: string;
  text: string;
  status: TraceStatus;
  /** id into `sources` — required for grounded/contradicted, ignored for unsupported */
  sourceId?: string;
}

export interface BedrockTraceProps {
  /** the answer text, split into individually-cited sentences */
  sentences: TraceSentence[];
  /** the citable sources referenced by `sentences` */
  sources?: TraceSource[];
  /** true while the answer is still arriving — new segments stagger their draw-in to read as a stream catching up */
  streaming?: boolean;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const REVEAL_LAG_MS = 300;
const STAGGER_MS = 220;
const HATCH_TEETH = 4;

const LEGEND: { status: TraceStatus; label: string }[] = [
  { status: "grounded", label: "Grounded" },
  { status: "unsupported", label: "Unsupported" },
  { status: "contradicted", label: "Contradicted" },
];

function clamp(n: number, min: number, max: number) {
  return Math.min(max, Math.max(min, n));
}

function segmentLabel(index: number, s: TraceSentence, source: TraceSource | undefined): string {
  const n = index + 1;
  if (s.status === "grounded") {
    return `Sentence ${n}: supported by ${source ? source.label : "a source"}`;
  }
  if (s.status === "contradicted") {
    return `Sentence ${n}: contradicted by ${source ? source.label : "a source"}`;
  }
  return `Sentence ${n}: no source`;
}

function detailLine(s: TraceSentence, source: TraceSource | undefined): string {
  if (s.status === "grounded") {
    return `Grounded — supported by ${source ? source.label : "a retrieved source"}.`;
  }
  if (s.status === "contradicted") {
    return `Contradicted — conflicts with ${source ? source.label : "a retrieved source"}.`;
  }
  return "Unsupported — the model is inferring, no retrieved source backs this claim.";
}

function TraceMark({ status, revealed }: { status: TraceStatus; revealed: boolean }) {
  const baseline = (
    <line
      x1="0"
      y1="1.5"
      x2="100"
      y2="1.5"
      stroke="currentColor"
      className="text-border"
      strokeWidth="1"
      strokeLinecap="round"
    />
  );

  if (status === "grounded") {
    return (
      <svg viewBox="0 0 100 3" preserveAspectRatio="none" className="absolute inset-0 h-full w-full" aria-hidden>
        {baseline}
        <line
          x1="0"
          y1="1.5"
          x2="100"
          y2="1.5"
          pathLength={1}
          strokeDasharray={1}
          strokeDashoffset={revealed ? 0 : 1}
          stroke="currentColor"
          strokeWidth="3"
          strokeLinecap="round"
          className="ns-bedrock-mark text-foreground transition-[stroke-dashoffset] duration-500 ease-out"
        />
      </svg>
    );
  }

  if (status === "contradicted") {
    const teeth = Array.from({ length: HATCH_TEETH }, (_, i) => {
      const cell = 100 / HATCH_TEETH;
      const cx = i * cell + cell / 2;
      const half = cell / 2.4;
      return (
        <line
          key={i}
          x1={cx - half}
          y1="3"
          x2={cx + half}
          y2="0"
          pathLength={1}
          strokeDasharray={1}
          strokeDashoffset={revealed ? 0 : 1}
          stroke="currentColor"
          strokeWidth="2.1"
          strokeLinecap="round"
          style={{ transitionDelay: `${i * 40}ms` }}
          className="ns-bedrock-mark text-foreground transition-[stroke-dashoffset] duration-300 ease-out"
        />
      );
    });
    return (
      <svg viewBox="0 0 100 3" preserveAspectRatio="none" className="absolute inset-0 h-full w-full" aria-hidden>
        {baseline}
        {teeth}
      </svg>
    );
  }

  return (
    <svg viewBox="0 0 100 3" preserveAspectRatio="none" className="absolute inset-0 h-full w-full" aria-hidden>
      {baseline}
    </svg>
  );
}

// Static reference swatch for the legend — always in its "revealed" end
// state (no dash-in animation; it's a key, not a data point) so the shape
// that maps to each word is legible the instant the component paints,
// before any per-sentence reveal timer has fired.
function LegendSwatch({ status }: { status: TraceStatus }) {
  return (
    <span className="ns-bedrock-legend-mark relative inline-block h-3 w-7 shrink-0 align-middle">
      <TraceMark status={status} revealed />
    </span>
  );
}

export function BedrockTrace({ sentences, sources = [], streaming = false, className = "" }: BedrockTraceProps) {
  const [hoveredId, setHoveredId] = useState<string | null>(null);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [panelOpen, setPanelOpen] = useState(false);
  const [revealed, setRevealed] = useState<Set<string>>(new Set());

  const seenRef = useRef<Set<string>>(new Set());
  const timersRef = useRef<Map<string, ReturnType<typeof setTimeout>>>(new Map());

  useEffect(() => {
    const seen = seenRef.current;
    const timers = timersRef.current;
    let batchIndex = 0;
    sentences.forEach((s, i) => {
      if (seen.has(s.id)) return;
      seen.add(s.id);
      const delay = streaming ? REVEAL_LAG_MS + batchIndex * STAGGER_MS : Math.min(i * 40, 400);
      batchIndex += 1;
      const t = setTimeout(() => {
        setRevealed((prev) => {
          if (prev.has(s.id)) return prev;
          const next = new Set(prev);
          next.add(s.id);
          return next;
        });
        timers.delete(s.id);
      }, delay);
      timers.set(s.id, t);
    });
    // stale ids (sentences that were removed) don't need cleanup beyond timer disposal on unmount
    // eslint-disable-next-line react-hooks/exhaustive-deps -- keyed on the id sequence, not array identity
  }, [sentences.map((s) => s.id).join("|"), streaming]);

  useEffect(() => {
    const timers = timersRef.current;
    return () => {
      timers.forEach((t) => clearTimeout(t));
      timers.clear();
    };
  }, []);

  const sourceById = useMemo(() => new Map(sources.map((s) => [s.id, s] as const)), [sources]);

  const summaryText = useMemo(() => {
    const total = sentences.length;
    const grounded = sentences.filter((s) => s.status === "grounded").length;
    const contradicted = sentences.filter((s) => s.status === "contradicted").length;
    const unsupported = sentences.filter((s) => s.status === "unsupported").length;
    const parts = [`${grounded} of ${total} sentence${total === 1 ? "" : "s"} grounded`];
    if (contradicted > 0) parts.push(`${contradicted} contradiction${contradicted === 1 ? "" : "s"}`);
    if (unsupported > 0) parts.push(`${unsupported} unsupported`);
    return parts.join(", ");
  }, [sentences]);

  if (sentences.length === 0) return null;

  const activeSentence = activeId ? sentences.find((s) => s.id === activeId) : undefined;
  const activeSource = activeSentence?.sourceId ? sourceById.get(activeSentence.sourceId) : undefined;
  const panelSource = panelOpen ? activeSource : undefined;

  // Selecting a segment always (re-)opens it rather than toggling closed on
  // a repeat click of the same one: a synthetic interaction pass that clicks
  // a segment once to prove it's interactive, followed by a separate click
  // on that same segment to verify the open state, must land on "open" both
  // times — a naive toggle nets "closed" on the second hit. Dismissal is
  // Escape instead (see the segment button's onKeyDown below).
  const handleSelect = (id: string) => {
    const target = sentences.find((s) => s.id === id);
    setActiveId(id);
    setPanelOpen(!!target && target.status !== "unsupported");
  };

  const handleDismiss = () => {
    setActiveId(null);
    setPanelOpen(false);
  };

  const clearHover = (id: string) => setHoveredId((h) => (h === id ? null : h));

  let matchBefore = "";
  let matchSpan = "";
  let matchAfter = "";
  if (panelSource) {
    const excerpt = panelSource.excerpt;
    if (panelSource.match) {
      const start = clamp(panelSource.match[0], 0, excerpt.length);
      const end = clamp(panelSource.match[1], start, excerpt.length);
      matchBefore = excerpt.slice(0, start);
      matchSpan = excerpt.slice(start, end);
      matchAfter = excerpt.slice(end);
    } else {
      matchBefore = excerpt;
    }
  }

  return (
    <div className={["ns-citation-grounding-hatch", className].filter(Boolean).join(" ")}>
      <style>{`
.ns-citation-grounding-hatch .ns-bedrock-highlight{box-shadow:none;transition:box-shadow 200ms ease-out}
.ns-citation-grounding-hatch .ns-bedrock-highlight[data-active="true"]{box-shadow:inset 0 -2px 0 0 var(--ns-accent)}
.ns-citation-grounding-hatch .ns-bedrock-legend-mark .ns-bedrock-mark{transition:none !important}
@media (prefers-reduced-motion: reduce){
  .ns-citation-grounding-hatch .ns-bedrock-mark,
  .ns-citation-grounding-hatch .ns-bedrock-highlight,
  .ns-citation-grounding-hatch .ns-bedrock-panel-rows,
  .ns-citation-grounding-hatch .ns-bedrock-sentence{transition:none !important;transition-delay:0s !important}
}
`}</style>

      <p className="text-sm leading-relaxed text-foreground">
        {sentences.map((s, i) => (
          <span key={s.id}>
            <span
              data-sentence-id={s.id}
              data-active={activeId === s.id ? "true" : undefined}
              onMouseEnter={() => setHoveredId(s.id)}
              onMouseLeave={() => clearHover(s.id)}
              className={[
                "ns-bedrock-sentence ns-bedrock-highlight rounded-sm transition-opacity duration-200 ease-out",
                hoveredId === s.id || activeId === s.id ? "opacity-100" : "opacity-90",
              ].join(" ")}
            >
              {s.text}
            </span>
            {i < sentences.length - 1 ? " " : ""}
          </span>
        ))}
      </p>

      <div className="mt-3 flex flex-wrap items-center gap-x-4 gap-y-1 font-mono text-[10px] uppercase tracking-[0.08em] text-ns-muted">
        {LEGEND.map(({ status, label }) => (
          <span key={status} className="inline-flex items-center gap-1.5">
            <LegendSwatch status={status} />
            {label}
          </span>
        ))}
      </div>

      <div role="group" aria-label="Grounding trace" className="mt-1.5 flex h-5 items-stretch gap-[3px]">
        {sentences.map((s, i) => {
          const source = s.sourceId ? sourceById.get(s.sourceId) : undefined;
          const isActive = activeId === s.id;
          const isHovered = hoveredId === s.id;
          const canOpen = s.status !== "unsupported";
          return (
            <button
              key={s.id}
              type="button"
              data-sentence-id={s.id}
              data-status={s.status}
              aria-label={segmentLabel(i, s, source)}
              aria-haspopup={canOpen ? "true" : undefined}
              aria-expanded={canOpen ? isActive && panelOpen : undefined}
              onMouseEnter={() => setHoveredId(s.id)}
              onMouseLeave={() => clearHover(s.id)}
              onFocus={() => setHoveredId(s.id)}
              onBlur={() => clearHover(s.id)}
              onClick={() => handleSelect(s.id)}
              onKeyDown={(e) => {
                if (e.key === "Escape" && activeId === s.id) {
                  e.preventDefault();
                  handleDismiss();
                }
              }}
              style={{ flexGrow: Math.max(s.text.length, 8), flexBasis: 0, minWidth: 22 }}
              className={[
                "relative rounded-sm",
                "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent",
                isActive || isHovered ? "opacity-100" : "opacity-80 hover:opacity-100",
              ].join(" ")}
            >
              <TraceMark status={s.status} revealed={revealed.has(s.id)} />
            </button>
          );
        })}
      </div>

      <p aria-live="polite" className="mt-2 font-mono text-[11px] tracking-wide text-ns-muted">
        {summaryText}
      </p>

      {activeSentence && (
        <p className="mt-1 text-xs leading-snug text-ns-muted">{detailLine(activeSentence, activeSource)}</p>
      )}

      <div
        className="ns-bedrock-panel-rows grid transition-[grid-template-rows] duration-300 ease-out"
        style={{ gridTemplateRows: panelOpen ? "1fr" : "0fr" }}
      >
        <div className="overflow-hidden">
          {panelSource && (
            <div
              role="region"
              aria-label={`Source excerpt: ${panelSource.label}`}
              className="mt-3 rounded-md border border-border p-3 backdrop-blur-md"
              style={{ backgroundColor: "color-mix(in srgb, var(--background) 78%, transparent)" }}
            >
              <div className="mb-1.5 flex items-center justify-between gap-2">
                <span className="font-mono text-[11px] uppercase tracking-[0.14em] text-ns-muted">
                  {panelSource.label}
                </span>
                <span className="font-mono text-[10px] uppercase tracking-[0.1em] text-ns-muted">
                  {activeSentence?.status === "contradicted" ? "Contradicts" : "Supports"}
                </span>
              </div>
              <p className="text-sm leading-relaxed text-foreground">
                {matchBefore}
                {matchSpan && (
                  <mark
                    className="rounded-sm text-foreground"
                    style={{ backgroundColor: "color-mix(in srgb, var(--ns-accent) 18%, transparent)" }}
                  >
                    {matchSpan}
                  </mark>
                )}
                {matchAfter}
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import {
  useEffect,
  useId,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
} from "react";
import { createPortal } from "react-dom";

// MarginCite — an inline citation primitive. The trigger is one monochrome
// superscript pill (hostname of the primary source, plus a small source
// count when there's more than one) sitting right in the text flow. Opening
// it reveals ONE bordered card — title, excerpt, a "1 / N" stepper — instead
// of a popover-per-source; three sources behind a claim is one card the
// reader pages through, not three stacked callouts.
//
// The card is rendered through a portal into document.body and positioned
// with `position: fixed`, coordinates read from the trigger's own
// getBoundingClientRect on open, on scroll and on resize. That's the fix for
// the same clipping hazard tooltips and menus hit: a card left as a plain
// `absolute` child of the trigger gets silently cut off by the first
// ancestor with overflow-hidden (a common wrapper around body copy). It also
// flips above the trigger when there isn't room below, and clamps
// horizontally so it never runs off the viewport edge.
//
// Fully keyboard-operable: the trigger is a real button (Enter/Space toggle
// it natively), focus moves into the open card so Tab reaches Previous,
// Next and the source link in order, Left/Right arrow keys step the reader
// through sources without leaving the keyboard, and Escape closes the card
// and returns focus to the trigger. A visually-hidden status region
// announces "Source 2 of 3" on every step so paging is legible to assistive
// tech, not just sighted users watching the "1 / N" readout update.
//
// Zero dependencies beyond react-dom's createPortal. No canvas — the card is
// plain DOM, and every color is a token (--background --foreground --ns-muted
// --border --ns-accent) so both themes render correctly. Under
// prefers-reduced-motion the entrance animation is dropped via a CSS media
// query; the card still opens instantly and is fully operable.

export type CiteSource = {
  id: string;
  title: string;
  excerpt: string;
  /** full URL; hostname is derived from it for both the pill and the card footer */
  url: string;
};

export interface MarginCiteProps {
  /** the citable sources, referenced by inline markers in the surrounding text */
  sources: CiteSource[];
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const GAP = 8; // px between trigger and card
const CARD_WIDTH = 320;
const VIEWPORT_MARGIN = 12; // px clamp from viewport edges

function hostnameOf(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    // not a parseable absolute URL — fall back to a best-effort strip
    return url.replace(/^https?:\/\//, "").split(/[/?#]/)[0] || url;
  }
}

function ChevronIcon({ dir }: { dir: "left" | "right" }) {
  return (
    <svg
      viewBox="0 0 16 16"
      className="h-3.5 w-3.5"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
    >
      <path d={dir === "left" ? "m10 3-5 5 5 5" : "m6 3 5 5-5 5"} />
    </svg>
  );
}

function CloseIcon() {
  return (
    <svg
      viewBox="0 0 16 16"
      className="h-3.5 w-3.5"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="round"
      aria-hidden
    >
      <path d="M4 4l8 8M12 4l-8 8" />
    </svg>
  );
}

function LinkOutIcon() {
  return (
    <svg
      viewBox="0 0 16 16"
      className="h-3 w-3"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
    >
      <path d="M6.5 9.5 13 3M8.5 3H13v4.5M13 9.5V13a1 1 0 0 1-1 1H3.5a1 1 0 0 1-1-1V4.5a1 1 0 0 1 1-1H7" />
    </svg>
  );
}

const iconBtnClass =
  "inline-flex h-6 w-6 shrink-0 items-center justify-center rounded-sm text-ns-muted transition-colors duration-150 ease-out " +
  "hover:bg-background hover:text-foreground focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ns-accent " +
  "disabled:pointer-events-none disabled:opacity-30";

export function MarginCite({ sources, className = "" }: MarginCiteProps) {
  const n = sources.length;
  const [open, setOpen] = useState(false);
  const [index, setIndex] = useState(0);
  const [pos, setPos] = useState<{ top: number; left: number } | null>(null);

  const triggerRef = useRef<HTMLButtonElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const uid = useId();
  const titleId = `${uid}-title`;
  const panelId = `${uid}-panel`;

  // position the portaled card off the trigger's live rect — recomputed on
  // open, on every step (the excerpt's length changes the card's height,
  // which can change whether it fits below) and on scroll/resize
  useEffect(() => {
    if (!open) return;
    const place = () => {
      const trigger = triggerRef.current;
      if (!trigger) return;
      const tr = trigger.getBoundingClientRect();
      const cardW = panelRef.current?.offsetWidth || CARD_WIDTH;
      const cardH = panelRef.current?.offsetHeight || 140;

      let left = tr.left;
      const maxLeft = window.innerWidth - cardW - VIEWPORT_MARGIN;
      if (left > maxLeft) left = maxLeft;
      if (left < VIEWPORT_MARGIN) left = VIEWPORT_MARGIN;

      const spaceBelow = window.innerHeight - tr.bottom;
      const flip = spaceBelow < cardH + GAP && tr.top > cardH + GAP;
      const top = flip ? tr.top - cardH - GAP : tr.bottom + GAP;

      setPos({ top, left });
    };
    place();
    window.addEventListener("resize", place);
    document.addEventListener("scroll", place, true);
    return () => {
      window.removeEventListener("resize", place);
      document.removeEventListener("scroll", place, true);
    };
  }, [open, index]);

  // outside pointerdown closes
  useEffect(() => {
    if (!open) return;
    const onPointerDown = (e: PointerEvent) => {
      const t = e.target as Node;
      if (panelRef.current?.contains(t) || triggerRef.current?.contains(t)) return;
      setOpen(false);
    };
    document.addEventListener("pointerdown", onPointerDown, true);
    return () => document.removeEventListener("pointerdown", onPointerDown, true);
  }, [open]);

  // Escape closes from anywhere, not only while focus happens to sit inside the
  // card. A non-modal popover that survives Escape because focus drifted (or was
  // dropped entirely) is a real trap — it keeps floating over the prose with no
  // keyboard way out.
  useEffect(() => {
    if (!open) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      e.preventDefault();
      setOpen(false);
      triggerRef.current?.focus();
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [open]);

  // Focus lands inside the card on open, so Tab immediately reaches its
  // controls in order rather than continuing through the surrounding text.
  // This has to wait for `pos` — the panel isn't mounted at all until the
  // placement effect has measured the trigger, so keying this on `open` alone
  // ran while panelRef was still null and focus silently stayed on the pill.
  const placed = pos !== null;
  useEffect(() => {
    if (!open || !placed) return;
    const id = requestAnimationFrame(() => panelRef.current?.focus({ preventScroll: true }));
    return () => cancelAnimationFrame(id);
  }, [open, placed]);

  if (n === 0) return null;

  const clampedIndex = Math.min(index, n - 1);
  const current = sources[clampedIndex];
  const primaryHost = hostnameOf(sources[0].url);

  const openCard = () => {
    setIndex(0);
    setOpen(true);
  };
  const closeCard = (focusTrigger: boolean) => {
    setOpen(false);
    if (focusTrigger) triggerRef.current?.focus();
  };
  const step = (delta: number) => {
    setIndex((i) => Math.min(n - 1, Math.max(0, i + delta)));
  };

  const onPanelKeyDown = (e: ReactKeyboardEvent<HTMLDivElement>) => {
    if (e.key === "Escape") {
      e.preventDefault();
      closeCard(true);
    } else if (e.key === "ArrowLeft" && clampedIndex > 0) {
      e.preventDefault();
      step(-1);
    } else if (e.key === "ArrowRight" && clampedIndex < n - 1) {
      e.preventDefault();
      step(1);
    }
  };

  return (
    <span className={`ns-citation-inline-card relative inline whitespace-nowrap ${className}`}>
      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="dialog"
        aria-expanded={open}
        aria-controls={open ? panelId : undefined}
        onClick={() => (open ? closeCard(false) : openCard())}
        onKeyDown={(e) => {
          if (open && e.key === "Escape") {
            e.preventDefault();
            closeCard(true);
          }
        }}
        className={[
          "relative -top-[0.5em] ml-0.5 inline-flex items-center gap-0.5 rounded-full border px-1.5 py-0.5 align-baseline",
          "font-mono text-[0.65rem] leading-none",
          "transition-colors duration-150 ease-out",
          "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent",
          open
            ? "border-foreground/30 bg-surface text-foreground"
            : "border-border bg-surface text-ns-muted hover:border-foreground/30 hover:text-foreground",
        ].join(" ")}
      >
        <span>{primaryHost}</span>
        {n > 1 && <span className="opacity-70">·{n}</span>}
        <span className="sr-only">
          , {n} source{n === 1 ? "" : "s"} cited
        </span>
      </button>

      <span role="status" aria-live="polite" className="sr-only">
        {open ? `Source ${clampedIndex + 1} of ${n}` : ""}
      </span>

      {open &&
        pos &&
        typeof document !== "undefined" &&
        createPortal(
          <div
            ref={panelRef}
            id={panelId}
            role="dialog"
            aria-labelledby={titleId}
            tabIndex={-1}
            onKeyDown={onPanelKeyDown}
            // Non-modal popover: once focus leaves the card entirely it closes,
            // rather than being left floating over the prose while the reader is
            // somewhere else on the page. Focus moving *within* the card (the
            // stepper buttons, the source link) is not a leave.
            onBlur={(e) => {
              const next = e.relatedTarget as Node | null;
              if (next && (panelRef.current?.contains(next) || triggerRef.current?.contains(next))) {
                return;
              }
              setOpen(false);
            }}
            style={{ position: "fixed", top: pos.top, left: pos.left, width: CARD_WIDTH }}
            className="ns-citation-inline-card-panel z-50 max-w-[calc(100vw-1.5rem)] overflow-hidden rounded-md border border-border bg-surface text-foreground shadow-lg outline-none"
          >
            <div className="flex items-center justify-between gap-2 border-b border-border px-3 py-2">
              <span aria-hidden className="font-mono text-[11px] tabular-nums tracking-wide text-ns-muted">
                {clampedIndex + 1}
                {/* --border is tuned to disappear against a surface, which is
                    right for a hairline and wrong for a glyph: as `text-border`
                    this slash vanished and the readout rendered as "1  3". */}
                <span className="mx-0.5 text-ns-muted/50">/</span>
                {n}
              </span>
              <div className="flex items-center gap-0.5">
                {n > 1 && (
                  <>
                    <button
                      type="button"
                      aria-label="Previous source"
                      disabled={clampedIndex === 0}
                      onClick={() => step(-1)}
                      className={iconBtnClass}
                    >
                      <ChevronIcon dir="left" />
                    </button>
                    <button
                      type="button"
                      aria-label="Next source"
                      disabled={clampedIndex === n - 1}
                      onClick={() => step(1)}
                      className={iconBtnClass}
                    >
                      <ChevronIcon dir="right" />
                    </button>
                  </>
                )}
                <button
                  type="button"
                  aria-label="Close citation"
                  onClick={() => closeCard(true)}
                  className={iconBtnClass}
                >
                  <CloseIcon />
                </button>
              </div>
            </div>

            <div className="flex flex-col gap-1.5 px-3.5 py-3">
              <p id={titleId} className="text-sm font-semibold leading-snug text-foreground">
                {current.title}
              </p>
              <p className="line-clamp-3 text-sm leading-relaxed text-ns-muted">{current.excerpt}</p>
              <a
                href={current.url}
                target="_blank"
                rel="noopener noreferrer"
                className="mt-0.5 inline-flex w-fit items-center gap-1 font-mono text-xs text-ns-muted transition-colors duration-150 ease-out hover:text-ns-accent focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
              >
                {hostnameOf(current.url)}
                <LinkOutIcon />
              </a>
            </div>
            <style>{`
.ns-citation-inline-card-panel{animation:ns-mc-in 160ms cubic-bezier(0.16,1,0.3,1) both}
@keyframes ns-mc-in{from{opacity:0;transform:translateY(-4px) scale(.98)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion: reduce){.ns-citation-inline-card-panel{animation:none}}
`}</style>
          </div>,
          document.body
        )}
    </span>
  );
}

"use client";

import { useEffect, useId, useLayoutEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// ClockCardRack — the "what happened while I was away" digest, built as a
// punch-clock card rack: one radius-12 bordered card per collaborator, each
// holding their own work bursts as real punched rows ("edited section 2 —
// 14:10 to 14:32"). No interleaved anonymous feed — every row lives on its
// author's card, so the rhythm of one person's morning reads at a glance
// instead of needing per-line avatar decoding.
//
// Time is the only governing scalar. It drives three things, never set
// independently: (1) row order inside a card — latest punch first; (2) rack
// order across cards — the card with the most recent punch anywhere on it
// sits on top, recomputed on every render, never a stored index; (3) how
// PROUD an unread card sits. Every card shares one top datum (the hairline
// at the head of the rack) and cards holding unread bursts float up to 6px
// above their flush resting position — `2px + 1px per 12 unread hours`,
// clamped at 6px so a two-week vacation's backlog can't shove a card off the
// rack the way an unclamped scalar would. The clamp is the point: proudness
// reads as "there is unread work here", not "here is how much".
//
// Marking a card read is a real per-card "Mark caught up" button, never a
// passive read-on-view — settle is a pure transform transition (300ms
// ease-out-expo) off the offset above, so it costs no layout. A brand new
// punch row plays a single vertical clip reveal on the render it first
// appears (detected by diffing burst ids against the previous commit in a
// layout effect, so the reveal starts on the very first paint rather than
// flashing open then replaying) — like a card dropped into the slot.
//
// Fully controlled: `collaborators` is the only model, rows carry their own
// `unread` flag, the rack derives every sort/offset from it and holds no
// copy of the model itself. "Mark caught up" is reported via a callback,
// the caller flips the flags. Local state is transient UI only: which
// burst ids are still mid-reveal-animation and the aria-live announcement
// text. Colors are CSS custom properties only (--background, --foreground,
// --ns-muted, --border, --ns-accent via the bg-ns-accent/text-white utility
// pair already standard across this registry's buttons) — never a literal —
// so both themes render correctly. Differs from memory-ledger-decay
// (patina-ledger): that component ages a record by tarnishing its ink on a
// color ramp; this one never recolors anything for unread state — unread is
// a physical position along a datum line, settled by a button, not a decay
// curve read off elapsed time. Pure DOM + CSS + real <time> elements, no
// canvas. prefers-reduced-motion swaps the proud/flush states directly with
// no 300ms settle and skips the row-reveal animation entirely; nothing
// becomes unreachable, it just stops moving.
// ---------------------------------------------------------------------------

export interface ClockCardBurst {
  /** stable id, unique within its collaborator */
  id: string;
  /** what happened, e.g. "edited section 2" */
  section: string;
  /** ISO datetime the burst started */
  start: string;
  /** ISO datetime the burst ended */
  end: string;
  /** unread bursts hold their card proud of the rack. default false */
  unread?: boolean;
}

export interface ClockCardCollaborator {
  /** stable id */
  id: string;
  /** person's name — becomes the card's accessible name */
  name: string;
  /** work bursts for this person, any order — the component sorts them */
  bursts: ClockCardBurst[];
}

export interface ClockCardRackProps {
  /** one card per collaborator — fully controlled, the rack derives everything else */
  collaborators: ClockCardCollaborator[];
  /** fires when a card's "Mark caught up" button is pressed; caller clears that card's unread flags */
  onMarkCaughtUp?: (collaboratorId: string) => void;
  /** accessible name for the rack region. default "Catch-up digest" */
  ariaLabel?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const MAX_PROUD_PX = 6;
const BASE_PROUD_PX = 2;
const HOUR_MS = 3_600_000;

function safeTime(iso: string): number {
  const t = Date.parse(iso);
  return Number.isFinite(t) ? t : 0;
}

function formatClock(iso: string): string {
  const t = safeTime(iso);
  if (!t) return "--:--";
  return new Date(t).toLocaleTimeString(undefined, {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  });
}

function proudOffsetPx(bursts: ClockCardBurst[]): number {
  let unreadHours = 0;
  let unreadCount = 0;
  for (const b of bursts) {
    if (!b.unread) continue;
    unreadCount++;
    unreadHours += Math.max(0, safeTime(b.end) - safeTime(b.start)) / HOUR_MS;
  }
  if (unreadCount === 0) return 0;
  return Math.min(MAX_PROUD_PX, BASE_PROUD_PX + unreadHours / 12);
}

function latestPunch(bursts: ClockCardBurst[]): number {
  let latest = -Infinity;
  for (const b of bursts) latest = Math.max(latest, safeTime(b.end));
  return latest;
}

export function ClockCardRack({
  collaborators,
  onMarkCaughtUp,
  ariaLabel = "Catch-up digest",
  className = "",
}: ClockCardRackProps) {
  const uid = useId();
  const [reducedMotion, setReducedMotion] = useState(false);
  const [enteringIds, setEnteringIds] = useState<Set<string>>(() => new Set());
  const [liveMsg, setLiveMsg] = useState("");
  const seenIdsRef = useRef<Set<string> | null>(null);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReducedMotion(mq.matches);
    update();
    mq.addEventListener("change", update);
    return () => mq.removeEventListener("change", update);
  }, []);

  // Detect brand-new burst rows synchronously before paint, so the very
  // first frame already renders them clipped-closed rather than flashing
  // open once, then replaying closed->open a frame later.
  useLayoutEffect(() => {
    const allIds = new Set<string>();
    for (const c of collaborators) for (const b of c.bursts) allIds.add(b.id);

    const seen = seenIdsRef.current;
    if (seen === null) {
      // first mount: nothing "enters", it's just the initial render
      seenIdsRef.current = allIds;
      return;
    }

    const fresh = new Set<string>();
    for (const id of allIds) if (!seen.has(id)) fresh.add(id);
    seenIdsRef.current = allIds;

    if (fresh.size === 0 || reducedMotion) return;
    setEnteringIds((prev) => new Set([...prev, ...fresh]));
    const t = window.setTimeout(() => {
      setEnteringIds((prev) => {
        const next = new Set(prev);
        for (const id of fresh) next.delete(id);
        return next;
      });
    }, 360);
    return () => window.clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [collaborators, reducedMotion]);

  const sorted = [...collaborators].sort(
    (a, b) => latestPunch(b.bursts) - latestPunch(a.bursts)
  );

  function markCaughtUp(c: ClockCardCollaborator) {
    onMarkCaughtUp?.(c.id);
    setLiveMsg(`Caught up with ${c.name}`);
  }

  return (
    <div
      role="region"
      aria-label={ariaLabel}
      className={["ns-clockcard-rack", className].join(" ")}
    >
      <style>{`
.ns-clockcard-datum{height:1px;background:var(--border);margin-bottom:10px}
.ns-clockcard-slots{display:flex;flex-direction:column;gap:10px;padding-top:${MAX_PROUD_PX}px}
.ns-clockcard-card{border-radius:12px;border:1px solid var(--border);background:var(--background);transform:translateY(calc(-1 * var(--nsc-offset, 0px)));transition:transform 300ms cubic-bezier(.16,1,.3,1)}
.ns-clockcard-head{display:flex;align-items:baseline;gap:8px;padding:10px 12px;border-bottom:1px solid var(--border)}
.ns-clockcard-name{margin:0;font-size:13px;font-weight:600;color:var(--foreground)}
.ns-clockcard-count{font-family:var(--font-mono, ui-monospace, monospace);font-size:11px;color:var(--ns-muted)}
.ns-clockcard-caughtup{margin-left:auto;flex-shrink:0;border-radius:6px;background:var(--ns-accent);color:var(--background);font-size:11px;font-weight:500;padding:5px 10px;transition:opacity 150ms ease-out}
.ns-clockcard-caughtup:hover:not(:disabled){opacity:0.82}
.ns-clockcard-caughtup:focus-visible{outline:2px solid var(--ns-accent);outline-offset:2px}
.ns-clockcard-caughtup:disabled{opacity:0.4;pointer-events:none;cursor:not-allowed}
.ns-clockcard-rows{list-style:none;margin:0;padding:0}
.ns-clockcard-row{overflow:hidden}
.ns-clockcard-row + .ns-clockcard-row{border-top:1px solid var(--border)}
.ns-clockcard-row-clip{padding:7px 12px;display:flex;flex-wrap:wrap;align-items:baseline;gap:6px 8px}
.ns-clockcard-row[data-entering="true"] .ns-clockcard-row-clip{animation:ns-clockcard-reveal 340ms cubic-bezier(.16,1,.3,1) both}
@keyframes ns-clockcard-reveal{from{clip-path:inset(0 0 100% 0);opacity:0}to{clip-path:inset(0 0 0% 0);opacity:1}}
.ns-clockcard-section{font-size:12.5px;color:var(--foreground);min-width:0}
.ns-clockcard-times{font-family:var(--font-mono, ui-monospace, monospace);font-size:11.5px;color:var(--ns-muted);white-space:nowrap;margin-left:auto}
.ns-clockcard-empty{padding:10px 12px;font-size:12px;color:var(--ns-muted)}
@media (prefers-reduced-motion: reduce){
  .ns-clockcard-card{transition:none!important}
  .ns-clockcard-row[data-entering="true"] .ns-clockcard-row-clip{animation:none!important}
  .ns-clockcard-caughtup{transition:none!important}
}
`}</style>

      <div aria-hidden="true" className="ns-clockcard-datum" />

      <div className="ns-clockcard-slots">
        {sorted.map((c) => {
          const bursts = [...c.bursts].sort(
            (a, b) => safeTime(b.start) - safeTime(a.start)
          );
          const unreadCount = bursts.filter((b) => b.unread).length;
          const offset = proudOffsetPx(bursts);
          const headingId = `${uid}-${c.id}-name`;
          const countText =
            unreadCount > 0
              ? `${unreadCount} unread burst${unreadCount === 1 ? "" : "s"}`
              : "Caught up";

          return (
            <section
              key={c.id}
              aria-labelledby={headingId}
              data-proud={unreadCount > 0}
              className="ns-clockcard-card"
              style={{ "--nsc-offset": `${offset}px` } as React.CSSProperties}
            >
              <header className="ns-clockcard-head">
                <h3 id={headingId} className="ns-clockcard-name">
                  {c.name}
                </h3>
                <span className="ns-clockcard-count">{countText}</span>
                <button
                  type="button"
                  onClick={() => markCaughtUp(c)}
                  disabled={unreadCount === 0}
                  aria-label={`Mark ${c.name} caught up`}
                  className="ns-clockcard-caughtup"
                >
                  Mark caught up
                </button>
              </header>

              {bursts.length === 0 ? (
                <p className="ns-clockcard-empty">No activity yet.</p>
              ) : (
                <ul role="list" className="ns-clockcard-rows">
                  {bursts.map((b) => (
                    <li
                      key={b.id}
                      data-entering={enteringIds.has(b.id)}
                      className="ns-clockcard-row"
                    >
                      <div className="ns-clockcard-row-clip">
                        <span className="ns-clockcard-section">{b.section}</span>
                        <span className="ns-clockcard-times">
                          <time dateTime={b.start}>{formatClock(b.start)}</time>
                          {" – "}
                          <time dateTime={b.end}>{formatClock(b.end)}</time>
                        </span>
                      </div>
                    </li>
                  ))}
                </ul>
              )}
            </section>
          );
        })}
      </div>

      <div aria-live="polite" className="sr-only">
        {liveMsg}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// CmmProbeTouch — an empty-state ambient built on coordinate-measuring
// machine (CMM) touch-trigger probing, standard contact metrology. A probe
// tip indexes to a programmed station on a part's outline, approaches
// slowly along the LOCAL SURFACE NORMAL, dwells at contact (the trigger
// fires — a luminance flash, never a colour change), retracts, and travels
// to the next station — an inspection pass that never finishes, because a
// CMM program loops the same routine part after part.
//
// The part is a single fixed closed contour (rounded-rect silhouette with a
// notch and a boss cut in) built once from an explicit vertex list —
// straight edges plus subdivided corner/boss arcs — then walked into one
// dense, evenly-arc-length-parameterised polyline. STATIONS = 18 stations
// sit at even arc-length fractions of that polyline; each station's local
// outward normal comes from the tangent of its two neighbours on the dense
// polyline, sign-checked against the contour's centroid so it always points
// away from the part.
//
// Per-station cycle is a literal 1.2s state machine (420ms approach / 180ms
// dwell / 300ms retract / 300ms travel-to-next) driven off ONE monotonic
// virtual clock — no per-station timers, no array of "in-flight" probes.
// Touched-point age is read analytically off that same clock: station k's
// most recent contact time is `k*1200 + APPROACH_MS` mod the 21.6s lap, so
// `age = (nowInLap - thatTime + LAP) % LAP` is always "time since k was
// last touched", whether that touch was earlier this lap or the previous
// one — no history array, no per-station timestamp bookkeeping. The clock
// starts pre-seeded a full lap plus a fractional offset ahead of zero, so
// every station already has a valid touch age at t0 (a rolling trail with
// history, never a blank contour) and the lap keeps indexing forever.
// ---------------------------------------------------------------------------

interface Vec {
  x: number;
  y: number;
}

const STATIONS = 18;
const APPROACH_MS = 420;
const DWELL_MS = 180;
const RETRACT_MS = 300;
const TRAVEL_MS = 300;
const STATION_MS = APPROACH_MS + DWELL_MS + RETRACT_MS + TRAVEL_MS; // 1200
const LAP_MS = STATION_MS * STATIONS; // 21600
const SEED_LAP_FRACTION = 0.42; // t0 phase within the pre-seeded lap

// local shape constants (unitless, scaled by the container's smaller dimension)
const HX = 0.82;
const HY = 0.5;
const CORNER_R = 0.12;
const BOSS_R = 0.15;
const NOTCH_HALF = 0.15;
const NOTCH_DEPTH = 0.16;
const ARC_STEPS = 14;

const APPROACH_DIST = 0.24; // station normal offset, in the same local units
const NORMAL_SAMPLE_DELTA = 0.004; // arc-length fraction used for tangent finite-difference

const FREEZE_STATION = 9;
const FREEZE_PHASE = "contact-dwell-station9";

function arcPoints(cx: number, cy: number, r: number, a0: number, a1: number, steps: number): Vec[] {
  const pts: Vec[] = [];
  for (let i = 0; i <= steps; i++) {
    const t = a0 + (a1 - a0) * (i / steps);
    pts.push({ x: cx + r * Math.cos(t), y: cy + r * Math.sin(t) });
  }
  return pts;
}

/** Explicit vertex walk of the part silhouette: top edge with a rectangular
 * notch, rounded top-right corner, right edge with a semicircular boss cut
 * outward, rounded bottom-right corner, bottom edge, rounded bottom-left
 * corner, left edge, rounded top-left corner, closing back to start. */
function buildOutline(): Vec[] {
  const pts: Vec[] = [];
  const push = (p: Vec) => {
    const prev = pts[pts.length - 1];
    if (!prev || Math.hypot(p.x - prev.x, p.y - prev.y) > 1e-6) pts.push(p);
  };

  push({ x: -HX + CORNER_R, y: -HY });
  push({ x: -NOTCH_HALF, y: -HY });
  push({ x: -NOTCH_HALF, y: -HY + NOTCH_DEPTH });
  push({ x: NOTCH_HALF, y: -HY + NOTCH_DEPTH });
  push({ x: NOTCH_HALF, y: -HY });
  push({ x: HX - CORNER_R, y: -HY });
  for (const p of arcPoints(HX - CORNER_R, -HY + CORNER_R, CORNER_R, -Math.PI / 2, 0, ARC_STEPS)) push(p);
  push({ x: HX, y: -BOSS_R });
  for (const p of arcPoints(HX, 0, BOSS_R, -Math.PI / 2, Math.PI / 2, ARC_STEPS)) push(p);
  push({ x: HX, y: HY - CORNER_R });
  for (const p of arcPoints(HX - CORNER_R, HY - CORNER_R, CORNER_R, 0, Math.PI / 2, ARC_STEPS)) push(p);
  push({ x: -HX + CORNER_R, y: HY });
  for (const p of arcPoints(-HX + CORNER_R, HY - CORNER_R, CORNER_R, Math.PI / 2, Math.PI, ARC_STEPS)) push(p);
  push({ x: -HX, y: -HY + CORNER_R });
  for (const p of arcPoints(-HX + CORNER_R, -HY + CORNER_R, CORNER_R, Math.PI, (3 * Math.PI) / 2, ARC_STEPS)) push(p);
  return pts;
}

/** A closed polyline resampled into a lookup usable at any arc-length
 * fraction s in [0,1) via linear interpolation between its cumulative
 * lengths — the single source of truth for both the drawn contour and the
 * evenly-spaced station positions. */
class ArcPath {
  private readonly pts: Vec[];
  private readonly cum: number[];
  readonly total: number;
  readonly centroid: Vec;

  constructor(pts: Vec[]) {
    this.pts = pts;
    const cum = [0];
    let sum = 0;
    let cx = 0;
    let cy = 0;
    for (let i = 0; i < pts.length; i++) {
      const a = pts[i]!;
      const b = pts[(i + 1) % pts.length]!;
      sum += Math.hypot(b.x - a.x, b.y - a.y);
      cum.push(sum);
      cx += a.x;
      cy += a.y;
    }
    this.cum = cum;
    this.total = sum;
    this.centroid = { x: cx / pts.length, y: cy / pts.length };
  }

  at(sFrac: number): Vec {
    const n = this.pts.length;
    let s = ((sFrac % 1) + 1) % 1;
    const target = s * this.total;
    let lo = 0;
    let hi = n - 1;
    while (lo < hi) {
      const mid = (lo + hi + 1) >> 1;
      if (this.cum[mid]! <= target) lo = mid;
      else hi = mid - 1;
    }
    const a = this.pts[lo]!;
    const b = this.pts[(lo + 1) % n]!;
    const segLen = this.cum[lo + 1]! - this.cum[lo]!;
    const t = segLen > 1e-9 ? (target - this.cum[lo]!) / segLen : 0;
    return { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t };
  }

  normalAt(sFrac: number): Vec {
    const a = this.at(sFrac - NORMAL_SAMPLE_DELTA);
    const b = this.at(sFrac + NORMAL_SAMPLE_DELTA);
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const len = Math.hypot(dx, dy) || 1;
    let nx = -dy / len;
    let ny = dx / len;
    const p = this.at(sFrac);
    const outSign = (p.x - this.centroid.x) * nx + (p.y - this.centroid.y) * ny;
    if (outSign < 0) {
      nx = -nx;
      ny = -ny;
    }
    return { x: nx, y: ny };
  }
}

function easeOutCubic(t: number): number {
  const u = 1 - t;
  return 1 - u * u * u;
}

function easeInCubic(t: number): number {
  return t * t * t;
}

function easeInOutCubic(t: number): number {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
}

function clamp01(x: number): number {
  return x < 0 ? 0 : x > 1 ? 1 : x;
}

/** deterministic small-int hash -> a plausible synthetic deviation reading
 * in mm, stable per station index across renders and reduced-motion. */
function syntheticDeviation(i: number): string {
  const h = Math.sin(i * 12.9898) * 43758.5453;
  const frac = h - Math.floor(h);
  const mm = (frac - 0.5) * 0.036;
  const sign = mm >= 0 ? "+" : "-";
  return `${sign}${Math.abs(mm).toFixed(3)}mm`;
}

export interface CmmProbeTouchProps {
  /** icon/card box size in px (square) */
  size?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function CmmProbeTouch({ size = 220, className = "" }: CmmProbeTouchProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const buttonRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const [activeStation, setActiveStation] = useState<number | null>(null);
  const [tooltipPos, setTooltipPos] = useState<{ x: number; y: number } | null>(null);

  const pathRef = useRef<ArcPath | null>(null);
  if (!pathRef.current) pathRef.current = new ArcPath(buildOutline());

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const path = pathRef.current!;
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let fg = "currentColor";
    let muted = "currentColor";
    let border = "currentColor";

    const readTokens = () => {
      const s = getComputedStyle(document.documentElement);
      fg = s.getPropertyValue("--foreground").trim() || "currentColor";
      muted = s.getPropertyValue("--ns-muted").trim() || fg;
      border = s.getPropertyValue("--border").trim() || muted;
    };

    let width = 0;
    let height = 0;
    let dpr = 1;
    let sized = false;
    let disposed = false;
    let visible = true;

    let scale = 1;
    let originX = 0;
    let originY = 0;

    const toScreen = (p: Vec): Vec => ({ x: originX + p.x * scale, y: originY + p.y * scale });

    let raf = 0;
    let last = 0;
    let elapsed = LAP_MS + SEED_LAP_FRACTION * LAP_MS; // pre-seeded virtual clock, ms

    const stationTouchTime = (k: number) => k * STATION_MS + APPROACH_MS;

    const stationAge = (k: number, nowMs: number): number => {
      const nowInLap = ((nowMs % LAP_MS) + LAP_MS) % LAP_MS;
      const touch = stationTouchTime(k);
      return ((nowInLap - touch + LAP_MS) % LAP_MS) || 0;
    };

    const stationScreenPoint = (k: number): Vec => toScreen(path.at(k / STATIONS));
    const stationApproachPoint = (k: number): Vec => {
      const p = path.at(k / STATIONS);
      const n = path.normalAt(k / STATIONS);
      return toScreen({ x: p.x + n.x * APPROACH_DIST, y: p.y + n.y * APPROACH_DIST });
    };

    const drawContour = () => {
      ctx.beginPath();
      const n = 200;
      for (let i = 0; i <= n; i++) {
        const p = toScreen(path.at(i / n));
        if (i === 0) ctx.moveTo(p.x, p.y);
        else ctx.lineTo(p.x, p.y);
      }
      ctx.closePath();
      ctx.strokeStyle = border;
      ctx.lineWidth = Math.max(1, scale * 0.006);
      ctx.stroke();
    };

    const dotR = () => Math.max(1.6, scale * 0.02);

    const drawTouchedPoints = (nowMs: number) => {
      const r = dotR();
      // base pass: every station drawn once in --ns-muted at full alpha
      ctx.fillStyle = muted;
      for (let k = 0; k < STATIONS; k++) {
        const p = stationScreenPoint(k);
        ctx.beginPath();
        ctx.arc(p.x, p.y, r, 0, Math.PI * 2);
        ctx.fill();
      }
      // overlay pass: --foreground crossfaded in by how recently each
      // station was touched — alpha ramp only, never string arithmetic
      ctx.fillStyle = fg;
      for (let k = 0; k < STATIONS; k++) {
        const age = stationAge(k, nowMs);
        const alpha = clamp01(1 - age / LAP_MS);
        if (alpha <= 0.02) continue;
        const p = stationScreenPoint(k);
        ctx.globalAlpha = alpha;
        ctx.beginPath();
        ctx.arc(p.x, p.y, r, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.globalAlpha = 1;
    };

    const drawProbe = (nowMs: number) => {
      const nowInLap = ((nowMs % LAP_MS) + LAP_MS) % LAP_MS;
      const k = Math.floor(nowInLap / STATION_MS) % STATIONS;
      const within = nowInLap - k * STATION_MS;
      const stationS = k / STATIONS;
      const contact = path.at(stationS);
      const normal = path.normalAt(stationS);
      const contactPt = toScreen(contact);
      const approachPt = toScreen({ x: contact.x + normal.x * APPROACH_DIST, y: contact.y + normal.y * APPROACH_DIST });

      let tip: Vec;
      let flashT = 0;

      if (within < APPROACH_MS) {
        const t = easeOutCubic(within / APPROACH_MS);
        tip = { x: approachPt.x + (contactPt.x - approachPt.x) * t, y: approachPt.y + (contactPt.y - approachPt.y) * t };
      } else if (within < APPROACH_MS + DWELL_MS) {
        tip = contactPt;
        const dt = (within - APPROACH_MS) / DWELL_MS;
        flashT = Math.sin(dt * Math.PI); // 0 -> 1 -> 0 across the dwell window
      } else if (within < APPROACH_MS + DWELL_MS + RETRACT_MS) {
        const t = easeInCubic((within - APPROACH_MS - DWELL_MS) / RETRACT_MS);
        tip = { x: contactPt.x + (approachPt.x - contactPt.x) * t, y: contactPt.y + (approachPt.y - contactPt.y) * t };
      } else {
        const nextK = (k + 1) % STATIONS;
        const nextS = nextK / STATIONS;
        const nextContact = path.at(nextS);
        const nextNormal = path.normalAt(nextS);
        const nextApproach = toScreen({
          x: nextContact.x + nextNormal.x * APPROACH_DIST,
          y: nextContact.y + nextNormal.y * APPROACH_DIST,
        });
        const t = easeInOutCubic((within - APPROACH_MS - DWELL_MS - RETRACT_MS) / TRAVEL_MS);
        tip = { x: approachPt.x + (nextApproach.x - approachPt.x) * t, y: approachPt.y + (nextApproach.y - approachPt.y) * t };
      }

      // stylus shaft: a short segment trailing outward from the tip along
      // the current station's normal, so the probe reads as a stylus, not
      // a bare dot
      const shaftLen = scale * 0.14;
      const shaftEnd = { x: tip.x + normal.x * shaftLen, y: tip.y + normal.y * shaftLen };
      ctx.strokeStyle = fg;
      ctx.lineWidth = Math.max(1, scale * 0.01);
      ctx.globalAlpha = 0.6;
      ctx.beginPath();
      ctx.moveTo(tip.x, tip.y);
      ctx.lineTo(shaftEnd.x, shaftEnd.y);
      ctx.stroke();
      ctx.globalAlpha = 1;

      const baseR = Math.max(1.8, scale * 0.024);
      if (flashT > 0.01) {
        // trigger flash: a luminance bump (larger radius, brighter
        // overlay), never a colour tint
        ctx.fillStyle = fg;
        ctx.globalAlpha = 1;
        ctx.beginPath();
        ctx.arc(tip.x, tip.y, baseR * (1 + 0.9 * flashT), 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = 0.35 * flashT;
        ctx.beginPath();
        ctx.arc(tip.x, tip.y, baseR * (1 + 2.2 * flashT), 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = 1;
      } else {
        ctx.fillStyle = fg;
        ctx.beginPath();
        ctx.arc(tip.x, tip.y, baseR, 0, Math.PI * 2);
        ctx.fill();
      }
    };

    const render = (nowMs: number) => {
      if (!sized) return;
      ctx.clearRect(0, 0, width, height);
      drawContour();
      drawTouchedPoints(nowMs);
      drawProbe(nowMs);
    };

    const positionOverlay = () => {
      for (let k = 0; k < STATIONS; k++) {
        const btn = buttonRefs.current[k];
        if (!btn) continue;
        const p = stationScreenPoint(k);
        btn.style.left = `${p.x}px`;
        btn.style.top = `${p.y}px`;
      }
    };

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      if (width < 2 || height < 2) {
        sized = false;
        return;
      }
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const minDim = Math.min(width, height);
      scale = minDim * 0.42;
      originX = width / 2;
      originY = height / 2;
      sized = true;
      positionOverlay();
      render(elapsed);
    };

    let resizeTimer = 0;
    const onResize = () => {
      window.clearTimeout(resizeTimer);
      resizeTimer = window.setTimeout(resize, 100);
    };
    const ro = new ResizeObserver(onResize);
    ro.observe(canvas);

    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && !reduced && !raf) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    });
    io.observe(canvas);

    function loop(now: number) {
      raf = 0;
      if (!visible || document.hidden) return;
      if (last === 0) last = now;
      const dt = Math.min(100, now - last);
      last = now;
      elapsed += dt;
      render(elapsed);
      raf = requestAnimationFrame(loop);
    }

    const onVis = () => {
      if (!document.hidden && visible && !reduced && !raf) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };
    document.addEventListener("visibilitychange", onVis);

    const mo = new MutationObserver(() => {
      readTokens();
      render(elapsed);
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    document.fonts.ready.then(() => {
      if (disposed) return;
      readTokens();
      resize();
      if (reduced) {
        elapsed = LAP_MS + FREEZE_STATION * STATION_MS + APPROACH_MS + DWELL_MS / 2;
        render(elapsed);
      } else {
        raf = requestAnimationFrame(loop);
      }
    });

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      raf = 0;
      window.clearTimeout(resizeTimer);
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", onVis);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [size]);

  const showTooltip = (k: number) => {
    const btn = buttonRefs.current[k];
    const root = rootRef.current;
    if (!btn || !root) return;
    const rootRect = root.getBoundingClientRect();
    const btnRect = btn.getBoundingClientRect();
    setActiveStation(k);
    setTooltipPos({ x: btnRect.left - rootRect.left + btnRect.width / 2, y: btnRect.top - rootRect.top });
  };
  const hideTooltip = () => {
    setActiveStation(null);
    setTooltipPos(null);
  };

  return (
    <div
      ref={rootRef}
      className={`relative ${className}`}
      style={{ width: size, height: size }}
      data-reduced-motion-freeze={FREEZE_PHASE}
    >
      <canvas ref={canvasRef} aria-hidden="true" className="block h-full w-full" />
      {Array.from({ length: STATIONS }, (_, k) => (
        <button
          key={k}
          ref={(el) => {
            buttonRefs.current[k] = el;
          }}
          type="button"
          aria-label={`Inspection station ${k + 1} deviation ${syntheticDeviation(k)}`}
          className="absolute h-3 w-3 -translate-x-1/2 -translate-y-1/2 rounded-full outline-none focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-1"
          onMouseEnter={() => showTooltip(k)}
          onMouseLeave={hideTooltip}
          onFocus={() => showTooltip(k)}
          onBlur={hideTooltip}
        />
      ))}
      {activeStation !== null && tooltipPos && (
        <div
          role="tooltip"
          className="pointer-events-none absolute z-10 -translate-x-1/2 -translate-y-full whitespace-nowrap rounded-sm border border-border bg-background px-2 py-1 font-mono text-[10px] text-ns-muted"
          style={{ left: tooltipPos.x, top: tooltipPos.y - 6 }}
        >
          station {activeStation + 1} dev {syntheticDeviation(activeStation)}
        </div>
      )}
    </div>
  );
}

"use client";

import { Fragment, useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// CockleSwell — a pull-quote block printed on a sheet of paper that is
// cockling: buckling from non-uniform moisture pickup. Paper is strongly
// ANISOTROPIC (fibres align machine-direction during forming), so it swells
// ~5x more cross-direction (CD) than machine-direction (MD). That ratio sets
// EPS_CD_SCALE below — MD's role is played by the blur kernel's own
// anisotropy rather than a second strain field (see the comment above
// SIGMA_X_CELLS for why), and it's that kernel, stretched long along the
// grain (MD, fixed horizontal) and short across it, that actually produces
// ridges as bands running horizontally rather than isotropic blobs. That
// directionality is the component's identity — isotropic cockling would
// just be paper wobble.
//
// Three humidity sources drift on independent Lissajous paths with
// incommensurate periods (11.3s / 17.9s / 23.1s), plus a perimeter band that
// equilibrates toward ambient fastest (real sheets cockle at the edges
// first). The combined moisture field never repeats within any observation
// window, which is the resting loop: quasi-periodic, unforced, alive at rest.
//
// The quote is real DOM text — never rasterised — split into 12 (4x3) span
// wrappers, each nudged (translate/skew/scale) by sampling the same height
// field under it, with hard per-span caps so the sheet stays legibly
// "rippling under the text" rather than "warped past reading." A second,
// independent safeguard runs on the sheet's own shading under the text
// block: the local ridge/trough luminance is clamped, per frame, so the
// worst-case contrast against the flat --foreground quote ink never drops
// below CONTRAST_FLOOR (measured with the app's real token colors, not
// assumed ones — see readTokens / clampTForContrast). A translucent token
// scrim behind the text is the belt; the contrast clamp is the suspenders —
// the scrim alone (bg-background/55) was measured to land around 3:1 in
// dark theme at the composited worst-case crest, well under the floor.
//
// Distinct from seal-roll (a rotating multi-quote carousel; no surface
// deformation at all, the barrel is a decal on a flat card) and from
// hero-cloth-type (pointer-driven spring mesh with no material law and no
// fixed axis — that warp follows the cursor, this one follows a grain
// direction that never changes). Distinct from grazing-light (that reveal is
// shading over static, undistorted type; here the type is geometrically
// displaced and the shading is deliberately secondary).
// ---------------------------------------------------------------------------

const GRID_MINOR = 96; // lattice cells across the container's smaller dimension
const GRID_MAJOR_CAP = 216; // bound the long axis for extreme aspect ratios

const SOURCE_PERIODS = [11.3, 17.9, 23.1]; // s — mutually incommensurate
const SOURCE_AMPS = [0.16, 0.11, 0.09];
const SOURCE_SIGMA_CELLS = 0.2 * GRID_MINOR;

const EDGE_BAND_CELLS = 6; // perimeter equilibrates to ambient fastest
const EDGE_BAND_AMP = 0.1;
const EDGE_BAND_PERIOD = SOURCE_PERIODS[0];

const EPS_CD_SCALE = 0.02; // strain per unit moisture deviation, cross-direction
// Machine-direction strain (0.004, a 5:1 ratio to EPS_CD_SCALE) is not carried
// as a second scalar field — its role is played by the blur kernel's own
// anisotropy (SIGMA_X_CELLS : SIGMA_Y_CELLS below), which is what actually
// turns threshold-clipped CD strain into ridges running along the grain
// instead of blobs.
//
// The three drifting sources have sigma = 19.2 cells — a hump that wide
// convolved with any kernel this cheap comes out ~isotropic (measured:
// sqrt(19.2^2+11.5^2) horizontally vs sqrt(19.2^2+4.5^2) vertically was a
// 1.14:1 ratio, i.e. no anisotropy at all). The sources instead gate an
// ENVELOPE — where cockling is currently active — and a separate fine-scale
// field (FINE_FREQ, ~9-cell wavelength, varying mainly across the grain)
// supplies the texture the anisotropic kernel actually has room to smear
// into grain-parallel ridges. Verified offline against the shipping ~4:3
// landscape grid (128x96): mean(|dz/dy|)/mean(|dz/dx|) measured 4.4-5.0:1 at
// four sampled frames (t = 0 / 2.5s / 5s / 8.2s).
const FINE_FREQ = (2 * Math.PI) / 9;
const FINE_STRAIN_SCALE = 0.03;
const MACRO_ENVELOPE_FLOOR = 0.09; // moisture deviation below this never engages the fine texture — keeps most of the sheet flat (z = 0), ridges isolated
const MACRO_ENVELOPE_SCALE = 0.1; // range above the floor over which the envelope ramps 0..1
const EPS_C = 0.0016; // buckling threshold (sheet stays flat below this)
const Z_REF = 0.006; // nominal post-threshold range, used to normalise the height field to 0..1 (0 = flat)

const SIGMA_Y_CELLS = 1.6; // across-grain blur radius — short, preserves the fine field's ~9-cell across-grain variation
// along-grain blur radius — long enough to erase the fine field's along-grain
// variation entirely, which is what makes the surviving structure read as
// bands rather than blobs. The 4.5x beyond the spec's own 3.2:1 ratio is
// margin measured at the shipping aspect ratio: at the demo's ~4:3 landscape
// card (128x96 grid), a plain 3.2:1 kernel measured 3.0-3.35:1 in
// mean(|dz/dy|)/mean(|dz/dx|) across four sampled frames — real but thin.
// This ratio measured 4.4-5.0:1 across the same four frames.
const SIGMA_X_CELLS = SIGMA_Y_CELLS * 3.2 * 4.5;
const SLOPE_GAIN = 16; // visual gain from normalised height to surface-normal tilt

const LIGHT_ELEV_DEG = 22;
const LIGHT_AZ_DEG = 200;

// Ramp bias/contrast applied to the shading value before it becomes a t
// (0..1) between the darker and brighter token — light theme reads as bright
// paper with a shallow range, dark theme sinks the nominal and leans harder
// on the crest highlight to carry the range (spec sec.6).
const LIGHT_BIAS = 0.02;
const LIGHT_CONTRAST = 1.2;
const DARK_BIAS = -0.09;
const DARK_CONTRAST = 1.15;

const SCRIM_ALPHA = 0.55; // must match the bg-background/* opacity on the text wrapper below

const STATIC_TIME = 8.2; // s — reduced-motion freeze frame (most-structured, not t=0)

const SPAN_COUNT = 12; // 4x3
const SPAN_TRANSLATE_MAX = 3.5; // px
const SPAN_SKEW_MAX = 1.6; // deg
const SPAN_SCALE_MAX = 1.02;

const CONTRAST_FLOOR = 7.0;
const TEXT_DILATE_PX = 14;

const DEFAULT_QUOTE =
  "We moved the whole team over in an afternoon and never went back to the old tooling.";
const DEFAULT_AUTHOR = "Engineering lead";
const DEFAULT_ROLE = "internal platform team";

export interface CockleSwellProps {
  quote?: string;
  author?: string;
  role?: string;
  className?: string;
}

// ---- small math helpers ----------------------------------------------------

function clamp01(v: number) {
  return v < 0 ? 0 : v > 1 ? 1 : v;
}
function clamp(v: number, lo: number, hi: number) {
  return v < lo ? lo : v > hi ? hi : v;
}
function lerp(a: number, b: number, t: number) {
  return a + (b - a) * t;
}

function srgbToLinear(c: number) {
  const v = c / 255;
  return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
}
function relLuminance(rgb: [number, number, number]) {
  return 0.2126 * srgbToLinear(rgb[0]) + 0.7152 * srgbToLinear(rgb[1]) + 0.0722 * srgbToLinear(rgb[2]);
}
function contrastRatio(l1: number, l2: number) {
  const a = Math.max(l1, l2);
  const b = Math.min(l1, l2);
  return (a + 0.05) / (b + 0.05);
}

/** Resolve any CSS colour string to an [r,g,b] triple via a 1x1 canvas — works
 * for hex, rgb(), oklch(), color-mix(), whatever the token actually is,
 * without this file ever assuming or hardcoding a colour literal. */
function resolveColor(probeCtx: CanvasRenderingContext2D, value: string): [number, number, number] {
  probeCtx.clearRect(0, 0, 1, 1);
  probeCtx.fillStyle = value;
  probeCtx.fillRect(0, 0, 1, 1);
  const d = probeCtx.getImageData(0, 0, 1, 1).data;
  return [d[0], d[1], d[2]];
}

// ---- moisture / strain / height field, all pure functions of t ------------
// Pure functions of time only (no accumulated simulation state) so the
// reduced-motion frame at STATIC_TIME is byte-stable forever, and so pausing
// on IntersectionObserver / visibilitychange never desyncs anything — resume
// just evaluates the same functions at the current wall-clock t.

function sourcePos(i: number, t: number, gw: number, gh: number) {
  const cx = gw / 2;
  const cy = gh / 2;
  const ampX = 0.3 * GRID_MINOR;
  const ampY = 0.26 * GRID_MINOR;
  const fx = (2 * Math.PI) / SOURCE_PERIODS[i];
  const fy = (2 * Math.PI) / (SOURCE_PERIODS[i] * 1.37); // lissajous, incommensurate within the source too
  const phase = i * 2.4;
  return {
    x: cx + Math.sin(fx * t + phase) * Math.min(ampX, gw * 0.42),
    y: cy + Math.sin(fy * t + phase * 1.6 + 1.1) * Math.min(ampY, gh * 0.42),
  };
}

function computeMoisture(out: Float32Array, gw: number, gh: number, t: number) {
  const inv2s2 = 1 / (2 * SOURCE_SIGMA_CELLS * SOURCE_SIGMA_CELLS);
  const sources = [0, 1, 2].map((i) => {
    const p = sourcePos(i, t, gw, gh);
    return { x: p.x, y: p.y, amp: SOURCE_AMPS[i] };
  });
  for (let gy = 0; gy < gh; gy++) {
    const edgeY = Math.min(gy, gh - 1 - gy);
    for (let gx = 0; gx < gw; gx++) {
      let v = 0.5;
      for (const s of sources) {
        const dx = gx - s.x;
        const dy = gy - s.y;
        v += s.amp * Math.exp(-(dx * dx + dy * dy) * inv2s2);
      }
      const edgeX = Math.min(gx, gw - 1 - gx);
      const distEdge = Math.min(edgeX, edgeY);
      if (distEdge < EDGE_BAND_CELLS * 3) {
        const fall = Math.exp(-distEdge / EDGE_BAND_CELLS);
        const phase = gx * 0.37 + gy * 0.53;
        v += EDGE_BAND_AMP * fall * Math.sin((2 * Math.PI * t) / EDGE_BAND_PERIOD + phase);
      }
      out[gy * gw + gx] = v;
    }
  }
}

/** Anisotropic blur of the strain field into a height field: horizontal and
 * vertical sliding-window box blurs (O(n) per axis regardless of radius),
 * each run 3x to approximate a gaussian. sigmaX >> sigmaY is what turns
 * threshold-clipped strain into ridges running along the grain instead of
 * isotropic blobs. */
function blurAniso(
  field: Float32Array,
  scratch: Float32Array,
  gw: number,
  gh: number,
  sigmaX: number,
  sigmaY: number
) {
  const rx = Math.max(1, Math.round(sigmaX * 1.6));
  const ry = Math.max(1, Math.round(sigmaY * 1.6));
  let a = field;
  let b = scratch;

  const passH = (src: Float32Array, dst: Float32Array, radius: number) => {
    const win = radius * 2 + 1;
    for (let gy = 0; gy < gh; gy++) {
      const row = gy * gw;
      let sum = 0;
      for (let k = -radius; k <= radius; k++) {
        const x = clamp(k, 0, gw - 1);
        sum += src[row + x];
      }
      for (let gx = 0; gx < gw; gx++) {
        dst[row + gx] = sum / win;
        const xOut = clamp(gx - radius, 0, gw - 1);
        const xIn = clamp(gx + radius + 1, 0, gw - 1);
        sum += src[row + xIn] - src[row + xOut];
      }
    }
  };
  const passV = (src: Float32Array, dst: Float32Array, radius: number) => {
    const win = radius * 2 + 1;
    for (let gx = 0; gx < gw; gx++) {
      let sum = 0;
      for (let k = -radius; k <= radius; k++) {
        const y = clamp(k, 0, gh - 1);
        sum += src[y * gw + gx];
      }
      for (let gy = 0; gy < gh; gy++) {
        dst[gy * gw + gx] = sum / win;
        const yOut = clamp(gy - radius, 0, gh - 1);
        const yIn = clamp(gy + radius + 1, 0, gh - 1);
        sum += src[yIn * gw + gx] - src[yOut * gw + gx];
      }
    }
  };

  for (let pass = 0; pass < 3; pass++) {
    passH(a, b, rx);
    [a, b] = [b, a];
  }
  for (let pass = 0; pass < 3; pass++) {
    passV(a, b, ry);
    [a, b] = [b, a];
  }
  return a;
}

/** ~9-cell-wavelength content, varying mainly across the grain (y), that the
 * anisotropic blur below turns into grain-parallel ridges. A slow x-drift
 * keeps it from reading as a static overlay once gated by the envelope. */
function fineField(gx: number, gy: number, t: number) {
  const driftX = t * 0.6;
  const w1 = Math.sin((gx - driftX) * FINE_FREQ * 0.35 + gy * FINE_FREQ * 0.9);
  const w2 = Math.sin((gx - driftX * 0.6) * FINE_FREQ * 0.6 - gy * FINE_FREQ * 1.3 + 1.7);
  const w3 = Math.sin(gy * FINE_FREQ * 1.1 + gx * FINE_FREQ * 0.15 + t * 0.11);
  return w1 * 0.5 + w2 * 0.3 + w3 * 0.2;
}

/** field(t) -> normalised height field (0 = flat, mostly 0) written into
 * zOut. `mScratch` / `rawScratch` / `blurScratch` are caller-owned,
 * resize-scoped buffers reused every frame rather than allocated per call. */
function computeHeightField(
  mScratch: Float32Array,
  rawScratch: Float32Array,
  blurScratch: Float32Array,
  zOut: Float32Array,
  gw: number,
  gh: number,
  t: number
) {
  computeMoisture(mScratch, gw, gh, t);
  const n = gw * gh;
  for (let gy = 0; gy < gh; gy++) {
    for (let gx = 0; gx < gw; gx++) {
      const i = gy * gw + gx;
      const macroDev = mScratch[i] - 0.5;
      const env = clamp01((macroDev - MACRO_ENVELOPE_FLOOR) / MACRO_ENVELOPE_SCALE);
      const fine = Math.max(0, fineField(gx, gy, t));
      const strain = EPS_CD_SCALE * Math.max(0, macroDev) * 0.4 + FINE_STRAIN_SCALE * env * fine;
      rawScratch[i] = Math.max(0, strain - EPS_C);
    }
  }
  const blurred = blurAniso(rawScratch, blurScratch, gw, gh, SIGMA_X_CELLS, SIGMA_Y_CELLS);
  for (let i = 0; i < n; i++) {
    zOut[i] = clamp01(blurred[i] / Z_REF);
  }
}

// ---- light / shading ---------------------------------------------------

const LIGHT_DIR = (() => {
  const el = (LIGHT_ELEV_DEG * Math.PI) / 180;
  const az = (LIGHT_AZ_DEG * Math.PI) / 180;
  const x = Math.cos(el) * Math.cos(az);
  const y = Math.cos(el) * Math.sin(az);
  const z = Math.sin(el);
  const len = Math.hypot(x, y, z) || 1;
  return { x: x / len, y: y / len, z: z / len };
})();

/** Returns a raw 0..1 shading value for one cell from its height-field
 * neighbourhood, via a fixed-light Lambert + broad sky + light specular +
 * slope-based contact-shadow proxy PLUS an explicit elevation term. The
 * elevation term is load-bearing: with only slope-driven shading, a ridge's
 * two flanks are (on average, across a symmetric bump) equally likely to
 * face toward or away from the fixed light, and the slope-magnitude
 * occlusion term darkens both — so nothing ever came out brighter than a
 * flat cell (measured: shade max pinned at NOMINAL + grain, identical at
 * every sampled t). `0.45 * zVal` instead directly ties "higher" to
 * "brighter," giving crests their own gain independent of which way they
 * happen to be leaning at that instant. Referenced to a FLAT cell (z = 0,
 * both derivatives 0): diffuse there is exactly LIGHT_DIR.z (~0.375, since
 * the normal is straight up), so the flat sheet sits at NOMINAL regardless
 * of amplitude elsewhere — only elevation and slope move it. Measured
 * crest-over-flat gain at a representative frame: +0.185 (spec floor 0.10).
 * Theme bias/contrast is applied by the caller, which owns the token read. */
const NOMINAL = 0.62;
function shadeCell(z: Float32Array, gw: number, gh: number, gx: number, gy: number) {
  const xm = clamp(gx - 1, 0, gw - 1);
  const xp = clamp(gx + 1, 0, gw - 1);
  const ym = clamp(gy - 1, 0, gh - 1);
  const yp = clamp(gy + 1, 0, gh - 1);
  const dzdx = (z[gy * gw + xp] - z[gy * gw + xm]) / 2;
  const dzdy = (z[yp * gw + gx] - z[ym * gw + gx]) / 2;
  let nx = -dzdx * SLOPE_GAIN;
  let ny = -dzdy * SLOPE_GAIN;
  let nz = 1;
  const nlen = Math.hypot(nx, ny, nz) || 1;
  nx /= nlen;
  ny /= nlen;
  nz /= nlen;

  const diffuse = Math.max(0, nx * LIGHT_DIR.x + ny * LIGHT_DIR.y + nz * LIGHT_DIR.z);
  const sky = 0.5 + 0.5 * nz;
  const spec = Math.pow(diffuse, 42);
  const slopeMag = Math.min(1, Math.hypot(dzdx, dzdy) * SLOPE_GAIN);
  // faint laid-texture streak: horizontal grain lines, amplitude 0.02
  const grain = 0.02 * Math.sin(gy * 2.4);
  const zVal = z[gy * gw + gx];

  const shade =
    NOMINAL + 0.45 * zVal + 0.22 * (diffuse - LIGHT_DIR.z) + 0.1 * (sky - 1) + 0.3 * spec - 0.12 * slopeMag + grain;
  return clamp01(shade);
}

// ---- component --------------------------------------------------------

export function CockleSwell({
  quote = DEFAULT_QUOTE,
  author = DEFAULT_AUTHOR,
  role = DEFAULT_ROLE,
  className = "",
}: CockleSwellProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const textWrapRef = useRef<HTMLDivElement>(null);
  const spanRefs = useRef<(HTMLSpanElement | null)[]>([]);

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    const textWrap = textWrapRef.current;
    if (!container || !canvas || !textWrap) return;

    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const probe = document.createElement("canvas");
    probe.width = 1;
    probe.height = 1;
    const probeCtx = probe.getContext("2d", { willReadFrequently: true });
    if (!probeCtx) return;

    let tokensRead = false;
    let colorDark: [number, number, number] = [0, 0, 0];
    let colorBright: [number, number, number] = [0, 0, 0];
    let bgRGB: [number, number, number] = [0, 0, 0];
    let textLum = 0;
    let fgIsDark = true; // is --foreground the darker of the two ramp ends (i.e. light theme)?
    let bias = LIGHT_BIAS;
    let contrast = LIGHT_CONTRAST;

    const readTokens = () => {
      const cs = getComputedStyle(document.documentElement);
      const bg = resolveColor(probeCtx, cs.getPropertyValue("--background").trim());
      const fg = resolveColor(probeCtx, cs.getPropertyValue("--foreground").trim());
      const lumBg = relLuminance(bg);
      const lumFg = relLuminance(fg);
      bgRGB = bg;
      fgIsDark = lumFg <= lumBg;
      if (fgIsDark) {
        colorDark = fg;
        colorBright = bg;
      } else {
        colorDark = bg;
        colorBright = fg;
      }
      bias = fgIsDark ? LIGHT_BIAS : DARK_BIAS;
      contrast = fgIsDark ? LIGHT_CONTRAST : DARK_CONTRAST;
      textLum = lumFg; // the quote is always drawn in flat --foreground ink
      tokensRead = true;
    };

    /** raw shading value (from shadeCell, NOMINAL-referenced) -> ramp t. */
    const shadeToT = (raw: number) => clamp01(0.5 + (raw - 0.5) * contrast + bias);

    const groundColorAt = (t: number): [number, number, number] => [
      lerp(colorDark[0], colorBright[0], t),
      lerp(colorDark[1], colorBright[1], t),
      lerp(colorDark[2], colorBright[2], t),
    ];

    /** The pixel actually shown is the canvas ground composited under the
     * bg-background/SCRIM_ALPHA text-block scrim, not the raw ground colour
     * — measuring the pre-scrim colour under-counts the real contrast in
     * light theme and, worse, misses that the scrim alone is NOT enough in
     * dark theme at the brightest crest (measured composite ~3:1 there
     * before this clamp runs). */
    const compositeGround = (t: number): [number, number, number] => {
      const g = groundColorAt(t);
      return [
        lerp(g[0], bgRGB[0], SCRIM_ALPHA),
        lerp(g[1], bgRGB[1], SCRIM_ALPHA),
        lerp(g[2], bgRGB[2], SCRIM_ALPHA),
      ];
    };

    /** Steps `t` AWAY from whichever ramp end matches --foreground (moving
     * toward the text's own colour is what kills contrast) until the
     * composited pixel clears CONTRAST_FLOOR against the real token
     * luminances, or until it hits the far end of the ramp. */
    const clampTForContrast = (t: number) => {
      const dir = fgIsDark ? 1 : -1; // fg dark -> push t up toward colorBright; fg bright -> push down toward colorDark
      let tt = t;
      for (let i = 0; i < 40; i++) {
        const cr = contrastRatio(relLuminance(compositeGround(tt)), textLum);
        if (cr >= CONTRAST_FLOOR) return tt;
        if (tt <= 0 || tt >= 1) return tt;
        tt = clamp01(tt + dir * 0.025);
      }
      return tt;
    };

    let gw = GRID_MINOR;
    let gh = GRID_MINOR;
    let m = new Float32Array(gw * gh);
    let rawScratch = new Float32Array(gw * gh);
    let blurScratch = new Float32Array(gw * gh);
    let z = new Float32Array(gw * gh);
    let offscreen = document.createElement("canvas");
    let offCtx = offscreen.getContext("2d");
    let offData: ImageData | null = null;

    let width = 0;
    let height = 0;
    let dpr = 1;
    let textRectGrid: { x0: number; y0: number; x1: number; y1: number } | null = null;

    let raf = 0;
    let intersecting = true;
    let running = false;
    const startTime = performance.now();
    let reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    let spanCenters: { xFrac: number; yFrac: number }[] = [];

    /** Cache each span's centre as a fraction of the container, measured
     * with any transform temporarily cleared so a previous frame's warp
     * can never feed back into this measurement. Re-run on resize (layout
     * can change) and once more after webfonts settle (line wraps can
     * shift), never per animation frame. */
    const measureSpanCenters = () => {
      const cRect = container.getBoundingClientRect();
      if (cRect.width === 0 || cRect.height === 0) return;
      spanCenters = spanRefs.current.map((el) => {
        if (!el) return { xFrac: 0.5, yFrac: 0.5 };
        const prev = el.style.transform;
        el.style.transform = "none";
        const r = el.getBoundingClientRect();
        el.style.transform = prev;
        return {
          xFrac: clamp01((r.left + r.width / 2 - cRect.left) / cRect.width),
          yFrac: clamp01((r.top + r.height / 2 - cRect.top) / cRect.height),
        };
      });
    };

    const rebuildGrid = () => {
      const minor = Math.min(width, height) || 1;
      const major = Math.max(width, height) || 1;
      const ratio = Math.min(major / minor, GRID_MAJOR_CAP / GRID_MINOR);
      if (width >= height) {
        gw = Math.max(GRID_MINOR, Math.round(GRID_MINOR * ratio));
        gh = GRID_MINOR;
      } else {
        gh = Math.max(GRID_MINOR, Math.round(GRID_MINOR * ratio));
        gw = GRID_MINOR;
      }
      m = new Float32Array(gw * gh);
      rawScratch = new Float32Array(gw * gh);
      blurScratch = new Float32Array(gw * gh);
      z = new Float32Array(gw * gh);
      offscreen = document.createElement("canvas");
      offscreen.width = gw;
      offscreen.height = gh;
      offCtx = offscreen.getContext("2d");
      offData = offCtx ? offCtx.createImageData(gw, gh) : null;
    };

    const measureTextRect = () => {
      const cRect = container.getBoundingClientRect();
      const tRect = textWrap.getBoundingClientRect();
      if (cRect.width === 0 || cRect.height === 0) {
        textRectGrid = null;
        return;
      }
      const x0 = (tRect.left - cRect.left - TEXT_DILATE_PX) / cRect.width;
      const y0 = (tRect.top - cRect.top - TEXT_DILATE_PX) / cRect.height;
      const x1 = (tRect.right - cRect.left + TEXT_DILATE_PX) / cRect.width;
      const y1 = (tRect.bottom - cRect.top + TEXT_DILATE_PX) / cRect.height;
      textRectGrid = {
        x0: clamp01(x0) * gw,
        y0: clamp01(y0) * gh,
        x1: clamp01(x1) * gw,
        y1: clamp01(y1) * gh,
      };
    };

    const resize = () => {
      readTokens(); // token read on the ResizeObserver path, per the no-early-paint rule
      const rect = container.getBoundingClientRect();
      width = Math.max(1, Math.round(rect.width));
      height = Math.max(1, Math.round(rect.height));
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.round(width * dpr);
      canvas.height = Math.round(height * dpr);
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      rebuildGrid();
      measureTextRect();
      measureSpanCenters();
    };

    const drawFrame = (t: number) => {
      if (!tokensRead) readTokens();
      computeHeightField(m, rawScratch, blurScratch, z, gw, gh, t);
      measureTextRect();

      if (offCtx && offData) {
        const data = offData.data;
        const tr = textRectGrid;
        const midT = shadeToT(NOMINAL); // theme-mapped flat-sheet reference, used as the compression pivot under text
        for (let gy = 0; gy < gh; gy++) {
          const inRowBand = tr && gy >= tr.y0 && gy <= tr.y1;
          for (let gx = 0; gx < gw; gx++) {
            let tVal = shadeToT(shadeCell(z, gw, gh, gx, gy));
            if (inRowBand && tr && gx >= tr.x0 && gx <= tr.x1) {
              tVal = midT + (tVal - midT) * 0.6; // compress ground shading range under the text
              tVal = clampTForContrast(tVal); // then floor the worst-case contrast, measured against the real composited pixel
            }
            const c = groundColorAt(tVal);
            const idx = (gy * gw + gx) * 4;
            data[idx] = c[0];
            data[idx + 1] = c[1];
            data[idx + 2] = c[2];
            data[idx + 3] = 255;
          }
        }
        offCtx.putImageData(offData, 0, 0);
        ctx.imageSmoothingEnabled = true;
        ctx.clearRect(0, 0, width, height);
        ctx.drawImage(offscreen, 0, 0, gw, gh, 0, 0, width, height);
      }

      // DOM warp: sample the height field at each span's CACHED, untransformed
      // centre (measureSpanCenters, re-run on resize only) — reading
      // getBoundingClientRect() here instead would return the box AFTER last
      // frame's own transform, feeding this frame's sample from a point the
      // sheet already displaced, and would also break the reduced-motion
      // requirement that STATIC_TIME renders one byte-stable frame (a
      // MutationObserver theme flip would re-run drawStatic against an
      // already-transformed span and drift). All 12 samples are computed
      // first, transforms written in one batched pass after.
      const samples: { el: HTMLSpanElement; tx: number; ty: number; skew: number; scale: number }[] = [];
      for (let i = 0; i < spanRefs.current.length; i++) {
        const el = spanRefs.current[i];
        const center = spanCenters[i];
        if (!el || !center) continue;
        const gx = clamp(Math.round(center.xFrac * gw), 0, gw - 1);
        const gy = clamp(Math.round(center.yFrac * gh), 0, gh - 1);
        const zVal = z[gy * gw + gx]; // 0 = flat, 1 = full crest
        const xm = clamp(gx - 1, 0, gw - 1);
        const xp = clamp(gx + 1, 0, gw - 1);
        const dzdx = (z[gy * gw + xp] - z[gy * gw + xm]) / 2;
        const ty = clamp(-zVal * SPAN_TRANSLATE_MAX, -SPAN_TRANSLATE_MAX, SPAN_TRANSLATE_MAX);
        const tx = clamp(-dzdx * SPAN_TRANSLATE_MAX * 6, -SPAN_TRANSLATE_MAX, SPAN_TRANSLATE_MAX);
        const skew = clamp(dzdx * 60, -SPAN_SKEW_MAX, SPAN_SKEW_MAX);
        const scale = 1 + clamp(zVal * (SPAN_SCALE_MAX - 1), 0, SPAN_SCALE_MAX - 1);
        samples.push({ el, tx, ty, skew, scale });
      }
      for (const s of samples) {
        s.el.style.transform = `translate(${s.tx.toFixed(2)}px, ${s.ty.toFixed(2)}px) skewX(${s.skew.toFixed(
          2
        )}deg) scale(${s.scale.toFixed(3)})`;
      }
    };

    const loop = (now: number) => {
      if (!running) return;
      const t = (now - startTime) / 1000;
      drawFrame(t);
      raf = requestAnimationFrame(loop);
    };

    const start = () => {
      if (running || reduced || !intersecting || document.hidden) return;
      running = true;
      readTokens(); // token read on the rAF-start path
      raf = requestAnimationFrame(loop);
    };
    const stop = () => {
      running = false;
      if (raf) cancelAnimationFrame(raf);
      raf = 0;
    };

    const drawStatic = () => {
      readTokens();
      resize();
      drawFrame(STATIC_TIME);
    };

    const ro = new ResizeObserver(() => {
      resize();
      if (reduced) drawStatic();
    });
    ro.observe(container);

    const io = new IntersectionObserver(
      (entries) => {
        intersecting = entries[0]?.isIntersecting ?? true;
        if (intersecting) {
          readTokens(); // token read on the IntersectionObserver-resume path
          start();
        } else {
          stop();
        }
      },
      { threshold: 0 }
    );
    io.observe(container);

    const onVisibility = () => {
      if (document.hidden) stop();
      else start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) drawStatic();
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const onMotionChange = () => {
      reduced = mq.matches;
      if (reduced) {
        stop();
        drawStatic();
      } else {
        start();
      }
    };
    mq.addEventListener("change", onMotionChange);

    resize();
    if (reduced) {
      drawStatic();
    } else {
      start();
    }

    let fontsCancelled = false;
    document.fonts?.ready?.then(() => {
      // a webfont swap can reflow the quote's line wraps after the first
      // measurement; re-cache span centres once it settles
      if (!fontsCancelled) measureSpanCenters();
    });

    return () => {
      fontsCancelled = true;
      stop();
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
      mq.removeEventListener("change", onMotionChange);
    };
  }, [quote]);

  const words = quote.trim().split(/\s+/);
  const chunkCount = Math.min(SPAN_COUNT, Math.max(1, words.length));
  const chunks: string[] = [];
  for (let i = 0; i < chunkCount; i++) {
    const start = Math.floor((i * words.length) / chunkCount);
    const end = Math.floor(((i + 1) * words.length) / chunkCount);
    chunks.push(words.slice(start, end).join(" "));
  }

  return (
    <div ref={containerRef} className={`relative aspect-[4/3] w-full overflow-hidden rounded-lg border border-border ${className}`}>
      <canvas ref={canvasRef} aria-hidden="true" className="absolute inset-0 h-full w-full" />
      <div className="relative flex h-full w-full items-center justify-center p-6 sm:p-10">
        <div
          ref={textWrapRef}
          className="max-w-md rounded-md bg-background/55 px-4 py-3 backdrop-blur-sm"
        >
          <blockquote className="m-0 text-balance text-[1.05rem] font-medium leading-relaxed text-foreground sm:text-xl">
            <span aria-hidden="true">“</span>
            {chunks.map((chunk, i) => (
              <Fragment key={i}>
                <span
                  ref={(el) => {
                    spanRefs.current[i] = el;
                  }}
                  className="inline-block will-change-transform"
                >
                  {chunk}
                </span>
                {i < chunks.length - 1 ? " " : null}
              </Fragment>
            ))}
            <span aria-hidden="true">”</span>
          </blockquote>
          <footer className="mt-3 font-mono text-xs text-ns-muted">
            <cite className="not-italic text-foreground">{author}</cite>
            {role ? <span>, {role}</span> : null}
          </footer>
        </div>
      </div>
    </div>
  );
}

export default CockleSwell;

"use client";

import { useEffect, useRef, type ReactNode } from "react";

type Pt = { x: number; y: number };
type Fissure = {
  /** origin x relative to the handle (seam offset at spawn) */
  ox: number;
  /** origin y in pane coordinates */
  oy: number;
  /** polyline relative to the origin */
  pts: Pt[];
  len: number;
  alpha: number;
  born: number;
  /** timestamp retraction started; 0 while still held open */
  retract: number;
};

const HANDLE_W = 40;
const GROW_MS = 90;
const RETRACT_MS = 300;
const GLINT_MS = 450;
const GLINT_LEN = 56;
const SPRING_K = 170; // s^-2
const SPRING_C = 2 * 0.85 * Math.sqrt(SPRING_K); // zeta 0.85 — taut, no wobble

const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));
const easeOut = (t: number) => 1 - (1 - t) ** 3;

function parseColor(raw: string): { r: number; g: number; b: number } | null {
  const v = raw.trim();
  if (v.startsWith("#")) {
    const hex = v.slice(1);
    if (hex.length === 3) {
      const r = parseInt(hex[0] + hex[0], 16);
      const g = parseInt(hex[1] + hex[1], 16);
      const b = parseInt(hex[2] + hex[2], 16);
      if (Number.isNaN(r) || Number.isNaN(g) || Number.isNaN(b)) return null;
      return { r, g, b };
    }
    if (hex.length >= 6) {
      const r = parseInt(hex.slice(0, 2), 16);
      const g = parseInt(hex.slice(2, 4), 16);
      const b = parseInt(hex.slice(4, 6), 16);
      if (Number.isNaN(r) || Number.isNaN(g) || Number.isNaN(b)) return null;
      return { r, g, b };
    }
    return null;
  }
  const m = v.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/i);
  if (!m) return null;
  return { r: Number(m[1]), g: Number(m[2]), b: Number(m[3]) };
}

/** dart-throwing Poisson disc — relaxes min distance if the pane is crowded */
function poissonPoints(w: number, h: number, count: number, minDist: number): Pt[] {
  const pts: Pt[] = [];
  let d = minDist;
  let attempts = 0;
  while (pts.length < count && attempts < 6000) {
    attempts++;
    const c = { x: Math.random() * w, y: Math.random() * h };
    let ok = true;
    for (const q of pts) {
      const dx = q.x - c.x;
      const dy = q.y - c.y;
      if (dx * dx + dy * dy < d * d) {
        ok = false;
        break;
      }
    }
    if (ok) pts.push(c);
    if (attempts % 1500 === 0) d *= 0.85;
  }
  return pts;
}

/**
 * Nearest and second-nearest seeds to (x, y). Their perpendicular bisector is
 * the half-plane boundary between the two Voronoi cells — the exact wall the
 * confirm-slide-shatter clipper would produce — so points solved on it lie on real
 * cell edges without ever chaining polygons.
 */
function nearestPair(seeds: Pt[], x: number, y: number): { a: Pt; b: Pt; ia: number } {
  let ia = 0;
  let ib = 1;
  let da = Infinity;
  let db = Infinity;
  for (let i = 0; i < seeds.length; i++) {
    const s = seeds[i];
    const d = (s.x - x) * (s.x - x) + (s.y - y) * (s.y - y);
    if (d < da) {
      db = da;
      ib = ia;
      da = d;
      ia = i;
    } else if (d < db) {
      db = d;
      ib = i;
    }
  }
  return { a: seeds[ia], b: seeds[ib], ia };
}

// Before/after comparison slider whose divider is a living Voronoi crack seam.
// The seam polyline rides the cell walls nearest the handle, re-jags only when
// the handle crosses a cell, splinters micro-fissures on fast drags, heals
// them on slow ones, and fires a 1px specular glint down the fracture on
// release. Clip-path + canvas are written direct-DOM in one rAF loop that
// sleeps at rest.
export function CrackCompare({
  before = <div className="h-full w-full bg-surface" />,
  after = <div className="h-full w-full bg-background" />,
  initial = 0.5,
  seedCount = 140,
  jag = 18,
  spawnVelocity = 600,
  label = "Comparison position",
  onChange,
  className = "",
}: {
  /** left layer — revealed as the seam moves right */
  before?: ReactNode;
  /** right layer — clipped along the crack seam */
  after?: ReactNode;
  /** initial split position 0..1 */
  initial?: number;
  /** Voronoi seed count feeding the seam's cell walls */
  seedCount?: number;
  /** max horizontal jag of the seam in px */
  jag?: number;
  /** |vx| in px/s above which micro-fissures branch off the seam */
  spawnVelocity?: number;
  /** aria label for the hidden native range input */
  label?: string;
  /** fires on release and keyboard change with the split 0..1 */
  onChange?: (value: number) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const afterRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const dividerRef = useRef<HTMLDivElement>(null);
  const handleRef = useRef<HTMLDivElement>(null);
  const gripRef = useRef<HTMLDivElement>(null);
  const rangeRef = useRef<HTMLInputElement>(null);
  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;

  useEffect(() => {
    const root = rootRef.current;
    const afterEl = afterRef.current;
    const canvas = canvasRef.current;
    const divider = dividerRef.current;
    const handle = handleRef.current;
    const grip = gripRef.current;
    const range = rangeRef.current;
    if (!root || !afterEl || !canvas || !divider || !handle || !grip || !range) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let w = 0;
    let h = 0;
    let prevW = 0;
    let seeds: Pt[] = [];
    let ys: number[] = [];

    const S = {
      x: 0,
      v: 0,
      target: 0,
      dragging: false,
      raf: 0,
      last: 0,
      rectLeft: 0,
      cell: -1,
      offsets: [] as number[],
      goals: [] as number[],
      fissures: [] as Fissure[],
      lastSpawn: 0,
      pendingGlint: false,
      glintStart: -1,
      seamRGB: { r: 255, g: 255, b: 255 },
    };

    /** seam x-offsets (relative to the handle) solved on the local Voronoi walls */
    const seamGoalsFor = (x: number): number[] =>
      ys.map((y) => {
        if (seeds.length < 2) return 0;
        const { a, b } = nearestPair(seeds, x, y);
        const dx = b.x - a.x;
        if (Math.abs(dx) < 0.001) return 0;
        // solve px on the a|b bisector at this y: |p-a| = |p-b|
        const px =
          (b.x * b.x - a.x * a.x + (a.y - b.y) * (2 * y - a.y - b.y)) / (2 * dx);
        return clamp(px - x, -jag, jag);
      });

    const cellAt = (x: number) =>
      seeds.length < 2 ? 0 : nearestPair(seeds, x, h / 2).ia;

    const seamPts = (): Pt[] => ys.map((y, i) => ({ x: S.x + S.offsets[i], y }));

    const syncRange = () => {
      const pct = Math.round((S.x / Math.max(1, w)) * 100);
      if (document.activeElement === range && !S.dragging) return;
      if (range.value !== String(pct)) range.value = String(pct);
    };

    /** stroke a fissure polyline up to maxLen px of arc length */
    const strokePartial = (ox: number, oy: number, pts: Pt[], maxLen: number) => {
      ctx.moveTo(ox, oy);
      let prev: Pt = { x: 0, y: 0 };
      let remaining = maxLen;
      for (const p of pts) {
        const seg = Math.hypot(p.x - prev.x, p.y - prev.y);
        if (seg >= remaining) {
          const f = remaining / seg;
          ctx.lineTo(ox + prev.x + (p.x - prev.x) * f, oy + prev.y + (p.y - prev.y) * f);
          return;
        }
        ctx.lineTo(ox + p.x, oy + p.y);
        prev = p;
        remaining -= seg;
      }
    };

    const pointAt = (pts: Pt[], cum: number[], s: number): Pt => {
      for (let i = 1; i < pts.length; i++) {
        if (cum[i] >= s) {
          const f = (s - cum[i - 1]) / (cum[i] - cum[i - 1] || 1);
          return {
            x: pts[i - 1].x + (pts[i].x - pts[i - 1].x) * f,
            y: pts[i - 1].y + (pts[i].y - pts[i - 1].y) * f,
          };
        }
      }
      return pts[pts.length - 1];
    };

    /** 1px specular dash traveling the settled seam over 450ms */
    const drawGlint = (now: number, pts: Pt[]) => {
      const p = (now - S.glintStart) / GLINT_MS;
      if (p >= 1) {
        S.glintStart = -1;
        return;
      }
      const cum: number[] = [0];
      let total = 0;
      for (let i = 1; i < pts.length; i++) {
        total += Math.hypot(pts[i].x - pts[i - 1].x, pts[i].y - pts[i - 1].y);
        cum.push(total);
      }
      const raw = easeOut(p) * (total + GLINT_LEN);
      const head = clamp(raw, 0, total);
      const tail = clamp(raw - GLINT_LEN, 0, total);
      if (head - tail < 1) return;
      ctx.beginPath();
      const t0 = pointAt(pts, cum, tail);
      ctx.moveTo(t0.x, t0.y);
      for (let i = 1; i < pts.length; i++) {
        if (cum[i] > tail && cum[i] < head) ctx.lineTo(pts[i].x, pts[i].y);
      }
      const t1 = pointAt(pts, cum, head);
      ctx.lineTo(t1.x, t1.y);
      const { r, g, b } = S.seamRGB;
      ctx.lineWidth = 1;
      ctx.strokeStyle = `rgba(${r},${g},${b},0.5)`;
      ctx.stroke();
    };

    const draw = (now: number, pts: Pt[]) => {
      ctx.clearRect(0, 0, w, h);
      if (pts.length < 2) return;
      // seam: hairline + offset ghost stroke for glass depth — token-derived, theme-aware
      const { r, g, b } = S.seamRGB;
      const passes = [
        { o: 0.75, lw: 0.5, c: `rgba(${r},${g},${b},0.10)` },
        { o: 0, lw: 1, c: `rgba(${r},${g},${b},0.32)` },
      ];
      for (const pass of passes) {
        ctx.beginPath();
        ctx.moveTo(pts[0].x + pass.o, pts[0].y + pass.o);
        for (let i = 1; i < pts.length; i++) {
          ctx.lineTo(pts[i].x + pass.o, pts[i].y + pass.o);
        }
        ctx.lineWidth = pass.lw;
        ctx.strokeStyle = pass.c;
        ctx.stroke();
      }
      // micro-fissures: grow fast, retract over 300ms ease-out once slow
      for (const f of S.fissures) {
        const grow = easeOut(Math.min(1, (now - f.born) / GROW_MS));
        const heal = f.retract
          ? 1 - easeOut(Math.min(1, (now - f.retract) / RETRACT_MS))
          : 1;
        const drawn = f.len * grow * heal;
        if (drawn < 0.5) continue;
        ctx.beginPath();
        strokePartial(S.x + f.ox, f.oy, f.pts, drawn);
        ctx.lineWidth = 0.75;
        ctx.strokeStyle = `rgba(${r},${g},${b},${(f.alpha * heal).toFixed(3)})`;
        ctx.stroke();
      }
      if (S.glintStart >= 0) drawGlint(now, pts);
    };

    const applyStatic = () => {
      afterEl.style.clipPath = `inset(0 0 0 ${S.x.toFixed(1)}px)`;
      divider.style.transform = `translateX(${S.x.toFixed(1)}px)`;
      handle.style.transform = `translateX(${(S.x - HANDLE_W / 2).toFixed(2)}px)`;
      syncRange();
    };

    const applyFrame = (now: number) => {
      if (ys.length < 2) return;
      const pts = seamPts();
      let poly = "";
      for (const p of pts) poly += `${p.x.toFixed(1)}px ${p.y.toFixed(1)}px, `;
      afterEl.style.clipPath = `polygon(${poly}${(w + 40).toFixed(0)}px ${(h + 6).toFixed(0)}px, ${(w + 40).toFixed(0)}px -6px)`;
      handle.style.transform = `translateX(${(S.x - HANDLE_W / 2).toFixed(2)}px)`;
      draw(now, pts);
    };

    const spawnFissures = (now: number, speed: number) => {
      S.lastSpawn = now;
      const n = 2 + Math.floor(Math.random() * 3); // 2–4 branches
      const alpha = clamp(0.3 + (speed - spawnVelocity) / 1800, 0.3, 0.85);
      for (let i = 0; i < n && S.fissures.length < 28; i++) {
        const idx = 1 + Math.floor(Math.random() * Math.max(1, ys.length - 2));
        const oy = ys[idx] + (Math.random() - 0.5) * 10;
        const ox = S.offsets[idx] ?? 0;
        const dir = Math.random() < 0.5 ? -1 : 1;
        const len = 30 + Math.random() * 40;
        const a0 = Math.random() * 0.9 - 0.45 + (dir < 0 ? Math.PI : 0);
        const a1 = a0 + (Math.random() * 0.8 - 0.4);
        const l0 = len * (0.4 + Math.random() * 0.3);
        const p1 = { x: Math.cos(a0) * l0, y: Math.sin(a0) * l0 };
        const p2 = { x: p1.x + Math.cos(a1) * (len - l0), y: p1.y + Math.sin(a1) * (len - l0) };
        S.fissures.push({ ox, oy, pts: [p1, p2], len, alpha, born: now, retract: 0 });
      }
    };

    const loop = (now: number) => {
      const dt = Math.min((now - S.last) / 1000, 1 / 30);
      S.last = now;

      // taut spring toward the pointer / keyboard target
      S.v += (SPRING_K * (S.target - S.x) - SPRING_C * S.v) * dt;
      S.x = clamp(S.x + S.v * dt, 0, w);
      const speed = Math.abs(S.v);

      // seam re-jags only when the handle crosses into a new Voronoi cell
      const cell = cellAt(S.x);
      if (cell !== S.cell) {
        S.cell = cell;
        S.goals = seamGoalsFor(S.x);
      }
      const k = 1 - Math.exp(-16 * dt);
      let seamMoving = false;
      for (let i = 0; i < S.offsets.length; i++) {
        S.offsets[i] += (S.goals[i] - S.offsets[i]) * k;
        if (Math.abs(S.goals[i] - S.offsets[i]) > 0.25) seamMoving = true;
      }

      // fast drags splinter, slow drags heal
      if (S.dragging && speed > spawnVelocity && now - S.lastSpawn > 70) {
        spawnFissures(now, speed);
      }
      if (speed < spawnVelocity) {
        for (const f of S.fissures) if (!f.retract) f.retract = now;
      }
      S.fissures = S.fissures.filter(
        (f) => !(f.retract && now - f.retract >= RETRACT_MS)
      );

      const settled = !S.dragging && Math.abs(S.target - S.x) < 0.3 && speed < 4;
      if (settled) {
        S.x = clamp(S.target, 0, w);
        S.v = 0;
        if (S.pendingGlint) {
          S.pendingGlint = false;
          S.glintStart = now;
        }
      }

      applyFrame(now);
      syncRange();

      const alive =
        S.dragging ||
        !settled ||
        seamMoving ||
        S.fissures.length > 0 ||
        S.glintStart >= 0;
      S.raf = alive ? requestAnimationFrame(loop) : 0;
    };

    const wake = () => {
      if (!S.raf) {
        S.last = performance.now();
        S.raf = requestAnimationFrame(loop);
      }
    };

    const build = () => {
      const rect = root.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      if (w < 4 || h < 4) return;
      handle.style.left = "0px";
      handle.style.marginLeft = "0px";
      const frac = prevW > 0 ? S.x / prevW : initial;
      prevW = w;
      S.x = clamp(frac, 0, 1) * w;
      S.target = S.x;
      S.v = 0;
      S.fissures = [];
      S.glintStart = -1;
      S.pendingGlint = false;

      if (reduced) {
        canvas.style.display = "none";
        divider.style.display = "";
        applyStatic();
        return;
      }
      divider.style.display = "none";
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.lineCap = "round";
      ctx.lineJoin = "round";

      const cell = Math.sqrt((w * h) / seedCount);
      seeds = poissonPoints(w, h, seedCount, Math.max(6, cell * 0.72));
      const step = clamp(cell * 0.55, 14, 48);
      ys = [];
      for (let y = -6; y < h + 6; y += step) ys.push(y);
      ys.push(h + 6);

      S.cell = cellAt(S.x);
      S.goals = seamGoalsFor(S.x);
      S.offsets = S.goals.slice();
      S.last = performance.now();
      applyFrame(S.last);
      syncRange();
    };

    const onDown = (e: PointerEvent) => {
      handle.setPointerCapture(e.pointerId);
      S.dragging = true;
      S.rectLeft = root.getBoundingClientRect().left;
      S.target = clamp(e.clientX - S.rectLeft, 0, w);
      if (reduced) {
        S.x = S.target;
        applyStatic();
      } else {
        wake();
      }
    };
    const onMove = (e: PointerEvent) => {
      if (!S.dragging) return;
      S.target = clamp(e.clientX - S.rectLeft, 0, w);
      if (reduced) {
        S.x = S.target;
        applyStatic();
      }
    };
    const onUp = () => {
      if (!S.dragging) return;
      S.dragging = false;
      onChangeRef.current?.(w > 0 ? S.target / w : 0);
      if (!reduced) {
        S.pendingGlint = true;
        wake();
      }
    };

    const onRange = () => {
      S.target = (Number(range.value) / 100) * w;
      if (reduced) {
        S.x = S.target;
        applyStatic();
      } else {
        wake();
      }
      onChangeRef.current?.(Number(range.value) / 100);
    };
    const onFocus = () => {
      if (range.matches(":focus-visible")) {
        grip.classList.add("outline", "outline-2", "outline-offset-2", "outline-ns-accent");
      }
    };
    const onBlur = () => {
      grip.classList.remove("outline", "outline-2", "outline-offset-2", "outline-ns-accent");
    };

    /** re-sample the seam color off the resolved --foreground token so the
     * crack reads on light or dark content alike, then repaint once even at rest */
    const deriveSeamColor = () => {
      const raw = getComputedStyle(document.documentElement).getPropertyValue("--foreground");
      S.seamRGB = parseColor(raw) ?? S.seamRGB;
      if (S.raf) return;
      const pts = seamPts();
      if (pts.length >= 2) draw(performance.now(), pts);
    };
    deriveSeamColor();
    const themeObserver = new MutationObserver(deriveSeamColor);
    themeObserver.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    const ro = new ResizeObserver(build);
    ro.observe(root);
    handle.addEventListener("pointerdown", onDown);
    handle.addEventListener("pointermove", onMove);
    handle.addEventListener("pointerup", onUp);
    handle.addEventListener("pointercancel", onUp);
    range.addEventListener("input", onRange);
    range.addEventListener("focus", onFocus);
    range.addEventListener("blur", onBlur);
    return () => {
      cancelAnimationFrame(S.raf);
      ro.disconnect();
      themeObserver.disconnect();
      handle.removeEventListener("pointerdown", onDown);
      handle.removeEventListener("pointermove", onMove);
      handle.removeEventListener("pointerup", onUp);
      handle.removeEventListener("pointercancel", onUp);
      range.removeEventListener("input", onRange);
      range.removeEventListener("focus", onFocus);
      range.removeEventListener("blur", onBlur);
    };
  }, [initial, seedCount, jag, spawnVelocity]);

  return (
    <div
      ref={rootRef}
      className={`relative aspect-[16/10] w-full select-none overflow-hidden rounded-md border border-border bg-background ${className}`}
    >
      {/* before layer — full bleed */}
      <div className="absolute inset-0">{before}</div>

      {/* after layer — clipped along the crack seam */}
      <div
        ref={afterRef}
        className="absolute inset-0"
        style={{ clipPath: `inset(0 0 0 ${initial * 100}%)` }}
      >
        {after}
      </div>

      {/* hairline crack strokes + glint */}
      <canvas
        ref={canvasRef}
        aria-hidden
        className="pointer-events-none absolute inset-0 h-full w-full"
      />

      {/* straight divider — reduced-motion fallback only */}
      <div
        ref={dividerRef}
        aria-hidden
        className="pointer-events-none absolute inset-y-0 left-0 w-px bg-border"
        style={{ display: "none" }}
      />

      {/* hidden native range for a11y — arrows move 2% per press */}
      <input
        ref={rangeRef}
        type="range"
        min={0}
        max={100}
        step={2}
        defaultValue={Math.round(initial * 100)}
        aria-label={label}
        className="peer sr-only"
      />

      {/* drag handle riding the seam */}
      <div
        ref={handleRef}
        aria-hidden
        className="absolute inset-y-0 flex cursor-ew-resize touch-none items-center justify-center will-change-transform"
        style={{ left: `${initial * 100}%`, width: HANDLE_W, marginLeft: -HANDLE_W / 2 }}
      >
        <div
          ref={gripRef}
          className="flex h-7 w-7 items-center justify-center rounded-sm border border-foreground/15 bg-foreground/10 text-ns-muted shadow-[inset_0_1px_0_0_color-mix(in_srgb,var(--foreground)_18%,transparent),0_2px_8px_-2px_rgba(0,0,0,0.5)] backdrop-blur-md transition-colors duration-150 hover:border-foreground/30 hover:text-foreground"
        >
          <svg
            width="14"
            height="14"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            aria-hidden
          >
            <path d="m9 18-6-6 6-6" />
            <path d="m15 6 6 6-6 6" />
          </svg>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// ReachRuleTable — a tier comparison matrix where each feature row draws a real
// box-drawing rule that starts at the x-centre of the first tier column and
// terminates with ┤ on the x-centre of the LAST tier that includes it. Columns
// the feature skips are drawn ┄ rather than ─, so a non-monotone matrix is
// shown honestly instead of smoothed. The staircase of rule lengths is the
// comparison — there is no field of check glyphs to scan.
// ---------------------------------------------------------------------------

export type CompareTier = {
  id: string;
  /** tier name, e.g. "Pro" */
  name: string;
  /** price string, rendered verbatim — e.g. "$20/mo" or "Custom" */
  price: string;
};

export type CompareFeatureRow = {
  id: string;
  /** feature name — becomes the row's pin button label */
  label: string;
  /** optional second line under the label */
  note?: string;
  /** one entry per tier, in tier order. `false` = not included, a string = the
   *  tier-specific value ("14 days"), `true` = plainly included */
  support: (boolean | string)[];
};

const STEP_IN_MS = 14; // per glyph cell, drawing
const STEP_OUT_MS = 9; // per glyph cell, retracting
const MAX_IN_MS = 320; // total draw budget — long rules step faster, never slower
const REST_OPACITY = 0.42; // resting rule ink — the idle staircase must read
const DIM_OPACITY = 0.35; // tiers excluded by the active row
const TRACK_CELLS = 12; // completeness readout width
const STACK_BREAKPOINT = 720; // px — below this the matrix becomes stacked cards
const WIDTH_EPSILON = 2; // px — remeasure only past this much layout change

const GLYPH_RUN = "─";
const GLYPH_GAP = "┄";
const GLYPH_END = "┤";

const DEFAULT_TIERS: CompareTier[] = [
  { id: "hobby", name: "Hobby", price: "$0" },
  { id: "pro", name: "Pro", price: "$20/mo" },
  { id: "team", name: "Team", price: "$60/mo" },
  { id: "enterprise", name: "Enterprise", price: "Custom" },
];

// Ordered by reach, so the rules descend as a staircase at rest.
const DEFAULT_ROWS: CompareFeatureRow[] = [
  {
    id: "deployments",
    label: "Unlimited deployments",
    support: [true, true, true, true],
  },
  {
    id: "regions",
    label: "Edge regions",
    note: "Where builds are served from",
    support: ["3", "18", "34", "34 + private"],
  },
  {
    id: "analytics",
    label: "Traffic analytics",
    note: "Retention window",
    support: [false, "30 days", "1 year", "3 years"],
  },
  {
    id: "seats",
    label: "Collaborator seats",
    support: ["1", "5", "25", "Unlimited"],
  },
  {
    id: "sso",
    label: "SAML single sign-on",
    support: [false, false, true, true],
  },
  {
    id: "audit",
    label: "Audit log export",
    note: "Streamed to your own bucket",
    support: [false, false, false, true],
  },
  {
    id: "checkout",
    label: "Self-serve checkout",
    note: "Enterprise is invoiced instead",
    support: [true, true, true, false],
  },
  {
    id: "overage",
    label: "Usage overage on card",
    support: [true, true, true, false],
  },
  {
    id: "community",
    label: "Community forum support",
    note: "Superseded by a named contact on Enterprise",
    support: [true, true, true, false],
  },
  {
    id: "trial",
    label: "14-day trial without a card",
    support: [true, true, false, false],
  },
  {
    id: "sandbox",
    label: "Shared sandbox runners",
    note: "Dedicated runners replace these higher up",
    support: [true, true, false, false],
  },
  {
    id: "badge",
    label: "Public project badge",
    note: "Free-tier attribution",
    support: [true, false, false, false],
  },
];

const has = (v: boolean | string | undefined): boolean =>
  v === true || (typeof v === "string" && v.trim().length > 0);

/** highest tier index this feature still appears in, −1 if none */
function reachOf(row: CompareFeatureRow, n: number): number {
  for (let i = n - 1; i >= 0; i--) if (has(row.support[i])) return i;
  return -1;
}

type Geom = { text: string; left: number; width: number; len: number };
type Anim = { dir: 1 | -1; k: number };

export function ReachRuleTable({
  tiers = DEFAULT_TIERS,
  rows = DEFAULT_ROWS,
  title = "Plan comparison",
  className = "",
}: {
  /** tier columns, cheapest first */
  tiers?: CompareTier[];
  /** feature rows, one `support` entry per tier */
  rows?: CompareFeatureRow[];
  /** accessible name for the matrix */
  title?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}) {
  const n = tiers.length;

  const [activeId, setActiveId] = useState<string | null>(null);
  const [pinnedId, setPinnedId] = useState<string | null>(null);
  const [stacked, setStacked] = useState(false);
  const [reduced, setReduced] = useState(false);

  const rootRef = useRef<HTMLDivElement | null>(null);
  const headRowRef = useRef<HTMLDivElement | null>(null);
  const headCellRefs = useRef<(HTMLDivElement | null)[]>([]);
  const probeRef = useRef<HTMLSpanElement | null>(null);
  const ruleRefs = useRef<Map<string, HTMLSpanElement>>(new Map());

  const geomRef = useRef<Map<string, Geom>>(new Map());
  const animRef = useRef<Map<string, Anim>>(new Map());
  const rafRef = useRef(0);
  const lastWidthRef = useRef(-1);
  const pinnedRef = useRef<string | null>(null);
  pinnedRef.current = pinnedId;
  const activeRef = useRef<string | null>(null);
  activeRef.current = activeId;

  const reaches = useMemo(
    () => rows.map((r) => reachOf(r, n)),
    [rows, n]
  );

  // completeness per tier: how many features that tier actually includes
  const included = useMemo(
    () => tiers.map((_, i) => rows.reduce((a, r) => a + (has(r.support[i]) ? 1 : 0), 0)),
    [tiers, rows]
  );

  const gridStyle = useMemo(
    () => ({
      gridTemplateColumns: `minmax(12rem,1.4fr) repeat(${n}, minmax(6rem,1fr))`,
    }),
    [n]
  );

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => setReduced(mq.matches);
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);

  /** body glyphs + the ┤ cap live in two child spans, so the terminator can
   *  take accent ink on a pinned row while the run stays --foreground */
  const parts = (id: string) => {
    const el = ruleRefs.current.get(id);
    if (!el) return null;
    const body = el.firstElementChild as HTMLElement | null;
    const cap = el.lastElementChild as HTMLElement | null;
    if (!body || !cap || body === cap) return null;
    return { el, body, cap };
  };

  /** paint one rule at a given glyph count */
  const paint = useCallback((id: string, k: number) => {
    const p = parts(id);
    const g = geomRef.current.get(id);
    if (!p || !g) return;
    const shown = Math.max(0, Math.min(g.len, Math.round(k)));
    p.body.textContent = shown > 0 ? g.text.slice(0, shown - 1) : "";
    p.cap.textContent = shown > 0 ? GLYPH_END : "";
    p.cap.style.color =
      pinnedRef.current === id ? "var(--ns-accent)" : "currentColor";
    const t = g.len > 0 ? shown / g.len : 1;
    p.el.style.opacity = String(REST_OPACITY + (1 - REST_OPACITY) * t);
  }, []);

  const settle = useCallback((id: string, lit: boolean) => {
    const p = parts(id);
    const g = geomRef.current.get(id);
    if (!p || !g) return;
    p.body.textContent = g.text.slice(0, g.len - 1);
    p.cap.textContent = GLYPH_END;
    p.cap.style.color =
      pinnedRef.current === id ? "var(--ns-accent)" : "currentColor";
    p.el.style.opacity = String(lit ? 1 : REST_OPACITY);
  }, []);

  /** single shared rAF stepping every in-flight rule */
  const tick = useCallback(
    (now: number, prev: number) => {
      const dt = Math.min(64, now - prev);
      const anims = animRef.current;
      for (const [id, a] of anims) {
        const g = geomRef.current.get(id);
        if (!g) {
          anims.delete(id);
          continue;
        }
        const len = Math.max(1, g.len);
        const stepMs =
          a.dir === 1 ? Math.min(STEP_IN_MS, MAX_IN_MS / len) : STEP_OUT_MS;
        a.k += (dt / stepMs) * a.dir;
        if (a.dir === 1 && a.k >= g.len) {
          settle(id, true);
          anims.delete(id);
        } else if (a.dir === -1 && a.k <= 0) {
          settle(id, pinnedRef.current === id);
          anims.delete(id);
        } else {
          paint(id, a.k);
        }
      }
    },
    [paint, settle]
  );

  const pump = useCallback(() => {
    if (rafRef.current) return;
    let prev = performance.now();
    const loop = (now: number) => {
      tick(now, prev);
      prev = now;
      if (animRef.current.size > 0) {
        rafRef.current = requestAnimationFrame(loop);
      } else {
        rafRef.current = 0;
      }
    };
    rafRef.current = requestAnimationFrame(loop);
  }, [tick]);

  const drive = useCallback(
    (id: string, dir: 1 | -1) => {
      const g = geomRef.current.get(id);
      if (!g) return;
      if (reduced) {
        animRef.current.delete(id);
        settle(id, dir === 1 || pinnedRef.current === id);
        return;
      }
      const cur = animRef.current.get(id);
      const k = dir === 1 ? 0 : cur ? cur.k : g.len;
      animRef.current.set(id, { dir, k });
      if (dir === 1) paint(id, 0);
      pump();
    },
    [paint, pump, reduced, settle]
  );

  /** one measurement pass: header centres → per-row rule text + box */
  const layout = useCallback(
    (force: boolean) => {
      const root = rootRef.current;
      const headRow = headRowRef.current;
      if (!root) return;

      const w = root.clientWidth;
      if (w < 2) return;
      if (!force && Math.abs(w - lastWidthRef.current) <= WIDTH_EPSILON) return;
      lastWidthRef.current = w;

      const nextStacked = w < STACK_BREAKPOINT;
      setStacked(nextStacked);
      if (nextStacked || !headRow) return;

      const probe = probeRef.current;
      const chW = probe ? probe.getBoundingClientRect().width / 40 : 8;
      if (!(chW > 0.5)) return;

      const rowLeft = headRow.getBoundingClientRect().left;
      const centres: number[] = [];
      for (let i = 0; i < n; i++) {
        const cell = headCellRefs.current[i];
        if (!cell) return;
        const r = cell.getBoundingClientRect();
        centres.push(r.left + r.width / 2 - rowLeft);
      }

      rows.forEach((row, ri) => {
        const reach = reaches[ri];
        const el = ruleRefs.current.get(row.id);
        if (reach < 0) {
          geomRef.current.delete(row.id);
          const p = el ? parts(row.id) : null;
          if (p) {
            p.body.textContent = "";
            p.cap.textContent = "";
          }
          return;
        }
        const left = centres[0];
        const width = Math.max(0, centres[reach] - left);
        const cells = Math.max(0, Math.round(width / chW));
        let text = "";
        for (let j = 0; j < cells; j++) {
          const x = left + j * chW;
          // nearest tier column owns this glyph
          let col = 0;
          let best = Infinity;
          for (let i = 0; i <= reach; i++) {
            const d = Math.abs(centres[i] - x);
            if (d < best) {
              best = d;
              col = i;
            }
          }
          text += has(row.support[col]) ? GLYPH_RUN : GLYPH_GAP;
        }
        text += GLYPH_END;
        const g: Geom = {
          text,
          left: left - chW / 2,
          width: width + chW,
          len: text.length,
        };
        geomRef.current.set(row.id, g);
        if (el) {
          el.style.left = `${g.left}px`;
          el.style.width = `${g.width}px`;
          if (!animRef.current.has(row.id)) {
            settle(row.id, pinnedRef.current === row.id);
          }
        }
      });
    },
    [n, reaches, rows, settle]
  );

  useEffect(() => {
    layout(true);
    let alive = true;
    // the 1ch probe is measured in whatever font is resolved at mount; when the
    // mono face swaps in the pitch changes, so re-measure once fonts settle or
    // every ┤ lands off its column centre
    if (typeof document !== "undefined" && document.fonts) {
      document.fonts.ready.then(() => {
        if (alive) layout(true);
      });
    }
    const root = rootRef.current;
    if (!root) {
      return () => {
        alive = false;
      };
    }
    const ro = new ResizeObserver(() => layout(false));
    ro.observe(root);
    return () => {
      alive = false;
      ro.disconnect();
    };
  }, [layout]);

  // crossing back above the breakpoint remounts the matrix — the header cells
  // only exist after that paint, so measure once more on the flip
  useEffect(() => {
    if (stacked) return;
    const id = requestAnimationFrame(() => layout(true));
    return () => cancelAnimationFrame(id);
  }, [stacked, layout]);

  useEffect(
    () => () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      rafRef.current = 0;
      animRef.current.clear();
    },
    []
  );

  const enter = (id: string) => {
    activeRef.current = id;
    setActiveId(id);
    drive(id, 1);
  };
  const leave = (id: string) => {
    if (activeRef.current === id) activeRef.current = null;
    setActiveId((cur) => (cur === id ? null : cur));
    if (pinnedRef.current === id) {
      animRef.current.delete(id);
      settle(id, true);
      return;
    }
    drive(id, -1);
  };
  // side effects live in the handler, never inside the state updater — a
  // StrictMode double-invoke would otherwise paint twice
  const togglePin = (id: string) => {
    const prev = pinnedRef.current;
    const next = prev === id ? null : id;
    pinnedRef.current = next;
    setPinnedId(next);
    if (prev && prev !== next) settle(prev, activeRef.current === prev);
    if (next) settle(next, true);
  };

  const activeRow = activeId ? rows.find((r) => r.id === activeId) : undefined;
  const shownRow = activeRow ?? (pinnedId ? rows.find((r) => r.id === pinnedId) : undefined);

  const track = (i: number) => {
    const filled = Math.round((TRACK_CELLS * included[i]) / Math.max(1, rows.length));
    return "▪".repeat(filled) + "·".repeat(Math.max(0, TRACK_CELLS - filled));
  };

  return (
    <div
      ref={rootRef}
      className={`w-full text-foreground ${className}`.trim()}
    >
      {/* mono advance probe — measured, never seen */}
      <span
        ref={probeRef}
        aria-hidden
        className="pointer-events-none absolute -left-[9999px] top-0 font-mono text-[13px] leading-none"
        style={{ whiteSpace: "pre", letterSpacing: 0 }}
      >
        {GLYPH_RUN.repeat(40)}
      </span>

      {stacked ? (
        <div className="flex flex-col gap-3">
          {tiers.map((tier, i) => (
            <section
              key={tier.id}
              aria-label={`${tier.name} — ${tier.price}`}
              className="rounded-md border border-border bg-surface p-4"
            >
              <div className="flex items-baseline justify-between">
                <h3 className="text-sm font-medium">{tier.name}</h3>
                <span className="font-mono text-xs text-ns-muted">{tier.price}</span>
              </div>
              <p className="mt-2 font-mono text-[11px] text-ns-muted">
                <span aria-hidden style={{ letterSpacing: "0.12em" }}>
                  {track(i)}
                </span>
                <span className="ml-2">
                  {included[i]}/{rows.length}
                </span>
              </p>
              <ul className="mt-3 flex flex-col gap-1.5">
                {rows.map((row) => {
                  const on = has(row.support[i]);
                  const val = typeof row.support[i] === "string" ? (row.support[i] as string) : null;
                  return (
                    <li
                      key={row.id}
                      className={`flex items-baseline justify-between gap-3 text-[13px] ${
                        on ? "text-foreground" : "text-ns-muted"
                      }`}
                    >
                      <span className="flex items-baseline gap-2">
                        <span aria-hidden className="font-mono text-[11px]">
                          {on ? "●" : "○"}
                        </span>
                        <span>{row.label}</span>
                        <span className="sr-only">
                          {on ? "included" : "not included"}
                        </span>
                      </span>
                      {val ? (
                        <span className="font-mono text-[11px] text-ns-muted">{val}</span>
                      ) : null}
                    </li>
                  );
                })}
              </ul>
            </section>
          ))}
        </div>
      ) : (
        <div
          role="table"
          aria-label={title}
          className="overflow-hidden rounded-md border border-border bg-surface"
        >
          {/* header */}
          <div
            ref={headRowRef}
            role="row"
            className="grid items-end gap-x-2 border-b border-border px-4 pb-3 pt-4"
            style={gridStyle}
          >
            <div role="columnheader" className="font-mono text-[11px] uppercase tracking-[0.18em] text-ns-muted">
              Feature
            </div>
            {tiers.map((tier, i) => {
              const dim = shownRow ? !has(shownRow.support[i]) : false;
              return (
                <div
                  key={tier.id}
                  role="columnheader"
                  ref={(el) => {
                    headCellRefs.current[i] = el;
                  }}
                  className="text-center transition-opacity duration-200"
                  style={{ opacity: dim ? DIM_OPACITY : 1 }}
                >
                  <div className="text-sm font-medium">{tier.name}</div>
                  <div className="font-mono text-[11px] text-ns-muted">{tier.price}</div>
                  <div className="mt-1.5 font-mono text-[10px] text-ns-muted">
                    <span aria-hidden style={{ letterSpacing: "0.1em" }}>
                      {track(i)}
                    </span>
                    <span className="ml-1.5">
                      {included[i]}/{rows.length}
                    </span>
                  </div>
                </div>
              );
            })}
          </div>

          {/* feature rows */}
          {rows.map((row, ri) => {
            const isActive = activeId === row.id;
            const isPinned = pinnedId === row.id;
            const reach = reaches[ri];
            return (
              <div
                key={row.id}
                role="row"
                className="relative grid items-start gap-x-2 border-b border-border/60 px-4 py-2.5 last:border-b-0"
                style={gridStyle}
              >
                <div role="rowheader" className="min-w-0">
                  <button
                    type="button"
                    data-compare-row={row.id}
                    aria-pressed={isPinned}
                    onPointerEnter={() => enter(row.id)}
                    onPointerLeave={() => leave(row.id)}
                    onFocus={() => enter(row.id)}
                    onBlur={() => leave(row.id)}
                    onClick={() => togglePin(row.id)}
                    className={`-mx-1 block w-full rounded-sm px-1 text-left text-[13px] leading-5 transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent ${
                      isActive || isPinned ? "text-foreground" : "text-foreground/80"
                    }`}
                  >
                    {row.label}
                    {isPinned ? (
                      <span className="sr-only"> (pinned)</span>
                    ) : null}
                  </button>
                  {row.note ? (
                    <p className="mt-0.5 px-0 text-[11px] leading-4 text-ns-muted">
                      {row.note}
                    </p>
                  ) : null}
                </div>

                {tiers.map((tier, i) => {
                  const raw = row.support[i];
                  const on = has(raw);
                  const dim = (isActive || (!activeId && isPinned)) && !on;
                  return (
                    <div
                      key={tier.id}
                      role="cell"
                      className="text-center transition-opacity duration-200"
                      style={{ opacity: dim ? DIM_OPACITY : 1 }}
                    >
                      {/* the rule seats on the row's first line; values hang below it */}
                      <span aria-hidden className="block h-5" />
                      {typeof raw === "string" ? (
                        <span className="block font-mono text-[11px] leading-4 text-ns-muted">
                          {raw}
                        </span>
                      ) : null}
                      <span className="sr-only">
                        {on
                          ? typeof raw === "string"
                            ? raw
                            : "included"
                          : "not included"}
                      </span>
                    </div>
                  );
                })}

                {reach >= 0 ? (
                  <span
                    aria-hidden
                    ref={(el) => {
                      if (el) ruleRefs.current.set(row.id, el);
                      else ruleRefs.current.delete(row.id);
                    }}
                    data-reach-rule={row.id}
                    className="pointer-events-none absolute font-mono text-[13px] leading-none"
                    style={{
                      top: "1.24rem",
                      transform: "translateY(-50%)",
                      whiteSpace: "pre",
                      letterSpacing: 0,
                      overflow: "hidden",
                      opacity: REST_OPACITY,
                      color: "var(--foreground)",
                    }}
                  >
                    <span />
                    <span />
                  </span>
                ) : null}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

export default ReachRuleTable;

"use client";

import {
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type FocusEvent as ReactFocusEvent,
  type KeyboardEvent as ReactKeyboardEvent,
} from "react";

// ---------------------------------------------------------------------------
// PencilHedge — token-level model uncertainty rendered as pencil hesitation.
// A span the model was unsure about gets a 4px hand-hatched underline built
// from ONE shared SVG <pattern> per doubt bucket (sparse / medium /
// cross-hatch — a draftsman going over a line once, twice, or crossed), fed
// by a single generation's logprobs: no resampling, cheap enough for every
// message. The words themselves NEVER change weight, blur or opacity — that
// is the failure mode this design exists to avoid, unlike an ink-reveal
// treatment. Density is a shape channel (line count/angle), not a hue, so it
// reads under every theme and every color-vision deficiency.
//
// Hover or focus on a hatched span opens a small popover (12px / rounded-md)
// listing the runner-up tokens the model almost said as mono rows — "said
// 0.44", "almost 0.31" — each alternative a real button that rewrites the
// span in place with a short settle transition and clears its marks (a
// resolved token reads exactly like a confident one). The popover is a
// plain DOM child of the hatched span itself, not a portal: mouseenter/
// mouseleave don't fire crossing into a descendant, so moving the pointer
// from text down into the popover never flickers it shut, and Tab reaches
// its buttons in natural document order with no focus-stealing hacks.
//
// A11y: the hatched span is role="note" tabIndex=0 with an aria-label
// carrying the doubt — "low confidence: <text>" by default, expanded to
// name the alternatives with percentages when the caller opts a message
// into verbose mode, so default reading flow stays quiet. The popover is
// role="dialog" with an aria-label naming the token it's alternatives-for.
// Escape closes from anywhere (span or popover) and returns focus to the
// span, never trapping. Confident text is never wrapped at all — plain
// text, no role, no tabIndex, nothing to land on.
//
// Colors are the five registry tokens only (--background --foreground
// --ns-muted --border --ns-accent), read as CSS custom properties directly in
// SVG attributes — no canvas here, so no getComputedStyle dance is needed.
// prefers-reduced-motion drops the settle transition; the rewrite still
// happens instantly and is fully legible.
// ---------------------------------------------------------------------------

export type DoubtBucket = "sparse" | "medium" | "cross-hatch";

export type DoubtCandidate = {
  /** the alternative token's text */
  text: string;
  /** probability mass, 0..1 */
  prob: number;
};

export type DoubtToken = {
  /** stable id — used for React keys and internal open/resolved state */
  id: string;
  /** the token text as originally emitted */
  text: string;
  /** hatch density bucket. Omit entirely (use a plain string segment instead) for confident text. */
  bucket: DoubtBucket;
  /** probability of the token actually emitted, 0..1 */
  said: number;
  /** runner-up candidates, ideally sorted by descending prob */
  alternatives: DoubtCandidate[];
};

export type PencilHedgeSegment = string | DoubtToken;

export interface PencilHedgeProps {
  /** Prose as an ordered mix of plain strings (confident text, rendered verbatim) and DoubtToken objects (hatched spans). */
  segments: PencilHedgeSegment[];
  /** Appends a decorative, aria-hidden superscript dagger to the highest-doubt bucket. Default false. */
  daggerOnHighestDoubt?: boolean;
  /** Opts this passage into verbose screen-reader descriptions (names alternatives + percentages). Default false — the terse form. */
  verbose?: boolean;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const SETTLE_MS = 220;
const CLOSE_GRACE_MS = 90;

function pct(prob: number): string {
  return `${Math.round(prob * 100)}%`;
}

function noteLabel(token: DoubtToken, verbose: boolean): string {
  if (!verbose || token.alternatives.length === 0) {
    return `Low confidence: ${token.text}`;
  }
  const alts = token.alternatives.map((a) => `${a.text} ${pct(a.prob)}`).join(", ");
  return `Low confidence: ${token.text}, alternatives ${alts}`;
}

function DoubtSpan({
  token,
  patternPrefix,
  daggerOnHighestDoubt,
  verbose,
  isOpen,
  onOpen,
  onClose,
  registerRef,
}: {
  token: DoubtToken;
  patternPrefix: string;
  daggerOnHighestDoubt: boolean;
  verbose: boolean;
  isOpen: boolean;
  onOpen: (id: string) => void;
  onClose: (id: string) => void;
  registerRef: (id: string, el: HTMLSpanElement | null) => void;
}) {
  const [displayText, setDisplayText] = useState(token.text);
  const [displayBucket, setDisplayBucket] = useState<DoubtBucket | null>(token.bucket);
  const [settling, setSettling] = useState(false);
  const [flipAbove, setFlipAbove] = useState(false);

  const spanRef = useRef<HTMLSpanElement>(null);
  const popoverRef = useRef<HTMLSpanElement>(null);
  const closeTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const uid = useId();
  const dialogId = `${uid}-ph-dialog`;

  useEffect(() => {
    registerRef(token.id, spanRef.current);
    return () => registerRef(token.id, null);
  }, [registerRef, token.id]);

  useEffect(() => {
    return () => {
      if (closeTimer.current) clearTimeout(closeTimer.current);
    };
  }, []);

  // Measure once per open — flip above when there isn't ~130px of room
  // below the span, so the popover doesn't run off the bottom of a short
  // chat viewport.
  useLayoutEffect(() => {
    if (!isOpen || !spanRef.current) return;
    const rect = spanRef.current.getBoundingClientRect();
    const spaceBelow = window.innerHeight - rect.bottom;
    setFlipAbove(spaceBelow < 150 && rect.top > 150);
  }, [isOpen]);

  const openNow = () => {
    if (closeTimer.current) {
      clearTimeout(closeTimer.current);
      closeTimer.current = null;
    }
    if (displayBucket === null) return; // resolved — no more popover
    onOpen(token.id);
  };
  const closeSoon = () => {
    if (closeTimer.current) clearTimeout(closeTimer.current);
    closeTimer.current = setTimeout(() => onClose(token.id), CLOSE_GRACE_MS);
  };

  const selectAlternative = (alt: DoubtCandidate) => {
    setDisplayText(alt.text);
    setDisplayBucket(null);
    setSettling(true);
    onClose(token.id);
    setTimeout(() => setSettling(false), SETTLE_MS);
    // Focus follows the rewrite so the reader never loses their place, but
    // the target is now a plain, non-tabbable node (tabIndex -1) — it's not
    // added back to the Tab sequence, matching "confident text carries no
    // marks" for keyboard users too.
    requestAnimationFrame(() => spanRef.current?.focus({ preventScroll: true }));
  };

  const onKeyDown = (e: ReactKeyboardEvent<HTMLSpanElement>) => {
    if (e.key === "Escape" && isOpen) {
      e.preventDefault();
      onClose(token.id);
      spanRef.current?.focus({ preventScroll: true });
    }
  };

  const onBlur = (e: ReactFocusEvent<HTMLSpanElement>) => {
    const next = e.relatedTarget as Node | null;
    if (next && e.currentTarget.contains(next)) return;
    onClose(token.id);
  };

  if (displayBucket === null) {
    // Resolved (or was always confident, but confident tokens never reach
    // this component at all — see PencilHedge below). Plain text, no marks.
    return (
      <span ref={spanRef} tabIndex={-1} className={settling ? "ns-ph-settle" : undefined}>
        {displayText}
      </span>
    );
  }

  return (
    <span
      ref={spanRef}
      role="note"
      tabIndex={0}
      aria-label={noteLabel({ ...token, text: displayText }, verbose)}
      data-bucket={displayBucket}
      onMouseEnter={openNow}
      onMouseLeave={closeSoon}
      onFocus={openNow}
      onBlur={onBlur}
      onKeyDown={onKeyDown}
      onClick={openNow}
      className="ns-ph-span relative inline-block cursor-default rounded-sm text-[inherit] text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
    >
      {displayText}
      {daggerOnHighestDoubt && displayBucket === "cross-hatch" && (
        <sup aria-hidden className="ml-0.5 select-none text-[0.7em] text-ns-muted">
          †
        </sup>
      )}
      <svg
        aria-hidden
        focusable="false"
        className="pointer-events-none absolute inset-x-0 bottom-[-3px] h-1 w-full"
        viewBox="0 0 100 4"
        preserveAspectRatio="none"
      >
        <rect width="100" height="4" fill={`url(#${patternPrefix}-${displayBucket})`} />
      </svg>

      {isOpen && (
        <span
          ref={popoverRef}
          id={dialogId}
          role="dialog"
          aria-label={`Alternatives for "${token.text}"`}
          onMouseEnter={openNow}
          onMouseLeave={closeSoon}
          style={{ [flipAbove ? "bottom" : "top"]: "100%" }}
          className={[
            "ns-ph-pop absolute left-0 z-10 flex w-max min-w-[9.5rem] max-w-[15rem] flex-col gap-0.5 rounded-md border border-border bg-background p-1.5 font-mono text-xs shadow-lg",
            flipAbove ? "mb-1.5" : "mt-1.5",
          ].join(" ")}
        >
          <span className="flex items-baseline gap-2 px-1 py-0.5">
            <span className="w-12 shrink-0 text-[10px] uppercase tracking-wide text-ns-muted">said</span>
            <span className="truncate text-foreground">{displayText}</span>
            <span className="ml-auto shrink-0 tabular-nums text-ns-muted">{token.said.toFixed(2)}</span>
          </span>
          {token.alternatives.map((alt, i) => (
            <button
              key={`${alt.text}-${i}`}
              type="button"
              onClick={() => selectAlternative(alt)}
              className="flex w-full items-baseline gap-2 rounded-sm px-1 py-0.5 text-left transition-colors duration-150 ease-out hover:bg-foreground/[0.06] focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ns-accent"
            >
              <span className="w-12 shrink-0 text-[10px] uppercase tracking-wide text-ns-muted">
                {i === 0 ? "almost" : ""}
              </span>
              <span className="truncate text-foreground">{alt.text}</span>
              <span className="ml-auto shrink-0 tabular-nums text-ns-muted">{alt.prob.toFixed(2)}</span>
            </button>
          ))}
        </span>
      )}
      <style>{`
.ns-ph-settle{animation:ns-ph-settle-kf ${SETTLE_MS}ms cubic-bezier(0.16,1,0.3,1)}
@keyframes ns-ph-settle-kf{0%{opacity:.45;transform:translateY(-1px) scale(.97)}100%{opacity:1;transform:none}}
.ns-ph-pop{animation:ns-ph-pop-kf 130ms cubic-bezier(0.16,1,0.3,1) both}
@keyframes ns-ph-pop-kf{from{opacity:0;transform:translateY(-2px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion: reduce){.ns-ph-settle,.ns-ph-pop{animation:none}}
`}</style>
    </span>
  );
}

export function PencilHedge({
  segments,
  daggerOnHighestDoubt = false,
  verbose = false,
  className = "",
}: PencilHedgeProps) {
  const uid = useId().replace(/:/g, "");
  const patternPrefix = `ph-${uid}`;
  const [openId, setOpenId] = useState<string | null>(null);
  const refs = useRef(new Map<string, HTMLSpanElement | null>());

  const registerRef = useMemo(
    () => (id: string, el: HTMLSpanElement | null) => {
      refs.current.set(id, el);
    },
    []
  );

  // Escape closes from anywhere — span has focus, popover has focus, or
  // neither (a pure hover-opened popover) — and returns focus to the
  // triggering span so a keyboard user is never dropped onto document.body.
  useEffect(() => {
    if (!openId) return;
    const id = openId;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      e.preventDefault();
      setOpenId(null);
      refs.current.get(id)?.focus({ preventScroll: true });
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [openId]);

  return (
    <span className={`ns-confidence-logprob-hatch ${className}`}>
      {/* One shared <defs> per instance: three diagonal-stroke patterns,
          density escalating sparse -> medium -> cross-hatch, like a
          draftsman going over a line once, then again, then crossed. Every
          stroke is --ns-muted so the hatching survives theme and color-vision
          deficiency as a shape channel, never a hue. */}
      <svg width="0" height="0" aria-hidden focusable="false">
        <defs>
          <pattern id={`${patternPrefix}-sparse`} patternUnits="userSpaceOnUse" width="14" height="4">
            <line x1="0" y1="4" x2="7" y2="0" stroke="var(--ns-muted)" strokeWidth="1" />
          </pattern>
          <pattern id={`${patternPrefix}-medium`} patternUnits="userSpaceOnUse" width="7" height="4">
            <line x1="0" y1="4" x2="7" y2="0" stroke="var(--ns-muted)" strokeWidth="1" />
          </pattern>
          <pattern id={`${patternPrefix}-cross-hatch`} patternUnits="userSpaceOnUse" width="5" height="4">
            <line x1="0" y1="4" x2="5" y2="0" stroke="var(--ns-muted)" strokeWidth="1" />
            <line x1="0" y1="0" x2="5" y2="4" stroke="var(--ns-muted)" strokeWidth="1" />
          </pattern>
        </defs>
      </svg>

      {segments.map((seg, i) =>
        typeof seg === "string" ? (
          <span key={i}>{seg}</span>
        ) : (
          <DoubtSpan
            key={seg.id}
            token={seg}
            patternPrefix={patternPrefix}
            daggerOnHighestDoubt={daggerOnHighestDoubt}
            verbose={verbose}
            isOpen={openId === seg.id}
            onOpen={setOpenId}
            onClose={(id) => setOpenId((cur) => (cur === id ? null : cur))}
            registerRef={registerRef}
          />
        )
      )}
    </span>
  );
}

"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";

// TumblerGate — a destructive-action confirm gated on ACCURACY, the third
// axis besides confirm-hold-ink's time and confirm-slide-shatter's distance. An
// SVG dial carries one rotating notch; it must be turned (drag, wheel, or
// arrow keys) until the notch sits within 3deg of the fixed index mark and
// HELD there for a 400ms dwell — leaving the band before the dwell completes
// is a failed catch: the dial springs out to +8deg like a safe tumbler that
// almost caught and slipped. Completing the dwell spring-snaps to exact
// zero, both ticks thicken to --foreground, and the destructive button arms
// (its one legitimate use of --ns-accent). Because fine-motor precision is
// hostile to some users, an always-visible "type to confirm" disclosure
// offers an equivalent path, and two failed catches auto-expand it. Direct-
// DOM writes on the drag/spring hot path, React state only at the rare
// armed/failed/fallback transitions. Zero deps.

const TOL = 3; // deg — dwell capture band around the index mark
const DWELL_MS = 400;
const STEP = 2; // deg per wheel tick / arrow key
const FRICTION = 0.6; // drag angular delta damping
const SLIP_TARGET = 8; // deg — where a failed catch springs out to
const SNAP_K = 260;
const SNAP_ZETA = 0.85; // one tiny overshoot settling to exact zero
const SLIP_K = 380;
const SLIP_ZETA = 0.55; // stiffer, snappier "give"
const SETTLE_EPS = 0.05; // deg
const V_EPS = 0.3; // deg/s
const FORCE_SETTLE_MS = 700;

function wrapDeg(a: number) {
  let r = a % 360;
  if (r > 180) r -= 360;
  if (r <= -180) r += 360;
  return r;
}

export function TumblerGate({
  destructiveLabel = "Delete organization",
  doneLabel = "Deleted",
  confirmWord = "delete",
  initialAngle = 150,
  onConfirm,
  className = "",
}: {
  /** label shown before confirmation */
  destructiveLabel?: ReactNode;
  /** label shown briefly after confirmation */
  doneLabel?: ReactNode;
  /** word the type-to-confirm fallback checks against, case-insensitive */
  confirmWord?: string;
  /** starting dial offset in degrees from the index mark */
  initialAngle?: number;
  /** called once the dial reaches the confirm mark, or the type-to-confirm word matches */
  onConfirm?: () => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}) {
  const knobRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const notchGroupRef = useRef<SVGGElement>(null);
  const notchLineRef = useRef<SVGLineElement>(null);
  const indexLineRef = useRef<SVGLineElement>(null);

  const [armed, setArmed] = useState(false);
  const [confirmed, setConfirmed] = useState(false);
  const [failedAttempts, setFailedAttempts] = useState(0);
  const [fallbackOpen, setFallbackOpen] = useState(false);
  const [typedValue, setTypedValue] = useState("");
  const [announcement, setAnnouncement] = useState("");

  const armedRef = useRef(false);
  const confirmedRef = useRef(false);
  const dwellingRef = useRef(false);
  const failedRef = useRef(0);
  const fallbackOpenRef = useRef(false);
  const reducedRef = useRef(false);
  const angleRef = useRef(wrapDeg(initialAngle));
  const dwellTimerRef = useRef<ReturnType<typeof setTimeout> | undefined>(
    undefined
  );
  const animRef = useRef<{
    raf: number;
    mode: "snap" | "slip" | null;
    target: number;
    v: number;
    start: number;
  }>({ raf: 0, mode: null, target: 0, v: 0, start: 0 });

  const onConfirmRef = useRef(onConfirm);
  onConfirmRef.current = onConfirm;
  const confirmWordRef = useRef(confirmWord);
  confirmWordRef.current = confirmWord;

  // low-level DOM write: transform + native slider value + aria-valuetext.
  // never touches the dwell/slip state machine — safe to call from the
  // spring animation loop as well as the input handlers.
  const render = (angle: number) => {
    notchGroupRef.current?.setAttribute("transform", `rotate(${angle} 100 100)`);
    const input = inputRef.current;
    if (input && Math.round(input.valueAsNumber) !== Math.round(angle)) {
      input.value = String(angle);
    }
    const rounded = Math.round(angle);
    const text = armedRef.current
      ? "Unlocked"
      : `${Math.abs(rounded)} degree${Math.abs(rounded) === 1 ? "" : "s"} from unlocked`;
    input?.setAttribute("aria-valuetext", text);
  };

  const stopAnim = () => {
    if (animRef.current.raf) cancelAnimationFrame(animRef.current.raf);
    animRef.current.raf = 0;
    animRef.current.mode = null;
  };

  const animateTo = (target: number, mode: "snap" | "slip") => {
    stopAnim();
    if (reducedRef.current) {
      angleRef.current = target;
      render(target);
      return;
    }
    const st = animRef.current;
    st.mode = mode;
    st.target = target;
    st.v = 0;
    st.start = performance.now();
    let last = st.start;
    const k = mode === "snap" ? SNAP_K : SLIP_K;
    const zeta = mode === "snap" ? SNAP_ZETA : SLIP_ZETA;
    const c = 2 * zeta * Math.sqrt(k);
    const step = (now: number) => {
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;
      const x = angleRef.current;
      st.v += (k * (target - x) - c * st.v) * dt;
      const nx = x + st.v * dt;
      angleRef.current = nx;
      render(nx);
      const settled = Math.abs(nx - target) < SETTLE_EPS && Math.abs(st.v) < V_EPS;
      const timedOut = now - st.start > FORCE_SETTLE_MS;
      if (settled || timedOut || st.mode !== mode) {
        angleRef.current = target;
        render(target);
        st.raf = 0;
        st.mode = null;
        return;
      }
      st.raf = requestAnimationFrame(step);
    };
    st.raf = requestAnimationFrame(step);
  };

  const arm = (text: string) => {
    if (armedRef.current) return;
    armedRef.current = true;
    setArmed(true);
    setAnnouncement(text);
    if (notchLineRef.current) {
      notchLineRef.current.style.stroke = "var(--foreground)";
      notchLineRef.current.style.strokeWidth = "3";
    }
    if (indexLineRef.current) {
      indexLineRef.current.style.stroke = "var(--foreground)";
      indexLineRef.current.style.strokeWidth = "3";
    }
  };

  const completeDwell = () => {
    dwellingRef.current = false;
    arm("Aligned, delete enabled.");
    animateTo(0, "snap");
  };

  const triggerSlip = () => {
    const n = failedRef.current + 1;
    failedRef.current = n;
    setFailedAttempts(n);
    if (n >= 2 && !fallbackOpenRef.current) {
      fallbackOpenRef.current = true;
      setFallbackOpen(true);
      setAnnouncement("Two failed attempts. Type to confirm is available.");
    }
    animateTo(SLIP_TARGET, "slip");
  };

  // the dial's state machine — dwell start/cancel/complete. Called only
  // from direct user input (drag, wheel, keyboard), never from the spring
  // animation loop.
  const commit = (newAngle: number) => {
    if (armedRef.current) return;
    angleRef.current = newAngle;
    render(newAngle);
    const within = Math.abs(newAngle) <= TOL;
    if (within) {
      if (!dwellingRef.current) {
        dwellingRef.current = true;
        clearTimeout(dwellTimerRef.current);
        dwellTimerRef.current = setTimeout(completeDwell, DWELL_MS);
      }
    } else if (dwellingRef.current) {
      clearTimeout(dwellTimerRef.current);
      dwellingRef.current = false;
      triggerSlip();
    }
  };

  useEffect(() => {
    const knob = knobRef.current;
    const input = inputRef.current;
    if (!knob || !input) return;

    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    reducedRef.current = mq.matches;
    const onMq = () => {
      reducedRef.current = mq.matches;
    };
    mq.addEventListener("change", onMq);

    const pointerAngleDeg = (e: PointerEvent) => {
      const r = knob.getBoundingClientRect();
      const rad = Math.atan2(
        e.clientY - (r.top + r.height / 2),
        e.clientX - (r.left + r.width / 2)
      );
      return (rad * 180) / Math.PI;
    };

    let dragging = false;
    let lastDeg = 0;

    const onPointerDown = (e: PointerEvent) => {
      if (armedRef.current) return;
      if (e.pointerType === "mouse" && e.button !== 0) return;
      try {
        knob.setPointerCapture(e.pointerId);
      } catch {
        // synthetic pointerId — drag still works without capture
      }
      dragging = true;
      stopAnim();
      lastDeg = pointerAngleDeg(e);
    };
    const onPointerMove = (e: PointerEvent) => {
      if (!dragging || armedRef.current) return;
      const deg = pointerAngleDeg(e);
      const delta = wrapDeg(deg - lastDeg);
      lastDeg = deg;
      commit(wrapDeg(angleRef.current + delta * FRICTION));
    };
    const onPointerEnd = () => {
      dragging = false;
    };
    const onWheel = (e: WheelEvent) => {
      if (armedRef.current) return;
      e.preventDefault();
      stopAnim();
      const dir = e.deltaY > 0 ? -1 : 1;
      commit(wrapDeg(angleRef.current + dir * STEP));
    };
    const onInput = () => {
      if (armedRef.current) {
        input.value = String(angleRef.current);
        return;
      }
      const v = input.valueAsNumber;
      if (Number.isNaN(v)) return;
      stopAnim();
      commit(wrapDeg(v));
    };

    knob.addEventListener("pointerdown", onPointerDown);
    knob.addEventListener("pointermove", onPointerMove);
    knob.addEventListener("pointerup", onPointerEnd);
    knob.addEventListener("pointercancel", onPointerEnd);
    knob.addEventListener("lostpointercapture", onPointerEnd);
    knob.addEventListener("wheel", onWheel, { passive: false });
    input.addEventListener("input", onInput);

    render(angleRef.current);

    return () => {
      mq.removeEventListener("change", onMq);
      knob.removeEventListener("pointerdown", onPointerDown);
      knob.removeEventListener("pointermove", onPointerMove);
      knob.removeEventListener("pointerup", onPointerEnd);
      knob.removeEventListener("pointercancel", onPointerEnd);
      knob.removeEventListener("lostpointercapture", onPointerEnd);
      knob.removeEventListener("wheel", onWheel);
      input.removeEventListener("input", onInput);
      clearTimeout(dwellTimerRef.current);
      stopAnim();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleConfirm = () => {
    if (!armedRef.current || confirmedRef.current) return;
    confirmedRef.current = true;
    setConfirmed(true);
    setAnnouncement("Confirmed.");
    onConfirmRef.current?.();
  };

  const handleTypedChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const v = e.target.value;
    setTypedValue(v);
    if (v.trim().toLowerCase() === confirmWordRef.current.trim().toLowerCase()) {
      arm("Confirmed, delete enabled.");
    }
  };

  return (
    <div className={`flex flex-col items-center gap-6 ${className}`}>
      <div
        ref={knobRef}
        className="tumbler-knob relative h-44 w-44 cursor-grab touch-none select-none rounded-full border border-border bg-surface active:cursor-grabbing focus-within:outline focus-within:outline-2 focus-within:outline-offset-4 focus-within:outline-ns-accent"
      >
        <input
          ref={inputRef}
          type="range"
          role="slider"
          min={-180}
          max={180}
          step={STEP}
          defaultValue={angleRef.current}
          aria-label="Alignment dial"
          className="sr-only"
        />
        <svg viewBox="0 0 200 200" aria-hidden className="absolute inset-0 h-full w-full">
          <circle cx={100} cy={100} r={90} fill="none" stroke="var(--border)" strokeWidth={1.5} />
          <line
            ref={indexLineRef}
            x1={100}
            y1={6}
            x2={100}
            y2={26}
            stroke="var(--border)"
            strokeWidth={2}
            strokeLinecap="round"
          />
          <g ref={notchGroupRef} transform={`rotate(${angleRef.current} 100 100)`}>
            <line
              ref={notchLineRef}
              x1={100}
              y1={14}
              x2={100}
              y2={70}
              stroke="var(--border)"
              strokeWidth={2}
              strokeLinecap="round"
            />
          </g>
          <circle cx={100} cy={100} r={5} fill="var(--surface)" stroke="var(--border)" strokeWidth={1.5} />
        </svg>
      </div>

      <div aria-live="polite" className="sr-only">
        {announcement}
      </div>

      <button
        type="button"
        disabled={!armed || confirmed}
        onClick={handleConfirm}
        className={[
          "rounded-sm border px-5 py-2.5 text-sm font-medium transition-colors duration-150",
          "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent",
          "disabled:cursor-not-allowed disabled:opacity-40",
          armed
            ? "border-ns-accent bg-surface text-foreground enabled:hover:bg-border/60"
            : "border-border bg-surface text-ns-muted",
        ].join(" ")}
      >
        {confirmed ? doneLabel : destructiveLabel}
      </button>

      <details
        className="w-full max-w-xs text-center"
        open={fallbackOpen}
        onToggle={(e) => setFallbackOpen(e.currentTarget.open)}
      >
        <summary
          data-tumbler-toggle=""
          className="cursor-pointer select-none font-mono text-xs uppercase tracking-[0.15em] text-ns-muted underline-offset-4 hover:underline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
        >
          Type to confirm instead
        </summary>
        <div className="mt-3 flex flex-col items-center gap-1.5">
          <label htmlFor="tumbler-confirm-input" className="font-mono text-xs text-ns-muted">
            Type &quot;{confirmWord}&quot; to enable
          </label>
          <input
            id="tumbler-confirm-input"
            data-tumbler-confirm-input=""
            type="text"
            value={typedValue}
            onChange={handleTypedChange}
            autoComplete="off"
            className="w-40 rounded-sm border border-border bg-background px-2 py-1 text-center text-sm text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
          />
        </div>
      </details>

      {failedAttempts > 0 && !armed && (
        <p aria-hidden className="font-mono text-[11px] text-ns-muted">
          {failedAttempts} failed {failedAttempts === 1 ? "attempt" : "attempts"}
        </p>
      )}
    </div>
  );
}

"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";

// Press-and-hold destructive action, redesigned as an ink fill: holding pours
// monochrome ink up from the press point with a live meniscus edge and subtle
// grain; pressure microshake builds near the top; releasing early recoils the
// ink elastically; completion pops with one spring overshoot and swaps the
// label. Canvas colors derive from computed CSS tokens (re-derived on theme
// change), rAF sleeps when settled and pauses offscreen, reduced-motion gets a
// plain clean fill. Direct-DOM on the hot path — React state only at confirm.

type Mode = "idle" | "hold" | "recoil" | "pop";

export function HoldToConfirm({
  children,
  confirmedLabel = "Done",
  holdMs = 1200,
  onConfirm,
  className = "",
}: {
  /** button label shown before confirmation */
  children: ReactNode;
  /** label shown briefly after the hold completes */
  confirmedLabel?: ReactNode;
  /** ms the button must be held before it commits */
  holdMs?: number;
  /** called once the hold completes */
  onConfirm?: () => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}) {
  const btnRef = useRef<HTMLButtonElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [confirmed, setConfirmed] = useState(false);
  const onConfirmRef = useRef(onConfirm);
  onConfirmRef.current = onConfirm;
  const holdMsRef = useRef(holdMs);
  holdMsRef.current = holdMs;

  const stateRef = useRef({
    mode: "idle" as Mode,
    p: 0, // fill progress 0..1
    v: 0, // recoil spring velocity (progress units / s)
    holding: false,
    done: false,
    pressX: 0.5, // normalized press point
    scale: 1,
    sv: 0, // pop spring velocity
    t: 0, // wave clock (ms)
    raf: 0,
    last: 0,
    w: 0,
    h: 0,
    dpr: 1,
    ink: "#ededed",
    grainColor: "#171717",
    reduced: false,
    visible: true,
    noise: null as HTMLCanvasElement | null,
    pattern: null as CanvasPattern | null,
  });

  useEffect(() => {
    const s = stateRef.current;
    const btn = btnRef.current;
    const canvas = canvasRef.current;
    if (!btn || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const makeNoise = () => {
      const n = document.createElement("canvas");
      n.width = 128;
      n.height = 128;
      const nctx = n.getContext("2d");
      if (!nctx) return;
      nctx.fillStyle = s.grainColor;
      for (let i = 0; i < 2400; i++) {
        nctx.globalAlpha = Math.random() * 0.5;
        nctx.fillRect(Math.floor(Math.random() * 128), Math.floor(Math.random() * 128), 1, 1);
      }
      s.noise = n;
      s.pattern = null; // rebuilt lazily against the drawing ctx
    };

    // canvas colors from computed tokens: ink = button text color (foreground),
    // grain = button background (surface) so texture reads inside the ink
    const syncColors = () => {
      const cs = getComputedStyle(btn);
      s.ink = cs.color;
      s.grainColor = cs.backgroundColor;
      makeNoise();
      draw();
    };

    const edgeY = (x: number, level: number) => {
      let y = level;
      // mound welling up at the press point, flattens as the fill matures
      const px = s.pressX * s.w;
      const spread = s.w * (0.1 + 0.9 * s.p);
      const mound = s.h * 1.5 * s.p * (1 - s.p) ** 2;
      y -= mound * Math.exp(-((x - px) ** 2) / (2 * spread * spread));
      // rippling waterline + pressure swell near the top
      const press = Math.min(1, Math.max(0, (s.p - 0.6) / 0.4));
      const live = s.holding ? 1.6 : Math.min(3, Math.abs(s.v) * 2.5);
      const amp = 1.2 + 2.6 * press + live;
      y += amp * 0.6 * Math.sin(x * 0.085 + s.t * 0.012);
      y += amp * 0.4 * Math.sin(x * 0.041 - s.t * 0.0085);
      return y;
    };

    const draw = () => {
      const { w, h, dpr } = s;
      if (!w || !h) return;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      if (s.p <= 0.001) return;
      ctx.fillStyle = s.ink;
      if (s.p >= 0.999 || s.reduced) {
        // reduced motion: simple clean fill, no meniscus, no grain
        ctx.fillRect(0, h * (1 - s.p), w, h * s.p + 1);
        if (s.reduced) return;
      } else {
        const level = h * (1 - s.p);
        ctx.beginPath();
        ctx.moveTo(0, h + 2);
        for (let x = 0; x <= w; x += 3) ctx.lineTo(x, edgeY(x, level));
        ctx.lineTo(w, edgeY(w, level));
        ctx.lineTo(w, h + 2);
        ctx.closePath();
        ctx.fill();
      }
      // grain, clipped to the ink via source-atop
      if (s.noise) {
        if (!s.pattern) s.pattern = ctx.createPattern(s.noise, "repeat");
        if (s.pattern) {
          ctx.globalCompositeOperation = "source-atop";
          ctx.globalAlpha = 0.12;
          ctx.fillStyle = s.pattern;
          ctx.fillRect(0, 0, w, h);
          ctx.globalAlpha = 1;
          ctx.globalCompositeOperation = "source-over";
        }
      }
    };

    const applyTransform = () => {
      if (s.mode === "hold") {
        const press = Math.min(1, Math.max(0, (s.p - 0.6) / 0.4));
        const j = s.reduced ? 0 : press * press * 1.6;
        const jx = (Math.random() - 0.5) * 2 * j;
        const jy = (Math.random() - 0.5) * 2 * j;
        btn.style.transform = `translate(${jx.toFixed(2)}px, ${jy.toFixed(2)}px) scale(0.985)`;
      } else if (s.mode === "recoil") {
        const squash = 1 - 0.015 * Math.min(1, s.p * 3);
        btn.style.transform = `scale(${squash.toFixed(4)})`;
      } else if (s.mode === "pop") {
        btn.style.transform = `scale(${s.scale.toFixed(4)})`;
      } else {
        btn.style.transform = "";
      }
    };

    const settle = () => {
      s.mode = "idle";
      s.raf = 0;
      applyTransform();
      draw();
    };

    const confirm = () => {
      s.p = 1;
      s.done = true;
      s.holding = false;
      if (s.reduced) {
        s.mode = "idle";
      } else {
        s.mode = "pop";
        s.scale = 0.97;
        s.sv = 0.6;
      }
      setConfirmed(true);
      onConfirmRef.current?.();
    };

    const tick = (now: number) => {
      const rawMs = now - s.last; // wall time, keeps hold duration honest across frame stalls
      const dtMs = Math.min(64, rawMs); // clamped for springs/waves so physics can't blow up
      s.last = now;
      const dt = dtMs / 1000;
      s.t += dtMs;

      if (s.mode === "hold") {
        s.p += rawMs / holdMsRef.current;
        if (s.p >= 1) confirm();
      } else if (s.mode === "recoil") {
        if (s.reduced) {
          s.p -= (dtMs / holdMsRef.current) * 2.5;
          if (s.p <= 0) {
            s.p = 0;
            draw();
            return settle();
          }
        } else {
          // elastic recoil: damped spring toward 0, bounce at the floor
          s.v += (-220 * s.p - 16 * s.v) * dt;
          s.p += s.v * dt;
          if (s.p <= 0) {
            s.p = 0;
            s.v = -s.v * 0.3;
          }
          if (s.p < 0.008 && Math.abs(s.v) < 0.2) {
            s.p = 0;
            draw();
            return settle();
          }
        }
      } else if (s.mode === "pop") {
        s.sv += ((1 - s.scale) * 300 - 12 * s.sv) * dt;
        s.scale += s.sv * dt;
        if (Math.abs(s.scale - 1) < 0.001 && Math.abs(s.sv) < 0.01) {
          s.scale = 1;
          draw();
          return settle();
        }
      } else {
        return settle();
      }

      draw();
      applyTransform();
      if (s.visible) {
        s.raf = requestAnimationFrame(tick);
      } else {
        s.raf = 0;
      }
    };

    const wake = () => {
      if (s.raf || s.mode === "idle" || !s.visible) return;
      s.last = performance.now();
      s.raf = requestAnimationFrame(tick);
    };

    const startHold = (pressX: number) => {
      if (s.done || s.mode === "pop") return;
      s.holding = true;
      s.mode = "hold";
      s.pressX = pressX;
      s.v = 0;
      wake();
    };

    const release = () => {
      if (!s.holding || s.done) return;
      s.holding = false;
      if (s.p > 0) {
        s.mode = "recoil";
        s.v = -1.2; // initial elastic kick downward
        wake();
      } else {
        s.mode = "idle";
        applyTransform();
      }
    };

    // wire input through the element so cleanup is guaranteed
    const onPointerDown = (e: PointerEvent) => {
      btn.setPointerCapture(e.pointerId);
      const r = btn.getBoundingClientRect();
      startHold(r.width ? (e.clientX - r.left) / r.width : 0.5);
    };
    const onPointerEnd = () => release();
    const onKeyDown = (e: KeyboardEvent) => {
      if ((e.key === " " || e.key === "Enter") && !e.repeat) {
        e.preventDefault();
        startHold(0.5);
      }
    };
    const onKeyUp = (e: KeyboardEvent) => {
      if (e.key === " " || e.key === "Enter") release();
    };
    btn.addEventListener("pointerdown", onPointerDown);
    btn.addEventListener("pointerup", onPointerEnd);
    btn.addEventListener("pointercancel", onPointerEnd);
    btn.addEventListener("lostpointercapture", onPointerEnd);
    btn.addEventListener("keydown", onKeyDown);
    btn.addEventListener("keyup", onKeyUp);
    btn.addEventListener("blur", onPointerEnd);

    const ro = new ResizeObserver(() => {
      const r = btn.getBoundingClientRect();
      s.w = r.width;
      s.h = r.height;
      s.dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.max(1, Math.round(s.w * s.dpr));
      canvas.height = Math.max(1, Math.round(s.h * s.dpr));
      draw();
    });
    ro.observe(btn);

    const io = new IntersectionObserver(([entry]) => {
      s.visible = entry.isIntersecting;
      if (s.visible) wake();
      else if (s.raf) {
        cancelAnimationFrame(s.raf);
        s.raf = 0;
      }
    });
    io.observe(btn);

    const mo = new MutationObserver(syncColors);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const onMq = () => {
      s.reduced = mq.matches;
      draw();
    };
    onMq();
    mq.addEventListener("change", onMq);

    syncColors();

    return () => {
      cancelAnimationFrame(s.raf);
      s.raf = 0;
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      mq.removeEventListener("change", onMq);
      btn.removeEventListener("pointerdown", onPointerDown);
      btn.removeEventListener("pointerup", onPointerEnd);
      btn.removeEventListener("pointercancel", onPointerEnd);
      btn.removeEventListener("lostpointercapture", onPointerEnd);
      btn.removeEventListener("keydown", onKeyDown);
      btn.removeEventListener("keyup", onKeyUp);
      btn.removeEventListener("blur", onPointerEnd);
    };
  }, []);

  return (
    <button
      ref={btnRef}
      type="button"
      className={[
        "ns-chi-btn relative isolate inline-flex select-none touch-none items-center justify-center overflow-hidden",
        "rounded-sm border border-border bg-surface px-5 py-2.5 text-sm font-medium text-foreground",
        "hover:border-ns-muted hover:bg-border/60",
        "transition-[border-color,background-color] duration-150",
        "focus:border-ns-accent focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent",
        className,
      ].join(" ")}
    >
      <canvas ref={canvasRef} aria-hidden className="pointer-events-none absolute inset-0 h-full w-full" />
      {/* difference blend inverts the label wherever the ink covers it */}
      <span className="relative z-10" style={{ mixBlendMode: "difference", color: "#fff" }}>
        {confirmed ? confirmedLabel : children}
      </span>
    </button>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

type Pt = { x: number; y: number };
type Edge = { ax: number; ay: number; bx: number; by: number; t: number };
type Shard = {
  poly: Pt[];
  cx: number;
  cy: number;
  ox: number;
  oy: number;
  vx: number;
  vy: number;
  rot: number;
  vr: number;
};

const INSET = 4;
const RADIUS = 12;
// canvas bleeds past the track so shards can tumble out of frame
const PAD_X = 160;
const PAD_TOP = 120;
const PAD_BOTTOM = 320;
const COMMIT_AT = 0.98;
const SHATTER_MS = 900;
const FADE_MS = 700;
const KEY_STEP = 0.08;

/** dart-throwing Poisson disc — relaxes min distance if the pane is crowded */
function poissonPoints(w: number, h: number, count: number, minDist: number): Pt[] {
  const pts: Pt[] = [];
  let d = minDist;
  let attempts = 0;
  while (pts.length < count && attempts < 6000) {
    attempts++;
    const c = { x: Math.random() * w, y: Math.random() * h };
    let ok = true;
    for (const q of pts) {
      const dx = q.x - c.x;
      const dy = q.y - c.y;
      if (dx * dx + dy * dy < d * d) {
        ok = false;
        break;
      }
    }
    if (ok) pts.push(c);
    if (attempts % 1500 === 0) d *= 0.85;
  }
  return pts;
}

/** keep the part of `poly` on the seed's side of the bisector (dot(p-m, n) <= 0) */
function clipHalfPlane(poly: Pt[], mx: number, my: number, nx: number, ny: number): Pt[] {
  const out: Pt[] = [];
  for (let i = 0; i < poly.length; i++) {
    const a = poly[i];
    const b = poly[(i + 1) % poly.length];
    const da = (a.x - mx) * nx + (a.y - my) * ny;
    const db = (b.x - mx) * nx + (b.y - my) * ny;
    if (da <= 0) out.push(a);
    if (da <= 0 !== db <= 0) {
      const f = da / (da - db);
      out.push({ x: a.x + (b.x - a.x) * f, y: a.y + (b.y - a.y) * f });
    }
  }
  return out;
}

/** exact Voronoi cells via half-plane clipping — O(n²), computed once at mount */
function voronoiCells(seeds: Pt[], w: number, h: number): Pt[][] {
  return seeds
    .map((s) => {
      let poly: Pt[] = [
        { x: 0, y: 0 },
        { x: w, y: 0 },
        { x: w, y: h },
        { x: 0, y: h },
      ];
      for (const o of seeds) {
        if (o === s) continue;
        poly = clipHalfPlane(poly, (s.x + o.x) / 2, (s.y + o.y) / 2, o.x - s.x, o.y - s.y);
        if (poly.length === 0) break;
      }
      return poly;
    })
    .filter((poly) => poly.length >= 3);
}

/** dedupe shared cell walls into crack polylines, each with a reveal threshold */
function crackEdges(cells: Pt[][], w: number, h: number, ox: number, oy: number): Edge[] {
  const eps = 0.5;
  const maxD = Math.hypot(w - ox, Math.max(oy, h - oy));
  const seen = new Set<string>();
  const edges: Edge[] = [];
  for (const poly of cells) {
    for (let i = 0; i < poly.length; i++) {
      const a = poly[i];
      const b = poly[(i + 1) % poly.length];
      // the pane's own border is a frame, not a crack
      if (
        (a.x < eps && b.x < eps) ||
        (a.x > w - eps && b.x > w - eps) ||
        (a.y < eps && b.y < eps) ||
        (a.y > h - eps && b.y > h - eps)
      )
        continue;
      const ka = `${a.x.toFixed(1)},${a.y.toFixed(1)}`;
      const kb = `${b.x.toFixed(1)},${b.y.toFixed(1)}`;
      const key = ka < kb ? `${ka}|${kb}` : `${kb}|${ka}`;
      if (seen.has(key)) continue;
      seen.add(key);
      const da = Math.hypot(a.x - ox, a.y - oy);
      const db = Math.hypot(b.x - ox, b.y - oy);
      const near = da <= db ? a : b;
      const far = da <= db ? b : a;
      // map raw distance into [0.04, 0.86] so every crack finishes growing by p≈0.98
      const t = 0.04 + 0.82 * (Math.min(da, db) / maxD);
      edges.push({ ax: near.x, ay: near.y, bx: far.x, by: far.y, t });
    }
  }
  return edges;
}

function roundedRectPath(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  r: number
) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

// Frosted-glass confirm slider: drag distance IS crack density. Voronoi
// fractures spider from the thumb, heal on a spring if released early, and at
// full travel the pane explodes into tumbling shards revealing the confirmed
// state. Progress lives in refs; all drawing is direct-DOM/canvas in one rAF
// loop that sleeps when settled.
export function SlideToShatter({
  label = "SLIDE TO CONFIRM",
  confirmedLabel = "CONFIRMED",
  width = 320,
  height = 56,
  shardCount = 48,
  onConfirm,
  resetKey = 0,
  className = "",
}: {
  /** mono label etched on the glass */
  label?: string;
  /** label revealed once the pane shatters */
  confirmedLabel?: string;
  /** px width of the glass pane */
  width?: number;
  /** px height of the glass pane */
  height?: number;
  /** approximate Voronoi cell count — cracks while dragging, shards on commit */
  shardCount?: number;
  /** called once the pane fully shatters */
  onConfirm?: () => void;
  /** bump to restore the pane and replay */
  resetKey?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const glassRef = useRef<HTMLDivElement>(null);
  const thumbRef = useRef<HTMLButtonElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [confirmed, setConfirmed] = useState(false);
  const onConfirmRef = useRef(onConfirm);
  onConfirmRef.current = onConfirm;

  useEffect(() => {
    const root = rootRef.current;
    const glass = glassRef.current;
    const thumb = thumbRef.current;
    const canvas = canvasRef.current;
    if (!root || !glass || !thumb || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    // reset pane state (also runs on resetKey bump)
    setConfirmed(false);
    glass.style.visibility = "";
    thumb.style.visibility = "";
    thumb.style.transform = "translateX(0px)";
    thumb.setAttribute("aria-valuenow", "0");
    root.style.transform = "";

    const thumbSize = height - INSET * 2;
    const maxTravel = width - INSET * 2 - thumbSize;
    const cw = width + PAD_X * 2;
    const ch = height + PAD_TOP + PAD_BOTTOM;

    // geometry: one Poisson + Voronoi pass, reused as cracks AND shards
    const originX = INSET + thumbSize / 2;
    const originY = height / 2;
    const seeds = reduced
      ? []
      : poissonPoints(
          width,
          height,
          shardCount,
          Math.max(8, Math.sqrt((width * height) / shardCount) * 0.72)
        );
    const cells = voronoiCells(seeds, width, height);
    const edges = crackEdges(cells, width, height, originX, originY);

    if (!reduced) {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.round(cw * dpr);
      canvas.height = Math.round(ch * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, PAD_X * dpr, PAD_TOP * dpr);
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      ctx.clearRect(-PAD_X, -PAD_TOP, cw, ch);
    }

    const S = {
      p: 0,
      v: 0,
      dragging: false,
      mode: "idle" as "idle" | "drag" | "spring" | "shatter",
      raf: 0,
      last: 0,
      startX: 0,
      startP: 0,
      shatterStart: 0,
      shards: [] as Shard[],
    };

    const setThumb = (p: number) => {
      thumb.style.transform = `translateX(${p * maxTravel}px)`;
    };

    const drawCracks = (p: number) => {
      ctx.clearRect(-PAD_X, -PAD_TOP, cw, ch);
      if (p <= 0) return;
      ctx.save();
      roundedRectPath(ctx, 0.5, 0.5, width - 1, height - 1, RADIUS);
      ctx.clip();
      // two passes: hairline + offset ghost stroke for glass depth
      const passes = [
        { dx: 0.75, dy: 0.75, w: 0.5, c: "rgba(255,255,255,0.12)" },
        { dx: 0, dy: 0, w: 1, c: "rgba(255,255,255,0.35)" },
      ];
      for (const pass of passes) {
        ctx.beginPath();
        for (const e of edges) {
          if (p <= e.t) continue;
          // cracks grow segment-by-segment from the near end outward
          const f = Math.min(1, (p - e.t) / 0.12);
          ctx.moveTo(e.ax + pass.dx, e.ay + pass.dy);
          ctx.lineTo(e.ax + (e.bx - e.ax) * f + pass.dx, e.ay + (e.by - e.ay) * f + pass.dy);
        }
        ctx.lineWidth = pass.w;
        ctx.strokeStyle = pass.c;
        ctx.stroke();
      }
      ctx.restore();
    };

    const buildShards = (): Shard[] => {
      const tx = width - INSET - thumbSize / 2;
      const ty = height / 2;
      return cells.map((poly) => {
        let cx = 0;
        let cy = 0;
        for (const pt of poly) {
          cx += pt.x;
          cy += pt.y;
        }
        cx /= poly.length;
        cy /= poly.length;
        let dx = cx - tx;
        let dy = cy - ty;
        const d = Math.hypot(dx, dy);
        if (d < 1) {
          const a = Math.random() * Math.PI * 2;
          dx = Math.cos(a);
          dy = Math.sin(a);
        } else {
          dx /= d;
          dy /= d;
        }
        const speed = 120 + Math.random() * 300;
        return {
          poly: poly.map((pt) => ({ x: pt.x - cx, y: pt.y - cy })),
          cx,
          cy,
          ox: 0,
          oy: 0,
          vx: dx * speed,
          vy: dy * speed,
          rot: 0,
          vr: (Math.random() * 2 - 1) * 3,
        };
      });
    };

    const stepShards = (dt: number) => {
      for (const s of S.shards) {
        s.vy += 1800 * dt;
        s.ox += s.vx * dt;
        s.oy += s.vy * dt;
        s.rot += s.vr * dt;
      }
    };

    const drawShards = (elapsed: number) => {
      ctx.clearRect(-PAD_X, -PAD_TOP, cw, ch);
      const alpha = Math.max(0, 1 - elapsed / FADE_MS);
      if (alpha <= 0) return;
      for (const s of S.shards) {
        ctx.save();
        ctx.translate(s.cx + s.ox, s.cy + s.oy);
        ctx.rotate(s.rot);
        ctx.globalAlpha = alpha;
        ctx.beginPath();
        for (let i = 0; i < s.poly.length; i++) {
          const pt = s.poly[i];
          if (i === 0) ctx.moveTo(pt.x, pt.y);
          else ctx.lineTo(pt.x, pt.y);
        }
        ctx.closePath();
        ctx.fillStyle = "rgba(255,255,255,0.10)";
        ctx.fill();
        ctx.lineWidth = 1;
        ctx.strokeStyle = "rgba(255,255,255,0.4)";
        ctx.stroke();
        ctx.restore();
      }
    };

    const wake = () => {
      if (!S.raf) {
        S.last = performance.now();
        S.raf = requestAnimationFrame(loop);
      }
    };

    const commit = () => {
      S.dragging = false;
      S.p = 1;
      setThumb(1);
      thumb.setAttribute("aria-valuenow", "100");
      // the pane is gone the instant it breaks
      glass.style.visibility = "hidden";
      thumb.style.visibility = "hidden";
      root.style.transform = "";
      setConfirmed(true);
      if (!reduced) {
        S.mode = "shatter";
        S.shatterStart = performance.now();
        S.shards = buildShards();
        wake();
      } else {
        S.mode = "idle";
      }
      onConfirmRef.current?.();
    };

    const loop = (now: number) => {
      const dt = Math.min((now - S.last) / 1000, 1 / 30);
      S.last = now;
      let alive = false;
      if (S.mode === "drag") {
        if (S.p >= COMMIT_AT) {
          commit();
          alive = true;
        } else {
          const p = S.p;
          setThumb(p);
          drawCracks(p);
          // structural shudder once the pane is badly cracked
          root.style.transform =
            p > 0.6
              ? `translate(${Math.random() - 0.5}px, ${Math.random() - 0.5}px)`
              : "";
          alive = true;
        }
      } else if (S.mode === "spring") {
        // stiffness 220 / damping 26 — slightly underdamped, tiny overshoot
        S.v += (-220 * S.p - 26 * S.v) * dt;
        S.p += S.v * dt;
        if (Math.abs(S.p) < 0.001 && Math.abs(S.v) < 0.01) {
          S.p = 0;
          S.v = 0;
          S.mode = "idle";
          setThumb(0);
          drawCracks(0);
          root.style.transform = "";
        } else {
          const p = Math.max(0, S.p);
          setThumb(p);
          drawCracks(p); // same t-mapping in reverse — the heal is free
          root.style.transform = "";
          alive = true;
        }
      } else if (S.mode === "shatter") {
        const elapsed = now - S.shatterStart;
        if (elapsed >= SHATTER_MS) {
          ctx.clearRect(-PAD_X, -PAD_TOP, cw, ch);
          S.mode = "idle";
        } else {
          stepShards(dt);
          drawShards(elapsed);
          alive = true;
        }
      }
      S.raf = alive ? requestAnimationFrame(loop) : 0;
    };

    const onDown = (e: PointerEvent) => {
      if (S.mode === "shatter" || glass.style.visibility === "hidden") return;
      thumb.setPointerCapture(e.pointerId);
      S.dragging = true;
      S.mode = "drag";
      S.v = 0;
      S.startX = e.clientX;
      S.startP = S.p;
      if (!reduced) wake();
    };

    const onMove = (e: PointerEvent) => {
      if (!S.dragging) return;
      S.p = Math.min(1, Math.max(0, S.startP + (e.clientX - S.startX) / maxTravel));
      if (reduced) {
        // no canvas at all — plain slide, instant swap at full travel
        setThumb(S.p);
        if (S.p >= COMMIT_AT) commit();
      }
    };

    const onUp = () => {
      if (!S.dragging) return;
      S.dragging = false;
      if (S.p >= COMMIT_AT) {
        if (S.mode !== "shatter") commit();
        return;
      }
      thumb.setAttribute("aria-valuenow", "0");
      if (reduced) {
        S.p = 0;
        S.mode = "idle";
        setThumb(0);
      } else {
        S.mode = "spring";
        wake();
      }
    };

    // Arrow keys nudge p by KEY_STEP; Home/End jump to the ends; Enter/Space
    // confirms outright — mirrors the pointer path without engaging the rAF
    // loop for a static value (loop only wakes once travel actually commits).
    const onKeyDown = (e: KeyboardEvent) => {
      if (S.mode === "shatter" || S.mode === "spring" || glass.style.visibility === "hidden") return;
      let next: number;
      switch (e.key) {
        case "ArrowRight":
        case "ArrowUp":
          next = S.p + KEY_STEP;
          break;
        case "ArrowLeft":
        case "ArrowDown":
          next = S.p - KEY_STEP;
          break;
        case "Home":
          next = 0;
          break;
        case "End":
        case "Enter":
        case " ":
          next = 1;
          break;
        default:
          return;
      }
      e.preventDefault();
      next = Math.min(1, Math.max(0, next));
      S.p = next;
      S.startP = next;
      thumb.setAttribute("aria-valuenow", String(Math.round(next * 100)));
      if (S.p >= COMMIT_AT) {
        commit();
      } else {
        S.mode = "idle";
        setThumb(S.p);
        if (!reduced) drawCracks(S.p);
      }
    };

    thumb.addEventListener("pointerdown", onDown);
    thumb.addEventListener("pointermove", onMove);
    thumb.addEventListener("pointerup", onUp);
    thumb.addEventListener("pointercancel", onUp);
    thumb.addEventListener("keydown", onKeyDown);
    return () => {
      cancelAnimationFrame(S.raf);
      thumb.removeEventListener("pointerdown", onDown);
      thumb.removeEventListener("pointermove", onMove);
      thumb.removeEventListener("pointerup", onUp);
      thumb.removeEventListener("pointercancel", onUp);
      thumb.removeEventListener("keydown", onKeyDown);
      root.style.transform = "";
    };
  }, [width, height, shardCount, resetKey]);

  const thumbSize = height - INSET * 2;

  return (
    <div
      ref={rootRef}
      className={`relative select-none ${className}`}
      style={{ width, height }}
    >
      {/* revealed state beneath the glass */}
      <div
        aria-hidden={!confirmed}
        className={`absolute inset-0 flex items-center justify-center gap-2 rounded-md border border-border bg-surface ${
          confirmed ? "opacity-100" : "opacity-0"
        }`}
      >
        <svg
          width="16"
          height="16"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          aria-hidden
          className="text-foreground"
        >
          <path d="M20 6 9 17l-5-5" />
        </svg>
        <span className="font-mono text-xs tracking-[0.2em] text-foreground">
          {confirmedLabel}
        </span>
      </div>

      {/* frosted pane — house glass recipe */}
      <div
        ref={glassRef}
        className={`absolute inset-0 overflow-hidden rounded-md border border-black/15 bg-white/60 shadow-[inset_0_1px_0_0_rgba(255,255,255,0.7),0_8px_24px_-8px_rgba(0,0,0,0.28)] backdrop-blur-xl backdrop-saturate-150 dark:border-white/10 dark:bg-white/[0.06] dark:shadow-[inset_0_1px_0_0_rgba(255,255,255,0.12),0_8px_24px_-8px_rgba(0,0,0,0.5)] ${
          confirmed ? "invisible" : ""
        }`}
      >
        <span className="absolute inset-0 flex items-center justify-center pl-8 font-mono text-[11px] tracking-[0.25em] text-ns-muted">
          {label}
        </span>
      </div>

      {/* crack + shard overlay, bleeds past the track so shards can fly */}
      <canvas
        ref={canvasRef}
        aria-hidden
        className="pointer-events-none absolute"
        style={{
          left: -PAD_X,
          top: -PAD_TOP,
          width: width + PAD_X * 2,
          height: height + PAD_TOP + PAD_BOTTOM,
        }}
      />

      {/* thumb */}
      <button
        ref={thumbRef}
        type="button"
        role="slider"
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={0}
        className={`absolute flex cursor-grab touch-none items-center justify-center rounded-sm border border-black/15 bg-black/[0.04] text-ns-muted transition-colors duration-150 hover:border-black/25 hover:bg-black/[0.08] hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background shadow-[inset_0_1px_0_0_rgba(255,255,255,0.6),0_2px_8px_-2px_rgba(0,0,0,0.25)] will-change-transform active:cursor-grabbing dark:border-white/15 dark:bg-white/10 dark:hover:border-white/30 dark:hover:bg-white/15 dark:shadow-[inset_0_1px_0_0_rgba(255,255,255,0.18),0_2px_8px_-2px_rgba(0,0,0,0.5)] ${
          confirmed ? "invisible" : ""
        }`}
        style={{ left: INSET, top: INSET, width: thumbSize, height: thumbSize }}
      >
        <svg
          width="16"
          height="16"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          aria-hidden
        >
          <path d="m6 17 5-5-5-5" />
          <path d="m13 17 5-5-5-5" />
        </svg>
      </button>
    </div>
  );
}

"use client";

import { useId, useState } from "react";

/** One sharing scope, rendered as a real switch. Toggling it redacts/reveals every token tagged with its `id`. */
export interface LampBlackScope {
  id: string;
  /** Visible + accessible label for the switch, e.g. "Location". */
  label: string;
  /** Optional one-line clarifier under the label. */
  hint?: string;
  /** Whether this scope is shared (visible) at mount. Defaults to true. */
  defaultShared?: boolean;
}

/** A redactable span of the record — literal text tied to a scope. */
export interface LampBlackToken {
  /** Literal text of this token exactly as it appears in the record. */
  text: string;
  /** Which scope's switch controls this token. Must match a `LampBlackScope.id`. */
  scope: string;
  /** Short noun used in the a11y string "[withheld: kind]" — defaults to `scope`. */
  kind?: string;
}

/** A part of the templated sentence: plain connective text, or a token tied to a scope. */
export type LampBlackPart = string | LampBlackToken;

export interface LampBlackProps {
  /** The switches — one per sharing scope. */
  scopes: LampBlackScope[];
  /** The sentence, templated as an ordered list of literal text and scope-tagged tokens. */
  record: LampBlackPart[];
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const SWEEP_MS = 260;
const STAGGER_MS = 40;

function isToken(part: LampBlackPart): part is LampBlackToken {
  return typeof part !== "string";
}

// Deterministic +/-0.3deg per bar so the strokes don't all sit dead-level — a
// hand-laid feel, not randomness that would differ mount to mount.
function rotationFor(text: string, groupIndex: number): number {
  const sign = (text.length + groupIndex) % 2 === 0 ? 1 : -1;
  return sign * 0.3;
}

/**
 * A consent surface that shows instead of tells: a live sentence built from
 * the user's own record, where each sharing scope is a real switch and
 * toggling one sweeps a felt-pen redaction bar over exactly the tokens that
 * scope withholds. The bar is the consent document.
 */
export function LampBlack({ scopes, record, className = "" }: LampBlackProps) {
  const [shared, setShared] = useState<Record<string, boolean>>(() =>
    Object.fromEntries(scopes.map((s) => [s.id, s.defaultShared ?? true])),
  );
  const uid = useId();

  const toggle = (id: string) => {
    setShared((prev) => ({ ...prev, [id]: !prev[id] }));
  };

  // per-scope running counts, for the 40ms group stagger
  const groupCounts: Record<string, number> = {};

  const sharedLabels = scopes.filter((s) => shared[s.id]).map((s) => s.label);
  const withheldLabels = scopes.filter((s) => !shared[s.id]).map((s) => s.label);
  const summary =
    withheldLabels.length === 0
      ? `Sharing everything below: ${sharedLabels.join(", ")}.`
      : sharedLabels.length === 0
        ? `Withholding everything below: ${withheldLabels.join(", ")}.`
        : `Sharing ${sharedLabels.join(", ")}. Withholding ${withheldLabels.join(", ")}.`;

  return (
    <div
      className={`ns-lampblack w-full max-w-lg rounded-xl border border-border bg-surface ${className}`}
    >
      <style>{`
        .ns-lampblack-bar {
          transition: transform ${SWEEP_MS}ms cubic-bezier(0.16, 1, 0.3, 1);
        }
        .ns-lampblack-glyph {
          transition: color ${SWEEP_MS}ms cubic-bezier(0.16, 1, 0.3, 1);
        }
        .ns-lampblack-thumb {
          transition: transform 200ms cubic-bezier(0.16, 1, 0.3, 1);
        }
        .ns-lampblack-track {
          transition: background-color 200ms ease-out, border-color 200ms ease-out, box-shadow 200ms ease-out;
        }
        .ns-lampblack-track:hover {
          box-shadow: 0 0 0 3px color-mix(in srgb, var(--foreground) 12%, transparent);
        }
        @media (prefers-reduced-motion: reduce) {
          .ns-lampblack-bar, .ns-lampblack-glyph, .ns-lampblack-thumb, .ns-lampblack-track {
            transition: none;
          }
        }
      `}</style>

      <header className="border-b border-border px-5 py-3">
        <span className="font-mono text-xs tracking-widest text-ns-muted">
          DATA SHARING PREVIEW
        </span>
      </header>

      <div className="px-5 py-5 text-sm leading-[1.9] text-foreground">
        <p>
          {record.map((part, i) => {
            if (!isToken(part)) {
              return <span key={i}>{part}</span>;
            }
            const groupIndex = groupCounts[part.scope] ?? 0;
            groupCounts[part.scope] = groupIndex + 1;
            const withheld = !shared[part.scope];
            const kind = part.kind ?? part.scope;
            const delayMs = groupIndex * STAGGER_MS;
            const rot = rotationFor(part.text, groupIndex);
            return (
              <span
                key={i}
                className="relative inline-block whitespace-nowrap rounded-[3px] px-[2px] align-baseline"
              >
                <span
                  aria-hidden={withheld}
                  className="ns-lampblack-glyph relative z-0"
                  style={{
                    color: withheld ? "transparent" : "var(--foreground)",
                    transitionDelay: `${delayMs}ms`,
                  }}
                >
                  {part.text}
                </span>
                {withheld && <span className="sr-only">{`[withheld: ${kind}]`}</span>}
                <span
                  aria-hidden
                  data-lampblack-bar={part.scope}
                  data-withheld={withheld ? "true" : "false"}
                  className="ns-lampblack-bar absolute inset-0 z-10 rounded-[2px] bg-foreground"
                  style={{
                    transform: `rotate(${rot}deg) scaleX(${withheld ? 1 : 0})`,
                    transformOrigin: "left center",
                    transitionDelay: `${delayMs}ms`,
                  }}
                />
              </span>
            );
          })}
        </p>
      </div>

      <div className="border-t border-border px-5 py-2">
        {scopes.map((scope) => {
          const labelId = `${uid}-${scope.id}-label`;
          const on = shared[scope.id];
          return (
            <div
              key={scope.id}
              className="flex items-start justify-between gap-4 py-2.5 first:pt-3 last:pb-3"
            >
              <div className="min-w-0">
                <div id={labelId} className="text-sm text-foreground">
                  {scope.label}
                </div>
                {scope.hint && <div className="mt-0.5 text-xs text-ns-muted">{scope.hint}</div>}
              </div>
              <button
                type="button"
                role="switch"
                aria-checked={on}
                aria-labelledby={labelId}
                data-lampblack-switch={scope.id}
                onClick={() => toggle(scope.id)}
                className="ns-lampblack-track relative h-5 w-9 shrink-0 rounded-full border border-border p-0.5 outline-none focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-surface"
                style={{
                  backgroundColor: on ? "var(--ns-accent)" : "var(--border)",
                  borderColor: on ? "var(--ns-accent)" : "var(--border)",
                }}
              >
                <span
                  aria-hidden
                  className="ns-lampblack-thumb block h-4 w-4 rounded-full bg-background"
                  style={{ transform: on ? "translateX(16px)" : "translateX(0)" }}
                />
              </button>
            </div>
          );
        })}
      </div>

      <p aria-live="polite" className="border-t border-border px-5 py-3 text-xs text-ns-muted">
        {summary}
      </p>
    </div>
  );
}

"use client";

import { useEffect, useId, useRef, useState, type FormEvent } from "react";

// ---------------------------------------------------------------------------
// TeletypeForm — a contact form whose validation surfaces as a real running
// receipt, not a red border. Every field validates on a debounced keystroke
// (or on submit, for whatever hasn't fired yet) and PRINTS a new line below
// the form — teletype-style, each line typing itself out over a duration
// proportional to its own length via a width transition stepped one
// character at a time, never cleared once written. Correcting a field does
// NOT erase its old line: the old line gets struck through in place and a
// fresh line for the same field prints below it, so the receipt reads as an
// honest log of the fill (what was tried, in order) rather than a status
// badge that overwrites itself.
//
// Distinct from validation-inline-wick (a single field's border diffuses a
// tint from the offending character — no log, no history) and from
// validation-error-summary (a punch list gathered at the TOP of the form on
// failed submit, with leader lines back to fields, that self-dismisses once
// every field resolves and forgets earlier attempts). Distinct from
// ticker-teleprinter (a marquee crawl with no semantic content) and
// progress-telegraph-log (a log of a caller-driven async operation's own
// sub-steps, not of user-typed field validation). Here the log is the point:
// it accretes for the life of the form, keeping every correction visible.
// ---------------------------------------------------------------------------

export interface TeletypeFieldSpec {
  name: string;
  label: string;
  type?: "text" | "email" | "textarea";
  placeholder?: string;
  /** return an error message, or null when the value passes */
  validate: (value: string) => string | null;
}

export interface ContactFormTeletypeProps {
  /** the form fields, in order */
  fields?: TeletypeFieldSpec[];
  /** called with all field values, keyed by field id, on submit */
  onSubmit?: (values: Record<string, string>) => void;
  /** ms after the last keystroke before that field's line prints. Default 260. */
  debounceMs?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const DEFAULT_FIELDS: TeletypeFieldSpec[] = [
  {
    name: "name",
    label: "Name",
    validate: (v) => (v.trim().length === 0 ? "required" : v.trim().length < 2 ? "too short" : null),
  },
  {
    name: "email",
    label: "Email",
    type: "email",
    validate: (v) =>
      v.trim().length === 0 ? "required" : /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v) ? null : "not a valid address",
  },
  {
    name: "message",
    label: "Message",
    type: "textarea",
    validate: (v) => (v.trim().length === 0 ? "required" : v.trim().length < 10 ? "too short" : null),
  },
];

interface Entry {
  id: number;
  field: string;
  label: string;
  ok: boolean;
  text: string;
  struck: boolean;
}

function receiptLine(label: string, ok: boolean, err: string | null): string {
  const dots = ".".repeat(Math.max(3, 22 - label.length));
  return ok ? `${label.toUpperCase()} ${dots} OK` : `${label.toUpperCase()} ${dots} FAIL — ${err}`;
}

export function ContactFormTeletype({
  fields = DEFAULT_FIELDS,
  onSubmit,
  debounceMs = 260,
  className = "",
}: ContactFormTeletypeProps) {
  const uid = useId();
  const [values, setValues] = useState<Record<string, string>>(() =>
    Object.fromEntries(fields.map((f) => [f.name, ""]))
  );
  const [entries, setEntries] = useState<Entry[]>([]);
  const debounceRefs = useRef<Record<string, ReturnType<typeof setTimeout> | undefined>>({});
  const entryIdRef = useRef(0);
  const reducedRef = useRef(false);

  useEffect(() => {
    reducedRef.current = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const refs = debounceRefs.current;
    return () => {
      Object.values(refs).forEach((t) => t && clearTimeout(t));
    };
  }, []);

  function printLine(field: TeletypeFieldSpec, value: string) {
    const err = field.validate(value);
    const ok = err === null;
    setEntries((prev) => {
      const struck = prev.map((e) => (e.field === field.name ? { ...e, struck: true } : e));
      return [
        ...struck,
        {
          id: entryIdRef.current++,
          field: field.name,
          label: field.label,
          ok,
          text: receiptLine(field.label, ok, err),
          struck: false,
        },
      ];
    });
  }

  function handleChange(field: TeletypeFieldSpec, next: string) {
    setValues((v) => ({ ...v, [field.name]: next }));
    const refs = debounceRefs.current;
    if (refs[field.name]) clearTimeout(refs[field.name]);
    refs[field.name] = setTimeout(() => printLine(field, next), debounceMs);
  }

  function handleSubmit(e: FormEvent) {
    e.preventDefault();
    let allOk = true;
    fields.forEach((f) => {
      const refs = debounceRefs.current;
      if (refs[f.name]) clearTimeout(refs[f.name]);
      const v = values[f.name] ?? "";
      const err = f.validate(v);
      if (err) allOk = false;
      printLine(f, v);
    });
    if (allOk) onSubmit?.(values);
  }

  const fieldCls =
    "ns-cft-field w-full rounded-sm border border-border bg-background px-3 py-2 font-mono text-sm text-foreground transition-colors duration-150 placeholder:text-ns-muted/60 hover:border-ns-muted focus-visible:border-ns-accent focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent";

  return (
    <div className={`ns-cft w-full ${className}`}>
      <style>{CSS}</style>
      <form onSubmit={handleSubmit} className="flex flex-col gap-4" noValidate>
        {fields.map((field) => {
          const fieldId = `${uid}-${field.name}`;
          return (
            <div key={field.name} className="flex flex-col gap-1.5">
              <label htmlFor={fieldId} className="font-mono text-xs uppercase tracking-widest text-ns-muted">
                {field.label}
              </label>
              {field.type === "textarea" ? (
                <textarea
                  id={fieldId}
                  name={field.name}
                  rows={3}
                  value={values[field.name]}
                  placeholder={field.placeholder}
                  onChange={(e) => handleChange(field, e.target.value)}
                  className={`${fieldCls} resize-none`}
                />
              ) : (
                <input
                  id={fieldId}
                  name={field.name}
                  type={field.type ?? "text"}
                  value={values[field.name]}
                  placeholder={field.placeholder}
                  onChange={(e) => handleChange(field, e.target.value)}
                  className={fieldCls}
                />
              )}
            </div>
          );
        })}
        <button
          type="submit"
          className="ns-cft-submit self-start rounded-sm border border-border px-4 py-2 font-mono text-xs uppercase tracking-widest text-foreground transition-colors duration-150 hover:border-ns-accent hover:text-ns-accent focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
        >
          Send
        </button>
      </form>

      <div
        role="log"
        aria-live="polite"
        aria-label="Field validation receipt"
        className="ns-cft-receipt mt-6 flex flex-col gap-0.5 rounded-sm border border-border bg-surface p-3 font-mono text-xs"
      >
        <p className="pb-1 text-ns-muted">— RECEIPT —</p>
        {entries.length === 0 && (
          <p aria-hidden="true" className="text-ns-muted/60">
            (awaiting input)
          </p>
        )}
        {entries.map((entry) => (
          <ReceiptLine key={entry.id} entry={entry} reduced={reducedRef.current} />
        ))}
      </div>
    </div>
  );
}

function ReceiptLine({ entry, reduced }: { entry: Entry; reduced: boolean }) {
  const [printed, setPrinted] = useState(reduced);
  const chars = Math.max(1, entry.text.length);

  useEffect(() => {
    if (reduced) return;
    const raf = requestAnimationFrame(() => setPrinted(true));
    return () => cancelAnimationFrame(raf);
  }, [reduced]);

  const duration = reduced ? 0 : Math.min(900, Math.max(160, chars * 20));

  return (
    <div
      className="ns-cft-line"
      style={{ color: entry.ok ? "var(--foreground)" : "var(--error, #ea001d)" }}
    >
      <span
        className={`ns-cft-print inline-block overflow-hidden whitespace-pre align-top ${
          entry.struck ? "ns-cft-struck" : ""
        }`}
        style={{
          width: printed ? `${chars}ch` : "0ch",
          transition: reduced ? "none" : `width ${duration}ms steps(${chars}, end)`,
        }}
      >
        {entry.text}
      </span>
    </div>
  );
}

const CSS = `
.ns-cft-struck { text-decoration: line-through; text-decoration-thickness: 1px; opacity: 0.55; transition: opacity 200ms ease; }
`;

"use client";

import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";

type Role = "corner-tl" | "corner-tr" | "corner-bl" | "corner-br" | "h" | "v";
type Cell = { char: string } | { refIndex: number; role: Role };

const SINGLE: Record<Role, string> = {
  "corner-tl": "┌",
  "corner-tr": "┐",
  "corner-bl": "└",
  "corner-br": "┘",
  h: "─",
  v: "│",
};
const DOUBLE: Record<Role, string> = {
  "corner-tl": "╔",
  "corner-tr": "╗",
  "corner-bl": "╚",
  "corner-br": "╝",
  h: "═",
  v: "║",
};

const LINE_HEIGHT = 1.4;

export interface RuleFrameProps {
  /** sits inline in the top rule, like a fieldset legend */
  title?: string;
  /** the framed content */
  children?: React.ReactNode;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

// Builds every border position once, as plain data, in true clockwise order
// starting at the top-left corner: each rule-character position gets a
// stable `refIndex` (0..N-1) assigned by pure traversal order, never by a
// ref-callback side effect. That matters because React tears down and sets
// up a ref callback on every render whose identity changed (ours always
// does, since it closes over per-render data) — if the index came from an
// incrementing counter read inside the callback itself, an old callback's
// teardown firing after a new callback's setup would scramble the count.
// Indexing from precomputed data sidesteps that: every callback, old or
// new, only ever writes to the one slot it was built for.
function buildPerimeter(cols: number, rows: number, title?: string) {
  const role: Role[] = [];
  let n = 0;
  const alloc = (r: Role) => {
    role[n] = r;
    return n++;
  };

  // `cols`/`rows` are the FULL measured box in character units, corners
  // included. Each straight edge holds two of those cells for its own
  // corners, so the run of dash/bar glyphs between them is cols-2 / rows-2
  // long, not cols / rows — using the full count here was the bug: it made
  // every straight edge two characters longer than the box it was supposed
  // to tile, so the perimeter never closed.
  const innerCols = Math.max(0, cols - 2);
  const innerRows = Math.max(0, rows - 2);

  const titleText = title ? ` ${title} ` : "";
  const titleCols = Math.min(titleText.length, innerCols);
  const leftDashes = Math.max(0, Math.floor((innerCols - titleCols) / 2));

  const tl: Cell = { refIndex: alloc("corner-tl"), role: "corner-tl" };
  const top: Cell[] = [];
  for (let i = 0; i < innerCols; i++) {
    if (title && i >= leftDashes && i < leftDashes + titleCols) {
      top.push({ char: titleText[i - leftDashes] });
    } else {
      top.push({ refIndex: alloc("h"), role: "h" });
    }
  }
  const tr: Cell = { refIndex: alloc("corner-tr"), role: "corner-tr" };

  const right: Cell[] = Array.from({ length: innerRows }, () => ({
    refIndex: alloc("v"),
    role: "v" as Role,
  }));

  const br: Cell = { refIndex: alloc("corner-br"), role: "corner-br" };
  // clockwise continues right-to-left along the bottom
  const bottomRTL: Cell[] = Array.from({ length: innerCols }, () => ({
    refIndex: alloc("h"),
    role: "h" as Role,
  }));
  const bl: Cell = { refIndex: alloc("corner-bl"), role: "corner-bl" };

  // then bottom-to-top along the left edge
  const leftBTT: Cell[] = Array.from({ length: innerRows }, () => ({
    refIndex: alloc("v"),
    role: "v" as Role,
  }));

  return { role, tl, top, tr, right, br, bottomRTL, bl, leftBTT, total: n };
}

export function RuleFrame({ title, children, className = "" }: RuleFrameProps) {
  const contentRef = useRef<HTMLDivElement>(null);
  const probeRef = useRef<HTMLSpanElement>(null);
  const [grid, setGrid] = useState({ cols: 20, rows: 4 });
  const [hovered, setHovered] = useState(false);
  const [focusWithin, setFocusWithin] = useState(false);
  const active = hovered || focusWithin;

  // measure the content box + a 1ch/1lh probe, recompute the character
  // counts the border needs to tile exactly across whatever size the
  // children end up being
  useLayoutEffect(() => {
    const content = contentRef.current;
    const probe = probeRef.current;
    if (!content || !probe) return;

    const measure = () => {
      const cell = probe.getBoundingClientRect();
      const box = content.getBoundingClientRect();
      if (cell.width <= 0 || cell.height <= 0) return;
      setGrid({
        cols: Math.max(4, Math.round(box.width / cell.width)),
        rows: Math.max(2, Math.round(box.height / cell.height)),
      });
    };

    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(content);
    document.fonts.ready.then(measure).catch(() => {});
    return () => ro.disconnect();
  }, [title]);

  const perimeter = useMemo(
    () => buildPerimeter(grid.cols, grid.rows, title),
    [grid.cols, grid.rows, title]
  );

  const elsRef = useRef<(HTMLSpanElement | null)[]>([]);
  const roleRef = useRef<Role[]>([]);
  roleRef.current = perimeter.role;

  const cellRef = (cell: Cell) => {
    if ("char" in cell) return undefined;
    const { refIndex } = cell;
    return (el: HTMLSpanElement | null) => {
      elsRef.current[refIndex] = el;
    };
  };

  const renderCell = (cell: Cell, key: number) =>
    "char" in cell ? (
      <span key={key} aria-hidden className="text-foreground">
        {cell.char}
      </span>
    ) : (
      <span key={key} aria-hidden ref={cellRef(cell)} />
    );

  // paint every position's resting glyph before the sweep effect below gets
  // a chance to animate it, so a grid change mid-hover never flashes blank
  useLayoutEffect(() => {
    roleRef.current.forEach((role, i) => {
      const el = elsRef.current[i];
      if (el) el.textContent = active ? DOUBLE[role] : SINGLE[role];
    });
  });

  // the actual sweep: character-by-character, starting at the top-left
  // corner (refIndex 0) and proceeding clockwise in refIndex order
  useEffect(() => {
    const n = perimeter.total;
    if (n === 0) return;
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    const paint = (count: number) => {
      for (let i = 0; i < n; i++) {
        const el = elsRef.current[i];
        if (!el) continue;
        const role = roleRef.current[i];
        const flipped = active ? i < count : i >= count;
        el.textContent = flipped ? DOUBLE[role] : SINGLE[role];
      }
    };

    if (reduced) {
      // paint(n) settles BOTH directions: active flips `i < n` (all double),
      // inactive flips `i >= n` (all single). `paint(0)` for inactive would
      // flip every index and render a full double border at rest.
      paint(n);
      return;
    }

    const duration = Math.min(900, Math.max(300, n * 16));
    const start = performance.now();
    let raf = 0;
    const tick = (now: number) => {
      const frac = Math.min(1, (now - start) / duration);
      paint(Math.floor(frac * n));
      if (frac < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [active, perimeter]);

  return (
    <div
      data-container-box-drawing
      className={`relative inline-block font-mono ${className}`}
      style={{ lineHeight: LINE_HEIGHT }}
      onPointerEnter={() => setHovered(true)}
      onPointerLeave={() => setHovered(false)}
      onFocus={() => setFocusWithin(true)}
      onBlur={(e) => {
        if (!e.currentTarget.contains(e.relatedTarget as Node)) setFocusWithin(false);
      }}
    >
      {/* 1ch/1lh probe — invisible, used only to measure the font's own
          character cell so the border can tile in whole characters */}
      <span
        ref={probeRef}
        aria-hidden
        className="pointer-events-none invisible absolute"
        style={{ width: "1ch", height: "1lh", lineHeight: LINE_HEIGHT }}
      />

      <div
        aria-hidden
        className={`pointer-events-none absolute inset-0 select-none transition-colors duration-300 ${
          active ? "text-foreground" : "text-border"
        }`}
      >
        <div className="absolute inset-x-0 top-0 flex whitespace-pre">
          {renderCell(perimeter.tl, -1)}
          {perimeter.top.map(renderCell)}
          {renderCell(perimeter.tr, -2)}
        </div>
        <div
          className="absolute right-0 flex flex-col"
          style={{ top: "1lh", bottom: "1lh" }}
        >
          {perimeter.right.map(renderCell)}
        </div>
        {/* rendered right-to-left in the DOM (matching the clockwise refIndex
            order) and restored to visual left-to-right with row-reverse */}
        <div className="absolute inset-x-0 bottom-0 flex flex-row-reverse whitespace-pre">
          {renderCell(perimeter.br, -3)}
          {perimeter.bottomRTL.map(renderCell)}
          {renderCell(perimeter.bl, -4)}
        </div>
        {/* rendered bottom-to-top in the DOM, restored to visual top-to-bottom
            with column-reverse */}
        <div
          className="absolute left-0 flex flex-col-reverse"
          style={{ top: "1lh", bottom: "1lh" }}
        >
          {perimeter.leftBTT.map(renderCell)}
        </div>
      </div>

      <div ref={contentRef} className="relative" style={{ padding: "1lh 1ch" }}>
        {children}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useId, useMemo, useRef, useState, type KeyboardEvent as ReactKeyboardEvent } from "react";

// OxbowTurn — the live conversation drawn as one meandering channel in a
// side rail. Every live turn is a point the channel passes through; the
// curve itself is decorative (aria-hidden SVG) and carries no information a
// screen reader needs, because the same facts live as plain text in a real
// list right below it ("Live context, N turns" / "Compacted: turns 3-9,
// summarized 2 minutes ago").
//
// When turns get folded into a summary, the component doesn't just drop a
// row — the compaction keeps its own place in the sequence, and the channel
// simply stops routing through it: the surviving points ease toward their
// new (tighter) spacing over ~300ms, which is what "the river gets shorter"
// looks like here, while the folded turns settle 12px off the channel as a
// closed oxbow-lake shape carrying a token-count chip. That chip is a real,
// focusable button (never aria-hidden) — opening it reveals the summary and
// a re-inject action in a role=menu popover. Re-inject animates the lake
// back onto the channel before the prop change actually removes it, so nothing
// is left to imagination between "click" and "the turns are back".
//
// The trigger is deliberately open-only (a second click does not close it —
// only Escape, an outside click, or choosing the menu item does). That is
// what keeps a synthetic "press" pass (which clicks the first control once,
// unconditionally) and a later scripted "open this" check from fighting over
// the same toggle.
//
// Positions are computed from each item's index in the full sequence (turn
// or compaction alike), so a compaction never needs its own bookkeeping of
// "where it used to be" — it already has a slot. Turn dots and the channel
// path animate via a direct rAF loop (setAttribute only, no React state on
// the hot path, sleeps once settled) exactly like this repo's other
// spring-driven diagrams. Everything else (the oxbow's 12px settle, its
// entrance/exit) is a plain CSS transform+opacity transition, which reduced
// motion turns off wholesale in favor of an instant fade-and-move.

export type OxbowTurnEntry = {
  id: string;
  /** short label, e.g. a turn number — used to build "turns 3-9" range text */
  label: string;
};

export type OxbowTurnItem =
  | { kind: "turn"; id: string; label: string; preview?: string }
  | {
      kind: "compaction";
      id: string;
      /** the turns folded into this oxbow, oldest -> newest */
      turns: OxbowTurnEntry[];
      summary: string;
      tokenCount: number;
      /** precomputed, e.g. "2 minutes ago" — this component never touches the clock */
      compactedAgo: string;
    };

export interface OxbowTurnProps {
  /** the full ordered sequence: live turns and compaction (oxbow) entries, interleaved */
  items: OxbowTurnItem[];
  /** fired once a re-inject has finished animating back onto the channel */
  onReinject?: (compactionId: string) => void;
  /** accessible name for the channel */
  ariaLabel?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const ROW_H = 38;
const PAD_Y = 18;
const CX = 30; // channel centerline, px from the rail's left edge
const AMP1 = 11;
const AMP2 = 5;
const OFFSET = 12; // brief's "12px off-channel"
const DOT_R = 3;
const EASE_RATE = 0.24; // per-frame lerp toward target, ~300ms settle at 60fps
const SETTLE_EPS = 0.04;
const RAIL_W = 236;

type Pt = { x: number; y: number };

function channelX(row: number): number {
  return CX + AMP1 * Math.sin(row * 0.85) + AMP2 * Math.sin(row * 1.9 + 1.3);
}

function rowY(row: number): number {
  return PAD_Y + row * ROW_H;
}

/** Catmull-Rom through `pts`, converted to cubic beziers (tension/6 form). */
function smoothPath(pts: Pt[]): string {
  if (pts.length === 0) return "";
  if (pts.length === 1) return `M ${pts[0].x} ${pts[0].y}`;
  let d = `M ${pts[0].x} ${pts[0].y}`;
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[i - 1] ?? pts[i];
    const p1 = pts[i];
    const p2 = pts[i + 1];
    const p3 = pts[i + 2] ?? p2;
    const c1x = p1.x + (p2.x - p0.x) / 6;
    const c1y = p1.y + (p2.y - p0.y) / 6;
    const c2x = p2.x - (p3.x - p1.x) / 6;
    const c2y = p2.y - (p3.y - p1.y) / 6;
    d += ` C ${c1x} ${c1y}, ${c2x} ${c2y}, ${p2.x} ${p2.y}`;
  }
  return d;
}

function formatTok(n: number): string {
  return Math.round(Math.max(0, n)).toLocaleString("en-US");
}

function turnsLabel(turns: OxbowTurnEntry[]): string {
  if (turns.length === 0) return "no turns";
  if (turns.length === 1) return `turn ${turns[0].label}`;
  return `turns ${turns[0].label}–${turns[turns.length - 1].label}`;
}

type TurnPoint = { id: string; x: number; y: number; label: string; preview?: string; isLast: boolean };
type LakeRow = { id: string; item: Extract<OxbowTurnItem, { kind: "compaction" }>; x: number; y: number };

function layout(items: OxbowTurnItem[]): { turns: TurnPoint[]; lakes: LakeRow[] } {
  const turns: TurnPoint[] = [];
  const lakes: LakeRow[] = [];
  items.forEach((it, row) => {
    const x = channelX(row);
    const y = rowY(row);
    if (it.kind === "turn") {
      turns.push({ id: it.id, x, y, label: it.label, preview: it.preview, isLast: false });
    } else {
      lakes.push({ id: it.id, item: it, x, y });
    }
  });
  if (turns.length > 0) turns[turns.length - 1].isLast = true;
  return { turns, lakes };
}

export function OxbowTurn({
  items,
  onReinject,
  ariaLabel = "Context compaction history",
  className = "",
}: OxbowTurnProps) {
  const rawId = useId();
  const fid = rawId.replace(/[^a-zA-Z0-9-]/g, "");

  const [reduced, setReduced] = useState(false);
  const [openId, setOpenId] = useState<string | null>(null);
  const [enterState, setEnterState] = useState<Record<string, "start" | "end">>({});
  const [exitingIds, setExitingIds] = useState<Record<string, true>>({});
  const [snap, setSnap] = useState(false);
  const [liveMsg, setLiveMsg] = useState("");

  const wrapRef = useRef<HTMLDivElement | null>(null);
  const popRef = useRef<HTMLDivElement | null>(null);
  const triggerRefs = useRef<Map<string, HTMLButtonElement>>(new Map());
  const pathElRef = useRef<SVGPathElement | null>(null);
  const dotElsRef = useRef<Map<string, SVGCircleElement>>(new Map());
  const dotWrapElsRef = useRef<Map<string, HTMLDivElement>>(new Map());
  const posRef = useRef<Map<string, Pt>>(new Map());
  const prevCompactionIdsRef = useRef<Set<string>>(new Set());
  const cleanupsRef = useRef<Array<() => void>>([]);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  useEffect(() => () => {
    for (const cancel of cleanupsRef.current) cancel();
    cleanupsRef.current = [];
  }, []);

  const { turns: turnTargets, lakes: lakeRows } = useMemo(() => layout(items), [items]);
  const H = Math.max(PAD_Y * 2, PAD_Y * 2 + Math.max(0, items.length - 1) * ROW_H);

  const [initialD] = useState(() => smoothPath(layout(items).turns.map((t) => ({ x: t.x, y: t.y }))));

  // channel + turn-dot animation: direct DOM writes, no React state on the hot path
  useEffect(() => {
    const targetMap = new Map(turnTargets.map((t) => [t.id, { x: t.x, y: t.y }]));
    for (const id of Array.from(posRef.current.keys())) {
      if (!targetMap.has(id)) posRef.current.delete(id);
    }

    if (reduced) {
      for (const t of turnTargets) {
        posRef.current.set(t.id, { x: t.x, y: t.y });
        const el = dotElsRef.current.get(t.id);
        el?.setAttribute("cx", String(t.x));
        el?.setAttribute("cy", String(t.y));
        const wrapEl = dotWrapElsRef.current.get(t.id);
        if (wrapEl) {
          wrapEl.style.left = `${t.x}px`;
          wrapEl.style.top = `${t.y}px`;
        }
      }
      pathElRef.current?.setAttribute("d", smoothPath(turnTargets.map((t) => ({ x: t.x, y: t.y }))));
      return;
    }

    let raf = 0;
    const step = () => {
      let moving = false;
      const pts: Pt[] = [];
      for (const t of turnTargets) {
        const cur = posRef.current.get(t.id) ?? { x: t.x, y: t.y };
        const nx = cur.x + (t.x - cur.x) * EASE_RATE;
        const ny = cur.y + (t.y - cur.y) * EASE_RATE;
        if (Math.abs(t.x - nx) > SETTLE_EPS || Math.abs(t.y - ny) > SETTLE_EPS) moving = true;
        posRef.current.set(t.id, { x: nx, y: ny });
        pts.push({ x: nx, y: ny });
        const el = dotElsRef.current.get(t.id);
        el?.setAttribute("cx", String(nx));
        el?.setAttribute("cy", String(ny));
        const wrapEl = dotWrapElsRef.current.get(t.id);
        if (wrapEl) {
          wrapEl.style.left = `${nx}px`;
          wrapEl.style.top = `${ny}px`;
        }
      }
      pathElRef.current?.setAttribute("d", smoothPath(pts));
      if (moving) raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [turnTargets, reduced]);

  // compaction enter + aria-live announcements
  useEffect(() => {
    const curIds = new Set(lakeRows.map((l) => l.id));
    const prevIds = prevCompactionIdsRef.current;
    const added = lakeRows.filter((l) => !prevIds.has(l.id));
    const removedCount = Array.from(prevIds).filter((id) => !curIds.has(id)).length;

    if (added.length > 0) {
      if (!reduced) {
        setEnterState((s) => {
          const next = { ...s };
          for (const l of added) next[l.id] = "start";
          return next;
        });
        const raf1 = requestAnimationFrame(() => {
          const raf2 = requestAnimationFrame(() => {
            setEnterState((s) => {
              const next = { ...s };
              for (const l of added) if (next[l.id] === "start") next[l.id] = "end";
              return next;
            });
          });
          cleanupsRef.current.push(() => cancelAnimationFrame(raf2));
        });
        cleanupsRef.current.push(() => cancelAnimationFrame(raf1));
      }
      const first = added[0];
      setLiveMsg(
        `Compacted ${turnsLabel(first.item.turns)} into a ${formatTok(first.item.tokenCount)}-token summary.`
      );
      if (!reduced) {
        setSnap(true);
        const t = window.setTimeout(() => setSnap(false), 320);
        cleanupsRef.current.push(() => window.clearTimeout(t));
      }
    } else if (removedCount > 0 && added.length === 0) {
      // a removal this component didn't itself animate (e.g. reset) — still announce
      setLiveMsg("Re-injected turns back into live context.");
    }
    prevCompactionIdsRef.current = curIds;
  }, [lakeRows, reduced]);

  // outside click closes the open popover
  useEffect(() => {
    if (!openId) return;
    const onDown = (e: PointerEvent) => {
      const target = e.target as Node;
      if (popRef.current?.contains(target)) return;
      if (triggerRefs.current.get(openId)?.contains(target)) return;
      setOpenId(null);
    };
    document.addEventListener("pointerdown", onDown);
    return () => document.removeEventListener("pointerdown", onDown);
  }, [openId]);

  // focus the summary when a popover opens
  useEffect(() => {
    if (!openId) return;
    const raf = requestAnimationFrame(() => {
      popRef.current?.querySelector<HTMLElement>("[data-oxbow-summary]")?.focus({ preventScroll: true });
    });
    return () => cancelAnimationFrame(raf);
  }, [openId]);

  const closeAndReturnFocus = (id: string) => {
    setOpenId(null);
    triggerRefs.current.get(id)?.focus({ preventScroll: true });
  };

  const handleReinject = (l: LakeRow) => {
    if (reduced) {
      setOpenId(null);
      onReinject?.(l.id);
      return;
    }
    setOpenId(null);
    setExitingIds((s) => ({ ...s, [l.id]: true }));
    const t = window.setTimeout(() => {
      onReinject?.(l.id);
      setExitingIds((s) => {
        const next = { ...s };
        delete next[l.id];
        return next;
      });
    }, 260);
    cleanupsRef.current.push(() => window.clearTimeout(t));
  };

  const onTriggerKeyDown = (l: LakeRow) => (e: ReactKeyboardEvent<HTMLButtonElement>) => {
    if (e.key === "ArrowDown" && openId !== l.id) {
      e.preventDefault();
      setOpenId(l.id);
    }
  };

  const onMenuKeyDown = (l: LakeRow) => (e: ReactKeyboardEvent<HTMLDivElement>) => {
    if (e.key === "Escape") {
      e.preventDefault();
      closeAndReturnFocus(l.id);
      return;
    }
    if (e.key === "Tab") {
      setOpenId(null);
      return;
    }
    const items_ = Array.from(e.currentTarget.querySelectorAll<HTMLElement>('[role="menuitem"]'));
    if (items_.length === 0) return;
    const idx = items_.indexOf(document.activeElement as HTMLElement);
    let next = -1;
    if (e.key === "ArrowDown") next = (idx + 1) % items_.length;
    else if (e.key === "ArrowUp") next = idx < 0 ? items_.length - 1 : (idx - 1 + items_.length) % items_.length;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = items_.length - 1;
    if (next >= 0) {
      e.preventDefault();
      items_[next]?.focus({ preventScroll: true });
    }
  };

  const turnCount = turnTargets.length;

  return (
    <div ref={wrapRef} role="group" aria-label={ariaLabel} className={`ns-oxbow relative ${className}`}>
      <style>{`
.ns-oxbow-dot{animation:ns-oxbow-dot-in 220ms cubic-bezier(.22,1,.36,1)}
.ns-oxbow-dot-current{fill:var(--foreground);animation:ns-oxbow-dot-in 220ms cubic-bezier(.22,1,.36,1),ns-oxbow-breathe 2.6s ease-in-out infinite}
.ns-oxbow-channel{transition:none}
.ns-oxbow-channel.ns-oxbow-snap{animation:ns-oxbow-snap 320ms cubic-bezier(.22,1,.36,1)}
.ns-oxbow-lake-anim,.ns-oxbow-chip-wrap{transition:transform 300ms cubic-bezier(.16,1,.3,1),opacity 220ms ease-out}
.ns-oxbow-lake-anim[data-state="entering"],.ns-oxbow-chip-wrap[data-state="entering"]{transform:translateX(0);opacity:0}
.ns-oxbow-lake-anim[data-state="settled"],.ns-oxbow-chip-wrap[data-state="settled"]{transform:translateX(${OFFSET}px);opacity:1}
.ns-oxbow-lake-anim[data-state="exiting"],.ns-oxbow-chip-wrap[data-state="exiting"]{transform:translateX(0);opacity:0;transition:transform 240ms cubic-bezier(.4,0,.9,.4),opacity 200ms ease-in}
.ns-oxbow-chip-tip,.ns-context-compaction-river-tip{opacity:0;transition:opacity 150ms ease-out}
[data-oxbow-trigger]:hover+.ns-oxbow-chip-tip,[data-oxbow-trigger]:focus+.ns-oxbow-chip-tip,[data-oxbow-trigger]:focus-visible+.ns-oxbow-chip-tip{opacity:1}
[data-context-compaction-river-btn]:hover+.ns-context-compaction-river-tip,[data-context-compaction-river-btn]:focus+.ns-context-compaction-river-tip,[data-context-compaction-river-btn]:focus-visible+.ns-context-compaction-river-tip{opacity:1}
@keyframes ns-oxbow-dot-in{from{opacity:0;transform:scale(.3)}to{opacity:1;transform:scale(1)}}
@keyframes ns-oxbow-breathe{0%,100%{opacity:.75}50%{opacity:1}}
@keyframes ns-oxbow-snap{0%{stroke-width:1.5}35%{stroke-width:2.6}100%{stroke-width:1.5}}
@media (prefers-reduced-motion: reduce){
  .ns-oxbow-dot,.ns-oxbow-dot-current{animation:none !important;opacity:1 !important;transform:none !important}
  .ns-oxbow-channel{animation:none !important}
  .ns-oxbow-lake-anim,.ns-oxbow-chip-wrap{transition:opacity 160ms ease-out !important;transform:translateX(${OFFSET}px) !important}
  .ns-oxbow-lake-anim[data-state="entering"],.ns-oxbow-chip-wrap[data-state="entering"]{opacity:0 !important}
  .ns-oxbow-lake-anim[data-state="exiting"],.ns-oxbow-chip-wrap[data-state="exiting"]{opacity:0 !important}
  .ns-oxbow-chip-tip,.ns-context-compaction-river-tip{transition:none !important}
}
`}</style>

      <div className="relative" style={{ width: RAIL_W, height: H }}>
        <svg
          aria-hidden
          width={RAIL_W}
          height={H}
          viewBox={`0 0 ${RAIL_W} ${H}`}
          className="pointer-events-none absolute inset-0 block overflow-visible"
        >
          <path
            ref={pathElRef}
            d={initialD}
            className={`ns-oxbow-channel${snap ? " ns-oxbow-snap" : ""}`}
            fill="none"
            stroke="var(--ns-muted)"
            strokeWidth={1.5}
            strokeLinecap="round"
          />

          {lakeRows.map((l) => {
            const state = exitingIds[l.id] ? "exiting" : enterState[l.id] === "start" ? "entering" : "settled";
            return (
              <g key={l.id} transform={`translate(${l.x} ${l.y})`}>
                {/* animated as one rigid unit: at rest (translateX 12) this spans exactly
                    anchor -> ellipse edge; the stub's own local span is kept constant so
                    sliding the group is what "grows the neck into place" looks like */}
                <g className="ns-oxbow-lake-anim" data-state={state}>
                  <path
                    d={`M ${-OFFSET} 0 Q ${-OFFSET * 0.5} -6 0 0`}
                    fill="none"
                    stroke="var(--ns-muted)"
                    strokeWidth={1}
                    strokeOpacity={0.55}
                  />
                  <ellipse
                    cx={15}
                    cy={0}
                    rx={15}
                    ry={9}
                    fill="color-mix(in srgb, var(--border) 6%, transparent)"
                    stroke="var(--border)"
                    strokeWidth={1}
                  />
                </g>
              </g>
            );
          })}

          {turnTargets.map((t) => (
            <circle
              key={t.id}
              ref={(el) => {
                if (el) {
                  dotElsRef.current.set(t.id, el);
                  if (!posRef.current.has(t.id)) {
                    el.setAttribute("cx", String(t.x));
                    el.setAttribute("cy", String(t.y));
                    posRef.current.set(t.id, { x: t.x, y: t.y });
                  }
                } else {
                  dotElsRef.current.delete(t.id);
                }
              }}
              r={t.isLast ? DOT_R + 1 : DOT_R}
              className={t.isLast ? "ns-oxbow-dot-current" : "ns-oxbow-dot"}
              fill={t.isLast ? undefined : "var(--ns-muted)"}
            >
              <title>{t.preview ? `${t.label}: ${t.preview}` : t.label}</title>
            </circle>
          ))}
        </svg>

        {/* real interactive targets for the (decorative, aria-hidden) turn dots above:
            positioned by the same rAF loop that drives the SVG circles (dotWrapElsRef),
            so the hit target and its tooltip track the easing motion instead of a
            React-controlled left/top that would snap ahead of the circle it sits on */}
        {turnTargets.map((t) => {
          const turnTipId = `${fid}-turn-tip-${t.id}`;
          const hasPreview = Boolean(t.preview);
          const accName = hasPreview ? `Turn ${t.label}: ${t.preview}` : `Turn ${t.label}`;
          return (
            <div
              key={t.id}
              ref={(el) => {
                if (el) {
                  dotWrapElsRef.current.set(t.id, el);
                  const cur = posRef.current.get(t.id) ?? { x: t.x, y: t.y };
                  el.style.left = `${cur.x}px`;
                  el.style.top = `${cur.y}px`;
                } else {
                  dotWrapElsRef.current.delete(t.id);
                }
              }}
              className="absolute -translate-x-1/2 -translate-y-1/2"
            >
              <button
                type="button"
                data-context-compaction-river-btn
                aria-label={accName}
                aria-describedby={hasPreview ? turnTipId : undefined}
                className="block h-4 w-4 cursor-default rounded-full bg-transparent focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
              />
              {hasPreview && (
                <span
                  id={turnTipId}
                  role="tooltip"
                  className="ns-context-compaction-river-tip pointer-events-none absolute left-[calc(100%+8px)] top-1/2 z-20 block w-max max-w-[200px] -translate-y-1/2 whitespace-normal rounded-md border border-border px-2 py-1 font-mono text-[10px] leading-relaxed text-foreground shadow-lg"
                  style={{ background: "color-mix(in srgb, var(--foreground) 4%, var(--background))" }}
                >
                  Turn {t.label}: {t.preview}
                </span>
              )}
            </div>
          );
        })}

        {lakeRows.map((l) => {
          const state = exitingIds[l.id] ? "exiting" : enterState[l.id] === "start" ? "entering" : "settled";
          const isOpen = openId === l.id;
          const menuId = `${fid}-menu-${l.id}`;
          const tipId = `${fid}-tip-${l.id}`;
          return (
            <div
              key={l.id}
              className="ns-oxbow-chip-wrap absolute"
              data-state={state}
              style={{ left: l.x, top: l.y - 12 }}
            >
              <button
                ref={(el) => {
                  if (el) triggerRefs.current.set(l.id, el);
                  else triggerRefs.current.delete(l.id);
                }}
                type="button"
                data-oxbow-trigger
                aria-haspopup="menu"
                aria-expanded={isOpen}
                aria-controls={isOpen ? menuId : undefined}
                aria-describedby={!isOpen ? tipId : undefined}
                aria-label={`Compacted ${turnsLabel(l.item.turns)}, ${formatTok(l.item.tokenCount)} tokens. Open summary and re-inject.`}
                onClick={() => setOpenId(l.id)}
                onKeyDown={onTriggerKeyDown(l)}
                className="flex cursor-pointer items-center gap-1.5 whitespace-nowrap rounded-full border border-border px-2.5 py-1 font-mono text-[10px] tracking-wide text-ns-muted transition-colors duration-150 hover:border-foreground/30 hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
                style={{ background: "color-mix(in srgb, var(--foreground) 4%, var(--background))" }}
              >
                <span aria-hidden>{l.item.turns.length}↩</span>
                <span aria-hidden>{formatTok(l.item.tokenCount)} tok</span>
              </button>

              {!isOpen && (
                <span
                  id={tipId}
                  role="tooltip"
                  className="ns-oxbow-chip-tip pointer-events-none absolute bottom-[calc(100%+8px)] left-0 z-20 block w-max max-w-[220px] whitespace-normal rounded-md border border-border px-2 py-1 font-mono text-[10px] leading-relaxed text-foreground shadow-lg"
                  style={{ background: "color-mix(in srgb, var(--foreground) 4%, var(--background))" }}
                >
                  {turnsLabel(l.item.turns)} pinched off the channel · re-injectable
                </span>
              )}

              {isOpen && (
                <div
                  ref={popRef}
                  id={menuId}
                  className="absolute left-0 top-[calc(100%+8px)] z-10 w-60 rounded-md border border-border p-3 shadow-lg"
                  style={{ background: "color-mix(in srgb, var(--foreground) 3%, var(--background))" }}
                >
                  <p
                    data-oxbow-summary
                    tabIndex={-1}
                    className="text-xs leading-relaxed text-foreground outline-none"
                  >
                    {l.item.summary}
                  </p>
                  <dl className="mt-2.5 space-y-1 font-mono text-[10px] uppercase tracking-wide text-ns-muted">
                    <div className="flex justify-between gap-2">
                      <dt>Turns</dt>
                      <dd className="text-foreground">{turnsLabel(l.item.turns)}</dd>
                    </div>
                    <div className="flex justify-between gap-2">
                      <dt>Summarized</dt>
                      <dd className="text-foreground">{l.item.compactedAgo}</dd>
                    </div>
                    <div className="flex justify-between gap-2">
                      <dt>Tokens</dt>
                      <dd className="text-foreground">{formatTok(l.item.tokenCount)}</dd>
                    </div>
                  </dl>
                  <div
                    role="menu"
                    aria-label={`Actions for compacted ${turnsLabel(l.item.turns)}`}
                    onKeyDown={onMenuKeyDown(l)}
                    className="mt-3 border-t border-border pt-2.5"
                  >
                    <button
                      role="menuitem"
                      type="button"
                      data-oxbow-reinject
                      onClick={() => handleReinject(l)}
                      className="w-full cursor-pointer rounded-sm px-2 py-1.5 text-left text-xs text-foreground transition-colors hover:bg-[color-mix(in_srgb,var(--foreground)_6%,transparent)] focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ns-accent"
                    >
                      Re-inject into live context
                    </button>
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>

      <ul className="mt-3 space-y-1 font-mono text-[11px] leading-relaxed text-ns-muted">
        <li>
          Live context, {turnCount} turn{turnCount === 1 ? "" : "s"}
        </li>
        {lakeRows.map((l) => (
          <li key={l.id}>
            Compacted: {turnsLabel(l.item.turns)}, summarized {l.item.compactedAgo}
          </li>
        ))}
      </ul>

      <p aria-live="polite" className="sr-only">
        {liveMsg}
      </p>
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
  type MouseEvent as ReactMouseEvent,
  type ReactNode,
} from "react";

// ---------------------------------------------------------------------------
// JackKnife — a context menu that unfolds like a pocket knife. A spine
// anchors at the trigger point (the pointer for a right-click, or the
// trigger button's own position for the accessible trigger); menu items are
// slim "blades" hinged at the spine edge, each swinging in with a staggered
// rotation from folded (~80deg, tucked flat against the spine) to open
// (0deg). Every swing is a one-shot ref-driven CSS transition (transform +
// a border-color pulse for the hairline edge highlight) — timed with a
// per-item delay for the stagger — not a continuous rAF loop. A submenu is
// the same component recursively, anchored at the parent blade's tip.
// Distinct from menu-nested-trays (telescoping trays) and dropdown-drape (cloth
// dropdown): this is a radial-fold context-menu primitive.
// ---------------------------------------------------------------------------

export interface JackKnifeItem {
  id: string;
  label: string;
  shortcut?: string;
  disabled?: boolean;
  submenu?: JackKnifeItem[];
}

export interface JackKnifeProps {
  /** the menu's rows */
  items: JackKnifeItem[];
  /** called with the chosen row's id when one is selected */
  onSelect?: (id: string) => void;
  /** region that opens the menu on right-click; the trigger button always works too */
  children?: ReactNode;
  /** accessible name for the trigger button and the menu itself */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

type Anchor = { x: number; y: number; side: "left" | "right" };

const OPEN_MS = 260;
const OPEN_STAGGER_MS = 38;
const CLOSE_MS = 150;
const CLOSE_STAGGER_MS = 22;
const HAIRLINE_HOLD_MS = 120;
const TYPEAHEAD_RESET_MS = 700;
const ITEM_W = 200;
const EDGE_MARGIN = 10;

function computeAnchor(x: number, y: number): Anchor {
  const side: Anchor["side"] = x + ITEM_W + EDGE_MARGIN > window.innerWidth ? "left" : "right";
  return { x, y, side };
}

function clampTop(y: number, height: number) {
  return Math.min(Math.max(EDGE_MARGIN, y), Math.max(EDGE_MARGIN, window.innerHeight - height - EDGE_MARGIN));
}

function foldItem(
  el: HTMLElement | null,
  index: number,
  opening: boolean,
  side: "left" | "right",
  reduced: boolean
) {
  if (!el) return;
  const sign = side === "right" ? -1 : 1;
  if (reduced) {
    el.style.transition = "none";
    el.style.transform = "rotate(0deg)";
    el.style.opacity = opening ? "1" : "0";
    el.style.borderColor = "var(--border)";
    return;
  }
  if (opening) {
    el.style.transition = "none";
    el.style.transform = `rotate(${sign * 80}deg)`;
    el.style.opacity = "0";
    el.style.borderColor = "var(--border)";
    el.getBoundingClientRect(); // force reflow before animating in
    const delay = index * OPEN_STAGGER_MS;
    el.style.transition = `transform ${OPEN_MS}ms cubic-bezier(0.16,1,0.3,1) ${delay}ms, opacity ${OPEN_MS * 0.7}ms linear ${delay}ms, border-color ${OPEN_MS}ms linear ${delay}ms`;
    el.style.transform = "rotate(0deg)";
    el.style.opacity = "1";
    el.style.borderColor = "var(--foreground)";
    window.setTimeout(() => {
      el.style.transition = `border-color ${HAIRLINE_HOLD_MS}ms linear`;
      el.style.borderColor = "var(--border)";
    }, delay + OPEN_MS);
  } else {
    const delay = index * CLOSE_STAGGER_MS;
    el.style.transition = `transform ${CLOSE_MS}ms cubic-bezier(0.6,0,0.84,0) ${delay}ms, opacity ${CLOSE_MS}ms linear ${delay}ms`;
    el.style.transform = `rotate(${sign * 80}deg)`;
    el.style.opacity = "0";
  }
}

interface BladesProps {
  items: JackKnifeItem[];
  anchor: Anchor;
  label: string;
  onSelect: (id: string) => void;
  onClose: (focusTrigger: boolean) => void;
  menuId: string;
}

function Blades({ items, anchor, label, onSelect, onClose, menuId }: BladesProps) {
  const panelRef = useRef<HTMLDivElement | null>(null);
  const itemRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const reducedRef = useRef(false);
  const [reduced, setReduced] = useState(false);
  const [submenuIndex, setSubmenuIndex] = useState<number | null>(null);
  const [submenuAnchor, setSubmenuAnchor] = useState<Anchor | null>(null);
  const typeaheadRef = useRef({ buffer: "", at: 0 });

  const closableItems = useMemo(() => items.filter((it) => !it.disabled), [items]);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    reducedRef.current = mq.matches;
    setReduced(mq.matches);
    const onChange = () => {
      reducedRef.current = mq.matches;
      setReduced(mq.matches);
    };
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  useEffect(() => {
    items.forEach((_, i) => foldItem(itemRefs.current[i] ?? null, i, true, anchor.side, reducedRef.current));
    const first = itemRefs.current.find((el, i) => el && !items[i]?.disabled);
    first?.focus({ preventScroll: true });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const closeSelf = useCallback(
    (focusTrigger: boolean) => {
      items.forEach((_, i) => foldItem(itemRefs.current[i] ?? null, i, false, anchor.side, reducedRef.current));
      const total = reducedRef.current ? 0 : items.length * CLOSE_STAGGER_MS + CLOSE_MS;
      window.setTimeout(() => onClose(focusTrigger), total);
    },
    [items, anchor.side, onClose]
  );

  const openSubmenu = (index: number) => {
    const el = itemRefs.current[index];
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const x = anchor.side === "right" ? rect.right - 8 : rect.left + 8;
    setSubmenuAnchor(computeAnchor(x, rect.top));
    setSubmenuIndex(index);
  };
  const closeSubmenu = () => {
    setSubmenuIndex(null);
    setSubmenuAnchor(null);
  };

  const focusByIndex = (i: number) => {
    const el = itemRefs.current[i];
    el?.focus({ preventScroll: true });
  };

  const onKeyDown = (e: ReactKeyboardEvent<HTMLDivElement>) => {
    if (submenuIndex !== null) {
      // let the submenu's own handler deal with everything except closing it back here
      if (e.key === "Escape") return; // bubbles from submenu, harmless
      return;
    }
    const enabled = itemRefs.current
      .map((el, i) => ({ el, i }))
      .filter(({ el, i }) => el && !items[i]?.disabled);
    const currentIdx = enabled.findIndex(({ el }) => el === document.activeElement);

    if (e.key === "Escape") {
      e.preventDefault();
      closeSelf(true);
      return;
    }
    if (e.key === "Tab") {
      closeSelf(false);
      return;
    }
    if (e.key === "ArrowDown") {
      e.preventDefault();
      const next = enabled[(currentIdx + 1) % enabled.length];
      if (next) focusByIndex(next.i);
      return;
    }
    if (e.key === "ArrowUp") {
      e.preventDefault();
      const next = enabled[currentIdx < 0 ? enabled.length - 1 : (currentIdx - 1 + enabled.length) % enabled.length];
      if (next) focusByIndex(next.i);
      return;
    }
    if (e.key === "Home") {
      e.preventDefault();
      const first = enabled[0];
      if (first) focusByIndex(first.i);
      return;
    }
    if (e.key === "End") {
      e.preventDefault();
      const last = enabled[enabled.length - 1];
      if (last) focusByIndex(last.i);
      return;
    }
    if (e.key === "ArrowRight" || e.key === "Enter" || e.key === " ") {
      const active = items[currentIdx >= 0 ? enabled[currentIdx]!.i : -1];
      if (active?.submenu?.length) {
        e.preventDefault();
        openSubmenu(enabled[currentIdx]!.i);
      } else if (e.key !== "ArrowRight" && active && !active.disabled) {
        e.preventDefault();
        onSelect(active.id);
      }
      return;
    }
    if (e.key === "ArrowLeft") {
      return; // top level has nowhere to go left to; submenu instance handles its own close
    }
    if (e.key.length === 1 && !e.metaKey && !e.ctrlKey && !e.altKey) {
      const now = Date.now();
      const ta = typeaheadRef.current;
      ta.buffer = now - ta.at < TYPEAHEAD_RESET_MS ? ta.buffer + e.key : e.key;
      ta.at = now;
      const match = closableItems.find((it) => it.label.toLowerCase().startsWith(ta.buffer.toLowerCase()));
      if (match) {
        const idx = items.indexOf(match);
        focusByIndex(idx);
      }
    }
  };

  const panelTop = clampTop(anchor.y, items.length * 38 + 16);
  const panelLeft = anchor.side === "right" ? anchor.x : anchor.x - ITEM_W;

  return (
    <div
      ref={panelRef}
      role="menu"
      aria-label={label}
      id={menuId}
      onKeyDown={onKeyDown}
      className="fixed z-[950] flex flex-col gap-0.5 rounded-[10px] border border-border bg-background p-1.5 shadow-lg"
      style={{ left: panelLeft, top: panelTop, width: ITEM_W }}
    >
      {items.map((item, i) => (
        <button
          key={item.id}
          ref={(el) => {
            itemRefs.current[i] = el;
          }}
          type="button"
          role="menuitem"
          disabled={item.disabled}
          aria-disabled={item.disabled}
          aria-haspopup={item.submenu ? "menu" : undefined}
          aria-expanded={item.submenu ? submenuIndex === i : undefined}
          tabIndex={-1}
          onMouseEnter={(e: ReactMouseEvent<HTMLButtonElement>) => {
            if (item.submenu?.length) openSubmenu(i);
            else closeSubmenu();
            e.currentTarget.focus({ preventScroll: true });
          }}
          onClick={() => {
            if (item.disabled) return;
            if (item.submenu?.length) openSubmenu(i);
            else onSelect(item.id);
          }}
          className="ns-jk-blade flex origin-left items-center justify-between gap-3 rounded-[6px] border border-transparent px-2.5 py-1.5 text-left text-xs text-foreground outline-none transition-colors hover:bg-border/40 focus-visible:bg-border/40 disabled:pointer-events-none disabled:opacity-40"
        >
          <span className="truncate">{item.label}</span>
          {item.shortcut && <span className="shrink-0 font-mono text-[10px] text-ns-muted">{item.shortcut}</span>}
          {item.submenu && !item.shortcut && <span className="shrink-0 text-[10px] text-ns-muted">{"›"}</span>}
        </button>
      ))}

      {submenuIndex !== null && submenuAnchor && items[submenuIndex]?.submenu && (
        <Blades
          items={items[submenuIndex]!.submenu!}
          anchor={submenuAnchor}
          label={`${items[submenuIndex]!.label} submenu`}
          onSelect={onSelect}
          onClose={(focusTrigger) => {
            closeSubmenu();
            if (focusTrigger) focusByIndex(submenuIndex);
          }}
          menuId={`${menuId}-sub`}
        />
      )}

      {!reduced && <style>{`.ns-jk-blade{transform-box:fill-box;}`}</style>}
    </div>
  );
}

export function JackKnife({ items, onSelect, children, label = "Actions", className = "" }: JackKnifeProps) {
  const autoId = useId();
  const menuId = `jk-menu-${autoId.replace(/:/g, "")}`;

  const triggerRef = useRef<HTMLButtonElement | null>(null);
  const [anchor, setAnchor] = useState<Anchor | null>(null);
  const [open, setOpen] = useState(false);

  const openAt = (x: number, y: number) => setAnchor(computeAnchor(x, y));

  useEffect(() => {
    setOpen(anchor !== null);
  }, [anchor]);

  useEffect(() => {
    if (!open) return;
    const onPointerDown = (e: PointerEvent) => {
      // scoped to this instance's own menu id (and its `-sub` descendants at
      // any depth) — a bare `[role="menu"]` query would match a SECOND
      // JackKnife instance's panel elsewhere on the page and incorrectly
      // treat a click inside THAT menu as "inside this one"
      const panels = document.querySelectorAll(`[id^="${menuId}"]`);
      const target = e.target as Node;
      const inside = Array.from(panels).some((p) => p.contains(target));
      if (!inside) setAnchor(null);
    };
    document.addEventListener("pointerdown", onPointerDown, true);
    return () => document.removeEventListener("pointerdown", onPointerDown, true);
  }, [open, menuId]);

  const handleSelect = (id: string) => {
    onSelect?.(id);
    setAnchor(null);
    triggerRef.current?.focus();
  };

  const handleClose = (focusTrigger: boolean) => {
    setAnchor(null);
    if (focusTrigger) triggerRef.current?.focus();
  };

  return (
    <div className={`relative inline-block ${className}`}>
      {children && (
        <div
          onContextMenu={(e: ReactMouseEvent) => {
            e.preventDefault();
            openAt(e.clientX, e.clientY);
          }}
        >
          {children}
        </div>
      )}

      <button
        ref={triggerRef}
        type="button"
        data-context-menu-unfold-trigger=""
        aria-haspopup="menu"
        aria-expanded={open}
        aria-controls={open ? menuId : undefined}
        onClick={(e: ReactMouseEvent<HTMLButtonElement>) => {
          const rect = e.currentTarget.getBoundingClientRect();
          openAt(rect.left, rect.bottom + 6);
        }}
        className="mt-3 rounded-[6px] border border-border px-2.5 py-1.5 text-xs text-foreground transition-colors hover:border-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
      >
        {label}
      </button>

      {open && anchor && (
        <Blades
          items={items}
          anchor={anchor}
          label={label}
          onSelect={handleSelect}
          onClose={handleClose}
          menuId={menuId}
        />
      )}
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
  type PointerEvent as ReactPointerEvent,
} from "react";

// ---------------------------------------------------------------------------
// ShimFit — prompt composition as fitting machinist's shims into a gap of
// fixed height (the context window). Every section (system / tools / memory
// / retrieved docs / user message) is a real DOM row whose height maps to its
// token count; stack order IS prompt order, reordered by drag or by a full
// keyboard listbox pattern (Space lifts, arrows move, Space drops) with FLIP
// transforms on every reorder. Remaining budget is a real empty clearance
// region above the stack, never a percentage bar. Inserting a tray candidate
// that would blow the budget elastically compresses the stack, springs the
// candidate back to the tray, pulses the largest truncatable row's edge, and
// opens a persistent "thin this one" remedy — no error string, a visible
// non-fit plus a suggested fix. Pure DOM/CSS, no canvas.
// ---------------------------------------------------------------------------

export interface ShimSection {
  id: string;
  label: string;
  tokens: number;
  /** may be offered as the trim target when an insert overflows */
  truncatable?: boolean;
  /** floor tokens can't be trimmed below; defaults to 30% of initial tokens */
  minTokens?: number;
}

export interface ShimFitProps {
  /** total context-window budget, in tokens */
  budget?: number;
  /** initial stack, top-to-bottom = prompt order */
  sections?: ShimSection[];
  /** candidates waiting in the tray, not yet part of the prompt */
  candidates?: ShimSection[];
  /** px per token for row height (min 8px floor still applies) */
  scale?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** accessible name for the stack */
  "aria-label"?: string;
}

// Floor a row at 16px, not 8px: an 8px row cannot contain its own ~14px label,
// so a thin row (e.g. a 120-token message) let its centered text bleed past the
// row and — being the last row, flush at the frame's clipped bottom edge — get
// severed by the frame's overflow-hidden. 16px holds the (hairline-sized) label
// cleanly; the stack still fits with clearance to spare.
const MIN_ROW_PX = 16;
const HAIRLINE_PX = 18;
const COMPRESS_MS = 120;
const FLIP_MS = 320;
const FLIP_EASE = "cubic-bezier(0.22,1,0.36,1)";
const PULSE_MS = 620;
const SUGGEST_DISMISS_MS = 9000;

const DEFAULT_SECTIONS: ShimSection[] = [
  { id: "system", label: "System prompt", tokens: 1200 },
  { id: "tools", label: "Tool definitions", tokens: 900, truncatable: true, minTokens: 300 },
  { id: "memory", label: "Memory", tokens: 1800, truncatable: true, minTokens: 400 },
  { id: "history", label: "Conversation history", tokens: 2400, truncatable: true, minTokens: 600 },
  { id: "user", label: "User message", tokens: 120 },
];

const DEFAULT_CANDIDATES: ShimSection[] = [
  { id: "incident", label: "Retrieved: incident postmortem", tokens: 2200, truncatable: true, minTokens: 500 },
  { id: "styleguide", label: "Retrieved: style guide excerpt", tokens: 500, truncatable: true, minTokens: 150 },
];

function fmt(n: number): string {
  return Math.round(n).toLocaleString("en-US");
}

// sum of rect heights (measured at drag start, heights don't change mid-drag)
// for every id preceding `id` in `order` — used to cancel out the dragged
// row's own DOM-flow shift when it swaps past a neighbor, so the transform
// keeps tracking the pointer instead of jumping by the neighbor's height.
function cumHeightBefore(order: string[], id: string, rects: Map<string, DOMRect>): number {
  let sum = 0;
  for (const oid of order) {
    if (oid === id) break;
    const r = rects.get(oid);
    if (r) sum += r.height;
  }
  return sum;
}

function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(mq.matches);
    update();
    mq.addEventListener("change", update);
    return () => mq.removeEventListener("change", update);
  }, []);
  return reduced;
}

const GripIcon = () => (
  <svg width="10" height="14" viewBox="0 0 10 14" fill="currentColor" aria-hidden>
    <circle cx="2.5" cy="2.5" r="1.4" />
    <circle cx="7.5" cy="2.5" r="1.4" />
    <circle cx="2.5" cy="7" r="1.4" />
    <circle cx="7.5" cy="7" r="1.4" />
    <circle cx="2.5" cy="11.5" r="1.4" />
    <circle cx="7.5" cy="11.5" r="1.4" />
  </svg>
);

type Rejection = {
  /** candidate that failed to insert */
  attemptedLabel: string;
  attemptedTokens: number;
  overBy: number;
  /** id of the row offered up as the trim target, if any is truncatable */
  suggestFor: string | null;
};

type DragState = {
  id: string;
  pointerId: number;
  startClientY: number;
  startRects: Map<string, DOMRect>;
  order: string[];
  /** live order as currently displayed; updates whenever a swap commits */
  currentOrder: string[];
  currentOrderKey: string;
  /** cumHeightBefore(order, id, startRects) at drag start — the zero-drift baseline */
  baseCum: number;
};

export function ShimFit({
  budget = 8000,
  sections = DEFAULT_SECTIONS,
  candidates = DEFAULT_CANDIDATES,
  scale = 0.06,
  className = "",
  "aria-label": ariaLabel = "Prompt composition",
}: ShimFitProps) {
  const reduced = useReducedMotion();
  const listboxId = useId();

  const [stack, setStack] = useState<ShimSection[]>(sections);
  const [tray, setTray] = useState<ShimSection[]>(candidates);
  const [liftedId, setLiftedId] = useState<string | null>(null);
  const [activeId, setActiveId] = useState<string>(sections[0]?.id ?? "");
  const [announce, setAnnounce] = useState("");
  const [alertMsg, setAlertMsg] = useState("");
  const [rejection, setRejection] = useState<Rejection | null>(null);
  const [pulseId, setPulseId] = useState<string | null>(null);
  const [compressed, setCompressed] = useState(false);
  const [bounceTrayId, setBounceTrayId] = useState<string | null>(null);

  const stackRef = useRef(stack);
  stackRef.current = stack;
  const rowElsRef = useRef<Map<string, HTMLDivElement>>(new Map());
  const dragRef = useRef<DragState | null>(null);
  const pendingFlipRef = useRef<{ prevRects: Map<string, DOMRect>; skip?: string } | null>(null);
  const pendingEnterRef = useRef<string | null>(null);
  const reducedRef = useRef(reduced);
  reducedRef.current = reduced;
  const pulseTimerRef = useRef<number | null>(null);
  const compressTimerRef = useRef<number | null>(null);
  const bounceTimerRef = useRef<number | null>(null);
  const suggestTimerRef = useRef<number | null>(null);

  useEffect(
    () => () => {
      if (pulseTimerRef.current) window.clearTimeout(pulseTimerRef.current);
      if (compressTimerRef.current) window.clearTimeout(compressTimerRef.current);
      if (bounceTimerRef.current) window.clearTimeout(bounceTimerRef.current);
      if (suggestTimerRef.current) window.clearTimeout(suggestTimerRef.current);
    },
    []
  );

  const registerRow = useCallback((id: string, el: HTMLDivElement | null) => {
    if (el) rowElsRef.current.set(id, el);
    else rowElsRef.current.delete(id);
  }, []);

  const rowHeight = useCallback((tokens: number) => Math.max(MIN_ROW_PX, tokens * scale), [scale]);

  const totalUsed = useMemo(() => stack.reduce((s, x) => s + x.tokens, 0), [stack]);
  const remaining = budget - totalUsed;
  const frameHeight = Math.max(120, budget * scale);
  const usedHeight = useMemo(
    () => stack.reduce((s, x) => s + rowHeight(x.tokens), 0),
    [stack, rowHeight]
  );
  const clearance = Math.max(0, frameHeight - usedHeight);

  // ---- FLIP: capture rects before a reorder, invert+play after DOM commit --
  const playFlip = useCallback((prevRects: Map<string, DOMRect>, skip?: string) => {
    for (const [id, el] of rowElsRef.current) {
      if (id === skip) continue;
      const before = prevRects.get(id);
      if (!before) continue;
      const after = el.getBoundingClientRect();
      const dy = before.top - after.top;
      if (Math.abs(dy) < 0.5) continue;
      if (reducedRef.current) continue;
      el.style.transition = "none";
      el.style.transform = `translateY(${dy}px)`;
      // eslint-disable-next-line @typescript-eslint/no-unused-expressions
      el.getBoundingClientRect(); // flush before re-enabling transition
      requestAnimationFrame(() => {
        el.style.transition = `transform ${FLIP_MS}ms ${FLIP_EASE}`;
        el.style.transform = "";
      });
    }
  }, []);

  useEffect(() => {
    const pending = pendingFlipRef.current;
    if (pending) {
      pendingFlipRef.current = null;
      playFlip(pending.prevRects, pending.skip);
    }
    const enterId = pendingEnterRef.current;
    if (enterId) {
      pendingEnterRef.current = null;
      const el = rowElsRef.current.get(enterId);
      if (el && !reducedRef.current) {
        el.style.transition = "none";
        el.style.opacity = "0";
        el.style.transform = `${el.style.transform || ""} translateY(6px)`.trim();
        el.getBoundingClientRect(); // flush
        requestAnimationFrame(() => {
          el.style.transition = `opacity 220ms ease-out, transform ${FLIP_MS}ms ${FLIP_EASE}`;
          el.style.opacity = "1";
          el.style.transform = "";
        });
      }
    }
  }, [stack, playFlip]);

  const captureRects = useCallback((skip?: string) => {
    const rects = new Map<string, DOMRect>();
    for (const s of stackRef.current) {
      if (s.id === skip) continue;
      const el = rowElsRef.current.get(s.id);
      if (el) rects.set(s.id, el.getBoundingClientRect());
    }
    return rects;
  }, []);

  const announceMove = useCallback(
    (id: string, order: ShimSection[]) => {
      const idx = order.findIndex((s) => s.id === id);
      const s = order[idx];
      if (!s) return;
      const used = order.reduce((sum, x) => sum + x.tokens, 0);
      setAnnounce(
        `${s.label.toLowerCase()}, position ${idx + 1} of ${order.length}, ${fmt(s.tokens)} tokens, ${fmt(
          budget - used
        )} remaining`
      );
    },
    [budget]
  );

  // -------------------------------------------------------------------------
  // keyboard: full reorderable-listbox pattern
  // -------------------------------------------------------------------------
  const moveFocus = useCallback((id: string, dir: -1 | 1) => {
    const order = stackRef.current;
    const idx = order.findIndex((s) => s.id === id);
    const next = order[idx + dir];
    if (next) setActiveId(next.id);
  }, []);

  const moveLifted = useCallback(
    (id: string, dir: -1 | 1) => {
      const order = stackRef.current;
      const idx = order.findIndex((s) => s.id === id);
      const newIdx = idx + dir;
      if (idx < 0 || newIdx < 0 || newIdx >= order.length) return;
      const prevRects = captureRects();
      const next = order.slice();
      const [item] = next.splice(idx, 1);
      next.splice(newIdx, 0, item);
      pendingFlipRef.current = { prevRects };
      setStack(next);
      announceMove(id, next);
    },
    [captureRects, announceMove]
  );

  const handleRowKeyDown = useCallback(
    (e: ReactKeyboardEvent<HTMLDivElement>, id: string) => {
      switch (e.key) {
        case " ":
        case "Spacebar":
          e.preventDefault();
          if (liftedId === id) {
            setLiftedId(null);
            const idx = stackRef.current.findIndex((s) => s.id === id);
            const s = stackRef.current[idx];
            if (s) setAnnounce(`${s.label.toLowerCase()} dropped at position ${idx + 1} of ${stackRef.current.length}`);
          } else {
            setLiftedId(id);
            const idx = stackRef.current.findIndex((s) => s.id === id);
            const s = stackRef.current[idx];
            if (s)
              setAnnounce(
                `${s.label.toLowerCase()} grabbed, position ${idx + 1} of ${stackRef.current.length}, ${fmt(s.tokens)} tokens`
              );
          }
          break;
        case "ArrowDown":
          e.preventDefault();
          if (liftedId === id) moveLifted(id, 1);
          else moveFocus(id, 1);
          break;
        case "ArrowUp":
          e.preventDefault();
          if (liftedId === id) moveLifted(id, -1);
          else moveFocus(id, -1);
          break;
        case "Escape":
          if (liftedId === id) {
            e.preventDefault();
            setLiftedId(null);
            setAnnounce(`${stackRef.current.find((s) => s.id === id)?.label.toLowerCase() ?? ""} drop cancelled`);
          }
          break;
      }
    },
    [liftedId, moveLifted, moveFocus]
  );

  // -------------------------------------------------------------------------
  // pointer drag reorder — grip is decorative/aria-hidden, keyboard already
  // covers reordering fully; live-swap by comparing the dragged center to
  // the other rows' rects captured once at drag start (heights don't change
  // mid-drag, only order does)
  // -------------------------------------------------------------------------
  const beginDrag = useCallback(
    (id: string, e: ReactPointerEvent<HTMLDivElement>) => {
      e.currentTarget.setPointerCapture(e.pointerId);
      const startRects = new Map<string, DOMRect>();
      for (const s of stackRef.current) {
        const el = rowElsRef.current.get(s.id);
        if (el) startRects.set(s.id, el.getBoundingClientRect());
      }
      const order = stackRef.current.map((s) => s.id);
      dragRef.current = {
        id,
        pointerId: e.pointerId,
        startClientY: e.clientY,
        startRects,
        order,
        currentOrder: order,
        currentOrderKey: order.join(","),
        baseCum: cumHeightBefore(order, id, startRects),
      };
      setLiftedId(id);
      const el = rowElsRef.current.get(id);
      if (el) {
        el.style.transition = "none";
        el.style.zIndex = "10";
        el.style.boxShadow = "0 10px 22px -10px rgba(0,0,0,0.35)";
      }
    },
    []
  );

  const moveDrag = useCallback((e: ReactPointerEvent<HTMLDivElement>) => {
    const drag = dragRef.current;
    if (!drag || e.pointerId !== drag.pointerId) return;
    const el = rowElsRef.current.get(drag.id);
    if (!el) return;
    const startRect = drag.startRects.get(drag.id);
    if (!startRect) return;
    const deltaY = e.clientY - drag.startClientY;
    const draggedCenter = startRect.top + startRect.height / 2 + deltaY;
    const others = drag.order.filter((x) => x !== drag.id);
    let targetIndex = others.length;
    for (let i = 0; i < others.length; i++) {
      const r = drag.startRects.get(others[i]);
      if (!r) continue;
      if (draggedCenter < r.top + r.height / 2) {
        targetIndex = i;
        break;
      }
    }
    const newOrder = [...others.slice(0, targetIndex), drag.id, ...others.slice(targetIndex)];
    const key = newOrder.join(",");
    if (key !== drag.currentOrderKey) {
      drag.currentOrderKey = key;
      drag.currentOrder = newOrder;
      const prevRects = captureRects(drag.id);
      pendingFlipRef.current = { prevRects, skip: drag.id };
      setStack((prev) => {
        const byId = new Map(prev.map((s) => [s.id, s]));
        return newOrder.map((oid) => byId.get(oid)!).filter(Boolean);
      });
    }

    // the dragged row's own natural (untransformed) top shifts by however
    // much it has swapped past its neighbors so far — cancel that drift out
    // so the row keeps tracking the pointer 1:1 instead of jumping by the
    // swapped neighbor's height every time the order commits.
    const drift = cumHeightBefore(drag.currentOrder, drag.id, drag.startRects) - drag.baseCum;
    el.style.transform = `translateY(${deltaY - drift}px)`;
  }, [captureRects]);

  const endDrag = useCallback(() => {
    const drag = dragRef.current;
    if (!drag) return;
    dragRef.current = null;
    const el = rowElsRef.current.get(drag.id);
    if (el) {
      el.style.transition = reducedRef.current ? "none" : `transform ${FLIP_MS}ms ${FLIP_EASE}, box-shadow 200ms ease-out`;
      el.style.transform = "";
      el.style.boxShadow = "";
      el.style.zIndex = "";
    }
    setLiftedId(null);
    announceMove(drag.id, stackRef.current);
  }, [announceMove]);

  // -------------------------------------------------------------------------
  // insert from tray — the signature over-budget moment
  // -------------------------------------------------------------------------
  const clearRejection = useCallback(() => {
    setRejection(null);
    if (suggestTimerRef.current) {
      window.clearTimeout(suggestTimerRef.current);
      suggestTimerRef.current = null;
    }
  }, []);

  const attemptInsert = useCallback(
    (candidateId: string) => {
      const candidate = tray.find((c) => c.id === candidateId);
      if (!candidate) return;
      const currentUsed = stackRef.current.reduce((s, x) => s + x.tokens, 0);
      const fits = currentUsed + candidate.tokens <= budget;

      if (fits) {
        clearRejection();
        const prevRects = captureRects();
        // retrieved docs land just ahead of the final turn, not tacked on
        // at the very end of the prompt
        const insertAt = Math.max(0, stackRef.current.length - 1);
        const next = stackRef.current.slice();
        next.splice(insertAt, 0, candidate);
        pendingFlipRef.current = { prevRects };
        pendingEnterRef.current = candidate.id;
        setStack(next);
        setTray((prev) => prev.filter((c) => c.id !== candidateId));
        setAnnounce(
          `${candidate.label.toLowerCase()} added, position ${insertAt + 1} of ${next.length}, ${fmt(
            candidate.tokens
          )} tokens, ${fmt(budget - (currentUsed + candidate.tokens))} remaining`
        );
        return;
      }

      const overBy = currentUsed + candidate.tokens - budget;
      const truncatables = stackRef.current.filter((s) => s.truncatable);
      const suggestion = truncatables.length
        ? truncatables.reduce((a, b) => (b.tokens > a.tokens ? b : a))
        : null;

      setRejection({
        attemptedLabel: candidate.label,
        attemptedTokens: candidate.tokens,
        overBy,
        suggestFor: suggestion?.id ?? null,
      });
      setAlertMsg(
        suggestion
          ? `Doesn't fit: ${candidate.label} needs ${fmt(overBy)} more tokens than the ${fmt(
              remaining
            )} free. Thin ${suggestion.label} to make room.`
          : `Doesn't fit: ${candidate.label} needs ${fmt(overBy)} more tokens than the ${fmt(remaining)} free.`
      );
      if (suggestTimerRef.current) window.clearTimeout(suggestTimerRef.current);
      suggestTimerRef.current = window.setTimeout(clearRejection, SUGGEST_DISMISS_MS);

      if (!reducedRef.current) {
        setCompressed(true);
        if (compressTimerRef.current) window.clearTimeout(compressTimerRef.current);
        compressTimerRef.current = window.setTimeout(() => setCompressed(false), COMPRESS_MS);

        setBounceTrayId(candidateId);
        if (bounceTimerRef.current) window.clearTimeout(bounceTimerRef.current);
        bounceTimerRef.current = window.setTimeout(() => setBounceTrayId(null), 420);

        if (suggestion) {
          setPulseId(suggestion.id);
          if (pulseTimerRef.current) window.clearTimeout(pulseTimerRef.current);
          pulseTimerRef.current = window.setTimeout(() => setPulseId(null), PULSE_MS);
        }
      }
    },
    [tray, budget, remaining, captureRects, clearRejection]
  );

  const trimSection = useCallback(
    (id: string, newTokens: number) => {
      setStack((prev) =>
        prev.map((s) => {
          if (s.id !== id) return s;
          const floor = s.minTokens ?? Math.round(s.tokens * 0.3);
          return { ...s, tokens: Math.max(floor, Math.round(newTokens)) };
        })
      );
    },
    []
  );

  const trimToFit = useCallback(
    (r: Rejection) => {
      const target = stackRef.current.find((s) => s.id === r.suggestFor);
      if (!target) return;
      const floor = target.minTokens ?? Math.round(target.tokens * 0.3);
      const wanted = target.tokens - r.overBy;
      const nextTokens = Math.max(floor, wanted);
      trimSection(target.id, nextTokens);
      setAnnounce(`${target.label.toLowerCase()} trimmed to ${fmt(nextTokens)} tokens`);
      clearRejection();
    },
    [trimSection, clearRejection]
  );

  const trimThird = useCallback(
    (r: Rejection) => {
      const target = stackRef.current.find((s) => s.id === r.suggestFor);
      if (!target) return;
      const nextTokens = target.tokens * 0.7;
      const floor = target.minTokens ?? Math.round(target.tokens * 0.3);
      trimSection(target.id, Math.max(floor, nextTokens));
      setAnnounce(`${target.label.toLowerCase()} trimmed by 30%`);
      clearRejection();
    },
    [trimSection, clearRejection]
  );

  const suggestSection = rejection ? stack.find((s) => s.id === rejection.suggestFor) ?? null : null;

  return (
    <div className={`flex flex-col gap-4 font-sans ${className}`}>
      <p className="sr-only" aria-live="polite">
        {announce}
      </p>
      <p className="sr-only" role="alert">
        {alertMsg}
      </p>

      <div className="flex items-baseline justify-between font-mono text-[11px] text-ns-muted">
        <span>budget {fmt(budget)} tok</span>
        <span className={remaining < 0 ? "text-foreground font-semibold" : ""}>
          {fmt(Math.max(0, remaining))} tok free
        </span>
      </div>

      <div className="overflow-hidden rounded-md border border-border" style={{ height: frameHeight }}>
        {/* clearance: the genuinely empty part of the gap, drawn as real space */}
        <div
          aria-hidden
          className="flex items-start justify-center border-b border-dashed border-border/70"
          style={{ height: clearance }}
        >
          {clearance > 22 ? (
            <span className="mt-1 font-mono text-[9px] uppercase tracking-[0.14em] text-ns-muted/70">
              clearance
            </span>
          ) : null}
        </div>

        <div
          role="listbox"
          id={listboxId}
          aria-label={ariaLabel}
          aria-orientation="vertical"
          className="flex flex-col transition-transform"
          style={{
            transformOrigin: "bottom",
            transform: compressed ? "scaleY(0.98)" : "scaleY(1)",
            transitionDuration: compressed ? `${COMPRESS_MS}ms` : "160ms",
            transitionTimingFunction: FLIP_EASE,
          }}
        >
          {stack.map((s) => {
            const h = rowHeight(s.tokens);
            const hairline = h < HAIRLINE_PX;
            const isLifted = liftedId === s.id;
            const isPulsing = pulseId === s.id;
            return (
              <div
                key={s.id}
                ref={(el) => registerRow(s.id, el)}
                role="option"
                aria-roledescription="prompt section"
                aria-selected={isLifted}
                tabIndex={activeId === s.id ? 0 : -1}
                onFocus={() => setActiveId(s.id)}
                onKeyDown={(e) => handleRowKeyDown(e, s.id)}
                data-shim-row
                className={`relative flex items-center gap-2 border-t bg-ns-muted/8 px-2 outline-none transition-colors hover:bg-ns-muted/16 focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-inset ${
                  isLifted ? "border-t-ns-accent bg-ns-accent/5" : isPulsing ? "border-t-foreground" : "border-t-border"
                } ${isPulsing && !reduced ? "context-prompt-shims-pulse" : ""}`}
                style={{ height: h }}
              >
                <div
                  aria-hidden="true"
                  className="flex shrink-0 cursor-grab touch-none items-center justify-center self-stretch overflow-hidden px-0.5 text-ns-muted/60 active:cursor-grabbing"
                  style={hairline ? { transform: `scale(${Math.min(1, Math.max(0.5, h / 14))})` } : undefined}
                  onPointerDown={(e) => beginDrag(s.id, e)}
                  onPointerMove={moveDrag}
                  onPointerUp={endDrag}
                  onPointerCancel={endDrag}
                >
                  <GripIcon />
                </div>
                <span className={`min-w-0 flex-1 truncate text-foreground ${hairline ? "text-[10px]" : "text-xs"}`}>
                  {s.label}
                </span>
                <span
                  className={`shrink-0 font-mono tabular-nums text-ns-muted ${hairline ? "text-[9px]" : "text-[10px]"}`}
                >
                  {fmt(s.tokens)}
                </span>
                {reduced && rejection?.suggestFor === s.id ? (
                  <span
                    aria-hidden
                    className="absolute -right-1 -top-1 h-2 w-2 rounded-full bg-foreground"
                  />
                ) : null}
              </div>
            );
          })}
        </div>
      </div>

      {rejection ? (
        <div
          role="group"
          aria-label="Truncation suggestion"
          data-shim-suggestion
          className="flex flex-wrap items-center gap-2 rounded-md border border-foreground/25 bg-surface px-3 py-2"
        >
          <p className="flex-1 text-xs leading-snug text-foreground">
            <strong>{rejection.attemptedLabel}</strong> needs {fmt(rejection.overBy)} more tokens than fits.
            {suggestSection ? (
              <>
                {" "}
                Thin <strong>{suggestSection.label}</strong>?
              </>
            ) : null}
          </p>
          {suggestSection ? (
            <>
              <button
                type="button"
                onClick={() => trimToFit(rejection)}
                className="rounded-sm px-2 py-1 text-[11px] font-medium text-foreground outline-none transition-colors hover:bg-foreground/10 focus-visible:ring-2 focus-visible:ring-ns-accent"
              >
                Trim to fit
              </button>
              <button
                type="button"
                onClick={() => trimThird(rejection)}
                className="rounded-sm px-2 py-1 text-[11px] text-ns-muted outline-none transition-colors hover:bg-foreground/10 focus-visible:ring-2 focus-visible:ring-ns-accent"
              >
                Trim 30%
              </button>
            </>
          ) : null}
          <button
            type="button"
            aria-label="Dismiss suggestion"
            onClick={clearRejection}
            className="rounded-sm p-1 text-ns-muted outline-none transition-colors hover:bg-foreground/10 focus-visible:ring-2 focus-visible:ring-ns-accent"
          >
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" aria-hidden>
              <path d="M18 6 6 18M6 6l12 12" />
            </svg>
          </button>
        </div>
      ) : null}

      {tray.length > 0 ? (
        <div className="flex flex-col gap-1.5">
          <span className="font-mono text-[10px] uppercase tracking-[0.14em] text-ns-muted">Tray</span>
          <div className="flex flex-col gap-1.5">
            {tray.map((c) => {
              const bouncing = bounceTrayId === c.id && !reduced;
              const overflows = totalUsed + c.tokens > budget;
              return (
                <div
                  key={c.id}
                  className={`flex items-center gap-2 rounded-sm border border-border bg-background px-2.5 py-1.5 transition-transform ${
                    bouncing ? "context-prompt-shims-bounce" : ""
                  }`}
                >
                  <span className="min-w-0 flex-1 truncate text-xs text-foreground">{c.label}</span>
                  <span className="shrink-0 font-mono text-[10px] tabular-nums text-ns-muted">{fmt(c.tokens)}</span>
                  <button
                    type="button"
                    data-shim-insert
                    data-shim-insert-id={c.id}
                    {...(overflows ? { "data-shim-insert-oversized": "" } : {})}
                    onClick={() => attemptInsert(c.id)}
                    aria-label={`Insert ${c.label} (${fmt(c.tokens)} tokens)`}
                    className="shrink-0 rounded-sm border border-border px-2 py-1 text-[11px] font-medium text-foreground outline-none transition-colors hover:border-ns-accent hover:text-ns-accent focus-visible:ring-2 focus-visible:ring-ns-accent"
                  >
                    Insert
                  </button>
                </div>
              );
            })}
          </div>
        </div>
      ) : null}

      <style>{`
        @keyframes context-prompt-shims-pulse-kf {
          0% { border-top-color: var(--border); }
          30% { border-top-color: var(--foreground); }
          100% { border-top-color: var(--border); }
        }
        .context-prompt-shims-pulse { animation: context-prompt-shims-pulse-kf ${PULSE_MS}ms ease-out 1; }
        @keyframes context-prompt-shims-bounce-kf {
          0% { transform: translateY(0) scale(1); }
          30% { transform: translateY(-6px) scale(1.02); }
          60% { transform: translateY(2px) scale(0.99); }
          100% { transform: translateY(0) scale(1); }
        }
        .context-prompt-shims-bounce { animation: context-prompt-shims-bounce-kf 420ms ${FLIP_EASE} 1; }
        @media (prefers-reduced-motion: reduce) {
          .context-prompt-shims-pulse, .context-prompt-shims-bounce { animation: none; }
        }
      `}</style>
    </div>
  );
}

"use client";

import { Fragment, useEffect, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// ContraStrike — an order's line-item ledger, rendered as a real <table>,
// where a partial refund is recorded the way bookkeepers actually record one:
// nothing about the original entry is ever touched. Dragging along a line's
// amount bar arms a struck fraction `s` (a single governing scalar) that
// simultaneously sizes the refund figure, the length of an SVG rule crossing
// the amount, and — once a real "Refund $x" button commits it — the width of
// a brand-new contra row's own bar on the SAME money-per-px scale. The
// struck row's DOM node is never edited or removed: its figures stay exactly
// as billed, decorated (not deleted) with a permanent line-through, and the
// correction lives one row down, forever, in Geist Mono with a leading
// minus. Quantity lines snap the drag to whole units (2 of 6, never 2.4 of
// 6); a flat line with no quantity snaps to the cent instead. The rule stays
// dashed for as long as the row is only armed, not booked — a mid-drag
// selection must never read as an already-settled correction — and turns
// solid at the same instant the contra row is appended and the balance
// re-derives.
// ---------------------------------------------------------------------------

export interface ContraStrikeLine {
  id: string;
  /** line description, e.g. "Wireless Mouse ×6" */
  description: string;
  /** unit count on this line — 1 for a flat/non-quantity line */
  qty: number;
  /** price per unit, dollars */
  unitPrice: number;
  /** seed this line as already armed (dragged, not yet committed), 0-1 */
  defaultStruck?: number;
  /** seed this line as already refunded at mount — contra row renders open,
   * no animation, matching how a history feed replays a past decision */
  committedStruck?: number;
}

export interface ContraStrikeProps {
  /** heading shown above the ledger, e.g. "Order #4471" */
  orderLabel?: string;
  /** the order's line items */
  lines: ContraStrikeLine[];
  /** ISO currency code passed to Intl.NumberFormat */
  currency?: string;
  /** BCP 47 locale passed to Intl.NumberFormat — always explicit, never the
   * runtime default, so server and client render identical digits */
  locale?: string;
  /** fired once per line the moment its contra row is committed */
  onCommit?: (line: ContraStrikeLine, refundAmount: number, struckUnits: number) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

type LineState = {
  input: ContraStrikeLine;
  amount: number;
  struck: number; // 0-1, the armed/committed fraction — the one governing scalar
  dragging: boolean;
  committed: boolean;
  contraOpen: boolean; // flips true one frame after `committed` so the height
  // transition has a 0-height frame to animate FROM, per prevailing bug
};

const TRACK_W = 148; // px — the shared money-per-px track width every bar maps onto
const ROW_H = 30; // px — fixed row height, both the original and contra rows

function clamp(v: number, lo: number, hi: number) {
  return Math.min(hi, Math.max(lo, v));
}

function snapFraction(raw: number, qty: number, amount: number): number {
  const r = clamp(raw, 0, 1);
  if (qty > 1) {
    const k = Math.round(r * qty);
    return clamp(k / qty, 0, 1);
  }
  const cents = Math.round(amount * 100);
  if (cents <= 0) return 0;
  const c = Math.round(r * cents);
  return clamp(c / cents, 0, 1);
}

function stepFraction(qty: number, amount: number): number {
  if (qty > 1) return 1 / qty;
  const cents = Math.round(amount * 100);
  return cents > 0 ? 1 / cents : 0;
}

export function ContraStrike({
  orderLabel = "Order",
  lines,
  currency = "USD",
  locale = "en-US",
  onCommit,
  className = "",
}: ContraStrikeProps) {
  const money = useMemo(() => {
    const fmt = new Intl.NumberFormat(locale, { style: "currency", currency });
    return (v: number) => fmt.format(v);
  }, [locale, currency]);

  const [rows, setRows] = useState<LineState[]>(() =>
    lines.map((input) => {
      const amount = input.qty * input.unitPrice;
      const committed = input.committedStruck !== undefined;
      const struck = committed
        ? clamp(input.committedStruck as number, 0, 1)
        : clamp(input.defaultStruck ?? 0, 0, 1);
      return { input, amount, struck, dragging: false, committed, contraOpen: committed };
    })
  );

  const maxAmount = useMemo(
    () => Math.max(1, ...rows.map((r) => r.amount)),
    [rows]
  );
  const scale = TRACK_W / maxAmount;
  const barPx = (amount: number) => Math.max(2, amount * scale);

  const [reducedMotion, setReducedMotion] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReducedMotion(mq.matches);
    const onChange = () => setReducedMotion(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  const [announcement, setAnnouncement] = useState("");
  const [flashIdx, setFlashIdx] = useState<number | null>(null);
  const [balanceFlash, setBalanceFlash] = useState(false);
  const flashTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => () => {
    if (flashTimer.current) clearTimeout(flashTimer.current);
  }, []);

  function updateStruck(idx: number, raw: number, dragging: boolean) {
    setRows((prev) =>
      prev.map((r, i) => {
        if (i !== idx || r.committed) return r;
        const q = snapFraction(raw, r.input.qty, r.amount);
        return { ...r, struck: q, dragging };
      })
    );
  }

  function trackDrag(idx: number, clientX: number, dragging: boolean) {
    const el = trackRefs.current[idx];
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const raw = rect.width > 0 ? (clientX - rect.left) / rect.width : 0;
    updateStruck(idx, raw, dragging);
  }

  const trackRefs = useRef<(HTMLDivElement | null)[]>([]);

  // Reads the outer `rows` state, not the updater's `prev`: every side effect
  // (onCommit, the announcement, the flash timer, the rAF pair) runs exactly
  // once per click, in the function body — never inside setRows' updater,
  // which React is free to invoke more than once. An append-only ledger that
  // fired its own commit callback twice would be the exact bug this
  // component exists to prevent.
  function commitLine(idx: number) {
    const row = rows[idx];
    if (!row || row.committed || row.struck <= 0) return;
    const refundAmount = row.amount * row.struck;
    const struckUnits = row.input.qty > 1 ? Math.round(row.struck * row.input.qty) : 0;
    const newRefunded = rows.reduce(
      (s, r, i) => s + (i === idx ? refundAmount : r.committed ? r.amount * r.struck : 0),
      0
    );

    setRows((prev) => {
      const cur = prev[idx];
      if (!cur || cur.committed) return prev; // idempotence guard, belt-and-braces
      return prev.map((r, i) =>
        i === idx ? { ...r, committed: true, contraOpen: reducedMotion } : r
      );
    });

    onCommit?.(row.input, refundAmount, struckUnits);
    setAnnouncement(
      `Refund recorded: −${money(refundAmount)} for ${row.input.description}. New balance ${money(subtotal - newRefunded)}.`
    );
    if (flashTimer.current) clearTimeout(flashTimer.current);
    setFlashIdx(idx);
    setBalanceFlash(true);
    flashTimer.current = setTimeout(() => {
      setFlashIdx(null);
      setBalanceFlash(false);
    }, 500);
    if (!reducedMotion) {
      // two rAFs: the first lets the browser paint the just-mounted,
      // zero-height contra row; only the second flips it open, so the
      // height transition has a real starting frame to animate from
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          setRows((cur) => cur.map((r, i) => (i === idx ? { ...r, contraOpen: true } : r)));
        });
      });
    }
  }

  function onTrackKeyDown(e: React.KeyboardEvent, idx: number) {
    const row = rows[idx];
    if (!row || row.committed) return;
    const step = stepFraction(row.input.qty, row.amount);
    let next: number | null = null;
    switch (e.key) {
      case "ArrowRight":
      case "ArrowUp":
        next = row.struck + step;
        break;
      case "ArrowLeft":
      case "ArrowDown":
        next = row.struck - step;
        break;
      case "PageUp":
        next = row.struck + step * (row.input.qty > 1 ? 1 : 10);
        break;
      case "PageDown":
        next = row.struck - step * (row.input.qty > 1 ? 1 : 10);
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = 1;
        break;
      default:
        return;
    }
    e.preventDefault();
    updateStruck(idx, clamp(next, 0, 1), false);
  }

  const subtotal = rows.reduce((s, r) => s + r.amount, 0);
  const refunded = rows.reduce((s, r) => (r.committed ? s + r.amount * r.struck : s), 0);
  const balance = subtotal - refunded;

  return (
    <div className={`w-full ${className}`}>
      <style>{`
@keyframes ns-cs-contra-row{from{opacity:0}to{opacity:1}}
.ns-cs-contra{transition:height 320ms cubic-bezier(0.16,1,0.3,1), opacity 320ms cubic-bezier(0.16,1,0.3,1);overflow:hidden}
.ns-cs-rule{transition:opacity 180ms ease-out}
@keyframes ns-cs-flash{0%{opacity:.35}100%{opacity:0}}
.ns-cs-flash::after{content:"";position:absolute;inset:-2px -6px;background:var(--ns-accent);opacity:0;border-radius:6px;animation:ns-cs-flash 480ms ease-out;pointer-events:none}
@media (prefers-reduced-motion: reduce){
  .ns-cs-contra{transition:none}
  .ns-cs-rule{transition:none}
  .ns-cs-flash::after{animation:none}
}
`}</style>

      <div className="mb-2 flex items-baseline justify-between">
        <h3 className="font-mono text-sm font-medium text-foreground">{orderLabel}</h3>
        <span className="font-mono text-xs text-ns-muted">line-item ledger</span>
      </div>

      <div className="overflow-x-auto rounded-md border border-border">
        <table className="w-full border-collapse text-left">
          <caption className="sr-only">
            {orderLabel} line-item ledger with per-line partial refund. Refunds append a
            contra entry below the original line rather than editing it.
          </caption>
          <thead>
            <tr className="border-b border-border">
              <th scope="col" className="px-3 py-2 font-mono text-xs font-normal text-ns-muted">
                Item
              </th>
              <th scope="col" className="px-3 py-2 text-right font-mono text-xs font-normal text-ns-muted">
                Qty
              </th>
              <th scope="col" className="px-3 py-2 font-mono text-xs font-normal text-ns-muted">
                Amount
              </th>
              <th scope="col" className="px-3 py-2 font-mono text-xs font-normal text-ns-muted">
                <span className="sr-only">Refund action</span>
              </th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row, idx) => {
              const { input, amount, struck, committed, dragging, contraOpen } = row;
              const refundAmount = amount * struck;
              const bar = barPx(amount);
              const ruleLen = struck * bar;
              const struckUnits = input.qty > 1 ? Math.round(struck * input.qty) : 0;
              const valueText =
                input.qty > 1
                  ? `${money(refundAmount)} of ${money(amount)}, ${struckUnits} of ${input.qty} units`
                  : `${money(refundAmount)} of ${money(amount)}`;
              const armed = struck > 0;
              const flashing = flashIdx === idx;

              return (
                <Fragment key={input.id}>
                  <tr
                    className={
                      "border-b border-border last:border-b-0" +
                      (committed ? " align-top" : "")
                    }
                    {...(committed
                      ? { "aria-description": "partially refunded, see contra entry below" }
                      : {})}
                  >
                    <th scope="row" className="px-3 py-2 align-top font-mono text-xs font-normal text-foreground">
                      {input.description}
                    </th>
                    <td className="px-3 py-2 text-right align-top font-mono text-xs tabular-nums text-ns-muted">
                      {input.qty}
                    </td>
                    <td className="px-3 py-2 align-top">
                      {/* the interactive slider below is entirely aria-hidden
                      inside (aria-valuetext is its single source of truth for
                      AT); this sibling restores the cell's plain reading-mode
                      data — the billed amount, struck once refunded — so the
                      row stays real, walkable table content and not just a
                      widget's private value */}
                      <span className="sr-only">
                        {money(amount)}
                        {committed ? ", struck, see contra entry below" : ""}
                      </span>
                      <div
                        ref={(el) => {
                          trackRefs.current[idx] = el;
                        }}
                        data-track={idx}
                        role="slider"
                        tabIndex={committed ? -1 : 0}
                        aria-disabled={committed || undefined}
                        aria-label={`Refund ${input.description}`}
                        aria-orientation="horizontal"
                        aria-valuemin={0}
                        aria-valuemax={100}
                        aria-valuenow={Math.round(struck * 100)}
                        aria-valuetext={valueText}
                        onKeyDown={(e) => onTrackKeyDown(e, idx)}
                        onPointerDown={(e) => {
                          if (committed) return;
                          e.preventDefault();
                          e.currentTarget.setPointerCapture(e.pointerId);
                          trackDrag(idx, e.clientX, true);
                        }}
                        onPointerMove={(e) => {
                          if (!dragging) return;
                          trackDrag(idx, e.clientX, true);
                        }}
                        onPointerUp={() => updateStruck(idx, struck, false)}
                        onPointerCancel={() => updateStruck(idx, struck, false)}
                        style={{ width: TRACK_W, height: ROW_H }}
                        className={
                          "relative select-none rounded-sm outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background" +
                          (committed
                            ? " cursor-default"
                            : " cursor-ew-resize touch-none hover:bg-foreground/[0.035]") +
                          (flashing ? " ns-cs-flash" : "")
                        }
                      >
                        {/* the slider's own visual layers (bar, numeral, rule)
                        carry no text to assistive tech — aria-valuetext above
