.ns-fdg-question{min-width:0;transition:color 160ms ease;}

.ns-fdg-sign{position:relative;flex:0 0 10px;width:10px;height:10px;}
.ns-fdg-sign-h,.ns-fdg-sign-v{position:absolute;left:0;top:0;background-color:var(--ns-muted);}
.ns-fdg-sign-h{width:10px;height:1.5px;top:4.25px;}
.ns-fdg-sign-v{width:1.5px;height:10px;left:4.25px;transition:transform 200ms ${EASE};transform-origin:center;}
.ns-fdg-sign[data-open="true"] .ns-fdg-sign-v{transform:scaleY(0);}

.ns-fdg-panel{overflow:hidden;height:0;}
.ns-fdg-panel[hidden]{display:none;}
.ns-fdg-answer{padding:0 0 20px 0;color:var(--ns-muted);font-size:13.5px;line-height:1.65;}
.ns-fdg-answer p{margin:0;}
.ns-fdg-answer p + p{margin-top:11px;}

@media (prefers-reduced-motion: reduce){
  .ns-fdg-sign-v,.ns-fdg-question{transition-duration:0ms !important;}
}
`;

"use client";

import { useEffect, useRef } from "react";
import type { CSSProperties } from "react";

// ---------------------------------------------------------------------------
// FaxLineSlip — a document-preview / attachment-thumbnail loading state
// reproducing a Group 3 fax handshake and page transmission, not a generic
// spinner or shimmer. Source: ITU-T T.30 handshake tones (calling machine
// sends a pulsed CNG tone, the answering machine holds a CED tone) followed
// by the page transmitting as sequential horizontal scan lines at the
// negotiated modem rate, plus the documented thermal-fax mechanical fault
// where the paper momentarily slips through the feed rollers mid-page,
// shearing a thin band of the received image sideways before lines resume
// true.
//
// One cycle, four phases, drawn onto a single persistent canvas that is
// never cleared mid-build (a real received page is composed, not repainted):
//
// 1. Handshake (2200ms): a waveform trace occupies the top ~15% of the
//    frame. A tight-period sine burst stands in for the 1100Hz CNG tone
//    (500ms), a silent 500ms gap, then a tighter-period burst stands in for
//    the 2100Hz CED tone (1200ms) — 500+500+1200 = 2200ms exactly, drawn at
//    human-followable pace because it already is one (not sped up).
// 2. Scan build: one scan line commits every 45ms (~22 lines/sec — real G3
//    at 9600bps is ~5-6 lines/sec, but rendering 220 lines at that real rate
//    would take ~40s, unbearably slow for a resting loop, so this is
//    compressed for pace, not decoupled for alias-avoidance). Line count is
//    derived from the container's own smaller dimension (one line per ~2px
//    of height, capped at 220) so the build reads at card scale. At a
//    randomized point 55-75% down the frame, one 3-line band commits with a
//    hard 14-22px horizontal offset baked permanently into those three
//    lines — the paper-slip artifact — then the very next line resumes at
//    zero offset with no easing, because a real slip is a sudden mechanical
//    discontinuity, not a glitch that repeats.
// 3. Hold (1800ms): the fully composed page sits still.
// 4. Reset (200ms): the frame does not fade — it clears top-to-bottom in one
//    wipe, mirroring a fresh page feeding in, then the handshake replays
//    with a freshly reseeded page and a freshly randomized slip position.
//
// The "document" content itself is a procedural stand-in for scanned text —
// deterministic hash-derived horizontal strokes with word-like gaps, grouped
// into text lines with occasional paragraph breaks — reseeded every cycle so
// no two received pages look identical. `--ns-accent` never appears; ink is
// `--foreground` over a `--background` field, read live via
// getComputedStyle + a MutationObserver on the theme class, matching the dark
// marks on light stock a real thermal print reads (dark theme inverts the
// relationship rather than swapping which token is which).
// ---------------------------------------------------------------------------

export interface FaxLineSlipProps {
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** inline styles merged onto the root element */
  style?: CSSProperties;
  /** sr-only status text describing the loading state */
  label?: string;
}

type RGB = [number, number, number];

function parseColor(raw: string): RGB | null {
  const s = raw.trim();
  if (s.startsWith("#")) {
    let hex = s.slice(1);
    if (hex.length === 3) hex = hex.split("").map((c) => c + c).join("");
    if (hex.length < 6) return null;
    const r = parseInt(hex.slice(0, 2), 16);
    const g = parseInt(hex.slice(2, 4), 16);
    const b = parseInt(hex.slice(4, 6), 16);
    return Number.isNaN(r + g + b) ? null : [r, g, b];
  }
  const m = s.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
}

function hash01(x: number, y: number): number {
  const n = Math.sin(x * 127.1 + y * 311.7) * 43758.5453123;
  return n - Math.floor(n);
}

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// -- handshake timing: 500ms CNG-stand-in burst, 500ms silence, 1200ms
// CED-stand-in burst — total 2200ms, real ITU-T T.30 pace, not compressed. --
const BURST1_MS = 500;
const GAP_MS = 500;
const BURST2_MS = 1200;
const HANDSHAKE_MS = BURST1_MS + GAP_MS + BURST2_MS; // 2200ms
const BURST1_CYCLES = 15; // tight-period trace standing in for 1100Hz
const BURST2_CYCLES = 28; // tighter-period trace standing in for 2100Hz

// -- scan build: one committed line every 45ms, capped at 220 for card scale --
const LINE_INTERVAL_MS = 45;
const MAX_LINES = 220;
const MIN_LINES = 30;
const SLIP_BAND_LINES = 3;
const SLIP_MIN_PX = 14;
const SLIP_MAX_PX = 22;
const SLIP_RANGE_START = 0.55; // fraction down the frame the slip may start
const SLIP_RANGE_SPAN = 0.2; // 0.55 - 0.75

const HOLD_MS = 1800;
const WIPE_MS = 200;

export function FaxLineSlip({ className = "", style, label = "Connecting" }: FaxLineSlipProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    let reduced = mq.matches;

    // -- token-derived ink/paper: read at mount, re-derived on theme change --
    let fg: RGB = [0, 0, 0];
    let bg: RGB = [255, 255, 255];
    let fgCSS = "rgb(0,0,0)";
    let bgCSS = "rgb(255,255,255)";
    const derive = () => {
      const cs = getComputedStyle(document.documentElement);
      fg = parseColor(cs.getPropertyValue("--foreground")) ?? fg;
      bg = parseColor(cs.getPropertyValue("--background")) ?? bg;
      fgCSS = `rgb(${fg[0]},${fg[1]},${fg[2]})`;
      bgCSS = `rgb(${bg[0]},${bg[1]},${bg[2]})`;
    };
    derive();

    let w = 0;
    let h = 0;
    let dpr = 1;
    let lineCount = MIN_LINES;
    let rowH = 1;
    let letterCell = 3;
    let lineSpacing = 7;
    let marginPx = 6;

    let seed = 0;
    let slipStartLine = -1;
    let slipOffsetPx = 0;
    let cycleBase = 0;
    let cycleIndex = 0;
    let lastLineDrawn = -1;
    let scanCleared = false;

    let raf = 0;
    let visible = true;

    // -- one procedurally-baked text line's metadata: blank (paragraph gap)
    // or a right margin fraction, deterministic per lineIndex+seed so every
    // raster row belonging to that text line agrees on its shape. ----------
    const lineMeta = (lineIndex: number) => {
      const blankRoll = hash01(lineIndex * 1.7 + seed, 3.1);
      if (blankRoll < 0.12) return { blank: true, widthFrac: 0 };
      const widthFrac = 0.45 + hash01(lineIndex * 2.3 + seed, 7.7) * 0.45;
      return { blank: false, widthFrac };
    };

    // -- commit one raster row of the document's baked content, offset in x
    // by xOffsetPx when this row falls inside the current cycle's slip band. --
    const drawDocumentRow = (y0: number, y1: number, xOffsetPx: number) => {
      const midY = (y0 + y1) / 2;
      const lineIndex = Math.floor(midY / lineSpacing);
      const meta = lineMeta(lineIndex);
      if (meta.blank) return;
      const bandFrac = (midY - lineIndex * lineSpacing) / lineSpacing;
      if (bandFrac > 0.5) return; // gap between text lines
      const usableW = w - marginPx * 2;
      const rightEdge = marginPx + meta.widthFrac * usableW;
      ctx.fillStyle = fgCSS;
      for (let x = marginPx; x < rightEdge; x += letterCell) {
        const bucket = Math.floor(x / letterCell);
        const v = hash01(lineIndex * 5.13 + seed, bucket * 3.71 + seed);
        if (v > 0.34) {
          ctx.fillRect(x + xOffsetPx, y0, letterCell * 0.82, Math.max(1, y1 - y0));
        }
      }
    };

    const clearCanvas = () => {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.fillStyle = bgCSS;
      ctx.fillRect(0, 0, w, h);
    };

    const commitLine = (lineIdx: number) => {
      const y0 = lineIdx * rowH;
      const y1 = y0 + rowH;
      const inSlip = lineIdx >= slipStartLine && lineIdx < slipStartLine + SLIP_BAND_LINES;
      drawDocumentRow(y0, y1, inSlip ? slipOffsetPx : 0);
    };

    const drawWaveform = (t: number) => {
      const bandH = h * 0.15;
      ctx.fillStyle = bgCSS;
      ctx.fillRect(0, 0, w, bandH);
      const midY = bandH * 0.5;
      const amp = bandH * 0.32;
      ctx.strokeStyle = fgCSS;
      ctx.lineWidth = Math.max(1, Math.min(w, h) / 220);

      const drawBurst = (revealFrac: number, cycles: number) => {
        if (revealFrac <= 0) return;
        const revealW = w * revealFrac;
        const steps = Math.max(2, Math.floor(revealW / 2));
        ctx.beginPath();
        for (let i = 0; i <= steps; i++) {
          const x = (i / steps) * revealW;
          const phase = (x / w) * cycles * Math.PI * 2;
          const y = midY + Math.sin(phase) * amp;
          if (i === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
        ctx.stroke();
      };

      if (t < BURST1_MS) {
        drawBurst(t / BURST1_MS, BURST1_CYCLES);
      } else if (t < BURST1_MS + GAP_MS) {
        // silent gap — band stays clear
      } else {
        const t2 = t - BURST1_MS - GAP_MS;
        drawBurst(Math.min(1, t2 / BURST2_MS), BURST2_CYCLES);
      }
    };

    const drawWipe = (frac: number) => {
      ctx.fillStyle = bgCSS;
      ctx.fillRect(0, 0, w, h * frac);
    };

    const reseedCycle = () => {
      seed = cycleIndex * 811.7;
      const rand = mulberry32(0x9e3779b9 ^ (cycleIndex + 1));
      slipStartLine = Math.max(
        0,
        Math.min(lineCount - SLIP_BAND_LINES, Math.floor(lineCount * (SLIP_RANGE_START + rand() * SLIP_RANGE_SPAN)))
      );
      const mag = SLIP_MIN_PX + rand() * (SLIP_MAX_PX - SLIP_MIN_PX);
      slipOffsetPx = rand() < 0.5 ? mag : -mag;
      lastLineDrawn = -1;
      scanCleared = false;
    };

    const totalCycleMs = () => HANDSHAKE_MS + lineCount * LINE_INTERVAL_MS + HOLD_MS + WIPE_MS;

    const drawStaticFrame = () => {
      // reduced-motion freeze: the fully-scanned page at rest, slip baked in
      reseedCycle();
      clearCanvas();
      for (let i = 0; i < lineCount; i++) commitLine(i);
    };

    const loop = (now: number) => {
      let cycleTime = now - cycleBase;
      const total = totalCycleMs();
      if (cycleTime >= total) {
        const laps = Math.floor(cycleTime / total);
        cycleBase += laps * total;
        cycleIndex += laps;
        reseedCycle();
        clearCanvas();
        cycleTime = now - cycleBase;
      }

      const scanMs = lineCount * LINE_INTERVAL_MS;
      if (cycleTime < HANDSHAKE_MS) {
        drawWaveform(cycleTime);
      } else if (cycleTime < HANDSHAKE_MS + scanMs) {
        if (!scanCleared) {
          clearCanvas();
          scanCleared = true;
        }
        const scanElapsed = cycleTime - HANDSHAKE_MS;
        const targetLine = Math.min(lineCount - 1, Math.floor(scanElapsed / LINE_INTERVAL_MS));
        while (lastLineDrawn < targetLine) {
          lastLineDrawn++;
          commitLine(lastLineDrawn);
        }
      } else if (cycleTime < HANDSHAKE_MS + scanMs + HOLD_MS) {
        if (!scanCleared) {
          clearCanvas();
          scanCleared = true;
        }
        while (lastLineDrawn < lineCount - 1) {
          lastLineDrawn++;
          commitLine(lastLineDrawn);
        }
      } else {
        const wipeT = cycleTime - HANDSHAKE_MS - scanMs - HOLD_MS;
        drawWipe(Math.min(1, wipeT / WIPE_MS));
      }

      if (!reduced && visible) raf = requestAnimationFrame(loop);
      else raf = 0;
    };

    const wake = () => {
      if (raf === 0 && !reduced && visible) raf = requestAnimationFrame(loop);
    };

    const resize = () => {
      const rect = root.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));

      // scan-line resolution derived from the container's smaller dimension
      const minDim = Math.min(w, h);
      lineCount = Math.min(MAX_LINES, Math.max(MIN_LINES, Math.round(h / 2)));
      rowH = h / lineCount;
      letterCell = Math.min(5, Math.max(2, minDim / 70));
      lineSpacing = Math.min(9, Math.max(5, minDim / 28));
      marginPx = Math.max(4, w * 0.05);

      cycleBase = performance.now();
      cycleIndex = 0;
      reseedCycle();

      if (reduced) {
        drawStaticFrame();
      } else {
        clearCanvas();
        wake();
      }
    };

    resize();

    const ro = new ResizeObserver(resize);
    ro.observe(root);

    const mo = new MutationObserver(() => {
      derive();
      if (reduced) drawStaticFrame();
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    const onReducedChange = () => {
      reduced = mq.matches;
      if (reduced) {
        cancelAnimationFrame(raf);
        raf = 0;
        drawStaticFrame();
      } else {
        cycleBase = performance.now();
        cycleIndex = 0;
        reseedCycle();
        clearCanvas();
        wake();
      }
    };
    mq.addEventListener("change", onReducedChange);

    const onVisibility = () => {
      visible = document.visibilityState === "visible";
      if (visible) wake();
      else {
        cancelAnimationFrame(raf);
        raf = 0;
      }
    };
    document.addEventListener("visibilitychange", onVisibility);

    const io = new IntersectionObserver((entries) => {
      const intersecting = entries[0]?.isIntersecting ?? true;
      visible = intersecting && document.visibilityState === "visible";
      if (visible) wake();
      else {
        cancelAnimationFrame(raf);
        raf = 0;
      }
    });
    io.observe(root);

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      mo.disconnect();
      io.disconnect();
      mq.removeEventListener("change", onReducedChange);
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, []);

  return (
    <div
      ref={rootRef}
      role="status"
      aria-busy="true"
      className={`ns-fls relative h-full w-full overflow-hidden bg-background ${className}`}
      style={style}
    >
      <span className="sr-only">{label}</span>
      <canvas ref={canvasRef} aria-hidden="true" className="pointer-events-none absolute inset-0 h-full w-full" />
    </div>
  );
}

FaxLineSlip.displayName = "FaxLineSlip";

export default FaxLineSlip;

"use client";

import { useEffect, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// FeatureGridAsciiRule — a feature grid where hovering or focusing a cell
// draws real box-drawing connectors between it and its related features,
// routed orthogonally through the grid's own gutters (never straight through
// a neighbouring cell). Every related pair always meets at the ONE shared
// horizontal gutter between the two rows: the connector drops from the
// source cell's gutter-facing edge, runs across at the gutter's mid-line,
// then rises into the target cell's gutter-facing edge — a uniform 3-segment
// Manhattan route regardless of which rows the two cells sit in, rasterized
// into individual ─ │ ┌ ┐ └ ┘ glyphs at a fixed pitch and revealed glyph by
// glyph (source -> target) on entry, retracted glyph by glyph in the
// opposite order (target -> source) on leave. This is a distinct mechanic
// from grid-bento-ascii (one static seam that structurally disappears when a
// single tile re-spans the whole grid — no relationships, no routing, no
// second cell involved once expanded), grid-bento-dense (FLIP reflow of tile
// footprints, no connectors at all) and grid-magnetic-lattice (a continuous
// cursor-warped field sampled by every line at once, not discrete per-pair
// routes tied to a data relationship).
// ---------------------------------------------------------------------------

export interface FeatureGridAsciiRuleItem {
  id: string;
  title: string;
  description: string;
  /** ids of other items in this same array this feature relates to */
  relatedIds: string[];
}

export interface FeatureGridAsciiRuleProps {
  /** the feature cards */
  items: FeatureGridAsciiRuleItem[];
  /** number of grid columns */
  cols?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

interface Tokens {
  fg: string;
  border: string;
  accent: string;
}

function readTokens(): Tokens {
  const cs = getComputedStyle(document.documentElement);
  const get = (name: string, fallback: string) => cs.getPropertyValue(name).trim() || fallback;
  return {
    fg: get("--foreground", "#ededed"),
    border: get("--border", "#2e2e2e"),
    accent: get("--ns-accent", "#006bff"),
  };
}

const PITCH = 11; // px per glyph, both axes
const STAGGER = 26; // ms per glyph step
const FADE = 140; // ms per glyph's own fade

type GlyphKind = "h" | "v" | "corner";

interface Glyph {
  x: number;
  y: number;
  ch: string;
  kind: GlyphKind;
  dist: number; // step index from source (0-based)
}

function corner(vert: "up" | "down", horiz: "left" | "right"): string {
  if (vert === "up" && horiz === "right") return "└"; // └
  if (vert === "up" && horiz === "left") return "┘"; // ┘
  if (vert === "down" && horiz === "right") return "┌"; // ┌
  return "┐"; // ┐
}

/** Builds the glyph list for one source -> target connector, routed through
 *  the single shared horizontal gutter between the two grid rows. */
function routeGlyphs(
  a: DOMRect,
  b: DOMRect,
  aIsTopRow: boolean,
  bIsTopRow: boolean,
  containerRect: DOMRect,
  gutterY: number
): Glyph[] {
  const ax = a.left + a.width / 2 - containerRect.left;
  const bx = b.left + b.width / 2 - containerRect.left;
  const aEdgeY = (aIsTopRow ? a.bottom : a.top) - containerRect.top;
  const bEdgeY = (bIsTopRow ? b.bottom : b.top) - containerRect.top;

  const glyphs: Glyph[] = [];
  let step = 0;

  // Anchor dot right on the source cell's own edge — without an explicit
  // mark here the connector's first glyph was drawn centered ON the
  // boundary line (half hidden behind the card), so the wire read as
  // fading into nothing rather than visibly plugging into the cell.
  glyphs.push({ x: ax, y: aEdgeY, ch: "●", kind: "corner", dist: step++ });

  // vertical run from the source cell's gutter-facing edge to the gutter line
  const v1Steps = Math.max(1, Math.round(Math.abs(gutterY - aEdgeY) / PITCH));
  for (let i = 1; i <= v1Steps; i++) {
    const y = aEdgeY + ((gutterY - aEdgeY) * i) / v1Steps;
    glyphs.push({ x: ax, y, ch: "│", kind: "v", dist: step++ });
  }

  // bend 1: connects back toward the source (vert) and across toward bend 2 (horiz)
  const vert1: "up" | "down" = aIsTopRow ? "up" : "down";
  const horiz1: "left" | "right" = bx >= ax ? "right" : "left";
  if (Math.abs(bx - ax) > 1) {
    glyphs.push({ x: ax, y: gutterY, ch: corner(vert1, horiz1), kind: "corner", dist: step++ });

    // horizontal run across the gutter
    const hSteps = Math.max(1, Math.round(Math.abs(bx - ax) / PITCH));
    for (let i = 1; i < hSteps; i++) {
      const x = ax + ((bx - ax) * i) / hSteps;
      glyphs.push({ x, y: gutterY, ch: "─", kind: "h", dist: step++ });
    }

    // bend 2: connects back toward bend 1 (horiz) and up/down toward the target (vert)
    const vert2: "up" | "down" = bIsTopRow ? "up" : "down";
    const horiz2: "left" | "right" = horiz1 === "right" ? "left" : "right";
    glyphs.push({ x: bx, y: gutterY, ch: corner(vert2, horiz2), kind: "corner", dist: step++ });
  } else {
    // same column: no bend needed, straight vertical line the whole way
  }

  // vertical run from the gutter to the target cell's gutter-facing edge
  const v2Steps = Math.max(1, Math.round(Math.abs(bEdgeY - gutterY) / PITCH));
  for (let i = 1; i <= v2Steps; i++) {
    const y = gutterY + ((bEdgeY - gutterY) * i) / v2Steps;
    glyphs.push({ x: bx, y, ch: "│", kind: "v", dist: step++ });
  }

  // Anchor dot on the target cell's edge, same reasoning as the source
  // anchor — this is the glyph that reads "arrived", so it's also the
  // first thing to fade on leave (retraction runs target -> source).
  glyphs.push({ x: bx, y: bEdgeY, ch: "●", kind: "corner", dist: step++ });

  return glyphs;
}

function easeOutCubic(t: number): number {
  const c = Math.min(1, Math.max(0, t));
  return 1 - Math.pow(1 - c, 3);
}

export function FeatureGridAsciiRule({ items, cols = 3, className = "" }: FeatureGridAsciiRuleProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const cellRefs = useRef<Record<string, HTMLButtonElement | null>>({});
  const [tokens, setTokens] = useState<Tokens>(() =>
    typeof document === "undefined" ? { fg: "#ededed", border: "#2e2e2e", accent: "#006bff" } : readTokens()
  );
  const [activeId, setActiveId] = useState<string | null>(null);
  const reducedRef = useRef(false);

  const byId = useMemo(() => {
    const m = new Map<string, FeatureGridAsciiRuleItem>();
    items.forEach((it) => m.set(it.id, it));
    return m;
  }, [items]);

  const rows = Math.ceil(items.length / cols);

  useEffect(() => {
    const sync = () => setTokens(readTokens());
    sync();
    const mo = new MutationObserver(sync);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style"] });
    return () => mo.disconnect();
  }, []);

  useEffect(() => {
    reducedRef.current = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  }, []);

  // active/last-active tracked with a transition timestamp so leaving
  // animates a real retraction rather than an instant clear
  const stateRef = useRef<{ id: string | null; since: number; leavingId: string | null }>({
    id: null,
    since: 0,
    leavingId: null,
  });

  useEffect(() => {
    const now = performance.now();
    if (activeId) {
      stateRef.current = { id: activeId, since: now, leavingId: null };
    } else if (stateRef.current.id) {
      stateRef.current = { id: null, since: now, leavingId: stateRef.current.id };
    }
  }, [activeId]);

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    if (!container || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let raf = 0;

    const sizeCanvas = () => {
      const rect = container.getBoundingClientRect();
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.ceil(rect.width * dpr);
      canvas.height = Math.ceil(rect.height * dpr);
      canvas.style.width = `${rect.width}px`;
      canvas.style.height = `${rect.height}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };
    sizeCanvas();
    const ro = new ResizeObserver(sizeCanvas);
    ro.observe(container);

    const draw = () => {
      const rect = container.getBoundingClientRect();
      ctx.clearRect(0, 0, rect.width, rect.height);

      const st = stateRef.current;
      const showId = st.id ?? st.leavingId;
      if (showId) {
        const source = byId.get(showId);
        const sourceEl = cellRefs.current[showId];
        if (source && sourceEl) {
          const aRect = sourceEl.getBoundingClientRect();
          const aRow = Object.keys(cellRefs.current).indexOf(showId); // fallback, unused
          const aIndex = items.findIndex((it) => it.id === showId);
          const aTopRow = Math.floor(aIndex / cols) === 0;
          const rowGutterTop = Math.min(...items.map((_, i) => (Math.floor(i / cols) === 0 ? 1 : 0)));
          void aRow;
          void rowGutterTop;

          // gutter mid-line: between row 0's bottom and row 1's top, using the
          // first cell of each row actually present
          const row0El = cellRefs.current[items[0]?.id ?? ""];
          const row1Idx = items.findIndex((_, i) => Math.floor(i / cols) === 1);
          const row1El = row1Idx >= 0 ? cellRefs.current[items[row1Idx]!.id] : null;
          const gutterY =
            row0El && row1El
              ? (row0El.getBoundingClientRect().bottom + row1El.getBoundingClientRect().top) / 2 -
                rect.top
              : aRect.bottom - rect.top;

          const now = performance.now();
          const elapsed = now - st.since;
          const advancing = st.id === showId;

          ctx.font = `${PITCH}px "GeistMono", ui-monospace, monospace`;
          ctx.textAlign = "center";
          ctx.textBaseline = "middle";

          for (const relId of source.relatedIds) {
            const targetEl = cellRefs.current[relId];
            const bIndex = items.findIndex((it) => it.id === relId);
            if (!targetEl || bIndex < 0) continue;
            const bRect = targetEl.getBoundingClientRect();
            const bTopRow = Math.floor(bIndex / cols) === 0;
            const glyphs = routeGlyphs(aRect, bRect, aTopRow, bTopRow, rect, gutterY);
            const n = Math.max(1, glyphs.length);

            for (const g of glyphs) {
              let opacity: number;
              if (reducedRef.current) {
                opacity = advancing ? 1 : 0;
              } else if (advancing) {
                const t = (elapsed - g.dist * STAGGER) / FADE;
                opacity = easeOutCubic(t);
              } else {
                // retract target-first: glyphs nearer the target (higher dist)
                // fade out earlier than glyphs nearer the source
                const revIndex = n - 1 - g.dist;
                const t = (elapsed - revIndex * STAGGER) / FADE;
                opacity = 1 - easeOutCubic(t);
              }
              if (opacity <= 0.01) continue;
              // Anchor dots draw in --ns-accent so both ends read as a clear
              // "plugged in" terminal against the fg-colored border glyphs;
              // the run between them stays --foreground so the accent reads
              // as an endpoint marker, not a wash over the whole wire.
              ctx.fillStyle = g.ch === "●" ? tokens.accent : tokens.fg;
              ctx.globalAlpha = Math.min(1, Math.max(0, opacity)) * (g.ch === "●" ? 1 : 0.9);
              ctx.fillText(g.ch, g.x, g.y);
            }
          }
          ctx.globalAlpha = 1;
        }
      }

      const st2 = stateRef.current;
      const stillLeaving = st2.leavingId && performance.now() - st2.since < STAGGER * 20 + FADE + 40;
      if (!stillLeaving && st2.leavingId) {
        stateRef.current = { id: st2.id, since: st2.since, leavingId: null };
      }
      const active = st2.id !== null || (st2.leavingId !== null && stillLeaving);
      if (active || !reducedRef.current) {
        raf = requestAnimationFrame(draw);
      }
    };
    raf = requestAnimationFrame(draw);

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
    };
  }, [byId, items, cols, tokens]);

  return (
    <div ref={containerRef} className={`relative w-full ${className}`}>
      <canvas ref={canvasRef} aria-hidden className="ns-fgar-canvas pointer-events-none absolute inset-0 z-10" />
      <div
        className="relative grid gap-x-10 gap-y-8"
        style={{ gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))` }}
      >
        {items.map((item) => {
          const isActive = activeId === item.id;
          const isRelated = activeId != null && byId.get(activeId)?.relatedIds.includes(item.id);
          return (
            <button
              key={item.id}
              type="button"
              ref={(el) => {
                cellRefs.current[item.id] = el;
              }}
              data-feature-cell={item.id}
              aria-label={`${item.title}: ${item.description}`}
              onPointerEnter={() => setActiveId(item.id)}
              onPointerLeave={() => setActiveId((c) => (c === item.id ? null : c))}
              onFocus={() => setActiveId(item.id)}
              onBlur={() => setActiveId((c) => (c === item.id ? null : c))}
              className={`group relative flex flex-col items-start gap-1.5 rounded-md border p-4 text-left transition-colors duration-150 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent ${
                isActive
                  ? "border-foreground/40 bg-surface"
                  : isRelated
                    ? "border-foreground/25 bg-surface/60"
                    : "border-border bg-surface hover:border-foreground/20"
              }`}
            >
              <span className="font-mono text-[10px] uppercase tracking-widest text-ns-muted">
                {String(items.indexOf(item) + 1).padStart(2, "0")}
              </span>
              <span className="text-sm font-semibold text-foreground">{item.title}</span>
              <span className="text-xs text-ns-muted">{item.description}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
} from "react";

// ---------------------------------------------------------------------------
// EscapementTick — a live feed admitted one item at a time by a physical
// gate, not a scheduler. Arrivals mount immediately as collapsed, aria-hidden
// list rows (height 0, translateY -8px) — the queue is real DOM, just
// invisible. A small SVG anchor fork in the gutter rocks +-12deg each time it
// lets exactly one row through; that row's height/translateY are driven by a
// single rAF spring (refs only, no React state on the hot path), and the
// anchor will not rock again until THAT spring's displacement and velocity
// both fall under epsilon. Because it's real block-level height growing in
// normal flow, everything already released underneath shifts down together
// as one connected chain — there is no per-row stagger to schedule. A burst
// of arrivals becomes calm tick-tick-tick admission instead of a dogpile.
// aria-live=polite (role=log) + per-row aria-atomic gives screen reader
// users the same serialized cadence for free. "Release all" (button or
// Escape) flushes the queue instantly, for when metered admission isn't
// what's wanted.
// ---------------------------------------------------------------------------

export interface EscapementEntryInput {
  title: string;
  detail?: string;
  /** display timestamp; defaults to the current time */
  timestamp?: string;
}

export interface EscapementTickHandle {
  /** enqueue one item behind the escapement; returns its id */
  arrive: (entry: EscapementEntryInput) => string;
  /** instantly reveal every pending item, skipping the metered cadence */
  releaseAll: () => void;
  /** remove every item and reset the queue */
  clear: () => void;
}

type EntryRec = {
  id: string;
  title: string;
  detail?: string;
  timestamp: string;
};

type SpringNode = {
  el: HTMLLIElement;
  natural: number;
  t: number;
  v: number;
  raf: number;
  last: number;
};

// spring constants — underdamped just enough for one small settle wobble,
// not a bounce; tuned against REST_OFFSET/ANCHOR_ANGLE below
const SPRING_K = 210;
const SPRING_C = 25;
const EPS_POS = 0.003;
const EPS_VEL = 0.02;
const REST_OFFSET = -8; // px, matches the brief's hidden-state translateY
const ANCHOR_ANGLE = 12; // deg, the fork's rock amplitude

let idSeed = 0;
function nextId() {
  idSeed += 1;
  return `esc-${idSeed}-${Date.now().toString(36)}`;
}

function nowLabel() {
  return new Date().toLocaleTimeString([], {
    hour12: false,
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
}

function AnchorFork({ innerRef }: { innerRef: (el: SVGSVGElement | null) => void }) {
  return (
    <svg
      ref={innerRef}
      aria-hidden
      width="22"
      height="22"
      viewBox="0 0 24 24"
      fill="none"
      className="shrink-0 text-ns-muted"
      style={{ transformOrigin: "12px 12px" }}
    >
      <circle cx="12" cy="12" r="1.6" fill="currentColor" />
      <path d="M4.5 12h15" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" />
      <path
        d="M4.5 12c0 1.8 1 3 2.6 3"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="round"
      />
      <path
        d="M19.5 12c0 1.8-1 3-2.6 3"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="round"
      />
    </svg>
  );
}

export const EscapementTick = forwardRef<
  EscapementTickHandle,
  {
    /** extra classes merged onto the rendered root element */
    className?: string;
    /** accessible name for the feed. Default "Live activity feed". */
    "aria-label"?: string;
    /** shown while no items have arrived yet */
    emptyLabel?: string;
  }
>(function EscapementTick(
  {
    className = "",
    "aria-label": ariaLabel = "Live activity feed",
    emptyLabel = "Waiting for activity…",
  },
  ref
) {
  const [entries, setEntries] = useState<EntryRec[]>([]);

  const itemElRef = useRef<Map<string, HTMLLIElement>>(new Map());
  const pendingRef = useRef<string[]>([]); // ids awaiting release, FIFO
  const activeIdRef = useRef<string | null>(null);
  const springRef = useRef<SpringNode | null>(null);
  const tickDirRef = useRef(1);
  const anchorElRef = useRef<SVGSVGElement | null>(null);
  const anchorTimeoutRef = useRef<number | null>(null);
  const reducedRef = useRef(false);
  const counterElRef = useRef<HTMLSpanElement>(null);
  const depthRef = useRef(0);
  // stable indirection: releaseNext recurses into "itself" via this ref so
  // its own useCallback identity never needs to depend on itself
  const releaseNextRef = useRef<() => void>(() => {});

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    reducedRef.current = mq.matches;
    const onChange = (e: MediaQueryListEvent) => {
      reducedRef.current = e.matches;
    };
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  useEffect(() => {
    return () => {
      if (springRef.current) cancelAnimationFrame(springRef.current.raf);
      if (anchorTimeoutRef.current !== null) window.clearTimeout(anchorTimeoutRef.current);
    };
  }, []);

  const setCounter = useCallback((n: number) => {
    depthRef.current = n;
    const el = counterElRef.current;
    if (el) el.textContent = String(n);
  }, []);

  const rockAnchor = useCallback(() => {
    const el = anchorElRef.current;
    if (!el || reducedRef.current) return;
    if (anchorTimeoutRef.current !== null) window.clearTimeout(anchorTimeoutRef.current);
    tickDirRef.current *= -1;
    const angle = tickDirRef.current * ANCHOR_ANGLE;
    el.style.transition = "transform 200ms cubic-bezier(0.34, 1.56, 0.64, 1)";
    el.style.transform = `rotate(${angle}deg)`;
    anchorTimeoutRef.current = window.setTimeout(() => {
      el.style.transition = "transform 260ms cubic-bezier(0.22, 1, 0.36, 1)";
      el.style.transform = "rotate(0deg)";
      anchorTimeoutRef.current = null;
    }, 200);
  }, []);

  const settleImmediately = useCallback((el: HTMLLIElement) => {
    el.style.transition = "none";
    el.style.height = "auto";
    el.style.transform = "translateY(0px)";
    el.removeAttribute("aria-hidden");
  }, []);

  // the escapement gate: exactly one spring runs at a time. It only pulls
  // the next queued id once displacement AND velocity are both under
  // epsilon, so cadence follows real settle time, never a fixed offset.
  const releaseNext = useCallback(() => {
    if (activeIdRef.current !== null) return; // still settling — gate closed
    const next = pendingRef.current.shift();
    if (!next) return;
    const el = itemElRef.current.get(next);
    if (!el) {
      releaseNextRef.current();
      return;
    }
    activeIdRef.current = next;
    el.removeAttribute("aria-hidden");
    rockAnchor();
    const natural = el.scrollHeight;
    const node: SpringNode = { el, natural, t: 0, v: 0, raf: 0, last: 0 };
    springRef.current = node;

    const step = (now: number) => {
      const dt = node.last === 0 ? 1 / 60 : Math.min(0.05, (now - node.last) / 1000);
      node.last = now;
      const force = SPRING_K * (1 - node.t) - SPRING_C * node.v;
      node.v += force * dt;
      node.t += node.v * dt;
      node.el.style.height = `${Math.max(0, node.t) * node.natural}px`;
      node.el.style.transform = `translateY(${((1 - node.t) * REST_OFFSET).toFixed(2)}px)`;

      if (Math.abs(1 - node.t) < EPS_POS && Math.abs(node.v) < EPS_VEL) {
        node.el.style.height = "auto";
        node.el.style.transform = "translateY(0px)";
        springRef.current = null;
        activeIdRef.current = null;
        setCounter(Math.max(0, depthRef.current - 1));
        releaseNextRef.current();
        return;
      }
      node.raf = requestAnimationFrame(step);
    };
    node.raf = requestAnimationFrame(step);
  }, [rockAnchor, setCounter]);

  releaseNextRef.current = releaseNext;

  const attachItem = useCallback(
    (id: string, el: HTMLLIElement | null) => {
      if (!el) return;
      if (itemElRef.current.get(id) === el) return; // same node, already wired
      itemElRef.current.set(id, el);

      if (reducedRef.current) {
        // reduced motion: nothing actually queues, so the depth this item
        // contributed in arrive() must come right back off — otherwise the
        // "queued" counter climbs forever while every item lands instantly.
        settleImmediately(el);
        setCounter(Math.max(0, depthRef.current - 1));
        return;
      }
      el.style.overflow = "hidden";
      el.style.height = "0px";
      el.style.transform = `translateY(${REST_OFFSET}px)`;
      el.setAttribute("aria-hidden", "true");
      pendingRef.current.push(id);
      releaseNextRef.current();
    },
    [settleImmediately, setCounter]
  );

  const arrive = useCallback(
    (entry: EscapementEntryInput) => {
      const id = nextId();
      setEntries((prev) => [
        { id, title: entry.title, detail: entry.detail, timestamp: entry.timestamp ?? nowLabel() },
        ...prev,
      ]);
      setCounter(depthRef.current + 1);
      return id;
    },
    [setCounter]
  );

  const releaseAll = useCallback(() => {
    const node = springRef.current;
    if (node) {
      cancelAnimationFrame(node.raf);
      settleImmediately(node.el);
      springRef.current = null;
    }
    activeIdRef.current = null;
    const remaining = pendingRef.current;
    pendingRef.current = [];
    for (const id of remaining) {
      const el = itemElRef.current.get(id);
      if (el) settleImmediately(el);
    }
    setCounter(0);
  }, [settleImmediately, setCounter]);

  const clear = useCallback(() => {
    if (springRef.current) cancelAnimationFrame(springRef.current.raf);
    springRef.current = null;
    activeIdRef.current = null;
    pendingRef.current = [];
    itemElRef.current.clear();
    setEntries([]);
    setCounter(0);
  }, [setCounter]);

  useImperativeHandle(ref, () => ({ arrive, releaseAll, clear }), [arrive, releaseAll, clear]);

  const onKeyDown = useCallback(
    (e: ReactKeyboardEvent<HTMLDivElement>) => {
      if (e.key === "Escape") {
        e.preventDefault();
        releaseAll();
      }
    },
    [releaseAll]
  );

  return (
    <div
      onKeyDown={onKeyDown}
      className={`flex w-full flex-col rounded-md border border-border bg-surface ${className}`}
    >
      <div className="flex items-center gap-2.5 border-b border-border px-3.5 py-2.5">
        <AnchorFork innerRef={(el) => (anchorElRef.current = el)} />
        <span className="font-mono text-[11px] tracking-wide text-ns-muted">
          <span ref={counterElRef}>0</span> queued
        </span>
        <button
          type="button"
          onClick={releaseAll}
          className="ml-auto cursor-pointer rounded-sm border border-border px-2.5 py-1 font-mono text-[10px] tracking-widest text-ns-muted transition-colors duration-150 hover:border-foreground/20 hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
        >
          RELEASE ALL
        </button>
      </div>
      <ul
        role="log"
        aria-live="polite"
        aria-relevant="additions"
        aria-label={ariaLabel}
        className="flex flex-col overflow-hidden"
      >
        {entries.length === 0 ? (
          <li className="px-3.5 py-6 text-center font-mono text-[11px] text-ns-muted">
            {emptyLabel}
          </li>
        ) : (
          entries.map((entry) => (
            <li
              key={entry.id}
              ref={(el) => attachItem(entry.id, el)}
              aria-atomic="true"
              className="border-b border-border/60 px-3.5 py-2.5 last:border-b-0 will-change-[height,transform]"
            >
              <div className="flex items-baseline justify-between gap-3">
                <p className="truncate text-[13px] text-foreground">{entry.title}</p>
                <span className="shrink-0 font-mono text-[10px] tabular-nums text-ns-muted">
                  {entry.timestamp}
                </span>
              </div>
              {entry.detail ? (
                <p className="mt-0.5 truncate font-mono text-[11px] text-ns-muted">{entry.detail}</p>
              ) : null}
            </li>
          ))
        )}
      </ul>
    </div>
  );
});

"use client";

import { useEffect, useId, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// FicheStepRepeat — a thumbnail grid that populates the way a COM (computer
// output microfilm) step-and-repeat camera exposed a microfiche sheet: one
// frame at a time, strict raster order (left-to-right, then down a row), a
// short exposure flash on arrival, and a typed index strip once the sheet is
// complete. The mechanical step between frames is genuinely the slow part —
// the flash itself is brief — so growth is paced at one cell per STEP_MS,
// with an explicit FLASH_UP/FLASH_DOWN envelope on top of every arrival
// rather than a plain fade-in (the real process is a discrete exposure, not
// a dissolve).
//
// Grid geometry: cols/rows are derived from the container's own width and
// height divided by a ~64px target cell, clamped to a 4x3 minimum and a
// 7x5 maximum — the closest card-scale abstraction of a real fiche's
// row/column raster (full sheets run 7x14 or denser; this keeps a card
// legible). One rAF loop drives the whole cycle from a single elapsed-time
// clock (grow -> type -> hold -> reset), touching the DOM directly per
// cell rather than through React state, since redrawing 12-35 tiny cells
// through render on every animation frame would be wasted work.
// ---------------------------------------------------------------------------

const STEP_MS = 850; // one raster step: mechanical pitch between exposures
const FLASH_UP_MS = 120; // exposure flash ramp to peak
const FLASH_DOWN_MS = 280; // flash relaxes back to the cell's rest luminance
const FLASH_MS = FLASH_UP_MS + FLASH_DOWN_MS;
const TYPE_MS = 600; // index strip typing window
const TYPE_CHAR_MS = 17; // ~one character reveal every 17ms
const HOLD_MS = 1400; // full-sheet hold once the index strip finishes
const RESET_MS = 400; // raster-order step back to blank
const FLASH_AMP_DARK = 0.12; // +12% luminance over settled value (dark theme)
const FLASH_AMP_LIGHT = 0.08; // less headroom against near-white thumbnails
const TARGET_CELL_PX = 64;
const MIN_COLS = 4;
const MAX_COLS = 7;
const MIN_ROWS = 3;
const MAX_ROWS = 5;

export interface FicheFrame {
  /** thumbnail image URL for this raster position */
  src: string;
  /** accessible description of the frame */
  alt: string;
}

export interface FicheStepRepeatProps {
  /** real thumbnails placed in raster order; cells beyond the supplied count
   * render the built-in placeholder silhouette */
  images?: FicheFrame[];
  /** reduction ratio printed on the index strip, e.g. 24 for "24x" */
  reductionRatio?: number;
  /** extra classes merged onto the root element */
  className?: string;
}

function FrameSilhouette() {
  return (
    <svg
      viewBox="0 0 24 24"
      aria-hidden="true"
      className="h-2/5 w-2/5 text-ns-muted opacity-40"
    >
      <rect x="2" y="2" width="20" height="20" rx="1.5" fill="none" stroke="currentColor" strokeWidth="1.2" />
      <circle cx="8" cy="8.5" r="2" fill="none" stroke="currentColor" strokeWidth="1.2" />
      <path
        d="M3 17.5l5-5a1.4 1.4 0 0 1 2 0l4.5 4.5 1.5-1.5a1.4 1.4 0 0 1 2 0L21 18"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.2"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

export function FicheStepRepeat({ images = [], reductionRatio = 24, className = "" }: FicheStepRepeatProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const cellRefs = useRef<(HTMLDivElement | null)[]>([]);
  const headerRef = useRef<HTMLParagraphElement>(null);
  const [grid, setGrid] = useState({ cols: MAX_COLS, rows: MAX_ROWS });
  const headerId = useId();

  const cellCount = grid.cols * grid.rows;
  const label = `${reductionRatio}× · ${cellCount} FRAMES`;

  // Derive the raster grid from the container's own dimensions — the
  // smaller axis governs how coarse a "still reads at card scale" grid is,
  // but each axis gets its own count so a wide card doesn't get squeezed
  // into a square.
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const measure = () => {
      const rect = root.getBoundingClientRect();
      if (rect.width < 2 || rect.height < 2) return;
      const cols = Math.min(MAX_COLS, Math.max(MIN_COLS, Math.round(rect.width / TARGET_CELL_PX)));
      const rows = Math.min(MAX_ROWS, Math.max(MIN_ROWS, Math.round(rect.height / TARGET_CELL_PX)));
      setGrid((prev) => (prev.cols === cols && prev.rows === rows ? prev : { cols, rows }));
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(root);
    return () => ro.disconnect();
  }, []);

  useEffect(() => {
    const header = headerRef.current;
    if (!header) return;

    const cells = cellRefs.current.slice(0, cellCount);
    const growEnd = cellCount * STEP_MS;
    const typeEnd = growEnd + TYPE_MS;
    const holdEnd = typeEnd + HOLD_MS;
    const totalCycle = holdEnd + RESET_MS;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    // Theme flip only ever swaps the `.dark` class — track it live so the
    // flash amplitude reads correctly without a remount.
    let flashAmp = document.documentElement.classList.contains("dark") ? FLASH_AMP_DARK : FLASH_AMP_LIGHT;
    const mo = new MutationObserver(() => {
      flashAmp = document.documentElement.classList.contains("dark") ? FLASH_AMP_DARK : FLASH_AMP_LIGHT;
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    const populated = new Array(cellCount).fill(false);
    let lastFlashCell = -1;
    let lastTypedChars = -1;

    const setFilled = (i: number, filled: boolean) => {
      if (populated[i] === filled) return;
      populated[i] = filled;
      const el = cells[i];
      if (!el) return;
      if (filled) el.dataset.filled = "true";
      else delete el.dataset.filled;
    };

    const clearFlash = (i: number) => {
      const el = cells[i];
      if (el) el.style.removeProperty("filter");
    };

    const setHeaderText = (text: string) => {
      if (lastTypedChars === text.length && header.textContent === text) return;
      header.textContent = text;
      lastTypedChars = text.length;
    };

    // Reduced motion: freeze on the full-sheet hold frame — every cell
    // populated at rest, index strip fully typed, no flash, no loop.
    if (reduced) {
      for (let i = 0; i < cellCount; i++) setFilled(i, true);
      setHeaderText(label);
      return () => mo.disconnect();
    }

    let raf = 0;
    let cycleStart = 0;
    let visible = true;

    const tick = (now: number) => {
      if (!visible) return;
      if (cycleStart === 0) cycleStart = now;
      let elapsed = now - cycleStart;
      if (elapsed >= totalCycle) {
        cycleStart += totalCycle;
        elapsed -= totalCycle;
      }

      if (elapsed < growEnd) {
        const idx = Math.min(cellCount - 1, Math.floor(elapsed / STEP_MS));
        for (let i = 0; i <= idx; i++) setFilled(i, true);
        const localT = elapsed - idx * STEP_MS;
        if (localT < FLASH_MS) {
          const p = localT < FLASH_UP_MS ? localT / FLASH_UP_MS : 1 - (localT - FLASH_UP_MS) / FLASH_DOWN_MS;
          const b = 1 + p * flashAmp;
          const el = cells[idx];
          if (el) el.style.filter = `brightness(${b.toFixed(3)})`;
          lastFlashCell = idx;
        } else if (lastFlashCell === idx) {
          clearFlash(idx);
          lastFlashCell = -1;
        }
        if (lastTypedChars !== 0) setHeaderText("");
      } else if (elapsed < typeEnd) {
        if (lastFlashCell !== -1) {
          clearFlash(lastFlashCell);
          lastFlashCell = -1;
        }
        const typed = Math.min(label.length, Math.floor(((elapsed - growEnd) / TYPE_MS) * label.length));
        setHeaderText(label.slice(0, typed));
      } else if (elapsed < holdEnd) {
        setHeaderText(label);
      } else {
        if (lastTypedChars !== 0) setHeaderText("");
        const t = elapsed - holdEnd;
        const removed = Math.min(cellCount, Math.floor((t / RESET_MS) * cellCount));
        for (let i = 0; i < removed; i++) setFilled(i, false);
      }

      raf = requestAnimationFrame(tick);
    };

    const io = new IntersectionObserver((entries) => {
      const wasVisible = visible;
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && !wasVisible) {
        // resume without a discontinuity: nudge cycleStart so elapsed picks
        // up exactly where it left off, then re-arm the loop.
        cycleStart = 0;
        if (!raf) raf = requestAnimationFrame((now) => {
          cycleStart = now;
          raf = requestAnimationFrame(tick);
        });
      }
    });
    io.observe(rootRef.current ?? header);

    raf = requestAnimationFrame(tick);

    return () => {
      cancelAnimationFrame(raf);
      io.disconnect();
      mo.disconnect();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [cellCount, label]);

  return (
    <div
      ref={rootRef}
      role="list"
      aria-labelledby={headerId}
      className={`relative flex h-full w-full flex-col gap-2 ${className}`}
    >
      <p id={headerId} className="sr-only">
        Thumbnail sheet, {label}
      </p>
      <p
        ref={headerRef}
        aria-hidden="true"
        className="h-3.5 shrink-0 whitespace-nowrap font-mono text-[11px] tracking-widest text-ns-muted"
      />
      <div
        className="grid min-h-0 flex-1 gap-1.5"
        style={{ gridTemplateColumns: `repeat(${grid.cols}, 1fr)`, gridTemplateRows: `repeat(${grid.rows}, 1fr)` }}
      >
        {Array.from({ length: cellCount }, (_, i) => {
          const frame = images[i];
          return (
            <div
              key={i}
              role="listitem"
              className="relative overflow-hidden rounded-[1px] border border-border"
            >
              <div
                ref={(el) => {
                  cellRefs.current[i] = el;
                }}
                className="absolute inset-0 flex items-center justify-center bg-surface opacity-0 outline-none transition-opacity duration-0 data-[filled=true]:opacity-100"
                style={{ willChange: "filter" }}
              >
                {frame ? (
                  <img
                    src={frame.src}
                    alt={frame.alt}
                    className="h-full w-full object-cover transition-[filter] duration-150 hover:brightness-105 focus-visible:brightness-105"
                    draggable={false}
                  />
                ) : (
                  <FrameSilhouette />
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type DragEvent,
  type KeyboardEvent,
  type RefObject,
} from "react";

// ---------------------------------------------------------------------------
// VacuumSeal — a file upload zone where progress IS the container, not a
// bar appended to it. Dropping a file spawns a loose dashed SVG rounded-rect
// outline 24px outside the card; as upload progress advances, one
// critically-damped spring per file pulls that outline inward — inset,
// dasharray, and a muted->foreground stroke crossfade all riding the same
// spring parameter — so it visibly breathes toward the card rather than
// stepping. Arrival at 100% is a real end-state: status flips to "sealed"
// and the card plays a one-shot scale(0.99) pucker-and-release. A failed
// upload targets the spring back to its loose, 24px-out rest position with
// light underdamping, so it visibly overshoots and wobbles before settling
// — the same spring engine, just less damped, drawn in --error instead of
// muted/foreground. Direct-DOM per-card rAF loops, one per uploading/sealing
// file, sleep once each has settled; pre-seeded (defaultFiles) entries never
// run the spring at all — their geometry is written once, synchronously,
// before paint.
// ---------------------------------------------------------------------------

const OUTER_GAP = 24; // px — loose outline distance at progress 0
const WOBBLE = 6; // px — extra overshoot room for the fail-relax bounce
const PAD = OUTER_GAP + WOBBLE + 4; // svg overhang each side
const CARD_RADIUS = 12; // matches the card's own rounded-md
const SEAL_K = 90; // spring constant while sealing/uploading (critically damped)
const FAIL_K = 46; // spring constant while relaxing after a failure (underdamped)
const FAIL_ZETA = 0.4;
const PUCKER_MS = 260;

type UploadStatus = "uploading" | "sealed" | "failed";

export interface VacuumSealFile {
  id: string;
  name: string;
  size: number;
  type: string;
}

interface FileEntry extends VacuumSealFile {
  status: UploadStatus;
  progress: number; // 0..1
}

function formatSize(bytes: number): string {
  if (bytes >= 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  if (bytes >= 1024) return `${Math.round(bytes / 1024)} KB`;
  return `${bytes} B`;
}

function acceptSummary(accept: string[]): string {
  if (accept.length === 0) return "Any file type";
  return accept
    .map((a) => (a.startsWith(".") ? a.slice(1).toUpperCase() : a))
    .join(", ");
}

function statusText(f: FileEntry): string {
  const size = formatSize(f.size);
  if (f.status === "sealed") return `${size} · sealed`;
  if (f.status === "failed") return `upload failed · ${size}`;
  return `uploading ${size}… ${Math.round(f.progress * 100)}%`;
}

function clamp(v: number, lo: number, hi: number) {
  return Math.max(lo, Math.min(hi, v));
}

// ---------------------------------------------------------------------------
// SealOutline — the per-card spring engine. Drives an SVG rect (or two, for
// the muted/foreground crossfade) via direct attribute writes, never React
// state. `dp` is a generalized "seal progress" spring variable: 0 = loose
// outline 24px out, 1 = flush/taut. For status "failed" the spring target is
// 0 with light underdamping, so dp is allowed to swing slightly negative —
// that alone produces the relax-with-wobble, no separate keyframe needed.
// ---------------------------------------------------------------------------
function useSealOutline(
  wrapRef: RefObject<HTMLDivElement | null>,
  svgRef: RefObject<SVGSVGElement | null>,
  mutedRef: RefObject<SVGRectElement | null>,
  fgRef: RefObject<SVGRectElement | null>,
  errRef: RefObject<SVGRectElement | null>,
  status: UploadStatus,
  progress: number,
  reduced: boolean,
  frozen: boolean // pre-seeded entries: write geometry once, never spring
) {
  const dpRef = useRef(status === "sealed" ? 1 : status === "failed" ? 0 : progress);
  const vRef = useRef(0);
  const wRef = useRef(0);
  const hRef = useRef(0);
  const rafRef = useRef(0);
  const lastRef = useRef(0);

  const applyGeom = useCallback(() => {
    const w = wRef.current;
    const h = hRef.current;
    if (w < 1 || h < 1) return;
    const dp = dpRef.current;
    const offset = clamp(OUTER_GAP * (1 - dp), 0, OUTER_GAP + WOBBLE);
    const rx = CARD_RADIUS + offset * 0.55;
    const x = PAD - offset;
    const y = PAD - offset;
    const rw = Math.max(0, w + offset * 2);
    const rh = Math.max(0, h + offset * 2);
    const svg = svgRef.current;
    if (svg) {
      svg.setAttribute("width", String(w + PAD * 2));
      svg.setAttribute("height", String(h + PAD * 2));
    }
    const pC = clamp(dp, 0, 1);
    const dashLen = (8 - 7 * pC).toFixed(2);
    const gapLen = (4 - 4 * pC).toFixed(2);
    for (const r of [mutedRef.current, fgRef.current, errRef.current]) {
      if (!r) continue;
      r.setAttribute("x", x.toFixed(2));
      r.setAttribute("y", y.toFixed(2));
      r.setAttribute("width", rw.toFixed(2));
      r.setAttribute("height", rh.toFixed(2));
      r.setAttribute("rx", rx.toFixed(2));
    }
    if (mutedRef.current) {
      mutedRef.current.setAttribute("stroke-dasharray", `${dashLen} ${gapLen}`);
      mutedRef.current.style.opacity = String(1 - pC);
    }
    if (fgRef.current) {
      fgRef.current.setAttribute("stroke-dasharray", `${dashLen} ${gapLen}`);
      fgRef.current.style.opacity = String(pC);
    }
    // errRef keeps its fixed loose dasharray (set in markup) — only geometry moves
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // measure + write geometry synchronously before first paint — this is what
  // keeps a pre-seeded (frozen) card static at rest instead of springing in
  useLayoutEffect(() => {
    const wrap = wrapRef.current;
    if (!wrap) return;
    const measure = () => {
      const rect = wrap.getBoundingClientRect();
      wRef.current = rect.width;
      hRef.current = rect.height;
      applyGeom();
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(wrap);
    return () => ro.disconnect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (frozen) return; // pre-seeded: geometry already written once, above
    if (reduced) {
      // discrete quartile steps, no spring, no overshoot
      const target = status === "failed" ? 0 : status === "sealed" ? 1 : progress;
      dpRef.current = status === "failed" ? 0 : Math.floor(clamp(target, 0, 1) * 4) / 4;
      vRef.current = 0;
      applyGeom();
      return;
    }
    const target = status === "failed" ? 0 : status === "sealed" ? 1 : progress;
    const k = status === "failed" ? FAIL_K : SEAL_K;
    const zeta = status === "failed" ? FAIL_ZETA : 1;
    const c = 2 * zeta * Math.sqrt(k);

    const loop = (now: number) => {
      const dt = lastRef.current ? Math.min(0.05, (now - lastRef.current) / 1000) : 1 / 60;
      lastRef.current = now;
      const dp = dpRef.current;
      const err = target - dp;
      vRef.current += (k * err - c * vRef.current) * dt;
      dpRef.current = dp + vRef.current * dt;
      applyGeom();
      if (Math.abs(target - dpRef.current) < 0.0025 && Math.abs(vRef.current) < 0.01) {
        dpRef.current = target;
        vRef.current = 0;
        applyGeom();
        rafRef.current = 0;
        lastRef.current = 0;
        return;
      }
      rafRef.current = requestAnimationFrame(loop);
    };
    lastRef.current = 0;
    cancelAnimationFrame(rafRef.current);
    rafRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(rafRef.current);
  }, [status, progress, reduced, frozen, applyGeom]);
}

function FileCard({
  file,
  reduced,
  frozen,
}: {
  file: FileEntry;
  reduced: boolean;
  frozen: boolean;
}) {
  const wrapRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);
  const mutedRef = useRef<SVGRectElement>(null);
  const fgRef = useRef<SVGRectElement>(null);
  const errRef = useRef<SVGRectElement>(null);
  const prevStatusRef = useRef(file.status);
  const [justSealed, setJustSealed] = useState(false);
  const progId = useId();

  useSealOutline(
    wrapRef,
    svgRef,
    mutedRef,
    fgRef,
    errRef,
    file.status,
    file.progress,
    reduced,
    frozen
  );

  useEffect(() => {
    if (!frozen && !reduced && prevStatusRef.current !== "sealed" && file.status === "sealed") {
      setJustSealed(true);
    }
    prevStatusRef.current = file.status;
  }, [file.status, frozen, reduced]);

  const pct = Math.round((file.status === "sealed" ? 1 : file.progress) * 100);

  return (
    <li className="relative" style={{ margin: `${PAD - 10}px 0` }}>
      <div
        ref={wrapRef}
        data-just-sealed={justSealed || undefined}
        onAnimationEnd={() => setJustSealed(false)}
        className="ns-file-upload-seal-card relative rounded-md border border-border bg-surface"
      >
        <svg
          ref={svgRef}
          aria-hidden
          className="pointer-events-none absolute overflow-visible"
          style={{ left: -PAD, top: -PAD }}
        >
          {file.status !== "failed" ? (
            <>
              <rect
                ref={mutedRef}
                className="text-ns-muted"
                fill="none"
                stroke="currentColor"
                strokeWidth={1.5}
              />
              <rect
                ref={fgRef}
                className="text-foreground"
                fill="none"
                stroke="currentColor"
                strokeWidth={1.5}
              />
            </>
          ) : (
            <rect
              ref={errRef}
              fill="none"
              strokeWidth={1.5}
              strokeDasharray="8 4"
              style={{ stroke: "var(--error, #ea001d)" }}
            />
          )}
        </svg>

        <div className="relative z-[1] flex items-center gap-3 px-4 py-3">
          <span className="shrink-0 text-ns-muted" aria-hidden>
            {file.status === "sealed" ? (
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" className="h-4 w-4 text-foreground">
                <path d="M4 12.5 9.5 18 20 6" />
              </svg>
            ) : file.status === "failed" ? (
              <svg viewBox="0 0 24 24" fill="none" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" className="h-4 w-4" style={{ stroke: "var(--error, #ea001d)" }}>
                <path d="M12 9v4M12 16.5v.01" />
                <path d="M10.3 3.9 2.6 17a1.8 1.8 0 0 0 1.55 2.7h15.7a1.8 1.8 0 0 0 1.55-2.7L13.7 3.9a1.8 1.8 0 0 0-3.4 0Z" />
              </svg>
            ) : (
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" className="h-4 w-4">
                <path d="M14 3v4a1 1 0 0 0 1 1h4" />
                <path d="M17 21H7a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h7l5 5v11a2 2 0 0 1-2 2Z" />
              </svg>
            )}
          </span>
          <div className="min-w-0 flex-1">
            <p className="truncate text-sm text-foreground">{file.name}</p>
            <p
              id={progId}
              role="progressbar"
              aria-label={`${file.name} upload progress`}
              aria-valuemin={0}
              aria-valuemax={100}
              aria-valuenow={pct}
              aria-valuetext={statusText(file)}
              className="font-mono text-[11px] text-ns-muted"
            >
              {statusText(file)}
            </p>
          </div>
        </div>
      </div>
    </li>
  );
}

// ---------------------------------------------------------------------------
// simulated upload — used whenever a consumer does not pass `uploadFile`.
// Chunky, irregular progress events (not a smooth ramp) are the point: it's
// what gives the spring something to visibly catch up to.
// ---------------------------------------------------------------------------
function simulateUpload(
  onProgress: (p: number) => void,
  onDone: (ok: boolean) => void
): () => void {
  let p = 0;
  const failAt = Math.random() < 0.16 ? 0.25 + Math.random() * 0.55 : 2; // 2 = never
  const id = setInterval(
    () => {
      p = Math.min(1, p + 0.1 + Math.random() * 0.16);
      if (p >= failAt) {
        clearInterval(id);
        onProgress(Math.min(p, 0.97));
        onDone(false);
        return;
      }
      onProgress(p);
      if (p >= 1) {
        clearInterval(id);
        onDone(true);
      }
    },
    170 + Math.random() * 110
  );
  return () => clearInterval(id);
}

export function VacuumSeal({
  defaultFiles = [],
  accept = [],
  maxSizeBytes = 25 * 1024 * 1024,
  uploadFile,
  onFilesChange,
  className = "",
  "aria-label": ariaLabel = "Upload files",
}: {
  /** files rendered already in their final state — sealed, mid-upload, or failed — at mount, with no entrance animation */
  defaultFiles?: {
    name: string;
    size: number;
    type: string;
    status?: UploadStatus;
    progress?: number;
  }[];
  /** allowed types: extensions (".png") or mime ("image/png", "image/*"); empty = any */
  accept?: string[];
  /** rejects any file larger than this. No default — unlimited. */
  maxSizeBytes?: number;
  /** perform the real upload, reporting 0..1 via onProgress; reject to fail the seal. omit to use a built-in simulated upload. */
  uploadFile?: (file: File, onProgress: (p: number) => void) => Promise<void>;
  /** called with the full file list after any add, progress update, or removal */
  onFilesChange?: (files: VacuumSealFile[]) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** accessible name for the dropzone. Default "Upload files". */
  "aria-label"?: string;
}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const zoneRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const idSeq = useRef(0);
  const dragDepth = useRef(0);
  const cleanupsRef = useRef(new Map<string, () => void>());
  const quartileRef = useRef(new Map<string, number>());
  const frozenIdsRef = useRef(new Set<string>());

  const [files, setFiles] = useState<FileEntry[]>(() =>
    defaultFiles.map((f, i) => {
      const id = `vs-d${i}`;
      frozenIdsRef.current.add(id);
      return {
        id,
        name: f.name,
        size: f.size,
        type: f.type,
        status: f.status ?? "sealed",
        progress: f.progress ?? (f.status === "failed" ? 0 : 1),
      };
    })
  );
  const [isOver, setIsOver] = useState(false);
  const [reduced, setReduced] = useState(false);
  const [announce, setAnnounce] = useState("");
  const hintId = useId();
  const lastNotifyKeyRef = useRef("");

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  useEffect(() => {
    const cleanups = cleanupsRef.current;
    return () => {
      for (const stop of cleanups.values()) stop();
      cleanups.clear();
    };
  }, []);

  const publicFiles = (list: FileEntry[]): VacuumSealFile[] =>
    list.map(({ id, name, size, type }) => ({ id, name, size, type }));

  // notify from an effect, keyed on the id set (add/remove only, not every
  // progress tick) — never call a consumer's setState from inside a
  // setFiles updater, which runs during this component's own render
  useEffect(() => {
    const pub = publicFiles(files);
    const key = pub.map((f) => f.id).join(",");
    if (key !== lastNotifyKeyRef.current) {
      lastNotifyKeyRef.current = key;
      onFilesChange?.(pub);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [files]);

  const startUpload = (id: string, name: string, file: File) => {
    const onProgress = (p: number) => {
      setFiles((fs) => fs.map((f) => (f.id === id ? { ...f, progress: p } : f)));
      const bucket = p >= 1 ? 4 : Math.floor(p * 4);
      const prev = quartileRef.current.get(id) ?? 0;
      if (bucket > prev && bucket > 0 && bucket < 4) {
        quartileRef.current.set(id, bucket);
        setAnnounce(`${name} ${bucket * 25}% uploaded`);
      }
    };
    const finalize = (ok: boolean) => {
      cleanupsRef.current.delete(id);
      setFiles((fs) =>
        fs.map((f) =>
          f.id === id ? { ...f, status: ok ? "sealed" : "failed", progress: ok ? 1 : f.progress } : f
        )
      );
      setAnnounce(ok ? `${name} sealed` : `${name} upload failed`);
    };
    if (uploadFile) {
      let live = true;
      uploadFile(file, (p) => live && onProgress(p)).then(
        () => live && finalize(true),
        () => live && finalize(false)
      );
      cleanupsRef.current.set(id, () => {
        live = false;
      });
    } else {
      const stop = simulateUpload(onProgress, finalize);
      cleanupsRef.current.set(id, stop);
    }
  };

  const validate = (file: File): string | null => {
    if (file.size > maxSizeBytes) return `exceeds the ${formatSize(maxSizeBytes)} limit`;
    if (accept.length > 0) {
      const lower = file.name.toLowerCase();
      const ok = accept.some((a) => {
        const s = a.trim().toLowerCase();
        if (s.startsWith(".")) return lower.endsWith(s);
        if (s.endsWith("/*")) return file.type.startsWith(s.slice(0, -1));
        return file.type === s;
      });
      if (!ok) return "file type not accepted";
    }
    return null;
  };

  const processFiles = (list: FileList | null) => {
    if (!list || list.length === 0) return;
    const accepted: FileEntry[] = [];
    const messages: string[] = [];
    for (const file of Array.from(list)) {
      const reason = validate(file);
      if (reason !== null) {
        messages.push(`${file.name} rejected — ${reason}`);
        continue;
      }
      const id = `vs-${idSeq.current++}`;
      accepted.push({
        id,
        name: file.name,
        size: file.size,
        type: file.type,
        status: "uploading",
        progress: 0,
      });
      startUpload(id, file.name, file);
    }
    if (accepted.length > 0) {
      setFiles((fs) => [...fs, ...accepted]);
      messages.push(...accepted.map((f) => `${f.name} added`));
    }
    if (messages.length > 0) setAnnounce(messages.join(". "));
  };

  const openPicker = () => inputRef.current?.click();

  const onZoneKey = (e: KeyboardEvent<HTMLDivElement>) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      openPicker();
    }
  };
  const dragHasFiles = (e: DragEvent<HTMLDivElement>) =>
    Array.from(e.dataTransfer?.types ?? []).includes("Files");

  const onDragEnter = (e: DragEvent<HTMLDivElement>) => {
    if (!dragHasFiles(e)) return;
    e.preventDefault();
    dragDepth.current += 1;
    if (dragDepth.current === 1) setIsOver(true);
  };
  const onDragOver = (e: DragEvent<HTMLDivElement>) => {
    if (!dragHasFiles(e)) return;
    e.preventDefault();
    if (e.dataTransfer) e.dataTransfer.dropEffect = "copy";
  };
  const onDragLeave = (e: DragEvent<HTMLDivElement>) => {
    if (!dragHasFiles(e)) return;
    e.preventDefault();
    dragDepth.current = Math.max(0, dragDepth.current - 1);
    if (dragDepth.current === 0) setIsOver(false);
  };
  const onDrop = (e: DragEvent<HTMLDivElement>) => {
    if (!dragHasFiles(e)) return;
    e.preventDefault();
    dragDepth.current = 0;
    setIsOver(false);
    processFiles(e.dataTransfer?.files ?? null);
  };

  // -- landing-card autoplay bridge -----------------------------------------
  // Mirrors file-upload-thermal's pattern: the shared pointer-path driver only
  // dispatches Pointer/Mouse events, so a sweep across the zone is bridged
  // into a synthetic drop on its "leave" (sweep-closing) edge, via the exact
  // same processFiles() a real onDrop calls with a File built through the
  // standard constructible DataTransfer. Every visual — outline appearing,
  // spring-tightening, pucker, or fail-wobble — is the real engine above;
  // nothing autoplay-specific is animated. Bounded: the previous demo file
  // is cleared before the next is added, so a card left running never
  // accumulates rows. Gated on [data-autoplay-root], stamped only for
  // embed=1&autoplay=1, so a real hover on /preview/file-upload-seal never wires
  // this up.
  useEffect(() => {
    const zone = zoneRef.current;
    if (!zone || !zone.closest("[data-autoplay-root]")) return;
    let dragging = false;
    let demoId: string | null = null;
    const onEnter = () => {
      dragging = true;
      setIsOver(true);
    };
    const onLeave = () => {
      if (!dragging) return;
      dragging = false;
      setIsOver(false);
      if (demoId) {
        const closing = demoId;
        cleanupsRef.current.get(closing)?.();
        cleanupsRef.current.delete(closing);
        setFiles((fs) => fs.filter((f) => f.id !== closing));
      }
      const dt = new DataTransfer();
      dt.items.add(new File(["demo"], "quarter-report.pdf", { type: "application/pdf" }));
      // idSeq is incremented exactly once per accepted file inside
      // processFiles, synchronously and in order — capturing it just before
      // the call gives the exact id the single dropped file will receive,
      // with no need to diff file lists afterward.
      const nextId = `vs-${idSeq.current}`;
      processFiles(dt.files);
      demoId = nextId;
    };
    zone.addEventListener("pointerenter", onEnter);
    zone.addEventListener("pointerleave", onLeave);
    return () => {
      zone.removeEventListener("pointerenter", onEnter);
      zone.removeEventListener("pointerleave", onLeave);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const hint = `${acceptSummary(accept)} · max ${formatSize(maxSizeBytes)}`;

  return (
    <div ref={rootRef} className={`flex flex-col gap-2 ${className}`}>
      <div
        ref={zoneRef}
        role="button"
        tabIndex={0}
        aria-label={ariaLabel}
        aria-describedby={hintId}
        onClick={openPicker}
        onKeyDown={onZoneKey}
        onDragEnter={onDragEnter}
        onDragOver={onDragOver}
        onDragLeave={onDragLeave}
        onDrop={onDrop}
        className={`relative flex min-h-[7rem] cursor-pointer flex-col items-center justify-center gap-1.5 rounded-md border border-dashed px-6 py-7 text-center outline-none transition-colors duration-200 focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background ${
          isOver
            ? "border-ns-accent bg-ns-accent/[0.05]"
            : "border-border bg-surface hover:border-foreground/25"
        }`}
      >
        <svg
          aria-hidden
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="1.5"
          strokeLinecap="round"
          strokeLinejoin="round"
          className={`h-5 w-5 transition-colors duration-200 ${isOver ? "text-ns-accent" : "text-ns-muted"}`}
        >
          <rect x="4" y="4" width="16" height="16" rx="2" />
          <path d="M9 12h6M12 9v6" />
        </svg>
        <p className="text-sm text-foreground">
          Drop files to seal, or{" "}
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              openPicker();
            }}
            className="rounded-[4px] font-medium text-ns-accent underline-offset-2 outline-none transition-colors hover:underline focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-surface"
          >
            browse
          </button>
        </p>
        <p id={hintId} className="font-mono text-[11px] tracking-wide text-ns-muted">
          {hint}
        </p>
      </div>

      <input
        ref={inputRef}
        type="file"
        multiple
        accept={accept.length > 0 ? accept.join(",") : undefined}
        tabIndex={-1}
        aria-hidden="true"
        className="sr-only"
        onChange={(e) => {
          processFiles(e.target.files);
          e.target.value = "";
        }}
      />

      {files.length > 0 && (
        <ul role="list" aria-label="Uploads" className="flex flex-col">
          {files.map((f) => (
            <FileCard key={f.id} file={f} reduced={reduced} frozen={frozenIdsRef.current.has(f.id)} />
          ))}
        </ul>
      )}

      <p role="status" aria-live="polite" className="min-h-4 font-mono text-[11px] text-ns-muted">
        {announce}
      </p>

      <style>{`
        .ns-file-upload-seal-card[data-just-sealed] {
          animation: ns-file-upload-seal-pucker ${PUCKER_MS}ms cubic-bezier(0.32, 1.6, 0.5, 1) both;
        }
        @keyframes ns-file-upload-seal-pucker {
          0% { transform: scale(1); }
          40% { transform: scale(0.99); }
          100% { transform: scale(1); }
        }
        @media (prefers-reduced-motion: reduce) {
          .ns-file-upload-seal-card[data-just-sealed] { animation: none; }
        }
      `}</style>
    </div>
  );
}

"use client";

import {
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type DragEvent,
  type KeyboardEvent,
  type ReactNode,
} from "react";

// ---------------------------------------------------------------------------
// UpdraftDropzone — file dropzone as a thermal field. Dragging a file over
// the zone spawns rising accent convection wisps on a canvas 2D layer (over
// the control, behind the copy). Accepted drops buoy upward off the drop
// point as DOM chips with damped sway, then squash-land into a docked queue
// rack; rejected files sink 40px and fade. Accept vs reject is felt
// physically, instantly. Direct-DOM rAF that sleeps when every chip is
// docked and every wisp is dead; wisp ink is derived from CSS tokens at
// mount and re-derived live on documentElement class changes.
// ---------------------------------------------------------------------------

// wisps
const SPAWN_RATE = 18; // wisps per second while dragging over
const WISP_CAP = 30; // max live wisps
const WISP_RISE_MIN = 30; // px/s
const WISP_RISE_MAX = 60; // px/s
const WISP_WOBBLE_AMP = 6; // px
const WISP_WOBBLE_PERIOD = 1.2; // s
const WISP_LIFE_MIN = 1.5; // s
const WISP_LIFE_MAX = 2.5; // s
const WISP_ALPHA = 0.12; // peak alpha, from --ns-accent
// accepted-chip flight
const BUOYANCY = 900; // px/s^2 upward boost
const BUOY_T = 0.18; // boost window s
const FLY_K = 70; // spring pull toward dock slot s^-2
const FLY_ZETA = 0.95; // linear drag (near-critical)
const SWAY_AMP = 10; // px
const SWAY_HZ = 2;
const SWAY_DECAY = 6.28; // zeta~0.5 envelope at 2 Hz: exp(-zeta*omega*t)
const SETTLE_DEADLINE = 1.4; // forced-settle per chip s
const STAGGER_MS = 90; // multi-drop launch stagger
// landing squash
const SQUASH_S = 0.88;
const SQUASH_HOLD = 0.12; // s at full squash
const SQUASH_K = 300; // s^-2
const SQUASH_ZETA = 0.6;
// rejected-chip sink
const SINK_G = 600; // px/s^2
const SINK_DIST = 40; // px
const SINK_FADE = 0.5; // s

type Vec3 = readonly [number, number, number];

interface Wisp {
  x: number;
  y: number;
  vy: number;
  phase: number;
  len: number;
  life: number;
  age: number;
}
interface Flight {
  el: HTMLElement;
  ox: number;
  oy: number;
  vx: number;
  vy: number;
  t: number; // negative during stagger wait
  phase: "fly" | "squash";
  squashT: number;
  s: number;
  sv: number;
}
interface SinkState {
  id: string;
  vy: number;
  dy: number;
  age: number;
}

export interface UpdraftFile {
  id: string;
  name: string;
  size: number;
  type: string;
}
interface RejectChip {
  id: string;
  name: string;
  x: number;
  y: number;
}

function parseColor(raw: string): Vec3 | null {
  const s = raw.trim();
  if (s.startsWith("#")) {
    const hex = s.slice(1);
    if (hex.length === 3) {
      const r = parseInt(hex.slice(0, 1) + hex.slice(0, 1), 16);
      const g = parseInt(hex.slice(1, 2) + hex.slice(1, 2), 16);
      const b = parseInt(hex.slice(2, 3) + hex.slice(2, 3), 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    if (hex.length >= 6) {
      const r = parseInt(hex.slice(0, 2), 16);
      const g = parseInt(hex.slice(2, 4), 16);
      const b = parseInt(hex.slice(4, 6), 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    return null;
  }
  const m = s.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
  if (m) return [Number(m[1]), Number(m[2]), Number(m[3])];
  // non-hex/rgb tokens (oklch(), hsl(), lab(), color(), named colors, …) —
  // let the browser normalize the value instead of regexing every possible
  // CSS color syntax: write it into a throwaway element and read back
  // getComputedStyle(...).color, which browsers always resolve to rgb()/rgba().
  if (typeof document === "undefined") return null;
  const probe = document.createElement("span");
  probe.style.color = s;
  if (!probe.style.color) return null; // invalid value, not just an unhandled format
  document.body.appendChild(probe);
  const resolved = getComputedStyle(probe).color;
  document.body.removeChild(probe);
  const m2 = resolved.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
  return m2 ? [Number(m2[1]), Number(m2[2]), Number(m2[3])] : null;
}

function formatSize(bytes: number): string {
  if (bytes >= 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  if (bytes >= 1024) return `${Math.round(bytes / 1024)} KB`;
  return `${bytes} B`;
}

function acceptSummary(accept: string[]): string {
  if (accept.length === 0) return "Any file type";
  return accept
    .map((a) => (a.startsWith(".") ? a.slice(1).toUpperCase() : a))
    .join(", ");
}

function typeIconPath(name: string, type: string): ReactNode {
  const lower = name.toLowerCase();
  if (type.startsWith("image/") || /\.(png|jpe?g|gif|webp|svg)$/.test(lower)) {
    return (
      <>
        <rect x="3" y="3" width="18" height="18" rx="2" />
        <circle cx="9" cy="9" r="2" />
        <path d="m21 15-3.5-3.5a2 2 0 0 0-3 0L6 20" />
      </>
    );
  }
  if (type === "application/pdf" || /\.(pdf|docx?|txt|md|log)$/.test(lower)) {
    return (
      <>
        <path d="M14 3v4a1 1 0 0 0 1 1h4" />
        <path d="M17 21H7a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h7l5 5v11a2 2 0 0 1-2 2Z" />
        <path d="M9 13h6M9 17h4" />
      </>
    );
  }
  return (
    <>
      <path d="M14 3v4a1 1 0 0 0 1 1h4" />
      <path d="M17 21H7a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h7l5 5v11a2 2 0 0 1-2 2Z" />
    </>
  );
}

export function UpdraftDropzone({
  defaultFiles = [],
  accept = [],
  maxSizeBytes = 8 * 1024 * 1024,
  onFilesChange,
  className = "",
  "aria-label": ariaLabel = "Upload files",
}: {
  /** files shown pre-docked in the queue rack */
  defaultFiles?: { name: string; size: number; type: string }[];
  /** allowed types: extensions (".png") or mime ("image/png", "image/*"); empty = any */
  accept?: string[];
  /** rejects any file larger than this. No default — unlimited. */
  maxSizeBytes?: number;
  /** called with the full file list after any add or removal */
  onFilesChange?: (files: UpdraftFile[]) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** accessible name for the dropzone. Default "Upload files". */
  "aria-label"?: string;
}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const zoneRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const chipEls = useRef(new Map<string, HTMLLIElement>());
  const idSeq = useRef(0);
  const dragDepth = useRef(0);
  const reducedRef = useRef(false);
  const pendingRef = useRef<
    { id: string; cx: number; cy: number; delay: number }[]
  >([]);
  const engineRef = useRef<{
    setDrag: (on: boolean) => void;
    dragPoint: (clientX: number) => void;
    fly: (el: HTMLElement, cx: number, cy: number, delayMs: number) => void;
    sink: (el: HTMLElement, id: string) => void;
  } | null>(null);

  const [files, setFiles] = useState<UpdraftFile[]>(() =>
    defaultFiles.map((f, i) => ({ ...f, id: `uf-d${i}` }))
  );
  const [rejects, setRejects] = useState<RejectChip[]>([]);
  const [isOver, setIsOver] = useState(false);
  const [announce, setAnnounce] = useState("");
  const hintId = useId();
  const liveId = useId();

  // -- engine: wisp canvas + chip physics, direct-DOM only ------------------
  useEffect(() => {
    const root = rootRef.current;
    const zone = zoneRef.current;
    const canvas = canvasRef.current;
    if (!root || !zone || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;
    reducedRef.current = reduced;

    // token-derived ink: read at mount, re-derived on theme class change
    let accentInk: Vec3 = [0, 107, 255];
    const derive = () => {
      const cs = getComputedStyle(document.documentElement);
      accentInk = parseColor(cs.getPropertyValue("--ns-accent")) ?? accentInk;
    };
    derive();

    // hot-path state: locals only, never React state
    let w = 0;
    let h = 0;
    let dpr = 1;
    let sized = false;
    let raf = 0;
    let last = 0;
    let visible = true;
    let dragging = false;
    let dragLeft = 0; // cached zone rect left while dragging
    let pointerX = -1; // canvas-local, -1 = unknown
    let spawnAcc = 0;
    let inkOn = false; // canvas has pixels that need a final clear
    const wisps: Wisp[] = [];
    const flights = new Map<HTMLElement, Flight>();
    const sinks = new Map<HTMLElement, SinkState>();

    const finishSink = (id: string) =>
      setRejects((rs) => rs.filter((r) => r.id !== id));

    const clearCanvas = () => {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
    };

    const resize = () => {
      const rect = zone.getBoundingClientRect();
      if (rect.width < 4 || rect.height < 4) {
        sized = false; // zero-size guard — never spawn into nothing
        return;
      }
      w = rect.width;
      h = rect.height;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
      // canvas is a replaced element — inset alone does not size it
      canvas.style.width = `${w}px`;
      canvas.style.height = `${h}px`;
      sized = true;
      clearCanvas();
    };
    resize();

    const settleChip = (f: Flight) => {
      f.el.style.transform = "";
      f.el.style.transformOrigin = "";
      f.el.style.opacity = "";
      f.el.style.zIndex = "";
      f.el.style.willChange = "";
      flights.delete(f.el);
    };

    const loop = (now: number) => {
      raf = 0;
      if (!visible || document.hidden) {
        last = 0;
        return; // paused offscreen/hidden — wake() resumes
      }
      const dt = last ? Math.min(0.05, (now - last) / 1000) : 1 / 60;
      last = now;
      let active = false;

      // -- wisps: pruned array, full clear + redraw every frame -------------
      if (sized) {
        if (dragging) {
          spawnAcc += SPAWN_RATE * dt;
          while (spawnAcc >= 1) {
            spawnAcc -= 1;
            if (wisps.length >= WISP_CAP) continue;
            // bias spawn toward the dragged pointer's column
            const cx = pointerX >= 0 ? pointerX : w / 2;
            const x =
              Math.random() < 0.7
                ? Math.min(w - 2, Math.max(2, cx + (Math.random() - 0.5) * 140))
                : Math.random() * w;
            wisps.push({
              x,
              y: h - 2 - Math.random() * 10,
              vy: -(WISP_RISE_MIN + Math.random() * (WISP_RISE_MAX - WISP_RISE_MIN)),
              phase: Math.random() * Math.PI * 2,
              len: 10 + Math.random() * 8,
              life: WISP_LIFE_MIN + Math.random() * (WISP_LIFE_MAX - WISP_LIFE_MIN),
              age: 0,
            });
          }
          active = true;
        }
        if (wisps.length > 0) {
          clearCanvas();
          inkOn = true;
          ctx.lineCap = "round";
          ctx.lineWidth = 1.5;
          for (let i = wisps.length - 1; i >= 0; i--) {
            const wp = wisps[i];
            if (!wp) continue;
            wp.age += dt;
            wp.y += wp.vy * dt;
            if (wp.age >= wp.life || wp.y + wp.len < 0) {
              wisps.splice(i, 1);
              continue;
            }
            const xd =
              wp.x +
              WISP_WOBBLE_AMP *
                Math.sin((wp.age / WISP_WOBBLE_PERIOD) * Math.PI * 2 + wp.phase);
            const a = WISP_ALPHA * Math.sin((Math.PI * wp.age) / wp.life);
            ctx.strokeStyle = `rgba(${accentInk[0]},${accentInk[1]},${accentInk[2]},${a.toFixed(3)})`;
            ctx.beginPath();
            ctx.moveTo(xd, wp.y);
            ctx.quadraticCurveTo(xd + 3, wp.y + wp.len * 0.5, xd, wp.y + wp.len);
            ctx.stroke();
          }
          active = true;
        } else if (inkOn) {
          clearCanvas(); // one explicit final clear, then the layer is inert
          inkOn = false;
        }
      }

      // -- accepted-chip flights: OFFSET transforms toward the dock slot ----
      for (const f of flights.values()) {
        if (!f.el.isConnected) {
          flights.delete(f.el);
          continue;
        }
        active = true;
        f.t += dt;
        if (f.t < 0) continue; // stagger wait, chip hidden at drop offset
        if (f.phase === "fly") {
          if (f.el.style.opacity !== "1") f.el.style.opacity = "1";
          const c = 2 * FLY_ZETA * Math.sqrt(FLY_K);
          const boost = f.t < BUOY_T ? BUOYANCY : 0;
          f.vx += (-FLY_K * f.ox - c * f.vx) * dt;
          f.vy += (-FLY_K * f.oy - c * f.vy - boost) * dt;
          f.ox += f.vx * dt;
          f.oy += f.vy * dt;
          const arrived =
            Math.abs(f.ox) < 1 &&
            Math.abs(f.oy) < 1 &&
            Math.abs(f.vx) + Math.abs(f.vy) < 24;
          if (arrived || f.t >= SETTLE_DEADLINE) {
            // forced-settle deadline — a chip never hovers past 1.4s
            f.phase = "squash";
            f.squashT = 0;
            f.s = SQUASH_S;
            f.sv = 0;
            f.el.style.transformOrigin = "50% 100%";
            f.el.style.transform = `scaleY(${SQUASH_S})`;
          } else {
            const sway =
              SWAY_AMP *
              Math.exp(-SWAY_DECAY * f.t) *
              Math.sin(Math.PI * 2 * SWAY_HZ * f.t);
            f.el.style.transform = `translate3d(${(f.ox + sway).toFixed(2)}px, ${f.oy.toFixed(2)}px, 0)`;
          }
        } else {
          f.squashT += dt;
          if (f.squashT >= SQUASH_HOLD) {
            const c = 2 * SQUASH_ZETA * Math.sqrt(SQUASH_K);
            f.sv += (-SQUASH_K * (f.s - 1) - c * f.sv) * dt;
            f.s += f.sv * dt;
            if (Math.abs(f.s - 1) < 0.004 && Math.abs(f.sv) < 0.08) {
              settleChip(f);
              continue;
            }
          }
          f.el.style.transform = `scaleY(${f.s.toFixed(4)})`;
        }
      }

      // -- rejected-chip sinks ----------------------------------------------
      for (const [el, s] of sinks) {
        if (!el.isConnected) {
          sinks.delete(el);
          continue;
        }
        s.age += dt;
        s.vy += SINK_G * dt;
        s.dy = Math.min(SINK_DIST, s.dy + s.vy * dt);
        el.style.transform = `translate3d(0, ${s.dy.toFixed(2)}px, 0)`;
        el.style.opacity = Math.max(0, 1 - s.age / SINK_FADE).toFixed(3);
        if (s.age >= SINK_FADE) {
          sinks.delete(el);
          finishSink(s.id);
        } else {
          active = true;
        }
      }

      if (active) raf = requestAnimationFrame(loop);
      else last = 0; // sleep — all chips docked, all wisps dead
    };

    const wake = () => {
      if (!raf && !reduced) raf = requestAnimationFrame(loop);
    };

    engineRef.current = {
      setDrag: (on) => {
        if (reduced) return; // static token-border highlight only
        dragging = on;
        if (on) {
          dragLeft = zone.getBoundingClientRect().left;
          spawnAcc = 0;
          wake();
        }
      },
      dragPoint: (clientX) => {
        pointerX = clientX - dragLeft;
      },
      fly: (el, cx, cy, delayMs) => {
        if (reduced) return; // chips appear docked instantly
        const r = el.getBoundingClientRect();
        if (r.width < 2 || r.height < 2) return; // zero-size guard — dock instantly
        const f: Flight = {
          el,
          ox: cx - (r.left + r.width / 2),
          oy: cy - (r.top + r.height / 2),
          vx: 0,
          vy: 0,
          t: -delayMs / 1000,
          phase: "fly",
          squashT: 0,
          s: 1,
          sv: 0,
        };
        el.style.willChange = "transform";
        el.style.zIndex = "20";
        el.style.opacity = delayMs > 0 ? "0" : "1";
        el.style.transform = `translate3d(${f.ox.toFixed(2)}px, ${f.oy.toFixed(2)}px, 0)`;
        flights.set(el, f);
        wake();
      },
      sink: (el, id) => {
        if (sinks.has(el)) return;
        sinks.set(el, { id, vy: 0, dy: 0, age: 0 });
        wake();
      },
    };

    const ro = new ResizeObserver(resize);
    ro.observe(zone);
    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible) wake();
    });
    io.observe(root);
    // live theme re-derive: watch documentElement class flips
    const mo = new MutationObserver(derive);
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });
    const onVis = () => {
      if (!document.hidden) wake();
    };
    document.addEventListener("visibilitychange", onVis);

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", onVis);
      wisps.length = 0;
      flights.clear();
      sinks.clear();
      engineRef.current = null;
    };
  }, []);

  // -- landing-card autoplay bridge -----------------------------------------
  // The component's only live interaction is the native HTML5 drag/drop API
  // (dragenter/dragover/dragleave/drop with a real DataTransfer) — there is
  // no pointer/hover/press affordance to synthesize against, so the shared
  // autoplay driver (which only dispatches Pointer/Mouse events) cannot
  // reach it as-is. This bridges the driver's synthetic pointer sweep into
  // the exact same setDrag/dragPoint calls the real dragenter/dragover
  // handlers already make, and — on the synthetic "leave" that closes each
  // sweep — into the exact same processFiles() the real onDrop handler
  // calls, with a File built via the standard constructible DataTransfer.
  // No new animation or state machine: every visual (wisps, border, the
  // buoy-and-dock flight) is the engine that already exists for real drops.
  // Native listeners (not React props) mirror the pattern this repo already
  // uses for driver-driven hover (dock-cursor-magnify's
  // addEventListener("pointerleave", ...)) so the driver's directly-
  // dispatched, non-bubbling pointerleave is caught reliably.
  // Gated on [data-autoplay-root]: the preview route only ever stamps that
  // attribute for `embed=1&autoplay=1` cards, so a real mouse hover on
  // /preview/file-upload-thermal (or plain ?embed=1) never wires this up and
  // behaves exactly as before.
  useEffect(() => {
    const zone = zoneRef.current;
    if (!zone || !zone.closest("[data-autoplay-root]")) return;
    let dragging = false;
    const baseline = () => defaultFiles.map((f, i) => ({ ...f, id: `uf-d${i}` }));
    const onMove = (e: PointerEvent) => {
      if (!dragging) {
        dragging = true;
        setIsOver(true);
        engineRef.current?.setDrag(true);
      }
      engineRef.current?.dragPoint(e.clientX);
    };
    const onLeave = () => {
      if (!dragging) return;
      dragging = false;
      setIsOver(false);
      engineRef.current?.setDrag(false);
      // bound growth: clear the chip the *previous* sweep dropped before
      // adding this sweep's — so a chip stays docked and visible for a
      // full cycle (not just the ~300ms rest beat) and a card left running
      // never accumulates chips.
      setFiles(baseline());
      onFilesChange?.(baseline());
      // demo "drop": a synthetic accepted file rides the same buoy-and-dock
      // flight a real drop uses, via the same processFiles() a real onDrop
      // calls — accept-types validation runs on it exactly as it would on
      // a real file.
      const dt = new DataTransfer();
      dt.items.add(new File(["demo"], "render-log.txt", { type: "text/plain" }));
      processFiles(dt.files, null);
    };
    zone.addEventListener("pointermove", onMove);
    zone.addEventListener("pointerleave", onLeave);
    return () => {
      zone.removeEventListener("pointermove", onMove);
      zone.removeEventListener("pointerleave", onLeave);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [defaultFiles]);

  // launch flights for freshly docked chips — layout effect so the offset
  // transform lands before paint (no flash of the chip already docked)
  useLayoutEffect(() => {
    const pend = pendingRef.current;
    if (pend.length === 0) return;
    pendingRef.current = [];
    for (const p of pend) {
      const el = chipEls.current.get(p.id);
      if (el) engineRef.current?.fly(el, p.cx, p.cy, p.delay);
    }
  }, [files]);

  const validate = (file: File): string | null => {
    if (file.size > maxSizeBytes)
      return `exceeds the ${formatSize(maxSizeBytes)} limit`;
    if (accept.length > 0) {
      const lower = file.name.toLowerCase();
      const ok = accept.some((a) => {
        const s = a.trim().toLowerCase();
        if (s.startsWith(".")) return lower.endsWith(s);
        if (s.endsWith("/*")) return file.type.startsWith(s.slice(0, -1));
        return file.type === s;
      });
      if (!ok) return "file type not accepted";
    }
    return null;
  };

  const processFiles = (
    list: FileList | null,
    point: { x: number; y: number } | null
  ) => {
    if (!list || list.length === 0) return;
    const zr = zoneRef.current?.getBoundingClientRect();
    const px = point?.x ?? (zr ? zr.left + zr.width / 2 : 0);
    const py = point?.y ?? (zr ? zr.top + zr.height / 2 : 0);
    const accepted: UpdraftFile[] = [];
    const newRejects: RejectChip[] = [];
    const messages: string[] = [];
    for (const file of Array.from(list)) {
      const reason = validate(file);
      if (reason === null) {
        accepted.push({
          id: `uf-${idSeq.current++}`,
          name: file.name,
          size: file.size,
          type: file.type,
        });
      } else {
        messages.push(`${file.name} rejected — ${reason}`);
        if (!reducedRef.current && zr) {
          newRejects.push({
            id: `rj-${idSeq.current++}`,
            name: file.name,
            x: Math.min(zr.width - 8, Math.max(8, px - zr.left)),
            y: Math.min(zr.height - 8, Math.max(8, py - zr.top)),
          });
        }
      }
    }
    if (accepted.length > 0) {
      if (!reducedRef.current) {
        pendingRef.current.push(
          ...accepted.map((f, i) => ({
            id: f.id,
            cx: px,
            cy: py,
            delay: i * STAGGER_MS, // stagger so flights never overlap
          }))
        );
      }
      const next = [...files, ...accepted];
      setFiles(next);
      onFilesChange?.(next);
      messages.push(...accepted.map((f) => `${f.name} added`));
    }
    if (newRejects.length > 0) setRejects((rs) => [...rs, ...newRejects]);
    if (messages.length > 0) setAnnounce(messages.join(". "));
  };

  const removeFile = (id: string) => {
    const i = files.findIndex((f) => f.id === id);
    if (i === -1) return;
    const removed = files[i];
    const neighbor = files[i + 1] ?? files[i - 1];
    const next = files.filter((f) => f.id !== id);
    setFiles(next);
    onFilesChange?.(next);
    if (removed) setAnnounce(`${removed.name} removed`);
    queueMicrotask(() => {
      (neighbor
        ? chipEls.current.get(neighbor.id)
        : zoneRef.current
      )?.focus();
    });
  };

  const openPicker = () => inputRef.current?.click();

  const onZoneKey = (e: KeyboardEvent<HTMLDivElement>) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      openPicker();
    }
  };
  const dragHasFiles = (e: DragEvent<HTMLDivElement>) =>
    Array.from(e.dataTransfer?.types ?? []).includes("Files");

  const onDragEnter = (e: DragEvent<HTMLDivElement>) => {
    if (!dragHasFiles(e)) return;
    e.preventDefault();
    dragDepth.current += 1;
    if (dragDepth.current === 1) {
      setIsOver(true);
      engineRef.current?.setDrag(true);
    }
  };
  const onDragOver = (e: DragEvent<HTMLDivElement>) => {
    if (!dragHasFiles(e)) return;
    e.preventDefault();
    if (e.dataTransfer) e.dataTransfer.dropEffect = "copy";
    engineRef.current?.dragPoint(e.clientX);
  };
  const onDragLeave = (e: DragEvent<HTMLDivElement>) => {
    if (!dragHasFiles(e)) return;
    e.preventDefault();
    dragDepth.current = Math.max(0, dragDepth.current - 1);
    if (dragDepth.current === 0) {
      setIsOver(false);
      engineRef.current?.setDrag(false);
    }
  };
  const onDrop = (e: DragEvent<HTMLDivElement>) => {
    if (!dragHasFiles(e)) return;
    e.preventDefault();
    dragDepth.current = 0;
    setIsOver(false);
    engineRef.current?.setDrag(false);
    processFiles(e.dataTransfer?.files ?? null, {
      x: e.clientX,
      y: e.clientY,
    });
  };

  const hint = `${acceptSummary(accept)} · max ${formatSize(maxSizeBytes)}`;

  return (
    <div ref={rootRef} className={`flex flex-col gap-3 ${className}`}>
      <div
        ref={zoneRef}
        role="button"
        tabIndex={0}
        aria-label={ariaLabel}
        aria-describedby={hintId}
        onClick={openPicker}
        onKeyDown={onZoneKey}
        onDragEnter={onDragEnter}
        onDragOver={onDragOver}
        onDragLeave={onDragLeave}
        onDrop={onDrop}
        className={`relative flex min-h-[8.5rem] cursor-pointer flex-col items-center justify-center gap-1.5 overflow-hidden rounded-md border border-dashed px-6 py-8 text-center outline-none transition-colors duration-200 focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background ${
          isOver
            ? "border-ns-accent bg-ns-accent/[0.05]"
            : "border-border bg-surface hover:border-foreground/25"
        }`}
      >
        <canvas
          ref={canvasRef}
          aria-hidden
          className="pointer-events-none absolute left-0 top-0"
        />
        <svg
          aria-hidden
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="1.5"
          strokeLinecap="round"
          strokeLinejoin="round"
          className={`relative z-[1] h-5 w-5 transition-colors duration-200 ${
            isOver ? "text-ns-accent" : "text-ns-muted"
          }`}
        >
          <path d="M12 16V4" />
          <path d="m7 9 5-5 5 5" />
          <path d="M4 20h16" />
        </svg>
        <p className="relative z-[1] text-sm text-foreground">
          Drop files to attach, or{" "}
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              openPicker();
            }}
            className="rounded-[4px] font-medium text-ns-accent underline-offset-2 outline-none transition-colors hover:underline focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-surface"
          >
            browse
          </button>
        </p>
        <p
          id={hintId}
          className="relative z-[1] font-mono text-[11px] tracking-wide text-ns-muted"
        >
          {hint}
        </p>

        {/* rejected files sink and fade inside the zone */}
        {rejects.map((r) => (
          <div
            key={r.id}
            aria-hidden
            className="pointer-events-none absolute z-10 -translate-x-1/2 -translate-y-1/2"
            style={{ left: r.x, top: r.y }}
          >
            <div
              ref={(el) => {
                if (el) engineRef.current?.sink(el, r.id);
              }}
              className="flex max-w-[11rem] items-center gap-1.5 rounded-sm border border-border bg-background px-2 py-1 shadow-sm"
            >
              <span className="truncate text-[11px] text-ns-muted line-through">
                {r.name}
              </span>
            </div>
          </div>
        ))}
      </div>

      <input
        ref={inputRef}
        type="file"
        multiple
        accept={accept.length > 0 ? accept.join(",") : undefined}
        tabIndex={-1}
        aria-hidden="true"
        className="sr-only"
        onChange={(e) => {
          processFiles(e.target.files, null);
          e.target.value = "";
        }}
      />

      {files.length > 0 && (
        <ul role="list" aria-label="Attached files" className="flex flex-wrap gap-2">
          {files.map((f) => (
            <li
              key={f.id}
              ref={(el) => {
                if (el) chipEls.current.set(f.id, el);
                else chipEls.current.delete(f.id);
              }}
              tabIndex={0}
              aria-label={`${f.name}, ${formatSize(f.size)}. Press Delete to remove.`}
              onKeyDown={(e) => {
                if (e.key === "Delete" || e.key === "Backspace") {
                  e.preventDefault();
                  removeFile(f.id);
                }
              }}
              className="relative flex items-center gap-2 rounded-sm border border-border bg-surface py-1.5 pl-2.5 pr-1.5 outline-none transition-colors hover:border-foreground/25 focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background"
            >
              <svg
                aria-hidden
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="1.5"
                strokeLinecap="round"
                strokeLinejoin="round"
                className="h-3.5 w-3.5 shrink-0 text-ns-muted"
              >
                {typeIconPath(f.name, f.type)}
              </svg>
              <span className="max-w-[10rem] truncate text-xs text-foreground">
                {f.name}
              </span>
              <span className="font-mono text-[10px] text-ns-muted">
                {formatSize(f.size)}
              </span>
              <button
                type="button"
                aria-label={`Remove ${f.name}`}
                onClick={() => removeFile(f.id)}
                className="rounded-[4px] p-0.5 text-ns-muted outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ns-accent"
              >
                <svg
                  aria-hidden
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="1.5"
                  strokeLinecap="round"
                  className="h-3 w-3"
                >
                  <path d="M18 6 6 18M6 6l12 12" />
                </svg>
              </button>
            </li>
          ))}
        </ul>
      )}

      <p
        id={liveId}
        role="status"
        aria-live="polite"
        className="min-h-4 font-mono text-[11px] text-ns-muted"
      >
        {announce}
      </p>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";

// Faceted filter chips as a sieve. A hairline mesh fans from a hub above the
// chip row down to every chip; active facets read as taut, bright threads,
// inactive ones as faint background lattice. Hovering a chip tightens its
// own thread (sag reduces toward a straight line via a CSS transition on the
// SVG path's `d` — same-topology path transitions animate natively in
// Chromium, no rAF needed for a discrete hover response). Deselecting a
// facet widens the results and shakes a few particles through the gap left
// at that chip; the result count re-renders as a staggered dot bar, never a
// tweened number. Chips are real toggle buttons (aria-pressed, visible
// accessible names); the count changes announce through an sr-only region.

type Facet = { key: string; label: string; factor: number };

const FACETS: Facet[] = [
  { key: "in-stock", label: "In stock", factor: 0.72 },
  { key: "new", label: "New", factor: 0.42 },
  { key: "on-sale", label: "On sale", factor: 0.58 },
  { key: "bestseller", label: "Bestseller", factor: 0.34 },
];

const POOL = 240;
const DOT_MAX = 16;
const HUB_HEIGHT = 40;

type Particle = { id: number; x: number };
let seq = 0;

export function SieveFacets({
  defaultActive = ["in-stock", "bestseller"],
  className = "",
}: {
  /** facet ids checked at mount */
  defaultActive?: string[];
  /** extra classes merged onto the rendered root element */
  className?: string;
}) {
  const [active, setActive] = useState<Set<string>>(() => new Set(defaultActive));
  const [hovered, setHovered] = useState<string | null>(null);
  const [particles, setParticles] = useState<Particle[]>([]);
  const [anchors, setAnchors] = useState<Record<string, number>>({});
  const [rowWidth, setRowWidth] = useState(0);
  const rowRef = useRef<HTMLDivElement>(null);
  const chipRefs = useRef<Record<string, HTMLButtonElement | null>>({});
  const liveRef = useRef<HTMLDivElement>(null);
  const reducedRef = useRef(false);

  useEffect(() => {
    reducedRef.current = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  }, []);

  const measure = useCallback(() => {
    const row = rowRef.current;
    if (!row) return;
    const rowRect = row.getBoundingClientRect();
    const next: Record<string, number> = {};
    for (const f of FACETS) {
      const el = chipRefs.current[f.key];
      if (el) {
        const r = el.getBoundingClientRect();
        next[f.key] = r.left + r.width / 2 - rowRect.left;
      }
    }
    setAnchors(next);
    setRowWidth(rowRect.width);
  }, []);

  useLayoutEffect(() => {
    measure();
    const row = rowRef.current;
    const ro = row ? new ResizeObserver(measure) : undefined;
    if (row && ro) ro.observe(row);
    window.addEventListener("resize", measure);
    return () => {
      ro?.disconnect();
      window.removeEventListener("resize", measure);
    };
  }, [measure]);

  const count = useMemo(() => {
    let c = POOL;
    for (const f of FACETS) if (active.has(f.key)) c *= f.factor;
    return Math.max(1, Math.round(c));
  }, [active]);

  const filledDots = Math.min(DOT_MAX, Math.max(0, Math.round((count / POOL) * DOT_MAX)));

  const toggle = (key: string) => {
    const wasActive = active.has(key);
    const next = new Set(active);
    if (wasActive) next.delete(key);
    else next.add(key);
    setActive(next);

    if (wasActive) {
      // excluded results shake back through the gap this facet leaves
      const x = anchors[key] ?? rowWidth / 2;
      const spawned: Particle[] = reducedRef.current
        ? []
        : Array.from({ length: 4 }, () => ({ id: ++seq, x: x + (Math.random() - 0.5) * 24 }));
      if (spawned.length) setParticles((p) => [...p, ...spawned]);
    }

    let nextCount = POOL;
    for (const f of FACETS) if (next.has(f.key)) nextCount *= f.factor;
    nextCount = Math.max(1, Math.round(nextCount));
    if (liveRef.current) liveRef.current.textContent = `${nextCount} results`;
  };

  const removeParticle = (id: number) => setParticles((p) => p.filter((x) => x.id !== id));

  const allClear = active.size === 0;

  return (
    <div className={`w-full max-w-md ${className}`}>
      <style>{`
        @keyframes nsui-sieve-fall {
          0% { transform: translateY(0) scale(1); opacity: 0.9; }
          100% { transform: translateY(56px) scale(0.5); opacity: 0; }
        }
        .nsui-sieve-line { transition: d 220ms ease-out, opacity 220ms ease-out, stroke-width 220ms ease-out; }
        .nsui-sieve-mesh { transition: opacity 300ms ease-out, transform 300ms ease-out; }
        .nsui-sieve-dot { transition: opacity 260ms ease-out, transform 260ms ease-out; }
      `}</style>

      {/* mesh: hairline threads from a hub down to each chip */}
      <svg
        aria-hidden="true"
        className={`nsui-sieve-mesh block w-full ${allClear ? "scale-95 opacity-0" : "scale-100 opacity-100"}`}
        style={{ height: HUB_HEIGHT }}
        viewBox={`0 0 ${Math.max(1, rowWidth)} ${HUB_HEIGHT}`}
        preserveAspectRatio="none"
      >
        <circle cx={rowWidth / 2} cy={4} r={2} className="fill-ns-muted" />
        {FACETS.map((f) => {
          const x = anchors[f.key];
          if (x === undefined) return null;
          const isActive = active.has(f.key);
          const isHover = hovered === f.key;
          const hubX = rowWidth / 2;
          const sag = isHover ? 3 : 13;
          const midX = (hubX + x) / 2;
          const midY = 4 + (HUB_HEIGHT - 4) * 0.5 + sag;
          return (
            <path
              key={f.key}
              className="nsui-sieve-line"
              d={`M ${hubX} 4 Q ${midX} ${midY} ${x} ${HUB_HEIGHT}`}
              fill="none"
              stroke={isActive ? "var(--foreground)" : "var(--border)"}
              strokeOpacity={isActive ? (isHover ? 0.85 : 0.55) : isHover ? 0.65 : 0.35}
              strokeWidth={isActive ? (isHover ? 1.75 : 1.25) : 1}
            />
          );
        })}
      </svg>

      {/* particle overlay */}
      <div aria-hidden="true" className="pointer-events-none relative h-0 overflow-visible">
        {particles.map((p) => (
          <span
            key={p.id}
            onAnimationEnd={() => removeParticle(p.id)}
            className="absolute top-0 h-1.5 w-1.5 rounded-full bg-foreground/70"
            style={{ left: p.x, animation: "nsui-sieve-fall 520ms ease-in forwards" }}
          />
        ))}
      </div>

      <div ref={rowRef} className="mt-2 flex flex-wrap justify-center gap-2">
        {FACETS.map((f) => {
          const isActive = active.has(f.key);
          return (
            <button
              key={f.key}
              ref={(el) => {
                chipRefs.current[f.key] = el;
              }}
              type="button"
              aria-pressed={isActive}
              onClick={() => toggle(f.key)}
              onMouseEnter={() => setHovered(f.key)}
              onMouseLeave={() => setHovered((h) => (h === f.key ? null : h))}
              onFocus={() => setHovered(f.key)}
              onBlur={() => setHovered((h) => (h === f.key ? null : h))}
              className={`rounded-full border px-3 py-1.5 font-mono text-xs outline-none transition-colors duration-150 focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background ${
                isActive
                  ? "border-foreground/50 bg-foreground/[0.08] text-foreground"
                  : "border-border text-ns-muted hover:border-foreground/30 hover:text-foreground"
              }`}
            >
              {f.label}
            </button>
          );
        })}
      </div>

      <div className="mt-6 flex flex-col items-center gap-2">
        <div className="flex items-center gap-1" aria-hidden="true">
          {Array.from({ length: DOT_MAX }, (_, i) => {
            const filled = i < filledDots;
            return (
              <span
                key={i}
                className={`nsui-sieve-dot h-1.5 w-1.5 rounded-full ${filled ? "scale-100 bg-foreground opacity-90" : "scale-75 bg-ns-muted opacity-30"}`}
                style={reducedRef.current ? undefined : { transitionDelay: `${i * 22}ms` }}
              />
            );
          })}
        </div>
        <p className="font-mono text-xs text-ns-muted">{count} results</p>
      </div>

      <div ref={liveRef} aria-live="polite" aria-atomic="true" className="sr-only" />
    </div>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState, type KeyboardEvent } from "react";

// ---------------------------------------------------------------------------
// FlamegraphAsciiFrames — a CPU-profile flame graph laid out in monospace
// character cells. One ROW per stack depth, frame WIDTH proportional to sample
// count, self-vs-total time encoded as ink weight. This is deliberately NOT a
// squarified/slice-and-dice partition (that is treemap-ascii-partition's
// mechanism): there is a real depth axis here, and a frame's horizontal extent
// is inherited from its parent's extent, never re-packed to fill a rectangle.
//
// LAYOUT: the zoom root spans all `cols` columns. A child of a frame spanning
// [x, x+w) gets childW = round(w * total(child) / total(parent)), laid left to
// right in the parent's own declared child order — stable, never sorted by
// size, so the same call site sits in the same place across renders. Children
// whose childW < 3 are dropped and accumulated into ONE trailing `... n` frame
// carrying their summed sample count: narrow frames become one honest marker
// instead of a row of unreadable one-column slivers.
//
// GLYPHS: a frame renders a left rule followed by its name truncated with an
// ellipsis to w-1 columns. The rest of its row is blank, so the graph is
// mostly negative space with a stepped silhouette rather than a filled block.
// ---------------------------------------------------------------------------

export interface FlameNode {
  /** Frame name, as it would appear in a profiler's stack. */
  name: string;
  /** Samples attributed to this frame itself, excluding its children. */
  self: number;
  children?: FlameNode[];
}

export interface FlamegraphAsciiFramesProps {
  /** Root of the sample tree. Totals are rolled up once, internally. */
  tree?: FlameNode;
  /** Rows are this tall in px; also drives the graph's overall height. */
  rowHeight?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

/** A child narrower than this many columns cannot carry a readable label. */
const MIN_FRAME_COLS = 3;
/** Self-fraction bucket edges. Four buckets are the ONLY visual encoding. */
const INK_BUCKETS = [0.02, 0.1, 0.3] as const;
/** Fallback column count used for the first paint, before measurement. */
const DEFAULT_COLS = 96;

const DEFAULT_TREE: FlameNode = {
  name: "node server.js",
  self: 74,
  children: [
    { name: "uv__io_poll", self: 486 },
    {
      name: "http.Server.emit",
      self: 74,
      children: [
        {
          name: "router.handle",
          self: 96,
          children: [
            { name: "parseHeaders", self: 402 },
            {
              name: "auth.verifyJwt",
              self: 130,
              children: [
                { name: "crypto.verify", self: 314 },
                { name: "jwt.decode", self: 14, children: [{ name: "Buffer.toString", self: 152 }] },
              ],
            },
            {
              name: "orders.list",
              self: 160,
              children: [
                {
                  name: "pg.query",
                  self: 68,
                  children: [
                    { name: "net.write", self: 214 },
                    {
                      name: "parseRowDescription",
                      self: 20,
                      children: [{ name: "Buffer.readUInt32BE", self: 234 }],
                    },
                  ],
                },
                { name: "serialize", self: 34, children: [{ name: "JSON.stringify", self: 284 }] },
              ],
            },
            { name: "metrics.observe", self: 18, children: [{ name: "hist.record", self: 22 }] },
            { name: "cors.apply", self: 14 },
            { name: "compress.gzip", self: 96 },
          ],
        },
        { name: "keepAliveTimeout", self: 26 },
      ],
    },
    { name: "gc.MarkCompact", self: 168 },
    { name: "require.resolve", self: 12 },
  ],
};

// --- rollup ---------------------------------------------------------------

interface RolledNode {
  key: string;
  name: string;
  self: number;
  /** total(n) = n.self + sum(total(children)), memoized once per tree. */
  total: number;
  children: RolledNode[];
}

function roll(node: FlameNode, key: string, index: Map<string, RolledNode>): RolledNode {
  const children = (node.children ?? []).map((c, i) => roll(c, `${key}.${i}`, index));
  const self = Math.max(0, node.self);
  const rolled: RolledNode = {
    key,
    name: node.name,
    self,
    total: self + children.reduce((s, c) => s + c.total, 0),
    children,
  };
  index.set(key, rolled);
  return rolled;
}

// --- layout ---------------------------------------------------------------

interface Frame {
  key: string;
  name: string;
  depth: number;
  /** Column offset and width, in character cells of the current `cols` grid. */
  x: number;
  w: number;
  self: number;
  total: number;
  parentKey: string | null;
  hasChildren: boolean;
  /** True for the aggregate `...` marker standing in for dropped siblings. */
  fold: boolean;
  foldCount: number;
}

function layoutFrames(root: RolledNode, cols: number): Frame[] {
  const out: Frame[] = [];
  walk(root, 0, cols, 0, null, out);
  return out;
}

function walk(
  node: RolledNode,
  x: number,
  w: number,
  depth: number,
  parentKey: string | null,
  out: Frame[],
) {
  out.push({
    key: node.key,
    name: node.name,
    depth,
    x,
    w,
    self: node.self,
    total: node.total,
    parentKey,
    hasChildren: node.children.length > 0,
    fold: false,
    foldCount: 0,
  });

  if (!node.children.length || node.total <= 0 || w <= 0) return;

  const childrenTotal = node.children.reduce((s, c) => s + c.total, 0);
  // The children run occupies only their share of the parent's span; the
  // remainder to the right is the parent's own self time, left as blank.
  const span = Math.round((w * childrenTotal) / node.total);

  const kept: { node: RolledNode; w: number }[] = [];
  let foldSamples = 0;
  let foldW = 0;
  let foldCount = 0;
  for (const child of node.children) {
    const cw = Math.max(0, Math.round((w * child.total) / node.total));
    if (cw < MIN_FRAME_COLS) {
      foldSamples += child.total;
      foldW += cw;
      foldCount += 1;
    } else {
      kept.push({ node: child, w: cw });
    }
  }

  // Rounding residual is absorbed by the LAST laid frame, so the run ends
  // exactly on `span` rather than drifting a column per child.
  let markerW = foldCount ? Math.max(MIN_FRAME_COLS, foldW) : 0;
  const laid = kept.reduce((s, k) => s + k.w, 0) + markerW;
  const residual = span - laid;
  if (foldCount) markerW = Math.max(MIN_FRAME_COLS, markerW + residual);
  else if (kept.length)
    kept[kept.length - 1].w = Math.max(MIN_FRAME_COLS, kept[kept.length - 1].w + residual);

  let cursor = x;
  const limit = x + w;
  for (const k of kept) {
    const width = Math.min(k.w, limit - cursor);
    if (width < 1) break;
    walk(k.node, cursor, width, depth + 1, node.key, out);
    cursor += width;
  }
  if (foldCount && cursor < limit) {
    // Let the marker borrow up to its own label length from the blank
    // self-time gutter to its right, so `⋯ 54` stays readable instead of
    // truncating to a bare ellipsis at the 3-column floor.
    const desired = `⋯ ${foldSamples.toLocaleString()}`.length;
    out.push({
      key: `${node.key}~fold`,
      name: "",
      depth: depth + 1,
      x: cursor,
      w: Math.min(Math.max(markerW, desired), limit - cursor),
      self: foldSamples,
      total: foldSamples,
      parentKey: node.key,
      hasChildren: false,
      fold: true,
      foldCount,
    });
  }
}

// --- ink ------------------------------------------------------------------

// Ink weight is bucketed self-fraction and nothing else: no fills, no hue
// ramp, no gradient. A leaf is 100% self, so accent ink lands exactly on the
// tips of the silhouette — where the CPU time actually is.
function inkClass(self: number, total: number): string {
  const s = total > 0 ? self / total : 0;
  if (s < INK_BUCKETS[0]) return "text-border";
  if (s < INK_BUCKETS[1]) return "text-ns-muted";
  if (s < INK_BUCKETS[2]) return "text-foreground";
  return "text-ns-accent";
}

function fit(name: string, width: number): string {
  if (width <= 0) return "";
  if (name.length <= width) return name;
  if (width === 1) return "…";
  return name.slice(0, width - 1) + "…";
}

function pct(part: number, whole: number): string {
  return `${whole > 0 ? ((part / whole) * 100).toFixed(1) : "0.0"}%`;
}

export function FlamegraphAsciiFrames({
  tree = DEFAULT_TREE,
  rowHeight = 22,
  className = "",
}: FlamegraphAsciiFramesProps) {
  const [zoomPath, setZoomPath] = useState<string[]>(["0"]);
  const [hoverKey, setHoverKey] = useState<string | null>(null);
  const [focusKey, setFocusKey] = useState<string | null>(null);
  /** Which frame Tab lands on — survives blur, unlike `focusKey`. */
  const [tabKey, setTabKey] = useState<string | null>(null);
  const [cols, setCols] = useState(DEFAULT_COLS);

  const wrapRef = useRef<HTMLDivElement>(null);
  const probeRef = useRef<HTMLSpanElement>(null);
  const btnRefs = useRef<Record<string, HTMLButtonElement | null>>({});

  const { root, index } = useMemo(() => {
    const map = new Map<string, RolledNode>();
    return { root: roll(tree, "0", map), index: map };
  }, [tree]);

  // A zoom path whose tail no longer exists (data swapped under us) falls back
  // to the true root rather than rendering nothing.
  const safePath = useMemo(() => {
    const valid = zoomPath.filter((k) => index.has(k));
    return valid.length ? valid : ["0"];
  }, [zoomPath, index]);

  const zoomRoot = index.get(safePath[safePath.length - 1]) ?? root;

  // Column count comes from a ResizeObserver over the graph box divided by one
  // measured monospace advance. No rAF loop, no canvas — this memo is the only
  // recompute, over (tree, zoomPath, cols).
  useEffect(() => {
    const wrap = wrapRef.current;
    const probe = probeRef.current;
    if (!wrap || !probe) return;
    const measure = () => {
      const advance = probe.getBoundingClientRect().width / 40;
      const width = wrap.clientWidth;
      if (!advance || !width) return;
      setCols(Math.max(24, Math.floor(width / advance)));
    };
    measure();
    // The first measure can land on a fallback font; re-measure once the real
    // mono face is in, or every column would be sized off the wrong advance.
    let disposed = false;
    document.fonts?.ready.then(() => {
      if (!disposed) measure();
    });
    const ro = new ResizeObserver(measure);
    ro.observe(wrap);
    return () => {
      disposed = true;
      ro.disconnect();
    };
  }, []);

  const frames = useMemo(() => layoutFrames(zoomRoot, cols), [zoomRoot, cols]);
  const depthCount = frames.reduce((m, f) => Math.max(m, f.depth), 0) + 1;

  const byKey = useMemo(() => {
    const m = new Map<string, Frame>();
    for (const f of frames) m.set(f.key, f);
    return m;
  }, [frames]);

  const activeKey = hoverKey ?? focusKey;

  // The active frame plus its whole ancestor chain keeps full ink; everything
  // else drops to --border.
  const litKeys = useMemo(() => {
    if (!activeKey) return null;
    const lit = new Set<string>();
    let cur: Frame | undefined = byKey.get(activeKey);
    while (cur) {
      lit.add(cur.key);
      cur = cur.parentKey ? byKey.get(cur.parentKey) : undefined;
    }
    return lit;
  }, [activeKey, byKey]);

  const readout = (activeKey && byKey.get(activeKey)) || byKey.get(zoomRoot.key);

  const pathId = safePath.join("/");
  /** Set when a zoom pops the focused frame out of the tree, so focus can land
   * on the new root instead of falling back to <body>. */
  const restoreRootFocus = useRef(false);
  useEffect(() => {
    setFocusKey(null);
    setHoverKey(null);
    setTabKey(null);
    if (restoreRootFocus.current) {
      restoreRootFocus.current = false;
      const rootKey = frames[0]?.key;
      if (rootKey) btnRefs.current[rootKey]?.focus();
    }
    // `frames` is read only to reach the freshly laid root frame for that
    // focus hand-off; re-running on every layout would steal focus.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pathId]);

  const zoomTo = useCallback(
    (key: string) => {
      const node = index.get(key);
      if (!node) return;
      // The key encodes the path from the root ("0.1.0"), so the crumb chain
      // is just its prefixes — no separate parent bookkeeping.
      const parts = key.split(".");
      setZoomPath(parts.map((_, i) => parts.slice(0, i + 1).join(".")));
    },
    [index],
  );

  const focusFrame = useCallback((key: string | undefined) => {
    if (!key) return;
    btnRefs.current[key]?.focus();
  }, []);

  const onKeyDown = (e: KeyboardEvent) => {
    if (e.key === "Escape") {
      if (safePath.length > 1) {
        e.preventDefault();
        restoreRootFocus.current = true;
        setZoomPath(["0"]);
      }
      return;
    }
    // The frame is read off the event target rather than `focusKey`: a zoom
    // clears that state while the DOM node keeps focus, and arrow keys would
    // otherwise go dead until the user tabbed out and back.
    const el = (e.target as HTMLElement | null)?.closest?.("[data-frame-key]");
    const key = el?.getAttribute("data-frame-key");
    const current = key ? byKey.get(key) : undefined;
    if (!current) return;
    if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
      e.preventDefault();
      const row = frames
        .filter((f) => f.depth === current.depth && !f.fold)
        .sort((a, b) => a.x - b.x);
      const i = row.findIndex((f) => f.key === current.key);
      const next = row[i + (e.key === "ArrowRight" ? 1 : -1)];
      focusFrame(next?.key);
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      focusFrame(current.parentKey ?? undefined);
    } else if (e.key === "ArrowDown") {
      e.preventDefault();
      const child = frames
        .filter((f) => f.parentKey === current.key && !f.fold)
        .sort((a, b) => a.x - b.x)[0];
      focusFrame(child?.key);
    }
  };

  const crumbs = safePath.map((k) => index.get(k)!).filter(Boolean);
  const rootTabKey = frames[0]?.key;

  return (
    // Escape / arrow handling sits on the outer wrapper so it also works while
    // focus is on a breadcrumb crumb, not only inside the graph box.
    <div className={`ns-flame font-mono ${className}`} onKeyDown={onKeyDown}>
      <style>{CSS}</style>

      <div
        role="group"
        aria-label="Zoom path"
        className="mb-2 flex min-h-[22px] flex-wrap items-center gap-1 text-[11px]"
      >
        {crumbs.length > 1 &&
          crumbs.map((c, i) => (
            <span key={c.key} className="flex items-center gap-1">
              {i > 0 && (
                <span aria-hidden className="text-border">
                  {"›"}
                </span>
              )}
              <button
                type="button"
                data-flame-crumb={i === 0 ? "root" : c.key}
                onClick={() => setZoomPath(safePath.slice(0, i + 1))}
                aria-current={i === crumbs.length - 1 ? "location" : undefined}
                aria-label={i === 0 ? "Zoom out to the whole graph" : `Zoom to ${c.name}`}
                className={`ns-flame-crumb rounded-sm px-1.5 py-0.5 transition-colors duration-150 motion-reduce:transition-none hover:text-foreground ${
                  i === crumbs.length - 1 ? "text-foreground" : "text-ns-muted"
                }`}
              >
                {i === 0 ? "root" : c.name}
              </button>
            </span>
          ))}
      </div>

      <div
        ref={wrapRef}
        data-flame-graph
        role="group"
        aria-label={`Flame graph of ${zoomRoot.name}, ${zoomRoot.total.toLocaleString()} samples. Arrow keys move between frames, Enter zooms, Escape resets.`}
        onPointerLeave={() => setHoverKey(null)}
        className="relative w-full select-none text-[13px]"
        style={{ height: depthCount * rowHeight }}
      >
        <span
          ref={probeRef}
          aria-hidden
          className="pointer-events-none absolute left-0 top-0 -z-10 opacity-0"
          style={{ whiteSpace: "pre" }}
        >
          {"0".repeat(40)}
        </span>

        {frames.map((f) => {
          const left = `${(f.x / cols) * 100}%`;
          const width = `${(f.w / cols) * 100}%`;
          const dim = litKeys ? !litKeys.has(f.key) : false;

          if (f.fold) {
            // Aggregate marker: it has no self-fraction of its own, so it sits
            // outside the four-bucket encoding at --ns-muted, and is static text
            // rather than a control — there is nothing to zoom into.
            return (
              <span
                key={f.key}
                role="img"
                aria-label={`Depth ${f.depth}, ${f.foldCount} frames too narrow to draw, ${f.total.toLocaleString()} samples combined.`}
                className={`ns-flame-fold absolute overflow-hidden whitespace-pre transition-colors duration-[120ms] motion-reduce:transition-none ${
                  dim ? "text-border" : "text-ns-muted"
                }`}
                style={{ left, width, top: f.depth * rowHeight, lineHeight: `${rowHeight}px` }}
              >
                {(() => {
                  const label = `⋯ ${f.total.toLocaleString()}`;
                  return label.length <= f.w ? label : "⋯";
                })()}
              </span>
            );
          }

          return (
            <button
              key={f.key}
              type="button"
              ref={(el) => {
                btnRefs.current[f.key] = el;
              }}
              data-flame-frame
              data-frame-key={f.key}
              data-frame-depth={f.depth}
              tabIndex={f.key === (tabKey ?? rootTabKey) ? 0 : -1}
              onFocus={() => {
                setFocusKey(f.key);
                setTabKey(f.key);
              }}
              onBlur={() => setFocusKey((k) => (k === f.key ? null : k))}
              onPointerEnter={() => setHoverKey(f.key)}
              onClick={() => zoomTo(f.key)}
              aria-label={`Depth ${f.depth}, ${f.name}, self ${pct(
                f.self,
                zoomRoot.total,
              )}, total ${pct(f.total, zoomRoot.total)}, ${f.total.toLocaleString()} samples${
                f.hasChildren ? ". Press Enter to zoom to this subtree." : "."
              }`}
              className={`ns-flame-frame absolute overflow-hidden whitespace-pre text-left transition-colors duration-[120ms] motion-reduce:transition-none ${
                dim ? "text-border" : inkClass(f.self, f.total)
              }`}
              style={{ left, width, top: f.depth * rowHeight, lineHeight: `${rowHeight}px` }}
            >
              <span aria-hidden>
                {"│"}
                {fit(f.name, f.w - 1)}
              </span>
            </button>
          );
        })}
      </div>

      <div
        data-flame-readout
        className="mt-3 overflow-hidden whitespace-nowrap border-t border-border pt-2 text-[12px] text-ns-muted transition-colors duration-[120ms] motion-reduce:transition-none"
      >
        {readout && (
          <>
            <span className="text-foreground">{readout.fold ? "folded frames" : readout.name}</span>
            <span className="ml-4">self </span>
            <span className="text-foreground">{pct(readout.self, zoomRoot.total)}</span>
            <span className="ml-3">total </span>
            <span className="text-foreground">{pct(readout.total, zoomRoot.total)}</span>
            <span className="ml-3 text-foreground">{readout.total.toLocaleString()}</span>
            <span> samples</span>
          </>
        )}
      </div>
    </div>
  );
}

const CSS = `
.ns-flame-frame:focus-visible { outline: 2px solid var(--ns-accent); outline-offset: -2px; }
.ns-flame-crumb:focus-visible { outline: 2px solid var(--ns-accent); outline-offset: 2px; }
`;

"use client";

import { useEffect, useRef, useState, type CSSProperties } from "react";

// ---------------------------------------------------------------------------
// FlashEntrain — an ambient field of pulse-coupled firefly oscillators
// (Mirollo-Strogatz coupling), not a scripted animation. Every firefly holds
// one phase in a shared Float32Array, climbing linearly from 0 toward a
// firing threshold of 1 at its own natural rate. The instant a firefly
// reaches 1 it fires: its phase resets to 0 and it nudges the phase of each
// of its k=12 STATIC nearest neighbours forward by a fixed coupling strength
// epsilon. A nudged neighbour that itself crosses 1 fires immediately in the
// same tick, cascading — this is the whole mechanism. There is no target
// synchrony state written anywhere; unison, travelling bands and partial-sync
// clusters are all the same cascade rule evaluated on a random initial phase
// field, and they are what makes the field's very long-run arc (twinkle,
// then order, then a local relapse near a deaf firefly, then re-entrainment,
// forever) genuinely emergent rather than authored.
//
// COUPLING STRENGTH is the one governing scalar. epsilon = 0.03 is the
// widest value that still shows travelling bands: above ~0.08 the field
// snaps to full unison in a few seconds and the "order" act eats the whole
// clip; below ~0.02 it never locks within a normal page dwell and only ever
// twinkles. The neighbour graph is k=12 nearest by planar distance, computed
// ONCE at mount and never rebuilt — coupling only ever happens along that
// fixed graph, which is what makes synchrony a spatially local, propagating
// event (a travelling wave, a cluster negotiating a merge) instead of a
// global average snapping over instantly.
//
// DEAF FIREFLIES (2% of the population, a fixed random subset) are the
// honest source of relapse: they never RECEIVE a neighbour's nudge (their
// own phase only ever advances at their own natural rate), they run a
// slightly faster natural period than the rest of the field, and they still
// SEND a pulse to their own neighbours every time they fire. A deaf firefly
// therefore drifts out of whatever local consensus has formed around it and,
// on its own schedule, reaches back in and perturbs its neighbourhood — that
// perturbation is what pulls a locally synced patch apart and restarts local
// entrainment, differently every time, with no scripted reset anywhere.
//
// RENDER SPLIT is the whole performance story: 350 fixed-position DOM dots
// are pre-mounted once at --ns-muted and never move. JS owns exactly one
// number per firefly (phase) and, on a fire event, toggles which of two
// identical-effect CSS classes is present on that one dot — the 200ms
// opacity/scale/color flash envelope itself is a `@keyframes` animation that
// then runs entirely on the compositor. JS never touches opacity, transform
// or color directly; it only ever adds/removes a class name.
//
// ACCESSIBILITY / PHOTOSENSITIVITY: two hard visual caps live in the render
// path, independent of prefers-reduced-motion. (1) A per-firefly refractory
// period of ~910ms after each flash means no single dot can visually flash
// faster than ~1.1Hz, even mid-cascade. (2) A global burst gate: when a
// cascade's eligible-flash count exceeds a small fraction of the field (a
// "unison" event), the WHOLE burst is suppressed unless at least 900ms has
// passed since the last one — phase state still updates normally underneath,
// only the visual flash of that particular burst is skipped, so unison never
// reads as flicker faster than roughly once per 900ms. That is well under
// the three-per-second photosensitivity guideline even without reduced
// motion engaged. With prefers-reduced-motion: reduce, no rAF loop ever
// starts: the field renders once, statically, at its seeded resting phases,
// and one spatial cluster (a BFS walk over the same neighbour graph used for
// coupling) is marked at +10% opacity as the frozen stand-in for a
// synchrony band — the arc is described, not demonstrated, with nothing
// live.
//
// Distinct from loader-pendulum-sync: that component is a small mechanical
// loader whose handful of pendulums converge on an AUTHORED schedule (their
// CSS animation-durations are picked so the row is guaranteed to land back
// in phase every periodMs, by integer-oscillation arithmetic with zero
// per-frame JS) and stay converged once finished. FlashEntrain has no
// schedule and no finish: 350 independent phases pulse-couple over a static
// neighbour graph, synchrony is earned frame by frame, and a handful of deaf
// individuals mean it never stays settled — the story is chaos-to-order-to
// relapse, forever, not converge-and-stop.
// ---------------------------------------------------------------------------

const TICK_MS = 1000 / 30; // fixed 30Hz physics step
const REFRACTORY_MS = 910; // per-firefly visual cooldown -> caps flash rate just under 1.1Hz
const BURST_GAP_MS = 900; // global unison-burst gate
const DOT_MIN_PX = 3;
const DOT_MAX_PX = 5;
const BAND_OPACITY_BOOST = 0.1; // reduced-motion frozen band differential
// Every firefly's own uncoupled cadence stays comfortably below the 1.1Hz
// visual cap: refractory should only ever bind during a coupling-accelerated
// cascade, never as routine background muting of normal ticking.
const MIN_PERIOD_MS = REFRACTORY_MS + 60;
// Concavity of the Mirollo-Strogatz charge/rise function f(phase). This is
// what a naive "phase += epsilon on every nudge" coupling is missing: with a
// LINEAR phase, equal nudges never compress the gap between two out-of-phase
// fireflies, and a headless sweep of that naive version never rose above an
// order parameter of ~0.1 in 90s at any epsilon from 0.02-0.25 — it just
// never locks. With f concave (f(phase)=ln(1+(e^b-1)*phase)/b, b=3 here,
// verified by the same sweep), an equal charge-nudge buys a LARGER phase
// jump for a firefly that is further from firing than for one already close
// to it, which is exactly the absorption mechanism that drives real
// convergence — chaos visibly resolving into partial and then near-full
// synchrony over tens of seconds, continuously reopened by the deaf
// fireflies, at coupling=0.03 exactly as specified.
const CONCAVITY_B = 3;

function mulberry32(seed: number): () => number {
  let a = seed >>> 0 || 1;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const CSS = `
.ns-fe-field{ position:relative; overflow:hidden; }
.ns-fe-dot{
  position:absolute;
  left:0; top:0;
  border-radius:9999px;
  background:var(--ns-muted);
  will-change:opacity,transform;
}
.ns-fe-flash-a, .ns-fe-flash-b{
  animation-duration:200ms;
  animation-timing-function:cubic-bezier(.22,.7,.32,1);
  animation-fill-mode:none;
}
.ns-fe-flash-a{ animation-name:ns-fe-flash-a; }
.ns-fe-flash-b{ animation-name:ns-fe-flash-b; }
@keyframes ns-fe-flash-a{
  0%{ opacity:var(--ns-fe-rest-o); transform:scale(1); background-color:var(--ns-muted); }
  18%{ opacity:1; transform:scale(1.9); background-color:var(--foreground); }
  100%{ opacity:var(--ns-fe-rest-o); transform:scale(1); background-color:var(--ns-muted); }
}
@keyframes ns-fe-flash-b{
  0%{ opacity:var(--ns-fe-rest-o); transform:scale(1); background-color:var(--ns-muted); }
  18%{ opacity:1; transform:scale(1.9); background-color:var(--foreground); }
  100%{ opacity:var(--ns-fe-rest-o); transform:scale(1); background-color:var(--ns-muted); }
}
@media (prefers-reduced-motion: reduce){
  .ns-fe-flash-a, .ns-fe-flash-b{ animation:none; }
}
`;

interface Firefly {
  xFrac: number;
  yFrac: number;
  sizePx: number;
  deaf: boolean;
}

export interface FlashEntrainProps {
  /** Population size. */
  count?: number;
  /** Mirollo-Strogatz coupling strength per firing (governing scalar). Above ~0.08 the field snaps to unison in seconds; below ~0.02 it never locks. */
  coupling?: number;
  /** Static nearest-neighbour graph size per firefly. */
  neighbors?: number;
  /** Fraction of the population that is deaf (never receives coupling), the source of relapse. */
  deafFraction?: number;
  /** Mean natural period, ms, before per-firefly jitter. */
  periodMs?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function FlashEntrain({
  count = 350,
  coupling = 0.03,
  neighbors = 12,
  deafFraction = 0.02,
  periodMs = 1250,
  className = "",
}: FlashEntrainProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const elRefs = useRef<(HTMLDivElement | null)[]>([]);
  const [reduced, setReduced] = useState(false);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = (e: MediaQueryListEvent) => setReduced(e.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  const n = Math.max(24, Math.round(count));
  const k = Math.max(3, Math.min(n - 1, Math.round(neighbors)));

  // -- one seeded field: positions, sizes, deaf flags, neighbour graph -----
  // Deterministic per (n, k, deafFraction) so re-mounts (and the SSR pass)
  // agree with the client without needing to defer render.
  const fieldRef = useRef<{
    fireflies: Firefly[];
    neighborIdx: Int32Array;
    restOpacity: number;
    bandMembers: Uint8Array;
    n: number;
    k: number;
    deafFraction: number;
  } | null>(null);
  if (
    !fieldRef.current ||
    fieldRef.current.n !== n ||
    fieldRef.current.k !== k ||
    fieldRef.current.deafFraction !== deafFraction
  ) {
    const rand = mulberry32(0x5eed0001 ^ n ^ (k << 8));
    const fireflies: Firefly[] = Array.from({ length: n }, () => ({
      xFrac: rand(),
      yFrac: rand(),
      sizePx: DOT_MIN_PX + rand() * (DOT_MAX_PX - DOT_MIN_PX),
      deaf: false,
    }));
    // Floored at 1: the deaf minority is the only source of relapse in this
    // model (see header comment), so deafFraction=0 would silently produce a
    // field that locks into unison and then just sits there forever — a
    // floor of one keeps that story honest even at a tiny population.
    const deafCount = Math.max(1, Math.round(n * deafFraction));
    // pick a random subset deaf, without replacement
    const order = Array.from({ length: n }, (_, i) => i);
    for (let i = order.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      const tmp = order[i]!;
      order[i] = order[j]!;
      order[j] = tmp;
    }
    for (let i = 0; i < deafCount; i++) fireflies[order[i]!]!.deaf = true;

    // k-NN by planar (fractional) distance, brute force — n is small (<=~700
    // in practice), computed once and never rebuilt.
    const neighborIdx = new Int32Array(n * k);
    const candIdx = new Int32Array(k);
    const candD2 = new Float32Array(k);
    for (let i = 0; i < n; i++) {
      let filled = 0;
      let worst = -1;
      let worstD2 = -Infinity;
      const xi = fireflies[i]!.xFrac;
      const yi = fireflies[i]!.yFrac;
      for (let j = 0; j < n; j++) {
        if (j === i) continue;
        const dx = fireflies[j]!.xFrac - xi;
        const dy = fireflies[j]!.yFrac - yi;
        const d2 = dx * dx + dy * dy;
        if (filled < k) {
          candIdx[filled] = j;
          candD2[filled] = d2;
          if (d2 > worstD2) {
            worstD2 = d2;
            worst = filled;
          }
          filled++;
        } else if (d2 < worstD2) {
          candIdx[worst] = j;
          candD2[worst] = d2;
          worstD2 = -Infinity;
          for (let m = 0; m < k; m++) {
            const dm = candD2[m]!;
            if (dm > worstD2) {
              worstD2 = dm;
              worst = m;
            }
          }
        }
      }
      for (let m = 0; m < k; m++) neighborIdx[i * k + m] = candIdx[m] ?? i;
    }

    // Reduced-motion frozen band: BFS over the same neighbour graph from one
    // seeded anchor, collecting ~15% of the population as "already synced".
    const bandMembers = new Uint8Array(n);
    const bandTarget = Math.max(1, Math.round(n * 0.15));
    const anchor = Math.floor(rand() * n);
    const queue: number[] = [anchor];
    bandMembers[anchor] = 1;
    let bandCount = 1;
    let qi = 0;
    while (qi < queue.length && bandCount < bandTarget) {
      const cur = queue[qi++]!;
      for (let m = 0; m < k; m++) {
        const nb = neighborIdx[cur * k + m]!;
        if (bandMembers[nb]) continue;
        bandMembers[nb] = 1;
        bandCount++;
        queue.push(nb);
        if (bandCount >= bandTarget) break;
      }
    }

    fieldRef.current = {
      fireflies,
      neighborIdx,
      restOpacity: 0.55,
      bandMembers,
      n,
      k,
      deafFraction,
    };
  }
  const field = fieldRef.current;

  useEffect(() => {
    if (reduced) return; // static frame only, no loop, no listeners
    const root = rootRef.current;
    if (!root) return;

    const { fireflies, neighborIdx } = field;

    const phase = new Float32Array(n);
    const rate = new Float32Array(n); // phase units per ms
    const isDeaf = new Uint8Array(n);
    // Float64, not Float32: holds performance.now()-scale timestamps, which
    // lose the millisecond precision the refractory comparison needs once a
    // long-lived tab's clock runs past ~4.6 hours in a Float32.
    const nextFlashOkAt = new Float64Array(n);
    const flip = new Uint8Array(n); // alternates which flash class to use
    const firedThisTick = new Uint8Array(n);

    const rand = mulberry32(0x5eed0002 ^ n);
    for (let i = 0; i < n; i++) {
      const ff = fireflies[i]!;
      isDeaf[i] = ff.deaf ? 1 : 0;
      phase[i] = rand(); // start scattered, not synced
      const jitter = 0.85 + rand() * 0.3; // +-15% natural-period spread
      // deaf fireflies run ~14% faster; MIN_PERIOD_MS floors every period
      // (deaf or not) above the refractory so ordinary ticking never trips
      // the visual rate cap on its own — only a coupling cascade does.
      const period = Math.max(
        MIN_PERIOD_MS,
        ff.deaf ? periodMs * jitter * 0.86 : periodMs * jitter
      );
      rate[i] = TICK_MS / period;
    }

    const eps = coupling;
    const eb = Math.exp(CONCAVITY_B);
    // phase -> charge (concave) and charge -> phase (its inverse). A firing
    // pulse nudges a neighbour's CHARGE by epsilon, then the neighbour's
    // phase is recovered from that new charge — see CONCAVITY_B above.
    const toCharge = (p: number) => Math.log(1 + (eb - 1) * p) / CONCAVITY_B;
    const toPhase = (x: number) => (Math.exp(CONCAVITY_B * x) - 1) / (eb - 1);
    const fireQueue: number[] = [];
    const eligible: number[] = [];
    let lastBurstAt = -Infinity;
    const burstThreshold = Math.max(6, Math.round(n * 0.06));

    const applyFlash = (i: number, nowMs: number) => {
      nextFlashOkAt[i] = nowMs + REFRACTORY_MS;
      const el = elRefs.current[i];
      if (!el) return;
      el.classList.remove("ns-fe-flash-a", "ns-fe-flash-b");
      // Alternating between two classes with distinct animation-name values
      // (not the same class re-added) is what forces the keyframe to
      // restart: re-adding an identical animation-name is a no-op per spec
      // even after the previous run finished, no reflow trick needed.
      el.classList.add(flip[i] ? "ns-fe-flash-b" : "ns-fe-flash-a");
      flip[i] = flip[i] ? 0 : 1;
    };

    const tick = (nowMs: number) => {
      for (let i = 0; i < n; i++) phase[i] += rate[i]!;

      firedThisTick.fill(0);
      fireQueue.length = 0;
      eligible.length = 0;
      for (let i = 0; i < n; i++) {
        if (phase[i]! >= 1 && !firedThisTick[i]) {
          firedThisTick[i] = 1;
          fireQueue.push(i);
        }
      }

      let qi = 0;
      while (qi < fireQueue.length) {
        const i = fireQueue[qi++]!;
        phase[i] = 0;
        if (nowMs >= nextFlashOkAt[i]!) eligible.push(i);

        const base = i * k;
        for (let m = 0; m < k; m++) {
          const j = neighborIdx[base + m]!;
          if (isDeaf[j]) continue; // deaf: never receives coupling
          // Mirollo-Strogatz coupling proper: nudge the neighbour's CHARGE
          // (the concave transform of its phase) by epsilon, not its phase
          // directly — see CONCAVITY_B above for why that distinction is
          // what makes convergence actually happen.
          const chargeJ = toCharge(Math.min(1, phase[j]!)) + eps;
          if (chargeJ >= 1) {
            if (!firedThisTick[j]) {
              firedThisTick[j] = 1;
              fireQueue.push(j); // popped next: reset to 0, coupled onward
            }
          } else {
            phase[j] = toPhase(chargeJ);
          }
        }
      }

      if (eligible.length === 0) return;
      if (eligible.length > burstThreshold) {
        if (nowMs - lastBurstAt < BURST_GAP_MS) return; // gated: physics ran, visuals held back
        lastBurstAt = nowMs;
      }
      for (let e = 0; e < eligible.length; e++) applyFlash(eligible[e]!, nowMs);
    };

    let raf = 0;
    let lastFrame = 0;
    let acc = 0;

    const loop = (now: number) => {
      const dt = lastFrame ? Math.min(200, now - lastFrame) : TICK_MS;
      lastFrame = now;
      acc += dt;
      while (acc >= TICK_MS) {
        tick(now);
        acc -= TICK_MS;
      }
      raf = requestAnimationFrame(loop);
    };

    const onVisibility = () => {
      if (document.hidden) {
        if (raf) cancelAnimationFrame(raf);
        raf = 0;
      } else if (!raf) {
        lastFrame = 0;
        acc = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    raf = requestAnimationFrame(loop);
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      if (raf) cancelAnimationFrame(raf);
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, [reduced, n, k, coupling, periodMs, field]);

  return (
    <div ref={rootRef} className={`ns-fe-field block h-full w-full ${className}`}>
      <style>{CSS}</style>
      <div aria-hidden="true" className="pointer-events-none absolute inset-0">
        {field.fireflies.map((ff, i) => {
          const bandOpacity = reduced && field.bandMembers[i]
            ? field.restOpacity + BAND_OPACITY_BOOST
            : field.restOpacity;
          return (
            <div
              key={i}
              ref={(el) => {
                elRefs.current[i] = el;
              }}
              className="ns-fe-dot"
              style={{
                left: `${ff.xFrac * 100}%`,
                top: `${ff.yFrac * 100}%`,
                width: ff.sizePx,
                height: ff.sizePx,
                marginLeft: -ff.sizePx / 2,
                marginTop: -ff.sizePx / 2,
                opacity: bandOpacity,
                "--ns-fe-rest-o": field.restOpacity,
              } as CSSProperties}
            />
          );
        })}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// FloatRibbonDraw — a multi-stage pipeline/job-status bar modeled on the
// float-glass process (the Pilkington process, the method that produces
// essentially all flat glass made today): molten glass flows continuously
// onto a bath of molten tin, floats and spreads to its natural equilibrium
// thickness, and is drawn forward by top rollers at a constant line speed
// while it cools along the bath's length, entering molten (~1,000C) and
// exiting set (~600C). That process has no start/stop within a run — it is
// a single continuous draw — which is exactly the shape most "job status"
// widgets get wrong by pausing their idle animation while "waiting."
//
// TWO SEPARATE THINGS, deliberately not conflated:
//  - The THERMAL GRADIENT (bright/dense "molten" -> dim "set", left to
//    right) is a FIXED function of position along the bar. It represents
//    the pipeline's stages, and never itself animates — pausing it would
//    misrepresent a process stage as somehow reversible.
//  - The RIPPLE (a faint sine wobble riding the top edge, confined to the
//    still-molten first third and damped out by where the gradient has
//    mostly set) is what SCROLLS continuously at a constant rate. It is the
//    "alive at rest" signal: material is actively moving through the
//    pipeline right now, regardless of which stage is highlighted.
//
// Colour is luminance-only: every fill is a lerp between --ns-muted (t=0,
// "set") and --foreground (t=1, "molten") — never a literal orange/red heat
// colour. That mapping holds in both themes because --foreground is already
// the theme's highest-density ink (near-white in dark, near-black in
// light), so "hot" reads as "densest" in both, not as a hue.
//
// Optional `stages`/`activeStage` overlay fixed pipeline-stage tick marks
// (queued/processing/done, etc.) at even x-fractions along the bar — the
// ribbon's own gradient/ripple keeps running unconditionally underneath
// regardless of which stage is active, per the real process never stopping
// mid-draw.
// ---------------------------------------------------------------------------

type Vec3 = [number, number, number];

// Same parse+lerp idiom used elsewhere in this registry (house convention,
// duplicated per component rather than shared).
function parseColor(raw: string): Vec3 | null {
  const s = raw.trim();
  if (s.startsWith("#")) {
    const hex = s.slice(1);
    if (hex.length === 3) {
      const r = parseInt(hex[0]! + hex[0], 16);
      const g = parseInt(hex[1]! + hex[1], 16);
      const b = parseInt(hex[2]! + hex[2], 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    if (hex.length >= 6) {
      const r = parseInt(hex.slice(0, 2), 16);
      const g = parseInt(hex.slice(2, 4), 16);
      const b = parseInt(hex.slice(4, 6), 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    return null;
  }
  const m = s.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
}

function lerpColor(a: Vec3, b: Vec3, t: number): Vec3 {
  const c = Math.min(1, Math.max(0, t));
  return [
    Math.round(a[0] + (b[0] - a[0]) * c),
    Math.round(a[1] + (b[1] - a[1]) * c),
    Math.round(a[2] + (b[2] - a[2]) * c),
  ];
}

function rgbStr(v: Vec3, alpha = 1): string {
  return alpha >= 1 ? `rgb(${v[0]},${v[1]},${v[2]})` : `rgba(${v[0]},${v[1]},${v[2]},${alpha})`;
}

const SAMPLES = 64; // 1D luminance/ripple lookup across the ribbon's length
const LAMBDA = 0.35; // exp decay constant, in ribbon-lengths — how fast "hot" gives way to "set"
const T_FLOOR = 0.08; // luminance never fully bottoms out to pure --ns-muted
const RIBBON_FRAC = 0.28; // ribbon band height as a fraction of container height
const SCROLL_FRAC_PER_S = 0.08; // ripple scroll speed, fraction of container width per second
const RIPPLE_WAVELEN_FRAC = 0.18; // ripple wavelength, fraction of container width
const RIPPLE_AMP_FRAC = 0.09; // ripple amplitude, fraction of ribbon height
const MOLTEN_ZONE = 0.34; // ripple envelope is ~0 past this fraction along the ribbon

function luminanceAt(xFrac: number): number {
  return T_FLOOR + (1 - T_FLOOR) * Math.exp(-xFrac / LAMBDA);
}

// ripple envelope: full amplitude near the molten (left) edge, damped to 0
// by MOLTEN_ZONE — a raised-cosine falloff, not a hard cutoff.
function rippleEnvelope(xFrac: number): number {
  if (xFrac >= MOLTEN_ZONE) return 0;
  const t = xFrac / MOLTEN_ZONE;
  return 0.5 * (1 + Math.cos(t * Math.PI));
}

export interface FloatRibbonDrawProps {
  /** total component height in px; the ribbon band derives as 28% of this. Default 88. */
  height?: number;
  /** optional ordered pipeline stage labels, drawn as fixed ticks along the bar */
  stages?: string[];
  /** index into `stages` that is currently active/lit. Omit for a purely ambient ribbon with no stage semantics. */
  activeStage?: number;
  /** accessible label for the status region. Default "Processing pipeline" */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function FloatRibbonDraw({
  height = 88,
  stages,
  activeStage,
  label = "Processing pipeline",
  className = "",
}: FloatRibbonDrawProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [announce, setAnnounce] = useState("");
  const lastAnnouncedRef = useRef<number | undefined>(undefined);

  useEffect(() => {
    if (!stages || activeStage === undefined) return;
    if (lastAnnouncedRef.current === activeStage) return;
    lastAnnouncedRef.current = activeStage;
    const s = stages[activeStage];
    if (s) setAnnounce(`Stage: ${s}`);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeStage, stages?.join("|")]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let muted: Vec3 = [128, 128, 128];
    let fg: Vec3 = [0, 0, 0];
    let border: Vec3 = [128, 128, 128];
    let borderAlpha = 1;

    const readTokens = () => {
      const root = getComputedStyle(document.documentElement);
      muted = parseColor(root.getPropertyValue("--ns-muted")) ?? muted;
      fg = parseColor(root.getPropertyValue("--foreground")) ?? fg;
      border = parseColor(root.getPropertyValue("--border")) ?? border;
      // --border ships at low alpha via its own token in some themes; if the
      // computed value carries no alpha channel, keep full opacity and let
      // the token's own colour do the (deliberately faint) work.
      const m = root.getPropertyValue("--border").match(/rgba?\([^)]*,\s*([\d.]+)\s*\)/);
      borderAlpha = m ? Number(m[1]) : 1;
    };

    let width = 0;
    let sized = false;
    let ribbonH = 0;

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      if (rect.width < 2 || rect.height < 2) {
        sized = false;
        return;
      }
      width = rect.width;
      ribbonH = Math.max(4, height * RIBBON_FRAC);
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(rect.width * dpr));
      canvas.height = Math.max(1, Math.round(rect.height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      sized = true;
    };

    // scrollPx: how far the ripple texture has travelled, in css px. Never
    // resets — the draw is a single continuous run.
    let scrollPx = 0;

    const draw = () => {
      if (!sized) return;
      const rect = canvas.getBoundingClientRect();
      const h = rect.height;
      const top = (h - ribbonH) / 2;
      ctx.clearRect(0, 0, rect.width, h);

      // 1D sample lookup across the ribbon's length: luminance (fixed, a
      // function of x only) and ripple y-offset (a function of x and the
      // scroll phase), bilinearly interpolated between the SAMPLES points.
      const lum = new Float32Array(SAMPLES);
      const rip = new Float32Array(SAMPLES);
      const wavelenPx = Math.max(1, width * RIPPLE_WAVELEN_FRAC);
      const ampPx = ribbonH * RIPPLE_AMP_FRAC;
      for (let i = 0; i < SAMPLES; i++) {
        const xFrac = i / (SAMPLES - 1);
        lum[i] = luminanceAt(xFrac);
        const env = rippleEnvelope(xFrac);
        const xPx = xFrac * width;
        rip[i] = env * ampPx * Math.sin(((xPx + scrollPx) / wavelenPx) * Math.PI * 2);
      }

      const sampleAt = (arr: Float32Array, xFrac: number): number => {
        const pos = Math.min(SAMPLES - 1, Math.max(0, xFrac * (SAMPLES - 1)));
        const i0 = Math.floor(pos);
        const i1 = Math.min(SAMPLES - 1, i0 + 1);
        const f = pos - i0;
        const a = arr[i0] ?? 0;
        const b = arr[i1] ?? 0;
        return a + (b - a) * f;
      };

      // gradient fill along the ribbon's length, stopped at 12 points from
      // the pre-sampled luminance curve (the curve is exponential, not
      // linear, so a 2-stop canvas gradient would misrepresent it).
      const grad = ctx.createLinearGradient(0, 0, width, 0);
      const STOPS = 12;
      for (let s = 0; s <= STOPS; s++) {
        const xFrac = s / STOPS;
        const t = sampleAt(lum, xFrac);
        grad.addColorStop(xFrac, rgbStr(lerpColor(muted, fg, t)));
      }

      ctx.beginPath();
      ctx.moveTo(0, top + sampleAt(rip, 0));
      const STEP = 2; // px, top-edge ripple polyline resolution
      for (let x = 0; x <= width; x += STEP) {
        const xFrac = x / width;
        ctx.lineTo(x, top + sampleAt(rip, xFrac));
      }
      ctx.lineTo(width, top + ribbonH);
      ctx.lineTo(0, top + ribbonH);
      ctx.closePath();
      ctx.fillStyle = grad;
      ctx.fill();

      // a thin --border rule under the full ribbon length, keeping the
      // "set" (right, low-luminance) end from disappearing into --surface
      // in light theme.
      ctx.beginPath();
      ctx.moveTo(0, top + ribbonH + 0.5);
      ctx.lineTo(width, top + ribbonH + 0.5);
      ctx.lineWidth = 1;
      ctx.strokeStyle = rgbStr(border, borderAlpha);
      ctx.stroke();

      // fixed pipeline-stage ticks, if provided — luminance only, never
      // accent, drawn on top of the ribbon at even x-fractions.
      if (stages && stages.length > 0) {
        for (let i = 0; i < stages.length; i++) {
          const xFrac = stages.length > 1 ? i / (stages.length - 1) : 0.5;
          const x = xFrac * width;
          const active = activeStage === i;
          ctx.fillStyle = rgbStr(active ? fg : muted, active ? 0.9 : 0.55);
          const tickH = active ? ribbonH * 0.55 : ribbonH * 0.35;
          ctx.fillRect(Math.round(x - 0.5), top + (ribbonH - tickH) / 2, 1, tickH);
        }
      }
    };

    let raf = 0;
    let last = 0;
    let visible = true;

    const loop = (now: number) => {
      if (!visible || document.hidden) {
        raf = 0;
        return;
      }
      const dtMs = last ? Math.min(250, now - last) : 1000 / 60;
      last = now;
      scrollPx += width * SCROLL_FRAC_PER_S * (dtMs / 1000);
      draw();
      raf = requestAnimationFrame(loop);
    };

    const start = () => {
      if (raf || reduced) return;
      last = 0;
      raf = requestAnimationFrame(loop);
    };
    const stop = () => {
      cancelAnimationFrame(raf);
      raf = 0;
    };

    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) draw();
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        readTokens();
        resize();
        draw();
      }, 120);
    };
    const ro = new ResizeObserver(onResize);
    ro.observe(canvas);

    const io = new IntersectionObserver(
      (entries) => {
        visible = entries[0]?.isIntersecting ?? true;
        if (visible) start();
        else stop();
      },
      { threshold: 0 }
    );
    io.observe(canvas);

    const onVis = () => {
      if (document.hidden) stop();
      else if (visible) start();
    };
    document.addEventListener("visibilitychange", onVis);

    // no paint before the first token read
    readTokens();
    resize();

    if (reduced) {
      // freeze at scroll-phase 0 — the ripple's most evenly-spread crest
      // layout across the molten zone, not an arbitrary mid-scroll moment.
      scrollPx = 0;
      draw();
    } else {
      draw();
      start();
    }

    return () => {
      stop();
      if (resizeTimer) clearTimeout(resizeTimer);
      mo.disconnect();
      ro.disconnect();
      io.disconnect();
      document.removeEventListener("visibilitychange", onVis);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [height, stages?.join("|"), activeStage]);

  return (
    <div role="group" aria-label={label} className={`relative w-full ${className}`} style={{ height }}>
      <canvas ref={canvasRef} aria-hidden="true" className="block h-full w-full" />
      {stages && stages.length > 0 && (
        <div
          aria-hidden="true"
          className="pointer-events-none absolute bottom-1 left-0 flex w-full justify-between px-0.5"
        >
          {stages.map((s, i) => (
            <span
              key={s}
              className="font-mono text-[9px] uppercase tracking-[0.1em]"
              style={{ color: activeStage === i ? "var(--foreground)" : "var(--ns-muted)" }}
            >
              {s}
            </span>
          ))}
        </div>
      )}
      <p role="status" aria-live="polite" className="sr-only">
        {announce}
      </p>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";

// ---------------------------------------------------------------------------
// FloretPack — a full-bleed phyllotactic background that is genuinely GROWN,
// not evaluated. A meristem at the container's centre births one primordium
// per plastochron at theta = orderIndex * 137.50776deg (the golden angle,
// sequential, mod 360 — never batch-computed). Each floret's radial motion
// is the exact analytic solution of dr/dt = K/r (area-conserving outward
// advection) taken from its own age, and on top of that a local repulsion
// pass every 30Hz tick nudges it against its birth-order neighbours, capped
// at 0.3px/tick, and that nudge is never pulled back to a target lattice —
// it is a permanent record of packing history. It is THIS relaxation, not
// the golden angle itself, that turns a field of jittered newborns into the
// visible 34/55 parastichy spirals a few rows out; switch it off and every
// floret just advects along its own fixed noisy ray with nothing to
// reorganise it, so the spirals visibly smear — the falsifiable tell that
// this is grown, not sampled from the closed-form Vogel layout r=c*sqrt(n).
//
// Every floret is one pre-mounted, absolutely-positioned div, pooled at a
// fixed size (maxPrimordia) and updated only via style.transform / opacity /
// backgroundColor from a direct-DOM rAF loop — no React state on the hot
// path, no canvas, no WebGL. A slot's index is literally birth order modulo
// the pool size, so the pool recycles itself exactly when a primordium
// reaches the rim (its radial lifetime is tuned to equal maxPrimordia
// plastochrons), with no separate free-list bookkeeping.
//
// Distinct from background-lloyd-relax: Lloyd relaxation converges toward a
// centroidal equilibrium and would sit still if the density field ever held
// still — it has no source and no sink. FloretPack has a permanent source
// (the meristem, always emitting) and a permanent sink (the rim, always
// consuming), a steady-state growth flow, and its local order comes from
// divergence-angle arrival history, never a centroidal correction.
// ---------------------------------------------------------------------------

const GOLDEN_ANGLE_RAD = (137.50776405003785 * Math.PI) / 180;
const TICK_MS = 1000 / 30; // fixed 30Hz physics step
const R0 = 3; // meristem birth radius, px
const NEIGHBOR_WINDOW = 10; // +-N birth-order slots searched for spatial neighbours
const NEIGHBOR_COUNT = 4; // 4-neighbour soft repulsion
const DESIRED_SPACING = 4; // px — the repulsion pass's target inter-floret spacing
const REPEL_STRENGTH = 0.9;
const MAX_STEP_PX = 0.3; // capped displacement per 30Hz tick
const RIM_FADE_START = 0.85; // senescence band: last 15% of the radial lifetime
const BIRTH_FADE_FRAC = 0.06; // opacity/scale ramp-in over the first 6% of lifetime
const DOT_SIZE = 10; // px, fully-grown dot diameter — sized against the ~27px mean spacing an inscribed rim gives, so the parastichy families read as lines rather than as scattered specks
const DOT_MIN_SCALE = 0.35;
const WARMUP_PLASTOCHRONS = 500;
const JITTER_MAX_PX = 2.2;

// --- MOTION VARIANT (switchable, ship value at the bottom) -----------------
// Three passes of tuning the existing radial-advection smoothness each still
// read as "movement is bad" — the field was moving correctly but too slowly
// to perceive (measured ~0.4px/s at r=100 with the pre-existing defaults) and
// only ever moved in one register (outward). These are three DIFFERENT
// motion treatments, not three more tunings of the same one:
//   "drift" — the component's existing analytic radial outflow on its own,
//             for comparison/debugging — individual florets stream from
//             meristem to rim, nothing else moves.
//   "spin"  — the shipped default: "drift" PLUS the whole resolved field
//             rotating as one rigid frame (a fixed deg/s added uniformly to
//             every floret's render angle, applied at the theta->x/y
//             resolution step, so it rides on top of the unchanged radial
//             advection and birth-order relaxation rather than replacing
//             either). The 34/55 spiral families visibly turn as a unit
//             WHILE still streaming outward at the same speed as "drift" —
//             this is the "rotating growth" the owner asked for, not a
//             separate spinning-graphic mode.
//   "pulse" — "drift", plus a slow sinusoidal multiplier on every floret's
//             resolved radius, so the whole head rhythmically breathes
//             in/out rather than only advecting one direction.
// All three still run the same emission clock, golden-angle placement and
// birth-order repulsion — only how the resolved (theta, r) maps to (x, y)
// changes, so packing/relaxation history is identical across variants.
const MOTION: "drift" | "spin" | "pulse" = "spin";
// deg/s the whole head rotates in "spin". Chosen so a floret's own radial
// lifetime (how long it takes one primordium to travel meristem -> rim)
// completes well under one full head rotation: at the demo's ~25s lifetime,
// 6deg/s is a 150deg turn per floret generation — enough that the spiral
// families visibly precess between frames a few seconds apart, not enough
// that any single rotation reads as a spinning logo. At the documented
// production defaults (plastochron 1400ms/maxPrimordia 700, ~980s lifetime)
// the same 6deg/s reads as calm long-run drift of the whole pattern, never a
// pinwheel.
const SPIN_DEG_PER_S = 6;
const PULSE_AMPL = 0.06; // "pulse" only — +/- fraction of resolved radius
const PULSE_PERIOD_S = 3.2; // "pulse" only — one breathe in + out

function mulberry32(seed: number): () => number {
  let a = seed >>> 0 || 1;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

interface RGB {
  r: number;
  g: number;
  b: number;
}

function parseHex(raw: string): RGB | null {
  const m = /^#?([0-9a-f]{6})$/i.exec(raw.trim());
  if (!m || !m[1]) return null;
  const int = parseInt(m[1], 16);
  return { r: (int >> 16) & 255, g: (int >> 8) & 255, b: int & 255 };
}

function lerpChannel(a: number, b: number, t: number): number {
  return Math.round(a + (b - a) * t);
}

// Three token stops from --ns-muted (young) toward --foreground (mature),
// read live so a theme flip re-derives them without a remount.
function readStops(): string[] {
  const cs = getComputedStyle(document.documentElement);
  const muted = parseHex(cs.getPropertyValue("--ns-muted")) ?? { r: 143, g: 143, b: 143 };
  const fg = parseHex(cs.getPropertyValue("--foreground")) ?? { r: 237, g: 237, b: 237 };
  return [0, 0.5, 1].map(
    (t) => `rgb(${lerpChannel(muted.r, fg.r, t)},${lerpChannel(muted.g, fg.g, t)},${lerpChannel(muted.b, fg.b, t)})`
  );
}

export interface FloretPackProps {
  /** Content overlaid on a bg-background/70 scrim above the growing head. */
  children?: ReactNode;
  /** Plastochron — ms between successive primordium emissions. ~1.4s reads as organic; faster reads as popcorn, slower as frozen. */
  plastochron?: number;
  /** Live primordia population cap — also the pool size and, by construction, the radial lifetime in plastochrons. */
  maxPrimordia?: number;
  className?: string;
}

export function FloretPack({ children, plastochron = 1400, maxPrimordia = 700, className = "" }: FloretPackProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const elRefs = useRef<(HTMLDivElement | null)[]>([]);
  const [reduced, setReduced] = useState(false);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = (e: MediaQueryListEvent) => setReduced(e.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;

    const n = maxPrimordia;
    const theta = new Float32Array(n);
    const bornAt = new Float32Array(n); // ms, sim clock
    const bornOrder = new Int32Array(n).fill(-1);
    const ox = new Float32Array(n);
    const oy = new Float32Array(n);
    const posX = new Float32Array(n);
    const posY = new Float32Array(n);
    // Render-interpolation buffers: the physics tick is fixed at 30Hz
    // (TICK_MS) but rAF fires at display rate (60/120Hz). Without these, the
    // last tick's posX/posY got re-applied verbatim to the DOM on every
    // in-between frame, so a tracked dot's per-frame render delta alternated
    // "0px for 1-2 frames, then a multi-px jump" — a beat between the 30Hz
    // physics step and the display's refresh rate, not smooth advection.
    // prevPosX/Y hold the position as of the second-most-recent tick;
    // applyToDOM lerps toward the latest tick by the leftover accumulator
    // fraction every frame, so the rendered position moves a little every
    // single frame instead of only on tick boundaries.
    const prevPosX = new Float32Array(n);
    const prevPosY = new Float32Array(n);
    const prevBornOrder = new Int32Array(n).fill(-1);
    const maturity = new Float32Array(n);
    const dx = new Float32Array(n);
    const dy = new Float32Array(n);
    const lastColorIdx = new Int8Array(n).fill(-1);
    const candD2: number[] = new Array(NEIGHBOR_WINDOW * 2);
    const candDx: number[] = new Array(NEIGHBOR_WINDOW * 2);
    const candDy: number[] = new Array(NEIGHBOR_WINDOW * 2);
    const rand = mulberry32(0x9e3779b9);

    let stops = readStops();
    let w = 0;
    let h = 0;
    let cx = 0;
    let cy = 0;
    let rRim = 100;
    let growthK = 1;
    let lifetimeMs = maxPrimordia * plastochron;
    let simAge = 0;
    let nextEmitAt = 0;
    let emitOrder = 0;
    let started = false;
    let raf = 0;
    let lastT = 0;
    let acc = 0;

    const measure = () => {
      const rect = root!.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      cx = w / 2;
      cy = h / 2;
      // The rim is the INSCRIBED circle, not the half-diagonal. Advection is
      // area-conserving, so a head whose rim is the half-diagonal spreads the
      // same maxPrimordia florets over ~1.7x the area AND pushes the rim off
      // screen entirely: the result is a uniform full-bleed scatter with no
      // visible head, no rim, and parastichy families too sparse to read as
      // spirals at all. Inscribing the head puts the whole flower in frame.
      rRim = Math.min(cx, cy) * 0.92;
    };

    const spawn = (order: number, atMs: number) => {
      const slot = order % n;
      // modulo 2*PI keeps the stored angle small (single-precision friendly)
      // over very long mount times without changing the golden-angle rule.
      theta[slot] = (order * GOLDEN_ANGLE_RAD) % (Math.PI * 2);
      bornAt[slot] = atMs;
      bornOrder[slot] = order;
      const jAng = rand() * Math.PI * 2;
      const jMag = rand() * JITTER_MAX_PX;
      ox[slot] = Math.cos(jAng) * jMag;
      oy[slot] = Math.sin(jAng) * jMag;
      lastColorIdx[slot] = -1;
    };

    // Resolves the analytic radial position (age -> r -> Cartesian, plus the
    // persisted relaxation offset) for every live floret against the
    // CURRENT cx/cy/growthK. Reused after a resize (reproject in place, no
    // physics advance) and as the first pass of stepPhysics.
    const computePositions = () => {
      // Rigid rotation and radial breathing are applied here, at the
      // theta/r -> x/y resolution step, so they ride on top of the
      // unchanged analytic advection and repulsion history rather than
      // replacing either — see the MOTION comment above.
      const spinRad = MOTION === "spin" ? ((simAge / 1000) * SPIN_DEG_PER_S * Math.PI) / 180 : 0;
      const pulseMult =
        MOTION === "pulse" ? 1 + PULSE_AMPL * Math.sin(((simAge / 1000 / PULSE_PERIOD_S) * Math.PI) * 2) : 1;
      for (let slot = 0; slot < n; slot++) {
        if (bornOrder[slot] < 0) continue;
        const age = Math.max(0, simAge - (bornAt[slot] ?? 0));
        const m = Math.min(1, age / lifetimeMs);
        maturity[slot] = m;
        // Continuous, not quantised: rounding this to a 4px grid (the old
        // behaviour) reads as fine-grained packing structure once you're
        // comparing sampled positions, but every floret's radius crosses a
        // 4px boundary at a different moment and pops there instantly — with
        // the accumulator fix elsewhere in this file actually running
        // physics at its intended ~30Hz (it previously fired only a handful
        // of times in 3s, which buried this), those pops became frequent
        // enough to read as the whole field stuttering rather than smooth
        // outward advection. The repulsion pass below still enforces
        // DESIRED_SPACING in continuous space, so the parastichy packing is
        // unaffected — only the render position stops jumping.
        const rBase = Math.sqrt(R0 * R0 + 2 * growthK * age) * pulseMult;
        const t = (theta[slot] ?? 0) + spinRad;
        posX[slot] = cx + rBase * Math.cos(t) + (ox[slot] ?? 0);
        posY[slot] = cy + rBase * Math.sin(t) + (oy[slot] ?? 0);
      }
    };

    // Advances the sim clock, spawns due primordia, resolves the analytic
    // radial position for every live floret, then runs one pass of capped
    // 4-neighbour soft repulsion on top. Pure physics — no DOM writes.
    const stepPhysics = (dtMs: number, capScale: number) => {
      simAge += dtMs;
      while (simAge >= nextEmitAt) {
        spawn(emitOrder, nextEmitAt);
        emitOrder++;
        nextEmitAt += plastochron;
      }

      computePositions();

      const cap = MAX_STEP_PX * capScale;
      for (let i = 0; i < n; i++) {
        if (bornOrder[i] < 0) {
          dx[i] = 0;
          dy[i] = 0;
          continue;
        }
        let count = 0;
        for (let off = -NEIGHBOR_WINDOW; off <= NEIGHBOR_WINDOW; off++) {
          if (off === 0) continue;
          const j = ((i + off) % n + n) % n;
          if (bornOrder[j] < 0) continue;
          const ddx = (posX[i] ?? 0) - (posX[j] ?? 0);
          const ddy = (posY[i] ?? 0) - (posY[j] ?? 0);
          candD2[count] = ddx * ddx + ddy * ddy;
          candDx[count] = ddx;
          candDy[count] = ddy;
          count++;
        }
        // partial selection: the NEIGHBOR_COUNT closest candidates by d2
        let fx = 0;
        let fy = 0;
        for (let pick = 0; pick < NEIGHBOR_COUNT && pick < count; pick++) {
          let bestIdx = -1;
          let bestD2 = Infinity;
          for (let c = 0; c < count; c++) {
            const d2 = candD2[c] ?? Infinity;
            if (d2 < bestD2) {
              bestD2 = d2;
              bestIdx = c;
            }
          }
          if (bestIdx < 0) break;
          candD2[bestIdx] = Infinity; // consumed
          if (bestD2 < DESIRED_SPACING * DESIRED_SPACING) {
            const dist = Math.sqrt(bestD2) || 0.01;
            const overlap = (DESIRED_SPACING - dist) / DESIRED_SPACING;
            const mag = overlap * REPEL_STRENGTH;
            fx += ((candDx[bestIdx] ?? 0) / dist) * mag;
            fy += ((candDy[bestIdx] ?? 0) / dist) * mag;
          }
        }
        const fMag = Math.hypot(fx, fy);
        if (fMag > cap) {
          const s = cap / fMag;
          fx *= s;
          fy *= s;
        }
        dx[i] = fx;
        dy[i] = fy;
      }

      for (let slot = 0; slot < n; slot++) {
        if (bornOrder[slot] < 0) continue;
        ox[slot] = (ox[slot] ?? 0) + (dx[slot] ?? 0);
        oy[slot] = (oy[slot] ?? 0) + (dy[slot] ?? 0);
        posX[slot] = (posX[slot] ?? 0) + (dx[slot] ?? 0);
        posY[slot] = (posY[slot] ?? 0) + (dy[slot] ?? 0);
      }
    };

    // `alpha` is the fraction of the way from the previous completed tick to
    // the latest one (0 right after a tick, approaching 1 just before the
    // next). alpha=1 means "render the latest tick's position outright" —
    // used by warmup and resize reprojection, which aren't running inside
    // the interpolated rAF loop.
    const applyToDOM = (alpha = 1) => {
      for (let slot = 0; slot < n; slot++) {
        const el = elRefs.current[slot];
        if (!el) continue;
        if (bornOrder[slot] < 0) {
          el.style.opacity = "0";
          continue;
        }
        const curX = posX[slot] ?? 0;
        const curY = posY[slot] ?? 0;
        let rx = curX;
        let ry = curY;
        // Only interpolate a floret that already existed at the previous
        // tick under this same slot — a just-spawned or just-recycled slot
        // has no meaningful "previous" position and must snap, not lerp in
        // from stale/garbage coordinates.
        if (alpha < 1 && prevBornOrder[slot] === bornOrder[slot]) {
          const px = prevPosX[slot] ?? curX;
          const py = prevPosY[slot] ?? curY;
          rx = px + (curX - px) * alpha;
          ry = py + (curY - py) * alpha;
        }
        const m = maturity[slot] ?? 0;
        const fadeIn = Math.min(1, m / BIRTH_FADE_FRAC);
        const fadeOut = m <= RIM_FADE_START ? 1 : Math.max(0, 1 - (m - RIM_FADE_START) / (1 - RIM_FADE_START));
        const opacity = fadeIn * fadeOut;
        const scale = DOT_MIN_SCALE + (1 - DOT_MIN_SCALE) * fadeIn;
        el.style.transform = `translate3d(${rx.toFixed(1)}px, ${ry.toFixed(1)}px, 0) scale(${scale.toFixed(3)})`;
        el.style.opacity = opacity.toFixed(3);
        const colorIdx = m < 1 / 3 ? 0 : m < 2 / 3 ? 1 : 2;
        if (lastColorIdx[slot] !== colorIdx) {
          lastColorIdx[slot] = colorIdx;
          el.style.backgroundColor = stops[colorIdx] ?? stops[0] ?? "";
        }
      }
    };

    const recomputeGrowthK = () => {
      lifetimeMs = maxPrimordia * plastochron;
      growthK = Math.max(0.0001, (rRim * rRim - R0 * R0) / (2 * lifetimeMs));
    };

    const warmup = () => {
      const stepMs = plastochron / 4;
      const capScale = stepMs / TICK_MS;
      const ticks = Math.ceil((WARMUP_PLASTOCHRONS * plastochron) / stepMs);
      for (let i = 0; i < ticks; i++) stepPhysics(stepMs, capScale);
      applyToDOM();
    };

    const onThemeChange = () => {
      stops = readStops();
      for (let i = 0; i < n; i++) lastColorIdx[i] = -1;
      applyToDOM();
    };
    const themeObserver = new MutationObserver(onThemeChange);

    const onResize = () => {
      const prevRim = rRim;
      measure();
      if (!started) {
        trySetup();
        return;
      }
      if (prevRim !== rRim) {
        // K stays fixed at its mount-time value on purpose — the live
        // population keeps advecting the same birth history toward the
        // new bounds instead of the field being re-sampled from a formula.
        // Reproject (not re-simulate) so the existing offsets/ages carry over.
        computePositions();
        applyToDOM();
      }
    };
    const ro = new ResizeObserver(onResize);

    const frame = (now: number) => {
      // Fixed-timestep accumulator: leftover sub-tick time MUST carry over
      // frame to frame (acc lives in the outer closure, not reset here) —
      // rAF fires faster than TICK_MS at most refresh rates, so resetting
      // acc to dt every call discarded the remainder every time and this
      // loop advanced physics only on the rare frame-time hiccup.
      const dt = Math.min(200, lastT ? now - lastT : TICK_MS);
      lastT = now;
      acc += dt;
      while (acc >= TICK_MS) {
        // Snapshot the pre-step state as "previous" right before overwriting
        // it, so prevPos always trails posX/posY by exactly one tick even
        // when a laggy frame runs several catch-up ticks in a row.
        prevPosX.set(posX);
        prevPosY.set(posY);
        prevBornOrder.set(bornOrder);
        stepPhysics(TICK_MS, 1);
        acc -= TICK_MS;
      }
      applyToDOM(acc / TICK_MS);
      raf = requestAnimationFrame(frame);
    };

    const onVisibility = () => {
      if (document.hidden) {
        if (raf) cancelAnimationFrame(raf);
        raf = 0;
      } else if (!reduced && started) {
        lastT = 0;
        raf = requestAnimationFrame(frame);
      }
    };

    // reduced-motion still needs to keep visibly living — a single warmed-up
    // frame that never changes again for the life of the mount is a frozen
    // frame, not a calm one. Every REDUCED_PULSE_INTERVAL_MS it runs a short
    // discrete burst of physics ticks and repaints once (a slow, stepped
    // pulse of continued growth/advection, never a continuous per-frame rAF
    // sweep, which is what the vestibular guard actually targets).
    const REDUCED_PULSE_INTERVAL_MS = 2200;
    const REDUCED_PULSE_TICKS = 24;
    let reducedTimer = 0;
    const reducedPulse = () => {
      reducedTimer = 0;
      if (!reduced || document.hidden) {
        reducedTimer = window.setTimeout(reducedPulse, REDUCED_PULSE_INTERVAL_MS);
        return;
      }
      for (let i = 0; i < REDUCED_PULSE_TICKS; i++) stepPhysics(TICK_MS, 1);
      applyToDOM();
      reducedTimer = window.setTimeout(reducedPulse, REDUCED_PULSE_INTERVAL_MS);
    };

    function trySetup() {
      if (started) return;
      measure();
      if (!w || !h) return;
      started = true;
      recomputeGrowthK();
      warmup();
      themeObserver.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });
      if (!reduced) {
        document.addEventListener("visibilitychange", onVisibility);
        raf = requestAnimationFrame(frame);
      } else {
        reducedTimer = window.setTimeout(reducedPulse, REDUCED_PULSE_INTERVAL_MS);
      }
    }

    trySetup();
    ro.observe(root);

    return () => {
      if (raf) cancelAnimationFrame(raf);
      if (reducedTimer) window.clearTimeout(reducedTimer);
      ro.disconnect();
      themeObserver.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, [reduced, plastochron, maxPrimordia]);

  return (
    <div
      ref={rootRef}
      className={["relative isolate min-h-[480px] w-full overflow-hidden bg-background", className].join(" ")}
    >
      <div aria-hidden="true" className="pointer-events-none absolute inset-0">
        {Array.from({ length: maxPrimordia }, (_, slot) => (
          <div
            key={slot}
            ref={(el) => {
              elRefs.current[slot] = el;
            }}
            className="will-change-transform absolute rounded-full"
            style={{
              left: 0,
              top: 0,
              width: DOT_SIZE,
              height: DOT_SIZE,
              marginLeft: -DOT_SIZE / 2,
              marginTop: -DOT_SIZE / 2,
              opacity: 0,
              backgroundColor: "var(--ns-muted)",
            }}
          />
        ))}
      </div>
      {children ? (
        <div className="relative z-10 flex min-h-[inherit] flex-col items-center justify-center px-8 py-14">
          {/* the scrim hugs the copy — spread over the whole pane it washed
              the entire head out to a faint speckle in both themes */}
          <div className="flex max-w-xl flex-col items-center gap-2 rounded-xl bg-background/80 px-8 py-8 text-center backdrop-blur-sm">
            {children}
          </div>
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { useEffect, useId, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// FlyballThrottle — a spend-cap widget built as a Watt centrifugal governor.
// One governing scalar, omega = spendRate / safeRate (safeRate = cap /
// periodDays), drives the whole mechanism: arm elevation angle rises with
// omega squared (capped at 68deg — the linkage self-intersects past that),
// the sleeve collar's drop down the spindle is computed FROM that angle
// through the drawn linkage (armLength * (1 - cos angle)), and the throttle
// lever's rotation maps LINEARLY from the collar's drop, sweeping across a
// small gate track until it lies flat over it at full flare. Axial spin is
// faked (never truly rotated — this is a side-profile diagram) by oscillating
// the two-arm-and-balls group's x-scale on one shared keyframe, at a period
// of SPIN_BASE_MS / omega set through a single CSS custom property — lazy
// spin reads as healthy, a fast blur reads as hot, with no per-ball
// choreography. `value`-style level state (percent of cap already spent)
// never touches the geometry: the arms answer "how fast is it burning right
// now", not "how much is gone" — that distinction is the whole point, and
// is what keeps this legible on day 28 of a calm, on-pace period as well as
// day 6 of a reckless one. Every geometry change (arm/ball position, collar
// drop, lever angle) rides one shared 250ms non-overshooting CSS transition
// on the transitionable SVG geometry properties (d/cx/cy/x/y — all
// CSS-animatable in evergreen browsers) so a stream of per-request omega
// updates settles smoothly instead of twitching frame to frame; no JS
// spring loop. `spent` vs `cap` is a genuinely separate, level-based
// boolean (capReached) that disables the two real action buttons — with
// aria-disabled (not the native attribute, so Tab still reaches them) plus
// an explanatory paragraph — and tints the collar's fill; it never feeds
// the arm/collar/lever geometry itself. DOM+SVG+CSS only, no canvas, every
// stroke/fill a `var(--token)`, --ns-accent reserved for focus/hover.
// ---------------------------------------------------------------------------

export interface FlyballThrottleProps {
  /** current burn rate, currency units per day */
  spendRate: number;
  /** total spend cap for the period */
  cap: number;
  /** length of the cap period, in days */
  periodDays: number;
  /** amount already spent this period — the level that actually gates the buttons */
  spent: number;
  /** currency symbol prefix for readouts (default "$") */
  currency?: string;
  /** what's being governed, shown above the readout, e.g. "API spend" */
  label?: string;
  /** called when "New purchase" is activated while under cap */
  onNewPurchase?: () => void;
  /** called when "Raise limit" is activated while under cap */
  onRaiseLimit?: () => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

// geometry, SVG viewBox units — one side-profile governor: lever+gate at the
// top, arm pivot and flyball assembly below it, sleeve collar sliding on the
// spindle below that, motor housing at the base.
const VIEW_W = 280;
const VIEW_H = 260;
const CX = 140;

const LEVER_PIVOT_Y = 48;
const LEVER_LEN = 84;
const LEVER_OPEN_DEG = 30; // resting angle above the gate track — clearly open
const LEVER_CLOSED_DEG = 0; // flat along the gate track — fully closed over it
const GATE_X1 = CX + LEVER_LEN; // where the gate track ends, == lever tip when flat

const ARM_PIVOT_Y = 108;
const ARM_LEN = 46;
const BALL_R = 7;
const MAX_ARM_DEG = 68; // the linkage self-intersects past this — hard ceiling
const MAX_ARM_RAD = (MAX_ARM_DEG * Math.PI) / 180;
const MAX_COLLAR_DROP = ARM_LEN * (1 - Math.cos(MAX_ARM_RAD));
const ANGLE_K = 22; // deg of arm elevation per omega^2 — small-physics approximation
// real flyball arms hinge on a finite pivot and never fold flush against the
// shaft — without a floor, low-omega ball centers sit closer together than
// their own 2*BALL_R diameter and merge into one blob, which is exactly the
// idle/default frame the registry's owner judges first and hardest. 13deg
// keeps the two balls visibly separated (2*ARM_LEN*sin(13deg) ≈ 20.7px
// center-to-center against a 14px diameter) at omega -> 0.
const MIN_HANG_DEG = 13;

const COLLAR_Y0 = 168; // collar's reference position at omega -> 0 (idle)
const COLLAR_W = 34;
const COLLAR_H = 10;

const MOTOR_TOP_Y = 214;
const MOTOR_H = 30;

const HOT_OMEGA = 1.3; // burn meaningfully above sustainable pace, short of capped
const SPIN_BASE_MS = 900; // spin period at omega == 1 (running exactly at sustainable pace)
const MIN_SPIN_MS = 260;
const MAX_SPIN_MS = 4000;
const MIN_OMEGA_FOR_SPIN = 0.08; // divisor floor so idle settles at MAX_SPIN_MS, not Infinity

type Band = "calm" | "hot" | "closed";

function clamp(n: number, lo: number, hi: number) {
  return Math.max(lo, Math.min(hi, n));
}

function fmtMoney(n: number, currency: string) {
  if (!Number.isFinite(n)) return `${currency}0`;
  const v = Math.max(0, n);
  const text = v < 10 && !Number.isInteger(v) ? v.toFixed(1) : Math.round(v).toString();
  return `${currency}${text}`;
}

function fmtDays(n: number) {
  if (!Number.isFinite(n) || n <= 0) return "today";
  if (n < 1) return "under a day";
  const r = Math.round(n);
  return `${r} day${r === 1 ? "" : "s"}`;
}

export function FlyballThrottle({
  spendRate,
  cap,
  periodDays,
  spent,
  currency = "$",
  label = "Spend governor",
  onNewPurchase,
  onRaiseLimit,
  className = "",
}: FlyballThrottleProps) {
  const uid = useId();
  const labelId = `${uid}-label`;
  const descId = `${uid}-desc`;
  const closedNoteId = `${uid}-closed`;

  const safeSpendRate = Math.max(0, spendRate);
  const safeRate = periodDays > 0 ? cap / periodDays : 0;
  const omega = safeRate > 0 ? safeSpendRate / safeRate : safeSpendRate > 0 ? Number.POSITIVE_INFINITY : 0;
  const omegaForGeometry = Number.isFinite(omega) ? omega : 999;

  const angleDeg = clamp(
    MIN_HANG_DEG + ANGLE_K * omegaForGeometry * omegaForGeometry,
    MIN_HANG_DEG,
    MAX_ARM_DEG
  );
  const angleRad = (angleDeg * Math.PI) / 180;

  const ballDX = ARM_LEN * Math.sin(angleRad);
  const ballDY = ARM_LEN * Math.cos(angleRad);
  const ballLeftX = CX - ballDX;
  const ballRightX = CX + ballDX;
  const ballY = ARM_PIVOT_Y + ballDY;

  const collarDrop = ARM_LEN * (1 - Math.cos(angleRad));
  const collarY = COLLAR_Y0 + collarDrop;

  const throttleFrac = MAX_COLLAR_DROP > 0 ? clamp(collarDrop / MAX_COLLAR_DROP, 0, 1) : 0;
  const leverDeg = LEVER_OPEN_DEG - (LEVER_OPEN_DEG - LEVER_CLOSED_DEG) * throttleFrac;
  const leverRad = (leverDeg * Math.PI) / 180;
  const leverEndX = CX + LEVER_LEN * Math.cos(leverRad);
  const leverEndY = LEVER_PIVOT_Y - LEVER_LEN * Math.sin(leverRad);

  const spinMs = clamp(SPIN_BASE_MS / Math.max(omegaForGeometry, MIN_OMEGA_FOR_SPIN), MIN_SPIN_MS, MAX_SPIN_MS);

  // capReached is a real, independent level check — spent vs cap — never the
  // arm/collar/lever geometry above, which is entirely rate-derived (omega).
  const capReached = cap > 0 && spent >= cap;

  const daysToCap = safeSpendRate > 0 ? (cap - spent) / safeSpendRate : Number.POSITIVE_INFINITY;
  const forecastText = capReached
    ? "the cap has been reached for this period"
    : !Number.isFinite(daysToCap) || daysToCap > periodDays
      ? "on pace to stay under cap this period"
      : `cap reached in ${fmtDays(daysToCap)} at this pace`;

  const band: Band = capReached ? "closed" : omega >= HOT_OMEGA ? "hot" : "calm";
  const [announce, setAnnounce] = useState("");
  const prevBandRef = useRef<Band | null>(null);

  useEffect(() => {
    if (prevBandRef.current === null) {
      prevBandRef.current = band; // no crossing announcement on first paint
      return;
    }
    if (prevBandRef.current === band) return;
    prevBandRef.current = band;
    if (band === "closed") {
      setAnnounce(
        `Closed — spend cap of ${fmtMoney(cap, currency)} reached; new purchases and limit increases are disabled until next period.`
      );
    } else if (band === "hot") {
      setAnnounce(
        `Hot — burning ${fmtMoney(safeSpendRate, currency)}/day against a ${fmtMoney(safeRate, currency)}/day sustainable rate.`
      );
    } else {
      setAnnounce("Calm — burn rate back under the sustainable pace.");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [band]);

  const btnBase =
    "flex-1 rounded-md border px-3 py-2 text-sm font-medium transition-colors duration-200 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent";
  const btnLive =
    "border-border bg-background text-foreground hover:border-foreground/30 hover:bg-foreground/[0.05] cursor-pointer";
  const btnDead = "border-border bg-background text-ns-muted opacity-50 cursor-not-allowed";

  return (
    <div
      role="group"
      data-flyball-root
      aria-labelledby={labelId}
      aria-describedby={descId}
      className={`w-full max-w-md rounded-md border border-border bg-background p-5 ${className}`}
    >
      <style>{`
.ns-flyball-part{transition-property:d,cx,cy,x,y}
.ns-flyball-part{transition-duration:250ms;transition-timing-function:cubic-bezier(0.16,1,0.3,1)}
@keyframes ns-flyball-spin{0%,100%{transform:scaleX(1)}50%{transform:scaleX(0.74)}}
.ns-flyball-spin-group{
  animation:ns-flyball-spin var(--ns-flyball-spin-ms,1400ms) linear infinite;
  transform-box:view-box;
  transform-origin:${CX}px ${ARM_PIVOT_Y}px;
}
@media (prefers-reduced-motion: reduce){
  /* Not a snap: a state change (a press moving omega) still needs to read as
     movement, just without the ambient never-ending spin blur, which is the
     part reduced-motion is actually meant to suppress. Short, linear, no
     overshoot — small-amplitude SVG attribute interpolation, not parallax
     or anything vestibular. */
  .ns-flyball-part{transition-duration:120ms !important; transition-timing-function:linear !important}
  .ns-flyball-spin-group{animation:none !important}
}
`}</style>

      <div className="flex items-baseline justify-between gap-3">
        <span id={labelId} className="font-mono text-[11px] tracking-wide text-ns-muted">
          {label.toUpperCase()}
        </span>
        <span className="font-mono text-[11px] font-semibold tracking-wide text-foreground">
          {band.toUpperCase()}
        </span>
      </div>

      <p id={descId} className="mt-2 text-sm leading-relaxed text-foreground">
        Spending <span className="font-mono font-semibold">{fmtMoney(safeSpendRate, currency)}</span>/day against a{" "}
        <span className="font-mono">{fmtMoney(safeRate, currency)}</span>/day sustainable rate — {forecastText}.
      </p>

      <div aria-hidden="true" className="mt-3 flex justify-center">
        <svg
          viewBox={`0 0 ${VIEW_W} ${VIEW_H}`}
          className="h-[210px] w-full max-w-[260px]"
          aria-hidden="true"
          focusable="false"
        >
          {/* spindle shaft */}
          <line x1={CX} y1={LEVER_PIVOT_Y} x2={CX} y2={MOTOR_TOP_Y} stroke="var(--border)" strokeWidth={2} />

          {/* motor housing, fixed reference at the base */}
          <rect
            x={CX - 30}
            y={MOTOR_TOP_Y}
            width={60}
            height={MOTOR_H}
            rx={4}
            fill="none"
            stroke="var(--border)"
            strokeWidth={2}
          />

          {/* pushrod — collar to lever pivot, the coupling that makes the collar "drive" the lever */}
          <line
            className="ns-flyball-part"
            x1={CX + 6}
            y1={collarY}
            x2={CX + 6}
            y2={LEVER_PIVOT_Y + 4}
            stroke="var(--border)"
            strokeWidth={1.25}
            strokeDasharray="2 5"
          />

          {/* throttle gate track + the two action glyphs the lever sweeps over */}
          <line
            x1={CX}
            y1={LEVER_PIVOT_Y}
            x2={GATE_X1}
            y2={LEVER_PIVOT_Y}
            stroke="var(--border)"
            strokeWidth={2}
