            opacity={0.55}
          />
          <rect
            x={CX + 20}
            y={LEVER_PIVOT_Y + 8}
            width={16}
            height={10}
            rx={2}
            fill="none"
            stroke="var(--border)"
            strokeWidth={1.25}
          />
          <rect
            x={CX + 48}
            y={LEVER_PIVOT_Y + 8}
            width={16}
            height={10}
            rx={2}
            fill="none"
            stroke="var(--border)"
            strokeWidth={1.25}
          />

          {/* lever pivot joint + the lever itself, rotation mapped linearly from collar drop */}
          <circle cx={CX} cy={LEVER_PIVOT_Y} r={3} fill="var(--foreground)" />
          <path
            className="ns-flyball-part"
            d={`M ${CX} ${LEVER_PIVOT_Y} L ${leverEndX.toFixed(2)} ${leverEndY.toFixed(2)}`}
            stroke="var(--foreground)"
            strokeWidth={3}
            strokeLinecap="round"
