"use client";

import { useEffect, useId, useRef } from "react";

// ---------------------------------------------------------------------------
// HelicorderLineWrap — a seismograph helicorder drum record: a pen traces one
// horizontal line at a time; when it runs off the right margin it steps down
// to the row below and starts again at the left, so the record grows as a
// stack of offset lines, oldest at top, rather than one continuous scroll.
//
// 8 fixed row slots, each its own <canvas> (a completed row is a static
// bitmap — it is never redrawn once finished, only the live row is painted
// incrementally). Once all 8 fill, a further wrap SHIFTS the whole stack up
// by one row (canvas-to-canvas drawImage copies, oldest row's content
// discarded) rather than looping/fading the whole card, so motion in the
// tower stays continuous forever instead of resetting.
//
// The wrap itself — the ONE followable event per the round-9 legibility rule
// — is never a teleport: the pen head fades out at the right margin over
// 80ms, the stack shifts (or steps down) while it is invisible, and a fresh
// pen head fades in at the left margin of the next row over 120ms. Idle
// drawing pauses for that 200ms window so nothing competes with the step.
// ---------------------------------------------------------------------------

export interface HelicorderLineWrapProps {
  /** Seconds of app time per traced row. @default 12 */
  lineSeconds?: number;
  /** Number of stacked rows in the drum. @default 8 */
  rows?: number;
  /** Average seconds between quake spikes (randomized +-40%). @default 28 */
  quakeIntervalSeconds?: number;
  /** Freezes on the composed still frame without unmounting. */
  paused?: boolean;
  className?: string;
  style?: React.CSSProperties;
}

type Phase = "drawing" | "fadeOut" | "fadeIn";

const MARGIN_PX = 2; // px kept clear at each row's edges so the trace never touches the border
const WRAP_FADE_OUT_MS = 80;
const WRAP_FADE_IN_MS = 120;
const IDLE_AMP_PX = 2; // baseline microseism, +-2px
const QUAKE_AMP_MIN = 15;
const QUAKE_AMP_MAX = 20;
const QUAKE_RISE_MS = 200;
const QUAKE_DECAY_MS = 2500;

// The reduced-motion / paused still: 4 of 8 rows completed, the 5th traced
// 60% across, one quake bump baked into an earlier completed row — a clearly
// mid-instrument, structured frame.
const STATIC_ROW = 4;
const STATIC_PROGRESS = 0.6;

// Smooth, seeded pseudo-noise (sum of two incommensurate sines) so both the
// live trace and the deterministic static frame can evaluate "the same kind
// of wiggle" at any x without needing stored random samples.
function microseism(x: number): number {
  return IDLE_AMP_PX * (0.6 * Math.sin(x * 0.041 + 1.7) + 0.4 * Math.sin(x * 0.095 + 0.3));
}

function quakeEnvelope(elapsedMs: number): number {
  if (elapsedMs < 0) return 0;
  if (elapsedMs < QUAKE_RISE_MS) return elapsedMs / QUAKE_RISE_MS;
  const t = elapsedMs - QUAKE_RISE_MS;
  return Math.exp(-t / (QUAKE_DECAY_MS / 3));
}

export function HelicorderLineWrap({
  lineSeconds = 12,
  rows = 8,
  quakeIntervalSeconds = 28,
  paused = false,
  className = "",
  style,
}: HelicorderLineWrapProps) {
  const wrapRef = useRef<HTMLDivElement | null>(null);
  const rowRefs = useRef<(HTMLCanvasElement | null)[]>([]);
  const headRef = useRef<HTMLDivElement | null>(null);
  const uid = useId();
  const pausedRef = useRef(paused);
  pausedRef.current = paused;

  useEffect(() => {
    const wrap = wrapRef.current;
    if (!wrap) return;
    const canvases = rowRefs.current.slice(0, rows);
    if (canvases.some((c) => !c)) return;
    const head = headRef.current;

    let disposed = false;
    let raf = 0;
    let running = false;
    let staticMode = false;

    let rowW = 0;
    let rowH = 0;
    let dpr = 1;

    let fg = "#171717";
    const readColors = () => {
      const cs = getComputedStyle(document.documentElement);
      fg = cs.getPropertyValue("--foreground").trim() || "#171717";
    };
    readColors();

    // ---- per-row backing store ---------------------------------------------
    const ctxs: (CanvasRenderingContext2D | null)[] = canvases.map((c) =>
      c!.getContext("2d", { alpha: true })
    );

    const sizeCanvas = (c: HTMLCanvasElement, ctx: CanvasRenderingContext2D | null) => {
      const pw = Math.max(2, Math.round(rowW * dpr));
      const ph = Math.max(2, Math.round(rowH * dpr));
      if (c.width !== pw || c.height !== ph) {
        c.width = pw;
        c.height = ph;
      }
      c.style.width = `${rowW}px`;
      c.style.height = `${rowH}px`;
      if (ctx) {
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      }
    };

    // ---- live-row state ------------------------------------------------------
    let liveRow = 0; // index into canvases, current bottom of the growing tower
    let stackFull = false;
    let x = 0; // css px across the live row, 0..rowW
    let lastX = 0;
    let lastY = 0;
    let lineMs = lineSeconds * 1000;
    let speedPxPerMs = 0;

    let simMs = 0;
    let nextQuakeAtMs = quakeIntervalSeconds * 1000 * (0.6 + Math.random() * 0.8);
    let quakeStartMs = -1e9;
    let quakeAmp = 0;
    let quakeSign = 1;

    let phase: Phase = "drawing";
    let phaseStartMs = 0;

    const resetRow = () => {
      x = MARGIN_PX;
      lastX = MARGIN_PX;
      lastY = rowH / 2;
    };

    const clearRowCanvas = (i: number) => {
      const c = canvases[i]!;
      const ctx = ctxs[i]!;
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, c.width, c.height);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };

    const shiftStackUp = () => {
      // canvas-to-canvas copy: row i takes row i+1's finished bitmap, row
      // `rows-1` (the one about to become live again) is cleared. This is
      // what makes the oldest trace scroll off the top instead of the whole
      // card looping and restarting.
      for (let i = 0; i < rows - 1; i++) {
        const dst = canvases[i]!;
        const dctx = ctxs[i]!;
        const src = canvases[i + 1]!;
        dctx.setTransform(1, 0, 0, 1, 0, 0);
        dctx.clearRect(0, 0, dst.width, dst.height);
        dctx.drawImage(src, 0, 0);
        dctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      }
      clearRowCanvas(rows - 1);
    };

    const drawSegment = (row: number, x0: number, y0: number, x1: number, y1: number) => {
      const ctx = ctxs[row];
      if (!ctx) return;
      ctx.strokeStyle = fg;
      ctx.lineWidth = 1.4;
      ctx.lineCap = "round";
      ctx.beginPath();
      ctx.moveTo(x0, y0);
      ctx.lineTo(x1, y1);
      ctx.stroke();
    };

    const traceY = (progressX: number, nowMs: number) => {
      let y = rowH / 2 + microseism(progressX);
      const env = quakeEnvelope(nowMs - quakeStartMs);
      if (env > 0.001) y += quakeSign * quakeAmp * env;
      return y;
    };

    const placeHead = (rowIndex: number, px: number, py: number, opacity: number) => {
      if (!head) return;
      head.style.transform = `translate(${px - 2}px, ${rowIndex * rowH + py - 2}px)`;
      head.style.opacity = String(opacity);
    };

    // ---- deterministic static frame -----------------------------------------
    const drawStaticFrame = () => {
      for (let i = 0; i < rows; i++) clearRowCanvas(i);
      if (head) head.style.opacity = "0";
      for (let r = 0; r < rows; r++) {
        if (r > STATIC_ROW) continue;
        const fullWidth = r < STATIC_ROW;
        const targetX = fullWidth ? rowW - MARGIN_PX : MARGIN_PX + (rowW - 2 * MARGIN_PX) * STATIC_PROGRESS;
        let px = MARGIN_PX;
        let py = rowH / 2;
        const step = 3;
        for (let sx = MARGIN_PX + step; sx <= targetX; sx += step) {
          let sy = rowH / 2 + microseism(sx);
          // bake one quake bump into row 1, mid-height, so the still isn't a
          // flat instrument with nothing having ever happened
          if (r === 1) {
            const bumpCenter = rowW * 0.55;
            const bumpEnv = quakeEnvelope(QUAKE_RISE_MS + (sx - bumpCenter) * 22);
            if (sx >= bumpCenter) sy += 18 * bumpEnv;
          }
          drawSegment(r, px, py, sx, sy);
          px = sx;
          py = sy;
        }
      }
    };

    // ---- main loop ------------------------------------------------------------
    let lastMs = performance.now();

    const stepDrawing = (dt: number, nowMs: number) => {
      if (nextQuakeAtMs <= simMs) {
        quakeStartMs = simMs;
        quakeAmp = QUAKE_AMP_MIN + Math.random() * (QUAKE_AMP_MAX - QUAKE_AMP_MIN);
        quakeSign = Math.random() < 0.5 ? -1 : 1;
        nextQuakeAtMs = simMs + quakeIntervalSeconds * 1000 * (0.64 + Math.random() * 1.43);
      }

      x += speedPxPerMs * dt;
      const clampedX = Math.min(x, rowW - MARGIN_PX);
      const y = traceY(clampedX, simMs);
      drawSegment(liveRow, lastX, lastY, clampedX, y);
      lastX = clampedX;
      lastY = y;
      placeHead(liveRow, clampedX, y, 1);

      if (x >= rowW - MARGIN_PX) {
        phase = "fadeOut";
        phaseStartMs = nowMs;
      }
    };

    const stepWrap = (nowMs: number) => {
      const elapsed = nowMs - phaseStartMs;
      if (phase === "fadeOut") {
        const t = Math.min(1, elapsed / WRAP_FADE_OUT_MS);
        placeHead(liveRow, lastX, lastY, 1 - t);
        if (t >= 1) {
          // the step itself happens while the head is invisible
          if (stackFull) {
            shiftStackUp();
            liveRow = rows - 1;
          } else if (liveRow < rows - 1) {
            liveRow += 1;
            if (liveRow === rows - 1) stackFull = true;
          } else {
            stackFull = true;
            shiftStackUp();
          }
          resetRow();
          phase = "fadeIn";
          phaseStartMs = nowMs;
          placeHead(liveRow, lastX, lastY, 0);
        }
      } else if (phase === "fadeIn") {
        const t = Math.min(1, elapsed / WRAP_FADE_IN_MS);
        placeHead(liveRow, lastX, lastY, t);
        if (t >= 1) phase = "drawing";
      }
    };

    const loop = (nowMs: number) => {
      const rawMs = Math.min(50, nowMs - lastMs);
      lastMs = nowMs;
      simMs += rawMs;
      if (phase === "drawing") stepDrawing(rawMs, nowMs);
      else stepWrap(nowMs);
      raf = requestAnimationFrame(loop);
    };

    const wake = () => {
      if (running || disposed) return;
      running = true;
      lastMs = performance.now();
      raf = requestAnimationFrame(loop);
    };
    const sleep = () => {
      cancelAnimationFrame(raf);
      running = false;
    };

    const resetAll = () => {
      for (let i = 0; i < rows; i++) clearRowCanvas(i);
      liveRow = 0;
      stackFull = false;
      resetRow();
      phase = "drawing";
      if (head) head.style.opacity = "0";
    };

    const applySize = () => {
      const rect = wrap.getBoundingClientRect();
      if (rect.width < 2 || rect.height < 2) return;
      const changed = Math.abs(rect.width - rowW) > 0.5 || Math.abs(rect.height / rows - rowH) > 0.5;
      rowW = rect.width;
      rowH = rect.height / rows;
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      lineMs = Math.max(1000, lineSeconds * 1000);
      speedPxPerMs = rowW / lineMs;
      for (let i = 0; i < rows; i++) sizeCanvas(canvases[i]!, ctxs[i]);
      if (changed) {
        if (staticMode) drawStaticFrame();
        else resetAll();
      }
    };

    const ro = new ResizeObserver(applySize);
    ro.observe(wrap);
    applySize();

    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    let reduced = mq.matches;
    const applyMode = () => {
      if (reduced || pausedRef.current) {
        staticMode = true;
        sleep();
        drawStaticFrame();
      } else {
        if (staticMode) resetAll();
        staticMode = false;
        wake();
      }
    };
    const onMq = () => {
      reduced = mq.matches;
      applyMode();
    };
    mq.addEventListener("change", onMq);

    let onScreen = true;
    const io = new IntersectionObserver(
      (entries) => {
        onScreen = entries.some((en) => en.isIntersecting);
        if (!onScreen) sleep();
        else if (!staticMode && !document.hidden) wake();
      },
      { threshold: 0 }
    );
    io.observe(wrap);

    const onVis = () => {
      if (document.hidden) sleep();
      else if (!staticMode && onScreen) wake();
    };
    document.addEventListener("visibilitychange", onVis);
    applyMode();

    let lastPolledPaused = pausedRef.current;
    let poll = 0;
    const tick = () => {
      if (pausedRef.current !== lastPolledPaused) {
        lastPolledPaused = pausedRef.current;
        applyMode();
      }
      poll = window.setTimeout(tick, 140);
    };
    tick();

    const themeObserver = new MutationObserver(() => {
      readColors();
      if (staticMode) drawStaticFrame();
    });
    themeObserver.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    return () => {
      disposed = true;
      ro.disconnect();
      io.disconnect();
      mq.removeEventListener("change", onMq);
      document.removeEventListener("visibilitychange", onVis);
      themeObserver.disconnect();
      window.clearTimeout(poll);
      sleep();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [lineSeconds, rows, quakeIntervalSeconds]);

  return (
    <div
      ref={wrapRef}
      data-helicorder-line-wrap={uid}
      role="img"
      aria-label="Seismic activity monitor, live helicorder trace"
      className={`relative flex h-full w-full flex-col overflow-hidden bg-background ${className}`}
      style={style}
    >
      {Array.from({ length: rows }).map((_, i) => (
        <div key={i} className={`relative flex-1 ${i > 0 ? "border-t border-border" : ""}`}>
          <canvas
            ref={(el) => {
              rowRefs.current[i] = el;
            }}
            aria-hidden="true"
            className="absolute inset-0 block h-full w-full"
          />
        </div>
      ))}
      {/* the pen head: a single overlay dot, its position and opacity
          written directly every frame (never React state) so the 80ms/120ms
          wrap fade reads as one continuous instrument, not a re-render */}
      <div
        ref={headRef}
        aria-hidden="true"
        className="pointer-events-none absolute left-0 top-0 h-1 w-1 rounded-full bg-foreground opacity-0"
      />
    </div>
  );
}

HelicorderLineWrap.displayName = "HelicorderLineWrap";

"use client";

import { useEffect, useRef } from "react";

const ASCII_RAMP = " .:-=+*#%@";

// Built-in 5x7 block font: uppercase A-Z, 0-9, space, "-", ".", "!". Each
// glyph is 7 rows of a 5-bit string, MSB-first, top row first. Deliberately
// hand-drawn geometric shapes, not a traced copy of any real bitmap font —
// good enough to read as block type, not meant to be typographically exact.
const FONT: Record<string, string[]> = {
  A: ["01110", "10001", "10001", "11111", "10001", "10001", "10001"],
  B: ["11110", "10001", "10001", "11110", "10001", "10001", "11110"],
  C: ["01111", "10000", "10000", "10000", "10000", "10000", "01111"],
  D: ["11110", "10001", "10001", "10001", "10001", "10001", "11110"],
  E: ["11111", "10000", "10000", "11110", "10000", "10000", "11111"],
  F: ["11111", "10000", "10000", "11110", "10000", "10000", "10000"],
  G: ["01111", "10000", "10000", "10011", "10001", "10001", "01110"],
  H: ["10001", "10001", "10001", "11111", "10001", "10001", "10001"],
  I: ["01110", "00100", "00100", "00100", "00100", "00100", "01110"],
  J: ["00111", "00010", "00010", "00010", "00010", "10010", "01100"],
  K: ["10001", "10010", "10100", "11000", "10100", "10010", "10001"],
  L: ["10000", "10000", "10000", "10000", "10000", "10000", "11111"],
  M: ["10001", "11011", "10101", "10101", "10001", "10001", "10001"],
  N: ["10001", "11001", "10101", "10101", "10011", "10001", "10001"],
  O: ["01110", "10001", "10001", "10001", "10001", "10001", "01110"],
  P: ["11110", "10001", "10001", "11110", "10000", "10000", "10000"],
  Q: ["01110", "10001", "10001", "10001", "10101", "10010", "01101"],
  R: ["11110", "10001", "10001", "11110", "10100", "10010", "10001"],
  S: ["01111", "10000", "10000", "01110", "00001", "00001", "11110"],
  T: ["11111", "00100", "00100", "00100", "00100", "00100", "00100"],
  U: ["10001", "10001", "10001", "10001", "10001", "10001", "01110"],
  V: ["10001", "10001", "10001", "10001", "10001", "01010", "00100"],
  W: ["10001", "10001", "10001", "10101", "10101", "11011", "10001"],
  X: ["10001", "10001", "01010", "00100", "01010", "10001", "10001"],
  Y: ["10001", "10001", "01010", "00100", "00100", "00100", "00100"],
  Z: ["11111", "00010", "00100", "01000", "10000", "10000", "11111"],
  "0": ["01110", "10001", "10011", "10101", "11001", "10001", "01110"],
  "1": ["00100", "01100", "00100", "00100", "00100", "00100", "01110"],
  "2": ["01110", "10001", "00001", "00010", "00100", "01000", "11111"],
  "3": ["11111", "00010", "00100", "00010", "00001", "10001", "01110"],
  "4": ["00010", "00110", "01010", "10010", "11111", "00010", "00010"],
  "5": ["11111", "10000", "11110", "00001", "00001", "10001", "01110"],
  "6": ["00110", "01000", "10000", "11110", "10001", "10001", "01110"],
  "7": ["11111", "00001", "00010", "00100", "01000", "01000", "01000"],
  "8": ["01110", "10001", "10001", "01110", "10001", "10001", "01110"],
  "9": ["01110", "10001", "10001", "01111", "00001", "00010", "01100"],
  " ": ["00000", "00000", "00000", "00000", "00000", "00000", "00000"],
  "-": ["00000", "00000", "00000", "11111", "00000", "00000", "00000"],
  ".": ["00000", "00000", "00000", "00000", "00000", "01100", "01100"],
  "!": ["00100", "00100", "00100", "00100", "00100", "00000", "00100"],
};

const GLYPH_W = 5;
const GLYPH_H = 7;
const GLYPH_GAP = 1; // blank columns between letters

export interface GlyphCastProps {
  /** headline text; unsupported characters render as a blank cell */
  text: string;
  /** cursor-proximity light radius in px, at the canvas's own pixel scale */
  cursorRadius?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function GlyphCast({
  text,
  cursorRadius = 120,
  className = "",
}: GlyphCastProps) {
  const wrapRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const wrap = wrapRef.current;
    const canvas = canvasRef.current;
    if (!wrap || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const chars = Array.from(text.toUpperCase());
    const cols = chars.length * GLYPH_W + Math.max(0, chars.length - 1) * GLYPH_GAP;
    const rows = GLYPH_H;

    // resolve which grid cells are "on" once — the font map never changes
    const bitmap: boolean[][] = Array.from({ length: rows }, () =>
      new Array(cols).fill(false)
    );
    let cx = 0;
    for (const ch of chars) {
      const glyph = FONT[ch] ?? FONT[" "];
      for (let r = 0; r < GLYPH_H; r++) {
        for (let c = 0; c < GLYPH_W; c++) {
          if (glyph[r][c] === "1") bitmap[r][cx + c] = true;
        }
      }
      cx += GLYPH_W + GLYPH_GAP;
    }

    let fg = getComputedStyle(canvas).color;
    let cellSize = 16;
    let dpr = 1;
    const cursor = { x: -1e4, y: -1e4, tx: -1e4, ty: -1e4, amt: 0, tAmt: 0 };
    let raf = 0;

    const resize = () => {
      const width = wrap.clientWidth;
      cellSize = width / cols;
      const height = cellSize * rows;
      wrap.style.height = `${height}px`;
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = width * dpr;
      canvas.height = height * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.font = `${cellSize * 0.92}px "GeistMono", ui-monospace, monospace`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      draw();
    };

    const draw = () => {
      const width = wrap.clientWidth;
      const height = cellSize * rows;
      ctx.clearRect(0, 0, width, height);
      ctx.fillStyle = fg;
      const r2 = cursorRadius * cursorRadius;
      const active = cursor.amt > 0.01;

      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          if (!bitmap[r][c]) continue;
          const px = c * cellSize + cellSize / 2;
          const py = r * cellSize + cellSize / 2;
          // resting density — uniform, deliberately legible on its own
          let lum = 0.78;
          if (active) {
            const dx = px - cursor.x;
            const dy = py - cursor.y;
            const d2 = dx * dx + dy * dy;
            const dist = Math.sqrt(d2);
            const boost = Math.exp(-d2 / r2) * 0.22;
            const farStart = cursorRadius * 1.15;
            const far = Math.min(
              1,
              Math.max(0, (dist - farStart) / (cursorRadius * 3))
            );
            lum = lum + cursor.amt * (boost - far * 0.55);
          }
          lum = Math.min(1, Math.max(0.08, lum));
          const idx = Math.round(lum * (ASCII_RAMP.length - 1));
          const glyph = ASCII_RAMP[idx];
          if (glyph === " ") continue;
          ctx.globalAlpha = 0.35 + lum * 0.65;
          ctx.fillText(glyph, px, py);
        }
      }
      ctx.globalAlpha = 1;
    };

    const loop = () => {
      cursor.x += (cursor.tx - cursor.x) * 0.18;
      cursor.y += (cursor.ty - cursor.y) * 0.18;
      cursor.amt += (cursor.tAmt - cursor.amt) * 0.12;
      draw();
      raf = requestAnimationFrame(loop);
    };

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(resize, 100);
    };
    const ro = new ResizeObserver(onResize);
    ro.observe(wrap);

    const onPointer = (e: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      cursor.tx = e.clientX - rect.left;
      cursor.ty = e.clientY - rect.top;
      cursor.tAmt = 1;
    };
    const onLeave = () => {
      cursor.tAmt = 0;
    };
    // the site's theme toggle flips a `.dark` class on <html> live, with no
    // remount — watch it so the glyph color updates without a page reload
    const themeObserver = new MutationObserver(() => {
      fg = getComputedStyle(canvas).color;
      if (reduced) draw();
    });
    themeObserver.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    resize();
    window.addEventListener("resize", onResize);
    canvas.addEventListener("pointermove", onPointer);
    canvas.addEventListener("pointerleave", onLeave);

    if (!reduced) raf = requestAnimationFrame(loop);

    return () => {
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      window.removeEventListener("resize", onResize);
      ro.disconnect();
      canvas.removeEventListener("pointermove", onPointer);
      canvas.removeEventListener("pointerleave", onLeave);
      themeObserver.disconnect();
    };
  }, [text, cursorRadius]);

  return (
    <div ref={wrapRef} className={`relative w-full ${className}`}>
      <canvas ref={canvasRef} aria-hidden className="ns-haw-canvas block w-full text-foreground" />
      <span className="sr-only">{text}</span>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// LodestoneHero — full-bleed hero where the headline exists twice: crisp DOM
// type above, and beneath it a canvas field of iron-filing strokes solved from
// a two-pole dipole field (cursor pole + fixed anchor pole behind the primary
// CTA). Filings pack densely only inside the headline's letter-mask, so the
// type visibly "iron-files" into existence as the cursor approaches; hovering
// the CTA doubles its pole strength and bends the whole field toward the
// button. Vector-field solver rendering: each filing is a short line segment
// whose angle chases atan2 of the summed field vector with critically-damped
// easing. Canvas 2D, refs-only hot path, breath-cycle ambient drift with real
// sleep windows between breaths.
// ---------------------------------------------------------------------------

type Vec3 = [number, number, number];

function parseColor(raw: string): Vec3 | null {
  const s = raw.trim();
  if (s.startsWith("#")) {
    const hex = s.slice(1);
    if (hex.length === 3) {
      const r = parseInt(hex.slice(0, 1) + hex.slice(0, 1), 16);
      const g = parseInt(hex.slice(1, 2) + hex.slice(1, 2), 16);
      const b = parseInt(hex.slice(2, 3) + hex.slice(2, 3), 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    if (hex.length >= 6) {
      const r = parseInt(hex.slice(0, 2), 16);
      const g = parseInt(hex.slice(2, 4), 16);
      const b = parseInt(hex.slice(4, 6), 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    return null;
  }
  const m = s.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
}

function mix(a: Vec3, b: Vec3, t: number): Vec3 {
  return [
    Math.round(a[0] + (b[0] - a[0]) * t),
    Math.round(a[1] + (b[1] - a[1]) * t),
    Math.round(a[2] + (b[2] - a[2]) * t),
  ];
}

// deterministic prng — filing placement is stable across re-renders
function mulberry32(a: number) {
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// 2-octave value noise — seeds each filing's ambient-drift character
function hash2(x: number, y: number) {
  const n = Math.sin(x * 127.1 + y * 311.7) * 43758.5453123;
  return n - Math.floor(n);
}
function vnoise(x: number, y: number) {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const xf = x - xi;
  const yf = y - yi;
  const u = xf * xf * (3 - 2 * xf);
  const v = yf * yf * (3 - 2 * yf);
  const a = hash2(xi, yi);
  const b = hash2(xi + 1, yi);
  const c = hash2(xi, yi + 1);
  const d = hash2(xi + 1, yi + 1);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}
function noise2(x: number, y: number) {
  return 0.65 * vnoise(x, y) + 0.35 * vnoise(x * 2.1 + 19.7, y * 2.1 + 7.3);
}

function easeOutExpo(p: number) {
  return p >= 1 ? 1 : 1 - Math.pow(2, -10 * p);
}

// time-based pole-strength tween — duration IS the forced-settle deadline
// (max 600ms < 800ms budget), so a spring can never hunt forever
type Tween = { from: number; to: number; t0: number; dur: number; value: number; active: boolean };
function retarget(tw: Tween, to: number, dur: number, now: number) {
  if (!tw.active && tw.value === to) return;
  tw.from = tw.value;
  tw.to = to;
  tw.t0 = now;
  tw.dur = dur;
  tw.active = true;
}
function tickTween(tw: Tween, now: number) {
  if (!tw.active) return;
  const p = (now - tw.t0) / tw.dur;
  if (p >= 1) {
    tw.value = tw.to;
    tw.active = false;
  } else {
    tw.value = tw.from + (tw.to - tw.from) * easeOutExpo(p);
  }
}

const POLE_RMIN = 48; // r clamp — field never blows up at the pole core
const MAG_SOFT = 5.5e-5; // soft-knee normalizer for magnitude → alpha
const IDLE_MS = 500; // pointer-idle threshold before ambient drift fades in
const DRIFT_HZ = 0.1; // ambient oscillation frequency
const DRIFT_AMP = (8 * Math.PI) / 180; // ±8°
const BREATH_S = 12; // ambient breath cycle length
const ACTIVE_FRAC = 0.72; // fraction of the cycle that drifts; rest = sleep
const SLEEP_EPS = 0.001; // max per-filing angular delta below which we sleep

export function LodestoneHero({
  eyebrow = "FIELD-ALIGNED INFRASTRUCTURE",
  headlineLines = ["Every signal bends", "toward your stack"],
  subcopy = "Lodestone routes traffic the way a magnet organizes iron filings: declare the pole, and every request, retry, and rollback aligns itself. No orchestration YAML, no drift.",
  primaryCta = { label: "Deploy the field", href: "#deploy" },
  secondaryCta = { label: "Read the docs", href: "#docs" },
  stats = [
    { value: "12ms", label: "p99 route solve" },
    { value: "99.98%", label: "field uptime" },
    { value: "4,200+", label: "clusters aligned" },
  ],
  maskFilings = 1800,
  ambientFilings = 600,
  className = "",
}: {
  /** mono eyebrow line above the headline */
  eyebrow?: string;
  /** display headline, one string per rendered line — this is the letter-mask source */
  headlineLines?: string[];
  /** muted supporting copy under the headline */
  subcopy?: string;
  /** primary accent CTA — its center is the fixed anchor pole */
  primaryCta?: { label: string; href: string };
  /** ghost secondary CTA */
  secondaryCta?: { label: string; href: string };
  /** three mono stats for the bordered strip below the CTAs */
  stats?: { value: string; label: string }[];
  /** filings rejection-sampled inside the headline letter-mask */
  maskFilings?: number;
  /** sparse ambient filings outside the mask */
  ambientFilings?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}) {
  const rootRef = useRef<HTMLElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const headlineRef = useRef<HTMLHeadingElement>(null);
  const ctaRef = useRef<HTMLAnchorElement>(null);
  const lineRefs = useRef<(HTMLSpanElement | null)[]>([]);
  const linesKey = headlineLines.join("�");

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    const headline = headlineRef.current;
    const cta = ctaRef.current;
    if (!root || !canvas || !headline || !cta) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const maskCanvas = document.createElement("canvas");
    const mctx = maskCanvas.getContext("2d", { willReadFrequently: true });
    if (!mctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const rand = mulberry32(0x10de);
    let disposed = false;

    // -- token-derived ink: read at mount, re-derived live on theme flips ----
    // 16 alpha-bucketed rgba strings per group so the draw loop batches
    // strokes instead of setting per-filing styles
    const styleFg: string[] = new Array(16).fill("");
    const styleAmb: string[] = new Array(16).fill("");
    const styleAcc: string[] = new Array(16).fill("");
    const derive = () => {
      const cs = getComputedStyle(document.documentElement);
      const bg = parseColor(cs.getPropertyValue("--background")) ?? [10, 10, 10];
      const fg = parseColor(cs.getPropertyValue("--foreground")) ?? [237, 237, 237];
      const accent = parseColor(cs.getPropertyValue("--ns-accent")) ?? [0, 107, 255];
      const border = parseColor(cs.getPropertyValue("--border")) ?? [46, 46, 46];
      const muted = parseColor(cs.getPropertyValue("--ns-muted")) ?? [143, 143, 143];
      // ambient ink leans toward --border on light themes so sparse filings
      // stay whisper-quiet against white instead of reading as dust
      const lum = (0.2126 * bg[0] + 0.7152 * bg[1] + 0.0722 * bg[2]) / 255;
      const amb = lum < 0.5 ? mix(muted, border, 0.25) : mix(muted, border, 0.45);
      for (let l = 0; l < 16; l++) {
        const a = (l / 15).toFixed(3);
        styleFg[l] = `rgba(${fg[0]},${fg[1]},${fg[2]},${a})`;
        styleAmb[l] = `rgba(${amb[0]},${amb[1]},${amb[2]},${a})`;
        styleAcc[l] = `rgba(${accent[0]},${accent[1]},${accent[2]},${a})`;
      }
    };
    derive();

    // -- sizing: canvas is a replaced element — style.width/height set
    // explicitly from the measured rect, backing store scaled by dpr --------
    let w = 0;
    let h = 0;
    let dpr = 1;
    let sized = false;
    const resize = () => {
      const rect = root.getBoundingClientRect();
      if (rect.width < 2 || rect.height < 2) {
        sized = false; // zero-size guard — loop no-ops until real
        return;
      }
      w = rect.width;
      h = rect.height;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.style.width = `${w}px`;
      canvas.style.height = `${h}px`;
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
      sized = true;
    };

    // -- filing storage (structure-of-arrays, hot loop reads these only) ----
    let n = 0; // total filings
    let nMask = 0; // first nMask live inside the letter-mask
    let fx = new Float32Array(0);
    let fy = new Float32Array(0);
    let fa = new Float32Array(0); // current angle
    let flen = new Float32Array(0); // segment length 6–10px
    let fna = new Float32Array(0); // drift amplitude seed [-1,1] (value noise)
    let fph = new Float32Array(0); // drift phase seed
    let ex0 = new Float32Array(0); // per-frame segment endpoints
    let ey0 = new Float32Array(0);
    let ex1 = new Float32Array(0);
    let ey1 = new Float32Array(0);
    let bucket = new Uint8Array(0); // quantized alpha 0–15
    let group = new Uint8Array(0); // 0 = mask/fg, 1 = ambient, 2 = accent
    let faccent = new Uint8Array(0); // in the ~5% nearest the anchor pole
    let ax = 0; // anchor pole — offset from container origin, NEVER page coords
    let ay = 0;

    // letter-mask + rejection sampling. Rebuilt on ResizeObserver and after
    // webfonts finish loading (glyph metrics shift the mask).
    const buildField = () => {
      if (!sized) return;
      const rootRect = root.getBoundingClientRect();
      const mw = Math.max(1, Math.round(w));
      const mh = Math.max(1, Math.round(h));
      maskCanvas.width = mw;
      maskCanvas.height = mh;
      mctx.clearRect(0, 0, mw, mh);
      mctx.fillStyle = "#fff";

      // font shorthand read from the live DOM headline so canvas glyphs
      // match the crisp type above
      const hcs = getComputedStyle(headline);
      mctx.font = `${hcs.fontStyle} ${hcs.fontWeight} ${hcs.fontSize} ${hcs.fontFamily}`;
      if ("letterSpacing" in mctx) {
        (mctx as CanvasRenderingContext2D & { letterSpacing: string }).letterSpacing =
          hcs.letterSpacing === "normal" ? "0px" : hcs.letterSpacing;
      }
      mctx.textAlign = "left";
      mctx.textBaseline = "alphabetic";

      let minX = mw;
      let minY = mh;
      let maxX = 0;
      let maxY = 0;
      for (let li = 0; li < headlineLines.length; li++) {
        const span = lineRefs.current[li];
        const text = headlineLines[li];
        if (!span || !text) continue;
        const r = span.getBoundingClientRect();
        const relL = r.left - rootRect.left;
        const relT = r.top - rootRect.top;
        const m = mctx.measureText(text);
        // center glyphs on the span's line box, x-scale to its measured
        // width so the mask tracks the DOM rendering
        const glyphMid = (m.actualBoundingBoxAscent - m.actualBoundingBoxDescent) / 2;
        const sc = m.width > 1 ? r.width / m.width : 1;
        mctx.save();
        mctx.translate(relL, relT + r.height / 2 + glyphMid);
        mctx.scale(sc, 1);
        mctx.fillText(text, 0, 0);
        mctx.restore();
        minX = Math.min(minX, relL);
        minY = Math.min(minY, relT);
        maxX = Math.max(maxX, relL + r.width);
        maxY = Math.max(maxY, relT + r.height);
      }
      const data = mctx.getImageData(0, 0, mw, mh).data;
      const inMask = (x: number, y: number) => {
        const xi = x | 0;
        const yi = y | 0;
        if (xi < 0 || yi < 0 || xi >= mw || yi >= mh) return false;
        return (data[(yi * mw + xi) * 4 + 3] ?? 0) > 100;
      };

      // anchor pole = primary CTA center as an offset from the container
      const cr = cta.getBoundingClientRect();
      ax = cr.left - rootRect.left + cr.width / 2;
      ay = cr.top - rootRect.top + cr.height / 2;

      // halve counts on dense-DPR narrow viewports
      const small = dpr >= 2 && w < 900;
      const wantMask = Math.max(0, Math.round(small ? maskFilings / 2 : maskFilings));
      const wantAmb = Math.max(0, Math.round(small ? ambientFilings / 2 : ambientFilings));
      const cap = wantMask + wantAmb;
      fx = new Float32Array(cap);
      fy = new Float32Array(cap);
      fa = new Float32Array(cap);
      flen = new Float32Array(cap);
      fna = new Float32Array(cap);
      fph = new Float32Array(cap);
      ex0 = new Float32Array(cap);
      ey0 = new Float32Array(cap);
      ex1 = new Float32Array(cap);
      ey1 = new Float32Array(cap);
      bucket = new Uint8Array(cap);
      group = new Uint8Array(cap);
      faccent = new Uint8Array(cap);

      // rejection-sample dense filings inside the mask (bbox-bounded)
      const bx = Math.max(0, minX - 8);
      const by = Math.max(0, minY - 8);
      const bw = Math.max(1, Math.min(mw, maxX + 8) - bx);
      const bh = Math.max(1, Math.min(mh, maxY + 8) - by);
      let i = 0;
      let tries = 0;
      const maxTriesMask = wantMask * 80;
      while (i < wantMask && tries < maxTriesMask) {
        tries++;
        const x = bx + rand() * bw;
        const y = by + rand() * bh;
        if (!inMask(x, y)) continue;
        fx[i] = x;
        fy[i] = y;
        i++;
      }
      nMask = i;
      // sparse ambient filings anywhere outside the mask
      tries = 0;
      const maxTriesAmb = wantAmb * 20;
      let j = 0;
      while (j < wantAmb && tries < maxTriesAmb) {
        tries++;
        const x = rand() * w;
        const y = rand() * h;
        if (inMask(x, y)) continue;
        fx[i + j] = x;
        fy[i + j] = y;
        j++;
      }
      n = nMask + j;

      // per-filing constants: length, drift seeds, accent eligibility
      const dists = new Float32Array(n);
      for (let k = 0; k < n; k++) {
        flen[k] = 6 + rand() * 4;
        fna[k] = 2 * noise2((fx[k] ?? 0) * 0.012, (fy[k] ?? 0) * 0.012) - 1;
        fph[k] = noise2((fx[k] ?? 0) * 0.03 + 51.7, (fy[k] ?? 0) * 0.03) * Math.PI * 2;
        dists[k] = Math.hypot((fx[k] ?? 0) - ax, (fy[k] ?? 0) - ay);
      }
      // ~5% nearest the anchor pole may take --ns-accent while the CTA is hot
      const sorted = Array.from(dists).sort((a, b) => a - b);
      const thr = sorted[Math.floor(n * 0.05)] ?? 0;
      for (let k = 0; k < n; k++) faccent[k] = (dists[k] ?? 0) <= thr ? 1 : 0;
    };

    // -- pole state ----------------------------------------------------------
    const cursorT: Tween = { from: 0, to: 0, t0: 0, dur: 1, value: 0, active: false };
    const anchorT: Tween = { from: 0.7, to: 0.7, t0: 0, dur: 1, value: 0.7, active: false };
    let pcx = 0;
    let pcy = 0;
    let ctaHot = false; // accent gate — hover/focus only
    let lastMove = -1e9;

    // solve the dipole field into angles/endpoints/buckets for one frame.
    // k = angle chase gain this frame (1 - exp(-dt*10) → critically damped);
    // returns the max remaining per-filing angular delta (sleep signal).
    const solve = (
      nowS: number,
      cs: number,
      asV: number,
      driftAmp: number,
      k: number
    ) => {
      let maxD = 0;
      const osc = Math.PI * 2 * DRIFT_HZ * nowS;
      for (let i = 0; i < n; i++) {
        const x = fx[i] ?? 0;
        const y = fy[i] ?? 0;
        let vx = 0;
        let vy = 0;
        // anchor pole — pure radial
        {
          const dx = x - ax;
          const dy = y - ay;
          const r = Math.hypot(dx, dy) || 1;
          const rc = Math.max(POLE_RMIN, r);
          const s = asV / (rc * rc);
          vx += (s * dx) / r;
          vy += (s * dy) / r;
        }
        // cursor pole — radial + mild tangential swirl
        if (cs > 1e-4) {
          const dx = x - pcx;
          const dy = y - pcy;
          const r = Math.hypot(dx, dy) || 1;
          const rc = Math.max(POLE_RMIN, r);
          const s = cs / (rc * rc);
          const ux = dx / r;
          const uy = dy / r;
          vx += s * (ux * 0.85 - uy * 0.35);
          vy += s * (uy * 0.85 + ux * 0.35);
        }
        const mag = Math.hypot(vx, vy);
        let target = Math.atan2(vy, vx);
        if (driftAmp > 1e-4) {
          target += driftAmp * (fna[i] ?? 0) * Math.sin(osc + (fph[i] ?? 0));
        }
        // shortest-path wrap, then critically-damped chase — no overshoot
        let d = target - (fa[i] ?? 0);
        d = ((d + Math.PI) % (Math.PI * 2) + Math.PI * 2) % (Math.PI * 2) - Math.PI;
        const ad = Math.abs(d);
        if (ad > maxD) maxD = ad;
        const ang = (fa[i] ?? 0) + d * k;
        fa[i] = ang;
        const half = (flen[i] ?? 8) / 2;
        const c = Math.cos(ang);
        const sn = Math.sin(ang);
        ex0[i] = x - c * half;
        ey0[i] = y - sn * half;
        ex1[i] = x + c * half;
        ey1[i] = y + sn * half;
        // magnitude → ink: mask 0.25→0.9 in --foreground, ambient 0.06→0.18
        const nm = mag / (mag + MAG_SOFT);
        const alpha = i < nMask ? 0.25 + 0.65 * nm : 0.06 + 0.12 * nm;
        bucket[i] = Math.round(alpha * 15);
        group[i] = ctaHot && faccent[i] === 1 ? 2 : i < nMask ? 0 : 1;
      }
      return maxD;
    };

    const draw = () => {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h); // full clear + redraw — no alpha accumulation
      ctx.lineCap = "round";
      ctx.lineWidth = 1;
      const styles = [styleFg, styleAmb, styleAcc] as const;
      for (let g = 0; g < 3; g++) {
        const pal = styles[g]!;
        for (let l = 1; l < 16; l++) {
          let any = false;
          ctx.beginPath();
          for (let i = 0; i < n; i++) {
            if (group[i] !== g || bucket[i] !== l) continue;
            ctx.moveTo(ex0[i] ?? 0, ey0[i] ?? 0);
            ctx.lineTo(ex1[i] ?? 0, ey1[i] ?? 0);
            any = true;
          }
          if (any) {
            ctx.strokeStyle = pal[l] ?? "rgba(0,0,0,0)";
            ctx.stroke();
          }
        }
      }
    };

    // -- reduced motion: one static solved frame, anchor pole only ----------
    const renderStatic = () => {
      resize();
      if (!sized) return;
      buildField();
      solve(0, 0, 0.7, 0, 1); // k=1 snaps angles straight to target
      draw();
    };

    if (reduced) {
      renderStatic();
      const ro = new ResizeObserver(renderStatic);
      ro.observe(root);
      const mo = new MutationObserver(() => {
        derive();
        if (sized) draw(); // re-ink the solved frame for the new theme
      });
      mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });
      document.fonts.ready.then(() => {
        if (!disposed) renderStatic();
      });
      return () => {
        disposed = true;
        ro.disconnect();
        mo.disconnect();
      };
    }

    // -- animated path -------------------------------------------------------
    resize();
    buildField();
    solve(performance.now() / 1000, 0, 0.7, 0, 1); // settle initial pose

    let raf = 0;
    let last = 0;
    let visible = true;
    let wakeTimer = 0;

    const loop = (now: number) => {
      raf = 0;
      if (!visible || !sized) {
        last = 0;
        return; // paused offscreen / zero-size — observers wake us
      }
      const dt = last === 0 ? 1 / 60 : Math.min(0.05, (now - last) / 1000);
      last = now;
      tickTween(cursorT, now);
      tickTween(anchorT, now);

      // ambient drift breathes on a 12s cycle: ~8.6s of value-noise drift,
      // then a rest phase where the loop genuinely sleeps until the next
      // breath — ambient is the default look, sleep is still real
      const nowS = now / 1000;
      const ph = (nowS % BREATH_S) / BREATH_S;
      const env =
        ph < ACTIVE_FRAC ? Math.pow(Math.sin((Math.PI * ph) / ACTIVE_FRAC), 2) : 0;
      const idle = Math.min(1, Math.max(0, (now - lastMove - IDLE_MS) / 400));
      const driftAmp = DRIFT_AMP * env * idle;

      const k = 1 - Math.exp(-dt * 10);
      const maxD = solve(nowS, cursorT.value, anchorT.value, driftAmp, k);
      draw();

      // sleep: field settled AND no pole strength animating AND drift at
      // its rest phase — schedule the wake for the next breath
      if (maxD < SLEEP_EPS && !cursorT.active && !anchorT.active && ph >= ACTIVE_FRAC) {
        last = 0;
        window.clearTimeout(wakeTimer);
        wakeTimer = window.setTimeout(wake, (1 - ph) * BREATH_S * 1000 + 32);
        return; // raf stays 0 — genuinely asleep
      }
      raf = requestAnimationFrame(loop);
    };

    const wake = () => {
      if (!raf && visible) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    // -- pointer: cursor pole ------------------------------------------------
    const onMove = (e: PointerEvent) => {
      const rect = root.getBoundingClientRect();
      pcx = e.clientX - rect.left;
      pcy = e.clientY - rect.top;
      lastMove = performance.now();
      if (cursorT.to !== 1) retarget(cursorT, 1, 200, lastMove);
      wake();
    };
    const onLeave = () => {
      // cursor pole decays to 0 over 600ms (deadline-bounded tween)
      retarget(cursorT, 0, 600, performance.now());
      wake();
    };
    root.addEventListener("pointermove", onMove);
    root.addEventListener("pointerdown", onMove);
    root.addEventListener("pointerleave", onLeave);

    // -- CTA pole: hover/focus springs 0.7 → 1.4 over 250ms ease-out-expo ---
    const ctaOn = () => {
      ctaHot = true;
      retarget(anchorT, 1.4, 250, performance.now());
      wake();
    };
    const ctaOff = () => {
      ctaHot = false;
      retarget(anchorT, 0.7, 250, performance.now());
      wake();
    };
    cta.addEventListener("pointerenter", ctaOn);
    cta.addEventListener("pointerleave", ctaOff);
    cta.addEventListener("focus", ctaOn);
    cta.addEventListener("blur", ctaOff);

    // -- observers -----------------------------------------------------------
    const ro = new ResizeObserver(() => {
      resize();
      buildField(); // letter-mask resampled on resize
      solve(performance.now() / 1000, cursorT.value, anchorT.value, 0, 1);
      if (sized) draw();
      wake();
    });
    ro.observe(root);
    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible) wake();
    });
    io.observe(root);
    const mo = new MutationObserver(() => {
      derive(); // live theme re-derive — next frame re-inks every filing
      if (sized) draw();
      wake();
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });
    document.fonts.ready.then(() => {
      // webfont swap moves glyph outlines — rebuild the mask once settled
      if (disposed) return;
      resize();
      buildField();
      solve(performance.now() / 1000, cursorT.value, anchorT.value, 0, 1);
      if (sized) draw();
      wake();
    });

    wake();

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      raf = 0;
      window.clearTimeout(wakeTimer);
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      root.removeEventListener("pointermove", onMove);
      root.removeEventListener("pointerdown", onMove);
      root.removeEventListener("pointerleave", onLeave);
      cta.removeEventListener("pointerenter", ctaOn);
      cta.removeEventListener("pointerleave", ctaOff);
      cta.removeEventListener("focus", ctaOn);
      cta.removeEventListener("blur", ctaOff);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [linesKey, maskFilings, ambientFilings]);

  return (
    <section
      ref={rootRef}
      className={`relative isolate overflow-hidden bg-background ${className}`}
    >
      {/* filing field — pointer-events none, DOM copy above stays interactive */}
      <canvas
        ref={canvasRef}
        aria-hidden
        className="pointer-events-none absolute left-0 top-0"
      />
      <div className="relative z-10 mx-auto flex w-full max-w-5xl flex-col items-center px-6 pb-16 pt-24 text-center sm:pb-24 sm:pt-32">
        <p className="mb-6 font-mono text-[11px] tracking-widest text-ns-muted">
          {eyebrow}
        </p>
        <h1
          ref={headlineRef}
          className="font-semibold text-foreground"
          style={{
            fontSize: "clamp(2.5rem, 6.5vw, 4.5rem)",
            lineHeight: 1.06,
            letterSpacing: "-0.03em",
          }}
        >
          {headlineLines.map((line, i) => (
            <span
              key={i}
              ref={(el) => {
                lineRefs.current[i] = el;
              }}
              className="block"
            >
              {line}
            </span>
          ))}
        </h1>
        <p className="mt-6 max-w-xl text-base leading-relaxed text-ns-muted">
          {subcopy}
        </p>
        <div className="mt-9 flex flex-wrap items-center justify-center gap-3">
          <a
            ref={ctaRef}
            href={primaryCta.href}
            className="rounded-sm bg-ns-accent px-5 py-2.5 text-sm font-medium text-white transition-colors duration-200 hover:bg-ns-accent-hover focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
          >
            {primaryCta.label}
          </a>
          <a
            href={secondaryCta.href}
            className="rounded-sm border border-border px-5 py-2.5 text-sm font-medium text-ns-muted transition-colors duration-200 hover:border-foreground/20 hover:bg-surface hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
          >
            {secondaryCta.label}
          </a>
        </div>
        <div className="mt-16 grid w-full max-w-2xl grid-cols-1 divide-y divide-border border-y border-border sm:grid-cols-3 sm:divide-x sm:divide-y-0">
          {stats.slice(0, 3).map((s) => (
            <div key={s.label} className="flex flex-col items-center gap-1 px-6 py-4">
              <span className="font-mono text-lg text-foreground">{s.value}</span>
              <span className="font-mono text-[11px] tracking-widest text-ns-muted">
                {s.label.toUpperCase()}
              </span>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

"use client";

import { useEffect, useRef, type ReactNode } from "react";

// ---------------------------------------------------------------------------
// SolargraphHero — hero surface that behaves like a long-exposure photograph:
// cursor movement burns light streaks into offscreen accumulation buffers that
// are never cleared per frame, only decayed on a slow half-life, so the canvas
// builds a "light painting" of the whole session. Persistence, not live
// emission, is the differentiator. Buffers store pure intensity (white ink);
// theme tint is applied at composite time via a source-in pass, so a theme
// flip recolors the entire accumulated exposure instantly. Canvas 2D,
// refs-only hot path, sleeps when the pointer rests and residual energy
// decays under an epsilon.
// ---------------------------------------------------------------------------

type Vec3 = [number, number, number];

function parseColor(raw: string): Vec3 | null {
  const s = raw.trim();
  if (s.startsWith("#")) {
    const hex = s.slice(1);
    if (hex.length === 3) {
      const r = parseInt(hex.slice(0, 1) + hex.slice(0, 1), 16);
      const g = parseInt(hex.slice(1, 2) + hex.slice(1, 2), 16);
      const b = parseInt(hex.slice(2, 3) + hex.slice(2, 3), 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    if (hex.length >= 6) {
      const r = parseInt(hex.slice(0, 2), 16);
      const g = parseInt(hex.slice(2, 4), 16);
      const b = parseInt(hex.slice(4, 6), 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    return null;
  }
  const m = s.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
}

function mix(a: Vec3, b: Vec3, t: number): Vec3 {
  return [
    Math.round(a[0] + (b[0] - a[0]) * t),
    Math.round(a[1] + (b[1] - a[1]) * t),
    Math.round(a[2] + (b[2] - a[2]) * t),
  ];
}

function css(c: Vec3): string {
  return `rgb(${c[0]},${c[1]},${c[2]})`;
}

// deterministic prng — buffer picks + the seeded reduced-motion exposure
function mulberry32(a: number) {
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const SLEEP_MS = 500; // pointer-idle threshold before the loop may sleep
const ENERGY_EPS = 0.02; // residual-exposure floor — below this, sleep + wipe
const INTRO_MS = 2000; // scripted figure-eight duration on load
// decay is batched over this many seconds of real elapsed time before being
// applied to the buffers. Canvas alpha is an 8-bit channel — the per-frame
// erosion this represents (~0.3% of a stroke's alpha at 60fps) rounds away to
// nothing every single frame, so the buffer never visibly fades. Batching the
// same exponential math over a bigger dt removes enough alpha in one op to
// survive 8-bit rounding, with no change to the actual half-life curve since
// exp(-dt/tau) compounds identically whether applied in small or large steps.
const DECAY_STEP_S = 0.15;

export function SolargraphHero({
  children,
  halfLifeMs = 4000,
  maxStrokeAlpha = 0.35,
  intro = true,
  className = "",
}: {
  /** hero copy / CTAs — rendered above the canvas, fully interactive */
  children?: ReactNode;
  /** exposure decay half-life in ms */
  halfLifeMs?: number;
  /** per-stroke alpha ceiling; repeated passes asymptote instead of whiting out */
  maxStrokeAlpha?: number;
  /** scripted 2s figure-eight on load so the exposure shows before any input */
  intro?: boolean;
  /** extra classes merged onto the rendered root element */
  className?: string;
}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const vctx = canvas.getContext("2d");
    if (!vctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;
    const tau = Math.max(0.5, halfLifeMs / 1000 / Math.LN2); // ≈ 5.77s at 4s half-life
    const rand = mulberry32(0x50a7);

    // accumulation buffers — never cleared per frame. A holds ~60% of the
    // segments (primary tint), B the rest (secondary tint).
    const bufA = document.createElement("canvas");
    const bufB = document.createElement("canvas");
    const scratch = document.createElement("canvas");
    const actxA = bufA.getContext("2d");
    const actxB = bufB.getContext("2d");
    const sctx = scratch.getContext("2d");
    if (!actxA || !actxB || !sctx) return;

    // -- token-derived tints + blend mode: read at mount, re-derived live ----
    let tintA: Vec3 = [0, 107, 255];
    let tintB: Vec3 = [237, 237, 237];
    const derive = () => {
      const cs = getComputedStyle(document.documentElement);
      const bg = parseColor(cs.getPropertyValue("--background")) ?? [10, 10, 10];
      const fg = parseColor(cs.getPropertyValue("--foreground")) ?? [237, 237, 237];
      const accent = parseColor(cs.getPropertyValue("--ns-accent")) ?? [0, 107, 255];
      const border = parseColor(cs.getPropertyValue("--border")) ?? [46, 46, 46];
      const muted = parseColor(cs.getPropertyValue("--ns-muted")) ?? [143, 143, 143];
      const lum = (0.2126 * bg[0] + 0.7152 * bg[1] + 0.0722 * bg[2]) / 255;
      if (lum < 0.5) {
        // dark: trails lighten the surface — accent-led glow
        tintA = accent;
        tintB = fg;
        canvas.style.mixBlendMode = "screen";
      } else {
        // light: screen would vanish on white — flip to multiply with ink
        // derived from --ns-muted/--border so trails darken instead
        tintA = muted;
        tintB = mix(border, muted, 0.6);
        canvas.style.mixBlendMode = "multiply";
      }
    };
    derive();

    // -- sizing: DPR clamp 2, exposure preserved across resize via copy ------
    let w = 0;
    let h = 0;
    let dpr = 1;
    let W = 0; // device px
    let H = 0;
    let sized = false;
    const resize = () => {
      const rect = root.getBoundingClientRect();
      if (rect.width < 2 || rect.height < 2) {
        sized = false; // guard zero-size containers — loop no-ops until real
        return;
      }
      w = rect.width;
      h = rect.height;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      const nW = Math.max(1, Math.round(w * dpr));
      const nH = Math.max(1, Math.round(h * dpr));
      const pW = W;
      const pH = H;
      W = nW;
      H = nH;
      canvas.width = W;
      canvas.height = H;
      for (const [buf, ctx] of [
        [bufA, actxA],
        [bufB, actxB],
      ] as const) {
        // snapshot old exposure, resize (clears), paint it back scaled
        if (pW > 0 && pH > 0) {
          scratch.width = pW;
          scratch.height = pH;
          sctx.drawImage(buf, 0, 0);
        }
        buf.width = W;
        buf.height = H;
        if (pW > 0 && pH > 0) ctx.drawImage(scratch, 0, 0, W, H);
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      }
      scratch.width = W;
      scratch.height = H;
      sized = true;
    };
    resize();

    const clearBuffers = () => {
      for (const ctx of [actxA, actxB]) {
        ctx.save();
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, W, H);
        ctx.restore();
      }
    };

    // framerate-independent decay: destination-out black over the buffer
    const decay = (dt: number) => {
      const a = 1 - Math.exp(-dt / tau);
      for (const ctx of [actxA, actxB]) {
        ctx.save();
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.globalCompositeOperation = "destination-out";
        ctx.globalAlpha = a;
        ctx.fillStyle = "#000";
        ctx.fillRect(0, 0, W, H);
        ctx.restore();
      }
    };

    // one quadratic segment into a weighted-random buffer. White here is an
    // intensity mask, not ink — display color is applied at composite time.
    const strokeSeg = (
      x0: number,
      y0: number,
      cx: number,
      cy: number,
      x1: number,
      y1: number,
      width: number,
      alpha: number
    ) => {
      const ctx = rand() < 0.6 ? actxA : actxB;
      ctx.save();
      ctx.globalAlpha = alpha; // ceiling — repeated passes asymptote to 1
      ctx.strokeStyle = "#fff";
      ctx.shadowColor = "#fff";
      ctx.shadowBlur = 12;
      ctx.lineCap = "round";
      ctx.lineWidth = width;
      ctx.beginPath();
      ctx.moveTo(x0, y0);
      ctx.quadraticCurveTo(cx, cy, x1, y1);
      ctx.stroke();
      ctx.restore();
    };

    // tint each intensity buffer via source-in and stack onto the visible
    // canvas — this IS the recolor pass, so theme flips re-tint the whole
    // accumulated exposure on the very next composite
    const composite = () => {
      if (!sized) return;
      vctx.setTransform(1, 0, 0, 1, 0, 0);
      vctx.clearRect(0, 0, W, H);
      const pairs = [
        [bufA, tintA],
        [bufB, tintB],
      ] as const;
      for (let i = 0; i < 2; i++) {
        const [buf, tint] = pairs[i]!;
        sctx.globalCompositeOperation = "source-over";
        sctx.clearRect(0, 0, W, H);
        sctx.drawImage(buf, 0, 0);
        sctx.globalCompositeOperation = "source-in";
        sctx.fillStyle = css(tint);
        sctx.fillRect(0, 0, W, H);
        vctx.globalCompositeOperation = i === 0 ? "source-over" : "lighter";
        vctx.drawImage(scratch, 0, 0);
      }
      vctx.globalCompositeOperation = "source-over";
    };

    // -- reduced motion: one seeded synthetic exposure, no loop --------------
    const renderStatic = () => {
      if (!sized) return;
      clearBuffers();
      const srand = mulberry32(0x5017);
      const steps = 150;
      let p2x = 0;
      let p2y = 0;
      let px = 0;
      let py = 0;
      for (let i = 0; i <= steps; i++) {
        const th = (i / steps) * Math.PI * 2;
        const x = w / 2 + w * 0.3 * Math.sin(th) + (srand() - 0.5) * 5;
        const y = h / 2 + h * 0.2 * Math.sin(th * 2) + (srand() - 0.5) * 5;
        if (i > 1) {
          strokeSeg(
            (p2x + px) / 2,
            (p2y + py) / 2,
            px,
            py,
            (px + x) / 2,
            (py + y) / 2,
            1.5 + srand(),
            0.14
          );
        }
        p2x = px;
        p2y = py;
        px = x;
        py = y;
      }
      composite();
    };

    if (reduced) {
      renderStatic();
      const ro = new ResizeObserver(() => {
        resize();
        renderStatic();
      });
      ro.observe(root);
      const mo = new MutationObserver(() => {
        derive();
        renderStatic(); // recolor the static exposure for the new theme
      });
      mo.observe(document.documentElement, {
        attributes: true,
        attributeFilter: ["class"],
      });
      return () => {
        ro.disconnect();
        mo.disconnect();
      };
    }

    // -- hot-path state: locals only, never React state ----------------------
    let raf = 0;
    let last = 0;
    let visible = true;
    let tx = 0; // raw pointer target
    let ty = 0;
    let sx = 0; // smoothed pointer sample
    let sy = 0;
    let px = 0; // previous smoothed sample (control point)
    let py = 0;
    let p2x = 0; // sample before that (segment start midpoint)
    let p2y = 0;
    let hasChain = false;
    let lastMove = -1e9;
    let energy = 0; // running sum of recent stroke alpha, decays with tau
    let introActive = intro;
    let introT0 = -1;
    let decayAccum = 0; // real seconds of decay owed to the buffers, batched

    const loop = (now: number) => {
      raf = 0;
      if (!visible) {
        last = 0;
        return; // paused offscreen — IntersectionObserver wakes us
      }
      if (!sized) {
        last = 0;
        return; // zero-size container — ResizeObserver wakes us when real
      }
      const dt = last === 0 ? 1 / 60 : Math.min(0.05, (now - last) / 1000);
      last = now;

      // scripted figure-eight until it ends or a real pointer takes over
      if (introActive) {
        if (introT0 < 0) introT0 = now;
        const t = (now - introT0) / INTRO_MS;
        if (t >= 1) {
          introActive = false;
          hasChain = false;
        } else {
          const th = t * Math.PI * 2;
          tx = w / 2 + w * 0.3 * Math.sin(th);
          ty = h / 2 + h * 0.2 * Math.sin(th * 2);
          if (!hasChain) {
            sx = px = p2x = tx;
            sy = py = p2y = ty;
            hasChain = true;
          }
          lastMove = now;
        }
      }

      // batch the destination-out erosion — see DECAY_STEP_S above
      decayAccum += dt;
      if (decayAccum >= DECAY_STEP_S) {
        decay(decayAccum);
        decayAccum = 0;
      }
      energy *= Math.exp(-dt / tau);

      if (hasChain) {
        // chase the raw pointer so segments are smoothed, not jittery
        const k = 1 - Math.exp(-dt * 18);
        sx += (tx - sx) * k;
        sy += (ty - sy) * k;
        const dist = Math.hypot(sx - px, sy - py);
        if (dist > 0.75) {
          const speed = dist / dt;
          const lw = 1.5 + Math.min(1.5, Math.max(0, speed / 1200));
          strokeSeg(
            (p2x + px) / 2,
            (p2y + py) / 2,
            px,
            py,
            (px + sx) / 2,
            (py + sy) / 2,
            lw,
            maxStrokeAlpha
          );
          energy = Math.min(4, energy + maxStrokeAlpha);
          p2x = px;
          p2y = py;
          px = sx;
          py = sy;
        }
      }

      composite();

      // sleep: pointer idle past threshold AND residual exposure spent
      if (now - lastMove > SLEEP_MS && energy < ENERGY_EPS) {
        clearBuffers(); // wipe the invisible residue so wake starts clean
        composite();
        energy = 0;
        decayAccum = 0;
        last = 0;
        return; // raf stays 0 — genuinely asleep
      }
      raf = requestAnimationFrame(loop);
    };

    const wake = () => {
      if (!raf) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const onMove = (e: PointerEvent) => {
      const rect = root.getBoundingClientRect();
      tx = e.clientX - rect.left;
      ty = e.clientY - rect.top;
      introActive = false; // a real cursor takes over the exposure
      if (!hasChain) {
        sx = px = p2x = tx;
        sy = py = p2y = ty;
        hasChain = true;
      }
      lastMove = performance.now();
      wake();
    };
    const onLeave = () => {
      hasChain = false; // break the chain — no streak to the re-entry point
    };

    // -- observers ------------------------------------------------------------
    const ro = new ResizeObserver(() => {
      resize();
      composite();
      wake();
    });
    ro.observe(root);
    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible) wake();
    });
    io.observe(root);
    // live theme re-derive: watch documentElement class flips; the next
    // composite re-tints the accumulated buffer via the source-in pass
    const mo = new MutationObserver(() => {
      derive();
      composite();
      wake();
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });
    const onVis = () => {
      if (!document.hidden) wake();
    };
    document.addEventListener("visibilitychange", onVis);

    root.addEventListener("pointermove", onMove);
    root.addEventListener("pointerdown", onMove);
    root.addEventListener("pointerleave", onLeave);
    if (intro) wake();

    return () => {
      cancelAnimationFrame(raf);
      raf = 0;
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", onVis);
      root.removeEventListener("pointermove", onMove);
      root.removeEventListener("pointerdown", onMove);
      root.removeEventListener("pointerleave", onLeave);
    };
  }, [halfLifeMs, maxStrokeAlpha, intro]);

  return (
    <div
      ref={rootRef}
      className={`relative isolate overflow-hidden ${className}`}
    >
      {/* exposure layer: pointer-events none — CTAs above stay clickable */}
      <canvas
        ref={canvasRef}
        aria-hidden
        className="pointer-events-none absolute inset-0 h-full w-full"
      />
      <div className="relative">{children}</div>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState, type RefObject } from "react";
import { Canvas, useFrame, useThree } from "@react-three/fiber";
import * as THREE from "three";
import { motion, useReducedMotion, type Variants } from "motion/react";

const COUNT = 6000;
const FIELD = { w: 22, h: 12 };
// repulsion radius in screen pixels; converted to world units per-frame
// since world-units-per-pixel changes with viewport size
const CURSOR_RADIUS_PX = 170;
// peak outward displacement as a fraction of the radius
const PUSH = 0.62;
// resting cursor position, far outside the field — falloff is 0 here, so
// easing back toward it lets every dot relax to its home position
const REST = new THREE.Vector2(999, 999);
// exponential ease factor for the cursor uniform: low enough that dots trail
// the pointer and spring back rather than snapping
const EASE = 0.09;

// All particle motion lives in the vertex shader — zero per-particle CPU work.
// JS only eases the cursor uniform each frame so the repulsion trails smoothly,
// and re-derives uColor from CSS tokens on theme change.
const vertexShader = /* glsl */ `
  uniform float uTime;
  uniform vec2 uCursor;
  uniform float uRadius;
  uniform float uPush;
  attribute float aSeed;
  void main() {
    vec3 p = position;
    // ambient drift — two desynced sines per dot
    p.x += sin(uTime * 0.4 + aSeed) * 0.3;
    p.y += cos(uTime * 0.32 + aSeed * 1.7) * 0.3;
    // reversed-polarity magnet: displace outward along (dot - cursor),
    // strongest at the pointer, decaying smoothly to zero at uRadius
    vec2 d = p.xy - uCursor;
    float dist = length(d);
    float falloff = 1.0 - smoothstep(0.0, uRadius, dist);
    // ease-out shaping so the shove is soft at the rim and firm at the core
    falloff = falloff * falloff * (3.0 - 2.0 * falloff);
    vec2 dir = dist > 0.0001 ? d / dist : vec2(0.0);
    p.xy += dir * falloff * uRadius * uPush;
    vec4 mv = modelViewMatrix * vec4(p, 1.0);
    gl_PointSize = 42.0 / -mv.z;
    gl_Position = projectionMatrix * mv;
  }
`;

const fragmentShader = /* glsl */ `
  uniform vec3 uColor;
  void main() {
    float d = length(gl_PointCoord - 0.5);
    float alpha = smoothstep(0.5, 0.15, d) * 0.55;
    if (alpha < 0.01) discard;
    gl_FragColor = vec4(uColor, alpha);
  }
`;

// #rrggbb / #rgb -> 0-1 float triple; falls back to muted gray on parse miss
function parseColor(hex: string): [number, number, number] | null {
  const s = hex.trim();
  const m = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(s);
  if (!m) return null;
  let h = m[1];
  if (h.length === 3) h = h.split("").map((c) => c + c).join("");
  const n = parseInt(h, 16);
  return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

function Particles({ still, visible }: { still: boolean; visible: RefObject<boolean> }) {
  const material = useRef<THREE.ShaderMaterial>(null);
  const pointerInside = useRef(false);
  // scratch vector for the per-frame ease target — avoids an allocation on
  // every frame the pointer is inside the canvas
  const target = useRef(new THREE.Vector2());
  const { viewport, pointer, size, gl } = useThree();

  const { positions, seeds } = useMemo(() => {
    const positions = new Float32Array(COUNT * 3);
    const seeds = new Float32Array(COUNT);
    for (let i = 0; i < COUNT; i++) {
      positions[i * 3] = (Math.random() - 0.5) * FIELD.w;
      positions[i * 3 + 1] = (Math.random() - 0.5) * FIELD.h;
      positions[i * 3 + 2] = 0;
      seeds[i] = Math.random() * Math.PI * 2;
    }
    return { positions, seeds };
  }, []);

  const uniforms = useMemo(
    () => ({
      uTime: { value: 0 },
      uCursor: { value: REST.clone() },
      uRadius: { value: 1 },
      uPush: { value: 0 },
      uColor: { value: new THREE.Vector3(0.561, 0.561, 0.561) },
    }),
    []
  );

  // track pointer enter/leave on the canvas element directly — pointer.x/y
  // from useThree freezes at the last in-bounds sample on leave, so without
  // this the cursor uniform would never ease back to rest
  useEffect(() => {
    const el = gl.domElement;
    const enter = () => (pointerInside.current = true);
    const leave = () => (pointerInside.current = false);
    el.addEventListener("pointerenter", enter);
    el.addEventListener("pointerleave", leave);
    return () => {
      el.removeEventListener("pointerenter", enter);
      el.removeEventListener("pointerleave", leave);
    };
  }, [gl]);

  // derive dot color from CSS tokens at mount, and again whenever the theme
  // class flips — mirrors the pattern used by other canvas components in
  // this registry (e.g. hero-long-exposure)
  useEffect(() => {
    const derive = () => {
      const u = material.current?.uniforms;
      if (!u) return;
      const cs = getComputedStyle(document.documentElement);
      const base = parseColor(cs.getPropertyValue("--ns-muted")) ?? [0.561, 0.561, 0.561];
      (u.uColor.value as THREE.Vector3).set(...base);
    };
    derive();
    const mo = new MutationObserver(derive);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });
    return () => mo.disconnect();
  }, []);

  useFrame(({ clock }) => {
    if (!material.current || !visible.current) return; // paused while scrolled offscreen
    const u = material.current.uniforms;
    // radius is defined in screen pixels; convert using this frame's
    // world-units-per-pixel so the void stays ~170px regardless of
    // viewport size or DPR
    u.uRadius.value = (CURSOR_RADIUS_PX * viewport.width) / size.width;
    if (still) return; // reduced motion: freeze drift and repulsion
    u.uTime.value = clock.elapsedTime;

    const inside = pointerInside.current;
    const t = target.current;
    if (inside) t.set((pointer.x * viewport.width) / 2, (pointer.y * viewport.height) / 2);
    else t.copy(REST);
    // exponential ease toward target — dots swell outward as the pointer
    // approaches and relax home behind it
    const c = u.uCursor.value as THREE.Vector2;
    c.x += (t.x - c.x) * EASE;
    c.y += (t.y - c.y) * EASE;
    // fade the push in on enter / out on leave so nothing pops
    const p = u.uPush as { value: number };
    p.value += ((inside ? PUSH : 0) - p.value) * EASE;
  });

  return (
    <points>
      <bufferGeometry>
        <bufferAttribute attach="attributes-position" args={[positions, 3]} />
        <bufferAttribute attach="attributes-aSeed" args={[seeds, 1]} />
      </bufferGeometry>
      <shaderMaterial
        ref={material}
        vertexShader={vertexShader}
        fragmentShader={fragmentShader}
        uniforms={uniforms}
        transparent
        depthWrite={false}
      />
    </points>
  );
}

// Memoised per document, and the probe context is handed straight back.
// Browsers cap live WebGL contexts per renderer process (~16 in Chrome), and a
// dropped canvas holds its context until GC gets round to it — so probing on
// every mount spent budget on feature detection alone, and once the cap is hit
// the browser kills the OLDEST contexts, i.e. the demos being looked at.
let webglSupport: boolean | null = null;
function detectWebGL() {
  if (webglSupport !== null) return webglSupport;
  const canvas = document.createElement("canvas");
  const gl = canvas.getContext("webgl2") || canvas.getContext("webgl");
  webglSupport = !!gl;
  gl?.getExtension("WEBGL_lose_context")?.loseContext();
  return webglSupport;
}

function useWebGLSupport() {
  const [supported, setSupported] = useState(true);
  useEffect(() => {
    setSupported(detectWebGL());
  }, []);
  return supported;
}

const reveal: Variants = {
  hidden: { opacity: 0, y: 24, filter: "blur(8px)" },
  show: (i: number) => ({
    opacity: 1,
    y: 0,
    filter: "blur(0px)",
    transition: { delay: 0.15 + i * 0.12, type: "spring", stiffness: 90, damping: 16 },
  }),
};

const ctaClasses =
  "inline-flex items-center justify-center rounded-sm bg-ns-accent px-5 py-2.5 text-sm font-medium text-white transition-colors duration-150 hover:bg-ns-accent-hover focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent";

const revealProps = (reduced: boolean, i: number) =>
  ({ variants: reveal, initial: reduced ? false : "hidden", animate: "show", custom: i }) as const;

export function ParticleHero({
  eyebrow = "ns-ui",
  headline = "Interfaces with gravity.",
  subline = "A registry of components built one at a time, each earning its place.",
  cta = "Browse components",
  ctaHref,
  onCtaClick,
}: {
  /** mono eyebrow label above the headline */
  eyebrow?: string;
  /** main hero heading */
  headline?: string;
  /** supporting copy under the headline */
  subline?: string;
  /** CTA button/link text */
  cta?: string;
  /** renders the CTA as an `<a href>` instead of a `<button>` */
