  {
    id: "europe",
    label: "Europe",
    cities: [
      "Amsterdam", "Athens", "Belgrade", "Berlin", "Brussels", "Bucharest",
      "Budapest", "Copenhagen", "Dublin", "Helsinki", "Kyiv", "Lisbon",
      "London", "Madrid", "Moscow", "Oslo", "Paris", "Prague", "Rome",
