const DEFAULT_GROUPS: ShingleCourseGroup[] = REGION_DATA.map((r) => ({
  id: r.id,
  label: r.label,
  options: r.cities.map((city) => ({
    value: `${r.id}-${slugify(city)}`,
    label: city,
  })),
}));

interface FlatOption {
  gi: number;
  oi: number;
  opt: ShingleCourseOption;
}

export function ShingleCourse({
  groups = DEFAULT_GROUPS,
  value,
  defaultValue = "",
  onValueChange,
  label = "Timezone",
  disabled = false,
  name,
  className = "",
}: {
  /** grouped options, rendered under sticky group headers */
  groups?: ShingleCourseGroup[];
  /** controlled value; omit for uncontrolled */
  value?: string;
  /** uncontrolled initial value */
  defaultValue?: string;
  /** called with the new value when a different option is selected */
  onValueChange?: (value: string) => void;
  /** field label rendered above the listbox */
  label?: string;
  /** blocks the listbox */
  disabled?: boolean;
  /** when set, renders a hidden input for form posts */
  name?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}) {
  const uid = useId();
  const labelId = `${uid}-label`;
  const listboxId = `${uid}-listbox`;
  const headerId = (gi: number) => `${uid}-hdr-${gi}`;
  const optId = (gi: number, oi: number) => `${uid}-opt-${gi}-${oi}`;

  const listRef = useRef<HTMLUListElement>(null);
  const sentinelRefs = useRef<Map<number, HTMLDivElement>>(new Map());
  const scrollCancelRef = useRef<() => void>(() => {});
  const typeRef = useRef<{ buf: string; timer: number }>({ buf: "", timer: 0 });

  const isControlled = value !== undefined;
  const [internal, setInternal] = useState(defaultValue);
  const val = isControlled ? value : internal;

  const flat = useMemo<FlatOption[]>(() => {
    const arr: FlatOption[] = [];
    groups.forEach((g, gi) => {
      g.options.forEach((opt, oi) => arr.push({ gi, oi, opt }));
    });
    return arr;
  }, [groups]);

  const groupStart = useMemo(() => {
    const starts: number[] = [];
    let acc = 0;
    for (const g of groups) {
      starts.push(acc);
      acc += g.options.length;
    }
    return starts;
  }, [groups]);

  const firstEnabledFlat = () => flat.findIndex((f) => !f.opt.disabled);
  const lastEnabledFlat = () => {
    for (let i = flat.length - 1; i >= 0; i--) {
      if (!flat[i]?.opt.disabled) return i;
    }
    return -1;
  };

  const [activeFlat, setActiveFlat] = useState(() => {
    const sel = flat.findIndex((f) => f.opt.value === val && !f.opt.disabled);
    return sel >= 0 ? sel : firstEnabledFlat();
  });

  // which group indices are currently covered by the one after them —
  // detected via IntersectionObserver, never derived from scrollTop math
  const [arrived, setArrived] = useState<Set<number>>(() => new Set());
  const isShingled = (gi: number) => arrived.has(gi + 1);

  // -- shingle detection: one sentinel + observer per group -----------------
  useEffect(() => {
    const root = listRef.current;
    if (!root) return;
    const observers: IntersectionObserver[] = [];
    groups.forEach((_, gi) => {
      const sentinel = sentinelRefs.current.get(gi);
      if (!sentinel) return;
      const top = gi * HEADER_STEP;
      const io = new IntersectionObserver(
        (entries) => {
          const entry = entries[0];
          if (!entry || !entry.rootBounds) return;
          const passed =
            !entry.isIntersecting &&
            entry.boundingClientRect.top < entry.rootBounds.top;
          setArrived((prev) => {
            const has = prev.has(gi);
            if (passed === has) return prev;
            const next = new Set(prev);
            if (passed) next.add(gi);
            else next.delete(gi);
            return next;
          });
        },
        { root, rootMargin: `-${top + 1}px 0px 0px 0px`, threshold: 0 }
      );
      io.observe(sentinel);
      observers.push(io);
    });
    return () => observers.forEach((io) => io.disconnect());
  }, [groups]);

  useEffect(() => {
    if (activeFlat < 0) return;
    const f = flat[activeFlat];
    if (!f) return;
    const el = document.getElementById(optId(f.gi, f.oi));
    el?.scrollIntoView({ block: "nearest" });
  }, [activeFlat]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    const t = typeRef.current;
    return () => window.clearTimeout(t.timer);
  }, []);

  useEffect(() => {
    return () => scrollCancelRef.current();
  }, []);

  // -- scroll-to-top on shingle click: ease-out-expo, skipped under
  // prefers-reduced-motion (jumps straight to target) ------------------------
  const scrollGroupToTop = (gi: number) => {
    const listEl = listRef.current;
    // anchor on the SENTINEL, not the header: once a header is stuck, its
    // own getBoundingClientRect reflects the current stuck screen position
    // rather than its natural document-flow position, so measuring from the
    // header itself makes this cancel out to a no-op for exactly the
    // headers a user is most likely to click (ones already pinned in the
    // shingle trail). The sentinel is a plain, never-sticky 1px marker at
    // the exact start of the group, so its rect is trustworthy regardless
    // of any header's stuck state.
    const sentinel = sentinelRefs.current.get(gi);
    if (!listEl || !sentinel) return;
    const listRect = listEl.getBoundingClientRect();
    const sentinelRect = sentinel.getBoundingClientRect();
    const naturalTop = sentinelRect.top - listRect.top + listEl.scrollTop;
    const target = Math.max(0, naturalTop - gi * HEADER_STEP);

    scrollCancelRef.current();
    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;
    const start = listEl.scrollTop;
    const delta = target - start;
    if (reduced || Math.abs(delta) < 1) {
      listEl.scrollTop = target;
      return;
    }
    const t0 = performance.now();
    let raf = 0;
    const step = (now: number) => {
      const t = Math.min(1, (now - t0) / SCROLL_MS);
      listEl.scrollTop = start + delta * easeOutExpo(t);
      if (t < 1) raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    scrollCancelRef.current = () => cancelAnimationFrame(raf);
  };

  // -- selection --------------------------------------------------------------
  const commit = (fi: number) => {
    const f = flat[fi];
    if (!f || f.opt.disabled) return;
    if (!isControlled) setInternal(f.opt.value);
    onValueChange?.(f.opt.value);
  };

  const typeahead = (ch: string) => {
    const t = typeRef.current;
    t.buf += ch.toLowerCase();
    window.clearTimeout(t.timer);
    t.timer = window.setTimeout(() => {
      t.buf = "";
    }, TYPEAHEAD_MS);
    const n = flat.length;
    if (n === 0) return;
    const start = activeFlat >= 0 ? activeFlat : 0;
    const offset = t.buf.length > 1 ? 0 : 1;
    for (let k = 0; k < n; k++) {
      const i = (start + offset + k) % n;
      const f = flat[i];
      if (f && !f.opt.disabled && f.opt.label.toLowerCase().startsWith(t.buf)) {
        setActiveFlat(i);
        return;
      }
    }
  };

  const step = (from: number, dir: 1 | -1, count = 1) => {
    let i = from;
    let moves = 0;
    let candidate = from;
    while (moves < count) {
      let next = i;
      let found = false;
      for (let k = 0; k < flat.length; k++) {
        next += dir;
        if (next < 0 || next >= flat.length) break;
        if (!flat[next]?.opt.disabled) {
          found = true;
          break;
        }
      }
      if (!found) break;
      i = next;
      candidate = i;
      moves++;
    }
    return candidate;
  };

  const onListKeyDown = (e: React.KeyboardEvent) => {
    if (disabled) return;
    const key = e.key;
    if (key === "ArrowDown") {
      e.preventDefault();
      setActiveFlat((a) => step(a, 1));
    } else if (key === "ArrowUp") {
      e.preventDefault();
      setActiveFlat((a) => step(a, -1));
    } else if (key === "PageDown") {
      e.preventDefault();
      setActiveFlat((a) => step(a, 1, PAGE_SIZE));
    } else if (key === "PageUp") {
      e.preventDefault();
      setActiveFlat((a) => step(a, -1, PAGE_SIZE));
    } else if (key === "Home") {
      e.preventDefault();
      const i = firstEnabledFlat();
      if (i >= 0) setActiveFlat(i);
    } else if (key === "End") {
      e.preventDefault();
      const i = lastEnabledFlat();
      if (i >= 0) setActiveFlat(i);
    } else if (key === "Enter" || (key === " " && typeRef.current.buf === "")) {
      e.preventDefault();
      commit(activeFlat);
    } else if (key.length === 1 && !e.altKey && !e.ctrlKey && !e.metaKey) {
      e.preventDefault();
      typeahead(key);
    }
  };

  return (
    <div className={className}>
      <span
        id={labelId}
        className="mb-1.5 block font-mono text-xs uppercase tracking-[0.14em] text-ns-muted"
      >
        {label}
      </span>
      {name ? <input type="hidden" name={name} value={val} /> : null}

      <ul
        ref={listRef}
        id={listboxId}
        role="listbox"
        tabIndex={disabled ? -1 : 0}
        aria-labelledby={labelId}
        aria-disabled={disabled || undefined}
        aria-activedescendant={
          !disabled && activeFlat >= 0
            ? (() => {
                const f = flat[activeFlat];
                return f ? optId(f.gi, f.oi) : undefined;
              })()
            : undefined
        }
        onKeyDown={onListKeyDown}
        className={`relative max-h-[420px] overflow-y-auto overscroll-contain rounded-md border border-border bg-background outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ns-accent ${
          disabled ? "pointer-events-none opacity-50" : ""
        }`}
      >
        {groups.map((g, gi) => {
          const shingled = isShingled(gi);
          return (
            // display:contents — the group <li> must NOT generate its own box.
            // A sticky element's containing block is its nearest box-generating
            // ancestor; if that were this per-group <li>, header gi would be
            // released the moment group gi's own rows scroll out, and the
            // shingle trail could never accumulate past the current group. With
            // the box suppressed, every header's containing block is the shared
            // <ul role="listbox"> itself, so passed headers stay pinned (and
            // stacked, painted in DOM order) for the life of the whole scroll.
            <li
              key={g.id}
              role="group"
              aria-labelledby={headerId(gi)}
              className="contents"
            >
              <div
                ref={(el) => {
                  if (el) sentinelRefs.current.set(gi, el);
                  else sentinelRefs.current.delete(gi);
                }}
                aria-hidden
                style={{ height: 1 }}
              />
              <button
                type="button"
                disabled={disabled}
                onClick={() => scrollGroupToTop(gi)}
                aria-label={`Jump to ${g.label}`}
                style={{ top: gi * HEADER_STEP, zIndex: gi + 1 }}
                className={`sticky flex h-9 w-full items-center justify-between gap-3 border-border bg-background px-3 text-left outline-none transition-[color,background-color,font-size,letter-spacing,padding] duration-200 enabled:hover:bg-surface focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-inset disabled:cursor-not-allowed motion-reduce:transition-none ${
                  shingled
                    ? "border-b text-[11px] font-medium uppercase tracking-[0.08em] text-ns-muted"
                    : "text-xs font-semibold text-foreground"
                }`}
              >
                <span id={headerId(gi)} className="truncate">
                  {g.label}
                </span>
                <span
                  aria-hidden
                  className="shrink-0 font-mono text-[10px] text-ns-muted"
                >
                  {g.options.length}
                </span>
              </button>

              <ul role="presentation" className="py-1">
                {g.options.map((opt, oi) => {
                  const fi = groupStart[gi]! + oi;
                  const isActive = fi === activeFlat;
                  const isSelected = opt.value === val;
                  return (
                    <li
                      key={opt.value}
                      id={optId(gi, oi)}
                      role="option"
                      aria-selected={isSelected}
                      aria-disabled={opt.disabled || undefined}
                      onPointerMove={() => {
                        if (!opt.disabled && !disabled && fi !== activeFlat) {
                          setActiveFlat(fi);
                        }
                      }}
                      onPointerDown={(e) => e.preventDefault()}
                      onClick={() => {
                        if (!disabled && !opt.disabled) commit(fi);
                      }}
                      className={`flex items-center justify-between gap-3 px-3 py-1.5 text-sm transition-colors duration-100 motion-reduce:transition-none ${
                        opt.disabled
                          ? "cursor-not-allowed text-ns-muted/60"
                          : isActive
                            ? "cursor-pointer bg-foreground/[0.07] text-foreground"
                            : "cursor-pointer text-foreground/85"
                      }`}
                    >
                      <span className="truncate">{opt.label}</span>
                      {isSelected ? (
                        <svg
                          aria-hidden
                          viewBox="0 0 16 16"
                          fill="none"
                          className="h-4 w-4 shrink-0 text-ns-accent"
                        >
                          <path
                            d="M3.5 8.5l3 3 6-6.5"
                            stroke="currentColor"
                            strokeWidth="1.5"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                          />
                        </svg>
                      ) : null}
                    </li>
                  );
                })}
              </ul>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

"use client";

// LoaderAsciiDiffuseFill — an indeterminate loader whose ASCII texture comes
// from real Floyd-Steinberg SERPENTINE error diffusion, not a fixed
// ordered-dither threshold matrix. The registry already ships an
// ordered-dither family (chart-bar-dither, chart-line-dither,
// chart-radar-dither, masonry-ascii-settle, background-ascii-dither) —
// every one of those quantizes a value by comparing it against a repeating
// 4x4 Bayer matrix, a fixed spatial pattern whose outcome at a cell never
// depends on its neighbours. This component is the family's
// PROPAGATED-ERROR member: each cell's quantization error (its true
// continuous value minus the nearest of the 10 ramp levels) is diffused
// into unprocessed neighbours with the canonical Floyd-Steinberg kernel —
// 7/16 forward, 3/16 down-behind, 5/16 down, 1/16 down-ahead — and the scan
// direction alternates every row (serpentine) so the propagation itself
// alternates instead of compounding one directional streak. That
// cell-to-cell coupling is what gives real error diffusion its signature:
// directional, frame-coherent artifact drift, categorically different from
// a repeating threshold tile. It's a real, citable distinction in
// dithering literature (ordered/Bayer vs. error-diffusion/Floyd-Steinberg),
// not a restyle of the existing family.
//
// The "fill" is a soft boundary sweeping continuously across the grid,
// cyclic and never pointer-gated: it wraps and re-enters from the left
// forever, because this is an indeterminate loader, not a completion bar.
// A low-amplitude flowing noise field is summed into every cell's value
// BEFORE quantization, so the diffusion pattern itself drifts frame to
// frame — not just the boundary's position — and both the filled and
// unfilled regions keep visible grain rather than settling flat. The full
// 2D value field is rebuilt and re-diffused from scratch every frame; there
// is no dither state carried over between frames, matching how the
// algorithm actually works on a value field rather than accumulating a
// trail.

import { useEffect, useLayoutEffect, useRef } from "react";

const RAMP = " .:-=+*#%@";
const LEVELS = RAMP.length; // 10 quantization levels

// canonical Floyd-Steinberg coefficients, out of 16
const FS_FWD = 7 / 16;
const FS_DL = 3 / 16;
const FS_D = 5 / 16;
const FS_DR = 1 / 16;

const SWEEP_SPEED = 5.2; // cols/sec the fill boundary advances
const BAND = 3; // soft-edge half-width, in cells, either side of the boundary
const MIN_CELLS_SHORT = 11; // cells guaranteed across the container's shorter dimension
const MIN_CELL_PX = 6;
const MAX_CELL_PX = 15;
// reduced-motion freeze: boundary parked ~46% across (mid-fill, so filled
// ink, unfilled paper AND the diffusion turbulence at the seam are all on
// screen at once) at a fixed nonzero time phase, so the noise term isn't
// sitting on the degenerate all-zero frame every sine in flow() shares at t=0
const STATIC_FRONT_FRAC = 0.46;
const STATIC_T = 3.7;

interface Tokens {
  fg: string;
}

function readTokens(): Tokens {
  const cs = getComputedStyle(document.documentElement);
  // no fallback literal: an empty read means "don't know the ink colour
  // yet" and the paint path below guards on that rather than defaulting to
  // a hardcoded value that could bake in the wrong theme's polarity
  return { fg: cs.getPropertyValue("--foreground").trim() };
}

// cheap flowing value-noise: three summed sines at different rates/scales,
// normalized to 0..1 — same family as background-ascii-dither's noise(),
// just fewer octaves since this only needs to nudge the field, not carry it
function flow(x: number, y: number, t: number): number {
  const v = Math.sin(x * 0.6 + t * 0.5) + Math.sin(y * 0.9 - t * 0.35) + Math.sin((x + y) * 0.4 + t * 0.2);
  return v / 6 + 0.5;
}

function smoothstep(edge0: number, edge1: number, x: number): number {
  const t = Math.min(1, Math.max(0, (x - edge0) / (edge1 - edge0)));
  return t * t * (3 - 2 * t);
}

export interface LoaderAsciiDiffuseFillProps {
  /** accessible label for the progressbar */
  "aria-label"?: string;
  /** extra classes merged onto the rendered root element — size it here (e.g. "h-20 w-64"); the canvas fills whatever box it's given */
  className?: string;
}

export function LoaderAsciiDiffuseFill({
  "aria-label": ariaLabel = "Loading",
  className = "",
}: LoaderAsciiDiffuseFillProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fgRef = useRef("");

  // token derive — synchronous, before first paint, so nothing can ever
  // draw with an empty/default ink color
  useLayoutEffect(() => {
    fgRef.current = readTokens().fg;
  }, []);

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    if (!container || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    let advancePerPx = 0.6; // '@' advance-width / font-size, refined once the mono font is ready
    let cellSize = 10;
    let fontSize = 10;
    let cols = 0;
    let rows = 0;
    let work: Float32Array | null = null;
    let quant: Uint8Array | null = null;
    let visible = true;
    let raf = 0;
    let metricsGen = 0;

    const measureAdvance = () => {
      const gen = ++metricsGen;
      const measure = () => {
        if (gen !== metricsGen) return;
        const off = document.createElement("canvas").getContext("2d");
        if (!off) return;
        const REF = 100;
        off.font = `${REF}px "GeistMono", ui-monospace, monospace`;
        const w = off.measureText("@").width;
        if (w > 0) advancePerPx = w / REF;
        computeGeometry();
      };
      if (document.fonts?.ready) {
        document.fonts.ready.then(measure);
      } else {
        measure();
      }
    };

    const computeGeometry = () => {
      const rect = container.getBoundingClientRect();
      const w = Math.max(1, rect.width);
      const h = Math.max(1, rect.height);
      const shortDim = Math.min(w, h);
      cellSize = Math.min(MAX_CELL_PX, Math.max(MIN_CELL_PX, Math.floor(shortDim / MIN_CELLS_SHORT)));
      fontSize = cellSize / advancePerPx;
      cols = Math.max(4, Math.floor(w / cellSize));
      rows = Math.max(3, Math.floor(h / cellSize));
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.ceil(w * dpr);
      canvas.height = Math.ceil(h * dpr);
      canvas.style.width = `${w}px`;
      canvas.style.height = `${h}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.font = `${fontSize}px "GeistMono", ui-monospace, monospace`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      work = new Float32Array(cols * rows);
      quant = new Uint8Array(cols * rows);
      if (reduced) {
        drawFrame(STATIC_T, STATIC_FRONT_FRAC * cols);
      } else {
        start();
      }
    };

    // fills `into` with the pre-quantization value field: a soft cyclic
    // sweep boundary plus a flowing noise term, present in BOTH the filled
    // and unfilled regions so the diffusion has texture to work on everywhere
    const buildField = (time: number, frontXOverride: number | null, into: Float32Array) => {
      const cyclePx = cols + BAND * 4;
      const frontX = frontXOverride ?? ((time * SWEEP_SPEED) % cyclePx) - BAND * 2;
      for (let gy = 0; gy < rows; gy++) {
        for (let gx = 0; gx < cols; gx++) {
          const d = gx - frontX;
          const filled = 1 - smoothstep(-BAND, BAND, d);
          const n = flow(gx * 0.5, gy * 0.5, time);
          const seamTurbulence = 1 - smoothstep(BAND * 0.4, BAND * 1.6, Math.abs(d));
          const amp = 0.09 + 0.05 * seamTurbulence;
          const base = 0.08 + filled * 0.85;
          into[gy * cols + gx] = Math.min(1, Math.max(0, base + amp * (n - 0.5) * 2));
        }
      }
    };

    // serpentine Floyd-Steinberg: alternates scan direction every row via
    // `dir` (+1 left-to-right, -1 right-to-left) and mirrors the kernel's x
    // offsets through `dir` rather than hardcoding left/right, so both scan
    // legs share one implementation. `field` is mutated in place (that's how
    // the propagated error actually reaches downstream cells); `quantOut`
    // collects the resulting ramp index per cell.
    const diffuse = (field: Float32Array, quantOut: Uint8Array) => {
      for (let gy = 0; gy < rows; gy++) {
        const dir = gy % 2 === 0 ? 1 : -1;
        const xStart = dir === 1 ? 0 : cols - 1;
        const xEnd = dir === 1 ? cols : -1;
        for (let gx = xStart; gx !== xEnd; gx += dir) {
          const idx = gy * cols + gx;
          const old = field[idx];
          const qi = Math.min(LEVELS - 1, Math.max(0, Math.round(old * (LEVELS - 1))));
          const newVal = qi / (LEVELS - 1);
          const err = old - newVal;
          quantOut[idx] = qi;

          const fx = gx + dir; // forward in scan direction: 7/16
          const bxBehind = gx - dir; // down, behind-side of scan: 3/16
          const bxAhead = gx + dir; // down, ahead-side of scan: 1/16
          if (fx >= 0 && fx < cols) field[idx + dir] += err * FS_FWD;
          if (gy + 1 < rows) {
            const rowBelow = (gy + 1) * cols;
            if (bxBehind >= 0 && bxBehind < cols) field[rowBelow + bxBehind] += err * FS_DL;
            field[rowBelow + gx] += err * FS_D;
            if (bxAhead >= 0 && bxAhead < cols) field[rowBelow + bxAhead] += err * FS_DR;
          }
        }
      }
    };

    const paint = (quantOut: Uint8Array) => {
      // guard, not a fallback color: if the token genuinely hasn't been
      // read yet (should be impossible — see the useLayoutEffect note
      // above — but this is the actual defense, not a hardcoded hex) skip
      // the paint rather than draw in an unknown/default ink
      if (!fgRef.current) return;
      const { width, height } = container.getBoundingClientRect();
      ctx.clearRect(0, 0, width, height);
      ctx.fillStyle = fgRef.current;
      for (let gy = 0; gy < rows; gy++) {
        for (let gx = 0; gx < cols; gx++) {
          const ch = RAMP[quantOut[gy * cols + gx]];
          if (ch === " ") continue;
          ctx.fillText(ch, gx * cellSize + cellSize / 2, gy * cellSize + cellSize / 2);
        }
      }
    };

    const drawFrame = (time: number, frontXOverride: number | null) => {
      if (!work || !quant || cols === 0 || rows === 0) return;
      buildField(time, frontXOverride, work);
      diffuse(work, quant);
      paint(quant);
    };

    const loop = (now: number) => {
      raf = 0;
      if (!visible || document.hidden) return; // paused: no reschedule, a wake() call restarts it
      drawFrame(now / 1000, null);
      raf = requestAnimationFrame(loop);
    };

    const start = () => {
      if (raf || reduced) return;
      raf = requestAnimationFrame(loop);
    };

    const ro = new ResizeObserver(computeGeometry);
    ro.observe(container);

    const io = new IntersectionObserver(
      (entries) => {
        visible = entries[0]?.isIntersecting ?? true;
        if (visible) start();
      },
      { threshold: 0 }
    );
    io.observe(container);

    const onVisibility = () => {
      if (!document.hidden) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const onReducedChange = () => {
      reduced = mq.matches;
      if (reduced) {
        cancelAnimationFrame(raf);
        raf = 0;
        drawFrame(STATIC_T, STATIC_FRONT_FRAC * cols);
      } else {
        start();
      }
    };
    mq.addEventListener("change", onReducedChange);

    const mo = new MutationObserver(() => {
      fgRef.current = readTokens().fg;
      if (reduced) drawFrame(STATIC_T, STATIC_FRONT_FRAC * cols);
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style"] });

    measureAdvance();

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
      mq.removeEventListener("change", onReducedChange);
    };
  }, []);

  return (
    <div
      ref={containerRef}
      role="progressbar"
      aria-label={ariaLabel}
      className={`relative block overflow-hidden ${className}`}
    >
      <canvas ref={canvasRef} aria-hidden className="block h-full w-full" />
    </div>
  );
}

"use client";

// A loader built from braille cells (U+2800 block), where each cell's eight
// dots are individually addressable bits rather than a single glyph from a
// spinner sprite sheet. Indeterminate: a wave travels through the row — each
// cell's fill level is a sine function of time, phase-shifted by its column,
// so dots rise and fall like a stadium wave rather than a rotating glyph.
// Determinate: `progress` maps onto every dot across the row in reading
// order (cell 0's eight dots fill first, then cell 1's, ...), so 0-100% has
// N_CELLS * 8 addressable steps — far finer than a block-character bar could
// offer at the same character width. Reaching 100 triggers a one-shot accent
// pulse across the row before settling.
//
// One direct-DOM rAF loop builds the row string and writes it to a single
// ref's textContent each frame (never React state per frame); glyph color is
// read from getComputedStyle so it tracks the surrounding theme. Settling
// on completion is the only thing that goes through React state, since it's
// a discrete one-shot transition, not a per-frame value.

import { useEffect, useId, useRef, useState } from "react";

const N_CELLS = 14;
// dot fill priority within a cell, bottom row first: rises like a level meter
const PRIORITY = [7, 8, 3, 6, 2, 5, 1, 4] as const;
const BIT: Record<number, number> = { 1: 0x01, 2: 0x02, 3: 0x04, 4: 0x08, 5: 0x10, 6: 0x20, 7: 0x40, 8: 0x80 };

function cellChar(n: number): string {
  const count = Math.max(0, Math.min(8, Math.round(n)));
  let mask = 0;
  for (let i = 0; i < count; i++) mask |= BIT[PRIORITY[i]];
  return String.fromCharCode(0x2800 + mask);
}

const WAVE_SPEED = 2.6; // rad/s
const PHASE_STEP = 0.55; // rad per column
const SETTLE_MS = 480;

export interface BrailleSpinProps {
  /** 0-100 for a determinate fill; omit (or leave undefined) for the indeterminate wave. */
  progress?: number;
  /** accessible label for the progressbar. */
  "aria-label"?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function BrailleSpin({
  progress,
  "aria-label": ariaLabel = "Loading",
  className = "",
}: BrailleSpinProps) {
  const rowRef = useRef<HTMLSpanElement>(null);
  const progressRef = useRef(progress);
  const [settled, setSettled] = useState(progress != null && progress >= 100);
  const settledOnceRef = useRef(settled);
  const idBase = useId();

  useEffect(() => {
    progressRef.current = progress;
  }, [progress]);

  useEffect(() => {
    if (progress != null && progress >= 100) {
      if (!settledOnceRef.current) {
        settledOnceRef.current = true;
        setSettled(true);
        const t = window.setTimeout(() => setSettled(false), SETTLE_MS);
        return () => window.clearTimeout(t);
      }
    } else {
      settledOnceRef.current = false;
    }
  }, [progress]);

  // mount-once animated loop; skipped entirely under reduced motion
  useEffect(() => {
    const row = rowRef.current;
    if (!row) return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

    const paint = (levels: number[]) => {
      row.textContent = levels.map(cellChar).join("");
    };
    let raf = 0;
    const start = performance.now();
    const loop = (now: number) => {
      const p = progressRef.current;
      if (p == null) {
        const t = (now - start) / 1000;
        paint(
          Array.from({ length: N_CELLS }, (_, i) => 4 + 4 * Math.sin(t * WAVE_SPEED - i * PHASE_STEP))
        );
      } else {
        const totalDots = N_CELLS * 8;
        const litDots = Math.round((Math.max(0, Math.min(100, p)) / 100) * totalDots);
        paint(Array.from({ length: N_CELLS }, (_, i) => litDots - i * 8));
      }
      raf = requestAnimationFrame(loop);
    };
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, []);

  // reduced motion: one correct static frame, repainted live if `progress` changes
  // (there is no running loop above to pick that change up on its own)
  useEffect(() => {
    const row = rowRef.current;
    if (!row) return;
    if (!window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    if (progress == null) {
      // gentle standing arc stands in for the wave with nothing moving
      row.textContent = Array.from({ length: N_CELLS }, (_, i) => cellChar(4 + 2 * Math.sin(i * PHASE_STEP))).join("");
    } else {
      const totalDots = N_CELLS * 8;
      const litDots = Math.round((Math.max(0, Math.min(100, progress)) / 100) * totalDots);
      row.textContent = Array.from({ length: N_CELLS }, (_, i) => cellChar(litDots - i * 8)).join("");
    }
  }, [progress]);

  const determinate = progress != null;
  const clamped = determinate ? Math.max(0, Math.min(100, progress as number)) : undefined;

  return (
    <div
      role="progressbar"
      aria-label={ariaLabel}
      aria-valuemin={determinate ? 0 : undefined}
      aria-valuemax={determinate ? 100 : undefined}
      aria-valuenow={determinate ? Math.round(clamped as number) : undefined}
      className={`inline-block font-mono leading-none ${className}`}
    >
      <style>{`
.ns-braille-row{transition:color 260ms ease-out}
.ns-braille-settled{color:var(--ns-accent) !important}
`}</style>
      <span
        ref={rowRef}
        id={idBase}
        aria-hidden
        className={`ns-braille-row whitespace-pre text-foreground ${settled ? "ns-braille-settled" : ""}`}
      >
        {cellChar(0).repeat(N_CELLS)}
      </span>
    </div>
  );
}

"use client";

// ---------------------------------------------------------------------------
// HingeTopple — an ambient loading glyph shaped as a die tumbling face over
// face on a fixed axle. Four pip-marked faces ring a CSS 3D cube; one
// rotateY keyframe steps it through them 90deg at a time, but each quarter
// isn't a clean rotation to its target — it eases in fast (ease-out-expo),
// swings 8deg past the landing face, then corrects back on the house spring
// curve (cubic-bezier(.34,1.56,.64,1), the same overshoot used for
// wizard-dovetail's chip seat), so every landing reads as weight catching
// itself rather than an animation hitting a number. A soft floor shadow
// underneath compresses as the cube rocks up off it and flares as it lands,
// entirely in CSS, synced to the same four-beat timeline.
// ---------------------------------------------------------------------------

const PIP_LAYOUT: Record<number, ReadonlyArray<readonly [number, number]>> = {
  1: [[50, 50]],
  2: [
    [30, 30],
    [70, 70],
  ],
  3: [
    [30, 30],
    [50, 50],
    [70, 70],
  ],
  4: [
    [30, 30],
    [70, 30],
    [30, 70],
    [70, 70],
  ],
};

const FACES: ReadonlyArray<{ pips: number; transform: string; shade: number }> = [
  { pips: 1, transform: "rotateY(0deg)", shade: 0 },
  { pips: 2, transform: "rotateY(90deg)", shade: 10 },
  { pips: 3, transform: "rotateY(180deg)", shade: 16 },
  { pips: 4, transform: "rotateY(-90deg)", shade: 10 },
];

const CSS = `
.ns-ht-stage{
  position:relative;
  perspective:calc(var(--ns-ht-size) * 5);
  width:var(--ns-ht-size);
  height:var(--ns-ht-size);
}
.ns-ht-cube{
  position:absolute;
  inset:0;
  transform-style:preserve-3d;
  animation:ns-ht-spin var(--ns-ht-period) infinite;
}
.ns-ht-face{
  position:absolute;
  inset:0;
  border-radius:6px;
  border:1px solid var(--border);
  background:var(--surface);
  backface-visibility:hidden;
  display:grid;
  grid-template-columns:repeat(3,1fr);
  grid-template-rows:repeat(3,1fr);
  padding:18%;
}
.ns-ht-face::before{
  content:"";
  position:absolute;
  inset:0;
  border-radius:6px;
  background:var(--ns-ht-shade);
  pointer-events:none;
}
.ns-ht-pip{
  width:14%;
  height:14%;
  border-radius:9999px;
  background:var(--foreground);
  align-self:center;
  justify-self:center;
}
.ns-ht-floor{
  position:absolute;
  left:50%;
  bottom:-10%;
  width:70%;
  height:10%;
  transform:translateX(-50%);
  border-radius:9999px;
  background:var(--foreground);
  filter:blur(3px);
  animation:ns-ht-floor var(--ns-ht-period) infinite;
}
@keyframes ns-ht-spin{
  0%{transform:rotateY(0deg);animation-timing-function:linear}
  14%{transform:rotateY(0deg);animation-timing-function:cubic-bezier(.16,1,.3,1)}
  20%{transform:rotateY(-98deg);animation-timing-function:cubic-bezier(.34,1.56,.64,1)}
  25%{transform:rotateY(-90deg);animation-timing-function:linear}
  39%{transform:rotateY(-90deg);animation-timing-function:cubic-bezier(.16,1,.3,1)}
  45%{transform:rotateY(-188deg);animation-timing-function:cubic-bezier(.34,1.56,.64,1)}
  50%{transform:rotateY(-180deg);animation-timing-function:linear}
  64%{transform:rotateY(-180deg);animation-timing-function:cubic-bezier(.16,1,.3,1)}
  70%{transform:rotateY(-278deg);animation-timing-function:cubic-bezier(.34,1.56,.64,1)}
  75%{transform:rotateY(-270deg);animation-timing-function:linear}
  89%{transform:rotateY(-270deg);animation-timing-function:cubic-bezier(.16,1,.3,1)}
  95%{transform:rotateY(-368deg);animation-timing-function:cubic-bezier(.34,1.56,.64,1)}
  100%{transform:rotateY(-360deg)}
}
@keyframes ns-ht-floor{
  0%,14%{transform:translateX(-50%) scaleX(1);opacity:.45}
  20%,45%,70%,95%{transform:translateX(-50%) scaleX(.55);opacity:.28}
  25%,50%,75%,100%{transform:translateX(-50%) scaleX(1.2);opacity:.6}
  39%,64%,89%{transform:translateX(-50%) scaleX(1);opacity:.45}
}
@media (prefers-reduced-motion: reduce){
  .ns-ht-cube,.ns-ht-floor{animation:none;}
  .ns-ht-floor{transform:translateX(-50%) scaleX(1);opacity:.45;}
}
`;

export interface HingeToppleProps {
  /** cube edge length in px */
  size?: number;
  /** ms for one full four-face loop */
  periodMs?: number;
  /** text announced via the component's own aria-live region */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function HingeTopple({
  size = 48,
  periodMs = 4800,
  label = "Loading",
  className = "",
}: HingeToppleProps) {
  const half = size / 2;
  return (
    <span
      role="status"
      aria-live="polite"
      data-loader-die-tumble
      className={`inline-flex items-center justify-center ${className}`}
      style={{
        width: size,
        paddingBottom: size * 0.18,
        ["--ns-ht-size" as string]: `${size}px`,
        ["--ns-ht-period" as string]: `${periodMs}ms`,
      }}
    >
      <style>{CSS}</style>
      <span className="ns-ht-stage" aria-hidden="true">
        <span className="ns-ht-cube">
          {FACES.map((face) => (
            <span
              key={face.pips}
              className="ns-ht-face"
              style={{
                transform: `${face.transform} translateZ(${half}px)`,
                ["--ns-ht-shade" as string]: `color-mix(in srgb, var(--foreground) ${face.shade}%, transparent)`,
              }}
            >
              {PIP_LAYOUT[face.pips]!.map(([x, y], i) => (
                <span
                  key={i}
                  className="ns-ht-pip"
                  style={{ gridColumn: x < 50 ? 1 : x > 50 ? 3 : 2, gridRow: y < 50 ? 1 : y > 50 ? 3 : 2 }}
                />
              ))}
            </span>
          ))}
        </span>
        <span className="ns-ht-floor" />
      </span>
      <span className="sr-only">{label}</span>
    </span>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// ThinkingGlyph — a small canvas-2D "assistant state" indicator: a soft ink
// blob traced through N points sampled around a circle, each point's radius
// perturbed by a per-state motion function. No WebGL, no SVG filters — flat
// canvas fills and strokes only, so it renders identically across browsers.
//
// Six states, six distinct motion signatures (not six lookups into the same
// noise field):
//   idle      — one slow sine wobble, gentle breathing scale
//   thinking  — three additive sine bands at different frequencies/phases
//               plus tiny deterministic per-point jitter (turbulent surface)
//   listening — the blob itself barely moves; a ring emits from its edge and
//               expands/fades on a fixed period (sonar pulse)
//   speaking  — a 6-lobe standing wave rides the outline, amplitude
//               modulated by a slow envelope (a wobbling waveform, not audio
//               reactive — no external signal)
//   success   — wobble amplitude eases to zero (blob settles into a near
//               circle) and a checkmark strokes itself in, timed from the
//               moment `state` became "success"
//   error     — a short decaying horizontal shake plays every ~900ms and an
//               X strokes itself in, timed from the moment `state` became
//               "error"
//
// Ink comes from --foreground/--ns-muted for the blob and --ns-accent/--success/
// --error for the sonar ring, checkmark and X respectively, all read via
// getComputedStyle at mount and re-read on a MutationObserver watching
// documentElement's class attribute. The rAF loop pauses on
// visibilitychange and under prefers-reduced-motion, drawing one static
// settled frame instead. Backing store is dpr-clamped to 2.
// ---------------------------------------------------------------------------

export type ThinkingGlyphState = "idle" | "thinking" | "listening" | "speaking" | "success" | "error";

export interface ThinkingGlyphProps {
  /** Which motion signature to show. @default "idle" */
  state?: ThinkingGlyphState;
  /** Rendered diameter in CSS px. @default 48 */
  size?: number;
  /** Animation speed multiplier. @default 1 */
  speed?: number;
  /** Freezes the current frame. @default false */
  paused?: boolean;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** inline styles merged onto the root element */
  style?: React.CSSProperties;
}

const POINTS = 72;
const TWO_PI = Math.PI * 2;

const STATE_LABEL: Record<ThinkingGlyphState, string> = {
  idle: "idle",
  thinking: "thinking",
  listening: "listening",
  speaking: "speaking",
  success: "done",
  error: "error",
};

function hashP(i: number): number {
  const h = Math.sin(i * 91.345 + 12.9) * 43758.5453;
  return h - Math.floor(h);
}

function parseHex(raw: string): [number, number, number] | null {
  const m = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(raw.trim());
  if (!m) return null;
  let h = m[1];
  if (h.length === 3) h = h.split("").map((c) => c + c).join("");
  const n = parseInt(h, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

export function ThinkingGlyph({
  state = "idle",
  size = 48,
  speed = 1,
  paused = false,
  className = "",
  style,
}: ThinkingGlyphProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const stateRef = useRef(state);
  const speedRef = useRef(speed);
  const pausedRef = useRef(paused);
  const now = () => (typeof performance !== "undefined" ? performance.now() : 0);
  const stateSinceRef = useRef(now());

  if (stateRef.current !== state) {
    stateRef.current = state;
    stateSinceRef.current = now();
  }
  speedRef.current = speed;
  pausedRef.current = paused;

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let raf = 0;
    let running = false;
    let dpr = 1;

    let fg = "rgba(23,23,23,1)";
    let fgSoft = "rgba(23,23,23,0.14)";
    let mutedStyle = "rgba(77,77,77,1)";
    let accentStyle = "#006bff";
    let successStyle = "#47a447";
    let errorStyle = "#ea001d";

    const readInk = () => {
      const cs = getComputedStyle(document.documentElement);
      const fgHex = cs.getPropertyValue("--foreground").trim();
      const rgb = parseHex(fgHex) ?? [23, 23, 23];
      fg = `rgba(${rgb[0]},${rgb[1]},${rgb[2]},0.92)`;
      fgSoft = `rgba(${rgb[0]},${rgb[1]},${rgb[2]},0.14)`;
      mutedStyle = cs.getPropertyValue("--ns-muted").trim() || "#4d4d4d";
      accentStyle = cs.getPropertyValue("--ns-accent").trim() || "#006bff";
      successStyle = cs.getPropertyValue("--success").trim() || "#47a447";
      errorStyle = cs.getPropertyValue("--error").trim() || "#ea001d";
    };
    readInk();

    const resize = () => {
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.round(size * dpr);
      canvas.height = Math.round(size * dpr);
      canvas.style.width = `${size}px`;
      canvas.style.height = `${size}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };
    resize();

    const cx = size / 2;
    const cy = size / 2;
    const baseR = size * 0.32;

    // per-point jitter phase, stable across frames (deterministic hash, not
    // Math.random — reproducible and free of a seeded-PRNG dependency)
    const jitter = new Float32Array(POINTS);
    for (let i = 0; i < POINTS; i++) jitter[i] = hashP(i) * TWO_PI;

    const radiusFor = (i: number, angle: number, t: number, st: ThinkingGlyphState, since: number): number => {
      const age = (performance.now() - since) / 1000;
      switch (st) {
        case "idle":
          return baseR * (1 + 0.04 * Math.sin(angle * 3 + t * 1.1));
        case "thinking":
          return (
            baseR *
            (1 +
              0.05 * Math.sin(angle * 5 + t * 2.3) +
              0.035 * Math.sin(angle * 8 - t * 3.1 + 1.7) +
              0.018 * Math.sin(angle * 13 + t * 4.3 + jitter[i]))
          );
        case "listening":
          return baseR * (1 + 0.05 * Math.sin(t * 3.2));
        case "speaking": {
          const envelope = 0.6 + 0.4 * Math.sin(t * 1.4);
          return baseR * (1 + 0.11 * envelope * Math.sin(angle * 6 + t * 5.2));
        }
        case "success": {
          const settle = Math.min(1, age / 0.5);
          const wobble = (1 - settle) * 0.05 * Math.sin(angle * 4 + t * 2);
          return baseR * (1 + wobble);
        }
        case "error": {
          const cyclePos = (t * 1.05) % 1;
          const burst = cyclePos < 0.35 ? Math.exp(-cyclePos * 14) : 0;
          return baseR * (1 + 0.03 * Math.sin(angle * 4 + t * 3) + 0.01 * burst);
        }
        default:
          return baseR;
      }
    };

    const drawBlob = (t: number, st: ThinkingGlyphState, since: number) => {
      let shakeX = 0;
      if (st === "error") {
        const cyclePos = (t * 1.05) % 1;
        if (cyclePos < 0.35) {
          const decay = Math.exp(-cyclePos * 14);
          shakeX = Math.sin(cyclePos * 90) * 3 * decay;
        }
      }

      ctx.save();
      ctx.translate(shakeX, 0);

      const pts: [number, number][] = [];
      for (let i = 0; i < POINTS; i++) {
        const angle = (i / POINTS) * TWO_PI;
        const r = radiusFor(i, angle, t, st, since);
        pts.push([cx + Math.cos(angle) * r, cy + Math.sin(angle) * r]);
      }

      ctx.beginPath();
      const first = pts[0];
      ctx.moveTo((first[0] + pts[POINTS - 1][0]) / 2, (first[1] + pts[POINTS - 1][1]) / 2);
      for (let i = 0; i < POINTS; i++) {
        const p = pts[i];
        const next = pts[(i + 1) % POINTS];
        const midX = (p[0] + next[0]) / 2;
        const midY = (p[1] + next[1]) / 2;
        ctx.quadraticCurveTo(p[0], p[1], midX, midY);
      }
      ctx.closePath();

      ctx.fillStyle = fgSoft;
      ctx.fill();
      ctx.lineWidth = Math.max(1, size * 0.03);
      ctx.strokeStyle = st === "thinking" ? mutedStyle : fg;
      ctx.stroke();
      ctx.restore();
    };

    const drawSonar = (t: number) => {
      const period = 1.2;
      const phase = (t % period) / period;
      const r = baseR * (1 + phase * 0.9);
      const alpha = (1 - phase) * 0.45;
      if (alpha <= 0.01) return;
      ctx.beginPath();
      ctx.arc(cx, cy, r, 0, TWO_PI);
      ctx.strokeStyle = accentStyle;
      ctx.globalAlpha = alpha;
      ctx.lineWidth = Math.max(1, size * 0.02);
      ctx.stroke();
      ctx.globalAlpha = 1;
    };

    const drawCheck = (since: number) => {
      const age = (performance.now() - since) / 1000;
      const p = Math.min(1, age / 0.4);
      if (p <= 0) return;
      const x0 = cx - baseR * 0.42;
      const y0 = cy + baseR * 0.02;
      const x1 = cx - baseR * 0.08;
      const y1 = cy + baseR * 0.34;
      const x2 = cx + baseR * 0.46;
      const y2 = cy - baseR * 0.32;
      ctx.beginPath();
      ctx.strokeStyle = successStyle;
      ctx.lineWidth = Math.max(1.5, size * 0.06);
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      ctx.moveTo(x0, y0);
      if (p <= 0.5) {
        const seg = p / 0.5;
        ctx.lineTo(x0 + (x1 - x0) * seg, y0 + (y1 - y0) * seg);
      } else {
        ctx.lineTo(x1, y1);
        const seg = (p - 0.5) / 0.5;
        ctx.lineTo(x1 + (x2 - x1) * seg, y1 + (y2 - y1) * seg);
      }
      ctx.stroke();
    };

    const drawX = (since: number) => {
      const age = (performance.now() - since) / 1000;
      const p = Math.min(1, age / 0.35);
      if (p <= 0) return;
      const k = baseR * 0.36;
      ctx.strokeStyle = errorStyle;
      ctx.lineWidth = Math.max(1.5, size * 0.06);
      ctx.lineCap = "round";
      ctx.beginPath();
      ctx.moveTo(cx - k, cy - k);
      ctx.lineTo(cx - k + (2 * k) * Math.min(1, p * 2), cy - k + (2 * k) * Math.min(1, p * 2));
      ctx.stroke();
      if (p > 0.5) {
        const seg = (p - 0.5) / 0.5;
        ctx.beginPath();
        ctx.moveTo(cx + k, cy - k);
        ctx.lineTo(cx + k - (2 * k) * seg, cy - k + (2 * k) * seg);
        ctx.stroke();
      }
    };

    const draw = (nowMs: number) => {
      ctx.clearRect(0, 0, size, size);
      const st = stateRef.current;
      const since = stateSinceRef.current;
      const t = (nowMs / 1000) * speedRef.current;
      if (st === "listening") drawSonar(t);
      drawBlob(t, st, since);
      if (st === "success") drawCheck(since);
      if (st === "error") drawX(since);
    };

    const loop = (t: number) => {
      draw(t);
      raf = requestAnimationFrame(loop);
    };
    const wake = () => {
      if (running) return;
      running = true;
      raf = requestAnimationFrame(loop);
    };
    const sleep = () => {
      cancelAnimationFrame(raf);
      running = false;
    };

    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    let reduced = mq.matches;
    const applyMode = () => {
      if (reduced || pausedRef.current) {
        sleep();
        draw(performance.now());
      } else {
        wake();
      }
    };
    const onMq = () => {
      reduced = mq.matches;
      applyMode();
    };
    mq.addEventListener("change", onMq);
    applyMode();

    let pollId = 0;
    let lastPaused = pausedRef.current;
    const poll = () => {
      if (pausedRef.current !== lastPaused) {
        lastPaused = pausedRef.current;
        applyMode();
      }
      pollId = window.setTimeout(poll, 120);
    };
    poll();

    const onVis = () => {
      if (document.hidden) sleep();
      else if (!reduced && !pausedRef.current) wake();
    };
    document.addEventListener("visibilitychange", onVis);

    const themeObserver = new MutationObserver(() => {
      readInk();
      if (reduced || pausedRef.current) draw(performance.now());
    });
    themeObserver.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    return () => {
      mq.removeEventListener("change", onMq);
      document.removeEventListener("visibilitychange", onVis);
      themeObserver.disconnect();
      window.clearTimeout(pollId);
      sleep();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [size]);

  return (
    <div
      role="img"
      aria-label={`Assistant is ${STATE_LABEL[state]}`}
      className={className}
      style={{ width: size, height: size, display: "inline-block", ...style }}
    >
      <canvas ref={canvasRef} aria-hidden="true" />
    </div>
  );
}

ThinkingGlyph.displayName = "ThinkingGlyph";

"use client";

// ---------------------------------------------------------------------------
// BladeIris — an ambient loading glyph shaped as a six-blade camera-iris
// diaphragm breathing open and shut inside a fixed housing ring. Each blade
// is one wedge polygon, repeated six times via SVG <g rotate(60*i 50 50)>,
// so only one shape is authored; the aperture itself is driven by a single
// shared translateY keyframe every blade runs identically (retreating
// toward the housing to open, sliding back toward center to close) — the
// hex hole in the middle is purely the six wedges' tips moving in unison,
// never a separately drawn shape. Both the open and the close leg ease in
// fast then overshoot their target before correcting on the house spring
// curve, so the aperture reads as spring-tensioned blades snapping to a
// stop rather than a shape tweening between two states.
// ---------------------------------------------------------------------------

const CSS = `
.ns-bi-blade{
  transform-box:fill-box;
  transform-origin:center;
  animation:ns-bi-breathe var(--ns-bi-period) infinite;
}
@keyframes ns-bi-breathe{
  0%,10%{transform:translateY(0px);animation-timing-function:cubic-bezier(.16,1,.3,1)}
  22%{transform:translateY(-9px);animation-timing-function:cubic-bezier(.34,1.56,.64,1)}
  28%{transform:translateY(-7.5px)}
  55%{transform:translateY(-7.5px);animation-timing-function:cubic-bezier(.16,1,.3,1)}
  67%{transform:translateY(1px);animation-timing-function:cubic-bezier(.34,1.56,.64,1)}
  73%,100%{transform:translateY(0px)}
}
@media (prefers-reduced-motion: reduce){
  .ns-bi-blade{animation:none;transform:translateY(-4px);}
}
`;

const BLADE_D = "M 50 47 L 37 12 L 63 12 Z";

export interface BladeIrisProps {
  /** glyph size in px */
  size?: number;
  /** ms for one full open-close breath */
  periodMs?: number;
  /** text announced via the component's own aria-live region */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function BladeIris({
  size = 40,
  periodMs = 2600,
  label = "Loading",
  className = "",
}: BladeIrisProps) {
  return (
    <span
      role="status"
      aria-live="polite"
      data-loader-iris
      className={`inline-flex shrink-0 items-center justify-center ${className}`}
      style={{ width: size, height: size }}
    >
      <style>{CSS}</style>
      <svg
        viewBox="0 0 100 100"
        width={size}
        height={size}
        aria-hidden="true"
        focusable="false"
        style={{ ["--ns-bi-period" as string]: `${periodMs}ms` }}
      >
        <circle cx={50} cy={50} r={46} fill="none" stroke="var(--border)" strokeWidth={1.5} />
        {Array.from({ length: 6 }, (_, i) => (
          <g key={i} transform={`rotate(${i * 60} 50 50)`}>
            <path
              className="ns-bi-blade"
              d={BLADE_D}
              fill="color-mix(in srgb, var(--foreground) 82%, transparent)"
              stroke="var(--surface)"
              strokeWidth={1}
              strokeLinejoin="round"
            />
          </g>
        ))}
        <circle cx={50} cy={50} r={2.5} fill="var(--foreground)" />
      </svg>
      <span className="sr-only">{label}</span>
    </span>
  );
}

"use client";

// ---------------------------------------------------------------------------
// PhaseSwing — an indeterminate loader built as a physical pendulum wave.
// A row of hairline pendulums (1px arm in --ns-muted, 4px bob in --foreground)
// share one mount instant but each gets its own animation-duration —
// periodMs / (BASE_OSCILLATIONS + i) — so pendulum i completes exactly
// BASE_OSCILLATIONS+i whole swings in one periodMs cycle. Because that
// count is an integer for every pendulum, the whole row is guaranteed to
// land back in phase, all at once, every periodMs — no JS drives that
// realignment, it falls out of picking integer-oscillation periods. Between
// realignments the same arithmetic passes the row through a travelling-wave
// phase and, at the half-cycle where every count differs from its neighbor
// by exactly one half-swing, a double-helix phase — pure interference, zero
// per-frame JS.
//
// The determinate variant (a `value` 0-100 prop) is the one place JS
// touches timing at all: each pendulum's duration is linearly retargeted
// from its natural period toward the middle pendulum's own natural period,
// so the whole row visibly detunes into unison exactly as value reaches
// 100 — converging on an existing rhythm in the row, not an arbitrary new
// one.
//
// A sync moment looks identical to "finished" by design (that's the point —
// it's a watchable heartbeat for a long wait) so completion is never
// inferred from rhythm: an explicit `done` prop is required to end the
// loader, and doing so changes the DOM structurally (every pendulum
// retracts upward and fades, animation paused mid-swing) rather than just
// letting a sync happen to land. The one text node is role=status/
// aria-live=polite and is the only place "done" is ever announced.
//
// Retargeting a *running* CSS animation's duration is not free: a CSS
// animation's internal clock is elapsed-time-since-it-started, never reset
// just because animation-duration changes later, so its on-screen position
// is always (elapsedSinceStart mod duration) / duration. Every pendulum span
// stays mounted (stable `key`) for the component's entire lifetime, so
// elapsedSinceStart only ever grows — and the sensitivity of that modulo to
// a small change in duration grows with it too (roughly proportional to how
// many whole swings have already elapsed). Naively writing a new
// animationDuration into the same long-lived span each time `value` ticks
// (the old bug) compounds: early on the jumps are imperceptible, but the
// longer the row has been alive the larger each subsequent retarget's jump
// gets, which reads as "speeds up, then glitches" — and never stabilizes,
// because the clock it's built on is never reset. The fix is to track each
// pendulum's phase ourselves (a tiny epoch: {start, duration, phase} in
// epochsRef) and, on every real duration change, compute the phase it's
// actually at *right now* from the small elapsed time since the *last*
// retarget (bounded to however often `value` changes, milliseconds — never
// since mount) and re-key that one span. A changed `key` forces React to
// unmount/remount the span, which hands it a fresh DOM node and therefore a
// fresh CSS animation clock; a matching negative animation-delay
// (-(phase * newDuration)) makes that fresh clock pick up exactly where the
// old one visually left off, so the restart is invisible and the sensitivity
// term never has more than one retarget-interval's worth of elapsed time to
// act on, indefinitely. Indeterminate mode never retargets post-mount
// (`durations` is a stable, memoized array) so this never fires there —
// it stays exactly the zero-JS pure-CSS mechanism described above.
// ---------------------------------------------------------------------------

import {
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
} from "react";

const BASE_OSCILLATIONS = 8; // pendulum 0 completes this many full swings per periodMs cycle
const MIN_COUNT = 9;
const MAX_COUNT = 15;
const ANNOUNCE_STEP_S = 5; // sparse — ticks the visible/aria text every 5s, never per-frame

const CSS = `
.ns-ps-row{
  display:flex;
  align-items:flex-start;
  justify-content:center;
  gap:13px;
  height:76px;
  padding-top:6px;
}
.ns-ps-pendulum{
  position:relative;
  width:1px;
  height:64px;
  transform-origin:top center;
  animation-name:ns-ps-swing;
  animation-timing-function:cubic-bezier(.37,0,.63,1);
  animation-iteration-count:infinite;
  transition:transform 520ms cubic-bezier(.16,1,.3,1),
             opacity 420ms ease;
}
.ns-ps-arm{
  position:absolute;
  inset:0;
  width:1px;
  background:var(--ns-muted);
}
.ns-ps-bob{
  position:absolute;
  left:50%;
  bottom:-2px;
  width:4px;
  height:4px;
  margin-left:-2px;
  border-radius:9999px;
  background:var(--foreground);
}
@keyframes ns-ps-swing{
  0%{transform:rotate(var(--ns-ps-amp))}
  50%{transform:rotate(calc(-1 * var(--ns-ps-amp)))}
  100%{transform:rotate(var(--ns-ps-amp))}
}
.ns-ps-row.ns-ps-done .ns-ps-pendulum{
  animation-play-state:paused;
  transition-delay:var(--ns-ps-retract-delay,0ms);
  transform:translateY(-140%);
  opacity:0;
}
@media (prefers-reduced-motion: reduce){
  .ns-ps-pendulum{
    animation:none;
    transition:opacity 200ms ease;
    transform:rotate(0deg);
  }
  .ns-ps-row.ns-ps-done .ns-ps-pendulum{
    transform:rotate(0deg);
    opacity:0;
  }
}
`;

export interface PhaseSwingProps {
  /** Text prefix for the status label, e.g. "Building" / "Indexing". */
  label?: string;
  /** Label shown (and announced) once `done` is true. */
  doneLabel?: string;
  /** Controlled 0-100 progress. Omit for pure ambient indeterminate mode. */
  value?: number;
  /** Explicit completion. Structural (pendulums retract) — never inferred from a sync moment. */
  done?: boolean;
  /** Full sync-chaos-sync cycle length, ms. */
  periodMs?: number;
  /** Pendulum count, clamped to 9-15. */
  count?: number;
  /** Half-angle of swing, degrees. */
  amplitudeDeg?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function PhaseSwing({
  label = "Building",
  doneLabel = "Build complete",
  value,
  done = false,
  periodMs = 10000,
  count = 13,
  amplitudeDeg = 26,
  className = "",
}: PhaseSwingProps) {
  const n = Math.min(MAX_COUNT, Math.max(MIN_COUNT, Math.round(count)));

  // Natural period per pendulum: pendulum i completes BASE+i whole swings
  // in one periodMs cycle, so every one lands back at phase 0 simultaneously.
  const naturalPeriods = useMemo(
    () => Array.from({ length: n }, (_, i) => periodMs / (BASE_OSCILLATIONS + i)),
    [n, periodMs]
  );

  // Determinate retarget: converge every pendulum toward the middle
  // pendulum's own natural period (not an arbitrary new tempo) as value
  // climbs 0->100, landing exactly in unison at 100.
  const targetPeriod = naturalPeriods[Math.floor((n - 1) / 2)] ?? naturalPeriods[0]!;
  const durations = useMemo(() => {
    if (value == null) return naturalPeriods;
    const t = Math.min(100, Math.max(0, value)) / 100;
    return naturalPeriods.map((p) => p + (targetPeriod - p) * t);
  }, [naturalPeriods, targetPeriod, value]);

  // Per-pendulum phase epoch (see header comment): lets a duration change be
  // applied as "restart from the phase we're actually at", instead of
  // leaving a long-lived CSS animation to reinterpret an ever-growing
  // elapsed time against a new duration.
  const epochsRef = useRef<{ start: number; duration: number; phase: number }[] | null>(null);
  const [animDelays, setAnimDelays] = useState<string[]>(() => durations.map(() => "-1ms"));
  const [animGens, setAnimGens] = useState<number[]>(() => durations.map(() => 0));

  useLayoutEffect(() => {
    const now = performance.now();
    const prev = epochsRef.current;

    if (!prev || prev.length !== durations.length) {
      // First paint at this pendulum count: nothing has run yet to retarget
      // away from, so just seed the epochs — the natural durations already
      // rendered (via the lazy useState initializers above) are correct.
      epochsRef.current = durations.map((d) => ({ start: now, duration: d, phase: 0 }));
      return;
    }

    if (value == null) return; // indeterminate: durations never change post-mount

    let changed = false;
    const nextDelays = animDelays.slice();
    const nextGens = animGens.slice();
    durations.forEach((d, i) => {
      const e = prev[i]!;
      if (Math.abs(d - e.duration) < 0.01) return; // no real change, don't force a restart
      const elapsed = now - e.start; // bounded: time since the *last* retarget, not since mount
      const phaseNow = (e.phase + elapsed / e.duration) % 1;
      prev[i] = { start: now, duration: d, phase: phaseNow };
      nextDelays[i] = `${-(phaseNow * d)}ms`;
      nextGens[i] = (nextGens[i] ?? 0) + 1;
      changed = true;
    });
    if (changed) {
      setAnimDelays(nextDelays);
      setAnimGens(nextGens);
    }
  }, [durations, value]);

  // Sparse elapsed-time announcement, resets whenever a fresh run starts.
  const [elapsed, setElapsed] = useState(0);
  const wasDoneRef = useRef(done);
  useEffect(() => {
    if (wasDoneRef.current && !done) setElapsed(0);
    wasDoneRef.current = done;
  }, [done]);
  useEffect(() => {
    if (done) return;
    const id = window.setInterval(() => setElapsed((s) => s + ANNOUNCE_STEP_S), ANNOUNCE_STEP_S * 1000);
    return () => window.clearInterval(id);
  }, [done]);

  const statusText = done
    ? doneLabel
    : `${label}, ${elapsed} second${elapsed === 1 ? "" : "s"} elapsed`;

  return (
    <div role="status" aria-live="polite" className={`inline-flex flex-col items-center gap-3 ${className}`}>
      <style>{CSS}</style>
      <div className={done ? "ns-ps-row ns-ps-done" : "ns-ps-row"} aria-hidden="true">
        {durations.map((d, i) => {
          const style: CSSProperties = {
            animationDuration: `${d}ms`,
            // At mount (and throughout indeterminate mode) this is the same
            // identical negative delay on every pendulum: nulls out any
            // one-frame paint stagger from mounting n elements in a single
            // React render (every pendulum is pre-advanced the same
            // wall-clock amount, which does not disturb relative phase).
            // In determinate mode, once a retarget has happened, this is
            // instead the phase-matched delay computed above, applied to a
            // freshly re-keyed (freshly mounted) span — see header comment.
            animationDelay: animDelays[i] ?? "-1ms",
            "--ns-ps-amp": `${amplitudeDeg}deg`,
            "--ns-ps-retract-delay": `${i * 22}ms`,
          } as CSSProperties;
          return (
            <span key={`${i}-${animGens[i] ?? 0}`} className="ns-ps-pendulum" style={style}>
              <span className="ns-ps-arm" />
              <span className="ns-ps-bob" />
            </span>
          );
        })}
      </div>
      <p className="font-mono text-xs text-ns-muted">{statusText}</p>
    </div>
  );
}

"use client";

// ---------------------------------------------------------------------------
// SpiroTrace — a determinate loader that inks in a real hypotrochoid.
//
// The curve is the classic spirograph pen path:
//   x(phi) = (R - r)cos(phi) + d*cos(((R - r)/r) * phi)
//   y(phi) = (R - r)sin(phi) - d*sin(((R - r)/r) * phi)
// With R = 5, r = 3 (gcd 1) the pen closes after r/gcd = 3 revolutions, so phi
// sweeps 0 -> 6*PI and the result is a closed five-petal rosette (petals =
// R/gcd = 5). It is sampled once into a single "M ... L ... Z" path string,
// memoised on R/r/d, and fitted to a 0 0 100 100 viewBox with a 6-unit margin.
//
// The whole rosette is ALWAYS on screen as a faint ghost; progress is simply
// the fraction of that curve's ARC LENGTH inked on top of it (pathLength="1",
// dasharray "1 1", dashoffset 1 - progress). So 0% and 100% are both legible
// shapes, and the route the loader will take is readable before it moves.
//
// Indeterminate is not a different widget: the same curve keeps a fixed
// 0.18-length dash window travelling around it at a constant arc-length rate.
// ---------------------------------------------------------------------------

import { useEffect, useMemo, useRef } from "react";

const SAMPLES = 720; // points sampled along the closed curve
const MARGIN = 6; // viewBox units of breathing room around the fitted rosette
const VIEW = 100;
const GLIDE_MS = 260; // determinate ease, matched to the CSS transition below
const SWEEP_MS = 2400; // one full traversal in indeterminate mode
const DASH = 0.18; // indeterminate window, as a fraction of arc length

const CSS = `
.ns-sg-trace{transition:stroke-dashoffset ${GLIDE_MS}ms cubic-bezier(.33,1,.68,1)}
.ns-sg-sweep{animation:ns-sg-sweep ${SWEEP_MS}ms linear infinite}
@keyframes ns-sg-sweep{from{stroke-dashoffset:0}to{stroke-dashoffset:-1}}
@media (prefers-reduced-motion: reduce){
  .ns-sg-trace{transition:none}
  .ns-sg-sweep{animation:none}
}
`;

function gcd(a: number, b: number): number {
  return b === 0 ? Math.abs(a) : gcd(b, a % b);
}

function easeOutCubic(p: number): number {
  return 1 - (1 - p) ** 3;
}

/** Sample the hypotrochoid once and fit it into the viewBox with a margin. */
function buildRosette(R: number, r: number, d: number): string {
  const turns = Math.max(1, Math.round(r / gcd(Math.round(R), Math.round(r))));
  const phiMax = 2 * Math.PI * turns;
  const xs: number[] = [];
  const ys: number[] = [];
  for (let i = 0; i < SAMPLES; i++) {
    const phi = (i / SAMPLES) * phiMax;
    xs.push((R - r) * Math.cos(phi) + d * Math.cos(((R - r) / r) * phi));
    ys.push((R - r) * Math.sin(phi) - d * Math.sin(((R - r) / r) * phi));
  }
  let minX = Infinity;
  let maxX = -Infinity;
  let minY = Infinity;
  let maxY = -Infinity;
  for (let i = 0; i < SAMPLES; i++) {
    if (xs[i] < minX) minX = xs[i];
    if (xs[i] > maxX) maxX = xs[i];
    if (ys[i] < minY) minY = ys[i];
    if (ys[i] > maxY) maxY = ys[i];
  }
  const span = VIEW - MARGIN * 2;
  const scale = Math.min(span / (maxX - minX || 1), span / (maxY - minY || 1));
  const ox = (VIEW - (maxX - minX) * scale) / 2 - minX * scale;
  const oy = (VIEW - (maxY - minY) * scale) / 2 - minY * scale;
  const pt = (i: number) =>
    `${(xs[i] * scale + ox).toFixed(2)} ${(ys[i] * scale + oy).toFixed(2)}`;
  let out = `M ${pt(0)}`;
  for (let i = 1; i < SAMPLES; i++) out += ` L ${pt(i)}`;
  return `${out} Z`;
}

export interface SpiroTraceProps {
  /** progress 0-100. Leave undefined for indeterminate (a travelling sweep). */
  value?: number;
  /** glyph size in px. */
  size?: number;
  /** accessible name for the progressbar. */
  label?: string;
  /** fixed radius of the spirograph ring. */
  R?: number;
  /** rolling radius. gcd(R, r) = 1 keeps the rosette a single closed curve. */
  r?: number;
  /** pen offset from the rolling circle's centre. */
  d?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function SpiroTrace({
  value,
  size = 160,
  label = "Loading",
  R = 5,
  r = 3,
  d = 2.1,
  className = "",
}: SpiroTraceProps) {
  const indeterminate = value == null || Number.isNaN(value);
  const target = indeterminate ? 0 : Math.min(100, Math.max(0, value ?? 0)) / 100;

  const path = useMemo(() => buildRosette(R, r, d), [R, r, d]);
  // the curve's first sampled point, parsed straight back out of the path
  // string: it is where the pen is parked before the effect measures the
  // path, so the very first painted frame already shows the dot on the curve
  // rather than off-canvas.
  const start = useMemo(() => {
    const m = path.slice(2, path.indexOf(" L")).split(" ");
    return { x: Number(m[0]), y: Number(m[1]) };
  }, [path]);

  const ghostRef = useRef<SVGPathElement>(null);
  const traceRef = useRef<SVGPathElement>(null);
  const penRef = useRef<SVGCircleElement>(null);
  // last progress actually painted, in arc-length fraction — the indeterminate
  // sweep keeps writing to it, which is how a real value converges from where
  // the window happened to be rather than restarting from zero.
  const displayRef = useRef(indeterminate ? 0 : target);
  const wasIndetRef = useRef(indeterminate);

  useEffect(() => {
    const ghost = ghostRef.current;
    const trace = traceRef.current;
    const pen = penRef.current;
    if (!ghost || !trace || !pen) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const total = ghost.getTotalLength();
    let raf = 0;

    const placePen = (p: number) => {
      const at = ((p % 1) + 1) % 1;
      const pt = ghost.getPointAtLength(at * total);
      pen.setAttribute("cx", pt.x.toFixed(2));
      pen.setAttribute("cy", pt.y.toFixed(2));
    };

    if (indeterminate) {
      trace.style.transition = "";
      trace.style.strokeDashoffset = "0";
      wasIndetRef.current = true;
      if (reduced) {
        // static window: the same shape, frozen at a fixed offset, still legible
        displayRef.current = DASH;
        placePen(DASH);
        return;
      }
      const start = performance.now();
      const loop = (now: number) => {
        // constant arc-length rate: one full traversal per SWEEP_MS
        const head = (((now - start) / SWEEP_MS) % 1) + DASH;
        displayRef.current = head % 1;
        placePen(head);
        raf = requestAnimationFrame(loop);
      };
      raf = requestAnimationFrame(loop);
      return () => cancelAnimationFrame(raf);
    }

    const from = displayRef.current;

    if (wasIndetRef.current) {
      // Coming out of the sweep: seed the inline dashoffset at wherever the
      // window's head was, with the transition suppressed for that one write,
      // so the following write to `target` glides from there instead of
      // snapping back to an empty ring.
      trace.style.transition = "none";
      trace.style.strokeDashoffset = String(1 - from);
      void trace.getBoundingClientRect(); // force a style recalc before re-enabling
      trace.style.transition = "";
      wasIndetRef.current = false;
    }
    trace.style.strokeDashoffset = String(1 - target);

    if (reduced || Math.abs(target - from) < 1e-4) {
      displayRef.current = target;
      placePen(target);
      return;
    }

    // the pen only needs a loop while progress is in flight; it stops after
    const startedAt = performance.now();
    const loop = (now: number) => {
      const p = Math.min(1, (now - startedAt) / GLIDE_MS);
      const at = from + (target - from) * easeOutCubic(p);
      displayRef.current = at;
      placePen(at);
      raf = p < 1 ? requestAnimationFrame(loop) : 0;
    };
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, [indeterminate, target, path]);

  const pct = Math.round(target * 100);

  return (
    <div
      role="progressbar"
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={100}
      // omitted entirely while indeterminate — that absence IS the signal
      aria-valuenow={indeterminate ? undefined : pct}
      data-spiro-trace
      className={`inline-flex items-center gap-4 ${className}`}
    >
      <style>{CSS}</style>
      <svg
        viewBox={`0 0 ${VIEW} ${VIEW}`}
        width={size}
        height={size}
        aria-hidden="true"
        focusable="false"
        className="shrink-0 overflow-visible"
      >
        {/* the whole closed rosette, always visible: the route, not a track */}
        <path
          ref={ghostRef}
          d={path}
          fill="none"
          stroke="var(--foreground)"
          strokeOpacity={0.22}
          strokeWidth={1.1}
          strokeLinejoin="round"
        />
        {/* the inked fraction of that same curve */}
        <path
          ref={traceRef}
          className={`ns-sg-trace${indeterminate ? " ns-sg-sweep" : ""}`}
          d={path}
          pathLength={1}
          fill="none"
          stroke="var(--foreground)"
          strokeOpacity={0.92}
          strokeWidth={1.6}
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeDasharray={indeterminate ? `${DASH} ${1 - DASH}` : "1 1"}
          style={{ strokeDashoffset: indeterminate ? 0 : 1 - target }}
        />
        {/* the pen, riding the curve at the current position */}
        <circle ref={penRef} r={2.2} cx={start.x} cy={start.y} fill="var(--ns-accent)" />
      </svg>

      <span aria-hidden="true" className="font-mono text-sm tabular-nums text-ns-muted">
        {indeterminate ? "———" : `${pct}%`}
      </span>
    </div>
  );
}

"use client";

// ---------------------------------------------------------------------------
// LathRack — an ambient loading glyph shaped as a row of leaf springs
// mounted on a rail, one shared displacement passing through them left to
// right. Each lath runs the identical keyframe (compressed rest -> rise,
// past its own height, on ease-out-expo -> a two-beat decaying overshoot on
// the house spring curve -> back to rest) but at a negative animation-delay
// staggered by index, so what's actually one waveform looks like a pulse
// of energy travelling down the rack rather than N bars animating in
// isolation — the same "one rule, offset per element" trick loader-pendulum-sync
// uses for its pendulum row, here on translateY/scaleY instead of rotation.
// ---------------------------------------------------------------------------

const CSS = `
.ns-lr-rack{
  display:flex;
  align-items:flex-end;
  justify-content:center;
  gap:calc(var(--ns-lr-bar) * .6);
  height:var(--ns-lr-height);
}
.ns-lr-bar{
  width:var(--ns-lr-bar);
  height:100%;
  border-radius:9999px;
  background:var(--foreground);
  transform-origin:bottom center;
  animation:ns-lr-pulse var(--ns-lr-period) infinite;
}
@keyframes ns-lr-pulse{
  0%,18%{transform:scaleY(.38);animation-timing-function:cubic-bezier(.16,1,.3,1)}
  30%{transform:scaleY(1.16);animation-timing-function:cubic-bezier(.34,1.56,.64,1)}
  38%{transform:scaleY(.88);animation-timing-function:cubic-bezier(.34,1.56,.64,1)}
  46%{transform:scaleY(1.05);animation-timing-function:cubic-bezier(.16,1,.3,1)}
  54%,100%{transform:scaleY(.38)}
}
@media (prefers-reduced-motion: reduce){
  .ns-lr-bar{animation:none;transform:scaleY(.7);opacity:.7;}
}
`;

export interface LathRackProps {
  /** number of laths, clamped 3-9 */
  count?: number;
  /** rack height in px */
  height?: number;
  /** ms for one full pulse to sweep across the rack and repeat */
  periodMs?: number;
  /** text announced via the component's own aria-live region */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function LathRack({
  count = 5,
  height = 40,
  periodMs = 2200,
  label = "Loading",
  className = "",
}: LathRackProps) {
  const n = Math.min(9, Math.max(3, Math.round(count)));
  const bar = Math.max(3, Math.round(height * 0.11));
  const step = periodMs * 0.085;

  return (
    <span
      role="status"
      aria-live="polite"
      data-loader-spring-bars
      className={`inline-flex items-end ${className}`}
      style={{
        height,
        ["--ns-lr-bar" as string]: `${bar}px`,
        ["--ns-lr-height" as string]: `${height}px`,
        ["--ns-lr-period" as string]: `${periodMs}ms`,
      }}
    >
      <style>{CSS}</style>
      <span className="ns-lr-rack" aria-hidden="true">
        {Array.from({ length: n }, (_, i) => (
          <span
            key={i}
            className="ns-lr-bar"
            style={{ animationDelay: `${-(i * step)}ms` }}
          />
        ))}
      </span>
      <span className="sr-only">{label}</span>
    </span>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// WindSpool — an indeterminate/determinate loader that never lies about
// elapsed time. While `total` is unknown, thread visibly winds onto a spool
// at a steady real-time cadence (one layer roughly every 700ms, radius
// growing logarithmically so a long wait stays compact instead of looping a
// spinner that erases how long you've waited). The instant `total` arrives,
// the SAME coil converts in place: a dashed ghost ring pops to the radius
// that represents 100%, and the wound thread re-scopes to loaded/total of
// that ring — one continuous object across the indeterminate -> determinate
// handoff, never a spinner swapped for a bar. Pure SVG + CSS, one rAF loop,
// direct-DOM attribute writes on pre-rendered nodes; React state only
// changes on discrete transitions (phase flips, rounded aria fields),
// never per frame.
// ---------------------------------------------------------------------------

const RING_MS = 700; // real ms per indeterminate thread-layer tick
const CORE_R = 15; // hub radius (inside the two flanges)
const MAX_R = 84; // visual radius standing in for "100% of total"
const PITCH = 3.4; // px between wound layers
const LOG_A = 11.5; // radius(n) = CORE_R + LOG_A * ln(1 + n) while indeterminate
const N_LAYERS = Math.ceil((MAX_R - CORE_R) / PITCH) + 2;

const CX = 108;
const CY = 92;
const ANCHOR_X = 196;
const ANCHOR_Y = 20;
const FEED_ANGLE = (-52 * Math.PI) / 180; // fixed feed direction (rad)
const WOBBLE_RAD = (4.5 * Math.PI) / 180;
const WOBBLE_MS = 2600;

// spring constants (critically-damped-ish, house style: k = stiffness s^-2,
// c = 2*zeta*sqrt(k))
const RADIUS_K = 90;
const RADIUS_C = 2 * 0.62 * Math.sqrt(RADIUS_K); // small overshoot per layer
const GHOST_K = 130;
const GHOST_C = 2 * 0.68 * Math.sqrt(GHOST_K);
const SNIP_K = 150;
const SNIP_C = 2 * 0.55 * Math.sqrt(SNIP_K); // a little recoil past the snip

function springStep(
  pos: number,
  vel: number,
  target: number,
  k: number,
  c: number,
  dt: number
): [number, number] {
  const acc = -k * (pos - target) - c * vel;
  const nv = vel + acc * dt;
  return [pos + nv * dt, nv];
}

function formatBytes(n: number): string {
  if (!Number.isFinite(n) || n <= 0) return "0 B";
  if (n < 1024) return `${Math.round(n)} B`;
  const units = ["KB", "MB", "GB", "TB"];
  let v = n / 1024;
  let u = 0;
  while (v >= 1024 && u < units.length - 1) {
    v /= 1024;
    u++;
  }
  return `${v >= 10 ? Math.round(v) : Math.round(v * 10) / 10} ${units[u]}`;
}

function formatElapsed(ms: number): string {
  const s = Math.max(0, Math.round(ms / 1000));
  if (s < 60) return `${s} second${s === 1 ? "" : "s"}`;
  const m = Math.floor(s / 60);
  const r = s % 60;
  return `${m}m ${r}s`;
}

export type WindSpoolProps = {
  /** total size in bytes once known; leave undefined while indeterminate */
  total?: number;
  /** bytes accumulated so far; only meaningful once `total` is known */
  loaded?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** accessible name for the loader */
  "aria-label"?: string;
};

export function WindSpool({
  total,
  loaded = 0,
  className = "",
  "aria-label": ariaLabel = "Loading",
}: WindSpoolProps) {
  const layersRef = useRef<(SVGCircleElement | null)[]>([]);
  const ghostRef = useRef<SVGCircleElement>(null);
  const feedRef = useRef<SVGLineElement>(null);
  const captionRef = useRef<HTMLSpanElement>(null);

  const totalRef = useRef(total);
  const loadedRef = useRef(loaded);
  const wakeRef = useRef<(() => void) | null>(null);

  const initialKnown = total != null && total > 0;
  const initialPct = initialKnown
    ? Math.round(Math.min(100, Math.max(0, (loaded / (total as number)) * 100)))
    : 0;

  const [phase, setPhase] = useState<"indeterminate" | "determinate">(
    initialKnown ? "determinate" : "indeterminate"
  );
  const [valueNow, setValueNow] = useState<number | undefined>(
    initialKnown ? initialPct : undefined
  );
  const [valueText, setValueText] = useState(
    initialKnown
      ? `Loading, ${initialPct} percent of ${formatBytes(total as number)}`
      : "Loading"
  );
  const [announce, setAnnounce] = useState("");
  const [captionText, setCaptionText] = useState(
    initialKnown ? `${initialPct}% of ${formatBytes(total as number)}` : "winding…"
  );

  useEffect(() => {
    totalRef.current = total;
    loadedRef.current = loaded;
    wakeRef.current?.();
  }, [total, loaded]);

  useEffect(() => {
    const ghost = ghostRef.current;
    const feed = feedRef.current;
    if (!ghost || !feed) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    let raf = 0;
    let last = 0;
    let indeterminateStart = performance.now();

    const knownAtMount = totalRef.current != null && totalRef.current > 0;
    const initialFraction = knownAtMount
      ? Math.min(1, Math.max(0, loadedRef.current / (totalRef.current as number)))
      : 0;

    let ringCount = 0;
    let ringAcc = 0; // ms accumulated toward the next 700ms tick
    let radius = knownAtMount ? CORE_R + (MAX_R - CORE_R) * initialFraction : CORE_R;
    let radiusVel = 0;
    let growTarget = radius;

    let known = knownAtMount;
    let ghostR = knownAtMount ? MAX_R : 0;
    let ghostVel = 0;

    let snipT = 0; // 0 = feed fully extended, 1 = fully retracted
    let snipVel = 0;
    let snipping = false;
    let settled = false;

    let lastAnnouncedSec = -10;

    const paintLayers = () => {
      const nVisible = Math.max(0, Math.floor((radius - CORE_R) / PITCH));
      for (let i = 0; i < N_LAYERS; i++) {
        const el = layersRef.current[i];
        if (!el) continue;
        if (i < nVisible) {
          el.setAttribute("r", String(CORE_R + PITCH * (i + 1)));
          el.style.opacity = "1";
        } else {
          el.style.opacity = "0";
        }
      }
    };

    const paintGhost = () => {
      ghost.setAttribute("r", String(Math.max(0.001, ghostR)));
      ghost.style.opacity = ghostR > 0.5 ? String(Math.min(1, ghostR / MAX_R)) : "0";
    };

    const paintFeed = (now: number) => {
      if (settled) {
        feed.style.opacity = "0";
        return;
      }
      const wobble = reduced
        ? 0
        : Math.sin(((now - indeterminateStart) / WOBBLE_MS) * Math.PI * 2) *
          WOBBLE_RAD;
      const angle = FEED_ANGLE + (snipping ? 0 : wobble);
      const t = Math.min(1.15, snipT);
      // attach point rides the current coil edge, then eases toward the
      // anchor as snipT climbs, so the line visibly shortens into the recoil
      const attachR = radius + 3;
      const ax = CX + Math.cos(angle) * attachR;
      const ay = CY + Math.sin(angle) * attachR;
      const x2 = ax + (ANCHOR_X - ax) * t;
      const y2 = ay + (ANCHOR_Y - ay) * t;
      feed.setAttribute("x1", String(ANCHOR_X));
      feed.setAttribute("y1", String(ANCHOR_Y));
      feed.setAttribute("x2", String(x2));
      feed.setAttribute("y2", String(y2));
      // stays visible through the overshoot; the `settled` guard above is
      // what finally hides it, once the recoil has actually resettled
      feed.style.opacity = "1";
    };

    const wake = () => {
      if (!raf) raf = requestAnimationFrame(loop);
    };
    wakeRef.current = wake;

    const loop = (now: number) => {
      const dt = last === 0 ? 1 / 60 : Math.min(0.05, (now - last) / 1000);
      last = now;

      const t = totalRef.current;
      const ld = loadedRef.current;
      const knownNow = t != null && t > 0;

      if (knownNow !== known) {
        known = knownNow;
        if (knownNow) {
          setPhase("determinate");
          const pct = Math.round(Math.min(100, Math.max(0, (ld / (t as number)) * 100)));
          setAnnounce(`Loading, ${pct} percent of ${formatBytes(t as number)}`);
        } else {
          // a fresh indeterminate run started — bank nothing, restart clean
          ringCount = 0;
          ringAcc = 0;
          radius = CORE_R;
          radiusVel = 0;
          growTarget = CORE_R;
          indeterminateStart = now;
          lastAnnouncedSec = -10;
          setPhase("indeterminate");
          setValueNow(undefined);
          setValueText("Loading");
        }
        settled = false;
        snipping = false;
        snipT = 0;
        snipVel = 0;
      }

      if (!knownNow) {
        ringAcc += dt * 1000;
        while (ringAcc >= RING_MS) {
          ringAcc -= RING_MS;
          ringCount += 1;
          growTarget = CORE_R + LOG_A * Math.log1p(ringCount);
          if (reduced) radius = growTarget;
        }
        if (!reduced) {
          [radius, radiusVel] = springStep(
            radius,
            radiusVel,
            growTarget,
            RADIUS_K,
            RADIUS_C,
            dt
          );
        }

        const elapsedSec = (now - indeterminateStart) / 1000;
        if (elapsedSec - lastAnnouncedSec >= 10) {
          lastAnnouncedSec = elapsedSec;
          setValueText(`Loading, ${formatElapsed(elapsedSec * 1000)} elapsed`);
        }

        if (reduced) {
          ghostR = 0;
          ghostVel = 0;
        } else {
          [ghostR, ghostVel] = springStep(ghostR, ghostVel, 0, GHOST_K, GHOST_C, dt);
        }

        setCaptionText(`winding — ${formatElapsed(elapsedSec * 1000)}`);
      } else {
        const total_ = t as number;
        const fraction = Math.min(1, Math.max(0, ld / total_));
        growTarget = CORE_R + (MAX_R - CORE_R) * fraction;
        if (reduced) {
          radius = growTarget;
        } else {
          [radius, radiusVel] = springStep(
            radius,
            radiusVel,
            growTarget,
            RADIUS_K,
            RADIUS_C,
            dt
          );
        }

        if (reduced) {
          ghostR = MAX_R;
        } else {
          [ghostR, ghostVel] = springStep(ghostR, ghostVel, MAX_R, GHOST_K, GHOST_C, dt);
        }

        const pct = Math.round(fraction * 100);
        setValueNow(pct);
        setValueText(`Loading, ${pct} percent of ${formatBytes(total_)}`);
        setCaptionText(`${pct}% of ${formatBytes(total_)}`);

        if (fraction >= 1 && !snipping) {
          snipping = true;
        }
        if (snipping) {
          if (reduced) {
            snipT = 1;
          } else {
            [snipT, snipVel] = springStep(snipT, snipVel, 1, SNIP_K, SNIP_C, dt);
          }
        }
      }

      paintLayers();
      paintGhost();
      paintFeed(now);

      const radiusDone = Math.abs(radius - growTarget) < 0.05 && Math.abs(radiusVel) < 0.05;
      const ghostDone =
        (!knownNow && ghostR < 0.05) || (knownNow && Math.abs(ghostR - MAX_R) < 0.05);
      const snipDone =
        snipping && (reduced || (Math.abs(snipT - 1) < 0.01 && Math.abs(snipVel) < 0.02));
      if (knownNow && radiusDone && ghostDone && snipping && snipDone) {
        settled = true;
        feed.style.opacity = "0";
      }

      raf = settled && knownNow ? 0 : requestAnimationFrame(loop);
    };

    raf = requestAnimationFrame(loop);

    return () => {
      cancelAnimationFrame(raf);
      wakeRef.current = null;
    };
    // mount-once engine; total/loaded are read live via refs each frame
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div
      role="progressbar"
      aria-label={ariaLabel}
      aria-valuemin={phase === "determinate" ? 0 : undefined}
      aria-valuemax={phase === "determinate" ? 100 : undefined}
      aria-valuenow={phase === "determinate" ? valueNow : undefined}
      aria-valuetext={valueText}
      className={`inline-flex flex-col items-center gap-2 ${className}`}
    >
      <svg
        viewBox="0 0 216 184"
        width={216}
        height={184}
        aria-hidden="true"
        className="max-w-full"
        data-thread-spool-svg
      >
        {/* feed line: taut thread entering from a fixed anchor */}
        <line
          ref={feedRef}
          x1={ANCHOR_X}
          y1={ANCHOR_Y}
          x2={ANCHOR_X}
          y2={ANCHOR_Y}
          stroke="var(--foreground)"
          strokeWidth={1}
          style={{ transition: "opacity 260ms ease-out" }}
        />

        {/* ghost ring: the final wound radius, revealed the moment total is known */}
        <circle
          ref={ghostRef}
          cx={CX}
          cy={CY}
          r={0.001}
          fill="none"
          stroke="var(--ns-muted)"
          strokeWidth={1}
          strokeDasharray="3 3"
        />

        {/* wound thread: concentric layers, drawn back-to-front */}
        <g>
          {Array.from({ length: N_LAYERS }, (_, i) => (
            <circle
              key={i}
              ref={(el) => {
                layersRef.current[i] = el;
              }}
              cx={CX}
              cy={CY}
              r={CORE_R}
              fill="none"
              stroke="var(--foreground)"
              strokeWidth={1}
              style={{ opacity: 0 }}
            />
          ))}
        </g>

        {/* spool hub: two flanges */}
        <circle cx={CX} cy={CY} r={CORE_R} fill="none" stroke="var(--border)" strokeWidth={1} />
        <circle cx={CX} cy={CY} r={CORE_R - 5} fill="none" stroke="var(--border)" strokeWidth={1} />
      </svg>

      <span
        ref={captionRef}
        aria-hidden="true"
        data-wind-caption
        data-phase={phase}
        className="font-mono text-[11px] tracking-wide text-ns-muted"
      >
        {captionText}
      </span>

      <div aria-live="polite" className="sr-only">
        {announce}
      </div>
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
} from "react";

// ---------------------------------------------------------------------------
// TailPane — a `tail -f` log viewer with a real bounded ring buffer, an ASCII
// severity column and follow-mode that detaches the instant you scroll up.
//
// The three things that make it honest rather than a log-shaped animation:
//  1. memory is bounded — appends overwrite the oldest slot of a fixed
//     Array(capacity); nothing grows without limit, however long it runs.
//  2. the stream is deterministic — one LCG drives both the inter-line delay
//     and the severity draw, so cadence jitters like real traffic instead of
//     ticking, and the same seed always replays the same log.
//  3. appends never render per-line — they land in a ref and flush to React
//     through ONE rAF-coalesced setState per frame, and only the rows inside
//     the viewport are in the DOM (fixed 18px rows, absolute positioning).
// ---------------------------------------------------------------------------

export type LogSeverity = "DEBUG" | "INFO" | "WARN" | "ERROR";

export type LogLine = {
  /** monotonically increasing sequence number; also its ring slot (seq % capacity) */
  seq: number;
  /** pre-formatted HH:MM:SS.mmm wall clock */
  time: string;
  sev: LogSeverity;
  service: string;
  message: string;
};

export interface LogViewerAsciiTailProps {
  /** ring buffer size — appends past this overwrite the oldest line. Default 2000. */
  capacity?: number;
  /** LCG seed; the same seed replays the same stream exactly. Default 20240804. */
  seed?: number;
  /** lines synthesised before the stream starts, so the pane is dense at rest. Default 200. */
  initialLines?: number;
  /** service column values drawn from. */
  services?: string[];
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** accessible name for the log pane */
  "aria-label"?: string;
}

const ROW_H = 18; // px — fixed, which is what makes windowing trivial
const OVERSCAN = 6; // rows rendered beyond the viewport, each side
const NEAR_BOTTOM = 8; // px — inside this, follow re-attaches
const SERVICE_W = 11; // chars, padded so the pipes form true vertical rules

const LEVELS: LogSeverity[] = ["DEBUG", "INFO", "WARN", "ERROR"];
const LEVEL_RANK: Record<LogSeverity, number> = { DEBUG: 0, INFO: 1, WARN: 2, ERROR: 3 };

const GLYPH: Record<LogSeverity, string> = {
  DEBUG: "·", // ·
  INFO: "─", // ─
  WARN: "≡", // ≡
  ERROR: "█", // █
};

// glyph AND weight together, never hue alone. The faintest ink is a muted
// tint, NOT `text-border` — --border is tuned for 1px hairlines and is
// invisible as type on the light theme (#ebebeb on #ffffff).
const FAINT = "text-ns-muted/45";

const SEV_INK: Record<LogSeverity, string> = {
  DEBUG: FAINT,
  INFO: "text-ns-muted",
  WARN: "text-foreground font-medium",
  ERROR: "text-ns-accent font-semibold",
};

const DEFAULT_SERVICES = [
  "api-gateway",
  "auth-worker",
  "orders-svc",
  "ledger-sync",
  "edge-cache",
  "search-idx",
];

const MESSAGES: Record<LogSeverity, string[]> = {
  DEBUG: [
    "cache hit ratio 0.94 over 512 keys",
    "span emitted trace=9f2a1c parent=3bd881",
    "pool idle 12/32 connections",
    "heartbeat ack in 4ms",
    "resolved 3 dns records ttl=30s",
    "compacted 18 segments into 6",
    "token introspection cached 240s",
  ],
  INFO: [
    "GET /v2/orders 200 in 38ms",
    "POST /v2/checkout 201 in 112ms",
    "session refreshed for user 84213",
    "published 128 events to orders.v2",
    "shard 4 rebalanced in 1.8s",
    "index snapshot written 41MB",
    "GET /health 200 in 2ms",
    "invoice 4471 settled in 74ms",
  ],
  WARN: [
    "retry 2/5 after connection reset",
    "queue depth 8420 above soft limit",
    "p99 latency 812ms over budget",
    "clock skew 340ms against peer 3",
    "rate limit 80% consumed for key ak_19",
  ],
  ERROR: [
    "upstream 502 after 3 retries",
    "deadline exceeded on shard 7",
    "checksum mismatch on segment 41",
    "connection refused to ledger:5432",
  ],
};

// deterministic LCG — one stream drives delay, severity, service and message
function nextSeed(s: number): number {
  return (s * 1664525 + 1013904223) >>> 0;
}

function formatClock(msOfDay: number): string {
  const ms = Math.floor(msOfDay) % 86_400_000;
  const h = Math.floor(ms / 3_600_000);
  const m = Math.floor(ms / 60_000) % 60;
  const s = Math.floor(ms / 1000) % 60;
  const f = Math.floor(ms) % 1000;
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}.${String(f).padStart(3, "0")}`;
}

function drawSeverity(r: number): LogSeverity {
  if (r < 0.42) return "DEBUG";
  if (r < 0.82) return "INFO";
  if (r < 0.95) return "WARN";
  return "ERROR";
}

/** splits a message around every case-insensitive occurrence of `q` */
function inkMatches(message: string, q: string) {
  if (!q) return [{ text: message, hit: false }];
  const out: { text: string; hit: boolean }[] = [];
  const hay = message.toLowerCase();
  const needle = q.toLowerCase();
  let i = 0;
  for (;;) {
    const at = hay.indexOf(needle, i);
    if (at === -1) break;
    if (at > i) out.push({ text: message.slice(i, at), hit: false });
    out.push({ text: message.slice(at, at + needle.length), hit: true });
    i = at + needle.length;
  }
  if (i < message.length) out.push({ text: message.slice(i), hit: false });
  return out;
}

const useIsoLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

export function LogViewerAsciiTail({
  capacity = 2000,
  seed = 20240804,
  initialLines = 200,
  services = DEFAULT_SERVICES,
  className = "",
  "aria-label": ariaLabel = "Application log, live tail",
}: LogViewerAsciiTailProps) {
  // an inline `services={[...]}` prop would otherwise be a new array every
  // render, re-creating appendOne and re-running the seed effect forever;
  // rebuilding from a joined key makes the identity depend on the CONTENT
  const serviceKey = services.join("|");
  const serviceList = useMemo(() => serviceKey.split("|"), [serviceKey]);

  // --- ring buffer ---------------------------------------------------------
  const ringRef = useRef<(LogLine | undefined)[]>([]);
  const totalRef = useRef(0); // total lines ever appended; head slot = total % capacity
  const rngRef = useRef(seed >>> 0);
  const clockRef = useRef(43_471_882); // 12:04:31.882, a fixed start so SSR/CSR agree

  // --- flush plumbing (one setState per frame, never one per line) ----------
  const [tick, setTick] = useState(0);
  const rafRef = useRef(0);
  const newRef = useRef(0);
  const [newCount, setNewCount] = useState(0);

  // --- follow mode ---------------------------------------------------------
  const paneRef = useRef<HTMLDivElement>(null);
  const followRef = useRef(true);
  const [follow, setFollow] = useState(true);

  // --- windowing -----------------------------------------------------------
  const [range, setRange] = useState({ start: 0, end: 60 });

  // --- filters -------------------------------------------------------------
  const [minLevel, setMinLevel] = useState<LogSeverity>("DEBUG");
  const [query, setQuery] = useState("");

  // --- motion / lifecycle --------------------------------------------------
  const [reduced, setReduced] = useState(false);
  const [running, setRunning] = useState(true);
  const runningRef = useRef(true);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const scheduleFlush = useCallback(() => {
    if (rafRef.current) return;
    rafRef.current = requestAnimationFrame(() => {
      rafRef.current = 0;
      setNewCount(newRef.current);
      setTick((t) => t + 1);
    });
  }, []);

  /** synthesise exactly one line and write it into its ring slot */
  const appendOne = useCallback(() => {
    let s = rngRef.current;

    s = nextSeed(s);
    const delay = 90 + (s / 4_294_967_296) * 260;
    clockRef.current += delay;

    s = nextSeed(s);
    const sev = drawSeverity(s / 4_294_967_296);

    s = nextSeed(s);
    const service =
      serviceList[Math.floor((s / 4_294_967_296) * serviceList.length)] ?? serviceList[0]!;

    s = nextSeed(s);
    const pool = MESSAGES[sev];
    const message = pool[Math.floor((s / 4_294_967_296) * pool.length)] ?? pool[0]!;

    rngRef.current = s;

    const seq = totalRef.current;
    ringRef.current[seq % capacity] = {
      seq,
      time: formatClock(clockRef.current),
      sev,
      service,
      message,
    };
    totalRef.current = seq + 1;
    if (!followRef.current) newRef.current += 1;
    return delay;
  }, [capacity, serviceList]);

  // reduced motion
  useEffect(() => {
    const mql = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => {
      setReduced(mql.matches);
      if (mql.matches) {
        setRunning(false);
        runningRef.current = false;
      }
    };
    update();
    mql.addEventListener("change", update);
    return () => mql.removeEventListener("change", update);
  }, []);

  // seed the buffer once — the pane is dense and legible before any motion
  useEffect(() => {
    ringRef.current = new Array(capacity);
    totalRef.current = 0;
    rngRef.current = seed >>> 0;
    clockRef.current = 43_471_882;
    for (let i = 0; i < initialLines; i++) appendOne();
    newRef.current = 0;
    setNewCount(0);
    setTick((t) => t + 1);
  }, [capacity, seed, initialLines, appendOne]);

  // the stream: a self-rescheduling timeout whose delay is drawn from the LCG,
  // paused while the tab is hidden and while `running` is false
  useEffect(() => {
    runningRef.current = running;
    if (!running) return;

    let cancelled = false;
    // document.hidden truly stops the generator (no polling); visibilitychange
    // restarts it, so a backgrounded tab costs nothing.
    const step = () => {
      if (cancelled || document.hidden) {
        timerRef.current = null;
        return;
      }
      const delay = appendOne();
      scheduleFlush();
      timerRef.current = setTimeout(step, delay);
    };
    timerRef.current = setTimeout(step, 120);

    const onVis = () => {
      if (!document.hidden && !cancelled && timerRef.current === null) {
        timerRef.current = setTimeout(step, 120);
      }
    };
    document.addEventListener("visibilitychange", onVis);

    return () => {
      cancelled = true;
      document.removeEventListener("visibilitychange", onVis);
      if (timerRef.current) clearTimeout(timerRef.current);
      timerRef.current = null;
    };
  }, [running, appendOne, scheduleFlush]);

  useEffect(() => () => cancelAnimationFrame(rafRef.current), []);

  // --- derived views -------------------------------------------------------
  const lines = useMemo(() => {
    const total = totalRef.current;
    const from = Math.max(0, total - capacity);
    const out: LogLine[] = [];
    for (let i = from; i < total; i++) {
      const l = ringRef.current[i % capacity];
      if (l) out.push(l);
    }
    return out;
    // tick is the flush signal; the data itself lives in refs
  }, [tick, capacity]);

  const rows = useMemo(() => {
    const min = LEVEL_RANK[minLevel];
    const q = query.trim().toLowerCase();
    return lines.filter(
      (l) =>
        LEVEL_RANK[l.sev] >= min &&
        (q === "" ||
          l.message.toLowerCase().includes(q) ||
          l.service.toLowerCase().includes(q))
    );
  }, [lines, minLevel, query]);

  // --- scroll plumbing -----------------------------------------------------
  const measure = useCallback(() => {
    const el = paneRef.current;
    if (!el) return;
    const start = Math.max(0, Math.floor(el.scrollTop / ROW_H) - OVERSCAN);
    const end = Math.ceil((el.scrollTop + el.clientHeight) / ROW_H) + OVERSCAN;
    setRange((r) => (r.start === start && r.end === end ? r : { start, end }));
  }, []);

  const attach = useCallback(() => {
    followRef.current = true;
    newRef.current = 0;
    setNewCount(0);
    setFollow(true);
    const el = paneRef.current;
    if (el) el.scrollTop = el.scrollHeight;
    measure();
  }, [measure]);

  const onScroll = useCallback(() => {
    const el = paneRef.current;
    if (!el) return;
    const distance = el.scrollHeight - el.scrollTop - el.clientHeight;
    if (distance > NEAR_BOTTOM) {
      if (followRef.current) {
        followRef.current = false;
        setFollow(false);
      }
    } else if (!followRef.current) {
      followRef.current = true;
      newRef.current = 0;
      setNewCount(0);
      setFollow(true);
    }
    measure();
  }, [measure]);

  // pin to the bottom while following — after every flush and every filter change
  useIsoLayoutEffect(() => {
    const el = paneRef.current;
    if (!el) return;
    if (followRef.current) el.scrollTop = el.scrollHeight;
    measure();
  }, [rows, measure]);

  const onKeyDown = (e: ReactKeyboardEvent<HTMLDivElement>) => {
    const el = paneRef.current;
    if (!el) return;
    if (e.key === "End") {
      e.preventDefault();
      attach();
    } else if (e.key === "Home") {
      e.preventDefault();
      el.scrollTop = 0;
    } else if (e.key === "ArrowDown") {
      e.preventDefault();
      el.scrollTop += ROW_H;
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      el.scrollTop -= ROW_H;
    } else if (e.key === "PageDown") {
      e.preventDefault();
      el.scrollTop += el.clientHeight - ROW_H;
    } else if (e.key === "PageUp") {
      e.preventDefault();
      el.scrollTop -= el.clientHeight - ROW_H;
    }
  };

  // roving tabindex: selecting with the arrow keys must MOVE focus too,
  // otherwise the ring is left behind on a button that is now tabIndex=-1
  const radioRefs = useRef<Partial<Record<LogSeverity, HTMLButtonElement | null>>>({});

  const moveLevel = (to: LogSeverity) => {
    setMinLevel(to);
    radioRefs.current[to]?.focus();
  };

  const onLevelKeyDown = (e: ReactKeyboardEvent<HTMLDivElement>) => {
    const i = LEVELS.indexOf(minLevel);
    if (e.key === "ArrowRight" || e.key === "ArrowDown") {
      e.preventDefault();
      moveLevel(LEVELS[Math.min(LEVELS.length - 1, i + 1)]!);
    } else if (e.key === "ArrowLeft" || e.key === "ArrowUp") {
      e.preventDefault();
      moveLevel(LEVELS[Math.max(0, i - 1)]!);
    } else if (e.key === "Home") {
      e.preventDefault();
      moveLevel(LEVELS[0]!);
    } else if (e.key === "End") {
      e.preventDefault();
      moveLevel(LEVELS[LEVELS.length - 1]!);
    }
  };

  const visible = rows.slice(range.start, range.end);
  const inputId = "log-tail-filter";

  return (
    <div
      className={`flex h-full min-h-0 flex-col overflow-hidden rounded-md border border-border bg-background font-mono text-xs ${className}`}
    >
      {/* header: the level control doubles as the glyph legend */}
      <div className="flex flex-wrap items-center gap-x-4 gap-y-2 border-b border-border px-3 py-2">
        <span className="text-ns-muted">
          tail -f <span className="text-foreground">/var/log/edge.log</span>
        </span>

        <div
          role="radiogroup"
          aria-label="Minimum severity"
          onKeyDown={onLevelKeyDown}
          className="flex items-center overflow-hidden rounded-sm border border-border"
        >
          {LEVELS.map((lv) => {
            const on = lv === minLevel;
            return (
              <button
                key={lv}
                ref={(node) => {
                  radioRefs.current[lv] = node;
                }}
                type="button"
                role="radio"
                aria-checked={on}
                tabIndex={on ? 0 : -1}
                onClick={() => setMinLevel(lv)}
                className={`px-2 py-1 whitespace-pre transition-colors duration-100 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-[-2px] focus-visible:outline-ns-accent ${
                  on ? "bg-surface text-foreground" : "text-ns-muted hover:text-foreground"
                }`}
              >
                <span className={on ? "" : SEV_INK[lv]}>{GLYPH[lv]}</span> {lv}
              </button>
            );
          })}
        </div>

        <div className="flex items-center gap-2">
          <label htmlFor={inputId} className="text-ns-muted">
            grep
          </label>
          <input
            id={inputId}
            type="search"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="502"
            spellCheck={false}
            className="w-28 rounded-sm border border-border bg-surface px-2 py-1 font-mono text-xs text-foreground placeholder:text-ns-muted/60 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-[-2px] focus-visible:outline-ns-accent"
          />
        </div>

        <span className="ml-auto tabular-nums text-ns-muted">
          {rows.length}/{lines.length} lines · ring {capacity}
        </span>
      </div>

      <div className="relative flex min-h-0 flex-1">
        {/* the log pane */}
        <div
          ref={paneRef}
          data-log-pane
          role="log"
          aria-live="off"
          aria-label={ariaLabel}
          tabIndex={0}
          onScroll={onScroll}
          onKeyDown={onKeyDown}
          className="min-h-0 flex-1 overflow-y-auto overflow-x-hidden focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-[-2px] focus-visible:outline-ns-accent"
        >
          <div className="relative w-full" style={{ height: rows.length * ROW_H }}>
            {visible.map((l, i) => (
              <div
                key={l.seq}
                className="absolute inset-x-0 flex items-center whitespace-pre px-3 text-ns-muted transition-colors duration-100 hover:bg-surface hover:text-foreground"
                style={{ top: (range.start + i) * ROW_H, height: ROW_H }}
              >
                <span className="tabular-nums">{l.time}</span>
                <span className={FAINT}>{" │ "}</span>
                <span className={SEV_INK[l.sev]}>{GLYPH[l.sev]}</span>
                <span className={FAINT}>{" │ "}</span>
                <span>{l.service.padEnd(SERVICE_W)}</span>
                <span className={FAINT}>{" │ "}</span>
                <span>
                  {inkMatches(l.message, query.trim()).map((seg, k) => (
                    <span key={k} className={seg.hit ? "text-ns-accent" : undefined}>
                      {seg.text}
                    </span>
                  ))}
                </span>
              </div>
            ))}
          </div>
        </div>

        {/* detach bar — the count of what arrived while you were reading */}
        {!follow && (
          <button
            type="button"
            onClick={attach}
            className="absolute inset-x-0 bottom-0 border-t border-border bg-surface py-1.5 text-center whitespace-pre text-ns-muted transition-colors duration-100 hover:text-foreground focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-[-2px] focus-visible:outline-ns-accent"
          >
            {"└─ "}
            <span className="tabular-nums text-ns-accent">{newCount}</span>
            {` new line${newCount === 1 ? "" : "s"} ─ End to follow ─┘`}
          </button>
        )}
      </div>

      {reduced && (
        <div className="flex items-center justify-between gap-3 border-t border-border px-3 py-2">
          <span className="text-ns-muted">
            {running
              ? `stream running — ${lines.length} lines in the ring`
              : `stream paused — ${lines.length} lines loaded`}
          </span>
          <button
            type="button"
            onClick={() => setRunning((r) => !r)}
            className="rounded-sm border border-border px-2 py-1 whitespace-pre text-ns-muted transition-colors duration-100 hover:border-ns-muted hover:text-foreground focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-[-2px] focus-visible:outline-ns-accent"
          >
            {running ? "■ pause stream" : "▸ resume stream"}
          </button>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// LogoCloudSettle — a trust wall of abstract marks that SETTLES onto its
// grid rather than simply fading in: each tile starts lifted, shrunk and
// tilted a few degrees, then drops into its resting transform on a per-item
// stagger with a slight overshoot (a spring-approximating cubic-bezier, the
// same shape this registry already uses for its digit/avatar settles) so it
// reads as physically landing, not just appearing. This is a distinct job
// from avatar-stack-flock: that component mills continuously as a boids
// flock at rest and only resolves into a row on hover/focus; this cloud is
// static at rest and settles ONCE per viewport entry via an
// IntersectionObserver, replaying only if it leaves and re-enters view —
// there is no continuous simulation here at all, just a CSS transition
// driven by one boolean.
//
// Marks are abstract, generated geometric glyphs (no real company logos or
// wordmarks), so there is nothing here with trademark exposure. Every color
// is a Tailwind token utility (text-ns-muted / border-border / bg-surface),
// never a literal, so both themes are correct without any getComputedStyle
// bookkeeping — this is plain DOM, not canvas.
// ---------------------------------------------------------------------------

type ShapeId = "ring" | "diamond" | "triangle" | "plus" | "hex" | "venn" | "chevron" | "grid";

export interface Mark {
  id: string;
  name: string;
  shape: ShapeId;
}

const DEFAULT_MARKS: Mark[] = [
  { id: "m1", name: "Nimbus", shape: "ring" },
  { id: "m2", name: "Vectra", shape: "diamond" },
  { id: "m3", name: "Solstice", shape: "triangle" },
  { id: "m4", name: "Ashgrove", shape: "plus" },
  { id: "m5", name: "Continuum", shape: "hex" },
  { id: "m6", name: "Rivermark", shape: "venn" },
  { id: "m7", name: "Anchorpoint", shape: "chevron" },
  { id: "m8", name: "Greywolf", shape: "grid" },
];

const STAGGER_MS = 42;
const DURATION = 560;
const EASE = "cubic-bezier(0.22, 1.7, 0.36, 1)"; // spring-approximating overshoot, same family as this registry's other settles
const DROP_PX = 22;

function MarkGlyph({ shape, className = "" }: { shape: ShapeId; className?: string }) {
  const common = {
    viewBox: "0 0 24 24",
    className,
    fill: "none",
    stroke: "currentColor",
    strokeWidth: 1.6,
    strokeLinecap: "round" as const,
    strokeLinejoin: "round" as const,
    "aria-hidden": true,
  };
  switch (shape) {
    case "ring":
      return (
        <svg {...common}>
          <circle cx="12" cy="12" r="8" />
          <circle cx="12" cy="12" r="1.6" fill="currentColor" stroke="none" />
        </svg>
      );
    case "diamond":
      return (
        <svg {...common}>
          <path d="M12 3 L20 12 L12 21 L4 12 Z" />
        </svg>
      );
    case "triangle":
      return (
        <svg {...common}>
          <path d="M12 4 L20 19 L4 19 Z" />
          <line x1="6" y1="19" x2="18" y2="19" />
        </svg>
      );
    case "plus":
      return (
        <svg {...common}>
          <line x1="12" y1="4" x2="12" y2="20" />
          <line x1="4" y1="12" x2="20" y2="12" />
        </svg>
      );
    case "hex":
      return (
        <svg {...common}>
          <path d="M12 3 L19.5 7.5 L19.5 16.5 L12 21 L4.5 16.5 L4.5 7.5 Z" />
        </svg>
      );
    case "venn":
      return (
        <svg {...common}>
          <circle cx="9.5" cy="12" r="6" />
          <circle cx="14.5" cy="12" r="6" />
        </svg>
      );
    case "chevron":
      return (
        <svg {...common}>
          <path d="M5 8 L12 14 L19 8" />
          <path d="M5 15 L12 21 L19 15" />
        </svg>
      );
    case "grid":
      return (
        <svg {...common}>
          <rect x="4" y="4" width="6" height="6" />
          <rect x="14" y="4" width="6" height="6" />
          <rect x="4" y="14" width="6" height="6" />
          <rect x="14" y="14" width="6" height="6" />
        </svg>
      );
    default:
      return null;
  }
}

export function LogoCloudSettle({
  marks = DEFAULT_MARKS,
  label = "Trusted by teams shipping with ns-ui",
  className = "",
}: {
  /** the logos, settling into place */
  marks?: Mark[];
  /** accessible name for the logo group */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const [settled, setSettled] = useState(false);
  const reducedRef = useRef(false);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    reducedRef.current = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reducedRef.current) {
      setSettled(true);
      return;
    }
    const io = new IntersectionObserver(
      (entries) => {
        const hit = entries[0];
        if (!hit) return;
        setSettled(hit.isIntersecting);
      },
      { threshold: 0.2 }
    );
    io.observe(root);
    return () => io.disconnect();
  }, []);

  return (
    <div className={className}>
      {label && (
        <p className="mb-5 text-center font-mono text-xs uppercase tracking-widest text-ns-muted">{label}</p>
      )}
      <div
        ref={rootRef}
        data-settled={settled}
        role="list"
        aria-label={label}
        className="grid grid-cols-2 gap-3 sm:grid-cols-4"
      >
        {marks.map((m, i) => (
          <div
            key={m.id}
            role="listitem"
            className="flex flex-col items-center justify-center gap-2 rounded-md border border-border bg-surface px-4 py-6 text-ns-muted"
            style={{
              transitionProperty: "transform, opacity",
              transitionDuration: `${DURATION}ms`,
              transitionTimingFunction: EASE,
              transitionDelay: settled ? `${i * STAGGER_MS}ms` : "0ms",
              transform: settled
                ? "translateY(0px) scale(1) rotate(0deg)"
                : `translateY(-${DROP_PX}px) scale(0.9) rotate(-4deg)`,
              opacity: settled ? 1 : 0,
              willChange: "transform, opacity",
            }}
          >
            <MarkGlyph shape={m.shape} className="h-7 w-7" />
            <span className="font-mono text-[10px] uppercase tracking-widest">{m.name}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// LugCageTally — an ambient loading glyph shaped as a row of five pin
// wheels spinning past a fixed read position, each engaged pin nudging a
// segmented tally bar forward one notch. Five wheels, mutually-prime full
// rotation periods (7s, 6s, 5s, 4s, 3.5s), each ringed with 8 pins in a
// fixed active/inactive pattern set once at mount. Every 45deg of rotation
// carries the next pin past the fixed 12-o'clock read mark; if that pin is
// active, its rim mark brightens in a 90ms luminance flash and the tally
// bar's next notch fills. Because the five periods share no small common
// factor their combined phase relationship doesn't repeat for well over a
// minute, so the wheels keep looking freshly decorrelated on any viewing.
// Pure SVG + direct-DOM rAF writes (refs only, no React state on the hot
// path); geometry is recomputed only on resize.
// ---------------------------------------------------------------------------

const WHEEL_COUNT = 5;
const PINS_PER_WHEEL = 8;
const PIN_STEP_DEG = 360 / PINS_PER_WHEEL;
// deg/s for each wheel — periods 7s, 6s, 5s, 4s, 3.5s, chosen to share no
// small common factor so the combined pattern reads as freshly decorrelated
const RATES_DEG_S = [51.42857142857143, 60, 72, 90, 102.85714285714286];
const FLASH_MS = 90;
const TALLY_LENGTH = 24;
const NOTCH_FILL_MS = 140;
const NOTCH_FADE_MS = 200;

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** exactly half the pins active, shuffled per wheel — set once, never
 * touched again, so a wheel's pattern never gives itself away except
 * through the read-event flash. */
function buildPattern(rand: () => number): boolean[] {
  const arr = [true, true, true, true, false, false, false, false];
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    const tmp = arr[i]!;
    arr[i] = arr[j]!;
    arr[j] = tmp;
  }
  return arr;
}

/** which pin index sits at the fixed 12-o'clock read mark after N pin-steps
 * of rotation, given pin 0 starts there at t=0 — the wheel visits pins in
 * descending index order as it turns, so this walks backward mod 8. */
function pinAtReadMark(stepCount: number): number {
  return (PINS_PER_WHEEL - (stepCount % PINS_PER_WHEEL)) % PINS_PER_WHEEL;
}

interface Layout {
  w: number;
  h: number;
  wheelR: number;
  wheelCx: number[];
  wheelCy: number;
  tallyX: number;
  tallyY: number;
  tallyW: number;
  tallyH: number;
  notchW: number;
  notchGap: number;
}

function computeLayout(w: number, h: number): Layout {
  const smaller = Math.max(1, Math.min(w, h));
  const d = smaller / 6.5; // wheel diameter
  const wheelR = d / 2;
  const tallyH = d * 0.3;
  const gapH = d * 0.55;
  const rowW = WHEEL_COUNT * d + (WHEEL_COUNT - 1) * gapH;
  const vGap = d * 0.4;
  const contentH = d + vGap + tallyH;
  const topY = Math.max(0, (h - contentH) / 2);
  const wheelCy = topY + wheelR;
  const startX = Math.max(0, (w - rowW) / 2) + wheelR;
  const wheelCx = Array.from({ length: WHEEL_COUNT }, (_, i) => startX + i * (d + gapH));
  const tallyX = Math.max(0, (w - rowW) / 2);
  const tallyY = topY + d + vGap;
  const notchGap = tallyH * 0.22;
  const notchW = (rowW - notchGap * (TALLY_LENGTH - 1)) / TALLY_LENGTH;
  return {
    w,
    h,
    wheelR,
    wheelCx,
    wheelCy,
    tallyX,
    tallyY,
    tallyW: rowW,
    tallyH,
    notchW: Math.max(1, notchW),
    notchGap,
  };
}

export interface LugCageTallyProps {
  /** text announced via the component's own aria-live region */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function LugCageTally({ label = "Loading", className = "" }: LugCageTallyProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);
  const wheelGroupRefs = useRef<(SVGGElement | null)[]>([]);
  const pinRefs = useRef<(SVGLineElement | null)[][]>(
    Array.from({ length: WHEEL_COUNT }, () => [])
  );
  const notchRefs = useRef<(SVGRectElement | null)[]>([]);
  const [dims, setDims] = useState({ w: 0, h: 0 });

  const layout = useMemo(() => computeLayout(dims.w, dims.h), [dims.w, dims.h]);

  // container sizing — smaller dimension drives every other measurement
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const ro = new ResizeObserver((entries) => {
      const entry = entries[0];
      if (!entry) return;
      const box = entry.contentRect;
      setDims({ w: box.width, h: box.height });
    });
    ro.observe(root);
    return () => ro.disconnect();
  }, []);

  // patterns fixed once per mount, independent of layout/resize
  const patternsRef = useRef<boolean[][] | null>(null);
  if (!patternsRef.current) {
    const rand = mulberry32(Date.now() ^ 0x9e3779b9);
    patternsRef.current = Array.from({ length: WHEEL_COUNT }, () => buildPattern(rand));
  }

  useEffect(() => {
    const root = rootRef.current;
    if (!root || layout.w <= 0 || layout.h <= 0) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const patterns = patternsRef.current!;
    let disposed = false;
    let visible = true;
    let raf = 0;
    let startTime = 0;
    const stepCounts = new Array(WHEEL_COUNT).fill(0);
    const flashTimers: (ReturnType<typeof setTimeout> | undefined)[][] = Array.from(
      { length: WHEEL_COUNT },
      () => []
    );
    let rollTimer: ReturnType<typeof setTimeout> | undefined;
    const tallyFilled: boolean[] = new Array(TALLY_LENGTH).fill(false);

    const setNotchStyle = (el: SVGRectElement | null, filled: boolean, withTransition: boolean) => {
      if (!el) return;
      el.style.transition = withTransition
        ? `fill-opacity ${NOTCH_FILL_MS}ms ease-out`
        : "none";
      el.style.fillOpacity = filled ? "0.8" : "0";
    };

    const advanceTally = () => {
      const filledCount = tallyFilled.filter(Boolean).length;
      if (filledCount < TALLY_LENGTH) {
        const idx = tallyFilled.findIndex((v) => !v);
        if (idx < 0) return;
        tallyFilled[idx] = true;
        setNotchStyle(notchRefs.current[idx] ?? null, true, true);
        return;
      }
      // rolling window: fade the leftmost notch, then re-index the strip
      // and fill the rightmost — no hard reset, the bar never empties
      const first = notchRefs.current[0];
      if (first) {
        first.style.transition = `fill-opacity ${NOTCH_FADE_MS}ms ease`;
        first.style.fillOpacity = "0";
      }
      if (rollTimer) clearTimeout(rollTimer);
      rollTimer = setTimeout(() => {
        if (disposed) return;
        for (let i = 0; i < TALLY_LENGTH - 1; i++) tallyFilled[i] = tallyFilled[i + 1] ?? true;
        tallyFilled[TALLY_LENGTH - 1] = false;
        for (let i = 0; i < TALLY_LENGTH - 1; i++) {
          setNotchStyle(notchRefs.current[i] ?? null, true, false);
        }
        tallyFilled[TALLY_LENGTH - 1] = true;
        setNotchStyle(notchRefs.current[TALLY_LENGTH - 1] ?? null, true, true);
      }, NOTCH_FADE_MS);
    };

    const flashPin = (wheelIdx: number, pinIdx: number) => {
      const el = pinRefs.current[wheelIdx]?.[pinIdx];
      if (!el) return;
      const pending = flashTimers[wheelIdx]?.[pinIdx];
      if (pending) clearTimeout(pending);
      el.style.transition = "none";
      el.style.opacity = "1";
      requestAnimationFrame(() => {
        if (disposed) return;
        el.style.transition = `opacity ${FLASH_MS}ms ease-out`;
        el.style.opacity = "0.85";
      });
      const arr = flashTimers[wheelIdx];
      if (arr) {
        arr[pinIdx] = setTimeout(() => {
          if (el) el.style.opacity = "0.85";
        }, FLASH_MS + 20);
      }
    };

    const applyFrame = (elapsedSec: number) => {
      for (let i = 0; i < WHEEL_COUNT; i++) {
        const rate = RATES_DEG_S[i] ?? 0;
        const angle = (rate * elapsedSec) % 360;
        const g = wheelGroupRefs.current[i];
        if (g) g.setAttribute("transform", `rotate(${angle.toFixed(2)} ${layout.wheelCx[i] ?? 0} ${layout.wheelCy})`);

        const cumSteps = Math.floor((rate * elapsedSec) / PIN_STEP_DEG);
        let prev = stepCounts[i] ?? 0;
        // guard against a huge dt (tab backgrounded) firing hundreds of
        // catch-up reads at once — only the most recent read is meaningful
        if (cumSteps - prev > PINS_PER_WHEEL) prev = cumSteps - PINS_PER_WHEEL;
        while (prev < cumSteps) {
          prev++;
          const pinIdx = pinAtReadMark(prev);
          if (patterns[i]?.[pinIdx]) {
            flashPin(i, pinIdx);
            advanceTally();
          }
        }
        stepCounts[i] = cumSteps;
      }
    };

    const loop = (now: number) => {
      raf = 0;
      if (!visible) return;
      if (startTime === 0) startTime = now;
      applyFrame((now - startTime) / 1000);
      raf = requestAnimationFrame(loop);
    };

    if (reduced) {
      // STATIC_PHASE: five wheels frozen at distinct phases, at least two
      // pin marks caught mid-fade, tally sitting at ~60% — the frame that
      // best shows "mechanism mid-tally" rather than a clean idle state
      const freezeAngles = [22, 168, 301, 74, 249];
      for (let i = 0; i < WHEEL_COUNT; i++) {
        const g = wheelGroupRefs.current[i];
        if (g) g.setAttribute("transform", `rotate(${freezeAngles[i]} ${layout.wheelCx[i] ?? 0} ${layout.wheelCy})`);
      }
      const midFadeWheels = [1, 3];
      for (let i = 0; i < WHEEL_COUNT; i++) {
        for (let p = 0; p < PINS_PER_WHEEL; p++) {
          const el = pinRefs.current[i]?.[p];
          if (!el) continue;
          el.style.transition = "none";
          el.style.opacity = midFadeWheels.includes(i) && p === 0 ? "0.93" : "0.85";
        }
      }
      const filledUpTo = Math.round(TALLY_LENGTH * 0.6);
      for (let i = 0; i < TALLY_LENGTH; i++) {
        setNotchStyle(notchRefs.current[i] ?? null, i < filledUpTo, false);
      }
      return () => {
        disposed = true;
      };
    }

    raf = requestAnimationFrame(loop);

    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && !raf) raf = requestAnimationFrame(loop);
    });
    io.observe(root);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      raf = 0;
      io.disconnect();
      if (rollTimer) clearTimeout(rollTimer);
      for (const wheel of flashTimers) {
        for (const t of wheel) if (t) clearTimeout(t);
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [layout.w, layout.h]);

  return (
    <div
      ref={rootRef}
      role="status"
      aria-live="polite"
      data-lug-cage-tally
      className={`relative flex h-full w-full items-center justify-center ${className}`}
    >
      <svg
        ref={svgRef}
        aria-hidden="true"
        focusable="false"
        className="h-full w-full"
        viewBox={`0 0 ${Math.max(1, layout.w)} ${Math.max(1, layout.h)}`}
      >
        {layout.wheelCx.map((cx, i) => (
          <g key={i}>
            {/* fixed 12-o'clock read mark — the highest-contrast reference
                point, does not rotate */}
            <line
              x1={cx}
              y1={layout.wheelCy - layout.wheelR - layout.wheelR * 0.32}
              x2={cx}
              y2={layout.wheelCy - layout.wheelR - layout.wheelR * 0.08}
              stroke="var(--foreground)"
              strokeWidth={Math.max(1, layout.wheelR * 0.09)}
              strokeLinecap="round"
            />
            <g
              ref={(el) => {
                wheelGroupRefs.current[i] = el;
              }}
            >
              <circle
                cx={cx}
                cy={layout.wheelCy}
                r={layout.wheelR}
                fill="none"
                stroke="var(--foreground)"
                strokeOpacity={0.55}
                strokeWidth={Math.max(1, layout.wheelR * 0.06)}
              />
              {Array.from({ length: PINS_PER_WHEEL }, (_, p) => {
                const angle = (p * PIN_STEP_DEG - 90) * (Math.PI / 180);
                const rOuter = layout.wheelR;
                const rInner = layout.wheelR * 0.78;
                const x1 = cx + Math.cos(angle) * rOuter;
                const y1 = layout.wheelCy + Math.sin(angle) * rOuter;
                const x2 = cx + Math.cos(angle) * rInner;
                const y2 = layout.wheelCy + Math.sin(angle) * rInner;
                return (
                  <line
                    key={p}
                    ref={(el) => {
                      const arr = pinRefs.current[i];
                      if (arr) arr[p] = el;
                    }}
                    x1={x1}
                    y1={y1}
                    x2={x2}
                    y2={y2}
                    stroke="var(--foreground)"
                    strokeOpacity={0.85}
                    strokeWidth={Math.max(1, layout.wheelR * 0.1)}
                    strokeLinecap="round"
                  />
                );
              })}
            </g>
          </g>
        ))}

        {Array.from({ length: TALLY_LENGTH }, (_, i) => {
          const x = layout.tallyX + i * (layout.notchW + layout.notchGap);
          return (
            <g key={i}>
              <rect
                x={x}
                y={layout.tallyY}
                width={layout.notchW}
                height={layout.tallyH}
                fill="none"
                stroke="var(--border)"
                strokeWidth={1}
              />
              <rect
                ref={(el) => {
                  notchRefs.current[i] = el;
                }}
                x={x}
                y={layout.tallyY}
                width={layout.notchW}
                height={layout.tallyH}
                fill="var(--foreground)"
                fillOpacity={0}
              />
            </g>
          );
        })}
      </svg>
      <span className="sr-only">{label}</span>
    </div>
  );
}

"use client";

import { useCallback, useId, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// ManifoldBleed — a connected app's standing grants drawn as a valve
// manifold. Each scope is one gate valve sitting right at the header where
// it branches off the account (the reservoir, left) toward the app (right):
// granted means the valve stands open and its line runs full of ink;
// revoking closes the valve and drains that line BACKWARD toward the valve
// itself, because the branch downstream of a closed valve empties, not the
// header behind it — authority returns to its source.
//
// The single governing scalar per row is `fill` (0 or 1, post-ack). Every
// other visual fact is a pure, LINEAR function of it, so no rAF tween is
// needed anywhere — one CSS transition on stroke-dashoffset/stroke-width/
// transform reproduces exactly what animating the scalar itself and
// re-deriving every frame would, because linear maps commute with easing:
//   - stroke-dashoffset = 1 - fill   (pathLength=1 line; the retreating
//     dash edge — rounded via strokeLinecap — IS the meniscus, no separate
//     marker needed)
//   - stroke-width       = 1 + 2*fill (a pressurized full line reads
//     bolder than the hairline it drains down to)
//   - valve-handle angle  = (1 - fill) * 90deg (0 = parallel to flow/open,
//     90 = perpendicular/closed — how a real ball/gate valve handle reads)
// The drained pipe never disappears: its --ns-muted hairline track is
// always rendered underneath the ink, at full length, for every scope —
// that hairline is the permanent record of what was once granted, and the
// list never shortens or removes a row.
//
// Falsifiable constraint: fill changes ONLY after the caller's
// onGrantChange (or, absent one, a short simulated network round trip)
// resolves. Clicking a valve does not touch `fill` — it flips a `pending`
// flag (aria-busy, a "…" status word) and waits; optimistic fill on grant
// is the deliberately forbidden shortcut, because this is the one panel
// whose entire job is telling the truth about what access exists right
// now. A second click on a row already in flight is ignored rather than
// queued or raced.
//
// A11y: each row is a real role=switch button (native <button>, click and
// Space/Enter both work for free) whose accessible name is the scope's own
// label via aria-labelledby, plus aria-describedby pointing at its
// plain-language description and aria-checked mirroring the CONFIRMED
// state (never the optimistic click). A single shared aria-live=polite
// region announces "{label} granted" / "{label} revoked" once the server
// actually confirms — never on the click itself. Every pipe/valve SVG is
// aria-hidden; the graphics are redundant encoding of the real switch
// state and the visible "Active"/"Revoked" status word beside each row,
// never the only carrier of it. prefers-reduced-motion drops every
// transition — fill, stroke-width and valve angle all land on their
// target value in one step, no drain animation, still fully legible via
// the status word and the valve's resting position.
//
// Distinct from transfer-list-siphon (which MOVES members between two
// columns as a bulk transfer gesture with beads that travel and land) and
// from envelope-window (the one-time consent/occlusion moment before a
// grant exists): this is the standing state afterward — a persistent flow
// diagram of continuing draw, where revocation has a direction and always
// leaves a drained line behind rather than removing anything from view.
// ---------------------------------------------------------------------------

export interface ManifoldScope {
  /** stable id, also the value threaded through onGrantChange */
  id: string;
  /** short scope name, e.g. "read:repos" — becomes the switch's accessible name */
  label: string;
  /** plain-language description of what this scope allows */
  description: string;
  /** initial granted state. Default true (most rows on a grants page start granted). */
  defaultGranted?: boolean;
}

export interface ManifoldBleedProps {
  /** the connected app these scopes belong to, e.g. "Northlake CI" */
  appName: string;
  /** the scopes/permissions, rendered top to bottom in this order */
  scopes: ManifoldScope[];
  /**
   * Called with the scope id and the requested next state. Resolve to
   * confirm the change (fill then updates and the row announces); reject
   * (or throw) to leave the grant unchanged. Omit to use a built-in
   * simulated ~320ms round trip, useful for demos without a real backend.
   */
  onGrantChange?: (scopeId: string, granted: boolean) => Promise<void> | void;
  className?: string;
}

const ACK_MS = 320;
const DRAIN_MS = 600;
const EASE = "cubic-bezier(0.16, 1, 0.3, 1)"; // ease-out-expo: fast off the valve, settles slow — draining under gravity, not a linear pour

function simulateAck(): Promise<void> {
  return new Promise((resolve) => {
    setTimeout(resolve, ACK_MS);
  });
}

export function ManifoldBleed({ appName, scopes, onGrantChange, className = "" }: ManifoldBleedProps) {
  const uid = useId();
  const [granted, setGranted] = useState<Record<string, boolean>>(() => {
    const init: Record<string, boolean> = {};
    for (const scope of scopes) init[scope.id] = scope.defaultGranted ?? true;
    return init;
  });
  const [pending, setPending] = useState<Record<string, boolean>>({});
  const pendingRef = useRef(pending);
  pendingRef.current = pending;
  const [announce, setAnnounce] = useState("");

  const toggle = useCallback(
    async (scope: ManifoldScope) => {
      if (pendingRef.current[scope.id]) return; // already in flight — ignore, don't queue or race
      const next = !(granted[scope.id] ?? true);
      setPending((p) => ({ ...p, [scope.id]: true }));
      try {
        await (onGrantChange?.(scope.id, next) ?? simulateAck());
        setGranted((g) => ({ ...g, [scope.id]: next }));
        setAnnounce(`${scope.label} ${next ? "granted" : "revoked"}`);
      } catch {
        setAnnounce(`${scope.label} unchanged`);
      } finally {
        setPending((p) => {
          const rest = { ...p };
          delete rest[scope.id];
          return rest;
        });
      }
    },
    [granted, onGrantChange]
  );

  return (
    <div className={`w-full max-w-md ${className}`}>
      <style>{CSS}</style>

      <div className="flex items-center justify-between border-b border-border pb-2.5">
        <div className="flex items-center gap-1.5">
          <span aria-hidden className="h-2 w-2 rounded-full bg-foreground" />
          <span className="font-mono text-[11px] uppercase tracking-wide text-ns-muted">Your account</span>
        </div>
        <div className="flex items-center gap-1.5">
          <span className="font-mono text-[11px] uppercase tracking-wide text-ns-muted">{appName}</span>
          <span aria-hidden className="h-2 w-2 rounded-full border border-border" />
        </div>
      </div>

      <ul className="flex flex-col">
        {scopes.map((scope) => {
          const isGranted = granted[scope.id] ?? true;
          const isPending = !!pending[scope.id];
          const fill = isGranted ? 1 : 0;
          const angle = (1 - fill) * 90;
          const strokeW = 1 + 2 * fill;
          const labelId = `${uid}-${scope.id}-label`;
          const descId = `${uid}-${scope.id}-desc`;

          return (
            <li key={scope.id} className="flex items-center gap-3 border-b border-border/60 py-3 last:border-0">
              <button
                type="button"
                role="switch"
                aria-checked={isGranted}
                aria-labelledby={labelId}
                aria-describedby={descId}
                aria-busy={isPending || undefined}
                data-manifold-scope={scope.id}
                onClick={() => toggle(scope)}
                className="ns-manifold-valve group relative grid h-7 w-7 shrink-0 place-items-center rounded-full outline-none transition-colors duration-150 hover:bg-border/40 focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background"
              >
                <svg viewBox="0 0 28 28" width={28} height={28} aria-hidden focusable="false" className="overflow-visible">
                  <circle
                    cx={14}
                    cy={14}
                    r={9}
                    fill="var(--background)"
                    stroke="var(--border)"
                    strokeWidth={1.25}
                    className="ns-manifold-body"
                  />
                  <line
                    className="ns-manifold-handle"
                    x1={14 - 6.5}
                    y1={14}
                    x2={14 + 6.5}
                    y2={14}
                    stroke="var(--foreground)"
                    strokeWidth={2.5}
                    strokeLinecap="round"
                    style={{ transform: `rotate(${angle}deg)` }}
                  />
                </svg>
              </button>

              <div className="flex min-w-[7.25rem] flex-col">
                <span id={labelId} className="font-mono text-xs text-foreground">
                  {scope.label}
                </span>
                <span id={descId} className="text-[11px] leading-snug text-ns-muted">
                  {scope.description}
                </span>
              </div>

              <div className="flex flex-1 items-center gap-1.5">
                <svg
                  className="h-4 flex-1"
                  viewBox="0 0 100 16"
                  preserveAspectRatio="none"
                  aria-hidden
                  focusable="false"
                >
                  {/* permanent hairline track — evidence of the line even once fully drained */}
                  <line x1={0} y1={8} x2={100} y2={8} stroke="var(--ns-muted)" strokeWidth={1} />
                  {/* ink — the only thing this component ever animates */}
                  <line
                    className="ns-manifold-ink"
                    x1={0}
                    y1={8}
                    x2={100}
                    y2={8}
                    pathLength={1}
                    stroke="var(--foreground)"
                    strokeLinecap="round"
                    strokeDasharray="1 1"
                    style={{ strokeWidth: strokeW, strokeDashoffset: 1 - fill }}
                  />
                </svg>
                <span aria-hidden className="h-2 w-2 shrink-0 rounded-full border border-border" />
              </div>

              <span
                data-manifold-status={scope.id}
                data-granted={isGranted}
                className="w-14 shrink-0 text-right font-mono text-[10px] uppercase tracking-wide text-ns-muted"
              >
                {isPending ? "…" : isGranted ? "Active" : "Revoked"}
              </span>
            </li>
          );
        })}
      </ul>

      <span role="status" aria-live="polite" aria-atomic="true" className="sr-only">
        {announce}
      </span>
    </div>
  );
}

const CSS = `
.ns-manifold-ink { transition: stroke-dashoffset ${DRAIN_MS}ms ${EASE}, stroke-width ${DRAIN_MS}ms ${EASE}; }
.ns-manifold-handle { transform-box: fill-box; transform-origin: center; transition: transform ${DRAIN_MS}ms ${EASE}; }
.ns-manifold-body { transition: stroke 150ms ease-out; }
.ns-manifold-valve:hover .ns-manifold-body { stroke: var(--foreground); }
@media (prefers-reduced-motion: reduce) {
  .ns-manifold-ink, .ns-manifold-handle { transition: none; }
}
`;

"use client";

import { useEffect, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// MapChoroplethAscii — the registry's first choropleth, and queue item #15
// (zero prior coverage). The geography is entirely synthetic: a fixed grid
// partitioned by hand-placed seed points into a Voronoi tessellation, not a
// real country, coastline or GeoJSON import — no geo dependency, nothing
// that could read as a political claim. Nearest neighbours: heatmap-year-
// stipple keys stipple density to a date, heatmap-calendar-tide and table-
// heat-shimmer key intensity to time-of-day or a threshold — none of the
// three tessellates a plane into regions with borders.
//
// Region fill is the family's shared ASCII ramp ' .:-=+*#%@', density
// tracking each region's synthetic index value, with a small deterministic
// per-cell jitter (a fixed hash, not Math.random) so a solid region still
// reads as ink texture rather than a flat block. The mechanic: hovering the
// map (exact cell under the pointer) or moving keyboard focus through the
// region list (Tab into the map, then ArrowLeft/ArrowRight) ISOLATES that
// region — every other region's cells drop to a fixed low "background"
// density while the hovered region keeps its true density and gains a thin
// var(--ns-accent) boundary trace — and the legend rescales its domain to a
// tight band around the hovered value instead of the global min/max,
// highlighting exactly where that value falls. Losing hover/focus restores
// the global view. Pure var(--foreground) ink; var(--ns-accent) is reserved
// for the isolated region's boundary and the legend marker only.
// ---------------------------------------------------------------------------

const RAMP = " .:-=+*#%@";

export interface ChoroplethRegion {
  id: number;
  label: string;
  /** Voronoi seed, in grid-cell coordinates */
  seedCol: number;
  seedRow: number;
  /** synthetic index value, arbitrary units */
  value: number;
}

export interface MapChoroplethAsciiProps {
  /** the shaded regions */
  regions?: ChoroplethRegion[];
  /** heading above the map */
  title?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

// hand-placed seeds across a fixed grid — an abstract tessellation, not a
// real place. Values are an invented "regional index", clearly synthetic.
const DEFAULT_REGIONS: ChoroplethRegion[] = [
  { id: 0, label: "Sector 1", seedCol: 3, seedRow: 3, value: 62 },
  { id: 1, label: "Sector 2", seedCol: 9, seedRow: 2, value: 34 },
  { id: 2, label: "Sector 3", seedCol: 16, seedRow: 3, value: 88 },
  { id: 3, label: "Sector 4", seedCol: 21, seedRow: 6, value: 45 },
  { id: 4, label: "Sector 5", seedCol: 14, seedRow: 7, value: 21 },
  { id: 5, label: "Sector 6", seedCol: 5, seedRow: 9, value: 70 },
  { id: 6, label: "Sector 7", seedCol: 10, seedRow: 11, value: 55 },
  { id: 7, label: "Sector 8", seedCol: 19, seedRow: 10, value: 39 },
];

const COLS = 24;
const ROWS = 13;
const CELL = 15;
const TOP_PAD = 10;
const LEFT_PAD = 10;
const RIGHT_PAD = 10;
const LEGEND_H = 44;
const MAP_W = COLS * CELL;
const MAP_H = ROWS * CELL;
const BAND = 14; // half-width of the rescaled legend band around a hovered value
const ENTRANCE_MS = 340;

interface Tokens {
  fg: string;
  bg: string;
  muted: string;
  border: string;
  accent: string;
}

function readTokens(): Tokens {
  const cs = getComputedStyle(document.documentElement);
  const get = (name: string, fallback: string) => cs.getPropertyValue(name).trim() || fallback;
  return {
    fg: get("--foreground", "#171717"),
    bg: get("--background", "#ffffff"),
    muted: get("--ns-muted", "#4d4d4d"),
    border: get("--border", "#ebebeb"),
    accent: get("--ns-accent", "#006bff"),
  };
}

function useTokens(): Tokens {
  const [tokens, setTokens] = useState<Tokens>(() =>
    typeof document === "undefined"
      ? { fg: "#171717", bg: "#ffffff", muted: "#4d4d4d", border: "#ebebeb", accent: "#006bff" }
      : readTokens()
  );
  useEffect(() => {
    const sync = () => setTokens(readTokens());
    sync();
    const mo = new MutationObserver(sync);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style"] });
    return () => mo.disconnect();
  }, []);
  return tokens;
}

// fixed hash, not Math.random — deterministic per-cell jitter for ink texture
function hashCell(c: number, r: number): number {
  const n = Math.sin(c * 12.9898 + r * 78.233) * 43758.5453;
  return n - Math.floor(n);
}

export function MapChoroplethAscii({ regions, title = "Regional index", className = "" }: MapChoroplethAsciiProps) {
  const data = useMemo(() => regions ?? DEFAULT_REGIONS, [regions]);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const hitRef = useRef<HTMLDivElement>(null);
  const tokens = useTokens();
  const [hoverId, setHoverId] = useState<number | null>(null);
  const [activeIdx, setActiveIdx] = useState(0);
  const rafRef = useRef(0);
  const mountAtRef = useRef(0);

  const reducedRef = useRef(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => {
      reducedRef.current = mq.matches;
    };
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);

  const globalMin = Math.min(...data.map((r) => r.value));
  const globalMax = Math.max(...data.map((r) => r.value));
  const globalSpan = Math.max(1e-6, globalMax - globalMin);

  // Voronoi cell -> region id, computed once per region set
  const cellRegion = useMemo(() => {
    const buf = new Uint8Array(COLS * ROWS);
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        let best = 0;
        let bestDist = Infinity;
        for (const region of data) {
          const dx = c - region.seedCol;
          const dy = r - region.seedRow;
          const d = dx * dx + dy * dy;
          if (d < bestDist) {
            bestDist = d;
            best = region.id;
          }
        }
        buf[r * COLS + c] = best;
      }
    }
    return buf;
  }, [data]);

  useEffect(() => {
    mountAtRef.current = performance.now();
  }, [data]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const viewW = LEFT_PAD + MAP_W + RIGHT_PAD;
    const viewH = TOP_PAD + MAP_H + LEGEND_H;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = viewW * dpr;
    canvas.height = viewH * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    // legend domain: global by default, tightened around the hovered value
    const hoveredRegion = hoverId !== null ? data.find((r) => r.id === hoverId) ?? null : null;
    const legendMin = hoveredRegion ? Math.max(globalMin, hoveredRegion.value - BAND) : globalMin;
    const legendMax = hoveredRegion ? Math.min(globalMax, hoveredRegion.value + BAND) : globalMax;
    const legendSpan = Math.max(1e-6, legendMax - legendMin);

    const draw = () => {
      const now = performance.now();
      const t = reducedRef.current ? 1 : Math.min(1, (now - mountAtRef.current) / ENTRANCE_MS);
      ctx.clearRect(0, 0, viewW, viewH);

      ctx.font = `${CELL - 4}px "GeistMono", ui-monospace, monospace`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";

      for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
          const regionId = cellRegion[r * COLS + c];
          const region = data.find((rg) => rg.id === regionId)!;
          const isolating = hoverId !== null;
          const isolated = isolating && regionId !== hoverId;
          const norm = (region.value - globalMin) / globalSpan;
          const jitter = (hashCell(c, r) - 0.5) * 0.14;
          const baseLevel = Math.min(RAMP.length - 1, Math.max(1, Math.round((norm + jitter) * (RAMP.length - 1))));
          const level = isolated ? 2 : baseLevel;
          const ch = RAMP[level];
          if (ch === " ") continue;
          const cx = LEFT_PAD + c * CELL + CELL / 2;
          const cy = TOP_PAD + r * CELL + CELL / 2;
          ctx.fillStyle = isolated ? tokens.muted : tokens.fg;
          ctx.globalAlpha = t * (isolated ? 0.55 : 1);
          ctx.fillText(ch, cx, cy);
          ctx.globalAlpha = 1;
        }
      }

      // region boundaries
      ctx.strokeStyle = tokens.border;
      ctx.lineWidth = 1;
      for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
          const id = cellRegion[r * COLS + c];
          const rightId = c + 1 < COLS ? cellRegion[r * COLS + c + 1] : id;
          const downId = r + 1 < ROWS ? cellRegion[(r + 1) * COLS + c] : id;
          const x = LEFT_PAD + (c + 1) * CELL;
          const y = TOP_PAD + (r + 1) * CELL;
          if (rightId !== id) {
            ctx.beginPath();
            ctx.moveTo(x + 0.5, TOP_PAD + r * CELL);
            ctx.lineTo(x + 0.5, TOP_PAD + (r + 1) * CELL);
            ctx.stroke();
          }
          if (downId !== id) {
            ctx.beginPath();
            ctx.moveTo(LEFT_PAD + c * CELL, y + 0.5);
            ctx.lineTo(LEFT_PAD + (c + 1) * CELL, y + 0.5);
            ctx.stroke();
          }
        }
      }

      // isolated region's own boundary re-traced in accent
      if (hoverId !== null) {
        ctx.strokeStyle = tokens.accent;
        ctx.lineWidth = 1.5;
        for (let r = 0; r < ROWS; r++) {
          for (let c = 0; c < COLS; c++) {
            const id = cellRegion[r * COLS + c];
            if (id !== hoverId) continue;
            const rightId = c + 1 < COLS ? cellRegion[r * COLS + c + 1] : -1;
            const downId = r + 1 < ROWS ? cellRegion[(r + 1) * COLS + c] : -1;
            const leftId = c - 1 >= 0 ? cellRegion[r * COLS + c - 1] : -1;
            const upId = r - 1 >= 0 ? cellRegion[(r - 1) * COLS + c] : -1;
            const x0 = LEFT_PAD + c * CELL;
            const y0 = TOP_PAD + r * CELL;
            if (rightId !== id) {
              ctx.beginPath();
              ctx.moveTo(x0 + CELL + 0.5, y0);
              ctx.lineTo(x0 + CELL + 0.5, y0 + CELL);
              ctx.stroke();
            }
            if (leftId !== id) {
              ctx.beginPath();
              ctx.moveTo(x0 + 0.5, y0);
              ctx.lineTo(x0 + 0.5, y0 + CELL);
              ctx.stroke();
            }
            if (downId !== id) {
              ctx.beginPath();
              ctx.moveTo(x0, y0 + CELL + 0.5);
              ctx.lineTo(x0 + CELL, y0 + CELL + 0.5);
              ctx.stroke();
            }
            if (upId !== id) {
              ctx.beginPath();
              ctx.moveTo(x0, y0 + 0.5);
              ctx.lineTo(x0 + CELL, y0 + 0.5);
              ctx.stroke();
            }
          }
        }
      }

      // legend — ramp gradient bar, domain rescales around the hovered value
      const legendY = TOP_PAD + MAP_H + 20;
      const legendW = MAP_W;
      const swatches = 20;
      ctx.font = `${CELL - 3}px "GeistMono", ui-monospace, monospace`;
      for (let i = 0; i < swatches; i++) {
        const frac = i / (swatches - 1);
        const level = Math.round(frac * (RAMP.length - 1));
        ctx.fillStyle = tokens.fg;
        ctx.fillText(RAMP[Math.max(level, 1)], LEFT_PAD + (i + 0.5) * (legendW / swatches), legendY);
      }
      ctx.fillStyle = tokens.muted;
      ctx.font = `9px "GeistMono", ui-monospace, monospace`;
      ctx.textAlign = "left";
      ctx.fillText(legendMin.toFixed(0), LEFT_PAD, legendY + 14);
      ctx.textAlign = "right";
      ctx.fillText(legendMax.toFixed(0), LEFT_PAD + legendW, legendY + 14);

      if (hoveredRegion) {
        const markFrac = Math.min(1, Math.max(0, (hoveredRegion.value - legendMin) / legendSpan));
        const mx = LEFT_PAD + markFrac * legendW;
        ctx.strokeStyle = tokens.accent;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(mx, legendY - 10);
        ctx.lineTo(mx, legendY + 6);
        ctx.stroke();
      }

      if (t < 1 && !reducedRef.current) rafRef.current = requestAnimationFrame(draw);
    };

    draw();
    return () => cancelAnimationFrame(rafRef.current);
  }, [cellRegion, data, tokens, hoverId, globalMin, globalMax, globalSpan, reducedRef]);

  const setHoverFromEvent = (e: { clientX: number; clientY: number }) => {
    const el = hitRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const c = Math.min(COLS - 1, Math.max(0, Math.floor(x / CELL)));
    const r = Math.min(ROWS - 1, Math.max(0, Math.floor(y / CELL)));
    const id = cellRegion[r * COLS + c];
    setHoverId(id);
    const idx = data.findIndex((rg) => rg.id === id);
    if (idx >= 0) setActiveIdx(idx);
  };

  const hoveredRegion = hoverId !== null ? data.find((r) => r.id === hoverId) ?? null : null;

  return (
    <figure className={`ns-mca inline-block ${className}`} aria-label={`${title}, choropleth map`}>
      <style>{CSS}</style>
      <div className="flex items-center justify-between gap-3 pb-2">
        <span className="font-mono text-xs tracking-widest text-ns-muted">{title.toUpperCase()}</span>
        <span className="font-mono text-[11px] text-ns-muted tabular-nums">
          {hoveredRegion ? `${hoveredRegion.label} · ${hoveredRegion.value}` : `${data.length} sectors`}
        </span>
      </div>
      <div className="relative" style={{ width: LEFT_PAD + MAP_W + RIGHT_PAD, maxWidth: "100%" }}>
        <canvas
          ref={canvasRef}
          aria-hidden="true"
          className="ns-mca-canvas"
          style={{
            width: LEFT_PAD + MAP_W + RIGHT_PAD,
            height: TOP_PAD + MAP_H + LEGEND_H,
            maxWidth: "100%",
            display: "block",
          }}
        />
        <div
          ref={hitRef}
          role="button"
          tabIndex={0}
          aria-label={
            hoveredRegion
              ? `${hoveredRegion.label}, index ${hoveredRegion.value}. Arrow keys cycle sectors.`
              : "Choropleth map. Point at a sector, or use arrow keys to cycle sectors."
          }
          className="ns-mca-hit absolute cursor-pointer rounded-sm outline-none"
          style={{ left: LEFT_PAD, top: TOP_PAD, width: MAP_W, height: MAP_H }}
          onPointerMove={(e) => setHoverFromEvent(e)}
          onPointerLeave={() => setHoverId(null)}
          onFocus={() => setHoverId(data[activeIdx]?.id ?? data[0].id)}
          onBlur={() => setHoverId(null)}
          onKeyDown={(e) => {
            if (e.key === "ArrowRight" || e.key === "ArrowDown") {
              e.preventDefault();
              const next = (activeIdx + 1) % data.length;
              setActiveIdx(next);
              setHoverId(data[next].id);
            } else if (e.key === "ArrowLeft" || e.key === "ArrowUp") {
              e.preventDefault();
              const next = (activeIdx - 1 + data.length) % data.length;
              setActiveIdx(next);
              setHoverId(data[next].id);
            } else if (e.key === "Escape") {
              setHoverId(null);
            }
          }}
        />
      </div>
    </figure>
  );
}

const CSS = `
.ns-mca-hit:focus-visible { outline: 2px solid var(--ns-accent); outline-offset: 2px; }
`;

"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// GlyphScrubTicker — a marquee that is an instrument, not a loop. Unlike a
// plain auto-scrolling ticker, the tape is GRABBABLE: pointerdown+drag scrubs
// it directly under the cursor (1:1, no easing while held), release throws it
// with momentum that decays under friction, and — the mechanic no sibling
// ticker has — per-character LEGIBILITY IS A FUNCTION OF INSTANTANEOUS SPEED.
// Below a resolve threshold (ambient auto-scroll speed, and the tail of every
// fling) each character renders its real glyph. Above it (an active scrub or
// the fast part of a fling) visible cells swap to a churning noise charset,
// re-rolled every couple of frames — the tape reads as blurred motion, then
// snaps back into focus the instant it slows down. One direct-DOM rAF loop
// drives position + per-cell textContent; no React state on the hot path.
// The real string is always exposed via aria-label per item (role=listitem,
// roving tabindex); the glyph cells themselves are aria-hidden, so a screen
// reader always hears the resolved value regardless of what's on screen.
// ---------------------------------------------------------------------------

export interface GlyphScrubTickerProps {
  /** items rendered in order, looped end to end */
  items: string[];
  /** glyph placed between items, including at the wrap seam */
  separator?: string;
  /** ambient auto-scroll speed in px/s while untouched and unpaused */
  speed?: number;
  /** px/s above which cells blur into noise glyphs (ambient speed should sit under this) */
  resolveThreshold?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const NOISE_CHARSET = "░▒▓#%&@*+=-:.";
const FRICTION = 0.94; // per-frame velocity decay after release (~60fps)
const MIN_FLING_V = 40; // px/s below which a release doesn't fling at all
const CELL_PROBE_CHAR = "0";

export function GlyphScrubTicker({
  items,
  separator = "/",
  speed = 34,
  resolveThreshold = 260,
  className = "",
}: GlyphScrubTickerProps) {
  const uid = useId().replace(/:/g, "");
  const containerRef = useRef<HTMLDivElement>(null);
  const trackRef = useRef<HTMLDivElement>(null);
  const probeRef = useRef<HTMLSpanElement>(null);
  const [reduced, setReduced] = useState(false);
  const [paused, setPaused] = useState(false);

  const tape = useMemo(() => {
    if (items.length === 0) return "";
    return ` ${items.join(` ${separator} `)} ${separator} `;
  }, [items, separator]);

  const label = useMemo(() => items.join(", "), [items]);

  const pausedRef = useRef(paused);
  pausedRef.current = paused;

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  useEffect(() => {
    const container = containerRef.current;
    const track = trackRef.current;
    const probe = probeRef.current;
    if (!container || !track || !probe || tape.length === 0) return;

    let cellWidth = probe.getBoundingClientRect().width || 8;
    let cells: HTMLSpanElement[] = [];
    let offset = 0; // fractional tape position, in characters
    let velocity = 0; // characters/sec, signed (negative = feeding forward)
    let raf = 0;
    let last = 0;
    let dragging = false;
    let dragLastX = 0;
    let dragLastT = 0;
    let hovering = false;
    let focused = false;

    const charAt = (absIndex: number) =>
      tape[((Math.floor(absIndex) % tape.length) + tape.length) % tape.length] ?? " ";

    const rebuild = () => {
      cellWidth = probe.getBoundingClientRect().width || cellWidth;
      const w = container.getBoundingClientRect().width;
      const count = Math.max(1, Math.ceil(w / cellWidth) + 1);
      track.textContent = "";
      cells = [];
      for (let i = 0; i < count; i++) {
        const span = document.createElement("span");
        span.setAttribute("aria-hidden", "true");
        span.style.display = "inline-block";
        span.style.width = `${cellWidth}px`;
        span.style.textAlign = "center";
        span.style.flexShrink = "0";
        track.appendChild(span);
        cells.push(span);
      }
      paint(0);
    };

    // paints every visible cell from the current offset + a resolved-vs-noise
    // decision driven by |speedPxPerSec|. Cells always keep a stable-width
    // monospace glyph (real char or a noise charset member) — never blank —
    // so nothing reflows.
    const paint = (speedPxPerSec: number) => {
      const blurred = Math.abs(speedPxPerSec) > resolveThreshold;
      for (let i = 0; i < cells.length; i++) {
        const idx = offset + i;
        if (blurred) {
          cells[i]!.textContent =
            NOISE_CHARSET[Math.floor(Math.random() * NOISE_CHARSET.length)]!;
        } else {
          cells[i]!.textContent = charAt(idx);
        }
      }
    };

    if (reduced) {
      rebuild();
      const ro = new ResizeObserver(rebuild);
      ro.observe(container);
      return () => ro.disconnect();
    }

    rebuild();

    const loop = (now: number) => {
      const dt = last ? Math.min(0.05, (now - last) / 1000) : 1 / 60;
      last = now;

      if (dragging) {
        // 1:1 scrub — position and velocity both come straight from pointer
        // deltas in onMove; nothing to integrate here.
      } else {
        const stopped = pausedRef.current || hovering || focused;
        const target = stopped ? 0 : -speed / cellWidth;
        if (Math.abs(velocity) > MIN_FLING_V / cellWidth || Math.abs(target) > 0.001) {
          // momentum decay toward the ambient target speed
          velocity += (target - velocity) * (1 - Math.pow(FRICTION, dt * 60));
        } else {
          velocity = target;
        }
        offset += velocity * dt;
      }

      paint(velocity * cellWidth);
      raf = requestAnimationFrame(loop);
    };
    raf = requestAnimationFrame(loop);

    const clientXToCharDelta = (dx: number) => -dx / cellWidth;

    const onPointerDown = (e: PointerEvent) => {
      dragging = true;
      dragLastX = e.clientX;
      dragLastT = performance.now();
      velocity = 0;
      container.setPointerCapture(e.pointerId);
    };
    const onPointerMove = (e: PointerEvent) => {
      if (!dragging) return;
      const now = performance.now();
      const dtMs = Math.max(1, now - dragLastT);
      const dx = e.clientX - dragLastX;
      const charDelta = clientXToCharDelta(dx);
      offset += charDelta;
      velocity = (charDelta / dtMs) * 1000; // chars/sec, feeds the resolve check
      dragLastX = e.clientX;
      dragLastT = now;
      paint(velocity * cellWidth);
    };
    const endDrag = () => {
      if (!dragging) return;
      dragging = false;
      if (Math.abs(velocity * cellWidth) < MIN_FLING_V) velocity = 0;
    };

    container.addEventListener("pointerdown", onPointerDown);
    container.addEventListener("pointermove", onPointerMove);
    container.addEventListener("pointerup", endDrag);
    container.addEventListener("pointercancel", endDrag);
    // Named, not inline: this effect re-runs on every `speed` /
    // `resolveThreshold` / reduced-motion change, and anonymous handlers
    // cannot be removed below — a consumer driving `speed` from state piled
    // four more onto the same node per change.
    const onPointerEnter = () => {
      hovering = true;
    };
    const onPointerLeave = () => {
      hovering = false;
    };
    const onFocusIn = () => {
      focused = true;
    };
    const onFocusOut = () => {
      focused = false;
    };
    container.addEventListener("pointerenter", onPointerEnter);
    container.addEventListener("pointerleave", onPointerLeave);
    container.addEventListener("focusin", onFocusIn);
    container.addEventListener("focusout", onFocusOut);

    // Arrow keys nudge the scrub position directly (fast enough repeats
    // briefly cross the resolve threshold so keyboard users can feel the
    // same blur-then-settle the pointer path gets).
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key !== "ArrowLeft" && e.key !== "ArrowRight") return;
      e.preventDefault();
      const dir = e.key === "ArrowRight" ? 1 : -1;
      offset += dir * 3;
      velocity = dir * (resolveThreshold / cellWidth) * 1.4;
      paint(velocity * cellWidth);
    };
    container.addEventListener("keydown", onKeyDown);

    const ro = new ResizeObserver(rebuild);
    ro.observe(container);

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      container.removeEventListener("pointerdown", onPointerDown);
      container.removeEventListener("pointermove", onPointerMove);
      container.removeEventListener("pointerup", endDrag);
      container.removeEventListener("pointercancel", endDrag);
      container.removeEventListener("keydown", onKeyDown);
      container.removeEventListener("pointerenter", onPointerEnter);
      container.removeEventListener("pointerleave", onPointerLeave);
      container.removeEventListener("focusin", onFocusIn);
      container.removeEventListener("focusout", onFocusOut);
    };
  }, [tape, speed, resolveThreshold, reduced]);

  return (
    <div className={`flex items-center gap-3 rounded-[12px] border border-border bg-background p-2 ${className}`}>
      <button
        type="button"
        aria-label={paused ? "Resume ticker" : "Pause ticker"}
        aria-pressed={paused}
        onClick={() => setPaused((p) => !p)}
        className="flex h-8 w-8 shrink-0 items-center justify-center rounded-[6px] border border-border text-foreground transition-colors hover:bg-border/40 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
      >
        {paused ? (
          <svg width="10" height="10" viewBox="0 0 10 10" aria-hidden="true">
            <path d="M1 0.5 L9 5 L1 9.5 Z" fill="currentColor" />
          </svg>
        ) : (
          <svg width="10" height="10" viewBox="0 0 10 10" aria-hidden="true">
            <rect x="1" y="0.5" width="3" height="9" fill="currentColor" />
            <rect x="6" y="0.5" width="3" height="9" fill="currentColor" />
          </svg>
        )}
      </button>

      <div
        ref={containerRef}
        role="list"
        aria-label={label}
        tabIndex={0}
        className="relative h-9 flex-1 touch-none select-none overflow-hidden font-mono text-sm text-foreground [cursor:grab] active:[cursor:grabbing] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
      >
        <span
          ref={probeRef}
          aria-hidden="true"
          className="pointer-events-none absolute -left-[9999px] top-0"
          style={{ visibility: "hidden", whiteSpace: "pre" }}
        >
          {CELL_PROBE_CHAR}
        </span>
        {reduced ? (
          <div className="flex h-full items-center gap-2 overflow-hidden whitespace-nowrap">
            {items.map((it, i) => (
              <span key={`${it}-${i}-${uid}`} role="listitem" aria-label={it} className="border-r border-border pr-2 last:border-none">
                {it}
              </span>
            ))}
          </div>
        ) : (
          <div ref={trackRef} className="flex h-full items-stretch will-change-[transform]" />
        )}
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// MasonryAsciiSettle — a masonry gallery where every tile renders as live
// ASCII halftone (a deterministic noise field mapped to a " .:-=+*#%@" glyph
// ramp, redrawn on <canvas>) that RESOLVES from a coarse print to a fine one
// exactly as the tile drops into its packed column slot: glyph pitch and drop
// offset ease together on one rAF loop, so "settling" is a real resolution
// change, not a decorative fade layered over a CSS `columns` snap. Column
// packing is this component's own shortest-column-first math (own math, not
// CSS `columns`, which flows top-to-bottom per column and can't be re-packed
// on demand). A container resize that crosses a column-count breakpoint
// re-packs every tile into its new column and replays the full coarse ->
// fine drop for all of them, staggered by row order — the reflow IS the
// interaction. This differs from gallery-coverflow-caustic (a 3D coverflow
// carousel with frosted-glass caustics, one card focused at a time, no
// masonry packing and no ASCII), testimonial-wall-reflow (FLIP-reflows real
// text cards on an expand/collapse toggle, no image content and no
// resolution mechanic), and logo-cloud-settle (drops static SVG marks once
// per viewport entry with no live rendering and no re-pack on resize).
// ---------------------------------------------------------------------------

export interface MasonryAsciiTile {
  id: string;
  title: string;
  /** noise seed for the generated ASCII field */
  seed: number;
  /** height as a multiple of the column width */
  aspect: number;
}

export interface MasonryAsciiSettleProps {
  /** the tiles, laid into the masonry grid and settling into place */
  tiles: MasonryAsciiTile[];
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const GAP = 14;
const COARSE_PITCH = 15;
const FINE_PITCH = 6;
const DROP_MS = 620;
const STAGGER_MS = 55;
const DROP_PX = 26;
const RAMP = " .:-=+*#%@";

function columnsFor(width: number): number {
  if (width < 520) return 1;
  if (width < 860) return 2;
  return 3;
}

function hash2(x: number, y: number) {
  const n = Math.sin(x * 127.1 + y * 311.7) * 43758.5453123;
  return n - Math.floor(n);
}
function vnoise(x: number, y: number) {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const xf = x - xi;
  const yf = y - yi;
  const u = xf * xf * (3 - 2 * xf);
  const v = yf * yf * (3 - 2 * yf);
  const a = hash2(xi, yi);
  const b = hash2(xi + 1, yi);
  const c = hash2(xi, yi + 1);
  const d = hash2(xi + 1, yi + 1);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}
function noise2(x: number, y: number) {
  return 0.6 * vnoise(x, y) + 0.4 * vnoise(x * 2.1 + 11.3, y * 2.1 + 4.7);
}

function easeOutCubic(t: number) {
  const c = Math.min(1, Math.max(0, t));
  return 1 - Math.pow(1 - c, 3);
}

interface Tokens {
  fg: string;
  bg: string;
}

function readTokens(): Tokens {
  const cs = getComputedStyle(document.documentElement);
  const get = (name: string, fallback: string) => cs.getPropertyValue(name).trim() || fallback;
  return { fg: get("--foreground", "#ededed"), bg: get("--surface", "#171717") };
}

type Pos = { x: number; y: number; w: number; h: number };

function pack(order: string[], sizeOf: (id: string) => number, cols: number, colW: number) {
  const colH = new Array(cols).fill(0);
  const pos: Record<string, Pos> = {};
  for (const id of order) {
    let target = 0;
    for (let c = 1; c < cols; c++) if (colH[c] < colH[target]) target = c;
    const h = sizeOf(id);
    pos[id] = { x: target * (colW + GAP), y: colH[target], w: colW, h };
    colH[target] += h + GAP;
  }
  const maxH = Math.max(0, ...colH.map((h) => Math.max(0, h - GAP)));
  return { pos, maxH };
}

export function MasonryAsciiSettle({ tiles, className = "" }: MasonryAsciiSettleProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRefs = useRef<Record<string, HTMLCanvasElement | null>>({});
  const wrapRefs = useRef<Record<string, HTMLDivElement | null>>({});
  const prevColsRef = useRef<number | null>(null);
  const dropStartRef = useRef<Record<string, number>>({});
  const tokensRef = useRef<Tokens>(typeof document === "undefined" ? { fg: "#ededed", bg: "#171717" } : readTokens());
  const reducedRef = useRef(false);
  const rafRef = useRef(0);
  const [containerHeight, setContainerHeight] = useState(0);
  const [colW, setColW] = useState(0);
  const [posMap, setPosMap] = useState<Record<string, Pos>>({});

  const ids = useMemo(() => tiles.map((t) => t.id), [tiles]);
  const byId = useMemo(() => {
    const m = new Map<string, MasonryAsciiTile>();
    tiles.forEach((t) => m.set(t.id, t));
    return m;
  }, [tiles]);

  const layout = useCallback(
    (replay: boolean) => {
      const container = containerRef.current;
      if (!container) return;
      const width = container.getBoundingClientRect().width;
      if (width < 4) return;
      const cols = columnsFor(width);
      const w = (width - GAP * (cols - 1)) / cols;
      setColW(w);

      const sizeOf = (id: string) => w * (byId.get(id)?.aspect ?? 1);
      const { pos, maxH } = pack(ids, sizeOf, cols, w);
      setPosMap(pos);
      setContainerHeight(maxH);

      const colsChanged = prevColsRef.current !== null && prevColsRef.current !== cols;
      prevColsRef.current = cols;

      if (replay && (colsChanged || dropStartRef.current["__first"] === undefined)) {
        dropStartRef.current["__first"] = 1;
        const now = performance.now();
        // stagger by final row (y), then column (x), so the reflow reads top
        // to bottom, left to right
        const order = [...ids].sort((a, b) => {
          const pa = pos[a];
          const pb = pos[b];
          if (!pa || !pb) return 0;
          if (Math.abs(pa.y - pb.y) > 1) return pa.y - pb.y;
          return pa.x - pb.x;
        });
        order.forEach((id, i) => {
          dropStartRef.current[id] = now + i * STAGGER_MS;
        });
        wake();
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [ids, byId]
  );

  const wake = () => {
    if (rafRef.current) return;
    rafRef.current = requestAnimationFrame(loop);
  };

  const loop = () => {
    rafRef.current = 0;
    const now = performance.now();
    let stillAnimating = false;

    for (const id of ids) {
      const canvas = canvasRefs.current[id];
      const wrap = wrapRefs.current[id];
      if (!canvas || !wrap) continue;
      const start = dropStartRef.current[id];
      const tile = byId.get(id);
      if (!tile) continue;

      let t = 1;
      if (start !== undefined && !reducedRef.current) {
        const elapsed = now - start;
        if (elapsed < 0) {
          t = 0;
          stillAnimating = true;
        } else {
          t = Math.min(1, elapsed / DROP_MS);
          if (t < 1) stillAnimating = true;
        }
      }
      const eased = easeOutCubic(t);
      wrap.style.transform = `translateY(${(1 - eased) * -DROP_PX}px)`;
      wrap.style.opacity = String(0.15 + 0.85 * eased);

      const pitch = COARSE_PITCH + (FINE_PITCH - COARSE_PITCH) * eased;
      paintTile(canvas, tile.seed, pitch);
    }

    if (stillAnimating) rafRef.current = requestAnimationFrame(loop);
  };

  const paintTile = (canvas: HTMLCanvasElement, seed: number, pitch: number) => {
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const cssW = canvas.clientWidth || 1;
    const cssH = canvas.clientHeight || 1;
    const targetW = Math.ceil(cssW * dpr);
    const targetH = Math.ceil(cssH * dpr);
    if (canvas.width !== targetW || canvas.height !== targetH) {
      canvas.width = targetW;
      canvas.height = targetH;
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    const { fg, bg } = tokensRef.current;
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, cssW, cssH);

    const cols = Math.max(1, Math.ceil(cssW / pitch));
    const rows = Math.max(1, Math.ceil(cssH / pitch));
    const cellW = cssW / cols;
    const cellH = cssH / rows;
    ctx.fillStyle = fg;
    ctx.font = `${Math.max(6, Math.round(cellH * 0.95))}px "GeistMono", ui-monospace, monospace`;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    for (let gy = 0; gy < rows; gy++) {
      for (let gx = 0; gx < cols; gx++) {
        const raw = Math.min(1, Math.max(0, noise2(gx * 0.3 + seed * 13.7, gy * 0.3 + seed * 5.1)));
        // Raw value-noise clusters tightly around the middle of the ramp —
        // every cell prints some mid-weight character and the tile reads as
        // uniform static, no negative space, no filaments. Power-sharpening
        // the same field (same seed, same mechanic) pushes most cells to
        // blank and only real peaks to the top of the ramp, so a tile reads
        // as sparse bright structure on paper rather than gray noise.
        const v = Math.pow(raw, 2.4);
        const idx = Math.min(RAMP.length - 1, Math.floor(v * RAMP.length));
        const ch = RAMP[idx];
        if (!ch || ch === " ") continue;
        ctx.fillText(ch, gx * cellW + cellW / 2, gy * cellH + cellH / 2);
      }
    }
  };

  useLayoutEffect(() => {
    reducedRef.current = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    tokensRef.current = readTokens();
    layout(true);
    const container = containerRef.current;
    if (!container) return;
    const ro = new ResizeObserver(() => layout(true));
    ro.observe(container);
    const mo = new MutationObserver(() => {
      tokensRef.current = readTokens();
      wake();
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style"] });
    return () => {
      ro.disconnect();
      mo.disconnect();
      cancelAnimationFrame(rafRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    layout(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tiles]);

  return (
    <div
      ref={containerRef}
      className={`relative w-full ${className}`}
      style={{ height: containerHeight || undefined }}
    >
      {tiles.map((tile) => {
        const p = posMap[tile.id];
        return (
          <div
            key={tile.id}
            ref={(el) => {
              wrapRefs.current[tile.id] = el;
            }}
            data-masonry-tile={tile.id}
            className="absolute overflow-hidden rounded-md border border-border will-change-transform"
            style={{
              left: p?.x ?? 0,
              top: p?.y ?? 0,
              width: p?.w ?? colW,
              height: p?.h ?? colW,
            }}
          >
            <canvas
              ref={(el) => {
                canvasRefs.current[tile.id] = el;
              }}
              aria-hidden
              className="block h-full w-full"
            />
            <span className="pointer-events-none absolute inset-x-0 bottom-0 truncate bg-gradient-to-t from-background/90 to-transparent px-3 py-2 font-mono text-[11px] text-foreground">
              {tile.title}
            </span>
          </div>
        );
      })}
      <p className="sr-only">
        {tiles.length} images: {tiles.map((t) => t.title).join(", ")}.
      </p>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// MeltPondDrain — an ambient loader/empty-state panel modelling Arctic
// melt-pond drainage (Polashenski et al.): a shallow top-view basin whose
// pool slowly fills over a melt season, then drains rapidly once meltwater
// finds a crack through to the ocean below, leaving a shallow residual pool
// that refills and drains again through a DIFFERENT crack later. Unbound and
// self-driven — no `value` prop, no steady-state reading — the climax is a
// periodic, self-triggered fill/drain CYCLE, distinct from the data-bound
// waterline gauges (gauge-capacity-waterline, meter-quota-meniscus) and from
// the fracture-family siblings (craze-rule, compare-crack-seam), where the
// crack is the subject rather than incidental drainage infrastructure.
//
// Fill: ~9-11s (randomized per cycle) from a shallow residual level up to a
// near-full threshold. Drain: a fixed 1.2s event with three visible stages —
// a funnel dimple forms at a newly chosen rim location (0-30%), the water
// level falls rapidly toward it while the dimple holds (30-85%), then the
// dimple recedes as the floor settles at a residual level 80-90% below the
// pre-drain level, never to zero (85-100%). The drain location is a new
// angle around the basin rim each cycle, chosen at least 100deg away from
// the immediately-prior crack so it reads as migrating drainage, not a
// mechanical valve firing in the same spot.
//
// Seeded mid-drain at mount (t0), so the pond is already visibly non-empty,
// non-full, and the fill/drain distinction, plus at least one full
// drain-to-refill cycle boundary, are guaranteed inside the first ~1.2s —
// well inside the 2.5s/5s resting-loop checks — rather than depending on
// where a randomized multi-second fill happened to start.
//
// All ink is read from --foreground/--ns-muted via getComputedStyle on
// documentElement (never a literal), re-read on a MutationObserver watching
// its class attribute. Water alpha is chosen from the theme's own read
// foreground luminance rather than a hardcoded per-theme branch, so a
// third theme with tokens in between still gets a legible value step.
// ---------------------------------------------------------------------------

const FILL_MS_MIN = 9000;
const FILL_MS_MAX = 11000;
const DRAIN_MS = 1200;
const DIMPLE_END = 0.3; // fraction of DRAIN_MS: dimple fully formed
const FALL_END = 0.85; // fraction of DRAIN_MS: level finishes falling
const FULL_LEVEL = 0.93; // fill threshold that triggers the next drain
const DROP_MIN = 0.8; // 80-90% of the pre-drain level is lost each event
const DROP_MAX = 0.9;
const RESEED_MIN_DEG = 100; // next crack is at least this far from the last
const RESEED_SPAN_DEG = 160;
const N_POINTS = 64;
const DIMPLE_HALF_WIDTH = 0.62; // radians, ~35deg
const DIMPLE_DEPTH = 0.24; // fraction of the water radius the dimple bites in

function clamp01(n: number): number {
  return Math.min(1, Math.max(0, n));
}

function smoothstep(a: number, b: number, x: number): number {
  if (a === b) return x < a ? 0 : 1;
  const t = clamp01((x - a) / (b - a));
  return t * t * (3 - 2 * t);
}

function easeInOutCubic(t: number): number {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
}

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function parseHex(raw: string): [number, number, number] | null {
  const m = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(raw.trim());
  if (!m) return null;
  let h = m[1];
  if (h.length === 3) h = h.split("").map((c) => c + c).join("");
  const n = parseInt(h, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function relLuminance([r, g, b]: [number, number, number]): number {
  return (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;
}

// smallest signed angular distance from a to b, in (-PI, PI]
function angleDelta(a: number, b: number): number {
  let d = (b - a) % (Math.PI * 2);
  if (d > Math.PI) d -= Math.PI * 2;
  if (d < -Math.PI) d += Math.PI * 2;
  return d;
}

interface DrainState {
  phase: "fill" | "drain";
  level: number; // current fill level, 0..1
  fillElapsed: number;
  fillDuration: number;
  drainElapsed: number;
  levelAtDrainStart: number;
  dropFraction: number;
  thetaDrain: number;
  prevTheta: number;
}

function pickNextTheta(prev: number, rand: () => number): number {
  const offsetDeg = RESEED_MIN_DEG + rand() * RESEED_SPAN_DEG;
  const offset = (offsetDeg * Math.PI) / 180;
  let theta = prev + offset;
  theta = ((theta % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2);
  return theta;
}

function coverageFor(level: number): number {
  return 0.16 + 0.76 * Math.sqrt(clamp01(level));
}

/** dimple amount (0..1) and the level for a given point inside a drain
 * event of duration DRAIN_MS, given elapsed ms into it. */
function drainFrame(
  elapsed: number,
  levelAtStart: number,
  dropFraction: number
): { dimple: number; level: number } {
  const u = clamp01(elapsed / DRAIN_MS);
  const residual = levelAtStart * (1 - dropFraction);
  if (u < DIMPLE_END) {
    return { dimple: smoothstep(0, DIMPLE_END, u), level: levelAtStart };
  }
  if (u < FALL_END) {
    const t = easeInOutCubic((u - DIMPLE_END) / (FALL_END - DIMPLE_END));
    return { dimple: 1, level: levelAtStart + (residual - levelAtStart) * t };
  }
  const recede = smoothstep(FALL_END, 1, u);
  return { dimple: 1 - recede, level: residual };
}

export interface MeltPondDrainProps {
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function MeltPondDrain({ className = "" }: MeltPondDrainProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const rand = mulberry32(0xd4a17e ^ Date.now());
    const reducedMq = window.matchMedia("(prefers-reduced-motion: reduce)");

    let disposed = false;
    let visible = true;
    let raf = 0;
    let last = 0;
    let dpr = 1;
    let w = 0;
    let h = 0;
    let sized = false;

    let fgRgb: [number, number, number] = [23, 23, 23];
    let mutedHex = "#4d4d4d";
    let waterAlphaBase = 0.55;

    const readTokens = () => {
      const cs = getComputedStyle(document.documentElement);
      const fgHex = cs.getPropertyValue("--foreground").trim();
      fgRgb = parseHex(fgHex) ?? fgRgb;
      mutedHex = cs.getPropertyValue("--ns-muted").trim() || mutedHex;
      const lum = relLuminance(fgRgb);
      // dark theme: foreground reads pale/bright -> water sits near its
      // bright end, high alpha ("pale reflective"). Light theme: foreground
      // reads dark -> water stays a moderate, subtle value step, leaning on
      // the specular/edge strokes below for definition rather than a flat
      // dark fill fighting the copy ink.
      waterAlphaBase = 0.42 + lum * 0.42;
    };
    readTokens();

    const fg = (a: number) => `rgba(${fgRgb[0]},${fgRgb[1]},${fgRgb[2]},${a})`;
    const muted = (a: number) => {
      const rgb = parseHex(mutedHex) ?? [128, 128, 128];
      return `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${a})`;
    };

    // Seeded mid-drain: the pond is already draining at mount, guaranteeing
    // a visibly different level by 2.5s and a completed drain-to-refill
    // cycle boundary well inside the 5s check, regardless of RNG.
    const seedTheta = rand() * Math.PI * 2;
    const state: DrainState = {
      phase: "drain",
      level: 0.8 + rand() * 0.12,
      fillElapsed: 0,
      fillDuration: FILL_MS_MIN + rand() * (FILL_MS_MAX - FILL_MS_MIN),
      drainElapsed: rand() * DRAIN_MS * 0.6,
      levelAtDrainStart: 0.8 + rand() * 0.12,
      dropFraction: DROP_MIN + rand() * (DROP_MAX - DROP_MIN),
      thetaDrain: seedTheta,
      prevTheta: seedTheta,
    };
    state.levelAtDrainStart = state.level;

    const advance = (dtMs: number) => {
      if (state.phase === "drain") {
        state.drainElapsed += dtMs;
        const frame = drainFrame(state.drainElapsed, state.levelAtDrainStart, state.dropFraction);
        state.level = frame.level;
        if (state.drainElapsed >= DRAIN_MS) {
          state.level = state.levelAtDrainStart * (1 - state.dropFraction);
          state.phase = "fill";
          state.fillElapsed = 0;
          state.fillDuration = FILL_MS_MIN + rand() * (FILL_MS_MAX - FILL_MS_MIN);
          state.prevTheta = state.thetaDrain;
        }
      } else {
        state.fillElapsed += dtMs;
        const t = easeInOutCubic(clamp01(state.fillElapsed / state.fillDuration));
        const residual = state.levelAtDrainStart * (1 - state.dropFraction);
        state.level = residual + (FULL_LEVEL - residual) * t;
        if (state.fillElapsed >= state.fillDuration) {
          state.phase = "drain";
          state.drainElapsed = 0;
          state.levelAtDrainStart = FULL_LEVEL;
          state.thetaDrain = pickNextTheta(state.prevTheta, rand);
        }
      }
    };

    const currentDimple = (): number => {
      if (state.phase !== "drain") return 0;
      return drainFrame(state.drainElapsed, state.levelAtDrainStart, state.dropFraction).dimple;
    };

    const draw = () => {
      if (!sized) return;
      ctx.clearRect(0, 0, w, h);

      const cx = w / 2;
      const cy = h / 2;
      const smaller = Math.min(w, h);
      const rx = smaller * 0.46;
      const ry = rx * 0.6;

      // basin depression: floor fill + rim hairline, --ns-muted only
      ctx.beginPath();
      ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
      ctx.fillStyle = muted(0.16);
      ctx.fill();
      ctx.lineWidth = 1;
      ctx.strokeStyle = muted(0.38);
      ctx.stroke();

      const dimple = currentDimple();
      const theta = state.thetaDrain;
      const coverage = coverageFor(state.level);

      const pts: [number, number][] = [];
      for (let i = 0; i < N_POINTS; i++) {
        const angle = (i / N_POINTS) * Math.PI * 2;
        const dist = Math.abs(angleDelta(angle, theta));
        const bump = smoothstep(DIMPLE_HALF_WIDTH, 0, dist);
        const indent = dimple * bump * DIMPLE_DEPTH;
        const r = coverage * (1 - indent);
        pts.push([cx + Math.cos(angle) * rx * r, cy + Math.sin(angle) * ry * r]);
      }

      // water surface, smoothed closed curve through the sampled points
      ctx.beginPath();
      const first = pts[0]!;
      const lastPt = pts[N_POINTS - 1]!;
      ctx.moveTo((first[0] + lastPt[0]) / 2, (first[1] + lastPt[1]) / 2);
      for (let i = 0; i < N_POINTS; i++) {
        const p = pts[i]!;
        const next = pts[(i + 1) % N_POINTS]!;
        const midX = (p[0] + next[0]) / 2;
        const midY = (p[1] + next[1]) / 2;
        ctx.quadraticCurveTo(p[0], p[1], midX, midY);
      }
      ctx.closePath();
      ctx.fillStyle = fg(waterAlphaBase);
      ctx.fill();
      ctx.lineWidth = 1;
      ctx.strokeStyle = fg(Math.min(0.95, waterAlphaBase + 0.22));
      ctx.stroke();

      // specular highlight — a soft arc toward the upper-left of the
      // surface, the value-step cue the light-theme spec calls for
      ctx.beginPath();
      ctx.ellipse(
        cx - rx * coverage * 0.32,
        cy - ry * coverage * 0.4,
        rx * coverage * 0.34,
        ry * coverage * 0.18,
        -0.4,
        0,
        Math.PI * 2
      );
      ctx.fillStyle = fg(Math.min(0.95, waterAlphaBase + 0.3));
      ctx.globalAlpha = 0.35;
      ctx.fill();
      ctx.globalAlpha = 1;

      // drain crack — a small zigzag from the water edge out to the rim,
      // visible only while a dimple is forming/holding/receding
      if (dimple > 0.02) {
        const edgeR = coverage * (1 - dimple * DIMPLE_DEPTH);
        const ex = cx + Math.cos(theta) * rx * edgeR;
        const ey = cy + Math.sin(theta) * ry * edgeR;
        const rimX = cx + Math.cos(theta) * rx * 0.97;
        const rimY = cy + Math.sin(theta) * ry * 0.97;
        const midX1 = ex + (rimX - ex) * 0.35 + Math.cos(theta + Math.PI / 2) * 4;
        const midY1 = ey + (rimY - ey) * 0.35 + Math.sin(theta + Math.PI / 2) * 4;
        const midX2 = ex + (rimX - ex) * 0.7 - Math.cos(theta + Math.PI / 2) * 4;
        const midY2 = ey + (rimY - ey) * 0.7 - Math.sin(theta + Math.PI / 2) * 4;
        ctx.beginPath();
        ctx.moveTo(ex, ey);
        ctx.lineTo(midX1, midY1);
        ctx.lineTo(midX2, midY2);
        ctx.lineTo(rimX, rimY);
        ctx.strokeStyle = muted(0.5 * dimple + 0.15);
        ctx.lineWidth = 1.25;
        ctx.stroke();
      }
    };

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      if (w < 2 || h < 2) {
        sized = false;
        return;
      }
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      sized = true;
    };

    const loop = (now: number) => {
      raf = 0;
      if (!visible || !sized) return;
      const dt = last ? Math.min(200, now - last) : 1000 / 60;
      last = now;
      advance(dt);
      draw();
      raf = requestAnimationFrame(loop);
    };

    const drawReducedFrame = () => {
      // deliberately NOT t0's live seed: a fixed, hand-chosen mid-drain
      // instant — dimple fully formed, level partway through its fall,
      // floor partly exposed — the single most structured frame.
      const frozen: DrainState = {
        ...state,
        phase: "drain",
        levelAtDrainStart: 0.88,
        dropFraction: 0.85,
        drainElapsed: DRAIN_MS * 0.55,
        thetaDrain: seedTheta,
      };
      const frame = drainFrame(frozen.drainElapsed, frozen.levelAtDrainStart, frozen.dropFraction);
      state.level = frame.level;
      state.phase = "drain";
      state.drainElapsed = frozen.drainElapsed;
      state.levelAtDrainStart = frozen.levelAtDrainStart;
      state.dropFraction = frozen.dropFraction;
      state.thetaDrain = frozen.thetaDrain;
      draw();
    };

    const start = () => {
      if (reducedMq.matches) {
        drawReducedFrame();
        return;
      }
      last = 0;
      if (!raf) raf = requestAnimationFrame(loop);
    };

    const stop = () => {
      cancelAnimationFrame(raf);
      raf = 0;
    };

    const ro = new ResizeObserver(() => {
      resize();
      if (reducedMq.matches) drawReducedFrame();
    });
    ro.observe(canvas);

    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && !reducedMq.matches) start();
      else stop();
    });
    io.observe(canvas);

    const mo = new MutationObserver(() => {
      readTokens();
      if (reducedMq.matches) drawReducedFrame();
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    const onReducedChange = () => {
      if (reducedMq.matches) {
        stop();
        drawReducedFrame();
      } else {
        start();
      }
    };
    reducedMq.addEventListener("change", onReducedChange);

    const onVis = () => {
      if (document.hidden) stop();
      else if (visible && !reducedMq.matches) start();
    };
    document.addEventListener("visibilitychange", onVis);

    resize();
    if (sized) {
      if (reducedMq.matches) drawReducedFrame();
      else start();
    }

    return () => {
      disposed = true;
      stop();
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      reducedMq.removeEventListener("change", onReducedChange);
      document.removeEventListener("visibilitychange", onVis);
      void disposed;
    };
  }, []);

  return (
    <div role="img" aria-label="Loading" className={`relative h-full w-full ${className}`}>
      <canvas ref={canvasRef} aria-hidden="true" className="block h-full w-full" />
    </div>
  );
}

MeltPondDrain.displayName = "MeltPondDrain";

"use client";

import { useEffect, useId, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// PatinaLedger — the "what does it think it knows about me right now" panel.
// One 32px row per remembered fact, 13px Geist Mono, inside a 12px-radius
// rail. Ink is literally time: an unreferenced row steps its color down a
// four-stop ramp from --foreground toward --ns-muted (fresh -> aging -> fading
// -> dormant) on a 600ms transition every turn it goes unused, so aging is
// perceptible at each turn boundary rather than a silent jump. The moment the
// agent actually cites a row in a reply, its color SNAPS back to --foreground
// (transition suppressed for that one commit, not eased — a discontinuity
// reads as "revived now" the way a slow brighten wouldn't) and a 1px
// --foreground underline wipes left-to-right under the text over 300ms
// before fading, so rehearsal is visible as an event, not just a color.
//
// Users govern the ledger, they don't just read it: pin stamps a 4px
// --foreground lacquer dot and permanently exempts the row from fading
// (data-age flips to "pinned", never advances); evict is a real two-step
// confirm — first press arms the row (label + button both announce
// "confirm"), second press collapses it via grid-template-rows 1fr->0fr +
// opacity, 250ms, then the row is handed to the caller to actually remove.
// Rows that fully dormant (unpinned, past the last threshold) leave the main
// list and fold into a "N dormant" disclosure at the bottom so the rail
// doesn't grow unbounded with things nobody's used in ages; expanding it
// reveals them inline, still with working pin/evict, so pinning a dormant
// row rescues it back into the main list on the next render for free.
//
// Fully controlled: memories + turn are props, the component derives every
// row's age from `turn - lastUsedTurn` and holds no model state of its own —
// pin/evict are reported via callbacks, the caller owns the array. The only
// local state is transient UI: which row is armed-for-evict, which rows are
// mid-collapse, whether the dormant drawer is open, and a short-lived
// "just cited" flag used to drive the wipe + a single aria-live
// announcement. Colors are CSS custom properties only (--foreground,
// --ns-muted, --border, --background) via color-mix(), never a literal, so
// both themes render correctly. Because color alone is invisible to a
// screen reader, every row's accessible name spells the age out in words —
// "remembers: prefers metric units — fading, 6 turns unused" — and pin/evict
// are real, separately-labelled, keyboard-reachable buttons. Under
// prefers-reduced-motion every wipe, fade and collapse animation is
// replaced by an instant state change; nothing becomes unreachable or
// unreadable, it just stops moving.
// ---------------------------------------------------------------------------

export interface PatinaMemory {
  /** stable identifier */
  id: string;
  /** the remembered fact, rendered verbatim in 13px Geist Mono */
  text: string;
  /** turn index this memory was last referenced or rehearsed */
  lastUsedTurn: number;
  /** pinned rows never fade and carry a lacquer dot */
  pinned?: boolean;
}

export interface PatinaLedgerProps {
  /** the ledger rows, each decaying independently by its own age */
  memories: PatinaMemory[];
  /** current turn index — advances as the conversation proceeds */
  turn: number;
  /**
   * turns-unused boundaries between fresh/aging/fading/dormant.
   * default [1, 4, 9] (0 turns = fresh, 1-3 = aging, 4-8 = fading, 9+ = dormant)
   */
  ageThresholds?: readonly [number, number, number];
  /** called when a row's pin is toggled */
  onPinToggle?: (id: string, pinned: boolean) => void;
  /** called once a row's evict collapse animation has finished */
  onEvict?: (id: string) => void;
  /** accessible name for the ledger list. default "Session memory" */
  ariaLabel?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

type AgeStop = 0 | 1 | 2 | 3;

function computeStop(turnsUnused: number, th: readonly [number, number, number]): AgeStop {
  const u = Math.max(0, turnsUnused);
  if (u < th[0]) return 0;
  if (u < th[1]) return 1;
  if (u < th[2]) return 2;
  return 3;
}

function ageWords(stop: AgeStop, turnsUnused: number, pinned: boolean): string {
  if (pinned) return "pinned";
  if (stop === 0) return "fresh";
  const n = Math.max(0, turnsUnused);
  const unit = n === 1 ? "turn" : "turns";
  const word = stop === 1 ? "aging" : stop === 2 ? "fading" : "dormant";
  return `${word}, ${n} ${unit} unused`;
}

function PinGlyph() {
  return (
    <svg viewBox="0 0 16 16" width="13" height="13" fill="none" aria-hidden="true">
      <path
        d="M8 1.5 9.6 5l3.4.5-2.6 2.4.7 3.5L8 9.7 5 11.4l.7-3.5-2.6-2.4L6.5 5 8 1.5Z"
        stroke="currentColor"
        strokeWidth="1.2"
        strokeLinejoin="round"
      />
      <path d="M8 11.4v3.1" stroke="currentColor" strokeWidth="1.2" strokeLinecap="round" />
    </svg>
  );
}

function EvictGlyph() {
  return (
    <svg viewBox="0 0 16 16" width="13" height="13" fill="none" aria-hidden="true">
      <path d="M4.5 4.5 11.5 11.5M11.5 4.5 4.5 11.5" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" />
    </svg>
  );
}

function ChevronGlyph({ expanded }: { expanded: boolean }) {
  return (
    <svg
      viewBox="0 0 16 16"
      width="11"
      height="11"
      fill="none"
      aria-hidden="true"
      className="ns-patina-chevron"
      data-expanded={expanded}
    >
      <path d="M5 3.5 10 8l-5 4.5" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

export function PatinaLedger({
  memories,
  turn,
  ageThresholds = [1, 4, 9],
  onPinToggle,
  onEvict,
  ariaLabel = "Session memory",
  className = "",
}: PatinaLedgerProps) {
  const uid = useId();
  const [armedId, setArmedId] = useState<string | null>(null);
  const [collapsingIds, setCollapsingIds] = useState<Set<string>>(() => new Set());
  const [expandedDormant, setExpandedDormant] = useState(false);
  const [justCited, setJustCited] = useState<{ id: string; key: number } | null>(null);
  const [liveMsg, setLiveMsg] = useState("");
  const [reducedMotion, setReducedMotion] = useState(false);
  const prevRef = useRef<Map<string, number>>(new Map());

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReducedMotion(mq.matches);
    update();
    mq.addEventListener("change", update);
    return () => mq.removeEventListener("change", update);
  }, []);

  // Detect rehearsal: any memory whose lastUsedTurn just increased. Compared
  // against the previous render's snapshot, not derived from `turn` alone,
  // so a memory can be cited on any turn without every sibling re-triggering.
  useEffect(() => {
    const prev = prevRef.current;
    for (const m of memories) {
      const before = prev.get(m.id);
      if (before !== undefined && m.lastUsedTurn > before) {
        setJustCited({ id: m.id, key: Date.now() + Math.random() });
        setLiveMsg(`Rehearsed: ${m.text} — turn ${m.lastUsedTurn}`);
      }
    }
    prevRef.current = new Map(memories.map((m) => [m.id, m.lastUsedTurn]));
  }, [memories]);

  useEffect(() => {
    if (!justCited) return;
    const t = window.setTimeout(() => {
      setJustCited((cur) => (cur?.key === justCited.key ? null : cur));
    }, 900);
    return () => window.clearTimeout(t);
  }, [justCited]);

  const rows = memories.map((m) => {
    const turnsUnused = Math.max(0, turn - m.lastUsedTurn);
    const stop = computeStop(turnsUnused, ageThresholds);
    const dormant = !m.pinned && stop === 3;
    return { ...m, turnsUnused, stop, dormant };
  });

  const visible = rows.filter((r) => !r.dormant);
  const dormantRows = rows.filter((r) => r.dormant);

  function requestEvict(id: string) {
    if (armedId === id) {
      setArmedId(null);
      setCollapsingIds((prev) => {
        const next = new Set(prev);
        next.add(id);
        return next;
      });
      const delay = reducedMotion ? 0 : 260;
      window.setTimeout(() => {
        setCollapsingIds((prev) => {
          const next = new Set(prev);
          next.delete(id);
          return next;
        });
        onEvict?.(id);
      }, delay);
    } else {
      setArmedId(id);
    }
  }

  function renderRow(r: (typeof rows)[number]) {
    const armed = armedId === r.id;
    const collapsing = collapsingIds.has(r.id);
    const cited = justCited?.id === r.id;
    const dataAge = r.pinned ? "pinned" : String(r.stop);
    const label = `Remembers: ${r.text} — ${ageWords(r.stop, r.turnsUnused, !!r.pinned)}`;

    return (
      <li
        key={r.id}
        aria-label={label}
        data-age={dataAge}
        data-collapsing={collapsing}
        data-justcited={cited}
        className="ns-patina-row"
      >
        <div className="ns-patina-row-clip">
          <div className="flex h-8 items-center gap-2 px-3">
            <span aria-hidden="true" className="ns-patina-dot" data-visible={!!r.pinned} />
            <span className="ns-patina-text relative min-w-0 flex-1 truncate font-mono text-[13px]">
              {r.text}
              <span aria-hidden="true" className="ns-patina-wipe" />
            </span>
            <div className="ml-auto flex shrink-0 items-center gap-0.5">
              <button
                type="button"
                aria-pressed={!!r.pinned}
                aria-label={`${r.pinned ? "Unpin" : "Pin"} memory: ${r.text}`}
                onClick={() => onPinToggle?.(r.id, !r.pinned)}
                data-active={!!r.pinned}
                className="ns-patina-btn"
              >
                <PinGlyph />
              </button>
              <button
                type="button"
                aria-label={armed ? `Confirm evict: ${r.text}` : `Evict memory: ${r.text}`}
                onClick={() => requestEvict(r.id)}
                onBlur={() => setArmedId((cur) => (cur === r.id ? null : cur))}
                data-armed={armed}
                className="ns-patina-btn"
              >
                <EvictGlyph />
              </button>
            </div>
          </div>
        </div>
      </li>
    );
  }

  return (
    <div className={["ns-patina", className].join(" ")}>
      <style>{`
.ns-patina-list{overflow:hidden}
.ns-patina-row{display:grid;grid-template-rows:1fr;opacity:1;transition:grid-template-rows 250ms cubic-bezier(.22,1,.36,1),opacity 250ms ease-out}
.ns-patina-row[data-collapsing="true"]{grid-template-rows:0fr;opacity:0}
.ns-patina-row-clip{overflow:hidden;min-height:0}
.ns-patina-row + .ns-patina-row > .ns-patina-row-clip{border-top:1px solid var(--border)}
.ns-patina-text{color:var(--foreground);transition:color 600ms ease-out}
.ns-patina-row[data-age="1"] .ns-patina-text{color:color-mix(in srgb, var(--foreground) 68%, var(--ns-muted))}
.ns-patina-row[data-age="2"] .ns-patina-text{color:color-mix(in srgb, var(--foreground) 36%, var(--ns-muted))}
.ns-patina-row[data-age="3"] .ns-patina-text{color:var(--ns-muted)}
.ns-patina-row[data-age="pinned"] .ns-patina-text{color:var(--foreground)}
.ns-patina-row[data-justcited="true"] .ns-patina-text{transition:none}
.ns-patina-wipe{position:absolute;left:0;right:0;bottom:-3px;height:1px;background:var(--foreground);opacity:0;transform:scaleX(0);transform-origin:left}
.ns-patina-row[data-justcited="true"] .ns-patina-wipe{animation:ns-patina-wipe-in 300ms cubic-bezier(.22,1,.36,1) forwards,ns-patina-wipe-out 300ms ease-in 600ms forwards}
@keyframes ns-patina-wipe-in{from{transform:scaleX(0);opacity:1}to{transform:scaleX(1);opacity:1}}
@keyframes ns-patina-wipe-out{from{opacity:1}to{opacity:0}}
.ns-patina-dot{width:0;height:4px;border-radius:9999px;background:var(--foreground);opacity:0;transition:width 200ms ease-out,opacity 200ms ease-out}
.ns-patina-dot[data-visible="true"]{width:4px;opacity:1}
.ns-patina-btn{display:inline-flex;height:22px;width:22px;align-items:center;justify-content:center;border-radius:6px;color:var(--ns-muted);transition:background-color 150ms ease-out,color 150ms ease-out,box-shadow 150ms ease-out}
.ns-patina-btn:hover{background:color-mix(in srgb, var(--foreground) 8%, transparent);color:var(--foreground)}
.ns-patina-btn:focus-visible{outline:2px solid var(--ns-accent);outline-offset:1px}
.ns-patina-btn[data-active="true"]{color:var(--foreground)}
.ns-patina-btn[data-armed="true"]{background:color-mix(in srgb, var(--ns-accent) 18%, transparent);color:var(--ns-accent);box-shadow:inset 0 0 0 1px color-mix(in srgb, var(--ns-accent) 55%, transparent)}
.ns-patina-btn[data-armed="true"]:hover{background:color-mix(in srgb, var(--ns-accent) 26%, transparent)}
.ns-patina-dormant-btn{color:var(--ns-muted);transition:color 150ms ease-out}
.ns-patina-dormant-btn:hover{color:var(--foreground)}
.ns-patina-dormant-btn:focus-visible{outline:2px solid var(--ns-accent);outline-offset:-1px;border-radius:6px}
.ns-patina-chevron{transition:transform 200ms cubic-bezier(.22,1,.36,1)}
.ns-patina-chevron[data-expanded="true"]{transform:rotate(90deg)}
.ns-patina-dormant-wrap{display:grid;grid-template-rows:0fr;transition:grid-template-rows 300ms cubic-bezier(.22,1,.36,1)}
.ns-patina-dormant-wrap[data-expanded="true"]{grid-template-rows:1fr}
.ns-patina-dormant-clip{overflow:hidden;min-height:0}
@media (prefers-reduced-motion: reduce){
  .ns-patina-row,.ns-patina-text,.ns-patina-dot,.ns-patina-dormant-wrap,.ns-patina-chevron,.ns-patina-btn,.ns-patina-dormant-btn{transition:none!important}
  .ns-patina-wipe{animation:none!important;opacity:0!important}
}
`}</style>

      <ul role="list" aria-label={ariaLabel} className="ns-patina-list rounded-xl border border-border bg-background">
        {visible.map(renderRow)}
        {dormantRows.length > 0 ? (
          <li className="ns-patina-row" data-age="pinned">
            <div className="ns-patina-row-clip">
              <div className="flex h-8 items-center px-3">
                <button
                  type="button"
                  data-dormant-toggle="true"
                  aria-expanded={expandedDormant}
                  aria-controls={`${uid}-dormant`}
                  aria-label={`${expandedDormant ? "Collapse" : "Expand"} ${dormantRows.length} dormant ${
                    dormantRows.length === 1 ? "memory" : "memories"
                  }`}
                  onClick={() => setExpandedDormant((v) => !v)}
                  className="ns-patina-dormant-btn flex w-full items-center gap-1.5 font-mono text-[13px]"
                >
                  <ChevronGlyph expanded={expandedDormant} />
                  <span>{dormantRows.length} dormant</span>
                </button>
              </div>
            </div>
          </li>
        ) : null}
      </ul>

      {dormantRows.length > 0 ? (
        <div className="ns-patina-dormant-wrap" data-expanded={expandedDormant}>
          <div className="ns-patina-dormant-clip">
            <ul
              id={`${uid}-dormant`}
              role="list"
              aria-label="Dormant memories"
              className="ns-patina-list mt-2 rounded-xl border border-border bg-background"
            >
              {dormantRows.map(renderRow)}
            </ul>
          </div>
        </div>
      ) : null}

      <div aria-live="polite" className="sr-only">
        {liveMsg}
      </div>
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
} from "react";

// ---------------------------------------------------------------------------
// ShuntTray — nested menus as telescoping card-catalog trays. Opening a
// submenu never spawns a floating panel beside the parent: it shunts the
// parent tray back (scale(0.97^depth), transform-origin on its own left
// edge — the exposed rail — so the sliver's position is scale-independent
// and only the tray's body recedes away behind the child) and dims it under
// a --muted-tinted film, while the child tray slides in from the right on
// the same rails to translateX(depth * 12px) — a fixed, index-keyed resting
// offset, not a per-open delta. Because every tray's rest offset only
// depends on its own depth, and scale pivots on that same left edge instead
// of moving it, the stack always exposes exactly a 12px sliver of every
// ancestor between its neighbor's offset and its own, regardless of how many
// levels are open beneath it — a live breadcrumb of menu depth.
// Each exposed sliver is covered by a real, separately-focusable button
// (absolutely positioned over that 12px strip, outside the ancestor tray's
// DOM so `inert` on the tray can't swallow it) labeled "Back to {level}";
// clicking it reverses every tray deeper than its target simultaneously,
// each on a 30ms stagger (deepest first) as they slide back to
// translateX(100%) and unmount. One composite layer per tray, transform +
// opacity only, ease-out-expo timing throughout.
//
// A11y: role=menu per tray, role=menuitem per row. ArrowRight/Enter on an
// item with children opens its subtray and moves focus to that subtray's
// first item; ArrowLeft/Escape shunts back one level and restores focus to
// the item that opened the level being left. Every tray that isn't the
// current top gets aria-hidden + inert, so Tab/AT can never land behind the
// active tray — the edge buttons live outside that inert subtree, so they
// stay reachable. prefers-reduced-motion drops the slide/scale/stagger
// entirely: level changes commit synchronously and only the ancestor dim
// film crossfades, over 100ms; the edge buttons render unchanged either way.
// Zero dependencies, DOM + CSS only — no canvas.
// ---------------------------------------------------------------------------

export type ShuntTrayItem = {
  /** stable id — also the React key and the row's data-item-id */
  id: string;
  label: string;
  /** rendered right-aligned in font-mono, e.g. a count or shortcut */
  hint?: string;
  /** presence of items (even []) renders this row as a submenu opener */
  items?: ShuntTrayItem[];
};

export type ShuntTrayProps = {
  /** accessible name of the root tray; also the "Back to {label}" text once it's an ancestor */
  label: string;
  /** the root tray's rows */
  items: ShuntTrayItem[];
  /** fires when a leaf row (no `items`) is activated */
  onSelect?: (item: ShuntTrayItem, path: ShuntTrayItem[]) => void;
  /** px width of the menu */
  width?: number;
  /** px height of the menu */
  height?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
};

const EDGE = 12; // px sliver reveal per ancestor level
const RECEDE_MS = 280;
const EASE = "cubic-bezier(0.16, 1, 0.3, 1)"; // ease-out-expo
const STAGGER_MS = 30;
const SCALE_STEP = 0.97;

function scaleFor(k: number) {
  return Math.pow(SCALE_STEP, k);
}

type Level = { label: string; items: ShuntTrayItem[] };

export function ShuntTray({
  label,
  items,
  onSelect,
  width = 300,
  height = 360,
  className = "",
}: ShuntTrayProps) {
  const [path, setPath] = useState<ShuntTrayItem[]>([]);
  const [enteringDepth, setEnteringDepth] = useState<number | null>(null);
  const [poppingToDepth, setPoppingToDepth] = useState<number | null>(null);
  const [reducedMotion, setReducedMotion] = useState(false);
  const [announcement, setAnnouncement] = useState("");

  const containerRef = useRef<HTMLDivElement>(null);
  const pendingFocusRef = useRef<{ level: number; id: string } | null>(null);
  const lastActionRef = useRef<"open" | "back" | null>(null);
  const rafRef = useRef<number[]>([]);
  const commitTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const isFirstRenderRef = useRef(true);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReducedMotion(mq.matches);
    const onChange = () => setReducedMotion(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  useEffect(
    () => () => {
      rafRef.current.forEach(cancelAnimationFrame);
      if (commitTimeoutRef.current) clearTimeout(commitTimeoutRef.current);
    },
    []
  );

  const levels = useMemo<Level[]>(() => {
    const base: Level[] = [{ label, items }];
    for (const step of path) base.push({ label: step.label, items: step.items ?? [] });
    return base;
  }, [label, items, path]);

  const committedDepth = levels.length - 1;
  const targetDepth = poppingToDepth ?? committedDepth;

  // Focus + live-region: fires once a change actually settles — never on
  // mount, and never mid-cascade (poppingToDepth re-fires this once it clears).
  useEffect(() => {
    if (isFirstRenderRef.current) {
      isFirstRenderRef.current = false;
      return;
    }
    if (poppingToDepth !== null) return;
    const container = containerRef.current;
    const pending = pendingFocusRef.current;
    if (pending) {
      pendingFocusRef.current = null;
      const el = container?.querySelector<HTMLElement>(
        `[data-shunt-level="${pending.level}"] [data-item-id="${CSS.escape(pending.id)}"]`
      );
      el?.focus();
    } else if (lastActionRef.current === "open") {
      const el = container?.querySelector<HTMLElement>(
        `[data-shunt-level="${committedDepth}"] [role="menuitem"]`
      );
      el?.focus();
    }
    lastActionRef.current = null;
    setAnnouncement(`Now showing ${levels[committedDepth].label}`);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- levels/committedDepth move together
  }, [committedDepth, poppingToDepth]);

  const openChild = useCallback(
    (item: ShuntTrayItem) => {
      if (!item.items || poppingToDepth !== null || enteringDepth !== null) return;
      lastActionRef.current = "open";
      const nextDepth = path.length + 1;
      setPath((p) => [...p, item]);
      if (reducedMotion) return;
      setEnteringDepth(nextDepth);
      const r1 = requestAnimationFrame(() => {
        const r2 = requestAnimationFrame(() => setEnteringDepth(null));
        rafRef.current.push(r2);
      });
      rafRef.current.push(r1);
    },
    [path.length, poppingToDepth, enteringDepth, reducedMotion]
  );

  const shuntTo = useCallback(
    (depth: number) => {
      if (depth >= committedDepth || poppingToDepth !== null || enteringDepth !== null) return;
      const focusId = path[depth]?.id;
      if (focusId) pendingFocusRef.current = { level: depth, id: focusId };
      if (reducedMotion) {
        setPath((p) => p.slice(0, depth));
        return;
      }
      setPoppingToDepth(depth);
      const exitingCount = committedDepth - depth;
      const total = (exitingCount - 1) * STAGGER_MS + RECEDE_MS + 20;
      if (commitTimeoutRef.current) clearTimeout(commitTimeoutRef.current);
      commitTimeoutRef.current = setTimeout(() => {
        setPath((p) => p.slice(0, depth));
        setPoppingToDepth(null);
      }, total);
    },
    [committedDepth, path, poppingToDepth, enteringDepth, reducedMotion]
  );

  const goBack = useCallback(() => {
    if (committedDepth === 0) return;
    shuntTo(committedDepth - 1);
  }, [committedDepth, shuntTo]);

  const handleSelect = useCallback(
    (item: ShuntTrayItem) => onSelect?.(item, path),
    [onSelect, path]
  );

  return (
    <div
      ref={containerRef}
      className={`relative isolate overflow-hidden rounded-md bg-background ${className}`}
      style={{ width, height }}
    >
      {levels.map((level, i) => {
        const exiting = poppingToDepth !== null && i > targetDepth;
        const isTopmost = i === targetDepth;
        const entering = enteringDepth === i;
        const inertNow = !isTopmost;
        const k = exiting ? 0 : Math.max(0, targetDepth - i);
        const transform =
          entering || exiting ? "translateX(100%) scale(1)" : `translateX(${i * EDGE}px) scale(${scaleFor(k)})`;
        const delayMs = exiting ? (committedDepth - i) * STAGGER_MS : 0;

        return (
          <div
            key={i}
            role="menu"
            aria-label={level.label}
            aria-hidden={inertNow || undefined}
            inert={inertNow || undefined}
            data-shunt-level={i}
            className="absolute inset-0 flex flex-col overflow-hidden rounded-md border border-border bg-surface transition-transform will-change-transform motion-reduce:transition-none"
            style={{
              transform,
              transformOrigin: "left center",
              transitionDuration: `${RECEDE_MS}ms`,
              transitionTimingFunction: EASE,
              transitionDelay: `${delayMs}ms`,
              zIndex: i + 1,
            }}
          >
            <div className="flex-1 overflow-y-auto p-1.5">
              {level.items.map((item) => (
                <ShuntRow
                  key={item.id}
                  item={item}
                  isLevelActive={isTopmost}
                  isOpen={committedDepth > i && path[i]?.id === item.id}
                  onOpen={openChild}
                  onSelect={handleSelect}
                  onBack={goBack}
                />
              ))}
              {level.items.length === 0 && (
                <p className="px-3 py-6 text-center text-xs text-ns-muted">No items</p>
              )}
            </div>
            {!isTopmost && (
              <div
                aria-hidden
                className="pointer-events-none absolute inset-0 rounded-md bg-ns-muted/20 transition-opacity duration-150 motion-reduce:duration-100"
              />
            )}
          </div>
        );
      })}

      {Array.from({ length: targetDepth }, (_, i) => (
        <button
          key={`edge-${i}`}
          type="button"
          aria-label={`Back to ${levels[i].label}`}
          onClick={() => shuntTo(i)}
          className="absolute inset-y-0 z-[100] bg-transparent transition-colors hover:bg-foreground/5 focus-visible:bg-foreground/5 focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ns-accent"
          style={{ left: i * EDGE, width: EDGE }}
        />
      ))}

      <div aria-live="polite" className="sr-only">
        {announcement}
      </div>
    </div>
  );
}

function ShuntRow({
  item,
  isLevelActive,
  isOpen,
  onOpen,
  onSelect,
  onBack,
}: {
  item: ShuntTrayItem;
  isLevelActive: boolean;
  isOpen: boolean;
  onOpen: (item: ShuntTrayItem) => void;
  onSelect: (item: ShuntTrayItem) => void;
  onBack: () => void;
}) {
  const ref = useRef<HTMLButtonElement>(null);
  const hasChildren = !!item.items;

  function handleKeyDown(e: ReactKeyboardEvent<HTMLButtonElement>) {
    switch (e.key) {
      case "ArrowRight":
        if (hasChildren) {
          e.preventDefault();
          onOpen(item);
        }
        break;
      case "Enter":
      case " ":
        e.preventDefault();
        if (hasChildren) onOpen(item);
        else onSelect(item);
        break;
      case "ArrowLeft":
      case "Escape":
        e.preventDefault();
        onBack();
        break;
      case "ArrowDown":
      case "ArrowUp": {
        e.preventDefault();
        const menu = ref.current?.closest('[role="menu"]');
        if (!menu) return;
        const siblings = Array.from(menu.querySelectorAll<HTMLElement>('[role="menuitem"]'));
        const idx = siblings.indexOf(ref.current!);
        if (idx === -1) return;
        const next = e.key === "ArrowDown" ? (idx + 1) % siblings.length : (idx - 1 + siblings.length) % siblings.length;
        siblings[next]?.focus();
        break;
      }
      default:
        break;
    }
  }

  return (
    <button
      ref={ref}
      type="button"
      role="menuitem"
      data-item-id={item.id}
      aria-haspopup={hasChildren ? "menu" : undefined}
      aria-expanded={hasChildren ? isOpen : undefined}
      tabIndex={isLevelActive ? 0 : -1}
      onClick={() => (hasChildren ? onOpen(item) : onSelect(item))}
      onKeyDown={handleKeyDown}
      className="flex w-full items-center gap-2 rounded-sm px-2.5 py-2 text-left text-sm text-foreground transition-colors hover:bg-background focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ns-accent"
    >
      <span className="flex-1 truncate">{item.label}</span>
      {item.hint && <span className="font-mono text-xs text-ns-muted">{item.hint}</span>}
      {hasChildren && (
        <svg aria-hidden viewBox="0 0 16 16" className="h-3.5 w-3.5 shrink-0 text-ns-muted">
          <path
            d="M6 3l5 5-5 5"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      )}
    </button>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type ChangeEvent,
  type PointerEvent as ReactPointerEvent,
} from "react";

// ---------------------------------------------------------------------------
// GearLashField — a currency amount field where two meshed gears ARE the FX
// quote: the tooth ratio is the exchange rate, and mechanical backlash (the
// small dead-travel every real gear pair has before the flanks re-engage on
// a direction reversal) is the provider's spread, made literal.
//
// MODEL
// One governing scalar, driveAngle, is a direct function of the typed
// amount (driveAngle = amount * DEG_PER_UNIT — "accumulated" in the sense
// that it is exactly what you'd get integrating a constant deg/unit rate
// over every keystroke/scrub delta, just computed directly since amount is
// already the source of truth). The gear only ever SHOWS driveAngle mod 360;
// a separate Geist Mono row shows the un-wrapped, fully computed amount.
//
// Backlash is the textbook control-theory "backlash" nonlinearity: a
// `contact` value that free-wheels with driveAngle while moving in one
// direction, but on a reversal sits frozen until driveAngle has crossed the
// FULL dead-zone width (2x half-width) — exactly the "drive turns through a
// visible dead angle before the driven picks up" behavior:
//
//   if driveAngle - contact >  halfWidth: contact = driveAngle - halfWidth
//   if driveAngle - contact < -halfWidth: contact = driveAngle + halfWidth
//   else: contact unchanged
//
// halfWidth is derived from the real spread fraction: lashWidthDeg =
// spreadFrac * DEG_PER_UNIT * LEGIBILITY_GAIN — a fixed, stated gain so a
// real 0.3-2% spread (otherwise a fraction of a degree) reads as an actual
// wedge on an 8-40 tooth gear.
//
// drivenAngle = (driveAngle - lashState) / ratio, where lashState =
// driveAngle - contact (the current position inside the dead zone) and
// ratio = teethDrive / teethDriven (the drawn gear ratio) — so
// driveAngle - lashState === contact, and drivenAngle === contact / ratio.
// The printed converted amount is read straight off drivenAngle (scaled
// back through DEG_PER_UNIT and a power-of-ten `scale` pulled out of the
// rate so gears stay legible for both near-parity and far-apart pairs) —
// there is no second, independently-computed "real" total sitting next to
// the gears. The spread shown to the user is the gap between that
// gear-integrated amount and amount*rate computed with no gear at all —
// literally the lost angle, printed in currency.
//
// TEETH: tooth counts are round(driveTeeth * mantissa) searched over
// driveTeeth in [8,40] for the closest integer ratio to the rate's mantissa
// (rate decomposed into mantissa in [0.2,5] x a power-of-ten `scale`, so a
// JPY-sized rate doesn't demand an unrenderable 1:150 tooth ratio). The
// residual between that drawn ratio and the true rate is disclosed as an
// "honesty line" rather than hidden.
//
// SVG has no native way to tile a fill *around* a circle, so the tooth
// SILHOUETTE (the part that has to be geometrically correct — right tooth
// count, trapezoid profile, correct mesh) is a computed closed path. The
// brief's literal "teeth are an SVG <pattern> of trapezoids" is honored as
// the tooth FILL: a small repeating <pattern> tile of one trapezoid paints
// the inside of that silhouette, so the pattern is real and load-bearing
// (it is what you see), even though the outer tooth boundary comes from
// trig, not from pattern tiling — a genuine SVG limitation, not a shortcut
// taken for convenience.
// ---------------------------------------------------------------------------

const DEG_PER_UNIT = 3.6; // degrees of drive rotation per 1 unit of source currency
const LEGIBILITY_GAIN = 500; // fixed, stated gain turning a 0.3-2% spread into a visible wedge
const TYPED_MS = 200;
const TYPED_EASE = "cubic-bezier(0.16, 1, 0.3, 1)";
const MODULE_PX = 2.15; // px of pitch radius per tooth
const ADDENDUM = 4.5;
const DEDENDUM = 5.5;
const TOOTH_TOP_FRAC = 0.42;
const TOOTH_BASE_FRAC = 0.62;
const LIVE_MS = 420; // how long the mesh contact mark stays lit after input
const ANNOUNCE_DEBOUNCE = 450; // ms of quiet before the live region commits
// Deliberately fine: at a typical 0.3-2% spread the dead zone is only a few
// currency units wide (13.5deg / DEG_PER_UNIT ~ 3.75 units at 0.75%/500x
// gain), so a coarse px->unit ratio would blow past the whole gap in under
// 2px of drag and the component's central claim would never be seen.
const SCRUB_UNITS_PER_PX = 0.3;
const MAX_AMOUNT = 999_999;
const SVG_MARGIN = 6;

// ---- pure math -------------------------------------------------------------

interface GearConfig {
  teethDrive: number;
  teethDriven: number;
  ratio: number; // teethDrive / teethDriven
  scale: number; // power-of-ten pulled out of rate so mantissa fits [0.2, 5]
  mantissa: number; // rate / scale
}

function computeGearConfig(rateInput: number): GearConfig {
  let scale = 1;
  let r = Math.abs(rateInput) || 1;
  let guard = 0;
  while (r < 0.2 && guard++ < 20) {
    r *= 10;
    scale /= 10;
  }
  guard = 0;
  while (r > 5 && guard++ < 20) {
    r /= 10;
    scale *= 10;
  }

  let best: { drive: number; driven: number; err: number } | null = null;
  for (let drive = 8; drive <= 40; drive++) {
    const driven = Math.round(drive * r);
    if (driven < 8 || driven > 40) continue;
    const err = Math.abs(driven / drive - r);
    if (!best || err < best.err) best = { drive, driven, err };
  }
  if (!best) {
    const drive = r < 1 ? 40 : 8;
    const driven = Math.min(40, Math.max(8, Math.round(drive * r)));
    best = { drive, driven, err: Math.abs(driven / drive - r) };
  }

  return {
    teethDrive: best.drive,
    teethDriven: best.driven,
    ratio: best.drive / best.driven,
    scale,
    mantissa: r,
  };
}

function lashHalfWidthDeg(spreadFrac: number): number {
  const clamped = Math.min(0.25, Math.max(0, spreadFrac));
  return (clamped * DEG_PER_UNIT * LEGIBILITY_GAIN) / 2;
}

/** The classic backlash / dead-zone nonlinearity. `contact` free-wheels with
 * `x` while moving in one direction; on a reversal it stays put until `x`
 * has crossed the full 2*halfWidth gap. */
function updateContact(prevContact: number, x: number, halfWidth: number): number {
  if (x - prevContact > halfWidth) return x - halfWidth;
  if (x - prevContact < -halfWidth) return x + halfWidth;
  return prevContact;
}

function parseAmount(raw: string): number | null {
  if (raw.trim() === "") return 0;
  const n = Number(raw);
  if (!Number.isFinite(n)) return null;
  return Math.min(MAX_AMOUNT, Math.max(0, n));
}

function formatCurrency(value: number, code: string): string {
  try {
    return new Intl.NumberFormat(undefined, {
      style: "currency",
      currency: code,
      maximumFractionDigits: 2,
    }).format(value);
  } catch {
    return `${value.toFixed(2)} ${code}`;
  }
}

// ---- gear geometry ----------------------------------------------------------

function pitchRadius(teeth: number): number {
  return teeth * MODULE_PX;
}

function polarPoint(r: number, deg: number): { x: number; y: number } {
  const rad = ((deg - 90) * Math.PI) / 180;
  return { x: r * Math.cos(rad), y: r * Math.sin(rad) };
}

function fmt(n: number): string {
  return Math.round(n * 100) / 100 + "";
}

/** One closed path, in LOCAL coordinates centered on (0,0): a ring of
 * trapezoid teeth between innerR (root) and outerR (tip). */
function gearToothPath(outerR: number, innerR: number, teeth: number): string {
  const step = 360 / teeth;
  const halfTop = (step * TOOTH_TOP_FRAC) / 2;
  const halfBase = (step * TOOTH_BASE_FRAC) / 2;
  let d = "";
  for (let i = 0; i < teeth; i++) {
    const c = i * step;
    const p1 = polarPoint(innerR, c - halfBase);
    const p2 = polarPoint(outerR, c - halfTop);
    const p3 = polarPoint(outerR, c + halfTop);
    const p4 = polarPoint(innerR, c + halfBase);
    d += `${i === 0 ? "M" : "L"} ${fmt(p1.x)} ${fmt(p1.y)} L ${fmt(p2.x)} ${fmt(p2.y)} L ${fmt(p3.x)} ${fmt(p3.y)} L ${fmt(p4.x)} ${fmt(p4.y)} `;
  }
  return d + "Z";
}

interface Scene {
  width: number;
  height: number;
  driveCx: number;
  driveCy: number;
  driveOuter: number;
  driveInner: number;
  driveHub: number;
  drivePath: string;
  drivenCx: number;
  drivenCy: number;
  drivenOuter: number;
  drivenInner: number;
  drivenHub: number;
  drivenPath: string;
  contactX: number;
  contactY: number;
}

function buildScene(cfg: GearConfig): Scene {
  const rDrive = pitchRadius(cfg.teethDrive);
  const rDriven = pitchRadius(cfg.teethDriven);
  const outerDrive = rDrive + ADDENDUM;
  const innerDrive = rDrive - DEDENDUM;
  const outerDriven = rDriven + ADDENDUM;
  const innerDriven = rDriven - DEDENDUM;
  const maxOuter = Math.max(outerDrive, outerDriven);

  const driveCx = SVG_MARGIN + outerDrive;
  const cy = SVG_MARGIN + maxOuter;
  const drivenCx = driveCx + rDrive + rDriven;

  return {
    width: drivenCx + outerDriven + SVG_MARGIN,
    height: cy * 2,
    driveCx,
    driveCy: cy,
    driveOuter: outerDrive,
    driveInner: innerDrive,
    driveHub: innerDrive * 0.42,
    drivePath: gearToothPath(outerDrive, innerDrive, cfg.teethDrive),
    drivenCx,
    drivenCy: cy,
    drivenOuter: outerDriven,
    drivenInner: innerDriven,
    drivenHub: innerDriven * 0.42,
    drivenPath: gearToothPath(outerDriven, innerDriven, cfg.teethDriven),
    contactX: driveCx + rDrive,
    contactY: cy,
  };
}

interface Mechanism {
  contact: number;
  driveAngle: number;
  drivenAngleRaw: number;
  converted: number;
  fee: number;
  honesty: string;
}

/** The whole mechanism as one pure function of (amount, prior contact) — used
 * both to seed the resting-state render (no "blank until mount" frame) and,
 * on every input, to recompute what the gears show and what settles into the
 * live region. One function, two callers, so there is never a second,
 * independently-computed number sitting beside the gear math. */
function deriveMechanism(amount: number, prevContact: number, cfg: GearConfig, halfWidth: number, rate: number): Mechanism {
  const driveAngle = amount * DEG_PER_UNIT;
  const contact = updateContact(prevContact, driveAngle, halfWidth);
  const drivenAngleRaw = contact / cfg.ratio;
  const converted = (drivenAngleRaw / DEG_PER_UNIT) * cfg.scale;
  const ideal = amount * rate;
  const fee = Math.abs(ideal - converted);
  const honesty = `drawn ${cfg.teethDriven}:${cfg.teethDrive}, true ${cfg.mantissa.toFixed(4)}${
    cfg.scale !== 1 ? ` ×${cfg.scale}` : ""
  }`;
  return { contact, driveAngle, drivenAngleRaw, converted, fee, honesty };
}

function writeRotation(el: SVGGElement | null, cx: number, cy: number, deg: number, ms: number, ease: string) {
  if (!el) return;
  el.style.transition = ms > 0 ? `transform ${ms}ms ${ease}` : "none";
  el.style.transform = `translate(${fmt(cx)}px, ${fmt(cy)}px) rotate(${fmt(deg)}deg)`;
}

// ---- component ---------------------------------------------------------------

export interface GearLashFieldProps {
  /** ISO-ish code for the amount being sent, e.g. "USD". Default "USD". */
  fromCurrency?: string;
  /** ISO-ish code for the amount received, e.g. "EUR". Default "EUR". */
  toCurrency?: string;
  /** True exchange rate: units of `toCurrency` per 1 unit of `fromCurrency`. */
  rate: number;
  /** Provider spread as a fraction, e.g. 0.008 for 0.8%. Typical range 0.003-0.02. */
  spreadFrac: number;
  /** Initial amount in `fromCurrency`. Default 250. */
  defaultAmount?: number;
  /** Label for the source amount field. Default "You send". */
  label?: string;
  /** Label for the live-region readout. Default "They receive". */
  receiveLabel?: string;
  /** Fires once per settle (debounced), never per raw keystroke. */
  onAmountChange?: (info: { amount: number; converted: number; fee: number }) => void;
  className?: string;
}

export function GearLashField({
  fromCurrency = "USD",
  toCurrency = "EUR",
  rate,
  spreadFrac,
  defaultAmount = 250,
  label = "You send",
  receiveLabel = "They receive",
  onAmountChange,
  className = "",
}: GearLashFieldProps) {
  const uid = useId().replace(/:/g, "");
  const patternId = `ns-mesh-lash-teeth-${uid}`;
  const inputId = `ns-mesh-lash-input-${uid}`;

  const safeRate = Number.isFinite(rate) && rate !== 0 ? rate : 1;
  const cfg = useMemo(() => computeGearConfig(safeRate), [safeRate]);
  const scene = useMemo(() => buildScene(cfg), [cfg]);
  const halfWidth = useMemo(() => lashHalfWidthDeg(spreadFrac), [spreadFrac]);

  const initialAmount = parseAmount(String(defaultAmount)) ?? 0;
  const initialMechanism = deriveMechanism(initialAmount, 0, cfg, halfWidth, safeRate);

  const [rawText, setRawText] = useState(() => String(defaultAmount));
  const [display, setDisplay] = useState(() => ({
    amount: initialAmount,
    converted: initialMechanism.converted,
    fee: initialMechanism.fee,
    honesty: initialMechanism.honesty,
  }));

  const driveGroupRef = useRef<SVGGElement | null>(null);
  const drivenGroupRef = useRef<SVGGElement | null>(null);
  const contactMarkRef = useRef<SVGCircleElement | null>(null);

  // Seeded from the same mechanism the resting frame renders, so the first
  // real input is a genuine transition rather than a "snap from zero".
  const contactRef = useRef(initialMechanism.contact);
  const isDraggingRef = useRef(false);
  const reducedRef = useRef(false);
  const liveTimer = useRef<number | undefined>(undefined);
  const announceTimer = useRef<number | undefined>(undefined);
  const dragStartRef = useRef({ x: 0, amount: 0 });

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    reducedRef.current = mq.matches;
    const onChange = () => {
      reducedRef.current = mq.matches;
    };
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  // Core mechanism: whenever the typed/scrubbed amount changes, recompute
  // drive/backlash/driven and write it straight to the gear rotations AND
  // to the numbers that get displayed (debounced) — same computation, one
  // path, no separately-derived "real" total sitting beside the gears.
  const applyAmount = useCallback(
    (amount: number) => {
      const m = deriveMechanism(amount, contactRef.current, cfg, halfWidth, safeRate);
      contactRef.current = m.contact;

      const ms = reducedRef.current || isDraggingRef.current ? 0 : TYPED_MS;
      writeRotation(driveGroupRef.current, scene.driveCx, scene.driveCy, m.driveAngle % 360, ms, TYPED_EASE);
      writeRotation(drivenGroupRef.current, scene.drivenCx, scene.drivenCy, -(m.drivenAngleRaw % 360), ms, TYPED_EASE);

      if (contactMarkRef.current) {
        contactMarkRef.current.style.transition = "opacity 150ms ease-out";
        contactMarkRef.current.style.opacity = "1";
      }
      window.clearTimeout(liveTimer.current);
      liveTimer.current = window.setTimeout(() => {
        if (contactMarkRef.current) contactMarkRef.current.style.opacity = "0";
      }, LIVE_MS);

      window.clearTimeout(announceTimer.current);
      announceTimer.current = window.setTimeout(() => {
        setDisplay({ amount, converted: m.converted, fee: m.fee, honesty: m.honesty });
        onAmountChange?.({ amount, converted: m.converted, fee: m.fee });
      }, ANNOUNCE_DEBOUNCE);
    },
    [cfg, halfWidth, onAmountChange, safeRate, scene]
  );

  useEffect(
    () => () => {
      window.clearTimeout(liveTimer.current);
      window.clearTimeout(announceTimer.current);
    },
    []
  );

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    const next = e.target.value;
    setRawText(next);
    const amount = parseAmount(next);
    if (amount === null) return; // mid-typing junk (e.g. "-") — don't fight the caret
    applyAmount(amount);
  };

  const handleScrubDown = (e: ReactPointerEvent<HTMLDivElement>) => {
    e.currentTarget.setPointerCapture(e.pointerId);
    isDraggingRef.current = true;
    const current = parseAmount(rawText) ?? 0;
    dragStartRef.current = { x: e.clientX, amount: current };
  };

  const handleScrubMove = (e: ReactPointerEvent<HTMLDivElement>) => {
    if (!isDraggingRef.current) return;
    const dx = e.clientX - dragStartRef.current.x;
    const amount = Math.min(MAX_AMOUNT, Math.max(0, dragStartRef.current.amount + dx * SCRUB_UNITS_PER_PX));
    setRawText(amount.toFixed(2));
    applyAmount(amount);
  };

  const endScrub = (e: ReactPointerEvent<HTMLDivElement>) => {
    if (!isDraggingRef.current) return;
    isDraggingRef.current = false;
    e.currentTarget.releasePointerCapture(e.pointerId);
  };

  const convertedFmt = formatCurrency(display.converted, toCurrency);
  const feeFmt = formatCurrency(display.fee, toCurrency);

  const initialDriveTransform = `translate(${fmt(scene.driveCx)}px, ${fmt(scene.driveCy)}px) rotate(${fmt(
    initialMechanism.driveAngle % 360
  )}deg)`;
  const initialDrivenTransform = `translate(${fmt(scene.drivenCx)}px, ${fmt(scene.drivenCy)}px) rotate(${fmt(
    -(initialMechanism.drivenAngleRaw % 360)
  )}deg)`;

  return (
    <div className={`ns-mesh-lash-root w-full max-w-sm ${className}`}>
      <label htmlFor={inputId} className="mb-1.5 block text-xs font-medium text-ns-muted">
        {label}
      </label>
      <div className="flex items-center gap-2 rounded-[12px] border border-border bg-background px-3 py-2.5 transition-colors hover:border-foreground/30">
        <input
          id={inputId}
          type="text"
          inputMode="decimal"
          autoComplete="off"
          value={rawText}
          onChange={handleChange}
          aria-label={`${label}, amount in ${fromCurrency}`}
          className="min-w-0 flex-1 rounded-[6px] bg-transparent font-mono text-lg tabular-nums text-foreground placeholder:text-ns-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
          placeholder="0.00"
        />
        <span aria-hidden="true" className="shrink-0 font-mono text-xs uppercase tracking-wider text-ns-muted">
          {fromCurrency}
        </span>
      </div>

      <div
        data-mesh-role="scrub"
        aria-hidden="true"
        onPointerDown={handleScrubDown}
        onPointerMove={handleScrubMove}
        onPointerUp={endScrub}
        onPointerCancel={endScrub}
        className="mt-3 select-none rounded-[16px] border border-border bg-background px-3 py-3 transition-colors hover:border-foreground/25"
        style={{ touchAction: "none", cursor: "ew-resize" }}
      >
        <svg viewBox={`0 0 ${scene.width} ${scene.height}`} width="100%" aria-hidden="true" style={{ display: "block" }}>
          <defs>
            <pattern id={patternId} width="5" height="5" patternUnits="userSpaceOnUse">
              <rect width="5" height="5" fill="var(--background)" />
              <polygon points="0,5 1.6,0.6 3.4,0.6 5,5" fill="var(--border)" opacity={0.55} />
            </pattern>
          </defs>

          <g ref={driveGroupRef} style={{ transform: initialDriveTransform }}>
            <path d={scene.drivePath} fill={`url(#${patternId})`} stroke="var(--foreground)" strokeOpacity={0.5} strokeWidth={1} />
            <circle r={scene.driveHub} fill="var(--background)" stroke="var(--border)" strokeWidth={1} />
            <circle r={1.4} fill="var(--ns-muted)" />
          </g>

          <g ref={drivenGroupRef} style={{ transform: initialDrivenTransform }}>
            <path d={scene.drivenPath} fill={`url(#${patternId})`} stroke="var(--foreground)" strokeOpacity={0.5} strokeWidth={1} />
            <circle r={scene.drivenHub} fill="var(--background)" stroke="var(--border)" strokeWidth={1} />
            <circle r={1.4} fill="var(--ns-muted)" />
          </g>

          <circle
            ref={contactMarkRef}
            cx={scene.contactX}
            cy={scene.contactY}
            r={1}
            fill="var(--ns-accent)"
            style={{ opacity: 0 }}
          />
        </svg>
      </div>

      <div role="status" aria-live="polite" aria-atomic="true" className="mt-3 space-y-0.5">
        <p className="font-mono text-sm tabular-nums text-foreground">
          {receiveLabel} <span className="font-medium">{convertedFmt}</span>
        </p>
        <p className="font-mono text-xs tabular-nums text-ns-muted">Spread cost {feeFmt}</p>
        <p className="pt-1 font-mono text-[10px] tracking-wide text-ns-muted" aria-hidden="true">
          {display.honesty}
        </p>
      </div>
    </div>
  );
}

"use client";

// A context-window budget meter: one hairline stacked bar segmenting the
// window into system prompt / tools / conversation history / current turn,
// plus the unclaimed remainder, with a Geist Mono token readout underneath.
// It reads at rest because the bar IS the thing it describes — no legend
// needed to decode "what does 40% mean," the segment widths are the answer.
//
// Segments carry no color of their own (the palette is monochrome by house
// rule) — they're told apart by a stepped weight ramp (four flat, clearly
// separated color-mix() tones, lightest for system up to heaviest for the
// live turn) plus a bonus pattern once a segment is wide enough to resolve
// it: tools a diagonal hatch, history a stipple, current turn a fine
// vertical hatch that breathes gently while it's live. A 1px hairline
// divider sits between every pair so the boundary reads even when two
// tones land close together. Pure CSS, built from color-mix() against
// --foreground and --background, never a hex literal and never --ns-accent
// (accent is reserved for interaction, not decoration).
//
// Layout is plain flexbox: each segment's flex-basis is its share of
// max(capacity, used) as a percentage, with a min-width floor on any segment
// that has real tokens but would round below a legible sliver. The floor is
// enforced by the browser's own flex-shrink algorithm (larger segments give
// up the room), not by a hand-rolled pixel solver — a segment with tokens
// never disappears, one with none never fakes a sliver it didn't earn.
//
// Approaching capacity is signalled through form: the wrapper gains a
// pulsing inset ring, the readout goes bold and grows a triangle glyph, and
// the free segment (if any width remains) grows a hazard hatch — never a red
// fill, this palette doesn't have one. Compaction is just a prop change:
// react re-renders new percentages and the segments ease into them on a
// shared transition, so the resettle itself carries the news.
//
// All the numbers are real DOM text (a <p> readout plus a legend list), so
// assistive tech gets the actual figures regardless of what the bar looks
// like; the bar itself is aria-hidden as a redundant visual. The readout is
// a polite live region since it changes asynchronously as tokens accrue.
// prefers-reduced-motion drops the transition, the breathing, and the
// hazard pulse — every state stays fully legible, just static.

export interface BallastContextProps {
  /** total size of the context window, in tokens */
  capacity: number;
  /** tokens spent on the system prompt */
  system: number;
  /** tokens spent on tool/function definitions and results */
  tools: number;
  /** tokens spent on prior conversation turns */
  history: number;
  /** tokens spent on the turn currently being read or generated */
  turn: number;
  /**
   * fraction of capacity (0-1) below which the free segment is flagged as
   * low headroom. default 0.08 (8%)
   */
  lowFreeThreshold?: number;
  /** accessible name for the meter. default "Context window budget" */
  ariaLabel?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const ROLES = [
  { role: "system", label: "System" },
  { role: "tools", label: "Tools" },
  { role: "history", label: "History" },
  { role: "turn", label: "Turn" },
  { role: "free", label: "Free" },
] as const;

function formatTokens(n: number): string {
  return Math.round(Math.max(0, n)).toLocaleString("en-US");
}

function formatPct(tokens: number, denom: number): string {
  if (tokens <= 0 || denom <= 0) return "0%";
  const p = (tokens / denom) * 100;
  if (p < 1) return "<1%";
  return `${Math.round(p)}%`;
}

export function BallastContext({
  capacity,
  system,
  tools,
  history,
  turn,
  lowFreeThreshold = 0.08,
  ariaLabel = "Context window budget",
  className = "",
}: BallastContextProps) {
  const safeSystem = Math.max(0, system);
  const safeTools = Math.max(0, tools);
  const safeHistory = Math.max(0, history);
  const safeTurn = Math.max(0, turn);
  const safeCapacity = Math.max(0, capacity);

  const used = safeSystem + safeTools + safeHistory + safeTurn;
  const overBudget = safeCapacity > 0 && used > safeCapacity;
  const free = Math.max(0, safeCapacity - used);
  // denominator the bar fills to 100% against: capacity normally, or the
  // used total itself once over budget, so the four segments still sum to
  // a full bar instead of visually shrinking below their real weight
  const denom = Math.max(safeCapacity, used, 1);

  const freeFraction = safeCapacity > 0 ? free / safeCapacity : 0;
  const warn = safeCapacity > 0 && (overBudget || freeFraction <= lowFreeThreshold);

  const tokensByRole: Record<(typeof ROLES)[number]["role"], number> = {
    system: safeSystem,
    tools: safeTools,
    history: safeHistory,
    turn: safeTurn,
    free,
  };

  const pct = safeCapacity > 0 ? Math.round((used / safeCapacity) * 100) : 0;
  const statusSuffix = overBudget ? " · over budget" : warn ? " · low headroom" : "";

  return (
    <div
      role="group"
      aria-label={ariaLabel}
      data-warn={warn}
      className={["ns-ballast", className].join(" ")}
    >
      <style>{`
.ns-ballast-track{transition:box-shadow 300ms ease-out}
.ns-ballast[data-warn="true"] .ns-ballast-track{animation:ns-ballast-ring 1.8s ease-in-out infinite}
.ns-ballast-seg{transition:flex-basis 520ms cubic-bezier(.22,1,.36,1)}
.ns-ballast-track .ns-ballast-seg:not([data-role="free"]){border-right:1px solid var(--background)}
.ns-ballast-seg[data-role="system"]{background:color-mix(in srgb, var(--foreground) 22%, var(--background))}
.ns-ballast-seg[data-role="tools"]{background-color:color-mix(in srgb, var(--foreground) 30%, var(--background));background-image:repeating-linear-gradient(45deg, color-mix(in srgb, var(--foreground) 46%, var(--background)) 0 2px, transparent 2px 5px)}
.ns-ballast-seg[data-role="history"]{background-color:color-mix(in srgb, var(--foreground) 40%, var(--background));background-image:radial-gradient(color-mix(in srgb, var(--foreground) 60%, var(--background)) 1.1px, transparent 1.3px);background-size:5px 5px}
.ns-ballast-seg[data-role="turn"]{background-color:color-mix(in srgb, var(--foreground) 52%, var(--background));background-image:repeating-linear-gradient(90deg, color-mix(in srgb, var(--foreground) 72%, var(--background)) 0 1.5px, transparent 1.5px 4px);animation:ns-ballast-breathe 2.6s ease-in-out infinite}
.ns-ballast-seg[data-role="free"]{background:transparent}
.ns-ballast[data-warn="true"] .ns-ballast-seg[data-role="free"]{background-image:repeating-linear-gradient(135deg, color-mix(in srgb, var(--foreground) 26%, transparent) 0 1px, transparent 1px 6px);animation:ns-ballast-hazard 1.6s ease-in-out infinite}
@keyframes ns-ballast-breathe{0%,100%{opacity:.82}50%{opacity:1}}
@keyframes ns-ballast-hazard{0%,100%{opacity:.5}50%{opacity:1}}
@keyframes ns-ballast-ring{0%,100%{box-shadow:inset 0 0 0 1px var(--border)}50%{box-shadow:inset 0 0 0 1px color-mix(in srgb, var(--foreground) 45%, transparent)}}
@media (prefers-reduced-motion: reduce){
  .ns-ballast-seg{transition:none;animation:none !important;opacity:1 !important}
  .ns-ballast-track{animation:none !important;box-shadow:inset 0 0 0 1px var(--border) !important}
}
`}</style>

      <div
        aria-hidden="true"
        className="ns-ballast-track flex h-2.5 w-full overflow-hidden rounded-full border border-border bg-background"
      >
        {ROLES.map(({ role }) => {
          const t = tokensByRole[role];
          return (
            <div
              key={role}
              data-role={role}
              className="ns-ballast-seg h-full shrink"
              style={{
                flexBasis: `${(t / denom) * 100}%`,
                flexGrow: 0,
                minWidth: t > 0 ? "3px" : "0px",
              }}
            />
          );
        })}
      </div>

      <p
        aria-live="polite"
        className={[
          "mt-3 flex items-center gap-1.5 font-mono text-xs tabular-nums text-ns-muted",
          warn ? "font-semibold text-foreground" : "",
        ].join(" ")}
      >
        {warn ? (
          <svg
            aria-hidden="true"
            width="12"
            height="12"
            viewBox="0 0 16 16"
            fill="none"
            className="shrink-0 text-foreground"
          >
            <path
              d="M8 2.4 14.6 13.6H1.4L8 2.4Z"
              stroke="currentColor"
              strokeWidth="1.3"
              strokeLinejoin="round"
            />
            <path d="M8 6.6v3.4" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" />
            <circle cx="8" cy="11.9" r="0.85" fill="currentColor" />
          </svg>
        ) : null}
        <span>
          {formatTokens(used)} / {formatTokens(safeCapacity)} tokens · {pct}%{statusSuffix}
        </span>
      </p>

      <ul className="mt-2.5 flex flex-wrap gap-x-4 gap-y-1.5 font-mono text-[11px] tabular-nums text-ns-muted">
        {ROLES.map(({ role, label }) => {
          const t = tokensByRole[role];
          return (
            <li key={role} className="flex items-center gap-1.5">
              <span
                aria-hidden="true"
                data-role={role}
                className="ns-ballast-seg h-2.5 w-2.5 shrink-0 rounded-[2px] border border-border"
              />
              <span className="tracking-wide text-ns-muted">{label}</span>
              <span className="text-foreground">{formatTokens(t)}</span>
              <span>{formatPct(t, denom)}</span>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// MeniscusHold — time-to-first-token rendered as calibrated capillary rise.
// A narrow tube fills toward a scribed line marking the historical p50
// first-token latency for this model/tool combo; the rise is eased so the
// meniscus reaches that line exactly when a response typically lands. It
// never fakes progress past what it can justify: reaching the p50 line with
// nothing having arrived doesn't keep climbing toward "done" — the liquid
// HOLDS there and trembles (an honest "still waiting, later than usual"
// signal) while a second scribe line for p95 fades in above it. Past p95 the
// tremble stops — trembling forever would itself be a lie about how confident
// the wait still is — and a stall affordance (retry / switch model) surfaces.
// First token landing (`arrivedAt` set) drains the tube fast, ease-out-expo,
// from wherever the level currently sits.
//
// Three states, three honest phrases, announced only on the transition
// between them (role=status, not a running commentary):
//   waiting -> "Waiting, typically N seconds."
//   slow    -> "Taking longer than usual."
//   stalled -> "May be stalled, retry available."
// Distinct from status-glyph-cadence (liveness — the connection is alive, no
// notion of "how long is normal") and password-strength-tide (liquid level
// encodes input strength, not elapsed-time-vs-percentile). This is the only
// one of the three built from a calibrated latency distribution.
//
// Timing is derived from `startedAt`/`p50Ms`/`p95Ms` via two scheduled
// setTimeouts (not a rAF poll — there's nothing to simulate physically here,
// just two thresholds), so a late mount (component created a few hundred ms
// after the real request began) still lands on the correct phase and eases
// in for whatever time remains, rather than replaying the whole rise from
// zero. Pure DOM + CSS + SVG: the fill is a div, the meniscus is a 1-path SVG
// riding its top edge, both colored from --foreground/--ns-muted, no canvas.
// prefers-reduced-motion drops the rise/tremor/fade entirely and swaps in a
// static three-segment strip (within-normal / slow / stalled) — the same
// phase machine, same announcements, nothing depends on perceiving motion.
// ---------------------------------------------------------------------------

export type MeniscusPhase = "waiting" | "slow" | "stalled" | "arrived";

const TUBE_H = 48; // px, per spec
const TUBE_W = 6; // px, per spec
const DRAIN_MS = 380;
const DRAIN_EASE = "cubic-bezier(0.16,1,0.3,1)"; // ease-out-expo
const RISE_EASE = "cubic-bezier(0.22,1,0.36,1)"; // gentle decelerate, distinct from drain
const P95_FADE_MS_FLOOR = 250;

function useReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

function fmtSeconds(ms: number): string {
  const safe = Number.isFinite(ms) && ms > 0 ? ms : 0;
  return (safe / 1000).toFixed(1);
}

// A fraction as a percentage string, fixed to 4 decimals. The raw value
// serialized as "43.3333%" on the server and "43.333333333333336%" on the
// client, and React discards the subtree over a string that long. Four
// decimals is far below one device pixel on a tube this size.
function pct(frac: number): string {
  return (frac * 100).toFixed(4);
}

// which of the two timed phases (ignoring `arrivedAt`) a given elapsed-ms
// falls in, for a p50/p95 pair
function timedPhase(elapsedMs: number, p50Ms: number, p95Ms: number): "waiting" | "slow" | "stalled" {
  if (elapsedMs < p50Ms) return "waiting";
  if (elapsedMs < p95Ms) return "slow";
  return "stalled";
}

const CSS = `
.ns-mh-tremor { animation: ns-mh-tremor 500ms ease-in-out infinite; }
@keyframes ns-mh-tremor {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(0.5px); }
}
@media (prefers-reduced-motion: reduce) {
  .ns-mh-tremor { animation: none; }
}
`;

export interface MeniscusHoldProps {
  /** ms epoch timestamp this request/turn began. Defaults to Date.now() at mount. */
  startedAt?: number;
  /** historical p50 (typical) first-token latency in ms, e.g. from a rolling latency store */
  p50Ms: number;
  /** historical p95 first-token latency in ms — should be greater than p50Ms */
  p95Ms: number;
  /** ms epoch timestamp the first token actually arrived; null/undefined while still waiting */
  arrivedAt?: number | null;
  /** fired when the user presses Retry after a stall */
  onRetry?: () => void;
  /** fired when the user presses "Switch model" after a stall */
  onSwitchModel?: () => void;
  /** accessible name for the root status region. Default "Time to first token" */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function MeniscusHold({
  startedAt,
  p50Ms,
  p95Ms,
  arrivedAt,
  onRetry,
  onSwitchModel,
  label = "Time to first token",
  className = "",
}: MeniscusHoldProps) {
  const reduced = useReducedMotion();
  const [autoStart] = useState(() => Date.now());
  const start = startedAt ?? autoStart;
  const safeP50 = p50Ms > 0 ? p50Ms : 1;
  const safeP95 = p95Ms > safeP50 ? p95Ms : safeP50 + 1;

  const [timed, setTimed] = useState<"waiting" | "slow" | "stalled">(() =>
    timedPhase(Date.now() - start, safeP50, safeP95)
  );

  // re-arm the two threshold timers whenever a new request starts. A late
  // mount schedules only whatever time remains, so a component created
  // 300ms into a request still crosses p50 300ms early, not late.
  useEffect(() => {
    const elapsed = Date.now() - start;
    setTimed(timedPhase(elapsed, safeP50, safeP95));
    const toSlow = safeP50 - elapsed;
    const toStalled = safeP95 - elapsed;
    const timers: number[] = [];
    if (toSlow > 0) {
      timers.push(window.setTimeout(() => setTimed("slow"), toSlow));
    }
    if (toStalled > 0) {
      timers.push(window.setTimeout(() => setTimed("stalled"), toStalled));
    }
    return () => timers.forEach((t) => window.clearTimeout(t));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [start, safeP50, safeP95]);

  const phase: MeniscusPhase = arrivedAt ? "arrived" : timed;

  // fill height, as a fraction of the tube, held at the p50 line once
  // reached — it never keeps climbing toward p95, that would be fake
  // progress. p95 anchors the very top of the tube.
  const p50Frac = Math.max(0, Math.min(1, safeP50 / safeP95));
  // The first client render must serialize EXACTLY what the server sent, and
  // the server cannot know how many ms elapsed before the browser hydrated —
  // any clock read here produced transition-duration 650ms against the 649ms
  // already committed to the DOM. So the elapsed clock is not read during
  // render at all: both sides render the full p50 duration, and the real
  // remaining time is installed in an effect, which runs only after hydration
  // has matched. Behaviour is unchanged — the threshold timers above still
  // decide when each phase begins.
  const [elapsedAtMount, setElapsedAtMount] = useState(0);
  useEffect(() => {
    setElapsedAtMount(Date.now() - start);
  }, [start]);
  const riseRemainMs = Math.max(0, safeP50 - elapsedAtMount);

  let fillFrac: number;
  let fillMs: number;
  let fillEase: string;
  if (phase === "arrived") {
    fillFrac = 0;
    fillMs = reduced ? 0 : DRAIN_MS;
    fillEase = DRAIN_EASE;
  } else if (phase === "waiting") {
    fillFrac = p50Frac;
    fillMs = reduced ? 0 : riseRemainMs;
    fillEase = RISE_EASE;
  } else {
    // slow or stalled: held at the p50 line, no further rise
    fillFrac = p50Frac;
    fillMs = 0;
    fillEase = RISE_EASE;
  }

  // p95 tick fades in across the "slow" window, complete by the time
  // "stalled" arrives; instant under reduced motion (still legible, just
  // not animated).
  const p95FadeMs = Math.max(P95_FADE_MS_FLOOR, safeP95 - safeP50);
  // driven by the underlying timed phase, not the arrived overlay — a token
  // that lands before p50 was ever reached should never suddenly reveal a
  // mark it hadn't earned yet.
  const p95Visible = timed !== "waiting";

  // announce only on transition, never a running commentary on the level
  const [liveText, setLiveText] = useState("");
  const lastAnnouncedRef = useRef<MeniscusPhase | null>(null);
  useEffect(() => {
    if (lastAnnouncedRef.current === phase) return;
    lastAnnouncedRef.current = phase;
    if (phase === "waiting") {
      setLiveText(`Waiting, typically ${fmtSeconds(safeP50)} seconds.`);
    } else if (phase === "slow") {
      setLiveText("Taking longer than usual.");
    } else if (phase === "stalled") {
      setLiveText("May be stalled, retry available.");
    } else {
      setLiveText("Response arrived.");
    }
  }, [phase, safeP50]);

  const p50Label = `${fmtSeconds(safeP50)}s`;
  const p95Label = `${fmtSeconds(safeP95)}s`;

  const captionText =
    phase === "waiting"
      ? "waiting"
      : phase === "slow"
        ? "slower than usual"
        : phase === "stalled"
          ? "may be stalled"
          : "arrived";

  return (
    <div
      data-meniscus-root
      role="group"
      aria-label={label}
      className={`inline-flex items-start gap-4 ${className}`}
    >
      <style>{CSS}</style>

      {/* the visual tube/tick apparatus (or its reduced-motion stand-in) —
          a dedicated, spatially disjoint hook for tooling: it never overlaps
          the retry/switch buttons rendered in the sibling column below, so
          clicking it (inert — there is no handler here) can never
          accidentally land on a button that only exists once stalled. */}
      <div data-meniscus-display>
        {reduced ? (
          <ReducedIndicator phase={phase} />
        ) : (
          <div className="flex items-end" style={{ height: TUBE_H }}>
            {/* the tube */}
            <div
              className="relative rounded-sm border border-border"
              style={{ width: TUBE_W, height: TUBE_H }}
            >
              <div className="absolute inset-0 overflow-hidden rounded-sm">
                <div
                  aria-hidden
                  className="absolute inset-x-0 bottom-0"
                  style={{
                    height: `${pct(fillFrac)}%`,
                    backgroundColor: "var(--ns-muted)",
                    opacity: 0.25,
                    transition: `height ${fillMs}ms ${fillEase}`,
                  }}
                />
              </div>

              {/* meniscus — a small concave curve riding the fill's top edge,
                  a sibling of the clipped layer so it's never cut off */}
              <div
                aria-hidden
                className={phase === "slow" ? "ns-mh-tremor" : ""}
                style={{
                  position: "absolute",
                  left: -1,
                  right: -1,
                  bottom: `calc(${pct(fillFrac)}% - 2px)`,
                  height: 4,
                  transition: `bottom ${fillMs}ms ${fillEase}`,
                }}
              >
                <svg width={TUBE_W + 2} height={4} viewBox="0 0 8 4" style={{ display: "block" }}>
                  <path
                    d="M0,0.5 Q4,3.2 8,0.5"
                    fill="none"
                    stroke="var(--foreground)"
                    strokeWidth="1"
                    strokeLinecap="round"
                  />
                </svg>
              </div>
            </div>

            {/* scribe marks + labels */}
            <div className="relative ml-2" style={{ height: TUBE_H, width: 34 }}>
              <Tick bottomFrac={p50Frac} label={p50Label} opacity={1} />
              <Tick
                bottomFrac={1}
                label={p95Label}
                opacity={p95Visible ? 1 : 0}
                transitionMs={reduced ? 0 : p95FadeMs}
              />
            </div>
          </div>
        )}
      </div>

      <div className="flex flex-col gap-2">
        <span className="font-mono text-[10px] uppercase tracking-[0.14em] text-ns-muted">
          {captionText}
        </span>

        {phase === "stalled" && (
          <div className="flex items-center gap-2">
            <button
              type="button"
              data-meniscus-retry
              onClick={onRetry}
              className="rounded-sm border border-border px-2 py-1 font-mono text-[11px] text-foreground transition-colors hover:bg-foreground/10 focus-visible:outline focus-visible:outline-2 focus-visible:outline-ns-accent"
            >
              Retry
            </button>
            <button
              type="button"
              data-meniscus-switch
              onClick={onSwitchModel}
              className="rounded-sm border border-border px-2 py-1 font-mono text-[11px] text-ns-muted transition-colors hover:bg-foreground/10 hover:text-foreground focus-visible:outline focus-visible:outline-2 focus-visible:outline-ns-accent"
            >
              Switch model
            </button>
          </div>
        )}
      </div>

      <p role="status" aria-live="polite" className="sr-only">
        {liveText}
      </p>
    </div>
  );
}

function Tick({
  bottomFrac,
  label,
  opacity,
  transitionMs = 0,
}: {
  bottomFrac: number;
  label: string;
  opacity: number;
  transitionMs?: number;
}) {
  return (
    <div
      aria-hidden
      className="absolute left-0 flex items-center gap-1"
      style={{
        bottom: `calc(${pct(bottomFrac)}% - 0.5px)`,
        opacity,
        transition: `opacity ${transitionMs}ms linear`,
      }}
    >
      <span className="block" style={{ width: 5, height: 1, backgroundColor: "var(--foreground)" }} />
      <span className="whitespace-nowrap font-mono text-[9px] text-ns-muted">{label}</span>
    </div>
  );
}

// Static, motion-free fallback: three fixed segments, the current phase lit
// from --ns-muted to --foreground. Same phase machine drives this branch —
// nothing here depends on perceiving a rise or a tremble.
function ReducedIndicator({ phase }: { phase: MeniscusPhase }) {
  const segments: { key: "waiting" | "slow" | "stalled"; text: string }[] = [
    { key: "waiting", text: "normal" },
    { key: "slow", text: "slow" },
    { key: "stalled", text: "stalled" },
  ];
  const activeKey = phase === "arrived" ? null : phase;
  return (
    <div className="flex items-end gap-1" style={{ height: TUBE_H }}>
      {segments.map((seg) => {
        const active = seg.key === activeKey;
        return (
          <div key={seg.key} className="flex flex-col items-center gap-1">
            <div
              className="rounded-sm border border-border"
              style={{
                width: TUBE_W,
                height: TUBE_H - 10,
                backgroundColor: active ? "var(--foreground)" : "var(--ns-muted)",
                opacity: active ? 0.55 : 0.15,
              }}
            />
            <span className="font-mono text-[8px] uppercase tracking-[0.1em] text-ns-muted">
              {seg.text}
            </span>
          </div>
        );
      })}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// MeterMatrixScan — a level meter rendered as a genuinely row-multiplexed
// LED dot-matrix panel.
//
// SOURCE, NOT INVENTED: cheap commercial LED dot-matrix signage (scrolling
// ticker boards, gym scoreboards, elevator floor indicators, budget
// character displays built on row/column multiplex driver chips) can't
// afford one continuous driver per LED. Instead the panel scans one row at
// a time at a frequency well above human flicker fusion, relying on
// persistence of vision to read a complete static image, and within each
// row's brief active slice an individual LED's apparent brightness is set
// by PWM (pulse-width modulation) duty cycle — fully on or fully off at any
// instant, perceived brightness being the fraction of the row's active
// window it spends on, quantized to a small number of duty steps. That
// quantized time-division duty cycle (not a continuous alpha/density value)
// is this component's entire identity, distinct from every other
// ASCII/glyph-luminance component in the registry.
//
// THE ROW-SCAN ARTIFACT: a real multiplex board's per-row scan is invisible
// at rest — that's the whole point of persistence of vision. It only ever
// becomes visible when something samples the panel at a rate that doesn't
// divide evenly into its own full-panel refresh, e.g. filming an LED sign
// with a camera whose shutter/frame rate doesn't line up with the panel's
// scan rate produces a soft band drifting through the image (the reason
// dashcam footage sometimes shows a faint bar through LED signage). A literal
// 1:1 real-time render of the raw ROW_SCAN_HZ clock against a ~60Hz browser
// paint rate aliases close enough to the paint rate itself to read as a hard
// strobe/flicker — a rendering-pipeline artifact, not the calm hardware
// phenomenon it's meant to represent. So the scan address (ROW_SCAN_HZ,
// documented below, is the real underlying clock) is deliberately mapped onto
// a slow, continuous sweep position instead of a discrete per-frame row
// index: a soft brightness gradient a couple of rows wide, low amplitude,
// drifting the full height of the panel and back over several seconds — the
// same round-robin row addressing concept, legible on a second look, without
// ever strobing near the paint rate.
// ---------------------------------------------------------------------------

const ROWS = 5;
const ROW_SCAN_HZ = 240; // real per-row multiplex clock this component represents
const PWM_LEVELS = 8; // 3-bit duty-cycle depth
const GUTTER_PX = 3; // gap between dots, ~2-4px per spec
const SWEEP_PERIOD_S = 7.5; // one full down-and-back sweep across the panel
const SWEEP_SIGMA_ROWS = 1.4; // gradient softness, in rows — wide, not a 1-row strip
const SCAN_HIGHLIGHT_ALPHA = 0.055; // luminance-only, low-amplitude boost at the sweep's center
const MIN_ON_ALPHA = 0.16; // floor so PWM band 1/8 never rounds to invisible in light theme

// slow generative "sensor" field used only when no external `value` prop is
// supplied — three non-commensurate traveling sine components, amplitude
// bounded so the simulated reading stays comfortably inside 0..100.
function sensorValue(t: number) {
  const f =
    Math.sin(t * 0.17) + 0.5 * Math.sin(t * 0.43 + 1.3) + 0.3 * Math.sin(t * 0.08 + 2.1);
  const norm = f / 1.8; // amplitude sum 1.8 -> -1..1
  return 55 + norm * 32; // ~23..87
}

// continuous sweep position, in row units (0..ROWS-1), a slow triangle wave
// so the drift is smooth and reverses without a jump-cut at either end
function sweepPosition(t: number) {
  const phase = (t % SWEEP_PERIOD_S) / SWEEP_PERIOD_S; // 0..1
  const tri = phase < 0.5 ? phase * 2 : 2 - phase * 2; // 0 -> 1 -> 0
  return tri * (ROWS - 1);
}

export interface MeterMatrixScanProps {
  /** current level, 0..max. Omit to drive the meter from an internal simulated sensor read. */
  value?: number;
  /** domain ceiling for value. Default 100. */
  max?: number;
  /** accessible name for the reading, e.g. "CPU load". Default "Level". */
  label?: string;
  /** panel height in px; ROWS=5 fixed, cell size derives as height / 5. Default 60. */
  height?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function MeterMatrixScan({
  value,
  max = 100,
  label = "Level",
  height = 60,
  className = "",
}: MeterMatrixScanProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const valueRef = useRef(value);
  valueRef.current = value;

  useEffect(() => {
    const canvas = canvasRef.current;
    const wrapper = wrapperRef.current;
    if (!canvas || !wrapper) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let bg = "";
    let fg = "";

    const cellSize = Math.max(2, height / ROWS);
    const radius = Math.max(1, (cellSize - GUTTER_PX) / 2);

    let cols = 0;
    let sized = false;
    let lastWidth = 0;

    const readTokens = () => {
      const root = getComputedStyle(document.documentElement);
      // fallbacks are CSS keywords, never literal colour values
      bg = root.getPropertyValue("--background").trim() || "transparent";
      fg = root.getPropertyValue("--foreground").trim() || "currentColor";
    };

    const resize = () => {
      const { width } = canvas.getBoundingClientRect();
      if (width < 2) {
        sized = false;
        return;
      }
      if (sized && Math.abs(width - lastWidth) < 1) return;
      lastWidth = width;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      cols = Math.max(6, Math.floor(width / cellSize));
      sized = true;
    };

    // globalT: seconds, drives both the simulated sensor field (when
    // `value` is uncontrolled) and the sweep position. Never resets.
    let globalT = 0;

    const currentValue = () => {
      const external = valueRef.current;
      const v = external === undefined ? sensorValue(globalT) : external;
      return Math.min(max, Math.max(0, v));
    };

    const draw = (sweepPos: number | null) => {
      if (!sized) return;
      const w = cols * cellSize;
      ctx.clearRect(0, 0, w, height);
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, w, height);

      const filled = (currentValue() / max) * cols;
      const fullCols = Math.min(cols, Math.floor(filled));
      const frac = filled - fullCols;
      // fractional boundary LED's brightness is a literal quantized PWM
      // duty step, never a smooth alpha ramp
      const boundaryLevel = Math.round(frac * PWM_LEVELS);

      for (let r = 0; r < ROWS; r++) {
        const cy = r * cellSize + cellSize / 2;
        // soft Gaussian weight of this row against the sweep's current
        // center — a wide, low-amplitude bump, not a hard on/off strip, so
        // several rows share a gentle gradient rather than one strobing
        let sweepBoost = 0;
        if (sweepPos !== null) {
          const d = r - sweepPos;
          sweepBoost = SCAN_HIGHLIGHT_ALPHA * Math.exp(-(d * d) / (2 * SWEEP_SIGMA_ROWS * SWEEP_SIGMA_ROWS));
        }
        for (let c = 0; c < cols; c++) {
          let level = 0;
          if (c < fullCols) level = PWM_LEVELS;
          else if (c === fullCols) level = boundaryLevel;
          if (level <= 0) continue;

          let alpha = level / PWM_LEVELS;
          alpha = Math.max(MIN_ON_ALPHA, alpha);
          alpha = Math.min(1, alpha + sweepBoost);

          const cx = c * cellSize + cellSize / 2;
          ctx.globalAlpha = alpha;
          ctx.fillStyle = fg;
          ctx.beginPath();
          ctx.arc(cx, cy, radius, 0, Math.PI * 2);
          ctx.fill();
        }

        // the same soft gradient laid across only the off (background)
        // columns of this row — what makes the sweep legible independent of
        // the value fill, luminance only, never a hard band. Confined to the
        // unlit region so it never stacks on top of an already-boosted dot.
        const offStartX = Math.min(w, (fullCols + 1) * cellSize);
        if (sweepBoost > 0.002 && offStartX < w) {
          ctx.globalAlpha = sweepBoost * 0.7;
          ctx.fillStyle = fg;
          ctx.fillRect(offStartX, r * cellSize, w - offStartX, cellSize);
        }
      }
      ctx.globalAlpha = 1;

      wrapper.setAttribute("aria-valuenow", String(Math.round(currentValue())));
    };

    // -- loop ----------------------------------------------------------------
    let raf = 0;
    let last = 0;

    const loop = (now: number) => {
      const dtMs = last ? Math.min(250, now - last) : 1000 / 60;
      last = now;
      globalT += dtMs / 1000;
      draw(sweepPosition(globalT));
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) draw(null);
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        readTokens();
        resize();
        draw(reduced ? null : sweepPosition(globalT));
      }, 150);
    };
    const ro = new ResizeObserver(onResize);
    ro.observe(canvas);

    const io = new IntersectionObserver(
      (entries) => {
        const visible = entries[0]?.isIntersecting;
        if (visible && !reduced && sized) {
          cancelAnimationFrame(raf);
          last = 0;
          raf = requestAnimationFrame(loop);
        } else if (!visible) {
          cancelAnimationFrame(raf);
        }
      },
      { threshold: 0 }
    );
    io.observe(canvas);

    const onVis = () => {
      cancelAnimationFrame(raf);
      if (!document.hidden && !reduced && sized) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };
    document.addEventListener("visibilitychange", onVis);

    // no paint before the first token read
    readTokens();
    resize();

    if (reduced) {
      // freeze with the sweep locked off entirely — no gradient visible,
      // every row rendered as if simultaneously lit at its true duty level —
      // at a value past the field's cold-start instant, same convention as
      // this registry's other generative components.
      globalT = 1.4;
      draw(null);
    } else {
      draw(sweepPosition(globalT));
      raf = requestAnimationFrame(loop);
    }

    return () => {
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      mo.disconnect();
      ro.disconnect();
      io.disconnect();
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [height, max]);

  return (
    <div
      ref={wrapperRef}
      role="meter"
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={max}
      className={`ns-mms w-full ${className}`}
    >
      <canvas
        ref={canvasRef}
        aria-hidden="true"
        className="block w-full"
        style={{ height }}
      />
    </div>
  );
}

"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// MeniscusMeter — a quota (storage, API budget, seats) rendered as liquid in
// a thin open-top vessel, where the fill's top-edge CURVATURE, not its level,
// carries the reading. Under the soft limit the level rises normally and the
// edge is concave (wets the walls, dips at center — climbs higher at the
// walls than the middle, same physical tell as water in a narrow glass tube).
// Exactly at the soft limit it flattens. Between soft and hard the level
// pins at the rim and the edge inverts to convex, bulging progressively
// higher above the rim as the value approaches the hard cap — visibly
// overfull, still held by surface tension, no color change required to read
// "tolerated but over." The instant value crosses the hard limit a bead
// detaches from the outer wall and eases down under gravity, then a static
// 1px --ns-muted stain remains — the crossing becomes a permanent mark, not
// just a momentary state. The whole shape is one SVG cubic bezier: fixed
// endpoints at the current level, two shared control points whose y-offset
// from that level is the single scalar that walks concave -> flat -> convex.
// A CSS transition on `d` with a back-out (overshoot) timing function is the
// "soft spring" — one wobble past the target, then it settles, no JS
// simulation loop needed. `role=meter` carries the real semantics (SVG is
// aria-hidden); a Geist Mono numeric readout beside the vessel means
// curvature is never the only signal. Every stroke/fill is a token-driven
// Tailwind class (text-border/text-ns-muted/text-foreground/text-ns-accent) at
// low opacity — no hex, no canvas, no getComputedStyle needed since nothing
// here is a raster surface.
// ---------------------------------------------------------------------------

export interface MeniscusMeterProps {
  /** current usage, same unit as softLimit/hardLimit */
  value: number;
  /** the soft threshold — the vessel's rim; reaching it flattens the surface */
  softLimit: number;
  /** the hard cap — crossing it detaches a bead and leaves a stain */
  hardLimit: number;
  /** unit suffix for every readout, e.g. "%", "GB", "seats" (default "%") */
  unit?: string;
  /** what's being metered, shown above the vessel, e.g. "Storage" */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

type Zone = "headroom" | "grace" | "spill";

// vessel geometry, SVG viewBox units
const VIEW_W = 96;
const VIEW_H = 168;
const WALL_L = 30;
const WALL_R = 66;
const RIM_Y = 34;
const FLOOR_Y = 142;
const MAX_CONCAVE = 9; // control-point dip at value = 0 (deep headroom)
const MAX_CONVEX = 20; // control-point rise at value = hardLimit (max dome)
// a two-control-point cubic's midpoint sits at 0.25*end + 0.75*control, so a
// concave dip of MAX_CONCAVE bows the visible trough ~0.75*MAX_CONCAVE below
// the wall-anchor point — reserve that much clearance above FLOOR_Y so an
// empty vessel's dipped meniscus never renders below the drawn floor line.
const LEVEL_FLOOR_Y = FLOOR_Y - Math.ceil(MAX_CONCAVE * 0.75) - 3;
const BEAD_X = WALL_R + 4;
const DRIP_LEN = 46; // stain length below the rim

function clamp(n: number, lo: number, hi: number) {
  return Math.max(lo, Math.min(hi, n));
}

function fmt(n: number) {
  if (!Number.isFinite(n)) return "0";
  const abs = Math.abs(n);
  if (Number.isInteger(n) || abs >= 100) return Math.round(n).toString();
  return n.toFixed(1);
}

function useReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

function zoneAnnounce(zone: Zone) {
  if (zone === "spill") return "over hard limit — overflowing";
  if (zone === "grace") return "over soft limit — still held";
  return "within soft limit";
}

function zoneShort(zone: Zone) {
  if (zone === "spill") return "over hard limit";
  if (zone === "grace") return "over soft limit";
  return "under soft limit";
}

function surface(value: number, softLimit: number, hardLimit: number) {
  const soft = Math.max(1e-6, softLimit);
  const hard = Math.max(soft + 1e-6, hardLimit);
  let levelY: number;
  let curveOffset: number; // positive = convex dome, negative = concave dip
  let zone: Zone;
  if (value <= soft) {
    const t = clamp(value / soft, 0, 1); // 0 empty -> 1 at rim
    levelY = LEVEL_FLOOR_Y - t * (LEVEL_FLOOR_Y - RIM_Y);
    curveOffset = -MAX_CONCAVE * (1 - t);
    zone = "headroom";
  } else {
    levelY = RIM_Y; // pinned — the level itself never rises further
    const t = clamp((value - soft) / (hard - soft), 0, 1);
    curveOffset = MAX_CONVEX * t;
    zone = value >= hard ? "spill" : "grace";
  }
  return { levelY, curveOffset, zone };
}

function surfacePath(levelY: number, curveOffset: number) {
  const cpY = levelY - curveOffset;
  const cp1x = WALL_L + (WALL_R - WALL_L) * 0.33;
  const cp2x = WALL_L + (WALL_R - WALL_L) * 0.67;
  return `M ${WALL_L} ${levelY} C ${cp1x} ${cpY} ${cp2x} ${cpY} ${WALL_R} ${levelY}`;
}

function fillPath(levelY: number, curveOffset: number) {
  return `${surfacePath(levelY, curveOffset)} L ${WALL_R} ${FLOOR_Y} L ${WALL_L} ${FLOOR_Y} Z`;
}

export function MeniscusMeter({
  value,
  softLimit,
  hardLimit,
  unit = "%",
  label = "Usage",
  className = "",
}: MeniscusMeterProps) {
  const uid = useId();
  const reduced = useReducedMotion();
  const { levelY, curveOffset, zone } = useMemo(
    () => surface(value, softLimit, hardLimit),
    [value, softLimit, hardLimit]
  );

  const prevZoneRef = useRef<Zone>(zone);
  const [stained, setStained] = useState(zone === "spill");
  const [beadTick, setBeadTick] = useState(0);
  const [announce, setAnnounce] = useState(() => zoneAnnounce(zone));

  useEffect(() => {
    const prev = prevZoneRef.current;
    if (prev !== zone) {
      setAnnounce(zoneAnnounce(zone));
      if (zone === "spill") {
        setStained(true);
        if (prev !== "spill") setBeadTick((k) => k + 1);
      } else if (zone === "headroom") {
        setStained(false);
      }
      prevZoneRef.current = zone;
    }
  }, [zone]);

  const labelId = `${uid}-label`;
  const liveId = `${uid}-live`;
  const unitSuffix = unit === "%" ? "%" : unit ? ` ${unit}` : "";
  const valueText = `${fmt(value)}${unitSuffix}, ${zoneShort(zone)}`;
  const d = fillPath(levelY, curveOffset);
  const surfaceD = surfacePath(levelY, curveOffset);

  return (
    <div className={className}>
      <style>{`
.ns-meniscus-fill,.ns-meniscus-surface{transition:d 700ms cubic-bezier(0.34,1.56,0.64,1)}
@keyframes ns-meniscus-drip{
  0%{transform:translateY(0);opacity:1}
  70%{opacity:1}
  100%{transform:translateY(${DRIP_LEN}px);opacity:0}
}
.ns-meniscus-bead{animation:ns-meniscus-drip 900ms cubic-bezier(0.55,0,0.85,0.35) 1}
@media (prefers-reduced-motion: reduce){
  .ns-meniscus-fill,.ns-meniscus-surface{transition-duration:140ms;transition-timing-function:linear}
  .ns-meniscus-bead{animation:none}
}
`}</style>

      <div className="flex items-baseline justify-between gap-3">
        <span id={labelId} className="font-mono text-[11px] tracking-wide text-ns-muted">
          {label.toUpperCase()}
        </span>
        <span
          className={
            "font-mono text-[11px] tracking-wide text-foreground " +
            (zone !== "headroom" ? "font-semibold" : "")
          }
        >
          {zoneShort(zone)}
        </span>
      </div>

      <div className="mt-1 flex items-baseline gap-1.5">
        <span className="text-2xl font-semibold tabular-nums text-foreground">
          {fmt(value)}
          {unit === "%" ? "%" : ""}
        </span>
        <span className="font-mono text-xs text-ns-muted">
          / {fmt(hardLimit)}
          {unit !== "%" ? ` ${unit}` : ""} cap
        </span>
      </div>

      <div
        role="meter"
        aria-labelledby={labelId}
        aria-valuemin={0}
        aria-valuemax={hardLimit}
        aria-valuenow={value}
        aria-valuetext={valueText}
        className="mt-3 flex justify-center"
      >
        <svg
          viewBox={`0 0 ${VIEW_W} ${VIEW_H}`}
          className="h-[168px] w-[96px]"
          aria-hidden
          focusable="false"
        >
          {/* floor */}
          <line
            x1={WALL_L}
            x2={WALL_R}
            y1={FLOOR_Y}
            y2={FLOOR_Y}
            className="stroke-current text-border"
            strokeWidth={1.5}
          />
          {/* liquid body, fill under the meniscus curve */}
          <path d={d} className="ns-meniscus-fill fill-current text-foreground opacity-[0.14]" />
          {/* surface line, more opaque than the body fill */}
          <path
            d={surfaceD}
            fill="none"
            className="ns-meniscus-surface stroke-current text-foreground"
            strokeWidth={1.5}
            strokeLinecap="round"
          />
          {/* walls, stop exactly at the rim so a grace-zone dome visibly rises
              into open space above them, unconfined */}
          <line
            x1={WALL_L}
            x2={WALL_L}
            y1={RIM_Y}
            y2={FLOOR_Y}
            className="stroke-current text-border"
            strokeWidth={2}
          />
          <line
            x1={WALL_R}
            x2={WALL_R}
            y1={RIM_Y}
            y2={FLOOR_Y}
            className="stroke-current text-border"
            strokeWidth={2}
          />
          {/* rim lip ticks */}
          <line
            x1={WALL_L - 3}
            x2={WALL_L + 3}
            y1={RIM_Y}
            y2={RIM_Y}
            className="stroke-current text-border"
            strokeWidth={1.5}
          />
          <line
            x1={WALL_R - 3}
            x2={WALL_R + 3}
            y1={RIM_Y}
            y2={RIM_Y}
            className="stroke-current text-border"
            strokeWidth={1.5}
          />
          {/* stain — static, left by the hard-limit crossing */}
          {stained ? (
            <line
              x1={BEAD_X}
              x2={BEAD_X}
              y1={RIM_Y}
              y2={RIM_Y + DRIP_LEN}
              className="stroke-current text-ns-muted opacity-60"
              strokeWidth={1}
            />
          ) : null}
          {/* bead — one-shot drop animation replayed via key on each crossing */}
          {!reduced && beadTick > 0 ? (
            <circle
              key={beadTick}
              cx={BEAD_X}
              cy={RIM_Y}
              r={2.25}
              className="ns-meniscus-bead fill-current text-ns-muted"
            />
          ) : null}
        </svg>
      </div>

      <p className="mt-2 text-center font-mono text-[11px] text-ns-muted">
        {zone === "spill"
          ? "held — overflow marked on the glass"
          : zone === "grace"
            ? "over the soft limit, still tolerated"
            : `${fmt(Math.max(0, softLimit - value))}${unitSuffix} of headroom left`}
      </p>

      <span id={liveId} role="status" aria-live="polite" className="sr-only">
        {announce}
      </span>
    </div>
  );
}

"use client";

import { useEffect, useId, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// RationRule — a quota meter with no bar, no fill, no pill: just the printed
// reading ('38.2 GB of 100 GB') sitting directly above a 4px-tall hairline.
// The rule itself IS the meter — its used portion is a solid --foreground
// stroke, its remainder a dashed --border stroke (2 3), and the boundary
// between them eases with the value. A fixed tick marks the warning
// threshold in --warning, never on the fill; crossing it doesn't turn
// anything red, it thickens the solid stroke 1px -> 2px and steps the
// numerals from weight 400 to 600 — the line asserts itself instead of
// alarming. Meant to sit dozens-deep on a settings page (storage, seats,
// API credits, budget) at text scale. Pure inline SVG + CSS, no canvas.
// ---------------------------------------------------------------------------

export interface RationRuleProps {
  /** what's being rationed, e.g. "Storage" — shown as a caption and used as the meter's accessible name */
  label: string;
  /** amount currently used */
  value: number;
  /** total allowance */
  max: number;
  /** short unit printed after both numbers, e.g. "GB" */
  unit: string;
  /** full unit word spoken by aria-valuetext, e.g. "gigabytes" — defaults to `unit` */
  unitLabel?: string;
  /** fraction of max (0-1) at which the rule crosses into warning weight */
  warning?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const VIEW_W = 400;
const VIEW_H = 6;
const RULE_Y = VIEW_H / 2;
const MOVE_MS = 350;

function easeOutExpo(t: number) {
  return t >= 1 ? 1 : 1 - Math.pow(2, -10 * t);
}

function fmt(n: number) {
  if (!Number.isFinite(n)) return "0";
  const rounded = Math.round(n * 10) / 10;
  return Number.isInteger(rounded) ? String(rounded) : rounded.toFixed(1);
}

function clamp01(n: number) {
  if (Number.isNaN(n)) return 0;
  return Math.min(1, Math.max(0, n));
}

function useReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

// eases `target` toward its resting value over `duration`ms with
// ease-out-expo, cleanly retargeting mid-flight from whatever the display
// value currently is. Snaps instantly when `reduced`.
function useEasedFraction(target: number, duration: number, reduced: boolean) {
  const [display, setDisplay] = useState(target);
  const displayRef = useRef(target);
  const fromRef = useRef(target);
  const toRef = useRef(target);
  const startRef = useRef(0);
  const rafRef = useRef<number | null>(null);

  useEffect(() => {
    if (reduced) {
      if (rafRef.current !== null) cancelAnimationFrame(rafRef.current);
      rafRef.current = null;
      displayRef.current = target;
      fromRef.current = target;
      toRef.current = target;
      setDisplay(target);
      return;
    }
    if (target === toRef.current) return;
    fromRef.current = displayRef.current;
    toRef.current = target;
    startRef.current = performance.now();
    if (rafRef.current !== null) cancelAnimationFrame(rafRef.current);

    const tick = (now: number) => {
      const t = Math.min(1, (now - startRef.current) / duration);
      const eased = easeOutExpo(t);
      const next = fromRef.current + (toRef.current - fromRef.current) * eased;
      displayRef.current = next;
      setDisplay(next);
      rafRef.current = t < 1 ? requestAnimationFrame(tick) : null;
    };
    rafRef.current = requestAnimationFrame(tick);
    return () => {
      if (rafRef.current !== null) cancelAnimationFrame(rafRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [target, duration, reduced]);

  return display;
}

export function RationRule({
  label,
  value,
  max,
  unit,
  unitLabel,
  warning = 0.8,
  className = "",
}: RationRuleProps) {
  const uid = useId();
  const reduced = useReducedMotion();

  const safeMax = max > 0 ? max : 1e-6;
  const targetFraction = clamp01(value / safeMax);
  const warningFraction = clamp01(warning);

  const displayFraction = useEasedFraction(targetFraction, MOVE_MS, reduced);

  // final rest-state crossing drives ARIA (never mid-animation dependent);
  // the visual stroke width/weight track the live animated position, so the
  // thickening visibly happens AT the tick as the boundary sweeps past it.
  const crossedFinal = targetFraction >= warningFraction;
  const crossedLive = displayFraction >= warningFraction;

  const boundaryX = displayFraction * VIEW_W;
  const tickX = warningFraction * VIEW_W;

  const usedText = fmt(value);
  const maxText = fmt(max);
  const resolvedUnitLabel = unitLabel || unit;
  const stateText = crossedFinal
    ? "at or above warning threshold"
    : "below warning threshold";
  const valueText =
    `${usedText} of ${maxText} ${resolvedUnitLabel}, ${stateText}`.replace(
      /\s+/g,
      " "
    );

  const labelId = `${uid}-label`;

  return (
    <div className={className}>
      <style>{`
.ns-ration-solid{transition:stroke-width 200ms cubic-bezier(0.22,1,0.36,1)}
.ns-ration-weight{transition:font-weight 200ms cubic-bezier(0.22,1,0.36,1)}
@media (prefers-reduced-motion: reduce){
  .ns-ration-solid{transition:none}
  .ns-ration-weight{transition:none}
}
`}</style>

      <span id={labelId} className="block font-mono text-[11px] tracking-wide text-ns-muted">
        {label.toUpperCase()}
      </span>

      <p
        className={
          "ns-ration-weight mt-1 text-sm tabular-nums text-foreground " +
          (crossedLive ? "font-semibold" : "font-normal")
        }
      >
        {usedText} {unit}{" "}
        <span className="text-ns-muted">
          of {maxText} {unit}
        </span>
      </p>

      <div
        role="meter"
        aria-labelledby={labelId}
        aria-valuemin={0}
        aria-valuemax={max}
        aria-valuenow={value}
        aria-valuetext={valueText}
        className="mt-1.5"
      >
        <svg
          viewBox={`0 0 ${VIEW_W} ${VIEW_H}`}
          preserveAspectRatio="none"
          className="block h-1.5 w-full"
          aria-hidden
          focusable="false"
        >
          <line
            x1={boundaryX}
            y1={RULE_Y}
            x2={VIEW_W}
            y2={RULE_Y}
            vectorEffect="non-scaling-stroke"
            strokeWidth={1}
            strokeDasharray="2 3"
            strokeLinecap="butt"
            className="stroke-current text-border"
          />
          <line
            x1={0}
            y1={RULE_Y}
            x2={boundaryX}
            y2={RULE_Y}
            vectorEffect="non-scaling-stroke"
            strokeWidth={crossedLive ? 2 : 1}
            strokeLinecap="butt"
            className="ns-ration-solid stroke-current text-foreground"
          />
          <line
            x1={tickX}
            y1={0}
            x2={tickX}
            y2={VIEW_H}
            vectorEffect="non-scaling-stroke"
            strokeWidth={1}
            style={{ stroke: "var(--warning, #f5a623)" }}
          />
        </svg>
      </div>

      <p role="status" aria-live="polite" className="sr-only">
        {valueText}
      </p>
    </div>
  );
}

"use client";

import { useEffect, useId, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// BimetalTrip — a data-driven threshold indicator built like a thermostat's
// bimetallic strip. One SVG quadratic-bezier path is fixed at two mounting
// posts; only its control point moves, offset upward as `value` climbs
// toward `tripAt` — straight at the bottom of the range, closing in on (but
// deliberately never quite touching) the contact pad as it nears the trip
// point, so there is always a real gap left for the latch to snap shut. That
// crossing LATCHES: the strip stays pinned at full bow (heavier --foreground
// stroke, filled contact pad — never
// --ns-accent, latching is data state, not interaction) regardless of value
// wobbling anywhere between `clearAt` and `tripAt`. It only relaxes back
// once value falls below `clearAt`, the lower re-arm mark — that gap between
// where it trips and where it clears is hysteresis made visible, not implied
// by a color. The snap into contact is a 320ms CSS `d`-transition on a
// back-out curve (~12% overshoot, no JS spring loop); the re-arm relax is a
// slow 600ms ease-out-expo settle; ordinary climbing between ticks gets a
// quick, non-overshooting ease. A muted hairline band under the strip spans
// clearAt..tripAt on the same x-domain as the strip's own mounts, with a
// live position marker and Geist Mono 'clears N / trips N' captions, so the
// two thresholds are legible from a single still frame. Every stroke/fill is
// a token class (text-foreground/text-ns-muted/text-border) — no hex, no
// canvas. DOM+SVG+CSS only.
// ---------------------------------------------------------------------------

export interface BimetalTripProps {
  /** the live metric being watched */
  value: number;
  /** the upper threshold — crossing it latches the strip against the contact */
  tripAt: number;
  /** the lower re-arm mark — the strip only relaxes once value falls below this */
  clearAt: number;
  /** domain floor for the visual scale (default 0) */
  min?: number;
  /** domain ceiling for the visual scale (default 100) */
  max?: number;
  /** unit suffix for readouts, e.g. "%", "ms", "req/s" (default "%") */
  unit?: string;
  /** what's being watched, shown above the strip, e.g. "CPU temp" */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

// geometry, SVG viewBox units
const VIEW_W = 320;
const VIEW_H = 150;
const ANCHOR_L_X = 40;
const ANCHOR_R_X = 280;
const MID_X = (ANCHOR_L_X + ANCHOR_R_X) / 2;
const BASE_Y = 62;
const MAX_CONTROL_OFFSET = 46; // control-point y-offset at full bow (bowFrac 1)
const PEAK_OFFSET = MAX_CONTROL_OFFSET / 2; // a quadratic's true peak sits at half the control offset
const CONTACT_Y = BASE_Y - PEAK_OFFSET; // where the strip's tip meets the pad, fully latched
const POST_TOP_Y = CONTACT_Y - 18;
const PAD_W = 16;
const PAD_H = 5;
const BAND_Y = 112;
const BAND_H = 6;
const TICK_H = 10;
// the unlatched approach curve's ceiling — kept below 1 (full/latched bow) so
// there is always a real geometric gap left against the contact pad for the
// latch's snap to close; see the bowFrac comment below for why this matters.
const UNLATCHED_BOW_CEILING = 0.75;

type TransitionKind = "climb" | "snap" | "rearm";

function clamp(n: number, lo: number, hi: number) {
  return Math.max(lo, Math.min(hi, n));
}

function fmt(n: number) {
  if (!Number.isFinite(n)) return "0";
  const abs = Math.abs(n);
  if (Number.isInteger(n) || abs >= 100) return Math.round(n).toString();
  return n.toFixed(1);
}

function useReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

function transitionStyle(kind: TransitionKind, reduced: boolean) {
  // The strip's curvature IS the reading (latched vs. clear) — a 0ms jump
  // removes the only passive signal that value crossed a threshold. Keep a
  // short, non-overshooting linear settle instead of the full snap/rearm
  // spring curves.
  if (reduced) return { transitionDuration: "140ms", transitionTimingFunction: "linear" };
  if (kind === "snap") {
    return {
      transitionDuration: "320ms",
      transitionTimingFunction: "cubic-bezier(0.34, 1.56, 0.64, 1)",
    };
  }
  if (kind === "rearm") {
    return {
      transitionDuration: "600ms",
      transitionTimingFunction: "cubic-bezier(0.16, 1, 0.3, 1)",
    };
  }
  return {
    transitionDuration: "260ms",
    transitionTimingFunction: "cubic-bezier(0.16, 1, 0.3, 1)",
  };
}

export function BimetalTrip({
  value,
  tripAt,
  clearAt,
  min = 0,
  max = 100,
  unit = "%",
  label = "Threshold",
  className = "",
}: BimetalTripProps) {
  const uid = useId();
  const reduced = useReducedMotion();

  // latched is derived data state, initialized once from the mounting value
  // so a demo/dashboard that mounts already past tripAt renders latched with
  // no spurious snap animation on first paint.
  const [latched, setLatched] = useState(() => value >= tripAt);
  const [transitionKind, setTransitionKind] = useState<TransitionKind>("climb");
  const [announce, setAnnounce] = useState("");
  const mountedRef = useRef(false);

  useEffect(() => {
    if (!mountedRef.current) {
      mountedRef.current = true;
      return;
    }
    if (!latched && value >= tripAt) {
      setLatched(true);
      setTransitionKind("snap");
      setAnnounce(
        `Latched — ${fmt(value)}${unit} crossed trip at ${fmt(tripAt)}${unit}. Holds until it falls below ${fmt(clearAt)}${unit}.`
      );
    } else if (latched && value < clearAt) {
      setLatched(false);
      setTransitionKind("rearm");
      setAnnounce(`Re-armed — ${fmt(value)}${unit} fell below clear mark ${fmt(clearAt)}${unit}.`);
    } else {
      setTransitionKind("climb");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value, tripAt, clearAt]);

  // BUG FIX: bowFrac must never let the *unlatched* approach curve reach the
  // same numeric value as the *latched* pinned bow (1). It used to — clamp()
  // saturated the unlatched formula to exactly 1 the instant value reached
  // tripAt, which is the same value the latch pins to, so by the time the
  // `latched` effect actually flipped (one tick later) the path's `d` hadn't
  // changed at all: no delta for the CSS transition to animate, so the
  // signature 320ms back-out "snap into contact" never played — the strip
  // just silently arrived already fully bowed. Capping the unlatched
  // approach short of 1 keeps a real, persistent gap against the contact pad
  // (matching "closes a visible gap" below) so crossing tripAt always leaves
  // genuine distance for the snap to close, regardless of step size.
  const safeTripAt = tripAt > min ? tripAt : min + 1e-6;
  const approachFrac = clamp((value - min) / (safeTripAt - min), 0, 1);
  const bowFrac = latched ? 1 : approachFrac * UNLATCHED_BOW_CEILING;
  const controlY = BASE_Y - bowFrac * MAX_CONTROL_OFFSET;
  const stripD = `M ${ANCHOR_L_X} ${BASE_Y} Q ${MID_X} ${controlY} ${ANCHOR_R_X} ${BASE_Y}`;
  const stripStyle = transitionStyle(transitionKind, reduced);

  const domain = Math.max(1e-6, max - min);
  const xFor = (v: number) => ANCHOR_L_X + (clamp(v, min, max) - min) / domain * (ANCHOR_R_X - ANCHOR_L_X);
  const xClear = xFor(clearAt);
  const xTrip = xFor(tripAt);
  const xValue = xFor(value);

  const labelId = `${uid}-label`;
  const descId = `${uid}-desc`;
  const liveId = `${uid}-live`;
  const valueText = `${fmt(value)}${unit}, ${latched ? "latched" : "clear"}, trips at ${fmt(tripAt)}${unit}, clears at ${fmt(clearAt)}${unit}`;
  const stateWord = latched ? "LATCHED" : "CLEAR";
  const description = latched
    ? `Latched at ${fmt(value)}${unit} — trips at ${fmt(tripAt)}${unit}, will re-arm below ${fmt(clearAt)}${unit}.`
    : `Clear at ${fmt(value)}${unit} — trips at ${fmt(tripAt)}${unit}, clears at ${fmt(clearAt)}${unit}.`;

  return (
    <div className={className}>
      <style>{`
.ns-bimetal-strip{transition-property:d}
@media (prefers-reduced-motion: reduce){
  .ns-bimetal-strip{transition-duration:140ms !important;transition-timing-function:linear !important}
}
`}</style>

      <div className="flex items-baseline justify-between gap-3">
        <span id={labelId} className="font-mono text-[11px] tracking-wide text-ns-muted">
          {label.toUpperCase()}
        </span>
        <span
          className={
            "font-mono text-[11px] tracking-wide text-foreground " +
            (latched ? "font-semibold" : "")
          }
        >
          {stateWord}
        </span>
      </div>

      <div className="mt-1 flex items-baseline gap-1.5">
        <span className="text-2xl font-semibold tabular-nums text-foreground">
          {fmt(value)}
          {unit}
        </span>
      </div>

      <div
        role="meter"
        aria-labelledby={labelId}
        aria-describedby={descId}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={clamp(value, min, max)}
        aria-valuetext={valueText}
        tabIndex={0}
        className="mt-3 rounded-md focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ns-accent"
      >
        <svg
          viewBox={`0 0 ${VIEW_W} ${VIEW_H}`}
          className="h-[150px] w-full"
          aria-hidden
          focusable="false"
        >
          {/* hysteresis band, on the strip's own x-domain */}
          <rect
            x={xClear}
            y={BAND_Y}
            width={Math.max(0, xTrip - xClear)}
            height={BAND_H}
            rx={2}
            className="fill-current text-ns-muted opacity-40"
          />
          <line
            x1={xClear}
            x2={xClear}
            y1={BAND_Y - TICK_H / 2}
            y2={BAND_Y + BAND_H + TICK_H / 2}
            className="stroke-current text-border"
            strokeWidth={1}
          />
          <line
            x1={xTrip}
            x2={xTrip}
            y1={BAND_Y - TICK_H / 2}
            y2={BAND_Y + BAND_H + TICK_H / 2}
            className="stroke-current text-border"
            strokeWidth={1}
          />
          {/* live position marker along the band */}
          <circle
            cx={xValue}
            cy={BAND_Y + BAND_H / 2}
            r={3}
            className="fill-current text-foreground"
          />

          {/* mounting posts, fixed endpoints of the strip */}
          <rect
            x={ANCHOR_L_X - 4}
            y={BASE_Y - 9}
            width={8}
            height={18}
            rx={2}
            className="fill-current text-border"
          />
          <rect
            x={ANCHOR_R_X - 4}
            y={BASE_Y - 9}
            width={8}
            height={18}
            rx={2}
            className="fill-current text-border"
          />

          {/* the strip itself — one quadratic bezier, control point is the mechanism */}
          <path
            d={stripD}
            fill="none"
            className="ns-bimetal-strip stroke-current text-foreground"
            style={stripStyle}
            strokeWidth={latched ? 3.5 : 2}
            strokeLinecap="round"
          />

          {/* contact assembly: fixed post + pad the strip's tip closes against */}
          <line
            x1={MID_X}
            x2={MID_X}
            y1={POST_TOP_Y}
            y2={CONTACT_Y}
            className="stroke-current text-border"
            strokeWidth={1.5}
          />
          <rect
            x={MID_X - PAD_W / 2}
            y={CONTACT_Y - PAD_H / 2}
            width={PAD_W}
            height={PAD_H}
            rx={1.5}
            className={
              latched
                ? "fill-current text-foreground"
                : "fill-none stroke-current text-border"
            }
            strokeWidth={latched ? 0 : 1.5}
          />
          {latched ? (
            <circle
              data-bimetal-contact-lit
              cx={MID_X}
              cy={CONTACT_Y}
              r={4}
              className="fill-current text-foreground"
            />
          ) : null}
        </svg>
      </div>

      <div className="mt-1.5 flex items-center justify-between font-mono text-[11px] text-ns-muted">
        <span>
          clears {fmt(clearAt)}
          {unit}
        </span>
        <span>
          trips {fmt(tripAt)}
          {unit}
        </span>
      </div>

      <p id={descId} className="mt-2 text-center font-mono text-[11px] text-ns-muted">
        {description}
      </p>

      <span id={liveId} role="status" aria-live="polite" className="sr-only">
        {announce}
      </span>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// MillstoneFurrowFlow — an ambient processing-section background modelled on
// a dressed millstone pair. Two sickle-furrow patterns are drawn concentric
// and share a centre but NOT a furrow count: the bedstone (static,
// underneath) is dressed with 13 furrows, the runner (rotating, on top) with
// the standard 12. Two near-equal angular frequencies beat against each
// other — that |13-12| = 1 mismatch is what produces a single crossing band
// that sweeps once around the stone per runner revolution, not 12 crossings
// drifting together (which a same-count pair would produce, reading as a
// restyled radial pattern rather than a genuine moiré). The bedstone's
// sickle curvature is also mirrored relative to the runner's, matching how a
// real bedstone is dressed as the runner's counter-pattern so the two
// furrow sets genuinely scissor rather than merely overlay.
//
// A second, independent process rides on top of the furrow field: grain
// particles spawn at the stone's eye (centre) and spiral outward, shrinking
// as they travel — coarse feed at the centre, fine meal at the rim — then
// disperse into a handful of fading dust motes instead of simply vanishing.
// A particle's own angle is coupled to 60% of the runner's angular rate, so
// its path traces a shallow spiral rather than a straight radius, visually
// tying it to the furrow pattern turning beneath it.
//
// The real runner stone turns at roughly 120 RPM (~2 rev/s); rendered here
// at 0.08 rev/s, a deliberate decoupling from the real rate for legibility
// (a viewer needs seconds, not a strobe, to track the moiré sweep) — the
// real number is documented, not animated 1:1.
// ---------------------------------------------------------------------------

type Vec3 = [number, number, number];

function parseColor(raw: string): Vec3 | null {
  const s = raw.trim();
  if (s.startsWith("#")) {
    const hex = s.slice(1);
    if (hex.length === 3) {
      const r = parseInt(hex.slice(0, 1) + hex.slice(0, 1), 16);
      const g = parseInt(hex.slice(1, 2) + hex.slice(1, 2), 16);
      const b = parseInt(hex.slice(2, 3) + hex.slice(2, 3), 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    if (hex.length >= 6) {
      const r = parseInt(hex.slice(0, 2), 16);
      const g = parseInt(hex.slice(2, 4), 16);
      const b = parseInt(hex.slice(4, 6), 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    return null;
  }
  const m = s.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
}

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// -- real millwright numbers, documented rate then a deliberately decoupled
// rendered rate (round-9 legibility rule: near/above-paint-rate mechanics
// must render slow, not 1:1) -------------------------------------------------
const REAL_RUNNER_RPM = 120; // ~2 rev/s on an operating stone mill
const RUNNER_REV_PER_SEC = 0.08; // rendered rate, documented as illustrative
const RUNNER_ANGULAR_RATE = RUNNER_REV_PER_SEC * Math.PI * 2; // rad/s

const RUNNER_FURROW_COUNT = 12; // sickle-dress furrow count, rotating layer
const BEDSTONE_FURROW_COUNT = 13; // one more than the runner — the frequency
// mismatch that turns two overlaid patterns into a genuine beating moiré
const STONE_RADIUS_RATIO = 0.48; // of min(w, h)
const EYE_RADIUS_RATIO = 0.04; // of stone radius
const SICKLE_SWEEP = (12 * Math.PI) / 180; // angular curvature per furrow
const FURROW_ALPHA_CENTER = 0.62; // deepest cut, highest local contrast
const FURROW_ALPHA_RIM = 0.24; // shallowest land, above --border's 1.1:1 floor
const BEDSTONE_ALPHA_SCALE = 0.72; // static layer sits slightly under the runner
const CURVE_STEPS = 20; // polyline samples per furrow curve

const SPAWN_INTERVAL_MS = 900; // one grain every 0.9s
const BASE_STONE_RADIUS = 240; // reference radius the real numbers were measured against
const BASE_TRAVEL_MS = 4500; // ~4.5s eye-to-rim at the reference radius (~14px/s outward)
const MIN_TRAVEL_MS = 1500;
const MAX_TRAVEL_MS = 9000;
const EASE_EXP = 1.15; // accelerating outward travel (centrifugal build-up)
const SIZE_EYE_PX = 5;
const SIZE_RIM_PX = 1;
const ANGULAR_COUPLE = 0.6; // fraction of the runner's angular delta a grain inherits
const DUST_FADE_MS = 800;
const DUST_SIZE_PX = 0.5;

interface Grain {
  spawnMs: number;
  spawnAngle: number;
  spawnRunnerAngle: number;
}

interface Dust {
  x: number;
  y: number;
  spawnMs: number;
}

export interface MillstoneFurrowFlowProps {
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function MillstoneFurrowFlow({ className = "" }: MillstoneFurrowFlowProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const rand = mulberry32(0x6d1157a3);

    // -- token-derived ink, re-derived on theme class change, no paint before
    // the first read ----------------------------------------------------------
    let muted: Vec3 = [143, 143, 143];
    let fg: Vec3 = [237, 237, 237];
    const derive = () => {
      const cs = getComputedStyle(document.documentElement);
      muted = parseColor(cs.getPropertyValue("--ns-muted")) ?? muted;
      fg = parseColor(cs.getPropertyValue("--foreground")) ?? fg;
    };
    derive();

    let w = 0;
    let h = 0;
    let dpr = 1;
    let cx = 0;
    let cy = 0;
    let stoneR = 0;
    let eyeR = 0;
    let travelMs = BASE_TRAVEL_MS;
    let bedPath: Path2D = new Path2D();
    let runnerPath: Path2D = new Path2D();
    let gradient: CanvasGradient | null = null;

    let raf = 0;
    let visible = true;

    let grains: Grain[] = [];
    let dust: Dust[] = [];
    let nextSpawnMs = 0;

    // -- a furrow is a quadratic bezier in polar space: radius eases linearly
    // eye->rim, angle curves through a midpoint offset by half the sickle
    // sweep before reaching its endpoint. sweepSign flips the curvature so
    // the bedstone pattern mirrors the runner's, matching a real dress. -----
    const buildFurrowPath = (count: number, sweepSign: 1 | -1): Path2D => {
      const path = new Path2D();
      const sweep = SICKLE_SWEEP * sweepSign;
      for (let f = 0; f < count; f++) {
        const a0 = (f / count) * Math.PI * 2;
        const aMid = a0 + sweep * 0.5;
        const aEnd = a0 + sweep;
        for (let i = 0; i <= CURVE_STEPS; i++) {
          const t = i / CURVE_STEPS;
          const ang = (1 - t) * (1 - t) * a0 + 2 * (1 - t) * t * aMid + t * t * aEnd;
          const r = eyeR + (stoneR - eyeR) * t;
          const px = cx + Math.cos(ang) * r;
          const py = cy + Math.sin(ang) * r;
          if (i === 0) path.moveTo(px, py);
          else path.lineTo(px, py);
        }
      }
      return path;
    };

    const buildGradient = (): CanvasGradient => {
      const g = ctx.createRadialGradient(cx, cy, eyeR, cx, cy, stoneR);
      g.addColorStop(0, `rgba(${muted[0]},${muted[1]},${muted[2]},${FURROW_ALPHA_CENTER})`);
      g.addColorStop(1, `rgba(${muted[0]},${muted[1]},${muted[2]},${FURROW_ALPHA_RIM})`);
      return g;
    };

    const spawnDust = (x: number, y: number, nowMs: number) => {
      const count = 3 + Math.floor(rand() * 4); // 3..6
      for (let i = 0; i < count; i++) {
        const jitter = 3 + rand() * 3;
        const jang = rand() * Math.PI * 2;
        dust.push({
          x: x + Math.cos(jang) * jitter,
          y: y + Math.sin(jang) * jitter,
          spawnMs: nowMs,
        });
      }
    };

    const drawGrain = (x: number, y: number, sizePx: number, alpha: number) => {
      ctx.beginPath();
      ctx.arc(x, y, Math.max(0.25, sizePx / 2), 0, Math.PI * 2);
      ctx.fillStyle = `rgba(${fg[0]},${fg[1]},${fg[2]},${alpha.toFixed(3)})`;
      ctx.fill();
    };

    const drawFurrows = (runnerAngle: number) => {
      if (!gradient) return;
      ctx.lineWidth = 1;
      ctx.strokeStyle = gradient;
      ctx.globalAlpha = BEDSTONE_ALPHA_SCALE;
      ctx.stroke(bedPath); // static bedstone, underneath
      ctx.globalAlpha = 1;
      // rotating runner, on top — the 12-vs-13 frequency mismatch against the
      // static bedstone is what produces the moiré band sweeping the stone
      ctx.save();
      ctx.translate(cx, cy);
      ctx.rotate(runnerAngle);
      ctx.translate(-cx, -cy);
      ctx.stroke(runnerPath);
      ctx.restore();
    };

    const render = (nowMs: number, runnerAngle: number) => {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      if (w <= 0 || h <= 0 || stoneR <= 0) return;

      drawFurrows(runnerAngle);

      for (const g of grains) {
        const elapsed = nowMs - g.spawnMs;
        const progress = Math.min(1, Math.max(0, elapsed / travelMs));
        const eased = Math.pow(progress, EASE_EXP);
        const r = eyeR + (stoneR - eyeR) * eased;
        const size = SIZE_EYE_PX + (SIZE_RIM_PX - SIZE_EYE_PX) * progress;
        const angle = g.spawnAngle + ANGULAR_COUPLE * (runnerAngle - g.spawnRunnerAngle);
        const x = cx + Math.cos(angle) * r;
        const y = cy + Math.sin(angle) * r;
        drawGrain(x, y, size, 1);
      }

      for (const d of dust) {
        const age = nowMs - d.spawnMs;
        const alpha = Math.max(0, 1 - age / DUST_FADE_MS);
        if (alpha <= 0) continue;
        drawGrain(d.x, d.y, DUST_SIZE_PX, alpha * 0.9);
      }
    };

    const step = (nowMs: number) => {
      // spawn grain feed — if the field was off-screen and paused long
      // enough that many spawns were missed, fast-forward the schedule
      // instead of catching up a runaway burst in one frame
      if (nowMs - nextSpawnMs > SPAWN_INTERVAL_MS * 4) {
        nextSpawnMs = nowMs - SPAWN_INTERVAL_MS;
      }
      while (nowMs >= nextSpawnMs) {
        grains.push({
          spawnMs: nextSpawnMs,
          spawnAngle: rand() * Math.PI * 2,
          spawnRunnerAngle: (nextSpawnMs / 1000) * RUNNER_ANGULAR_RATE,
        });
        nextSpawnMs += SPAWN_INTERVAL_MS;
      }
      // mature grains -> dust at the rim
      const kept: Grain[] = [];
      for (const g of grains) {
        const elapsed = nowMs - g.spawnMs;
        if (elapsed >= travelMs) {
          const runnerAngle = (nowMs / 1000) * RUNNER_ANGULAR_RATE;
          const angle = g.spawnAngle + ANGULAR_COUPLE * (runnerAngle - g.spawnRunnerAngle);
          const x = cx + Math.cos(angle) * stoneR;
          const y = cy + Math.sin(angle) * stoneR;
          spawnDust(x, y, nowMs);
        } else {
          kept.push(g);
        }
      }
      grains = kept;
      // cull expired dust
      dust = dust.filter((d) => nowMs - d.spawnMs < DUST_FADE_MS);
    };

    // -- absolute rAF timestamps throughout (never elapsed-since-mount): a
    // pause/resume via IntersectionObserver never has to rewind or offset a
    // clock, so grain spawnMs values stay valid and progress never goes
    // negative across a visibility gap ----------------------------------------
    const loop = (nowMs: number) => {
      if (!visible) {
        raf = 0;
        return;
      }
      step(nowMs);
      const runnerAngle = (nowMs / 1000) * RUNNER_ANGULAR_RATE;
      render(nowMs, runnerAngle);
      raf = requestAnimationFrame(loop);
    };

    const drawReducedFrame = () => {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      if (w <= 0 || h <= 0 || stoneR <= 0) return;
      // deliberately chosen NON-t0 most-structured frame: runner offset from
      // the bedstone (visible cross-hatch, not full alignment), one grain
      // mid-grind, one dust puff mid-fade — the whole process visible at once
      const runnerAngle = (18 * Math.PI) / 180;
      drawFurrows(runnerAngle);
      const progress = 0.6;
      const eased = Math.pow(progress, EASE_EXP);
      const r = eyeR + (stoneR - eyeR) * eased;
      const size = SIZE_EYE_PX + (SIZE_RIM_PX - SIZE_EYE_PX) * progress;
      const angle = Math.PI * 0.35;
      drawGrain(cx + Math.cos(angle) * r, cy + Math.sin(angle) * r, size, 1);
      const dustAngle = Math.PI * 1.2;
      drawGrain(cx + Math.cos(dustAngle) * stoneR, cy + Math.sin(dustAngle) * stoneR, DUST_SIZE_PX, 0.45);
    };

    const resize = () => {
      const rect = root.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      dpr = Math.min(1.5, window.devicePixelRatio || 1);
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
      cx = w / 2;
      cy = h / 2;
      stoneR = Math.min(w, h) * STONE_RADIUS_RATIO;
      eyeR = stoneR * EYE_RADIUS_RATIO;
      // duration scales with stone radius (not a fixed px/s divisor) so a
      // card-sized instance still reads a full ~4.5s transit at the 240px
      // reference radius rather than a formula-derived crawl
      travelMs = Math.min(
        MAX_TRAVEL_MS,
        Math.max(MIN_TRAVEL_MS, BASE_TRAVEL_MS * (stoneR / BASE_STONE_RADIUS || 1))
      );
      bedPath = buildFurrowPath(BEDSTONE_FURROW_COUNT, -1);
      runnerPath = buildFurrowPath(RUNNER_FURROW_COUNT, 1);
      gradient = buildGradient();
      if (reduced) {
        drawReducedFrame();
      } else if (raf === 0 && visible) {
        render(performance.now(), 0);
      }
    };

    resize();

    if (!reduced) {
      raf = requestAnimationFrame(loop);
    }

    const ro = new ResizeObserver(resize);
    ro.observe(root);

    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (!reduced && visible && raf === 0) {
        raf = requestAnimationFrame(loop);
      }
    });
    io.observe(root);

    const mo = new MutationObserver(() => {
      derive();
      gradient = buildGradient();
      if (reduced) drawReducedFrame();
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    return () => {
      cancelAnimationFrame(raf);
      raf = 0;
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
    };
  }, []);

  return (
    <div ref={rootRef} className={`relative overflow-hidden bg-background ${className}`}>
      <canvas ref={canvasRef} aria-hidden="true" className="pointer-events-none absolute inset-0 h-full w-full" />
    </div>
  );
}

"use client";

import { useEffect, useRef, type ReactNode } from "react";

// ScissorReach — a minimap whose viewport rectangle is physically wired to
// the real viewport by a live SVG pantograph. The minimap is a scaled clone
// of the same content (CSS transform: scale, never re-measured — width and
// height ratios are derived once from the fixed contentWidth/contentHeight
// props). Between the minimap's viewport rect and the real viewport's
// top-left corner, two mirrored 2-bar elbow arms are solved every frame by
// trivial IK from the two live anchor points; only the elbow (joint)
// springs — the anchors themselves track their DOM elements exactly, never
// lagging, so the linkage always reads as physically attached rather than
// floating. Direct-DOM rAF, refs only on the hot path, sleeps when the
// spring settles and dragging has stopped.

type Vec = { x: number; y: number };

const BOW = 26; // px — arm reach exceeds half the anchor span by this much
const SPRING_K = 200; // s^-2
const SPRING_ZETA = 0.8; // slightly underdamped -> a hair of catch-up snap
const SPRING_C = 2 * SPRING_ZETA * Math.sqrt(SPRING_K);
const SETTLE_EPS = 0.15; // px
const SETTLE_V_EPS = 2; // px/s
const IDLE_MS = 700; // idle relax delay before the linkage fades to 0.3
const STEP_X = 32; // px per ArrowLeft/Right, content space

function clamp(v: number, lo: number, hi: number) {
  return Math.min(hi, Math.max(lo, v));
}

// Two equal-length links whose combined reach is fixed at (d/2 + bow) for
// the current anchor distance d — always solvable (no negative sqrt), and
// the bow shrinks as a fraction of d as the anchors pull apart, which reads
// as "the linkage extends and flattens" rather than a floppy fixed arm.
function twoBarElbow(a: Vec, b: Vec, bow: number) {
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const d = Math.max(1e-4, Math.hypot(dx, dy));
  const link = d / 2 + bow;
  const h = Math.sqrt(Math.max(0, link * link - (d / 2) * (d / 2)));
  const mx = (a.x + b.x) / 2;
  const my = (a.y + b.y) / 2;
  const nx = -dy / d;
  const ny = dx / d;
  return {
    up: { x: mx + nx * h, y: my + ny * h },
    down: { x: mx - nx * h, y: my - ny * h },
  };
}

export function ScissorReach({
  children,
  contentWidth,
  contentHeight,
  minimapWidth = 140,
  minimapHeight = 220,
  viewportHeight = 340,
  rowHeight = 16,
  unitLabel = "rows",
  className = "",
  "aria-label": ariaLabel = "Document position",
}: {
  /** the full content — size it so it renders at exactly contentWidth x contentHeight */
  children: ReactNode;
  /** logical content extent in px that `children` occupies */
  contentWidth: number;
  /** logical content height in px that `children` occupies */
  contentHeight: number;
  /** minimap panel size in px — independent of content aspect ratio, like a scrollbar rail */
  minimapWidth?: number;
  /** minimap panel height in px */
  minimapHeight?: number;
  /** fixed viewport pane height in px */
  viewportHeight?: number;
  /** row height in px — used only to phrase the aria-valuetext readout */
  rowHeight?: number;
  /** unit noun appended to the aria-valuetext readout, e.g. "rows" */
  unitLabel?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** accessible name for the minimap. Default "Document position". */
  "aria-label"?: string;
}) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const trackRef = useRef<HTMLDivElement | null>(null);
  const handleRef = useRef<HTMLDivElement | null>(null);
  const viewportRef = useRef<HTMLDivElement | null>(null);
  const groupRef = useRef<SVGGElement | null>(null);
  const lineRefs = useRef<(SVGLineElement | null)[]>([]);
  const circleRefs = useRef<(SVGCircleElement | null)[]>([]);

  const totalRows = Math.max(1, Math.round(contentHeight / rowHeight));
  const initialEndRow = Math.min(totalRows, Math.ceil(viewportHeight / rowHeight));

  useEffect(() => {
    const container = containerRef.current;
    const track = trackRef.current;
    const handle = handleRef.current;
    const viewport = viewportRef.current;
    const group = groupRef.current;
    if (!container || !track || !handle || !viewport || !group) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    const scaleX = minimapWidth / contentWidth;
    const scaleY = minimapHeight / contentHeight;

    let vpW = viewport.clientWidth;
    let vpH = viewport.clientHeight;

    let dragging = false;
    let dragStartX = 0;
    let dragStartY = 0;
    let dragScrollLeft = 0;
    let dragScrollTop = 0;

    let upPos: Vec = { x: 0, y: 0 };
    let upVel: Vec = { x: 0, y: 0 };
    let downPos: Vec = { x: 0, y: 0 };
    let downVel: Vec = { x: 0, y: 0 };
    let primed = false;

    let raf = 0;
    let last = 0;
    let idleTimer: ReturnType<typeof setTimeout> | null = null;

    const maxTop = () => Math.max(0, contentHeight - vpH);
    const maxLeft = () => Math.max(0, contentWidth - vpW);

    const markActive = () => {
      group.style.opacity = "1";
      if (idleTimer) clearTimeout(idleTimer);
      idleTimer = setTimeout(() => {
        group.style.opacity = "0.3";
      }, IDLE_MS);
    };

    // returns true once settled (always true immediately under reduced motion)
    const springTo = (pos: Vec, vel: Vec, target: Vec, dt: number) => {
      if (reduced) {
        pos.x = target.x;
        pos.y = target.y;
        vel.x = 0;
        vel.y = 0;
        return true;
      }
      vel.x += (SPRING_K * (target.x - pos.x) - SPRING_C * vel.x) * dt;
      vel.y += (SPRING_K * (target.y - pos.y) - SPRING_C * vel.y) * dt;
      pos.x += vel.x * dt;
      pos.y += vel.y * dt;
      const dErr = Math.hypot(target.x - pos.x, target.y - pos.y);
      const vErr = Math.hypot(vel.x, vel.y);
      return dErr < SETTLE_EPS && vErr < SETTLE_V_EPS;
    };

    const frame = (now: number) => {
      raf = 0;
      const dt = last ? clamp((now - last) / 1000, 0.001, 1 / 30) : 1 / 60;
      last = now;

      const scrollTop = clamp(viewport.scrollTop, 0, maxTop());
      const scrollLeft = clamp(viewport.scrollLeft, 0, maxLeft());

      const rectW = Math.min(minimapWidth, Math.max(4, vpW * scaleX));
      const rectH = Math.min(minimapHeight, Math.max(4, vpH * scaleY));
      const rectLeft = clamp(scrollLeft * scaleX, 0, Math.max(0, minimapWidth - rectW));
      const rectTop = clamp(scrollTop * scaleY, 0, Math.max(0, minimapHeight - rectH));

      handle.style.left = `${rectLeft}px`;
      handle.style.top = `${rectTop}px`;
      handle.style.width = `${rectW}px`;
      handle.style.height = `${rectH}px`;

      const trackBox = track.getBoundingClientRect();
      const containerBox = container.getBoundingClientRect();
      const viewportBox = viewport.getBoundingClientRect();
      const originX = trackBox.left - containerBox.left;
      const originY = trackBox.top - containerBox.top;

      // A: the rect's near corner (moves with the drag). B: the real
      // viewport's fixed corner. Neither is ever sprung — only the elbow
      // joints between them are, so the linkage always looks attached.
      const a: Vec = { x: originX + rectLeft + rectW, y: originY + rectTop };
      const b: Vec = { x: viewportBox.left - containerBox.left, y: viewportBox.top - containerBox.top };

      const target = twoBarElbow(a, b, BOW);
      if (!primed) {
        upPos = { ...target.up };
        downPos = { ...target.down };
        primed = true;
      }
      const settledUp = springTo(upPos, upVel, target.up, dt);
      const settledDown = springTo(downPos, downVel, target.down, dt);

      const segs = lineRefs.current;
      const write = (el: SVGLineElement | null | undefined, p1: Vec, p2: Vec) => {
        if (!el) return;
        el.setAttribute("x1", String(p1.x));
        el.setAttribute("y1", String(p1.y));
        el.setAttribute("x2", String(p2.x));
        el.setAttribute("y2", String(p2.y));
      };
      write(segs[0], a, upPos);
      write(segs[1], upPos, b);
      write(segs[2], a, downPos);
      write(segs[3], downPos, b);

      const pts = [a, upPos, downPos, b];
      circleRefs.current.forEach((c, i) => {
        const p = pts[i];
        if (c && p) {
          c.setAttribute("cx", String(p.x));
          c.setAttribute("cy", String(p.y));
        }
      });

      const startRow = Math.floor(scrollTop / rowHeight) + 1;
      const endRow = Math.min(totalRows, Math.ceil((scrollTop + vpH) / rowHeight));
      handle.setAttribute("aria-valuenow", String(startRow));
      handle.setAttribute(
        "aria-valuetext",
        `viewing ${unitLabel} ${startRow}-${endRow} of ${totalRows}`
      );

      const active = dragging || !settledUp || !settledDown;
      if (active) raf = requestAnimationFrame(frame);
    };

    const wake = () => {
      markActive();
      if (!raf) {
        last = 0;
        raf = requestAnimationFrame(frame);
      }
    };

    const onPointerDown = (e: PointerEvent) => {
      e.preventDefault();
      track.setPointerCapture(e.pointerId);
      handle.focus({ preventScroll: true });
      dragging = true;
      dragStartX = e.clientX;
      dragStartY = e.clientY;
      dragScrollLeft = viewport.scrollLeft;
      dragScrollTop = viewport.scrollTop;
      wake();
    };
    const onPointerMove = (e: PointerEvent) => {
      if (!dragging) return;
      const dxContent = (e.clientX - dragStartX) / scaleX;
      const dyContent = (e.clientY - dragStartY) / scaleY;
      viewport.scrollLeft = clamp(dragScrollLeft + dxContent, 0, maxLeft());
      viewport.scrollTop = clamp(dragScrollTop + dyContent, 0, maxTop());
      wake();
    };
    const endDrag = (e: PointerEvent) => {
      if (!dragging) return;
      dragging = false;
      try {
        track.releasePointerCapture(e.pointerId);
      } catch {
        // synthetic pointerId during autoplay — nothing to release
      }
      wake();
    };

    const onKeyDown = (e: KeyboardEvent) => {
      let handled = true;
      switch (e.key) {
        case "ArrowDown":
          viewport.scrollTop = clamp(viewport.scrollTop + rowHeight, 0, maxTop());
          break;
        case "ArrowUp":
          viewport.scrollTop = clamp(viewport.scrollTop - rowHeight, 0, maxTop());
          break;
        case "ArrowRight":
          viewport.scrollLeft = clamp(viewport.scrollLeft + STEP_X, 0, maxLeft());
          break;
        case "ArrowLeft":
          viewport.scrollLeft = clamp(viewport.scrollLeft - STEP_X, 0, maxLeft());
          break;
        case "PageDown":
          viewport.scrollTop = clamp(viewport.scrollTop + vpH * 0.9, 0, maxTop());
          break;
        case "PageUp":
          viewport.scrollTop = clamp(viewport.scrollTop - vpH * 0.9, 0, maxTop());
          break;
        case "Home":
          viewport.scrollTop = 0;
          break;
        case "End":
          viewport.scrollTop = maxTop();
          break;
        default:
          handled = false;
      }
      if (handled) {
        e.preventDefault();
        wake();
      }
    };

    const onScroll = () => wake();

    const ro = new ResizeObserver(() => {
      vpW = viewport.clientWidth;
      vpH = viewport.clientHeight;
      wake();
    });
    ro.observe(viewport);

    track.addEventListener("pointerdown", onPointerDown);
    track.addEventListener("pointermove", onPointerMove);
    track.addEventListener("pointerup", endDrag);
    track.addEventListener("pointercancel", endDrag);
    handle.addEventListener("keydown", onKeyDown);
    viewport.addEventListener("scroll", onScroll, { passive: true });

    wake();

    return () => {
      cancelAnimationFrame(raf);
      if (idleTimer) clearTimeout(idleTimer);
      ro.disconnect();
      track.removeEventListener("pointerdown", onPointerDown);
      track.removeEventListener("pointermove", onPointerMove);
      track.removeEventListener("pointerup", endDrag);
      track.removeEventListener("pointercancel", endDrag);
      handle.removeEventListener("keydown", onKeyDown);
      viewport.removeEventListener("scroll", onScroll);
    };
  }, [contentWidth, contentHeight, minimapWidth, minimapHeight, viewportHeight, rowHeight, unitLabel, totalRows]);

  return (
    <div ref={containerRef} className={`relative flex items-start gap-24 ${className}`}>
      <div
        ref={trackRef}
        data-scissor-track
        className="relative shrink-0 touch-none select-none overflow-hidden rounded-sm border border-border bg-background"
        style={{ width: minimapWidth, height: minimapHeight }}
      >
        <div
          aria-hidden
          className="pointer-events-none absolute left-0 top-0 origin-top-left opacity-70"
          style={{
            width: contentWidth,
            height: contentHeight,
            transform: `scale(${minimapWidth / contentWidth}, ${minimapHeight / contentHeight})`,
          }}
        >
          {children}
        </div>
        <div
          ref={handleRef}
          role="slider"
          tabIndex={0}
          aria-label={ariaLabel}
          aria-orientation="vertical"
          aria-valuemin={1}
          aria-valuemax={totalRows}
          aria-valuenow={1}
          aria-valuetext={`viewing ${unitLabel} 1-${initialEndRow} of ${totalRows}`}
          className="absolute cursor-grab rounded-[3px] border-2 border-foreground/60 bg-foreground/[0.06] outline-none transition-colors hover:border-ns-accent focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background active:cursor-grabbing"
        />
      </div>

      <svg aria-hidden className="pointer-events-none absolute inset-0 h-full w-full overflow-visible">
        <g ref={groupRef} className="text-ns-muted transition-opacity duration-300 ease-out" style={{ opacity: 1 }}>
          {[0, 1, 2, 3].map((i) => (
            <line
              key={i}
              ref={(el) => {
                lineRefs.current[i] = el;
              }}
              stroke="currentColor"
              strokeWidth={1}
            />
          ))}
          {[0, 1, 2, 3].map((i) => (
            <circle
              key={i}
              ref={(el) => {
                circleRefs.current[i] = el;
              }}
              r={3}
              fill="currentColor"
            />
          ))}
        </g>
      </svg>

      <div
        ref={viewportRef}
        className="relative min-w-0 flex-1 overflow-auto rounded-sm border border-border bg-background"
        style={{ height: viewportHeight }}
      >
        <div style={{ width: contentWidth, height: contentHeight }}>{children}</div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// MudflowLeveeBuild — an ambient activity track where the track itself is
// self-built by the traffic flowing through it, rather than a pre-existing
// channel being filled. Modelled on lateral levee formation in debris flows
// (mudflows with a coarse clast fraction — cobbles suspended in a fine
// matrix): shear at a flow's margins is highest where the edges lag the
// faster center, and that shear preferentially strands the coarsest
// material at the margins. Over many surges those margins build into two
// low ridges that confine and channelize everything behind them, narrowing
// the channel — until a surge overtops one bank, breaching it, and the
// active path avulses sideways, leaving the old levee pair behind as a
// static scar.
//
// Two lanes (top half of the track, bottom half) each hold their own pair
// of Float32Array levee-height buckets (one bucket per horizontal position,
// bucket width derived from the container's smaller dimension so the ridge
// reads at card scale). Only one lane is "active" (carries live surges) at
// a time; the other sits empty until a breach hands it the channel. A surge
// spawns every ~1.6-3.4s (mean 2.4s), sweeps left to right over 1.8s, and
// deposits growth onto BOTH margins of whichever bucket it currently
// occupies roughly every 90ms — so levee height at any point is a literal
// record of how many surges have passed there and how coarse each was, not
// a uniform ramp. Once a margin bucket's height crosses 78% of the lane's
// half-height, the flow breaches there: that levee's height collapses
// toward a residual scar value over 300ms, the active lane freezes in
// place (no further deposits, ever), and the OTHER lane resets to a flat
// channel and takes over as active, starting its own pair from scratch.
// The abandoned lane keeps rendering its frozen ridge (and its gap)
// indefinitely as a visible scar.
//
// Levee ridges are drawn as a granulated cluster of small markers rather
// than a filled bar: marker count per bucket is derived directly from that
// bucket's stored height (height / DOT_PITCH), and each marker's jittered
// position is a deterministic hash of its (lane, margin, bucket, index) —
// so growing the height only ever appends new markers at the outer end,
// every existing marker holds its exact pixel position frame to frame, and
// nothing needs to be stored beyond the height arrays themselves (bounded
// memory, unbounded loop). The active lane's flow band is a horizontally
// tapered translucent fill following the current surge position(s),
// confined between that bucket's live margin heights, so the band visibly
// narrows as the levees grow beneath it.
//
// Legibility: the one thing to follow is levee height climbing at the
// margins (never the channel "filling") until a breach visibly snaps the
// active path sideways — a rare (~9-13s), unmistakably discrete event
// distinct from the continuous narrowing around it.
// ---------------------------------------------------------------------------

type Vec3 = [number, number, number];

function parseColor(raw: string): Vec3 | null {
  const s = raw.trim();
  if (s.startsWith("#")) {
    const hex = s.slice(1);
    if (hex.length === 3) {
      const r = parseInt(hex.slice(0, 1) + hex.slice(0, 1), 16);
      const g = parseInt(hex.slice(1, 2) + hex.slice(1, 2), 16);
      const b = parseInt(hex.slice(2, 3) + hex.slice(2, 3), 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    if (hex.length >= 6) {
      const r = parseInt(hex.slice(0, 2), 16);
      const g = parseInt(hex.slice(2, 4), 16);
      const b = parseInt(hex.slice(4, 6), 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    return null;
  }
  const m = s.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
}

// deterministic per-cell hash — used for marker jitter (must stay fixed
// across frames) and for the flow band's turbulence texture.
function hash01(x: number, y: number): number {
  const n = Math.sin(x * 127.1 + y * 311.7) * 43758.5453123;
  return n - Math.floor(n);
}

function easeOutCubic(t: number): number {
  const u = 1 - t;
  return 1 - u * u * u;
}

const SURGE_TRAVERSE_MS = 1800;
const SURGE_MIN_GAP = 1600;
const SURGE_MAX_GAP = 3400;
const MARKER_INTERVAL_MS = 90;
const GROWTH_MIN = 0.4;
const GROWTH_MAX = 0.9;
const COARSE_MIN = 0.6;
const COARSE_MAX = 1.4;
const BREACH_THRESHOLD_FRAC = 0.78;
const BREACH_MS = 300;
const BREACH_RESIDUAL = 0.12; // fraction of pre-breach height left as scar gap
const TAPER_BUCKETS = 6; // how many buckets either side of a surge the flow band tapers over
const MAX_SURGES = 4;

interface LaneState {
  top: Float32Array;
  bottom: Float32Array;
  active: boolean;
}

interface Surge {
  lane: number;
  start: number;
  lastDeposit: number;
  coarse: number;
}

interface BreachAnim {
  lane: number;
  bucket: number;
  margin: "top" | "bottom";
  start: number;
  from: number;
}

export interface MudflowLeveeBuildProps {
  /** accessible label describing the ambient visualisation */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function MudflowLeveeBuild({
  label = "Channel activity",
  className = "",
}: MudflowLeveeBuildProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    // -- token-derived ink: read at mount, re-derived on theme class change --
    let fg: Vec3 = [237, 237, 237];
    let bd: Vec3 = [55, 55, 55];
    const derive = () => {
      const cs = getComputedStyle(document.documentElement);
      fg = parseColor(cs.getPropertyValue("--foreground")) ?? fg;
      bd = parseColor(cs.getPropertyValue("--border")) ?? bd;
    };
    derive(); // no paint happens before this

    let disposed = false;
    let visible = true;
    let raf = 0;

    let w = 0;
    let h = 0;
    let dpr = 1;
    let numBuckets = 32;
    let bucketPxWidth = 8;
    let laneH = 0;
    let laneGap = 2;
    let halfLane = 1;
    let dotPitch = 3;

    const lanes: LaneState[] = [
      { top: new Float32Array(0), bottom: new Float32Array(0), active: true },
      { top: new Float32Array(0), bottom: new Float32Array(0), active: false },
    ];
    let activeLane = 0;
    let surges: Surge[] = [];
    let nextSpawnAt = 0;
    let breachAnim: BreachAnim | null = null;

    const coarseRand = () => COARSE_MIN + Math.random() * (COARSE_MAX - COARSE_MIN);
    const spawnGap = () => {
      const t = (Math.random() + Math.random()) / 2; // bias toward the mean
      return SURGE_MIN_GAP + t * (SURGE_MAX_GAP - SURGE_MIN_GAP);
    };

    const laneY0 = (lane: number) => (lane === 0 ? 0 : laneH + laneGap);
    const bucketX = (b: number) => b * bucketPxWidth;

    const triggerBreach = (now: number, lane: number, bucket: number, margin: "top" | "bottom") => {
      const arr = lanes[lane][margin];
      breachAnim = { lane, bucket, margin, start: now, from: arr[bucket] ?? 0 };
      lanes[lane].active = false;
      const nextLane = 1 - lane;
      const nl = lanes[nextLane];
      nl.top.fill(0);
      nl.bottom.fill(0);
      nl.active = true;
      activeLane = nextLane;
      surges = [{ lane: nextLane, start: now, lastDeposit: now, coarse: coarseRand() }];
      nextSpawnAt = now + spawnGap();
    };

    const warmStart = (now: number) => {
      // never a fresh flat channel at t0 — pre-build an asymmetric ridge as
      // if several surges already passed, and put one surge already
      // partway across the track.
      const lane = lanes[0];
      for (let b = 0; b < numBuckets; b++) {
        lane.top[b] = (0.1 + 0.24 * hash01(b, 11)) * halfLane;
        lane.bottom[b] = (0.05 + 0.16 * hash01(b, 29)) * halfLane;
      }
      lane.active = true;
      lanes[1].active = false;
      activeLane = 0;
      surges = [
        { lane: 0, start: now - SURGE_TRAVERSE_MS * 0.45, lastDeposit: now, coarse: coarseRand() },
      ];
      nextSpawnAt = now + spawnGap();
      breachAnim = null;
    };

    const buildReducedFrame = () => {
      // frozen "immediately after a breach" frame: an abandoned lane with a
      // visible gap sitting beside a fresh, partially-built active lane.
      const old = lanes[0];
      const fresh = lanes[1];
      for (let b = 0; b < numBuckets; b++) {
        old.top[b] = (0.4 + 0.34 * hash01(b, 3)) * halfLane;
        old.bottom[b] = (0.32 + 0.3 * hash01(b, 7)) * halfLane;
      }
      const gapB = Math.floor(numBuckets * 0.6);
      for (let d = -1; d <= 1; d++) {
        const bb = gapB + d;
        if (bb >= 0 && bb < numBuckets) old.top[bb] = (old.top[bb] ?? 0) * BREACH_RESIDUAL;
      }
      old.active = false;
      for (let b = 0; b < numBuckets; b++) {
        fresh.top[b] = (0.05 + 0.14 * hash01(b, 41)) * halfLane;
        fresh.bottom[b] = (0.04 + 0.11 * hash01(b, 53)) * halfLane;
      }
      fresh.active = true;
      activeLane = 1;
      surges = [];
      breachAnim = null;
    };

    const deposit = (now: number) => {
      if (breachAnim) return;
      for (let i = surges.length - 1; i >= 0; i--) {
        const s = surges[i];
        if (!s) continue;
        const progress = (now - s.start) / SURGE_TRAVERSE_MS;
        if (progress >= 1) {
          surges.splice(i, 1);
          continue;
        }
        if (progress < 0) continue;
        if (now - s.lastDeposit < MARKER_INTERVAL_MS) continue;
        s.lastDeposit = now;
        const lane = lanes[s.lane];
        if (!lane.active) continue;
        const bucket = Math.max(0, Math.min(numBuckets - 1, Math.floor(progress * numBuckets)));
        const growTop = (GROWTH_MIN + Math.random() * (GROWTH_MAX - GROWTH_MIN)) * s.coarse;
        const growBottom = (GROWTH_MIN + Math.random() * (GROWTH_MAX - GROWTH_MIN)) * s.coarse;
        lane.top[bucket] = Math.min(halfLane, (lane.top[bucket] ?? 0) + growTop);
        lane.bottom[bucket] = Math.min(halfLane, (lane.bottom[bucket] ?? 0) + growBottom);
        const threshold = BREACH_THRESHOLD_FRAC * halfLane;
        if (!breachAnim) {
          if ((lane.top[bucket] ?? 0) >= threshold) {
            triggerBreach(now, s.lane, bucket, "top");
            return;
          }
          if ((lane.bottom[bucket] ?? 0) >= threshold) {
            triggerBreach(now, s.lane, bucket, "bottom");
            return;
          }
        }
      }
      if (!breachAnim && now >= nextSpawnAt) {
        surges.push({ lane: activeLane, start: now, lastDeposit: now, coarse: coarseRand() });
        if (surges.length > MAX_SURGES) surges.shift();
        nextSpawnAt = now + spawnGap();
      }
    };

    const resolveBreachAnim = (now: number) => {
      if (!breachAnim) return;
      const p = Math.min(1, (now - breachAnim.start) / BREACH_MS);
      const eased = easeOutCubic(p);
      const target = breachAnim.from * BREACH_RESIDUAL;
      const val = breachAnim.from + (target - breachAnim.from) * eased;
      const lane = lanes[breachAnim.lane];
      lane[breachAnim.margin][breachAnim.bucket] = val;
      // widen the visible gap slightly into the immediate neighbours
      for (const d of [-1, 1]) {
        const bb = breachAnim.bucket + d;
        if (bb < 0 || bb >= numBuckets) continue;
        const arr = lane[breachAnim.margin];
        const base = arr[bb] ?? 0;
        arr[bb] = base - (base - base * BREACH_RESIDUAL) * eased * 0.5;
      }
      if (p >= 1) breachAnim = null;
    };

    const drawMargin = (lane: LaneState, laneTop: number, l: number, margin: "top" | "bottom") => {
      const arr = lane[margin];
      for (let b = 0; b < numBuckets; b++) {
        const height = arr[b] ?? 0;
        if (height <= 0.5) continue;
        const count = Math.max(1, Math.ceil(height / dotPitch));
        const x = bucketX(b) + bucketPxWidth / 2;
        for (let i = 0; i < count; i++) {
          const dist = Math.min(height, i * dotPitch + dotPitch * 0.4);
          const jx = (hash01(b * 7 + i * 3 + l * 131 + (margin === "top" ? 1 : 2), 5) - 0.5) * bucketPxWidth * 0.7;
          const size = 2 + hash01(b * 3 + l * 17, i + (margin === "top" ? 31 : 59)) * 1.1;
          const y = margin === "top" ? laneTop + dist : laneTop + laneH - dist;
          ctx.fillRect(x + jx - size / 2, y - size / 2, size, size);
        }
      }
    };

    const drawFlowBand = (lane: LaneState, laneTop: number, l: number, now: number) => {
      for (let b = 0; b < numBuckets; b++) {
        let alpha = 0;
        for (const s of surges) {
          if (s.lane !== l) continue;
          const progress = (now - s.start) / SURGE_TRAVERSE_MS;
          if (progress < 0 || progress > 1) continue;
          const sx = progress * numBuckets;
          const d = Math.abs(b - sx);
          const a = Math.max(0, 1 - d / TAPER_BUCKETS);
          if (a > alpha) alpha = a;
        }
        if (alpha <= 0.02) continue;
        const yTop = laneTop + (lane.top[b] ?? 0);
        const yBot = laneTop + laneH - (lane.bottom[b] ?? 0);
        if (yBot <= yTop) continue;
        const flicker = 0.82 + 0.32 * hash01(b, Math.floor(now / 90));
        const a = Math.min(0.5, alpha * 0.5 * flicker);
        ctx.fillStyle = `rgba(${fg[0]},${fg[1]},${fg[2]},${a.toFixed(3)})`;
        ctx.fillRect(bucketX(b), yTop, bucketPxWidth + 0.5, yBot - yTop);
      }
    };

    const drawStaticFlow = (lane: LaneState, laneTop: number) => {
      // reduced-motion only: a single non-scrolling fill so the fresh
      // channel still reads as carrying live flow, not an empty gutter.
      for (let b = 0; b < numBuckets; b++) {
        const yTop = laneTop + (lane.top[b] ?? 0);
        const yBot = laneTop + laneH - (lane.bottom[b] ?? 0);
        if (yBot <= yTop) continue;
        ctx.fillStyle = `rgba(${fg[0]},${fg[1]},${fg[2]},0.35)`;
        ctx.fillRect(bucketX(b), yTop, bucketPxWidth + 0.5, yBot - yTop);
      }
    };

    const draw = (now: number) => {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      if (w <= 0 || h <= 0) return;

      ctx.strokeStyle = `rgb(${bd[0]},${bd[1]},${bd[2]})`;
      ctx.lineWidth = 1;
      ctx.strokeRect(0.5, 0.5, Math.max(0, w - 1), Math.max(0, h - 1));

      for (let l = 0; l < 2; l++) {
        const lane = lanes[l];
        if (!lane) continue;
        const top = laneY0(l);
        if (lane.active) {
          if (reduced) drawStaticFlow(lane, top);
          else drawFlowBand(lane, top, l, now);
        }
        ctx.fillStyle = `rgb(${fg[0]},${fg[1]},${fg[2]})`;
        drawMargin(lane, top, l, "top");
        drawMargin(lane, top, l, "bottom");
      }
    };

    const loop = (now: number) => {
      if (disposed) return;
      if (!visible) {
        raf = 0;
        return;
      }
      deposit(now);
      resolveBreachAnim(now);
      draw(now);
      raf = requestAnimationFrame(loop);
    };

    const allocLanes = () => {
      lanes[0].top = new Float32Array(numBuckets);
      lanes[0].bottom = new Float32Array(numBuckets);
      lanes[1].top = new Float32Array(numBuckets);
      lanes[1].bottom = new Float32Array(numBuckets);
    };

    const measure = () => {
      const rect = root.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      if (w < 2 || h < 2) return false;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));

      const minDim = Math.min(w, h);
      const bucketTarget = Math.max(3, minDim / 40);
      numBuckets = Math.max(16, Math.floor(w / bucketTarget));
      bucketPxWidth = w / numBuckets;
      laneGap = Math.max(1, Math.round(minDim / 80));
      laneH = (h - laneGap) / 2;
      halfLane = laneH / 2;
      dotPitch = Math.max(2, Math.min(4, Math.round(minDim / 90)));
      allocLanes();
      return true;
    };

    const start = () => {
      if (!measure()) return;
      const now = performance.now();
      if (reduced) {
        buildReducedFrame();
        draw(now);
        raf = 0;
        return;
      }
      warmStart(now);
      draw(now);
      if (raf === 0) raf = requestAnimationFrame(loop);
    };

    start();

    let resizeTimer = 0;
    const onResize = () => {
      window.clearTimeout(resizeTimer);
      resizeTimer = window.setTimeout(() => {
        if (disposed) return;
        cancelAnimationFrame(raf);
        raf = 0;
        start();
      }, 120);
    };
    const ro = new ResizeObserver(onResize);
    ro.observe(root);

    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && !reduced && raf === 0 && !disposed) {
        raf = requestAnimationFrame(loop);
      }
    });
    io.observe(root);

    const mo = new MutationObserver(() => {
      derive();
      if (raf === 0) draw(performance.now());
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      raf = 0;
      window.clearTimeout(resizeTimer);
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
    };
  }, []);

  return (
    <div
      ref={rootRef}
      role="img"
      aria-label={label}
      className={`relative w-full overflow-hidden rounded-sm ${className}`}
    >
      <canvas ref={canvasRef} aria-hidden className="h-full w-full" />
    </div>
  );
}

"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// MullHinge — a margin comment thread glued to its anchored phrase by a
// translucent SVG tissue strip (a bookbinder's hinge), whose geometry is a
// strain gauge on anchor health rather than decoration. The thread is a
// controlled component: the consumer's collab/document layer supplies
// `driftPx` (currentAnchorTop − anchorTopAtCreation, in px) and `orphaned`
// (true once the anchored text itself was deleted upstream) — this
// component owns only the physics and the rendering, never the measurement.
//
// PHYSICS: driftPx changes spring-animate (k=210 s^-2, zeta=0.9) rather than
// snapping, so a large upstream paste reads as the hinge being yanked, not
// as a teleport. From the *displayed* (spring) drift we derive shear angle
// = atan(drift / hingeLength), capped at ±38deg — past that angle the strip
// would visually slip off the card's edge and read as broken when the
// anchor is actually still perfectly attached, so both the quoted-text
// marker and the hinge's own geometry are driven off the SAME capped value.
// That's what keeps the hard constraint true: the hinge is glued at both
// endpoints at all times, it just refuses to *look* torn before it is.
// Tissue opacity falls 0.5 -> 0.25 with the same capped ratio (stretched
// tissue reads thinner). Past 120px of raw drift a Mend affordance fades
// in, letting the consumer accept the current position as the new baseline.
//
// ORPHAN: when `orphaned` flips true, the single tissue quad — always
// rendered as two SVG pieces sharing one precomputed jagged clip-path
// boundary, invisible at rest because the pieces sit flush — separates
// along that boundary over 300ms ease-out (a real CSS transform
// transition, not a re-layout), then the card-side piece gets one damped
// ~4deg sway (a second spring, k=70 zeta=0.32) around the point still
// glued to the card. The text-side remainder becomes a frayed, inert stub.
// Nothing is deleted from the DOM or reflows into a different shape —
// dangling is a genuine end state, not a leader line re-routing.
//
// Differs from margin-cite on purpose: that is static citation furniture
// that never claims to track anything. Here the connector is stateful and
// its whole job is to make broken attachment visible before you read a
// word — every other shipped margin-comment competitor asserts attachment
// and silently orphans instead.
//
// A11y: real <section> with a heading; the hinge SVG is aria-hidden and its
// meaning is duplicated as plain text via aria-describedby ('anchored to
// "…", drifted N paragraphs down' / 'original text deleted'); a real
// <textarea> and reply buttons carry the thread; Jump-to-anchor moves focus
// to the quoted-text marker and scrolls it into view; orphaned threads keep
// the last-known quote inline, never hide it. Reduced motion swaps every
// spring for an instant snap and drops the sway entirely.
//
// Pure DOM + inline SVG + CSS. Colors: --background, --foreground,
// --ns-muted, --border, --ns-accent only — --ns-accent appears solely on
// focus rings and the reply/mend affordances.
// ---------------------------------------------------------------------------

type Spring = { x: number; v: number; t: number };
function stepSpring(s: Spring, k: number, zeta: number, dt: number) {
  const c = 2 * zeta * Math.sqrt(k);
  s.v += (k * (s.t - s.x) - c * s.v) * dt;
  s.x += s.v * dt;
}
function settled(s: Spring, epsX = 0.05, epsV = 0.05) {
  return Math.abs(s.x - s.t) < epsX && Math.abs(s.v) < epsV;
}
const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));

const DRIFT_K = 210; // s^-2
const DRIFT_ZETA = 0.9;
const SWAY_K = 70; // s^-2
const SWAY_ZETA = 0.32;
const ANGLE_CAP = (38 * Math.PI) / 180;
const MEND_THRESHOLD = 120; // px, raw (uncapped) drift
const TEAR_MS = 300;
const OPACITY_MAX = 0.5;
const OPACITY_MIN = 0.25;

// Hinge logical geometry, in SVG viewBox units (== px at hingeLength width).
const H = 40; // strip height
const CY = H / 2;
const HALF = 7; // glued-edge half-thickness
const STUB_LEN = 15; // px into the strip where the tear boundary sits

// Precomputed jagged tear boundary: (yFraction 0..1, x offset from STUB_LEN).
// Fixed once — this is the polyline the tear always splits along, never
// recomputed per drift or per orphan, matching a real physical tear.
const JAGGED: [number, number][] = [
  [0, 0],
  [0.22, -2.6],
  [0.45, 1.8],
  [0.68, -1.9],
  [0.86, 2.3],
  [1, 0],
];

function buildClipPaths(w: number) {
  const cutX = (dx: number) => STUB_LEN + dx;
  const down = JAGGED.map(([yFrac, dx]) => `${cutX(dx)},${yFrac * H}`);
  const up = [...JAGGED].reverse().map(([yFrac, dx]) => `${cutX(dx)},${yFrac * H}`);
  const left = `0,0 0,${H} ${down.join(" ")}`;
  const right = `${up.join(" ")} ${w},${H} ${w},0`;
  return { left, right };
}

export interface MullHingeComment {
  id: string;
  author: string;
  body: string;
  timestamp?: string;
}

export interface MullHingeProps {
  /** the exact phrase this thread is anchored to; shown as the margin marker and, if orphaned, the permanent last-known snapshot */
  anchorQuote: string;
  /** currentAnchorTop − anchorTopAtCreation, in px. Positive = the anchor moved down. Drives the hinge's shear/opacity via a spring. */
  driftPx: number;
  /** true once the anchored text has been deleted upstream — tears the hinge and leaves the card dangling from a frayed stub */
  orphaned?: boolean;
  /** thread heading, e.g. "3 comments" */
  title: string;
  comments: MullHingeComment[];
  /** fires with the trimmed reply body; the composer clears itself on submit */
  onReply?: (body: string) => void;
  /** re-anchor: accept the current drifted position as the new baseline. Shown once |driftPx| exceeds 120px. */
  onMend?: () => void;
  /** fires when Jump-to-anchor is activated, in addition to the built-in focus+scroll */
  onJumpToAnchor?: () => void;
  /** horizontal span the tissue strip covers, in px. @default 56 */
  hingeLength?: number;
  replyPlaceholder?: string;
  replyLabel?: string;
  jumpLabel?: string;
  mendLabel?: string;
  className?: string;
}

export function MullHinge({
  anchorQuote,
  driftPx,
  orphaned = false,
  title,
  comments,
  onReply,
  onMend,
  onJumpToAnchor,
  hingeLength = 56,
  replyPlaceholder = "Reply…",
  replyLabel = "Post reply",
  jumpLabel = "Jump to anchor",
  mendLabel = "Mend",
  className = "",
}: MullHingeProps) {
  const rawId = useId().replace(/:/g, "");
  const headingId = `${rawId}-h`;
  const describeId = `${rawId}-d`;
  const markerId = `${rawId}-m`;
  const clipLeftId = `${rawId}-cl`;
  const clipRightId = `${rawId}-cr`;

  const [displayDrift, setDisplayDrift] = useState(driftPx);
  const [torn, setTorn] = useState(orphaned);
  const [swayDeg, setSwayDeg] = useState(0);
  const [reply, setReply] = useState("");

  const springRef = useRef<Spring>({ x: driftPx, v: 0, t: driftPx });
  const rafRef = useRef<number | undefined>(undefined);
  const lastRef = useRef<number | null>(null);
  const reducedRef = useRef(false);
  const markerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    reducedRef.current = mq.matches;
    const onChange = () => {
      reducedRef.current = mq.matches;
    };
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  // drive the drift spring toward driftPx
  useEffect(() => {
    springRef.current.t = driftPx;
    if (reducedRef.current) {
      springRef.current.x = driftPx;
      springRef.current.v = 0;
      setDisplayDrift(driftPx);
      return;
    }
    if (rafRef.current != null) return; // loop already running; picks up the new target next tick
    const loop = (now: number) => {
      if (lastRef.current == null) lastRef.current = now;
      const dt = Math.min((now - lastRef.current) / 1000, 0.032);
      lastRef.current = now;
      stepSpring(springRef.current, DRIFT_K, DRIFT_ZETA, dt);
      setDisplayDrift(springRef.current.x);
      if (settled(springRef.current)) {
        rafRef.current = undefined;
        lastRef.current = null;
        return;
      }
      rafRef.current = requestAnimationFrame(loop);
    };
    rafRef.current = requestAnimationFrame(loop);
  }, [driftPx]);

  useEffect(
    () => () => {
      if (rafRef.current != null) cancelAnimationFrame(rafRef.current);
    },
    []
  );

  // tear sequencing: orphaned true -> split plays (CSS, TEAR_MS) -> one damped sway spring
  useEffect(() => {
    if (!orphaned) {
      setTorn(false);
      setSwayDeg(0);
      return;
    }
    setTorn(true);
    if (reducedRef.current) {
      setSwayDeg(0);
      return;
    }
    let raf = 0;
    const timer = window.setTimeout(() => {
      const s: Spring = { x: 4, v: 0, t: 0 };
      let last: number | null = null;
      const step = (now: number) => {
        if (last == null) last = now;
        const dt = Math.min((now - last) / 1000, 0.032);
        last = now;
        stepSpring(s, SWAY_K, SWAY_ZETA, dt);
        setSwayDeg(s.x);
        if (settled(s)) return;
        raf = requestAnimationFrame(step);
      };
      raf = requestAnimationFrame(step);
    }, TEAR_MS);
    return () => {
      window.clearTimeout(timer);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [orphaned]);

  const rawAngle = Math.atan2(displayDrift, hingeLength);
  const clampedAngle = clamp(rawAngle, -ANGLE_CAP, ANGLE_CAP);
  const visualOffset = hingeLength * Math.tan(clampedAngle);
  const normalized = clamp(Math.abs(clampedAngle) / ANGLE_CAP, 0, 1);
  const tissueOpacity = OPACITY_MAX - (OPACITY_MAX - OPACITY_MIN) * normalized;
  const mendVisible = !orphaned && Math.abs(displayDrift) > MEND_THRESHOLD;

  const { left: clipLeftPoints, right: clipRightPoints } = useMemo(
    () => buildClipPaths(hingeLength),
    [hingeLength]
  );

  const leftEdgeCenter = CY + visualOffset; // anchor/text side — moves with drift
  const rightEdgeCenter = CY; // card side — fixed, always glued
  const quadPoints = `0,${leftEdgeCenter - HALF} ${hingeLength},${rightEdgeCenter - HALF} ${hingeLength},${rightEdgeCenter + HALF} 0,${leftEdgeCenter + HALF}`;

  const describeText = orphaned
    ? "original text deleted"
    : (() => {
        const abs = Math.abs(Math.round(driftPx));
        if (abs < 8) return `anchored to "${anchorQuote}", holding steady`;
        const paragraphs = Math.max(1, Math.round(abs / 72));
        return `anchored to "${anchorQuote}", drifted ${paragraphs} paragraph${paragraphs === 1 ? "" : "s"} ${driftPx > 0 ? "down" : "up"}`;
      })();

  function submitReply() {
    const body = reply.trim();
    if (!body) return;
    onReply?.(body);
    setReply("");
  }

  function jumpToAnchor() {
    const el = markerRef.current;
    el?.focus({ preventScroll: true });
    el?.scrollIntoView({ block: "center", behavior: reducedRef.current ? "auto" : "smooth" });
    onJumpToAnchor?.();
  }

  function replyTo(author: string) {
    setReply((r) => (r ? r : `@${author} `));
    textareaRef.current?.focus();
  }

  return (
    <section
      aria-labelledby={headingId}
      aria-describedby={describeId}
      className={`ns-mullhinge relative flex items-start gap-0 text-foreground ${className}`}
    >
      <span id={describeId} className="sr-only">
        {describeText}
      </span>

      {/* anchor-side marker — the quoted phrase, translated by the SAME
          capped offset that drives the hinge, so it never visually detaches
          from the strip it's supposedly glued to */}
      <div
        ref={markerRef}
        id={markerId}
        tabIndex={-1}
        style={{ transform: `translateY(${visualOffset}px)` }}
        className="ns-mullhinge-marker max-w-[10rem] shrink-0 rounded-md border border-border bg-background px-2.5 py-1.5 text-xs leading-snug text-ns-muted outline-none focus-visible:ring-2 focus-visible:ring-ns-accent"
      >
        <span className="line-clamp-3">&ldquo;{anchorQuote}&rdquo;</span>
      </div>

      {/* the hinge itself */}
      <svg
        aria-hidden="true"
        width={hingeLength}
        height={H + 16}
        viewBox={`0 -8 ${hingeLength} ${H + 16}`}
        className="ns-mullhinge-svg shrink-0 self-center"
      >
        <defs>
          <clipPath id={clipLeftId}>
            <polygon points={clipLeftPoints} />
          </clipPath>
          <clipPath id={clipRightId}>
            <polygon points={clipRightPoints} />
          </clipPath>
        </defs>

        {/* text-side stub — recedes and droops once torn */}
        <g
          className="ns-mullhinge-stub"
          style={{
            transformBox: "fill-box",
            transformOrigin: "0% 50%",
            transform: torn ? "translate(-5px, 3px) rotate(-9deg)" : "translate(0px, 0px) rotate(0deg)",
          }}
        >
          <polygon
            points={quadPoints}
            clipPath={`url(#${clipLeftId})`}
            fill="var(--foreground)"
            fillOpacity={torn ? 0.22 : tissueOpacity}
            stroke="var(--border)"
            strokeWidth={0.5}
          />
        </g>

        {/* card-side piece — separates, then swings from the card's fixed edge */}
        <g
          className="ns-mullhinge-dangler"
          style={{
            transformBox: "fill-box",
            transformOrigin: "100% 50%",
            transform: torn ? "translate(5px, 0px)" : "translate(0px, 0px)",
          }}
        >
          <g
            style={{
              transformBox: "fill-box",
              transformOrigin: "100% 50%",
              transform: `rotate(${torn ? swayDeg : 0}deg)`,
            }}
          >
            <polygon
              points={quadPoints}
              clipPath={`url(#${clipRightId})`}
              fill="var(--foreground)"
              fillOpacity={tissueOpacity}
              stroke="var(--border)"
              strokeWidth={0.5}
            />
          </g>
        </g>
      </svg>

      {/* the thread card */}
      <div className="ns-mullhinge-card min-w-0 flex-1 rounded-md border border-border bg-background">
        <header className="flex items-center justify-between gap-2 border-b border-border px-3 py-2">
          <h3 id={headingId} className="min-w-0 truncate text-sm font-medium">
            {title}
          </h3>
          <div className="flex shrink-0 items-center gap-1.5">
            {orphaned && (
              <span
                data-mullhinge-orphaned-badge=""
                className="rounded-sm border border-border px-1.5 py-0.5 font-mono text-[9px] uppercase tracking-widest text-ns-muted"
              >
                Orphaned
              </span>
            )}
            {mendVisible && (
              <button
                type="button"
                onClick={() => onMend?.()}
                data-mullhinge-mend=""
                className="rounded-sm px-2 py-1 font-mono text-[10px] uppercase tracking-wide text-ns-accent outline-none transition-colors hover:bg-ns-accent/10 focus-visible:ring-2 focus-visible:ring-ns-accent"
              >
                {mendLabel}
              </button>
            )}
            <button
              type="button"
              onClick={jumpToAnchor}
              data-mullhinge-jump=""
              className="rounded-sm px-2 py-1 font-mono text-[10px] uppercase tracking-wide text-ns-muted outline-none transition-colors hover:bg-foreground/[0.06] hover:text-foreground focus-visible:ring-2 focus-visible:ring-ns-accent"
            >
              {jumpLabel}
            </button>
          </div>
        </header>

        <ul className="flex flex-col gap-2.5 px-3 py-2.5">
          {orphaned && (
            <li className="rounded-sm border border-border bg-foreground/[0.03] px-2.5 py-2 text-xs leading-relaxed text-ns-muted">
              Last known quote: &ldquo;{anchorQuote}&rdquo;
            </li>
          )}
          {comments.map((c) => (
            <li key={c.id} className="flex items-start justify-between gap-2">
              <div className="min-w-0">
                <p className="text-xs font-medium">
                  {c.author}
                  {c.timestamp && <span className="ml-1.5 font-normal text-ns-muted">{c.timestamp}</span>}
                </p>
                <p className="mt-0.5 text-sm leading-relaxed">{c.body}</p>
              </div>
              <button
                type="button"
                onClick={() => replyTo(c.author)}
                aria-label={`Reply to ${c.author}`}
                className="shrink-0 rounded-sm px-1.5 py-1 font-mono text-[10px] uppercase tracking-wide text-ns-muted outline-none transition-colors hover:bg-foreground/[0.06] hover:text-foreground focus-visible:ring-2 focus-visible:ring-ns-accent"
              >
                Reply
              </button>
            </li>
          ))}
        </ul>

        <div className="flex flex-col gap-1.5 border-t border-border px-3 py-2.5">
          <label htmlFor={`${rawId}-ta`} className="sr-only">
            Reply to {title}
          </label>
          <textarea
            ref={textareaRef}
            id={`${rawId}-ta`}
            value={reply}
            onChange={(e) => setReply(e.target.value)}
            placeholder={replyPlaceholder}
            rows={2}
            className="w-full resize-none rounded-sm border border-border bg-background px-2 py-1.5 text-sm leading-relaxed outline-none focus-visible:ring-2 focus-visible:ring-ns-accent"
          />
          <button
            type="button"
            onClick={submitReply}
            disabled={!reply.trim()}
            data-mullhinge-post=""
            className="self-end rounded-sm border border-border px-2.5 py-1 font-mono text-[10px] uppercase tracking-wide text-foreground outline-none transition-colors hover:bg-foreground/[0.06] focus-visible:ring-2 focus-visible:ring-ns-accent disabled:pointer-events-none disabled:opacity-40"
          >
            {replyLabel}
          </button>
        </div>
      </div>

      <style>{`
        .ns-mullhinge-marker {
          transition: transform 80ms linear;
        }
        .ns-mullhinge-stub,
        .ns-mullhinge-dangler {
          transition: transform ${TEAR_MS}ms ease-out;
        }
        @media (prefers-reduced-motion: reduce) {
          .ns-mullhinge-marker,
          .ns-mullhinge-stub,
          .ns-mullhinge-dangler {
            transition: none;
          }
        }
      `}</style>
    </section>
  );
}

"use client";

import { useLayoutEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// NavBlueNoiseScrim — the dimming backdrop behind a command palette / search
// overlay, rendered as a TEMPORAL blue-noise dither instead of a flat tint.
//
// Spatial mask: a real void-and-cluster point distribution (Ulichney 1993),
// computed once per matrix size. Unlike the repo's ordered-dither family
// (background-ascii-dither's Bayer mode, chart-*-dither), which threshold
// against a small regular 4x4 matrix and read as a visible crosshatch at any
// zoom, void-and-cluster iteratively balances a binary pattern against its
// own Gaussian-blurred energy so no two "on" cells ever cluster and no
// region goes empty for long — an aperiodic, non-repeating-looking point set
// with no dominant frequency. That produces a RANK for every cell in the
// matrix (0..N-1): thresholding "rank < coverage * N" at any coverage level
// yields a blue-noise-distributed dot set, which is the mechanism ordered
// dithering is built on but with a fundamentally different point-generation
// algorithm and a different visual signature (fine, grain-like, isotropic —
// not a lattice).
//
// Temporal reshuffle: real-time renderers get "temporal blue noise" by
// pairing a spatial blue-noise mask with a decorrelated per-frame offset
// (the animated-noise / golden-ratio-sequence trick used for TAA dithering,
// e.g. Playdead's INSIDE, Jorge Jimenez's "Interleaved Gradient Noise").
// Every rAF tick we advance a frame-offset by the golden-ratio conjugate mod
// 1 and threshold `frac(rank / N + offset) < coverage` — every cell cycles
// through the full rank order over N frames, decorrelated frame to frame,
// so which dots are lit changes completely each frame while the SPATIAL
// distribution of "on" cells stays blue-noise at every instant. This is an
// honest approximation of full spatiotemporal blue noise (STBN, which needs
// a pre-baked 3D noise volume) built from one 2D void-and-cluster mask, not
// a from-scratch spatiotemporal solve.
// ---------------------------------------------------------------------------

const MATRIX_SIZE = 32; // 1024-cell void-and-cluster tile
const GOLDEN_CONJUGATE = 0.6180339887498949;

// module-level cache: the matrix is expensive-ish (O(n^2) balancing passes)
// and fully deterministic for a fixed size, so every mounted instance shares
// one computation instead of repeating it per scrim.
let cachedRanks: Uint32Array | null = null;

function computeVoidClusterRanks(size: number): Uint32Array {
  const n = size * size;
  const R = 2; // filter radius (5x5 support)
  const sigma = 1.5;
  const kernel: number[] = [];
  for (let dy = -R; dy <= R; dy++) {
    for (let dx = -R; dx <= R; dx++) {
      kernel.push(Math.exp(-(dx * dx + dy * dy) / (2 * sigma * sigma)));
    }
  }
  const idx = (x: number, y: number) =>
    ((y + size) % size) * size + ((x + size) % size);

  const addEnergy = (
    energy: Float32Array,
    x: number,
    y: number,
    sign: number
  ) => {
    let k = 0;
    for (let dy = -R; dy <= R; dy++) {
      for (let dx = -R; dx <= R; dx++) {
        energy[idx(x + dx, y + dy)] += sign * kernel[k++];
      }
    }
  };

  const tightestCluster = (pattern: Uint8Array, energy: Float32Array) => {
    let best = -1;
    let bestE = -Infinity;
    for (let i = 0; i < n; i++) {
      if (pattern[i] === 1 && energy[i] > bestE) {
        bestE = energy[i];
        best = i;
      }
    }
    return best;
  };
  const largestVoid = (pattern: Uint8Array, energy: Float32Array) => {
    let best = -1;
    let bestE = Infinity;
    for (let i = 0; i < n; i++) {
      if (pattern[i] === 0 && energy[i] < bestE) {
        bestE = energy[i];
        best = i;
      }
    }
    return best;
  };

  // deterministic seed so the mask is stable across reloads/screenshots
  let seed = 0x9e3779b9;
  const rand = () => {
    seed = (seed + 0x6d2b79f5) >>> 0;
    let t = seed;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };

  const pattern = new Uint8Array(n);
  const energy = new Float32Array(n);
  const initialCount = Math.max(2, Math.round(n * 0.1));
  const ones = new Set<number>();
  while (ones.size < initialCount) ones.add(Math.floor(rand() * n));
  for (const i of ones) {
    pattern[i] = 1;
    addEnergy(energy, i % size, Math.floor(i / size), 1);
  }

  // Phase 1 — balance the initial pattern: swap the tightest cluster for the
  // largest void until a swap would just reverse itself (converged).
  for (let iter = 0; iter < initialCount * 4; iter++) {
    const cluster = tightestCluster(pattern, energy);
    pattern[cluster] = 0;
    addEnergy(energy, cluster % size, Math.floor(cluster / size), -1);
    const voidCell = largestVoid(pattern, energy);
    if (voidCell === cluster) {
      pattern[cluster] = 1;
      addEnergy(energy, cluster % size, Math.floor(cluster / size), 1);
      break;
    }
    pattern[voidCell] = 1;
    addEnergy(energy, voidCell % size, Math.floor(voidCell / size), 1);
  }

  const ranks = new Uint32Array(n);
  const balancedCount = pattern.reduce((a, b) => a + b, 0);
  // snapshot the converged, balanced pattern before phase 2 consumes it —
  // phase 3 restarts from this exact state rather than re-deriving it.
  const p3 = pattern.slice();
  const e3 = energy.slice();

  // Phase 2 — rank the balanced ones downward (n0-1 .. 0): repeatedly strip
  // the tightest cluster, so the most-clustered cell gets the lowest rank
  // and empties first as coverage shrinks.
  const p2 = pattern;
  const e2 = energy;
  let rank = balancedCount - 1;
  while (rank >= 0) {
    const cluster = tightestCluster(p2, e2);
    p2[cluster] = 0;
    addEnergy(e2, cluster % size, Math.floor(cluster / size), -1);
    ranks[cluster] = rank;
    rank--;
  }

  // Phase 3 — rank the remaining zeros upward (n0 .. N-1) from the snapshot
  // of the balanced pattern: repeatedly fill the largest void, so cells fill
  // in the order that keeps the pattern most evenly spread at every coverage.
  rank = balancedCount;
  while (rank < n) {
    const voidCell = largestVoid(p3, e3);
    p3[voidCell] = 1;
    addEnergy(e3, voidCell % size, Math.floor(voidCell / size), 1);
    ranks[voidCell] = rank;
    rank++;
  }

  return ranks;
}

export interface NavBlueNoiseScrimProps {
  /** grain cell size in px — kept fine and proportional, never a coarse checkerboard */
  cellSize?: number;
  /** mean fraction of cells lit at any instant, 0..1 */
  coverage?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function NavBlueNoiseScrim({
  cellSize = 4,
  coverage = 0.07,
  className = "",
}: NavBlueNoiseScrimProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // token derive happens in useLayoutEffect, before first paint, so no rAF /
  // ResizeObserver / reduced-motion branch can draw with an empty ink string
  useLayoutEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    let bg = "";
    let fg = "";
    const readTokens = () => {
      const cs = getComputedStyle(document.documentElement);
      bg = cs.getPropertyValue("--background").trim();
      fg = cs.getPropertyValue("--foreground").trim();
    };
    readTokens();

    if (!cachedRanks) cachedRanks = computeVoidClusterRanks(MATRIX_SIZE);
    const ranks = cachedRanks;
    const n = MATRIX_SIZE * MATRIX_SIZE;

    let dpr = 1;
    let cols = 0;
    let rows = 0;
    let cssW = 0;
    let cssH = 0;
    let raf = 0;
    let frame = 0;
    let disposed = false;

    const resize = () => {
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      const rect = canvas.getBoundingClientRect();
      cssW = rect.width;
      cssH = rect.height;
      canvas.width = Math.max(1, Math.round(cssW * dpr));
      canvas.height = Math.max(1, Math.round(cssH * dpr));
      cols = Math.ceil(cssW / cellSize);
      rows = Math.ceil(cssH / cellSize);
    };

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const ro = new ResizeObserver(() => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
        if (reduced) draw(0);
      }, 100);
    });
    ro.observe(canvas);

    // base dim: a controlled, flat --background wash so the scrim reads as
    // "behind the dialog" even where no grain cell lands this frame — the
    // grain is texture on TOP of legibility, not the source of it. The
    // dialog panel itself (see demo) is fully opaque, so nothing drawn here
    // ever touches its text regardless of coverage or alpha.
    const BASE_DIM_ALPHA = 0.55;
    const GRAIN_ALPHA = 0.5;

    const draw = (offset: number) => {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, cssW, cssH);
      ctx.fillStyle = bg;
      ctx.globalAlpha = BASE_DIM_ALPHA;
      ctx.fillRect(0, 0, cssW, cssH);

      ctx.fillStyle = fg;
      ctx.globalAlpha = GRAIN_ALPHA;
      for (let gy = 0; gy < rows; gy++) {
        const my = gy % MATRIX_SIZE;
        for (let gx = 0; gx < cols; gx++) {
          const mx = gx % MATRIX_SIZE;
          const rank = ranks[my * MATRIX_SIZE + mx];
          const t = (rank / n + offset) % 1;
          if (t < coverage) {
            ctx.fillRect(gx * cellSize, gy * cellSize, cellSize, cellSize);
          }
        }
      }
      ctx.globalAlpha = 1;
    };

    const loop = () => {
      frame++;
      const offset = (frame * GOLDEN_CONJUGATE) % 1;
      draw(offset);
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    const onVis = () => {
      if (!document.hidden && !reduced) {
        raf = requestAnimationFrame(loop);
      }
    };
    document.addEventListener("visibilitychange", onVis);

    // theme flip re-reads tokens live; frozen reduced-motion frame repaints
    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) draw(0);
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    document.fonts.ready.then(() => {
      if (disposed) return;
      resize();
      if (reduced) {
        // prefers-reduced-motion: freeze to a single static blue-noise mask
        // instance (offset 0) rather than reshuffling every frame — still
        // aperiodic and still distinct from Bayer, just not animated. A
        // per-frame reshuffling grain is exactly the kind of motion this
        // media query exists to suppress.
        draw(0);
      } else {
        raf = requestAnimationFrame(loop);
      }
    });

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      ro.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [cellSize, coverage]);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden="true"
      className={`pointer-events-none block h-full w-full ${className}`}
    />
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// NavCondenseRail — a full-width site nav that condenses in place as the page
// scrolls: roomy at the top (tall padding, full-size wordmark and links) and
// a dense pinned rail once you've moved past it (tight padding, smaller type,
// tighter gaps). Unlike a scroll-position hack keyed to an arbitrary pixel
// constant, the travel distance the condense happens over is the *measured*
// difference between the nav's own roomy height and its own dense height —
// two off-screen probes render the real markup at each extreme and report
// their heights via ResizeObserver, so the transition is always exactly as
// long as the nav's own vertical shrink, on any wordmark, any font, any
// viewport. Everything that changes every scroll frame (height, padding,
// wordmark scale, link size/gap, border/background opacity) is written
// straight to refs' inline styles inside one rAF loop; React state only holds
// the two measured heights (set once, rarely) and reduced-motion.
// ---------------------------------------------------------------------------

export interface NavCondenseRailLink {
  href: string;
  label: string;
}

export interface NavCondenseRailProps {
  /** brand text on the left */
  wordmark?: string;
  /** nav links, in order */
  links?: NavCondenseRailLink[];
  /** trailing CTA link/button */
  cta?: NavCondenseRailLink;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const DEFAULT_LINKS: NavCondenseRailLink[] = [
  { href: "#work", label: "Work" },
  { href: "#process", label: "Process" },
  { href: "#pricing", label: "Pricing" },
  { href: "#contact", label: "Contact" },
];

const DEFAULT_CTA: NavCondenseRailLink = { href: "#start", label: "Start a project" };

// Style pairs interpolated between the roomy (progress 0) and dense
// (progress 1) ends. Heights are never guessed here — they come from the
// measured probes below.
const ROOMY = { padY: 28, logoScale: 1, linkSize: 15, gap: 32, ctaPadX: 18, ctaPadY: 10 };
const DENSE = { padY: 12, logoScale: 0.82, linkSize: 13, gap: 22, ctaPadX: 14, ctaPadY: 7 };
const LERP_RATE = 14; // 1/s — exponential approach toward the scroll-derived target
const FALLBACK_TRAVEL = 40; // px, used only for the handful of frames before probes report in

function lerp(a: number, b: number, t: number) {
  return a + (b - a) * t;
}

function clamp01(v: number) {
  return v < 0 ? 0 : v > 1 ? 1 : v;
}

// The nav's real inner markup, shared between the live bar and the two
// measurement probes so a probe's height is never anything other than the
// height the actual bar would take at that padding/font size.
function NavInner({
  wordmark,
  links,
  cta,
  padY,
  linkSize,
  gap,
  ctaPadX,
  ctaPadY,
  wordmarkRef,
  linksContainerRef,
}: {
  wordmark: string;
  links: NavCondenseRailLink[];
  cta?: NavCondenseRailLink;
  padY: number;
  linkSize: number;
  gap: number;
  ctaPadX: number;
  ctaPadY: number;
  wordmarkRef?: (el: HTMLSpanElement | null) => void;
  linksContainerRef?: (el: HTMLDivElement | null) => void;
}) {
  return (
    <div
      className="mx-auto flex w-full max-w-6xl items-center justify-between px-6"
      style={{ paddingTop: padY, paddingBottom: padY }}
    >
      <a
        href="#top"
        className="shrink-0 rounded-sm font-mono font-semibold tracking-tight text-foreground transition-colors duration-150 hover:text-ns-accent focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ns-accent"
        style={{ fontSize: 17 }}
      >
        <span ref={wordmarkRef} className="inline-block origin-left">
          {wordmark}
        </span>
      </a>

      <div ref={linksContainerRef} className="flex items-center" style={{ gap }}>
        {links.map((l) => (
          <a
            key={l.href}
            href={l.href}
            className="whitespace-nowrap rounded-sm text-ns-muted transition-colors duration-150 hover:text-foreground focus-visible:text-foreground focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ns-accent"
            style={{ fontSize: linkSize }}
          >
            {l.label}
          </a>
        ))}
        {cta && (
          <a
            href={cta.href}
            className="shrink-0 whitespace-nowrap rounded-sm bg-ns-accent font-medium text-white transition-colors duration-150 hover:bg-ns-accent-hover focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ns-accent"
            style={{ fontSize: linkSize, paddingInline: ctaPadX, paddingBlock: ctaPadY }}
          >
            {cta.label}
          </a>
        )}
      </div>
    </div>
  );
}

export function NavCondenseRail({
  wordmark = "ns-ui",
  links = DEFAULT_LINKS,
  cta = DEFAULT_CTA,
  className = "",
}: NavCondenseRailProps) {
  const navRef = useRef<HTMLDivElement | null>(null);
  const spacerRef = useRef<HTMLDivElement | null>(null);
  const wordmarkRef = useRef<HTMLSpanElement | null>(null);
  const linksRef = useRef<HTMLDivElement | null>(null);
  const roomyProbeRef = useRef<HTMLDivElement | null>(null);
  const denseProbeRef = useRef<HTMLDivElement | null>(null);

  const [reduced, setReduced] = useState(false);
  const [roomyH, setRoomyH] = useState<number | null>(null);
  const [denseH, setDenseH] = useState<number | null>(null);

  // ---- reduced motion ---------------------------------------------------
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  // ---- measure the real roomy/dense heights off-screen -------------------
  useEffect(() => {
    const roomy = roomyProbeRef.current;
    const dense = denseProbeRef.current;
    if (!roomy || !dense) return;
    const ro = new ResizeObserver((entries) => {
      for (const entry of entries) {
        const h = entry.borderBoxSize?.[0]?.blockSize ?? entry.contentRect.height;
        if (entry.target === roomy) setRoomyH(h);
        else if (entry.target === dense) setDenseH(h);
      }
    });
    ro.observe(roomy);
    ro.observe(dense);
    return () => ro.disconnect();
  }, [wordmark, links, cta]);

  const travel =
    roomyH != null && denseH != null && roomyH - denseH > 1 ? roomyH - denseH : FALLBACK_TRAVEL;

  const applyFrame = useCallback(
    (p: number) => {
      const nav = navRef.current;
      const spacer = spacerRef.current;
      const wm = wordmarkRef.current;
      const linksEl = linksRef.current;
      if (!nav) return;

      const padY = lerp(ROOMY.padY, DENSE.padY, p);
      const logoScale = lerp(ROOMY.logoScale, DENSE.logoScale, p);
      const linkSize = lerp(ROOMY.linkSize, DENSE.linkSize, p);
      const gap = lerp(ROOMY.gap, DENSE.gap, p);

      nav.style.paddingTop = `${padY}px`;
      nav.style.paddingBottom = `${padY}px`;
      nav.style.backgroundColor =
        p > 0.02
          ? `color-mix(in srgb, var(--background) ${lerp(0, 100, clamp01(p / 0.3))}%, transparent)`
          : "transparent";
      nav.style.borderBottomWidth = "1px";
      nav.style.borderBottomColor = `color-mix(in srgb, var(--border) ${Math.round(clamp01(p / 0.15) * 100)}%, transparent)`;
      nav.style.backdropFilter = p > 0.05 ? "blur(10px)" : "none";

      if (wm) wm.style.transform = `scale(${logoScale})`;
      if (linksEl) {
        linksEl.style.gap = `${gap}px`;
        for (const child of Array.from(linksEl.children)) {
          (child as HTMLElement).style.fontSize = `${linkSize}px`;
          if ((child as HTMLElement).tagName === "A" && child === linksEl.lastElementChild && cta) {
            (child as HTMLElement).style.paddingInline = `${lerp(ROOMY.ctaPadX, DENSE.ctaPadX, p)}px`;
            (child as HTMLElement).style.paddingBlock = `${lerp(ROOMY.ctaPadY, DENSE.ctaPadY, p)}px`;
          }
        }
      }

      const h = lerp(roomyH ?? ROOMY.padY * 2 + 24, denseH ?? DENSE.padY * 2 + 24, clamp01(p));
      if (spacer) spacer.style.height = `${h}px`;
    },
    [cta, roomyH, denseH]
  );

  useEffect(() => {
    if (reduced) return;
    let raf = 0;
    let last = performance.now();
    let current = 0;

    const tick = (now: number) => {
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;
      const target = clamp01(window.scrollY / travel);
      current = lerp(current, target, 1 - Math.exp(-LERP_RATE * dt));
      applyFrame(current);
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [reduced, travel, applyFrame]);

  // reduced motion: two discrete states, no interpolation, boundary sits at
  // the midpoint of the measured travel distance (not an arbitrary constant)
  useEffect(() => {
    if (!reduced) return;
    const apply = () => applyFrame(window.scrollY > travel / 2 ? 1 : 0);
    apply();
    window.addEventListener("scroll", apply, { passive: true });
    return () => window.removeEventListener("scroll", apply);
  }, [reduced, travel, applyFrame]);

  return (
    <>
      <div
        ref={navRef}
        role="navigation"
        aria-label="Primary"
        className={`fixed inset-x-0 top-0 z-40 border-b ${className}`}
        style={{ borderBottomColor: "transparent", transitionProperty: "none" }}
      >
        <NavInner
          wordmark={wordmark}
          links={links}
          cta={cta}
          padY={ROOMY.padY}
          linkSize={ROOMY.linkSize}
          gap={ROOMY.gap}
          ctaPadX={ROOMY.ctaPadX}
          ctaPadY={ROOMY.ctaPadY}
          wordmarkRef={(el) => {
            wordmarkRef.current = el;
          }}
          linksContainerRef={(el) => {
            linksRef.current = el;
          }}
        />
      </div>

      {/* Reserves the fixed bar's current height in normal flow so the page
          never jumps as it condenses; height is written every frame above. */}
      <div ref={spacerRef} aria-hidden="true" style={{ height: ROOMY.padY * 2 + 24 }} />

      {/* Off-screen measurement probes: real markup at each extreme, never
          painted, purely so the travel distance is a measured fact rather
          than a guessed pixel constant. */}
      <div
        ref={roomyProbeRef}
        aria-hidden="true"
        className="pointer-events-none fixed left-[-99999px] top-0 w-full"
        style={{ visibility: "hidden" }}
      >
        <NavInner
          wordmark={wordmark}
          links={links}
          cta={cta}
          padY={ROOMY.padY}
          linkSize={ROOMY.linkSize}
          gap={ROOMY.gap}
          ctaPadX={ROOMY.ctaPadX}
          ctaPadY={ROOMY.ctaPadY}
        />
      </div>
      <div
        ref={denseProbeRef}
        aria-hidden="true"
        className="pointer-events-none fixed left-[-99999px] top-0 w-full"
        style={{ visibility: "hidden" }}
      >
        <NavInner
          wordmark={wordmark}
          links={links}
          cta={cta}
          padY={DENSE.padY}
          linkSize={DENSE.linkSize}
          gap={DENSE.gap}
          ctaPadX={DENSE.ctaPadX}
          ctaPadY={DENSE.ctaPadY}
        />
      </div>
    </>
  );
}

"use client";

import { useLayoutEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// NavOverstrikeTypewriter — a real site nav whose backing strip is rendered
// as typewriter OVERSTRIKE shading: striking several characters into the
// same cell without advancing the carriage, so their ink compounds into a
// denser mark. This is a real technique from typewriter-art practice (e.g.
// "M" over "8" over ":" to fake a mid-tone the machine's fixed character set
// has no single glyph for) — it is NOT this registry's usual glyph-density
// ramp, where one glyph is picked off an ordered list by luminance. Every
// cell here gets 1-3 *separate* fillText passes composited on top of each
// other with independent jitter and alpha, so coverage genuinely compounds
// where strokes overlap — a fake version would just look up a single denser
// glyph, which is exactly the mechanic this component exists to be distinct
// from.
//
// The strip sits as a thin ruled line beneath the real link row, one column
// band per nav item. The item carrying aria-current="page" always strikes
// at the deepest stack (3 passes) — "the active item is whichever cells
// carry the deepest overstrike stack" is not a metaphor, it is literally how
// the current-page indicator reads. A slow ping-pong sweep — a carriage
// returning and going back over the line — passes across the strip
// continuously, giving every cell it crosses one extra, freshly-chosen
// overstrike pass that fades with proximity, so the strip visibly re-types
// itself at rest without ever using --ns-accent (interaction-only) in the
// ambient field.
//
// House idiom duplicated on purpose (no shared helpers, per project
// convention): cell metrics via an offscreen measureText after
// document.fonts.ready, tokens via getComputedStyle + a MutationObserver on
// documentElement's class, one rAF loop paused on document visibilitychange.
// ---------------------------------------------------------------------------

export interface NavOverstrikeTypewriterLink {
  href: string;
  label: string;
  /** marks this item as the current page — also the deepest overstrike stack */
  current?: boolean;
}

export interface NavOverstrikeTypewriterProps {
  /** brand text on the left */
  wordmark?: string;
  /** nav links, in order */
  links?: NavOverstrikeTypewriterLink[];
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const DEFAULT_LINKS: NavOverstrikeTypewriterLink[] = [
  { href: "#work", label: "Work", current: true },
  { href: "#process", label: "Process" },
  { href: "#pricing", label: "Pricing" },
  { href: "#contact", label: "Contact" },
];

// Characters real overstrike shading actually reaches for: tall, ink-heavy
// letterforms and punctuation a typewriter's fixed set would stack to fake
// tone the machine has no single glyph for.
const GLYPH_POOL = ["M", "W", "N", "H", "K", "X", "#", "8", "%", "&", ":", ".", "-", "+", "/"];

const BASE_STACK_MIN = 1;
const BASE_STACK_MAX = 2;
const ACTIVE_STACK = 3;
const MAX_STACK = 3;
const JITTER_PX = 1.3;
const SWEEP_PERIOD_MS = 7200; // one carriage return + return-stroke, full cycle
const SWEEP_SIGMA = 26; // px, width of the re-strike kernel around the carriage
// Reduced motion freezes here rather than at t=0: at this sweep phase the
// carriage sits clear of the active item's own permanent 3-stack, so a
// single static frame shows BOTH cues at once — the always-deep active
// column and a freshly re-struck ambient cell — rather than a blank strip
// or the two effects coinciding and looking like one.
const STATIC_SWEEP_T = 0.63;

function hash32(x: number): number {
  x = Math.imul(x ^ (x >>> 16), 0x45d9f3b);
  x = Math.imul(x ^ (x >>> 16), 0x45d9f3b);
  x = x ^ (x >>> 16);
  return x >>> 0;
}

function glyphFor(seed: number): string {
  return GLYPH_POOL[hash32(seed) % GLYPH_POOL.length];
}

function jitterFor(seed: number): number {
  const h = hash32(seed + 0x2545f4);
  return ((h % 1000) / 1000 - 0.5) * JITTER_PX * 2;
}

// Triangle wave: 0 -> 1 -> 0 over one period, like a carriage sweeping right
// then returning left rather than snapping back.
function triangle(t: number): number {
  const p = t * 2;
  return p > 1 ? 2 - p : p;
}

export function NavOverstrikeTypewriter({
  wordmark = "ns-ui",
  links = DEFAULT_LINKS,
  className = "",
}: NavOverstrikeTypewriterProps) {
  const navRef = useRef<HTMLElement | null>(null);
  const stripRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const linkRefs = useRef<Map<string, HTMLAnchorElement>>(new Map());

  // token derive happens in useLayoutEffect, before first paint, so no rAF /
  // ResizeObserver / reduced-motion branch can draw with an empty ink string
  useLayoutEffect(() => {
    const strip = stripRef.current;
    const canvas = canvasRef.current;
    if (!strip || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const offscreen = document.createElement("canvas").getContext("2d");
    if (!offscreen) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let fg = "";
    let muted = "";
    const readTokens = () => {
      const cs = getComputedStyle(document.documentElement);
      fg = cs.getPropertyValue("--foreground").trim();
      muted = cs.getPropertyValue("--ns-muted").trim();
    };
    readTokens();

    let disposed = false;
    let raf = 0;
    let dpr = 1;
    let cssW = 0;
    let cssH = 0;
    let cellW = 0;
    let cellH = 0;
    let cols = 0;
    let fontPx = 12;
    let activeStart = -1;
    let activeEnd = -1;

    const computeActiveRange = () => {
      const activeEl = strip
        .closest("nav")
        ?.querySelector<HTMLAnchorElement>('a[aria-current="page"]');
      if (!activeEl || !cellW) {
        activeStart = -1;
        activeEnd = -1;
        return;
      }
      const canvasRect = canvas.getBoundingClientRect();
      const linkRect = activeEl.getBoundingClientRect();
      const startPx = linkRect.left - canvasRect.left;
      const endPx = linkRect.right - canvasRect.left;
      activeStart = Math.max(0, Math.floor(startPx / cellW));
      activeEnd = Math.min(cols, Math.ceil(endPx / cellW));
    };

    const computeGrid = () => {
      const rect = canvas.getBoundingClientRect();
      cssW = rect.width;
      cssH = rect.height;
      if (cssW <= 0 || cssH <= 0) return;
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(cssW * dpr));
      canvas.height = Math.max(1, Math.round(cssH * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      // font size derived proportionally from the strip's own measured
      // height, never a fixed px constant — keeps the mark compact rather
      // than turning into a coarse zoomed-in grid on a narrow nav.
      fontPx = Math.max(9, Math.min(14, Math.round(cssH * 0.62)));
      offscreen.font = `${fontPx}px var(--font-mono), "GeistMono", ui-monospace, monospace`;
      const m = offscreen.measureText("M");
      cellW = Math.max(7, m.width * 1.55);
      cellH = cssH;
      cols = Math.max(1, Math.floor(cssW / cellW));
      cellW = cssW / cols; // even division across the full strip width

      ctx.font = `${fontPx}px var(--font-mono), "GeistMono", ui-monospace, monospace`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      computeActiveRange();
    };

    const drawCell = (col: number, stackDepth: number, extraSeedBucket: number) => {
      const cx = col * cellW + cellW / 2;
      const cy = cellH / 2;
      for (let pass = 0; pass < stackDepth; pass++) {
        const seed = col * 977 + pass * 131 + extraSeedBucket * 31;
        const glyph = glyphFor(seed);
        const dx = jitterFor(seed);
        const dy = jitterFor(seed + 1);
        ctx.fillStyle = pass % 2 === 0 ? fg : muted;
        ctx.globalAlpha = 0.3 - pass * 0.05;
        ctx.fillText(glyph, cx + dx, cy + dy);
      }
      ctx.globalAlpha = 1;
    };

    const draw = (nowMs: number, sweepTOverride?: number) => {
      if (cols <= 0) return;
      ctx.clearRect(0, 0, cssW, cssH);
      const sweepT = sweepTOverride ?? triangle((nowMs % SWEEP_PERIOD_MS) / SWEEP_PERIOD_MS);
      const sweepX = sweepT * cssW;
      // a coarse time bucket, not per-frame, so a re-struck cell holds its
      // freshly-picked glyph for a beat instead of flickering every 16ms
      const bucket = Math.floor(nowMs / 420);

      for (let c = 0; c < cols; c++) {
        const isActive = c >= activeStart && c < activeEnd;
        let depth = isActive
          ? ACTIVE_STACK
          : BASE_STACK_MIN + (hash32(c) % 2 === 0 ? 0 : BASE_STACK_MAX - BASE_STACK_MIN);

        const cellCx = c * cellW + cellW / 2;
        const dist = Math.abs(cellCx - sweepX);
        const kernel = Math.exp(-(dist * dist) / (2 * SWEEP_SIGMA * SWEEP_SIGMA));
        const restruck = kernel > 0.12;
        if (restruck) depth = Math.min(MAX_STACK, depth + 1);

        drawCell(c, depth, restruck ? bucket : c);
      }
    };

    const loop = (ts: number) => {
      if (disposed || document.hidden) return;
      draw(ts);
      raf = requestAnimationFrame(loop);
    };

    const onVis = () => {
      if (!document.hidden && !reduced && !disposed) raf = requestAnimationFrame(loop);
    };
    document.addEventListener("visibilitychange", onVis);

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const ro = new ResizeObserver(() => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        computeGrid();
        if (reduced) draw(0, STATIC_SWEEP_T);
      }, 100);
    });
    ro.observe(strip);

    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) draw(0, STATIC_SWEEP_T);
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    document.fonts.ready.then(() => {
      if (disposed) return;
      computeGrid();
      if (reduced) {
        draw(0, STATIC_SWEEP_T);
      } else {
        raf = requestAnimationFrame(loop);
      }
    });

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      ro.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [links]);

  return (
    <nav
      ref={navRef}
      aria-label="Primary"
      className={`relative w-full border-b border-border bg-background ${className}`}
    >
      <div className="mx-auto flex w-full max-w-6xl items-center justify-between px-6 pt-4">
        <a
          href="#top"
          className="shrink-0 rounded-sm font-mono text-[15px] font-semibold tracking-tight text-foreground transition-colors duration-150 hover:text-ns-accent focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ns-accent"
        >
          {wordmark}
        </a>
        <ul className="flex items-center gap-7">
          {links.map((link) => (
            <li key={link.href}>
              <a
                ref={(el) => {
                  if (el) linkRefs.current.set(link.href, el);
                  else linkRefs.current.delete(link.href);
                }}
                href={link.href}
                aria-current={link.current ? "page" : undefined}
                className={`rounded-sm text-sm transition-colors duration-150 hover:text-foreground focus-visible:text-foreground focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ns-accent ${
                  link.current ? "text-foreground" : "text-ns-muted"
                }`}
              >
                {link.label}
              </a>
            </li>
          ))}
        </ul>
      </div>

      {/* decorative overstrike strip — a ruled typed line beneath the real
          links, aria-hidden. It illustrates which item is current (deepest
          stack) and that the strip is alive at rest (the re-strike sweep);
          it never carries navigation semantics of its own. */}
      <div ref={stripRef} aria-hidden="true" className="relative mx-auto mt-2 h-5 w-full max-w-6xl px-6">
        <canvas ref={canvasRef} className="block h-full w-full" />
      </div>
    </nav>
  );
}

"use client";

import { useEffect, useId, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// NavSiteCondense — a full-width top nav with the mechanics an actual site
// needs and this registry didn't have yet: real scroll state (a plain
// threshold class-swap, deliberately subordinate — nav-condense-rail already
// owns the continuous, measured density transition and header-scroll-pill
// already owns the silhouette morph into a pill; this component's job is
// everything neither of those ships), a menu trigger that is present at
// every width (not hidden behind a responsive breakpoint that would make it
// unreachable at some viewport sizes), and a mobile sheet built on the
// native <dialog> element for a free focus trap, Escape-to-close and
// top-layer stacking.
// ---------------------------------------------------------------------------

export interface NavLinkItem {
  label: string;
  href: string;
}

export interface NavSiteCondenseProps {
  /** wordmark / brand text */
  brand?: string;
  /** nav links, in order */
  links: NavLinkItem[];
  /** px of scrollY past which the bar condenses. default 24 */
  condenseAt?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function NavSiteCondense({
  brand = "ns-ui",
  links,
  condenseAt = 24,
  className = "",
}: NavSiteCondenseProps) {
  const [condensed, setCondensed] = useState(false);
  const [sheetOpen, setSheetOpen] = useState(false);

  const dialogRef = useRef<HTMLDialogElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const dialogId = useId();
  const sheetTitleId = useId();

  // -- scroll condense: a plain threshold, not a continuous interpolation --
  useEffect(() => {
    let ticking = false;
    const evaluate = () => {
      ticking = false;
      setCondensed(window.scrollY > condenseAt);
    };
    const onScroll = () => {
      if (ticking) return;
      ticking = true;
      requestAnimationFrame(evaluate);
    };
    evaluate(); // honest initial read: the page may load already scrolled
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, [condenseAt]);

  // -- sheet: native <dialog> drives the trap, Escape and top layer --------
  useEffect(() => {
    const dlg = dialogRef.current;
    if (!dlg) return;

    if (sheetOpen && !dlg.open) dlg.showModal();
    if (!sheetOpen && dlg.open) dlg.close();

    const onCancel = (e: Event) => {
      // native Escape handling; just keep our state in sync
      e.preventDefault();
      setSheetOpen(false);
    };
    const onClose = () => setSheetOpen(false);
    const onBackdrop = (e: MouseEvent) => {
      if (e.target === dlg) setSheetOpen(false);
    };
    dlg.addEventListener("cancel", onCancel);
    dlg.addEventListener("close", onClose);
    dlg.addEventListener("click", onBackdrop);
    return () => {
      dlg.removeEventListener("cancel", onCancel);
      dlg.removeEventListener("close", onClose);
      dlg.removeEventListener("click", onBackdrop);
    };
  }, [sheetOpen]);

  const closeSheet = () => setSheetOpen(false);

  return (
    <>
      <header
        data-nav-site-condense
        className={`sticky top-0 z-40 border-b transition-[padding-block,box-shadow,background-color] duration-300 motion-reduce:transition-none ${
          condensed
            ? "border-border bg-background/95 py-2 shadow-sm backdrop-blur-sm"
            : "border-transparent bg-background py-5"
        } ${className}`}
      >
        <div className="mx-auto flex max-w-5xl items-center justify-between gap-4 px-4 sm:px-6">
          <a
            href="#top"
            className={`shrink-0 rounded-sm font-mono font-semibold tracking-tight text-foreground transition-[font-size,color] duration-300 hover:text-ns-accent focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ns-accent motion-reduce:transition-none ${
              condensed ? "text-sm" : "text-base"
            }`}
          >
            {brand}
          </a>

          <nav aria-label="Primary" className="hidden items-center gap-6 sm:flex">
            {links.map((link) => (
              <a
                key={link.href}
                href={link.href}
                className="rounded-sm text-sm text-ns-muted transition-colors hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ns-accent"
              >
                {link.label}
              </a>
            ))}
          </nav>

          {/* Present at every width on purpose: a trigger hidden behind a
              responsive breakpoint is unreachable at whatever viewport a
              test (or a user on an in-between width) actually has. Doubles
              as the full-sitemap entry point even on wide screens. */}
          <button
            type="button"
            ref={triggerRef}
