"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// NeonTubeStriation — a horizontal section divider rendered as the positive
// column of a lit glow-discharge (neon) tube.
//
// Real mechanic: in the positive column of a glow-discharge tube — the long
// uniform-looking stretch away from the electrodes — the plasma commonly
// self-organizes into moving striations, an ionization-wave instability that
// produces alternating brighter/dimmer bands drifting along the tube's axis
// at a roughly constant rate for a given gas fill. Separately, electrode
// sputtering slowly darkens the glass near both ends as cathode material
// erodes and deposits on the inside of the tube — the familiar blackened
// ends of an aged neon sign or fluorescent tube.
//
// Rendering is two passes over one capsule path: a blurred halo underlay for
// glow, then a crisp core clipped to the same pill shape and filled column
// by column, each column's luminance the product of a base "lit tube" level,
// the traveling striation modulation, an aperiodic low-frequency current
// flicker, and the end-zone sputtering ramp.
//
// The striation phase is computed directly from elapsed wall-clock time
// (phase = 2π · elapsedMs / 4000), never accumulated per rendered frame —
// that is what keeps the drift rate identical regardless of display refresh
// rate, the aliasing failure a real per-frame increment would risk at high
// Hz. The 4-7Hz current noise is resampled on its own aperiodic timer and
// eased toward, not read straight off the 60Hz paint loop either.
// ---------------------------------------------------------------------------

const WAVELENGTH_FRAC = 0.07; // striation wavelength, fraction of tube length
const DRIFT_PERIOD_MS = 4000; // one full wavelength of phase advance
const STRIATION_RATIO = 1.6; // bright:dark luminance ratio around base
const STRIATION_AMP = (STRIATION_RATIO - 1) / (STRIATION_RATIO + 1); // unclamped multiplicative amplitude

const NOISE_AMP = 0.03; // ±3% whole-tube current flicker
const NOISE_MIN_HZ = 4;
const NOISE_MAX_HZ = 7;
const NOISE_EASE = 0.15; // per-frame ease toward the current resampled target

const END_ZONE_FRAC = 0.06; // each electrode darkening zone, fraction of tube length
const END_DARK_MAX = 0.35; // cap on sputtering darkening
const END_DARK_TAU_S = 30; // 1 - exp(-t/30s) ramp

const BASE_MIX = 0.82; // baseline "lit tube" position between --background (0) and --foreground (1)
const MIN_MIX = 0.42; // floor so the dimmest striation trough stays visibly lit in light theme
const MAX_MIX = 0.99;

const STROKE_FRAC = 0.045; // tube diameter as a fraction of the container's height
const STROKE_MIN = 3;
const STROKE_MAX = 10;

const REDUCED_FREEZE_DEG = 130; // reduced-motion freeze phase
const REDUCED_FREEZE_S = 20; // seconds into the sputter ramp shown at freeze

const COL_STEP = 2; // px per rendered column — striations don't need per-pixel resolution

let swatchCtx: CanvasRenderingContext2D | null = null;
function resolveTokenRGB(token: string): [number, number, number] | null {
  if (!swatchCtx) {
    const c = document.createElement("canvas");
    c.width = 1;
    c.height = 1;
    swatchCtx = c.getContext("2d", { willReadFrequently: true });
  }
  const ctx = swatchCtx;
  if (!ctx) return null;
  ctx.clearRect(0, 0, 1, 1);
  ctx.fillStyle = token;
  ctx.fillRect(0, 0, 1, 1);
  const [r, g, b] = ctx.getImageData(0, 0, 1, 1).data;
  if (r === undefined || g === undefined || b === undefined) return null;
  return [r, g, b];
}

function mixRGB(bg: [number, number, number], fg: [number, number, number], t: number): string {
  const r = Math.round(bg[0] + (fg[0] - bg[0]) * t);
  const g = Math.round(bg[1] + (fg[1] - bg[1]) * t);
  const b = Math.round(bg[2] + (fg[2] - bg[2]) * t);
  return `rgb(${r}, ${g}, ${b})`;
}

function pillPath(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number) {
  const r = h / 2;
  ctx.beginPath();
  if (typeof ctx.roundRect === "function") {
    ctx.roundRect(x, y, w, h, r);
  } else {
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.arc(x + w - r, y + r, r, -Math.PI / 2, Math.PI / 2);
    ctx.lineTo(x + r, y + h);
    ctx.arc(x + r, y + r, r, Math.PI / 2, (3 * Math.PI) / 2);
  }
  ctx.closePath();
}

/** column luminance mix-fraction (0..1, background..foreground) at local
 * x (0..tubeLength) and elapsed real time t (ms), given the current sputter
 * ramp seconds and aperiodic noise offset already resolved for this frame */
function columnMix(x: number, tubeLength: number, phase: number, noise: number, rampT: number): number {
  const wavelength = Math.max(1, WAVELENGTH_FRAC * tubeLength);
  const striation = 1 + STRIATION_AMP * Math.sin((2 * Math.PI * x) / wavelength - phase);

  const zone = END_ZONE_FRAC * tubeLength;
  const ramp = 1 - Math.exp(-rampT / END_DARK_TAU_S);
  const leftFrac = zone > 0 ? Math.max(0, 1 - x / zone) : 0;
  const rightFrac = zone > 0 ? Math.max(0, 1 - (tubeLength - x) / zone) : 0;
  const sputter = END_DARK_MAX * ramp * Math.max(leftFrac, rightFrac);

  const raw = BASE_MIX * striation * (1 + noise) * (1 - sputter);
  return Math.min(MAX_MIX, Math.max(MIN_MIX, raw));
}

export interface NeonTubeStriationProps {
  /** divider height in px — the container's smaller dimension geometry derives from. Default 96. */
  height?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function NeonTubeStriation({ height = 96, className = "" }: NeonTubeStriationProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let disposed = false;
    let sized = false;
    let tokensRead = false;
    let width = 0;
    let strokeW = STROKE_MIN;
    let bgRGB: [number, number, number] | null = null;
    let fgRGB: [number, number, number] | null = null;

    // no fallback colour literals — if the tokens aren't resolvable yet,
    // tokensRead stays false and draw() simply doesn't paint this pass
    const readTokens = () => {
      const styles = getComputedStyle(document.documentElement);
      const bgTok = styles.getPropertyValue("--background").trim();
      const fgTok = styles.getPropertyValue("--foreground").trim();
      if (!bgTok || !fgTok) return;
      const bg = resolveTokenRGB(bgTok);
      const fg = resolveTokenRGB(fgTok);
      if (!bg || !fg) return;
      bgRGB = bg;
      fgRGB = fg;
      tokensRead = true;
    };

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      if (rect.width < 2 || rect.height < 2) {
        sized = false;
        return;
      }
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(rect.width * dpr));
      canvas.height = Math.max(1, Math.round(rect.height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      width = rect.width;
      strokeW = Math.min(STROKE_MAX, Math.max(STROKE_MIN, rect.height * STROKE_FRAC));
      sized = true;
      if (!tokensRead) readTokens();
    };

    // -- aperiodic 4-7Hz current noise: resampled on its own timer, eased
    // toward each frame — never a value read straight off the 60Hz loop ---
    let noiseTarget = 0;
    let noiseCurrent = 0;
    let noiseTimer: ReturnType<typeof setTimeout> | null = null;
    const scheduleNoise = () => {
      const hz = NOISE_MIN_HZ + Math.random() * (NOISE_MAX_HZ - NOISE_MIN_HZ);
      const ms = 1000 / hz;
      noiseTimer = setTimeout(() => {
        noiseTarget = (Math.random() * 2 - 1) * NOISE_AMP;
        scheduleNoise();
      }, ms);
    };

    const draw = (phase: number, rampT: number, noise: number) => {
      if (!sized || !tokensRead || !bgRGB || !fgRGB) return;
      const bg = bgRGB;
      const fg = fgRGB;
      const cy = height / 2 - strokeW / 2;

      ctx.clearRect(0, 0, width, height);

      // pass 1: blurred halo underlay
      ctx.save();
      ctx.filter = `blur(${Math.max(2, strokeW * 1.6)}px)`;
      ctx.globalAlpha = 0.4;
      pillPath(ctx, 0, cy, width, strokeW);
      ctx.fillStyle = mixRGB(bg, fg, BASE_MIX);
      ctx.fill();
      ctx.restore();

      // pass 2: crisp core, clipped to the tube, column by column
      ctx.save();
      pillPath(ctx, 0, cy, width, strokeW);
      ctx.clip();
      for (let x = 0; x < width; x += COL_STEP) {
        const mix = columnMix(x, width, phase, noise, rampT);
        ctx.fillStyle = mixRGB(bg, fg, mix);
        ctx.fillRect(x, cy, COL_STEP + 1, strokeW);
      }
      ctx.restore();
    };

    let raf = 0;
    let start = 0;

    const loop = (now: number) => {
      if (!visible) {
        raf = 0;
        return;
      }
      if (!start) start = now;
      const elapsedMs = now - start;
      noiseCurrent += (noiseTarget - noiseCurrent) * NOISE_EASE;
      // phase derived directly from elapsed real time, not per-frame steps —
      // the decoupling that keeps drift rate independent of display Hz
      const phase = (2 * Math.PI * elapsedMs) / DRIFT_PERIOD_MS;
      const rampT = elapsedMs / 1000;
      draw(phase, rampT, noiseCurrent);
      raf = requestAnimationFrame(loop);
    };

    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) drawReducedFrame();
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
        if (reduced) drawReducedFrame();
      }, 150);
    };
    const ro = new ResizeObserver(onResize);
    ro.observe(canvas);

    let visible = true;
    const io = new IntersectionObserver((entries) => {
      const wasVisible = visible;
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && !wasVisible && !reduced && sized && !raf) {
        raf = requestAnimationFrame(loop);
      }
    });
    io.observe(canvas);

    const onVis = () => {
      cancelAnimationFrame(raf);
      raf = 0;
      if (!document.hidden && visible && !reduced && sized) {
        raf = requestAnimationFrame(loop);
      }
    };
    document.addEventListener("visibilitychange", onVis);

    const drawReducedFrame = () => {
      // freeze at striation phase 130° into the cycle — an asymmetric band
      // arrangement, more legible than the near-symmetric phase-0 frame —
      // with the sputter ramp partway in so both mechanics read at a glance
      const freezePhase = (REDUCED_FREEZE_DEG / 360) * 2 * Math.PI;
      draw(freezePhase, REDUCED_FREEZE_S, 0);
    };

    document.fonts.ready.then(() => {
      if (disposed) return;
      readTokens();
      resize();

      if (reduced) {
        drawReducedFrame();
        return;
      }

      scheduleNoise();
      raf = requestAnimationFrame(loop);
    });

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      raf = 0;
      if (resizeTimer) clearTimeout(resizeTimer);
      if (noiseTimer) clearTimeout(noiseTimer);
      mo.disconnect();
      ro.disconnect();
      io.disconnect();
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [height]);

  return (
    <div role="separator" aria-orientation="horizontal" className={`ns-nts w-full ${className}`}>
      <canvas ref={canvasRef} aria-hidden="true" className="block w-full" style={{ height }} />
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// PacketTrace — a small fixed node/edge network (9 nodes, 13 hairline edges,
// deliberately irregular positions) with data pulses that travel edge-to-edge
// via random walks, easing along each segment with a short fading tail.
// Everything on the animation hot path (pulse head/tail positions) is a
// direct-DOM write of `cx`/`cy`/`opacity` on pre-mounted SVG circle refs
// inside a rAF loop — no React state per frame. Hovering (or focusing) a
// node is React state, since it only changes 9 edges' stroke + one node's
// radius, cheap enough to re-render.
//
// `state` drives traffic shape, not just a cosmetic tint:
//   - idle: sparse ambient pulses (~3 concurrent), slow spawn.
//   - active: dense traffic (~10 concurrent), fast spawn.
//   - error: every new pulse takes the shortest path to a fixed hub node
//     (the highest-degree node) and, on arrival, PARKS there instead of
//     despawning — pulses stack visually above the node (newest on top,
//     oldest evicted once the stack exceeds its cap) while the node itself
//     blinks --error via a CSS keyframe (not JS) for as long as `state`
//     stays "error". Switching away from "error" clears the queue.
//
// Reduced motion drops the whole rAF layer: no traveling pulses at all.
// Instead each edge's stroke-width is set from a fixed per-edge weight
// table (the network's inherent "which routes matter more" shape), so the
// static picture still communicates route frequency.
// ---------------------------------------------------------------------------

export type PacketTraceState = "idle" | "active" | "error";

export interface PacketTraceProps {
  /** Traffic pattern. Default "idle". */
  state?: PacketTraceState;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const VIEW_W = 320;
const VIEW_H = 180;

interface Node {
  x: number;
  y: number;
}

// Deliberately irregular — hand-placed, not a grid.
const NODES: Node[] = [
  { x: 38, y: 92 },
  { x: 98, y: 36 },
  { x: 92, y: 152 },
  { x: 163, y: 55 },
  { x: 156, y: 124 },
  { x: 228, y: 26 },
  { x: 222, y: 93 },
  { x: 230, y: 146 },
  { x: 282, y: 102 },
];

// Undirected edges; several cycles so a random walk actually branches.
const EDGES: [number, number][] = [
  [0, 1],
  [0, 2],
  [1, 3],
  [2, 3],
  [2, 4],
  [3, 5],
  [3, 6],
  [4, 6],
  [4, 7],
  [5, 6],
  [6, 7],
  [6, 8],
  [7, 8],
];

// Fixed per-edge traffic weight for the reduced-motion static picture —
// edges touching the hub (node 6) run heavier than peripheral spurs.
const EDGE_WEIGHT: number[] = EDGES.map(([a, b]) => (a === 6 || b === 6 ? 2.4 : a === 3 || b === 3 ? 1.6 : 1));

// Node 6 is the highest-degree node (5 edges) — the natural congestion
// point, and where "error" traffic queues.
const ERROR_NODE = 6;

const ADJACENCY: number[][] = NODES.map(() => []);
EDGES.forEach(([a, b]) => {
  ADJACENCY[a].push(b);
  ADJACENCY[b].push(a);
});

function randomWalk(start: number, hops: number): number[] {
  const path = [start];
  let prev = -1;
  let cur = start;
  for (let i = 0; i < hops; i++) {
    const neighbors = ADJACENCY[cur];
    const candidates = neighbors.filter((n) => n !== prev);
    const pool = candidates.length > 0 ? candidates : neighbors;
    const next = pool[Math.floor(Math.random() * pool.length)]!;
    path.push(next);
    prev = cur;
    cur = next;
  }
  return path;
}

function bfsPath(start: number, target: number): number[] {
  if (start === target) return [start];
  const prev = new Array(NODES.length).fill(-1);
  const visited = new Array(NODES.length).fill(false);
  visited[start] = true;
  const queue = [start];
  while (queue.length) {
    const cur = queue.shift()!;
    if (cur === target) break;
    for (const n of ADJACENCY[cur]) {
      if (!visited[n]) {
        visited[n] = true;
        prev[n] = cur;
        queue.push(n);
      }
    }
  }
  const path: number[] = [];
  let cur = target;
  while (cur !== -1) {
    path.unshift(cur);
    if (cur === start) break;
    cur = prev[cur];
  }
  return path.length > 1 ? path : [start, target];
}

function easeInOutCubic(t: number): number {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
}

interface Pulse {
  path: number[];
  hop: number;
  t: number;
  speedPerMs: number;
  queued: boolean;
}

const MAX_PULSES = 16;
const TAIL_COUNT = 3;
const QUEUE_CAP = 6;

const CONCURRENCY: Record<PacketTraceState, number> = { idle: 3, active: 10, error: 4 };
const SPAWN_RANGE: Record<PacketTraceState, [number, number]> = {
  idle: [900, 1800],
  active: [150, 400],
  error: [400, 900],
};

export function PacketTrace({ state = "idle", className = "" }: PacketTraceProps) {
  const dotRefs = useRef<(SVGCircleElement | null)[][]>(
    Array.from({ length: MAX_PULSES }, () => Array(TAIL_COUNT + 1).fill(null))
  );
  const pulsesRef = useRef<(Pulse | null)[]>(Array(MAX_PULSES).fill(null));
  const queueOrderRef = useRef<number[]>([]);
  const nextSpawnAtRef = useRef(0);
  const visitCountsRef = useRef<number[]>(Array(NODES.length).fill(0));
  const stateRef = useRef<PacketTraceState>(state);

  const [reducedMotion, setReducedMotion] = useState(false);
  const [hoveredNode, setHoveredNode] = useState<number | null>(null);
  const [tick, setTick] = useState(0);
  const [announce, setAnnounce] = useState("");

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReducedMotion(mq.matches);
    const onChange = () => setReducedMotion(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  // Reset the simulation cleanly on every state transition.
  useEffect(() => {
    stateRef.current = state;
    pulsesRef.current = Array(MAX_PULSES).fill(null);
    queueOrderRef.current = [];
    nextSpawnAtRef.current = 0;
    for (const slot of dotRefs.current) {
      for (const el of slot) {
        if (el) el.style.opacity = "0";
      }
    }
    const text =
      state === "error"
        ? `Network error — packets queuing at node ${ERROR_NODE + 1}.`
        : state === "active"
          ? "Network active — dense traffic."
          : "Network idle.";
    setAnnounce(text);
  }, [state]);

  useEffect(() => {
    if (reducedMotion) return;
    let raf = 0;
    let last = performance.now();

    const setDot = (el: SVGCircleElement | null, x: number, y: number, opacity: number) => {
      if (!el) return;
      el.setAttribute("cx", String(x));
      el.setAttribute("cy", String(y));
      el.style.opacity = String(opacity);
    };

    const step = (now: number) => {
      const dt = now - last;
      last = now;
      const cur = stateRef.current;
      const pulses = pulsesRef.current;
      const concurrency = CONCURRENCY[cur];
      const [minSpawn, maxSpawn] = SPAWN_RANGE[cur];

      if (now >= nextSpawnAtRef.current) {
        const traveling = pulses.filter((p) => p && !p.queued).length;
        if (traveling < concurrency) {
          const slot = pulses.findIndex((p) => p === null);
          if (slot !== -1) {
            let path: number[];
            if (cur === "error") {
              let start = Math.floor(Math.random() * NODES.length);
              if (start === ERROR_NODE) start = (start + 1) % NODES.length;
              path = bfsPath(start, ERROR_NODE);
            } else {
              const start = Math.floor(Math.random() * NODES.length);
              path = randomWalk(start, 3 + Math.floor(Math.random() * 4));
            }
            const duration = 550 + Math.random() * 400;
            pulses[slot] = { path, hop: 0, t: 0, speedPerMs: 1 / duration, queued: false };
          }
        }
        nextSpawnAtRef.current = now + minSpawn + Math.random() * (maxSpawn - minSpawn);
      }

      for (let i = 0; i < pulses.length; i++) {
        const p = pulses[i];
        if (!p || p.queued) continue;
        p.t += p.speedPerMs * dt;
        if (p.t >= 1) {
          const arrivedIdx = p.hop + 1;
          const arrivedNode = p.path[arrivedIdx]!;
          visitCountsRef.current[arrivedNode]! += 1;
          if (arrivedIdx >= p.path.length - 1) {
            if (cur === "error" && arrivedNode === ERROR_NODE) {
              p.queued = true;
              p.t = 1;
              queueOrderRef.current.push(i);
              if (queueOrderRef.current.length > QUEUE_CAP) {
                const evict = queueOrderRef.current.shift()!;
                pulses[evict] = null;
              }
            } else {
              pulses[i] = null;
            }
          } else {
            p.hop = arrivedIdx;
            p.t = 0;
          }
        }
      }

      for (let i = 0; i < pulses.length; i++) {
        const p = pulses[i];
        const refs = dotRefs.current[i]!;
        if (!p) {
          for (const el of refs) if (el) el.style.opacity = "0";
          continue;
        }
        if (p.queued) {
          const qIdx = Math.max(0, queueOrderRef.current.indexOf(i));
          const node = NODES[ERROR_NODE]!;
          setDot(refs[0]!, node.x - 9, node.y - 12 - qIdx * 5, 1);
          for (let k = 1; k <= TAIL_COUNT; k++) if (refs[k]) refs[k]!.style.opacity = "0";
          continue;
        }
        const a = NODES[p.path[p.hop]!]!;
        const b = NODES[p.path[p.hop + 1]!]!;
        const eased = easeInOutCubic(p.t);
        setDot(refs[0]!, a.x + (b.x - a.x) * eased, a.y + (b.y - a.y) * eased, 1);
        for (let k = 1; k <= TAIL_COUNT; k++) {
          const tt = Math.max(0, eased - k * 0.14);
          const op = tt > 0 || eased > 0 ? Math.max(0.1, 1 - k * 0.3) : 0;
          setDot(refs[k]!, a.x + (b.x - a.x) * tt, a.y + (b.y - a.y) * tt, op);
        }
      }

      raf = requestAnimationFrame(step);
    };

    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [reducedMotion]);

  // Live-refresh the tooltip's throughput count while a node is hovered/focused.
  useEffect(() => {
    if (hoveredNode === null) return;
    const id = window.setInterval(() => setTick((t) => t + 1), 500);
    return () => window.clearInterval(id);
  }, [hoveredNode]);

  const openNode = (idx: number) => setHoveredNode(idx);
  const closeNode = (idx: number) => setHoveredNode((cur) => (cur === idx ? null : cur));

  const hovered = hoveredNode !== null ? NODES[hoveredNode] : null;
  const throughput = hoveredNode !== null ? visitCountsRef.current[hoveredNode] : 0;
  void tick; // read for the interval's re-render side effect only

  return (
    <div className={`relative inline-block ${className}`}>
      <style>{CSS}</style>
      <span role="status" aria-live="polite" aria-atomic="true" className="sr-only">
        {announce}
      </span>

      <svg
        viewBox={`0 0 ${VIEW_W} ${VIEW_H}`}
        width="100%"
        style={{ maxWidth: VIEW_W }}
        focusable="false"
      >
        <g aria-hidden="true">
          {EDGES.map(([a, b], i) => {
            const na = NODES[a]!;
            const nb = NODES[b]!;
            const isHoverRoute = hoveredNode !== null && (a === hoveredNode || b === hoveredNode);
            const width = reducedMotion ? 0.6 + EDGE_WEIGHT[i]! * 0.7 : isHoverRoute ? 1.6 : 1;
            return (
              <line
                key={i}
                x1={na.x}
                y1={na.y}
                x2={nb.x}
                y2={nb.y}
                stroke={isHoverRoute ? "var(--foreground)" : "var(--border)"}
                strokeWidth={width}
                strokeLinecap="round"
              />
            );
          })}
        </g>

        {!reducedMotion && (
          <g aria-hidden="true">
            {Array.from({ length: MAX_PULSES }, (_, i) => (
              <g key={i}>
                {Array.from({ length: TAIL_COUNT + 1 }, (_, k) => (
                  <circle
                    key={k}
                    ref={(el) => {
                      dotRefs.current[i]![k] = el;
                    }}
                    r={k === 0 ? 2 : 1.4}
                    fill="var(--foreground)"
                    opacity={0}
                    cx={-10}
                    cy={-10}
                  />
                ))}
              </g>
            ))}
          </g>
        )}

        {reducedMotion && state === "error" && (
          <g aria-hidden="true">
            {[0, 1, 2].map((k) => (
              <circle
                key={k}
                cx={NODES[ERROR_NODE]!.x - 9}
                cy={NODES[ERROR_NODE]!.y - 12 - k * 5}
                r={1.4}
                fill="var(--foreground)"
                opacity={1 - k * 0.25}
              />
            ))}
          </g>
        )}

        {NODES.map((n, i) => {
          const isHovered = hoveredNode === i;
          const isError = state === "error" && i === ERROR_NODE;
          return (
            <circle
              key={i}
              role="button"
              tabIndex={0}
              aria-label={`Network node ${i + 1}${isError ? ", congested" : ""}`}
              aria-describedby={isHovered ? "network-packet-trace-tip" : undefined}
              cx={n.x}
              cy={n.y}
              r={isHovered ? 5.5 : 4}
              fill={isError ? "var(--error)" : "var(--foreground)"}
              className={isError ? "ns-pk-blink" : undefined}
              style={{ cursor: "pointer", outline: "none" }}
              onPointerEnter={() => openNode(i)}
              onPointerLeave={() => closeNode(i)}
              onFocus={() => openNode(i)}
              onBlur={() => closeNode(i)}
              onKeyDown={(e) => {
                if (e.key === "Escape") closeNode(i);
              }}
            />
          );
        })}

        {hoveredNode !== null && (
          <circle
            cx={NODES[hoveredNode]!.x}
            cy={NODES[hoveredNode]!.y}
            r={8}
            fill="none"
            stroke="var(--foreground)"
            strokeWidth={1}
            opacity={0.35}
            aria-hidden="true"
          />
        )}
      </svg>

      {hovered && (
        <div
          id="network-packet-trace-tip"
          role="tooltip"
          aria-live="off"
          className="pointer-events-none absolute z-10 -translate-x-1/2 -translate-y-full whitespace-nowrap rounded-[6px] border border-border bg-background px-2 py-1 font-mono text-[11px] text-foreground shadow-sm"
          style={{
            left: `${(hovered.x / VIEW_W) * 100}%`,
            top: `${(hovered.y / VIEW_H) * 100 - 4}%`,
          }}
        >
          Node {hoveredNode! + 1} — {throughput} routed
        </div>
      )}
    </div>
  );
}

const CSS = `
@keyframes ns-pk-blink { 0%, 100% { opacity: 1; } 50% { opacity: 0.35; } }
.ns-pk-blink { animation: ns-pk-blink 1.1s ease-in-out infinite; }
@media (prefers-reduced-motion: reduce) {
  .ns-pk-blink { animation: none; }
}
`;

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type FormEvent,
} from "react";

// ---------------------------------------------------------------------------
// NewsletterCadenceRail — a newsletter capture whose headline element is the
// publication's actual rhythm, drawn as a mono day-rail. Six weeks of days at
// a 1ch pitch: a dot per ordinary day, a `│` on every issue day (derived from
// one anchor date plus an interval, so the spacing IS the cadence and can be
// counted), and a `▮` caret on today. The same arithmetic that draws the rail
// writes the readout line beneath it, so the information is never trapped in
// the decoration — the rail is aria-hidden, the sentence is the accessible
// truth.
//
// The only ambient motion is today's caret, breathing on a pure CSS keyframe
// whose duration is jittered once at mount so two instances on a page never
// lock step. There is no rAF loop. Nothing responds to the pointer.
// ---------------------------------------------------------------------------

export interface NewsletterIssue {
  /** issue number, e.g. 48 */
  number: number;
  title: string;
  /** ISO date (YYYY-MM-DD) the issue shipped */
  dateISO: string;
  href?: string;
}

export interface NewsletterCadenceRailProps {
  /** any known past issue date, ISO (YYYY-MM-DD). Anchors the whole cadence. */
  anchorISO: string;
  /** days between issues. Default 14. */
  intervalDays?: number;
  /** recent issues, newest first — rendered as a short archive list */
  issues?: NewsletterIssue[];
  /** called with the entered email on submit */
  onSubmit?: (email: string) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const DAY_MS = 86_400_000;
const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const WEEKDAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const EMAIL_RE = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;

/** cells, and how many of them sit before today */
const NO_ISSUES: NewsletterIssue[] = [];
const WIDE = { cells: 42, past: 28 };
const NARROW = { cells: 28, past: 21 };

function startOfDay(d: Date): number {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
}

function parseISO(iso: string): number {
  const [y, m, d] = iso.split("-").map((n) => parseInt(n, 10));
  return new Date(y, (m || 1) - 1, d || 1).getTime();
}

function addDays(ms: number, n: number): number {
  const d = new Date(ms);
  return new Date(d.getFullYear(), d.getMonth(), d.getDate() + n).getTime();
}

function dayDiff(a: number, b: number): number {
  return Math.round((a - b) / DAY_MS);
}

/** `Jul 07` */
function shortDate(ms: number): string {
  const d = new Date(ms);
  return `${MONTHS[d.getMonth()]} ${String(d.getDate()).padStart(2, "0")}`;
}

/** `Tue 12 Aug` */
function longDate(ms: number): string {
  const d = new Date(ms);
  return `${WEEKDAYS[d.getDay()]} ${String(d.getDate()).padStart(2, "0")} ${MONTHS[d.getMonth()]}`;
}

function agoPhrase(days: number): string {
  if (days === 0) return "ships today";
  if (days === 1) return "shipped yesterday";
  return `shipped ${days} days ago`;
}

export function NewsletterCadenceRail({
  anchorISO,
  intervalDays = 14,
  issues = NO_ISSUES,
  onSubmit,
  className = "",
}: NewsletterCadenceRailProps) {
  const uid = useId();
  const interval = Math.max(1, Math.round(intervalDays));

  const railRef = useRef<HTMLDivElement | null>(null);
  const chRef = useRef<HTMLSpanElement | null>(null);
  const travelRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const [size, setSize] = useState<"wide" | "narrow" | "none">("wide");
  const [pulse, setPulse] = useState<string | null>(null);
  const [reduced, setReduced] = useState(false);
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState("");
  const [invalid, setInvalid] = useState(false);
  const [done, setDone] = useState(false);
  const [marker, setMarker] = useState<number | null>(null);
  // The server renders in its own timezone; a viewer east or west of it can be
  // on a different calendar day, which would slide the whole rail by one cell.
  // Seeded at render so SSR still emits a real rail, re-read once at mount so
  // the client's own midnight wins (identical value ⇒ React bails out).
  const [nowMs, setNowMs] = useState(() => startOfDay(new Date()));

  // ---- cadence arithmetic (one source for both the rail and the readout) ---
  const cadence = useMemo(() => {
    const today = nowMs;
    const anchor = parseISO(anchorISO);
    const elapsed = dayDiff(today, anchor);
    const offset = ((elapsed % interval) + interval) % interval;
    const last = addDays(today, -offset);
    const next = offset === 0 ? addDays(today, interval) : addDays(last, interval);

    // issue number of `last`, extrapolated from the newest archive entry
    let lastNumber: number | null = null;
    if (issues.length > 0) {
      const newest = issues.reduce((a, b) => (b.number > a.number ? b : a));
      const steps = Math.round(dayDiff(last, parseISO(newest.dateISO)) / interval);
      lastNumber = newest.number + steps;
    }
    return { today, anchor, last, next, lastNumber, sinceLast: offset };
  }, [anchorISO, interval, issues, nowMs]);

  const dims = size === "narrow" ? NARROW : WIDE;

  const cells = useMemo(() => {
    const out: { ms: number; issue: boolean; today: boolean }[] = [];
    for (let i = 0; i < dims.cells; i++) {
      const ms = addDays(cadence.today, i - dims.past);
      const delta = Math.floor(dayDiff(ms, cadence.anchor));
      out.push({
        ms,
        issue: ((delta % interval) + interval) % interval === 0,
        today: i === dims.past,
      });
    }
    return out;
  }, [cadence.today, cadence.anchor, dims, interval]);

  // The next issue can fall past the end of the rail (most days in narrow,
  // where the rail only reaches today+6). Clamp where the marker stops, but remember
  // that the stop is NOT the issue cell — nothing may flip to a destination
  // glyph on an ordinary day. The readout still carries the real date.
  const next = useMemo(() => {
    const raw = dims.past + dayDiff(cadence.next, cadence.today);
    return { idx: Math.min(raw, dims.cells - 1), onRail: raw <= dims.cells - 1 };
  }, [cadence.next, cadence.today, dims]);
  const nextIdx = next.idx;

  // ---- mount-time jitter: no two instances breathe in lockstep -------------
  useEffect(() => {
    setNowMs(startOfDay(new Date()));
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    if (!mq.matches) setPulse(`${(3.2 * (0.92 + Math.random() * 0.16)).toFixed(3)}s`);
    const onChange = () => {
      setReduced(mq.matches);
      setPulse(mq.matches ? null : `${(3.2 * (0.92 + Math.random() * 0.16)).toFixed(3)}s`);
    };
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  // ---- responsive: measure the rail box in ch -----------------------------
  const measure = useCallback(() => {
    const rail = railRef.current;
    const probe = chRef.current;
    if (!rail || !probe) return;
    const ch = probe.getBoundingClientRect().width / 10;
    if (!ch) return;
    const capacity = rail.getBoundingClientRect().width / ch;
    setSize(capacity >= WIDE.cells ? "wide" : capacity >= 20 ? "narrow" : "none");
  }, []);

  useEffect(() => {
    measure();
    const rail = railRef.current;
    if (!rail || typeof ResizeObserver === "undefined") return;
    const ro = new ResizeObserver(measure);
    ro.observe(rail);
    return () => ro.disconnect();
  }, [measure]);

  useEffect(() => () => {
    if (travelRef.current) clearInterval(travelRef.current);
  }, []);

  // ---- form ---------------------------------------------------------------
  function handleSubmit(e: FormEvent) {
    e.preventDefault();
    const value = email.trim();
    if (value.length === 0) {
      setInvalid(true);
      setStatus("Enter an email address");
      return;
    }
    if (!EMAIL_RE.test(value)) {
      setInvalid(true);
      setStatus("That address looks incomplete");
      return;
    }
    setInvalid(false);
    setDone(true);
    setStatus(`You're on the list — first issue lands ${longDate(cadence.next)}`);
    onSubmit?.(value);

    if (reduced) {
      setMarker(nextIdx);
      return;
    }
    let idx = dims.past;
    setMarker(idx);
    if (travelRef.current) clearInterval(travelRef.current);
    travelRef.current = setInterval(() => {
      idx += 1;
      setMarker(idx);
      if (idx >= nextIdx && travelRef.current) {
        clearInterval(travelRef.current);
        travelRef.current = null;
      }
    }, 90);
  }

  const arrived = marker !== null && marker >= nextIdx;

  const weekLabels: { idx: number; text: string }[] = [];
  for (let i = 0; i + 6 < dims.cells; i += 7) {
    weekLabels.push({ idx: i, text: shortDate(cells[i]?.ms ?? cadence.today).padEnd(7, " ") });
  }

  const readout = [
    cadence.lastNumber !== null
      ? `issue #${cadence.lastNumber} ${agoPhrase(cadence.sinceLast)}`
      : `last issue ${agoPhrase(cadence.sinceLast)}`,
    `next issue ${longDate(cadence.next)}`,
    `every ${interval} days`,
  ].join(" · ");

  const fieldId = `${uid}-email`;
  const statusId = `${uid}-status`;

  return (
    <div className={`ns-ncr relative w-full ${className}`}>
      <style>{CSS}</style>

      {/* ch probe — measured, never seen */}
      <span
        ref={chRef}
        aria-hidden="true"
        className="pointer-events-none absolute -z-10 select-none font-mono text-[13px] leading-none opacity-0"
      >
        0000000000
      </span>

      <div ref={railRef} className="w-full overflow-hidden">
        {size !== "none" && (
          <div aria-hidden="true" className="font-mono text-[13px] leading-[1.5] whitespace-pre">
            <div suppressHydrationWarning>
              {cells.map((cell, i) => {
                const isDest = arrived && next.onRail && i === nextIdx;
                const isMarker = marker !== null && marker === i && !isDest;
                let glyph = cell.issue ? "│" : "·";
                if (cell.today) glyph = "▮";
                if (isDest) glyph = "█";
                if (isMarker) glyph = "▸";

                let color = "var(--ns-muted)";
                let opacity = i < dims.past ? 0.35 : 0.6;
                if (cell.issue) {
                  color = "var(--foreground)";
                  opacity = 0.9;
                }
                if (cell.today || isMarker || isDest) {
                  color = "var(--ns-accent)";
                  opacity = 1;
                }

                return (
                  <span
                    key={i}
                    suppressHydrationWarning
                    className={cell.today && pulse && !isMarker ? "ns-ncr-caret" : undefined}
                    style={{
                      color,
                      opacity,
                      animationDuration: cell.today && pulse && !isMarker ? pulse : undefined,
                    }}
                  >
                    {glyph}
                  </span>
                );
              })}
            </div>
            <div
              suppressHydrationWarning
              className="tabular-nums text-ns-muted opacity-70 text-[13px] leading-[1.5]"
            >
              {weekLabels.map((w) => (
                <span key={w.idx} suppressHydrationWarning>
                  {w.text}
                </span>
              ))}
            </div>
          </div>
        )}
      </div>

      <p
        suppressHydrationWarning
        className="mt-3 font-mono text-xs tabular-nums text-ns-muted"
      >
        {readout}
      </p>

      {issues.length > 0 && (
        <ul className="mt-4 flex flex-col border-t border-border">
          {issues.slice(0, 3).map((issue) => (
            <li key={issue.number} className="border-b border-border">
              <a
                href={issue.href ?? "#"}
                className="flex items-baseline gap-3 py-2 text-sm text-foreground transition-colors duration-150 hover:text-ns-accent focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
              >
                <span className="font-mono text-xs tabular-nums text-ns-muted">
                  #{issue.number}
                </span>
                <span className="min-w-0 flex-1 truncate">{issue.title}</span>
                <span className="font-mono text-xs tabular-nums text-ns-muted">
                  {shortDate(parseISO(issue.dateISO))}
                </span>
              </a>
            </li>
          ))}
        </ul>
      )}

      {done ? (
        <p className="mt-5 font-mono text-sm text-foreground">
          <span className="text-ns-accent">▸</span> Subscribed.
        </p>
      ) : (
        <form onSubmit={handleSubmit} className="mt-5 flex flex-col gap-2" noValidate>
          <label
            htmlFor={fieldId}
            className="font-mono text-[11px] uppercase tracking-[0.18em] text-ns-muted"
          >
            Email
          </label>
          <div className="flex flex-col gap-2 sm:flex-row">
            <input
              id={fieldId}
              name="email"
              type="email"
              required
              autoComplete="email"
              value={email}
              placeholder="you@studio.com"
              aria-invalid={invalid || undefined}
              aria-describedby={statusId}
              onChange={(e) => setEmail(e.target.value)}
              className="min-w-0 flex-1 rounded-sm border border-border bg-background px-3 py-2 font-mono text-sm text-foreground transition-colors duration-150 placeholder:text-ns-muted/60 hover:border-ns-muted focus-visible:border-ns-accent focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent aria-[invalid=true]:border-[var(--error)]"
            />
            <button
              type="submit"
              className="shrink-0 rounded-sm border border-border px-4 py-2 font-mono text-xs uppercase tracking-[0.18em] text-foreground transition-colors duration-150 hover:border-ns-accent hover:text-ns-accent focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
            >
              Subscribe
            </button>
          </div>
        </form>
      )}

      <p
        id={statusId}
        role="status"
        aria-live="polite"
        className={`mt-2 min-h-[1.25rem] font-mono text-xs ${
          invalid ? "text-[var(--error)]" : "text-ns-muted"
        }`}
      >
        {status}
      </p>
    </div>
  );
}

const CSS = `
@keyframes ns-ncr-breathe { 0%, 100% { opacity: 0.55; } 50% { opacity: 1; } }
.ns-ncr-caret { animation-name: ns-ncr-breathe; animation-timing-function: ease-in-out; animation-iteration-count: infinite; }
@media (prefers-reduced-motion: reduce) { .ns-ncr-caret { animation: none; } }
`;

export default NewsletterCadenceRail;

"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";
import type { CSSProperties } from "react";

// ---------------------------------------------------------------------------
// HeaterRack — a cache diagnostics panel where every key-group is a
// storage-heater brick holding heat. One rule drives every brick: its
// temperature T is a pure function of elapsed time since its last hit,
// T(dt) = exp(-dt / tau) with tau = ttlMs/3000 seconds — chosen so a
// never-hit entry already reads visibly cold at roughly a third of its
// lifetime, early enough to PREDICT an eviction rather than report one. A
// hit resets a brick's clock (T snaps to 1); the "single fast charge ease"
// the brief asks for is realized as a plain ~220ms CSS opacity transition on
// each stipple dot, not a hand-rolled JS ramp — the same trick this
// registry already uses for its other scalar-driven surfaces (see
// button-cooldown-heat's --heat). Temperature never touches color: it is
// rendered purely as glyph-density STIPPLE (a fixed pool of deterministic,
// per-brick dot positions, radially ranked so a warming brick fills from its
// own center outward) quantized to a 5-level ramp — level = floor(T*5).
//
// Every visual property of a brick derives from ITS OWN T and nothing else.
// There is no shared clock, stagger, or wave across the rack: two bricks
// with identical hit histories always look identical, and a brick being hit
// over and over while its neighbors sit idle visibly flickers cold-hot
// against a static field — that contrast is the component's only
// diagnostic value, so nothing here is allowed to move the whole rack in
// unison.
//
// The rack's order is exactly the order of the `entries` prop and is NEVER
// re-sorted by temperature — re-sorting would make it impossible to track
// one brick's heat over time, which is the entire point of a diagnostics
// view. An id that drops out of `entries` (a real eviction) doesn't vanish;
// it plays a brief "leaving" contraction (max-width/opacity/margin easing
// to zero) and only then leaves the DOM, so the rack visibly contracts by
// exactly one slot instead of jump-cutting.
//
// Each brick is `role="listitem"` carrying the full diagnostic sentence in
// its own aria-label (key-group, hit count, a T/tau-derived eviction
// forecast) so a screen reader can walk the list without touching anything.
// The stipple SVG itself is aria-hidden. Anything beyond that summary — raw
// temperature, TTL, last-hit age — sits behind a real per-brick disclosure
// button (never a hover-only tooltip), which is also what keeps the
// component keyboard-reachable: a diagnostics grid otherwise has no natural
// "control" at all. Header stats (hit ratio, entry count, evictions/min)
// are live numbers; a separate sr-only aria-live=polite region announces
// only when `hitRatio` crosses the caller-supplied
// `hitRatioAlertThreshold`, never on every tick.
//
// DOM + SVG + CSS only, no canvas. Every ink value is --foreground over
// --ns-muted/--border/--background; --ns-accent appears solely on the
// disclosure button's focus ring.
// ---------------------------------------------------------------------------

export interface CacheEntryInput {
  /** stable identity for this cache entry/shard */
  id: string;
  /** the key-group label rendered on the brick, e.g. "user:profile" */
  keyGroup: string;
  /** this entry's TTL in ms — tau (the decay time-constant) is ttlMs / 3 */
  ttlMs: number;
  /** cumulative hit count, owned by the caller */
  hitCount: number;
  /** epoch ms of this entry's most recent hit (or creation, if never hit again) */
  lastHitAt: number;
}

export interface HeaterRackProps {
  /**
   * The tracked key-groups, in the fixed diagnostic order the rack renders
   * them — this order is never touched by the component. An id that drops
   * out of a later `entries` array is treated as a real eviction and
   * animates out; a new id is appended as a new brick.
   */
  entries: CacheEntryInput[];
  /** rolling hit ratio, 0..1, shown in the header. Caller computes this — the rack doesn't infer it from `entries`. */
  hitRatio: number;
  /** evictions observed in the last 60s, shown in the header. */
  evictionsPerMin: number;
  /** if set, the sr-only live region announces only when hitRatio crosses this value (either direction). */
  hitRatioAlertThreshold?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

interface BrickRow {
  id: string;
  entry: CacheEntryInput;
  leaving: boolean;
}

const POOL_SIZE = 16;
const EVICT_TH = 0.15; // T below this reads as "at risk now" in the forecast text
const POLL_MS_NORMAL = 220;
const POLL_MS_REDUCED = 1000;
const LEAVE_MS = 260;

function hashStr(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function mulberry32(seed: number) {
  let a = seed;
  return function () {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Deterministic, per-id stipple pool in normalized [0,1] space, ranked by
 *  distance from center so the reveal order (see `visibleCount`) fills a
 *  warming brick from its own core outward. Computed once per id and cached
 *  on a ref for the component's lifetime — positions never change. */
function stipplePool(id: string): { x: number; y: number }[] {
  const rng = mulberry32(hashStr(id));
  const pts = Array.from({ length: POOL_SIZE }, () => ({ x: rng(), y: rng() }));
  pts.sort((a, b) => Math.hypot(a.x - 0.5, a.y - 0.5) - Math.hypot(b.x - 0.5, b.y - 0.5));
  return pts;
}

function computeT(nowMs: number, entry: CacheEntryInput): number {
  const dt = Math.max(0, (nowMs - entry.lastHitAt) / 1000);
  if (dt === 0) return 1;
  const tau = Math.max(0.05, entry.ttlMs / 3000);
  return Math.exp(-dt / tau);
}

function levelFromT(t: number): number {
  return Math.min(4, Math.max(0, Math.floor(t * 5)));
}

function visibleCount(level: number): number {
  return Math.round((level / 4) * POOL_SIZE);
}

function fmtDuration(ms: number): string {
  const s = Math.max(0, Math.round(ms / 1000));
  if (s < 60) return `${s}s`;
  return `${Math.floor(s / 60)}m ${s % 60}s`;
}

function forecastText(t: number, entry: CacheEntryInput): string {
  if (t >= 0.94) return "just hit, full heat";
  if (t <= EVICT_TH) return "cold, at risk of eviction now";
  const tau = Math.max(0.05, entry.ttlMs / 3000);
  const secs = Math.max(1, Math.round(tau * Math.log(t / EVICT_TH)));
  return `cooling, likely evicted in ~${secs}s`;
}

function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

export function HeaterRack({
  entries,
  hitRatio,
  evictionsPerMin,
  hitRatioAlertThreshold,
  className = "",
}: HeaterRackProps) {
  const uid = useId();
  const reduced = useReducedMotion();

  // -- ordered rows: mirrors `entries` exactly while an id is present, keeps
  // a departed id around (marked `leaving`) just long enough to animate the
  // rack's contraction, and never reorders anything itself.
  const [rows, setRows] = useState<BrickRow[]>(() =>
    entries.map((entry) => ({ id: entry.id, entry, leaving: false }))
  );
  const leaveTimersRef = useRef<Map<string, number>>(new Map());

  useEffect(() => {
    const byId = new Map(entries.map((e) => [e.id, e]));
    setRows((prev) => {
      const next: BrickRow[] = [];
      const seen = new Set<string>();
      for (const row of prev) {
        seen.add(row.id);
        const live = byId.get(row.id);
        if (live) {
          next.push({ id: row.id, entry: live, leaving: false });
        } else if (row.leaving) {
          next.push(row); // already animating out
        } else {
          next.push({ ...row, leaving: true });
          const timer = window.setTimeout(() => {
            setRows((cur) => cur.filter((r) => r.id !== row.id));
            leaveTimersRef.current.delete(row.id);
          }, LEAVE_MS);
          const prior = leaveTimersRef.current.get(row.id);
          if (prior) window.clearTimeout(prior);
          leaveTimersRef.current.set(row.id, timer);
        }
      }
      for (const entry of entries) {
        if (!seen.has(entry.id)) next.push({ id: entry.id, entry, leaving: false });
      }
      return next;
    });
  }, [entries]);

  useEffect(() => {
    const timers = leaveTimersRef.current;
    return () => {
      timers.forEach((t) => window.clearTimeout(t));
      timers.clear();
    };
  }, []);

  // -- periodic recompute of T for every brick. T is a pure function of
  // elapsed time, so there's nothing to simulate frame-by-frame — this just
  // re-samples it, at 1Hz under reduced motion per the spec, faster
  // otherwise so the fast charge-ease reads smoothly.
  const [tick, setTick] = useState(0);
  const reducedRef = useRef(reduced);
  reducedRef.current = reduced;
  useEffect(() => {
    let id = 0;
    const schedule = () => {
      id = window.setTimeout(() => {
        setTick((t) => t + 1);
        schedule();
      }, reducedRef.current ? POLL_MS_REDUCED : POLL_MS_NORMAL);
    };
    schedule();
    return () => window.clearTimeout(id);
  }, []);

  const now = useMemo(() => Date.now(), [tick]);

  const poolCacheRef = useRef<Map<string, { x: number; y: number }[]>>(new Map());
  const poolFor = (id: string) => {
    let pool = poolCacheRef.current.get(id);
    if (!pool) {
      pool = stipplePool(id);
      poolCacheRef.current.set(id, pool);
    }
    return pool;
  };

  const [expanded, setExpanded] = useState<Set<string>>(() => new Set());
  const toggleExpanded = (id: string) => {
    setExpanded((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  // -- threshold-crossing announcement only, never a per-tick readout.
  const [announce, setAnnounce] = useState("");
  const prevAboveRef = useRef<boolean | null>(null);
  useEffect(() => {
    if (hitRatioAlertThreshold == null) return;
    const above = hitRatio >= hitRatioAlertThreshold;
    if (prevAboveRef.current !== null && prevAboveRef.current !== above) {
      const pct = Math.round(hitRatioAlertThreshold * 100);
      setAnnounce(
        above
          ? `Hit ratio recovered above ${pct}%.`
          : `Hit ratio dropped below ${pct}% — cache under pressure.`
      );
    }
    prevAboveRef.current = above;
  }, [hitRatio, hitRatioAlertThreshold]);

  return (
    <div className={`ns-hr-root ${className}`}>
      <style>{CSS}</style>

      <dl className="m-0 flex flex-wrap gap-x-6 gap-y-2 p-0" aria-label="Cache health">
        <div className="flex flex-col gap-0.5">
          <dt className="m-0 font-mono text-[10px] uppercase tracking-wider text-ns-muted">Hit ratio</dt>
          <dd className="m-0 font-mono text-sm font-semibold tabular-nums text-foreground">
            {Math.round(hitRatio * 100)}%
          </dd>
        </div>
        <div className="flex flex-col gap-0.5">
          <dt className="m-0 font-mono text-[10px] uppercase tracking-wider text-ns-muted">Entries</dt>
          <dd className="m-0 font-mono text-sm font-semibold tabular-nums text-foreground">{entries.length}</dd>
        </div>
        <div className="flex flex-col gap-0.5">
          <dt className="m-0 font-mono text-[10px] uppercase tracking-wider text-ns-muted">Evictions/min</dt>
          <dd className="m-0 font-mono text-sm font-semibold tabular-nums text-foreground">{evictionsPerMin}</dd>
        </div>
      </dl>

      <ul className="ns-hr-rack m-0 mt-3 flex flex-wrap p-0" style={{ listStyle: "none" }}>
        {rows.map((row, index) => {
          const t = row.leaving ? 0 : computeT(now, row.entry);
          const level = levelFromT(t);
          const shown = visibleCount(level);
          const pool = poolFor(row.id);
          const isExpanded = expanded.has(row.id);
          const detailId = `${uid}-detail-${row.id}`;
          const forecast = forecastText(t, row.entry);
          const hitNoun = row.entry.hitCount === 1 ? "hit" : "hits";
          const ariaLabel = `${row.entry.keyGroup}, ${row.entry.hitCount} ${hitNoun}, ${forecast}`;

          return (
            <li
              key={row.id}
              role="listitem"
              aria-label={ariaLabel}
              data-ns-brick-index={index}
              className={`ns-hr-brick ${row.leaving ? "ns-hr-brick-leaving" : ""}`}
              style={{ "--t": t.toFixed(3) } as CSSProperties}
            >
              <div className="ns-hr-stipple" aria-hidden="true">
                <svg viewBox="0 0 1 1" preserveAspectRatio="none" focusable="false">
                  {pool.map((p, k) => (
                    <circle
                      key={k}
                      cx={p.x}
                      cy={p.y}
                      r={0.055}
                      className="ns-hr-dot"
                      style={{ opacity: k < shown ? 1 : 0 }}
                    />
                  ))}
                </svg>
              </div>

              <div className="mt-1.5 flex items-baseline justify-between gap-1.5">
                <span className="truncate font-mono text-[10px] text-foreground">{row.entry.keyGroup}</span>
                <span className="shrink-0 font-mono text-[10px] tabular-nums text-ns-muted">
                  {row.entry.hitCount}
                </span>
              </div>

              <button
                type="button"
                data-ns-disclosure
                aria-expanded={isExpanded}
                aria-controls={detailId}
                onClick={() => toggleExpanded(row.id)}
                className="ns-hr-disclosure mt-1.5 flex w-full items-center justify-center rounded-[6px] border border-border py-0.5 text-[11px] leading-none text-ns-muted transition-colors duration-150 hover:border-foreground/30 hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
              >
                <span className="sr-only">
                  {isExpanded ? "Hide" : "Show"} details for {row.entry.keyGroup}
                </span>
                <span aria-hidden="true">{isExpanded ? "−" : "+"}</span>
              </button>

              {isExpanded ? (
                <dl
                  id={detailId}
                  data-ns-detail
                  className="mt-1.5 flex flex-col gap-0.5 border-t border-border pt-1.5"
                >
                  <div className="flex justify-between gap-2">
                    <dt className="m-0 font-mono text-[9px] text-ns-muted">Temp</dt>
                    <dd className="m-0 font-mono text-[9px] tabular-nums text-foreground">{Math.round(t * 100)}%</dd>
                  </div>
                  <div className="flex justify-between gap-2">
                    <dt className="m-0 font-mono text-[9px] text-ns-muted">TTL</dt>
                    <dd className="m-0 font-mono text-[9px] tabular-nums text-foreground">
                      {fmtDuration(row.entry.ttlMs)}
                    </dd>
                  </div>
                  <div className="flex justify-between gap-2">
                    <dt className="m-0 font-mono text-[9px] text-ns-muted">Last hit</dt>
                    <dd className="m-0 font-mono text-[9px] tabular-nums text-foreground">
                      {fmtDuration(now - row.entry.lastHitAt)} ago
                    </dd>
                  </div>
                  <div className="flex justify-between gap-2">
                    <dt className="m-0 font-mono text-[9px] text-ns-muted">Forecast</dt>
                    <dd className="m-0 text-right font-mono text-[9px] text-foreground">{forecast}</dd>
                  </div>
                </dl>
              ) : null}
            </li>
          );
        })}
      </ul>

      <span role="status" aria-live="polite" className="sr-only">
        {announce}
      </span>
    </div>
  );
}

const CSS = `
.ns-hr-brick {
  position: relative;
  box-sizing: border-box;
  width: 104px;
  max-width: 104px;
  margin: 0 8px 8px 0;
  padding: 8px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background-color: color-mix(in srgb, var(--background), var(--ns-muted) calc(var(--t, 0) * 7%));
  overflow: hidden;
  transition: max-width 260ms cubic-bezier(0.4,0,0.2,1), opacity 260ms ease-in, margin-right 260ms ease-in, padding-left 260ms ease-in, padding-right 260ms ease-in, border-width 260ms ease-in, background-color 220ms ease-out;
}
.ns-hr-brick-leaving {
  max-width: 0;
  width: 0;
  opacity: 0;
  margin-right: 0;
  padding-left: 0;
  padding-right: 0;
  border-left-width: 0;
  border-right-width: 0;
}
.ns-hr-stipple { width: 100%; height: 40px; }
.ns-hr-stipple svg { width: 100%; height: 100%; display: block; }
.ns-hr-dot { fill: var(--foreground); transition: opacity 220ms ease-out; }
@media (prefers-reduced-motion: reduce) {
  .ns-hr-brick { transition: none; }
  .ns-hr-dot { transition: none; }
}
`;

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// NomogramEdge — a two-input estimator built as a real paper nomogram, not a
// decorated pair of sliders. Three vertical ASCII scales (tick glyphs ─ ┬ on
// a │ spine): left and right carry draggable role=slider handles, the middle
// is read-only and sits at the exact horizontal midpoint. GEOMETRY: with a
// shared log modulus R = ln(leftMax/leftMin) and both outer scales anchored
// so their own max maps to frac 0 (top), frac(u) = ln(leftMax/u)/R and
// frac(v) = ln(rightMax/v)/R. Because the middle column is the true pixel
// midpoint between the two handles, the straight line's crossing there is
// ALWAYS (fracLeft+fracRight)/2 by the intercept theorem — so rendering the
// middle scale's own ticks at frac(w) = ln(wMax/w)/(2R), wMax = leftMax *
// rightMax, makes a straight SVG line between the handles land exactly on
// the middle scale's tick for w = u*v. No pixel measurement, no canvas: the
// crossing is computed analytically (result = leftValue*rightValue) and
// placed at that same halfway-average fraction, so the drawn line and the
// printed number are provably the same answer. R is taken from the LEFT
// domain only — the right scale (and therefore the middle scale, since it's
// the average) may span less than the full track when its own log-ratio is
// smaller than the left's, ending at a real "══" scale cap rather than
// filling the column. That's authentic nomography, not a bug: doubling the
// right value moves the crossing by ln(2)/(2R) same as doubling the left
// would, but a scale whose reachable domain covers fewer decades swings the
// SAME handle travel through a much bigger fraction of its own range, which
// is the actual sensitivity story this component tells. `mode="sum"` swaps
// the same machinery to linear scales/addition for non-multiplicative pairs.
// Handles are role=slider with arrow/page/home/end tick-stepping; drag is
// continuous and un-quantized, release snaps to the nearest tick with a
// spring-flavored CSS ease (skipped under prefers-reduced-motion, detected
// in JS so the transition can be fully suppressed rather than just shortened).
// The straightedge carries a small quadratic-bezier sag while a handle is
// down (control point offset from the true midpoint) and eases flat again on
// release — decorative only; the crossing computation never reads the path.
// DOM + inline SVG only, no canvas. --ns-accent appears nowhere but the
// grabbed handle and focus rings.
// ---------------------------------------------------------------------------

type Mode = "product" | "sum";
type Side = "left" | "right";
type Tick = { value: number; major: boolean };

const TRACK_H_DEFAULT = 480; // px, track column height — a pricing-hero instrument, not a form-row widget
const SAG = 3.2; // viewBox units, straightedge sag while a handle is down
// A handful of illustrative (fracLeft, fracRight) waypoints the crossing
// drifts through before anyone touches the component — spread across the
// domain so the sensitivity story (one side swinging the crossing more than
// the other) is visible without a single click. Permanently cancelled on the
// first real pointerdown/keydown (see interactedRef) and never started under
// reduced motion.
const IDLE_WAYPOINTS: [number, number][] = [
  [0.14, 0.82],
  [0.62, 0.26],
  [0.36, 0.58],
  [0.8, 0.12],
];
const IDLE_STEP_MS = 2600;
const IDLE_FIRST_DELAY_MS = 1100;
const ENTRY_FRAC = 0.5; // both handles start here on mount and spring out to their real reading
const ENTRANCE_MS = 640; // draw-in duration, same overshoot curve as the interactive snap

function clamp(v: number, lo: number, hi: number): number {
  return v < lo ? lo : v > hi ? hi : v;
}

function refSpanOf(mode: Mode, min: number, max: number): number {
  return mode === "product" ? Math.log(max / min) : max - min;
}

// frac 0 = anchorMax (top of column), frac grows downward as value falls.
function fracOf(mode: Mode, value: number, anchorMax: number, refSpan: number): number {
  if (mode === "product") {
    const v = value > 0 ? value : anchorMax * 1e-9;
    return Math.log(anchorMax / v) / refSpan;
  }
  return (anchorMax - value) / refSpan;
}

function valueOf(mode: Mode, frac: number, anchorMax: number, refSpan: number): number {
  return mode === "product" ? anchorMax * Math.exp(-frac * refSpan) : anchorMax - frac * refSpan;
}

function combine(mode: Mode, u: number, v: number): number {
  return mode === "product" ? u * v : u + v;
}

function buildLogTicks(min: number, max: number): Tick[] {
  const out: Tick[] = [];
  const k0 = Math.floor(Math.log10(min));
  const k1 = Math.ceil(Math.log10(max));
  for (let k = k0; k <= k1; k++) {
    for (const m of [1, 2, 5]) {
      const v = m * Math.pow(10, k);
      if (v >= min * 0.999 && v <= max * 1.001) out.push({ value: v, major: m === 1 });
    }
  }
  return out.sort((a, b) => a.value - b.value);
}

function niceLinearStep(range: number): number {
  const raw = range / 8;
  const mag = Math.pow(10, Math.floor(Math.log10(raw)));
  const norm = raw / mag;
  const nice = norm < 1.5 ? 1 : norm < 3 ? 2 : norm < 7 ? 5 : 10;
  return nice * mag;
}

function buildLinearTicks(min: number, max: number): Tick[] {
  const step = niceLinearStep(max - min) || 1;
  const out: Tick[] = [];
  const start = Math.ceil(min / step) * step;
  for (let v = start; v <= max + step * 1e-6; v += step) {
    out.push({ value: Number(v.toFixed(6)), major: Math.round(v / step) % 5 === 0 });
  }
  return out;
}

function buildTicks(mode: Mode, min: number, max: number): Tick[] {
  return mode === "product" ? buildLogTicks(min, max) : buildLinearTicks(min, max);
}

function fmtCompact(v: number): string {
  const abs = Math.abs(v);
  if (abs >= 1_000_000) return `${(v / 1_000_000).toFixed(v % 1_000_000 === 0 ? 0 : 1)}M`;
  if (abs >= 1000) return `${(v / 1000).toFixed(v % 1000 === 0 ? 0 : 1)}k`;
  if (abs > 0 && abs < 1) return v.toFixed(abs < 0.01 ? 3 : 2).replace(/0+$/, "").replace(/\.$/, "");
  return Number.isInteger(v) ? String(v) : v.toFixed(1);
}

function usePrefersReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

export interface NomogramEdgeProps {
  /** "product" (log scales, w = left*right) or "sum" (linear scales, w = left+right) */
  mode?: Mode;
  leftLabel?: string;
  rightLabel?: string;
  middleLabel?: string;
  leftMin?: number;
  leftMax?: number;
  rightMin?: number;
  rightMax?: number;
  defaultLeftValue?: number;
  defaultRightValue?: number;
  formatLeft?: (v: number) => string;
  formatRight?: (v: number) => string;
  formatResult?: (v: number) => string;
  onValuesChange?: (left: number, right: number, result: number) => void;
  /** Track column height in px. Default 480 — a full instrument, not a form-row control. */
  trackHeight?: number;
  /** Before any interaction, the crossing drifts through a few illustrative
   * value pairs on its own (off under prefers-reduced-motion, and cancelled
   * for good the moment a real drag or keystroke lands). Default true. */
  ambient?: boolean;
  className?: string;
}

export function NomogramEdge({
  mode = "product",
  leftLabel = "Requests / mo",
  rightLabel = "Price / request",
  middleLabel = "Monthly cost",
  leftMin = 100,
  leftMax = 100_000,
  rightMin = 0.01,
  rightMax = 1,
  defaultLeftValue = 100_000,
  defaultRightValue = 0.01,
  formatLeft = (v) => `${fmtCompact(v)} requests`,
  formatRight = (v) => `$${v.toFixed(2)}/request`,
  formatResult = (v) => (v >= 1000 ? `$${Math.round(v).toLocaleString()}/mo` : `$${v.toFixed(2)}/mo`),
  onValuesChange,
  trackHeight = TRACK_H_DEFAULT,
  ambient = true,
  className = "",
}: NomogramEdgeProps) {
  const reduced = usePrefersReducedMotion();

  const [leftValue, setLeftValue] = useState(() => clamp(defaultLeftValue, leftMin, leftMax));
  const [rightValue, setRightValue] = useState(() => clamp(defaultRightValue, rightMin, rightMax));
  const [dragging, setDragging] = useState<Side | null>(null);
  // flips (and stays flipped) the instant a real drag or keystroke lands —
  // ends the idle drift for good and switches the handle's `top` easing from
  // the slow ambient drift back to the snappy interactive spring.
  const [interacted, setInteracted] = useState(false);
  const interactedRef = useRef(false);
  const stepIndexRef = useRef(0);
  const markInteracted = useCallback(() => {
    if (interactedRef.current) return;
    interactedRef.current = true;
    setInteracted(true);
  }, []);
  // `entered` flips true one paint after mount so the very first frame draws
  // both handles at ENTRY_FRAC with no transition, then the flip animates
  // them out to their real reading on the same overshoot spring as an
  // interactive snap — the "drawn in" reveal. `settled` flips true once that
  // reveal has had time to finish, so the ambient idle ease (below) doesn't
  // start competing with it. Both resolve instantly under reduced motion.
  const [entered, setEntered] = useState(false);
  const [settled, setSettled] = useState(false);
  useEffect(() => {
    if (reduced) {
      setEntered(true);
      setSettled(true);
      return;
    }
    let raf2 = 0;
    const raf1 = requestAnimationFrame(() => {
      raf2 = requestAnimationFrame(() => setEntered(true));
    });
    return () => {
      cancelAnimationFrame(raf1);
      cancelAnimationFrame(raf2);
    };
  }, [reduced]);
  useEffect(() => {
    if (!entered || reduced) return;
    const t = setTimeout(() => setSettled(true), ENTRANCE_MS + 60);
    return () => clearTimeout(t);
  }, [entered, reduced]);
  const [liveText, setLiveText] = useState(
    () =>
      `${formatLeft(clamp(defaultLeftValue, leftMin, leftMax))} × ${formatRight(
        clamp(defaultRightValue, rightMin, rightMax)
      )} → ${formatResult(combine(mode, clamp(defaultLeftValue, leftMin, leftMax), clamp(defaultRightValue, rightMin, rightMax)))}`
  );

  const leftTrackRef = useRef<HTMLDivElement>(null);
  const rightTrackRef = useRef<HTMLDivElement>(null);
  const leftHandleRef = useRef<HTMLDivElement>(null);
  const rightHandleRef = useRef<HTMLDivElement>(null);
  // mirrors of the latest committed values, updated synchronously alongside
  // setState — pointerup can fire before a just-queued setState from the
  // final pointermove has landed, so the release-time snap reads these
  // refs (always current) rather than the possibly one-frame-stale state.
  const leftValueRef = useRef(leftValue);
  const rightValueRef = useRef(rightValue);
  const setLeft = (v: number) => {
    leftValueRef.current = v;
    setLeftValue(v);
  };
  const setRight = (v: number) => {
    rightValueRef.current = v;
    setRightValue(v);
  };

  const R = useMemo(() => refSpanOf(mode, leftMin, leftMax), [mode, leftMin, leftMax]);
  const rightSpanFrac = useMemo(
    () => refSpanOf(mode, rightMin, rightMax) / R,
    [mode, rightMin, rightMax, R]
  );
  const midSpanFrac = (1 + rightSpanFrac) / 2;
  const wMax = combine(mode, leftMax, rightMax);
  const wMin = combine(mode, leftMin, rightMin);

  const ticksLeft = useMemo(() => buildTicks(mode, leftMin, leftMax), [mode, leftMin, leftMax]);
  const ticksRight = useMemo(() => buildTicks(mode, rightMin, rightMax), [mode, rightMin, rightMax]);
  const ticksMid = useMemo(() => buildTicks(mode, wMin, wMax), [mode, wMin, wMax]);

  const fracLeft = fracOf(mode, leftValue, leftMax, R);
  const fracRight = fracOf(mode, rightValue, rightMax, R);
  const fracMid = (fracLeft + fracRight) / 2;
  const result = combine(mode, leftValue, rightValue);

  // visual-only positions: everything DRAWN (handles, line, crossing) reads
  // these, never the raw fracs directly, so the pre-`entered` first frame
  // paints at ENTRY_FRAC while `leftValue`/`rightValue` (and therefore every
  // number on screen) are already correct from the very first render.
  const renderFracLeft = entered ? fracLeft : ENTRY_FRAC;
  const renderFracRight = entered ? fracRight : ENTRY_FRAC;
  const renderFracMid = (renderFracLeft + renderFracRight) / 2;

  const updateFromClientY = useCallback(
    (side: Side, clientY: number) => {
      const trackEl = side === "left" ? leftTrackRef.current : rightTrackRef.current;
      if (!trackEl) return;
      const rect = trackEl.getBoundingClientRect();
      const frac = clamp((clientY - rect.top) / Math.max(1, rect.height), 0, 1);
      const anchorMax = side === "left" ? leftMax : rightMax;
      const min = side === "left" ? leftMin : rightMin;
      const max = side === "left" ? leftMax : rightMax;
      const v = clamp(valueOf(mode, frac, anchorMax, R), min, max);
      const nextLeft = side === "left" ? v : leftValueRef.current;
      const nextRight = side === "right" ? v : rightValueRef.current;
      if (side === "left") setLeft(v);
      else setRight(v);
      onValuesChange?.(nextLeft, nextRight, combine(mode, nextLeft, nextRight));
    },
    [mode, leftMin, leftMax, rightMin, rightMax, R, onValuesChange]
  );

  const commitValue = useCallback(
    (side: Side, v: number) => {
      const nextLeft = side === "left" ? v : leftValueRef.current;
      const nextRight = side === "right" ? v : rightValueRef.current;
      if (side === "left") setLeft(v);
      else setRight(v);
      const nextResult = combine(mode, nextLeft, nextRight);
      const joiner = mode === "product" ? "×" : "+";
      setLiveText(`${formatLeft(nextLeft)} ${joiner} ${formatRight(nextRight)} → ${formatResult(nextResult)}`);
      onValuesChange?.(nextLeft, nextRight, nextResult);
    },
    [mode, formatLeft, formatRight, formatResult, onValuesChange]
  );

  const nearestTickIndex = (ticks: Tick[], side: Side, current: number): number => {
    if (ticks.length === 0) return -1;
    const anchorMax = side === "left" ? leftMax : rightMax;
    const curFrac = fracOf(mode, current, anchorMax, R);
    let best = 0;
    let bestD = Infinity;
    ticks.forEach((t, i) => {
      const f = fracOf(mode, t.value, anchorMax, R);
      const d = Math.abs(f - curFrac);
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    });
    return best;
  };

  const snapToNearestTick = (side: Side) => {
    const ticks = side === "left" ? ticksLeft : ticksRight;
    const current = side === "left" ? leftValueRef.current : rightValueRef.current;
    const idx = nearestTickIndex(ticks, side, current);
    if (idx >= 0) commitValue(side, ticks[idx].value);
  };

  const onPointerDown = (side: Side) => (e: React.PointerEvent<HTMLDivElement>) => {
    e.preventDefault();
    markInteracted();
    const trackEl = side === "left" ? leftTrackRef.current : rightTrackRef.current;
    trackEl?.setPointerCapture(e.pointerId);
    (side === "left" ? leftHandleRef : rightHandleRef).current?.focus({ preventScroll: true });
    setDragging(side);
    updateFromClientY(side, e.clientY);
  };

  const onPointerMove = (side: Side) => (e: React.PointerEvent<HTMLDivElement>) => {
    if (dragging !== side) return;
    updateFromClientY(side, e.clientY);
  };

  const endDrag = (side: Side) => () => {
    if (dragging !== side) return;
    setDragging(null);
    snapToNearestTick(side);
  };

  const onKeyDown = (side: Side) => (e: React.KeyboardEvent) => {
    const ticks = side === "left" ? ticksLeft : ticksRight;
    if (ticks.length === 0) return;
    const current = side === "left" ? leftValueRef.current : rightValueRef.current;
    const idx = nearestTickIndex(ticks, side, current);
    const jump = mode === "product" ? 3 : 5;
    let next = idx;
    switch (e.key) {
      case "ArrowUp":
      case "ArrowRight":
        next = idx + 1;
        break;
      case "ArrowDown":
      case "ArrowLeft":
        next = idx - 1;
        break;
      case "PageUp":
        next = idx + jump;
        break;
      case "PageDown":
        next = idx - jump;
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = ticks.length - 1;
        break;
      default:
        return;
    }
    e.preventDefault();
    markInteracted();
    next = clamp(next, 0, ticks.length - 1);
    commitValue(side, ticks[next].value);
  };

  // Before anyone touches a handle, the crossing drifts through a few
  // illustrative waypoints on its own — this is what makes the resting frame
  // read as alive rather than a static instrument nobody has picked up.
  // Cancelled for good (interactedRef) the instant a real drag or keystroke
  // lands, whether from an actual visitor or the site's own autoplay driver
  // (both dispatch genuine pointerdown events onPointerDown already sees).
  useEffect(() => {
    if (!ambient || reduced) return;
    let cancelled = false;
    const step = () => {
      if (cancelled || interactedRef.current) return;
      const [fl, fr] = IDLE_WAYPOINTS[stepIndexRef.current % IDLE_WAYPOINTS.length];
      stepIndexRef.current += 1;
      const lv = clamp(valueOf(mode, fl, leftMax, R), leftMin, leftMax);
      const rv = clamp(valueOf(mode, fr, rightMax, R), rightMin, rightMax);
      setLeft(lv);
      setRight(rv);
      // no aria-live announce here and no `commitValue` — an autonomous
      // demo drift is not a user commit, and shouldn't read to a screen
      // reader as though someone chose these values.
      onValuesChange?.(lv, rv, combine(mode, lv, rv));
    };
    const first = setTimeout(step, IDLE_FIRST_DELAY_MS);
    const id = setInterval(step, IDLE_STEP_MS);
    return () => {
      cancelled = true;
      clearTimeout(first);
      clearInterval(id);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ambient, reduced, mode, leftMin, leftMax, rightMin, rightMax, R]);

  // Four motion phases, in the order a mount actually passes through them:
  // "none" (pre-entrance first paint, no transition at all), "entrance" (the
  // spring draw-in), "idle" (the slow ambient drift, once settled and still
  // untouched), "interactive" (the normal drag-release/keyboard snap). Same
  // phase drives the handle's `top`, the crossing's `top`, and the
  // straightedge path's `d` so the three never fall out of sync with
  // each other mid-transition.
  const motionPhase: "none" | "entrance" | "idle" | "interactive" = !entered
    ? "none"
    : !settled
      ? "entrance"
      : !interacted && ambient
        ? "idle"
        : "interactive";
  const posEase =
    motionPhase === "entrance"
      ? `${ENTRANCE_MS}ms cubic-bezier(0.34,1.56,0.64,1)`
      : motionPhase === "idle"
        ? "1600ms cubic-bezier(0.45,0,0.55,1)"
        : motionPhase === "interactive"
          ? "320ms cubic-bezier(0.34,1.56,0.64,1)"
          : null;

  const handleTransition = (side: Side) =>
    reduced
      ? "none"
      : dragging === side
        ? "background-color 150ms ease, border-color 150ms ease"
        : `${posEase ? `top ${posEase}, ` : ""}background-color 150ms ease, border-color 150ms ease`;

  const crossingTransition = reduced ? "none" : posEase ? `top ${posEase}` : "none";

  const pathTransition = reduced ? "none" : posEase ? `d ${posEase}` : "none";

  // straightedge: quadratic bezier whose control point sits at the true
  // midpoint x (50) and the average of the two endpoint y's — at sag=0 this
  // is mathematically identical to a straight line through both handles.
  const x1 = 100 / 6;
  const xm = 50;
  const x2 = 500 / 6;
  const y1 = renderFracLeft * 100;
  const y2 = renderFracRight * 100;
  const sag = dragging ? SAG : 0;
  const pathD = `M ${x1.toFixed(2)} ${y1.toFixed(2)} Q ${xm} ${((y1 + y2) / 2 + sag).toFixed(2)} ${x2.toFixed(2)} ${y2.toFixed(2)}`;

  const renderOuterTicks = (ticks: Tick[], side: Side, anchorMax: number) => (
    <>
      {ticks.map((t) => {
        const f = fracOf(mode, t.value, anchorMax, R);
        return (
          <div
            key={t.value}
            aria-hidden
            className="absolute left-1/2 -translate-y-1/2 select-none"
            style={{ top: `${f * 100}%` }}
          >
            <span className="font-mono text-sm leading-none text-ns-muted">{t.major ? "┬" : "─"}</span>
            {t.major ? (
              // mr-4/ml-4 (16px) clears the 16px handle's ~11.3px rotated
              // half-diagonal with margin to spare — at the old mr-1.5 (6px)
              // gap, a handle sitting at or near this tick's own value
              // visually swallowed the number it's supposed to label. `z-20`
              // plus its own `bg-background` chip is a second, size-independent
              // defense: even if a future resize shrinks that clearance again,
              // the label paints over the handle instead of the reverse.
              <span
                className={`absolute top-1/2 z-20 -translate-y-1/2 whitespace-nowrap font-mono text-xs tabular-nums text-ns-muted ${
                  side === "left" ? "right-full mr-4 text-right" : "left-full ml-4"
                }`}
              >
                <span className="rounded-sm bg-background px-0.5">{fmtCompact(t.value)}</span>
              </span>
            ) : null}
          </div>
        );
      })}
    </>
  );

  const renderMidTicks = () => (
    <>
      {ticksMid.map((t) => {
        const f = fracOf(mode, t.value, wMax, 2 * R);
        return (
          <span
            key={t.value}
            aria-hidden
            className="absolute left-1/2 -translate-x-1/2 -translate-y-1/2 select-none font-mono text-sm leading-none text-ns-muted"
            style={{ top: `${f * 100}%` }}
          >
            {t.major ? "┬" : "─"}
          </span>
        );
      })}
    </>
  );

  const renderSpine = (spanFrac: number) => (
    <>
      <div
        aria-hidden
        className="absolute left-1/2 top-0 w-px -translate-x-1/2 bg-border"
        style={{ height: `${clamp(spanFrac, 0, 1) * 100}%` }}
      />
      {spanFrac < 0.999 ? (
        <span
          aria-hidden
          className="absolute left-1/2 -translate-x-1/2 -translate-y-1/2 select-none font-mono text-xs leading-none text-ns-muted"
          style={{ top: `${clamp(spanFrac, 0, 1) * 100}%` }}
        >
          {"══"}
        </span>
      ) : null}
    </>
  );

  const renderHandle = (side: Side) => {
    const value = side === "left" ? leftValue : rightValue;
    const frac = side === "left" ? renderFracLeft : renderFracRight;
    const min = side === "left" ? leftMin : rightMin;
    const max = side === "left" ? leftMax : rightMax;
    const label = side === "left" ? leftLabel : rightLabel;
    const fmt = side === "left" ? formatLeft : formatRight;
    return (
      <div
        ref={side === "left" ? leftHandleRef : rightHandleRef}
        role="slider"
        tabIndex={0}
        aria-label={label}
        aria-orientation="vertical"
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={Number(value.toFixed(6))}
        aria-valuetext={`${fmt(value)} — estimated ${formatResult(result)}`}
        data-nomogram-handle={side}
        onKeyDown={onKeyDown(side)}
        className={`absolute left-1/2 z-10 h-4 w-4 -translate-x-1/2 -translate-y-1/2 rotate-45 cursor-grab rounded-sm border-2 outline-none focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background active:cursor-grabbing ${
          dragging === side ? "border-ns-accent bg-ns-accent" : "border-foreground bg-background"
        }`}
        style={{ top: `${frac * 100}%`, transition: handleTransition(side) }}
      />
    );
  };

  const renderTrack = (side: Side) => {
    const ticks = side === "left" ? ticksLeft : ticksRight;
    const anchorMax = side === "left" ? leftMax : rightMax;
    const spanFrac = side === "left" ? 1 : rightSpanFrac;
    return (
      <div
        ref={side === "left" ? leftTrackRef : rightTrackRef}
        data-nomogram-track={side}
        className="relative h-full touch-none select-none"
        onPointerDown={onPointerDown(side)}
        onPointerMove={onPointerMove(side)}
        onPointerUp={endDrag(side)}
        onPointerCancel={endDrag(side)}
        onLostPointerCapture={endDrag(side)}
      >
        {renderSpine(spanFrac)}
        {renderOuterTicks(ticks, side, anchorMax)}
        {renderHandle(side)}
      </div>
    );
  };

  return (
    <div className={`w-full max-w-3xl rounded-md border border-border bg-background p-7 font-mono ${className}`}>
      <div className="grid grid-cols-3 gap-3">
        <div className="flex flex-col items-start gap-1">
          <span className="text-[11px] uppercase tracking-[0.2em] text-ns-muted">{leftLabel}</span>
          <span className="text-xl font-semibold tabular-nums text-foreground">{formatLeft(leftValue)}</span>
        </div>
        <div className="flex flex-col items-center gap-1">
          <span className="text-[11px] uppercase tracking-[0.2em] text-ns-muted">{middleLabel}</span>
          <span className="text-2xl font-bold tabular-nums text-foreground">{formatResult(result)}</span>
        </div>
        <div className="flex flex-col items-end gap-1">
          <span className="text-[11px] uppercase tracking-[0.2em] text-ns-muted">{rightLabel}</span>
          <span className="text-xl font-semibold tabular-nums text-foreground">{formatRight(rightValue)}</span>
        </div>
      </div>

      <div className="relative mt-6" style={{ height: trackHeight }}>
        <svg
          aria-hidden
          className="pointer-events-none absolute inset-0 h-full w-full text-foreground"
          viewBox="0 0 100 100"
          preserveAspectRatio="none"
        >
          <path
            d={pathD}
            stroke="currentColor"
            strokeWidth={2.5}
            strokeLinecap="round"
            fill="none"
            vectorEffect="non-scaling-stroke"
            style={{ transition: pathTransition }}
          />
        </svg>

        <div className="grid h-full grid-cols-3 gap-0">
          {renderTrack("left")}
          <div className="relative h-full">
            {renderSpine(midSpanFrac)}
            {renderMidTicks()}
            <div
              aria-hidden
              className="absolute left-1/2 z-20 flex items-center -translate-y-1/2"
              style={{ top: `${renderFracMid * 100}%`, transition: crossingTransition }}
            >
              <span className="-translate-x-1/2 select-none font-mono text-3xl font-semibold leading-none text-foreground">
                {"╪"}
              </span>
              <span className="ml-1.5 whitespace-nowrap rounded-sm border border-border bg-background px-2.5 py-1 font-mono text-sm font-bold tabular-nums text-foreground">
                {formatResult(result)}
              </span>
            </div>
          </div>
          {renderTrack("right")}
        </div>
      </div>

      <p className="mt-4 font-mono text-xs text-ns-muted">
        drag or arrow-key either handle · the straightedge crosses the middle scale at the answer
      </p>
      <p aria-live="polite" className="sr-only">
        {liveText}
      </p>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useId, useRef, useState, type PointerEvent as ReactPointerEvent } from "react";

// ---------------------------------------------------------------------------
// ClapperBell — a notification bell whose clapper physically rings instead
// of a badge just incrementing. The swing is a real damped harmonic
// oscillator (angle'' = -k*angle - c*angle'), integrated with a rAF loop
// and written straight to two SVG group refs (clapper rotateZ, bell body
// rotateZ at a smaller opposite amplitude for the recoil) — never React
// state per frame, matching the hot-path rule. Every new arrival ADDS an
// impulse to the oscillator's velocity rather than starting a fresh
// animation, so a burst of arrivals reads as one cumulative, increasingly
// wild, then settling swing — not N discrete dings layered on top of each
// other. The rAF loop itself only runs while the system still has visible
// energy (|angle| or |velocity| above a small threshold), so an idle bell
// costs nothing.
//
// The badge increments the instant an arrival's impulse lands (not at a
// literal zero-crossing "strike", which would need much more physics to
// detect honestly) and gets a one-frame CSS scale squash retriggered via
// a forced reflow, so bursts still show a visible pulse per arrival even
// though they share one physical swing.
//
// Hover: pointer position over the bell button drives a small +/-2deg tilt
// toward the cursor (direct ref write, no React state). Click opens a
// non-modal anchored tray: a hand-rolled focus trap (Tab cycles within it,
// Escape closes and returns focus to the trigger, a pointerdown outside
// closes it too) rather than the native <dialog>, since a notification
// tray shouldn't dim or block the rest of the page the way a modal does.
// Opening instantly damps the oscillator to rest, marks every notification
// read, and drains the badge. sr-only live region announces "N new
// notifications" for a burst, throttled to avoid spamming.
//
// prefers-reduced-motion: no swing/recoil at all (the physics loop is
// skipped outright); the badge does a single opacity pulse per arrival
// instead of the scale squash.
// ---------------------------------------------------------------------------

export interface ClapperBellItem {
  id: string;
  message: string;
}

export interface ClapperBellProps {
  /** Append-only notification list; ids not seen on a previous render are treated as arrivals. */
  items: ClapperBellItem[];
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const K = 90; // spring stiffness
const C = 6.4; // damping
const IMPULSE = 10; // angular velocity added per arrival (deg/s-ish, integrated in arbitrary units)
const RECOIL_RATIO = 0.22; // bell body swings opposite the clapper, smaller
const REST_EPS = 0.05;
const MAX_ANGLE = 34;
const HOVER_TILT_DEG = 2;
const ANNOUNCE_THROTTLE_MS = 4000;
const FOCUSABLE = 'button, [href], input, [tabindex]:not([tabindex="-1"])';

export function ClapperBell({ items, className = "" }: ClapperBellProps) {
  const [open, setOpen] = useState(false);
  const [badgeCount, setBadgeCount] = useState(0);
  const [announceText, setAnnounceText] = useState("");
  const [tray, setTray] = useState<ClapperBellItem[]>([]);

  const reducedRef = useRef(false);
  const knownIdsRef = useRef<Set<string>>(new Set());
  const angleRef = useRef(0);
  const velRef = useRef(0);
  const rafRef = useRef<number | undefined>(undefined);
  const lastTsRef = useRef<number | undefined>(undefined);
  const clapperRef = useRef<SVGGElement | null>(null);
  const bodyRef = useRef<SVGGElement | null>(null);
  const badgeRef = useRef<HTMLSpanElement | null>(null);
  const buttonRef = useRef<HTMLButtonElement | null>(null);
  const trayRef = useRef<HTMLDivElement | null>(null);
  const pendingAnnounceRef = useRef(0);
  const announceTimerRef = useRef<number | undefined>(undefined);
  const titleId = useId();

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    reducedRef.current = mq.matches;
    const onMq = () => {
      reducedRef.current = mq.matches;
    };
    mq.addEventListener("change", onMq);
    return () => mq.removeEventListener("change", onMq);
  }, []);

  const applyPose = useCallback((angle: number) => {
    if (clapperRef.current) clapperRef.current.style.transform = `rotate(${angle}deg)`;
    if (bodyRef.current) bodyRef.current.style.transform = `rotate(${-angle * RECOIL_RATIO}deg)`;
  }, []);

  const tick = useCallback(
    (ts: number) => {
      const last = lastTsRef.current ?? ts;
      const dt = Math.min((ts - last) / 1000, 0.05);
      lastTsRef.current = ts;

      const a = angleRef.current;
      const v = velRef.current;
      const accel = -K * a - C * v;
      const nv = v + accel * dt;
      const na = a + nv * dt;
      angleRef.current = Math.max(-MAX_ANGLE, Math.min(MAX_ANGLE, na));
      velRef.current = nv;
      applyPose(angleRef.current);

      if (Math.abs(angleRef.current) < REST_EPS && Math.abs(velRef.current) < REST_EPS) {
        angleRef.current = 0;
        velRef.current = 0;
        applyPose(0);
        lastTsRef.current = undefined;
        rafRef.current = undefined;
        return;
      }
      rafRef.current = requestAnimationFrame(tick);
    },
    [applyPose]
  );

  const ensureLoop = useCallback(() => {
    if (rafRef.current === undefined) {
      rafRef.current = requestAnimationFrame(tick);
    }
  }, [tick]);

  const pulseBadge = useCallback(() => {
    const el = badgeRef.current;
    if (!el) return;
    el.classList.remove(reducedRef.current ? "ns-cb-badge-pulse-reduced" : "ns-cb-badge-pulse");
    void el.offsetWidth; // force reflow so the animation retriggers on repeat arrivals
    el.classList.add(reducedRef.current ? "ns-cb-badge-pulse-reduced" : "ns-cb-badge-pulse");
  }, []);

  const dampToRest = useCallback(() => {
    if (rafRef.current !== undefined) {
      cancelAnimationFrame(rafRef.current);
      rafRef.current = undefined;
    }
    lastTsRef.current = undefined;
    angleRef.current = 0;
    velRef.current = 0;
    applyPose(0);
  }, [applyPose]);

  // Detect arrivals: ids present now but not on the previous render.
  useEffect(() => {
    const prevKnown = knownIdsRef.current;
    const arrivals = items.filter((it) => !prevKnown.has(it.id));
    knownIdsRef.current = new Set(items.map((it) => it.id));
    if (arrivals.length === 0) return;

    setTray((t) => [...arrivals, ...t]);
    setBadgeCount((c) => c + arrivals.length);
    pulseBadge();

    if (!reducedRef.current) {
      velRef.current += IMPULSE * arrivals.length;
      ensureLoop();
    }

    pendingAnnounceRef.current += arrivals.length;
    window.clearTimeout(announceTimerRef.current);
    announceTimerRef.current = window.setTimeout(() => {
      const n = pendingAnnounceRef.current;
      pendingAnnounceRef.current = 0;
      setAnnounceText(`${n} new notification${n === 1 ? "" : "s"}`);
    }, ANNOUNCE_THROTTLE_MS);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [items]);

  useEffect(() => () => {
    if (rafRef.current !== undefined) cancelAnimationFrame(rafRef.current);
    window.clearTimeout(announceTimerRef.current);
  }, []);

  const openTray = () => {
    setOpen(true);
    dampToRest();
    setBadgeCount(0);
  };

  const closeTray = (focusTrigger: boolean) => {
    setOpen(false);
    if (focusTrigger) buttonRef.current?.focus();
  };

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        e.preventDefault();
        closeTray(true);
        return;
      }
      if (e.key !== "Tab" || !trayRef.current) return;
      const focusable = Array.from(trayRef.current.querySelectorAll<HTMLElement>(FOCUSABLE));
      if (focusable.length === 0) return;
      const first = focusable[0]!;
      const last = focusable[focusable.length - 1]!;
      if (e.shiftKey && document.activeElement === first) {
        e.preventDefault();
        last.focus();
      } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    };
    const onPointerDown = (e: PointerEvent) => {
      const t = e.target as Node;
      if (trayRef.current?.contains(t) || buttonRef.current?.contains(t)) return;
      closeTray(false);
    };
    document.addEventListener("keydown", onKey);
    document.addEventListener("pointerdown", onPointerDown, true);
    const focusable = trayRef.current?.querySelector<HTMLElement>(FOCUSABLE);
    focusable?.focus();
    return () => {
      document.removeEventListener("keydown", onKey);
      document.removeEventListener("pointerdown", onPointerDown, true);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  const onPointerMove = (e: ReactPointerEvent<HTMLButtonElement>) => {
    if (reducedRef.current || rafRef.current !== undefined) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const offset = (e.clientX - (rect.left + rect.width / 2)) / (rect.width / 2);
    // Clamp magnitude away from exactly 0 — a pointer landing dead-center
    // (as a synthetic/testing hover does) should still visibly tilt toward
    // whichever half it's nominally in, not cancel out to "no tilt at all".
    const sign = offset < 0 ? -1 : 1;
    const magnitude = Math.max(0.5, Math.min(1, Math.abs(offset)));
    const tilt = sign * magnitude * HOVER_TILT_DEG;
    if (bodyRef.current) bodyRef.current.style.transform = `rotate(${tilt}deg)`;
  };

  const onPointerLeave = () => {
    if (rafRef.current !== undefined) return;
    if (bodyRef.current) bodyRef.current.style.transform = "rotate(0deg)";
  };

  return (
    <div className={`ns-cb-root ${className}`}>
      <style>{CSS}</style>
      <span role="status" aria-live="polite" aria-atomic="true" className="sr-only">
        {announceText}
      </span>

      <button
        ref={buttonRef}
        type="button"
        aria-haspopup="true"
        aria-expanded={open}
        aria-controls={open ? titleId : undefined}
        aria-label={badgeCount > 0 ? `Notifications, ${badgeCount} unread` : "Notifications"}
        className="ns-cb-trigger"
        onClick={() => (open ? closeTray(false) : openTray())}
        onPointerMove={onPointerMove}
        onPointerLeave={onPointerLeave}
      >
        <svg width="26" height="26" viewBox="0 0 26 26" aria-hidden="true" focusable="false">
          <g ref={bodyRef} className="ns-cb-body" style={{ transformOrigin: "13px 4px" }}>
            <path
              d="M13 3.5c-3.6 0-6 2.8-6 6.6 0 5-1.8 6.9-1.8 6.9h15.6s-1.8-1.9-1.8-6.9c0-3.8-2.4-6.6-6-6.6Z"
              fill="none"
              stroke="var(--foreground)"
              strokeWidth="1.3"
              strokeLinejoin="round"
            />
            <path d="M10.4 19c.3 1.2 1.3 2 2.6 2s2.3-.8 2.6-2" fill="none" stroke="var(--foreground)" strokeWidth="1.3" strokeLinecap="round" />
          </g>
          <g ref={clapperRef} style={{ transformOrigin: "13px 11px" }}>
            <line x1="13" y1="11" x2="13" y2="16.5" stroke="var(--ns-muted)" strokeWidth="1.2" strokeLinecap="round" />
            <circle cx="13" cy="17.4" r="1.5" fill="var(--ns-muted)" />
          </g>
        </svg>
        {badgeCount > 0 && (
          <span ref={badgeRef} className="ns-cb-badge" aria-hidden="true">
            {badgeCount > 9 ? "9+" : badgeCount}
          </span>
        )}
      </button>

      {open && (
        <div
          ref={trayRef}
          id={titleId}
          role="dialog"
          aria-label="Notifications"
          className="ns-cb-tray"
        >
          {tray.length === 0 ? (
            <p className="ns-cb-empty">No notifications yet.</p>
          ) : (
            <ul className="ns-cb-list">
              {tray.map((n) => (
                <li key={n.id} className="ns-cb-row">
                  {n.message}
                </li>
              ))}
            </ul>
          )}
          <button type="button" className="ns-cb-close" onClick={() => closeTray(true)}>
            Close
          </button>
        </div>
      )}
    </div>
  );
}

