export default PunchFigure;

"use client";

import { useId, useMemo, useRef, useState } from "react";
import type { KeyboardEvent as ReactKeyboardEvent } from "react";

// ---------------------------------------------------------------------------
// PunchPatch — a role x permission matrix rendered as a Jacquard card where
// authority is asymmetric material. Granting a permission punches a clean
// circular hole through the card stock; revoking never un-punches — it pastes
// a visible patch over the hole instead, leaving the hole's rim peeking 1px
// around the patch and its torn corners permanent for the session. Re-granting
// punches straight through the existing patch (a smaller hole cut through its
// centre), so a cell that was ever revoked stays visibly distinct from one
// that was never touched, forever, regardless of its current state. Inherited
// grants render as sealed eyelets — solid rim + inner ring, non-interactive,
// with a tooltip naming the parent role. Dependencies (grant X requires Y)
// share one punch-bar motion across both cells instead of two animations run
// back to back. Pure DOM + SVG, tokens only, reduced motion swaps instantly.
// ---------------------------------------------------------------------------

export interface PunchPatchRole {
  id: string;
  name: string;
}

export interface PunchPatchPermission {
  id: string;
  name: string;
  /** id of another permission in the same set this one depends on; granting
   *  this one cascades a grant of the dependency first, if it isn't held. */
  requires?: string;
}

export interface PunchPatchGrant {
  roleId: string;
  permissionId: string;
}

export interface PunchPatchInherited extends PunchPatchGrant {
  /** name of the parent role this grant is inherited from */
  from: string;
}

export interface PunchPatchProps {
  /** accessible name for the whole matrix */
  label?: string;
  /** row headers */
  roles: PunchPatchRole[];
  /** column headers */
  permissions: PunchPatchPermission[];
  /** cells punched (granted) at mount */
  defaultGranted?: PunchPatchGrant[];
  /** cells with a punch-then-patch history at mount: currently off, previously granted */
  defaultRevoked?: PunchPatchGrant[];
  /** cells granted via role inheritance — rendered as sealed, non-interactive eyelets */
  inherited?: PunchPatchInherited[];
  /** fires with the current directly-held (non-inherited) grants after any toggle */
  onChange?: (grants: PunchPatchGrant[]) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

interface CellState {
  granted: boolean;
  /** sticky for the session once true: this cell has been revoked at least once */
  patched: boolean;
}

const key = (roleId: string, permId: string) => `${roleId}::${permId}`;

function useReducedMotion() {
  return useRef(
    typeof window !== "undefined" &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches,
  ).current;
}

function buildInitialCells(
  granted: PunchPatchGrant[],
  revoked: PunchPatchGrant[],
): Map<string, CellState> {
  const m = new Map<string, CellState>();
  for (const g of granted) m.set(key(g.roleId, g.permissionId), { granted: true, patched: false });
  for (const r of revoked) m.set(key(r.roleId, r.permissionId), { granted: false, patched: true });
  return m;
}

interface PunchBar {
  id: number;
  left: number;
  top: number;
  width: number;
}

export function PunchPatch({
  label = "Role permissions",
  roles,
  permissions,
  defaultGranted = [],
  defaultRevoked = [],
  inherited = [],
  onChange,
  className = "",
}: PunchPatchProps) {
  const reduced = useReducedMotion();
  const baseId = useId();
  const patchedDescId = `${baseId}-patched-desc`;

  const [cells, setCells] = useState<Map<string, CellState>>(() =>
    buildInitialCells(defaultGranted, defaultRevoked),
  );
  const [focusedR, setFocusedR] = useState(0);
  const [focusedP, setFocusedP] = useState(0);
  const [punchBar, setPunchBar] = useState<PunchBar | null>(null);

  const chadEverRef = useRef<Set<string>>(new Set());
  const gridWrapRef = useRef<HTMLDivElement>(null);
  const cellRefs = useRef<Map<string, HTMLButtonElement>>(new Map());
  const liveRef = useRef<HTMLDivElement>(null);
  const barIdRef = useRef(0);
  const barTimeoutRef = useRef<number | null>(null);

  const inheritedMap = useMemo(() => {
    const m = new Map<string, string>();
    for (const i of inherited) m.set(key(i.roleId, i.permissionId), i.from);
    return m;
  }, [inherited]);

  const permById = useMemo(() => {
    const m = new Map<string, PunchPatchPermission>();
    for (const p of permissions) m.set(p.id, p);
    return m;
  }, [permissions]);

  const announce = (text: string) => {
    if (liveRef.current) liveRef.current.textContent = text;
  };

  const emitChange = (next: Map<string, CellState>) => {
    if (!onChange) return;
    const out: PunchPatchGrant[] = [];
    for (const role of roles) {
      for (const perm of permissions) {
        if (next.get(key(role.id, perm.id))?.granted) {
          out.push({ roleId: role.id, permissionId: perm.id });
        }
      }
    }
    onChange(out);
  };

  const triggerPunchBar = (roleId: string, fromPermId: string, toPermId: string) => {
    if (reduced) return;
    const wrap = gridWrapRef.current;
    const fromEl = cellRefs.current.get(key(roleId, fromPermId));
    const toEl = cellRefs.current.get(key(roleId, toPermId));
    if (!wrap || !fromEl || !toEl) return;
    const wr = wrap.getBoundingClientRect();
    const fr = fromEl.getBoundingClientRect();
    const tr = toEl.getBoundingClientRect();
    const left = Math.min(fr.left, tr.left) - wr.left;
    const right = Math.max(fr.right, tr.right) - wr.left;
    if (barTimeoutRef.current) window.clearTimeout(barTimeoutRef.current);
    barIdRef.current += 1;
    setPunchBar({
      id: barIdRef.current,
      left,
      top: fr.top - wr.top + fr.height / 2 - 1.5,
      width: right - left,
    });
    barTimeoutRef.current = window.setTimeout(() => setPunchBar(null), 340);
  };

  // Reads `cells` from the render closure rather than a functional setState
  // updater on purpose: toggle only ever runs from a discrete click/keydown,
  // one at a time, each committed before the next can fire — so there's no
  // batching hazard here. That keeps onChange/announce/triggerPunchBar (each
  // itself a state update) out of the updater function, where React would
  // otherwise double-invoke them under StrictMode and warn about setState
  // during another component's render.
  const toggle = (roleId: string, roleName: string, permId: string) => {
    const k = key(roleId, permId);
    if (inheritedMap.has(k)) return;

    const cur = cells.get(k) ?? { granted: false, patched: false };
    const next = new Map(cells);
    const perm = permById.get(permId);
    const permName = perm?.name ?? permId;

    if (cur.granted) {
      next.set(k, { granted: false, patched: true });
      setCells(next);
      announce(`${permName} revoked for ${roleName}. Previously granted.`);
      emitChange(next);
      return;
    }

    next.set(k, { granted: true, patched: cur.patched });
    chadEverRef.current.add(k);

    let cascadeName: string | null = null;
    let cascadeReqId: string | null = null;
    const reqId = perm?.requires;
    if (reqId) {
      const reqKey = key(roleId, reqId);
      const reqCur = cells.get(reqKey) ?? { granted: false, patched: false };
      if (!reqCur.granted) {
        next.set(reqKey, { granted: true, patched: reqCur.patched });
        chadEverRef.current.add(reqKey);
        cascadeName = permById.get(reqId)?.name ?? reqId;
        cascadeReqId = reqId;
      }
    }

    setCells(next);
    if (cascadeReqId) triggerPunchBar(roleId, permId, cascadeReqId);
    announce(
      cascadeName
        ? `${permName} granted for ${roleName}. Also granted: ${cascadeName}.`
        : `${permName} granted for ${roleName}.`,
    );
    emitChange(next);
  };

  const colTemplate = `10rem repeat(${permissions.length}, minmax(3.25rem, 1fr))`;

  const moveFocus = (nr: number, np: number) => {
    const r = Math.min(Math.max(nr, 0), roles.length - 1);
    const p = Math.min(Math.max(np, 0), permissions.length - 1);
    setFocusedR(r);
    setFocusedP(p);
    cellRefs.current.get(key(roles[r].id, permissions[p].id))?.focus();
  };

  const onGridKeyDown = (e: ReactKeyboardEvent<HTMLDivElement>) => {
    switch (e.key) {
      case "ArrowRight":
        e.preventDefault();
        moveFocus(focusedR, focusedP + 1);
        return;
      case "ArrowLeft":
        e.preventDefault();
        moveFocus(focusedR, focusedP - 1);
        return;
      case "ArrowDown":
        e.preventDefault();
        moveFocus(focusedR + 1, focusedP);
        return;
      case "ArrowUp":
        e.preventDefault();
        moveFocus(focusedR - 1, focusedP);
        return;
      case "Home":
        e.preventDefault();
        moveFocus(focusedR, 0);
        return;
      case "End":
        e.preventDefault();
        moveFocus(focusedR, permissions.length - 1);
        return;
      default:
        return;
    }
  };

  return (
    <div className={`ns-pp-root w-full ${className}`}>
      <style>{`
        @keyframes ns-pp-patch-in {
          from { transform: translateX(7px); opacity: 0; }
          to { transform: translateX(0); opacity: 1; }
        }
        .ns-pp-patch-in { animation: ns-pp-patch-in 200ms cubic-bezier(0,0,0.2,1) both; }
        @keyframes ns-pp-chad {
          from { transform: translateY(0); opacity: 1; }
          to { transform: translateY(10px); opacity: 0; }
        }
        .ns-pp-chad { animation: ns-pp-chad 200ms cubic-bezier(0.4,0,1,1) both; }
        @keyframes ns-pp-bar {
          from { transform: scaleX(0); opacity: 0.9; }
          65% { opacity: 0.9; }
          to { transform: scaleX(1); opacity: 0; }
        }
        .ns-pp-bar { animation: ns-pp-bar 320ms cubic-bezier(0.16,1,0.3,1) both; transform-origin: left center; }
        @media (prefers-reduced-motion: reduce) {
          .ns-pp-patch-in, .ns-pp-chad, .ns-pp-bar { animation: none !important; }
        }
      `}</style>

      <p className="mb-2 font-mono text-xs tracking-widest text-ns-muted uppercase">{label}</p>

      <div className="w-full overflow-x-auto rounded-md border border-border">
        <div
          ref={gridWrapRef}
          role="grid"
          aria-label={label}
          onKeyDown={onGridKeyDown}
          className="relative min-w-max"
        >
          {punchBar && (
            <div
              key={punchBar.id}
              aria-hidden
              className="ns-pp-bar pointer-events-none absolute z-10 h-[3px] rounded-full bg-ns-accent/50"
              style={{ left: punchBar.left, top: punchBar.top, width: punchBar.width }}
            />
          )}

          <div role="row" className="grid border-b border-border" style={{ gridTemplateColumns: colTemplate }}>
            <div role="columnheader" className="border-r border-border">
              <span className="sr-only">Role</span>
            </div>
            {permissions.map((perm) => (
              <div
                key={perm.id}
                role="columnheader"
                className="border-r border-border px-2 py-2 text-center font-mono text-[10px] leading-tight tracking-wide text-ns-muted uppercase last:border-r-0"
              >
                {perm.name}
              </div>
            ))}
          </div>

          {roles.map((role, r) => (
            <div
              key={role.id}
              role="row"
              className="grid border-b border-border last:border-b-0"
              style={{ gridTemplateColumns: colTemplate }}
            >
              <div
                role="rowheader"
                className="flex items-center border-r border-border px-3 py-2 text-sm text-foreground"
              >
                {role.name}
              </div>
              {permissions.map((perm, p) => {
                const k = key(role.id, perm.id);
                const from = inheritedMap.get(k);
                const isInherited = from !== undefined;
                const cell = cells.get(k) ?? { granted: false, patched: false };
                const isTabbable = r === focusedR && p === focusedP;
                const tipId = `${baseId}-tip-${role.id}-${perm.id}`;
                const showChad = !reduced && cell.granted && chadEverRef.current.has(k);

                if (isInherited) {
                  return (
                    <div
                      key={perm.id}
                      role="gridcell"
                      className="border-r border-border last:border-r-0"
                    >
                      <button
                        ref={(el) => {
                          if (el) cellRefs.current.set(k, el);
                          else cellRefs.current.delete(k);
                        }}
                        type="button"
                        role="checkbox"
                        aria-checked="true"
                        aria-disabled="true"
                        aria-label={`${role.name}: ${perm.name}`}
                        aria-describedby={tipId}
                        className="group relative flex h-12 w-full cursor-default items-center justify-center focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ns-accent"
                        tabIndex={isTabbable ? 0 : -1}
                        onFocus={() => {
                          setFocusedR(r);
                          setFocusedP(p);
                        }}
                      >
                        <svg width={26} height={26} viewBox="0 0 40 40" aria-hidden className="shrink-0" style={{ pointerEvents: "none" }}>
                          <circle cx={20} cy={20} r={9} fill="var(--background)" stroke="var(--foreground)" strokeWidth={1.5} opacity={0.85} />
                          <circle cx={20} cy={20} r={3} fill="none" stroke="var(--foreground)" strokeWidth={1} opacity={0.5} />
                        </svg>
                        <span
                          id={tipId}
                          role="tooltip"
                          className="pointer-events-none absolute top-full left-1/2 z-20 mt-1 w-max max-w-[9rem] -translate-x-1/2 rounded-sm border border-border bg-background px-1.5 py-1 text-left text-[10px] leading-tight text-foreground opacity-0 shadow-sm transition-opacity duration-150 group-hover:opacity-100 group-focus-visible:opacity-100"
                        >
                          Inherited from {from}
                        </span>
                      </button>
                    </div>
                  );
                }

                const describedBy = !cell.granted && cell.patched ? patchedDescId : undefined;

                return (
                  <div
                    key={perm.id}
                    role="gridcell"
                    className="border-r border-border last:border-r-0"
                  >
                    <button
                      ref={(el) => {
                        if (el) cellRefs.current.set(k, el);
                        else cellRefs.current.delete(k);
                      }}
                      type="button"
                      role="checkbox"
                      aria-checked={cell.granted}
                      aria-label={`${role.name}: ${perm.name}`}
                      aria-describedby={describedBy}
                      data-pp-idx={r * permissions.length + p}
                      tabIndex={isTabbable ? 0 : -1}
                      onFocus={() => {
                        setFocusedR(r);
                        setFocusedP(p);
                      }}
                      onClick={() => toggle(role.id, role.name, perm.id)}
                      className="flex h-12 w-full items-center justify-center transition-colors duration-150 hover:bg-border/30 focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ns-accent"
                    >
                      <svg width={26} height={26} viewBox="0 0 40 40" aria-hidden className="shrink-0" style={{ pointerEvents: "none" }}>
                        <circle
                          cx={20}
                          cy={20}
                          r={10}
                          fill="none"
                          stroke="var(--foreground)"
                          strokeWidth={1}
                          strokeDasharray="2.5 3"
                          opacity={0.28}
                        />
                        {cell.patched && (
                          <g className={reduced ? undefined : "ns-pp-patch-in"}>
                            <rect x={12} y={12} width={18} height={18} rx={3} fill="var(--foreground)" opacity={0.22} />
                            <rect x={11} y={11} width={18} height={18} rx={3} fill="var(--ns-muted)" />
                            <path d="M12.5 16 L12.5 12 L16.5 12" fill="none" stroke="var(--foreground)" strokeWidth={1} strokeLinecap="round" opacity={0.4} />
                            <path d="M27.5 24 L27.5 28 L23.5 28" fill="none" stroke="var(--foreground)" strokeWidth={1} strokeLinecap="round" opacity={0.4} />
                          </g>
                        )}
                        <circle
                          data-pp-hole={cell.granted ? "" : undefined}
                          cx={20}
                          cy={20}
                          r={cell.patched ? 6 : 8}
                          fill="var(--background)"
                          // A hole cut in bare card stock is background-on-
                          // background: without an edge, a granted cell renders
                          // pixel-identical to an ungranted one at rest (the
                          // patched case reads only because the patch behind it
                          // is --ns-muted). The rim is what makes the punch a
                          // punch on every cell, not just the patched ones.
                          stroke="var(--foreground)"
                          strokeWidth={1.5}
                          style={{
                            transformBox: "fill-box",
                            transformOrigin: "center",
                            transform: cell.granted ? "scale(1)" : "scale(0)",
                            opacity: cell.granted ? 1 : 0,
                            transition: reduced
                              ? "none"
                              : "transform 160ms cubic-bezier(0.3,0.9,0.4,1), opacity 130ms linear",
                          }}
                        />
                        {showChad && (
                          <circle key="chad" className="ns-pp-chad" cx={20} cy={20} r={3} fill="var(--ns-muted)" />
                        )}
                      </svg>
                    </button>
                  </div>
                );
              })}
            </div>
          ))}
        </div>
      </div>

      <span id={patchedDescId} className="sr-only">
        Previously granted, later revoked.
      </span>
      <div ref={liveRef} role="status" aria-live="polite" className="sr-only" />
    </div>
  );
}

"use client";

// PawlClick — a card-triage queue whose progress is a literal ratchet. Below
// the flat (no-3D) card stack sits a horizontal SVG rack of sawtooth teeth
// and a pawl. Deciding a card (archive or keep) fires the card out with a
// spring, and the rack advances exactly one tooth-width under a fixed pawl
// with a hard-stop ease — zero overshoot, sharp settle, unmistakably a click
// that only goes one way. Undo is deliberately a different kind of gesture:
// the pawl rotates up ~20deg and holds — visibly disengaging the mechanism —
// before the rack is allowed to ease backward one tooth, slowly and with
// visible effort, and only then does the pawl drop again. Undo always plays
// the lift/hold/drop gesture on request (never a disabled dead end); it only
// additionally restores a card and eases the rack when there is something in
// history to restore.
//
// Cards are a listbox: the stack is role="listbox" with roving
// aria-activedescendant onto the top card (role="option"). Left/Right arrows
// or J/K triage (archive/keep), U or Cmd/Ctrl+Z undoes — every gesture also
// has an on-screen button, nothing requires drag. A polite aria-live region
// announces each outcome ("Archived. 6 remaining. Press U to undo."). The
// rack + pawl SVG is aria-hidden — purely decorative reinforcement of a
// state that's already fully described in text.
//
// Reduced motion: card exit becomes a fast plain fade, the rack steps
// instantly (no transition), and the pawl's lift/drop is an instant
// attribute flip with no rotation tween — semantics (and the aria-live
// announcements) are unchanged either way.
//
// Pure DOM/SVG/CSS, no canvas. Colors are CSS custom properties only:
// --foreground for ink/ the engaged tooth, --border for resting teeth and
// hairlines, --ns-muted for secondary text, --ns-accent for focus rings only.

import { useCallback, useEffect, useId, useMemo, useRef, useState } from "react";

export interface PawlClickCard {
  id: string;
  title: string;
  subtitle?: string;
  body?: string;
}

export interface PawlClickProps {
  /** Initial queue, top of stack first. Managed internally after mount. */
  cards: PawlClickCard[];
  /** Called with the card whenever it's archived. */
  onArchive?: (card: PawlClickCard) => void;
  /** Called with the card whenever it's kept. */
  onKeep?: (card: PawlClickCard) => void;
  /** Called with the card whenever an archive/keep is undone. */
  onUndo?: (card: PawlClickCard) => void;
  /** Called once the queue is fully drained. */
  onEmpty?: () => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

type Decision = "archived" | "kept";
type Phase = "idle" | "commit" | "undo-lift" | "undo-ease";

interface HistoryEntry {
  card: PawlClickCard;
  decision: Decision;
}

const TOOTH = 26; // px, tooth pitch
const RACK_PAD = 12; // px, left padding before the first tooth
const PAWL_X = RACK_PAD + 10; // px, fixed screen x the pawl tip engages at

const COMMIT_RACK_MS = 260; // hard-stop ease, zero overshoot
const COMMIT_EXIT_MS = 320; // card spring exit
const PAWL_FLEX_MS = 200; // brief flex-over-tooth on drop

const LIFT_MS = 240; // pawl rotates up and holds
const EASE_MS = 680; // slow, effortful rack ease backward
const EMPTY_HOLD_MS = 320; // lift-and-drop with nothing to undo

const RACK_EASE_FWD = "cubic-bezier(0.16, 1, 0.3, 1)"; // sharp settle, no overshoot
const RACK_EASE_BACK = "cubic-bezier(0.65, 0, 0.35, 1)"; // slow, labored
const CARD_EXIT_EASE = "cubic-bezier(0.34, 1.56, 0.64, 1)"; // spring-ish snap

function useReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

export function PawlClick({
  cards,
  onArchive,
  onKeep,
  onUndo,
  onEmpty,
  className = "",
}: PawlClickProps) {
  const uid = useId();
  const reducedMotion = useReducedMotion();

  const initialRef = useRef(cards);
  const totalRef = useRef(Math.max(1, cards.length));
  const teethCount = totalRef.current;

  const [queue, setQueue] = useState<PawlClickCard[]>(initialRef.current);
  const [history, setHistory] = useState<HistoryEntry[]>([]);
  const [notch, setNotch] = useState(0);
  const [phase, setPhase] = useState<Phase>("idle");
  const [exiting, setExiting] = useState<{ card: PawlClickCard; dir: "left" | "right" } | null>(
    null,
  );
  const [announcement, setAnnouncement] = useState("");
  const [busy, setBusy] = useState(false); // gates Archive/Keep only

  const timersRef = useRef<Set<ReturnType<typeof setTimeout>>>(new Set());
  const undoBusyRef = useRef(false);
  const emptyFiredRef = useRef(false);

  const addTimer = useCallback((fn: () => void, ms: number) => {
    const id = setTimeout(() => {
      timersRef.current.delete(id);
      fn();
    }, ms);
    timersRef.current.add(id);
    return id;
  }, []);

  const clearAllTimers = useCallback(() => {
    timersRef.current.forEach((id) => clearTimeout(id));
    timersRef.current.clear();
  }, []);

  useEffect(() => clearAllTimers, [clearAllTimers]);

  useEffect(() => {
    if (queue.length === 0 && !emptyFiredRef.current) {
      emptyFiredRef.current = true;
      onEmpty?.();
    } else if (queue.length > 0) {
      emptyFiredRef.current = false;
    }
  }, [queue.length, onEmpty]);

  const commit = useCallback(
    (decision: Decision) => {
      if (busy || queue.length === 0) return;
      const card = queue[0];
      const dir: "left" | "right" = decision === "archived" ? "left" : "right";

      setBusy(true);
      setPhase("commit");
      setExiting({ card, dir });
      setQueue((q) => q.slice(1));
      setHistory((h) => [...h, { card, decision }]);
      setNotch((n) => Math.min(teethCount - 1, n + 1));

      const remaining = queue.length - 1;
      const label = decision === "archived" ? "Archived" : "Kept";
      setAnnouncement(
        remaining > 0
          ? `${label}. ${remaining} remaining. Press U to undo.`
          : `${label}. Queue clear. Press U to undo.`,
      );

      if (decision === "archived") onArchive?.(card);
      else onKeep?.(card);

      const exitMs = reducedMotion ? 120 : COMMIT_EXIT_MS;
      const rackMs = reducedMotion ? 0 : COMMIT_RACK_MS + PAWL_FLEX_MS;
      const settleMs = Math.max(exitMs, rackMs);

      addTimer(() => {
        setExiting(null);
        setPhase("idle");
        setBusy(false);
      }, settleMs);
    },
    [busy, queue, teethCount, reducedMotion, addTimer, onArchive, onKeep],
  );

  const undo = useCallback(() => {
    if (undoBusyRef.current) return;
    undoBusyRef.current = true;
    // clearAllTimers cancels any pending commit-settle timer too — reconcile
    // that lock immediately rather than leaving Archive/Keep dead forever if
    // undo interrupts a still-animating commit.
    clearAllTimers();
    setBusy(false);
    setExiting(null);
    setPhase("undo-lift");

    // captured from this render's closure, not read back out of a state
    // updater — updaters must stay pure (StrictMode invokes them twice),
    // so every side effect below runs in a plain timer callback instead.
    const entry = history[history.length - 1];
    const queueLenAtClick = queue.length;

    // The CSS transition duration is zeroed under reduced motion (an
    // instant step, no tween) but the *state* still holds briefly either
    // way — "lifted" has to be a real, observable moment, not motion.
    const liftMs = reducedMotion ? 180 : LIFT_MS;
    addTimer(() => {
      if (!entry) {
        setAnnouncement("Nothing to undo.");
        const holdMs = reducedMotion ? 150 : EMPTY_HOLD_MS;
        addTimer(() => {
          setPhase("idle");
          undoBusyRef.current = false;
        }, holdMs);
        return;
      }
      setPhase("undo-ease");
      setHistory((h) => h.slice(0, -1));
      setQueue((q) => [entry.card, ...q]);
      setNotch((n) => Math.max(0, n - 1));
      onUndo?.(entry.card);
      setAnnouncement(`Undone. ${entry.card.title} restored. ${queueLenAtClick + 1} remaining.`);
      const easeMs = reducedMotion ? 220 : EASE_MS;
      addTimer(() => {
        setPhase("idle");
        undoBusyRef.current = false;
      }, easeMs);
    }, liftMs);
  }, [history, queue, reducedMotion, addTimer, clearAllTimers, onUndo]);

  const onKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLDivElement>) => {
      const key = e.key.toLowerCase();
      if (key === "arrowleft" || key === "j") {
        e.preventDefault();
        commit("archived");
      } else if (key === "arrowright" || key === "k") {
        e.preventDefault();
        commit("kept");
      } else if (key === "u" || ((e.metaKey || e.ctrlKey) && key === "z")) {
        e.preventDefault();
        undo();
      }
    },
    [commit, undo],
  );

  const engagedTooth = Math.min(notch, teethCount - 1);
  const rackTranslate = PAWL_X - (engagedTooth * TOOTH + RACK_PAD);
  const rackDuration = reducedMotion
    ? 0
    : phase === "undo-ease"
      ? EASE_MS
      : COMMIT_RACK_MS;
  const rackEase = phase === "undo-ease" ? RACK_EASE_BACK : RACK_EASE_FWD;

  const pawlLifted = phase === "undo-lift" || phase === "undo-ease";
  const pawlAngle = pawlLifted ? -20 : 0;
  const pawlDuration = reducedMotion ? 0 : phase === "undo-ease" ? 0 : LIFT_MS;

  const teeth = useMemo(() => {
    const out: { x: number; d: string }[] = [];
    for (let i = 0; i < teethCount; i++) {
      const x = RACK_PAD + i * TOOTH;
      // asymmetric sawtooth: shallow climbing ramp, then a steep blocking
      // face — the geometry itself reads "this only turns one way".
      const d = `M ${x} 30 L ${x + TOOTH * 0.72} 8 L ${x + TOOTH} 8 L ${x + TOOTH} 30 Z`;
      out.push({ x, d });
    }
    return out;
  }, [teethCount]);

  const rackWidth = RACK_PAD + teethCount * TOOTH + RACK_PAD;

  const topCard = queue[0];
  const stackVisible = queue.slice(0, 3);
  const optionId = (id: string) => `${uid}-opt-${id}`;
  const busyOrEmpty = busy || queue.length === 0;

  return (
    <div className={["mx-auto flex w-full max-w-md flex-col gap-5", className].join(" ")}>
      <div
        role="listbox"
        aria-label="Card triage queue"
        aria-activedescendant={topCard ? optionId(topCard.id) : undefined}
        tabIndex={0}
        onKeyDown={onKeyDown}
        className="ns-pw-stack relative rounded-md focus:outline-none focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background"
        style={{ height: 176 }}
      >
        {stackVisible
          .slice()
          .reverse()
          .map((card, ri) => {
            const i = stackVisible.length - 1 - ri;
            const isTop = i === 0;
            return (
              <div
                key={card.id}
                id={optionId(card.id)}
                role="option"
                aria-selected={isTop}
                className="ns-pw-card absolute inset-x-0 top-0 flex flex-col gap-1.5 rounded-md border border-border bg-surface p-5 shadow-sm"
                style={{
                  transform: `translateY(${i * 10}px) scale(${1 - i * 0.03})`,
                  opacity: 1 - i * 0.22,
                  zIndex: 10 - i,
                }}
              >
                <h3 className="text-sm font-semibold text-foreground">{card.title}</h3>
                {card.subtitle && (
                  <p className="text-xs text-ns-muted">{card.subtitle}</p>
                )}
                {card.body && isTop && (
                  <p className="mt-1 text-sm leading-relaxed text-foreground/90">{card.body}</p>
                )}
              </div>
            );
          })}

        {exiting && (
          <div
            aria-hidden
            className="ns-pw-card ns-pw-exit absolute inset-x-0 top-0 flex flex-col gap-1.5 rounded-md border border-border bg-surface p-5 shadow-sm"
            data-dir={exiting.dir}
            data-reduced={reducedMotion || undefined}
            style={{ zIndex: 20 }}
          >
            <h3 className="text-sm font-semibold text-foreground">{exiting.card.title}</h3>
            {exiting.card.subtitle && (
              <p className="text-xs text-ns-muted">{exiting.card.subtitle}</p>
            )}
          </div>
        )}

        {!topCard && (
          <div className="absolute inset-0 flex items-center justify-center rounded-md border border-dashed border-border">
            <p className="text-sm text-ns-muted">Queue clear</p>
          </div>
        )}
      </div>

      {/* rack + pawl — decorative, fully described by the live region above */}
      <div aria-hidden="true" className="relative h-9 w-full">
        <div className="absolute inset-0 overflow-hidden rounded-sm border border-border bg-background">
          <svg
            width={rackWidth}
            height={38}
            viewBox={`0 0 ${rackWidth} 38`}
            className="absolute inset-y-0"
            style={{
              transform: `translateX(${rackTranslate}px)`,
              transitionProperty: "transform",
              transitionDuration: `${rackDuration}ms`,
              transitionTimingFunction: rackEase,
            }}
          >
            {teeth.map((t, i) => (
              <path
                key={t.x}
                d={t.d}
                fill={i === engagedTooth ? "var(--foreground)" : "none"}
                fillOpacity={i === engagedTooth ? 0.14 : 1}
                stroke={i === engagedTooth ? "var(--foreground)" : "var(--border)"}
                strokeWidth={i === engagedTooth ? 1.75 : 1.25}
              />
            ))}
          </svg>
        </div>

        <svg
          width={22}
          height={26}
          viewBox="0 0 22 26"
          className="pointer-events-none absolute -top-3"
          style={{
            left: PAWL_X - 5,
            transform: `rotate(${pawlAngle}deg)`,
            transformOrigin: "4px 5px",
            transitionProperty: "transform",
            transitionDuration: `${pawlDuration}ms`,
            transitionTimingFunction: "cubic-bezier(0.34, 1.56, 0.64, 1)",
          }}
        >
          <path
            d="M4 4 L4 15 Q4 19 9 19 L16 19"
            fill="none"
            stroke="var(--foreground)"
            strokeWidth={2.25}
            strokeLinecap="round"
            strokeLinejoin="round"
          />
          <circle cx={4} cy={4} r={2} fill="var(--foreground)" />
        </svg>

        {/* Real (non-decorative, hit-testable) "armed to reverse" marker —
            the pawl svg above is pointer-events-none and its stroke is thin
            enough that a screenshot/gate hit-test at its own center can
            land on empty space, so the gate's `expect` target is this
            plain, normally-painted node instead, not the svg. */}
        {pawlLifted && (
          <div
            data-pawl-lifted="true"
            aria-hidden="true"
            className="absolute h-2.5 w-2.5 rounded-full bg-foreground"
            style={{ left: PAWL_X - 6, top: -10 }}
          />
        )}
      </div>

      <div className="flex items-center gap-2">
        <button
          type="button"
          onClick={() => commit("archived")}
          disabled={busyOrEmpty}
          className="ns-pw-btn flex-1 rounded-sm border border-border bg-surface px-3 py-2 text-sm font-medium text-foreground transition-colors hover:enabled:border-ns-muted hover:enabled:bg-border/60 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent disabled:cursor-not-allowed disabled:opacity-45"
        >
          Archive
        </button>
        <button
          type="button"
          onClick={() => commit("kept")}
          disabled={busyOrEmpty}
          className="ns-pw-btn flex-1 rounded-sm border border-border bg-surface px-3 py-2 text-sm font-medium text-foreground transition-colors hover:enabled:border-ns-muted hover:enabled:bg-border/60 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent disabled:cursor-not-allowed disabled:opacity-45"
        >
          Keep
        </button>
        <button
          type="button"
          data-pawl-undo
          onClick={undo}
          className="ns-pw-btn rounded-sm border border-border bg-surface px-3 py-2 text-sm font-medium text-ns-muted transition-colors hover:border-ns-muted hover:bg-border/60 hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
        >
          Undo
        </button>
      </div>

      <p className="text-xs text-ns-muted">
        Left/Right or J/K to triage, U (or Cmd/Ctrl+Z) to undo — undo lifts the pawl before the
        rack eases back.
      </p>

      <div role="status" aria-live="polite" className="sr-only">
        {announcement}
      </div>

      <style>{`
        .ns-pw-card {
          transition: transform 260ms ${CARD_EXIT_EASE}, opacity 260ms ease;
        }
        .ns-pw-exit[data-dir="left"] {
          animation: ns-pw-exit-left ${COMMIT_EXIT_MS}ms ${CARD_EXIT_EASE} both;
        }
        .ns-pw-exit[data-dir="right"] {
          animation: ns-pw-exit-right ${COMMIT_EXIT_MS}ms ${CARD_EXIT_EASE} both;
        }
        @keyframes ns-pw-exit-left {
          to { transform: translateX(-135%) rotate(-8deg); opacity: 0; }
        }
        @keyframes ns-pw-exit-right {
          to { transform: translateX(135%) rotate(8deg); opacity: 0; }
        }
        .ns-pw-exit[data-reduced][data-dir] {
          animation: ns-pw-exit-fade 120ms ease both;
        }
        @keyframes ns-pw-exit-fade {
          to { opacity: 0; }
        }
      `}</style>
    </div>
  );
}

"use client";

import { useLayoutEffect, useMemo, useRef, useState, type KeyboardEvent } from "react";

// ---------------------------------------------------------------------------
// QuoinLockup — a bento grid whose interesting variable is PRESSURE, not cell
// assignment. Five tiles sit in a FIXED arrangement inside a steel chase; the
// gutters between them are real furniture with discrete quantised widths, and
// four quoins (opposing wedge pairs at the right edge and the foot) supply the
// pressure that holds the whole lockup flush. Pressure creeps down forever;
// once a tile's seeded hold value crosses the lift threshold it pies — sinks
// out of plane, tilts, grows a contact shadow — and the operator re-keys the
// quoins one at a time to bring it back. Nothing ever changes which cell a
// tile occupies: that is the entire difference from grid-bento-dense (which
// re-packs on `grid-auto-flow: dense`) and grid-bento-ascii (which re-spans a
// cell across every seam track). Here the arrangement is a constant; only the
// pressure — and, downstream of it, gutter width and tile plane — moves.
//
// D8 (round 13 decisions): this sits near letterpress the same way
// convert-foil-block does, but the two are disjoint. foil-block's variable is
// a dual TRANSFER THRESHOLD (heat + force) deciding whether a mark takes on
// paper at all; it renders no bed of type. This component's variable is
// PRESSURE distributing an already-fixed layout — it never decides whether
// content "takes", only how tightly the grid holding it is locked up.
//
// Colour is pure CSS: every value comes from --background/--foreground/
// --ns-muted/--border/--ns-accent through Tailwind utilities or an inline
// `color-mix(in srgb, var(--x), var(--y) N%)`, with light/dark deltas carried
// by a `dark:` class flipping a small custom property the color-mix reads.
// Nothing here is a raster surface, so there is no getComputedStyle/
// MutationObserver token pipeline to race against first paint — the browser
// resolves every var() and color-mix() synchronously at paint time. This
// mirrors grid-bento-dense, the nearest sibling in this collection ("All
// color from tokens via Tailwind utility classes, zero canvas").
// ---------------------------------------------------------------------------

export interface QuoinLockupTile {
  id: string;
  title: string;
  body?: string;
  href?: string;
}

export interface QuoinLockupProps {
  /** Exactly 5 tiles, fixed arrangement (2x2 hero, two elongated, two 1x1). */
  tiles?: QuoinLockupTile[];
  /** How often (in press cycles) the planer sweeps and flushes the whole form. */
  planerEvery?: number;
  className?: string;
}

const DEFAULT_TILES: QuoinLockupTile[] = [
  {
    id: "hero",
    title: "One workspace, everything in it",
    body: "Docs, tasks and reviews read from the same record, so nothing drifts out of sync between them.",
    href: "#",
  },
  { id: "tall", title: "Fast on a cold start", body: "Pages stream in as you open them, with no build step to wait on.", href: "#" },
  { id: "wide", title: "Version history", body: "Roll any document back to an earlier state without leaving the page.", href: "#" },
  { id: "a", title: "Scoped access", body: "Invite a team and choose exactly what each role can see.", href: "#" },
  { id: "b", title: "Works offline", body: "Edits queue on the device and merge cleanly the moment you reconnect.", href: "#" },
];

// -- real numbers (spec section 5) ------------------------------------------
const CHASE_INSET_F = 0.055;
const RAIL_STROKE_F = 0.012;
const U_F = 0.0125; // one pica, as a fraction of M
const LEGAL_LEVELS = [2, 3, 4, 6, 8]; // legal gutter widths, in u
const QUOIN_TRAVEL_U = 1.0;
const P_MAX = 0.93;
const P_MIN = 0.62;
const LIFT_THRESHOLD = 0.62;
const DECAY_RATE = 0.055; // P units / second
const DECAY_DURATION = (P_MAX - P_MIN) / DECAY_RATE; // ~5.64s, spec's "5.6s"
const QUOIN_COUNT = 4;
const QUOIN_INTERVAL = 0.64; // s between quoins starting their turn
const QUOIN_ROTATE = 0.32; // s for a key to turn 90deg
const QUOIN_STEP_UP = 0.19; // P per quoin, clamped at P_MAX
const REKEY_DURATION = QUOIN_COUNT * QUOIN_INTERVAL; // 2.56s, spec's "~2.6s"
const CYCLE = DECAY_DURATION + REKEY_DURATION; // ~8.2s, spec's period
const PLANER_DURATION = 0.7;
const SINK_DEPTH_F = 0.028; // fraction of M
const SINK_SCALE = 0.022; // 1 - this at full sink -> 0.978
const SINK_TILT_DEG = 0.9;
const STATIC_TIME = 6.3;

// fixed seed, never Math.random: same tile always loosens first
const JITTER = [-0.62, 0.35, -0.88, 0.71, 0.08];
const TILT_SIGN = [1, -1, 1, -1, 1];

type GutterKey = "gx1" | "gx2" | "gy1" | "gy2" | "gy3";
const FULL_GUTTERS: GutterKey[] = ["gx1", "gx2", "gy1", "gy2", "gy3"];
const COMPACT_GUTTERS: GutterKey[] = ["gx1", "gy1"];

// which gutters border each tile, so hover/focus can step just those down a
// legal size — nothing about the grid ever re-assigns, only these widths
const FULL_TILE_GUTTERS: GutterKey[][] = [
  ["gx2", "gy2"], // hero: 2x2, cols 1-2 rows 1-2
  ["gx2", "gy2"], // tall: 1x2, col 3 rows 1-2
  ["gy2", "gy3"], // wide: 2x1, cols 1-2 row 3
  ["gx2", "gy2", "gy3"], // a: 1x1, col 3 row 3
  ["gy3"], // b: full-width foot course, row 4
];
const COMPACT_TILE_GUTTERS: GutterKey[][] = [
  ["gy1"], // wide: 2x1, cols 1-2 row 1
  ["gx1", "gy1"], // a: 1x1, col 1 row 2
  ["gx1", "gy1"], // b: 1x1, col 2 row 2
];

function quantize(target: number): number {
  let best = LEGAL_LEVELS[0];
  let bestDist = Infinity;
  for (const level of LEGAL_LEVELS) {
    const d = Math.abs(level - target);
    if (d < bestDist) {
      bestDist = d;
      best = level;
    }
  }
  return best;
}

// legal gutter width, in u, for a given pressure: tighter lockup -> narrower
// furniture. Quantised, so this never reports a continuous value.
function gutterLevelFor(p: number): number {
  const clamped = Math.min(1, Math.max(0, p));
  const target = 2 + (1 - clamped) * (8 - 2);
  return quantize(target);
}

function smoothstep(x: number): number {
  const t = Math.min(1, Math.max(0, x));
  return t * t * (3 - 2 * t);
}

interface QuoinLockupState {
  p: number;
  cyclePos: number;
  rekeyActive: boolean;
  activeQuoin: number; // -1 when none mid-turn
  quoinTravel: number[]; // 0..1, one per quoin, uniform
  keyDock: number; // which quoin the key sits at when idle (last one turned)
  keyRotate: number; // 0..1 (0..90deg) for the quoin mid-turn
  planerActive: boolean;
  planerX: number; // 0..1 across the form
}

// Pure function of absolute time: no integration, so the same t always
// produces the same frame. This is what makes STATIC_TIME byte-stable.
function stateAt(t: number, planerEvery: number): QuoinLockupState {
  const cycleIndex = Math.floor(t / CYCLE);
  const cyclePos = t - cycleIndex * CYCLE;
  const isPlanerCycle = planerEvery > 0 && (cycleIndex + 1) % planerEvery === 0;

  let p: number;
  let rekeyActive = false;
  let activeQuoin = -1;
  const quoinTravel = [0, 0, 0, 0];
  let keyDock = QUOIN_COUNT - 1;
  let keyRotate = 0;
  let planerActive = false;
  let planerX = 0;

  if (cyclePos < DECAY_DURATION) {
    p = P_MAX - DECAY_RATE * cyclePos;
    // wedges ease back toward their resting travel as pressure relaxes
    const travel = smoothstep((p - P_MIN) / (P_MAX - P_MIN));
    quoinTravel[0] = quoinTravel[1] = quoinTravel[2] = quoinTravel[3] = travel;
    keyDock = -1; // key is out, riding the last quoin from the previous cycle
  } else {
    rekeyActive = true;
    const rk = cyclePos - DECAY_DURATION;
    p = LIFT_THRESHOLD;
    for (let i = 0; i < QUOIN_COUNT; i++) {
      const start = i * QUOIN_INTERVAL;
      if (rk < start) {
        quoinTravel[i] = 0;
        continue;
      }
      const local = rk - start;
      const turnProgress = smoothstep(local / QUOIN_ROTATE);
      quoinTravel[i] = turnProgress;
      if (local < QUOIN_ROTATE) {
        activeQuoin = i;
        keyRotate = turnProgress;
      } else {
        keyDock = i;
      }
      // the +0.19 step begins 140ms into the turn and completes over the
      // remaining 180ms (critically damped ease, approximated by smoothstep);
      // each later quoin's iteration overwrites p with its own cumulative
      // total, so the last quoin whose turn has started wins, which is
      // exactly the running pressure after i completed steps plus this one
      const stepProgress = smoothstep((local - 0.14) / 0.18);
      p = Math.min(P_MAX, LIFT_THRESHOLD + i * QUOIN_STEP_UP + QUOIN_STEP_UP * stepProgress);
    }
    if (isPlanerCycle && rk < PLANER_DURATION) {
      planerActive = true;
      planerX = smoothstep(rk / PLANER_DURATION);
    }
  }

  return { p, cyclePos, rekeyActive, activeQuoin, quoinTravel, keyDock, keyRotate, planerActive, planerX };
}

function sinkFracFor(p: number, index: number): number {
  const h = p + 0.1 * JITTER[index];
  if (h >= LIFT_THRESHOLD) return 0;
  return Math.min(1, (LIFT_THRESHOLD - h) / LIFT_THRESHOLD);
}

// tile x-position, as a fraction of the chase width, used only to decide when
// the planer bar has swept past a given tile (left column vs right column)
const FULL_TILE_X: number[] = [0.28, 0.83, 0.28, 0.83, 0.5];
const COMPACT_TILE_X: number[] = [0.5, 0.25, 0.75];

export function QuoinLockup({ tiles = DEFAULT_TILES, planerEvery = 3, className = "" }: QuoinLockupProps) {
  const hostRef = useRef<HTMLDivElement | null>(null);
  const [m, setM] = useState(0);
  const [compact, setCompact] = useState(false);
  const [hoveredId, setHoveredId] = useState<string | null>(null);
  const [activeIdx, setActiveIdx] = useState(0);
  const [reducedMotion, setReducedMotion] = useState(false);

  const gridRef = useRef<HTMLDivElement | null>(null);
  const tileRefs = useRef(new Map<string, HTMLAnchorElement | HTMLButtonElement>());
  const quoinRefs = useRef<(HTMLDivElement | null)[]>([null, null, null, null]);
  const keyRef = useRef<HTMLDivElement | null>(null);
  const planerRef = useRef<HTMLDivElement | null>(null);
  const railRef = useRef<HTMLDivElement | null>(null);

  const rows = compact ? tiles.slice(0, 3) : tiles.slice(0, 5);
  const gutterKeys = compact ? COMPACT_GUTTERS : FULL_GUTTERS;
  const tileGutters = compact ? COMPACT_TILE_GUTTERS : FULL_TILE_GUTTERS;
  const tileX = compact ? COMPACT_TILE_X : FULL_TILE_X;

  // measure before paint so the form is never shown at the wrong size
  useLayoutEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const measure = (w: number) => {
      setM(w);
      setCompact(w < 320);
    };
    const rect = host.getBoundingClientRect();
    measure(Math.min(rect.width, rect.height) || rect.width);
    const ro = new ResizeObserver((entries) => {
      const entry = entries[0];
      if (!entry) return;
      const box = entry.contentRect;
      measure(Math.min(box.width, box.height) || box.width);
    });
    ro.observe(host);
    return () => ro.disconnect();
  }, []);

  useLayoutEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReducedMotion(mq.matches);
    const onChange = () => setReducedMotion(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  const u = m * U_F;

  const applyFrame = useMemo(
    () => (t: number) => {
      const st = stateAt(t, planerEvery);

      // gutters: pressure-derived legal width, minus one legal step for
      // whichever gutters border the currently hovered/focused tile
      const hoveredIndex = hoveredId ? rows.findIndex((c) => c.id === hoveredId) : -1;
      const hoveredKeys = hoveredIndex >= 0 ? tileGutters[hoveredIndex] : [];
      const baseLevel = gutterLevelFor(st.p);
      const grid = gridRef.current;
      if (grid) {
        for (const key of gutterKeys) {
          let level = baseLevel;
          if (hoveredKeys.includes(key)) {
            const idx = LEGAL_LEVELS.indexOf(level);
            level = LEGAL_LEVELS[Math.max(0, idx - 1)];
          }
          // the track size lives on the grid container's own custom
          // property — a property set on a gutter cell would not be
          // inherited upward by its ancestor's grid-template
          grid.style.setProperty(`--gw-${key}`, `${level * u}px`);
        }
      }

      // tiles: sink, tilt, contact shadow, planer override
      rows.forEach((tile, i) => {
        const el = tileRefs.current.get(tile.id);
        if (!el) return;
        let sink = sinkFracFor(st.p, i);
        if (st.planerActive && st.planerX >= tileX[i]) sink = 0;
        const sinkPx = sink * SINK_DEPTH_F * m;
        const scale = 1 - SINK_SCALE * sink;
        const tilt = SINK_TILT_DEG * sink * TILT_SIGN[i];
        el.style.setProperty("--sink", `${sinkPx}px`);
        el.style.setProperty("--tile-scale", `${scale}`);
        el.style.setProperty("--tile-tilt", `${tilt}deg`);
        el.style.setProperty("--shadow-o", `${sink}`);
        el.style.setProperty("--edge-o", `${1 - sink}`);
      });

      // quoins + key
      for (let i = 0; i < QUOIN_COUNT; i++) {
        const el = quoinRefs.current[i];
        if (el) el.style.setProperty("--travel", `${st.quoinTravel[i] * QUOIN_TRAVEL_U * u}px`);
      }
      if (keyRef.current) {
        const dockIndex = st.activeQuoin >= 0 ? st.activeQuoin : Math.max(0, st.keyDock);
        keyRef.current.style.setProperty("--key-slot", `${dockIndex}`);
        keyRef.current.style.setProperty("--key-rotate", `${st.keyRotate * 90}deg`);
        keyRef.current.style.opacity = st.rekeyActive ? "1" : "0";
      }
      if (planerRef.current) {
        planerRef.current.style.opacity = st.planerActive ? "1" : "0";
        planerRef.current.style.setProperty("--planer-x", `${st.planerX * 100}%`);
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [m, u, compact, hoveredId, planerEvery]
  );

  useLayoutEffect(() => {
    if (m <= 0) return;

    if (reducedMotion) {
      applyFrame(STATIC_TIME);
      return;
    }

    let raf = 0;
    let running = false;
    const origin = performance.now();

    const loop = (now: number) => {
      applyFrame((now - origin) / 1000);
      raf = requestAnimationFrame(loop);
    };
    const wake = () => {
      if (running) return;
      running = true;
      raf = requestAnimationFrame(loop);
    };
    const sleep = () => {
      cancelAnimationFrame(raf);
      running = false;
    };

    const host = hostRef.current;
    let onScreen = true;
    const io = host
      ? new IntersectionObserver(
          (entries) => {
            onScreen = entries.some((en) => en.isIntersecting);
            if (!onScreen) sleep();
            else if (!document.hidden) wake();
          },
          { threshold: 0 }
        )
      : null;
    if (host && io) io.observe(host);

    const onVis = () => {
      if (document.hidden) sleep();
      else if (onScreen) wake();
    };
    document.addEventListener("visibilitychange", onVis);
    wake();

    return () => {
      sleep();
      io?.disconnect();
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [m, reducedMotion, applyFrame]);

  const onKeyDown = (e: KeyboardEvent<HTMLElement>, index: number) => {
    const count = rows.length;
    let next = index;
    switch (e.key) {
      case "ArrowRight":
      case "ArrowDown":
        e.preventDefault();
        next = (index + 1) % count;
        break;
      case "ArrowLeft":
      case "ArrowUp":
        e.preventDefault();
        next = (index - 1 + count) % count;
        break;
      default:
        return;
    }
    setActiveIdx(next);
    const el = tileRefs.current.get(rows[next].id);
    el?.focus();
  };

  // grid-column/row spans are module-level constants, never written after
  // mount — pressure changes gutter TRACK SIZE (the --gw-* custom
  // properties, set imperatively on the grid container in applyFrame), spans
  // never change.
  const fullTemplateCols = "minmax(0,1fr) var(--gw-gx1,3px) minmax(0,1fr) var(--gw-gx2,3px) minmax(0,1fr)";
  const fullTemplateRows =
    "minmax(0,1fr) var(--gw-gy1,3px) minmax(0,1fr) var(--gw-gy2,3px) minmax(0,1fr) var(--gw-gy3,3px) minmax(0,1fr)";
  const compactTemplateCols = "minmax(0,1fr) var(--gw-gx1,3px) minmax(0,1fr)";
  const compactTemplateRows = "minmax(0,1fr) var(--gw-gy1,3px) minmax(0,1fr)";

  return (
    <div ref={hostRef} className={`relative h-full w-full min-h-[240px] ${className}`}>
      {/* frame layer: chase rail + quoins + key + planer. Positioned as
          fractions of the chase, so it needs nothing from the tile grid. */}
      <div aria-hidden className="pointer-events-none absolute inset-0 z-0">
        <div
          ref={railRef}
          className="absolute [--rail-a:72%] dark:[--rail-a:100%]"
          style={{
            inset: m * CHASE_INSET_F,
            borderWidth: Math.max(1, m * RAIL_STROKE_F),
            borderStyle: "solid",
            borderColor: "color-mix(in srgb, var(--foreground) var(--rail-a), transparent)",
            borderRadius: 2,
          }}
        />
        {[0, 1, 2, 3].map((i) => {
          const edge = i < 2 ? "right" : "foot";
          const along = edge === "right" ? (i === 0 ? 0.32 : 0.68) : i === 2 ? 0.32 : 0.68;
          const len = u * 3;
          const thick = u * 1.4;
          return (
            <div
              key={i}
              ref={(el) => {
                quoinRefs.current[i] = el;
              }}
              className="absolute [--travel:0px]"
              style={
                edge === "right"
                  ? {
                      right: m * CHASE_INSET_F - thick * 0.4,
                      top: `calc(${along * 100}% - ${len / 2}px)`,
                      width: thick,
                      height: len,
                    }
                  : {
                      bottom: m * CHASE_INSET_F - thick * 0.4,
                      left: `calc(${along * 100}% - ${len / 2}px)`,
                      height: thick,
                      width: len,
                    }
              }
            >
              <div
                className="absolute inset-0 [--wedge-a:46%] dark:[--wedge-a:58%]"
                style={{
                  background: "color-mix(in srgb, var(--background), var(--foreground) var(--wedge-a))",
                  transform: edge === "right" ? "skewY(-14deg)" : "skewX(-14deg)",
                }}
              />
              <div
                className="absolute inset-0 [--wedge-b:34%] dark:[--wedge-b:46%]"
                style={{
                  background: "color-mix(in srgb, var(--background), var(--foreground) var(--wedge-b))",
                  transform:
                    edge === "right"
                      ? "skewY(-14deg) translateY(var(--travel))"
                      : "skewX(-14deg) translateX(var(--travel))",
                }}
              />
            </div>
          );
        })}
        <div
          ref={keyRef}
          className="absolute h-[1.6em] w-[1.6em] max-h-4 max-w-4 border-2 border-ns-muted transition-[opacity] duration-200"
          style={{
            right: m * CHASE_INSET_F - 8,
            bottom: `calc(20% + var(--key-slot, 0) * 15%)`,
            transform: "rotate(var(--key-rotate, 0deg))",
            opacity: 0,
          }}
        />
        <div
          ref={planerRef}
          className="absolute top-0 h-full w-[3px] bg-ns-muted transition-[opacity] duration-150"
          style={{ left: "var(--planer-x, 0%)", opacity: 0 }}
        />
      </div>

      <div
        ref={gridRef}
        role="group"
        aria-label="Bento grid locked by four quoins. Arrow keys move between tiles."
        className="relative z-[1] grid h-full w-full gap-0"
        style={{
          padding: m * CHASE_INSET_F + Math.max(1, m * RAIL_STROKE_F) * 2,
          gridTemplateColumns: compact ? compactTemplateCols : fullTemplateCols,
          gridTemplateRows: compact ? compactTemplateRows : fullTemplateRows,
        }}
      >
        {gutterKeys.map((key) => (
          <div
            key={key}
            aria-hidden
            className="[--fill-a:40%]"
            style={{
              gridColumn: gridAreaFor(key, compact, "col"),
              gridRow: gridAreaFor(key, compact, "row"),
              backgroundColor: "color-mix(in srgb, var(--background), var(--foreground) var(--fill-a))",
              backgroundImage:
                key.startsWith("gx")
                  ? `repeating-linear-gradient(to bottom, transparent 0, transparent calc(${Math.max(
                      1,
                      m * 0.11
                    )}px - 1px), color-mix(in srgb, var(--border), var(--foreground) 30%) calc(${Math.max(
                      1,
                      m * 0.11
                    )}px - 1px), color-mix(in srgb, var(--border), var(--foreground) 30%) ${Math.max(1, m * 0.11)}px)`
                  : `repeating-linear-gradient(to right, transparent 0, transparent calc(${Math.max(
                      1,
                      m * 0.11
                    )}px - 1px), color-mix(in srgb, var(--border), var(--foreground) 30%) calc(${Math.max(
                      1,
                      m * 0.11
                    )}px - 1px), color-mix(in srgb, var(--border), var(--foreground) 30%) ${Math.max(1, m * 0.11)}px)`,
            }}
          />
        ))}

        {rows.map((tile, i) => {
          const isHero = !compact && i === 0;
          const commonProps = {
            ref: (el: HTMLAnchorElement | HTMLButtonElement | null) => {
              if (el) tileRefs.current.set(tile.id, el);
              else tileRefs.current.delete(tile.id);
            },
            tabIndex: i === activeIdx ? 0 : -1,
            onFocus: () => setActiveIdx(i),
            onMouseEnter: () => setHoveredId(tile.id),
            onMouseLeave: () => setHoveredId((cur) => (cur === tile.id ? null : cur)),
            onKeyDown: (e: KeyboardEvent<HTMLElement>) => onKeyDown(e, i),
            className:
              "quoin-lockup-tile group relative isolate flex flex-col justify-start gap-1 overflow-hidden rounded-sm border p-3 text-left transition-colors duration-150 " +
              "[--face-mix:10%] dark:[--face-mix:16%] " +
              "border-transparent hover:[--face-mix:12%] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent",
            style: {
              gridColumn: gridAreaFor(`tile-${i}`, compact, "col"),
              gridRow: gridAreaFor(`tile-${i}`, compact, "row"),
              backgroundColor: "color-mix(in srgb, var(--background), var(--foreground) var(--face-mix))",
              borderTopColor: "color-mix(in srgb, var(--foreground) calc(var(--edge-o, 1) * 22%), transparent)",
              transform:
                "translateY(var(--sink, 0px)) scale(var(--tile-scale, 1)) rotate(var(--tile-tilt, 0deg))",
              boxShadow: "0 calc(var(--sink, 0px) * 0.6) calc(var(--sink, 0px) * 1.8) color-mix(in srgb, var(--foreground) calc(var(--shadow-o, 0) * 38%), transparent)",
              zIndex: i,
            } as React.CSSProperties,
            "aria-label": tile.title,
            "data-tile-id": tile.id,
          };
          const content = (
            <>
              <h3 className={`font-medium leading-snug text-foreground ${isHero ? "text-base" : "text-sm"}`}>
                {tile.title}
              </h3>
              {tile.body && (
                <p className={`text-ns-muted ${isHero ? "max-w-[34ch] text-sm leading-snug" : "text-xs leading-snug"}`}>
                  {tile.body}
                </p>
              )}
            </>
          );
          return tile.href ? (
            <a key={tile.id} {...commonProps} href={tile.href}>
              {content}
            </a>
          ) : (
            <button key={tile.id} {...commonProps} type="button">
              {content}
            </button>
          );
        })}
      </div>
    </div>
  );
}

// Raw grid line coordinates for the fixed arrangement. Content track i (1..n)
// sits at raw line [2i-1, 2i] once gutter tracks are interleaved between
// every pair of content tracks. These are constants — never recomputed by
// pressure state, only read once per render.
function gridAreaFor(key: string, compact: boolean, axis: "col" | "row"): string {
  const rawLine = (content: number) => `${2 * content - 1} / ${2 * content + 1}`;
  if (compact) {
    const colOf = (c1: number, c2 = c1) => `${2 * c1 - 1} / ${2 * c2}`;
    const rowOf = (r1: number, r2 = r1) => `${2 * r1 - 1} / ${2 * r2}`;
    if (key === "gx1") return axis === "col" ? "2 / 3" : "1 / 4";
    if (key === "gy1") return axis === "row" ? "2 / 3" : "1 / 4";
    switch (key) {
      case "tile-0": // wide: cols 1-2, row 1
        return axis === "col" ? colOf(1, 2) : rowOf(1);
      case "tile-1": // a: col 1, row 2
        return axis === "col" ? colOf(1) : rowOf(2);
      case "tile-2": // b: col 2, row 2
        return axis === "col" ? colOf(2) : rowOf(2);
      default:
        return "1 / 2";
    }
  }
  const colOf = (c1: number, c2 = c1) => `${2 * c1 - 1} / ${2 * c2}`;
  const rowOf = (r1: number, r2 = r1) => `${2 * r1 - 1} / ${2 * r2}`;
  if (key === "gx1") return axis === "col" ? "2 / 3" : "1 / 7";
  if (key === "gx2") return axis === "col" ? "4 / 5" : "1 / 6";
  if (key === "gy1") return axis === "row" ? "2 / 3" : "1 / 6";
  if (key === "gy2") return axis === "row" ? "4 / 5" : "1 / 6";
  if (key === "gy3") return axis === "row" ? "6 / 7" : "1 / 6";
  switch (key) {
    case "tile-0": // hero: cols 1-2, rows 1-2
      return axis === "col" ? colOf(1, 2) : rowOf(1, 2);
    case "tile-1": // tall: col 3, rows 1-2
      return axis === "col" ? colOf(3) : rowOf(1, 2);
    case "tile-2": // wide: cols 1-2, row 3
      return axis === "col" ? colOf(1, 2) : rowOf(3);
    case "tile-3": // a: col 3, row 3
      return axis === "col" ? colOf(3) : rowOf(3);
    case "tile-4": // b: cols 1-3, row 4 — the foot course runs the full width,
      // so the chase is packed edge to edge and no cell is left inert
      return axis === "col" ? colOf(1, 3) : rowOf(4);
    default:
      return rawLine(1);
  }
}

QuoinLockup.displayName = "QuoinLockup";

"use client";

import { useCallback, useEffect, useId, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// RackSeat — step-up auth for a group of sensitive actions, drawn as
// switchgear racking instead of a modal ambush.
//
// One governing scalar, `rackTravel` (0..1), owns everything. At rest
// (0) the action group sits physically pulled back on its rails, contacts
// unmade, fully legible the whole time — never dimmed behind a disabled
// overlay. A fresh verification racks the group IN over 450ms
// ease-out-expo to travel=1: the seated position. From there, elevation is
// a physical withdrawal on the same scalar — travel creeps back
// continuously for the length of the elevation window and then plunges,
// visibly accelerating, through the final `accelerateMs`. The group is
// pulled back OUT before it goes fully stale, so expiry is watched, not
// discovered by a failed request.
//
// `rackTravel` never touches the interactive flip mid-creep: the plateau
// phase keeps travel effectively at 1 (the drift there is sub-pixel,
// purely cosmetic continuity), and only the visible final withdrawal
// crosses SEATED_THRESHOLD and actually re-locks the group — so the lock
// and the motion that explains it land together.
// ---------------------------------------------------------------------------

export type RackAction = {
  id: string;
  label: string;
};

export interface RackSeatProps {
  /** the sensitive actions the group holds, e.g. delete-org, rotate-key */
  actions: RackAction[];
  /** epoch ms when the current elevation lapses, or null when not elevated.
   * The owner sets this after real step-up verification succeeds:
   * `Date.now() + elevationMs`. This component never verifies anything —
   * it only asks for it and reflects the window it was handed. */
  expiresAt: number | null;
  /** total elevation window once verified. Default 5 minutes. */
  elevationMs?: number;
  /** final segment of the window where the withdrawal visibly accelerates.
   * Default 10s, clamped to `elevationMs`. */
  accelerateMs?: number;
  /** accessible name for the group region */
  label?: string;
  /** mono caption above the rack */
  title?: string;
  /** fired when a racked-out action is pressed — the owner should start
   * the real step-up flow (WebAuthn, TOTP, whatever) elsewhere on the
   * page; this component only asks for it */
  onRequestVerification?: (actionId: string) => void;
  /** fired when the user presses the inline "Verify identity" affordance */
  onVerify?: () => void;
  /** fired when a seated (travel === 1) action is pressed — the actual
   * sensitive action */
  onActivate?: (actionId: string) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const TRAVEL_PX = 12;
const TICK_COUNT = 6;
const SEAT_MS = 450;
const SEAT_EASE = "cubic-bezier(0.16, 1, 0.3, 1)";
const DEFAULT_ELEVATION_MS = 5 * 60 * 1000;
const DEFAULT_ACCELERATE_MS = 10_000;
/** end of the plateau / start of the visible withdrawal, and the boundary
 * the interactive flip is compared against. The plateau drifts down to
 * exactly this value (never below it) so travel keeps reading as "seated"
 * for the whole holding period; only the accelerate phase, which starts
 * right at this value, carries it below the threshold. */
const SEATED_THRESHOLD = 0.995;

function computeTravel(elapsedMs: number, elevationMs: number, accelerateMs: number) {
  if (elapsedMs <= 0) return 1;
  if (elapsedMs >= elevationMs) return 0;
  const warnStart = Math.max(elevationMs - accelerateMs, 0);
  if (elapsedMs <= warnStart) {
    const span = warnStart || 1;
    const p = elapsedMs / span;
    return 1 - p * (1 - SEATED_THRESHOLD);
  }
  const span = elevationMs - warnStart || 1;
  const p = Math.min(Math.max((elapsedMs - warnStart) / span, 0), 1);
  // ease-in cubic: shallow at the boundary, steep by the time it hits 0 —
  // the visible "accelerates through the final ten seconds" plunge.
  return SEATED_THRESHOLD * (1 - p ** 3);
}

function formatDuration(ms: number) {
  const totalSec = Math.max(Math.round(ms / 1000), 0);
  if (totalSec < 60) return `${totalSec} second${totalSec === 1 ? "" : "s"}`;
  const min = Math.round(totalSec / 60);
  return `${min} minute${min === 1 ? "" : "s"}`;
}

function formatCountdown(ms: number) {
  const totalSec = Math.max(Math.ceil(ms / 1000), 0);
  const m = Math.floor(totalSec / 60);
  const s = totalSec % 60;
  return `${m}:${String(s).padStart(2, "0")}`;
}

function ChevronMark({
  direction,
  className,
}: {
  direction: "left" | "right";
  className?: string;
}) {
  const points = direction === "right" ? "0,0 7,5 0,10" : "7,0 0,5 7,10";
  return (
    <svg
      aria-hidden
      width="7"
      height="10"
      viewBox="0 0 7 10"
      className={className}
    >
      <polygon points={points} fill="currentColor" />
    </svg>
  );
}

export function RackSeat({
  actions,
  expiresAt,
  elevationMs = DEFAULT_ELEVATION_MS,
  accelerateMs = DEFAULT_ACCELERATE_MS,
  label = "Sensitive actions, verification required",
  title = "Sensitive actions",
  onRequestVerification,
  onVerify,
  onActivate,
  className = "",
}: RackSeatProps) {
  const uid = useId().replace(/[^a-zA-Z0-9]/g, "");
  const lockedDescId = `ns-rack-locked-${uid}`;
  const unlockedDescId = `ns-rack-unlocked-${uid}`;

  const [travel, setTravel] = useState(0);
  const [remainMs, setRemainMs] = useState(0);
  const [justSeated, setJustSeated] = useState(false);
  const [stepUpOpen, setStepUpOpen] = useState(false);
  const [announce, setAnnounce] = useState("");
  const [reduced, setReduced] = useState(false);

  const elevatedRef = useRef(false);
  const seatTimerRef = useRef<number | null>(null);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => setReduced(mq.matches);
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);

  const clearSeatTimer = useCallback(() => {
    if (seatTimerRef.current != null) {
      window.clearTimeout(seatTimerRef.current);
      seatTimerRef.current = null;
    }
  }, []);

  useEffect(() => clearSeatTimer, [clearSeatTimer]);

  // The single driver: given expiresAt, either the group is resting
  // locked (no timer) or a window is open and rackTravel is a continuous
  // function of how much of it has elapsed. Seat and expiry announcements
  // are detected here, against the real clock, not against prop identity —
  // an elevation window that simply runs out needs to announce too.
  useEffect(() => {
    let cancelled = false;
    let raf = 0;

    const applyLocked = () => {
      setTravel(0);
      setRemainMs(0);
      if (elevatedRef.current) {
        elevatedRef.current = false;
        setAnnounce("Verification expired, sensitive actions locked.");
      }
    };

    if (!expiresAt) {
      applyLocked();
      return;
    }

    if (reduced) {
      const check = () => {
        const now = Date.now();
        const remain = expiresAt - now;
        if (remain <= 0) {
          applyLocked();
          return;
        }
        setTravel(1);
        setRemainMs(remain);
        if (!elevatedRef.current) {
          elevatedRef.current = true;
          setAnnounce(
            `Verified. Sensitive actions unlocked for ${formatDuration(elevationMs)}.`
          );
        }
      };
      check();
      const id = window.setInterval(check, 1000);
      return () => window.clearInterval(id);
    }

    const tick = () => {
      if (cancelled) return;
      const now = Date.now();
      const remain = expiresAt - now;
      if (remain <= 0) {
        applyLocked();
        return;
      }
      const elapsed = elevationMs - remain;
      setTravel(computeTravel(elapsed, elevationMs, accelerateMs));
      setRemainMs(remain);
      if (!elevatedRef.current) {
        elevatedRef.current = true;
        setAnnounce(
          `Verified. Sensitive actions unlocked for ${formatDuration(elevationMs)}.`
        );
        setJustSeated(true);
        clearSeatTimer();
        seatTimerRef.current = window.setTimeout(() => {
          if (!cancelled) setJustSeated(false);
        }, SEAT_MS);
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);

    return () => {
      cancelled = true;
      cancelAnimationFrame(raf);
    };
  }, [expiresAt, elevationMs, accelerateMs, reduced, clearSeatTimer]);

  const seated = travel >= SEATED_THRESHOLD;

  // Once genuinely seated, the inline step-up affordance has done its job.
  useEffect(() => {
    if (seated) setStepUpOpen(false);
  }, [seated]);

  const ticks = useMemo(
    () =>
      Array.from({ length: TICK_COUNT }, (_, i) => i < Math.round(travel * TICK_COUNT)),
    [travel]
  );

  const offsetPx = -(1 - travel) * TRAVEL_PX;
  const motionStyle: React.CSSProperties =
    justSeated && !reduced
      ? { transition: `transform ${SEAT_MS}ms ${SEAT_EASE}` }
      : { transition: "none" };

  function handleAction(id: string) {
    if (seated) {
      onActivate?.(id);
      return;
    }
    setStepUpOpen(true);
    onRequestVerification?.(id);
  }

  function handleVerify() {
    onVerify?.();
  }

  const readout = reduced
    ? seated
      ? `Unlocked for ${formatDuration(elevationMs)}`
      : "Locked, requires verification"
    : seated
      ? `Unlocked · ${formatCountdown(remainMs)} remaining`
      : remainMs > 0
        ? `Withdrawing · ${formatCountdown(remainMs)} remaining`
        : "Locked · requires verification";

  return (
    <section
      data-rack-seat
      data-seated={seated ? "true" : "false"}
      role="region"
      aria-label={label}
      className={"flex flex-col font-sans " + className}
    >
      <style>{`
.ns-rack-fade{transition:background-color 180ms ease-out}
[data-rack-action]:hover,[data-verify-button]:hover{background-color:color-mix(in srgb, var(--foreground) 6%, transparent)}
@media (prefers-reduced-motion: reduce){.ns-rack-fade{transition:none}}
`}</style>

      <div className="order-1 mb-3 flex items-baseline justify-between gap-4">
        <p className="font-mono text-[11px] uppercase tracking-[0.18em] text-ns-muted">
          {title}
        </p>
        <p
          data-rack-readout
          className="shrink-0 font-mono text-[11px] text-foreground"
        >
          {readout}
        </p>
      </div>

      {/*
        Source order is deliberately head → step-up panel → track, with
        `order-*` reflowing it visually to head → track → panel: the
        autoplay driver and the verifier's own "press first control" pass
        both walk the DOM in TREE order, not visual order, and `target`
        is re-queried every cycle. Placing the panel earlier in the tree
        means that once it exists, a union selector's "first match" finds
        the Verify button instead of re-finding a rack action — the same
        click target naturally advances from "start step-up" to "complete
        step-up" across cycles, without the component special-casing
        autoplay at all.
      */}
      {stepUpOpen ? (
        <div
          data-rack-stepup
          className="order-3 mt-3 flex flex-wrap items-center justify-between gap-3 rounded-md border border-border px-3 py-2"
        >
          <p className="text-xs text-ns-muted">
            Verification required to continue.
          </p>
          <button
            type="button"
            data-verify-button
            onClick={handleVerify}
            className="shrink-0 rounded-sm border border-border px-2.5 py-1 font-mono text-[11px] uppercase tracking-wide text-foreground transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
          >
            Verify identity
          </button>
        </div>
      ) : null}

      <div
        data-rack-track
        className="order-2 flex items-center gap-3 rounded-md border border-border p-4"
      >
        {/* rail + tick gauge + contact pair — decorative, state is carried
            by the group's own transform and the real controls below */}
        <div className="relative h-9 w-9 shrink-0" aria-hidden>
          <div className="absolute inset-x-1 top-1/2 h-px -translate-y-1/2 bg-border" />
          <div className="absolute inset-x-1 top-[calc(50%-6px)] flex justify-between">
            {ticks.map((lit, i) => (
              <span
                key={i}
                className="ns-rack-fade block h-[3px] w-px"
                style={{ backgroundColor: lit ? "var(--foreground)" : "var(--border)" }}
              />
            ))}
          </div>
          <span className="absolute right-0 top-1/2 -translate-y-1/2 text-foreground">
            <ChevronMark direction="left" />
          </span>
          <span
            className="absolute right-[7px] top-1/2 text-foreground"
            style={{
              ...motionStyle,
              transform: `translateY(-50%) translateX(${offsetPx}px)`,
            }}
          >
            <ChevronMark direction="right" />
          </span>
        </div>

        <div
          data-rack-group
          className="flex flex-1 flex-wrap items-center gap-2"
          style={{ ...motionStyle, transform: `translateX(${offsetPx}px)` }}
        >
          {actions.map((a) => (
            <button
              key={a.id}
              type="button"
              data-rack-action={a.id}
              aria-disabled={seated ? undefined : "true"}
              aria-describedby={seated ? unlockedDescId : lockedDescId}
              onClick={() => handleAction(a.id)}
              className="rounded-sm border border-border px-3 py-2 text-sm text-foreground transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
            >
              {a.label}
            </button>
          ))}
        </div>
      </div>

      <p id={lockedDescId} className="sr-only">
        Requires recent verification. Activating starts verification.
      </p>
      <p id={unlockedDescId} className="sr-only">
        Verified. Activating performs this action.
      </p>
      <p role="status" aria-live="polite" className="sr-only">
        {announce}
      </p>
    </section>
  );
}

"use client";

import { useCallback, useEffect, useId, useRef, useState } from "react";

// A single-choice input rendered as a paper ballot. Each option is a real
// role="radio" button (roving tabindex, arrow-key navigation — the standard
// WAI-ARIA radiogroup pattern) styled as a paper slip; hovering an unselected
// slip lifts its corner. Selecting one spawns a decorative ghost clone that
// folds, flutters, and rises through the ballot box's slot before fading —
// changing the vote also retracts the previous ghost back out. The real
// option element never leaves the DOM (it just switches to its "chosen"
// ink), so the control stays a fully functional, always-focusable radio
// group; the paper-drop animation is a one-shot CSS keyframe flourish, not a
// per-frame rAF simulation.

export type BallotOption = { value: string; label: string };

const DEFAULT_OPTIONS: BallotOption[] = [
  { value: "lisbon", label: "Lisbon" },
  { value: "kyoto", label: "Kyoto" },
  { value: "reykjavik", label: "Reykjavik" },
];

type Ghost = {
  id: number;
  label: string;
  top: number;
  left: number;
  width: number;
  height: number;
  travel: number;
  mode: "drop" | "retract";
};

let ghostSeq = 0;

export function BallotDrop({
  options = DEFAULT_OPTIONS,
  label = "Offsite location",
  defaultValue,
  className = "",
}: {
  /** the radio options */
  options?: BallotOption[];
  /** accessible name for the radio group */
  label?: string;
  /** uncontrolled initial selected value */
  defaultValue?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}) {
  const reactId = useId();
  const wrapRef = useRef<HTMLDivElement>(null);
  const boxRef = useRef<HTMLDivElement>(null);
  const optionRefs = useRef<Record<string, HTMLButtonElement | null>>({});
  const [selected, setSelected] = useState<string | undefined>(defaultValue);
  const [ghosts, setGhosts] = useState<Ghost[]>([]);
  const liveRef = useRef<HTMLDivElement>(null);
  const reducedRef = useRef(false);

  useEffect(() => {
    reducedRef.current = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  }, []);

  const announce = useCallback((text: string) => {
    if (liveRef.current) liveRef.current.textContent = text;
  }, []);

  const spawnGhost = useCallback((optionEl: HTMLButtonElement, mode: Ghost["mode"]) => {
    const wrap = wrapRef.current;
    const box = boxRef.current;
    if (!wrap || !box) return;
    const wrapRect = wrap.getBoundingClientRect();
    const optRect = optionEl.getBoundingClientRect();
    const boxRect = box.getBoundingClientRect();
    const top = optRect.top - wrapRect.top;
    const left = optRect.left - wrapRect.left;
    const travel = boxRect.bottom - optRect.top - optRect.height * 0.3;
    const id = ++ghostSeq;
    setGhosts((g) => [
      ...g,
      {
        id,
        label: optionEl.textContent ?? "",
        top,
        left,
        width: optRect.width,
        height: optRect.height,
        travel: -travel,
        mode,
      },
    ]);
    return id;
  }, []);

  const removeGhost = (id: number) => setGhosts((g) => g.filter((x) => x.id !== id));

  const choose = useCallback(
    (value: string) => {
      if (value === selected) return;
      const prevValue = selected;
      const el = optionRefs.current[value];
      setSelected(value);
      const opt = options.find((o) => o.value === value);
      announce(prevValue ? `Vote changed to ${opt?.label}` : `Voted: ${opt?.label}`);
      if (el) spawnGhost(el, "drop");
      if (prevValue) {
        const prevEl = optionRefs.current[prevValue];
        if (prevEl) spawnGhost(prevEl, "retract");
      }
    },
    [selected, options, announce, spawnGhost]
  );

  const onKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    const idx = options.findIndex((o) => o.value === (selected ?? options[0]?.value));
    let next = -1;
    if (e.key === "ArrowLeft" || e.key === "ArrowUp") next = (idx - 1 + options.length) % options.length;
    else if (e.key === "ArrowRight" || e.key === "ArrowDown") next = (idx + 1) % options.length;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = options.length - 1;
    else return;
    e.preventDefault();
    const target = options[next];
    if (target) {
      choose(target.value);
      optionRefs.current[target.value]?.focus();
    }
  };

  return (
    <div ref={wrapRef} className={`relative flex w-64 flex-col items-center ${className}`}>
      <style>{`
        @keyframes nsui-radio-ballot-drop {
          0% { transform: translateY(0) rotate(0deg) scaleY(1); opacity: 1; }
          18% { transform: translateY(calc(var(--nsui-travel) * 0.12)) rotate(-7deg) scaleY(0.9); opacity: 1; }
          40% { transform: translateY(calc(var(--nsui-travel) * 0.55)) rotate(6deg) scaleY(0.82); opacity: 1; }
          62% { transform: translateY(calc(var(--nsui-travel) * 0.85)) rotate(-4deg) scaleY(0.78); opacity: 0.85; }
          100% { transform: translateY(var(--nsui-travel)) rotate(2deg) scaleY(0.72); opacity: 0; }
        }
        @keyframes nsui-ballot-retract {
          0% { transform: translateY(var(--nsui-travel)) rotate(2deg) scaleY(0.72); opacity: 0; }
          20% { transform: translateY(calc(var(--nsui-travel) * 0.7)) rotate(-5deg) scaleY(0.8); opacity: 0.7; }
          55% { transform: translateY(calc(var(--nsui-travel) * 0.25)) rotate(4deg) scaleY(0.9); opacity: 0.6; }
          100% { transform: translateY(0) rotate(0deg) scaleY(1); opacity: 0; }
        }
        @keyframes nsui-radio-ballot-drop-reduced {
          0% { transform: translateY(0); opacity: 1; }
          100% { transform: translateY(calc(var(--nsui-travel) * 0.4)); opacity: 0; }
        }
        @keyframes nsui-ballot-retract-reduced {
          0% { transform: translateY(calc(var(--nsui-travel) * 0.4)); opacity: 0; }
          100% { transform: translateY(0); opacity: 0; }
        }
      `}</style>

      {/* the ballot box: hairline body with a slot notch facing the options below it */}
      <div
        ref={boxRef}
        aria-hidden="true"
        className="relative z-10 h-14 w-44 rounded-t-[12px] border border-border bg-surface"
      >
        <div className="absolute inset-x-0 -bottom-px flex justify-center">
          <div className="h-[3px] w-20 rounded-full border border-border bg-background" />
        </div>
      </div>

      {/* ghost overlay: decorative paper-drop clones, never focusable */}
      <div aria-hidden="true" className="pointer-events-none absolute inset-0 z-20 overflow-visible">
        {ghosts.map((g) => (
          <div
            key={g.id}
            onAnimationEnd={() => removeGhost(g.id)}
            className="absolute rounded-[4px] border border-border bg-[#f4f2ec] shadow-[0_4px_10px_-4px_rgba(0,0,0,0.35)]"
            style={
              {
                top: g.top,
                left: g.left,
                width: g.width,
                height: g.height,
                "--nsui-travel": `${g.travel}px`,
                animation: `${
                  reducedRef.current
                    ? g.mode === "drop"
                      ? "nsui-radio-ballot-drop-reduced"
                      : "nsui-ballot-retract-reduced"
                    : g.mode === "drop"
                      ? "nsui-radio-ballot-drop"
                      : "nsui-ballot-retract"
                } ${reducedRef.current ? 260 : 620}ms cubic-bezier(0.3,0.6,0.3,1) forwards`,
              } as React.CSSProperties
            }
          >
            <span className="flex h-full items-center justify-center px-2 font-mono text-[11px] text-[#171717]">
              {g.label}
            </span>
          </div>
        ))}
      </div>

      <div
        role="radiogroup"
        aria-label={label}
        aria-describedby={`${reactId}-hint`}
        onKeyDown={onKeyDown}
        className="mt-6 flex w-full flex-col gap-2.5"
      >
        {options.map((opt) => {
          const checked = opt.value === selected;
          return (
            <button
              key={opt.value}
              ref={(el) => {
                optionRefs.current[opt.value] = el;
              }}
              type="button"
              role="radio"
              aria-checked={checked}
              tabIndex={checked || (!selected && opt.value === options[0]?.value) ? 0 : -1}
              onClick={() => choose(opt.value)}
              className="group relative overflow-visible rounded-[6px] border border-border bg-[#f4f2ec] px-4 py-3 text-left outline-none transition-[transform,box-shadow] duration-150 ease-out motion-reduce:transition-none focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background"
            >
              {/* peeling corner: lifts on hover of an unselected slip */}
              <span
                aria-hidden="true"
                className="absolute right-0 top-0 h-4 w-4 origin-top-right rounded-bl-[6px] bg-[#e7e3d8] shadow-[0_1px_2px_rgba(0,0,0,0.15)] transition-transform duration-200 ease-out group-hover:-translate-y-0.5 group-hover:translate-x-0.5 group-hover:rotate-[8deg] motion-reduce:transition-none"
                style={{ clipPath: "polygon(0 0, 100% 0, 100% 100%)" }}
              />
              <span className="flex items-center justify-between gap-3">
                <span className="font-mono text-sm text-[#171717]">{opt.label}</span>
                <span
                  aria-hidden="true"
                  className={`h-2 w-2 rounded-full border border-[#171717]/40 transition-colors ${
                    checked ? "bg-[#171717]" : "bg-transparent"
                  }`}
                />
              </span>
            </button>
          );
        })}
      </div>

      <div ref={liveRef} aria-live="polite" aria-atomic="true" className="sr-only" />
      <p className="sr-only" id={`${reactId}-hint`}>
        Use arrow keys to change your vote.
      </p>
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
} from "react";

// ---------------------------------------------------------------------------
// PinTumbler — a vertical radio group whose single choice is embodied by
// exactly one indicator: a --foreground DOT sitting on the checked row's
// notch. It only ever looks like a line while it is actually in transit —
// re-selecting elongates it into a thin traveling pill that stretches
// toward the new row, then contracts back down to a dot once it arrives.
// At rest it is never a line: rest state and travel state are visually
// distinct on purpose, so a glance at a settled control shows a dot, never
// mid-motion residue. Distance traveled (both the trip duration and how
// far it stretches) reads as how far apart the options are in the list —
// reorder the options and the trip's duration changes with them.
//
// MECHANISM: the indicator is one absolutely-positioned element whose
// `top`, `height` AND `width` (not a scale transform) are driven together
// via the Web Animations API against measured row centers (a
// ResizeObserver keeps those centers correct across re-layout): in the
// stretch phase, its leading edge eases straight to the new row's center
// while its trailing edge stays put and its width narrows from the dot's
// diameter down to the thin traveling thickness, so it visibly elongates
// into a line across whatever sits between old and new; then, in the
// settle phase, the trailing edge eases up to meet the leading one while
// the width widens back out, contracting the line back into a dot exactly
// where it stopped. Horizontal centering never needs its own keyframe —
// the element sits at the rail column's horizontal center with a permanent
// `translateX(-50%)`, so as WAAPI mutates its inline width every frame the
// browser recenters it for free. Both phases use a single no-overshoot
// ease-out curve (control points never exceed the endpoint) — the edges
// and the width move monotonically toward their targets and stop, they
// never overshoot past the destination and bounce back. Passing an
// intermediate notch schedules a brief opacity/scale "tick" on that notch,
// timed proportionally to where the line's leading edge is along the
// travel phase.
//
// STRUCTURE: real native `<input type="radio">` per row, visually hidden
// but present and focusable — roving arrow keys, form participation, and
// checked-state announcements all come free from the browser, nothing is
// reimplemented. aria-checked is inherent to `<input type=radio>` and
// flips the instant the browser commits the change; the dot/line animation
// is a trailing, aria-hidden visual layer on top of that, never a gate on
// it. Each row is a full-width `<label>` (min 44px tall) so the hit area
// covers the whole row, not just the hidden input.
//
// Reduced motion: the indicator's position, height and width update with
// no animation — straight teleport to the new row as a dot, still fully
// legible and functional.
//
// Pure DOM/CSS, no canvas. Ink is token-relative only: --foreground for
// the dot/line, --border for notches and the rail, --ns-muted for resting
// label text, --ns-accent solely for the keyboard focus ring.
//
// Distinct from segmented-control-fling: segmented-control-fling is a horizontal segmented
// control with a draggable, flingable pill and release-velocity physics.
// PinTumbler is a stacked vertical radio *list* — no dragging, selection
// only ever changes via click or native radio keyboard roving — whose
// indicator visibly commutes between the old and new row along a fixed
// rail, so the trip itself communicates list distance.
// ---------------------------------------------------------------------------

// Single no-overshoot ease-out: both control points' y stays at the 1.0
// endpoint, so the curve decelerates hard into its target and never swings
// past it — no spring, no bounce, on any of the indicator's position,
// length or width.
const TRAVEL_EASE = "cubic-bezier(0.22, 1, 0.36, 1)";
const PER_ROW_MS = 65;
const MIN_TRAVEL_MS = 90;
const SETTLE_MS = 160;
const TICK_MS = 220;

// Rest shape: a DOT_SIZE x DOT_SIZE circle (border-radius: full), sized to
// match the notch's own 10px footprint so the checked row reads as "its
// notch, filled in" rather than a second, differently-shaped glyph. While
// traveling the indicator narrows to LINE_W — a thin pill — for the
// duration of the trip only; DOT_SIZE is also what the bridge span's cap
// is measured in (see bridgeTop/bridgeHeight below), so the line's start
// and end land exactly on the outer edges of the dot boxes it grew out of.
const DOT_SIZE = 10;
const LINE_W = 3;
const RAIL_COL = 28;

export interface PinTumblerOption {
  /** Stable identifier, used as the native radio's value. */
  value: string;
  label: string;
  /** Optional secondary line, e.g. price or latency. */
  description?: string;
}

export interface PinTumblerProps {
  /** Accessible name for the radiogroup, e.g. "Shipping speed". */
  label: string;
  /** the radio options */
  options: PinTumblerOption[];
  /** Controlled selected value. */
  value?: string;
  /** Initial value when uncontrolled. @default options[0]?.value */
  defaultValue?: string;
  /** called with the new value when a different option is selected */
  onValueChange?: (value: string) => void;
  /** Shared `name` for the native radios. @default a generated id */
  name?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

type Vars = React.CSSProperties & Record<`--${string}`, string | number>;

function useReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

export function PinTumbler({
  label,
  options,
  value,
  defaultValue,
  onValueChange,
  name,
  className = "",
}: PinTumblerProps) {
  const generatedName = useId();
  const groupName = name ?? generatedName;

  const isControlled = value !== undefined;
  const [internal, setInternal] = useState(
    () => defaultValue ?? options[0]?.value ?? ""
  );
  const committed = isControlled ? (value as string) : internal;
  const committedIndex = Math.max(
    0,
    options.findIndex((o) => o.value === committed)
  );

  const reducedMotion = useReducedMotion();

  const groupRef = useRef<HTMLDivElement | null>(null);
  const rowRefs = useRef<(HTMLLabelElement | null)[]>([]);
  const pinRef = useRef<HTMLDivElement | null>(null);
  const [rowOffsets, setRowOffsets] = useState<number[]>([]);

  const measure = useCallback(() => {
    const group = groupRef.current;
    if (!group) return;
    const groupTop = group.getBoundingClientRect().top;
    const offsets = rowRefs.current.map((el) => {
      if (!el) return 0;
      const r = el.getBoundingClientRect();
      return r.top - groupTop + r.height / 2;
    });
    setRowOffsets(offsets);
  }, []);

  useLayoutEffect(() => {
    measure();
    // options.length affects row count; re-measure when it changes.
  }, [measure, options.length]);

  useEffect(() => {
    const group = groupRef.current;
    if (!group || typeof ResizeObserver === "undefined") return;
    const ro = new ResizeObserver(() => measure());
    ro.observe(group);
    return () => ro.disconnect();
  }, [measure]);

  const commit = useCallback(
    (v: string) => {
      if (!isControlled) setInternal(v);
      if (v !== committed) onValueChange?.(v);
    },
    [isControlled, committed, onValueChange]
  );

  // --- pin animation ---------------------------------------------------
  // `restIndex` is the single source of truth for "where the pin is
  // actually rendered right now" — it only ever advances in `onfinish`,
  // i.e. once a travel has genuinely completed. Deriving `prev` from it
  // (rather than a separately-tracked ref updated eagerly at effect start)
  // matters the moment a row is re-selected before the in-flight travel
  // finishes: cancelling the live Animation reverts the element to its
  // underlying inline style, which is exactly `rowOffsets[restIndex]` —
  // so the next leg's start keyframe is guaranteed to match what's on
  // screen at that instant. An eagerly-updated ref would already point at
  // the (unfinished) target, so the new leg would start its first
  // keyframe from a row the pin never actually reached, and the browser
  // renders that as an instant teleport before reversing back toward the
  // real new target — visible as a jarring step mid-glide on fast
  // re-selection (rapid clicks or held arrow-key roving).
  const [restIndex, setRestIndex] = useState(committedIndex);
  const animRef = useRef<Animation | null>(null);
  const timeoutsRef = useRef<number[]>([]);
  const [tickSet, setTickSet] = useState<Set<number>>(() => new Set());

  useLayoutEffect(() => {
    const prev = restIndex;
    if (committedIndex === prev) return;

    const pin = pinRef.current;
    const fromCenterY = rowOffsets[prev];
    const toCenterY = rowOffsets[committedIndex];

    // Start the new leg from the indicator's LIVE on-screen box — read its
    // computed `top`/`height`/`width` *before* cancelling the in-flight
    // animation. cancel() reverts the element to its inline style
    // (rowOffsets[restIndex] at the resting DOT_SIZE box), but restIndex
    // still points at the row this travel started from (it only advances in
    // onfinish), so seeding the new leg from rowOffsets[prev]'s resting dot
    // on every re-selection would snap the indicator back to a fully-formed
    // dot even mid-stretch — a visible jump. Reading getComputedStyle first
    // lets the interrupt leg begin from whatever box it actually is right
    // now — a dot, a mid-morph pill, or anything between.
    let fromTop =
      fromCenterY !== undefined ? fromCenterY - DOT_SIZE / 2 : undefined;
    let fromHeight = DOT_SIZE;
    let fromWidth = DOT_SIZE;
    if (pin && animRef.current) {
      const cs = getComputedStyle(pin);
      const liveTop = parseFloat(cs.top);
      const liveHeight = parseFloat(cs.height);
      const liveWidth = parseFloat(cs.width);
      if (
        !Number.isNaN(liveTop) &&
        !Number.isNaN(liveHeight) &&
        !Number.isNaN(liveWidth)
      ) {
        fromTop = liveTop;
        fromHeight = liveHeight;
        fromWidth = liveWidth;
      }
    }

    timeoutsRef.current.forEach((id) => window.clearTimeout(id));
    timeoutsRef.current = [];
    animRef.current?.cancel();
    animRef.current = null;
    setTickSet(new Set());

    if (
      reducedMotion ||
      !pin ||
      typeof pin.animate !== "function" ||
      fromTop === undefined ||
      fromCenterY === undefined ||
      toCenterY === undefined
    ) {
      setRestIndex(committedIndex);
      return;
    }

    const toTop = toCenterY - DOT_SIZE / 2;
    // The line's leading edge reaches the destination first; its trailing
    // edge stays anchored at the far end of [fromCenterY, toCenterY] until
    // the settle phase catches it up. That single box — spanning exactly the
    // two row centers plus the *dot's* own half-caps, i.e. the union of the
    // two rest-dot boxes at fromCenterY and toCenterY — is what "the line
    // stretches toward where it's going" means geometrically: it never
    // reaches further than where the dot's own edge would already sit at
    // either end. No keyframe here ever positions an edge past its own
    // destination, so there is nothing to bounce back from.
    const bridgeTop = Math.min(fromCenterY, toCenterY) - DOT_SIZE / 2;
    const bridgeHeight = Math.abs(toCenterY - fromCenterY) + DOT_SIZE;

    const dist = Math.abs(committedIndex - prev);
    const travelMs = Math.max(MIN_TRAVEL_MS, dist * PER_ROW_MS);
    const total = travelMs + SETTLE_MS;
    const arriveAt = travelMs / total;

    const anim = pin.animate(
      [
        {
          top: `${fromTop}px`,
          height: `${fromHeight}px`,
          width: `${fromWidth}px`,
          offset: 0,
          easing: TRAVEL_EASE,
        },
        {
          top: `${bridgeTop}px`,
          height: `${bridgeHeight}px`,
          width: `${LINE_W}px`,
          offset: arriveAt,
          easing: TRAVEL_EASE,
        },
        {
          top: `${toTop}px`,
          height: `${DOT_SIZE}px`,
          width: `${DOT_SIZE}px`,
          offset: 1,
        },
      ],
      { duration: total, fill: "forwards" }
    );
    animRef.current = anim;
    anim.onfinish = () => {
      // Deliberately not cancelling here: the animation's `fill: "forwards"`
      // holds the exact final keyframe (the resting dot box at
      // `toTop`/`DOT_SIZE`/`DOT_SIZE`), which is the same value `restIndex`
      // now resolves to via the resting inline style. Cancelling immediately
      // would strip the animation's held effect before this `setRestIndex`
      // has actually re-rendered, snapping the element back to the
      // *previous* underlying style for one frame — a visible flash/step
      // right at the end of every single travel. Leaving the finished
      // animation in place keeps the on-screen
      // value continuous; it's reclaimed for free by the
      // `animRef.current?.cancel()` at the top of this effect the next time
      // a travel actually starts.
      setRestIndex(committedIndex);
    };

    const dir = committedIndex > prev ? 1 : -1;
    for (let idx = prev + dir; idx !== committedIndex; idx += dir) {
      const frac = Math.abs(idx - prev) / dist;
      const t = frac * travelMs;
      const onId = window.setTimeout(() => {
        setTickSet((s) => new Set(s).add(idx));
      }, t);
      const offId = window.setTimeout(() => {
        setTickSet((s) => {
          if (!s.has(idx)) return s;
          const next = new Set(s);
          next.delete(idx);
          return next;
        });
      }, t + TICK_MS);
      timeoutsRef.current.push(onId, offId);
    }
    // `restIndex` is read (as `prev`) above; adding it here is safe — once
    // `onfinish` advances it to `committedIndex`, this effect reruns, sees
    // `committedIndex === prev`, and bails on the very first line.
  }, [committedIndex, reducedMotion, rowOffsets, restIndex]);

  useEffect(() => {
    return () => {
      timeoutsRef.current.forEach((id) => window.clearTimeout(id));
      animRef.current?.cancel();
    };
  }, []);

  const measured = rowOffsets.length === options.length && options.length > 0;
  const railTop = measured ? rowOffsets[0] : 0;
  const railHeight = measured ? rowOffsets[rowOffsets.length - 1] - railTop : 0;
  const pinTop = (rowOffsets[restIndex] ?? 0) - DOT_SIZE / 2;

  return (
    <div className={`ns-pt-wrap ${className}`}>
      <div
        ref={groupRef}
        role="radiogroup"
        aria-label={label}
        data-reduced={reducedMotion || undefined}
        className="ns-pt-group"
        style={
          {
            "--pt-rail-col": `${RAIL_COL}px`,
          } as Vars
        }
      >
        {options.length > 1 && (
          <div
            aria-hidden="true"
            className="ns-pt-rail"
            style={{
              top: railTop,
              height: Math.max(0, railHeight),
              opacity: measured ? 1 : 0,
            }}
          />
        )}

        {options.map((opt, i) => (
          <label
            key={opt.value}
            ref={(el) => {
              rowRefs.current[i] = el;
            }}
            className="ns-pt-row"
          >
            <input
              type="radio"
              className="ns-pt-input"
              name={groupName}
              value={opt.value}
              checked={i === committedIndex}
              onChange={() => commit(opt.value)}
            />
            <span className="ns-pt-visual">
              <span className="ns-pt-rail-col">
                <span
                  className="ns-pt-notch"
                  data-ticking={tickSet.has(i) || undefined}
                />
              </span>
              <span className="ns-pt-text">
                <span className="ns-pt-label-text" data-checked={i === committedIndex || undefined}>
                  {opt.label}
                </span>
                {opt.description && (
                  <span className="ns-pt-desc">{opt.description}</span>
                )}
              </span>
            </span>
          </label>
        ))}

        <div
          ref={pinRef}
          aria-hidden="true"
          className="ns-pt-pin"
          style={{
            top: pinTop,
            height: DOT_SIZE,
            width: DOT_SIZE,
            opacity: measured ? 1 : 0,
          }}
        />
      </div>

      <style>{`
        .ns-pt-wrap {
          display: block;
        }
        .ns-pt-group {
          position: relative;
          display: flex;
          flex-direction: column;
        }
        .ns-pt-rail {
          position: absolute;
          left: calc(var(--pt-rail-col) / 2 - 0.5px);
          width: 1px;
          background: var(--border);
          pointer-events: none;
        }
        .ns-pt-row {
          position: relative;
          display: block;
          min-height: 44px;
          cursor: pointer;
          -webkit-tap-highlight-color: transparent;
        }
        .ns-pt-input {
          position: absolute;
          width: 1px;
          height: 1px;
          padding: 0;
          margin: -1px;
          overflow: hidden;
          clip: rect(0, 0, 0, 0);
          white-space: nowrap;
          border: 0;
          outline: none;
        }
        .ns-pt-visual {
          display: flex;
          align-items: center;
          gap: 4px;
          min-height: 44px;
          padding: 6px 12px 6px 0;
          border-radius: 8px;
          transition: background-color 140ms ease;
        }
        .ns-pt-row:hover .ns-pt-visual {
          background: color-mix(in oklab, var(--foreground) 4%, transparent);
        }
        .ns-pt-input:focus-visible + .ns-pt-visual {
          outline: 2px solid var(--ns-accent);
          outline-offset: 2px;
        }
        .ns-pt-rail-col {
          flex: 0 0 var(--pt-rail-col);
          display: flex;
          align-items: center;
          justify-content: center;
        }
        .ns-pt-notch {
          width: 10px;
          height: 10px;
          border-radius: 3px;
          border: 1px solid var(--border);
          box-sizing: border-box;
          transform: scale(1);
          transition: transform 160ms ease, border-color 160ms ease;
        }
        .ns-pt-notch[data-ticking] {
          border-color: var(--foreground);
          transform: scale(1.35);
        }
        .ns-pt-text {
          display: flex;
          flex-direction: column;
          gap: 1px;
          min-width: 0;
        }
        .ns-pt-label-text {
          font-size: 0.875rem;
          color: var(--ns-muted);
          transition: color 160ms ease;
        }
        .ns-pt-label-text[data-checked] {
          color: var(--foreground);
          font-weight: 500;
        }
        .ns-pt-desc {
          font-size: 0.75rem;
          color: var(--ns-muted);
        }
        .ns-pt-pin {
          /* left sits at the rail column's center and stays there via a
             permanent translateX(-50%) — width is animated (dot <-> thin
             traveling pill) straight through JS/WAAPI inline styles, so
             centering can't be a fixed calc() against a constant width. */
          position: absolute;
          left: calc(var(--pt-rail-col) / 2);
          transform: translateX(-50%);
          border-radius: 9999px;
          background: var(--foreground);
          pointer-events: none;
        }

        .ns-pt-group[data-reduced] .ns-pt-notch,
        .ns-pt-group[data-reduced] .ns-pt-label-text {
          transition: none;
        }

        @media (prefers-reduced-motion: reduce) {
          .ns-pt-notch,
          .ns-pt-label-text,
          .ns-pt-visual {
            transition: none;
          }
        }
      `}</style>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// RaftMoor — a thin presence rail down the document's edge. Each
// collaborator is a 20px initialed chip whose y is their live scroll
// fraction through the document, set directly (no easing curve on the
// mapping itself). When two or more chips land within CLUSTER_GAP of each
// other they "raft up": the earliest-arrived stays flush to the rail, every
// later arrival moors one chip-width further out, so co-location is legible
// instead of collapsing into a "+n" count. Motion between targets is a
// per-chip critically-damped spring (settles well under 400ms) integrated
// in one rAF loop that sleeps once every chip is at rest; a separate 1.5s
// interval (independent of the spring) tracks per-collaborator idle time and
// eases opacity to 0.5 past the threshold, since a "have they moved
// recently" check has nothing to do with spatial motion. DOM+SVG-free —
// plain absolutely-positioned buttons, transforms written by ref, no React
// state on the hot path. Colors are token classes only; --ns-accent never
// touches a resting chip, only the hover/focus state of the jump button.
// ---------------------------------------------------------------------------

export interface RaftMoorCollaborator {
  /** stable identity — used for React keys, DOM refs and raft bookkeeping */
  id: string;
  /** full name, used in the accessible name */
  name: string;
  /** 1–2 chars shown in the chip; derived from `name` when omitted */
  initials?: string;
  /** 0..1 — fraction through the document. The governing scalar: sets tag y directly. */
  fraction: number;
  /** id of the heading/section element this collaborator is nearest to */
  sectionId: string;
  /** human label for that section, used in the accessible name */
  sectionLabel: string;
}

const CHIP = 20; // px — chip is 20×20, radius-6
const GAP = 6; // px between raft slots
const SLOT = CHIP + GAP;
const CLUSTER_GAP = 24; // px — chips within this vertical distance raft together
const STIFFNESS = 260; // px/s² per px of error
const DAMPING = 30; // just under critical — settles well inside 400ms, no overshoot to speak of
const IDLE_POLL_MS = 1500;

function clamp01(n: number) {
  return Math.max(0, Math.min(1, n));
}

function initialsOf(c: RaftMoorCollaborator) {
  if (c.initials) return c.initials.slice(0, 2).toUpperCase();
  return c.name
    .split(/\s+/)
    .map((w) => w[0] ?? "")
    .join("")
    .slice(0, 2)
    .toUpperCase();
}

function labelFor(c: RaftMoorCollaborator) {
  const pct = Math.round(clamp01(c.fraction) * 100);
  return `Jump to ${c.name}, ${pct}% through, section ${c.sectionLabel}`;
}

export function RaftMoor({
  collaborators,
  /** ms of no fraction/section change before a chip eases to 50% opacity */
  idleThresholdMs = 60000,
  /** rail height as a fraction of viewport height */
  railHeightVh = 70,
  className = "",
}: {
  collaborators: RaftMoorCollaborator[];
  idleThresholdMs?: number;
  railHeightVh?: number;
  className?: string;
}) {
  const btnRefs = useRef<Map<string, HTMLButtonElement>>(new Map());
  const collabRef = useRef(collaborators);
  const reducedRef = useRef(false);
  const apiRef = useRef<{ recompute: () => void; idleTick: () => void } | null>(null);

  useEffect(() => {
    collabRef.current = collaborators;
    apiRef.current?.recompute();
    apiRef.current?.idleTick();
  }, [collaborators]);

  const jump = useCallback((c: RaftMoorCollaborator) => {
    const target = document.getElementById(c.sectionId);
    if (!target) return;
    const reduced = reducedRef.current;
    target.scrollIntoView({ behavior: reduced ? "auto" : "smooth", block: "start" });
    const focusTarget = () => {
      if (!target.hasAttribute("tabindex")) target.setAttribute("tabindex", "-1");
      target.focus({ preventScroll: true });
    };
    // let the smooth scroll actually land before yanking focus into view
    if (reduced) focusTarget();
    else window.setTimeout(focusTarget, 450);
  }, []);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    reducedRef.current = mq.matches;

    let H = window.innerHeight * (railHeightVh / 100);

    type Phys = { x: number; y: number; vx: number; vy: number };
    const phys = new Map<string, Phys>();
    // per-id: the timestamp this id most recently joined its current raft,
    // and the set of raft-mates it joined with (used to tell "still rafted
    // with someone" apart from "just arrived at a new stretch")
    const arrival = new Map<string, { at: number; neighbors: Set<string> }>();
    const moved = new Map<string, { sig: string; at: number }>();
    const targetX = new Map<string, number>();
    const targetY = new Map<string, number>();

    let raf = 0;
    let last = 0;

    const prune = () => {
      const ids = new Set(collabRef.current.map((c) => c.id));
      for (const m of [phys, arrival, moved, targetX, targetY] as Map<string, unknown>[]) {
        for (const id of Array.from(m.keys())) if (!ids.has(id)) m.delete(id);
      }
      for (const id of Array.from(btnRefs.current.keys())) {
        if (!ids.has(id)) btnRefs.current.delete(id);
      }
    };

    // clusters chips within CLUSTER_GAP of each other and assigns each one a
    // raft slot by arrival order: the id that has been continuously rafted
    // (sharing at least one prior raft-mate) longest gets slot 0 (flush to
    // the rail); everyone newer to this particular raft moors further out.
    const layoutSlots = () => {
      const list = collabRef.current;
      list.forEach((c) => targetY.set(c.id, clamp01(c.fraction) * H));

      const order = [...list].sort((a, b) => (targetY.get(a.id) ?? 0) - (targetY.get(b.id) ?? 0));
      const clusters: RaftMoorCollaborator[][] = [];
      let cur: RaftMoorCollaborator[] = [];
      let prevY = -Infinity;
      for (const c of order) {
        const y = targetY.get(c.id) ?? 0;
        if (cur.length && y - prevY > CLUSTER_GAP) {
          clusters.push(cur);
          cur = [];
        }
        cur.push(c);
        prevY = y;
      }
      if (cur.length) clusters.push(cur);

      for (const cluster of clusters) {
        if (cluster.length === 1) {
          const id = cluster[0]?.id;
          if (id) {
            targetX.set(id, 0);
            arrival.delete(id); // solo now — a future raft here is a fresh arrival
          }
          continue;
        }
        const ids = new Set(cluster.map((c) => c.id));
        for (const c of cluster) {
          const others = new Set(ids);
          others.delete(c.id);
          const prev = arrival.get(c.id);
          let stillTogether = false;
          if (prev) {
            for (const id of prev.neighbors) {
              if (others.has(id)) {
                stillTogether = true;
                break;
              }
            }
          }
          arrival.set(c.id, {
            at: stillTogether && prev ? prev.at : performance.now(),
            neighbors: others,
          });
        }
        const ranked = [...cluster].sort((a, b) => {
          const ta = arrival.get(a.id)?.at ?? 0;
          const tb = arrival.get(b.id)?.at ?? 0;
          return ta !== tb ? ta - tb : a.id.localeCompare(b.id);
        });
        ranked.forEach((c, i) => targetX.set(c.id, i * SLOT));
      }
    };

    const springStep = (now: number) => {
      const dt = Math.min(Math.max((now - last) / 1000, 0.001), 1 / 30);
      last = now;
      let settled = true;
      for (const c of collabRef.current) {
        const p = phys.get(c.id);
        if (!p) continue;
        const tx = targetX.get(c.id) ?? p.x;
        const ty = targetY.get(c.id) ?? p.y;
        p.vx += (STIFFNESS * (tx - p.x) - DAMPING * p.vx) * dt;
        p.x += p.vx * dt;
        p.vy += (STIFFNESS * (ty - p.y) - DAMPING * p.vy) * dt;
        p.y += p.vy * dt;
        if (Math.abs(p.vx) > 0.4 || Math.abs(p.vy) > 0.4 || Math.abs(tx - p.x) > 0.25 || Math.abs(ty - p.y) > 0.25) {
          settled = false;
        }
        const btn = btnRefs.current.get(c.id);
        if (btn) btn.style.transform = `translate3d(${p.x}px, ${p.y}px, 0)`;
      }
      raf = settled ? 0 : requestAnimationFrame(springStep);
    };
    const wake = () => {
      if (!raf) {
        last = performance.now();
        raf = requestAnimationFrame(springStep);
      }
    };

    const recompute = () => {
      prune();
      layoutSlots();
      const list = collabRef.current;

      // place any chip that has no physics state yet directly at its target
      // (first appearance never "flies in" from 0,0) and reveal it
      for (const c of list) {
        if (!phys.has(c.id)) {
          const x = targetX.get(c.id) ?? 0;
          const y = targetY.get(c.id) ?? 0;
          phys.set(c.id, { x, y, vx: 0, vy: 0 });
          const btn = btnRefs.current.get(c.id);
          if (btn) {
            btn.style.transform = `translate3d(${x}px, ${y}px, 0)`;
            btn.style.opacity = "1";
          }
        }
      }

      if (reducedRef.current) {
        for (const c of list) {
          const p = phys.get(c.id);
          if (!p) continue;
          p.x = targetX.get(c.id) ?? p.x;
          p.y = targetY.get(c.id) ?? p.y;
          p.vx = 0;
          p.vy = 0;
          const btn = btnRefs.current.get(c.id);
          if (btn) btn.style.transform = `translate3d(${p.x}px, ${p.y}px, 0)`;
        }
      } else {
        wake();
      }
    };

    const idleTick = () => {
      const now = Date.now();
      for (const c of collabRef.current) {
        const sig = `${c.fraction.toFixed(4)}|${c.sectionId}`;
        const prev = moved.get(c.id);
        if (!prev || prev.sig !== sig) moved.set(c.id, { sig, at: now });
        const lastAt = moved.get(c.id)?.at ?? now;
        const idle = now - lastAt > idleThresholdMs;
        const btn = btnRefs.current.get(c.id);
        if (!btn) continue;
        btn.style.opacity = idle ? "0.5" : "1";
        const label = labelFor(c);
        if (btn.getAttribute("aria-label") !== label) btn.setAttribute("aria-label", label);
      }
    };

    apiRef.current = { recompute, idleTick };
    recompute();
    idleTick();

    const onResize = () => {
      H = window.innerHeight * (railHeightVh / 100);
      recompute();
    };
    const onReducedChange = () => {
      reducedRef.current = mq.matches;
      recompute();
    };
    window.addEventListener("resize", onResize);
    mq.addEventListener("change", onReducedChange);
    const interval = window.setInterval(idleTick, IDLE_POLL_MS);

    return () => {
      cancelAnimationFrame(raf);
      window.clearInterval(interval);
      window.removeEventListener("resize", onResize);
      mq.removeEventListener("change", onReducedChange);
      apiRef.current = null;
    };
    // idleThresholdMs / railHeightVh changing mid-life is rare enough that a
    // remount (picking up the new value) is the right cost/complexity trade
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [idleThresholdMs, railHeightVh]);

  return (
    <nav
      aria-label="Collaborators' positions in this document"
      className={`fixed left-4 top-1/2 z-40 -translate-y-1/2 ${className}`}
      style={{ height: `${railHeightVh}vh` }}
    >
      <div aria-hidden className="absolute left-0 top-0 h-full w-px bg-border" />
      <ul className="relative m-0 h-full list-none p-0">
        {collaborators.map((c) => (
          <li key={c.id} className="absolute left-0 top-0 m-0 p-0">
            <button
              type="button"
              ref={(el) => {
                if (el) btnRefs.current.set(c.id, el);
                else btnRefs.current.delete(c.id);
              }}
              onClick={() => jump(c)}
              aria-label={labelFor(c)}
              className="flex h-5 w-5 select-none items-center justify-center rounded-sm border border-border bg-background font-mono text-[9px] font-medium leading-none text-foreground opacity-0 transition-[opacity,border-color] duration-300 ease-out hover:border-ns-accent focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
            >
              <span aria-hidden>{initialsOf(c)}</span>
            </button>
          </li>
        ))}
      </ul>
    </nav>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// RangeLightTransit — an ambient convergence indicator modelled on maritime
// range lights (leading lights): a pair of navigation marks at different
// distances/heights that a pilot keeps vertically stacked ("in transit") to
// hold a safe channel course. Off the line the lights visibly separate; back
// on it, they read as one aligned pair (USCG / Trinity House leading-line
// marks). Used here for a status moment where two independent, slowly
// varying states are converging and briefly agreeing — distinct from a
// determinate progress bar or a binary connected/disconnected dot.
//
// The front (lower, closer) and rear (higher, farther) light each drift
// horizontally on their own sine, incommensurate periods (6.2s / 9.7s) so
// alignment is never on a fixed beat. A thin line always connects the two
// disc centres — vertical exactly when they share an X, visibly tilted
// otherwise — so the tilt straightening out IS the converging read. Its
// opacity has two components: a continuous "how close" glow that climbs as
// the horizontal gap shrinks, plus a 250ms brighten-in that only completes
// if the gap stays under the 3%-of-width alignment threshold continuously
// for that long. The arrival cue (both discs grow and gain a soft --foreground
// drop-shadow — a halo in dark theme, a deepening shadow in light theme, so
// it reads correctly off the same token in both directions with no per-theme
// branch) is GATED on that same 250ms dwell, then fires once, at the true
// local minimum of the gap inside the dwell, held 300ms then eased back over
// 600ms — never a single-frame flash. The dwell gate matters on both cues:
// two independent sines cross within the threshold constantly (every
// ~1.5-4s) just passing through, but only stay inside it for 250ms+ on a
// real transit crossing (roughly every 1.5-11s at these periods) — without
// the gate, the pulse would fire on every passing crossing and read as
// generic blinking, not converging. Pure DOM/SVG, refs-only hot path, no
// React state, no canvas.
// ---------------------------------------------------------------------------

const FRONT_AMP_FRAC = 0.18; // front light drift amplitude, fraction of card width
const FRONT_PERIOD_S = 6.2;
const FRONT_PHASE = 1.9; // rad, arbitrary — chosen so t0 sits at a nonzero offset
const REAR_AMP_FRAC = 0.14; // rear light drift amplitude, fraction of card width
const REAR_PERIOD_S = 9.7;
const REAR_PHASE = 4.3; // rad
const ALIGN_THRESHOLD_FRAC = 0.03; // "in transit" gap, fraction of card width
const APPROACH_WINDOW_FRAC = ALIGN_THRESHOLD_FRAC * 3; // where the continuous glow begins
const GUIDE_FLOOR_OPACITY = 0.12; // guideline is faint, never fully absent — see note below
const GUIDE_RAMP_MS = 250; // continuous dwell inside threshold before the line reads fully "in transit"
const PULSE_HOLD_MS = 300; // arrival cue held at full luminance
const PULSE_DECAY_MS = 600; // then eased back to baseline
const PULSE_GROW = 0.15; // disc radius growth at peak, fraction of base radius
const PULSE_SHADOW_MAX = 6; // drop-shadow blur radius (px) at peak
const FRONT_Y_FRAC = 0.78; // lower in the card (nearer light)
const REAR_Y_FRAC = 0.24; // higher in the card (farther light)
const MIN_DISC_R = 3;
const MAX_DISC_R = 7;
const DISC_R_FRAC = 0.05; // of min(w, h)
const REAR_R_SCALE = 0.75; // farther light reads visibly smaller

// FREEZE FRAME: reduced-motion renders a single frame at t = 1.753s via a
// fresh call to render() (no accumulated dwell state), so the dwell ramp
// term is always 0 there and the guideline shows the continuous glow term
// alone. At this instant gap = 1.32% of card width (inside the 3% threshold,
// still closing — a real approach, not an incidental touch) which puts that
// glow term at ~0.43 opacity: both discs visibly offset, the line visibly
// present but not fully bright, no arrival cue active. The full-alignment
// frame is deliberately avoided (the pulse would read as blown-out on a
// static frame) and so is a maximum-offset frame (the line is fully
// resting at its GUIDE_FLOOR_OPACITY there, the least structured option).
const FREEZE_T_S = 1.753;

function easeOutCubic(t: number): number {
  const u = 1 - t;
  return 1 - u * u * u;
}

export interface RangeLightTransitProps {
  /** label above the reading */
  label?: string;
  /** card height in px */
  height?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function RangeLightTransit({
  label = "Sync transit",
  height = 200,
  className = "",
}: RangeLightTransitProps) {
  const svgRef = useRef<SVGSVGElement>(null);
  const guideRef = useRef<SVGLineElement>(null);
  const frontRef = useRef<SVGCircleElement>(null);
  const rearRef = useRef<SVGCircleElement>(null);

  useEffect(() => {
    const svg = svgRef.current;
    const guide = guideRef.current;
    const front = frontRef.current;
    const rear = rearRef.current;
    if (!svg || !guide || !front || !rear) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    // fallbacks are CSS keywords, never literal colour values
    let fg = "currentColor";
    const readTokens = () => {
      const root = getComputedStyle(document.documentElement);
      fg = root.getPropertyValue("--foreground").trim() || "currentColor";
      front.style.fill = fg;
      rear.style.fill = fg;
      guide.style.stroke = fg;
    };

    let w = 0;
    let h = 0;
    let sized = false;

    const measure = () => {
      const rect = svg.getBoundingClientRect();
      if (rect.width < 2 || rect.height < 2) {
        sized = false;
        return;
      }
      w = rect.width;
      h = rect.height;
      svg.setAttribute("viewBox", `0 0 ${w} ${h}`);
      sized = true;
    };

    // -- per-frame gap state, refs only, never React state ------------------
    let insideSince: number | null = null;
    let prevDiff = Infinity;
    let approaching = false;
    let pulseFiredThisDwell = false;
    let pulseStartMs: number | null = null;

    const render = (tMs: number) => {
      if (!sized) return;
      const tS = tMs / 1000;
      const fx = FRONT_AMP_FRAC * Math.sin((2 * Math.PI * tS) / FRONT_PERIOD_S + FRONT_PHASE);
      const rx = REAR_AMP_FRAC * Math.sin((2 * Math.PI * tS) / REAR_PERIOD_S + REAR_PHASE);
      const diff = Math.abs(fx - rx);
      const within = diff < ALIGN_THRESHOLD_FRAC;

      if (within) {
        if (insideSince === null) insideSince = tMs;
      } else {
        insideSince = null;
        pulseFiredThisDwell = false;
        approaching = false;
      }
      const rampT = within && insideSince !== null ? Math.min(1, (tMs - insideSince) / GUIDE_RAMP_MS) : 0;

      // arrival cue fires once, at the true local minimum of the gap, but
      // only once the gap has genuinely dwelled inside the threshold for the
      // same 250ms the guideline needs — this is what keeps the cue off the
      // many fast, glancing crossings and reserves it for a real transit.
      const dwelledEnough = insideSince !== null && tMs - insideSince >= GUIDE_RAMP_MS;
      if (within) {
        if (diff < prevDiff) {
          approaching = true;
        } else if (approaching && !pulseFiredThisDwell && dwelledEnough) {
          pulseFiredThisDwell = true;
          pulseStartMs = tMs;
          approaching = false;
        }
      }
      prevDiff = diff;

      // max amplitude difference (18%+14%) means the raw gap spends over
      // half of any long window beyond the approach window entirely — a
      // pure closeness^2 term would leave the connecting line fully absent
      // more often than not, which reads as two unconnected drifting dots
      // rather than a pair converging. A small resting floor keeps the
      // reference line always faintly present (spec allows "dim or absent").
      const closeness = Math.max(0, Math.min(1, 1 - diff / APPROACH_WINDOW_FRAC));
      const approachOpacity = GUIDE_FLOOR_OPACITY + (0.55 - GUIDE_FLOOR_OPACITY) * closeness * closeness;
      const guideOpacity = within ? approachOpacity + (1 - approachOpacity) * easeOutCubic(rampT) : approachOpacity;

      let pulseFactor = 0;
      if (pulseStartMs !== null) {
        const since = tMs - pulseStartMs;
        if (since <= PULSE_HOLD_MS) pulseFactor = 1;
        else if (since <= PULSE_HOLD_MS + PULSE_DECAY_MS) {
          pulseFactor = 1 - (since - PULSE_HOLD_MS) / PULSE_DECAY_MS;
        } else {
          pulseFactor = 0;
          pulseStartMs = null;
        }
      }

      const side = Math.min(w, h);
      const baseR = Math.min(MAX_DISC_R, Math.max(MIN_DISC_R, side * DISC_R_FRAC));
      const discR = baseR * (1 + PULSE_GROW * pulseFactor);
      const rearR = discR * REAR_R_SCALE;
      const cx = w / 2;
      const frontX = cx + fx * w;
      const frontY = h * FRONT_Y_FRAC;
      const rearX = cx + rx * w;
      const rearY = h * REAR_Y_FRAC;

      front.setAttribute("cx", frontX.toFixed(2));
      front.setAttribute("cy", frontY.toFixed(2));
      front.setAttribute("r", discR.toFixed(2));
      rear.setAttribute("cx", rearX.toFixed(2));
      rear.setAttribute("cy", rearY.toFixed(2));
      rear.setAttribute("r", rearR.toFixed(2));

      guide.setAttribute("x1", frontX.toFixed(2));
      guide.setAttribute("y1", frontY.toFixed(2));
      guide.setAttribute("x2", rearX.toFixed(2));
      guide.setAttribute("y2", rearY.toFixed(2));
      guide.style.opacity = guideOpacity.toFixed(3);

      // One formula for both themes, no isDark branch: a --foreground
      // drop-shadow plus a small radius grow. Because fg is already the
      // token that flips per theme, this reads as a soft light-coloured
      // halo blooming around the disc in dark theme, and as a deepening
      // dark shadow around it in light theme — a literal brightness()
      // filter was tried here and clamped to a barely-visible +7.6% swing
      // against near-white --foreground in dark theme, so the cue is
      // carried by shadow + size instead of a filter that can clip.
      if (pulseFactor > 0) {
        const f = `drop-shadow(0 0 ${(PULSE_SHADOW_MAX * pulseFactor).toFixed(2)}px ${fg})`;
        front.style.filter = f;
        rear.style.filter = f;
      } else {
        front.style.filter = "none";
        rear.style.filter = "none";
      }
    };

    let raf = 0;
    let last = 0;
    let globalTMs = 0;
    let visible = true;

    const loop = (now: number) => {
      if (last === 0) last = now;
      globalTMs += Math.min(100, now - last);
      last = now;
      render(globalTMs);
      if (visible && !reduced) raf = requestAnimationFrame(loop);
      else raf = 0;
    };

    const mo = new MutationObserver(() => {
      readTokens();
      render(reduced ? FREEZE_T_S * 1000 : globalTMs);
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        measure();
        render(reduced ? FREEZE_T_S * 1000 : globalTMs);
      }, 120);
    };
    const ro = new ResizeObserver(onResize);
    ro.observe(svg);

    const io = new IntersectionObserver(
      (entries) => {
        visible = entries[0]?.isIntersecting ?? true;
        if (visible && !reduced && sized && !raf) {
          last = 0;
          raf = requestAnimationFrame(loop);
        }
      },
      { threshold: 0 }
    );
    io.observe(svg);

    const onVis = () => {
      if (document.hidden) {
        cancelAnimationFrame(raf);
        raf = 0;
      } else if (!reduced && sized && visible && !raf) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };
    document.addEventListener("visibilitychange", onVis);

    // no paint before the first token read
    readTokens();
    measure();

    if (reduced) {
      render(FREEZE_T_S * 1000);
    } else if (sized) {
      raf = requestAnimationFrame(loop);
    }

    return () => {
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      mo.disconnect();
      ro.disconnect();
      io.disconnect();
      document.removeEventListener("visibilitychange", onVis);
    };
  }, []);

  return (
    <div className={className}>
      <div className="flex items-baseline justify-between gap-3">
        <span className="font-mono text-[11px] tracking-wide text-ns-muted">
          {label.toUpperCase()}
        </span>
        <span className="font-mono text-[11px] tracking-wide text-ns-muted">RANGE LIGHTS</span>
      </div>
      <div
        role="img"
        aria-label={`${label}: two lights drifting independently, briefly aligning as they converge`}
        className="mt-2"
      >
        <svg ref={svgRef} aria-hidden="true" className="block w-full" style={{ height }}>
          <line ref={guideRef} strokeWidth={1.25} strokeLinecap="round" />
          <circle ref={rearRef} />
          <circle ref={frontRef} />
        </svg>
      </div>
      <div className="mt-1.5 flex items-center justify-between font-mono text-[11px] text-ns-muted">
        <span>FRONT {FRONT_PERIOD_S.toFixed(1)}s</span>
        <span>REAR {REAR_PERIOD_S.toFixed(1)}s</span>
      </div>
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";

// ---------------------------------------------------------------------------
// ChopPress — a rating / level input rendered as a row of seal impressions.
// Chosen levels are stamped solid with a short physical "thud" (scale
// 1.15 -> 1.0, ease-out-expo) while a single concentric ring in --border
// expands and fades outward, reading as paper taking the impression.
// Unfilled levels wait as faint --ns-muted outlines. Lowering the value drains
// marks right-to-left with a 30ms stagger, as if the ink is lifting off in
// sequence. Hovering (or focusing) a level dashes the outline of whichever
// marks would change if you committed there, without committing anything.
//
// Real ARIA radiogroup semantics underneath: one role="radio" per level,
// only the committed level's radio is aria-checked, roving tabindex, arrow
// keys move AND commit (Home/End jump to the ends), and each radio's
// accessible name reads "N of M" plus an optional word ("3 of 5 - High").
// The stamp is a purely visual layer on top — nothing here depends on a
// screen reader ever seeing the seal glyph. Reduced motion: stamps land and
// drain instantly, no scale/ring/stagger.
//
// Pure DOM/SVG/CSS — no canvas. All ink is token-relative: --foreground for
// the stamp body, --ns-muted for resting outlines, --border for the impression
// ring, --ns-accent only for the keyboard focus ring.
// ---------------------------------------------------------------------------

const PRESS_MS = 140; // press-landing scale, ease-out-expo
const RING_MS = 380; // impression ring expand + fade
const PRESS_FILL_MS = 90; // ink appears fast — a thud, not a fade-in
const DRAIN_FILL_MS = 170; // ink lifts gradually
const STAGGER_MS = 30; // per-mark delay, both directions

const SIZE_PX = { sm: 26, md: 34, lg: 42 } as const;

type Kind = "press" | "drain";

export interface ChopPressProps {
  /** Accessible name for the radiogroup, e.g. "Priority". */
  label: string;
  /** Number of levels. @default 5 */
  max?: number;
  /** Controlled value, 0..max. 0 = nothing stamped yet. */
  value?: number;
  /** Initial value when uncontrolled. @default 0 */
  defaultValue?: number;
  /** Fires on commit — click, or an arrow/Home/End key move. Never on hover. */
  onValueChange?: (value: number) => void;
  /**
   * Optional word per level (index 0 = level 1), appended to that level's
   * accessible name — e.g. `["Low", "", "", "", "Critical"]` reads level 5
   * as "5 of 5 - Critical". Sparse arrays are fine, empty entries are
   * skipped.
   */
  levelNames?: string[];
  /** @default "md" */
  size?: "sm" | "md" | "lg";
  /** extra classes merged onto the rendered root element */
  className?: string;
}

type Vars = React.CSSProperties & Record<`--${string}`, string | number>;

function clampLevel(v: number, max: number) {
  if (!Number.isFinite(v)) return 0;
  return Math.min(max, Math.max(0, Math.round(v)));
}

// Deterministic per-index variation (rotation + corner radius) so seals read
// as individually struck rather than one glyph rubber-stamped M times.
// Seeded off the index only — identical across renders and between the two
// themes.
function sealVariant(i: number) {
  const s = Math.sin(i * 12.9898 + 4.1414) * 43758.5453;
  const frac = s - Math.floor(s);
  return {
    rotate: (frac - 0.5) * 5, // -2.5..2.5deg
    rx: 3.2 + frac * 1.8, // 3.2..5 corner radius, viewBox units
  };
}

function useReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

export function ChopPress({
  label,
  max = 5,
  value,
  defaultValue = 0,
  onValueChange,
  levelNames,
  size = "md",
  className = "",
}: ChopPressProps) {
  const M = Math.max(1, Math.floor(max));
  const isControlled = value !== undefined;
  const [internal, setInternal] = useState(() => clampLevel(defaultValue, M));
  const committed = clampLevel(isControlled ? (value as number) : internal, M);

  const reducedMotion = useReducedMotion();
  const prevRef = useRef(committed);
  const [batch, setBatch] = useState(0);
  const [transitions, setTransitions] = useState<
    Map<number, { kind: Kind; delay: number }>
  >(new Map());
  const [hoverIndex, setHoverIndex] = useState<number | null>(null);
  const btnRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const groupId = useId();

  // Runs before paint whenever the committed value changes, whichever path
  // caused it (click, arrow key, or a controlled prop update from outside).
  // Building the transition map here — not inside the click handler — means
  // both paths animate identically and there's no one-frame flash of the
  // final state before the animation classes attach.
  useLayoutEffect(() => {
    const prev = prevRef.current;
    if (committed !== prev) {
      if (reducedMotion) {
        setTransitions(new Map());
      } else {
        const map = new Map<number, { kind: Kind; delay: number }>();
        if (committed > prev) {
          for (let i = prev; i < committed; i++) {
            map.set(i, { kind: "press", delay: (i - prev) * STAGGER_MS });
          }
        } else {
          for (let i = committed; i < prev; i++) {
            // right-to-left: the highest index (rightmost) drains first.
            map.set(i, { kind: "drain", delay: (prev - 1 - i) * STAGGER_MS });
          }
        }
        setTransitions(map);
        setBatch((b) => b + 1);
      }
      prevRef.current = committed;
    }
  }, [committed, reducedMotion]);

  const commit = useCallback(
    (next: number) => {
      const clamped = clampLevel(next, M);
      if (!isControlled) setInternal(clamped);
      if (clamped !== committed) onValueChange?.(clamped);
    },
    [M, isControlled, committed, onValueChange]
  );

  const onKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    let next: number | null = null;
    if (e.key === "ArrowRight" || e.key === "ArrowUp") {
      next = Math.min(M, Math.max(1, committed + 1));
    } else if (e.key === "ArrowLeft" || e.key === "ArrowDown") {
      next = Math.max(1, committed - 1);
    } else if (e.key === "Home") {
      next = 1;
    } else if (e.key === "End") {
      next = M;
    } else {
      return;
    }
    e.preventDefault();
    commit(next);
    btnRefs.current[next - 1]?.focus();
  };

  const levels = useMemo(() => Array.from({ length: M }, (_, i) => i), [M]);

  return (
    <div
      role="radiogroup"
      aria-label={label}
      onKeyDown={onKeyDown}
      data-reduced={reducedMotion || undefined}
      className={`ns-cp-group ${className}`}
      style={{ ["--cp-size"]: `${SIZE_PX[size]}px` } as Vars}
    >
      {levels.map((i) => {
        const filled = i < committed;
        const previewTarget = hoverIndex !== null ? i <= hoverIndex : filled;
        const previewing = hoverIndex !== null && previewTarget !== filled;
        const checked = i === committed - 1;
        const t = transitions.get(i);
        const variant = sealVariant(i);
        const level = i + 1;
        const name = levelNames?.[i];
        const ariaLabel = `${level} of ${M}${name ? ` - ${name}` : ""}`;
        const tabbable = committed === 0 ? i === 0 : i === committed - 1;
        const fillMs = t?.kind === "drain" ? DRAIN_FILL_MS : PRESS_FILL_MS;

        return (
          <button
            key={i}
            ref={(el) => {
              btnRefs.current[i] = el;
            }}
            type="button"
            role="radio"
            aria-checked={checked}
            aria-label={ariaLabel}
            id={`${groupId}-${i}`}
            tabIndex={tabbable ? 0 : -1}
            data-transition={t?.kind}
            className="ns-cp-seal"
            style={
              {
                "--cp-delay": `${t?.delay ?? 0}ms`,
                "--cp-fill-ms": `${fillMs}ms`,
              } as Vars
            }
            onClick={() => commit(level)}
            onMouseEnter={() => setHoverIndex(i)}
            onMouseLeave={() => setHoverIndex((h) => (h === i ? null : h))}
            onFocus={() => setHoverIndex(i)}
            onBlur={() => setHoverIndex((h) => (h === i ? null : h))}
          >
            <svg
              viewBox="0 0 32 32"
              aria-hidden="true"
              focusable="false"
              className="ns-cp-glyph"
              style={{ transform: `rotate(${variant.rotate.toFixed(2)}deg)` }}
            >
              <rect
                x={3}
                y={3}
                width={26}
                height={26}
                rx={variant.rx}
                className="ns-cp-base"
                data-filled={filled || undefined}
                data-preview={previewing || undefined}
              />
              <path
                d={`M 6 ${(6 + variant.rx).toFixed(1)} L 6 6 L ${(6 + variant.rx).toFixed(1)} 6`}
                className="ns-cp-edge-hi"
                data-filled={filled || undefined}
              />
              <path
                d={`M ${(26 - variant.rx).toFixed(1)} 26 L 26 26 L 26 ${(26 - variant.rx).toFixed(1)}`}
                className="ns-cp-edge-lo"
                data-filled={filled || undefined}
              />
            </svg>
            {t?.kind === "press" && (
              <span key={`ring-${batch}-${i}`} className="ns-cp-ring" aria-hidden="true" />
            )}
          </button>
        );
      })}

      <style>{`
        .ns-cp-group {
          display: inline-flex;
          align-items: center;
          gap: 8px;
        }
        .ns-cp-seal {
          position: relative;
          width: var(--cp-size, 34px);
          height: var(--cp-size, 34px);
          padding: 0;
          border: none;
          border-radius: 6px;
          background: transparent;
          color: inherit;
          cursor: pointer;
          display: grid;
          place-items: center;
          outline: none;
          -webkit-tap-highlight-color: transparent;
        }
        .ns-cp-seal:hover {
          background: color-mix(in oklab, var(--foreground) 4%, transparent);
        }
        .ns-cp-seal:focus-visible {
          outline: 2px solid var(--ns-accent);
          outline-offset: 2px;
        }
        .ns-cp-glyph {
          width: 68%;
          height: 68%;
          overflow: visible;
        }
        .ns-cp-base {
          /* fill is always --foreground; only fill-opacity animates. a
             color <-> "none" transition is a discrete 50% flip in every
             engine, not an interpolation — fill-opacity is a plain number
             and always interpolates smoothly. */
          fill: var(--foreground);
          fill-opacity: 0;
          stroke: var(--ns-muted);
          stroke-width: 1.5px;
          transition:
            fill-opacity var(--cp-fill-ms, 140ms) ease var(--cp-delay, 0ms),
            stroke 140ms ease var(--cp-delay, 0ms),
            stroke-dasharray 120ms ease;
        }
        .ns-cp-base[data-filled] {
          fill-opacity: 1;
          stroke-opacity: 0.4;
        }
        .ns-cp-base[data-preview] {
          stroke-dasharray: 3 2.5;
          stroke: color-mix(in oklab, var(--foreground) 55%, var(--ns-muted));
        }
        .ns-cp-edge-hi,
        .ns-cp-edge-lo {
          fill: none;
          stroke-width: 1px;
          opacity: 0;
          transition: opacity var(--cp-fill-ms, 140ms) ease var(--cp-delay, 0ms);
        }
        .ns-cp-edge-hi[data-filled],
        .ns-cp-edge-lo[data-filled] {
          opacity: 1;
        }
        .ns-cp-edge-hi {
          stroke: color-mix(in oklab, var(--background) 45%, transparent);
        }
        .ns-cp-edge-lo {
          stroke: var(--border);
        }

        .ns-cp-seal[data-transition="press"] {
          animation: ns-cp-press ${PRESS_MS}ms cubic-bezier(0.16, 1, 0.3, 1) both;
          animation-delay: var(--cp-delay, 0ms);
        }

        .ns-cp-ring {
          position: absolute;
          inset: 2px;
          border-radius: 6px;
          border: 1px solid var(--border);
          pointer-events: none;
          opacity: 0.9;
          transform: scale(0.85);
          animation: ns-cp-ring ${RING_MS}ms ease-out both;
          animation-delay: var(--cp-delay, 0ms);
        }

        @keyframes ns-cp-press {
          from { transform: scale(1.15); }
          to { transform: scale(1); }
        }
        @keyframes ns-cp-ring {
          from { opacity: 0.9; transform: scale(0.9); }
          to { opacity: 0; transform: scale(1.6); }
        }

        .ns-cp-group[data-reduced] .ns-cp-base,
        .ns-cp-group[data-reduced] .ns-cp-edge-hi,
        .ns-cp-group[data-reduced] .ns-cp-edge-lo {
          transition: none;
        }
        .ns-cp-group[data-reduced] .ns-cp-seal[data-transition],
        .ns-cp-group[data-reduced] .ns-cp-ring {
          animation: none;
          display: none;
        }

        @media (prefers-reduced-motion: reduce) {
          .ns-cp-base,
          .ns-cp-edge-hi,
          .ns-cp-edge-lo {
            transition: none;
          }
          .ns-cp-seal[data-transition],
          .ns-cp-ring {
            animation: none;
          }
        }
      `}</style>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

export interface UnderInkProps {
  /** The sensitive text under the bar. Sized by the real text, so the bar never lies about length. */
  children: string;
  /** Tiny mono tag on the bar naming WHAT is hidden without revealing it — "email", "amount". */
  label?: string;
  /** ms after a hold-peek release before the ink flows back. */
  resealMs?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const HOLD_THRESHOLD_MS = 280; // press shorter than this is a click-toggle, longer is a peek

/**
 * Inline redaction. The bar is drawn over the real text (which sets the
 * width — a redaction that hides length hides less than people think, and a
 * fixed-width bar that lies about it reads as fake). Two ways in:
 * press-and-hold lifts the ink for a peek and it flows back shortly after
 * release; a plain click (or Enter/Space) latches it open until clicked
 * again. aria-pressed tracks whether the text is currently exposed.
 */
export function UnderInk({ children, label, resealMs = 900, className = "" }: UnderInkProps) {
  const [latched, setLatched] = useState(false);
  const [peeking, setPeeking] = useState(false);
  const pressStartRef = useRef(0);
  const resealRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const suppressClickRef = useRef(false);

  const revealed = latched || peeking;

  useEffect(() => () => window.clearTimeout(resealRef.current), []);

  // Escape is the panic key: seal immediately, latched or mid-peek.
  useEffect(() => {
    if (!revealed) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        window.clearTimeout(resealRef.current);
        setLatched(false);
        setPeeking(false);
      }
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [revealed]);

  const onPointerDown = (e: React.PointerEvent) => {
    if (e.button !== 0 || latched) return;
    window.clearTimeout(resealRef.current);
    suppressClickRef.current = false; // a drag-out could leave a stale suppress behind
    pressStartRef.current = performance.now();
    setPeeking(true);
  };

  const endPress = () => {
    if (!peeking) return;
    const held = performance.now() - pressStartRef.current;
    if (held >= HOLD_THRESHOLD_MS) {
      // it was a peek: the ink takes a moment to flow back
      suppressClickRef.current = true; // the click that follows pointerup must not latch
      resealRef.current = setTimeout(() => setPeeking(false), resealMs);
    } else {
      // short press: let the click handler latch it
      setPeeking(false);
    }
  };

  const onClick = (e: React.MouseEvent) => {
    if (suppressClickRef.current) {
      suppressClickRef.current = false;
      return;
    }
    // e.detail === 0 → keyboard activation (Enter/Space): always a toggle
    window.clearTimeout(resealRef.current);
    setPeeking(false);
    setLatched((l) => !l);
  };

  return (
    <button
      type="button"
      aria-pressed={revealed}
      aria-label={
        revealed
          ? `Hide redacted ${label ?? "content"}`
          : `Reveal redacted ${label ?? "content"} — hold to peek, click to keep open`
      }
      onPointerDown={onPointerDown}
      onPointerUp={endPress}
      onPointerCancel={endPress}
      onPointerLeave={endPress}
      onClick={onClick}
      className={`ns-underink group relative inline-block cursor-pointer whitespace-nowrap rounded-[3px] px-[3px] align-baseline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent ${className}`}
    >
      <style>{`
        .ns-underink .ns-underink-bar {
          transition: transform 240ms cubic-bezier(0.22, 1, 0.36, 1), opacity 200ms ease-out;
          transform-origin: top;
        }
        .ns-underink[aria-pressed="true"] .ns-underink-bar {
          transform: scaleY(0.14) translateY(-2px);
          opacity: 0.85;
        }
        .ns-underink .ns-underink-text {
          transition: opacity 180ms ease-out 60ms;
        }
        .ns-underink:hover .ns-underink-bar { opacity: 0.82; }
        @media (prefers-reduced-motion: reduce) {
          .ns-underink .ns-underink-bar, .ns-underink .ns-underink-text { transition: none; }
        }
      `}</style>
      {/* the real text sets the width; hidden from everyone (visually + AT) while sealed */}
      <span
        data-underink-text
        aria-hidden={!revealed}
        className={`ns-underink-text relative z-0 ${revealed ? "opacity-100" : "opacity-0"}`}
      >
        {children}
      </span>
      {/* the ink: lifts to a thin overline on reveal, so the redaction never disappears — it hovers over what it was hiding */}
      <span
        aria-hidden
        className="ns-underink-bar absolute inset-0 z-10 rounded-[3px] bg-foreground"
      >
        {label && (
          // stays mounted; hidden by opacity when revealed. Unmounting it on
          // reveal removed the exact node under a centred click between
          // pointerdown and pointerup, so the browser fired no `click` and the
          // latch never happened.
          <span
            className={`flex h-full items-center justify-center overflow-hidden px-1 font-mono text-[9px] uppercase tracking-[0.18em] text-background/80 ${revealed ? "opacity-0" : "opacity-100"}`}
          >
            {label}
          </span>
        )}
      </span>
    </button>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";

// ---------------------------------------------------------------------------
// FlywheelPull — pull-to-refresh as a crank and flywheel. Dragging the wheel
// zone down winds a spoked SVG wheel through a visible rack-and-pinion
// drivetrain, pull distance mapping 1:1 to wind-up angle. Releasing hands the
// wheel an angular velocity of pullDistance * a gain constant, integrated per
// rAF frame under low friction while the (real or simulated) refresh request
// is in flight — the loading state IS the gesture's energy bleeding off, not
// a canned spinner swap. When the response lands, friction jumps and the
// wheel decays to rest over ~400ms; new rows FLIP into the list at the same
// moment the wheel settles. A visible Refresh button is always the primary
// path; the drag is enhancement, and clicking it replays the same physics
// via a synthetic pull so the two paths feel like one mechanism. DOM+SVG+CSS
// only, no canvas, colors are CSS custom properties only.
// ---------------------------------------------------------------------------

const WIND_DEG_PER_PX = 1.05; // wind-up angle per px pulled
const MAX_PULL = 130; // px — beyond this, rubber-band resistance
const RUBBER = 0.32; // beyond-MAX_PULL displacement scale
const RELEASE_GAIN = 1.65; // deg/s of release velocity per px pulled
const FRICTION_FREE = 0.55; // s^-1 — low friction while request is in flight
const FRICTION_BRAKE = 10; // s^-1 — applied once the response arrives
const SLEEP_OMEGA = 3; // deg/s — below this, and braking, the wheel is at rest
const PULL_RETURN = 16; // s^-1 — rack/pinion spring back to 0 after release
const FORCE_SETTLE_MS = 6000; // safety deadline so physics never spins forever
const BUTTON_WIND_PX = 96; // synthetic pull distance for a click-only refresh
const MIN_LATENCY_MS = 900;
const MAX_LATENCY_MS = 1500;
const MAX_ITEMS = 14;
const ENTER_STAGGER_MS = 70;
const ENTER_DURATION_MS = 380;

const CX_WHEEL = 176;
const CY_WHEEL = 80;
const R_WHEEL = 54;
const CX_PINION = 86;
const CY_PINION = 80;
const R_PINION = 15;
const SPOKES = 8;
const RACK_X = 40;
const RACK_Y = 6;
const RACK_W = 30;
const RACK_H = 148;
const TOOTH_PITCH = 16;

export interface FlywheelPullItem {
  id: string;
  title: string;
  meta?: string;
}

export interface FlywheelPullProps {
  /** Initial feed rows, newest first. */
  defaultItems?: FlywheelPullItem[];
  /**
   * Called on release/refresh; resolve with the new rows to prepend. Omit to
   * use a built-in simulated request (900-1500ms) that manufactures rows —
   * fine for a demo, but a real feed should supply this.
   */
  onRefresh?: () => Promise<FlywheelPullItem[]>;
  /** Accessible label for the row list. */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const SAMPLE_TITLES = [
  "New comment on “Q3 roadmap”",
  "3 people starred your repo",
  "Deploy finished: prod-web-42",
  "Weekly digest is ready",
  "Mentioned you in #general",
  "New follower: @octavia",
  "Build failed on staging",
  "Invoice #4021 was paid",
  "2 reviewers approved your PR",
  "New device signed in",
];

let idCounter = 0;
function generateItems(n: number): FlywheelPullItem[] {
  const out: FlywheelPullItem[] = [];
  for (let i = 0; i < n; i++) {
    idCounter += 1;
    const title =
      SAMPLE_TITLES[Math.floor(Math.random() * SAMPLE_TITLES.length)] ??
      "Update";
    out.push({ id: `fw-${idCounter}`, title, meta: "just now" });
  }
  return out;
}

function simulateRefresh(): Promise<FlywheelPullItem[]> {
  const latency =
    MIN_LATENCY_MS + Math.random() * (MAX_LATENCY_MS - MIN_LATENCY_MS);
  const count = 2 + Math.floor(Math.random() * 5); // 2..6
  return new Promise((resolve) => {
    window.setTimeout(() => resolve(generateItems(count)), latency);
  });
}

type Phase = "idle" | "busy" | "done" | "error";

export function FlywheelPull({
  defaultItems,
  onRefresh,
  label = "Activity feed",
  className = "",
}: FlywheelPullProps) {
  const [items, setItems] = useState<FlywheelPullItem[]>(
    () => defaultItems ?? generateItems(5)
  );
  const [phase, setPhase] = useState<Phase>("idle");
  const [liveText, setLiveText] = useState("");
  const [enteringOrder, setEnteringOrder] = useState<string[]>([]);

  const zoneRef = useRef<HTMLDivElement>(null);
  const wheelGroupRef = useRef<SVGGElement>(null);
  const pinionGroupRef = useRef<SVGGElement>(null);
  const rackTeethRef = useRef<SVGGElement>(null);
  const rowRefs = useRef<Map<string, HTMLLIElement>>(new Map());
  const prevRectsRef = useRef<Map<string, DOMRect>>(new Map());

  const reducedRef = useRef(false);
  const onRefreshRef = useRef(onRefresh);
  onRefreshRef.current = onRefresh;

  const captureRects = useCallback(() => {
    const map = new Map<string, DOMRect>();
    rowRefs.current.forEach((el, id) => {
      map.set(id, el.getBoundingClientRect());
    });
    prevRectsRef.current = map;
  }, []);

  // single place that turns a settled request into visible feed state —
  // called from the physics loop (in flight), the reduced-motion pointer
  // path, and the reduced-motion button path alike.
  const applyResult = useCallback(
    (result: FlywheelPullItem[] | null, failed: boolean) => {
      if (failed || !result) {
        setPhase("error");
        setLiveText("Refresh failed, wheel at rest.");
        window.setTimeout(() => setPhase("idle"), 1600);
        return;
      }
      captureRects();
      setItems((prev) => [...result, ...prev].slice(0, MAX_ITEMS));
      const ids = result.map((r) => r.id);
      setEnteringOrder(ids);
      setPhase("done");
      setLiveText(
        `Updated, ${result.length} new item${result.length === 1 ? "" : "s"}`
      );
      window.setTimeout(
        () => {
          setEnteringOrder((cur) => cur.filter((id) => !ids.includes(id)));
        },
        ENTER_DURATION_MS + ids.length * ENTER_STAGGER_MS + 60
      );
    },
    [captureRects]
  );
  const applyResultRef = useRef(applyResult);
  applyResultRef.current = applyResult;
  // every refresh (drag release or button) bumps this; a resolving request
  // only commits if it's still the most recent one — clicking Refresh again
  // mid-flight restarts the wheel instead of queuing a second, stale commit.
  const genRef = useRef(0);

  useLayoutEffect(() => {
    if (reducedRef.current) return;
    const prev = prevRectsRef.current;
    rowRefs.current.forEach((el, id) => {
      const before = prev.get(id);
      if (!before) return;
      const after = el.getBoundingClientRect();
      const dy = before.top - after.top;
      if (Math.abs(dy) < 0.5) return;
      el.style.transition = "none";
      el.style.transform = `translateY(${dy}px)`;
      requestAnimationFrame(() => {
        el.style.transition = "transform 420ms cubic-bezier(.22,1,.36,1)";
        el.style.transform = "";
      });
    });
  }, [items]);

  useEffect(() => {
    const zone = zoneRef.current;
    if (!zone) return;
    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;
    reducedRef.current = reduced;

    // hot-path physics state — plain locals, no React state per frame
    let angle = 0;
    let pull = 0;
    let v = 0; // deg/s
    let braking = false;
    let raf = 0;
    let last = 0;
    let deadline = 0;
    let dragging = false;
    let pointerId = -1;
    let startY = 0;
    let baseAngle = 0;
    let pendingResolve: (() => void) | null = null;

    const writeTransforms = (a: number, p: number) => {
      wheelGroupRef.current?.setAttribute(
        "transform",
        `rotate(${a.toFixed(2)} ${CX_WHEEL} ${CY_WHEEL})`
      );
      pinionGroupRef.current?.setAttribute(
        "transform",
        `rotate(${a.toFixed(2)} ${CX_PINION} ${CY_PINION})`
      );
      rackTeethRef.current?.setAttribute(
        "transform",
        `translate(0 ${p.toFixed(2)})`
      );
    };

    const loop = (now: number) => {
      raf = 0;
      const dt = last ? Math.min(0.032, (now - last) / 1000) : 1 / 60;
      last = now;

      const friction = braking ? FRICTION_BRAKE : FRICTION_FREE;
      v *= Math.exp(-friction * dt);
      angle += v * dt;
      pull = pull > 0.02 ? pull * Math.exp(-PULL_RETURN * dt) : 0;
      writeTransforms(angle, pull);

      const settleReady = braking && Math.abs(v) < SLEEP_OMEGA;
      const forceSettle = now > deadline;
      if (settleReady || forceSettle) {
        v = 0;
        pull = 0;
        writeTransforms(angle, 0);
        const resolve = pendingResolve;
        pendingResolve = null;
        resolve?.();
        return;
      }
      raf = requestAnimationFrame(loop);
    };

    const startFlight = (releaseVelocity: number) => {
      v = releaseVelocity;
      braking = false;
      pendingResolve = null;
      deadline = performance.now() + FORCE_SETTLE_MS;
      setPhase("busy");
      setLiveText("Refreshing…");
      last = 0;
      raf = requestAnimationFrame(loop);

      const myGen = ++genRef.current;
      const req = onRefreshRef.current
        ? onRefreshRef.current()
        : simulateRefresh();

      const finish = (result: FlywheelPullItem[] | null, failed: boolean) => {
        if (myGen !== genRef.current) return; // superseded by a later refresh
        // response arrived — raise friction, wait for the loop to actually
        // settle, then commit rows exactly as the wheel comes to rest.
        braking = true;
        pendingResolve = () => applyResultRef.current(result, failed);
      };
      req.then(
        (result) => finish(result, false),
        () => finish(null, true)
      );
    };

    const springBackIdle = () => {
      last = 0;
      const idleLoop = (now: number) => {
        raf = 0;
        const dt = last ? Math.min(0.032, (now - last) / 1000) : 1 / 60;
        last = now;
        pull *= Math.exp(-PULL_RETURN * dt);
        writeTransforms(angle, pull);
        if (pull > 0.05) raf = requestAnimationFrame(idleLoop);
        else {
          pull = 0;
          writeTransforms(angle, 0);
        }
      };
      raf = requestAnimationFrame(idleLoop);
    };

    const onPointerDown = (e: PointerEvent) => {
      if (e.button !== 0) return;
      // grabs the wheel even mid-freewheel/mid-brake — catching it and
      // winding again always wins over whatever was already in flight; a
      // stale response is dropped by the genRef check in `finish`.
      dragging = true;
      pointerId = e.pointerId;
      startY = e.clientY;
      baseAngle = angle;
      pull = 0;
      v = 0;
      braking = false;
      pendingResolve = null;
      // a grab always supersedes whatever request was in flight — otherwise a
      // late response with no loop left to resolve it (e.g. grab then release
      // under the 4px threshold, no re-flight started) would strand `phase`
      // on "busy" forever. Reset unconditionally (React bails out a same-value
      // set) rather than reading `phase`, which is stale in this mount-once
      // closure.
      genRef.current++;
      setPhase("idle");
      zone.style.cursor = "grabbing";
      try {
        zone.setPointerCapture(e.pointerId);
      } catch {
        /* synthetic or already-gone pointer */
      }
      cancelAnimationFrame(raf);
      raf = 0;
      if (!reduced) writeTransforms(angle, 0);
    };

    const onPointerMove = (e: PointerEvent) => {
      if (!dragging || e.pointerId !== pointerId) return;
      const rawDy = e.clientY - startY;
      const dy = rawDy < 0 ? 0 : rawDy;
      pull = dy <= MAX_PULL ? dy : MAX_PULL + (dy - MAX_PULL) * RUBBER;
      if (reduced) return;
      angle = baseAngle + pull * WIND_DEG_PER_PX;
      writeTransforms(angle, pull);
    };

    const onPointerUp = (e: PointerEvent) => {
      if (e.pointerId !== pointerId) return;
      zone.style.cursor = "";
      if (!dragging) return;
      dragging = false;
      pointerId = -1;
      const finalPull = pull;

      if (reduced) {
        if (finalPull >= 4) {
          setPhase("busy");
          setLiveText("Refreshing…");
          const myGen = ++genRef.current;
          const req = onRefreshRef.current
            ? onRefreshRef.current()
            : simulateRefresh();
          req.then(
            (result) => {
              if (myGen === genRef.current) applyResultRef.current(result, false);
            },
            () => {
              if (myGen === genRef.current) applyResultRef.current(null, true);
            }
          );
        }
        pull = 0;
        return;
      }

      if (finalPull < 4) {
        springBackIdle();
        return;
      }
      startFlight(finalPull * RELEASE_GAIN);
    };

    const onPointerCancel = (e: PointerEvent) => onPointerUp(e);

    zone.addEventListener("pointerdown", onPointerDown);
    zone.addEventListener("pointermove", onPointerMove);
    zone.addEventListener("pointerup", onPointerUp);
    zone.addEventListener("pointercancel", onPointerCancel);

    return () => {
      cancelAnimationFrame(raf);
      zone.removeEventListener("pointerdown", onPointerDown);
      zone.removeEventListener("pointermove", onPointerMove);
      zone.removeEventListener("pointerup", onPointerUp);
      zone.removeEventListener("pointercancel", onPointerCancel);
    };
  }, []);

  const handleButtonRefresh = useCallback(() => {
    // always restarts the cycle, even mid-flight — a second press is a
    // fresh yank on the crank, not a no-op; see genRef in the physics effect.
    if (reducedRef.current) {
      setPhase("busy");
      setLiveText("Refreshing…");
      const myGen = ++genRef.current;
      const req = onRefreshRef.current
        ? onRefreshRef.current()
        : simulateRefresh();
      req.then(
        (result) => {
          if (myGen === genRef.current) applyResultRef.current(result, false);
        },
        () => {
          if (myGen === genRef.current) applyResultRef.current(null, true);
        }
      );
      return;
    }

    // dispatch a synthetic pull onto the drag zone so a plain click runs the
    // exact same wind -> release -> freewheel -> brake physics as a real drag.
    const zone = zoneRef.current;
    if (!zone) return;
    const rect = zone.getBoundingClientRect();
    const cx = rect.left + rect.width / 2;
    const top = rect.top + 8;
    const pid = -999;
    const opts = { pointerId: pid, clientX: cx, button: 0, bubbles: true };
    zone.dispatchEvent(new PointerEvent("pointerdown", { ...opts, clientY: top }));
    zone.dispatchEvent(
      new PointerEvent("pointermove", { ...opts, clientY: top + BUTTON_WIND_PX })
    );
    zone.dispatchEvent(
      new PointerEvent("pointerup", { ...opts, clientY: top + BUTTON_WIND_PX })
    );
  }, []);

  const busy = phase === "busy";
  const statusText =
    phase === "idle" ? "Pull the wheel down, or press Refresh." : liveText;

  return (
    <div
      className={`w-full max-w-md rounded-md border border-border bg-background ${className}`}
    >
      <div
        ref={zoneRef}
        role="presentation"
        aria-hidden="true"
        className="flex touch-none select-none items-center justify-center py-3"
        style={{ cursor: "grab" }}
      >
        <svg
          viewBox="0 0 240 160"
          width="180"
          height="120"
          className="max-w-full"
        >
          <defs>
            <clipPath id="fw-rack-clip">
              <rect x={RACK_X} y={RACK_Y} width={RACK_W} height={RACK_H} />
            </clipPath>
          </defs>

          {/* rack — vertical bar; teeth slide behind the window as you pull */}
          <rect
            x={RACK_X}
            y={RACK_Y}
            width={RACK_W}
            height={RACK_H}
            rx={3}
            fill="none"
            stroke="var(--border)"
            strokeWidth={2}
          />
          <g clipPath="url(#fw-rack-clip)">
            <g ref={rackTeethRef}>
              {Array.from({ length: 14 }, (_, i) => (
                <rect
                  key={i}
                  x={RACK_X + 2}
                  y={RACK_Y - TOOTH_PITCH * 3 + i * TOOTH_PITCH}
                  width={RACK_W - 8}
                  height={5}
                  fill="var(--border)"
                />
              ))}
            </g>
          </g>

          {/* pinion — small gear meshed with the rack, shares the drive angle */}
          <g ref={pinionGroupRef}>
            <circle
              cx={CX_PINION}
              cy={CY_PINION}
              r={R_PINION}
              fill="var(--background)"
              stroke="var(--border)"
              strokeWidth={2}
            />
            {Array.from({ length: 8 }, (_, i) => {
              const a = (i * 360) / 8;
              const rad = (a * Math.PI) / 180;
              const x1 = CX_PINION + Math.cos(rad) * (R_PINION - 1);
              const y1 = CY_PINION + Math.sin(rad) * (R_PINION - 1);
              const x2 = CX_PINION + Math.cos(rad) * (R_PINION + 4);
              const y2 = CY_PINION + Math.sin(rad) * (R_PINION + 4);
              return (
                <line
                  key={i}
                  x1={x1}
                  y1={y1}
                  x2={x2}
                  y2={y2}
                  stroke="var(--border)"
                  strokeWidth={2}
                />
              );
            })}
          </g>

          {/* shaft — couples pinion and wheel onto one drive axle */}
          <line
            x1={CX_PINION + R_PINION + 4}
            y1={CY_PINION}
            x2={CX_WHEEL - R_WHEEL + 6}
            y2={CY_WHEEL}
            stroke="var(--border)"
            strokeWidth={2}
            strokeDasharray="2 5"
          />

          {/* flywheel — spokes in --border, one index spoke in --foreground */}
          <g ref={wheelGroupRef}>
            <circle
              cx={CX_WHEEL}
              cy={CY_WHEEL}
              r={R_WHEEL}
              fill="none"
              stroke="var(--border)"
              strokeWidth={3}
            />
            {Array.from({ length: SPOKES }, (_, i) => {
              const a = (i * 360) / SPOKES;
              const rad = (a * Math.PI) / 180;
              const inner = 10;
              const outer = R_WHEEL - 5;
              const x1 = CX_WHEEL + Math.cos(rad) * inner;
              const y1 = CY_WHEEL + Math.sin(rad) * inner;
              const x2 = CX_WHEEL + Math.cos(rad) * outer;
              const y2 = CY_WHEEL + Math.sin(rad) * outer;
              const isIndex = i === 0;
              return (
                <line
                  key={i}
                  x1={x1}
                  y1={y1}
                  x2={x2}
                  y2={y2}
                  stroke={isIndex ? "var(--foreground)" : "var(--border)"}
                  strokeWidth={isIndex ? 4 : 2.5}
                  strokeLinecap="round"
                />
              );
            })}
            <circle
              cx={CX_WHEEL}
              cy={CY_WHEEL - (R_WHEEL - 5)}
              r={3}
              fill="var(--foreground)"
            />
            <circle
              cx={CX_WHEEL}
              cy={CY_WHEEL}
              r={9}
              fill="var(--background)"
              stroke="var(--border)"
              strokeWidth={2}
            />
          </g>
        </svg>
      </div>

      <div className="flex items-center gap-3 border-t border-b border-border px-4 py-3">
        <button
          type="button"
          data-flywheel-refresh
          onClick={handleButtonRefresh}
          className="inline-flex shrink-0 items-center gap-2 rounded-sm border border-border bg-background px-3 py-1.5 text-sm font-medium text-foreground outline-none transition-colors hover:border-foreground/25 focus-visible:ring-2 focus-visible:ring-ns-accent"
        >
          <svg
            aria-hidden="true"
            viewBox="0 0 16 16"
            width="14"
            height="14"
            className={busy ? "motion-safe:animate-spin" : ""}
            style={{ animationDuration: "900ms" }}
          >
            <path
              d="M13.5 8a5.5 5.5 0 1 1-1.65-3.93M13.5 2v3.5H10"
              fill="none"
              stroke="currentColor"
              strokeWidth={1.4}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
          {busy ? "Refreshing…" : "Refresh"}
        </button>
        <p
          data-flywheel-status={phase}
          className="min-w-0 flex-1 truncate font-mono text-xs text-ns-muted"
        >
          {statusText}
        </p>
      </div>

      <div role="status" aria-live="polite" className="sr-only">
        {liveText}
      </div>

      <ul
        aria-label={label}
        aria-busy={busy}
        className="max-h-72 divide-y divide-border overflow-y-auto"
      >
        {items.map((item) => {
          const entering = !reducedRef.current && enteringOrder.includes(item.id);
          return (
            <li
              key={item.id}
              ref={(el) => {
                if (el) rowRefs.current.set(item.id, el);
                else rowRefs.current.delete(item.id);
              }}
              className={`flex items-center justify-between gap-3 px-4 py-3 ${
                entering ? "ns-fw-enter" : ""
              }`}
              style={
                entering
                  ? { animationDelay: `${enteringOrder.indexOf(item.id) * ENTER_STAGGER_MS}ms` }
                  : undefined
              }
            >
              <span className="min-w-0 flex-1 truncate text-sm text-foreground">
                {item.title}
              </span>
              {item.meta && (
                <span className="shrink-0 font-mono text-xs text-ns-muted">
                  {item.meta}
                </span>
              )}
            </li>
          );
        })}
      </ul>

      <style>{`
        @keyframes ns-fw-enter {
          from { opacity: 0; transform: translateY(-10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .ns-fw-enter {
          animation: ns-fw-enter ${ENTER_DURATION_MS}ms cubic-bezier(.22,1,.36,1) both;
        }
        @media (prefers-reduced-motion: reduce) {
          .ns-fw-enter { animation: none; }
        }
      `}</style>
    </div>
  );
}

"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// RedlineParley — the counter-offer after a guardrail closes, not the gate
// itself (that's approval-inline-diff's job, for a different decision entirely: a
// human approving an agent's already-permitted tool call). Here the request
// was already refused. The offending span is echoed back struck through —
// never a full-red block, just a --ns-muted strikethrough bar that draws
// left-to-right once on mount — with the reason beneath it and a small
// group of narrowing levers (switches) that each rewrite the span. Flipping
// any lever re-runs its rewrite against the *original* span, cross-fades the
// old phrasing into the new one without changing the line's height, and
// recomputes whether the rewritten request now clears `recheck`. Passing
// retracts the strike (the same bar, animating the other direction) and is
// the only moment --ns-accent appears anywhere in this component: the resend
// button's border. A visible status line always states "Blocked"/"Allowed"
// in plain words too, so the outcome never rides on noticing a line move.
//
// Gate-selector note: the verifier's generic press pass clicks the first
// interactive control before checking a declared `gate`. The first control
// here is remedies[0]'s switch. Point any `gate.openBy` at remedies[1] (or
// later) — `passed` is an OR over every active remedy by default, so a
// press-pass toggle of remedies[0] and a gate click on remedies[1] both
// leave at least one lever on and the gate still resolves.
// ---------------------------------------------------------------------------

export interface RedlineSpan {
  /** text before the flagged span, echoed verbatim */
  before: string;
  /** the substring that tripped the guardrail */
  flagged: string;
  /** text after the flagged span, echoed verbatim */
  after: string;
}

export interface RedlineRemedy {
  id: string;
  /** short label on the toggle chip, e.g. "anonymize names" */
  label: string;
  /** rewrites the span — called against the *original* span each time the
   * lever is (re)armed, so levers don't compound off each other's output */
  rewrite: (span: RedlineSpan) => RedlineSpan;
}

export interface RedlineResolution {
  /** before + flagged + after, as finally rewritten */
  request: string;
  /** ids of the remedies that were active at send time */
  activeRemedies: string[];
}

export interface RedlineParleyProps {
  /** the flagged prompt span, echoed back for context */
  span: RedlineSpan;
  /** one-sentence explanation of what tripped, shown under the echoed prompt */
  reason: string;
  /** available fixes the user can toggle on to clear the guardrail */
  remedies: RedlineRemedy[];
  /** decides whether the rewritten span now clears the guardrail. Default:
   * passes once at least one remedy is active — a real integration should
   * pass its own check against the actual guardrail instead. */
  recheck?: (span: RedlineSpan, activeRemedyIds: string[]) => boolean;
  /** called when the user resends the rewritten span, with the final resolution */
  onResend?: (resolution: RedlineResolution) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const FADE_MS = 220;
const STRIKE_MS = 200;
const SENT_HOLD_MS = 1400;

function defaultRecheck(_span: RedlineSpan, activeRemedyIds: string[]) {
  return activeRemedyIds.length > 0;
}

export function RedlineParley({
  span,
  reason,
  remedies,
  recheck = defaultRecheck,
  onResend,
  className = "",
}: RedlineParleyProps) {
  const original = useRef(span).current;
  const uid = useId();

  const [activeIds, setActiveIds] = useState<string[]>([]);
  const [justSent, setJustSent] = useState(false);
  const sentTimeout = useRef<number | undefined>(undefined);

  // Each active remedy's rewrite is folded over the *original* span in
  // remedy-array order — a lever always starts from what the guardrail
  // actually flagged, never from another lever's output, so toggling one
  // off doesn't leave a stray partial rewrite behind from another.
  const currentSpan = useMemo(
    () =>
      remedies.reduce(
        (acc, r) => (activeIds.includes(r.id) ? r.rewrite(acc) : acc),
        original
      ),
    [remedies, activeIds, original]
  );

  const passed = recheck(currentSpan, activeIds);

  // Cross-fade the flagged text old -> new without moving the line: the two
  // copies stack in the same CSS grid cell (grid sizes the cell to the
  // larger of the two, so nothing else on the line reflows mid-fade) while
  // opacity swaps between them.
  const lastFlaggedRef = useRef(original.flagged);
  const [displayFlagged, setDisplayFlagged] = useState(original.flagged);
  const [ghost, setGhost] = useState<string | null>(null);
  const [revealed, setRevealed] = useState(true);
  const ghostTimeout = useRef<number | undefined>(undefined);

  useEffect(() => {
    if (currentSpan.flagged === lastFlaggedRef.current) return;
    const previous = lastFlaggedRef.current;
    lastFlaggedRef.current = currentSpan.flagged;
    setGhost(previous);
    setDisplayFlagged(currentSpan.flagged);
    setRevealed(false);
    const raf = requestAnimationFrame(() => setRevealed(true));
    window.clearTimeout(ghostTimeout.current);
    ghostTimeout.current = window.setTimeout(() => setGhost(null), FADE_MS);
    return () => cancelAnimationFrame(raf);
  }, [currentSpan.flagged]);

  useEffect(() => () => window.clearTimeout(ghostTimeout.current), []);
  useEffect(() => () => window.clearTimeout(sentTimeout.current), []);

  // The strike bar's scale tracks `!passed`, deferred one frame so the very
  // first paint (undrawn) and the draw-in (drawn) are two distinct commits —
  // without the frame gap the mount would paint straight at its final value
  // and no transition would ever be observed.
  const [barScale, setBarScale] = useState(0);
  useEffect(() => {
    const raf = requestAnimationFrame(() => setBarScale(passed ? 0 : 1));
    return () => cancelAnimationFrame(raf);
  }, [passed]);

  // sr-only announcement, one per lever flip — skipped on mount so a screen
  // reader doesn't hear a phantom "rewritten" before anything happened.
  const mountedRef = useRef(false);
  const [announcement, setAnnouncement] = useState("");
  useEffect(() => {
    if (!mountedRef.current) {
      mountedRef.current = true;
      return;
    }
    setAnnouncement(
      `rewritten: ${currentSpan.flagged}, request now ${passed ? "allowed" : "blocked"}`
    );
  }, [currentSpan.flagged, passed]);

  function toggle(id: string) {
    setActiveIds((prev) =>
      prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]
    );
  }

  function handleSend() {
    if (!passed) return;
    onResend?.({
      request: currentSpan.before + currentSpan.flagged + currentSpan.after,
      activeRemedies: activeIds,
    });
    setJustSent(true);
    window.clearTimeout(sentTimeout.current);
    sentTimeout.current = window.setTimeout(() => setJustSent(false), SENT_HOLD_MS);
  }

  return (
    <div className={className}>
      <style>{`
.ns-rp-strike { transition: transform ${STRIKE_MS}ms cubic-bezier(0.16,1,0.3,1); }
.ns-rp-fade { transition: opacity ${FADE_MS}ms cubic-bezier(0.16,1,0.3,1); }
.ns-rp-chip { transition: color 160ms ease, border-color 160ms ease, background-color 160ms ease; }
.ns-rp-send { transition: border-color 220ms cubic-bezier(0.16,1,0.3,1), box-shadow 220ms cubic-bezier(0.16,1,0.3,1); }
@media (prefers-reduced-motion: reduce) {
  .ns-rp-strike, .ns-rp-fade, .ns-rp-chip, .ns-rp-send { transition: none !important; }
}
`}</style>

      <div className="rounded-md border border-border bg-surface p-4">
        <p className="text-sm leading-relaxed text-foreground">
          {currentSpan.before}
          <span
            role="mark"
            tabIndex={0}
            aria-label={`flagged: ${reason}`}
            className="relative inline-grid align-baseline rounded-sm focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-foreground/60"
          >
            {ghost !== null ? (
              <span
                aria-hidden
                style={{ gridArea: "1 / 1" }}
                className={
                  "ns-rp-fade pointer-events-none " +
                  (revealed ? "opacity-0" : "opacity-100")
                }
              >
                {ghost}
              </span>
            ) : null}
            <span
              style={{ gridArea: "1 / 1" }}
              className={
                "ns-rp-fade relative " +
                (ghost !== null ? (revealed ? "opacity-100" : "opacity-0") : "opacity-100")
              }
            >
              {displayFlagged}
              <span
                aria-hidden
                className="ns-rp-strike pointer-events-none absolute inset-x-0 top-1/2 h-[1.5px] bg-ns-muted"
                style={{ transform: `translateY(-50%) scaleX(${barScale})` }}
              />
            </span>
          </span>
          {currentSpan.after}
        </p>

        <p className="mt-2 text-sm text-ns-muted">{reason}</p>

        <p
          data-redline-status={passed ? "allowed" : "blocked"}
          className="mt-4 font-mono text-[11px] uppercase tracking-wide text-ns-muted"
        >
          {passed ? "Allowed — ready to resend" : "Blocked"}
        </p>

        <div
          role="group"
          aria-label="Narrowing levers"
          className="mt-2 flex flex-wrap gap-2"
        >
          {remedies.map((r, i) => {
            const active = activeIds.includes(r.id);
            return (
              <button
                key={r.id}
                type="button"
                role="switch"
                aria-checked={active}
                data-redline-remedy={r.id}
                data-redline-index={i}
                onClick={() => toggle(r.id)}
                className={
                  "ns-rp-chip inline-flex items-center gap-1.5 rounded-full border px-3 py-1.5 text-xs focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-foreground/60 " +
                  (active
                    ? "border-foreground bg-foreground text-background"
                    : "border-border text-ns-muted hover:border-foreground/40 hover:text-foreground")
                }
              >
                <span
                  aria-hidden
                  className={
                    "h-1.5 w-1.5 rounded-full " +
                    (active ? "bg-background" : "bg-ns-muted")
                  }
                />
                {r.label}
              </button>
            );
          })}
        </div>

        <p role="status" aria-live="polite" className="sr-only">
          {announcement}
        </p>

        <div className="mt-4 flex items-center gap-3">
          <button
            type="button"
            id={`${uid}-send`}
            disabled={!passed}
            onClick={handleSend}
            className={
              "ns-rp-send rounded-sm border bg-background px-3 py-1.5 text-sm font-medium text-foreground disabled:cursor-not-allowed disabled:opacity-40 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent " +
              (passed ? "border-ns-accent" : "border-border")
            }
          >
            {justSent ? "Sent" : "Resend request"}
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// RemnantCut — a plan-change proration panel drawn as a draper cutting cloth.
// The current billing period is a horizontal bolt: a woven-hatch SVG strip,
// selvage rules at both ends, cut at today's date. ONE governing scalar,
// `cutFrac = elapsedDays / periodDays`, drives everything on the old strip —
// the shear x-position, the dimmed "offcut" (used) width, the bright
// "remnant" (unused) width, and `creditRaw = (1 - cutFrac) * oldPrice` — the
// same expression that sizes the remnant rect also prints as the credit,
// never a second computation. A strip's bar HEIGHT maps to its plan's daily
// rate, so rect area (width-in-days * height-in-rate) literally IS money;
// that identity is the same on every row, so it survives the reflow.
//
// Choosing a candidate plan re-measures that credit against the new plan's
// daily rate: creditedDays = creditedAmount / newDailyRate, and the remnant
// animates from its old-strip position/size to that new width and the new
// plan's own bar height, across one 600ms ease-out-expo progress value `t`.
// Both endpoints already satisfy width*height === creditedAmount * K (K =
// px-per-day * px-per-rate, one constant shared by both rows), so deriving
// width(t) by lerp and height(t) = creditedAmount*K / width(t) keeps the
// rectangle's area exactly constant on every intermediate frame too — area
// preservation isn't checked after the fact, it's structurally impossible
// for the rect to have any other area at any t.
//
// Whatever the raw credit loses to the provider's rounding unit (floored to
// the nearest cent by default) is never silently absorbed: it renders as its
// own thin labelled sliver — the kerf — sitting right at the cut, between
// the offcut and the remnant. offcut + kerf + remnant always reconstruct the
// full old strip exactly; credit + charge, rounded to the cent a bill shows,
// never quite sum back to the strip's full price, and the kerf sliver is
// where the missing fraction visibly lives instead of vanishing.
//
// The cut itself is a fixed hash-seeded (mulberry32) 2px polyline, same seed
// every render regardless of props — a perfectly straight line reads as a
// CSS border, a wavered one reads as a blade having actually passed through.
//
// A11Y: the cloth (both SVG strips) is aria-hidden — decoration only, never
// the source of truth. The real controls are native <input type=radio> per
// candidate plan (grouped in a <fieldset>/<legend>, so the group's
// accessible name and per-option checked-state announcements come free from
// the browser) and a real <button> whose visible text states the derived
// numbers outright ("$8.41 credit, 6.5 days applied, ..."). A single
// role=status/aria-live=polite paragraph carries the same sentence and is
// always on screen (not sr-only), so sighted and assistive-tech readers see
// the identical figures at the identical moment. Nothing on the cloth is
// interactive; Tab only ever reaches the radios and the button.
//
// Distinct from wizard-canal-lock on purpose: that component stages a
// multi-step commitment through sequential gates and conserves nothing
// numeric — advancing a lock chamber doesn't compute or carry a quantity.
// RemnantCut is a single-step proration readout where a strict conservation
// law (area = money, unused days = used days' complement) is the entire
// mechanism; there is no sequence of steps, no validation gate, and the
// "physical" motion exists only to make one arithmetic identity legible.
//
// Pure DOM + SVG + CSS, no canvas. Every stroke/fill token is one of
// --background/--foreground/--ns-muted/--border/--ns-accent; --ns-accent is
// used only for the keyboard focus ring. prefers-reduced-motion skips the
// rAF tween entirely and renders the remnant at its final reflowed position,
// size and figures instantly.
// ---------------------------------------------------------------------------

export interface RemnantCutPlan {
  /** stable identifier, used as the native radio's value */
  id: string;
  /** display name, e.g. "Team" */
  name: string;
  /** full-period price in dollars, e.g. a monthly price */
  price: number;
  /** length of one billing period for this plan, in days */
  periodDays: number;
}

export interface RemnantCutSummary {
  planId: string;
  creditRaw: number;
  creditedAmount: number;
  kerf: number;
  creditedDays: number;
  newPeriodStart: string;
}

export interface RemnantCutProps {
  /** the plan currently being paid for */
  currentPlan: RemnantCutPlan;
  /** candidate plans offered as the radio choices */
  plans: RemnantCutPlan[];
  /** days elapsed in the current billing period as of today */
  elapsedDays: number;
  /** ISO date string for "today" — only used to print the new period's start date. @default now */
  today?: string;
  /** the provider's credit-rounding unit in dollars, e.g. 0.01 for whole cents. @default 0.01 */
  roundingUnit?: number;
  /** controlled selected candidate-plan id */
  value?: string;
  /** initial selected candidate-plan id when uncontrolled */
  defaultValue?: string;
  /** called with the newly selected candidate-plan id */
  onValueChange?: (id: string) => void;
  /** called with the derived confirmation figures when Confirm is pressed */
  onConfirm?: (summary: RemnantCutSummary) => void;
  /** fieldset legend text. @default "Change to" */
  label?: string;
  /** shared name for the native radios. @default a generated id */
  name?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

// -- geometry ----------------------------------------------------------------

const PAD = 14;
const BAR_MAX = 46;
const OLD_BASELINE = 56;
const NEW_BASELINE = 172;
const VH = 192;
const CUT_SEED = 733; // fixed — never derived from props, so the waver never re-randomizes on data change

function clamp(n: number, lo: number, hi: number) {
  return Math.max(lo, Math.min(hi, n));
}

function fmtMoney(n: number) {
  const sign = n < 0 ? "-" : "";
  return `${sign}$${Math.abs(n).toFixed(2)}`;
}

function fmtKerf(n: number) {
  // the kerf is deliberately the sub-cent remainder — shown at 4dp so the
  // "odd cents" a 2dp bill can't represent still have a printed home.
  const sign = n < 0 ? "-" : "";
  return `${sign}$${Math.abs(n).toFixed(4)}`;
}

function fmtDays(n: number) {
  return `${n.toFixed(1)} days`;
}

function fmtDate(iso: string) {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

/** mulberry32 — small, fast, deterministic given a seed */
function mulberry32(seed: number) {
  let s = seed | 0;
  return () => {
    s = (s + 0x6d2b79f5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** a fixed, constant-across-renders jittered polyline for the cut blade */
function cutWaver(topY: number, bottomY: number, cx: number) {
  const rng = mulberry32(CUT_SEED);
  const steps = 7;
  const pts: string[] = [];
  for (let i = 0; i <= steps; i++) {
    const y = topY + ((bottomY - topY) * i) / steps;
    const jitter = (rng() - 0.5) * 2; // +-1px
    pts.push(`${(cx + jitter).toFixed(2)},${y.toFixed(2)}`);
  }
  return pts.join(" ");
}

function easeOutExpo(t: number) {
  return t >= 1 ? 1 : 1 - Math.pow(2, -10 * t);
}

function useReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

interface Rect {
  x: number;
  y: number;
  w: number;
  h: number;
}

export function RemnantCut({
  currentPlan,
  plans,
  elapsedDays,
  today,
  roundingUnit = 0.01,
  value,
  defaultValue,
  onValueChange,
  onConfirm,
  label = "Change to",
  name,
  className = "",
}: RemnantCutProps) {
  const uid = useId();
  const reduced = useReducedMotion();
  const groupName = name ?? uid;
  const hatchId = `${uid}-hatch`;

  const [uncontrolled, setUncontrolled] = useState<string | undefined>(defaultValue);
  const selectedId = value !== undefined ? value : uncontrolled;
  const setSelectedId = (id: string) => {
    if (value === undefined) setUncontrolled(id);
    onValueChange?.(id);
  };

  const todayIso = today ?? new Date().toISOString();
  const selectedPlan = plans.find((p) => p.id === selectedId) ?? null;

  // -- geometry scales, derived from every plan in play so any prop set stays legible --
  const { pxPerDay, pxPerRate } = useMemo(() => {
    const maxDays = Math.max(currentPlan.periodDays, ...plans.map((p) => p.periodDays), 1);
    const maxRate = Math.max(
      currentPlan.price / currentPlan.periodDays,
      ...plans.map((p) => p.price / Math.max(1, p.periodDays)),
      1e-6
    );
    return {
      pxPerDay: clamp(400 / maxDays, 4, 22),
      pxPerRate: clamp(BAR_MAX / maxRate, 0.5, 400),
    };
  }, [currentPlan, plans]);

  const K = pxPerDay * pxPerRate; // px^2 per dollar — the one constant that makes area = money everywhere
  const amountToWidth = (amount: number, dailyRate: number) =>
    dailyRate > 0 ? (amount / dailyRate) * pxPerDay : 0;
  const rateToHeight = (rate: number) => rate * pxPerRate;

  const maxDays = Math.max(currentPlan.periodDays, ...plans.map((p) => p.periodDays), 1);
  const VW = PAD * 2 + maxDays * pxPerDay;

  // -- old strip: the single governing scalar and everything it drives --
  const oldDailyRate = currentPlan.price / currentPlan.periodDays;
  const oldBarH = rateToHeight(oldDailyRate);
  const oldStripW = currentPlan.periodDays * pxPerDay;
  const cutFrac = clamp(elapsedDays / currentPlan.periodDays, 0, 1);
  const cutX = PAD + cutFrac * oldStripW;
  const offcutW = cutX - PAD;
  const remnantW0 = oldStripW - offcutW; // pre-move remnant width, at oldBarH height
  const creditRaw = (1 - cutFrac) * currentPlan.price; // prints from the SAME cutFrac that sized remnantW0 above
  const unit = Math.max(0.0001, roundingUnit);
  const creditedAmount = Math.floor(creditRaw / unit + 1e-9) * unit;
  const kerf = Math.max(0, creditRaw - creditedAmount);
  const kerfWRaw = amountToWidth(kerf, oldDailyRate);
  const kerfW = kerf > 0 ? Math.max(kerfWRaw, 1.5) : 0;
  const remnantVisibleW = Math.max(0, remnantW0 - kerfWRaw);
  const remainingDays = (1 - cutFrac) * currentPlan.periodDays;

  const start: Rect = {
    x: cutX + kerfWRaw,
    y: OLD_BASELINE - oldBarH,
    w: remnantVisibleW,
    h: oldBarH,
  };

  // -- new strip target, once a candidate plan is selected --
  const newDailyRate = selectedPlan ? selectedPlan.price / Math.max(1, selectedPlan.periodDays) : 0;
  const newBarH = selectedPlan ? rateToHeight(newDailyRate) : 0;
  const newStripW = selectedPlan ? selectedPlan.periodDays * pxPerDay : 0;
  const creditedDays = newDailyRate > 0 ? creditedAmount / newDailyRate : 0;
  const remnantWEnd = selectedPlan ? amountToWidth(creditedAmount, newDailyRate) : 0;
  const end: Rect = { x: PAD, y: NEW_BASELINE - newBarH, w: remnantWEnd, h: newBarH };
  const newPeriodStart = todayIso;
  const newPeriodStartLabel = fmtDate(newPeriodStart);

  // -- one 600ms ease-out-expo progress value; width lerps, height is DERIVED
  // (creditedAmount*K / width) so area is exactly conserved at every frame,
  // not just at the two ends. --
  const [anim, setAnim] = useState<Rect | null>(null);
  const rafRef = useRef<number | null>(null);
  const startRef = useRef(start);
  startRef.current = start;

  useEffect(() => {
    if (rafRef.current !== null) cancelAnimationFrame(rafRef.current);
    if (!selectedPlan) {
      setAnim(null);
      return;
    }
    const from = startRef.current;
    const to = end;
    const creditPx = creditedAmount * K;
    if (reduced || creditPx <= 0) {
      setAnim(to);
      return;
    }
    const duration = 600;
    const t0 = performance.now();
    const tick = (now: number) => {
      const raw = clamp((now - t0) / duration, 0, 1);
      const eased = easeOutExpo(raw);
      const w = from.w + (to.w - from.w) * eased;
      const h = w > 0 ? creditPx / w : to.h;
      const baseline = OLD_BASELINE + (NEW_BASELINE - OLD_BASELINE) * eased;
      const x = from.x + (to.x - from.x) * eased;
      const y = baseline - h;
      setAnim({ x, y, w, h });
      if (raw < 1) {
        rafRef.current = requestAnimationFrame(tick);
      } else {
        rafRef.current = null;
      }
    };
    rafRef.current = requestAnimationFrame(tick);
    return () => {
      if (rafRef.current !== null) cancelAnimationFrame(rafRef.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedId, reduced, creditedAmount, K]);

  const cutWaverPoints = useMemo(
    () => cutWaver(OLD_BASELINE - BAR_MAX - 4, OLD_BASELINE + 6, cutX),
    [cutX]
  );

  function ticks(x0: number, days: number, baseline: number) {
    const step = pxPerDay >= 9 ? 1 : 5;
    const marks: { x: number }[] = [];
    for (let d = 0; d <= days; d += step) {
      marks.push({ x: x0 + d * pxPerDay });
    }
    return marks.map((m, i) => (
      <line
        key={i}
        x1={m.x}
        x2={m.x}
        y1={baseline + 2}
        y2={baseline + 6}
        className="stroke-current text-border"
        strokeWidth={1}
      />
    ));
  }

  function selvage(xEdge: number, baseline: number, barH: number) {
    const top = baseline - barH - 6;
    const bottom = baseline + 8;
    return [0, 3, 6].map((dx) => (
      <line
        key={dx}
        x1={xEdge + dx}
        x2={xEdge + dx}
        y1={top}
        y2={bottom}
        className="stroke-current text-border"
        strokeWidth={dx === 0 ? 1.5 : 1}
        opacity={dx === 0 ? 0.9 : 0.5}
      />
    ));
  }

  const summaryText = selectedPlan
    ? `${fmtMoney(creditRaw)} raw credit for ${fmtDays(remainingDays)} unused, rounded to ${fmtMoney(
        creditedAmount
      )} (${fmtKerf(kerf)} lost to rounding). Re-measured against ${selectedPlan.name}'s ${fmtMoney(
        newDailyRate
      )}/day rate: ${fmtDays(creditedDays)} applied. New period starts ${newPeriodStartLabel}.`
    : `${fmtMoney(creditRaw)} raw credit for ${fmtDays(remainingDays)} unused, rounded to ${fmtMoney(
        creditedAmount
      )} (${fmtKerf(kerf)} lost to rounding). Choose a plan below to apply it.`;

  const confirmText = selectedPlan
    ? `Confirm: ${fmtMoney(creditedAmount)} credit, ${fmtDays(creditedDays)} applied, ${fmtKerf(
        kerf
      )} rounding, new period starts ${newPeriodStartLabel}`
    : "Select a plan to continue";

  function handleConfirm() {
    if (!selectedPlan) return;
    onConfirm?.({
      planId: selectedPlan.id,
      creditRaw,
      creditedAmount,
      kerf,
      creditedDays,
      newPeriodStart,
    });
  }

  // fall back to the pre-tween start rect on the very first paint after a
  // selection (before the first rAF frame lands), so the piece is never
  // absent for a frame — it's always somewhere, just not yet where it's going.
  const displayRect = anim ?? (selectedPlan ? start : null);
  const showStaticRemnant = !selectedPlan;

  return (
    <div className={`w-full ${className}`}>
      <style>{`
        .ns-remnant-input {
          position: absolute;
          width: 1px;
          height: 1px;
          padding: 0;
          margin: -1px;
          overflow: hidden;
          clip: rect(0, 0, 0, 0);
          white-space: nowrap;
          border: 0;
        }
        .ns-remnant-input:focus-visible + .ns-remnant-visual {
          outline: 2px solid var(--ns-accent);
          outline-offset: 2px;
        }
        .ns-remnant-row {
          transition: background-color 150ms ease;
        }
        .ns-remnant-row:hover {
          background-color: color-mix(in oklab, var(--foreground) 4%, transparent);
        }
        @media (prefers-reduced-motion: reduce) {
          .ns-remnant-row {
            transition: none;
          }
        }
      `}</style>

      <div className="flex items-baseline justify-between gap-3">
        <div>
          <p className="font-mono text-[11px] uppercase tracking-wide text-ns-muted">Current plan</p>
          <p className="text-sm font-semibold text-foreground">
            {currentPlan.name} &middot; {fmtMoney(currentPlan.price)}/period
          </p>
        </div>
        <p className="font-mono text-[11px] text-ns-muted">
          {elapsedDays} of {currentPlan.periodDays} days used
        </p>
      </div>

      <svg
        viewBox={`0 0 ${VW} ${VH}`}
        className="mt-3 w-full"
        aria-hidden="true"
        focusable="false"
      >
        <defs>
          <pattern id={hatchId} width={6} height={6} patternUnits="userSpaceOnUse">
            <line x1={0} y1={0} x2={6} y2={6} className="stroke-current text-border" strokeWidth={0.6} opacity={0.5} />
            <line x1={6} y1={0} x2={0} y2={6} className="stroke-current text-border" strokeWidth={0.6} opacity={0.5} />
          </pattern>
        </defs>

        {/* OLD STRIP */}
        <g>
          {selvage(PAD, OLD_BASELINE, oldBarH)}
          {selvage(PAD + oldStripW, OLD_BASELINE, oldBarH)}
          <rect
            x={PAD}
            y={OLD_BASELINE - oldBarH}
            width={oldStripW}
            height={oldBarH}
            fill={`url(#${hatchId})`}
          />
          <rect
            x={PAD}
            y={OLD_BASELINE - oldBarH}
            width={offcutW}
            height={oldBarH}
            className="fill-current text-ns-muted"
            opacity={0.22}
          />
          {kerfW > 0 && (
            <rect
              x={cutX}
              y={OLD_BASELINE - oldBarH}
              width={kerfW}
              height={oldBarH}
              className="fill-current text-foreground"
              opacity={0.35}
            />
          )}
          {showStaticRemnant && remnantVisibleW > 0 && (
            <rect
              x={cutX + kerfWRaw}
              y={OLD_BASELINE - oldBarH}
              width={remnantVisibleW}
              height={oldBarH}
              className="fill-current text-foreground"
              opacity={0.6}
            />
          )}
          <polyline
            points={cutWaverPoints}
            className="stroke-current text-foreground"
            strokeWidth={2}
            fill="none"
            strokeLinejoin="round"
          />
          {ticks(PAD, currentPlan.periodDays, OLD_BASELINE)}
          {kerfW > 0 && (
            <text
              x={cutX + kerfW / 2}
              y={OLD_BASELINE - oldBarH - 8}
              textAnchor="middle"
              className="fill-current text-ns-muted"
              fontSize={7}
              fontFamily="var(--font-mono, monospace)"
            >
              kerf
            </text>
          )}
        </g>

        {/* NEW STRIP */}
        <g>
          {selectedPlan ? (
            <>
              {selvage(PAD, NEW_BASELINE, newBarH)}
              {selvage(PAD + newStripW, NEW_BASELINE, newBarH)}
              <rect
                x={PAD}
                y={NEW_BASELINE - newBarH}
                width={newStripW}
                height={newBarH}
                fill={`url(#${hatchId})`}
              />
              <rect
                x={PAD}
                y={NEW_BASELINE - newBarH}
                width={newStripW}
                height={newBarH}
                fill="none"
                className="stroke-current text-border"
                strokeWidth={1}
                strokeDasharray="2 2"
              />
              {displayRect && (
                <rect
                  data-remnant-piece
                  x={displayRect.x}
                  y={Math.min(displayRect.y, NEW_BASELINE)}
                  width={displayRect.w}
                  height={displayRect.h}
                  className="fill-current text-foreground"
                  opacity={0.68}
                />
              )}
              {ticks(PAD, selectedPlan.periodDays, NEW_BASELINE)}
            </>
          ) : (
            <rect
              x={PAD}
              y={NEW_BASELINE - 22}
              width={180}
              height={22}
              fill="none"
              className="stroke-current text-border"
              strokeWidth={1}
              strokeDasharray="4 3"
              rx={3}
            />
          )}
        </g>
      </svg>

      <fieldset className="mt-4 border-0 p-0">
        <legend className="font-mono text-[11px] uppercase tracking-wide text-ns-muted">{label}</legend>
        <div className="mt-2 flex flex-col gap-1.5">
          {plans.map((p) => {
            const rate = p.price / Math.max(1, p.periodDays);
            const checked = selectedId === p.id;
            return (
              <label
                key={p.id}
                className="ns-remnant-row relative flex cursor-pointer items-center gap-2.5 rounded-lg px-1.5 py-1.5"
              >
                <input
                  type="radio"
                  className="ns-remnant-input"
                  name={groupName}
                  value={p.id}
                  checked={checked}
                  onChange={() => setSelectedId(p.id)}
                />
                <span
                  aria-hidden="true"
                  className="ns-remnant-visual flex h-4 w-4 flex-none items-center justify-center rounded-full border border-border"
                >
                  {checked && <span className="h-2 w-2 rounded-full bg-foreground" />}
                </span>
                <span className="flex flex-1 items-baseline justify-between gap-3 text-sm">
                  <span className={checked ? "font-medium text-foreground" : "text-ns-muted"}>{p.name}</span>
                  <span className="font-mono text-[11px] text-ns-muted">
                    {fmtMoney(p.price)}/period &middot; {fmtMoney(rate)}/day
                  </span>
                </span>
              </label>
            );
          })}
        </div>
      </fieldset>

      <p
        data-remnant-figures
        role="status"
        aria-live="polite"
        className="mt-3 font-mono text-[11px] leading-relaxed text-ns-muted"
      >
        {summaryText}
      </p>

      <button
        type="button"
        data-remnant-confirm
        disabled={!selectedPlan}
        onClick={handleConfirm}
        className="mt-3 w-full rounded-md border border-border px-3 py-2 text-left font-mono text-[11px] text-foreground transition-colors duration-150 enabled:hover:border-foreground/30 disabled:cursor-not-allowed disabled:pointer-events-none disabled:opacity-50 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
      >
        {confirmText}
      </button>
    </div>
  );
}

"use client";

import { useEffect, useId, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// RemontoireRewind — a sync/upload progress strip driven by a constant-force
// remontoire instead of a plain glide. In a real remontoire d'egalite (e.g.
// Harrison's regulators) a small secondary spring is slowly wound by the
// mainspring, then trips and dumps ONE calibrated, constant-force release
// into the escapement, over and over — the escapement only ever feels the
// remontoire's flat repeated kick, never the mainspring's decaying torque.
// Here the spring glyph (an SVG coil, drawn fresh each frame as a sampled
// sine path so its pitch reads continuously, not as a swapped sprite) winds
// tighter — 5 visible turns compressing to 2 — over a slow "wind" phase,
// then snaps back out to 5 with one small overshoot on "trip". The bar
// underneath mirrors the same two-speed rhythm: a near-invisible 0.3%/s
// creep through the wind, then a fixed 6% kick — ~20x the creep rate — in
// the same instant the spring releases, so trip reads as a distinct payoff
// and never blurs into the creep. A brighter leading-edge segment (a pure
// --foreground luminance lift, never --ns-accent) flashes on that kick and
// eases back to the fill's resting opacity over 150ms.
//
// One real-time cycle = 3.2s (2.9s wind + 0.3s trip), compressed ~9.4x from
// a typical 30s precision-clock rearm interval — a discrete event, not a
// continuous oscillation, so it sits clear of any paint-rate aliasing band.
// The whole thing runs on one rAF loop keyed off real elapsed time (never
// frame count), self-driven, unbounded — nothing here waits on input.
//
// Optional controlled `value` (0-100) lets this sit on a real transfer: the
// bar's overall width then tracks `value` directly and the wind/trip cycle
// keeps running underneath purely as "work is happening" chrome layered on
// top, never touching the actual fill width itself.
// ---------------------------------------------------------------------------

const WIND_MS = 2900;
const TRIP_MS = 300;
const CYCLE_MS = WIND_MS + TRIP_MS;
const CREEP_PCT_PER_MS = 0.3 / 1000; // 0.3%/s
const TRIP_JUMP_PCT = 6;
const WIND_EASE_POWER = 1.6; // ease-in: slow start, accelerating tighten
const TURNS_RELAXED = 5;
const TURNS_WOUND = 2;
const FLASH_MS = 150;

const TRIP_BEZIER: [number, number, number, number] = [0.2, 1.4, 0.4, 1]; // one small overshoot

function clamp(n: number, lo: number, hi: number) {
  return Math.max(lo, Math.min(hi, n));
}

function bez1d(u: number, a: number, b: number, c: number, d: number) {
  const mu = 1 - u;
  return mu * mu * mu * a + 3 * mu * mu * u * b + 3 * mu * u * u * c + u * u * u * d;
}

// Solves x(u) = t for a cubic bezier anchored at (0,0)/(1,1) via bisection
// (x is monotonic since p1x/p2x sit in [0,1]), returns y(u) — which CAN
// exceed 1 mid-curve when a control point's y does, giving the overshoot.
function cubicBezierEase(t: number, [p1x, p1y, p2x, p2y]: [number, number, number, number]) {
  let lo = 0;
  let hi = 1;
  let u = t;
  for (let i = 0; i < 20; i++) {
    u = (lo + hi) / 2;
    const x = bez1d(u, 0, p1x, p2x, 1);
    if (x < t) lo = u;
    else hi = u;
  }
  return bez1d(u, 0, p1y, p2y, 1);
}

// Samples the coil as a plain sine wave across a 0-100 x span and returns an
// SVG path `d`. `turns` is the (continuous) number of full periods visible —
// fewer turns at the same span reads as coils bunched/compressed together,
// more turns reads as the loose, fully relaxed spring.
function springPath(turns: number, amplitude: number, samples: number) {
  let d = "";
  for (let i = 0; i <= samples; i++) {
    const x = (i / samples) * 100;
    const y = 12 + amplitude * Math.sin((i / samples) * turns * Math.PI * 2);
    d += i === 0 ? `M${x.toFixed(2)} ${y.toFixed(2)}` : `L${x.toFixed(2)} ${y.toFixed(2)}`;
  }
  return d;
}

function useReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

export interface RemontoireRewindProps {
  /** real transfer progress, 0-100. Omit to let the remontoire drive its own idle loop. */
  value?: number;
  /** visible + accessible label, e.g. "Syncing workspace" (default "Sync progress") */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function RemontoireRewind({ value, label = "Sync progress", className = "" }: RemontoireRewindProps) {
  const uid = useId();
  const labelId = `${uid}-label`;
  const reduced = useReducedMotion();

  const rootRef = useRef<HTMLDivElement>(null);
  const springRef = useRef<SVGPathElement>(null);
  const fillRef = useRef<HTMLDivElement>(null);
  const flashRef = useRef<HTMLDivElement>(null);
  const controlledValueRef = useRef(value);
  controlledValueRef.current = value;

  useEffect(() => {
    const root = rootRef.current;
    const spring = springRef.current;
    const fill = fillRef.current;
    const flash = flashRef.current;
    if (!root || !spring || !fill || !flash) return;

    let disposed = false;
    let visible = true;
    let raf = 0;

    // uncontrolled accumulation: how much of the strip the remontoire itself
    // has "delivered" so far this wrap, independent of any controlled value.
    let internalFill = 0;
    let fillAtTripStart = 0;
    let cycleStart = 0;
    let lastPhase: "wind" | "trip" = "wind";

    const paint = (now: number) => {
      let elapsed = now - cycleStart;
      if (elapsed >= CYCLE_MS) {
        const wraps = Math.floor(elapsed / CYCLE_MS);
        cycleStart += wraps * CYCLE_MS;
        elapsed -= wraps * CYCLE_MS;
      }

      let turns: number;
      let tripped = false;

      if (elapsed < WIND_MS) {
        const t = elapsed / WIND_MS;
        turns = TURNS_RELAXED - (TURNS_RELAXED - TURNS_WOUND) * Math.pow(t, WIND_EASE_POWER);
        if (lastPhase === "trip") {
          // just re-entered wind on a fresh cycle: lock in the post-trip baseline
          fillAtTripStart = internalFill;
        }
        lastPhase = "wind";
        internalFill = fillAtTripStart + elapsed * CREEP_PCT_PER_MS;
      } else {
        const t = clamp((elapsed - WIND_MS) / TRIP_MS, 0, 1);
        const eased = cubicBezierEase(t, TRIP_BEZIER);
        turns = TURNS_WOUND + (TURNS_RELAXED - TURNS_WOUND) * eased;
        if (lastPhase === "wind") fillAtTripStart = internalFill;
        lastPhase = "trip";
        const jumpEase = 1 - Math.pow(1 - t, 3); // ease-out, distinct kick
        internalFill = fillAtTripStart + jumpEase * TRIP_JUMP_PCT;
        tripped = t >= 1;
      }

      if (internalFill >= 100) internalFill -= 100; // seamless wrap, no pause at the seam

      const controlled = controlledValueRef.current;
      const displayFill = controlled === undefined ? internalFill : clamp(controlled, 0, 100);

      spring.setAttribute("d", springPath(turns, 4.5, 48));
      fill.style.width = `${displayFill}%`;

      if (tripped) {
        flash.style.transition = "none";
        flash.style.opacity = "1";
        // next frame: ease the flash back down over FLASH_MS
        requestAnimationFrame(() => {
          if (disposed) return;
          flash.style.transition = `opacity ${FLASH_MS}ms ease-out`;
          flash.style.opacity = "0";
        });
      }
    };

    const loop = (now: number) => {
      if (!visible) {
        raf = 0;
        return;
      }
      paint(now);
      raf = requestAnimationFrame(loop);
    };

    if (reduced) {
      // Deliberately chosen non-t0, most-structured freeze: mid-wind (turns
      // clearly between fully coiled and fully tripped) with the bar sitting
      // just after a trip-jump, so it reads as "a mechanism mid-cycle".
      spring.setAttribute("d", springPath(3.5, 4.5, 48));
      const controlled = controlledValueRef.current;
      fill.style.width = `${controlled === undefined ? 46 : clamp(controlled, 0, 100)}%`;
      flash.style.transition = "none";
      flash.style.opacity = "0.55";
    } else {
      cycleStart = performance.now();
      raf = requestAnimationFrame(loop);
    }

    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && !reduced && !raf) raf = requestAnimationFrame(loop);
    });
    io.observe(root);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      raf = 0;
      io.disconnect();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps -- `value` is read live via controlledValueRef, not a loop dependency
  }, [reduced]);

  const valueNow = value === undefined ? undefined : Math.round(clamp(value, 0, 100));

  return (
    <div ref={rootRef} className={className}>
      <div className="mb-2 flex items-baseline justify-between gap-3">
        <span id={labelId} className="font-mono text-xs text-ns-muted">
          {label}
        </span>
        {valueNow !== undefined ? (
          <span className="font-mono text-xs tabular-nums text-foreground" aria-hidden>
            {valueNow}%
          </span>
        ) : null}
      </div>

      <svg
        aria-hidden="true"
        focusable="false"
        viewBox="0 0 100 24"
        preserveAspectRatio="none"
        className="mb-1 h-6 w-full text-foreground"
      >
        <path ref={springRef} d="" fill="none" stroke="currentColor" strokeWidth={1.4} strokeLinecap="round" strokeLinejoin="round" />
      </svg>

      <div
        role="progressbar"
        aria-labelledby={labelId}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={valueNow}
        aria-valuetext={valueNow === undefined ? "Syncing" : `${valueNow}%`}
        className="relative h-1.5 overflow-hidden rounded-full border border-border bg-ns-muted/20"
      >
        <div ref={fillRef} className="absolute inset-y-0 left-0 w-0 rounded-full bg-foreground/85">
          <div ref={flashRef} className="absolute inset-y-0 right-0 w-2.5 rounded-full bg-foreground opacity-0" />
        </div>
      </div>
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
  type PointerEvent as ReactPointerEvent,
} from "react";

// ---------------------------------------------------------------------------
// BowWake — drag-to-reorder where the dragged row pushes a continuous falloff
// field through its neighbors instead of snapping them onto a hard placeholder
// line. Every other row's transform is a function of its distance to the
// dragged card's live center: translateY reflows it into the slot the card
// would land in, translateX shoulders it up to 10px sideways (smoothstep
// falloff over 1.5 row heights) so the gap it will drop into visibly reads as
// the widest point of the wake before the card ever arrives. The dragged card
// gets a 1.01 scale and a velocity-deepened shadow; on release the wake
// collapses inward first (neighbors are already converging on their slots)
// and the card itself settles last, on a short hold, into one underdamped
// spring with a single overshoot. Positions are refs-only, written per-frame
// on a direct-DOM rAF loop that sleeps once every row is at rest — no canvas,
// DOM + CSS transforms only. Distinct from avatar-stack-flock: nothing here trails a
// leader, every neighbor reacts independently to a field around one dragged
// card. Full keyboard reorder ships alongside: a grip button arms discrete
// mode (aria-pressed), arrow keys step the row through the same slots with a
// position announcement, and Escape restores the pre-pickup order. Reduced
// motion turns the field off entirely: rows reflow instantly and a plain
// dashed placeholder marks the drop slot instead.
// ---------------------------------------------------------------------------

export interface BowWakeItem {
  id: string;
  label: string;
  subtitle?: string;
}

export interface BowWakeProps {
  /** the reorderable rows, in order */
  items: BowWakeItem[];
  /** fires whenever the committed order changes — drag drop or a keyboard step */
  onReorder?: (items: BowWakeItem[]) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** accessible name for the list */
  "aria-label"?: string;
}

const ROW_H = 56;
const ROW_GAP = 8;
const STEP = ROW_H + ROW_GAP;
const WAKE_X = 10; // px, max lateral shoulder
const WAKE_RADIUS = STEP * 1.5; // smoothstep falloff distance
const DRAG_THRESHOLD = 4; // px of travel before a pointerdown becomes a live drag
const NEIGHBOR_K = 220;
const NEIGHBOR_C = 2 * 0.92 * Math.sqrt(NEIGHBOR_K); // near-critical, no overshoot
const SETTLE_K = 170;
const SETTLE_C = 2 * 0.58 * Math.sqrt(SETTLE_K); // underdamped — one overshoot
const SETTLE_HOLD_MS = 90; // wake collapses before the dragged card starts settling
const REST_EPS = 0.3;
const REST_VEPS = 2;

function smoothstep(t: number) {
  const x = Math.min(1, Math.max(0, t));
  return x * x * (3 - 2 * x);
}

function buildLiveOrder(base: string[], dragId: string, insertionIndex: number): string[] {
  const rest = base.filter((id) => id !== dragId);
  const clamped = Math.min(rest.length, Math.max(0, insertionIndex));
  rest.splice(clamped, 0, dragId);
  return rest;
}

type Phys = { x: number; y: number; vx: number; vy: number; scale: number };

type DragState = {
  id: string;
  pointerId: number;
  grabOffsetY: number;
  startClientY: number;
  active: boolean;
  baseOrder: string[];
  topY: number;
  insertionIndex: number;
  lastY: number;
  lastT: number;
  vY: number;
};

type SettleState = { startAt: number; targetSlot: number };

function GripIcon() {
  return (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" focusable="false">
      <circle cx="9" cy="6" r="1.6" />
      <circle cx="15" cy="6" r="1.6" />
      <circle cx="9" cy="12" r="1.6" />
      <circle cx="15" cy="12" r="1.6" />
      <circle cx="9" cy="18" r="1.6" />
      <circle cx="15" cy="18" r="1.6" />
    </svg>
  );
}

export function BowWake({
  items,
  onReorder,
  className = "",
  "aria-label": ariaLabel = "Reorderable list",
}: BowWakeProps) {
  const itemsById = useMemo(() => {
    const m = new Map<string, BowWakeItem>();
    for (const it of items) m.set(it.id, it);
    return m;
  }, [items]);

  const [order, setOrder] = useState<string[]>(() => items.map((i) => i.id));
  const [armedId, setArmedId] = useState<string | null>(null);
  const [liveMsg, setLiveMsg] = useState("");
  const [reduced, setReduced] = useState(false);

  const orderRef = useRef(order);
  orderRef.current = order;
  const armedIdRef = useRef<string | null>(null);
  armedIdRef.current = armedId;
  const reducedRef = useRef(false);
  reducedRef.current = reduced;
  const pickupOrderRef = useRef<string[] | null>(null);
  const firstReorder = useRef(true);

  const containerRef = useRef<HTMLDivElement>(null);
  const rowRefs = useRef<Map<string, HTMLDivElement>>(new Map());
  const placeholderRef = useRef<HTMLDivElement>(null);
  const physRef = useRef<Map<string, Phys>>(new Map());
  const dragRef = useRef<DragState | null>(null);
  const settleRef = useRef<Map<string, SettleState>>(new Map());
  const suppressClickRef = useRef(false);
  const rafRef = useRef(0);
  const lastFrameRef = useRef(0);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(mq.matches);
    update();
    mq.addEventListener("change", update);
    return () => mq.removeEventListener("change", update);
  }, []);

  // announce committed reorders (drag drop or keyboard step), never on mount
  useEffect(() => {
    if (firstReorder.current) {
      firstReorder.current = false;
      return;
    }
    onReorder?.(order.map((id) => itemsById.get(id)).filter((x): x is BowWakeItem => !!x));
  }, [order, itemsById, onReorder]);

  const writeTransform = useCallback((id: string, p: Phys) => {
    const el = rowRefs.current.get(id);
    if (!el) return;
    el.style.transform = `translate3d(${p.x.toFixed(2)}px, ${p.y.toFixed(2)}px, 0) scale(${p.scale.toFixed(3)})`;
  }, []);

  const ensureLoop = useCallback(() => {
    if (rafRef.current) return;
    lastFrameRef.current = 0;
    rafRef.current = requestAnimationFrame(loop);
  }, []);

  // Seed physics for ids that don't have a record yet (mount, or items added)
  // and write their transform synchronously before paint — otherwise every
  // row sits at the browser's default (0,0) for one frame and the whole list
  // reads as a single stacked card until the rAF loop happens to run.
  useLayoutEffect(() => {
    const phys = physRef.current;
    order.forEach((id, i) => {
      let p = phys.get(id);
      if (!p) {
        p = { x: 0, y: i * STEP, vx: 0, vy: 0, scale: 1 };
        phys.set(id, p);
      }
      writeTransform(id, p);
    });
    for (const id of Array.from(phys.keys())) {
      if (!itemsById.has(id)) phys.delete(id);
    }
    ensureLoop();
  }, [order, itemsById, writeTransform, ensureLoop]);

  // dragged-row-only visuals (lift shadow, stacking order) reset the moment
  // a drag ends, whichever way it ends — the settle spring below only owns x/y
  const resetDragVisual = useCallback((id: string) => {
    const el = rowRefs.current.get(id);
    if (!el) return;
    el.style.zIndex = "10";
    el.style.setProperty("--bw-lift", "0.35");
  }, []);

  // eslint-disable-next-line react-hooks/exhaustive-deps -- loop reads refs, deps stable across renders
  function loop(now: number) {
    rafRef.current = 0;
    const dt = lastFrameRef.current ? Math.min(0.032, (now - lastFrameRef.current) / 1000) : 1 / 60;
    lastFrameRef.current = now;

    const ord = orderRef.current;
    const drag = dragRef.current;
    const phys = physRef.current;
    let settled = true;

    const liveOrder = drag && drag.active ? buildLiveOrder(drag.baseOrder, drag.id, drag.insertionIndex) : null;

    if (drag && drag.active) {
      const p = phys.get(drag.id);
      if (p) {
        p.x = 0;
        p.y = drag.topY;
        p.vx = 0;
        p.vy = 0;
        const shadowLift = Math.min(1, Math.abs(drag.vY) / 900);
        const el = rowRefs.current.get(drag.id);
        if (el) {
          el.style.setProperty("--bw-lift", (0.35 + shadowLift * 0.65).toFixed(2));
          el.style.zIndex = "30";
        }
        if (!reducedRef.current) {
          p.scale += (1.01 - p.scale) * Math.min(1, 16 * dt);
        } else {
          p.scale = 1;
        }
        writeTransform(drag.id, p);
      }
      settled = false;

      const ph = placeholderRef.current;
      if (ph && reducedRef.current) {
        ph.style.display = "block";
        ph.style.transform = `translate3d(0, ${(drag.insertionIndex * STEP).toFixed(2)}px, 0)`;
      } else if (ph) {
        ph.style.display = "none";
      }
    } else {
      const ph = placeholderRef.current;
      if (ph) ph.style.display = "none";
    }

    for (const id of ord) {
      if (drag && drag.active && id === drag.id) continue;
      const p = phys.get(id);
      if (!p) continue;

      let targetX = 0;
      let targetY: number;

      if (liveOrder && drag) {
        const slot = liveOrder.indexOf(id);
        targetY = slot * STEP;
        const dist = Math.abs(p.y - drag.topY);
        const falloff = reducedRef.current ? 0 : smoothstep(1 - dist / WAKE_RADIUS);
        const sign = p.y < drag.topY ? -1 : 1;
        targetX = sign * WAKE_X * falloff;
      } else {
        targetY = ord.indexOf(id) * STEP;
      }

      const settle = !drag ? settleRef.current.get(id) : undefined;
      if (settle) {
        if (now < settle.startAt) {
          p.vx = 0;
          p.vy = 0;
          settled = false;
        } else {
          const targetSlotY = settle.targetSlot * STEP;
          if (reducedRef.current) {
            p.x = 0;
            p.y = targetSlotY;
            p.vx = 0;
            p.vy = 0;
            p.scale = 1;
            settleRef.current.delete(id);
          } else {
            const ax = -SETTLE_K * (p.x - 0) - SETTLE_C * p.vx;
            const ay = -SETTLE_K * (p.y - targetSlotY) - SETTLE_C * p.vy;
            p.vx += ax * dt;
            p.vy += ay * dt;
            p.x += p.vx * dt;
            p.y += p.vy * dt;
            p.scale += (1 - p.scale) * Math.min(1, 10 * dt);
            if (Math.abs(p.x) < REST_EPS && Math.abs(p.y - targetSlotY) < REST_EPS && Math.abs(p.vx) < REST_VEPS && Math.abs(p.vy) < REST_VEPS) {
              p.x = 0;
              p.y = targetSlotY;
              p.vx = 0;
              p.vy = 0;
              p.scale = 1;
              settleRef.current.delete(id);
            } else {
              settled = false;
            }
          }
        }
        writeTransform(id, p);
        continue;
      }

      if (reducedRef.current) {
        p.x = 0;
        p.y = targetY;
        p.vx = 0;
        p.vy = 0;
        p.scale = 1;
      } else {
        const ax = -NEIGHBOR_K * (p.x - targetX) - NEIGHBOR_C * p.vx;
        const ay = -NEIGHBOR_K * (p.y - targetY) - NEIGHBOR_C * p.vy;
        p.vx += ax * dt;
        p.vy += ay * dt;
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.scale += (1 - p.scale) * Math.min(1, 12 * dt);
        if (Math.abs(p.x - targetX) > REST_EPS || Math.abs(p.y - targetY) > REST_EPS || Math.abs(p.vx) > REST_VEPS || Math.abs(p.vy) > REST_VEPS) {
          settled = false;
        }
      }
      const el = rowRefs.current.get(id);
      if (el) el.style.zIndex = "10";
      writeTransform(id, p);
    }

    if (!settled || (drag && drag.active)) {
      rafRef.current = requestAnimationFrame(loop);
    }
  }

  const beginDrag = useCallback(
    (id: string, e: ReactPointerEvent<HTMLButtonElement>) => {
      if (armedIdRef.current) return; // no live drag while another row is keyboard-armed
      const container = containerRef.current;
      const row = rowRefs.current.get(id);
      if (!container || !row) return;
      const rowTop = row.getBoundingClientRect().top;
      e.currentTarget.setPointerCapture(e.pointerId);
      dragRef.current = {
        id,
        pointerId: e.pointerId,
        grabOffsetY: e.clientY - rowTop,
        startClientY: e.clientY,
        active: false,
        baseOrder: orderRef.current.slice(),
        topY: rowTop - container.getBoundingClientRect().top,
        insertionIndex: orderRef.current.indexOf(id),
        lastY: 0,
        lastT: 0,
        vY: 0,
      };
    },
    []
  );

  const moveDrag = useCallback(
    (id: string, e: ReactPointerEvent<HTMLButtonElement>) => {
      const d = dragRef.current;
      if (!d || d.id !== id || d.pointerId !== e.pointerId) return;
      const container = containerRef.current;
      if (!container) return;

      if (!d.active && Math.abs(e.clientY - d.startClientY) > DRAG_THRESHOLD) {
        d.active = true;
        suppressClickRef.current = true;
        ensureLoop();
      }
      if (!d.active) return;

      const n = d.baseOrder.length;
      const maxTop = Math.max(0, (n - 1) * STEP);
      const containerTop = container.getBoundingClientRect().top;
      const rawTop = e.clientY - containerTop - d.grabOffsetY;
      d.topY = Math.min(maxTop, Math.max(0, rawTop));
      d.insertionIndex = Math.min(n - 1, Math.max(0, Math.round(d.topY / STEP)));

      const now = performance.now();
      if (d.lastT) {
        const dt = (now - d.lastT) / 1000;
        if (dt > 0.001) d.vY = (d.topY - d.lastY) / dt;
      }
      d.lastY = d.topY;
      d.lastT = now;
      ensureLoop();
    },
    [ensureLoop]
  );

  const endDrag = useCallback(
    (id: string, e: ReactPointerEvent<HTMLButtonElement>, cancelled: boolean) => {
      const d = dragRef.current;
      if (!d || d.id !== id || d.pointerId !== e.pointerId) return;
      if (e.currentTarget.hasPointerCapture(e.pointerId)) {
        e.currentTarget.releasePointerCapture(e.pointerId);
      }
      dragRef.current = null;

      if (!d.active) return; // it was a click-length press; the click handler arms it
      resetDragVisual(id);

      if (cancelled) {
        settleRef.current.set(id, { startAt: 0, targetSlot: d.baseOrder.indexOf(id) });
        ensureLoop();
        return;
      }

      const finalOrder = buildLiveOrder(d.baseOrder, id, d.insertionIndex);
      settleRef.current.set(id, { startAt: performance.now() + SETTLE_HOLD_MS, targetSlot: finalOrder.indexOf(id) });
      setOrder(finalOrder);
      ensureLoop();
    },
    [ensureLoop, resetDragVisual]
  );

  const armOrDrop = useCallback(
    (id: string) => {
      if (suppressClickRef.current) {
        suppressClickRef.current = false;
        return;
      }
      if (armedIdRef.current && armedIdRef.current !== id) return; // another row already armed

      if (armedIdRef.current === id) {
        const idx = orderRef.current.indexOf(id);
        setLiveMsg(`Dropped. ${itemsById.get(id)?.label ?? ""}, now at position ${idx + 1} of ${orderRef.current.length}.`);
        setArmedId(null);
        pickupOrderRef.current = null;
      } else {
        pickupOrderRef.current = orderRef.current.slice();
        setArmedId(id);
        const idx = orderRef.current.indexOf(id);
        setLiveMsg(
          `Grabbed ${itemsById.get(id)?.label ?? ""}. Now at position ${idx + 1} of ${orderRef.current.length}. Use arrow keys to move, space to drop, escape to cancel.`
        );
      }
    },
    [itemsById]
  );

  const onHandleKeyDown = useCallback(
    (id: string, e: ReactKeyboardEvent<HTMLButtonElement>) => {
      if (armedIdRef.current !== id) return;
      if (e.key !== "ArrowUp" && e.key !== "ArrowDown") return;
      e.preventDefault();
      const cur = orderRef.current;
      const idx = cur.indexOf(id);
      const swapWith = e.key === "ArrowUp" ? idx - 1 : idx + 1;
      if (swapWith < 0 || swapWith >= cur.length) return;
      const next = cur.slice();
      next[idx] = cur[swapWith];
      next[swapWith] = cur[idx];
      setOrder(next);
      settleRef.current.set(id, { startAt: 0, targetSlot: swapWith });
      const otherId = cur[swapWith];
      settleRef.current.set(otherId, { startAt: 0, targetSlot: idx });
      setLiveMsg(`${itemsById.get(id)?.label ?? ""}, now at position ${swapWith + 1} of ${cur.length}.`);
      ensureLoop();
    },
    [ensureLoop, itemsById]
  );

  // Escape: cancel a live pointer drag, or restore the pre-pickup order while
  // keyboard-armed. Deliberately global (not scoped to focus) — the operation
  // is "in flight" regardless of where focus lands in between.
  useEffect(() => {
    function onKeyDown(e: KeyboardEvent) {
      if (e.key !== "Escape") return;
      const d = dragRef.current;
      if (d) {
        if (d.active) {
          resetDragVisual(d.id);
          settleRef.current.set(d.id, { startAt: 0, targetSlot: d.baseOrder.indexOf(d.id) });
          ensureLoop();
        }
        dragRef.current = null;
        return;
      }
      const armed = armedIdRef.current;
      if (!armed) return;
      const restore = pickupOrderRef.current;
      if (restore) setOrder(restore);
      const idx = restore ? restore.indexOf(armed) : 0;
      setLiveMsg(`Reorder cancelled. ${itemsById.get(armed)?.label ?? ""} restored to position ${idx + 1} of ${restore?.length ?? 0}.`);
      setArmedId(null);
      pickupOrderRef.current = null;
    }
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [itemsById, ensureLoop, resetDragVisual]);

  useEffect(() => {
    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, []);

  const containerHeight = Math.max(ROW_H, order.length * STEP - ROW_GAP);

  return (
    <div
      className={`relative ${className}`}
      role="list"
      aria-label={ariaLabel}
      style={{ height: containerHeight }}
      ref={containerRef}
    >
      <div aria-live="polite" role="status" className="sr-only">
        {liveMsg}
      </div>

      <div
        ref={placeholderRef}
        aria-hidden="true"
        style={{ display: "none", height: ROW_H }}
        className="pointer-events-none absolute inset-x-0 top-0 rounded-md border border-dashed border-border/70"
      />

      {order.map((id, rowIdx) => {
        const item = itemsById.get(id);
        if (!item) return null;
        const pos = order.indexOf(id) + 1;
        const isArmed = armedId === id;
        return (
          <div
            key={id}
            ref={(el) => {
              if (el) rowRefs.current.set(id, el);
              else rowRefs.current.delete(id);
            }}
            role="listitem"
            className="absolute inset-x-0 top-0 will-change-transform"
            style={{ height: ROW_H, "--bw-lift": 0.35 } as React.CSSProperties}
          >
            <div
              className={`flex h-full items-center gap-3 rounded-md border bg-surface px-3 transition-colors duration-150 ${
                isArmed ? "border-ns-accent" : "border-border hover:border-foreground/20"
              }`}
              style={{
                boxShadow: `0 calc(6px + 10px * var(--bw-lift)) calc(16px + 10px * var(--bw-lift)) calc(-8px - 2px * var(--bw-lift)) rgba(0,0,0,calc(0.22 + 0.18 * var(--bw-lift)))`,
              }}
            >
              <button
                type="button"
                data-bow-handle
                data-bow-row={rowIdx}
                aria-pressed={isArmed}
                aria-label={`${isArmed ? "Grabbed. " : ""}Reorder ${item.label}. Position ${pos} of ${order.length}.`}
                onPointerDown={(e) => beginDrag(id, e)}
                onPointerMove={(e) => moveDrag(id, e)}
                onPointerUp={(e) => endDrag(id, e, false)}
                onPointerCancel={(e) => endDrag(id, e, true)}
                onClick={() => armOrDrop(id)}
                onKeyDown={(e) => onHandleKeyDown(id, e)}
                className={`flex shrink-0 cursor-grab touch-none select-none items-center justify-center rounded-sm p-1.5 text-ns-muted transition-colors duration-150 hover:bg-foreground/10 hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent active:cursor-grabbing ${
                  isArmed ? "bg-ns-accent/10 text-ns-accent" : ""
                }`}
              >
                <GripIcon />
              </button>
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm text-foreground">{item.label}</p>
                {item.subtitle ? (
                  <p className="truncate font-mono text-xs text-ns-muted">{item.subtitle}</p>
                ) : null}
              </div>
              <span className="shrink-0 rounded-full border border-border bg-background px-1.5 py-0.5 font-mono text-[10px] text-ns-muted">
                {pos}
              </span>
            </div>
          </div>
        );
      })}
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// ChunkSieve — RAG retrieval drawn as a literal sieve.
//
// One 2px --foreground rule spans the frame at 42% height. Every retrieved
// chunk is placed on x by RANK (highest similarity leftmost, 1fr per column)
// and on y by SCORE relative to the cutoff. A chunk whose score clears the
// cutoff RESTS ON the rule as a solid hairline card — mono doc id, char span,
// a 34px score bar — lifted (score − cutoff) × 240px above it. A chunk that
// misses FALLS THROUGH: a bare 1px stub at 0.38 alpha, only its doc id, sunk
// (cutoff − score) × 300px below the rule and tapering 1fr → 40% wide as it
// falls. So the resting composition is one hard boundary with the ink packed
// against it: six solid rows above, a thin dust of ghosts below, most of the
// lower frame empty.
//
// The second, harder question a retrieval panel usually hides is which of the
// retained chunks the answer actually USED. An ANSWER RAIL (1px --border) runs
// above the retained zone; a chunk with used:true draws a 1px connector from
// its right edge up to the rail, ending in a 3px filled square. A retained but
// uncited chunk draws NOTHING. "Retrieved and never cited" — the real RAG
// failure mode — is therefore visible as absence, with no badge and no color.
//
// The rule is the control: it is a real role="slider", and a vertical drag on
// it maps 1px = 0.004 score. Chunks crossing the new cutoff reflow between the
// two zones on one shared 240ms transform+opacity transition — the reflow IS
// the feedback, there is no separate readout animation.
//
// Ink is --foreground / --border / --ns-muted throughout; --ns-accent is spent only
// on focus rings. DOM + CSS only, no canvas, no SVG, no measurement pass.
// ---------------------------------------------------------------------------

export interface SieveChunk {
  id: string;
  /** Short source identifier, e.g. "runbook.md". Rendered in mono. */
  doc: string;
  /** Character offsets of the chunk inside its document: [start, end]. */
  span: [number, number];
  /** Similarity score, 0…1. Drives both zone and height. */
  score: number;
  /** True when the generated answer actually cited this chunk. */
  used?: boolean;
  /** Chunk text, shown in the strip pinned to the frame's bottom edge on hover. */
  preview: string;
}

export interface ChunkSieveProps {
  /** Retrieved chunks. Rank on screen is derived from score, not array order. */
  chunks: SieveChunk[];
  /** Controlled similarity cutoff, 0…1. */
  cutoff?: number;
  /** Initial cutoff when uncontrolled. @default 0.5 */
  defaultCutoff?: number;
  /** Fires on release / keypress with the value snapped to 3 decimals. */
  onCutoffChange?: (cutoff: number) => void;
  /** Frame height in px — the sieve's geometry is absolute, not fluid. @default 440 */
  height?: number;
  /** Accessible name for the cutoff slider. @default "Similarity cutoff" */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const LINE_PCT = 0.42; // the sieve rule's height in the frame
const LIFT_PER_SCORE = 240; // px of lift per 1.0 of score above the cutoff
const DROP_PER_SCORE = 300; // px of fall per 1.0 of score below the cutoff
const CARD_H = 52; // retained card height (fixed, so connectors need no measuring)
const RAIL_TOP = 24; // answer rail, px from the frame's inner top
const RAIL_GAP = 14; // minimum clearance between a lifted card and the rail
const SCORE_BAR_W = 34;
const PX_PER_SCORE = 0.004; // drag sensitivity: 1px = 0.004 score
const STUB_MIN_W = 40; // % width a stub tapers to at the bottom of its fall
// Stub alpha. 0.38 is the floor at which a 1px --foreground hairline and 9px
// mono are still legible in BOTH themes (~2.6:1 light, ~3.0:1 dark); the
// original 0.14 composited to ~1.35:1 in both, i.e. not rendered — which
// deleted the "falls through" half of the sieve from the resting frame.
const STUB_ALPHA = 0.38;
const STUB_ALPHA_DIM = 0.15; // a stub while some other chunk is hovered

function clamp01(v: number): number {
  return v < 0 ? 0 : v > 1 ? 1 : v;
}

function round3(v: number): number {
  return Math.round(v * 1000) / 1000;
}

function fmt3(v: number): string {
  return v.toFixed(3);
}

export function ChunkSieve({
  chunks,
  cutoff,
  defaultCutoff = 0.5,
  onCutoffChange,
  height = 440,
  label = "Similarity cutoff",
  className = "",
}: ChunkSieveProps) {
  const isControlled = cutoff !== undefined;
  const [internal, setInternal] = useState(() => clamp01(defaultCutoff));
  // Live drag value overrides both, so a controlled consumer still sees the
  // reflow while the pointer is down even though onCutoffChange fires on release.
  const [live, setLive] = useState<number | null>(null);
  const committed = clamp01(isControlled ? cutoff! : internal);
  const value = live ?? committed;

  const [hovered, setHovered] = useState<string | null>(null);
  const [arrived, setArrived] = useState<string[]>([]);
  const prevRetained = useRef<Set<string> | null>(null);
  const dragRef = useRef<{ y: number; from: number } | null>(null);
  const arriveTimer = useRef<number | null>(null);

  const ordered = [...chunks].sort((a, b) => b.score - a.score);
  const retainedCount = ordered.filter((c) => c.score >= value).length;

  const lineY = height * LINE_PCT;
  const maxLift = Math.max(0, lineY - CARD_H - RAIL_TOP - RAIL_GAP);
  const maxDrop = Math.max(1, height - lineY - 28);

  // Newly retained chunks pulse once on arrival.
  useEffect(() => {
    const now = new Set(
      chunks.filter((c) => c.score >= value).map((c) => c.id)
    );
    const prev = prevRetained.current;
    prevRetained.current = now;
    if (!prev) return;
    const fresh: string[] = [];
    now.forEach((id) => {
      if (!prev.has(id)) fresh.push(id);
    });
    if (fresh.length === 0) return;
    setArrived(fresh);
    // The timer lives in a ref, not in the effect's cleanup: `value` changes on
    // every frame of a drag, and an effect-scoped cleanup would cancel the
    // pending clear on the very next frame, leaving `arrived` stuck with stale
    // ids so those chunks could never pulse again on re-entry.
    if (arriveTimer.current !== null) window.clearTimeout(arriveTimer.current);
    arriveTimer.current = window.setTimeout(() => {
      arriveTimer.current = null;
      setArrived([]);
    }, 900);
  }, [value, chunks]);

  useEffect(
    () => () => {
      if (arriveTimer.current !== null) window.clearTimeout(arriveTimer.current);
    },
    []
  );

  const commit = (next: number) => {
    const v = round3(clamp01(next));
    if (!isControlled) setInternal(v);
    if (v !== round3(committed)) onCutoffChange?.(v);
  };

  const onPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    dragRef.current = { y: e.clientY, from: value };
    e.currentTarget.setPointerCapture(e.pointerId);
    setLive(value);
  };

  const onPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    const d = dragRef.current;
    if (!d) return;
    // Dragging the rule DOWN lowers the bar: more chunks clear it.
    setLive(clamp01(d.from - (e.clientY - d.y) * PX_PER_SCORE));
  };

  const endDrag = () => {
    const d = dragRef.current;
    if (!d) return;
    dragRef.current = null;
    const v = live;
    setLive(null);
    if (v !== null) commit(v);
  };

  const onKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    let next: number | null = null;
    if (e.key === "ArrowUp" || e.key === "ArrowRight") next = value + 0.01;
    else if (e.key === "ArrowDown" || e.key === "ArrowLeft") next = value - 0.01;
    else if (e.key === "PageUp") next = value + 0.1;
    else if (e.key === "PageDown") next = value - 0.1;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = 1;
    else return;
    e.preventDefault();
    setLive(null);
    commit(next);
  };

  const hoveredChunk = hovered ? chunks.find((c) => c.id === hovered) : undefined;
  const readout = `cutoff ${fmt3(value)} · ${retainedCount}/${chunks.length} retained`;

  return (
    <div
      className={`ns-sieve-root relative w-full overflow-hidden border border-border bg-background ${className}`}
      style={{ height }}
    >
      <style>{`
.ns-sieve-flow{transition:transform 240ms cubic-bezier(0.22,1,0.36,1),opacity 240ms cubic-bezier(0.22,1,0.36,1),width 240ms cubic-bezier(0.22,1,0.36,1),height 240ms cubic-bezier(0.22,1,0.36,1)}
.ns-sieve-strip{transition:opacity 180ms ease-out,transform 180ms ease-out}
@keyframes ns-sieve-breathe{0%{transform:translateY(-0.5px)}50%{transform:translateY(0.5px)}100%{transform:translateY(-0.5px)}}
@keyframes ns-sieve-arrive{0%{opacity:0.6}100%{opacity:1}}
.ns-sieve-rule{animation:ns-sieve-breathe 4s ease-in-out infinite}
.ns-sieve-arrive{animation:ns-sieve-arrive 900ms ease-out 1}
@media (prefers-reduced-motion: reduce){
  .ns-sieve-flow,.ns-sieve-strip{transition:none}
  .ns-sieve-rule,.ns-sieve-arrive{animation:none}
}
`}</style>

      {/* ---- answer rail ---- */}
      <div
        aria-hidden="true"
        className="pointer-events-none absolute left-3 right-3 h-px bg-border"
        style={{ top: RAIL_TOP }}
      />
      <span
        aria-hidden="true"
        className="pointer-events-none absolute right-3 font-mono text-[9px] uppercase tracking-[0.18em] text-ns-muted"
        style={{ top: RAIL_TOP - 16 }}
      >
        answer
      </span>

      {/* ---- live readout, sitting just above the rule ----
           aria-hidden on purpose: the slider's aria-valuetext already carries
           "cutoff 0.742, 6 of 12 chunks retained", so an aria-live copy of the
           same string would double-announce on every arrow key and on every
           frame of a drag. */}
      <div
        aria-hidden="true"
        className="pointer-events-none absolute right-3 z-10 font-mono text-[10px] tabular-nums text-ns-muted"
        style={{ top: lineY - 30 }}
      >
        {readout}
      </div>

      {/* ---- chunk columns ---- */}
      <div className="absolute inset-y-0 left-3 right-3 flex items-stretch gap-1.5">
        {ordered.map((c) => {
          const retained = c.score >= value;
          const isHovered = hovered === c.id;
          const dim = hovered !== null && !isHovered;
          const spanText = `[${c.span[0]}-${c.span[1]}]`;
          // No `border-0`/`bg-transparent` here: preflight already resets both
          // on <button>, and stating them would race the retained card's own
          // `border border-border bg-background` in the generated stylesheet.
          const common =
            "ns-sieve-flow absolute left-0 right-0 block p-0 text-left focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent";

          if (retained) {
            const lift = Math.min(maxLift, (c.score - value) * LIFT_PER_SCORE);
            const connectorH = lineY - lift - CARD_H - RAIL_TOP;
            return (
              <div key={c.id} className="relative min-w-0 flex-1">
                <div className="absolute left-0 right-0" style={{ top: lineY }}>
                  <button
                    type="button"
                    aria-label={`${c.doc}, characters ${c.span[0]} to ${
                      c.span[1]
                    }, score ${fmt3(c.score)}, retained${
                      c.used ? ", cited in the answer" : ", not cited"
                    }`}
                    onPointerEnter={() => setHovered(c.id)}
                    onPointerLeave={() => setHovered((h) => (h === c.id ? null : h))}
                    onFocus={() => setHovered(c.id)}
                    onBlur={() => setHovered((h) => (h === c.id ? null : h))}
                    className={`${common} ${
                      arrived.includes(c.id) ? "ns-sieve-arrive" : ""
                    } bottom-0 flex flex-col justify-between border border-border bg-background px-1.5 py-1`}
                    style={{
                      height: CARD_H,
                      opacity: dim ? 0.35 : 1,
                      transform: `translateY(${-(lift + (isHovered ? 2 : 0))}px)`,
                    }}
                  >
                    {/* connector to the answer rail — drawn only when cited */}
                    {c.used && connectorH > 6 && (
                      <span
                        aria-hidden="true"
                        className="ns-sieve-flow absolute bottom-full right-[3px] w-px bg-foreground"
                        style={{ height: connectorH }}
                      >
                        <span className="absolute -top-px left-1/2 h-[3px] w-[3px] -translate-x-1/2 bg-foreground" />
                      </span>
                    )}
                    <span className="block truncate font-mono text-[10px] leading-none text-foreground">
                      {c.doc}
                    </span>
                    <span className="block truncate font-mono text-[9px] leading-none tabular-nums text-ns-muted">
                      {spanText}
                    </span>
                    <span
                      aria-hidden="true"
                      className="relative block h-[3px] max-w-full bg-border"
                      style={{ width: SCORE_BAR_W }}
                    >
                      <span
                        className="absolute inset-y-0 left-0 bg-foreground"
                        style={{ width: `${clamp01(c.score) * 100}%` }}
                      />
                    </span>
                  </button>
                </div>
              </div>
            );
          }

          const drop = Math.min(maxDrop, (value - c.score) * DROP_PER_SCORE);
          const taper = clamp01(drop / maxDrop);
          return (
            <div key={c.id} className="relative min-w-0 flex-1">
              <div className="absolute left-0 right-0" style={{ top: lineY }}>
                <button
                  type="button"
                  aria-label={`${c.doc}, characters ${c.span[0]} to ${
                    c.span[1]
                  }, score ${fmt3(c.score)}, below the cutoff`}
                  onPointerEnter={() => setHovered(c.id)}
                  onPointerLeave={() => setHovered((h) => (h === c.id ? null : h))}
                  onFocus={() => setHovered(c.id)}
                  onBlur={() => setHovered((h) => (h === c.id ? null : h))}
                  className={`${common} top-0 py-1`}
                  style={{
                    width: `${100 - (100 - STUB_MIN_W) * taper}%`,
                    right: "auto",
                    opacity: isHovered ? 1 : dim ? STUB_ALPHA_DIM : STUB_ALPHA,
                    transform: `translateY(${drop - (isHovered ? 2 : 0)}px)`,
                  }}
                >
                  <span
                    aria-hidden="true"
                    className="block h-px w-full bg-foreground"
                  />
                  <span className="mt-1 block truncate font-mono text-[9px] leading-none text-foreground">
                    {c.doc}
                  </span>
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {/* ---- the sieve rule: the control ----
           The focus ring uses a NEGATIVE outline-offset on purpose: the grab
           strip runs edge to edge, so an outward offset pushes its left/right
           caps under the frame's overflow-hidden and the ring degrades into
           two loose horizontal lines. */}
      <div
        data-sieve-line=""
        role="slider"
        tabIndex={0}
        aria-label={label}
        aria-orientation="vertical"
        aria-valuemin={0}
        aria-valuemax={1}
        aria-valuenow={round3(value)}
        aria-valuetext={`cutoff ${fmt3(value)}, ${retainedCount} of ${
          chunks.length
        } chunks retained`}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={endDrag}
        onPointerCancel={endDrag}
        onKeyDown={onKeyDown}
        className="absolute left-0 right-0 z-20 flex h-10 -translate-y-1/2 cursor-ns-resize touch-none items-center focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ns-accent"
        style={{ top: lineY }}
      >
        <span
          aria-hidden="true"
          className="ns-sieve-rule block h-[2px] w-full bg-foreground"
        />
      </div>

      {/* ---- preview strip, pinned to the frame's bottom edge ---- */}
      <div
        aria-hidden="true"
        className="ns-sieve-strip pointer-events-none absolute inset-x-0 bottom-0 border-t border-border bg-background px-3 py-2"
        style={{
          opacity: hoveredChunk ? 1 : 0,
          transform: `translateY(${hoveredChunk ? 0 : 6}px)`,
        }}
      >
        <p className="truncate font-mono text-[10px] leading-relaxed text-ns-muted">
          {hoveredChunk ? (
            <>
              <span className="text-foreground">{hoveredChunk.doc}</span>
              <span className="tabular-nums">
                {" "}
                [{hoveredChunk.span[0]}-{hoveredChunk.span[1]}] ·{" "}
                {fmt3(hoveredChunk.score)} ·{" "}
                {hoveredChunk.score >= value
                  ? hoveredChunk.used
                    ? "cited"
                    : "retained, not cited"
                  : "below cutoff"}
              </span>
              <span className="text-ns-muted"> — {hoveredChunk.preview}</span>
            </>
          ) : (
            " "
          )}
        </p>
      </div>
    </div>
  );
}

export default ChunkSieve;

"use client";

import { useEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// ReturnAviso — an @mention chip that behaves like registered post. On send,
// a thin stub tears off along a dashed perforation at the chip's trailing
// edge and drifts 12px clear, holding at 40% opacity — dispatched, then
// delivered, look identical, because neither is the news. Only when the
// mentioned person actually opens the thread does the stub travel back and
// dock as a filled corner notch, matching the chip's own corner radius, with
// a small Geist Mono timestamp riding along — a permanent per-mention read
// receipt, legible at rest, no hover required.
//
// Mechanism: `deliveryState` (0 sent, 1 delivered, 2 seen) is the ONLY
// animation input. Everything else — stub offset, stub width/fill, notch
// radius, timestamp reveal — is a pure function of `seen = deliveryState >=
// 2`. Sent and delivered render byte-identical on purpose: the person you
// mentioned hasn't looked yet either way, so the chip has nothing new to
// report until they do. The prop still carries three values rather than a
// boolean because the sync layer's own transport states (queued vs acked)
// are worth being honest about in the API, even where the UI collapses two
// of them into one look.
//
// Hard constraint: this component NEVER promotes itself to "seen" on its
// own — deliveryState is fully controlled, read straight from the sync
// layer's confirmation, never guessed optimistically on send. A receipt
// that fires before the fact is decoration wearing a receipt's clothes.
//
// Accessibility: the chip is a real <a> to the mentioned person; its
// accessible name is "@name" (plain text content), and aria-description
// spells out the state in words ("mentioned, seen 14:22" / "mentioned, not
// yet seen") so the two-state receipt is always available as text, not just
// as a shape change. The stub, perforation and inline timestamp are all
// aria-hidden — duplicating aria-description, never adding information a
// screen reader user wouldn't otherwise have. A visually-hidden aria-live
// region announces the sent/delivered -> seen transition, but only when
// `authoredByViewer` is true: a receipt is only news to the person who sent
// the mention, not to everyone re-rendering a thread that mentions them.
// prefers-reduced-motion drops the translate/width travel and crossfades
// opacity + fill only — still three readable states, no travel.
//
// Differs from badge-unread-tarnish: that ages the CURRENT user's own
// unread state on a badge over elapsed time. This tracks a round-trip
// acknowledgment on someone ELSE's attention, driven by discrete confirmed
// events from a sync layer, never by a clock.
//
// DOM/CSS only, no canvas. Colors: --background, --foreground, --ns-muted,
// --border. --ns-accent is reserved for the focus ring only.
// ---------------------------------------------------------------------------

const EASE_EXPO = "cubic-bezier(0.22, 1, 0.36, 1)";
const TRANSITION_MS = 220;

export type AvisoDeliveryState = 0 | 1 | 2;

export interface ReturnAvisoProps {
  /** The mentioned person's display name, rendered as "@name". Also forms
   * the chip's accessible name. */
  name: string;
  /** Link target for the mentioned person — this is a real link, not a
   * decorated span. */
  href: string;
  /** 0 = sent, 1 = delivered, 2 = seen — from the sync layer only. The
   * single governing scalar: stub position, notch fill and timestamp
   * visibility all derive from this and nothing else. Never set this to 2
   * optimistically on send. */
  deliveryState: AvisoDeliveryState;
  /** Pre-formatted "HH:MM" shown once deliveryState reaches 2. Formatting
   * (locale, timezone) is the caller's call, not this component's — passing
   * a raw Date here would make the same receipt read a different clock time
   * on the server that renders it than on the browser that hydrates it. */
  seenAt?: string;
  /** True only for mentions the current viewer authored. Gates the polite
   * live-region announcement on the not-seen -> seen transition — a receipt
   * is news to the sender, not to every viewer of a thread that mentions
   * them. @default false */
  authoredByViewer?: boolean;
  /** extra classes merged onto the rendered <a> */
  className?: string;
}

export function ReturnAviso({
  name,
  href,
  deliveryState,
  seenAt,
  authoredByViewer = false,
  className = "",
}: ReturnAvisoProps) {
  const seen = deliveryState >= 2;

  const description = seen
    ? `mentioned, seen ${seenAt ?? ""}`.trim()
    : "mentioned, not yet seen";

  // Announce only the not-seen -> seen crossing, only for mentions the
  // viewer authored, and never on mount (a chip can mount already seen —
  // e.g. a page reload after the fact — and that is not news either).
  const [announcement, setAnnouncement] = useState("");
  const prevSeenRef = useRef(seen);
  const firstRenderRef = useRef(true);
  const clearTimerRef = useRef<number | undefined>(undefined);

  useEffect(() => {
    if (firstRenderRef.current) {
      firstRenderRef.current = false;
      prevSeenRef.current = seen;
      return;
    }
    const justSeen = !prevSeenRef.current && seen;
    prevSeenRef.current = seen;
    if (!justSeen || !authoredByViewer) return;

    setAnnouncement(`@${name} saw your mention${seenAt ? ` at ${seenAt}` : ""}`);
    window.clearTimeout(clearTimerRef.current);
    // Cleared a beat later so a second live region on the page re-reads a
    // repeat announcement as new rather than finding stale, identical text.
    clearTimerRef.current = window.setTimeout(() => setAnnouncement(""), 4000);
  }, [seen, authoredByViewer, name, seenAt]);

  useEffect(() => () => window.clearTimeout(clearTimerRef.current), []);

  return (
    <>
      <a
        href={href}
        aria-description={description}
        data-ns-aviso-seen={seen ? "" : undefined}
        className={`ns-aviso relative inline-flex items-stretch rounded-sm border border-border bg-transparent py-1 pl-2.5 pr-4 font-sans text-sm leading-none text-foreground no-underline transition-colors duration-150 hover:border-foreground/40 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent ${className}`}
      >
        <span className="self-center">@{name}</span>

        <span
          className="ns-aviso-time self-center overflow-hidden font-mono text-[10px] tracking-tight text-ns-muted"
          data-seen={seen ? "" : undefined}
          aria-hidden="true"
        >
          <span className="ns-aviso-time-inner block whitespace-nowrap">{seenAt ?? ""}</span>
        </span>

        <span aria-hidden="true" className="ns-aviso-perf pointer-events-none absolute inset-y-[3px] right-3 w-px" />
        <span
          aria-hidden="true"
          data-seen={seen ? "" : undefined}
          className="ns-aviso-stub pointer-events-none absolute inset-y-0 right-0"
        />

        <style>{`
        .ns-aviso-perf {
          background: var(--border);
          -webkit-mask-image: repeating-linear-gradient(to bottom, black 0 2px, transparent 2px 4px);
          mask-image: repeating-linear-gradient(to bottom, black 0 2px, transparent 2px 4px);
        }
        .ns-aviso-stub {
          width: 3px;
          background: transparent;
          border: 1px solid var(--border);
          border-radius: 0;
          opacity: 0.4;
          transform: translateX(12px);
          transition:
            transform ${TRANSITION_MS}ms ${EASE_EXPO},
            width ${TRANSITION_MS}ms ${EASE_EXPO},
            opacity ${TRANSITION_MS}ms ${EASE_EXPO},
            background-color ${TRANSITION_MS}ms ${EASE_EXPO},
            border-color ${TRANSITION_MS}ms ${EASE_EXPO},
            border-radius ${TRANSITION_MS}ms ${EASE_EXPO};
        }
        .ns-aviso-stub[data-seen] {
          width: 7px;
          background: var(--foreground);
          border-color: var(--foreground);
          border-radius: 0 6px 6px 0;
          opacity: 1;
          transform: translateX(0);
        }
        .ns-aviso-time {
          display: grid;
          grid-template-columns: 0fr;
          opacity: 0;
          transition:
            grid-template-columns ${TRANSITION_MS}ms ${EASE_EXPO},
            opacity ${TRANSITION_MS}ms ${EASE_EXPO};
        }
        .ns-aviso-time[data-seen] {
          grid-template-columns: 1fr;
          opacity: 1;
          margin-left: 6px;
        }
        .ns-aviso-time-inner {
          min-width: 0;
        }
        @media (prefers-reduced-motion: reduce) {
          /* No travel: the stub sits docked at all times and the three
             states crossfade through fill/opacity only, never position or
             width — a pure state indicator instead of a physical journey. */
          .ns-aviso-stub,
          .ns-aviso-stub[data-seen] {
            width: 5px;
            transform: none;
            border-radius: 0 6px 6px 0;
            transition:
              opacity ${TRANSITION_MS}ms linear,
              background-color ${TRANSITION_MS}ms linear,
              border-color ${TRANSITION_MS}ms linear;
          }
          .ns-aviso-time,
          .ns-aviso-time[data-seen] {
            grid-template-columns: 1fr;
            transition: opacity ${TRANSITION_MS}ms linear;
          }
        }
      `}</style>
      </a>

      {/* Separate from the link on purpose — nested inside the <a>, this
          text would splice into the link's own accessible name for as long
          as it holds a message ("@dana" -> "@dana @dana saw your mention at
          14:22"), which the a11y audit's mere name-exists check would never
          catch. */}
      <span aria-live="polite" className="sr-only">
        {announcement}
      </span>
    </>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// RippleUnfold — media behind a coarse tile grid. A height-field wave sim
// sweeps a ripple front out from the trigger point (scroll-into-view or first
// pointer entry): tiles pop open when local amplitude crosses a threshold,
// and revealed tiles refract their source rect along the wave gradient like
// wet glass. After full reveal the cursor keeps perturbing the water.
// Single DPR-aware Canvas 2D, direct-DOM rAF loop that sleeps when the field
// and every tile spring settle. All drawn ink derives from CSS tokens at
// mount and re-derives live on documentElement class changes.
// ---------------------------------------------------------------------------

type RGB = [number, number, number];

interface Palette {
  background: RGB;
  foreground: RGB;
  surface: RGB;
  border: RGB;
  muted: RGB;
  accent: RGB;
}

const FALLBACK_DARK: Palette = {
  background: [10, 10, 10],
  foreground: [237, 237, 237],
  surface: [23, 23, 23],
  border: [46, 46, 46],
  muted: [143, 143, 143],
  accent: [0, 107, 255],
};

const FALLBACK_LIGHT: Palette = {
  background: [255, 255, 255],
  foreground: [23, 23, 23],
  surface: [250, 250, 250],
  border: [235, 235, 235],
  muted: [143, 143, 143],
  accent: [0, 107, 255],
};

const EPS = 0.004; // dual sleep epsilon for max|h| and max|v|
const SPRING_K = 90; // s^-2
const SPRING_C = 2 * 0.7 * Math.sqrt(SPRING_K); // zeta = 0.7
const SQUASH_MS = 320;
const DT_MAX = 0.033;

function css(c: RGB, a: number) {
  return `rgba(${c[0]},${c[1]},${c[2]},${a})`;
}

// resolve a CSS custom property to rgb via an in-document probe element
function readToken(probe: HTMLElement, token: string, fallback: RGB): RGB {
  probe.style.color = "";
  probe.style.color = `var(${token})`;
  const raw = getComputedStyle(probe).color;
  let m = raw.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
  if (m) return [+m[1]!, +m[2]!, +m[3]!];
  m = raw.match(/color\(srgb\s+([\d.]+)\s+([\d.]+)\s+([\d.]+)/);
  if (m) {
    return [
      Math.round(+m[1]! * 255),
      Math.round(+m[2]! * 255),
      Math.round(+m[3]! * 255),
    ];
  }
  return fallback;
}

// cubic-bezier(0.22, 1, 0.36, 1) solved via Newton–Raphson
function makeBezier(p1x: number, p1y: number, p2x: number, p2y: number) {
  const cx = 3 * p1x;
  const bx = 3 * (p2x - p1x) - cx;
  const ax = 1 - cx - bx;
  const cy = 3 * p1y;
  const by = 3 * (p2y - p1y) - cy;
  const ay = 1 - cy - by;
  const sampleX = (t: number) => ((ax * t + bx) * t + cx) * t;
  const sampleY = (t: number) => ((ay * t + by) * t + cy) * t;
  const slopeX = (t: number) => (3 * ax * t + 2 * bx) * t + cx;
  return (x: number) => {
    if (x <= 0) return 0;
    if (x >= 1) return 1;
    let t = x;
    for (let i = 0; i < 6; i++) {
      const s = slopeX(t);
      if (Math.abs(s) < 1e-6) break;
      t -= (sampleX(t) - x) / s;
    }
    return sampleY(Math.min(1, Math.max(0, t)));
  };
}
const glideEase = makeBezier(0.22, 1, 0.36, 1);

export function RippleUnfold({
  src,
  tileSize = 32,
  threshold = 0.12,
  refraction = 6,
  impulse = 0.35,
  className = "aspect-[16/10]",
  "aria-label": ariaLabel = "Media revealed by a ripple wave",
}: {
  /** image URL; omitted → a token-derived generative artwork is drawn */
  src?: string;
  /** target tile edge in px; cols/rows derive from container size */
  tileSize?: number;
  /** |h| a tile must see before it pops open */
  threshold?: number;
  /** max source-rect refraction offset in px per unit wave gradient */
  refraction?: number;
  /** wave height injected per cursor move after full reveal */
  impulse?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** accessible name for the reveal. Default "Media revealed by a ripple wave". */
  "aria-label"?: string;
}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const off = document.createElement("canvas");
    const octx = off.getContext("2d");
    if (!octx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    // hot-path state — locals only, the rAF loop is the sole writer
    let w = 0;
    let h = 0;
    let dpr = 1;
    let cols = 0;
    let rows = 0;
    let tw = 0;
    let th = 0;
    let total = 0;
    let hf = new Float32Array(0); // wave height
    let vf = new Float32Array(0); // wave velocity
    let stateArr = new Uint8Array(0); // 0 closed, 1 open/scheduled
    let scaleArr = new Float32Array(0); // tile spring scale
    let svelArr = new Float32Array(0); // tile spring velocity
    let openAtArr = new Float64Array(0); // timestamp the tile starts opening
    let openedCount = 0;
    let triggered = false;
    let trigCol = 0;
    let trigRow = 0;
    let maxH = 0;
    let maxV = 0;
    let pendingPointer = -1; // cell index — throttles impulses to one/frame
    let raf = 0;
    let last = 0;
    let visible = true;
    let disposed = false;
    let img: HTMLImageElement | null = null;
    let imgReady = false;

    // theme ink — derived from CSS tokens, re-derived on theme class change
    let pal: Palette = FALLBACK_DARK;
    let borderStroke = "";
    let fgFaint = "";
    let accentPrefix = "";

    const deriveColors = () => {
      const dark = document.documentElement.classList.contains("dark");
      const fb = dark ? FALLBACK_DARK : FALLBACK_LIGHT;
      const probe = document.createElement("span");
      probe.style.display = "none";
      root.appendChild(probe);
      pal = {
        background: readToken(probe, "--background", fb.background),
        foreground: readToken(probe, "--foreground", fb.foreground),
        surface: readToken(probe, "--surface", fb.surface),
        border: readToken(probe, "--border", fb.border),
        muted: readToken(probe, "--ns-muted", fb.muted),
        accent: readToken(probe, "--ns-accent", fb.accent),
      };
      probe.remove();
      borderStroke = css(pal.border, 1);
      fgFaint = css(pal.foreground, 0.05);
      accentPrefix = `rgba(${pal.accent[0]},${pal.accent[1]},${pal.accent[2]},`;
    };

    // token-derived generative artwork used when no src is provided —
    // monochrome orbital study so the demo needs no network fetch
    const paintArtwork = () => {
      const W = off.width;
      const H = off.height;
      if (W < 2 || H < 2) return;
      const o = octx;
      const m = Math.min(W, H);
      o.setTransform(1, 0, 0, 1, 0, 0);
      o.fillStyle = css(pal.surface, 1);
      o.fillRect(0, 0, W, H);

      // diagonal hatch field, lower-left
      o.strokeStyle = css(pal.foreground, 0.05);
      o.lineWidth = Math.max(1, m / 640);
      o.beginPath();
      const hatch = m * 0.022;
      for (let x = -H; x < W * 0.6; x += hatch) {
        o.moveTo(x, H);
        o.lineTo(x + H * 0.9, H * 0.1);
      }
      o.stroke();

      // concentric orbit rings
      const ocx = W * 0.63;
      const ocy = H * 0.4;
      for (let i = 0; i < 7; i++) {
        o.strokeStyle = css(pal.muted, 0.55 - i * 0.065);
        o.lineWidth = Math.max(1, m / 520);
        o.beginPath();
        o.arc(ocx, ocy, m * (0.07 + 0.075 * i), 0, Math.PI * 2);
        o.stroke();
      }
      // core disc + satellite on the third ring
      o.fillStyle = css(pal.foreground, 0.92);
      o.beginPath();
      o.arc(ocx, ocy, m * 0.048, 0, Math.PI * 2);
      o.fill();
      const orbitR = m * (0.07 + 0.075 * 3);
      o.beginPath();
      o.arc(
        ocx + Math.cos(-0.6) * orbitR,
        ocy + Math.sin(-0.6) * orbitR,
        m * 0.016,
        0,
        Math.PI * 2
      );
      o.fill();

      // instrumentation baseline + ticks
      const by = H * 0.82;
      o.strokeStyle = css(pal.muted, 0.7);
      o.lineWidth = Math.max(1, m / 640);
      o.beginPath();
      o.moveTo(W * 0.08, by);
      o.lineTo(W * 0.92, by);
      o.stroke();
      o.strokeStyle = css(pal.foreground, 0.6);
      o.beginPath();
      for (let i = 0; i <= 12; i++) {
        const tx = W * 0.08 + (W * 0.84 * i) / 12;
        o.moveTo(tx, by - m * 0.012);
        o.lineTo(tx, by + m * 0.012);
      }
      o.stroke();

      // inset frame
      o.strokeStyle = css(pal.muted, 0.3);
      o.lineWidth = Math.max(1, m / 640);
      o.strokeRect(m * 0.035, m * 0.035, W - m * 0.07, H - m * 0.07);
    };

    const paintOffscreen = () => {
      if (off.width < 2 || off.height < 2) return;
      if (imgReady && img && img.naturalWidth > 0 && img.naturalHeight > 0) {
        const sc = Math.max(
          off.width / img.naturalWidth,
          off.height / img.naturalHeight
        );
        const dw = img.naturalWidth * sc;
        const dh = img.naturalHeight * sc;
        octx.setTransform(1, 0, 0, 1, 0, 0);
        octx.fillStyle = css(pal.surface, 1);
        octx.fillRect(0, 0, off.width, off.height);
        octx.drawImage(img, (off.width - dw) / 2, (off.height - dh) / 2, dw, dh);
        return;
      }
      paintArtwork();
    };

    const revealAll = () => {
      for (let idx = 0; idx < total; idx++) {
        stateArr[idx] = 1;
        scaleArr[idx] = 1;
        svelArr[idx] = 0;
        openAtArr[idx] = -1e6; // squash long finished
      }
      openedCount = total;
    };

    const rebuildGrid = () => {
      cols = Math.max(2, Math.min(96, Math.round(w / Math.max(8, tileSize))));
      rows = Math.max(2, Math.min(96, Math.round(h / Math.max(8, tileSize))));
      tw = w / cols;
      th = h / rows;
      total = cols * rows;
      hf = new Float32Array(total);
      vf = new Float32Array(total);
      stateArr = new Uint8Array(total);
      scaleArr = new Float32Array(total);
      svelArr = new Float32Array(total);
      openAtArr = new Float64Array(total);
      openedCount = 0;
      maxH = 0;
      maxV = 0;
      pendingPointer = -1;
      // resizing mid-reveal restarts nothing: an already-triggered surface
      // settles straight to fully revealed
      if (triggered) revealAll();
    };

    const resize = () => {
      const rect = root.getBoundingClientRect();
      if (rect.width < 4 || rect.height < 4) {
        // zero-size guard — no canvas work until we have real bounds
        w = 0;
        h = 0;
        total = 0;
        return;
      }
      w = rect.width;
      h = rect.height;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
      off.width = canvas.width;
      off.height = canvas.height;
      paintOffscreen();
      rebuildGrid();
    };

    // classic discrete wave equation, Neumann edges, damping 0.985/step
    // (0.95/step once every tile has opened — nothing is visibly changing
    // by then, so the idle tail decays below EPS in under a second instead
    // of several)
    const step = () => {
      const c = cols;
      const damping = openedCount >= total ? 0.95 : 0.985;
      for (let j = 0; j < rows; j++) {
        const row = j * c;
        for (let i = 0; i < c; i++) {
          const idx = row + i;
          const hc = hf[idx]!;
          const l = i > 0 ? hf[idx - 1]! : hc;
          const r = i < c - 1 ? hf[idx + 1]! : hc;
          const u = j > 0 ? hf[idx - c]! : hc;
          const d = j < rows - 1 ? hf[idx + c]! : hc;
          vf[idx] = (vf[idx]! + ((l + r + u + d) * 0.25 - hc) * 0.5) * damping;
        }
      }
      maxH = 0;
      maxV = 0;
      for (let idx = 0; idx < total; idx++) {
        const nh = hf[idx]! + vf[idx]!;
        hf[idx] = nh;
        const ah = nh < 0 ? -nh : nh;
        const av = vf[idx]! < 0 ? -vf[idx]! : vf[idx]!;
        if (ah > maxH) maxH = ah;
        if (av > maxV) maxV = av;
      }
    };

    const openTile = (idx: number, at: number) => {
      stateArr[idx] = 1;
      scaleArr[idx] = 0.6;
      svelArr[idx] = 0;
      openAtArr[idx] = at;
      openedCount++;
    };

    // safeguard: a coarse wave can die below threshold before reaching the
    // far corners — schedule the stragglers outward from the trigger cell
    const flush = (now: number) => {
      for (let j = 0; j < rows; j++) {
        for (let i = 0; i < cols; i++) {
          const idx = j * cols + i;
          if (stateArr[idx] === 0) {
            openTile(idx, now + Math.hypot(i - trigCol, j - trigRow) * 16);
          }
        }
      }
    };

    // draw + tile springs; returns whether anything still animates
    const render = (now: number, dt: number): boolean => {
      let animating = false;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      ctx.lineWidth = 1;
      const offW = off.width;
      const offH = off.height;
      const swD = tw * dpr;
      const shD = th * dpr;
      const maxSx = Math.max(0, offW - swD);
      const maxSy = Math.max(0, offH - shD);

      for (let j = 0; j < rows; j++) {
        for (let i = 0; i < cols; i++) {
          const idx = j * cols + i;
          const x = i * tw;
          const y = j * th;
          const opened = stateArr[idx] === 1 && now >= openAtArr[idx]!;

          if (!opened) {
            if (stateArr[idx] === 1) animating = true; // scheduled, waiting
            // closed tile: faint fg lift + border hairline + accent shimmer
            ctx.fillStyle = fgFaint;
            ctx.fillRect(x + 0.5, y + 0.5, tw - 1, th - 1);
            const amp = Math.abs(hf[idx] ?? 0);
            if (amp > 0.012) {
              ctx.fillStyle =
                accentPrefix + Math.min(0.4, amp * 0.85).toFixed(3) + ")";
              ctx.fillRect(x + 0.5, y + 0.5, tw - 1, th - 1);
            }
            ctx.strokeStyle = borderStroke;
            ctx.strokeRect(x + 0.5, y + 0.5, tw - 1, th - 1);
            continue;
          }

          // open spring: k = 90 s^-2, zeta = 0.7, scale 0.6 → 1
          let s = scaleArr[idx]!;
          let sv = svelArr[idx]!;
          if (s !== 1 || sv !== 0) {
            sv += (SPRING_K * (1 - s) - SPRING_C * sv) * dt;
            s += sv * dt;
            if (Math.abs(1 - s) < 0.002 && Math.abs(sv) < 0.02) {
              s = 1;
              sv = 0;
            } else {
              animating = true;
            }
            scaleArr[idx] = s;
            svelArr[idx] = sv;
          }
          // vertical squash 35% → 0 over 320ms, glide ease
          const tq = (now - openAtArr[idx]!) / SQUASH_MS;
          let squash = 1;
          if (tq < 1) {
            squash = 0.65 + 0.35 * glideEase(Math.max(0, tq));
            animating = true;
          }

          // wet-glass refraction: source rect offset by the wave gradient
          const hc = hf[idx]!;
          const l = i > 0 ? hf[idx - 1]! : hc;
          const r = i < cols - 1 ? hf[idx + 1]! : hc;
          const u = j > 0 ? hf[idx - cols]! : hc;
          const d = j < rows - 1 ? hf[idx + cols]! : hc;
          const sx = Math.min(
            Math.max(x * dpr + (r - l) * 0.5 * refraction * dpr, 0),
            maxSx
          );
          const sy = Math.min(
            Math.max(y * dpr + (d - u) * 0.5 * refraction * dpr, 0),
            maxSy
          );

          if (s === 1 && squash === 1) {
            ctx.drawImage(off, sx, sy, swD, shD, x, y, tw, th);
          } else {
            ctx.save();
            ctx.translate(x + tw / 2, y + th / 2);
            ctx.scale(s, s * squash);
            ctx.drawImage(off, sx, sy, swD, shD, -tw / 2, -th / 2, tw, th);
            ctx.restore();
          }
        }
      }
      return animating;
    };

    const loop = (now: number) => {
      raf = 0;
      if (disposed || w === 0 || total === 0) return;
      const dt = Math.min(Math.max((now - last) / 1000, 0), DT_MAX);
      last = now;
      let animating = false;

      if (triggered) {
        if (pendingPointer >= 0 && pendingPointer < total) {
          hf[pendingPointer] = Math.min(1.5, hf[pendingPointer]! + impulse);
          pendingPointer = -1;
        }
        step();
        step();
        if (maxH > EPS || maxV > EPS) {
          animating = true;
        } else if (maxH > 0 || maxV > 0) {
          // settle hard so refraction offsets are exactly zero at rest
          hf.fill(0);
          vf.fill(0);
          maxH = 0;
          maxV = 0;
        }
        if (openedCount < total) {
          for (let idx = 0; idx < total; idx++) {
            if (stateArr[idx] === 0 && Math.abs(hf[idx]!) > threshold) {
              openTile(idx, now);
            }
          }
          if (openedCount < total && maxH < threshold * 0.5) flush(now);
          animating = true;
        }
      }

      if (render(now, dt)) animating = true;
      if (animating && visible) raf = requestAnimationFrame(loop);
    };

    const wake = () => {
      if (raf === 0 && visible && !disposed && w > 0) {
        last = performance.now();
        raf = requestAnimationFrame(loop);
      }
    };

    const drawOnce = () => {
      if (w > 0 && total > 0) render(performance.now(), 0);
    };

    const repaint = () => {
      if (reduced) drawOnce();
      else wake();
    };

    const trigger = (ci: number, ri: number) => {
      if (triggered || disposed) return;
      triggered = true;
      if (total === 0) return; // grid rebuild reveals on next real size
      if (reduced) {
        // reduced motion: single instant paint, zero wave distortion
        revealAll();
        drawOnce();
        return;
      }
      trigCol = Math.min(Math.max(ci, 0), cols - 1);
      trigRow = Math.min(Math.max(ri, 0), rows - 1);
      hf[trigRow * cols + trigCol] = 1;
      maxH = 1;
      wake();
    };

    const cellAt = (e: PointerEvent): [number, number] | null => {
      if (total === 0) return null;
      const rect = root.getBoundingClientRect();
      if (rect.width < 1 || rect.height < 1) return null;
      const ci = Math.min(
        Math.max(Math.floor(((e.clientX - rect.left) / rect.width) * cols), 0),
        cols - 1
      );
      const ri = Math.min(
        Math.max(Math.floor(((e.clientY - rect.top) / rect.height) * rows), 0),
        rows - 1
      );
      return [ci, ri];
    };

    const onPointer = (e: PointerEvent) => {
      if (!triggered) {
        const c = cellAt(e);
        trigger(c ? c[0] : cols >> 1, c ? c[1] : rows >> 1);
        return;
      }
      // cursor keeps perturbing the water only after full reveal;
      // pendingPointer throttles injection to one impulse per frame
      if (reduced || openedCount < total || total === 0) return;
      const c = cellAt(e);
      if (!c) return;
      pendingPointer = c[1] * cols + c[0];
      wake();
    };

    deriveColors();
    resize();
    repaint();

    // scroll trigger at 0.35 visibility + offscreen pause
    const io = new IntersectionObserver(
      (entries) => {
        for (const e of entries) {
          visible = e.isIntersecting;
          if (!triggered && e.intersectionRatio >= 0.35) {
            trigger(cols >> 1, rows >> 1);
          }
        }
        if (visible) {
          if (!reduced) wake();
        } else if (raf) {
          cancelAnimationFrame(raf);
          raf = 0;
        }
      },
      { threshold: [0, 0.35] }
    );
    io.observe(root);

    const ro = new ResizeObserver((entries) => {
      const e = entries[0];
      if (!e) return;
      if (
        Math.abs(e.contentRect.width - w) < 1 &&
        Math.abs(e.contentRect.height - h) < 1
      ) {
        return;
      }
      resize();
      repaint();
    });
    ro.observe(root);

    // live theme re-derive: watch documentElement class changes
    const mo = new MutationObserver(() => {
      deriveColors();
      if (!imgReady) paintOffscreen(); // artwork ink is token-derived
      repaint();
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    root.addEventListener("pointerenter", onPointer);
    root.addEventListener("pointermove", onPointer);
    root.addEventListener("pointerdown", onPointer);

    if (src) {
      img = new Image();
      img.decoding = "async";
      img.onload = () => {
        if (disposed) return;
        imgReady = true;
        paintOffscreen();
        repaint();
      };
      img.onerror = () => {
        // keep the generative artwork — never a blank surface
        imgReady = false;
      };
      img.src = src;
    }

    return () => {
      disposed = true;
      if (raf) cancelAnimationFrame(raf);
      raf = 0;
      io.disconnect();
      ro.disconnect();
      mo.disconnect();
      root.removeEventListener("pointerenter", onPointer);
      root.removeEventListener("pointermove", onPointer);
      root.removeEventListener("pointerdown", onPointer);
      if (img) {
        img.onload = null;
        img.onerror = null;
      }
    };
  }, [src, tileSize, threshold, refraction, impulse]);

  return (
    <div
      ref={rootRef}
      role="img"
      aria-label={ariaLabel}
      className={`relative w-full select-none overflow-hidden ${className}`}
    >
      <canvas
        ref={canvasRef}
        aria-hidden
        className="absolute inset-0 h-full w-full"
      />
    </div>
  );
}

"use client";

// ---------------------------------------------------------------------------
// RingStain — a loader built on the coffee-ring effect. 90 small SVG
// particles drift outward from the center on a capillary-flow velocity
// profile (slow near the middle, sharply accelerating near the rim, the same
// shape as the outward flux that pins coffee grounds to a drying drop's
// contact line) plus a little Brownian jitter for organic texture. A
// particle that reaches the rim while its angle is "eligible" freezes there
// and brightens from --ns-muted to --foreground; an ineligible arrival just
// respawns near the center with a fresh angle. Nothing ever un-freezes and
// nothing rotates — nothing here is a cycle, the deposit is a residue.
//
// Two independent readings of "eligible":
//   determinate  (value 0-100)  -> a contiguous rim ARC, its width the
//                                   percent, so coverage angle reads as
//                                   progress.
//   indeterminate (value omitted) -> every angle is eligible, but the total
//                                   allowed to freeze is capped by an
//                                   asymptotic function of elapsed time, so
//                                   DENSITY alone encodes how long the wait
//                                   has run.
//
// On completion (value reaches 100, or the `complete` prop is set — the
// escape hatch for an indeterminate wait that resolves without ever having
// had a percent) the still-drifting interior particles fade out and the
// deposited rim particles ease, on a spring, onto sampled points along a
// checkmark path — the residue itself rearranges into the check, rather
// than being swapped for a separate glyph — while a thin stroke of the same
// path draws in underneath them for legibility when few particles deposited.
//
// prefers-reduced-motion drops the whole drift simulation: the same 90
// circles are pinned at fixed, evenly spaced rim slots from the first frame
// and never move again — only their opacity/fill step between "empty" and
// "deposited" at a coarse interval, in a fixed pseudo-random (golden-ratio)
// order so the reveal doesn't read as a mechanical wipe. Accumulation
// without motion.
//
// Pure DOM + SVG + CSS. Every stroke/fill is a `var(--token)` presentation
// attribute or a CSS class rule (CSS wins the cascade over the presentation
// attribute), so a theme flip needs no getComputedStyle and no rAF re-read.
// ---------------------------------------------------------------------------

import { useEffect, useId, useRef, useState } from "react";

export interface RingStainProps {
  /** progress 0-100. Omit for indeterminate (density-over-time). */
  value?: number;
  /** force the completion sequence even with no value (e.g. an
   * indeterminate wait that just resolved). Also true automatically once
   * `value` reaches 100. */
  complete?: boolean;
  /** glyph size in px (square). */
  size?: number;
  /** accessible name for the progressbar region. */
  label?: string;
  className?: string;
}

const COUNT = 90; // particles, within the 60-120 range
const RIM = 36; // rim radius, local units (the <g> is translated to center)
const CLIP_R = 44;
const SPAWN_R_MAX = 2.2;
const V_BASE = 5; // units/sec at r = 0
const V_RIM = 46; // units/sec approaching the rim (capillary acceleration)
const CAPILLARY_POWER = 2.6;
const JITTER_THETA = 0.9; // rad/sec-scale Brownian wobble
const JITTER_R = 3; // units/sec-scale Brownian wobble
const INDETERMINATE_TAU = 9; // seconds — density approaches full, never quite arrives
const ARC_START = -Math.PI / 2; // 12 o'clock
const TWO_PI = Math.PI * 2;
const STATUS_INTERVAL_MS = 1500; // aria-live text refresh cadence — coarse, not per-frame
const REDUCED_TICK_MS = 800; // reduced-motion stepwise fill cadence
const GOLDEN = 0.6180339887498949;
const CHECK_PATH = "M -18 2 L -6 15 L 20 -16";

interface Particle {
  r: number;
  theta: number;
  frozen: boolean;
  speedMul: number;
}

// deterministic per-index radius (0.5 - 1.5), a low-discrepancy sequence so
// dot sizes look organically varied without Math.random touching render.
// Floor on how many particles form the finished checkmark — see the completion
// effect. Enough to read as a dotted glyph rather than a few specks.
const MIN_RESIDUE = 34;
// Radii in local units against the 100-unit viewBox. Widened from 0.5..1.5:
// at the demo's 104-160px render that produced ~1.5-3px dots that all but
// vanished, and disappeared entirely on a scaled-down catalog card.
const RADII: number[] = Array.from({ length: COUNT }, (_, i) => 0.9 + ((i * GOLDEN + 0.5) % 1) * 1.6);

// deterministic fixed rim-slot angles for prefers-reduced-motion.
const SLOT_ANGLES: number[] = Array.from({ length: COUNT }, (_, i) => (i / COUNT) * TWO_PI);

// deterministic fill order for reduced-motion indeterminate density steps —
// a golden-ratio permutation so the reveal scatters rather than sweeps.
const FILL_ORDER: number[] = Array.from({ length: COUNT }, (_, i) => i).sort(
  (a, b) => ((a * GOLDEN) % 1) - ((b * GOLDEN) % 1),
);

function clamp01(n: number): number {
  return Math.min(1, Math.max(0, n));
}

function densityCap(elapsedSec: number): number {
  return 1 - Math.exp(-elapsedSec / INDETERMINATE_TAU);
}

function withinArc(theta: number, fraction: number): boolean {
  const norm = (((theta - ARC_START) % TWO_PI) + TWO_PI) % TWO_PI;
  return norm < fraction * TWO_PI;
}

const CSS = `
.ns-rs-dot{transition:fill 220ms ease, opacity 220ms ease;}
.ns-rs-dot.ns-rs-deposit{fill:var(--foreground);}
.ns-rs-check{transition:stroke-dashoffset 420ms cubic-bezier(.34,1.56,.64,1) 90ms;}
@media (prefers-reduced-motion: reduce){
  .ns-rs-dot{transition:opacity 180ms ease;}
  .ns-rs-check{transition:none;}
}
`;

export function RingStain({
  value,
  complete,
  size = 120,
  label = "Loading",
  className = "",
}: RingStainProps) {
  const clipId = useId();
  const svgId = useId();

  const clampedValue = typeof value === "number" && !Number.isNaN(value) ? clamp01(value / 100) * 100 : undefined;
  const indeterminate = clampedValue === undefined;

  const [reducedMotion, setReducedMotion] = useState(false);
  const [settled, setSettled] = useState(false);
  const [statusText, setStatusText] = useState("");
  const [resetCycle, setResetCycle] = useState(0);

  const elsRef = useRef<(SVGCircleElement | null)[]>([]);
  const checkPathRef = useRef<SVGPathElement | null>(null);
  const particlesRef = useRef<Particle[]>([]);
  const depositedRef = useRef<Set<number>>(new Set());
  const frozenCountRef = useRef(0);

  const valueRef = useRef(clampedValue);
  const settledRef = useRef(false);
  const reducedMotionRef = useRef(false);
  useEffect(() => {
    valueRef.current = clampedValue;
  }, [clampedValue]);
  useEffect(() => {
    settledRef.current = settled;
  }, [settled]);
  useEffect(() => {
    reducedMotionRef.current = reducedMotion;
  }, [reducedMotion]);

  // watch the reduced-motion query, live.
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReducedMotion(mq.matches);
    const onChange = () => setReducedMotion(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  // completion detection: value hitting 100, or the explicit `complete`
  // prop. Falling back out of completion (a reused loader starting a new
  // wait) bumps resetCycle so the particle field starts fresh.
  const prevSettledRef = useRef(false);
  useEffect(() => {
    const isComplete = complete === true || (clampedValue !== undefined && clampedValue >= 100);
    if (isComplete && !prevSettledRef.current) {
      prevSettledRef.current = true;
      setSettled(true);
    } else if (!isComplete && prevSettledRef.current) {
      prevSettledRef.current = false;
      setSettled(false);
      setResetCycle((k) => k + 1);
    }
  }, [complete, clampedValue]);

  // the particle simulation (or its reduced-motion stand-in). Restarts only
  // on mount, a reduced-motion flip, or an explicit new cycle — never on a
  // mere value tick, which would otherwise look like the ring restarting.
  useEffect(() => {
    const els = elsRef.current;
    const reduced = reducedMotionRef.current;

    const particles: Particle[] = Array.from({ length: COUNT }, (_, i) =>
      reduced
        ? { r: RIM, theta: SLOT_ANGLES[i], frozen: false, speedMul: 1 }
        : {
            r: Math.random() * SPAWN_R_MAX,
            theta: Math.random() * TWO_PI,
            frozen: false,
            speedMul: 0.75 + Math.random() * 0.6,
          },
    );
    particlesRef.current = particles;
    depositedRef.current = new Set();
    frozenCountRef.current = 0;

    for (let i = 0; i < COUNT; i++) {
      const el = els[i];
      if (!el) continue;
      el.classList.remove("ns-rs-deposit");
      el.style.transition = "none";
      el.style.opacity = "1";
      const p = particles[i];
      el.style.transform = `translate(${(p.r * Math.cos(p.theta)).toFixed(2)}px, ${(p.r * Math.sin(p.theta)).toFixed(2)}px)`;
    }
    const check = checkPathRef.current;
    if (check) {
      check.style.transition = "none";
      check.style.strokeDashoffset = "1";
    }
    // one reflow, then hand transform/transition back to normal control.
    void els[0]?.getBoundingClientRect();
    for (let i = 0; i < COUNT; i++) {
      const el = els[i];
      if (el) el.style.transition = "";
    }
    if (check) check.style.transition = "";

    const startedAt = performance.now();

    if (reduced) {
      const tick = () => {
        if (settledRef.current) return;
        const elapsed = (performance.now() - startedAt) / 1000;
        const v = valueRef.current;
        let filled: Set<number>;
        if (v !== undefined) {
          const frac = clamp01(v / 100);
          filled = new Set();
          for (let i = 0; i < COUNT; i++) {
            if (withinArc(particles[i].theta, frac)) filled.add(i);
          }
        } else {
          const cap = Math.round(densityCap(elapsed) * COUNT);
          filled = new Set(FILL_ORDER.slice(0, cap));
        }
        depositedRef.current = filled;
        frozenCountRef.current = filled.size;
        for (let i = 0; i < COUNT; i++) {
          const el = els[i];
          if (el) el.classList.toggle("ns-rs-deposit", filled.has(i));
        }
      };
      tick();
      const id = window.setInterval(tick, REDUCED_TICK_MS);
      return () => window.clearInterval(id);
    }

    let raf = 0;
    let last = performance.now();
    const loop = (now: number) => {
      if (settledRef.current) {
        raf = 0;
        return;
      }
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;
      const elapsed = (now - startedAt) / 1000;
      const v = valueRef.current;
      const frac = v !== undefined ? clamp01(v / 100) : 0;

      for (let i = 0; i < COUNT; i++) {
        const p = particles[i];
        const el = els[i];
        if (p.frozen || !el) continue;

        const speed = V_BASE + (V_RIM - V_BASE) * Math.pow(Math.min(1, p.r / RIM), CAPILLARY_POWER);
        p.r += speed * p.speedMul * dt;
        p.theta += (Math.random() - 0.5) * JITTER_THETA * dt;
        p.r += (Math.random() - 0.5) * JITTER_R * dt;
        if (p.r < 0) p.r = 0;

        if (p.r >= RIM) {
          const eligible = v !== undefined ? withinArc(p.theta, frac) : frozenCountRef.current < densityCap(elapsed) * COUNT;
          if (eligible) {
            p.frozen = true;
            p.r = RIM;
            frozenCountRef.current += 1;
            depositedRef.current.add(i);
            el.style.transform = `translate(${(RIM * Math.cos(p.theta)).toFixed(2)}px, ${(RIM * Math.sin(p.theta)).toFixed(2)}px)`;
            el.classList.add("ns-rs-deposit");
            continue;
          }
          p.r = Math.random() * SPAWN_R_MAX;
          p.theta = Math.random() * TWO_PI;
          p.speedMul = 0.75 + Math.random() * 0.6;
        }
        el.style.transform = `translate(${(p.r * Math.cos(p.theta)).toFixed(2)}px, ${(p.r * Math.sin(p.theta)).toFixed(2)}px)`;
      }
      raf = requestAnimationFrame(loop);
    };
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, [resetCycle, reducedMotion]);

  // completion: fade the interior, ease every deposited particle onto a
  // sampled point along the checkmark path, draw the underlying stroke.
  useEffect(() => {
    if (!settled) return;
    const els = elsRef.current;
    const check = checkPathRef.current;
    const deposited = Array.from(depositedRef.current);
    const total = check ? check.getTotalLength() : 0;
    const reduced = reducedMotionRef.current;

    // The residue IS the checkmark, so there has to be some. Completing with an
    // empty deposit set used to hide all COUNT particles and leave a bare
    // stroke: mounting already-complete (or firing `complete` during an early
    // indeterminate wait) never gives the rim time to collect anything, so the
    // panel rendered as an empty circle — measured deposited:0, 90 particles at
    // opacity:0. Recruit particles up to a floor so the glyph always reads as
    // settled residue, and mark the recruits deposited so they take the same
    // --foreground fill rather than staying muted.
    const residue = deposited.slice();
    for (let i = 0; i < COUNT && residue.length < MIN_RESIDUE; i++) {
      if (depositedRef.current.has(i)) continue;
      depositedRef.current.add(i);
      els[i]?.classList.add("ns-rs-deposit");
      residue.push(i);
    }

    residue.forEach((idx, j) => {
      const el = els[idx];
      if (!el || !check) return;
      const frac = residue.length > 1 ? j / (residue.length - 1) : 0.5;
      const pt = check.getPointAtLength(frac * total);
      el.style.transition = reduced ? "none" : "transform 460ms cubic-bezier(.34,1.56,.64,1)";
      el.style.transform = `translate(${pt.x.toFixed(2)}px, ${pt.y.toFixed(2)}px)`;
    });

    const onCheck = new Set(residue);
    for (let i = 0; i < COUNT; i++) {
      if (onCheck.has(i)) continue;
      const el = els[i];
      if (!el) continue;
      el.style.transition = reduced ? "none" : "opacity 200ms ease";
      el.style.opacity = "0";
    }

    if (check) check.style.strokeDashoffset = "0";
  }, [settled]);

  // visually hidden status line, refreshed at a coarse interval — never
  // per-frame.
  useEffect(() => {
    const compute = () => {
      if (settled) return `${label} complete.`;
      if (clampedValue !== undefined) return `${label}, ${Math.round(clampedValue)} percent.`;
      const pct = Math.round((depositedRef.current.size / COUNT) * 100);
      return `${label}, ring ${pct} percent filled.`;
    };
    setStatusText(compute());
    if (settled) return;
    const id = window.setInterval(() => setStatusText(compute()), STATUS_INTERVAL_MS);
    return () => window.clearInterval(id);
  }, [clampedValue, label, settled]);

  const displayPct = indeterminate ? undefined : settled ? 100 : Math.round(clampedValue as number);

  return (
    <div className={`inline-flex flex-col items-center gap-2 ${className}`} data-ring-stain>
      <style>{CSS}</style>
      <div
        role="progressbar"
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={indeterminate ? undefined : displayPct}
        aria-busy={indeterminate && !settled}
        style={{ width: size, height: size }}
        className="relative shrink-0"
      >
        <svg
          id={svgId}
          viewBox="0 0 100 100"
          width={size}
          height={size}
          aria-hidden="true"
          focusable="false"
        >
          <defs>
            {/*
              userSpaceOnUse (the default) resolves this circle in the user
              space of the element that REFERENCES the clip — i.e. the <g>
              below, AFTER its own translate(50 50). Authoring it at (50,50)
              therefore put the clip at viewBox (100,100) and clipped every
              particle and the checkmark away, leaving a bare crescent of the
              rim. The clip is centred on the same origin as its contents: 0,0.
            */}
            <clipPath id={clipId}>
              <circle cx={0} cy={0} r={CLIP_R} />
            </clipPath>
          </defs>
          <g transform="translate(50 50)" clipPath={`url(#${clipId})`}>
            <circle r={RIM} fill="none" stroke="var(--border)" strokeWidth={1.4} />
            {Array.from({ length: COUNT }).map((_, i) => (
              <circle
                key={i}
                ref={(el) => {
                  elsRef.current[i] = el;
                }}
                className="ns-rs-dot"
                r={RADII[i]}
                cx={0}
                cy={0}
                fill="var(--ns-muted)"
              />
            ))}
            <path
              ref={checkPathRef}
              className="ns-rs-check"
              d={CHECK_PATH}
              pathLength={1}
              fill="none"
              stroke="var(--foreground)"
              strokeWidth={2.5}
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeDasharray="1 1"
              style={{ strokeDashoffset: 1 }}
            />
          </g>
        </svg>
      </div>
      <span role="status" aria-live="polite" className="sr-only">
        {statusText}
      </span>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import type { CSSProperties } from "react";

// ---------------------------------------------------------------------------
// RisoDrumPass — a loader / background ambient texture reproducing a
// risograph duplication run, not a generic dot grid. A riso duplicator
// forces ink from inside a perforated cylindrical drum, wrapped in a
// stencil master, out through the stencil's micro-perforations onto paper
// as the drum makes ONE full rotation per printed sheet. Multi-colour riso
// work is never printed in one pass — it is run as SEQUENTIAL separate
// drum passes, one physical drum per colour, fed back through by hand or a
// colour-change unit — and every pass after the first mis-registers by a
// few pixels against the one before it purely from paper-feed tolerance,
// plus every pass shows faint concentric banding from uneven drum surface
// pressure across that one rotation. This is a single-screen, single-drum
// mechanic (card-dot-gain-screen) reproducing tonal dot-gain, and a
// two-screen static moiré mechanic (background-halftone-rosette)
// reproducing plate registration ANGLE drift; this component's identity is
// neither — it is three SEQUENTIAL, TIME-ORDERED sweeps of the SAME
// stencil dot field, each drawn as a live top-to-bottom rotation, offset a
// few pixels from the shared field so the drift reads as doubled edges and
// moiré between passes, never as three unrelated random layers.
//
// Per cycle: three passes, 2s each (drum rotation: 1.4s sweep + 0.6s pause
// for the drum swap, budgeted inside that same 2s slot) = 6s total. Pass
// index k (0,1,2) shares ONE value-noise stencil field for the whole cycle
// (so the same dots are common to all three passes — the actual mechanic a
// riso mis-registers) but nudges its own open/closed threshold by a small
// per-pass delta, standing in for that colour's own stencil-cutting
// tolerance, and reads its dots at a cumulative registration offset of
// (k*1.3px, k*0.7px) off the shared grid — the same sheet drifting further
// through each successive nip, not three independent misalignments. The
// whole stencil field is reseeded fresh every lap of the loop, so no two
// cycles print an identical sheet.
//
// Drum pressure banding: a dot's alpha is modulated by a sinusoid tied to
// the rotation angle at which its row was printed (row / totalRows
// standing in for angle-around-the-drum, amplitude 0.08), phase-shifted a
// third of a turn per pass index so the three passes' bands beat against
// each other rather than stacking as one static gradient. Baked in
// permanently at the moment that row is swept, because on a real press
// that row's ink density was fixed the instant the drum's high-pressure
// arc passed over it, not something that re-modulates after printing.
//
// Overlap: three passes at nominal alpha 0.55 compositing normally (as
// separate real ink layers do) would union to ~0.91 opacity where all
// three land on the same shared dot — past what the spec caps as visually
// "still separate layers of ink" rather than solid plugged fill. Per cell,
// each pass's alpha is therefore reduced ONLY when it would push the
// running Porter-Duff union past 0.82: alpha_k = min(banded, (0.82 -
// prior) / (1 - prior)). The first two passes on any shared cell almost
// always keep their full alpha; only a genuine triple-overlap cell gets
// its third layer thinned.
// ---------------------------------------------------------------------------

export interface RisoDrumPassProps {
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** inline styles merged onto the root element */
  style?: CSSProperties;
}

type RGB = [number, number, number];

function parseColor(raw: string): RGB | null {
  const s = raw.trim();
  if (s.startsWith("#")) {
    let hex = s.slice(1);
    if (hex.length === 3) hex = hex.split("").map((c) => c + c).join("");
    if (hex.length < 6) return null;
    const r = parseInt(hex.slice(0, 2), 16);
    const g = parseInt(hex.slice(2, 4), 16);
    const b = parseInt(hex.slice(4, 6), 16);
    return Number.isNaN(r + g + b) ? null : [r, g, b];
  }
  const m = s.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
}

// deterministic per-cell hash — the ONE shared stencil field a cycle's
// three passes all read from (see module doc: shared field is what makes
// the registration offset between passes actually visible).
function hash01(x: number, y: number): number {
  const n = Math.sin(x * 127.1 + y * 311.7) * 43758.5453123;
  return n - Math.floor(n);
}

// each 2s pass slot budgets a 1.4s live rotation sweep + a 0.6s drum-swap
// pause, so three slots total exactly 6s with no gap or invented rest.
const SWEEP_MS = 1400;
const PAUSE_MS = 600;
const PASS_SLOT_MS = SWEEP_MS + PAUSE_MS; // 2000ms
const CYCLE_MS = PASS_SLOT_MS * 3; // 6000ms, 3 passes, no trailing rest
const PASS_COUNT = 3;

const REG_OFFSET_X = 1.3; // px, cumulative per pass index
const REG_OFFSET_Y = 0.7;
const BAND_AMPLITUDE = 0.08; // pressure-banding alpha modulation
const PASS_ALPHA = 0.55;
const ALPHA_CAP = 0.82; // hard union cap where all three passes overlap
const DOT_THRESHOLD = 0.5; // shared stencil cutoff — roughly half the field open
const THRESHOLD_DELTA = 0.04; // per-pass cutting tolerance around the shared threshold

// spec's explicit freeze time: passes 1 and 2 fully complete (their sweeps
// end at 3400ms), pass 3 already sweeping (its sweep starts at 4000ms) —
// the most structurally dense, most legibly drifted static frame short of
// waiting for the whole cycle to finish.
const STATIC_TIME_MS = 4200;

function passStart(k: number): number {
  return k * PASS_SLOT_MS;
}

/** sweep progress of pass k in [0,1] at cycleTime; 0 before its sweep
 * starts, 1 once its sweep is done (through its own pause and beyond). */
function passProgress(k: number, cycleTime: number): number {
  const start = passStart(k);
  if (cycleTime <= start) return 0;
  return Math.min(1, (cycleTime - start) / SWEEP_MS);
}

export function RisoDrumPass({ className = "", style }: RisoDrumPassProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    let reduced = mq.matches;

    // -- token-derived ink: read at mount, re-derived on theme class change --
    let fg: RGB = [0, 0, 0];
    const derive = () => {
      const cs = getComputedStyle(document.documentElement);
      fg = parseColor(cs.getPropertyValue("--foreground")) ?? fg;
    };
    derive();

    let w = 0;
    let h = 0;
    let dpr = 1;
    let pitch = 6;
    let cols = 0;
    let rows = 0;
    let raf = 0;
    let visible = true;
    let cycleBase = 0; // performance.now() at the start of the current cycle
    let cycleIndex = 0; // increments once per lap — reseeds the shared stencil

    // -- draw the sheet as it stands at `cycleTime` (ms since this cycle's
    // stencil was cut). Every cell is visited once; each of the three
    // passes that has swept past that cell's row reads the SAME shared
    // dot field (nudged by its own threshold delta) at its own cumulative
    // registration offset, alpha-capped per cell via a running union. -----
    const draw = (cycleTime: number) => {
      if (w <= 0 || h <= 0 || cols <= 0 || rows <= 0) return;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      ctx.fillStyle = `rgb(${fg[0]},${fg[1]},${fg[2]})`;

      const seed = cycleIndex * 997.13;
      const radius = pitch * 0.4;

      // per-pass sweep front row (fractional) and whether the pass has
      // started at all this cycleTime, precomputed once per frame
      const fronts: number[] = [];
      const started: boolean[] = [];
      for (let k = 0; k < PASS_COUNT; k++) {
        const p = passProgress(k, cycleTime);
        started.push(cycleTime > passStart(k));
        fronts.push(p * rows);
      }

      for (let j = 0; j < rows; j++) {
        const rotationFrac = rows > 1 ? j / (rows - 1) : 0;
        for (let i = 0; i < cols; i++) {
          const n = hash01(i * 0.37 + seed, j * 0.41 + seed); // ONE shared field
          let prior = 0; // running combined alpha for this cell this frame
          for (let k = 0; k < PASS_COUNT; k++) {
            if (!started[k]) break; // later passes never precede earlier ones
            const front = fronts[k] ?? 0;
            if (j > front) continue; // this pass hasn't swept this row yet

            // shared stencil, nudged by this colour's own cutting tolerance
            const threshold = DOT_THRESHOLD + (k - 1) * THRESHOLD_DELTA;
            if (n < threshold) continue;

            // pressure banding baked in at the rotation angle this row
            // printed at, phased a third of a turn apart per pass
            const phase = 2 * Math.PI * rotationFrac + (k * 2 * Math.PI) / 3;
            const band = 1 + BAND_AMPLITUDE * Math.sin(phase);
            let alpha = PASS_ALPHA * band;

            // cap the running union at ALPHA_CAP, thinning only the layer
            // that would actually push the cell past it
            const room = (ALPHA_CAP - prior) / Math.max(0.0001, 1 - prior);
            alpha = Math.max(0, Math.min(alpha, room));
            if (alpha <= 0.004) continue;
            prior = prior + alpha * (1 - prior);

            const cx = (i + 0.5) * pitch + k * REG_OFFSET_X;
            const cy = (j + 0.5) * pitch + k * REG_OFFSET_Y;

            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.arc(cx, cy, radius, 0, Math.PI * 2);
            ctx.fill();
          }
        }
      }
      ctx.globalAlpha = 1;

      // faint sweep-front nip line for the pass currently in motion —
      // luminance only, no accent, a soft foreground band at the drum's
      // current contact row
      for (let k = 0; k < PASS_COUNT; k++) {
        const p = passProgress(k, cycleTime);
        if (p > 0 && p < 1) {
          const y = (fronts[k] ?? 0) * pitch;
          const grad = ctx.createLinearGradient(0, y - pitch * 2, 0, y + pitch * 2);
          grad.addColorStop(0, `rgba(${fg[0]},${fg[1]},${fg[2]},0)`);
          grad.addColorStop(0.5, `rgba(${fg[0]},${fg[1]},${fg[2]},0.05)`);
          grad.addColorStop(1, `rgba(${fg[0]},${fg[1]},${fg[2]},0)`);
          ctx.fillStyle = grad;
          ctx.fillRect(0, y - pitch * 2, w, pitch * 4);
        }
      }
    };

    const loop = (now: number) => {
      let cycleTime = now - cycleBase;
      if (cycleTime >= CYCLE_MS) {
        const laps = Math.floor(cycleTime / CYCLE_MS);
        cycleBase += laps * CYCLE_MS;
        cycleIndex += laps;
        cycleTime = now - cycleBase;
      }
      draw(cycleTime);
      if (!reduced && visible) raf = requestAnimationFrame(loop);
      else raf = 0;
    };
    const wake = () => {
      if (raf === 0 && !reduced && visible) raf = requestAnimationFrame(loop);
    };

    const resize = () => {
      const rect = root.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
      // stencil pitch derived from the container's own smaller dimension so
      // the drum screen reads at card scale rather than coarsening or vanishing
      pitch = Math.min(10, Math.max(5, Math.min(w, h) / 40));
      cols = Math.ceil(w / pitch) + 1;
      rows = Math.ceil(h / pitch) + 1;
      if (reduced) {
        draw(STATIC_TIME_MS);
      } else {
        draw(Math.max(0, performance.now() - cycleBase));
      }
    };

    cycleBase = performance.now();
    resize();
    if (!reduced) wake();

    const ro = new ResizeObserver(resize);
    ro.observe(root);

    const mo = new MutationObserver(() => {
      derive();
      draw(reduced ? STATIC_TIME_MS : Math.max(0, performance.now() - cycleBase));
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    const onReducedChange = () => {
      reduced = mq.matches;
      if (reduced) {
        cancelAnimationFrame(raf);
        raf = 0;
        draw(STATIC_TIME_MS);
      } else {
        cycleBase = performance.now();
        cycleIndex = 0;
        wake();
      }
    };
    mq.addEventListener("change", onReducedChange);

    const onVisibility = () => {
      visible = document.visibilityState === "visible";
      if (visible) {
        wake();
      } else {
        cancelAnimationFrame(raf);
        raf = 0;
      }
    };
    document.addEventListener("visibilitychange", onVisibility);

    const io = new IntersectionObserver((entries) => {
      const intersecting = entries[0]?.isIntersecting ?? true;
      visible = intersecting && document.visibilityState === "visible";
      if (visible) wake();
      else {
        cancelAnimationFrame(raf);
        raf = 0;
      }
    });
    io.observe(root);

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      mo.disconnect();
      io.disconnect();
      mq.removeEventListener("change", onReducedChange);
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, []);

  return (
    <div
      ref={rootRef}
      className={`ns-rdp relative h-full w-full overflow-hidden bg-background ${className}`}
      style={style}
    >
      <canvas ref={canvasRef} aria-hidden="true" className="pointer-events-none absolute inset-0 h-full w-full" />
    </div>
  );
}

RisoDrumPass.displayName = "RisoDrumPass";

export default RisoDrumPass;

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// RollerBreakReduce — an ambient multi-stage pipeline indicator built as a
// flour mill's break system: grain passes through a sequence of paired
// corrugated rollers (B1..B4), each pair spinning at a 2.5:1 differential
// (fast roll over slow roll) so the nip SHEARS the stock rather than
// crushing it. Every stage narrows the roll gap; every pass through a nip
// reduces particle size by ~35% and is drawn as a 150ms compression, never
// an instant swap. This is a continuous ambient stream (no query, no
// gravity/mesh threshold) — distinct from a sieve's pass/fail aperture gate.
//
// Rollers are plain DOM + CSS transform (fixed geometry, cheap to rotate);
// the particle stream is a single 2D canvas overlay. Stage count and roller
// diameter derive from the container's smaller dimension so the mechanism
// still reads at card scale. Colours used on the canvas are read once via
// getComputedStyle on the documentElement and re-read on a MutationObserver
// watching its class — no canvas paint happens before that first read. DOM
// roller/hairline colour comes straight from CSS var() tokens.
// ---------------------------------------------------------------------------

export interface RollerBreakReduceProps {
  /** Highlights one stage's corrugation via a luminance boost (never accent). */
  activeStage?: number;
  className?: string;
}

const FEED_RATE = 3; // particles / second entering at the left edge
const BASE_DIAM_MIN = 8; // px, coarse entry particle
const BASE_DIAM_MAX = 10;
const REDUCTION = 0.65; // ~35% size loss per break stage
const SEG_MS = 900; // inter-stage travel time
const NIP_MS = 150; // compression window at each nip crossing
const POP_CAP = 35; // steady-state on-screen ceiling (spec: 25-35)
const SLOW_REV_S = 0.6; // slow roll rev/s
const FAST_REV_S = 1.5; // fast roll rev/s (2.5:1 differential, matches the real ratio)
const RIDGE_COUNT = 60; // corrugation ridges per roller rim (fine pitch)

interface Particle {
  id: number;
  segIndex: number; // which travel segment [0 .. stageCount] the particle is in
  segStart: number; // ms timestamp the current segment began
  yOffset: number; // px scatter around the nip centreline while travelling
  baseDiameter: number; // px, at spawn (before any break stage)
}

interface Layout {
  w: number;
  h: number;
  stageCount: number;
  rollerDiameter: number;
  nipGaps: number[]; // px, one per stage — narrows stage to stage
  boundaryX: number[]; // [0, nip0, nip1, ..., width], length stageCount + 2
  centerY: number;
  jitterAmp: number;
}

function lerp(a: number, b: number, t: number) {
  return a + (b - a) * t;
}
function clamp01(t: number) {
  return t < 0 ? 0 : t > 1 ? 1 : t;
}
function easeInOutCubic(t: number) {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
}

function computeLayout(w: number, h: number): Layout {
  const minDim = Math.min(w, h);
  const stageCount = minDim < 280 ? 3 : 4;
  const rollerDiameter = minDim * 0.14;
  const marginX = w * 0.08;
  const usableW = Math.max(1, w - marginX * 2);
  const boundaryX: number[] = [0];
  for (let i = 0; i < stageCount; i++) {
    boundaryX.push(marginX + (usableW * (i + 0.5)) / stageCount);
  }
  boundaryX.push(w);
  const nipGaps: number[] = [];
  for (let i = 0; i < stageCount; i++) {
    // each break stage narrows the gap
    nipGaps.push(Math.max(rollerDiameter * 0.05, rollerDiameter * (0.22 - i * 0.045)));
  }
  return {
    w,
    h,
    stageCount,
    rollerDiameter,
    nipGaps,
    boundaryX,
    centerY: h / 2,
    jitterAmp: rollerDiameter * 0.55,
  };
}

export function RollerBreakReduce({ activeStage, className = "" }: RollerBreakReduceProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const stageRefs = useRef<(HTMLDivElement | null)[]>([]);
  const fastRefs = useRef<(HTMLDivElement | null)[]>([]);
  const slowRefs = useRef<(HTMLDivElement | null)[]>([]);
  const hairlineRefs = useRef<(HTMLDivElement | null)[]>([]);
  const activeStageRef = useRef<number | undefined>(activeStage);
  activeStageRef.current = activeStage;

  // keep the luminance-boost highlight in sync even when the main rAF loop
  // isn't running (reduced motion's frozen frame, or an off-screen pause).
  useEffect(() => {
    for (let i = 0; i < stageRefs.current.length; i++) {
      const el = stageRefs.current[i];
      if (el) el.style.filter = activeStage === i ? "brightness(1.4)" : "";
    }
  }, [activeStage]);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let layout: Layout = computeLayout(1, 1);
    let dpr = 1;
    let particles: Particle[] = [];
    let idCounter = 0;
    let spawnAcc = 0;
    let fastAngle = 0;
    let slowAngle = 0;
    let raf = 0;
    let last = 0;
    let visible = true;
    let sized = false;

    // -- colour: read once via getComputedStyle, re-read only on a class
    // mutation (theme flip). No canvas paint happens before this first read.
    let fg = "";
    const readColors = () => {
      const cs = getComputedStyle(document.documentElement);
      fg = cs.getPropertyValue("--foreground").trim() || fg;
    };
    readColors();

    const mo = new MutationObserver(readColors);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    const applyRollerStyles = () => {
      const sc = layout.stageCount;
      for (let i = 0; i < stageRefs.current.length; i++) {
        const stageEl = stageRefs.current[i];
        const hairEl = hairlineRefs.current[i];
        if (i >= sc) {
          if (stageEl) stageEl.style.display = "none";
          if (hairEl) hairEl.style.display = "none";
          continue;
        }
        const fastEl = fastRefs.current[i];
        const slowEl = slowRefs.current[i];
        if (!stageEl || !fastEl || !slowEl) continue;
        stageEl.style.display = "";
        if (hairEl) hairEl.style.display = "";
        const x = layout.boundaryX[i + 1] ?? 0;
        const gap = layout.nipGaps[i] ?? 0;
        const r = layout.rollerDiameter;
        stageEl.style.left = `${x}px`;
        stageEl.style.top = `${layout.centerY}px`;
        stageEl.style.width = `${r}px`;
        stageEl.style.filter = activeStageRef.current === i ? "brightness(1.4)" : "";
        fastEl.style.width = `${r}px`;
        fastEl.style.height = `${r}px`;
        fastEl.style.transform = `translate(-50%, calc(-100% - ${gap / 2}px)) rotate(${fastAngle}deg)`;
        slowEl.style.width = `${r}px`;
        slowEl.style.height = `${r}px`;
        slowEl.style.transform = `translate(-50%, ${gap / 2}px) rotate(${slowAngle}deg)`;
        if (hairEl) {
          hairEl.style.left = `${x}px`;
        }
      }
    };

    const draw = (now: number) => {
      const { boundaryX, stageCount, centerY, w, h } = layout;
      ctx.clearRect(0, 0, w, h);
      ctx.fillStyle = fg;
      for (const p of particles) {
        const segFrac = clamp01((now - p.segStart) / SEG_MS);
        const ease = easeInOutCubic(segFrac);
        const x = lerp(boundaryX[p.segIndex] ?? 0, boundaryX[p.segIndex + 1] ?? w, ease);
        const passingNipAhead = p.segIndex < stageCount;
        let compressT = 0;
        if (passingNipAhead && segFrac >= 1 - NIP_MS / SEG_MS) {
          compressT = (segFrac - (1 - NIP_MS / SEG_MS)) / (NIP_MS / SEG_MS);
        }
        const squish = Math.sin(Math.PI * clamp01(compressT)) * 0.45;
        const diamPre = p.baseDiameter * Math.pow(REDUCTION, Math.min(p.segIndex, stageCount));
        const diamPost = p.baseDiameter * Math.pow(REDUCTION, Math.min(p.segIndex + 1, stageCount));
        const diameter = passingNipAhead ? lerp(diamPre, diamPost, compressT) : diamPre;
        const rx = Math.max(0.5, (diameter / 2) * (1 + squish * 0.6));
        const ry = Math.max(0.5, (diameter / 2) * (1 - squish));
        const yOffsetNow = passingNipAhead ? lerp(p.yOffset, 0, compressT) : p.yOffset;
        const y = centerY + yOffsetNow;
        ctx.beginPath();
        ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
        ctx.fill();
      }
    };

    const step = (now: number, dt: number) => {
      const { stageCount, jitterAmp } = layout;
      const totalSegs = stageCount + 1;

      spawnAcc += dt;
      const spawnInterval = 1000 / FEED_RATE;
      while (spawnAcc >= spawnInterval && particles.length < POP_CAP * 2) {
        spawnAcc -= spawnInterval;
        particles.push({
          id: idCounter++,
          segIndex: 0,
          segStart: now,
          yOffset: (Math.random() * 2 - 1) * jitterAmp,
          baseDiameter: BASE_DIAM_MIN + Math.random() * (BASE_DIAM_MAX - BASE_DIAM_MIN),
        });
      }

      const next: Particle[] = [];
      for (const p of particles) {
        const segFrac = (now - p.segStart) / SEG_MS;
        if (segFrac >= 1) {
          const crossedNip = p.segIndex < stageCount;
          const overshoot = (segFrac - 1) * SEG_MS;
          const newSegIndex = p.segIndex + 1;
          if (newSegIndex >= totalSegs) continue; // exited the pipeline
          p.segIndex = newSegIndex;
          p.segStart = now - overshoot;
          if (crossedNip && next.length < POP_CAP) {
            // a kernel breaks into fragments: 1:2 split, capped at steady state
            next.push({
              ...p,
              id: idCounter++,
              yOffset: (Math.random() * 2 - 1) * jitterAmp,
            });
          }
        }
        next.push(p);
      }
      particles = next;

      fastAngle = (fastAngle + FAST_REV_S * 360 * (dt / 1000)) % 360;
      slowAngle = (slowAngle + SLOW_REV_S * 360 * (dt / 1000)) % 360;
    };

    const loop = (now: number) => {
      raf = 0;
      if (!visible || !sized) return;
      if (last === 0) last = now;
      const dt = Math.min(100, now - last);
      last = now;
      step(now, dt);
      applyRollerStyles();
      draw(now);
      raf = requestAnimationFrame(loop);
    };

    // -- reduced motion: freeze on a deliberately chosen non-t0 frame — mid
    // nip at stage 2, with the full size-reduction gradient already visible
    // across the rest of the pipeline. No rAF loop is ever started. -------
    const renderReducedFrame = () => {
      const { stageCount, jitterAmp } = layout;
      fastAngle = 132;
      slowAngle = 47;
      const frameParticles: Particle[] = [];
      // one particle resting mid-segment for every travel segment...
      for (let seg = 0; seg <= stageCount; seg++) {
        frameParticles.push({
          id: seg,
          segIndex: seg,
          segStart: -SEG_MS * 0.45,
          yOffset: (seg % 2 === 0 ? 1 : -1) * jitterAmp * 0.4,
          baseDiameter: (BASE_DIAM_MIN + BASE_DIAM_MAX) / 2,
        });
      }
      // ...except stage index 1 ("stage 2"), caught mid-compression in its nip.
      if (stageCount >= 2) {
        frameParticles[1] = {
          id: 99,
          segIndex: 1,
          segStart: -(SEG_MS - NIP_MS / 2),
          yOffset: 0,
          baseDiameter: (BASE_DIAM_MIN + BASE_DIAM_MAX) / 2,
        };
      }
      particles = frameParticles;
      applyRollerStyles();
      draw(0);
    };

    const resize = () => {
      const rect = root.getBoundingClientRect();
      if (rect.width < 2 || rect.height < 2) {
        sized = false;
        return;
      }
      layout = computeLayout(rect.width, rect.height);
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.style.width = `${rect.width}px`;
      canvas.style.height = `${rect.height}px`;
      canvas.width = Math.round(rect.width * dpr);
      canvas.height = Math.round(rect.height * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      sized = true;

      if (reduced) {
        renderReducedFrame();
        return;
      }
      last = 0;
      if (!raf) raf = requestAnimationFrame(loop);
    };

    const ro = new ResizeObserver(resize);
    ro.observe(root);
    resize();

    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && !reduced && sized && !raf) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    });
    io.observe(root);

    const onVis = () => {
      visible = document.visibilityState === "visible";
      if (visible && !reduced && sized && !raf) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };
    document.addEventListener("visibilitychange", onVis);

    return () => {
      cancelAnimationFrame(raf);
      raf = 0;
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", onVis);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // stage count is not known until measured; render a fixed max of 4 stage
  // shells (the effect only ever writes styles onto however many the
  // current layout uses, the rest stay display:none via the loop below —
  // but since stageCount is derived from the same measurement the effect
  // uses, we just always mount 4 and let unused ones sit off in width 0).
  const stageSlots = [0, 1, 2, 3];

  return (
    <div ref={rootRef} className={`relative overflow-hidden bg-background ${className}`}>
      {stageSlots.map((i) => (
        <div key={i} className="absolute h-px w-px border-l border-border" style={{ top: 0, bottom: 0, height: "100%" }} ref={(el) => { hairlineRefs.current[i] = el; }} />
      ))}
      {stageSlots.map((i) => (
        <div
          key={i}
          ref={(el) => {
            stageRefs.current[i] = el;
          }}
          className="absolute"
          aria-hidden="true"
        >
          <div
            ref={(el) => {
              fastRefs.current[i] = el;
            }}
            className="absolute left-0 top-0 rounded-full"
            style={{
              background: "var(--ns-muted)",
              backgroundImage: `repeating-conic-gradient(from 0deg, var(--foreground) 0deg ${
                360 / RIDGE_COUNT / 2
              }deg, transparent ${360 / RIDGE_COUNT / 2}deg ${360 / RIDGE_COUNT}deg)`,
              opacity: 0.92,
            }}
          />
          <div
            ref={(el) => {
              slowRefs.current[i] = el;
            }}
            className="absolute left-0 top-0 rounded-full"
            style={{
              background: "var(--ns-muted)",
              backgroundImage: `repeating-conic-gradient(from 0deg, var(--foreground) 0deg ${
                360 / RIDGE_COUNT / 2
              }deg, transparent ${360 / RIDGE_COUNT / 2}deg ${360 / RIDGE_COUNT}deg)`,
              opacity: 0.92,
            }}
          />
        </div>
      ))}
      <canvas ref={canvasRef} className="pointer-events-none absolute inset-0 h-full w-full" aria-hidden="true" />
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// RollerOcclusion — a determinate-feel "something is being pumped" ambient,
// drawn as a real peristaltic (roller-head) pump: a three-roller rotor spins
// above a horizontal tube, each roller's ORBITAL POSITION projected onto the
// tube's x-axis (rollerX = pivotX + rotorRadius*cos(angle)) so the pinch it
// makes visibly travels along the tube as the rotor turns, rather than
// squeezing one fixed spot. Occlusion depth is governed by a ±70°
// contact window centred on the roller's closest approach to the tube
// (angle = 90°, i.e. straight down from the rotor pivot): the lumen closes
// over a fixed 60ms as a roller enters that window, holds fully flat for the
// remainder, then releases over a fixed 90ms as it exits — real numbers for
// tube-wall viscoelastic response, held constant in wall-clock time
// regardless of rotor speed (a material property, not a pump-speed one).
// Three rollers at 120° spacing with a 140°-wide window each mean windows
// overlap ~20°, so exactly one roller is ever ≥95% occluding — flow reads as
// quasi-continuous, the standard justification for choosing a roller pump
// over a piston pump.
//
// A fluid slug (length = rotor circumference / 3, one per roller gap) is
// painted as a repeating sawtooth luminance ramp along the tube's lumen —
// leading edge brightest, fading linearly to the trailing edge over the
// slug's own length — advancing at 1.08 tube-lengths per rotor revolution.
// That 1.08 is deliberately NOT 1: an integer ratio would make the slug
// pattern land on the exact same tube pixels every revolution and the loop
// would read as freezing every ~5s (kill criterion). Both the rotor angle
// and the slug offset are unwrapped, monotonically increasing values, so the
// resting loop is genuinely different at every point in time and only
// approximately repeats after many revolutions.
//
// Every ink (--foreground, --ns-muted, --border, --background) is read once
// via getComputedStyle(document.documentElement) before the first paint and
// re-read on a MutationObserver watching documentElement's class — no canvas
// draw call ever runs before that first read completes. Hover/focus over the
// component nudges rotor speed to 1.6x for the duration (a "spinning up"
// read, luminance/speed only, never the fluid's colour) and decays back to
// 1x over 400ms on release; it never pauses the rotor and never recolors
// anything with --ns-accent — the whole component avoids the accent token
// entirely, since nothing here is interaction chrome.
// ---------------------------------------------------------------------------

const IDLE_RPM = 12; // rotor speed at rest — mid-range for a lab peristaltic pump
const IDLE_DEG_PER_SEC = (IDLE_RPM / 60) * 360;
const HOVER_MULT = 1.6;
const RELEASE_MS = 400; // decay of the hover speed bump back to 1x

const ROLLER_COUNT = 3;
const ROLLER_STEP_DEG = 360 / ROLLER_COUNT;
const CONTACT_HALF_DEG = 70; // ±70° = 140° contact arc per roller
const CLOSE_MS = 60; // wall-clock lumen close time, entering contact
const OPEN_MS = 90; // wall-clock lumen release time, exiting contact
const MIN_LUMEN_FRAC = 0.04; // fully-occluded lumen, 4% of open width

const TUBE_LEN_FRAC = 0.7; // of the container's smaller dimension
const TUBE_DIAM_FRAC = 0.18; // of the container's smaller dimension
const ROTOR_RADIUS_MULT = 1.4; // x tube diameter
// The spec's "12% of tube diameter" reads as a typo against its own "sized
// to visibly flatten the tube" — a roller that small could never reach the
// lumen centreline. Sized here so the roller circle actually overlaps and
// fully closes the tube at closest approach, per that same clause.
const ROLLER_RADIUS_MULT = 0.62; // x tube diameter
const SLUG_ADVANCE_RATIO = 1.08; // tube-lengths advanced per rotor revolution
const COLS = 96; // tube cross-section samples per frame

const DEG2RAD = Math.PI / 180;

function clamp(n: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, n));
}

function smoothstep(t: number): number {
  const x = clamp(t, 0, 1);
  return x * x * (3 - 2 * x);
}

type RGB = { r: number; g: number; b: number };

function parseHex(raw: string): RGB | null {
  const m = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(raw.trim());
  if (!m) return null;
  let h = m[1]!;
  if (h.length === 3) h = h.split("").map((c) => c + c).join("");
  const n = parseInt(h, 16);
  return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
}

function mix(a: RGB, b: RGB, t: number): RGB {
  const k = clamp(t, 0, 1);
  return {
    r: a.r + (b.r - a.r) * k,
    g: a.g + (b.g - a.g) * k,
    b: a.b + (b.b - a.b) * k,
  };
}

function rgbStr(c: RGB, alpha = 1): string {
  return `rgba(${c.r.toFixed(1)},${c.g.toFixed(1)},${c.b.toFixed(1)},${alpha})`;
}

// wraps to (-180, 180]
function wrapDelta(deg: number): number {
  let d = deg % 360;
  if (d > 180) d -= 360;
  if (d <= -180) d += 360;
  return d;
}

/** occlusion 0..1 for a roller at angular distance `raw` degrees from the
 * contact centre (90°, straight down from the pivot), given the rotor's
 * current speed in degrees/second. Close/open durations are fixed wall-clock
 * ms, converted to an angular fraction of the current window using that
 * speed — a material property held constant regardless of rotor RPM. */
function occlusionFor(raw: number, degPerSec: number): number {
  if (Math.abs(raw) > CONTACT_HALF_DEG) return 0;
  const localT = (raw + CONTACT_HALF_DEG) / (CONTACT_HALF_DEG * 2); // 0..1
  const windowMs = ((CONTACT_HALF_DEG * 2) / Math.max(1, degPerSec)) * 1000;
  const fIn = CLOSE_MS / windowMs;
  const fOut = OPEN_MS / windowMs;
  if (localT < fIn) return smoothstep(localT / Math.max(1e-6, fIn));
  if (localT > 1 - fOut) return 1 - smoothstep((localT - (1 - fOut)) / Math.max(1e-6, fOut));
  return 1;
}

export interface RollerOcclusionProps {
  /** accessible label for the ambient region. Default "Data pump active" */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function RollerOcclusion({ label = "Data pump active", className = "" }: RollerOcclusionProps) {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");

    // ---- token inks: read before anything paints, re-read live -----------
    let fg: RGB = { r: 23, g: 23, b: 23 };
    let mutedC: RGB = { r: 77, g: 77, b: 77 };
    let borderC: RGB = { r: 235, g: 235, b: 235 };
    let bgC: RGB = { r: 255, g: 255, b: 255 };
    let isDark = false;
    const readTokens = () => {
      const cs = getComputedStyle(document.documentElement);
      fg = parseHex(cs.getPropertyValue("--foreground")) ?? fg;
      mutedC = parseHex(cs.getPropertyValue("--ns-muted")) ?? mutedC;
      borderC = parseHex(cs.getPropertyValue("--border")) ?? borderC;
      bgC = parseHex(cs.getPropertyValue("--background")) ?? bgC;
      isDark = document.documentElement.classList.contains("dark");
    };
    readTokens();

    let w = 0;
    let h = 0;
    let dpr = 1;
    let sized = false;
    let visible = true;

    let tubeLeft = 0;
    let tubeLen = 0;
    let tubeRadius = 0;
    let rotorRadius = 0;
    let rollerRadius = 0;
    let pivotX = 0;
    let rotorCenterY = 0;
    let tubeCenterY = 0;

    const measure = () => {
      const rect = root.getBoundingClientRect();
      if (rect.width < 2 || rect.height < 2) {
        sized = false;
        return;
      }
      w = rect.width;
      h = rect.height;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
      canvas.style.width = `${w}px`;
      canvas.style.height = `${h}px`;

      const minDim = Math.min(w, h);
      tubeLen = minDim * TUBE_LEN_FRAC;
      const tubeDiam = minDim * TUBE_DIAM_FRAC;
      tubeRadius = tubeDiam / 2;
      rotorRadius = tubeDiam * ROTOR_RADIUS_MULT;
      rollerRadius = tubeDiam * ROLLER_RADIUS_MULT;
      pivotX = w / 2;
      tubeCenterY = h / 2 + rotorRadius - tubeRadius / 2;
      rotorCenterY = tubeCenterY - rotorRadius;
      tubeLeft = pivotX - tubeLen / 2;
      sized = true;
    };
    measure();

    const slugPeriod = () => (2 * Math.PI * rotorRadius) / ROLLER_COUNT;

    // ---- hover/focus speed bump: 1x <-> 1.6x, snap up, 400ms decay -------
    let hoverActive = false;
    let mult = 1;
    let releaseFrom = 1;
    let releaseStart = 0;

    const applyHover = (active: boolean) => {
      if (active && !hoverActive) {
        hoverActive = true;
        mult = HOVER_MULT;
      } else if (!active && hoverActive) {
        hoverActive = false;
        releaseFrom = mult;
        releaseStart = performance.now();
      }
      wake();
    };

    const tickMult = (now: number) => {
      if (hoverActive) {
        mult = HOVER_MULT;
        return;
      }
      if (releaseStart) {
        const t = clamp((now - releaseStart) / RELEASE_MS, 0, 1);
        mult = releaseFrom + (1 - releaseFrom) * smoothstep(t);
        if (t >= 1) releaseStart = 0;
      } else {
        mult = 1;
      }
    };

    // ---- state: unwrapped rotor angle + slug offset -----------------------
    // t0: roller 0 sits at 90° (dead-bottom, fully occluding); a slug
    // boundary sits at the tube midpoint.
    let rotorDeg = 90;
    let slugOffset = 0; // px, unwrapped
    let sizedOnce = false;

    const draw = () => {
      if (!sized) return;
      if (!sizedOnce) {
        slugOffset = tubeLen / 2;
        sizedOnce = true;
      }
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);

      const rollerXs: number[] = [];
      const rollerOcc: number[] = [];
      for (let i = 0; i < ROLLER_COUNT; i++) {
        const angle = rotorDeg + i * ROLLER_STEP_DEG;
        const raw = wrapDelta(angle - 90);
        const occ = occlusionFor(raw, IDLE_DEG_PER_SEC * mult);
        const rad = angle * DEG2RAD;
        rollerXs.push(pivotX + Math.cos(rad) * rotorRadius);
        rollerOcc.push(occ);
      }
      const sigma = rollerRadius * 0.9;
      const period = slugPeriod();

      const colW = tubeLen / COLS + 0.6;
      for (let c = 0; c < COLS; c++) {
        const frac = c / (COLS - 1);
        const x = tubeLeft + frac * tubeLen;

        let occAtX = 0;
        for (let i = 0; i < ROLLER_COUNT; i++) {
          const dx = x - rollerXs[i]!;
          const g = Math.exp(-(dx * dx) / (2 * sigma * sigma));
          const contribution = rollerOcc[i]! * g;
          if (contribution > occAtX) occAtX = contribution;
        }
        const wallHalf = tubeRadius * Math.max(MIN_LUMEN_FRAC, 1 - occAtX * (1 - MIN_LUMEN_FRAC));
        const lumenHalf = wallHalf * 0.6;

        // wall: dark theme is a flat --ns-muted fill; light theme ramps
        // --background -> --ns-muted across the tube so the pinch point
        // never nearly vanishes against a light page (checked first, not
        // as an afterthought — the documented failure mode).
        const wallColor = isDark ? mutedC : mix(bgC, mutedC, 0.35 + 0.5 * frac);

        ctx.fillStyle = rgbStr(wallColor, isDark ? 0.85 : 1);
        ctx.fillRect(x - colW / 2, tubeCenterY - wallHalf, colW, wallHalf * 2);

        // fluid slug: sawtooth luminance ramp, leading edge brightest,
        // fading to the trailing edge over the slug's own length — a
        // gradient in colour, never in opacity, so it composites correctly
        // under both themes.
        const local = (((x - slugOffset) % period) + period) % period;
        const leadFrac = 1 - local / period;
        const leadColor = fg;
        const fluidColor = mix(mutedC, leadColor, leadFrac);
        ctx.fillStyle = rgbStr(fluidColor, 0.95);
        ctx.fillRect(x - colW / 2, tubeCenterY - lumenHalf, colW, lumenHalf * 2);
      }

      // outline: a border-token stroke only, traced along the same wall
      // envelope used above — never a fill, per the separator-token rule.
      ctx.beginPath();
      for (let c = 0; c < COLS; c++) {
        const frac = c / (COLS - 1);
        const x = tubeLeft + frac * tubeLen;
        let occAtX = 0;
        for (let i = 0; i < ROLLER_COUNT; i++) {
          const dx = x - rollerXs[i]!;
          const g = Math.exp(-(dx * dx) / (2 * sigma * sigma));
          const contribution = rollerOcc[i]! * g;
          if (contribution > occAtX) occAtX = contribution;
        }
        const wallHalf = tubeRadius * Math.max(MIN_LUMEN_FRAC, 1 - occAtX * (1 - MIN_LUMEN_FRAC));
        if (c === 0) ctx.moveTo(x, tubeCenterY - wallHalf);
        else ctx.lineTo(x, tubeCenterY - wallHalf);
      }
      for (let c = COLS - 1; c >= 0; c--) {
        const frac = c / (COLS - 1);
        const x = tubeLeft + frac * tubeLen;
        let occAtX = 0;
        for (let i = 0; i < ROLLER_COUNT; i++) {
          const dx = x - rollerXs[i]!;
          const g = Math.exp(-(dx * dx) / (2 * sigma * sigma));
          const contribution = rollerOcc[i]! * g;
          if (contribution > occAtX) occAtX = contribution;
        }
        const wallHalf = tubeRadius * Math.max(MIN_LUMEN_FRAC, 1 - occAtX * (1 - MIN_LUMEN_FRAC));
        ctx.lineTo(x, tubeCenterY + wallHalf);
      }
      ctx.closePath();
      ctx.lineWidth = 1;
      ctx.strokeStyle = rgbStr(borderC, isDark ? 0.9 : 1);
      ctx.stroke();

      // rotor + rollers, a light structural read above the tube
      ctx.beginPath();
      ctx.arc(pivotX, rotorCenterY, rotorRadius, 0, Math.PI * 2);
      ctx.strokeStyle = rgbStr(mutedC, 0.3);
      ctx.lineWidth = 1;
      ctx.stroke();
      for (let i = 0; i < ROLLER_COUNT; i++) {
        const angle = (rotorDeg + i * ROLLER_STEP_DEG) * DEG2RAD;
        const rx = pivotX + Math.cos(angle) * rotorRadius;
        const ry = rotorCenterY + Math.sin(angle) * rotorRadius;
        ctx.beginPath();
        ctx.arc(rx, ry, rollerRadius, 0, Math.PI * 2);
        const t = rollerOcc[i]!;
        ctx.fillStyle = rgbStr(mix(mutedC, fg, t * 0.5), 0.22 + t * 0.35);
        ctx.fill();
        ctx.strokeStyle = rgbStr(mutedC, 0.55);
        ctx.stroke();
      }
      ctx.beginPath();
      ctx.arc(pivotX, rotorCenterY, Math.max(1.5, rotorRadius * 0.06), 0, Math.PI * 2);
      ctx.fillStyle = rgbStr(mutedC, 0.5);
      ctx.fill();
    };

    // ---- reduced-motion: one deliberately chosen structured frame --------
    // FREEZE_PHASE = 35deg-into-occlusion: roller 0 sits 35° into its 140°
    // contact arc (raw = -35, i.e. angle = 55°), tube ~60% occluded there —
    // mid-motion, not fully pinched, not fully open — with a slug boundary
    // parked at the tube's 1/3 mark.
    const drawReduced = () => {
      if (!sized) return;
      rotorDeg = 55;
      const savedOcclusion = 0.6;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);

      const rollerXs: number[] = [];
      const rollerOcc: number[] = [0, 0, 0];
      rollerOcc[0] = savedOcclusion;
      for (let i = 0; i < ROLLER_COUNT; i++) {
        const angle = (rotorDeg + i * ROLLER_STEP_DEG) * DEG2RAD;
        rollerXs.push(pivotX + Math.cos(angle) * rotorRadius);
      }
      const sigma = rollerRadius * 0.9;
      const period = slugPeriod();
      const colW = tubeLen / COLS + 0.6;
      const boundaryOffset = tubeLeft + tubeLen / 3; // slug boundary at the 1/3 mark

      for (let c = 0; c < COLS; c++) {
        const frac = c / (COLS - 1);
        const x = tubeLeft + frac * tubeLen;
        let occAtX = 0;
        for (let i = 0; i < ROLLER_COUNT; i++) {
          const dx = x - rollerXs[i]!;
          const g = Math.exp(-(dx * dx) / (2 * sigma * sigma));
          const contribution = rollerOcc[i]! * g;
          if (contribution > occAtX) occAtX = contribution;
        }
        const wallHalf = tubeRadius * Math.max(MIN_LUMEN_FRAC, 1 - occAtX * (1 - MIN_LUMEN_FRAC));
        const lumenHalf = wallHalf * 0.6;
        const wallColor = isDark ? mutedC : mix(bgC, mutedC, 0.35 + 0.5 * frac);
        ctx.fillStyle = rgbStr(wallColor, isDark ? 0.85 : 1);
        ctx.fillRect(x - colW / 2, tubeCenterY - wallHalf, colW, wallHalf * 2);

        const local = (((x - boundaryOffset) % period) + period) % period;
        const leadFrac = 1 - local / period;
        const fluidColor = mix(mutedC, fg, leadFrac);
        ctx.fillStyle = rgbStr(fluidColor, 0.95);
        ctx.fillRect(x - colW / 2, tubeCenterY - lumenHalf, colW, lumenHalf * 2);
      }

      ctx.beginPath();
      ctx.arc(pivotX, rotorCenterY, rotorRadius, 0, Math.PI * 2);
      ctx.strokeStyle = rgbStr(mutedC, 0.3);
      ctx.lineWidth = 1;
      ctx.stroke();
      for (let i = 0; i < ROLLER_COUNT; i++) {
        const angle = (rotorDeg + i * ROLLER_STEP_DEG) * DEG2RAD;
        const rx = pivotX + Math.cos(angle) * rotorRadius;
        const ry = rotorCenterY + Math.sin(angle) * rotorRadius;
        ctx.beginPath();
        ctx.arc(rx, ry, rollerRadius, 0, Math.PI * 2);
        const t = rollerOcc[i]!;
        ctx.fillStyle = rgbStr(mix(mutedC, fg, t * 0.5), 0.22 + t * 0.35);
        ctx.fill();
        ctx.strokeStyle = rgbStr(mutedC, 0.55);
        ctx.stroke();
      }
    };

    let raf = 0;
    let last = 0;

    const loop = (now: number) => {
      raf = 0;
      if (!visible || document.hidden || !sized) {
        last = 0;
        return;
      }
      const dt = last === 0 ? 1 / 60 : Math.min(0.05, (now - last) / 1000);
      last = now;

      tickMult(now);
      const degPerSec = IDLE_DEG_PER_SEC * mult;
      rotorDeg += degPerSec * dt;
      slugOffset += SLUG_ADVANCE_RATIO * tubeLen * (degPerSec / 360) * dt;

      draw();
      raf = requestAnimationFrame(loop);
    };

    const wake = () => {
      if (mq.matches) {
        drawReduced();
        return;
      }
      if (!raf) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    if (mq.matches) {
      drawReduced();
    } else {
      wake();
    }

    const onMq = () => {
      if (mq.matches) {
        cancelAnimationFrame(raf);
        raf = 0;
        drawReduced();
      } else {
        wake();
      }
    };
    mq.addEventListener("change", onMq);

    const ro = new ResizeObserver(() => {
      measure();
      if (mq.matches) drawReduced();
      else wake();
    });
    ro.observe(root);

    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && !mq.matches) wake();
    });
    io.observe(root);

    const mo = new MutationObserver(() => {
      readTokens();
      if (mq.matches) drawReduced();
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    const onVis = () => {
      if (!document.hidden) wake();
    };
    document.addEventListener("visibilitychange", onVis);

    const onEnter = () => applyHover(true);
    const onLeave = () => applyHover(false);
    root.addEventListener("pointerenter", onEnter);
    root.addEventListener("pointerleave", onLeave);
    root.addEventListener("focus", onEnter);
    root.addEventListener("blur", onLeave);

    return () => {
      cancelAnimationFrame(raf);
      raf = 0;
      mq.removeEventListener("change", onMq);
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", onVis);
      root.removeEventListener("pointerenter", onEnter);
      root.removeEventListener("pointerleave", onLeave);
      root.removeEventListener("focus", onEnter);
      root.removeEventListener("blur", onLeave);
    };
  }, []);

  return (
    <div
      ref={rootRef}
      role="group"
      aria-label={label}
      tabIndex={0}
      data-roller-occlusion
      className={`relative h-full w-full overflow-hidden rounded-md border border-border bg-background outline-none focus-visible:ring-2 focus-visible:ring-foreground/70 ${className}`}
    >
      <canvas ref={canvasRef} aria-hidden="true" className="block h-full w-full" />
    </div>
  );
}

RollerOcclusion.displayName = "RollerOcclusion";

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// RopewalkLayTwist — an ambient card background modeling rope laying in a
// traditional ropewalk: three pre-twisted yarns are drawn together at a
// fixed convergence point ("the top") where a counter-rotation locks them
// into one rope, which is continuously hauled off and wound onto a take-up
// drum. Source: ropewalk cordage manufacture (yarn-twist and rope-lay run
// in opposite directions, which is what keeps a finished rope torque-
// balanced and un-kinked).
//
// TWO ROTATIONS, deliberately not the same rate:
//  - LAY rotation — how fast the 3 strands spiral into the rope at the
//    convergence point — is governed by feedDist / L (lay length).
//  - WRAP rate — how fast completed rope winds around the drum's own
//    circumference — is governed by feedDist / C (drum circumference).
//  Both are driven by the SAME feedDist (one continuous haul-off clock,
//  never reset), but L and C are unrelated lengths, so the two rotations
//  run at different, independently-tunable periods. (A build note: an
//  earlier draft of this spec assumed the same rate for both, which
//  produced a drum that would take ~25s to show a single wrap at card
//  scale — fixed here by decoupling the two periods properly, matching
//  the spec's own "alive at rest within 5s" requirement instead of its
//  literal shared-omega description.)
//
// STRANDS (pre-convergence, x in [0, topX]): each is a travelling cosine
// wave y = midY + strandR * cos(2π*x/L - 2π*feedDist/L + phase_i), phase_i
// = i * 2π/3. This both twists the strands (three-lobed) and slides that
// twist rightward at exactly FEED px/s, matching the haul-off speed.
// Z-order/opacity per strand comes from cos(phase) at the convergence
// point: whichever strand is nearest full amplitude (+1, "toward viewer")
// draws last, at higher opacity.
//
// ROPE (post-convergence): a single stroked path from the convergence
// point to the drum, with a faint periodic luminance ripple at the same
// wavelength L, reading as twisted structure rather than a flat cable.
//
// DRUM: a ring-recycling system. Every completed drum layer (a run of
// WRAPS_PER_LAYER full wraps) is tracked by an absolute integer index.
// Only the most recent MAX_LAYERS layers are ever rendered, each easing
// toward its current display radius (innermost = oldest of the visible
// set); a layer aging out of that window eases its opacity to 0 over
// LAYER_FADE_MS while the rest ease one slot inward — "the oldest layer
// fades to make room" from the spec, done continuously rather than as a
// hard cut. The layer still being wound sits one slot further out than
// the newest completed layer and fills in as: a single sweeping arc for
// its very first wrap (0 -> 2π), then rising opacity (not a redundant
// sweep) for each additional wrap in that layer, since further wraps at
// an unchanged radius are genuinely indistinguishable from the first.
// ---------------------------------------------------------------------------

type RGB = [number, number, number];

function parseColor(raw: string): RGB | null {
  const s = raw.trim();
  if (s.startsWith("#")) {
    const hex = s.slice(1);
    if (hex.length === 3) {
      const r = parseInt(hex[0]! + hex[0], 16);
      const g = parseInt(hex[1]! + hex[1], 16);
      const b = parseInt(hex[2]! + hex[2], 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    if (hex.length >= 6) {
      const r = parseInt(hex.slice(0, 2), 16);
      const g = parseInt(hex.slice(2, 4), 16);
      const b = parseInt(hex.slice(4, 6), 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    return null;
  }
  const m = s.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
}

function rgbStr(v: RGB, alpha: number): string {
  return `rgba(${v[0]},${v[1]},${v[2]},${Math.max(0, Math.min(1, alpha))})`;
}

const NOMINAL_MIN_DIM = 160; // px — the size the raw constants below assume
const L0 = 64; // lay length (helical period along the feed axis), px
const FEED0 = 26; // haul-off speed, px/s
const STRAND_R0 = 9; // strand helix radius, px
const LAYER_STEP0 = 6; // radial spacing between drum layers, px
const TOP_X_FRAC = 0.3; // convergence point x, fraction of width
const DRUM_PAD0 = 16; // gap between drum outer edge and the right edge, px
const WRAPS_PER_LAYER = 3;
const MAX_LAYERS = 4;
const LAYER_FADE_S = 2; // seconds for a recycled layer to fade to 0
const RADIUS_EASE = 6; // 1/s — how fast a ring eases toward its target radius
const RIPPLE_ALPHA = 0.22; // rope-body luminance ripple amplitude

interface RingState {
  absIdx: number;
  radius: number;
  targetRadius: number;
  opacity: number;
  targetOpacity: number;
}

export interface RopewalkLayTwistProps {
  /** component height in px. Default 160. */
  height?: number;
  /** accessible label for the decorative root. Default "Rope forming" */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function RopewalkLayTwist({
  height = 160,
  label = "Rope forming",
  className = "",
}: RopewalkLayTwistProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let fg: RGB = [0, 0, 0];
    let muted: RGB = [128, 128, 128];
    let border: RGB = [128, 128, 128];
    let borderAlpha = 1;
    let background: RGB = [255, 255, 255];

    const readTokens = () => {
      const root = getComputedStyle(document.documentElement);
      fg = parseColor(root.getPropertyValue("--foreground")) ?? fg;
      muted = parseColor(root.getPropertyValue("--ns-muted")) ?? muted;
      border = parseColor(root.getPropertyValue("--border")) ?? border;
      background = parseColor(root.getPropertyValue("--background")) ?? background;
      const m = root.getPropertyValue("--border").match(/rgba?\([^)]*,\s*([\d.]+)\s*\)/);
      borderAlpha = m ? Number(m[1]) : 1;
    };

    let width = 0;
    let sized = false;
    let minDim = NOMINAL_MIN_DIM;
    let scale = 1;
    let L = L0;
    let FEED = FEED0;
    let strandR = STRAND_R0;
    let layerStep = LAYER_STEP0;
    let topX = 0;
    let midY = 0;
    let baseRadius = 0;
    let drumCx = 0;
    let circumference = 1;

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      if (rect.width < 2 || rect.height < 2) {
        sized = false;
        return;
      }
      width = rect.width;
      const h = rect.height;
      minDim = Math.min(width, h);
      scale = Math.max(0.55, Math.min(2.2, minDim / NOMINAL_MIN_DIM));
      L = L0 * scale;
      FEED = FEED0 * scale;
      strandR = STRAND_R0 * scale;
      layerStep = LAYER_STEP0 * scale;
      midY = h / 2;
      baseRadius = minDim * 0.12;
      const maxOuterRadius = baseRadius + (MAX_LAYERS + 1) * layerStep;
      const pad = DRUM_PAD0 * scale;
      drumCx = width - pad - maxOuterRadius;
      topX = Math.min(width * TOP_X_FRAC, Math.max(20, drumCx - 24));
      circumference = 2 * Math.PI * baseRadius;

      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(rect.width * dpr));
      canvas.height = Math.max(1, Math.round(rect.height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      sized = true;
    };

    // -- persistent state ---------------------------------------------------
    let feedDist = 0; // px hauled off, monotonic, never reset
    let newestCompletedLayer = -1; // absolute index of newest fully-wound layer
    const rings: RingState[] = [];

    const slotRadius = (slot: number) => baseRadius + slot * layerStep;

    // called whenever newestCompletedLayer advances by exactly one — keeps
    // the visible ring window (the most recent MAX_LAYERS layers) current
    // and starts recycling the layer that just aged out of it.
    const promoteLayer = () => {
      rings.push({
        absIdx: newestCompletedLayer,
        radius: baseRadius + (MAX_LAYERS + 1) * layerStep, // starts at the active-ring position
        targetRadius: slotRadius(MAX_LAYERS - 1),
        opacity: 1,
        targetOpacity: 1,
      });
      const oldestVisible = newestCompletedLayer - MAX_LAYERS + 1;
      for (const r of rings) {
        if (r.absIdx < oldestVisible) {
          r.targetOpacity = 0;
        } else {
          const slot = MAX_LAYERS - 1 - (newestCompletedLayer - r.absIdx);
          r.targetRadius = slotRadius(slot);
        }
      }
    };

    const stepRings = (dt: number) => {
      const rEase = 1 - Math.exp(-RADIUS_EASE * dt);
      const oEase = 1 - Math.exp(-(1 / LAYER_FADE_S) * dt);
      for (let i = rings.length - 1; i >= 0; i--) {
        const r = rings[i]!;
        r.radius += (r.targetRadius - r.radius) * rEase;
        r.opacity += (r.targetOpacity - r.opacity) * oEase;
        if (r.targetOpacity === 0 && r.opacity < 0.01) rings.splice(i, 1);
      }
    };

    const strandColor = (t: number, alpha: number) => {
      // t in [0,1]: 0 = furthest strand (--ns-muted), 1 = nearest (--foreground)
      const c: RGB = [
        Math.round(muted[0] + (fg[0] - muted[0]) * t),
        Math.round(muted[1] + (fg[1] - muted[1]) * t),
        Math.round(muted[2] + (fg[2] - muted[2]) * t),
      ];
      return rgbStr(c, alpha);
    };

    const draw = () => {
      if (!sized) return;
      const rect = canvas.getBoundingClientRect();
      const h = rect.height;
      ctx.clearRect(0, 0, rect.width, h);

      const layPhase = (2 * Math.PI * feedDist) / L;

      // -- 3 strands, back-to-front by their cos(phase) at convergence -----
      const strandOrder = [0, 1, 2].sort((a, b) => {
        const ca = Math.cos((a * 2 * Math.PI) / 3 - layPhase);
        const cb = Math.cos((b * 2 * Math.PI) / 3 - layPhase);
        return ca - cb; // ascending: furthest (most negative) drawn first
      });
      const STEP_PX = 4;
      for (const i of strandOrder) {
        const phase = (i * 2 * Math.PI) / 3;
        const frontness = (Math.cos(phase - layPhase) + 1) / 2; // 0..1
        ctx.beginPath();
        let started = false;
        for (let x = 0; x <= topX; x += STEP_PX) {
          const y = midY + strandR * Math.cos((2 * Math.PI * x) / L - layPhase + phase);
          if (!started) {
            ctx.moveTo(x, y);
            started = true;
          } else {
            ctx.lineTo(x, y);
          }
        }
        ctx.strokeStyle = strandColor(frontness, 0.5 + 0.4 * frontness);
        ctx.lineWidth = 1.4 * scale;
        ctx.lineCap = "round";
        ctx.stroke();
      }

      // -- the laid rope, convergence point to drum -------------------------
      const ropeEndX = drumCx - baseRadius;
      ctx.beginPath();
      ctx.moveTo(topX, midY);
      ctx.lineTo(ropeEndX, midY);
      ctx.strokeStyle = rgbStr(fg, 0.85);
      ctx.lineWidth = 2.4 * scale;
      ctx.lineCap = "round";
      ctx.stroke();
      // periodic luminance ripple riding the rope body — twist structure,
      // never itself a separate hue.
      for (let x = topX; x < ropeEndX; x += 3) {
        const ripple = Math.cos((2 * Math.PI * x) / L - layPhase);
        if (ripple <= 0.4) continue;
        ctx.fillStyle = rgbStr(background, RIPPLE_ALPHA * ripple);
        ctx.fillRect(x, midY - 1.2 * scale, 3, 2.4 * scale);
      }

      // -- drum -------------------------------------------------------------
      ctx.beginPath();
      ctx.arc(drumCx, midY, baseRadius, 0, Math.PI * 2);
      ctx.strokeStyle = rgbStr(border, borderAlpha);
      ctx.lineWidth = 1;
      ctx.stroke();

      for (const r of rings) {
        if (r.opacity <= 0.01) continue;
        ctx.beginPath();
        ctx.arc(drumCx, midY, r.radius, 0, Math.PI * 2);
        ctx.strokeStyle = rgbStr(fg, 0.75 * r.opacity);
        ctx.lineWidth = Math.max(1, layerStep * 0.6);
        ctx.stroke();
      }

      // active (still-filling) layer
      const wrapProgressTotal = feedDist / circumference;
      const wrapsCompletedInt = Math.floor(wrapProgressTotal);
      const partialWrap = wrapProgressTotal - wrapsCompletedInt;
      const currentLayerWraps = ((wrapsCompletedInt % WRAPS_PER_LAYER) + WRAPS_PER_LAYER) % WRAPS_PER_LAYER;
      const activeRadius = baseRadius + (MAX_LAYERS + 1) * layerStep;
      if (currentLayerWraps === 0) {
        // first wrap of a fresh layer: a genuine sweeping arc, 0 -> 2π
        ctx.beginPath();
        ctx.arc(drumCx, midY, activeRadius, -Math.PI / 2, -Math.PI / 2 + partialWrap * Math.PI * 2);
        ctx.strokeStyle = rgbStr(fg, 0.85);
        ctx.lineWidth = Math.max(1, layerStep * 0.6);
        ctx.stroke();
      } else {
        // subsequent wraps at the same radius are indistinguishable from
        // the first — represented as rising opacity, not a redundant sweep.
        const fillFrac = (currentLayerWraps + partialWrap) / WRAPS_PER_LAYER;
        ctx.beginPath();
        ctx.arc(drumCx, midY, activeRadius, 0, Math.PI * 2);
        ctx.strokeStyle = rgbStr(fg, 0.5 + 0.4 * fillFrac);
        ctx.lineWidth = Math.max(1, layerStep * 0.6);
        ctx.stroke();
      }
    };

    let raf = 0;
    let last = 0;
    let visible = true;

    const loop = (now: number) => {
      if (!visible || document.hidden) {
        raf = 0;
        return;
      }
      const dt = last ? Math.min(0.25, (now - last) / 1000) : 1 / 60;
      last = now;
      feedDist += FEED * dt;

      const wrapsCompletedInt = Math.floor(feedDist / circumference);
      const totalCompletedLayers = Math.floor(wrapsCompletedInt / WRAPS_PER_LAYER);
      while (totalCompletedLayers > newestCompletedLayer + 1) {
        newestCompletedLayer += 1;
        promoteLayer();
      }
      if (totalCompletedLayers === newestCompletedLayer + 1) {
        newestCompletedLayer += 1;
        promoteLayer();
      }

      stepRings(dt);
      draw();
      raf = requestAnimationFrame(loop);
    };

    const start = () => {
      if (raf || reduced) return;
      last = 0;
      raf = requestAnimationFrame(loop);
    };
    const stop = () => {
      cancelAnimationFrame(raf);
      raf = 0;
    };

    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) draw();
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        readTokens();
        resize();
        draw();
      }, 120);
    };
    const ro = new ResizeObserver(onResize);
    ro.observe(canvas);

    const io = new IntersectionObserver(
      (entries) => {
        visible = entries[0]?.isIntersecting ?? true;
        if (visible) start();
        else stop();
      },
      { threshold: 0 }
    );
    io.observe(canvas);

    const onVis = () => {
      if (document.hidden) stop();
      else if (visible) start();
    };
    document.addEventListener("visibilitychange", onVis);

    // no paint before the first token read
    readTokens();
    resize();

    if (reduced) {
      // LAY_QUARTER_PHASE — strand phase frozen at π/2 (the 3 strands at
      // their most visually separated moment, pre-convergence) while the
      // drum already shows 2 full layers plus a half-filled 3rd, so both
      // the twist mechanism and the accumulation are legible in one frame.
      const wrapsForTwoLayers = 2 * WRAPS_PER_LAYER + WRAPS_PER_LAYER * 0.5;
      const rawFeedForWraps = wrapsForTwoLayers * circumference;
      const quarterPhaseOffset = L * 0.25;
      const layTurns = Math.round((rawFeedForWraps - quarterPhaseOffset) / L);
      feedDist = layTurns * L + quarterPhaseOffset;

      const wrapsCompletedInt = Math.floor(feedDist / circumference);
      const totalCompletedLayers = Math.floor(wrapsCompletedInt / WRAPS_PER_LAYER);
      while (totalCompletedLayers > newestCompletedLayer) {
        newestCompletedLayer += 1;
        promoteLayer();
      }
      for (const r of rings) {
        r.radius = r.targetRadius;
        r.opacity = r.targetOpacity;
      }
      draw();
    } else {
      draw();
      start();
    }

    return () => {
      stop();
      if (resizeTimer) clearTimeout(resizeTimer);
      mo.disconnect();
      ro.disconnect();
      io.disconnect();
      document.removeEventListener("visibilitychange", onVis);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [height]);

  return (
    <div role="img" aria-label={label} className={`relative w-full ${className}`} style={{ height }}>
      <canvas ref={canvasRef} aria-hidden="true" className="block h-full w-full" />
    </div>
  );
}

"use client";

import { useCallback, useEffect, useId, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// RouterTierCascade — model routing drawn as a cascade of weirs. One hairline
// row per model tier, cheapest at top. Each row's 1px baseline is broken by a
// WEIR NOTCH at x = ceiling: a 10px gap flanked by two short vertical lips.
// A request enters the top row as a 3px square and travels right at 90px/s.
// If it reaches the notch and its difficulty exceeds that tier's ceiling it
// SPILLS — one row down over 260ms with a 3px overshoot — and resumes on the
// next row. It comes to rest at x = difficulty on whichever row could hold it.
// Cost lives on the same geometry: a mono gutter per row with the accepted
// count, the cumulative spend, and a 1px bar scaled to the busiest row.
// There is no color coding anywhere — tier identity is row position and notch
// x, never hue. DOM + CSS only, one rAF loop shared by all in-flight glyphs.
// ---------------------------------------------------------------------------

export interface RouterTier {
  id: string;
  /** shown in the left column, e.g. "edge-2b" */
  label: string;
  /** cost ceiling as a 0..1 difficulty fraction — where this row's notch sits */
  ceiling: number;
  /** price per 1k tokens, in whatever currency the caller formats around */
  pricePer1k: number;
}

export interface RouterRequest {
  id: string;
  /** 0..1 — how hard the request is; also its resting x on the accepting row */
  difficulty: number;
  /** tokens billed for this request */
  tokens: number;
  /**
   * Advisory only. The component always derives the accepting row from the
   * LIVE ceilings, so dragging a notch re-routes settled traffic; a fixed
   * accepted tier would contradict that.
   */
  acceptedTier?: string;
}

export interface RouterTierCascadeProps {
  /** model tiers, cheapest first — one hairline row each */
  tiers: RouterTier[];
  /** the routed traffic; appending to this array is what animates a cascade */
  requests: RouterRequest[];
  /** ms for a settled tick to fade 1 -> 0.25 (default 45000) */
  decayMs?: number;
  /** fires when a notch is dragged or arrow-keyed to a new ceiling */
  onCeilingChange?: (tierId: string, ceiling: number) => void;
  /** formats a spend figure for the right gutter */
  formatCost?: (amount: number) => string;
  /** accessible name for the cascade */
  ariaLabel?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const ROW_H = 34; // px, one tier
const TICK = 3; // px, settled tick
const TICK_HOVER = 5;
const LIP = 4; // px, notch lip height
const LIP_HOVER = 10;
const NOTCH_GAP = 10; // px cut out of the baseline
const SPILL_MS = 260;
const SPILL_SETTLE_MS = 60; // the last stretch, easing the 3px overshoot out
const OVERSHOOT = 3; // px
const SPEED = 90; // px/s rightward travel
const HOVER_TC = "0.16s";
const PULSE_MS = 3400;
const JITTER_MS = 180;
const CAP = 40; // FIFO settled ticks per row
const MIN_CEIL = 0.02;
const MAX_CEIL = 0.98;

function clamp(v: number, lo: number, hi: number) {
  return Math.min(hi, Math.max(lo, v));
}

function snap(v: number) {
  return Math.round(clamp(v, MIN_CEIL, MAX_CEIL) * 100) / 100;
}

// cubic-bezier(0.33, 0, 0.15, 1) evaluated in JS — the spill uses the same
// curve the CSS re-cascade transition uses, so a drag-triggered re-route and a
// live arrival move identically.
function bezier(x1: number, y1: number, x2: number, y2: number, p: number) {
  const cx = (t: number) => ((1 - t) * (1 - t) * 3 * t * x1) + ((1 - t) * 3 * t * t * x2) + t * t * t;
  const cy = (t: number) => ((1 - t) * (1 - t) * 3 * t * y1) + ((1 - t) * 3 * t * t * y2) + t * t * t;
  let t = p;
  for (let i = 0; i < 6; i++) {
    const err = cx(t) - p;
    if (Math.abs(err) < 1e-5) break;
    const d = (cx(t + 1e-4) - cx(t - 1e-4)) / 2e-4;
    if (Math.abs(d) < 1e-6) break;
    t -= err / d;
    t = clamp(t, 0, 1);
  }
  return cy(t);
}

const SPILL_EASE = (p: number) => bezier(0.33, 0, 0.15, 1, clamp(p, 0, 1));

function useReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const on = () => setReduced(mq.matches);
    mq.addEventListener("change", on);
    return () => mq.removeEventListener("change", on);
  }, []);
  return reduced;
}

function defaultFormatCost(amount: number) {
  if (!Number.isFinite(amount)) return "$0";
  if (amount === 0) return "$0";
  if (amount >= 1) return `$${amount.toFixed(2)}`;
  return `$${amount.toFixed(4)}`;
}

interface Settled {
  id: string;
  difficulty: number;
  tokens: number;
  seq: number;
  /** ms of decay already elapsed when the tick first rendered (seeded batch) */
  aged: number;
}

interface Flight {
  id: string;
  difficulty: number;
  tokens: number;
  row: number;
  x: number; // normalized 0..1
  phase: "travel" | "spill";
  t0: number;
}

/** first tier whose ceiling can hold this difficulty; the last tier otherwise */
function acceptRow(difficulty: number, ceilings: number[]) {
  for (let i = 0; i < ceilings.length; i++) {
    if (difficulty <= ceilings[i]) return i;
  }
  return Math.max(0, ceilings.length - 1);
}

export function RouterTierCascade({
  tiers,
  requests,
  decayMs = 45000,
  onCeilingChange,
  formatCost = defaultFormatCost,
  ariaLabel = "Model routing cascade",
  className = "",
}: RouterTierCascadeProps) {
  const uid = useId();
  const reduced = useReducedMotion();

  const [ceilings, setCeilings] = useState<number[]>(() => tiers.map((t) => snap(t.ceiling)));
  const [settled, setSettled] = useState<Settled[]>([]);
  const [flights, setFlights] = useState<Flight[]>([]);
  const [hover, setHover] = useState<number | null>(null);

  const ceilingsRef = useRef(ceilings);
  ceilingsRef.current = ceilings;

  // keep ceilings in sync when the caller genuinely changes the tier config,
  // without clobbering a ceiling the user just dragged
  const incomingSig = tiers.map((t) => `${t.id}:${t.ceiling}`).join("|");
  const prevSig = useRef(incomingSig);
  useEffect(() => {
    if (prevSig.current === incomingSig) return;
    prevSig.current = incomingSig;
    setCeilings(tiers.map((t) => snap(t.ceiling)));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [incomingSig]);

  const trackRef = useRef<HTMLDivElement | null>(null);
  const trackW = useRef(640);
  useEffect(() => {
    const el = trackRef.current;
    if (!el) return;
    const read = () => {
      const w = el.getBoundingClientRect().width;
      if (w > 0) trackW.current = w;
    };
    read();
    const ro = new ResizeObserver(read);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  // ---- intake -------------------------------------------------------------
  const seen = useRef<Set<string>>(new Set());
  const seq = useRef(0);
  const firstBatch = useRef(true);

  useEffect(() => {
    const fresh = requests.filter((r) => !seen.current.has(r.id));
    if (fresh.length === 0) return;
    fresh.forEach((r) => seen.current.add(r.id));

    // The first batch is history, not live traffic: it lands settled, and each
    // tick is pre-aged along the decay ramp in arrival order so the resting
    // frame reads as accumulated traffic rather than 40 simultaneous arrivals.
    const seeding = firstBatch.current;
    firstBatch.current = false;

    if (seeding || reduced) {
      setSettled((prev) => {
        const next = [...prev];
        fresh.forEach((r, i) => {
          next.push({
            id: r.id,
            difficulty: clamp(r.difficulty, 0, 1),
            tokens: Math.max(0, r.tokens),
            seq: seq.current++,
            aged: seeding ? (1 - (i + 1) / (fresh.length + 1)) * decayMs * 0.55 : 0,
          });
        });
        return next.slice(-CAP * Math.max(1, tiers.length));
      });
      return;
    }

    setFlights((prev) => [
      ...prev,
      ...fresh.map((r) => ({
        id: r.id,
        difficulty: clamp(r.difficulty, 0, 1),
        tokens: Math.max(0, r.tokens),
        row: 0,
        x: 0,
        phase: "travel" as const,
        t0: 0,
      })),
    ]);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [requests, reduced]);

  // ---- the cascade loop ---------------------------------------------------
  const flightRefs = useRef(new Map<string, HTMLDivElement>());
  const stateRef = useRef(new Map<string, Flight>());
  const rafRef = useRef(0);

  // mirror the React flight list into the mutable map the loop walks
  useEffect(() => {
    flights.forEach((f) => {
      if (!stateRef.current.has(f.id)) stateRef.current.set(f.id, { ...f });
    });
    const live = new Set(flights.map((f) => f.id));
    stateRef.current.forEach((_, id) => {
      if (!live.has(id)) stateRef.current.delete(id);
    });
  }, [flights]);

  const settle = useCallback((f: Flight) => {
    setSettled((prev) =>
      [...prev, { id: f.id, difficulty: f.difficulty, tokens: f.tokens, seq: seq.current++, aged: 0 }].slice(
        -CAP * 8
      )
    );
    setFlights((prev) => prev.filter((x) => x.id !== f.id));
  }, []);

  useEffect(() => {
    if (flights.length === 0 || reduced) return;
    let last = performance.now();
    const step = (now: number) => {
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;
      const cs = ceilingsRef.current;
      const speedNorm = SPEED / Math.max(1, trackW.current);
      const done: Flight[] = [];

      stateRef.current.forEach((f) => {
        const el = flightRefs.current.get(f.id);
        if (f.phase === "travel") {
          const ceil = cs[f.row] ?? 1;
          const lastRow = f.row >= cs.length - 1;
          const target = f.difficulty <= ceil || lastRow ? f.difficulty : ceil;
          f.x = Math.min(target, f.x + speedNorm * dt);
          if (f.x >= target - 1e-4) {
            f.x = target;
            if (f.difficulty <= ceil || lastRow) {
              done.push(f);
            } else {
              f.phase = "spill";
              f.t0 = now;
            }
          }
          if (el) {
            el.style.left = `${f.x * 100}%`;
            el.style.transform = `translate(-50%, calc(-50% + ${f.row * ROW_H}px))`;
          }
        } else {
          const p = clamp((now - f.t0) / SPILL_MS, 0, 1);
          const risePart = (SPILL_MS - SPILL_SETTLE_MS) / SPILL_MS;
          let dy: number;
          if (p < risePart) {
            dy = SPILL_EASE(p / risePart) * (ROW_H + OVERSHOOT);
          } else {
            const q = (p - risePart) / (1 - risePart);
            dy = ROW_H + OVERSHOOT - OVERSHOOT * q;
          }
          if (el) {
            el.style.transform = `translate(-50%, calc(-50% + ${f.row * ROW_H + dy}px))`;
          }
          if (p >= 1) {
            f.row += 1;
            f.phase = "travel";
            if (el) el.style.transform = `translate(-50%, calc(-50% + ${f.row * ROW_H}px))`;
          }
        }
      });

      done.forEach((f) => {
        stateRef.current.delete(f.id);
        settle(f);
      });
      rafRef.current = requestAnimationFrame(step);
    };
    rafRef.current = requestAnimationFrame(step);
    return () => cancelAnimationFrame(rafRef.current);
  }, [flights.length, reduced, settle]);

  // ---- derived rows -------------------------------------------------------
  const rows = useMemo(() => {
    const byRow: Settled[][] = tiers.map(() => []);
    settled.forEach((s) => {
      const r = acceptRow(s.difficulty, ceilings);
      byRow[Math.min(r, byRow.length - 1)]?.push(s);
    });
    return byRow.map((list, i) => {
      const kept = list.slice(-CAP);
      const price = tiers[i]?.pricePer1k ?? 0;
      const spend = kept.reduce((a, s) => a + (s.tokens / 1000) * price, 0);
      const per = kept.map((s) => (s.tokens / 1000) * price).sort((a, b) => a - b);
      const median =
        per.length === 0
          ? 0
          : per.length % 2
            ? per[(per.length - 1) / 2]
            : (per[per.length / 2 - 1] + per[per.length / 2]) / 2;
      return { ticks: kept, spend, median, count: kept.length };
    });
  }, [settled, ceilings, tiers]);

  const maxSpend = Math.max(1e-9, ...rows.map((r) => r.spend));
  const newestId = useMemo(() => {
    let best: Settled | null = null;
    settled.forEach((s) => {
      if (!best || s.seq > best.seq) best = s;
    });
    return (best as Settled | null)?.id ?? null;
  }, [settled]);

  // ---- notch drag / keyboard ---------------------------------------------
  const setCeiling = useCallback(
    (i: number, value: number) => {
      const v = snap(value);
      setCeilings((prev) => {
        if (prev[i] === v) return prev;
        const next = [...prev];
        next[i] = v;
        return next;
      });
      const tier = tiers[i];
      if (tier) onCeilingChange?.(tier.id, v);
    },
    [onCeilingChange, tiers]
  );

  const dragging = useRef<number | null>(null);
  const onNotchDown = (i: number) => (e: React.PointerEvent<HTMLDivElement>) => {
    dragging.current = i;
    e.currentTarget.setPointerCapture?.(e.pointerId);
    e.preventDefault();
  };
  const onNotchMove = (i: number) => (e: React.PointerEvent<HTMLDivElement>) => {
    if (dragging.current !== i) return;
    const box = trackRef.current?.getBoundingClientRect();
    if (!box || box.width === 0) return;
    setCeiling(i, (e.clientX - box.left) / box.width);
  };
  const onNotchUp = (i: number) => (e: React.PointerEvent<HTMLDivElement>) => {
    if (dragging.current !== i) return;
    dragging.current = null;
    e.currentTarget.releasePointerCapture?.(e.pointerId);
  };
  const onNotchKey = (i: number) => (e: React.KeyboardEvent<HTMLDivElement>) => {
    const c = ceilings[i] ?? 0;
    let next = c;
    if (e.key === "ArrowLeft" || e.key === "ArrowDown") next = c - 0.01;
    else if (e.key === "ArrowRight" || e.key === "ArrowUp") next = c + 0.01;
    else if (e.key === "PageDown") next = c - 0.1;
    else if (e.key === "PageUp") next = c + 0.1;
    else if (e.key === "Home") next = MIN_CEIL;
    else if (e.key === "End") next = MAX_CEIL;
    else return;
    e.preventDefault();
    setCeiling(i, next);
  };

  const dimmed = (i: number) => hover !== null && hover !== i;

  return (
    <div className={className}>
      <style>{`
.ns-rtc-row{transition:opacity ${HOVER_TC} cubic-bezier(0.4,0,0.2,1)}
.ns-rtc-tick{transition:width ${HOVER_TC} cubic-bezier(0.4,0,0.2,1),height ${HOVER_TC} cubic-bezier(0.4,0,0.2,1),left 260ms cubic-bezier(0.33,0,0.15,1),transform 260ms cubic-bezier(0.33,0,0.15,1)}
.ns-rtc-lip{transition:height ${HOVER_TC} cubic-bezier(0.4,0,0.2,1)}
.ns-rtc-decay{animation:ns-rtc-fade linear forwards}
.ns-rtc-pulse{animation:ns-rtc-breathe ${PULSE_MS}ms ease-in-out infinite alternate}
.ns-rtc-bar{transition:width 400ms cubic-bezier(0.16,1,0.3,1)}
@keyframes ns-rtc-fade{from{opacity:1}to{opacity:0.25}}
@keyframes ns-rtc-breathe{from{opacity:0.55}to{opacity:1}}
@media (prefers-reduced-motion: reduce){
  .ns-rtc-tick,.ns-rtc-row,.ns-rtc-lip,.ns-rtc-bar{transition:none !important}
  .ns-rtc-decay,.ns-rtc-pulse{animation:none !important}
}
`}</style>

      <div role="group" aria-label={ariaLabel} className="w-full select-none">
        <div className="grid grid-cols-[112px_1fr_132px] items-baseline gap-x-3 pb-2 font-mono text-[10px] uppercase tracking-[0.14em] text-ns-muted">
          <span>tier</span>
          <span>difficulty spill &rarr;</span>
          <span className="text-right">accepted · spend</span>
        </div>

        <div className="border-t border-border pt-2" onPointerLeave={() => setHover(null)}>
          {tiers.map((tier, i) => {
            const c = ceilings[i] ?? 0;
            const row = rows[i] ?? { ticks: [], spend: 0, median: 0, count: 0 };
            const hot = hover === i;
            const size = hot ? TICK_HOVER : TICK;
            const lipH = hot ? LIP_HOVER : LIP;
            return (
              <div
                key={tier.id}
                data-tier-row={tier.id}
                className="ns-rtc-row grid grid-cols-[112px_1fr_132px] items-center gap-x-3"
                style={{ height: ROW_H, opacity: dimmed(i) ? 0.18 : 1 }}
                onPointerOver={() => setHover(i)}
                onPointerOut={(e) => {
                  const to = e.relatedTarget as Node | null;
                  if (!to || !e.currentTarget.contains(to)) setHover(null);
                }}
              >
                <div className="flex items-baseline gap-1.5 overflow-hidden font-mono text-[11px]">
                  <span className="truncate text-foreground">{tier.label}</span>
                  <span className="shrink-0 tabular-nums text-ns-muted">
                    {formatCost(tier.pricePer1k)}
                  </span>
                </div>

                {/* track: baseline + weir notch + settled ticks */}
                <div
                  ref={i === 0 ? trackRef : undefined}
                  className="relative h-full"
                  style={i === 0 ? { zIndex: 5 } : undefined}
                >
                  {/* baseline, cut by the notch */}
                  <div
                    className="absolute top-1/2 h-px bg-border"
                    style={{ left: 0, width: `calc(${c * 100}% - ${NOTCH_GAP / 2}px)` }}
                  />
                  <div
                    className="absolute top-1/2 right-0 h-px bg-border"
                    style={{ left: `calc(${c * 100}% + ${NOTCH_GAP / 2}px)` }}
                  />
                  {/* the two weir lips */}
                  <div
                    className="ns-rtc-lip absolute w-px bg-foreground"
                    style={{
                      left: `calc(${c * 100}% - ${NOTCH_GAP / 2}px)`,
                      height: lipH,
                      top: `calc(50% - ${lipH}px)`,
                    }}
                  />
                  <div
                    className="ns-rtc-lip absolute w-px bg-foreground"
                    style={{
                      left: `calc(${c * 100}% + ${NOTCH_GAP / 2}px)`,
                      height: lipH,
                      top: "50%",
                    }}
                  />

                  {/* settled ticks */}
                  {row.ticks.map((s) => {
                    const jitter = ((s.seq * 97) % (2 * JITTER_MS)) - JITTER_MS;
                    return (
                      <div
                        key={s.id}
                        className="ns-rtc-decay absolute top-1/2"
                        style={{
                          left: `${s.difficulty * 100}%`,
                          animationDuration: `${decayMs}ms`,
                          animationDelay: `${-s.aged}ms`,
                        }}
                      >
                        <div
                          className={
                            "ns-rtc-tick bg-foreground" +
                            (s.id === newestId ? " ns-rtc-pulse" : "")
                          }
                          style={{
                            width: size,
                            height: size,
                            marginLeft: -size / 2,
                            marginTop: -size / 2,
                            animationDelay: s.id === newestId ? `${jitter}ms` : undefined,
                          }}
                        />
                      </div>
                    );
                  })}

                  {/* in-flight glyphs live in row 0's track and translate down */}
                  {i === 0
                    ? flights.map((f) => (
                        <div
                          key={f.id}
                          ref={(el) => {
                            if (el) flightRefs.current.set(f.id, el);
                            else flightRefs.current.delete(f.id);
                          }}
                          data-flight
                          className="absolute top-1/2 bg-foreground"
                          style={{
                            left: 0,
                            width: TICK,
                            height: TICK,
                            transform: "translate(-50%, -50%)",
                          }}
                        />
                      ))
                    : null}

                  {/* the notch itself — a real slider */}
                  <div
                    role="slider"
                    tabIndex={0}
                    aria-label={`${tier.label} cost ceiling`}
                    aria-valuemin={MIN_CEIL}
                    aria-valuemax={MAX_CEIL}
                    aria-valuenow={c}
                    aria-valuetext={`${Math.round(c * 100)} percent difficulty`}
                    aria-orientation="horizontal"
                    aria-describedby={`${uid}-r${i}`}
                    onPointerDown={onNotchDown(i)}
                    onPointerMove={onNotchMove(i)}
                    onPointerUp={onNotchUp(i)}
                    onPointerCancel={onNotchUp(i)}
                    onKeyDown={onNotchKey(i)}
                    className="absolute top-0 h-full cursor-ew-resize rounded-[2px] focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-ns-accent"
                    style={{ left: `${c * 100}%`, width: 18, marginLeft: -9, touchAction: "none" }}
                  />
                </div>

                {/* cost gutter, same geometry as the routing */}
                <div className="flex flex-col items-end gap-1 font-mono text-[11px] tabular-nums">
                  <span className="flex items-baseline gap-2">
                    <span className="text-ns-muted">{row.count}</span>
                    <span className="text-foreground">
                      {hot ? `~${formatCost(row.median)}` : formatCost(row.spend)}
                    </span>
                  </span>
                  <span className="block h-px w-full bg-border">
                    <span
                      className="ns-rtc-bar block h-px bg-foreground"
                      style={{ width: `${(row.spend / maxSpend) * 100}%` }}
                    />
                  </span>
                </div>

                <span className="sr-only" id={`${uid}-r${i}`}>
                  {tier.label}: ceiling {Math.round(c * 100)} percent, {row.count} requests accepted,{" "}
                  {formatCost(row.spend)} spent.
                </span>
              </div>
            );
          })}
        </div>

        <p className="pt-2 font-mono text-[10px] text-ns-muted">
          {hover === null
            ? "each row spills at its notch — median per request on hover"
            : `${tiers[hover]?.label ?? ""} · median per request`}
        </p>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// RouteSlip — a multi-party approval ledger styled as an interoffice routing
// slip, not an avatar-stack "seen by" row. Approver rows render in fixed
// ROUTED order and never reorder themselves; that order is set once from the
// `approvers` prop and is the spine every other visual hangs off. Signing is
// a real, irreversible action scoped to `currentApproverId`'s own row — no
// other row ever renders a Sign control. What distinguishes this from a
// checkmark list is that signing out of turn is explicitly PERMITTED: a
// signature is flagged "out of turn" whenever, at final state, some earlier
// -routed approver's slot is still empty or was filled later than this one
// (computed purely from routed index + signed timestamp, not from the order
// clicks happened to arrive in). An in-turn chop settles at a plain 3deg
// tilt; an out-of-turn chop lands with an 8deg skew on top of that tilt —
// large enough to read as irregular at a glance, small enough to stay
// legible — and the row also carries a plain-text "out of turn" note, so the
// distinction never depends on noticing the skew.
//
// One governing scalar — signed count over `quorum` — derives the progress
// line, Publish's aria-disabled state + written reason, and the crawling
// underline under whichever unsigned row is currently "Now" (the first gap
// in routed order, independent of who's allowed to fill it). `quorum` can be
// less than the full roster: publish can unblock before every name is
// stamped, which is a different claim than "everyone signed."
//
// Pure DOM + CSS: a real <table> (approver / role / status / time columns,
// <caption>, <th scope="col">), a polite aria-live region announcing
// "{n} of {total} signed; waiting on {role}", and every color drawn from
// --background / --foreground / --ns-muted / --border / --ns-accent.
// --ns-accent appears nowhere but the enabled Sign/Publish buttons' own
// hover/focus/active states — never on a chop, never as a fill elsewhere.
// ---------------------------------------------------------------------------

export interface RouteSlipApprover {
  /** stable identifier */
  id: string;
  /** printed name */
  name: string;
  /** short role/team label, e.g. "Legal" — this is what Publish's reason and
   * the aria-live announcement name when this approver is next */
  role: string;
}

export interface RouteSlipSignature {
  approverId: string;
  /** when this approver actually signed */
  at: number | Date;
}

export interface RouteSlipProps {
  /** the approver chain in ROUTED order — fixed row order, index 0 is first
   * in sequence. This order never changes regardless of actual signing order. */
  approvers: RouteSlipApprover[];
  /** seed one or more approvers as already signed, in whatever order they
   * actually signed (not necessarily routed order) — out-of-turn flags are
   * derived from this at every render */
  initialSignatures?: RouteSlipSignature[];
  /** signatures required before Publish unblocks. Clamped to
   * [1, approvers.length]. @default approvers.length */
  quorum?: number;
  /** the approver whose row gets a real Sign button — every other row is
   * read-only regardless of signed state */
  currentApproverId?: string;
  /** label for the document being routed, shown as the card title and in
   * the table's accessible caption */
  docLabel?: string;
  /** called once per successful sign, with the approver id and timestamp */
  onSign?: (approverId: string, at: number) => void;
  /** called once, when Publish is activated at or above quorum */
  onPublish?: () => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

type Sig = { approverId: string; at: number };

const CHOP_MS = 260;

function toMs(v: number | Date): number {
  return typeof v === "number" ? v : v.getTime();
}

function initialsOf(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return "?";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

// A wall-clock stamp is the one thing here that can legitimately differ
// between the server render and the client one (locale/timezone), same
// reasoning as approval-inline-diff's TimeStamp — suppressHydrationWarning
// is correct, not a bug being papered over.
function TimeStamp({ ts }: { ts: number }) {
  const label = new Date(ts).toLocaleTimeString(undefined, {
    hour: "numeric",
    minute: "2-digit",
    second: "2-digit",
  });
  return <span suppressHydrationWarning>{label}</span>;
}

export function RouteSlip({
  approvers,
  initialSignatures,
  quorum,
  currentApproverId,
  docLabel = "Routing slip",
  onSign,
  onPublish,
  className = "",
}: RouteSlipProps) {
  const uid = useId().replace(/:/g, "");
  const captionId = `rs-caption-${uid}`;
  const reasonId = `rs-reason-${uid}`;

  const reducedMotion = useReducedMotion();

  const [signatures, setSignatures] = useState<Sig[]>(() =>
    (initialSignatures ?? []).map((s) => ({ approverId: s.approverId, at: toMs(s.at) }))
  );
  const [published, setPublished] = useState(false);
  const [arrivingId, setArrivingId] = useState<string | null>(null);
  const [announce, setAnnounce] = useState("");
  const arriveTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const prevSignedCount = useRef(signatures.length);
  const prevPublished = useRef(false);

  useEffect(() => () => clearTimeout(arriveTimer.current), []);

  const quorumN = useMemo(() => {
    const total = approvers.length || 1;
    const raw = quorum ?? total;
    return Math.min(total, Math.max(1, raw));
  }, [quorum, approvers.length]);

  const signedMap = useMemo(() => {
    const m = new Map<string, number>();
    for (const s of signatures) m.set(s.approverId, s.at);
    return m;
  }, [signatures]);

  // Out-of-turn is derived from final state alone: approver i is out of turn
  // if some earlier-routed approver j<i is still unsigned, or signed later
  // than i did. Row 0 can never be out of turn — there is no one earlier to
  // have skipped ahead of.
  const outOfTurn = useMemo(() => {
    const flags = new Array<boolean>(approvers.length).fill(false);
    for (let i = 0; i < approvers.length; i++) {
      const at = signedMap.get(approvers[i].id);
      if (at === undefined) continue;
      for (let j = 0; j < i; j++) {
        const otherAt = signedMap.get(approvers[j].id);
        if (otherAt === undefined || otherAt > at) {
          flags[i] = true;
          break;
        }
      }
    }
    return flags;
  }, [approvers, signedMap]);

  const nextIndex = useMemo(
    () => approvers.findIndex((a) => !signedMap.has(a.id)),
    [approvers, signedMap]
  );
  const nextApprover = nextIndex >= 0 ? approvers[nextIndex] : null;

  const signedCount = signatures.length;
  const quorumMet = signedCount >= quorumN;
  const total = approvers.length;

  // Announce only on genuine transitions (new sign / publish), never on the
  // initial seeded mount — matches due-slip's newcomer-only announce pattern.
  useEffect(() => {
    if (signedCount > prevSignedCount.current) {
      const msg = nextApprover
        ? `${signedCount} of ${total} signed; waiting on ${nextApprover.role}.`
        : `${signedCount} of ${total} signed; all signed.`;
      setAnnounce(quorumMet ? `${msg} Publish unlocked.` : msg);
    }
    prevSignedCount.current = signedCount;
  }, [signedCount, total, nextApprover, quorumMet]);

  useEffect(() => {
    if (published && !prevPublished.current) setAnnounce("Published.");
    prevPublished.current = published;
  }, [published]);

  function handleSign() {
    if (!currentApproverId || published) return;
    if (signedMap.has(currentApproverId)) return;
    const at = Date.now();
    setSignatures((prev) => [...prev, { approverId: currentApproverId, at }]);
    onSign?.(currentApproverId, at);
    if (!reducedMotion) {
      setArrivingId(currentApproverId);
      clearTimeout(arriveTimer.current);
      arriveTimer.current = setTimeout(() => setArrivingId(null), CHOP_MS);
    }
  }

  function handlePublish() {
    if (published || !quorumMet) return;
    setPublished(true);
    onPublish?.();
  }

  const remaining = Math.max(0, quorumN - signedCount);
  let reasonText: string;
  if (published) {
    reasonText = "Published.";
  } else if (quorumMet) {
    reasonText = "Quorum met — ready to publish.";
  } else if (nextApprover) {
    reasonText = `Publish disabled — needs ${remaining} more signature${
      remaining === 1 ? "" : "s"
    }, waiting on ${nextApprover.role}.`;
  } else {
    reasonText = "Publish disabled — awaiting signatures.";
  }

  const publishDisabled = !quorumMet || published;

  return (
    <div className={`w-full max-w-xl rounded-md border border-border bg-background ${className}`}>
      <style>{CSS}</style>
      <span role="status" aria-live="polite" aria-atomic="true" className="sr-only">
        {announce}
      </span>

      <div className="flex items-center justify-between gap-3 border-b border-border px-4 py-3">
        <div className="min-w-0">
          <p className="truncate text-sm font-medium text-foreground">{docLabel}</p>
          <p className="font-mono text-[11px] text-ns-muted">
            Quorum {quorumN} of {total}
          </p>
        </div>
        <p className="shrink-0 font-mono text-xs tabular-nums text-ns-muted">
          {signedCount} of {total} signed
        </p>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full border-collapse text-sm">
          <caption id={captionId} className="sr-only">
            Approver routing slip for {docLabel}, in routed order
          </caption>
          <thead>
            <tr className="border-b border-border">
              <th scope="col" className="px-4 py-2 text-left font-mono text-[10px] uppercase tracking-wide text-ns-muted">
                Approver
              </th>
              <th scope="col" className="px-3 py-2 text-left font-mono text-[10px] uppercase tracking-wide text-ns-muted">
                Role
              </th>
              <th scope="col" className="px-3 py-2 text-left font-mono text-[10px] uppercase tracking-wide text-ns-muted">
                Status
              </th>
              <th scope="col" className="px-4 py-2 text-right font-mono text-[10px] uppercase tracking-wide text-ns-muted">
                Time
              </th>
            </tr>
          </thead>
          <tbody>
            {approvers.map((a, i) => {
              const at = signedMap.get(a.id);
              const isSigned = at !== undefined;
              const isNext = !isSigned && i === nextIndex;
              const isOutOfTurn = isSigned && outOfTurn[i];
              const showSign = a.id === currentApproverId && !isSigned && !published;
              const arriving = arrivingId === a.id;

              return (
                <tr key={a.id} className="border-b border-border last:border-b-0">
                  <td className="px-4 py-3 align-top">
                    <div className="flex items-center gap-2.5">
                      <span className="text-foreground">{a.name}</span>
                      <span
                        aria-hidden="true"
                        className="ns-rs-box"
                        data-signed={isSigned || undefined}
                        data-out-of-turn={isOutOfTurn || undefined}
                        data-arriving={arriving || undefined}
                      >
                        {isSigned ? initialsOf(a.name) : null}
                      </span>
                    </div>
                    {isOutOfTurn && (
                      <p
                        data-slip-out-of-turn
                        className="mt-1 font-mono text-[10px] uppercase tracking-wide text-ns-muted"
                      >
                        out of turn
                      </p>
                    )}
                  </td>
                  <td className="px-3 py-3 align-top text-ns-muted">{a.role}</td>
                  <td className="px-3 py-3 align-top">
                    {isSigned ? (
                      <span className="font-mono text-xs text-foreground">Signed</span>
                    ) : showSign ? (
                      <button
                        type="button"
                        data-slip-sign
                        onClick={handleSign}
                        className="ns-rs-btn"
                      >
                        Sign as {a.name}
                      </button>
                    ) : isNext ? (
                      <span className="ns-rs-now">Now</span>
                    ) : (
                      <span className="font-mono text-xs text-ns-muted">Awaiting</span>
                    )}
                  </td>
                  <td className="px-4 py-3 align-top text-right">
                    {isSigned ? (
                      <time
                        dateTime={new Date(at as number).toISOString()}
                        suppressHydrationWarning
                        className="font-mono text-xs tabular-nums text-ns-muted"
                      >
                        <TimeStamp ts={at as number} />
                      </time>
                    ) : (
                      <span aria-hidden="true" className="font-mono text-xs text-ns-muted">
                        —
                      </span>
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <div className="border-t border-border px-4 py-3">
        <button
          type="button"
          data-slip-publish
          aria-disabled={publishDisabled}
          aria-describedby={reasonId}
          data-disabled={publishDisabled || undefined}
          onClick={handlePublish}
          className="ns-rs-btn w-full py-2 text-xs uppercase tracking-wide"
        >
          {published ? "Published" : "Publish"}
        </button>
        <p id={reasonId} className="mt-2 font-mono text-[11px] text-ns-muted">
          {reasonText}
        </p>
      </div>
    </div>
  );
}

const CSS = `
.ns-rs-box{
  position: relative;
  display: inline-flex;
  min-width: 42px;
  height: 26px;
  align-items: center;
  justify-content: center;
  padding: 0 6px;
  border: 1px dashed var(--border);
  border-radius: 6px;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--foreground);
  transform-origin: center;
}
.ns-rs-box[data-signed]{
  border-style: solid;
  border-color: var(--foreground);
  transform: rotate(3deg);
}
.ns-rs-box[data-out-of-turn]{
  transform: rotate(2deg) skewX(8deg);
}
.ns-rs-box[data-arriving]{
  animation: ns-rs-chop-in ${CHOP_MS}ms cubic-bezier(0.16,1,0.3,1) both;
}
.ns-rs-box[data-arriving][data-out-of-turn]{
  animation-name: ns-rs-chop-in-skew;
}
@keyframes ns-rs-chop-in{
  from{ transform: scale(1.15) rotate(0deg); opacity: 0.45; }
  to{ transform: scale(1) rotate(3deg); opacity: 1; }
}
@keyframes ns-rs-chop-in-skew{
  from{ transform: scale(1.15) rotate(0deg) skewX(0deg); opacity: 0.45; }
  to{ transform: scale(1) rotate(2deg) skewX(8deg); opacity: 1; }
}

.ns-rs-now{
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--foreground);
  padding-bottom: 3px;
  background-image: repeating-linear-gradient(90deg, var(--foreground) 0 5px, transparent 5px 10px);
  background-position: 0 100%;
  background-repeat: repeat-x;
  background-size: 20px 1px;
  animation: ns-rs-crawl 900ms linear infinite;
}
@keyframes ns-rs-crawl{
  to{ background-position: -20px 100%; }
}

.ns-rs-btn{
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-mono);
  font-size: 11px;
  padding: 4px 10px;
  cursor: pointer;
  transition: background-color 150ms ease-out, border-color 150ms ease-out;
}
.ns-rs-btn:hover{
  border-color: var(--ns-accent);
  background: color-mix(in srgb, var(--ns-accent) 10%, var(--background));
}
.ns-rs-btn:active{
  background: color-mix(in srgb, var(--ns-accent) 18%, var(--background));
}
.ns-rs-btn:focus-visible{
  outline: 2px solid var(--ns-accent);
  outline-offset: 2px;
}
.ns-rs-btn[data-disabled="true"]{
  color: var(--ns-muted);
  cursor: not-allowed;
}
.ns-rs-btn[data-disabled="true"]:hover,
.ns-rs-btn[data-disabled="true"]:active{
  border-color: var(--border);
  background: var(--background);
}
.ns-rs-btn[data-disabled="true"]:focus-visible{
  outline: 2px solid var(--foreground);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce){
  .ns-rs-box[data-arriving]{ animation: none; }
  .ns-rs-now{ animation: none; }
  .ns-rs-btn{ transition: none; }
}
`;

"use client";

import { useEffect, useId, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// RunningBelay — a deploy pipeline drawn as a climbing pitch. Stages are
// protection anchors bolted along a vertical SVG line; the current deploy is
// the climber-end of a rope clipped through every passed anchor. The segment
// between the last clipped anchor and the leader bows with a quadratic
// bezier control offset of `headroom * 24px` (24px at 96px stage spacing
// reads as slack; the same offset never exceeds 28px, past which the curve
// would cross its own anchor line and stop reading as clipped through) — so
// headroom approaching 0 pulls the rope visibly taut before an automated
// abort fires. Advancement is a linear climb on ease-out-expo; passing an
// anchor clips through with a one-frame carabiner-ring flash, no per-stage
// celebration. ARREST (fall arrest / rollback) is computed only as the
// greatest passed anchor and is a single translate of the leader there, with
// one overshoot-and-settle spring on the leader — never a stage-by-stage
// reverse walk, because a rollback is not a tidy reverse deploy and
// animating it as one teaches a false mental model. The catch itself also
// draws a second, dashed rope segment pinned taut (the same 28px hard-capped
// bow as the live rope) between the target anchor and where the leader fell
// from, fading out over the spring's own duration as it settles — the rope
// visibly taking the load, not just a dot relocating. Pure DOM + SVG + CSS,
// every ink a token, no canvas.
// ---------------------------------------------------------------------------

export type BelayStageStatus = "pending" | "active" | "passed" | "failed";

export interface BelayStage {
  /** stable id, also what onArrest reports back */
  id: string;
  /** short stage name, e.g. "build", "canary", "10%" */
  label: string;
  status: BelayStageStatus;
  /** shown next to the stage and read out in the arrest target description */
  timestamp?: string;
}

export interface RunningBelayProps {
  /** pipeline stages, bottom of the pitch to the top — e.g. build..canary..100% */
  stages: BelayStage[];
  /** 0..1 aggregated canary-health margin; drives how much the live rope bows */
  headroom: number;
  /** fires with the stage id the arrest fell back to */
  onArrest?: (targetStageId: string) => void;
  /** accessible name for the pipeline group */
  ariaLabel?: string;
  className?: string;
}

const SPACING = 96; // px between anchors
const RAIL_W = 40; // px, the SVG rail column
const LINE_X = RAIL_W / 2;
const ANCHOR_R = 5;
const BOW_MAX = 24; // px, at headroom = 1
const BOW_CAP = 28; // px, hard ceiling — past this the curve crosses the line
const CLIMB_MS = 600;
const CLIMB_EASE = "cubic-bezier(0.16,1,0.3,1)"; // ease-out-expo
const SPRING_MS = 700;
const SPRING_EASE = "cubic-bezier(0.34,1.56,0.64,1)"; // overshoot + settle
const CLIP_FLASH_MS = 150;
const ARREST_FLASH_MS = 500;

function clamp(v: number, lo: number, hi: number) {
  return Math.min(hi, Math.max(lo, v));
}

function useReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const on = () => setReduced(mq.matches);
    mq.addEventListener("change", on);
    return () => mq.removeEventListener("change", on);
  }, []);
  return reduced;
}

/** the frontmost stage the deploy is currently at — the active one, or the
 *  furthest passed stage once nothing is active */
function naturalLeaderIndex(stages: BelayStage[]): number {
  const active = stages.findIndex((s) => s.status === "active");
  if (active !== -1) return active;
  let idx = 0;
  stages.forEach((s, i) => {
    if (s.status === "passed") idx = i;
  });
  return idx;
}

/** the arrest target: the greatest passed anchor, full stop. -1 if none. */
function greatestPassedIndex(stages: BelayStage[]): number {
  let idx = -1;
  stages.forEach((s, i) => {
    if (s.status === "passed" && i > idx) idx = i;
  });
  return idx;
}

export function RunningBelay({
  stages,
  headroom,
  onArrest,
  ariaLabel = "Deploy pipeline",
  className = "",
}: RunningBelayProps) {
  const uid = useId();
  const reduced = useReducedMotion();
  const n = stages.length;
  const totalH = Math.max(1, n) * SPACING;

  const natural = naturalLeaderIndex(stages);
  const lastPassed = greatestPassedIndex(stages);

  // arrestedIdx is a local, optimistic override — released the moment the
  // caller's own stages prop confirms the deploy is actually back there.
  const [arrestedIdx, setArrestedIdx] = useState<number | null>(null);
  const [springOn, setSpringOn] = useState(false);
  const springTimeout = useRef<number | undefined>(undefined);
  // the leader's position the instant BEFORE a fall — kept only for the
  // duration of the spring, so the catch has a rope to show the load on.
  const [fallFromIdx, setFallFromIdx] = useState<number | null>(null);
  const [fallFading, setFallFading] = useState(false);
  const fallFadeFrame = useRef<number | undefined>(undefined);
  const [arrestFlashIdx, setArrestFlashIdx] = useState<number | null>(null);
  const arrestFlashTimeout = useRef<number | undefined>(undefined);
  const [assertiveMsg, setAssertiveMsg] = useState("");

  useEffect(() => {
    if (arrestedIdx !== null && natural === arrestedIdx) setArrestedIdx(null);
  }, [natural, arrestedIdx]);

  const leaderIndex = arrestedIdx ?? natural;

  // polite announcement whenever a stage's own status changes
  const prevStages = useRef(stages);
  const [politeMsg, setPoliteMsg] = useState("");
  useEffect(() => {
    const prev = prevStages.current;
    prevStages.current = stages;
    if (prev === stages) return;
    for (let i = 0; i < stages.length; i++) {
      const p = prev[i];
      const s = stages[i];
      if (p && s && p.status !== s.status) {
        setPoliteMsg(`${s.label} is now ${s.status}${s.timestamp ? `, ${s.timestamp}` : ""}.`);
      }
    }
  }, [stages]);

  // one-frame carabiner-ring flash the instant an anchor newly becomes passed
  const passedSeen = useRef<Set<number>>(new Set());
  const [clipFlashIdx, setClipFlashIdx] = useState<number | null>(null);
  const clipFlashTimeout = useRef<number | undefined>(undefined);
  useEffect(() => {
    const prevSeen = passedSeen.current;
    const nextSeen = new Set<number>();
    let fresh: number | null = null;
    stages.forEach((s, i) => {
      if (s.status === "passed") {
        nextSeen.add(i);
        if (!prevSeen.has(i)) fresh = i;
      }
    });
    passedSeen.current = nextSeen;
    if (fresh !== null && !reduced) {
      setClipFlashIdx(fresh);
      window.clearTimeout(clipFlashTimeout.current);
      clipFlashTimeout.current = window.setTimeout(() => setClipFlashIdx(null), CLIP_FLASH_MS);
    }
  }, [stages, reduced]);

  useEffect(
    () => () => {
      window.clearTimeout(springTimeout.current);
      window.clearTimeout(arrestFlashTimeout.current);
      window.clearTimeout(clipFlashTimeout.current);
      window.cancelAnimationFrame(fallFadeFrame.current ?? -1);
    },
    []
  );

  const targetStage = lastPassed >= 0 ? stages[lastPassed] : null;

  function handleArrest() {
    if (lastPassed < 0 || !targetStage) return;
    const fellFrom = reduced ? null : leaderIndex;
    setFallFromIdx(fellFrom);
    setFallFading(false);
    window.cancelAnimationFrame(fallFadeFrame.current ?? -1);
    if (fellFrom !== null) {
      // mount the taut catch-rope at full opacity, then flip to the CSS
      // transition target on the next frame so it fades out OVER the
      // spring's duration rather than vanishing with it.
      fallFadeFrame.current = window.requestAnimationFrame(() => setFallFading(true));
    }
    setArrestedIdx(lastPassed);
    setSpringOn(true);
    window.clearTimeout(springTimeout.current);
    springTimeout.current = window.setTimeout(() => {
      setSpringOn(false);
      setFallFromIdx(null);
      setFallFading(false);
    }, SPRING_MS);
    setArrestFlashIdx(lastPassed);
    window.clearTimeout(arrestFlashTimeout.current);
    arrestFlashTimeout.current = window.setTimeout(() => setArrestFlashIdx(null), ARREST_FLASH_MS);
    setAssertiveMsg(
      `Arrested. Rolled back to ${targetStage.label} cohort, deployed ${targetStage.timestamp ?? "unknown time"}.`
    );
    onArrest?.(targetStage.id);
  }

  const describeId = `${uid}-target`;
  const targetDesc =
    lastPassed < 0 || !targetStage
      ? "No healthy checkpoint recorded yet — arrest has nothing to fall back to."
      : `Rolls back to ${targetStage.label} cohort, deployed ${targetStage.timestamp ?? "unknown time"}.`;

  const yFor = (i: number) => i * SPACING + SPACING / 2;

  const solidSegments: Array<{ y0: number; y1: number }> = [];
  for (let i = 0; i < n - 1; i++) {
    if (stages[i]?.status === "passed" && stages[i + 1]?.status === "passed") {
      solidSegments.push({ y0: yFor(i), y1: yFor(i + 1) });
    }
  }

  const showLive = lastPassed >= 0 && leaderIndex > lastPassed;
  const bowOffset = reduced ? 0 : clamp(clamp(headroom, 0, 1) * BOW_MAX, 0, BOW_CAP);
  const liveY0 = lastPassed >= 0 ? yFor(lastPassed) : 0;
  const liveY1 = yFor(leaderIndex);
  const liveMidY = (liveY0 + liveY1) / 2;
  const liveD = `M ${LINE_X} ${liveY0} Q ${LINE_X + bowOffset} ${liveMidY} ${LINE_X} ${liveY1}`;

  // the catch-rope: only exists for the SPRING_MS of an arrest, pinned
  // between the target anchor and where the leader fell from, bowed to the
  // same hard-capped 28px — the rope taking the full load, then fading as
  // it settles. Never drawn under reduced motion (fallFromIdx stays null).
  const fallD =
    fallFromIdx !== null && fallFromIdx > lastPassed
      ? (() => {
          const y0 = yFor(lastPassed);
          const y1 = yFor(fallFromIdx);
          const midY = (y0 + y1) / 2;
          return `M ${LINE_X} ${y0} Q ${LINE_X + BOW_CAP} ${midY} ${LINE_X} ${y1}`;
        })()
      : null;

  const leaderTransition = reduced
    ? "none"
    : `transform ${springOn ? SPRING_MS : CLIMB_MS}ms ${springOn ? SPRING_EASE : CLIMB_EASE}`;

  return (
    <div
      className={className}
      role="group"
      aria-label={ariaLabel}
      data-belay-state={arrestedIdx !== null ? "arrested" : "armed"}
    >
      <style>{`
@media (prefers-reduced-motion: reduce){
  .ns-rb-leader{transition:none !important}
  .ns-rb-clip{transition:none !important}
}
`}</style>

      <div className="relative w-full">
        <svg
          aria-hidden="true"
          className="pointer-events-none absolute left-0 top-0"
          width={RAIL_W}
          height={totalH}
          viewBox={`0 0 ${RAIL_W} ${totalH}`}
        >
          {/* the permanent conduit — always fully visible */}
          <line x1={LINE_X} y1={yFor(0)} x2={LINE_X} y2={yFor(Math.max(0, n - 1))} stroke="var(--border)" strokeWidth={1} />

          {solidSegments.map((seg, i) => (
            <line
              key={i}
              x1={LINE_X}
              y1={seg.y0}
              x2={LINE_X}
              y2={seg.y1}
              stroke="var(--foreground)"
              strokeWidth={1.5}
            />
          ))}

          {showLive && (
            <path d={liveD} fill="none" stroke="var(--foreground)" strokeOpacity={0.65} strokeWidth={1.5} />
          )}

          {fallD && (
            <path
              d={fallD}
              fill="none"
              stroke="var(--foreground)"
              strokeWidth={1.5}
              strokeDasharray="2 3"
              style={{
                opacity: fallFading ? 0 : 0.9,
                transition: reduced ? "none" : `opacity ${SPRING_MS}ms ease-out`,
              }}
            />
          )}

          {stages.map((s, i) => {
            const y = yFor(i);
            const passed = s.status === "passed";
            const failed = s.status === "failed";
            const isActiveAnchor = i === natural && s.status === "active";
            const clipping = clipFlashIdx === i;
            const flashing = arrestFlashIdx === i;
            return (
              <g key={s.id} transform={`translate(${LINE_X}, ${y})`}>
                {failed ? (
                  <>
                    <line x1={-ANCHOR_R} y1={-ANCHOR_R} x2={ANCHOR_R} y2={ANCHOR_R} stroke="var(--foreground)" strokeWidth={1.5} />
                    <line x1={-ANCHOR_R} y1={ANCHOR_R} x2={ANCHOR_R} y2={-ANCHOR_R} stroke="var(--foreground)" strokeWidth={1.5} />
                  </>
                ) : isActiveAnchor ? (
                  <circle r={ANCHOR_R} fill="none" stroke="var(--foreground)" strokeWidth={1.5} />
                ) : (
                  <circle r={ANCHOR_R} fill={passed ? "var(--foreground)" : "var(--border)"} />
                )}
                {passed && (
                  <ellipse
                    className="ns-rb-clip"
                    cx={0}
                    cy={0}
                    rx={ANCHOR_R + 4}
                    ry={ANCHOR_R + 2}
                    fill="none"
                    stroke="var(--foreground)"
                    strokeWidth={1}
                    opacity={clipping ? 1 : 0.5}
                    style={{ transition: reduced ? "none" : "opacity 140ms ease-out" }}
                  />
                )}
                {flashing && (
                  <circle r={ANCHOR_R + 6} fill="none" stroke="var(--foreground)" strokeWidth={1} opacity={0.85} />
                )}
              </g>
            );
          })}

          <g
            className="ns-rb-leader"
            style={{
              transform: `translate(${LINE_X}px, ${yFor(leaderIndex)}px)`,
              transition: leaderTransition,
            }}
          >
            <circle r={6} fill="var(--background)" stroke="var(--foreground)" strokeWidth={2} />
            <circle r={2} fill="var(--foreground)" />
          </g>
        </svg>

        <ol className="relative m-0 list-none p-0" style={{ paddingLeft: RAIL_W + 16 }}>
          {stages.map((s, i) => {
            const isCurrent = i === leaderIndex;
            return (
              <li
                key={s.id}
                aria-current={isCurrent ? "step" : undefined}
                className="flex flex-col justify-center gap-0.5"
                style={{ height: SPACING }}
              >
                <span className="font-sans text-sm text-foreground">{s.label}</span>
                <span className="font-mono text-[11px] text-ns-muted">
                  {s.status}
                  {s.timestamp ? ` · ${s.timestamp}` : ""}
                </span>
              </li>
            );
          })}
        </ol>
      </div>

      <div className="mt-4 flex items-center justify-between gap-3 border-t border-border pt-3">
        <p className="font-mono text-[11px] text-ns-muted">
          headroom {Math.round(clamp(headroom, 0, 1) * 100)}%
        </p>
        <button
          type="button"
          data-belay-arrest
          disabled={lastPassed < 0}
          aria-describedby={describeId}
          onClick={handleArrest}
          className="rounded-[6px] border border-border px-3 py-1.5 font-mono text-xs text-foreground transition-colors hover:border-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent disabled:pointer-events-none disabled:opacity-40"
        >
          Arrest rollout
        </button>
      </div>
      <span id={describeId} className="sr-only">
        {targetDesc}
      </span>

      <p aria-live="polite" className="sr-only">
        {politeMsg}
      </p>
      <p aria-live="assertive" className="sr-only">
        {assertiveMsg}
      </p>
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";

// ---------------------------------------------------------------------------
// AsciiSankeyFlow — a weighted, branching multi-stage flow diagram where the
// connecting bands are rendered as ASCII density ramp (" .:-=+*#%@") rather
// than colour, and node height is proportional to its own throughput. THE
// mechanic that separates this from a picture: clicking a node ISOLATES it —
// every ancestor (any node with a path leading into it) and every descendant
// (any node reachable from it) stays, everything else disappears — and the
// remaining nodes/bands don't just get left at their old size with everyone
// else dimmed: each surviving stage re-stacks from scratch using ONLY the
// isolated subset's values, so the visible nodes and bands genuinely GROW to
// fill the same vertical space the full graph used to occupy. Undoing the
// isolation (Escape, or the "Show all" control) re-expands back to the full
// graph. Pure DOM text + CSS, zero dependencies.
// ---------------------------------------------------------------------------

export interface SankeyNode {
  id: string;
  label: string;
  stage: number;
  value: number;
}

export interface SankeyLink {
  from: string;
  to: string;
  value: number;
}

export interface AsciiSankeyFlowProps {
  /** the diagram's nodes */
  nodes?: SankeyNode[];
  /** the flows between nodes */
  links?: SankeyLink[];
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const ASCII_RAMP = " .:-=+*#%@";

const STAGE_COUNT = 3;
const NODE_W = 3;
const BAND_W = 10;
const ROWS_STAGE = 16;
const CELL_W = 12;
const CELL_H = 15;
const TOP_PAD = 1;
const COLS = STAGE_COUNT * NODE_W + (STAGE_COUNT - 1) * BAND_W + 2;
const ROWS = ROWS_STAGE + TOP_PAD + 1;

const DEFAULT_NODES: SankeyNode[] = [
  { id: "search", label: "Search", stage: 0, value: 100 },
  { id: "social", label: "Social", stage: 0, value: 60 },
  { id: "referral", label: "Referral", stage: 0, value: 40 },
  { id: "onboarded", label: "Onboarded", stage: 1, value: 125 },
  { id: "bounced", label: "Bounced", stage: 1, value: 75 },
  { id: "converted", label: "Converted", stage: 2, value: 100 },
  { id: "churned", label: "Churned", stage: 2, value: 100 },
];

const DEFAULT_LINKS: SankeyLink[] = [
  { from: "search", to: "onboarded", value: 70 },
  { from: "search", to: "bounced", value: 30 },
  { from: "social", to: "onboarded", value: 30 },
  { from: "social", to: "bounced", value: 30 },
  { from: "referral", to: "onboarded", value: 25 },
  { from: "referral", to: "bounced", value: 15 },
  { from: "onboarded", to: "converted", value: 90 },
  { from: "onboarded", to: "churned", value: 35 },
  { from: "bounced", to: "converted", value: 10 },
  { from: "bounced", to: "churned", value: 65 },
];

interface Span {
  top: number;
  bottom: number;
}

// Cumulative-rounded 1D stacking — same technique as treemap-ascii-partition's
// layoutSlice, collapsed to one axis: every boundary derives from the running
// total so far, so adjacent spans always share an exact edge.
function stackSpans<T extends { value: number }>(items: T[], top: number, bottom: number): Span[] {
  const total = items.reduce((s, i) => s + Math.max(0, i.value), 0) || 1;
  const height = bottom - top;
  let acc = 0;
  let cursor = top;
  return items.map((item) => {
    acc += Math.max(0, item.value);
    const next = top + Math.round((acc / total) * height);
    const span = { top: cursor, bottom: Math.max(cursor + 1, next) };
    cursor = span.bottom;
    return span;
  });
}

function stageCol(stage: number): number {
  return 1 + stage * (NODE_W + BAND_W);
}

// This used to read --foreground/--background/etc via getComputedStyle at
// mount, hold them in state, and apply the result as raw hex through inline
// `style` — a real bug, not a style choice, see diagram-ascii-flow's
// component.tsx for the full story. Short version: SSR always renders with
// no `document`, so the FIRST markup bakes in the light-theme fallback hex,
// and because the client-computed value never CHANGES across renders (this
// component recomputes the same "correct" dark hex every time), React never
// patches it into the DOM — it only writes an attribute when the new
// render's value differs from the PREVIOUS render's, not from what's
// actually painted. Confirmed live here too: on a fresh load with dark mode
// already saved (the anti-flash script sets `.dark` on `<html>` before
// hydration), every node rendered background rgb(255,255,255) against a
// rgb(10,10,10) page. Tailwind classes bound to the same custom properties
// sidestep the whole bug class: the cascade resolves --background per theme
// at PAINT time, no JS or hydration step involved.

// Every node reachable from `id` by walking edges backward (ancestors) or
// forward (descendants) — the "isolate" set is {id} union both directions,
// which is what makes it a real subgraph isolation rather than a 1-hop
// highlight.
function reachable(id: string, links: SankeyLink[], direction: "forward" | "backward"): Set<string> {
  const out = new Set<string>();
  const frontier = [id];
  while (frontier.length) {
    const cur = frontier.pop()!;
    for (const link of links) {
      const next = direction === "forward" ? (link.from === cur ? link.to : null) : link.to === cur ? link.from : null;
      if (next && !out.has(next)) {
        out.add(next);
        frontier.push(next);
      }
    }
  }
  return out;
}

export function AsciiSankeyFlow({
  nodes = DEFAULT_NODES,
  links = DEFAULT_LINKS,
  className = "",
}: AsciiSankeyFlowProps) {
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [hoverId, setHoverId] = useState<string | null>(null);

  const isolatedIds = useMemo(() => {
    if (!selectedId) return null;
    const ancestors = reachable(selectedId, links, "backward");
    const descendants = reachable(selectedId, links, "forward");
    return new Set<string>([selectedId, ...ancestors, ...descendants]);
  }, [selectedId, links]);

  const visibleNodes = useMemo(
    () => (isolatedIds ? nodes.filter((n) => isolatedIds.has(n.id)) : nodes),
    [nodes, isolatedIds]
  );
  const visibleLinks = useMemo(
    () =>
      isolatedIds ? links.filter((l) => isolatedIds.has(l.from) && isolatedIds.has(l.to)) : links,
    [links, isolatedIds]
  );

  // per-stage vertical spans, restacked from ONLY the currently visible
  // nodes' values — this is the re-weight: an isolated subset's nodes claim
  // the full ROWS_STAGE height among just themselves, not a subset of the
  // full graph's original spans.
  const nodeSpan = useMemo(() => {
    const map = new Map<string, Span>();
    for (let stage = 0; stage < STAGE_COUNT; stage++) {
      const stageNodes = visibleNodes.filter((n) => n.stage === stage);
      const spans = stackSpans(stageNodes, TOP_PAD, TOP_PAD + ROWS_STAGE);
      stageNodes.forEach((n, i) => map.set(n.id, spans[i]));
    }
    return map;
  }, [visibleNodes]);

  // per-node, per-link sub-spans (outgoing sub-spans partition the node's
  // own span for bands leaving it; incoming sub-spans partition it for bands
  // arriving) — same cumulative stacking, one level down.
  const linkSpan = useMemo(() => {
    const outMap = new Map<string, Span>(); // keyed by `${link.from}->${link.to}`
    const inMap = new Map<string, Span>();
    for (const node of visibleNodes) {
      const outgoing = visibleLinks.filter((l) => l.from === node.id);
      const incoming = visibleLinks.filter((l) => l.to === node.id);
      const span = nodeSpan.get(node.id);
      if (!span) continue;
      const outSpans = stackSpans(outgoing, span.top, span.bottom);
      outgoing.forEach((l, i) => outMap.set(`${l.from}->${l.to}`, outSpans[i]));
      const inSpans = stackSpans(incoming, span.top, span.bottom);
      incoming.forEach((l, i) => inMap.set(`${l.from}->${l.to}`, inSpans[i]));
    }
    return { outMap, inMap };
  }, [visibleNodes, visibleLinks, nodeSpan]);

  const maxLinkValue = useMemo(() => Math.max(1, ...visibleLinks.map((l) => l.value)), [visibleLinks]);

  const rows = useMemo(() => {
    const cells: string[][] = Array.from({ length: ROWS }, () => Array(COLS).fill(" "));
    for (const link of visibleLinks) {
      const srcNode = visibleNodes.find((n) => n.id === link.from);
      const dstNode = visibleNodes.find((n) => n.id === link.to);
      if (!srcNode || !dstNode) continue;
      const srcSpan = linkSpan.outMap.get(`${link.from}->${link.to}`);
      const dstSpan = linkSpan.inMap.get(`${link.from}->${link.to}`);
      if (!srcSpan || !dstSpan) continue;
      const srcRight = stageCol(srcNode.stage) + NODE_W;
      const dstLeft = stageCol(dstNode.stage) - 1;
      const level = Math.max(1, Math.round((link.value / maxLinkValue) * (ASCII_RAMP.length - 1)));
      const ch = ASCII_RAMP[level];
      for (let x = srcRight; x <= dstLeft; x++) {
        const t = dstLeft > srcRight ? (x - srcRight) / (dstLeft - srcRight) : 0;
        const top = srcSpan.top + (dstSpan.top - srcSpan.top) * t;
        const bottom = srcSpan.bottom + (dstSpan.bottom - srcSpan.bottom) * t;
        for (let y = Math.round(top); y < Math.round(bottom); y++) {
          if (y >= 0 && y < ROWS && x >= 0 && x < COLS) cells[y][x] = ch;
        }
      }
    }
    return cells.map((r) => r.join(""));
  }, [visibleLinks, visibleNodes, linkSpan, maxLinkValue]);

  const connectionsCount = (id: string) => links.filter((l) => l.from === id || l.to === id).length;

  return (
    <div className={`ns-saf font-mono ${className}`}>
      <style>{CSS}</style>

      <div className="relative" style={{ width: COLS * CELL_W, height: ROWS * CELL_H, maxWidth: "100%" }}>
        {/* Each character is its own fixed-width span rather than one flowing
            text string per row: a browser's real monospace glyph advance
            almost never equals CELL_W exactly, and the bands must land on
            the SAME px grid the absolutely-positioned node buttons use — a
            flowing string drifts column alignment cumulatively across the
            row until bands land under the wrong node entirely. */}
        <div
          aria-hidden
          className="pointer-events-none absolute inset-0 text-ns-muted"
          style={{ fontSize: 10 }}
        >
          {rows.map((line, y) => (
            <div key={y} style={{ height: CELL_H, lineHeight: `${CELL_H}px`, whiteSpace: "nowrap" }}>
              {line.split("").map((ch, x) => (
                <span key={x} style={{ display: "inline-block", width: CELL_W, textAlign: "center" }}>
                  {ch}
                </span>
              ))}
            </div>
          ))}
        </div>

        {visibleNodes.map((n) => {
          const span = nodeSpan.get(n.id);
          if (!span) return null;
          const selected = selectedId === n.id;
          const hovered = hoverId === n.id;
          const col = stageCol(n.stage);
          return (
            <button
              key={n.id}
              type="button"
              data-sankey-node={n.id}
              aria-pressed={selected}
              aria-label={`${n.label}: ${n.value.toLocaleString()}, ${connectionsCount(n.id)} connection${
                connectionsCount(n.id) === 1 ? "" : "s"
              }. Press Enter to isolate its upstream and downstream flow.`}
              className={`ns-saf-node absolute overflow-hidden border bg-background text-left text-[10px] transition-colors duration-150 motion-reduce:transition-none ${
                selected
                  ? "border-ns-accent text-foreground"
                  : hovered
                    ? "border-ns-accent/40 text-foreground"
                    : "border-border text-ns-muted"
              }`}
              style={{
                left: col * CELL_W,
                top: span.top * CELL_H,
                width: NODE_W * CELL_W,
                height: (span.bottom - span.top) * CELL_H,
              }}
              onPointerEnter={() => setHoverId(n.id)}
              onPointerLeave={() => setHoverId((c) => (c === n.id ? null : c))}
              onClick={() => setSelectedId(n.id)}
              onKeyDown={(e) => {
                if (e.key === "Escape") setSelectedId(null);
              }}
            >
              <span className="block truncate px-1 pt-0.5">{n.label}</span>
              <span className="block px-1 text-ns-muted">{n.value}</span>
            </button>
          );
        })}
      </div>

      <div className="mt-3 min-h-[1.5em] font-mono text-xs text-ns-muted">
        {selectedId ? (
          <span data-sankey-isolated className="inline-flex items-center gap-2">
            Isolated: <strong className="text-foreground">{nodes.find((n) => n.id === selectedId)?.label}</strong> —{" "}
            {visibleNodes.length} of {nodes.length} nodes
            <button
              type="button"
              onClick={() => setSelectedId(null)}
              className="ns-saf-clear rounded-sm border border-border px-1.5 py-0.5 text-[10px] text-ns-muted transition-colors duration-150 motion-reduce:transition-none hover:text-foreground"
            >
              Show all
            </button>
          </span>
        ) : (
          <span>Click a node to isolate its upstream and downstream flow.</span>
        )}
      </div>
    </div>
  );
}

const CSS = `
.ns-saf-node:focus-visible { outline: 2px solid var(--ns-accent); outline-offset: 2px; }
.ns-saf-clear:focus-visible { outline: 2px solid var(--ns-accent); outline-offset: 2px; }
`;

"use client";

import { useCallback, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// ScheduleAsciiFreebusy — a meeting-time finder that shows its own work.
//
// One row of block glyphs per attendee over 18 half-hour slots (09:00–18:00)
// and an underlined accent window marking the earliest slot where everyone
// required is actually free. The solver is a bitwise AND of the required
// attendees' inverted busy masks followed by a single left-to-right
// run-length scan — dropping one person to optional removes their mask from
// the AND and the answer visibly moves, which is the whole argument of the
// component.
//
// Status is glyph-encoded, never color-encoded: free ·, tentative ▒, busy █,
// outside working hours blank. Pure DOM + tokens: no canvas, no rAF loop.
// ---------------------------------------------------------------------------

export type SlotStatus = "free" | "tentative" | "busy" | "out";

export interface Attendee {
  /** stable lowercase id, also used for [data-attendee-toggle] */
  id: string;
  name: string;
  /** one status per slot; length must equal `slots` */
  day: SlotStatus[];
}

export interface ScheduleAsciiFreebusyProps {
  /** attendees and their free/busy blocks, rendered as one row each */
  attendees: Attendee[];
  /** number of half-hour columns (default 18 = 09:00–18:00) */
  slots?: number;
  /** minutes at the first column (default 540 = 09:00) */
  dayStartMinutes?: number;
  /** initial meeting length in minutes; must be one of `durations` */
  defaultDuration?: number;
  /** offered meeting-length options, in minutes */
  durations?: number[];
  /** heading above the grid */
  title?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const GLYPH: Record<SlotStatus, string> = {
  free: "·",
  tentative: "▒",
  busy: "█",
  out: " ",
};

// Resting ink. NOT `text-border` — --border is tuned for 1px hairlines and is
// invisible as type on the light theme (#ebebeb on #fafafa), which would leave
// the free cells and the rule blank at rest. Muted tints read in both themes
// and still sit below the busy blocks in the hierarchy.
const FREE_INK = "text-ns-muted/50";
const RULE_INK = "text-ns-muted/55";
const OPTIONAL_INK = "text-ns-muted/30";

const GLYPH_CLASS: Record<SlotStatus, string> = {
  free: FREE_INK,
  tentative: "text-ns-muted",
  busy: "text-foreground",
  out: FREE_INK,
};

const STATUS_WORD: Record<SlotStatus, string> = {
  free: "free",
  tentative: "tentative",
  busy: "busy",
  out: "outside working hours",
};

/** busy for solving purposes: a hard conflict or a slot outside working hours */
const isBlocked = (s: SlotStatus) => s === "busy" || s === "out";

function clamp(v: number, lo: number, hi: number) {
  return Math.min(hi, Math.max(lo, v));
}

type Run = { start: number; end: number };

/** every maximal run of set bits in `mask` whose length is at least `min` */
function maximalRuns(mask: boolean[], min: number): Run[] {
  const runs: Run[] = [];
  let start = -1;
  for (let k = 0; k <= mask.length; k++) {
    if (k < mask.length && mask[k]) {
      if (start === -1) start = k;
    } else if (start !== -1) {
      if (k - start >= min) runs.push({ start, end: k - 1 });
      start = -1;
    }
  }
  return runs;
}

export function ScheduleAsciiFreebusy({
  attendees,
  slots = 18,
  dayStartMinutes = 9 * 60,
  defaultDuration = 60,
  durations = [30, 60, 90],
  title = "Design sync — find a time",
  className = "",
}: ScheduleAsciiFreebusyProps) {
  const [duration, setDuration] = useState(defaultDuration);
  const [optional, setOptional] = useState<Record<string, boolean>>({});
  const [hoverCol, setHoverCol] = useState<number | null>(null);
  const [active, setActive] = useState<{ r: number; c: number }>({ r: 0, c: 0 });
  const gridRef = useRef<HTMLDivElement>(null);
  const durationRef = useRef<HTMLDivElement>(null);

  const durationSlots = Math.max(1, Math.round(duration / 30));

  const timeAt = useCallback(
    (k: number) => {
      const m = dayStartMinutes + k * 30;
      const hh = String(Math.floor(m / 60)).padStart(2, "0");
      const mm = String(m % 60).padStart(2, "0");
      return `${hh}:${mm}`;
    },
    [dayStartMinutes]
  );

  const required = useMemo(() => attendees.filter((a) => !optional[a.id]), [attendees, optional]);

  /** freeMask[k] = AND over required attendees of NOT blocked */
  const freeMask = useMemo(() => {
    const mask: boolean[] = [];
    for (let k = 0; k < slots; k++) {
      mask.push(required.length > 0 && required.every((a) => !isBlocked(a.day[k] ?? "out")));
    }
    return mask;
  }, [required, slots]);

  const runs = useMemo(() => maximalRuns(freeMask, durationSlots), [freeMask, durationSlots]);

  /** earliest of the longest qualifying runs */
  const best = useMemo(() => {
    let win: Run | null = null;
    for (const r of runs) {
      const len = r.end - r.start + 1;
      if (!win || len > win.end - win.start + 1) win = r;
    }
    return win;
  }, [runs]);

  /** when nothing qualifies: the window of `durationSlots` with the fewest blocked people */
  const nearMiss = useMemo(() => {
    if (best || required.length === 0) return null;
    let winner: { start: number; names: string[] } | null = null;
    for (let s = 0; s + durationSlots <= slots; s++) {
      const names: string[] = [];
      for (const a of required) {
        for (let k = s; k < s + durationSlots; k++) {
          if (isBlocked(a.day[k] ?? "out")) {
            names.push(a.name);
            break;
          }
        }
      }
      if (!winner || names.length < winner.names.length) winner = { start: s, names };
    }
    return winner;
  }, [best, required, durationSlots, slots]);

  const answer = useMemo(() => {
    if (required.length === 0) return "no one required — pick at least one attendee";
    if (best) {
      const who =
        required.length === attendees.length
          ? `all ${required.length} free`
          : `${required.length} required free`;
      return `${timeAt(best.start)} → ${timeAt(best.end + 1)}   ${who}`;
    }
    if (nearMiss) {
      const names = nearMiss.names.join(", ");
      return `no window — best is ${timeAt(nearMiss.start)} → ${timeAt(nearMiss.start + durationSlots)} with ${names} busy`;
    }
    return "no window";
  }, [required, attendees.length, best, nearMiss, timeAt, durationSlots]);

  const hoverLine = useMemo(() => {
    if (hoverCol === null) return null;
    const blocked = required.filter((a) => isBlocked(a.day[hoverCol] ?? "out"));
    if (required.length === 0) return `${timeAt(hoverCol)} — no one required`;
    if (blocked.length === 0) return `${timeAt(hoverCol)} — everyone free`;
    const names = blocked
      .map((a) => (a.day[hoverCol] === "out" ? `${a.name} (off)` : a.name))
      .join(", ");
    return `${timeAt(hoverCol)} — ${blocked.length} of ${required.length} busy: ${names}`;
  }, [hoverCol, required, timeAt]);

  const restLine = `${runs.length} window${runs.length === 1 ? "" : "s"} ≥ ${duration} min · click a name to drop them to optional`;

  const toggle = (id: string) => setOptional((o) => ({ ...o, [id]: !o[id] }));

  const focusCell = (r: number, c: number) => {
    gridRef.current
      ?.querySelector<HTMLDivElement>(`[data-cell-r="${r}"][data-cell-c="${c}"]`)
      ?.focus();
  };

  const onCellKeyDown = (e: React.KeyboardEvent, r: number, c: number) => {
    if (e.key === "Escape") {
      setHoverCol(null);
      return;
    }
    const map: Record<string, [number, number]> = {
      ArrowUp: [-1, 0],
      ArrowDown: [1, 0],
      ArrowLeft: [0, -1],
      ArrowRight: [0, 1],
    };
    const d = map[e.key];
    if (!d) return;
    e.preventDefault();
    const nr = clamp(r + d[0], 0, attendees.length - 1);
    const nc = clamp(c + d[1], 0, slots - 1);
    setActive({ r: nr, c: nc });
    setHoverCol(nc);
    focusCell(nr, nc);
  };

  /** radiogroup semantics: arrows move the selection and the single tab stop */
  const onDurationKeyDown = (e: React.KeyboardEvent, i: number) => {
    const step =
      e.key === "ArrowRight" || e.key === "ArrowDown"
        ? 1
        : e.key === "ArrowLeft" || e.key === "ArrowUp"
          ? -1
          : 0;
    if (!step) return;
    e.preventDefault();
    const next = durations[(i + step + durations.length) % durations.length];
    if (next === undefined) return;
    setDuration(next);
    durationRef.current
      ?.querySelector<HTMLButtonElement>(`[data-duration="${next}"]`)
      ?.focus();
  };

  const inBest = (k: number) => !!best && k >= best.start && k <= best.end;

  const colTint = (k: number) =>
    hoverCol === k ? "bg-ns-accent/[0.10]" : inBest(k) ? "bg-ns-accent/[0.06]" : "";

  /** underline glyph for a window of `len` columns at offset `i` */
  const underline = (len: number, i: number) => {
    if (len === 1) return "┴";
    if (i === 0) return "└";
    if (i === len - 1) return "┘";
    return "─";
  };

  const runAt = (k: number) => runs.find((r) => k >= r.start && k <= r.end) ?? null;

  const cell = "flex h-[1.35em] items-center justify-center select-none";
  const labelColumn = "7em";
  const cellWidth = "1.5em";

  return (
    <div className={`inline-flex flex-col gap-3 font-mono text-[14px] ${className}`}>
      <div className="flex flex-wrap items-center justify-between gap-4">
        <span className="text-[11px] uppercase tracking-[0.18em] text-ns-muted">{title}</span>
        <div
          ref={durationRef}
          role="radiogroup"
          aria-label="Meeting length"
          className="flex items-center rounded-sm border border-border"
        >
          {durations.map((d, i) => {
            const on = d === duration;
            return (
              <button
                key={d}
                type="button"
                role="radio"
                aria-checked={on}
                data-duration={d}
                tabIndex={on || (!durations.includes(duration) && i === 0) ? 0 : -1}
                onClick={() => setDuration(d)}
                onKeyDown={(e) => onDurationKeyDown(e, i)}
                className={`px-2.5 py-1 text-[11px] tabular-nums outline-none transition-colors duration-150 first:rounded-l-sm last:rounded-r-sm motion-reduce:transition-none focus-visible:ring-2 focus-visible:ring-ns-accent ${
                  on ? "bg-ns-accent/[0.14] text-foreground" : "text-ns-muted hover:text-foreground"
                }`}
              >
                {d} min
              </button>
            );
          })}
        </div>
      </div>

      <div
        ref={gridRef}
        role="grid"
        aria-label={`Attendee availability, ${timeAt(0)} to ${timeAt(slots)} in half-hour slots`}
        aria-colcount={slots + 1}
        onPointerLeave={() => setHoverCol(null)}
        onKeyDown={(e) => {
          if (e.key === "Escape") setHoverCol(null);
        }}
        className="grid rounded-sm border border-border bg-surface px-3 py-2.5"
        style={{ gridTemplateColumns: `${labelColumn} repeat(${slots}, ${cellWidth})` }}
      >
        {/* hour ruler */}
        <div role="row" className="contents">
          <div role="columnheader" aria-colindex={1} className="h-[1.35em]" />
          {Array.from({ length: slots }, (_, k) =>
            k % 2 === 0 ? (
              <div
                key={k}
                role="columnheader"
                aria-colindex={k + 2}
                aria-colspan={Math.min(2, slots - k)}
                style={{ gridColumn: `span ${Math.min(2, slots - k)}` }}
                className="flex h-[1.35em] items-center text-[10px] tabular-nums text-ns-muted"
              >
                {timeAt(k).slice(0, 2)}
              </div>
            ) : null
          )}
        </div>

        {/* one row per attendee */}
        {attendees.map((a, r) => {
          const off = !!optional[a.id];
          return (
            <div key={a.id} role="row" className="contents">
              <div role="rowheader" className="flex h-[1.35em] items-center pr-2">
                <button
                  type="button"
                  data-attendee-toggle={a.id}
                  aria-pressed={!off}
                  aria-label={`${a.name} — ${off ? "optional, excluded from the search" : "required"}. Toggle.`}
                  onClick={() => toggle(a.id)}
                  className={`w-full truncate rounded-[2px] text-left text-[12px] outline-none transition-colors duration-150 motion-reduce:transition-none focus-visible:ring-2 focus-visible:ring-ns-accent ${
                    off ? "text-ns-muted/60 hover:text-ns-muted" : "text-foreground hover:text-ns-accent"
                  }`}
                >
                  {off ? `(${a.name})` : a.name}
                </button>
              </div>
              {Array.from({ length: slots }, (_, k) => {
                const status = a.day[k] ?? "out";
                const isActive = active.r === r && active.c === k;
                const ruled = hoverCol === k && !isBlocked(status);
                return (
                  <div
                    key={k}
                    role="gridcell"
                    data-cell-r={r}
                    data-cell-c={k}
                    tabIndex={isActive ? 0 : -1}
                    aria-selected={!off && inBest(k)}
                    aria-label={`${a.name}, ${timeAt(k)}, ${STATUS_WORD[status]}${off ? ", optional" : ""}`}
                    onPointerEnter={() => setHoverCol(k)}
                    onFocus={() => {
                      setActive({ r, c: k });
                      setHoverCol(k);
                    }}
                    onKeyDown={(e) => onCellKeyDown(e, r, k)}
                    className={`${cell} rounded-[1px] outline-none transition-colors duration-150 motion-reduce:transition-none focus-visible:ring-2 focus-visible:ring-ns-accent ${colTint(k)} ${
                      off ? OPTIONAL_INK : GLYPH_CLASS[status]
                    }`}
                  >
                    {ruled ? "┊" : GLYPH[status]}
                  </div>
                );
              })}
            </div>
          );
        })}

        {/* separator rule */}
        <div role="row" aria-hidden className="contents">
          <div className="h-[1.1em]" />
          {Array.from({ length: slots }, (_, k) => (
            <div key={k} className={`flex h-[1.1em] items-center justify-center ${RULE_INK}`}>
              {k === 0 ? "├" : k === slots - 1 ? "┤" : "─"}
            </div>
          ))}
        </div>

        {/* every qualifying window underlined; the best one in accent */}
        <div role="row" aria-hidden className="contents">
          <div className="h-[1.1em]" />
          {Array.from({ length: slots }, (_, k) => {
            const r = runAt(k);
            const isBest = !!best && !!r && r.start === best.start;
            const len = r ? r.end - r.start + 1 : 0;
            return (
              <div
                key={k}
                className={`flex h-[1.1em] items-center justify-center leading-none ${
                  isBest ? "text-ns-accent" : "text-ns-muted"
                }`}
              >
                {r ? underline(len, k - r.start) : ""}
              </div>
            );
          })}
        </div>

        {/* the answer, seated under its own window */}
        <div role="row" className="contents">
          <div role="rowheader" className="h-[1.35em]" />
          <div
            role="gridcell"
            aria-live="polite"
            style={{ gridColumn: `${(best ? Math.min(best.start, 5) : 0) + 2} / -1` }}
            className={`flex h-[1.35em] items-center whitespace-nowrap text-[12px] tabular-nums ${
              best ? "text-ns-accent" : "text-ns-muted"
            }`}
          >
            {answer}
          </div>
        </div>
      </div>

      {/* readout: hover detail crossfading with the resting hint */}
      <div className="relative h-[1.4em] text-[11px] text-ns-muted">
        <span
          className={`absolute inset-0 flex items-center whitespace-nowrap transition-opacity duration-150 motion-reduce:transition-none ${
            hoverLine ? "opacity-0" : "opacity-100"
          }`}
        >
          {restLine}
        </span>
        <span
          aria-live="polite"
          className={`absolute inset-0 flex items-center whitespace-nowrap tabular-nums text-foreground transition-opacity duration-150 motion-reduce:transition-none ${
            hoverLine ? "opacity-100" : "opacity-0"
          }`}
        >
          {hoverLine ?? ""}
        </span>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import type { CSSProperties } from "react";

// ---------------------------------------------------------------------------
// ScreenFloodStroke — a loader / ambient "something is being produced"
// affordance modelled on the real screen-printing flood/print stroke cycle,
// not a percentage bar. A squeegee makes two passes per cycle across a
// printing mesh: a FLOOD stroke (light pressure, left->right) that spreads
// ink evenly across the mesh weave without forcing it through, then a PRINT
// stroke (firm pressure, blade angled ~18deg from vertical, right->left)
// that forces ink through the mesh openings the blade has already crossed
// and deposits a real impression on the substrate underneath. The two
// passes are deliberately drawn with different weight and different effect
// on the surface (a transient low-alpha wash during flood vs a persistent
// high-alpha deposit during print) so the two-stroke mechanic stays legible
// rather than reading as one generic wipe.
//
// The mesh fabric itself is a fixed low-alpha grid, always visible under
// whatever ink sits on top of it — screen pitch is derived from the
// canvas's own smaller dimension via ResizeObserver, finer than the ink
// grain since it represents woven mesh, not a printed dot.
//
// Ink-through is a persistent per-cell field, not a redraw-from-scratch
// wash: an opening the print stroke has just crossed jumps straight to the
// alpha cap (0.9 of --foreground), then decays exponentially (tau = 2.4s)
// toward a floor of 0.2 between impressions — residual staining that never
// reaches 0, so a resting card always shows the ghost of at least one prior
// impression plus whatever the current stroke is doing. That is what keeps
// the loop visibly different at t0 / 2.5s / 5s: t0 catches a bare flood
// pass with no fresh deposit yet, 2.5s shows one impression mid-fade under
// a new flood pass, and 5s stacks two ghosts of different ages under the
// live stroke.
// ---------------------------------------------------------------------------

export interface ScreenFloodStrokeProps {
  /** Optional 0-1 determinate progress. When set, ink only takes on
   * openings within that fraction of the mesh's width — the print stroke
   * still sweeps the full mesh every cycle and the flood wash keeps
   * animating unforced, so the component never reads as "finished and
   * stopped" even once progress reaches 1. Omit for a purely ambient loop. */
  progress?: number;
  /** accessible label for the loader */
  "aria-label"?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** inline styles merged onto the root element */
  style?: CSSProperties;
}

type RGB = [number, number, number];

function parseColor(raw: string): RGB | null {
  const s = raw.trim();
  if (s.startsWith("#")) {
    let hex = s.slice(1);
    if (hex.length === 3) hex = hex.split("").map((c) => c + c).join("");
    if (hex.length < 6) return null;
    const r = parseInt(hex.slice(0, 2), 16);
    const g = parseInt(hex.slice(2, 4), 16);
    const b = parseInt(hex.slice(4, 6), 16);
    return Number.isNaN(r + g + b) ? null : [r, g, b];
  }
  const m = s.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
}

// --- real numbers from the spec's observed flood/print/dwell cycle --------
const FLOOD_MS = 600; // light pass, left -> right, spreads without printing
const PRINT_MS = 900; // firm pass, right -> left, forces ink through
const DWELL_MS = 300; // blade lifts clear before the next flood pass
const CYCLE_MS = FLOOD_MS + PRINT_MS + DWELL_MS; // 1800

const ANGLE = (18 * Math.PI) / 180; // squeegee tilt from vertical
const FLOOD_ALPHA = 0.15; // flat wash alpha while the flood pass is over a cell
const MESH_ALPHA = 0.08; // fixed mesh-fabric line alpha, always visible
const INK_CAP = 0.9; // alpha a freshly printed opening jumps to
const INK_FLOOR = 0.2; // residual-stain floor ink decays toward, never 0
const INK_TAU = 2.4; // seconds, exponential decay time constant

// Reduced-motion freeze frame. The spec names FREEZE_PHASE =
// "print-stroke-60pct" (squeegee mid print-stroke, ~60% of the mesh printed,
// 40% not yet — the most legible "process caught in the act" frame). Taking
// that 60%-through-print-stroke intent at face value rather than the spec's
// literal t=1.5s (which lands exactly at this cycle's flood(0.6)+print(0.9)
// boundary, i.e. a FULLY printed frame with no unprinted mesh left to show)
// is what actually reproduces the described 60/40 split; the value below is
// derived from the phase math instead of the raw seconds figure.
const FREEZE_PHASE = "print-stroke-60pct";
const STATIC_TIME_MS = FLOOD_MS + 0.6 * PRINT_MS; // 1140ms

export function ScreenFloodStroke({
  progress,
  "aria-label": ariaLabel = "Loading",
  className = "",
  style,
}: ScreenFloodStrokeProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const progressRef = useRef(progress);
  progressRef.current = progress;

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    let reduced = mq.matches;

    // -- token-derived ink: read at mount, re-derived on theme class change.
    // No literal fallback — draw() bails out while fg is still null, so
    // there is genuinely no paint before the first successful token read. --
    let fg: RGB | null = null;
    const derive = () => {
      const cs = getComputedStyle(document.documentElement);
      const parsed = parseColor(cs.getPropertyValue("--foreground"));
      if (parsed) fg = parsed;
    };
    derive();

    let w = 0;
    let h = 0;
    let dpr = 1;
    let pitch = 6;
    let cols = 0;
    let rows = 0;
    let ink = new Float32Array(0); // per-cell accumulated print-through alpha
    let raf = 0;
    let visible = true;
    let last = 0;

    // Only reallocates (and so only wipes accumulated ghosts) when the grid
    // shape actually changed. A ResizeObserver commonly fires more than
    // once for the same effective size (initial observe, font-load reflow,
    // flex settling); without this guard every one of those calls would
    // erase every ink impression and quietly break the t=2.5s/5s aliveness
    // this component depends on.
    const resizeField = () => {
      const nextCols = Math.max(1, Math.ceil(w / pitch));
      const nextRows = Math.max(1, Math.ceil(h / pitch));
      if (nextCols === cols && nextRows === rows && ink.length === nextCols * nextRows) return;
      cols = nextCols;
      rows = nextRows;
      ink = new Float32Array(cols * rows);
    };

    // squeegee's local x position at a given row, angled ANGLE from vertical
    // around the blade's centreline (baseX, h/2)
    const localX = (baseX: number, cy: number) => baseX + (cy - h / 2) * Math.sin(ANGLE);

    const step = (timeMs: number, dtMs: number) => {
      const t = timeMs % CYCLE_MS;
      const phase: "flood" | "print" | "dwell" = t < FLOOD_MS ? "flood" : t < FLOOD_MS + PRINT_MS ? "print" : "dwell";

      let baseX: number;
      if (phase === "flood") {
        baseX = (t / FLOOD_MS) * w;
      } else if (phase === "print") {
        const p = (t - FLOOD_MS) / PRINT_MS;
        baseX = w * (1 - p);
      } else {
        baseX = 0;
      }

      // decay every already-inked cell toward the residual-stain floor —
      // untouched cells (ink 0) stay 0 until their first impression
      const decay = Math.exp(-dtMs / 1000 / INK_TAU);
      for (let i = 0; i < ink.length; i++) {
        const v = ink[i];
        if (v > 0) ink[i] = INK_FLOOR + (v - INK_FLOOR) * decay;
      }

      // print stroke deposits: every cell already crossed by the blade
      // (to the right of its current, leftward-travelling position) jumps
      // straight to the alpha cap
      if (phase === "print") {
        const cap = progressRef.current;
        for (let j = 0; j < rows; j++) {
          const cy = j * pitch + pitch / 2;
          const lx = localX(baseX, cy);
          for (let i = 0; i < cols; i++) {
            const cx = i * pitch + pitch / 2;
            if (cx < lx) continue; // not yet crossed by the blade
            if (cap !== undefined && cx / w > Math.max(0, Math.min(1, cap))) continue;
            ink[j * cols + i] = INK_CAP;
          }
        }
      }

      return { phase, baseX };
    };

    const draw = (phase: "flood" | "print" | "dwell", baseX: number, timeMs: number) => {
      if (w <= 0 || h <= 0 || !fg) return;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);

      // mesh fabric — fixed low alpha, always drawn first so ink sits on
      // top of it while the grid still shows through the ink's own alpha
      ctx.strokeStyle = `rgba(${fg[0]},${fg[1]},${fg[2]},${MESH_ALPHA})`;
      ctx.lineWidth = 1;
      ctx.beginPath();
      for (let i = 0; i <= cols; i++) {
        const x = Math.min(w, i * pitch);
        ctx.moveTo(x, 0);
        ctx.lineTo(x, h);
      }
      for (let j = 0; j <= rows; j++) {
        const y = Math.min(h, j * pitch);
        ctx.moveTo(0, y);
        ctx.lineTo(w, y);
      }
      ctx.stroke();

      // print-through ink, per cell
      for (let j = 0; j < rows; j++) {
        for (let i = 0; i < cols; i++) {
          const v = ink[j * cols + i];
          if (v <= 0.005) continue;
          ctx.fillStyle = `rgba(${fg[0]},${fg[1]},${fg[2]},${v})`;
          ctx.fillRect(i * pitch, j * pitch, pitch, pitch);
        }
      }

      // flood wash — transient, recomputed live every frame, never stored:
      // it represents ink sitting on the mesh surface, not yet forced
      // through, so it has no persistence beyond the current flood pass
      if (phase === "flood") {
        ctx.fillStyle = `rgba(${fg[0]},${fg[1]},${fg[2]},${FLOOD_ALPHA})`;
        for (let j = 0; j < rows; j++) {
          const cy = j * pitch + pitch / 2;
          const lx = localX(baseX, cy);
          const xEnd = Math.max(0, Math.min(w, lx));
          if (xEnd > 0) ctx.fillRect(0, j * pitch, xEnd, pitch);
        }
      }

      // squeegee blade itself
      const barLen = h / Math.cos(ANGLE) + pitch * 2;
      const barWidth = Math.max(2, Math.min(w, h) * 0.045);
      let alpha = phase === "print" ? 0.95 : phase === "flood" ? 0.5 : 0;
      if (phase === "dwell") {
        const lift = (timeMs % CYCLE_MS) - (FLOOD_MS + PRINT_MS);
        alpha = Math.max(0, 0.4 * (1 - lift / DWELL_MS));
      }
      if (alpha > 0.01) {
        ctx.save();
        ctx.translate(baseX, h / 2);
        ctx.rotate(ANGLE);
        ctx.fillStyle = `rgba(${fg[0]},${fg[1]},${fg[2]},${alpha})`;
        ctx.fillRect(-barWidth / 2, -barLen / 2, barWidth, barLen);
        ctx.restore();
      }
    };

    const loop = (now: number) => {
      if (last === 0) last = now;
      const dt = Math.min(100, now - last);
      last = now;
      const { phase, baseX } = step(now, dt);
      draw(phase, baseX, now);
      if (!reduced && visible) raf = requestAnimationFrame(loop);
      else raf = 0;
    };
    const wake = () => {
      if (raf === 0 && !reduced && visible) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const resize = () => {
      const rect = root.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
      // mesh pitch off the container's own smaller dimension — finer than
      // a printed-dot pitch since it represents woven fabric, not ink
      pitch = Math.min(9, Math.max(4, Math.min(w, h) / 60));
      resizeField();
      if (reduced) {
        const { phase, baseX } = step(STATIC_TIME_MS, 0);
        draw(phase, baseX, STATIC_TIME_MS);
      } else {
        last = 0;
        const { phase, baseX } = step(0, 0);
        draw(phase, baseX, 0);
      }
    };

    resize();
    if (!reduced) wake();

    const ro = new ResizeObserver(resize);
    ro.observe(root);

    const mo = new MutationObserver(() => {
      derive();
      if (reduced) {
        const { phase, baseX } = step(STATIC_TIME_MS, 0);
        draw(phase, baseX, STATIC_TIME_MS);
      }
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    const onReducedChange = () => {
      reduced = mq.matches;
      if (reduced) {
        cancelAnimationFrame(raf);
        raf = 0;
        ink.fill(0);
        resizeField();
        const { phase, baseX } = step(STATIC_TIME_MS, 0);
        draw(phase, baseX, STATIC_TIME_MS);
      } else {
        ink.fill(0);
        wake();
      }
    };
    mq.addEventListener("change", onReducedChange);

    const onVisibility = () => {
      visible = document.visibilityState === "visible";
      if (visible) wake();
      else {
        cancelAnimationFrame(raf);
        raf = 0;
      }
    };
    document.addEventListener("visibilitychange", onVisibility);

    const io = new IntersectionObserver((entries) => {
      const isVisible = entries[0]?.isIntersecting ?? true;
      visible = isVisible && document.visibilityState === "visible";
      if (visible) wake();
      else {
        cancelAnimationFrame(raf);
        raf = 0;
      }
    });
    io.observe(root);

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      mo.disconnect();
      io.disconnect();
      mq.removeEventListener("change", onReducedChange);
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, []);

  return (
    <div
      ref={rootRef}
      role="img"
      aria-label={ariaLabel}
      data-freeze-phase={FREEZE_PHASE}
      className={`ns-sfs relative h-40 w-40 overflow-hidden rounded-[10px] border border-border bg-background ${className}`}
      style={style}
    >
      <canvas ref={canvasRef} aria-hidden="true" className="pointer-events-none absolute inset-0 h-full w-full" />
    </div>
  );
}

ScreenFloodStroke.displayName = "ScreenFloodStroke";

export default ScreenFloodStroke;

"use client";

import { useEffect, useRef, type ReactNode } from "react";

const W = 48; // instrument width in px

// ---------------------------------------------------------------------------
// damped spring integrator — k in s^-2, zeta dimensionless (1 = critical)
// ---------------------------------------------------------------------------
type Spring = { x: number; v: number; t: number };
function stepSpring(s: Spring, k: number, zeta: number, dt: number) {
  const c = 2 * zeta * Math.sqrt(k);
  s.v += (k * (s.t - s.x) - c * s.v) * dt;
  s.x += s.v * dt;
}
function isSettled(s: Spring) {
  return Math.abs(s.x - s.t) < 0.05 && Math.abs(s.v) < 0.05;
}

// bare-usage fallback content: three short measured sections
function FallbackSections() {
  const blocks: [string, string][] = [
    [
      "Datum",
      "Every measurement starts from a reference surface. The caliper treats the top of each section as its datum and closes the opposing jaw on the far edge.",
    ],
    [
      "Extent",
      "The jaw opening reads the section's visible span in pixels. Scroll and the blades chase the new edges with near-critical spring damping, a hair of lag by design.",
    ],
    [
      "Runout",
      "Stop scrolling and the needle over-settles with a visible wobble before locking, the way a real dial indicator bleeds off its last few microns of momentum.",
    ],
  ];
  return (
    <div className="space-y-12 p-8">
      {blocks.map(([title, copy]) => (
        <section key={title} data-section className="space-y-3">
          <h3 className="text-sm font-semibold text-foreground">{title}</h3>
          <p className="text-sm leading-relaxed text-ns-muted">{copy}</p>
          <p className="text-sm leading-relaxed text-ns-muted">{copy}</p>
        </section>
      ))}
    </div>
  );
}

// ---------------------------------------------------------------------------
// ScrollCaliper — a vernier caliper pinned to the right edge of a bounded
// scroll container. Its jaws close over the active [data-section]'s vertical
// extent (spring k=120 s^-2, zeta=0.9), a font-mono readout ticks px/percent
// on a softer spring (k=90, zeta=0.55) so it wobbles when scrolling stops,
// and the tick scale streaks with velocity-scaled motion blur. SVG + direct-
// DOM rAF, refs only; the loop sleeps 150ms after the last scroll once every
// spring settles. All ink is currentColor via token classes (text-border /
// text-foreground / text-ns-accent), so theme flips restyle the SVG live with
// no numeric getComputedStyle reads to re-derive.
// ---------------------------------------------------------------------------
export function ScrollCaliper({
  children,
  sectionSelector = "[data-section]",
  jawStiffness = 120,
  jawDamping = 0.9,
  needleStiffness = 90,
  needleDamping = 0.55,
  className = "h-[480px]",
}: {
  /** scrollable content; sections are matched via sectionSelector */
  children?: ReactNode;
  /** selector for measurable sections inside the scroller */
  sectionSelector?: string;
  /** jaw spring stiffness in s^-2 (near-critical chase) */
  jawStiffness?: number;
  /** jaw damping ratio (1 = critical) */
  jawDamping?: number;
  /** readout needle stiffness in s^-2 (softer, visible over-settle) */
  needleStiffness?: number;
  /** readout needle damping ratio */
  needleDamping?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const scrollerRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);
  const tickRef = useRef<SVGGElement>(null);
  const minorRef = useRef<SVGPathElement>(null);
  const majorRef = useRef<SVGPathElement>(null);
  const echoRef = useRef<SVGGElement>(null);
  const echoMinorRef = useRef<SVGPathElement>(null);
  const echoMajorRef = useRef<SVGPathElement>(null);
  const spineRef = useRef<SVGPathElement>(null);
  const regionRef = useRef<SVGRectElement>(null);
  const topJawRef = useRef<SVGGElement>(null);
  const botJawRef = useRef<SVGGElement>(null);
  const markerRef = useRef<SVGGElement>(null);
  const chipLabelRef = useRef<HTMLDivElement>(null);
  const chipPxRef = useRef<HTMLSpanElement>(null);
  const chipPctRef = useRef<HTMLSpanElement>(null);
  const liveRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const scroller = scrollerRef.current;
    const svg = svgRef.current;
    const tickG = tickRef.current;
    const minorPath = minorRef.current;
    const majorPath = majorRef.current;
    const echoG = echoRef.current;
    const echoMinor = echoMinorRef.current;
    const echoMajor = echoMajorRef.current;
    const spine = spineRef.current;
    const region = regionRef.current;
    const topJaw = topJawRef.current;
    const botJaw = botJawRef.current;
    const marker = markerRef.current;
    const chipLabel = chipLabelRef.current;
    const chipPx = chipPxRef.current;
    const chipPct = chipPctRef.current;
    const live = liveRef.current;
    if (
      !scroller || !svg || !tickG || !minorPath || !majorPath || !echoG ||
      !echoMinor || !echoMajor || !spine || !region || !topJaw || !botJaw ||
      !marker || !chipLabel || !chipPx || !chipPct || !live
    )
      return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    const sections = Array.from(
      scroller.querySelectorAll<HTMLElement>(sectionSelector)
    );
    const total = sections.length;

    // hot-path state — closure locals only, never React state
    const jawTop: Spring = { x: 0, v: 0, t: 0 };
    const jawBot: Spring = { x: 0, v: 0, t: 0 };
    const needle: Spring = { x: 0, v: 0, t: 0 }; // percent through section
    let H = 0;
    let raf = 0;
    let running = false;
    let last = 0;
    let primed = false;
    let lastScrollT = 0; // performance.now() of last scroll event
    let prevScroll = scroller.scrollTop;
    let vSmooth = 0; // px/s, exponentially smoothed (alpha 0.2)
    let activeIdx = -1;
    let prevPxText = "";
    let prevPctText = "";
    let lastAnnounce = 0;
    let flashTimer: ReturnType<typeof setTimeout> | undefined;
    let announceTimer: ReturnType<typeof setTimeout> | undefined;
    const visiblePx = new Map<Element, number>();

    // tick scale: minor every 2px, major every 8px, long major every 40px —
    // rebuilt on resize only; per-frame motion is a translate of the group
    const rebuild = () => {
      H = scroller.clientHeight;
      if (H <= 0) return; // zero-size container guard
      svg.setAttribute("viewBox", `0 0 ${W} ${H}`);
      let minor = "";
      let major = "";
      for (let y = -8; y <= H + 8; y += 2) {
        if (y % 40 === 0) major += `M${W - 16} ${y}h16`;
        else if (y % 8 === 0) major += `M${W - 10} ${y}h10`;
        else minor += `M${W - 5} ${y}h5`;
      }
      minorPath.setAttribute("d", minor);
      majorPath.setAttribute("d", major);
      echoMinor.setAttribute("d", minor);
      echoMajor.setAttribute("d", major);
      spine.setAttribute("d", `M${W - 0.75} 0V${H}`);
    };
    rebuild();

    // map the active section's extent to container-space jaw targets;
    // needle target = percent of the section swept past the container center
    const measure = () => {
      if (H <= 0) return;
      const cRect = scroller.getBoundingClientRect();
      const el = activeIdx >= 0 ? sections[activeIdx] : undefined;
      if (el) {
        const r = el.getBoundingClientRect();
        jawTop.t = Math.min(H, Math.max(0, r.top - cRect.top));
        jawBot.t = Math.min(H, Math.max(0, r.bottom - cRect.top));
        // zero-height section guard: never divide by a degenerate extent
        needle.t =
          r.height > 0.5
            ? Math.min(1, Math.max(0, (cRect.top + H / 2 - r.top) / r.height)) *
              100
            : 0;
      } else {
        jawTop.t = 0;
        jawBot.t = H;
        const range = scroller.scrollHeight - H;
        needle.t = range > 0 ? (scroller.scrollTop / range) * 100 : 0;
      }
    };

    const loop = (now: number) => {
      const dt = last === 0 ? 1 / 60 : Math.min(0.05, (now - last) / 1000);
      last = now;
      const sc = scroller.scrollTop;
      vSmooth += 0.2 * ((sc - prevScroll) / dt - vSmooth);
      prevScroll = sc;

      measure();
      if (reduced || !primed) {
        // reduced motion snaps every frame; first frame snaps to avoid a
        // mount sweep from zero
        jawTop.x = jawTop.t;
        jawBot.x = jawBot.t;
        needle.x = needle.t;
        jawTop.v = jawBot.v = needle.v = 0;
        primed = true;
      } else {
        stepSpring(jawTop, jawStiffness, jawDamping, dt);
        stepSpring(jawBot, jawStiffness, jawDamping, dt);
        stepSpring(needle, needleStiffness, needleDamping, dt);
      }

      // writes — direct DOM, no React
      const phase = -(sc % 8);
      tickG.style.transform = `translateY(${phase.toFixed(2)}px)`;
      topJaw.style.transform = `translateY(${jawTop.x.toFixed(2)}px)`;
      botJaw.style.transform = `translateY(${jawBot.x.toFixed(2)}px)`;
      const gap = Math.max(0, jawBot.x - jawTop.x);
      region.setAttribute("y", jawTop.x.toFixed(2));
      region.setAttribute("height", gap.toFixed(2));
      const pct = Math.min(100, Math.max(0, needle.x));
      marker.style.transform = `translateY(${(jawTop.x + (pct / 100) * gap).toFixed(2)}px)`;

      // motion-blur echo: duplicated tick layer trailing the scroll direction
      if (!reduced) {
        const speed = Math.abs(vSmooth);
        const o = Math.min(0.6, speed / 3000);
        const len = Math.min(10, speed / 200);
        if (o > 0.02) {
          echoG.style.opacity = o.toFixed(3);
          echoG.style.transform = `translateY(${(phase + Math.sign(vSmooth) * len).toFixed(2)}px)`;
          echoG.style.filter = `blur(${(len / 2).toFixed(2)}px)`;
        } else {
          echoG.style.opacity = "0";
          echoG.style.filter = "none";
        }
      }

      const pxText = gap.toFixed(1);
      if (pxText !== prevPxText) {
        chipPx.textContent = pxText;
        prevPxText = pxText;
      }
      const pctText = String(Math.round(pct));
      if (pctText !== prevPctText) {
        chipPct.textContent = pctText;
        prevPctText = pctText;
      }

      // sleep: 150ms since last scroll AND every spring inside the epsilon
      if (
        now - lastScrollT > 150 &&
        isSettled(jawTop) &&
        isSettled(jawBot) &&
        isSettled(needle)
      ) {
        echoG.style.opacity = "0"; // blur layer removed at rest for crispness
        echoG.style.filter = "none";
        vSmooth = 0;
        running = false;
        return;
      }
      raf = requestAnimationFrame(loop);
    };

    const wake = () => {
      if (!running) {
        running = true;
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const onScroll = () => {
      lastScrollT = performance.now();
      wake();
    };
    scroller.addEventListener("scroll", onScroll, { passive: true });

    // 200ms accent flash of the readout label on section change
    const flash = () => {
      chipLabel.textContent = `SEC ${activeIdx + 1}/${total}`;
      chipLabel.classList.remove("text-ns-muted");
      chipLabel.classList.add("text-ns-accent");
      if (flashTimer) clearTimeout(flashTimer);
      flashTimer = setTimeout(() => {
        chipLabel.classList.remove("text-ns-accent");
        chipLabel.classList.add("text-ns-muted");
      }, 200);
    };

    // throttled live region: 'Section 2 of 4, 38%'
    const announce = () => {
      const fire = () => {
        lastAnnounce = performance.now();
        live.textContent = `Section ${activeIdx + 1} of ${total}, ${Math.round(
          Math.min(100, Math.max(0, needle.t))
        )}%`;
      };
      if (announceTimer) clearTimeout(announceTimer);
      const since = performance.now() - lastAnnounce;
      if (since > 1200) fire();
      else announceTimer = setTimeout(fire, 1200 - since);
    };

    // active section = the one with the most visible pixels in the scroller
    const io = new IntersectionObserver(
      (entries) => {
        for (const e of entries) {
          visiblePx.set(e.target, e.isIntersecting ? e.intersectionRect.height : 0);
        }
        let best = -1;
        let bestH = 0;
        sections.forEach((s, i) => {
          const h = visiblePx.get(s) ?? 0;
          if (h > bestH) {
            bestH = h;
            best = i;
          }
        });
        if (best >= 0 && best !== activeIdx) {
          activeIdx = best;
          flash();
          announce();
          wake();
        }
      },
      { root: scroller, threshold: [0, 0.2, 0.4, 0.6, 0.8, 1] }
    );
    sections.forEach((s) => io.observe(s));

    const ro = new ResizeObserver(() => {
      rebuild();
      wake();
    });
    ro.observe(scroller);

    if (total === 0) chipLabel.textContent = "SEC —";
    wake(); // one primed frame, then immediate sleep until scroll

    return () => {
      cancelAnimationFrame(raf);
      running = false;
      io.disconnect();
      ro.disconnect();
      scroller.removeEventListener("scroll", onScroll);
      if (flashTimer) clearTimeout(flashTimer);
      if (announceTimer) clearTimeout(announceTimer);
    };
  }, [
    sectionSelector,
    jawStiffness,
    jawDamping,
    needleStiffness,
    needleDamping,
  ]);

  return (
    <div ref={rootRef} className={`relative w-full overflow-hidden ${className}`}>
      <div
        ref={scrollerRef}
        tabIndex={0}
        role="region"
        aria-label="scrollable content, measured by caliper"
        className="h-full overflow-y-auto overscroll-contain pr-16 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
      >
        {children ?? <FallbackSections />}
      </div>

      {/* instrument overlay — read-only, decorative; the live region below
          carries the accessible signal */}
      <div aria-hidden className="pointer-events-none absolute inset-0">
        <svg
          ref={svgRef}
          className="absolute inset-y-0 right-0 h-full w-12"
          viewBox={`0 0 ${W} 1`}
          preserveAspectRatio="none"
          fill="none"
        >
          {/* motion-blur echo of the tick scale (opacity/blur driven by
              scroll velocity, removed at rest) */}
          <g ref={echoRef} opacity={0}>
            <path
              ref={echoMinorRef}
              className="text-border"
              stroke="currentColor"
              strokeWidth={1}
            />
            <path
              ref={echoMajorRef}
              className="text-foreground/60"
              stroke="currentColor"
              strokeWidth={1}
            />
          </g>
          {/* main tick scale — translated by -(scrollTop % 8) per frame */}
          <g ref={tickRef}>
            <path
              ref={minorRef}
              className="text-border"
              stroke="currentColor"
              strokeWidth={1}
            />
            <path
              ref={majorRef}
              className="text-foreground/60"
              stroke="currentColor"
              strokeWidth={1}
            />
          </g>
          {/* beam spine */}
          <path
            ref={spineRef}
            className="text-border"
            stroke="currentColor"
            strokeWidth={1.5}
          />
          {/* measured span tint between the jaws */}
          <rect
            ref={regionRef}
            x={2}
            y={0}
            width={W - 4}
            height={0}
            className="text-foreground"
            fill="currentColor"
            opacity={0.05}
          />
          {/* top jaw blade */}
          <g ref={topJawRef} className="text-foreground">
            <path d={`M3 0H${W}`} stroke="currentColor" strokeWidth={1.5} />
            <path d="M3 0V-14" stroke="currentColor" strokeWidth={2.5} />
            <path d="M3 0l12 -5v5z" fill="currentColor" />
          </g>
          {/* bottom jaw blade + vernier subscale */}
          <g ref={botJawRef} className="text-foreground">
            <path d={`M3 0H${W}`} stroke="currentColor" strokeWidth={1.5} />
            <path d="M3 0V14" stroke="currentColor" strokeWidth={2.5} />
            <path d="M3 0l12 5v-5z" fill="currentColor" />
            <path
              d="M30 4h8M30 7.5h8M30 11h8M30 14.5h8"
              stroke="currentColor"
              strokeWidth={1}
              opacity={0.45}
            />
          </g>
          {/* active-value marker — the only accent ink on the instrument */}
          <g ref={markerRef} className="text-ns-accent">
            <path d={`M${W - 22} 0H${W}`} stroke="currentColor" strokeWidth={1.5} />
            <path d={`M${W - 22} 0l-5 -3.5v7z`} fill="currentColor" />
          </g>
        </svg>

        {/* digital readout chip */}
        <div className="absolute bottom-3 right-14 rounded-sm border border-foreground/20 bg-surface px-2.5 py-1.5 font-mono text-[10px] leading-snug shadow-sm">
