export interface SeamGildProps {
  /** idle button label — the weighty action being confirmed. default "Confirm payment" */
  actionLabel?: string;
  /** button label while awaiting an async onConfirm. default "Processing…" */
  pendingLabel?: string;
  /** the real confirmation: fired into an aria-live=assertive region the instant the action resolves, independent of the visual. default "Payment cleared." */
  confirmedMessage?: string;
  /** short description shown in the panel body */
  description?: string;
  /** called on trigger; return a Promise and the seam fires on resolve (reverts to idle on reject) */
  onConfirm?: () => void | Promise<void>;
  /** sessionStorage namespace — give concurrent panels on one page distinct keys. default "panel" */
  storageKey?: string;
  /** how many seams the panel keeps before the oldest is retired. default 5 */
  maxSeams?: number;
  /** bump to wipe this panel's stored seams and start fresh */
  resetKey?: number;
  className?: string;
}

export function SeamGild({
  actionLabel = "Confirm payment",
  pendingLabel = "Processing…",
  confirmedMessage = "Payment cleared.",
  description = "One tap commits the charge. Every confirmation leaves its own mark on this panel for the rest of the session.",
  onConfirm,
  storageKey = "panel",
  maxSeams = MAX_SEAMS,
  resetKey = 0,
  className = "",
}: SeamGildProps) {
  const reduced = useReducedMotion();
  const panelRef = useRef<HTMLDivElement>(null);
  const [box, setBox] = useState({ w: 0, h: 0 });
  const [seams, setSeams] = useState<SeamRecord[]>([]);
  const [newestId, setNewestId] = useState<string | null>(null);
  const [pending, setPending] = useState(false);
  const [announcement, setAnnouncement] = useState("");
  const [count, setCount] = useState(0);
  const [pendingBuild, setPendingBuild] = useState(0);
  const idRef = useRef(0);
  const onConfirmRef = useRef(onConfirm);
  onConfirmRef.current = onConfirm;

  // load persisted seams for this key on mount / when storageKey or resetKey changes
  useEffect(() => {
    if (resetKey > 0) {
      writeSeams(storageKey, []);
      writeCount(storageKey, 0);
      setSeams([]);
      setCount(0);
    } else {
      setSeams(readSeams(storageKey));
      setCount(readCount(storageKey));
    }
    setNewestId(null);
  }, [storageKey, resetKey]);

  useEffect(() => {
    const panel = panelRef.current;
    if (!panel) return;
    const measure = () => {
      const r = panel.getBoundingClientRect();
      setBox({ w: r.width, h: r.height });
    };
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(panel);
    return () => ro.disconnect();
  }, []);

  async function handleConfirm() {
    if (pending) return;
    const result = onConfirmRef.current?.();
    if (result && typeof (result as Promise<void>).then === "function") {
      setPending(true);
      try {
        await result;
      } catch {
        setPending(false);
        return;
      }
      setPending(false);
    }

    // the real confirmation: fires no matter what happens to the visual below
    const nextCount = readCount(storageKey) + 1;
    writeCount(storageKey, nextCount);
    setCount(nextCount);
    setAnnouncement(confirmedMessage);

    // defer the crack geometry to the layout effect below, which runs after
    // this render (the count above included) has actually committed to the
    // DOM — see its comment for why that ordering matters.
    setPendingBuild((n) => n + 1);
  }

  // Builds a seam against exclusion rects measured from the DOM *after* the
  // triggering render committed. Measuring inside handleConfirm instead
  // (synchronously, before React flushes the state updates above) missed
  // the counter on exactly the confirmation that makes it first appear —
  // count goes 0 -> 1 in the same click that starts the crack, so
  // `querySelectorAll("[data-seam-avoid]")` ran against DOM that hadn't
  // grown the counter span yet, and the crack could route straight through
  // where the number was about to land.
  useLayoutEffect(() => {
    if (pendingBuild === 0) return; // nothing pending on initial mount
    const panel = panelRef.current;
    if (!panel || box.w <= 0 || box.h <= 0) return;
    const panelRect = panel.getBoundingClientRect();
    const localAvoid = Array.from(panel.querySelectorAll<HTMLElement>("[data-seam-avoid]")).map(
      (el) => {
        const r = el.getBoundingClientRect();
        return new DOMRect(r.left - panelRect.left, r.top - panelRect.top, r.width, r.height);
      }
    );
    const built = buildSeam(box.w, box.h, localAvoid);
    if (!built) return; // too crowded to fit a new seam this time — confirmation still counted above

    idRef.current += 1;
    const record: SeamRecord = {
      id: `${Date.now()}-${idRef.current}`,
      trunk: normalize(built.trunk, box.w, box.h),
      branch: built.branch ? normalize(built.branch, box.w, box.h) : null,
    };

    setSeams((prev) => {
      const next = [...prev, record].slice(-maxSeams);
      writeSeams(storageKey, next);
      return next;
    });
    setNewestId(record.id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pendingBuild]);

  return (
    <div
      ref={panelRef}
      className={`relative overflow-hidden rounded-[12px] border border-border bg-background p-6 ${className}`}
    >
      <svg
        aria-hidden="true"
        role="presentation"
        className="pointer-events-none absolute inset-0 h-full w-full"
        viewBox={`0 0 ${Math.max(1, box.w)} ${Math.max(1, box.h)}`}
        preserveAspectRatio="none"
      >
        {box.w > 0 && box.h > 0 && seams.length === 0 && !reduced && (
          <IdleStress panelRef={panelRef} box={box} />
        )}
        {box.w > 0 &&
          box.h > 0 &&
          seams.map((s) => (
            <SeamMark
              key={s.id}
              trunk={denormalize(s.trunk, box.w, box.h)}
              branch={s.branch ? denormalize(s.branch, box.w, box.h) : null}
              playIntro={!reduced && s.id === newestId}
            />
          ))}
      </svg>

      <div data-seam-avoid className="relative flex flex-col gap-2">
        <p className="font-mono text-xs uppercase tracking-[0.2em] text-ns-muted">
          ns-ui / seam-gild
        </p>
        <p className="max-w-sm text-sm text-foreground">{description}</p>
      </div>

      <div className="relative mt-6 flex flex-wrap items-center gap-4">
        <button
          type="button"
          data-seam-gild-trigger
          data-seam-avoid
          onClick={handleConfirm}
          disabled={pending}
          className="rounded-[6px] border border-border bg-background px-4 py-2 text-sm font-medium text-foreground transition-colors duration-150 hover:border-ns-accent/50 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent disabled:pointer-events-none disabled:opacity-60"
        >
          {pending ? pendingLabel : actionLabel}
        </button>

        {count > 0 && (
          <span
            data-seam-gild-status
            data-seam-avoid
            role="status"
            aria-live="polite"
            className="font-mono text-xs text-ns-muted"
          >
            {count} seam{count === 1 ? "" : "s"} this session
          </span>
        )}
      </div>

      {/* the real confirmation — independent of whether the visual seam drew */}
      <span role="status" aria-live="assertive" className="sr-only">
        {announcement}
      </span>
    </div>
  );
}

"use client";

import { useId, useMemo, useRef, useState } from "react";

// Search input that winnows its list like grain from chaff: as the query
// narrows, non-matching rows lose their weight — drifting aside with a slight
// tumble and fading — then their slot collapses so the survivors settle
// together. Matches keep full ink with the matched span emphasized. Two-phase
// exit (drift, then collapse) is pure CSS: an outer grid-rows 1fr->0fr
// collapse delayed behind the inner drift. Combobox keyboard pattern:
// ArrowUp/Down roves an active option, Enter selects, Escape clears.

export interface ChaffWinnowItem {
  id: string;
  label: string;
  hint?: string;
}

export interface ChaffWinnowProps {
  /** the searchable items */
  items: ChaffWinnowItem[];
  /** input placeholder text */
  placeholder?: string;
  /** accessible name for the search input */
  label?: string;
  /** called with the chosen item when one is selected */
  onSelect?: (item: ChaffWinnowItem) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

function Highlight({ text, query }: { text: string; query: string }) {
  if (!query) return <>{text}</>;
  const i = text.toLowerCase().indexOf(query.toLowerCase());
  if (i === -1) return <>{text}</>;
  return (
    <>
      {text.slice(0, i)}
      <mark className="rounded-[3px] bg-border/80 px-0.5 font-medium text-foreground">
        {text.slice(i, i + query.length)}
      </mark>
      {text.slice(i + query.length)}
    </>
  );
}

export function ChaffWinnow({
  items,
  placeholder = "Search…",
  label = "Search",
  onSelect,
  className = "",
}: ChaffWinnowProps) {
  const [query, setQuery] = useState("");
  const [active, setActive] = useState(-1);
  const listId = useId();
  const reduced = useRef(
    typeof window !== "undefined" &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches,
  ).current;

  const q = query.trim();
  const matched = useMemo(() => {
    if (!q) return new Set(items.map((it) => it.id));
    const lq = q.toLowerCase();
    return new Set(
      items
        .filter(
          (it) =>
            it.label.toLowerCase().includes(lq) || it.hint?.toLowerCase().includes(lq),
        )
        .map((it) => it.id),
    );
  }, [items, q]);

  const visible = items.filter((it) => matched.has(it.id));
  const clampedActive = Math.min(active, visible.length - 1);

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setActive((a) => Math.min((a < 0 ? -1 : Math.min(a, visible.length - 1)) + 1, visible.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setActive((a) => Math.max(Math.min(a, visible.length - 1) - 1, 0));
    } else if (e.key === "Enter" && clampedActive >= 0 && visible[clampedActive]) {
      e.preventDefault();
      onSelect?.(visible[clampedActive]);
    } else if (e.key === "Escape") {
      setQuery("");
      setActive(-1);
    }
  };

  return (
    <div className={["w-full rounded-md border border-border bg-surface", className].join(" ")}>
      <div className="flex items-center gap-2.5 border-b border-border px-4 py-3">
        <svg aria-hidden width={15} height={15} viewBox="0 0 15 15" className="shrink-0 text-ns-muted">
          <circle cx={6.5} cy={6.5} r={4.5} fill="none" stroke="currentColor" strokeWidth={1.5} />
          <path d="M 10 10 L 13.5 13.5" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" />
        </svg>
        <input
          type="text"
          role="combobox"
          aria-label={label}
          aria-expanded={visible.length > 0}
          aria-controls={listId}
          aria-activedescendant={
            clampedActive >= 0 && visible[clampedActive]
              ? `${listId}-${visible[clampedActive].id}`
              : undefined
          }
          aria-autocomplete="list"
          value={query}
          placeholder={placeholder}
          onChange={(e) => {
            setQuery(e.target.value);
            setActive(-1);
          }}
          onKeyDown={onKeyDown}
          className="w-full bg-transparent text-sm text-foreground outline-none placeholder:text-ns-muted"
        />
        <span aria-live="polite" className="shrink-0 font-mono text-[11px] tabular-nums text-ns-muted">
          {visible.length}/{items.length}
        </span>
      </div>
      <ul id={listId} role="listbox" aria-label={label} className="py-1">
        {items.map((it) => {
          const out = !matched.has(it.id);
          const vi = visible.findIndex((v) => v.id === it.id);
          const isActive = vi >= 0 && vi === clampedActive;
          return (
            // outer: slot collapse, delayed behind the inner drift so the
            // row visibly blows aside before its space closes
            <li
              key={it.id}
              role={out ? "presentation" : "option"}
              id={out ? undefined : `${listId}-${it.id}`}
              aria-selected={out ? undefined : isActive}
              className="grid"
              style={{
                gridTemplateRows: out ? "0fr" : "1fr",
                transition: reduced
                  ? "none"
                  : `grid-template-rows 280ms cubic-bezier(0.22, 1, 0.36, 1) ${out ? "140ms" : "0ms"}`,
              }}
            >
              <div className="min-h-0 overflow-hidden">
                <div
                  onClick={out ? undefined : () => onSelect?.(it)}
                  className={[
                    "mx-1 flex items-baseline gap-3 rounded-sm px-3 py-2",
                    out ? "" : "cursor-pointer",
                    isActive ? "bg-border/60" : out ? "" : "hover:bg-border/40",
                    "transition-[background-color] duration-150",
                  ].join(" ")}
                  style={{
                    opacity: out ? 0 : 1,
                    transform: out
                      ? "translateX(14px) rotate(1.5deg)"
                      : "translateX(0) rotate(0deg)",
                    transition: reduced
                      ? "opacity 0ms"
                      : `opacity 220ms ease, transform 260ms cubic-bezier(0.55, 0, 0.55, 0.2), background-color 150ms ease`,
                  }}
                >
                  <span className="min-w-0 flex-1 truncate text-sm text-foreground">
                    <Highlight text={it.label} query={q} />
                  </span>
                  {it.hint ? (
                    <span className="shrink-0 font-mono text-[11px] text-ns-muted">
                      <Highlight text={it.hint} query={q} />
                    </span>
                  ) : null}
                </div>
              </div>
            </li>
          );
        })}
        <li
          role="presentation"
          className="grid"
          style={{
            gridTemplateRows: visible.length === 0 ? "1fr" : "0fr",
            transition: reduced
              ? "none"
              : "grid-template-rows 280ms cubic-bezier(0.22, 1, 0.36, 1) 140ms",
          }}
        >
          <div className="min-h-0 overflow-hidden">
            <p className="px-4 py-2 font-mono text-[11px] text-ns-muted">
              nothing survives “{q}”
            </p>
          </div>
        </li>
      </ul>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// SeatmapAsciiPick — an ASCII floor plan where a drag marquee selects a
// CONTIGUOUS block of seats, not one seat at a time. Taken seats and the
// aisle gap are both "unavailable" for the purpose of contiguity: dragging a
// marquee across a row that contains one breaks the run right there, and the
// selection snaps to the single longest unbroken run of available seats
// inside the marquee's row span — never the raw rectangle, which is what
// makes "unavailable cells break the block" visible rather than assumed.
// Distinct from grid-magnetic-lattice (ambient cursor field, nothing is
// selected) and filter-facet-mesh (toggling a SET of facet chips, not a
// contiguous run of grid cells). No canvas: every glyph is a real DOM
// button/span, colored from tokens via Tailwind classes only.
// ---------------------------------------------------------------------------

type SeatStatus = "available" | "taken" | "aisle";
type Cell = { r: number; c: number };

export interface SeatmapAsciiPickProps {
  /** rows x cols seat status grid */
  seats?: SeatStatus[][];
  /** label for each row, left of the grid */
  rowLabels?: string[];
  /** label for each column, above the grid */
  colLabels?: string[];
  /** heading above the seatmap */
  sectionLabel?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const A: SeatStatus = "available";
const T: SeatStatus = "taken";
const G: SeatStatus = "aisle";

const DEFAULT_SEATS: SeatStatus[][] = [
  [A, A, T, A, A, G, A, A, A, T, A],
  [A, A, A, A, T, G, A, A, T, A, A],
  [T, A, A, A, A, G, A, A, A, A, A],
  [A, A, A, T, A, G, A, T, A, A, A],
  [A, T, A, A, A, G, A, A, A, A, T],
  [A, A, A, A, A, G, T, A, A, A, A],
];

const DEFAULT_ROW_LABELS = ["ROW 8", "ROW 9", "ROW 10", "ROW 11", "ROW 12", "ROW 13"];
const DEFAULT_COL_LABELS = ["A", "B", "C", "D", "E", "", "F", "G", "H", "I", "J"];

function clamp(v: number, lo: number, hi: number) {
  return Math.min(hi, Math.max(lo, v));
}

/** longest unbroken run of available seats, within [left,right], across every row in [top,bottom] */
function bestRun(seats: SeatStatus[][], top: number, bottom: number, left: number, right: number) {
  let best: { r: number; start: number; end: number } | null = null;
  for (let r = top; r <= bottom; r++) {
    let runStart = -1;
    for (let c = left; c <= right + 1; c++) {
      const status = c <= right ? seats[r]?.[c] : "taken"; // sentinel to flush a trailing run
      if (status === "available") {
        if (runStart === -1) runStart = c;
      } else {
        if (runStart !== -1) {
          const len = c - runStart;
          if (!best || len > best.end - best.start + 1) {
            best = { r, start: runStart, end: c - 1 };
          }
        }
        runStart = -1;
      }
    }
  }
  return best;
}

export function SeatmapAsciiPick({
  seats = DEFAULT_SEATS,
  rowLabels = DEFAULT_ROW_LABELS,
  colLabels = DEFAULT_COL_LABELS,
  sectionLabel = "SECTION C",
  className = "",
}: SeatmapAsciiPickProps) {
  const rows = seats.length;
  const cols = seats[0]?.length ?? 0;

  const [anchor, setAnchor] = useState<Cell | null>(null);
  const [focus, setFocus] = useState<Cell | null>(null);
  const draggingRef = useRef(false);
  const gridRef = useRef<HTMLDivElement>(null);

  const run = useMemo(() => {
    if (!anchor || !focus) return null;
    const top = Math.min(anchor.r, focus.r);
    const bottom = Math.max(anchor.r, focus.r);
    const left = Math.min(anchor.c, focus.c);
    const right = Math.max(anchor.c, focus.c);
    return bestRun(seats, top, bottom, left, right);
  }, [anchor, focus, seats]);

  const startDrag = (cell: Cell) => {
    if (seats[cell.r]?.[cell.c] === "aisle") return;
    draggingRef.current = true;
    setAnchor(cell);
    setFocus(cell);
  };

  const dragTo = (cell: Cell) => {
    if (draggingRef.current) setFocus(cell);
  };

  useEffect(() => {
    const end = () => {
      draggingRef.current = false;
    };
    window.addEventListener("pointerup", end);
    return () => window.removeEventListener("pointerup", end);
  }, []);

  const focusSeatButton = (r: number, c: number) => {
    gridRef.current?.querySelector<HTMLButtonElement>(`[data-r="${r}"][data-c="${c}"]`)?.focus();
  };

  const nextAvailable = useCallback(
    (r: number, c: number, dc: number): number => {
      let nc = c;
      for (let i = 0; i < cols; i++) {
        nc = clamp(nc + dc, 0, cols - 1);
        if (seats[r]?.[nc] !== "aisle") return nc;
        if (nc === 0 || nc === cols - 1) return nc;
      }
      return c;
    },
    [cols, seats]
  );

  const onKeyDown = (e: React.KeyboardEvent, cell: Cell) => {
    const map: Record<string, [number, number]> = {
      ArrowUp: [-1, 0],
      ArrowDown: [1, 0],
      ArrowLeft: [0, -1],
      ArrowRight: [0, 1],
    };
    const delta = map[e.key];
    if (!delta) return;
    e.preventDefault();
    let nr = clamp(cell.r + delta[0], 0, rows - 1);
    let nc = clamp(cell.c + delta[1], 0, cols - 1);
    if (delta[1] !== 0) nc = nextAvailable(cell.r, cell.c, delta[1]);
    if (seats[nr]?.[nc] === "aisle") return;
    if (e.shiftKey) {
      setAnchor((a) => a ?? cell);
      setFocus({ r: nr, c: nc });
    } else {
      setAnchor({ r: nr, c: nc });
      setFocus({ r: nr, c: nc });
    }
    focusSeatButton(nr, nc);
  };

  const inRun = (r: number, c: number) => !!run && run.r === r && c >= run.start && c <= run.end;

  const [activeR, activeC] = focus ? [focus.r, focus.c] : [0, 0];

  return (
    <div className={`inline-flex flex-col gap-2 font-mono ${className}`}>
      <div className="flex items-center justify-between gap-3">
        <span className="text-xs uppercase tracking-widest text-ns-muted">{sectionLabel}</span>
        <span className="text-[10px] uppercase tracking-widest text-ns-muted">drag to select a block</span>
      </div>

      <div className="flex flex-col items-center gap-1 rounded-sm border border-border bg-surface px-4 py-3">
        <span className="mb-1 select-none text-[10px] tracking-[0.4em] text-ns-muted">— STAGE —</span>
        <div
          ref={gridRef}
          className="grid gap-y-1"
          style={{ gridTemplateColumns: `2.5em repeat(${cols}, 1.6em)` }}
        >
          {seats.map((seatRow, r) => (
            <div key={r} className="contents">
              <div className="flex items-center text-[10px] text-ns-muted">{rowLabels[r]}</div>
              {seatRow.map((status, c) => {
                if (status === "aisle") {
                  return (
                    <div
                      key={c}
                      aria-hidden
                      className="flex h-6 items-center justify-center text-border"
                      onPointerEnter={() => dragTo({ r, c })}
                    >
                      {" "}
                    </div>
                  );
                }
                const selected = inRun(r, c);
                const isActive = activeR === r && activeC === c;
                return (
                  <button
                    key={c}
                    type="button"
                    data-r={r}
                    data-c={c}
                    disabled={status === "taken"}
                    aria-pressed={selected}
                    aria-label={`${rowLabels[r]} seat ${colLabels[c]}${status === "taken" ? ", taken" : selected ? ", selected" : ", available"}`}
                    tabIndex={isActive ? 0 : -1}
                    className={`flex h-6 w-6 items-center justify-center rounded-[2px] text-xs outline-none transition-colors duration-100 motion-reduce:transition-none focus-visible:z-10 focus-visible:ring-2 focus-visible:ring-ns-accent ${
                      status === "taken"
                        ? "cursor-not-allowed text-ns-muted/50"
                        : selected
                          ? "bg-ns-accent/[0.16] text-foreground hover:bg-ns-accent/[0.24]"
                          : "text-foreground hover:bg-foreground/[0.08]"
                    }`}
                    onPointerDown={() => startDrag({ r, c })}
                    onPointerEnter={() => dragTo({ r, c })}
                    onFocus={() => setFocus({ r, c })}
                    onKeyDown={(e) => onKeyDown(e, { r, c })}
                  >
                    {status === "taken" ? "×" : selected ? "●" : "○"}
                  </button>
                );
              })}
            </div>
          ))}
        </div>
      </div>

      <div
        data-count-readout
        aria-live="polite"
        className="rounded-sm border border-border bg-background px-3 py-1.5 text-[11px] tabular-nums text-ns-muted"
      >
        {run ? (
          <>
            <span className="text-foreground">{run.end - run.start + 1}</span>
            {" seats selected — "}
            <span className="text-foreground">
              {rowLabels[run.r]} {colLabels[run.start]}–{colLabels[run.end]}
            </span>
          </>
        ) : (
          "no seats selected — drag across an available block"
        )}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// SeepLattice — a feature-flag rollout picker where "blast radius" is
// computed as literal site percolation, not a smooth percentage. Every user
// segment is a cell in a fixed grid lattice; adjacency is DECLARED as an
// explicit edge list (each cell's up/down/left/right neighbours — the
// lattice standing in for shared-infra/shared-tenancy proximity), never
// inferred from distance to the slider value. One scalar `p` (the rollout
// percentage) governs everything: a fixed seeded permutation orders every
// cell once at mount, and the wet set is always exactly the first
// round(p/100 * n) cells of that order — so p directly prefixes the wet
// set, dragging back down un-wets in EXACT reverse, and nothing is ever
// re-rolled mid-drag. On every value change, union-find runs over the
// declared adjacency graph (never a radial or rectangular zone guess) to
// find the largest connected wet cluster; that cluster's outer boundary is
// traced into ONE SVG perimeter path (marching-squares-style edge walk, not
// per-cell borders), and its size is the headline figure. The containment
// threshold line is measured once at mount by binary search over THIS
// lattice's actual spanning behaviour (top-row-to-bottom-row connectivity),
// not the textbook 0.5927 — a finite lattice with this adjacency has its
// own threshold. Newly-wet cells fill with a capillary stagger: a mini BFS
// over just the cells added this step, seeded from wherever they touch
// already-wet cells, delays each cell's fill transition by its BFS depth —
// water visibly floods outward from existing wet regions, not a uniform
// flash. Everything is a pure function of p and the lattice; the only
// interactive control is the rollout slider itself.
// ---------------------------------------------------------------------------

const CELL_GAP = 0.16; // inset per cell, in viewBox cell-units
const FRONT_SPEED_MS = 16; // ms per BFS-depth step of capillary stagger
const MAX_STAGGER_MS = 260; // cap so a huge jump doesn't queue forever
const FILL_DURATION_MS = 200;

function clamp(v: number, lo: number, hi: number) {
  return Math.min(hi, Math.max(lo, v));
}

// -- seeded PRNG + permutation ----------------------------------------------

function mulberry32(seed: number) {
  let s = seed >>> 0;
  return function rand() {
    s = (s + 0x6d2b79f5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function seededOrder(n: number, seed: number): number[] {
  const order = Array.from({ length: n }, (_, i) => i);
  const rand = mulberry32(seed);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    const tmp = order[i];
    order[i] = order[j];
    order[j] = tmp;
  }
  return order;
}

// -- declared adjacency (4-neighbour grid, explicit edge list) --------------

function buildNeighbors(rows: number, cols: number): number[][] {
  const n = rows * cols;
  const neighbors: number[][] = new Array(n);
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const idx = r * cols + c;
      const list: number[] = [];
      if (r > 0) list.push(idx - cols);
      if (r < rows - 1) list.push(idx + cols);
      if (c > 0) list.push(idx - 1);
      if (c < cols - 1) list.push(idx + 1);
      neighbors[idx] = list;
    }
  }
  return neighbors;
}

// -- spanning test (top row <-> bottom row) over the wet prefix -------------

function isSpanning(
  k: number,
  order: number[],
  neighbors: number[][],
  rows: number,
  cols: number,
  n: number
): boolean {
  const TOP = n;
  const BOTTOM = n + 1;
  const parent = new Int32Array(n + 2);
  for (let i = 0; i < n + 2; i++) parent[i] = i;
  const find = (x: number): number => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  };
  const union = (a: number, b: number) => {
    const ra = find(a);
    const rb = find(b);
    if (ra !== rb) parent[ra] = rb;
  };
  const wet = new Uint8Array(n);
  for (let i = 0; i < k; i++) wet[order[i]] = 1;
  for (let c = 0; c < n; c++) {
    if (!wet[c]) continue;
    const row = Math.floor(c / cols);
    if (row === 0) union(c, TOP);
    if (row === rows - 1) union(c, BOTTOM);
    for (const nb of neighbors[c]) if (wet[nb]) union(c, nb);
  }
  return find(TOP) === find(BOTTOM);
}

interface Lattice {
  n: number;
  rows: number;
  cols: number;
  neighbors: number[][];
  order: number[];
  thresholdK: number;
  thresholdPct: number;
}

// Built once per (rows, cols, seed): declares adjacency, fixes the wetting
// permutation, and measures this exact lattice's own percolation threshold
// by binary search (spanning is monotonic in k since wet cells only ever
// accumulate along a fixed prefix).
function buildLattice(rows: number, cols: number, seed: number): Lattice {
  const n = rows * cols;
  const neighbors = buildNeighbors(rows, cols);
  const order = seededOrder(n, seed);
  let lo = 0;
  let hi = n;
  while (lo + 1 < hi) {
    const mid = (lo + hi) >> 1;
    if (isSpanning(mid, order, neighbors, rows, cols, n)) hi = mid;
    else lo = mid;
  }
  return { n, rows, cols, neighbors, order, thresholdK: hi, thresholdPct: (hi / n) * 100 };
}

// -- union-find over the wet prefix, every frame -----------------------------

interface WetResult {
  wetMask: Uint8Array;
  clusterMask: Uint8Array;
  largestSize: number;
}

function computeWet(k: number, lattice: Lattice): WetResult {
  const { n, order, neighbors } = lattice;
  const wet = new Uint8Array(n);
  for (let i = 0; i < k; i++) wet[order[i]] = 1;
  const parent = new Int32Array(n);
  const size = new Int32Array(n).fill(1);
  for (let i = 0; i < n; i++) parent[i] = i;
  const find = (x: number): number => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  };
  const union = (a: number, b: number) => {
    let ra = find(a);
    let rb = find(b);
    if (ra === rb) return;
    if (size[ra] < size[rb]) {
      const t = ra;
      ra = rb;
      rb = t;
    }
    parent[rb] = ra;
    size[ra] += size[rb];
  };
  for (let c = 0; c < n; c++) {
    if (!wet[c]) continue;
    for (const nb of neighbors[c]) if (wet[nb]) union(c, nb);
  }
  let bestRoot = -1;
  let bestSize = 0;
  for (let c = 0; c < n; c++) {
    if (!wet[c]) continue;
    const r = find(c);
    if (size[r] > bestSize) {
      bestSize = size[r];
      bestRoot = r;
    }
  }
  const clusterMask = new Uint8Array(n);
  if (bestRoot >= 0) {
    for (let c = 0; c < n; c++) if (wet[c] && find(c) === bestRoot) clusterMask[c] = 1;
  }
  return { wetMask: wet, clusterMask, largestSize: bestSize };
}

// -- trace the largest cluster's outer boundary into one (or more, if it
// has a hole) SVG path loop, by walking declared grid edges — not by
// drawing per-cell borders. Any deterministic pick at a rare diagonal-touch
// vertex still decomposes the edge set into valid closed loops. -----------

function tracePerimeter(mask: Uint8Array, rows: number, cols: number): string {
  const at = (r: number, c: number): boolean =>
    r >= 0 && r < rows && c >= 0 && c < cols ? mask[r * cols + c] === 1 : false;

  const out = new Map<string, { x: number; y: number }[]>();
  const push = (fx: number, fy: number, tx: number, ty: number) => {
    const key = `${fx},${fy}`;
    const arr = out.get(key);
    if (arr) arr.push({ x: tx, y: ty });
    else out.set(key, [{ x: tx, y: ty }]);
  };

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (!at(r, c)) continue;
      if (!at(r - 1, c)) push(c + 1, r, c, r); // north edge, right -> left
      if (!at(r, c + 1)) push(c + 1, r + 1, c + 1, r); // east edge, bottom -> top
      if (!at(r + 1, c)) push(c, r + 1, c + 1, r + 1); // south edge, left -> right
      if (!at(r, c - 1)) push(c, r, c, r + 1); // west edge, top -> bottom
    }
  }

  const loops: { x: number; y: number }[][] = [];
  for (const [startKey, arr] of out) {
    while (arr.length) {
      const [sx, sy] = startKey.split(",").map(Number);
      let cx = sx;
      let cy = sy;
      const loop: { x: number; y: number }[] = [{ x: cx, y: cy }];
      let guard = 0;
      while (guard++ < 100000) {
        const outs = out.get(`${cx},${cy}`);
        if (!outs || outs.length === 0) break;
        const next = outs.pop() as { x: number; y: number };
        cx = next.x;
        cy = next.y;
        if (cx === sx && cy === sy) break;
        loop.push({ x: cx, y: cy });
      }
      if (loop.length >= 3) loops.push(loop);
    }
  }

  if (!loops.length) return "";
  return loops.map((loop) => `M ${loop.map((p) => `${p.x} ${p.y}`).join(" L ")} Z`).join(" ");
}

// -----------------------------------------------------------------------------

export interface SeepLatticeProps {
  /** lattice height, in cells (kept small so union-find stays cheap per frame) */
  rows?: number;
  /** lattice width, in cells */
  cols?: number;
  /** fixed seed for the wetting permutation and adjacency — same seed, same lattice */
  seed?: number;
  /** controlled rollout percentage, 0-100 */
  rollout?: number;
  /** uncontrolled initial rollout percentage */
  defaultRollout?: number;
  /** called with the new rollout percentage on every change */
  onRolloutChange?: (v: number) => void;
  /** noun used in the readouts, e.g. "traffic" (default) or "requests" */
  segmentLabel?: string;
  /** extra classes merged onto the root element */
  className?: string;
}

export function SeepLattice({
  rows = 16,
  cols = 24,
  seed = 20260817,
  rollout,
  defaultRollout = 35,
  onRolloutChange,
  segmentLabel = "traffic",
  className = "",
}: SeepLatticeProps) {
  const isControlled = rollout !== undefined;
  const [rolloutInternal, setRolloutInternal] = useState(() => clamp(defaultRollout, 0, 100));
  const value = isControlled ? (rollout as number) : rolloutInternal;
  const valueRef = useRef(value);
  valueRef.current = value;

  const safeRows = Math.max(2, Math.floor(rows));
  const safeCols = Math.max(2, Math.floor(cols));
  const lattice = useMemo(() => buildLattice(safeRows, safeCols, seed), [safeRows, safeCols, seed]);

  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(mq.matches);
    update();
    mq.addEventListener("change", update);
    return () => mq.removeEventListener("change", update);
  }, []);

  const k = clamp(Math.round((value / 100) * lattice.n), 0, lattice.n);

  const { wetMask, clusterMask, largestSize } = useMemo(() => computeWet(k, lattice), [k, lattice]);
  const perimeterD = useMemo(
    () => tracePerimeter(clusterMask, lattice.rows, lattice.cols),
    [clusterMask, lattice]
  );

  const clusterPct = lattice.n > 0 ? Math.round((largestSize / lattice.n) * 100) : 0;
  const roundedRollout = Math.round(value);
  const thresholdRoundedPct = Math.round(lattice.thresholdPct);
  const aboveThreshold = k >= lattice.thresholdK;

  // -- capillary stagger: a mini BFS over just this step's newly-wet cells,
  // seeded from wherever they touch already-wet cells, sets each affected
  // cell's transition-delay directly (skipped outright under reduced motion
  // — cells then just snap, no stagger, no entrance). Runs in a layout
  // effect so the delay lands before the browser paints the fill change
  // committed in the same render. --------------------------------------
  const cellElsRef = useRef<(SVGRectElement | null)[]>([]);
  const prevKRef = useRef(0);
  const prevWetRef = useRef<Uint8Array | null>(null);

  useLayoutEffect(() => {
    const { n, order, neighbors } = lattice;
    if (!prevWetRef.current || prevWetRef.current.length !== n) {
      prevWetRef.current = new Uint8Array(n);
      prevKRef.current = 0;
    }
    const prevWet = prevWetRef.current;
    const prevK = prevKRef.current;

    // Un-wetting (dragging p down) is always instant with no stagger — clear
    // any delay left over from a prior flood before deciding whether this
    // step needs a new one, or a cell that flooded in staggered would dry
    // out staggered by a delay computed for a different pass.
    for (let i = 0; i < n; i++) {
      const el = cellElsRef.current[i];
      if (el && el.style.transitionDelay) el.style.transitionDelay = "";
    }

    if (!reduced && k > prevK) {
      const newlySet = new Set<number>();
      for (let i = prevK; i < k; i++) newlySet.add(order[i]);
      const depth = new Map<number, number>();
      const queue: number[] = [];
      for (const cell of newlySet) {
        for (const nb of neighbors[cell]) {
          if (prevWet[nb]) {
            depth.set(cell, 0);
            queue.push(cell);
            break;
          }
        }
      }
      if (queue.length === 0) {
        for (const cell of newlySet) {
          depth.set(cell, 0);
          queue.push(cell);
        }
      }
      let qi = 0;
      while (qi < queue.length) {
        const cur = queue[qi++];
        const d = depth.get(cur) as number;
        for (const nb of neighbors[cur]) {
          if (newlySet.has(nb) && !depth.has(nb)) {
            depth.set(nb, d + 1);
            queue.push(nb);
          }
        }
      }
      for (const [cell, d] of depth) {
        const el = cellElsRef.current[cell];
        if (el) el.style.transitionDelay = `${Math.min(d * FRONT_SPEED_MS, MAX_STAGGER_MS)}ms`;
      }
    }

    const curWet = new Uint8Array(n);
    for (let i = 0; i < k; i++) curWet[order[i]] = 1;
    prevWetRef.current = curWet;
    prevKRef.current = k;
  }, [lattice, k, reduced]);

  // -- one polite announcement per threshold crossing, in each direction --
  const liveRegionRef = useRef<HTMLDivElement>(null);
  const mountedRef = useRef(false);
  const prevAboveRef = useRef(aboveThreshold);
  useEffect(() => {
    if (!mountedRef.current) {
      mountedRef.current = true;
      prevAboveRef.current = aboveThreshold;
      return;
    }
    if (aboveThreshold !== prevAboveRef.current) {
      prevAboveRef.current = aboveThreshold;
      if (liveRegionRef.current) {
        liveRegionRef.current.textContent = aboveThreshold
          ? `Crossed containment threshold — largest connected exposure now spans the lattice.`
          : `Back below containment threshold.`;
      }
    }
  }, [aboveThreshold]);

  const commit = (v: number) => {
    const q = clamp(v, 0, 100);
    if (Math.abs(q - valueRef.current) < 1e-9) return;
    if (!isControlled) setRolloutInternal(q);
    onRolloutChange?.(q);
  };

  const trackRef = useRef<HTMLDivElement>(null);
  const draggingRef = useRef(false);
  const [active, setActive] = useState(false);

  const posToValue = (clientX: number): number => {
    const track = trackRef.current;
    if (!track) return valueRef.current;
    const rect = track.getBoundingClientRect();
    if (rect.width <= 0) return valueRef.current;
    return clamp(((clientX - rect.left) / rect.width) * 100, 0, 100);
  };

  const onTrackPointerDown = (e: React.PointerEvent) => {
    e.preventDefault();
    e.currentTarget.setPointerCapture(e.pointerId);
    draggingRef.current = true;
    setActive(true);
    commit(posToValue(e.clientX));
  };
  const onTrackPointerMove = (e: React.PointerEvent) => {
    if (!draggingRef.current) return;
    commit(posToValue(e.clientX));
  };
  const endDrag = () => {
    draggingRef.current = false;
    setActive(false);
  };

  const onKeyDown = (e: React.KeyboardEvent) => {
    const v = valueRef.current;
    const cellStep = Math.max(100 / lattice.n, 0.5);
    let next: number | null = null;
    switch (e.key) {
      case "ArrowRight":
      case "ArrowUp":
        next = v + cellStep;
        break;
      case "ArrowLeft":
      case "ArrowDown":
        next = v - cellStep;
        break;
      case "PageUp":
        next = v + 10;
        break;
      case "PageDown":
        next = v - 10;
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = 100;
        break;
      default:
        return;
    }
    e.preventDefault();
    commit(clamp(next, 0, 100));
  };

  const valueText = `rollout ${roundedRollout}% — largest connected exposure ${clusterPct}% of ${segmentLabel}, ${
    aboveThreshold ? "above" : "below"
  } containment threshold`;

  return (
    <div className={`w-full select-none ${className}`}>
      <svg
        aria-hidden="true"
        focusable="false"
        viewBox={`0 0 ${lattice.cols} ${lattice.rows}`}
        preserveAspectRatio="xMidYMid meet"
        className="block w-full rounded-md border border-border bg-background"
        style={{ aspectRatio: `${lattice.cols} / ${lattice.rows}` }}
      >
        {Array.from({ length: lattice.n }, (_, i) => {
          const r = Math.floor(i / lattice.cols);
          const c = i % lattice.cols;
          const isWet = wetMask[i] === 1;
          const isCluster = clusterMask[i] === 1;
          const fill = isCluster ? "var(--foreground)" : isWet ? "var(--ns-muted)" : "var(--border)";
          return (
            <rect
              key={i}
              ref={(el) => {
                cellElsRef.current[i] = el;
              }}
              x={c + CELL_GAP / 2}
              y={r + CELL_GAP / 2}
              width={1 - CELL_GAP}
              height={1 - CELL_GAP}
              rx={0.06}
              fill={fill}
              className="transition-colors ease-out motion-reduce:transition-none"
              style={{ transitionDuration: `${FILL_DURATION_MS}ms` }}
            />
          );
        })}
        {perimeterD && (
          <path
            d={perimeterD}
            fill="var(--foreground)"
            fillOpacity={0.06}
            fillRule="evenodd"
            stroke="var(--foreground)"
            strokeWidth={2}
            strokeLinejoin="round"
            vectorEffect="non-scaling-stroke"
          />
        )}
      </svg>

      <div className="mt-3 flex items-center justify-between font-mono text-xs">
        <span className="text-ns-muted">Rollout</span>
        <span className="tabular-nums text-foreground">{roundedRollout}%</span>
      </div>

      <div
        ref={trackRef}
        role="slider"
        tabIndex={0}
        aria-label="Rollout percentage"
        aria-orientation="horizontal"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={roundedRollout}
        aria-valuetext={valueText}
        onKeyDown={onKeyDown}
        onFocus={() => setActive(true)}
        onBlur={() => setActive(false)}
        onPointerDown={onTrackPointerDown}
        onPointerMove={onTrackPointerMove}
        onPointerUp={endDrag}
        onPointerCancel={endDrag}
        className="group relative mt-1.5 h-5 w-full cursor-pointer touch-none outline-none focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background"
      >
        <span className="absolute left-0 top-1/2 h-1 w-full -translate-y-1/2 rounded-full bg-border" />
        <span
          aria-hidden
          className="absolute top-1/2 h-1 -translate-y-1/2 rounded-full bg-foreground/70"
          style={{ width: `${roundedRollout}%` }}
        />
        <span
          aria-hidden
          className="absolute top-1/2 h-3 w-px -translate-y-1/2 bg-foreground/50"
          style={{ left: `${thresholdRoundedPct}%` }}
        />
        <span
          aria-hidden
          data-active={active}
          style={{ left: `${roundedRollout}%` }}
          className="absolute top-1/2 h-3.5 w-3.5 -translate-x-1/2 -translate-y-1/2 rounded-full border border-border bg-background transition-colors duration-150 group-hover:border-foreground/40 data-[active=true]:border-ns-accent"
        />
      </div>

      <p className="mt-2 font-mono text-xs text-ns-muted">
        threshold <span className="tabular-nums text-foreground">{thresholdRoundedPct}%</span>
        {" · "}largest connected exposure{" "}
        <span className="tabular-nums text-foreground">{clusterPct}%</span> of {segmentLabel}
        {" — "}
        <span className={aboveThreshold ? "text-foreground" : "text-ns-muted"}>
          {aboveThreshold ? "above" : "below"} containment threshold
        </span>
      </p>

      <div aria-live="polite" className="sr-only" ref={liveRegionRef} />
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// FlingSegment — segmented control whose selection pill is grabbable: drag
// and release it anywhere along the track and it coasts on real release
// velocity under exponential friction, rubber-bands off the track edges, and
// captures into the nearest segment detent with one small overshoot. Click
// and keyboard remain instant no-drag paths (critically damped glide across
// both x and width — segments may differ in width). Pure DOM: the pill is an
// absolutely-positioned node driven by OFFSET transforms relative to its
// layout slot on a direct-DOM rAF loop — zero React state on the hot path,
// the loop sleeps at a velocity epsilon, pauses offscreen, and a 1 s
// forced-settle deadline guarantees physics never jitters forever. All ink
// is token-relative CSS (background/surface/border/foreground/accent), so
// both themes restyle live with nothing to re-derive.
// ---------------------------------------------------------------------------

const FRICTION = 4.5; // exponential coast friction, s^-1
const CAPTURE_V = 300; // px/s — below this the nearest detent captures
const DETENT_K = 280; // detent capture spring, s^-2
const DETENT_ZETA = 0.8; // one small overshoot
const EDGE_K = 320; // edge rubber-band spring, s^-2
const EDGE_ZETA = 0.9;
const GLIDE_K = 220; // click/keyboard glide — critically damped, ~260 ms
const GLIDE_ZETA = 1.0;
const RUBBER = 0.35; // beyond-track displacement scale
const SETTLE_MS = 1000; // forced-settle deadline
const V_WINDOW = 80; // ms of pointer samples averaged into release velocity
const INTRO_DELAY_MS = 2500; // one-shot intro fling — a beat after first paint

export interface FlingSegmentOption {
  value: string;
  label: string;
}

const DEFAULT_OPTIONS: FlingSegmentOption[] = [
  { value: "list", label: "List" },
  { value: "board", label: "Board" },
  { value: "timeline", label: "Timeline" },
];

export function FlingSegment({
  options = DEFAULT_OPTIONS,
  value,
  defaultValue,
  onValueChange,
  introFling = false,
  className = "",
  "aria-label": ariaLabel = "View",
}: {
  /** the segments */
  options?: FlingSegmentOption[];
  /** controlled value; omit for uncontrolled */
  value?: string;
  /** uncontrolled initial value */
  defaultValue?: string;
  /** fires once per selection change — on detent commit, never per-frame */
  onValueChange?: (value: string) => void;
  /**
   * opt-in one-shot self-demo: a beat after mount the pill is flung to the
   * far segment, coasts, and captures into the detent. Plays exactly once,
   * never loops, is skipped under reduced motion, and is permanently
   * cancelled by any pointer or keyboard interaction.
   */
  introFling?: boolean;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** accessible name for the control. Default "View". */
  "aria-label"?: string;
}) {
  const trackRef = useRef<HTMLDivElement>(null);
  const pillRef = useRef<HTMLSpanElement>(null);
  const btnRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const engineRef = useRef<{
    goTo: (index: number, animate: boolean) => void;
  } | null>(null);
  const firstRef = useRef(true);

  const isControlled = value !== undefined;
  const [internal, setInternal] = useState(
    defaultValue ?? options[0]?.value ?? ""
  );
  const selectedValue = isControlled ? value : internal;
  let selectedIndex = options.findIndex((o) => o.value === selectedValue);
  if (selectedIndex < 0) selectedIndex = 0;

  const selectedRef = useRef(selectedIndex);
  selectedRef.current = selectedIndex;
  const optsLenRef = useRef(options.length);
  optsLenRef.current = options.length;
  const introRef = useRef(introFling);
  introRef.current = introFling;
  const introDoneRef = useRef(false); // survives option changes — plays once ever

  // instant commit path shared by click, keyboard, and the physics engine's
  // detent settle — fires onValueChange exactly once per selection change
  const setIndex = (i: number) => {
    const opt = options[i];
    if (!opt) return;
    if (!isControlled) setInternal(opt.value);
    if (opt.value !== selectedValue) onValueChange?.(opt.value);
  };
  const commitRef = useRef<(i: number) => void>(() => {});
  commitRef.current = setIndex;

  const optKey = options.map((o) => o.value).join("�");

  useEffect(() => {
    const track = trackRef.current;
    const pill = pillRef.current;
    if (!track || !pill) return;
    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    // -- hot-path state: locals only, never React state --------------------
    let segX: number[] = []; // offsetLeft per segment (track-relative)
    let segW: number[] = []; // offsetWidth per segment
    let minX = 0;
    let maxX = 0;
    let sized = false;
    let x = 0; // pill offset within the track's layout, px
    let v = 0; // px/s
    let w = 0; // pill width, px
    let wv = 0;
    let mode: 0 | 1 | 2 | 3 | 4 = 0; // idle | drag | coast | detent | glide
    let targetI = selectedRef.current;
    let deadline = 0;
    let raf = 0;
    let last = 0;
    let visible = true;

    // drag bookkeeping
    let pointerId = -1;
    let downX = 0;
    let basePillX = 0;
    let pointerX = 0;
    let samples: { t: number; x: number }[] = [];

    const render = () => {
      // beyond-track displacement renders scaled ×RUBBER (rubber band); the
      // physical x stays unscaled so the edge spring sees true displacement
      let rx = x;
      if (rx < minX) rx = minX + (rx - minX) * RUBBER;
      else if (rx > maxX) rx = maxX + (rx - maxX) * RUBBER;
      pill.style.width = `${w.toFixed(2)}px`;
      pill.style.transform = `translateX(${rx.toFixed(2)}px)`;
    };

    const nearest = () => {
      const center = x + w / 2;
      let best = 0;
      let bd = Infinity;
      for (let i = 0; i < segX.length; i++) {
        const d = Math.abs((segX[i] ?? 0) + (segW[i] ?? 0) / 2 - center);
        if (d < bd) {
          bd = d;
          best = i;
        }
      }
      return best;
    };

    const measure = () => {
      const btns: HTMLButtonElement[] = [];
      for (let i = 0; i < optsLenRef.current; i++) {
        const b = btnRefs.current[i];
        if (b) btns.push(b);
      }
      const rect = track.getBoundingClientRect();
      const first = btns[0];
      if (!first || rect.width < 8 || rect.height < 8) {
        sized = false; // zero-size guard — no physics into nothing
        pill.style.opacity = "0";
        return;
      }
      segX = btns.map((b) => b.offsetLeft);
      segW = btns.map((b) => b.offsetWidth);
      minX = segX[0] ?? 0;
      maxX = segX[segX.length - 1] ?? 0;
      pill.style.top = `${first.offsetTop}px`;
      pill.style.height = `${first.offsetHeight}px`;
      pill.style.opacity = "1";
      sized = true;
      if (mode === 0) {
        targetI = Math.min(targetI, segX.length - 1);
        x = segX[targetI] ?? 0;
        w = segW[targetI] ?? 0;
        v = wv = 0;
        render();
      }
    };

    const settle = () => {
      mode = 0;
      render();
      track.style.cursor = "";
      commitRef.current(targetI);
    };

    const loop = (now: number) => {
      raf = 0;
      const dt = last ? Math.min(0.032, (now - last) / 1000) : 1 / 60;
      last = now;
      if (!sized || mode === 0) return;
      let running = true;

      if (mode === 1) {
        // drag: pill tracks the pointer 1:1; width springs toward whichever
        // segment is currently nearest so unequal widths morph mid-drag
        x = basePillX + (pointerX - downX);
        const tw = segW[nearest()] ?? w;
        const c = 2 * DETENT_ZETA * Math.sqrt(DETENT_K);
        wv += (-DETENT_K * (w - tw) - c * wv) * dt;
        w += wv * dt;
      } else if (mode === 2) {
        if (x < minX || x > maxX) {
          // overshot an end — rubber-band spring hauls it back
          const edge = x < minX ? minX : maxX;
          const c = 2 * EDGE_ZETA * Math.sqrt(EDGE_K);
          v += (-EDGE_K * (x - edge) - c * v) * dt;
          x += v * dt;
          if (x >= minX && x <= maxX && Math.abs(v) < CAPTURE_V) {
            mode = 3;
            targetI = nearest();
          }
        } else {
          v *= Math.exp(-FRICTION * dt);
          x += v * dt;
          if (Math.abs(v) < CAPTURE_V) {
            mode = 3;
            targetI = nearest();
          }
        }
        const tw = segW[nearest()] ?? w;
        const c = 2 * DETENT_ZETA * Math.sqrt(DETENT_K);
        wv += (-DETENT_K * (w - tw) - c * wv) * dt;
        w += wv * dt;
      } else {
        // detent capture (one small overshoot) or click/keyboard glide
        const k = mode === 3 ? DETENT_K : GLIDE_K;
        const z = mode === 3 ? DETENT_ZETA : GLIDE_ZETA;
        const tx = segX[targetI] ?? 0;
        const tw = segW[targetI] ?? w;
        const c = 2 * z * Math.sqrt(k);
        v += (-k * (x - tx) - c * v) * dt;
        x += v * dt;
        wv += (-k * (w - tw) - c * wv) * dt;
        w += wv * dt;
        if (
          Math.abs(x - tx) < 0.3 &&
          Math.abs(v) < 8 &&
          Math.abs(w - tw) < 0.3 &&
          Math.abs(wv) < 8
        ) {
          x = tx;
          w = tw;
          v = wv = 0;
          running = false; // velocity-epsilon sleep
        }
      }

      // forced-settle deadline — physics never jitters forever
      if (mode !== 1 && now > deadline) {
        if (mode === 2) targetI = nearest();
        x = segX[targetI] ?? x;
        w = segW[targetI] ?? w;
        v = wv = 0;
        running = false;
      }

      if (!running) {
        settle();
        return;
      }
      render();
      if (visible && !document.hidden) raf = requestAnimationFrame(loop);
    };

    const wake = () => {
      if (!raf && !reduced && sized && mode !== 0 && visible && !document.hidden) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const goTo = (i: number, animate: boolean) => {
      if (!sized) {
        targetI = i;
        return;
      }
      if (mode === 1) return; // user owns the pill mid-drag
      targetI = Math.max(0, Math.min(i, segX.length - 1));
      if (reduced || !animate) {
        x = segX[targetI] ?? 0;
        w = segW[targetI] ?? 0;
        v = wv = 0;
        mode = 0;
        render();
        return;
      }
      if (mode === 0 && Math.abs(x - (segX[targetI] ?? 0)) < 0.5) return;
      mode = 4;
      deadline = performance.now() + SETTLE_MS;
      wake();
    };

    const finishDrag = (releaseV: number) => {
      pointerId = -1;
      if (mode !== 1) return;
      track.style.cursor = "";
      if (reduced) {
        // no coast — release selects the nearest segment instantly
        targetI = nearest();
        x = segX[targetI] ?? x;
        w = segW[targetI] ?? w;
        v = wv = 0;
        mode = 0;
        render();
        commitRef.current(targetI);
        return;
      }
      v = releaseV;
      x = basePillX + (pointerX - downX);
      mode = 2;
      deadline = performance.now() + SETTLE_MS;
      wake();
    };

    // -- one-shot intro fling (opt-in via introFling) -----------------------
    // scripted self-demo: the pill gets flung toward the far segment, coasts
    // on friction, nudges the end rubber band, and captures into the detent —
    // so a first-time viewer instantly sees the mechanic. Runs once shortly
    // after mount, never loops, skipped under reduced motion, permanently
    // cancelled by any pointer or keyboard interaction.
    let introTimer = 0;
    const cancelIntro = () => {
      introDoneRef.current = true;
      if (introTimer) {
        window.clearTimeout(introTimer);
        introTimer = 0;
      }
    };
    if (introRef.current && !reduced && !introDoneRef.current) {
      introTimer = window.setTimeout(() => {
        introTimer = 0;
        if (introDoneRef.current || !sized || mode !== 0) return;
        introDoneRef.current = true;
        const to = selectedRef.current === segX.length - 1 ? 0 : segX.length - 1;
        const d = (segX[to] ?? 0) - x;
        if (Math.abs(d) < 4) return;
        // release velocity sized so friction bleeds it to capture speed just
        // past the target — a visible coast plus one rubber-band nudge
        v = Math.sign(d) * (CAPTURE_V + FRICTION * Math.abs(d) + 60);
        mode = 2;
        deadline = performance.now() + SETTLE_MS;
        wake();
      }, INTRO_DELAY_MS);
    }

    const onDown = (e: PointerEvent) => {
      cancelIntro(); // any real interaction retires the self-demo for good
      if (e.button !== 0 || !sized || mode === 1) return;
      // is the press inside the pill's rendered span? (track coords; the 1px
      // track border is absorbed by the ±2px tolerance)
      const px = e.clientX - track.getBoundingClientRect().left;
      let rx = x;
      if (rx < minX) rx = minX + (rx - minX) * RUBBER;
      else if (rx > maxX) rx = maxX + (rx - maxX) * RUBBER;
      if (px < rx - 2 || px > rx + w + 2) return; // segment click path instead
      pointerId = e.pointerId;
      downX = e.clientX;
      pointerX = e.clientX;
      basePillX = x;
      v = wv = 0;
      samples = [{ t: e.timeStamp, x: e.clientX }];
      mode = 1; // catch the pill — even mid-flight
      track.style.cursor = "grabbing";
      try {
        track.setPointerCapture(e.pointerId);
      } catch {
        /* pointer already gone */
      }
      if (reduced) render();
      else wake();
    };

    const onMove = (e: PointerEvent) => {
      if (mode !== 1 || e.pointerId !== pointerId) return;
      pointerX = e.clientX;
      samples.push({ t: e.timeStamp, x: e.clientX });
      while (samples.length > 1 && e.timeStamp - (samples[0]?.t ?? 0) > 120)
        samples.shift();
      if (reduced) {
        x = Math.min(maxX, Math.max(minX, basePillX + (pointerX - downX)));
        w = segW[nearest()] ?? w;
        render();
      }
    };

    const onUp = (e: PointerEvent) => {
      if (e.pointerId !== pointerId) return;
      // release velocity = mean of pointer samples from the last 80 ms
      const cutoff = e.timeStamp - V_WINDOW;
      let i0 = 0;
      while (i0 < samples.length - 1 && (samples[i0]?.t ?? 0) < cutoff) i0++;
      const a = samples[i0];
      const b = samples[samples.length - 1];
      let rv = 0;
      if (a && b && b.t - a.t > 8) rv = ((b.x - a.x) / (b.t - a.t)) * 1000;
      finishDrag(rv);
    };

    const onCancel = (e: PointerEvent) => {
      if (e.pointerId !== pointerId) return;
      finishDrag(0);
    };

    measure();
    engineRef.current = { goTo };

    // -- observers ----------------------------------------------------------
    const ro = new ResizeObserver(measure);
    ro.observe(track);
    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible) wake();
      else {
        cancelAnimationFrame(raf);
        raf = 0; // offscreen — loop pauses, resumes on re-entry
      }
    });
    io.observe(track);
    const onVis = () => {
      if (!document.hidden) wake();
    };
    document.addEventListener("visibilitychange", onVis);
    track.addEventListener("keydown", cancelIntro, true);
    track.addEventListener("pointerdown", onDown);
    track.addEventListener("pointermove", onMove);
    track.addEventListener("pointerup", onUp);
    track.addEventListener("pointercancel", onCancel);

    return () => {
      cancelAnimationFrame(raf);
      if (introTimer) window.clearTimeout(introTimer); // teardown ≠ played
      ro.disconnect();
      io.disconnect();
      document.removeEventListener("visibilitychange", onVis);
      track.removeEventListener("keydown", cancelIntro, true);
      track.removeEventListener("pointerdown", onDown);
      track.removeEventListener("pointermove", onMove);
      track.removeEventListener("pointerup", onUp);
      track.removeEventListener("pointercancel", onCancel);
      track.style.cursor = "";
      engineRef.current = null;
    };
  }, [optKey]);

  // selection changes glide the pill; drag commits land here already parked
  // at the detent, so the glide is a no-op for them
  useEffect(() => {
    if (firstRef.current) {
      firstRef.current = false;
      return;
    }
    engineRef.current?.goTo(selectedIndex, true);
  }, [selectedIndex, optKey]);

  const onKeyDown = (e: React.KeyboardEvent) => {
    const n = options.length;
    if (n === 0) return;
    let next = -1;
    switch (e.key) {
      case "ArrowRight":
      case "ArrowDown":
        next = (selectedIndex + 1) % n;
        break;
      case "ArrowLeft":
      case "ArrowUp":
        next = (selectedIndex - 1 + n) % n;
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = n - 1;
        break;
      case " ":
      case "Enter":
        next = selectedIndex; // commit focused
        break;
      default:
        return;
    }
    e.preventDefault();
    setIndex(next);
    btnRefs.current[next]?.focus();
  };

  return (
    <div
      ref={trackRef}
      role="radiogroup"
      aria-label={ariaLabel}
      onKeyDown={onKeyDown}
      className={`group/fling relative inline-flex touch-pan-y select-none items-center rounded-sm border border-border bg-foreground/[0.04] p-1 ${className}`}
    >
      <span
        ref={pillRef}
        aria-hidden
        className="absolute left-0 top-0 rounded-[5px] border border-border bg-background opacity-0 shadow-[0_1px_2px_rgba(0,0,0,0.12)] transition-shadow duration-150 will-change-transform group-has-[button[aria-checked=true]:hover]/fling:shadow-[0_3px_8px_rgba(0,0,0,0.24)]"
      >
        {/* grip affordance — six dots hugging the pill's right edge say
            "this is a handle"; they brighten when the pill is hovered */}
        <span className="absolute right-[5px] top-1/2 grid -translate-y-1/2 grid-cols-2 gap-[3px]">
          {[0, 1, 2, 3, 4, 5].map((i) => (
            <span
              key={i}
              className="h-[2px] w-[2px] rounded-full bg-foreground/25 transition-colors duration-150 group-has-[button[aria-checked=true]:hover]/fling:bg-foreground/50"
            />
          ))}
        </span>
      </span>
      {options.map((opt, i) => {
        const selected = i === selectedIndex;
        return (
          <button
            key={opt.value}
            ref={(el) => {
              btnRefs.current[i] = el;
            }}
            type="button"
            role="radio"
            aria-checked={selected}
            tabIndex={selected ? 0 : -1}
            onClick={() => setIndex(i)}
            className={`relative rounded-[5px] px-3.5 py-1.5 text-sm font-medium outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ns-accent ${
              selected
                ? "cursor-grab text-foreground active:cursor-grabbing"
                : "cursor-pointer text-ns-muted hover:text-foreground"
            }`}
          >
            {opt.label}
          </button>
        );
      })}
    </div>
  );
}

"use client";

import { useEffect, useId, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// CausticSelect — single-select whose closed trigger and open listbox are
// frosted glass over live caustic light: 6-8 drifting radial blobs summed
// additively on a canvas BENEATH each surface's backdrop-filter layer, so the
// blur turns them into pooled light. Opening scale-springs the panel from the
// trigger while blob anchors spring-redistribute down the list height; the
// active row (cursor OR keyboard — one target) carries a lens that bends
// nearby caustics up to 6px toward the row so the highlight reads as pressed
// into the glass. Direct-DOM rAF: fully asleep while closed, paused offscreen
// and on hidden tabs, lens has a 1s forced-settle deadline. All drawn ink is
// derived from CSS tokens at mount and re-derived on documentElement class
// changes. Full listbox keyboard pattern with aria-activedescendant.
// ---------------------------------------------------------------------------

const TRIGGER_BLOBS = 6;
const PANEL_BLOBS = 8;
const DRIFT_MIN = 6; // px/s peak drift speed per blob
const DRIFT_MAX = 10;
const OPEN_MS = 180;
const ANCHOR_K = 60; // s^-2 — blob anchor redistribution spring
const ANCHOR_ZETA = 0.9;
const LENS_K = 140; // s^-2 — lens follow spring
const LENS_ZETA = 0.8;
const LENS_R = 56; // px displacement field radius
const LENS_PULL = 6; // px max pull toward the active row center
const SETTLE_MS = 1000; // forced-settle deadline after last input
const TYPEAHEAD_MS = 500;

type Vec3 = readonly [number, number, number];

interface CausticBlob {
  ax: number; // anchor position (spring state)
  ay: number;
  vx: number;
  vy: number;
  tx: number; // anchor target
  ty: number;
  amp: number; // drift amplitude px
  wx: number; // drift angular frequency rad/s (amp*wx = peak px/s)
  wy: number;
  phase: number;
  phase2: number;
  r: number;
  rf: number; // persistent per-blob randoms (radius / layout jitter)
  jx: number;
  jy: number;
  mixT: number; // 0 = --ns-accent, 1 = --foreground
  alpha: number; // 0.06-0.10
}

interface Lens {
  x: number;
  y: number;
  vx: number;
  vy: number;
  tx: number;
  ty: number;
  s: number; // strength 0..1
  ts: number;
  on: boolean;
}

export interface CausticSelectOption {
  value: string;
  label: string;
  /** mono hint rendered right of the label (e.g. a region code) */
  hint?: string;
  disabled?: boolean;
}

const DEFAULT_OPTIONS: CausticSelectOption[] = [
  { value: "iad1", label: "Washington, D.C.", hint: "iad1" },
  { value: "sfo1", label: "San Francisco", hint: "sfo1" },
  { value: "fra1", label: "Frankfurt", hint: "fra1" },
  { value: "hnd1", label: "Tokyo", hint: "hnd1" },
  { value: "syd1", label: "Sydney", hint: "syd1" },
  { value: "gru1", label: "São Paulo", hint: "gru1" },
];

// deterministic PRNG — blob character is stable across opens in-session
function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function parseColor(raw: string): Vec3 | null {
  const s = raw.trim();
  if (s.startsWith("#")) {
    const hex = s.slice(1);
    if (hex.length === 3) {
      const r = parseInt(hex.slice(0, 1) + hex.slice(0, 1), 16);
      const g = parseInt(hex.slice(1, 2) + hex.slice(1, 2), 16);
      const b = parseInt(hex.slice(2, 3) + hex.slice(2, 3), 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    if (hex.length >= 6) {
      const r = parseInt(hex.slice(0, 2), 16);
      const g = parseInt(hex.slice(2, 4), 16);
      const b = parseInt(hex.slice(4, 6), 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    return null;
  }
  const m = s.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
}

function mix(a: Vec3, b: Vec3, t: number): Vec3 {
  return [
    Math.round(a[0] + (b[0] - a[0]) * t),
    Math.round(a[1] + (b[1] - a[1]) * t),
    Math.round(a[2] + (b[2] - a[2]) * t),
  ];
}

export function CausticSelect({
  options = DEFAULT_OPTIONS,
  value,
  defaultValue = "",
  onValueChange,
  label = "Region",
  placeholder = "Select a region",
  disabled = false,
  name,
  className = "",
}: {
  /** the selectable options */
  options?: CausticSelectOption[];
  /** controlled value; omit for uncontrolled */
  value?: string;
  /** uncontrolled initial value */
  defaultValue?: string;
  /** called with the new value when a different option is selected */
  onValueChange?: (value: string) => void;
  /** field label rendered above the trigger */
  label?: string;
  /** shown on the trigger while no option is selected */
  placeholder?: string;
  /** blocks the trigger and closes the popover if open */
  disabled?: boolean;
  /** when set, renders a hidden input for form posts */
  name?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}) {
  const uid = useId();
  const labelId = `${uid}-label`;
  const valueId = `${uid}-value`;
  const listboxId = `${uid}-listbox`;
  const optId = (i: number) => `${uid}-opt-${i}`;

  const rootRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const trigCanvasRef = useRef<HTMLCanvasElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const panelCanvasRef = useRef<HTMLCanvasElement>(null);
  const listboxRef = useRef<HTMLUListElement>(null);
  const engineRef = useRef<{
    opened: () => void;
    closed: () => void;
    setLens: (i: number) => void;
  } | null>(null);

  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const openRef = useRef(open);

  const isControlled = value !== undefined;
  const [internal, setInternal] = useState(defaultValue);
  const val = isControlled ? value : internal;
  const selected = options.find((o) => o.value === val) ?? null;

  const typeRef = useRef<{ buf: string; timer: number }>({ buf: "", timer: 0 });

  // -- caustic engine: one mount effect, direct-DOM hot path -----------------
  useEffect(() => {
    const root = rootRef.current;
    const trigger = triggerRef.current;
    const tCanvas = trigCanvasRef.current;
    const panel = panelRef.current;
    const pCanvas = panelCanvasRef.current;
    const listbox = listboxRef.current;
    if (!root || !trigger || !tCanvas || !panel || !pCanvas || !listbox) return;
    const tCtx = tCanvas.getContext("2d");
    const pCtx = pCanvas.getContext("2d");
    if (!tCtx || !pCtx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    // token-derived ink: read at mount, re-derived on theme class change
    let accent: Vec3 = [0, 107, 255];
    let fg: Vec3 = [237, 237, 237];
    const derive = () => {
      const cs = getComputedStyle(document.documentElement);
      accent = parseColor(cs.getPropertyValue("--ns-accent")) ?? accent;
      fg = parseColor(cs.getPropertyValue("--foreground")) ?? fg;
    };
    derive();

    const rand = mulberry32(0x5eaf00d);
    const makeBlobs = (n: number): CausticBlob[] => {
      const arr: CausticBlob[] = [];
      for (let i = 0; i < n; i++) {
        const amp = 10 + rand() * 6;
        const speed = DRIFT_MIN + rand() * (DRIFT_MAX - DRIFT_MIN);
        arr.push({
          ax: 0,
          ay: 0,
          vx: 0,
          vy: 0,
          tx: 0,
          ty: 0,
          amp,
          wx: speed / amp,
          wy: (speed / amp) * 0.83,
          phase: rand() * Math.PI * 2,
          phase2: rand() * Math.PI * 2,
          r: 40,
          rf: rand(),
          jx: rand(),
          jy: rand(),
          mixT: i % 2 === 0 ? 0.12 + rand() * 0.2 : 0.65 + rand() * 0.3,
          alpha: 0.06 + rand() * 0.04,
        });
      }
      return arr;
    };
    const tBlobs = makeBlobs(TRIGGER_BLOBS);
    const pBlobs = makeBlobs(PANEL_BLOBS);

    // hot-path state: locals only, never React state
    let dpr = 1;
    let tW = 0;
    let tH = 0;
    let pW = 0;
    let pH = 0;
    let tSized = false;
    let pSized = false;
    let raf = 0;
    let last = 0;
    let visible = true;
    let lastInput = 0;
    let anim: Animation | null = null;
    const lens: Lens = {
      x: 0,
      y: 0,
      vx: 0,
      vy: 0,
      tx: 0,
      ty: 0,
      s: 0,
      ts: 0,
      on: false,
    };

    // <canvas> is a replaced element — inset never sizes it; set BOTH the CSS
    // size and the backing store explicitly. offsetWidth/Height ignore the
    // open-scale transform, so layout stays honest mid-animation.
    const sizeCanvas = (
      host: HTMLElement,
      canvas: HTMLCanvasElement
    ): { w: number; h: number; ok: boolean } => {
      const w = host.offsetWidth;
      const h = host.offsetHeight;
      if (w < 8 || h < 8) return { w: 0, h: 0, ok: false }; // zero-size guard
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.style.width = `${w}px`;
      canvas.style.height = `${h}px`;
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
      return { w, h, ok: true };
    };

    const layoutTrigger = () => {
      const n = tBlobs.length;
      for (let i = 0; i < n; i++) {
        const b = tBlobs[i];
        if (!b) continue;
        b.tx = tW * ((i + 0.5) / n) + (b.jx - 0.5) * tW * 0.25;
        b.ty = tH * (0.2 + b.jy * 0.6);
        b.r = 20 + b.rf * 22;
        b.ax = b.tx; // trigger anchors never spring — targets ARE positions
        b.ay = b.ty;
      }
    };
    // redistribute anchors evenly down the list height, jittered laterally
    const layoutPanel = () => {
      const n = pBlobs.length;
      for (let i = 0; i < n; i++) {
        const b = pBlobs[i];
        if (!b) continue;
        b.ty = pH * ((i + 0.5) / n) + (b.jy - 0.5) * pH * 0.12;
        b.tx = pW * (0.12 + b.jx * 0.76);
        b.r = 42 + b.rf * 40;
      }
    };

    // full clear + full redraw every frame — additive blobs must never
    // accumulate (destination-in style fades quantize and pile up forever)
    const drawSurface = (
      ctx: CanvasRenderingContext2D,
      blobs: CausticBlob[],
      w: number,
      h: number,
      t: number,
      lensRef: Lens | null
    ) => {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      ctx.globalCompositeOperation = "lighter";
      for (const b of blobs) {
        let x = b.ax + Math.sin(t * b.wx + b.phase) * b.amp;
        let y = b.ay + Math.cos(t * b.wy + b.phase2) * b.amp;
        let boost = 0;
        if (lensRef && lensRef.s > 0.01) {
          const dx = lensRef.x - x;
          const dy = lensRef.y - y;
          const dist = Math.hypot(dx, dy);
          if (dist > 0.01 && dist < LENS_R) {
            const f = (1 - dist / LENS_R) * lensRef.s;
            x += (dx / dist) * LENS_PULL * f;
            y += (dy / dist) * LENS_PULL * f;
            boost = 0.05 * f;
          }
        }
        const c = mix(accent, fg, b.mixT);
        const a = b.alpha + boost;
        const g = ctx.createRadialGradient(x, y, 0, x, y, b.r);
        g.addColorStop(0, `rgba(${c[0]},${c[1]},${c[2]},${a.toFixed(3)})`);
        g.addColorStop(1, `rgba(${c[0]},${c[1]},${c[2]},0)`);
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(x, y, b.r, 0, Math.PI * 2);
        ctx.fill();
      }
      // the lens itself: a tight accent pool pressed under the active row
      if (lensRef && lensRef.s > 0.01) {
        const a = 0.09 * lensRef.s;
        const g = ctx.createRadialGradient(
          lensRef.x,
          lensRef.y,
          0,
          lensRef.x,
          lensRef.y,
          LENS_R
        );
        g.addColorStop(
          0,
          `rgba(${accent[0]},${accent[1]},${accent[2]},${a.toFixed(3)})`
        );
        g.addColorStop(1, `rgba(${accent[0]},${accent[1]},${accent[2]},0)`);
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(lensRef.x, lensRef.y, LENS_R, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.globalCompositeOperation = "source-over";
    };

    const drawTriggerStatic = () => {
      if (tSized) drawSurface(tCtx, tBlobs, tW, tH, 0, null);
    };
    const drawPanelStatic = () => {
      if (!pSized) return;
      for (const b of pBlobs) {
        b.ax = b.tx;
        b.ay = b.ty;
        b.vx = 0;
        b.vy = 0;
      }
      drawSurface(pCtx, pBlobs, pW, pH, 0, null);
    };

    const loop = (now: number) => {
      raf = 0;
      if (!openRef.current) return; // canvas fully asleep while closed
      const dt = last ? Math.min(0.033, (now - last) / 1000) : 1 / 60;
      last = now;
      const t = now / 1000;

      // anchor redistribution springs (k=60, zeta=0.9, ~450ms settle)
      const cA = 2 * ANCHOR_ZETA * Math.sqrt(ANCHOR_K);
      for (const b of pBlobs) {
        b.vx += (-ANCHOR_K * (b.ax - b.tx) - cA * b.vx) * dt;
        b.vy += (-ANCHOR_K * (b.ay - b.ty) - cA * b.vy) * dt;
        b.ax += b.vx * dt;
        b.ay += b.vy * dt;
      }

      // lens follow spring (k=140, zeta=0.8) + forced-settle deadline —
      // never trusts epsilon alone
      if (lens.on) {
        if (now - lastInput > SETTLE_MS) {
          lens.x = lens.tx;
          lens.y = lens.ty;
          lens.vx = 0;
          lens.vy = 0;
          lens.s = lens.ts;
        } else {
          const cL = 2 * LENS_ZETA * Math.sqrt(LENS_K);
          lens.vx += (-LENS_K * (lens.x - lens.tx) - cL * lens.vx) * dt;
          lens.vy += (-LENS_K * (lens.y - lens.ty) - cL * lens.vy) * dt;
          lens.x += lens.vx * dt;
          lens.y += lens.vy * dt;
          lens.s += (lens.ts - lens.s) * Math.min(1, dt * 12);
        }
      }

      if (tSized) drawSurface(tCtx, tBlobs, tW, tH, t, null);
      if (pSized) drawSurface(pCtx, pBlobs, pW, pH, t, lens.on ? lens : null);

      // idle simmer is the ambient default while open; sleeps offscreen/hidden
      if (visible && !document.hidden) raf = requestAnimationFrame(loop);
    };
    const wake = () => {
      if (!raf && !reduced && openRef.current && visible && !document.hidden) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const resizeTrigger = () => {
      const s = sizeCanvas(trigger, tCanvas);
      tW = s.w;
      tH = s.h;
      tSized = s.ok;
      if (tSized) layoutTrigger();
      if (!openRef.current || reduced) drawTriggerStatic();
    };
    const resizePanel = () => {
      const s = sizeCanvas(panel, pCanvas);
      pW = s.w;
      pH = s.h;
      pSized = s.ok;
      if (pSized) layoutPanel();
    };
    resizeTrigger();

    const opened = () => {
      resizePanel();
      lens.on = false;
      lens.s = 0;
      lens.ts = 0;
      if (reduced) {
        // static frost texture, instant open — no drift, no lens
        drawTriggerStatic();
        drawPanelStatic();
        return;
      }
      // anchors start clustered at the transform origin, spring outward
      for (const b of pBlobs) {
        b.ax = pW / 2 + (b.jx - 0.5) * pW * 0.3;
        b.ay = b.jy * 18;
        b.vx = 0;
        b.vy = 0;
      }
      anim?.cancel();
      anim = panel.animate(
        [
          { transform: "scale(0.96)", opacity: 0 },
          { transform: "scale(1)", opacity: 1 },
        ],
        { duration: OPEN_MS, easing: "cubic-bezier(0.16, 1, 0.3, 1)" }
      );
      wake();
    };

    const closed = () => {
      anim?.cancel();
      anim = null;
      if (raf) {
        cancelAnimationFrame(raf);
        raf = 0;
      }
      lens.on = false;
      lens.s = 0;
      drawTriggerStatic();
    };

    const setLens = (i: number) => {
      if (!openRef.current || reduced) return;
      const row = listbox.children.item(i) as HTMLElement | null;
      if (!row) return;
      // panel is DOM-anchored: lens works in panel-local offsets, never
      // absolute canvas/page coordinates
      const pr = panel.getBoundingClientRect();
      const rr = row.getBoundingClientRect();
      const cx = rr.left - pr.left + rr.width / 2;
      const cy = rr.top - pr.top + rr.height / 2;
      if (!lens.on) {
        lens.x = cx;
        lens.y = cy;
        lens.vx = 0;
        lens.vy = 0;
        lens.on = true;
      }
      lens.tx = cx;
      lens.ty = cy;
      lens.ts = 1;
      lastInput = performance.now();
      wake();
    };

    engineRef.current = { opened, closed, setLens };

    // -- observers ----------------------------------------------------------
    const ro = new ResizeObserver(() => {
      resizeTrigger();
      if (openRef.current) {
        resizePanel();
        if (reduced) drawPanelStatic();
        wake();
      }
    });
    ro.observe(trigger);
    ro.observe(panel);
    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible) wake();
    });
    io.observe(root);
    // live theme re-derive: watch documentElement class flips
    const mo = new MutationObserver(() => {
      derive();
      if (!openRef.current) drawTriggerStatic();
      else if (reduced) {
        drawTriggerStatic();
        drawPanelStatic();
      }
      // open + animating: next loop frame repaints with the new ink
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });
    const onVis = () => {
      if (!document.hidden) wake();
    };
    document.addEventListener("visibilitychange", onVis);

    return () => {
      cancelAnimationFrame(raf);
      anim?.cancel();
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", onVis);
      engineRef.current = null;
    };
  }, []);

  // -- open/close orchestration ----------------------------------------------
  useEffect(() => {
    openRef.current = open;
    const eng = engineRef.current;
    if (!eng) return;
    if (open) {
      eng.opened();
      listboxRef.current?.focus({ preventScroll: true });
    } else {
      eng.closed();
    }
  }, [open]);

  useEffect(() => {
    if (!open || activeIndex < 0) return;
    const el = listboxRef.current?.children.item(activeIndex) as
      | HTMLElement
      | null;
    el?.scrollIntoView({ block: "nearest" });
    engineRef.current?.setLens(activeIndex);
  }, [open, activeIndex]);

  useEffect(() => {
    if (!open) return;
    const onDown = (e: PointerEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) {
        setOpen(false);
        triggerRef.current?.focus();
      }
    };
    document.addEventListener("pointerdown", onDown);
    return () => document.removeEventListener("pointerdown", onDown);
  }, [open]);

  useEffect(() => {
    if (disabled && open) setOpen(false);
  }, [disabled, open]);

  useEffect(() => {
    const t = typeRef.current;
    return () => window.clearTimeout(t.timer);
  }, []);

  // -- selection + keyboard --------------------------------------------------
  const firstEnabled = () => options.findIndex((o) => !o.disabled);
  const lastEnabled = () => {
    for (let i = options.length - 1; i >= 0; i--) {
      const o = options[i];
      if (o && !o.disabled) return i;
    }
    return -1;
  };
  const step = (from: number, dir: 1 | -1) => {
    let i = from;
    for (let k = 0; k < options.length; k++) {
      i += dir;
      if (i < 0 || i >= options.length) break;
      const o = options[i];
      if (o && !o.disabled) return i;
    }
    return from;
  };

  const openList = () => {
    if (disabled || open || options.length === 0) return;
    const sel = options.findIndex((o) => o.value === val && !o.disabled);
    setActiveIndex(sel >= 0 ? sel : firstEnabled());
    setOpen(true);
  };
  const closeList = (restoreFocus: boolean) => {
    typeRef.current.buf = "";
    setOpen(false);
    if (restoreFocus) triggerRef.current?.focus();
  };
  const commit = (i: number) => {
    const o = options[i];
    if (!o || o.disabled) return;
    if (!isControlled) setInternal(o.value);
    onValueChange?.(o.value);
    closeList(true);
  };

  const typeahead = (ch: string) => {
    const t = typeRef.current;
    t.buf += ch.toLowerCase();
    window.clearTimeout(t.timer);
    t.timer = window.setTimeout(() => {
      t.buf = "";
    }, TYPEAHEAD_MS);
    const n = options.length;
    const start = activeIndex >= 0 ? activeIndex : 0;
    const offset = t.buf.length > 1 ? 0 : 1;
    for (let k = 0; k < n; k++) {
      const i = (start + offset + k) % n;
      const o = options[i];
      if (o && !o.disabled && o.label.toLowerCase().startsWith(t.buf)) {
        setActiveIndex(i);
        return;
      }
    }
  };

  const onTriggerKeyDown = (e: React.KeyboardEvent) => {
    if (disabled) return;
    if (
      e.key === "Enter" ||
      e.key === " " ||
      e.key === "ArrowDown" ||
      e.key === "ArrowUp"
    ) {
      e.preventDefault();
      openList();
    }
  };

  const onListKeyDown = (e: React.KeyboardEvent) => {
    const key = e.key;
    if (key === "ArrowDown") {
      e.preventDefault();
      setActiveIndex((a) => step(a, 1));
    } else if (key === "ArrowUp") {
      e.preventDefault();
      setActiveIndex((a) => step(a, -1));
    } else if (key === "Home") {
      e.preventDefault();
      const i = firstEnabled();
      if (i >= 0) setActiveIndex(i);
    } else if (key === "End") {
      e.preventDefault();
      const i = lastEnabled();
      if (i >= 0) setActiveIndex(i);
    } else if (key === "Enter" || (key === " " && typeRef.current.buf === "")) {
      e.preventDefault();
      commit(activeIndex);
    } else if (key === "Escape") {
      e.preventDefault();
      closeList(true);
    } else if (key === "Tab") {
      closeList(false);
    } else if (key.length === 1 && !e.altKey && !e.ctrlKey && !e.metaKey) {
      e.preventDefault();
      typeahead(key);
    }
  };

  return (
    <div ref={rootRef} className={`relative ${className}`}>
      <span
        id={labelId}
        className="mb-1.5 block font-mono text-xs uppercase tracking-[0.14em] text-ns-muted"
      >
        {label}
      </span>
      {name ? <input type="hidden" name={name} value={val} /> : null}

      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={open ? listboxId : undefined}
        aria-labelledby={`${labelId} ${valueId}`}
        disabled={disabled}
        onClick={() => (open ? closeList(true) : openList())}
        onKeyDown={onTriggerKeyDown}
        className="relative flex h-10 w-full items-center justify-between overflow-hidden rounded-sm border border-border text-left outline-none transition-colors hover:border-foreground/25 focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:cursor-not-allowed disabled:opacity-50 motion-reduce:transition-none disabled:pointer-events-none"
      >
        {/* caustic light beneath the frost */}
        <canvas
          ref={trigCanvasRef}
          aria-hidden
          className="pointer-events-none absolute left-0 top-0"
        />
        {/* the frost itself: backdrop-filter blurs the canvas under it */}
        <span
          aria-hidden
          className="pointer-events-none absolute inset-0 bg-surface/55 backdrop-blur-md backdrop-saturate-150"
        />
        <span
          id={valueId}
          className={`relative z-[1] truncate px-3 text-sm ${
            selected ? "text-foreground" : "text-ns-muted"
          }`}
        >
          {selected ? selected.label : placeholder}
        </span>
        <svg
          aria-hidden
          viewBox="0 0 16 16"
          fill="none"
          className={`relative z-[1] mr-3 h-4 w-4 shrink-0 text-ns-muted transition-transform duration-200 motion-reduce:transition-none ${
            open ? "rotate-180" : ""
          }`}
        >
          <path
            d="M4 6l4 4 4-4"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      </button>

      <div
        ref={panelRef}
        className={`absolute left-0 right-0 top-full z-30 mt-2 overflow-hidden rounded-md border border-border shadow-[0_8px_16px_-4px_rgba(0,0,0,0.2),0_20px_48px_-12px_rgba(0,0,0,0.35)] ${
          open ? "" : "hidden"
        }`}
        style={{ transformOrigin: "50% 0%" }}
      >
        <canvas
          ref={panelCanvasRef}
          aria-hidden
          className="pointer-events-none absolute left-0 top-0"
        />
        <div
          aria-hidden
          className="pointer-events-none absolute inset-0 bg-surface/70 backdrop-blur-xl backdrop-saturate-150"
        />
        <ul
          ref={listboxRef}
          id={listboxId}
          role="listbox"
          tabIndex={-1}
          aria-labelledby={labelId}
          aria-activedescendant={
            open && activeIndex >= 0 ? optId(activeIndex) : undefined
          }
          onKeyDown={onListKeyDown}
          onScroll={() => {
            if (activeIndex >= 0) engineRef.current?.setLens(activeIndex);
          }}
          className="relative z-[1] max-h-72 overflow-y-auto py-1.5 outline-none"
        >
          {options.map((opt, i) => {
            const isActive = i === activeIndex;
            const isSelected = opt.value === val;
            return (
              <li
                key={opt.value}
                id={optId(i)}
                role="option"
                aria-selected={isSelected}
                aria-disabled={opt.disabled || undefined}
                onPointerMove={() => {
                  if (!opt.disabled && i !== activeIndex) setActiveIndex(i);
                }}
                onPointerDown={(e) => e.preventDefault()}
                onClick={() => {
                  if (!opt.disabled) commit(i);
                }}
                className={`flex items-center justify-between gap-3 px-3 py-2 text-sm transition-colors duration-100 motion-reduce:transition-none ${
                  opt.disabled
                    ? "cursor-not-allowed text-ns-muted/60"
                    : isActive
                      ? "cursor-pointer bg-foreground/[0.07] text-foreground"
                      : "cursor-pointer text-foreground/85"
                }`}
              >
                <span className="flex min-w-0 items-baseline gap-2">
                  <span className="truncate">{opt.label}</span>
                  {opt.hint ? (
                    <span className="shrink-0 font-mono text-[11px] text-ns-muted">
                      {opt.hint}
                    </span>
                  ) : null}
                </span>
                {isSelected ? (
                  <svg
                    aria-hidden
                    viewBox="0 0 16 16"
                    fill="none"
                    className="h-4 w-4 shrink-0 text-ns-accent"
                  >
                    <path
                      d="M3.5 8.5l3 3 6-6.5"
                      stroke="currentColor"
                      strokeWidth="1.5"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                ) : null}
              </li>
            );
          })}
        </ul>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// ServingMalletWind — a card-scale ambient loader modelled on marlinspike
// seamanship's "serving" pass: protecting a line from chafe by tightly
// winding small stuff (twine) around it so each turn lies flush against its
// neighbour, worked with a serving mallet that both delivers and beds down
// the turns as it travels the rope's length.
//
// The rope is a continuous horizontal feed: bare rope drifts in from the
// right, covered (served) rope drifts out to the left, so the served/bare
// boundary can sit at a FIXED screen x (canvas centre) forever, with work
// never running out. Two decoupled clocks drive it: a fast, un-followable
// wrap texture (rendered as continuous scrolling helical hatching, never
// claimed as individually countable turns) and a slow, deliberately
// followable turn-lock highlight that sweeps once around the rope's
// circumference and snaps into place every 0.9s — the one thing a viewer's
// eye is meant to track. Cylinder shading is luminance-only (no hue); the
// served/bare step is a hard boundary, ridged vs smooth.
//
// Colour is read once via getComputedStyle(document.documentElement) with
// no literal fallback of any kind, retried on rAF until every token
// resolves, and re-read on every documentElement class flip. Geometry is
// derived from the container's smaller dimension.
// ---------------------------------------------------------------------------

const FEED_PX_S = 22; // continuous rope drift, bare-to-covered
const WRAP_PITCH = 4; // px between helical wrap lines (fast, decorative texture only)
const LOCK_INTERVAL_S = 0.9; // the one followable cadence
const LOCK_SWEEP_FRAC = 0.7; // fraction of the interval spent sweeping vs held settled
const ZONE_W = 46; // px, fixed on screen — the working band straddling the boundary
const DIAMETER_RATIO = 1 / 8; // rope diameter = minDim * this

interface Tokens {
  fg: string;
  muted: string;
}

function readTokens(): Tokens | null {
  if (typeof document === "undefined") return null;
  const cs = getComputedStyle(document.documentElement);
  const fg = cs.getPropertyValue("--foreground").trim();
  const muted = cs.getPropertyValue("--ns-muted").trim();
  if (!fg || !muted) return null; // stylesheet not applied yet — paint nothing
  return { fg, muted };
}

// -- the rope's "lay": three incommensurate sine periods sampled in MATERIAL
// coordinates (screen x + accumulated feed), so a fixed screen point shows
// different material as the rope drifts under it — without this the rope
// has no identity and t0/2.5s/5s are indistinguishable whenever the lock
// highlight happens to land on the same phase. Range approx [-1, 1]. --------
function laySignal(xMaterial: number): number {
  return (
    Math.sin(xMaterial / 53) * 0.5 +
    Math.sin(xMaterial / 89 + 1.7) * 0.3 +
    Math.sin(xMaterial / 137 + 0.4) * 0.2
  );
}

export interface ServingMalletWindProps {
  /** small mono label above the rope (default "Serving in progress") */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function ServingMalletWind({
  label = "Serving in progress",
  className = "",
}: ServingMalletWindProps) {
  const wrapRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const wrap = wrapRef.current;
    const canvas = canvasRef.current;
    if (!wrap || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let disposed = false;
    let tokens: Tokens | null = null;
    let dpr = 1;
    let w = 0;
    let h = 0;
    let sized = false;
    let visible = true;

    let start = 0; // performance.now() at t=0
    let raf = 0;
    let tokenWaitRaf = 0;

    const fitCanvas = () => {
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };

    const layout = () => {
      const minDim = Math.min(w, h);
      const diameter = minDim * DIAMETER_RATIO;
      const cy = h / 2;
      const ropeTop = cy - diameter / 2;
      const ropeBottom = cy + diameter / 2;
      const boundaryX = w / 2; // fixed screen position: bare enters right, served exits left
      return { minDim, diameter, ropeTop, ropeBottom, boundaryX };
    };

    // -- one frame: elapsedS drives the feed (fast, continuous) and the
    // lock cadence (slow, discrete-feeling) independently. -----------------
    const draw = (elapsedS: number) => {
      if (!tokens || !sized) return;
      const t = tokens;
      const { diameter, ropeTop, ropeBottom, boundaryX } = layout();
      const ropeH = ropeBottom - ropeTop;
      ctx.clearRect(0, 0, w, h);
      if (diameter <= 0) return;

      const feedPx = elapsedS * FEED_PX_S;
      // working zone: transition to fully-served begins at the boundary and
      // finishes ZONE_W into the bare side.
      const zoneRight = boundaryX + ZONE_W;

      // -- base cylinder: a faint vertical sheen (luminance only, no hue),
      // shared by bare and served rope alike so both read as the same
      // physical line. ------------------------------------------------------
      ctx.save();
      ctx.beginPath();
      ctx.rect(0, ropeTop, w, ropeH);
      ctx.clip();

      const sheen = ctx.createLinearGradient(0, ropeTop, 0, ropeBottom);
      sheen.addColorStop(0, t.muted);
      sheen.addColorStop(0.5, t.fg);
      sheen.addColorStop(1, t.muted);
      ctx.globalAlpha = 0.16;
      ctx.fillStyle = sheen;
      ctx.fillRect(0, ropeTop, w, ropeH);

      // -- lay variation: coarse, aperiodic luminance mottling sampled in
      // material coordinates (x + feedPx), present across the WHOLE rope so
      // both halves carry an identity that visibly drifts — this is what
      // makes t0/2.5s/5s different even between lock-highlight events. -----
      const LAY_STEP = 6;
      ctx.fillStyle = t.fg;
      for (let x = 0; x < w; x += LAY_STEP) {
        const s = laySignal(x + feedPx);
        ctx.globalAlpha = 0.1 + 0.09 * s;
        ctx.fillRect(x, ropeTop, LAY_STEP + 0.5, ropeH);
      }

      // -- served half (x <= boundaryX): higher-contrast base + a continuous
      // scrolling helical wrap texture, ramping in across the ZONE_W working
      // band (boundaryX..zoneRight) rather than starting/stopping instantly,
      // so the mallet's footprint is the transition and the boundary itself
      // is where it finishes — the hard luminance step. The pitch (4px) is
      // far finer than any followable cadence, so it is rendered purely as
      // texture — no single turn is claimed as individually trackable. -----
      const rampAt = (x: number) => Math.max(0, Math.min(1, (zoneRight - x) / ZONE_W));

      const servedGrad = ctx.createLinearGradient(zoneRight, 0, boundaryX, 0);
      servedGrad.addColorStop(0, "transparent");
      servedGrad.addColorStop(1, t.fg);
      ctx.globalAlpha = 0.22;
      ctx.fillStyle = servedGrad;
      ctx.fillRect(0, ropeTop, zoneRight, ropeH);

      const slant = ropeH * 0.55;
      const phase = ((feedPx % WRAP_PITCH) + WRAP_PITCH) % WRAP_PITCH;
      ctx.strokeStyle = t.fg;
      ctx.lineWidth = 1;
      // established region (fully served, left of the boundary): one batched
      // stroke at full alpha.
      ctx.globalAlpha = 0.5;
      ctx.beginPath();
      for (let x = boundaryX - phase; x > -slant; x -= WRAP_PITCH) {
        ctx.moveTo(x, ropeTop);
        ctx.lineTo(x - slant, ropeBottom);
      }
      ctx.stroke();
      // working zone (boundaryX..zoneRight): each line ramps in individually.
      for (let x = boundaryX + WRAP_PITCH - phase; x < zoneRight + slant; x += WRAP_PITCH) {
        ctx.globalAlpha = 0.5 * rampAt(x);
        ctx.beginPath();
        ctx.moveTo(x, ropeTop);
        ctx.lineTo(x - slant, ropeBottom);
        ctx.stroke();
      }
      ctx.restore();

      // -- bare half (x > zoneRight): smooth flat gradient + lay mottling
      // only, no ridge — the point, per spec: bare rope drift is not itself
      // meant to be legible, only what happens to it once served. ----------

      // -- hard luminance step at the boundary itself. ------------------------
      ctx.globalAlpha = 0.4;
      ctx.strokeStyle = t.fg;
      ctx.lineWidth = Math.max(1, diameter * 0.03);
      ctx.beginPath();
      ctx.moveTo(boundaryX, ropeTop);
      ctx.lineTo(boundaryX, ropeBottom);
      ctx.stroke();

      // -- turn-lock highlight: the ONE followable event. Sweeps once around
      // the rope's circumference (rendered as vertical travel across the
      // cylinder, since we view it side-on) and snaps to the newest fully
      // seated turn every LOCK_INTERVAL_S. Luminance-only, --foreground —
      // never --ns-accent, matching the recipe's pointer-highlight rule
      // even though this highlight has no pointer behind it. -----------------
      const lockPhase = elapsedS % LOCK_INTERVAL_S;
      const sweepDur = LOCK_INTERVAL_S * LOCK_SWEEP_FRAC;
      let highlightY: number;
      let highlightAlpha: number;
      if (lockPhase < sweepDur) {
        // linear, not eased — a viewer needs to see it travel the WHOLE
        // rope diameter over the WHOLE sweep, not jump most of the way in
        // the first frame and then appear to sit still (the exact "blink,
        // not a sweep" failure the round's legibility rule calls out).
        const p = lockPhase / sweepDur;
        highlightY = ropeTop + p * ropeH;
        highlightAlpha = 0.4 + 0.3 * p;
      } else {
        // snap: a brief brightness peak on arrival, decaying through the hold.
        const holdP = (lockPhase - sweepDur) / (LOCK_INTERVAL_S - sweepDur);
        highlightY = ropeBottom;
        highlightAlpha = 0.95 - 0.35 * holdP;
      }
      // Concentric fills at descending alpha (never a colour-stop-to-bg
      // gradient, which punches an opaque hole instead of glowing) — the
      // repo's proven idiom for a soft point light in a single token.
      const glowR = Math.max(2, diameter * 0.2);
      ctx.save();
      ctx.beginPath();
      ctx.rect(0, ropeTop, w, ropeH);
      ctx.clip();
      ctx.fillStyle = t.fg;
      for (const [rFrac, aFrac] of [
        [1, 0.22],
        [0.6, 0.45],
        [0.3, 0.9],
      ] as const) {
        ctx.globalAlpha = highlightAlpha * aFrac;
        ctx.beginPath();
        ctx.arc(boundaryX, highlightY, glowR * rFrac, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();

      ctx.globalAlpha = 1;
    };

    const resize = () => {
      const rect = wrap.getBoundingClientRect();
      if (rect.width < 4 || rect.height < 4) {
        sized = false;
        return;
      }
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      w = rect.width;
      h = rect.height;
      fitCanvas();
      sized = true;
    };

    const loop = (now: number) => {
      if (disposed) return;
      if (!visible) {
        raf = 0; // re-armed by the IntersectionObserver on re-entry
        return;
      }
      raf = requestAnimationFrame(loop);
      if (!sized || !tokens) return;
      if (start === 0) start = now;
      draw((now - start) / 1000);
    };

    let started = false;
    const kick = () => {
      if (started || disposed || !tokens || !sized) return;
      started = true;
      if (reduced) {
        // LOCK_SETTLED: frozen exactly on a lock-interval boundary, highlight
        // fully snapped (not mid-sweep), served/bare halves both maximally
        // legible. No rAF loop, no timers, no observers driving motion.
        const settledElapsed = LOCK_INTERVAL_S * (LOCK_SWEEP_FRAC + (1 - LOCK_SWEEP_FRAC) / 2);
        draw(settledElapsed);
        return;
      }
      raf = requestAnimationFrame(loop);
    };

    const boot = () => {
      if (disposed) return;
      tokens = readTokens();
      if (!tokens) {
        tokenWaitRaf = requestAnimationFrame(boot);
        return;
      }
      resize();
      kick();
    };

    const ro = new ResizeObserver(() => {
      if (!tokens) return;
      resize();
      if (reduced) {
        const settledElapsed = LOCK_INTERVAL_S * (LOCK_SWEEP_FRAC + (1 - LOCK_SWEEP_FRAC) / 2);
        draw(settledElapsed);
      }
      kick();
    });
    ro.observe(wrap);

    const mo = new MutationObserver(() => {
      tokens = readTokens();
      if (!tokens) return;
      if (reduced) {
        const settledElapsed = LOCK_INTERVAL_S * (LOCK_SWEEP_FRAC + (1 - LOCK_SWEEP_FRAC) / 2);
        draw(settledElapsed);
      } else if (sized && start !== 0) {
        draw((performance.now() - start) / 1000);
      }
      kick();
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    const io = new IntersectionObserver((entries) => {
      const wasVisible = visible;
      visible = entries[0]?.isIntersecting ?? true;
      if (visible && !wasVisible && !reduced && tokens && !raf) {
        tokens = readTokens() ?? tokens; // pick up a theme flip that happened while hidden
        resize();
        raf = requestAnimationFrame(loop);
      }
    });
    io.observe(wrap);

    boot();

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      cancelAnimationFrame(tokenWaitRaf);
      ro.disconnect();
      mo.disconnect();
      io.disconnect();
    };
  }, []);

  return (
    <div
      ref={wrapRef}
      className={`relative w-full max-w-sm overflow-hidden rounded-md border border-border bg-surface p-4 ${className}`}
    >
      <p className="mb-3 font-mono text-[11px] tracking-widest text-ns-muted">{label}</p>
      <div className="relative w-full" style={{ aspectRatio: "5 / 2" }}>
        <canvas ref={canvasRef} aria-hidden="true" className="pointer-events-none absolute inset-0 h-full w-full" />
      </div>
    </div>
  );
}

"use client";

// ---------------------------------------------------------------------------
// ShearerAdvance — a "loading more rows" strip for an infinite-scroll or
// virtualised list, built on real longwall coal-mining mechanics rather than
// an invented spinner shape.
//
// A shearer (the small drummed unit) traverses back and forth along a coal
// face, its two rotating drums cutting a slice on every pass. Cut material
// drops onto an armoured face conveyor (the dashed line beneath it), which
// carries it away in one constant direction, independent of the shearer's
// travel direction — exactly like a real AFC. Behind the shearer, hydraulic
// roof supports (the small prop-and-cap glyphs) release from the roof, nose
// forward, and re-set in sequence as the cut passes them, one after another
// in a travelling wave rather than all at once.
//
// The mapping onto the UI concept: the shearer's traverse across the face IS
// the fetch in flight; the conveyor carrying material away IS the response
// data moving into the list; the supports advancing behind it IS the list
// growing, one row taking its turn after another rather than the whole list
// updating at once. `loading` keeps the face working; `exhausted` parks the
// machine — a longwall panel that has been fully worked, not a machine that
// broke or a wheel that spins forever implying infinite content.
//
// House idiom: colors are read directly as `var(--token)` in SVG
// presentation attributes (the same convention loader-thread-spool uses) —
// SVG supports custom-property references natively, so no
// getComputedStyle/MutationObserver token pipeline is needed here the way a
// <canvas> component would require. One mount-time rAF loop writes transform
// attributes directly to a handful of refs every frame (never React state
// per frame); geometry that only changes on resize goes through normal
// React state instead. The loop pauses via IntersectionObserver (offscreen)
// and `visibilitychange` (hidden tab), matching every other ambient
// component in the registry.
// ---------------------------------------------------------------------------

import { useEffect, useLayoutEffect, useRef, useState } from "react";

const N_SUPPORTS = 7;
const LEG_MS = 2400; // time for one traverse of the face, one direction
const CYCLE_MS = LEG_MS * 2; // full back-and-forth pass
const DRUM_REV_MS = 620; // one drum revolution
const CONVEYOR_CYCLE_MS = 900; // time for the AFC dash pattern to repeat
// half-width (in leg-fraction units) of the window around a support's cross
// point during which it's mid-advance. Wide enough that several supports
// (spacing 1/N_SUPPORTS ~= 0.143) overlap at any instant — the row reads as
// a phase-lagged wave with multiple supports at different stages, not one
// dot hopping down the line.
const BUMP_WINDOW = 0.22;
const DY_MAX = 4; // px a support's cap drops off the roof while advancing
const DX_MAX = 2.5; // px a support noses forward while advancing
const STATIC_TIME_MS = 1650; // reduced-motion freeze frame, mid-leg, staggered supports

function triangleWave(t: number, period: number): number {
  const x = (t % period) / period;
  return x < 0.5 ? x * 2 : 2 - x * 2;
}

function smoothstep(t: number): number {
  const c = Math.max(0, Math.min(1, t));
  return c * c * (3 - 2 * c);
}

interface Frame {
  u: number; // 0-1 shearer position along the face
  drumDeg: number;
  conveyorOffset: number;
  supports: { dx: number; dy: number }[]; // length N_SUPPORTS
}

// A support's advance is staged, not a single blended nod: lower (cap drops
// off the roofline) -> step (noses forward at full drop) -> reset (cap
// re-seats). `n` is the support's own progress through its pulse window,
// 0 at entry, 1 at exit — directly derived from elapsed leg time, so the
// three stages always play in that order as the shearer's pass reaches it.
function supportOffset(n: number, stepSign: number): { dx: number; dy: number } {
  if (n <= 0 || n >= 1) return { dx: 0, dy: 0 };
  if (n < 1 / 3) {
    return { dx: 0, dy: DY_MAX * smoothstep(n / (1 / 3)) };
  }
  if (n < 2 / 3) {
    return { dx: DX_MAX * stepSign * smoothstep((n - 1 / 3) / (1 / 3)), dy: DY_MAX };
  }
  const local = (n - 2 / 3) / (1 / 3);
  return {
    dx: DX_MAX * stepSign * (1 - smoothstep(local)),
    dy: DY_MAX * (1 - smoothstep(local)),
  };
}

function computeFrame(tMs: number): Frame {
  const inRightLeg = tMs % CYCLE_MS < LEG_MS;
  const u = triangleWave(tMs, CYCLE_MS);
  const legProgress = inRightLeg ? u : 1 - u;
  const stepSign = inRightLeg ? 1 : -1;

  const supports = Array.from({ length: N_SUPPORTS }, (_, i) => {
    const p = (i + 0.5) / N_SUPPORTS;
    const crossFrac = inRightLeg ? p : 1 - p;
    const d = legProgress - crossFrac;
    if (Math.abs(d) > BUMP_WINDOW) return { dx: 0, dy: 0 };
    const n = (d + BUMP_WINDOW) / (2 * BUMP_WINDOW); // 0 entering the window -> 1 leaving it
    return supportOffset(n, stepSign);
  });

  return {
    u,
    drumDeg: ((tMs / DRUM_REV_MS) * 360) % 360,
    conveyorOffset: ((tMs / CONVEYOR_CYCLE_MS) * -16) % 8,
    supports,
  };
}

// shared geometry so the rAF paint step and the static JSX layout never
// disagree about where the shearer body/drums sit
function getGeometry(w: number, h: number) {
  const margin = Math.max(12, h * 0.35);
  const faceLeft = margin;
  const faceWidth = Math.max(0, w - margin * 2);
  const bodyW = Math.min(26, faceWidth * 0.2);
  return { margin, faceLeft, faceWidth, bodyW };
}

// parked geometry for the terminal "no more rows" state: shearer at the end
// of the worked-out panel, drums stopped, every support fully re-set, AFC
// still (nothing left to carry)
const PARKED_FRAME: Frame = {
  u: 1,
  drumDeg: 0,
  conveyorOffset: 0,
  supports: Array.from({ length: N_SUPPORTS }, () => ({ dx: 0, dy: 0 })),
};

export interface ShearerAdvanceProps {
  /** true while more rows are being fetched; the face keeps working while true. Default true. */
  loading?: boolean;
  /** true once the list has no more rows; parks the machine and stops the conveyor. Default false. */
  exhausted?: boolean;
  /** accessible label override; defaults to a message describing loading/exhausted state. */
  "aria-label"?: string;
  /** strip height in px. Default 40; drum/cap geometry scales down with it (not visually verified below ~28px in this build). */
  height?: number;
  className?: string;
}

export function ShearerAdvance({
  loading = true,
  exhausted = false,
  "aria-label": ariaLabel,
  height = 40,
  className = "",
}: ShearerAdvanceProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const [width, setWidth] = useState(0);
  const [reducedMotion, setReducedMotion] = useState(false);

  const shearerRef = useRef<SVGGElement>(null);
  const drumARef = useRef<SVGGElement>(null);
  const drumBRef = useRef<SVGGElement>(null);
  const conveyorRef = useRef<SVGLineElement>(null);
  const supportOuterRefs = useRef<(SVGGElement | null)[]>([]);
  const supportPropRefs = useRef<(SVGLineElement | null)[]>([]);
  const supportCapRefs = useRef<(SVGLineElement | null)[]>([]);

  // width from ResizeObserver, geometry-affecting so it goes through state
  useLayoutEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const ro = new ResizeObserver((entries) => {
      const w = entries[0]?.contentRect.width;
      if (w) setWidth(w);
    });
    ro.observe(el);
    setWidth(el.getBoundingClientRect().width);
    return () => ro.disconnect();
  }, []);

  useLayoutEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReducedMotion(mq.matches);
    const onChange = (e: MediaQueryListEvent) => setReducedMotion(e.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  const active = loading && !exhausted && !reducedMotion;
  const roofY = Math.max(4, height * 0.12);
  const conveyorY = height - 6;

  const paint = (frame: Frame, w: number) => {
    const { faceLeft, faceWidth, bodyW } = getGeometry(w, height);
    const cx = faceLeft + frame.u * faceWidth;

    if (shearerRef.current) {
      shearerRef.current.style.transform = `translateX(${(cx - bodyW / 2).toFixed(2)}px)`;
    }
    if (drumARef.current) drumARef.current.style.transform = `rotate(${frame.drumDeg}deg)`;
    if (drumBRef.current) drumBRef.current.style.transform = `rotate(${(-frame.drumDeg).toFixed(2)}deg)`;
    if (conveyorRef.current) conveyorRef.current.style.strokeDashoffset = `${frame.conveyorOffset}`;

    for (let i = 0; i < N_SUPPORTS; i++) {
      const outer = supportOuterRefs.current[i];
      const prop = supportPropRefs.current[i];
      const cap = supportCapRefs.current[i];
      const s = frame.supports[i];
      // dy shortens the prop from the top and carries the cap with it, so
      // the cap detaches from the roof and re-seats flush on it rather than
      // floating free of its own prop; dx (the "step") moves prop+cap
      // together via the outer group.
      const y = roofY + s.dy;
      if (outer) outer.style.transform = `translateX(${s.dx.toFixed(2)}px)`;
      if (prop) prop.setAttribute("y1", y.toFixed(2));
      if (cap) {
        cap.setAttribute("y1", y.toFixed(2));
        cap.setAttribute("y2", y.toFixed(2));
      }
    }
  };

  // static states: exhausted (parked), reduced motion, or simply not
  // currently loading — every non-live state gets a deliberately-chosen
  // full paint, never a leftover mid-motion frame from before the loop
  // stopped.
  useEffect(() => {
    if (width <= 0 || active) return;
    paint(exhausted ? PARKED_FRAME : computeFrame(STATIC_TIME_MS), width);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [active, exhausted, width, height]);

  // live rAF loop: only while actually loading, not exhausted, motion allowed
  useEffect(() => {
    if (!active || width <= 0) return;
    const root = rootRef.current;
    if (!root) return;

    let raf = 0;
    let running = true;
    const start = performance.now();

    const tick = (now: number) => {
      if (!running) return;
      paint(computeFrame(now - start), width);
      raf = requestAnimationFrame(tick);
    };

    const io = new IntersectionObserver(
      (entries) => {
        const visible = entries[0]?.isIntersecting ?? true;
        if (visible && !document.hidden) {
          if (!raf) raf = requestAnimationFrame(tick);
        } else if (raf) {
          cancelAnimationFrame(raf);
          raf = 0;
        }
      },
      { threshold: 0 }
    );
    io.observe(root);

    const onVisibility = () => {
      if (document.hidden && raf) {
        cancelAnimationFrame(raf);
        raf = 0;
      } else if (!document.hidden && !raf) {
        raf = requestAnimationFrame(tick);
      }
    };
    document.addEventListener("visibilitychange", onVisibility);

    raf = requestAnimationFrame(tick);

    return () => {
      running = false;
      io.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
      if (raf) cancelAnimationFrame(raf);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [active, width, height]);

  const statusText =
    ariaLabel ??
    (exhausted ? "No more rows to load" : "Loading more rows");

  const capW = 8;
  const propBottom = height - 6;

  return (
    <div
      ref={rootRef}
      role="status"
      aria-busy={loading && !exhausted}
      aria-label={statusText}
      className={`w-full select-none ${className}`}
      style={{ height }}
    >
      <span className="sr-only">{statusText}</span>
      {width > 0 && (
        <svg
          data-shearer-advance-svg
          width={width}
          height={height}
          aria-hidden
          className="block overflow-visible"
        >
          {/* roofline — structural boundary, not machinery */}
          <line
            x1={4}
            y1={roofY}
            x2={width - 4}
            y2={roofY}
            stroke="var(--border)"
            strokeWidth={1}
          />

          {/* armoured face conveyor: carries cut material away, one constant
              direction, independent of the shearer's travel direction */}
          <line
            ref={conveyorRef}
            x1={4}
            y1={conveyorY}
            x2={width - 4}
            y2={conveyorY}
            stroke="var(--foreground)"
            strokeWidth={1.5}
            strokeDasharray="2 6"
            strokeLinecap="round"
          />

          {/* hydraulic roof supports, evenly spaced along the face */}
          {Array.from({ length: N_SUPPORTS }, (_, i) => {
            const { faceLeft, faceWidth } = getGeometry(width, height);
            const p = (i + 0.5) / N_SUPPORTS;
            const sx = faceLeft + p * faceWidth;
            return (
              <g
                key={i}
                ref={(el) => {
                  supportOuterRefs.current[i] = el;
                }}
              >
                {/* prop: shortens from the top (y1 rises/falls in the paint
                    loop) so retracting from the roof reads as the prop
                    itself compressing, not a piece floating loose */}
                <line
                  ref={(el) => {
                    supportPropRefs.current[i] = el;
                  }}
                  x1={sx}
                  y1={roofY}
                  x2={sx}
                  y2={propBottom}
                  stroke="var(--ns-muted)"
                  strokeWidth={1.25}
                />
                {/* cap: always flush with the prop's current top (same y as
                    the prop's y1, written together in the paint loop) */}
                <line
                  ref={(el) => {
                    supportCapRefs.current[i] = el;
                  }}
                  x1={sx - capW / 2}
                  y1={roofY}
                  x2={sx + capW / 2}
                  y2={roofY}
                  stroke="var(--foreground)"
                  strokeWidth={2}
                  strokeLinecap="round"
                />
              </g>
            );
          })}

          {/* the shearer: body + two rotating cutting drums. Drum position is
              baked into their own geometry (cx, transform-origin) rather than
              a `transform="translate(...)"` attribute, because setting
              `style.transform` for the rAF-driven spin would otherwise wipe
              out an attribute-based translate outright — SVG lets a CSS
              transform fully replace the presentation-attribute one. */}
          <g ref={shearerRef}>
            {(() => {
              const { bodyW } = getGeometry(width, height);
              const drumBX = bodyW - 3;
              return (
                <>
                  <rect
                    x={0}
                    y={height / 2 - 5}
                    width={bodyW}
                    height={10}
                    rx={2}
                    fill="var(--background)"
                    stroke="var(--foreground)"
                    strokeWidth={1.5}
                  />
                  <g ref={drumARef} style={{ transformOrigin: "3px center" }}>
                    <circle cx={3} cy={height / 2} r={5} fill="var(--background)" stroke="var(--foreground)" strokeWidth={1.5} />
                    <line x1={3} y1={height / 2} x2={7.5} y2={height / 2} stroke="var(--foreground)" strokeWidth={1.25} />
                  </g>
                  <g ref={drumBRef} style={{ transformOrigin: `${drumBX}px center` }}>
                    <circle cx={drumBX} cy={height / 2} r={5} fill="var(--background)" stroke="var(--foreground)" strokeWidth={1.5} />
                    <line x1={drumBX} y1={height / 2} x2={drumBX + 4.5} y2={height / 2} stroke="var(--foreground)" strokeWidth={1.25} />
                  </g>
                </>
              );
            })()}
          </g>

          {/* end-of-panel stop, only meaningful (and only drawn) once the
              face has actually been worked out */}
          {exhausted && (
            <line
              x1={width - 4}
              y1={roofY}
              x2={width - 4}
              y2={conveyorY}
              stroke="var(--ns-muted)"
              strokeWidth={2}
            />
          )}
        </svg>
      )}
    </div>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// SheetAsciiRange — a spreadsheet-style rectangular range select. Dragging
// (or Shift+Arrow from a roving-tabindex active cell) grows a rectangle of
// cells; the rectangle's own perimeter is drawn from real box-drawing glyphs
// (┌─┐│└┘) positioned on the seams between cells, and a live ASCII status
// bar prints the aggregate (n / sum / mean / min / max) of whatever is
// currently inside it. The aggregate recomputes on every cell the rectangle
// gains or loses, whether that came from a pointer drag or a keystroke — the
// mechanic is the rectangle-of-cells selection itself, not a cell's visual
// style (table-heat-shimmer is a fixed table whose HOT rows shimmer; nothing
// here is selectable). No canvas: every glyph is a real DOM span positioned
// on the cell grid, colored from tokens via Tailwind classes only.
// ---------------------------------------------------------------------------

type Cell = { r: number; c: number };

export interface SheetAsciiRangeProps {
  /** rows x cols numeric grid */
  data?: number[][];
  /** label for each row, left of the grid */
  rowLabels?: string[];
  /** label for each column, above the grid */
  colLabels?: string[];
  /** unit suffix printed after aggregate numbers, e.g. "units" */
  unit?: string;
  /** heading above the grid */
  title?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const DEFAULT_DATA: number[][] = [
  [42, 58, 61, 33, 70, 45, 52, 39],
  [55, 63, 47, 71, 38, 60, 44, 57],
  [31, 49, 66, 52, 59, 41, 68, 36],
  [64, 40, 53, 62, 46, 73, 35, 50],
  [48, 57, 34, 65, 51, 43, 69, 32],
  [37, 61, 56, 48, 67, 54, 42, 60],
];

const DEFAULT_ROW_LABELS = ["MON", "TUE", "WED", "THU", "FRI", "SAT"];
const DEFAULT_COL_LABELS = ["W1", "W2", "W3", "W4", "W5", "W6", "W7", "W8"];

function clamp(v: number, lo: number, hi: number) {
  return Math.min(hi, Math.max(lo, v));
}

function fmt(n: number): string {
  return Number.isInteger(n) ? String(n) : n.toFixed(1);
}

export function SheetAsciiRange({
  data = DEFAULT_DATA,
  rowLabels = DEFAULT_ROW_LABELS,
  colLabels = DEFAULT_COL_LABELS,
  unit = "units",
  title = "Shipment log",
  className = "",
}: SheetAsciiRangeProps) {
  const rows = data.length;
  const cols = data[0]?.length ?? 0;

  const [anchor, setAnchor] = useState<Cell | null>(null);
  const [focus, setFocus] = useState<Cell>({ r: 0, c: 0 });
  const draggingRef = useRef(false);
  const gridRef = useRef<HTMLDivElement>(null);

  const rect = useMemo(() => {
    if (!anchor) return null;
    return {
      top: Math.min(anchor.r, focus.r),
      bottom: Math.max(anchor.r, focus.r),
      left: Math.min(anchor.c, focus.c),
      right: Math.max(anchor.c, focus.c),
    };
  }, [anchor, focus]);

  const stats = useMemo(() => {
    if (!rect) return { n: 0, sum: 0, mean: 0, min: 0, max: 0 };
    let n = 0;
    let sum = 0;
    let min = Infinity;
    let max = -Infinity;
    for (let r = rect.top; r <= rect.bottom; r++) {
      for (let c = rect.left; c <= rect.right; c++) {
        const v = data[r]?.[c] ?? 0;
        n++;
        sum += v;
        if (v < min) min = v;
        if (v > max) max = v;
      }
    }
    return { n, sum, mean: n ? sum / n : 0, min: n ? min : 0, max: n ? max : 0 };
  }, [rect, data]);

  const inRect = useCallback(
    (r: number, c: number) => !!rect && r >= rect.top && r <= rect.bottom && c >= rect.left && c <= rect.right,
    [rect]
  );

  const startDrag = (cell: Cell) => {
    draggingRef.current = true;
    setAnchor(cell);
    setFocus(cell);
  };

  const dragTo = (cell: Cell) => {
    if (draggingRef.current) setFocus(cell);
  };

  useEffect(() => {
    const end = () => {
      draggingRef.current = false;
    };
    window.addEventListener("pointerup", end);
    return () => window.removeEventListener("pointerup", end);
  }, []);

  const focusCellButton = (r: number, c: number) => {
    gridRef.current?.querySelector<HTMLButtonElement>(`[data-r="${r}"][data-c="${c}"]`)?.focus();
  };

  const moveActive = (dr: number, dc: number, extend: boolean) => {
    const nr = clamp(focus.r + dr, 0, rows - 1);
    const nc = clamp(focus.c + dc, 0, cols - 1);
    if (extend) {
      if (!anchor) setAnchor(focus);
      setFocus({ r: nr, c: nc });
    } else {
      setAnchor({ r: nr, c: nc });
      setFocus({ r: nr, c: nc });
    }
    focusCellButton(nr, nc);
  };

  const onKeyDown = (e: React.KeyboardEvent) => {
    const map: Record<string, [number, number]> = {
      ArrowUp: [-1, 0],
      ArrowDown: [1, 0],
      ArrowLeft: [0, -1],
      ArrowRight: [0, 1],
    };
    const delta = map[e.key];
    if (!delta) return;
    e.preventDefault();
    moveActive(delta[0], delta[1], e.shiftKey);
  };

  return (
    <div className={`inline-flex flex-col gap-2 font-mono ${className}`}>
      <div className="flex items-center justify-between gap-3">
        <span className="text-xs uppercase tracking-widest text-ns-muted">{title}</span>
        <span className="text-[10px] uppercase tracking-widest text-ns-muted">drag or shift+arrow to select</span>
      </div>

      <div
        ref={gridRef}
        role="grid"
        aria-label={`${title} cell grid`}
        className="relative inline-grid select-none rounded-sm border border-border bg-surface p-2"
        style={{
          gridTemplateColumns: `3.5em repeat(${cols}, 3em)`,
        }}
      >
        <div />
        {colLabels.map((label) => (
          <div key={label} className="px-1 py-1 text-center text-[10px] text-ns-muted">
            {label}
          </div>
        ))}

        {rowLabels.map((rowLabel, r) => (
          <div key={rowLabel} className="contents">
            <div className="flex items-center px-1 text-[10px] text-ns-muted">{rowLabel}</div>
            {Array.from({ length: cols }, (_, c) => {
              const value = data[r]?.[c] ?? 0;
              const selected = inRect(r, c);
              const isActive = focus.r === r && focus.c === c;
              const isTop = selected && r === rect!.top;
              const isBottom = selected && r === rect!.bottom;
              const isLeft = selected && c === rect!.left;
              const isRight = selected && c === rect!.right;

              let corner: string | null = null;
              if (isTop && isLeft) corner = "corner-tl";
              else if (isTop && isRight) corner = "corner-tr";
              else if (isBottom && isLeft) corner = "corner-bl";
              else if (isBottom && isRight) corner = "corner-br";

              const glyph =
                corner === "corner-tl"
                  ? "┌"
                  : corner === "corner-tr"
                    ? "┐"
                    : corner === "corner-bl"
                      ? "└"
                      : corner === "corner-br"
                        ? "┘"
                        : isTop || isBottom
                          ? "─"
                          : isLeft || isRight
                            ? "│"
                            : null;

              return (
                <button
                  key={`${r}-${c}`}
                  type="button"
                  data-r={r}
                  data-c={c}
                  role="gridcell"
                  aria-selected={selected}
                  aria-label={`${rowLabel} ${colLabels[c]}: ${fmt(value)} ${unit}`}
                  tabIndex={isActive ? 0 : -1}
                  className={`relative flex h-8 items-center justify-end px-1.5 text-xs tabular-nums text-foreground outline-none transition-colors duration-100 motion-reduce:transition-none hover:bg-foreground/[0.06] focus-visible:z-10 focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ns-accent ${
                    selected ? "bg-ns-accent/[0.09]" : ""
                  }`}
                  onPointerDown={() => startDrag({ r, c })}
                  onPointerEnter={() => dragTo({ r, c })}
                  onFocus={() => setFocus({ r, c })}
                  onKeyDown={onKeyDown}
                >
                  {fmt(value)}
                  {glyph && (
                    <span
                      aria-hidden
                      data-glyph={corner ?? (isTop ? "top" : isBottom ? "bottom" : isLeft ? "left" : "right")}
                      className={`absolute select-none text-[11px] leading-none text-foreground ${
                        corner
                          ? corner === "corner-tl"
                            ? "-left-px -top-px -translate-x-1/2 -translate-y-1/2"
                            : corner === "corner-tr"
                              ? "-right-px -top-px translate-x-1/2 -translate-y-1/2"
                              : corner === "corner-bl"
                                ? "-bottom-px -left-px -translate-x-1/2 translate-y-1/2"
                                : "-bottom-px -right-px translate-x-1/2 translate-y-1/2"
                          : isTop
                            ? "inset-x-0 -top-px -translate-y-1/2 text-center"
                            : isBottom
                              ? "inset-x-0 -bottom-px translate-y-1/2 text-center"
                              : isLeft
                                ? "inset-y-0 -left-px -translate-x-1/2 flex items-center"
                                : "inset-y-0 -right-px translate-x-1/2 flex items-center"
                      }`}
                    >
                      {glyph}
                    </span>
                  )}
                </button>
              );
            })}
          </div>
        ))}
      </div>

      <div
        data-status-bar
        aria-live="polite"
        className="rounded-sm border border-border bg-background px-3 py-1.5 text-[11px] tabular-nums text-ns-muted"
      >
        {stats.n > 0 ? (
          <>
            <span className="text-foreground">n={stats.n}</span>
            {"  Σ="}
            <span className="text-foreground">{fmt(stats.sum)}</span>
            {"  x̄="}
            <span className="text-foreground">{fmt(stats.mean)}</span>
            {"  min="}
            <span className="text-foreground">{fmt(stats.min)}</span>
            {"  max="}
            <span className="text-foreground">{fmt(stats.max)}</span>
            {` ${unit}`}
          </>
        ) : (
          "n=0 — click a cell or drag a range"
        )}
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useId, useMemo, useRef, useState } from "react";

// A keyboard-shortcut cheat sheet that owns the keyboard while it is up.
// Shortcuts render as physical keycaps; every real keydown that matches a
// listed combo depresses that specific cap and flashes it in --ns-accent, and the
// event is swallowed (preventDefault + stopPropagation in the capture phase)
// so the app's own handler behind the overlay does not also fire. You can
// rehearse a shortcut and watch its keys press themselves — clicking a row
// plays the same press, one step at a time for sequences like "G then P".
//
// Everything modal comes from the native <dialog> opened with showModal():
// focus trap, background inertness, top-layer stacking, ::backdrop and
// Escape-to-close are the platform's, not a hand-rolled trap.
//
// The part that actually decides whether this works is normalization, and it
// is deliberately not a string compare. A chord is a set of required modifier
// flags plus one canonical base key. Matching runs two passes: an exact pass
// where every modifier flag must agree, then a lenient pass that ignores Shift
// for single printable characters — "?" arrives as {key:"?", shiftKey:true} on
// US layouts, so a naive exact compare against the token "?" never fires,
// while a blanket "ignore shift" would make Mod+Shift+Z indistinguishable from
// Mod+Z. Exact-first gives both. "Mod" folds to metaKey on Apple and ctrlKey
// elsewhere and never to both, so a plain Ctrl press on a Mac does not match a
// Mod shortcut. Letters and digits additionally accept e.code (KeyK / Digit1)
// when the chord carries a modifier, which is what rescues non-Latin layouts
// where e.key is a Cyrillic or Greek character.

const MODIFIER_KEYS = new Set(["Shift", "Control", "Alt", "Meta", "CapsLock", "OS"]);
const SEQUENCE_WINDOW_MS = 1200; // how long "G" waits for its "P"
const STEP_GAP_MS = 60; // pause between rehearsed steps

/** One chord: the modifier flags it requires plus its single base key. */
export type QuickKeyChord = {
  /** Display tokens, in the order they were authored. */
  tokens: string[];
  /** Canonical base key: "K", "?", "ESC", "ENTER", "↑", "SPACE"… */
  base: string;
  ctrl: boolean;
  meta: boolean;
  shift: boolean;
  alt: boolean;
};

export type QuickKeyShortcut = {
  /**
   * Tokens: "Mod" | "Ctrl" | "Meta" | "Shift" | "Alt" plus one key per chord
   * ("K", "?", "Enter", "Esc", "↑", "Space"). A literal "then" token starts a
   * new chord, so ["G", "then", "P"] is a two-step sequence.
   */
  keys: string[];
  label: string;
};

export type QuickKeySection = { title: string; items: QuickKeyShortcut[] };

export interface QuickKeyProps {
  /** Grouped shortcut list. Rendered in order; sections flow into `columns`. */
  sections: QuickKeySection[];
  /** Controlled open state. Omit to run uncontrolled from `defaultOpen`. */
  open?: boolean;
  /** Uncontrolled initial state. Ignored when `open` is passed. */
  defaultOpen?: boolean;
  /** Fired for every close the platform can originate: Escape, backdrop, the close button. */
  onOpenChange?: (open: boolean) => void;
  /** heading above the sections */
  title?: string;
  /** number of columns the sections flow into */
  columns?: 1 | 2;
  /** Match real keydowns and flash the matching caps. Default true. */
  liveEcho?: boolean;
  /** How long a cap stays depressed, ms. Default 180. */
  echoDuration?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

/* ---------------------------------------------------------------- parsing */

const NAMED_BASE: Record<string, string> = {
  esc: "ESC",
  escape: "ESC",
  enter: "ENTER",
  return: "ENTER",
  tab: "TAB",
  space: "SPACE",
  spacebar: "SPACE",
  backspace: "BACKSPACE",
  delete: "DELETE",
  del: "DELETE",
  up: "↑",
  down: "↓",
  left: "←",
  right: "→",
  arrowup: "↑",
  arrowdown: "↓",
  arrowleft: "←",
  arrowright: "→",
};

/** Fold an author token or an `event.key` onto one canonical spelling. */
export function canonicalBase(raw: string): string {
  if (raw === " ") return "SPACE";
  if (raw.length === 1) return raw.toUpperCase();
  return NAMED_BASE[raw.toLowerCase()] ?? raw.toUpperCase();
}

/** Split `keys` on "then" and parse each chord. `isApple` decides what Mod folds to. */
export function parseShortcut(keys: string[], isApple: boolean): QuickKeyChord[] {
  const steps: string[][] = [[]];
  for (const token of keys) {
    if (/^(then|>)$/i.test(token)) steps.push([]);
    else steps[steps.length - 1].push(token);
  }
  return steps
    .filter((tokens) => tokens.length > 0)
    .map((tokens) => {
      const chord: QuickKeyChord = { tokens, base: "", ctrl: false, meta: false, shift: false, alt: false };
      for (const token of tokens) {
        switch (token.toLowerCase()) {
          case "mod":
            if (isApple) chord.meta = true;
            else chord.ctrl = true;
            break;
          case "ctrl":
          case "control":
          case "⌃":
            chord.ctrl = true;
            break;
          case "meta":
          case "cmd":
          case "command":
          case "⌘":
            chord.meta = true;
            break;
          case "shift":
          case "⇧":
            chord.shift = true;
            break;
          case "alt":
          case "opt":
          case "option":
          case "⌥":
            chord.alt = true;
            break;
          default:
            chord.base = canonicalBase(token);
        }
      }
      return chord;
    });
}

/** The subset of KeyboardEvent matching reads — so it can be exercised with a literal. */
export type QuickKeyEvent = {
  key: string;
  code?: string;
  ctrlKey: boolean;
  metaKey: boolean;
  shiftKey: boolean;
  altKey: boolean;
};

function baseMatches(chord: QuickKeyChord, e: QuickKeyEvent): boolean {
  if (canonicalBase(e.key) === chord.base) return true;
  // Physical-position fallback. Only for letters/digits, and only when the
  // chord carries a modifier — otherwise a Cyrillic layout typing "к" would
  // fire a bare "K" shortcut the user never asked for.
  if (!e.code || chord.base.length !== 1) return false;
  if (!chord.ctrl && !chord.meta && !chord.alt) return false;
  if (chord.base >= "A" && chord.base <= "Z") return e.code === `Key${chord.base}`;
  if (chord.base >= "0" && chord.base <= "9") return e.code === `Digit${chord.base}`;
  return false;
}

/**
 * `lenientShift` runs the second pass: Shift is treated as already baked into
 * the printed character. Only legal for a single-character base on an event
 * that actually held Shift, so it can never widen a named-key or chord match.
 */
export function chordMatchesEvent(chord: QuickKeyChord, e: QuickKeyEvent, lenientShift = false): boolean {
  if (!chord.base) return false;
  if (e.ctrlKey !== chord.ctrl || e.metaKey !== chord.meta || e.altKey !== chord.alt) return false;
  if (lenientShift) {
    if (chord.shift || !e.shiftKey || chord.base.length !== 1) return false;
  } else if (e.shiftKey !== chord.shift) {
    return false;
  }
  return baseMatches(chord, e);
}

// Dev-only tripwire. Normalization is the one part of this component that can
// break silently — a wrong fold still screenshots perfectly, it just never
// fires. These are the four cases that go wrong in practice. `warn`, not
// `error`, so a failure is loud in the console without tripping a screenshot
// gate that only watches for errors.
if (process.env.NODE_ENV !== "production") {
  const ev = (key: string, mods: Partial<QuickKeyEvent> = {}): QuickKeyEvent => ({
    key,
    ctrlKey: false,
    metaKey: false,
    shiftKey: false,
    altKey: false,
    ...mods,
  });
  const macModK = parseShortcut(["Mod", "K"], true)[0];
  const modZ = parseShortcut(["Mod", "Z"], false)[0];
  const modShiftZ = parseShortcut(["Mod", "Shift", "Z"], false)[0];
  const question = parseShortcut(["?"], false)[0];
  const checks: [string, boolean][] = [
    ["Mod folds to Meta on Apple", chordMatchesEvent(macModK, ev("k", { metaKey: true }))],
    ["Mod does not match bare Ctrl on Apple", !chordMatchesEvent(macModK, ev("k", { ctrlKey: true }))],
    ["? matches Shift+/ only on the lenient pass", !chordMatchesEvent(question, ev("?", { shiftKey: true })) && chordMatchesEvent(question, ev("?", { shiftKey: true }), true)],
    ["Mod+Shift+Z does not collapse into Mod+Z", chordMatchesEvent(modShiftZ, ev("Z", { ctrlKey: true, shiftKey: true })) && !chordMatchesEvent(modZ, ev("Z", { ctrlKey: true, shiftKey: true }))],
    ["non-Latin layout falls back to e.code", chordMatchesEvent(macModK, ev("к", { code: "KeyK", metaKey: true }))],
  ];
  for (const [name, ok] of checks) {
    if (!ok) console.warn(`[shortcuts-cheat-sheet] key normalization check failed: ${name}`);
  }
}

/* --------------------------------------------------------------- display */

function displayToken(token: string, isApple: boolean): string {
  switch (token.toLowerCase()) {
    case "mod":
      return isApple ? "⌘" : "Ctrl";
    case "meta":
    case "cmd":
    case "command":
      return isApple ? "⌘" : "Win";
    case "ctrl":
    case "control":
      return isApple ? "⌃" : "Ctrl";
    case "shift":
      return isApple ? "⇧" : "Shift";
    case "alt":
    case "opt":
    case "option":
      return isApple ? "⌥" : "Alt";
    case "space":
      return "Space";
    default:
      return token;
  }
}

const SPOKEN: Record<string, string> = {
  "⌘": "Command",
  "⇧": "Shift",
  "⌥": "Option",
  "⌃": "Control",
  "↑": "Up arrow",
  "↓": "Down arrow",
  "←": "Left arrow",
  "→": "Right arrow",
  "?": "Question mark",
  "/": "Slash",
  ",": "Comma",
  ".": "Period",
};

/** "Command plus K", so a screen reader never has to read ⌘ as an unknown glyph. */
function spokenKeys(chords: QuickKeyChord[], isApple: boolean): string {
  return chords
    .map((chord) =>
      chord.tokens
        .map((token) => {
          const shown = displayToken(token, isApple);
          return SPOKEN[shown] ?? shown;
        })
        .join(" plus ")
    )
    .join(", then ");
}

/* ------------------------------------------------------------- component */

export function QuickKey({
  sections,
  open,
  defaultOpen = false,
  onOpenChange,
  title = "Keyboard Shortcuts",
  columns = 2,
  liveEcho = true,
  echoDuration = 180,
  className = "",
}: QuickKeyProps) {
  const dialogRef = useRef<HTMLDialogElement>(null);
  const closingRef = useRef(0);
  const flashTimers = useRef<number[]>([]);
  const pendingRef = useRef<{ row: string; step: number } | null>(null);
  const pendingTimer = useRef(0);
  const titleId = useId();

  const [uncontrolled, setUncontrolled] = useState(defaultOpen);
  const isOpen = open ?? uncontrolled;
  const [flash, setFlash] = useState<string | null>(null);

  // Resolved after mount so the server and the first client render agree; SSR
  // ships the "Ctrl" spelling and Apple machines correct it in one commit.
  const [isApple, setIsApple] = useState(false);
  useEffect(() => {
    const nav = navigator as Navigator & { userAgentData?: { platform?: string } };
    const platform = nav.userAgentData?.platform || navigator.platform || navigator.userAgent || "";
    setIsApple(/mac|iphone|ipad|ipod/i.test(platform));
  }, []);

  const rows = useMemo(
    () =>
      sections.map((section, s) => ({
        ...section,
        items: section.items.map((item, i) => ({
          ...item,
          rowKey: `${s}-${i}`,
          chords: parseShortcut(item.keys, isApple),
        })),
      })),
    [sections, isApple]
  );

  const flatRows = useMemo(() => rows.flatMap((section) => section.items), [rows]);

  const clearFlashTimers = useCallback(() => {
    flashTimers.current.forEach(clearTimeout);
    flashTimers.current = [];
  }, []);

  const requestClose = useCallback(() => {
    onOpenChange?.(false);
    if (open === undefined) setUncontrolled(false);
  }, [onOpenChange, open]);

  /** Depress one step's caps for `echoDuration`. */
  const flashStep = useCallback(
    (rowKey: string, step: number) => {
      clearFlashTimers();
      setFlash(`${rowKey}:${step}`);
      flashTimers.current.push(window.setTimeout(() => setFlash(null), Math.max(40, echoDuration)));
    },
    [clearFlashTimers, echoDuration]
  );

  /** Click a row: play every step in order, so a sequence reads as a sequence. */
  const rehearse = useCallback(
    (rowKey: string, stepCount: number) => {
      clearFlashTimers();
      const beat = Math.max(40, echoDuration) + STEP_GAP_MS;
      setFlash(`${rowKey}:0`);
      for (let step = 1; step < stepCount; step += 1) {
        flashTimers.current.push(
          window.setTimeout(() => setFlash(`${rowKey}:${step}`), step * beat)
        );
      }
      flashTimers.current.push(window.setTimeout(() => setFlash(null), stepCount * beat));
    },
    [clearFlashTimers, echoDuration]
  );

  // Open/close the platform dialog from state.
  useEffect(() => {
    const dlg = dialogRef.current;
    if (!dlg) return;
    if (isOpen) {
      clearTimeout(closingRef.current);
      dlg.removeAttribute("data-closing");
      if (!dlg.open) dlg.showModal();
      return;
    }
    if (!dlg.open || dlg.hasAttribute("data-closing")) return;
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduced) {
      dlg.close();
      return;
    }
    // timer-driven, not transitionend-driven: a backgrounded tab must not be
    // able to strand an open dialog
    dlg.setAttribute("data-closing", "");
    closingRef.current = window.setTimeout(() => {
      dlg.removeAttribute("data-closing");
      dlg.close();
    }, 150);
  }, [isOpen]);

  // Escape fires `cancel`; `close` catches anything that closed the dialog
  // without going through the prop (form method=dialog, browser UI).
  useEffect(() => {
    const dlg = dialogRef.current;
    if (!dlg) return;
    const onCancel = (e: Event) => {
      e.preventDefault();
      requestClose();
    };
    const onClose = () => {
      if (isOpen) requestClose();
    };
    const onClick = (e: MouseEvent) => {
      if (e.target === dlg) requestClose();
    };
    dlg.addEventListener("cancel", onCancel);
    dlg.addEventListener("close", onClose);
    dlg.addEventListener("click", onClick);
    return () => {
      dlg.removeEventListener("cancel", onCancel);
      dlg.removeEventListener("close", onClose);
      dlg.removeEventListener("click", onClick);
    };
  }, [isOpen, requestClose]);

  // The keyboard-ownership listener. Capture phase on window, installed only
  // while open, so nothing behind the overlay ever sees a listed combo.
  useEffect(() => {
    if (!isOpen || !liveEcho) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (MODIFIER_KEYS.has(e.key)) return;
      // Escape and Tab stay the platform's: Escape closes via `cancel`, Tab
      // walks the dialog's native focus trap.
      if (e.key === "Escape" || e.key === "Tab") {
        pendingRef.current = null;
        return;
      }
      // Enter/Space on a focused control activates it. Swallowing those would
      // make the panel's own buttons unreachable by keyboard the moment a
      // sheet happens to list Enter as a shortcut.
      if ((e.key === "Enter" || e.key === " ") && (e.target as HTMLElement | null)?.closest?.("button")) {
        return;
      }

      const pending = pendingRef.current;
      if (pending) {
        const row = flatRows.find((r) => r.rowKey === pending.row);
        const chord = row?.chords[pending.step];
        if (row && chord && (chordMatchesEvent(chord, e) || chordMatchesEvent(chord, e, true))) {
          e.preventDefault();
          e.stopPropagation();
          flashStep(row.rowKey, pending.step);
          clearTimeout(pendingTimer.current);
          pendingRef.current =
            pending.step + 1 < row.chords.length ? { row: row.rowKey, step: pending.step + 1 } : null;
          if (pendingRef.current) {
            pendingTimer.current = window.setTimeout(() => {
              pendingRef.current = null;
            }, SEQUENCE_WINDOW_MS);
          }
          return;
        }
        pendingRef.current = null;
        clearTimeout(pendingTimer.current);
      }

      // exact pass first, lenient (Shift folded into the character) second
      const hit =
        flatRows.find((r) => r.chords[0] && chordMatchesEvent(r.chords[0], e)) ??
        flatRows.find((r) => r.chords[0] && chordMatchesEvent(r.chords[0], e, true));
      if (!hit) return;

      e.preventDefault();
      e.stopPropagation();
      flashStep(hit.rowKey, 0);
      if (hit.chords.length > 1) {
        pendingRef.current = { row: hit.rowKey, step: 1 };
        clearTimeout(pendingTimer.current);
        pendingTimer.current = window.setTimeout(() => {
          pendingRef.current = null;
        }, SEQUENCE_WINDOW_MS);
      }
    };
    window.addEventListener("keydown", onKeyDown, { capture: true });
    return () => window.removeEventListener("keydown", onKeyDown, { capture: true });
  }, [isOpen, liveEcho, flatRows, flashStep]);

  // Closing must not leave a half-played rehearsal to resume on reopen.
  useEffect(() => {
    if (isOpen) return;
    clearFlashTimers();
    clearTimeout(pendingTimer.current);
    pendingRef.current = null;
    setFlash(null);
  }, [isOpen, clearFlashTimers]);

  useEffect(
    () => () => {
      flashTimers.current.forEach(clearTimeout);
      flashTimers.current = [];
      clearTimeout(pendingTimer.current);
      clearTimeout(closingRef.current);
    },
    []
  );

  return (
    <dialog
      ref={dialogRef}
      aria-labelledby={titleId}
      className={`ns-qk m-auto w-[min(40rem,calc(100vw-2rem))] overflow-visible p-0 ${className}`}
    >
      {/* showModal() focuses the first focusable descendant unless something
          claims it. Left alone that pre-selects the first shortcut row and
          paints a focus ring on it at rest — take it here so focus lands in
          the panel, the title is announced, and Tab starts at the top. */}
      <div autoFocus tabIndex={-1} className="ns-qk-panel">
        <header className="flex items-baseline justify-between gap-4 px-6 pb-4 pt-5">
          <h2 id={titleId} className="text-base font-semibold tracking-tight text-foreground">
            {title}
          </h2>
          <p className="shrink-0 text-xs text-ns-muted">Press a shortcut to try it</p>
        </header>

        <div
          className={`grid gap-x-8 gap-y-6 px-6 pb-2 ${columns === 2 ? "sm:grid-cols-2" : "grid-cols-1"}`}
        >
          {rows.map((section, s) => (
            <section key={`${section.title}-${s}`} aria-labelledby={`${titleId}-s${s}`}>
              <h3
                id={`${titleId}-s${s}`}
                className="mb-2 px-2 text-[11px] font-medium uppercase tracking-[0.06em] text-ns-muted"
              >
                {section.title}
              </h3>
              <ul className="flex flex-col gap-0.5">
                {section.items.map((item) => (
                  <li key={item.rowKey}>
                    <button
                      type="button"
                      data-rehearse
                      onClick={() => rehearse(item.rowKey, item.chords.length)}
                      aria-label={`${item.label}: ${spokenKeys(item.chords, isApple)}`}
                      className="ns-qk-row"
                    >
                      <span aria-hidden className="min-w-0 truncate text-[13px] text-foreground">
                        {item.label}
                      </span>
                      <span aria-hidden className="flex shrink-0 items-center gap-1">
                        {item.chords.map((chord, step) => (
                          <span key={step} className="flex items-center gap-1">
                            {step > 0 && <span className="ns-qk-then">then</span>}
                            {chord.tokens.map((token, t) => (
                              <kbd
                                key={t}
                                className="ns-qk-cap"
                                data-pressed={flash === `${item.rowKey}:${step}` ? "" : undefined}
                              >
                                {displayToken(token, isApple)}
                              </kbd>
                            ))}
                          </span>
                        ))}
                      </span>
                    </button>
                  </li>
                ))}
              </ul>
            </section>
          ))}
        </div>

        <footer className="mt-2 flex items-center justify-between gap-4 border-t border-border px-6 py-3">
          <p className="flex items-center gap-2 text-xs text-ns-muted">
            <kbd className="ns-qk-cap" aria-hidden>
              Esc
            </kbd>
            to close
          </p>
          <button type="button" onClick={requestClose} className="ns-qk-close">
            Close
          </button>
        </footer>
      </div>

      {/* ::backdrop inherits custom properties from its originating element,
          so the scrim stays token-derived in both themes. */}
      <style>{`
        .ns-qk {
          border: 1px solid var(--border);
          border-radius: 16px;
          background: var(--surface);
          color: var(--foreground);
          box-shadow: 0 24px 60px -20px rgba(0, 0, 0, 0.45);
          animation: ns-qk-panel-in 220ms cubic-bezier(0.22, 1, 0.36, 1) both;
        }
        .ns-qk[data-closing] { animation: ns-qk-panel-out 150ms ease-in both; }
        .ns-qk::backdrop {
          background: color-mix(in oklab, var(--background) 72%, transparent);
          backdrop-filter: blur(2px);
          animation: ns-qk-scrim-in 120ms linear both;
        }
        .ns-qk[data-closing]::backdrop { animation: ns-qk-scrim-out 150ms linear both; }
        .ns-qk-panel { outline: none; }

        @keyframes ns-qk-panel-in {
          from { opacity: 0; transform: translateY(8px) scale(0.98); }
          to { opacity: 1; transform: none; }
        }
        @keyframes ns-qk-panel-out {
          from { opacity: 1; transform: none; }
          to { opacity: 0; transform: translateY(4px) scale(0.99); }
        }
        @keyframes ns-qk-scrim-in { from { opacity: 0 } to { opacity: 1 } }
        @keyframes ns-qk-scrim-out { from { opacity: 1 } to { opacity: 0 } }

        .ns-qk-row {
          display: flex;
          width: 100%;
          align-items: center;
          justify-content: space-between;
          gap: 16px;
          padding: 5px 8px;
          border: 1px solid transparent;
          border-radius: 6px;
          background: transparent;
          text-align: left;
          transition: background-color 140ms ease-out, border-color 140ms ease-out;
        }
        .ns-qk-row:hover {
          background: color-mix(in oklab, var(--foreground) 6%, transparent);
          border-color: var(--border);
        }
        .ns-qk-row:active {
          background: color-mix(in oklab, var(--ns-accent) 12%, transparent);
          border-color: color-mix(in oklab, var(--ns-accent) 45%, var(--border));
        }
        .ns-qk-row:focus-visible {
          outline: 2px solid var(--ns-accent);
          outline-offset: 2px;
        }

        .ns-qk-then {
          font-size: 11px;
          color: var(--ns-muted);
          padding: 0 2px;
        }

        .ns-qk-cap {
          display: inline-flex;
          align-items: center;
          justify-content: center;
          min-width: 26px;
          height: 26px;
          padding: 0 7px;
          border: 1px solid var(--border);
          border-radius: 6px;
          /* the panel is --surface, so caps sit on --background to read as a
             separate physical object in both themes */
          background: var(--background);
          box-shadow: 0 2px 0 var(--border);
          color: var(--foreground);
          font: 500 12px/1 var(--font-mono, ui-monospace, monospace);
          white-space: nowrap;
          /* release: slow settle back up */
          transition: transform 140ms cubic-bezier(0.22, 1, 0.36, 1),
            box-shadow 140ms cubic-bezier(0.22, 1, 0.36, 1),
            background-color 200ms ease-out, border-color 200ms ease-out, color 200ms ease-out;
        }
        .ns-qk-cap[data-pressed] {
          transform: translateY(2px);
          box-shadow: 0 0 0 var(--border);
          border-color: var(--ns-accent);
          background: color-mix(in oklab, var(--ns-accent) 14%, var(--surface));
          color: var(--ns-accent);
          /* press-in: immediate */
          transition: transform 60ms linear, box-shadow 60ms linear,
            background-color 60ms linear, border-color 60ms linear, color 60ms linear;
        }

        .ns-qk-close {
          border: 1px solid var(--border);
          border-radius: 6px;
          background: var(--background);
          color: var(--foreground);
          font-size: 12px;
          padding: 4px 12px;
          transition: background-color 140ms ease-out, border-color 140ms ease-out;
        }
        .ns-qk-close:hover {
          border-color: var(--ns-accent);
          background: color-mix(in oklab, var(--ns-accent) 10%, var(--background));
        }
        .ns-qk-close:focus-visible { outline: 2px solid var(--ns-accent); outline-offset: 2px; }

        @media (prefers-reduced-motion: reduce) {
          /* opacity only, one frame; the flash drops travel and becomes a pure
             colour change — still a real pixel change, so headless
             hover/keydown verification keeps working */
          .ns-qk, .ns-qk[data-closing] {
            animation-duration: 1ms;
            animation-timing-function: linear;
          }
          @keyframes ns-qk-panel-in { from { opacity: 0 } to { opacity: 1 } }
          @keyframes ns-qk-panel-out { from { opacity: 1 } to { opacity: 0 } }
          .ns-qk-cap, .ns-qk-cap[data-pressed] {
            transform: none;
            box-shadow: 0 2px 0 var(--border);
            transition: background-color 200ms ease-out, border-color 200ms ease-out,
              color 200ms ease-out;
          }
        }
      `}</style>
    </dialog>
  );
}

"use client";

// ShutterTelegraphBoard — an ambient multi-stage status board modelled on the
// Admiralty six-shutter telegraph (Murray's telegraph, England 1795-1816): a
// 2x3 board of louvred shutters, each independently flipped edge-on (nearly
// invisible, background shows through) or face-on (a solid opaque square),
// read hilltop to hilltop through a telescope. Each of the 63 open/closed
// combinations encoded a number or codebook phrase.
//
// Pure DOM/CSS, no canvas. Each shutter is a small stack of two divs: a
// fixed 1px --foreground-at-25%-opacity frame (the shutter's edge, visible
// once the panel in front of it rotates out of the way) and an opaque
// --foreground panel driven purely by `transform: perspective(...)
// rotateY(deg)` between 0deg (face-on/closed) and 90deg (edge-on/open) — the
// perspective projection itself is what visually collapses the panel to a
// near-invisible sliver, no opacity fade involved. Every 2s a new symbol
// (one of 8 fixed 6-bit patterns) is applied; the six shutters that need to
// flip each get a 60ms-staggered transitionDelay in reading order
// (left-to-right, top-to-bottom) so a symbol change reads as a wave
// crossing the board rather than a simultaneous snap, each individual flip
// taking 320ms ease-in-out. Colours are plain `var(--foreground)` in inline
// styles — pure DOM with no per-pixel colour math, so (as with the shipped
// flag-hoist-run) there is nothing for getComputedStyle/MutationObserver to
// do that the CSS cascade doesn't already do for free on a theme switch.

import { useEffect, useRef, useState } from "react";

const COLS = 2;
const ROWS = 3;
const CELL_COUNT = COLS * ROWS;

const FLIP_MS = 320;
const STAGGER_MS = 60;
const DWELL_MS = 1700;
const SYMBOL_INTERVAL_MS = DWELL_MS + (CELL_COUNT - 1) * STAGGER_MS; // ~2000ms
const PERSPECTIVE_PX = 600;

// 8 fixed 6-bit symbols, reading order (row-major, top-to-bottom,
// left-to-right within a row): true = open (edge-on), false = closed
// (face-on). Index 4 is an exact checkerboard — 3 open / 3 closed, the
// maximum structural contrast in the set — reserved as the reduced-motion
// freeze frame. The set deliberately also contains the degenerate
// all-closed (0) and all-open (5) symbols elsewhere in the loop, which is
// exactly why those two are never chosen as the static frame.
const SYMBOLS: readonly boolean[][] = [
  [false, false, false, false, false, false],
  [true, true, false, false, true, false],
  [false, true, true, false, true, true],
  [true, false, true, true, false, false],
  [true, false, false, true, true, false], // checkerboard — reduced-motion frame
  [true, true, true, true, true, true],
  [false, true, false, true, false, true],
  [true, false, true, false, true, false],
];

const STATIC_SYMBOL_INDEX = 4;
const START_SYMBOL_INDEX = 2; // a mixed, non-degenerate t0

export interface ShutterTelegraphBoardProps {
  /** accessible label for the ambient board */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function ShutterTelegraphBoard({
  label = "Signal board",
  className = "",
}: ShutterTelegraphBoardProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const gridRef = useRef<HTMLDivElement>(null);
  const [cellSize, setCellSize] = useState(0);
  const [reduced, setReduced] = useState(false);
  // matches SSR's default (reduced motion is unknown server-side); flipped
  // to STATIC_SYMBOL_INDEX synchronously in the reduced-motion effect below
  // before any timer would otherwise fire, so no flash of the wrong symbol.
  const [symbolIndex, setSymbolIndex] = useState(START_SYMBOL_INDEX);

  // -- reduced motion: pin to the checkerboard symbol, never advance. ----
  useEffect(() => {
    const isReduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    setReduced(isReduced);
    if (isReduced) setSymbolIndex(STATIC_SYMBOL_INDEX);
  }, []);

  // -- geometry: square shutters sized from the container's smaller
  // dimension, so the board reads at card scale on any card. -------------
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const ro = new ResizeObserver((entries) => {
      const rect = entries[0]?.contentRect;
      if (!rect) return;
      const minDim = Math.min(rect.width, rect.height);
      setCellSize(minDim / 4);
    });
    ro.observe(root);
    return () => ro.disconnect();
  }, []);

  // -- the loop: a new symbol every SYMBOL_INTERVAL_MS, unbounded, 8-symbol
  // repeat (~16s per full cycle). Paused while off-screen, skipped
  // entirely under reduced motion. ----------------------------------------
  useEffect(() => {
    if (reduced) return;
    const root = rootRef.current;
    if (!root) return;
    let id = 0;
    const start = () => {
      if (id) return;
      id = window.setInterval(() => {
        setSymbolIndex((i) => (i + 1) % SYMBOLS.length);
      }, SYMBOL_INTERVAL_MS);
    };
    const stop = () => {
      if (!id) return;
      window.clearInterval(id);
      id = 0;
    };
    const io = new IntersectionObserver((entries) => {
      if (entries[0]?.isIntersecting) start();
      else stop();
    });
    io.observe(root);
    return () => {
      stop();
      io.disconnect();
    };
  }, [reduced]);

  const gap = cellSize * 0.14;
  const pattern = SYMBOLS[symbolIndex] ?? SYMBOLS[0]!;

  return (
    <div
      ref={rootRef}
      role="img"
      aria-label={label}
      className={`relative flex w-full items-center justify-center overflow-hidden ${className}`}
    >
      <div
        ref={gridRef}
        aria-hidden="true"
        style={{
          display: "grid",
          gridTemplateColumns: `repeat(${COLS}, ${cellSize}px)`,
          gridTemplateRows: `repeat(${ROWS}, ${cellSize}px)`,
          gap: `${gap}px`,
          visibility: cellSize > 0 ? "visible" : "hidden",
        }}
      >
        {pattern.map((open, i) => (
          <div key={i} style={{ position: "relative", width: cellSize, height: cellSize }}>
            <div
              style={{
                position: "absolute",
                inset: 0,
                border: "1px solid var(--foreground)",
                opacity: 0.25,
              }}
            />
            <div
              className="ns-shutter-panel"
              style={{
                position: "absolute",
                inset: 0,
                backgroundColor: "var(--foreground)",
                transformOrigin: "50% 50%",
                transform: `perspective(${PERSPECTIVE_PX}px) rotateY(${open ? 90 : 0}deg)`,
                transitionProperty: reduced ? "none" : "transform",
                transitionDuration: `${FLIP_MS}ms`,
                transitionTimingFunction: "ease-in-out",
                transitionDelay: `${i * STAGGER_MS}ms`,
              }}
            />
          </div>
        ))}
      </div>
      <style>{`
@media (prefers-reduced-motion: reduce){
  .ns-shutter-panel{transition:none!important;}
}
`}</style>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useId, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// DeedStroke — signature capture as consent, not a checkbox tick (see
// checkbox-ink-stroke for that). A canvas ink layer renders pointer strokes with
// pen-pressure feel (velocity maps inversely to line width, a pooled dab at
// every stroke start), backed by a baseline guide div. On release, a
// "witness" replay retraces the captured points once at a constant pace so
// the signer sees their mark rendered cleanly, then Confirm unlocks —
// confirming embosses the strip (inset shadow + caption swap to
// "Authorized"). Clear resets. A keyboard/no-pointer path lets the signer
// type their name instead, styled as an italic mark, which skips the replay
// (there is nothing to smooth) and unlocks Confirm as soon as it is non-empty.
//
// All ink drawing is direct 2D-canvas calls driven by refs — no React state
// on the draw or replay hot path. Hover reveals a two-tone nib-dot CSS
// cursor (visible on any theme, no JS pointer tracking needed) and brightens
// the baseline guide via a plain CSS :hover rule.
// ---------------------------------------------------------------------------

export interface DeedStrokeValue {
  mode: "draw" | "type";
  dataUrl?: string;
  name?: string;
}

export interface DeedStrokeProps {
  /** Caption shown before signing. Default "Sign to authorize". */
  prompt?: string;
  /** Called once, when the signer confirms. */
  onConfirm?: (value: DeedStrokeValue) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

type Point = { x: number; y: number; t: number };
type Stroke = Point[];

const MIN_WIDTH = 1.1;
const MAX_WIDTH = 4.4;
const VELOCITY_SCALE = 0.09; // px/ms -> width falloff
const POOL_RADIUS = MAX_WIDTH * 0.95;
const REPLAY_MS = 650;
const REPLAY_WIDTH = 1.8;
const MIN_POINTS_TO_SIGN = 2;

// Two-tone dot (dark center, light ring) reads on any theme without CSS
// variables — cursor images can't resolve custom properties.
const NIB_CURSOR = `url("data:image/svg+xml,${encodeURIComponent(
  '<svg xmlns="http://www.w3.org/2000/svg" width="10" height="10"><circle cx="5" cy="5" r="4" fill="%23f5f5f5" stroke="%23171717" stroke-width="1"/><circle cx="5" cy="5" r="1.5" fill="%23171717"/></svg>'
)}") 5 5, crosshair`;

function resolveInk(canvas: HTMLCanvasElement): string {
  return getComputedStyle(canvas).color || "#ededed";
}

function distance(a: Point, b: Point) {
  return Math.hypot(b.x - a.x, b.y - a.y);
}

function strokeSegment(
  ctx: CanvasRenderingContext2D,
  a: Point,
  b: Point,
  width: number,
  color: string
) {
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.beginPath();
  ctx.moveTo(a.x, a.y);
  ctx.lineTo(b.x, b.y);
  ctx.stroke();
}

function drawPool(ctx: CanvasRenderingContext2D, p: Point, color: string) {
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.arc(p.x, p.y, POOL_RADIUS, 0, Math.PI * 2);
  ctx.fill();
}

export function DeedStroke({ prompt = "Sign to authorize", onConfirm, className = "" }: DeedStrokeProps) {
  const autoId = useId().replace(/:/g, "");
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const strokesRef = useRef<Stroke[]>([]);
  const drawingRef = useRef(false);
  const lastPointRef = useRef<Point | null>(null);
  const inkColorRef = useRef("#ededed");
  const reducedRef = useRef(false);
  const replayFrameRef = useRef<number | undefined>(undefined);

  const [mode, setMode] = useState<"draw" | "type">("draw");
  const [typedName, setTypedName] = useState("");
  const [hasStroke, setHasStroke] = useState(false);
  const [replaying, setReplaying] = useState(false);
  const [canConfirm, setCanConfirm] = useState(false);
  const [confirmed, setConfirmed] = useState(false);
  const [announce, setAnnounce] = useState("");

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    reducedRef.current = mq.matches;
    const onChange = () => {
      reducedRef.current = mq.matches;
    };
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  useEffect(() => () => {
    if (replayFrameRef.current) cancelAnimationFrame(replayFrameRef.current);
  }, []);

  const clearCanvas = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    ctx?.clearRect(0, 0, canvas.width, canvas.height);
  }, []);

  const reset = useCallback(() => {
    if (replayFrameRef.current) cancelAnimationFrame(replayFrameRef.current);
    strokesRef.current = [];
    lastPointRef.current = null;
    drawingRef.current = false;
    clearCanvas();
    setHasStroke(false);
    setReplaying(false);
    setCanConfirm(false);
    setConfirmed(false);
    setTypedName("");
    setAnnounce("Signature cleared.");
  }, [clearCanvas]);

  // Retrace every captured point once at a constant pace, redrawing the
  // whole path-so-far each frame (a signature is a few hundred points at
  // most — cheap to redraw wholesale, and it sidesteps incremental-segment
  // bookkeeping across the pen-up gaps between strokes).
  const runWitnessReplay = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const strokes = strokesRef.current;
    const color = inkColorRef.current;

    type Seg = { a: Point; b: Point; len: number };
    const segments: Seg[] = [];
    let total = 0;
    for (const stroke of strokes) {
      for (let i = 1; i < stroke.length; i++) {
        const len = distance(stroke[i - 1]!, stroke[i]!);
        segments.push({ a: stroke[i - 1]!, b: stroke[i]!, len });
        total += len;
      }
    }
    if (total === 0) {
      setCanConfirm(true);
      setReplaying(false);
      return;
    }

    setReplaying(true);
    const start = performance.now();

    const frame = (now: number) => {
      const fraction = Math.min(1, (now - start) / REPLAY_MS);
      clearCanvas();
      let budget = total * fraction;
      for (const seg of segments) {
        if (budget <= 0) break;
        if (seg.len <= budget) {
          strokeSegment(ctx, seg.a, seg.b, REPLAY_WIDTH, color);
          budget -= seg.len;
        } else {
          const t = seg.len === 0 ? 0 : budget / seg.len;
          const bx = seg.a.x + (seg.b.x - seg.a.x) * t;
          const by = seg.a.y + (seg.b.y - seg.a.y) * t;
          strokeSegment(ctx, seg.a, { x: bx, y: by, t: seg.a.t }, REPLAY_WIDTH, color);
          budget = 0;
        }
      }
      if (fraction < 1) {
        replayFrameRef.current = requestAnimationFrame(frame);
      } else {
        setReplaying(false);
        setCanConfirm(true);
        setAnnounce("Signature captured. Ready to confirm.");
      }
    };
    replayFrameRef.current = requestAnimationFrame(frame);
  }, [clearCanvas]);

  const onPointerDown = useCallback((e: React.PointerEvent<HTMLCanvasElement>) => {
    if (confirmed || replaying) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    canvas.setPointerCapture(e.pointerId);
    inkColorRef.current = resolveInk(canvas);
    const rect = canvas.getBoundingClientRect();
    const p: Point = { x: e.clientX - rect.left, y: e.clientY - rect.top, t: performance.now() };
    drawingRef.current = true;
    strokesRef.current.push([p]);
    lastPointRef.current = p;
    const ctx = canvas.getContext("2d");
    if (ctx) drawPool(ctx, p, inkColorRef.current);
  }, [confirmed, replaying]);

  const onPointerMove = useCallback((e: React.PointerEvent<HTMLCanvasElement>) => {
    if (!drawingRef.current) return;
    const canvas = canvasRef.current;
    const last = lastPointRef.current;
    if (!canvas || !last) return;
    const rect = canvas.getBoundingClientRect();
    const p: Point = { x: e.clientX - rect.left, y: e.clientY - rect.top, t: performance.now() };
    const dt = Math.max(1, p.t - last.t);
    const dist = distance(last, p);
    const velocity = dist / dt;
    const width = Math.min(MAX_WIDTH, Math.max(MIN_WIDTH, MAX_WIDTH - velocity / VELOCITY_SCALE));
    const ctx = canvas.getContext("2d");
    if (ctx) strokeSegment(ctx, last, p, width, inkColorRef.current);
    strokesRef.current[strokesRef.current.length - 1]?.push(p);
    lastPointRef.current = p;
  }, []);

  const finishStroke = useCallback(() => {
    if (!drawingRef.current) return;
    drawingRef.current = false;
    lastPointRef.current = null;
    const totalPoints = strokesRef.current.reduce((n, s) => n + s.length, 0);
    const signed = totalPoints >= MIN_POINTS_TO_SIGN;
    setHasStroke(signed);
    if (!signed) return;
    if (reducedRef.current) {
      setCanConfirm(true);
      setAnnounce("Signature captured. Ready to confirm.");
    } else {
      runWitnessReplay();
    }
  }, [runWitnessReplay]);

  const handleConfirm = useCallback(() => {
    if (!canConfirm || confirmed) return;
    setConfirmed(true);
    setAnnounce("Authorized.");
    if (mode === "draw") {
      onConfirm?.({ mode, dataUrl: canvasRef.current?.toDataURL() });
    } else {
      onConfirm?.({ mode, name: typedName.trim() });
    }
  }, [canConfirm, confirmed, mode, onConfirm, typedName]);

  const toggleMode = useCallback(() => {
    if (confirmed) return;
    setMode((m) => (m === "draw" ? "type" : "draw"));
    reset();
  }, [confirmed, reset]);

  const nameId = `signature-consent-name-${autoId}`;
  const captionText = confirmed ? "Authorized" : prompt;
  const drawReady = mode === "draw" && canConfirm && !confirmed;
  const typeReady = mode === "type" && typedName.trim().length > 0 && !confirmed;
  const confirmEnabled = drawReady || typeReady;

  return (
    <div className={`w-full max-w-md rounded-[12px] border border-border bg-background ${className}`}>
      <style>{CSS}</style>
      <span role="status" aria-live="polite" aria-atomic="true" className="sr-only">
        {announce}
      </span>

      <div className="flex items-center justify-between gap-3 border-b border-border px-4 py-3">
        <p className="font-mono text-xs uppercase tracking-[0.2em] text-ns-muted">{captionText}</p>
        <button
          type="button"
          onClick={toggleMode}
          disabled={confirmed}
          className="ns-ds-link font-mono text-[11px] text-ns-muted underline-offset-4 hover:text-foreground hover:underline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent disabled:cursor-not-allowed disabled:opacity-40 disabled:pointer-events-none"
        >
          {mode === "draw" ? "Type your name instead" : "Draw signature instead"}
        </button>
      </div>

      <div className="px-5 py-6">
        {mode === "draw" ? (
          <div
            className={`ns-ds-area relative h-32 w-full overflow-hidden rounded-[6px] border border-border transition-shadow duration-200 ${
              confirmed ? "ns-ds-embossed" : ""
            }`}
          >
            <div aria-hidden="true" className="ns-ds-baseline absolute inset-x-4 bottom-9 h-px bg-ns-muted" />
            <canvas
              ref={canvasRef}
              width={352}
              height={128}
              role="img"
              aria-label={confirmed ? "Authorized signature" : "Signature pad — draw with your pointer"}
              className="ns-ds-canvas relative h-32 w-full touch-none text-foreground"
              onPointerDown={onPointerDown}
              onPointerMove={onPointerMove}
              onPointerUp={finishStroke}
              onPointerLeave={finishStroke}
              onPointerCancel={finishStroke}
              style={{ cursor: confirmed || replaying ? "default" : NIB_CURSOR }}
            />
            {!hasStroke && !replaying && (
              <p
                aria-hidden="true"
                className="pointer-events-none absolute inset-x-0 bottom-2 text-center font-mono text-[10px] uppercase tracking-widest text-ns-muted"
              >
                Draw here
              </p>
            )}
          </div>
        ) : (
          <div>
            <label htmlFor={nameId} className="sr-only">
              Type your name
            </label>
            <input
              id={nameId}
              type="text"
              value={typedName}
              disabled={confirmed}
              onChange={(e) => setTypedName(e.target.value)}
              placeholder="Type your name"
              autoComplete="name"
              className={`ns-ds-name-input w-full rounded-[6px] border border-border bg-transparent px-3 py-4 text-2xl text-foreground placeholder:text-ns-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent ${
                confirmed ? "ns-ds-embossed" : ""
              }`}
            />
          </div>
        )}
      </div>

      <div className="flex items-center justify-between gap-3 border-t border-border px-4 py-3">
        <button
          type="button"
          onClick={reset}
          disabled={!hasStroke && typedName.length === 0 && !confirmed}
          className="font-mono text-xs text-ns-muted underline-offset-4 hover:text-foreground hover:underline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent disabled:cursor-not-allowed disabled:opacity-40 disabled:pointer-events-none"
        >
          Clear
        </button>
        <button
          type="button"
          onClick={handleConfirm}
          disabled={!confirmEnabled}
          className="rounded-[6px] border border-border bg-foreground px-4 py-1.5 font-mono text-xs text-background hover:opacity-90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent disabled:cursor-not-allowed disabled:border-border disabled:bg-transparent disabled:text-ns-muted disabled:opacity-60 disabled:pointer-events-none"
        >
          {confirmed ? "Authorized" : "Confirm"}
        </button>
      </div>
    </div>
  );
}

const CSS = `
.ns-ds-area:hover .ns-ds-baseline{ background: var(--foreground); }
.ns-ds-embossed{
  box-shadow: inset 0 1px 3px rgba(0,0,0,0.45), inset 0 -1px 0 rgba(255,255,255,0.04);
  transition: box-shadow 200ms ease-out;
}
@media (prefers-reduced-motion: reduce){
  .ns-ds-embossed{ transition: none; }
}
`;

export default DeedStroke;

"use client";

import { useEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// SinkholeRavel — a destructive-action confirm modeled on cover-collapse
// sinkhole formation in karst terrain: groundwater dissolves a void in the
// bedrock, and the granular cover above it doesn't just sit there — grains at
// the void's ceiling continuously RAVEL (individually lose support and fall
// into the cavity, a real geotechnical term), so the void migrates upward
// through the overburden one grain-layer at a time as a narrow "stoping"
// chimney. This can run a long time with no surface expression. Once the
// chimney gets close enough to the surface, the remaining crust can no
// longer arch-bridge its own weight and drops in one sudden collapse,
// leaving a crater whose loose rim material immediately starts sliding back
// in to partially backfill it — never fully, so the scar is visible going
// into the next cycle, which renucleates at a new lateral position.
//
// A canvas cross-section renders a lattice of grains packed into rows
// (count derived from the container's smaller dimension). A single scalar
// void height (0 = void only at the bedrock line, 1 = void has reached the
// surface crust) tracks how far the chimney has migrated. Grains fall out of
// the lattice individually, each on its own randomized per-250ms trigger
// once it enters the ravel band (void height +/- one grain-row) — never in a
// body-wide sweep — so the ravel front reads as organic, independently-timed
// grain loss rather than a wipe. Crossing 0.94 fires the one big legible
// event per cycle: the remaining crust drops as a fast 220ms collapse, then
// loose rim grains slide back in along a 34deg angle-of-repose slope for
// 3.5s, refilling to ~55% before the chimney renucleates at a new x.
//
// The confirm control is click-arm-then-confirm: arming visibly accelerates
// the ambient ravel rate (teasing an early collapse, fully reversible — a
// second click within the window, Escape, or blur before that resolves
// nothing), a second click inside the window forces the collapse
// immediately regardless of where the ambient cycle sits and fires
// onConfirm once, exactly as the crater finishes dropping.
//
// Every colour is read from the theme via getComputedStyle on
// document.documentElement, re-read on a MutationObserver watching its
// class, and nothing paints before that first read. --ns-accent never
// touches the grains/void/collapse — it is the confirm button's own chrome.
// ---------------------------------------------------------------------------

type Phase = "ravel" | "collapsing" | "backfilling" | "waiting";

interface Grain {
  x: number;
  y: number;
  r: number;
  rowFrac: number; // 0 = bedrock (bottom), 1 = surface (top)
  state: "alive" | "falling" | "gone";
  fallStart: number;
  fallDur: number;
  fallDist: number;
}

const RAVEL_RATE = 0.09; // void-height fraction / s, ambient
const RAVEL_JITTER = 0.15; // +/-15% amplitude
const RAVEL_JITTER_MS = 400;
const RAVEL_TICK_MS = 250;
const RAVEL_CHANCE = 1 / 6; // per eligible grain, per tick
const FALL_DUR_MS = 180;
const COLLAPSE_THRESHOLD = 0.94;
const COLLAPSE_CRUST_FRAC = 0.06; // top 6% of overburden height
const COLLAPSE_DUR_MS = 220;
const BACKFILL_DUR_MS = 3500;
const BACKFILL_GRAIN_MS = 140;
const BACKFILL_FILL_FRAC = 0.55;
const BACKFILL_SLOPE_DEG = 34;
const RENUCLEATE_DELAY_MS = 900;
const ARM_WINDOW_MS = 3200;
const ARM_RATE_MULT = 3.5;
const ARM_EASE_PER_S = 3.4; // how fast the accel/de-accel ramps

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function buildGrains(
  w: number,
  h: number,
  minDim: number,
  rand: () => number
): { grains: Grain[]; rows: number; avgR: number } {
  const maxGrains = Math.min(2400, Math.max(1800, Math.round((minDim * minDim) / 340)));
  const cell = Math.sqrt((w * h) / maxGrains);
  const cols = Math.max(4, Math.round(w / cell));
  const rows = Math.max(4, Math.round(h / cell));
  const cw = w / cols;
  const ch = h / rows;
  const grains: Grain[] = [];
  let rSum = 0;
  for (let row = 0; row < rows; row++) {
    const rowFrac = rows > 1 ? (rows - 1 - row) / (rows - 1) : 1;
    for (let col = 0; col < cols; col++) {
      const x = (col + 0.5) * cw + (rand() - 0.5) * 0.7 * cw;
      const y = (row + 0.5) * ch + (rand() - 0.5) * 0.7 * ch;
      const r = Math.min(cw, ch) * 0.32 * (0.85 + 0.3 * rand());
      rSum += r;
      grains.push({ x, y, r, rowFrac, state: "alive", fallStart: 0, fallDur: 0, fallDist: 0 });
    }
  }
  return { grains, rows, avgR: rSum / Math.max(1, grains.length) };
}

export interface SinkholeRavelProps {
  /** idle button label */
  children?: string;
  /** label shown once armed, awaiting the confirming click */
  armedLabel?: string;
  /** ms the armed window stays open before it auto de-arms */
  armWindowMs?: number;
  /** fired once, exactly as the forced crater finishes dropping */
  onConfirm?: () => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function SinkholeRavel({
  children = "Trigger collapse",
  armedLabel = "Confirm collapse",
  armWindowMs = ARM_WINDOW_MS,
  onConfirm,
  className = "",
}: SinkholeRavelProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [armed, setArmed] = useState(false);
  const [announcement, setAnnouncement] = useState("");
  const onConfirmRef = useRef(onConfirm);
  onConfirmRef.current = onConfirm;
  const armWindowRef = useRef(armWindowMs);
  armWindowRef.current = armWindowMs;

  const s = useRef({
    grains: [] as Grain[],
    rows: 1,
    avgR: 2,
    w: 0,
    h: 0,
    dpr: 1,
    chimneyBase: 0,
    chimneyX: 0,
    voidFrac: 0,
    phase: "ravel" as Phase,
    jitterMult: 1,
    lastJitterAt: 0,
    raveAcc: 0,
    collapseStart: 0,
    backfillStart: 0,
    backfillAcc: 0,
    backfillSpawned: 0,
    backfillTarget: 0,
    waitStart: 0,
    armed: false,
    armEase: 0,
    armTimer: 0,
    seedCounter: 1,
    rand: mulberry32(0x5117e0),
    reduced: false,
    visible: true,
    raf: 0,
    last: 0,
    mountedAt: 0,
    tokens: { foreground: "", muted: "", background: "" },
  });

  useEffect(() => {
    const st = s.current;
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    st.mountedAt = performance.now();
    st.rand = mulberry32(0xa11ce5ee);

    const syncTokens = () => {
      const cs = getComputedStyle(document.documentElement);
      st.tokens.foreground = cs.getPropertyValue("--foreground").trim();
      st.tokens.muted = cs.getPropertyValue("--ns-muted").trim();
      st.tokens.background = cs.getPropertyValue("--background").trim();
      draw(performance.now());
    };

    const radiusAt = (rowFrac: number) => st.chimneyBase * (0.6 + 0.4 * rowFrac);
    const inChimney = (g: Grain) => Math.abs(g.x - st.chimneyX) < radiusAt(g.rowFrac);

    const triggerFall = (g: Grain, now: number, dur: number, extraDelay: number) => {
      g.state = "falling";
      g.fallStart = now + extraDelay;
      g.fallDur = dur;
      g.fallDist = g.r * (2.4 + st.rand() * 2.2);
    };

    // -- one 250ms tick: any alive grain in the chimney whose row sits within
    // one grain-row of the current void front rolls an independent 1-in-6
    // chance to ravel early; anything the front has already passed by more
    // than a few rows is force-removed as a safety net so nothing is left
    // floating mid-void. --------------------------------------------------
    const raveTick = (now: number) => {
      const bandHalf = 1 / st.rows;
      for (const g of st.grains) {
        if (g.state !== "alive" || !inChimney(g)) continue;
        const ahead = g.rowFrac - st.voidFrac; // + = not yet engulfed
        if (ahead < -3 * bandHalf) {
          triggerFall(g, now, FALL_DUR_MS, 0);
        } else if (ahead <= bandHalf) {
          if (st.rand() < RAVEL_CHANCE) triggerFall(g, now, FALL_DUR_MS, 0);
        }
      }
    };

    const beginCollapse = (now: number, forced: boolean) => {
      st.phase = "collapsing";
      st.collapseStart = now;
      st.voidFrac = 1;
      const crustFloor = forced ? 0 : 1 - COLLAPSE_CRUST_FRAC;
      for (const g of st.grains) {
        if (g.state === "alive" && inChimney(g) && g.rowFrac >= crustFloor) {
          triggerFall(g, now, COLLAPSE_DUR_MS, st.rand() * 40);
        }
      }
      if (forced) {
        setAnnouncement("Collapsing.");
      }
      (st as unknown as { pendingConfirm: boolean }).pendingConfirm = forced;
    };

    const beginBackfill = (now: number) => {
      st.phase = "backfilling";
      st.backfillStart = now;
      st.backfillAcc = 0;
      st.backfillSpawned = 0;
      st.backfillTarget = Math.round(BACKFILL_DUR_MS / BACKFILL_GRAIN_MS);
      if ((st as unknown as { pendingConfirm: boolean }).pendingConfirm) {
        (st as unknown as { pendingConfirm: boolean }).pendingConfirm = false;
        onConfirmRef.current?.();
      }
    };

    const spawnBackfillGrain = (now: number) => {
      const rimRadius = st.chimneyBase * (0.6 + 0.4 * 1) * 1.25;
      const rowFrac = st.rand() * BACKFILL_FILL_FRAC;
      const spanFrac = 0.55 + 0.4 * st.rand();
      const x = st.chimneyX + (st.rand() - 0.5) * 2 * rimRadius * spanFrac;
      const y = st.h - rowFrac * st.h;
      const r = st.avgR * (0.85 + 0.3 * st.rand());
      st.grains.push({
        x,
        y,
        r,
        rowFrac,
        state: "falling",
        fallStart: now,
        fallDur: 260 + st.rand() * 120,
        fallDist: -st.avgR * 1.6, // slides IN (fades up from below-alpha) rather than out
      });
      // the "fall" here is used in reverse as an arrival tween — patched below
    };

    const renucleate = (now: number) => {
      const w = st.w;
      const prevX = st.chimneyX;
      let nx = prevX;
      let guard = 0;
      while (Math.abs(nx - prevX) < w * 0.22 && guard < 12) {
        nx = w * (0.18 + st.rand() * 0.64);
        guard++;
      }
      st.chimneyX = nx;
      st.voidFrac = 0;
      st.phase = "ravel";
      st.raveAcc = 0;
    };

    // -- draw ---------------------------------------------------------------
    const draw = (now: number) => {
      const { w, h, dpr } = st;
      if (!w || !h) return;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      const bandHalf = 1 / st.rows;

      for (const g of st.grains) {
        if (g.state === "gone") continue;
        let alpha = 0.55;
        let gy = g.y;
        if (g.state === "falling") {
          const t = Math.max(0, Math.min(1, (now - g.fallStart) / g.fallDur));
          if (now < g.fallStart) continue;
          if (g.fallDist < 0) {
            // backfill arrival: fades/slides in rather than out
            alpha = 0.55 * t;
            gy = g.y - g.fallDist * (1 - t);
          } else {
            const ease = t * t;
            alpha = 0.55 * (1 - t);
            gy = g.y + g.fallDist * ease;
          }
          if (t >= 1) {
            if (g.fallDist < 0) {
              g.state = "alive";
              gy = g.y;
              alpha = 0.55;
            } else {
              g.state = "gone";
              continue;
            }
          }
        } else {
          const ahead = g.rowFrac - st.voidFrac;
          if (st.phase === "ravel" && ahead >= -bandHalf && ahead <= bandHalf && Math.abs(g.x - st.chimneyX) < radiusAt(g.rowFrac) + g.r * 3) {
            const glowT = 0.5 + 0.5 * Math.sin((now - st.mountedAt) / 180 + g.x * 0.05);
            ctx.globalAlpha = 0.14 + 0.14 * glowT;
            ctx.fillStyle = st.tokens.muted;
            ctx.beginPath();
            ctx.arc(g.x, gy, g.r * 2.1, 0, Math.PI * 2);
            ctx.fill();
          }
        }
        ctx.globalAlpha = alpha;
        ctx.fillStyle = st.tokens.foreground;
        ctx.beginPath();
        ctx.arc(g.x, gy, g.r, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.globalAlpha = 1;
    };

    // -- main loop ------------------------------------------------------
    const tick = (now: number) => {
      if (!st.visible) {
        st.raf = 0;
        return;
      }
      const dt = Math.min(0.064, st.last ? (now - st.last) / 1000 : 0);
      st.last = now;

      if (now - st.lastJitterAt >= RAVEL_JITTER_MS) {
        st.lastJitterAt = now;
        st.jitterMult = 1 + (st.rand() * 2 - 1) * RAVEL_JITTER;
      }

      const armTarget = st.armed ? 1 : 0;
      st.armEase += (armTarget - st.armEase) * Math.min(1, ARM_EASE_PER_S * dt);

      if (st.phase === "ravel") {
        const rate = RAVEL_RATE * st.jitterMult * (1 + st.armEase * (ARM_RATE_MULT - 1));
        st.voidFrac = Math.min(1, st.voidFrac + rate * dt);
        st.raveAcc += dt * 1000;
        while (st.raveAcc >= RAVEL_TICK_MS) {
          st.raveAcc -= RAVEL_TICK_MS;
          raveTick(now);
        }
        if (st.voidFrac >= COLLAPSE_THRESHOLD) beginCollapse(now, false);
      } else if (st.phase === "collapsing") {
        if (now - st.collapseStart >= COLLAPSE_DUR_MS + 60) beginBackfill(now);
      } else if (st.phase === "backfilling") {
        st.backfillAcc += dt * 1000;
        while (st.backfillAcc >= BACKFILL_GRAIN_MS && st.backfillSpawned < st.backfillTarget) {
          st.backfillAcc -= BACKFILL_GRAIN_MS;
          st.backfillSpawned += 1;
          spawnBackfillGrain(now);
        }
        if (now - st.backfillStart >= BACKFILL_DUR_MS) {
          st.phase = "waiting";
          st.waitStart = now;
        }
      } else if (st.phase === "waiting") {
        if (now - st.waitStart >= RENUCLEATE_DELAY_MS) renucleate(now);
      }

      draw(now);
      st.raf = requestAnimationFrame(tick);
    };

    const wake = () => {
      if (st.raf || !st.visible || st.reduced) return;
      st.last = 0;
      st.raf = requestAnimationFrame(tick);
    };

    // -- reduced motion: run the sim forward deterministically to exactly
    // the post-collapse, pre-backfill instant (crater fully open, walls
    // sharp) and render once — the single most structured frame. ---------
    const runReducedToFreeze = () => {
      const stepMs = 16;
      let now = st.mountedAt;
      let safety = 0;
      while (st.phase !== "collapsing" && safety < 4000) {
        now += stepMs;
        const dt = stepMs / 1000;
        st.voidFrac = Math.min(1, st.voidFrac + RAVEL_RATE * dt);
        st.raveAcc += stepMs;
        while (st.raveAcc >= RAVEL_TICK_MS) {
          st.raveAcc -= RAVEL_TICK_MS;
          raveTick(now);
        }
        if (st.voidFrac >= COLLAPSE_THRESHOLD) beginCollapse(now, false);
        safety++;
      }
      // land every triggered fall exactly at its finished state
      for (const g of st.grains) {
        if (g.state === "falling") g.state = "gone";
      }
      draw(now + COLLAPSE_DUR_MS + 10);
    };

    const startField = () => {
      const rect = root.getBoundingClientRect();
      const w = rect.width;
      const h = rect.height;
      if (w < 2 || h < 2) return;
      st.dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.max(1, Math.round(w * st.dpr));
      canvas.height = Math.max(1, Math.round(h * st.dpr));
      canvas.style.width = `${w}px`;
      canvas.style.height = `${h}px`;
      st.w = w;
      st.h = h;
      const minDim = Math.min(w, h);
      const rand = mulberry32(0x9e3779 ^ st.seedCounter);
      st.seedCounter += 1;
      const built = buildGrains(w, h, minDim, rand);
      st.grains = built.grains;
      st.rows = built.rows;
      st.avgR = built.avgR;
      st.chimneyBase = minDim * 0.17;
      st.chimneyX = w * (0.32 + rand() * 0.36);
      st.voidFrac = 0;
      st.phase = "ravel";
      st.raveAcc = 0;
      st.lastJitterAt = 0;
      st.jitterMult = 1;

      cancelAnimationFrame(st.raf);
      st.raf = 0;
      st.last = 0;

      if (st.reduced) {
        runReducedToFreeze();
        return;
      }
      draw(performance.now());
      wake();
    };

    let resizeTimer = 0;
    const onResize = () => {
      window.clearTimeout(resizeTimer);
      resizeTimer = window.setTimeout(startField, 100);
    };
    const ro = new ResizeObserver(onResize);
    ro.observe(root);

    const io = new IntersectionObserver(([entry]) => {
      st.visible = entry?.isIntersecting ?? true;
      if (st.visible) wake();
      else if (st.raf) {
        cancelAnimationFrame(st.raf);
        st.raf = 0;
      }
    });
    io.observe(root);

    const onVisChange = () => {
      if (document.hidden) {
        if (st.raf) {
          cancelAnimationFrame(st.raf);
          st.raf = 0;
        }
      } else {
        wake();
      }
    };
    document.addEventListener("visibilitychange", onVisChange);

    const mo = new MutationObserver(syncTokens);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const onMq = () => {
      st.reduced = mq.matches;
      if (st.raf) {
        cancelAnimationFrame(st.raf);
        st.raf = 0;
      }
      startField();
    };
    st.reduced = mq.matches;
    mq.addEventListener("change", onMq);

    syncTokens();
    startField();

    // -- confirm arm/commit — click driven, keyboard-equivalent via Enter/
    // Space on the button, Escape and blur both de-arm. --------------------
    const deArm = () => {
      if (!st.armed) return;
      st.armed = false;
      setArmed(false);
      setAnnouncement("");
      window.clearTimeout(st.armTimer);
    };

    const handleActivate = () => {
      if (st.phase !== "ravel") return;
      if (!st.armed) {
        st.armed = true;
        setArmed(true);
        setAnnouncement("Armed. Confirm to collapse.");
        window.clearTimeout(st.armTimer);
        st.armTimer = window.setTimeout(deArm, armWindowRef.current);
      } else {
        window.clearTimeout(st.armTimer);
        st.armed = false;
        setArmed(false);
        beginCollapse(performance.now(), true);
        wake();
      }
    };

    const btn = root.querySelector<HTMLButtonElement>("[data-sinkhole-confirm]");
    const onClick = () => handleActivate();
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape" && st.armed) deArm();
    };
    const onBlur = () => deArm();
    btn?.addEventListener("click", onClick);
    btn?.addEventListener("keydown", onKeyDown);
    btn?.addEventListener("blur", onBlur);

    return () => {
      cancelAnimationFrame(st.raf);
      st.raf = 0;
      window.clearTimeout(resizeTimer);
      window.clearTimeout(st.armTimer);
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", onVisChange);
      mq.removeEventListener("change", onMq);
      btn?.removeEventListener("click", onClick);
      btn?.removeEventListener("keydown", onKeyDown);
      btn?.removeEventListener("blur", onBlur);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div
      ref={rootRef}
      className={["ns-skr relative overflow-hidden rounded-[12px] border border-border bg-background", className].join(" ")}
    >
      <canvas ref={canvasRef} aria-hidden="true" className="pointer-events-none block h-full w-full" />
      <div className="pointer-events-none absolute inset-x-0 bottom-0 flex justify-end p-3">
        <button
          type="button"
          data-sinkhole-confirm
          data-armed={armed}
          className="ns-skr-btn pointer-events-auto"
        >
          {armed ? armedLabel : children}
        </button>
      </div>
      <div role="status" aria-live="polite" aria-atomic="true" className="sr-only">
        {announcement}
      </div>
      <style>{CSS}</style>
    </div>
  );
}

const CSS = `
.ns-skr-btn{display:inline-flex;height:30px;align-items:center;justify-content:center;border-radius:6px;padding:0 12px;border:1px solid var(--border);background:var(--background);color:var(--ns-muted);font-family:var(--font-geist-mono,ui-monospace,monospace);font-size:11px;letter-spacing:0.02em;transition:background-color 150ms ease-out,color 150ms ease-out,border-color 150ms ease-out}
.ns-skr-btn:hover{color:var(--foreground);border-color:var(--foreground)}
.ns-skr-btn:focus-visible{outline:2px solid var(--ns-accent);outline-offset:2px}
.ns-skr-btn[data-armed="true"]{color:var(--ns-accent);border-color:var(--ns-accent)}
@media (prefers-reduced-motion: reduce){
  .ns-skr-btn{transition:none}
}
`;

export default SinkholeRavel;

"use client";

import { useEffect, useRef, useState, type CSSProperties, type ReactNode } from "react";

// Loading wrapper whose placeholder DEVELOPS into the real content, like a
// print coming up in a tray: on `loading` -> false both layers are stacked and
// a soft-edged alpha mask sweeps downward — the ghost blocks dissolve and
// settle upward as the children un-blur behind them, top first. No swap, no
// flash. While loading, each block carries a token-derived sweep (a recessed
// --background trough followed by a --ns-muted crest over a --border bed), not the
// white-to-grey shine every skeleton on the internet ships.
//
// Layout comes from the declarative `blocks` prop — the children are never
// measured, because while loading they are not mounted at all. Everything
// animating is CSS (compositor-friendly, zero rAF); React only runs the
// three-state phase machine. prefers-reduced-motion drops to an instant swap
// with still blocks.

export type SkeletonBlock =
  /** One emphasised bar. `width` is a fraction of the container, 0..1. */
  | { kind: "heading"; width?: number }
  /** `lines` body bars; the last one is short, the way a paragraph ends. */
  | { kind: "text"; lines?: number; width?: number }
  /** Avatar / icon disc. `size` in px. */
  | { kind: "circle"; size?: number }
  /** Media or card placeholder. `height` in px, `width` a fraction. */
  | { kind: "box"; height?: number; width?: number }
  /** Horizontal group — an avatar beside its two lines, a row of chips. */
  | { kind: "row"; gap?: number; align?: "start" | "center"; items: SkeletonBlock[] };

export interface DevelopSkeletonProps {
  /** While true the placeholder is shown; flipping it false runs the develop. */
  loading: boolean;
  /** The real content. Not rendered — and so never measured — while loading. */
  children: ReactNode;
  /** Placeholder layout. Defaults to a heading over three lines of text. */
  blocks?: SkeletonBlock[];
  /** Duration of the develop transition, ms. */
  developMs?: number;
  /** Announced to screen readers while loading. */
  loadingLabel?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

type Phase = "loading" | "developing" | "ready";

const DEFAULT_BLOCKS: SkeletonBlock[] = [
  { kind: "heading", width: 0.55 },
  { kind: "text", lines: 3 },
];

const CSS = `
.ns-dev-bar{position:relative;overflow:hidden;background:var(--border)}
.ns-dev-bar::after{
  content:"";position:absolute;inset:0;
  background-image:linear-gradient(100deg,
    transparent 22%,
    color-mix(in oklab, var(--background) 55%, transparent) 39%,
    color-mix(in oklab, var(--ns-muted) 24%, transparent) 52%,
    transparent 74%);
  transform:translateX(-100%);
  /* the delay is a custom property, not animation-delay on the host element:
     animation-delay does not inherit into ::after, custom properties do */
  animation:ns-dev-sweep 2600ms cubic-bezier(.42,0,.2,1) var(--ns-dev-delay,0ms) infinite;
}
@keyframes ns-dev-sweep{0%{transform:translateX(-100%)}64%,100%{transform:translateX(100%)}}

/* Alpha masks only — the gradients below are opacity ramps, not ink. */
.ns-dev-content{
  -webkit-mask-image:linear-gradient(to bottom,rgb(0 0 0/1) 0 33%,rgb(0 0 0/0) 47% 100%);
  mask-image:linear-gradient(to bottom,rgb(0 0 0/1) 0 33%,rgb(0 0 0/0) 47% 100%);
  -webkit-mask-size:100% 300%;mask-size:100% 300%;
  -webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;
  animation:ns-dev-resolve var(--ns-dev-ms) cubic-bezier(.22,1,.36,1) both;
}
@keyframes ns-dev-resolve{
  from{-webkit-mask-position:0 100%;mask-position:0 100%;filter:blur(7px) contrast(.7)}
  to{-webkit-mask-position:0 0%;mask-position:0 0%;filter:blur(0) contrast(1)}
}
.ns-dev-ghost{
  transform-origin:top center;
  -webkit-mask-image:linear-gradient(to bottom,rgb(0 0 0/0) 0 33%,rgb(0 0 0/1) 47% 100%);
  mask-image:linear-gradient(to bottom,rgb(0 0 0/0) 0 33%,rgb(0 0 0/1) 47% 100%);
  -webkit-mask-size:100% 300%;mask-size:100% 300%;
  -webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;
  animation:ns-dev-dissolve var(--ns-dev-ms) cubic-bezier(.22,1,.36,1) both;
}
@keyframes ns-dev-dissolve{
  from{-webkit-mask-position:0 100%;mask-position:0 100%;filter:blur(0);transform:scaleY(1)}
  to{-webkit-mask-position:0 0%;mask-position:0 0%;filter:blur(5px);transform:scaleY(.975)}
}
@media (prefers-reduced-motion: reduce){
  .ns-dev-bar::after{animation:none;background-image:none}
  .ns-dev-content,.ns-dev-ghost{animation:none;-webkit-mask-image:none;mask-image:none;filter:none}
}
`;

function renderBlocks(blocks: SkeletonBlock[], seq: { n: number }): ReactNode[] {
  return blocks.map((block, i) => {
    // negative delays offset each bar's sweep so the panel reads as one wave
    // travelling through it rather than every bar flashing in lockstep
    const bar = (width: number, height: number, radius: string) => (
      <div
        className={`ns-dev-bar ${radius}`}
        style={
          {
            width: `${width * 100}%`,
            height,
            "--ns-dev-delay": `${-140 * seq.n++}ms`,
          } as CSSProperties
        }
      />
    );

    switch (block.kind) {
      case "heading":
        return <div key={i}>{bar(block.width ?? 0.55, 20, "rounded-sm")}</div>;
      case "text": {
        const lines = Math.max(1, block.lines ?? 3);
        const width = block.width ?? 1;
        return (
          <div key={i} className="flex flex-col gap-3">
            {Array.from({ length: lines }, (_, l) => (
              // a paragraph's last line stops short — without it the block
              // reads as a table, not prose
              <div key={l}>{bar(l === lines - 1 ? width * 0.62 : width, 12, "rounded-full")}</div>
            ))}
          </div>
        );
      }
      case "circle": {
        const size = block.size ?? 40;
        return (
          <div
            key={i}
            className="ns-dev-bar shrink-0 rounded-full"
            style={
              { width: size, height: size, "--ns-dev-delay": `${-140 * seq.n++}ms` } as CSSProperties
            }
          />
        );
      }
      case "box":
        return <div key={i}>{bar(block.width ?? 1, block.height ?? 120, "rounded-md")}</div>;
      case "row":
        return (
          <div
            key={i}
            className="flex w-full"
            style={{ gap: block.gap ?? 12, alignItems: block.align === "center" ? "center" : "flex-start" }}
          >
            {block.items.map((item, j) => (
              // a disc keeps its own size; everything else shares the rest
              <div key={j} className={item.kind === "circle" ? "shrink-0" : "min-w-0 flex-1"}>
                {renderBlocks([item], seq)}
              </div>
            ))}
          </div>
        );
    }
  });
}

export function DevelopSkeleton({
  loading,
  children,
  blocks = DEFAULT_BLOCKS,
  developMs = 900,
  loadingLabel = "Loading",
  className = "",
}: DevelopSkeletonProps) {
  const [reduced, setReduced] = useState(false);
  const [phase, setPhase] = useState<Phase>(loading ? "loading" : "ready");
  // content that mounted already-loaded must not play a develop it never earned
  const wasLoading = useRef(loading);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const onChange = () => setReduced(mq.matches);
    onChange();
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  useEffect(() => {
    if (loading) {
      wasLoading.current = true;
      setPhase("loading");
      return;
    }
    if (!wasLoading.current) {
      setPhase("ready");
      return;
    }
    wasLoading.current = false;
    if (reduced) {
      setPhase("ready");
      return;
    }
    setPhase("developing");
    const id = window.setTimeout(() => setPhase("ready"), developMs);
    // flipping back to loading mid-develop lands here first: the pending
    // settle is dropped, so the ghost cannot un-hide a half-developed layer
    return () => window.clearTimeout(id);
  }, [loading, developMs, reduced]);

  const developing = phase === "developing";
  const vars = { "--ns-dev-ms": `${developMs}ms` } as CSSProperties;

  return (
    <div className={`relative ${className}`} style={vars} aria-busy={phase !== "ready"}>
      <style>{CSS}</style>

      {phase !== "loading" && (
        <div className={developing ? "ns-dev-content" : undefined}>{children}</div>
      )}

      {phase !== "ready" && (
        <div
          aria-hidden
          className={[
            "flex w-full flex-col gap-4",
            developing ? "ns-dev-ghost pointer-events-none absolute inset-0" : "",
          ].join(" ")}
        >
          {renderBlocks(blocks, { n: 0 })}
        </div>
      )}

      {phase === "loading" && (
        <span role="status" className="sr-only">
          {loadingLabel}
        </span>
      )}
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";

// SlipCast — pour streaming, schema-shaped JSON into a visible mold. The
// moment the schema is known (before a single token of data has arrived) the
// full shape of the answer renders as a skeleton of empty slots: every key
// already typeset in Geist Mono at --ns-muted, sitting in a dashed 1px --border
// blank pre-sized by its declared type (numbers short, booleans a fixed
// true/false width, strings full-row so a long value never reflows the row
// that holds it). That skeleton IS the progress bar — there is no separate
// spinner or bar element anywhere in this component.
//
// As each value streams in, its slot — and only its slot — flips from
// pending to set: the dashed border crossfades to solid over 150ms
// ease-out-expo (border-style itself can't be animated, so this is two
// stacked frames whose opacity crosses over, not a literal style
// interpolation), the value drops in with a small spring overshoot
// (translateY 3px -> 0), and a 4px corner tick fades --ns-muted -> --foreground.
// Nested objects get the same dashed->solid treatment on their own
// container, independent of whether their children have filled yet — a
// nested object "sets" the instant its key exists in the stream, even with
// every field inside it still dashed. Arrays keep two ghost rows appended
// past the last arrived item at all times, so the row a value is about to
// land in was already on screen, dashed, before it filled — nothing new
// reflows into existence under the incoming value itself, only the trailing
// ghost buffer grows. Nesting indents in fixed 16px steps.
//
// Content that mounts already-complete (a value with every field present on
// first render) skips the fill animation entirely — the "live" transitions
// only arm after mount, so a component that never streamed doesn't play a
// pointless cascade.
//
// Unlike a generic content-shaped loading skeleton (bars standing in for
// unknown prose), this is schema-driven and field-granular: real keys are
// typeset before any value exists, every slot tracks its own pending/set
// state independently, and a slot still dashed when streaming ends is left
// exactly as dashed — an honest "this field never arrived" rather than a
// skeleton dissolving into empty space. It renders the *shape* of a
// streaming payload; it does not own the character-level caret inside a
// value that is itself still arriving — that's streaming-markdown-caret's job, and the two
// compose (a string slot's value can itself be a streaming-markdown-caret span).
//
// Pure DOM + CSS: real dt/dd pairs inside real dl elements (nested objects
// get a nested dl, array items a dl per row), role=region with aria-busy
// while streaming, a visually-hidden aria-live=polite region that announces
// batched "N of M fields complete" milestones (debounced, never per-token),
// and exactly one focusable control per top-level object: a Copy JSON
// button. Colors are tokens only (--background --foreground --ns-muted
// --border --ns-accent); --ns-accent appears only on the copy button's focus
// ring. prefers-reduced-motion drops every transition — slots simply appear
// filled, nothing eases.

export type SlotType = "string" | "number" | "boolean" | "null";
export type SlotKind = SlotType | "object" | "array";

export interface SlotSchema {
  /** the real field name, typeset verbatim as the dt */
  key: string;
  kind: SlotKind;
  /** children, for kind: "object" */
  fields?: SlotSchema[];
  /** shape of one array item, for kind: "array" — an object shape, or a scalar kind for a flat array */
  item?: SlotSchema[] | SlotType;
}

export type JsonValue =
  | string
  | number
  | boolean
  | null
  | JsonValue[]
  | { [key: string]: JsonValue }
  | undefined;

export type JsonRecord = Record<string, JsonValue>;

export interface SlipCastProps {
  /** the known shape of the answer, available before any value has arrived */
  schema: SlotSchema[];
  /** the accumulated value so far — a deep-partial object; absent keys read as pending */
  value: JsonRecord | undefined;
  /** true while more values are still expected; drives aria-busy and the milestone copy */
  streaming?: boolean;
  /** accessible name for the region, and the noun the copy button acts on */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const GHOST_ROWS_AHEAD = 2;
const ANNOUNCE_DEBOUNCE_MS = 350;

function hasOwn(obj: unknown, key: string): obj is Record<string, JsonValue> {
  return typeof obj === "object" && obj !== null && Object.prototype.hasOwnProperty.call(obj, key);
}

function getAtPath(root: JsonValue, path: string): { present: boolean; value: JsonValue } {
  let cur: JsonValue = root;
  for (const part of path.split(".")) {
    if (!hasOwn(cur, part)) return { present: false, value: undefined };
    cur = (cur as JsonRecord)[part];
    if (cur === undefined) return { present: false, value: undefined };
  }
  return { present: true, value: cur };
}

/** Flattens the schema into the fixed set of slots the milestone count is
 * measured against. Arrays count as exactly one slot — their item rows are
 * unbounded and streaming, so they're excluded from the denominator or "4 of
 * 9" would keep retargeting mid-stream. */
function flattenSchema(fields: SlotSchema[], base = ""): string[] {
  const out: string[] = [];
  for (const f of fields) {
    const path = base ? `${base}.${f.key}` : f.key;
    out.push(path);
    if (f.kind === "object" && f.fields) out.push(...flattenSchema(f.fields, path));
  }
  return out;
}

function formatScalar(kind: SlotType, value: JsonValue): ReactNode {
  if (kind === "null") return <span className="italic">null</span>;
  if (kind === "boolean") return value ? "true" : "false";
  if (kind === "number") return typeof value === "number" ? value.toLocaleString() : String(value ?? "");
  return typeof value === "string" ? value : String(value ?? "");
}

function ValueSlot({ kind, present, value }: { kind: SlotType; present: boolean; value: JsonValue }) {
  return (
    <span className={`ns-slip-value-wrap ns-slip-${kind}`} data-state={present ? "set" : "pending"}>
      <span className="ns-slip-edge ns-slip-edge-dashed" aria-hidden="true" />
      <span className="ns-slip-edge ns-slip-edge-solid" aria-hidden="true" />
      <span className="ns-slip-tick" aria-hidden="true" />
      <span className="ns-slip-value">{present ? formatScalar(kind, value) : ""}</span>
    </span>
  );
}

function ObjectSlot({ present, children }: { present: boolean; children: ReactNode }) {
  // a div, not a span: a <dl> is flow content and cannot legally nest inside
  // phrasing content — a span wrapper here would get silently reparented by
  // the HTML parser, taking the edge-overlay positioning context with it
  return (
    <div className="ns-slip-container" data-state={present ? "set" : "pending"}>
      <span className="ns-slip-edge ns-slip-edge-dashed" aria-hidden="true" />
      <span className="ns-slip-edge ns-slip-edge-solid" aria-hidden="true" />
      <span className="ns-slip-tick" aria-hidden="true" />
      <dl className="ns-slip-dl">{children}</dl>
    </div>
  );
}

function renderField(field: SlotSchema, parent: JsonValue, depth: number, keyPrefix: string): ReactNode {
  const present = hasOwn(parent, field.key);
  const raw = present ? (parent as JsonRecord)[field.key] : undefined;
  const rowKey = `${keyPrefix}.${field.key}`;
  const indent = { paddingLeft: depth * 16 };

  if (field.kind === "object") {
    const nested = field.fields ?? [];
    return (
      <div className="ns-slip-row" style={indent} key={rowKey}>
        <dt className="ns-slip-key">{field.key}</dt>
        <dd>
          <ObjectSlot present={present}>
            {nested.map((child) => renderField(child, raw, depth + 1, rowKey))}
          </ObjectSlot>
        </dd>
      </div>
    );
  }

  if (field.kind === "array") {
    const arr = present && Array.isArray(raw) ? raw : [];
    const rowCount = arr.length + GHOST_ROWS_AHEAD;
    const itemFields = Array.isArray(field.item) ? field.item : undefined;
    const scalarKind: SlotType = typeof field.item === "string" ? field.item : "string";
    return (
      <div className="ns-slip-row" style={indent} key={rowKey}>
        <dt className="ns-slip-key">{field.key}</dt>
        <dd>
          <ObjectSlot present={present}>
            {Array.from({ length: rowCount }, (_, i) => {
              const itemPresent = i < arr.length;
              const itemValue = itemPresent ? arr[i] : undefined;
              const itemRowKey = `${rowKey}.${i}`;
              if (itemFields) {
                return (
                  <div className="ns-slip-row" style={{ paddingLeft: (depth + 1) * 16 }} key={itemRowKey}>
                    <dt className="ns-slip-index">[{i}]</dt>
                    <dd>
                      <ObjectSlot present={itemPresent}>
                        {itemFields.map((child) => renderField(child, itemValue, depth + 2, itemRowKey))}
                      </ObjectSlot>
                    </dd>
                  </div>
                );
              }
              return (
                <div className="ns-slip-row" style={{ paddingLeft: (depth + 1) * 16 }} key={itemRowKey}>
                  <dt className="ns-slip-index">[{i}]</dt>
                  <dd>
                    <ValueSlot kind={scalarKind} present={itemPresent} value={itemValue} />
                  </dd>
                </div>
              );
            })}
          </ObjectSlot>
        </dd>
      </div>
    );
  }

  return (
    <div className="ns-slip-row" style={indent} key={rowKey}>
      <dt className="ns-slip-key">{field.key}</dt>
      <dd>
        <ValueSlot kind={field.kind} present={present} value={raw} />
      </dd>
    </div>
  );
}

async function copyToClipboard(text: string): Promise<boolean> {
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(text);
      return true;
    }
  } catch {
    // fall through to the legacy path below
  }
  try {
    const ta = document.createElement("textarea");
    ta.value = text;
    ta.style.position = "fixed";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.focus();
    ta.select();
    const ok = document.execCommand("copy");
    document.body.removeChild(ta);
    return ok;
  } catch {
    return false;
  }
}

