const DEFAULT_ITEMS: SlateTestimonial[] = DEFAULT_QUOTES.map((q, i) => ({
  id: `slate-${i + 1}`,
  ...q,
}));

interface Slate {
  index: number;
  row: number;
  col: number;
  x: number; // design px, unscaled
  top: number; // design px, unscaled — top of this course's exposed gauge
  h: number;
  gauge: number;
  exposure: number;
  centreNailed: boolean;
}

function layout(items: SlateTestimonial[], columns: number): { slates: Slate[]; naturalW: number; naturalH: number } {
  const cols = Math.max(1, columns);
  const rows = Math.ceil(items.length / cols);
  const courseTop: number[] = [0];
  for (let r = 0; r < rows; r++) courseTop.push(courseTop[r] + COURSES[r % COURSES.length].exposure);

  const slates: Slate[] = items.map((_, i) => {
    const row = Math.floor(i / cols);
    const col = i % cols;
    const course = COURSES[row % COURSES.length];
    const offset = row % 2 === 1 ? COL_OFFSET : 0;
    return {
      index: i,
      row,
      col,
      x: col * SLATE_W + offset,
      top: courseTop[row],
      h: course.h,
      gauge: course.gauge,
      exposure: course.exposure,
      centreNailed: isCentreNailed(i),
    };
  });

  const naturalW = cols * SLATE_W + COL_OFFSET;
  const naturalH = courseTop[rows]; // sum of every course's exposure — the last course's excess is trimmed
  return { slates, naturalW, naturalH };
}

export function SlateGauge({
  items = DEFAULT_ITEMS,
  columns = 3,
  heading = "What teams say",
  className = "",
}: SlateGaugeProps) {
  const hostRef = useRef<HTMLDivElement>(null);
  const wallRef = useRef<HTMLDivElement>(null);
  const slateFaceRefs = useRef<Record<number, HTMLElement | null>>({});
  const rivenRefs = useRef<Record<number, HTMLDivElement | null>>({});
  const [liftedIndex, setLiftedIndex] = useState<number | null>(null);
  const [scale, setScale] = useState(1);
  const liftedRef = useRef<number | null>(null);
  liftedRef.current = liftedIndex;

  const { slates, naturalW, naturalH } = useMemo(() => layout(items, columns), [items, columns]);

  // reduced-motion picks one representative slate to hold lifted and one
  // centre-nailed slate near the frozen gust to hold mid-clatter, so the
  // single composed frame shows every state the wall has at once (spec §5)
  const staticPicks = useMemo(() => {
    const gustCol = Math.min(1, Math.max(0, columns - 1));
    const lifted = Math.min(2, slates.length - 1);
    const near = slates.find((s) => s.centreNailed && s.col === gustCol) ?? slates.find((s) => s.centreNailed);
    return { lifted, microLift: near?.index ?? null };
  }, [slates, columns]);

  const rivenBg = useMemo(() => {
    // deterministic per-slate band pattern (spacing only — colours are
    // re-applied on token read) computed once so it is byte-stable forever
    const maps: Record<number, { start: number; end: number }[]> = {};
    for (const s of slates) {
      const bands: { start: number; end: number }[] = [];
      let y = 0;
      let seed = s.index * 97 + 11;
      while (y < s.h) {
        const w = 3 + hash(seed) * 6; // 3-9px
        bands.push({ start: y, end: Math.min(s.h, y + w) });
        y += w;
        seed += 1;
      }
      maps[s.index] = bands;
    }
    return maps;
  }, [slates]);

  // ---- token read, geometry fit, and the whole idle loop -----------------
  useLayoutEffect(() => {
    const host = hostRef.current;
    const wall = wallRef.current;
    if (!host || !wall) return;

    // token read happens before anything paints — see the class comment
    let tokens = readTokens();
    const applyTokens = () => {
      wall.style.setProperty("--slate-face", tokens.face);
      wall.style.setProperty("--slate-margin", tokens.margin);
      wall.style.setProperty("--slate-shadow-color", tokens.shadow);
      wall.style.setProperty("--slate-edge", tokens.edge);
      wall.style.setProperty("--slate-backing", tokens.backing);
      wall.style.setProperty("--slate-riven", tokens.riven);
      wall.style.setProperty("--slate-ink", tokens.ink);
      wall.style.setProperty("--slate-ink-muted", tokens.inkMuted);
      // repaint riven band gradients with the fresh colour pair — percentage
      // stops (of the slate's own full height) so the pattern never needs to
      // be re-scaled when the fit scale or the lift height changes
      for (const s of slates) {
        const el = rivenRefs.current[s.index];
        if (!el) continue;
        const stops = rivenBg[s.index]
          .map((b, i) => {
            // ±0.03L fracture banding (section 6) — a texture on the stone
            // itself, distinct from the sky-lit margin tint layered above it
            const c = i % 2 === 0 ? tokens.face : tokens.riven;
            return `${c} ${(b.start / s.h) * 100}%, ${c} ${(b.end / s.h) * 100}%`;
          })
          .join(", ");
        el.style.backgroundImage = `linear-gradient(to bottom, ${stops})`;
      }
    };
    applyTokens();

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    const fit = () => {
      const rect = host.getBoundingClientRect();
      if (rect.width < 4 || rect.height < 4) return;
      const s = Math.max(SCALE_MIN, Math.min(SCALE_MAX, Math.min(rect.width / naturalW, rect.height / naturalH)));
      setScale(s);
    };
    fit();
    const ro = new ResizeObserver(fit);
    ro.observe(host);

    if (reduced) {
      // one composed still frame, byte-stable: no loop, no listeners
      wall.style.setProperty("--wall-azimuth", "-6");
      if (staticPicks.microLift != null) {
        const el = slateFaceRefs.current[staticPicks.microLift];
        if (el) el.style.setProperty("--gust-lift", "5");
      }
      setLiftedIndex(staticPicks.lifted);
      const liftedEl = slateFaceRefs.current[staticPicks.lifted];
      if (liftedEl) liftedEl.style.transform = `rotate(${LIFT_TARGET}deg)`;
      return () => ro.disconnect();
    }

    // ---- continuous idle loop: gust field + light azimuth + micro-lifts --
    let raf = 0;
    let running = false;
    let last = performance.now();
    let t = 0;
    const liftState = new Map<number, { v: number; vel: number; target: number }>();
    let readLift = { v: 0, vel: 0 };

    // the slate currently returning after release is tracked separately from
    // the one actively held, since liftedIndex can flip to null the instant
    // a pointer leaves — the spring still needs a face to write to
    let lastHeld: number | null = null;
    const tick = (now: number) => {
      raf = requestAnimationFrame(tick);
      const dt = Math.min(0.05, Math.max(0, (now - last) / 1000));
      last = now;
      t += dt;

      const azimuth = AZIMUTH_DEG * Math.cos((2 * Math.PI * t) / AZIMUTH_PERIOD);
      wall.style.setProperty("--wall-azimuth", azimuth.toFixed(2));

      // gust math stays entirely in natural (unscaled) design units, the same
      // space slate.x already lives in — the fit `scale` only ever touches
      // the JSX render, never this comparison
      const span = naturalW + GUST_WIDTH * 2;
      const frac = (t % GUST_PERIOD) / GUST_PERIOD;
      const gustX = -GUST_WIDTH + frac * span;

      for (const s of slates) {
        if (!s.centreNailed) continue;
        const el = slateFaceRefs.current[s.index];
        if (!el) continue;
        const centerX = s.x + SLATE_W / 2;
        const inGust = Math.abs(centerX - gustX) < GUST_WIDTH / 2;
        const amp = 2.5 + hash(s.index * 31 + 7) * 2.5;
        let st = liftState.get(s.index);
        if (!st) {
          st = { v: 0, vel: 0, target: 0 };
          liftState.set(s.index, st);
        }
        st.target = inGust ? amp : 0;
        const [nv, nvel] = springStep(st.v, st.vel, st.target, GUST_LIFT_K, GUST_LIFT_C, dt);
        st.v = nv;
        st.vel = nvel;
        el.style.setProperty("--gust-lift", st.v.toFixed(2));
      }

      const held = liftedRef.current;
      const activeIndex = held ?? lastHeld;
      if (held != null) lastHeld = held;
      if (activeIndex != null) {
        const el = slateFaceRefs.current[activeIndex];
        const target = held != null ? LIFT_TARGET : 0;
        const [nv, nvel] = springStep(readLift.v, readLift.vel, target, LIFT_K, LIFT_C, dt);
        readLift = { v: nv, vel: nvel };
        if (el) el.style.transform = nv === 0 ? "" : `rotate(${nv.toFixed(2)}deg)`;
        if (held == null && Math.abs(nv) < 0.02 && Math.abs(nvel) < 0.02) {
          if (el) el.style.transform = "";
          lastHeld = null;
          readLift = { v: 0, vel: 0 };
        }
      }
    };
    running = true;
    raf = requestAnimationFrame(tick);

    const io = new IntersectionObserver(
      (entries) => {
        const visible = entries.some((e) => e.isIntersecting);
        if (visible && !running) {
          running = true;
          last = performance.now();
          raf = requestAnimationFrame(tick);
        } else if (!visible && running) {
          running = false;
          cancelAnimationFrame(raf);
        }
      },
      { threshold: 0 }
    );
    io.observe(host);

    const onVis = () => {
      if (document.hidden && running) {
        running = false;
        cancelAnimationFrame(raf);
      } else if (!document.hidden && !running) {
        running = true;
        last = performance.now();
        raf = requestAnimationFrame(tick);
      }
    };
    document.addEventListener("visibilitychange", onVis);

    const mo = new MutationObserver(() => {
      tokens = readTokens();
      applyTokens();
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    return () => {
      ro.disconnect();
      io.disconnect();
      document.removeEventListener("visibilitychange", onVis);
      mo.disconnect();
      cancelAnimationFrame(raf);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [slates, naturalW, naturalH, rivenBg, staticPicks]);

  const toggle = (index: number) => {
    setLiftedIndex((prev) => (prev === index ? null : index));
  };

  return (
    <div ref={hostRef} className={`relative flex h-full w-full flex-col items-center justify-center gap-4 overflow-hidden bg-background p-4 ${className}`}>
      <p className="font-mono text-xs tracking-widest text-ns-muted">{heading}</p>
      <div
        ref={wallRef}
        className="relative shrink-0"
        // the eaves rail occupies its own band below the last course rather
        // than overlaying it — laid on top it clipped the foot course's last
        // line, which is the exact fault it exists to prevent
        style={{ width: naturalW * scale, height: naturalH * scale + Math.max(4, 6 * scale) }}
      >
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 z-0 rounded-[1px]"
          style={{ backgroundColor: "var(--slate-backing)" }}
        />
        {/* The eaves. Every interior course is cut off by the slate lapping
            over it, which is what reads as overlap; the bottom course has
            nothing above it, so without a rail its cut edge reads as
            truncated text instead of as the foot of the wall. */}
        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-x-0 z-[1001]"
          style={{
            bottom: 0,
            height: Math.max(4, 6 * scale),
            backgroundColor: "var(--slate-shadow-color)",
            boxShadow: [
              `inset 0 ${Math.max(1, scale)}px 0 0 var(--slate-edge)`,
              `0 ${-3 * scale}px ${8 * scale}px ${-2 * scale}px var(--slate-shadow-color)`,
            ].join(", "),
          }}
        />
        {slates.map((s) => {
          const isLifted = liftedIndex === s.index;
          const padAbove = Math.max(0, MIN_HIT - s.exposure * scale);
          return (
            <button
              key={items[s.index].id}
              type="button"
              aria-expanded={isLifted}
              data-expanded={isLifted}
              data-slate-lift
              aria-label={`${isLifted ? "Collapse" : "Read"} testimonial from ${items[s.index].name}`}
              onClick={() => toggle(s.index)}
              onBlur={() => {
                if (liftedRef.current === s.index) setLiftedIndex(null);
              }}
              onKeyDown={(e) => {
                if (e.key === "Escape" && liftedRef.current === s.index) {
                  setLiftedIndex(null);
                  (e.currentTarget as HTMLElement).blur();
                }
              }}
              className="group absolute cursor-pointer appearance-none border-0 bg-transparent p-0 text-left"
              style={{
                left: s.x * scale,
                top: s.top * scale - padAbove,
                width: SLATE_W * scale,
                height: s.exposure * scale + padAbove,
                // resting bands never overlap (each course occupies exactly
                // its own gauge, edge to edge), so z only has to win once a
                // slate is lifted and needs to paint over the course below it
                zIndex: isLifted ? 1000 : 1,
              }}
            >
              <article
                ref={(el) => {
                  slateFaceRefs.current[s.index] = el;
                }}
                data-slate-face
                className="absolute overflow-hidden rounded-[1px] border-0 bg-[var(--slate-face)] group-focus-visible:ring-2 group-focus-visible:ring-ns-accent group-focus-visible:ring-offset-1"
                style={{
                  top: padAbove,
                  left: 0,
                  width: SLATE_W * scale,
                  // at rest the face IS its gauge — only the exposed margin
                  // is ever painted; lifting grows it to the slate's real
                  // height, which is what reveals the rest of the quote
                  height: (isLifted ? s.h : s.exposure) * scale,
                  transformOrigin: `50% ${NAIL_Y * scale}px`,
                  // no colour fallback here on purpose: before the token read
                  // commits (useLayoutEffect, pre-paint) --slate-shadow-color
                  // is unset, which makes the whole box-shadow invalid and
                  // therefore simply not painted, rather than painted with a
                  // literal placeholder colour
                  // one cast shadow onto the course below (this is what makes
                  // the lap read as a slate sitting OVER its neighbour rather
                  // than as text truncated at a hard edge), one inset seam,
                  // and a sky-lit top arris. All three swing with the single
                  // root-level azimuth property.
                  boxShadow: [
                    `0 ${-1 * Math.max(1, scale)}px 0 0 var(--slate-shadow-color)`,
                    `0 ${-3 * scale}px ${7 * scale}px ${-1 * scale}px var(--slate-shadow-color)`,
                    `inset calc(var(--wall-azimuth, 0) * 0.4px) ${3 * scale}px ${5 * scale}px ${-1 * scale}px var(--slate-shadow-color)`,
                    `inset 0 ${Math.max(1, scale)}px 0 0 var(--slate-edge)`,
                  ].join(", "),
                  translate: `0 calc(var(--gust-lift, 0) * -1px)`,
                }}
              >
                {/* riven texture: a separate layer fixed at the slate's FULL
                    design height regardless of the article's current (gauge
                    or lifted) height, so its percentage-based band stops
                    always land at the same physical position on the stone —
                    the article's own overflow-hidden is what crops it to
                    whichever margin is currently showing */}
                <div
                  ref={(el) => {
                    rivenRefs.current[s.index] = el;
                  }}
                  aria-hidden="true"
                  className="absolute inset-x-0 top-0"
                  style={{ height: s.h * scale }}
                />
                {/* the exposed margin is sky-lit relative to the rest of the
                    stone (section 6, +0.06/+0.05L) — a fixed-height tint over
                    exactly the gauge strip, independent of the article's own
                    current (gauge or lifted) height */}
                <div
                  aria-hidden="true"
                  className="absolute inset-x-0 top-0 bg-[var(--slate-margin)] opacity-40"
                  style={{ height: s.exposure * scale }}
                />
                <div
                  className="relative flex h-full flex-col"
                  style={{
                    color: "var(--slate-ink)",
                    padding: `${PAD_Y * scale}px ${8 * scale}px`,
                    // type is scaled with the wall, not left at a fixed pixel
                    // size — a fixed 10px against a gauge that grows with the
                    // fit scale is what left a half line at every lap
                    fontSize: `${FONT_PX * scale}px`,
                    lineHeight: LINE_RATIO,
                  }}
                >
                  {/* always full text in the DOM, never display:none — the
                      gauge-height article above is what occludes it visually */}
                  <blockquote className="m-0">&ldquo;{items[s.index].quote}&rdquo;</blockquote>
                  <footer
                    className="m-0 font-medium"
                    style={{ color: "var(--slate-ink-muted)", fontSize: `${FONT_PX * scale}px` }}
                  >
                    {items[s.index].name} &middot; {items[s.index].role}
                  </footer>
                </div>
              </article>
            </button>
          );
        })}
      </div>
    </div>
  );
}

SlateGauge.displayName = "SlateGauge";

export default SlateGauge;

"use client";

import { useEffect, useRef } from "react";
import type { CSSProperties } from "react";

// ---------------------------------------------------------------------------
// SleeperRenewalRelay — an ambient "processing/refreshing" row indicator
// sourced from mechanised sleeper-renewal trains (railway maintenance-of-way
// engineering): a crawling gang crane lifts one old sleeper clear, swings a
// new one into the gap, and clips the rail down before advancing to the next
// tie, never stopping the line for more than a single swap.
//
// The stack is a fixed 8-row visible window, each row a "sleeper" whose
// vertical size (rowSize) is the container's SMALLER measured dimension
// divided by 8, so the whole panel reads at card scale regardless of the
// host's aspect ratio. A crane carriage rides a gantry line down the left
// edge; a full lift -> swap -> drop -> clip cycle takes 1.3s per row (450ms
// departure arc, 350ms arrival arc, 500ms settled dwell — the last 150ms of
// which slides the carriage on to the next row so it is already positioned
// when that row's own lift begins). Eight rows at 1.3s/row is a 10.4s lap;
// on reaching row 7 the carriage travels straight back to row 0 and the lap
// repeats, unbounded, exactly the "wraps to the top and continues" reading.
//
// Old-vs-new is NOT a binary flag. Every row carries a continuous "wear"
// value derived straight from elapsed time since its most recent completed
// drop: 0 the instant a fresh sleeper lands, ramping back toward 1 (fully
// worn) over the ~10.4s until the crane is due back — so a viewer sees a
// visible gradient across the stack (freshest just behind the crane, most
// worn just ahead of it) rather than a hard on/off flip, and the row the
// crane is CURRENTLY lifting reads its wear from the exact same continuous
// formula, so the departing sleeper's colour is already wherever it had
// smoothly drifted to — no colour ever jumps at a phase boundary. Fill is a
// single `color-mix(in srgb, var(--ns-muted) X%, var(--foreground) (100-X)%)`
// string per row, recomputed every frame; no canvas, no JS colour math, so
// a theme flip repaints for free through the underlying custom properties.
// ---------------------------------------------------------------------------

export interface SleeperRenewalRelayProps {
  /** row / card heading above the panel */
  title?: string;
  /** mono description under the heading */
  description?: string;
  /** freeze the loop at the next settled dwell point (never mid-arc) once true */
  paused?: boolean;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** inline styles merged onto the root element */
  style?: CSSProperties;
}

const ROWS = 8;
const CYCLE_MS = 1300; // one full lift -> swap -> drop -> clip cycle per row
const RISE_MS = 250; // straight vertical lift, still directly above the gap
const SWING_MS = 200; // sideways kick out to the side wagon
const LIFT_MS = RISE_MS + SWING_MS; // 450 — the visible departure arc
const ENTER_MS = 200; // new sleeper swings in from the gantry side, elevated
const SETTLE_MS = 150; // lowers into the gap with a small clip-down bounce
const DROP_MS = ENTER_MS + SETTLE_MS; // 350 — the visible arrival arc
const DROP_START = LIFT_MS; // 450
const DWELL_START = LIFT_MS + DROP_MS; // 800
const DWELL_MS = CYCLE_MS - DWELL_START; // 500
const TRAVEL_MS = 150; // tail of the dwell — carriage slides on to next row
const LAP_MS = ROWS * CYCLE_MS; // 10400
const WEAR_SPAN_CYCLES = ROWS; // wear ramps 0..1 over one lap since renewal

// reduced-motion freeze: mid rise sub-phase of row 3's departure — old
// sleeper lifted straight up, still directly above its own gap, not yet
// kicked sideways or dropped; rows 0-2 already show a fresher wear value,
// rows 4-7 have never been reached (fully worn) — old-out / new-in-pending
// / clip-pending all visible at once.
const STATIC_ROW = 3;
const STATIC_LOCAL_T = 200;
const STATIC_ELAPSED = STATIC_ROW * CYCLE_MS + STATIC_LOCAL_T;

// mount offset so the very first live frame already shows a wear gradient
// and a mid-swing crane, distinct from the reduced-motion freeze above —
// row 5, 20ms into its 200ms swing sub-phase, rows 0-4 carrying distinct
// wear values.
const INITIAL_OFFSET_MS = 5 * CYCLE_MS + RISE_MS + 20;

const REF_ROW = 32; // reference row size used to scale stroke widths

function clamp01(v: number): number {
  return v < 0 ? 0 : v > 1 ? 1 : v;
}
function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}
function easeOutCubic(t: number): number {
  const x = clamp01(t);
  return 1 - Math.pow(1 - x, 3);
}
function easeInOutCubic(t: number): number {
  const x = clamp01(t);
  return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
}

function wearColor(wear: number): string {
  const muted = clamp01(wear) * 100;
  const fresh = 100 - muted;
  return `color-mix(in srgb, var(--ns-muted) ${muted.toFixed(1)}%, var(--foreground) ${fresh.toFixed(1)}%)`;
}

/** Continuous 0 (just renewed) .. 1 (fully worn, due again) wear value for
 * a row at a given elapsed time, derived from the most recent completed
 * drop (localT >= DWELL_START) that row ever had — or 1, fixed, if the
 * crane has never reached it yet (only possible during the very first
 * lap). No stored per-row state: fully reconstructible from elapsed time
 * alone, which is what keeps every frame — including a paused resume —
 * exactly continuous. */
function rowWear(row: number, elapsedMs: number): number {
  const dropOffset = row * CYCLE_MS + DWELL_START;
  const num = elapsedMs - dropOffset;
  if (num < 0) return 1;
  const lapsSinceFirstDrop = Math.floor(num / LAP_MS);
  const completionTime = dropOffset + lapsSinceFirstDrop * LAP_MS;
  const sinceMs = elapsedMs - completionTime;
  const cyclesSince = sinceMs / CYCLE_MS;
  return clamp01(cyclesSince / WEAR_SPAN_CYCLES);
}

interface Geometry {
  w: number;
  h: number;
  rowSize: number;
  scale: number;
  stackTop: number;
  gantryX: number;
  railX1: number;
  railX2: number;
  sleeperX1: number;
  sleeperX2: number;
  sleeperH: number;
}

function measureGeometry(w: number, h: number): Geometry {
  const rowSize = Math.max(1, Math.min(w, h) / ROWS);
  const scale = rowSize / REF_ROW;
  const stackHeight = rowSize * ROWS;
  const stackTop = (h - stackHeight) / 2;
  return {
    w,
    h,
    rowSize,
    scale,
    stackTop,
    gantryX: w * 0.08,
    railX1: w * 0.3,
    railX2: w * 0.7,
    sleeperX1: w * 0.14,
    sleeperX2: w * 0.86,
    sleeperH: rowSize * 0.46,
  };
}

function rowCenterY(g: Geometry, row: number): number {
  return g.stackTop + row * g.rowSize + g.rowSize / 2;
}

export function SleeperRenewalRelay({
  title = "Backfilling search index",
  description = "One row swaps at a time — old cleared, new clipped in, never stopping the line.",
  paused = false,
  className = "",
  style,
}: SleeperRenewalRelayProps) {
  const panelRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);
  const gantryRef = useRef<SVGLineElement>(null);
  const railRefs = useRef<(SVGLineElement | null)[]>([]);
  const sleeperRefs = useRef<(SVGRectElement | null)[]>([]);
  const tickRefs = useRef<(SVGPathElement | null)[]>([]);
  const gapRef = useRef<SVGRectElement>(null);
  const movingRef = useRef<SVGRectElement>(null);
  const carriageRef = useRef<SVGRectElement>(null);
  const armRef = useRef<SVGLineElement>(null);
  const hookRef = useRef<SVGCircleElement>(null);
  const pausedRef = useRef(paused);

  useEffect(() => {
    pausedRef.current = paused;
  }, [paused]);

  useEffect(() => {
    const panel = panelRef.current;
    const svg = svgRef.current;
    if (!panel || !svg) return;

    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    let reduced = mq.matches;
    let visible = true;
    let raf = 0;
    let startTime = performance.now() - INITIAL_OFFSET_MS;
    let frozen = false;
    let frozenElapsed = 0;
    let geom = measureGeometry(panel.clientWidth || 1, panel.clientHeight || 1);

    const setAttrs = (el: Element | null, attrs: Record<string, string>) => {
      if (!el) return;
      for (const k in attrs) el.setAttribute(k, attrs[k]!);
    };

    const layout = () => {
      const rect = panel.getBoundingClientRect();
      geom = measureGeometry(Math.max(1, rect.width), Math.max(1, rect.height));
      const { w, h, gantryX, railX1, railX2, stackTop, rowSize, scale } = geom;
      svg.setAttribute("viewBox", `0 0 ${w} ${h}`);
      svg.setAttribute("width", String(w));
      svg.setAttribute("height", String(h));
      const stackBottom = stackTop + rowSize * ROWS;

      setAttrs(gantryRef.current, {
        x1: String(gantryX),
        x2: String(gantryX),
        y1: String(stackTop),
        y2: String(stackBottom),
        "stroke-width": String(Math.max(0.75, 1 * scale)),
      });
      const rails = railRefs.current;
      [railX1, railX2].forEach((x, i) => {
        setAttrs(rails[i] ?? null, {
          x1: String(x),
          x2: String(x),
          y1: String(stackTop),
          y2: String(stackBottom),
          "stroke-width": String(Math.max(1, 1.25 * scale)),
        });
      });

      for (let r = 0; r < ROWS; r++) {
        const cy = rowCenterY(geom, r);
        setAttrs(sleeperRefs.current[r] ?? null, {
          x: String(geom.sleeperX1),
          y: String(cy - geom.sleeperH / 2),
          width: String(geom.sleeperX2 - geom.sleeperX1),
          height: String(geom.sleeperH),
          rx: String(Math.max(1, 2 * scale)),
        });
        setAttrs(tickRefs.current[r] ?? null, {
          d: tickPath(geom, cy, scale),
          "stroke-width": String(Math.max(0.75, 1.1 * scale)),
        });
      }
      setAttrs(gapRef.current, {
        width: String(geom.sleeperX2 - geom.sleeperX1),
        height: String(geom.sleeperH),
        rx: String(Math.max(1, 2 * scale)),
        "stroke-width": String(Math.max(0.75, 1 * scale)),
      });
      setAttrs(movingRef.current, {
        width: String(geom.sleeperX2 - geom.sleeperX1),
        height: String(geom.sleeperH),
        rx: String(Math.max(1, 2 * scale)),
      });
      setAttrs(carriageRef.current, {
        width: String(Math.max(4, 8 * scale)),
        height: String(Math.max(4, 8 * scale)),
        rx: String(Math.max(0.5, 1.5 * scale)),
      });
      setAttrs(hookRef.current, { r: String(Math.max(1, 2.4 * scale)) });
      setAttrs(armRef.current, { "stroke-width": String(Math.max(0.75, 1.5 * scale)) });
      setAttrs(carriageRef.current, { "stroke-width": String(Math.max(0.75, 1.5 * scale)) });
    };

    function tickPath(g: Geometry, cy: number, scale: number): string {
      const len = Math.max(3, 5 * scale);
      const a = `M ${g.railX1} ${cy - len / 2} L ${g.railX1} ${cy + len / 2}`;
      const b = `M ${g.railX2} ${cy - len / 2} L ${g.railX2} ${cy + len / 2}`;
      return `${a} ${b}`;
    }

    const render = (elapsedMs: number) => {
      const g = geom;
      const cycleIndex = Math.floor(elapsedMs / CYCLE_MS);
      const currentRow = ((cycleIndex % ROWS) + ROWS) % ROWS;
      const localT = elapsedMs - cycleIndex * CYCLE_MS;

      // -- carriage vertical position: rides on the active row until the
      // final TRAVEL_MS of dwell, then eases on to the next row so it is
      // already in place when that row's own lift begins.
      let carriageRow = currentRow;
      let carriageFrac = 0;
      if (localT >= DWELL_START + DWELL_MS - TRAVEL_MS) {
        carriageFrac = easeInOutCubic((localT - (DWELL_START + DWELL_MS - TRAVEL_MS)) / TRAVEL_MS);
      }
      const nextRow = (currentRow + 1) % ROWS;
      const carriageY = lerp(rowCenterY(g, carriageRow), rowCenterY(g, nextRow), carriageFrac);

      // -- static rows: continuous wear-derived fill + tick opacity --
      for (let r = 0; r < ROWS; r++) {
        const isActiveMoving = r === currentRow && localT < DWELL_START;
        const wear = rowWear(r, elapsedMs);
        const rect = sleeperRefs.current[r];
        if (rect) {
          rect.setAttribute("fill", wearColor(wear));
          rect.setAttribute("opacity", isActiveMoving ? "0" : "1");
          rect.removeAttribute("transform");
        }
        const tick = tickRefs.current[r];
        if (tick) {
          const op = clamp01((0.85 - wear) / 0.85) * 0.6;
          tick.setAttribute("opacity", String(op));
        }
      }

      // -- moving sleeper + gap outline + crane arm, only meaningful while
      // the active row is mid lift/drop --
      const restCx = (g.sleeperX1 + g.sleeperX2) / 2;
      const restCy = rowCenterY(g, currentRow);
      const sideReach = g.w * 0.22;

      let dx = 0;
      let dy = 0;
      let rot = 0;
      let opacity = 0;
      let gapOpacity = 0;
      let fill = wearColor(1);
      let hookX = restCx;
      let hookY = restCy;
      let armLen = 1;

      if (localT < LIFT_MS) {
        opacity = 1;
        fill = wearColor(rowWear(currentRow, elapsedMs));
        if (localT < RISE_MS) {
          const u = easeOutCubic(localT / RISE_MS);
          dy = -g.rowSize * 0.9 * u;
          gapOpacity = 0.35 * clamp01((localT - RISE_MS * 0.3) / (RISE_MS * 0.7));
        } else {
          const v = easeInOutCubic((localT - RISE_MS) / SWING_MS);
          dy = -g.rowSize * 0.9 + g.rowSize * 0.3 * v;
          dx = sideReach * v;
          rot = 12 * v;
          opacity = 1 - 0.85 * v;
          gapOpacity = 0.35;
        }
        hookX = restCx + dx;
        hookY = restCy + dy;
      } else if (localT < DWELL_START) {
        const local2 = localT - DROP_START;
        opacity = 1;
        if (local2 < ENTER_MS) {
          const p = easeOutCubic(local2 / ENTER_MS);
          dx = -sideReach * (1 - p);
          dy = -g.rowSize * 0.5 * (1 - p);
          rot = -8 * (1 - p);
          opacity = clamp01(local2 / (ENTER_MS * 0.25));
          const wearAtDropStart = rowWear(currentRow, startOfCycle(cycleIndex) + DROP_START);
          fill = wearColor(lerp(wearAtDropStart, 0, p));
          gapOpacity = 0.35 * (1 - p);
        } else {
          const q = easeOutCubic((local2 - ENTER_MS) / SETTLE_MS);
          dy = g.rowSize * 0.1 * Math.sin(Math.PI * q);
          rot = 3 * Math.sin(Math.PI * q) * (1 - q);
          fill = wearColor(0);
          gapOpacity = 0;
        }
        hookX = restCx + dx;
        hookY = restCy + dy;
      } else {
        // dwell: settled sleeper is the ordinary static row again; the arm
        // rests directly on it until the travel window pulls it away.
        opacity = 0;
        gapOpacity = 0;
        const dwellLocal = localT - DWELL_START;
        if (dwellLocal >= DWELL_MS - TRAVEL_MS) {
          const t = easeInOutCubic((dwellLocal - (DWELL_MS - TRAVEL_MS)) / TRAVEL_MS);
          hookX = lerp(restCx, g.gantryX, t);
          hookY = lerp(restCy - g.rowSize * 0.5, carriageY, t);
          armLen = 1 - t;
        } else {
          hookX = restCx;
          hookY = restCy - g.rowSize * 0.5;
        }
      }

      if (movingRef.current) {
        movingRef.current.setAttribute("fill", fill);
        movingRef.current.setAttribute("opacity", String(opacity));
        movingRef.current.setAttribute(
          "transform",
          `translate(${dx.toFixed(2)} ${dy.toFixed(2)}) rotate(${rot.toFixed(2)} ${restCx.toFixed(2)} ${restCy.toFixed(2)})`
        );
        movingRef.current.setAttribute("x", String(g.sleeperX1));
        movingRef.current.setAttribute("y", String(restCy - g.sleeperH / 2));
      }
      if (gapRef.current) {
        gapRef.current.setAttribute("opacity", String(gapOpacity));
        gapRef.current.setAttribute("x", String(g.sleeperX1));
        gapRef.current.setAttribute("y", String(restCy - g.sleeperH / 2));
      }

      setAttrs(carriageRef.current, {
        x: String(g.gantryX - Math.max(4, 8 * g.scale) / 2),
        y: String(carriageY - Math.max(4, 8 * g.scale) / 2),
      });
      const armOpacity = Math.max(0, Math.min(1, armLen));
      setAttrs(armRef.current, {
        x1: String(g.gantryX),
        y1: String(carriageY),
        x2: String(hookX.toFixed(2)),
        y2: String(hookY.toFixed(2)),
        opacity: String(armOpacity),
      });
      setAttrs(hookRef.current, {
        cx: String(hookX.toFixed(2)),
        cy: String(hookY.toFixed(2)),
        opacity: String(armOpacity),
      });
    };

    function startOfCycle(cycleIndex: number): number {
      return cycleIndex * CYCLE_MS;
    }

    const loop = (now: number) => {
      raf = 0;
      if (!visible) return;
      if (frozen && !pausedRef.current) {
        frozen = false;
        startTime = now - frozenElapsed;
      }
      if (!frozen) {
        const rawElapsed = now - startTime;
        const cycleIndex = Math.floor(rawElapsed / CYCLE_MS);
        const localT = rawElapsed - cycleIndex * CYCLE_MS;
        if (pausedRef.current && localT >= DWELL_START) {
          frozen = true;
          frozenElapsed = rawElapsed;
        }
      }
      const elapsed = frozen ? frozenElapsed : now - startTime;
      render(elapsed);
      raf = requestAnimationFrame(loop);
    };

    const wake = () => {
      if (raf === 0 && !reduced && visible) raf = requestAnimationFrame(loop);
    };

    layout();
    if (reduced) {
      render(STATIC_ELAPSED);
    } else {
      wake();
    }

    const ro = new ResizeObserver(() => {
      layout();
      render(reduced ? STATIC_ELAPSED : frozen ? frozenElapsed : performance.now() - startTime);
    });
    ro.observe(panel);

    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible) wake();
      else if (raf) {
        cancelAnimationFrame(raf);
        raf = 0;
      }
    });
    io.observe(panel);

    const onReducedChange = () => {
      reduced = mq.matches;
      if (reduced) {
        cancelAnimationFrame(raf);
        raf = 0;
        render(STATIC_ELAPSED);
      } else {
        startTime = performance.now();
        frozen = false;
        wake();
      }
    };
    mq.addEventListener("change", onReducedChange);

    const onVisibility = () => {
      if (document.visibilityState === "visible") wake();
      else if (raf) {
        cancelAnimationFrame(raf);
        raf = 0;
      }
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      cancelAnimationFrame(raf);
      raf = 0;
      ro.disconnect();
      io.disconnect();
      mq.removeEventListener("change", onReducedChange);
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, []);

  return (
    <div
      className={`ns-sleeper-renewal-relay flex w-full max-w-sm flex-col gap-3 rounded-[14px] border border-border bg-background p-4 ${className}`}
      style={style}
      data-reduced-motion-freeze="mid-lift"
    >
      <div className="min-w-0">
        <h3 className="text-balance font-sans text-sm font-medium text-foreground">{title}</h3>
        <p className="mt-1 text-pretty font-mono text-xs leading-relaxed text-ns-muted">{description}</p>
      </div>
      <div
        ref={panelRef}
        role="img"
        aria-label="Row renewal in progress"
        className="relative h-56 w-full shrink-0 overflow-hidden rounded-md border border-border bg-background"
      >
        <svg ref={svgRef} aria-hidden="true" className="absolute inset-0 h-full w-full">
          <line ref={gantryRef} stroke="var(--foreground)" strokeOpacity={0.28} />
          <line ref={(el) => { railRefs.current[0] = el; }} stroke="var(--foreground)" strokeOpacity={0.4} />
          <line ref={(el) => { railRefs.current[1] = el; }} stroke="var(--foreground)" strokeOpacity={0.4} />
          {Array.from({ length: ROWS }).map((_, i) => (
            <rect key={i} ref={(el) => { sleeperRefs.current[i] = el; }} fill="var(--foreground)" />
          ))}
          {Array.from({ length: ROWS }).map((_, i) => (
            <path
              key={i}
              ref={(el) => { tickRefs.current[i] = el; }}
              stroke="var(--foreground)"
              strokeLinecap="round"
              fill="none"
            />
          ))}
          <rect
            ref={gapRef}
            fill="none"
            stroke="var(--foreground)"
            strokeDasharray="3 3"
            opacity={0}
          />
          <rect ref={movingRef} opacity={0} />
          <line ref={armRef} stroke="var(--foreground)" strokeLinecap="round" opacity={0} />
          <circle ref={hookRef} fill="var(--foreground)" opacity={0} />
          <rect ref={carriageRef} fill="none" stroke="var(--foreground)" strokeOpacity={0.7} />
        </svg>
      </div>
    </div>
  );
}

SleeperRenewalRelay.displayName = "SleeperRenewalRelay";

export default SleeperRenewalRelay;

"use client";

import { useEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// CatenarySplit — a two-way allocation slider built as a slack wire between
// two labeled anchors. The bead's position along the wire sets the RATIO
// (left share vs right share); the wire's SAG encodes a second, independent
// variable — the unallocated remainder — so a taut straight wire reads as
// "fully committed" and a deep droop reads as "budget still on the table".
// Mechanism: an SVG quadratic bezier whose control-point depth is
// proportional to the unallocated fraction, rebuilt every frame; the bead is
// positioned by genuine arc-length parameterization (sampled table, not raw
// parametric t) so it slides evenly along whatever shape the wire currently
// has. A wheel/pinch on the wire, or dragging the paired "Total allocated"
// track, winches the total; easing toward a taut wire plays two decaying
// tension oscillations when it lands fully committed. Direct-DOM rAF hot
// path — React state only holds the committed integer values, per-frame
// geometry lives in refs/locals and is written straight to the DOM.
// ---------------------------------------------------------------------------

const VB_W = 400; // svg viewBox width (units, not px — scaled to the box)
const VB_H = 120;
const ANCHOR_X = 30; // inset of each anchor from the viewBox edges
const WIRE_Y = 46; // baseline y both anchors sit on
const MAX_DEPTH = 44; // control-point sag at fully unallocated (total = 0)
const SAMPLES = 48; // arc-length table resolution

const RATIO_K = 220; // keyboard/glide spring, s^-2 (critically-ish damped)
const RATIO_ZETA = 0.9;
const DEPTH_K = 130; // sag spring when NOT snapping taut
const DEPTH_ZETA = 1.0;
const TAUT_MS = 900; // scripted tension-wobble window when total hits 100
const TAUT_DECAY = 3.4;
const TAUT_CYCLES = 2; // exactly two damped oscillations
const SETTLE_MS = 1200; // forced-settle deadline for any pending motion

function clamp(v: number, lo: number, hi: number) {
  return Math.min(hi, Math.max(lo, v));
}

interface Pt {
  x: number;
  y: number;
}

function quadPoint(p0: Pt, p1: Pt, p2: Pt, t: number): Pt {
  const mt = 1 - t;
  return {
    x: mt * mt * p0.x + 2 * mt * t * p1.x + t * t * p2.x,
    y: mt * mt * p0.y + 2 * mt * t * p1.y + t * t * p2.y,
  };
}

interface ArcTable {
  xs: number[];
  ys: number[];
  lens: number[];
  total: number;
}

// Samples the current quadratic bezier into an arc-length lookup table. Since
// both anchors sit at the same y and the control point's x is always their
// midpoint, x(t) is monotonic — the table doubles as an x -> arc-length map.
function buildTable(p0: Pt, p1: Pt, p2: Pt): ArcTable {
  const xs: number[] = [p0.x];
  const ys: number[] = [p0.y];
  const lens: number[] = [0];
  let prevX = p0.x;
  let prevY = p0.y;
  let acc = 0;
  for (let i = 1; i <= SAMPLES; i++) {
    const { x, y } = quadPoint(p0, p1, p2, i / SAMPLES);
    acc += Math.hypot(x - prevX, y - prevY);
    xs.push(x);
    ys.push(y);
    lens.push(acc);
    prevX = x;
    prevY = y;
  }
  return { xs, ys, lens, total: Math.max(1e-6, acc) };
}

// Point at a given arc-length fraction (0..1) — genuine arc-length walk, not
// a lerp on parametric t.
function pointAtFraction(table: ArcTable, f: number): Pt {
  const target = clamp(f, 0, 1) * table.total;
  const { xs, ys, lens } = table;
  for (let i = 1; i < lens.length; i++) {
    if (lens[i] >= target) {
      const span = lens[i] - lens[i - 1];
      const u = span > 1e-6 ? (target - lens[i - 1]) / span : 0;
      return {
        x: xs[i - 1] + (xs[i] - xs[i - 1]) * u,
        y: ys[i - 1] + (ys[i] - ys[i - 1]) * u,
      };
    }
  }
  const last = lens.length - 1;
  return { x: xs[last], y: ys[last] };
}

// Inverse: arc-length fraction nearest a given x (binary search — x is
// monotonic by construction). Used to map a pointer position on the wire
// back to a ratio.
function fractionForX(table: ArcTable, x: number): number {
  const { xs, lens } = table;
  const hi0 = xs.length - 1;
  if (x <= xs[0]) return 0;
  if (x >= xs[hi0]) return 1;
  let lo = 0;
  let hi = hi0;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (xs[mid] < x) lo = mid;
    else hi = mid;
  }
  const span = xs[hi] - xs[lo];
  const u = span > 1e-6 ? (x - xs[lo]) / span : 0;
  const len = lens[lo] + (lens[hi] - lens[lo]) * u;
  return clamp(len / table.total, 0, 1);
}

export interface CatenarySplitProps {
  /** label for the left anchor, e.g. "Compute" */
  leftLabel?: string;
  /** label for the right anchor, e.g. "Storage" */
  rightLabel?: string;
  /** controlled split ratio, 0-100 (% of the committed total given to left) */
  ratio?: number;
  /** uncontrolled initial split ratio */
  defaultRatio?: number;
  /** controlled total committed, 0-100 (% of budget not left on the table) */
  total?: number;
  /** uncontrolled initial total committed */
  defaultTotal?: number;
  /** called with the new ratio on every drag */
  onRatioChange?: (v: number) => void;
  /** called with the new total on every drag */
  onTotalChange?: (v: number) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function CatenarySplit({
  leftLabel = "Compute",
  rightLabel = "Storage",
  ratio,
  defaultRatio = 60,
  total,
  defaultTotal = 65,
  onRatioChange,
  onTotalChange,
  className = "",
}: CatenarySplitProps) {
  const isRatioControlled = ratio !== undefined;
  const [ratioInternal, setRatioInternal] = useState(() =>
    clamp(defaultRatio, 0, 100)
  );
  const ratioValue = isRatioControlled ? (ratio as number) : ratioInternal;
  const ratioRef = useRef(ratioValue);
  ratioRef.current = ratioValue;

  const isTotalControlled = total !== undefined;
  const [totalInternal, setTotalInternal] = useState(() =>
    clamp(defaultTotal, 0, 100)
  );
  const totalValue = isTotalControlled ? (total as number) : totalInternal;
  const totalRef = useRef(totalValue);
  totalRef.current = totalValue;

  const [ratioActive, setRatioActive] = useState(false); // focus or drag
  const [totalActive, setTotalActive] = useState(false);

  const commitRatioRef = useRef<(v: number) => void>(() => {});
  commitRatioRef.current = (v: number) => {
    const q = clamp(Math.round(v), 0, 100);
    if (q === ratioRef.current) return;
    if (!isRatioControlled) setRatioInternal(q);
    onRatioChange?.(q);
  };
  const commitTotalRef = useRef<(v: number) => void>(() => {});
  commitTotalRef.current = (v: number) => {
    const q = clamp(Math.round(v), 0, 100);
    if (q === totalRef.current) return;
    if (!isTotalControlled) setTotalInternal(q);
    onTotalChange?.(q);
  };

  const wireBoxRef = useRef<HTMLDivElement>(null);
  const pathRef = useRef<SVGPathElement>(null);
  const beadRef = useRef<HTMLDivElement>(null);
  const leftPctRef = useRef<HTMLSpanElement>(null);
  const rightPctRef = useRef<HTMLSpanElement>(null);
  const totalTrackRef = useRef<HTMLDivElement>(null);
  const totalFillRef = useRef<HTMLDivElement>(null);
  const totalHandleRef = useRef<HTMLDivElement>(null);
  const totalCaptionRef = useRef<HTMLSpanElement>(null);

  const engineRef = useRef<{
    beadDragStart: (clientX: number) => void;
    beadDragMove: (clientX: number) => void;
    beadDragEnd: () => void;
    totalDragStart: (clientX: number) => void;
    totalDragMove: (clientX: number) => void;
    totalDragEnd: () => void;
    wheelTotal: (deltaPercent: number) => void;
    syncRatio: (v: number) => void;
    syncTotal: (v: number) => void;
  } | null>(null);

  useEffect(() => {
    const wireBox = wireBoxRef.current;
    const path = pathRef.current;
    const bead = beadRef.current;
    const leftPct = leftPctRef.current;
    const rightPct = rightPctRef.current;
    const totalTrack = totalTrackRef.current;
    const totalFill = totalFillRef.current;
    const totalHandle = totalHandleRef.current;
    const totalCaption = totalCaptionRef.current;
    if (
      !wireBox ||
      !path ||
      !bead ||
      !leftPct ||
      !rightPct ||
      !totalTrack ||
      !totalFill ||
      !totalHandle ||
      !totalCaption
    )
      return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    let raf = 0;
    let last = 0;
    let visible = true;
    let scaleX = 1;
    let scaleY = 1;
    let sized = false;

    // -- hot-path state ------------------------------------------------------
    let aRatio = ratioRef.current; // animated ratio (0-100), what the bead reads
    let rv = 0; // ratio velocity
    let ratioTarget = ratioRef.current;
    let draggingRatio = false;
    let committedRatio = ratioRef.current; // dedupes onRatioChange during a drag

    let aDepth = MAX_DEPTH * (1 - totalRef.current / 100);
    let dv = 0; // depth velocity
    let depthTarget = aDepth;
    let tautAt = -1; // performance.now() when a taut-snap wobble started, -1 = none
    let tautFrom = 0;
    let draggingTotal = false;
    // hot-path mirror of the committed total, for immediate render feedback —
    // kept separate from totalRef (the React-state mirror) so drag/wheel
    // handlers never race the commit function's own dedup check
    let liveTotal = totalRef.current;

    let deadline = 0;

    const anchors = () => ({
      p0: { x: ANCHOR_X, y: WIRE_Y },
      p2: { x: VB_W - ANCHOR_X, y: WIRE_Y },
    });

    const tableFor = (depth: number) => {
      const { p0, p2 } = anchors();
      const p1 = { x: (p0.x + p2.x) / 2, y: WIRE_Y + depth };
      return { table: buildTable(p0, p1, p2), p0, p1, p2 };
    };

    const render = () => {
      const { table, p0, p1, p2 } = tableFor(aDepth);
      path.setAttribute(
        "d",
        `M ${p0.x} ${p0.y} Q ${p1.x} ${p1.y} ${p2.x} ${p2.y}`
      );
      const bp = pointAtFraction(table, aRatio / 100);
      bead.style.transform = `translate3d(${(bp.x * scaleX).toFixed(2)}px, ${(
        bp.y * scaleY
      ).toFixed(2)}px, 0) translate(-50%, -50%)`;

      const leftRounded = Math.round(aRatio);
      leftPct.textContent = `${leftRounded}%`;
      rightPct.textContent = `${100 - leftRounded}%`;

      const totalRounded = clamp(Math.round(liveTotal), 0, 100);
      totalCaption.textContent = `${totalRounded}%`;
      totalFill.style.width = `${totalRounded}%`;
      totalHandle.style.left = `${totalRounded}%`;
    };

    const resize = () => {
      const rect = wireBox.getBoundingClientRect();
      if (rect.width < 40 || rect.height < 20) {
        sized = false;
        return;
      }
      scaleX = rect.width / VB_W;
      scaleY = rect.height / VB_H;
      sized = true;
      render();
    };
    resize();

    const loop = (now: number) => {
      raf = 0;
      const dt = last ? Math.min(0.033, (now - last) / 1000) : 1 / 60;
      last = now;
      let active = false;

      // ratio: pinned to pointer while dragging, otherwise a plain glide
      if (!draggingRatio) {
        const c = 2 * RATIO_ZETA * Math.sqrt(RATIO_K);
        rv += (-RATIO_K * (aRatio - ratioTarget) - c * rv) * dt;
        aRatio += rv * dt;
        if (Math.abs(aRatio - ratioTarget) < 0.05 && Math.abs(rv) < 0.5) {
          aRatio = ratioTarget;
          rv = 0;
        } else active = true;
      }

      // depth: either the scripted taut-snap wobble, or a plain damped glide
      if (tautAt >= 0) {
        const p = clamp((now - tautAt) / TAUT_MS, 0, 1);
        if (p >= 1) {
          aDepth = 0;
          dv = 0;
          tautAt = -1;
        } else {
          aDepth =
            tautFrom *
            Math.exp(-TAUT_DECAY * p) *
            Math.cos(2 * Math.PI * TAUT_CYCLES * p);
          active = true;
        }
      } else {
        // eases toward depthTarget on EVERY total-changing path, including a
        // live drag on the paired track — winching reads as mechanical drag,
        // never a jump cut, so the spring keeps running while draggingTotal
        // is true instead of freezing until pointer-up
        const c = 2 * DEPTH_ZETA * Math.sqrt(DEPTH_K);
        dv += (-DEPTH_K * (aDepth - depthTarget) - c * dv) * dt;
        aDepth += dv * dt;
        if (Math.abs(aDepth - depthTarget) < 0.05 && Math.abs(dv) < 0.5) {
          aDepth = depthTarget;
          dv = 0;
        } else active = true;
      }

      if (active && now > deadline) {
        aRatio = ratioTarget;
        rv = 0;
        if (tautAt < 0) {
          aDepth = depthTarget;
          dv = 0;
        }
        active = false;
      }

      if (sized) render();
      if (active && visible && !document.hidden) {
        raf = requestAnimationFrame(loop);
      }
    };

    const wake = () => {
      if (!raf && sized) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const armDeadline = () => {
      deadline = performance.now() + SETTLE_MS;
    };

    const setRatioTarget = (v: number) => {
      ratioTarget = v;
      if (reduced) {
        aRatio = v;
        rv = 0;
        if (sized) render();
        return;
      }
      armDeadline();
      wake();
    };

    // Every path that changes the total (drag on the paired track, wheel/
    // pinch on the wire, keyboard) routes through here so the sag always
    // eases rather than teleporting — including while actively dragging the
    // total track, so "winching" reads as mechanical, not instant. That is
    // also what lets the taut-snap wobble fire on drag: the transition is
    // detected the moment the eased depth's TARGET reaches zero, while the
    // animated depth itself is still mid-glide and has real energy to decay.
    const setTotalTarget = (v: number) => {
      const wasFull = depthTarget <= 0.01;
      depthTarget = MAX_DEPTH * (1 - v / 100);
      const nowFull = depthTarget <= 0.01;
      if (reduced) {
        aDepth = depthTarget;
        dv = 0;
        tautAt = -1;
        if (sized) render();
        return;
      }
      if (nowFull && !wasFull && tautAt < 0) {
        // landing on a fully-committed total plucks the wire taut — two
        // decaying tension oscillations from wherever the sag currently is
        tautFrom = aDepth;
        tautAt = performance.now();
      }
      armDeadline();
      wake();
    };

    // -- bead drag: arc-length projection of the pointer onto the CURRENT
    // curve shape, so the bead genuinely rides whatever sag is on screen --
    const beadDragStart = (clientX: number) => {
      if (!sized) return;
      draggingRatio = true;
      beadDragMove(clientX);
    };
    const beadDragMove = (clientX: number) => {
      if (!sized || !draggingRatio) return;
      const rect = wireBox.getBoundingClientRect();
      const x = (clientX - rect.left) / scaleX;
      const { table } = tableFor(aDepth);
      const f = fractionForX(table, x);
      aRatio = f * 100;
      rv = 0;
      const q = clamp(Math.round(aRatio), 0, 100);
      ratioTarget = q;
      if (q !== committedRatio) {
        committedRatio = q;
        commitRatioRef.current(q);
      }
      armDeadline();
      if (sized) render();
    };
    const beadDragEnd = () => {
      if (!draggingRatio) return;
      draggingRatio = false;
      ratioTarget = clamp(Math.round(aRatio), 0, 100);
      aRatio = ratioTarget;
      armDeadline();
      wake();
    };

    // -- total drag: linear along the paired track ---------------------------
    const totalDragStart = (clientX: number) => {
      if (!sized) return;
      draggingTotal = true;
      totalDragMove(clientX);
    };
    const totalDragMove = (clientX: number) => {
      if (!draggingTotal) return;
      const rect = totalTrack.getBoundingClientRect();
      const f = rect.width > 0 ? (clientX - rect.left) / rect.width : 0;
      const v = clamp(Math.round(f * 100), 0, 100);
      liveTotal = v; // reflected immediately for the caption/fill/handle
      commitTotalRef.current(v);
      setTotalTarget(v); // eases like every other total-changing path
    };
    const totalDragEnd = () => {
      if (!draggingTotal) return;
      draggingTotal = false;
      setTotalTarget(liveTotal); // idempotent — already the drag target
    };

    const wheelTotal = (deltaPercent: number) => {
      const next = clamp(Math.round(liveTotal + deltaPercent), 0, 100);
      if (next === liveTotal) return;
      liveTotal = next;
      commitTotalRef.current(next);
      setTotalTarget(next);
    };

    // external/keyboard commits: glide to the new value unless that axis is
    // mid-drag, in which case the pointer already owns it this frame
    const syncRatio = (v: number) => {
      if (draggingRatio) return;
      committedRatio = v;
      setRatioTarget(v);
    };
    const syncTotal = (v: number) => {
      if (draggingTotal) return;
      liveTotal = v;
      setTotalTarget(v);
    };

    engineRef.current = {
      beadDragStart,
      beadDragMove,
      beadDragEnd,
      totalDragStart,
      totalDragMove,
      totalDragEnd,
      wheelTotal,
      syncRatio,
      syncTotal,
    };

    const ro = new ResizeObserver(resize);
    ro.observe(wireBox);
    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible) wake();
    });
    io.observe(wireBox);
    const onVis = () => {
      if (!document.hidden) wake();
    };
    document.addEventListener("visibilitychange", onVis);

    // React registers wheel listeners as passive by default, so a synthetic
    // onWheel prop can never call preventDefault without throwing — bind a
    // real non-passive listener instead so scroll/pinch on the wire can
    // actually consume the gesture instead of also scrolling the page.
    const onWheel = (e: WheelEvent) => {
      e.preventDefault();
      // trackpad pinch reports as a wheel event with ctrlKey set
      const scale = e.ctrlKey ? 0.6 : 0.15;
      engineRef.current?.wheelTotal(-e.deltaY * scale);
    };
    wireBox.addEventListener("wheel", onWheel, { passive: false });

    // keep the animated targets aligned with external/committed value changes
    setRatioTarget(ratioRef.current);
    setTotalTarget(totalRef.current);

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      io.disconnect();
      document.removeEventListener("visibilitychange", onVis);
      wireBox.removeEventListener("wheel", onWheel);
      engineRef.current = null;
    };
    // mount-only: geometry constants are module-level, external value syncs
    // are handled by the effects below via engineRef.syncRatio/syncTotal
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // external/keyboard ratio and total changes glide toward the new value
  // (a live drag on that same axis already owns the frame and is skipped)
  useEffect(() => {
    engineRef.current?.syncRatio(ratioValue);
  }, [ratioValue]);
  useEffect(() => {
    engineRef.current?.syncTotal(totalValue);
  }, [totalValue]);

  // -- keyboard: bead ("Split") ----------------------------------------------
  const onBeadKeyDown = (e: React.KeyboardEvent) => {
    const v = ratioRef.current;
    let next: number | null = null;
    switch (e.key) {
      case "ArrowRight":
      case "ArrowUp":
        next = v + 1;
        break;
      case "ArrowLeft":
      case "ArrowDown":
        next = v - 1;
        break;
      case "PageUp":
        next = v + 10;
        break;
      case "PageDown":
        next = v - 10;
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = 100;
        break;
      default:
        return;
    }
    e.preventDefault();
    next = clamp(next, 0, 100);
    if (next !== v) commitRatioRef.current(next);
  };

  // -- keyboard: "Total allocated" -------------------------------------------
  const onTotalKeyDown = (e: React.KeyboardEvent) => {
    const v = totalRef.current;
    let next: number | null = null;
    switch (e.key) {
      case "ArrowRight":
      case "ArrowUp":
        next = v + 1;
        break;
      case "ArrowLeft":
      case "ArrowDown":
        next = v - 1;
        break;
      case "PageUp":
        next = v + 10;
        break;
      case "PageDown":
        next = v - 10;
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = 100;
        break;
      default:
        return;
    }
    e.preventDefault();
    next = clamp(next, 0, 100);
    if (next !== v) commitTotalRef.current(next);
  };

  const leftPctNow = Math.round(ratioValue);
  const rightPctNow = 100 - leftPctNow;
  const totalNow = Math.round(totalValue);
  const beadValueText = `${leftPctNow}% ${leftLabel.toLowerCase()}, ${rightPctNow}% ${rightLabel.toLowerCase()}`;
  const totalValueText = `${totalNow}% of budget allocated`;

  return (
    <div className={`w-full select-none ${className}`}>
      <div
        ref={wireBoxRef}
        className="group relative h-28 w-full touch-none"
        onPointerDown={(e) => {
          e.preventDefault();
          e.currentTarget.setPointerCapture(e.pointerId);
          beadRef.current?.focus({ preventScroll: true });
          engineRef.current?.beadDragStart(e.clientX);
          setRatioActive(true);
        }}
        onPointerMove={(e) => engineRef.current?.beadDragMove(e.clientX)}
        onPointerUp={() => {
          engineRef.current?.beadDragEnd();
          setRatioActive(false);
        }}
        onPointerCancel={() => {
          engineRef.current?.beadDragEnd();
          setRatioActive(false);
        }}
      >
        <svg
          aria-hidden
          viewBox={`0 0 ${VB_W} ${VB_H}`}
          preserveAspectRatio="none"
          className="absolute inset-0 h-full w-full cursor-ew-resize"
        >
          <path
            ref={pathRef}
            fill="none"
            stroke="var(--ns-muted)"
            strokeWidth={1.5}
            strokeLinecap="round"
          />
          <circle cx={ANCHOR_X} cy={WIRE_Y} r={3} fill="var(--border)" />
          <circle
            cx={VB_W - ANCHOR_X}
            cy={WIRE_Y}
            r={3}
            fill="var(--border)"
          />
        </svg>

        <div
          ref={beadRef}
          role="slider"
          tabIndex={0}
          aria-label="Split"
          aria-orientation="horizontal"
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={leftPctNow}
          aria-valuetext={beadValueText}
          onKeyDown={onBeadKeyDown}
          onFocus={() => setRatioActive(true)}
          onBlur={() => setRatioActive(false)}
          className="absolute left-0 top-0 h-7 w-7 cursor-grab rounded-full outline-none will-change-transform active:cursor-grabbing focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background"
        >
          <span
            aria-hidden
            data-active={ratioActive}
            className="absolute inset-[3px] rounded-full border border-border bg-background transition-colors duration-150 group-hover:border-foreground/40 data-[active=true]:border-ns-accent"
          />
          <span
            aria-hidden
            className="absolute left-1/2 top-1/2 h-2 w-2 -translate-x-1/2 -translate-y-1/2 rounded-full bg-foreground"
          />
        </div>
      </div>

      <div className="flex items-start justify-between px-0.5 pt-1 font-mono">
        <div className="flex flex-col gap-0.5">
          <span className="text-xs text-ns-muted">{leftLabel}</span>
          <span
            ref={leftPctRef}
            className="tabular-nums text-sm text-foreground"
          >
            {leftPctNow}%
          </span>
        </div>
        <div className="flex flex-col items-end gap-0.5">
          <span className="text-xs text-ns-muted">{rightLabel}</span>
          <span
            ref={rightPctRef}
            className="tabular-nums text-sm text-foreground"
          >
            {rightPctNow}%
          </span>
        </div>
      </div>

      <div className="mt-5">
        <div className="flex items-center justify-between pb-1.5">
          <span className="font-mono text-xs text-ns-muted">
            Total allocated
          </span>
          <span
            ref={totalCaptionRef}
            className="font-mono text-xs tabular-nums text-ns-muted"
          >
            {totalNow}%
          </span>
        </div>
        <div
          ref={totalTrackRef}
          role="slider"
          tabIndex={0}
          aria-label="Total allocated"
          aria-orientation="horizontal"
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={totalNow}
          aria-valuetext={totalValueText}
          onKeyDown={onTotalKeyDown}
          onFocus={() => setTotalActive(true)}
          onBlur={() => setTotalActive(false)}
          onPointerDown={(e) => {
            e.preventDefault();
            e.currentTarget.setPointerCapture(e.pointerId);
            engineRef.current?.totalDragStart(e.clientX);
            setTotalActive(true);
          }}
          onPointerMove={(e) => engineRef.current?.totalDragMove(e.clientX)}
          onPointerUp={() => {
            engineRef.current?.totalDragEnd();
            setTotalActive(false);
          }}
          onPointerCancel={() => {
            engineRef.current?.totalDragEnd();
            setTotalActive(false);
          }}
          className="relative h-4 w-full cursor-ew-resize touch-none outline-none focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background"
        >
          <span className="absolute left-0 top-1/2 h-1 w-full -translate-y-1/2 rounded-full bg-border" />
          <div
            ref={totalFillRef}
            className="absolute left-0 top-1/2 h-1 -translate-y-1/2 rounded-full bg-foreground/70"
            style={{ width: `${totalNow}%` }}
          />
          <div
            ref={totalHandleRef}
            data-active={totalActive}
            style={{ left: `${totalNow}%` }}
            className="absolute top-1/2 h-3 w-3 -translate-x-1/2 -translate-y-1/2 rounded-full border border-border bg-background transition-colors duration-150 data-[active=true]:border-ns-accent"
          />
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// LoupeSlider — single-value slider read through a circular magnifying loupe
// riding the thumb. The tick scale is drawn twice from cached layers: a base
// pass pre-blurred (ctx.filter blur(1.5px), rebuilt only on size/theme change)
// at 55% alpha, and a sharp 1.8x-magnified pass inside a 44px circular clip
// centered on the loupe — lens focus IS the readout. The loupe springs after
// the thumb (k=180, zeta=0.75, slight optical lag); dragging past the bounds
// rubber-bands at x0.3 (capped 24px) and release springs home (k=260,
// zeta=0.7) while magnification wobbles 1.8 -> 2.0 -> 1.8 over 350ms.
// Direct-DOM rAF that sleeps at a velocity epsilon, pauses offscreen, and
// carries a 1s forced-settle deadline. All canvas ink is derived from CSS
// tokens at mount and re-derived live on documentElement class changes.
// ---------------------------------------------------------------------------

const LENS_R = 22; // px lens radius (44px loupe)
const PAD = 28; // track inset so the lens never clips at the ends
const MAG_BASE = 1.8;
const MAG_PEAK = 2.0;
const WOBBLE_MS = 350;
const LOUPE_K = 180; // loupe chase spring, s^-2
const LOUPE_ZETA = 0.75;
const HOME_K = 260; // rubber-band return / glide spring, s^-2
const HOME_ZETA = 0.7;
const RUBBER = 0.3; // overshoot gain past the bounds
const RUBBER_MAX = 24; // px overshoot cap
const SETTLE_MS = 1000; // forced-settle deadline

type Vec3 = readonly [number, number, number];

function parseColor(raw: string): Vec3 | null {
  const s = raw.trim();
  if (s.startsWith("#")) {
    const hex = s.slice(1);
    if (hex.length === 3) {
      const r = parseInt(hex.slice(0, 1) + hex.slice(0, 1), 16);
      const g = parseInt(hex.slice(1, 2) + hex.slice(1, 2), 16);
      const b = parseInt(hex.slice(2, 3) + hex.slice(2, 3), 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    if (hex.length >= 6) {
      const r = parseInt(hex.slice(0, 2), 16);
      const g = parseInt(hex.slice(2, 4), 16);
      const b = parseInt(hex.slice(4, 6), 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    return null;
  }
  const m = s.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
}

function rgba(c: Vec3, a: number) {
  return `rgba(${c[0]},${c[1]},${c[2]},${a})`;
}

// round a raw interval to a 1/2/5 decade so tick labels land on clean values
function niceStep(raw: number) {
  const mag = 10 ** Math.floor(Math.log10(Math.max(1e-9, raw)));
  const n = raw / mag;
  return (n <= 1 ? 1 : n <= 2 ? 2 : n <= 5 ? 5 : 10) * mag;
}

export function LoupeSlider({
  value,
  defaultValue = 50,
  min = 0,
  max = 100,
  step = 1,
  tickStep,
  majorEvery = 5,
  formatLabel,
  formatValue,
  onValueChange,
  className = "",
  "aria-label": ariaLabel = "Value",
}: {
  /** controlled value; omit for uncontrolled */
  value?: number;
  /** uncontrolled initial value */
  defaultValue?: number;
  /** minimum allowed value */
  min?: number;
  /** maximum allowed value */
  max?: number;
  /** increment per keyboard/drag step */
  step?: number;
  /** minor tick interval in value units; auto-derived when omitted */
  tickStep?: number;
  /** every Nth minor tick is major and labeled */
  majorEvery?: number;
  /** tick label text (drawn on canvas) */
  formatLabel?: (v: number) => string;
  /** aria-valuetext for the current value */
  formatValue?: (v: number) => string;
  /** called with the new value on every drag/keyboard change */
  onValueChange?: (v: number) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** accessible name for the slider. Default "Value". */
  "aria-label"?: string;
}) {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const loupeRef = useRef<HTMLDivElement>(null);
  const thumbRef = useRef<HTMLDivElement>(null);
  const engineRef = useRef<{
    dragStart: (clientX: number) => void;
    dragMove: (clientX: number) => void;
    dragEnd: () => void;
    glideTo: (v: number) => void;
    dragging: () => boolean;
  } | null>(null);

  const isControlled = value !== undefined;
  const [internal, setInternal] = useState(() =>
    Math.min(max, Math.max(min, defaultValue))
  );
  const current = isControlled ? value : internal;
  const currentRef = useRef(current);
  currentRef.current = current;
  // mirrors :hover into data-hover — synthetic/dispatched pointer events never
  // flip Chromium's real hover pseudo-class, so an autoplay driver using them
  // needs an attribute to target (additive, doesn't change real-pointer feel)
  const [hover, setHover] = useState(false);

  const defaultLabel = (v: number) =>
    step < 1 ? v.toFixed(1) : String(Math.round(v));
  const fmtLabel = formatLabel ?? defaultLabel;
  const fmtValue = formatValue ?? fmtLabel;
  const labelRef = useRef(fmtLabel);
  labelRef.current = fmtLabel;

  const commitRef = useRef<(v: number) => void>(() => {});
  commitRef.current = (v: number) => {
    if (!isControlled) setInternal(v);
    onValueChange?.(v);
  };

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    const loupe = loupeRef.current;
    const thumb = thumbRef.current;
    if (!container || !canvas || !loupe || !thumb) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    // -- token-derived ink: read at mount, re-derived on theme class change --
    let fg: Vec3 = [237, 237, 237];
    let bd: Vec3 = [46, 46, 46];
    let monoFam = "ui-monospace, SFMono-Regular, Menlo, monospace";
    const derive = () => {
      const cs = getComputedStyle(document.documentElement);
      fg =
        parseColor(cs.getPropertyValue("--foreground")) ??
        parseColor(getComputedStyle(container).color) ??
        fg;
      bd = parseColor(cs.getPropertyValue("--border")) ?? bd;
      const fam = getComputedStyle(container).fontFamily;
      if (fam) monoFam = fam;
    };
    derive();

    // -- hot-path state: locals only, never React state ---------------------
    let w = 0;
    let h = 0;
    let cy = 32;
    let dpr = 1;
    let sized = false;
    let raf = 0;
    let last = 0;
    let visible = true;
    let tx = 0; // thumb x (canvas coords)
    let tv = 0;
    let lx = 0; // loupe x, springs after the thumb
    let lv = 0;
    let targetX = 0;
    let mag = MAG_BASE;
    let wobbleAt = -1; // performance.now() when the wobble started
    let dragging = false;
    let committed = currentRef.current;
    let deadline = 0; // forced-settle deadline (performance.now())

    // cached layers: sharp scale at 2x supersample (stays crisp when the lens
    // magnifies it), blurred base derived from it once per size/theme change
    const sharp = document.createElement("canvas");
    const soft = document.createElement("canvas");

    const span = () => Math.max(1e-9, max - min);
    const xFor = (v: number) =>
      PAD + ((v - min) / span()) * Math.max(1, w - PAD * 2);
    const quantize = (v: number) => {
      const q = min + Math.round((v - min) / step) * step;
      return Math.min(max, Math.max(min, Number(q.toFixed(6))));
    };

    // geometry hugs the lens center: the clip radius is LENS_R*mag/MAG_BASE
    // and the draw pass is scaled by `mag` around the same center, so a
    // pre-mag point at offset d from (lx,cy) lands at d*mag post-transform —
    // the mag-INDEPENDENT safe envelope is |d| <= LENS_R/MAG_BASE (R0),
    // regardless of the 1.8->2.0 wobble. That only bounds height though:
    // labels also need their magnified WIDTH inside the chord at that
    // offset, so they sit at the lens's vertical center (dy small, near 0)
    // for the widest available chord, AND get measured + font-shrunk per
    // label so arbitrary formatLabel strings (not just 2-digit numbers)
    // never get sliced by the rim.
    const drawScale = (g: CanvasRenderingContext2D) => {
      let minor = tickStep && tickStep > 0 ? tickStep : niceStep(span() / 60);
      while (span() / minor > 240) minor *= 2; // cap the tick count
      const every = majorEvery > 0 ? Math.round(majorEvery) : 5;
      const axisY = cy - 12;
      g.strokeStyle = rgba(bd, 1);
      g.lineWidth = 1;
      g.beginPath();
      g.moveTo(PAD, axisY + 0.5);
      g.lineTo(w - PAD, axisY + 0.5);
      g.stroke();
      const count = Math.floor(span() / minor + 1e-6);
      // minor ticks
      g.strokeStyle = rgba(fg, 0.45);
      g.beginPath();
      for (let i = 0; i <= count; i++) {
        if (i % every === 0) continue;
        const x = Math.round(xFor(min + i * minor)) + 0.5;
        g.moveTo(x, axisY);
        g.lineTo(x, axisY + 6);
      }
      g.stroke();
      // major ticks + labels
      g.strokeStyle = rgba(fg, 0.8);
      g.beginPath();
      for (let i = 0; i <= count; i += every) {
        const x = Math.round(xFor(min + i * minor)) + 0.5;
        g.moveTo(x, axisY);
        g.lineTo(x, axisY + 10);
      }
      g.stroke();
      // labels: near lens-center for max chord width, font shrunk per-label
      // when it would still overflow that chord (see comment above drawScale)
      const R0 = LENS_R / MAG_BASE;
      const labelDy = 2; // small clearance below the major tick tips (-2)
      const maxWidth =
        2 * Math.sqrt(Math.max(0, R0 * R0 - labelDy * labelDy)) * 0.92;
      const baseFontPx = 9;
      g.textAlign = "center";
      g.textBaseline = "middle";
      g.fillStyle = rgba(fg, 0.9);
      for (let i = 0; i <= count; i += every) {
        const v = Number((min + i * minor).toFixed(6));
        const text = labelRef.current(v);
        g.font = `500 ${baseFontPx}px ${monoFam}`;
        const measured = g.measureText(text).width;
        const fontPx =
          measured > maxWidth && measured > 0
            ? Math.max(5, baseFontPx * (maxWidth / measured))
            : baseFontPx;
        if (fontPx !== baseFontPx) g.font = `500 ${fontPx}px ${monoFam}`;
        g.fillText(text, xFor(v), cy + labelDy);
      }
    };

    const buildLayers = () => {
      if (!sized) return;
      const S = dpr * 2; // supersample so the 1.8-2.0x pass stays sharp
      sharp.width = Math.ceil(w * S);
      sharp.height = Math.ceil(h * S);
      const sctx = sharp.getContext("2d");
      if (!sctx) return;
      sctx.setTransform(S, 0, 0, S, 0, 0);
      sctx.clearRect(0, 0, w, h);
      drawScale(sctx);
      soft.width = Math.ceil(w * dpr);
      soft.height = Math.ceil(h * dpr);
      const bctx = soft.getContext("2d");
      if (!bctx) return;
      bctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      bctx.clearRect(0, 0, w, h);
      bctx.filter = "blur(1.5px)";
      if (bctx.filter.indexOf("blur") !== -1) {
        bctx.drawImage(sharp, 0, 0, w, h);
        bctx.filter = "none";
      } else {
        // no ctx.filter support: approximate with a 9-tap ring average
        bctx.globalAlpha = 1 / 9;
        bctx.drawImage(sharp, 0, 0, w, h);
        for (let k = 0; k < 8; k++) {
          const a = (k / 8) * Math.PI * 2;
          bctx.drawImage(sharp, Math.cos(a) * 1.3, Math.sin(a) * 1.3, w, h);
        }
        bctx.globalAlpha = 1;
      }
    };

    // full clear + composite from cached layers every frame — no filter work
    // on the hot path, no alpha accumulation
    const render = () => {
      if (!sized) return;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      ctx.globalAlpha = 0.55;
      ctx.drawImage(soft, 0, 0, w, h);
      ctx.globalAlpha = 1;
      const r = LENS_R * (mag / MAG_BASE);
      ctx.save();
      ctx.beginPath();
      ctx.arc(lx, cy, r, 0, Math.PI * 2);
      ctx.clip();
      ctx.clearRect(0, 0, w, h); // knock the soft pass out of the lens
      ctx.translate(lx, cy);
      ctx.scale(mag, mag);
      ctx.translate(-lx, -cy);
      ctx.drawImage(sharp, 0, 0, w, h);
      ctx.restore();
      // loupe + thumb are DOM nodes on OFFSET transforms from the container's
      // top-left anchor — never absolute canvas coords
      const ringScale = mag / MAG_BASE;
      loupe.style.transform = `translate3d(${(lx - LENS_R).toFixed(2)}px, ${(
        cy - LENS_R
      ).toFixed(2)}px, 0) scale(${ringScale.toFixed(4)})`;
      thumb.style.transform = `translate3d(${(tx - 12).toFixed(2)}px, ${(
        cy - 12
      ).toFixed(2)}px, 0)`;
    };

    const resize = () => {
      const rect = container.getBoundingClientRect();
      if (rect.width < PAD * 2 + 8 || rect.height < 8) {
        sized = false; // zero-size guard — never draw into nothing
        return;
      }
      w = rect.width;
      h = rect.height;
      cy = h / 2;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      // a <canvas> is a replaced element: size the CSS box EXPLICITLY, or it
      // renders at dpr scale
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
      canvas.style.width = `${w}px`;
      canvas.style.height = `${h}px`;
      sized = true;
      buildLayers();
      targetX = xFor(currentRef.current);
      if (!raf) {
        tx = targetX;
        tv = 0;
        lx = targetX;
        lv = 0;
      }
      render();
    };
    resize();

    const loop = (now: number) => {
      raf = 0;
      const dt = last ? Math.min(0.033, (now - last) / 1000) : 1 / 60;
      last = now;
      let active = false;

      if (dragging) {
        active = true; // thumb is pinned to the pointer; loupe still chases
      } else {
        const c = 2 * HOME_ZETA * Math.sqrt(HOME_K);
        tv += (-HOME_K * (tx - targetX) - c * tv) * dt;
        tx += tv * dt;
        if (Math.abs(tx - targetX) < 0.05 && Math.abs(tv) < 0.5) {
          tx = targetX;
          tv = 0;
        } else active = true;
      }

      const cl = 2 * LOUPE_ZETA * Math.sqrt(LOUPE_K);
      lv += (-LOUPE_K * (lx - tx) - cl * lv) * dt;
      lx += lv * dt;
      if (!dragging && Math.abs(lx - tx) < 0.05 && Math.abs(lv) < 0.5) {
        lx = tx;
        lv = 0;
      } else if (Math.abs(lx - tx) >= 0.05 || Math.abs(lv) >= 0.5) {
        active = true;
      }

      if (wobbleAt >= 0) {
        const p = (now - wobbleAt) / WOBBLE_MS;
        if (p >= 1) {
          wobbleAt = -1;
          mag = MAG_BASE;
        } else {
          // half-sine out-and-back, tail damped: 1.8 -> 2.0 -> 1.8
          mag =
            MAG_BASE +
            (MAG_PEAK - MAG_BASE) * Math.sin(Math.PI * p) * (1 - 0.25 * p);
          active = true;
        }
      }

      // forced-settle deadline — springs AND wobble both answer to it
      if (active && !dragging && now > deadline) {
        tx = targetX;
        tv = 0;
        lx = targetX;
        lv = 0;
        mag = MAG_BASE;
        wobbleAt = -1;
        active = false;
      }

      render();
      if (active && visible && !document.hidden) {
        raf = requestAnimationFrame(loop);
      }
    };

    const wake = () => {
      if (!raf && sized) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    // -- interaction (called from React handlers via engineRef) -------------
    const dragMove = (clientX: number) => {
      if (!sized) return;
      const rect = canvas.getBoundingClientRect();
      const x = clientX - rect.left;
      const lo = PAD;
      const hi = w - PAD;
      let px = x;
      if (x < lo) px = lo + Math.max(-RUBBER_MAX, (x - lo) * RUBBER);
      else if (x > hi) px = hi + Math.min(RUBBER_MAX, (x - hi) * RUBBER);
      const clamped = Math.min(hi, Math.max(lo, x));
      const v = quantize(min + ((clamped - lo) / Math.max(1, hi - lo)) * span());
      targetX = xFor(v); // release springs home to the committed value
      if (v !== committed) {
        committed = v;
        commitRef.current(v);
      }
      deadline = performance.now() + SETTLE_MS;
      if (reduced) {
        tx = px;
        lx = px;
        tv = 0;
        lv = 0;
        render();
        return;
      }
      tx = px;
      wake();
    };

    const dragStart = (clientX: number) => {
      if (!sized) return;
      dragging = true;
      committed = currentRef.current;
      dragMove(clientX);
    };

    const dragEnd = () => {
      if (!dragging) return;
      dragging = false;
      const past = tx < PAD - 0.5 || tx > w - PAD + 0.5;
      deadline = performance.now() + SETTLE_MS;
      if (reduced) {
        tx = targetX;
        lx = targetX;
        tv = 0;
        lv = 0;
        render(); // no wobble, instant reposition — magnification itself stays
        return;
      }
      if (past) wobbleAt = performance.now(); // refractive wobble on release
      wake();
    };

    const glideTo = (v: number) => {
      if (dragging || !sized) return;
      committed = v;
      targetX = xFor(v);
      deadline = performance.now() + SETTLE_MS;
      if (reduced) {
        tx = targetX;
        lx = targetX;
        tv = 0;
        lv = 0;
        render();
        return;
      }
      wake();
    };

    engineRef.current = {
      dragStart,
      dragMove,
      dragEnd,
      glideTo,
      dragging: () => dragging,
    };

    // -- observers ----------------------------------------------------------
    const ro = new ResizeObserver(resize);
    ro.observe(container);
    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
      if (visible) wake();
    });
    io.observe(container);
    // live theme re-derive: rebuild the blur layer on documentElement flips
    const mo = new MutationObserver(() => {
      derive();
      buildLayers();
      render();
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });
    const onVis = () => {
      if (!document.hidden) wake();
    };
    document.addEventListener("visibilitychange", onVis);

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", onVis);
      engineRef.current = null;
    };
  }, [min, max, step, tickStep, majorEvery]);

  // keyboard + external value changes glide the loupe on the same spring
  useEffect(() => {
    engineRef.current?.glideTo(current);
  }, [current]);

  const onKeyDown = (e: React.KeyboardEvent) => {
    let next: number | null = null;
    const v = currentRef.current;
    switch (e.key) {
      case "ArrowRight":
      case "ArrowUp":
        next = v + step;
        break;
      case "ArrowLeft":
      case "ArrowDown":
        next = v - step;
        break;
      case "PageUp":
        next = v + step * 10;
        break;
      case "PageDown":
        next = v - step * 10;
        break;
      case "Home":
        next = min;
        break;
      case "End":
        next = max;
        break;
      default:
        return;
    }
    e.preventDefault();
    next = Math.min(max, Math.max(min, Number(next.toFixed(6))));
    if (next !== v) commitRef.current(next);
  };

  return (
    <div
      ref={containerRef}
      data-hover={hover}
      className={`group relative h-16 w-full cursor-ew-resize touch-none select-none font-mono ${className}`}
      onPointerDown={(e) => {
        e.preventDefault();
        e.currentTarget.setPointerCapture(e.pointerId);
        thumbRef.current?.focus({ preventScroll: true });
        engineRef.current?.dragStart(e.clientX);
      }}
      onPointerMove={(e) => {
        if (engineRef.current?.dragging()) engineRef.current.dragMove(e.clientX);
      }}
      onPointerUp={() => engineRef.current?.dragEnd()}
      onPointerCancel={() => engineRef.current?.dragEnd()}
      onPointerEnter={() => setHover(true)}
      onPointerLeave={() => setHover(false)}
    >
      <canvas
        ref={canvasRef}
        aria-hidden
        className="pointer-events-none absolute left-0 top-0"
      />
      <div
        ref={loupeRef}
        aria-hidden
        className="pointer-events-none absolute left-0 top-0 h-11 w-11 rounded-full border border-border shadow-[0_2px_10px_-4px_rgba(0,0,0,0.4)] transition-colors duration-200 will-change-transform group-hover:border-foreground/40 group-data-[hover=true]:border-foreground/40"
      />
      <div
        ref={thumbRef}
        role="slider"
        tabIndex={0}
        aria-label={ariaLabel}
        aria-orientation="horizontal"
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={current}
        aria-valuetext={fmtValue(current)}
        onKeyDown={onKeyDown}
        className="absolute left-0 top-0 h-6 w-6 rounded-full outline-none will-change-transform focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background"
      >
        <span
          aria-hidden
          className="absolute left-1/2 top-1/2 h-4 w-0.5 -translate-x-1/2 -translate-y-1/2 rounded-full bg-foreground/80 transition-colors duration-200 group-hover:bg-foreground group-data-[hover=true]:bg-foreground"
        />
      </div>
    </div>
  );
}

"use client";

import { useLayoutEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// ShearBand — dual-handle range slider whose selected span is a taut band of
// material rather than two disconnected thumbs. The band is an SVG <polygon>
// between the min/max grips, not a plain rect: while a grip drags, the
// pointer's instantaneous velocity drives a clamped px "lean" applied ONLY to
// the two corners of the dragged (near) edge — offset in opposite directions,
// top one way and bottom the other — while the far edge's two corners stay
// pinned at its exact x. That's a deliberate departure from a literal CSS
// skewX(): skewX shears every row by the same amount regardless of x, so it
// cannot keep one vertical edge stationary while the other leans — at any
// magnitude big enough to actually see, a symmetric skew would drag the far
// edge visibly off the planted grip, which reads as broken, not as tension.
// Four independently-placed polygon corners can pin one edge exactly while
// the other one leans, which is what "shears under velocity, far thumb
// stays planted" actually requires. Release relaxes the lean back to 0 on an
// underdamped spring (~1.5 visible oscillations) rather than snapping flat.
//
// A11y is carried entirely by two real <input type="range"> (min/max),
// visually hidden (sr-only, not display:none) so Tab reaches both and native
// arrow/Home/End/PageUp/PageDown handling comes for free. Each input's own
// min/max attribute is clamped to the OTHER thumb's current value (minInput's
// max = current hi, maxInput's min = current lo) so keyboard input can never
// cross the thumbs — no custom keydown handler needed. aria-valuetext names
// the other bound so a screen reader hears "minimum, 40 of maximum 200"
// rather than a bare number. The lean is presentation-only: it never touches
// the committed value and is skipped entirely under prefers-reduced-motion
// (positions still update, just without the lean or the release spring).
//
// Pointer interaction lives on the shared root, not on the (invisible)
// inputs — a pointerdown picks whichever grip's pixel position is nearer the
// click (ties resolve toward whichever grip the pointer sits outside of),
// then focuses that grip's real input so keyboard nav can continue from
// there. That proximity arbitration is what makes overlapping/touching
// thumbs (a zero-width span) pickable on touch, where there's no hover to
// disambiguate first.
// ---------------------------------------------------------------------------

const PAD = 14; // px inset so grips/labels never clip at the track ends
const BAND_H = 14; // px height of the material band
const TRACK_Y = 40; // px vertical center of the track/grips within the root
const ROOT_H = 56; // px total component height (label row + track row)
const LEAN_MAX_PX = 8; // max near-edge corner offset (top and bottom, opposite signs)
const VEL_TO_LEAN = 0.09; // px of lean per px/s of pointer velocity, pre-clamp
const LEAN_SMOOTH = 0.5; // per-event lerp toward the velocity-derived target
const SPRING_K = 300; // s^-2, release spring back to 0
const SPRING_ZETA = 0.22; // underdamped -> ~1.5 visible oscillations before rest

type Thumb = "lo" | "hi";

const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));

export interface ShearBandProps {
  /** minimum allowed value for either thumb */
  min?: number;
  /** maximum allowed value for either thumb */
  max?: number;
  /** increment per keyboard/drag step */
  step?: number;
  /** controlled [min, max] value; omit for uncontrolled */
  value?: [number, number];
  /** uncontrolled initial [min, max] value */
  defaultValue?: [number, number];
  /** called with the new [min, max] on every drag/keyboard change */
  onValueChange?: (value: [number, number]) => void;
  /** formats a bound for both the printed readout and aria-valuetext */
  formatValue?: (v: number) => string;
  /** accessible name for the lower-bound input */
  minLabel?: string;
  /** accessible name for the upper-bound input */
  maxLabel?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function ShearBand({
  min = 0,
  max = 100,
  step = 1,
  value,
  defaultValue = [25, 75],
  onValueChange,
  formatValue,
  minLabel = "Minimum value",
  maxLabel = "Maximum value",
  className = "",
}: ShearBandProps) {
  const isControlled = value !== undefined;
  const [loState, setLoState] = useState(() => clamp(defaultValue[0], min, max));
  const [hiState, setHiState] = useState(() => clamp(defaultValue[1], min, max));
  const lo = isControlled ? value[0] : loState;
  const hi = isControlled ? value[1] : hiState;
  const loRef = useRef(lo);
  loRef.current = lo;
  const hiRef = useRef(hi);
  hiRef.current = hi;

  const fmt = formatValue ?? ((v: number) => (step % 1 !== 0 ? v.toFixed(2) : String(Math.round(v))));
  const fmtRef = useRef(fmt);
  fmtRef.current = fmt;

  const [activeThumb, setActiveThumb] = useState<Thumb | null>(null);
  const [focusedThumb, setFocusedThumb] = useState<Thumb | null>(null);
  const [trackW, setTrackW] = useState(0);
  // lean: signed px offset applied to the dragged edge's corners; shearSide:
  // which edge is currently "near" (the other stays planted). Both are React
  // state — position changes already re-render on every quantized pointermove,
  // so driving the lean through state too costs nothing extra and keeps a
  // single source of truth instead of a parallel imperative path.
  const [lean, setLean] = useState(0);
  const [shearSide, setShearSide] = useState<Thumb | null>(null);

  const rootRef = useRef<HTMLDivElement>(null);
  const minInputRef = useRef<HTMLInputElement>(null);
  const maxInputRef = useRef<HTMLInputElement>(null);

  const activeRef = useRef<Thumb | null>(null);
  const reducedRef = useRef(false);
  const rafRef = useRef(0);
  const leanRef = useRef(0);
  const leanVelRef = useRef(0);
  const lastXRef = useRef(0);
  const lastTRef = useRef(0);

  // live width of the track/grip row — measured, not assumed, so PAD-relative
  // positions stay exact across container resizes
  useLayoutEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const measure = () => setTrackW(el.getBoundingClientRect().width);
    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  useLayoutEffect(() => {
    reducedRef.current = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, []);

  const xFor = (v: number, w: number) => {
    const frac = clamp((v - min) / (max - min || 1e-9), 0, 1);
    return PAD + frac * Math.max(1, w - PAD * 2);
  };
  const valueFromX = (x: number, w: number) => {
    const usable = Math.max(1, w - PAD * 2);
    const frac = clamp((x - PAD) / usable, 0, 1);
    return min + frac * (max - min);
  };
  const quantize = (v: number) => {
    const stepped = min + Math.round((v - min) / step) * step;
    return Number(clamp(stepped, min, max).toFixed(6));
  };

  const commit = (which: Thumb, v: number) => {
    const nextLo = which === "lo" ? v : loRef.current;
    const nextHi = which === "hi" ? v : hiRef.current;
    if (nextLo === loRef.current && nextHi === hiRef.current) return;
    loRef.current = nextLo;
    hiRef.current = nextHi;
    if (!isControlled) {
      setLoState(nextLo);
      setHiState(nextHi);
    }
    onValueChange?.([nextLo, nextHi]);
  };

  // proximity arbitration: whichever grip's pixel position is nearer the
  // pointer wins; an exact tie (thumbs coincident, or click sits precisely at
  // the midpoint) extends outward in whichever direction the pointer already
  // sits past the shared span, else defaults to the lower bound — this is
  // what makes a zero-width (touching) span still pickable on touch
  const pickThumb = (x: number, loPx: number, hiPx: number): Thumb => {
    const dLo = Math.abs(x - loPx);
    const dHi = Math.abs(x - hiPx);
    if (dLo !== dHi) return dLo < dHi ? "lo" : "hi";
    if (x < loPx) return "lo";
    if (x > hiPx) return "hi";
    return "lo";
  };

  const moveActiveTo = (which: Thumb, x: number, w: number) => {
    let v = quantize(valueFromX(x, w));
    if (which === "lo") v = Math.min(v, hiRef.current);
    else v = Math.max(v, loRef.current);
    commit(which, v);
  };

  const startSpring = () => {
    let last = performance.now();
    const tick = (now: number) => {
      const dt = Math.min(0.032, Math.max(0, (now - last) / 1000));
      last = now;
      const c = 2 * SPRING_ZETA * Math.sqrt(SPRING_K);
      leanVelRef.current += (-SPRING_K * leanRef.current - c * leanVelRef.current) * dt;
      leanRef.current += leanVelRef.current * dt;
      if (Math.abs(leanRef.current) < 0.05 && Math.abs(leanVelRef.current) < 1) {
        leanRef.current = 0;
        leanVelRef.current = 0;
        setLean(0);
        rafRef.current = 0;
        return;
      }
      setLean(leanRef.current);
      rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);
  };

  const onPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    const root = e.currentTarget;
    const rect = root.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const which = pickThumb(x, xFor(loRef.current, rect.width), xFor(hiRef.current, rect.width));
    activeRef.current = which;
    setActiveThumb(which);
    setShearSide(which);
    root.setPointerCapture(e.pointerId);
    (which === "lo" ? minInputRef : maxInputRef).current?.focus({ preventScroll: true });
    lastXRef.current = x;
    lastTRef.current = performance.now();
    if (rafRef.current) {
      cancelAnimationFrame(rafRef.current);
      rafRef.current = 0;
    }
    leanRef.current = 0;
    leanVelRef.current = 0;
    setLean(0);
    moveActiveTo(which, x, rect.width);
    e.preventDefault();
  };

  const onPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    const which = activeRef.current;
    if (!which) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX - rect.left;
    moveActiveTo(which, x, rect.width);
    const now = performance.now();
    const dt = Math.max(1, now - lastTRef.current) / 1000;
    const dx = x - lastXRef.current;
    lastXRef.current = x;
    lastTRef.current = now;
    if (!reducedRef.current) {
      const vel = dx / dt;
      const target = clamp(vel * VEL_TO_LEAN, -LEAN_MAX_PX, LEAN_MAX_PX);
      leanRef.current += (target - leanRef.current) * LEAN_SMOOTH;
      setLean(leanRef.current);
    }
  };

  const endDrag = () => {
    if (!activeRef.current) return;
    activeRef.current = null;
    setActiveThumb(null);
    if (!reducedRef.current && Math.abs(leanRef.current) > 0.01) {
      startSpring();
    } else {
      leanRef.current = 0;
      setLean(0);
    }
  };

  const onFocusVisible = (which: Thumb) => (e: React.FocusEvent<HTMLInputElement>) => {
    if (e.target.matches(":focus-visible")) setFocusedThumb(which);
  };
  const onBlurThumb = (which: Thumb) => () => {
    setFocusedThumb((f) => (f === which ? null : f));
  };

  const loPx = xFor(lo, trackW);
  const hiPx = xFor(hi, trackW);
  const loEngaged = activeThumb === "lo" || focusedThumb === "lo";
  const hiEngaged = activeThumb === "hi" || focusedThumb === "hi";

  // pinned-edge trapezoid: the far edge's top+bottom corners share one x (the
  // planted grip), the near (dragged) edge's corners split by +-lean — clamped
  // to a fraction of the current span so a near-zero gap can't self-cross
  const span = Math.max(0, hiPx - loPx);
  const effLean = shearSide ? clamp(lean, -span * 0.9, span * 0.9) : 0;
  const bandPoints =
    shearSide === "lo"
      ? `${loPx + effLean},0 ${hiPx},0 ${hiPx},${BAND_H} ${loPx - effLean},${BAND_H}`
      : shearSide === "hi"
        ? `${loPx},0 ${hiPx + effLean},0 ${hiPx - effLean},${BAND_H} ${loPx},${BAND_H}`
        : `${loPx},0 ${hiPx},0 ${hiPx},${BAND_H} ${loPx},${BAND_H}`;

  const gripStyle = (px: number, engaged: boolean): React.CSSProperties => ({
    transform: `translate3d(${px}px, ${TRACK_Y}px, 0) translate(-50%, -50%)`,
    height: engaged ? 26 : 20,
    width: engaged ? 3 : 2,
    backgroundColor: "var(--foreground)",
    opacity: engaged ? 1 : 0.55,
    boxShadow: engaged
      ? "0 1px 2px 0 color-mix(in srgb, var(--foreground) 45%, transparent)"
      : "none",
  });

  return (
    <div className={`relative w-full font-mono ${className}`} style={{ height: ROOT_H }}>
      <div
        ref={rootRef}
        data-slider-range-shear-track
        className="relative h-full w-full touch-none select-none"
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={endDrag}
        onPointerCancel={endDrag}
      >
        {/* printed values, Geist Mono, sliding with their grip */}
        <span
          aria-hidden
          className="pointer-events-none absolute top-0 whitespace-nowrap text-xs tabular-nums text-foreground transition-transform duration-150 ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:transition-none"
          style={{ transform: `translateX(${loPx}px) translateX(-50%)` }}
        >
          {fmt(lo)}
        </span>
        <span
          aria-hidden
          className="pointer-events-none absolute top-0 whitespace-nowrap text-xs tabular-nums text-foreground transition-transform duration-150 ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:transition-none"
          style={{ transform: `translateX(${hiPx}px) translateX(-50%)` }}
        >
          {fmt(hi)}
        </span>

        {/* hairline base track */}
        <div
          aria-hidden
          className="pointer-events-none absolute h-px"
          style={{ left: PAD, right: PAD, top: TRACK_Y, backgroundColor: "var(--border)" }}
        />

        {/* the band — a real SVG polygon, the taut material between the
            grips. Its far edge (opposite whichever grip is dragging) is
            pinned to an exact x; only the near edge's corners lean */}
        <svg
          aria-hidden
          className="pointer-events-none absolute left-0 overflow-visible"
          width={trackW}
          height={BAND_H}
          style={{ top: TRACK_Y - BAND_H / 2 }}
        >
          <polygon
            points={bandPoints}
            style={{
              fill: "color-mix(in srgb, var(--foreground) 10%, transparent)",
              stroke: "var(--border)",
              strokeWidth: 1,
            }}
          />
        </svg>

        {/* grips — thin vertical bars; the dragged one thickens and lifts */}
        <div
          aria-hidden
          className="pointer-events-none absolute left-0 top-0 rounded-full transition-[height,width,box-shadow] duration-150 ease-out motion-reduce:transition-none"
          style={gripStyle(loPx, loEngaged)}
        />
        <div
          aria-hidden
          className="pointer-events-none absolute left-0 top-0 rounded-full transition-[height,width,box-shadow] duration-150 ease-out motion-reduce:transition-none"
          style={gripStyle(hiPx, hiEngaged)}
        />
        {focusedThumb === "lo" && (
          <div
            aria-hidden
            className="pointer-events-none absolute left-0 top-0 rounded-full ring-2 ring-ns-accent ring-offset-2 ring-offset-background"
            style={{
              transform: `translate3d(${loPx}px, ${TRACK_Y}px, 0) translate(-50%, -50%)`,
              height: 26,
              width: 3,
            }}
          />
        )}
        {focusedThumb === "hi" && (
          <div
            aria-hidden
            className="pointer-events-none absolute left-0 top-0 rounded-full ring-2 ring-ns-accent ring-offset-2 ring-offset-background"
            style={{
              transform: `translate3d(${hiPx}px, ${TRACK_Y}px, 0) translate(-50%, -50%)`,
              height: 26,
              width: 3,
            }}
          />
        )}

        {/* real inputs carry all a11y: focusable, Tab-reachable, native
            arrow/Home/End/PageUp/PageDown; each one's own min/max is pinned to
            the other thumb's current value so keyboard can never cross them */}
        <input
          ref={minInputRef}
          type="range"
          min={min}
          max={hi}
          step={step}
          value={lo}
          aria-label={minLabel}
          aria-valuetext={`minimum, ${fmtRef.current(lo)} of maximum ${fmtRef.current(hi)}`}
          onChange={(e) => commit("lo", Math.min(quantize(Number(e.target.value)), hiRef.current))}
          onFocus={onFocusVisible("lo")}
          onBlur={onBlurThumb("lo")}
          className="sr-only"
        />
        <input
          ref={maxInputRef}
          type="range"
          min={lo}
          max={max}
          step={step}
          value={hi}
          aria-label={maxLabel}
          aria-valuetext={`maximum, ${fmtRef.current(hi)} of minimum ${fmtRef.current(lo)}`}
          onChange={(e) => commit("hi", Math.max(quantize(Number(e.target.value)), loRef.current))}
          onFocus={onFocusVisible("hi")}
          onBlur={onBlurThumb("hi")}
          className="sr-only"
        />
      </div>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// VernierSlip — a numeric input built as a true vernier caliper: a fixed
// coarse tick row (one tick per 10*step, "UNIT") sits above a sliding fine
// row whose pitch is 0.9x the coarse pitch. Given quantized value v, let
// totalSteps = round((v-min)/step), fineIdx = totalSteps mod 10 (0..9),
// coarseIdx = (totalSteps-fineIdx)/10. Real vernier math: fine tick #fineIdx
// coincides with main tick #(coarseIdx+fineIdx), not #coarseIdx — the
// matching line drifts down the fixed scale as the reading grows, exactly
// as on a physical caliper. That fine tick gets --ns-accent plus a hairline
// back to its coincidence partner. Two drag zones on the same track: upper
// half ("body") maps pointer position to value absolutely (fast, spans the
// whole range); lower half (the vernier row itself) maps pointer DELTA to
// value at one step per fine-tick-width (slow, precise). Both zones commit
// through the same quantize(step) pipeline — the split changes sensitivity,
// not resolution. Release, keyboard nav, and external value changes ease
// the visual (never the already-committed value) toward the settled
// position on an ease-out-expo tween; raw drag tracks the pointer 1:1 so
// the coincidence is something you visibly chase into alignment. Direct-DOM
// rAF for the tween only (sleeps otherwise); tick highlighting is ordinary
// React state, since it only changes at quantized-value granularity. All
// ink is currentColor via token utility classes — no canvas, no derived hex.
// ---------------------------------------------------------------------------

const FINE_RATIO = 0.9; // vernier pitch = 0.9x coarse pitch — the actual geometry
const MIN_PITCH = 18;
const MAX_PITCH = 56;
const SETTLE_MS = 260;
const H = 84; // svg content height
const COARSE_BASELINE = 15;
const COARSE_TIP_MINOR = 24;
const COARSE_TIP_MAJOR = 30;
const COARSE_LABEL_Y = 8;
const FINE_BASELINE = 68;
const FINE_TIP = 54;
const FINE_LABEL_Y = 78;

function easeOutExpo(t: number) {
  return t >= 1 ? 1 : 1 - Math.pow(2, -10 * t);
}

export interface VernierSlipProps {
  /** controlled value; omit for uncontrolled */
  value?: number;
  /** uncontrolled initial value */
  defaultValue?: number;
  /** minimum allowed value */
  min?: number;
  /** maximum allowed value */
  max?: number;
  /** resolution — the fine (vernier) scale reveals exactly this last digit */
  step?: number;
  /** accessible name, also shown as the eyebrow caption */
  label?: string;
  /** unit suffix rendered beside the value, e.g. "mg", "dB" */
  unit?: string;
  /** aria-valuetext override */
  formatValue?: (v: number) => string;
  /** called with the new value on every drag/keyboard change */
  onValueChange?: (value: number) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function VernierSlip({
  value,
  defaultValue = 1,
  min = 0,
  max = 10,
  step = 0.1,
  label = "Value",
  unit,
  formatValue,
  onValueChange,
  className = "",
}: VernierSlipProps) {
  const safeStep = step > 0 ? step : 0.1;
  const safeMax = max > min ? max : min + safeStep * 10;
  const decimals = (() => {
    const f = String(safeStep).split(".")[1];
    return f ? f.length : 0;
  })();
  const UNIT = safeStep * 10; // coarse pitch, in value units

  const quantize = (v: number) => {
    const q = min + Math.round((v - min) / safeStep) * safeStep;
    return Number(Math.min(safeMax, Math.max(min, q)).toFixed(6));
  };

  const isControlled = value !== undefined;
  const [internal, setInternal] = useState(() =>
    quantize(defaultValue)
  );
  const current = isControlled ? quantize(value as number) : internal;
  const currentRef = useRef(current);
  currentRef.current = current;

  const fmtValue =
    formatValue ?? ((v: number) => `${v.toFixed(decimals)}${unit ? ` ${unit}` : ""}`);

  // -- index math: which fine tick lights up, and which main tick it meets --
  const totalSteps = Math.round((current - min) / safeStep);
  const fineIdx = ((totalSteps % 10) + 10) % 10;
  const coarseIdx = (totalSteps - fineIdx) / 10;
  const matchIdx = coarseIdx + fineIdx;

  const totalStepsMax = Math.round((safeMax - min) / safeStep);
  const coarseIdxMax = Math.max(1, Math.ceil(totalStepsMax / 10));
  // +9 padding so the coincidence tick (which can drift up to 9 ticks past
  // the "reading" index) always has a rendered main tick to land on
  const numCoarseTicks = coarseIdxMax + 9;

  const [pitch, setPitch] = useState(32);
  const trackRef = useRef<HTMLDivElement>(null);
  const fineGroupRef = useRef<SVGGElement>(null);
  const hairRef = useRef<SVGLineElement>(null);
  const pointerRef = useRef<SVGLineElement>(null);

  const pitchRef = useRef(pitch);
  pitchRef.current = pitch;
  const matchIdxRef = useRef(matchIdx);
  matchIdxRef.current = matchIdx;
  const fineIdxRef = useRef(fineIdx);
  fineIdxRef.current = fineIdx;

  // fit coarse pitch to the container; falls back to horizontal scroll
  // (track has overflow-x-auto) for domains too wide even at MIN_PITCH
  useEffect(() => {
    const track = trackRef.current;
    if (!track) return;
    const fit = (w: number) =>
      Math.min(MAX_PITCH, Math.max(MIN_PITCH, w / Math.max(1, numCoarseTicks)));
    setPitch(fit(track.clientWidth));
    const ro = new ResizeObserver((entries) => {
      const w = entries[0]?.contentRect.width ?? track.clientWidth;
      setPitch(fit(w));
    });
    ro.observe(track);
    return () => ro.disconnect();
  }, [numCoarseTicks]);

  const commitRef = useRef<(v: number) => void>(() => {});
  commitRef.current = (v: number) => {
    if (!isControlled) setInternal(v);
    onValueChange?.(v);
  };

  const engineRef = useRef<{
    dragStart: (clientX: number, clientY: number) => void;
    dragMove: (clientX: number) => void;
    dragEnd: () => void;
    glideTo: (v: number) => void;
  } | null>(null);

  // -- drag / settle engine: direct DOM, refs only, never React state -------
  useEffect(() => {
    const track = trackRef.current;
    const fineGroup = fineGroupRef.current;
    const hair = hairRef.current;
    const pointer = pointerRef.current;
    if (!track || !fineGroup || !hair || !pointer) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    const localQuantize = (v: number) => {
      const q = min + Math.round((v - min) / safeStep) * safeStep;
      return Number(Math.min(safeMax, Math.max(min, q)).toFixed(6));
    };

    let raw = currentRef.current; // continuous, unquantized while dragging
    let visX = 0; // current visual anchor of the fine group, world px
    let targetX = 0;
    let dragging = false;
    let dragMode: "coarse" | "fine" | null = null;
    let dragStartClientX = 0;
    let dragStartValue = 0;
    let raf = 0;
    let tweenStart = 0;
    let tweenFrom = 0;

    const pxPerUnit = () => pitchRef.current / UNIT;
    const xFor = (v: number) => (v - min) * pxPerUnit();

    const render = (x: number) => {
      visX = x;
      fineGroup.style.transform = `translate3d(${x.toFixed(2)}px,0,0)`;
      const finePitch = pitchRef.current * FINE_RATIO;
      const hx2 = x + fineIdxRef.current * finePitch;
      const hx1 = matchIdxRef.current * pitchRef.current;
      hair.setAttribute("x1", hx1.toFixed(2));
      hair.setAttribute("x2", hx2.toFixed(2));
      pointer.setAttribute("x1", x.toFixed(2));
      pointer.setAttribute("x2", x.toFixed(2));
    };

    render(xFor(raw));

    const loop = (now: number) => {
      raf = 0;
      if (dragging) return;
      const t = Math.min(1, (now - tweenStart) / SETTLE_MS);
      render(tweenFrom + (targetX - tweenFrom) * easeOutExpo(t));
      if (t < 1) raf = requestAnimationFrame(loop);
    };

    const wake = () => {
      if (!raf) raf = requestAnimationFrame(loop);
    };

    const settleTo = (v: number) => {
      targetX = xFor(v);
      raw = v;
      if (reduced) {
        cancelAnimationFrame(raf);
        raf = 0;
        render(targetX);
        return;
      }
      tweenFrom = visX;
      tweenStart = performance.now();
      wake();
    };

    const dragMove = (clientX: number) => {
      if (!dragging) return;
      const rect = track.getBoundingClientRect();
      let nextRaw: number;
      if (dragMode === "coarse") {
        nextRaw = min + (clientX - rect.left) / pxPerUnit();
      } else {
        const finePitch = pitchRef.current * FINE_RATIO;
        const deltaSteps = (clientX - dragStartClientX) / finePitch;
        nextRaw = dragStartValue + deltaSteps * safeStep;
      }
      nextRaw = Math.min(safeMax, Math.max(min, nextRaw));
      raw = nextRaw;
      render(xFor(raw));
      const q = localQuantize(raw);
      if (q !== currentRef.current) commitRef.current(q);
    };

    const dragStart = (clientX: number, clientY: number) => {
      const rect = track.getBoundingClientRect();
      dragMode = clientY - rect.top < H / 2 ? "coarse" : "fine";
      dragging = true;
      dragStartClientX = clientX;
      dragStartValue = currentRef.current;
      cancelAnimationFrame(raf);
      raf = 0;
      dragMove(clientX);
    };

    const dragEnd = () => {
      if (!dragging) return;
      dragging = false;
      dragMode = null;
      settleTo(currentRef.current);
    };

    const glideTo = (v: number) => {
      if (dragging) return;
      settleTo(v);
    };

    engineRef.current = { dragStart, dragMove, dragEnd, glideTo };

    return () => {
      cancelAnimationFrame(raf);
      engineRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [min, safeMax, safeStep, UNIT]);

  useEffect(() => {
    engineRef.current?.glideTo(current);
  }, [current]);

  const onKeyDown = (e: React.KeyboardEvent) => {
    const v = currentRef.current;
    let next: number | null = null;
    switch (e.key) {
      case "ArrowRight":
      case "ArrowUp":
        next = v + safeStep;
        break;
      case "ArrowLeft":
      case "ArrowDown":
        next = v - safeStep;
        break;
      case "PageUp":
        next = v + UNIT;
        break;
      case "PageDown":
        next = v - UNIT;
        break;
      case "Home":
        next = min;
        break;
      case "End":
        next = safeMax;
        break;
      default:
        return;
    }
    e.preventDefault();
    next = quantize(next);
    if (next !== v) commitRef.current(next);
  };

  const finePitch = pitch * FINE_RATIO;
  const labelStride = pitch < 26 ? 5 : pitch < 40 ? 2 : 1;

  const coarseTicks = useMemo(() => {
    const arr: { i: number; major: boolean; v: number }[] = [];
    for (let i = 0; i <= numCoarseTicks; i++) {
      arr.push({ i, major: i % labelStride === 0, v: min + i * UNIT });
    }
    return arr;
  }, [numCoarseTicks, labelStride, min, UNIT]);

  const fineTicks = useMemo(() => {
    const arr: { k: number }[] = [];
    for (let k = 0; k <= 10; k++) arr.push({ k });
    return arr;
  }, []);

  const svgWidth = numCoarseTicks * pitch;
  const str = current.toFixed(decimals);
  const restStr = decimals > 0 ? str.slice(0, -1) : str;
  const digitStr = decimals > 0 ? str.slice(-1) : "";

  return (
    <div
      className={`w-full max-w-md rounded-md border border-border bg-surface p-4 font-mono ${className}`}
    >
      <div className="flex items-baseline justify-between gap-3 pb-3">
        <span className="text-[10px] uppercase tracking-[0.2em] text-ns-muted">
          {label}
        </span>
        <div className="flex items-baseline gap-1">
          <span
            aria-hidden
            className="text-2xl font-semibold tabular-nums text-foreground"
          >
            {restStr}
            {digitStr ? (
              <span className="text-ns-accent">{digitStr}</span>
            ) : null}
          </span>
          {unit ? (
            <span className="text-xs text-ns-muted">{unit}</span>
          ) : null}
        </div>
      </div>

      <div
        ref={trackRef}
        role="slider"
        tabIndex={0}
        aria-label={label}
        aria-orientation="horizontal"
        aria-valuemin={min}
        aria-valuemax={safeMax}
        aria-valuenow={current}
        aria-valuetext={fmtValue(current)}
        data-vernier-track
        onKeyDown={onKeyDown}
        onPointerDown={(e) => {
          e.preventDefault();
          trackRef.current?.setPointerCapture(e.pointerId);
          trackRef.current?.focus({ preventScroll: true });
          engineRef.current?.dragStart(e.clientX, e.clientY);
        }}
        onPointerMove={(e) => engineRef.current?.dragMove(e.clientX)}
        onPointerUp={() => engineRef.current?.dragEnd()}
        onPointerCancel={() => engineRef.current?.dragEnd()}
        className="relative block w-full touch-none select-none overflow-x-auto rounded-sm outline-none focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-surface"
      >
        <svg
          width={svgWidth}
          height={H}
          className="block cursor-ew-resize"
          aria-hidden
        >
          {/* zone divider — subtle, purely decorative */}
          <line
            x1={0}
            x2={svgWidth}
            y1={H / 2}
            y2={H / 2}
            className="text-border"
            stroke="currentColor"
            strokeWidth={1}
            strokeDasharray="1 4"
          />

          {/* raw drag position — full-height guide, tracks the pointer 1:1 */}
          <line
            ref={pointerRef}
            y1={0}
            y2={H}
            className="text-foreground/15"
            stroke="currentColor"
            strokeWidth={1}
          />

          {/* coarse row — fixed, never translates */}
          <g>
            {coarseTicks.map(({ i, major, v }) => {
              const x = i * pitch;
              const isMatch = i === matchIdx;
              const tip = isMatch
                ? COARSE_TIP_MAJOR + 4
                : major
                  ? COARSE_TIP_MAJOR
                  : COARSE_TIP_MINOR;
              return (
                <g key={i}>
                  <line
                    x1={x}
                    x2={x}
                    y1={COARSE_BASELINE}
                    y2={tip}
                    className={isMatch ? "text-ns-accent" : "text-foreground/70"}
                    stroke="currentColor"
                    strokeWidth={isMatch ? 2 : 1}
                  />
                  {major && pitch >= 22 ? (
                    <text
                      x={x}
                      y={COARSE_LABEL_Y}
                      textAnchor={x < 6 ? "start" : x > svgWidth - 6 ? "end" : "middle"}
                      className={
                        isMatch
                          ? "fill-ns-accent font-medium"
                          : "fill-ns-muted"
                      }
                      style={{ fontSize: 9 }}
                    >
                      {v.toFixed(Math.max(0, decimals - 1))}
                    </text>
                  ) : null}
                </g>
              );
            })}
            <line
              x1={0}
              x2={svgWidth}
              y1={COARSE_BASELINE}
              y2={COARSE_BASELINE}
              className="text-border"
              stroke="currentColor"
              strokeWidth={1}
            />
          </g>

          {/* connecting hairline — the coincidence, drawn live each frame */}
          <line
            ref={hairRef}
            y1={COARSE_TIP_MAJOR}
            y2={FINE_TIP}
            className="text-ns-accent"
            stroke="currentColor"
            strokeWidth={1.25}
            strokeDasharray="2 2"
          />

          {/* fine (vernier) row — a rigid group that translates as one body */}
          <g ref={fineGroupRef}>
            <line
              x1={0}
              x2={10 * finePitch}
              y1={FINE_BASELINE}
              y2={FINE_BASELINE}
              className="text-border"
              stroke="currentColor"
              strokeWidth={1}
            />
            {fineTicks.map(({ k }) => {
              const x = k * finePitch;
              const isMatch = k === fineIdx;
              return (
                <g key={k}>
                  <line
                    x1={x}
                    x2={x}
                    y1={FINE_BASELINE}
                    y2={isMatch ? FINE_TIP - 4 : FINE_TIP}
                    className={
                      isMatch
                        ? "text-ns-accent"
                        : k <= 9
                          ? "text-foreground/70"
                          : "text-foreground/30"
                    }
                    stroke="currentColor"
                    strokeWidth={isMatch ? 2 : 1}
                  />
                  {k <= 9 ? (
                    <text
                      x={x}
                      y={FINE_LABEL_Y}
                      textAnchor="middle"
                      className={
                        isMatch ? "fill-ns-accent font-semibold" : "fill-ns-muted"
                      }
                      style={{ fontSize: 9 }}
                    >
                      {k}
                    </text>
                  ) : null}
                </g>
              );
            })}
          </g>
        </svg>
      </div>

      <div className="flex items-center justify-between pt-2 font-mono text-[10px] text-ns-muted">
        <span>drag body to set · drag scale below to fine-tune</span>
        <span aria-hidden className="tabular-nums">
          {min.toFixed(Math.max(0, decimals - 1))}–{safeMax.toFixed(Math.max(0, decimals - 1))}
        </span>
      </div>
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type CSSProperties,
} from "react";

// ---------------------------------------------------------------------------
// CarbonFlimsy — a primary text field with a "carbon copy" derived field
// stacked underneath it. Every keystroke in the primary is transformed
// (default: slugified) and stamped onto the flimsy sheet: each newly-arrived
// character mounts fresh and plays a short pressure-jitter keyframe
// (translate 0.4px, font-weight 600 -> 400), staggered ~15ms apart when
// several characters land at once (paste, or a full re-stamp). The flimsy
// sheet sits visually offset 4px down-right from the primary, like a second
// page peeking out from underneath — while linked its border and background
// read as a thin under-sheet (color-mix toward --ns-muted).
//
// Editing the flimsy directly detaches it: the offset springs back to zero,
// the border firms to --foreground at 30%, mirroring stops, and the value
// becomes independently editable. A "Relink" button (only rendered while
// detached) restores the coupling and replays a full re-stamp sweep across
// the freshly-derived value.
//
// Both fields are real, independently labelled <input> elements — the only
// decorative-only layer is the stamp overlay, an aria-hidden row of spans
// painted exactly over the flimsy input while its own text is transparent
// (caret-color kept so a real caret still shows). The flimsy input always
// carries the accessible value; the overlay never diverges from it. Detach
// and relink each fire one polite live-region announcement. Reduced motion
// drops the jitter and the spring transition; nothing about legibility or
// operability depends on either.
// ---------------------------------------------------------------------------

type Vars = CSSProperties & Record<`--${string}`, string | number>;

const CHAR_STAGGER_MS = 15;

function defaultTransform(value: string): string {
  return value
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function commonPrefixLength(a: string, b: string): number {
  const n = Math.min(a.length, b.length);
  let i = 0;
  while (i < n && a[i] === b[i]) i++;
  return i;
}

function useReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

interface Stamp {
  text: string;
  /** per-character "batch" id — a span's React key includes this, so only
   *  characters whose gen just changed remount and replay the jitter. */
  gen: number[];
  /** index the current batch's newly-stamped run starts at, for stagger delay. */
  from: number;
}

export interface CarbonFlimsyProps {
  /** Accessible label for the primary field, e.g. "Project title". */
  label: string;
  /** Accessible label for the derived flimsy field, e.g. "Slug". */
  derivedLabel: string;
  /** Controlled primary value. */
  value?: string;
  /** Initial primary value when uncontrolled. @default "" */
  defaultValue?: string;
  /** called with the new primary value on every keystroke */
  onValueChange?: (value: string) => void;
  /** Fires whenever the derived value changes, with whether it's still linked. */
  onDerivedChange?: (value: string, linked: boolean) => void;
  /** Transforms the primary value into the derived one. @default slugify */
  transform?: (value: string) => string;
  /** placeholder for the primary field */
  placeholder?: string;
  /** Shown in the flimsy field while its value is empty. @default "auto-generated" */
  derivedPlaceholder?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function CarbonFlimsy({
  label,
  derivedLabel,
  value,
  defaultValue = "",
  onValueChange,
  onDerivedChange,
  transform = defaultTransform,
  placeholder,
  derivedPlaceholder = "auto-generated",
  className = "",
}: CarbonFlimsyProps) {
  const isControlled = value !== undefined;
  const [internalPrimary, setInternalPrimary] = useState(defaultValue);
  const primary = isControlled ? (value as string) : internalPrimary;

  const [linked, setLinked] = useState(true);
  const [stamp, setStamp] = useState<Stamp>(() => {
    const t = transform(defaultValue);
    return { text: t, gen: Array.from(t, () => 0), from: 0 };
  });
  const [live, setLive] = useState("");

  const reducedMotion = useReducedMotion();
  const stampGenRef = useRef(0);
  const prevPrimaryRef = useRef(primary);
  const uid = useId();
  const primaryId = `${uid}-primary`;
  const derivedId = `${uid}-derived`;
  const hintId = `${uid}-hint`;

  const stampDerived = useCallback((next: string, full = false) => {
    setStamp((prev) => {
      const prefixLen = full ? 0 : commonPrefixLength(prev.text, next);
      stampGenRef.current += 1;
      const gen = stampGenRef.current;
      return {
        text: next,
        gen: Array.from(next, (_, i) => (i < prefixLen ? (prev.gen[i] ?? 0) : gen)),
        from: prefixLen,
      };
    });
  }, []);

  // Re-derive whenever the primary value actually changes while linked —
  // covers both the uncontrolled onChange path and an externally controlled
  // `value` update, without duplicating the derivation logic in either handler.
  useEffect(() => {
    if (!linked) {
      prevPrimaryRef.current = primary;
      return;
    }
    if (primary === prevPrimaryRef.current) return;
    prevPrimaryRef.current = primary;
    const next = transform(primary);
    stampDerived(next);
    onDerivedChange?.(next, true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [primary, linked]);

  const handlePrimaryChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const next = e.target.value;
    if (!isControlled) setInternalPrimary(next);
    onValueChange?.(next);
  };

  const handleFlimsyChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const next = e.target.value;
    setStamp((prev) => ({ ...prev, text: next }));
    if (linked) {
      setLinked(false);
      setLive(`Detached. ${derivedLabel} no longer follows ${label}.`);
    }
    onDerivedChange?.(next, false);
  };

  const handleRelink = () => {
    const next = transform(primary);
    setLinked(true);
    stampDerived(next, true);
    setLive(`Relinked. ${derivedLabel} restored from ${label}.`);
    onDerivedChange?.(next, true);
  };

  return (
    <div
      className={`ns-cf-root flex w-full flex-col gap-1.5 ${className}`}
      data-reduced={reducedMotion || undefined}
    >
      <style>{`
.ns-cf-flimsy-box{transition:transform 340ms cubic-bezier(.34,1.56,.64,1),border-color 200ms ease,background-color 200ms ease,box-shadow 150ms ease}
.ns-cf-flimsy-box[data-linked]{transform:translate(4px,4px);border-color:var(--border);background:color-mix(in oklab,var(--ns-muted) 14%,var(--background))}
.ns-cf-flimsy-box[data-detached]{transform:translate(0,0);border-color:color-mix(in oklab,var(--foreground) 30%,transparent);background:var(--background)}
.ns-cf-flimsy-box:focus-within{border-color:var(--ns-accent);box-shadow:0 0 0 3px color-mix(in oklab,var(--ns-accent) 18%,transparent)}
.ns-cf-flimsy-input[data-linked]{color:transparent;caret-color:var(--foreground)}
.ns-cf-char{display:inline-block;animation:ns-cf-stamp 120ms ease-out both;animation-delay:var(--cf-delay,0ms)}
@keyframes ns-cf-stamp{0%{transform:translate(0,0);font-weight:600}45%{transform:translate(.4px,.4px);font-weight:500}100%{transform:translate(0,0);font-weight:400}}
.ns-cf-primary-input:focus-visible,.ns-cf-flimsy-input:focus-visible{outline:2px solid var(--ns-accent);outline-offset:2px}
.ns-cf-relink:focus-visible{outline:2px solid var(--ns-accent);outline-offset:2px}
.ns-cf-root[data-reduced] .ns-cf-char{animation:none;font-weight:400}
.ns-cf-root[data-reduced] .ns-cf-flimsy-box{transition:none}
@media (prefers-reduced-motion: reduce){
.ns-cf-char{animation:none;font-weight:400}
.ns-cf-flimsy-box{transition:none}
}
`}</style>

      <div className="flex flex-col gap-1.5">
        <label
          htmlFor={primaryId}
          className="text-[13px] font-medium tracking-tight text-foreground"
        >
          {label}
        </label>
        <input
          id={primaryId}
          type="text"
          value={primary}
          placeholder={placeholder}
          onChange={handlePrimaryChange}
          data-cf-role="primary"
          className="ns-cf-primary-input h-9 rounded-[6px] border border-border bg-background px-3 text-sm text-foreground outline-none transition-colors duration-150 placeholder:text-ns-muted/70 hover:border-foreground/25 focus:border-ns-accent"
        />
      </div>

      <div className="relative mt-1 pb-1 pr-1">
        <div
          data-linked={linked || undefined}
          data-detached={!linked || undefined}
          className="ns-cf-flimsy-box flex flex-col gap-1 rounded-[12px] border px-3 py-2"
        >
          <div className="flex items-center justify-between gap-2">
            <label
              htmlFor={derivedId}
              className="text-[11px] font-medium uppercase tracking-[0.08em] text-ns-muted"
            >
              {derivedLabel}
            </label>
            {!linked && (
              <button
                type="button"
                onClick={handleRelink}
                className="ns-cf-relink inline-flex items-center gap-1 rounded-[6px] px-1.5 py-0.5 text-[11px] font-medium text-ns-accent transition-colors hover:text-ns-accent-hover"
              >
                <svg aria-hidden="true" viewBox="0 0 12 12" className="h-[10px] w-[10px]">
                  <path
                    d="M4.6 4.6 1.8 7.4a1.7 1.7 0 0 0 2.4 2.4L7 7"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="1.3"
                    strokeLinecap="round"
                  />
                  <path
                    d="M7.4 7.4l2.8-2.8a1.7 1.7 0 0 0-2.4-2.4L5 5"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="1.3"
                    strokeLinecap="round"
                  />
                </svg>
                Relink
              </button>
            )}
          </div>

          <div className="relative">
            <input
              id={derivedId}
              type="text"
              value={stamp.text}
              placeholder={derivedPlaceholder}
              onChange={handleFlimsyChange}
              aria-describedby={hintId}
              data-linked={linked || undefined}
              className="ns-cf-flimsy-input h-7 w-full border-0 bg-transparent p-0 font-mono text-[13px] leading-7 text-foreground outline-none placeholder:text-ns-muted/70"
            />
            {linked && (
              <div
                aria-hidden="true"
                className="ns-cf-overlay pointer-events-none absolute inset-0 flex items-center overflow-hidden whitespace-nowrap font-mono text-[13px] leading-7 text-foreground"
              >
                {Array.from(stamp.text).map((ch, i) => {
                  const delay = i >= stamp.from ? (i - stamp.from) * CHAR_STAGGER_MS : 0;
                  return (
                    <span
                      key={`${i}-${stamp.gen[i] ?? 0}`}
                      className="ns-cf-char"
                      style={{ "--cf-delay": `${delay}ms` } as Vars}
                    >
                      {ch === " " ? " " : ch}
                    </span>
                  );
                })}
              </div>
            )}
          </div>
        </div>
      </div>

      <p id={hintId} className="text-[12px] leading-4 text-ns-muted">
        Auto-generated from {label}. Editing detaches it.
      </p>

      <span role="status" aria-live="polite" className="sr-only">
        {live}
      </span>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// SlumpMouldDrape — a content-reveal/settle moment built on kiln-slumping in
// warm glass work: a flat glass blank heated to its slumping range sags
// purely under gravity over a mould, the centre drooping first (least
// supported) while the drape spreads outward toward the rim as heat and time
// progress. It's a slow, staggered viscous deformation, never a snap or a
// bounce — the whole point is the visible LAG between the centre and the
// edges, not a uniformly eased reveal.
//
// The profile is a pure function of elapsed time: N=32 sample points, each
// following y_i(t) = mould(x_i) * (1 - exp(-(t - delay_i) / TAU)), where
// delay_i grows with distance from centre (0 at centre, DELAY_EDGE_S at the
// rim). No physics state carries frame to frame, which is what makes the
// reduced-motion freeze frame a single function call rather than a replay.
// ---------------------------------------------------------------------------

const N_POINTS = 32;
const DRAPE_S = 4.5; // flat -> fully conformed
const HOLD_S = 1.5; // fully slumped, motionless, exact conformity
const RESET_S = 0.4; // lifts back to flat (a fresh blank going into the kiln)
const CYCLE_S = DRAPE_S + HOLD_S + RESET_S; // 6.4s, repeats indefinitely
const TAU_S = 1.0;
const DELAY_EDGE_S = 1.8; // delay at the outermost sample point, 0 at centre
const MAX_DROOP_FRAC = 0.3; // of the container's smaller dimension
const STATIC_TIME_S = 2.5; // reduced-motion freeze: centre conformed, edges still lagging

function mouldDepth(x: number, depth: number): number {
  // shallow-bowl reference curve: 0 at both rims, depth at centre
  return (depth * (1 - Math.cos(2 * Math.PI * x))) / 2;
}

function delayAt(x: number): number {
  return DELAY_EDGE_S * (Math.abs(x - 0.5) / 0.5);
}

// the profile's y-offset (px, downward-positive) for sample x at drape-phase
// elapsed time; only valid while phaseT < DRAPE_S.
function draping(x: number, elapsed: number, depth: number): number {
  const delay = delayAt(x);
  if (elapsed <= delay) return 0;
  return mouldDepth(x, depth) * (1 - Math.exp(-(elapsed - delay) / TAU_S));
}

export interface SlumpMouldDrapeProps {
  /** ambient idle loop (drape -> hold -> reset -> repeat) vs. a one-shot
   * reveal that plays once and holds its settled state forever. @default true */
  loop?: boolean;
  className?: string;
}

export function SlumpMouldDrape({
  loop = true,
  className = "",
}: SlumpMouldDrapeProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    // -- token-derived ink, read at mount and re-derived on theme flip ------
    let fg = "rgb(237,237,237)";
    let border = "rgba(237,237,237,0.11)";
    let dark = true;
    const readTokens = () => {
      dark = document.documentElement.classList.contains("dark");
      const cs = getComputedStyle(document.documentElement);
      fg = cs.getPropertyValue("--foreground").trim() || fg;
      border = cs.getPropertyValue("--border").trim() || border;
    };
    readTokens();

    // -- hot-path state: locals only, never React state ---------------------
    let w = 0;
    let h = 0;
    let dpr = 1;
    let sized = false;
    let paused = false;
    let reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    let baselineY = 0;
    let depth = 0;
    let lineWidth = 1.4;
    let mouldLineWidth = 1;

    const xAt = (i: number) => i / (N_POINTS - 1);

    // profile y-offset (downward-positive, px) for sample index i at a given
    // absolute elapsed time within one cycle (or clamped past the hold end
    // when !loop).
    const profileOffset = (i: number, phaseT: number) => {
      const x = xAt(i);
      if (phaseT < DRAPE_S) return draping(x, phaseT, depth);
      if (phaseT < DRAPE_S + HOLD_S) return mouldDepth(x, depth); // exact conformity
      const resetT = phaseT - DRAPE_S - HOLD_S;
      const frac = Math.min(1, resetT / RESET_S);
      const eased = frac * frac * (3 - 2 * frac); // smoothstep lift
      return mouldDepth(x, depth) * (1 - eased);
    };

    const drawPolyline = (getY: (i: number) => number, useCurve: boolean) => {
      ctx.beginPath();
      for (let i = 0; i < N_POINTS; i++) {
        const px = (xAt(i) * w);
        const py = getY(i);
        if (i === 0) {
          ctx.moveTo(px, py);
        } else if (useCurve) {
          const prevX = xAt(i - 1) * w;
          const prevY = getY(i - 1);
          const midX = (prevX + px) / 2;
          const midY = (prevY + py) / 2;
          ctx.quadraticCurveTo(prevX, prevY, midX, midY);
        } else {
          ctx.lineTo(px, py);
        }
      }
      // finish the last curve segment to the final point
      if (useCurve) {
        ctx.lineTo(xAt(N_POINTS - 1) * w, getY(N_POINTS - 1));
      }
      ctx.stroke();
    };

    const draw = (phaseT: number) => {
      if (!sized) return;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);

      // mould reference contour — a fixed, non-load-bearing target line the
      // profile drapes toward; --border only, never a fill or the "arrived"
      // signal itself (that's read from geometric conformity, not colour).
      ctx.strokeStyle = border;
      ctx.lineWidth = mouldLineWidth;
      ctx.globalAlpha = 1;
      drawPolyline((i) => baselineY + mouldDepth(xAt(i), depth), true);

      // glass profile
      ctx.strokeStyle = fg;
      ctx.lineWidth = lineWidth;
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      drawPolyline((i) => baselineY + profileOffset(i, phaseT), true);
    };

    const resize = () => {
      const rect = root.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      if (w < 2 || h < 2) {
        sized = false;
        return;
      }
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
      const minDim = Math.min(w, h);
      depth = MAX_DROOP_FRAC * minDim;
      baselineY = h * 0.5 - depth * 0.5;
      lineWidth = Math.max(1.4, 0.007 * minDim);
      // light theme's --border reads at ~1.1:1 — a heavier stroke (same
      // token, not a different one) keeps the mould contour legible as a
      // target line rather than a different-weight rule change per theme.
      mouldLineWidth = Math.max(1, 0.0045 * minDim) * (dark ? 1 : 1.6);
      sized = true;
    };

    const renderStatic = () => {
      draw(STATIC_TIME_S);
    };

    let raf = 0;
    let start = 0;
    const loopFrame = (now: number) => {
      if (!start) start = now;
      const elapsed = (now - start) / 1000;
      const phaseT = loop
        ? elapsed % CYCLE_S
        : Math.min(elapsed, DRAPE_S + HOLD_S);
      draw(phaseT);
      if (!paused) raf = requestAnimationFrame(loopFrame);
    };

    const stopLoop = () => {
      if (raf) cancelAnimationFrame(raf);
      raf = 0;
    };

    const startLoop = () => {
      stopLoop();
      if (paused || !sized) return;
      if (reduced) {
        renderStatic();
        return;
      }
      start = 0;
      raf = requestAnimationFrame(loopFrame);
    };

    resize();

    const ro = new ResizeObserver(() => {
      resize();
      if (reduced) renderStatic();
    });
    ro.observe(root);

    const onThemeChange = () => {
      readTokens();
      resize(); // mould stroke weight depends on the dark/light read above
      if (reduced) draw(STATIC_TIME_S);
    };
    const mo = new MutationObserver(onThemeChange);
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class", "data-theme"],
    });
    const colorScheme = window.matchMedia("(prefers-color-scheme: dark)");
    colorScheme.addEventListener("change", onThemeChange);

    const reducedMq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const onReducedChange = () => {
      reduced = reducedMq.matches;
      startLoop();
    };
    reducedMq.addEventListener("change", onReducedChange);

    const onVisibility = () => {
      paused = document.hidden;
      startLoop();
    };
    document.addEventListener("visibilitychange", onVisibility);

    let io: IntersectionObserver | undefined;
    if ("IntersectionObserver" in window) {
      io = new IntersectionObserver((entries) => {
        const entry = entries[0];
        if (!entry) return;
        paused = !entry.isIntersecting || document.hidden;
        startLoop();
      });
      io.observe(root);
    }

    startLoop();

    return () => {
      stopLoop();
      ro.disconnect();
      mo.disconnect();
      colorScheme.removeEventListener("change", onThemeChange);
      reducedMq.removeEventListener("change", onReducedChange);
      document.removeEventListener("visibilitychange", onVisibility);
      io?.disconnect();
    };
  }, [loop]);

  return (
    <div
      ref={rootRef}
      className={`relative h-full w-full overflow-hidden ${className}`}
    >
      <canvas ref={canvasRef} aria-hidden className="block h-full w-full" />
    </div>
  );
}

"use client";

// ---------------------------------------------------------------------------
// SorterPocketRoute — an ambient processing/organizing loader modeled on a
// Hollerith tabulating-machine card sorter's CHUTE, not its brush reader.
// Cards drop single-file down a center track; at a fixed gate a flap swings
// to one of five headings and the card curves off with it into a numbered
// pocket below, landing on that pocket's growing stack. The read event
// (round 9's jacquard-card-chain territory — a needle bank resolving a
// punched pattern) is deliberately absent here: nothing is "read" on
// screen, there is no bank of needles or pips, and the visible subject is
// entirely the routing mechanism — the gate's decisive swing and the
// pockets filling unevenly over time, never a card being decoded.
//
// ROUTING. Pocket assignment cycles a fixed period-17 sequence (never a
// runtime Math.random pick) weighted so the center pocket receives roughly
// 2x an outer pocket's share — uneven fill is part of what reads "alive".
// The sequence is long enough that it doesn't visibly repeat within a
// short viewing window (17 cards * 1.1s feed ~= 18.7s per full cycle).
//
// TIMING. One card feeds every 1.1s. A card's full journey — 300ms
// straight drop to the gate, then 380ms ease-in-out gate-swing + curve
// into its pocket — takes 680ms, safely inside the 1.1s feed interval, so
// exactly one card is ever mid-journey at a time and a viewer can follow
// one card start-to-finish without a second card's motion overlapping it.
// The gate flap itself swings in the same 380ms window and eases back to
// its neutral heading between cards, so the mechanism reads as "deciding"
// rather than merely decorating the card's own motion.
//
// POCKETS. Each pocket holds a rolling window of 14 visible cards, newest
// on top; a 15th arrival fades the bottom (oldest) card out over 260ms as
// the new one lands — a continuous rolling loop with no visible restart.
// Stack rise is 3px/card, capped so the tallest pocket never exceeds 70%
// of the bin's height (older cards compress toward that cap rather than
// spilling out of the bin).
//
// TOKENS. Card fill is --background, card outline --foreground at 60%
// opacity (color-mix, no literal). Pocket bin outlines are --border — a
// separator, never a fill. Stacked cards inside a pocket step from 25% to
// 55% --foreground mixed into --background, oldest to newest, so pocket
// depth reads as a value gradient. No --ns-accent anywhere: the gate's
// heading is conveyed purely by its swing angle and the card's curved
// path, never by a color cue. All colors are CSS custom properties
// referenced directly (var(...) / color-mix(...)) — nothing is read via
// getComputedStyle because nothing here needs a numeric color value, only
// a token reference the browser resolves itself.
// ---------------------------------------------------------------------------

import { useEffect, useId, useMemo, useRef, useState } from "react";

const POCKET_COUNT = 5;
// period-17 pseudo-random routing sequence, center pocket (index 2) weighted
// roughly 2x an outer pocket's share (6 hits vs ~3 each for the outer four)
const ROUTE_PATTERN = [2, 0, 3, 2, 4, 1, 2, 0, 3, 2, 1, 4, 2, 0, 3, 1, 2] as const;
const GATE_ANGLES = [-60, -30, 0, 30, 60] as const; // deg, pocket 0..4

const FEED_MS = 1100;
const DROP_MS = 300;
const ROUTE_MS = 380;
const POCKET_CAPACITY = 14;
const FADE_MS = 260;
const RISE_PX = 3;
const MAX_RISE_FRAC = 0.7; // of bin height

const ROUTE_EASE = "cubic-bezier(0.4, 0, 0.2, 1)"; // ease-in-out

interface FlightCard {
  id: number;
  pocket: number;
  phase: "drop" | "route";
}

interface LandedCard {
  id: number;
  removing: boolean;
}

export interface SorterPocketRouteProps {
  /** text announced via the component's own aria-live region */
  label?: string;
  /** freeze on the reduced-motion tableau regardless of the OS setting */
  paused?: boolean;
  /** extra classes merged onto the rendered root element */
  className?: string;
  style?: React.CSSProperties;
}

function useReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

// hand-authored STATIC_PHASE: one card frozen mid-chute at the 60%-through
// point of its gate-swing (its translate sits between the vertical drop
// line and its pocket's horizontal offset, so it reads angled, neither
// vertical nor horizontal), and five pockets showing a distinctly uneven
// fill — never all-empty, never all-equal.
const STATIC_POCKET_COUNTS = [4, 9, 3, 11, 6];
const STATIC_FROZEN_POCKET = 4;
const STATIC_PROGRESS = 0.6;

export function SorterPocketRoute({
  label = "Sorting",
  paused = false,
  className = "",
  style,
}: SorterPocketRouteProps) {
  const uid = useId();
  const reducedMotion = useReducedMotion();
  const frozen = reducedMotion || paused;

  const rootRef = useRef<HTMLDivElement>(null);
  const [size, setSize] = useState({ w: 320, h: 220 });

  const [pockets, setPockets] = useState<LandedCard[][]>(() =>
    Array.from({ length: POCKET_COUNT }, () => []),
  );
  const [flight, setFlight] = useState<FlightCard | null>(null);
  const [gatePocket, setGatePocket] = useState<number | null>(null);

  const nextIdRef = useRef(0);
  const routeCountRef = useRef(0);
  const timersRef = useRef<Set<ReturnType<typeof setTimeout>>>(new Set());
  const addTimer = (fn: () => void, ms: number) => {
    const id = setTimeout(() => {
      timersRef.current.delete(id);
      fn();
    }, ms);
    timersRef.current.add(id);
    return id;
  };
  const clearAllTimers = () => {
    timersRef.current.forEach((id) => clearTimeout(id));
    timersRef.current.clear();
  };

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const ro = new ResizeObserver((entries) => {
      const rect = entries[0]?.contentRect;
      if (!rect || rect.width < 2 || rect.height < 2) return;
      setSize({ w: rect.width, h: rect.height });
    });
    ro.observe(root);
    return () => ro.disconnect();
  }, []);

  useEffect(() => {
    if (frozen) {
      clearAllTimers();
      setFlight(null);
      setGatePocket(null);
      return;
    }

    const spawn = () => {
      const pocket = ROUTE_PATTERN[routeCountRef.current % ROUTE_PATTERN.length]!;
      routeCountRef.current += 1;
      const id = nextIdRef.current++;
      setFlight({ id, pocket, phase: "drop" });

      addTimer(() => {
        setFlight((f) => (f && f.id === id ? { ...f, phase: "route" } : f));
        setGatePocket(pocket);
      }, DROP_MS);

      addTimer(() => {
        setFlight((f) => (f && f.id === id ? null : f));
        setGatePocket((p) => (p === pocket ? null : p));
        setPockets((prev) => {
          const next = prev.map((bin) => bin.slice());
          next[pocket]!.push({ id, removing: false });
          if (next[pocket]!.length > POCKET_CAPACITY) {
            const oldest = next[pocket]![0]!;
            oldest.removing = true;
            const oldestId = oldest.id;
            addTimer(() => {
              setPockets((p2) => {
                const n2 = p2.map((bin) => bin.slice());
                n2[pocket] = n2[pocket]!.filter((c) => c.id !== oldestId);
                return n2;
              });
            }, FADE_MS);
          }
          return next;
        });
      }, DROP_MS + ROUTE_MS);
    };

    // first card feeds immediately so the loader isn't empty at mount
    spawn();
    const interval = setInterval(spawn, FEED_MS);
    return () => {
      clearInterval(interval);
      clearAllTimers();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [frozen]);

  useEffect(() => clearAllTimers, []);

  // -------------------------------------------------------------------
  // geometry — pocket width from container width (leaves a gutter), card
  // height derived from pocket width, so the whole assembly compresses
  // together at narrow container widths rather than any piece clipping.
  // -------------------------------------------------------------------
  const geo = useMemo(() => {
    const w = size.w;
    const h = size.h;
    const pocketW = w / 5.5;
    const cardH = pocketW * 0.4;
    const cardW = pocketW * 0.72;
    const gutter = POCKET_COUNT > 1 ? (w - POCKET_COUNT * pocketW) / (POCKET_COUNT - 1) : 0;
    const pocketLeft = (i: number) => i * (pocketW + gutter);
    const pocketCenterX = (i: number) => pocketLeft(i) + pocketW / 2;
    const trackX = w / 2;
    const gateY = h * 0.32;
    const binTop = h * 0.4;
    const binHeight = h * 0.58;
    const binBottom = binTop + binHeight;
    const rise = Math.min(RISE_PX, (binHeight * MAX_RISE_FRAC) / POCKET_CAPACITY);
    return { w, h, pocketW, cardH, cardW, pocketLeft, pocketCenterX, trackX, gateY, binTop, binHeight, binBottom, rise };
  }, [size]);

  const landY = (pocket: number, indexFromBottom: number) => geo.binBottom - geo.cardH / 2 - indexFromBottom * geo.rise;

  const flightStyle = (): React.CSSProperties | null => {
    if (!flight) return null;
    const startX = geo.trackX;
    const startY = geo.cardH / 2;
    if (flight.phase === "drop") {
      return {
        left: startX - geo.cardW / 2,
        top: 0,
        width: geo.cardW,
        height: geo.cardH,
        transform: `translateY(${geo.gateY - geo.cardH / 2}px) rotate(0deg)`,
        transition: `transform ${DROP_MS}ms linear`,
      };
    }
    const targetX = geo.pocketCenterX(flight.pocket);
    const targetY = landY(flight.pocket, pockets[flight.pocket]?.length ?? 0);
    return {
      left: startX - geo.cardW / 2,
      top: 0,
      width: geo.cardW,
      height: geo.cardH,
      transform: `translate(${targetX - startX}px, ${targetY}px) rotate(-6deg)`,
      transition: `transform ${ROUTE_MS}ms ${ROUTE_EASE}`,
    };
  };

  const frozenFlightStyle = (): React.CSSProperties => {
    const startX = geo.trackX;
    const targetX = geo.pocketCenterX(STATIC_FROZEN_POCKET);
    const targetY = landY(STATIC_FROZEN_POCKET, STATIC_POCKET_COUNTS[STATIC_FROZEN_POCKET]!);
    const t = STATIC_PROGRESS;
    return {
      left: startX - geo.cardW / 2,
      top: 0,
      width: geo.cardW,
      height: geo.cardH,
      transform: `translate(${(targetX - startX) * t}px, ${geo.gateY - geo.cardH / 2 + (targetY - (geo.gateY - geo.cardH / 2)) * t}px) rotate(${-6 * t}deg)`,
    };
  };

  const gateAngle = frozen
    ? GATE_ANGLES[STATIC_FROZEN_POCKET]! * STATIC_PROGRESS
    : gatePocket === null
      ? 0
      : GATE_ANGLES[gatePocket]!;

  const activePockets: LandedCard[][] = frozen
    ? STATIC_POCKET_COUNTS.map((n) =>
        Array.from({ length: n }, (_, i) => ({ id: i, removing: false })),
      )
    : pockets;

  return (
    <div
      ref={rootRef}
      role="status"
      aria-live="polite"
      className={`relative h-[220px] w-full select-none ${className}`}
      style={style}
    >
      <span className="sr-only">{label}</span>
      <div className="relative h-full w-full" aria-hidden="true">
        {/* gate + flap — the mechanism, not the card, is the decision-maker */}
        <div
          className="absolute left-1/2 -translate-x-1/2"
          style={{ top: geo.gateY - 1 }}
        >
          <div
            className="h-[2px] origin-left rounded-full"
            style={{
              width: geo.pocketW * 0.55,
              backgroundColor: "var(--foreground)",
              transform: `rotate(${gateAngle}deg)`,
              transition: frozen ? "none" : `transform ${ROUTE_MS}ms ${ROUTE_EASE}`,
            }}
          />
        </div>

        {/* flying card */}
        {frozen ? (
          <div
            className="absolute rounded-[2px] border"
            style={{
              ...frozenFlightStyle(),
              backgroundColor: "var(--background)",
              borderColor: "color-mix(in srgb, var(--foreground) 60%, transparent)",
            }}
          />
        ) : (
          flight && (
            <div
              className="absolute rounded-[2px] border"
              style={{
                ...(flightStyle() as React.CSSProperties),
                backgroundColor: "var(--background)",
                borderColor: "color-mix(in srgb, var(--foreground) 60%, transparent)",
              }}
            />
          )
        )}

        {/* pockets row */}
        <div className="absolute inset-x-0" style={{ top: geo.binTop, height: geo.binHeight }}>
          {Array.from({ length: POCKET_COUNT }).map((_, p) => (
            <div
              key={p}
              className="absolute rounded-[3px] border"
              style={{
                left: geo.pocketLeft(p),
                width: geo.pocketW,
                top: 0,
                height: geo.binHeight,
                borderColor: "var(--border)",
              }}
            >
              {activePockets[p]!.map((card, i) => {
                const pct = 25 + (30 * i) / Math.max(1, POCKET_CAPACITY - 1);
                return (
                  <div
                    key={`${uid}-${p}-${card.id}`}
                    className="absolute rounded-[1px]"
                    style={{
                      left: (geo.pocketW - geo.cardW) / 2,
                      width: geo.cardW,
                      height: geo.cardH,
                      bottom: i * geo.rise,
                      backgroundColor: `color-mix(in srgb, var(--foreground) ${pct}%, var(--background))`,
                      opacity: card.removing ? 0 : 1,
                      transition: card.removing ? `opacity ${FADE_MS}ms ease` : undefined,
                    }}
                  />
                );
              })}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

SorterPocketRoute.displayName = "SorterPocketRoute";

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// SpallFace — a card-scale background texture panel modelling frost (freeze-
// thaw) weathering of a porous rock/masonry face: water in surface pores
// freezes, expands, and fatigues the near-surface layer until a flake
// (spall) detaches at once, exposing fresh material beneath. Two mechanics
// run independently on the same cell grid:
//
// 1) CONVEYOR — the entire sampled field drifts slowly upward. Rows are
//    stored in a buffer one taller than the visible span; a fractional pixel
//    offset slides everything smoothly, and once that offset crosses a full
//    cell height the oldest (top) row is shifted off — permanently exiting
//    the visible frame — and a brand-new, unweathered row is pushed in at
//    the bottom. This is real material transport (fresh rock entering one edge,
//    weathered/spalled rock permanently leaving the other), not a fixed
//    surface that fills up and stops — the property that keeps the loop
//    genuinely unbounded rather than converging on a static pitted texture
//    (see registry/loud/edm-crater-field, a steady-state field with no net
//    transport — the deliberate differentiator from this component).
//
// 2) SPALL EVENTS — on a random 1.3-2s cadence, one small cell block is
//    picked and enters a 350ms lift -> tip -> fall departure: the flake
//    keeps the patch's OLD (pre-event) colour as it lifts and tips outward,
//    fades while falling off-frame, and the instant it fully detaches (the
//    fall stage begins) the patch underneath resets to a fresh-exposure
//    state and starts glowing. That glow (an exponential decay toward the
//    ambient base tone) is what "brightens immediately, then weathers over
//    the following several seconds" looks like — a real recession cycle of
//    ~0.1-2mm/yr compressed to an illustrative ~40s per patch, documented
//    here rather than literally timed per cell.
//
// Every cell's rendered tone is a single 3-stop lerp across --background ->
// --ns-muted -> --foreground, driven by a base tone plus the exposure glow
// plus a fixed per-cell grain value (a smooth banded function of the row's
// own generation index, so strata form and ride the conveyor coherently
// instead of flickering as uncorrelated per-cell noise). Because both
// the "fresh" and "ambient" ends of that lerp are the SAME two tokens in
// both themes, a fresh patch is automatically brighter in dark theme
// (moving toward --foreground = lighter ink there) and automatically reads
// as a darker, more structured patch in light theme (moving toward
// --foreground = darker ink there) with no theme branch anywhere — the
// inversion the spec calls for falls straight out of the token roles.
// ---------------------------------------------------------------------------

interface Cell {
  grain: number; // fixed per-cell tone jitter, set once at row creation
  sinceExposure: number; // seconds since this cell last freshly spalled
}

interface Flake {
  cell: Cell;
  sizePx: number;
  tipDirX: number; // -1..1, lateral tip direction
  startTime: number; // ms, performance.now() at spawn
  exposed: boolean;
  capturedT: number; // the patch's tone at the instant it detached, carried by the flake
  rowIdx: number;
  colIdx: number;
}

export interface SpallFaceProps {
  /** extra classes merged onto the rendered root element */
  className?: string;
}

type RGB = [number, number, number];

function parseColor(raw: string): RGB | null {
  const s = raw.trim();
  if (s.startsWith("#")) {
    let hex = s.slice(1);
    if (hex.length === 3) hex = hex.split("").map((c) => c + c).join("");
    if (hex.length < 6) return null;
    const r = parseInt(hex.slice(0, 2), 16);
    const g = parseInt(hex.slice(2, 4), 16);
    const b = parseInt(hex.slice(4, 6), 16);
    return Number.isNaN(r + g + b) ? null : [r, g, b];
  }
  const m = s.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
}

function mixRGB(a: RGB, b: RGB, t: number): RGB {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// -- grid + tone constants --------------------------------------------------
const CELLS_ACROSS = 48; // cell count along the container's SMALLER dimension
const BASE_T = 0.14; // ambient (unweathered) tone position on the 0..1 ramp
const BUMP_AMP = 0.6; // how far a fresh exposure pushes the tone up the ramp
const TAU_EXPOSURE = 9; // s, exponential decay constant of the fresh-glow

// -- initial scatter (t0 must show varied weathering ages, not a blank face) --
const INIT_SCATTER_FRACTION = 0.025;
const INIT_SCATTER_MAX_AGE = 22; // s

// -- conveyor -----------------------------------------------------------
// full nominal 48-cell pass takes ~70s -> constant px/s speed regardless of
// container aspect, since cellPx itself scales off the smaller dimension.
// Fast enough that a band (see bandFor()) visibly advances within 2.5s.
const DRIFT_CELLS_PER_SEC = 48 / 70;

// -- spall events ---------------------------------------------------------
const SPALL_MIN_INTERVAL = 1300; // ms
const SPALL_MAX_INTERVAL = 2000; // ms
const FLAKE_LIFT_END = 120; // ms
const FLAKE_TIP_END = 220; // ms — exposure resets the instant fall begins
const FLAKE_DURATION = 350; // ms
const FLAKE_SIZE_MIN_FRAC = 0.04; // of container's smaller dimension
const FLAKE_SIZE_MAX_FRAC = 0.07;
const MAX_CONCURRENT_FLAKES = 3;
const EDGE_MARGIN_ROWS = 2; // keep new flakes clear of the buffer's top/bottom

const BUCKETS = 16;
const DT_MAX = 1 / 30;

// reduced-motion freeze frame: a flake mid-fall (past lift+tip, visibly
// departed, its patch already brightening) plus older weathering patches
// elsewhere — shows fresh / aging / mid-spall in one still.
const STATIC_FLAKE_ELAPSED = 280; // ms — inside the fall stage
const STATIC_AGES = [1.4, 5.5, 13, 21]; // s — scattered "now weathering" patches

// real rock faces have bedding, not uniform per-cell noise — a row's grain
// is a smooth function of its own generation index (two incommensurate
// sines), so adjacent rows correlate into horizontal strata a few cells
// wide; per-cell jitter on top keeps each band from looking flat. The bands
// are what makes the upward conveyor drift legible: the eye tracks a band,
// not a single random cell.
const BAND_JITTER = 0.02;
function bandFor(seq: number): number {
  return 0.09 * Math.sin(seq * 0.34) + 0.05 * Math.sin(seq * 0.13 + 2.1);
}

function makeRow(cols: number, rand: () => number, seq: number): Cell[] {
  const band = bandFor(seq);
  return Array.from({ length: cols }, () => ({
    grain: band + (rand() * 2 - 1) * BAND_JITTER,
    sinceExposure: 9999,
  }));
}

export function SpallFace({ className = "" }: SpallFaceProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    let reduced = mq.matches;
    const rand = mulberry32(0x5fa11ace);

    // -- token-derived ink, re-derived on theme class change -----------
    let bg: RGB = [10, 10, 10];
    let muted: RGB = [143, 143, 143];
    let fg: RGB = [237, 237, 237];
    const derive = () => {
      const cs = getComputedStyle(document.documentElement);
      bg = parseColor(cs.getPropertyValue("--background")) ?? bg;
      muted = parseColor(cs.getPropertyValue("--ns-muted")) ?? muted;
      fg = parseColor(cs.getPropertyValue("--foreground")) ?? fg;
    };
    derive();

    const colorAt = (t: number): RGB => {
      const c = Math.min(1, Math.max(0, t));
      return c < 0.5 ? mixRGB(bg, muted, c * 2) : mixRGB(muted, fg, (c - 0.5) * 2);
    };

    let w = 0;
    let h = 0;
    let dpr = 1;
    let cellPx = 8;
    let cols = 0;
    let visibleRows = 0;
    let rowsBuf: Cell[][] = []; // length visibleRows + 1, index 0 = incoming buffer row
    let rowSeq = 0; // generation counter feeding bandFor(), advances one per new row
    let conveyorPix = 0;
    let flakes: Flake[] = [];
    let nextSpallAt = 0;
    let raf = 0;
    let last = 0;
    let visible = true;

    const buildGrid = () => {
      const minDim = Math.max(1, Math.min(w, h));
      cellPx = Math.max(3, minDim / CELLS_ACROSS);
      cols = Math.max(1, Math.ceil(w / cellPx));
      visibleRows = Math.max(1, Math.ceil(h / cellPx));
      rowSeq = 0;
      rowsBuf = Array.from({ length: visibleRows + 1 }, () => makeRow(cols, rand, rowSeq++));
      // seed varied weathering ages so t0 isn't a blank, uniformly fresh face
      for (const row of rowsBuf) {
        for (const cell of row) {
          if (rand() < INIT_SCATTER_FRACTION) cell.sinceExposure = rand() * INIT_SCATTER_MAX_AGE;
        }
      }
      conveyorPix = 0;
      flakes = [];
    };

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      w = Math.max(1, rect.width);
      h = Math.max(1, rect.height);
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      buildGrid();
    };

    const spawnFlake = (now: number) => {
      if (flakes.length >= MAX_CONCURRENT_FLAKES) return;
      const lastIdx = rowsBuf.length - 1;
      const rowIdx = EDGE_MARGIN_ROWS + Math.floor(rand() * Math.max(1, lastIdx - EDGE_MARGIN_ROWS * 2));
      const colIdx = Math.floor(rand() * cols);
      const row = rowsBuf[rowIdx];
      const cell = row?.[colIdx];
      if (!cell) return;
      const minDim = Math.min(w, h);
      const sizePx = minDim * (FLAKE_SIZE_MIN_FRAC + rand() * (FLAKE_SIZE_MAX_FRAC - FLAKE_SIZE_MIN_FRAC));
      const bump = Math.exp(-cell.sinceExposure / TAU_EXPOSURE) * BUMP_AMP;
      const capturedT = Math.min(1, Math.max(0, BASE_T + bump + cell.grain));
      flakes.push({
        cell,
        sizePx,
        tipDirX: rand() < 0.5 ? -1 : 1,
        startTime: now,
        exposed: false,
        capturedT,
        rowIdx,
        colIdx,
      });
    };

    const exposePatch = (rowIdx: number, colIdx: number, radiusCells: number) => {
      for (let ry = rowIdx - radiusCells; ry <= rowIdx + radiusCells; ry++) {
        const row = rowsBuf[ry];
        if (!row) continue;
        for (let rx = colIdx - radiusCells; rx <= colIdx + radiusCells; rx++) {
          const cell = row[rx];
          if (cell) cell.sinceExposure = 0;
        }
      }
    };

    const drawFace = (now: number, staticFlakeElapsed: number | null) => {
      ctx.clearRect(0, 0, w, h);
      const frac = conveyorPix;

      const buckets: { x: number; y: number }[][] = Array.from({ length: BUCKETS }, () => []);
      for (let i = 0; i < rowsBuf.length; i++) {
        const row = rowsBuf[i];
        if (!row) continue;
        const y = i * cellPx - frac;
        if (y > h || y + cellPx < 0) continue;
        for (let c = 0; c < row.length; c++) {
          const cell = row[c];
          if (!cell) continue;
          const bump = Math.exp(-cell.sinceExposure / TAU_EXPOSURE) * BUMP_AMP;
          const t = Math.min(1, Math.max(0, BASE_T + bump + cell.grain));
          const bucket = Math.round(t * (BUCKETS - 1));
          buckets[bucket]?.push({ x: c * cellPx, y });
        }
      }
      for (let b = 0; b < BUCKETS; b++) {
        const rects = buckets[b];
        if (!rects || rects.length === 0) continue;
        const [r, g, bl] = colorAt(b / (BUCKETS - 1));
        ctx.fillStyle = `rgb(${r | 0},${g | 0},${bl | 0})`;
        ctx.beginPath();
        for (const rect of rects) ctx.rect(rect.x, rect.y, cellPx + 0.5, cellPx + 0.5);
        ctx.fill();
      }

      const drawFlake = (fl: Flake, elapsed: number) => {
        let lift: number;
        let rotDeg: number;
        let alpha = 1;
        if (elapsed <= FLAKE_LIFT_END) {
          const lt = elapsed / FLAKE_LIFT_END;
          lift = lt * fl.sizePx * 0.35;
          rotDeg = lt * 8;
        } else if (elapsed <= FLAKE_TIP_END) {
          const tt = (elapsed - FLAKE_LIFT_END) / (FLAKE_TIP_END - FLAKE_LIFT_END);
          lift = fl.sizePx * 0.35 + tt * fl.sizePx * 0.15;
          rotDeg = 8 + tt * 30;
        } else {
          const ft = Math.min(1, (elapsed - FLAKE_TIP_END) / (FLAKE_DURATION - FLAKE_TIP_END));
          lift = fl.sizePx * 0.5 + ft * ft * fl.sizePx * 2.4;
          rotDeg = 38 + ft * 55;
          alpha = 1 - ft;
        }
        const [r, g, bl] = colorAt(fl.capturedT);
        // rides the same conveyor coordinates as the grid, not a frozen
        // spawn-time pixel — a row shift mid-flight must not desync the
        // flake from the patch it is exposing.
        const x = (fl.colIdx + 0.5) * cellPx;
        const y = (fl.rowIdx + 0.5) * cellPx - conveyorPix;
        ctx.save();
        ctx.globalAlpha = Math.max(0, alpha);
        ctx.translate(x + fl.tipDirX * lift * 0.6, y - lift);
        ctx.rotate((rotDeg * fl.tipDirX * Math.PI) / 180);
        ctx.fillStyle = `rgb(${r | 0},${g | 0},${bl | 0})`;
        ctx.fillRect(-fl.sizePx / 2, -fl.sizePx / 2, fl.sizePx, fl.sizePx);
        ctx.restore();
      };

      if (staticFlakeElapsed != null && flakes[0]) {
        drawFlake(flakes[0], staticFlakeElapsed);
      } else {
        for (const fl of flakes) drawFlake(fl, now - fl.startTime);
      }
      ctx.globalAlpha = 1;
    };

    const step = (dt: number, now: number) => {
      for (const row of rowsBuf) {
        for (const cell of row) cell.sinceExposure += dt;
      }

      // upward drift: bottom buffer row is the incoming fresh rock,
      // top row is what permanently exits the visible frame.
      conveyorPix += DRIFT_CELLS_PER_SEC * cellPx * dt;
      while (conveyorPix >= cellPx) {
        conveyorPix -= cellPx;
        rowsBuf.shift();
        rowsBuf.push(makeRow(cols, rand, rowSeq++));
        // every row index shifts down by one — an in-flight flake must
        // track the same cell it was spawned over, not drift a row stale.
        for (const fl of flakes) fl.rowIdx -= 1;
      }
      flakes = flakes.filter((fl) => fl.rowIdx >= 0);

      if (now >= nextSpallAt) {
        spawnFlake(now);
        nextSpallAt = now + SPALL_MIN_INTERVAL + rand() * (SPALL_MAX_INTERVAL - SPALL_MIN_INTERVAL);
      }

      for (const fl of flakes) {
        const elapsed = now - fl.startTime;
        if (!fl.exposed && elapsed >= FLAKE_TIP_END) {
          const radiusCells = Math.max(1, Math.round(fl.sizePx / (2 * cellPx)));
          exposePatch(fl.rowIdx, fl.colIdx, radiusCells);
          fl.exposed = true;
        }
      }
      flakes = flakes.filter((fl) => now - fl.startTime < FLAKE_DURATION);
    };

    const loop = (now: number) => {
      const dt = last ? Math.min(DT_MAX, (now - last) / 1000) : 1 / 60;
      last = now;
      step(dt, now);
      drawFace(now, null);
      raf = requestAnimationFrame(loop);
    };

    const wake = () => {
      if (raf === 0 && !reduced && visible) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const drawStatic = () => {
      const rowIdx = Math.max(EDGE_MARGIN_ROWS, Math.floor(rowsBuf.length / 2));
      const colIdx = Math.floor(cols / 2);
      const row = rowsBuf[rowIdx];
      const cell = row?.[colIdx];
      let staticFlake: Flake | null = null;
      if (cell) {
        // the flake carries the patch's OLD (ambient) tone as it departs...
        const capturedT = Math.min(1, Math.max(0, BASE_T + cell.grain));
        cell.sinceExposure = 0.15; // ...while the patch underneath is already exposed, brightening
        const minDim = Math.min(w, h);
        staticFlake = {
          cell,
          sizePx: minDim * (FLAKE_SIZE_MIN_FRAC + FLAKE_SIZE_MAX_FRAC) * 0.5,
          tipDirX: 1,
          startTime: 0,
          exposed: true,
          capturedT,
          rowIdx,
          colIdx,
        };
      }
      // older, now-weathering patches scattered elsewhere on the face
      let ai = 0;
      for (const r of rowsBuf) {
        for (const c of r) {
          if (c === cell) continue;
          if (rand() < 0.006 && ai < STATIC_AGES.length) {
            c.sinceExposure = STATIC_AGES[ai] ?? c.sinceExposure;
            ai++;
          }
        }
      }
      flakes = staticFlake ? [staticFlake] : [];
      drawFace(0, STATIC_FLAKE_ELAPSED);
    };

    resize();
    if (reduced) {
      drawStatic();
    } else {
      nextSpallAt = performance.now() + SPALL_MIN_INTERVAL + rand() * (SPALL_MAX_INTERVAL - SPALL_MIN_INTERVAL);
      raf = requestAnimationFrame(loop);
    }

    const ro = new ResizeObserver(() => {
      resize();
      if (reduced) drawStatic();
    });
    ro.observe(canvas);

    const mo = new MutationObserver(() => {
      derive();
      // if the loop is currently paused (tab hidden / off-screen) nothing
      // will repaint on its own — force one frame so a theme flip never
      // leaves a stale-theme frame sitting until the loop wakes.
      if (reduced) drawStatic();
      else if (raf === 0) drawFace(performance.now(), null);
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    const onReducedChange = () => {
      reduced = mq.matches;
      if (reduced) {
        cancelAnimationFrame(raf);
        raf = 0;
        buildGrid();
        drawStatic();
      } else {
        wake();
      }
    };
    mq.addEventListener("change", onReducedChange);

    const onVisibility = () => {
      visible = document.visibilityState === "visible";
      if (visible) wake();
      else {
        cancelAnimationFrame(raf);
        raf = 0;
      }
    };
    document.addEventListener("visibilitychange", onVisibility);

    const io = new IntersectionObserver(
      (entries) => {
        const entry = entries[0];
        if (!entry) return;
        visible = entry.isIntersecting && document.visibilityState === "visible";
        if (visible) wake();
        else {
          cancelAnimationFrame(raf);
          raf = 0;
        }
      },
      { threshold: 0.01 }
    );
    io.observe(canvas);

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      mo.disconnect();
      io.disconnect();
      mq.removeEventListener("change", onReducedChange);
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, []);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden
      className={`block h-full w-full ${className}`}
    />
  );
}

SpallFace.displayName = "SpallFace";

export default SpallFace;

"use client";

import { useLayoutEffect, useRef, useState } from "react";

// 8 sub-row block-fraction glyphs, 1/8 full to 8/8 full
const BLOCKS = ["▁", "▂", "▃", "▄", "▅", "▆", "▇", "█"];
const ROWS = 8;
const COL_W = 1; // ch, one glyph per column
const COL_GAP = 0.6; // ch, whitespace between columns

export interface RampTraceProps {
  /** the series to plot; needs at least one value */
  data: number[];
  /** accessible name for each column, e.g. "Revenue"; used in per-option labels */
  label?: string;
  /** formats a raw value for the in-grid readout and accessible names */
  valueFormat?: (value: number) => string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function RampTrace({
  data,
  label = "value",
  valueFormat = (v) => v.toLocaleString(),
  className = "",
}: RampTraceProps) {
  const series = data.length ? data : [0];
  const min = Math.min(...series);
  const max = Math.max(...series);
  const range = max - min;
  const norm = series.map((v) => (range === 0 ? 0.5 : (v - min) / range));

  const [hoverIdx, setHoverIdx] = useState<number | null>(null);
  const [focusIdx, setFocusIdx] = useState<number | null>(null);
  const activeIdx = hoverIdx ?? focusIdx;
  const colRefs = useRef<(HTMLDivElement | null)[]>([]);
  const containerRef = useRef<HTMLDivElement | null>(null);
  // the readout is centered on the active column's own measured position,
  // not a parallel `ch`-based pitch calculation: the readout row and the
  // bar row can differ in font-size (e.g. text-xs vs the ambient size),
  // which makes `ch` resolve to different px in each row and drift
  // linearly with column index. Measuring the real element sidesteps
  // that entirely.
  const [readoutCenter, setReadoutCenter] = useState<number | null>(null);

  useLayoutEffect(() => {
    if (activeIdx === null) {
      setReadoutCenter(null);
      return;
    }
    const update = () => {
      const col = colRefs.current[activeIdx];
      const container = containerRef.current;
      if (!col || !container) return;
      const colRect = col.getBoundingClientRect();
      const containerRect = container.getBoundingClientRect();
      setReadoutCenter(colRect.left - containerRect.left + colRect.width / 2);
    };
    update();
    window.addEventListener("resize", update);
    return () => window.removeEventListener("resize", update);
  }, [activeIdx]);

  const moveFocus = (i: number) => {
    const clamped = Math.min(series.length - 1, Math.max(0, i));
    colRefs.current[clamped]?.focus();
  };

  const onKeyDown = (e: React.KeyboardEvent) => {
    const current = focusIdx ?? 0;
    switch (e.key) {
      case "ArrowLeft":
        e.preventDefault();
        moveFocus(current - 1);
        break;
      case "ArrowRight":
        e.preventDefault();
        moveFocus(current + 1);
        break;
      case "Home":
        e.preventDefault();
        moveFocus(0);
        break;
      case "End":
        e.preventDefault();
        moveFocus(series.length - 1);
        break;
      default:
        break;
    }
  };

  const glyphFor = (i: number) => {
    const units = norm[i] * ROWS * 8;
    let fullRows = Math.floor(units / 8);
    let remainder = Math.round(units - fullRows * 8);
    if (remainder === 8) {
      fullRows = Math.min(ROWS, fullRows + 1);
      remainder = 0;
    }
    const rows: { glyph: string; kind: "bar" | "empty" }[] = [];
    for (let r = ROWS - 1; r >= 0; r--) {
      if (r < fullRows) {
        rows.push({ glyph: "█", kind: "bar" });
      } else if (r === fullRows && remainder > 0) {
        rows.push({ glyph: BLOCKS[remainder - 1], kind: "bar" });
      } else {
        rows.push({ glyph: " ", kind: "empty" });
      }
    }
    return rows;
  };

  return (
    <div ref={containerRef} className={`font-mono ${className}`}>
      <div className="relative h-[1.1em] text-xs" style={{ lineHeight: "1.1em" }}>
        {activeIdx !== null && readoutCenter !== null ? (
          <span
            aria-hidden
            className="absolute bottom-0 -translate-x-1/2 whitespace-nowrap text-ns-accent"
            style={{ left: `${readoutCenter}px` }}
          >
            {valueFormat(series[activeIdx])}
          </span>
        ) : null}
      </div>
      <div
        role="listbox"
        aria-label={label}
        aria-orientation="horizontal"
        className="flex items-end outline-none"
        style={{ gap: `${COL_GAP}ch` }}
        onKeyDown={onKeyDown}
        onBlur={(e) => {
          if (!e.currentTarget.contains(e.relatedTarget as Node)) setFocusIdx(null);
        }}
      >
        {series.map((v, i) => {
          // inversion follows hover-or-focus, but `aria-selected` and the focus
          // ring follow DOM focus alone: hovering column 3 while column 0 is
          // focused must not move the announced selection off column 0, nor
          // leave the genuinely focused column with no visible indicator.
          const selected = activeIdx === i;
          const focused = focusIdx === i;
          const rows = glyphFor(i);
          return (
            <div
              key={i}
              ref={(el) => {
                colRefs.current[i] = el;
              }}
              role="option"
              aria-selected={focused}
              aria-label={`${label} ${i + 1} of ${series.length}: ${valueFormat(v)}`}
              tabIndex={i === (focusIdx ?? 0) ? 0 : -1}
              onFocus={() => setFocusIdx(i)}
              onPointerEnter={() => setHoverIdx(i)}
              onPointerLeave={() => setHoverIdx(null)}
              onClick={(e) => e.currentTarget.focus()}
              className={`flex cursor-pointer flex-col text-center leading-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent ${
                selected ? "bg-foreground" : ""
              }`}
              style={{ width: `${COL_W}ch` }}
            >
              {rows.map((row, r) => (
                <span
                  key={r}
                  aria-hidden
                  style={{ lineHeight: "1.2em" }}
                  className={
                    // painting bg-foreground on every row, not just the
                    // column div, guarantees a fully solid fill top to
                    // bottom even though the column div and its rows don't
                    // share a background layer once each row is its own
                    // flex-blockified box.
                    selected
                      ? "bg-foreground"
                      : row.kind === "bar"
                        ? "text-foreground"
                        : "text-ns-muted/30"
                  }
                >
                  {selected
                    ? // "█" is a fully-inked glyph: recoloring it to the
                      // background token (as the rest of this knock-out
                      // relies on) paints the *entire* cell in that dark
                      // color, which just blends back into the page and
                      // makes a tall bar's own rows disappear instead of
                      // highlighting them. A blank cell has no ink to fight
                      // the fill, so every row renders as blank and the
                      // row's own solid background does all the work — a
                      // uniform, unmistakable bar of color the full height
                      // of the column, bar rows and empty rows alike. A
                      // literal " " won't do it: a whitespace-only block box
                      // collapses its line box to zero height, which is why
                      // this needs a non-breaking space instead.
                      " "
                    : row.kind === "empty"
                      ? "·"
                      : row.glyph}
                </span>
              ))}
            </div>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// RuleSparkline — inline KPI sparkline over an elementary cellular-automaton
// texture. The Wolfram rule is selected by the series' volatility (coefficient
// of variation): calm data grows a sparse automaton, volatile data a chaotic
// one, one generation column per data point — the texture reads the data
// instead of decorating it. CA is computed once per data update and cached to
// an offscreen canvas; rAF exists only during the entrance sweep and active
// scrub, cancelled otherwise.
// ---------------------------------------------------------------------------

type Vec3 = [number, number, number];

// cubic-bezier(0.22, 1, 0.36, 1) solved via Newton–Raphson
function makeBezier(p1x: number, p1y: number, p2x: number, p2y: number) {
  const cx = 3 * p1x;
  const bx = 3 * (p2x - p1x) - cx;
  const ax = 1 - cx - bx;
  const cy = 3 * p1y;
  const by = 3 * (p2y - p1y) - cy;
  const ay = 1 - cy - by;
  const sampleX = (t: number) => ((ax * t + bx) * t + cx) * t;
  const sampleY = (t: number) => ((ay * t + by) * t + cy) * t;
  const slopeX = (t: number) => (3 * ax * t + 2 * bx) * t + cx;
  return (x: number) => {
    if (x <= 0) return 0;
    if (x >= 1) return 1;
    let t = x;
    for (let i = 0; i < 6; i++) {
      const s = slopeX(t);
      if (Math.abs(s) < 1e-6) break;
      t -= (sampleX(t) - x) / s;
    }
    return sampleY(Math.min(1, Math.max(0, t)));
  };
}
const glideEase = makeBezier(0.22, 1, 0.36, 1);

function parseColor(raw: string): Vec3 | null {
  const s = raw.trim();
  if (s.startsWith("#")) {
    const hex = s.slice(1);
    if (hex.length === 3) {
      const r = parseInt(hex.slice(0, 1) + hex.slice(0, 1), 16);
      const g = parseInt(hex.slice(1, 2) + hex.slice(1, 2), 16);
      const b = parseInt(hex.slice(2, 3) + hex.slice(2, 3), 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    if (hex.length >= 6) {
      const r = parseInt(hex.slice(0, 2), 16);
      const g = parseInt(hex.slice(2, 4), 16);
      const b = parseInt(hex.slice(4, 6), 16);
      return Number.isNaN(r + g + b) ? null : [r, g, b];
    }
    return null;
  }
  const m = s.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
}

// deterministic per-cell hash → stable alpha texture across repaints
function hash01(x: number, y: number) {
  const n = Math.sin(x * 127.1 + y * 311.7) * 43758.5453123;
  return n - Math.floor(n);
}

// volatility bucket → elementary rule. cv = stddev/mean, zero-mean guarded.
function volatilityRule(data: number[]): { rule: number; cv: number } {
  const n = data.length;
  if (n < 2) return { rule: 4, cv: 0 };
  let sum = 0;
  for (let i = 0; i < n; i++) sum += data[i] ?? 0;
  const mean = sum / n;
  let sq = 0;
  for (let i = 0; i < n; i++) {
    const d = (data[i] ?? 0) - mean;
    sq += d * d;
  }
  const sd = Math.sqrt(sq / n);
  const denom = Math.abs(mean);
  const cv = denom < 1e-9 ? (sd > 1e-9 ? 1 : 0) : sd / denom;
  if (cv < 0.08) return { rule: 4, cv };
  if (cv < 0.2) return { rule: 108, cv };
  if (cv < 0.4) return { rule: 110, cv };
  return { rule: 30, cv };
}

// seed row derived from the first value's IEEE-754 bits (mulberry32 walk) —
// identical data reproduces identical texture
function seedRow(rows: number, firstValue: number): Uint8Array {
  const f = new Float32Array(1);
  f[0] = firstValue;
  let s = (new Uint32Array(f.buffer)[0] ?? 0) || 0x9e3779b9;
  const out = new Uint8Array(rows);
  for (let i = 0; i < rows; i++) {
    s = (s + 0x6d2b79f5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    out[i] = (((t ^ (t >>> 14)) >>> 0) >>> 8) & 1;
  }
  return out;
}

function nextGen(prev: Uint8Array, rule: number): Uint8Array {
  const n = prev.length;
  const out = new Uint8Array(n);
  for (let i = 0; i < n; i++) {
    const l = prev[(i - 1 + n) % n] ?? 0;
    const c = prev[i] ?? 0;
    const r = prev[(i + 1) % n] ?? 0;
    out[i] = (rule >> ((l << 2) | (c << 1) | r)) & 1;
  }
  return out;
}

const DEFAULT_DATA = [
  42, 44, 43, 47, 45, 49, 46, 51, 48, 53, 50, 47, 52, 55, 51, 56, 53, 58, 55,
  60, 57, 61, 59, 63,
];

function defaultFormat(v: number) {
  return v.toLocaleString("en-US", { maximumFractionDigits: 1 });
}

export function RuleSparkline({
  data = DEFAULT_DATA,
  cellSize = 3,
  entranceMs = 900,
  strokeWidth = 1.5,
  formatValue = defaultFormat,
  className = "h-14",
  "aria-label": ariaLabel = "KPI sparkline",
}: {
  /** series values, oldest → newest; one CA generation per point */
  data?: number[];
  /** CA cell height in px */
  cellSize?: number;
  /** entrance sweep duration in ms */
  entranceMs?: number;
  /** polyline stroke width in px */
  strokeWidth?: number;
  /** scrub readout formatter */
  formatValue?: (value: number, index: number) => string;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** accessible name for the sparkline. Default "KPI sparkline". */
  "aria-label"?: string;
}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const readoutRef = useRef<HTMLDivElement>(null);
  const dataRef = useRef(data);
  const formatRef = useRef(formatValue);
  formatRef.current = formatValue;
  const ariaLabelRef = useRef(ariaLabel);
  ariaLabelRef.current = ariaLabel;
  const engineRef = useRef<{ setData: (d: number[]) => void } | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    const readout = readoutRef.current;
    if (!root || !canvas || !readout) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const off = document.createElement("canvas");
    const octx = off.getContext("2d");
    if (!octx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    // -- token-derived ink: read at mount, re-derived on theme class change --
    let fg: Vec3 = [237, 237, 237];
    let ac: Vec3 = [0, 107, 255];
    let mu: Vec3 = [143, 143, 143];
    const derive = () => {
      const cs = getComputedStyle(document.documentElement);
      fg = parseColor(cs.getPropertyValue("--foreground")) ?? fg;
      ac = parseColor(cs.getPropertyValue("--ns-accent")) ?? ac;
      mu = parseColor(cs.getPropertyValue("--ns-muted")) ?? mu;
    };
    derive();

    // -- hot-path state: locals only, never React state ---------------------
    let w = 0;
    let h = 0;
    let dpr = 1;
    let raf = 0;
    let last = 0;
    let cur: number[] = dataRef.current;
    let gens: Uint8Array[] = [];
    let rule = 4;
    let rows = 0;
    let xs = new Float32Array(0);
    let ys = new Float32Array(0);
    let pathLen = 0;
    // sweep: -1 = settled (fully revealed)
    let sweepStart = -1;
    let sweepDur = entranceMs;
    let sweepFromFrac = 0;
    // scrub spring: k = 250 s^-2, zeta = 1.0 (critically damped)
    const K = 250;
    const C = 2 * Math.sqrt(K);
    let hx = 0;
    let hv = 0;
    let tx = 0;
    let alpha = 0;
    let targetAlpha = 0;
    let ai = -1;
    let readoutAi = -1;
    let readoutShown = false;

    const computeCA = () => {
      gens = [];
      const picked = volatilityRule(cur);
      rule = picked.rule;
      rows = Math.max(0, Math.floor(h / cellSize));
      if (cur.length === 0 || rows === 0) return;
      let row = seedRow(rows, cur[0] ?? 0);
      gens.push(row);
      for (let i = 1; i < cur.length; i++) {
        row = nextGen(row, rule);
        gens.push(row);
      }
    };

    const computeGeometry = () => {
      const n = cur.length;
      xs = new Float32Array(n);
      ys = new Float32Array(n);
      pathLen = 0;
      if (n === 0 || w <= 0 || h <= 0) return;
      let mn = Infinity;
      let mx = -Infinity;
      for (let i = 0; i < n; i++) {
        const v = cur[i] ?? 0;
        if (v < mn) mn = v;
        if (v > mx) mx = v;
      }
      const span = mx - mn;
      const padY = Math.max(3, strokeWidth + 2);
      for (let i = 0; i < n; i++) {
        xs[i] = n > 1 ? (i / (n - 1)) * w : w / 2;
        ys[i] =
          span > 1e-12
            ? padY + (1 - ((cur[i] ?? 0) - mn) / span) * (h - padY * 2)
            : h / 2;
      }
      for (let i = 1; i < n; i++) {
        const dx = (xs[i] ?? 0) - (xs[i - 1] ?? 0);
        const dy = (ys[i] ?? 0) - (ys[i - 1] ?? 0);
        pathLen += Math.sqrt(dx * dx + dy * dy);
      }
    };

    // CA texture painted ONCE per data/theme/size change — never per frame
    const paintOffscreen = () => {
      off.width = Math.max(1, Math.round(w * dpr));
      off.height = Math.max(1, Math.round(h * dpr));
      const n = gens.length;
      if (w <= 0 || h <= 0 || n === 0) return;
      octx.setTransform(dpr, 0, 0, dpr, 0, 0);
      octx.clearRect(0, 0, w, h);
      const colW = w / n;
      const gap = colW > 2.5 ? 1 : 0;
      const cellGap = cellSize > 2 ? 1 : 0;
      for (let i = 0; i < n; i++) {
        const g = gens[i];
        if (!g) continue;
        const x = i * colW;
        for (let r = 0; r < rows; r++) {
          if (!g[r]) continue;
          // foreground ink at 8–14% alpha, deterministic per cell
          const a = 0.08 + 0.06 * hash01(i * 7.13 + 1.7, r * 3.71 + 9.2);
          octx.fillStyle = `rgba(${fg[0]},${fg[1]},${fg[2]},${a.toFixed(3)})`;
          octx.fillRect(
            x,
            r * cellSize,
            Math.max(0.5, colW - gap),
            cellSize - cellGap
          );
        }
      }
    };

    const sweepX = (now: number) => {
      if (sweepStart < 0) return w;
      const p = (now - sweepStart) / sweepDur;
      if (p >= 1) {
        sweepStart = -1;
        return w;
      }
      const from = sweepFromFrac * w;
      return from + (w - from) * glideEase(p);
    };

    const draw = (now: number) => {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      if (w <= 0 || h <= 0) return;
      const sx = Math.max(0, Math.min(w, sweepX(now)));
      // CA backdrop revealed by clip-rect sweep (source-rect blit)
      if (sx > 0.5 && off.width > 1) {
        ctx.drawImage(off, 0, 0, sx * dpr, off.height, 0, 0, sx, h);
      }
      // polyline drawn via dash-offset technique
      const n = cur.length;
      if (n >= 2 && pathLen > 0) {
        const frac = sx / w;
        if (frac > 0.001) {
          ctx.beginPath();
          ctx.moveTo(xs[0] ?? 0, ys[0] ?? 0);
          for (let i = 1; i < n; i++) ctx.lineTo(xs[i] ?? 0, ys[i] ?? 0);
          ctx.strokeStyle = `rgb(${ac[0]},${ac[1]},${ac[2]})`;
          ctx.lineWidth = strokeWidth;
          ctx.lineJoin = "round";
          ctx.lineCap = "round";
          if (frac < 1) ctx.setLineDash([pathLen * frac, pathLen]);
          ctx.stroke();
          ctx.setLineDash([]);
        }
      }
      // scrub hairline + snapped point marker
      if (alpha > 0.01 && n > 0 && ai >= 0) {
        const cx = Math.round(hx) + 0.5;
        ctx.globalAlpha = alpha;
        ctx.strokeStyle = `rgba(${mu[0]},${mu[1]},${mu[2]},0.7)`;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(cx, 0);
        ctx.lineTo(cx, h);
        ctx.stroke();
        ctx.fillStyle = `rgb(${ac[0]},${ac[1]},${ac[2]})`;
        ctx.beginPath();
        ctx.arc(xs[ai] ?? 0, ys[ai] ?? 0, strokeWidth + 1.5, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = 1;
      }
    };

    const springActive = () =>
      targetAlpha > 0 && (Math.abs(tx - hx) > 0.3 || Math.abs(hv) > 3);
    const active = () =>
      sweepStart >= 0 || springActive() || Math.abs(targetAlpha - alpha) > 0.01;

    const loop = (now: number) => {
      const dt = Math.min(0.05, last === 0 ? 1 / 60 : (now - last) / 1000);
      last = now;
      // critically damped spring toward the snapped target
      const a = K * (tx - hx) - C * hv;
      hv += a * dt;
      hx += hv * dt;
      if (!springActive() && targetAlpha > 0) {
        hx = tx;
        hv = 0;
      }
      alpha += (targetAlpha - alpha) * Math.min(1, dt * 14);
      if (Math.abs(targetAlpha - alpha) <= 0.01) alpha = targetAlpha;
      draw(now);
      if (active()) {
        raf = requestAnimationFrame(loop);
      } else {
        // genuinely idle: no rAF at rest — draw once settled, then stop
        raf = 0;
        last = 0;
        draw(now);
      }
    };
    const wake = () => {
      if (raf === 0 && !reduced) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const updateReadout = () => {
      const show = targetAlpha > 0 && ai >= 0 && ai < cur.length;
      if (show && (readoutAi !== ai || !readoutShown)) {
        readoutAi = ai;
        const val = formatRef.current(cur[ai] ?? 0, ai);
        readout.textContent = val;
        root.setAttribute("aria-label", `${ariaLabelRef.current}, ${val}`);
        const rw = readout.offsetWidth;
        const x = Math.max(0, Math.min(w - rw, (xs[ai] ?? 0) - rw / 2));
        readout.style.transform = `translateX(${x.toFixed(1)}px)`;
      }
      if (show !== readoutShown) {
        readoutShown = show;
        readout.style.opacity = show ? "1" : "0";
        if (!show) root.setAttribute("aria-label", ariaLabelRef.current);
      }
    };

    const setActive = (i: number, show: boolean) => {
      const n = cur.length;
      if (n === 0 || w <= 0) return;
      ai = Math.max(0, Math.min(n - 1, i));
      tx = xs[ai] ?? 0;
      targetAlpha = show ? 1 : 0;
      updateReadout();
      if (reduced) {
        hx = tx;
        hv = 0;
        alpha = targetAlpha;
        draw(performance.now());
      } else {
        wake();
      }
    };

    const rebuild = () => {
      computeCA();
      computeGeometry();
      paintOffscreen();
    };

    const resize = () => {
      const rect = root.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
      rebuild();
      if (ai >= 0) {
        tx = xs[ai] ?? 0;
        readoutAi = -1; // reposition the readout against the new geometry
        updateReadout();
      }
      if (raf === 0) draw(performance.now());
    };
    // arm the entrance BEFORE the first paint so frame 0 renders at sweep≈0
    // (no one-frame flash of the finished texture)
    if (!reduced && entranceMs > 0) {
      sweepFromFrac = 0;
      sweepDur = entranceMs;
      sweepStart = performance.now();
    }
    resize();

    const samePrefix = (a: number[], b: number[]) => {
      for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
      return true;
    };

    const setData = (d: number[]) => {
      if (d === cur) return;
      const prev = cur;
      const prevRule = rule;
      cur = d;
      const picked = volatilityRule(cur);
      // tail push: same prefix, same rule bucket → extrude only new columns
      const isTail =
        prev.length > 0 &&
        cur.length > prev.length &&
        picked.rule === prevRule &&
        gens.length === prev.length &&
        rows > 0 &&
        samePrefix(prev, cur);
      if (isTail) {
        rule = picked.rule;
        let row = gens[gens.length - 1] ?? seedRow(rows, cur[0] ?? 0);
        for (let i = prev.length; i < cur.length; i++) {
          row = nextGen(row, rule);
          gens.push(row);
        }
        computeGeometry();
        paintOffscreen();
      } else {
        rebuild();
      }
      if (ai >= cur.length) ai = cur.length - 1;
      if (ai >= 0) {
        tx = xs[ai] ?? 0;
        readoutAi = -1; // force readout refresh
        updateReadout();
      }
      if (reduced || w <= 0) {
        draw(performance.now());
        return;
      }
      // 200ms sweep over the new tail only (full width on replacement)
      sweepFromFrac =
        isTail && cur.length > 1 ? (prev.length - 1) / (cur.length - 1) : 0;
      sweepDur = 200;
      sweepStart = performance.now();
      wake();
    };
    engineRef.current = { setData };

    // -- entrance: 900ms left→right reveal, skipped under reduced motion ----
    if (!reduced && entranceMs > 0) wake();

    // -- events -------------------------------------------------------------
    const onMove = (e: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      const n = cur.length;
      if (n === 0 || rect.width <= 0) return;
      const x = e.clientX - rect.left;
      setActive(Math.round((x / rect.width) * (n - 1)), true);
    };
    const onLeave = () => {
      targetAlpha = 0;
      updateReadout();
      if (reduced) {
        alpha = 0;
        draw(performance.now());
      } else {
        wake();
      }
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "ArrowLeft" && e.key !== "ArrowRight") return;
      e.preventDefault();
      const step = e.key === "ArrowLeft" ? -1 : 1;
      setActive((ai < 0 ? cur.length - 1 : ai) + step, true);
    };
    const onBlur = () => onLeave();
    root.addEventListener("pointermove", onMove);
    root.addEventListener("pointerdown", onMove);
    root.addEventListener("pointerleave", onLeave);
    root.addEventListener("keydown", onKey);
    root.addEventListener("blur", onBlur);

    const ro = new ResizeObserver(resize);
    ro.observe(root);
    // live theme re-derive: repaint the cached CA in the new ink
    const mo = new MutationObserver(() => {
      derive();
      paintOffscreen();
      if (raf === 0) draw(performance.now());
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      mo.disconnect();
      root.removeEventListener("pointermove", onMove);
      root.removeEventListener("pointerdown", onMove);
      root.removeEventListener("pointerleave", onLeave);
      root.removeEventListener("keydown", onKey);
      root.removeEventListener("blur", onBlur);
      engineRef.current = null;
    };
  }, [cellSize, entranceMs, strokeWidth]);

  useEffect(() => {
    dataRef.current = data;
    engineRef.current?.setData(data);
  }, [data]);

  return (
    <div
      ref={rootRef}
      role="group"
      aria-label={ariaLabel}
      tabIndex={0}
      style={{ touchAction: "pan-y" }}
      className={`relative w-full cursor-crosshair overflow-hidden rounded-sm outline-none transition-colors duration-200 hover:bg-foreground/[0.03] focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent ${className}`}
    >
      <canvas
        ref={canvasRef}
        aria-hidden
        className="absolute inset-0 h-full w-full"
      />
      <div
        ref={readoutRef}
        role="status"
        aria-live="polite"
        aria-atomic="true"
        className="pointer-events-none absolute left-0 top-0.5 rounded-sm border border-border bg-surface px-1.5 py-0.5 font-mono text-[10px] tabular-nums text-foreground opacity-0 transition-opacity duration-150"
      />
    </div>
  );
}

"use client";

import { useId, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// SpecieClip — a partial-refund control drawn as a struck coin: an SVG disc
// with a reeded edge (120 ticks, every 3deg) and the outstanding amount as
// its face. Refunding is CLIPPING: the user drags a chord across the disc
// and the sector on the far side of it is the refund.
//
// The one governing scalar is `refundFrac` (0-1). Geometry and money are
// bound by the real circular-segment area formula, not a linear ratio:
//   fracAtD(d)   = (acos(d) - d*sqrt(1-d^2)) / pi     for d in [-1, 1]
// where d is the chord's signed offset from the disc centre in radius
// units. This is exact and cheap (one acos), so live dragging reads the
// chord's pixel position and evaluates it directly, forward, every move.
// The INVERSE — "what chord position pays out exactly 25%, or exactly
// $30.00" — has no closed form (acos - d*sqrt(1-d^2) isn't solvable for d
// algebraically), so whenever refundFrac is the source of truth (keyboard
// step, typed amount, a snapped detent, a controlled-prop sync) the chord
// position is looked up from a 256-sample table of fracAtD(d) built once at
// module load and walked with linear interpolation. Forward = formula.
// Backward = table. Both directions always agree because they're the same
// curve; nothing here is a disguised linear slider.
//
// RENDER: the coin is drawn twice, once per side of the chord, each a full
// disc + full reeded edge + full face text, each clipped to its half by a
// <clipPath> rect driven by the same chord x. Together the two halves are
// pixel-identical to one undivided coin — the seam is the clip boundary,
// nothing is faked. On commit (button only, never on drag release) the far
// side's <g> is torn free with a single 280ms translate+fade tween along
// the chord's normal, eased ease-out-expo (1 - 2^(-10t), a real physical
// deceleration curve, not a CSS approximation) and driven imperatively via
// rAF writing the SVG `transform`/`opacity` attributes directly — CSS
// transitions on inline SVG groups are ambiguous about px-vs-user-space
// under viewBox scaling, so this keeps the shear numerically exact in the
// same coordinate system as the ticks it's carrying with it. The shear
// reads from that geometry alone — the departing <g>'s own translate+fade
// is the only signal that it's being torn free. When the tween lands, the
// coin re-strikes: the outstanding amount drops by the refund and the
// chord resets to the disc's edge (0% again), ready for the next partial
// refund. The live cut line inside the coin (the chord's visible
// position, doubling as the otherwise-invisible role=slider handle's
// value indicator) is drawn in --border, the same value the disc's own
// edge stroke uses — it reads as another physical seam of the coin, not
// an accent highlight. The clip boundary alone can't carry that job: the
// two halves are deliberately pixel-identical to one undivided coin at
// rest, so the boundary itself is invisible until commit tears the cut
// half free. --ns-accent appears only on the keyboard focus ring — the
// one genuinely interaction-tied, never rest-state, use of it.
// ---------------------------------------------------------------------------

const VB = 200; // svg viewBox is VB x VB
const CX = VB / 2;
const CY = VB / 2;
const FACE_R = 78; // metal disc radius
const OUTER_R = 92; // reeded-edge tick outer radius
const TICK_STEP_DEG = 3;
const TICK_ANGLES: number[] = Array.from(
  { length: 360 / TICK_STEP_DEG },
  (_, i) => i * TICK_STEP_DEG
);

const LUT_SIZE = 256;
const SHEAR_MS = 280;
const SHEAR_DX = 46; // svg user units the cut sector travels on commit
const SNAP_PX = 4; // real screen px radius for detent snapping

function clamp(v: number, lo: number, hi: number) {
  return Math.min(hi, Math.max(lo, v));
}
function round2(v: number) {
  return Math.round(v * 100) / 100;
}

/** Area, as a fraction of the whole disc, that lies on the far side (x > d)
 * of a chord at signed offset d (in radius units, -1..1) from the centre of
 * a unit circle. Exact, closed-form, monotonically decreasing 1 -> 0. */
function fracAtD(d: number): number {
  const dc = clamp(d, -1, 1);
  return (Math.acos(dc) - dc * Math.sqrt(1 - dc * dc)) / Math.PI;
}

// Precomputed once: FRAC_TABLE[i] = fracAtD(d) for d sampled uniformly
// across [-1, 1]. fracAtD has no algebraic inverse, so recovering "the d
// that pays out this fraction" is done by walking this table, never by
// re-deriving it per call.
const FRAC_TABLE: number[] = Array.from({ length: LUT_SIZE }, (_, i) =>
  fracAtD(-1 + (2 * i) / (LUT_SIZE - 1))
);

/** Inverse of fracAtD: given a target refund fraction, find the chord
 * offset d that produces it — binary search into FRAC_TABLE (monotonic
 * descending) plus linear interpolation between the two bracketing
 * samples. */
function dForFrac(frac: number): number {
  const f = clamp(frac, 0, 1);
  let lo = 0;
  let hi = LUT_SIZE - 1;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (FRAC_TABLE[mid] > f) lo = mid;
    else hi = mid;
  }
  const fLo = FRAC_TABLE[lo];
  const fHi = FRAC_TABLE[hi];
  const span = fLo - fHi;
  const u = span > 1e-9 ? (fLo - f) / span : 0;
  const dLo = -1 + (2 * lo) / (LUT_SIZE - 1);
  const dHi = -1 + (2 * hi) / (LUT_SIZE - 1);
  return dLo + (dHi - dLo) * u;
}

/** Rounds a raw dollar amount to a "nice" support-refund step, scaled to
 * the size of the charge — $120 rounds to $5s, $1200 rounds to $100s. */
function niceStep(chargeValue: number): number {
  if (chargeValue <= 20) return 1;
  if (chargeValue <= 100) return 5;
  if (chargeValue <= 500) return 10;
  if (chargeValue <= 2000) return 25;
  return 100;
}

/** Snaps a raw drag-derived fraction to the nearest of {25%, 50%, 100%, one
 * nice round dollar amount} if that candidate's chord position is within
 * SNAP_PX real pixels of the raw one — else returns the raw fraction
 * untouched. */
function snapFrac(
  rawD: number,
  rawFrac: number,
  chargeValue: number,
  pxPerUnit: number
): number {
  if (!(pxPerUnit > 0)) return rawFrac;
  const rawPx = rawD * FACE_R;
  const candidates: number[] = [0.25, 0.5, 1];
  if (chargeValue > 0) {
    const step = niceStep(chargeValue);
    const rounded = clamp(
      Math.round((chargeValue * rawFrac) / step) * step,
      0,
      chargeValue
    );
    candidates.push(rounded / chargeValue);
  }
  let best = rawFrac;
  let bestDist = Infinity;
  for (const c of candidates) {
    const px = dForFrac(c) * FACE_R;
    const dist = Math.abs(px - rawPx) * pxPerUnit;
    if (dist < bestDist) {
      bestDist = dist;
      best = c;
    }
  }
  return bestDist <= SNAP_PX ? best : rawFrac;
}

function fmt(amount: number, symbol: string) {
  return `${symbol}${amount.toFixed(2)}`;
}

function easeOutExpo(t: number) {
  return t >= 1 ? 1 : 1 - Math.pow(2, -10 * t);
}

interface DiscFaceProps {
  label: string;
}

/** The struck face: disc + reeded edge + amount. Rendered twice (once per
 * clip half) so the two halves are, together, one undivided coin. */
function DiscFace({ label }: DiscFaceProps) {
  return (
    <>
      <circle
        cx={CX}
        cy={CY}
        r={FACE_R}
        fill="var(--background)"
        stroke="var(--border)"
        strokeWidth={1.5}
      />
      {TICK_ANGLES.map((deg) => {
        const rad = (deg * Math.PI) / 180;
        const cos = Math.cos(rad);
        const sin = Math.sin(rad);
        // rounded: Math.cos/sin can differ by a ULP between Node (SSR) and the
        // browser's engine (CSR), which surfaced as x2="62.58022883702639" on
        // the server vs 62.5802288370264 on the client — a hydration mismatch
        // despite both being "correct".
        return (
          <line
            key={deg}
            x1={round2(CX + FACE_R * cos)}
            y1={round2(CY + FACE_R * sin)}
            x2={round2(CX + OUTER_R * cos)}
            y2={round2(CY + OUTER_R * sin)}
            stroke="var(--ns-muted)"
            strokeWidth={1}
          />
        );
      })}
      <text
        x={CX}
        y={CY}
        textAnchor="middle"
        dominantBaseline="central"
        className="font-mono"
        fill="var(--foreground)"
        fontSize={18}
        fontWeight={500}
      >
        {label}
      </text>
    </>
  );
}

export interface SpecieClipProps {
  /** controlled outstanding charge amount available to refund */
  chargeAmount?: number;
  /** uncontrolled initial charge amount */
  defaultChargeAmount?: number;
  /** controlled refund fraction, 0-1 */
  refundFrac?: number;
  /** uncontrolled initial refund fraction */
  defaultRefundFrac?: number;
  /** currency symbol prefix */
  currencySymbol?: string;
  /** fires on every drag/keyboard/typed change to the fraction (no money moves) */
  onRefundFracChange?: (frac: number) => void;
  /** fires once the refund is committed via the button, after the shear settles */
  onRefund?: (refundedAmount: number, remainingAmount: number) => void;
  /** extra classes merged onto the root element */
  className?: string;
}

export function SpecieClip({
  chargeAmount,
  defaultChargeAmount = 120,
  refundFrac,
  defaultRefundFrac = 0.25,
  currencySymbol = "$",
  onRefundFracChange,
  onRefund,
  className = "",
}: SpecieClipProps) {
  const isChargeControlled = chargeAmount !== undefined;
  const [chargeInternal, setChargeInternal] = useState(() =>
    Math.max(0, defaultChargeAmount)
  );
  const chargeValue = isChargeControlled
    ? (chargeAmount as number)
    : chargeInternal;

  const isFracControlled = refundFrac !== undefined;
  const [fracInternal, setFracInternal] = useState(() =>
    clamp(defaultRefundFrac, 0, 1)
  );
  const fracValue = isFracControlled ? (refundFrac as number) : fracInternal;

  const [dragging, setDragging] = useState(false);
  const [committing, setCommitting] = useState(false);
  const [ledgerMsg, setLedgerMsg] = useState("");

  const coinBoxRef = useRef<HTMLDivElement>(null);
  const handleRef = useRef<HTMLDivElement>(null);
  const cutGroupRef = useRef<SVGGElement>(null);

  const keptClipId = useId();
  const cutClipId = useId();
  const inputId = useId();

  const commitFracChange = (next: number) => {
    const q = clamp(next, 0, 1);
    if (!isFracControlled) setFracInternal(q);
    onRefundFracChange?.(q);
  };

  const d = dForFrac(fracValue);
  const chordXpx = clamp(CX + d * FACE_R, CX - FACE_R, CX + FACE_R);
  const refundAmt = round2(chargeValue * fracValue);
  const remainingAmt = round2(Math.max(0, chargeValue - refundAmt));
  const pct = Math.round(fracValue * 100);
  const valueText = `refund ${fmt(refundAmt, currencySymbol)} of ${fmt(
    chargeValue,
    currencySymbol
  )}, ${pct}%`;

  const updateFromClientX = (clientX: number) => {
    const box = coinBoxRef.current;
    if (!box) return;
    const rect = box.getBoundingClientRect();
    if (rect.width <= 0) return;
    const xLocal = ((clientX - rect.left) / rect.width) * VB;
    const rawD = clamp((xLocal - CX) / FACE_R, -1, 1);
    const rawFrac = clamp(fracAtD(rawD), 0, 1);
    const pxPerUnit = rect.width / VB;
    const snapped = snapFrac(rawD, rawFrac, chargeValue, pxPerUnit);
    commitFracChange(snapped);
  };

  const onCoinPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (committing) return;
    e.preventDefault();
    e.currentTarget.setPointerCapture(e.pointerId);
    handleRef.current?.focus({ preventScroll: true });
    setDragging(true);
    updateFromClientX(e.clientX);
  };
  const onCoinPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!dragging) return;
    updateFromClientX(e.clientX);
  };
  const endDrag = () => setDragging(false);

  const onHandleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (committing || chargeValue <= 0) return;
    const step = 1 / chargeValue;
    const bigStep = 10 / chargeValue;
    let next: number | null = null;
    switch (e.key) {
      case "ArrowRight":
      case "ArrowUp":
        next = fracValue + (e.shiftKey ? bigStep : step);
        break;
      case "ArrowLeft":
      case "ArrowDown":
        next = fracValue - (e.shiftKey ? bigStep : step);
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = 1;
        break;
      default:
        return;
    }
    e.preventDefault();
    commitFracChange(clamp(next, 0, 1));
  };

  const handleCommit = () => {
    if (committing || refundAmt <= 0 || chargeValue <= 0) return;
    setCommitting(true);
    const refunded = refundAmt;
    const remaining = remainingAmt;
    const reduced =
      typeof window !== "undefined" &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    const finalize = () => {
      const g = cutGroupRef.current;
      g?.removeAttribute("transform");
      g?.removeAttribute("opacity");
      if (!isChargeControlled) setChargeInternal(remaining);
      if (!isFracControlled) setFracInternal(0);
      onRefundFracChange?.(0);
      onRefund?.(refunded, remaining);
      setLedgerMsg(
        `Refunded ${fmt(refunded, currencySymbol)}. ${fmt(
          remaining,
          currencySymbol
        )} remaining.`
      );
      setCommitting(false);
    };

    const g = cutGroupRef.current;
    if (reduced || !g) {
      g?.setAttribute("transform", `translate(${SHEAR_DX} 0)`);
      g?.setAttribute("opacity", "0");
      finalize();
      return;
    }

    const start = performance.now();
    const step = (now: number) => {
      const t = clamp((now - start) / SHEAR_MS, 0, 1);
      const e = easeOutExpo(t);
      g.setAttribute("transform", `translate(${SHEAR_DX * e} 0)`);
      g.setAttribute("opacity", String(1 - e));
      if (t < 1) requestAnimationFrame(step);
      else finalize();
    };
    requestAnimationFrame(step);
  };

  const onInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (committing) return;
    const raw = Number.parseFloat(e.target.value);
    const amt = Number.isFinite(raw) ? clamp(raw, 0, chargeValue) : 0;
    commitFracChange(chargeValue > 0 ? amt / chargeValue : 0);
  };

  return (
    <div className={`w-full max-w-[280px] select-none ${className}`}>
      <div
        ref={coinBoxRef}
        data-cc-coin=""
        className="relative aspect-square w-full touch-none"
        onPointerDown={onCoinPointerDown}
        onPointerMove={onCoinPointerMove}
        onPointerUp={endDrag}
        onPointerCancel={endDrag}
      >
        <svg
          aria-hidden
          viewBox={`0 0 ${VB} ${VB}`}
          className="absolute inset-0 h-full w-full cursor-ew-resize"
        >
          <defs>
            <clipPath id={keptClipId}>
              <rect x={0} y={0} width={chordXpx} height={VB} />
            </clipPath>
            <clipPath id={cutClipId}>
              <rect
                x={chordXpx}
                y={0}
                width={Math.max(0, VB - chordXpx)}
                height={VB}
              />
            </clipPath>
          </defs>

          <g clipPath={`url(#${keptClipId})`}>
            <DiscFace label={fmt(chargeValue, currencySymbol)} />
          </g>
          <g ref={cutGroupRef} clipPath={`url(#${cutClipId})`}>
            <DiscFace label={fmt(chargeValue, currencySymbol)} />
          </g>

          {/* the live cut line — authoritative, always current. Drawn in
              --border (the same stroke the disc's own edge uses), not
              --ns-accent: it's the coin's physical seam, not a UI accent. */}
          <line
            x1={chordXpx}
            y1={CY - OUTER_R - 4}
            x2={chordXpx}
            y2={CY + OUTER_R + 4}
            stroke="var(--border)"
            strokeWidth={1}
            vectorEffect="non-scaling-stroke"
          />
        </svg>

        <div
          ref={handleRef}
          role="slider"
          tabIndex={0}
          aria-label="Refund amount"
          aria-orientation="horizontal"
          aria-valuemin={0}
          aria-valuemax={chargeValue}
          aria-valuenow={refundAmt}
          aria-valuetext={valueText}
          onKeyDown={onHandleKeyDown}
          style={{ left: `${(chordXpx / VB) * 100}%` }}
          className="absolute top-0 h-full w-6 -translate-x-1/2 cursor-ew-resize touch-none outline-none focus-visible:ring-2 focus-visible:ring-ns-accent focus-visible:ring-offset-2 focus-visible:ring-offset-background"
        />
      </div>

      <div className="mt-3 flex items-baseline justify-between font-mono">
        <span className="text-sm tabular-nums text-foreground">
          {`Refund ${fmt(refundAmt, currencySymbol)}`}
        </span>
        <span className="text-xs tabular-nums text-ns-muted">
          {`of ${fmt(chargeValue, currencySymbol)} · ${pct}%`}
        </span>
      </div>

      <div className="mt-3 flex items-center gap-2">
        <label
          htmlFor={inputId}
          className="font-mono text-xs text-ns-muted"
        >
          Amount
        </label>
        <input
          id={inputId}
          type="number"
          inputMode="decimal"
          min={0}
          max={chargeValue}
          step={0.01}
          disabled={committing}
          value={refundAmt.toFixed(2)}
          onChange={onInputChange}
          className="w-24 rounded-md border border-border bg-background px-2 py-1 font-mono text-sm tabular-nums text-foreground outline-none focus-visible:ring-2 focus-visible:ring-ns-accent disabled:cursor-not-allowed disabled:opacity-50 disabled:pointer-events-none"
        />
      </div>

      <button
        type="button"
        data-cc-commit=""
        disabled={committing || refundAmt <= 0}
        onClick={handleCommit}
        className="mt-4 w-full rounded-md border border-border bg-background px-3 py-2 font-mono text-sm text-foreground transition-colors duration-150 hover:enabled:border-foreground/40 outline-none focus-visible:ring-2 focus-visible:ring-ns-accent disabled:cursor-not-allowed disabled:opacity-50 disabled:pointer-events-none"
      >
        {`Refund ${fmt(refundAmt, currencySymbol)}`}
      </button>

      <p
        role="status"
        aria-live="polite"
        className="mt-2 min-h-[1em] font-mono text-xs text-ns-muted"
      >
        {ledgerMsg}
      </p>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// SpectrogramAsciiBands — a scrolling spectrogram printed in monospace ink.
//
// The analysis is real: a 512-point radix-2 Cooley–Tukey FFT (inlined, no
// dependency) over a Hann-windowed frame, magnitudes in dB, grouped into 32
// log-spaced bands. The mechanism that makes it READABLE rather than a
// uniform medium-density wash is the per-band adaptive floor: each band runs
// its own slow AGC that falls fast (0.02) and rises slowly (0.002) toward the
// band's own dB, so it tracks the QUIET baseline. A steady hiss sinks into
// its own floor and disappears; only structure that stands above its band's
// baseline prints at all, and anything under floor + 12 dB prints nothing. Most
// of the frame is empty by construction.
//
// The pointer never distorts the field — the cells are measurements, and
// bending them would lie. It parks a cursor on a column and reads that
// column's peak out in the readout instead.
// ---------------------------------------------------------------------------

const RAMP = " .:-=+*#%@";
const ALPHA_BUCKETS = 6;

const FFT_N = 512;
const LOG2N = 9;
const BANDS = 32;
const MIN_BIN = 2;
const MAX_BIN = 200;
const HOP_MS = 50;
const SEED_COLS = 240;

const FLOOR_INIT = -70; // dB — seeded low so the AGC warms UP into each band's baseline
const FLOOR_MAX = -35; // dB — the AGC stays in the quiet regime; it may not climb onto the subject
const WARMUP_HOPS = 300; // analysis-only hops before any visible column is committed
const WARMUP_BOOST = 12; // rise coefficient multiplier during warmup only
const FLOOR_FALL = 0.02;
const FLOOR_RISE = 0.002;
const GATE_DB = 12; // dB above floor before a cell prints anything at all
const SPAN_DB = 32; // dB above floor mapped across the full ramp

const CURSOR_TAU = 0.4; // s — cursor / readout crossfade time constant
const DT_MAX = 0.25;
const MAX_HOPS_PER_FRAME = 4;

const SYNTH_SR = 16000;
const LABEL_BANDS = [0, 8, 16, 24, 31];

// -- FFT tables -------------------------------------------------------------
const REV = new Uint16Array(FFT_N);
for (let i = 0; i < FFT_N; i++) {
  let r = 0;
  for (let b = 0; b < LOG2N; b++) r |= ((i >> b) & 1) << (LOG2N - 1 - b);
  REV[i] = r;
}
const TW_COS = new Float32Array(FFT_N / 2);
const TW_SIN = new Float32Array(FFT_N / 2);
for (let i = 0; i < FFT_N / 2; i++) {
  TW_COS[i] = Math.cos((-2 * Math.PI * i) / FFT_N);
  TW_SIN[i] = Math.sin((-2 * Math.PI * i) / FFT_N);
}
const HANN = new Float32Array(FFT_N);
for (let n = 0; n < FFT_N; n++) {
  HANN[n] = 0.5 - 0.5 * Math.cos((2 * Math.PI * n) / (FFT_N - 1));
}

// Band k covers bins BAND_START[k] .. BAND_START[k+1]. The ratio 100^(1/32) is
// under 1.16, so the log formula's first ten starts collide on bins 2..5 — left
// as-is that prints ten byte-identical rows at the bottom of the field and a
// max() over an empty range yields -Infinity. Each start is therefore forced
// strictly above its predecessor, which makes the lowest bands one bin wide
// (the FFT's own resolution limit down there) and log-spaced from there up.
const BAND_START = new Int32Array(BANDS + 1);
{
  let prev = -1;
  for (let k = 0; k <= BANDS; k++) {
    let v = Math.floor(MIN_BIN * Math.pow(MAX_BIN / MIN_BIN, k / BANDS));
    if (v <= prev) v = prev + 1;
    BAND_START[k] = v;
    prev = v;
  }
}

function fft(re: Float32Array, im: Float32Array) {
  for (let i = 0; i < FFT_N; i++) {
    const j = REV[i]!;
    if (j > i) {
      const tr = re[i]!;
      re[i] = re[j]!;
      re[j] = tr;
      const ti = im[i]!;
      im[i] = im[j]!;
      im[j] = ti;
    }
  }
  for (let size = 2; size <= FFT_N; size <<= 1) {
    const half = size >> 1;
    const step = FFT_N / size;
    for (let i = 0; i < FFT_N; i += size) {
      for (let j = 0; j < half; j++) {
        const k = j * step;
        const wr = TW_COS[k]!;
        const wi = TW_SIN[k]!;
        const a = i + j;
        const b = a + half;
        const xr = re[b]! * wr - im[b]! * wi;
        const xi = re[b]! * wi + im[b]! * wr;
        re[b] = re[a]! - xr;
        im[b] = im[a]! - xi;
        re[a] = re[a]! + xr;
        im[a] = im[a]! + xi;
      }
    }
  }
}

function mulberry32(seed: number) {
  let a = seed;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Deterministic stand-in for a microphone: two vowel-like formants at 320 Hz
 * and 1.9 kHz with a shared ±8% vibrato at 0.4 Hz, an exponential 200→4000 Hz
 * sweep looping every 9 s, and pink-ish noise at −48 dB. Nothing here calls
 * getUserMedia, so the preview never meets a permission prompt.
 */
function createSyntheticSource() {
  const rand = mulberry32(0x5c09a1);
  let t = 0;
  let p1 = 0;
  let p2 = 0;
  let ps = 0;
  let pink = 0;
  const dt = 1 / SYNTH_SR;
  return (n: number, write: (v: number) => void) => {
    for (let i = 0; i < n; i++) {
      t += dt;
      const vib = 1 + 0.08 * Math.sin(2 * Math.PI * 0.4 * t);
      const fs = 200 * Math.pow(20, (t % 9) / 9);
      p1 += 2 * Math.PI * 320 * vib * dt;
      p2 += 2 * Math.PI * 1900 * vib * dt;
      ps += 2 * Math.PI * fs * dt;
      pink = pink * 0.96 + (rand() * 2 - 1) * 0.04;
      write(
        0.5 * Math.sin(p1) +
          0.32 * Math.sin(p2) +
          0.3 * Math.sin(ps) +
          pink * 0.012
      );
    }
  };
}

export interface SpectrogramAsciiBandsProps {
  /**
   * Where samples come from: a live `AnalyserNode`, or a provider that fills
   * the passed Float32Array with the newest 512 time-domain samples. Omitted
   * ⇒ the built-in deterministic synthetic signal.
   */
  source?: AnalyserNode | ((out: Float32Array) => void);
  /** Row height in px; the field is (32 + 2) rows tall. Default 16. */
  cellSize?: number;
  /** Accessible name for the focusable readout region. */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function SpectrogramAsciiBands({
  source,
  cellSize = 16,
  label = "Spectrogram readout — arrow keys step the cursor through the history",
  className = "",
}: SpectrogramAsciiBandsProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const readoutRef = useRef<HTMLDivElement>(null);
  const liveRef = useRef<HTMLSpanElement>(null);
  const cursorTextRef = useRef<HTMLSpanElement>(null);
  const gutterRef = useRef<HTMLDivElement>(null);
  const srRef = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    const sampleRate =
      source instanceof AnalyserNode ? source.context.sampleRate : SYNTH_SR;
    const hopSamples = Math.max(1, Math.round((sampleRate * HOP_MS) / 1000));
    const binHz = sampleRate / FFT_N;

    const fmtHz = (hz: number) =>
      hz >= 1000 ? `${(hz / 1000).toFixed(1)} kHz` : `${Math.round(hz)} Hz`;

    // gutter labels depend on the source's sample rate, so they are written
    // here rather than baked into the markup
    const gutter = gutterRef.current;
    if (gutter) {
      for (const el of Array.from(gutter.children)) {
        const b = Number((el as HTMLElement).dataset.band);
        (el as HTMLElement).textContent = fmtHz(BAND_START[b]! * binHz);
      }
    }

    // -- analysis state ------------------------------------------------------
    const ring = new Float32Array(FFT_N); // newest 512 samples, modular
    let ringHead = 0;
    const re = new Float32Array(FFT_N);
    const im = new Float32Array(FFT_N);
    const floors = new Float32Array(BANDS).fill(FLOOR_INIT);
    const bandDb = new Float32Array(BANDS);
    const synth = createSyntheticSource();
    const writeSample = (v: number) => {
      ring[ringHead] = v;
      ringHead = (ringHead + 1) % FFT_N;
    };
    const external =
      source instanceof AnalyserNode
        ? (() => {
            const buf = new Float32Array(source.fftSize);
            return () => {
              source.getFloatTimeDomainData(buf);
              const off = Math.max(0, buf.length - FFT_N);
              for (let i = 0; i < FFT_N; i++) writeSample(buf[off + i] ?? 0);
            };
          })()
        : typeof source === "function"
          ? (() => {
              const buf = new Float32Array(FFT_N);
              return () => {
                source(buf);
                for (let i = 0; i < FFT_N; i++) writeSample(buf[i] ?? 0);
              };
            })()
          : null;

    // -- history ring --------------------------------------------------------
    let cols = 0;
    let cells = new Uint8Array(0); // ramp index per (col, band)
    let peakBand = new Uint8Array(0);
    let peakDb = new Float32Array(0);
    let head = 0; // oldest column

    let riseBoost = 1;

    const analyse = () => {
      if (external) external();
      else synth(hopSamples, writeSample);

      for (let n = 0; n < FFT_N; n++) {
        re[n] = ring[(ringHead + n) % FFT_N]! * HANN[n]!;
        im[n] = 0;
      }
      fft(re, im);

      for (let k = 0; k < BANDS; k++) {
        const start = BAND_START[k]!;
        const end = Math.max(start + 1, BAND_START[k + 1]!);
        let best = -Infinity;
        for (let b = start; b < end; b++) {
          const mag = Math.sqrt(re[b]! * re[b]! + im[b]! * im[b]!) / (FFT_N / 4);
          const db = 20 * Math.log10(mag + 1e-9);
          if (db > best) best = db;
        }
        bandDb[k] = best;
        const f = floors[k]!;
        floors[k] = Math.min(
          FLOOR_MAX,
          f + (best - f) * (best < f ? FLOOR_FALL : FLOOR_RISE * riseBoost)
        );
      }
    };

    const commitColumn = () => {
      if (cols === 0) return;
      const col = head;
      head = (head + 1) % cols;
      const base = col * BANDS;
      let bestBand = 0;
      let bestExcess = -Infinity;
      for (let k = 0; k < BANDS; k++) {
        const excess = bandDb[k]! - floors[k]!;
        let idx = 0;
        if (excess >= GATE_DB) {
          idx = Math.round((excess / SPAN_DB) * 9);
          idx = idx < 1 ? 1 : idx > 9 ? 9 : idx;
        }
        cells[base + k] = idx;
        if (excess > bestExcess) {
          bestExcess = excess;
          bestBand = k;
        }
      }
      peakBand[col] = bestExcess >= GATE_DB ? bestBand : 255;
      peakDb[col] = bandDb[bestBand]!;
    };

    const hop = () => {
      analyse();
      commitColumn();
    };

    // -- layout / tokens -----------------------------------------------------
    let fg = "currentColor";
    let accent = "currentColor";
    let cellW = cellSize * 0.6;
    const cellH = cellSize;
    const rows = BANDS + 1; // row 0 = headroom, rows 1..32 = field (band 31 at top)
    let sized = false;
    let disposed = false;
    let warmed = false;

    const readTokens = () => {
      fg = getComputedStyle(canvas).color;
      accent =
        getComputedStyle(document.documentElement)
          .getPropertyValue("--ns-accent")
          .trim() || fg;
    };

    const bucketLists: number[][] = Array.from({ length: ALPHA_BUCKETS }, () => []);

    const resize = () => {
      const { width } = canvas.getBoundingClientRect();
      const height = rows * cellH;
      if (width < 2) {
        sized = false;
        return;
      }
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      const fontFamily = getComputedStyle(canvas).fontFamily;
      const off = document.createElement("canvas").getContext("2d");
      if (off) {
        off.font = `${cellSize}px ${fontFamily}`;
        cellW = Math.max(4, off.measureText("MMMMMMMMMM").width / 10);
      }
      ctx.font = `${cellSize}px ${fontFamily}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";

      const nextCols = Math.max(16, Math.floor(width / cellW));
      if (nextCols !== cols) {
        cols = nextCols;
        cells = new Uint8Array(cols * BANDS);
        peakBand = new Uint8Array(cols).fill(255);
        peakDb = new Float32Array(cols);
        head = 0;
        if (!warmed) {
          // Settle the per-band floors BEFORE any visible column is committed,
          // with a boosted rise coefficient so ~300 hops reach where the real
          // 0.002 coefficient would need ~2000. Without it every band's floor
          // is still down at its -70 dB seed, everything clears the gate, and
          // the first visible field is a uniform medium-density wash.
          riseBoost = WARMUP_BOOST;
          for (let i = 0; i < WARMUP_HOPS; i++) analyse();
          riseBoost = 1;
          warmed = true;
        }
        for (let i = 0; i < Math.max(cols, SEED_COLS); i++) hop();
      }
      sized = true;
    };

    // -- cursor state (refs only; nothing on the hot path is React state) -----
    let cursorCol: number | null = null; // screen column, 0 = oldest/left
    let cursorAlpha = 0;

    const setReadout = () => {
      const live = liveRef.current;
      const cur = cursorTextRef.current;
      if (live) {
        // running summary: the loudest band across the whole visible window
        let bb = 255;
        let bd = -Infinity;
        for (let j = 0; j < cols; j++) {
          const c = (head + j) % cols;
          if (peakBand[c] === 255) continue;
          if (peakDb[c]! > bd) {
            bd = peakDb[c]!;
            bb = peakBand[c]!;
          }
        }
        live.textContent =
          bb === 255
            ? `no signal above floor · ${((cols * HOP_MS) / 1000).toFixed(1)} s window`
            : `peak ${fmtHz(BAND_START[bb]! * binHz)}  ${bd >= 0 ? "" : "−"}${Math.abs(bd).toFixed(0)} dB  · ${((cols * HOP_MS) / 1000).toFixed(1)} s window`;
      }
      if (cur) {
        if (cursorCol === null) cur.textContent = "";
        else {
          const c = (head + cursorCol) % cols;
          const age = ((cols - 1 - cursorCol) * HOP_MS) / 1000;
          const b = peakBand[c];
          cur.textContent =
            b === undefined || b === 255
              ? `— below floor  ${age.toFixed(1)} s ago`
              : `${fmtHz(BAND_START[b]! * binHz)}  ${peakDb[c]! >= 0 ? "" : "−"}${Math.abs(peakDb[c]!).toFixed(0)} dB  ${age.toFixed(1)} s ago`;
        }
      }
    };

    const draw = () => {
      if (!sized) return;
      const w = cols * cellW;
      ctx.clearRect(0, 0, w + cellW, rows * cellH);

      // field — pass one buckets, pass two draws one alpha per bucket
      for (let b = 0; b < ALPHA_BUCKETS; b++) bucketLists[b]!.length = 0;
      for (let j = 0; j < cols; j++) {
        const c = (head + j) % cols;
        const base = c * BANDS;
        for (let k = 0; k < BANDS; k++) {
          const idx = cells[base + k]!;
          if (idx === 0) continue;
          const bucket = Math.min(
            ALPHA_BUCKETS - 1,
            Math.floor(((idx - 1) / 9) * ALPHA_BUCKETS)
          );
          bucketLists[bucket]!.push((j << 8) | (k << 2) | 0);
        }
      }
      ctx.fillStyle = fg;
      for (let b = 0; b < ALPHA_BUCKETS; b++) {
        const list = bucketLists[b]!;
        ctx.globalAlpha = 0.22 + (b / (ALPHA_BUCKETS - 1)) * 0.78;
        for (let n = 0; n < list.length; n++) {
          const packed = list[n]!;
          const j = packed >> 8;
          const k = (packed >> 2) & 63;
          const c = (head + j) % cols;
          ctx.fillText(
            RAMP[cells[c * BANDS + k]!]!,
            j * cellW + cellW / 2,
            (1 + (BANDS - 1 - k)) * cellH + cellH * 0.5
          );
        }
      }

      // pitch track — the argmax band of each column, one accent dot drawn ON
      // its own row (a one-row strip cannot encode WHICH band won, so it
      // degenerates into a solid rule). Drawn after the field so it reads as a
      // contour riding over the dominant ribbon.
      ctx.fillStyle = accent;
      ctx.globalAlpha = 0.9;
      for (let j = 0; j < cols; j++) {
        const c = (head + j) % cols;
        const b = peakBand[c];
        if (b === undefined || b === 255) continue;
        ctx.fillText(
          "·",
          j * cellW + cellW / 2,
          (1 + (BANDS - 1 - b)) * cellH + cellH * 0.5
        );
      }

      // cursor — a measurement marker, never a distortion of the field
      if (cursorCol !== null && cursorAlpha > 0.01) {
        ctx.fillStyle = accent;
        ctx.globalAlpha = cursorAlpha * 0.8;
        const x = cursorCol * cellW + cellW / 2;
        for (let r = 1; r < rows; r++) ctx.fillText("┊", x, r * cellH + cellH * 0.5);
      }
      ctx.globalAlpha = 1;
    };

    const applyFade = () => {
      const cur = cursorTextRef.current;
      const live = liveRef.current;
      if (cur) cur.style.opacity = String(cursorAlpha);
      if (live) live.style.opacity = String(1 - cursorAlpha);
    };

    // -- loop ----------------------------------------------------------------
    let raf = 0;
    let last = 0;
    let acc = 0;

    const loop = (now: number) => {
      const dt = last ? Math.min(DT_MAX, (now - last) / 1000) : 1 / 60;
      last = now;
      acc += dt * 1000;
      let hops = 0;
      while (acc >= HOP_MS && hops < MAX_HOPS_PER_FRAME) {
        acc -= HOP_MS;
        hop();
        hops++;
      }
      if (acc > HOP_MS * MAX_HOPS_PER_FRAME) acc = 0;
      const target = cursorCol !== null ? 1 : 0;
      cursorAlpha += (target - cursorAlpha) * Math.min(1, dt / CURSOR_TAU);
      if (cursorCol === null && cursorAlpha < 0.01) cursorAlpha = 0;
      if (hops > 0 || cursorAlpha > 0) setReadout();
      applyFade();
      draw();
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    const colFromClientX = (clientX: number) => {
      const rect = canvas.getBoundingClientRect();
      const j = Math.floor((clientX - rect.left) / cellW);
      return j < 0 ? 0 : j > cols - 1 ? cols - 1 : j;
    };
    const onPointerMove = (e: PointerEvent) => {
      cursorCol = colFromClientX(e.clientX);
    };
    const onPointerLeave = () => {
      cursorCol = null;
    };

    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key !== "ArrowLeft" && e.key !== "ArrowRight") return;
      e.preventDefault();
      const step = e.key === "ArrowLeft" ? -1 : 1;
      const from = cursorCol === null ? cols - 1 : cursorCol + step;
      cursorCol = from < 0 ? 0 : from > cols - 1 ? cols - 1 : from;
      setReadout();
      // announce only on a deliberate key step — the 20 Hz running summary is
      // never put in the live region, which would be a screen-reader firehose
      const sr = srRef.current;
      if (sr) sr.textContent = cursorTextRef.current?.textContent ?? "";
      if (reduced) {
        cursorAlpha = 1;
        setReadout();
        applyFade();
        draw();
      }
    };
    const onBlur = () => {
      if (cursorCol !== null && document.activeElement !== readoutRef.current) {
        cursorCol = null;
        const sr = srRef.current;
        if (sr) sr.textContent = "";
        if (reduced) {
          cursorAlpha = 0;
          setReadout();
          applyFade();
          draw();
        }
      }
    };

    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) draw();
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
        setReadout();
        if (reduced) draw();
      }, 150);
    };

    const onVis = () => {
      // the frame queued before the tab hid is still pending — without this the
      // resumed loop runs alongside it and the hop rate silently doubles
      cancelAnimationFrame(raf);
      if (!document.hidden && !reduced && sized) {
        last = 0;
        acc = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const readout = readoutRef.current;
    readout?.addEventListener("keydown", onKeyDown);
    readout?.addEventListener("blur", onBlur);
    window.addEventListener("resize", onResize);
    document.addEventListener("visibilitychange", onVis);
    if (!reduced) {
      canvas.addEventListener("pointermove", onPointerMove);
      canvas.addEventListener("pointerleave", onPointerLeave);
    }

    document.fonts.ready.then(() => {
      if (disposed) return;
      readTokens();
      resize();
      setReadout();
      applyFade();
      draw();
      if (!reduced) raf = requestAnimationFrame(loop);
    });

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      mo.disconnect();
      readout?.removeEventListener("keydown", onKeyDown);
      readout?.removeEventListener("blur", onBlur);
      window.removeEventListener("resize", onResize);
      document.removeEventListener("visibilitychange", onVis);
      canvas.removeEventListener("pointermove", onPointerMove);
      canvas.removeEventListener("pointerleave", onPointerLeave);
    };
  }, [source, cellSize]);

  const fieldHeight = (BANDS + 1) * cellSize;

  return (
    <div className={`ns-sab w-full font-mono ${className}`}>
      <style>{CSS}</style>
      <div className="flex w-full items-start">
        <div
          ref={gutterRef}
          aria-hidden="true"
          className="relative shrink-0"
          style={{ width: cellSize * 4.2, height: fieldHeight }}
        >
          {LABEL_BANDS.map((b) => (
            <span
              key={b}
              data-band={b}
              className="absolute right-0 flex items-center justify-end pr-2 text-ns-muted"
              style={{
                top: (1 + (BANDS - 1 - b)) * cellSize,
                height: cellSize,
                fontSize: Math.max(9, cellSize * 0.62),
                lineHeight: 1,
              }}
            />
          ))}
        </div>
        <canvas
          ref={canvasRef}
          aria-hidden="true"
          className="block min-w-0 flex-1 text-foreground"
          style={{ height: fieldHeight }}
        />
      </div>
      <div
        ref={readoutRef}
        tabIndex={0}
        role="group"
        aria-label={label}
        className="ns-sab-readout relative mt-2 block w-full rounded-sm border border-border px-3 outline-none"
        style={{ height: cellSize * 1.9, fontSize: Math.max(10, cellSize * 0.68) }}
      >
        <span
          ref={liveRef}
          className="absolute inset-0 flex items-center px-3 text-ns-muted"
        />
        <span
          ref={cursorTextRef}
          className="absolute inset-0 flex items-center px-3 text-foreground"
          style={{ opacity: 0 }}
        />
        <span ref={srRef} aria-live="polite" className="ns-sab-sr" />
      </div>
    </div>
  );
}

const CSS = `
.ns-sab-readout:focus { outline: 2px solid var(--ns-accent); outline-offset: 2px; }
.ns-sab-readout:hover { border-color: var(--ns-accent); }
.ns-sab-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
`;

"use client";

import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// SpindleStrike — payment history as a diner-receipt spindle. Every settled
// transaction is a small card impaled on a shared 1px vertical spine
// (--border), newest closest to the top. The whole thing hangs off ONE
// governing scalar per card, `rawY` (px along the spine, computed once in
// JS from that card's recency index * an 8px CARD_GAP), and everything else
// — translateY, z-index, and how far its ink has drifted from --foreground
// toward --ns-muted — is derived from that same number, never chosen
// independently. A brand-new settlement starts CARD_ENTER_DROP above its
// landing spot and opacity 0; clearing that offset one frame later lets the
// existing transform/opacity transition (one shared rule, one
// cubic-bezier(.34,1.56,.64,1) overshoot, 500ms, on every card alike — no
// per-card delay or stagger) carry it down and past its rest position once,
// which reads as "struck the spike and the pile gave". Because every other
// card's rawY is also just index*CARD_GAP, the same single transition rule
// is what makes the rest of the pile appear to shove down in sync — there
// is no separate "shove" animation to keep in step with the drop.
//
// A refund does NOT remove or restyle a row. The existing <li> is the one
// DOM node that keeps moving: its rawY gets a fixed REFUND_LIFT subtracted,
// pulling it a short distance back up the spine from wherever it already
// sat (usually clear of the whole pile, since refunds mostly land on
// something still near the top) — same node, same puncture, now elongated
// from a 3px dot into a slot, because the paper visibly slid along the pin
// rather than coming off it. Depth-darkening reads off the *unshifted* rawY,
// so a lifted refund reads brighter (less "handled"), and z-index is
// `constant - rawY`, so whichever card ends up highest on the spine wins
// the stack order for free, refunded or not — EXCEPT that REFUND_LIFT is
// deliberately an exact multiple of CARD_GAP (see below), so a refunded
// card's rawY can exactly equal a settled card's rawY, and once it does it
// STAYS equal every press after (both age by the same CARD_GAP per settle,
// nothing resolves the tie on its own). Two cards genuinely sharing a
// z-index falls back to paint order, i.e. whichever <li> is later in the
// DOM — arbitrary from the model's point of view, and it is what let a
// refunded card sit permanently hidden behind a same-z settled card for
// several presses in a row, reading as "the refund did nothing" even
// though rawY says it should be frontmost. zIndex below breaks that tie
// explicitly, in the refund's favor, instead of leaving it to paint order.
//
// Fully controlled: `transactions` is the only data in, in caller-supplied
// chronological order (oldest first) — that is also the <li> DOM order,
// independent of the visual stacking, so a screen reader always gets the
// story in time order even though sighted users see newest-on-top. Rotation
// is a djb2-style hash of the id, not Math.random(), so SSR and client
// renders agree and re-renders don't jitter; it's capped at +-3deg because
// beyond that the amount stops being legible at rest. Colors are
// var(--background/--foreground/--ns-muted/--border) only, composed with
// color-mix() for the depth ramp — no hex, no --ns-accent except the
// keyboard focus ring, which is the one interaction highlight. Cards are
// individually focusable; focus lifts one 2px clear of the pile via
// translateY + z-index only (JS-tracked, not CSS transform on top of the
// base transform, so it composes with rotation cleanly) — no scale, no
// opacity change, so the receipt's text never shifts size under focus.
// prefers-reduced-motion shortens the entrance drop and every
// transform/opacity/color transition to a brief, linear pass instead of
// dropping them — positions still update, but as a short visible move
// rather than an instant snap; rotation, being static already, is
// unaffected either way. Refunds fire one
// aria-live announcement naming the amount returned; each row also carries
// a real <dl> (date/amount/status) so "refunded" is legible as text, not
// only as position.
// ---------------------------------------------------------------------------

export interface SpindleTransaction {
  /** stable identifier — also the seed for this card's fixed rotation */
  id: string;
  /** display date, e.g. "Aug 14" */
  date: string;
  /** original settled amount, in dollars */
  amount: number;
  /** "refunded" pulls the existing card up the spine instead of removing it */
  status: "settled" | "refunded";
  /** amount returned; defaults to `amount` when refunded and omitted */
  refundedAmount?: number;
}

export interface SpindleStrikeProps {
  /** the receipts, in chronological order (oldest first) — also the DOM order */
  transactions: SpindleTransaction[];
  /** accessible name for the <ol>. default "Payment history" */
  ariaLabel?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const CARD_GAP = 8; // px the stack shoves per settled receipt — the one shared scalar step
const REFUND_LIFT = 6 * CARD_GAP; // px an existing card is pulled back up the spine on refund —
// kept as an exact multiple of CARD_GAP (not a literal) so a refund six settles back reaches the
// same rawY as the settled card born 6 presses later, rather than staying permanently deeper (and
// permanently z-behind) than every new arrival, which is what made refund reads look inert on the
// first pass. Because it's an exact multiple, that rawY match is an exact tie, and because both
// cards age by the same CARD_GAP every subsequent settle, the tie does not resolve itself — it
// holds for as long as both cards share the pile. Z_TIE_BREAK below (not paint order) decides it.
const MAX_DARK_DEPTH = 14 * CARD_GAP; // px of rawY at which the darken ramp maxes out — scales
// with CARD_GAP so the same ~14-receipt pile depth still spans the full ramp instead of pegging
// every card past the fourth or fifth at max darkness.
const MAX_DARK_PCT = 62; // darkest a receipt gets — never fully --ns-muted, still legible
const ENTER_DROP = 90; // px a newly-struck card starts above its landing spot at rest (full
// travel, no-preference motion) — big enough that the strike reads as landing, not fading in.
const ENTER_DROP_REDUCED = 14; // px equivalent under prefers-reduced-motion: reduce — a short,
// small-amplitude offset (not zero) so a press still visibly moves rather than snapping silently.
const CARD_WIDTH = 216;
const CARD_HEIGHT = 88; // reserved layout height per card, top-of-stack
const Z_SCALE = 100; // multiplies every real (3000 - rawY) gap before the tie-break is added, so
// Z_TIE_BREAK can never leak into ordering two cards whose rawY actually differs (the smallest
// real gap is one CARD_GAP, i.e. >=800 once scaled — comfortably clear of a +/-1 nudge).
const Z_TIE_BREAK = 1; // an exact rawY tie (REFUND_LIFT lands a refunded card on a settled card's
// slot) is resolved in the refund's favor, explicitly, instead of falling through to paint/DOM
// order — which is what let a refunded card sit invisibly behind a same-depth settled card.
const Z_LIFTED = 10_000_000; // focus-lift always wins regardless of the scaled range above

function hashRotation(id: string): number {
  let h = 0;
  for (let i = 0; i < id.length; i++) {
    h = (Math.imul(h, 31) + id.charCodeAt(i)) | 0;
  }
  const norm = (((h % 2000) + 2000) % 2000) / 2000; // 0..1, deterministic
  return Math.round((norm * 2 - 1) * 3 * 100) / 100; // -3..3 deg, stable across SSR/re-renders
}

function clamp(n: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, n));
}

export function SpindleStrike({
  transactions,
  ariaLabel = "Payment history",
  className = "",
}: SpindleStrikeProps) {
  const [reducedMotion, setReducedMotion] = useState(false);
  const [enteringIds, setEnteringIds] = useState<Set<string>>(() => new Set());
  const [focusedId, setFocusedId] = useState<string | null>(null);
  const [liveMsg, setLiveMsg] = useState("");
  const prevStatusRef = useRef<Map<string, SpindleTransaction["status"]>>(new Map());
  const mountedRef = useRef(false);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReducedMotion(mq.matches);
    update();
    mq.addEventListener("change", update);
    return () => mq.removeEventListener("change", update);
  }, []);

  // Diff against the previous render to find newly-struck ids and any
  // settled -> refunded transitions — never derived from `turn`-less state,
  // so callers can add or refund in any order without extra bookkeeping.
  // useLayoutEffect, not useEffect: this must set the entering offset
  // BEFORE the browser paints. A brand-new card's very first render
  // otherwise commits at rest (entering hasn't been set yet, since a
  // regular effect runs post-paint) and the browser paints that resting
  // frame — so the offset that follows a moment later is read as an
  // actual FROM-rest transition, which the retarget-to-rest then
  // interrupts almost immediately. Measured: with useEffect, the drop
  // collapsed to a ~1px blip regardless of ENTER_DROP's value, worst on
  // the reduced-motion path where the short transition leaves no room to
  // recover. With useLayoutEffect, entering is already true by the first
  // paint, so the offset is the genuine starting point, no false start.
  useLayoutEffect(() => {
    const prev = prevStatusRef.current;
    if (mountedRef.current) {
      const added: string[] = [];
      let refundedNow: SpindleTransaction | null = null;
      for (const t of transactions) {
        const before = prev.get(t.id);
        if (before === undefined) added.push(t.id);
        else if (before === "settled" && t.status === "refunded") refundedNow = t;
      }
      if (added.length > 0) {
        // Reduced motion still gets an entering pass — just a short one
        // (ENTER_DROP_REDUCED, a fast linear CSS transition below) instead
        // of skipping straight to rest. A silent snap reads identically to
        // "nothing happened" to anyone who can't see the drop; a brief,
        // small-amplitude move reads as the strike landing without the
        // spring overshoot. Merge rather than replace: a second card struck
        // while the first is still entering must not drop the first from the
        // set before its own clear fires below.
        setEnteringIds((cur) => {
          const next = new Set(cur);
          for (const id of added) next.add(id);
          return next;
        });
      }
      if (refundedNow) {
        const back = refundedNow.refundedAmount ?? refundedNow.amount;
        setLiveMsg(`Refunded: ${refundedNow.date}, $${refundedNow.amount.toFixed(2)} — $${back.toFixed(2)} returned`);
      }
    }
    prevStatusRef.current = new Map(transactions.map((t) => [t.id, t.status]));
    mountedRef.current = true;
  }, [transactions, reducedMotion]);

  // Owns the entering-flag's clear, independent of whatever triggered
  // enteringIds to become non-empty. Previously this timer lived inline in
  // the diff effect above and was only *rescheduled* when that effect found
  // a newly-added id — but React tears down and reruns that whole effect
  // (cancelling any pending timer via its cleanup) on every `transactions`
  // change, added or not. A refund landing on a card within its own 32ms
  // entering window re-ran the diff effect with `added: []` (the card
  // already existed), which cancelled the pending clear but scheduled no
  // replacement: `entering` stayed true forever, pinning that card at
  // opacity 0 with its entrance offset applied — permanently invisible.
  // Keying this effect on `enteringIds` itself instead means it reschedules
  // exactly when the set actually changes, and an unrelated transactions
  // update (like that refund) that doesn't touch enteringIds can't cancel a
  // clear that's already in flight.
  useEffect(() => {
    if (enteringIds.size === 0) return;
    const clearTimer = setTimeout(() => setEnteringIds(new Set()), 32);
    return () => clearTimeout(clearTimer);
  }, [enteringIds]);

  // Recency index among ALL receipts (refunded ones included), newest = 0.
  // Refunded cards keep the index their position implies, so the pile below
  // them keeps its own spacing rather than closing the gap — the missing
  // step reads as the slot the receipt was pulled out of.
  const baseIndexById = useMemo(() => {
    const map = new Map<string, number>();
    const desc = [...transactions].reverse();
    desc.forEach((t, i) => map.set(t.id, i));
    return map;
  }, [transactions]);

  const layout = useMemo(() => {
    const raw = transactions.map((t) => {
      const baseIndex = baseIndexById.get(t.id) ?? 0;
      const rawY = baseIndex * CARD_GAP - (t.status === "refunded" ? REFUND_LIFT : 0);
      return { id: t.id, rawY };
    });
    const minY = Math.min(0, ...raw.map((r) => r.rawY));
    const maxY = Math.max(0, ...raw.map((r) => r.rawY));
    const topPad = -minY;
    const height = CARD_HEIGHT + (maxY - minY);
    const byId = new Map(raw.map((r) => [r.id, { rawY: r.rawY, shiftedY: r.rawY + topPad }]));
    return { byId, height, topPad };
  }, [transactions, baseIndexById]);

  return (
    <div className={["ns-spindle relative mx-auto", className].join(" ")} style={{ width: CARD_WIDTH + 40, height: layout.height }}>
      <style>{`
.ns-spindle-spine{position:absolute;top:0;bottom:0;left:50%;width:1px;background:var(--border);transform:translateX(-0.5px);pointer-events:none}
.ns-spindle-list{position:relative;margin:0;padding:0;height:100%;list-style:none}
.ns-spindle-card{
  position:absolute;
  left:50%;
  top:0;
  width:${CARD_WIDTH}px;
  padding:20px 14px 12px;
  border-radius:12px;
  box-shadow:0 1px 3px color-mix(in srgb, var(--foreground) 14%, transparent);
  transition:transform 560ms cubic-bezier(.34,1.56,.64,1), opacity 460ms ease-out, color 560ms ease-out;
  cursor:default;
}
.ns-spindle-card:focus-visible{outline:2px solid var(--ns-accent);outline-offset:2px}
.ns-spindle-puncture{
  position:absolute;
  left:50%;
  top:16px;
  width:3px;
  height:3px;
  border-radius:9999px;
  background:color-mix(in srgb, var(--foreground) 45%, var(--ns-muted));
  transform:translate(-50%,-50%) scale(1);
  opacity:1;
  transition:width 320ms cubic-bezier(.22,1,.36,1), height 320ms cubic-bezier(.22,1,.36,1),
    opacity 160ms ease-out 380ms, transform 160ms cubic-bezier(.34,1.56,.64,1) 380ms;
}
.ns-spindle-card[data-status="refunded"] .ns-spindle-puncture{width:3px;height:13px;border-radius:9999px}
.ns-spindle-card[data-entering="true"] .ns-spindle-puncture{opacity:0;transform:translate(-50%,-50%) scale(.25)}
.ns-spindle-dl{margin:6px 0 0}
