"use client";

import { useEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// GantryRun — a scroll-scrubbed, infinitely-looping 3D card gallery. Cards
// hang off a receding gantry track: real CSS `perspective` + `preserve-3d`
// does the projection (translate3d/rotateY per card, written directly to
// each card's ref every frame — no React state on the hot path), the browser
// computes the actual on-screen scale and foreshortening.
//
// The loop is a buffer trick: the item list is rendered twice back to back
// along the track, and scroll progress drives a camera distance that runs
// exactly the length of ONE set before the pass completes — so by the time
// the last real card has receded out of view, its duplicate is already
// approaching from the far end, and the whole thing reads as an unbroken
// belt. There is no distance-to-mouse magnetism per card (that always reads
// as N springs firing independently as the pointer crosses the grid) —
// instead the track itself tilts toward the pointer like a specimen tray,
// and whichever card currently sits nearest the camera (by depth, not by
// pointer distance) gets a procedural focus highlight and its title is
// pushed into a live readout — the "camera" itself is what has attention,
// not the mouse.
// ---------------------------------------------------------------------------

export interface GantryItem {
  id: string;
  title: string;
  caption?: string;
}

export interface GantryRunProps {
  /** the gallery images, in order */
  items?: GantryItem[];
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const DEFAULT_ITEMS: GantryItem[] = [
  { id: "01", title: "Signal Plate", caption: "Rev. A" },
  { id: "02", title: "Trace Coil", caption: "Rev. C" },
  { id: "03", title: "Bench Jig", caption: "Rev. B" },
  { id: "04", title: "Vernier Set", caption: "Rev. A" },
  { id: "05", title: "Ratchet Frame", caption: "Rev. D" },
  { id: "06", title: "Sounding Rail", caption: "Rev. B" },
  { id: "07", title: "Gantry Head", caption: "Rev. A" },
  { id: "08", title: "Solder Bridge", caption: "Rev. C" },
];

const STEP_X = 34; // px lateral drift per card
const STEP_Y = -16; // px vertical rise per card
const STEP_Z = 260; // px receding depth per card
const FOCUS_WINDOW = 130; // depth window (px) counted as "in focus"

function useReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const onChange = () => setReduced(mq.matches);
    onChange();
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

export function GantryRun({ items = DEFAULT_ITEMS, className = "" }: GantryRunProps) {
  const sectionRef = useRef<HTMLElement>(null);
  const trackRef = useRef<HTMLDivElement>(null);
  const cardRefs = useRef<(HTMLDivElement | null)[]>([]);
  const labelRef = useRef<HTMLSpanElement>(null);
  const reduced = useReducedMotion();
  const doubled = [...items, ...items];
  const loopDistance = items.length * STEP_Z;

  useEffect(() => {
    const section = sectionRef.current;
    const track = trackRef.current;
    if (!section || !track) return;

    let raf = 0;
    let p = 0; // scroll progress 0..1
    let tiltX = 0;
    let tiltY = 0;
    let tiltTargetX = 0;
    let tiltTargetY = 0;
    let focusIndex = -1;
    let dirty = true;

    const frame = () => {
      dirty = false;
      const camZ = p * loopDistance;

      const k = 0.1;
      tiltX += (tiltTargetX - tiltX) * k;
      tiltY += (tiltTargetY - tiltY) * k;
      track.style.transform = `rotateX(${tiltY.toFixed(3)}deg) rotateY(${tiltX.toFixed(3)}deg)`;

      let bestDz = Infinity;
      let bestIdx = -1;
      for (let i = 0; i < doubled.length; i++) {
        const el = cardRefs.current[i];
        if (!el) continue;
        const worldZ = i * STEP_Z;
        const dz = worldZ - camZ;
        const adz = Math.abs(dz);
        if (adz < bestDz) {
          bestDz = adz;
          bestIdx = i;
        }
        // cull cards far behind the camera or far down the track
        if (dz < -STEP_Z * 1.5 || dz > loopDistance + STEP_Z * 1.5) {
          el.style.opacity = "0";
          continue;
        }
        const worldX = i * STEP_X;
        const worldY = i * STEP_Y;
        const inFocus = adz < FOCUS_WINDOW;
        const scale = inFocus ? 1.05 : 1;
        el.style.transform = `translate3d(${worldX}px, ${worldY}px, ${(-dz).toFixed(1)}px) rotateY(-6deg) scale(${scale})`;
        const fade = Math.max(0, 1 - Math.max(0, dz + STEP_Z) / (loopDistance * 0.55));
        el.style.opacity = String(Math.min(1, Math.max(0, fade)));
        el.dataset.focused = inFocus ? "true" : "false";
      }

      if (bestIdx !== focusIndex && bestIdx >= 0) {
        focusIndex = bestIdx;
        const item = items[bestIdx % items.length];
        if (labelRef.current && item) {
          labelRef.current.textContent = `${item.id} — ${item.title}`;
        }
      }

      const tiltSettled = Math.abs(tiltTargetX - tiltX) < 0.02 && Math.abs(tiltTargetY - tiltY) < 0.02;
      if (!dirty && tiltSettled) {
        raf = 0;
        return;
      }
      raf = requestAnimationFrame(frame);
    };

    const wake = () => {
      if (!raf) raf = requestAnimationFrame(frame);
    };

    const readScroll = () => {
      const rect = section.getBoundingClientRect();
      const trackLen = rect.height - window.innerHeight;
      p = trackLen > 0 ? Math.min(1, Math.max(0, -rect.top / trackLen)) : 0;
      dirty = true;
      wake();
    };

    const onPointer = (e: PointerEvent) => {
      const rect = section.getBoundingClientRect();
      const vw = window.innerWidth;
      const vh = Math.min(window.innerHeight, rect.height);
      tiltTargetX = ((e.clientX - vw / 2) / vw) * 14;
      tiltTargetY = -((e.clientY - vh / 2) / vh) * 8;
      dirty = true;
      wake();
    };
    const onLeave = () => {
      tiltTargetX = 0;
      tiltTargetY = 0;
      dirty = true;
      wake();
    };

    readScroll();
    wake();
    window.addEventListener("scroll", readScroll, { passive: true });
    window.addEventListener("resize", readScroll);
    window.addEventListener("pointermove", onPointer, { passive: true });
    window.addEventListener("pointerleave", onLeave);
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("scroll", readScroll);
      window.removeEventListener("resize", readScroll);
      window.removeEventListener("pointermove", onPointer);
      window.removeEventListener("pointerleave", onLeave);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [items.length, loopDistance, reduced]);

  // prefers-reduced-motion: no scroll scrub, no 3D tilt, no receding track —
  // a plain static grid of the same cards, same tokens, same focus styling
  // rules minus the depth-driven trigger.
  if (reduced) {
    return (
      <section data-gallery-gantry-track data-gantry-viewport className={`bg-background px-6 py-16 ${className}`}>
        <div className="mx-auto flex max-w-4xl items-center justify-between pb-6">
          <span className="font-mono text-xs uppercase tracking-widest text-ns-muted">Gantry catalog</span>
          <span className="font-mono text-xs tabular-nums text-foreground">{items.length} items</span>
        </div>
        <div className="mx-auto grid max-w-4xl grid-cols-2 gap-4 sm:grid-cols-4">
          {items.map((item) => (
            <div
              key={item.id}
              data-gantry-card
              className="flex h-[220px] flex-col justify-between rounded-[12px] border border-border bg-surface p-4 shadow-sm"
            >
              <span className="font-mono text-[10px] uppercase tracking-widest text-ns-muted">{item.id}</span>
              <div
                aria-hidden
                className="h-16 w-full rounded-sm border border-border"
                style={{
                  backgroundImage:
                    "repeating-linear-gradient(135deg, var(--border) 0px, var(--border) 1px, transparent 1px, transparent 9px)",
                }}
              />
              <div>
                <p className="truncate text-sm font-medium text-foreground">{item.title}</p>
                {item.caption ? <p className="truncate text-xs text-ns-muted">{item.caption}</p> : null}
              </div>
            </div>
          ))}
        </div>
      </section>
    );
  }

  return (
    <section ref={sectionRef} data-gallery-gantry-track className={`relative h-[400vh] bg-background ${className}`}>
      <div data-gantry-viewport className="sticky top-0 flex h-screen w-full flex-col overflow-hidden">

        <div
          data-gantry-stage
          className="flex flex-1 items-center justify-center"
          style={{ perspective: "1400px", perspectiveOrigin: "50% 45%" }}
        >
          <div ref={trackRef} className="relative h-0 w-0" style={{ transformStyle: "preserve-3d" }}>
            {doubled.map((item, i) => (
              <div
                key={`${item.id}-${i}`}
                ref={(el) => {
                  cardRefs.current[i] = el;
                }}
                data-gantry-card
                className="absolute flex h-[220px] w-[168px] -translate-x-1/2 -translate-y-1/2 flex-col justify-between rounded-[12px] border bg-surface p-4 shadow-sm transition-[border-color,box-shadow] duration-200 ease-out data-[focused=true]:border-ns-accent data-[focused=true]:shadow-md"
                style={{ borderColor: "var(--border)", transformStyle: "preserve-3d" }}
              >
                <span className="font-mono text-[10px] uppercase tracking-widest text-ns-muted">{item.id}</span>
                <div
                  aria-hidden
                  className="h-16 w-full rounded-sm border border-border"
                  style={{
                    backgroundImage:
                      "repeating-linear-gradient(135deg, var(--border) 0px, var(--border) 1px, transparent 1px, transparent 9px)",
                  }}
                />
                <div>
                  <p className="truncate text-sm font-medium text-foreground">{item.title}</p>
                  {item.caption ? <p className="truncate text-xs text-ns-muted">{item.caption}</p> : null}
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="pointer-events-none absolute inset-x-0 bottom-6 flex flex-col items-center gap-1.5">
          <span ref={labelRef} className="font-mono text-xs tabular-nums text-foreground">
            {items[0] ? `${items[0].id} — ${items[0].title}` : ""}
          </span>
          <p className="text-center font-mono text-[11px] tracking-widest text-ns-muted">SCROLL TO RUN THE GANTRY</p>
        </div>
      </div>
    </section>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// GranuleChurn — a full-bleed stellar photosphere. Solar granulation: bright
// upwelling convection cells packed edge to edge, separated by the dark
// intergranular lanes the cooled material drains back down through.
//
// The mechanism is a small compressible surface flow, not a cell diagram.
// A potential field S(x,y,t) is built from a lattice of gaussian plumes, each
// born at a jittered position, swelling over its own lifetime and fading out
// again. Horizontal velocity is u = -k grad(S), so material runs DOWNHILL away
// from every plume's summit and piles up in the troughs where three or four
// plumes' skirts meet. Nothing anywhere computes a nearest-site distance: the
// lanes are not the edges of a partition, they are where a real advected
// density has been squeezed together, and they inherit a fluid's memory —
// varying width, broken segments, a lag behind the plumes that pushed them.
//
// Four channels ride one RGBA16F ping-pong target and are advected by that
// same velocity in a single semi-Lagrangian pass:
//   T  temperature — injected where the flow diverges (a granule's summit),
//      cooling radiatively as it travels out, so a cell is hot in the middle
//      and dim by the time it reaches its own boundary
//   c  material density — multiplied by exp(-div u dt), the continuity term,
//      which is what actually darkens a lane rather than a painted stroke
//   f  faculae — bright flecks seeded stochastically in the strongest
//      downdrafts and carried along the lane they were born in
//   a  pointer freshness — lifts luminance under the cursor. Pure brightness,
//      no hue: --ns-accent is reserved for interaction chrome elsewhere in the
//      registry, and a resting frame (which is what every screenshot is) has
//      no pointer "interacting" with it, so no accent belongs in this pass
//
// Birth and death are structural. Each lattice site runs its own period; when
// a plume's envelope reaches zero its successor is born at a new jittered
// position with a new radius, so its neighbours immediately expand into the
// space and the lane network re-knits. Sites drawn above a threshold develop
// an "exploding granule" late in life — a negative dimple opening at the
// summit that pushes a new lane straight through the middle of the cell and
// splits it in two, which is exactly how the real ones die.
//
// Palette: five stops from --background, --foreground, --ns-muted and --border
// via getComputedStyle, re-read on a documentElement class MutationObserver.
// The ramp INVERTS between themes rather than shifting its distribution: dark
// theme is a luminous star, light theme its deliberate negative — graphite
// granules on a paper field, tuned so the frame stays mid-toned instead of
// going to a black page. No colour literal appears anywhere, shaders included.
// ---------------------------------------------------------------------------

export interface GranuleChurnProps {
  /** Granule count: cells across the container's short side. @default 1 */
  density?: number;
  /** Convection speed multiplier. @default 1 */
  speed?: number;
  /** Faculae (bright lane flecks) amount, 0 disables them. @default 1 */
  faculae?: number;
  /** Freezes the surface on a fully developed still frame without unmounting. */
  paused?: boolean;
  /** Rendered in the DOM over the surface — eyebrow, headline, CTA. */
  children?: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
}

const VERT_SRC = `#version 300 es
in vec2 a_pos;
out vec2 v_uv;
void main() {
  v_uv = a_pos * 0.5 + 0.5;
  gl_Position = vec4(a_pos, 0.0, 1.0);
}`;

// Shared by both passes. Coordinates are in LATTICE CELLS, isotropic in screen
// space: q = vec2(uv.x * aspect, uv.y) * cells. Working in uv instead would
// make every gaussian an ellipse that restretches with the window, and would
// make the divergence operator anisotropic — which on a compressible flow is
// not a cosmetic error, it is lanes that are systematically wider in one axis.
const COMMON = `
precision highp float;

uniform float u_aspect;
uniform float u_cells;
uniform float u_time;

vec3 hash32(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
  p3 += dot(p3, p3.yxz + 33.33);
  return fract((p3.xxy + p3.yzz) * p3.zyx);
}

vec4 hash42(vec2 p) {
  vec4 p4 = fract(vec4(p.xyxy) * vec4(0.1031, 0.1030, 0.0973, 0.1099));
  p4 += dot(p4, p4.wzxy + 33.33);
  return fract((p4.xxyz + p4.yzzw) * p4.zywx);
}

float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  float a = hash32(i).x;
  float b = hash32(i + vec2(1.0, 0.0)).x;
  float c = hash32(i + vec2(0.0, 1.0)).x;
  float d = hash32(i + vec2(1.0, 1.0)).x;
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

vec2 cellCoord(vec2 uv) {
  return vec2(uv.x * u_aspect, uv.y) * u_cells;
}
`;

// The plume lattice. One site per lattice cell, three by three neighbours
// gathered — with a jitter of 0.36 cells and a radius under half a cell, a
// contribution from further out is below 1e-5 and invisible.
//
// Returns (S, dS/dx, dS/dy, laplacian S). Having the laplacian analytically is
// what makes the whole thing cheap: divergence of u = -k grad(S) is exactly
// -k lap(S), so the compression that builds the lanes needs no extra taps.
//
// A supergranular warp is applied to the lookup coordinate before the gather.
// Without it the lattice reads as a lattice within about two seconds of
// looking — jitter alone leaves every cell centre inside its own square, and
// the eye finds that grid immediately on a full-bleed field. The warp is slow
// and shallow enough that its Jacobian stays close to identity, so the
// gradient taken in warped coordinates is still very nearly the true one.
const PLUMES = `
uniform float u_split;

vec2 warp(vec2 q) {
  return q + 0.62 * vec2(
    vnoise(q * 0.115 + vec2(0.0, u_time * 0.012)) - 0.5,
    vnoise(q * 0.115 + vec2(9.71, -u_time * 0.009) + 4.3) - 0.5
  ) + 0.26 * vec2(
    vnoise(q * 0.31 + vec2(u_time * 0.02, 2.1)) - 0.5,
    vnoise(q * 0.31 + vec2(-1.7, u_time * 0.017) + 8.9) - 0.5
  )
  // a third octave at sub-cell scale. The two above move whole groups of
  // granules around; this one is what stops each individual cell from being a
  // circle. Real granules are ragged polygons, and the difference between
  // "photosphere" and "soap foam" is almost entirely in the boundary: a
  // perfectly round cell reads as a bubble no matter what its interior does.
  // Amplitude is held under a tenth of a cell so the warp's Jacobian stays
  // near identity and the gradient taken in warped coordinates is still the
  // true one.
  + 0.085 * vec2(
    vnoise(q * 0.95 + vec2(u_time * 0.03, 5.3)) - 0.5,
    vnoise(q * 0.95 + vec2(3.9, -u_time * 0.026) + 1.7) - 0.5
  );
}

vec4 plumes(vec2 q) {
  vec2 base = floor(q);
  vec4 acc = vec4(0.0);
  for (int j = -1; j <= 1; j++) {
    for (int i = -1; i <= 1; i++) {
      vec2 id = base + vec2(float(i), float(j));
      vec4 h = hash42(id);
      // every site keeps its own period and phase, so births are decorrelated
      // across the field: a shared clock makes the entire surface pulse
      float per = mix(8.5, 16.5, h.x);
      float u = u_time / per + h.y * 11.0;
      float gen = floor(u);
      float life = u - gen;
      // a new draw per generation — position, size and fate all change when a
      // site's plume is replaced, which is what makes neighbours jostle
      vec3 g = hash32(id * 1.37 + vec2(gen * 19.73, gen * 7.31) + 3.1);
      vec2 c = id + 0.5 + (g.xy - 0.5) * 0.72;
      float rad = mix(0.30, 0.47, g.z) * (0.78 + 0.52 * life);
      float amp = pow(sin(3.14159265 * life), 0.7);
      vec2 d = q - c;
      float ir2 = 1.0 / (rad * rad);
      float r2 = dot(d, d) * ir2;
      float e = exp(-r2) * amp;
      acc.x += e;
      acc.yz += e * (-2.0 * d * ir2);
      acc.w += e * (4.0 * r2 * ir2 - 4.0 * ir2);

      // exploding granule: a dimple opens at the summit late in life, so a
      // lane is driven through the middle of the cell and it splits rather
      // than simply fading. Roughly a third of sites are drawn for it.
      //
      // The dimple has to be BROAD, not deep. At rad*0.44 it was narrower than
      // the sim texel scale, so instead of splitting the cell it punched a
      // single-texel negative spike that clamped T to zero — a hard black
      // pinprick sitting in the middle of a bright granule, which read as a
      // rendering defect rather than as a pore. At 0.66 of the parent radius
      // the dimple is wide enough that the flow actually reverses across a
      // band, which is what drives a lane through and cleaves the cell in two.
      float fate = step(0.66, h.z) * u_split;
      float amp2 = fate * amp * 0.46 * smoothstep(0.48, 0.92, life);
      float rad2 = rad * 0.66;
      float ir2b = 1.0 / (rad2 * rad2);
      float r2b = dot(d, d) * ir2b;
      float eb = exp(-r2b) * amp2;
      acc.x -= eb;
      acc.yz -= eb * (-2.0 * d * ir2b);
      acc.w -= eb * (4.0 * r2b * ir2b - 4.0 * ir2b);
    }
  }
  return acc;
}
`;

// One pass per step: velocity is evaluated analytically at the destination
// pixel, all four channels ride one backtrace, and every source term lands in
// the same write. There is no pressure solve because there is nothing to
// project — a photosphere's surface flow is COMPRESSIBLE by construction, and
// the divergence is not an error to be removed, it is the entire signal.
const SIM_SRC = `#version 300 es
${COMMON}
${PLUMES}
in vec2 v_uv;
out vec4 fragColor;

uniform sampler2D u_field;
uniform vec2 u_texel;
uniform vec2 u_grid;
uniform float u_dt;
uniform float u_flow;
uniform float u_fleck;
uniform vec3 u_ptr;      // xy uv, z strength
uniform float u_ptrAcc;

void main() {
  vec2 q = warp(cellCoord(v_uv));
  vec4 P = plumes(q);

  // the pointer is an extra upwelling: it pushes the lanes apart and floats
  // fresh hot material up under the cursor, the same way every other plume
  // does, so the interaction is the mechanism rather than a decal on it
  if (u_ptr.z > 0.0) {
    vec2 pc = cellCoord(u_ptr.xy);
    vec2 d = q - pc;
    float rad = 1.35;
    float ir2 = 1.0 / (rad * rad);
    float r2 = dot(d, d) * ir2;
    float e = exp(-r2) * u_ptr.z * 1.5;
    P.x += e;
    P.yz += e * (-2.0 * d * ir2);
    P.w += e * (4.0 * r2 * ir2 - 4.0 * ir2);
  }

  vec2 vel = -u_flow * P.yz;      // cells/s
  float div = -u_flow * P.w;      // 1/s

  // soft walls: without them the outward half of every edge plume drags the
  // clamped border texel inward across a tenth of the frame
  vec2 edge = smoothstep(vec2(0.0), vec2(0.035, 0.035 * u_aspect), min(v_uv, 1.0 - v_uv));
  vel *= min(edge.x, edge.y) * 0.85 + 0.15;

  vec2 duv = vel * u_dt / u_cells * vec2(1.0 / u_aspect, 1.0);
  vec4 s = texture(u_field, v_uv - duv);

  float T = s.x;
  float c = s.y;
  float f = s.z;
  float a = s.w;

  // continuity. This single line is what makes a lane: converging flow
  // multiplies the density it carries, diverging flow thins it out, and the
  // result is a network whose brightness records how hard the surface has been
  // squeezing there rather than where a boundary was declared to be.
  c *= exp(-div * u_dt * 0.052);
  c += (1.0 - c) * (1.0 - exp(-u_dt / 22.0));
  c = clamp(c, 0.12, 4.0);

  // radiative cooling on the way out from the summit is what gives a granule
  // its interior falloff, and the rate has to be tuned against the crossing
  // time rather than to taste: cool too slowly and every cell is one flat
  // plateau of the same value, which is foam, not a photosphere. At ~0.7s
  // against a ~0.5s centre-to-lane crossing, material arrives at its own
  // boundary noticeably dimmer than it left the summit.
  T += max(div, 0.0) * u_dt * 0.115;
  T -= T * u_dt * 1.45;
  T = clamp(T, 0.0, 3.0);

  // faculae: sparse, seeded on a 6Hz tick so the rate is independent of frame
  // rate, gated on both a piled-up lane and a live downdraft, then advected
  // with the lane that made them
  float lane = smoothstep(1.30, 2.10, c);
  float conv = smoothstep(0.30, 1.40, max(-div, 0.0));
  vec3 hs = hash32(floor(v_uv * u_grid * 0.5) + vec2(floor(u_time * 6.0) * 31.7));
  // the threshold is the seeding rate, and it was set so far out that a
  // 640x400 field produced under one live fleck at a time — invisible in the
  // dark theme, which is exactly where a bright point on a black lane should
  // be the most rewarding thing in the frame
  float spark = step(0.9991, hs.x) * lane * conv * u_fleck;
  f = max(f - f * u_dt * 2.3, spark * (0.55 + 0.75 * hs.y));

  a = max(a - a * u_dt * 0.9, u_ptrAcc * exp(-dot(cellCoord(v_uv) - cellCoord(u_ptr.xy), cellCoord(v_uv) - cellCoord(u_ptr.xy)) / 1.4));

  fragColor = vec4(T, c, f, a);
}`;

const RENDER_SRC = `#version 300 es
${COMMON}
in vec2 v_uv;
out vec4 fragColor;

uniform sampler2D u_field;
uniform vec2 u_texel;
uniform vec2 u_res;
uniform vec3 u_c0;
uniform vec3 u_c1;
uniform vec3 u_c2;
uniform vec3 u_c3;
uniform vec3 u_c4;
uniform float u_bias;
uniform float u_contrast;
uniform float u_mottle;

vec3 ramp(float x) {
  vec3 c = mix(u_c0, u_c1, smoothstep(0.0, 0.26, x));
  c = mix(c, u_c2, smoothstep(0.24, 0.52, x));
  c = mix(c, u_c3, smoothstep(0.50, 0.80, x));
  c = mix(c, u_c4, smoothstep(0.78, 1.0, x));
  return c;
}

void main() {
  vec4 s = texture(u_field, v_uv);
  float T = s.x;
  float c = s.y;
  float f = s.z;
  float a = s.w;

  float lane = max(c - 1.0, 0.0);
  float open = max(1.0 - c, 0.0);

  // The four neighbours, fetched once and used twice — the lane seam below
  // needs grad(c), and T needs an unsharp.
  //
  // The unsharp is not a cosmetic sharpen. Semi-Lagrangian advection is
  // unconditionally stable precisely because it interpolates, and every step
  // pays for that with a bilinear fetch that low-passes the field; run it at
  // 60Hz and the surface is being blurred sixty times a second. The sim is
  // then magnified roughly four times onto the backing store, so what reaches
  // the eye is a soft field with no edge anywhere and the whole photosphere
  // reads out of focus. Subtracting the discrete laplacian puts back the
  // frequency band that dissipation just removed, at the cost of nothing —
  // these taps were already paid for.
  vec4 sl = texture(u_field, v_uv - vec2(u_texel.x, 0.0));
  vec4 sr = texture(u_field, v_uv + vec2(u_texel.x, 0.0));
  vec4 sd = texture(u_field, v_uv - vec2(0.0, u_texel.y));
  vec4 su = texture(u_field, v_uv + vec2(0.0, u_texel.y));
  float Tlap = (sl.x + sr.x + sd.x + su.x) * 0.25 - T;
  T = max(T - Tlap * 0.85, 0.0);

  // T goes through a saturating exposure rather than straight into the ramp.
  // Linear, the summit of every cell clips to the top stop within a second of
  // spin-up and the whole frame becomes white blobs in black seams — soap
  // foam, which is the exact failure this component has to avoid.
  //
  // Saturating alone was not enough: at an exposure of 2.1 the shoulder was
  // reached by the time T was ~1, so most of a granule's area still landed on
  // the top stop and the interiors were flat plateaus with all the variation
  // crushed out of them. A star does not look like that — granule-to-lane
  // contrast on the real photosphere is a fraction of full range, and every
  // cue that makes the surface worth staring at lives INSIDE that fraction.
  // Exposure 1.15 against a gain of 0.55 puts a typical summit near 0.75 of
  // the ramp rather than pinned at 1.0, which leaves the top quarter for the
  // hottest few percent of the field and gives the mottle and the cooling
  // falloff somewhere to be seen.
  float hot = 1.0 - exp(-T * 1.15);

  float L = 0.205;
  L += hot * 0.60;
  L -= smoothstep(0.03, 1.15, lane) * 0.32;
  L += open * 0.07;

  // the lane's own gradient, added as a thin seam. A density field advected
  // semi-Lagrangian loses its highest frequencies every step; putting a little
  // of the gradient back is the difference between a lane with an edge and a
  // soft grey smear where one used to be.
  float grad = length(vec2(sr.y - sl.y, su.y - sd.y));
  // gated to the lane side. Unclamped it also fires on the granule side of
  // every boundary, which laid a dark ring just inside each cell and embossed
  // the whole field — every granule beaded up as a separate object instead of
  // packing against its neighbours.
  L -= min(grad * 3.4, 0.24) * 0.5 * smoothstep(0.85, 1.15, c);

  // micro-mottle, confined to the hot interiors — a granule is not a smooth
  // plateau. Its lookup is displaced by the field itself, which costs nothing
  // and makes the texture travel with the material instead of sitting still
  // behind a moving surface.
  //
  // It carries most of the load now that the exposure no longer clips: with a
  // flat plateau there was nothing for it to modulate, and with headroom above
  // the summit it is the only thing between a granule and a painted disc.
  // Three octaves, and gated to open early (T = 0.04) so it reaches the cooler
  // outer thirds of a cell rather than only the summit.
  //
  // The displacement is small and CENTRED, and both of those were learned the
  // hard way. At vec2(c, T) * 2.3 the offset ran to several noise periods, so
  // the lookup did not travel with the material, it sheared with it: every
  // granule grew a bright cap on its upflow side and a speckled tail opposite,
  // and forty of those in a frame read as a field of mushrooms. Subtracting
  // c's rest value of 1 also matters — uncentred, the whole field carries a
  // constant offset and the term stops being a perturbation at all.
  vec2 mp = v_uv * vec2(u_aspect, 1.0) * u_cells * 6.5 + vec2(c - 1.0, T) * 0.85;
  float m = vnoise(mp) * 0.55 + vnoise(mp * 2.3 + 7.1) * 0.28 + vnoise(mp * 4.7 + 2.9) * 0.14;
  L += (m - 0.46) * u_mottle * smoothstep(0.04, 0.42, T);

  L += f * 0.62;

  // pointer freshness lifts luminance under the cursor, same ramp as
  // everything else — brighter or dimmer depending where L already sits,
  // never a hue laid on top. Folded in before the ramp so it also picks up
  // contrast/bias like every other term, rather than being a flat overlay.
  L += clamp(a, 0.0, 1.0) * 0.22;

  // a full-bleed surface should reach the edge of the frame. The vignette is
  // here only to stop the clamped border texels from reading as a hard cut,
  // so it starts late and lands shallow — at 0.09 it put visible black bands
  // across the top and bottom of a 16:10 frame and undid the full bleed.
  vec2 vp = v_uv - 0.5;
  float vig = smoothstep(0.62, 1.18, length(vp * vec2(u_aspect / max(u_aspect, 1.0), 1.0)) * 1.3);
  L -= vig * 0.045;

  L = clamp((L - 0.5) * u_contrast + 0.5 + u_bias, 0.0, 1.0);
  vec3 col = ramp(L);

  // the low end of a full-bleed ramp is a very long flat gradient, which is
  // exactly where 8-bit banding shows
  float dith = (hash32(gl_FragCoord.xy).x - 0.5) / 255.0;
  fragColor = vec4(col + dith, 1.0);
}`;

type RGB = [number, number, number];
type FBO = { tex: WebGLTexture; fbo: WebGLFramebuffer; w: number; h: number };
type Double = { read: FBO; write: FBO; swap: () => void };

function parseColor(raw: string): RGB | null {
  const v = raw.trim();
  if (!v) return null;
  const hex = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(v);
  if (hex) {
    let h = hex[1];
    if (h.length === 3) h = h.split("").map((ch) => ch + ch).join("");
    const n = parseInt(h, 16);
    return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
  }
  const fn = /^rgba?\(([^)]+)\)$/i.exec(v);
  if (fn) {
    const parts = fn[1].split(/[\s,/]+/).filter(Boolean).map(parseFloat);
    if (parts.length >= 3) return [parts[0] / 255, parts[1] / 255, parts[2] / 255];
  }
  return null;
}

function mixRGB(a: RGB, b: RGB, t: number): RGB {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

function luminance([r, g, b]: RGB): number {
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

// ---------------------------------------------------------------------------
// Surface — the GL host: context, programs, ping-pong targets, one fullscreen
// triangle. It knows nothing about convection, so a second preset could mount
// it with different shader sources.
// ---------------------------------------------------------------------------
class Surface {
  gl: WebGL2RenderingContext | null = null;
  private vao: WebGLVertexArrayObject | null = null;
  private buffer: WebGLBuffer | null = null;
  private programs: WebGLProgram[] = [];
  private locs = new WeakMap<WebGLProgram, Map<string, WebGLUniformLocation | null>>();
  private fbos: FBO[] = [];
  private active: WebGLProgram | null = null;

  constructor(private canvas: HTMLCanvasElement) {}

  init(isRestore = false): boolean {
    const gl = this.canvas.getContext("webgl2", {
      alpha: false,
      antialias: false,
      depth: false,
      stencil: false,
      premultipliedAlpha: false,
      preserveDrawingBuffer: false,
      powerPreference: "high-performance",
    });
    if (!gl) return false;
    this.gl = gl;
    // RGBA16F is only colour-renderable behind one of these. Without it
    // nothing renders and the caller's children sit on --background.
    const ext =
      gl.getExtension("EXT_color_buffer_float") ??
      gl.getExtension("EXT_color_buffer_half_float");
    if (!ext) {
      // The context is live by this point, and the caller's early return on
      // false never registers the effect cleanup that hands one back, so an
      // unreleased context would outlive the mount. The condition is the
      // inverse of that cleanup's `!canvas.isConnected` — the canvas is still
      // attached on this path — and the one context to leave alone is one the
      // browser just restored, since onRestored re-enters init() and a release
      // there would feed its own loss/restore/fail cycle.
      if (!isRestore) gl.getExtension("WEBGL_lose_context")?.loseContext();
      return false;
    }
    gl.getExtension("OES_texture_float_linear");

    this.buffer = gl.createBuffer();
    this.vao = gl.createVertexArray();
    gl.bindVertexArray(this.vao);
    gl.bindBuffer(gl.ARRAY_BUFFER, this.buffer);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
    gl.disable(gl.BLEND);
    gl.disable(gl.DEPTH_TEST);
    return true;
  }

  program(frag: string): WebGLProgram | null {
    const gl = this.gl;
    if (!gl) return null;
    const vs = this.compile(gl.VERTEX_SHADER, VERT_SRC);
    const fs = this.compile(gl.FRAGMENT_SHADER, frag);
    if (!vs || !fs) return null;
    const p = gl.createProgram();
    if (!p) return null;
    gl.attachShader(p, vs);
    gl.attachShader(p, fs);
    gl.bindAttribLocation(p, 0, "a_pos");
    gl.linkProgram(p);
    gl.deleteShader(vs);
    gl.deleteShader(fs);
    if (!gl.getProgramParameter(p, gl.LINK_STATUS)) {
      gl.deleteProgram(p);
      return null;
    }
    this.programs.push(p);
    this.locs.set(p, new Map());
    return p;
  }

  private compile(type: number, src: string): WebGLShader | null {
    const gl = this.gl!;
    const s = gl.createShader(type);
    if (!s) return null;
    gl.shaderSource(s, src);
    gl.compileShader(s);
    if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) {
      gl.deleteShader(s);
      return null;
    }
    return s;
  }

  use(p: WebGLProgram) {
    this.gl?.useProgram(p);
    this.active = p;
  }

  private loc(name: string): WebGLUniformLocation | null {
    const p = this.active;
    if (!p || !this.gl) return null;
    const map = this.locs.get(p)!;
    if (!map.has(name)) map.set(name, this.gl.getUniformLocation(p, name));
    return map.get(name) ?? null;
  }

  f(n: string, x: number) {
    this.gl?.uniform1f(this.loc(n), x);
  }
  v2(n: string, x: number, y: number) {
    this.gl?.uniform2f(this.loc(n), x, y);
  }
  v3(n: string, c: RGB) {
    this.gl?.uniform3f(this.loc(n), c[0], c[1], c[2]);
  }
  v3f(n: string, x: number, y: number, z: number) {
    this.gl?.uniform3f(this.loc(n), x, y, z);
  }
  tex(n: string, unit: number, t: WebGLTexture) {
    const gl = this.gl;
    if (!gl) return;
    gl.activeTexture(gl.TEXTURE0 + unit);
    gl.bindTexture(gl.TEXTURE_2D, t);
    gl.uniform1i(this.loc(n), unit);
  }

  makeFBO(w: number, h: number): FBO | null {
    const gl = this.gl!;
    const tex = gl.createTexture();
    if (!tex) return null;
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, tex);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA16F, w, h, 0, gl.RGBA, gl.HALF_FLOAT, null);
    const fbo = gl.createFramebuffer();
    if (!fbo) {
      gl.deleteTexture(tex);
      return null;
    }
    gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
    gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, tex, 0);
    if (gl.checkFramebufferStatus(gl.FRAMEBUFFER) !== gl.FRAMEBUFFER_COMPLETE) {
      gl.deleteTexture(tex);
      gl.deleteFramebuffer(fbo);
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      return null;
    }
    // the field's rest state is T = 0, c = 1: a surface with nothing moving on
    // it yet and its material spread evenly
    gl.clearColor(0, 1, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    const f: FBO = { tex, fbo, w, h };
    this.fbos.push(f);
    return f;
  }

  makeDouble(w: number, h: number): Double | null {
    const a = this.makeFBO(w, h);
    const b = this.makeFBO(w, h);
    if (!a || !b) return null;
    const d: Double = {
      read: a,
      write: b,
      swap: () => {
        const t = d.read;
        d.read = d.write;
        d.write = t;
      },
    };
    return d;
  }

  blit(target: FBO | null) {
    const gl = this.gl;
    if (!gl) return;
    if (target) {
      gl.bindFramebuffer(gl.FRAMEBUFFER, target.fbo);
      gl.viewport(0, 0, target.w, target.h);
    } else {
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      gl.viewport(0, 0, this.canvas.width, this.canvas.height);
    }
    gl.drawArrays(gl.TRIANGLES, 0, 3);
  }

  free(f: FBO | null) {
    const gl = this.gl;
    if (!gl || !f) return;
    gl.deleteTexture(f.tex);
    gl.deleteFramebuffer(f.fbo);
    this.fbos = this.fbos.filter((x) => x !== f);
  }

  freeDouble(d: Double | null) {
    if (!d) return;
    this.free(d.read);
    this.free(d.write);
  }

  destroy() {
    const gl = this.gl;
    if (!gl) return;
    for (const f of this.fbos.slice()) this.free(f);
    for (const p of this.programs) gl.deleteProgram(p);
    if (this.buffer) gl.deleteBuffer(this.buffer);
    if (this.vao) gl.deleteVertexArray(this.vao);
    this.programs = [];
    this.fbos = [];
    this.buffer = null;
    this.vao = null;
    this.active = null;
    this.gl = null;
  }
}

// A convecting surface has no meaningful t = 0 — an unstirred field is a flat
// grey rectangle. The sim is spun up before the first paint in EVERY mode, at
// a coarse step (semi-Lagrangian advection is unconditionally stable, so the
// only cost of a big dt is a little extra diffusion that settles out within a
// second of live stepping). 300 steps at 1/16s is nearly twenty seconds of
// convection: cells have already been born, expanded and died, and the lane
// network is fully knitted before anyone looks at it.
const WARMUP_STEPS = 300;
const WARMUP_DT = 1 / 16;
const STATIC_STEPS = 460;

// Pointer smoothing. A plain exponential follower has a steady-state error of
// exactly velocity*tau under constant motion, so the upwelling would sit that
// far behind the cursor and read as the surface responding late. Extrapolating
// the target one tau ahead cancels the term algebraically; the smoothing is
// then spent only on direction changes and on interpolating between events
// that arrived sparser than frames. The velocity window has to outlive the gap
// between two pointer events or the estimate — and with it the compensation —
// collapses to zero on any frame that carried none.
const POINTER_TAU = 0.012;
const VEL_TAU = 0.06;
const LEAD_MAX = 26;

export function GranuleChurn({
  density = 1,
  speed = 1,
  faculae = 1,
  paused = false,
  children,
  className = "",
  style,
}: GranuleChurnProps) {
  const wrapRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  const pausedRef = useRef(paused);
  pausedRef.current = paused;

  useEffect(() => {
    const wrap = wrapRef.current;
    const canvas = canvasRef.current;
    if (!wrap || !canvas) return;

    const surface = new Surface(canvas);
    if (!surface.init()) return;
    const simProg = surface.program(SIM_SRC);
    const renderProg = surface.program(RENDER_SRC);
    if (!simProg || !renderProg) {
      // The programs failed on a context getContext() did hand over, and this
      // return comes before any cleanup is registered: destroy() frees the GL
      // objects, but only an explicit release gets the context itself back.
      // No isRestore guard is needed here — onRestored re-enters init() and
      // nothing else, so this block cannot cycle.
      const lose = surface.gl?.getExtension("WEBGL_lose_context");
      surface.destroy();
      lose?.loseContext();
      return;
    }

    let raf = 0;
    let running = false;
    let staticMode = false;
    let disposed = false;
    let cssW = 0;
    let cssH = 0;
    let dpr = 1;
    let simW = 0;
    let simH = 0;
    let field: Double | null = null;
    let lastMs = performance.now();
    let simTime = 0;

    // Adaptive ladder. Every threshold is wall clock, never frames: a
    // frame-counted gate waits longer the slower the machine is, which is
    // backwards. Display scale goes first because the render pass is the one
    // that scales with DPR; sim resolution is last because it is what keeps
    // the lanes thin.
    const DISPLAY_SCALES = [1, 0.8, 0.62];
    // the sim runs far below display resolution and is magnified with a linear
    // fetch, so its long side sets how fine a lane can be. At 640 against a
    // 2880px backing a lane was four device pixels wide before filtering and
    // the whole field read soft. 768 is the point where lanes come back to a
    // hard edge; the pass is ~0.3M fragments, a rounding error next to the
    // 5.2M-fragment render pass it feeds.
    const SIM_LONG = [896, 704, 512];
    const BUDGET_OVER = 26;
    let tier = 0;
    let frameEma = 16.7;
    let overMs = 0;
    let underMs = 0;
    let upWindow = 8000;

    let hoverTarget = 0;
    let hoverAmt = 0;
    let pressAmt = 0;
    let pressTarget = 0;

    let havePointer = false;
    let tgtX = 0;
    let tgtY = 0;
    let ptrX = 0;
    let ptrY = 0;
    let velX = 0;
    let velY = 0;
    let lastTgtX = 0;
    let lastTgtY = 0;
    let rectLeft = 0;
    let rectTop = 0;
    let rectDirty = true;

    let c0: RGB = [0.02, 0.02, 0.03];
    let c1: RGB = [0.1, 0.1, 0.11];
    let c2: RGB = [0.42, 0.42, 0.44];
    let c3: RGB = [0.86, 0.86, 0.87];
    let c4: RGB = [1, 1, 1];
    let bias = 0;
    let contrast = 1.18;
    let mottle = 0.14;

    // Five stops, and the direction genuinely inverts between themes. A
    // reflective surface can span black-to-white in both because it is lit by
    // a room; a self-luminous one cannot — brightness IS the subject, so light
    // theme has to be the negative, not a dimmed positive. Its stops are
    // written apart rather than derived with a bias term, and they stop short
    // of black on purpose: granules cover most of the frame, so ramping their
    // interiors all the way down would hand the light theme a black page.
    const readColors = () => {
      const cs = getComputedStyle(document.documentElement);
      const bg = parseColor(cs.getPropertyValue("--background")) ?? [1, 1, 1];
      const fg = parseColor(cs.getPropertyValue("--foreground")) ?? [0.09, 0.09, 0.09];
      const muted = parseColor(cs.getPropertyValue("--ns-muted")) ?? [0.55, 0.55, 0.55];
      const border = parseColor(cs.getPropertyValue("--border")) ?? [0.2, 0.2, 0.2];
      const black: RGB = [0, 0, 0];
      const white: RGB = [1, 1, 1];
      if (luminance(bg) < 0.5) {
        // a star: lanes sink below the page, granule tops climb past --foreground
        c0 = mixRGB(bg, black, 0.6);
        c1 = mixRGB(border, bg, 0.1);
        c2 = mixRGB(muted, fg, 0.25);
        c3 = fg;
        c4 = mixRGB(fg, white, 0.9);
        bias = -0.04;
        contrast = 1.2;
        mottle = 0.17;
      } else {
        // the negative: pale lanes, graphite granules, and the darkest stop
        // held well off black so the field reads as inked paper
        c0 = bg;
        c1 = mixRGB(bg, muted, 0.42);
        c2 = mixRGB(muted, fg, 0.3);
        c3 = mixRGB(fg, muted, 0.34);
        c4 = mixRGB(fg, black, 0.15);
        bias = 0.02;
        contrast = 1.14;
        mottle = 0.15;
      }
    };
    readColors();

    const cellsAcross = () => 15 * Math.max(0.35, Math.min(2.5, density));

    const setSimUniforms = (dt: number, ptrStrength: number) => {
      surface.use(simProg);
      surface.f("u_aspect", cssW / Math.max(1, cssH));
      surface.f("u_cells", cellsAcross());
      surface.f("u_time", simTime);
      surface.f("u_dt", dt);
      surface.f("u_flow", 0.55 * Math.max(0.05, speed));
      surface.f("u_split", 1);
      surface.f("u_fleck", Math.max(0, faculae));
      surface.v2("u_texel", 1 / simW, 1 / simH);
      surface.v2("u_grid", simW, simH);
      surface.v3f("u_ptr", ptrX / Math.max(1, cssW), ptrY / Math.max(1, cssH), ptrStrength);
      surface.f("u_ptrAcc", ptrStrength > 0 ? Math.min(1, ptrStrength * 1.1) : 0);
    };

    const step = (dt: number) => {
      if (!field) return;
      const strength = havePointer ? hoverAmt * (0.5 + 0.9 * pressAmt) : 0;
      simTime += dt * Math.max(0.05, speed);
      setSimUniforms(dt, strength);
      surface.tex("u_field", 0, field.read.tex);
      surface.blit(field.write);
      field.swap();
    };

    const render = () => {
      if (!field) return;
      surface.use(renderProg);
      surface.f("u_aspect", cssW / Math.max(1, cssH));
      surface.f("u_cells", cellsAcross());
      surface.f("u_time", simTime);
      surface.v2("u_texel", 1 / simW, 1 / simH);
      surface.v2("u_res", cssW, cssH);
      surface.v3("u_c0", c0);
      surface.v3("u_c1", c1);
      surface.v3("u_c2", c2);
      surface.v3("u_c3", c3);
      surface.v3("u_c4", c4);
      surface.f("u_bias", bias);
      surface.f("u_contrast", contrast);
      surface.f("u_mottle", mottle);
      surface.tex("u_field", 0, field.read.tex);
      surface.blit(null);
    };

    const seed = (steps: number) => {
      const savedTime = simTime;
      simTime = 0;
      for (let i = 0; i < steps; i++) step(WARMUP_DT);
      // the clock keeps running from where the spin-up left it, so a resize
      // that re-seeds does not restart every plume's phase
      simTime = savedTime > 0 ? savedTime : simTime;
    };

    const buildTargets = () => {
      const gl = surface.gl;
      if (!gl || cssW < 2 || cssH < 2) return;
      const long = SIM_LONG[tier];
      const aspect = cssW / cssH;
      const w = aspect >= 1 ? long : Math.max(96, Math.round(long * aspect));
      const h = aspect >= 1 ? Math.max(96, Math.round(long / aspect)) : long;
      if (field && simW === w && simH === h) return;
      surface.freeDouble(field);
      simW = w;
      simH = h;
      field = surface.makeDouble(w, h);
      seed(WARMUP_STEPS);
    };

    const applyBacking = () => {
      if (cssW < 2 || cssH < 2) return;
      // Capped at 1.7 rather than the usual 2. The render pass is full-bleed
      // and costs five texture fetches plus three octaves of value noise per
      // fragment, so the area term dominates everything else in the component:
      // measured with a readPixels fence on an M3 (ANGLE/Metal — gl.finish()
      // is a no-op there and reads 0.00ms, which is how a naive bench calls
      // this free), an uncapped 2880x1800 costs 8.2ms of a 16.7ms budget. That
      // is inside it, but it is half the frame for a BACKGROUND, and this
      // surface is never the only thing on the page. 1.7 spends 5.9ms for a
      // field of continuous noise whose finest structure is well under a
      // device pixel either way — there is no visible loss, only headroom.
      dpr = Math.min(window.devicePixelRatio || 1, 1.7) * DISPLAY_SCALES[tier];
      const pw = Math.max(1, Math.round(cssW * dpr));
      const ph = Math.max(1, Math.round(cssH * dpr));
      if (canvas.width !== pw || canvas.height !== ph) {
        canvas.width = pw;
        canvas.height = ph;
      }
      canvas.style.width = `${cssW}px`;
      canvas.style.height = `${cssH}px`;
    };

    let resizeRaf = 0;
    const doResize = () => {
      resizeRaf = 0;
      const rect = wrap.getBoundingClientRect();
      if (rect.width < 2 || rect.height < 2) return;
      cssW = rect.width;
      cssH = rect.height;
      rectLeft = rect.left;
      rectTop = rect.top;
      rectDirty = false;
      // a new size is a new cost, so the ladder starts over rather than
      // carrying a verdict earned at a different number of fragments
      tier = 0;
      overMs = 0;
      underMs = 0;
      upWindow = 8000;
      frameEma = 16.7;
      applyBacking();
      buildTargets();
      render();
    };
    // ResizeObserver fires on every step of a window drag; coalescing to one
    // rAF is what stops a drag from paying for a re-seed per pixel
    const resize = () => {
      if (resizeRaf) return;
      resizeRaf = requestAnimationFrame(doResize);
    };

    const stepPointer = (dt: number) => {
      if (!havePointer || dt <= 0) return;
      const vk = 1 - Math.exp(-dt / VEL_TAU);
      velX += ((tgtX - lastTgtX) / dt - velX) * vk;
      velY += ((tgtY - lastTgtY) / dt - velY) * vk;
      lastTgtX = tgtX;
      lastTgtY = tgtY;
      let leadX = velX * POINTER_TAU;
      let leadY = velY * POINTER_TAU;
      const lead = Math.hypot(leadX, leadY);
      if (lead > LEAD_MAX) {
        leadX = (leadX / lead) * LEAD_MAX;
        leadY = (leadY / lead) * LEAD_MAX;
      }
      const k = 1 - Math.exp(-dt / POINTER_TAU);
      ptrX += (tgtX + leadX - ptrX) * k;
      ptrY += (tgtY + leadY - ptrY) * k;
    };

    const loop = (nowMs: number) => {
      const rawMs = nowMs - lastMs;
      lastMs = nowMs;
      const dt = Math.min(0.05, Math.max(0.0005, rawMs / 1000));
      hoverAmt += (hoverTarget - hoverAmt) * (1 - Math.exp(-dt * 7));
      pressAmt += (pressTarget - pressAmt) * (1 - Math.exp(-dt * 6));
      stepPointer(dt);
      step(dt);
      render();

      const clamped = Math.min(50, rawMs);
      frameEma += (clamped - frameEma) * (1 - Math.exp(-clamped / 120));
      if (frameEma > BUDGET_OVER) {
        overMs += clamped;
        underMs = 0;
      } else {
        underMs += clamped;
        overMs = 0;
      }
      // asymmetric: drop after a sustained stretch of stutter, climb back only
      // after a much longer clean one, and double the wait each time — the
      // frame time being watched is the PAGE's, and this surface is rarely
      // what blew it, so a sibling's layout storm must not permanently soften it
      const down = overMs > 1600 && tier < DISPLAY_SCALES.length - 1;
      const up = underMs > upWindow && tier > 0;
      if (down || up) {
        tier += down ? 1 : -1;
        if (down) upWindow = Math.min(64000, upWindow * 2);
        overMs = 0;
        underMs = 0;
        frameEma = 16.7;
        applyBacking();
        buildTargets();
      }
      raf = requestAnimationFrame(loop);
    };

    const wake = () => {
      if (running || disposed) return;
      running = true;
      lastMs = performance.now();
      raf = requestAnimationFrame(loop);
    };
    const sleep = () => {
      cancelAnimationFrame(raf);
      running = false;
    };

    const syncRect = () => {
      if (!rectDirty) return;
      const rect = wrap.getBoundingClientRect();
      rectLeft = rect.left;
      rectTop = rect.top;
      rectDirty = false;
    };
    const markRectDirty = () => {
      rectDirty = true;
    };

    const setTarget = (e: PointerEvent) => {
      syncRect();
      const co = typeof e.getCoalescedEvents === "function" ? e.getCoalescedEvents() : null;
      const last = co && co.length > 0 ? co[co.length - 1] : e;
      tgtX = last.clientX - rectLeft;
      tgtY = last.clientY - rectTop;
    };
    const snapPointer = () => {
      ptrX = tgtX;
      ptrY = tgtY;
      velX = 0;
      velY = 0;
      lastTgtX = tgtX;
      lastTgtY = tgtY;
      havePointer = true;
    };
    // static mode has no loop to smooth in, so pointer input runs one further
    // step under the cursor and repaints the frozen frame
    const staticPoke = () => {
      hoverAmt = 1;
      step(1 / 60);
      render();
    };

    const onPointerEnter = (e: PointerEvent) => {
      hoverTarget = 1;
      setTarget(e);
      snapPointer();
      if (staticMode) staticPoke();
    };
    const onPointerMove = (e: PointerEvent) => {
      setTarget(e);
      if (!havePointer) {
        snapPointer();
        hoverTarget = 1;
      }
      if (staticMode) {
        ptrX = tgtX;
        ptrY = tgtY;
        staticPoke();
      }
    };
    const onPointerLeave = () => {
      hoverTarget = 0;
      pressTarget = 0;
      havePointer = false;
    };
    const onPointerDown = (e: PointerEvent) => {
      setTarget(e);
      snapPointer();
      hoverTarget = 1;
      pressTarget = 1;
      if (staticMode) staticPoke();
    };
    const onPointerUp = (e: PointerEvent) => {
      pressTarget = 0;
      // a lifted touch has no position any more and no pointerleave is coming
      if (e.pointerType !== "mouse") {
        hoverTarget = 0;
        havePointer = false;
      }
    };
    const onPointerCancel = () => {
      hoverTarget = 0;
      pressTarget = 0;
      havePointer = false;
    };

    const ro = new ResizeObserver(resize);
    ro.observe(wrap);
    doResize();

    wrap.addEventListener("pointerenter", onPointerEnter);
    wrap.addEventListener("pointerleave", onPointerLeave);
    wrap.addEventListener("pointermove", onPointerMove);
    wrap.addEventListener("pointerdown", onPointerDown);
    wrap.addEventListener("pointerup", onPointerUp);
    wrap.addEventListener("pointercancel", onPointerCancel);
    window.addEventListener("scroll", markRectDirty, { passive: true, capture: true });
    window.addEventListener("resize", markRectDirty, { passive: true });

    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    let reduced = mq.matches;
    const applyMode = () => {
      if (reduced || pausedRef.current) {
        if (!staticMode) {
          staticMode = true;
          sleep();
          // reduced motion still gets a fully developed surface, just a frozen
          // one: a longer spin-up and then no further stepping
          seed(STATIC_STEPS - WARMUP_STEPS);
          render();
        }
      } else if (staticMode || !running) {
        staticMode = false;
        wake();
      }
    };
    const onMq = () => {
      reduced = mq.matches;
      applyMode();
    };
    mq.addEventListener("change", onMq);

    let onScreen = true;
    const io = new IntersectionObserver(
      (entries) => {
        onScreen = entries.some((en) => en.isIntersecting);
        if (!onScreen) sleep();
        else if (!staticMode && !document.hidden) wake();
      },
      { threshold: 0 }
    );
    io.observe(wrap);

    const onVis = () => {
      if (document.hidden) sleep();
      else if (!staticMode && onScreen) wake();
    };
    document.addEventListener("visibilitychange", onVis);
    applyMode();

    // polled rather than made an effect dependency: either would tear down and
    // rebuild the GL context to change a boolean
    let lastPolledPaused = pausedRef.current;
    let poll = 0;
    const tick = () => {
      if (pausedRef.current !== lastPolledPaused) {
        lastPolledPaused = pausedRef.current;
        if (!pausedRef.current && !reduced) staticMode = true; // force applyMode to wake
        applyMode();
      }
      poll = window.setTimeout(tick, 140);
    };
    tick();

    const themeObserver = new MutationObserver(() => {
      readColors();
      if (staticMode) render();
    });
    themeObserver.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    const onLost = (e: Event) => {
      e.preventDefault();
      sleep();
    };
    const onRestored = () => {
      field = null;
      if (surface.init(true)) doResize();
    };
    canvas.addEventListener("webglcontextlost", onLost);
    canvas.addEventListener("webglcontextrestored", onRestored);

    return () => {
      disposed = true;
      sleep();
      cancelAnimationFrame(resizeRaf);
      ro.disconnect();
      io.disconnect();
      mq.removeEventListener("change", onMq);
      document.removeEventListener("visibilitychange", onVis);
      themeObserver.disconnect();
      canvas.removeEventListener("webglcontextlost", onLost);
      canvas.removeEventListener("webglcontextrestored", onRestored);
      wrap.removeEventListener("pointerenter", onPointerEnter);
      wrap.removeEventListener("pointerleave", onPointerLeave);
      wrap.removeEventListener("pointermove", onPointerMove);
      wrap.removeEventListener("pointerdown", onPointerDown);
      wrap.removeEventListener("pointerup", onPointerUp);
      wrap.removeEventListener("pointercancel", onPointerCancel);
      window.removeEventListener("scroll", markRectDirty, {
        capture: true,
      } as EventListenerOptions);
      window.removeEventListener("resize", markRectDirty);
      window.clearTimeout(poll);
      // destroy() frees the GL objects but not the context holding them, and a
      // detached canvas keeps its context until GC gets round to it —
      // browsers cap live contexts per renderer process and evict the oldest
      // first, which kills fields still on screen. Hand it back explicitly,
      // but only on a real unmount: this cleanup also runs when a dep changes,
      // and a canvas returns its one lost context to every later getContext(),
      // so releasing too eagerly would blank the rebuilt field.
      const lose = surface.gl?.getExtension("WEBGL_lose_context");
      surface.destroy();
      if (!canvas.isConnected) lose?.loseContext();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [density, speed, faculae]);

  return (
    <div
      ref={wrapRef}
      className={`relative isolate h-full w-full touch-none overflow-hidden bg-background ${className}`}
      style={style}
    >
      <canvas ref={canvasRef} aria-hidden="true" className="absolute inset-0 block" />
      {children ? <div className="relative z-[1] h-full w-full">{children}</div> : null}
    </div>
  );
}

GranuleChurn.displayName = "GranuleChurn";

"use client";

import { useMemo, useRef, useState } from "react";

export type TideCell = { date: string; value: number };

// A year of daily values read as a tide table: one column per week, one row per
// weekday, depth carried by a single-hue sequential ramp rather than a rainbow.
//
// Every step is mixed at runtime from --ns-accent into --background, so the ramp is
// re-stepped by the theme instead of being two hardcoded palettes: the same 5
// stops read as ink-on-paper in light and as lit water in dark. A day with no
// reading is not step 0 of the ramp — it is border-coloured slack, so "nothing
// recorded" never looks like "recorded, and low".
const STEPS = [18, 34, 52, 74, 100];
const SLACK = "color-mix(in oklab, var(--border) 70%, var(--background))";
const depth = (step: number) =>
  `color-mix(in oklab, var(--ns-accent) ${STEPS[step]}%, var(--background))`;

const DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

export function TideLedger({
  data,
  weeks = 26,
  cell = 13,
  gap = 3,
  label = "Daily readings",
  onSelect,
  className = "",
}: {
  /** one entry per day; the trailing `weeks * 7` days are shown */
  data: TideCell[];
  /** number of weeks (columns) rendered, most recent last */
  weeks?: number;
  /** px edge of one day cell */
  cell?: number;
  /** px gap between cells, both axes */
  gap?: number;
  /** caption above the grid; also the grid's accessible name */
  label?: string;
  /** called with the clicked day's data */
  onSelect?: (cell: TideCell) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}) {
  const [active, setActive] = useState<number | null>(null);
  const [cursor, setCursor] = useState(0);
  const gridRef = useRef<HTMLDivElement>(null);

  // Column-major: index = week * 7 + weekday, which is the order the DOM is in,
  // so arrow-key movement is plain index arithmetic rather than a lookup.
  const cells = useMemo(() => data.slice(-(weeks * 7)), [data, weeks]);
  const max = useMemo(() => Math.max(1, ...cells.map((c) => c.value)), [cells]);

  const stepOf = (value: number) =>
    value <= 0 ? -1 : Math.min(STEPS.length - 1, Math.floor((value / max) * STEPS.length));

  const move = (delta: number) => {
    const next = Math.min(cells.length - 1, Math.max(0, cursor + delta));
    setCursor(next);
    setActive(next);
    (gridRef.current?.children[next] as HTMLElement | undefined)?.focus();
  };

  const shown = active !== null ? cells[active] : null;

  return (
    <figure className={["ns-hct-figure inline-flex flex-col gap-3", className].join(" ")}>
      <figcaption className="flex items-baseline justify-between gap-6 font-mono text-[11px] uppercase tracking-[0.18em] text-ns-muted">
        <span>{label}</span>
        {/* The readout is the direct label: one value, the hovered one, rather
            than a number stamped on 182 cells. */}
        <span className="text-foreground/80" aria-live="polite">
          {shown ? `${shown.date} · ${shown.value}` : `peak ${max}`}
        </span>
      </figcaption>

      <div className="flex gap-2">
        <div
          className="grid shrink-0 text-[10px] text-ns-muted"
          style={{ gridTemplateRows: `repeat(7, ${cell}px)`, rowGap: gap }}
          aria-hidden
        >
          {DAYS.map((d, i) => (
            <span key={d} className="leading-none" style={{ fontSize: 9, lineHeight: `${cell}px` }}>
              {i % 2 === 0 ? d[0] : ""}
            </span>
          ))}
        </div>

        <div
          ref={gridRef}
          role="grid"
          aria-label={label}
          className="grid"
          style={{
            gridTemplateRows: `repeat(7, ${cell}px)`,
            gridAutoFlow: "column",
            gridAutoColumns: `${cell}px`,
            gap,
          }}
          onKeyDown={(e) => {
            const delta =
              e.key === "ArrowRight" ? 7 : e.key === "ArrowLeft" ? -7 : e.key === "ArrowDown" ? 1 : e.key === "ArrowUp" ? -1 : 0;
            if (!delta) return;
            e.preventDefault();
            move(delta);
          }}
          onMouseLeave={() => setActive(null)}
        >
          {cells.map((c, i) => {
            const step = stepOf(c.value);
            return (
              <button
                key={c.date}
                type="button"
                role="gridcell"
                // Roving tabindex: the grid is one tab stop, arrows walk it.
                tabIndex={i === cursor ? 0 : -1}
                aria-label={`${c.date}: ${c.value}`}
                onMouseEnter={() => setActive(i)}
                onFocus={() => {
                  setCursor(i);
                  setActive(i);
                }}
                onClick={() => onSelect?.(c)}
                className="rounded-[2px] transition-[transform,box-shadow] duration-150 ease-out hover:scale-[1.35] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent motion-reduce:transition-none motion-reduce:hover:scale-100"
                style={{
                  background: step < 0 ? SLACK : depth(step),
                  // 2px surface ring so neighbouring depths never bleed into one
                  // continuous field.
                  boxShadow: active === i ? "0 0 0 2px var(--background), 0 0 0 3px var(--ns-accent)" : "none",
                }}
              />
            );
          })}
        </div>
      </div>

      <div className="flex items-center gap-2 font-mono text-[10px] uppercase tracking-[0.18em] text-ns-muted">
        <span>slack</span>
        <span className="h-[10px] w-[10px] rounded-[2px]" style={{ background: SLACK }} />
        {STEPS.map((_, i) => (
          <span key={i} className="h-[10px] w-[10px] rounded-[2px]" style={{ background: depth(i) }} />
        ))}
        <span>flood</span>
      </div>
    </figure>
  );
}

"use client";

import { useEffect, useRef } from "react";
import type { ReactNode } from "react";

// ---------------------------------------------------------------------------
// QuadrantOcclusion404 — a full-bleed 404 hero that renders the numeral
// "404" and an orbiting occluding disc from ONE shared silhouette, at
// HALF-CELL precision, using Unicode quadrant/half-block glyphs
// (▘▝▖▗▚▞▛▜▙▟█▀▄▌▐). Every other ASCII component in this registry quantizes
// to one glyph = one full-cell density value; nothing else renders sub-cell
// partial-block geometry. That is the entire point of this component.
//
// Each glyph cell owns a 2x2 addressable sub-grid (TL/TR/BL/BR). The "404"
// numeral is rasterized once (after document.fonts.ready) into an offscreen
// alpha mask and area-averaged into a static per-sub-cell coverage table —
// this never changes after resize, since the numeral itself is stationary.
// The occluder is a disc with a low-order radial harmonic on its edge
// (r(theta) = R * (1 + a*sin(3*theta + wt))), tested analytically at each of
// the same 4 sub-positions every frame — no raster, just a distance compare.
// Per cell, per frame: combinedBits = occluderBits | numeralBits, looked up
// in a 16-entry quadrant-glyph table for the shape; the CELL'S COLOR is
// --foreground if any of its 4 sub-positions belongs to the occluder (the
// disc always "wins" and stays legible whether it's crossing ink or empty
// space) and --ns-muted otherwise. The occluder's curved edge is therefore
// always the sub-cell-resolved boundary in motion — the crisp half-cell
// silhouette is demonstrated continuously, not in a static crop.
//
// Cell metrics come from measureText("█") (the full block), not a
// letter — block glyphs tile by their own ink box, and measuring "M" (the
// ramp-glyph convention elsewhere in this registry) can shear the grid if
// the loaded font's block-glyph advance differs from its letter advance.
// Draw uses textAlign="left"/textBaseline="alphabetic" at
// (col*cellW, row*cellH + ascent) so cells tile edge-to-edge by construction
// regardless of what the font does internally.
// ---------------------------------------------------------------------------

// bit order: TL=1, TR=2, BL=4, BR=8
const QUAD_GLYPH = [
  " ", // 0
  "▘", // 1  TL
  "▝", // 2  TR
  "▀", // 3  TL+TR (top half)
  "▖", // 4  BL
  "▌", // 5  TL+BL (left half)
  "▞", // 6  TR+BL
  "▛", // 7  TL+TR+BL
  "▗", // 8  BR
  "▚", // 9  TL+BR
  "▐", // 10 TR+BR (right half)
  "▜", // 11 TL+TR+BR
  "▄", // 12 BL+BR (bottom half)
  "▙", // 13 TL+BL+BR
  "▟", // 14 TR+BL+BR
  "█", // 15 full block
];

const SUB_DX = [0.25, 0.75, 0.25, 0.75]; // TL, TR, BL, BR
const SUB_DY = [0.25, 0.25, 0.75, 0.75];
const MASK_OVERSAMPLE = 2; // one-time rasterization quality, not per-frame cost
const COVERAGE_THRESHOLD = 0.42; // fraction of a sub-cell's mask alpha to count as "ink"
const ORBIT_HARMONIC_K = 3; // radial lobes on the occluder's edge
const ORBIT_HARMONIC_AMP = 0.22; // fraction of radius the lobes displace
const POINTER_BIAS_EASE = 0.06;
const DT_MAX = 0.05;

// reduced-motion static frame: the occluder is parked off-center over the
// numeral rather than clear of it or centered in a glyph's dead space —
// chosen to maximize the count of cells whose 4-bit code is neither 0
// (empty) nor 15 (solid), i.e. genuinely partial half-cell cells, which is
// the state this component exists to show. A parked-clear or
// fully-covering position would both minimize that count instead.
const STATIC_OFFSET_X = 0.62; // fraction of orbit radius, right of numeral center
const STATIC_OFFSET_Y = -0.12;

export interface QuadrantOcclusion404Props {
  /** grid cell size in px (font-size fed into measureText, not the final cell box) */
  cellSize?: number;
  /** occluder disc radius in px; default derives proportionally from the container */
  occluderRadius?: number;
  /** copy / CTAs rendered under the numeral field */
  children?: ReactNode;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function QuadrantOcclusion404({
  cellSize = 16,
  occluderRadius,
  children,
  className = "",
}: QuadrantOcclusion404Props) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    // -- tokens: read synchronously, before any observer/rAF is armed, so
    // nothing can ever paint with a placeholder value (rule: no color
    // literal, and no path may draw before the real read lands) -----------
    let fg = "";
    let muted = "";
    const readTokens = () => {
      const cs = getComputedStyle(document.documentElement);
      fg = cs.getPropertyValue("--foreground").trim();
      muted = cs.getPropertyValue("--ns-muted").trim();
    };
    readTokens();

    let cellW = cellSize;
    let cellH = cellSize;
    let ascent = cellSize;
    let cols = 0;
    let rows = 0;
    let dpr = 1;
    let sized = false;
    let ready = false;
    let disposed = false;

    let cx = 0; // numeral/orbit center, css px
    let cy = 0;
    let orbitRx = 0;
    let orbitRy = 0;
    let baseOccluderR = occluderRadius ?? 0;

    // static per-subcell numeral coverage — (cols*2) x (rows*2), rebuilt
    // only on resize/font-ready, never per frame (the numeral doesn't move)
    let numeralSub = new Uint8Array(0);
    let subCols = 0;
    let subRows = 0;

    const measureCell = (fontFamily: string) => {
      const off = document.createElement("canvas");
      const octx = off.getContext("2d");
      if (!octx) return;
      octx.font = `${cellSize}px ${fontFamily}`;
      const m = octx.measureText("█");
      cellW = Math.max(4, m.width);
      const a = m.actualBoundingBoxAscent || cellSize * 0.8;
      const d = m.actualBoundingBoxDescent || cellSize * 0.2;
      cellH = Math.max(4, a + d);
      ascent = a;
    };

    const buildNumeralMask = (fontFamily: string) => {
      subCols = cols * 2;
      subRows = rows * 2;
      numeralSub = new Uint8Array(subCols * subRows);
      if (subCols < 2 || subRows < 2) return;

      const w = cols * cellW;
      const h = rows * cellH;
      const os = MASK_OVERSAMPLE;
      const mw = Math.max(1, Math.round(w * os));
      const mh = Math.max(1, Math.round(h * os));

      const mask = document.createElement("canvas");
      mask.width = mw;
      mask.height = mh;
      const mctx = mask.getContext("2d", { willReadFrequently: true });
      if (!mctx) return;
      mctx.clearRect(0, 0, mw, mh);
      const fontPx = Math.min(w, h) * 0.62 * os; // rule 6: derive from the
      // container's smaller dimension, with real margin around the glyphs
      mctx.font = `700 ${fontPx}px ${fontFamily}`;
      mctx.textAlign = "center";
      mctx.textBaseline = "middle";
      // `mask`/`mctx` is a detached, never-appended offscreen canvas used
      // ONLY as an alpha/coverage source: this colour is never read below
      // (only `data[...+3]`, the alpha byte, is used) and `mask` is never
      // drawImage'd anywhere, so it never reaches the visible canvas or the
      // screen in either theme. The fill colour here is arbitrary and could
      // be any opaque value — it is not a token and does not need to be.
      mctx.fillStyle = "#fff";
      mctx.fillText("404", mw / 2, mh / 2);

      const data = mctx.getImageData(0, 0, mw, mh).data;
      const subW = mw / subCols;
      const subH = mh / subRows;
      const sum = new Float64Array(subCols * subRows);
      const count = new Float64Array(subCols * subRows);
      for (let py = 0; py < mh; py++) {
        const sy = Math.min(subRows - 1, Math.floor(py / subH));
        const rowBase = py * mw;
        for (let px = 0; px < mw; px++) {
          const sx = Math.min(subCols - 1, Math.floor(px / subW));
          const idx = sy * subCols + sx;
          sum[idx] += data[(rowBase + px) * 4 + 3]!;
          count[idx] += 255;
        }
      }
      for (let i = 0; i < numeralSub.length; i++) {
        numeralSub[i] = count[i]! > 0 && sum[i]! / count[i]! > COVERAGE_THRESHOLD ? 1 : 0;
      }

      cx = w / 2;
      cy = h / 2;
      const minDim = Math.min(w, h);
      orbitRx = minDim * 0.34;
      orbitRy = minDim * 0.22;
      if (occluderRadius == null) baseOccluderR = minDim * 0.16;
    };

    const resize = () => {
      const rect = root.getBoundingClientRect();
      if (rect.width < 2 || rect.height < 2) {
        sized = false;
        return;
      }
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(rect.width * dpr));
      canvas.height = Math.max(1, Math.round(rect.height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const fontFamily = getComputedStyle(canvas).fontFamily;
      measureCell(fontFamily);
      ctx.font = `${cellSize}px ${fontFamily}`;
      ctx.textAlign = "left";
      ctx.textBaseline = "alphabetic";

      cols = Math.max(8, Math.ceil(rect.width / cellW));
      rows = Math.max(8, Math.ceil(rect.height / cellH));

      if (ready) buildNumeralMask(fontFamily);
      sized = true;
    };

    // -- per-subposition occluder test: analytic distance vs a radially
    // wobbled disc edge, no raster involved -------------------------------
    const occluderCovered = (
      px: number,
      py: number,
      ox: number,
      oy: number,
      t: number
    ) => {
      const dx = px - ox;
      const dy = py - oy;
      const dist = Math.hypot(dx, dy);
      const theta = Math.atan2(dy, dx);
      const r =
        baseOccluderR *
        (1 + ORBIT_HARMONIC_AMP * Math.sin(ORBIT_HARMONIC_K * theta + t * 0.6));
      return dist <= r;
    };

    const draw = (t: number, ox: number, oy: number) => {
      if (!sized || subCols < 2) return;
      const w = cols * cellW;
      const h = rows * cellH;
      ctx.clearRect(0, 0, w, h);

      for (let gy = 0; gy < rows; gy++) {
        const cellY = gy * cellH;
        for (let gx = 0; gx < cols; gx++) {
          const cellX = gx * cellW;
          let numBits = 0;
          for (let s = 0; s < 4; s++) {
            const sx = Math.min(subCols - 1, (gx * 2 + (s & 1)) | 0);
            const sy = Math.min(subRows - 1, (gy * 2 + (s >> 1)) | 0);
            if (numeralSub[sy * subCols + sx]) numBits |= 1 << s;
          }
          // cheap reject: skip the 4x hypot/atan2/sin occluder test
          // entirely for the ~95% of cells nowhere near the disc's edge
          const cellCx = cellX + cellW * 0.5;
          const cellCy = cellY + cellH * 0.5;
          const nearOccluder =
            Math.hypot(cellCx - ox, cellCy - oy) <=
            baseOccluderR * (1 + ORBIT_HARMONIC_AMP) + Math.hypot(cellW, cellH);
          let occBits = 0;
          if (nearOccluder) {
            for (let s = 0; s < 4; s++) {
              const px = cellX + cellW * SUB_DX[s]!;
              const py = cellY + cellH * SUB_DY[s]!;
              if (occluderCovered(px, py, ox, oy, t)) occBits |= 1 << s;
            }
          }
          // two draws, not one: over the numeral's interior numBits is
          // already 15, so a single fillStyle-per-cell decision would carry
          // the disc's boundary by COLOR there and stair-step it. Subtract
          // the occluder from the numeral bits and draw each remainder in
          // its own token — the boundary between them is a genuine half-cell
          // shape step in both regions, not just over empty background.
          const numOnly = numBits & ~occBits;
          if (numOnly) {
            ctx.fillStyle = muted;
            ctx.fillText(QUAD_GLYPH[numOnly]!, cellX, cellY + ascent);
          }
          if (occBits) {
            ctx.fillStyle = fg;
            ctx.fillText(QUAD_GLYPH[occBits]!, cellX, cellY + ascent);
          }
        }
      }
    };

    // -- hot-path state ------------------------------------------------------
    let raf = 0;
    let last = 0;
    let t = 0;
    let biasX = 0;
    let biasY = 0;
    let biasTargetX = 0;
    let biasTargetY = 0;
    let pointerActive = false;

    const orbitPos = (time: number) => ({
      x: cx + orbitRx * Math.sin(0.17 * time),
      y: cy + orbitRy * Math.sin(0.11 * time + 1.3),
    });

    const loop = (now: number) => {
      const dt = last ? Math.min(DT_MAX, (now - last) / 1000) : 1 / 60;
      last = now;
      t += dt;

      const tx = pointerActive ? biasTargetX : 0;
      const ty = pointerActive ? biasTargetY : 0;
      biasX += (tx - biasX) * POINTER_BIAS_EASE;
      biasY += (ty - biasY) * POINTER_BIAS_EASE;

      const base = orbitPos(t);
      draw(t, base.x + biasX, base.y + biasY);
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    const onPointerMove = (e: PointerEvent) => {
      const rect = root.getBoundingClientRect();
      // pointer BIASES the orbit, never replaces it — an idle pointer
      // parked mid-canvas must not freeze the occluder
      biasTargetX = (e.clientX - rect.left - cx) * 0.35;
      biasTargetY = (e.clientY - rect.top - cy) * 0.35;
      pointerActive = true;
    };
    const onPointerLeave = () => {
      pointerActive = false;
    };

    const onVis = () => {
      if (!document.hidden && !reduced && ready) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
        if (reduced && ready) {
          draw(0, cx + orbitRx * STATIC_OFFSET_X, cy + orbitRy * STATIC_OFFSET_Y);
        }
      }, 150);
    };
    const ro = new ResizeObserver(onResize);
    ro.observe(root);

    const io = new IntersectionObserver((entries) => {
      const visible = entries[0]?.isIntersecting ?? true;
      if (visible && !document.hidden && !reduced && ready && !raf) {
        last = 0;
        raf = requestAnimationFrame(loop);
      } else if (!visible && raf) {
        cancelAnimationFrame(raf);
        raf = 0;
      }
    });
    io.observe(root);

    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced && ready) {
        draw(0, cx + orbitRx * STATIC_OFFSET_X, cy + orbitRy * STATIC_OFFSET_Y);
      }
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    document.fonts.ready.then(() => {
      if (disposed) return;
      ready = true; // must land before resize() so buildNumeralMask runs on mount
      resize();
      readTokens();
      if (reduced) {
        draw(0, cx + orbitRx * STATIC_OFFSET_X, cy + orbitRy * STATIC_OFFSET_Y);
      } else {
        raf = requestAnimationFrame(loop);
      }
    });

    window.addEventListener("resize", onResize);
    if (!reduced) {
      root.addEventListener("pointermove", onPointerMove);
      root.addEventListener("pointerleave", onPointerLeave);
    }
    document.addEventListener("visibilitychange", onVis);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      window.removeEventListener("resize", onResize);
      root.removeEventListener("pointermove", onPointerMove);
      root.removeEventListener("pointerleave", onPointerLeave);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [cellSize, occluderRadius]);

  return (
    <div
      ref={rootRef}
      className={`relative isolate w-full overflow-hidden bg-background font-mono ${
        /\bmin-h-/.test(className) ? "" : "min-h-screen"
      } ${className}`}
    >
      <canvas
        ref={canvasRef}
        aria-hidden
        className="absolute inset-0 block h-full w-full text-foreground"
      />
      <h1 className="sr-only">404 — page not found</h1>
      {children ? (
        <div className="relative z-10 flex h-full w-full flex-col items-center justify-end gap-4 p-8 text-center sm:p-14">
          {children}
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import type { ReactNode } from "react";

// ---------------------------------------------------------------------------
// Totality — a full-bleed ASCII hero built around an OCCLUSION event: a dark
// disc (the moon) transits a bright glyph disc (the sun) sitting over a
// sparse fixed starfield. This is a compositing problem, not a field-sample
// or particle problem — per cell, in strict paint order: inside the moon's
// radius is always blank (it occludes everything beneath it, sun or star,
// unconditionally); inside the sun's radius but outside the moon draws the
// photosphere (density ramp, brighter toward its own center); a ring band
// just outside the sun's radius draws the CORONA — glyphs whose density
// carries an angular "streamer" flicker (a per-angle sine, not noise, so the
// flare pattern is smooth and repeatable) — but the corona's overall
// intensity is a single scalar driven by how closely the moon's center
// currently sits over the sun's: it is near zero during an ordinary partial
// transit and only blooms as the two centers nearly coincide (totality),
// which is the actual astronomy the effect is named for. Elsewhere, the
// fixed starfield (identical technique to hero-ascii-terrain's sky) shows
// through. The pointer DRAGS the moon across the sun (eased toward the raw
// pointer position); at rest, a slow idle drift carries it back and forth on
// its own so the transit is never a dead frame.
// ---------------------------------------------------------------------------

const RAMP = " .:-=+*#%@";
const STAR_CHARS = [1, 2, 3];
const CURSOR_EASE = 0.08;
const IDLE_PERIOD = 9; // s for one full idle sweep across the sun
const DT_MAX = 0.05;

function mulberry32(a: number) {
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export interface TotalityProps {
  /** grid cell size in px */
  cellSize?: number;
  /** headline / CTA rendered over the field */
  children?: ReactNode;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function Totality({
  cellSize = 13,
  children,
  className = "",
}: TotalityProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    let fg = "currentColor";
    let muted = "currentColor";
    let accent = "currentColor";
    let cellW = cellSize;
    let cellH = cellSize;
    let cols = 0;
    let rows = 0;
    let dpr = 1;
    let sized = false;
    let ready = false;
    let disposed = false;

    let sunPx = 0;
    let sunPy = 0;
    let sunR = 0;
    let moonR = 0;
    let coronaW = 0;

    let starCol = new Float32Array(0);
    let starRow = new Float32Array(0);
    let starChar = new Uint8Array(0);
    let starPhase = new Float32Array(0);
    let starAlpha = new Float32Array(0);
    let starCount = 0;

    const readTokens = () => {
      fg = getComputedStyle(canvas).color;
      const cs = getComputedStyle(document.documentElement);
      muted = cs.getPropertyValue("--ns-muted").trim() || fg;
      accent = cs.getPropertyValue("--ns-accent").trim() || fg;
    };

    const measureCell = (fontFamily: string) => {
      const off = document.createElement("canvas");
      const octx = off.getContext("2d");
      if (!octx) return;
      octx.font = `${cellSize}px ${fontFamily}`;
      cellW = Math.max(4, octx.measureText("MMMMMMMMMM").width / 10);
      cellH = cellSize;
    };

    const buildStars = () => {
      const w = cols * cellW;
      const h = rows * cellH;
      const rand = mulberry32(0x0ec11950 ^ (cols * 71 + rows));
      starCount = Math.min(260, Math.max(0, Math.floor(cols * rows * 0.045)));
      starCol = new Float32Array(starCount);
      starRow = new Float32Array(starCount);
      starChar = new Uint8Array(starCount);
      starPhase = new Float32Array(starCount);
      starAlpha = new Float32Array(starCount);
      for (let i = 0; i < starCount; i++) {
        starCol[i] = rand() * w;
        starRow[i] = rand() * h;
        starChar[i] = STAR_CHARS[Math.floor(rand() * STAR_CHARS.length)]!;
        starPhase[i] = rand() * Math.PI * 2;
        starAlpha[i] = 0.25 + rand() * 0.45;
      }
    };

    const resize = () => {
      const { width, height } = canvas.getBoundingClientRect();
      if (width < 2 || height < 2) {
        sized = false;
        return;
      }
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const fontFamily = getComputedStyle(canvas).fontFamily;
      measureCell(fontFamily);
      ctx.font = `${cellSize}px ${fontFamily}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";

      cols = Math.max(8, Math.ceil(width / cellW));
      rows = Math.max(8, Math.ceil(height / cellH));

      sunPx = cols * cellW * 0.5;
      sunPy = rows * cellH * 0.42;
      sunR = Math.min(cols * cellW, rows * cellH) * 0.15;
      moonR = sunR * 1.04;
      coronaW = sunR * 0.65;

      buildStars();
      sized = true;
    };

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
        if (reduced) draw(0, sunPx - moonR * 2.4, sunPy);
      }, 150);
    };

    const draw = (t: number, moonPx: number, moonPy: number) => {
      if (!sized) return;
      const w = cols * cellW;
      const h = rows * cellH;
      ctx.clearRect(0, 0, w, h);

      const centerDist = Math.hypot(moonPx - sunPx, moonPy - sunPy);
      const coronaIntensity = Math.pow(
        Math.max(0, 1 - centerDist / (sunR * 0.85)),
        2
      );

      // -- starfield: sparse breathing background, drawn first ---------------
      ctx.fillStyle = muted;
      for (let i = 0; i < starCount; i++) {
        const dm = Math.hypot(starCol[i]! - moonPx, starRow[i]! - moonPy);
        if (dm <= moonR) continue; // occluded by the moon
        const twinkle = 0.6 + 0.4 * Math.sin(t * 0.6 + starPhase[i]!);
        ctx.globalAlpha = starAlpha[i]! * twinkle;
        ctx.fillText(RAMP[starChar[i]!]!, starCol[i]!, starRow[i]!);
      }

      // -- sun + corona + moon occlusion, one pass over a coarse cell grid ---
      const outerR = sunR + coronaW;
      for (let gy = 0; gy < rows; gy++) {
        const py = gy * cellH + cellH / 2;
        for (let gx = 0; gx < cols; gx++) {
          const px = gx * cellW + cellW / 2;

          const dMoon = Math.hypot(px - moonPx, py - moonPy);
          if (dMoon <= moonR) continue; // the moon occludes everything, always

          const dSun = Math.hypot(px - sunPx, py - sunPy);
          if (dSun <= sunR) {
            const lum = 1 - (dSun / sunR) * 0.55;
            const ci = Math.max(1, Math.floor(lum * (RAMP.length - 1)));
            ctx.fillStyle = fg;
            ctx.globalAlpha = 0.55 + lum * 0.45;
            ctx.fillText(RAMP[ci]!, px, py);
            continue;
          }

          if (dSun <= outerR && coronaIntensity > 0.02) {
            const radial = 1 - (dSun - sunR) / coronaW;
            const angle = Math.atan2(py - sunPy, px - sunPx);
            const streamer = 0.55 + 0.45 * Math.sin(angle * 7 + t * 1.4);
            const lum = radial * streamer * coronaIntensity;
            if (lum > 0.05) {
              const ci = Math.max(1, Math.floor(lum * (RAMP.length - 1)));
              ctx.fillStyle = accent;
              ctx.globalAlpha = Math.min(1, lum);
              ctx.fillText(RAMP[ci]!, px, py);
            }
          }
        }
      }
      ctx.globalAlpha = 1;
    };

    // -- hot-path state -------------------------------------------------------
    let raf = 0;
    let last = 0;
    let t = 0;
    const cursor = { has: false, tx: 0, ty: 0, x: 0, y: 0 };

    const loop = (now: number) => {
      const dt = last ? Math.min(DT_MAX, (now - last) / 1000) : 1 / 60;
      last = now;
      t += dt;

      let moonPx: number;
      let moonPy: number;
      if (cursor.has) {
        cursor.x += (cursor.tx - cursor.x) * CURSOR_EASE;
        cursor.y += (cursor.ty - cursor.y) * CURSOR_EASE;
        moonPx = cursor.x;
        moonPy = cursor.y;
      } else {
        // idle transit: a slow sweep back and forth through the sun
        const phase = (t / IDLE_PERIOD) % 1;
        const sweep = Math.sin(phase * Math.PI * 2);
        moonPx = sunPx + sweep * moonR * 2.6;
        moonPy = sunPy + Math.sin(phase * Math.PI * 4) * moonR * 0.35;
        cursor.x = moonPx;
        cursor.y = moonPy;
      }

      draw(t, moonPx, moonPy);
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    const onPointerMove = (e: PointerEvent) => {
      const rect = root.getBoundingClientRect();
      cursor.tx = e.clientX - rect.left;
      cursor.ty = e.clientY - rect.top;
      cursor.has = true;
    };
    const onPointerLeave = () => {
      cursor.has = false;
    };

    const onVis = () => {
      if (!document.hidden && !reduced && ready) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };
    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) draw(0, sunPx - moonR * 2.4, sunPy);
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    document.fonts.ready.then(() => {
      if (disposed) return;
      readTokens();
      resize();
      ready = true;
      if (reduced) {
        // static frame: moon well clear of the sun, an ordinary partial
        // transit moment, corona at rest (near zero)
        draw(0, sunPx - moonR * 2.4, sunPy);
      } else {
        raf = requestAnimationFrame(loop);
      }
    });

    window.addEventListener("resize", onResize);
    if (!reduced) {
      root.addEventListener("pointermove", onPointerMove);
      root.addEventListener("pointerleave", onPointerLeave);
    }
    document.addEventListener("visibilitychange", onVis);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      mo.disconnect();
      window.removeEventListener("resize", onResize);
      root.removeEventListener("pointermove", onPointerMove);
      root.removeEventListener("pointerleave", onPointerLeave);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [cellSize]);

  return (
    <div
      ref={rootRef}
      className={`relative isolate w-full overflow-hidden bg-background font-mono ${
        /\bmin-h-/.test(className) ? "" : "min-h-screen"
      } ${className}`}
    >
      <canvas
        ref={canvasRef}
        aria-hidden
        className="absolute inset-0 block h-full w-full text-foreground"
      />
      {children ? (
        <div className="relative z-10 flex h-full w-full flex-col items-start justify-end gap-4 p-8 sm:p-14">
          {children}
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import type { ReactNode } from "react";

// ---------------------------------------------------------------------------
// StrikeFigure — a full-bleed ASCII hero running the Dielectric Breakdown
// Model (Niemeyer-Pietronero-Wiesmann) directly on the glyph grid. The
// discharge channel is a perfect conductor held at phi = 0; the left and
// right plates are held at phi = 1; top and bottom are insulating (Neumann,
// mirrored rows), which is what makes the figure spread ACROSS the frame
// instead of sprinting for whichever edge happens to be nearest. Each frame
// runs 12 Gauss-Seidel sweeps of the 5-point Laplace stencil over the
// aggregate's bounding box (the far field is flat at 1, so relaxing outside
// it buys nothing), then grows the tree one site at a time by drawing a
// candidate — an unoccupied 4-neighbour of the aggregate — with probability
// proportional to phi_i^eta. Growth is held PLATE_CLEARANCE columns clear of
// the two plates; see that constant for why.
//
// eta is the whole character of the piece. At eta = 1 this is a fat DLA blob;
// at eta = 3 the tip with the steepest local field wins almost every draw, so
// the aggregate collapses into a few long, sharply forked channels covering
// ~3% of the grid and leaving the rest of the frame black. That sparsity is
// structural, not a threshold applied afterwards.
//
// Glyphs are chosen by BRANCH GEOMETRY rather than luminance: the two-link
// chord from a cell's grandparent gives '-', '|', '/' or '\', and any cell
// that acquires a second child becomes '+', the fork. The tree therefore
// reads as drawn line-work. Brightness is pow(1 - depth/maxDepth, 0.7), so
// the trunk near the seed is hot and the fine tips are faint, which is what a
// discharge photograph actually looks like.
//
// The pointer is an electrode. Cells within 6 of it are pinned above plate
// potential on a gaussian profile, eased in over tau 0.45s; because the
// growth weight goes as phi^3, the Laplace solution steepens toward it and
// new branches visibly fork and race for the cursor. On leave the pin eases
// back out and later branching returns to its undisturbed statistics.
// Already-grown channel stays exactly where it is: a discharge does not
// un-happen.
//
// The optional `quiet` rect is a patch of dielectric held at lower field
// strength: its scale multiplies the growth weight, so fewer channels grow
// there and the figure thins out to nothing across the falloff band. Overlaid
// copy therefore reads against bare background without a scrim over the field.
// ---------------------------------------------------------------------------

/** '-' horizontal link, '|' vertical, '/' and '\' the two diagonals, '+' a fork */
const GLYPHS = ["-", "|", "/", "\\", "+"] as const;

const BUCKETS = 6; // alpha buckets — one ctx.globalAlpha write each, never per cell
const SWEEPS = 12; // Gauss-Seidel sweeps per animated frame
const PRIME_SWEEPS = 2; // sweeps per site when a figure is built in one go
const PRIME_WARMUP = 40; // sweeps before the first site of a primed figure

const GROW_MS = 2200; // a figure completes in ~2.2s
const PERIOD_MS = 3600; // a new strike is seeded every 3.6s
const FADE_DELAY_MS = 4900; // ...and starts fading only once its successor is well under way
const FADE_MS = 1600; // ~0.6 alpha/s

const SITES_PER_COL = 3.2; // budget tied to width, because the figure must span it
const MIN_SITES = 160;
const MAX_SITES = 1000;

const RELAX_MARGIN = 14; // cells of slack around the aggregate bbox
// Columns 0 and cols-1 are the plates: the relaxation never writes them, so
// they hold phi = 1 forever. A cell at x = 1 therefore always has a
// full-strength source as a neighbour, and once the channel touched the plate
// it ran straight down it — a dead-straight 1-cell rule glued to the frame
// edge that took ~11% of the figure's sites (measured, both plates). Growth is
// kept this many columns clear of the plates, which drops that to ~4% and
// leaves the branch that gets there reading as a trunk rather than a border.
// x only: the top and bottom rows ARE written, by the Neumann mirror, so they
// are not sources and a y clearance would cost vertical span for nothing.
const PLATE_CLEARANCE = 10; // columns
const ELECTRODE_R = 6; // cells
const ELECTRODE_SIGMA2 = 18;
const ELECTRODE_GAIN = 0.9;
const ELECTRODE_TAU = 0.45; // s
const DT_MAX = 0.05;

/** deterministic PRNG — a session replays identically, unlike Math.random */
function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

interface Strike {
  occupied: Uint8Array;
  parent: Int32Array;
  candParent: Int32Array;
  depth: Uint16Array;
  kids: Uint8Array;
  glyph: Uint8Array;
  order: Int32Array;
  isCand: Uint8Array;
  cands: number[];
  count: number;
  maxDepth: number;
  born: number; // seconds, on the loop clock
  done: boolean;
  minX: number;
  maxX: number;
  minY: number;
  maxY: number;
}

export interface StrikeFigureProps {
  /** grid cell size in px */
  cellSize?: number;
  /** DBM growth exponent — 1 is a fat blob, 3 the sparse forked lightning figure */
  eta?: number;
  /**
   * Rect of lowered field strength in normalized frame coords (0..1 from the
   * top-left) — pass the rect the overlaid copy occupies. Growth weight is
   * scaled to zero inside it and ramps back to full just outside, so the
   * discharge grows fewer channels there instead of being masked afterwards.
   */
  quiet?: { x: number; y: number; w: number; h: number };
  /** copy overlaid on the discharge; also informs the `quiet` rect's contents */
  children?: ReactNode;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function StrikeFigure({
  cellSize = 12,
  eta = 3.0,
  quiet,
  children,
  className = "",
}: StrikeFigureProps) {
  // primitives, not the object: an inline literal from the parent would
  // otherwise be a fresh identity every render and rebuild the whole figure
  const qx = quiet ? quiet.x : 0;
  const qy = quiet ? quiet.y : 0;
  const qw = quiet ? quiet.w : 0;
  const qh = quiet ? quiet.h : 0;
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let fg = "currentColor";
    let accent = "currentColor";
    let cellW = cellSize;
    let cellH = cellSize;
    let cols = 0;
    let rows = 0;
    let target = 0;
    let keep = 1; // resolved plate clearance, clamped to the grid in rebuild()
    let sized = false;
    let disposed = false;

    let phi = new Float32Array(0);
    // per-cell field scale: 1 everywhere by default, 0 inside the quiet rect,
    // smoothstepped back up across the falloff band so there is no contour
    let quietMask: Float32Array | null = null;
    let pool: Strike[] = [];
    let live: Strike[] = [];
    let poolCursor = 0;
    let rng = mulberry32(0x1ec47);
    let seedFlip = 0;
    let nextBirth = 0;

    const bucketLists: number[][] = Array.from({ length: BUCKETS }, () => []);

    // -- tokens ---------------------------------------------------------------
    const readTokens = () => {
      fg = getComputedStyle(canvas).color;
      const raw = getComputedStyle(document.documentElement)
        .getPropertyValue("--ns-accent")
        .trim();
      accent = raw || fg;
    };

    // -- geometry -------------------------------------------------------------
    const makeStrike = (): Strike => {
      const n = cols * rows;
      return {
        occupied: new Uint8Array(n),
        parent: new Int32Array(n),
        candParent: new Int32Array(n),
        depth: new Uint16Array(n),
        kids: new Uint8Array(n),
        glyph: new Uint8Array(n),
        order: new Int32Array(target),
        isCand: new Uint8Array(n),
        cands: [],
        count: 0,
        maxDepth: 1,
        born: 0,
        done: false,
        minX: 0,
        maxX: 0,
        minY: 0,
        maxY: 0,
      };
    };

    // -- field ----------------------------------------------------------------
    // Dirichlet phi = 1 on the left and right plates (columns 0 and cols-1),
    // Neumann on top and bottom, phi = 0 inside the channel.
    const resetField = () => {
      phi.fill(1);
    };

    /**
     * A region of the dielectric held at lower field strength grows fewer
     * channels — that is all this is. The scale multiplies the growth weight,
     * so the tree thins out and stops at the edge of the rect on its own
     * rather than being covered up after the fact.
     */
    const buildQuietMask = () => {
      if (qw <= 0 || qh <= 0) {
        quietMask = null;
        return;
      }
      const x0 = qx * cols;
      const x1 = (qx + qw) * cols;
      const y0 = qy * rows;
      const y1 = (qy + qh) * rows;
      // the falloff band, 5% of the frame width and never under 2 cells: a
      // hard edge would read as the panel this whole approach exists to avoid
      const band = Math.max(2, 0.05 * cols);
      const m = new Float32Array(cols * rows);
      for (let y = 0; y < rows; y++) {
        const dy = y < y0 ? y0 - y : y > y1 ? y - y1 : 0;
        for (let x = 0; x < cols; x++) {
          const dx = x < x0 ? x0 - x : x > x1 ? x - x1 : 0;
          const d = Math.sqrt(dx * dx + dy * dy) / band;
          const f = d < 1 ? d : 1;
          m[y * cols + x] = f * f * (3 - 2 * f); // smoothstep
        }
      }
      quietMask = m;
    };

    const electrode = { gx: -1e5, gy: -1e5, has: false, strength: 0 };

    const pinElectrode = () => {
      if (electrode.strength <= 0.01) return;
      const ex = electrode.gx;
      const ey = electrode.gy;
      const s = live[live.length - 1];
      if (!s) return;
      const x0 = Math.max(1, Math.floor(ex - ELECTRODE_R));
      const x1 = Math.min(cols - 2, Math.ceil(ex + ELECTRODE_R));
      const y0 = Math.max(1, Math.floor(ey - ELECTRODE_R));
      const y1 = Math.min(rows - 2, Math.ceil(ey + ELECTRODE_R));
      const r2 = ELECTRODE_R * ELECTRODE_R;
      for (let y = y0; y <= y1; y++) {
        const row = y * cols;
        for (let x = x0; x <= x1; x++) {
          const dx = x - ex;
          const dy = y - ey;
          const d2 = dx * dx + dy * dy;
          if (d2 > r2) continue;
          const i = row + x;
          if (s.occupied[i]) continue;
          phi[i] =
            1 +
            ELECTRODE_GAIN * Math.exp(-d2 / ELECTRODE_SIGMA2) * electrode.strength;
        }
      }
    };

    const relax = (sweeps: number, s: Strike) => {
      let x0 = Math.max(1, s.minX - RELAX_MARGIN);
      let x1 = Math.min(cols - 2, s.maxX + RELAX_MARGIN);
      let y0 = Math.max(1, s.minY - RELAX_MARGIN);
      let y1 = Math.min(rows - 2, s.maxY + RELAX_MARGIN);
      if (electrode.strength > 0.01) {
        x0 = Math.max(1, Math.min(x0, Math.floor(electrode.gx - ELECTRODE_R - 2)));
        x1 = Math.min(cols - 2, Math.max(x1, Math.ceil(electrode.gx + ELECTRODE_R + 2)));
        y0 = Math.max(1, Math.min(y0, Math.floor(electrode.gy - ELECTRODE_R - 2)));
        y1 = Math.min(rows - 2, Math.max(y1, Math.ceil(electrode.gy + ELECTRODE_R + 2)));
      }
      if (x1 < x0 || y1 < y0) return;
      const occ = s.occupied;
      for (let k = 0; k < sweeps; k++) {
        for (let y = y0; y <= y1; y++) {
          const row = y * cols;
          for (let x = x0; x <= x1; x++) {
            const i = row + x;
            if (occ[i]) {
              phi[i] = 0;
              continue;
            }
            phi[i] =
              0.25 * (phi[i - 1] + phi[i + 1] + phi[i - cols] + phi[i + cols]);
          }
        }
        // insulating top/bottom: the ghost row mirrors its neighbour
        if (y0 <= 1) {
          for (let x = x0; x <= x1; x++) phi[x] = phi[cols + x];
        }
        if (y1 >= rows - 2) {
          const a = (rows - 1) * cols;
          const b = (rows - 2) * cols;
          for (let x = x0; x <= x1; x++) phi[a + x] = phi[b + x];
        }
        pinElectrode();
      }
    };

    // -- growth ---------------------------------------------------------------
    const addCandidate = (s: Strike, i: number, from: number) => {
      if (s.occupied[i] || s.isCand[i]) return;
      s.isCand[i] = 1;
      s.candParent[i] = from;
      s.cands.push(i);
    };

    const occupy = (s: Strike, i: number, from: number) => {
      s.occupied[i] = 1;
      phi[i] = 0;
      s.parent[i] = from;
      const x = i % cols;
      const y = (i - x) / cols;
      if (s.count === 0) {
        s.minX = s.maxX = x;
        s.minY = s.maxY = y;
      } else {
        if (x < s.minX) s.minX = x;
        if (x > s.maxX) s.maxX = x;
        if (y < s.minY) s.minY = y;
        if (y > s.maxY) s.maxY = y;
      }

      if (from < 0) {
        s.depth[i] = 0;
        s.glyph[i] = 4;
      } else {
        const d = s.depth[from]! + 1;
        s.depth[i] = d;
        if (d > s.maxDepth) s.maxDepth = d;
        s.kids[from] = (s.kids[from]! + 1) as number;
        if (s.kids[from]! >= 2) s.glyph[from] = 4; // this cell forked

        // glyph from the two-link chord (grandparent -> here), so a staircase
        // run reads as a diagonal rather than a stack of alternating dashes
        const gp = s.parent[from]! >= 0 ? s.parent[from]! : from;
        const gx = gp % cols;
        const gy = (gp - gx) / cols;
        const dx = x - gx;
        const dy = y - gy;
        const adx = dx < 0 ? -dx : dx;
        const ady = dy < 0 ? -dy : dy;
        let g: number;
        if (adx > 0 && ady > 0) g = dx * dy > 0 ? 3 : 2;
        else if (adx >= ady) g = 0;
        else g = 1;
        s.glyph[i] = g;
      }

      s.order[s.count] = i;
      s.count++;

      if (y > 1) addCandidate(s, i - cols, i);
      if (y < rows - 2) addCandidate(s, i + cols, i);
      if (x > keep) addCandidate(s, i - 1, i);
      if (x < cols - 1 - keep) addCandidate(s, i + 1, i);
    };

    /** one DBM growth event: draw a candidate with p ∝ phi^eta */
    const growOne = (s: Strike): boolean => {
      const cands = s.cands;
      const n = cands.length;
      if (n === 0 || s.count >= target) return false;
      const q = quietMask;
      let total = 0;
      for (let k = 0; k < n; k++) {
        const c = cands[k]!;
        const p = phi[c]!;
        if (p > 0) total += Math.pow(p, eta) * (q ? q[c]! : 1);
      }
      let li: number;
      if (total > 1e-12) {
        const r = rng() * total;
        let acc = 0;
        li = n - 1;
        for (let k = 0; k < n; k++) {
          const c = cands[k]!;
          const p = phi[c]!;
          if (p > 0) acc += Math.pow(p, eta) * (q ? q[c]! : 1);
          if (acc >= r) {
            li = k;
            break;
          }
        }
      } else {
        li = Math.min(n - 1, Math.floor(rng() * n));
      }
      const pick = cands[li]!;
      cands[li] = cands[n - 1]!;
      cands.pop();
      s.isCand[pick] = 0;
      occupy(s, pick, s.candParent[pick]!);
      return true;
    };

    const seedStrike = (s: Strike, t: number) => {
      s.occupied.fill(0);
      s.isCand.fill(0);
      s.kids.fill(0);
      s.cands.length = 0;
      s.count = 0;
      s.maxDepth = 1;
      s.done = false;
      s.born = t;
      resetField();

      // two anchors, alternating, with a jittered offset — successive strikes
      // land on opposite thirds of the frame
      const upperLeft = seedFlip % 2 === 0;
      seedFlip++;
      const fx = upperLeft ? 0.3 : 0.7;
      const fy = upperLeft ? 0.34 : 0.66;
      const jx = (rng() - 0.5) * 0.1 * cols;
      const jy = (rng() - 0.5) * 0.16 * rows;
      const sx = Math.min(
        cols - 2 - keep,
        Math.max(keep + 1, Math.round(fx * cols + jx))
      );
      const sy = Math.min(rows - 3, Math.max(2, Math.round(fy * rows + jy)));
      occupy(s, sy * cols + sx, -1);
    };

    /** build one complete figure in a single blocking pass */
    const primeStrike = (s: Strike, t: number) => {
      seedStrike(s, t);
      relax(PRIME_WARMUP, s);
      while (s.count < target) {
        relax(PRIME_SWEEPS, s);
        if (!growOne(s)) break;
      }
      s.done = true;
    };

    // -- render ---------------------------------------------------------------
    const strikeAlpha = (s: Strike, t: number) => {
      const ageMs = (t - s.born) * 1000;
      if (ageMs <= FADE_DELAY_MS) return 1;
      return Math.max(0, 1 - (ageMs - FADE_DELAY_MS) / FADE_MS);
    };

    const draw = (t: number) => {
      if (!sized) return;
      ctx.clearRect(0, 0, cols * cellW, rows * cellH);
      for (let b = 0; b < BUCKETS; b++) bucketLists[b]!.length = 0;

      for (let si = 0; si < live.length; si++) {
        const s = live[si]!;
        const a = strikeAlpha(s, t);
        if (a <= 0.01) continue;
        const md = Math.max(4, s.maxDepth);
        for (let k = 0; k < s.count; k++) {
          const idx = s.order[k]!;
          const rel = 1 - s.depth[idx]! / md;
          const lum = Math.pow(rel > 0.08 ? rel : 0.08, 0.7) * a;
          let b = Math.floor(lum * BUCKETS);
          if (b < 0) b = 0;
          else if (b > BUCKETS - 1) b = BUCKETS - 1;
          bucketLists[b]!.push(idx * 5 + s.glyph[idx]!);
        }
      }

      for (let b = 0; b < BUCKETS; b++) {
        const list = bucketLists[b]!;
        if (list.length === 0) continue;
        ctx.globalAlpha = 0.1 + (b / (BUCKETS - 1)) * 0.9;
        // the hot core of the channel carries the one accent; everything else
        // is monochrome ink
        ctx.fillStyle = b === BUCKETS - 1 ? accent : fg;
        for (let k = 0; k < list.length; k++) {
          const v = list[k]!;
          const g = v % 5;
          const idx = (v - g) / 5;
          const gx = idx % cols;
          const gy = (idx - gx) / cols;
          ctx.fillText(
            GLYPHS[g]!,
            gx * cellW + cellW / 2,
            gy * cellH + cellH / 2
          );
        }
      }
      ctx.globalAlpha = 1;
    };

    // -- sizing ---------------------------------------------------------------
    const measureCell = (fontFamily: string) => {
      const off = document.createElement("canvas");
      const octx = off.getContext("2d");
      if (!octx) return;
      octx.font = `${cellSize}px ${fontFamily}`;
      cellW = Math.max(4, octx.measureText("MMMMMMMMMM").width / 10);
      cellH = cellSize;
    };

    const rebuild = (t: number) => {
      const { width, height } = canvas.getBoundingClientRect();
      if (width < 2 || height < 2) {
        sized = false;
        return;
      }
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const fontFamily = getComputedStyle(canvas).fontFamily;
      measureCell(fontFamily);
      ctx.font = `${cellSize}px ${fontFamily}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      cols = Math.max(12, Math.ceil(width / cellW));
      rows = Math.max(12, Math.ceil(height / cellH));
      // a narrow grid must still leave room to grow between the two clearances
      keep = Math.max(1, Math.min(PLATE_CLEARANCE, Math.floor(cols / 6)));
      target = Math.max(
        MIN_SITES,
        Math.min(MAX_SITES, Math.round(cols * SITES_PER_COL))
      );
      phi = new Float32Array(cols * rows);
      buildQuietMask();
      rng = mulberry32(0x1ec47);
      seedFlip = 0;
      pool = [makeStrike(), makeStrike()];
      poolCursor = 0;
      live = [];
      sized = true;

      // the frame is never allowed to open empty: the first figure is built
      // complete, then back-dated so it is already in its hold phase
      const first = pool[0]!;
      poolCursor = 1;
      primeStrike(first, t - GROW_MS / 1000);
      live = [first];
      nextBirth = first.born + PERIOD_MS / 1000;
      draw(t);
    };

    // -- loop -----------------------------------------------------------------
    let raf = 0;
    let last = 0;
    let clock = 0;

    const step = (dt: number) => {
      clock += dt;
      const t = clock;

      const want = electrode.has ? 1 : 0;
      electrode.strength +=
        (want - electrode.strength) * Math.min(1, dt / ELECTRODE_TAU);

      // retire dead strikes before spawning, so the pool of two always has a
      // free slot
      for (let i = live.length - 1; i >= 0; i--) {
        if ((t - live[i]!.born) * 1000 > FADE_DELAY_MS + FADE_MS) live.splice(i, 1);
      }

      if (t >= nextBirth) {
        const s = pool[poolCursor % 2]!;
        poolCursor++;
        const at = live.indexOf(s);
        if (at >= 0) live.splice(at, 1);
        seedStrike(s, t);
        live.push(s);
        nextBirth = t + PERIOD_MS / 1000;
      }

      const g = live[live.length - 1];
      if (g) {
        if (!g.done) {
          relax(SWEEPS, g);
          const wantN = Math.min(
            target,
            Math.round((target * ((t - g.born) * 1000)) / GROW_MS)
          );
          let n = wantN - g.count;
          while (n-- > 0 && growOne(g)) {
            /* one site per tick */
          }
          if (g.count >= target || g.cands.length === 0) g.done = true;
        } else if (electrode.strength > 0.01) {
          // keep the field warm so the electrode is already in the solution
          // when the next strike seeds
          relax(2, g);
        }
      }

      draw(t);
    };

    const loop = (now: number) => {
      const dt = last ? Math.min(DT_MAX, (now - last) / 1000) : 1 / 60;
      last = now;
      step(dt);
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    // -- listeners ------------------------------------------------------------
    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        rebuild(clock);
      }, 150);
    };

    const onPointerMove = (e: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      electrode.gx = (e.clientX - rect.left) / cellW;
      electrode.gy = (e.clientY - rect.top) / cellH;
      electrode.has = true;
    };
    const onPointerLeave = () => {
      electrode.has = false;
    };

    const onVis = () => {
      if (!document.hidden && !reduced && sized) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) draw(clock);
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    document.fonts.ready.then(() => {
      if (disposed) return;
      readTokens();
      rebuild(0);
      if (!reduced) raf = requestAnimationFrame(loop);
    });

    window.addEventListener("resize", onResize);
    if (!reduced) {
      root.addEventListener("pointermove", onPointerMove);
      root.addEventListener("pointerleave", onPointerLeave);
    }
    document.addEventListener("visibilitychange", onVis);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      mo.disconnect();
      window.removeEventListener("resize", onResize);
      root.removeEventListener("pointermove", onPointerMove);
      root.removeEventListener("pointerleave", onPointerLeave);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [cellSize, eta, qx, qy, qw, qh]);

  // `h-full` matters as much as the min-height: a min-height is only a floor,
  // so a stretched grid/flex parent taller than it would leave a band of dead
  // background under the field.
  return (
    <div
      ref={rootRef}
      className={`relative isolate h-full w-full overflow-hidden bg-background font-mono ${
        /\bmin-h-/.test(className) ? "" : "min-h-screen"
      } ${className}`}
    >
      <canvas
        ref={canvasRef}
        aria-hidden
        className="absolute inset-0 block h-full w-full text-foreground"
      />
      {children ? (
        <div className="relative z-10 flex h-full w-full flex-col items-start justify-end gap-4 p-8 sm:p-14">
          {children}
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import type { ReactNode } from "react";

// ---------------------------------------------------------------------------
// Downpour — a full-bleed ASCII precipitation hero. Unlike a stamped heat grid
// or a sampled scalar field, this is a genuine per-column PARTICLE simulation:
// every column owns one falling "drop" (a float head position in row-units, a
// rows/sec fall speed and a trail length), advancing independently every
// frame and wrapping back above the top once its trail clears the bottom —
// the same treadmill trick a starfield uses, so the loop never resets
// visibly. A column's glyph only gets reassigned the instant the head enters
// a NEW row (not every frame), so a settled trail doesn't flicker; luminance
// is purely a function of distance-from-head, gamma-shaped so the head reads
// bright and the tail fades to ink. The pointer doesn't paint or warp
// individual cells — it drives WIND: a per-column lateral pixel offset,
// gaussian-weighted by horizontal distance to the pointer and gusting on a
// per-column sine so nearby streams bend independently rather than as one
// rigid sheet, with the gust's overall amplitude rising on pointer speed and
// relaxing over ~1s once it stops, so the curtain settles back to falling
// straight down on its own.
// ---------------------------------------------------------------------------

const RAIN_CHARS = "|:.'`,;";
const SPEED_MIN = 9; // rows/s
const SPEED_MAX = 22;
const TRAIL_MIN = 6; // rows
const TRAIL_MAX = 18;
const WIND_RADIUS_COLS = 10; // gaussian falloff sigma, in columns
const WIND_MAX_PX = 14; // max lateral bend at full gust energy
const WIND_GUST_FREQ_MIN = 0.6; // rad/s
const WIND_GUST_FREQ_MAX = 1.4;
const WIND_EASE = 0.1; // per-frame lerp toward target offset
const ENERGY_GAIN = 0.05;
const ENERGY_TAU = 1.0; // s — relaxation time constant
const DT_MAX = 0.05;

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export interface DownpourProps {
  /** grid cell size in px */
  cellSize?: number;
  /** headline / CTA rendered over the field */
  children?: ReactNode;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function Downpour({
  cellSize = 13,
  children,
  className = "",
}: DownpourProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    let fg = "currentColor";
    let cellW = cellSize;
    let cellH = cellSize;
    let cols = 0;
    let rows = 0;
    let dpr = 1;
    let sized = false;
    let ready = false;
    let disposed = false;

    let headRow = new Float32Array(0);
    let speed = new Float32Array(0);
    let trailLen = new Float32Array(0);
    let lastRow = new Int32Array(0);
    let charBuf = new Uint8Array(0);
    let windOffset = new Float32Array(0);
    let windPhase = new Float32Array(0);
    let windFreq = new Float32Array(0);

    const readTokens = () => {
      fg = getComputedStyle(canvas).color;
    };

    const measureCell = (fontFamily: string) => {
      const off = document.createElement("canvas");
      const octx = off.getContext("2d");
      if (!octx) return;
      octx.font = `${cellSize}px ${fontFamily}`;
      cellW = Math.max(4, octx.measureText("MMMMMMMMMM").width / 10);
      cellH = cellSize;
    };

    const rand = mulberry32(0x5a17a1);

    const seedColumn = (c: number, initial: boolean) => {
      speed[c] = SPEED_MIN + rand() * (SPEED_MAX - SPEED_MIN);
      trailLen[c] = TRAIL_MIN + rand() * (TRAIL_MAX - TRAIL_MIN);
      // stagger restarts: begin above the top by a random multiple of the
      // column's own trail so drops never fall back in visible unison
      headRow[c] = initial
        ? rand() * rows
        : -(rand() * trailLen[c]! * 3);
      lastRow[c] = -1e6;
      windPhase[c] = rand() * Math.PI * 2;
      windFreq[c] = WIND_GUST_FREQ_MIN + rand() * (WIND_GUST_FREQ_MAX - WIND_GUST_FREQ_MIN);
    };

    const resize = () => {
      const { width, height } = canvas.getBoundingClientRect();
      if (width < 2 || height < 2) {
        sized = false;
        return;
      }
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const fontFamily = getComputedStyle(canvas).fontFamily;
      measureCell(fontFamily);
      ctx.font = `${cellSize}px ${fontFamily}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";

      // ceil, not floor — flooring leaves an unpainted strip along the
      // bottom/right edge; the root clips, so overdraw is free.
      cols = Math.max(4, Math.ceil(width / cellW));
      rows = Math.max(4, Math.ceil(height / cellH));

      headRow = new Float32Array(cols);
      speed = new Float32Array(cols);
      trailLen = new Float32Array(cols);
      lastRow = new Int32Array(cols);
      charBuf = new Uint8Array(cols * rows);
      windOffset = new Float32Array(cols);
      windPhase = new Float32Array(cols);
      windFreq = new Float32Array(cols);

      for (let c = 0; c < cols; c++) seedColumn(c, true);
      sized = true;
    };

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
        if (reduced) drawStatic();
      }, 150);
    };

    // advance the simulation by dt (no-op for the static reduced-motion frame)
    const step = (dt: number) => {
      for (let c = 0; c < cols; c++) {
        headRow[c]! += speed[c]! * dt;
        if (headRow[c]! - trailLen[c]! > rows) {
          seedColumn(c, false);
          continue;
        }
        const newRow = Math.floor(headRow[c]!);
        if (newRow !== lastRow[c] && newRow >= 0 && newRow < rows) {
          charBuf[newRow * cols + c] = Math.floor(rand() * RAIN_CHARS.length);
          lastRow[c] = newRow;
        }
      }
    };

    const draw = (t: number) => {
      if (!sized) return;
      const w = cols * cellW;
      const h = rows * cellH;
      ctx.clearRect(0, 0, w, h);
      ctx.fillStyle = fg;
      for (let c = 0; c < cols; c++) {
        const head = headRow[c]!;
        const trail = trailLen[c]!;
        const x = c * cellW + cellW / 2 + windOffset[c]!;
        const rFrom = Math.max(0, Math.ceil(head - trail));
        const rTo = Math.min(rows - 1, Math.floor(head));
        for (let r = rFrom; r <= rTo; r++) {
          const dist = head - r;
          const lum = 1 - dist / trail;
          if (lum <= 0.03) continue;
          const alpha = Math.pow(lum, 1.5);
          ctx.globalAlpha = 0.08 + alpha * 0.92;
          const ch = RAIN_CHARS[charBuf[r * cols + c]!] ?? ".";
          ctx.fillText(ch, x, r * cellH + cellH / 2);
        }
      }
      ctx.globalAlpha = 1;
      void t;
    };

    // static reduced-motion frame: fill every column full-height so the
    // silhouette of the effect is legible at rest, no animation, no listeners
    const drawStatic = () => {
      if (!sized) return;
      for (let c = 0; c < cols; c++) {
        headRow[c] = rows - 1;
        trailLen[c] = rows;
        for (let r = 0; r < rows; r++) {
          charBuf[r * cols + c] = Math.floor(rand() * RAIN_CHARS.length);
        }
        windOffset[c] = 0;
      }
      draw(0);
    };

    // -- hot-path state -------------------------------------------------------
    let raf = 0;
    let last = 0;
    let t = 0;
    const pointer = { x: -1e5, y: -1e5, tx: -1e5, ty: -1e5, energy: 0, has: false };

    const loop = (now: number) => {
      const dt = last ? Math.min(DT_MAX, (now - last) / 1000) : 1 / 60;
      last = now;
      t += dt;
      step(dt);

      pointer.energy *= Math.exp(-dt / ENERGY_TAU);
      const pointerCol = pointer.has ? pointer.x / cellW : -1e5;
      for (let c = 0; c < cols; c++) {
        let target = 0;
        if (pointer.has && pointer.energy > 0.004) {
          const dCols = c - pointerCol;
          const falloff = Math.exp(-(dCols * dCols) / (2 * WIND_RADIUS_COLS * WIND_RADIUS_COLS));
          const gust = Math.sin(t * windFreq[c]! + windPhase[c]!);
          target = falloff * pointer.energy * WIND_MAX_PX * gust;
        }
        windOffset[c]! += (target - windOffset[c]!) * WIND_EASE;
      }

      draw(t);
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    const onPointerMove = (e: PointerEvent) => {
      const rect = root.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      if (pointer.has) {
        const dx = x - pointer.tx;
        const dy = y - pointer.ty;
        const speedPx = Math.hypot(dx, dy);
        pointer.energy = Math.min(1, pointer.energy + speedPx * ENERGY_GAIN * 0.02);
      }
      pointer.tx = x;
      pointer.ty = y;
      pointer.x = x;
      pointer.y = y;
      pointer.has = true;
    };
    const onPointerLeave = () => {
      pointer.has = false;
    };

    const onVis = () => {
      if (!document.hidden && !reduced && ready) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };
    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) draw(t);
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    document.fonts.ready.then(() => {
      if (disposed) return;
      readTokens();
      resize();
      ready = true;
      if (reduced) {
        drawStatic();
      } else {
        raf = requestAnimationFrame(loop);
      }
    });

    window.addEventListener("resize", onResize);
    if (!reduced) {
      root.addEventListener("pointermove", onPointerMove);
      root.addEventListener("pointerleave", onPointerLeave);
    }
    document.addEventListener("visibilitychange", onVis);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      mo.disconnect();
      window.removeEventListener("resize", onResize);
      root.removeEventListener("pointermove", onPointerMove);
      root.removeEventListener("pointerleave", onPointerLeave);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [cellSize]);

  return (
    <div
      ref={rootRef}
      className={`relative isolate w-full overflow-hidden bg-background font-mono ${
        /\bmin-h-/.test(className) ? "" : "min-h-screen"
      } ${className}`}
    >
      <canvas
        ref={canvasRef}
        aria-hidden
        className="absolute inset-0 block h-full w-full text-foreground"
      />
      {children ? (
        <div className="relative z-10 flex h-full w-full flex-col items-start justify-end gap-4 p-8 sm:p-14">
          {children}
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// ReactionFront — a full-bleed ASCII hero driven by a live Gray-Scott
// reaction-diffusion simulation. The sim grid IS the glyph grid, so every
// character is one cell of a real chemical solver rather than a sampled
// texture.
//
// The sparsity trick, and the whole reason this reads as line structure
// instead of a wash: luminance is NOT the V concentration. Inking V would
// fill the reacted interiors and produce blobs. Instead each cell is inked by
// the MAGNITUDE OF THE GRADIENT of V — |dV/dx| + |dV/dy| — and then only the
// RIDGE of that gradient field survives: a cell inks only if its gradient is
// a local maximum along EITHER axis (non-maximum suppression; see the note at
// the ridge test for why the dominant-axis variant is wrong here). A raw
// gradient threshold inks the whole shoulder of every front, four to six
// cells wide, which measured 80% of the frame at steady state — a wash.
// Keeping the ridge alone collapses each front to a one-cell line and holds
// ink at a measured 11-15% of cells from the first paint out to 30000
// substeps, with 96% of inked cells in 8-connected runs of 8 cells or more
// and a mean run of 25 cells. Both the reacted interior and the unreacted
// bulk are flat-gradient, therefore blank, therefore each front is a line.
//
// The pointer is a pipette, not a brush: it raises V and consumes U in a
// small gaussian, which nucleates a genuinely new front under the cursor.
// When the pointer leaves, the injection eases off but the front it seeded
// keeps travelling and dissipates through the reaction's own dynamics — the
// relaxation is physical, not a fade-out.
// ---------------------------------------------------------------------------

const RAMP = " .:-=+*#%@";
const ALPHA_BUCKETS = 6;

// Gray-Scott in the worm/front regime (NOT the spot regime — spots ink as
// dots, fronts ink as lines). Du/Dv are the canonical pairing for this
// 9-point stencil at dt=1: Du*dt*|lambda|max = 1.6, inside the explicit-Euler
// stability bound of 2. Feed/kill sit in the chaotic worm band, which is the
// only band measured to be BOTH sparse and moving — the frozen bands
// (F >= 0.042) settle to exactly zero motion, dead rings.
const DU = 1.0;
const DV = 0.5;
const FEED = 0.018;
const KILL = 0.051;
const DT = 1.0;
const SUBSTEPS = 4; // sim substeps per rAF frame
const WARMUP = 600; // substeps run before the first paint
const REDUCED_EXTRA = 400; // extra substeps for the single static frame

const SEED_COUNT = 7;
const SEED_RADIUS = 4;

// sparsity: the ridge of the gradient field is the only thing that survives
const GRAD_SCALE = 0.14; // ~p95 of the ridge gradient, so the ramp spans
const GRAD_POW = 1.0;
const INK_FLOOR = 0.08;

// 9-point laplacian: diagonal weight is fixed, the two orthogonal weights are
// split by cell ASPECT so the field is isotropic ON SCREEN. A mono cell is
// ~7.2px wide and 12px tall, so an isotropic-in-grid front would render 1.67x
// taller than wide. Splitting the 0.8 orthogonal budget as 1/dx^2 : 1/dy^2
// keeps the stencil's eigenvalue (and therefore its stability bound) exactly
// where the isotropic version had it.
const W_DIAG = 0.05;
const W_ORTHO_TOTAL = 0.8;

// pipette
const INJECT_TAU = 0.4; // s
const INJECT_RADIUS = 3.5; // cells
const INJECT_V = 0.42;
const INJECT_U = 0.2;

const DT_MAX = 0.05;

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export interface ReactionFrontProps {
  /** grid cell size in px — the sim grid is the glyph grid, never supersampled */
  cellSize?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function ReactionFront({
  cellSize = 12,
  className = "",
}: ReactionFrontProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    let fg = "currentColor";
    let cellW = cellSize;
    let cellH = cellSize;
    let cols = 0;
    let rows = 0;
    let dpr = 1;
    let sized = false;
    let ready = false;
    let disposed = false;

    // ping-ponged concentration fields
    let U = new Float32Array(0);
    let V = new Float32Array(0);
    let Un = new Float32Array(0);
    let Vn = new Float32Array(0);
    // toroidal neighbour lookup
    let lf = new Int32Array(0);
    let rt = new Int32Array(0);
    let up = new Int32Array(0);
    let dn = new Int32Array(0);

    let charBuf = new Uint8Array(0);
    let gradBuf = new Float32Array(0);
    // aspect-split orthogonal laplacian weights, set in resize()
    let wx = W_ORTHO_TOTAL / 4;
    let wy = W_ORTHO_TOTAL / 4;
    const bucketLists: number[][] = Array.from(
      { length: ALPHA_BUCKETS },
      () => []
    );

    const readTokens = () => {
      fg = getComputedStyle(canvas).color;
    };

    const measureCell = (fontFamily: string) => {
      const off = document.createElement("canvas");
      const octx = off.getContext("2d");
      if (!octx) return;
      octx.font = `${cellSize}px ${fontFamily}`;
      cellW = Math.max(4, octx.measureText("MMMMMMMMMM").width / 10);
      cellH = cellSize;
    };

    const seed = () => {
      U.fill(1);
      V.fill(0);
      const rnd = mulberry32(0x5eed1);
      for (let s = 0; s < SEED_COUNT; s++) {
        const cx = Math.floor(rnd() * cols);
        const cy = Math.floor(rnd() * rows);
        for (let dy = -SEED_RADIUS; dy <= SEED_RADIUS; dy++) {
          for (let dx = -SEED_RADIUS; dx <= SEED_RADIUS; dx++) {
            if (dx * dx + dy * dy > SEED_RADIUS * SEED_RADIUS) continue;
            const x = ((cx + dx) % cols + cols) % cols;
            const y = ((cy + dy) % rows + rows) % rows;
            const i = y * cols + x;
            V[i] = 0.5;
            U[i] = 0.25;
          }
        }
      }
    };

    // one Gray-Scott substep with the 9-point laplacian and toroidal wrap
    const step = () => {
      for (let y = 0; y < rows; y++) {
        const yc = y * cols;
        const ym = up[y]! * cols;
        const yp = dn[y]! * cols;
        for (let x = 0; x < cols; x++) {
          const xm = lf[x]!;
          const xp = rt[x]!;
          const i = yc + x;
          const u = U[i]!;
          const v = V[i]!;
          const lapU =
            -u +
            wx * (U[yc + xm]! + U[yc + xp]!) +
            wy * (U[ym + x]! + U[yp + x]!) +
            W_DIAG *
              (U[ym + xm]! + U[ym + xp]! + U[yp + xm]! + U[yp + xp]!);
          const lapV =
            -v +
            wx * (V[yc + xm]! + V[yc + xp]!) +
            wy * (V[ym + x]! + V[yp + x]!) +
            W_DIAG *
              (V[ym + xm]! + V[ym + xp]! + V[yp + xm]! + V[yp + xp]!);
          const uvv = u * v * v;
          Un[i] = u + (DU * lapU - uvv + FEED * (1 - u)) * DT;
          Vn[i] = v + (DV * lapV + uvv - (FEED + KILL) * v) * DT;
        }
      }
      const tu = U;
      U = Un;
      Un = tu;
      const tv = V;
      V = Vn;
      Vn = tv;
    };

    const inject = (gx: number, gy: number, strength: number) => {
      if (strength < 0.01) return;
      const r = Math.ceil(INJECT_RADIUS);
      const cx = Math.round(gx);
      const cy = Math.round(gy);
      for (let dy = -r; dy <= r; dy++) {
        for (let dx = -r; dx <= r; dx++) {
          const d2 = dx * dx + dy * dy;
          if (d2 > INJECT_RADIUS * INJECT_RADIUS) continue;
          const x = ((cx + dx) % cols + cols) % cols;
          const y = ((cy + dy) % rows + rows) % rows;
          const i = y * cols + x;
          const g = Math.exp(-d2 / 6);
          V[i] = Math.min(1, V[i]! + INJECT_V * strength * g);
          U[i] = Math.max(0, U[i]! - INJECT_U * strength * g);
        }
      }
    };

    const draw = () => {
      if (!sized) return;
      const w = cols * cellW;
      const h = rows * cellH;
      ctx.clearRect(0, 0, w, h);
      for (let b = 0; b < ALPHA_BUCKETS; b++) bucketLists[b]!.length = 0;

      // pass one, part A — gradient magnitude of V over the whole grid
      for (let y = 0; y < rows; y++) {
        const yc = y * cols;
        const ym = up[y]! * cols;
        const yp = dn[y]! * cols;
        for (let x = 0; x < cols; x++) {
          const gx = (V[yc + rt[x]!]! - V[yc + lf[x]!]!) * 0.5;
          const gy = (V[yp + x]! - V[ym + x]!) * 0.5;
          gradBuf[yc + x] = Math.abs(gx) + Math.abs(gy);
        }
      }

      // pass one, part B — keep only the RIDGE of that gradient field, then
      // ramp-index it and bucket it by luminance
      for (let y = 0; y < rows; y++) {
        const yc = y * cols;
        const ym = up[y]! * cols;
        const yp = dn[y]! * cols;
        for (let x = 0; x < cols; x++) {
          const i = yc + x;
          charBuf[i] = 0;
          const g = gradBuf[i]!;
          // non-maximum suppression: a cell is on the ridge if its gradient is
          // a local maximum along EITHER axis. Testing only the locally
          // dominant axis breaks fronts into dashes wherever they run
          // diagonally and the two axes tie — measured 12.1 cells per
          // connected run against 25-39 for the either-axis test, at the cost
          // of a few percent more ink. Longer runs read as lines; short ones
          // read as speckle, which is the failure this whole pass exists to
          // avoid.
          const onRidge =
            (g >= gradBuf[yc + rt[x]!]! && g >= gradBuf[yc + lf[x]!]!) ||
            (g >= gradBuf[yp + x]! && g >= gradBuf[ym + x]!);
          if (!onRidge) continue;
          let lum = g / GRAD_SCALE;
          lum = lum < 0 ? 0 : lum > 1 ? 1 : lum;
          lum = Math.pow(lum, GRAD_POW);
          if (lum < INK_FLOOR) continue;
          const ci = Math.floor(lum * (RAMP.length - 1));
          charBuf[i] = ci;
          if (ci === 0) continue;
          const b = Math.min(ALPHA_BUCKETS - 1, Math.floor(lum * ALPHA_BUCKETS));
          bucketLists[b]!.push(i);
        }
      }

      // pass two — one globalAlpha write per bucket
      ctx.fillStyle = fg;
      for (let b = 0; b < ALPHA_BUCKETS; b++) {
        const list = bucketLists[b]!;
        if (list.length === 0) continue;
        ctx.globalAlpha = 0.1 + (b / (ALPHA_BUCKETS - 1)) * 0.9;
        for (let k = 0; k < list.length; k++) {
          const idx = list[k]!;
          const x = idx % cols;
          const y = (idx - x) / cols;
          ctx.fillText(
            RAMP[charBuf[idx]!]!,
            x * cellW + cellW / 2,
            y * cellH + cellH / 2
          );
        }
      }
      ctx.globalAlpha = 1;
    };

    const resize = () => {
      const { width, height } = canvas.getBoundingClientRect();
      if (width < 2 || height < 2) {
        sized = false;
        return;
      }
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const fontFamily = getComputedStyle(canvas).fontFamily;
      measureCell(fontFamily);
      ctx.font = `${cellSize}px ${fontFamily}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      cols = Math.max(8, Math.ceil(width / cellW));
      rows = Math.max(8, Math.ceil(height / cellH));

      // split the orthogonal laplacian budget by 1/dx^2 : 1/dy^2 so the sim is
      // isotropic on screen despite the non-square mono cell
      const aspect2 = (cellH / cellW) * (cellH / cellW);
      wx = (W_ORTHO_TOTAL / 2) * (aspect2 / (1 + aspect2));
      wy = (W_ORTHO_TOTAL / 2) * (1 / (1 + aspect2));

      const n = cols * rows;
      U = new Float32Array(n);
      V = new Float32Array(n);
      Un = new Float32Array(n);
      Vn = new Float32Array(n);
      charBuf = new Uint8Array(n);
      gradBuf = new Float32Array(n);
      lf = new Int32Array(cols);
      rt = new Int32Array(cols);
      up = new Int32Array(rows);
      dn = new Int32Array(rows);
      for (let x = 0; x < cols; x++) {
        lf[x] = (x - 1 + cols) % cols;
        rt[x] = (x + 1) % cols;
      }
      for (let y = 0; y < rows; y++) {
        up[y] = (y - 1 + rows) % rows;
        dn[y] = (y + 1) % rows;
      }
      sized = true;

      // MOUNT WARMUP — without it the first second of the hero is a blank grid
      seed();
      const warm = reduced ? WARMUP + REDUCED_EXTRA : WARMUP;
      for (let s = 0; s < warm; s++) step();
    };

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
        draw();
      }, 200);
    };

    // -- hot-path state -------------------------------------------------------
    let raf = 0;
    let last = 0;
    const ptr = { gx: -1e5, gy: -1e5, has: false, strength: 0 };

    const loop = (now: number) => {
      const dt = last ? Math.min(DT_MAX, (now - last) / 1000) : 1 / 60;
      last = now;
      const target = ptr.has ? 1 : 0;
      ptr.strength += (target - ptr.strength) * Math.min(1, dt / INJECT_TAU);
      if (sized) {
        if (ptr.strength > 0.01 && ptr.gx > -1e4) {
          inject(ptr.gx, ptr.gy, ptr.strength);
        }
        for (let s = 0; s < SUBSTEPS; s++) step();
        draw();
      }
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    const onPointerMove = (e: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      ptr.gx = (e.clientX - rect.left) / cellW;
      ptr.gy = (e.clientY - rect.top) / cellH;
      ptr.has = true;
    };
    const onPointerLeave = () => {
      ptr.has = false;
    };

    const onVis = () => {
      if (!document.hidden && !reduced && ready) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) draw();
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    document.fonts.ready.then(() => {
      if (disposed) return;
      readTokens();
      resize();
      ready = true;
      if (reduced) {
        draw();
      } else {
        raf = requestAnimationFrame(loop);
      }
    });

    window.addEventListener("resize", onResize);
    if (!reduced) {
      canvas.addEventListener("pointermove", onPointerMove);
      canvas.addEventListener("pointerleave", onPointerLeave);
    }
    document.addEventListener("visibilitychange", onVis);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      mo.disconnect();
      window.removeEventListener("resize", onResize);
      canvas.removeEventListener("pointermove", onPointerMove);
      canvas.removeEventListener("pointerleave", onPointerLeave);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [cellSize]);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden
      className={`block h-full w-full font-mono text-foreground ${className}`}
    />
  );
}

"use client";

import { useEffect, useRef, type ReactNode } from "react";

// ---------------------------------------------------------------------------
// SchlierenRig — a real schlieren bench rendered in ASCII ink.
//
// A schlieren photograph does not show air. It shows the DERIVATIVE of air:
// light passing through a refractive-index gradient is deflected, and a knife
// edge parked at the focal point clips exactly the deflected half. Uniform
// bulk air deflects nothing, lands dead-centre on the knife, and comes out a
// flat mid-grey — which is why a real schlieren frame is almost entirely
// empty, with only the steep density boundaries surviving as thin bright and
// dark bands.
//
// So: evaluate an analytic density field rho(x,y,t) (a buoyant plume of
// discrete puffs, plus a Kelvin-Helmholtz shear interface across the lower
// third), take its directional gradient on the glyph grid, and map that
// gradient through a HARD cut — ink only where the transmitted fraction
// departs far enough from the knife's mid-point. Everything inside that dead
// band draws nothing at all, which is ~90% of the frame.
//
// The pointer IS the knife, and it rotates. A knife edge only reveals
// gradients perpendicular to it, so turning it re-selects which family of
// boundaries is visible: sweep right and the plume's vertical flanks give way
// to its horizontal puff caps and the shear interface. That is the single
// most characteristic thing an operator does on a real bench.
// ---------------------------------------------------------------------------

const RAMP = " .:-=+*#%@";
const ALPHA_BUCKETS = 6;

const PLUME_WEIGHT = 0.55; // rho contribution of the buoyant column
const PLUME_X = 0.42; // fraction of W — the column's mean axis
const PLUME_SIGMA = 0.024; // fraction of W — gaussian half-width at the base
const PLUME_SPREAD = 1.2; // the column widens by this factor as it rises
const PUFF_K = 0.038; // rad/px — vertical wavenumber of the shed puff train
const PUFF_FLOOR = 0.5; // puffs MODULATE a standing column, never gate it off:
// at 0 the flanks break into detached dashes and the
// column stops reading as one continuous filament pair

const SHEAR_WEIGHT = 0.13; // rho contribution of the shear interface
const SHEAR_Y = 0.68; // fraction of H — interface sits across the lower third
const SHEAR_THICK = 0.02; // fraction of H — tanh transition thickness
const SHEAR_AMP = 0.035; // fraction of H — KH billow displacement amplitude

const KNIFE_SLOPE = 118; // px — gradient -> transmitted-fraction sensitivity
const DEAD_BAND = 0.24; // |s - 0.5| below this transmits nothing: blank cell
const LUM_SPAN = 0.5 - DEAD_BAND;
const REF_DIAG = Math.hypot(1440, 900); // gain was tuned at this field size
const LUM_POW = 0.85;
const DARK_SCALE = 0.45; // dark flank = same ink, less alpha. never a 2nd hue

const KNIFE_MAX = 0.55; // rad — full knife rotation either side of vertical
const KNIFE_TAU = 0.5; // s — knife rotation time constant
const DT_MAX = 0.05;
const STATIC_T = 1.8; // reduced-motion frozen frame

/**
 * Analytic density field. No advection sim — every cell is evaluated
 * independently and exactly, which is what keeps the gradient clean enough
 * for a hard knife cut to produce thin bands instead of noise.
 */
function density(
  x: number,
  y: number,
  t: number,
  w: number,
  h: number
): number {
  // -- buoyant plume: a meandering column of discrete puffs -----------------
  const axis = PLUME_X * w + 0.06 * w * Math.sin(y * 0.011 - t * 0.9);
  // canvas y grows downward, so (1 - y/h) grows upward: the column widens as
  // it rises, the way a real thermal entrains surrounding air
  const sigma = PLUME_SIGMA * w * (1 + PLUME_SPREAD * (1 - y / h));
  const dx = x - axis;
  const core = Math.exp(-(dx * dx) / (2 * sigma * sigma));
  // rectified puff train — buoyancy sheds discrete parcels, so the column
  // pulses in brightness up its length rather than reading as a smooth smear
  const raw = Math.sin(y * PUFF_K - t * 2.2);
  const rect = raw > 0 ? Math.pow(raw, 1.5) : 0;
  const puff = PUFF_FLOOR + (1 - PUFF_FLOOR) * rect;

  // -- Kelvin-Helmholtz shear interface across the lower third --------------
  // The billow DISPLACES the interface rather than scaling the tanh: scaling
  // it would ripple the far field too (tanh saturates to ±1 everywhere away
  // from the interface), wallpapering the whole frame with a gradient the
  // knife then transmits — the exact "uniform wash" failure this technique
  // exists to avoid. Displacing it leaves the bulk air perfectly flat, and
  // gives the interface the horizontal gradient component that is the only
  // reason a vertical knife can see a horizontal layer at all.
  const billow =
    Math.sin(x * 0.03 - t * 1.4) * (1 + 0.35 * Math.sin(x * 0.017 + t * 0.6));
  const yInterface = SHEAR_Y * h + SHEAR_AMP * h * billow;
  const shear = Math.tanh((y - yInterface) / (SHEAR_THICK * h));

  return 1.0 - PLUME_WEIGHT * core * puff - SHEAR_WEIGHT * shear;
}

export interface SchlierenRigProps {
  /** grid cell size in px */
  cellSize?: number;
  /** knife sensitivity — higher cuts more of the field into visible bands */
  gain?: number;
  /** optional hero content, rendered over the field */
  children?: ReactNode;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function SchlierenRig({
  cellSize = 12,
  gain = 1.0,
  children,
  className = "",
}: SchlierenRigProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    let fg = "currentColor";
    let cellW = cellSize;
    let cellH = cellSize;
    let cols = 0;
    let rows = 0;
    let fieldW = 0;
    let fieldH = 0;
    let sized = false;
    let ready = false;
    let disposed = false;

    // rho is sampled once per node on a 1-cell-padded grid so the central
    // differences below are four array reads, not four field evaluations
    let rhoBuf = new Float32Array(0);
    let charBuf = new Uint8Array(0);
    const brightLists: number[][] = Array.from(
      { length: ALPHA_BUCKETS },
      () => []
    );
    const darkLists: number[][] = Array.from(
      { length: ALPHA_BUCKETS },
      () => []
    );

    const readTokens = () => {
      fg = getComputedStyle(canvas).color;
    };

    const measureCell = (fontFamily: string) => {
      const off = document.createElement("canvas");
      const octx = off.getContext("2d");
      if (!octx) return;
      octx.font = `${cellSize}px ${fontFamily}`;
      cellW = Math.max(4, octx.measureText("MMMMMMMMMM").width / 10);
      cellH = cellSize;
    };

    const resize = () => {
      const { width, height } = canvas.getBoundingClientRect();
      if (width < 2 || height < 2) {
        sized = false;
        return;
      }
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const fontFamily = getComputedStyle(canvas).fontFamily;
      measureCell(fontFamily);
      ctx.font = `${cellSize}px ${fontFamily}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      fieldW = width;
      fieldH = height;
      cols = Math.max(4, Math.ceil(width / cellW));
      rows = Math.max(4, Math.ceil(height / cellH));
      rhoBuf = new Float32Array((cols + 2) * (rows + 2));
      charBuf = new Uint8Array(cols * rows);
      sized = true;
    };

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
        if (reduced) draw(STATIC_T, 0);
      }, 150);
    };

    const draw = (t: number, knife: number) => {
      if (!sized) return;
      ctx.clearRect(0, 0, cols * cellW, rows * cellH);

      for (let b = 0; b < ALPHA_BUCKETS; b++) {
        brightLists[b]!.length = 0;
        darkLists[b]!.length = 0;
      }

      // -- pass 0: sample rho on the padded node grid ------------------------
      const stride = cols + 2;
      for (let gy = -1; gy <= rows; gy++) {
        const py = (gy + 0.5) * cellH;
        const rowOff = (gy + 1) * stride;
        for (let gx = -1; gx <= cols; gx++) {
          rhoBuf[rowOff + gx + 1] = density(
            (gx + 0.5) * cellW,
            py,
            t,
            fieldW,
            fieldH
          );
        }
      }

      // -- pass 1: knife cut -> ramp index + bucket --------------------------
      const ca = Math.cos(knife);
      const sa = Math.sin(knife);
      // Central differences are divided by the cell's own px size so the
      // result is a true per-px derivative: the glyph cell is ~7x12, and
      // differencing in cell units alone would make the knife 1.7x more
      // sensitive to vertical gradients than horizontal ones — a bias that
      // would show up as the field lighting unevenly as the knife rotates.
      const kx = (KNIFE_SLOPE * gain) / (2 * cellW);
      const ky = (KNIFE_SLOPE * gain) / (2 * cellH);
      // A bench's gain is set per shot: the plume's own width scales with the
      // field, so without this a narrow viewport's much steeper gradients
      // would clip every surviving cell to solid '@'.
      const fit = Math.hypot(fieldW, fieldH) / REF_DIAG;
      const gx0 = kx * fit;
      const gy0 = ky * fit;
      let i = 0;
      for (let gy = 0; gy < rows; gy++) {
        const c = (gy + 1) * stride + 1;
        for (let gx = 0; gx < cols; gx++, i++) {
          const n = c + gx;
          // central difference on the glyph grid — the deflection angle a ray
          // picks up crossing this cell
          const dRx = (rhoBuf[n + 1]! - rhoBuf[n - 1]!) * gx0;
          const dRy = (rhoBuf[n + stride]! - rhoBuf[n - stride]!) * gy0;
          // ...projected onto the knife's own axis. A knife only ever reveals
          // gradients perpendicular to its edge.
          const d = ca * dRx + sa * dRy;
          // fraction of the ray's cone the knife lets past. 0.5 = undeflected.
          let s = 0.5 + d;
          s = s < 0 ? 0 : s > 1 ? 1 : s;
          const dev = s - 0.5;
          const mag = dev < 0 ? -dev : dev;
          if (mag <= DEAD_BAND) {
            charBuf[i] = 0; // inside the dead band: the knife shows nothing
            continue;
          }
          const lum = Math.pow((mag - DEAD_BAND) / LUM_SPAN, LUM_POW);
          const ci = Math.floor(lum * (RAMP.length - 1));
          charBuf[i] = ci;
          if (ci === 0) continue;
          const bucket = Math.min(
            ALPHA_BUCKETS - 1,
            Math.floor(lum * ALPHA_BUCKETS)
          );
          (dev > 0 ? brightLists : darkLists)[bucket]!.push(i);
        }
      }

      // -- pass 2: one globalAlpha write per bucket --------------------------
      ctx.fillStyle = fg;
      for (let b = 0; b < ALPHA_BUCKETS; b++) {
        const alpha = 0.12 + (b / (ALPHA_BUCKETS - 1)) * 0.88;
        for (let pass = 0; pass < 2; pass++) {
          const list = pass === 0 ? brightLists[b]! : darkLists[b]!;
          if (list.length === 0) continue;
          ctx.globalAlpha = pass === 0 ? alpha : alpha * DARK_SCALE;
          for (let k = 0; k < list.length; k++) {
            const idx = list[k]!;
            const gx = idx % cols;
            const gy = (idx - gx) / cols;
            ctx.fillText(
              RAMP[charBuf[idx]!]!,
              gx * cellW + cellW / 2,
              gy * cellH + cellH / 2
            );
          }
        }
      }
      ctx.globalAlpha = 1;
    };

    // -- hot-path state -------------------------------------------------------
    let raf = 0;
    let last = 0;
    let t = 0;
    let knife = 0;
    let knifeTarget = 0;

    const loop = (now: number) => {
      const dt = last ? Math.min(DT_MAX, (now - last) / 1000) : 1 / 60;
      last = now;
      t += dt;
      knife += (knifeTarget - knife) * Math.min(1, dt / KNIFE_TAU);
      draw(t, knife);
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    const onPointerMove = (e: PointerEvent) => {
      const rect = root.getBoundingClientRect();
      if (rect.width < 2) return;
      const nx = (e.clientX - rect.left) / rect.width;
      knifeTarget = (Math.min(1, Math.max(0, nx)) * 2 - 1) * KNIFE_MAX;
    };
    const onPointerLeave = () => {
      knifeTarget = 0;
    };

    const onVis = () => {
      // a frame requested before the tab hid is still pending (rAF callbacks
      // don't run while hidden); scheduling another here without cancelling it
      // leaves two loops driving t, at double speed
      cancelAnimationFrame(raf);
      if (!document.hidden && !reduced && ready) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) draw(STATIC_T, 0);
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    document.fonts.ready.then(() => {
      if (disposed) return;
      readTokens();
      resize();
      ready = true;
      if (reduced) {
        draw(STATIC_T, 0);
      } else {
        raf = requestAnimationFrame(loop);
      }
    });

    window.addEventListener("resize", onResize);
    if (!reduced) {
      root.addEventListener("pointermove", onPointerMove);
      root.addEventListener("pointerleave", onPointerLeave);
    }
    document.addEventListener("visibilitychange", onVis);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      mo.disconnect();
      window.removeEventListener("resize", onResize);
      root.removeEventListener("pointermove", onPointerMove);
      root.removeEventListener("pointerleave", onPointerLeave);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [cellSize, gain]);

  // `h-full` matters as much as the min-height: a min-height is only a floor,
  // and in a stretched grid item taller than it the canvas would stop partway
  // down and leave a band of dead background beneath the field.
  return (
    <div
      ref={rootRef}
      className={`relative isolate h-full w-full overflow-hidden bg-background font-mono ${
        /\bmin-h-/.test(className) ? "" : "min-h-screen"
      } ${className}`}
    >
      <canvas
        ref={canvasRef}
        aria-hidden
        className="absolute inset-0 block h-full w-full text-foreground"
      />
      {children ? (
        <div className="relative z-10 flex h-full w-full flex-col items-start justify-end gap-4 p-8 sm:p-14">
          {children}
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import type { ReactNode } from "react";

// ---------------------------------------------------------------------------
// ShockTrain — a full-bleed ASCII hero of a supersonic exhaust plume. This is
// gas dynamics, not a pattern: an underexpanded jet leaving a nozzle turns
// through a fan, over-expands, and is turned back by an OBLIQUE SHOCK that
// leaves the nozzle lip at the Mach angle mu = asin(1/M). That shock reflects
// specularly off the free jet boundary, crosses its mirror image from the
// opposite lip, and the whole thing repeats — a shock CELL — every
// L = 1.30 * D * sqrt(M^2 - 1) (Prandtl-Pack). Two travelling families is all
// it takes: p1 = a + b and p2 = a - b, where a is downstream distance in cells
// and b is transverse distance in cells; a cell is ON a shock when either
// phase lands near an integer. Where BOTH land near an integer the two
// families cross, and that crossing is the diamond node — it is inked 1.9x
// harder, which is the whole reason the frame reads as a string of bright X's
// on the centreline rather than a diagonal hatch. The design Mach number is
// LOW (1.5) on purpose: the Mach angle is then 42 degrees, so the two families
// cross at close to a right angle and the arms read as chevrons instead of
// merging into horizontal streaks, and the shorter cell length lets D grow to
// 0.28*H so the train is a tall band rather than a thin line. Everything else
// is blank: the shocks are hard-masked to the plume's own waisted envelope,
// and the plume's interior between shocks is empty. The plume rides HIGH in
// the frame — axis at 0.26*H — because the hero copy is anchored bottom-left
// and the two must not overlap. The pointer is the THROTTLE — its
// x position sets the nozzle pressure ratio, M is re-solved from it
// isentropically, and since L scales with sqrt(M^2 - 1) the diamonds visibly
// stretch apart to the right and compress to the left. Pointer y vectors the
// jet axis. Both ease back to the design plume when the pointer leaves.
// ---------------------------------------------------------------------------

const RAMP = " .:-=+*#%@";
const ALPHA_BUCKETS = 6;
const SHOCK_TOL = 0.035; // phase half-width of a shock, in cell lengths
const SHOCK_POW = 1.6; // line profile sharpness
const NODE_GAIN = 1.9; // crossing multiplier — makes the X's the picture
const INK_DECAY = 6.0; // shock strength e-folding, in cell lengths
const ENV_DECAY = 4.5; // plume envelope e-folding, in cell lengths
const PLUME_END = 6.0; // stop evaluating past this many cells
const THROTTLE_TAU = 0.6; // s — pointer easing time constant
const PULSE_A = 0.018; // resting breath in cell spacing
const PULSE_B = 0.008;
const CELLS_ACROSS = 3.2; // design: shock cells that fit the frame at rest
const AXIS_FRAC = 0.26; // jet axis height — copy owns the bottom of the frame
const D_MAX_FRAC = 0.28; // hard cap on nozzle diameter, as a fraction of H
const VECTOR_FRAC = 0.04; // thrust-vector travel, as a fraction of H
const NPR_LO = 0.66; // throttle window, as a multiple of the design NPR
const NPR_HI = 2.13;
const DT_MAX = 0.05;

/** isentropic (gamma 1.4) Mach number from a nozzle pressure ratio */
function machFromNpr(npr: number): number {
  const m2 = 5 * (Math.pow(Math.max(1.0001, npr), 0.2857) - 1);
  return Math.max(1.05, Math.sqrt(Math.max(0.1025, m2)));
}

/** nozzle pressure ratio that produces this design Mach number */
function nprFromMach(m: number): number {
  return Math.pow(1 + 0.2 * m * m, 3.5);
}

/** distance from p to the nearest integer, in [0, 0.5] */
function phaseDist(p: number): number {
  const f = p - Math.floor(p);
  return f < 0.5 ? f : 1 - f;
}

export interface ShockTrainProps {
  /** grid cell size in px */
  cellSize?: number;
  /** design Mach number of the plume at rest */
  mach?: number;
  /** headline / CTA rendered over the plume */
  children?: ReactNode;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function ShockTrain({
  cellSize = 12,
  mach = 1.5,
  children,
  className = "",
}: ShockTrainProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    const machDesign = Math.min(4.5, Math.max(1.2, mach));
    const nprDesign = nprFromMach(machDesign);
    const nprMin = nprDesign * NPR_LO;
    const nprMax = nprDesign * NPR_HI;

    let fg = "currentColor";
    let cellW = cellSize;
    let cellH = cellSize;
    let cols = 0;
    let rows = 0;
    let dpr = 1;
    let sized = false;
    let ready = false;
    let disposed = false;

    let nozzleX = 0; // x0 — nozzle exit plane
    let axisY = 0; // yc at rest — the undeflected jet axis
    let nozzleD = 0; // D — nozzle exit diameter
    let vectorMax = 0; // px of thrust-vector travel

    let charBuf = new Uint8Array(0);
    const bucketLists: number[][] = Array.from(
      { length: ALPHA_BUCKETS },
      () => []
    );

    const readTokens = () => {
      fg = getComputedStyle(canvas).color;
    };

    const measureCell = (fontFamily: string) => {
      const off = document.createElement("canvas");
      const octx = off.getContext("2d");
      if (!octx) return;
      octx.font = `${cellSize}px ${fontFamily}`;
      cellW = Math.max(4, octx.measureText("MMMMMMMMMM").width / 10);
      cellH = cellSize;
    };

    const resize = () => {
      const { width, height } = canvas.getBoundingClientRect();
      if (width < 2 || height < 2) {
        sized = false;
        return;
      }
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const fontFamily = getComputedStyle(canvas).fontFamily;
      measureCell(fontFamily);
      ctx.font = `${cellSize}px ${fontFamily}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";

      cols = Math.max(8, Math.ceil(width / cellW));
      rows = Math.max(8, Math.ceil(height / cellH));

      const w = cols * cellW;
      const h = rows * cellH;
      nozzleX = w * 0.1;
      // the jet axis is snapped to a ROW CENTRE: the on-axis diamond node sits
      // exactly at y = yc, and if that lands between two rows the brightest
      // cell in the whole picture is never sampled and the train degrades into
      // a chevron hatch. Snapping is what keeps the X's on the centreline.
      axisY =
        Math.round((h * AXIS_FRAC - cellH / 2) / cellH) * cellH + cellH / 2;
      vectorMax = h * VECTOR_FRAC;
      // D is the one free geometric parameter and it sets how TALL the train
      // is: the shock band is about 1.5*D high, so D is pushed as large as the
      // frame allows — up to 0.28*H — and the cell count is what gives way.
      // Only ~3.5 cells lay across the frame (three crossings and the lip),
      // which is the point: three legible diamonds beat six horizontal dashes.
      // Pinned to machDesign, never the live Mach — D is the hardware, and it
      // is precisely because D is fixed that a throttle change moves L.
      const kDesign = 1.3 * Math.sqrt(machDesign * machDesign - 1);
      nozzleD = Math.min(
        h * D_MAX_FRAC,
        ((w - nozzleX) * 0.98) / (CELLS_ACROSS * kDesign)
      );
      nozzleD = Math.max(nozzleD, cellH * 8);

      charBuf = new Uint8Array(cols * rows);
      sized = true;
    };

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
        if (reduced) draw(0, machDesign, 0);
      }, 150);
    };

    const draw = (t: number, machEff: number, vectorY: number) => {
      if (!sized) return;
      const w = cols * cellW;
      const h = rows * cellH;
      ctx.clearRect(0, 0, w, h);
      for (let b = 0; b < ALPHA_BUCKETS; b++) bucketLists[b]!.length = 0;

      const M = Math.max(1.05, machEff);
      // Prandtl-Pack shock-cell length, and the Mach angle the lip shock
      // leaves at. Both move together when the throttle moves.
      const L = 1.3 * nozzleD * Math.sqrt(M * M - 1);
      const tanMu = Math.tan(Math.asin(1 / M));
      const invBand = 1 / (L * tanMu);
      // thrust vectoring moves the axis in whole rows, so the node stays on a
      // row centre wherever it is aimed
      const yc = axisY + Math.round(vectorY / cellH) * cellH;
      const rMax = 0.5 * nozzleD * 1.55;
      const envHalf = cellH * 0.55;
      const tau = Math.PI * 2;

      // A shock is 0.035 cell-lengths of phase wide, which on this grid is
      // thinner than one row — sampled naively the line falls between cells and
      // breaks into dashes. Dilate the hit test to at least one cell while
      // keeping the physical 0.035 profile: everything inside the dilation is
      // full-strength line, and the original profile fades over the last
      // 0.035. Conservative rasterization, not a fattened shock.
      const gradMag = Math.hypot(1 / L, invBand);
      const tol = Math.max(SHOCK_TOL, 0.62 * cellH * gradMag);
      const dilate = tol - SHOCK_TOL;
      const profile = (d: number) => {
        const de = d <= dilate ? 0 : d - dilate;
        return Math.pow(Math.max(0, 1 - de / SHOCK_TOL), SHOCK_POW);
      };

      for (let gy = 0; gy < rows; gy++) {
        const py = gy * cellH + cellH / 2;
        const dy = py - yc;
        const ady = dy < 0 ? -dy : dy;
        if (ady > rMax + envHalf) continue; // outside the widest bulge: blank
        const rowBase = gy * cols;

        for (let gx = 0; gx < cols; gx++) {
          const px = gx * cellW + cellW / 2;
          const a = (px - nozzleX) / L; // downstream distance, in shock cells
          if (a < 0 || a > PLUME_END) continue;

          // free-boundary envelope: the periodic bulge/waist of an
          // underexpanded jet, dying out downstream
          const r =
            0.5 *
            nozzleD *
            (1 + 0.55 * Math.sin(tau * a + Math.PI / 2)) *
            Math.exp(-a / ENV_DECAY);

          if (ady > r) {
            // faint trace of the jet boundary itself — the waisted envelope
            if (ady - r < envHalf) {
              const idx = rowBase + gx;
              charBuf[idx] = 1;
              bucketLists[0]!.push(idx);
            }
            continue;
          }

          // the two travelling shock families, as phase coordinates
          const b = dy * invBand;
          const d1 = phaseDist(a + b);
          const d2 = phaseDist(a - b);
          const on1 = d1 < tol;
          const on2 = d2 < tol;
          if (!on1 && !on2) continue; // plume interior between shocks: blank

          let s = 0;
          if (on1) s = profile(d1);
          if (on2) {
            const s2 = profile(d2);
            if (s2 > s) s = s2;
          }
          // both families here — this is the diamond node
          if (on1 && on2) s = Math.min(1, s * NODE_GAIN);
          s *= Math.exp(-a / INK_DECAY);
          if (s <= 0.04) continue;

          const ci = Math.max(1, Math.floor(s * (RAMP.length - 1)));
          const bucket = Math.min(
            ALPHA_BUCKETS - 1,
            Math.floor(s * ALPHA_BUCKETS)
          );
          const idx = rowBase + gx;
          charBuf[idx] = ci;
          bucketLists[bucket]!.push(idx);
        }
      }

      ctx.fillStyle = fg;
      for (let b = 0; b < ALPHA_BUCKETS; b++) {
        const list = bucketLists[b]!;
        if (list.length === 0) continue;
        ctx.globalAlpha = 0.1 + (b / (ALPHA_BUCKETS - 1)) * 0.9;
        for (let k = 0; k < list.length; k++) {
          const idx = list[k]!;
          const gx = idx % cols;
          const gy = (idx - gx) / cols;
          ctx.fillText(
            RAMP[charBuf[idx]!]!,
            gx * cellW + cellW / 2,
            gy * cellH + cellH / 2
          );
        }
      }
      ctx.globalAlpha = 1;
    };

    // -- hot-path state -------------------------------------------------------
    let raf = 0;
    let last = 0;
    let t = 0;
    let npr = nprDesign; // eased nozzle pressure ratio — the throttle
    let nprTarget = nprDesign;
    let vector = 0; // eased thrust-vector offset in px
    let vectorTarget = 0;

    const loop = (now: number) => {
      const dt = last ? Math.min(DT_MAX, (now - last) / 1000) : 1 / 60;
      last = now;
      t += dt;

      const k = Math.min(1, dt / THROTTLE_TAU);
      npr += (nprTarget - npr) * k;
      vector += (vectorTarget - vector) * k;

      // resting breath: a small jitter in cell spacing, never a scroll
      const machEff =
        machFromNpr(npr) *
        (1 + PULSE_A * Math.sin(t * 0.85) + PULSE_B * Math.sin(t * 2.3));

      draw(t, machEff, vector);
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    const onPointerMove = (e: PointerEvent) => {
      const rect = root.getBoundingClientRect();
      if (rect.width < 2 || rect.height < 2) return;
      const fx = Math.min(1, Math.max(0, (e.clientX - rect.left) / rect.width));
      nprTarget = nprMin + fx * (nprMax - nprMin);
      const fy = (e.clientY - rect.top - rect.height / 2) / (rect.height * 0.25);
      vectorTarget = Math.min(1, Math.max(-1, fy)) * vectorMax;
    };
    const onPointerLeave = () => {
      nprTarget = nprDesign;
      vectorTarget = 0;
    };

    const onVis = () => {
      if (!document.hidden && !reduced && ready) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };
    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) draw(0, machDesign, 0);
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    document.fonts.ready.then(() => {
      if (disposed) return;
      readTokens();
      resize();
      ready = true;
      if (reduced) {
        draw(0, machDesign, 0);
      } else {
        raf = requestAnimationFrame(loop);
      }
    });

    window.addEventListener("resize", onResize);
    if (!reduced) {
      root.addEventListener("pointermove", onPointerMove);
      root.addEventListener("pointerleave", onPointerLeave);
    }
    document.addEventListener("visibilitychange", onVis);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      mo.disconnect();
      window.removeEventListener("resize", onResize);
      root.removeEventListener("pointermove", onPointerMove);
      root.removeEventListener("pointerleave", onPointerLeave);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [cellSize, mach]);

  return (
    <div
      ref={rootRef}
      className={`relative isolate h-full w-full overflow-hidden bg-background font-mono ${
        /\bmin-h-/.test(className) ? "" : "min-h-screen"
      } ${className}`}
    >
      <canvas
        ref={canvasRef}
        aria-hidden
        className="absolute inset-0 block h-full w-full text-foreground"
      />
      {children ? (
        <div className="absolute inset-0 z-10 flex flex-col items-start justify-end gap-4 p-8 sm:p-14">
          {children}
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import type { ReactNode } from "react";

// ---------------------------------------------------------------------------
// ScarpHorizon — a full-bleed ASCII landscape hero. Five ridgelines recede
// toward a fixed horizon row, each a deterministic 1D value-noise curve (two
// octaves, fixed hash seed per layer — the terrain never reshuffles on
// remount) sampled at an ever-larger spatial frequency and amplitude going
// from farthest to nearest, so distant ridges read as smooth low rolling haze
// and the nearest ridge reads as jagged and dense. Every column is resolved
// far-to-near into one Uint8Array "which layer wins this cell" buffer before
// a single render pass — that overwrite-in-draw-order is what gives clean
// occlusion (a nearer ridge silhouette blotting out a farther one) instead of
// two glyphs stacked translucently in the same cell. Layer opacity and ramp
// character both step up with proximity (haze -> ink). A sparse fixed star
// field fills the sky above the horizon, each star's alpha breathing on a
// slow sine so the sky isn't a dead flat void. The pointer drives parallax —
// each layer's horizontal (and slightly vertical) sample offset is scaled by
// its own proximity factor, eased, plus a slow idle drift so the scene keeps
// a pulse even at rest — so panning across the field reads like a window
// gliding past terrain, nearer ridges sliding faster than the horizon.
// ---------------------------------------------------------------------------

const RAMP = " .:-=+*#%@"; // 10-step density ramp, index 0 = blank

interface Layer {
  freq: number; // spatial frequency in noise-space, per column
  baseFrac: number; // fraction of terrain band the ridge's average sits at
  ampFrac: number; // fraction of terrain band the ridge swings by
  parallax: number; // 0..1, how much this layer answers to the pointer
  drift: number; // idle ambient pan, in GRID COLUMNS/s (not noise-space)
  alpha: number; // resting opacity, haze (far) -> ink (near)
  charIdx: number; // index into RAMP
  seedA: number;
  seedB: number;
}

// far -> near: frequency, base depth and amplitude all step up together —
// the nearest ridge is the tallest, most jagged, and reaches lowest in frame.
// Amplitude is large relative to the gap between layers on purpose: a ridge
// silhouette only reads as terrain if it has real peaks and valleys, not a
// nearly flat line with a haze tint.
//
// `drift` used to be one global constant (IDLE_DRIFT) multiplied through
// `parallax`, same as the pointer offset. That reads as "barely moving" no
// matter how large the constant gets: the ridge only repaints when the
// sampled noise crosses into a different grid COLUMN, and with parallax
// spanning 0.05 -> 0.95 the resulting pace was ~1 column every 125s on the
// farthest layer and ~1 column every 6.6s even on the nearest — both well
// below what a glance registers, confirmed at 0% of cells changing per
// second measured over a 6s sample at rest. `drift` is now authored directly
// in columns/second, decoupled from `parallax` (which still governs only the
// pointer response): the near layer crosses a column every ~0.3s, the far
// layer keeps drifting slowly rather than being effectively frozen.
const LAYERS: Layer[] = [
  { freq: 0.012, baseFrac: 0.0, ampFrac: 0.11, parallax: 0.05, drift: 0.45, alpha: 0.24, charIdx: 1, seedA: 11, seedB: 511 },
  { freq: 0.018, baseFrac: 0.14, ampFrac: 0.16, parallax: 0.18, drift: 0.9, alpha: 0.44, charIdx: 3, seedA: 23, seedB: 727 },
  { freq: 0.026, baseFrac: 0.32, ampFrac: 0.2, parallax: 0.38, drift: 1.7, alpha: 0.64, charIdx: 5, seedA: 47, seedB: 941 },
  { freq: 0.038, baseFrac: 0.52, ampFrac: 0.24, parallax: 0.62, drift: 2.8, alpha: 0.84, charIdx: 7, seedA: 71, seedB: 1153 },
  { freq: 0.055, baseFrac: 0.74, ampFrac: 0.27, parallax: 0.95, drift: 4.5, alpha: 1, charIdx: 9, seedA: 97, seedB: 1381 },
];

const STAR_CHARS = [1, 2, 3]; // RAMP indices used for stars
const CURSOR_EASE = 0.08;
const MAX_PARALLAX_COLS = 46; // world-unit shift at full pointer travel
const MAX_PARALLAX_ROWS = 5;
const DT_MAX = 0.05;

// deterministic hash -> [0,1); fixed seed means the terrain is the same
// shape every mount, never reshuffled
function hash1(n: number, seed: number): number {
  const x = Math.sin(n * 127.1 + seed * 311.7) * 43758.5453;
  return x - Math.floor(x);
}

function noise1D(x: number, seed: number): number {
  const i0 = Math.floor(x);
  const i1 = i0 + 1;
  const t = x - i0;
  const s = t * t * (3 - 2 * t);
  const a = hash1(i0, seed);
  const b = hash1(i1, seed);
  return a + (b - a) * s;
}

// two octaves, weighted 0.7/0.3, mapped to -1..1
function ridgeNoise(x: number, seedA: number, seedB: number): number {
  const n = noise1D(x, seedA) * 0.7 + noise1D(x * 2.7 + 11.3, seedB) * 0.3;
  return n * 2 - 1;
}

function mulberry32(a: number) {
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export interface ScarpHorizonProps {
  /** grid cell size in px */
  cellSize?: number;
  /** headline / CTA rendered over the field */
  children?: ReactNode;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function ScarpHorizon({
  cellSize = 13,
  children,
  className = "",
}: ScarpHorizonProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    let fg = "currentColor";
    let muted = "currentColor";
    let cellW = cellSize;
    let cellH = cellSize;
    let cols = 0;
    let rows = 0;
    let dpr = 1;
    let sized = false;
    let ready = false;
    let disposed = false;

    let horizonRow = 0;
    let terrainRows = 0;

    let grpBuf = new Int8Array(0); // -1 = sky/blank, 0..LAYERS.length-1 = layer
    let charBuf = new Uint8Array(0);

    let starCol = new Float32Array(0);
    let starRow = new Float32Array(0);
    let starChar = new Uint8Array(0);
    let starPhase = new Float32Array(0);
    let starAlpha = new Float32Array(0);
    let starCount = 0;

    const readTokens = () => {
      fg = getComputedStyle(canvas).color;
      muted =
        getComputedStyle(document.documentElement)
          .getPropertyValue("--ns-muted")
          .trim() || fg;
    };

    const measureCell = (fontFamily: string) => {
      const off = document.createElement("canvas");
      const octx = off.getContext("2d");
      if (!octx) return;
      octx.font = `${cellSize}px ${fontFamily}`;
      cellW = Math.max(4, octx.measureText("MMMMMMMMMM").width / 10);
      cellH = cellSize;
    };

    const buildStars = () => {
      const skyRows = horizonRow;
      const rand = mulberry32(0xa57e0);
      starCount = Math.min(240, Math.max(0, Math.floor(cols * skyRows * 0.035)));
      starCol = new Float32Array(starCount);
      starRow = new Float32Array(starCount);
      starChar = new Uint8Array(starCount);
      starPhase = new Float32Array(starCount);
      starAlpha = new Float32Array(starCount);
      for (let i = 0; i < starCount; i++) {
        starCol[i] = Math.floor(rand() * cols);
        starRow[i] = Math.floor(rand() * Math.max(1, skyRows - 1));
        starChar[i] = STAR_CHARS[Math.floor(rand() * STAR_CHARS.length)];
        starPhase[i] = rand() * Math.PI * 2;
        starAlpha[i] = 0.25 + rand() * 0.4;
      }
    };

    const resize = () => {
      const { width, height } = canvas.getBoundingClientRect();
      if (width < 2 || height < 2) {
        sized = false;
        return;
      }
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const fontFamily = getComputedStyle(canvas).fontFamily;
      measureCell(fontFamily);
      ctx.font = `${cellSize}px ${fontFamily}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";

      // `ceil`, not `floor`: the grid is `rows * cellH` tall, so flooring left
      // an unpainted strip up to one cell high along the bottom edge — read as
      // a stray band of padding under the terrain. Overdrawing by a partial
      // row instead costs nothing, because the root clips with
      // `overflow-hidden`. Same for columns and the right edge.
      cols = Math.max(8, Math.ceil(width / cellW));
      rows = Math.max(10, Math.ceil(height / cellH));
      horizonRow = Math.max(2, Math.floor(rows * 0.34));
      terrainRows = Math.max(1, rows - horizonRow);

      grpBuf = new Int8Array(cols * rows);
      charBuf = new Uint8Array(cols * rows);
      buildStars();
      sized = true;
    };

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
        if (reduced) draw(0, 0, 0);
      }, 150);
    };

    const draw = (t: number, offX: number, offY: number) => {
      if (!sized) return;
      const w = cols * cellW;
      const h = rows * cellH;
      ctx.clearRect(0, 0, w, h);
      grpBuf.fill(-1);
      charBuf.fill(0);

      // -- terrain: far -> near, each layer overwrites the cells it covers --
      for (let li = 0; li < LAYERS.length; li++) {
        const layer = LAYERS[li];
        // pointer parallax and idle drift are two different units on
        // purpose: pointer offset is already in grid columns (scaled by
        // proximity), idle drift is authored directly in columns/s per
        // layer — see the comment on `LAYERS` for why they used to share
        // one constant and why that read as motionless.
        const worldOffX = offX * layer.parallax + t * layer.drift;
        const worldOffY = offY * layer.parallax * 0.6;
        for (let c = 0; c < cols; c++) {
          const nx = (c + worldOffX) * layer.freq;
          const n = ridgeNoise(nx, layer.seedA, layer.seedB);
          let ridge =
            horizonRow +
            layer.baseFrac * terrainRows +
            n * layer.ampFrac * terrainRows -
            worldOffY;
          ridge = Math.max(horizonRow, Math.min(rows - 1, Math.round(ridge)));
          // flat body at the layer's own density — no internal gradient — so
          // the boundary against the (lighter) layer behind it stays a hard,
          // legible edge instead of blurring into a continuous field
          for (let r = ridge; r < rows; r++) {
            const idx = r * cols + c;
            grpBuf[idx] = li;
            charBuf[idx] = layer.charIdx;
          }
          // one-row crest highlight, denser than the layer's own body, so the
          // silhouette line itself reads as a distinct rim against the haze
          const crestIdx = ridge * cols + c;
          charBuf[crestIdx] = Math.min(RAMP.length - 1, layer.charIdx + 1);
        }
      }

      // -- sky: sparse breathing stars, drawn directly (no grid buffer) -----
      ctx.fillStyle = muted;
      for (let i = 0; i < starCount; i++) {
        const twinkle = 0.5 + 0.5 * Math.sin(t * 1.1 + starPhase[i]);
        ctx.globalAlpha = starAlpha[i] * twinkle;
        ctx.fillText(
          RAMP[starChar[i]],
          starCol[i] * cellW + cellW / 2,
          starRow[i] * cellH + cellH / 2
        );
      }

      // -- terrain render: one pass per layer, one globalAlpha set each -----
      ctx.fillStyle = fg;
      for (let li = 0; li < LAYERS.length; li++) {
        const layer = LAYERS[li];
        ctx.globalAlpha = layer.alpha;
        for (let r = horizonRow; r < rows; r++) {
          for (let c = 0; c < cols; c++) {
            const idx = r * cols + c;
            if (grpBuf[idx] !== li) continue;
            ctx.fillText(
              RAMP[charBuf[idx]],
              c * cellW + cellW / 2,
              r * cellH + cellH / 2
            );
          }
        }
      }
      ctx.globalAlpha = 1;
    };

    // -- hot-path state: locals only, never React state ---------------------
    let raf = 0;
    let last = 0;
    let t = 0;
    const cursor = { tx: 0, ty: 0, x: 0, y: 0 };

    const loop = (now: number) => {
      const dt = last ? Math.min(DT_MAX, (now - last) / 1000) : 1 / 60;
      last = now;
      t += dt;
      cursor.x += (cursor.tx - cursor.x) * CURSOR_EASE;
      cursor.y += (cursor.ty - cursor.y) * CURSOR_EASE;
      draw(t, cursor.x, cursor.y);
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    const onPointerMove = (e: PointerEvent) => {
      const rect = root.getBoundingClientRect();
      const nx = (e.clientX - rect.left) / rect.width - 0.5; // -0.5..0.5
      const ny = (e.clientY - rect.top) / rect.height - 0.5;
      cursor.tx = nx * MAX_PARALLAX_COLS;
      cursor.ty = ny * MAX_PARALLAX_ROWS;
    };
    const onPointerLeave = () => {
      cursor.tx = 0;
      cursor.ty = 0;
    };

    const onVis = () => {
      if (!document.hidden && !reduced && ready) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };
    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) draw(0, 0, 0);
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    document.fonts.ready.then(() => {
      if (disposed) return;
      readTokens();
      resize();
      ready = true;
      if (reduced) {
        draw(0, 0, 0);
      } else {
        raf = requestAnimationFrame(loop);
      }
    });

    window.addEventListener("resize", onResize);
    if (!reduced) {
      root.addEventListener("pointermove", onPointerMove);
      root.addEventListener("pointerleave", onPointerLeave);
    }
    document.addEventListener("visibilitychange", onVis);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      mo.disconnect();
      window.removeEventListener("resize", onResize);
      root.removeEventListener("pointermove", onPointerMove);
      root.removeEventListener("pointerleave", onPointerLeave);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [cellSize]);

  // `h-full` matters as much as the min-height below: a min-height only sets a
  // FLOOR. Dropped into a stretched grid/flex item taller than that floor — an
  // auth panel whose other column carries more copy — the root stopped at its
  // min-height and the canvas ended partway down, leaving a band of dead
  // background under the terrain. `h-full` resolves to `auto` when the parent
  // has no definite height (so the min-height still governs a standalone
  // hero) and fills the parent when it does.
  return (
    <div
      ref={rootRef}
      className={`relative isolate h-full w-full overflow-hidden bg-background font-mono ${
        /\bmin-h-/.test(className) ? "" : "min-h-screen"
      } ${className}`}
    >
      <canvas ref={canvasRef} aria-hidden className="absolute inset-0 block h-full w-full text-foreground" />
      {children ? (
        <div className="relative z-10 flex h-full w-full flex-col items-start justify-end gap-4 p-8 sm:p-14">
          {children}
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import type { ReactNode } from "react";

// ---------------------------------------------------------------------------
// VanishRun — a full-bleed ASCII perspective corridor. A fixed count of
// superellipse ("squircle") rings sit at evenly-spaced world depths and
// advance toward the viewer every frame (z -= speed*dt), wrapping back to
// the far plane once they pass the near clip so the ring count and spacing
// never change — the same treadmill trick a starfield uses, which is what
// makes the loop read as continuous forward motion down a tunnel rather than
// a reset. Every ring point projects into ISOTROPIC pixel space (both axes
// scaled by one constant K1, exactly the ascii-torus-donut discipline) around a
// shared vanishing point, and only THEN quantizes to the mono cell grid, so
// the rings stay true ellipses/squares instead of stretching with the cell's
// ~2:1 aspect. Nearer points win a per-cell Float32Array depth competition
// (bigger 1/z = nearer), same as ascii-torus-donut's depth buffer, because ring
// draw order does not correspond to depth order once rings have wrapped at
// different times — without it, a far ring could paint over a near one. The
// pointer steers the shared vanishing point itself (eased trailing toward
// the raw pointer position), so the whole corridor tilts toward the cursor;
// optional children re-center on that same point every frame via a direct
// style.transform write, never React state.
// ---------------------------------------------------------------------------

const RAMP = " .:-=+*#%@"; // 10-step density ramp, index 0 = blank
const RING_COUNT = 16;
const Z_NEAR = 0.55;
const Z_FAR = 6.2;
const CYCLE_SECONDS = 3.4; // time for one ring to travel Z_FAR -> Z_NEAR
const RING_SPEED = (Z_FAR - Z_NEAR) / CYCLE_SECONDS;
const WORLD_A = 1.55; // squircle half-width, world units
const WORLD_B = 1; // squircle half-height, world units
const SQUIRCLE_EXP = 0.5; // 2/n with n=4 — rounded-rect-ish ring
const VP_EASE = 0.07; // per-frame lerp of the vanishing point toward target
const VP_RANGE = 0.34; // fraction of render size the vp can travel
const DT_MAX = 0.05;
const CONTENT_FEATHER_PX = 64; // soft falloff distance beyond the children's box

export interface VanishRunProps {
  /** grid cell size in px */
  cellSize?: number;
  /** headline / CTA centered at the vanishing point */
  children?: ReactNode;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function VanishRun({
  cellSize = 13,
  children,
  className = "",
}: VanishRunProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    let fg = "currentColor";
    let cellW = cellSize;
    let cellH = cellSize;
    let cols = 0;
    let rows = 0;
    let dpr = 1;
    let sized = false;
    let ready = false;
    let disposed = false;

    let rMinRow = 0;
    let rMaxRow = 0;
    let rMinCol = 0;
    let rMaxCol = 0;
    let renderCx = 0;
    let renderCy = 0;
    let K1 = 0;
    let vpMaxPx = 0;
    let rootW = 0;
    let rootH = 0;

    // -- children's measured box, kept fresh via ResizeObserver, used to
    // attenuate the ring field under whatever the caller passes as children --
    const content = contentRef.current;
    const hasContent = !!content;
    let contentW = 0;
    let contentH = 0;
    const measureContent = () => {
      if (!content) return;
      const r = content.getBoundingClientRect();
      contentW = r.width;
      contentH = r.height;
    };
    measureContent();
    const contentRO = content ? new ResizeObserver(measureContent) : null;
    if (content) contentRO?.observe(content);

    let depthBuf = new Float32Array(0);
    let charBuf = new Uint8Array(0);

    let pointsPerRing = 96;
    const ringZ = new Float32Array(RING_COUNT);
    for (let i = 0; i < RING_COUNT; i++) {
      ringZ[i] = Z_NEAR + (i * (Z_FAR - Z_NEAR)) / RING_COUNT;
    }

    const readTokens = () => {
      fg = getComputedStyle(canvas).color;
    };

    const measureCell = (fontFamily: string) => {
      const off = document.createElement("canvas");
      const octx = off.getContext("2d");
      if (!octx) return;
      octx.font = `${cellSize}px ${fontFamily}`;
      cellW = Math.max(4, octx.measureText("MMMMMMMMMM").width / 10);
      cellH = cellSize;
    };

    const resize = () => {
      const { width, height } = canvas.getBoundingClientRect();
      if (width < 2 || height < 2) {
        sized = false;
        return;
      }
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const fontFamily = getComputedStyle(canvas).fontFamily;
      measureCell(fontFamily);
      ctx.font = `${cellSize}px ${fontFamily}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";

      rootW = width;
      rootH = height;

      cols = Math.max(4, Math.floor(width / cellW));
      rows = Math.max(6, Math.floor(height / cellH));

      rMinRow = 0;
      rMaxRow = rows;
      rMinCol = 0;
      rMaxCol = cols;

      const renderW = rMaxCol * cellW;
      const renderH = rMaxRow * cellH;
      renderCx = renderW / 2;
      renderCy = renderH / 2;
      const minRenderPx = Math.min(renderW, renderH);
      K1 = minRenderPx * 0.46;
      vpMaxPx = minRenderPx * VP_RANGE;

      pointsPerRing = Math.min(220, Math.max(48, Math.round(minRenderPx / 5)));

      depthBuf = new Float32Array(cols * rows);
      charBuf = new Uint8Array(cols * rows);
      sized = true;
    };

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
        if (reduced) draw();
      }, 150);
    };

    const draw = () => {
      if (!sized) return;
      const w = cols * cellW;
      const h = rows * cellH;
      ctx.clearRect(0, 0, w, h);
      depthBuf.fill(0);
      charBuf.fill(0);

      const cx = renderCx + vp.x;
      const cy = renderCy + vp.y;
      const thetaStep = (Math.PI * 2) / pointsPerRing;

      for (let i = 0; i < RING_COUNT; i++) {
        const z = ringZ[i];
        const ooz = 1 / z;
        const depthT = Math.min(
          1,
          Math.max(0, 1 - (z - Z_NEAR) / (Z_FAR - Z_NEAR))
        );
        const li = Math.min(
          RAMP.length - 1,
          Math.max(1, Math.round(Math.pow(depthT, 0.85) * (RAMP.length - 1)))
        );

        for (let p = 0; p < pointsPerRing; p++) {
          const theta = p * thetaStep;
          const cosT = Math.cos(theta);
          const sinT = Math.sin(theta);
          const wx =
            WORLD_A * Math.sign(cosT) * Math.pow(Math.abs(cosT), SQUIRCLE_EXP);
          const wy =
            WORLD_B * Math.sign(sinT) * Math.pow(Math.abs(sinT), SQUIRCLE_EXP);

          const px = cx + K1 * ooz * wx;
          const py = cy + K1 * ooz * wy;
          const col = Math.round(px / cellW);
          const row = Math.round(py / cellH);
          if (col < rMinCol || col >= rMaxCol || row < rMinRow || row >= rMaxRow)
            continue;

          const idx = row * cols + col;
          if (ooz > depthBuf[idx]) {
            depthBuf[idx] = ooz;
            charBuf[idx] = li + 1;
          }
        }
      }

      // children's box in the same coordinate space canvas cells are drawn
      // in (root-local CSS px) — the field attenuates toward the background
      // under it, feathering out over CONTENT_FEATHER_PX rather than a hard
      // cut, so it reads as glyphs dimming out rather than a punched hole
      const hasContentBox = hasContent && contentW > 0 && contentH > 0;
      const contentCx = rootW / 2 + vp.x;
      const contentCy = rootH / 2 + vp.y;
      const innerHalfW = contentW / 2;
      const innerHalfH = contentH / 2;

      ctx.fillStyle = fg;
      for (let row = rMinRow; row < rMaxRow; row++) {
        for (let col = rMinCol; col < rMaxCol; col++) {
          const idx = row * cols + col;
          const ci = charBuf[idx];
          if (ci === 0) continue;
          const li = ci - 1;
          let alpha = 0.3 + (li / (RAMP.length - 1)) * 0.7;
          const px = col * cellW + cellW / 2;
          const py = row * cellH + cellH / 2;
          if (hasContentBox) {
            const dx = Math.max(Math.abs(px - contentCx) - innerHalfW, 0);
            const dy = Math.max(Math.abs(py - contentCy) - innerHalfH, 0);
            const dist = Math.sqrt(dx * dx + dy * dy);
            const t = Math.min(1, Math.max(0, dist / CONTENT_FEATHER_PX));
            const atten = t * t * (3 - 2 * t); // smoothstep
            if (atten <= 0.02) continue;
            alpha *= atten;
          }
          ctx.globalAlpha = alpha;
          ctx.fillText(RAMP[li], px, py);
        }
      }
      ctx.globalAlpha = 1;
    };

    // -- hot-path state: locals only, never React state ---------------------
    let raf = 0;
    let last = 0;
    const vp = { tx: 0, ty: 0, x: 0, y: 0 };

    const placeContent = () => {
      const content = contentRef.current;
      if (!content) return;
      content.style.transform = `translate(-50%, -50%) translate(${vp.x}px, ${vp.y}px)`;
    };

    const loop = (now: number) => {
      const dt = last ? Math.min(DT_MAX, (now - last) / 1000) : 1 / 60;
      last = now;
      for (let i = 0; i < RING_COUNT; i++) {
        ringZ[i] -= RING_SPEED * dt;
        if (ringZ[i] < Z_NEAR) ringZ[i] += Z_FAR - Z_NEAR;
      }
      vp.x += (vp.tx - vp.x) * VP_EASE;
      vp.y += (vp.ty - vp.y) * VP_EASE;
      draw();
      placeContent();
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    const onPointerMove = (e: PointerEvent) => {
      const rect = root.getBoundingClientRect();
      const nx = (e.clientX - rect.left) / rect.width - 0.5;
      const ny = (e.clientY - rect.top) / rect.height - 0.5;
      vp.tx = nx * 2 * vpMaxPx;
      vp.ty = ny * 2 * vpMaxPx;
    };
    const onPointerLeave = () => {
      vp.tx = 0;
      vp.ty = 0;
    };

    const onVis = () => {
      if (!document.hidden && !reduced && ready) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };
    const mo = new MutationObserver(() => {
      readTokens();
      if (reduced) draw();
    });
    mo.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    document.fonts.ready.then(() => {
      if (disposed) return;
      readTokens();
      resize();
      ready = true;
      if (reduced) {
        draw();
        placeContent();
      } else {
        raf = requestAnimationFrame(loop);
      }
    });

    window.addEventListener("resize", onResize);
    if (!reduced) {
      root.addEventListener("pointermove", onPointerMove);
      root.addEventListener("pointerleave", onPointerLeave);
    }
    document.addEventListener("visibilitychange", onVis);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      if (resizeTimer) clearTimeout(resizeTimer);
      mo.disconnect();
      contentRO?.disconnect();
      window.removeEventListener("resize", onResize);
      root.removeEventListener("pointermove", onPointerMove);
      root.removeEventListener("pointerleave", onPointerLeave);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [cellSize]);

  return (
    <div
      ref={rootRef}
      className={`relative isolate min-h-screen w-full overflow-hidden bg-background font-mono ${className}`}
    >
      <canvas ref={canvasRef} aria-hidden className="absolute inset-0 block h-full w-full text-foreground" />
      {children ? (
        <div
          ref={contentRef}
          className="absolute left-1/2 top-1/2 flex w-full max-w-md flex-col items-center gap-4 px-6 text-center"
          style={{ transform: "translate(-50%, -50%)" }}
        >
          {children}
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { useEffect, useRef, type ReactNode } from "react";

// ---------------------------------------------------------------------------
// HeroBeamGlyph — a full-bleed hero wordmark drawn the way an XY vector CRT
// (Asteroids/Tempest/Vectrex-class arcade hardware, Tektronix vector/storage
// scope character generators) actually drew text: an electron beam tracing
// single-stroke letterforms (Hershey-style — one continuous poly-line per
// glyph, pen lifted between disconnected strokes), never a filled or
// raster/block glyph like every other ASCII/glyph component in this
// registry. A vector beam has no shutter and no pixel grid, so brightness at
// any point on the trace is a direct function of beam DWELL TIME: fast along
// long straight runs (dimmer), slow at direction-change vertices and stroke
// endpoints (brighter) — real vector-monitor beam physics, not a stylistic
// choice.
//
// The beam retraces the wordmark on a fixed 36Hz cycle (matches the
// commonly cited ~30-40Hz refresh of real vector arcade hardware under
// moderate draw-list length). Each retrace fades the previous pass toward
// the background token first, THEN draws the new pass additively/
// subtractively depending on theme direction (see COMPOSITE DIRECTION
// below) — a short multi-frame phosphor trail, deliberately NOT
// flyback-tear's whole-seconds broadcast-signal decay: this is a live,
// continuously-refreshing beam, not a failing timebase.
//
// COMPOSITE DIRECTION IS THEME-AWARE, NOT A COLOUR SWAP. In dark theme
// (bright foreground on a near-black background) a "glow" is genuinely
// additive — brighter strokes should push toward white, so retrace passes
// use `globalCompositeOperation: "lighter"`. In light theme the SAME
// brighter-at-corners relationship has to read as MORE INK, not more white
// — additive blending in light theme would wash dark strokes toward the
// light background and invert the whole mechanic, so light theme retraces
// with `"multiply"` instead. Which mode applies is decided at every token
// read by comparing the relative luminance of --foreground and
// --background, never by a class-name assumption.
//
// Beam jitter (simulated CRT deflection-coil hum) perturbs every vertex by
// a small smooth per-vertex-phased sine, sampled from a continuous
// simulation clock independent of the 36Hz retrace cadence (so its phase
// keeps advancing between retraces even though only a retrace event ever
// paints it). Pointer proximity locally boosts jitter amplitude near the
// cursor and decays back over roughly a second once the pointer leaves —
// brightness/jitter only, --ns-accent never appears anywhere in this
// component.
// ---------------------------------------------------------------------------

// -- single-stroke vector font -----------------------------------------
// Each letter is a list of strokes; each stroke is a flat [x0,y0,x1,y1,...]
// polyline in a 4-wide x 6-tall unit cell (Hershey-style: continuous pen-down
// runs, pen lifted between separate strokes). Hand-authored geometric
// approximation, not a traced copy of the historical Hershey glyph set.
const STROKE_FONT: Record<string, number[][]> = {
