"use client";

import { useEffect, useRef, useState } from "react";

// Success moment as magnetism: a field of scattered iron filings drifts
// aimlessly until the action confirms — then a field switches on and the
// filings migrate and ALIGN, drawing the checkmark as revealed field lines.
// Filings near the path snap onto it; the rest stay put but rotate to the
// local field direction, so the check emerges from the whole field, not a
// stamped glyph. All canvas ink is read from CSS tokens at mount and on
// theme change.

type Particle = {
  x: number;
  y: number;
  vx: number;
  vy: number;
  angle: number;
  // assigned on confirm
  tx: number;
  ty: number;
  tAngle: number;
  delay: number;
  onPath: boolean;
  // idle drift
  dx: number;
  dy: number;
  spin: number;
  seed: number;
};

const COUNT = 520;
// checkmark polyline, normalized to the field box
const CHECK: [number, number][] = [
  [0.3, 0.55],
  [0.45, 0.72],
  [0.72, 0.3],
];

function nearestOnCheck(
  x: number,
  y: number,
  w: number,
  h: number
): { px: number; py: number; tangent: number; dist: number } {
  let best = { px: 0, py: 0, tangent: 0, dist: Infinity };
  for (let s = 0; s < CHECK.length - 1; s++) {
    const ax = CHECK[s][0] * w;
    const ay = CHECK[s][1] * h;
    const bx = CHECK[s + 1][0] * w;
    const by = CHECK[s + 1][1] * h;
    const abx = bx - ax;
    const aby = by - ay;
    const len2 = abx * abx + aby * aby;
    const t = Math.max(
      0,
      Math.min(1, ((x - ax) * abx + (y - ay) * aby) / len2)
    );
    const px = ax + abx * t;
    const py = ay + aby * t;
    const d = Math.hypot(x - px, y - py);
    if (d < best.dist) {
      best = { px, py, tangent: Math.atan2(aby, abx), dist: d };
    }
  }
  return best;
}

export function IronFilings({
  className = "",
}: {
  /** extra classes merged onto the rendered root element */
  className?: string;
}) {
  const [phase, setPhase] = useState<"idle" | "pending" | "done">("idle");
  const fieldRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const phaseRef = useRef(phase);
  phaseRef.current = phase;
  const reduced = useRef(false);
  const confirmAt = useRef(0);

  useEffect(() => {
    const field = fieldRef.current;
    const canvas = canvasRef.current;
    if (!field || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    reduced.current = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    let w = 0;
    let h = 0;
    let ink = { fg: "#888", muted: "#888" };
    let raf = 0;
    let last = 0;
    let running = false;

    const readInk = () => {
      const cs = getComputedStyle(document.documentElement);
      ink = {
        fg: cs.getPropertyValue("--foreground").trim() || "#888",
        muted: cs.getPropertyValue("--ns-muted").trim() || "#888",
      };
    };
    readInk();

    // deterministic-ish scatter, reseeded per mount
    const rand = (() => {
      let s = 1234567;
      return () => {
        s = (s * 1103515245 + 12345) & 0x7fffffff;
        return s / 0x7fffffff;
      };
    })();

    const particles: Particle[] = Array.from({ length: COUNT }, () => ({
      x: 0,
      y: 0,
      vx: 0,
      vy: 0,
      angle: rand() * Math.PI,
      tx: 0,
      ty: 0,
      tAngle: 0,
      delay: 0,
      onPath: false,
      dx: (rand() - 0.5) * 5,
      dy: (rand() - 0.5) * 5,
      spin: (rand() - 0.5) * 0.35,
      seed: rand(),
    }));
    let seeded = false;

    const resize = () => {
      const rect = field.getBoundingClientRect();
      if (rect.width < 4 || rect.height < 4) return;
      w = rect.width;
      h = rect.height;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
      canvas.style.width = `${w}px`;
      canvas.style.height = `${h}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      if (!seeded) {
        for (const p of particles) {
          p.x = rand() * w;
          p.y = rand() * h;
        }
        seeded = true;
      }
      if (phaseRef.current === "done") assignTargets();
      wake();
    };

    const assignTargets = () => {
      // 68% land on the stroke itself, the rest align in place as halo
      for (let i = 0; i < particles.length; i++) {
        const p = particles[i];
        p.onPath = p.seed < 0.68;
        if (p.onPath) {
          const t = (i / particles.length + p.seed * 0.13) % 1;
          // walk the polyline by arc length
          const l1 = Math.hypot(
            (CHECK[1][0] - CHECK[0][0]) * w,
            (CHECK[1][1] - CHECK[0][1]) * h
          );
          const l2 = Math.hypot(
            (CHECK[2][0] - CHECK[1][0]) * w,
            (CHECK[2][1] - CHECK[1][1]) * h
          );
          const d = t * (l1 + l2);
          const seg = d < l1 ? 0 : 1;
          const st = seg === 0 ? d / l1 : (d - l1) / l2;
          const ax = CHECK[seg][0] * w;
          const ay = CHECK[seg][1] * h;
          const bx = CHECK[seg + 1][0] * w;
          const by = CHECK[seg + 1][1] * h;
          const tangent = Math.atan2(by - ay, bx - ax);
          // thickness: gaussian-ish normal offset builds a soft stroke
          const off =
            (p.seed - 0.5 + (((p.seed * 7919) % 1) - 0.5)) * 7;
          p.tx = ax + (bx - ax) * st + Math.cos(tangent + Math.PI / 2) * off;
          p.ty = ay + (by - ay) * st + Math.sin(tangent + Math.PI / 2) * off;
          p.tAngle = tangent + (p.seed - 0.5) * 0.3;
          p.delay = t * 0.45 + p.seed * 0.15;
        } else {
          const near = nearestOnCheck(p.x, p.y, w, h);
          // halo filings creep slightly toward the field, mostly rotate
          p.tx = p.x + (near.px - p.x) * 0.12;
          p.ty = p.y + (near.py - p.y) * 0.12;
          p.tAngle = near.tangent;
          p.delay = p.seed * 0.5;
        }
      }
      confirmAt.current = performance.now();
    };

    const K = 130;
    const ZETA = 0.82;
    const draw = (dt: number, now: number) => {
      ctx.clearRect(0, 0, w, h);
      const done = phaseRef.current === "done";
      const elapsed = (now - confirmAt.current) / 1000;
      let settled = true;
      for (const p of particles) {
        if (done) {
          if (elapsed > p.delay) {
            const c = 2 * ZETA * Math.sqrt(K);
            p.vx += (K * (p.tx - p.x) - c * p.vx) * dt;
            p.vy += (K * (p.ty - p.y) - c * p.vy) * dt;
            p.x += p.vx * dt;
            p.y += p.vy * dt;
            let dA = p.tAngle - p.angle;
            while (dA > Math.PI / 2) dA -= Math.PI;
            while (dA < -Math.PI / 2) dA += Math.PI;
            p.angle += dA * Math.min(1, dt * 7);
            if (
              Math.abs(p.tx - p.x) > 0.4 ||
              Math.abs(p.vx) > 3 ||
              Math.abs(dA) > 0.02
            )
              settled = false;
          } else {
            // pre-delay: burst velocity coasts under drag, so a replay's
            // outward fling is visible before the field pulls back
            p.x += p.vx * dt;
            p.y += p.vy * dt;
            p.vx -= p.vx * 3 * dt;
            p.vy -= p.vy * 3 * dt;
            settled = false;
          }
        } else {
          // aimless drift, wrapped
          p.x += p.dx * dt;
          p.y += p.dy * dt;
          p.angle += p.spin * dt;
          if (p.x < -4) p.x = w + 4;
          if (p.x > w + 4) p.x = -4;
          if (p.y < -4) p.y = h + 4;
          if (p.y > h + 4) p.y = -4;
          settled = false;
        }
        const len = p.onPath && done ? 3.4 : 2.8;
        const alpha = done ? (p.onPath ? 0.95 : 0.28) : 0.4;
        ctx.strokeStyle = done && p.onPath ? ink.fg : ink.muted;
        ctx.globalAlpha = alpha;
        ctx.lineWidth = 1.1;
        ctx.beginPath();
        ctx.moveTo(
          p.x - Math.cos(p.angle) * len,
          p.y - Math.sin(p.angle) * len
        );
        ctx.lineTo(
          p.x + Math.cos(p.angle) * len,
          p.y + Math.sin(p.angle) * len
        );
        ctx.stroke();
      }
      ctx.globalAlpha = 1;
      return settled;
    };

    const loop = (t: number) => {
      const dt = Math.min((t - (last || t)) / 1000, 1 / 30);
      last = t;
      const settled = draw(dt, t);
      if (settled || (reduced.current && phaseRef.current !== "done")) {
        running = false;
        return;
      }
      raf = requestAnimationFrame(loop);
    };
    const wake = () => {
      if (!running) {
        running = true;
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    // reduced motion: skip migration entirely — jump to the final frame
    const snapToFinal = () => {
      for (const p of particles) {
        p.x = p.tx;
        p.y = p.ty;
        p.angle = p.tAngle;
        p.vx = p.vy = 0;
        p.delay = 0;
      }
      confirmAt.current = -Infinity;
      draw(0, performance.now());
    };

    const api = {
      confirm: () => {
        assignTargets();
        if (reduced.current) snapToFinal();
        else wake();
      },
      replay: () => {
        // burst outward, then re-align — the celebration replays
        for (const p of particles) {
          p.vx += (p.seed - 0.5) * 1600;
          p.vy += (((p.seed * 7919) % 1) - 0.5) * 1600;
        }
        assignTargets();
        if (reduced.current) snapToFinal();
        else wake();
      },
    };
    (
      field as HTMLDivElement & { __filings?: typeof api }
    ).__filings = api;

    const ro = new ResizeObserver(resize);
    ro.observe(field);
    resize();

    const themeObserver = new MutationObserver(() => {
      readInk();
      wake();
      if (reduced.current) draw(0, performance.now());
    });
    themeObserver.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });
    const onVis = () => {
      if (document.hidden) {
        cancelAnimationFrame(raf);
        running = false;
      } else wake();
    };
    document.addEventListener("visibilitychange", onVis);
    if (!reduced.current) wake();
    else draw(0, performance.now());

    return () => {
      ro.disconnect();
      themeObserver.disconnect();
      document.removeEventListener("visibilitychange", onVis);
      cancelAnimationFrame(raf);
      delete (field as HTMLDivElement & { __filings?: typeof api })
        .__filings;
    };
  }, []);

  const act = (fn: "confirm" | "replay") => {
    (
      fieldRef.current as
        | (HTMLDivElement & {
            __filings?: { confirm: () => void; replay: () => void };
          })
        | null
    )?.__filings?.[fn]();
  };

  const onClick = () => {
    if (phase === "pending") return;
    if (phase === "done") {
      act("replay");
      return;
    }
    setPhase("pending");
    window.setTimeout(() => {
      setPhase("done");
      act("confirm");
    }, 350);
  };

  return (
    <div
      className={`relative overflow-hidden rounded-md border border-border bg-background ${className}`}
    >
      {/* the field */}
      <div ref={fieldRef} className="relative h-64 w-full">
        <canvas
          ref={canvasRef}
          aria-hidden="true"
          className="pointer-events-none absolute inset-0"
        />
        <div
          aria-live="polite"
          className="absolute inset-x-0 bottom-4 text-center"
        >
          {phase === "done" && (
            <p
              data-filings-done=""
              className="font-mono text-xs uppercase tracking-[0.2em] text-foreground"
            >
              Payment confirmed
            </p>
          )}
          {phase === "pending" && (
            <p className="font-mono text-xs uppercase tracking-[0.2em] text-ns-muted">
              Processing
            </p>
          )}
        </div>
      </div>

      <div className="flex items-center justify-between border-t border-border px-5 py-4">
        <div
          className={`transition-opacity duration-300 ${phase === "done" ? "opacity-40" : ""}`}
        >
          <p className="text-sm font-medium text-foreground">Order #1284</p>
          <p className="font-mono text-xs text-ns-muted">3 items · $148.00</p>
        </div>
        <button
          type="button"
          onClick={onClick}
          disabled={phase === "pending"}
          className="rounded-sm bg-ns-accent px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-ns-accent-hover focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent disabled:opacity-60 disabled:pointer-events-none"
        >
          {phase === "done"
            ? "Replay"
            : phase === "pending"
              ? "Processing…"
              : "Confirm payment"}
        </button>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// SeedCrystal — a high-stakes success moment built on supercooling. While an
// action is pending (payment confirming, deploy running, publish in flight)
// the panel behind the content is a supercooled liquid: a canvas particle
// field of ~800 points doing damped random walks, a faint restless shimmer
// that visibly holds more energy than a settled surface should. The instant
// the pending action resolves, a nucleation flash fires at the exact point
// the user pressed and dendritic crystal growth races outward from it —
// needle segments advancing with side branches forking at ~60deg at
// depth-decaying probability — while nearby shimmer particles lock onto the
// nearest needle as its front passes, freezing the whole pane solid in
// ~700ms. The confirmation line then sits calm on the now-still crystal.
//
// MECHANISM: growth is precomputed synchronously the instant success fires
// (mulberry32-seeded), not simulated tip-by-tip per frame — every needle
// segment carries a "birth" time (seconds from growth start) baked in when
// it's built, the same reveal-by-threshold technique as switch-frost.
// Each animation frame just draws every segment whose birth <= elapsed and
// every particle whose precomputed lockBirth <= elapsed, which is O(live
// geometry) per frame instead of O(particles x segments) per frame — the
// nearest-segment lock search itself is a single one-time scan done once at
// growth start, not repeated on every tick.
//
// A locked particle's target point and birth are baked in at that same scan;
// past its lockBirth it eases from its ambient position onto the needle
// over a short settle window, tinting from --ns-muted toward --foreground as it
// commits. Once every particle has finished settling the loop cancels itself
// entirely — "frozen" is a real stopped rAF, not a slow one, matching the
// brief's "freezing solid" rather than an animation that merely looks still.
//
// TOKENS: every drawn color is read from --ns-muted / --foreground via
// getComputedStyle at mount and re-derived on a MutationObserver watching
// documentElement class changes (both the live loop and a frozen redraw use
// the same ref, so a theme flip repaints correctly whether mid-growth or
// long settled). The canvas itself is never painted with a background —
// --background shows through from the panel div underneath it.
//
// A11Y: canvas is aria-hidden + role=presentation. Success is announced via
// a role=status aria-live=assertive line that mounts the instant React state
// flips to "success" — independent of the ~700ms canvas animation, which is
// purely decorative. The trigger button is never disabled (state re-entry is
// guarded in JS, not via the disabled attribute), so it stays clickable
// throughout and never blocks anything. Reduced motion swaps the whole
// canvas for one static, seeded-once crystal texture — no shimmer, no
// growth — with the same status text driven by the same state machine.
// ---------------------------------------------------------------------------

type Status = "idle" | "pending" | "success";
type RGB = [number, number, number];

interface Seg {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  depth: number;
  birth: number; // seconds from growth start
}

interface Particle {
  bx: number; // base x, px
  by: number; // base y, px
  dx: number; // OU shimmer offset x, px
  dy: number;
  vx: number;
  vy: number;
  lockBirth: number; // seconds; Infinity = never locks
  lx: number; // lock target x
  ly: number; // lock target y
}

const PARTICLE_COUNT = 800;
const MAX_SEGS = 900;
const LOCK_RADIUS = 15; // px
const SETTLE_S = 0.22;
const FLASH_MS = 180;
const FREEZE_PAD_MS = 260; // extra time after growMs for the last lock to settle

function clamp01(v: number) {
  return Math.min(1, Math.max(0, v));
}
function lerp(a: number, b: number, t: number) {
  return a + (b - a) * t;
}
function easeOutCubic(t: number) {
  const u = 1 - t;
  return 1 - u * u * u;
}

function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function parseHex(v: string): RGB | null {
  const m = v.trim().match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/i);
  if (!m) return null;
  let h = m[1]!;
  if (h.length === 3) h = h.split("").map((c) => c + c).join("");
  const n = parseInt(h, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function readToken(el: HTMLElement, name: string, fallback: RGB): RGB {
  return parseHex(getComputedStyle(el).getPropertyValue(name)) ?? fallback;
}

function rgbaStr(rgb: RGB, a: number): string {
  return `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${a})`;
}

function mixRgb(a: RGB, b: RGB, t: number): RGB {
  return [lerp(a[0], b[0], t), lerp(a[1], b[1], t), lerp(a[2], b[2], t)];
}

function buildDust(count: number, w: number, h: number, rand: () => number): Particle[] {
  const out: Particle[] = [];
  for (let i = 0; i < count; i++) {
    out.push({
      bx: lerp(w * 0.04, w * 0.96, rand()),
      by: lerp(h * 0.04, h * 0.96, rand()),
      dx: 0,
      dy: 0,
      vx: 0,
      vy: 0,
      lockBirth: Infinity,
      lx: 0,
      ly: 0,
    });
  }
  return out;
}

// Precompute the whole dendritic pattern up front: primary arms radiate from
// the nucleation point, each a slightly curved walk that throws side
// branches at ~60deg with depth-decaying probability. Every segment's birth
// time is baked in at build time (reveal-by-threshold at draw time), the
// same trick switch-frost uses for its frost spines.
function buildCrystal(
  rand: () => number,
  cx: number,
  cy: number,
  w: number,
  h: number,
  growS: number
): { segs: Seg[]; maxBirth: number } {
  const segs: Seg[] = [];
  const STEP = 4;
  const maxLen = Math.hypot(w, h) * 0.58;
  const speed = maxLen / growS; // px/s, tuned so a straight arm finishes near growS
  const stepDur = STEP / speed;
  const maxDepth = 3;
  const baseProb = 0.5;
  const decay = 0.5;

  function grow(x: number, y: number, angle: number, depth: number, birth: number, steps: number) {
    let a = angle;
    let bx = x;
    let by = y;
    let b = birth;
    const curv = (rand() - 0.5) * 0.05;
    for (let k = 0; k < steps && segs.length < MAX_SEGS; k++) {
      a += curv + (rand() - 0.5) * 0.14;
      const nx = bx + Math.cos(a) * STEP;
      const ny = by + Math.sin(a) * STEP;
      if (nx < 1 || nx > w - 1 || ny < 1 || ny > h - 1) break;
      const birthClamped = Math.min(b, growS);
      segs.push({ x1: bx, y1: by, x2: nx, y2: ny, depth, birth: birthClamped });
      if (depth < maxDepth && k > 1 && k % 3 === 0) {
        const p = baseProb * Math.pow(decay, depth);
        if (rand() < p) {
          const side = rand() < 0.5 ? 1 : -1;
          const branchAngle = a + side * (0.96 + rand() * 0.18); // ~55-65deg
          const branchSteps = Math.max(3, Math.floor(steps * 0.45));
          grow(nx, ny, branchAngle, depth + 1, b + stepDur * 0.6, branchSteps);
        }
      }
      b += stepDur;
      bx = nx;
      by = ny;
    }
  }

  const arms = 5 + Math.floor(rand() * 2);
  const spread = (Math.PI * 2) / arms;
  for (let i = 0; i < arms; i++) {
    const angle = i * spread + (rand() - 0.5) * spread * 0.6;
    grow(cx, cy, angle, 0, 0, Math.ceil(maxLen / STEP));
  }

  let maxBirth = 0;
  for (const s of segs) if (s.birth > maxBirth) maxBirth = s.birth;
  return { segs, maxBirth: Math.max(maxBirth, 0.001) };
}

// one-time nearest-segment-endpoint scan: every particle either finds a
// needle endpoint within LOCK_RADIUS (and adopts that segment's birth as its
// own lockBirth + that endpoint as its settle target) or never locks and
// simply stops moving, in place, when the pane freezes.
function assignLocks(particles: Particle[], segs: Seg[]) {
  for (const p of particles) {
    let bestD = LOCK_RADIUS * LOCK_RADIUS;
    let bestSeg: Seg | null = null;
    for (const s of segs) {
      const dx = s.x2 - p.bx;
      const dy = s.y2 - p.by;
      const d = dx * dx + dy * dy;
      if (d < bestD) {
        bestD = d;
        bestSeg = s;
      }
    }
    if (bestSeg) {
      p.lockBirth = bestSeg.birth;
      p.lx = bestSeg.x2;
      p.ly = bestSeg.y2;
    }
  }
}

function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = (e: MediaQueryListEvent) => setReduced(e.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  return reduced;
}

export interface SeedCrystalProps {
  /** idle button label. default "Confirm payment" */
  label?: string;
  /** button label while the action is in flight. default "Confirming…" */
  pendingLabel?: string;
  /** the calm payoff line, also the aria-live=assertive announcement text. default "Payment confirmed" */
  confirmedText?: string;
  /** called on trigger; return a Promise and success plays on resolve (or reverts to idle on reject) */
  onConfirm?: () => void | Promise<void>;
  /** fallback simulated pending duration when onConfirm is absent or synchronous. default 900 */
  pendingMs?: number;
  /** crystal growth duration in ms. default 700 */
  growMs?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

export function SeedCrystal({
  label = "Confirm payment",
  pendingLabel = "Confirming…",
  confirmedText = "Payment confirmed",
  onConfirm,
  pendingMs = 900,
  growMs = 700,
  className = "",
}: SeedCrystalProps) {
  const reduced = useReducedMotion();
  const [status, setStatus] = useState<Status>("idle");
  const statusRef = useRef<Status>("idle");
  statusRef.current = status;

  const panelRef = useRef<HTMLDivElement>(null);
  const btnRef = useRef<HTMLButtonElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const pendingMsRef = useRef(pendingMs);
  pendingMsRef.current = pendingMs;
  const growMsRef = useRef(growMs);
  growMsRef.current = growMs;
  const onConfirmRef = useRef(onConfirm);
  onConfirmRef.current = onConfirm;

  const engineRef = useRef({
    w: 0,
    h: 0,
    dpr: 1,
    particles: [] as Particle[],
    segs: [] as Seg[],
    maxBirth: 0.001,
    growStart: 0, // performance.now() ms
    nucX: 0,
    nucY: 0,
    frozen: false,
    raf: 0,
    lastNow: 0,
    visible: true,
    muted: [141, 141, 141] as RGB,
    foreground: [237, 237, 237] as RGB,
    reduced: false,
    seedCounter: 1,
  });

  const controls = useRef<{
    startPending?: () => void;
    startGrowth?: (x: number, y: number) => void;
  }>({});

  useEffect(() => {
    const panel = panelRef.current;
    const canvas = canvasRef.current;
    if (!panel || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const e = engineRef.current;

    const syncColors = () => {
      e.muted = readToken(panel, "--ns-muted", e.muted);
      e.foreground = readToken(panel, "--foreground", e.foreground);
    };

    const resize = () => {
      const r = panel.getBoundingClientRect();
      e.w = Math.max(1, r.width);
      e.h = Math.max(1, r.height);
      e.dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.round(e.w * e.dpr);
      canvas.height = Math.round(e.h * e.dpr);
      canvas.style.width = `${e.w}px`;
      canvas.style.height = `${e.h}px`;
      if (statusRef.current === "idle" || statusRef.current === "pending") {
        // ambient only — safe to regenerate on resize, nothing depends on continuity
        e.particles = buildDust(PARTICLE_COUNT, e.w, e.h, mulberry32(e.seedCounter * 7919 + 1));
      }
    };

    const drawStatic = () => {
      // reduced motion: one faint, seeded-once dendritic texture, no motion.
      ctx.setTransform(e.dpr, 0, 0, e.dpr, 0, 0);
      ctx.clearRect(0, 0, e.w, e.h);
      const rand = mulberry32(424242);
      const { segs } = buildCrystal(rand, e.w * 0.5, e.h * 0.5, e.w, e.h, 1);
      ctx.lineCap = "round";
      ctx.strokeStyle = rgbaStr(e.foreground, 0.16);
      ctx.lineWidth = 0.75;
      ctx.beginPath();
      for (const s of segs) {
        ctx.moveTo(s.x1, s.y1);
        ctx.lineTo(s.x2, s.y2);
      }
      ctx.stroke();
    };

    const drawDust = () => {
      ctx.setTransform(e.dpr, 0, 0, e.dpr, 0, 0);
      ctx.clearRect(0, 0, e.w, e.h);
      ctx.fillStyle = rgbaStr(e.muted, 0.55);
      for (const p of e.particles) {
        ctx.beginPath();
        ctx.arc(p.bx + p.dx, p.by + p.dy, 0.9, 0, Math.PI * 2);
        ctx.fill();
      }
    };

    const stepDust = (dtS: number) => {
      const K = 46; // spring back toward origin
      const C = 7.5; // damping
      const NOISE = 90;
      for (const p of e.particles) {
        p.vx += (-K * p.dx - C * p.vx) * dtS + (Math.random() - 0.5) * NOISE * dtS;
        p.vy += (-K * p.dy - C * p.vy) * dtS + (Math.random() - 0.5) * NOISE * dtS;
        p.dx += p.vx * dtS;
        p.dy += p.vy * dtS;
      }
    };

    const drawGrowth = (elapsedMs: number) => {
      ctx.setTransform(e.dpr, 0, 0, e.dpr, 0, 0);
      ctx.clearRect(0, 0, e.w, e.h);
      const elapsedS = elapsedMs / 1000;

      // nucleation flash
      if (elapsedMs < FLASH_MS) {
        const t = elapsedMs / FLASH_MS;
        const r = lerp(2, 46, easeOutCubic(t));
        const a = (1 - t) * 0.85;
        const grad = ctx.createRadialGradient(e.nucX, e.nucY, 0, e.nucX, e.nucY, r);
        grad.addColorStop(0, rgbaStr(e.foreground, a));
        grad.addColorStop(1, rgbaStr(e.foreground, 0));
        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, e.w, e.h);
      }

      // particles: ambient shimmer until their needle passes, then settle
      // onto it, tinting from --ns-muted toward --foreground as they commit.
      // (velocity/offset integration for the still-unlocked ones happens once
      // per frame in the caller, before this draw — this only reads state.)
      for (const p of e.particles) {
        if (elapsedS < p.lockBirth) {
          ctx.fillStyle = rgbaStr(e.muted, 0.55);
          ctx.beginPath();
          ctx.arc(p.bx + p.dx, p.by + p.dy, 0.9, 0, Math.PI * 2);
          ctx.fill();
        } else {
          const t = clamp01((elapsedS - p.lockBirth) / SETTLE_S);
          const ease = easeOutCubic(t);
          const x = lerp(p.bx + p.dx, p.lx, ease);
          const y = lerp(p.by + p.dy, p.ly, ease);
          const col = mixRgb(e.muted, e.foreground, ease);
          ctx.fillStyle = rgbaStr(col, 0.5 + 0.45 * ease);
          ctx.beginPath();
          ctx.arc(x, y, 0.9 + 0.5 * ease, 0, Math.PI * 2);
          ctx.fill();
        }
      }

      // needles: soft halo pass then a crisp core, revealed by birth <= elapsed
      ctx.lineCap = "round";
      const widths = [1.4, 1.0, 0.75, 0.6];
      for (let pass = 0; pass < 2; pass++) {
        for (let d = 0; d <= 3; d++) {
          let any = false;
          ctx.beginPath();
          for (const s of e.segs) {
            if (s.depth !== d || s.birth > elapsedS) continue;
            ctx.moveTo(s.x1, s.y1);
            ctx.lineTo(s.x2, s.y2);
            any = true;
          }
          if (!any) continue;
          if (pass === 0) {
            ctx.strokeStyle = rgbaStr(e.foreground, 0.16);
            ctx.lineWidth = widths[d]! + 2.2;
          } else {
            ctx.strokeStyle = rgbaStr(e.foreground, 0.92);
            ctx.lineWidth = widths[d]!;
          }
          ctx.stroke();
        }
      }
    };

    // idle draws nothing (the panel's own --background shows through) and
    // does not reschedule itself — there's nothing to animate at rest, so
    // the loop stops rather than clearing an empty canvas 60x/s forever.
    const drawIdle = () => {
      ctx.setTransform(e.dpr, 0, 0, e.dpr, 0, 0);
      ctx.clearRect(0, 0, e.w, e.h);
    };

    const paintStill = () => {
      if (e.reduced) return drawStatic();
      const st = statusRef.current;
      if (st === "success") drawGrowth(e.frozen ? growMsRef.current + FREEZE_PAD_MS : performance.now() - e.growStart);
      else if (st === "pending") drawDust();
      else drawIdle();
    };

    const loop = (now: number) => {
      const dtMs = Math.min(48, now - e.lastNow);
      e.lastNow = now;
      const st = statusRef.current;

      if (st === "success") {
        const elapsedMs = now - e.growStart;
        // advance shimmer physics only for particles still unlocked
        const dtS = dtMs / 1000;
        const elapsedS = elapsedMs / 1000;
        const K = 46;
        const C = 7.5;
        const NOISE = 90;
        for (const p of e.particles) {
          if (elapsedS < p.lockBirth) {
            p.vx += (-K * p.dx - C * p.vx) * dtS + (Math.random() - 0.5) * NOISE * dtS;
            p.vy += (-K * p.dy - C * p.vy) * dtS + (Math.random() - 0.5) * NOISE * dtS;
            p.dx += p.vx * dtS;
            p.dy += p.vy * dtS;
          }
        }
        drawGrowth(elapsedMs);
        if (elapsedMs >= growMsRef.current + FREEZE_PAD_MS) {
          drawGrowth(growMsRef.current + FREEZE_PAD_MS); // final settled frame
          e.frozen = true;
          e.raf = 0;
          return; // loop stops — genuinely frozen, not just slow
        }
      } else if (st === "pending") {
        stepDust(dtMs / 1000);
        drawDust();
      } else {
        drawIdle();
        e.raf = 0;
        return; // nothing to animate at rest
      }

      e.raf = e.visible ? requestAnimationFrame(loop) : 0;
    };

    const wake = () => {
      if (e.raf || !e.visible || e.frozen) return;
      e.lastNow = performance.now();
      e.raf = requestAnimationFrame(loop);
    };

    controls.current.startPending = () => {
      e.frozen = false;
      e.particles = buildDust(PARTICLE_COUNT, e.w, e.h, mulberry32(e.seedCounter * 104729 + 3));
      wake();
    };

    controls.current.startGrowth = (nx: number, ny: number) => {
      e.nucX = nx;
      e.nucY = ny;
      e.growStart = performance.now();
      const seed = (e.seedCounter++ * 2654435761 + Math.floor(nx) * 97 + Math.floor(ny)) >>> 0;
      const rand = mulberry32(seed || 1);
      const growS = growMsRef.current / 1000;
      const built = buildCrystal(rand, nx, ny, e.w, e.h, growS);
      e.segs = built.segs;
      e.maxBirth = built.maxBirth;
      assignLocks(e.particles, e.segs);
      e.frozen = false;
      wake();
    };

    resize();
    syncColors();
    e.reduced = reduced;
    paintStill();

    const ro = new ResizeObserver(() => {
      resize();
      paintStill();
    });
    ro.observe(panel);

    const io = new IntersectionObserver(
      ([entry]) => {
        e.visible = !!entry?.isIntersecting;
        if (e.visible) wake();
        else if (e.raf) {
          cancelAnimationFrame(e.raf);
          e.raf = 0;
        }
      },
      { threshold: 0 }
    );
    io.observe(panel);

    const mo = new MutationObserver(() => {
      syncColors();
      if (!e.raf) paintStill(); // repaint the current still frame with new colors
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    return () => {
      cancelAnimationFrame(e.raf);
      e.raf = 0;
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reduced]);

  function handleActivate(clientX: number, clientY: number) {
    if (statusRef.current !== "idle") return;
    setStatus("pending");

    const canvas = canvasRef.current;
    const btn = btnRef.current;
    if (!reduced) controls.current.startPending?.();

    const finishToSuccess = () => {
      setStatus("success");
      const r = canvas?.getBoundingClientRect();
      let nx = engineRef.current.w * 0.5;
      let ny = engineRef.current.h * 0.5;
      // a real pointer click carries genuine coordinates; a keyboard-fired
      // click reports (0,0) in every browser, so treat that as "no point"
      // and nucleate from the button's own centre instead of the corner.
      const bt = btn?.getBoundingClientRect();
      const px = clientX === 0 && clientY === 0 && bt ? bt.left + bt.width / 2 : clientX;
      const py = clientX === 0 && clientY === 0 && bt ? bt.top + bt.height / 2 : clientY;
      if (r) {
        nx = clamp01((px - r.left) / (r.width || 1)) * engineRef.current.w;
        ny = clamp01((py - r.top) / (r.height || 1)) * engineRef.current.h;
      }
      if (!reduced) controls.current.startGrowth?.(nx, ny);
    };

    const ret = onConfirmRef.current?.();
    if (ret && typeof (ret as Promise<void>).then === "function") {
      (ret as Promise<void>).then(finishToSuccess, () => setStatus("idle"));
    } else {
      window.setTimeout(finishToSuccess, pendingMsRef.current);
    }
  }

  return (
    <div className={className}>
      <style>{`
@keyframes ns-seed-in{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:translateY(0)}}
.ns-seed-in{animation:ns-seed-in 320ms cubic-bezier(0.16,1,0.3,1) both}
@media (prefers-reduced-motion: reduce){ .ns-seed-in{animation:none} }
`}</style>

      <div
        ref={panelRef}
        data-seed-panel
        className="relative w-full overflow-hidden rounded-md border border-border bg-background p-6"
        style={{ minHeight: 220 }}
      >
        <canvas
          ref={canvasRef}
          aria-hidden
          role="presentation"
          className="pointer-events-none absolute inset-0 h-full w-full"
        />

        <div className="relative z-10 flex h-full flex-col justify-between gap-6">
          <div>
            <p className="font-mono text-xs uppercase tracking-[0.2em] text-ns-muted">
              Secure checkout
            </p>
            <p className="mt-1 text-sm text-ns-muted">
              One-time confirmation — held in a supercooled state until you act.
            </p>
          </div>

          <div className="flex flex-col items-start gap-4">
            <button
              ref={btnRef}
              type="button"
              onClick={(ev) => handleActivate(ev.clientX, ev.clientY)}
              aria-busy={status === "pending"}
              className="inline-flex items-center gap-2 rounded-sm bg-ns-accent px-5 py-2.5 text-sm font-medium text-white transition-colors hover:bg-ns-accent-hover focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
            >
              {status === "success" ? (
                <>
                  <svg viewBox="0 0 16 16" className="h-3.5 w-3.5" fill="none" aria-hidden>
                    <path
                      d="M3.5 8.5l3 3 6-7"
                      stroke="currentColor"
                      strokeWidth="1.6"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                  Confirmed
                </>
              ) : status === "pending" ? (
                pendingLabel
              ) : (
                label
              )}
            </button>

            {status === "success" ? (
              <p
                role="status"
                aria-live="assertive"
                data-seed-status
                className="ns-seed-in text-sm font-medium text-foreground"
              >
                {confirmedText}
              </p>
            ) : null}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// PlumbTrue — a success moment built on a plumb bob instead of confetti or a
// checkmark draw. Pressing the trigger stands in for the real event (payment
// confirmed, deploy finished, form accepted) firing *before* any motion plays:
// the accessible announcement and onConfirm fire synchronously at the press,
// then a bob drops from a fixed anchor on a fine string (translateY, gravity
// ease-in, a hard stop at full string length — no bounce in the length
// itself), and the sudden stop kicks it into a pendulum swing (rotate about
// the anchor) that decays through a few honest diminishing oscillations
// (closed-form damped cosine, recomputed every frame — no keyframe list) back
// to hanging dead straight. The card carries a second, fixed vertical datum
// line at the same x as the anchor: while swinging, the string visibly
// diverges from it; the moment the swing decays to rest the two are
// collinear — that coincidence *is* the verification, not a separate symbol.
// Only then does a level line draw outward from the bob's tip in both
// directions (stroke-dashoffset, ease-out-expo) and the success text rises
// and fades onto it. Two faint echo copies of the string+bob, tinted via
// color-mix, trail the first swing and fade out — an optional motion-blur
// read, never load-bearing.
//
// The pendulum's continuous per-frame pose is written straight to SVG
// attributes/style via refs (no React state on that path); the few discrete
// phase changes (armed -> settled, live-region text, button label) go through
// React state since they render only a handful of times per mount. Reduced
// motion skips the drop/swing/echoes entirely and snaps straight to the
// settled pose — the level line and text are simply already there, per the
// brief's "reduced motion renders the bob at rest, line and text already
// placed." Every color is a var(--token) reference read straight off the
// cascade (SVG attribute values resolve CSS custom properties natively), so
// there is nothing to re-derive on theme change.
// ---------------------------------------------------------------------------

export interface PlumbTrueProps {
  /** small line above the trigger, shown only while pending */
  pendingCopy?: string;
  /** label on the trigger button before it's pressed */
  pendingLabel?: string;
  /** label shown on the button while the bob is dropping/swinging */
  armingLabel?: string;
  /** announced immediately (role=status) and set onto the level line at rest */
  successMessage?: string;
  /** label the same button carries once settled — the real next action */
  nextActionLabel?: string;
  /** fires synchronously at press, before any motion — this *is* the event */
  onConfirm?: () => void;
  /** fires when the settled button is pressed */
  onNextAction?: () => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

type Phase = "pending" | "active" | "settled";

// -- geometry (SVG user units, viewBox 0 0 240 160) --------------------------
const VB_W = 240;
const VB_H = 160;
const ANCHOR_X = 120;
const ANCHOR_Y = 16;
const STRING_LEN = 92;
// bob: a small teardrop, local origin at its attach point, tip pointing down
const BOB_PATH = "M -6 4 A 6 6 0 1 1 6 4 Q 6 15 0 21 Q -6 15 -6 4 Z";
const BOB_TIP_Y = 21; // local y of the tip, relative to the bob's attach point
const LEVEL_Y = ANCHOR_Y + STRING_LEN + BOB_TIP_Y; // world y the level line draws at
const LEVEL_HALF = 84; // px the level line reaches left/right of center
const DATUM_TOP = 30;
const DATUM_BOTTOM = 126;

// -- timing/physics -----------------------------------------------------------
const DROP_MS = 200; // straight fall, ease-in, hard stop at STRING_LEN
const SWING_MS = 950; // pendulum decay window after the stop
const SWING_AMP = 15; // deg, deflection right at the stop (the "overshoot")
const SWING_PERIOD = 330; // ms per oscillation (~2.9 cycles over SWING_MS)
const SWING_TAU = 260; // ms, exponential decay time-constant
const ECHO_FADE_MS = 500; // ghost trail only reads during the first swing
const LEVEL_MS = 260; // ease-out-expo level-line draw
const TEXT_MS = 300; // success text fade + rise

function easeInQuad(t: number) {
  return t * t;
}

export function PlumbTrue({
  pendingCopy = "Order total $49.00",
  pendingLabel = "Confirm payment",
  armingLabel = "Confirming…",
  successMessage = "Payment confirmed",
  nextActionLabel = "View receipt",
  onConfirm,
  onNextAction,
  className = "",
}: PlumbTrueProps) {
  const [phase, setPhase] = useState<Phase>("pending");
  const [reduced, setReduced] = useState(false);
  const [live, setLive] = useState("");

  const phaseRef = useRef<Phase>("pending");
  const reducedRef = useRef(false);
  const rafRef = useRef(0);
  const buttonRef = useRef<HTMLButtonElement>(null);
  const wasSettled = useRef(false);

  const groupRef = useRef<SVGGElement>(null);
  const stringRef = useRef<SVGLineElement>(null);
  const bobRef = useRef<SVGPathElement>(null);
  const echo1GroupRef = useRef<SVGGElement>(null);
  const echo1StringRef = useRef<SVGLineElement>(null);
  const echo1BobRef = useRef<SVGPathElement>(null);
  const echo2GroupRef = useRef<SVGGElement>(null);
  const echo2StringRef = useRef<SVGLineElement>(null);
  const echo2BobRef = useRef<SVGPathElement>(null);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => {
      reducedRef.current = mq.matches;
      setReduced(mq.matches);
    };
    sync();
    mq.addEventListener("change", sync);
    return () => {
      mq.removeEventListener("change", sync);
      cancelAnimationFrame(rafRef.current);
    };
  }, []);

  // move focus onto the primary next action once settled, so a screen reader
  // (or a keyboard user who never looked away) lands where the flow expects
  useEffect(() => {
    if (phase === "settled" && !wasSettled.current) {
      wasSettled.current = true;
      buttonRef.current?.focus();
    }
  }, [phase]);

  function applyPose(l: number, thetaDeg: number) {
    const s = stringRef.current;
    const b = bobRef.current;
    const g = groupRef.current;
    if (s) s.setAttribute("y2", String(ANCHOR_Y + l));
    if (b) b.setAttribute("transform", `translate(${ANCHOR_X} ${ANCHOR_Y + l})`);
    if (g) g.style.transform = `rotate(${thetaDeg.toFixed(3)}deg)`;
  }

  function applyEcho(
    groupEl: SVGGElement | null,
    stringEl: SVGLineElement | null,
    bobEl: SVGPathElement | null,
    thetaDeg: number,
    opacity: number
  ) {
    if (stringEl) stringEl.setAttribute("y2", String(ANCHOR_Y + STRING_LEN));
    if (bobEl) bobEl.setAttribute("transform", `translate(${ANCHOR_X} ${ANCHOR_Y + STRING_LEN})`);
    if (groupEl) {
      groupEl.style.transform = `rotate(${thetaDeg.toFixed(3)}deg)`;
      groupEl.style.opacity = opacity.toFixed(3);
    }
  }

  function snapSettled() {
    applyPose(STRING_LEN, 0);
    applyEcho(echo1GroupRef.current, echo1StringRef.current, echo1BobRef.current, 0, 0);
    applyEcho(echo2GroupRef.current, echo2StringRef.current, echo2BobRef.current, 0, 0);
  }

  function startAnimation() {
    const start = performance.now();
    const tick = (now: number) => {
      const elapsed = now - start;
      if (elapsed < DROP_MS) {
        const l = STRING_LEN * easeInQuad(elapsed / DROP_MS);
        applyPose(l, 0);
      } else if (elapsed < DROP_MS + SWING_MS) {
        const tt = elapsed - DROP_MS;
        const theta =
          SWING_AMP * Math.exp(-tt / SWING_TAU) * Math.cos((2 * Math.PI * tt) / SWING_PERIOD);
        applyPose(STRING_LEN, theta);

        const echoOpacity = Math.max(0, 1 - tt / ECHO_FADE_MS) * 0.2;
        for (const lag of [40, 80] as const) {
          const et = Math.max(0, tt - lag);
          const etheta =
            SWING_AMP * Math.exp(-et / SWING_TAU) * Math.cos((2 * Math.PI * et) / SWING_PERIOD);
          if (lag === 40) {
            applyEcho(echo1GroupRef.current, echo1StringRef.current, echo1BobRef.current, etheta, echoOpacity);
          } else {
            applyEcho(echo2GroupRef.current, echo2StringRef.current, echo2BobRef.current, etheta, echoOpacity * 0.6);
          }
        }
      } else {
        snapSettled();
        phaseRef.current = "settled";
        setPhase("settled");
        rafRef.current = 0;
        return;
      }
      rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);
  }

  function confirm() {
    if (phaseRef.current !== "pending") return; // irreversible: one press decides it
    phaseRef.current = "active";
    setPhase("active");
    // the real event happens now, in full, regardless of what the instrument
    // goes on to draw — announcement and callback are never gated on motion
    setLive(successMessage);
    onConfirm?.();
    if (reducedRef.current) {
      snapSettled();
      phaseRef.current = "settled";
      setPhase("settled");
    } else {
      startAnimation();
    }
  }

  function handleClick() {
    if (phaseRef.current === "pending") confirm();
    else if (phaseRef.current === "settled") onNextAction?.();
    // mid-swing presses are inert: the outcome is already decided
  }

  const settled = phase === "settled";
  const textTop = (LEVEL_Y / VB_H) * 100;
  const buttonLabel = phase === "pending" ? pendingLabel : settled ? nextActionLabel : armingLabel;

  return (
    <div className={`rounded-md border border-border bg-background p-6 ${className}`}>
      <div
        className="relative mx-auto mb-1 w-full max-w-[220px]"
        style={{ aspectRatio: `${VB_W} / ${VB_H}` }}
      >
        <svg
          viewBox={`0 0 ${VB_W} ${VB_H}`}
          className="absolute inset-0 h-full w-full"
          aria-hidden="true"
        >
          {/* mount bracket + pivot */}
          <line
            x1={ANCHOR_X - 15}
            y1={ANCHOR_Y - 8}
            x2={ANCHOR_X + 15}
            y2={ANCHOR_Y - 8}
            stroke="var(--border)"
            strokeWidth="1"
          />
          <circle cx={ANCHOR_X} cy={ANCHOR_Y} r="2" fill="var(--border)" />

          {/* etched vertical datum — the fixed reference the bob must agree with */}
          <line
            x1={ANCHOR_X}
            y1={DATUM_TOP}
            x2={ANCHOR_X}
            y2={DATUM_BOTTOM}
            stroke="var(--border)"
            strokeWidth="1"
            strokeDasharray="1 3"
          />
          <line x1={ANCHOR_X - 5} y1={DATUM_TOP} x2={ANCHOR_X + 5} y2={DATUM_TOP} stroke="var(--border)" strokeWidth="1" />
          <line
            x1={ANCHOR_X - 5}
            y1={DATUM_BOTTOM}
            x2={ANCHOR_X + 5}
            y2={DATUM_BOTTOM}
            stroke="var(--border)"
            strokeWidth="1"
          />

          {/* ghost echoes — faint motion-blur read on the first swing only */}
          <g ref={echo1GroupRef} style={{ transformOrigin: `${ANCHOR_X}px ${ANCHOR_Y}px`, opacity: 0 }}>
            <line
              ref={echo1StringRef}
              x1={ANCHOR_X}
              y1={ANCHOR_Y}
              x2={ANCHOR_X}
              y2={ANCHOR_Y}
              stroke="color-mix(in srgb, var(--ns-muted) 20%, transparent)"
              strokeWidth="1"
            />
            <path ref={echo1BobRef} d={BOB_PATH} fill="color-mix(in srgb, var(--foreground) 20%, transparent)" />
          </g>
          <g ref={echo2GroupRef} style={{ transformOrigin: `${ANCHOR_X}px ${ANCHOR_Y}px`, opacity: 0 }}>
            <line
              ref={echo2StringRef}
              x1={ANCHOR_X}
              y1={ANCHOR_Y}
              x2={ANCHOR_X}
              y2={ANCHOR_Y}
              stroke="color-mix(in srgb, var(--ns-muted) 20%, transparent)"
              strokeWidth="1"
            />
            <path ref={echo2BobRef} d={BOB_PATH} fill="color-mix(in srgb, var(--foreground) 20%, transparent)" />
          </g>

          {/* the bob itself: fine string + filled teardrop, rotating about the anchor */}
          <g ref={groupRef} style={{ transformOrigin: `${ANCHOR_X}px ${ANCHOR_Y}px` }}>
            <line ref={stringRef} x1={ANCHOR_X} y1={ANCHOR_Y} x2={ANCHOR_X} y2={ANCHOR_Y} stroke="var(--ns-muted)" strokeWidth="1" />
            <path ref={bobRef} d={BOB_PATH} fill="var(--foreground)" transform={`translate(${ANCHOR_X} ${ANCHOR_Y})`} />
          </g>

          {/* level line — draws outward from the tip in both directions once settled */}
          <line
            x1={ANCHOR_X}
            y1={LEVEL_Y}
            x2={ANCHOR_X - LEVEL_HALF}
            y2={LEVEL_Y}
            stroke="var(--foreground)"
            strokeWidth="1"
            strokeDasharray={LEVEL_HALF}
            strokeDashoffset={settled ? 0 : LEVEL_HALF}
            style={{ transition: reduced ? "none" : `stroke-dashoffset ${LEVEL_MS}ms cubic-bezier(0.16,1,0.3,1)` }}
          />
          <line
            x1={ANCHOR_X}
            y1={LEVEL_Y}
            x2={ANCHOR_X + LEVEL_HALF}
            y2={LEVEL_Y}
            stroke="var(--foreground)"
            strokeWidth="1"
            strokeDasharray={LEVEL_HALF}
            strokeDashoffset={settled ? 0 : LEVEL_HALF}
            style={{ transition: reduced ? "none" : `stroke-dashoffset ${LEVEL_MS}ms cubic-bezier(0.16,1,0.3,1)` }}
          />
        </svg>

        {/* real DOM success text — sits just below the level line, clear of the
            resting bob (which occupies the space directly above the tip), and
            rises the last 8px up into that resting spot as it fades in */}
        <div
          className="pointer-events-none absolute left-1/2 w-[85%] -translate-x-1/2 pt-2 text-center"
          style={{ top: `${textTop}%` }}
        >
          <span
            data-plumb-success
            aria-hidden={settled ? undefined : "true"}
            className="pointer-events-auto inline-block text-sm font-semibold text-foreground sm:text-base"
            style={{
              opacity: settled ? 1 : 0,
              transform: `translateY(${settled ? 0 : 8}px)`,
              transition: reduced ? "none" : `opacity ${TEXT_MS}ms ease-out, transform ${TEXT_MS}ms cubic-bezier(0.16,1,0.3,1)`,
            }}
          >
            {successMessage}
          </span>
        </div>
      </div>

      <p
        className="text-center text-sm text-ns-muted"
        style={{ opacity: phase === "pending" ? 1 : 0, transition: "opacity 200ms ease-out" }}
      >
        {pendingCopy}
      </p>

      <div className="mt-4 flex justify-center">
        <button
          ref={buttonRef}
          type="button"
          onClick={handleClick}
          className="rounded-sm border border-border bg-background px-4 py-2 text-sm font-medium text-foreground transition-colors hover:bg-border/40 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
        >
          {buttonLabel}
        </button>
      </div>

      {/* announced immediately at confirm() — never delayed for the instrument */}
      <p role="status" aria-live="polite" className="sr-only">
        {live}
      </p>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import type { CSSProperties, ReactNode } from "react";

// ---------------------------------------------------------------------------
// TermiteVentilationShafts — a full-bleed ambient background modeling
// Macrotermes mound ventilation: thermosiphon convection through a FIXED
// network of surface ridge/shaft conduits (Turner 2001, "On the mound of
// Macrotermes michaelseni" — the exhalent/inhalent flow model). The conduit
// network — a chimney trunk at the container's center branching outward via
// a recursive angle-split — is generated exactly ONCE at mount and never
// re-grown or re-simulated. That is the load-bearing difference from the
// space-colonization pieces (auxin-canal, forage-vein, agar-starve): those
// regenerate or discover their network topology live; here the topology is
// architecture, fixed the moment the mound is built, and what's alive is
// only the flow direction and volume moving through it.
//
// MECHANIC: a single slow diurnal clock (42s period, a compressed day/night
// cycle) drives a temperature differential dT(t) = sin(2*PI*t/42). dT > 0 is
// exhale (warm air rising out through the network, flow runs trunk-to-tip);
// dT < 0 is inhale (flow reverses, tip-to-trunk). |dT| sets flow magnitude,
// so the network goes nearly still at the two crossover points each cycle
// (t=0, t=21) rather than snapping between directions. Each conduit segment
// eases its fill-fraction toward clamp(|dT| * segmentDepthFactor, 0, 1) on a
// 2.5s time constant, with segmentDepthFactor = 1 - 0.05*generation so flow
// visibly propagates outward from the trunk (or inward toward it) rather
// than updating everywhere at once. Direction is legible from a fill
// gradient alone only ambiguously, which is why a particle overlay carries
// it explicitly: any segment whose fill-fraction exceeds 0.15 gets 4-8 dots
// (scaled by segment length) advancing at 12px/s along the current flow
// direction, wrapping at the segment end. For the ~1.5s window around each
// crossover (|dT| < 0.08) particle motion pauses entirely — a real, briefly
// still moment twice per cycle — rather than crawling through zero.
//
// TOKENS: conduit outlines stroke in --border (the fixed structure, never a
// fill). Fill wash strokes the same path in --ns-muted at alpha scaled 0 to
// ~0.4 by fill-fraction. Flow particles are small --foreground dots at low
// alpha (raised in light theme, where the --ns-muted wash and --foreground
// sit closer together in contrast). --ns-accent never appears — direction
// is carried entirely by particle motion, magnitude entirely by fill-alpha,
// never by hue, so the piece stays legible with color removed entirely.
// ---------------------------------------------------------------------------

const CYCLE_S = 42; // diurnal period, s — the single governing clock
const FILL_TAU = 2.5; // s, fill-fraction ease time constant
const DEPTH_FACTOR_STEP = 0.05; // fill-target attenuation per generation (lag outward)
const PARTICLE_SPEED = 12; // px/s along a conduit
const STALL_THRESHOLD = 0.08; // |dT| below which particle motion fully stops
const FILL_GATE = 0.15; // fill-fraction above which particles render at all

const MAX_GEN = 6; // generations, trunk = 0
const TRUNK_COUNT = 7; // initial branches radiating from the chimney
const LENGTH_RATIO = 0.72; // per-generation length falloff
const SPREAD_MIN = (25 * Math.PI) / 180;
const SPREAD_MAX = (40 * Math.PI) / 180;
const CHILD_MIN = 2;
const CHILD_MAX = 3;
const EDGE_MARGIN = 0.46; // fraction of min(width,height)/1 — recursion stops past this radius
const TRUNK_LEN = 0.14; // fraction of min(width,height), generation-0 branch length

const REDUCED_FREEZE_T = 10.5; // in-cycle seconds -> dT=1, PEAK_EXHALE

// mulberry32 — deterministic per-mount PRNG so the fixed network is stable
// across re-renders within one mount (only the seed varies mount to mount).
function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

interface Segment {
  x0: number; // normalized coords, fraction of min(width,height), origin at container center
  y0: number;
  x1: number;
  y1: number;
  generation: number;
  length: number; // px, filled in on resize
  fill: number; // current eased fill-fraction, 0..1
  particles: Float32Array; // t in [0,1] along the segment, one entry per particle
}

function buildNetwork(rand: () => number): Segment[] {
  const segments: Segment[] = [];

  const grow = (x: number, y: number, angle: number, length: number, generation: number) => {
    const x1 = x + Math.cos(angle) * length;
    const y1 = y + Math.sin(angle) * length;
    segments.push({ x0: x, y0: y, x1, y1, generation, length: 0, fill: 0, particles: new Float32Array(0) });

    const r1 = Math.hypot(x1, y1);
    if (generation >= MAX_GEN - 1 || r1 >= EDGE_MARGIN) return;

    const childCount = rand() < 0.5 ? CHILD_MIN : CHILD_MAX;
    const spread = SPREAD_MIN + rand() * (SPREAD_MAX - SPREAD_MIN);
    const nextLength = length * LENGTH_RATIO;
    for (let i = 0; i < childCount; i++) {
      const t = i / (childCount - 1) - 0.5; // -0.5..0.5
      const jitter = (rand() - 0.5) * spread * 0.3;
      const childAngle = angle + t * spread * 2 + jitter;
      grow(x1, y1, childAngle, nextLength, generation + 1);
    }
  };

  for (let i = 0; i < TRUNK_COUNT; i++) {
    const angle = (i / TRUNK_COUNT) * Math.PI * 2 + rand() * 0.3;
    grow(0, 0, angle, TRUNK_LEN, 0);
  }

  return segments;
}

function particleCountFor(px: number): number {
  const n = Math.round(4 + (px / 90) * 4);
  return Math.max(4, Math.min(8, n));
}

function parseHex(raw: string): [number, number, number] {
  const m = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(raw.trim());
  if (!m) return [128, 128, 128];
  let h = m[1];
  if (h.length === 3) {
    h = h
      .split("")
      .map((c) => c + c)
      .join("");
  }
  const n = parseInt(h, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

const clamp01 = (v: number) => (v < 0 ? 0 : v > 1 ? 1 : v);

export interface TermiteVentilationShaftsProps {
  /** Skips mounting the canvas layer entirely; children render on the plain background. */
  disabled?: boolean;
  children?: ReactNode;
  className?: string;
  style?: CSSProperties;
}

export function TermiteVentilationShafts({
  disabled = false,
  children,
  className = "",
  style,
}: TermiteVentilationShaftsProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (disabled) return;
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    // mount mid-cycle at a random phase, not t=0, so the resting loop shows
    // motion already in progress from the first paint
    const rand = mulberry32((Math.random() * 0xffffffff) >>> 0);
    const segments = buildNetwork(rand);
    // mount phase, in-cycle seconds; reduced motion freezes on PEAK_EXHALE regardless
    const phaseOffset = reduced ? REDUCED_FREEZE_T : rand() * CYCLE_S;
    const startTime = performance.now() / 1000 - phaseOffset;

    let disposed = false;
    let ready = false;
    let raf = 0;
    let last = 0;

    let width = 0;
    let height = 0;
    let minDim = 0;

    let borderColor: [number, number, number] = [200, 200, 200];
    let mutedColor: [number, number, number] = [128, 128, 128];
    let fgColor: [number, number, number] = [23, 23, 23];
    let particleAlpha = 0.5;

    const readTokens = () => {
      const cs = getComputedStyle(document.documentElement);
      borderColor = parseHex(cs.getPropertyValue("--border") || "#e5e5e5");
      mutedColor = parseHex(cs.getPropertyValue("--ns-muted") || "#8f8f8f");
      fgColor = parseHex(cs.getPropertyValue("--foreground") || "#171717");
      // light theme's fill/foreground contrast compresses relative to dark,
      // so particles need a higher floor to stay distinct against the wash
      const isDark = document.documentElement.classList.contains("dark");
      particleAlpha = isDark ? 0.5 : 0.68;
    };

    const resize = () => {
      const rect = root.getBoundingClientRect();
      const w = Math.round(rect.width);
      const h = Math.round(rect.height);
      if (w < 2 || h < 2) return;
      width = w;
      height = h;
      minDim = Math.min(w, h);
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      for (const seg of segments) {
        const px0 = width / 2 + seg.x0 * minDim;
        const py0 = height / 2 + seg.y0 * minDim;
        const px1 = width / 2 + seg.x1 * minDim;
        const py1 = height / 2 + seg.y1 * minDim;
        seg.length = Math.hypot(px1 - px0, py1 - py0);
        const count = particleCountFor(seg.length);
        if (seg.particles.length !== count) {
          const next = new Float32Array(count);
          for (let i = 0; i < count; i++) next[i] = i / count;
          seg.particles = next;
        }
      }
    };

    const dTAt = (tCycle: number) => Math.sin((2 * Math.PI * tCycle) / CYCLE_S);

    const step = (nowS: number, dt: number) => {
      const tCycle = ((nowS % CYCLE_S) + CYCLE_S) % CYCLE_S;
      const dT = dTAt(tCycle);
      const mag = Math.abs(dT);
      const direction = dT >= 0 ? 1 : -1; // +1 exhale/outward, -1 inhale/inward
      const stalled = mag < STALL_THRESHOLD;
      const easeAmount = FILL_TAU > 0 ? 1 - Math.exp(-dt / FILL_TAU) : 1;

      for (const seg of segments) {
        const depthFactor = 1 - DEPTH_FACTOR_STEP * seg.generation;
        const target = clamp01(mag * depthFactor);
        seg.fill += (target - seg.fill) * easeAmount;

        if (seg.fill <= FILL_GATE || stalled || seg.length <= 0) continue;
        const dtNorm = (PARTICLE_SPEED * dt) / seg.length;
        for (let i = 0; i < seg.particles.length; i++) {
          let t = seg.particles[i] + direction * dtNorm;
          if (t > 1) t -= 1;
          else if (t < 0) t += 1;
          seg.particles[i] = t;
        }
      }
    };

    const render = () => {
      ctx.clearRect(0, 0, width, height);
      const cx = width / 2;
      const cy = height / 2;

      // pass 1: fixed outline, --border, thinner further out
      ctx.strokeStyle = `rgb(${borderColor[0]}, ${borderColor[1]}, ${borderColor[2]})`;
      for (const seg of segments) {
        const w = Math.max(0.6, minDim * 0.014 * Math.pow(LENGTH_RATIO, seg.generation));
        ctx.lineWidth = w;
        ctx.lineCap = "round";
        ctx.beginPath();
        ctx.moveTo(cx + seg.x0 * minDim, cy + seg.y0 * minDim);
        ctx.lineTo(cx + seg.x1 * minDim, cy + seg.y1 * minDim);
        ctx.stroke();
      }

      // pass 2: flow fill wash, --ns-muted, alpha by fill-fraction (0..~0.4)
      for (const seg of segments) {
        if (seg.fill <= 0.01) continue;
        const w = Math.max(0.8, minDim * 0.022 * Math.pow(LENGTH_RATIO, seg.generation));
        const alpha = seg.fill * 0.4;
        ctx.strokeStyle = `rgba(${mutedColor[0]}, ${mutedColor[1]}, ${mutedColor[2]}, ${alpha})`;
        ctx.lineWidth = w;
        ctx.lineCap = "round";
        ctx.beginPath();
        ctx.moveTo(cx + seg.x0 * minDim, cy + seg.y0 * minDim);
        ctx.lineTo(cx + seg.x1 * minDim, cy + seg.y1 * minDim);
        ctx.stroke();
      }

      // pass 3: flow particles, --foreground, low alpha
      ctx.fillStyle = `rgba(${fgColor[0]}, ${fgColor[1]}, ${fgColor[2]}, ${particleAlpha})`;
      const dotR = Math.max(0.9, minDim * 0.0032);
      for (const seg of segments) {
        if (seg.fill <= FILL_GATE) continue;
        for (let i = 0; i < seg.particles.length; i++) {
          const t = seg.particles[i];
          const px = cx + (seg.x0 + (seg.x1 - seg.x0) * t) * minDim;
          const py = cy + (seg.y0 + (seg.y1 - seg.y0) * t) * minDim;
          ctx.beginPath();
          ctx.arc(px, py, dotR, 0, Math.PI * 2);
          ctx.fill();
        }
      }
    };

    const loop = (nowMs: number) => {
      if (!ready) {
        raf = requestAnimationFrame(loop);
        return;
      }
      const nowS = nowMs / 1000;
      const dt = last ? Math.min(0.1, nowS - last) : 1 / 60;
      last = nowS;
      step(nowS - startTime, dt);
      render();
      if (!document.hidden) raf = requestAnimationFrame(loop);
    };

    const renderFrozenFrame = () => {
      // one deterministic settle pass at the PEAK_EXHALE phase (fill targets
      // fully converged, no easing lag left) so the freeze doesn't land
      // mid-ease from whatever partial fill mount happened to start at
      for (let i = 0; i < 40; i++) step(REDUCED_FREEZE_T, FILL_TAU);
      render();
    };

    const onVis = () => {
      if (!document.hidden && !reduced && ready) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    let resizeTimer: ReturnType<typeof setTimeout> | null = null;
    const onResize = () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        resize();
        if (reduced && ready) renderFrozenFrame();
      }, 150);
    };

    const mo = new MutationObserver(() => {
      readTokens();
      if (ready) {
        if (reduced) renderFrozenFrame();
        else render();
      }
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });

    let ro: ResizeObserver | undefined;
    let io: IntersectionObserver | undefined;
    let visible = true;

    readTokens();
    document.fonts.ready.then(() => {
      if (disposed) return;
      resize();
      ready = true;
      if (reduced) {
        renderFrozenFrame();
      } else {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
      ro = new ResizeObserver(onResize);
      ro.observe(root);
      if (!reduced) {
        io = new IntersectionObserver(
          (entries) => {
            const entry = entries[0];
            if (!entry) return;
            visible = entry.isIntersecting;
            if (visible && !raf) {
              last = 0;
              raf = requestAnimationFrame(loop);
            } else if (!visible && raf) {
              cancelAnimationFrame(raf);
              raf = 0;
            }
          },
          { threshold: 0 },
        );
        io.observe(root);
      }
    });

    if (!reduced) document.addEventListener("visibilitychange", onVis);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      raf = 0;
      if (resizeTimer) clearTimeout(resizeTimer);
      ro?.disconnect();
      io?.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [disabled]);

  return (
    <div
      ref={rootRef}
      className={`relative flex h-full w-full flex-col overflow-hidden bg-background ${className}`}
      style={style}
    >
      {!disabled ? (
        <canvas
          ref={canvasRef}
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 block h-full w-full"
        />
      ) : null}
      {children ? <div className="relative z-10 flex h-full w-full flex-col">{children}</div> : null}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// deterministic 2-octave value noise — no deps, stable across frames
// ---------------------------------------------------------------------------
function hash2(x: number, y: number) {
  const n = Math.sin(x * 127.1 + y * 311.7) * 43758.5453123;
  return n - Math.floor(n);
}
function vnoise(x: number, y: number) {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const xf = x - xi;
  const yf = y - yi;
  const u = xf * xf * (3 - 2 * xf);
  const v = yf * yf * (3 - 2 * yf);
  const a = hash2(xi, yi);
  const b = hash2(xi + 1, yi);
  const c = hash2(xi, yi + 1);
  const d = hash2(xi + 1, yi + 1);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}
function noise2(x: number, y: number) {
  return 0.65 * vnoise(x, y) + 0.35 * vnoise(x * 2.1 + 19.7, y * 2.1 + 7.3);
}

// ---------------------------------------------------------------------------
// ErosionTrail — the cursor is a river. Dragging across a live topographic
// map carves a channel into a 96x96 heightfield (base noise − carve delta);
// marching-squares isolines reflow per frame into canyon walls around the
// path, with a faint waterline while carving. Release and sediment heals the
// field back (exponential decay, tau ≈ 2.2s). Canvas 2D, refs only — the rAF
// loop is the sole writer and sleeps once the field has healed.
// ---------------------------------------------------------------------------
export function ErosionTrail({
  gridSize = 96,
  contourStep = 0.08,
  brushSigma = 28,
  carveRate = 0.9,
  healTau = 2.2,
  showReadout = true,
  className = "h-96",
  "aria-label": ariaLabel = "Topographic map — drag to carve a river channel",
}: {
  /** heightfield resolution per axis (nodes) */
  gridSize?: number;
  /** elevation gap between isolines; every 5th index line renders brighter */
  contourStep?: number;
  /** gaussian carve-brush radius (sigma) in screen px */
  brushSigma?: number;
  /** carve rate in elevation units per second at full depth */
  carveRate?: number;
  /** healing time constant in seconds (95% healed ≈ 3·tau) */
  healTau?: number;
  /** font-mono corner readout of cursor grid coords */
  showReadout?: boolean;
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** accessible name for the terrain */
  "aria-label"?: string;
}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const readoutRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    if (!root || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;

    const N = Math.max(8, Math.floor(gridSize));
    const NN = N * N;
    const base = new Float32Array(NN);
    const delta = new Float32Array(NN); // positive carve depth per node
    const field = new Float32Array(NN); // base − delta, rebuilt per frame
    const freq = 3.4 / (N - 1); // ~3.4 noise features across the sheet
    for (let gy = 0; gy < N; gy++) {
      for (let gx = 0; gx < N; gx++) {
        base[gy * N + gx] = noise2(gx * freq + 11.8, gy * freq + 5.2);
      }
    }

    // ambient drift — a static per-node phase map; sampling sin(phase − t·speed)
    // reads as slow traveling ripples through the contours, alive at rest
    const driftFreq = 0.9 / (N - 1);
    const driftPhase = new Float32Array(NN);
    for (let gy = 0; gy < N; gy++) {
      for (let gx = 0; gx < N; gx++) {
        driftPhase[gy * N + gx] =
          noise2(gx * driftFreq + 41.3, gy * driftFreq + 27.6) * Math.PI * 2;
      }
    }
    const ambientAmp = contourStep * 0.42;
    const driftSpeed = (Math.PI * 2) / 10; // one full drift cycle ≈ 10s

    let w = 0;
    let h = 0;
    let dpr = 1;
    let cellW = 1;
    let cellH = 1;
    const resize = () => {
      const rect = root.getBoundingClientRect();
      w = rect.width;
      h = rect.height;
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.max(1, Math.round(w * dpr));
      canvas.height = Math.max(1, Math.round(h * dpr));
      cellW = w / (N - 1);
      cellH = h / (N - 1);
    };
    resize();

    // hot-path state — locals only, never React state
    let raf = 0;
    let last = 0;
    let elapsed = 0;
    let visible = true;
    let down = false;
    let rawX = 0;
    let rawY = 0;
    let sx = 0; // velocity-smoothed trail head (lerp 0.25/sample)
    let sy = 0;
    let lastSx = 0;
    let lastSy = 0;
    const TRAIL_MAX = 10;
    const trailX = new Float32Array(TRAIL_MAX);
    const trailY = new Float32Array(TRAIL_MAX);
    let trailLen = 0;

    // ambient sediment — a handful of specks trickling downhill along the
    // static base gradient, independent of drag; the idle "alive" layer.
    // Skipped entirely under reduced motion (arrays stay zero-length).
    const P = reduced ? 0 : 42;
    const partX = new Float32Array(P);
    const partY = new Float32Array(P);
    const partAge = new Float32Array(P);
    const partLife = new Float32Array(P);
    const spawnParticle = (i: number) => {
      partX[i] = Math.random() * w;
      partY[i] = Math.random() * h;
      partAge[i] = 0;
      partLife[i] = 3 + Math.random() * 4;
    };
    for (let i = 0; i < P; i++) spawnParticle(i);

    const updateParticles = (dt: number) => {
      for (let i = 0; i < P; i++) {
        const gx = Math.min(N - 2, Math.max(1, Math.round(partX[i]! / cellW)));
        const gy = Math.min(N - 2, Math.max(1, Math.round(partY[i]! / cellH)));
        const row = gy * N;
        const dHdx = (base[row + gx + 1]! - base[row + gx - 1]!) / (2 * cellW);
        const dHdy = (base[row + N + gx]! - base[row - N + gx]!) / (2 * cellH);
        let vx = -dHdx * 2600;
        let vy = -dHdy * 2600;
        const sp = Math.hypot(vx, vy);
        if (sp > 26) {
          vx = (vx / sp) * 26;
          vy = (vy / sp) * 26;
        } else if (sp < 4) {
          // near-flat ground — a slow noise-driven nudge so it never stalls
          const a =
            noise2(partX[i]! * 0.01, partY[i]! * 0.01 + elapsed * 0.15) *
            Math.PI *
            2;
          vx = Math.cos(a) * 6;
          vy = Math.sin(a) * 6;
        }
        partX[i]! += vx * dt;
        partY[i]! += vy * dt;
        partAge[i]! += dt;
        if (
          partAge[i]! > partLife[i]! ||
          partX[i]! < 0 ||
          partX[i]! > w ||
          partY[i]! < 0 ||
          partY[i]! > h
        ) {
          spawnParticle(i);
        }
      }
    };

    const carveSegment = (dt: number) => {
      const segLen = Math.hypot(sx - lastSx, sy - lastSy);
      const speed = segLen / Math.max(dt, 1e-4); // px/s
      // full depth below 80 px/s, tapering to 0.25x at 400 px/s
      const speedScale =
        speed <= 80
          ? 1
          : speed >= 400
            ? 0.25
            : 1 - 0.75 * ((speed - 80) / 320);
      const total = carveRate * dt * speedScale;
      const stamps = Math.max(1, Math.ceil(segLen / (brushSigma * 0.5)));
      const dep = total / stamps;
      const reach = brushSigma * 3;
      const inv2s2 = 1 / (2 * brushSigma * brushSigma);
      for (let s = 0; s < stamps; s++) {
        const f = stamps === 1 ? 1 : s / (stamps - 1);
        const px = lastSx + (sx - lastSx) * f;
        const py = lastSy + (sy - lastSy) * f;
        const gx0 = Math.max(0, Math.floor((px - reach) / cellW));
        const gx1 = Math.min(N - 1, Math.ceil((px + reach) / cellW));
        const gy0 = Math.max(0, Math.floor((py - reach) / cellH));
        const gy1 = Math.min(N - 1, Math.ceil((py + reach) / cellH));
        for (let gy = gy0; gy <= gy1; gy++) {
          const dy = gy * cellH - py;
          const row = gy * N;
          for (let gx = gx0; gx <= gx1; gx++) {
            const dx = gx * cellW - px;
            const wgt = Math.exp(-(dx * dx + dy * dy) * inv2s2);
            if (wgt < 0.01) continue;
            const v = delta[row + gx]! + dep * wgt;
            delta[row + gx] = v > 1 ? 1 : v;
          }
        }
      }
      // record the trail head for the waterline proximity test
      if (trailLen < TRAIL_MAX) {
        trailX[trailLen] = sx;
        trailY[trailLen] = sy;
        trailLen++;
      } else {
        for (let i = 1; i < TRAIL_MAX; i++) {
          trailX[i - 1] = trailX[i]!;
          trailY[i - 1] = trailY[i]!;
        }
        trailX[TRAIL_MAX - 1] = sx;
        trailY[TRAIL_MAX - 1] = sy;
      }
    };

    const draw = () => {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);

      let minH = Infinity;
      let maxH = -Infinity;
      for (let i = 0; i < NN; i++) {
        const v =
          base[i]! -
          delta[i]! +
          ambientAmp * Math.sin(driftPhase[i]! - elapsed * driftSpeed);
        field[i] = v;
        if (v < minH) minH = v;
        if (v > maxH) maxH = v;
      }

      // waterline: carved cells near the active trail, pointer down only —
      // the single accent, earned by interaction
      if (down && trailLen > 0) {
        let bx0 = Infinity;
        let bx1 = -Infinity;
        let by0 = Infinity;
        let by1 = -Infinity;
        for (let i = 0; i < trailLen; i++) {
          const tx = trailX[i]!;
          const ty = trailY[i]!;
          if (tx < bx0) bx0 = tx;
          if (tx > bx1) bx1 = tx;
          if (ty < by0) by0 = ty;
          if (ty > by1) by1 = ty;
        }
        const R = 40;
        const R2 = R * R;
        const gx0 = Math.max(0, Math.floor((bx0 - R) / cellW));
        const gx1 = Math.min(N - 1, Math.ceil((bx1 + R) / cellW));
        const gy0 = Math.max(0, Math.floor((by0 - R) / cellH));
        const gy1 = Math.min(N - 1, Math.ceil((by1 + R) / cellH));
        ctx.fillStyle = "rgba(0,107,255,0.35)";
        for (let gy = gy0; gy <= gy1; gy++) {
          const ny = gy * cellH;
          const row = gy * N;
          for (let gx = gx0; gx <= gx1; gx++) {
            if (delta[row + gx]! <= 0.12) continue;
            const nx = gx * cellW;
            let near = false;
            for (let i = 0; i < trailLen; i++) {
              const dx = nx - trailX[i]!;
              const dy = ny - trailY[i]!;
              if (dx * dx + dy * dy < R2) {
                near = true;
                break;
              }
            }
            if (near) {
              ctx.fillRect(nx - cellW / 2, ny - cellH / 2, cellW + 1, cellH + 1);
            }
          }
        }
      }

      // marching squares on the coarse grid, one level per contourStep;
      // batched into two paths — hairline minors, every 5th index major
      const minor = new Path2D();
      const major = new Path2D();
      const kMin = Math.ceil(minH / contourStep);
      const kMax = Math.floor(maxH / contourStep);
      for (let k = kMin; k <= kMax; k++) {
        const t = k * contourStep;
        const path = k % 5 === 0 ? major : minor;
        for (let gy = 0; gy < N - 1; gy++) {
          const rowA = gy * N;
          const rowB = rowA + N;
          const y0 = gy * cellH;
          const y1 = y0 + cellH;
          for (let gx = 0; gx < N - 1; gx++) {
            const a = field[rowA + gx]!;
            const b = field[rowA + gx + 1]!;
            const c = field[rowB + gx + 1]!;
            const d = field[rowB + gx]!;
            const code =
              (a > t ? 8 : 0) | (b > t ? 4 : 0) | (c > t ? 2 : 0) | (d > t ? 1 : 0);
            if (code === 0 || code === 15) continue;
            const x0 = gx * cellW;
            const x1 = x0 + cellW;
            // lazily interpolated edge crossings (only for crossed edges)
            const topX = () => x0 + (cellW * (t - a)) / (b - a);
            const rightY = () => y0 + (cellH * (t - b)) / (c - b);
            const botX = () => x0 + (cellW * (t - d)) / (c - d);
            const leftY = () => y0 + (cellH * (t - a)) / (d - a);
            switch (code) {
              case 1:
              case 14:
                path.moveTo(x0, leftY());
                path.lineTo(botX(), y1);
                break;
              case 2:
              case 13:
                path.moveTo(botX(), y1);
                path.lineTo(x1, rightY());
                break;
              case 3:
              case 12:
                path.moveTo(x0, leftY());
                path.lineTo(x1, rightY());
                break;
              case 4:
              case 11:
                path.moveTo(topX(), y0);
                path.lineTo(x1, rightY());
                break;
              case 5:
                path.moveTo(topX(), y0);
                path.lineTo(x1, rightY());
                path.moveTo(x0, leftY());
                path.lineTo(botX(), y1);
                break;
              case 6:
              case 9:
                path.moveTo(topX(), y0);
                path.lineTo(botX(), y1);
                break;
              case 7:
              case 8:
                path.moveTo(topX(), y0);
                path.lineTo(x0, leftY());
                break;
              case 10:
                path.moveTo(topX(), y0);
                path.lineTo(x0, leftY());
                path.moveTo(botX(), y1);
                path.lineTo(x1, rightY());
                break;
            }
          }
        }
      }
      ctx.lineJoin = "round";
      ctx.strokeStyle = "#2e2e2e";
      ctx.lineWidth = 0.75;
      ctx.stroke(minor);
      ctx.strokeStyle = "#8f8f8f";
      ctx.lineWidth = 1;
      ctx.stroke(major);

      // ambient sediment specks — soft in/out fade over their lifespan
      if (P > 0) {
        ctx.fillStyle = "#8f8f8f";
        for (let i = 0; i < P; i++) {
          const life = partLife[i]!;
          const age = partAge[i]!;
          const fadeIn = Math.min(1, age / 0.6);
          const fadeOut = Math.min(1, (life - age) / 0.6);
          const alpha = Math.max(0, Math.min(fadeIn, fadeOut)) * 0.5;
          if (alpha <= 0.01) continue;
          ctx.globalAlpha = alpha;
          ctx.beginPath();
          ctx.arc(partX[i]!, partY[i]!, 1.4, 0, Math.PI * 2);
          ctx.fill();
        }
        ctx.globalAlpha = 1;
      }
    };

    const loop = (now: number) => {
      const dt = last === 0 ? 1 / 60 : Math.min(0.05, (now - last) / 1000);
      last = now;
      elapsed += dt;

      if (down) {
        // velocity-smoothed trail head prevents scalloping
        sx += (rawX - sx) * 0.25;
        sy += (rawY - sy) * 0.25;
        carveSegment(dt);
        lastSx = sx;
        lastSy = sy;
      }

      // sediment heals: per-node exponential decay of the carve delta
      let maxDelta = 0;
      const decay = Math.exp(-dt / healTau);
      for (let i = 0; i < NN; i++) {
        const v = delta[i]! * decay;
        delta[i] = v;
        if (v > maxDelta) maxDelta = v;
      }
      if (!down && maxDelta <= 0.002) delta.fill(0);

      updateParticles(dt);
      draw();

      // ambient drift + sediment keep this looping while visible — it only
      // sleeps once scrolled offscreen or under reduced motion (never enters)
      if (visible) {
        raf = requestAnimationFrame(loop);
      } else {
        raf = 0;
        last = 0;
      }
    };

    const wake = () => {
      if (reduced) return;
      if (!raf) {
        last = 0;
        raf = requestAnimationFrame(loop);
      }
    };

    const updateReadout = (x: number, y: number) => {
      const el = readoutRef.current;
      if (!el) return;
      const gx = Math.min(N - 1, Math.max(0, Math.round(x / cellW)));
      const gy = Math.min(N - 1, Math.max(0, Math.round(y / cellH)));
      el.textContent = `GRID ${String(gx).padStart(2, "0")}·${String(gy).padStart(2, "0")}`;
    };
    const clearReadout = () => {
      const el = readoutRef.current;
      if (el) el.textContent = "GRID --·--";
    };

    const toLocal = (e: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      rawX = e.clientX - rect.left;
      rawY = e.clientY - rect.top;
    };

    const onDown = (e: PointerEvent) => {
      if (reduced) return;
      toLocal(e);
      root.setPointerCapture(e.pointerId);
      down = true;
      sx = rawX;
      sy = rawY;
      lastSx = rawX;
      lastSy = rawY;
      trailLen = 0;
      updateReadout(rawX, rawY);
      wake();
    };
    const onMove = (e: PointerEvent) => {
      toLocal(e);
      updateReadout(rawX, rawY);
    };
    const endDrag = () => {
      down = false;
      trailLen = 0;
    };
    const onUp = () => endDrag();
    const onLeave = () => {
      clearReadout();
    };

    const ro = new ResizeObserver(() => {
      resize();
      draw();
    });
    ro.observe(root);

    // ambient motion pauses off-screen — the loop is the only thing that
    // should ever spin while nothing is looking at it
    const io = reduced
      ? null
      : new IntersectionObserver(
          (entries) => {
            const entry = entries[0];
            if (!entry) return;
            visible = entry.isIntersecting;
            if (visible) {
              wake();
            } else if (raf) {
              cancelAnimationFrame(raf);
              raf = 0;
              last = 0;
            }
          },
          { threshold: 0 }
        );
    if (io) io.observe(root);

    root.addEventListener("pointermove", onMove);
    root.addEventListener("pointerleave", onLeave);
    if (!reduced) {
      root.addEventListener("pointerdown", onDown);
      root.addEventListener("pointerup", onUp);
      root.addEventListener("pointercancel", onUp);
      root.addEventListener("lostpointercapture", onUp);
    }

    // reduced motion renders once and stays put — a real static fallback;
    // otherwise the ambient loop starts immediately, alive before any input
    if (reduced) {
      draw();
    } else {
      wake();
    }

    return () => {
      cancelAnimationFrame(raf);
      raf = 0;
      ro.disconnect();
      if (io) io.disconnect();
      root.removeEventListener("pointermove", onMove);
      root.removeEventListener("pointerleave", onLeave);
      if (!reduced) {
        root.removeEventListener("pointerdown", onDown);
        root.removeEventListener("pointerup", onUp);
        root.removeEventListener("pointercancel", onUp);
        root.removeEventListener("lostpointercapture", onUp);
      }
    };
  }, [gridSize, contourStep, brushSigma, carveRate, healTau]);

  return (
    <div
      ref={rootRef}
      role="img"
      aria-label={ariaLabel}
      className={`relative w-full cursor-crosshair touch-none select-none overflow-hidden ${className}`}
    >
      <canvas
        ref={canvasRef}
        aria-hidden
        className="absolute inset-0 h-full w-full"
      />
      {showReadout && (
        <div
          ref={readoutRef}
          aria-hidden
          className="pointer-events-none absolute right-3 top-3 font-mono text-[10px] tracking-widest text-ns-muted"
        >
          GRID --·--
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";

// ---------------------------------------------------------------------------
// AsciiCascadeText — a showpiece where a headline collapses character by
// character into a scattered glyph field below it, then reassembles. This is
// a different axis of motion from text-decrypt (identity churns IN PLACE,
// positions never move) and from split-flap/counter-carry-ripple (a hinge or
// a 2-state vertical flip on a fixed grid): here every character is a free
// body that falls, drifts and fades into a field of noise glyphs, then climbs
// back to its exact slot with a staggered reassemble. The cycle runs
// ambiently forever at a slow, low-amplitude "breathe"; hovering immediately
// interrupts it with a full, high-amplitude cascade for as long as the
// pointer stays over it, so hover and rest are never the same frame. Pure
// direct-DOM rAF per character (translate3d + opacity on refs) — no React
// state on the hot path, monospace charset so no cell ever changes width.
// ---------------------------------------------------------------------------

const NOISE_CHARSET = "#%&@*+=-:.░▒▓";

type Phase = "settled" | "falling" | "field" | "reforming";

interface CharState {
  el: HTMLSpanElement | null;
  homeX: number;
  homeY: number;
  x: number;
  y: number;
  vy: number;
  dx: number; // per-character horizontal drift target while in the field
  opacity: number;
  glyph: string;
  target: string;
}

export interface AsciiCascadeTextProps {
  /** the rendered text */
  text: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

function pick(charset: string) {
  return charset[Math.floor(Math.random() * charset.length)] ?? "#";
}

export function AsciiCascadeText({ text, className = "" }: AsciiCascadeTextProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const charsStateRef = useRef<CharState[]>([]);
  const [reduced, setReduced] = useState(false);
  const hoverRef = useRef(false);

  const glyphs = useMemo(() => Array.from(text), [text]);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const onChange = () => setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  useEffect(() => {
    const container = containerRef.current;
    if (!container || reduced) return;

    const states = charsStateRef.current;

    const measureHomes = () => {
      const rect = container.getBoundingClientRect();
      for (const s of states) {
        if (!s.el) continue;
        const box = s.el.getBoundingClientRect();
        s.homeX = box.left - rect.left;
        s.homeY = box.top - rect.top;
        if (s.x === 0 && s.y === 0 && s.opacity === 1) {
          s.x = s.homeX;
          s.y = s.homeY;
        }
      }
    };
    measureHomes();

    let raf = 0;
    let last = 0;
    let phase: Phase = "settled";
    let phaseStart = performance.now();
    let visible = true;

    const FIELD_DROP = 46; // low-amplitude ambient fall, px
    const FIELD_DROP_HOVER = 96; // amplified fall while hovered

    const HOLD_MS = 2600;
    const FALL_MS = 620;
    const DWELL_MS = 520;
    const REFORM_MS = 720;

    const startFall = (now: number) => {
      phase = "falling";
      phaseStart = now;
      for (const s of states) {
        s.dx = (Math.random() - 0.5) * 18;
        s.vy = 0;
      }
    };

    const loop = (now: number) => {
      const dt = last ? Math.min(0.05, (now - last) / 1000) : 1 / 60;
      last = now;
      const hovering = hoverRef.current;
      const drop = hovering ? FIELD_DROP_HOVER : FIELD_DROP;
      const elapsed = now - phaseStart;

      if (phase === "settled" && elapsed > (hovering ? 0 : HOLD_MS)) {
        startFall(now);
      } else if (phase === "falling") {
        const p = Math.min(1, elapsed / FALL_MS);
        const eased = 1 - Math.pow(1 - p, 3);
        for (const s of states) {
          s.x = s.homeX + s.dx * eased;
          s.y = s.homeY + drop * eased;
          s.opacity = 1 - 0.72 * eased;
          if (Math.random() < 0.35) s.glyph = pick(NOISE_CHARSET);
        }
        if (p >= 1) {
          phase = "field";
          phaseStart = now;
        }
      } else if (phase === "field") {
        for (const s of states) {
          if (Math.random() < 0.18) s.glyph = pick(NOISE_CHARSET);
        }
        if (elapsed > (hovering ? DWELL_MS * 0.4 : DWELL_MS)) {
          phase = "reforming";
          phaseStart = now;
        }
      } else if (phase === "reforming") {
        const p = Math.min(1, elapsed / REFORM_MS);
        for (let i = 0; i < states.length; i++) {
          const s = states[i]!;
          const stagger = Math.min(0.35, i * 0.02);
          const local = Math.max(0, Math.min(1, (p - stagger) / (1 - stagger)));
          const eased = 1 - Math.pow(1 - local, 3);
          // lerp from the field's scattered offset back to the char's home slot
          s.x = s.homeX + s.dx * (1 - eased);
          s.y = s.homeY + drop * (1 - eased);
          s.opacity = 0.28 + 0.72 * eased;
          if (local < 1 && Math.random() < 0.25) s.glyph = pick(NOISE_CHARSET);
          else if (local >= 1) s.glyph = s.target;
        }
        if (p >= 1) {
          for (const s of states) {
            s.x = s.homeX;
            s.y = s.homeY;
            s.opacity = 1;
            s.glyph = s.target;
          }
          phase = "settled";
          phaseStart = now;
        }
      }

      for (const s of states) {
        if (!s.el) continue;
        s.el.style.transform = `translate3d(${(s.x - s.homeX).toFixed(2)}px, ${(s.y - s.homeY).toFixed(2)}px, 0)`;
        s.el.style.opacity = String(s.opacity);
        s.el.textContent = s.glyph;
        // the further a char has fallen from home, the more accent bleeds in —
        // a loud, colour-coded readout of "how far into the field" it is
        const strayed = Math.min(1, (1 - s.opacity) / 0.72);
        s.el.style.color = `color-mix(in oklab, var(--ns-accent) ${Math.round(strayed * 70)}%, var(--foreground))`;
      }

      if (visible && !document.hidden) raf = requestAnimationFrame(loop);
    };
    raf = requestAnimationFrame(loop);

    const ro = new ResizeObserver(measureHomes);
    ro.observe(container);
    const io = new IntersectionObserver((entries) => {
      visible = entries[0]?.isIntersecting ?? true;
    });
    io.observe(container);
    const onVis = () => {
      if (!document.hidden && !raf) raf = requestAnimationFrame(loop);
    };
    document.addEventListener("visibilitychange", onVis);

    const onEnter = () => {
      hoverRef.current = true;
    };
    const onLeave = () => {
      hoverRef.current = false;
    };
    container.addEventListener("pointerenter", onEnter);
    container.addEventListener("pointerleave", onLeave);

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      io.disconnect();
      document.removeEventListener("visibilitychange", onVis);
      container.removeEventListener("pointerenter", onEnter);
      container.removeEventListener("pointerleave", onLeave);
    };
  }, [glyphs, reduced]);

  return (
    <div
      ref={containerRef}
      className={`relative inline-block whitespace-pre-wrap font-mono font-semibold text-foreground ${className}`}
    >
      <span aria-label={text} role="text">
        {glyphs.map((g, i) => (
          <span
            key={i}
            aria-hidden
            ref={(el) => {
              if (!charsStateRef.current[i]) {
                charsStateRef.current[i] = {
                  el: null,
                  homeX: 0,
                  homeY: 0,
                  x: 0,
                  y: 0,
                  vy: 0,
                  dx: 0,
                  opacity: 1,
                  glyph: g,
                  target: g,
                };
              }
              charsStateRef.current[i]!.el = el;
              charsStateRef.current[i]!.target = g;
            }}
            className="relative inline-block will-change-transform"
          >
            {g}
          </span>
        ))}
      </span>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

// A frosted prism strip rides the cursor across a headline. Text behind the
// strip magnifies about the strip center and tears into offset RGB channel
// slices (screen-blended clones) proportional to drag velocity — light
// through cut glass, spatial and physical, not a global hover filter. Each
// glyph snaps back with spring overshoot as the strip clears it. Manual
// spring integrator on a direct-DOM rAF loop; no React state on the hot
// path; the loop sleeps when settled.
export function PrismDragSplit({
  text = "REFRACTION",
  stripWidth = 120,
  stiffness = 300,
  damping = 24,
  mass = 1,
  dispersionGain = 0.018,
  maxDispersion = 14,
  magnify = 1.06,
  className = "",
}: {
  /** the rendered text */
  text?: string;
  /** prism strip width in px */
  stripWidth?: number;
  /** spring stiffness (N/m-ish, px units) */
  stiffness?: number;
  /** spring damping coefficient */
  damping?: number;
  /** spring mass */
  mass?: number;
  /** px of red-channel offset per px/s of strip velocity */
  dispersionGain?: number;
  /** channel offset clamp in px */
  maxDispersion?: number;
  /** scale of the refracted clones inside the strip */
  magnify?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}) {
  const containerRef = useRef<HTMLDivElement>(null);
  const stripRef = useRef<HTMLDivElement>(null);
  const baseRef = useRef<HTMLSpanElement>(null);
  const redRef = useRef<HTMLDivElement>(null);
  const greenRef = useRef<HTMLDivElement>(null);
  const blueRef = useRef<HTMLDivElement>(null);
  const charRefs = useRef<(HTMLSpanElement | null)[]>([]);

  const glyphs = Array.from(text);

  useEffect(() => {
    const container = containerRef.current;
    const strip = stripRef.current;
    const base = baseRef.current;
    const red = redRef.current;
    const green = greenRef.current;
    const blue = blueRef.current;
    if (!container || !strip || !base || !red || !green || !blue) return;

    const chars = charRefs.current
      .slice(0, Array.from(text).length)
      .filter((el): el is HTMLSpanElement => el !== null);
    const channels: [HTMLDivElement, number][] = [
      [red, 1],
      [green, 0],
      [blue, -1],
    ];

    let width = 0;
    let baseX = 0;
    let centers: number[] = [];

    // untransformed offsets — clones are pinned to the base headline's box so
    // the counter-translate keeps glyphs registered regardless of padding
    const measure = () => {
      width = container.offsetWidth;
      baseX = base.offsetLeft;
      const baseY = base.offsetTop;
      centers = chars.map((el) => el.offsetLeft + el.offsetWidth / 2);
      for (const [el] of channels) {
        el.style.left = `${baseX}px`;
        el.style.top = `${baseY}px`;
      }
    };

    // strip at x; clones counter-translated by -x and scaled about the strip
    // center so the glyph under the center stays registered while neighbors
    // bulge outward — a lens, not a sticker
    const apply = (x: number, dx: number) => {
      strip.style.transform = `translate3d(${x}px,0,0)`;
      const origin = `${x + stripWidth / 2 - baseX}px 50%`;
      for (const [el, sign] of channels) {
        el.style.transform = `translateX(${-x + dx * sign}px) scale(${magnify})`;
        el.style.transformOrigin = origin;
      }
    };

    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      // no rAF: strip pinned at 38% with fixed channel offsets — the frozen
      // dispersion still reads as the concept
      const place = () => {
        measure();
        apply(width * 0.38, 6);
      };
      place();
      const ro = new ResizeObserver(place);
      ro.observe(container);
      return () => ro.disconnect();
    }

    measure();
    let x = width / 2 - stripWidth / 2;
    let v = 0;
    let target = x;
    let raf = 0;
    let last = 0;
    let covered = centers.map((c) => c > x && c < x + stripWidth);
    apply(x, 0);

    const loop = (now: number) => {
      const dt = Math.min(0.032, Math.max(0.001, (now - last) / 1000));
      last = now;
      // semi-implicit Euler spring integrator
      const accel = (stiffness * (target - x) - damping * v) / mass;
      v += accel * dt;
      x += v * dt;
      // velocity-proportional dispersion: stationary = converged near-white,
      // dragging tears the channels apart
      const dx = Math.max(-maxDispersion, Math.min(maxDispersion, v * dispersionGain));

      // glyph snap-back the instant the strip clears a char center
      for (let i = 0; i < centers.length; i++) {
        const inside = centers[i] > x && centers[i] < x + stripWidth;
        if (covered[i] && !inside) {
          const el = chars[i];
          el.style.setProperty("--nsui-psd-dx", `${v >= 0 ? 6 : -6}px`);
          el.classList.remove("nsui-psd-snap");
          void el.offsetWidth; // restart the overshoot animation
          el.classList.add("nsui-psd-snap");
        }
        covered[i] = inside;
      }

      if (Math.abs(v) < 2 && Math.abs(target - x) < 0.25) {
        x = target;
        v = 0;
        apply(x, 0);
        raf = 0; // sleep
      } else {
        apply(x, dx);
        raf = requestAnimationFrame(loop);
      }
    };

    const wake = () => {
      if (!raf) {
        last = performance.now();
        raf = requestAnimationFrame(loop);
      }
    };
    const clampTarget = (t: number) =>
      Math.min(width - stripWidth / 2, Math.max(-stripWidth / 2, t));

    const onMove = (e: PointerEvent) => {
      const left = container.getBoundingClientRect().left;
      target = clampTarget(e.clientX - left - stripWidth / 2);
      wake();
    };
    const onLeave = () => {
      target = width / 2 - stripWidth / 2; // spring back to center rest
      wake();
    };
    const ro = new ResizeObserver(() => {
      measure();
      target = clampTarget(target);
      covered = centers.map((c) => c > x && c < x + stripWidth);
      apply(x, 0);
    });

    ro.observe(container);
    container.addEventListener("pointermove", onMove);
    container.addEventListener("pointerleave", onLeave);
    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      container.removeEventListener("pointermove", onMove);
      container.removeEventListener("pointerleave", onLeave);
    };
  }, [text, stripWidth, stiffness, damping, mass, dispersionGain, maxDispersion, magnify]);

  return (
    <div
      ref={containerRef}
      className={`relative inline-block cursor-ew-resize touch-none select-none font-sans font-semibold text-foreground ${className}`}
      // kerning/ligatures off so the per-char base and the continuous-text
      // clones produce byte-identical layout — registration depends on it
      style={{
        fontKerning: "none",
        fontVariantLigatures: "none",
        fontFeatureSettings: '"liga" 0, "kern" 0',
      }}
    >
      <style>{`@keyframes nsui-psd-snap{from{transform:translateX(var(--nsui-psd-dx,6px))}to{transform:translateX(0)}}.nsui-psd-snap{animation:nsui-psd-snap 350ms cubic-bezier(0.34,1.56,0.64,1)}`}</style>

      {/* base headline, split per-char for the snap-back */}
      <span ref={baseRef} aria-label={text} role="text" className="whitespace-pre">
        {glyphs.map((g, i) => (
          <span
            key={i}
            aria-hidden
            ref={(el) => {
              charRefs.current[i] = el;
            }}
            className="inline-block will-change-transform"
          >
            {g === " " ? " " : g}
          </span>
        ))}
      </span>

      {/* prism strip: frosted slab that occludes the base beneath it */}
      <div
        ref={stripRef}
        aria-hidden
        className="pointer-events-none absolute inset-y-0 left-0 isolate overflow-hidden border-x border-black/10 dark:border-white/10 bg-background/85 backdrop-blur-md will-change-transform shadow-[inset_0_1px_0_0_rgba(0,0,0,0.06),inset_0_-1px_0_0_rgba(0,0,0,0.03),0_8px_24px_-8px_rgba(0,0,0,0.25)] dark:shadow-[inset_0_1px_0_0_rgba(255,255,255,0.12),inset_0_-1px_0_0_rgba(255,255,255,0.06),0_8px_24px_-8px_rgba(0,0,0,0.5)]"
        style={{ width: stripWidth }}
      >
        {/* refracted content, edge-faded so glyphs melt in instead of hard-clipping.
            Forced dark tint (not theme-token-driven) so the mix-blend-screen RGB
            clones always pop against a near-black backdrop — screen blending
            against a near-white light-mode background would wash channel text
            out to invisible. */}
        <div className="absolute inset-0 bg-[#0a0a0a]/90 [mask-image:linear-gradient(to_right,transparent,black_12px,black_calc(100%-12px),transparent)]">
          {(
            [
              [redRef, "#ff0000"],
              [greenRef, "#00ff00"],
              [blueRef, "#0000ff"],
            ] as const
          ).map(([ref, color]) => (
            <div
              key={color}
              ref={ref}
              className="absolute left-0 top-0 whitespace-pre mix-blend-screen will-change-transform"
              style={{ color }}
            >
              {text.replace(/ /g, " ")}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type MouseEvent as ReactMouseEvent,
  type PointerEvent as ReactPointerEvent,
} from "react";

// ---------------------------------------------------------------------------
// StitchPick — a headline rendered as running-stitch embroidery that a
// passing cursor (a seam ripper) picks loose, letter by letter. Each glyph is
// two offset, dashed, fill:none SVG <text> strokes (thread texture, subtle
// two-tone shimmer via a second stroke color at low opacity) laid out on a
// monospace grid so per-letter hit zones are trivial index math, no DOM
// measurement of proportional glyph widths.
//
// Per-letter state machine, entirely local to that letter:
//   stitched  -> pointer enters its zone -> picked (thread detaches, dangles
//                on a 4-point verlet chain: gravity + a little sway, driven
//                by a shared rAF loop, direct SVG attribute writes on a path
//                ref — no React state on the physics hot path).
//   picked    -> pointer leaves before the dwell threshold -> stitched again
//                (retracts: the dangling thread fades, the dash redraws).
//             -> dwell threshold elapses while still hovered -> unraveled
//                (thread fully detaches into a static loose pile at the
//                glyph's baseline; physics stops, the pile just sits there).
//   unraveled -> click that letter, or the always-present "Re-sew" button
//                (which resews every unraveled letter at once) -> stitched,
//                dash redraws with a short per-letter delayed stagger so it
//                reads as sewn back in order rather than snapping at once.
//
// A single onPointerMove/onPointerLeave/onClick on the SVG root does the hit
// testing (glyph index = floor(localX / advance)) rather than per-glyph DOM
// listeners. Reduced motion skips the whole state machine: hover just
// brightens that letter's thread stroke opacity, instantly, no dangling,
// no pile.
// ---------------------------------------------------------------------------

type LetterState = "stitched" | "picked" | "unraveled";

export interface StitchPickProps {
  /** the rendered text */
  text?: string;
  /** Glyph font size in px. Default 56. */
  size?: number;
  /** Hover dwell before a picked letter fully unravels into a pile, ms. Default 650. */
  dwellMs?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const POINTS = 4;
const GRAVITY = 0.055;
const DAMPING = 0.96;
const SEGMENT = 4.2;
const CONSTRAINT_ITERS = 3;

interface ThreadSim {
  x: number[];
  y: number[];
  px: number[];
  py: number[];
  anchorX: number;
  anchorY: number;
  seed: number;
}

function makeSim(anchorX: number, anchorY: number, seed: number): ThreadSim {
  const x = new Array(POINTS).fill(anchorX);
  const y = new Array(POINTS).fill(anchorY);
  return { x, y, px: [...x], py: [...y], anchorX, anchorY, seed };
}

function stepSim(sim: ThreadSim, t: number) {
  sim.x[0] = sim.anchorX;
  sim.y[0] = sim.anchorY;
  sim.px[0] = sim.anchorX;
  sim.py[0] = sim.anchorY;

  for (let i = 1; i < POINTS; i++) {
    const vx = (sim.x[i] - sim.px[i]) * DAMPING;
    const vy = (sim.y[i] - sim.py[i]) * DAMPING;
    const sway = Math.sin(t * 0.004 + sim.seed + i) * 0.06;
    sim.px[i] = sim.x[i];
    sim.py[i] = sim.y[i];
    sim.x[i] += vx + sway;
    sim.y[i] += vy + GRAVITY;
  }

  for (let iter = 0; iter < CONSTRAINT_ITERS; iter++) {
    for (let i = 1; i < POINTS; i++) {
      const ax = sim.x[i - 1];
      const ay = sim.y[i - 1];
      const dx = sim.x[i] - ax;
      const dy = sim.y[i] - ay;
      const dist = Math.hypot(dx, dy) || 0.0001;
      const diff = (dist - SEGMENT) / dist;
      if (i === 1) {
        sim.x[i] -= dx * diff;
        sim.y[i] -= dy * diff;
      } else {
        sim.x[i] -= dx * diff * 0.5;
        sim.y[i] -= dy * diff * 0.5;
        sim.x[i - 1] += dx * diff * 0.5;
        sim.y[i - 1] += dy * diff * 0.5;
      }
    }
  }
}

function pathFor(sim: ThreadSim): string {
  let d = `M ${sim.x[0].toFixed(1)} ${sim.y[0].toFixed(1)}`;
  for (let i = 1; i < POINTS; i++) d += ` L ${sim.x[i].toFixed(1)} ${sim.y[i].toFixed(1)}`;
  return d;
}

export function StitchPick({ text = "UNRAVEL", size = 56, dwellMs = 650, className = "" }: StitchPickProps) {
  const glyphs = useMemo(() => Array.from(text), [text]);

  const svgRef = useRef<SVGSVGElement | null>(null);
  const measureRef = useRef<SVGTextElement | null>(null);
  const threadPathRefs = useRef<(SVGPathElement | null)[]>([]);
  const reducedRef = useRef(false);

  const [advance, setAdvance] = useState(size * 0.62);
  const [states, setStates] = useState<LetterState[]>(() => glyphs.map(() => "stitched"));
  const statesRef = useRef(states);
  statesRef.current = states;

  const [brightIndex, setBrightIndex] = useState(-1);
  const hoveredRef = useRef(-1);
  const dwellTimers = useRef<Record<number, ReturnType<typeof setTimeout>>>({});
  const sims = useRef<Record<number, ThreadSim>>({});
  // Indices currently animating, tracked independently of `states` — the rAF
  // loop reads this ref directly instead of deriving liveness from
  // statesRef, since a pointermove-triggered setState is not guaranteed to
  // flush before the next animation frame runs.
  const activeRef = useRef<Set<number>>(new Set());
  const rafRef = useRef<number | undefined>(undefined);

  const fontSize = size;
  const height = fontSize * 1.7;
  const baseline = fontSize * 1.05;
  const width = Math.max(1, glyphs.length) * advance;

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    reducedRef.current = mq.matches;
    const onChange = () => {
      reducedRef.current = mq.matches;
    };
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  const measure = useCallback(() => {
    const el = measureRef.current;
    if (!el) return;
    const len = el.getComputedTextLength();
    if (len > 0) setAdvance(len);
  }, []);

  useEffect(() => {
    measure();
    if (typeof document !== "undefined" && "fonts" in document) {
      document.fonts.ready.then(measure).catch(() => {});
    }
  }, [measure, size]);

  const runLoop = useCallback(() => {
    const loop = (t: number) => {
      for (const i of activeRef.current) {
        const sim = sims.current[i];
        if (!sim) continue;
        stepSim(sim, t);
        const el = threadPathRefs.current[i];
        if (el) el.setAttribute("d", pathFor(sim));
      }
      if (activeRef.current.size > 0) {
        rafRef.current = requestAnimationFrame(loop);
      } else {
        rafRef.current = undefined;
      }
    };
    if (rafRef.current === undefined) {
      rafRef.current = requestAnimationFrame(loop);
    }
  }, []);

  useEffect(
    () => () => {
      if (rafRef.current !== undefined) cancelAnimationFrame(rafRef.current);
      Object.values(dwellTimers.current).forEach((id) => clearTimeout(id));
    },
    []
  );

  // Reset per-letter state when the headline text itself changes — states
  // is a fixed-length array seeded once from the initial glyph count, so a
  // later prop change would otherwise leave extra/changed glyphs stuck with
  // no state entry (invisible, inert to hover).
  const lastTextRef = useRef(text);
  useEffect(() => {
    if (lastTextRef.current === text) return;
    lastTextRef.current = text;
    Object.values(dwellTimers.current).forEach((id) => clearTimeout(id));
    dwellTimers.current = {};
    sims.current = {};
    activeRef.current.clear();
    hoveredRef.current = -1;
    setStates(glyphs.map(() => "stitched"));
  }, [text, glyphs]);

  const setLetterState = useCallback((i: number, next: LetterState) => {
    setStates((prev) => {
      if (prev[i] === next) return prev;
      const copy = prev.slice();
      copy[i] = next;
      return copy;
    });
  }, []);

  const enterLetter = useCallback(
    (i: number) => {
      if (i < 0 || i >= glyphs.length || glyphs[i] === " ") return;
      if (statesRef.current[i] !== "stitched") return;
      const anchorX = i * advance + advance / 2;
      const anchorY = baseline + 2;
      sims.current[i] = makeSim(anchorX, anchorY, i * 1.37);
      activeRef.current.add(i);
      setLetterState(i, "picked");
      runLoop();
      clearTimeout(dwellTimers.current[i]);
      dwellTimers.current[i] = setTimeout(() => {
        if (statesRef.current[i] === "picked") {
          activeRef.current.delete(i);
          setLetterState(i, "unraveled");
        }
      }, dwellMs);
    },
    [advance, baseline, dwellMs, glyphs, runLoop, setLetterState]
  );

  const leaveLetter = useCallback(
    (i: number) => {
      if (i < 0 || i >= glyphs.length) return;
      if (statesRef.current[i] === "picked") {
        clearTimeout(dwellTimers.current[i]);
        activeRef.current.delete(i);
        setLetterState(i, "stitched");
      }
    },
    [glyphs.length, setLetterState]
  );

  const indexAt = (clientX: number) => {
    const rect = svgRef.current?.getBoundingClientRect();
    if (!rect || advance <= 0) return -1;
    const idx = Math.floor((clientX - rect.left) / advance);
    return Math.min(glyphs.length - 1, Math.max(0, idx));
  };

  const onPointerMove = (e: ReactPointerEvent<SVGSVGElement>) => {
    const idx = indexAt(e.clientX);
    if (reducedRef.current) {
      if (idx !== brightIndex) setBrightIndex(idx);
      return;
    }
    if (idx === hoveredRef.current) return;
    leaveLetter(hoveredRef.current);
    enterLetter(idx);
    hoveredRef.current = idx;
  };

  const onPointerLeave = () => {
    if (reducedRef.current) {
      setBrightIndex(-1);
      return;
    }
    leaveLetter(hoveredRef.current);
    hoveredRef.current = -1;
  };

  const onClickLetter = (e: ReactMouseEvent<SVGSVGElement>) => {
    const idx = indexAt(e.clientX);
    if (idx >= 0 && statesRef.current[idx] === "unraveled") {
      clearTimeout(dwellTimers.current[idx]);
      setLetterState(idx, "stitched");
    }
  };

  const resewAll = () => {
    Object.values(dwellTimers.current).forEach((id) => clearTimeout(id));
    dwellTimers.current = {};
    setStates((prev) => prev.map(() => "stitched" as LetterState));
  };

  const anyUnraveled = states.some((s) => s === "unraveled");

  return (
    <div className={`inline-flex flex-col items-center gap-4 ${className}`}>
      <style>{CSS}</style>
      <svg
        ref={svgRef}
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        className="ns-stitch-svg select-none"
        role="img"
        aria-label={text}
        onPointerMove={onPointerMove}
        onPointerLeave={onPointerLeave}
        onClick={onClickLetter}
      >
        <text
          ref={measureRef}
          x={-9999}
          y={-9999}
          fontFamily="var(--font-mono)"
          fontSize={fontSize}
          fontWeight={700}
          aria-hidden="true"
        >
          {"M"}
        </text>

        {glyphs.map((ch, i) => {
          const cx = i * advance;
          const state = states[i];
          if (ch === " ") return null;
          const bright = i === brightIndex;
          return (
            <g key={i} data-letter-state={state}>
              <g
                className="ns-stitch-thread"
                style={{
                  opacity: state === "stitched" ? 1 : 0,
                  transitionDelay: state === "stitched" ? `${i * 18}ms` : "0ms",
                }}
              >
                <text
                  x={cx}
                  y={baseline}
                  fontFamily="var(--font-mono)"
                  fontSize={fontSize}
                  fontWeight={700}
                  fill="none"
                  stroke="var(--foreground)"
                  strokeOpacity={bright ? 1 : 0.85}
                  strokeWidth={1.6}
                  strokeDasharray="3 2.4"
                  strokeLinecap="round"
                  aria-hidden="true"
                >
                  {ch}
                </text>
                <text
                  x={cx + 0.6}
                  y={baseline - 0.6}
                  fontFamily="var(--font-mono)"
                  fontSize={fontSize}
                  fontWeight={700}
                  fill="none"
                  stroke="var(--ns-accent)"
                  strokeOpacity={bright ? 0.4 : 0.22}
                  strokeWidth={1}
                  strokeDasharray="3 2.4"
                  strokeLinecap="round"
                  aria-hidden="true"
                >
                  {ch}
                </text>
              </g>

              {state === "picked" && (
                <path
                  ref={(el) => {
                    threadPathRefs.current[i] = el;
                  }}
                  d={`M ${cx + advance / 2} ${baseline + 2} L ${cx + advance / 2} ${baseline + 2}`}
                  fill="none"
                  stroke="var(--foreground)"
                  strokeWidth={1.4}
                  strokeDasharray="2 2"
                  strokeLinecap="round"
                  aria-hidden="true"
                />
              )}

              {state === "unraveled" && (
                <g className="ns-stitch-pile" aria-hidden="true">
                  <path
                    d={`M ${cx + advance * 0.16} ${baseline - 2}
                        q ${advance * 0.16} 12 ${advance * 0.34} 6
                        q ${advance * 0.22} -9 ${advance * 0.42} 3
                        q -${advance * 0.1} 9 ${advance * 0.1} 13
                        q ${advance * 0.14} -5 ${advance * 0.28} 0`}
                    fill="none"
                    stroke="var(--foreground)"
                    strokeWidth={1.5}
                    strokeDasharray="2.2 2.2"
                    strokeLinecap="round"
                  />
                  <path
                    d={`M ${cx + advance * 0.22} ${baseline + 1}
                        q ${advance * 0.12} 8 ${advance * 0.3} 4`}
                    fill="none"
                    stroke="var(--ns-accent)"
                    strokeOpacity={0.3}
                    strokeWidth={1}
                    strokeDasharray="2 2"
                    strokeLinecap="round"
                  />
                </g>
              )}
            </g>
          );
        })}
      </svg>

      <button
        type="button"
        onClick={resewAll}
        className="ns-stitch-resew rounded-[6px] border border-border px-3 py-1.5 font-mono text-[11px] uppercase tracking-wide text-foreground hover:bg-border/40 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
      >
        {anyUnraveled ? "Re-sew" : "Re-sew (nothing loose)"}
      </button>
    </div>
  );
}

const CSS = `
.ns-stitch-thread{transition:opacity 200ms ease-out;}
.ns-stitch-thread text{transition:stroke-opacity 150ms ease-out;}
.ns-stitch-pile{animation:ns-stitch-settle 220ms cubic-bezier(0.16,1,0.3,1);}
@keyframes ns-stitch-settle{from{opacity:0;transform:translateY(-3px) scale(0.9);}to{opacity:1;transform:none;}}
@media (prefers-reduced-motion: reduce){
  .ns-stitch-thread{transition:opacity 0ms;}
  .ns-stitch-thread text{transition:stroke-opacity 120ms linear;}
  .ns-stitch-pile{animation:none;}
}
.ns-stitch-svg text{paint-order:stroke;}
`;

"use client";

import { useEffect, useRef } from "react";

// ---------------------------------------------------------------------------
// ThallusSiege — a pane of crustose lichen fighting a slow, never-finished war
// for the same patch of rock.
//
// TERRITORY IS GROWN, NOT PARTITIONED. A dozen concurrent "thalli" nucleate at
// staggered moments on bare substrate. Each grows a front of ~180 radial
// spokes; every spoke advances at its own thallus's rate, scaled by a slow
// angular/temporal noise term so the margin comes out lobed rather than a
// clean circle. A spoke stamps the cell it enters into a shared occupancy
// lattice (owner id + claim time). Stepping into a cell another thallus
// already owns kills the spoke's advance there UNLESS this thallus's rate
// exceeds the rival's by more than 1.3x, in which case it keeps creeping in
// at (ratio - 1.3) * base — slow, but real reconquest, not a redraw. Nothing
// here ever asks "which seed is nearest" — the tells that would give away a
// Voronoi/distance-field impostor (boundaries bowing toward the slow side,
// a late seed walled into a concave cell, a centre that never reopens) are
// exactly the behaviours this front-growth mechanism produces for free.
//
// THE GOVERNING SCALAR is growth-rate variance across thalli (the `variance`
// prop). At variance = 0 every thallus grows at the same pace, the 1.3x
// dead-band is never crossed, no front ever reconquers another, and the
// mosaic settles into flat, static, roughly-equidistant cells — a fair
// near-Voronoi partition in every way but how it was computed. That is the
// exact failure this piece exists to avoid, which is why variance defaults
// to a real spread rather than a token one.
//
// SENESCENCE falls out of the same lattice for free: a cell's claim time is
// stamped once and not refreshed, so the cells nearest a thallus's own
// nucleation point are always its oldest. Aging a cell out past its thallus's
// senescence limit therefore clears centre-first, outward, automatically —
// no separate "shrink from the middle" pass is needed. A cleared cell is
// bare substrate again; the neighbour whose front already stalled against it
// resumes growing into it on the very next step. When a thallus's last cell
// clears, its slot goes quiet for a staggered cooldown and then nucleates
// again elsewhere, so the war never actually finishes — it only ever pauses
// between shifts, which is the whole point of a 20-simulated-minute prewarm:
// the frame you land on already has one or two turnovers baked into it.
//
// A contested cell that reverts to substrate — either by senescence or by
// being overrun — leaves a mark in a separate, slowly-decaying "seam" field.
// Rendered as a hairline lattice of --border, it is the pane's memory of
// where a border used to run even after both sides that drew it are gone.
//
// RENDER is plain 2D canvas, no WebGL. The occupancy lattice is coarse
// (quarter the density of anything a viewer could resolve as a grid); its
// blocky per-cell ownership is smoothed into an organic contour with a real
// marching-squares pass over the lattice (binary field per species, a single
// segment per 2-crossing square, the diagonal pair for the 4-crossing saddle
// case) rather than any blur or upscale trick. Fill is per-species ordered
// dithering between --background and --ns-muted — 12 fixed densities, one
// per lattice slot, so a slot keeps a recognisable "species" texture across
// however many generations nucleate into it. Every colour is read from
// getComputedStyle at mount and on a documentElement class mutation; nothing
// is a literal. --ns-accent never appears — this is idle rock, nothing here
// is being interacted with.
// ---------------------------------------------------------------------------

export interface ThallusSiegeProps {
  /** Concurrent lichen thalli contesting the pane. @default 12 */
  count?: number;
  /**
   * Spread of growth rate sampled per thallus — the mechanism's governing
   * scalar. 0 flattens every front to the same pace, the 1.3x reconquest
   * band is never crossed, and the mosaic settles into fair, static,
   * near-Voronoi cells: the exact failure this piece is built to avoid.
   * @default 1
   */
  variance?: number;
  /** Simulation-time multiplier. @default 1 */
  speed?: number;
  /** Freezes the pane on its current developed frame without unmounting. */
  paused?: boolean;
  /** Rendered over the pane — eyebrow, headline, CTA. */
  children?: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
}

const TAU = Math.PI * 2;

// Lattice + spoke geometry.
const CELL = 6; // css px per occupancy cell — coarse on purpose
const SPOKES = 180;

// Growth mechanics.
const BASE_RATE = 0.85; // px/s at variance's centre — deliberately glacial
const CONTACT_RATIO = 1.3; // dead-band: a spoke stalls below this rate ratio
const NOISE_AMOUNT = 0.3; // fraction of rate the margin noise can add/remove

// Lifecycle timing, all in SIMULATED seconds.
const T_SEN_BASE = 780; // ~13 sim-minutes before a thallus's oldest cells fade
const T_SEN_SPREAD = 0.4; // +/- fraction of variety across individuals
const SEAM_TAU = 220; // ghost-seam decay time constant
const STAGGER_WINDOW = 300; // initial dozen nucleate across this span
const COOLDOWN_MIN = 40; // shortest gap before a retired slot tries again
const COOLDOWN_SPREAD = 140;
const NUCLEATION_CLEARANCE = CELL * 2.5;

// The pane arrives already having fought over itself for a while.
const PREWARM_SECONDS = 1200; // 20 simulated minutes
const PREWARM_DT = 2; // sim seconds per prewarm step -> 600 steps

const DRAW_INTERVAL_MS = 380; // growth is glacial; redraw far under 60fps

// 8x8 ordered (Bayer) dither matrix, values 0..63.
const BAYER8: number[][] = [
  [0, 32, 8, 40, 2, 34, 10, 42],
  [48, 16, 56, 24, 50, 18, 58, 26],
  [12, 44, 4, 36, 14, 46, 6, 38],
  [60, 28, 52, 20, 62, 30, 54, 22],
  [3, 35, 11, 43, 1, 33, 9, 41],
  [51, 19, 59, 27, 49, 17, 57, 25],
  [15, 47, 7, 39, 13, 45, 5, 37],
  [63, 31, 55, 23, 61, 29, 53, 21],
];

type Thallus = {
  id: number;
  slot: number;
  cx: number;
  cy: number;
  rate: number;
  seed: number;
  senLimit: number;
  spokeR: Float32Array;
  bboxMinC: number;
  bboxMaxC: number;
  bboxMinR: number;
  bboxMaxR: number;
  cellCount: number;
};

/** Slow, lobed angular perturbation. Not true curl noise — a stand-in built
 * from a few incommensurate sine terms in theta with a slow phase drift in
 * t, tuned so the margin scallops rather than either vanishing flat or
 * spiking into fingers. */
function marginNoise(theta: number, simTime: number, seed: number): number {
  const a = Math.sin(theta * 3 + seed * 7.1 + simTime * 0.013);
  const b = Math.sin(theta * 5 - seed * 3.3 + simTime * 0.021) * 0.6;
  const c = Math.sin(theta * 8 + seed * 11.7 - simTime * 0.009) * 0.35;
  return (a + b + c) / 1.95;
}

export function ThallusSiege({
  count = 12,
  variance = 1,
  speed = 1,
  paused = false,
  children,
  className = "",
  style,
}: ThallusSiegeProps) {
  const wrapRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const pausedRef = useRef(paused);
  pausedRef.current = paused;

  useEffect(() => {
    const wrap = wrapRef.current;
    const canvas = canvasRef.current;
    if (!wrap || !canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const nSlots = Math.max(4, Math.min(24, Math.round(count)));
    const varAmt = Math.max(0, variance);
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    let reduced = mq.matches;

    let disposed = false;
    let cssW = 0;
    let cssH = 0;
    let dpr = 1;
    let cols = 0;
    let rows = 0;
    let sized = false;
    let staticMode = false;

    // -- occupancy lattice -----------------------------------------------
    let owner: Uint16Array = new Uint16Array(0);
    let claimedAt: Float32Array = new Float32Array(0);
    let seam: Float32Array = new Float32Array(0);
    const seamCells = new Set<number>();

    let simTime = 0;
    let idSeq = 1;
    let rngState = 0x9e3779b9 >>> 0;
    const rng = () => {
      rngState ^= rngState << 13;
      rngState >>>= 0;
      rngState ^= rngState >>> 17;
      rngState ^= rngState << 5;
      rngState >>>= 0;
      return rngState / 4294967296;
    };

    const slots: (Thallus | null)[] = new Array(nSlots).fill(null);
    const slotCooldown = new Float32Array(nSlots);
    const activeById = new Map<number, Thallus>();

    // -- colors -------------------------------------------------------------
    let bgColor = "#ffffff";
    let mutedColor = "#4d4d4d";
    let borderColor = "#ebebeb";
    const readColors = () => {
      const cs = getComputedStyle(document.documentElement);
      bgColor = (cs.getPropertyValue("--background") || "#ffffff").trim() || "#ffffff";
      mutedColor = (cs.getPropertyValue("--ns-muted") || "#4d4d4d").trim() || "#4d4d4d";
      borderColor = (cs.getPropertyValue("--border") || "#ebebeb").trim() || "#ebebeb";
    };
    readColors();

    // Per-slot dithered fill, rebuilt on resize (dpr change) and theme change.
    let patterns: CanvasPattern[] = [];
    const buildPatterns = () => {
      const tileCss = 8;
      const size = Math.max(1, Math.round(tileCss * dpr));
      const next: CanvasPattern[] = [];
      for (let s = 0; s < nSlots; s++) {
        const density = nSlots > 1 ? 0.14 + (s / (nSlots - 1)) * 0.46 : 0.3;
        const off = document.createElement("canvas");
        off.width = size;
        off.height = size;
        const octx = off.getContext("2d");
        if (!octx) continue;
        for (let py = 0; py < size; py++) {
          const by = Math.min(7, Math.floor((py / size) * 8));
          for (let px = 0; px < size; px++) {
            const bx = Math.min(7, Math.floor((px / size) * 8));
            const thr = (BAYER8[by]![bx]! + 0.5) / 64;
            octx.fillStyle = thr < density ? mutedColor : bgColor;
            octx.fillRect(px, py, 1, 1);
          }
        }
        const pat = ctx.createPattern(off, "repeat");
        if (!pat) continue;
        pat.setTransform(new DOMMatrix([1 / dpr, 0, 0, 1 / dpr, 0, 0]));
        next[s] = pat;
      }
      patterns = next;
    };

    // -- lattice helpers ------------------------------------------------
    const cellIndexAt = (x: number, y: number): number => {
      const gx = Math.floor(x / CELL);
      const gy = Math.floor(y / CELL);
      if (gx < 0 || gy < 0 || gx >= cols || gy >= rows) return -1;
      return gy * cols + gx;
    };

    const clearAround = (x: number, y: number, r: number): boolean => {
      const gx = Math.floor(x / CELL);
      const gy = Math.floor(y / CELL);
      const rc = Math.ceil(r / CELL);
      for (let j = -rc; j <= rc; j++) {
        const gy2 = gy + j;
        if (gy2 < 0 || gy2 >= rows) continue;
        const row = gy2 * cols;
        for (let i = -rc; i <= rc; i++) {
          const gx2 = gx + i;
          if (gx2 < 0 || gx2 >= cols) continue;
          if (owner[row + gx2] !== 0) return false;
        }
      }
      return true;
    };

    const markSeam = (ci: number) => {
      seam[ci] = 1;
      seamCells.add(ci);
    };

    const retireThallus = (t: Thallus) => {
      activeById.delete(t.id);
      slots[t.slot] = null;
      slotCooldown[t.slot] = simTime + COOLDOWN_MIN + rng() * COOLDOWN_SPREAD;
    };

    const releaseCell = (ci: number) => {
      const prevId = owner[ci];
      if (prevId === 0) return;
      const t = activeById.get(prevId);
      if (t) {
        t.cellCount--;
        if (t.cellCount <= 0) retireThallus(t);
      }
      owner[ci] = 0;
    };

    const updateBBox = (t: Thallus, ci: number) => {
      const gx = ci % cols;
      const gy = (ci / cols) | 0;
      if (gx < t.bboxMinC) t.bboxMinC = gx;
      if (gx > t.bboxMaxC) t.bboxMaxC = gx;
      if (gy < t.bboxMinR) t.bboxMinR = gy;
      if (gy > t.bboxMaxR) t.bboxMaxR = gy;
    };

    const claimCell = (ci: number, t: Thallus, now: number) => {
      const prevId = owner[ci];
      if (prevId === t.id) return;
      if (prevId !== 0) {
        const rival = activeById.get(prevId);
        if (rival) {
          rival.cellCount--;
          if (rival.cellCount <= 0) retireThallus(rival);
        }
        markSeam(ci);
      }
      owner[ci] = t.id;
      claimedAt[ci] = now;
      t.cellCount++;
      updateBBox(t, ci);
    };

    // -- nucleation -------------------------------------------------------
    const nucleate = (slot: number, now: number) => {
      for (let attempt = 0; attempt < 10; attempt++) {
        const x = rng() * cssW;
        const y = rng() * cssH;
        if (clearAround(x, y, NUCLEATION_CLEARANCE)) {
          const id = idSeq++;
          const rate = BASE_RATE * Math.pow(2, (rng() * 2 - 1) * varAmt);
          const t: Thallus = {
            id,
            slot,
            cx: x,
            cy: y,
            rate,
            seed: rng() * 1000,
            senLimit: T_SEN_BASE * (1 - T_SEN_SPREAD / 2 + rng() * T_SEN_SPREAD),
            spokeR: new Float32Array(SPOKES),
            bboxMinC: Infinity,
            bboxMaxC: -Infinity,
            bboxMinR: Infinity,
            bboxMaxR: -Infinity,
            cellCount: 0,
          };
          slots[slot] = t;
          activeById.set(id, t);
          return;
        }
      }
      slotCooldown[slot] = now + 5; // no room yet; try again soon
    };

    const growThallus = (t: Thallus, dt: number) => {
      for (let k = 0; k < SPOKES; k++) {
        const theta = (k * TAU) / SPOKES;
        const n = marginNoise(theta, simTime, t.seed);
        const vel = t.rate * Math.max(0.15, 1 + NOISE_AMOUNT * n);
        const candR = t.spokeR[k]! + vel * dt;
        const cos = Math.cos(theta);
        const sin = Math.sin(theta);
        const ci = cellIndexAt(t.cx + cos * candR, t.cy + sin * candR);
        if (ci < 0) continue; // spoke stalls at the pane's edge
        const own = owner[ci];
        if (own === 0 || own === t.id) {
          claimCell(ci, t, simTime);
          t.spokeR[k] = candR;
          continue;
        }
        const rival = activeById.get(own);
        if (!rival) {
          claimCell(ci, t, simTime);
          t.spokeR[k] = candR;
          continue;
        }
        const ratio = t.rate / rival.rate;
        if (ratio > CONTACT_RATIO) {
          const advVel = (ratio - CONTACT_RATIO) * BASE_RATE;
          const advR = t.spokeR[k]! + advVel * dt;
          const ci2 = cellIndexAt(t.cx + cos * advR, t.cy + sin * advR);
          if (ci2 >= 0) claimCell(ci2, t, simTime);
          t.spokeR[k] = advR;
        }
        // else: rate ratio inside the dead band — this spoke stalls here.
      }
    };

    const neighborDiffers = (gx: number, gy: number, ownBefore: number): boolean => {
      const dirs: Array<[number, number]> = [
        [1, 0],
        [-1, 0],
        [0, 1],
        [0, -1],
      ];
      for (const [dx, dy] of dirs) {
        const nx = gx + dx;
        const ny = gy + dy;
        if (nx < 0 || ny < 0 || nx >= cols || ny >= rows) continue;
        const no = owner[ny * cols + nx];
        if (no !== 0 && no !== ownBefore) return true;
      }
      return false;
    };

    const senescenceSweep = () => {
      const living = Array.from(activeById.values());
      for (const t of living) {
        if (!activeById.has(t.id)) continue; // retired earlier this sweep
        const c0 = Math.max(0, Math.floor(t.bboxMinC));
        const c1 = Math.min(cols - 1, Math.floor(t.bboxMaxC));
        const r0 = Math.max(0, Math.floor(t.bboxMinR));
        const r1 = Math.min(rows - 1, Math.floor(t.bboxMaxR));
        for (let gy = r0; gy <= r1; gy++) {
          const row = gy * cols;
          for (let gx = c0; gx <= c1; gx++) {
            const ci = row + gx;
            if (owner[ci] !== t.id) continue;
            const age = simTime - claimedAt[ci]!;
            if (age > t.senLimit) {
              if (neighborDiffers(gx, gy, t.id)) markSeam(ci);
              releaseCell(ci);
            }
          }
        }
      }
    };

    const decaySeams = (dt: number) => {
      if (seamCells.size === 0) return;
      const decay = Math.exp(-dt / SEAM_TAU);
      for (const ci of seamCells) {
        const v = seam[ci]! * decay;
        seam[ci] = v;
        if (v < 0.02) seamCells.delete(ci);
      }
    };

    const stepSim = (dt: number) => {
      if (dt <= 0) return;
      simTime += dt;
      for (let s = 0; s < nSlots; s++) {
        if (!slots[s] && simTime >= slotCooldown[s]!) nucleate(s, simTime);
      }
      for (let s = 0; s < nSlots; s++) {
        const t = slots[s];
        if (t) growThallus(t, dt);
      }
      senescenceSweep();
      decaySeams(dt);
    };

    const resetSim = () => {
      cols = Math.max(1, Math.ceil(cssW / CELL));
      rows = Math.max(1, Math.ceil(cssH / CELL));
      owner = new Uint16Array(cols * rows);
      claimedAt = new Float32Array(cols * rows);
      seam = new Float32Array(cols * rows);
      seamCells.clear();
      simTime = 0;
      idSeq = 1;
      rngState = 0x9e3779b9 >>> 0;
      activeById.clear();
      for (let s = 0; s < nSlots; s++) {
        slots[s] = null;
        slotCooldown[s] = rng() * STAGGER_WINDOW;
      }
    };

    const prewarm = () => {
      const steps = Math.round(PREWARM_SECONDS / PREWARM_DT);
      for (let i = 0; i < steps; i++) stepSim(PREWARM_DT);
    };

    // -- marching squares over the binary field for one species ----------
    const marchSpecies = (t: Thallus, path: Path2D) => {
      if (t.cellCount <= 0) return;
      const i0 = Math.max(0, Math.floor(t.bboxMinC) - 1);
      const i1 = Math.min(cols - 2, Math.floor(t.bboxMaxC));
      const j0 = Math.max(0, Math.floor(t.bboxMinR) - 1);
      const j1 = Math.min(rows - 2, Math.floor(t.bboxMaxR));
      if (i1 < i0 || j1 < j0) return;
      const sampleAt = (gx: number, gy: number): number => {
        if (gx < 0 || gy < 0 || gx >= cols || gy >= rows) return 0;
        return owner[gy * cols + gx] === t.id ? 1 : 0;
      };
      for (let j = j0; j <= j1; j++) {
        for (let i = i0; i <= i1; i++) {
          const tl = sampleAt(i, j);
          const tr = sampleAt(i + 1, j);
          const br = sampleAt(i + 1, j + 1);
          const bl = sampleAt(i, j + 1);
          if (tl === tr && tr === br && br === bl) continue;
          const x0 = i * CELL;
          const x1 = x0 + CELL;
          const y0 = j * CELL;
          const y1 = y0 + CELL;
          const midX = (x0 + x1) / 2;
          const midY = (y0 + y1) / 2;
          const T: [number, number] = [midX, y0];
          const R: [number, number] = [x1, midY];
          const B: [number, number] = [midX, y1];
          const L: [number, number] = [x0, midY];
          const crossTop = tl !== tr;
          const crossRight = tr !== br;
          const crossBottom = bl !== br;
          const crossLeft = tl !== bl;
          const count =
            (crossTop ? 1 : 0) + (crossRight ? 1 : 0) + (crossBottom ? 1 : 0) + (crossLeft ? 1 : 0);
          if (count === 2) {
            const pts: Array<[number, number]> = [];
            if (crossTop) pts.push(T);
            if (crossRight) pts.push(R);
            if (crossBottom) pts.push(B);
            if (crossLeft) pts.push(L);
            path.moveTo(pts[0]![0], pts[0]![1]);
            path.lineTo(pts[1]![0], pts[1]![1]);
          } else if (count === 4) {
            if (tl === 1) {
              path.moveTo(T[0], T[1]);
              path.lineTo(L[0], L[1]);
              path.moveTo(B[0], B[1]);
              path.lineTo(R[0], R[1]);
            } else {
              path.moveTo(T[0], T[1]);
              path.lineTo(R[0], R[1]);
              path.moveTo(B[0], B[1]);
              path.lineTo(L[0], L[1]);
            }
          }
        }
      }
    };

    const fillThallus = (t: Thallus) => {
      if (t.cellCount <= 0) return;
      const pat = patterns[t.slot];
      if (!pat) return;
      const c0 = Math.max(0, Math.floor(t.bboxMinC));
      const c1 = Math.min(cols - 1, Math.floor(t.bboxMaxC));
      const r0 = Math.max(0, Math.floor(t.bboxMinR));
      const r1 = Math.min(rows - 1, Math.floor(t.bboxMaxR));
      const path = new Path2D();
      let any = false;
      for (let gy = r0; gy <= r1; gy++) {
        const row = gy * cols;
        for (let gx = c0; gx <= c1; gx++) {
          if (owner[row + gx] === t.id) {
            path.rect(gx * CELL, gy * CELL, CELL, CELL);
            any = true;
          }
        }
      }
      if (!any) return;
      ctx.fillStyle = pat;
      ctx.fill(path);
    };

    const SEAM_BUCKET_T = [0.25, 0.5, 0.75, 1.01];
    const SEAM_BUCKET_ALPHA = [0.12, 0.22, 0.32, 0.42];

    const drawSeams = () => {
      if (seamCells.size === 0) return;
      const buckets = [new Path2D(), new Path2D(), new Path2D(), new Path2D()];
      for (const ci of seamCells) {
        const v = seam[ci]!;
        if (v < 0.02) continue;
        let b = 0;
        while (b < 3 && v > SEAM_BUCKET_T[b]!) b++;
        const gx = ci % cols;
        const gy = (ci / cols) | 0;
        buckets[b]!.rect(gx * CELL + 1, gy * CELL + 1, CELL - 2, CELL - 2);
      }
      ctx.lineWidth = 1;
      ctx.strokeStyle = borderColor;
      for (let b = 0; b < 4; b++) {
        ctx.globalAlpha = SEAM_BUCKET_ALPHA[b]!;
        ctx.stroke(buckets[b]!);
      }
      ctx.globalAlpha = 1;
    };

    const draw = () => {
      if (!sized) return;
      ctx.clearRect(0, 0, cssW, cssH);
      for (const t of activeById.values()) fillThallus(t);
      const boundary = new Path2D();
      for (const t of activeById.values()) marchSpecies(t, boundary);
      ctx.lineWidth = 1;
      ctx.strokeStyle = borderColor;
      ctx.globalAlpha = 0.55;
      ctx.stroke(boundary);
      ctx.globalAlpha = 1;
      drawSeams();
    };

    // -- host plumbing ------------------------------------------------------
    const applyBacking = () => {
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(cssW * dpr));
      canvas.height = Math.max(1, Math.round(cssH * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };

    const rebuild = () => {
      if (cssW < 2 || cssH < 2) {
        sized = false;
        return;
      }
      applyBacking();
      buildPatterns();
      resetSim();
      prewarm();
      sized = true;
      draw();
    };

    let lastW = 0;
    let lastH = 0;
    const resize = () => {
      const rect = wrap.getBoundingClientRect();
      if (rect.width < 2 || rect.height < 2) return;
      if (Math.abs(rect.width - lastW) < 2 && Math.abs(rect.height - lastH) < 2) return;
      lastW = rect.width;
      lastH = rect.height;
      cssW = rect.width;
      cssH = rect.height;
      rebuild();
    };

    let raf = 0;
    let running = false;
    let lastMs = 0;
    let lastDrawMs = 0;

    const loop = (now: number) => {
      const dt = lastMs ? Math.min(0.25, (now - lastMs) / 1000) : 1 / 60;
      lastMs = now;
      stepSim(dt * Math.max(0, speed));
      if (now - lastDrawMs >= DRAW_INTERVAL_MS) {
        draw();
        lastDrawMs = now;
      }
      raf = requestAnimationFrame(loop);
    };

    const wake = () => {
      if (running || disposed || !sized || staticMode) return;
      running = true;
      lastMs = 0;
      raf = requestAnimationFrame(loop);
    };
    const sleep = () => {
      cancelAnimationFrame(raf);
      running = false;
    };

    const applyMode = () => {
      staticMode = reduced || pausedRef.current;
      if (staticMode) {
        sleep();
        draw();
      } else {
        wake();
      }
    };

    const ro = new ResizeObserver(resize);
    ro.observe(wrap);
    resize();
    applyMode();

    let onScreen = true;
    const io = new IntersectionObserver(
      (entries) => {
        onScreen = entries.some((en) => en.isIntersecting);
        if (!onScreen) sleep();
        else if (!staticMode && !document.hidden) wake();
      },
      { threshold: 0 }
    );
    io.observe(wrap);

    const onVis = () => {
      if (document.hidden) sleep();
      else if (!staticMode && onScreen) wake();
    };
    document.addEventListener("visibilitychange", onVis);

    const onMq = () => {
      reduced = mq.matches;
      applyMode();
    };
    mq.addEventListener("change", onMq);

    const themeObserver = new MutationObserver(() => {
      readColors();
      if (sized) {
        buildPatterns();
        draw();
      }
    });
    themeObserver.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    // paused is polled rather than an effect dependency, so toggling it does
    // not tear down and re-prewarm 20 minutes of simulated history.
    let lastPolledPaused = pausedRef.current;
    let pollTimer = 0;
    const poll = () => {
      if (pausedRef.current !== lastPolledPaused) {
        lastPolledPaused = pausedRef.current;
        applyMode();
      }
      pollTimer = window.setTimeout(poll, 160);
    };
    poll();

    return () => {
      disposed = true;
      ro.disconnect();
      io.disconnect();
      mq.removeEventListener("change", onMq);
      document.removeEventListener("visibilitychange", onVis);
      themeObserver.disconnect();
      window.clearTimeout(pollTimer);
      sleep();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [count, variance, speed]);

  return (
    <div
      ref={wrapRef}
      className={`relative isolate h-full w-full overflow-hidden bg-background ${className}`}
      style={style}
    >
      <canvas ref={canvasRef} aria-hidden="true" className="absolute inset-0 block" />
      {children ? <div className="relative z-[1] h-full w-full">{children}</div> : null}
    </div>
  );
}

ThallusSiege.displayName = "ThallusSiege";

"use client";

import {
  forwardRef,
  useCallback,
  useEffect,
  useId,
  useImperativeHandle,
  useRef,
  useState,
  type ReactNode,
} from "react";

// ---------------------------------------------------------------------------
// ImpulseCradle — a toast stack that behaves like a Newton's cradle. A new
// toast swings in from the top with an accelerating (ease-in) entrance and
// "strikes" the queue; the impact travels down through every already-queued
// toast as a fast domino of 2-3px shunts, staggered 35ms apart, so the eye
// reads how deep the stack is without counting anything. Under capacity that
// impulse simply dissipates — the last toast shunts and returns. At capacity
// the same impulse instead carries the oldest toast off the far (bottom) end:
// it inherits the shunt's momentum and departs with an ease-out arc, a slight
// rotation, and a fade — conservation of notifications, visibly enforced.
// Pure DOM transforms via the Web Animations API, tokens only, no canvas.
// ---------------------------------------------------------------------------

export type ImpulseSeverity = "info" | "error";

export interface ImpulseToastInput {
  severity?: ImpulseSeverity;
  title: string;
  message?: string;
  /** ms before auto-dismiss; 0 disables; defaults to the stack `duration` */
  duration?: number;
}

export interface ImpulseCradleHandle {
  /** swing a new toast into the stack, returns its id */
  push: (toast: ImpulseToastInput) => string;
  dismiss: (id: string) => void;
  clear: () => void;
}

type ToastRec = {
  id: string;
  severity: ImpulseSeverity;
  title: string;
  message?: string;
  duration: number;
};

type HistoryReason = "dismissed" | "expired" | "evicted";
type HistoryRec = ToastRec & { reason: HistoryReason; at: number };

type TimerEntry = { handle: number | null; deadline: number; remaining: number };
type PauseReason = "hover" | "focus";

const SHUNT_STAGGER = 35; // ms between each toast's impulse pulse
const SHUNT_MS = 60;
const SHUNT_PX = 3;
const EJECT_MS = 340;
const ENTER_MS = 200;
const EXIT_MS = 150;
const EASE_IN = "cubic-bezier(.55,.06,.68,.19)"; // accelerating, released-ball entrance
const EASE_OUT = "cubic-bezier(0.16,1,0.3,1)"; // decelerating, matches the eject's inherited velocity

const ICONS: Record<ImpulseSeverity, ReactNode> = {
  error: (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <circle cx="12" cy="12" r="9" />
      <path d="m15 9-6 6M9 9l6 6" />
    </svg>
  ),
  info: (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <circle cx="12" cy="12" r="9" />
      <path d="m8.5 12.5 2.5 2.5 4.5-5" />
    </svg>
  ),
};

function CardShell({ toast, onDismiss }: { toast: ToastRec; onDismiss: () => void }) {
  return (
    <div className="flex items-start gap-2.5 py-2.5 pl-3 pr-1.5">
      <span className="mt-0.5 shrink-0 text-ns-muted">{ICONS[toast.severity]}</span>
      <div className="min-w-0 flex-1">
        <p
          className={`truncate text-[13px] leading-tight text-foreground ${
            toast.severity === "error" ? "font-semibold" : "font-medium"
          }`}
        >
          {toast.title}
        </p>
        {toast.message ? (
          <p className="mt-0.5 truncate font-mono text-[11px] leading-tight text-ns-muted">
            {toast.message}
          </p>
        ) : null}
      </div>
      <button
        type="button"
        aria-label={`Dismiss: ${toast.title}`}
        onClick={onDismiss}
        className="shrink-0 cursor-pointer rounded-sm p-1 text-ns-muted transition-colors duration-150 hover:bg-foreground/10 hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-ns-accent"
      >
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" aria-hidden>
          <path d="M18 6 6 18M6 6l12 12" />
        </svg>
      </button>
    </div>
  );
}

export const ImpulseCradle = forwardRef<
  ImpulseCradleHandle,
  {
    /** how many toasts the stack shows before the impulse starts ejecting */
    maxVisible?: number;
    /** ms before a toast auto-dismisses (paused on hover/focus); 0 disables */
    duration?: number;
    /** toasts present at mount */
    initial?: ImpulseToastInput[];
    /** extra classes merged onto the rendered root element */
    className?: string;
    /** accessible name for the toast stack */
    "aria-label"?: string;
  }
>(function ImpulseCradle(
  {
    maxVisible = 4,
    duration = 5000,
    initial,
    className = "w-full max-w-sm",
    "aria-label": ariaLabel = "Notifications",
  },
  ref
) {
  const cap = Math.max(1, maxVisible);
  const regionRef = useRef<HTMLDivElement>(null);
  const historyPanelId = useId();

  const seqRef = useRef(0);
  const liveSeqRef = useRef(0);
  const toastsRef = useRef<ToastRec[]>([]);
  const timersRef = useRef<Map<string, TimerEntry>>(new Map());
  const pauseReasonsRef = useRef<Map<string, Set<PauseReason>>>(new Map());
  const cardElsRef = useRef<Map<string, HTMLDivElement>>(new Map());
  const enteredRef = useRef<Set<string>>(new Set());
  const exitingIdsRef = useRef<Set<string>>(new Set());
  const evictDelayRef = useRef<Map<string, number>>(new Map());
  const evictAttachedRef = useRef<Set<string>>(new Set());

  const [toasts, setToasts] = useState<ToastRec[]>(() =>
    (initial ?? []).map((t, i) => ({
      id: `ic-init-${i}`,
      severity: t.severity ?? "info",
      title: t.title,
      message: t.message,
      duration: t.duration ?? duration,
    }))
  );
  toastsRef.current = toasts;
  const [evicting, setEvicting] = useState<ToastRec[]>([]);
  const [history, setHistory] = useState<HistoryRec[]>([]);
  const [historyOpen, setHistoryOpen] = useState(false);
  const [reduced, setReduced] = useState(false);
  const [live, setLive] = useState<{ text: string; level: "polite" | "assertive"; seq: number }>({
    text: "",
    level: "polite",
    seq: -1,
  });

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(mq.matches);
    update();
    mq.addEventListener("change", update);
    return () => mq.removeEventListener("change", update);
  }, []);

  const announce = useCallback((text: string, level: "polite" | "assertive") => {
    setLive({ text, level, seq: ++liveSeqRef.current });
  }, []);

  const pushHistory = useCallback((t: ToastRec, reason: HistoryReason) => {
    setHistory((prev) => [{ ...t, reason, at: Date.now() }, ...prev].slice(0, 12));
  }, []);

  const clearTimer = useCallback((id: string) => {
    const entry = timersRef.current.get(id);
    if (entry?.handle !== null && entry) clearTimeout(entry.handle);
    timersRef.current.delete(id);
    pauseReasonsRef.current.delete(id);
  }, []);

  const dismiss = useCallback(
    (id: string, reason: HistoryReason = "dismissed") => {
      if (exitingIdsRef.current.has(id)) return;
      const t = toastsRef.current.find((x) => x.id === id);
      if (!t) return;
      exitingIdsRef.current.add(id);
      clearTimer(id);
      const el = cardElsRef.current.get(id);
      const finish = () => {
        exitingIdsRef.current.delete(id);
        cardElsRef.current.delete(id);
        enteredRef.current.delete(id);
        setToasts((prev) => prev.filter((x) => x.id !== id));
        pushHistory(t, reason);
      };
      if (el) {
        const anim = el.animate([{ opacity: 1 }, { opacity: 0 }], {
          duration: EXIT_MS,
          easing: "ease-out",
          fill: "forwards",
        });
        anim.finished.catch(() => {}).finally(finish);
      } else {
        finish();
      }
    },
    [clearTimer, pushHistory]
  );

  const armTimer = useCallback(
    (t: ToastRec) => {
      if (t.duration <= 0) return;
      timersRef.current.set(t.id, {
        handle: window.setTimeout(() => dismiss(t.id, "expired"), t.duration),
        deadline: Date.now() + t.duration,
        remaining: t.duration,
      });
    },
    [dismiss]
  );

  const pauseTimer = useCallback((id: string, reason: PauseReason) => {
    const reasons = pauseReasonsRef.current.get(id) ?? new Set<PauseReason>();
    reasons.add(reason);
    pauseReasonsRef.current.set(id, reasons);
    const entry = timersRef.current.get(id);
    if (entry?.handle !== null && entry) {
      clearTimeout(entry.handle);
      entry.handle = null;
      entry.remaining = Math.max(0, entry.deadline - Date.now());
    }
  }, []);

  const resumeTimer = useCallback(
    (id: string, reason: PauseReason) => {
      const reasons = pauseReasonsRef.current.get(id);
      if (reasons) {
        reasons.delete(reason);
        if (reasons.size > 0) return;
      }
      const entry = timersRef.current.get(id);
      if (!entry || entry.handle !== null) return;
      const ms = Math.max(400, entry.remaining);
      entry.deadline = Date.now() + ms;
      entry.handle = window.setTimeout(() => dismiss(id, "expired"), ms);
    },
    [dismiss]
  );

  const finalizeEvict = useCallback(
    (t: ToastRec) => {
      evictAttachedRef.current.delete(t.id);
      cardElsRef.current.delete(t.id);
      setEvicting((prev) => prev.filter((x) => x.id !== t.id));
      pushHistory(t, "evicted");
    },
    [pushHistory]
  );

  // entrance: every freshly-mounted toast card plays this exactly once — by
  // construction the only card that ever mounts fresh is the newest arrival,
  // since surviving cards keep their DOM identity (same React key) and just
  // ride out the shunt in place instead of remounting.
  const attachCard = useCallback(
    (id: string, el: HTMLDivElement | null) => {
      if (!el) return;
      cardElsRef.current.set(id, el);
      if (enteredRef.current.has(id)) return;
      enteredRef.current.add(id);
      if (reduced) {
        el.animate([{ opacity: 0 }, { opacity: 1 }], { duration: EXIT_MS, easing: "ease-out" });
      } else {
        el.animate(
          [
            { transform: "translateY(-26px) scale(0.97)", opacity: 0 },
            { transform: "translateY(0) scale(1)", opacity: 1 },
          ],
          { duration: ENTER_MS, easing: EASE_IN }
        );
      }
    },
    [reduced]
  );

  // eviction: the oldest toast, bumped out of the visible cap, keeps
  // rendering (in an inert overlay list) just long enough to play its
  // departure, inheriting the same stagger slot the shunt cascade would have
  // given it had it survived.
  const attachEvicting = useCallback(
    (t: ToastRec, el: HTMLDivElement | null) => {
      if (!el || evictAttachedRef.current.has(t.id)) return;
      evictAttachedRef.current.add(t.id);
      const delay = evictDelayRef.current.get(t.id) ?? 0;
      const anim = reduced
        ? el.animate([{ opacity: 1 }, { opacity: 0 }], {
            duration: EXIT_MS,
            easing: "ease-out",
            fill: "forwards",
          })
        : el.animate(
            [
              { transform: "translateY(0px) rotate(0deg)", opacity: 1 },
              { transform: "translateY(10px) rotate(2deg)", opacity: 1, offset: 0.35 },
              { transform: "translateY(46px) rotate(9deg)", opacity: 0 },
            ],
            { duration: EJECT_MS, delay, easing: EASE_OUT, fill: "forwards" }
          );
      anim.finished
        .catch(() => {})
        .finally(() => finalizeEvict(t));
    },
    [reduced, finalizeEvict]
  );

  const push = useCallback(
    (input: ImpulseToastInput): string => {
      const id = `ic-${++seqRef.current}`;
      const severity: ImpulseSeverity = input.severity ?? "info";
      const rec: ToastRec = {
        id,
        severity,
        title: input.title,
        message: input.message,
        duration: input.duration ?? duration,
      };

      const prev = toastsRef.current;
      const overCap = prev.length >= cap;
      const kept = overCap ? prev.slice(0, Math.max(0, cap - 1)) : prev;
      const ejected = overCap ? prev[prev.length - 1] : null;
      const next = [rec, ...kept];
      toastsRef.current = next;
      setToasts(next);

      if (ejected) {
        clearTimer(ejected.id);
        evictDelayRef.current.set(ejected.id, kept.length * SHUNT_STAGGER);
        setEvicting((ev) => [...ev, ejected]);
      }

      armTimer(rec);
      announce(
        `${severity === "error" ? "Error" : "Notification"}: ${rec.title}${
          rec.message ? `. ${rec.message}` : ""
        }`,
        severity === "error" ? "assertive" : "polite"
      );

      // the impulse cascade — every toast that survives the push (i.e. every
      // toast except the new arrival) gets a 3px shunt toward the far end,
      // staggered 35ms deeper per position, then springs back. The ejected
      // toast plays the matching (but non-returning) motion in attachEvicting.
      if (!reduced) {
        requestAnimationFrame(() => {
          kept.forEach((t, i) => {
            const el = cardElsRef.current.get(t.id);
            el?.animate(
              [
                { transform: "translateY(0px)" },
                { transform: `translateY(${SHUNT_PX}px)`, offset: 0.4 },
                { transform: "translateY(0px)" },
              ],
              { duration: SHUNT_MS, delay: (i + 1) * SHUNT_STAGGER, easing: "ease-out" }
            );
          });
        });
      }

      return id;
    },
    [cap, duration, armTimer, announce, clearTimer, reduced]
  );

  const clear = useCallback(() => {
    for (const t of toastsRef.current) dismiss(t.id);
  }, [dismiss]);

  useImperativeHandle(ref, () => ({ push, dismiss, clear }), [push, dismiss, clear]);

  // arm timers for `initial` toasts seeded at mount (push() handles its own)
  useEffect(() => {
    for (const t of toastsRef.current) {
      if (!timersRef.current.has(t.id)) armTimer(t);
    }
    // deliberately mount-only: push() arms its own toasts as they arrive
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // teardown: every pending timer dies with the component
  useEffect(() => {
    const timers = timersRef.current;
    return () => {
      for (const entry of timers.values()) if (entry.handle !== null) clearTimeout(entry.handle);
      timers.clear();
    };
  }, []);

  // F6 (pane-jump convention): send focus straight to the toast region —
  // the newest toast if one is present, otherwise the region landmark itself.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "F6") return;
      const root = regionRef.current;
      if (!root) return;
      e.preventDefault();
      const firstToast = root.querySelector<HTMLElement>("[data-ic-toast]");
      (firstToast ?? root).focus();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  return (
    <div className={`relative ${className}`}>
      <div
        ref={regionRef}
        role="region"
        aria-label={ariaLabel}
        tabIndex={-1}
        className="flex flex-col gap-2 outline-none"
      >
        {toasts.map((t) => (
          <div
            key={t.id}
            ref={(el) => attachCard(t.id, el)}
            data-ic-toast
            role={t.severity === "error" ? "alert" : "status"}
            aria-label={`${t.severity === "error" ? "Error" : "Notification"}: ${t.title}`}
            tabIndex={0}
            onPointerEnter={() => pauseTimer(t.id, "hover")}
            onPointerLeave={() => resumeTimer(t.id, "hover")}
            onFocus={() => pauseTimer(t.id, "focus")}
            onBlur={() => resumeTimer(t.id, "focus")}
            onKeyDown={(e) => {
              if (e.key === "Escape") {
                e.stopPropagation();
                dismiss(t.id);
              }
            }}
            className="overflow-hidden rounded-sm border border-border bg-background will-change-transform focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
          >
            <CardShell toast={t} onDismiss={() => dismiss(t.id)} />
          </div>
        ))}
        {evicting.map((t) => (
          <div
            key={`evict-${t.id}`}
            ref={(el) => attachEvicting(t, el)}
            aria-hidden="true"
            className="pointer-events-none overflow-hidden rounded-sm border border-border bg-background will-change-transform"
          >
            <CardShell toast={t} onDismiss={() => {}} />
          </div>
        ))}
      </div>

      {history.length > 0 ? (
        <div className="mt-2">
          <button
            type="button"
            data-ic-history-toggle
            aria-expanded={historyOpen}
            aria-controls={historyPanelId}
            onClick={() => setHistoryOpen((v) => !v)}
            className="cursor-pointer rounded-sm border border-border px-2 py-1 font-mono text-[11px] tracking-wide text-ns-muted transition-colors duration-150 hover:border-foreground/20 hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent"
          >
            History ({history.length})
          </button>
          {historyOpen ? (
            <ul
              id={historyPanelId}
              className="mt-1.5 flex flex-col gap-1 rounded-sm border border-border p-2"
            >
              {history.map((h) => (
                <li
                  key={`${h.id}-${h.at}`}
                  data-ic-history-item
                  className="flex items-baseline justify-between gap-3 font-mono text-[11px]"
                >
                  <span className="truncate text-foreground">{h.title}</span>
                  <span className="shrink-0 text-ns-muted">{h.reason}</span>
                </li>
              ))}
            </ul>
          ) : null}
        </div>
      ) : null}

      {/* single shared announcer: politeness swaps between info and error by
          remounting on `seq`, since a live region's live-ness is typically
          fixed at first AT encounter — physics-only reflow never touches
          this, so an existing toast is never re-announced */}
      <div key={live.seq} role="status" aria-live={live.level} aria-atomic="true" className="sr-only">
        {live.text}
      </div>
    </div>
  );
});

"use client";

import {
  useEffect,
  useId,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  type ReactNode,
} from "react";

// ---------------------------------------------------------------------------
// AsciiDissolveTransition — a layout transition whose seam is a SPATIAL
// dissolve front, not a per-character identity churn. Two full panels sit
// stacked: the outgoing `from` panel on top, hard-clipped at a front
// position; the incoming `to` panel underneath, always full. A canvas veil
// layered above both draws a band of ASCII glyph noise centered exactly on
// the front, density falling off with distance from it — the outgoing
// panel visibly frays into noise on the side not yet swept, and the
// incoming panel visibly resolves out of that same noise on the side
// already swept. The front's position is a real, continuously draggable
// value (mouse, touch or keyboard) — there is no autoplay-only, one-shot
// "reveal" here: dragging it back un-sweeps the transition exactly as far
// as you pull it, because both the CSS clip and the noise band are pure
// functions of the current front value, not of a play/finished state
// machine. That reversibility is what keeps this a spatial transition
// mechanic instead of the scramble-text restyle this registry holds a
// standing position against (text-decrypt, background-ascii-dither already
// own "characters churn in place").
//
// Distinct from text-decrypt / text-ascii-cascade (identity churn or
// physical fall of a STRING's own characters, no front, no drag, one-shot),
// scroll-defrost (a shader anneal driven by scroll with no discrete
// draggable front and no second DOM panel underneath), and
// transition-panel-crumble (a full-screen physics pour between two REAL
// panels, gravity-timed and irreversible once triggered — this component's
// front is a live, bidirectional value the user parks anywhere, not a
// particle simulation that plays once).
// ---------------------------------------------------------------------------

export interface AsciiDissolveTransitionProps {
  /** outgoing content, visible where the front hasn't swept yet */
  from: ReactNode;
  /** incoming content, visible where the front has already swept */
  to: ReactNode;
  /** controlled front position, 0 (all `from`) .. 1 (all `to`) */
  value?: number;
  /** initial front position when uncontrolled. Default 0.35 */
  defaultValue?: number;
  /** called with the new front position on every drag/keyboard change */
  onValueChange?: (value: number) => void;
  /** accessible name for the slider */
  label?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

const CELL = 12;
const BAND_PX = 90;
const CHARSET = "░▒▓█#%@*+=-:. ";

function smoothstep(t: number): number {
  const c = Math.max(0, Math.min(1, t));
  return c * c * (3 - 2 * c);
}

interface Tokens {
  fg: string;
  muted: string;
  border: string;
  accent: string;
}

function readTokens(): Tokens {
  const cs = getComputedStyle(document.documentElement);
  const get = (name: string, fallback: string) => cs.getPropertyValue(name).trim() || fallback;
  return {
    fg: get("--foreground", "#171717"),
    muted: get("--ns-muted", "#4d4d4d"),
    border: get("--border", "#ebebeb"),
    accent: get("--ns-accent", "#006bff"),
  };
}

function useTokens(): Tokens {
  const [tokens, setTokens] = useState<Tokens>(() =>
    typeof document === "undefined"
      ? { fg: "#171717", muted: "#4d4d4d", border: "#ebebeb", accent: "#006bff" }
      : readTokens()
  );
  useEffect(() => {
    const sync = () => setTokens(readTokens());
    sync();
    const mo = new MutationObserver(sync);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style"] });
    return () => mo.disconnect();
  }, []);
  return tokens;
}

function randomGlyph(): string {
  return CHARSET[Math.floor(Math.random() * CHARSET.length)];
}

export function AsciiDissolveTransition({
  from,
  to,
  value,
  defaultValue = 0.35,
  onValueChange,
  label = "Dissolve transition",
  className = "",
}: AsciiDissolveTransitionProps) {
  const uid = useId();
  const wrapRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const tokens = useTokens();

  const isControlled = value !== undefined;
  const [inner, setInner] = useState(defaultValue);
  const front = isControlled ? (value as number) : inner;

  const [dragging, setDragging] = useState(false);
  const [focused, setFocused] = useState(false);
  const reducedRef = useRef(false);

  useEffect(() => {
    reducedRef.current = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  }, []);

  function commit(next: number) {
    const clamped = Math.max(0, Math.min(1, next));
    if (!isControlled) setInner(clamped);
    onValueChange?.(clamped);
  }

  function posFromClientX(clientX: number): number {
    const rect = wrapRef.current?.getBoundingClientRect();
    if (!rect || rect.width === 0) return front;
    return Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
  }

  function handlePointerDown(e: ReactPointerEvent<HTMLDivElement>) {
    e.currentTarget.setPointerCapture(e.pointerId);
    setDragging(true);
    commit(posFromClientX(e.clientX));
  }
  function handlePointerMove(e: ReactPointerEvent<HTMLDivElement>) {
    if (dragging) commit(posFromClientX(e.clientX));
  }
  function endDrag() {
    setDragging(false);
  }
  function handleKeyDown(e: ReactKeyboardEvent<HTMLDivElement>) {
    let next = front;
    if (e.key === "ArrowLeft") next -= 0.02;
    else if (e.key === "ArrowRight") next += 0.02;
    else if (e.key === "PageDown") next -= 0.1;
    else if (e.key === "PageUp") next += 0.1;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = 1;
    else return;
    e.preventDefault();
    commit(next);
  }

  useEffect(() => {
    const canvas = canvasRef.current;
    const wrap = wrapRef.current;
    if (!canvas || !wrap) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const rect = wrap.getBoundingClientRect();
    const w = Math.max(1, rect.width);
    const h = Math.max(1, rect.height);
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = w * dpr;
    canvas.height = h * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const cols = Math.ceil(w / CELL);
    const rows = Math.ceil(h / CELL);
    const frontX = front * w;

    let raf = 0;

    const draw = () => {
      ctx.clearRect(0, 0, w, h);

      for (let gy = 0; gy < rows; gy++) {
        for (let gx = 0; gx < cols; gx++) {
          const cx = gx * CELL + CELL / 2;
          const cy = gy * CELL + CELL / 2;
          const dist = Math.abs(cx - frontX);
          if (dist > BAND_PX) continue;
          const density = 1 - smoothstep(dist / BAND_PX);
          if (density < 0.02) continue;
          ctx.globalAlpha = density;
          ctx.fillStyle = dist < BAND_PX * 0.18 ? tokens.accent : tokens.fg;
          ctx.font = `${CELL - 2}px "GeistMono", ui-monospace, monospace`;
          ctx.textAlign = "center";
          ctx.textBaseline = "middle";
          ctx.fillText(randomGlyph(), cx, cy);
        }
      }
      ctx.globalAlpha = 1;

      // seam line
      ctx.strokeStyle = tokens.accent;
      ctx.lineWidth = dragging || focused ? 2 : 1.5;
      ctx.beginPath();
      ctx.moveTo(Math.round(frontX) + 0.5, 0);
      ctx.lineTo(Math.round(frontX) + 0.5, h);
      ctx.stroke();

      // churn continues only while the front is actively being interacted
      // with (dragged or keyboard-focused); otherwise one frozen frame
      // stands, matching reduced-motion behavior and keeping this cheap at
      // rest.
      if (!reducedRef.current && (dragging || focused)) {
        raf = requestAnimationFrame(draw);
      }
    };

    draw();
    return () => cancelAnimationFrame(raf);
  }, [tokens, front, dragging, focused]);

  return (
    <div
      ref={wrapRef}
      className={`ns-tad relative overflow-hidden rounded-sm border border-border ${className}`}
    >
      <style>{CSS}</style>

      {/* incoming panel — always full, sits underneath */}
      <div className="absolute inset-0" aria-hidden={front < 0.5}>
        {to}
      </div>

      {/* outgoing panel — hard-clipped to the unswept region */}
      <div
        className="absolute inset-0"
        aria-hidden={front >= 0.5}
        style={{ clipPath: `inset(0 0 0 ${front * 100}%)` }}
      >
        {from}
      </div>

      <canvas ref={canvasRef} aria-hidden="true" className="pointer-events-none absolute inset-0 h-full w-full" />

      <div
        id={`${uid}-handle`}
        role="slider"
        tabIndex={0}
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={Math.round(front * 100)}
        aria-valuetext={`${Math.round(front * 100)}% resolved`}
        aria-orientation="horizontal"
        className="ns-tad-handle absolute inset-0 cursor-col-resize touch-none outline-none"
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={endDrag}
        onPointerCancel={endDrag}
        onKeyDown={handleKeyDown}
        onFocus={() => setFocused(true)}
        onBlur={() => {
          setFocused(false);
          setDragging(false);
        }}
      />
    </div>
  );
}

const CSS = `
.ns-tad-handle:focus-visible { outline: 2px solid var(--ns-accent); outline-offset: -2px; }
.ns-tad-handle:hover { background: linear-gradient(90deg, transparent 0%, color-mix(in srgb, var(--ns-accent) 8%, transparent) 50%, transparent 100%); }
`;

"use client";

import { useEffect, useLayoutEffect, useRef, useState } from "react";

type ViewId = "overview" | "detail";
type Tone = "foreground" | "muted" | "border" | "accent";

interface RegionRect {
  x: number;
  y: number;
  w: number;
  h: number;
  tone: Tone;
}

interface Grain {
  x: number;
  y: number;
  ox: number;
  oy: number;
  tx: number;
  ty: number;
  rgb: string;
  baseAlpha: number;
  size: number;
  delay: number;
  matched: boolean;
  driftX: number;
  localSpan: number; // ms available for this grain's own animation (duration - delay)
}

interface RGB {
  r: number;
  g: number;
  b: number;
}

const DURATION = 900; // ms, full pour simulation
const REDUCED_FADE = 150; // ms, reduced-motion / low-power substitute
const GRAVITY_MATCHED = 1500; // px/s^2, fades out as the funnel takes over
const GRAVITY_FALL = 2100; // px/s^2, unmatched (departing) grains
const K_START = 4; // funnel spring constant at release
const K_END = 150; // funnel spring constant at settle
const DAMP_MATCHED = 0.9;
const DAMP_FALL = 0.995;
const MAX_GRAINS = 4000;
const LOW_POWER_THRESHOLD_MS = 45;
const EDGE_FADE_PX = 24; // px band, inside the canvas, over which a grain dissolves before it would reach the container's edge — matches the layout's own p-6 padding

function smoothstep(t: number) {
  const c = Math.min(1, Math.max(0, t));
  return c * c * (3 - 2 * c);
}

function clamp01(v: number) {
  return Math.min(1, Math.max(0, v));
}

// deterministic-enough color parsing for the four house tokens (hex or rgb()).
function parseColor(raw: string): RGB | null {
  const v = raw.trim();
  if (!v) return null;
  if (v.startsWith("#")) {
    const hex = v.slice(1);
    if (hex.length === 3) {
      const r = parseInt(hex[0] + hex[0], 16);
      const g = parseInt(hex[1] + hex[1], 16);
      const b = parseInt(hex[2] + hex[2], 16);
      if ([r, g, b].some(Number.isNaN)) return null;
      return { r, g, b };
    }
    if (hex.length >= 6) {
      const r = parseInt(hex.slice(0, 2), 16);
      const g = parseInt(hex.slice(2, 4), 16);
      const b = parseInt(hex.slice(4, 6), 16);
      if ([r, g, b].some(Number.isNaN)) return null;
      return { r, g, b };
    }
    return null;
  }
  const m = v.match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/);
  if (m) return { r: Number(m[1]), g: Number(m[2]), b: Number(m[3]) };
  return null;
}

function rgbString(rgb: RGB | null, fallback: string) {
  if (!rgb) return fallback;
  return `${rgb.r},${rgb.g},${rgb.b}`;
}

// a fixed amount of arithmetic timed synchronously: on a throttled/low-power
// device this takes visibly longer than on a normal one, standing in for a
// frame-budget check without needing to burn a real animation frame to learn
// it. The threshold errs toward NOT flagging: a false negative just runs the
// full pour (harmless), a false positive silently skips the signature effect.
function detectLowPower(): boolean {
  if (typeof performance === "undefined") return false;
  const t0 = performance.now();
  let acc = 0;
  for (let i = 0; i < 200_000; i++) {
    acc += Math.sqrt(i) * Math.sin(i);
  }
  const elapsed = performance.now() - t0;
  // guard against the loop being optimized away entirely
  return elapsed > LOW_POWER_THRESHOLD_MS || !Number.isFinite(acc);
}

function captureRects(container: HTMLElement): Map<string, RegionRect> {
  const cRect = container.getBoundingClientRect();
  const map = new Map<string, RegionRect>();
  container.querySelectorAll<HTMLElement>("[data-scree-id]").forEach((el) => {
    const id = el.dataset.screeId;
    if (!id) return;
    const r = el.getBoundingClientRect();
    if (r.width <= 0 || r.height <= 0) return;
    const tone = (el.dataset.screeTone as Tone) || "foreground";
    map.set(id, { x: r.left - cRect.left, y: r.top - cRect.top, w: r.width, h: r.height, tone });
  });
  return map;
}

function buildGrains(
  oldRects: Map<string, RegionRect>,
  newRects: Map<string, RegionRect>,
  rgbTable: Record<Tone, string>,
  budget: number
): Grain[] {
  const entries: { rect: RegionRect; match?: RegionRect }[] = [];
  let totalArea = 0;
  oldRects.forEach((rect, id) => {
    entries.push({ rect, match: newRects.get(id) });
    totalArea += Math.max(rect.w * rect.h, 1);
  });
  if (entries.length === 0) return [];

  const grains: Grain[] = [];
  for (const { rect, match } of entries) {
    const area = Math.max(rect.w * rect.h, 40);
    const count = Math.max(14, Math.round((budget * area) / totalArea));
    const rgb = rgbTable[rect.tone];
    for (let i = 0; i < count; i++) {
      const gx = rect.x + Math.random() * rect.w;
      const gy = rect.y + Math.random() * rect.h;
      const size = 2 + Math.random();
      const delay = Math.random() * 140;
      const baseAlpha = 0.62 + Math.random() * 0.32;
      if (match) {
        const tx = match.x + Math.random() * match.w;
        const ty = match.y + Math.random() * match.h;
        grains.push({
          x: gx,
          y: gy,
          ox: gx,
          oy: gy,
          tx,
          ty,
          rgb,
          baseAlpha,
          size,
          delay,
          matched: true,
          driftX: 0,
          localSpan: Math.max(120, DURATION - delay),
        });
      } else {
        grains.push({
          x: gx,
          y: gy,
          ox: gx,
          oy: gy,
          tx: gx,
          ty: rect.y + rect.h + 400,
          rgb,
          baseAlpha,
          size,
          delay,
          matched: false,
          driftX: (Math.random() - 0.5) * 70,
          localSpan: Math.max(120, DURATION - delay),
        });
      }
      if (grains.length >= MAX_GRAINS) return grains;
    }
  }
  return grains;
}

const LABELS: Record<ViewId, string> = {
  overview: "Overview",
  detail: "Sessions detail",
};

/**
 * A layout transition where the outgoing panel crumbles into token-colored
 * grains that pour into the incoming panel's silhouette — an hourglass turn
 * between a dashboard overview and a metric's detail pivot. The DOM swap
 * itself is instant and fully accessible from frame one (real content,
 * correct focus, a live-region announcement); the grains are a canvas
 * overlay riding on top that explains where the old layout's matter went,
 * then fades to nothing once the new layout has settled.
 */
export function ScreePour({
  className = "",
  grainBudget = 2400,
}: {
  /** extra classes merged onto the rendered root element */
  className?: string;
  /** total grains spawned per transition, distributed across regions by area */
  grainBudget?: number;
}) {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const panelRef = useRef<HTMLDivElement | null>(null);
  const headingOverviewRef = useRef<HTMLHeadingElement>(null);
  const headingDetailRef = useRef<HTMLHeadingElement>(null);
  const liveRef = useRef<HTMLParagraphElement>(null);

  const [active, setActive] = useState<ViewId>("overview");
  const [phase, setPhase] = useState<"idle" | "pouring">("idle");
  const [lastUpdated, setLastUpdated] = useState("just now");

  const phaseRef = useRef<"idle" | "pouring">("idle");
  const pendingRef = useRef<{ oldRects: Map<string, RegionRect>; next: ViewId } | null>(null);
  const rafRef = useRef(0);
  const colorsRef = useRef<Record<Tone, string>>({
    foreground: "23,23,23",
    muted: "77,77,77",
    border: "235,235,235",
    accent: "0,107,255",
  });
  const reducedMotionRef = useRef(false);
  const lowPowerRef = useRef(false);

  // theme tokens: read at mount, re-read whenever <html>'s class changes
  useEffect(() => {
    const read = () => {
      const cs = getComputedStyle(document.documentElement);
      colorsRef.current = {
        foreground: rgbString(
          parseColor(cs.getPropertyValue("--foreground")),
          colorsRef.current.foreground
        ),
        muted: rgbString(parseColor(cs.getPropertyValue("--ns-muted")), colorsRef.current.muted),
        border: rgbString(parseColor(cs.getPropertyValue("--border")), colorsRef.current.border),
        accent: rgbString(parseColor(cs.getPropertyValue("--ns-accent")), colorsRef.current.accent),
      };
    };
    read();
    const mo = new MutationObserver(read);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class"] });
    return () => mo.disconnect();
  }, []);

  // prefers-reduced-motion, live
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    reducedMotionRef.current = mq.matches;
    const onChange = (e: MediaQueryListEvent) => {
      reducedMotionRef.current = e.matches;
    };
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  // one-shot frame-budget check standing in for low-power device detection
  useEffect(() => {
    lowPowerRef.current = detectLowPower();
  }, []);

  // canvas backing store tracks the container, dpr-clamped
  useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;
    const resize = () => {
      const rect = container.getBoundingClientRect();
      const dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.max(1, Math.round(rect.width * dpr));
      canvas.height = Math.max(1, Math.round(rect.height * dpr));
      const ctx = canvas.getContext("2d");
      if (ctx) ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };
    resize();
    const ro = new ResizeObserver(resize);
    ro.observe(container);
    return () => ro.disconnect();
  }, []);

  const runPour = (oldRects: Map<string, RegionRect>, newRects: Map<string, RegionRect>) => {
    const canvas = canvasRef.current;
    if (!canvas) {
      phaseRef.current = "idle";
      setPhase("idle");
      return;
    }
    const ctx = canvas.getContext("2d");
    if (!ctx) {
      phaseRef.current = "idle";
      setPhase("idle");
      return;
    }
    const grains = buildGrains(oldRects, newRects, colorsRef.current, grainBudget);
    if (grains.length === 0) {
      phaseRef.current = "idle";
      setPhase("idle");
      return;
    }

    const start = performance.now();
    let lastT = start;

    const frame = (now: number) => {
      const elapsed = now - start;
      const dt = Math.min(0.05, (now - lastT) / 1000);
      lastT = now;
      const w = canvas.clientWidth;
      const h = canvas.clientHeight;
      ctx.clearRect(0, 0, w, h);

      for (const g of grains) {
        const gElapsed = elapsed - g.delay;
        if (gElapsed < 0) {
          // not yet released: sits at its spawn point, still solid (still
          // subject to the edge fade below — a region tagged right at the
          // container's edge shouldn't spawn a hard-edged dot either)
          const spawnEdge = smoothstep(
            clamp01(Math.min(g.x, w - g.x, g.y, h - g.y) / EDGE_FADE_PX)
          );
          const spawnAlpha = g.baseAlpha * spawnEdge;
          if (spawnAlpha > 0.01) {
            ctx.fillStyle = `rgba(${g.rgb},${spawnAlpha.toFixed(3)})`;
            ctx.fillRect(g.x - g.size / 2, g.y - g.size / 2, g.size, g.size);
          }
          continue;
        }
        const localT = clamp01(gElapsed / g.localSpan);
        let alpha: number;
        if (g.matched) {
          const k = K_START + (K_END - K_START) * smoothstep(localT);
          const gravity = GRAVITY_MATCHED * (1 - smoothstep(localT));
          const ax = (g.tx - g.x) * k;
          const ay = (g.ty - g.y) * k + gravity;
          const vx = (g.x - g.ox) * DAMP_MATCHED;
          const vy = (g.y - g.oy) * DAMP_MATCHED;
          g.ox = g.x;
          g.oy = g.y;
          g.x += vx + ax * dt * dt;
          g.y += vy + ay * dt * dt;
          const fadeT = clamp01((localT - 0.6) / 0.4);
          alpha = g.baseAlpha * (1 - smoothstep(fadeT));
        } else {
          const ax = g.driftX;
          const ay = GRAVITY_FALL;
          const vx = (g.x - g.ox) * DAMP_FALL;
          const vy = (g.y - g.oy) * DAMP_FALL;
          g.ox = g.x;
          g.oy = g.y;
          g.x += vx + ax * dt * dt;
          g.y += vy + ay * dt * dt;
          const fadeT = clamp01((localT - 0.5) / 0.5);
          alpha = g.baseAlpha * (1 - smoothstep(fadeT));
        }
        // Fade by proximity to the canvas bounds, not just elapsed time.
        // Time-based fade alone lets a falling (unmatched) grain reach the
        // bottom edge at near-full alpha — gravity gets it there in ~350-450ms,
        // right as its own fade window (localT > 0.5/0.6) has barely started —
        // so a bright, undecayed mass arrives at the boundary together and
        // then hard-clips at the canvas edge, reading as a wall of litter at
        // the edges instead of a dissolve. This tapers alpha to 0 over the
        // last EDGE_FADE_PX (matches the layout's own p-6 padding, so settled
        // matched content — which lives inside that padding — is never
        // touched by it) before a grain would ever reach the boundary.
        const distToEdge = Math.min(g.x, w - g.x, g.y, h - g.y);
        alpha *= smoothstep(clamp01(distToEdge / EDGE_FADE_PX));
        if (alpha <= 0.01) continue;
        ctx.fillStyle = `rgba(${g.rgb},${alpha.toFixed(3)})`;
        ctx.fillRect(g.x - g.size / 2, g.y - g.size / 2, g.size, g.size);
      }

      if (elapsed < DURATION) {
        rafRef.current = requestAnimationFrame(frame);
      } else {
        ctx.clearRect(0, 0, w, h);
        rafRef.current = 0;
        phaseRef.current = "idle";
        setPhase("idle");
      }
    };
    rafRef.current = requestAnimationFrame(frame);
  };

  // after a triggered view swap commits, measure the new layout and either
  // run the full pour or (reduced motion / low power) a plain 150ms fade.
  useLayoutEffect(() => {
    const pending = pendingRef.current;
    if (!pending || pending.next !== active) return;
    pendingRef.current = null;

    const headingEl = active === "detail" ? headingDetailRef.current : headingOverviewRef.current;
    headingEl?.focus();

    if (reducedMotionRef.current || lowPowerRef.current) {
      const panelEl = panelRef.current;
      if (panelEl) {
        // floor at 0.6, never 0 — the panel must never read as transparent,
        // even a single check instant after this branch runs
        panelEl.style.opacity = "0.6";
        panelEl.style.transition = `opacity ${REDUCED_FADE}ms cubic-bezier(0.16,1,0.3,1)`;
        requestAnimationFrame(() => {
          panelEl.style.opacity = "1";
        });
        window.setTimeout(() => {
          panelEl.style.transition = "";
        }, REDUCED_FADE + 40);
      }
      phaseRef.current = "idle";
      setPhase("idle");
      return;
    }

    const container = containerRef.current;
    if (!container) {
      phaseRef.current = "idle";
      setPhase("idle");
      return;
    }
    const newRects = captureRects(container);
    runPour(pending.oldRects, newRects);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [active]);

  useEffect(() => {
    return () => cancelAnimationFrame(rafRef.current);
  }, []);

  const trigger = (next: ViewId) => {
    if (phaseRef.current === "pouring") return;
    if (liveRef.current) liveRef.current.textContent = `Now showing: ${LABELS[next]}`;
    const container = containerRef.current;
    if (!container) {
      setActive(next);
      return;
    }
    const oldRects = captureRects(container);
    pendingRef.current = { oldRects, next };
    phaseRef.current = "pouring";
    setPhase("pouring");
    setActive(next);
  };

  const refresh = () => setLastUpdated(new Date().toLocaleTimeString());

  const triggerClass =
    "inline-flex items-center gap-1.5 rounded-sm border border-ns-accent px-3 py-1.5 text-xs font-medium text-ns-accent transition-colors hover:text-ns-accent-hover focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ns-accent disabled:opacity-60 disabled:pointer-events-none";

  return (
    <div
      ref={containerRef}
      className={`relative overflow-hidden rounded-lg border border-border bg-background ${className}`}
    >
      <p ref={liveRef} aria-live="polite" className="sr-only" />

      {active === "overview" ? (
        <div ref={panelRef} data-scree-view="overview" className="flex h-full flex-col gap-6 p-6">
          <div className="flex items-center justify-between gap-3">
            <h2
              ref={headingOverviewRef}
