/**
 * CYBR//UI · Boot Sequence Loader
 * MIT License · Copyright (c) 2026 JLTDigital and Jonathan Taft
 * https://cybr-ui.com/docs/components/boot-sequence-loader
 * https://github.com/JLTDigital/cybr-ui
 */
"use client";

import { useEffect, useRef, useState, type ComponentProps } from "react";

import { useReducedMotion } from "@/lib/use-reduced-motion";
import { cn } from "@/lib/utils";

export type BootLine = { text: string; status: string };

const DEFAULT_LINE_MS = 1000;

// Boot log that prints one line per lineDuration and fills each line's status
// in --signal when the next step starts, then calls onComplete once. The log is
// aria-hidden; a visually hidden status region announces only the final line.
// Static-first: the server, no-JS and reduced-motion render is the full log.
export function BootSequenceLoader({
  lines,
  lineDuration = DEFAULT_LINE_MS,
  onComplete,
  className,
  ...props
}: Omit<ComponentProps<"div">, "children"> & {
  lines: BootLine[];
  lineDuration?: number;
  onComplete?: () => void;
}) {
  const reduced = useReducedMotion();
  const [step, setStep] = useState<number | null>(null);
  const onCompleteRef = useRef(onComplete);

  useEffect(() => {
    onCompleteRef.current = onComplete;
  });

  const count = lines.length;
  const duration = Number.isFinite(lineDuration) && lineDuration > 0 ? lineDuration : DEFAULT_LINE_MS;
  const signature = lines.map((line) => `${line.text}\u0000${line.status}`).join("\n");

  useEffect(() => {
    // Deferred so the hydration pass, which always reports reduced motion,
    // cancels it if the real preference turns out to allow motion.
    if (reduced) {
      const timer = setTimeout(() => onCompleteRef.current?.(), 0);
      return () => clearTimeout(timer);
    }
    let current = -1;
    let timer: ReturnType<typeof setTimeout>;
    const advance = () => {
      current += 1;
      setStep(current);
      if (current >= count) onCompleteRef.current?.();
      else timer = setTimeout(advance, duration);
    };
    timer = setTimeout(advance, 0);
    return () => {
      clearTimeout(timer);
      setStep(null);
    };
  }, [reduced, signature, count, duration]);

  const settled = reduced || step === null;
  const shown = settled ? count : Math.min(count, step + 1);
  const done = settled ? count : step;
  const last = lines[count - 1];
  const announcement = done >= count && last ? `${last.text.replace(/[.\s]+$/, "")} ${last.status}` : "";

  return (
    <div
      className={cn("bg-ground-void px-8 py-6 font-mono text-xs leading-[1.65] text-label", className)}
      {...props}
    >
      <p role="status" className="sr-only">
        {announcement}
      </p>
      <div aria-hidden="true">
        {lines.slice(0, shown).map((line, i) => (
          <div key={i} className="whitespace-pre">
            {line.text}
            {i < done && <span className="text-signal">{line.status}</span>}
          </div>
        ))}
        <span className="inline-block h-3.75 w-2.25 bg-current align-[-2px] text-signal cursor-blink" />
      </div>
    </div>
  );
}

/**
 * CYBR//UI · Segmented Progress
 * MIT License · Copyright (c) 2026 JLTDigital and Jonathan Taft
 * https://cybr-ui.com/docs/components/segmented-progress
 * https://github.com/JLTDigital/cybr-ui
 */
import type { ComponentProps, ReactNode } from "react";

import { cn } from "@/lib/utils";

function finiteOr(n: number, fallback: number) {
  return Number.isFinite(n) ? n : fallback;
}

// Determinate progress as a row of hard segments under a big padded readout.
// The track is the progressbar; the readout repeats its value, so it is
// aria-hidden. Segments snap on and off with no animation.
export function SegmentedProgress({
  value,
  max = 100,
  segments = 20,
  label,
  phase,
  showValue = true,
  className,
  ...props
}: Omit<ComponentProps<"div">, "children"> & {
  value: number;
  max?: number;
  segments?: number;
  label: string;
  phase?: ReactNode;
  showValue?: boolean;
}) {
  const limit = finiteOr(max, 100) > 0 ? max : 100;
  const count = Math.max(1, Math.floor(finiteOr(segments, 20)));
  const current = Math.min(limit, Math.max(0, finiteOr(value, 0)));
  const filled = Math.floor((current / limit) * count);
  const percent = Math.round((current / limit) * 100);

  return (
    <div className={cn("flex flex-col gap-3 font-mono text-ink", className)} {...props}>
      {(showValue || phase) && (
        <div className="flex items-baseline justify-between gap-4">
          {showValue ? (
            <span aria-hidden="true" className="font-display text-[4rem] leading-[0.9] tabular-nums">
              {String(percent).padStart(3, "0")}%
            </span>
          ) : (
            <span />
          )}
          {phase && <span className="text-caption tracking-label text-label">{phase}</span>}
        </div>
      )}
      <div
        role="progressbar"
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={limit}
        aria-valuenow={current}
        className="grid h-5.5 gap-1 border-(length:--border-base) border-ink p-0.75"
        style={{ gridTemplateColumns: `repeat(${count}, minmax(0, 1fr))` }}
      >
        {Array.from({ length: count }, (_, i) => (
          <span key={i} className={i < filled ? "bg-signal" : undefined} />
        ))}
      </div>
    </div>
  );
}

/**
 * CYBR//UI · Data-Readout Carousel
 * MIT License · Copyright (c) 2026 JLTDigital and Jonathan Taft
 * https://cybr-ui.com/docs/components/data-readout-carousel
 * https://github.com/JLTDigital/cybr-ui
 */
"use client";

import { useState, type ComponentProps, type KeyboardEvent, type ReactNode } from "react";

import { cn } from "@/lib/utils";

const button =
  "flex min-h-11 cursor-pointer items-center gap-1.5 border-0 bg-transparent px-4 font-mono text-xs font-bold tracking-label text-ink aria-[disabled=false]:hover:bg-bg aria-disabled:cursor-not-allowed aria-disabled:text-dim focus-visible:outline-(length:--focus-width) focus-visible:outline-offset-[-3px] focus-visible:outline-solid focus-visible:outline-signal";

function pad(n: number) {
  return String(n).padStart(2, "0");
}

function isTextField(target: EventTarget) {
  return (
    target instanceof HTMLElement &&
    (target.isContentEditable || ["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName))
  );
}

// Framed slide viewer with a 01 / 08 counter, PREV / NEXT buttons and a
// decorative segment strip. Inactive slides stay in the DOM with `hidden`, so
// the server and no-JS render show slide 1. After the first change, each slide
// that is shown plays a short stepped wipe (off under reduced motion), because
// CSS animations restart when an element leaves display: none. The end buttons
// use aria-disabled, not disabled, so focus stays on them at the first or last
// slide and the arrow keys keep working.
export function DataReadoutCarousel({
  label,
  slides,
  index,
  defaultIndex = 0,
  onIndexChange,
  loop = false,
  className,
  onKeyDown,
  ...props
}: Omit<ComponentProps<"section">, "children" | "aria-label"> & {
  label: string;
  slides: ReactNode[];
  index?: number;
  defaultIndex?: number;
  onIndexChange?: (index: number) => void;
  loop?: boolean;
}) {
  const [inner, setInner] = useState(defaultIndex);
  const [moved, setMoved] = useState(false);
  const total = slides.length;
  const raw = index ?? inner;
  const current = total === 0 ? 0 : Math.min(total - 1, Math.max(0, Number.isFinite(raw) ? Math.trunc(raw) : 0));
  const canPrev = total > 1 && (loop || current > 0);
  const canNext = total > 1 && (loop || current < total - 1);

  const go = (step: -1 | 1) => {
    if (step === -1 ? !canPrev : !canNext) return;
    const next = (current + step + total) % total;
    if (index === undefined) setInner(next);
    setMoved(true);
    onIndexChange?.(next);
  };

  return (
    <section
      aria-roledescription="carousel"
      aria-label={label}
      className={cn("flex flex-col border-(length:--border-base) border-line bg-bg font-mono", className)}
      onKeyDown={(event: KeyboardEvent<HTMLElement>) => {
        onKeyDown?.(event);
        if (event.defaultPrevented || isTextField(event.target)) return;
        if (event.key === "ArrowLeft" || event.key === "ArrowRight") {
          event.preventDefault();
          go(event.key === "ArrowLeft" ? -1 : 1);
        }
      }}
      {...props}
    >
      <div className="flex items-center justify-between gap-4 border-b-(length:--border-base) border-line bg-ground-deep px-5 py-3 text-xs tracking-label">
        <span className="text-label">{label}</span>
        <span aria-hidden="true" className="tabular-nums">
          <span className="text-signal">{pad(total === 0 ? 0 : current + 1)}</span>
          <span className="text-label"> / {pad(total)}</span>
        </span>
      </div>
      <div aria-live="polite" className="relative">
        {slides.map((slide, i) => (
          <div
            key={i}
            role="group"
            aria-roledescription="slide"
            aria-label={`${i + 1} of ${total}`}
            hidden={i !== current}
            className={cn(moved && "wipe-reveal [animation-duration:300ms]")}
          >
            {slide}
          </div>
        ))}
      </div>
      <div className="flex items-stretch justify-between gap-4 border-t-(length:--border-base) border-line bg-ground-deep">
        <button type="button" aria-label="Previous slide" aria-disabled={!canPrev} onClick={() => go(-1)} className={button}>
          <span aria-hidden="true">[ ← PREV ]</span>
        </button>
        <span
          aria-hidden="true"
          className="grid max-w-60 flex-1 items-center gap-1"
          style={{ gridTemplateColumns: `repeat(${Math.max(1, total)}, minmax(0, 1fr))` }}
        >
          {slides.map((_, i) => (
            <span key={i} className={cn("h-1.5", i === current ? "bg-signal" : "bg-line")} />
          ))}
        </span>
        <button type="button" aria-label="Next slide" aria-disabled={!canNext} onClick={() => go(1)} className={button}>
          <span aria-hidden="true">[ NEXT → ]</span>
        </button>
      </div>
    </section>
  );
}

