// ⌘K / Ctrl+K command dialog on Base UI: a Dialog holding an always-open,
// inline Autocomplete, as in Base UI's own command-palette example. Typing
// filters items by label; Enter or a click runs onSelect and closes. The
// dialog and its input unmount on close, so the query starts empty each time.
// Nothing animates.
export function CommandPalette({
  groups,
  onSelect,
  open,
  defaultOpen = false,
  onOpenChange,
  shortcut = true,
  shortcutLabel = "⌘K",
  trigger,
  label = "Command palette",
  placeholder = "Type a command…",
  className,
}: {
  groups: CommandPaletteGroup[];
  onSelect: (value: string) => void;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  shortcut?: boolean;
  shortcutLabel?: string;
  trigger?: ReactNode | false;
  label?: string;
  placeholder?: string;
  className?: string;
}) {
  const [innerOpen, setInnerOpen] = useState(defaultOpen);
  const isOpen = open ?? innerOpen;
  const instructionsId = useId();

  const setOpen = (next: boolean) => {
    if (open === undefined) setInnerOpen(next);
    onOpenChange?.(next);
  };

  useEffect(() => {
    if (!shortcut) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.isComposing || event.key.toLowerCase() !== "k" || !(event.metaKey || event.ctrlKey)) return;
      event.preventDefault();
      if (open === undefined) setInnerOpen(!isOpen);
      onOpenChange?.(!isOpen);
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [shortcut, isOpen, open, onOpenChange]);

  return (
    <Dialog.Root open={isOpen} onOpenChange={setOpen}>
      {trigger !== false && (
        <Dialog.Trigger
          className={cn(
            "inline-flex min-h-11 cursor-pointer items-center gap-3 border-(length:--border-base) border-line bg-ground-deep pr-1.5 pl-4 font-mono text-xs font-bold tracking-label text-ink hover:border-ink",
            focus,
            className,
          )}
        >
          {trigger ?? "SEARCH"}
          <kbd className="border-(length:--border-hair) border-line bg-ground-void px-2 py-1 font-mono text-caption font-normal text-label">
            {shortcutLabel}
          </kbd>
        </Dialog.Trigger>
      )}
      <Dialog.Portal>
        <Dialog.Backdrop className="fixed inset-0 z-50 bg-ground-void/80" />
        <Dialog.Viewport className="fixed inset-0 z-50 flex items-start justify-center px-4 pt-[15vh]">
          <Dialog.Popup
            aria-label={label}
            className="flex w-full max-w-160 flex-col border-(length:--border-base) border-line bg-ground-deep font-mono text-ink shadow-hard outline-none"
          >
            <Autocomplete.Root open inline items={groups} autoHighlight="always" keepHighlight>
              <Autocomplete.InputGroup className="flex items-center gap-3 border-b-(length:--border-base) border-line px-4">
                <span aria-hidden="true" className="text-signal">
                  &gt;
                </span>
                <Autocomplete.Input
                  aria-label="Search commands"
                  aria-describedby={instructionsId}
                  placeholder={placeholder}
                  className="h-13 min-w-0 flex-1 border-0 bg-transparent font-mono text-sm text-ink caret-signal outline-none placeholder:text-label"
                />
              </Autocomplete.InputGroup>
              <Dialog.Close className="sr-only">Close</Dialog.Close>
              <div className="max-h-[min(60dvh,24rem)] overflow-y-auto overscroll-contain">
                <Autocomplete.Empty>
                  <p className="m-0 px-4 py-8 text-center text-xs tracking-label text-label">NO MATCH // 0 RESULTS</p>
                </Autocomplete.Empty>
                <Autocomplete.List className="py-1">
                  {(group: CommandPaletteGroup) => (
                    <Autocomplete.Group key={group.label} items={group.items} className="pb-1">
                      <Autocomplete.GroupLabel className="px-4 pt-3 pb-1.5 text-micro tracking-label text-label">
                        {"// "}
                        {group.label}
                      </Autocomplete.GroupLabel>
                      <Autocomplete.Collection>
                        {(entry: CommandPaletteItem) => (
                          <Autocomplete.Item
                            key={entry.value}
                            value={entry}
                            onClick={() => {
                              onSelect(entry.value);
                              setOpen(false);
                            }}
                            className="flex min-h-10 cursor-pointer items-center justify-between gap-4 px-4 text-[0.8125rem] text-ink data-highlighted:bg-signal data-highlighted:text-ground-deep"
                          >
                            <span>{entry.label}</span>
                            {entry.hint && (
                              <span className="text-caption tracking-label text-label in-data-highlighted:text-ground-deep">
                                {entry.hint}
                              </span>
                            )}
                          </Autocomplete.Item>
                        )}
                      </Autocomplete.Collection>
                    </Autocomplete.Group>
                  )}
                </Autocomplete.List>
              </div>
              <div className="flex items-center justify-between gap-4 border-t-(length:--border-base) border-line bg-ground-void px-4 py-2 text-micro tracking-label text-label">
                <span aria-hidden="true">↑↓ NAVIGATE · ↵ RUN · ESC CLOSE</span>
                <span id={instructionsId} className="sr-only">
                  Use the up and down arrows to move through commands, Enter to run one and Escape to close.
                </span>
                <ResultCount />
              </div>
            </Autocomplete.Root>
          </Dialog.Popup>
        </Dialog.Viewport>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

/**
 * CYBR//UI · Pixelated Image Trail
 * MIT License · Copyright (c) 2026 JLTDigital and Jonathan Taft
 * https://cybr-ui.com/docs/components/pixelated-image-trail
 * https://github.com/JLTDigital/cybr-ui
 */
"use client";

import { useEffect, useRef, useState, type ComponentProps, type PointerEvent } from "react";

import { useReducedMotion } from "@/lib/use-reduced-motion";
import { cn } from "@/lib/utils";

type Size = { width: number; height: number };
type Tile = { id: number; x: number; y: number; image: HTMLImageElement };

// Block sizes in CSS px: resolve in, hold sharp, step back out.
const FRAMES = [24, 12, 6, 3, 1, 3, 12, 24];
const FRAME_MS = 70;
const HOLD_MS = 400;
const SHARP = FRAMES.indexOf(1);

// Draws the image cover-fitted at 1/block resolution, then scales it up with
// smoothing off so each block is a hard square. Never reads pixels back, so
// cross-origin images draw without CORS setup.
function draw(canvas: HTMLCanvasElement, small: HTMLCanvasElement, image: HTMLImageElement, block: number, dpr: number) {
  const ctx = canvas.getContext("2d");
  const smallCtx = small.getContext("2d");
  if (!ctx || !smallCtx) return;
  const sw = Math.max(1, Math.round(canvas.width / (block * dpr)));
  const sh = Math.max(1, Math.round(canvas.height / (block * dpr)));
  small.width = sw;
  small.height = sh;
  const scale = Math.max(canvas.width / image.naturalWidth, canvas.height / image.naturalHeight);
  const cropW = canvas.width / scale;
  const cropH = canvas.height / scale;
  smallCtx.drawImage(image, (image.naturalWidth - cropW) / 2, (image.naturalHeight - cropH) / 2, cropW, cropH, 0, 0, sw, sh);
  ctx.imageSmoothingEnabled = false;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.drawImage(small, 0, 0, sw, sh, 0, 0, canvas.width, canvas.height);
}

function TrailTile({ tile, size, onDone }: { tile: Tile; size: Size; onDone: (id: number) => void }) {
  const ref = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const dpr = window.devicePixelRatio || 1;
    canvas.width = Math.round(size.width * dpr);
    canvas.height = Math.round(size.height * dpr);
    const small = document.createElement("canvas");
    let frame = 0;
    let timer: ReturnType<typeof setTimeout>;
    const step = () => {
      if (frame >= FRAMES.length) {
        onDone(tile.id);
        return;
      }
      draw(canvas, small, tile.image, FRAMES[frame], dpr);
      timer = setTimeout(step, frame === SHARP ? HOLD_MS : FRAME_MS);
      frame += 1;
    };
    step();
    return () => clearTimeout(timer);
  }, [tile, size.width, size.height, onDone]);

  return (
    <canvas
      ref={ref}
      className="absolute border-(length:--border-hair) border-line"
      style={{ left: tile.x - size.width / 2, top: tile.y - size.height / 2, width: size.width, height: size.height }}
    />
  );
}

// Host box that drops image tiles behind a mouse or pen. Each tile resolves
// from coarse pixels to sharp, holds, then steps back out and disappears.
// The trail layer is aria-hidden and ignores pointer events, so the children
// stay readable and clickable. No trail for touch, under reduced motion
// (reported until hydration finishes) or without JavaScript.
export function PixelatedImageTrail({
  images,
  spacing = 80,
  size = { width: 160, height: 120 },
  max = 8,
  className,
  children,
  onPointerMove,
  ...props
}: ComponentProps<"div"> & {
  images: string[];
  spacing?: number;
  size?: Size;
  max?: number;
}) {
  const reduced = useReducedMotion();
  const [tiles, setTiles] = useState<Tile[]>([]);
  const loaded = useRef<(HTMLImageElement | null)[]>([]);
  const last = useRef<{ x: number; y: number } | null>(null);
  const next = useRef(0);
  const ids = useRef(0);
  const signature = images.join("\n");

  useEffect(() => {
    const list: (HTMLImageElement | null)[] = images.map(() => null);
    loaded.current = list;
    images.forEach((src, i) => {
      const image = new Image();
      image.onload = () => {
        list[i] = image;
      };
      image.src = src;
    });
    return () => {
      loaded.current = [];
    };
    // `signature` stands in for the array, so a new array with the same URLs does not reload.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [signature]);

  const [removeTile] = useState(() => (id: number) => setTiles((all) => all.filter((t) => t.id !== id)));

  const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
    onPointerMove?.(event);
    if (reduced || event.pointerType === "touch") return;
    const rect = event.currentTarget.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    const gap = Math.max(1, spacing);
    if (last.current && Math.hypot(x - last.current.x, y - last.current.y) < gap) return;
    const ready = loaded.current;
    for (let tries = 0; tries < ready.length; tries += 1) {
      const index = (next.current + tries) % ready.length;
      const image = ready[index];
      if (!image) continue;
      next.current = index + 1;
      last.current = { x, y };
      ids.current += 1;
      const tile = { id: ids.current, x, y, image };
      setTiles((all) => [...all, tile].slice(-Math.max(1, max)));
      return;
    }
  };

  return (
    <div
      className={cn("relative isolate overflow-hidden", className)}
      onPointerMove={handlePointerMove}
      onPointerLeave={() => {
        last.current = null;
      }}
      {...props}
    >
      {children}
      <div aria-hidden="true" className="pointer-events-none absolute inset-0 z-10">
        {tiles.map((tile) => (
          <TrailTile key={tile.id} tile={tile} size={size} onDone={removeTile} />
        ))}
      </div>
    </div>
  );
}

