.furin-chime-bell {
  --furin-chime-bell-vidrio: #9ed8ff;
  --furin-chime-bell-pintura: #e8452c;
  --furin-chime-bell-tira: #ffffff;
  --furin-chime-bell-numero: #e8452c;
  --furin-chime-bell-soporte: #9a8f7d;

  position: relative;
  display: inline-block;
  flex: none;
  line-height: 0;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

.furin-chime-bell__dibujo {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
  --furin-chime-bell-brillo: 0;
}

/* Botón real para teclado y lectores de pantalla: invisible, pero enfocable. */
.furin-chime-bell__tocar {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  border: 0;
  opacity: 0;
}

.furin-chime-bell__tocar:focus-visible ~ .furin-chime-bell__dibujo {
  outline: 3px solid var(--furin-chime-bell-pintura);
  outline-offset: 4px;
