/* ---------- Badajo y tira ---------- */
.furin-chime-bell__hilo {
  stroke: var(--furin-chime-bell-pintura);
  stroke-width: 1.3;
  stroke-opacity: 0.85;
  stroke-linecap: round;
}

.furin-chime-bell__brillo-badajo {
  fill: #ffffff;
  fill-opacity: 0.85;
}

.furin-chime-bell__tira {
