}

.furin-chime-bell__papel {
  fill: var(--furin-chime-bell-tira);
  stroke: var(--furin-chime-bell-pintura);
  stroke-opacity: 0.55;
  stroke-width: 1;
}

.furin-chime-bell__marco {
  fill: none;
  stroke: var(--furin-chime-bell-pintura);
  stroke-opacity: 0.3;
  stroke-width: 1;
}

.furin-chime-bell__cabecera {
  stroke: var(--furin-chime-bell-pintura);
  stroke-opacity: 0.55;
  stroke-width: 1.2;
}

.furin-chime-bell__agujero {
  fill: var(--furin-chime-bell-pintura);
  fill-opacity: 0.55;
}

.furin-chime-bell__numero {
  fill: var(--furin-chime-bell-numero);
  font-family: inherit;
  font-variant-numeric: tabular-nums;
  user-select: none;
}

.furin-chime-bell__adorno circle {
  fill: var(--furin-chime-bell-pintura);
  fill-opacity: 0.45;
}

/* ---------- Ondas de sonido ---------- */
.furin-chime-bell__ecos path {
  fill: none;
  stroke: #ffffff;
  stroke-width: 2.4;
  stroke-linecap: round;
}

.furin-chime-bell__ecos {
  opacity: 0;
  pointer-events: none;
  transform-box: fill-box;
  transform-origin: center;
}

.furin-chime-bell__ecos--activos {
  animation: furin-chime-bell-eco 0.95s ease-out both;
}

@keyframes furin-chime-bell-eco {
  0% {
    opacity: 0;
    transform: scale(0.86);
  }
  18% {
    opacity: 0.85;
  }
  100% {
    opacity: 0;
    transform: scale(1.12);
  }
}

/* Movimiento reducido: las ondas solo aparecen y se desvanecen, sin crecer. */
@media (prefers-reduced-motion: reduce) {
  .furin-chime-bell__ecos--activos {
    animation-name: furin-chime-bell-eco-quieto;
  }
}

@keyframes furin-chime-bell-eco-quieto {
  0% {
    opacity: 0;
  }
  20% {
    opacity: 0.8;
  }
  100% {
    opacity: 0;
  }
}

