    const rg = g.createRadialGradient(x - r * 0.3, y - r * 0.3, 0, x, y, r);
    rg.addColorStop(0, "#fff"); rg.addColorStop(0.5, pal[3]); rg.addColorStop(1, pal[2]);
    g.shadowColor = pal[3]; g.shadowBlur = r * 2.2; g.fillStyle = rg;
