/** Glifos propios, trazo blanco de 1.8 en una cuadrícula de 24. */
function Glifo({ name }: { name: DockIconName }) {
  const p = { fill: "none", stroke: "currentColor", strokeWidth: 1.8, strokeLinecap: "round", strokeLinejoin: "round" } as const;
  return (
