/** Tarjeta de vidrio líquido: refracta lo que hay detrás, borde especular y un reflejo que persigue al cursor. */
export function GlassCard({
  children,
  caption = "",
  radius = 30,
  blur = 1.2,
  refraction = 1,
  dispersion = 0.12,
  tint = "rgba(255,255,255,0.10)",
  glare = 0.55,
  tilt = 6,
  scene = false,
  className = "",
  style,
