/* Copia invisible para lectores de pantalla: siempre dice el texto completo. */
.furin-gust__lectura {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

