}

/* La letra se mueve solo con transform: el flujo del texto no cambia nunca. */
.furin-gust__letra {
  position: relative;
  display: inline-block;
  transform-origin: 50% 58%;
}

/* La misma letra en el color de acento, encima: aparece a medida que la hoja se aleja de su sitio. */
