export interface LiquidChromeProps {
  /** Contenido que va encima del metal. */
  children?: ReactNode;
  /** Qué tan rápido fluye el metal. */
  speed?: number;
  /** Tamaño de las olas (menor = más olas). */
  scale?: number;
