/* Tonos del líquido derivados del color elegido. El primer stop-color es el respaldo sin color-mix. */
.furin-liquid-fill__c-hi { stop-color: var(--furin-liquid-fill-color); stop-color: color-mix(in oklab, var(--furin-liquid-fill-color) 70%, #fff); }
.furin-liquid-fill__c-glow { stop-color: var(--furin-liquid-fill-color); stop-color: color-mix(in oklab, var(--furin-liquid-fill-color) 52%, #fff); }
.furin-liquid-fill__c-mid { stop-color: var(--furin-liquid-fill-color); }
.furin-liquid-fill__c-mid2 { stop-color: var(--furin-liquid-fill-color); stop-color: color-mix(in oklab, var(--furin-liquid-fill-color) 86%, #020b12); }
.furin-liquid-fill__c-deep { stop-color: var(--furin-liquid-fill-color); stop-color: color-mix(in oklab, var(--furin-liquid-fill-color) 55%, #020b12); }

.furin-liquid-fill__tint { fill: var(--furin-liquid-fill-color); fill: color-mix(in oklab, var(--furin-liquid-fill-color) 82%, #fff); }

/* Porcentaje: sans con números tabulares y sombra suave para leerse sobre vidrio y líquido.
