          const v = ((e.clientX - s.lx) / (t - s.lt)) * 1000;
          s.boostT = Math.max(-1800, Math.min(1800, s.boostT * 0.5 + v * live.current.push * 0.5));
        }
        s.lx = e.clientX; s.lt = t;
      },
    });
