            <img
              className="ui-avtc__img"
              src={src}
              alt=""
              loading="lazy"
              decoding="async"
              draggable={false}
              onLoad={() => setLoaded(src)}
              onError={() => setFailed(src)}
              // A cached picture can finish before React listens – take it as loaded right away
              ref={(el) => {
                if (el?.complete && el.naturalWidth > 0) setLoaded(src);
              }}
