  --ui-ma-ok: var(--aui-success, #7dcf9f);
  --ui-ma-ok-bg: color-mix(in srgb, var(--aui-green, #7dcf9f) 12%, transparent);
  --ui-ma-tip-bg: #ededed;
  --ui-ma-tip-text: #171717;
  --ui-ma-focus: var(--aui-focus, rgba(77, 141, 255, 0.8));
}
