      aria-label={ariaLabel}
      className={["ui-pgnc", className].filter(Boolean).join(" ")}
      data-disabled={disabled || undefined}
      style={{ ...rest.style, "--ui-pgnc-digits": fmt.format(count).length } as CSSProperties}
