      role="radiogroup"
      aria-label={rest["aria-label"] ?? (rest["aria-labelledby"] ? undefined : "Rating")}
      aria-disabled={disabled || undefined}
      className={cls}
      data-size={sz}
      data-disabled={disabled || undefined}
      onPointerLeave={(e) => {
        setHover(null);
        rest.onPointerLeave?.(e);
