/* ---------- Helpers ---------- */

function useControllable<T>(value: T | undefined, initial: T, onChange?: (v: T) => void) {
  const [own, setOwn] = useState(initial);
  const controlled = value !== undefined;
  const set = (v: T) => {
    if (!controlled) setOwn(v);
    onChange?.(v);
  };
  return [controlled ? value : own, set] as const;
}

