/* ---------- Styles ---------- */

const css = /* css */ `
.ui-rd {
  --ui-rd-ease: cubic-bezier(0.22, 1, 0.36, 1);
  position: relative;
  width: 100%;
  aspect-ratio: 540 / 440;
}
.ui-rd-map,
.ui-rd-art {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
}

/* One full loop around the border every 14 seconds; the offsets keep the layers slightly staggered */
.ui-rd-band {
  animation: ui-rd-travel 14s linear infinite;
}
.ui-rd-band--1 {
  animation-delay: -0.42s;
}
.ui-rd-band--2 {
  animation-delay: -0.84s;
}
@keyframes ui-rd-travel {
  from {
    stroke-dashoffset: 0;
  }
  to {
    stroke-dashoffset: -1000;
  }
}

/* Switching: the old map fades and grows away, the new one settles in from slightly smaller */
.ui-rd-layer {
  transform-box: view-box;
  transform-origin: 270px 220px;
}
.ui-rd-layer[data-phase="enter"] {
  animation: ui-rd-in 520ms var(--ui-rd-ease) both;
}
.ui-rd-layer[data-phase="exit"] {
  animation: ui-rd-out 320ms cubic-bezier(0.4, 0, 1, 1) both;
}
@keyframes ui-rd-in {
  from {
    opacity: 0;
    transform: scale(0.94);
  }
}
@keyframes ui-rd-out {
  to {
    opacity: 0;
    transform: scale(1.04);
  }
}

/* ---------- Region menu ---------- */
.ui-rd-switch {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 1;
  padding: 12px;
  transform: scale(var(--ui-rd-s, 1));
  transform-origin: 0 0;
  font-family: inherit;
  -webkit-font-smoothing: antialiased;
}
.ui-rd-trigger {
  display: flex;
  align-items: center;
  gap: 4px;
  height: 28px;
  margin: 0;
  padding: 0 8px 0 12px;
  border: 1px solid #e5e5e5;
  border-radius: 999px;
  background: #ffffff;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04);
  color: #171717;
  font: inherit;
  font-size: 13px;
  font-weight: 500;
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
  transition: transform 160ms var(--ui-rd-ease);
}
.ui-rd-trigger:active {
  transform: scale(0.96);
}
.ui-rd-trigger:focus-visible {
  outline: 2px solid #a8b5ff;
  outline-offset: 2px;
}
.ui-rd-chevron {
  width: 14px;
  height: 14px;
  transition: transform 220ms var(--ui-rd-ease);
}
.ui-rd-trigger[aria-expanded="true"] .ui-rd-chevron {
  transform: rotate(180deg);
}

/* Opening morphs the panel out of a trigger-sized pill in its top-left corner */
.ui-rd-menu {
  --morph: 420ms cubic-bezier(0.32, 0.72, 0, 1);
  position: absolute;
  top: calc(12px + 28px + 6px);
