  const setView = useCallback((el: HTMLDivElement | null) => {
    view.current = el;
    assign(viewportRef, el);
  }, [viewportRef]);
  const setRoot = useCallback((el: HTMLDivElement | null) => {
    root.current = el;
    assign(ref, el);
  }, [ref]);

