        tabIndex={scrolls ? 0 : undefined}
        role={ariaLabel || ariaLabelledby ? "region" : undefined}
        aria-label={ariaLabel}
        aria-labelledby={ariaLabelledby}
        onScroll={scrolled}
      >
        <div ref={content} className="ui-sac__content">
          {children}
        </div>
      </div>
      {wantY && bar("y")}
      {wantX && bar("x")}
    </div>
  );
}

