        else move(1);
        break;
      case "ArrowUp":
        e.preventDefault();
        move(-1);
        break;
      case "PageDown":
        if (!open) return;
        e.preventDefault();
        move(page);
        break;
      case "PageUp":
        if (!open) return;
        e.preventDefault();
        move(-page);
        break;
      case "Enter":
