      {open && (
        <div
          ref={list}
          id={listId}
          className="ui-tpk__list"
          role="listbox"
          aria-labelledby={label != null ? labelId : undefined}
          aria-label={label == null ? ariaLabel ?? "Times" : undefined}
          popover="manual"
