  transform-origin: top center;
  animation: ui-tpkc-in 200ms var(--ui-tpkc-ease) both;
}
.ui-tpkc__list[data-up] { transform-origin: bottom center; animation-name: ui-tpkc-in-up; }
.ui-tpkc__list::backdrop { display: none; }

