.ui-tpkc__glow {
  position: absolute;
  top: 0;
  left: 4px;
  right: 4px;
  border-radius: 6px;
  background: var(--ui-tpkc-glow);
  pointer-events: none;
  transition: transform 160ms var(--ui-tpkc-ease), height 160ms var(--ui-tpkc-ease);
}

.ui-tpkc__option {
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  height: 32px;
  padding: 0 8px;
  border-radius: 6px;
  font-size: 13px;
  line-height: 20px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
