}
.ui-tclc__icon > svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.4; stroke-linecap: round; stroke-linejoin: round; }

.ui-tclc__main {
  display: flex;
  align-items: baseline;
  gap: 8px;
  flex: 1;
