export function VerifyEmail() {
  const [code, setCode] = useState("");
  const [status, setStatus] = useState<OtpStatus>("idle");
  const [triesLeft, setTriesLeft] = useState(3);

  async function verify(value: string) {
    setStatus("verifying");
    const res = await fetch("/api/verify", { method: "POST", body: JSON.stringify({ code: value }) });
    if (res.ok) {
      setStatus("success");
      router.push("/dashboard");
    } else {
      setTriesLeft((n) => n - 1);
      setStatus("error");
    }
  }

  return (
    <OtpInput
      value={code}
      onChange={(next) => {
        setCode(next);
        if (status === "error" && next) setStatus("idle");
      }}
      onComplete={verify}
      status={status}
      errorMessage={`That code didn't work. ${triesLeft} tries left.`}
      separator
      autoFocus
      onResend={() => fetch("/api/send-code", { method: "POST" })}
      resendIn={30}
    />
  );
}
```

### Props

| Name | Type | Default | Description |
| --- | --- | --- | --- |
| length | `number` | `6` | Number of boxes |
| separator | `boolean \| number` | `false` | A small dash between the boxes – true puts it in the middle, a number after that many boxes |
| numeric | `boolean` | `true` | Digits only with the numeric keyboard on phones; false allows letters too, shown in capitals |
| value | `string` |  | The code – makes the field controlled |
| defaultValue | `string` | `""` | Starting code when uncontrolled |
| onChange | `(code: string) => void` |  | Every change: typing, Backspace, paste, autofill and the clearing after an error |
| onComplete | `(code: string) => void` |  | Called once the last box is filled by the user – the place to start verifying |
| status | `"idle" \| "verifying" \| "error" \| "success"` | `"idle"` | Verifying shimmers and locks the field, error shakes and shows the message, success morphs into the pill |
| errorMessage | `ReactNode` | `"That code didn't work. Try again."` | Shown below the boxes after an error, until the user types again |
| clearOnError | `boolean` | `true` | Clears the boxes shortly after the shake, ready for the next try |
| successLabel | `string` | `"Verified"` | Text in the pill on success |
| onResend | `() => void` |  | Shows "Didn't get a code?" below the boxes with a countdown that becomes a Resend button; clicking restarts the countdown |
| resendIn | `number` | `30` | Seconds until the code can be resent |
| align | `"start" \| "center"` | `"start"` | Where the boxes and the lines below them sit |
| disabled | `boolean` | `false` | Dims the field and ignores input |
| autoFocus | `boolean` | `false` | Focuses the field on mount (without scrolling) |
| label | `string` | `"Verification code"` | Accessible name; the number of digits is added |
| className | `string` |  | Extra class on the root |

### Keyboard

- 0–9: Fills the active box and moves on; typing on a filled box replaces it
- ⌫: Clears the box and goes back one
- ← / →: Moves between the filled boxes and the next empty one
- Home / End: Jumps to the first box, or to the next empty one
- ⌘ / V: Pastes a whole code – spaces and dashes are ignored

### Accessibility

- One real text input carries the whole code, so screen readers hear one field ("Verification code, 6 digits") instead of six
- autocomplete="one-time-code" lets iOS and Android offer the code from an SMS; inputMode="numeric" opens the number pad
- Errors set aria-invalid and point to the message with aria-describedby; verifying, errors, success and resend are announced in a polite live region

### Motion

- A single focus ring glides from box to box with a softly blinking caret; digits pop in out of a short blur
- Pasted or autofilled codes fill the boxes one after another
- Verifying: a soft light passes over the boxes. Error: a calm shake, red borders, the message grows in below and the code fades out for the next try
- Success: the boxes slide together while one frame morphs its width into a "Verified" pill and the check draws in
- With prefers-reduced-motion everything switches instantly

### Responsive

- Container query: the boxes shrink to fit their container – six boxes with a separator fit a 320px phone
- Inputs use 16px text under the hood, so iOS doesn't zoom in on focus
- Dark mode built in: switches when an ancestor (usually <html>) has the class dark or data-theme="dark"

### Requirements

- React 19

Related: combobox, segmented-control, button, toaster

import type { ReactNode } from "react";

export type DemoFrameProps = {
  /** Header title. Leave it out for demos that draw their own app chrome. */
  title?: ReactNode;
  /** Muted text on the right of the header, e.g. "5 items". */
  meta?: ReactNode;
  /**
   * Controls on the right of the header. Bordered and filled controls sit on the 16px content
   * line; pass ghost buttons `edge="end"` so their icon or label lands on it instead.
   */
  actions?: ReactNode;
  /** Extra classes for the root, e.g. `select-none`. */
  className?: string;
  /** The frame's height in px. Default 420; a full app screen (a block with a sidebar) may ask for more. */
  height?: number;
  children: ReactNode;
};

/**
 * The standard Eased demo shell: 420px tall, 28rem wide unless a parent sets `--demo-width`,
 * shrinks to its container (never forces
 * horizontal scroll), 16px panel radius, and a 48px header with one title style. The root
 * is a size container, so demos adapt to the tile with `@max-sm:` and friends rather than
 * the viewport, and it exposes `--radius-outer`/`--pad` for concentric children. It sets
 * Eased's UI type (`text-ui`) and text colour, so a demo reads the same in any app.
 */
export function DemoFrame({ title, meta, actions, className = "", height, children }: DemoFrameProps) {
  return (
    <div
      // A gallery slot can cap the frame with --demo-max-height (the /components tiles do); the content then scrolls inside.
      style={height === undefined ? undefined : { height: `min(${height}px, var(--demo-max-height, ${height}px))` }}
      className={`@container relative flex h-[420px] w-full max-w-(--demo-width,28rem) min-w-0 flex-col overflow-hidden rounded-panel border border-line-subtle bg-surface text-ui text-text [--pad:16px] [--radius-outer:var(--eased-radius-panel)] ${className}`}
    >
      {title !== undefined && (
        <div
          className="flex h-12 shrink-0 items-center justify-between gap-3 border-b border-line-subtle px-(--pad)"
        >
          <div className="flex min-w-0 items-center gap-2 text-ui font-medium text-text">
            {typeof title === "string" ? <p className="truncate">{title}</p> : title}
          </div>
          {(meta !== undefined || actions) && (
            <div className="flex shrink-0 items-center gap-2">
              {meta !== undefined && <div className="text-ui-sm text-text-muted tabular-nums">{meta}</div>}
              {actions}
            </div>
          )}
        </div>
      )}
      {children}
    </div>
  );
}

import { useEffect, type RefObject } from "react";

/** True when a key event lands in a text field, so global shortcuts leave typing alone. */
export function isEditable(t: EventTarget | null) {
  return t instanceof HTMLElement && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName));
}

/**
 * 20px scroll feathers, each only while there is content past that edge (R94). Sets
 * `--fade-top`/`--fade-bottom` (axis "y") or `--fade-start`/`--fade-end` (axis "x", read by
 * the `fade-x` utility) on the scroller; pair them with a mask-image.
 */
export function useScrollFades(ref: RefObject<HTMLElement | null>, axis: "x" | "y" = "y") {
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const [start, end] = axis === "x" ? ["--fade-start", "--fade-end"] : ["--fade-top", "--fade-bottom"];
    const update = () => {
      const [pos, size, view] = axis === "x" ? [el.scrollLeft, el.scrollWidth, el.clientWidth] : [el.scrollTop, el.scrollHeight, el.clientHeight];
      el.style.setProperty(start, pos > 1 ? "20px" : "0px");
      el.style.setProperty(end, size - view - pos > 1 ? "20px" : "0px");
    };
    update();
    el.addEventListener("scroll", update, { passive: true });
    const ro = new ResizeObserver(update);
    ro.observe(el);
    if (el.firstElementChild) ro.observe(el.firstElementChild);
    return () => {
      el.removeEventListener("scroll", update);
      ro.disconnect();
    };
  }, [ref, axis]);
}

/**
 * Number formatting shared by the finance and crypto blocks. Intl writes negatives with a
 * hyphen-minus (U+002D), which is narrower than "+" and breaks a tabular column; Eased uses the
 * true minus sign (U+2212) everywhere.
 */

/** Swap Intl's hyphen-minus for the true minus sign. */
export const trueMinus = (text: string) => text.replace(/-/g, "−");

/**
 * An Intl formatter that writes negatives with the true minus sign. Pass it to NumberRoll as
 * `formatter`, or call it directly: `const pct = minusFormatter(locale, { style: "percent" })`.
 */
export function minusFormatter(locale: Intl.LocalesArgument, options: Intl.NumberFormatOptions): (value: number) => string {
  const format = new Intl.NumberFormat(locale, options);
  return (value) => trueMinus(format.format(value));
}

