import { useEffect } from "react";

/**
 * The macOS look for the Eased Mac pack: system type, translucent "vibrancy" materials and
 * hairlines, in light and dark. Motion stays Eased's (`./motion`); only the material and the
 * geometry follow macOS, so a Mac component still moves like the rest of the library.
 *
 *   macFont          the San Francisco stack, at macOS's 13px body size
 *   macMaterial      frosted panel: translucent tint + backdrop blur/saturate, hairline, shadow
 *   MAC_RADIUS       corner radii macOS uses for popovers, HUDs and controls (px)
 *   useSystemAppearance   puts `.dark` on <html> while the system is dark (Tauri/Electron windows)
 *
 * Dark follows Eased's convention: a `.dark` class or `data-theme="dark"` on an ancestor, so a
 * web app keeps its own theme toggle.
 *
 * Inside a Tauri/Electron window that already draws native vibrancy (Tauri `windowEffects`,
 * `window-vibrancy`, Electron `vibrancy`), pass `"native"`: the CSS blur and tint drop out so
 * the real material shows through, and the hairline stays.
 */

/** -apple-system resolves to SF Pro on Apple platforms; elsewhere the platform UI font. */
export const macFontFamily = "font-[-apple-system,BlinkMacSystemFont,system-ui,sans-serif]";
export const macFont = `${macFontFamily} text-[13px] leading-[16px] antialiased`;

/** `css` approximates vibrancy in the browser; `native` leaves it to the window behind. */
export type MacMaterialMode = "css" | "native";

/** The materials the pack draws, after the NSVisualEffectView materials they stand in for. */
export type MacMaterialKind = "popover" | "hud";

/*
 * Values are measured approximations of macOS's materials (estimates, not Apple constants):
 * popover ≈ NSVisualEffectView.Material.popover, hud ≈ .hudWindow. Every class is written out
 * in full (no string building) so Tailwind finds it; dark repeats each one under `in-[.dark]:`
 * and `in-data-[theme=dark]:`.
 */
const FILL: Record<MacMaterialKind, string> = {
  popover:
    "bg-[rgb(236_236_236/0.72)] in-[.dark]:bg-[rgb(44_44_46/0.72)] in-data-[theme=dark]:bg-[rgb(44_44_46/0.72)] backdrop-blur-[40px] backdrop-saturate-[1.8]",
  hud: "bg-[rgb(240_240_240/0.78)] in-[.dark]:bg-[rgb(30_30_30/0.72)] in-data-[theme=dark]:bg-[rgb(30_30_30/0.72)] backdrop-blur-[30px] backdrop-saturate-[1.5]",
};

/** Half-pixel hairline as an inset ring, so it never changes the box size. */
const HAIRLINE =
  "shadow-[inset_0_0_0_0.5px_rgb(0_0_0/0.15)] in-[.dark]:shadow-[inset_0_0_0_0.5px_rgb(255_255_255/0.14)] in-data-[theme=dark]:shadow-[inset_0_0_0_0.5px_rgb(255_255_255/0.14)]";

/**
 * The same hairline as an SVG stroke colour, for shapes a box-shadow can't follow (the popover's
 * arrow). Stroke 1px along the clip edge: the clip keeps the inner half, a 0.5px hairline.
 */
export const macHairlineStroke =
  "stroke-[rgb(0_0_0/0.15)] in-[.dark]:stroke-[rgb(255_255_255/0.14)] in-data-[theme=dark]:stroke-[rgb(255_255_255/0.14)]";

/** Text colours on the materials: macOS's label and secondaryLabel. */
export const macText =
  "text-[rgb(0_0_0/0.85)] in-[.dark]:text-[rgb(255_255_255/0.85)] in-data-[theme=dark]:text-[rgb(255_255_255/0.85)]";
export const macTextSecondary =
  "text-[rgb(0_0_0/0.5)] in-[.dark]:text-[rgb(255_255_255/0.55)] in-data-[theme=dark]:text-[rgb(255_255_255/0.55)]";

/**
 * Classes for a frosted macOS surface. Add a radius and padding. The outer drop shadow is
 * separate (`macShadow`) because a clip-path shape (the popover's arrow) clips box-shadow.
 * Pass `hairline: false` when the shape draws its own (`macHairlineStroke`).
 */
export function macMaterial(kind: MacMaterialKind, mode: MacMaterialMode = "css", { hairline = true }: { hairline?: boolean } = {}) {
  return `${mode === "native" ? "" : FILL[kind]} ${hairline ? HAIRLINE : ""} ${macText}`;
}

/**
 * The floating shadow for a popover-like surface, as a filter so it follows clip-path shapes.
 * Put it on a sibling layer behind the surface, never an ancestor: a `filter` (or opacity < 1)
 * on an ancestor stops the surface's backdrop blur from seeing the page behind it.
 */
export const macShadow =
  "drop-shadow-[0_8px_24px_rgb(0_0_0/0.22)] in-[.dark]:drop-shadow-[0_8px_24px_rgb(0_0_0/0.45)] in-data-[theme=dark]:drop-shadow-[0_8px_24px_rgb(0_0_0/0.45)]";

/** Corner radii in px (measured on macOS 14–15; macOS 26 rounds popovers to ~16). */
export const MAC_RADIUS = { popover: 11, hud: 18, pill: 9999, control: 6 } as const;

/**
 * Follows the system appearance: toggles `.dark` on <html> from `prefers-color-scheme` and keeps
 * it in step. For a Tauri/Electron window, whose native vibrancy (and the webview's
 * `prefers-color-scheme`) follow the OS; without it dark vibrancy gets light-mode text. Runs in
 * an effect, so it is hydration-safe. Leave it out of a web app that has its own theme toggle.
 */
export function useSystemAppearance() {
  useEffect(() => {
    const query = window.matchMedia("(prefers-color-scheme: dark)");
    const apply = () => document.documentElement.classList.toggle("dark", query.matches);
    apply();
    query.addEventListener("change", apply);
    return () => query.removeEventListener("change", apply);
  }, []);
}

/**
 * Eased motion tokens for Motion (motion/react), mirroring `eased.css`.
 * The CSS springs (`--eased-spring-*`) are these same springs sampled as linear(),
 * so a CSS transition and a Motion animation with the same name feel identical.
 *
 *   snappy  presses, toggles, thumbs, indicators, text swaps, rolling digits, focus ring
 *   smooth  layout, FLIP, panels, toast and tooltip position (no overshoot)
 *   bouncy  shape morphs and playful reveals only; never exits
 */

import { useSyncExternalStore } from "react";

export const snappy = { type: "spring", stiffness: 520, damping: 38 } as const;
export const smooth = { type: "spring", visualDuration: 0.4, bounce: 0 } as const;
export const bouncy = { type: "spring", stiffness: 400, damping: 26 } as const;

/** Cubic-bezier curves, same as `--eased-ease-enter`, `--eased-ease-standard`, `--eased-ease-exit`, `--eased-ease-in-out`. */
export const ease = {
  enter: [0.16, 1, 0.3, 1],
  standard: [0.22, 1, 0.36, 1],
  exit: [0.7, 0, 0.84, 0],
  inOut: [0.65, 0, 0.35, 1],
} as const;

/** Seconds, same as `--eased-duration-*`. */
export const duration = {
  instant: 0.1,
  fast: 0.15,
  standard: 0.2,
  slow: 0.3,
  sheet: 0.5,
  /** Before an image fallback (Avatar initials) shows, so a fast load never flashes it. */
  fallback: 0.4,
} as const;

/** Seconds between staggered children (rule 83); keep the total ≤ 0.4s. */
export const stagger = { char: 0.016, item: 0.035, word: 0.04, line: 0.08 } as const;

/** Blur radii in motion: `soft` for text and icon swaps; `text` is the most anything may blur. */
export const blur = { subtle: "2px", soft: "4px", text: "8px" } as const;

/** Things that appear: opacity and blur alongside a spring. */
export const enter = { duration: duration.standard, ease: ease.enter } as const;
/** Opacity and colour while something stays on screen. */
export const fade = { duration: duration.fast, ease: ease.standard } as const;
/** Things that leave: ≤ 0.75 × `enter`, ease-in, never overshoots. */
export const exit = { duration: duration.fast, ease: ease.exit } as const;
/** Small things that leave: buttons, chips, the outgoing half of a swap. */
export const exitFast = { duration: duration.instant, ease: ease.exit } as const;
/** The reduced-motion branch: opacity only, at `--eased-duration-instant`. */
export const reducedFade = { duration: duration.instant } as const;
export const instant = { duration: 0 } as const;

/** Text and icon swaps (rule 82): out up 3px, in from 4px below, blur tweened apart from the spring. */
export const swapIn = { opacity: 0, y: 4, filter: `blur(${blur.soft})` } as const;
export const swapShown = { opacity: 1, y: 0, filter: "blur(0px)" } as const;
export const swapOut = { opacity: 0, y: -3, filter: `blur(${blur.soft})` } as const;
export const swap = { ...snappy, opacity: fade, filter: fade } as const;

const REDUCE = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const mq = window.matchMedia(REDUCE);
  mq.addEventListener("change", onChange);
  return () => mq.removeEventListener("change", onChange);
};

/**
 * `prefers-reduced-motion`, read after hydration (rule 86): false on the server and during
 * hydration, the real value from then on, and live when the setting changes. Use this, not
 * Motion's `useReducedMotion`, which reads the media query during the first client render
 * and so mismatches the server HTML for reduced-motion users.
 */
export function useSafeReducedMotion() {
  return useSyncExternalStore(subscribeReduced, () => window.matchMedia(REDUCE).matches, () => false);
}

import { useSyncExternalStore } from "react";

const subscribe = () => () => {};
const isMac = () => /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent);

/**
 * True on Apple platforms, read after hydration: the server (and the hydrating render) says
 * Mac, so shortcut hints render ⌘ first and correct to Ctrl on other systems.
 */
export function useIsMac() {
  return useSyncExternalStore(subscribe, isMac, () => true);
}

/** The printed modifier for shortcuts: "⌘" on Apple platforms, "Ctrl" elsewhere. */
export function modKey(mac: boolean) {
  return mac ? "⌘" : "Ctrl";
}

/**
 * Press feedback as one class string per control size (rule 63). Colour moves at 150ms on
 * the standard curve; scale presses down in `--eased-duration-instant` and releases on the snappy
 * spring. Keyboard focus draws Eased's ring (`focus-ring`). Append your own colour classes;
 * do not add another `transition-*` class.
 *
 *   press      text buttons (`--eased-press-scale`, 0.97)
 *   pressIcon  icon buttons ≤ 48px (`--eased-press-scale-icon`, 0.96)
 *   pressWide  bars and cards > 220px (`--eased-press-scale-wide`, 0.985)
 */
const base =
  "[transition:color_150ms_var(--eased-ease-standard),background-color_150ms_var(--eased-ease-standard),border-color_150ms_var(--eased-ease-standard),opacity_150ms_var(--eased-ease-standard),scale_var(--eased-duration-spring-snappy)_var(--eased-spring-snappy),box-shadow_var(--eased-duration-focus)_var(--eased-ease-standard)] active:duration-(--eased-duration-instant) active:ease-standard reduced:active:scale-none focus-ring";

export const press = `${base} active:scale-(--eased-press-scale)`;
export const pressIcon = `${base} active:scale-(--eased-press-scale-icon)`;
export const pressWide = `${base} active:scale-(--eased-press-scale-wide)`;

"use client";

import { animate, type AnimationPlaybackControlsWithThen, type Transition } from "motion/react";
import { useLayoutEffect, useRef, useState, type CSSProperties, type HTMLAttributes, type ReactNode } from "react";
import { duration, ease, exitFast, reducedFade, smooth, useSafeReducedMotion } from "../../lib/motion";

export type AutoHeightProps = Omit<HTMLAttributes<HTMLDivElement>, "children"> & {
  children: ReactNode;
  /**
   * `false` collapses to 0 and hides the content (`visibility: hidden`, so it leaves the tab
   * order and the accessibility tree once closed; `inert` while closing). Default `true`.
   */
  open?: boolean;
  /** Fade the content in once the height is mostly there, and out before it closes. Default `true`. */
  fade?: boolean;
  /** The height spring. Default `smooth`: no overshoot, so content never bounces past its edge. */
  transition?: Transition;
  /** Classes for the measured inner wrapper. Put padding here, never on the root. */
  innerClassName?: string;
  /** Fires when an open or close has fully settled. */
  onOpenChangeComplete?: (open: boolean) => void;
};

/** Start the content fade this far into the height spring, so it lands just after the height does. */
const FADE_DELAY = 0.12;

/**
 * Animates its own height to whatever its content measures: a `height: auto` spring.
 * Content that grows or shrinks while open springs to its new height (a list filtering, an
 * error appearing); `open` collapses it to 0 and back. At rest the root is `height: auto`
 * with no clipping, so focus rings and shadows inside are never cut off; it clips the
 * vertical axis only while moving. Interruptible: a change mid-flight continues from the
 * current height. Reduced motion snaps the height and fades opacity only.
 */
export function AutoHeight({
  open = true,
  fade = true,
  transition = smooth,
  className = "",
  innerClassName = "",
  style,
  onOpenChangeComplete,
  children,
  ...props
}: AutoHeightProps) {
  const outerRef = useRef<HTMLDivElement>(null);
  const innerRef = useRef<HTMLDivElement>(null);
  const reduced = useSafeReducedMotion();
  // Styles that describe the first frame only; afterwards the element is driven imperatively.
  const [initialOpen] = useState(open);
  const prevOpen = useRef(open);
  const openRef = useRef(open);
  const contentHeight = useRef<number | null>(null);
  const heightAnim = useRef<AnimationPlaybackControlsWithThen | null>(null);
  const run = useRef(0);
  const latest = useRef({ reduced, transition, fade, onOpenChangeComplete });

  useLayoutEffect(() => {
    latest.current = { reduced, transition, fade, onOpenChangeComplete };
  });

  /** Spring the root from `from` to `to` px, then release it to `auto` (open) or keep it at 0 (closed). */
  const springHeight = (from: number, to: number, settledOpen: boolean | null) => {
    const el = outerRef.current;
    const content = innerRef.current;
    if (!el || !content) return;
    const { reduced, transition, onOpenChangeComplete } = latest.current;
    const token = ++run.current;
    heightAnim.current?.stop();
    el.style.overflowY = "clip";
    el.style.height = `${from}px`;
    const settle = () => {
      if (token !== run.current) return;
      heightAnim.current = null;
      if (openRef.current) {
        el.style.height = "";
        el.style.overflowY = "";
      } else {
        el.style.height = "0px";
        content.style.visibility = "hidden";
      }
      if (settledOpen !== null) onOpenChangeComplete?.(settledOpen);
    };
    if (reduced || Math.abs(from - to) < 0.5) {
      el.style.height = `${to}px`;
      settle();
      return;
    }
    heightAnim.current = animate(el, { height: [from, to] }, transition);
    heightAnim.current.then(settle);
  };

  /** The root's rendered height right now: mid-animation it is whatever the spring has reached. */
  const currentHeight = () => {
    const el = outerRef.current!;
    return el.style.height && el.style.height !== "auto" ? parseFloat(getComputedStyle(el).height) : el.offsetHeight;
  };

  // Open and close.
  useLayoutEffect(() => {
    if (prevOpen.current === open) return;
    prevOpen.current = open;
    openRef.current = open;
    const el = outerRef.current;
    const content = innerRef.current;
    if (!el || !content) return;
    const { reduced, fade } = latest.current;
    const from = heightAnim.current ? currentHeight() : open ? 0 : el.offsetHeight;
    if (open) {
      content.style.visibility = "";
      const to = content.offsetHeight;
      contentHeight.current = to;
      if (fade) {
        animate(
          content,
          { opacity: [Number(getComputedStyle(content).opacity), 1] },
          reduced ? reducedFade : { duration: duration.standard, ease: ease.enter, delay: FADE_DELAY },
        );
      } else content.style.opacity = "";
      springHeight(from, to, true);
    } else {
      if (fade) animate(content, { opacity: 0 }, reduced ? reducedFade : exitFast);
      springHeight(from, 0, false);
    }
  }, [open]);

  // Content resizing while open.
  useLayoutEffect(() => {
    const content = innerRef.current;
    if (!content) return;
    contentHeight.current = content.offsetHeight;
    const observer = new ResizeObserver(() => {
      const next = content.offsetHeight;
      const prev = contentHeight.current;
      contentHeight.current = next;
      if (!openRef.current || prev === null || prev === next) return;
      // At rest the root is already `auto` (it has jumped this frame, before paint): start from the old height.
      springHeight(heightAnim.current ? currentHeight() : prev, next, null);
    });
    observer.observe(content);
    return () => observer.disconnect();
  }, []);

  const rootStyle: CSSProperties = initialOpen ? { ...style } : { height: 0, overflowY: "clip", ...style };
  const innerStyle: CSSProperties | undefined = initialOpen ? undefined : { visibility: "hidden", opacity: fade ? 0 : undefined };

  return (
    <div ref={outerRef} className={className} style={rootStyle} {...props}>
      <div ref={innerRef} inert={!open} className={`flow-root ${innerClassName}`} style={innerStyle}>
        {children}
      </div>
    </div>
  );
}

/** A half-open time interval [start, end). */
export type Interval = { start: Date | number; end: Date | number };
type Ms = { start: number; end: number };

const ms = (i: Interval): Ms => ({ start: +new Date(i.start), end: +new Date(i.end) });
const out = (i: Ms) => ({ start: new Date(i.start), end: new Date(i.end) });

/** Sorts and merges overlapping or touching intervals. */
export function mergeIntervals(intervals: readonly Interval[]): { start: Date; end: Date }[] {
  const sorted = intervals.map(ms).filter((i) => i.end > i.start).sort((a, b) => a.start - b.start);
  const merged: Ms[] = [];
  for (const i of sorted) {
    const last = merged[merged.length - 1];
    if (last && i.start <= last.end) last.end = Math.max(last.end, i.end);
    else merged.push({ ...i });
  }
  return merged.map(out);
}

/** The free time inside `within` once `busy` is taken out. */
export function subtractBusy(within: Interval, busy: readonly Interval[]): { start: Date; end: Date }[] {
  const w = ms(within);
  const free: Ms[] = [];
  let cursor = w.start;
  for (const b of mergeIntervals(busy).map(ms)) {
    if (b.end <= cursor) continue;
    if (b.start >= w.end) break;
    if (b.start > cursor) free.push({ start: cursor, end: Math.min(b.start, w.end) });
    cursor = Math.max(cursor, b.end);
  }
  if (cursor < w.end) free.push({ start: cursor, end: w.end });
  return free.map(out);
}

/**
 * When everyone is free: the intersection of each person's free intervals. The Interview
 * Scheduler's highlighted overlap.
 */
export function intersectAvailability(people: readonly (readonly Interval[])[]): { start: Date; end: Date }[] {
  if (!people.length) return [];
  let acc: Ms[] = mergeIntervals(people[0]).map(ms);
  for (const person of people.slice(1)) {
    const other = mergeIntervals(person).map(ms);
    const next: Ms[] = [];
    let i = 0;
    let j = 0;
    while (i < acc.length && j < other.length) {
      const start = Math.max(acc[i].start, other[j].start);
      const end = Math.min(acc[i].end, other[j].end);
      if (end > start) next.push({ start, end });
      if (acc[i].end < other[j].end) i++;
      else j++;
    }
    acc = next;
  }
  return acc.map(out);
}

/** Bookable slot starts of `durationMinutes` inside free intervals, every `stepMinutes` on the clock (local). */
export function slotsIn(free: readonly Interval[], { durationMinutes = 30, stepMinutes = durationMinutes }: { durationMinutes?: number; stepMinutes?: number } = {}): Date[] {
  const step = stepMinutes * 60_000;
  const dur = durationMinutes * 60_000;
  const slots: Date[] = [];
  for (const f of free.map(ms)) {
    const offset = new Date(f.start).getTimezoneOffset() * 60_000;
    let t = Math.ceil((f.start - offset) / step) * step + offset;
    for (; t + dur <= f.end; t += step) slots.push(new Date(t));
  }
  return slots;
}

/**
 * Local-time date math for calendar-core. The names and semantics match date-fns
 * (`addDays`, `startOfWeek({ weekStartsOn })`, `differenceInCalendarDays` …) so this file can
 * be swapped for `date-fns` imports one-for-one. Every function returns a new Date.
 */

export type WeekStart = 0 | 1 | 2 | 3 | 4 | 5 | 6;

const clone = (d: Date | number) => new Date(typeof d === "number" ? d : d.getTime());

export function startOfDay(d: Date | number): Date {
  const x = clone(d);
  x.setHours(0, 0, 0, 0);
  return x;
}
export function endOfDay(d: Date | number): Date {
  const x = clone(d);
  x.setHours(23, 59, 59, 999);
  return x;
}
/** Calendar days, so a DST change keeps the wall-clock time. */
export function addDays(d: Date | number, n: number): Date {
  const x = clone(d);
  x.setDate(x.getDate() + n);
  return x;
}
export const addWeeks = (d: Date | number, n: number) => addDays(d, n * 7);
/** Clamps to the last day of a shorter month (31 Jan + 1 month → 28/29 Feb), like date-fns. */
export function addMonths(d: Date | number, n: number): Date {
  const x = clone(d);
  const day = x.getDate();
  x.setDate(1);
  x.setMonth(x.getMonth() + n);
  x.setDate(Math.min(day, getDaysInMonth(x)));
  return x;
}
export function addMinutes(d: Date | number, n: number): Date {
  return new Date(clone(d).getTime() + n * 60_000);
}
export function getDaysInMonth(d: Date | number): number {
  const x = clone(d);
  return new Date(x.getFullYear(), x.getMonth() + 1, 0).getDate();
}
export function startOfMonth(d: Date | number): Date {
  const x = startOfDay(d);
  x.setDate(1);
  return x;
}
export function endOfMonth(d: Date | number): Date {
  const x = startOfMonth(d);
  x.setMonth(x.getMonth() + 1, 0);
  return endOfDay(x);
}
export function startOfWeek(d: Date | number, { weekStartsOn = 0 }: { weekStartsOn?: WeekStart } = {}): Date {
  const x = startOfDay(d);
  const diff = (x.getDay() - weekStartsOn + 7) % 7;
  return addDays(x, -diff);
}
export function endOfWeek(d: Date | number, options: { weekStartsOn?: WeekStart } = {}): Date {
  return endOfDay(addDays(startOfWeek(d, options), 6));
}
export const isSameDay = (a: Date | number, b: Date | number) => startOfDay(a).getTime() === startOfDay(b).getTime();
export function isSameMonth(a: Date | number, b: Date | number): boolean {
  const x = clone(a);
  const y = clone(b);
  return x.getFullYear() === y.getFullYear() && x.getMonth() === y.getMonth();
}
export const isWeekend = (d: Date | number) => {
  const day = clone(d).getDay();
  return day === 0 || day === 6;
};
/** Whole calendar days from `b` to `a` (a − b), ignoring time of day and DST. */
export function differenceInCalendarDays(a: Date | number, b: Date | number): number {
  const x = startOfDay(a);
  const y = startOfDay(b);
  const utc = (d: Date) => Date.UTC(d.getFullYear(), d.getMonth(), d.getDate());
  return Math.round((utc(x) - utc(y)) / 86_400_000);
}
export const isBefore = (a: Date | number, b: Date | number) => clone(a).getTime() < clone(b).getTime();
export const isAfter = (a: Date | number, b: Date | number) => clone(a).getTime() > clone(b).getTime();
export const min = (a: Date, b: Date) => (a.getTime() <= b.getTime() ? a : b);
export const max = (a: Date, b: Date) => (a.getTime() >= b.getTime() ? a : b);

/** `YYYY-MM-DD` in local time: a stable React key and `data-date` for a day cell. */
export function toDayKey(d: Date | number): string {
  const x = clone(d);
  const p = (n: number) => String(n).padStart(2, "0");
  return `${x.getFullYear()}-${p(x.getMonth() + 1)}-${p(x.getDate())}`;
}
/** Local midnight of a `YYYY-MM-DD` key. */
export function fromDayKey(key: string): Date {
  const [y, m, d] = key.split("-").map(Number);
  return new Date(y, m - 1, d);
}

/** The locale's first day of the week (Intl `weekInfo` where supported), else Monday, or Sunday for en-US. */
export function localeWeekStart(locale?: string): WeekStart {
  try {
    const loc = new Intl.Locale(locale ?? Intl.DateTimeFormat().resolvedOptions().locale) as Intl.Locale & {
      weekInfo?: { firstDay: number };
      getWeekInfo?: () => { firstDay: number };
    };
    const info = loc.getWeekInfo?.() ?? loc.weekInfo;
    if (info) return (info.firstDay % 7) as WeekStart;
    return loc.region === "US" || loc.baseName === "en" ? 0 : 1;
  } catch {
    return 1;
  }
}

import {
  addDays,
  addMinutes,
  differenceInCalendarDays,
  endOfMonth,
  isSameDay,
  isSameMonth,
  isWeekend,
  startOfDay,
  startOfMonth,
  startOfWeek,
  toDayKey,
  type WeekStart,
} from "./dates";

export type CalendarDay = {
  date: Date;
  /** `YYYY-MM-DD`, local: key cells by it. */
  key: string;
  /** Day of month, 1–31. */
  day: number;
  /** 0 Sunday … 6 Saturday. */
  weekday: number;
  /** False for the leading/trailing days of neighbouring months in a month grid. */
  inMonth: boolean;
  isToday: boolean;
  isWeekend: boolean;
};

export type GridOptions = {
  /** 0 Sunday … 6 Saturday. Default 1 (Monday); `localeWeekStart(locale)` reads the locale's. */
  weekStartsOn?: WeekStart;
  /** "Today", for the today mark. Pass a fixed date for deterministic demos; default none. */
  today?: Date | number;
  locale?: string;
};

const dayOf = (date: Date, month: Date | null, today: Date | number | undefined): CalendarDay => ({
  date,
  key: toDayKey(date),
  day: date.getDate(),
  weekday: date.getDay(),
  inMonth: month ? isSameMonth(date, month) : true,
  isToday: today !== undefined && isSameDay(date, today),
  isWeekend: isWeekend(date),
});

/** Weekday headers in display order: `{ narrow: "M", short: "Mon", long: "Monday" }`. */
export function weekdays({ weekStartsOn = 1, locale }: Pick<GridOptions, "weekStartsOn" | "locale"> = {}) {
  // 4 Jan 1970 was a Sunday.
  const base = new Date(1970, 0, 4 + weekStartsOn);
  const f = (weekday: "narrow" | "short" | "long") => new Intl.DateTimeFormat(locale, { weekday });
  const [n, s, l] = [f("narrow"), f("short"), f("long")];
  return Array.from({ length: 7 }, (_, i) => {
    const d = addDays(base, i);
    return { weekday: d.getDay(), narrow: n.format(d), short: s.format(d), long: l.format(d) };
  });
}

/**
 * A month as weeks of days, padded with the neighbouring months' days. `fixedWeeks` (default
 * true) always returns six weeks, so paging months never changes the grid's height.
 *
 *   const { title, weeks, weekdays } = monthGrid(new Date(2026, 9), { today: FIXTURE_NOW });
 */
export function monthGrid(month: Date | number, { weekStartsOn = 1, today, locale, fixedWeeks = true }: GridOptions & { fixedWeeks?: boolean } = {}) {
  const first = startOfMonth(month);
  const start = startOfWeek(first, { weekStartsOn });
  const span = differenceInCalendarDays(endOfMonth(first), start) + 1;
  const weekCount = fixedWeeks ? 6 : Math.ceil(span / 7);
  const weeks: CalendarDay[][] = Array.from({ length: weekCount }, (_, w) => Array.from({ length: 7 }, (_, d) => dayOf(addDays(start, w * 7 + d), first, today)));
  return {
    title: new Intl.DateTimeFormat(locale, { month: "long", year: "numeric" }).format(first),
    month: first,
    weeks,
    days: weeks.flat(),
    weekdays: weekdays({ weekStartsOn, locale }),
    start,
    end: addDays(start, weekCount * 7 - 1),
  };
}

export type TimeGridOptions = GridOptions & {
  /** Days shown. Default 7 (a week grid); 5 for a work week; 1 for a day. */
  days?: number;
  /** First and last hour shown (end exclusive). Default 8 → 20. */
  startHour?: number;
  endHour?: number;
  /** Slot length. Default 30. */
  slotMinutes?: number;
  /** Start on `anchor` itself instead of its week start (day views, rolling 3-day views). */
  fromAnchor?: boolean;
};

export type TimeSlot = {
  index: number;
  /** Minutes after midnight. */
  minutes: number;
  /** Localised label ("09:00" or "9 AM"), on whole hours only; empty otherwise. */
  label: string;
  hourStart: boolean;
};

/**
 * A week (or day) time grid: day columns and time slots, plus `slotStart(day, slot)` to turn
 * a cell back into a Date. The basis of Week Calendar, Tour and Interview Schedulers.
 */
export function timeGrid(anchor: Date | number, options: TimeGridOptions = {}) {
  const { weekStartsOn = 1, today, locale, days = 7, startHour = 8, endHour = 20, slotMinutes = 30, fromAnchor = false } = options;
  const first = fromAnchor ? startOfDay(anchor) : startOfWeek(anchor, { weekStartsOn });
  const dayList = Array.from({ length: days }, (_, i) => dayOf(addDays(first, i), null, today));
  const hourFmt = new Intl.DateTimeFormat(locale, { hour: "numeric", minute: "2-digit" });
  const slotCount = Math.max(0, Math.round(((endHour - startHour) * 60) / slotMinutes));
  const slots: TimeSlot[] = Array.from({ length: slotCount }, (_, index) => {
    const minutes = startHour * 60 + index * slotMinutes;
    const hourStart = minutes % 60 === 0;
    return { index, minutes, hourStart, label: hourStart ? hourFmt.format(new Date(1970, 0, 1, minutes / 60)) : "" };
  });
  const last = dayList[dayList.length - 1]?.date ?? first;
  const rangeFmt = new Intl.DateTimeFormat(locale, { day: "numeric", month: "short", year: "numeric" });
  return {
    title: days === 1 ? new Intl.DateTimeFormat(locale, { weekday: "long", day: "numeric", month: "long" }).format(first) : rangeFmt.formatRange(first, last),
    days: dayList,
    slots,
    slotMinutes,
    startHour,
    endHour,
    /** The Date a cell starts at. */
    slotStart: (dayIndex: number, slotIndex: number) => addMinutes(startOfDay(dayList[dayIndex].date), startHour * 60 + slotIndex * slotMinutes),
    /** The cell a Date falls in, or null when it is outside the grid. */
    cellOf: (t: Date | number) => {
      const d = new Date(t);
      const dayIndex = dayList.findIndex((x) => isSameDay(x.date, d));
      const m = d.getHours() * 60 + d.getMinutes() - startHour * 60;
      if (dayIndex < 0 || m < 0 || m >= slotCount * slotMinutes) return null;
      return { dayIndex, slotIndex: Math.floor(m / slotMinutes) };
    },
  };
}

export type TimedItem = { id: string; start: Date | number; end: Date | number };

export type PlacedItem<T> = {
  item: T;
  /** 0–1 share of the visible hours: `top: ${top * 100}%`. */
  top: number;
  height: number;
  /** Side-by-side columns for overlapping items. */
  column: number;
  columns: number;
};

/**
 * Places one day's timed items (appointments, shifts, tours) on a time grid: top and height as
 * shares of the visible hours (clipped to them), and overlapping items in side-by-side columns
 * whose count is per cluster, not per day.
 */
export function placeDayItems<T extends TimedItem>(items: readonly T[], day: Date | number, { startHour = 8, endHour = 20 }: { startHour?: number; endHour?: number } = {}): PlacedItem<T>[] {
  const dayStart = startOfDay(day).getTime();
  const lo = dayStart + startHour * 3_600_000;
  const hi = dayStart + endHour * 3_600_000;
  const span = hi - lo;
  const visible = items
    .map((item) => ({ item, s: Math.max(lo, +new Date(item.start)), e: Math.min(hi, +new Date(item.end)) }))
    .filter((x) => x.e > x.s)
    .sort((a, b) => a.s - b.s || b.e - a.e);
  const out: PlacedItem<T>[] = [];
  let cluster: { x: (typeof visible)[number]; column: number }[] = [];
  let clusterEnd = -Infinity;
  const flush = () => {
    const columns = Math.max(1, ...cluster.map((c) => c.column + 1));
    for (const c of cluster) out.push({ item: c.x.item, top: (c.x.s - lo) / span, height: (c.x.e - c.x.s) / span, column: c.column, columns });
    cluster = [];
  };
  for (const x of visible) {
    if (x.s >= clusterEnd) {
      flush();
      clusterEnd = -Infinity;
    }
    const taken = new Set(cluster.filter((c) => c.x.e > x.s).map((c) => c.column));
    let column = 0;
    while (taken.has(column)) column++;
    cluster.push({ x, column });
    clusterEnd = Math.max(clusterEnd, x.e);
  }
  flush();
  return out;
}

/**
 * Items bucketed by the local days they touch, for month grids: a three-day leave shows on
 * each of its days. Keys are `YYYY-MM-DD`.
 */
export function itemsByDay<T extends TimedItem>(items: readonly T[]): Map<string, T[]> {
  const map = new Map<string, T[]>();
  for (const item of items) {
    const s = startOfDay(item.start);
    // An item ending exactly at midnight doesn't touch that day; a zero-length item still shows on its day.
    const days = Math.max(0, differenceInCalendarDays(+new Date(item.end) - 1, s));
    for (let i = 0; i <= days; i++) {
      const k = toDayKey(addDays(s, i));
      const list = map.get(k);
      if (list) list.push(item);
      else map.set(k, [item]);
    }
  }
  return map;
}

"use client";

import { useCallback, useEffect, useState, type KeyboardEvent, type PointerEvent } from "react";
import { addDays, addMinutes, differenceInCalendarDays, startOfDay, toDayKey } from "./dates";

/** Whole days (bookings, leave, deadlines) or fixed-length time slots (tours, shifts). */
export type Granularity = "day" | { minutes: number };

/** An inclusive range of units: `end` is the last selected day, or the start of the last selected slot. */
export type DateRange = { start: Date; end: Date };

const isDay = (g: Granularity): g is "day" => g === "day";
const unitStart = (d: Date | number, g: Granularity) => {
  if (isDay(g)) return startOfDay(d);
  const ms = g.minutes * 60_000;
  const t = +new Date(d);
  const local = t - new Date(t).getTimezoneOffset() * 60_000;
  return new Date(t - (((local % ms) + ms) % ms));
};
const unitAdd = (d: Date, n: number, g: Granularity) => (isDay(g) ? addDays(d, n) : addMinutes(d, n * g.minutes));
const unitDiff = (a: Date, b: Date, g: Granularity) => (isDay(g) ? differenceInCalendarDays(a, b) : Math.round((+a - +b) / (g.minutes * 60_000)));
const sameUnit = (a: Date, b: Date, g: Granularity) => unitDiff(a, b, g) === 0;

/** Orders two dates into a range, snapped to whole units. */
export function normalizeRange(a: Date | number, b: Date | number, granularity: Granularity = "day"): DateRange {
  const x = unitStart(a, granularity);
  const y = unitStart(b, granularity);
  return +x <= +y ? { start: x, end: y } : { start: y, end: x };
}

/** Units in a range, inclusive: a one-night booking selected as two days is 2. */
export function rangeLength(r: DateRange, granularity: Granularity = "day"): number {
  return unitDiff(r.end, r.start, granularity) + 1;
}

export function isInRange(d: Date | number, r: DateRange | null | undefined, granularity: Granularity = "day"): boolean {
  if (!r) return false;
  const u = unitStart(d, granularity);
  return +u >= +r.start && +u <= +r.end;
}

export type RangePosition = "single" | "start" | "middle" | "end";

/** Where a cell sits in a range, for the pill shape: rounded ends, square middle. */
export function rangePosition(d: Date | number, r: DateRange | null | undefined, granularity: Granularity = "day"): RangePosition | null {
  if (!r || !isInRange(d, r, granularity)) return null;
  const u = unitStart(d, granularity);
  const s = sameUnit(u, r.start, granularity);
  const e = sameUnit(u, r.end, granularity);
  return s && e ? "single" : s ? "start" : e ? "end" : "middle";
}

export type RangeConstraints = {
  granularity?: Granularity;
  /** Units that can't be selected (booked nights, weekends, past days). A range never spans one. */
  isDisabled?: (d: Date) => boolean;
  /** Fewest units in a committed range. Default 1. */
  minLength?: number;
  /** Most units. Default unlimited. */
  maxLength?: number;
};

/**
 * The range from `anchor` towards `target` that the constraints allow: it stops before the
 * first disabled unit (a stay can't span a booked night), caps at `maxLength`, and stretches
 * to `minLength` in the drag's direction when it can. Null when the anchor itself is disabled
 * or `minLength` can't be met.
 */
export function constrainRange(anchor: Date | number, target: Date | number, { granularity = "day", isDisabled, minLength = 1, maxLength = Infinity }: RangeConstraints = {}): DateRange | null {
  const a = unitStart(anchor, granularity);
  const t = unitStart(target, granularity);
  if (isDisabled?.(a)) return null;
  const dir = +t >= +a ? 1 : -1;
  const want = Math.max(minLength, Math.min(maxLength, Math.abs(unitDiff(t, a, granularity)) + 1));
  let end = a;
  let n = 1;
  while (n < want) {
    const next = unitAdd(end, dir, granularity);
    if (isDisabled?.(next)) break;
    end = next;
    n++;
  }
  if (n < minLength) return null;
  return normalizeRange(a, end, granularity);
}

export type UseRangeSelectionOptions = RangeConstraints & {
  /** Controlled committed range. */
  value?: DateRange | null;
  defaultValue?: DateRange | null;
  onChange?: (range: DateRange | null) => void;
};

export type CellState = {
  /** In the committed range. */
  selected: boolean;
  /** In the range being chosen (between the anchor and the pointer). */
  previewing: boolean;
  /** Position in whichever range is showing (the preview while choosing): drives the pill shape. */
  position: RangePosition | null;
  disabled: boolean;
  /** The first click / drag start of the range being chosen. */
  anchor: boolean;
};

type Pending = { anchor: Date | null; hover: Date | null; dragging: boolean; moved: boolean };
const idle: Pending = { anchor: null, hover: null, dragging: false, moved: false };

/**
 * Range selection for day grids and time grids. Click a start and an end, or press and drag
 * across cells (touch too: give the grid `touch-action: none`); Enter or Space on a focused cell
 * acts as a click, Escape cancels. While choosing, `preview` follows the pointer and respects
 * the constraints, so a guest sees exactly the stay they would get.
 *
 *   const sel = useRangeSelection({ isDisabled: (d) => booked.has(toDayKey(d)), maxLength: 14 });
 *   <button {...sel.cellProps(day.date)} data-position={sel.stateOf(day.date).position ?? undefined} />
 */
export function useRangeSelection(options: UseRangeSelectionOptions = {}) {
  const { value: controlled, defaultValue = null, onChange, granularity = "day", isDisabled, minLength, maxLength } = options;
  const [uncontrolled, setUncontrolled] = useState<DateRange | null>(defaultValue);
  const [pending, setPending] = useState<Pending>(idle);
  const value = controlled !== undefined ? controlled : uncontrolled;
  const constraints: RangeConstraints = { granularity, isDisabled, minLength, maxLength };

  const commit = (range: DateRange | null) => {
    if (controlled === undefined) setUncontrolled(range);
    onChange?.(range);
    setPending(idle);
  };

  const preview = pending.anchor ? constrainRange(pending.anchor, pending.hover ?? pending.anchor, constraints) : null;

  /** A click (or Enter/Space): starts a range, or ends the one being chosen. */
  const select = (d: Date) => {
    if (isDisabled?.(unitStart(d, granularity))) return;
    if (!pending.anchor) return setPending({ anchor: unitStart(d, granularity), hover: null, dragging: false, moved: false });
    const range = constrainRange(pending.anchor, d, constraints);
    if (range) commit(range);
  };
  const hover = (d: Date | null) => setPending((p) => (p.anchor ? { ...p, hover: d, moved: p.moved || (d !== null && !sameUnit(d, p.anchor, granularity)) } : p));
  const cancel = () => setPending(idle);
  const clear = () => commit(null);

  // A drag that ends outside the grid still ends.
  const dragging = pending.dragging;
  const endDrag = useCallback(() => {
    setPending((p) => (p.dragging ? { ...p, dragging: false } : p));
  }, []);
  useEffect(() => {
    if (!dragging) return;
    window.addEventListener("pointerup", endDrag);
    window.addEventListener("pointercancel", endDrag);
    return () => {
      window.removeEventListener("pointerup", endDrag);
      window.removeEventListener("pointercancel", endDrag);
    };
  }, [dragging, endDrag]);

  const cellProps = (date: Date) => ({
    "data-date": isDay(granularity) ? toDayKey(date) : unitStart(date, granularity).toISOString(),
    "aria-selected": isInRange(date, value, granularity),
    "aria-disabled": isDisabled?.(unitStart(date, granularity)) || undefined,
    onPointerDown: (e: PointerEvent<HTMLElement>) => {
      if (e.button !== 0) return;
      // Release touch's implicit capture so the cells under the finger get pointerenter.
      if (e.currentTarget.hasPointerCapture?.(e.pointerId)) e.currentTarget.releasePointerCapture(e.pointerId);
      if (pending.anchor && !pending.dragging) return select(date);
      if (isDisabled?.(unitStart(date, granularity))) return;
      setPending({ anchor: unitStart(date, granularity), hover: date, dragging: true, moved: false });
    },
    onPointerEnter: () => {
      if (pending.anchor) hover(date);
    },
    onPointerUp: () => {
      if (!pending.dragging || !pending.anchor) return;
      // A press without movement leaves the anchor for click-click; a drag commits.
      if (!pending.moved && sameUnit(date, pending.anchor, granularity)) return setPending((p) => ({ ...p, dragging: false }));
      const range = constrainRange(pending.anchor, date, constraints);
      if (range) commit(range);
      else cancel();
    },
    onKeyDown: (e: KeyboardEvent<HTMLElement>) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        select(date);
      } else if (e.key === "Escape" && pending.anchor) {
        e.preventDefault();
        cancel();
      }
    },
    onFocus: () => {
      if (pending.anchor) hover(date);
    },
  });

  const stateOf = (date: Date): CellState => {
    const showing = preview ?? value;
    return {
      selected: isInRange(date, value, granularity),
      previewing: isInRange(date, preview, granularity),
      position: rangePosition(date, showing, granularity),
      disabled: !!isDisabled?.(unitStart(date, granularity)),
      anchor: !!pending.anchor && sameUnit(date, pending.anchor, granularity),
    };
  };

  return { value, preview, anchor: pending.anchor, selecting: !!pending.anchor, select, hover, cancel, clear, setValue: commit, cellProps, stateOf };
}

/**
 * The date a roving-focus grid moves to for a key (WAI-ARIA date grid): arrows ±1 day / ±1
 * week, Home/End to the week's ends, PageUp/PageDown ±1 month (Shift: ±1 year). Null for other keys.
 */
export function nextFocusDate(date: Date, key: string, { weekStartsOn = 1, shift = false }: { weekStartsOn?: number; shift?: boolean } = {}): Date | null {
  const month = (n: number) => {
    const d = new Date(date);
    const day = d.getDate();
    d.setDate(1);
    d.setMonth(d.getMonth() + n);
    d.setDate(Math.min(day, new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate()));
    return d;
  };
  const offset = (date.getDay() - weekStartsOn + 7) % 7;
  switch (key) {
    case "ArrowLeft":
      return addDays(date, -1);
    case "ArrowRight":
      return addDays(date, 1);
    case "ArrowUp":
      return addDays(date, -7);
    case "ArrowDown":
      return addDays(date, 7);
    case "Home":
      return addDays(date, -offset);
    case "End":
      return addDays(date, 6 - offset);
    case "PageUp":
      return month(shift ? -12 : -1);
    case "PageDown":
      return month(shift ? 12 : 1);
    default:
      return null;
  }
}

import type { ReactNode } from "react";

export type ChartDataColumn<D> = {
  /** Column header, e.g. the series label. */
  label: string;
  /** The cell's text for a row. */
  value: (datum: D, index: number) => ReactNode;
};

export type ChartDataTableProps<D> = {
  /** What the table lists, e.g. "Revenue by day". */
  caption: string;
  data: readonly D[];
  /** The row header (usually the formatted date or category). */
  rowLabel: (datum: D, index: number) => ReactNode;
  /** Header of the row-label column. Default "Date". */
  rowLabelHeader?: string;
  columns: readonly ChartDataColumn<D>[];
};

/**
 * Every point of a chart as a real `<table>`, visually hidden. Screen reader users get the
 * whole dataset in table navigation, and anyone who cannot tell two hues apart has the
 * numbers. Pair it with an `aria-hidden` SVG.
 */
export function ChartDataTable<D>({ caption, data, rowLabel, rowLabelHeader = "Date", columns }: ChartDataTableProps<D>) {
  return (
    <table className="sr-only">
      <caption>{caption}</caption>
      <thead>
        <tr>
          <th scope="col">{rowLabelHeader}</th>
          {columns.map((c) => (
            <th key={c.label} scope="col">
              {c.label}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {data.map((d, i) => (
          <tr key={i}>
            <th scope="row">{rowLabel(d, i)}</th>
            {columns.map((c) => (
              <td key={c.label}>{c.value(d, i)}</td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

"use client";

import { animate, useInView, useMotionValue } from "motion/react";
import { useEffect, type RefObject } from "react";
import { ease } from "../../lib/motion";

export type DrawInOptions = {
  reduced?: boolean;
  /** Seconds. Default 0.9: a chart is read left to right, so it is drawn at reading pace. */
  duration?: number;
  delay?: number;
  /** Share of the chart that must be on screen. Default 0.35. */
  amount?: number;
};

/**
 * 0 → 1 once, the first time `ref` scrolls into view; then never again (rule 83: entrances
 * run once per mount). Drive a left-to-right clip, bar heights or dot opacity from it.
 * Reduced motion starts at 1.
 */
export function useDrawIn(ref: RefObject<Element | null>, { reduced = false, duration = 0.9, delay = 0, amount = 0.35 }: DrawInOptions = {}) {
  const progress = useMotionValue(0);
  const inView = useInView(ref, { once: true, amount });
  useEffect(() => {
    if (reduced) {
      progress.jump(1);
      return;
    }
    if (!inView) return;
    const controls = animate(progress, 1, { duration, delay, ease: ease.inOut });
    return () => controls.stop();
  }, [inView, reduced, progress, duration, delay]);
  return progress;
}

"use client";

import { AnimatePresence, motion, useMotionValueEvent, type MotionValue, type Transition } from "motion/react";
import { useLayoutEffect, useRef } from "react";
import { exitFast, fade, instant } from "../../lib/motion";
import { linear, type Domain } from "./scales";

export type ChartGridProps = {
  /** Gridline values, usually `niceScale(...).ticks`. */
  ticks: readonly number[];
  /** The live value domain. Gridlines ride it, so they slide while the scale springs. */
  domain: MotionValue<Domain>;
  /** Full width, px, gutter included. */
  width: number;
  /** Left gutter for the labels, px (see `gutterFor`). Lines start after it. Default 0: labels sit above the lines. */
  gutter?: number;
  /** Pixel range the domain maps to, top to bottom: `[top, bottom]`. */
  range: Domain;
  /** Tick label text. Leave out for unlabelled gridlines. */
  format?: (value: number) => string;
  reduced?: boolean;
};

/** A label gutter wide enough for the widest tick label (11px tabular figures), plus an 8px gap. */
export function gutterFor(labels: readonly string[]) {
  const longest = labels.reduce((m, l) => Math.max(m, l.length), 0);
  return longest ? Math.ceil(longest * 6.4) + 8 : 0;
}

/**
 * Hairline gridlines with their labels left-aligned on the chart's leading edge (the same x
 * as the headline and legend above it): in a gutter beside the lines, or just above them. When the domain changes, lines that
 * stay slide with the springing scale; new values fade in and retired ones fade out while
 * still sliding, so nothing pops. SVG; render it inside the plot's `<svg>`.
 */
export function ChartGrid({ ticks, domain, width, gutter = 0, range, format, reduced = false }: ChartGridProps) {
  return (
    <g aria-hidden>
      <AnimatePresence initial={false}>
        {ticks.map((t) => (
          <Tick key={t} value={t} domain={domain} width={width} gutter={gutter} range={range} label={format?.(t)} reduced={reduced} />
        ))}
      </AnimatePresence>
    </g>
  );
}

function Tick({ value, domain, width, gutter, range, label, reduced }: { value: number; domain: MotionValue<Domain>; width: number; gutter: number; range: Domain; label?: string; reduced: boolean }) {
  const ref = useRef<SVGGElement>(null);
  const place = (d: Domain) => {
    const y = Math.round(linear(d, [range[1], range[0]])(value)) + 0.5;
    ref.current?.setAttribute("transform", `translate(0 ${y})`);
  };
  useLayoutEffect(() => place(domain.get()));
  useMotionValueEvent(domain, "change", place);

  return (
    <motion.g
      ref={ref}
      initial={{ opacity: 0 }}
      animate={{ opacity: 1, transition: reduced ? instant : fade }}
      exit={{ opacity: 0, transition: reduced ? instant : exitFast }}
    >
      <line x1={gutter} x2={width} stroke="var(--eased-chart-grid)" strokeWidth={1} shapeRendering="crispEdges" />
      {label !== undefined && (
        <text y={gutter ? 0 : -6} dominantBaseline={gutter ? "central" : undefined} className="fill-text-muted tabular-nums" style={{ fontSize: 11 }}>
          {label}
        </text>
      )}
    </motion.g>
  );
}

export type ChartXAxisProps = {
  /** The labels to show (already thinned), each with its bucket's key and pixel x. */
  items: readonly { key: string; x: number; text: string; align?: "start" | "center" | "end" }[];
  /** Morph transition for labels that stay. */
  transition: Transition;
  reduced?: boolean;
  /** Left offset of the row, px: the plot's gutter. */
  left?: number;
  className?: string;
};

/**
 * X labels in an HTML row under the plot. Labels keyed by their bucket slide to their new
 * position when the range changes; others fade. The first label starts on the plot's left
 * line and the last ends on its right line (`align`), so neither clips and both edges stay true.
 */
export function ChartXAxis({ items, transition, reduced = false, left = 0, className = "" }: ChartXAxisProps) {
  return (
    <div aria-hidden className={`pointer-events-none h-4 text-ui-2xs text-text-muted tabular-nums ${className}`} style={{ left }}>
      <AnimatePresence initial={false}>
        {items.map((item) => {
          const shift = item.align === "start" ? "" : item.align === "end" ? "-translate-x-full" : "-translate-x-1/2";
          return (
            <motion.span
              key={item.key}
              className={`absolute top-0 left-0 whitespace-nowrap ${shift}`}
              initial={{ x: item.x, opacity: 0 }}
              animate={{ x: item.x, opacity: 1, transition: reduced ? instant : { x: transition, opacity: fade } }}
              exit={{ opacity: 0, transition: reduced ? instant : exitFast }}
            >
              {item.text}
            </motion.span>
          );
        })}
      </AnimatePresence>
    </div>
  );
}

"use client";

import type { ReactNode } from "react";
import { press } from "../../lib/press";

export type ChartKey = {
  key: string;
  label: string;
  /** CSS colour, usually `chartColor(n)`. */
  color: string;
  /** Previous-period style: a dashed line key. */
  dashed?: boolean;
};

/** A series' identity mark: a short line key for lines, a rounded square for bars and areas. */
export function ChartSwatch({ color, shape = "square", dashed = false, off = false }: { color: string; shape?: "line" | "square"; dashed?: boolean; off?: boolean }) {
  if (shape === "line") {
    return (
      <svg aria-hidden width={12} height={8} viewBox="0 0 12 8" className="shrink-0 overflow-visible">
        <line x1={1} x2={11} y1={4} y2={4} stroke={color} strokeWidth={2} strokeLinecap="round" strokeDasharray={dashed ? "2 3" : undefined} opacity={off ? 0.35 : dashed ? 0.6 : 1} />
      </svg>
    );
  }
  return (
    <span
      aria-hidden
      className="size-2 shrink-0 rounded-[calc(var(--eased-radius-control-2xs)/2)] transition-opacity duration-150 ease-standard"
      style={{ background: off ? "transparent" : color, boxShadow: off ? `inset 0 0 0 1.5px ${color}` : undefined, opacity: off ? 0.6 : 1 }}
    />
  );
}

export type ChartLegendProps = {
  items: readonly ChartKey[];
  /** Keys currently hidden. */
  hidden?: ReadonlySet<string>;
  /** Makes each key a toggle button. Leave out for a static legend. */
  onToggle?: (key: string) => void;
  /** Hovering or focusing a key previews it: the chart dims the others. */
  onPreview?: (key: string | null) => void;
  shape?: "line" | "square";
  /** Extra content on the right, e.g. a total. */
  trailing?: ReactNode;
  className?: string;
};

/**
 * The legend: always present for two or more series, so identity never rests on colour.
 * As toggles, each key is a pressed/unpressed button; the row is pulled left by the buttons'
 * padding so the first swatch sits on the content's left line (rule 104).
 */
export function ChartLegend({ items, hidden, onToggle, onPreview, shape = "square", trailing, className = "" }: ChartLegendProps) {
  return (
    <div className={`flex min-w-0 items-center justify-between gap-3 ${className}`}>
      <ul className={`flex min-w-0 flex-wrap items-center ${onToggle ? "-ml-2 gap-x-0.5" : "gap-x-4"} gap-y-1`}>
        {items.map((item) => {
          const off = hidden?.has(item.key) ?? false;
          const body = (
            <>
              <ChartSwatch color={item.color} shape={shape} dashed={item.dashed} off={off} />
              <span className="truncate">{item.label}</span>
            </>
          );
          return (
            <li key={item.key} className="min-w-0">
              {onToggle ? (
                <button
                  type="button"
                  aria-pressed={!off}
                  onClick={() => onToggle(item.key)}
                  onPointerEnter={(e) => e.pointerType === "mouse" && onPreview?.(item.key)}
                  onPointerLeave={() => onPreview?.(null)}
                  onFocus={() => onPreview?.(item.key)}
                  onBlur={() => onPreview?.(null)}
                  className={`${press} inline-flex h-6 max-w-full cursor-pointer items-center gap-1.5 rounded-control-xs px-2 text-ui-xs hover-fine:bg-surface-hover ${off ? "text-text-muted" : "text-text-secondary hover-fine:text-text"}`}
                >
                  {body}
                </button>
              ) : (
                <span className="inline-flex h-6 items-center gap-1.5 text-ui-xs text-text-secondary">{body}</span>
              )}
            </li>
          );
        })}
      </ul>
      {trailing}
    </div>
  );
}

"use client";

import { animate, type AnimationPlaybackControls, type Transition } from "motion/react";
import { useLayoutEffect, useRef, useState } from "react";
import { smooth } from "../../lib/motion";
import { lerp, type Domain } from "./scales";

export type Curve = "monotone" | "linear";

/* ---------- Sampling ------------------------------------------------------- */

// d3-shape's curveMonotoneX tangents (Steffen 1990) for evenly spaced points, so a sampled
// curve is the exact curve d3 would draw. With x evenly spaced the Bézier's x is linear in t,
// so each segment is a cubic Hermite in y and can be evaluated at any x directly.
function tangents(v: readonly number[]) {
  const n = v.length;
  const t = new Float64Array(n);
  if (n < 2) return t;
  const s = (i: number) => v[i + 1] - v[i]; // secant over one step
  for (let i = 1; i < n - 1; i++) {
    const s0 = s(i - 1);
    const s1 = s(i);
    const p = (s0 + s1) / 2;
    t[i] = (Math.sign(s0) + Math.sign(s1)) * Math.min(Math.abs(s0), Math.abs(s1), 0.5 * Math.abs(p)) || 0;
  }
  t[0] = n > 2 ? (3 * s(0) - t[1]) / 2 : s(0);
  t[n - 1] = n > 2 ? (3 * s(n - 2) - t[n - 2]) / 2 : s(0);
  return t;
}

/**
 * Samples a series of evenly spaced values at `count` evenly spaced positions across the
 * same span, along a monotone (d3 `curveMonotoneX`) or straight curve. Two series with
 * different lengths sampled at the same `count` share their x positions: that is what lets
 * a 7-point line morph into a 30-point one without inventing or dropping vertices.
 */
export function sampleSeries(values: readonly number[], count: number, curve: Curve = "monotone"): Float64Array {
  const out = new Float64Array(count);
  const n = values.length;
  if (n === 0) return out;
  if (n === 1 || count === 1) return out.fill(n === 1 ? values[0] : values[n - 1]);
  const t = curve === "monotone" ? tangents(values) : null;
  for (let k = 0; k < count; k++) {
    const pos = (k / (count - 1)) * (n - 1);
    const i = Math.min(n - 2, Math.floor(pos));
    const u = pos - i;
    const y0 = values[i];
    const y1 = values[i + 1];
    if (!t) {
      out[k] = y0 + (y1 - y0) * u;
      continue;
    }
    const u2 = u * u;
    const u3 = u2 * u;
    out[k] = (2 * u3 - 3 * u2 + 1) * y0 + (u3 - 2 * u2 + u) * t[i] + (-2 * u3 + 3 * u2) * y1 + (u3 - u2) * t[i + 1];
  }
  return out;
}

/** The sampled value at `u` ∈ [0, 1] along a sampled series (linear between samples). */
export function sampleAt(samples: ArrayLike<number>, u: number) {
  const n = samples.length;
  if (n === 0) return 0;
  if (n === 1) return samples[0];
  const pos = Math.max(0, Math.min(1, u)) * (n - 1);
  const i = Math.min(n - 2, Math.floor(pos));
  return lerp(samples[i], samples[i + 1], pos - i);
}

function resample(samples: Float64Array, count: number) {
  if (samples.length === count) return samples;
  const out = new Float64Array(count);
  for (let k = 0; k < count; k++) out[k] = sampleAt(samples, count === 1 ? 1 : k / (count - 1));
  return out;
}

const round = (n: number) => Math.round(n * 100) / 100;

/** An SVG path through the samples. `x(u)` maps 0–1 across the plot, `y(v)` a value to a pixel. */
export function samplesToPath(samples: ArrayLike<number>, x: (u: number) => number, y: (v: number) => number) {
  const n = samples.length;
  if (n === 0) return "";
  let d = "";
  for (let k = 0; k < n; k++) d += `${k ? "L" : "M"}${round(x(n === 1 ? 1 : k / (n - 1)))},${round(y(samples[k]))}`;
  return d;
}

/** The same line closed down to `baseY`, for an area fill. */
export function samplesToArea(samples: ArrayLike<number>, x: (u: number) => number, y: (v: number) => number, baseY: number) {
  if (samples.length === 0) return "";
  return `${samplesToPath(samples, x, y)}L${round(x(1))},${round(baseY)}L${round(x(0))},${round(baseY)}Z`;
}

/** Where a series rests when it enters or leaves: zero if the domain holds it, else the nearer edge. */
export const baselineOf = ([lo, hi]: Domain) => Math.min(hi, Math.max(lo, 0));

/* ---------- useMorphPath --------------------------------------------------- */

/** What the chart should show: each series' values (evenly spaced in x) and the value domain. */
export type MorphShape = { series: Readonly<Record<string, readonly number[]>>; domain: Domain };
/** What is on screen this frame: every series sampled on shared x positions, and the domain. */
export type MorphFrame = { series: Record<string, Float64Array>; domain: Domain };

export type UseMorphPathOptions = {
  /** Draws a frame: write `d` attributes and move gridlines here. Called outside React render. */
  onFrame: (frame: MorphFrame) => void;
  /** Shared x samples per series. Default 160; keep ≥ 8 per data segment for smooth curves. */
  samples?: number;
  curve?: Curve;
  /** The morph's transition. Default `smooth` (no overshoot: data should not wobble past its value). */
  transition?: Transition;
  /** False jumps to every new shape (reduced motion, scrubbing a slider). Default true. */
  animate?: boolean;
};

const signature = (shape: MorphShape, count: number, curve: Curve) => {
  let s = `${count}|${curve}|${shape.domain[0]},${shape.domain[1]}`;
  for (const key of Object.keys(shape.series)) s += `|${key}:${shape.series[key].join(",")}`;
  return s;
};

/**
 * Morphs a set of paths between shapes the way Arc does, without React re-rendering a frame:
 * every series is resampled onto the same x positions, so any shape tweens into any other
 * point for point, and the value domain rides the same progress so gridlines and lines stay
 * in register. A change mid-morph starts from what is on screen. Series that appear grow out
 * of the baseline; series that leave flatten into it and are then dropped from the frame.
 *
 *   const morph = useMorphPath({ series: { revenue }, domain }, { onFrame: (f) => {
 *     line.current?.setAttribute("d", samplesToPath(f.series.revenue, x, y));
 *   }});
 *
 * Returns `get()` (the current frame) and `redraw()` (re-emit it, e.g. after a resize).
 */
export function useMorphPath(shape: MorphShape, { onFrame, samples = 160, curve = "monotone", transition = smooth, animate: animated = true }: UseMorphPathOptions) {
  const frame = useRef<MorphFrame | null>(null);
  const anim = useRef<AnimationPlaybackControls | null>(null);
  const draw = useRef(onFrame);
  const shapeRef = useRef(shape);
  const options = useRef({ samples, curve, transition, animated });
  useLayoutEffect(() => {
    draw.current = onFrame;
    shapeRef.current = shape;
    options.current = { samples, curve, transition, animated };
  });

  const key = signature(shape, samples, curve);
  useLayoutEffect(() => {
    const { samples: count, curve: c, transition: tr, animated: anime } = options.current;
    const next = shapeRef.current;
    const target: MorphFrame = { series: {}, domain: next.domain };
    for (const k of Object.keys(next.series)) target.series[k] = sampleSeries(next.series[k], count, c);

    const from = frame.current;
    anim.current?.stop();
    if (!from || !anime) {
      frame.current = target;
      draw.current(target);
      return;
    }

    const keys = new Set([...Object.keys(from.series), ...Object.keys(target.series)]);
    const a: Record<string, Float64Array> = {};
    const b: Record<string, Float64Array> = {};
    for (const k of keys) {
      a[k] = from.series[k] ? resample(from.series[k], count) : new Float64Array(count).fill(baselineOf(from.domain));
      b[k] = target.series[k] ?? new Float64Array(count).fill(baselineOf(target.domain));
    }
    const live: MorphFrame = { series: {}, domain: from.domain };
    for (const k of keys) live.series[k] = new Float64Array(count);

    anim.current = animate(0, 1, {
      ...tr,
      onUpdate: (p) => {
        for (const k of keys) {
          const out = live.series[k];
          const s0 = a[k];
          const s1 = b[k];
          for (let i = 0; i < count; i++) out[i] = s0[i] + (s1[i] - s0[i]) * p;
        }
        live.domain = [lerp(from.domain[0], target.domain[0], p), lerp(from.domain[1], target.domain[1], p)];
        frame.current = live;
        draw.current(live);
      },
      onComplete: () => {
        frame.current = target;
        draw.current(target);
      },
    });
  }, [key]);

  useLayoutEffect(() => () => anim.current?.stop(), []);

  const [api] = useState(() => ({
    get: () => frame.current,
    redraw: () => {
      if (frame.current) draw.current(frame.current);
    },
  }));
  return api;
}

"use client";

import { arc as d3arc } from "d3-shape";
import { animate, type AnimationPlaybackControls, type Transition } from "motion/react";
import { useLayoutEffect, useRef, useState } from "react";
import { smooth } from "../../lib/motion";
import { lerp } from "./scales";
import { spreadLabels } from "./value-label";

/*
 * Angles follow d3-shape: radians, clockwise, zero at 12 o'clock. A full turn is `TAU`.
 */

export const TAU = Math.PI * 2;

/** One keyed arc: where it starts and ends, in radians. */
export type ArcSlice = { key: string; start: number; end: number };

/** The point at `angle` and `radius` from the centre (y grows down, as in SVG). */
export function polar(angle: number, radius: number): [number, number] {
  return [Math.sin(angle) * radius, -Math.cos(angle) * radius];
}

/**
 * The angle of an offset from the centre, in [0, TAU): the inverse of `polar`, for hit testing.
 * Arcs laid out from a negative `startAngle` (a gauge from −0.75π) carry negative angles, so
 * test them against `a > Math.PI ? a - TAU : a`, or whichever turn their sweep covers.
 */
export function angleOf(dx: number, dy: number) {
  const a = Math.atan2(dx, -dy);
  return a < 0 ? a + TAU : a;
}

export const midAngle = (s: { start: number; end: number }) => (s.start + s.end) / 2;

export type PieLayoutOptions = {
  /** Where the first slice starts. Default 0 (12 o'clock). */
  startAngle?: number;
  /** Where the last slice ends. Default `TAU`; a gauge might sweep from −0.75π to 0.75π. */
  endAngle?: number;
};

/**
 * Splits a sweep between keyed values in the order given, never sorted, so the same key
 * keeps its place from one dataset to the next and morphs in place. A zero, negative or
 * missing value is a zero-width slice on its seam: it stays in the layout, so it can grow
 * back out of the same place.
 */
export function pieLayout(items: readonly { key: string; value: number }[], { startAngle = 0, endAngle = TAU }: PieLayoutOptions = {}): ArcSlice[] {
  const values = items.map((d) => (Number.isFinite(d.value) && d.value > 0 ? d.value : 0));
  const total = values.reduce((s, v) => s + v, 0);
  const k = total > 0 ? (endAngle - startAngle) / total : 0;
  let at = startAngle;
  return items.map((d, i) => {
    const start = at;
    at += values[i] * k;
    return { key: d.key, start, end: at };
  });
}

export type ArcShape = {
  outerRadius: number;
  /** 0 draws a pie wedge. Default 0. */
  innerRadius?: number;
  /** Rounds the arc's four corners, px; d3 clamps it to half the ring's thickness. Default 0. */
  cornerRadius?: number;
  /** Surface gap between neighbouring arcs, px, constant from the inner to the outer edge. Default 0. */
  gap?: number;
};

type ArcArgs = ArcShape & { start: number; end: number };
const ARC = d3arc<ArcArgs>()
  .innerRadius((a) => a.innerRadius ?? 0)
  .outerRadius((a) => a.outerRadius)
  .cornerRadius((a) => a.cornerRadius ?? 0)
  .padRadius((a) => a.outerRadius)
  .padAngle((a) => (a.gap ? a.gap / a.outerRadius : 0))
  .startAngle((a) => a.start)
  .endAngle((a) => a.end)
  .digits(2);

/** The SVG path of one arc around (0, 0), or "" when it has no width to draw. */
export function arcPath(shape: ArcShape, start: number, end: number) {
  if (!(end - start > 1e-4) || shape.outerRadius <= 0) return "";
  return ARC({ ...shape, start, end }) ?? "";
}

/* ---------- useArcMorph ---------------------------------------------------- */

export type UseArcMorphOptions = {
  /** Draws a frame: write `d` attributes and move labels here. Called outside React render. */
  onFrame: (slices: readonly ArcSlice[]) => void;
  /** The morph's transition. Default `smooth` (no overshoot). */
  transition?: Transition;
  /** False jumps to every new layout (reduced motion). Default true. */
  animate?: boolean;
  /**
   * Where a key with no partner grows out of and closes into: `"seam"` (default), its place
   * in a ring of touching slices; `"start"`, its own start angle, for arcs that each start at
   * the same angle (concentric rings, gauges).
   */
  grow?: "seam" | "start";
};

/** Each key's start and end on both sides of a morph. */
type Pair = { key: string; a: { start: number; end: number }; b: { start: number; end: number } };

/**
 * Where a slice with no partner on the other side sits: zero-width on the seam it grows out
 * of or closes into, i.e. the end of the nearest key before it that both sides share (else
 * the start of the nearest one after it, else its own start).
 */
function seam(order: readonly ArcSlice[], index: number, other: ReadonlyMap<string, ArcSlice>) {
  for (let j = index - 1; j >= 0; j--) {
    const s = other.get(order[j].key);
    if (s) return s.end;
  }
  for (let j = index + 1; j < order.length; j++) {
    const s = other.get(order[j].key);
    if (s) return s.start;
  }
  return order[index].start;
}

function pairsOf(from: readonly ArcSlice[], to: readonly ArcSlice[], grow: "seam" | "start"): Pair[] {
  const before = new Map(from.map((s) => [s.key, s]));
  const after = new Map(to.map((s) => [s.key, s]));
  const pairs: Pair[] = to.map((s, i) => {
    const a = before.get(s.key);
    const at = a ? 0 : grow === "start" ? s.start : seam(to, i, before);
    return { key: s.key, a: a ?? { start: at, end: at }, b: s };
  });
  // Leaving keys keep their place: after the nearest key before them that is still there.
  from.forEach((s, i) => {
    if (after.has(s.key)) return;
    const at = grow === "start" ? s.start : seam(from, i, after);
    let index = 0;
    for (let j = i - 1; j >= 0; j--) {
      const k = pairs.findIndex((p) => p.key === from[j].key);
      if (k !== -1) {
        index = k + 1;
        break;
      }
    }
    pairs.splice(index, 0, { key: s.key, a: s, b: { start: at, end: at } });
  });
  return pairs;
}

const sameKeys = (a: readonly string[], b: readonly string[]) => a.length === b.length && a.every((k, i) => k === b[i]);

/**
 * Morphs keyed arcs between layouts without React re-rendering a frame: every key tweens its
 * start and end angle on one progress, from whatever is on screen. A key that appears grows
 * out of the seam where it will sit; a key that leaves closes into its seam and is then
 * dropped. A change mid-morph starts from the frame on screen.
 *
 *   const { keys } = useArcMorph(pieLayout(items), { onFrame: (slices) => {
 *     for (const s of slices) paths.current[s.key]?.setAttribute("d", arcPath(shape, s.start, s.end));
 *   }});
 *
 * `keys` are the slices on screen, leaving ones included, in drawing order: render one
 * element per key. `get()` is the current frame; `redraw()` re-emits it, e.g. after a resize.
 */
export function useArcMorph(slices: readonly ArcSlice[], { onFrame, transition = smooth, animate: animated = true, grow = "seam" }: UseArcMorphOptions) {
  const frame = useRef<ArcSlice[] | null>(null);
  const anim = useRef<AnimationPlaybackControls | null>(null);
  const draw = useRef(onFrame);
  const latest = useRef({ slices, transition, animated, grow });
  const [keys, setKeys] = useState<readonly string[]>(() => slices.map((s) => s.key));
  useLayoutEffect(() => {
    draw.current = onFrame;
    latest.current = { slices, transition, animated, grow };
  });

  const settle = (next: readonly string[]) => setKeys((k) => (sameKeys(k, next) ? k : next));
  const signature = slices.map((s) => `${s.key}:${s.start.toFixed(5)}:${s.end.toFixed(5)}`).join("|");
  useLayoutEffect(() => {
    const { slices, transition: tr, animated: anime, grow: g } = latest.current;
    const target = slices.map((s) => ({ ...s }));
    const from = frame.current;
    anim.current?.stop();
    if (!from || !anime) {
      frame.current = target;
      settle(target.map((s) => s.key));
      draw.current(target);
      return;
    }
    const pairs = pairsOf(from, target, g);
    settle(pairs.map((p) => p.key));
    const live: ArcSlice[] = pairs.map((p) => ({ key: p.key, ...p.a }));
    anim.current = animate(0, 1, {
      ...tr,
      onUpdate: (t) => {
        pairs.forEach((p, i) => {
          live[i].start = lerp(p.a.start, p.b.start, t);
          live[i].end = lerp(p.a.end, p.b.end, t);
        });
        frame.current = live;
        draw.current(live);
      },
      onComplete: () => {
        frame.current = target;
        settle(target.map((s) => s.key));
        draw.current(target);
      },
    });
  }, [signature]);

  useLayoutEffect(() => () => anim.current?.stop(), []);
  // A key that just mounted has an element now: give it this frame's shape.
  useLayoutEffect(() => {
    if (frame.current) draw.current(frame.current);
  }, [keys]);

  const [api] = useState(() => ({
    get: () => frame.current as readonly ArcSlice[] | null,
    redraw: () => {
      if (frame.current) draw.current(frame.current);
    },
  }));
  return { keys, get: api.get, redraw: api.redraw };
}

/* ---------- Outside labels ------------------------------------------------- */

export type ArcLabelPlacement = {
  key: string;
  /** Which column the label sits in. */
  side: "left" | "right";
  /** Where the label's text starts (right) or ends (left), and its vertical centre, relative to the centre. */
  x: number;
  y: number;
  /** The leader line, relative to the centre: out from the arc, an elbow, then level into the label. */
  leader: string;
};

export type ArcLabelOptions = {
  /** The arcs' outer radius, px. */
  radius: number;
  /** How far the leader runs out from the arc before it turns, px. Default 12. */
  elbow?: number;
  /** The gap between the ring and each label column, px. Default 28. */
  column?: number;
  /** The space above and below the centre the labels may use, px. */
  top: number;
  bottom: number;
  /** A label's line height plus the air it needs, px. Default 20. */
  pitch?: number;
  /** Arcs narrower than this (radians) get no label. Default 0.02. */
  minAngle?: number;
};

/**
 * Outside labels for a ring: a column each side, each label level with the middle of its arc
 * where there is room, and spread apart (`spreadLabels`) where there is not. When a column
 * cannot hold them all, the labels of the narrowest arcs drop out. Returns a placement per
 * labelled arc; arcs that got none are left out.
 */
export function arcLabelLayout(slices: readonly ArcSlice[], { radius, elbow = 12, column = 28, top, bottom, pitch = 20, minAngle = 0.02 }: ArcLabelOptions): ArcLabelPlacement[] {
  const out: ArcLabelPlacement[] = [];
  for (const side of ["right", "left"] as const) {
    const items = slices
      .filter((s) => s.end - s.start >= minAngle && (Math.sin(midAngle(s)) >= 0) === (side === "right"))
      .map((s) => ({ key: s.key, at: polar(midAngle(s), radius + elbow)[1], priority: s.end - s.start, slice: s }));
    const placed = spreadLabels(items, { min: top + pitch / 2, max: bottom - pitch / 2, pitch });
    const dir = side === "right" ? 1 : -1;
    const x = dir * (radius + column);
    for (const item of items) {
      const y = placed.get(item.key);
      if (y === undefined) continue;
      const mid = midAngle(item.slice);
      const [x0, y0] = polar(mid, radius + 3);
      const [x1] = polar(mid, radius + elbow);
      const r = (n: number) => Math.round(n * 100) / 100;
      out.push({ key: item.key, side, x, y, leader: `M${r(x0)},${r(y0)}L${r(x1)},${r(y)}L${r(x - dir * 4)},${r(y)}` });
    }
  }
  return out;
}

"use client";

import type { Transition } from "motion/react";
import { createContext, useCallback, useContext, useMemo, useState, type ReactNode } from "react";
import { smooth } from "../../lib/motion";

/**
 * The shared date range of a page of charts. Changing it is one coordinated beat: every chart
 * under the provider morphs on the same transition, starting in the same frame.
 *
 * Frozen contract (lane 5 → Range Picker, Metrics Dashboard):
 *   range       the selected range key, e.g. "7d"
 *   setRange    select another range
 *   beat        increments on every change; key per-change effects off it
 *   transition  the morph every chart under the provider uses
 *   compare     whether a previous-period series is shown
 *   setCompare  toggle it
 */
export type ChartRangeValue<R extends string = string> = {
  range: R;
  setRange: (range: R) => void;
  beat: number;
  transition: Transition;
  compare: boolean;
  setCompare: (compare: boolean) => void;
};

export const ChartRangeContext = createContext<ChartRangeValue | null>(null);

export type ChartRangeProviderProps<R extends string> = {
  /** Controlled range. */
  value?: R;
  /** Uncontrolled initial range. */
  defaultValue?: R;
  onValueChange?: (range: R) => void;
  compare?: boolean;
  defaultCompare?: boolean;
  onCompareChange?: (compare: boolean) => void;
  /** The morph shared by every chart below. Default `smooth`. */
  transition?: Transition;
  children: ReactNode;
};

export function ChartRangeProvider<R extends string>({
  value,
  defaultValue,
  onValueChange,
  compare: compareProp,
  defaultCompare = false,
  onCompareChange,
  transition = smooth,
  children,
}: ChartRangeProviderProps<R>) {
  const [inner, setInner] = useState(defaultValue as R);
  const [innerCompare, setInnerCompare] = useState(defaultCompare);
  const [beat, setBeat] = useState(0);
  const range = value ?? inner;
  const compare = compareProp ?? innerCompare;

  const setRange = useCallback(
    (next: R) => {
      if (next === range) return;
      setInner(next);
      setBeat((b) => b + 1);
      onValueChange?.(next);
    },
    [range, onValueChange],
  );
  const setCompare = useCallback(
    (next: boolean) => {
      setInnerCompare(next);
      onCompareChange?.(next);
    },
    [onCompareChange],
  );

  const ctx = useMemo(
    () => ({ range, setRange, beat, transition, compare, setCompare }) as unknown as ChartRangeValue,
    [range, setRange, beat, transition, compare, setCompare],
  );
  return <ChartRangeContext.Provider value={ctx}>{children}</ChartRangeContext.Provider>;
}

/** The surrounding range, or null outside a `ChartRangeProvider`. */
export function useChartRange<R extends string = string>() {
  return useContext(ChartRangeContext) as ChartRangeValue<R> | null;
}

/** The morph transition a chart should use: the provider's, else `fallback`. */
export function useChartTransition(fallback: Transition = smooth) {
  return useContext(ChartRangeContext)?.transition ?? fallback;
}

import { scaleLinear } from "d3-scale";

/** A value domain, low to high. */
export type Domain = readonly [number, number];

export type NiceScaleOptions = {
  /** Keep zero inside the domain. Bars and areas need it; lines may drop it. Default true. */
  zero?: boolean;
  /** Roughly how many gridlines. Default 4. */
  ticks?: number;
};

/**
 * A clean value domain and its gridline values for a set of numbers: rounded to tick steps
 * (0 / 2K / 4K …), zero kept by default, and a flat or empty series still gets a usable range.
 */
export function niceScale(values: Iterable<number>, { zero = true, ticks = 4 }: NiceScaleOptions = {}) {
  let lo = Infinity;
  let hi = -Infinity;
  for (const v of values) {
    if (!Number.isFinite(v)) continue;
    if (v < lo) lo = v;
    if (v > hi) hi = v;
  }
  if (lo === Infinity) [lo, hi] = [0, 1];
  if (zero) [lo, hi] = [Math.min(0, lo), Math.max(0, hi)];
  if (lo === hi) [lo, hi] = lo === 0 ? [0, 1] : [lo - Math.abs(lo) * 0.1, hi + Math.abs(hi) * 0.1];
  // d3's tick count is a hint; step it down until there are at most `ticks + 1` lines.
  for (let count = ticks; ; count--) {
    const scale = scaleLinear().domain([lo, hi]).nice(count);
    const t = scale.ticks(count);
    if (t.length <= ticks + 1 || count <= 1) {
      const [a, b] = scale.domain();
      return { domain: [a, b] as Domain, ticks: t };
    }
  }
}

/** Maps a value in `domain` to a pixel in `range`; `range` may run high to low (y grows down). */
export function linear(domain: Domain, range: Domain) {
  const [d0, d1] = domain;
  const [r0, r1] = range;
  const k = d1 === d0 ? 0 : (r1 - r0) / (d1 - d0);
  return (v: number) => r0 + (v - d0) * k;
}

export const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

/**
 * Which of `count` evenly spaced x labels to show at `width`: at most one per `minGap` px
 * (Arc's 76), always keeping the newest, then stepping back from it so the gaps stay even.
 */
export function thinLabels(count: number, width: number, minGap = 76): number[] {
  if (count <= 0) return [];
  if (count === 1) return [0];
  const spacing = width / (count - 1);
  const step = Math.max(1, Math.ceil(minGap / Math.max(spacing, 0.0001)));
  const out: number[] = [];
  for (let i = count - 1; i >= 0; i -= step) out.unshift(i);
  return out;
}

/** Evenly spaced bands for bars: the band width, each band's left edge, and a bar width capped at 24px with ≥ 2px air. */
export function bands(count: number, width: number, { maxBar = 24, gap = 0.32 }: { maxBar?: number; gap?: number } = {}) {
  const band = count > 0 ? width / count : width;
  const bar = Math.max(1, Math.min(maxBar, band - Math.max(2, band * gap)));
  return { band, bar, left: (i: number) => i * band, center: (i: number) => i * band + band / 2 };
}

"use client";

import { animate, motion, useMotionValue, type MotionValue, type Transition } from "motion/react";
import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  useSyncExternalStore,
  type CSSProperties,
  type FocusEvent,
  type KeyboardEvent,
  type PointerEvent,
  type ReactNode,
} from "react";
import { enter, exitFast, instant, smooth, snappy } from "../../lib/motion";

/* ---------- Active index store --------------------------------------------- */

/**
 * The scrubbed index, outside React state: the plot never re-renders while you scrub.
 * Only the pieces that show the value (tooltip, headline) subscribe.
 */
export type ActiveStore = {
  get(): number | null;
  set(index: number | null): void;
  subscribe(listener: () => void): () => void;
};

export function createActiveStore(): ActiveStore {
  let value: number | null = null;
  const listeners = new Set<() => void>();
  return {
    get: () => value,
    set(next) {
      if (next === value) return;
      value = next;
      for (const l of listeners) l();
    },
    subscribe(l) {
      listeners.add(l);
      return () => listeners.delete(l);
    },
  };
}

/** One store per chart, stable across renders. */
export function useActiveStore() {
  const [store] = useState(createActiveStore);
  return store;
}

/** Subscribe a component to the scrubbed index (re-renders only that component). */
export function useActiveIndex(store: ActiveStore) {
  return useSyncExternalStore(store.subscribe, store.get, () => null);
}

/* ---------- Scrub: pointer, keyboard, crosshair ---------------------------- */

export type UseChartScrubOptions = {
  /** Number of points (or bars). */
  count: number;
  store: ActiveStore;
  /** The pixel x of point `i`, relative to the scrub surface. */
  xOf: (index: number) => number;
  /** The nearest index to a pixel x on the scrub surface. */
  indexAt: (x: number) => number;
  /** What a screen reader hears for point `i`: date, then every visible value. */
  valueText: (index: number) => string;
  /** The figure's name, e.g. "Revenue, last 30 days". */
  label: string;
  onActiveChange?: (index: number | null) => void;
  reduced?: boolean;
  /** How the crosshair glides between points. Default `snappy`. */
  transition?: Transition;
};

/**
 * The interaction model every Eased chart shares (Arc's, kept): the plot is one
 * `role="slider"` whose value is the scrubbed point. Pointer and touch scrub it (vertical
 * page scroll still works); arrows step, PageUp/PageDown jump a tenth, Home/End go to the
 * ends, Escape lets go. `aria-valuetext` reads the date and every value, updated in place.
 *
 * Returns props to spread on the scrub surface (a div exactly over the plot) and the
 * crosshair's motion values: `x` glides to the active point, `opacity` fades it in and out.
 */
export function useChartScrub({ count, store, xOf, indexAt, valueText, label, onActiveChange, reduced = false, transition = snappy }: UseChartScrubOptions) {
  const ref = useRef<HTMLDivElement>(null);
  const x = useMotionValue(0);
  const opacity = useMotionValue(0);
  const latest = useRef({ count, xOf, valueText, onActiveChange, reduced, transition });
  useLayoutEffect(() => {
    latest.current = { count, xOf, valueText, onActiveChange, reduced, transition };
  });

  // Follow the store: glide the crosshair, keep ARIA current, notify.
  useEffect(() => {
    let shown = store.get() !== null;
    const sync = () => {
      const i = store.get();
      const { xOf, valueText, onActiveChange, reduced, transition, count } = latest.current;
      const el = ref.current;
      if (el && count > 0) {
        const now = i ?? count - 1;
        el.setAttribute("aria-valuenow", String(now));
        el.setAttribute("aria-valuetext", valueText(now));
      }
      if (i === null) {
        animate(opacity, 0, reduced ? instant : exitFast);
        shown = false;
      } else {
        const target = xOf(i);
        if (!shown || reduced) x.jump(target);
        else animate(x, target, transition);
        animate(opacity, 1, reduced ? instant : { duration: 0.12 });
        shown = true;
      }
      onActiveChange?.(i);
    };
    return store.subscribe(sync);
  }, [store, x, opacity]);

  // Data or size changed under an active point: clamp it and re-seat the crosshair.
  useLayoutEffect(() => {
    const i = store.get();
    if (i === null) return;
    if (i > count - 1) store.set(count > 0 ? count - 1 : null);
    else animate(x, xOf(i), reduced ? instant : smooth);
  }, [count, xOf, store, x, reduced]);

  const fromPointer = useCallback(
    (e: PointerEvent<HTMLDivElement>) => {
      const rect = e.currentTarget.getBoundingClientRect();
      const i = indexAt(e.clientX - rect.left);
      store.set(Math.max(0, Math.min(count - 1, i)));
    },
    [count, indexAt, store],
  );

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (count === 0) return;
    const i = store.get() ?? count - 1;
    const page = Math.max(1, Math.round(count / 10));
    const next: Record<string, number | null> = {
      ArrowRight: i + 1,
      ArrowUp: i + 1,
      ArrowLeft: i - 1,
      ArrowDown: i - 1,
      PageUp: i + page,
      PageDown: i - page,
      Home: 0,
      End: count - 1,
      Escape: null,
    };
    if (!(e.key in next)) return;
    e.preventDefault();
    const n = next[e.key];
    store.set(n === null ? null : Math.max(0, Math.min(count - 1, n)));
  };

  const last = Math.max(0, count - 1);
  const props = {
    ref,
    role: "slider",
    tabIndex: count > 0 ? 0 : -1,
    "aria-label": label,
    "aria-valuemin": 0,
    "aria-valuemax": last,
    "aria-valuenow": last,
    "aria-valuetext": count > 0 ? valueText(last) : undefined,
    "aria-orientation": "horizontal" as const,
    onKeyDown,
    onFocus: (e: FocusEvent<HTMLDivElement>) => {
      // Keyboard focus lands on the newest point; pointer focus is handled by the pointer.
      if (e.currentTarget.matches(":focus-visible") && store.get() === null && count > 0) store.set(count - 1);
    },
    onBlur: () => store.set(null),
    onPointerDown: fromPointer,
    onPointerMove: fromPointer,
    onPointerLeave: () => store.set(null),
    onPointerCancel: () => store.set(null),
    style: { touchAction: "pan-y" } as CSSProperties,
  };

  return { props, x, opacity };
}

/* ---------- Tooltip -------------------------------------------------------- */

export type ChartTooltipProps = {
  store: ActiveStore;
  /** The pixel x of point `i`, in the same coordinates as the tooltip's container. */
  xOf: (index: number) => number;
  /** The container's width; the tooltip flips to the left of the point before it overflows. */
  width: number;
  /** Gap between the point and the tooltip, px. Default 12. */
  offset?: number;
  /** Distance from the container's top, px. Default 0. */
  top?: number;
  reduced?: boolean;
  /** The content for point `i`. Re-rendered only while scrubbing, and only here. */
  children: (index: number) => ReactNode;
  className?: string;
};

/**
 * A floating readout that follows the scrubbed point on its own `smooth` spring, a beat
 * behind the crosshair, and flips sides before it would leave the plot. It keeps showing the
 * last point while it fades out, so content never blanks mid-exit. `aria-hidden`: the slider
 * already reads the same values.
 */
export function ChartTooltip({ store, xOf, width, offset = 12, top = 0, reduced = false, children, className = "" }: ChartTooltipProps) {
  const index = useActiveIndex(store);
  const [shown, setShown] = useState<number | null>(null);
  const el = useRef<HTMLDivElement>(null);
  const x = useMotionValue(0);
  const visible = useRef(false);
  if (index !== null && index !== shown) setShown(index);

  useLayoutEffect(() => {
    if (index === null || !el.current) {
      visible.current = false;
      return;
    }
    const w = el.current.offsetWidth;
    const px = xOf(index);
    const right = px + offset + w <= width;
    const target = Math.max(0, Math.min(width - w, right ? px + offset : px - offset - w));
    if (!visible.current || reduced) x.jump(target);
    else animate(x, target, smooth);
    visible.current = true;
  }, [index, xOf, width, offset, reduced, x]);

  return (
    <motion.div
      ref={el}
      aria-hidden
      className={`pointer-events-none absolute left-0 z-10 rounded-control border border-line bg-surface-raised px-3 py-2 text-ui-xs text-text shadow-floating ${className}`}
      style={{ x, top }}
      initial={false}
      animate={index === null ? { opacity: 0, scale: 0.97 } : { opacity: 1, scale: 1 }}
      transition={reduced ? instant : index === null ? exitFast : enter}
    >
      {shown !== null && children(shown)}
    </motion.div>
  );
}

/** The crosshair's motion values, for a vertical rule in the plot's `<svg>`. */
export function Crosshair({ x, opacity, height, top = 0 }: { x: MotionValue<number>; opacity: MotionValue<number>; height: number; top?: number }) {
  return (
    <motion.line
      aria-hidden
      x1={0}
      x2={0}
      y1={top}
      y2={height}
      stroke="var(--eased-chart-cursor)"
      strokeWidth={1}
      style={{ x, opacity }}
      shapeRendering="crispEdges"
    />
  );
}

import type { Domain } from "./scales";
import { chartColor } from "./tokens";

/**
 * The colour of a cell with no value (null, NaN, or 0 when zero is empty): the line colour, one
 * step firmer than the chart grid so an empty cell still reads as a cell (1.44:1 on a light
 * surface, 1.65:1 on a dark one).
 */
export const SEQUENTIAL_EMPTY = "var(--eased-line)";

export type SequentialStop = {
  /** 0 for the lightest step. */
  step: number;
  color: string;
  /** The step covers values from `from` (inclusive) to `to` (exclusive; the last step includes it). */
  from: number;
  to: number;
};

export type SequentialScale = {
  domain: Domain;
  steps: number;
  /** The colour for missing values. */
  empty: string;
  /** One per step, lightest first: a legend draws these. */
  stops: readonly SequentialStop[];
  /** The step a value falls in, clamped to the domain, or -1 when it is empty. */
  step: (value: number | null | undefined) => number;
  /** The step's colour, or `empty`. */
  color: (value: number | null | undefined) => string;
};

export type SequentialScaleOptions = {
  /** How many colour steps the domain splits into, 2 to 9. Default 5. */
  steps?: number;
  /** The hue the ramp builds to. Default `chartColor(1)`. */
  color?: string;
  /** Draw a value of exactly 0 as empty, not as the lightest step: counts, where nothing happened. Default true. */
  zeroIsEmpty?: boolean;
};

/**
 * The ramp alone: `steps` colours from just past the empty cell to past the hue. The first
 * steps mix the hue into the empty colour in even shares (at most half for the first of two);
 * the last leans 30% toward the text colour, one more even lightness step past the hue. Mixed
 * in Oklab, so the ramp keeps one hue and its lightness changes evenly (Oklab L 0.80 → 0.47 in
 * light, 0.43 → 0.72 in dark): darker means more on a light surface, brighter on a dark one,
 * and it reads under every colour vision deficiency. With five steps, neighbouring steps differ
 * by 1.28–1.56:1 in contrast, and the first sits 1.28:1 from empty: tell values apart in the
 * tooltip or table, not by shade alone.
 */
export function sequentialColors(steps = 5, color = chartColor(1)): string[] {
  const n = Math.max(2, Math.min(9, Math.round(steps)));
  return Array.from({ length: n }, (_, i) =>
    i === n - 1
      ? `color-mix(in oklab, ${color} 70%, var(--eased-text))`
      : `color-mix(in oklab, ${color} ${Math.round(((i + 1) / Math.max(2, n - 1)) * 1000) / 10}%, ${SEQUENTIAL_EMPTY})`,
  );
}

/**
 * A sequential colour scale for magnitudes: heatmaps, cohort and retention tables. Splits
 * `domain` into `steps` equal bins, each a token-built colour, and returns the bins as legend
 * stops. Pass a fixed domain (e.g. [0, 1] for retention) when two datasets should share colours.
 */
export function sequentialScale(domain: Domain, { steps = 5, color = chartColor(1), zeroIsEmpty = true }: SequentialScaleOptions = {}): SequentialScale {
  const colors = sequentialColors(steps, color);
  const n = colors.length;
  const [lo, hi] = domain;
  const span = hi - lo;
  const step = (value: number | null | undefined) => {
    if (value == null || !Number.isFinite(value) || (zeroIsEmpty && value === 0)) return -1;
    if (span <= 0) return n - 1;
    return Math.max(0, Math.min(n - 1, Math.floor(((value - lo) / span) * n)));
  };
  return {
    domain,
    steps: n,
    empty: SEQUENTIAL_EMPTY,
    stops: colors.map((c, i) => ({ step: i, color: c, from: lo + (span * i) / n, to: lo + (span * (i + 1)) / n })),
    step,
    color: (value) => {
      const s = step(value);
      return s === -1 ? SEQUENTIAL_EMPTY : colors[s];
    },
  };
}

/**
 * The chart palette: six categorical hues in a fixed order, stepped separately for light and
 * dark and validated as a set (adjacent CVD ΔE ≥ 8.4, normal-vision ΔE ≥ 19.3, both themes).
 * Slots 3–5 sit under 3:1 on a white surface, which is why every chart ships a data table and
 * a legend: identity is never colour alone.
 *
 * They live here until `eased.css` carries them. Declared at zero specificity, so the same
 * variables in `eased.css` (or your own theme) win the moment they exist.
 */
const LIGHT = [
  "oklch(57.5% 0.163 255.5)", // blue
  "oklch(67.1% 0.175 40.6)", // orange
  "oklch(66.9% 0.141 162.1)", // aqua
  "oklch(76.4% 0.161 75.1)", // amber
  "oklch(71.6% 0.141 357.4)", // pink
  "oklch(52.7% 0.197 283.4)", // violet
];
const DARK = [
  "oklch(62.2% 0.161 255.1)",
  "oklch(62.2% 0.173 40.1)",
  "oklch(62.1% 0.128 163.1)",
  "oklch(67% 0.143 73.2)",
  "oklch(62.2% 0.171 0.8)",
  "oklch(67% 0.145 286.8)",
];

const vars = (colors: string[]) => colors.map((c, i) => `--eased-chart-${i + 1}:${c};`).join("");

/** The CSS the charts inject; also what to paste into `eased.css` to make the tokens global. */
export const CHART_TOKENS_CSS =
  `:where(:root){${vars(LIGHT)}--eased-chart-grid:var(--eased-line-subtle);--eased-chart-cursor:var(--eased-line-strong);}` +
  `:where(.dark,[data-theme="dark"]){${vars(DARK)}}`;

/**
 * Renders the chart tokens once per document (React 19 hoists and dedupes a `<style>` with
 * an `href`). Every chart renders it; you never need to.
 */
export function ChartTokens() {
  return (
    <style href="eased-chart-tokens" precedence="low">
      {CHART_TOKENS_CSS}
    </style>
  );
}

/** Number of categorical slots. A seventh series is not a generated hue: fold it into "Other". */
export const CHART_SLOTS = 6;

/**
 * The colour for series slot `n` (1-based) as a CSS variable. Slots past six fall back to
 * muted text rather than cycling, so two series never share a hue silently.
 */
export function chartColor(n: number) {
  return n >= 1 && n <= CHART_SLOTS ? `var(--eased-chart-${n})` : "var(--eased-text-muted)";
}

"use client";

import { useLayoutEffect, useRef, useState, type RefObject } from "react";

export type ChartSize = { width: number; height: number };

/**
 * The content-box size of an element, kept current with a ResizeObserver and rounded to
 * whole pixels so sub-pixel jitter never re-renders a chart. 0 × 0 until measured (and on the
 * server), so draw nothing until `width > 0`.
 */
export function useChartSize<T extends HTMLElement = HTMLDivElement>(): [RefObject<T | null>, ChartSize] {
  const ref = useRef<T>(null);
  const [size, setSize] = useState<ChartSize>({ width: 0, height: 0 });

  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const update = (width: number, height: number) => {
      const w = Math.round(width);
      const h = Math.round(height);
      setSize((s) => (s.width === w && s.height === h ? s : { width: w, height: h }));
    };
    const rect = el.getBoundingClientRect();
    update(rect.width, rect.height);
    const ro = new ResizeObserver(([entry]) => update(entry.contentRect.width, entry.contentRect.height));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  return [ref, size];
}

"use client";

import type { ReactNode, Ref } from "react";
import { NumberRoll, type NumberRollFormat } from "../number-roll/number-roll";

/* ---------- ChartValueLabel ------------------------------------------------ */

export type ValueLabelAlign = "start" | "center" | "end";

export type ChartValueLabelProps = NumberRollFormat & {
  value: number;
  /** Text before the number, e.g. the slice or series name. */
  label?: ReactNode;
  /** False shows a new value at once instead of rolling to it. Default true. */
  animated?: boolean;
  /** Fades the label back while another part of the chart is active. */
  dimmed?: boolean;
  ref?: Ref<HTMLDivElement>;
  className?: string;
};

/**
 * A value printed on a chart: an optional name, then the number, which rolls to each new
 * value (NumberRoll). It renders hidden at the top left of its positioned container; the
 * chart moves it each frame with `placeValueLabel`, so it rides a morph without React
 * re-rendering. `aria-hidden`: the chart's slider and data table already read every value.
 */
export function ChartValueLabel({ value, label, animated = true, dimmed = false, ref, className = "", ...format }: ChartValueLabelProps) {
  return (
    <div
      ref={ref}
      aria-hidden
      data-hidden=""
      data-dimmed={dimmed || undefined}
      className={`pointer-events-none absolute top-0 left-0 flex items-center gap-1.5 text-ui-xs whitespace-nowrap transition-opacity duration-150 ease-standard data-hidden:opacity-0 data-dimmed:not-data-hidden:opacity-35 reduced:transition-none ${className}`}
    >
      {label != null && <span className="min-w-0 truncate text-text-secondary">{label}</span>}
      <span className="shrink-0 font-medium text-text tabular-nums">
        <NumberRoll value={value} animated={animated} {...format} aria-hidden />
      </span>
    </div>
  );
}

export type ValueLabelPlacement = {
  /** The anchor point in the container, px; `align` says which edge of the label sits on it. */
  x: number;
  /** The label's vertical centre, px. */
  y: number;
  align: ValueLabelAlign;
  /** False fades the label out where it stands. */
  visible: boolean;
  /** Truncates the name past this width, px. */
  maxWidth?: number;
};

const SHIFT: Record<ValueLabelAlign, string> = { start: "0%", center: "-50%", end: "-100%" };

/** Moves a `ChartValueLabel` to its spot for this frame. Call it from a chart's `onFrame`. */
export function placeValueLabel(el: HTMLElement | null, { x, y, align, visible, maxWidth }: ValueLabelPlacement) {
  if (!el) return;
  el.style.transform = `translate(${Math.round(x * 2) / 2}px, ${Math.round(y * 2) / 2}px) translate(${SHIFT[align]}, -50%)`;
  el.style.maxWidth = maxWidth === undefined ? "" : `${Math.max(0, Math.floor(maxWidth))}px`;
  el.toggleAttribute("data-hidden", !visible);
}

/* ---------- Collision ------------------------------------------------------ */

export type SpreadItem = {
  key: string;
  /** Where the label wants to sit, px along the axis. */
  at: number;
  /** Which labels to keep when they do not all fit; higher stays. Default 0. */
  priority?: number;
};

/**
 * One-dimensional label collision: keeps each label as close to where it wants to be as it
 * can while every pair stays at least `pitch` apart inside [min, max]. When they do not all
 * fit, the lowest-priority labels drop out first. Returns the position of every label kept.
 * Works along any axis: a column of arc labels, a row of bar value labels.
 */
export function spreadLabels(items: readonly SpreadItem[], { min, max, pitch }: { min: number; max: number; pitch: number }): Map<string, number> {
  const fit = Math.max(0, Math.floor((max - min) / pitch) + 1);
  let kept = [...items].sort((a, b) => a.at - b.at);
  if (kept.length > fit) {
    const drop = new Set(
      [...kept]
        .sort((a, b) => (a.priority ?? 0) - (b.priority ?? 0))
        .slice(0, kept.length - fit)
        .map((d) => d.key),
    );
    kept = kept.filter((d) => !drop.has(d.key));
  }
  const pos = kept.map((d) => Math.max(min, Math.min(max, d.at)));
  // Down from the top, then back up from the bottom: the smallest move that clears every overlap.
  for (let i = 1; i < pos.length; i++) pos[i] = Math.max(pos[i], pos[i - 1] + pitch);
  if (pos.length && pos[pos.length - 1] > max) {
    pos[pos.length - 1] = max;
    for (let i = pos.length - 2; i >= 0; i--) pos[i] = Math.min(pos[i], pos[i + 1] - pitch);
  }
  return new Map(kept.map((d, i) => [d.key, pos[i]]));
}

"use client";

import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import type { ChatFilePart } from "./types";

/* ---------- The model ---------------------------------------------------------- */

export type AttachmentKind = "image" | "file";
export type AttachmentStatus = "uploading" | "done" | "error";

/** One attachment in a composer or a sent message. Plain data: store it anywhere. */
export type Attachment = {
  id: string;
  name: string;
  /** `image` shows a thumbnail; everything else is a file chip. */
  kind: AttachmentKind;
  /** MIME type, e.g. `image/png`, `application/pdf`. */
  mediaType: string;
  /** Bytes. */
  size?: number;
  /** Where the file lives once uploaded (or a `data:` URL). Sent as the `file` part's `url`. */
  url?: string;
  /** A local preview for images while they upload (an object URL). */
  previewUrl?: string;
  /** Default `done`. */
  status?: AttachmentStatus;
  /** Upload progress 0–1 while `uploading`; leave it out when unknown (the ring spins). */
  progress?: number;
  /** Shown under the name when `status` is `error`, e.g. "Over 20 MB". */
  error?: string;
  /** The original file, when it came from the user's device. */
  file?: File;
};

export const kindOf = (mediaType: string): AttachmentKind => (mediaType.startsWith("image/") ? "image" : "file");

let counter = 0;
const newId = () => (typeof crypto !== "undefined" && "randomUUID" in crypto ? crypto.randomUUID() : `att-${Date.now()}-${++counter}`);

/** An attachment for a picked, dropped or pasted file. Images get an object-URL preview: call `releaseAttachment` when done. */
export function attachmentFromFile(file: File, status: AttachmentStatus = "uploading"): Attachment {
  const mediaType = file.type || "application/octet-stream";
  const kind = kindOf(mediaType);
  return {
    id: newId(),
    name: file.name || (kind === "image" ? "Pasted image" : "File"),
    kind,
    mediaType,
    size: file.size,
    previewUrl: kind === "image" ? URL.createObjectURL(file) : undefined,
    status,
    file,
  };
}

/** Frees an attachment's object-URL preview. */
export function releaseAttachment(a: Attachment) {
  if (a.previewUrl?.startsWith("blob:")) URL.revokeObjectURL(a.previewUrl);
}

/** `1.2 MB`, `840 KB`, with a no-break space. */
export function formatBytes(bytes: number, locale?: Intl.LocalesArgument) {
  if (bytes < 1000) return `${new Intl.NumberFormat(locale).format(bytes)}\u00a0${bytes === 1 ? "byte" : "bytes"}`;
  const units = ["byte", "kilobyte", "megabyte", "gigabyte"] as const;
  let i = 0;
  let n = bytes;
  while (n >= 1000 && i < units.length - 1) {
    n /= 1000;
    i++;
  }
  return new Intl.NumberFormat(locale, { style: "unit", unit: units[i], unitDisplay: "short", maximumFractionDigits: n < 10 && i > 0 ? 1 : 0 })
    .format(n)
    .replace(" ", " ");
}

/** The short type label for a file chip: `PDF`, `CSV`, `ZIP`. */
export function fileTypeLabel(a: Pick<Attachment, "name" | "mediaType">) {
  const ext = a.name.includes(".") ? a.name.split(".").pop() : undefined;
  return (ext || a.mediaType.split("/").pop() || "file").slice(0, 4).toUpperCase();
}

/** An AI SDK `file` part for a finished attachment (`sendMessage({ text, files })`). Returns null until it has a URL. */
export function toFilePart(a: Attachment): ChatFilePart | null {
  const url = a.url ?? (a.status === "done" || a.status === undefined ? a.previewUrl : undefined);
  return url ? { type: "file", mediaType: a.mediaType, filename: a.name, url } : null;
}

/** The reverse: an attachment to render a sent `file` part. */
export function fromFilePart(part: ChatFilePart, id = part.url): Attachment {
  return { id, name: part.filename ?? "Attachment", kind: kindOf(part.mediaType), mediaType: part.mediaType, url: part.url, status: "done" };
}

/* ---------- useAttachments ---------------------------------------------------- */

/** Uploads one file. Report progress 0–1; resolve with where it now lives. Respect `signal`. */
export type UploadFn = (file: File, ctx: { onProgress: (fraction: number) => void; signal: AbortSignal }) => Promise<{ url: string }>;

export type UseAttachmentsOptions = {
  /** Upload each file as it is added. Without it, files are kept locally (`done`, previewed by object URL). */
  upload?: UploadFn;
  /** Same syntax as `<input accept>`, e.g. `"image/*,.pdf"`. Files that do not match are rejected. */
  accept?: string;
  /** Bytes; larger files are added with an error so the user sees why. */
  maxSize?: number;
  /** Extra files past this are dropped and reported through `onReject`. */
  maxFiles?: number;
  /** Called with files that were refused, and why. */
  onReject?: (rejected: { file: File; reason: "type" | "count" }[]) => void;
  /** Controlled list. Pair with `onChange`. */
  value?: Attachment[];
  defaultValue?: Attachment[];
  onChange?: (attachments: Attachment[]) => void;
};

export function matchesAccept(file: File, accept?: string) {
  if (!accept) return true;
  const name = file.name.toLowerCase();
  const type = file.type.toLowerCase();
  return accept.split(",").some((raw) => {
    const rule = raw.trim().toLowerCase();
    if (!rule) return false;
    if (rule.startsWith(".")) return name.endsWith(rule);
    if (rule.endsWith("/*")) return type.startsWith(rule.slice(0, -1));
    return type === rule;
  });
}

/**
 * The attachment state machine for a composer: add (pick, drop, paste), upload with progress,
 * cancel on remove, retry on error, and clear after sending. Object-URL previews are freed
 * when an attachment leaves the list and on unmount.
 */
export function useAttachments({ upload, accept, maxSize, maxFiles, onReject, value, defaultValue, onChange }: UseAttachmentsOptions = {}) {
  const [inner, setInner] = useState<Attachment[]>(defaultValue ?? []);
  const attachments = value ?? inner;
  const list = useRef(attachments);
  const controllers = useRef(new Map<string, AbortController>());
  const latest = useRef({ upload, onChange, controlled: value !== undefined });
  useLayoutEffect(() => {
    list.current = attachments;
    latest.current = { upload, onChange, controlled: value !== undefined };
  });

  const commit = useCallback((next: Attachment[]) => {
    for (const a of list.current) if (!next.some((n) => n.id === a.id)) releaseAttachment(a);
    list.current = next;
    if (!latest.current.controlled) setInner(next);
    latest.current.onChange?.(next);
  }, []);

  const patch = useCallback(
    (id: string, changes: Partial<Attachment>) => {
      if (!list.current.some((a) => a.id === id)) return;
      commit(list.current.map((a) => (a.id === id ? { ...a, ...changes } : a)));
    },
    [commit],
  );

  const start = useCallback(
    (a: Attachment) => {
      const fn = latest.current.upload;
      if (!fn || !a.file) return;
      const controller = new AbortController();
      controllers.current.set(a.id, controller);
      let last = 0;
      fn(a.file, {
        signal: controller.signal,
        onProgress: (fraction) => {
          // Throttle to visible steps; the ring springs between them.
          if (controller.signal.aborted || (fraction - last < 0.01 && fraction < 1)) return;
          last = fraction;
          patch(a.id, { progress: Math.min(1, Math.max(0, fraction)) });
        },
      }).then(
        ({ url }) => {
          controllers.current.delete(a.id);
          if (!controller.signal.aborted) patch(a.id, { status: "done", progress: 1, url, error: undefined });
        },
        (err: unknown) => {
          controllers.current.delete(a.id);
          if (!controller.signal.aborted) patch(a.id, { status: "error", error: err instanceof Error ? err.message : "Upload failed" });
        },
      );
    },
    [patch],
  );

  const add = useCallback(
    (files: Iterable<File> | ArrayLike<File>) => {
      const incoming = Array.from(files);
      const rejected: { file: File; reason: "type" | "count" }[] = [];
      const room = maxFiles === undefined ? Infinity : Math.max(0, maxFiles - list.current.length);
      const added: Attachment[] = [];
      for (const file of incoming) {
        if (!matchesAccept(file, accept)) rejected.push({ file, reason: "type" });
        else if (added.length >= room) rejected.push({ file, reason: "count" });
        else {
          const tooBig = maxSize !== undefined && file.size > maxSize;
          const a = attachmentFromFile(file, tooBig ? "error" : latest.current.upload ? "uploading" : "done");
          if (tooBig) a.error = `Over ${formatBytes(maxSize!)}`;
          added.push(a);
        }
      }
      if (rejected.length) onReject?.(rejected);
      if (!added.length) return [];
      commit([...list.current, ...added]);
      for (const a of added) if (a.status === "uploading") start(a);
      return added;
    },
    [accept, maxFiles, maxSize, onReject, commit, start],
  );

  const remove = useCallback(
    (id: string) => {
      controllers.current.get(id)?.abort();
      controllers.current.delete(id);
      commit(list.current.filter((a) => a.id !== id));
    },
    [commit],
  );

  const retry = useCallback(
    (id: string) => {
      const a = list.current.find((x) => x.id === id);
      if (!a?.file || !latest.current.upload) return;
      if (maxSize !== undefined && a.file.size > maxSize) return;
      const next = { ...a, status: "uploading" as const, progress: undefined, error: undefined };
      commit(list.current.map((x) => (x.id === id ? next : x)));
      start(next);
    },
    [commit, start, maxSize],
  );

  /** Empties the list after a send. Previews are kept alive for `keepPreviews` (the sent message may still show them). */
  const clear = useCallback(
    ({ keepPreviews = true }: { keepPreviews?: boolean } = {}) => {
      for (const c of controllers.current.values()) c.abort();
      controllers.current.clear();
      if (keepPreviews) list.current = [];
      commit([]);
    },
    [commit],
  );

  useEffect(() => {
    const ctrl = controllers.current;
    return () => {
      for (const c of ctrl.values()) c.abort();
      for (const a of list.current) releaseAttachment(a);
    };
  }, []);

  const uploading = attachments.some((a) => a.status === "uploading");
  const failed = attachments.some((a) => a.status === "error");

  return {
    attachments,
    add,
    remove,
    retry,
    clear,
    update: patch,
    /** True while any file is still uploading: hold Send until it is false. */
    uploading,
    /** True when any file failed: Send skips those files. */
    failed,
    /** The finished attachments as AI SDK `file` parts. */
    fileParts: attachments.map(toFilePart).filter((p): p is ChatFilePart => p !== null),
  };
}

/**
 * P12 chat-core: the shared model and hooks behind Composer, Attachment Chip, Message,
 * Conversation and Chat Shell. Import from here.
 */
export * from "./types";
export * from "./group-messages";
export * from "./attachments";
export * from "./composer-keys";
