/* ---------- Bag button ------------------------------------------------------------------- */

export type BagButtonProps = Omit<ComponentProps<"button">, "children" | "type"> & {
  /** Items in the bag. The count rolls, and pops whenever it goes up. */
  count: number;
  locale?: Intl.LocalesArgument;
};

/**
 * The header's bag: a 32px icon button with a count bubble that rolls its digits and pops on
 * every add, so a quick add elsewhere on the page lands somewhere visible. Hidden at zero.
 */
export function BagButton({ count, locale = COMMERCE_LOCALE, className = "", ref, ...props }: BagButtonProps) {
  const reduced = useSafeReducedMotion();
  const [scope, animate] = useAnimate<HTMLSpanElement>();
  const prev = useRef(count);
  useEffect(() => {
    if (count > prev.current && prev.current > 0 && !reduced && scope.current) {
      animate(scope.current, { scale: [1, 1.22, 1] }, { duration: 0.4, ease: ease.enter });
    }
    prev.current = count;
  }, [count, reduced, animate, scope]);
  return (
    <button
      ref={ref}
      type="button"
      aria-label={`Bag, ${count} item${count === 1 ? "" : "s"}`}
      {...props}
      className={`relative inline-flex size-8 shrink-0 cursor-pointer items-center justify-center rounded-control-sm text-text-secondary hover-fine:bg-surface-hover hover-fine:text-text ${pressIcon} ${className}`}
    >
      <BagIcon className="size-[18px]" />
      <AnimatePresence initial={false}>
        {count > 0 && (
          <motion.span
            key="count"
            aria-hidden
            className="absolute -top-0.5 -right-0.5 flex"
            initial={reduced ? { opacity: 0 } : { opacity: 0, scale: 0.6 }}
            animate={{ opacity: 1, scale: 1, transition: reduced ? reducedFade : swap }}
            exit={{ opacity: 0, scale: reduced ? 1 : 0.8, transition: { duration: 0.1 } }}
          >
            <span ref={scope} className="flex h-4 min-w-4 items-center justify-center rounded-pill bg-text px-1 text-ui-2xs font-medium text-surface tabular-nums ring-2 ring-surface">
              <NumberRoll value={count} locale={locale} aria-hidden />
            </span>
          </motion.span>
        )}
      </AnimatePresence>
    </button>
  );
}

"use client";

import { AnimatePresence, motion } from "motion/react";
import { useCallback, useEffect, useRef, useState, type ComponentPropsWithoutRef } from "react";
import { TextSwap } from "../text-swap/text-swap";
import { exitFast, fade, reducedFade, snappy, swap, swapIn, swapOut, swapShown, useSafeReducedMotion } from "../../lib/motion";
import { pressIcon } from "../../lib/press";

/** How long the check stays before the copy icon returns, ms. */
export const COPIED_MS = 1600;

/** Write text to the clipboard, falling back to a hidden textarea where the async API is blocked. */
export async function writeClipboard(text: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    try {
      const el = document.createElement("textarea");
      el.value = text;
      el.setAttribute("readonly", "");
      el.style.cssText = "position:fixed;opacity:0;pointer-events:none";
      document.body.append(el);
      el.select();
      const ok = document.execCommand("copy");
      el.remove();
      return ok;
    } catch {
      return false;
    }
  }
}

/**
 * Copy state for any trigger: `copy()` writes the text and flips `copied` for `COPIED_MS`.
 * Copying again restarts the timer, so the check never flickers off between quick copies.
 */
export function useCopy(text: string | (() => string), { timeout = COPIED_MS, onCopy }: { timeout?: number; onCopy?: (text: string) => void } = {}) {
  const [copied, setCopied] = useState(false);
  const timer = useRef<number | undefined>(undefined);
  useEffect(() => () => window.clearTimeout(timer.current), []);
  const copy = useCallback(async () => {
    const value = typeof text === "function" ? text() : text;
    if (!(await writeClipboard(value))) return false;
    onCopy?.(value);
    setCopied(true);
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => setCopied(false), timeout);
    return true;
  }, [text, timeout, onCopy]);
  return { copied, copy };
}

/**
 * The copy → check morph. The two sheets lift and blur away while the check draws itself in
 * on the snappy spring; going back, the check leaves faster than it came (exit ≤ 0.75 ×
 * enter). Reduced motion: a plain cross-fade.
 */
export function CopyIcon({ copied, className = "" }: { copied: boolean; className?: string }) {
  const reduced = useSafeReducedMotion();
  // Both icons share one grid cell, so the swap never changes the layout (popLayout cannot lift an SVG out of flow).
  return (
    <span aria-hidden className={`grid size-4 shrink-0 place-items-center *:col-start-1 *:row-start-1 ${className}`}>
      <AnimatePresence initial={false}>
        {copied ? (
          <motion.svg
            key="check"
            viewBox="0 0 16 16"
            fill="none"
            className="size-4 overflow-visible"
            initial={reduced ? { opacity: 0 } : { opacity: 0, scale: 0.8, filter: "blur(2px)" }}
            animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }}
            exit={reduced ? { opacity: 0, transition: reducedFade } : { ...swapOut, transition: { ...swap, opacity: exitFast, filter: exitFast } }}
            transition={reduced ? reducedFade : { ...snappy, opacity: fade, filter: fade }}
          >
            <motion.path
              d="M3.25 8.5 6.5 11.75 12.75 4.75"
              stroke="currentColor"
              strokeWidth={1.5}
              strokeLinecap="round"
              strokeLinejoin="round"
              initial={reduced ? false : { pathLength: 0 }}
              animate={{ pathLength: 1 }}
              transition={{ ...snappy, delay: 0.04 }}
            />
          </motion.svg>
        ) : (
          <motion.svg
            key="copy"
            viewBox="0 0 16 16"
            fill="none"
            className="size-4"
            initial={reduced ? { opacity: 0 } : swapIn}
            animate={reduced ? { opacity: 1 } : swapShown}
            exit={reduced ? { opacity: 0, transition: reducedFade } : { opacity: 0, scale: 0.85, filter: "blur(2px)", transition: { ...snappy, opacity: exitFast, filter: exitFast } }}
            transition={reduced ? reducedFade : swap}
          >
            <rect x="5.25" y="5.25" width="8" height="8" rx="2" stroke="currentColor" strokeWidth="1.5" />
            <path d="M10.75 5.25V4.5a1.75 1.75 0 0 0-1.75-1.75H4.5A1.75 1.75 0 0 0 2.75 4.5V9a1.75 1.75 0 0 0 1.75 1.75h.75" stroke="currentColor" strokeWidth="1.5" />
          </motion.svg>
        )}
      </AnimatePresence>
    </span>
  );
}

export type CopyButtonProps = Omit<ComponentPropsWithoutRef<"button">, "onClick" | "children" | "onCopy"> & {
  /** The text to copy, or a function that returns it at click time. */
  text: string | (() => string);
  /** Accessible name. Default "Copy code". */
  label?: string;
  /**
   * Slide a "Copied" label out to the left of the check (the button grows leftward on a
   * spring and shrinks back). Default true; pass false where there is no room.
   */
  showLabel?: boolean;
  /** Extend the target to 44×44px. Default true; pass false inside a row of other targets. */
  hitArea?: boolean;
  /** Radius class. Default `rounded-control-sm`; pass `radius-nested` inside a padded control. */
  radius?: string;
  onCopy?: (text: string) => void;
};

/**
 * A 32px ghost copy button with the copy → check morph. Announces "Copied" politely to
 * screen readers. Its right edge stays put when the label slides out, so park it at the
 * end of a row.
 */
export function CopyButton({ text, label = "Copy code", showLabel = true, hitArea = true, radius = "rounded-control-sm", onCopy, className = "", ...props }: CopyButtonProps) {
  const { copied, copy } = useCopy(text, { onCopy });
  return (
    <>
      <button
        type="button"
        aria-label={label}
        {...props}
        onClick={() => void copy()}
        className={`relative inline-flex h-8 min-w-8 shrink-0 cursor-pointer items-center justify-center ${radius} px-2 text-ui-sm font-medium whitespace-nowrap select-none ${
          copied ? "text-text" : "text-text-muted hover-fine:text-text"
        } hover-fine:bg-surface-hover active:bg-surface-active ${pressIcon} ${hitArea ? "hit-area" : ""} ${className}`}
      >
        {showLabel && (
          <TextSwap swapKey={copied ? "copied" : "idle"} aria-hidden>
            {copied ? <span className="pr-1.5">Copied</span> : null}
          </TextSwap>
        )}
        <CopyIcon copied={copied} />
      </button>
      <span role="status" className="sr-only">
        {copied ? "Copied" : ""}
      </span>
    </>
  );
}

/**
 * crypto-core: the small pieces every Eased crypto block shares, so a wallet, a swap and an
 * order book read as one product: the token glyph, chain tints, address truncation and the
 * price and amount formats. Import from here.
 */
import type { CSSProperties } from "react";
import { minusFormatter } from "../../lib/format";

/* ---------- Token glyph ------------------------------------------------------------------ */

/**
 * Monochrome marks for the common symbols. No brand logos: a disc with a glyph reads as
 * "a token" at 20px, sits on any theme and never clashes with the page's accent.
 */
const GLYPHS: Record<string, string> = {
  BTC: "₿",
  ETH: "Ξ",
  SOL: "◎",
  USDC: "$",
  USDT: "₮",
  DAI: "◈",
  LINK: "⬢",
};

export type TokenGlyphProps = {
  symbol: string;
  /** Pixel size of the disc. Default 20; the glyph scales with it. */
  size?: number;
  className?: string;
};

/** A token's disc: sunken fill, the alpha image ring, and a glyph (or the symbol's first letter). */
export function TokenGlyph({ symbol, size = 20, className = "" }: TokenGlyphProps) {
  const glyph = GLYPHS[symbol.toUpperCase()] ?? symbol.slice(0, 1).toUpperCase();
  return (
    <span
      aria-hidden
      style={{ width: size, height: size, fontSize: Math.round(size * 0.55) } as CSSProperties}
      className={`relative inline-flex shrink-0 items-center justify-center rounded-full bg-surface-active font-medium leading-none text-text-secondary image-ring select-none ${className}`}
    >
      {glyph}
    </span>
  );
}

/* ---------- Chain tints ------------------------------------------------------------------ */

export type ChainTone = "info" | "brand" | "success" | "warning" | "neutral";

/** A chain's tint as a token, for washes and dots. Never decoration beyond one glow (rule 35/36). */
export const CHAIN_TONE_VAR: Record<ChainTone, string> = {
  info: "var(--color-info)",
  brand: "var(--color-brand)",
  success: "var(--color-success)",
  warning: "var(--color-warning)",
  neutral: "var(--color-text-muted)",
};

/** A ≤ 10%-alpha radial glow of a chain's tone, for the top of a card (rule 36). */
export const chainGlow = (tone: ChainTone, alpha = 10) =>
  `radial-gradient(120% 80% at 0% 0%, color-mix(in oklch, ${CHAIN_TONE_VAR[tone]} ${alpha}%, transparent), transparent 70%)`;

/* ---------- Formats ---------------------------------------------------------------------- */

/** Default locale for every crypto format: prices read `$67,321.50`, never `US$`. Pass your own. */
export const CRYPTO_LOCALE = "en-US";

/** `0x7a3F…Bf62`: the head and tail a person actually checks. */
export function truncateAddress(address: string, head = 6, tail = 4) {
  if (address.length <= head + tail + 1) return address;
  return `${address.slice(0, head)}…${address.slice(-tail)}`;
}

/** Fraction digits for a USD price: cents above $1, more below, so small tokens stay legible. */
export function priceDecimals(price: number) {
  const p = Math.abs(price);
  if (p >= 1000) return 2;
  if (p >= 1) return p >= 10 ? 2 : 3;
  if (p >= 0.01) return 4;
  return 6;
}

/** Intl options for a USD price with `priceDecimals`, ready for NumberRoll's `format`. */
export const usdFormat = (price: number, decimals = priceDecimals(price)): Intl.NumberFormatOptions => ({
  style: "currency",
  currency: "USD",
  minimumFractionDigits: decimals,
  maximumFractionDigits: decimals,
});

/** Significant decimals for a token amount: fewer for big holdings, more for fractions of a coin. */
export function amountDecimals(amount: number) {
  const a = Math.abs(amount);
  if (a === 0) return 2;
  if (a >= 1000) return 2;
  if (a >= 1) return 4;
  return 6;
}

/** `4.2817`, `12,480.55`, `0.002914` — token amounts at a sensible precision. */
export const formatAmount = (amount: number, { locale = CRYPTO_LOCALE, decimals = amountDecimals(amount) }: { locale?: Intl.LocalesArgument; decimals?: number } = {}) =>
  new Intl.NumberFormat(locale, { minimumFractionDigits: Math.min(2, decimals), maximumFractionDigits: decimals }).format(amount);

/** `$12,480.55` (or `$4.2K` compact). */
export const formatUsd = (value: number, { locale = CRYPTO_LOCALE, decimals, compact = false }: { locale?: Intl.LocalesArgument; decimals?: number; compact?: boolean } = {}) =>
  new Intl.NumberFormat(locale, {
    style: "currency",
    currency: "USD",
    notation: compact ? "compact" : "standard",
    minimumFractionDigits: decimals ?? (compact ? 0 : 2),
    maximumFractionDigits: decimals ?? (compact ? 1 : 2),
  }).format(value);

/** `+1.84%` / `−0.93%`, always signed, one decimal unless told otherwise. */
export const formatChange = (share: number, { locale = CRYPTO_LOCALE, decimals = 2 }: { locale?: Intl.LocalesArgument; decimals?: number } = {}) =>
  minusFormatter(locale, { style: "percent", minimumFractionDigits: decimals, maximumFractionDigits: decimals, signDisplay: "exceptZero" })(share);

/**
 * The market colour of a move: up reads success, down reads danger (trading convention), flat is
 * muted. Only for market moves (prices, rates, P&L). A fall in a metric the user owns, like
 * spend or a balance, reads warning instead (rule 119).
 */
export const moveTone = (delta: number) => (delta > 0 ? "text-success-text" : delta < 0 ? "text-danger-text" : "text-text-muted");

import { redline, type RedlineSegment } from "./redline";
import { blockById, type Doc } from "./types";

/**
 * A durable pointer at a span of one block's text, for comments and AI suggestions. It keeps
 * offsets for speed and a quote with context (like the W3C TextQuoteSelector) so it can be
 * found again after the text changes.
 */
export type TextAnchor = {
  id: string;
  blockId: string;
  start: number;
  end: number;
  /** The anchored text when created. */
  quote: string;
  /** Up to `context` characters either side, to disambiguate repeated phrases. */
  prefix: string;
  suffix: string;
};

export type Comment = TextAnchor & {
  kind: "comment";
  author: string;
  body: string;
  /** Epoch ms. */
  createdAt: number;
  resolved?: boolean;
  /** Replies, oldest first. */
  replies?: { id: string; author: string; body: string; createdAt: number }[];
};

export type Suggestion = TextAnchor & {
  kind: "suggestion";
  /** The text proposed in place of `quote` (empty to delete it). */
  replacement: string;
  /** Why: "Caps liability at 12 months' fees, per playbook §3." */
  rationale?: string;
  author?: string;
  /** 0–1, for AI suggestions. */
  confidence?: number;
  status: "pending" | "accepted" | "rejected";
};

/** An anchor over `block.text.slice(start, end)`. */
export function createAnchor(doc: Doc, blockId: string, start: number, end: number, { id, context = 24 }: { id: string; context?: number }): TextAnchor {
  const text = blockById(doc, blockId)?.text ?? "";
  const s = Math.max(0, Math.min(start, end, text.length));
  const e = Math.min(text.length, Math.max(start, end));
  return { id, blockId, start: s, end: e, quote: text.slice(s, e), prefix: text.slice(Math.max(0, s - context), s), suffix: text.slice(e, e + context) };
}

/** An anchor over the first occurrence of `quote` in a block (after `from`): handy for fixtures and AI output that cites text. */
export function anchorQuote(doc: Doc, blockId: string, quote: string, { id, from = 0, context }: { id: string; from?: number; context?: number }): TextAnchor | null {
  const text = blockById(doc, blockId)?.text ?? "";
  const i = text.indexOf(quote, from);
  return i < 0 ? null : createAnchor(doc, blockId, i, i + quote.length, { id, context });
}

export type ResolvedAnchor = { blockId: string; start: number; end: number; status: "exact" | "moved" | "orphaned" };

/**
 * Where an anchor points in `doc` now: `exact` when the offsets still hold the quote, `moved`
 * when the quote was found elsewhere (the occurrence whose context matches best, nearest the
 * old offset), `orphaned` when the quoted text is gone (show it as "on deleted text").
 */
export function resolveAnchor(doc: Doc, anchor: TextAnchor): ResolvedAnchor {
  const home = blockById(doc, anchor.blockId);
  if (home && home.text.slice(anchor.start, anchor.end) === anchor.quote) return { blockId: home.id, start: anchor.start, end: anchor.end, status: "exact" };
  if (!anchor.quote) return { blockId: anchor.blockId, start: 0, end: 0, status: "orphaned" };
  const candidates = home ? [home, ...doc.blocks.filter((b) => b !== home)] : doc.blocks;
  let best: { blockId: string; start: number; score: number } | null = null;
  for (const b of candidates) {
    for (let i = b.text.indexOf(anchor.quote); i >= 0; i = b.text.indexOf(anchor.quote, i + 1)) {
      const before = b.text.slice(Math.max(0, i - anchor.prefix.length), i);
      const after = b.text.slice(i + anchor.quote.length, i + anchor.quote.length + anchor.suffix.length);
      const score =
        sharedSuffix(before, anchor.prefix) + sharedPrefix(after, anchor.suffix) + (b.id === anchor.blockId ? 1000 - Math.min(999, Math.abs(i - anchor.start)) / 1000 : 0);
      if (!best || score > best.score) best = { blockId: b.id, start: i, score };
    }
  }
  return best ? { blockId: best.blockId, start: best.start, end: best.start + anchor.quote.length, status: "moved" } : { blockId: anchor.blockId, start: 0, end: 0, status: "orphaned" };
}

const sharedPrefix = (a: string, b: string) => {
  let n = 0;
  while (n < a.length && n < b.length && a[n] === b[n]) n++;
  return n;
};
const sharedSuffix = (a: string, b: string) => {
  let n = 0;
  while (n < a.length && n < b.length && a[a.length - 1 - n] === b[b.length - 1 - n]) n++;
  return n;
};

/**
 * Maps an offset in the redline's "before" text to the "after" text. Offsets inside deleted
 * text land at the deletion point; `bias` decides which side of an insertion at the offset.
 */
export function mapOffset(offset: number, segments: readonly RedlineSegment[], bias: "before" | "after" = "after"): number {
  let a = 0;
  let b = 0;
  for (const s of segments) {
    if (s.kind === "insert") {
      if (a < offset || (a === offset && bias === "after")) b += s.text.length;
      continue;
    }
    const len = s.text.length;
    if (offset < a + len) return s.kind === "equal" ? b + (offset - a) : b;
    a += len;
    if (s.kind === "equal") b += len;
  }
  return b;
}

/** An anchor moved through an edit of its block (offsets mapped, quote and context refreshed). */
export function rebaseAnchor<A extends TextAnchor>(anchor: A, before: string, after: string, segments = redline(before, after).segments): A {
  const start = mapOffset(anchor.start, segments, "after");
  const end = Math.max(start, mapOffset(anchor.end, segments, "before"));
  const context = Math.max(anchor.prefix.length, anchor.suffix.length, 24);
  return { ...anchor, start, end, quote: after.slice(start, end), prefix: after.slice(Math.max(0, start - context), start), suffix: after.slice(end, end + context) };
}

export type MarkedRun = { text: string; start: number; end: number; ids: string[] };

/**
 * A block's text cut into runs at every anchor edge, each run listing the anchors covering
 * it: render runs with `ids.length` as `<mark>` (overlaps nest naturally as multiple ids).
 */
export function splitByAnchors(text: string, anchors: readonly { id: string; start: number; end: number }[]): MarkedRun[] {
  const cuts = new Set([0, text.length]);
  for (const a of anchors) {
    cuts.add(Math.max(0, Math.min(text.length, a.start)));
    cuts.add(Math.max(0, Math.min(text.length, a.end)));
  }
  const points = [...cuts].sort((x, y) => x - y);
  const runs: MarkedRun[] = [];
  for (let i = 0; i < points.length - 1; i++) {
    const [s, e] = [points[i], points[i + 1]];
    if (e <= s) continue;
    runs.push({ text: text.slice(s, e), start: s, end: e, ids: anchors.filter((a) => a.start < e && a.end > s).map((a) => a.id) });
  }
  return runs;
}

/**
 * The anchored span of a DOM selection inside one rendered block. Blocks must render their
 * text verbatim inside an element with `data-doc-block={block.id}` (marks and ins are fine;
 * extra text such as clause numbers must sit outside it). Null for collapsed or cross-block
 * selections.
 */
export function anchorFromSelection(selection: Selection | null = typeof window === "undefined" ? null : window.getSelection()): { blockId: string; start: number; end: number; quote: string } | null {
  if (!selection || selection.rangeCount === 0 || selection.isCollapsed) return null;
  const range = selection.getRangeAt(0);
  const blockOf = (n: Node) => (n.nodeType === Node.ELEMENT_NODE ? (n as Element) : n.parentElement)?.closest<HTMLElement>("[data-doc-block]") ?? null;
  const block = blockOf(range.startContainer);
  if (!block || block !== blockOf(range.endContainer)) return null;
  const offsetOf = (node: Node, offset: number) => {
    const r = document.createRange();
    r.selectNodeContents(block);
    r.setEnd(node, offset);
    return r.toString().length;
  };
  const start = offsetOf(range.startContainer, range.startOffset);
  const end = offsetOf(range.endContainer, range.endOffset);
  return { blockId: block.dataset.docBlock!, start, end, quote: range.toString() };
}

/** The block text with a suggestion applied, and its redline: render it inline or in an Approval Card. */
export function suggestionPreview(doc: Doc, s: Suggestion) {
  const block = blockById(doc, s.blockId);
  const at = resolveAnchor(doc, s);
  const before = block?.text ?? "";
  const after = at.status === "orphaned" ? before : before.slice(0, at.start) + s.replacement + before.slice(at.end);
  return { before, after, anchor: at, redline: redline(before, after, { idPrefix: `${s.id}:` }) };
}

/**
 * Accepts a suggestion: a new document with the replacement in place, and every other anchor
 * (comments, other suggestions) on that block rebased through the edit so it still points at
 * its text.
 */
export function applySuggestion<A extends TextAnchor>(doc: Doc, s: Suggestion, others: readonly A[] = []): { doc: Doc; anchors: A[] } {
  const { before, after, anchor, redline: r } = suggestionPreview(doc, s);
  if (anchor.status === "orphaned") return { doc, anchors: [...others] };
  const next: Doc = { ...doc, blocks: doc.blocks.map((b) => (b.id === anchor.blockId ? { ...b, text: after } : b)) };
  const anchors = others.map((a) => (a.blockId === anchor.blockId && a.id !== s.id ? rebaseAnchor(a, before, after, r.segments) : a));
  return { doc: next, anchors };
}

import { diffChars, diffSentences, diffWords, diffWordsWithSpace, structuredPatch, type ChangeObject } from "diff";
import type { Doc, DocBlock } from "./types";

/** A run of text in an inline redline. Rendered as plain, `<ins>` or `<del>`. */
export type RedlineSegment = {
  kind: "equal" | "insert" | "delete";
  text: string;
  /** Inserts and deletes that form one edit share a change id (a replacement is a delete + an insert). */
  changeId?: string;
};

/** One reviewable edit: accept or reject it as a unit. */
export type RedlineChange = {
  id: string;
  kind: "insert" | "delete" | "replace";
  deleted: string;
  inserted: string;
};

export type Redline = {
  segments: RedlineSegment[];
  changes: RedlineChange[];
  /** Words added and removed, for "+12 −3". */
  stats: { inserted: number; deleted: number; changes: number };
};

export type RedlineOptions = {
  /** `word` (default) reads like a lawyer's redline; `char` for codes and figures; `sentence` for long rewrites. */
  granularity?: "word" | "char" | "sentence";
  /** Word boundaries follow this locale's `Intl.Segmenter` (so "1.5%" changes as "1.5", not ".5"). Default the runtime's. */
  locale?: string;
  /** Prefix for change ids, so two blocks' changes stay unique: `${prefix}${n}`. Default `c`. */
  idPrefix?: string;
};

const words = (s: string) => (s.match(/\S+/g) ?? []).length;

/**
 * An inline redline between two strings on the `diff` package: segments for rendering, and
 * the edits grouped into changes you can accept or reject. A delete next to an insert is one
 * replacement, and up to three characters of space or punctuation between two edits are folded
 * in, so "three (3) months" → "twelve (12) months" reads as one change, not two.
 *
 *   const { segments, changes, stats } = redline(clause.text, revised.text);
 */
export function redline(before: string, after: string, { granularity = "word", idPrefix = "c", locale }: RedlineOptions = {}): Redline {
  const raw: ChangeObject<string>[] =
    granularity === "char" ? diffChars(before, after) : granularity === "sentence" ? diffSentences(before, after) : diffByWords(before, after, locale);

  // Group into runs: equal text, or a change (deleted + inserted), folding short space/punctuation equals between two changes.
  type Run = { equal: string } | { deleted: string; inserted: string };
  const runs: Run[] = [];
  for (let i = 0; i < raw.length; i++) {
    const p = raw[i];
    const last = runs[runs.length - 1];
    if (!p.added && !p.removed) {
      const next = raw[i + 1];
      const bridges = last && "deleted" in last && next && (next.added || next.removed) && /^[\s\p{P}]{1,3}$/u.test(p.value);
      if (bridges) {
        last.deleted += p.value;
        last.inserted += p.value;
      } else runs.push({ equal: p.value });
      continue;
    }
    if (!last || "equal" in last) runs.push({ deleted: "", inserted: "" });
    const run = runs[runs.length - 1] as { deleted: string; inserted: string };
    if (p.removed) run.deleted += p.value;
    else run.inserted += p.value;
  }

  // A pure insert or delete takes the space before it with it, so rejecting "days of notice."
  // gives "days." and not "days ." (word diffs leave that space in the equal text).
  for (let i = 1; i < runs.length; i++) {
    const run = runs[i];
    const prev = runs[i - 1];
    const next = runs[i + 1];
    if ("equal" in run || "deleted" in prev || (run.deleted && run.inserted)) continue;
    const text = run.deleted || run.inserted;
    const ws = /\s+$/.exec(prev.equal)?.[0];
    if (!ws || /\s$/.test(text) || (next && "equal" in next && /^\s/.test(next.equal))) continue;
    prev.equal = prev.equal.slice(0, -ws.length);
    if (run.deleted) run.deleted = ws + run.deleted;
    else run.inserted = ws + run.inserted;
  }

  const segments: RedlineSegment[] = [];
  const changes: RedlineChange[] = [];
  let ins = 0;
  let del = 0;
  for (const run of runs) {
    if ("equal" in run) {
      segments.push({ kind: "equal", text: run.equal });
      continue;
    }
    // Trim the whitespace both sides share at the ends back out into plain text.
    let { deleted, inserted } = run;
    const lead = commonEdge(deleted, inserted, "start");
    const trail = commonEdge(deleted.slice(lead.length), inserted.slice(lead.length), "end");
    deleted = deleted.slice(lead.length, deleted.length - trail.length);
    inserted = inserted.slice(lead.length, inserted.length - trail.length);
    if (lead) segments.push({ kind: "equal", text: lead });
    const id = `${idPrefix}${changes.length + 1}`;
    if (deleted) segments.push({ kind: "delete", text: deleted, changeId: id });
    if (inserted) segments.push({ kind: "insert", text: inserted, changeId: id });
    if (deleted || inserted) changes.push({ id, kind: deleted && inserted ? "replace" : deleted ? "delete" : "insert", deleted, inserted });
    if (trail) segments.push({ kind: "equal", text: trail });
    ins += words(inserted);
    del += words(deleted);
  }
  return { segments: mergeEquals(segments), changes, stats: { inserted: ins, deleted: del, changes: changes.length } };
}

const segmenters = new Map<string, Intl.Segmenter>();
function diffByWords(before: string, after: string, locale?: string): ChangeObject<string>[] {
  if (typeof Intl === "undefined" || typeof Intl.Segmenter !== "function") return diffWordsWithSpace(before, after);
  const key = locale ?? "";
  let seg = segmenters.get(key);
  if (!seg) segmenters.set(key, (seg = new Intl.Segmenter(locale, { granularity: "word" })));
  return diffWords(before, after, { intlSegmenter: seg });
}

function commonEdge(a: string, b: string, edge: "start" | "end"): string {
  let n = 0;
  const max = Math.min(a.length, b.length);
  if (edge === "start") {
    while (n < max && a[n] === b[n] && /\s/.test(a[n])) n++;
    return a.slice(0, n);
  }
  while (n < max && a[a.length - 1 - n] === b[b.length - 1 - n] && /\s/.test(a[a.length - 1 - n])) n++;
  return n ? a.slice(a.length - n) : "";
}

function mergeEquals(segments: RedlineSegment[]) {
  const out: RedlineSegment[] = [];
  for (const s of segments) {
    const last = out[out.length - 1];
    if (last && last.kind === "equal" && s.kind === "equal") last.text += s.text;
    else if (s.text) out.push({ ...s });
  }
  return out;
}

export type Decision = "accept" | "reject";

/**
 * The text after deciding each change: accepted changes take their insert, rejected ones
 * keep the original. Undecided changes follow `pending` (default `reject`: the original stands).
 */
export function resolveRedline(segments: readonly RedlineSegment[], decisions: Record<string, Decision | undefined>, { pending = "reject" }: { pending?: Decision } = {}): string {
  let out = "";
  for (const s of segments) {
    if (s.kind === "equal") out += s.text;
    else {
      const d = (s.changeId && decisions[s.changeId]) || pending;
      if ((s.kind === "insert" && d === "accept") || (s.kind === "delete" && d === "reject")) out += s.text;
    }
  }
  return out;
}

export type BlockDiff = {
  id: string;
  status: "same" | "changed" | "added" | "removed";
  before?: DocBlock;
  after?: DocBlock;
  /** For changed blocks (and added/removed ones, as one insert/delete). */
  redline: Redline;
};

/**
 * Two versions of a document compared block by block (matched by id): the order of `after`,
 * with removed blocks kept where they were. Change ids are prefixed by block id, so they are
 * unique across the document.
 */
export function diffDocs(before: Doc, after: Doc, options: Omit<RedlineOptions, "idPrefix"> = {}) {
  const old = new Map(before.blocks.map((b, i) => [b.id, { b, i }]));
  const kept = new Set(after.blocks.map((b) => b.id));
  const out: BlockDiff[] = [];
  const emitRemovedBefore = (limit: number, from: { i: number }) => {
    for (; from.i < limit; from.i++) {
      const b = before.blocks[from.i];
      if (!kept.has(b.id)) out.push({ id: b.id, status: "removed", before: b, redline: redline(b.text, "", { ...options, idPrefix: `${b.id}:` }) });
    }
  };
  const cursor = { i: 0 };
  for (const b of after.blocks) {
    const prev = old.get(b.id);
    if (prev) emitRemovedBefore(prev.i, cursor);
    if (prev && cursor.i <= prev.i) cursor.i = prev.i + 1;
    const r = redline(prev?.b.text ?? "", b.text, { ...options, idPrefix: `${b.id}:` });
    out.push({ id: b.id, status: !prev ? "added" : r.changes.length || prev.b.title !== b.title ? "changed" : "same", before: prev?.b, after: b, redline: r });
  }
  emitRemovedBefore(before.blocks.length, cursor);
  const stats = out.reduce((s, d) => ({ inserted: s.inserted + d.redline.stats.inserted, deleted: s.deleted + d.redline.stats.deleted, changes: s.changes + d.redline.stats.changes }), {
    inserted: 0,
    deleted: 0,
    changes: 0,
  });
  return { blocks: out, stats, changed: out.filter((d) => d.status !== "same").length };
}

/**
 * Line hunks between two texts, shaped exactly like code-core's `DiffHunk` (`oldStart`,
 * `oldLines`, `newStart`, `newLines`, `lines: { kind, text }[]`), so a Diff Block can render a
 * document version diff without doc-core depending on code-core.
 */
export function lineHunks(before: string, after: string, { context = 3 }: { context?: number } = {}) {
  const patch = structuredPatch("before", "after", before, after, undefined, undefined, { context });
  return patch.hunks.map((h) => ({
    oldStart: h.oldStart,
    oldLines: h.oldLines,
    newStart: h.newStart,
    newLines: h.newLines,
    lines: h.lines
      .filter((l) => !l.startsWith("\\"))
      .map((l) => ({ kind: l[0] === "+" ? ("add" as const) : l[0] === "-" ? ("remove" as const) : ("context" as const), text: l.slice(1) })),
  }));
}

export type DocBlockKind = "heading" | "paragraph" | "clause";
export type Risk = "low" | "medium" | "high";

/** One block of a document. Offsets in anchors and redlines are into `text`. */
export type DocBlock = {
  /** Stable across versions: `diffDocs` matches blocks by it. */
  id: string;
  kind: DocBlockKind;
  text: string;
  /** Clause number, "4.2" (see `numberClauses`). */
  number?: string;
  /** A clause's caption, "Limitation of liability". */
  title?: string;
  /** Heading level (1–3) or clause depth (1 = "4", 2 = "4.2", 3 = "4.2.1"). Default 1. */
  level?: number;
  risk?: Risk;
};

export type Doc = { id: string; title: string; version?: string; blocks: DocBlock[] };

/** Assigns "1", "1.1", "1.1.1" … to clauses by `level`, restarting sub-numbers under each parent. Headings and paragraphs are skipped. Immutable. */
export function numberClauses(blocks: readonly DocBlock[]): DocBlock[] {
  const counters: number[] = [];
  return blocks.map((b) => {
    if (b.kind !== "clause") return b;
    const level = Math.max(1, b.level ?? 1);
    counters.length = level;
    for (let i = 0; i < level; i++) counters[i] ??= 0;
    counters[level - 1]++;
    return { ...b, number: counters.slice(0, level).join(".") };
  });
}

/**
 * A document from plain text: `# Title` and `## Heading` lines, numbered clauses ("4.", "4.2",
 * "4.2.1" with an optional "Title." caption), and blank-line paragraphs. Ids are `b1`, `b2` …
 * in order, so parse two versions with matching structure and they diff block by block.
 */
export function docFromText(text: string, { id = "doc" }: { id?: string } = {}): Doc {
  let title = "";
  const blocks: DocBlock[] = [];
  let n = 0;
  for (const chunk of text.replace(/\r\n?/g, "\n").split(/\n\s*\n/)) {
    const raw = chunk.trim();
    if (!raw) continue;
    const heading = /^(#{1,3})\s+([\s\S]*)$/.exec(raw);
    if (heading) {
      if (heading[1].length === 1 && !title) {
        title = heading[2].trim();
        continue;
      }
      blocks.push({ id: `b${++n}`, kind: "heading", level: heading[1].length - 1 || 1, text: heading[2].trim() });
      continue;
    }
    const clause = /^(\d+(?:\.\d+)*)\.?\s+(?:([A-Z][A-Za-z'’\- ]{1,48})\.\s+)?([\s\S]*)$/.exec(raw);
    if (clause) {
      // A caption is short ("Limitation of liability."); a longer first sentence is body text.
      const caption = clause[2] && clause[2].trim().split(/\s+/).length <= 6 ? clause[2].trim() : undefined;
      const body = caption ? clause[3] : raw.slice(clause[1].length).replace(/^\.?\s+/, "");
      blocks.push({ id: `b${++n}`, kind: "clause", number: clause[1], level: clause[1].split(".").length, title: caption, text: body.replace(/\s*\n\s*/g, " ").trim() });
      continue;
    }
    blocks.push({ id: `b${++n}`, kind: "paragraph", text: raw.replace(/\s*\n\s*/g, " ") });
  }
  return { id, title, blocks };
}

export const blockById = (doc: Doc, id: string) => doc.blocks.find((b) => b.id === id);

"use client";

import { Field as BaseField } from "@base-ui/react/field";
import { AnimatePresence, animate, motion, useIsPresent } from "motion/react";
import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type ComponentPropsWithoutRef,
  type PointerEvent,
  type ReactNode,
} from "react";
import { enter, exitFast, reducedFade, smooth, swap, swapIn, swapOut, swapShown, useSafeReducedMotion } from "../../lib/motion";
import { AutoHeight } from "../auto-height/auto-height";

/* ---------- Sizes ------------------------------------------------------------- */

export type ControlSize = "sm" | "md" | "lg";

/**
 * Height, radius, gap and type for a text control's shell, by size. Each sets
 * `--radius-outer`/`--pad` so anything nested (a clear button, a chip) can use `radius-nested`.
 */
export const controlSizeClass: Record<ControlSize, string> = {
  sm: "min-h-control-sm rounded-control-sm gap-1.5 text-ui-sm [--pad:6px] [--radius-outer:var(--eased-radius-control-sm)]",
  md: "min-h-control-md rounded-control gap-2 text-ui [--pad:8px] [--radius-outer:var(--eased-radius-control)]",
  lg: "min-h-control-lg rounded-control gap-2 text-ui [--pad:8px] [--radius-outer:var(--eased-radius-control)]",
};

/** Horizontal padding of a one-line shell, by size (0.3–0.35 × height: text fields sit tighter than buttons). */
export const controlPadClass: Record<ControlSize, string> = { sm: "px-2.5", md: "px-3", lg: "px-3.5" };

/**
 * Classes for the bare `<input>`/`<textarea>` inside an `InputGroup`: no box of its own (the
 * group draws border and focus), 16px on touch screens so iOS does not zoom on focus.
 */
export const controlClass =
  "min-w-0 flex-1 self-stretch bg-transparent text-text outline-none placeholder:text-text-muted disabled:cursor-not-allowed disabled:text-text-disabled disabled:placeholder:text-text-disabled pointer-coarse:text-ui-md";

/* ---------- Root, label, description ---------------------------------------- */

export type FieldRootProps = Omit<ComponentProps<typeof BaseField.Root>, "className"> & { className?: string };

/**
 * Base UI's Field.Root: wires label, control, description and error together (ids,
 * `aria-describedby`, validation, `data-invalid` …). Stacks its parts with a 6px rhythm.
 */
export function FieldRoot({ className = "", ...props }: FieldRootProps) {
  return (
    <BaseField.Root
      {...props}
      className={`group/field flex min-w-0 flex-col gap-1.5 ${className}`}
    />
  );
}

export type FieldLabelProps = Omit<ComponentProps<typeof BaseField.Label>, "className"> & { className?: string };

export function FieldLabel({ className = "", ...props }: FieldLabelProps) {
  return (
    <BaseField.Label
      {...props}
      className={`w-fit cursor-default text-ui font-medium text-text group-data-disabled/field:text-text-disabled ${className}`}
    />
  );
}

/* ---------- The message slot: description ⇄ error ----------------------------- */

export type FieldMessageProps = {
  /** Helper text shown while the field is valid. An error takes its place, then gives it back. */
  description?: ReactNode;
  /**
   * The error to show while the field is invalid. Leave it out to show Base UI's message: your
   * `validate()` result, a `<Form errors>` entry, or the browser's validation message.
   */
  error?: ReactNode;
  className?: string;
};

/**
 * One line under the control that holds either the description or the error. They swap in
 * place with y + blur (the outgoing line lifts, the incoming rises), and the slot's height
 * springs when the line count changes or the slot opens from nothing. Must sit inside a
 * `FieldRoot`.
 */
export function FieldMessage(props: FieldMessageProps) {
  return <BaseField.Validity>{(v) => <MessageSlot {...props} validity={v} />}</BaseField.Validity>;
}

function MessageSlot({
  description,
  error,
  className = "",
  validity,
}: FieldMessageProps & { validity: BaseField.Validity.State }) {
  const reduced = useSafeReducedMotion();
  const invalid = validity.validity.valid === false;
  // Key the error by its text, so a new message swaps instead of sitting still.
  const errorKey = typeof error === "string" ? error : validity.errors.join("\n") || validity.error || "invalid";
  // An error with no description to replace opens the slot: let the control's shake land first.
  const delay = invalid && !description && !reduced ? 0.08 : 0;

  return (
    // The slot owns the 6px gap above it (pt-1.5 against -mt-1.5), so an empty slot adds no space.
    <AutoHeight fade={false} transition={{ ...smooth, delay }} className={`-mt-1.5 ${className}`} aria-live="polite">
      <div className="relative">
        <AnimatePresence mode="popLayout" initial={false}>
          {invalid ? (
            <MessageLine key={`error:${errorKey}`} reduced={reduced} delay={delay} tone="error">
              <ErrorIcon />
              <ErrorText error={error} />
            </MessageLine>
          ) : description ? (
            <MessageLine key="description" reduced={reduced} delay={0} tone="description">
              <BaseField.Description className="min-w-0 text-pretty">{description}</BaseField.Description>
            </MessageLine>
          ) : null}
        </AnimatePresence>
      </div>
    </AutoHeight>
  );
}

// `ref` is forwarded: AnimatePresence's popLayout needs it to lift the outgoing line out of flow.
function MessageLine({
  children,
  reduced,
  delay,
  tone,
  ref,
}: {
  children: ReactNode;
  reduced: boolean;
  delay: number;
  tone: "error" | "description";
  ref?: React.Ref<HTMLDivElement>;
}) {
  const present = useIsPresent();
  return (
    <motion.div
      ref={ref}
      aria-hidden={present ? undefined : true}
      initial={reduced ? { opacity: 0 } : swapIn}
      animate={reduced ? { opacity: 1 } : swapShown}
      exit={
        reduced
          ? { opacity: 0, transition: reducedFade }
          : { ...swapOut, transition: { ...swap, opacity: exitFast, filter: exitFast } }
      }
      transition={reduced ? reducedFade : { ...swap, opacity: { ...enter, delay }, filter: { ...enter, delay }, delay }}
      className={`flex w-full items-start gap-1.5 pt-1.5 text-ui-sm ${
        tone === "error" ? "text-danger-text" : "text-text-secondary"
      }`}
    >
      {children}
    </motion.div>
  );
}

/**
 * Base UI's Field.Error, which reads the live message. A line that is leaving keeps the
 * message it arrived with, so the outgoing copy never flashes the incoming text.
 */
function ErrorText({ error }: { error?: ReactNode }) {
  const present = useIsPresent();
  const frozen = useRef<ReactNode>(null);
  return (
    <BaseField.Error
      match
      className="min-w-0 text-pretty"
      // No `children` key unless we have one: an explicit undefined would blank Base UI's message.
      {...(error !== undefined ? { children: error } : null)}
      render={(props) => {
        if (present) frozen.current = props.children;
        return <div {...props}>{present ? props.children : frozen.current}</div>;
      }}
    />
  );
}

function ErrorIcon() {
  // 16px to match 13px text (rule 54), centred on the first line (rule 58).
  return (
    <svg viewBox="0 0 16 16" fill="none" aria-hidden className="mt-px size-4 shrink-0 translate-y-[0.5px]">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path d="M8 4.75v3.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
      <circle cx="8" cy="10.9" r="0.85" fill="currentColor" />
    </svg>
  );
}

/* ---------- Input group: the box a text control lives in -------------------- */

export type InputGroupProps = ComponentPropsWithoutRef<"div"> & {
  size?: ControlSize;
  /**
   * Draw the invalid state and shake once when it turns on. Inside a `FieldRoot` this follows
   * the field's validity on its own; pass it to drive a standalone control.
   */
  invalid?: boolean;
  /** Stack content vertically (a textarea and its footer) instead of in one row. */
  multiline?: boolean;
};

/**
 * The bordered shell for a text control and its addons (icons, prefixes, a clear button, a
 * shortcut hint). Hover steps the border up once; focus steps it up and grows a soft 3px glow
 * (`--eased-ring-soft`), the only ring the field draws; an invalid field keeps its danger border
 * and glows in danger while focused; a field turning invalid shakes the shell once, 6px, then
 * the message opens. A press anywhere
 * on the shell that is not itself interactive focuses the control, so addons never steal it.
 */
export function InputGroup({
  size = "md",
  invalid: invalidProp,
  multiline = false,
  className = "",
  onPointerDown,
  children,
  ...props
}: InputGroupProps) {
  const reduced = useSafeReducedMotion();
  const ref = useRef<HTMLDivElement>(null);
  const controlInvalid = useControlInvalid(ref);
  const invalid = invalidProp ?? controlInvalid;
  useShakeOnInvalid(ref, invalid, reduced);

  const focusControl = (e: PointerEvent<HTMLDivElement>) => {
    onPointerDown?.(e);
    if (e.defaultPrevented || e.button !== 0) return;
    const target = e.target as HTMLElement;
    if (target.closest("input, textarea, select, button, a, [role=button], [contenteditable=true]")) return;
    const control = ref.current?.querySelector<HTMLElement>("input, textarea");
    if (!control || control.matches(":disabled")) return;
    e.preventDefault();
    control.focus();
  };

  return (
    <div
      ref={ref}
      {...props}
      data-invalid={invalid || undefined}
      onPointerDown={focusControl}
      className={`relative flex w-full min-w-0 cursor-text border border-line-strong bg-surface text-text transition-[border-color,background-color,box-shadow] duration-(--eased-duration-standard) ease-standard reduced:transition-none ${
        multiline ? "flex-col items-stretch" : `items-center ${controlPadClass[size]}`
      } ${controlSizeClass[size]} hover-fine:not-data-invalid:border-(--eased-neutral-9) focus-within:not-data-invalid:border-(--eased-neutral-9) focus-within:shadow-[0_0_0_3px_var(--eased-ring-soft)] data-invalid:border-danger focus-within:data-invalid:shadow-[0_0_0_3px_var(--eased-ring-danger)] has-[:is(input,textarea,[aria-haspopup]):disabled]:cursor-not-allowed has-[:is(input,textarea,[aria-haspopup]):disabled]:border-line has-[:is(input,textarea,[aria-haspopup]):disabled]:bg-surface-sunken has-[:is(input,textarea,[aria-haspopup]):disabled]:text-text-disabled ${className}`}
    >
      {children}
    </div>
  );
}

/**
 * Whether the control inside reads as invalid. Base UI marks a field's control with
 * `data-invalid` and `aria-invalid`, so this works inside a Field and for a standalone control
 * given `aria-invalid`, with no context required.
 */
function useControlInvalid(ref: React.RefObject<HTMLElement | null>) {
  const [invalid, setInvalid] = useState(false);
  useLayoutEffect(() => {
    const control = ref.current?.querySelector("input, textarea");
    if (!control) return;
    const read = () =>
      setInvalid(control.hasAttribute("data-invalid") || control.getAttribute("aria-invalid") === "true");
    read();
    const mo = new MutationObserver(read);
    mo.observe(control, { attributes: true, attributeFilter: ["data-invalid", "aria-invalid"] });
    return () => mo.disconnect();
  }, [ref]);
  return invalid;
}

/** One horizontal shake, 6px, when `invalid` turns on. Reduced motion: none (the colour carries it). */
export function useShakeOnInvalid(ref: React.RefObject<HTMLElement | null>, invalid: boolean, reduced: boolean) {
  const was = useRef(invalid);
  useEffect(() => {
    const turnedOn = invalid && !was.current;
    was.current = invalid;
    if (!turnedOn || reduced || !ref.current) return;
    const shake = animate(ref.current, { x: [0, -6, 5, -3, 1.5, 0] }, { duration: 0.36, ease: "easeOut" });
    return () => shake.stop();
  }, [invalid, reduced, ref]);
}

export type InputGroupAddonProps = ComponentPropsWithoutRef<"span">;

/** A leading or trailing slot: icons at 16px in the muted colour, text prefixes, kbd hints. */
export function InputGroupAddon({ className = "", ...props }: InputGroupAddonProps) {
  return (
    <span
      {...props}
      className={`inline-flex shrink-0 items-center gap-1.5 text-text-muted select-none [&_svg]:size-4 [&_svg]:shrink-0 ${className}`}
    />
  );
}

