export type DragAxis = "x" | "y";

export type DragInfo = {
  /** The displayed position, after rubber-banding. */
  value: number;
  /** Pointer travel along the axis since the drag started. */
  offset: number;
  /** Pointer velocity along the axis, px/s. */
  velocity: number;
  /** Where a release right now would carry the element: `value` plus the velocity projection. */
  projected: number;
};

export type DragReleaseInfo = DragInfo & {
  /** The snap point the release picked, or -1 without snap points. */
  index: number;
  /** The position the release will settle at. */
  target: number;
};

export type UseDragOptions = {
  /** The axis the element moves on. Default "y". The other axis is left to the page. */
  axis?: DragAxis;
  /** Drive your own MotionValue instead of the one the hook creates. */
  value?: MotionValue<number>;
  /** Positions (px) a release settles on, chosen by velocity projection. */
  snapPoints?: readonly number[];
  /** Uncontrolled starting snap point. Default 0. */
  defaultIndex?: number;
  /** Controlled snap point. Changing it animates there. */
  index?: number;
  /** Called when a release, a key or `snapTo` picks a new snap point. */
  onIndexChange?: (index: number) => void;
  /** Hard ends. Default: the lowest and highest snap point, or unbounded without snap points. */
  min?: number;
  max?: number;
  /** Resist past `min`/`max` with Apple's rubber-band (true, default), a custom constant, or clamp (false). */
  rubberBand?: boolean | number;
  /** The distance the rubber-band flattens toward. Default: the element's size on the axis. */
  dimension?: number;
  /** Friction for velocity projection. Default `DECELERATION.normal` (0.998); pagers want `fast`. */
  decelerationRate?: number;
  /** Without snap points, keep gliding after release (Motion inertia) instead of stopping. Default false. */
  momentum?: boolean;
  /** Pointer travel (px) before a press becomes a drag, so taps and clicks still work. Default 4. */
  threshold?: number;
  /**
   * Hand scrolling over to the drag, as an iOS sheet does: inside a scroller on the same axis,
   * the content scrolls until it reaches its start, then the same pull drags the element.
   * Give the scroller `overscroll-behavior: contain`. Default true.
   */
  scrollHandoff?: boolean;
  /** CSS touch-action the hook sets on the element. Default "pan-x" for y, "pan-y" for x; false leaves it alone. */
  touchAction?: string | false;
  disabled?: boolean;
  /** How a release settles. Default the smooth spring, carrying the release velocity. */
  transition?: Transition;
  onDragStart?: (info: DragInfo) => void;
  onDrag?: (info: DragInfo) => void;
  /**
   * Called on release before the element settles. Return a snap index to go there instead,
   * or `false` to skip settling and animate the value yourself.
   */
  onRelease?: (info: DragReleaseInfo) => number | false | void;
  onDragEnd?: (info: DragReleaseInfo) => void;
};

export type UseDrag = {
  /** Attach to the draggable element. */
  ref: (el: HTMLElement | null) => () => void;
  /** The position. Bind it to `style.x` or `style.y`. */
  value: MotionValue<number>;
  /** True while a pointer drags the element. */
  dragging: boolean;
  /** The current snap point, or -1 without snap points. */
  index: number;
  /** Animate to a snap point. `immediate` jumps (layout changes, reduced motion). */
  snapTo: (index: number, immediate?: boolean) => void;
  /**
   * Put on the element's keyboard handle (a button or slider): arrows step between snap points
   * in screen order, Home and End jump to the ends.
   */
  onKeyDown: (e: ReactKeyboardEvent) => void;
};

type Session = {
  id: number;
  type: string;
  startX: number;
  startY: number;
  phase: "pending" | "dragging" | "ignored";
  scroller: HTMLElement | null;
  /** The release animation this press interrupted, if any. */
  interrupted: boolean;
  dragStart: number;
  origin: number;
  dimension: number;
  last: DragInfo;
};

const scrollPos = (el: HTMLElement, axis: DragAxis) => (axis === "y" ? el.scrollTop : Math.abs(el.scrollLeft));

/** The nearest element between `from` and `root` that scrolls on `axis`. */
function findScroller(from: EventTarget | null, root: HTMLElement, axis: DragAxis) {
  let el = from instanceof Element ? from : null;
  while (el && el !== root) {
    if (el instanceof HTMLElement) {
      const overflow = getComputedStyle(el)[axis === "y" ? "overflowY" : "overflowX"];
      const scrolls = axis === "y" ? el.scrollHeight > el.clientHeight + 1 : el.scrollWidth > el.clientWidth + 1;
      if (scrolls && /auto|scroll|overlay/.test(overflow)) return el;
    }
    el = el.parentElement;
  }
  return null;
}

/**
 * Eased's drag gesture: one axis, Apple's rubber-band past the ends, velocity projection onto
 * snap points, scroll handoff, and a release that carries the finger's velocity into a spring.
 * Built on Motion values and Motion's spring and inertia animations, so a drag can catch an
 * element mid-flight and any Motion style can read it.
 *
 *   const drag = useDrag({ snapPoints: [0, 240, 400] });
 *   <motion.div ref={drag.ref} style={{ y: drag.value }} />
 */
export function useDrag(options: UseDragOptions = {}): UseDrag {
  const {
    axis = "y",
    snapPoints,
    defaultIndex = 0,
    index: controlledIndex,
    touchAction,
  } = options;
  const reduced = useSafeReducedMotion();
  const own = useMotionValue(snapPoints?.[controlledIndex ?? defaultIndex] ?? 0);
  const value = options.value ?? own;

  const [dragging, setDragging] = useState(false);
  const [index, setIndex] = useState(snapPoints ? (controlledIndex ?? defaultIndex) : -1);

  // Listeners are bound once per element; they read the latest options from here.
  const opts = useRef(options);
  const motion = useRef({ reduced, value });
  // Layout effect, so a press straight after a render already sees the new options.
  useLayoutEffect(() => {
    opts.current = options;
    motion.current = { reduced, value };
  });

  const current = useRef(index);
  const anim = useRef<AnimationPlaybackControls | null>(null);
  const session = useRef<Session | null>(null);

  const bounds = useCallback(() => {
    const o = opts.current;
    const pts = o.snapPoints ?? [];
    const min = o.min ?? (pts.length ? Math.min(...pts) : -Infinity);
    const max = o.max ?? (pts.length ? Math.max(...pts) : Infinity);
    return { min, max };
  }, []);

  const settle = useCallback((target: number, velocity = 0, immediate = false) => {
    const { reduced, value } = motion.current;
    anim.current?.stop();
    if (immediate) {
      value.jump(target);
      return;
    }
    anim.current = animate(value, target, { ...(reduced ? instant : (opts.current.transition ?? smooth)), velocity });
  }, []);

  // Set below, once snapTo exists: re-syncs to a controlled index the parent did not accept.
  const resync = useRef<() => void>(() => {});

  const choose = useCallback((next: number) => {
    if (next === current.current) return;
    current.current = next;
    setIndex(next);
    opts.current.onIndexChange?.(next);
    // Controlled: if the parent keeps its old index, go back to it.
    if (opts.current.index !== undefined) requestAnimationFrame(() => resync.current());
  }, []);

  const snapTo = useCallback(
    (next: number, immediate = false) => {
      const pts = opts.current.snapPoints;
      if (!pts?.length) return;
      const i = clamp(Math.round(next), 0, pts.length - 1);
      choose(i);
      settle(pts[i], 0, immediate || motion.current.reduced);
    },
    [choose, settle],
  );

  // A controlled index that moves on its own animates there (never under a finger).
  useEffect(() => {
    resync.current = () => {
      const want = opts.current.index;
      if (want === undefined || want === current.current || session.current?.phase === "dragging") return;
      snapTo(want);
    };
  }, [snapTo]);
  useEffect(() => {
    resync.current();
  }, [controlledIndex]);

  // Snap points that move (a resize, a measured container) carry the element with them.
  const pointsKey = snapPoints?.join(",") ?? "";
  useEffect(() => {
    const pts = opts.current.snapPoints;
    if (!pts?.length || session.current?.phase === "dragging") return;
    const i = clamp(current.current, 0, pts.length - 1);
    if (current.current < 0) choose(i);
    if (anim.current?.state !== "running") motion.current.value.jump(pts[i]);
    else settle(pts[i]);
  }, [pointsKey, choose, settle]);

  const ref = useCallback(
    (el: HTMLElement | null) => {
      if (!el) return () => {};
      const ax = opts.current.axis ?? "y";
      const action = opts.current.touchAction ?? (ax === "y" ? "pan-x" : "pan-y");
      if (action !== false) el.style.touchAction = action;

      const tracker = createVelocityTracker();
      let restoreSelect = "";

      const infoFor = (s: Session, pointer: number): DragInfo => {
        const o = opts.current;
        const { min, max } = bounds();
        const raw = s.origin + (pointer - s.dragStart);
        const band = o.rubberBand ?? true;
        const shown =
          band === false ? clamp(raw, min, max) : rubberbandClamp(raw, min, max, s.dimension, band === true ? RUBBER_BAND : band);
        const velocity = tracker.velocity();
        return { value: shown, offset: pointer - s.dragStart, velocity, projected: shown + project(velocity, o.decelerationRate ?? DECELERATION.normal) };
      };

      // The scroller keeps the gesture while it has content to scroll back to, or while the
      // element is already at its far end; otherwise the pull drags the element.
      const scrollerWins = (scroller: HTMLElement, dir: number) => {
        if (scrollPos(scroller, ax) > 1) return true;
        if (dir > 0) return false;
        return motion.current.value.get() <= bounds().min + 0.5;
      };

      const begin = (s: Session, pointer: number) => {
        const o = opts.current;
        const { min, max } = bounds();
        const band = o.rubberBand ?? true;
        s.phase = "dragging";
        s.dragStart = pointer;
        s.dimension = o.dimension ?? (ax === "y" ? el.offsetHeight : el.offsetWidth);
        s.origin =
          band === false ? motion.current.value.get() : rubberbandUnclamp(motion.current.value.get(), min, max, s.dimension, band === true ? RUBBER_BAND : band);
        anim.current?.stop();
        tracker.reset();
        tracker.add(pointer);
        restoreSelect = document.documentElement.style.userSelect;
        document.documentElement.style.userSelect = "none";
        window.getSelection()?.removeAllRanges();
        el.style.willChange = "transform";
        setDragging(true);
        s.last = infoFor(s, pointer);
        o.onDragStart?.(s.last);
      };

      const finish = (s: Session, cancelled: boolean) => {
        const o = opts.current;
        const pts = o.snapPoints ?? [];
        const { min, max } = bounds();
        document.documentElement.style.userSelect = restoreSelect;
        el.style.willChange = "";
        setDragging(false);

        // A drag is never also a click on whatever it started on.
        const swallow = (e: MouseEvent) => {
          e.stopPropagation();
          e.preventDefault();
        };
        window.addEventListener("click", swallow, { capture: true, once: true });
        window.setTimeout(() => window.removeEventListener("click", swallow, { capture: true }), 0);

        const info = s.last;
        const velocity = cancelled ? 0 : info.velocity;
        const projected = info.value + project(velocity, o.decelerationRate ?? DECELERATION.normal);
        let target = clamp(info.value, min, max);
        let i = -1;
        if (pts.length) {
          i = nearest(projected, pts);
          target = pts[i];
        }
        const release: DragReleaseInfo = { ...info, velocity, projected, index: i, target };
        const override = o.onRelease?.(release);
        if (override === false) {
          o.onDragEnd?.(release);
          return;
        }
        if (typeof override === "number" && pts.length) {
          release.index = clamp(override, 0, pts.length - 1);
          release.target = pts[release.index];
        }
        if (release.index >= 0) choose(release.index);

        // Out of bounds, the spring pulls back without the outward velocity.
        const inside = info.value >= min && info.value <= max;
        if (!pts.length && o.momentum && inside && !motion.current.reduced) {
          anim.current?.stop();
          const rate = o.decelerationRate ?? DECELERATION.normal;
          // Not `info.value`: Motion skips an animation whose keyframes are all equal.
          anim.current = animate(motion.current.value, projected, {
            type: "inertia",
            velocity,
            power: rate / (1 - rate) / 1000,
            timeConstant: 325,
            min: Number.isFinite(min) ? min : undefined,
            max: Number.isFinite(max) ? max : undefined,
            bounceStiffness: 520,
            bounceDamping: 38,
          });
        } else settle(release.target, inside ? velocity : 0);
        o.onDragEnd?.(release);
      };

      const onMove = (e: PointerEvent) => {
        const s = session.current;
        if (!s || e.pointerId !== s.id || s.phase === "ignored") return;
        const dx = e.clientX - s.startX;
        const dy = e.clientY - s.startY;
        const main = ax === "y" ? dy : dx;
        const cross = ax === "y" ? dx : dy;
        const pointer = ax === "y" ? e.clientY : e.clientX;

        if (s.phase === "pending") {
          const threshold = opts.current.threshold ?? 4;
          // A touch inside a scroller is decided on its first move, before the browser commits
          // to scrolling; everything else waits for the threshold so taps stay taps.
          const decideNow = s.scroller && s.type === "touch" && (main !== 0 || cross !== 0);
          if (!decideNow && Math.abs(main) < threshold) {
            if (Math.abs(cross) >= threshold) s.phase = "ignored";
            return;
          }
          if (Math.abs(cross) > Math.abs(main)) {
            s.phase = "ignored";
            return;
          }
          if (s.scroller && scrollerWins(s.scroller, Math.sign(main))) {
            s.phase = "ignored";
            return;
          }
          begin(s, pointer);
          return;
        }

        tracker.add(pointer);
        s.last = infoFor(s, pointer);
        motion.current.value.set(s.last.value);
        opts.current.onDrag?.(s.last);
      };

      const end = (e: PointerEvent) => {
        const s = session.current;
        if (!s || e.pointerId !== s.id) return;
        session.current = null;
        window.removeEventListener("pointermove", onMove);
        window.removeEventListener("pointerup", end);
        window.removeEventListener("pointercancel", end);
        el.removeEventListener("touchmove", onTouchMove);
        if (s.phase === "dragging") {
          tracker.add(ax === "y" ? e.clientY : e.clientX);
          if (e.type === "pointerup") s.last = { ...s.last, velocity: tracker.velocity() };
          finish(s, e.type === "pointercancel");
        } else if (s.interrupted) {
          // A tap that caught the element mid-flight lets it finish where it was going.
          const pts = opts.current.snapPoints;
          const v = motion.current.value;
          if (pts?.length && current.current >= 0) settle(pts[current.current], v.getVelocity());
          else {
            const { min, max } = bounds();
            const inside = clamp(v.get(), min, max);
            if (inside !== v.get()) settle(inside, v.getVelocity());
          }
        }
      };

      const onDown = (e: PointerEvent) => {
        const o = opts.current;
        if (o.disabled || session.current) return;
        if (e.pointerType === "mouse" && e.button !== 0) return;
        if (isEditable(e.target) || (e.target instanceof Element && e.target.closest("[data-drag-ignore]"))) return;
        const interrupted = anim.current?.state === "running";
        if (interrupted) anim.current?.stop();
        session.current = {
          id: e.pointerId,
          type: e.pointerType,
          startX: e.clientX,
          startY: e.clientY,
          phase: "pending",
          scroller: (o.scrollHandoff ?? true) ? findScroller(e.target, el, ax) : null,
          interrupted,
          dragStart: 0,
          origin: 0,
          dimension: 1,
          last: { value: motion.current.value.get(), offset: 0, velocity: 0, projected: motion.current.value.get() },
        };
        window.addEventListener("pointermove", onMove);
        window.addEventListener("pointerup", end);
        window.addEventListener("pointercancel", end);
        // Non-passive only while a finger is down (pointerdown fires before touchstart, so it is
        // in place for this gesture); an idle element keeps compositor-threaded scrolling.
        if (e.pointerType === "touch") el.addEventListener("touchmove", onTouchMove, { passive: false });
      };

      // Touch scrolling is only cancellable from touchmove: once a pull is claimed as a drag,
      // the scroller under it must not also scroll or overscroll.
      const onTouchMove = (e: TouchEvent) => {
        if (session.current?.phase === "dragging" && e.cancelable) e.preventDefault();
      };

      el.addEventListener("pointerdown", onDown);
      return () => {
        el.removeEventListener("pointerdown", onDown);
        el.removeEventListener("touchmove", onTouchMove);
        window.removeEventListener("pointermove", onMove);
        window.removeEventListener("pointerup", end);
        window.removeEventListener("pointercancel", end);
        // Torn down mid-drag (unmount, or a new axis): give the page its selection back and
        // put the element back on a resting point.
        if (session.current?.phase === "dragging") {
          document.documentElement.style.userSelect = restoreSelect;
          el.style.willChange = "";
          setDragging(false);
          const pts = opts.current.snapPoints;
          const { min, max } = bounds();
          const v = motion.current.value;
          settle(pts?.length && current.current >= 0 ? pts[current.current] : clamp(v.get(), min, max), 0, true);
        }
        session.current = null;
      };
    },
    // Re-bind only when the axis or touch-action changes; everything else is read live.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [axis, touchAction === false ? "off" : (touchAction ?? ""), bounds, choose, settle],
  );

  useEffect(() => () => anim.current?.stop(), []);

  const onKeyDown = useCallback(
    (e: ReactKeyboardEvent) => {
      const pts = opts.current.snapPoints;
      if (!pts?.length) return;
      const ax = opts.current.axis ?? "y";
      const back = ax === "y" ? "ArrowUp" : "ArrowLeft";
      const forward = ax === "y" ? "ArrowDown" : "ArrowRight";
      // Screen order, so "up" always means toward the top whatever order the points are in.
      const order = pts.map((_, i) => i).sort((a, b) => pts[a] - pts[b]);
      const at = Math.max(0, order.indexOf(current.current));
      const to =
        e.key === back ? order[Math.max(0, at - 1)]
        : e.key === forward ? order[Math.min(order.length - 1, at + 1)]
        : e.key === "Home" ? order[0]
        : e.key === "End" ? order[order.length - 1]
        : undefined;
      if (to === undefined) return;
      e.preventDefault();
      snapTo(to);
    },
    [snapTo],
  );

  return { ref, value, dragging, index, snapTo, onKeyDown };
}

"use client";

/**
 * health-core: the pieces every Eased health block shares, so vitals, labs and schedules read
 * as one product: where a value sits against its range, the flag that says so, and clinic
 * clock times. Out of range reads `warning`, never `danger`: it is information for the
 * patient and their care team, not an error (rule 119). Import from here.
 */
import { AnimatePresence, motion } from "motion/react";
import { exitFast, reducedFade, snappy, useSafeReducedMotion } from "../../lib/motion";
import { TextSwap } from "../text-swap/text-swap";

/** Default locale and clinic time zone for every health format. Pass your own. */
export const HEALTH_LOCALE = "en-US";
export const HEALTH_TIME_ZONE = "UTC";

/* ---------- Ranges ----------------------------------------------------------------------- */

export type RangeStatus = "low" | "normal" | "high";
export type Range = { low: number; high: number };

/** Where `value` sits against a reference range (inclusive at both ends). */
export function rangeStatus(value: number, { low, high }: Range): RangeStatus {
  return value < low ? "low" : value > high ? "high" : "normal";
}

/** Text colour for a value in this state: in range stays `text-text`, out of range is `warning`. */
export const rangeText = (status: RangeStatus) => (status === "normal" ? "text-text" : "text-warning-text");

const FLAG_LABEL: Record<RangeStatus, string> = { low: "Low", normal: "In range", high: "High" };

export type RangeFlagProps = {
  status: RangeStatus;
  /** Show the "In range" chip too. Default false: only flags appear, and they pop in and out. */
  showNormal?: boolean;
  /** Override the labels, e.g. `{ high: "Above range" }`. */
  labels?: Partial<Record<RangeStatus, string>>;
  className?: string;
};

/**
 * A 20px flag for a value outside its range. It pops in on the snappy spring when a value
 * leaves the range and shrinks away when it returns; between Low and High its label swaps.
 */
export function RangeFlag({ status, showNormal = false, labels, className = "" }: RangeFlagProps) {
  const reduced = useSafeReducedMotion();
  const shown = status !== "normal" || showNormal;
  const label = labels?.[status] ?? FLAG_LABEL[status];
  const tone = status === "normal" ? "bg-success-subtle text-success-text" : "bg-warning-subtle text-warning-text";
  return (
    <AnimatePresence initial={false}>
      {shown && (
        <motion.span
          initial={reduced ? { opacity: 0 } : { opacity: 0, scale: 0.85 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={reduced ? { opacity: 0, transition: reducedFade } : { opacity: 0, scale: 0.9, transition: exitFast }}
          transition={reduced ? reducedFade : snappy}
          className={`inline-flex h-5 shrink-0 items-center rounded-control-xs px-1.5 text-ui-xs font-medium whitespace-nowrap transition-colors duration-150 ease-standard ${tone} ${className}`}
        >
          <TextSwap>{label}</TextSwap>
        </motion.span>
      )}
    </AnimatePresence>
  );
}

/* ---------- Clinic time ------------------------------------------------------------------ */

/** "08:30" → 510 minutes after midnight. */
export const toMinutes = (hhmm: string) => {
  const [h, m] = hhmm.split(":").map(Number);
  return h * 60 + (m || 0);
};

const timeFmt = new Map<string, Intl.DateTimeFormat>();
/** Epoch ms → "8:30 AM" in the clinic's time zone. */
export function formatClock(t: number, { locale = HEALTH_LOCALE, timeZone = HEALTH_TIME_ZONE }: { locale?: string; timeZone?: string } = {}) {
  const k = `${locale}|${timeZone}`;
  let f = timeFmt.get(k);
  if (!f) timeFmt.set(k, (f = new Intl.DateTimeFormat(locale, { hour: "numeric", minute: "2-digit", timeZone })));
  return f.format(t);
}

/** Minutes after midnight → "9:00 PM", without a date. */
export const formatMinutes = (minutes: number, locale = HEALTH_LOCALE) => formatClock(Date.UTC(2026, 0, 1, 0, minutes), { locale, timeZone: "UTC" });

"use client";

import { animate, motion, useMotionValue, useTransform, type AnimationPlaybackControls, type MotionValue } from "motion/react";
import { useCallback, useEffect, useRef, useState, type ButtonHTMLAttributes } from "react";
import { TextSwap } from "../text-swap/text-swap";

export type Hold = {
  /** 0 → 1 while held; drains back to 0 when let go early. */
  progress: MotionValue<number>;
  /** True between the hold starting and it completing or being let go. */
  holding: boolean;
  start: () => void;
  cancel: () => void;
};

/**
 * Hold-to-confirm timing. `start` fills `progress` linearly over the remaining share of
 * `holdMs`, so it reads as a clock and resuming a half-drained hold takes half the time;
 * `cancel` drains it on a short no-overshoot spring. `onDone` fires once the fill lands.
 */
export function useHold(holdMs: number, onDone: () => void, disabled: boolean): Hold {
  const progress = useMotionValue(0);
  const anim = useRef<AnimationPlaybackControls | null>(null);
  const done = useRef(onDone);
  useEffect(() => {
    done.current = onDone;
  });
  const [holding, setHolding] = useState(false);

  const start = useCallback(() => {
    if (disabled || anim.current) return;
    setHolding(true);
    // Time-true fill: the remaining share of the hold, linearly, so it reads as a clock.
    anim.current = animate(progress, 1, {
      duration: (holdMs / 1000) * (1 - progress.get()),
      ease: "linear",
      onComplete: () => {
        anim.current = null;
        setHolding(false);
        done.current();
      },
    });
  }, [disabled, holdMs, progress]);

  const cancel = useCallback(() => {
    if (!anim.current) return;
    anim.current.stop();
    anim.current = null;
    setHolding(false);
    // Let go early and it drains back quickly on the smooth spring, never overshooting.
    animate(progress, 0, { type: "spring", visualDuration: 0.3, bounce: 0 });
  }, [progress]);

  return { progress, holding, start, cancel };
}

export type HoldButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children"> & {
  hold: Hold;
  label: string;
};

/**
 * A 32px button that runs `hold` on pointer, Space or Enter: the same check + label on brand
 * is revealed left to right as the hold runs. Pass the resting surface, cursor and press
 * classes in `className`; the fill, size and handlers are fixed.
 */
export function HoldButton({ hold, label, className = "", ...props }: HoldButtonProps) {
  const clip = useTransform(hold.progress, (p) => `inset(0 ${(1 - p) * 100}% 0 0)`);
  const content = (tone: string) => (
    <span className={`inline-flex items-center gap-1.5 ${tone}`}>
      <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round" aria-hidden className="size-4 shrink-0">
        <path d="M3.5 8.5l3 3 6-7" />
      </svg>
      <TextSwap>{label}</TextSwap>
    </span>
  );
  return (
    <button
      type="button"
      {...props}
      data-holding={hold.holding || undefined}
      onPointerDown={(e) => {
        if (e.button !== 0) return;
        e.currentTarget.setPointerCapture(e.pointerId);
        hold.start();
      }}
      onPointerUp={hold.cancel}
      onPointerCancel={hold.cancel}
      onLostPointerCapture={hold.cancel}
      onKeyDown={(e) => {
        if ((e.key === " " || e.key === "Enter") && !e.repeat) {
          e.preventDefault();
          hold.start();
        }
      }}
      onKeyUp={(e) => {
        if (e.key === " " || e.key === "Enter") hold.cancel();
      }}
      onClick={(e) => e.preventDefault()}
      onContextMenu={(e) => e.preventDefault()}
      className={`relative inline-flex h-control-sm shrink-0 touch-none items-center justify-center overflow-hidden rounded-control-sm px-3 text-ui-sm font-medium select-none ${className}`}
    >
      {content("text-text")}
      {/* The fill: the same label on brand, revealed left to right as the hold runs. */}
      <motion.span aria-hidden className="absolute inset-0 flex items-center justify-center bg-brand inset-shadow-highlight" style={{ clipPath: clip }}>
        {content("text-text-on-brand")}
      </motion.span>
    </button>
  );
}

"use client";

/**
 * hr-core: what every Eased HR / recruiting block shares, so a pipeline, a profile and a
 * scorecard read as one product: the 1–4 interview scale, its four-pip meter, and the short
 * "3d in stage" clock. Import from here.
 */
import { motion } from "motion/react";
import { smooth, useSafeReducedMotion } from "../../lib/motion";

/** Default locale for every HR format. Pass your own. */
export const HR_LOCALE = "en-US";

/* ---------- The interview scale ---------------------------------------------------------- */

/** The four points Greenhouse and Ashby use. There is no middle: a panelist has to lean. */
export const RATING_LABELS = ["Strong no", "No", "Yes", "Strong yes"] as const;

/** "Strong yes" for 4, "Yes" for 3.4 (rounded), "" for no rating. */
export function ratingLabel(rating: number | null | undefined) {
  if (!rating) return "";
  return RATING_LABELS[Math.min(4, Math.max(1, Math.round(rating))) - 1];
}

/** Colour role of a rating: yes leans success, no leans warning (a "no" is information, not an error). */
export function ratingTone(rating: number | null | undefined): "success" | "warning" | "neutral" {
  if (!rating) return "neutral";
  return rating >= 2.5 ? "success" : "warning";
}

const PIP_FILL = { success: "bg-success", warning: "bg-warning", neutral: "bg-text-muted" } as const;

export type RatingPipsProps = {
  /** 1–4, fractional for a mean (3.4 fills three and a half pips). Null: empty. */
  value: number | null | undefined;
  /** Spoken label, e.g. "Jonas Lindqvist". The value and its word are added. */
  label?: string;
  locale?: Intl.LocalesArgument;
  /** Set the width here (default `w-16`); the pips share it. */
  className?: string;
};

/**
 * Four pips that fill to a rating: each pip's fill slides in on the smooth spring (a
 * transform, so a half pip keeps its rounded end), tinted success for yes and warning for no.
 * A `meter` with the value and its word spoken.
 */
export function RatingPips({ value, label, locale = HR_LOCALE, className = "w-16" }: RatingPipsProps) {
  const reduced = useSafeReducedMotion();
  const v = value ?? 0;
  const fill = PIP_FILL[ratingTone(value)];
  const nf = new Intl.NumberFormat(locale, { maximumFractionDigits: 1 });
  return (
    <span
      role="meter"
      aria-label={label}
      aria-valuemin={1}
      aria-valuemax={4}
      aria-valuenow={value ?? undefined}
      aria-valuetext={value ? `${nf.format(v)} of 4, ${ratingLabel(v)}` : "Not rated"}
      className={`inline-grid shrink-0 grid-cols-4 gap-0.5 ${className}`}
    >
      {[0, 1, 2, 3].map((i) => {
        const share = Math.min(1, Math.max(0, v - i));
        return (
          <span key={i} aria-hidden className="relative h-1.5 overflow-hidden rounded-pill bg-surface-active">
            <motion.span
              className={`absolute inset-0 rounded-pill transition-colors duration-200 ease-standard ${fill}`}
              initial={false}
              animate={{ x: `${(share - 1) * 100}%` }}
              transition={reduced ? { duration: 0 } : { ...smooth, delay: share > 0 ? i * 0.03 : (3 - i) * 0.03 }}
            />
          </span>
        );
      })}
    </span>
  );
}

/* ---------- Time in stage ---------------------------------------------------------------- */

/** "5h", "3d", "2w": how long something has sat in a stage, for dense cards. */
export function timeIn(since: number, now: number) {
  const h = Math.max(0, (now - since) / 3_600_000);
  if (h < 24) return `${Math.max(1, Math.round(h))}h`;
  const d = Math.round(h / 24);
  return d < 14 ? `${d}d` : `${Math.round(d / 7)}w`;
}

/** "5 hours", "3 days", for the spoken copy of `timeIn`. */
export function timeInLong(since: number, now: number) {
  const short = timeIn(since, now);
  const n = Number.parseInt(short, 10);
  const unit = short.endsWith("h") ? "hour" : short.endsWith("d") ? "day" : "week";
  return `${n} ${unit}${n === 1 ? "" : "s"}`;
}

"use client";

import {
  LayoutGroup,
  motion,
  useMotionValue,
  type HTMLMotionProps,
  type Transition,
} from "motion/react";
import { createContext, use, useId, useLayoutEffect, useMemo, useRef, type ReactNode } from "react";
import { instant, snappy, useSafeReducedMotion } from "../../lib/motion";

type IndicatorContextValue = { id: string; transition: Transition };

const IndicatorContext = createContext<IndicatorContextValue | null>(null);

export type IndicatorGroupProps = {
  children: ReactNode;
  /**
   * The spring every indicator in the group travels on. Default `snappy` (indicators are
   * feedback for a choice). Reduced motion always jumps, whatever you pass.
   */
  transition?: Transition;
};

/**
 * Scopes a set of indicators. Every `<Indicator>` with the same `name` inside one group is
 * the same visual element: render it inside whichever item is active and it travels there.
 * Groups never collide, so two segmented controls on a page move independently.
 */
export function IndicatorGroup({ children, transition = snappy }: IndicatorGroupProps) {
  const id = useId();
  const reduced = useSafeReducedMotion();
  const value = useMemo(() => ({ id, transition: reduced ? instant : transition }), [id, reduced, transition]);
  return (
    <LayoutGroup id={id}>
      <IndicatorContext value={value}>{children}</IndicatorContext>
    </LayoutGroup>
  );
}

export type IndicatorProps = Omit<HTMLMotionProps<"span">, "layoutId" | "layout"> & {
  /**
   * Indicators with the same name are one element. Use two names for two layers that move
   * independently, such as a selected thumb and a hover highlight. Default "indicator".
   */
  name?: string;
  /**
   * The corner radius, e.g. `"var(--eased-radius-control-sm)"`. Default: whatever your classes
   * resolve to, re-read whenever the indicator resizes. Pass it when the radius can change
   * without a resize (a theme that retunes `--eased-radius-*`).
   */
  radius?: string;
};

const CORNERS = ["borderTopLeftRadius", "borderTopRightRadius", "borderBottomRightRadius", "borderBottomLeftRadius"] as const;

/**
 * The shared-layout highlight. Render it, absolutely positioned, inside the active item
 * (the item needs `position: relative` and should draw its label above it); when another
 * item becomes active, render it there instead and it glides across.
 *
 * Interruptible: a new target mid-flight redirects from wherever the highlight is.
 * The corners stay round while it stretches between items of different widths: the
 * radius your classes resolve to (or `radius`) is handed to Motion's scale correction, and
 * re-read when the indicator resizes, so a responsive radius class stays correct.
 * Decorative: `aria-hidden` and `pointer-events: none`; the item carries the state.
 */
export function Indicator({ name = "indicator", radius, className = "", transition, style, ...props }: IndicatorProps) {
  const group = use(IndicatorContext);
  if (!group) throw new Error("<Indicator> must be rendered inside an <IndicatorGroup>.");
  const ref = useRef<HTMLSpanElement>(null);
  const tl = useMotionValue("");
  const tr = useMotionValue("");
  const br = useMotionValue("");
  const bl = useMotionValue("");

  // Before the first frame of a layout animation: corners set in `style` are scale-corrected.
  // To re-read the class radius, drop the inline corners for the read, then hand them back.
  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const corners = [tl, tr, br, bl];
    const read = () => {
      if (radius !== undefined) return corners.forEach((corner) => corner.set(radius));
      CORNERS.forEach((k) => (el.style[k] = ""));
      const computed = getComputedStyle(el);
      corners.forEach((corner, i) => {
        const value = computed[CORNERS[i]];
        el.style[CORNERS[i]] = value;
        corner.set(value);
      });
    };
    read();
    const ro = new ResizeObserver(read);
    ro.observe(el);
    return () => ro.disconnect();
  }, [radius, tl, tr, br, bl]);

  return (
    <motion.span
      ref={ref}
      aria-hidden
      layoutId={`${group.id}-${name}`}
      // One highlight moving, not two cross-fading: the old one hands over at full opacity.
      layoutCrossfade={false}
      transition={group.transition === instant ? instant : (transition ?? group.transition)}
      className={`pointer-events-none absolute ${className}`}
      style={{ borderTopLeftRadius: tl, borderTopRightRadius: tr, borderBottomRightRadius: br, borderBottomLeftRadius: bl, ...style }}
      {...props}
    />
  );
}

"use client";

import { animate, type AnimationPlaybackControls, type MotionValue, type Transition } from "motion/react";
import { useCallback, useEffect, useLayoutEffect, useMemo, useRef } from "react";
import { useSafeReducedMotion } from "../../lib/motion";
import { DECELERATION, clamp, nearest, project } from "../gesture/gesture-math";

/**
 * Where a coast is allowed to stop: a list of points, a step (every multiple of it, from
 * `min` or 0), or a function that rounds a resting position.
 */
export type InertiaSnap = readonly number[] | number | ((resting: number) => number);

export type InertiaOptions = {
  /** Resting points. Unset: the coast stops wherever friction leaves it. */
  snap?: InertiaSnap;
  /** Hard ends. The coast never rests past them. */
  min?: number;
  max?: number;
  /** UIScrollView friction per ms. Default `DECELERATION.normal` (0.998); wheels and pagers want `fast`. */
  decelerationRate?: number;
  /**
   * Below this release speed (px/s) a flick does not coast: the value rests where it was let go,
   * unless it is within `magnet` of a snap point. Default 0 (every release coasts).
   */
  minVelocity?: number;
  /** A slow release this close (px) to a snap point is pulled onto it. Default 0. */
  magnet?: number;
  /**
   * How the value travels to its resting point. `"spring"` (default) rides `transition`
   * carrying the release velocity; `"decay"` is iOS scroll friction that eases onto the point
   * (releases below `minVelocity` still settle on the spring).
   */
  mode?: "spring" | "decay";
  /** The spring for `"spring"` mode. Default a smooth spring that carries velocity. */
  transition?: Transition;
  /** Called once the value has come to rest, with where it rests. */
  onRest?: (value: number) => void;
};

const coast = { type: "spring", visualDuration: 0.45, bounce: 0.08 } as const;

/** Rounds `value` onto `snap`, inside `[min, max]`. */
export function resolveSnap(value: number, snap: InertiaSnap | undefined, min = -Infinity, max = Infinity) {
  const inside = clamp(value, min, max);
  if (snap === undefined) return inside;
  if (typeof snap === "function") return clamp(snap(inside), min, max);
  if (typeof snap === "number") {
    if (snap <= 0) return inside;
    const origin = Number.isFinite(min) ? min : 0;
    return clamp(origin + Math.round((inside - origin) / snap) * snap, min, max);
  }
  if (!snap.length) return inside;
  return clamp(snap[nearest(inside, snap)], min, max);
}

/**
 * Where a release at `position` moving at `velocity` (px/s) comes to rest: the snap point
 * nearest to where friction would carry it, not the one nearest the finger. Pure, so a
 * component can show the destination (a label, a tick) before the value gets there.
 */
export function inertiaTarget(position: number, velocity: number, options: InertiaOptions = {}) {
  const { snap, min = -Infinity, max = Infinity, decelerationRate = DECELERATION.normal, minVelocity = 0, magnet = 0 } = options;
  if (Math.abs(velocity) < minVelocity) {
    const resting = clamp(position, min, max);
    if (snap === undefined || magnet <= 0) return resting;
    const snapped = resolveSnap(resting, snap, min, max);
    return Math.abs(snapped - resting) <= magnet ? snapped : resting;
  }
  return resolveSnap(position + project(velocity, decelerationRate), snap, min, max);
}

export type UseInertia = {
  /**
   * Release the value with a velocity (px/s): it coasts and rests on a snap point inside the
   * bounds. Returns the resting position. Per-call options override the hook's.
   */
  release: (velocity: number, options?: InertiaOptions) => number;
  /** Animate to a position, carrying an optional velocity (keyboard steps, clicks, controlled values). */
  to: (target: number, options?: { velocity?: number; transition?: Transition; immediate?: boolean }) => void;
  /** Stop wherever the value is, e.g. when a finger catches it mid-coast. */
  stop: () => void;
  /** True while a coast or `to` animation runs. */
  isAnimating: () => boolean;
};

/**
 * Momentum for a MotionValue that something else drags: hand it the release velocity and it
 * coasts, with UIScrollView friction, to the snap point the flick would reach. Pairs with
 * `useDrag({ onRelease: () => false })` from the gesture kit. Under reduced motion every
 * release and `to` jumps straight to its resting point.
 *
 *   const inertia = useInertia(x, { snap: [0, 160, 320], min: 0, max: 320 });
 *   useDrag({ value: x, onRelease: ({ value, velocity }) => (inertia.release(velocity), false) });
 */
export function useInertia(value: MotionValue<number>, options: InertiaOptions = {}): UseInertia {
  const reduced = useSafeReducedMotion();
  const opts = useRef(options);
  const live = useRef({ value, reduced });
  useLayoutEffect(() => {
    opts.current = options;
    live.current = { value, reduced };
  });
  const anim = useRef<AnimationPlaybackControls | null>(null);

  const stop = useCallback(() => {
    anim.current?.stop();
    anim.current = null;
  }, []);

  const finish = useCallback((controls: AnimationPlaybackControls, onRest?: (v: number) => void) => {
    anim.current = controls;
    controls.finished.then(() => {
      if (anim.current !== controls) return;
      anim.current = null;
      onRest?.(live.current.value.get());
    });
  }, []);

  const to = useCallback<UseInertia["to"]>(
    (target, { velocity = 0, transition, immediate } = {}) => {
      const { value, reduced } = live.current;
      stop();
      if (immediate || reduced) {
        value.jump(target);
        opts.current.onRest?.(target);
        return;
      }
      finish(animate(value, target, { ...(transition ?? opts.current.transition ?? coast), velocity }), opts.current.onRest);
    },
    [finish, stop],
  );

  const release = useCallback<UseInertia["release"]>(
    (velocity, override) => {
      const o = { ...opts.current, ...override };
      const { value, reduced } = live.current;
      const from = value.get();
      const target = inertiaTarget(from, velocity, o);
      stop();
      if (reduced) {
        value.jump(target);
        o.onRest?.(target);
        return target;
      }
      // Released past an end: pull back without the outward velocity.
      const outside = from < (o.min ?? -Infinity) || from > (o.max ?? Infinity);
      const v = outside && Math.sign(velocity) === Math.sign(from - target) ? 0 : velocity;
      // A release slower than `minVelocity` has nothing to coast on: the spring settles it.
      if (o.mode === "decay" && Math.abs(velocity) >= (o.minVelocity ?? 0)) {
        const rate = o.decelerationRate ?? DECELERATION.normal;
        // Inertia only reads the origin, but Motion skips any animation whose keyframes are
        // all equal, so the keyframe must be the target rather than `from`.
        finish(
          animate(value, target, {
            type: "inertia",
            velocity: v,
            power: rate / (1 - rate) / 1000,
            timeConstant: 240,
            restDelta: 0.5,
            modifyTarget: () => target,
            min: o.min,
            max: o.max,
            bounceStiffness: 520,
            bounceDamping: 38,
          }),
          o.onRest,
        );
      } else {
        finish(animate(value, target, { ...(o.transition ?? coast), velocity: v }), o.onRest);
      }
      return target;
    },
    [finish, stop],
  );

  const isAnimating = useCallback(() => anim.current?.state === "running", []);

  useEffect(() => stop, [stop]);

  return useMemo(() => ({ release, to, stop, isAnimating }), [release, to, stop, isAnimating]);
}

export { DECELERATION } from "../gesture/gesture-math";

"use client";

/**
 * legal-core: the pieces every Eased legal block shares, so a review, a version compare and an
 * obligations list read as one product: the inline redline, the clause label, the AI mark,
 * deadline wording and the legal date formats. Import from here.
 */
import type { ReactNode } from "react";
import type { RedlineSegment } from "../doc-core/doc-core";

/** Default locale for every legal format. Pass your own. */
export const LEGAL_LOCALE = "en-US";

/* ---------- Formats ---------------------------------------------------------------------- */

const DAY = 86_400_000;
const HOUR = 3_600_000;

/** `Oct 27`, or `Oct 27, 2027` outside the current year. UTC unless you pass a zone. */
export function formatLegalDate(t: number, { now, locale = LEGAL_LOCALE, timeZone = "UTC" }: { now?: number; locale?: Intl.LocalesArgument; timeZone?: string } = {}) {
  const sameYear = now === undefined || new Date(now).getUTCFullYear() === new Date(t).getUTCFullYear();
  return new Intl.DateTimeFormat(locale, { month: "short", day: "numeric", year: sameYear ? undefined : "numeric", timeZone }).format(t);
}

export type Countdown = {
  /** Short, for a ring or a chip: `9d`, `22h`, `45m`, `2d` (overdue). */
  short: string;
  /** Spoken and for tooltips: "Due in 9 days", "Due in 22 hours", "Overdue by 2 days". */
  long: string;
  overdue: boolean;
  /** Milliseconds until due (negative once overdue). */
  remaining: number;
};

/** How far off a deadline is, in the largest whole unit that reads at a glance. */
export function countdown(due: number, now: number, locale: Intl.LocalesArgument = LEGAL_LOCALE): Countdown {
  const remaining = due - now;
  const abs = Math.abs(remaining);
  // Days from a day and a half, hours under that. Time left counts down in whole units (10.8
  // days left is "10d"); time overdue rounds, so 45 hours late reads "2 days".
  const days = remaining < 0 ? Math.round(abs / DAY) : Math.floor(abs / DAY);
  const [n, unit, letter] = abs >= 1.5 * DAY ? [days, "day", "d"] : abs >= HOUR ? [Math.floor(abs / HOUR), "hour", "h"] : [Math.max(1, Math.floor(abs / 60_000)), "minute", "m"];
  const count = new Intl.NumberFormat(locale, { style: "unit", unit: unit as "day", unitDisplay: "long" }).format(n);
  const overdue = remaining < 0;
  return { short: `${n}${letter}`, long: overdue ? `Overdue by ${count}` : `Due in ${count}`, overdue, remaining };
}

/** `93%` for a model confidence. */
export const formatConfidence = (v: number, locale: Intl.LocalesArgument = LEGAL_LOCALE) => new Intl.NumberFormat(locale, { style: "percent", maximumFractionDigits: 0 }).format(v);

/* ---------- Clause label ----------------------------------------------------------------- */

/**
 * The clause number in a fixed track and its caption, for any row that cites a clause:
 * `4  Limitation of liability`. Put it in a `grid-cols-[2rem_minmax(0,1fr)]` row (or use
 * `CLAUSE_GRID`) so every number and every caption share one edge (rule 101).
 */
export const CLAUSE_GRID = "grid grid-cols-[2rem_minmax(0,1fr)]";

export function ClauseLabel({ number, title, className = "" }: { number?: string; title?: ReactNode; className?: string }) {
  return (
    <>
      <span className={`text-ui-sm text-text-muted tabular-nums ${className}`}>{number}</span>
      <span className={`min-w-0 truncate text-ui-sm font-medium text-text ${className}`}>{title}</span>
    </>
  );
}

/* ---------- Redline ---------------------------------------------------------------------- */

const count = (s: string, c: string) => s.split(c).length - 1;

/**
 * Word diffs split "thirty (30)" → "forty-five (45)" around the bracket they share, leaving
 * "thirty (30" struck and ")" plain. This moves a closing bracket that an edit opened back into
 * the edit (both sides), so each side reads as a whole phrase. Pure; safe in render.
 */
export function tidyRedline(segments: readonly RedlineSegment[]): RedlineSegment[] {
  const out = segments.map((s) => ({ ...s }));
  for (let i = 0; i < out.length; i++) {
    const s = out[i];
    if (s.kind === "equal" || !s.changeId) continue;
    let j = i;
    while (j + 1 < out.length && out[j + 1].kind !== "equal" && out[j + 1].changeId === s.changeId) j++;
    const next = out[j + 1];
    const m = next && /^[)\]]/.exec(next.text);
    const group = out.slice(i, j + 1);
    if (m && group.every((g) => count(g.text, "(") + count(g.text, "[") > count(g.text, ")") + count(g.text, "]"))) {
      for (const g of group) g.text += m[0];
      next.text = next.text.slice(1);
    }
    i = j;
  }
  return out.filter((s) => s.text);
}

export type RedlineTextProps = {
  segments: readonly RedlineSegment[];
  /** Show only one side: `before` hides inserts, `after` hides deletes. Default both (a redline). */
  side?: "both" | "before" | "after";
  /** Change ids that are being rejected right now: their inserts strike through and dim. */
  striking?: ReadonlySet<string>;
  className?: string;
};

/**
 * A lawyer's inline redline: inserted words in success ink with an underline, deleted words
 * struck in danger ink, the rest as written. Inserts and deletes are real `<ins>`/`<del>`, so
 * screen readers and copy-paste keep the meaning. Colours change on a 150ms tween, so a
 * strike that lands mid-swap stays smooth.
 */
export function RedlineText({ segments, side = "both", striking, className = "" }: RedlineTextProps) {
  return (
    <span className={className}>
      {segments.map((s, i) => {
        if (s.kind === "equal") return <span key={i}>{s.text}</span>;
        if (s.kind === "insert") {
          if (side === "before") return null;
          const struck = s.changeId && striking?.has(s.changeId);
          // A replacement's insert sits right after its delete: keep a hair of space between them.
          const afterDelete = side === "both" && segments[i - 1]?.kind === "delete";
          return (
            <ins
              key={i}
              className={`rounded-control-2xs no-underline transition-[color,background-color,text-decoration-color,opacity] duration-150 ease-standard ${
                side === "after" ? "bg-success-subtle text-success-text" : "underline decoration-success-text/40 decoration-1 underline-offset-[3px] text-success-text"
              } ${afterDelete ? "ms-[0.3em]" : ""} ${struck ? "line-through decoration-danger-text opacity-60" : ""}`}
            >
              {s.text}
            </ins>
          );
        }
        if (side === "after") return null;
        return (
          <del
            key={i}
            className={`rounded-control-2xs transition-colors duration-150 ease-standard ${side === "before" ? "bg-danger-subtle text-danger-text no-underline" : "text-danger-text line-through decoration-danger-text/60"}`}
          >
            {s.text}
          </del>
        );
      })}
    </span>
  );
}

