/**
 * The frosted panel. 11px corners, 12px padding, 13px SF type. It exposes `--pad` and
 * `--radius-outer` so nested corners stay concentric (rows use 7px).
 */
export function MacMenuPopoverContent({
  width = 320,
  arrow = true,
  material = "css",
  side = "bottom",
  align = "center",
  sideOffset = 6,
  alignOffset = 0,
  collisionPadding = 8,
  collisionBoundary,
  initialFocus,
  finalFocus,
  container,
  zIndex = 50,
  className = "",
  children,
