  return (
    <svg {...iconProps}>
      <path d="M4.5 2h4.2L12 5.3v7.2c0 .8-.7 1.5-1.5 1.5h-6c-.8 0-1.5-.7-1.5-1.5v-9C3 2.7 3.7 2 4.5 2z" />
      <path d="M8.5 2v3.5H12" />
