  data,
  columns,
  getRowId,
  label,
  loading,
  selectable,
  pageSizes,
  sort,
  defaultSort,
  onSortChange,
  search,
  defaultSearch,
  onSearchChange,
  filters,
  defaultFilters,
  onFiltersChange,
  hiddenColumns,
  defaultHiddenColumns,
  onHiddenColumnsChange,
  selected,
  defaultSelected,
  onSelectedChange,
  page,
  defaultPage,
  onPageChange,
  pageSize,
  defaultPageSize,
  onPageSizeChange,
  className,
  children,
  ...props
}: DataTableRootProps) {
  const handle = usePrimitive(dataTable, {
    data,
    columns,
    getRowId,
    label,
    loading,
    selectable,
    pageSizes,
    sort,
    defaultSort,
    onSortChange,
    search,
    defaultSearch,
    onSearchChange,
    filters,
    defaultFilters,
    onFiltersChange,
    hiddenColumns,
