    <DatePickerPresetPart
      className={withClass("transition-[scale] duration-[calc(200ms*var(--kf-speed,1))] ease-pop active:scale-[0.96] data-disabled:active:scale-100 motion-reduce:transition-none!", className)}
      {...props}
    />
