const keyframes =
  "@keyframes kf-dir-rtl{from{opacity:0;translate:28px 0;filter:blur(6px)}}" +
  "@keyframes kf-dir-ltr{from{opacity:0;translate:-28px 0;filter:blur(6px)}}"

