/* Description lists, as UI SDK primitives. UI SDK ships none, so they are defined with its core: the
   same definitions render in React, Vue, Svelte, Solid and web components.

   `descriptionList` is the label and value rows of a detail page (a customer, an order), with real
   `dl` / `dt` / `dd` semantics. It lays them out as rows, stacked or a grid (`layout`), wraps or
   truncates long values (`truncate`, with the full text as a title), and keeps every label and value
   readable for agents as its `items`.

   `descriptionListCopy` is a button that copies one value: the text you give it, or the value it
   sits beside. It says "Copied" on itself for two seconds and tells screen readers. */

import { announce, css, definePrimitive } from "@ui-sdk/core"

type DescriptionListLayout = "rows" | "stacked" | "grid"

type DescriptionListOptions = {
  /** "rows" (a label column and hairlines, the default), "stacked" (label above value) or "grid". */
  layout?: DescriptionListLayout
  /** For the grid: how many columns, at full width. */
  columns?: number
  /** Long values stay on one line, ending in an ellipsis, with the full text as a title. */
  truncate?: boolean
}

type DescriptionListItem = { value: string; label: string }

type DescriptionListState = {
  layout: DescriptionListLayout
  columns: number
  truncate: boolean
  /** Every label with its value, read from the page. */
  items: DescriptionListItem[]
}

const fromOptions = (options: DescriptionListOptions) => ({
  layout: options.layout ?? "rows",
  columns: Math.max(1, Math.min(4, options.columns ?? 2)),
  truncate: options.truncate ?? false,
})

/* The text a value part shows, without its actions or anything hidden from readers. */
function readText(node: Node): string {
  if (node.nodeType === Node.TEXT_NODE) return node.textContent ?? ""
  if (!(node instanceof Element)) return ""
  if (node.matches('[aria-hidden="true"], [hidden], [data-agent-hidden], [data-slot="description-list-actions"], .sr-only')) return ""
  if (node.hasAttribute("data-agent-secret")) return "[redacted]"
  return Array.from(node.childNodes, readText).join(" ")
}

const clean = (text: string) => text.replace(/\s+/g, " ").trim()

/** The value of one item element: its value part if it has one, else its details. */
function valueOf(item: Element) {
  const value = item.querySelector('[data-slot="description-list-value"]') ?? item.querySelector('[data-slot="description-list-details"]')
  return value ? clean(readText(value)) : ""
}

function labelOf(item: Element) {
  const term = item.querySelector('[data-slot="description-list-term"]')
  return term ? clean(readText(term)) : ""
}

const descriptionList = definePrimitive({
  name: "description-list",
  options: { layout: "string", columns: "number", truncate: "boolean" },
  state: (options: DescriptionListOptions): DescriptionListState => ({ ...fromOptions(options), items: [] }),
  sync: (options) => fromOptions(options),
  controlled: ["items", "layout"],
  api: (context) => ({
    /** @internal Reads every label and value from the page into `items`. */
    read(el: HTMLElement) {
      const items = Array.from(el.querySelectorAll('[data-slot="description-list-item"]'), (item) => ({
        label: labelOf(item),
        value: valueOf(item),
      })).filter((item) => item.label || item.value)
      const now = context.store.get().items
      if (items.length === now.length && items.every((item, index) => item.label === now[index].label && item.value === now[index].value)) return
      context.store.set({ items })
    },
  }),
  slots: (slot) => ({
    root: slot<{}, { layout: DescriptionListLayout; columns: number; truncate: boolean }>({
      state: (state) => ({ layout: state.layout, columns: state.columns, truncate: state.truncate }),
      attrs: (state) => ({
        "data-layout": state.layout,
        "data-truncate": state.truncate ? "" : undefined,
        style: css({ "--description-list-columns": state.columns }),
      }),
      bind: (el, part) => {
        part.api.read(el)
        const observer = new MutationObserver(() => part.api.read(el))
        observer.observe(el, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ["aria-hidden", "hidden"] })
        return () => observer.disconnect()
      },
    }),
    /* One label with its value. A `div` around a `dt` and its `dd`s is valid inside a `dl`. */
    item: slot<{ value?: string }, { layout: DescriptionListLayout }>({
      props: { value: "string" },
      state: (state) => ({ layout: state.layout }),
      attrs: (state) => ({ "data-layout": state.layout }),
    }),
    term: slot({}),
    details: slot<{}, { truncate: boolean }>({
      state: (state) => ({ truncate: state.truncate }),
      attrs: (state) => ({ "data-truncate": state.truncate ? "" : undefined }),
    }),
    /* The value itself, beside any actions. Truncated, it carries its full text as a title. */
    value: slot<{}, { truncate: boolean }>({
      state: (state) => ({ truncate: state.truncate }),
      attrs: (state) => ({ "data-truncate": state.truncate ? "" : undefined }),
      bind: (el, part) => {
        const title = () => {
          const text = clean(readText(el))
          if (part.store.get().truncate && text) el.setAttribute("title", text)
          else el.removeAttribute("title")
        }
        title()
        const observer = new MutationObserver(title)
        observer.observe(el, { subtree: true, childList: true, characterData: true })
        const stop = part.store.subscribe(title)
        return () => {
          observer.disconnect()
          stop()
        }
      },
    }),
    /* Buttons or links that act on the value: a copy button, an Edit link. */
    actions: slot({}),
  }),
  /* Agents read every label and value; the list itself has no actions. */
  agent: { actions: [] },
})

type DescriptionListCopyOptions = {
  /** The text to copy. Leave it out to copy the value the button sits beside. */
  value?: string
  /** What the value is called, for the button's name ("Copy Email"). Read from the item's label when left out. */
  label?: string
  /** Runs after the text was copied. */
  onCopy?: (text: string) => void
}

type DescriptionListCopyState = {
  copied: boolean
  /** What the button copies, read from the page when no `value` is given. */
  text: string
  /** What the value is called. */
  label: string
}

const descriptionListCopy = definePrimitive({
  name: "description-list-copy",
  options: { value: "string", label: "string", onCopy: "callback" },
  state: (options: DescriptionListCopyOptions): DescriptionListCopyState => ({
    copied: false,
    text: options.value ?? "",
    label: options.label ?? "",
  }),
  sync: (options) => ({
    ...(options.value === undefined ? {} : { text: options.value }),
    ...(options.label === undefined ? {} : { label: options.label }),
  }),
  controlled: ["copied", "text"],
  api: (context) => {
    let timer: ReturnType<typeof setTimeout> | undefined
    let button: HTMLElement | undefined
    context.onDestroy(() => clearTimeout(timer))

    const write = async (text: string) => {
      try {
        await navigator.clipboard.writeText(text)
      } catch {
        /* No clipboard permission (an insecure page, an embedded frame): the old way still works. */
        const area = document.createElement("textarea")
        area.value = text
        area.setAttribute("readonly", "")
        area.style.position = "fixed"
        area.style.opacity = "0"
        document.body.append(area)
        area.select()
        document.execCommand("copy")
        area.remove()
      }
    }

    return {
      /** @internal Reads the value and label beside the button, when they weren't given. */
      attach(el: HTMLElement) {
        button = el
        const item = el.closest('[data-slot="description-list-item"]')
        if (!item) return () => {}
        const read = () => {
          const options = context.options()
          const next: Partial<DescriptionListCopyState> = {}
          if (options.value === undefined) next.text = valueOf(item)
          if (options.label === undefined) next.label = labelOf(item)
          const now = context.store.get()
          if ((next.text ?? now.text) !== now.text || (next.label ?? now.label) !== now.label) context.store.set(next)
        }
        read()
        const observer = new MutationObserver(read)
        observer.observe(item, { subtree: true, childList: true, characterData: true })
        return () => {
          observer.disconnect()
          button = undefined
        }
      },
      /** Copies the value, says "Copied" on the button for two seconds and tells screen readers. */
      async copy() {
        const { text } = context.store.get()
        await write(text)
        clearTimeout(timer)
        context.store.set({ copied: true })
        announce("Copied")
        context.options().onCopy?.(text)
        const speed = (button && parseFloat(getComputedStyle(button).getPropertyValue("--kf-speed"))) || 1
        timer = setTimeout(() => context.store.set({ copied: false }), 2000 * speed)
      },
    }
  },
  slots: (slot) => ({
    root: slot<{}, { copied: boolean }>({
      role: "button",
      focus: "native",
      state: (state) => ({ copied: state.copied }),
      attrs: (state) => ({
        type: "button",
        "aria-label": state.copied ? "Copied" : state.label ? `Copy ${state.label}` : "Copy",
        "data-copied": state.copied ? "" : undefined,
      }),
      press: ({ api }) => void api.copy(),
      bind: (el, part) => part.api.attach(el),
    }),
  }),
  agent: { actions: ["copy"] },
})

export {
  descriptionList,
  descriptionListCopy,
  type DescriptionListCopyOptions,
  type DescriptionListItem,
  type DescriptionListLayout,
  type DescriptionListOptions,
}

/* Reading direction, as a UI SDK primitive. UI SDK's rule is that right to left needs no provider:
   its components read the direction from the page (`isRTL(el)`, the computed `direction`), so
   arrow keys, positions and stretches already mirror wherever `dir="rtl"` applies. What a page
   still needs is a part that sets `dir` (and `lang`) for the content inside it, a way to flip it,
   and a way to read it. That is this primitive, defined with UI SDK's core: the same definition
   renders in React, Vue, Svelte, Solid and web components.

   It holds no context. Everything inside reads the direction from the element, as UI SDK's own
   components do, so a component that knows nothing of this one mirrors with it. */

import { type ChangeDetails, createChange, definePrimitive, isRTL } from "@ui-sdk/core"

type Dir = "ltr" | "rtl"

// "toggle-press" isn't in UI SDK's shared vocabulary.
type DirChangeReason = "toggle-press" | "imperative"

type DirectionOptions = {
  /** The reading direction of the content inside, when you control it. */
  dir?: Dir
  /** The reading direction to start with, when the part keeps it. Defaults to `"ltr"`. */
  defaultDir?: Dir
  /** Called when the direction is asked to change. */
  onDirChange?: (dir: Dir, details: ChangeDetails<DirChangeReason>) => void
  /** The language of the content inside, written as `lang` beside `dir`. */
  lang?: string
}

type DirectionState = {
  dir: Dir
  lang: string | undefined
  /** How many times the direction has changed since the part mounted. */
  flips: number
}

/** The direction an element is laid out in, from its computed style. */
function directionOf(el: Element | null | undefined): Dir {
  return isRTL(el) ? "rtl" : "ltr"
}

/** Calls `onChange` whenever a `dir` attribute anywhere in the page changes the direction `el` is
    laid out in. Returns the function that stops watching. */
function watchDirection(el: Element, onChange: (dir: Dir) => void) {
  let current = directionOf(el)
  const observer = new MutationObserver(() => {
    const next = directionOf(el)
    if (next === current) return
    current = next
    onChange(next)
  })
  observer.observe(el.ownerDocument.documentElement, { attributes: true, attributeFilter: ["dir"], subtree: true })
  return () => observer.disconnect()
}

const labels: Record<Dir, string> = { ltr: "Left to right", rtl: "Right to left" }

const direction = definePrimitive({
  name: "direction",
  options: { dir: "string", defaultDir: "string", onDirChange: "callback", lang: "string" },
  controlled: ["dir"],
  state: (options: DirectionOptions): DirectionState => ({
    dir: options.dir ?? options.defaultDir ?? "ltr",
    lang: options.lang,
    flips: 0,
  }),
  sync: (options) => ({ ...(options.dir === undefined ? {} : { dir: options.dir }), lang: options.lang }),
  api: (context) => {
    const change = createChange(context)
    /* Count every change of direction, controlled or not, so the content can play its move only
       after one (never on first load). */
    let last = context.store.get().dir
    context.onDestroy(
      context.store.subscribe(() => {
        const { dir, flips } = context.store.get()
        if (dir === last) return
        last = dir
        context.store.set({ flips: flips + 1 })
      }),
    )
    return {
      /** Sets the reading direction. */
      setDir: (dir: Dir, event?: Event) => change("dir", dir, { reason: "imperative", event }),
      /** Switches between left to right and right to left. */
      toggle: (event?: Event) =>
        change("dir", context.store.get().dir === "rtl" ? "ltr" : "rtl", { reason: "toggle-press", event }),
    }
  },
  slots: (slot) => ({
    root: slot<{}, { dir: Dir; flipped: boolean }>({
      state: (state) => ({ dir: state.dir, flipped: state.flips > 0 }),
      attrs: (state) => ({
        dir: state.dir,
        lang: state.lang,
        "data-dir": state.dir,
        "data-flipped": state.flips > 0 ? "" : undefined,
      }),
    }),
    /* A button that flips the direction. Pressed while the content reads right to left. */
    toggle: slot<{}, { dir: Dir }>({
      role: "button",
      focus: "native",
      press: ({ api }, event) => api.toggle(event),
      state: (state) => ({ dir: state.dir }),
      attrs: (state) => ({
        type: "button",
        "aria-pressed": String(state.dir === "rtl"),
        "data-dir": state.dir,
      }),
    }),
  }),
  agent: {
    actions: ["setDir", "toggle"],
    closed: true,
    items: () => (["ltr", "rtl"] as const).map((value) => ({ value, label: labels[value] })),
  },
})

export { type Dir, direction, directionOf, type DirectionOptions, watchDirection }

/* Empty state, as a UI SDK primitive. UI SDK ships no empty state, so it is defined with its core:
   the same definition renders in React, Vue, Svelte, Solid and web components.

   An empty state stands in for content that isn't there yet: no results, an empty inbox, a
   project with no files. Its parts are shadcn's: a header holding the media, title and
   description, then content for the actions. It arrives with an entrance (`data-starting-style`
   for its first frame, from `animateIn`). With `announce`, a screen reader hears its title and
   description when it appears, as when a search finds nothing. */

import { animateIn, announce, definePrimitive, elements, prepareAnnouncements } from "@ui-sdk/core"

import { bindAgentContent } from "@/components/core/agent-content"

type EmptyOptions = {
  /** Reads the title and description to screen readers when the empty state appears. Use it when it replaces results someone was looking at. @defaultValue false */
  announce?: boolean
}

type EmptyMediaVariant = "default" | "icon"

const empty = definePrimitive({
  name: "empty",
  options: { announce: "boolean" },
  state: (_options: EmptyOptions) => ({ content: "" }),
  controlled: ["content"],
  api: (context) => ({
    /** Plays the entrance, and with `announce` reads the title and description once it is in. */
    arrive(el: HTMLElement) {
      const stop = animateIn(el)
      if (!context.options().announce) return stop
      prepareAnnouncements(el.ownerDocument)
      /* After the regions exist, so screen readers that only watch regions already there hear it. */
      const timer = setTimeout(() => {
        const text = [...elements(context, "title"), ...elements(context, "description")]
          .map((part) => part.el.textContent?.trim())
          .filter(Boolean)
          .join(". ")
        if (text) announce(text, { doc: el.ownerDocument })
      }, 150)
      return () => {
        stop()
        clearTimeout(timer)
      }
    },
  }),
  slots: (slot) => ({
    root: slot({
      state: () => ({}),
      bind: (el, part) => {
        const stopEntrance = part.api.arrive(el)
        const stopContent = bindAgentContent(el, (content) => part.store.set({ content }))
        return () => {
          stopEntrance()
          stopContent()
        }
      },
    }),
    header: slot({}),
    media: slot<{ variant?: EmptyMediaVariant }, { variant: EmptyMediaVariant }>({
      props: { variant: "string" },
      state: (_state, part) => ({ variant: part.props.variant ?? "default" }),
      attrs: (_state, part) => ({ "data-variant": part.props.variant ?? "default", "aria-hidden": "true" }),
    }),
    title: slot({}),
    description: slot({}),
    content: slot({}),
  }),
  /* Expose the empty state's title and description; its buttons own their actions. */
  agent: { actions: [] },
})

export { empty, type EmptyMediaVariant, type EmptyOptions }

/* Faceted filters, as UI SDK primitives. UI SDK ships no filter, so these are defined with its core:
   the same definitions render in React, Vue, Svelte, Solid and web components.

   `filter` is one facet of a data table's toolbar: a chip named after a column ("Status") that opens
   a searchable list of that column's values, each with a count. It owns which values are chosen,
   whether its list is open and what is typed in its search. The list itself is UI SDK's combobox
   (multiple, with its input inside the popup), rendered by the adapter and controlled from this
   state: the combobox's `onValueChange`, `onOpenChange` and `onQueryChange` call `choose`,
   `setOpen` and `search` here. The value is always a list of strings; with `multiple: false`,
   choosing a value replaces the one before and closes the list.

   `filterBar` is the row that holds several filters. It counts the filters inside it that have
   something chosen, and its reset button clears them all (each filter hears a `filter-reset`
   event on its root and clears itself, so controlled and uncontrolled filters both work). */

import { type ChangeDetails, createChange, definePrimitive, dispatch } from "@ui-sdk/core"

/** One value a filter offers. */
type FilterOption = {
  /** What the filter's value holds when this option is chosen. */
  value: string
  /** What the option and its badge say. */
  label: string
  /** How many rows have this value. Shown at the option's end. */
  count?: number
  /** Can't be chosen. */
  disabled?: boolean
}

/** The value the "Clear filter" row of the list carries. The filter never stores it. */
const FILTER_CLEAR = "kf-filter-clear"

/* "clear-press", "reset-press" and "imperative" aren't in the shared vocabulary. The combobox's own
   reasons ("item-press", "chip-remove-press", "backspace-key", …) pass through as they are. */
type FilterValueChangeReason = "item-press" | "clear-press" | "reset-press" | "imperative" | (string & {})
type FilterOpenChangeReason = "trigger-press" | "item-press" | "escape-key" | "outside-press" | "focus-out" | "imperative" | (string & {})

type FilterOptions = {
  /** The column or facet the filter narrows, like "Status". Names the chip, its list and the filter for agents. */
  label?: string
  /** The values to choose from. */
  options?: readonly FilterOption[]
  /** The chosen values, controlled. */
  value?: string[]
  /** The chosen values at first, when uncontrolled. */
  defaultValue?: string[]
  /** Runs when the chosen values want to change. `details.cancel()` keeps them. */
  onValueChange?: (value: string[], details: ChangeDetails<FilterValueChangeReason>) => void
  /** Several values at once (the default), or one that replaces the last. */
  multiple?: boolean
  /** Whether the list is open, controlled. */
  open?: boolean
  /** Whether the list starts open, when uncontrolled. */
  defaultOpen?: boolean
  /** Runs when the list wants to open or close. */
  onOpenChange?: (open: boolean, details: ChangeDetails<FilterOpenChangeReason>) => void
}

type FilterState = {
  label: string
  options: readonly FilterOption[]
  value: string[]
  /** The chosen options' labels, in the options' order. */
  chosen: string[]
  multiple: boolean
  open: boolean
  query: string
}

const labelsOf = (options: readonly FilterOption[], value: readonly string[]) =>
  options.filter((option) => value.includes(option.value)).map((option) => option.label)

/* Chosen values in the options' order, so badges don't reorder as people pick. Values the options
   don't know (yet) stay at the end. */
const ordered = (options: readonly FilterOption[], value: readonly string[]) => [
  ...options.filter((option) => value.includes(option.value)).map((option) => option.value),
  ...value.filter((entry) => !options.some((option) => option.value === entry)),
]

const filter = definePrimitive({
  name: "filter",
  options: {
    label: "string",
    options: "value",
    value: "list",
    defaultValue: "list",
    onValueChange: "callback",
    multiple: "boolean",
    open: "boolean",
    defaultOpen: "boolean",
    onOpenChange: "callback",
  },
  state: (options: FilterOptions): FilterState => {
    const value = options.value ?? options.defaultValue ?? []
    const list = options.options ?? []
    return {
      label: options.label ?? "Filter",
      options: list,
      value,
      chosen: labelsOf(list, value),
      multiple: options.multiple ?? true,
      open: options.open ?? options.defaultOpen ?? false,
      query: "",
    }
  },
  sync: (options) => ({
    label: options.label ?? "Filter",
    options: options.options ?? [],
    multiple: options.multiple ?? true,
    ...(options.value === undefined ? {} : { value: options.value }),
    ...(options.open === undefined ? {} : { open: options.open }),
  }),
  controlled: ["value", "open", "chosen"],
  api: (context) => {
    const { store } = context
    const change = createChange(context)

    /* `chosen` follows the value and the options, however either changes. */
    let from = { options: store.get().options, value: store.get().value }
    context.onDestroy(
      store.subscribe(() => {
        const { options, value } = store.get()
        if (options === from.options && value === from.value) return
        from = { options, value }
        store.set({ chosen: labelsOf(options, value) })
      }),
    )

    /* A value or a label, matched without regard to case, as an agent or a person might name it. */
    const resolve = (name: string) => {
      const options = store.get().options
      const exact = options.find((option) => option.value === name)
      if (exact) return exact.value
      const lower = name.trim().toLowerCase()
      return options.find((option) => option.label.toLowerCase() === lower || option.value.toLowerCase() === lower)?.value ?? name
    }

    const write = (next: string[], reason: FilterValueChangeReason, event?: Event) => {
      const value = ordered(store.get().options, next)
      const now = store.get().value
      if (value.length === now.length && value.every((entry, index) => entry === now[index])) return false
      return change("value", value, { reason, event })
    }

    const api = {
      /** Chooses exactly these values (by value or label). With `multiple: false`, only the first counts. */
      setValue(value: string[] | string, event?: Event) {
        const list = (Array.isArray(value) ? value : [value]).map(resolve)
        return write(store.get().multiple ? list : list.slice(0, 1), "imperative", event)
      },
      /** Adds a value if it isn't chosen, removes it if it is. */
      toggle(value: string, event?: Event) {
        const key = resolve(value)
        const now = store.get().value
        if (now.includes(key)) return write(now.filter((entry) => entry !== key), "imperative", event)
        return write(store.get().multiple ? [...now, key] : [key], "imperative", event)
      },
      /** Removes every chosen value. */
      clear(event?: Event, reason: FilterValueChangeReason = "clear-press") {
        return write([], reason, event)
      },
      /** What the combobox inside wants the value to be: a toggle, the clear row, or Backspace. */
      choose(next: readonly string[], details: { reason: string; event?: Event }) {
        const { value: now, multiple } = store.get()
        if (next.includes(FILTER_CLEAR)) {
          api.clear(details.event)
          return
        }
        if (multiple) {
          write([...next], details.reason, details.event)
          return
        }
        const added = next.find((entry) => !now.includes(entry))
        write(added ? [added] : [...next].slice(-1).filter((entry) => !now.includes(entry)), details.reason, details.event)
        if (added) api.setOpen(false, { reason: "item-press", event: details.event })
      },
      /** Opens or closes the list. Opening starts the search over. */
      setOpen(open: boolean, details: { reason?: FilterOpenChangeReason; event?: Event } = {}) {
        if (open === store.get().open) return true
        const done = change("open", open, { reason: details.reason ?? "imperative", event: details.event })
        if (done && open) store.set({ query: "" })
        return done
      },
      /** What is typed in the list's search field. */
      search(query: string) {
        if (query !== store.get().query) store.set({ query })
      },
      /** The options, for agents to choose from. */
      items() {
        return store.get().options.map((option) => ({ value: option.value, label: option.label }))
      },
    }
    return api
  },
  slots: (slot) => ({
    /* Wraps the chip and its list. Named after the facet, so the filter reads as "Status". */
    root: slot<{}, { value: string[]; chosen: string[]; open: boolean; query: string; active: boolean }>({
      role: "group",
      state: (state) => ({ value: state.value, chosen: state.chosen, open: state.open, query: state.query, active: state.value.length > 0 }),
      attrs: (state) => ({
        "aria-label": state.label,
        "data-active": state.value.length > 0 ? "" : undefined,
        "data-open": state.open ? "" : undefined,
        "data-count": String(state.value.length),
      }),
      bind: (el, part) => {
        const reset = (event: Event) => part.api.clear(event, "reset-press")
        el.addEventListener("filter-reset", reset)
        return () => el.removeEventListener("filter-reset", reset)
      },
    }),
  }),
  agent: { actions: ["setValue", "toggle", "clear"], items: (api) => api.items() },
})

type FilterValuesOptions = {
  /** The chosen values. */
  value?: string[]
  /** Their labels, in the same order. */
  chosen?: string[]
}

/* The chosen values inside the chip, as a primitive of their own: the chip belongs to the combobox
   (which the filter hides from agents, since the filter already offers everything it does), so its
   contents can't be parts of the filter without hiding the filter too. Its width follows what it
   holds (`--filter-values-width`, measured from its first child), so the chip can widen and narrow
   smoothly. Decorative: the chip's accessible name carries the chosen labels as text. */
const filterValues = definePrimitive({
  name: "filter-values",
  options: { value: "list", chosen: "list" },
  state: (options: FilterValuesOptions) => ({ value: options.value ?? [], chosen: options.chosen ?? [] }),
  sync: (options) => ({ value: options.value ?? [], chosen: options.chosen ?? [] }),
  controlled: [],
  api: () => ({}),
  slots: (slot) => ({
    root: slot<{}, { value: string[]; chosen: string[]; count: number; summary: string }>({
      state: (state) => ({
        value: state.value,
        chosen: state.chosen,
        count: state.value.length,
        summary: state.chosen.length ? `, ${state.chosen.length} selected: ${state.chosen.join(", ")}` : "",
      }),
      attrs: (state) => ({
        "data-empty": state.value.length ? undefined : "",
        "data-count": String(state.value.length),
      }),
      bind: (el) => {
        const measure = () => {
          const inner = el.querySelector<HTMLElement>("[data-filter-values-row]")
          el.style.setProperty("--filter-values-width", `${inner ? inner.offsetWidth : 0}px`)
        }
        const resize = new ResizeObserver(measure)
        const watch = () => {
          resize.disconnect()
          const inner = el.querySelector("[data-filter-values-row]")
          if (inner) resize.observe(inner)
          measure()
        }
        watch()
        const children = new MutationObserver(watch)
        children.observe(el, { childList: true })
        return () => {
          resize.disconnect()
          children.disconnect()
        }
      },
    }),
  }),
  agent: { actions: [] },
})

type FilterBarOptions = {
  /** Runs when the reset button is pressed, before the filters inside clear themselves. `details.cancel()` stops it. */
  onReset?: (value: null, details: ChangeDetails<"reset-press" | "imperative">) => void
}

type FilterBarState = {
  /** How many filters inside have something chosen. */
  active: number
}

const filterBar = definePrimitive({
  name: "filter-bar",
  options: { onReset: "callback" },
  state: (_options: FilterBarOptions): FilterBarState => ({ active: 0 }),
  controlled: ["active"],
  api: (context) => {
    let root: HTMLElement | undefined
    return {
      /** @internal Where the filters are. */
      attach(el: HTMLElement) {
        root = el
        const count = () => {
          const active = el.querySelectorAll('[data-slot="filter"][data-active]').length
          if (active !== context.store.get().active) context.store.set({ active })
        }
        count()
        const observer = new MutationObserver(count)
        observer.observe(el, { subtree: true, childList: true, attributes: true, attributeFilter: ["data-active"] })
        return () => {
          observer.disconnect()
          root = undefined
        }
      },
      /** Clears every filter in the bar. */
      reset(event?: Event) {
        if (!root || !context.store.get().active) return false
        if (dispatch(context, "onReset", null, { reason: event ? "reset-press" : "imperative", event })) return false
        for (const el of root.querySelectorAll('[data-slot="filter"][data-active]')) el.dispatchEvent(new CustomEvent("filter-reset"))
        return true
      },
    }
  },
  slots: (slot) => ({
    root: slot<{}, { active: number }>({
      role: "group",
      state: (state) => ({ active: state.active }),
      attrs: (state) => ({ "data-active": state.active ? "" : undefined, "data-count": String(state.active) }),
      bind: (el, part) => part.api.attach(el),
    }),
    /* Stays in the page so it can slide out; while nothing is chosen it is inert and hidden. */
    reset: slot<{}, { active: number }>({
      role: "button",
      focus: "native",
      state: (state) => ({ active: state.active }),
      attrs: (state) => ({
        type: "button",
        "data-hidden": state.active ? undefined : "",
        "aria-hidden": state.active ? undefined : "true",
        inert: state.active ? undefined : "",
      }),
      press: ({ api }, event) => api.reset(event),
    }),
  }),
  agent: { actions: ["reset"] },
})

export { FILTER_CLEAR, filter, filterBar, filterValues, type FilterBarOptions, type FilterOption, type FilterOptions, type FilterState }

/* A form, as a UI SDK primitive. UI SDK ships Field (a label, a control, a description and its
   errors, with the browser's validation shown in the page) but no form around the fields. This is
   that form, defined with UI SDK's core: the same definition renders in React, Vue, Svelte, Solid
   and web components.

   It does what Field leaves to the page: it runs your `submit` once every field passes, keeps the
   status of that submission (submitting, done, refused), and puts the errors your server returns
   onto the fields they belong to. It puts them there through the browser's own validity
   (`setCustomValidity`), so UI SDK's Field shows them exactly as it shows its own: in its
   FieldError, with `aria-invalid` and focus on the first one. Editing a field clears its error. */

import { announce, type ChangeDetails, createChange, definePrimitive } from "@ui-sdk/core"

type FormStatus = "idle" | "submitting" | "success" | "error"

/** What `submit` may return: messages for named fields, and one line for the whole form. */
type FormResult = { errors?: Record<string, string>; message?: string } | void | undefined

// None of these reasons is in UI SDK's shared vocabulary.
type FormStatusReason = "submit" | "resolve" | "reject" | "edit" | "reset"

type FormOptions = {
  /** Runs when the form is submitted and every field is valid, with the form's data. Return or
      resolve to `{ errors: { email: "…" } }` to mark fields invalid with your messages, and
      `{ message: "…" }` for one line about the whole form. Throwing or rejecting refuses the
      submission with the error's message. Without it the form submits the browser's way. */
  submit?: (data: FormData, details: { event?: Event }) => FormResult | Promise<FormResult>
  /** Called as the submission moves between `idle`, `submitting`, `success` and `error`. */
  onStatusChange?: (status: FormStatus, details: ChangeDetails<FormStatusReason>) => void
  /** Clears the fields once a submission succeeds. The success status stays until the next edit. */
  resetOnSuccess?: boolean
}

type FormState = {
  status: FormStatus
  /** The line for the whole form from the last submission. */
  message: string
}

type Control = HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement

const isControl = (el: unknown): el is Control =>
  el instanceof HTMLInputElement || el instanceof HTMLSelectElement || el instanceof HTMLTextAreaElement

const form = definePrimitive({
  name: "form",
  options: { submit: "action", onStatusChange: "callback", resetOnSuccess: "boolean" },
  state: (_options: FormOptions): FormState => ({ status: "idle", message: "" }),
  controlled: ["status", "message"],
  api: (context) => {
    const change = createChange(context)
    let root: HTMLFormElement | null = null
    /* A reset this form starts itself keeps the success it follows. */
    let resetting = false
    /* Only the latest submission may write its outcome. */
    let run = 0

    const controls = () => (root ? [...root.elements].filter(isControl) : [])
    const clearErrors = () => controls().forEach((control) => control.validity.customError && control.setCustomValidity(""))
    const setStatus = (status: FormStatus, reason: FormStatusReason, message: string, event?: Event) => {
      context.store.set({ message })
      change("status", status, { reason, event })
    }

    return {
      /** Connects the form element. The root part does this; it returns the cleanup. */
      attach(el: HTMLFormElement) {
        root = el
        /* Capture, so the error is cleared before the field reads the control's validity again. */
        const edit = (event: Event) => {
          const target = event.target
          if (isControl(target) && target.validity.customError) target.setCustomValidity("")
          const { status } = context.store.get()
          if (status === "success" || status === "error") setStatus("idle", "edit", "", event)
        }
        el.addEventListener("input", edit, true)
        el.addEventListener("change", edit, true)
        return () => {
          el.removeEventListener("input", edit, true)
          el.removeEventListener("change", edit, true)
          root = null
        }
      },
      /** Submits the form the way its submit button would: fields are checked first. */
      submit() {
        root?.requestSubmit()
      },
      /** Puts every field back to its default and the form back to idle. */
      reset() {
        root?.reset()
      },
      /** Handles the form's submit event. */
      async handle(event: SubmitEvent) {
        const { submit, resetOnSuccess } = context.options()
        if (!submit || !root) return
        event.preventDefault()
        if (context.store.get().status === "submitting") return
        const el = root
        const mine = ++run
        clearErrors()
        setStatus("submitting", "submit", "", event)
        let result: FormResult
        try {
          result = await submit(new FormData(el, event.submitter), { event })
        } catch (error) {
          if (mine !== run) return
          const message = error instanceof Error ? error.message : String(error ?? "")
          setStatus("error", "reject", message)
          if (message) announce(message, { priority: "assertive" })
          return
        }
        if (mine !== run) return
        const errors = Object.entries(result?.errors ?? {}).filter(([, text]) => text)
        if (errors.length) {
          for (const [name, text] of errors) {
            const named = el.elements.namedItem(name)
            const target = named instanceof RadioNodeList ? named[0] : named
            if (isControl(target)) target.setCustomValidity(text)
          }
          setStatus("error", "reject", result?.message ?? "")
          /* The browser reports the fields now invalid; UI SDK's Field shows each error in the page
             and the first invalid field takes focus. */
          el.reportValidity()
          return
        }
        setStatus("success", "resolve", result?.message ?? "")
        if (result?.message) announce(result.message)
        if (resetOnSuccess) {
          resetting = true
          el.reset()
          resetting = false
        }
      },
      /** Handles the form's reset event. */
      onReset(event: Event) {
        clearErrors()
        run++
        if (resetting) return
        if (context.store.get().status !== "idle") setStatus("idle", "reset", "", event)
      },
    }
  },
  slots: (slot) => ({
    root: slot<{}, { status: FormStatus }>({
      state: (state) => ({ status: state.status }),
      attrs: (state) => ({
        "data-status": state.status,
        "aria-busy": state.status === "submitting" ? "true" : undefined,
      }),
      on: {
        submit: (event, { api }) => void api.handle(event as SubmitEvent),
        reset: (event, { api }) => api.onReset(event),
      },
      bind: (el, part) => (el instanceof HTMLFormElement ? part.api.attach(el) : undefined),
    }),
    /* The submit button. It stays focusable while the form submits, and ignores presses then. */
    submit: slot<{}, { status: FormStatus }>({
      role: "button",
      focus: "native",
      press: { none: "A submit button submits its form natively; the form's submit handler does the work." },
      state: (state) => ({ status: state.status }),
      attrs: (state) => ({
        type: "submit",
        "data-status": state.status,
        "aria-disabled": state.status === "submitting" ? "true" : undefined,
      }),
      on: {
        click: (event, { store }) => {
          if (store.get().status === "submitting") event.preventDefault()
        },
      },
    }),
    /* One line about the whole submission: what happened, or why it was refused. */
    status: slot<{}, { status: FormStatus; message: string }>({
      role: (state) => (state.status === "error" ? "alert" : "status"),
      roles: ["alert", "status"],
      present: (state) => state.message !== "",
      state: (state) => ({ status: state.status, message: state.message }),
      attrs: (state) => ({ "data-status": state.status }),
    }),
  }),
  agent: { actions: ["submit", "reset"] },
})

export { form, type FormOptions, type FormResult, type FormStatus }

/* A field with things around it, as a UI SDK primitive: icons, text, buttons and counters on either
   side of an input, or above and below a textarea. UI SDK's own InputGroup (in `@ui-sdk/react/input`)
   holds an Input and a clear button on one line; this one adds shadcn/ui's addons on four sides, a
   textarea, and a character count.

   The control inside is UI SDK's own Input or Textarea (Keyframery's, in the styled file); this
   primitive never binds to it. It listens as events bubble to the group instead, and keeps what the
   group's look needs in state: whether the control is focused, filled, invalid or disabled, how
   many characters it holds and its `maxLength`. Pressing an addon's text or icon focuses the control. */

import { definePrimitive } from "@ui-sdk/core"

type Align = "inline-start" | "inline-end" | "block-start" | "block-end"

type InputGroupState = {
  /** Keyboard or pointer focus is in the control (not in a button of the group). */
  focused: boolean
  /** Focus in the control came from the keyboard, so the ring shows. */
  focusVisible: boolean
  filled: boolean
  /** Characters in the control. */
  length: number
  /** The control's `maxLength`, or 0 when it has none. */
  max: number
  invalid: boolean
  disabled: boolean
  /** The control is a textarea. */
  multiline: boolean
}

const CONTROL = "input, textarea"

function controlOf(root: Element | null) {
  return root?.querySelector<HTMLInputElement | HTMLTextAreaElement>(CONTROL) ?? null
}

function read(control: HTMLInputElement | HTMLTextAreaElement | null): Partial<InputGroupState> {
  if (!control) return {}
  return {
    filled: control.value.length > 0,
    length: control.value.length,
    max: control.maxLength > 0 ? control.maxLength : 0,
    invalid: control.getAttribute("aria-invalid") === "true",
    disabled: control.disabled,
    multiline: control instanceof HTMLTextAreaElement,
  }
}

/* Writes only what changed, so a keystroke that changes nothing the group shows renders nothing. */
function same(a: Partial<InputGroupState>, b: InputGroupState) {
  return (Object.keys(a) as (keyof InputGroupState)[]).every((key) => a[key] === b[key])
}

const inputGroup = definePrimitive({
  name: "input-group",
  state: (): InputGroupState => ({
    focused: false,
    focusVisible: false,
    filled: false,
    length: 0,
    max: 0,
    invalid: false,
    disabled: false,
    multiline: false,
  }),
  controlled: ["invalid", "disabled", "multiline", "max"],
  api: (context) => {
    const { store } = context
    const update = (next: Partial<InputGroupState>) => {
      if (!same(next, store.get())) store.set(next)
    }
    return {
      /** Reads the control again: its text, length, limit and whether it is invalid or disabled. */
      refresh(root: HTMLElement) {
        update(read(controlOf(root)))
      },
      focusIn(event: FocusEvent, root: HTMLElement) {
        const target = event.target as Element
        const inControl = target.matches(CONTROL)
        update({ ...read(controlOf(root)), focused: inControl, focusVisible: inControl && target.matches(":focus-visible") })
      },
      focusOut(event: FocusEvent, root: HTMLElement) {
        const next = event.relatedTarget as Element | null
        const stillIn = !!next && root.contains(next) && next.matches(CONTROL)
        update({ ...read(controlOf(root)), focused: stillIn, focusVisible: stillIn && store.get().focusVisible })
      },
      /** Moves focus into the control, as a press on an addon's text or icon does. */
      focusControl(from: Element) {
        const control = controlOf(from.closest('[data-slot="input-group"]'))
        if (control && !control.disabled) control.focus()
      },
    }
  },
  slots: (slot) => ({
    root: slot<{}, InputGroupState>({
      role: "group",
      state: (state) => state,
      attrs: (state) => ({
        "data-focused": state.focused ? "" : undefined,
        "data-focus-visible": state.focusVisible ? "" : undefined,
        "data-filled": state.filled ? "" : undefined,
        "data-invalid": state.invalid ? "" : undefined,
        "data-disabled": state.disabled ? "" : undefined,
        "data-multiline": state.multiline ? "" : undefined,
      }),
      on: {
        focusin: (event, { el, api }) => el && api.focusIn(event as FocusEvent, el),
        focusout: (event, { el, api }) => el && api.focusOut(event as FocusEvent, el),
        input: (_event, { el, api }) => el && api.refresh(el),
        change: (_event, { el, api }) => el && api.refresh(el),
      },
      bind: (el, part) => {
        part.api.refresh(el)
        /* A field or form can flip `aria-invalid` and `disabled` without an event. */
        const observer = new MutationObserver(() => part.api.refresh(el))
        observer.observe(el, { subtree: true, attributes: true, attributeFilter: ["aria-invalid", "disabled", "maxlength"] })
        return () => observer.disconnect()
      },
    }),
    /* Icons, text, buttons or a count beside or around the control. */
    addon: slot<{ align?: Align }, { align: Align; focused: boolean; filled: boolean }>({
      role: "group",
      props: { align: "string" },
      state: (state, part) => ({ align: part.props.align ?? "inline-start", focused: state.focused, filled: state.filled }),
      attrs: (_state, part) => ({ "data-align": part.props.align ?? "inline-start" }),
      on: {
        /* Text and icons in an addon focus the control, like a label. Buttons and links keep their own press. */
        click: (event, { el, api }) => {
          const target = event.target as Element
          if (!el || target.closest("button, a, input, textarea, select, [role=button]")) return
          api.focusControl(el)
        },
      },
    }),
    /* Plain words in an addon: a unit, a prefix like "https://", a hint. */
    text: slot({}),
    /* How many characters the control holds, or how many are left under its `maxLength`. */
    count: slot<{ show?: "used" | "left" }, { value: number; length: number; max: number; near: boolean }>({
      props: { show: "string" },
      state: (state, part) => {
        const left = state.max ? state.max - state.length : 0
        return {
          value: part.props.show === "left" && state.max ? left : state.length,
          length: state.length,
          max: state.max,
          near: state.max > 0 && left <= Math.max(1, Math.round(state.max * 0.1)),
        }
      },
      attrs: (state) => {
        const left = state.max ? state.max - state.length : 0
        return {
          "data-near-limit": state.max > 0 && left <= Math.max(1, Math.round(state.max * 0.1)) ? "" : undefined,
          "data-at-limit": state.max > 0 && left <= 0 ? "" : undefined,
        }
      },
    }),
  }),
  /* Expose validation and control metadata; the Input or Textarea owns its value and actions. */
  agent: { actions: [] },
})

export { type Align as InputGroupAlign, inputGroup }

/* Items, as UI SDK primitives. UI SDK ships no item, so these are defined with its core: the same
   definitions render in React, Vue, Svelte, Solid and web components.

   An `item` is one row of content: media, a title, a description and actions. It can stay a plain
   row or become a link or a button with `render`. `itemGroup` is a list of them. An item inside a
   group becomes a list item; outside one it has no role, so it never claims to be in a list.

   The item reports `data-hovered` while a pointer is over it, so a group can move one highlight
   from row to row (a script's pointer events count too, which CSS `:hover` cannot see). */

import { definePrimitive } from "@ui-sdk/core"

import { bindAgentContent } from "@/components/core/agent-content"

type ItemVariant = "default" | "outline" | "muted"
type ItemSize = "default" | "sm"
type ItemMediaVariant = "default" | "icon" | "image"

type ItemOptions = {
  /** The surface: `"default"` is bare, `"outline"` has a hairline, `"muted"` a soft fill. */
  variant?: ItemVariant
  /** `"sm"` tightens the padding and the gap. */
  size?: ItemSize
}

type ItemState = {
  content: string
  variant: ItemVariant
  size: ItemSize
  /** A pointer is over the item. */
  hovered: boolean
  /** The item sits inside an item group, so it is one of its list items. */
  listed: boolean
}

const item = definePrimitive({
  name: "item",
  options: { variant: "string", size: "string" },
  state: (options: ItemOptions): ItemState => ({
    content: "",
    variant: options.variant ?? "default",
    size: options.size ?? "default",
    hovered: false,
    listed: false,
  }),
  sync: (options) => ({ variant: options.variant ?? "default", size: options.size ?? "default" }),
  controlled: ["content"],
  api: (context) => ({
    /** Marks the item hovered or not. A pointer does this; a demo or a test can too. */
    hover(hovered: boolean) {
      if (context.store.get().hovered !== hovered) context.store.set({ hovered })
    },
  }),
  slots: (slot) => ({
    root: slot<{}, { variant: ItemVariant; size: ItemSize; hovered: boolean }>({
      role: (state) => (state.listed ? "listitem" : undefined),
      roles: ["listitem"],
      state: (state) => ({ variant: state.variant, size: state.size, hovered: state.hovered }),
      attrs: (state) => ({
        "data-variant": state.variant,
        "data-size": state.size,
        "data-hovered": state.hovered ? "" : undefined,
      }),
      on: {
        pointerenter: (_event, { api }) => api.hover(true),
        pointerleave: (_event, { api }) => api.hover(false),
      },
      /* Whether it is in a list is a fact of the page, so it is read once the element is there.
         A row rendered as a link or a button keeps its own role: a list item role would hide it. */
      bind: (el, part) => {
        const interactive = el.matches("a[href], button, [role=button], [role=link]")
        const listed = !interactive && !!el.parentElement?.closest('[data-slot="item-group"]')
        if (part.store.get().listed !== listed) part.store.set({ listed })
        return bindAgentContent(el, (content) => part.store.set({ content }))
      },
    }),
    media: slot<{ variant?: ItemMediaVariant }, { variant: ItemMediaVariant }>({
      props: { variant: "string" },
      state: (_state, part) => ({ variant: part.props.variant ?? "default" }),
      attrs: (_state, part) => ({ "data-variant": part.props.variant ?? "default" }),
    }),
    content: slot({}),
    title: slot({}),
    description: slot({}),
    actions: slot({}),
    header: slot({}),
    footer: slot({}),
  }),
  /* Expose the item's title and description; its controls own their actions. */
  agent: { actions: [] },
})

/* A list of items. Its separators are UI SDK's Separator, composed in the renderer. */
const itemGroup = definePrimitive({
  name: "item-group",
  state: () => ({}),
  controlled: [],
  api: () => ({}),
  slots: (slot) => ({
    root: slot({ role: "list" }),
  }),
  agent: { actions: [] },
})

export { item, itemGroup, type ItemMediaVariant, type ItemOptions, type ItemSize, type ItemVariant }

/* Keyboard keys, as UI SDK primitives. UI SDK ships no kbd, so these are defined with its core:
   the same definitions render in React, Vue, Svelte, Solid and web components.

   `kbd` is one key. `kbdCombo` is a shortcut: a row of keys that can sink together (`pressed`) or
   follow the real keyboard (`listen`), each one sinking while it is held. */

import { definePrimitive } from "@ui-sdk/core"

import { bindAgentContent } from "@/components/core/agent-content"

const isApple = () => typeof navigator !== "undefined" && /Mac|iPhone|iPad|iPod/.test(navigator.platform || navigator.userAgent)

/* Names a combo takes, how they show, and how the keyboard reports the modifiers. */
const named: Record<string, { label: string | ((apple: boolean) => string); test?: (event: KeyboardEvent) => boolean }> = {
  mod: { label: (apple) => (apple ? "⌘" : "Ctrl"), test: (event) => (isApple() ? event.metaKey : event.ctrlKey) },
  meta: { label: "⌘", test: (event) => event.metaKey },
  cmd: { label: "⌘", test: (event) => event.metaKey },
  ctrl: { label: (apple) => (apple ? "⌃" : "Ctrl"), test: (event) => event.ctrlKey },
  shift: { label: "⇧", test: (event) => event.shiftKey },
  alt: { label: (apple) => (apple ? "⌥" : "Alt"), test: (event) => event.altKey },
  option: { label: "⌥", test: (event) => event.altKey },
  enter: { label: "↵" },
  escape: { label: "Esc" },
  esc: { label: "Esc" },
  backspace: { label: "⌫" },
  tab: { label: "⇥" },
  space: { label: "Space" },
  up: { label: "↑" },
  down: { label: "↓" },
  left: { label: "←" },
  right: { label: "→" },
}

/* `KeyboardEvent.key`, lower case, for each name that isn't a modifier. */
const eventKey: Record<string, string> = {
  enter: "enter",
  escape: "escape",
  esc: "escape",
  backspace: "backspace",
  tab: "tab",
  space: " ",
  up: "arrowup",
  down: "arrowdown",
  left: "arrowleft",
  right: "arrowright",
}

/** What a key is called on the keycap: "mod" is ⌘ on Apple platforms and Ctrl elsewhere. */
function keyLabel(key: string, apple = isApple()) {
  const entry = named[key.toLowerCase()]
  if (!entry) return key.length === 1 ? key.toUpperCase() : key
  return typeof entry.label === "function" ? entry.label(apple) : entry.label
}

type KbdOptions = {
  /** Draws the key pressed in. */
  pressed?: boolean
}

const kbd = definePrimitive({
  name: "kbd",
  options: { pressed: "boolean" },
  state: (options: KbdOptions) => ({ pressed: options.pressed ?? false, content: "" }),
  sync: (options) => ({ pressed: options.pressed ?? false }),
  controlled: ["pressed", "content"],
  api: () => ({}),
  slots: (slot) => ({
    root: slot<{}, { pressed: boolean }>({
      state: (state) => ({ pressed: state.pressed }),
      attrs: (state) => ({ "data-pressed": state.pressed ? "" : undefined }),
      bind: (el, part) => bindAgentContent(el, (content) => part.store.set({ content })),
    }),
  }),
  /* The keycap reports its pressed state without offering a keyboard action. */
  agent: { actions: [] },
})

type KbdComboOptions = {
  /** The keys, in order: names like "mod", "shift", "alt", "enter", "escape", or a character. */
  keys?: string[]
  /** Sinks every key, one after another. */
  pressed?: boolean
  /** Sinks each key while it is held on the real keyboard. */
  listen?: boolean
}

type KbdComboState = {
  content: string
  keys: string[]
  pressed: boolean
  /** The names in `keys` the keyboard is holding now. */
  held: string[]
  /** False on the server and for the first client render, so the page hydrates without a mismatch. */
  apple: boolean
}

const kbdCombo = definePrimitive({
  name: "kbd-combo",
  options: { keys: "list", pressed: "boolean", listen: "boolean" },
  state: (options: KbdComboOptions): KbdComboState => ({
    content: "",
    keys: options.keys ?? [],
    pressed: options.pressed ?? false,
    held: [],
    apple: false,
  }),
  sync: (options) => ({ keys: options.keys ?? [], pressed: options.pressed ?? false }),
  controlled: ["keys", "pressed", "held", "content"],
  api: (context) => {
    const down = new Set<string>()
    const setHeld = (held: string[]) => {
      const now = context.store.get().held
      if (held.length !== now.length || held.some((name, index) => name !== now[index])) context.store.set({ held })
    }
    const read = (event: KeyboardEvent | null) =>
      setHeld(
        context.store.get().keys.filter((key) => {
          const name = key.toLowerCase()
          const modifier = named[name]?.test
          return event && modifier ? modifier(event) : down.has(eventKey[name] ?? name)
        }),
      )
    return {
      /** Follows the keyboard while `listen` is on. Returns the function that stops it. */
      watch() {
        context.store.set({ apple: isApple() })
        const onDown = (event: KeyboardEvent) => {
          if (!context.options().listen) return
          down.add(event.key.toLowerCase())
          read(event)
        }
        const onUp = (event: KeyboardEvent) => {
          if (!context.options().listen) return
          down.delete(event.key.toLowerCase())
          /* With Command held, browsers send no keyup for the other keys: let go of them with it. */
          if (event.key === "Meta") down.clear()
          read(event)
        }
        const onBlur = () => {
          down.clear()
          setHeld([])
        }
        window.addEventListener("keydown", onDown)
        window.addEventListener("keyup", onUp)
        window.addEventListener("blur", onBlur)
        return () => {
          window.removeEventListener("keydown", onDown)
          window.removeEventListener("keyup", onUp)
          window.removeEventListener("blur", onBlur)
        }
      },
    }
  },
  slots: (slot) => ({
    root: slot<{}, { pressed: boolean }>({
      state: (state) => ({ pressed: state.pressed }),
      attrs: (state) => ({
        "data-pressed": state.pressed ? "" : undefined,
        "aria-keyshortcuts": state.keys.length ? state.keys.join("+") : undefined,
      }),
      bind: (el, part) => {
        const stop = part.api.watch()
        const stopContent = bindAgentContent(el, (content) => part.store.set({ content }))
        return () => {
          stopContent()
          stop()
        }
      },
    }),
    key: slot<{ value: string }, { pressed: boolean; label: string }>({
      props: { value: "key" },
      state: (state, part) => ({
        pressed: state.pressed || state.held.includes(part.key),
        label: keyLabel(part.key, state.apple),
      }),
      attrs: (state, part) => ({ "data-pressed": state.pressed || state.held.includes(part.key) ? "" : undefined }),
    }),
  }),
  agent: { actions: [] },
})

export { kbd, kbdCombo, type KbdComboOptions, type KbdOptions, keyLabel }

/* A marker, as a UI SDK primitive. UI SDK ships no marker, so it is defined with its core: the same
   definition renders in React, Vue, Svelte, Solid and web components.

   A marker is a short line inside a stream of content that says where you are or what happened:
   "Today" between two days of messages, "Ana joined", "Searching the knowledge base". It can sit
   between two rules (`separator`) or over one (`border`). A marker that reports something as it
   happens is `live`: it becomes a status that screen readers read out when its text changes. While
   `pending`, the work it names is still running. */

import { definePrimitive } from "@ui-sdk/core"

import { bindAgentContent } from "@/components/core/agent-content"

type MarkerVariant = "default" | "separator" | "border"

type MarkerOptions = {
  /** `"separator"` draws a rule on each side of the content, `"border"` a rule under it. */
  variant?: MarkerVariant
  /** Reads the marker out when its text changes, as a status. */
  live?: boolean
  /** The work the marker names is still going on. */
  pending?: boolean
}

type MarkerState = { variant: MarkerVariant; live: boolean; pending: boolean; content: string }

const marker = definePrimitive({
  name: "marker",
  options: { variant: "string", live: "boolean", pending: "boolean" },
  state: (options: MarkerOptions): MarkerState => ({
    variant: options.variant ?? "default",
    live: options.live ?? false,
    pending: options.pending ?? false,
    content: "",
  }),
  sync: (options) => ({
    variant: options.variant ?? "default",
    live: options.live ?? false,
    pending: options.pending ?? false,
  }),
  controlled: ["pending", "live", "content"],
  api: () => ({}),
  slots: (slot) => ({
    root: slot<{}, { variant: MarkerVariant; pending: boolean }>({
      role: (state) => (state.live ? "status" : undefined),
      roles: ["status"],
      state: (state) => ({ variant: state.variant, pending: state.pending }),
      attrs: (state) => ({
        "data-variant": state.variant,
        "data-pending": state.pending ? "" : undefined,
        "aria-busy": state.live && state.pending ? "true" : undefined,
      }),
      bind: (el, part) => bindAgentContent(el, (content) => part.store.set({ content })),
    }),
    /* The icon repeats what the words say, so it is hidden from screen readers. */
    icon: slot<{}, { pending: boolean }>({
      state: (state) => ({ pending: state.pending }),
      attrs: (state) => ({ "aria-hidden": "true", "data-pending": state.pending ? "" : undefined }),
    }),
    content: slot<{}, { pending: boolean }>({
      state: (state) => ({ pending: state.pending }),
      attrs: (state) => ({ "data-pending": state.pending ? "" : undefined }),
    }),
  }),
  /* Agents read whether the work is pending; a marker has no actions. */
  agent: { actions: [] },
})

export { marker, type MarkerOptions, type MarkerVariant }

/* A chat's scroller, as a UI SDK primitive. UI SDK ships no message scroller, but its scroll area
   already keeps the end in view as content grows (`stickToEnd`) and has a "jump to latest" button
   (`ScrollAreaScrollToEnd`). So this primitive does only what the scroll area does not:

   - It remembers which messages were there when it first showed (`data-history` on their items),
     so the history loaded with the page sits still and only new arrivals play their entrance.
     Bubble, message and attachment read that mark too: see `enter`.
   - It counts the messages that arrive while the reader has scrolled away (`unread`), clears the
     count when they come back to the end, and can bring the view down when the person sends one.

   It follows the scroll area through its controller, passed as `scroller`. */

import { animateIn, type ChangeDetails, createChange, css, definePrimitive, elements } from "@ui-sdk/core"

/** What the scroller reads from the scroll area it follows: UI SDK's scroll-area controller. */
type MessageScrollerScroller = {
  scrollToEnd(options?: { behavior?: "instant" | "smooth" }): void
  isAtEnd(): boolean
  isSticking(): boolean
}

/* None of these is in the shared vocabulary: a message arrived while the reader was away, the
   reader asked for the end, the reader scrolled back down by themselves. */
type MessageScrollerUnreadReason = "item-arrived" | "scroll-to-end" | "scroll"

type MessageScrollerOptions = {
  /** The scroll area's controller, from `createScrollAreaController()`. */
  scroller?: MessageScrollerScroller
  /** How many messages arrived while the reader was away from the end. */
  unread?: number
  defaultUnread?: number
  onUnreadChange?: (unread: number, details: ChangeDetails<MessageScrollerUnreadReason>) => void
}

type MessageScrollerState = {
  unread: number
  /** False until the first frame after the scroller binds: what is there by then is history. */
  ready: boolean
  /** The items that were there when the scroller first showed. */
  history: string[]
}

/* Elements that have played their entrance. A binding can run again for the same element (React's
   strict mode, a re-render with new part props), and the entrance must not replay. */
const entered = new WeakSet<HTMLElement>()

/** Plays a part's entrance (`data-starting-style` for its first frame) once per element, unless it
    sits in a message that was already there when its message scroller first showed. */
function enter(el: HTMLElement) {
  if (entered.has(el)) return
  entered.add(el)
  if (el.closest("[data-history]")) return
  animateIn(el)
}

const messageScroller = definePrimitive({
  name: "message-scroller",
  options: { scroller: "value", unread: "number", defaultUnread: "number", onUnreadChange: "callback" },
  controlled: ["unread"],
  state: (options: MessageScrollerOptions): MessageScrollerState => ({
    unread: options.unread ?? options.defaultUnread ?? 0,
    ready: false,
    history: [],
  }),
  sync: (options) => (options.unread === undefined ? {} : { unread: options.unread }),
  api: (context) => {
    const change = createChange(context)
    /* Items already counted or followed, so a binding that runs twice (React's strict mode, a
       remount) never counts a message twice. */
    const arrived = new Set<string>()
    const scroller = () => context.options().scroller
    /* With `stickToEnd` the view follows growth after it happens, so "at the end" right after a
       message is added reads as sticking, not as the scroll position. */
    const following = () => {
      const s = scroller()
      return s ? s.isSticking() || s.isAtEnd() : true
    }

    return {
      /** Brings the view down to the newest message and clears the unread count. */
      scrollToEnd(event?: Event) {
        scroller()?.scrollToEnd({ behavior: "smooth" })
        if (context.store.get().unread) change("unread", 0, { reason: "scroll-to-end", event })
      },
      /** The root's binding: marks the history once the first frame is out, and clears the count
          when the reader scrolls back to the end. Scroll events do not bubble, so it listens in
          the capture phase. */
      watch(el: HTMLElement) {
        const frame = requestAnimationFrame(() => {
          context.store.set({ ready: true, history: elements(context, "item").map((item) => item.key) })
        })
        const onScroll = (event: Event) => {
          if (context.store.get().unread && scroller()?.isAtEnd()) change("unread", 0, { reason: "scroll", event })
        }
        el.addEventListener("scroll", onScroll, { capture: true, passive: true })
        return () => {
          cancelAnimationFrame(frame)
          el.removeEventListener("scroll", onScroll, { capture: true })
        }
      },
      /** An item's binding: a message that arrives after the first frame plays its entrance, counts
          as unread while the reader is away, or brings the view down when it is the person's own. */
      arrive(el: HTMLElement, key: string, follow: boolean | undefined) {
        if (!context.store.get().ready) {
          /* History: remembered, so a later binding of the same item never counts it. */
          arrived.add(key)
          entered.add(el)
        } else if (!arrived.has(key)) {
          arrived.add(key)
          if (follow) scroller()?.scrollToEnd({ behavior: "smooth" })
          else if (!following()) change("unread", context.store.get().unread + 1, { reason: "item-arrived" })
        }
        enter(el)
        return () => {
          /* Forget it once it has really left, so the same message can arrive again later. */
          requestAnimationFrame(() => {
            if (!el.isConnected) arrived.delete(key)
          })
        }
      },
    }
  },
  slots: (slot) => ({
    root: slot<{}, { unread: number }>({
      state: (state) => ({ unread: state.unread }),
      attrs: (state) => ({
        "data-unread": state.unread ? String(state.unread) : undefined,
        style: css({ "--message-scroller-unread": String(state.unread) }),
      }),
      bind: (el, part) => part.api.watch(el),
    }),
    item: slot<{ value: string; follow?: boolean }, { history: boolean }>({
      props: { value: "string", follow: "boolean" },
      state: (state, part) => ({ history: !state.ready || state.history.includes(part.key) }),
      attrs: (state, part) => ({
        "data-history": !state.ready || state.history.includes(part.key) ? "" : undefined,
      }),
      bind: (el, part) => part.api.arrive(el, part.key, part.props.follow),
    }),
    /* The words on the jump-to-latest button. */
    label: slot<{}, { unread: number }>({
      state: (state) => ({ unread: state.unread }),
      attrs: (state) => ({ "data-unread": state.unread ? String(state.unread) : undefined }),
    }),
  }),
  /* Keep the unread count readable even at zero; an agent can bring the view to the end. */
  agent: { actions: ["scrollToEnd"] },
})

export {
  enter,
  messageScroller,
  type MessageScrollerOptions,
  type MessageScrollerScroller,
  type MessageScrollerUnreadReason,
}

/* A chat message, as UI SDK primitives. UI SDK ships no message, so these are defined with its core:
   the same definitions render in React, Vue, Svelte, Solid and web components.

   `message` lays out one turn of a conversation: who sent it (avatar), a header (name, time), the
   content (bubbles, attachments) and a footer (read, edited). `align` puts your own messages on the
   other side. A message plays its entrance when it mounts, unless it was already there when its
   message scroller first showed. `messageGroup` stacks messages. */

import { definePrimitive } from "@ui-sdk/core"

import { bindAgentContent } from "@/components/core/agent-content"
import { enter } from "@/components/core/message-scroller"

type MessageOptions = {
  /** `"start"` for the other person, `"end"` for your own: the avatar and bubbles move across. */
  align?: "start" | "end"
}

type MessageState = { align: "start" | "end"; content: string }

const message = definePrimitive({
  name: "message",
  options: { align: "string" },
  state: (options: MessageOptions): MessageState => ({ align: options.align ?? "start", content: "" }),
  sync: (options) => ({ align: options.align ?? "start" }),
  controlled: ["align", "content"],
  api: () => ({}),
  slots: (slot) => ({
    root: slot<{}, Pick<MessageState, "align">>({
      state: (state) => ({ align: state.align }),
      attrs: (state) => ({ "data-align": state.align }),
      bind: (el, part) => {
        enter(el)
        return bindAgentContent(el, (content) => part.store.set({ content }))
      },
    }),
    avatar: slot({}),
    content: slot({}),
    header: slot({}),
    footer: slot({}),
  }),
  /* Messages are readable entries; actions belong to the controls they contain. */
  agent: { actions: [] },
})

const messageGroup = definePrimitive({
  name: "message-group",
  state: () => ({}),
  controlled: [],
  api: () => ({}),
  slots: (slot) => ({
    root: slot({}),
  }),
  agent: { actions: [] },
})

export { message, messageGroup, type MessageOptions }

/* A native <select>, as a UI SDK primitive. UI SDK ships a custom Select; this one keeps the
   browser's own picker (the wheel on a phone, the system menu on a desktop) and adds what a styled
   one needs: the value in state, a change callback with a reason, the label of the chosen option
   for a value part that can animate, and state attributes for the look.

   Parts: `root` (the wrapper), `control` (the <select>), `value` (the chosen option's label, drawn
   over the select), `icon` (the chevron), `option` and `optgroup`. */

import { type ChangeDetails, createChange, definePrimitive, elements } from "@ui-sdk/core"

// "input-change" isn't in the shared vocabulary: the browser reports a native pick as a `change` event.
type NativeSelectValueChangeReason = "input-change" | "imperative"

type NativeSelectOptions = {
  /** The chosen option's value, for a controlled select. */
  value?: string
  /** The value it starts with. */
  defaultValue?: string
  /** Called when the chosen option changes: picked in the browser's menu (`"input-change"`) or set from code (`"imperative"`). `details.cancel()` keeps the old one. */
  onValueChange?: (value: string, details: ChangeDetails<NativeSelectValueChangeReason>) => void
  /** `"sm"` is 32px tall, `"default"` 36px. */
  size?: "sm" | "default"
  /** Disables the select. */
  disabled?: boolean
  /** Marks the value as wrong: the select gets `aria-invalid`. */
  invalid?: boolean
}

type NativeSelectState = {
  /** Null until the select is in the page and the browser has said which option it shows. */
  value: string | null
  /** The chosen option's text. */
  label: string
  /** The label before the last change, so a value part can show it leaving. */
  previous: string
  /** Counts changes, so the value part can replay its motion on each one. */
  changes: number
  size: "sm" | "default"
  disabled: boolean
  invalid: boolean
}

const optionLabel = (select: HTMLSelectElement) => select.selectedOptions[0]?.text.trim() ?? ""

const nativeSelect = definePrimitive({
  name: "native-select",
  options: {
    value: "string",
    defaultValue: "string",
    onValueChange: "callback",
    size: "string",
    disabled: "boolean",
    invalid: "boolean",
  },
  controlled: ["value"],
  state: (options: NativeSelectOptions): NativeSelectState => ({
    value: options.value ?? options.defaultValue ?? null,
    label: "",
    previous: "",
    changes: 0,
    size: options.size ?? "default",
    disabled: options.disabled ?? false,
    invalid: options.invalid ?? false,
  }),
  sync: (options) => ({
    ...(options.value === undefined ? {} : { value: options.value }),
    size: options.size ?? "default",
    disabled: options.disabled ?? false,
    invalid: options.invalid ?? false,
  }),
  api: (context) => {
    const change = createChange(context)
    const { store } = context
    const control = () => context.element("control") as HTMLSelectElement | null

    /* The select shows what state says, and state keeps the label of what it shows. A new label
       after the first one counts as a change, from a pick, from code or from a controlled value. */
    const show = () => {
      const select = control()
      if (!select) return
      const { value, label } = store.get()
      if (value === null) {
        store.set({ value: select.value, label: optionLabel(select) })
        return
      }
      if (select.value !== value) select.value = value
      const next = optionLabel(select)
      if (next !== label) store.set(label ? { label: next, previous: label, changes: store.get().changes + 1 } : { label: next })
    }

    return {
      show,
      /** Chooses the option with this value. */
      setValue(value: string) {
        return change("value", value, { reason: "imperative" })
      },
      /** Handles a pick in the browser's menu. A refused or controlled change puts the old option back. */
      pick(event: Event) {
        const select = event.target as HTMLSelectElement
        change("value", select.value, { reason: "input-change", event })
        show()
      },
      focus() {
        control()?.focus()
      },
      /** The options on the page, for an agent. */
      items() {
        return elements<{ value: string }>(context, "option").map((option) => ({
          value: option.key,
          label: option.el.textContent?.trim() || option.key,
        }))
      },
    }
  },
  slots: (slot) => ({
    root: slot<{}, { disabled: boolean; invalid: boolean }>({
      state: (state) => ({ disabled: state.disabled, invalid: state.invalid }),
      attrs: (state) => ({
        "data-size": state.size,
        "data-disabled": state.disabled ? "" : undefined,
        "data-invalid": state.invalid ? "" : undefined,
      }),
    }),
    control: slot<{}, { value: string | null; disabled: boolean; invalid: boolean }>({
      state: (state) => ({ value: state.value, disabled: state.disabled, invalid: state.invalid }),
      attrs: (state) => ({
        "data-size": state.size,
        disabled: state.disabled ? "" : undefined,
        "aria-invalid": state.invalid ? "true" : undefined,
        "data-placeholder": state.value === "" ? "" : undefined,
      }),
      on: { change: (event, { api }) => api.pick(event) },
      bind: (_el, part) => {
        part.api.show()
        return part.store.subscribe(() => part.api.show())
      },
    }),
    value: slot<{}, { label: string; previous: string; changes: number; placeholder: boolean }>({
      state: (state) => ({
        label: state.label,
        previous: state.previous,
        changes: state.changes,
        placeholder: state.value === "",
      }),
      attrs: (state) => ({
        "aria-hidden": "true",
        "data-placeholder": state.value === "" ? "" : undefined,
        "data-changed": state.changes ? "" : undefined,
      }),
    }),
    icon: slot<{}, { changes: number }>({
      state: (state) => ({ changes: state.changes }),
      attrs: () => ({ "aria-hidden": "true" }),
    }),
    option: slot<{ value: string }>({
      props: { value: "string" },
      attrs: (_state, part) => ({ value: part.key }),
    }),
    optgroup: slot({}),
  }),
  /* The value is always one of its options. */
  agent: { actions: ["setValue"], closed: true, items: (api) => api.items() },
})

export { nativeSelect, type NativeSelectOptions, type NativeSelectValueChangeReason }

/* A questionnaire: one question at a time, as a UI SDK primitive. UI SDK ships none, so it is
   defined with its core: the same definition renders in React, Vue, Svelte, Solid and web components.

   It owns the ordered items, the active item, the answers, which items were skipped or failed
   validation, progress, and moving forward and back (buttons, arrow keys, Enter, Mod+Enter, and
   letter or number shortcuts for the answers). The answer controls themselves are UI SDK's radio
   group, checkbox group and input, composed by the renderer and controlled from this state: the
   group's `onValueChange` calls `answer` here. The root is a form; the last item submits it.

   Shape and keys follow shadcn's Questionnaire. Keys with no APG rule: Enter on a chosen answer
   goes on; ←/→ outside a radio or text field go back and on; Mod+Enter goes on from anywhere and
   submits on the last item. */

import { type ChangeDetails, createChange, css, definePrimitive, dispatch, idPart } from "@ui-sdk/core"

type QuestionnaireChoiceDefinition = string | { value: string; disabled?: boolean }

type QuestionnaireItemDefinition = {
  /** Unique; also the native form field name of its answers. */
  name: string
  /** Needs an answer to go on, and can't be skipped. */
  required?: boolean
  /** Answers with checkboxes instead of radios. */
  multiple?: boolean
  /** Left out of progress and navigation. */
  disabled?: boolean
  /** The choices' values in order, for shortcuts. */
  choices?: readonly QuestionnaireChoiceDefinition[]
}

/** A radio item's answer is a string (a choice's value or typed text); a multiple item's a list. */
type QuestionnaireAnswer = string | string[]
type QuestionnaireValue = Record<string, QuestionnaireAnswer>
type QuestionnaireItemStatus = "unanswered" | "answered" | "skipped"

/* "next-press", "previous-press", "skip-press", "submit-press" and "validation" aren't in the shared vocabulary. */
type QuestionnaireItemChangeReason = "next-press" | "previous-press" | "skip-press" | "submit-press" | "keyboard" | "validation" | "imperative"
/* "shortcut-key" and "skip-press" aren't in the shared vocabulary. */
type QuestionnaireValueChangeReason = "item-press" | "input-change" | "shortcut-key" | "skip-press" | "imperative"

type QuestionnaireOptions = {
  /** The items, in order. Progress, navigation and shortcuts read them. */
  items?: readonly QuestionnaireItemDefinition[]
  /** The active item's name, to control it. */
  item?: string
  /** The item active at first. Defaults to the first enabled one. */
  defaultItem?: string
  onItemChange?: (item: string, details: ChangeDetails<QuestionnaireItemChangeReason>) => void
  /** The answers by item name, to control them. */
  value?: QuestionnaireValue
  /** The answers at first. */
  defaultValue?: QuestionnaireValue
  onValueChange?: (value: QuestionnaireValue, details: ChangeDetails<QuestionnaireValueChangeReason>) => void
  /** Gives each fixed choice a key: "letters" (A, B, C) or "numbers" (1, 2, 3). */
  shortcuts?: "letters" | "numbers"
  /** Called with the answers when the form submits after every item is valid. */
  onComplete?: (value: QuestionnaireValue, details: { reason: string; event?: Event }) => void
}

type QuestionnaireState = {
  items: readonly QuestionnaireItemDefinition[]
  item: string | null
  value: QuestionnaireValue
  skipped: string[]
  invalid: string[]
  shortcuts: "letters" | "numbers" | undefined
}

const enabledOf = (state: Pick<QuestionnaireState, "items">) => state.items.filter((item) => !item.disabled)
const definitionOf = (state: QuestionnaireState, name: string) => state.items.find((item) => item.name === name)
const activeOf = (state: QuestionnaireState) => state.item ?? enabledOf(state)[0]?.name ?? null
const filled = (answer: QuestionnaireAnswer | undefined) =>
  Array.isArray(answer) ? answer.length > 0 : typeof answer === "string" && answer.trim() !== ""
const statusOf = (state: QuestionnaireState, name: string): QuestionnaireItemStatus =>
  filled(state.value[name]) ? "answered" : state.skipped.includes(name) ? "skipped" : "unanswered"
const choiceValue = (choice: QuestionnaireChoiceDefinition) => (typeof choice === "string" ? choice : choice.value)
const choiceDisabled = (choice: QuestionnaireChoiceDefinition) => typeof choice !== "string" && !!choice.disabled

/* The key for a choice: its place among the item's enabled choices. */
function shortcutOf(state: QuestionnaireState, name: string, value: string) {
  if (!state.shortcuts) return undefined
  const choices = (definitionOf(state, name)?.choices ?? []).filter((choice) => !choiceDisabled(choice))
  const index = choices.findIndex((choice) => choiceValue(choice) === value)
  if (index < 0 || index > 25) return undefined
  return state.shortcuts === "numbers" ? (index < 9 ? String(index + 1) : undefined) : String.fromCharCode(65 + index)
}

const position = (state: QuestionnaireState, name: string) => {
  const enabled = enabledOf(state)
  const at = enabled.findIndex((item) => item.name === name)
  const active = enabled.findIndex((item) => item.name === activeOf(state))
  return at < active ? "before" : at === active ? "active" : "after"
}

const ids = (id: string, name: string) => ({
  title: `${id}-${idPart(name)}-title`,
  description: `${id}-${idPart(name)}-description`,
  error: `${id}-${idPart(name)}-error`,
})

type NameProps = { name: string }

const questionnaire = definePrimitive({
  name: "questionnaire",
  options: {
    items: "value",
    item: "string",
    defaultItem: "string",
    onItemChange: "callback",
    value: "value",
    defaultValue: "value",
    onValueChange: "callback",
    shortcuts: "string",
    onComplete: "callback",
  },
  controlled: ["item", "value"],
  state: (options: QuestionnaireOptions): QuestionnaireState => ({
    items: options.items ?? [],
    item: options.item ?? options.defaultItem ?? null,
    value: options.value ?? options.defaultValue ?? {},
    skipped: [],
    invalid: [],
    shortcuts: options.shortcuts,
  }),
  sync: (options) => ({
    items: options.items ?? [],
    shortcuts: options.shortcuts,
    ...(options.item === undefined ? {} : { item: options.item }),
    ...(options.value === undefined ? {} : { value: options.value }),
  }),
  api: (context) => {
    const { store } = context
    const change = createChange(context)
    let focusTimer: ReturnType<typeof setTimeout> | undefined
    context.onDestroy(() => clearTimeout(focusTimer))

    const root = () => context.element("root") as HTMLFormElement | undefined
    const itemEl = (name: string) => context.element("item", name) as HTMLElement | undefined
    const focusInside = () => {
      const el = root()
      return !!el && (el.contains(document.activeElement) || document.activeElement === document.body)
    }
    /* After the attributes have moved (inert comes off the new item), so focus can land. */
    const later = (run: () => void) => {
      clearTimeout(focusTimer)
      focusTimer = setTimeout(run, 0)
    }
    const firstControl = (name: string) =>
      itemEl(name)?.querySelector<HTMLElement>(
        '[role=radio][tabindex="0"], [role=radio]:not([tabindex="-1"]), [role=checkbox], input:not([type=hidden]):not([aria-hidden=true]), textarea',
      )

    const setInvalid = (name: string, invalid: boolean) => {
      const list = store.get().invalid
      if (invalid === list.includes(name)) return
      store.set({ invalid: invalid ? [...list, name] : list.filter((n) => n !== name) })
    }
    const isValid = (name: string) => {
      const state = store.get()
      return !definitionOf(state, name)?.required || filled(state.value[name])
    }

    const goTo = (name: string, reason: QuestionnaireItemChangeReason, event?: Event) => {
      const had = focusInside()
      const moved = change("item", name, { reason, event })
      if (moved && had) later(() => itemEl(name)?.focus())
      return moved
    }
    const neighbour = (step: 1 | -1) => {
      const state = store.get()
      const enabled = enabledOf(state)
      const at = enabled.findIndex((item) => item.name === activeOf(state))
      return enabled[at + step]?.name
    }
    /* Shows the error on an item that can't go on and puts focus on its first answer. */
    const refuse = (name: string) => {
      setInvalid(name, true)
      later(() => firstControl(name)?.focus())
      return false
    }

    const api = {
      /** Moves to the next item, once the active one is answered or optional. */
      next(event?: Event, reason: QuestionnaireItemChangeReason = "next-press") {
        const name = activeOf(store.get())
        if (!name) return false
        if (!isValid(name)) return refuse(name)
        const to = neighbour(1)
        return to ? goTo(to, reason, event) : false
      },
      /** Moves back one item. */
      previous(event?: Event, reason: QuestionnaireItemChangeReason = "previous-press") {
        const to = neighbour(-1)
        return to ? goTo(to, reason, event) : false
      },
      /** Leaves an optional item unanswered on purpose, and moves on. */
      skip(event?: Event) {
        const state = store.get()
        const name = activeOf(state)
        if (!name || definitionOf(state, name)?.required) return false
        if (state.value[name] !== undefined) {
          const { [name]: _dropped, ...rest } = state.value
          change("value", rest, { reason: "skip-press", event })
        }
        if (!store.get().skipped.includes(name)) store.set({ skipped: [...store.get().skipped, name] })
        setInvalid(name, false)
        const to = neighbour(1)
        return to ? goTo(to, "skip-press", event) : true
      },
      /** Goes straight to an item. */
      goTo(name: string, event?: Event) {
        return goTo(name, "imperative", event)
      },
      /** Sets an item's answer. */
      answer(name: string, answer: QuestionnaireAnswer, event?: Event, reason: QuestionnaireValueChangeReason = "item-press") {
        const state = store.get()
        const next = { ...state.value, [name]: answer }
        const changed = change("value", next, { reason, event })
        if (filled(answer)) {
          setInvalid(name, false)
          if (store.get().skipped.includes(name)) store.set({ skipped: store.get().skipped.filter((n) => n !== name) })
        }
        return changed
      },
      /** Checks every item; the first that needs an answer becomes active and shows its error. */
      validate(event?: Event) {
        const state = store.get()
        const failing = enabledOf(state).filter((item) => !isValid(item.name)).map((item) => item.name)
        store.set({ invalid: failing })
        if (failing.length === 0) return true
        if (activeOf(store.get()) !== failing[0]) change("item", failing[0], { reason: "validation", event })
        later(() => firstControl(failing[0])?.focus())
        return false
      },
      /** Validates, then submits the form. */
      submit(event?: Event) {
        if (!api.validate(event)) return false
        root()?.requestSubmit()
        return true
      },
      /** The Submit button's press: stops the native submit while something needs an answer. */
      submitPress(event?: Event) {
        if (!api.validate(event)) event?.preventDefault()
      },
      /** The form's submit, after validation: reports the answers. */
      completed(event: Event) {
        if (!api.validate(event)) {
          event.preventDefault()
          return
        }
        dispatch(context, "onComplete", store.get().value, { reason: "submit", event })
      },
      /** The root's keys. A handler of the page's that prevents the event turns them off. */
      keydown(event: KeyboardEvent) {
        if (event.defaultPrevented || event.isComposing) return
        const state = store.get()
        const name = activeOf(state)
        if (!name) return
        const target = event.target as HTMLElement
        const role = target.getAttribute("role")
        const typing = target.matches('input:not([type=radio]):not([type=checkbox]):not([type=hidden]), textarea, [contenteditable="true"]')
        const last = !neighbour(1)
        const goOn = () => (last ? api.submit(event) : api.next(event, "keyboard"))

        if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) {
          event.preventDefault()
          goOn()
          return
        }
        if (typing) {
          if (event.key === "Enter") {
            event.preventDefault()
            if (filled((target as HTMLInputElement).value)) goOn()
          }
          return
        }
        if (event.key === "Enter" && (role === "radio" || role === "checkbox")) {
          event.preventDefault()
          if (statusOf(state, name) === "answered") goOn()
          else refuse(name)
          return
        }
        if ((event.key === "ArrowLeft" || event.key === "ArrowRight") && role !== "radio") {
          const rtl = getComputedStyle(target).direction === "rtl"
          const back = (event.key === "ArrowLeft") !== rtl
          event.preventDefault()
          if (back) api.previous(event, "keyboard")
          else if (statusOf(state, name) !== "unanswered" || !definitionOf(state, name)?.required) api.next(event, "keyboard")
          return
        }
        if ((event.key === "ArrowDown" || event.key === "ArrowUp") && role === "checkbox") {
          const boxes = [...(itemEl(name)?.querySelectorAll<HTMLElement>("[role=checkbox]:not([data-disabled]), input:not([type=hidden])") ?? [])]
          const at = boxes.indexOf(target)
          const to = boxes[at + (event.key === "ArrowDown" ? 1 : -1)]
          if (to) {
            event.preventDefault()
            to.focus()
          }
          return
        }
        /* Answer shortcuts. */
        if (state.shortcuts && event.key.length === 1 && !event.metaKey && !event.ctrlKey && !event.altKey) {
          const definition = definitionOf(state, name)
          const choices = (definition?.choices ?? []).filter((choice) => !choiceDisabled(choice))
          const key = event.key.toUpperCase()
          const index = state.shortcuts === "numbers" ? Number(key) - 1 : key.charCodeAt(0) - 65
          const choice = choices[index]
          if (!choice || Number.isNaN(index)) return
          event.preventDefault()
          const value = choiceValue(choice)
          if (definition?.multiple) {
            const current = (state.value[name] as string[] | undefined) ?? []
            api.answer(name, current.includes(value) ? current.filter((v) => v !== value) : [...current, value], event, "shortcut-key")
          } else api.answer(name, value, event, "shortcut-key")
          later(() => itemEl(name)?.querySelector<HTMLElement>(`[data-slot=questionnaire-choice][data-value="${CSS.escape(value)}"] [role=radio], [data-slot=questionnaire-choice][data-value="${CSS.escape(value)}"] [role=checkbox]`)?.focus())
        }
      },
      /** Each item's status: answered, skipped or unanswered. */
      statusOf: (state: QuestionnaireState, name: string) => statusOf(state, name),
      /** The active item's name. */
      active: (state: QuestionnaireState) => activeOf(state),
    }
    return api
  },
  slots: (slot) => {
    /* Shown only while it applies to the active item. */
    const action = (
      applies: (state: QuestionnaireState, last: boolean, first: boolean) => boolean,
      kind: "previous" | "skip" | "next" | "submit",
    ) =>
      slot<{}, { visible: boolean; status: QuestionnaireItemStatus }>({
        /* The part wraps a button: its click bubbles here, so keys and screen readers work too. */
        press: ({ api }, event) => {
          if (kind === "submit") api.submitPress(event)
          else void api[kind](event)
        },
        state: (state) => {
          const enabled = enabledOf(state)
          const name = activeOf(state)
          const at = enabled.findIndex((item) => item.name === name)
          return {
            visible: applies(state, at === enabled.length - 1, at <= 0),
            status: name ? statusOf(state, name) : "unanswered",
          }
        },
        attrs: (state) => {
          const enabled = enabledOf(state)
          const name = activeOf(state)
          const at = enabled.findIndex((item) => item.name === name)
          const visible = applies(state, at === enabled.length - 1, at <= 0)
          return {
            hidden: visible ? undefined : "",
            "data-visible": visible ? "" : undefined,
            "data-hidden": visible ? undefined : "",
            "data-status": name ? statusOf(state, name) : "unanswered",
          }
        },
      })

    return {
      root: slot<{}, { current: number; total: number; first: boolean; last: boolean }>({
        state: (state) => {
          const enabled = enabledOf(state)
          const at = enabled.findIndex((item) => item.name === activeOf(state))
          return { current: at + 1, total: enabled.length, first: at <= 0, last: at === enabled.length - 1 }
        },
        attrs: (state) => {
          const enabled = enabledOf(state)
          const at = enabled.findIndex((item) => item.name === activeOf(state))
          return {
            "data-current": String(at + 1),
            "data-total": String(enabled.length),
            "data-first": at <= 0 ? "" : undefined,
            "data-last": at === enabled.length - 1 ? "" : undefined,
            "data-shortcuts": state.shortcuts,
            "aria-keyshortcuts": "Control+Enter Meta+Enter",
          }
        },
        on: {
          keydown: (event, { api }) => api.keydown(event as KeyboardEvent),
          submit: (event, { api }) => api.completed(event),
        },
      }),
      progress: slot<{}, { current: number; total: number; answered: number; first: boolean; last: boolean }>({
        role: "progressbar",
        state: (state) => {
          const enabled = enabledOf(state)
          const at = enabled.findIndex((item) => item.name === activeOf(state))
          return {
            current: at + 1,
            total: enabled.length,
            answered: enabled.filter((item) => statusOf(state, item.name) !== "unanswered").length,
            first: at <= 0,
            last: at === enabled.length - 1,
          }
        },
        attrs: (state) => {
          const enabled = enabledOf(state)
          const at = enabled.findIndex((item) => item.name === activeOf(state))
          return {
            "aria-label": "Questionnaire progress",
            "aria-valuemin": "1",
            "aria-valuemax": String(enabled.length),
            "aria-valuenow": String(at + 1),
            "aria-valuetext": `Question ${at + 1} of ${enabled.length}`,
            "data-current": String(at + 1),
            "data-total": String(enabled.length),
            style: css({ "--questionnaire-progress": enabled.length ? (at + 1) / enabled.length : 0 }),
          }
        },
      }),
      item: slot<NameProps, { active: boolean; status: QuestionnaireItemStatus; invalid: boolean; position: "before" | "active" | "after" }>({
        props: { name: "string" },
        state: (state, part) => ({
          active: activeOf(state) === part.props.name,
          status: statusOf(state, part.props.name),
          invalid: state.invalid.includes(part.props.name),
          position: position(state, part.props.name),
        }),
        attrs: (state, part) => {
          const definition = definitionOf(state, part.props.name)
          const active = activeOf(state) === part.props.name
          const invalid = state.invalid.includes(part.props.name)
          const id = ids(part.id, part.props.name)
          return {
            tabindex: "-1",
            inert: active ? undefined : "true",
            "aria-hidden": active ? undefined : "true",
            "aria-describedby": [id.description, invalid ? id.error : ""].filter(Boolean).join(" "),
            "aria-invalid": invalid ? "true" : undefined,
            "data-active": active ? "" : undefined,
            "data-position": position(state, part.props.name),
            "data-status": statusOf(state, part.props.name),
            "data-required": definition?.required ? "" : undefined,
            "data-multiple": definition?.multiple ? "" : undefined,
            "data-disabled": definition?.disabled ? "" : undefined,
            "data-invalid": invalid ? "" : undefined,
          }
        },
      }),
      /* Optional: holds the items so the one leaving and the one arriving overlap. */
      items: slot({}),
      /* A row for Previous, Skip, Next and Submit. */
      actions: slot({}),
      title: slot<NameProps>({
        props: { name: { kind: "string", from: "item", required: true } },
        attrs: (_state, part) => ({ id: ids(part.id, part.props.name).title }),
      }),
      description: slot<NameProps>({
        props: { name: { kind: "string", from: "item", required: true } },
        attrs: (_state, part) => ({ id: ids(part.id, part.props.name).description }),
      }),
      choices: slot<NameProps, { name: string; value: QuestionnaireAnswer | undefined; multiple: boolean; invalid: boolean; required: boolean; labelledBy: string }>({
        props: { name: { kind: "string", from: "item", required: true } },
        state: (state, part) => ({
          name: part.props.name,
          value: state.value[part.props.name],
          multiple: !!definitionOf(state, part.props.name)?.multiple,
          invalid: state.invalid.includes(part.props.name),
          required: !!definitionOf(state, part.props.name)?.required,
          labelledBy: ids(part.id, part.props.name).title,
        }),
        attrs: (state) => ({ "data-shortcuts": state.shortcuts }),
      }),
      choice: slot<{ value: string; name: string }, { checked: boolean; type: "radio" | "checkbox"; shortcut: string | undefined; invalid: boolean; disabled: boolean }>({
        props: { value: "string", name: { kind: "string", from: "item", required: true } },
        state: (state, part) => {
          const answer = state.value[part.props.name]
          const definition = definitionOf(state, part.props.name)
          return {
            checked: Array.isArray(answer) ? answer.includes(part.key) : answer === part.key,
            type: definition?.multiple ? "checkbox" : "radio",
            shortcut: shortcutOf(state, part.props.name, part.key),
            invalid: state.invalid.includes(part.props.name),
            disabled: !!definition?.choices?.some((choice) => choiceValue(choice) === part.key && choiceDisabled(choice)),
          }
        },
        attrs: (state, part) => {
          const answer = state.value[part.props.name]
          const checked = Array.isArray(answer) ? answer.includes(part.key) : answer === part.key
          const shortcut = shortcutOf(state, part.props.name, part.key)
          return {
            "data-value": part.key,
            "data-type": definitionOf(state, part.props.name)?.multiple ? "checkbox" : "radio",
            "data-checked": checked ? "" : undefined,
            "data-unchecked": checked ? undefined : "",
            "data-invalid": state.invalid.includes(part.props.name) ? "" : undefined,
            "data-shortcut": shortcut,
            "aria-keyshortcuts": shortcut,
          }
        },
      }),
      "choice-label": slot({}),
      "choice-shortcut": slot<{ value: string; name: string }, { shortcut: string | undefined }>({
        props: { value: { kind: "string", from: "choice", required: true }, name: { kind: "string", from: "item", required: true } },
        present: (state, part) => !!shortcutOf(state, part.props.name, part.props.value),
        state: (state, part) => ({ shortcut: shortcutOf(state, part.props.name, part.props.value) }),
        attrs: () => ({ "aria-hidden": "true" }),
      }),
      input: slot<NameProps, { name: string; value: string; filled: boolean; invalid: boolean }>({
        props: { name: { kind: "string", from: "item", required: true } },
        state: (state, part) => {
          const answer = state.value[part.props.name]
          const text = typeof answer === "string" && !(definitionOf(state, part.props.name)?.choices ?? []).some((c) => choiceValue(c) === answer) ? answer : ""
          return { name: part.props.name, value: text, filled: text.trim() !== "", invalid: state.invalid.includes(part.props.name) }
        },
        attrs: (state, part) => {
          const answer = state.value[part.props.name]
          const text = typeof answer === "string" && !(definitionOf(state, part.props.name)?.choices ?? []).some((c) => choiceValue(c) === answer) ? answer : ""
          return {
            "data-filled": text.trim() ? "" : undefined,
            "data-empty": text.trim() ? undefined : "",
            "data-invalid": state.invalid.includes(part.props.name) ? "" : undefined,
          }
        },
      }),
      error: slot<NameProps, { invalid: boolean }>({
        props: { name: { kind: "string", from: "item", required: true } },
        present: (state, part) => state.invalid.includes(part.props.name),
        state: (state, part) => ({ invalid: state.invalid.includes(part.props.name) }),
        attrs: (_state, part) => ({ id: ids(part.id, part.props.name).error, "aria-live": "polite", "data-invalid": "" }),
      }),
      previous: action((_state, _last, first) => !first, "previous"),
      skip: action(
        (state) => {
          const name = activeOf(state)
          return !!name && !definitionOf(state, name)?.required
        },
        "skip",
      ),
      next: action((_state, last) => !last, "next"),
      submit: action((_state, last) => last, "submit"),
    }
  },
  agent: { actions: ["answer", "next", "previous", "skip", "goTo", "submit"] },
})

