/* A stepper, as a UI SDK primitive. UI SDK ships none, so it is defined with its core: the same
   definition renders in React, Vue, Svelte, Solid and web components.

   It owns the steps (as data, so every step's place and state is known before anything mounts), the
   current one, how far someone has got, and which way they last moved. Each step is complete,
   current, upcoming or error. Two uses:

   - A read-only progress strip (`interactive: false`): an order that is Placed, Paid, Packed. The
     steps are plain text; the current one carries `aria-current="step"`.
   - An interactive multi-step form: the steps are buttons with one tab stop and arrow keys between
     them (`createRovingFocus`). `linear` (the default) lets people go back to any step they have
     reached but forward only through `next`; without it, any step can be chosen. A step that can't be
     chosen yet is `aria-disabled`, and stays focusable so the arrows don't skip it.

   Follows the pattern UI SDK's patterns page gives for a stepper: a list of buttons with one tab
   stop, the current step marked `aria-current="step"`, no tab or radio roles. */

import { type ChangeDetails, createChange, createRovingFocus, definePrimitive } from "@ui-sdk/core"

type StepperStepState = "complete" | "current" | "upcoming" | "error"

/** One step. */
type StepperStep = {
  /** Unique, and what `value` holds while this step is current. */
  value: string
  /** The step's name: "Shipping". */
  label: string
  /** A line under the name. */
  description?: string
  /** Something on this step needs fixing. Shown as the error state wherever the step is. */
  error?: boolean
  /** Can't be chosen. */
  disabled?: boolean
}

/* "previous-press", "next-press" and "imperative" aren't in the shared vocabulary. */
type StepperValueChangeReason = "item-press" | "previous-press" | "next-press" | "imperative"

type StepperOptions = {
  /** The steps, in order. */
  steps?: readonly StepperStep[]
  /** The current step's value, controlled. */
  value?: string
  /** The current step at first, when uncontrolled. Defaults to the first step. */
  defaultValue?: string
  /** Runs when the current step wants to change. `details.cancel()` stays put, like a step that doesn't validate. */
  onValueChange?: (value: string, details: ChangeDetails<StepperValueChangeReason>) => void
  /** The steps that are done. Defaults to every step before the furthest one reached. Pass every value for a finished flow. */
  completed?: string[]
  /** Steps are buttons people can choose (the default). Off, the stepper is a read-only progress strip. */
  interactive?: boolean
  /** Forward only through `next`; back to any step already reached (the default). Off, any step can be chosen. */
  linear?: boolean
  /** "horizontal" (the default) or "vertical". */
  orientation?: "horizontal" | "vertical"
}

type StepperSummary = { value: string; label: string; state: StepperStepState }

type StepperState = {
  steps: readonly StepperStep[]
  value: string
  /** The furthest step reached, by index. */
  reached: number
  completed: string[] | undefined
  interactive: boolean
  linear: boolean
  orientation: "horizontal" | "vertical"
  /** Which way the last move went, for panels that arrive from that side. */
  direction: "forward" | "backward"
  /** The step with the tab stop. */
  focused: string | null
  /** Every step with its state, for agents and for anyone reading the state. */
  progress: StepperSummary[]
}

const indexOf = (state: Pick<StepperState, "steps">, value: string | null | undefined) =>
  state.steps.findIndex((step) => step.value === value)

/** A step's state: error wins, then current, then complete, else upcoming. */
function stepState(state: StepperState, value: string): StepperStepState {
  const index = indexOf(state, value)
  const step = state.steps[index]
  if (!step) return "upcoming"
  if (step.error) return "error"
  if (value === state.value) return "current"
  if (state.completed) return state.completed.includes(value) ? "complete" : "upcoming"
  return index < state.reached ? "complete" : "upcoming"
}

/** Whether someone can go to this step now. */
function reachable(state: StepperState, value: string) {
  const index = indexOf(state, value)
  const step = state.steps[index]
  if (!state.interactive || !step || step.disabled) return false
  if (!state.linear) return true
  return index <= state.reached || (state.completed?.includes(value) ?? false)
}

const progressOf = (state: StepperState): StepperSummary[] =>
  state.steps.map((step) => ({ value: step.value, label: step.label, state: stepState(state, step.value) }))

const stepper = definePrimitive({
  name: "stepper",
  options: {
    steps: "value",
    value: "string",
    defaultValue: "string",
    onValueChange: "callback",
    completed: "list",
    interactive: "boolean",
    linear: "boolean",
    orientation: "string",
  },
  state: (options: StepperOptions): StepperState => {
    const steps = options.steps ?? []
    const value = options.value ?? options.defaultValue ?? steps[0]?.value ?? ""
    const base: StepperState = {
      steps,
      value,
      reached: Math.max(0, steps.findIndex((step) => step.value === value)),
      completed: options.completed,
      interactive: options.interactive ?? true,
      linear: options.linear ?? true,
      orientation: options.orientation ?? "horizontal",
      direction: "forward",
      focused: null,
      progress: [],
    }
    return { ...base, progress: progressOf(base) }
  },
  sync: (options) => ({
    steps: options.steps ?? [],
    completed: options.completed,
    interactive: options.interactive ?? true,
    linear: options.linear ?? true,
    orientation: options.orientation ?? "horizontal",
    ...(options.value === undefined ? {} : { value: options.value }),
  }),
  controlled: ["value", "progress"],
  api: (context) => {
    const { store } = context
    const change = createChange(context)

    /* However the value or the steps change (a click, a controlled parent, new data), keep how far
       someone got, which way they went and every step's state current. */
    let from = { value: store.get().value, steps: store.get().steps, completed: store.get().completed }
    context.onDestroy(
      store.subscribe(() => {
        const state = store.get()
        if (state.value === from.value && state.steps === from.steps && state.completed === from.completed) return
        const before = indexOf({ steps: from.steps }, from.value)
        const now = indexOf(state, state.value)
        from = { value: state.value, steps: state.steps, completed: state.completed }
        const next = { ...state, reached: Math.max(state.reached, now), direction: now < before ? ("backward" as const) : ("forward" as const) }
        store.set({ reached: next.reached, direction: next.direction, progress: progressOf(next) })
      }),
    )

    const roving = createRovingFocus(context, {
      slot: "step",
      key: "focused",
      orientation: () => store.get().orientation,
      preferred: (step) => step.key === store.get().value,
      claims: (state, step) => step.key === state.value,
    })

    const go = (value: string, reason: StepperValueChangeReason, event?: Event) => {
      const state = store.get()
      if (value === state.value || indexOf(state, value) < 0) return false
      return change("value", value, { reason, event })
    }

    return {
      roving,
      /** Goes to a step, by value or label, if it can be reached now. */
      goTo(step: string, event?: Event) {
        const state = store.get()
        const lower = step.trim().toLowerCase()
        const value = state.steps.find((entry) => entry.value === step || entry.label.toLowerCase() === lower)?.value ?? step
        if (!reachable(state, value)) return false
        return go(value, "item-press", event)
      },
      /** Goes on to the next step (in a linear stepper, the only way forward). */
      next(event?: Event) {
        const state = store.get()
        if (!state.interactive) return false
        const following = state.steps.slice(indexOf(state, state.value) + 1).find((step) => !step.disabled)
        return following ? go(following.value, "next-press", event) : false
      },
      /** Goes back to the step before. */
      previous(event?: Event) {
        const state = store.get()
        if (!state.interactive) return false
        const before = state.steps.slice(0, Math.max(0, indexOf(state, state.value))).reverse().find((step) => !step.disabled)
        return before ? go(before.value, "previous-press", event) : false
      },
      /** The steps, for agents to choose from. */
      items() {
        return store.get().steps.map((step) => ({ value: step.value, label: step.label }))
      },
      /** @internal */
      stateOf: (state: StepperState, value: string) => stepState(state, value),
      /** @internal */
      reachable: (state: StepperState, value: string) => reachable(state, value),
    }
  },
  slots: (slot) => ({
    root: slot<{}, { value: string; orientation: "horizontal" | "vertical"; direction: "forward" | "backward"; interactive: boolean }>({
      role: "group",
      state: (state) => ({ value: state.value, orientation: state.orientation, direction: state.direction, interactive: state.interactive }),
      attrs: (state) => ({
        "data-orientation": state.orientation,
        "data-direction": state.direction,
        "data-interactive": state.interactive ? "" : undefined,
      }),
    }),
    list: slot<{}, { orientation: "horizontal" | "vertical"; steps: readonly StepperStep[] }>({
      state: (state) => ({ orientation: state.orientation, steps: state.steps }),
      attrs: (state) => ({ "data-orientation": state.orientation }),
    }),
    /* One step's place in the list: indicator, text and the connector to the next step. */
    item: slot<{ value: string }, { state: StepperStepState; index: number; last: boolean; orientation: "horizontal" | "vertical" }>({
      props: { value: "string" },
      state: (state, part) => ({
        state: part.api.stateOf(state, part.key),
        index: indexOf(state, part.key),
        last: indexOf(state, part.key) === state.steps.length - 1,
        orientation: state.orientation,
      }),
      attrs: (state, part) => ({
        "data-state": part.api.stateOf(state, part.key),
        "data-orientation": state.orientation,
        "data-last": indexOf(state, part.key) === state.steps.length - 1 ? "" : undefined,
        "aria-current": !state.interactive && state.value === part.key ? "step" : undefined,
      }),
    }),
    /* The step itself: a button in an interactive stepper, plain text in a progress strip. */
    step: slot<{ value: string }, { state: StepperStepState; index: number; reachable: boolean; interactive: boolean }>({
      props: { value: "string" },
      role: (state) => (state.interactive ? "button" : "none"),
      roles: ["button", "none"],
      focus: (state) => (state.interactive ? "roving" : { none: "A read-only progress strip takes no focus." }),
      keys: (state) => (state.orientation === "vertical" ? ["ArrowUp", "ArrowDown", "Home", "End"] : ["ArrowLeft", "ArrowRight", "Home", "End"]),
      state: (state, part) => ({
        state: part.api.stateOf(state, part.key),
        index: indexOf(state, part.key),
        reachable: part.api.reachable(state, part.key),
        interactive: state.interactive,
      }),
      attrs: (state, part) => ({
        type: state.interactive ? "button" : undefined,
        tabindex: state.interactive ? part.api.roving.tabIndex(state, part) : undefined,
        "aria-current": state.interactive && state.value === part.key ? "step" : undefined,
        "aria-disabled": state.interactive && !part.api.reachable(state, part.key) ? "true" : undefined,
        "data-state": part.api.stateOf(state, part.key),
        "data-reachable": part.api.reachable(state, part.key) ? "" : undefined,
      }),
      press: ({ api, key }, event) => void api.goTo(key, event),
      on: {
        keydown: (event, { el, api, store }) => {
          if (el && store.get().interactive) api.roving.keydown(event as KeyboardEvent, el)
        },
      },
      bind: (el, part) => part.api.roving.bind(el, part),
    }),
    indicator: slot<{ value: string }, { state: StepperStepState; index: number }>({
      props: { value: { kind: "string", from: "item" } },
      state: (state, part) => ({ state: part.api.stateOf(state, part.key), index: indexOf(state, part.key) }),
      attrs: (state, part) => ({ "aria-hidden": "true", "data-state": part.api.stateOf(state, part.key) }),
    }),
    title: slot({}),
    description: slot({}),
    /* The line to the next step. `data-filled` once the next step is reached, so it can draw itself. */
    connector: slot<{ value: string }, { filled: boolean }>({
      props: { value: { kind: "string", from: "item" } },
      present: (state, part) => indexOf(state, part.key) < state.steps.length - 1,
      state: (state, part) => {
        const next = state.steps[indexOf(state, part.key) + 1]
        return { filled: !!next && ["complete", "current"].includes(part.api.stateOf(state, next.value)) }
      },
      attrs: (state, part) => {
        const next = state.steps[indexOf(state, part.key) + 1]
        const filled = !!next && ["complete", "current"].includes(part.api.stateOf(state, next.value))
        return { "aria-hidden": "true", "data-filled": filled ? "" : undefined, "data-orientation": state.orientation }
      },
    }),
    /* A step's content, shown while it is current. `data-direction` says which way the move went. */
    panel: slot<{ value: string }, { direction: "forward" | "backward" }>({
      props: { value: "string" },
      present: (state, part) => state.value === part.key,
      state: (state) => ({ direction: state.direction }),
      attrs: (state) => ({ "data-direction": state.direction, "data-orientation": state.orientation }),
    }),
  }),
  agent: { actions: ["goTo", "next", "previous"], closed: true, items: (api) => api.items() },
})

export { stepper, type StepperOptions, type StepperStep, type StepperStepState, type StepperSummary }

/* A table, as UI SDK primitives. UI SDK ships no table, so it is defined with its core: the same
   definitions render in React, Vue, Svelte, Solid and web components.

   `table` is the table and its parts: a scrolling container that knows which sides it can still
   scroll toward, and rows that can be selected. `tableHead` is one column header, which becomes a
   sort button when it is sortable: pressing it turns the sort over, and the header reports it with
   `aria-sort`. Each header is its own instance, so a sortable header keeps its own sort. */

import { type ChangeDetails, createChange, definePrimitive, dispatch } from "@ui-sdk/core"

import { bindAgentContent } from "@/components/core/agent-content"

/** How a column is sorted, with the values `aria-sort` takes. */
type SortDirection = "ascending" | "descending" | "none"

type TableState = {
  /** The readable table content, kept current as rows and cells change. */
  content: string
  /** The container can scroll back toward the start. */
  scrollStart: boolean
  /** The container can scroll on toward the end. */
  scrollEnd: boolean
}

const table = definePrimitive({
  name: "table",
  state: (): TableState => ({ content: "", scrollStart: false, scrollEnd: false }),
  controlled: ["content", "scrollStart", "scrollEnd"],
  api: (context) => ({
    /** Reads how far the container is scrolled and marks the sides it can still scroll toward. */
    measure(el: HTMLElement) {
      const max = el.scrollWidth - el.clientWidth
      /* Right to left, scrollLeft runs from 0 down to -max, so its size is the distance from the start. */
      const at = Math.abs(el.scrollLeft)
      const next = { scrollStart: at > 1, scrollEnd: max - at > 1 }
      const now = context.store.get()
      if (next.scrollStart !== now.scrollStart || next.scrollEnd !== now.scrollEnd) context.store.set(next)
    },
  }),
  slots: (slot) => ({
    /* Scrolls sideways when the table is wider than the space it has. */
    container: slot<{}, Pick<TableState, "scrollStart" | "scrollEnd">>({
      state: (state) => ({ scrollStart: state.scrollStart, scrollEnd: state.scrollEnd }),
      attrs: (state) => ({
        "data-scroll-start": state.scrollStart ? "" : undefined,
        "data-scroll-end": state.scrollEnd ? "" : undefined,
      }),
      bind: (el, part) => {
        const measure = () => part.api.measure(el)
        measure()
        const resize = new ResizeObserver(measure)
        resize.observe(el)
        if (el.firstElementChild) resize.observe(el.firstElementChild)
        el.addEventListener("scroll", measure, { passive: true })
        return () => {
          resize.disconnect()
          el.removeEventListener("scroll", measure)
        }
      },
    }),
    root: slot({
      bind: (el, part) => bindAgentContent(el, (content) => part.store.set({ content })),
    }),
    header: slot({}),
    body: slot({}),
    footer: slot({}),
    row: slot<{ selected?: boolean }, { selected: boolean }>({
      props: { selected: "boolean" },
      state: (_state, part) => ({ selected: part.props.selected ?? false }),
      attrs: (_state, part) => ({
        "data-selected": part.props.selected ? "" : undefined,
        "aria-selected": part.props.selected === undefined ? undefined : String(part.props.selected),
      }),
    }),
    cell: slot({}),
    caption: slot({}),
  }),
  /* The table is readable data; sortable headers expose their own actions. */
  agent: { actions: [] },
})

type TableHeadOptions = {
  /** How this column is sorted, controlled. Pass `onSort` or `onSortChange` with it. */
  sort?: SortDirection
  /** How this column is sorted at first, when you don't control `sort`. Makes the header sortable. */
  defaultSort?: SortDirection
  /** Runs when the sort changes, with the next direction. */
  onSortChange?: (sort: SortDirection, details: ChangeDetails<"press">) => void
  /** Runs when the header is pressed, with the direction it turns to. Flip `sort` here. Makes the header sortable. */
  onSort?: (sort: SortDirection, details: ChangeDetails<"press">) => void
}

type TableHeadState = {
  sort: SortDirection
  /** The header is a sort button: it has `onSort`, `onSortChange` or `defaultSort`. */
  sortable: boolean
}

const isSortable = (options: TableHeadOptions) =>
  options.onSort !== undefined || options.onSortChange !== undefined || options.defaultSort !== undefined

/* Its parts are the table's own (`table-head`, `table-sort`, `table-sort-arrow`), so the name is
   the table's; `label` names the header in warnings and the devtools. */
const tableHead = definePrimitive({
  name: "table",
  label: "table-head",
  options: { sort: "string", defaultSort: "string", onSortChange: "callback", onSort: "callback" },
  controlled: ["sort", "sortable"],
  state: (options: TableHeadOptions): TableHeadState => ({
    sort: options.sort ?? options.defaultSort ?? "none",
    sortable: isSortable(options),
  }),
  sync: (options) => ({ ...(options.sort === undefined ? {} : { sort: options.sort }), sortable: isSortable(options) }),
  api: (context) => {
    const change = createChange(context)
    return {
      /** Turns the sort over: ascending becomes descending, anything else ascending. */
      toggleSort(event?: Event) {
        const { sort, sortable } = context.store.get()
        if (!sortable) return false
        const next: SortDirection = sort === "ascending" ? "descending" : "ascending"
        if (dispatch(context, "onSort", next, { reason: "press", event })) return false
        return change("sort", next, { reason: "press", event })
      },
    }
  },
  slots: (slot) => ({
    head: slot<{}, TableHeadState>({
      state: (state) => ({ sort: state.sort, sortable: state.sortable }),
      attrs: (state) => ({
        "aria-sort": state.sortable ? state.sort : undefined,
        "data-sort": state.sortable ? state.sort : undefined,
      }),
    }),
    /* The whole label is the button, so it is easy to hit. */
    sort: slot<{}, { sort: SortDirection }>({
      present: (state) => state.sortable,
      state: (state) => ({ sort: state.sort }),
      attrs: (state) => ({ type: "button", "data-sort": state.sort }),
      press: ({ api }, event) => api.toggleSort(event),
    }),
    "sort-arrow": slot<{}, { sort: SortDirection }>({
      present: (state) => state.sortable,
      state: (state) => ({ sort: state.sort }),
      attrs: (state) => ({ "aria-hidden": "true", "data-sort": state.sort }),
    }),
  }),
  agent: { actions: ["toggleSort"], shown: (state) => state.sortable },
})

export { type SortDirection, table, tableHead, type TableHeadOptions, type TableHeadState, type TableState }

/* A trace: the steps an assistant or a job went through, one line each, as a UI SDK primitive. UI SDK
   ships none, so it is defined with its core: the same definition renders in React, Vue, Svelte,
   Solid and web components.

   A line has a status (running, error, pending, or done when it has none) and a title. When a line
   stops running, screen readers hear its new title once, so "Searching flights" becoming "Found
   12 flights" is announced without a live region on the whole list. Lines that expand are UI SDK's
   collapsible, composed in the renderer: this primitive adds no open state of its own. */

import { announce, definePrimitive } from "@ui-sdk/core"

import { bindAgentContent } from "@/components/core/agent-content"

/** A line's state. Leave it out for a step that finished. */
type TraceStatus = "running" | "error" | "pending"

const statusAttr = (status: string | undefined) => (status === "running" || status === "error" || status === "pending" ? status : undefined)

const trace = definePrimitive({
  name: "trace",
  options: {},
  state: () => ({ content: "" }),
  controlled: ["content"],
  api: () => ({}),
  slots: (slot) => ({
    root: slot({
      state: () => ({}),
      bind: (el, part) => bindAgentContent(el, (content) => part.store.set({ content })),
    }),
    line: slot<{ status?: TraceStatus }, { status: TraceStatus | undefined }>({
      props: { status: "string" },
      state: (_state, part) => ({ status: statusAttr(part.props.status) as TraceStatus | undefined }),
      attrs: (_state, part) => ({
        "data-status": statusAttr(part.props.status),
        "data-done": statusAttr(part.props.status) ? undefined : "",
      }),
      /* Reads the title out once when the step stops running or fails. */
      bind: (el) => {
        let was = el.getAttribute("data-status")
        const observer = new MutationObserver(() => {
          const now = el.getAttribute("data-status")
          if (now === was) return
          const ended = was === "running" && now !== "running"
          was = now
          if (!ended) return
          const title = el.querySelector("[data-slot=trace-title]")?.textContent?.trim()
          if (title) announce(title, { priority: now === "error" ? "assertive" : "polite" })
        })
        observer.observe(el, { attributes: true, attributeFilter: ["data-status"] })
        return () => observer.disconnect()
      },
    }),
    /* Decorative: the title is the line's name. */
    icon: slot({
      attrs: () => ({ "aria-hidden": "true" }),
    }),
    title: slot({}),
    description: slot({}),
  }),
  /* Expose the trace's titles and descriptions; expanding rows are separate collapsibles. */
  agent: { actions: [] },
})

export { trace, type TraceStatus }

import { createAgent, type AgentAction, type AgentComponent, type AgentStep, type ObservedChange } from "@ui-sdk/react/agent"
import { elementOf } from "@ui-sdk/react/observe"

type Bridge = ReturnType<typeof createAgent>
type ActionResult = Awaited<ReturnType<Bridge["act"]>>

export type AgentPreviewSnapshot = {
  components: AgentComponent[]
  ready: boolean
  pending: boolean
  error: string | null
  result: unknown
  changes: ObservedChange[]
  truncated: boolean
}

export const emptyAgentPreview: AgentPreviewSnapshot = {
  components: [], ready: false, pending: false, error: null, result: null, changes: [], truncated: false,
}

const scopes = new Set<HTMLElement>()
let bridge: Bridge | undefined
let authorized: { scope: HTMLElement; ref: string; action: string } | undefined
let actionQueue = Promise.resolve()

function elementFor(ref: string) {
  try { return elementOf(ref) } catch { return undefined }
}

/** The element UI SDK registered for a snapshot ref, for pointing at it in the preview. */
export function elementForRef(ref: string): HTMLElement | undefined {
  const el = elementFor(ref)
  return el instanceof HTMLElement && el.isConnected ? el : undefined
}

function contentScope(scope: HTMLElement) {
  return scope.querySelector<HTMLElement>("[data-agent-preview-content]") ?? scope
}

/* A popup can live outside its trigger's DOM subtree. Follow its ARIA ownership, while never
   borrowing another mounted preview's canvas. Native top-layer popups remain descendants. */
function ownedRegions(scope: HTMLElement) {
  const content = contentScope(scope)
  const regions = new Set<HTMLElement>([content])
  const previews = new Set([...scopes, ...scope.ownerDocument.querySelectorAll<HTMLElement>("[data-agent-preview-canvas]")])
  for (const region of regions) {
    for (const control of region.querySelectorAll<HTMLElement>("[aria-controls], [aria-owns]")) {
      for (const id of `${control.getAttribute("aria-controls") ?? ""} ${control.getAttribute("aria-owns") ?? ""}`.split(/\s+/)) {
        if (!id) continue
        const target = scope.ownerDocument.getElementById(id)
        if (!target || target.contains(content) || [...previews].some((other) => other !== scope && (other.contains(target) || target.contains(other)))) continue
        regions.add(target)
      }
    }
    if (regions.size > 100) break
  }
  return regions
}

function owns(scope: HTMLElement, ref: string) {
  const el = elementFor(ref)
  return !!el?.isConnected && !el.closest("[data-agent-hidden]") && [...ownedRegions(scope)].some((region) => region.contains(el))
}

function pageBridge() {
  if (typeof document === "undefined") throw new Error("Agent previews are available in the browser.")
  return bridge ??= createAgent({
    allow: (step: AgentAction) => !!authorized && !step.confirm &&
      step.ref === authorized.ref && step.action === authorized.action && owns(authorized.scope, step.ref),
  })
}

function serializeAction<T>(run: () => Promise<T>) {
  const operation = actionQueue.then(run, run)
  actionQueue = operation.then(() => undefined, () => undefined)
  return operation
}

function failure(message: string): ActionResult {
  return { ok: false, steps: [], appeared: [], values: {}, error: { step: 0, message } }
}

function messageOf(error: unknown) { return error instanceof Error ? error.message : String(error) }

/* A global snapshot stops at 100 entries. Query the kinds actually rendered in this canvas
   when it is capped; data-slot prefixes include both component and part names. */
function renderedKinds(scope: HTMLElement) {
  const kinds = new Set<string>()
  for (const region of ownedRegions(scope)) {
    for (const el of [region, ...region.querySelectorAll<HTMLElement>("[data-slot]")]) {
      if (el.closest("[data-agent-hidden]")) continue
      const words = el.getAttribute("data-slot")?.split("-") ?? []
      while (words.length) {
        kinds.add(words.join("-"))
        words.pop()
      }
    }
  }
  return kinds
}

function renderedLabels(scope: HTMLElement) {
  const labels = new Set<string>()
  for (const region of ownedRegions(scope)) {
    for (const el of [region, ...region.querySelectorAll<HTMLElement>("[aria-label], [aria-labelledby], label")]) {
      if (el.closest('[data-agent-hidden], [aria-hidden="true"]')) continue
      const referenced = el.getAttribute("aria-labelledby")?.split(/\s+/)
        .map((id) => scope.ownerDocument.getElementById(id)?.textContent ?? "").join(" ")
      const name = el.getAttribute("aria-label") || referenced || (el.tagName === "LABEL" ? el.textContent : "")
      if (name?.trim()) labels.add(name.trim())
    }
  }
  return labels
}

function hasRef(refs: Set<string>, value: string) {
  return [...refs].some((ref) => value === ref || value.startsWith(`${ref} `))
}

export function createAgentPreviewSession(scope: HTMLElement) {
  const agent = pageBridge()
  scopes.add(scope)
  let state = emptyAgentPreview
  let disposed = false
  let visible = true
  let scheduled = false
  let dirty = false
  let refreshing: Promise<void> | undefined
  let activeChanges: ObservedChange[] | undefined
  const listeners = new Set<() => void>()

  const update = (next: Partial<AgentPreviewSnapshot>) => {
    if (disposed) return
    state = { ...state, ...next }
    for (const listener of listeners) listener()
  }

  const local = (entry: AgentComponent) => entry.component !== "more" && !entry.offPage && owns(scope, entry.ref)
  async function readComponents() {
    const snapshot = agent.snapshot()
    const found = new Map(snapshot.filter(local).map((entry) => [entry.ref, entry]))
    let truncated = false
    if (snapshot.some((entry) => entry.component === "more")) {
      for (const kind of renderedKinds(scope)) {
        if (disposed) break
        const result = await agent.query({ kind })
        if ("error" in result) continue
        truncated ||= result.some((entry) => entry.component === "more")
        for (const entry of result) if (local(entry)) found.set(entry.ref, entry)
      }
      /* A kind can itself exceed 100 components elsewhere on a documentation page. Names
         rendered in this example narrow that query without exposing other examples. */
      if (truncated) for (const text of renderedLabels(scope)) {
        if (disposed) break
        const result = await agent.query({ text })
        if ("error" in result) continue
        for (const entry of result) if (local(entry)) found.set(entry.ref, entry)
      }
    }
    return { components: [...found.values()], truncated }
  }

  async function refresh() {
    if (disposed) return
    if (refreshing) { dirty = true; return refreshing }
    refreshing = (async () => {
      do {
        dirty = false
        try {
          const next = await readComponents()
          if (!state.ready || state.truncated !== next.truncated || JSON.stringify(state.components) !== JSON.stringify(next.components)) {
            update({ ...next, ready: true })
          }
        } catch (error) {
          update({ ready: true, error: messageOf(error) })
        }
      } while (dirty && !disposed)
    })().finally(() => { refreshing = undefined })
    return refreshing
  }

  const schedule = () => {
    if (disposed || scheduled || !visible) return
    scheduled = true
    queueMicrotask(() => { scheduled = false; void refresh() })
  }

  const unsubscribe = agent.subscribe((change) => {
    if (!owns(scope, change.ref)) return
    activeChanges?.push(change)
    update({ changes: [...state.changes, change].slice(-10) })
    schedule()
  })
  const mutations = new MutationObserver(schedule)
  mutations.observe(scope, { subtree: true, childList: true, characterData: true, attributes: true })
  const events = ["input", "change", "click", "keydown", "pointerup"]
  events.forEach((name) => scope.addEventListener(name, schedule, true))
  const intersection = typeof IntersectionObserver === "undefined" ? undefined : new IntersectionObserver(([entry]) => {
    visible = entry.isIntersecting
    if (visible) schedule()
  })
  intersection?.observe(scope.closest("[data-agent-preview-layout]") ?? scope)
  /* Some primitive state is programmatic and changes no DOM. A bounded fallback keeps that
     state live too; inactive examples do no polling, and inspector DOM is outside this scope. */
  const interval = setInterval(() => { if (visible && !scope.ownerDocument.hidden) schedule() }, 1000)

  function target(ref: string) {
    return state.components.find((entry) => entry.ref === ref && owns(scope, ref))
  }

  async function query(ref: string): Promise<AgentComponent[] | { error: string }> {
    if (disposed) return { error: "This preview is no longer mounted." }
    await refresh()
    if (disposed) return { error: "This preview is no longer mounted." }
    if (!target(ref)) {
      const result = { error: "Choose a component from this preview." }
      update({ error: result.error, result })
      return result
    }
    update({ pending: true, error: null })
    try {
      const response = await agent.query({ within: ref })
      const result = "error" in response ? response : response.filter(local)
      update({ result, error: "error" in result ? result.error : null })
      return result
    } catch (error) {
      const result = { error: messageOf(error) }
      update({ error: result.error, result })
      return result
    } finally { update({ pending: false }); await refresh() }
  }

  async function act(step: AgentStep) {
    if (disposed) return failure("This preview is no longer mounted.")
    update({ pending: true, error: null })
    try {
      return await serializeAction(async () => {
        if (disposed) return failure("This preview is no longer mounted.")
        await refresh()
        if (disposed) return failure("This preview is no longer mounted.")
        const entry = target(step.ref)
        if (!entry || !entry.actions.includes(step.action)) {
          const result = failure("Choose an available action on a component in this preview.")
          update({ error: result.error!.message, result })
          return result
        }
        if (entry.confirm) {
          const result = failure("This action needs confirmation in the component.")
          update({ error: result.error!.message, result })
          return result
        }
        const refs = new Set(state.components.map((component) => component.ref))
        scope.dispatchEvent(new CustomEvent("keyframery:agent-action", { bubbles: true }))
        authorized = { scope, ref: step.ref, action: step.action }
        activeChanges = []
        let raw: ActionResult
        try { raw = await agent.act({ steps: [step] }) } finally { authorized = undefined }
        const changes = activeChanges
        activeChanges = undefined
        await refresh()
        state.components.forEach((component) => refs.add(component.ref))
        const result: ActionResult = {
          ...raw,
          appeared: raw.appeared.filter(local),
          values: Object.fromEntries(Object.entries(raw.values).filter(([key]) => hasRef(refs, key))),
          ...(raw.open ? { open: raw.open.filter(local) } : {}),
          steps: raw.steps.filter((done) => refs.has(done.ref)).map((done) => ({
            ...done,
            changes: changes.map(({ component, label, key, value }) => ({ component, label, key, value })),
            ...(done.gone ? { gone: done.gone.filter((ref) => hasRef(refs, ref)) } : {}),
          })),
        }
        update({ result, error: result.error?.message ?? null })
        return result
      })
    } catch (error) {
      activeChanges = undefined
      const result = failure(messageOf(error))
      update({ error: result.error!.message, result })
      return result
    } finally { update({ pending: false }); await refresh() }
  }

  void refresh()
  return {
    getSnapshot: () => state,
    subscribe(listener: () => void) { listeners.add(listener); return () => { listeners.delete(listener) } },
    refresh,
    query,
    act,
    destroy() {
      disposed = true
      scopes.delete(scope)
      listeners.clear()
      unsubscribe()
      mutations.disconnect()
      intersection?.disconnect()
      clearInterval(interval)
      events.forEach((name) => scope.removeEventListener(name, schedule, true))
    },
  }
}

export type AgentPreviewSession = ReturnType<typeof createAgentPreviewSession>

"use client"

import * as React from "react"

/* One step of a demo's self-running sequence. Selectors are CSS selectors, looked up inside the
   demo first and then in the whole page (popups render outside the demo). */
export type PlayStep = {
  click?: string
  hover?: string
  unhover?: string
  key?: string
  type?: string
  into?: string
  wait?: number
  /** Run this step only at one size: a demo's narrow (phone) layout can need its own steps. */
  only?: "wide" | "narrow"
}

/* Below this the demo is showing its phone layout. */
const NARROW = 520

function find(root: HTMLElement, selector: string) {
  return root.querySelector<HTMLElement>(selector) ?? document.querySelector<HTMLElement>(selector)
}

function pointer(el: HTMLElement, types: string[]) {
  const r = el.getBoundingClientRect()
  const init = { bubbles: true, clientX: r.left + r.width / 2, clientY: r.top + r.height / 2, pointerType: "mouse" }
  for (const t of types) el.dispatchEvent(t.startsWith("pointer") ? new PointerEvent(t, init) : new MouseEvent(t, init))
}

function runStep(root: HTMLElement, step: PlayStep) {
  if (step.only && (root.clientWidth < NARROW ? "narrow" : "wide") !== step.only) return false
  if (step.click) find(root, step.click)?.click()
  if (step.hover) {
    const el = find(root, step.hover)
    if (el) pointer(el, ["pointerover", "pointerenter", "mouseover", "mouseenter", "pointermove", "mousemove"])
  }
  if (step.unhover) {
    const el = find(root, step.unhover)
    if (el) pointer(el, ["pointerout", "pointerleave", "mouseout", "mouseleave"])
  }
  if (step.key) {
    const target = (document.activeElement as HTMLElement | null) ?? root
    for (const t of ["keydown", "keyup"]) target.dispatchEvent(new KeyboardEvent(t, { key: step.key, bubbles: true }))
  }
  if (step.type !== undefined && step.into) {
    const el = find(root, step.into) as HTMLInputElement | null
    if (el) {
      const proto = el instanceof HTMLTextAreaElement ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype
      Object.getOwnPropertyDescriptor(proto, "value")?.set?.call(el, step.type)
      el.dispatchEvent(new Event("input", { bubbles: true }))
    }
  }
  return true
}

/* Set by the first real key press on the page. From then on focus rings are never hidden,
   because a keyboard user needs to see where focus is even inside a playing demo. */
let keyboardUser = false
if (typeof window !== "undefined") {
  window.addEventListener("keydown", (e) => {
    if (!e.isTrusted) return
    keyboardUser = true
    document.querySelectorAll("[data-autoplaying]").forEach((el) => el.removeAttribute("data-autoplaying"))
  }, { capture: true })
}

/* Plays once on first view. Changing replayToken explicitly starts a fresh pass, including for
   reduced motion or ?play=off; normal renders, resizes and new step-array identities do not.
   Real interaction ends automatic control permanently until the visitor asks for a replay. */
export function useAutoplay(ref: React.RefObject<HTMLDivElement | null>, steps: PlayStep[] | undefined, replayToken = 0) {
  const latestSteps = React.useRef(steps)
  latestSteps.current = steps
  const hasSteps = Boolean(steps?.length)

  React.useEffect(() => {
    const root = ref.current
    const script = latestSteps.current
    if (!root) return
    root.setAttribute("data-playback", "idle")
    root.removeAttribute("data-autoplaying")
    if (!script?.length) return
    const manual = replayToken > 0
    if (!manual && (window.matchMedia("(prefers-reduced-motion: reduce)").matches ||
      new URLSearchParams(window.location.search).get("play") === "off")) return

    let visible = manual
    let started = false
    let finished = false
    let disposed = false
    let waitingForView = false
    let index = 0
    let timer: ReturnType<typeof setTimeout> | undefined

    /* While the script drives the demo, its clicks and the focus that returns to a trigger
       when a popup closes look like keyboard focus to the browser, so every clicked button
       would wear a focus ring. `data-autoplaying` hides those rings (see index.css); it comes
       off the moment a real pointer or a real key press reaches the demo. */
    const driving = (on: boolean) => root.toggleAttribute("data-autoplaying", on && !keyboardUser)
    const clear = () => {
      if (timer !== undefined) clearTimeout(timer)
      timer = undefined
      driving(false)
      io.disconnect()
      root.removeEventListener("pointerenter", used)
      document.removeEventListener("pointerdown", used, true)
      document.removeEventListener("keydown", used, true)
      document.removeEventListener("keyframery:agent-action", agentUsed, true)
    }
    const finish = (state: "complete" | "stopped") => {
      finished = true
      root.setAttribute("data-playback", state)
      clear()
    }
    const used = (event: Event) => {
      if (!event.isTrusted || (!started && !root.contains(event.target as Node))) return
      if (event.type === "keydown") keyboardUser = true
      // Listen on the document as well: a demo's popup can live outside its frame.
      finish("stopped")
    }
    const agentUsed = (event: Event) => {
      const target = event.target as HTMLElement | null
      if (target && (root.contains(target) || target.contains?.(root))) finish("stopped")
    }
    const advance = () => {
      timer = undefined
      if (disposed || finished) return
      if (index === script.length) {
        finish("complete")
        return
      }
      if (!visible) {
        waitingForView = true
        driving(false)
        return
      }
      waitingForView = false
      root.setAttribute("data-playback", "playing")
      driving(true)
      while (index < script.length) {
        const step = script[index++]
        if (runStep(root, step)) {
          timer = setTimeout(advance, step.wait ?? 900)
          return
        }
      }
      finish("complete")
    }
    const start = () => {
      if (started || finished || disposed) return
      started = true
      timer = setTimeout(advance, manual ? 0 : 900)
    }
    const io = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting && (manual || entry.intersectionRatio >= 0.6)
      if (!visible) driving(false)
      else if (waitingForView) advance()
      else start()
    }, { threshold: [0, 0.6] })

    root.addEventListener("pointerenter", used)
    document.addEventListener("pointerdown", used, true)
    document.addEventListener("keydown", used, true)
    document.addEventListener("keyframery:agent-action", agentUsed, true)
    io.observe(root)
    if (manual) start()
    return () => {
      disposed = true
      clear()
    }
  }, [ref, hasSteps, replayToken])
}

/* The controls a demo offers in the Customize panel under its preview.

   A demo declares them next to its `meta` and takes the same names as optional props:

     export const controls = {
       variant: { type: "select", label: "Variant", options: ["default", "primary"], default: "default" },
       disabled: { type: "switch", label: "Disabled", default: false },
       gap: { type: "slider", label: "Gap", min: 0, max: 24, step: 2, default: 8, unit: "px" },
       label: { type: "text", label: "Label", default: "Book trip" },
       fill: { type: "color", label: "Fill", default: "", group: "Colours" },
     } as const

     export default function ButtonDemo({ variant = "default", disabled = false, gap = 8, label = "Book trip", fill = "" }: {
       variant?: "default" | "primary"; disabled?: boolean; gap?: number; label?: string; fill?: string
     }) { … }

   A demo rendered with no props (the landing page, the gallery) falls back to the defaults, so the
   defaults in the function must match the ones here. The docs strip the `controls` block from the
   example code, which is why it is a plain object with no import.

   `group` records related controls for documentation. The compact panel keeps declaration order.
   A colour's default is "" when the component should keep its own theme colour until someone
   picks one: apply it only when it is not empty.

   Not declared here, because the panel adds it to every component: how long the motion takes. */
type Shared = { label: string; group?: string }

export type Control =
  | (Shared & { type: "slider"; min: number; max: number; step?: number; default: number; unit?: string })
  | (Shared & { type: "switch"; default: boolean })
  | (Shared & { type: "select"; options: readonly string[]; default: string })
  | (Shared & { type: "color"; default: string })
  | (Shared & { type: "text"; default: string })

export type Controls = Readonly<Record<string, Control>>

export type ControlValue = number | boolean | string

export type ControlValues = Record<string, ControlValue>

export function defaultValues(controls: Controls | undefined): ControlValues {
  return Object.fromEntries(Object.entries(controls ?? {}).map(([name, control]) => [name, control.default]))
}

/* "variant:primary,disabled:true,gap:12,fill:%23e5484d" from a URL, read against the demo's controls. */
export function parseValues(controls: Controls | undefined, text: string | null): ControlValues {
  const values = defaultValues(controls)
  for (const pair of (text ?? "").split(",")) {
    const at = pair.indexOf(":")
    if (at < 0) continue
    const name = pair.slice(0, at)
    const control = controls?.[name]
    if (!control) continue
    let raw: string
    try { raw = decodeURIComponent(pair.slice(at + 1)) }
    catch { continue }
    if (control.type === "slider") {
      const numeric = Number(raw)
      const value = Number.isFinite(numeric) ? numeric : control.default
      const step = control.step ?? 1
      const snapped = Number((control.min + Math.round((value - control.min) / step) * step).toFixed(10))
      values[name] = Math.min(control.max, Math.max(control.min, snapped))
    }
    else if (control.type === "switch") values[name] = raw === "true"
    else if (control.type === "select") values[name] = control.options.includes(raw) ? raw : control.default
    else values[name] = raw
  }
  return values
}

"use client"

/* The Customize panel under a component's preview. Every control is one row of the same shape: a
   recessed well with its name on the left and its value on the right, drawn with Keyframery's own
   slider, switch, select and colour picker. Used by the docs site and the lab. See
   `@/lib/controls` for how a demo declares its controls. */

import { Check, ChevronsUpDown, RotateCcw } from "lucide-react"
import { Slider, SliderControl, SliderIndicator, SliderThumb, SliderTrack } from "@/components/primitives/slider"
import { Button } from "@/components/ui/button"
import {
  ColorPicker,
  ColorPickerArea,
  ColorPickerAreaThumb,
  ColorPickerContent,
  ColorPickerInput,
  ColorPickerPopover,
  ColorPickerSlider,
  ColorPickerSliderThumb,
  ColorPickerTrigger,
} from "@/components/ui/color-picker"
import { Select, SelectContent, SelectItem, SelectTrigger } from "@/components/primitives/select"
import { Switch } from "@/components/ui/switch"
import type { Control, Controls, ControlValue, ControlValues } from "@/lib/controls"
import { cn } from "@/lib/utils"

const words = (value: string) => value.replace(/[-_]+/g, " ").replace(/^./, (first) => first.toUpperCase())

const trim = (value: number) => String(Math.round(value * 100) / 100)

/* One row: a well the height of a field, the name inset 12px from the left, the value 12px from the right. */
const well = cn(
  "relative flex h-9 w-full items-center rounded-[10px] bg-muted text-[13px] leading-none outline-none select-none",
  "shadow-[inset_0_1px_1px_rgb(0_0_0/0.05),inset_0_0_0_1px_rgb(0_0_0/0.035)]",
  "dark:shadow-[inset_0_1px_2px_rgb(0_0_0/0.45),inset_0_0_0_1px_rgb(255_255_255/0.04)]",
)
const focus = "has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ring/60 focus-visible:ring-2 focus-visible:ring-ring/60"
const name = "pointer-events-none relative z-10 truncate ps-3 pe-2 text-muted-foreground"
const amount = "pointer-events-none relative z-10 ms-auto shrink-0 pe-3 font-medium text-foreground tabular-nums"

/* The row's parts, for panels that build their own rows in the same shape (the /create page). */
export const rowStyles = { well, focus, name, amount }

/* A slider you scrub: the whole row is the track, and the fill behind the words is the value. A
   thin grip shows at the fill's edge while the pointer or the keyboard is on it. */
export function PreviewSlider({
  id,
  label,
  value,
  min,
  max,
  step = 1,
  unit = "",
  onChange,
}: {
  id: string
  label: string
  value: number
  min: number
  max: number
  step?: number
  unit?: string
  onChange: (value: number) => void
}) {
  return (
    <Slider
      data-control={id}
      aria-label={label}
      className={cn(well, focus, "group/scrub overflow-hidden")}
      value={value}
      min={min}
      max={max}
      step={step}
      onValueChange={(next) => onChange(Array.isArray(next) ? next[0] : (next as number))}
    >
      {/* UI SDK positions the track, the fill and the thumb itself, so the track only needs a size. */}
      <SliderControl className="absolute inset-0 cursor-ew-resize touch-pan-y">
        <SliderTrack className="block h-9 w-full">
          <SliderIndicator className="bg-foreground/[0.09] dark:bg-foreground/[0.11]" />
          <SliderThumb aria-label={label} className="h-4 w-[3px] rounded-full bg-foreground/60 opacity-0 group-hover/scrub:opacity-100 has-[:focus-visible]:opacity-100 data-dragging:opacity-100" />
        </SliderTrack>
      </SliderControl>
      <span className={name}>{label}</span>
      <span className={amount}>
        {trim(value)}
        {unit}
      </span>
    </Slider>
  )
}

export function PreviewSwitch({
  id,
  label,
  checked,
  onChange,
}: {
  id: string
  label: string
  checked: boolean
  onChange: (checked: boolean) => void
}) {
  return (
    <label data-control={id} className={cn(well, focus, "cursor-pointer")}>
      <span className={cn(name, "pointer-events-auto")}>{label}</span>
      <span className="relative z-10 ms-auto flex shrink-0 items-center pe-2.5">
        <Switch aria-label={label} checked={checked} onCheckedChange={(next) => onChange(Boolean(next))} />
      </span>
    </label>
  )
}

export function PreviewSelect({
  id,
  label,
  value,
  options,
  onChange,
}: {
  id: string
  label: string
  value: string
  options: readonly string[]
  onChange: (value: string) => void
}) {
  return (
    <Select value={value} onValueChange={(next) => typeof next === "string" && onChange(next)}>
