  className,
  style,
  ...props
}: React.ComponentProps<typeof DialogContentPart>) {
  return (
    <DialogContentPart
      className={withClass(
        cn(
          "fixed inset-0 m-auto h-fit max-h-[calc(100dvh-32px)] w-[min(var(--dialog-width,440px),calc(100vw-32px))] max-w-none overflow-y-auto overscroll-contain",
