      case "submenu":
        return (
          <MenuSub key={`submenu-${index}`}>
            <MenuSubTrigger disabled={item.disabled}>{item.label}</MenuSubTrigger>
            <MenuSubContent>
              <MenuItems items={item.items} />
            </MenuSubContent>
          </MenuSub>
        )
    }
  })
}

