  double: { bl: "╚", br: "╝", h: "═", tl: "╔", tr: "╗", v: "║", x: "╬" },
  heavy: { bl: "┗", br: "┛", h: "━", tl: "┏", tr: "┓", v: "┃", x: "╋" },
  light: { bl: "└", br: "┘", h: "─", tl: "┌", tr: "┐", v: "│", x: "┼" },
  rounded: { bl: "╰", br: "╯", h: "─", tl: "╭", tr: "╮", v: "│", x: "┼" },
