 */
export interface AsciiSceneProps
  extends AsciiLook, Omit<ComponentProps<"div">, "children"> {
  /** Cell height in CSS pixels. Default `--ascii-cell`, or the scene's own. */
  cell?: number;
  /** Time multiplier. Default 1. */
  speed?: number;
