 */
/** A colour as red, green, blue and alpha, each in [0, 1]. */
export type Rgba = readonly [number, number, number, number];

/**
 * The named colours of the asciicn palette. `ink` is the theme's own
 * `--ascii-ink`; the others are `--ascii-color-<name>` from the
 * `ascii-tokens` stylesheet, tuned separately for light and dark.
 */
export const ASCII_COLOR_NAMES = [
  "ink",
  "blue",
  "purple",
  "green",
  "pink",
  "orange",
  "red",
  "grey",
] as const;

export type AsciiColorName = (typeof ASCII_COLOR_NAMES)[number];

/**
 * Used when a named colour's variable is missing, as in a stylesheet from
 * before the palette existed. Mid lightness, so it reads on black and white.
 */
const FALLBACKS = {
  blue: "oklch(0.64 0.16 245)",
  green: "oklch(0.68 0.16 152)",
  grey: "oklch(0.6 0 0)",
  ink: "oklch(0.6 0.2 270)",
  orange: "oklch(0.72 0.16 58)",
  pink: "oklch(0.66 0.19 352)",
  purple: "oklch(0.62 0.2 302)",
  red: "oklch(0.62 0.21 26)",
} as const satisfies Record<AsciiColorName, string>;

/** The CSS variable behind each named colour. */
export const ASCII_COLORS = {
  blue: "--ascii-color-blue",
  green: "--ascii-color-green",
  grey: "--ascii-color-grey",
  ink: "--ascii-ink",
  orange: "--ascii-color-orange",
  pink: "--ascii-color-pink",
  purple: "--ascii-color-purple",
  red: "--ascii-color-red",
} as const satisfies Record<AsciiColorName, `--${string}`>;

/**
 * A colour asciicn components accept: a palette name such as
 * `"green"`, a CSS variable name such as `"--ascii-ink"`, or any CSS
 * colour such as `"var(--chart-1)"`, `"oklch(0.7 0.15 272)"` or `"#fff"`.
 * Palette names win over the CSS keywords they share (`"red"` is the
 * asciicn red, not `#f00`).
 */
// oxlint-disable-next-line typescript/ban-types -- `string & {}` keeps editor autocomplete for the names.
export type AsciiColor = AsciiColorName | (string & {});

/** Colours from tone 0 (paper) to tone 1 (ink). At least two. */
export type AsciiPalette = readonly [AsciiColor, AsciiColor, ...AsciiColor[]];

/** Paper to ink, from the `ascii-tokens` CSS variables. */
export const DEFAULT_PALETTE = [
  "--ascii-paper",
  "--ascii-ink",
] as const satisfies AsciiPalette;

const isColorName = (value: string): value is AsciiColorName =>
  Object.hasOwn(ASCII_COLORS, value);

/**
 * A CSS colour for any `AsciiColor`: `"green"` becomes
 * `"var(--ascii-color-green, <fallback>)"`, `"--chart-1"` becomes `"var(--chart-1)"`,
 * and anything else passes through.
 */
export const cssColor = (value: AsciiColor): string => {
  if (isColorName(value)) {
    return `var(${ASCII_COLORS[value]}, ${FALLBACKS[value]})`;
  }
  return value.startsWith("--") ? `var(${value})` : value;
};

/**
 * Motion tokens shared by every component: one ease-out curve and three
 * durations in milliseconds. `ease` matches the site's `--ease-out`.
 */
export const MOTION = {
  base: 240,
  ease: "cubic-bezier(0.23, 1, 0.32, 1)",
  fast: 150,
  slow: 600,
} as const;

# Export

`ascii-export` (`lib/ascii/export.ts`) turns what a renderer drew into files. When this file and the code disagree, the code wins.

## Get the frame

Every renderer and component takes a `handle` ref. The engine fills it with an `AsciiHandle`:

```tsx
"use client";

import { useRef } from "react";

import type { AsciiHandle } from "@/lib/ascii";
import { copyText, toText } from "@/lib/ascii/export";

export const Exportable = () => {
  const handle = useRef<AsciiHandle | null>(null);
  const copy = () => {
    const frame = handle.current?.capture();
    if (frame) {
      void copyText(toText(frame, { trimEnd: true }));
    }
  };
  return (
    <div className="relative h-80">
      <MyBackground handle={handle} className="absolute inset-0" />
      <button type="button" onClick={copy} className="relative">
        Copy as text
      </button>
    </div>
  );
};
```

`handle.current` has `capture()` (the current `AsciiFrame`: `columns`, `rows`, `glyphs`, `colors`), `canvas`, `colors()` (the resolved ink and paper) and `metrics()` (the `CellMetrics`). The GPU renderer reads back the glyphs it drew, so exported text is exactly what is on screen.

## Formats

| Function                                                          | Returns            | Notes                                                                                                                                                   |
| ----------------------------------------------------------------- | ------------------ | ------------------------------------------------------------------------------------------------------------------------------------------------------- |
| `toText(frame, { trimEnd })`                                      | `string`           | Plain text, one line per row                                                                                                                            |
| `toAnsi(frame, { mode, ansi, ink, paper, background })`           | `string`           | ANSI escape codes. `mode: "truecolor"` (24-bit, default) or `"ansi16"` (snapped to `ansi`: `vga` or `xterm`). Save as `.ans`, or `cat` it in a terminal |
| `toSvg(frame, { metrics, ink, paper, font, shapes })`             | `string`           | Blocks, shades, Braille, box lines and dots become vector shapes (`shapes`, default true); other glyphs are text                                        |
| `toPng(handleOrFrameOrCanvas, { scale, ink, paper, cell, font })` | `Promise<Blob>`    | A handle without `scale` saves the live canvas, CRT effects included; otherwise the frame is re-rendered                                                |
| `recordCanvas(canvas, { durationMs, fps, mimeType })`             | `Promise<Blob>`    | Records the live canvas. `createRecorder(canvas, options)` gives a start/stop recorder for a button                                                     |
| `pickVideoType()`, `videoExtension(type)`                         | `string`           | The first video type the browser can record (WebM first, MP4 in Safari) and its extension                                                               |
| `downloadBlob(blob, name)`, `downloadText(text, name)`            | `void`             | Saves a file                                                                                                                                            |
| `copyText(text)`                                                  | `Promise<boolean>` | Clipboard; resolves `false` when the browser refuses                                                                                                    |

`handle.current.colors()` returns the ink and paper on screen as CSS colours; pass them to `toSvg` and `toPng` so the file matches the theme. `toAnsi` needs `#rrggbb` strings or `[r, g, b]` bytes: convert a CSS colour with `resolveColor` (RGBA from 0 to 1) and scale by 255.

## Static art on the server

`frameToText(frame)` and `AsciiPre` work without a browser, so a frame computed with `createToneField` and `mapTones` can be rendered into a server component, an email, a README or an RSS feed.

## Checks

- Export from a frame that has finished drawing: call `capture()` after the first frame (the root's `data-state` is no longer `fallback`).
- Recording needs `MediaRecorder` and `canvas.captureStream`. Show the record button only when `pickVideoType()` returns a type, and name the file with `videoExtension(type)`: Safari may record MP4 instead of WebM.
- `.ans` files read correctly in terminals that support the chosen mode. Use `ansi16` for maximum compatibility.

# Recipes

Complete components to adapt. Each one is a starting point: change the field, the charset and the props to fit what the user asked for. Imports use `@/lib/ascii`; use the project's alias.

## A shader background

A slow, theme-coloured field with the engine's look props passed through, so the user (or a Studio) can switch charset and colours, and a `handle` for export.

```tsx
"use client";

import type { AsciiSceneProps } from "@/lib/ascii";
import { AsciiShader } from "@/lib/ascii/shader";

const FIELD = /* glsl */ `
float field(vec2 uv, vec2 res, float t) {
  vec2 p = vec2(uv.x * res.x / res.y, uv.y);
  float drift = fbm(p * 1.6 + vec2(t * 0.03, t * 0.01));
  float bands = 0.5 + 0.5 * sin((p.y + drift * 0.8) * 9.0 - t * 0.2);
  float tone = smoothstep(0.15, 0.95, bands * drift * 1.6) * smoothstep(0.0, 0.25, uv.y);
  return tone * tideIntensity;
}`;

export interface TideBackgroundProps extends AsciiSceneProps {
  /** How strong the pattern is, 0 to 1. Default 0.9. */
  intensity?: number;
}

export const TideBackground = ({
  intensity = 0.9,
  charset = "braille",
  colorMode = "mono",
  stillTime = 6,
  ...props
}: TideBackgroundProps) => (
  <AsciiShader
    field={FIELD}
    uniforms={{ tideIntensity: intensity }}
    charset={charset}
    colorMode={colorMode}
    stillTime={stillTime}
    {...props}
  />
);
```

Every uniform you pass must be read in the field, or the compiler drops it and the engine warns.

## A hero that clears its headline

Measure the text block and clear a rounded box around it, so the headline sits on clean ground at every width.

```tsx
"use client";

import { useEffect, useRef, useState } from "react";

import { AsciiShader } from "@/lib/ascii/shader";

const FIELD = /* glsl */ `
float heroBox(vec2 p, vec4 box, float radius) {
  vec2 centre = box.xy + box.zw * 0.5;
  vec2 d = abs(p - centre) - box.zw * 0.5 + radius;
  return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0) - radius;
}

float field(vec2 uv, vec2 res, float t) {
  float aspect = res.x / res.y;
  vec2 p = vec2(uv.x * aspect, uv.y);
  float rings = 0.5 + 0.5 * sin(length(p - vec2(aspect * 0.8, 0.2)) * 28.0 - t * 0.6);
  float glyphs = smoothstep(0.35, 1.0, rings) * (0.4 + 0.6 * fbm(p * 2.0 + t * 0.02));
  // heroText is the text block in the same square units, y up.
  vec4 box = vec4(heroText.x * aspect, heroText.y, heroText.z * aspect, heroText.w);
  float clear = smoothstep(0.0, 0.08, heroBox(p, box, 0.04));
  return glyphs * clear;
}`;

export const Hero = () => {
  const section = useRef<HTMLElement>(null);
  const text = useRef<HTMLDivElement>(null);
  const [box, setBox] = useState<[number, number, number, number]>([
    0, 0, 0, 0,
  ]);

  useEffect(() => {
    const measure = () => {
      const outer = section.current?.getBoundingClientRect();
      const inner = text.current?.getBoundingClientRect();
      if (!(outer && inner && outer.width && outer.height)) {
        return;
      }
      // uv space: x and width over the section width, y up from the bottom.
      setBox([
        (inner.left - outer.left) / outer.width,
        (outer.bottom - inner.bottom) / outer.height,
        inner.width / outer.width,
        inner.height / outer.height,
      ]);
    };
    measure();
    const observer = new ResizeObserver(measure);
    if (section.current) {
      observer.observe(section.current);
    }
    return () => observer.disconnect();
  }, []);

  return (
    <section ref={section} className="relative isolate overflow-hidden">
      <AsciiShader
        field={FIELD}
        uniforms={{ heroText: box }}
        charset="standard"
        className="absolute inset-0 -z-10"
      />
      <div
        ref={text}
        className="relative mx-auto max-w-2xl px-6 py-32 text-center"
      >
        <h1 className="text-5xl font-semibold tracking-tight">
          Ship logs you can read
        </h1>
        <p className="text-muted-foreground mt-4 text-lg">
          One sentence about the product.
        </p>
      </div>
    </section>
  );
};
```

## A spinning object on the CPU

A torus shaded with a light, drawn into an `AsciiGrid` through `mapTones`. The same pattern draws any 3D mesh, heightmap or simulation: compute a tone per sample, then map.

```tsx
"use client";

import { useRef } from "react";

import {
  AsciiGrid,
  createToneField,
  mapTones,
  resolveCharset,
} from "@/lib/ascii";
import type { AsciiGridDrawContext, CharsetName, ToneField } from "@/lib/ascii";

export interface SpinningTorusProps {
  /** Glyph set. Default `"standard"`. */
  charset?: CharsetName;
  /** Cell height in CSS px. Default `--ascii-cell`. */
  cell?: number;
  className?: string;
}

export const SpinningTorus = ({
  charset = "standard",
  cell,
  className,
}: SpinningTorusProps) => {
  const fieldRef = useRef<ToneField | null>(null);
  const depthRef = useRef(new Float32Array(0));

  const draw = ({
    frame,
    columns,
    rows,
    time,
    metrics,
  }: AsciiGridDrawContext) => {
    const set = resolveCharset(charset);
    const [gx, gy] = set.grid;
    let field = fieldRef.current;
    if (!field || field.width !== columns * gx || field.height !== rows * gy) {
      field = createToneField(columns, rows, set);
      fieldRef.current = field;
      depthRef.current = new Float32Array(field.tones.length);
    }
    field.tones.fill(0);
    const depth = depthRef.current;
    depth.fill(0);
    const a = time * 0.7;
    const b = time * 0.4;
    // Sample aspect: cells are metrics.width wide and metrics.height tall.
    const aspect =
      (field.width * metrics.width) /
      gx /
      ((field.height * metrics.height) / gy);
    for (let theta = 0; theta < 6.283; theta += 0.04) {
      for (let phi = 0; phi < 6.283; phi += 0.015) {
        const circle = 2 + Math.cos(theta);
        const x0 = circle * Math.cos(phi);
        const y0 = Math.sin(theta);
        const z0 = circle * Math.sin(phi);
        const y = y0 * Math.cos(a) - z0 * Math.sin(a);
        const z1 = y0 * Math.sin(a) + z0 * Math.cos(a);
        const x = x0 * Math.cos(b) - z1 * Math.sin(b);
        const z = 6 + x0 * Math.sin(b) + z1 * Math.cos(b);
        const inv = 1 / z;
        const u = 0.5 + (x * inv * 1.4) / aspect;
        const v = 0.5 - y * inv * 1.4;
        const sx = Math.floor(u * field.width);
        const sy = Math.floor(v * field.height);
        if (sx < 0 || sy < 0 || sx >= field.width || sy >= field.height) {
          continue;
        }
        const i = sy * field.width + sx;
        if (inv > (depth[i] ?? 0)) {
          depth[i] = inv;
          const nx = Math.cos(theta) * Math.cos(phi);
          const ny = Math.sin(theta);
          const light = Math.max(0, nx * 0.5 + ny * 0.7 + 0.3);
          field.tones[i] = 0.15 + 0.85 * light;
        }
      }
    }
    mapTones(field, columns, rows, { charset: set }, frame);
  };

  return (
    <AsciiGrid draw={draw} cell={cell} stillTime={1.2} className={className} />
  );
};
```

## A Braille trace

A line through a list of values: a waveform, a CPU trace in a terminal pane, the height profile of a route. Two dots across and four down per glyph make the line four times sharper than one glyph per point. Draw it with `brailleChar`, and keep the numbers in HTML.

```tsx
"use client";

import { AsciiGrid, BRAILLE_DOT_BITS, brailleChar } from "@/lib/ascii";
import type { AsciiGridDrawContext } from "@/lib/ascii";

export interface BrailleTraceProps {
  /** Values in any range; the trace scales to min and max. */
  data: readonly number[];
  /** Text equivalent for screen readers, such as "Requests per minute, last hour: 120 to 340". */
  label: string;
  className?: string;
}

export const BrailleTrace = ({ data, label, className }: BrailleTraceProps) => {
  const draw = ({ frame, columns, rows }: AsciiGridDrawContext) => {
    const width = columns * 2;
    const height = rows * 4;
    const masks = new Uint8Array(columns * rows);
    const min = Math.min(...data);
    const span = Math.max(...data) - min || 1;
    const yAt = (x: number) => {
      const t = (x / (width - 1)) * (data.length - 1);
      const i = Math.floor(t);
      const value =
        (data[i] ?? 0) +
        ((data[i + 1] ?? data[i] ?? 0) - (data[i] ?? 0)) * (t - i);
      return Math.round((1 - (value - min) / span) * (height - 1));
    };
    for (let x = 0; x < width; x += 1) {
      const y0 = yAt(x);
      const y1 = x + 1 < width ? yAt(x + 1) : y0;
      // Fill the vertical gap so steep segments stay connected.
      for (let y = Math.min(y0, y1); y <= Math.max(y0, y1); y += 1) {
        const cell = Math.floor(y / 4) * columns + Math.floor(x / 2);
        masks[cell] =
          (masks[cell] ?? 0) | (BRAILLE_DOT_BITS[y % 4]?.[x % 2] ?? 0);
      }
    }
    masks.forEach((mask, i) => {
      if (mask) {
        frame.put(i % columns, Math.floor(i / columns), brailleChar(mask));
      }
    });
  };

  return (
    <AsciiGrid
      draw={draw}
      animate={false}
      role="img"
      aria-hidden={false}
      aria-label={label}
      className={className}
    />
  );
};
```

