"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import type {
  ComponentProps,
  CSSProperties,
  FocusEvent,
  PointerEvent,
  RefObject,
} from "react";

import {
  AsciiMedia,
  splitLook,
  useLoadedImage,
} from "@/components/asciicn/ascii-image";
import type { MediaDrawContext } from "@/components/asciicn/ascii-image";
import {
  AsciiGrid,
  resolveCharset,
  useInView,
  usePrefersReducedMotion,
} from "@/lib/ascii";
import type {
  AsciiColor,
  AsciiGridDrawContext,
  AsciiHandle,
  AsciiLook,
  Charset,
  MutableFrame,
} from "@/lib/ascii";
import { cn } from "@/lib/utils";

/**
 * What starts the reveal.
 * - `view`: once, when the image scrolls into view.
 * - `hover`: on hover or focus, and back to glyphs on leave. A tap toggles it.
 * - `manual`: follows the `revealed` prop.
 */
export const REVEAL_TRIGGERS = ["view", "hover", "manual"] as const;
export type RevealTrigger = (typeof REVEAL_TRIGGERS)[number];

/** Which way the handover edge travels. */
export const REVEAL_DIRECTIONS = [
  "down",
  "up",
  "left",
  "right",
  "radial",
  "random",
] as const;
export type RevealDirection = (typeof REVEAL_DIRECTIONS)[number];

export interface AsciiRevealProps
  extends AsciiLook, Omit<ComponentProps<"div">, "children"> {
  /** Image URL. Cross-origin files need CORS headers, or the glyphs can't be sampled. */
  src: string;
  /** What the image shows, passed to the `<img>`. `""` marks it decorative. */
  alt: string;
  /** What starts the reveal. Default `"view"`. */
  trigger?: RevealTrigger;
  /** With `trigger="manual"`: show the photo. Default `false`. */
  revealed?: boolean;
  /** Which way the handover edge travels. Default `"down"`. */
  direction?: RevealDirection;
  /** Length of one full sweep in milliseconds. Default 2400. */
  duration?: number;
  /** Default `"standard"`. */
  charset?: AsciiLook["charset"];
  /** Default `"mono"`. */
  colorMode?: AsciiLook["colorMode"];
  /** Colour of the glyphs that scramble at the edge. Default `"orange"`, the amber accent. */
  accent?: AsciiColor;
  /** Width over height of the box. Default: the image's own ratio once it loads, 4/3 before. */
  ratio?: number;
  /** Cell height in CSS pixels. Default 9. */
  cell?: number;
  /** `false` swaps states without a sweep, as reduced motion does. Default `true`. */
  animate?: boolean;
  /** Passed to the image requests. Default `"anonymous"`. */
  crossOrigin?: ComponentProps<"img">["crossOrigin"];
  /** Filled with a handle for export of the glyph layer. */
  handle?: RefObject<AsciiHandle | null>;
}

/**
 * How wide the handover band is, as a share of the sweep. A random
 * dissolve has no single front, so its band runs wider to stay readable.
 */
const BANDS = {
  down: 0.1,
  left: 0.1,
  radial: 0.1,
  random: 0.2,
  right: 0.1,
  up: 0.1,
} as const satisfies Record<RevealDirection, number>;

// A short beat of glyphs before a `view` reveal starts, so it reads as one.
const VIEW_HOLD_MS = 450;

const clamp01 = (value: number) => Math.min(1, Math.max(0, value));

const smoothstep = (edge0: number, edge1: number, value: number) => {
  const t = clamp01((value - edge0) / (edge1 - edge0));
  return t * t * (3 - 2 * t);
};

// Sine in and out: the edge never rushes, even mid-sweep.
const easeInOut = (t: number) => (1 - Math.cos(Math.PI * clamp01(t))) / 2;

const hash = (x: number, y: number) => {
  const value = Math.sin(x * 127.1 + y * 311.7) * 43_758.5453;
  return value - Math.floor(value);
};

/** Smooth value noise in one dimension, for a front that bends gently. */
const wave = (x: number, seed: number) => {
  const cell = Math.floor(x);
  const t = x - cell;
  const eased = t * t * (3 - 2 * t);
  return hash(cell, seed) * (1 - eased) + hash(cell + 1, seed) * eased;
};

/** Smooth value noise in two dimensions, so a dissolve comes in patches. */
const patches = (x: number, y: number) => {
  const cx = Math.floor(x);
  const cy = Math.floor(y);
  const tx = x - cx;
  const ty = y - cy;
  const ex = tx * tx * (3 - 2 * tx);
  const ey = ty * ty * (3 - 2 * ty);
  const top = hash(cx, cy) * (1 - ex) + hash(cx + 1, cy) * ex;
  const bottom = hash(cx, cy + 1) * (1 - ex) + hash(cx + 1, cy + 1) * ex;
  return top * (1 - ey) + bottom * ey;
};

const popcount = (value: number) => {
  let bits = 0;
  for (let rest = value; rest > 0; rest = Math.floor(rest / 2)) {
    bits += rest % 2;
  }
  return bits;
};

/**
 * How much ink each glyph of a charset carries, 0 to 1. Ramps run from
 * empty to dense by position. Braille and quadrant glyphs are indexed by
 * dot mask, so their ink is the share of dots lit.
 */
const glyphInk = (charset: Charset): ReadonlyMap<string, number> => {
  const ink = new Map<string, number>();
  const { glyphs, kind } = charset;
  const packed = kind === "braille" || kind === "quadrants";
  const dots = kind === "braille" ? 8 : 4;
  for (const [index, glyph] of glyphs.entries()) {
    if (!ink.has(glyph)) {
      ink.set(
        glyph,
        packed ? popcount(index) / dots : index / Math.max(1, glyphs.length - 1)
      );
    }
  }
  return ink;
};

/** A glyph of about `ink` density, varied by `pick` so the edge flickers. */
const scrambleGlyph = (charset: Charset, ink: number, pick: number): string => {
  const { glyphs, kind } = charset;
  if (kind === "braille" || kind === "quadrants") {
    // Light each dot with the cell's ink as its odds.
    const dots = kind === "braille" ? 8 : 4;
    let mask = 0;
    for (let dot = 0; dot < dots; dot += 1) {
      if (hash(pick * 91.7 + dot, dot * 3.1) < ink) {
        mask += 2 ** dot;
      }
    }
    return glyphs[mask] ?? " ";
  }
  const top = glyphs.length - 1;
  const level = Math.round(ink * top + (pick - 0.5) * 4);
  return glyphs[Math.min(top, Math.max(1, level))] ?? " ";
};

/**
 * When each cell hands over, from 0 (first) to 1 (last). Straight sweeps
 * get a gently bent front with a little grain, so cells lock in one by
 * one instead of in ruled lines.
 */
const cellOrder = (
  direction: RevealDirection,
  columns: number,
  rows: number,
  cellWidth: number,
  cellHeight: number,
  out: Float32Array
): void => {
  const halfWidth = (columns * cellWidth) / 2;
  const halfHeight = (rows * cellHeight) / 2;
  const reach = Math.hypot(halfWidth, halfHeight) || 1;
  let low = Infinity;
  let high = -Infinity;
  for (let row = 0; row < rows; row += 1) {
    const v = (row + 0.5) / rows;
    for (let column = 0; column < columns; column += 1) {
      const u = (column + 0.5) / columns;
      const grain = hash(column, row);
      let order = grain;
      if (direction === "down" || direction === "up") {
        const along = direction === "down" ? v : 1 - v;
        order = along * 0.82 + wave(u * 3.2, 7) * 0.11 + grain * 0.07;
      } else if (direction === "left" || direction === "right") {
        const along = direction === "right" ? u : 1 - u;
        order = along * 0.82 + wave(v * 3.2, 11) * 0.11 + grain * 0.07;
      } else if (direction === "radial") {
        const dx = (column + 0.5) * cellWidth - halfWidth;
        const dy = (row + 0.5) * cellHeight - halfHeight;
        order = (Math.hypot(dx, dy) / reach) * 0.86 + grain * 0.14;
      } else {
        order = patches(u * 4.5, v * 4.5) * 0.6 + grain * 0.4;
      }
      out[row * columns + column] = order;
      low = Math.min(low, order);
      high = Math.max(high, order);
    }
  }
  const span = high - low || 1;
  for (let index = 0; index < out.length; index += 1) {
    out[index] = ((out[index] ?? 0) - low) / span;
  }
};

/** Where every cell is in its handover this frame, shared by the layers. */
interface SweepState {
  /** Linear progress of the sweep, 0 (glyphs) to 1 (photo). */
  value: number;
  /** When `value` last advanced, from `performance.now()`. */
  at: number;
  key: string;
  order: Float32Array;
  /** Per cell: at or below 0 still glyphs, 0 to 1 handing over, 1 photo. */
  phase: Float32Array;
  /** Per cell: the ink of the glyph it held, so the edge keeps the picture. */
  ink: Float32Array;
  columns: number;
  rows: number;
  /** One pixel per cell, scaled up to mask the photo. */
  mask: HTMLCanvasElement | null;
}

/**
 * An image that resolves out of glyphs. It starts as the picture in
 * ASCII, sampled from the photo, then cells lock in and hand over to the
 * real image along a sweep. Glyphs scramble in the accent colour at the
 * edge; behind it the photo shows, ahead of it the glyphs hold.
 */
// oxlint-disable-next-line complexity -- each prop default counts as a branch.
export const AsciiReveal = (props: AsciiRevealProps) => {
  const [
    look,
    {
      src,
      alt,
      trigger = "view",
      revealed = false,
      direction = "down",
      duration = 2400,
      accent = "orange",
      ratio,
      cell = 9,
      animate = true,
      crossOrigin = "anonymous",
      handle,
      className,
      style,
      onPointerEnter,
      onPointerLeave,
      onPointerDown,
      onFocus,
      onBlur,
      ...rest
    },
  ] = splitLook(props);
  const charset = look.charset ?? "standard";
  const colorMode = look.colorMode ?? "mono";
  const resolved = resolveCharset(charset, look.chars);
  const inkMap = useMemo(
    () => glyphInk(resolveCharset(charset, look.chars)),
    [charset, look.chars]
  );
  const reducedMotion = usePrefersReducedMotion();
  const still = reducedMotion || !animate;

  const rootRef = useRef<HTMLDivElement>(null);
  const photoRef = useRef<HTMLCanvasElement>(null);
  const sweepRef = useRef<SweepState>({
    at: 0,
    columns: 0,
    ink: new Float32Array(0),
    key: "",
    mask: null,
    order: new Float32Array(0),
    phase: new Float32Array(0),
    rows: 0,
    value: 0,
  });

  // Load the photo for sampling only once the box is near the viewport.
  const near = useInView(rootRef, { rootMargin: "320px" });
  const [armed, setArmed] = useState(false);
  useEffect(() => {
    if (near) {
      setArmed(true);
    }
  }, [near]);
  const image = useLoadedImage(armed ? src : null, crossOrigin);
  const ready = image.status === "ready";

  // `view`: reveal once, when enough of the box is on screen.
  const [seen, setSeen] = useState(false);
  useEffect(() => {
    const root = rootRef.current;
    if (trigger !== "view" || !root || seen) {
      return;
    }
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (!entry?.isIntersecting) {
          return;
        }
        const tall = entry.intersectionRect.height >= window.innerHeight * 0.5;
        if (entry.intersectionRatio >= 0.35 || tall) {
          setSeen(true);
          observer.disconnect();
        }
      },
      { threshold: [0, 0.2, 0.35, 0.5] }
    );
    observer.observe(root);
    return () => observer.disconnect();
  }, [trigger, seen]);

  const [hovered, setHovered] = useState(false);
  const [held, setHeld] = useState(false);
  useEffect(() => {
    if (!(trigger === "view" && seen && ready) || still) {
      setHeld(false);
      return;
    }
    const timer = window.setTimeout(() => setHeld(true), VIEW_HOLD_MS);
    return () => window.clearTimeout(timer);
  }, [trigger, seen, ready, still]);

  let wanted = false;
  if (trigger === "manual") {
    wanted = revealed;
  } else if (trigger === "hover") {
    wanted = hovered;
  } else {
    // Under reduced motion a `view` reveal shows its final state outright.
    wanted = still || held;
  }
  const target = ready && wanted ? 1 : 0;

  const [moving, setMoving] = useState(false);
  // Where the sweep last came to rest. The <img> shows only at rest on 1.
  const [restingAt, setRestingAt] = useState(0);
  useEffect(() => {
    const sweep = sweepRef.current;
    if (still) {
      sweep.value = target;
      setMoving(false);
      setRestingAt(target);
      return;
    }
    if (sweep.value !== target) {
      sweep.at = performance.now();
      setMoving(true);
    }
  }, [target, still]);

  /** Step the sweep towards the target. Safe to call twice in a frame. */
  const advance = () => {
    const sweep = sweepRef.current;
    const now = performance.now();
    if (still) {
      sweep.value = target;
    } else {
      const elapsed = Math.min(100, Math.max(0, now - sweep.at));
      const step = elapsed / Math.max(1, duration);
      sweep.value =
        target > sweep.value
          ? Math.min(target, sweep.value + step)
          : Math.max(target, sweep.value - step);
    }
    sweep.at = now;
    return sweep;
  };

  /** Draw the photo through a one-pixel-per-cell mask of the handed-over cells. */
  const paintPhoto = (sweep: SweepState, context: MediaDrawContext) => {
    const canvas = photoRef.current;
    const drawable = canvas?.getContext("2d");
    if (!(canvas && drawable && image.status === "ready")) {
      return;
    }
    const { metrics, box, columns, rows } = context;
    const width = Math.max(1, Math.round(box.width * metrics.dpr));
    const height = Math.max(1, Math.round(box.height * metrics.dpr));
    if (canvas.width !== width || canvas.height !== height) {
      canvas.width = width;
      canvas.height = height;
    }
    drawable.globalCompositeOperation = "source-over";
    drawable.clearRect(0, 0, width, height);
    if (sweep.value <= 0) {
      return;
    }
    // Cover the box, centred, the way the <img> does with object-fit.
    const { source } = image;
    const scale = Math.max(width / source.width, height / source.height);
    const drawWidth = source.width * scale;
    const drawHeight = source.height * scale;
    drawable.imageSmoothingEnabled = true;
    drawable.imageSmoothingQuality = "high";
    drawable.drawImage(
      source.element,
      (width - drawWidth) / 2,
      (height - drawHeight) / 2,
      drawWidth,
      drawHeight
    );
    if (sweep.value >= 1) {
      return;
    }
    // One extra column and row cover the strip past the last whole cell.
    const maskWidth = columns + 1;
    const maskHeight = rows + 1;
    const mask = sweep.mask ?? document.createElement("canvas");
    sweep.mask = mask;
    if (mask.width !== maskWidth || mask.height !== maskHeight) {
      mask.width = maskWidth;
      mask.height = maskHeight;
    }
    const maskContext = mask.getContext("2d");
    if (!maskContext) {
      return;
    }
    const pixels = maskContext.createImageData(maskWidth, maskHeight);
    for (let row = 0; row < maskHeight; row += 1) {
      const sourceRow = Math.min(row, rows - 1);
      for (let column = 0; column < maskWidth; column += 1) {
        const sourceColumn = Math.min(column, columns - 1);
        const phase = sweep.phase[sourceRow * columns + sourceColumn] ?? 0;
        pixels.data[(row * maskWidth + column) * 4 + 3] = Math.round(
          smoothstep(0.45, 0.95, phase) * 255
        );
      }
    }
    maskContext.putImageData(pixels, 0, 0);
    drawable.globalCompositeOperation = "destination-in";
    // A smoothed mask softens the photo's edge by about a cell, so the
    // handover reads as glyphs dissolving, not as square pixels.
    drawable.imageSmoothingEnabled = true;
    drawable.drawImage(
      mask,
      0,
      0,
      maskWidth * metrics.deviceWidth,
      maskHeight * metrics.deviceHeight
    );
    drawable.globalCompositeOperation = "source-over";
  };

  // Glyphs ahead of the edge hold; at and behind it they clear for the photo.
  const finish = (frame: MutableFrame, context: MediaDrawContext) => {
    const sweep = advance();
    const { columns, rows, metrics } = context;
    const size = columns * rows;
    const key = [direction, columns, rows, metrics.width, metrics.height].join(
      "|"
    );
    if (sweep.key !== key) {
      sweep.key = key;
      sweep.order = new Float32Array(size);
      sweep.phase = new Float32Array(size);
      sweep.ink = new Float32Array(size);
      sweep.columns = columns;
      sweep.rows = rows;
      cellOrder(
        direction,
        columns,
        rows,
        metrics.width,
        metrics.height,
        sweep.order
      );
    }
    const band = BANDS[direction];
    const front = easeInOut(sweep.value) * (1 + band);
    const { order, phase, value } = sweep;
    for (let index = 0; index < size; index += 1) {
      let cellPhase = value >= 1 ? 1 : 0;
      if (value > 0 && value < 1) {
        cellPhase = (front - (order[index] ?? 0)) / band;
      }
      phase[index] = cellPhase;
      if (cellPhase > 0) {
        if (cellPhase < 1) {
          sweep.ink[index] = inkMap.get(frame.glyphs[index] ?? " ") ?? 0.6;
        }
        frame.glyphs[index] = " ";
      }
    }
    paintPhoto(sweep, context);
    if (value === target) {
      setMoving(false);
      setRestingAt(target);
    }
  };

  // The edge: cells mid-handover flicker through glyphs in the accent
  // colour, about as dense as the glyph they held, thinning as they lock in.
  const drawEdge = ({ frame, columns, rows }: AsciiGridDrawContext) => {
    const sweep = sweepRef.current;
    if (
      sweep.columns !== columns ||
      sweep.rows !== rows ||
      sweep.value <= 0 ||
      sweep.value >= 1
    ) {
      return;
    }
    // A new glyph about every 80ms reads as a flicker, not as noise.
    const tick = Math.floor(performance.now() / 80);
    for (let index = 0; index < sweep.phase.length; index += 1) {
      const phase = sweep.phase[index] ?? 0;
      if (phase <= 0 || phase >= 0.85) {
        continue;
      }
      const ink = sweep.ink[index] ?? 0;
      if (ink <= 0) {
        continue;
      }
      const pick = hash(index * 0.37 + tick * 1.7, tick * 0.13);
      const fade = 1 - smoothstep(0.15, 0.85, phase) * 0.75;
      frame.glyphs[index] = scrambleGlyph(resolved, ink * fade, pick);
    }
  };

  /* Hover and focus -------------------------------------------------------- */

  const hover = trigger === "hover";
  const handleEnter = (event: PointerEvent<HTMLDivElement>) => {
    onPointerEnter?.(event);
    if (hover && event.pointerType === "mouse") {
      setHovered(true);
    }
  };
  const handleLeave = (event: PointerEvent<HTMLDivElement>) => {
    onPointerLeave?.(event);
    if (hover && event.pointerType === "mouse") {
      setHovered(false);
    }
  };
  // Touch has no hover, so a tap toggles the photo.
  const handleDown = (event: PointerEvent<HTMLDivElement>) => {
    onPointerDown?.(event);
    if (hover && event.pointerType !== "mouse") {
      setHovered((value) => !value);
    }
  };
  const handleFocus = (event: FocusEvent<HTMLDivElement>) => {
    onFocus?.(event);
    if (hover) {
      setHovered(true);
    }
  };
  const handleBlur = (event: FocusEvent<HTMLDivElement>) => {
    onBlur?.(event);
    const next = event.relatedTarget;
    if (
      hover &&
      !(next instanceof Node && event.currentTarget.contains(next))
    ) {
      setHovered(false);
    }
  };

  const natural = ready
    ? image.source.width / Math.max(1, image.source.height)
    : undefined;
  const boxRatio = ratio ?? natural ?? 4 / 3;
  const showImage = ready && target === 1 && restingAt === 1 && !moving;
  let state = "glyphs";
  if (showImage) {
    state = "photo";
  } else if (moving) {
    state = "revealing";
  }

  return (
    <div
      ref={rootRef}
      data-status={image.status}
      data-state={state}
      tabIndex={hover ? 0 : undefined}
      className={cn(
        "group/reveal relative aspect-(--reveal-ratio) overflow-hidden",
        hover && "outline-none focus-visible:ring-2 focus-visible:ring-ring",
        className
      )}
      style={{ "--reveal-ratio": `${boxRatio}`, ...style } as CSSProperties}
      onPointerEnter={handleEnter}
      onPointerLeave={handleLeave}
      onPointerDown={handleDown}
      onFocus={handleFocus}
      onBlur={handleBlur}
      {...rest}
    >
      <AsciiMedia
        {...look}
        charset={charset}
        colorMode={colorMode}
        source={ready ? image.source : null}
        status={image.status}
        cell={cell}
        animate={moving}
        finish={finish}
        handle={handle}
        className="absolute inset-0"
      />
      <canvas
        ref={photoRef}
        aria-hidden
        className="pointer-events-none absolute inset-0 size-full"
      />
      <AsciiGrid
        draw={drawEdge}
        cell={cell}
        ink={accent}
        animate={moving}
        className="absolute inset-0"
      />
      {/* oxlint-disable-next-line nextjs/no-img-element -- the photo must be the exact file the glyphs were sampled from. */}
      <img
        src={src}
        alt={alt}
        loading="lazy"
        decoding="async"
        crossOrigin={crossOrigin}
        draggable={false}
        className={cn(
          "pointer-events-none absolute inset-0 size-full object-cover",
          showImage ? "opacity-100" : "opacity-0"
        )}
      />
    </div>
  );
};

"use client";

import { useEffect, useRef, useState } from "react";
import type { ComponentProps, CSSProperties, RefObject } from "react";

import {
  AsciiGrid,
  autoLevels as stretchLevels,
  CrtOverlay,
  createToneField,
  hexToRgb,
  luma,
  mapTones,
  PHOSPHORS,
  RAMPS,
  resolveCharset,
  sampleToField,
  SPINNERS,
  useAsciiColors,
  usePrefersReducedMotion,
} from "@/lib/ascii";
import type {
  AsciiColor,
  AsciiGridDrawContext,
  AsciiHandle,
  AsciiLook,
  Charset,
  MapOptions,
  MutableFrame,
  Rgb8,
  SampleCrop,
  ToneField,
} from "@/lib/ascii";
import { cn } from "@/lib/utils";

/* -------------------------------------------------------------------------- */
/* Colour: ink, paper and which way tones run                                  */
/* -------------------------------------------------------------------------- */

/** Ink and paper for a look, and whether dark source pixels draw dense glyphs. */
export interface GlyphPaint {
  readonly ink: AsciiColor;
  readonly paper: AsciiColor | "transparent";
  /**
   * Dense glyphs stand for dark pixels. True on a light page, where ink is
   * dark, so a photo still reads the right way round.
   */
  readonly darkIsDense: boolean;
  /** Paper then ink as bytes, for `colorMode="palette"`. */
  readonly palette: readonly Rgb8[];
}

const toBytes = ([r, g, b]: readonly number[]): Rgb8 => [
  Math.round((r ?? 0) * 255),
  Math.round((g ?? 0) * 255),
  Math.round((b ?? 0) * 255),
];

const rampPaper = (ramp: AsciiLook["ramp"]): string => {
  if (ramp === undefined) {
    return RAMPS.mainframe[0];
  }
  if (typeof ramp === "string") {
    return (RAMPS[ramp as keyof typeof RAMPS] ?? RAMPS.mainframe)[0];
  }
  return ramp[0] ?? RAMPS.mainframe[0];
};

/**
 * Ink and paper for a look, following the theme. Phosphors and duotone
 * ramps are screen looks: they bring their own dark glass, whatever the
 * page theme. Everything else draws in `--ascii-ink` on `--ascii-paper`.
 */
export const useGlyphPaint = (
  ref: RefObject<Element | null>,
  {
    colorMode,
    phosphor,
    ramp,
    invert,
    background = "paper",
  }: Pick<
    AsciiLook,
    "colorMode" | "phosphor" | "ramp" | "invert" | "background"
  >
): GlyphPaint => {
  const theme = useAsciiColors(ref);
  const transparent = background === "transparent";
  const themeInk: Rgb8 = theme ? toBytes(theme[0]) : [230, 230, 230];
  const themePaper: Rgb8 = theme ? toBytes(theme[1]) : [10, 10, 10];
  const pageIsLight = luma(...themePaper) > 0.5;

  if (colorMode === "duotone") {
    const paper = rampPaper(ramp);
    return {
      darkIsDense: invert ?? (transparent ? pageIsLight : false),
      ink: "--ascii-ink",
      palette: [hexToRgb(paper), themeInk],
      paper: transparent ? "transparent" : paper,
    };
  }
  if (phosphor && (colorMode === undefined || colorMode === "mono")) {
    const preset = PHOSPHORS[phosphor];
    return {
      darkIsDense: invert ?? (transparent ? pageIsLight : false),
      ink: preset.ink,
      palette: [hexToRgb(preset.paper), hexToRgb(preset.ink)],
      paper: transparent ? "transparent" : preset.paper,
    };
  }
  return {
    darkIsDense: invert ?? pageIsLight,
    ink: "--ascii-ink",
    palette: [themePaper, themeInk],
    paper: transparent ? "transparent" : "--ascii-paper",
  };
};

/**
 * Braille and quadrants light a dot or leave it dark, so without help a
 * soft gradient collapses to one hard edge. Blue-noise ordered dithering
 * keeps the gradient as a stipple; a ramp charset needs none.
 */
export const packedDither = (
  look: Pick<AsciiLook, "charset" | "chars">
): "none" | "blue-noise" => {
  const { kind } = resolveCharset(look.charset ?? "standard", look.chars);
  return kind === "braille" || kind === "quadrants" ? "blue-noise" : "none";
};

/**
 * The `mapTones` options for a look. Inversion is left to the sampler,
 * which knows which samples are empty (transparent or letterboxed) and
 * must stay empty either way round.
 */
export const lookToMapOptions = (
  look: AsciiLook,
  paint: GlyphPaint,
  fallbackMode: NonNullable<AsciiLook["colorMode"]> = "truecolor"
): MapOptions => ({
  ansi: look.ansi,
  chars: look.chars,
  charset: look.charset ?? "standard",
  colorMode: look.colorMode ?? fallbackMode,
  dither: look.dither ?? packedDither(look),
  edgeThreshold: look.edgeThreshold,
  grade: look.grade,
  invert: false,
  palette: paint.palette,
  ramp: look.ramp,
  threshold: look.threshold,
});

/**
 * Split the look props from everything else, so a component can hand the
 * look to its renderer and the rest to its wrapper element.
 */
export const splitLook = <Props extends AsciiLook>({
  charset,
  chars,
  colorMode,
  phosphor,
  ramp,
  ansi,
  grade,
  invert,
  threshold,
  edgeThreshold,
  dither,
  background,
  fx,
  ...rest
}: Props) =>
  [
    {
      ansi,
      background,
      chars,
      charset,
      colorMode,
      dither,
      edgeThreshold,
      fx,
      grade,
      invert,
      phosphor,
      ramp,
      threshold,
    } satisfies AsciiLook,
    rest,
  ] as const;

/* -------------------------------------------------------------------------- */
/* Sampling: any image, video or canvas into a tone field                      */
/* -------------------------------------------------------------------------- */

/** How media fills its box, as in `object-fit`. */
export type MediaFit = "cover" | "contain" | "fill";

/**
 * What a sample's tone measures. `luma` suits photos and video; `alpha`
 * suits logos and icons on a transparent background, where the shape is
 * the coverage and colour only tints it.
 */
export type MediaTone = "luma" | "alpha";

/** Something drawable and its natural size. `key` changes when the content does. */
export interface MediaInput {
  readonly element: CanvasImageSource;
  readonly width: number;
  readonly height: number;
  readonly key: string;
}

export interface MediaSampleOptions {
  readonly columns: number;
  readonly rows: number;
  readonly charset: Charset;
  /** The grid's width over height in CSS pixels. */
  readonly aspect: number;
  readonly fit: MediaFit;
  /** Where the media sits when it overflows, 0 to 1 per axis. */
  readonly focus: readonly [number, number];
  readonly mirror: boolean;
  readonly tone: MediaTone;
  readonly darkIsDense: boolean;
  /** Stretch the darkest and brightest 1% of tones to the ends of the ramp. */
  readonly levels: boolean;
}

/** The part of the source `cover` keeps, slid towards `focus`. */
const coverCrop = (
  { width, height }: Pick<MediaInput, "width" | "height">,
  aspect: number,
  [focusX, focusY]: readonly [number, number]
): SampleCrop => {
  const sourceAspect = width / Math.max(1, height);
  if (sourceAspect > aspect) {
    const keep = aspect / sourceAspect;
    return { height: 1, width: keep, x: (1 - keep) * focusX, y: 0 };
  }
  const keep = sourceAspect / aspect;
  return { height: keep, width: 1, x: 0, y: (1 - keep) * focusY };
};

/**
 * Sample media into a tone field with the engine's area-averaging
 * sampler, then set which way tones run. Samples outside the media
 * (letterboxing, transparent pixels) stay at tone 0 either way round, so
 * they draw nothing.
 */
export const sampleMedia = (
  source: MediaInput,
  field: ToneField,
  options: MediaSampleOptions
): void => {
  const { aspect, fit } = options;
  sampleToField(source.element, {
    aspect,
    charset: options.charset,
    columns: options.columns,
    crop:
      fit === "cover" ? coverCrop(source, aspect, options.focus) : undefined,
    fit: fit === "cover" ? "fill" : fit,
    into: field,
    mirror: options.mirror,
    rows: options.rows,
  });
  const { tones, colors } = field;
  if (options.tone === "alpha") {
    for (let index = 0; index < tones.length; index += 1) {
      tones[index] = (colors?.[index * 4 + 3] ?? 0) / 255;
    }
    return;
  }
  if (options.levels) {
    stretchLevels(field, 1);
  }
  if (options.darkIsDense) {
    for (let index = 0; index < tones.length; index += 1) {
      const cover = (colors?.[index * 4 + 3] ?? 255) / 255;
      tones[index] = Math.max(0, cover - (tones[index] ?? 0));
    }
  }
};

/* -------------------------------------------------------------------------- */
/* Loading media                                                               */
/* -------------------------------------------------------------------------- */

/** Where an image is in loading. */
export type ImageState =
  | { readonly status: "loading" }
  | { readonly status: "ready"; readonly source: MediaInput }
  | { readonly status: "error" };

/**
 * Load and decode an image for sampling. Cross-origin files need CORS
 * headers, or the canvas can't read their pixels. `null` waits, for
 * images that load lazily.
 */
export const useLoadedImage = (
  src: string | null,
  crossOrigin: ComponentProps<"img">["crossOrigin"] = "anonymous"
): ImageState => {
  const [state, setState] = useState<ImageState>({ status: "loading" });
  useEffect(() => {
    let current = true;
    setState({ status: "loading" });
    if (src === null) {
      return;
    }
    const image = new Image();
    if (crossOrigin !== undefined) {
      image.crossOrigin = crossOrigin;
    }
    image.decoding = "async";
    image.src = src;
    const load = async () => {
      try {
        await image.decode();
      } catch {
        if (current) {
          setState({ status: "error" });
        }
        return;
      }
      if (current) {
        setState({
          source: {
            element: image,
            height: image.naturalHeight || 1,
            key: src,
            width: image.naturalWidth || 1,
          },
          status: "ready",
        });
      }
    };
    load();
    return () => {
      current = false;
    };
  }, [src, crossOrigin]);
  return state;
};

/* -------------------------------------------------------------------------- */
/* AsciiMedia: the shared renderer                                             */
/* -------------------------------------------------------------------------- */

/** What the `shape` and `finish` hooks of `AsciiMedia` get each frame. */
export interface MediaDrawContext extends AsciiGridDrawContext {
  readonly charset: Charset;
  /** The element's size in CSS pixels. */
  readonly box: { readonly width: number; readonly height: number };
}

export type MediaStatus = "loading" | "ready" | "error";

export interface AsciiMediaProps
  extends AsciiLook, Omit<ComponentProps<"div">, "children"> {
  /** What to draw, or `null` while it loads. */
  source: MediaInput | null;
  /** Drawn as a glyph placeholder until `"ready"`. Default `"ready"`. */
  status?: MediaStatus;
  /** Draw a loading sweep and error text in glyphs. Default `true`. */
  placeholder?: boolean;
  /** Shown in glyphs when `status` is `"error"`. Default `"image unavailable"`. */
  message?: string;
  /** Default `"cover"`. */
  fit?: MediaFit;
  /** Media position when it overflows its box, 0 to 1 per axis. Default centred. */
  focus?: readonly [number, number];
  /** Flip horizontally, as a webcam preview does. Default `false`. */
  mirror?: boolean;
  /** Default `"luma"`. */
  tone?: MediaTone;
  /** Stretch the media's tones to fill the ramp. Default `true`. */
  autoLevels?: boolean;
  /** Sample the source again every frame, for video. Default `false`. */
  live?: boolean;
  /** Glyph colour in `mono`, overriding the theme ink and any phosphor. */
  ink?: AsciiColor;
  /** Colour mode when `colorMode` is unset. Default `"truecolor"`. */
  defaultColorMode?: NonNullable<AsciiLook["colorMode"]>;
  /** Adjust tones after sampling, before glyphs are chosen. Runs every frame. */
  shape?: (field: ToneField, context: MediaDrawContext) => void;
  /** Adjust glyphs after mapping. Runs every frame. */
  finish?: (frame: MutableFrame, context: MediaDrawContext) => void;
  /** Cell height in CSS pixels. Default 10. */
  cell?: number;
  /** Keep drawing every frame. Default `false`: one frame per change. */
  animate?: boolean;
  /** Frame rate cap while animating. Default 30. */
  fps?: number;
  /** Filled with a handle for export. */
  handle?: RefObject<AsciiHandle | null>;
}

interface FieldCache {
  key: string;
  base: ToneField;
  work: ToneField;
}

const hash = (x: number, y: number) => {
  const value = Math.sin(x * 127.1 + y * 311.7) * 43_758.5453;
  return value - Math.floor(value);
};

/** A sweeping band of faint glyphs and a status line, while media loads. */
const drawPlaceholder = (
  context: AsciiGridDrawContext,
  status: Exclude<MediaStatus, "ready">,
  message: string
) => {
  const { frame, columns, rows, time } = context;
  const sweep = (time * 0.45) % 1.6;
  for (let row = 0; row < rows; row += 1) {
    for (let column = 0; column < columns; column += 1) {
      const u = column / Math.max(1, columns - 1);
      const v = row / Math.max(1, rows - 1);
      const band =
        status === "loading"
          ? Math.exp(-((u + v * 0.35 - sweep + 0.2) ** 2) * 60)
          : 0;
      const grain = hash(column, row);
      const tone = 0.06 + band * 0.5;
      if (grain < tone) {
        frame.put(column, row, grain < tone * 0.4 ? ":" : "·");
      }
    }
  }
  const spinner = SPINNERS.braille;
  const label =
    status === "loading"
      ? `${spinner[Math.floor(time * 12) % spinner.length] ?? ""} loading`
      : `[ ${message} ]`;
  const text = label.slice(0, columns);
  const x = Math.floor((columns - text.length) / 2);
  const y = Math.floor(rows / 2);
  frame.fillRect(x - 1, y, text.length + 2, 1, " ");
  frame.write(x, y, text);
};

const CENTRE = [0.5, 0.5] as const;

/**
 * The renderer behind every media component: samples an image, video or
 * canvas into glyphs on an `AsciiGrid`. Charset and colour switch without
 * sampling again; size, fit and source changes sample once.
 */
// oxlint-disable-next-line complexity -- each prop default counts as a branch.
export const AsciiMedia = (props: AsciiMediaProps) => {
  const [
    look,
    {
      source,
      status = "ready",
      placeholder = true,
      message = "image unavailable",
      fit = "cover",
      focus = CENTRE,
      mirror = false,
      tone = "luma",
      autoLevels = true,
      live = false,
      ink,
      defaultColorMode = "truecolor",
      shape,
      finish,
      cell = 10,
      animate = false,
      fps = 30,
      handle,
      className,
      ...rest
    },
  ] = splitLook(props);
  const rootRef = useRef<HTMLDivElement>(null);
  const cacheRef = useRef<FieldCache | null>(null);
  const paint = useGlyphPaint(rootRef, look);
  const options = lookToMapOptions(look, paint, defaultColorMode);
  const resolved = resolveCharset(options.charset, options.chars);
  const mode = options.colorMode ?? "mono";

  const draw = (context: AsciiGridDrawContext) => {
    if (status !== "ready" || !source) {
      if (!placeholder) {
        return;
      }
      drawPlaceholder(
        context,
        status === "ready" ? "loading" : status,
        message
      );
      return;
    }
    const root = rootRef.current;
    const { columns, rows, metrics } = context;
    const box = {
      height: root?.clientHeight || rows * metrics.height,
      width: root?.clientWidth || columns * metrics.width,
    };
    const [gx, gy] = resolved.grid;
    const key = [
      source.key,
      columns,
      rows,
      gx,
      gy,
      metrics.width,
      metrics.height,
      box.width,
      box.height,
      fit,
      focus[0],
      focus[1],
      mirror,
      tone,
      autoLevels,
      paint.darkIsDense,
    ].join("|");
    let cache = cacheRef.current;
    if (!cache || cache.key !== key || live) {
      if (
        !cache ||
        cache.base.width !== columns * gx ||
        cache.base.height !== rows * gy
      ) {
        cache = {
          base: createToneField(columns, rows, resolved, { color: true }),
          key,
          work: createToneField(columns, rows, resolved, { color: true }),
        };
      }
      cache.key = key;
      sampleMedia(source, cache.base, {
        aspect: (columns * metrics.width) / (rows * metrics.height),
        charset: resolved,
        columns,
        darkIsDense: paint.darkIsDense,
        fit,
        focus,
        levels: autoLevels,
        mirror,
        rows,
        tone,
      });
      cacheRef.current = cache;
    }
    const mediaContext: MediaDrawContext = {
      ...context,
      box,
      charset: resolved,
    };
    let field = cache.base;
    if (shape) {
      cache.work.tones.set(cache.base.tones);
      if (cache.work.colors && cache.base.colors) {
        cache.work.colors.set(cache.base.colors);
      }
      shape(cache.work, mediaContext);
      field = cache.work;
    }
    mapTones(field, columns, rows, options, context.frame);
    finish?.(context.frame, mediaContext);
  };

  const grid = (
    <AsciiGrid
      ref={rootRef}
      draw={draw}
      cell={cell}
      ink={ink ?? paint.ink}
      paper={paint.paper}
      colored={mode !== "mono"}
      animate={animate || live || (placeholder && status === "loading")}
      fps={fps}
      handle={handle}
      data-status={status}
      className={cn("size-full", look.fx ? "absolute inset-0" : className)}
      {...(look.fx ? {} : rest)}
    />
  );
  if (!look.fx) {
    return grid;
  }
  // The CRT finish is a CSS layer over the canvas, so it needs a wrapper.
  return (
    <div className={cn("relative", className)} {...rest}>
      {grid}
      <CrtOverlay fx={look.fx} />
    </div>
  );
};

/* -------------------------------------------------------------------------- */
/* AsciiImage                                                                  */
/* -------------------------------------------------------------------------- */

/**
 * What the pointer does over the image.
 * - `none`: nothing.
 * - `spotlight`: glyphs thin out away from the pointer and run full
 *   density under it, like a torch over the page.
 * - `photo`: a soft window around the pointer shows the original photo.
 */
export const IMAGE_REVEALS = ["none", "spotlight", "photo"] as const;
export type ImageReveal = (typeof IMAGE_REVEALS)[number];

export interface AsciiImageProps
  extends AsciiLook, Omit<ComponentProps<"div">, "children"> {
  /** Image URL. Cross-origin files need CORS headers. */
  src: string;
  /** What the image shows, read by screen readers. `""` marks it decorative. */
  alt: string;
  /** How the image fills its box. Default `"cover"`. */
  fit?: MediaFit;
  /** Image position when it overflows, 0 to 1 per axis. Default centred. */
  focus?: readonly [number, number];
  /** Stretch the image's tones to use the whole ramp. Default `true`. */
  autoLevels?: boolean;
  /** Pointer effect. Default `"none"`. */
  reveal?: ImageReveal;
  /** Radius of the reveal in CSS pixels. Default 120. */
  revealRadius?: number;
  /** Glyphs resolve in from noise once the image loads. Default `true`. */
  intro?: boolean;
  /** Cell height in CSS pixels. Default 10. */
  cell?: number;
  /** `false` skips the intro and the loading sweep. Default `true`. */
  animate?: boolean;
  /** Passed to the image request. Default `"anonymous"`. */
  crossOrigin?: ComponentProps<"img">["crossOrigin"];
  /** Filled with a handle for export. */
  handle?: RefObject<AsciiHandle | null>;
}

const INTRO_MS = 900;

// What braille and quadrant cells flicker through while they resolve.
const SCRAMBLE = [..."⠁⠂⠄⡀⠈⠐⠠⢀·:"];

/** Hide cells that haven't resolved yet and scramble the ones resolving. */
const resolveIn = (frame: MutableFrame, charset: Charset, progress: number) => {
  const { glyphs, columns } = frame;
  const ramp = charset.kind === "ramp" || charset.kind === "edge";
  const pool = ramp ? charset.glyphs.slice(1) : SCRAMBLE;
  for (let index = 0; index < glyphs.length; index += 1) {
    const column = index % columns;
    const row = (index - column) / columns;
    // Cells resolve roughly top to bottom, in a ragged order.
    const order = hash(column, row) * 0.7 + (row / frame.rows) * 0.3;
    if (order > progress + 0.12) {
      glyphs[index] = " ";
    } else if (order > progress && glyphs[index] !== " ") {
      glyphs[index] =
        pool[Math.floor(hash(row + progress * 31, column) * pool.length)] ??
        "·";
    }
  }
};

const smoothstep = (edge0: number, edge1: number, value: number) => {
  const t = Math.min(1, Math.max(0, (value - edge0) / (edge1 - edge0)));
  return t * t * (3 - 2 * t);
};

/**
 * An image redrawn in glyphs, sampled on the CPU: every glyph is the area
 * average of the pixels under its cell. Charset and colour switch live.
 */
// oxlint-disable-next-line complexity -- each prop default counts as a branch.
export const AsciiImage = (props: AsciiImageProps) => {
  const [
    look,
    {
      src,
      alt,
      fit = "cover",
      focus,
      autoLevels = true,
      reveal = "none",
      revealRadius = 120,
      intro = true,
      cell = 10,
      animate = true,
      crossOrigin = "anonymous",
      handle,
      className,
      style,
      ...rest
    },
  ] = splitLook(props);
  const image = useLoadedImage(src, crossOrigin);
  const reducedMotion = usePrefersReducedMotion();
  const wrapperRef = useRef<HTMLDivElement>(null);
  const pointer = useRef({ eased: 0, inside: false, x: 0, y: 0 });
  const intro0 = useRef({ at: 0, key: "" });
  const [introRunning, setIntroRunning] = useState(false);
  const playIntro = intro && animate && !reducedMotion;

  // Keep the loop running for the length of the intro, then let it rest.
  useEffect(() => {
    if (image.status !== "ready" || !playIntro) {
      setIntroRunning(false);
      return;
    }
    setIntroRunning(true);
    const timer = window.setTimeout(
      () => setIntroRunning(false),
      INTRO_MS + 120
    );
    return () => window.clearTimeout(timer);
  }, [image.status, playIntro]);

  useEffect(() => {
    const wrapper = wrapperRef.current;
    if (!wrapper || reveal === "none") {
      return;
    }
    const move = (event: PointerEvent) => {
      const box = wrapper.getBoundingClientRect();
      pointer.current.x = event.clientX - box.left;
      pointer.current.y = event.clientY - box.top;
      pointer.current.inside = true;
      wrapper.style.setProperty("--reveal-x", `${pointer.current.x}px`);
      wrapper.style.setProperty("--reveal-y", `${pointer.current.y}px`);
      wrapper.style.setProperty("--reveal-r", `${revealRadius}px`);
    };
    const leave = () => {
      pointer.current.inside = false;
      wrapper.style.setProperty("--reveal-r", "0px");
    };
    wrapper.addEventListener("pointermove", move, { passive: true });
    wrapper.addEventListener("pointerdown", move, { passive: true });
    wrapper.addEventListener("pointerleave", leave);
    wrapper.addEventListener("pointercancel", leave);
    return () => {
      wrapper.removeEventListener("pointermove", move);
      wrapper.removeEventListener("pointerdown", move);
      wrapper.removeEventListener("pointerleave", leave);
      wrapper.removeEventListener("pointercancel", leave);
    };
  }, [reveal, revealRadius]);

  const spotlight = (field: ToneField, context: MediaDrawContext) => {
    const state = pointer.current;
    // Ease the light in and out instead of snapping when the pointer enters.
    const target = state.inside ? 1 : 0;
    const rate = context.delta > 0 ? Math.min(1, context.delta * 6) : 1;
    state.eased += (target - state.eased) * rate;
    if (state.eased < 0.01) {
      return;
    }
    const [gx, gy] = context.charset.grid;
    const sampleWidth = context.metrics.width / gx;
    const sampleHeight = context.metrics.height / gy;
    const floor = 1 - 0.75 * state.eased;
    for (let y = 0; y < field.height; y += 1) {
      const dy = (y + 0.5) * sampleHeight - state.y;
      for (let x = 0; x < field.width; x += 1) {
        const dx = (x + 0.5) * sampleWidth - state.x;
        const light = smoothstep(
          revealRadius,
          revealRadius * 0.35,
          Math.hypot(dx, dy)
        );
        const index = y * field.width + x;
        field.tones[index] =
          (field.tones[index] ?? 0) * (floor + (1 - floor) * light);
      }
    }
  };

  const finish = (frame: MutableFrame, context: MediaDrawContext) => {
    if (!playIntro) {
      return;
    }
    // The intro clock starts on the first frame drawn from this image.
    if (intro0.current.key !== src) {
      intro0.current = { at: performance.now(), key: src };
    }
    const progress = (performance.now() - intro0.current.at) / INTRO_MS;
    if (progress < 1) {
      resolveIn(frame, context.charset, progress * 1.12);
    }
  };

  const decorative = alt === "";
  const showPhoto = reveal === "photo" && image.status === "ready";

  return (
    <div
      ref={wrapperRef}
      role={decorative ? undefined : "img"}
      aria-label={decorative ? undefined : alt}
      aria-hidden={decorative ? true : undefined}
      data-status={image.status}
      className={cn("relative overflow-hidden", className)}
      style={
        {
          "--reveal-r": "0px",
          "--reveal-x": "50%",
          "--reveal-y": "50%",
          ...style,
        } as CSSProperties
      }
      {...rest}
    >
      {showPhoto ? (
        // oxlint-disable-next-line nextjs/no-img-element -- the photo under the glyphs must match the sampled file exactly.
        <img
          src={src}
          alt=""
          crossOrigin={crossOrigin}
          className="absolute inset-0 size-full"
          style={{
            objectFit: fit,
            objectPosition: focus
              ? `${focus[0] * 100}% ${focus[1] * 100}%`
              : undefined,
          }}
        />
      ) : null}
      <AsciiMedia
        {...look}
        source={image.status === "ready" ? image.source : null}
        status={image.status}
        fit={fit}
        focus={focus}
        autoLevels={autoLevels}
        cell={cell}
        animate={
          animate &&
          (introRunning || reveal === "spotlight" || image.status === "loading")
        }
        shape={reveal === "spotlight" ? spotlight : undefined}
        finish={finish}
        handle={handle}
        className="absolute inset-0"
        style={
          showPhoto
            ? {
                maskImage:
                  "radial-gradient(circle at var(--reveal-x) var(--reveal-y), transparent calc(var(--reveal-r) * 0.5), black var(--reveal-r))",
              }
            : undefined
        }
      />
    </div>
  );
};

