/**
 * Layered glass folds in violet and teal, drawn in glyphs. Each seed bends
 * the ribbons differently and shifts the two hues within their families.
 * Decorative and full-bleed: size it with `className`, usually
 * `absolute inset-0`.
 */
export const Prism = ({
  seed = "prism",
  charset = "standard",
  ...props
}: PrismProps) => (
  <SeedField
    {...props}
    seed={seed}
    kind="ribbons"
