  /** Cable glyphs indexed by a direction mask: N 1, E 2, S 4, W 8. */
  cable: readonly string[];
  /** The same shapes, lit by a passing pulse. */
  pulse: readonly string[];
}

const GLYPHS = {
  cp437: {
    bar: [" ", "▄", "█"],
    bay: "▒",
    bezel: { bl: "└", br: "┘", tl: "┌", tr: "┐", v: "│" },
    cable: [..." │─└│││├─┘─┴┐┤┬┼"],
    cellEmpty: "░",
    cellFull: "█",
    fan: ["│", "/", "─", "\\"],
    fibre: "◘",
    handle: "═",
    jack: "■",
    ledOff: "·",
    ledOn: "•",
    outlet: "◘",
    pdu: "▐",
    plate: "∙",
    power: "○",
    pulse: [..." ║═╚║║╔╠═╝═╩╗╣╦╬"],
    rail: "│",
    screw: "◘",
