/** A stable 0..1 jitter per key, so typing has a human rhythm that repeats exactly. */
const jitter = (index: number) => {
  const x = Math.sin(index * 12.9898 + 78.233) * 43_758.5453;
  return x - Math.floor(x);
};

/** Seconds from the first key to each key of `text`, at speed 1. */
const keyTimes = (text: string): number[] => {
  const times: number[] = [];
  let at = 0;
  for (const [index, char] of [...text].entries()) {
    at += TIMING.key * (0.55 + jitter(index) * 0.9);
    // A beat after a space or a slash, as fingers find the next word.
    if (char === " " || char === "/") {
      at += TIMING.key * 1.2;
    }
    times.push(at);
  }
  return times;
};

interface Timed {
  readonly step: TerminalStep;
  readonly start: number;
  readonly end: number;
  /** For commands: when each key lands, from the step's start. */
  readonly keys: readonly number[];
}

interface Timeline {
  readonly steps: readonly Timed[];
  readonly total: number;
}

const stepLength = (step: TerminalStep, keys: readonly number[]): number => {
  switch (step.kind) {
    case "command": {
      return TIMING.beforeTyping + (keys.at(-1) ?? 0) + TIMING.enter;
    }
    case "output": {
      return (step.text.split("\n").length + 1) * TIMING.line;
    }
    case "task": {
      return step.duration ?? 1.2;
    }
    case "progress": {
      return step.duration ?? 2;
    }
    case "wait": {
      return step.duration;
    }
    default: {
      const exhaustive: never = step;
      return exhaustive;
    }
  }
};

const compile = (script: readonly TerminalStep[]): Timeline => {
  let at = 0;
  const steps = script.map((step) => {
    const keys = step.kind === "command" ? keyTimes(step.text) : [];
    const start = at;
    at += Math.max(0, stepLength(step, keys));
    return { end: at, keys, start, step };
  });
  return { steps, total: at };
};

/** One line on the screen. */
type Line =
  | { kind: "command"; text: string; typing: boolean }
  | { kind: "output"; text: string; tone: TerminalTone; wrap: boolean }
  | { kind: "task"; text: string; state: "running" | TerminalResult }
  | { kind: "progress"; label: string; value: number; width: number };

interface Screen {
  readonly lines: readonly Line[];
  /** The session is over: an idle prompt waits at the bottom. */
  readonly idle: boolean;
}

/** Progress that stalls and spurts like a real install, still always rising. */
const progressAt = (t: number) =>
  Math.min(1, Math.max(0, t - 0.035 * Math.sin(t * Math.PI * 3)));

const linesOf = (timed: Timed, time: number): Line[] => {
  const { step, start, end } = timed;
  const local = time - start;
  switch (step.kind) {
    case "command": {
      const typed = timed.keys.filter(
        (at) => at <= local - TIMING.beforeTyping
      ).length;
      return [
        {
          kind: "command",
          text: [...step.text].slice(0, typed).join(""),
          typing: time < end,
        },
      ];
    }
    case "output": {
      const shown = Math.floor(local / TIMING.line) + 1;
      return step.text
        .split("\n")
        .slice(0, shown)
        .map((text) => ({
          kind: "output",
          text,
          tone: step.tone ?? "plain",
          wrap: step.wrap ?? true,
        }));
    }
    case "task": {
      const over = time >= end;
      return [
        {
          kind: "task",
          state: over ? (step.result ?? "ok") : "running",
          text: over ? (step.done ?? step.text) : step.text,
        },
      ];
    }
    case "progress": {
      const length = end - start;
      return [
        {
          kind: "progress",
          label: step.label,
          value: length > 0 ? progressAt(local / length) * 100 : 100,
          width: step.width ?? 20,
        },
      ];
    }
    case "wait": {
      return [];
    }
    default: {
      const exhaustive: never = step;
      return exhaustive;
    }
  }
};

/** The screen at `time` seconds into the session. */
const screenAt = (timeline: Timeline, time: number): Screen => ({
  idle: time >= timeline.total,
  lines: timeline.steps
    .filter((timed) => timed.start <= time)
    .flatMap((timed) => linesOf(timed, time)),
});

/** Changes exactly when what the screen draws changes, so the clock can skip renders. */
const screenKey = (screen: Screen): string =>
  `${screen.idle ? 1 : 0}|${screen.lines
    .map((line) => {
      switch (line.kind) {
        case "command": {
          return `${line.text.length}${line.typing ? "t" : ""}`;
        }
        case "task": {
          return line.state;
        }
        case "progress": {
          // An eighth of a cell is the smallest step the bar can draw.
          return String(Math.round((line.value / 100) * line.width * 8));
        }
        case "output": {
          return "o";
        }
        default: {
          const exhaustive: never = line;
          return exhaustive;
        }
      }
    })
    .join(",")}`;

/** The whole session as plain lines, for screen readers. */
const transcript = (
  script: readonly TerminalStep[],
  prompt: string
): string[] =>
  script.flatMap((step) => {
    switch (step.kind) {
      case "command": {
        return [`${prompt} ${step.text}`];
      }
      case "output": {
        // Art reads as noise, so `alt` can say what it is instead.
        return step.alt === undefined
          ? step.text.split("\n").map((line) => line.trim())
          : [step.alt];
      }
      case "task": {
        return [step.done ?? step.text];
      }
      case "progress": {
        return [`${step.label}: done`];
      }
      case "wait": {
        return [];
      }
      default: {
        const exhaustive: never = step;
        return exhaustive;
      }
    }
  });

/** A block cursor; it holds solid while keys land and blinks at rest. */
const Cursor = ({ blink }: { blink: boolean }) => (
  <span
    aria-hidden="true"
    className={cn(
      "inline-block w-[1ch] bg-[var(--term-ink)] align-top",
      blink && "motion-safe:animate-[term-blink_1.06s_steps(1,end)_infinite]"
    )}
    style={{ height: "var(--term-cell)" }}
  />
);

const Mark = ({ tone }: { tone: TerminalTone }) =>
  MARKS[tone] ? (
    <span
      className="inline-block w-[2ch] shrink-0"
      style={{ color: cssColor(TONE_COLORS[tone]) }}
    >
      {MARKS[tone]}
    </span>
  ) : null;

const ScreenLine = ({
  line,
  prompt,
  cell,
}: {
  line: Line;
  prompt: string;
  cell: number;
}) => {
  switch (line.kind) {
    case "command": {
      return (
        <div className="break-words whitespace-pre-wrap">
          <span style={{ color: cssColor("green") }}>{prompt} </span>
          <span className="text-[var(--term-ink)]">{line.text}</span>
          {line.typing ? <Cursor blink={false} /> : null}
        </div>
      );
    }
    case "output": {
      const color =
        line.tone === "warn" || line.tone === "error" || line.tone === "muted"
          ? cssColor(TONE_COLORS[line.tone])
          : "var(--term-ink)";
      return (
        <div
          className={cn(
            "flex",
            line.wrap
              ? "break-words whitespace-pre-wrap"
              : "overflow-hidden whitespace-pre"
          )}
        >
          <Mark tone={line.tone} />
          <span className="min-w-0" style={{ color }}>
            {line.text || " "}
          </span>
        </div>
      );
    }
    case "task": {
      return (
        <div className="flex whitespace-pre-wrap">
          <span className="inline-flex w-[2ch] shrink-0">
            {line.state === "running" ? (
              <Loader
                label={line.text}
                spinner="orbit"
                color="blue"
                cell={cell}
              />
            ) : (
              <Mark tone={line.state} />
            )}
          </span>
          <span
            className="min-w-0 break-words"
            style={{
              color:
                line.state === "error" || line.state === "warn"
                  ? cssColor(TONE_COLORS[line.state])
                  : undefined,
            }}
          >
            {line.text}
          </span>
        </div>
      );
    }
    case "progress": {
      const percent = Math.floor(line.value);
      return (
        <div className="flex flex-wrap items-center gap-x-[1ch]">
          <span className="inline-flex items-center">
            <span>[</span>
            <span className="inline-grid">
              <ProgressBar
                label={line.label}
                hideLabel
                value={line.value}
                columns={line.width}
                // ProgressBar sets its glyphs at cell / 1.17; this lands them
                // at the terminal's cell / 1.2, so the bar sits on its grid.
                cell={(cell * 1.17) / 1.2}
                color="ink"
                animate={false}
              />
            </span>
            <span>]</span>
          </span>
          <span className="w-[4ch] text-right tabular-nums">{`${percent}%`}</span>
          <span style={{ color: cssColor("grey") }}>{line.label}</span>
        </div>
      );
    }
    default: {
      const exhaustive: never = line;
      return exhaustive;
    }
  }
};

type PlayState = "playing" | "paused" | "done";

const PLAY_LABELS = {
  done: { glyph: "↻", text: "Replay" },
  paused: { glyph: "▶", text: "Play" },
  playing: { glyph: "‖", text: "Pause" },
} as const satisfies Record<PlayState, { glyph: string; text: string }>;

/** The terminal's CSS variables: cell height and text ink. */
type TerminalVars = CSSProperties &
  Record<"--term-cell" | "--term-ink", string>;

/**
 * A terminal window framed in box-drawing glyphs that plays a scripted
 * session: commands typed key by key, output streamed line by line,
 * spinners from `Loader`, block bars from `ProgressBar`, coloured ok, warn
 * and error lines, and a blinking cursor at the final prompt. It starts
 * when scrolled into view, has a pause button in its bottom border, and
 * shows the finished session as one still frame under reduced motion.
 */
export const TerminalWindow = ({
  script = DEFAULT_TERMINAL_SCRIPT,
  title = "~/acme — zsh",
  speed = 1,
  loop = true,
  rows = 18,
  prompt = "$",
  frame = "rounded",
  size = "lg",
  cell,
  color = "grey",
  className,
  style,
  ...props
}: TerminalWindowProps) => {
  const screenRef = useRef<HTMLDivElement>(null);
  const reduced = usePrefersReducedMotion();
  const height = cell ?? CELLS[size];
  const timeline = compile(script);
  const [play, setPlay] = useState<PlayState>("playing");
  const [time, setTime] = useState(0);
  const clock = useRef(0);
  const shownKey = useRef("");

  useFrameLoop(
    (_time, delta) => {
      const next = clock.current + delta * Math.max(0, speed);
      if (next >= timeline.total + TIMING.hold && timeline.total > 0) {
        if (loop) {
          clock.current = 0;
          shownKey.current = "";
          setTime(0);
        } else {
          clock.current = timeline.total;
          setTime(timeline.total);
          setPlay("done");
        }
        return;
      }
      clock.current = next;
      // Render only when the screen would change, not on every tick.
      const key = screenKey(screenAt(timeline, next));
      if (key !== shownKey.current) {
        shownKey.current = key;
        setTime(next);
      }
    },
    { enabled: play === "playing", fps: 30, target: screenRef }
  );

  // Under reduced motion the session is one still frame: the end.
  const shown = reduced ? timeline.total : time;
  const screen = screenAt(timeline, shown);

  // New lines push old ones off the top, as in a real terminal.
  const lineCount = screen.lines.length;
  useLayoutEffect(() => {
    const el = screenRef.current;
    if (el && lineCount >= 0) {
      el.scrollTop = el.scrollHeight;
    }
  }, [lineCount, shown]);

  const toggle = () => {
    if (play === "done") {
      clock.current = 0;
      shownKey.current = "";
      setTime(0);
      setPlay("playing");
      return;
    }
    setPlay(play === "playing" ? "paused" : "playing");
  };

  const vars: TerminalVars = {
    "--term-cell": `${height}px`,
    "--term-ink": "var(--ascii-ink)",
    ...style,
  };
  const textStyle: CSSProperties = {
    fontFamily: "var(--ascii-font, monospace)",
    fontSize: `${height / 1.2}px`,
    fontVariantLigatures: "none",
    height: `${rows * height}px`,
    letterSpacing: 0,
    lineHeight: `${height}px`,
  };
  const control = PLAY_LABELS[play];

  const titleBar: ReactNode = (
    <span className="inline-flex items-baseline gap-[1ch]">
      <span aria-hidden="true" className="tracking-[0.1em]">
        <span style={{ color: cssColor("red") }}>●</span>
        <span style={{ color: cssColor("orange") }}>●</span>
        <span style={{ color: cssColor("green") }}>●</span>
      </span>
      <span>{title}</span>
    </span>
  );

  const footer: ReactNode = reduced ? null : (
    <button
      type="button"
      onClick={toggle}
      aria-label={`${control.text} the terminal session`}
      className="pointer-events-auto cursor-pointer px-[1ch] text-muted-foreground outline-hidden select-none hover:text-foreground focus-visible:bg-[var(--ascii-ink)] focus-visible:text-[var(--ascii-paper)]"
    >
      {`${control.glyph} ${control.text.toLowerCase()}`}
    </button>
  );

  return (
    <AsciiBox
      data-slot="terminal-window"
      frame={frame}
      title={titleBar}
      footer={footer}
      color={color}
      cell={height}
      className={cn("w-full", className)}
      style={vars}
      {...props}
    >
      <style>{"@keyframes term-blink{0%{opacity:1}50%{opacity:0}}"}</style>
      <div
        ref={screenRef}
        aria-hidden="true"
        className="overflow-hidden text-[var(--term-ink)]"
        style={textStyle}
      >
        {screen.lines.map((line, index) => (
          // Lines are positional: the nth line of the session.
          // oxlint-disable-next-line react/no-array-index-key
          <ScreenLine key={index} line={line} prompt={prompt} cell={height} />
        ))}
        {screen.idle ? (
          <div>
            <span style={{ color: cssColor("green") }}>{prompt} </span>
            <Cursor blink />
          </div>
        ) : null}
      </div>
      <div className="sr-only">
        {transcript(script, prompt).map((line, index) => (
          // oxlint-disable-next-line react/no-array-index-key
          <p key={index}>{line}</p>
        ))}
      </div>
    </AsciiBox>
  );
};

"use client";

import { useId, useLayoutEffect, useRef } from "react";
import type { ComponentProps, CSSProperties, ReactNode } from "react";

import { BOX, cssColor } from "@/lib/ascii";
import type { AsciiColor, BoxStyle } from "@/lib/ascii";
import { cn } from "@/lib/utils";

/*
 * The frame is real box-drawing text in a 3x3 grid: one cell for each
 * corner and side, with the sides as long runs of glyphs clipped to fit.
 * After mount the box measures its content, rounds its own size up to
 * whole cells and pins it, so every glyph of the frame lands on the cell
 * grid and the corners join the sides exactly. Before that (and on the
 * server) the clipped runs still draw a closed frame, so nothing jumps.
 */

/** Frame glyph sets, from `BOX` in the engine. */
export const ASCII_BOX_FRAMES = [
  "light",
  "heavy",
  "double",
  "rounded",
  "ascii",
] as const satisfies readonly BoxStyle[];

export type AsciiBoxFrame = (typeof ASCII_BOX_FRAMES)[number];

/** Shade glyphs for the drop shadow, from light to dark. */
export const ASCII_BOX_SHADOWS = {
  dark: "▓",
  light: "░",
  medium: "▒",
} as const;

export type AsciiBoxShadow = keyof typeof ASCII_BOX_SHADOWS;

export type AsciiBoxLabelAlign = "start" | "center" | "end";

/** Long enough for any side; the overflow is clipped. */
const RUN = 320;

// Glyph cell width per cell height before the font is measured: 0.6em
// advance over a 1.2em line, as `measureCell` assumes.
const FALLBACK_WIDTH = "calc(var(--box-ch) * 0.5)";

export interface AsciiBoxProps extends Omit<ComponentProps<"div">, "title"> {
  /** Box-drawing set for the frame. Default `"light"`. */
  frame?: AsciiBoxFrame;
  /** A label set into the top border, as in `┌─ Title ───┐`. Also names the box for screen readers. */
  title?: ReactNode;
  /** A label set into the bottom border, such as a status or a count. */
  footer?: ReactNode;
  /** Where the labels sit along their border. Default `"start"`. */
  labelAlign?: AsciiBoxLabelAlign;
  /** A shade-glyph drop shadow one cell right and one row down. Default `false` (none). */
  shadow?: boolean | AsciiBoxShadow;
  /** Frame colour: a palette name, a CSS variable name or any CSS colour. Default `"ink"`. */
  color?: AsciiColor;
  /** Space between the frame and the content in rows; columns are doubled so both read the same. Default 1. */
  padding?: number;
  /** Cell height in CSS pixels. Default `--ascii-cell`, or 12. */
  cell?: number;
  /** Paint `--ascii-paper` inside the frame, so the box hides what sits behind it. Default `false`. */
  filled?: boolean;
  /** Decoration drawn inside the frame and behind the content, such as `AsciiGlow`. It fills the inner cells. */
  backdrop?: ReactNode;
}

/** The box's CSS variables: cell height, cell width and frame colour. */
type BoxVars = CSSProperties &
  Record<"--box-ch" | "--box-cw" | "--box-ink", string>;

interface Glyphs {
  readonly tl: string;
  readonly tr: string;
  readonly bl: string;
  readonly br: string;
  readonly h: string;
  readonly v: string;
}

/**
 * The content width of the nearest box around the box's wrapper: the most
 * the box may take. `display: contents` ancestors have no box, so skip them.
 */
const roomFor = (wrapper: HTMLElement | null): number => {
  let outer = wrapper?.parentElement ?? null;
  while (outer && getComputedStyle(outer).display === "contents") {
    outer = outer.parentElement;
  }
  if (!outer) {
    return Number.POSITIVE_INFINITY;
  }
  const computed = getComputedStyle(outer);
  return (
    outer.clientWidth -
    (Number.parseFloat(computed.paddingLeft) || 0) -
    (Number.parseFloat(computed.paddingRight) || 0)
  );
};

const verticalRun = (glyph: string) => `${glyph}\n`.repeat(RUN / 4);

const Label = ({
  id,
  glyph,
  align,
  children,
}: {
  id?: string;
  glyph: string;
  align: AsciiBoxLabelAlign;
  children: ReactNode;
}) => {
  const run = glyph.repeat(RUN);
  return (
    <div className="flex min-w-0 overflow-hidden">
      <span
        aria-hidden="true"
        className={cn(
          "overflow-hidden",
          align === "start"
            ? "w-[var(--box-cw)] shrink-0"
            : "min-w-[var(--box-cw)] flex-1"
        )}
      >
        {run}
      </span>
      <span
        id={id}
        data-slot="ascii-box-label"
        className="min-w-0 truncate px-[var(--box-cw)] text-foreground"
      >
        {children}
      </span>
      <span
        aria-hidden="true"
        className={cn(
          "overflow-hidden",
          align === "end"
            ? "w-[var(--box-cw)] shrink-0"
            : "min-w-[var(--box-cw)] flex-1"
        )}
      >
        {run}
      </span>
    </div>
  );
};

const Edge = ({
  glyph,
  label,
  labelId,
  align,
}: {
  glyph: string;
  label: ReactNode;
  labelId?: string;
  align: AsciiBoxLabelAlign;
}) =>
  label === undefined || label === null || label === false ? (
    <div aria-hidden="true" className="overflow-hidden">
      {glyph.repeat(RUN)}
    </div>
  ) : (
    <Label id={labelId} glyph={glyph} align={align}>
      {label}
    </Label>
  );

/**
 * Wraps any content in a box-drawing frame that sizes to the content on
 * the glyph cell grid: `light`, `heavy`, `double`, `rounded` or `ascii`
 * borders, labels set into the top and bottom borders, and an optional
 * shade-glyph shadow. The primitive the other asciicn interface pieces
 * are built on.
 */
export const AsciiBox = ({
  frame = "light",
  title,
  footer,
  labelAlign = "start",
  shadow = false,
  color = "ink",
  padding = 1,
  cell,
  filled = false,
  backdrop,
  className,
  style,
  children,
  ...props
}: AsciiBoxProps) => {
  const boxRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const probeRef = useRef<HTMLSpanElement>(null);
  const titleId = useId();
  const glyphs: Glyphs = BOX[frame];
  const shade =
    shadow === false
      ? null
      : ASCII_BOX_SHADOWS[shadow === true ? "light" : shadow];
  const hasTitle = title !== undefined && title !== null && title !== false;
  const pad = Math.max(0, padding);

  // Snap the box to whole cells whenever it or its content changes size.
  useLayoutEffect(() => {
    const box = boxRef.current;
    const content = contentRef.current;
    const probe = probeRef.current;
    if (!(box && content && probe)) {
      return;
    }
    const snap = () => {
      const run = probe.getBoundingClientRect();
      const width = run.width / 10;
      const { height } = run;
      if (!(width > 0 && height > 0)) {
        return;
      }
      box.style.setProperty("--box-cw", `${width}px`);
      // Measure the natural size with nothing pinned, then pin whole cells.
      box.style.width = "";
      box.style.height = "";
      const natural = box.getBoundingClientRect();
      const room = roomFor(box.parentElement) - (shade ? width : 0);
      // Round up, unless that would overflow the parent: then round down.
      let columns = Math.ceil(natural.width / width - 0.01);
      if (columns * width > room + 0.5) {
        columns = Math.max(2, Math.floor(natural.width / width + 0.01));
      }
      const rows = Math.max(2, Math.ceil(natural.height / height - 0.01));
      box.style.width = `${columns * width}px`;
      box.style.height = `${rows * height}px`;
      box.dataset.columns = String(columns);
      box.dataset.rows = String(rows);
    };
    snap();
    const resize = new ResizeObserver(snap);
    resize.observe(content);
    // The wrapper follows its container's width, so it reports when the room changes.
    if (box.parentElement) {
      resize.observe(box.parentElement);
    }
    // Text that grows without changing the content's height still needs a new width.
    const mutations = new MutationObserver(snap);
    mutations.observe(content, {
      characterData: true,
      childList: true,
      subtree: true,
    });
    document.fonts?.addEventListener?.("loadingdone", snap);
    return () => {
      resize.disconnect();
      mutations.disconnect();
      document.fonts?.removeEventListener?.("loadingdone", snap);
    };
  }, [shade, cell, pad, frame]);

  const vars: BoxVars = {
    "--box-ch": cell === undefined ? "var(--ascii-cell, 12px)" : `${cell}px`,
    "--box-cw": FALLBACK_WIDTH,
    "--box-ink": cssColor(color),
  };

  return (
    <div
      data-slot="ascii-box"
      role={hasTitle ? "group" : undefined}
      aria-labelledby={hasTitle ? titleId : undefined}
      className={cn(
        "relative w-fit max-w-full",
        shade && "pr-[var(--box-cw)] pb-[var(--box-ch)]",
        className
      )}
      style={{ ...vars, ...style }}
      {...props}
    >
      <div
        ref={boxRef}
        data-frame={frame}
        className="relative max-w-full"
        style={{
          padding: `calc(var(--box-ch) * ${1 + pad}) calc(var(--box-cw) * ${1 + pad * 2})`,
        }}
      >
        {filled ? (
          <div
            aria-hidden="true"
            className="absolute inset-[calc(var(--box-ch)/2)_calc(var(--box-cw)/2)] bg-[var(--ascii-paper)]"
          />
        ) : null}
        {backdrop ? (
          <div
            aria-hidden="true"
            className="pointer-events-none absolute inset-[var(--box-ch)_var(--box-cw)] overflow-hidden"
          >
            {backdrop}
          </div>
        ) : null}
        <div className="pointer-events-none absolute inset-0 grid grid-cols-[var(--box-cw)_minmax(0,1fr)_var(--box-cw)] grid-rows-[var(--box-ch)_minmax(0,1fr)_var(--box-ch)] font-[family-name:var(--ascii-font,ui-monospace,monospace)] text-[var(--box-ink)] whitespace-pre select-none [font-size:calc(var(--box-ch)/1.17)] [font-variant-ligatures:none] leading-[var(--box-ch)]">
          <span aria-hidden="true">{glyphs.tl}</span>
          <Edge
            glyph={glyphs.h}
            label={title}
            labelId={titleId}
            align={labelAlign}
          />
          <span aria-hidden="true">{glyphs.tr}</span>
          <div aria-hidden="true" className="overflow-hidden">
            {verticalRun(glyphs.v)}
          </div>
          <span
            aria-hidden="true"
            ref={probeRef}
            className="invisible absolute top-0 left-0"
          >
            {glyphs.h.repeat(10)}
          </span>
          <div aria-hidden="true" className="col-start-3 overflow-hidden">
            {verticalRun(glyphs.v)}
          </div>
          <span aria-hidden="true">{glyphs.bl}</span>
          <Edge glyph={glyphs.h} label={footer} align={labelAlign} />
          <span aria-hidden="true">{glyphs.br}</span>
        </div>
        <div ref={contentRef} className="relative min-w-0">
          {children}
        </div>
      </div>
      {shade ? (
        <div
          aria-hidden="true"
          className="pointer-events-none absolute top-[var(--box-ch)] right-0 bottom-0 left-[var(--box-cw)] font-[family-name:var(--ascii-font,ui-monospace,monospace)] text-[var(--box-ink)] whitespace-pre opacity-70 select-none [font-size:calc(var(--box-ch)/1.17)] leading-[var(--box-ch)]"
        >
          <div className="absolute top-0 right-0 bottom-0 w-[var(--box-cw)] overflow-hidden">
            {verticalRun(shade)}
          </div>
          <div className="absolute right-0 bottom-0 left-0 h-[var(--box-ch)] overflow-hidden">
            {shade.repeat(RUN)}
          </div>
        </div>
      ) : null}
    </div>
  );
};

"use client";

import { useRef } from "react";
import type { ComponentProps, CSSProperties } from "react";

import {
  BRAILLE_DOT_BITS,
  brailleChar,
  cssColor,
  EIGHTHS_UP,
  SPINNERS,
  useFrameLoop,
} from "@/lib/ascii";
import type { AsciiColor, SpinnerName } from "@/lib/ascii";
import { cn } from "@/lib/utils";

/**
 * Font size per cell height for DOM glyphs. Cascadia Mono's full block and
 * box lines are 1.17em tall, so at this size blocks and lines in
 * neighbouring rows touch instead of leaving a hairline between them.
 */
const GLYPH_EM = 1.17;

/**
 * A hairline stroke in the text colour. Adjacent block glyphs meet at
 * fractional pixels, where anti-aliasing leaves a faint seam; the stroke
 * covers it without visibly thickening the glyphs.
 */
const SEAL = { WebkitTextStroke: "0.045em currentColor" } as const;

/**
 * `spinner` cycles one glyph through a `SPINNERS` sequence, `dots` walks a
 * bright dot along three, `wave` rolls eighth blocks like an equaliser and
 * `comet` sends a Braille comet across six cells.
 */
export type LoaderVariant = "spinner" | "dots" | "wave" | "comet";

export type LoaderSize = "sm" | "md" | "lg";

export interface LoaderProps extends Omit<
  ComponentProps<"span">,
  "children" | "color"
> {
  /** What is loading, announced politely to screen readers. Default `"Loading"`. */
  label?: string;
  /** Show the label as text next to the glyphs. Default false. */
  showLabel?: boolean;
  /** The animation. Default `"spinner"`. */
  variant?: LoaderVariant;
  /** For `variant="spinner"`: which glyph sequence. Default `"orbit"`. */
  spinner?: SpinnerName;
  /** Glyph cell height: `sm` 12px, `md` 16px, `lg` 24px. Default `"md"`. */
  size?: LoaderSize;
  /** Glyph colour: a palette name or any CSS colour, such as `"currentColor"`. Default `"ink"`. */
  color?: AsciiColor;
  /** Playback speed multiplier. Default 1. */
  speed?: number;
  /** Glyph cell height in CSS pixels. Overrides `size`. */
  cell?: number;
}

const CELLS = { lg: 24, md: 16, sm: 12 } as const satisfies Record<
  LoaderSize,
  number
>;

/** Frames per second of each variant at speed 1, and its width in cells. */
const TIMING = {
  comet: { cells: 6, rate: 28 },
  dots: { cells: 3, rate: 6 },
  spinner: { cells: 1, rate: 11 },
  wave: { cells: 6, rate: 24 },
} as const satisfies Record<LoaderVariant, { cells: number; rate: number }>;

const DOT_GLYPHS = ["·", "•", "●"] as const;

/** Dots: a bright dot steps along, the one it just left still half lit. */
const dotsFrame = (frame: number): string => {
  const head = frame % 4;
  let out = "";
  for (let index = 0; index < 3; index += 1) {
    let level = 0;
    if (index === head) {
      level = 2;
    } else if (index === head - 1) {
      level = 1;
    }
    out += DOT_GLYPHS[level];
  }
  return out;
};

/** Wave: each column rides a sine one step behind its left neighbour. */
const waveFrame = (frame: number, cells: number): string => {
  let out = "";
  for (let index = 0; index < cells; index += 1) {
    const phase = (frame / 24 - index / 7) * Math.PI * 2;
    const level = 1 + Math.round(((Math.sin(phase) + 1) / 2) * 7);
    out += EIGHTHS_UP[level] ?? "▄";
  }
  return out;
};

/** Dots lit per Braille column, from the comet's head back along its tail. */
const COMET_TAIL = [4, 4, 3, 2, 2, 1, 1, 1] as const;
/** Which rows a column with `n` dots lights, kept near the middle. */
const COMET_ROWS = [[], [2], [1, 2], [0, 1, 2], [0, 1, 2, 3]] as const;

/** Comet: a dense head of full Braille columns thinning to single dots. */
const cometFrame = (frame: number, cells: number): string => {
  const columns = cells * 2;
  const span = columns + COMET_TAIL.length;
  const head = frame % span;
  let out = "";
  for (let cell = 0; cell < cells; cell += 1) {
    let mask = 0;
    for (let side = 0; side < 2; side += 1) {
      const behind = head - (cell * 2 + side);
      const dots = behind >= 0 ? (COMET_TAIL[behind] ?? 0) : 0;
      for (const row of COMET_ROWS[dots] ?? []) {
        mask += BRAILLE_DOT_BITS[row]?.[side] ?? 0;
      }
    }
    out += mask === 0 ? " " : brailleChar(mask);
  }
  return out;
};

const glyphsAt = (
  variant: LoaderVariant,
  spinner: SpinnerName,
  frame: number
): string => {
  switch (variant) {
    case "spinner": {
      const frames = SPINNERS[spinner];
      return frames[frame % frames.length] ?? " ";
    }
    case "dots": {
      return dotsFrame(frame);
    }
    case "wave": {
      return waveFrame(frame, TIMING.wave.cells);
    }
    case "comet": {
      return cometFrame(frame, TIMING.comet.cells);
    }
    default: {
      const exhaustive: never = variant;
      return exhaustive;
    }
  }
};

/** The frame drawn when motion is off: one that reads as "busy" on its own. */
const STILL_FRAME = {
  comet: 9,
  dots: 1,
  spinner: 0,
  wave: 6,
} as const satisfies Record<LoaderVariant, number>;

/**
 * A loading indicator drawn in glyphs: a spinner from `SPINNERS`, walking
 * dots, an eighth-block wave or a Braille comet. It is a polite live
 * region, so screen readers hear `label` once; the glyphs are hidden from
 * them. The width is fixed in cells, so nothing around it shifts.
 */
export const Loader = ({
  label = "Loading",
  showLabel = false,
  variant = "spinner",
  spinner = "orbit",
  size = "md",
  color = "ink",
  speed = 1,
  cell,
  className,
  style,
  ...props
}: LoaderProps) => {
  const glyphRef = useRef<HTMLSpanElement>(null);
  const shown = useRef("");
  const height = cell ?? CELLS[size];
  const { cells, rate } = TIMING[variant];
  const still = STILL_FRAME[variant];
  // Frames per second of motion; speed 0 holds the still frame.
  const pace = rate * Math.max(speed, 0.01);

  useFrameLoop(
    (time) => {
      const el = glyphRef.current;
      if (!el) {
        return;
      }
      const text = glyphsAt(variant, spinner, Math.floor(time * pace));
      // Only touch the DOM when the glyphs change, not every tick.
      if (text !== shown.current) {
        shown.current = text;
        el.textContent = text;
      }
    },
    {
      enabled: speed > 0,
      fps: Math.min(60, Math.max(4, pace)),
      // Halfway into the still frame, so rounding can't land on its neighbour.
      stillTime: (still + 0.5) / pace,
      target: glyphRef,
    }
  );

  const glyphStyle: CSSProperties = {
    ...SEAL,
    color: cssColor(color),
    fontFamily: "var(--ascii-font, monospace)",
    fontSize: `${height / GLYPH_EM}px`,
    fontVariantLigatures: "none",
    letterSpacing: 0,
    lineHeight: `${height}px`,
    width: `${cells}ch`,
  };

  return (
    <span
      role="status"
      aria-live="polite"
      className={cn("inline-flex items-center gap-2 align-middle", className)}
      style={style}
      {...props}
    >
      <span
        ref={glyphRef}
        aria-hidden="true"
        className="inline-block shrink-0 overflow-hidden whitespace-pre select-none"
        style={glyphStyle}
      >
        {glyphsAt(variant, spinner, still)}
      </span>
      <span
        className={cn(
          showLabel ? "text-muted-foreground font-mono text-xs" : "sr-only"
        )}
      >
        {label}
      </span>
    </span>
  );
};

"use client";

import { useEffect, useId, useRef, useState } from "react";
import type { ComponentProps, CSSProperties } from "react";

import {
  cssColor,
  EIGHTHS_RIGHT,
  eighthsBar,
  MOTION,
  SERIES_COLORS,
  useFrameLoop,
  usePrefersReducedMotion,
} from "@/lib/ascii";
import type { AsciiColor } from "@/lib/ascii";
import { cn } from "@/lib/utils";

/**
 * Font size per cell height for DOM glyphs. Cascadia Mono's full block and
 * box lines are 1.17em tall, so at this size blocks and lines in
 * neighbouring rows touch instead of leaving a hairline between them.
 */
const GLYPH_EM = 1.17;

/**
 * A hairline stroke in the text colour. Adjacent block glyphs meet at
 * fractional pixels, where anti-aliasing leaves a faint seam; the stroke
 * covers it without visibly thickening the glyphs.
 */
const SEAL = { WebkitTextStroke: "0.045em currentColor" } as const;

export type ProgressBarSize = "sm" | "md" | "lg";

/** The glyph drawn along the empty part of the track. */
export type ProgressTrack = "shade" | "dots" | "line" | "none";

/** One part of a stacked bar, such as one file type in a storage quota. */
export interface ProgressPart {
  /** Name in the legend and for screen readers. */
  label: string;
  /** Size of the part, in the same units as `max`. */
  value: number;
  /** Colour: a palette name or any CSS colour. Default: the next series colour. */
  color?: AsciiColor;
}

interface ProgressShared {
  /** What is in progress. Shown above the bar and used as its accessible name. */
  label: string;
  /** The value that means done (or the capacity, for parts). Default 100. */
  max?: number;
  /** Text for the readout and screen readers. Default: the percentage. */
  valueText?: string;
  /** Keep the label and readout for screen readers only. Default false. */
  hideLabel?: boolean;
  /** Glyph cell height: `sm` 12px, `md` 16px, `lg` 20px. Default `"md"`. */
  size?: ProgressBarSize;
  /** Glyph along the empty track: `░`, `·`, `─` or nothing. Default `"shade"`. */
  track?: ProgressTrack;
  /** Colour of the fill: a palette name or any CSS colour. Default `ink`. */
  color?: AsciiColor;
  /** Split the bar into this many blocks a cell apart, like a step meter. Default: one continuous bar. */
  segments?: number;
  /** Width in cells. Default: as many whole cells as fit the container. */
  columns?: number;
  /** Ease between values and grow in on mount. Default true; off under reduced motion. */
  animate?: boolean;
  /** Glyph cell height in CSS pixels. Overrides `size`. */
  cell?: number;
}

/** One value from 0 to `max`, or indeterminate when `value` is left out. */
export interface SingleProgressProps extends ProgressShared {
  /** Progress from 0 to `max`. Leave it out (or pass null) for an indeterminate bar. */
  value?: number | null;
  parts?: never;
  unit?: never;
}

/** Several parts stacked left to right, with a legend under the bar. */
export interface StackedProgressProps extends ProgressShared {
  /** The parts, left to right. Their sum is the total against `max`. */
  parts: readonly ProgressPart[];
  /** Shown after each part's value in the legend, such as `" GB"`. */
  unit?: string;
  value?: never;
}

export type ProgressBarProps = Omit<ComponentProps<"div">, "children"> &
  (SingleProgressProps | StackedProgressProps);

const CELLS = { lg: 20, md: 16, sm: 12 } as const satisfies Record<
  ProgressBarSize,
  number
>;

const TRACK_GLYPHS = {
  dots: "·",
  line: "─",
  none: " ",
  shade: "░",
} as const satisfies Record<ProgressTrack, string>;

/** Used for the first render, before the container is measured. */
const FALLBACK_COLUMNS = 32;
const PROBE = "0000000000";
/** The indeterminate comet: shaded tail, solid body, then an eighths head. */
const COMET_TAIL = ["░", "▒", "▓"] as const;
const COMET_BODY = 4;
const SWEEP_SECONDS = 1.8;

const clamp01 = (value: number) => (value > 0 ? Math.min(value, 1) : 0);

/** Font size and line height that make one line of text one glyph cell tall. */
const cellText = (cell: number): CSSProperties => ({
  fontFamily: "var(--ascii-font, monospace)",
  fontSize: `${cell / GLYPH_EM}px`,
  fontVariantLigatures: "none",
  letterSpacing: 0,
  lineHeight: `${cell}px`,
  whiteSpace: "pre",
});

/**
 * Whole glyph cells that fit the box, from the width of a probe set in the
 * same font. The probe is observed too, so a web font that loads late or a
 * zoom change measures again.
 */
const useColumns = (fixed: number | undefined) => {
  const boxRef = useRef<HTMLDivElement>(null);
  const probeRef = useRef<HTMLSpanElement>(null);
  const [measured, setMeasured] = useState(FALLBACK_COLUMNS);
  useEffect(() => {
    const box = boxRef.current;
    const probe = probeRef.current;
    if (fixed !== undefined || !box || !probe) {
      return;
    }
    const measure = () => {
      const advance = probe.getBoundingClientRect().width / PROBE.length;
      // A hidden or unlaid-out box reads 0 wide: keep the last good count.
      if (advance > 0 && box.clientWidth > 0) {
        setMeasured(Math.max(1, Math.floor(box.clientWidth / advance + 0.01)));
      }
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(box);
    observer.observe(probe);
    return () => observer.disconnect();
  }, [fixed]);
  return {
    boxRef,
    columns: fixed === undefined ? measured : Math.max(1, Math.round(fixed)),
    probeRef,
  };
};

/**
 * `target` eased from the values shown last, so a new value slides in
 * eighth by eighth instead of jumping. Starts from zeros when `animate`.
 */
const useEased = (
  target: readonly number[],
  animate: boolean
): readonly number[] => {
  const reduced = usePrefersReducedMotion();
  const live = animate && !reduced;
  const [shown, setShown] = useState<readonly number[]>(() =>
    live ? target.map(() => 0) : target
  );
  const shownRef = useRef(shown);
  const key = target.join(",");
  useEffect(() => {
    const goal = key === "" ? [] : key.split(",").map(Number);
    const from = shownRef.current;
    if (!live || from.length !== goal.length) {
      shownRef.current = goal;
      setShown(goal);
      return;
    }
    const start = performance.now();
    let frame = 0;
    const step = (now: number) => {
      const t = Math.min(1, Math.max(0, (now - start) / MOTION.slow));
      // Ease out: fast toward the new value, settling gently on it.
      const eased = 1 - (1 - t) ** 4;
      const next = goal.map((value, index) => {
        const previous = from[index] ?? 0;
        return previous + (value - previous) * eased;
      });
      shownRef.current = next;
      setShown(next);
      if (t < 1) {
        frame = requestAnimationFrame(step);
      }
    };
    frame = requestAnimationFrame(step);
    return () => cancelAnimationFrame(frame);
  }, [key, live]);
  return shown;
};

interface Layout {
  /** For each drawn cell, whether it is part of the bar (false: a gap). */
  readonly slots: readonly boolean[];
  /** Number of bar cells, gaps excluded. */
  readonly fillable: number;
}

/** The cells of the bar, cut into `segments` blocks one blank cell apart. */
const layoutCells = (columns: number, segments: number | undefined): Layout => {
  const count = segments === undefined ? 1 : Math.max(1, Math.round(segments));
  if (count < 2) {
    return {
      fillable: columns,
      slots: Array.from({ length: columns }, () => true),
    };
  }
  const width = Math.max(1, Math.floor((columns - (count - 1)) / count));
  const slots: boolean[] = [];
  for (let block = 0; block < count; block += 1) {
    if (block > 0) {
      slots.push(false);
    }
    for (let cell = 0; cell < width; cell += 1) {
      slots.push(true);
    }
  }
  return { fillable: width * count, slots };
};

/** Spread a run of glyphs, one per bar cell, over the layout's slots. */
const spread = (glyphs: string, layout: Layout): string => {
  const cells = [...glyphs];
  let next = 0;
  return layout.slots
    .map((slot) => {
      if (!slot) {
        return " ";
      }
      const glyph = cells[next] ?? " ";
      next += 1;
      return glyph;
    })
    .join("");
};

interface Run {
  readonly text: string;
  readonly color: AsciiColor;
}

interface StackedPart extends ProgressPart {
  readonly color: AsciiColor;
  readonly share: number;
}

/** Parts with their colours and shares of `max`, clipped to the track. */
const stackParts = (
  parts: readonly ProgressPart[],
  max: number
): StackedPart[] => {
  let room = 1;
  return parts.map((part, index) => {
    const share = Math.min(room, clamp01(Math.max(0, part.value) / max));
    room -= share;
    return {
      ...part,
      color: part.color ?? SERIES_COLORS[index % SERIES_COLORS.length] ?? "ink",
      share,
    };
  });
};

/**
 * Stacked fills as coloured runs. Part boundaries snap to whole cells (a
 * cell holds one glyph, so it can't show two colours side by side); the
 * leading edge of the total keeps its eighth-cell precision.
 */
const stackedRuns = (
  shares: readonly number[],
  colors: readonly AsciiColor[],
  layout: Layout
): Run[] => {
  const total = clamp01(shares.reduce((sum, share) => sum + share, 0));
  const edge = eighthsBar(total, layout.fillable);
  const solidCells = Math.floor(total * layout.fillable);
  const runs: Run[] = [];
  let used = 0;
  let cumulative = 0;
  for (const [index, share] of shares.entries()) {
    cumulative += share;
    const last = index === shares.length - 1 || cumulative >= total - 1e-9;
    const end = last
      ? layout.fillable
      : Math.min(solidCells, Math.round(cumulative * layout.fillable));
    if (end > used) {
      runs.push({ color: colors[index] ?? "ink", text: edge.slice(used, end) });
      used = end;
    }
    if (last) {
      break;
    }
  }
  return runs;
};

/** Cut runs into the slots of a segmented layout, keeping their colours. */
const spreadRuns = (runs: readonly Run[], layout: Layout): Run[] => {
  const flat = runs.flatMap((run) =>
    [...run.text].map((glyph) => ({ color: run.color, glyph }))
  );
  const out: Run[] = [];
  let next = 0;
  for (const slot of layout.slots) {
    const cell = slot ? flat[next] : undefined;
    if (slot) {
      next += 1;
    }
    const glyph = cell?.glyph ?? " ";
    const color = cell?.color ?? "ink";
    const previous = out.at(-1);
    if (previous && (previous.color === color || glyph === " ")) {
      out[out.length - 1] = {
        color: previous.color,
        text: previous.text + glyph,
      };
    } else {
      out.push({ color, text: glyph });
    }
  }
  return out;
};

/** The comet at sweep phase `t` (0 to 1) as one string of `cells` glyphs. */
const cometLine = (t: number, cells: number): string => {
  const length = COMET_TAIL.length + COMET_BODY;
  // In eighths: from the head just entering to the tail just leaving.
  const travel = (cells + length + 1) * 8;
  const eased = t < 0.5 ? 4 * t ** 3 : 1 - (-2 * t + 2) ** 3 / 2;
  const head = Math.round(eased * travel);
  const headCell = Math.floor(head / 8);
  const glyphs: string[] = Array.from({ length: cells }, () => " ");
  const put = (index: number, glyph: string) => {
    if (index >= 0 && index < cells) {
      glyphs[index] = glyph;
    }
  };
  put(headCell, EIGHTHS_RIGHT[head % 8] ?? " ");
  for (let offset = 1; offset <= length; offset += 1) {
    const tail = offset - COMET_BODY - 1;
    put(headCell - offset, tail < 0 ? "█" : (COMET_TAIL.at(-1 - tail) ?? "░"));
  }
  return glyphs.join("");
};

/** The indeterminate fill: a comet that sweeps the track on a loop. */
const Comet = ({ layout, color }: { layout: Layout; color: AsciiColor }) => {
  const ref = useRef<HTMLSpanElement>(null);
  const draw = (time: number) => {
    const el = ref.current;
    if (el) {
      const phase = (time / SWEEP_SECONDS) % 1;
      el.textContent = spread(cometLine(phase, layout.fillable), layout);
    }
  };
  // Still frame under reduced motion: the comet rests mid-track.
  useFrameLoop(draw, { fps: 30, stillTime: SWEEP_SECONDS / 2, target: ref });
  return (
    <span
      ref={ref}
      className="absolute inset-0"
      style={{ ...SEAL, color: cssColor(color) }}
    >
      {spread(cometLine(0.5, layout.fillable), layout)}
    </span>
  );
};

const number = new Intl.NumberFormat("en", { maximumFractionDigits: 1 });

/** Aria value props for a determinate or indeterminate bar. */
const ariaValues = ({
  determinate,
  current,
  max,
  readout,
  valueText,
}: {
  determinate: boolean;
  current: number;
  max: number;
  readout: string;
  valueText: string | undefined;
}) =>
  determinate
    ? {
        "aria-valuemax": max,
        "aria-valuemin": 0,
        "aria-valuenow": current,
        "aria-valuetext": readout,
      }
    : { "aria-valuetext": valueText };

/** What the fill eases toward: one share per part, the ratio, or nothing. */
const targetShares = (
  stacked: readonly StackedPart[] | null,
  determinate: boolean,
  ratio: number
): number[] => {
  if (stacked !== null) {
    return stacked.map((part) => part.share);
  }
  return determinate ? [ratio] : [];
};

/** The fill as coloured runs, from the shares shown right now. */
const fillRuns = ({
  stacked,
  shares,
  color,
  layout,
}: {
  stacked: readonly StackedPart[] | null;
  shares: readonly number[];
  color: AsciiColor;
  layout: Layout;
}): Run[] => {
  if (stacked !== null) {
    const colors = stacked.map((part) => part.color);
    return spreadRuns(stackedRuns(shares, colors, layout), layout);
  }
  if (shares.length === 0) {
    return [];
  }
  const text = spread(eighthsBar(shares[0] ?? 0, layout.fillable), layout);
  return [{ color, text }];
};

/** `█` swatch, label and value for each part, under a stacked bar. */
const Legend = ({
  parts,
  unit,
}: {
  parts: readonly StackedPart[];
  unit: string;
}) => (
  <ul className="flex flex-wrap gap-x-4 gap-y-1">
    {parts.map((part) => (
      <li
        key={part.label}
        className="text-muted-foreground flex items-baseline gap-1.5 text-xs"
      >
        <span
          aria-hidden="true"
          className="font-mono"
          style={{ color: cssColor(part.color) }}
        >
          █
        </span>
        <span className="text-foreground">{part.label}</span>
        <span className="font-mono tabular-nums">
          {`${number.format(part.value)}${unit}`}
        </span>
      </li>
    ))}
  </ul>
);

/**
 * A progress bar drawn in glyphs. The fill is eighth blocks (`▏▎▍▌▋▊▉█`),
 * so the value is exact to an eighth of a cell, over a track of `░`, `·`
 * or `─`. Without a `value`, a comet of shaded glyphs sweeps the track.
 * `parts` stacks several values in their own colours with a legend, and
 * `segments` cuts the bar into blocks for step meters.
 */
export const ProgressBar = ({
  label,
  value,
  parts,
  unit = "",
  max = 100,
  valueText,
  hideLabel = false,
  size = "md",
  track = "shade",
  color = "ink",
  segments,
  columns: fixedColumns,
  animate = true,
  cell,
  className,
  style,
  ...props
}: ProgressBarProps) => {
  const labelId = useId();
  const limit = Math.max(max, 1e-9);
  const stacked = parts === undefined ? null : stackParts(parts, limit);
  const total =
    parts === undefined
      ? (value ?? 0)
      : parts.reduce((sum, part) => sum + Math.max(0, part.value), 0);
  const determinate = stacked !== null || typeof value === "number";
  const ratio = clamp01(total / limit);
  const readout = valueText ?? `${Math.round(ratio * 100)}%`;
  const height = cell ?? CELLS[size];

  const { boxRef, probeRef, columns } = useColumns(fixedColumns);
  const layout = layoutCells(columns, segments);
  const width = layout.slots.length;
  const shares = useEased(targetShares(stacked, determinate, ratio), animate);
  const fill = fillRuns({ color, layout, shares, stacked });
  const trackGlyph = TRACK_GLYPHS[track];
  const trackColor = cssColor(stacked === null ? color : "grey");

  return (
    <div
      role="progressbar"
      aria-labelledby={labelId}
      {...ariaValues({
        current: Math.min(max, Math.max(0, total)),
        determinate,
        max,
        readout,
        valueText,
      })}
      className={cn("flex w-full min-w-0 flex-col gap-2", className)}
      style={style}
      {...props}
    >
      <div
        className={cn(
          "flex items-baseline justify-between gap-4 text-sm",
          hideLabel && "sr-only"
        )}
      >
        <span id={labelId} className="text-foreground min-w-0 truncate">
          {label}
        </span>
        {determinate || valueText ? (
          <span
            aria-hidden="true"
            className="text-muted-foreground shrink-0 font-mono text-xs tabular-nums"
          >
            {readout}
          </span>
        ) : null}
      </div>
      <div ref={boxRef} aria-hidden="true" className="relative w-full min-w-0">
        <span
          ref={probeRef}
          className="invisible absolute top-0 left-0"
          style={cellText(height)}
        >
          {PROBE}
        </span>
        <div
          className="relative overflow-hidden select-none"
          style={{ ...cellText(height), width: `${width}ch` }}
        >
          <span
            className="block"
            style={{
              color: `color-mix(in oklab, ${trackColor} 50%, transparent)`,
            }}
          >
            {spread(trackGlyph.repeat(layout.fillable), layout)}
          </span>
          {determinate ? (
            <span className="absolute inset-0" style={SEAL}>
              {fill.map((run, index) => (
                <span
                  // Runs are positional: the nth run of the bar.
                  // oxlint-disable-next-line react/no-array-index-key
                  key={index}
                  style={{ color: cssColor(run.color) }}
                >
                  {run.text}
                </span>
              ))}
            </span>
          ) : (
            <Comet layout={layout} color={color} />
          )}
        </div>
      </div>
      {stacked === null ? null : <Legend parts={stacked} unit={unit} />}
    </div>
  );
};

