/* ---------- odometer ---------- */

function Reel({ digit, lh, delay }: { digit: number; lh: number; delay: number }) {
  return (
    <span className="inline-block overflow-hidden align-top" style={{ height: lh }}>
      <motion.span
        className="flex flex-col"
        initial={{ y: 0 }}
