        {chars.map((c, i) =>
          c === " " ? (
            <span key={chars.length - i} className="inline-block w-[0.6em]" />
          ) : (
            <Reel key={chars.length - i} digit={Number(c)} lh={lh} />
          ),
        )}
        <span style={{ lineHeight: `${lh}px` }}>%</span>
      </span>
    </span>
  )
}

