          )}

          {state === "done" && (
            <motion.div key="done" {...content} className="absolute inset-0 flex items-center gap-3 pl-2 pr-5">
              <motion.span
                className="grid size-8 place-items-center rounded-full bg-[#3ecf6e] text-black"
