  function handleDragEnd(_: PointerEvent | MouseEvent | TouchEvent, info: PanInfo) {
    const direction = Math.sign(info.offset.x || info.velocity.x);
    // A short swipe springs back with its release velocity and a slight settle instead of drifting home.
    if (Math.abs(info.offset.x) < swipe.distance && Math.abs(info.velocity.x) < swipe.velocity) {
      animate(x, 0, { ...motionTokens.spring.snappy, velocity: info.velocity.x });
      return;
    }
    releaseVelocity.current = info.velocity.x;
    dismiss(direction * ((surface.current?.offsetWidth ?? 320) + 48));
  }

  const variants: Variants = reduce ? {
    hidden: { opacity: 0 },
    shown: { opacity: 1, transition: { duration: motionTokens.duration.instant } },
    exit: fadeOut,
  } : {
    // x resets here because the drag value outlives a thrown toast; the next one must rise from the center.
    hidden: { opacity: 0, x: 0, y: 16, scale: .96 },
    // x returns to center too, in case the toast is raised again while a throw is still leaving.
    shown: { opacity: 1, x: 0, y: 0, scale: 1, transition: { ...motionTokens.spring.morph, opacity: enter } },
    // A thrown toast keeps its release velocity; a closed one sinks back toward the edge it came from.
    // The throw settles loosely: it is invisible once the fade ends, so no long unseen tail keeps it mounted.
    exit: (to: number) => to
      ? { x: to, opacity: 0, transition: { x: { type: "spring", visualDuration: .3, bounce: 0, velocity: releaseVelocity.current, restDelta: 2, restSpeed: 40 }, opacity: { duration: motionTokens.duration.exit } } }
      : { opacity: 0, y: 8, scale: .97, transition: { duration: motionTokens.duration.exit, ease: [...motionTokens.ease.standard] } },
  };
  const swap: MotionProps = { initial: reduce ? { opacity: 0 } : textIn, animate: textShown, exit: reduce ? fadeOut : textOut, transition: reduce ? { duration: motionTokens.duration.instant } : enter };

  return (
    <AnimatePresence initial={enterOnMount} custom={throwX}>
      {visible && <motion.div
        key="toast"
        ref={surface}
        className={styles.toast}
        role="status"
        aria-live="polite"
        aria-atomic="true"
        custom={throwX}
        variants={variants}
        initial="hidden"
        animate="shown"
        exit="exit"
        style={{ x }}
        // Drag writes touch-action into the markup, so the reduced motion switch waits for hydration to keep server and client in step.
        drag={reduce && hydrated ? false : "x"}
        dragMomentum={false}
        onDragEnd={handleDragEnd}
      >
        <span className={styles.icon} aria-hidden="true">
          <svg width={16} height={16} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2.25} strokeLinecap="round" strokeLinejoin="round">
            <motion.path d="M4 12.5l5 5L20 6.5" initial={reduce ? false : { pathLength: 0 }} animate={{ pathLength: 1 }} transition={{ duration: motionTokens.duration.standard, ease: [...motionTokens.ease.enter], delay: .12 }} />
          </svg>
        </span>
        {/* The copy column follows its content height, so a longer message grows the toast instead of snapping it. */}
        <HeightFrame reduce={reduce} morphKey={`${title}\n${description ?? ""}`}>
          <strong className={styles.title}><AnimatePresence mode="popLayout" initial={false}><Swap key={title} className={styles.line} {...swap}>{title}</Swap></AnimatePresence></strong>
          <AnimatePresence mode="popLayout" initial={false}>{description ? <Swap key={description} className={styles.description} {...swap}>{description}</Swap> : null}</AnimatePresence>
        </HeightFrame>
        <button
          className={styles.close}
          type="button"
          aria-label="Dismiss notification"
          onClick={() => dismiss(0)}
        >
          <X width={16} height={16} strokeWidth={2} aria-hidden="true" />
        </button>
      </motion.div>}
    </AnimatePresence>
  );
}

.field { display: grid; justify-items: start; gap: 6px; min-width: 0; }
.label { color: var(--foreground); font-size: var(--text-sm); font-weight: 500; line-height: var(--leading-body); letter-spacing: var(--tracking-body); }
.row { display: flex; flex-wrap: wrap; align-items: center; column-gap: 8px; row-gap: 2px; max-width: 100%; }
/* Cells are wider than their stars; the negative inline margin lines the first star up with the label. */
.stars { --cell: 36px; --glyph: 24px; display: inline-flex; gap: 2px; margin-inline: calc((var(--glyph) - var(--cell)) / 2); touch-action: pan-y; user-select: none; -webkit-user-select: none; }
.sm .stars { --cell: 28px; --glyph: 18px; }
.lg .stars { --cell: 44px; --glyph: 30px; }
.cell { position: relative; display: grid; width: var(--cell); height: var(--cell); flex: none; place-items: center; border-radius: calc(var(--radius-control) - 6px); }
/* The radio covers the cell; with half stars a second radio takes the leading half. */
.hit { position: absolute; inset: 0; margin: 0; border: 0; border-radius: inherit; padding: 0; background: transparent; cursor: pointer; -webkit-tap-highlight-color: transparent; }
.hit:focus-visible { outline: none; }
.half { z-index: 1; inset-inline-end: 50%; border-start-end-radius: 0; border-end-end-radius: 0; }
.hit:disabled { cursor: default; }
/* The lift answers press and softening; the pop inside carries the commit impulse, so the two transforms never fight. */
.lift, .pop { display: grid; width: var(--glyph); height: var(--glyph); pointer-events: none; }
.base, .kept, .fill { display: grid; grid-area: 1 / 1; }
.base svg, .kept svg, .fill svg { width: var(--glyph); height: var(--glyph); }
.base svg { fill: transparent; stroke: var(--border-strong); transition: fill var(--duration-standard) var(--ease-standard), stroke var(--duration-standard) var(--ease-standard); }
/* Once a value shows, empty stars soften from an outline into a quiet solid, so a partly filled star reads as one shape. */
.stars[data-rated] .base svg { fill: var(--border); stroke: var(--border); }
.kept { color: color-mix(in oklab, var(--warning) 30%, transparent); }
.fill { color: var(--warning); }
.kept svg, .fill svg { fill: currentColor; stroke: currentColor; }
.value { display: inline-grid; color: var(--text-secondary); font-size: var(--text-sm); line-height: var(--leading-body); letter-spacing: var(--tracking-body); font-variant-numeric: tabular-nums; white-space: nowrap; transition: color var(--duration-fast) var(--ease-standard); }
.value[data-empty] { color: var(--text-muted); }
.value > * { grid-area: 1 / 1; }
.sizer { visibility: hidden; }
.description { color: var(--text-muted); font-size: var(--text-xs); line-height: var(--leading-body); letter-spacing: var(--tracking-body); font-variant-numeric: tabular-nums; }
.roll { position: relative; display: block; }
.word { display: inline-block; white-space: pre; }
.srOnly { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.field[data-disabled] .stars, .field[data-disabled] .value { opacity: .5; }
@media (prefers-reduced-motion: reduce) { .base svg, .value { transition: none; } }

