  .shell[data-expanded]:not(:has(> .input:focus)):hover { border-color: var(--foreground); }
  .clear:hover { background: var(--surface-muted); color: var(--foreground); }
}
/* A compact press while it is still a button; the morph takes over on release. */
.shell:not([data-expanded]):has(> .trigger:active) { transform: scale(.97); transition-duration: var(--duration-fast), var(--duration-fast), var(--duration-fast), var(--duration-standard), var(--duration-instant); }
.trigger { position: absolute; z-index: 1; inset: 0; margin: 0; padding: 0; border: 0; border-radius: inherit; background: transparent; cursor: pointer; -webkit-tap-highlight-color: transparent; }
