                    <span className={styles.name}>{NAMES[part.unit][compact ? 1 : 0]}</span>
                  </span>
                </span>;
              })}
            </motion.span>}
        </AnimatePresence>
      </div>
    </motion.div>
    <span className={styles.srOnly}>{spoken}</span>
  </div>;
}

