          </AnimatePresence>
        </motion.div>
        <div className={styles.controls}>
          {navigable ? <>
            <button type="button" className={styles.icon} aria-label="Previous announcement" aria-controls={`${uid}-slides`} onClick={() => go(-1)}><ChevronUp size={16} strokeWidth={1.75} aria-hidden="true" /></button>
