        : <span className={styles.unit} aria-hidden="true">{unit}</span>)}
    </motion.div>
    <AnimatePresence>
      {multiplier && !scrubbing?.locked && <motion.span key="tag" className={styles.tag} aria-hidden="true"
        initial={reduced ? { opacity: 0 } : { opacity: 0, y: 4, scale: .96 }} animate={{ opacity: 1, y: 0, scale: 1 }}
        exit={{ opacity: 0, transition: { duration: duration.instant } }} transition={reduced ? { duration: duration.instant } : spring.snappy}>
        {multiplier}
      </motion.span>}
    </AnimatePresence>
    {hydrated && scrubbing?.locked && createPortal(
      <motion.div className={styles.cursor} style={{ x: cursorX, y: cursorY }} aria-hidden="true"
        initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: duration.instant, ease: [...ease.standard] }}>
        <svg width="26" height="16" viewBox="0 0 26 16" className={styles.cursorGlyph}>
          <path d="M1.5 8 L7.5 2.5 V6 H18.5 V2.5 L24.5 8 L18.5 13.5 V10 H7.5 V13.5 Z" />
        </svg>
        <AnimatePresence>
          {multiplier && <motion.span key="multiplier" className={styles.multiplier}
            initial={reduced ? { opacity: 0 } : { opacity: 0, scale: .9, y: -2 }} animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, transition: { duration: duration.instant } }} transition={reduced ? { duration: duration.instant } : spring.snappy}>
            {multiplier}
          </motion.span>}
        </AnimatePresence>
      </motion.div>, document.body)}
  </div>;
});

export default ScrubInput;

/* One bordered surface. The header pins while the body scrolls; every row shares one grid template so columns line up through the tree. */
.root {
  position: relative;
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--radius-panel);
  background: var(--surface);
  color: var(--foreground);
  font-family: var(--font-body);
  font-size: var(--text-sm);
  letter-spacing: var(--tracking-body);
  line-height: var(--leading-body);
}
.root *, .root *::before, .root *::after { box-sizing: border-box; }
.scroller { max-height: var(--tt-max); overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; }
.grid { display: flex; min-width: 0; flex-direction: column; padding-bottom: 6px; }

.header {
  position: sticky;
  z-index: 2;
  top: 0;
  display: grid;
  height: 40px;
  grid-template-columns: var(--tt-columns);
  align-items: center;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
  color: var(--text-muted);
  font-size: var(--text-xs);
}
.headerCell { display: flex; min-width: 0; height: 100%; align-items: center; gap: 2px; padding: 0 12px; }
.headerCell[data-tree] { padding-left: 8px; }
/* The header label lines up with the row names: chevron column, then the same 4px gap the rows use. */
.headerCell[data-tree] .leaf { margin-right: 4px; }
.headerCell[data-align="end"] { justify-content: flex-end; }
.headerLabel { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sort {
  display: inline-flex; min-width: 0; height: 28px; align-items: center; gap: 4px; margin: 0 -8px; padding: 0 8px; border: 0; border-radius: 10px;
  background: transparent; color: inherit; font: inherit; cursor: pointer; -webkit-tap-highlight-color: transparent;
  transition: color var(--duration-fast) var(--ease-standard), background-color var(--duration-fast) var(--ease-standard);
}
.headerCell[data-align="end"] .sort { flex-direction: row-reverse; }
.sort[data-sorted] { color: var(--foreground); }
.sortIcon { display: grid; flex: none; place-items: center; }
.expandAll {
  display: grid; flex: none; width: 28px; height: 28px; place-items: center; margin: 0; padding: 0; border: 0; border-radius: 10px;
  background: transparent; color: var(--text-muted); cursor: pointer; -webkit-tap-highlight-color: transparent;
  transition: color var(--duration-fast) var(--ease-standard), background-color var(--duration-fast) var(--ease-standard), transform var(--duration-fast) var(--ease-standard);
}
.expandAll:active { transform: scale(.94); }
.glyph { display: grid; place-items: center; }

/* Rows grow from zero height, so cells sit at the top with a fixed height and never re-center while a row opens. */
.row {
  position: relative;
  display: grid;
  grid-template-columns: var(--tt-columns);
  align-items: start;
  overflow: hidden;
  scroll-margin-top: 40px;
  box-shadow: inset 0 -1px 0 var(--border-subtle);
  cursor: default;
  transition: background-color var(--duration-fast) var(--ease-standard);
}
.row[data-expandable] { cursor: pointer; }
.row:focus-visible { background: var(--surface-muted); }
.row[data-selected] { background: var(--accent-subtle); }
.row[data-selected]:focus-visible { background: color-mix(in oklab, var(--accent-subtle), var(--foreground) 5%); }

.checkCell { display: flex; height: var(--tt-row); align-items: center; justify-content: center; padding-left: 6px; }
.cell { display: flex; min-width: 0; height: var(--tt-row); align-items: center; padding: 0 12px; color: var(--text-secondary); white-space: nowrap; }
.cell[data-align="end"] { justify-content: flex-end; font-variant-numeric: tabular-nums; }
.treeCell { position: relative; display: flex; min-width: 0; height: var(--tt-row); align-items: center; gap: 4px; margin-left: 10px; padding-right: 12px; }
.treeContent { display: flex; min-width: 0; flex: 1; align-items: center; gap: 8px; overflow: hidden; white-space: nowrap; }

/* Guides run through each ancestor's chevron column; the branch you are in darkens. */
.guide { position: absolute; top: 0; bottom: 0; width: 1px; background: var(--border); transition: background-color var(--duration-standard) var(--ease-standard); }
.guide[data-active] { background: var(--border-strong); }

.chevron {
  display: grid; flex: none; width: var(--tt-chevron); height: var(--tt-chevron); place-items: center; padding: 0; border: 0; border-radius: 8px;
  background: transparent; color: var(--text-muted); cursor: pointer; -webkit-tap-highlight-color: transparent;
  transition: color var(--duration-fast) var(--ease-standard), background-color var(--duration-fast) var(--ease-standard);
}
.row[aria-expanded="true"] > .treeCell .chevron { color: var(--foreground); }
.leaf { flex: none; width: var(--tt-chevron); }

.pending { display: inline-flex; min-width: 0; align-items: center; gap: 8px; padding-left: calc(var(--tt-chevron) + 4px); color: var(--text-muted); white-space: nowrap; }
.pending[data-tone="danger"] { color: var(--danger); }
.retry {
  display: inline-flex; height: 28px; align-items: center; gap: 6px; padding: 0 10px; border: 0; border-radius: var(--radius-pill);
  background: var(--surface-muted); color: var(--foreground); font: inherit; font-size: var(--text-xs); font-weight: 500; cursor: pointer;
  transition: transform var(--duration-fast) var(--ease-standard), background-color var(--duration-fast) var(--ease-standard);
}
.retry:active { transform: scale(.97); }
.skeleton { width: min(72px, 80%); height: 10px; border-radius: var(--radius-pill); background: var(--surface-muted); animation: breathe 1.2s var(--ease-in-out) 4 alternate; }
.row[data-pending] .cell[data-align="end"] { justify-content: flex-end; }
.spin { animation: spin .8s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes breathe { to { opacity: .45; } }

.empty { display: grid; place-items: center; padding: 32px 16px; color: var(--text-muted); }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }

@media (hover: hover) and (pointer: fine) {
  .row:not([data-pending]):hover { background: var(--surface-muted); }
  .row[data-selected]:hover { background: color-mix(in oklab, var(--accent-subtle), var(--foreground) 4%); }
  .sort:hover, .expandAll:hover { background: var(--surface-muted); color: var(--foreground); }
  .chevron:hover { background: color-mix(in oklab, var(--surface-muted), var(--foreground) 6%); color: var(--foreground); }
  .retry:hover { background: color-mix(in oklab, var(--surface-muted), var(--foreground) 6%); }
}
@media (prefers-contrast: more) { .guide { background: var(--border-strong); } .row { box-shadow: inset 0 -1px 0 var(--border); } }
@media (prefers-reduced-motion: reduce) {
  .row, .guide, .chevron, .sort, .expandAll, .retry { transition: none; }
  .expandAll:active, .retry:active { transform: none; }
  .spin { animation-duration: 1.6s; }
  .skeleton { animation: none; }
}

