.form { display: grid; gap: var(--space-4); }
.wide { width: 100%; }
.passwordGroup { display: grid; min-width: 0; }
/* One stable row under the password: the words change in place and the meter fills beside them. */
.feedback { display: flex; min-height: 18px; align-items: center; justify-content: space-between; gap: var(--space-3); margin-top: var(--space-2); font-size: var(--text-xs); line-height: var(--leading-body); }
