/* The grid. Every stat has the same rows, so numbers, labels, and visuals line up across the band. */
.stats { position: relative; display: grid; grid-template-columns: repeat(var(--count), minmax(0, 1fr)); column-gap: var(--space-10); row-gap: var(--space-16); margin: 0; }
.stat {
