  --ink: var(--text-secondary);
  --soft: var(--border-strong);
  position: relative; display: flex; min-width: 0; flex-direction: column; cursor: default; -webkit-tap-highlight-color: transparent;
}
.stat:focus { outline: none; }
.figure { order: -1; margin: 0 0 var(--space-5); }
.label { color: var(--foreground); font-size: var(--text-sm); font-weight: 500; line-height: var(--leading-body); text-wrap: pretty; }
.caption { display: grid; margin: 2px 0 0; color: var(--text-muted); font-size: var(--text-sm); line-height: var(--leading-body); }
.detail, .context { grid-area: 1 / 1; min-width: 0; text-wrap: pretty; transition: opacity var(--duration-standard) var(--ease-standard), transform var(--duration-standard) var(--ease-standard); }
.stat[data-context] .context { opacity: 0; transform: translateY(4px); }
.context { color: var(--text-secondary); }

/* The number: display type, tabular digits, the unit smaller and quieter on the same baseline. */
.number { display: inline-flex; align-items: baseline; font-family: var(--font-display); font-size: clamp(2.5rem, 1.4rem + 3cqi, var(--text-4xl)); font-weight: 500; letter-spacing: var(--tracking-display); line-height: 1; font-variant-numeric: tabular-nums; white-space: nowrap; }
.prefix, .suffix { color: var(--text-muted); font-size: .5em; letter-spacing: -.01em; }
.prefix { margin-right: .08em; }
.suffix { margin-left: .1em; }
.digits { display: inline-grid; justify-items: start; }
.sizer, .live { grid-area: 1 / 1; }
.sizer { visibility: hidden; }

/* Visuals sit on the bottom row, all the same height, so they line up whatever the copy above them does. */
.visual { position: relative; display: flex; flex: none; flex-direction: column; justify-content: flex-end; height: calc(56px + var(--space-8)); margin: auto 0 0; padding-top: var(--space-8); }
.visual > * { position: relative; height: 100%; }
.visual > .bars[data-dense] { height: 56%; }
.draw { display: block; width: 100%; height: 100%; overflow: visible; }

.trend { margin-right: 3px; }
.area { fill: var(--soft); opacity: .22; transition: fill var(--duration-standard) var(--ease-standard); }
.line { fill: none; stroke: var(--ink); stroke-width: 1.5; stroke-linejoin: round; stroke-linecap: round; transition: stroke var(--duration-standard) var(--ease-standard); }
.endDot { position: absolute; width: 7px; height: 7px; margin: -3.5px 0 0 -3.5px; border-radius: 50%; background: var(--ink); box-shadow: 0 0 0 2px var(--background); transition: background-color var(--duration-standard) var(--ease-standard), opacity 320ms var(--ease-standard), transform var(--duration-spring) var(--ease-spring); }

.bars { display: flex; align-items: flex-end; gap: 3px; }
