.lit { fill: var(--ink); transition: fill var(--duration-standard) var(--ease-standard); }

/* Hover or focus: the context line fades in and the visual takes the accent. The other stats stay neutral. */
.stat:focus-visible { --ink: var(--accent); --soft: color-mix(in oklab, var(--accent) 42%, var(--background)); }
.stat[data-context]:focus-visible .detail { opacity: 0; transform: translateY(-4px); }
