/* Entry: stats rise in sequence while the numbers count, then each visual draws in once its number has landed. */
.stat { opacity: 0; transform: translateY(8px); transition: opacity 480ms var(--ease-enter), transform 640ms var(--ease-enter); transition-delay: calc(var(--i) * 90ms); }
