.band[data-layout="divided"][data-in-view] .stats::after { transform: scaleX(1); }
.band[data-layout="divided"] .stat { padding: var(--space-10) var(--space-8) var(--space-8); }
.band[data-layout="divided"] .stat:first-child { padding-left: 0; }
.band[data-layout="divided"] .stat:last-child { padding-right: 0; }
.band[data-layout="divided"] .stat:not(:first-child)::before { content: ""; position: absolute; top: 0; bottom: 0; left: 0; width: 1px; background: var(--border); transform: scaleY(0); transform-origin: top; transition: transform 700ms var(--ease-enter); transition-delay: calc(var(--i) * 90ms + 240ms); }
.band[data-layout="divided"][data-in-view] .stat::before { transform: scaleY(1); }

/* Tablet: two by two. A band of three stacks instead of leaving an orphan. */
@container stats (max-width: 800px) {
  .inner { padding: var(--space-20) var(--space-8); }
  .header { grid-template-columns: minmax(0, 1fr); margin-bottom: var(--space-12); }
  .description { justify-self: start; }
  .stats { grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: var(--space-8); row-gap: var(--space-12); }
  .band[data-layout="divided"] .stat { padding: var(--space-8) var(--space-8) var(--space-8); }
  .band[data-layout="divided"] .stat:nth-child(2n + 1) { padding-left: 0; }
  .band[data-layout="divided"] .stat:nth-child(2n) { padding-right: 0; }
  .band[data-layout="divided"] .stat:nth-child(2n + 1)::before { display: none; }
