/* Phone: one stat per row, the visual beside the number so nothing is cramped. */
@container stats (max-width: 520px) {
  .inner { padding: var(--space-16) var(--space-4); }
  .header { margin-bottom: var(--space-10); }
  .stats { grid-template-columns: minmax(0, 1fr); row-gap: var(--space-10); }
  .stat { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 40%); grid-template-areas: "figure visual" "label label" "caption caption"; column-gap: var(--space-6); }
  .figure { grid-area: figure; align-self: end; margin-bottom: var(--space-3); }
