  .band[data-layout="divided"] .stats::before, .band[data-layout="divided"] .stats::after, .band[data-layout="divided"] .stat::before { transition-duration: 0ms; transition-delay: 0ms; }
  .band .stat { opacity: 1; transform: none; }
